INSERT INTO traducoes (id, nome, abreviacao, descricao, data_criacao, deletado) VALUES
(1, 'Almeida Atualizada', 'AA', 'Tradução Almeida Atualizada', CURRENT_TIMESTAMP, false)
INSERT INTO traducoes (id, nome, abreviacao, descricao, data_criacao, deletado) VALUES
(2, 'Almeida Corrigida Fiel', 'ACF', 'Tradução Almeida Corrigida Fiel', CURRENT_TIMESTAMP, false)
INSERT INTO traducoes (id, nome, abreviacao, descricao, data_criacao, deletado) VALUES
(3, 'Nova Versão Internacional', 'NVI', 'Tradução Nova Versão Internacional', CURRENT_TIMESTAMP, false)
INSERT INTO versiculos (livro, capitulo, numero, texto, traducao_id, data_criacao, deletado) VALUES
(46, 1, 1, 'Paulo, chamado para ser apóstolo de Jesus Cristo pela vontade de Deus, e o irmão Sóstenes,', 1, CURRENT_TIMESTAMP, false),
(46, 1, 2, 'à igreja de Deus que está em Corinto, aos santificados em Cristo Jesus, chamados para serem santos, com todos os que em todo lugar invocam o nome de nosso Senhor Jesus Cristo, Senhor deles e nosso:', 1, CURRENT_TIMESTAMP, false),
(46, 1, 3, 'Graça seja convosco, e paz, da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 4, 'Sempre dou graças a Deus por vós, pela graça de Deus que vos foi dada em Cristo Jesus;', 1, CURRENT_TIMESTAMP, false),
(46, 1, 5, 'porque em tudo fostes enriquecidos nele, em toda palavra e em todo o conhecimento,', 1, CURRENT_TIMESTAMP, false),
(46, 1, 6, 'assim como o testemunho de Cristo foi confirmado entre vós;', 1, CURRENT_TIMESTAMP, false),
(46, 1, 7, 'de maneira que nenhum dom vos falta, enquanto aguardais a manifestação de nosso Senhor Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(46, 1, 8, 'o qual também vos confirmará até o fim, para serdes irrepreensíveis no dia de nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 9, 'Fiel é Deus, pelo qual fostes chamados para a comunhão de seu Filho Jesus Cristo nosso Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 10, 'Rogo-vos, irmãos, em nome de nosso Senhor Jesus Cristo, que sejais concordes no falar, e que não haja dissensões entre vós; antes sejais unidos no mesmo pensamento e no mesmo parecer.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 11, 'Pois a respeito de vós, irmãos meus, fui informado pelos da família de Cloé que há contendas entre vós.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 12, 'Quero dizer com isto, que cada um de vós diz: Eu sou de Paulo; ou, Eu de Apolo; ou Eu sou de Cefas; ou, Eu de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 13, 'será que Cristo está dividido? foi Paulo crucificado por amor de vós? ou fostes vós batizados em nome de Paulo?', 1, CURRENT_TIMESTAMP, false),
(46, 1, 14, 'Dou graças a Deus que a nenhum de vós batizei, senão a Crispo e a Gaio;', 1, CURRENT_TIMESTAMP, false),
(46, 1, 15, 'para que ninguém diga que fostes batizados em meu nome.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 16, 'É verdade, batizei também a família de Estéfanas, além destes, não sei se batizei algum outro.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 17, 'Porque Cristo não me enviou para batizar, mas para pregar o evangelho; não em sabedoria de palavras, para não se tornar vã a cruz de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 18, 'Porque a palavra da cruz é deveras loucura para os que perecem; mas para nós, que somos salvos, é o poder de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 19, 'porque está escrito: Destruirei a sabedoria dos sábios, e aniquilarei a sabedoria o entendimento dos entendidos.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 20, 'Onde está o sábio? Onde o escriba? Onde o questionador deste século? Porventura não tornou Deus louca a sabedoria deste mundo?', 1, CURRENT_TIMESTAMP, false),
(46, 1, 21, 'Visto como na sabedoria de Deus o mundo pela sua sabedoria não conheceu a Deus, aprouve a Deus salvar pela loucura da pregação os que crêem.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 22, 'Pois, enquanto os judeus pedem sinal, e os gregos buscam sabedoria,', 1, CURRENT_TIMESTAMP, false),
(46, 1, 23, 'nós pregamos a Cristo crucificado, que é escândalo para os judeus, e loucura para os gregos,', 1, CURRENT_TIMESTAMP, false),
(46, 1, 24, 'mas para os que são chamados, tanto judeus como gregos, Cristo, poder de Deus, e sabedoria de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 25, 'Porque a loucura de Deus é mais sábia que os homens; e a fraqueza de Deus é mais forte que os homens.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 26, 'Ora, vede, irmãos, a vossa vocação, que não são muitos os sábios segundo a carne, nem muitos os poderosos. nem muitos os nobres que são chamados.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 27, 'Pelo contrário, Deus escolheu as coisas loucas do mundo para confundir os sábios; e Deus escolheu as coisas fracas do mundo para confundir as fortes;', 1, CURRENT_TIMESTAMP, false),
(46, 1, 28, 'e Deus escolheu as coisas ignóbeis do mundo, e as desprezadas, e as que não são, para reduzir a nada as que são;', 1, CURRENT_TIMESTAMP, false),
(46, 1, 29, 'para que nenhum mortal se glorie na presença de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 1, 30, 'Mas vós sois dele, em Cristo Jesus, o qual para nós foi feito por Deus sabedoria, e justiça, e santificação, e redenção;', 1, CURRENT_TIMESTAMP, false),
(46, 1, 31, 'para que, como está escrito: Aquele que se gloria, glorie-se no Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 1, 'E eu, irmãos, quando fui ter convosco, anunciando-vos o testemunho de Deus, não fui com sublimidade de palavras ou de sabedoria.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 2, 'Porque nada me propus saber entre vós, senão a Jesus Cristo, e este crucificado.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 3, 'E eu estive convosco em fraqueza, e em temor, e em grande tremor.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 4, 'A minha linguagem e a minha pregação não consistiram em palavras persuasivas de sabedoria, mas em demonstração do Espírito de poder;', 1, CURRENT_TIMESTAMP, false),
(46, 2, 5, 'para que a vossa fé não se apoiasse na sabedoria dos homens, mas no poder de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 6, 'Na verdade, entre os perfeitos falamos sabedoria, não porém a sabedoria deste mundo, nem dos príncipes deste mundo, que estão sendo reduzidos a nada;', 1, CURRENT_TIMESTAMP, false),
(46, 2, 7, 'mas falamos a sabedoria de Deus em mistério, que esteve oculta, a qual Deus preordenou antes dos séculos para nossa glória;', 1, CURRENT_TIMESTAMP, false),
(46, 2, 8, 'a qual nenhum dos príncipes deste mundo compreendeu; porque se a tivessem compreendido, não teriam crucificado o Senhor da glória.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 9, 'Mas, como está escrito: As coisas que olhos não viram, nem ouvidos ouviram, nem penetraram o coração do homem, são as que Deus preparou para os que o amam.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 10, 'Porque Deus no-las revelou pelo seu Espírito; pois o Espírito esquadrinha todas as coisas, mesmos as profundezas de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 11, 'Pois, qual dos homens entende as coisas do homem, senão o espírito do homem que nele está? assim também as coisas de Deus, ninguém as compreendeu, senão o Espírito de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 12, 'Ora, nós não temos recebido o espírito do mundo, mas sim o Espírito que provém de Deus, a fim de compreendermos as coisas que nos foram dadas gratuitamente por Deus;', 1, CURRENT_TIMESTAMP, false),
(46, 2, 13, 'as quais também falamos, não com palavras ensinadas pela sabedoria humana, mas com palavras ensinadas pelo Espírito Santo, comparando coisas espirituais com espirituais.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 14, 'Ora, o homem natural não aceita as coisas do Espírito de Deus, porque para ele são loucura; e não pode entendê-las, porque elas se discernem espiritualmente.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 15, 'Mas o que é espiritual discerne bem tudo, enquanto ele por ninguém é discernido.', 1, CURRENT_TIMESTAMP, false),
(46, 2, 16, 'Pois, quem jamais conheceu a mente do Senhor, para que possa instruí-lo? Mas nós temos a mente de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 1, 'E eu, irmãos não vos pude falar como a espirituais, mas como a carnais, como a criancinhas em Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 2, 'Leite vos dei por alimento, e não comida sólida, porque não a podíeis suportar; nem ainda agora podeis;', 1, CURRENT_TIMESTAMP, false),
(46, 3, 3, 'porquanto ainda sois carnais; pois, havendo entre vós inveja e contendas, não sois porventura carnais, e não estais andando segundo os homens?', 1, CURRENT_TIMESTAMP, false),
(46, 3, 4, 'Porque, dizendo um: Eu sou de Paulo; e outro: Eu de Apolo; não sois apenas homens?', 1, CURRENT_TIMESTAMP, false),
(46, 3, 5, 'Pois, que é Apolo, e que é Paulo, senão ministros pelos quais crestes, e isso conforme o que o Senhor concedeu a cada um?', 1, CURRENT_TIMESTAMP, false),
(46, 3, 6, 'Eu plantei; Apolo regou; mas Deus deu o crescimento.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 7, 'De modo que, nem o que planta é alguma coisa, nem o que rega, mas Deus, que dá o crescimento.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 8, 'Ora, uma só coisa é o que planta e o que rega; e cada um receberá o seu galardão segundo o seu trabalho.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 9, 'Porque nós somos cooperadores de Deus; vós sois lavoura de Deus e edifício de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 10, 'Segundo a graça de Deus que me foi dada, lancei eu como sábio construtor, o fundamento, e outro edifica sobre ele; mas veja cada um como edifica sobre ele.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 11, 'Porque ninguém pode lançar outro fundamento, além do que já está posto, o qual é Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 12, 'E, se alguém sobre este fundamento levanta um edifício de ouro, prata, pedras preciosas, madeira, feno, palha,', 1, CURRENT_TIMESTAMP, false),
(46, 3, 13, 'a obra de cada um se manifestará; pois aquele dia a demonstrará, porque será revelada no fogo, e o fogo provará qual seja a obra de cada um.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 14, 'Se permanecer a obra que alguém sobre ele edificou, esse receberá galardão.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 15, 'Se a obra de alguém se queimar, sofrerá ele prejuízo; mas o tal será salvo todavia como que pelo fogo.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 16, 'Não sabeis vós que sois santuário de Deus, e que o Espírito de Deus habita em vós?', 1, CURRENT_TIMESTAMP, false),
(46, 3, 17, 'Se alguém destruir o santuário de Deus, Deus o destruirá; porque sagrado é o santuário de Deus, que sois vós.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 18, 'Ninguém se engane a si mesmo; se alguém dentre vós se tem por sábio neste mundo, faça-se louco para se tornar sábio.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 19, 'Porque a sabedoria deste mundo é loucura diante de Deus; pois está escrito: Ele apanha os sábios na sua própria astúcia;', 1, CURRENT_TIMESTAMP, false),
(46, 3, 20, 'e outra vez: O Senhor conhece as cogitações dos sábios, que são vãs.', 1, CURRENT_TIMESTAMP, false),
(46, 3, 21, 'Portanto ninguém se glorie nos homens; porque tudo é vosso;', 1, CURRENT_TIMESTAMP, false),
(46, 3, 22, 'seja Paulo, ou Apolo, ou Cefas; seja o mundo, ou a vida, ou a morte; sejam as coisas presentes, ou as vindouras, tudo é vosso,', 1, CURRENT_TIMESTAMP, false),
(46, 3, 23, 'e vós de Cristo, e Cristo de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 1, 'Que os homens nos considerem, pois, como ministros de Cristo, e despenseiros dos mistérios de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 2, 'Ora, além disso, o que se requer nos despenseiros é que cada um seja encontrado fiel.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 3, 'Todavia, a mim mui pouco se me dá de ser julgado por vós, ou por qualquer tribunal humano; nem eu tampouco a mim mesmo me julgo.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 4, 'Porque, embora em nada me sinta culpado, nem por isso sou justificado; pois quem me julga é o Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 5, 'Portanto nada julgueis antes do tempo, até que venha o Senhor, o qual não só trará à luz as coisas ocultas das trevas, mas também manifestará os desígnios dos corações; e então cada um receberá de Deus o seu louvor.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 6, 'Ora, irmãos, estas coisas eu as apliquei figuradamente a mim e a Apolo, por amor de vós; para que em nós aprendais a não ir além do que está escrito, de modo que nenhum de vós se ensoberbeça a favor de um contra outro.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 7, 'Pois, quem te diferença? E que tens tu que não tenhas recebido? E, se o recebeste, por que te glorias, como se não o houveras recebido?', 1, CURRENT_TIMESTAMP, false),
(46, 4, 8, 'Já estais fartos! já estais ricos! sem nós já chegastes a reinar! e oxalá reinásseis de fato, para que também nós reinássemos convosco!', 1, CURRENT_TIMESTAMP, false),
(46, 4, 9, 'Porque tenho para mim, que Deus a nós, apóstolos, nos pôs por últimos, como condenados à morte; pois somos feitos espetáculo ao mundo, tanto a anjos como a homens.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 10, 'Nós somos loucos por amor de Cristo, e vós sábios em Cristo; nós fracos, e vós fortes; vós ilustres, e nós desprezíveis.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 11, 'Até a presente hora padecemos fome, e sede; estamos nus, e recebemos bofetadas, e não temos pousada certa,', 1, CURRENT_TIMESTAMP, false),
(46, 4, 12, 'e nos afadigamos, trabalhando com nossas próprias mãos; somos injuriados, e bendizemos; somos perseguidos, e o suportamos;', 1, CURRENT_TIMESTAMP, false),
(46, 4, 13, 'somos difamados, e exortamos; até o presente somos considerados como o refugo do mundo, e como a escória de tudo.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 14, 'Não escrevo estas coisas para vos envergonhar, mas para vos admoestar, como a filhos meus amados.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 15, 'Porque ainda que tenhais dez mil aios em Cristo, não tendes contudo muitos pais; pois eu pelo evangelho vos gerei em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 16, 'Rogo-vos, portanto, que sejais meus imitadores.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 17, 'Por isso mesmo vos enviei Timóteo, que é meu filho amado, e fiel no Senhor; o qual vos lembrará os meus caminhos em Cristo, como por toda parte eu ensino em cada igreja.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 18, 'Mas alguns andam inchados, como se eu não houvesse de ir ter convosco.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 19, 'Em breve, porém, irei ter convosco, se o Senhor quiser, e então conhecerei, não as palavras dos que andam inchados, mas o poder.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 20, 'Porque o reino de Deus não consiste em palavras, mas em poder.', 1, CURRENT_TIMESTAMP, false),
(46, 4, 21, 'Que quereis? Irei a vós com vara, ou com amor e espírito de mansidão?', 1, CURRENT_TIMESTAMP, false),
(46, 5, 1, 'Geralmente se ouve que há entre vós imoralidade, imoralidade que nem mesmo entre os gentios se vê, a ponto de haver quem vive com a mulher de seu pai.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 2, 'E vós estais inchados? e nem ao menos pranteastes para que fosse tirado do vosso meio quem praticou esse mal?', 1, CURRENT_TIMESTAMP, false),
(46, 5, 3, 'Eu, na verdade, ainda que ausente no corpo, mas presente no espírito, já julguei, como se estivesse presente, aquele que cometeu este ultraje.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 4, 'Em nome de nosso Senhor Jesus, congregados vós e o meu espírito, pelo poder de nosso Senhor Jesus,', 1, CURRENT_TIMESTAMP, false),
(46, 5, 5, 'seja entregue a Satanás para destruição da carne, para que o espírito seja salvo no dia do Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 6, 'Não é boa a vossa jactância. Não sabeis que um pouco de fermento leveda a massa toda?', 1, CURRENT_TIMESTAMP, false),
(46, 5, 7, 'Expurgai o fermento velho, para que sejais massa nova, assim como sois sem fermento. Porque Cristo, nossa páscoa, já foi sacrificado.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 8, 'Pelo que celebremos a festa, não com o fermento velho, nem com o fermento da malícia e da corrupção, mas com os ázimos da sinceridade e da verdade.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 9, 'Já por carta vos escrevi que não vos comunicásseis com os que se prostituem;', 1, CURRENT_TIMESTAMP, false),
(46, 5, 10, 'com isso não me referia à comunicação em geral com os devassos deste mundo, ou com os avarentos, ou com os roubadores, ou com os idólatras; porque então vos seria necessário sair do mundo.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 11, 'Mas agora vos escrevo que não vos comuniqueis com aquele que, dizendo-se irmão, for devasso, ou avarento, ou idólatra, ou maldizente, ou beberrão, ou roubador; com esse tal nem sequer comais.', 1, CURRENT_TIMESTAMP, false),
(46, 5, 12, 'Pois, que me importa julgar os que estão de fora? Não julgais vós os que estão de dentro?', 1, CURRENT_TIMESTAMP, false),
(46, 5, 13, 'Mas Deus julga os que estão de fora. Tirai esse iníquo do meio de vós.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 1, 'Ousa algum de vós, tendo uma queixa contra outro, ir a juízo perante os injustos, e não perante os santos?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 2, 'Ou não sabeis vós que os santos hão de julgar o mundo? Ora, se o mundo há de ser julgado por vós, sois porventura indignos de julgar as coisas mínimas?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 3, 'Não sabeis vós que havemos de julgar os anjos? Quanto mais as coisas pertencentes a esta vida?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 4, 'Então, se tiverdes negócios em juízo, pertencentes a esta vida, constituís como juízes deles os que são de menos estima na igreja?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 5, 'Para vos envergonhar o digo. Será que não há entre vós sequer um sábio, que possa julgar entre seus irmãos?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 6, 'Mas vai um irmão a juízo contra outro irmão, e isto perante incrédulos?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 7, 'Na verdade já é uma completa derrota para vós o terdes demandadas uns contra os outros. Por que não sofreis antes a injustiça? Por que não sofreis antes a fraude?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 8, 'Mas vós mesmos é que fazeis injustiça e defraudais; e isto a irmãos.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 9, 'Não sabeis que os injustos não herdarão o reino de Deus? Não vos enganeis: nem os devassos, nem os idólatras, nem os adúlteros, nem os efeminados, nem os sodomitas,', 1, CURRENT_TIMESTAMP, false),
(46, 6, 10, 'nem os ladrões, nem os avarentos, nem os bêbedos, nem os maldizentes, nem os roubadores herdarão o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 11, 'E tais fostes alguns de vós; mas fostes lavados, mas fostes santificados, mas fostes justificados em nome do Senhor Jesus Cristo e no Espírito do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 12, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm. Todas as coisas me são lícitas; mas eu não me deixarei dominar por nenhuma delas.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 13, 'Os alimentos são para o estômago e o estômago para os alimentos; Deus, porém aniquilará, tanto um como os outros. Mas o corpo não é para a prostituição, mas para o Senhor, e o Senhor para o corpo.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 14, 'Ora, Deus não somente ressuscitou ao Senhor, mas também nos ressuscitará a nós pelo seu poder.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 15, 'Não sabeis vós que os vossos corpos são membros de Cristo? Tomarei pois os membros de Cristo, e os farei membros de uma meretriz? De modo nenhum.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 16, 'Ou não sabeis que o que se une à meretriz, faz-se um corpo com ela? Porque, como foi dito, os dois serão uma só carne.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 17, 'Mas, o que se une ao Senhor é um só espírito com ele.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 18, 'Fugi da prostituição. Qualquer outro pecado que o homem comete, é fora do corpo; mas o que se prostitui peca contra o seu próprio corpo.', 1, CURRENT_TIMESTAMP, false),
(46, 6, 19, 'Ou não sabeis que o vosso corpo é santuário do Espírito Santo, que habita em vós, o qual possuís da parte de Deus, e que não sois de vós mesmos?', 1, CURRENT_TIMESTAMP, false),
(46, 6, 20, 'Porque fostes comprados por preço; glorificai pois a Deus no vosso corpo.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 1, 'Ora, quanto às coisas de que me escrevestes, bom seria que o homem não tocasse em mulher;', 1, CURRENT_TIMESTAMP, false),
(46, 7, 2, 'mas, por causa da prostituição, tenha cada homem sua própria mulher e cada mulher seu próprio marido.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 3, 'O marido pague à mulher o que lhe é devido, e do mesmo modo a mulher ao marido.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 4, 'A mulher não tem autoridade sobre o seu próprio corpo, mas sim o marido; e também da mesma sorte o marido não tem autoridade sobre o seu próprio corpo, mas sim a mulher.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 5, 'Não vos negueis um ao outro, senão de comum acordo por algum tempo, a fim de vos aplicardes à oração e depois vos ajuntardes outra vez, para que Satanás não vos tente pela vossa incontinência.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 6, 'Digo isto, porém, como que por concessão e não por mandamento.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 7, 'Contudo queria que todos os homens fossem como eu mesmo; mas cada um tem de Deus o seu próprio dom, um deste modo, e outro daquele.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 8, 'Digo, porém, aos solteiros e às viúvas, que lhes é bom se ficarem como eu.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 9, 'Mas, se não podem conter-se, casem-se. Porque é melhor casar do que abrasar-se.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 10, 'Todavia, aos casados, mando, não eu mas o Senhor, que a mulher não se aparte do marido;', 1, CURRENT_TIMESTAMP, false),
(46, 7, 11, 'se, porém, se apartar, que fique sem casar, ou se reconcilie com o marido; e que o marido não deixe a mulher.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 12, 'Mas aos outros digo eu, não o Senhor: Se algum irmão tem mulher incrédula, e ela consente em habitar com ele, não se separe dela.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 13, 'E se alguma mulher tem marido incrédulo, e ele consente em habitar com ela, não se separe dele.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 14, 'Porque o marido incrédulo é santificado pela mulher, e a mulher incrédula é santificada pelo marido crente; de outro modo, os vossos filhos seriam imundos; mas agora são santos.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 15, 'Mas, se o incrédulo se apartar, aparte-se; porque neste caso o irmão, ou a irmã, não está sujeito à servidão; pois Deus nos chamou em paz.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 16, 'Pois, como sabes tu, ó mulher, se salvarás teu marido? ou, como sabes tu, ó marido, se salvarás tua mulher?', 1, CURRENT_TIMESTAMP, false),
(46, 7, 17, 'Somente ande cada um como o Senhor lhe repartiu, cada um como Deus o chamou. E é isso o que ordeno em todas as igrejas.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 18, 'Foi chamado alguém, estando circuncidado? permaneça assim. Foi alguém chamado na incircuncisão? não se circuncide.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 19, 'A circuncisão nada é, e também a incircuncisão nada é, mas sim a observância dos mandamentos de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 20, 'Cada um fique no estado em que foi chamado.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 21, 'Foste chamado sendo escravo? não te dê cuidado; mas se ainda podes tornar-te livre, aproveita a oportunidade.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 22, 'Pois aquele que foi chamado no Senhor, mesmo sendo escravo, é um liberto do Senhor; e assim também o que foi chamado sendo livre, escravo é de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 23, 'Por preço fostes comprados; mas vos façais escravos de homens.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 24, 'Irmãos, cada um fique diante de Deus no estado em que foi chamado.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 25, 'Ora, quanto às virgens, não tenho mandamento do Senhor; dou, porém, o meu parecer, como quem tem alcançado misericórdia do Senhor para ser fiel.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 26, 'Acho, pois, que é bom, por causa da instante necessidade, que a pessoa fique como está.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 27, 'Estás ligado a mulher? não procures separação. Estás livre de mulher? não procures casamento.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 28, 'Mas, se te casares, não pecaste; e, se a virgem se casar, não pecou. Todavia estes padecerão tribulação na carne e eu quisera poupar-vos.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 29, 'Isto, porém, vos digo, irmãos, que o tempo se abrevia; pelo que, doravante, os que têm mulher sejam como se não a tivessem;', 1, CURRENT_TIMESTAMP, false),
(46, 7, 30, 'os que choram, como se não chorassem; os que folgam, como se não folgassem; os que compram, como se não possuíssem;', 1, CURRENT_TIMESTAMP, false),
(46, 7, 31, 'e os que usam deste mundo, como se dele não usassem em absoluto, porque a aparência deste mundo passa.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 32, 'Pois quero que estejais livres de cuidado. Quem não é casado cuida das coisas do Senhor, em como há de agradar ao Senhor,', 1, CURRENT_TIMESTAMP, false),
(46, 7, 33, 'mas quem é casado cuida das coisas do mundo, em como há de agradar a sua mulher,', 1, CURRENT_TIMESTAMP, false),
(46, 7, 34, 'e está dividido. A mulher não casada e a virgem cuidam das coisas do Senhor para serem santas, tanto no corpo como no espírito; a casada, porém, cuida das coisas do mundo, em como há de agradar ao marido.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 35, 'E digo isto para proveito vosso; não para vos enredar, mas para o que é decente, e a fim de poderdes dedicar-vos ao Senhor sem distração alguma.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 36, 'Mas, se alguém julgar que lhe é desairoso conservar solteira a sua filha donzela, se ela estiver passando da idade de se casar, e se for necessário, faça o que quiser; não peca; casem-se.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 37, 'Todavia aquele que está firme em seu coração, não tendo necessidade, mas tendo domínio sobre a sua própria vontade, se resolver no seu coração guardar virgem sua filha, fará bem.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 38, 'De modo que aquele que dá em casamento a sua filha donzela, faz bem; mas o que não a der, fará melhor.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 39, 'A mulher está ligada enquanto o marido vive; mas se falecer o marido, fica livre para casar com quem quiser, contanto que seja no Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 7, 40, 'Será, porém, mais feliz se permanecer como está, segundo o meu parecer, e eu penso que também tenho o Espírito de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 1, 'Ora, no tocante às coisas sacrificadas aos ídolos, sabemos que todos temos ciência. A ciência incha, mas o amor edifica.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 2, 'Se alguém cuida saber alguma coisa, ainda não sabe como convém saber.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 3, 'Mas, se alguém ama a Deus, esse é conhecido dele.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 4, 'Quanto, pois, ao comer das coisas sacrificadas aos ídolos, sabemos que o ídolo nada é no mundo, e que não há outro Deus, senão um só.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 5, 'Pois, ainda que haja também alguns que se chamem deuses, quer no céu quer na terra {como há muitos deuses e muitos senhores},', 1, CURRENT_TIMESTAMP, false),
(46, 8, 6, 'todavia para nós há um só Deus, o Pai, de quem são todas as coisas e para quem nós vivemos; e um só Senhor, Jesus Cristo, pelo qual existem todas as coisas, e por ele nós também.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 7, 'Entretanto, nem em todos há esse conhecimento; pois alguns há que, acostumados até agora com o ídolo, comem como de coisas sacrificadas a um ídolo; e a sua consciência, sendo fraca, contamina-se.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 8, 'Não é, porém, a comida que nos há de recomendar a Deus; pois não somos piores se não comermos, nem melhores se comermos.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 9, 'Mas, vede que essa liberdade vossa não venha a ser motivo de tropeço para os fracos.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 10, 'Porque, se alguém te vir a ti, que tens ciência, reclinado à mesa em templo de ídolos, não será induzido, sendo a sua consciência fraca, a comer das coisas sacrificadas aos ídolos?', 1, CURRENT_TIMESTAMP, false),
(46, 8, 11, 'Pela tua ciência, pois, perece aquele que é fraco, o teu irmão por quem Cristo morreu.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 12, 'Ora, pecando assim contra os irmãos, e ferindo-lhes a consciência quando fraca, pecais contra Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 8, 13, 'Pelo que, se a comida fizer tropeçar a meu irmão, nunca mais comerei carne, para não servir de tropeço a meu irmão.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 1, 'Não sou eu livre? Não sou apóstolo? Não vi eu a Jesus nosso Senhor? Não sois vós obra minha no Senhor?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 2, 'Se eu não sou apóstolo para os outros, ao menos para vós o sou; porque vós sois o selo do meu apostolado no Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 3, 'Esta é a minha defesa para com os que me acusam.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 4, 'Não temos nós direito de comer e de beber?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 5, 'Não temos nós direito de levar conosco esposa crente, como também os demais apóstolos, e os irmãos do Senhor, e Cefas?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 6, 'Ou será que só eu e Barnabé não temos direito de deixar de trabalhar?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 7, 'Quem jamais vai à guerra à sua própria custa? Quem planta uma vinha e não come do seu fruto? Ou quem apascenta um rebanho e não se alimenta do leite do rebanho?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 8, 'Porventura digo eu isto como homem? Ou não diz a lei também o mesmo?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 9, 'Pois na lei de Moisés está escrito: Não atarás a boca do boi quando debulha. Porventura está Deus cuidando dos bois?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 10, 'Ou não o diz certamente por nós? Com efeito, é por amor de nós que está escrito; porque o que lavra deve debulhar com esperança de participar do fruto.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 11, 'Se nós semeamos para vós as coisas espirituais, será muito que de vós colhamos as matérias?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 12, 'Se outros participam deste direito sobre vós, por que não nós com mais justiça? Mas nós nunca usamos deste direito; antes suportamos tudo, para não pormos impedimento algum ao evangelho de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 13, 'Não sabeis vós que os que administram o que é sagrado comem do que é do templo? E que os que servem ao altar, participam do altar?', 1, CURRENT_TIMESTAMP, false),
(46, 9, 14, 'Assim ordenou também o Senhor aos que anunciam o evangelho, que vivam do evangelho.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 15, 'Mas eu de nenhuma destas coisas tenho usado. Nem escrevo isto para que assim se faça comigo; porque melhor me fora morrer, do que alguém fazer vã esta minha glória.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 16, 'Pois, se anuncio o evangelho, não tenho de que me gloriar, porque me é imposta essa obrigação; e ai de mim, se não anunciar o evangelho!', 1, CURRENT_TIMESTAMP, false),
(46, 9, 17, 'Se, pois, o faço de vontade própria, tenho recompensa; mas, se não é de vontade própria, estou apenas incumbido de uma mordomia.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 18, 'Logo, qual é a minha recompensa? É que, pregando o evangelho, eu o faça gratuitamente, para não usar em absoluto do meu direito no evangelho.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 19, 'Pois, sendo livre de todos, fiz-me escravo de todos para ganhar o maior número possível:', 1, CURRENT_TIMESTAMP, false),
(46, 9, 20, 'Fiz-me como judeu para os judeus, para ganhar os judeus; para os que estão debaixo da lei, como se estivesse eu debaixo da lei {embora debaixo da lei não esteja}, para ganhar os que estão debaixo da lei;', 1, CURRENT_TIMESTAMP, false),
(46, 9, 21, 'para os que estão sem lei, como se estivesse sem lei {não estando sem lei para com Deus, mas debaixo da lei de Cristo}, para ganhar os que estão sem lei.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 22, 'Fiz-me como fraco para os fracos, para ganhar os fracos. Fiz-me tudo para todos, para por todos os meios chegar a salvar alguns.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 23, 'Ora, tudo faço por causa do evangelho, para dele tornar-me co-participante.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 24, 'Não sabeis vós que os que correm no estádio, todos, na verdade, correm, mas um só é que recebe o prêmio? Correi de tal maneira que o alcanceis.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 25, 'E todo aquele que luta, exerce domínio próprio em todas as coisas; ora, eles o fazem para alcançar uma coroa corruptível, nós, porém, uma incorruptível.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 26, 'Pois eu assim corro, não como indeciso; assim combato, não como batendo no ar.', 1, CURRENT_TIMESTAMP, false),
(46, 9, 27, 'Antes subjugo o meu corpo, e o reduzo à submissão, para que, depois de pregar a outros, eu mesmo não venha a ficar reprovado.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 1, 'Pois não quero, irmãos, que ignoreis que nossos pais estiveram todos debaixo da nuvem, e todos passaram pelo mar;', 1, CURRENT_TIMESTAMP, false),
(46, 10, 2, 'e, na nuvem e no mar, todos foram batizados em Moisés,', 1, CURRENT_TIMESTAMP, false),
(46, 10, 3, 'e todos comeram do mesmo alimento espiritual;', 1, CURRENT_TIMESTAMP, false),
(46, 10, 4, 'e beberam todos da mesma bebida espiritual, porque bebiam da pedra espiritual que os acompanhava; e a pedra era Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 5, 'Mas Deus não se agradou da maior parte deles; pelo que foram prostrados no deserto.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 6, 'Ora, estas coisas nos foram feitas para exemplo, a fim de que não cobicemos as coisas más, como eles cobiçaram.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 7, 'Não vos torneis, pois, idólatras, como alguns deles, conforme está escrito: O povo assentou-se a comer e a beber, e levantou-se para folgar.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 8, 'Nem nos prostituamos, como alguns deles fizeram; e caíram num só dia vinte e três mil.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 9, 'E não tentemos o Senhor, como alguns deles o tentaram, e pereceram pelas serpentes.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 10, 'E não murmureis, como alguns deles murmuraram, e pereceram pelo destruidor.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 11, 'Ora, tudo isto lhes acontecia como exemplo, e foi escrito para aviso nosso, para quem já são chegados os fins dos séculos.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 12, 'Aquele, pois, que pensa estar em pé, olhe não caia.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 13, 'Não vos sobreveio nenhuma tentação, senão humana; mas fiel é Deus, o qual não deixará que sejais tentados acima do que podeis resistir, antes com a tentação dará também o meio de saída, para que a possais suportar.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 14, 'Portanto, meus amados, fugi da idolatria.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 15, 'Falo como a entendidos; julgai vós mesmos o que digo.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 16, 'Porventura o cálice de bênção que abençoamos, não é a comunhão do sangue de Cristo? O pão que partimos, não é porventura a comunhão do corpo de Cristo?', 1, CURRENT_TIMESTAMP, false),
(46, 10, 17, 'Pois nós, embora muitos, somos um só pão, um só corpo; porque todos participamos de um mesmo pão.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 18, 'Vede a Israel segundo a carne; os que comem dos sacrifícios não são porventura participantes do altar?', 1, CURRENT_TIMESTAMP, false),
(46, 10, 19, 'Mas que digo? Que o sacrificado ao ídolo é alguma coisa? Ou que o ídolo é alguma coisa?', 1, CURRENT_TIMESTAMP, false),
(46, 10, 20, 'Antes digo que as coisas que eles sacrificam, sacrificam-nas a demônios, e não a Deus. E não quero que sejais participantes com os demônios.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 21, 'Não podeis beber do cálice do Senhor e do cálice de demônios; não podeis participar da mesa do Senhor e da mesa de demônios.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 22, 'Ou provocaremos a zelos o Senhor? Somos, porventura, mais fortes do que ele?', 1, CURRENT_TIMESTAMP, false),
(46, 10, 23, 'Todas as coisas são lícitas, mas nem todas as coisas convêm; todas as coisas são lícitas, mas nem todas as coisas edificam.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 24, 'Ninguém busque o proveito próprio, antes cada um o de outrem.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 25, 'Comei de tudo quanto se vende no mercado, nada perguntando por causa da consciência.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 26, 'Pois do Senhor é a terra e a sua plenitude.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 27, 'Se, portanto, algum dos incrédulos vos convidar, e quiserdes ir, comei de tudo o que se puser diante de vós, nada perguntando por causa da consciência.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 28, 'Mas, se alguém vos disser: Isto foi oferecido em sacrifício; não comais por causa daquele que vos advertiu e por causa da consciência;', 1, CURRENT_TIMESTAMP, false),
(46, 10, 29, 'consciência, digo, não a tua, mas a do outro. Pois, por que há de ser julgada a minha liberdade pela consciência de outrem?', 1, CURRENT_TIMESTAMP, false),
(46, 10, 30, 'E, se eu com gratidão participo, por que sou vilipendiado por causa daquilo por que dou graças?', 1, CURRENT_TIMESTAMP, false),
(46, 10, 31, 'Portanto, quer comais quer bebais, ou façais, qualquer outra coisa, fazei tudo para glória de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 10, 32, 'Não vos torneis causa de tropeço nem a judeus, nem a gregos, nem a igreja de Deus;', 1, CURRENT_TIMESTAMP, false),
(46, 10, 33, 'assim como também eu em tudo procuro agradar a todos, não buscando o meu próprio proveito, mas o de muitos, para que sejam salvos.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 1, 'Sede meus imitadores, como também eu o sou de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 2, 'Ora, eu vos louvo, porque em tudo vos lembrais de mim, e guardais os preceitos assim como vo-los entreguei.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 3, 'Quero porém, que saibais que Cristo é a cabeça de todo homem, o homem a cabeça da mulher, e Deus a cabeça de Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 4, 'Todo homem que ora ou profetiza com a cabeça coberta desonra a sua cabeça.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 5, 'Mas toda mulher que ora ou profetiza com a cabeça descoberta desonra a sua cabeça, porque é a mesma coisa como se estivesse rapada.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 6, 'Portanto, se a mulher não se cobre com véu, tosquie-se também; se, porém, para a mulher é vergonhoso ser tosquiada ou rapada, cubra-se com véu.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 7, 'Pois o homem, na verdade, não deve cobrir a cabeça, porque é a imagem e glória de Deus; mas a mulher é a glória do homem.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 8, 'Porque o homem não proveio da mulher, mas a mulher do homem;', 1, CURRENT_TIMESTAMP, false),
(46, 11, 9, 'nem foi o homem criado por causa da mulher, mas sim, a mulher por causa do homem.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 10, 'Portanto, a mulher deve trazer sobre a cabeça um sinal de submissão, por causa dos anjos.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 11, 'Todavia, no Senhor, nem a mulher é independente do homem, nem o homem é independente da mulher.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 12, 'pois, assim como a mulher veio do homem, assim também o homem nasce da mulher, mas tudo vem de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 13, 'julgai entre vós mesmos: é conveniente que uma mulher com a cabeça descoberta ore a Deus?', 1, CURRENT_TIMESTAMP, false),
(46, 11, 14, 'Não vos ensina a própria natureza que se o homem tiver cabelo comprido, é para ele uma desonra;', 1, CURRENT_TIMESTAMP, false),
(46, 11, 15, 'mas se a mulher tiver o cabelo comprido, é para ela uma glória? Pois a cabeleira lhe foi dada em lugar de véu.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 16, 'Mas, se alguém quiser ser contencioso, nós não temos tal costume, nem tampouco as igrejas de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 17, 'Nisto, porém, que vou dizer-vos não vos louvo; porquanto vos ajuntais, não para melhor, mas para pior.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 18, 'Porque, antes de tudo, ouço que quando vos ajuntais na igreja há entre vós dissensões; e em parte o creio.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 19, 'E até importa que haja entre vós facções, para que os aprovados se tornem manifestos entre vós.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 20, 'De sorte que, quando vos ajuntais num lugar, não é para comer a ceia do Senhor;', 1, CURRENT_TIMESTAMP, false),
(46, 11, 21, 'porque quando comeis, cada um toma antes de outrem a sua própria ceia; e assim um fica com fome e outro se embriaga.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 22, 'Não tendes porventura casas onde comer e beber? Ou desprezais a igreja de Deus, e envergonhais os que nada têm? Que vos direi? Louvar-vos-ei? Nisto não vos louvo.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 23, 'Porque eu recebi do Senhor o que também vos entreguei: que o Senhor Jesus, na noite em que foi traído, tomou pão;', 1, CURRENT_TIMESTAMP, false),
(46, 11, 24, 'e, havendo dado graças, o partiu e disse: Isto é o meu corpo que é por vós; fazei isto em memória de mim.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 25, 'Semelhantemente também, depois de cear, tomou o cálice, dizendo: Este cálice é o novo pacto no meu sangue; fazei isto, todas as vezes que o beberdes, em memória de mim.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 26, 'Porque todas as vezes que comerdes deste pão e beberdes do cálice estareis anunciando a morte do Senhor, até que ele venha.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 27, 'De modo que qualquer que comer do pão, ou beber do cálice do Senhor indignamente, será culpado do corpo e do sangue do Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 28, 'Examine-se, pois, o homem a si mesmo, e assim coma do pão e beba do cálice.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 29, 'Porque quem come e bebe, come e bebe para sua própria condenação, se não discernir o corpo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 30, 'Por causa disto há entre vós muitos fracos e enfermos, e muitos que dormem.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 31, 'Mas, se nós nos julgássemos a nós mesmos, não seríamos julgados;', 1, CURRENT_TIMESTAMP, false),
(46, 11, 32, 'quando, porém, somos julgados pelo Senhor, somos corrigidos, para não sermos condenados com o mundo.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 33, 'Portanto, meus irmãos, quando vos ajuntais para comer, esperai uns pelos outros.', 1, CURRENT_TIMESTAMP, false),
(46, 11, 34, 'Se algum tiver fome, coma em casa, a fim de que não vos reunais para condenação vossa. E as demais coisas eu as ordenarei quando for.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 1, 'Ora, a respeito dos dons espirituais, não quero, irmãos, que sejais ignorantes.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 2, 'Vós sabeis que, quando éreis gentios, vos desviáveis para os ídolos mudos, conforme éreis levados.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 3, 'Portanto vos quero fazer compreender que ninguém, falando pelo Espírito de Deus, diz: Jesus é anátema! e ninguém pode dizer: Jesus é o Senhor! senão pelo Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 4, 'Ora, há diversidade de dons, mas o Espírito é o mesmo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 5, 'E há diversidade de ministérios, mas o Senhor é o mesmo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 6, 'E há diversidade de operações, mas é o mesmo Deus que opera tudo em todos.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 7, 'A cada um, porém, é dada a manifestação do Espírito para o proveito comum.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 8, 'Porque a um, pelo Espírito, é dada a palavra da sabedoria; a outro, pelo mesmo Espírito, a palavra da ciência;', 1, CURRENT_TIMESTAMP, false),
(46, 12, 9, 'a outro, pelo mesmo Espírito, a fé; a outro, pelo mesmo Espírito, os dons de curar;', 1, CURRENT_TIMESTAMP, false),
(46, 12, 10, 'a outro a operação de milagres; a outro a profecia; a outro o dom de discernir espíritos; a outro a variedade de línguas; e a outro a interpretação de línguas.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 11, 'Mas um só e o mesmo Espírito opera todas estas coisas, distribuindo particularmente a cada um como quer.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 12, 'Porque, assim como o corpo é um, e tem muitos membros, e todos os membros do corpo, embora muitos, formam um só corpo, assim também é Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 13, 'Pois em um só Espírito fomos todos nós batizados em um só corpo, quer judeus, quer gregos, quer escravos quer livres; e a todos nós foi dado beber de um só Espírito.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 14, 'Porque também o corpo não é um membro, mas muitos.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 15, 'Se o pé disser: Porque não sou mão, não sou do corpo; nem por isso deixará de ser do corpo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 16, 'E se a orelha disser: Porque não sou olho, não sou do corpo; nem por isso deixará de ser do corpo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 17, 'Se o corpo todo fosse olho, onde estaria o ouvido? Se todo fosse ouvido, onde estaria o olfato?', 1, CURRENT_TIMESTAMP, false),
(46, 12, 18, 'Mas agora Deus colocou os membros no corpo, cada um deles como quis.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 19, 'E, se todos fossem um só membro, onde estaria o corpo?', 1, CURRENT_TIMESTAMP, false),
(46, 12, 20, 'Agora, porém, há muitos membros, mas um só corpo.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 21, 'E o olho não pode dizer à mão: Não tenho necessidade de ti; nem ainda a cabeça aos pés: Não tenho necessidade de vós.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 22, 'Antes, os membros do corpo que parecem ser mais fracos são necessários;', 1, CURRENT_TIMESTAMP, false),
(46, 12, 23, 'e os membros do corpo que reputamos serem menos honrados, a esses revestimos com muito mais honra; e os que em nós não são decorosos têm muito mais decoro,', 1, CURRENT_TIMESTAMP, false),
(46, 12, 24, 'ao passo que os decorosos não têm necessidade disso. Mas Deus assim formou o corpo, dando muito mais honra ao que tinha falta dela,', 1, CURRENT_TIMESTAMP, false),
(46, 12, 25, 'para que não haja divisão no corpo, mas que os membros tenham igual cuidado uns dos outros.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 26, 'De maneira que, se um membro padece, todos os membros padecem com ele; e, se um membro é honrado, todos os membros se regozijam com ele.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 27, 'Ora, vós sois corpo de Cristo, e individualmente seus membros.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 28, 'E a uns pôs Deus na igreja, primeiramente apóstolos, em segundo lugar profetas, em terceiro mestres, depois operadores de milagres, depois dons de curar, socorros, governos, variedades de línguas.', 1, CURRENT_TIMESTAMP, false),
(46, 12, 29, 'Porventura são todos apóstolos? são todos profetas? são todos mestres? são todos operadores de milagres?', 1, CURRENT_TIMESTAMP, false),
(46, 12, 30, 'Todos têm dons de curar? falam todos em línguas? interpretam todos?', 1, CURRENT_TIMESTAMP, false),
(46, 12, 31, 'Mas procurai com zelo os maiores dons. Ademais, eu vos mostrarei um caminho sobremodo excelente.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 1, 'Ainda que eu falasse as línguas dos homens e dos anjos, e não tivesse amor, seria como o metal que soa ou como o címbalo que retine.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 2, 'E ainda que tivesse o dom de profecia, e conhecesse todos os mistérios e toda a ciência, e ainda que tivesse toda fé, de maneira tal que transportasse os montes, e não tivesse amor, nada seria.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 3, 'E ainda que distribuísse todos os meus bens para sustento dos pobres, e ainda que entregasse o meu corpo para ser queimado, e não tivesse amor, nada disso me aproveitaria.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 4, 'O amor é sofredor, é benigno; o amor não é invejoso; o amor não se vangloria, não se ensoberbece,', 1, CURRENT_TIMESTAMP, false),
(46, 13, 5, 'não se porta inconvenientemente, não busca os seus próprios interesses, não se irrita, não suspeita mal;', 1, CURRENT_TIMESTAMP, false),
(46, 13, 6, 'não se regozija com a injustiça, mas se regozija com a verdade;', 1, CURRENT_TIMESTAMP, false),
(46, 13, 7, 'tudo sofre, tudo crê, tudo espera, tudo suporta.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 8, 'O amor jamais acaba; mas havendo profecias, serão aniquiladas; havendo línguas, cessarão; havendo ciência, desaparecerá;', 1, CURRENT_TIMESTAMP, false),
(46, 13, 9, 'porque, em parte conhecemos, e em parte profetizamos;', 1, CURRENT_TIMESTAMP, false),
(46, 13, 10, 'mas, quando vier o que é perfeito, então o que é em parte será aniquilado.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 11, 'Quando eu era menino, pensava como menino; mas, logo que cheguei a ser homem, acabei com as coisas de menino.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 12, 'Porque agora vemos como por espelho, em enigma, mas então veremos face a face; agora conheço em parte, mas então conhecerei plenamente, como também sou plenamente conhecido.', 1, CURRENT_TIMESTAMP, false),
(46, 13, 13, 'Agora, pois, permanecem a fé, a esperança, o amor, estes três; mas o maior destes é o amor.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 1, 'Segui o amor; e procurai com zelo os dons espirituais, mas principalmente o de profetizar.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 2, 'Porque o que fala em língua não fala aos homens, mas a Deus; pois ninguém o entende; porque em espírito fala mistérios.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 3, 'Mas o que profetiza fala aos homens para edificação, exortação e consolação.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 4, 'O que fala em língua edifica-se a si mesmo, mas o que profetiza edifica a igreja.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 5, 'Ora, quero que todos vós faleis em línguas, mas muito mais que profetizeis, pois quem profetiza é maior do que aquele que fala em línguas, a não ser que também intercede para que a igreja receba edificação.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 6, 'E agora, irmãos, se eu for ter convosco falando em línguas, de que vos aproveitarei, se vos não falar ou por meio de revelação, ou de ciência, ou de profecia, ou de doutrina?', 1, CURRENT_TIMESTAMP, false),
(46, 14, 7, 'Ora, até as coisas inanimadas, que emitem som, seja flauta, seja cítara, se não formarem sons distintos, como se conhecerá o que se toca na flauta ou na cítara?', 1, CURRENT_TIMESTAMP, false),
(46, 14, 8, 'Porque, se a trombeta der sonido incerto, quem se preparará para a batalha?', 1, CURRENT_TIMESTAMP, false),
(46, 14, 9, 'Assim também vós, se com a língua não pronunciardes palavras bem inteligíveis, como se entenderá o que se diz? porque estareis como que falando ao ar.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 10, 'Há, por exemplo, tantas espécies de vozes no mundo, e nenhuma delas sem significação.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 11, 'Se, pois, eu não souber o sentido da voz, serei estrangeiro para aquele que fala, e o que fala será estrangeiro para mim.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 12, 'Assim também vós, já que estais desejosos de dons espirituais, procurai abundar neles para a edificação da igreja.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 13, 'Por isso, o que fala em língua, ore para que a possa interpretar.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 14, 'Porque se eu orar em língua, o meu espírito ora, sim, mas o meu entendimento fica infrutífero.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 15, 'Que fazer, pois? Orarei com o espírito, mas também orarei com o entendimento; cantarei com o espírito, mas também cantarei com o entendimento.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 16, 'De outra maneira, se tu bendisseres com o espírito, como dirá o amém sobre a tua ação de graças aquele que ocupa o lugar de indouto, visto que não sabe o que dizes?', 1, CURRENT_TIMESTAMP, false),
(46, 14, 17, 'Porque realmente tu dás bem as graças, mas o outro não é edificado.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 18, 'Dou graças a Deus, que falo em línguas mais do que vós todos.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 19, 'Todavia na igreja eu antes quero falar cinco palavras com o meu entendimento, para que possa também instruir os outros, do que dez mil palavras em língua.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 20, 'Irmãos, não sejais meninos no entendimento; na malícia, contudo, sede criancinhas, mas adultos no entendimento.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 21, 'Está escrito na lei: Por homens de outras línguas e por lábios de estrangeiros falarei a este povo; e nem assim me ouvirão, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 22, 'De modo que as línguas são um sinal, não para os crentes, mas para os incrédulos; a profecia, porém, não é sinal para os incrédulos, mas para os crentes.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 23, 'Se, pois, toda a igreja se reunir num mesmo lugar, e todos falarem em línguas, e entrarem indoutos ou incrédulos, não dirão porventura que estais loucos?', 1, CURRENT_TIMESTAMP, false),
(46, 14, 24, 'Mas, se todos profetizarem, e algum incrédulo ou indouto entrar, por todos é convencido, por todos é julgado;', 1, CURRENT_TIMESTAMP, false),
(46, 14, 25, 'os segredos do seu coração se tornam manifestos; e assim, prostrando-se sobre o seu rosto, adorará a Deus, declarando que Deus está verdadeiramente entre vós.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 26, 'Que fazer, pois, irmãos? Quando vos congregais, cada um de vós tem salmo, tem doutrina, tem revelação, tem língua, tem interpretação. Faça-se tudo para edificação.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 27, 'Se alguém falar em língua, faça-se isso por dois, ou quando muito três, e cada um por sua vez, e haja um que interprete.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 28, 'Mas, se não houver intérprete, esteja calado na igreja, e fale consigo mesmo, e com Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 29, 'E falem os profetas, dois ou três, e os outros julguem.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 30, 'Mas se a outro, que estiver sentado, for revelada alguma coisa, cale-se o primeiro.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 31, 'Porque todos podereis profetizar, cada um por sua vez; para que todos aprendam e todos sejam consolados;', 1, CURRENT_TIMESTAMP, false),
(46, 14, 32, 'pois os espíritos dos profetas estão sujeitos aos profetas;', 1, CURRENT_TIMESTAMP, false),
(46, 14, 33, 'porque Deus não é Deus de confusão, mas sim de paz. Como em todas as igrejas dos santos,', 1, CURRENT_TIMESTAMP, false),
(46, 14, 34, 'as mulheres estejam caladas nas igrejas; porque lhes não é permitido falar; mas estejam submissas como também ordena a lei.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 35, 'E, se querem aprender alguma coisa, perguntem em casa a seus próprios maridos; porque é indecoroso para a mulher o falar na igreja.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 36, 'Porventura foi de vós que partiu a palavra de Deus? Ou veio ela somente para vós?', 1, CURRENT_TIMESTAMP, false),
(46, 14, 37, 'Se alguém se considera profeta, ou espiritual, reconheça que as coisas que vos escrevo são mandamentos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 38, 'Mas, se alguém ignora isto, ele é ignorado.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 39, 'Portanto, irmãos, procurai com zelo o profetizar, e não proibais o falar em línguas.', 1, CURRENT_TIMESTAMP, false),
(46, 14, 40, 'Mas faça-se tudo decentemente e com ordem.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 1, 'Ora, eu vos lembro, irmãos, o evangelho que já vos anunciei; o qual também recebestes, e no qual perseverais,', 1, CURRENT_TIMESTAMP, false),
(46, 15, 2, 'pelo qual também sois salvos, se é que o conservais tal como vo-lo anunciei; se não é que crestes em vão.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 3, 'Porque primeiramente vos entreguei o que também recebi: que Cristo morreu por nossos pecados, segundo as Escrituras;', 1, CURRENT_TIMESTAMP, false),
(46, 15, 4, 'que foi sepultado; que foi ressuscitado ao terceiro dia, segundo as Escrituras;', 1, CURRENT_TIMESTAMP, false),
(46, 15, 5, 'que apareceu a Cefas, e depois aos doze;', 1, CURRENT_TIMESTAMP, false),
(46, 15, 6, 'depois apareceu a mais de quinhentos irmãos duma vez, dos quais vive ainda a maior parte, mas alguns já dormiram;', 1, CURRENT_TIMESTAMP, false),
(46, 15, 7, 'depois apareceu a Tiago, então a todos os apóstolos;', 1, CURRENT_TIMESTAMP, false),
(46, 15, 8, 'e por derradeiro de todos apareceu também a mim, como a um abortivo.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 9, 'Pois eu sou o menor dos apóstolos, que nem sou digno de ser chamado apóstolo, porque persegui a igreja de Deus.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 10, 'Mas pela graça de Deus sou o que sou; e a sua graça para comigo não foi vã, antes trabalhei muito mais do que todos eles; todavia não eu, mas a graça de Deus que está comigo.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 11, 'Então, ou seja eu ou sejam eles, assim pregamos e assim crestes.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 12, 'Ora, se prega que Cristo foi ressuscitado dentre os mortos, como dizem alguns entre vós que não há ressurreição de mortos?', 1, CURRENT_TIMESTAMP, false),
(46, 15, 13, 'Mas se não há ressurreição de mortos, também Cristo não foi ressuscitado.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 14, 'E, se Cristo não foi ressuscitado, logo é vã a nossa pregação, e também é vã a vossa fé.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 15, 'E assim somos também considerados como falsas testemunhas de Deus que ele ressuscitou a Cristo, ao qual, porém, não ressuscitou, se, na verdade, os mortos não são ressuscitados.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 16, 'Porque, se os mortos não são ressuscitados, também Cristo não foi ressuscitado.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 17, 'E, se Cristo não foi ressuscitado, é vã a vossa fé, e ainda estais nos vossos pecados.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 18, 'Logo, também os que dormiram em Cristo estão perdidos.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 19, 'Se é só para esta vida que esperamos em Cristo, somos de todos os homens os mais dignos de lástima.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 20, 'Mas na realidade Cristo foi ressuscitado dentre os mortos, sendo ele as primícias dos que dormem.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 21, 'Porque, assim como por um homem veio a morte, também por um homem veio a ressurreição dos mortos.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 22, 'Pois como em Adão todos morrem, do mesmo modo em Cristo todos serão vivificados.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 23, 'Cada um, porém, na sua ordem: Cristo as primícias, depois os que são de Cristo, na sua vinda.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 24, 'Então virá o fim quando ele entregar o reino a Deus o Pai, quando houver destruído todo domínio, e toda autoridade e todo poder.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 25, 'Pois é necessário que ele reine até que haja posto todos os inimigos debaixo de seus pés.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 26, 'Ora, o último inimigo a ser destruído é a morte.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 27, 'Pois se lê: Todas as coisas sujeitou debaixo de seus pés. Mas, quando diz: Todas as coisas lhe estão sujeitas, claro está que se excetua aquele que lhe sujeitou todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 28, 'E, quando todas as coisas lhe estiverem sujeitas, então também o próprio Filho se sujeitará àquele que todas as coisas lhe sujeitou, para que Deus seja tudo em todos.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 29, 'De outra maneira, que farão os que se batizam pelos mortos? Se absolutamente os mortos não ressuscitam, por que então se batizam por eles?', 1, CURRENT_TIMESTAMP, false),
(46, 15, 30, 'E por que nos expomos também nós a perigos a toda hora?', 1, CURRENT_TIMESTAMP, false),
(46, 15, 31, 'Eu vos declaro, irmãos, pela glória que de vós tenho em Cristo Jesus nosso Senhor, que morro todos os dias.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 32, 'Se, como homem, combati em Éfeso com as feras, que me aproveita isso? Se os mortos não são ressuscitados, comamos e bebamos, porque amanhã morreremos.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 33, 'Não vos enganeis. As más companhias corrompem os bons costumes.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 34, 'Acordai para a justiça e não pequeis mais; porque alguns ainda não têm conhecimento de Deus; digo-o para vergonha vossa.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 35, 'Mas alguém dirá: Como ressuscitam os mortos? e com que qualidade de corpo vêm?', 1, CURRENT_TIMESTAMP, false),
(46, 15, 36, 'Insensato! o que tu semeias não é vivificado, se primeiro não morrer.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 37, 'E, quando semeias, não semeias o corpo que há de nascer, mas o simples grão, como o de trigo, ou o de outra qualquer semente.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 38, 'Mas Deus lhe dá um corpo como lhe aprouve, e a cada uma das sementes um corpo próprio.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 39, 'Nem toda carne é uma mesma carne; mas uma é a carne dos homens, outra a carne dos animais, outra a das aves e outra a dos peixes.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 40, 'Também há corpos celestes e corpos terrestres, mas uma é a glória dos celestes e outra a dos terrestres.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 41, 'Uma é a glória do sol, outra a glória da lua e outra a glória das estrelas; porque uma estrela difere em glória de outra estrela.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 42, 'Assim também é a ressurreição, é ressuscitado em incorrupção.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 43, 'Semeia-se em ignomínia, é ressuscitado em glória. Semeia-se em fraqueza, é ressuscitado em poder.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 44, 'Semeia-se corpo animal, é ressuscitado corpo espiritual. Se há corpo animal, há também corpo espiritual.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 45, 'Assim também está escrito: O primeiro homem, Adão, tornou-se alma vivente; o último Adão, espírito vivificante.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 46, 'Mas não é primeiro o espiritual, senão o animal; depois o espiritual.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 47, 'O primeiro homem, sendo da terra, é terreno; o segundo homem é do céu.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 48, 'Qual o terreno, tais também os terrenos; e, qual o celestial, tais também os celestiais.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 49, 'E, assim como trouxemos a imagem do terreno, traremos também a imagem do celestial.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 50, 'Mas digo isto, irmãos, que carne e sangue não podem herdar o reino de Deus; nem a corrupção herda a incorrupção.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 51, 'Eis aqui vos digo um mistério: Nem todos dormiremos mas todos seremos transformados,', 1, CURRENT_TIMESTAMP, false),
(46, 15, 52, 'num momento, num abrir e fechar de olhos, ao som da última trombeta; porque a trombeta soará, e os mortos serão ressuscitados incorruptíveis, e nós seremos transformados.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 53, 'Porque é necessário que isto que é corruptível se revista da incorruptibilidade e que isto que é mortal se revista da imortalidade.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 54, 'Mas, quando isto que é corruptível se revestir da incorruptibilidade, e isto que é mortal se revestir da imortalidade, então se cumprirá a palavra que está escrito: Tragada foi a morte na vitória.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 55, 'Onde está, ó morte, a tua vitória? Onde está, ó morte, o teu aguilhão?', 1, CURRENT_TIMESTAMP, false),
(46, 15, 56, 'O aguilhão da morte é o pecado, e a força do pecado é a lei.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 57, 'Mas graça a Deus que nos dá a vitória por nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(46, 15, 58, 'Portanto, meus amados irmãos, sede firmes e constantes, sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão no Senhor.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 1, 'Ora, quanto à coleta para os santos fazei vós também o mesmo que ordenei às igrejas da Galiléia.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 2, 'No primeiro dia da semana cada um de vós ponha de parte o que puder, conforme tiver prosperado, guardando-o, para que se não façam coletas quando eu chegar.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 3, 'E, quando tiver chegado, mandarei os que por carta aprovardes para levar a vossa dádiva a Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(46, 16, 4, 'mas, se valer a pena que eu também vá, irão comigo.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 5, 'Irei, porém, ter convosco depois de ter passado pela Macedônia, pois tenho de passar pela Macedônia;', 1, CURRENT_TIMESTAMP, false),
(46, 16, 6, 'e talvez demore convosco algum tempo, ou mesmo passe o inverno, para que me encaminheis para onde quer que eu for.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 7, 'Pois não quero ver-vos desta vez apenas de passagem, antes espero ficar convosco algum tempo, se o Senhor o permitir.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 8, 'Ficarei, porém, em Éfeso até o Pentecostes;', 1, CURRENT_TIMESTAMP, false),
(46, 16, 9, 'porque uma porta grande e eficaz se me abriu; e há muitos adversários.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 10, 'Ora, se Timóteo for, vede que esteja sem temor entre vós; porque trabalha na obra do Senhor, como eu também,', 1, CURRENT_TIMESTAMP, false),
(46, 16, 11, 'Portanto ninguém o despreze; mas encaminhai-o em paz, para que venha ter comigo, pois o espero com os irmãos.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 12, 'Quanto ao irmão Apolo, roguei-lhe muito que fosse com os irmãos ter convosco; mas de modo algum quis ir agora; irá porém, quando se lhe ofereça boa ocasião.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 13, 'Vigiai, estai firmes na fé, portai-vos varonilmente, sede fortes.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 14, 'Todas as vossas obras sejam feitas em amor.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 15, 'Agora vos rogo, irmãos-pois sabeis que a família de Estéfanas é as primícias da Acaía, e que se tem dedicado ao ministério dos santos-', 1, CURRENT_TIMESTAMP, false),
(46, 16, 16, 'que também vos sujeiteis aos tais, e a todo aquele que auxilia na obra e trabalha.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 17, 'Regozijo-me com a vinda de Estéfanas, de Fortunato e de Acaico; porque estes supriram o que da vossa parte me faltava.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 18, 'Porque recrearam o meu espírito assim como o vosso. Reconhecei, pois, aos tais.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 19, 'As igrejas da Ásia vos saúdam. Saúdam-vos afetuosamente no Senhor Aqüila e Prisca, com a igreja que está em sua casa.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 20, 'Todos os irmãos vos saúdam. Saudai-vos uns aos outros com ósculo santo.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 21, 'Esta saudação é de meu próprio punho, Paulo.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 22, 'Se alguém não ama ao Senhor, seja anátema! Maranata.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 23, 'A graça do Senhor Jesus seja convosco.', 1, CURRENT_TIMESTAMP, false),
(46, 16, 24, 'O meu amor seja com todos vós em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 1, 'Adão, Sete, Enos,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 2, 'Quenã, Maalalel, Jarede,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 3, 'Enoque, Matusalém, Lameque,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 4, 'Noé, Sem, Cam e Jafé.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 5, 'Os filhos de Jafé: Gomer, Magogue, Madai, Javã, Tubal, Meseque e Tiras.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 6, 'Os filhos de Gomer: Asquenaz, Rifate e Togarma.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 7, 'Os filhos de Javã: Elisá, Társis, Quitim e Dodanim.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 8, 'Os filhos de Cam: Cuche, Mizraim, Pute e Canaã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 9, 'Os filhos de Cuche: Seba, Havilá, Sabtá, Raamá e Sabtecá; e os filhos de Raamá: Sebá e Dedã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 10, 'Cuche foi pai de Ninrode, o qual foi o primeiro a ser poderoso na terra:', 1, CURRENT_TIMESTAMP, false),
(13, 1, 11, 'De Mizraim descenderam os ludeus, os anameus, os leabeus, os naftueus,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 12, 'os patrusins, os casluins {dos quais procederam os filisteus} e os caftoreus.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 13, 'Canaã foi pai de Sidom, seu primogênito, e de Hete,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 14, 'e dos jebuseus, dos amorreus, dos girgaseus,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 15, 'dos heveus, dos arqueus, dos sineus,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 16, 'dos arvadeus, dos zemareus e dos hamateus.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 17, 'Os filhos de Sem: Elão, Assur, Arfaxade, Lude, Arã, Uz, Hul, Geter e Meseque.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 18, 'Arfaxade foi pai de Selá; e Selá foi pai de Eber.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 19, 'A Eber nasceram dois filhos: o nome dum foi Pelegue, pois nos seus dias se repartiu a terra; e o nome do seu irmão foi Joctã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 20, 'Joctã foi pai de Almodá, Selefe, Hazarmavé, Jerá,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 21, 'Hadorão, Uzal, Diclá,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 22, 'Ebal, Abimael, Sebá,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 23, 'Ofir, Havilá e Jobabe; todos esses foram filhos de Joctã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 24, 'Sem, Arfaxade, Selá;', 1, CURRENT_TIMESTAMP, false),
(13, 1, 25, 'Eber, Pelegue, Reú;', 1, CURRENT_TIMESTAMP, false),
(13, 1, 26, 'Serugue, Naor, Tera;', 1, CURRENT_TIMESTAMP, false),
(13, 1, 27, 'Abrão, que é Abraão.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 28, 'Os filhos de Abraão: Isaque e Ismael.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 29, 'Estas são as suas gerações: o primogênito de Ismael, Nebaiote; depois Quedar, Adbeel, Mibsão,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 30, 'Misma, Dumá, Massá, Hadade, Tema,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 31, 'Jetur, Nafis e Quedemá; esses foram os filhos de Ismael.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 32, 'Quanto aos filhos de Quetura, concubina de Abraão, esta deu à luz Zinrã, Jocsã, Medã, Midiã, Isbaque e Suá. Os filhos de Jocsã foram Sebá e Dedã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 33, 'Os filhos de Midiã: Efá, Efer, Hanoque, Abidá e Eldá; todos esses foram filhos de Quetura.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 34, 'Abraão foi pai de Isaque. Os filhos de Isaque: Esaú e Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 35, 'Os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão e Corá.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 36, 'Os filhos de Elifaz: Temã, Omar, Zefi, Gatã, Quenaz, Timna e Amaleque.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 37, 'Os filhos de Reuel: Naate, Zerá, Samá e Mizá.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 38, 'Os filhos de Seir: Lotã, Sobal, Zibeão, Anás, Disom, Eser e Disã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 39, 'Os filhos de Lotã: Hori, e Homã; e a irmã de Lotã foi Timna.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 40, 'Os filhos de Sobal: Aliã, Manaate, Ebal, Sefi e Onã. Os filhos de Zibeão: Aías e Anás.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 41, 'Anás foi pai de Disom. Os filhos de Disom: Hanrão, Esbã, Itrã e Querã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 42, 'Os filhos de Eser: Bilã, Zaavã e Jaacã. Os filhos de Disã: Uz e Arã.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 43, 'Estes foram os reis que reinaram na terra de Edom, antes que houvesse rei sobre os filhos de Israel: Belá, filho de Beor; e era o nome da sua cidade Dinabá.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 44, 'Morreu Belá, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 45, 'Morreu Jobabe, e reinou em seu lugar Husão, da terra dos temanitas.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 46, 'Morreu Husão, e reinou em seu lugar Hadade, filho de Bedade, que derrotou os midianitas no campo de Moabe; e era o nome da sua cidade Avite.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 47, 'Morreu Hadade, e reinou em seu lugar Sâmela, de Masreca.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 48, 'Morreu Sâmela, e reinou em seu lugar Saul, de Reobote junto ao rio.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 49, 'Morreu Saul, e reinou em seu lugar Baal-Ranã, filho de Acbor.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 50, 'Morreu Baal-Hanã, e Hadade reinou em seu lugar; e era o nome da sua cidade Paí. O nome de sua mulher era Meetabel, filha de Matrede, filha de Me-Zaabe.', 1, CURRENT_TIMESTAMP, false),
(13, 1, 51, 'E morreu Hadade. Os príncipes de Edom foram: o príncipe Timna, o príncipe Aliá, o príncipe Jetete,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 52, 'o príncipe Aolíbama, o príncipe Elá, o príncipe Pinom,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 53, 'o príncipe Quenaz, o príncipe Temã, o príncipe Mibzar,', 1, CURRENT_TIMESTAMP, false),
(13, 1, 54, 'o príncipe Magdiel, o príncipe lrã. Estes foram os príncipes de Edom.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 1, 'Foram estes os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar, Zebulom,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 2, 'Dã, José, Benjamim, Naftali, Gade e Aser.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 3, 'Os filhos de Judá: Er, Onã e Selá; estes três lhe nasceram da filha de Suá, a cananéia. E Er, o primogênito de Judá, foi mau aos olhos do Senhor, que o matou:', 1, CURRENT_TIMESTAMP, false),
(13, 2, 4, 'Tamar, nora de Judá, lhe deu à luz Pérez e Zerá. Ao todo os filhos de Judá foram cinco.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 5, 'Os filhos de Perez: Hezrom e Hamul:', 1, CURRENT_TIMESTAMP, false),
(13, 2, 6, 'Os filhos de Zerá: Zinri, Etã, Hemã, Calcol e Dara; cinco ao todo.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 7, 'Os filhos de Carmi: Acar, o perturbador de Israel, que pecou no anátema.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 8, 'De Etã foi filho Azarias.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 9, 'Os filhos que nasceram a Hezrom: Jerameel, Rão e Quelubai.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 10, 'Rão foi pai de Aminadabe, e Aminadabe de Nasom, príncipe dos filhos de Judá;', 1, CURRENT_TIMESTAMP, false),
(13, 2, 11, 'Nason foi pai de Salmom, e Salmom de Boaz;', 1, CURRENT_TIMESTAMP, false),
(13, 2, 12, 'Boaz foi pai de Obede, e Obede de Jessé;', 1, CURRENT_TIMESTAMP, false),
(13, 2, 13, 'a Jessé nasceram Eliabe, seu primogênito, Abinadabe o segundo, Siméia o terceiro,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 14, 'Netanel o quarto, Radai o quinto,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 15, 'Ozen o sexto e Davi o sétimo;', 1, CURRENT_TIMESTAMP, false),
(13, 2, 16, 'e foram suas irmãs Zeruia e Abigail. Os filhos de Zeruia foram: Abisai, Joabe e Asael, três.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 17, 'Abigail deu à luz Amasa; o pai de Amasa foi Jeter, o ismaelita.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 18, 'A Calebe, filho de Hezrom, nasceram filhos de Azuba, sua mulher, e de Jeriote; e os filhos dela foram estes: Jeser, Sobabe e Ardom.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 19, 'Morreu Azuba; e Calebe tomou para si Efrata, da qual lhe nasceu Hur.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 20, 'Hur foi pai de îri, e îri de Bezaleel.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 21, 'Então Hezrom, tendo já sessenta anos, tomou por mulher a filha de Maquir, pai de Gileade; e conheceu-a, e ela lhe deu à luz Segube.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 22, 'Segube foi pai de Jair, o qual veio a ter vinte e três cidades na terra de Gileade.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 23, 'Mas Gesur e Arã tomaram deles Havote-Jair, e Quenate e suas aldeias, sessenta cidades. Todos estes foram filhos de Maquir, pai de Gileade.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 24, 'Depois da morte de Hezrom, em Calebe de Efrata, Abia, mulher de Hezrom, lhe deu Asur, pai de Tecoa.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 25, 'Os filhos de Jerameel, primogênito de Jezrom, foram: Rão, o primogênito, Buna, Orem, Ozem e Aías.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 26, 'Jerameel teve outra mulher, cujo nome era Atara, a qual foi mãe de Onã.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 27, 'Os filhos de Rão, primogênito de Jerameel, foram: Maaz, Jamim e Equer.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 28, 'Os filhos de Onã, foram: Samai e Jada; e os filhos de Samai: Nadabe e Abisur.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 29, 'O nome da mulher de Abisur era Abiail, que lhe deu à luz Abã e Molide.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 30, 'Os filhos de Nadabe: Selede e Apaim; e Selede morreu sem filhos.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 31, 'O filho de Apaim: Isi; o filho de Isi: Sesã; o filho de Sesã: Alai.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 32, 'Os filhos de Jada, irmão de Samai: Jeter e Jônatas; e Jeter morreu sem filhos.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 33, 'Os filhos de Jônatas: Pelete e Zaza. Esses foram os filhos de Jerameel.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 34, 'Sesã não teve filhos, mas filhas. E tinha Sesã um servo egípcio, cujo nome era Jará:', 1, CURRENT_TIMESTAMP, false),
(13, 2, 35, 'Deu, pois, Sesã sua filha por mulher a Jará, seu servo; e ela lhe deu à luz Atai.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 36, 'Atai foi pai de Natã, Natã de Zabade,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 37, 'Zabade de Eflal, Eflal de Obede,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 38, 'Obede de Jeú, Jeú de Azarias,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 39, 'Azarias de Helez, Helez de Eleasá,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 40, 'Eleasá de Sismai, Sismai de Salum,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 41, 'Salum de Jecamias, e Jecamias de Elisama.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 42, 'Os filhos de Calebe, irmão de Jerameel: Messa, seu primogênito, que foi o pai de Zife, e os filhos de Maressa, pai de Hebrom.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 43, 'Os filhos de Hebrom: Corá, Tapua, Requem e Sema.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 44, 'Sema foi pai de Raão, pai de Jorqueão; e Requem foi pai de Samai.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 45, 'O filho de Samai foi Maom; e Maom foi pai de Bete-Zur.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 46, 'Efá, a concubina de Calebe, teve Harã, Moza e Gazez; e Harã foi pai de Gazez.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 47, 'Os filhos de Jadai: Regem, Jotão, Gesã, Pelete, Efá e Saafe.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 48, 'Maacá, concubina de Calebe, deu à luz Seber e Tiraná.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 49, 'Deu à luz também Saafe, pai de Madmana, e Seva, pai de Macbena e de Gibeá; e a filha de Calebe foi Acsa.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 50, 'Estes foram os filhos de Calebe, filho de Hur, o primogênito de Efrata: Sobal, pai de Quiriate-Jearim,', 1, CURRENT_TIMESTAMP, false),
(13, 2, 51, 'Salma, pai de Belém, e Harefe, pai de Bete-Gader.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 52, 'Os filhos de Sobal, pai de Quiriate-Jearim, foram: Haroé e metade dos menuotes.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 53, 'As famílias de Quiriate-Jearim: os itreus, os puteus, os sumateus e os misraeus; destes saíram os zorateus e os estaloeus.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 54, 'Os filhos de Salma: Belém, os netofatitas, Atarote-Bete-Joabe, metade dos manaatitas e os zoritas.', 1, CURRENT_TIMESTAMP, false),
(13, 2, 55, 'As famílias dos escribas que habitavam em Jabes: os tiratitas, os simeatitas e os sucatitas; estes são os queneus que descenderam de Hamate, pai da casa de Recabe.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 1, 'Estes foram os filhos de Davi que lhe nasceram em Hebrom: o primogênito Amnom, de Ainoã, a jizreelita; o segundo Daniel, de Abigail, a carmelita;', 1, CURRENT_TIMESTAMP, false),
(13, 3, 2, 'O terceiro Absalão, filho de Maacá, filha de Talmai, rei de Gesur; o quarto Adonias, filho de Hagite;', 1, CURRENT_TIMESTAMP, false),
(13, 3, 3, 'O quinto Sefatias, de Abital; o sexto Itreão, de Eglá, sua mulher.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 4, 'Seis lhe nasceram em Hebrom, onde reinou sete anos e seis meses; e reinou trinta e três anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 5, 'Estes lhe nasceram em Jerusalém: Siméia, Sobabe, Natã e Salomão; estes quatro lhe nasceram de Bate-Sua, filha de Amiel.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 6, 'Nasceram-lhe mais: Ibar, Elisama, Elifelete,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 7, 'Nogá, Nefegue, Jafia,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 8, 'Elisama, Eliadá e Elifelete, nove.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 9, 'Todos estes foram filhos de Davi, afora os filhos das concubinas; e Tamar foi irmã deles.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 10, 'Filho de Salomão foi Roboão, de quem foi filho Abias, de quem foi filho Asa, de quem foi filho Jeosafá,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 11, 'de quem foi filho Jorão, de quem foi filho Acazias, de quem foi filho Joás,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 12, 'de quem foi filho Amazias, de quem foi filho Jotão,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 13, 'de quem foi filho Acaz, de quem foi filho Ezequias, de quem foi filho Manassés,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 14, 'de quem foi filho Amom, e de quem foi filho Josias.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 15, 'Os filhos de Josias: o primogênito Joanã, o segundo Jeoiaquim, o terceiro Zedequias, o quarto Salum.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 16, 'Os filhos de Jeoiaquim: Jeconias, seu filho, e Zedequias, seu filho.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 17, 'Os filhos de Jeconias, o deportado: Sealtiel, seu filho,', 1, CURRENT_TIMESTAMP, false),
(13, 3, 18, 'Malquirão, Pedaías, Senazar, Jecamias, Hosama e Nedabias.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 19, 'Os filhos de Pedaías: Zorobabel e Simei; e os filhos de Zorobabel: Mesulão e Hananias, e Selomite, irmã destes;', 1, CURRENT_TIMESTAMP, false),
(13, 3, 20, 'e Hasubá, Oel, Berequias, Hasadias e Jusabe-Hesede, cinco.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 21, 'Hananias foi pai de Pelatias; Pelatias de Jesaías; Jesaías de Refaías; Refaías de Arnã; Arnã de Obadias; e Obadias de Secanias.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 22, 'Os filhos de Secanias: Semaías e os filhos deste: Hatus, Igal, Bariá, Nearias e Safate, seis.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 23, 'Os filhos de Nearias: Elioenai, Ezequias e Azricão, três.', 1, CURRENT_TIMESTAMP, false),
(13, 3, 24, 'E os filhos de Elioenai: Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías e Anani, sete.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 1, 'Os filhos de Judá: Pérez, Hezrom, Carmi, Hur e Sobal.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 2, 'Reaías, filho de Sobal, foi pai de Jaate, e Jaate de Aümai e Laade; estas são as famílias dos zoratitas.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 3, 'Estes foram os filhos de Etã: Jizreel, Ismá, e Idbás; e o nome da irmã deles era Hazelelponi;', 1, CURRENT_TIMESTAMP, false),
(13, 4, 4, 'e mais Penuel, pai de Gedor, e Ézer, pai de Husá; estes foram os filhos de Hur, o primogênito de Efrata, pai de Belém.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 5, 'Asur, pai de Tecoa, tinha duas mulheres: Helá e Naará.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 6, 'Naará deu-lhe à luz Aüzão, Hefer, Temêni e Haastári; estes foram os filhos de Naará.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 7, 'E os filhos de Helá: Zerete, Izar e Etnã.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 8, 'Coz foi pai de Anube e Zobeba, e das famílias de Acarel, filho de Harum.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 9, 'Jabes foi mais ilustre do que seus irmãos {sua mãe lhe pusera o nome de Jabes, dizendo: Porquanto com dores o dei à luz}..', 1, CURRENT_TIMESTAMP, false),
(13, 4, 10, 'Jabes invocou o Deus de Israel, dizendo: Oxalá que me abençoes, e estendas os meus termos; que a tua mão seja comigo e faças que do mal eu não seja afligido! E Deus lhe concedeu o que lhe pedira.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 11, 'Quelube, irmão de Suá, foi pai de Meir; e este foi pai de Estom.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 12, 'Estom foi pai de Bete-Rafa, Paséia e Teína, que foi pai de Ir-Naás; estes foram os homens, de Reca.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 13, 'Os filhos de Quenaz: Otniel e Seraías; e Otniel foi pai de Hatate', 1, CURRENT_TIMESTAMP, false),
(13, 4, 14, 'e Meonotai, que foi pai de Ofra; Seraías foi pai de Joabe, fundador de Ge-Harasim, cujos habitantes foram artífices.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 15, 'Os filhos de Calebe, filho de Jefoné: Íru, Elá e Naã; e Elá foi pai de Quenaz:', 1, CURRENT_TIMESTAMP, false),
(13, 4, 16, 'Os filhos de Jealelel: Zife, Zifá, Tíria e Asareel.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 17, 'Os filhos de Ezra: Jeter, Merede, Efer e Jalom; e ela deu à luz Miriã, Samai, e Isbá, pai de Estemoa,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 18, 'cuja mulher judia deu à luz Jerede, pai de Gedor, Heber, pai de Socó, e Jecutiel, pai de Zanoa; e estes foram os filhos de Bitia, filha de Faraó, que Merede tomou.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 19, 'Os filhos da mulher de Hodias, irmã de Naã, foram os pais de Queila, o garmita, e Estemoa, o maacatita.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 20, 'Os filhos de Simão: Amnom, Rina, Bene-Hanã e Tilom; e os filhos de Isi: Zoete e Bene-Zoete.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 21, 'Os filhos de Selá, filho de Judá: Er, pai de Leca, Lada, pai de Maressa, e as famílias da casa dos que fabricavam linho, em Bete-Asbéia;', 1, CURRENT_TIMESTAMP, false),
(13, 4, 22, 'como também Joquim, e os homens de Cozeba, e Joás e Sarafe, os quais dominavam sobre Moabe, e Jasúbi-Leém. {Estes registros são antigos.}', 1, CURRENT_TIMESTAMP, false),
(13, 4, 23, 'Estes foram os oleiros, os habitantes de Netaim e de Gedera; e moravam ali com o rei para o seu serviço.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 24, 'Os filhos de Simeão: Nemuel, Jamim, Jaribe, Zerá e Saul,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 25, 'de quem foi filho Salum, de quem foi filho Mibsão, de quem foi filho Misma.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 26, 'Os filhos de Misma: Jamuel, seu filho, de quem foi filho Zacur, de quem foi filho Simei.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 27, 'Simei teve dezesseis filhos e seis filhas; porém seus irmãos não tiveram muitos filhos, nem se multiplicou toda a sua família tanto como as dos filhos de Judá.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 28, 'Eles habitaram em Berseba, Molada, Hazar-Sual,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 29, 'Bila, Ezem, Tolade,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 30, 'Betuel, Horma, Ziclague,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 31, 'Bete-Marcabote, Hazar-Susim, Bete-Biri e Saraim; essas foram as suas cidades até o reinado de Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 32, 'As suas aldeias foram: Etã, Aim, Rimom, Toquem e Asã, cinco cidades,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 33, 'com todas as suas aldeias, que estavam em redor destas cidades, até Baal. Estas foram as suas habitações e as suas genealogias.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 34, 'Ora, Mesobabe, Jamleque, Josa, filho de Amazias,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 35, 'Joel, Jeú, filho de Josibias, filho de Seraías, filho de Asiel,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 36, 'Elioenai, Jaacobá, Jesoaías, Asaías, Adiel, Jesimiel, Benaías,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 37, 'e Ziza, filho de Sifi, filho de Alom, filho de Jedaías, filho de Sínri, filho de Semaías', 1, CURRENT_TIMESTAMP, false),
(13, 4, 38, 'estes, registrados por nome, foram príncipes nas suas famílias; e as famílias de seus pais se multiplicaram grandemente.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 39, 'Chegaram até a entrada de Gedor, ao lado oriental do vale, em busca de pasto para os seus rebanhos;', 1, CURRENT_TIMESTAMP, false),
(13, 4, 40, 'e acharam pasto abundante e bom, e a terra era espaçosa, quieta e pacífica; pois os que antes habitavam ali eram descendentes de Cam.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 41, 'Estes que estão inscritos por nome, vieram nos dias de Ezequias, rei de Judá, e destruíram as tendas e os meunins que se acharam ali, e os exterminaram totalmente até o dia de hoje, e habitaram em lugar deles; porque ali havia pasto para os seus rebanhos.', 1, CURRENT_TIMESTAMP, false),
(13, 4, 42, 'Também deles, isto é, dos filhos de Simeão, quinhentos homens foram ao monte Seir, tendo por capitães Pelatias, Nearias, Refaías e Uziel, filhos de Isi,', 1, CURRENT_TIMESTAMP, false),
(13, 4, 43, 'e, matando o restante dos amalequitas, que havia escapado, ficaram habitando ali até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 1, 'Quanto aos filhos de Rúben, o primogênito de Israel {pois ele era o primogênito; mas, porquanto profanara a cama de seu pai, deu-se a sua primogenitura aos filhos de José, filho de Israel, de sorte que a sua genealogia não é contada segundo o direito da primogenitura;}', 1, CURRENT_TIMESTAMP, false),
(13, 5, 2, '{pois Judá prevaleceu sobre seus irmãos, e dele proveio o príncipe; porém a primogenitura foi de José};', 1, CURRENT_TIMESTAMP, false),
(13, 5, 3, 'os filhos de Rúben o primogênito de Israel: Hanoque, Palu, Hezrom e Carmi.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 4, 'Os filhos de Joel: Semaías, de quem foi filho Gogue, de quem foi filho Simei,', 1, CURRENT_TIMESTAMP, false),
(13, 5, 5, 'de quem foi filho Mica, de quem foi filho Reaías, de quem foi filho Baal,', 1, CURRENT_TIMESTAMP, false),
(13, 5, 6, 'de quem foi filho Beera, a quem Tilgate-Pilneser levou cativo; ele foi príncipe dos rubenitas.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 7, 'E seus irmãos, pelas suas famílias, quando se fez a genealogia das suas gerações, foram: o chefe Jeiel, Zacarias,', 1, CURRENT_TIMESTAMP, false),
(13, 5, 8, 'Belá, filho de Azaz, filho de Sema, filho de Joel, que habitou em Aroer até Nebo e Baal-Meom;', 1, CURRENT_TIMESTAMP, false),
(13, 5, 9, 'ao oriente habitou até a entrada do deserto, desde o rio Eufrates; porque seu gado se tinha multiplicado na terra de Gileade.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 10, 'E nos dias de Saul fizeram guerra aos hagarenos, que caíram pela sua mão; e eles habitaram nas suas tendas em toda a região oriental de Gileade.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 11, 'E os filhos de Gade habitaram defronte deles na terra de Basã, até Salca:', 1, CURRENT_TIMESTAMP, false),
(13, 5, 12, 'o chefe Joel, Safã o segundo, Janai e Safate em Basã,', 1, CURRENT_TIMESTAMP, false),
(13, 5, 13, 'e seus irmãos, segundo as suas casas paternas: Micael, Mesulão, Sebá, Jorai, Jacã, Ziá e Eber, sete.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 14, 'Estes foram os filhos de Abiail, filho de Huri, filho de Jaroá, filho de Gileade, filho de Micael, filho de Jesisai, filho de Jado, filho de Buz;', 1, CURRENT_TIMESTAMP, false),
(13, 5, 15, 'Aí, filho de Abdiel, filho de Guni, chefe das casas paternas.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 16, 'E habitaram em Gileade, em Basã, e nas suas aldeias, como também em todos os arrabaldes de Sarom até os seus termos.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 17, 'Todos estes foram registrados, segundo as suas genealogias, nos dias de Jotão, rei de Judá, e nos dias de Jeroboão, rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 18, 'Os rubenitas, os gaditas, e a meia tribo de Manassés tinham homens valentes, que traziam escudo e espada e entesavam o arco, e que eram destros na guerra, quarenta e quatro mil setecentos e sessenta, que saíam à peleja.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 19, 'Fizeram guerra aos hagarenos, bem como a Jetur, a Nafis e a Nodabe,', 1, CURRENT_TIMESTAMP, false),
(13, 5, 20, 'e foram ajudados contra eles, de sorte que os hagarenos e todos quantos estavam com eles foram entregues em sua mão; porque clamaram a Deus na peleja, e ele lhes deu ouvidos, porquanto confiaram nele.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 21, 'E levaram o gado deles: cinqüenta mil camelos, duzentos e cinqüenta mil ovelhas e dois mil jumentos; e também cem mil homens,', 1, CURRENT_TIMESTAMP, false),
(13, 5, 22, 'pois muitos caíram mortos, porque de Deus era a peleja; e ficaram habitando no lugar deles até o cativeiro.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 23, 'Os filhos da meia tribo de Manassés habitaram naquela terra; e multiplicaram-se desde Basã até Baal-Hermom, Senir, e o monte Hermom.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 24, 'E estes foram os cabeças de suas casas paternas, a saber: Efer, Isi, Eliel, Azriel, Jeremias, Hodavias e Jadiel, homens valentes, homens de nome, e chefes das suas casas paternas.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 25, 'Cometeram, porém, transgressões contra o Deus de seus pais, e se prostituíram, seguindo os deuses dos povos da terra, os quais Deus destruíra de diante deles.', 1, CURRENT_TIMESTAMP, false),
(13, 5, 26, 'Pelo que o Deus de Israel excitou o espírito de Pul, rei da Assíria, e o espírito de Tilgate-Pilneser, rei da Assíria, que os levaram cativos, a saber: os rubenitas, os gaditas, e a meia tribo de Manassés; e os transportaram para Hala, Habor, Hara, e para o rio de Gozã, onde estão até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 1, 'Os filhos de Levi: Gérson, Coate e Merári.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 2, 'Os filhos de Coate: Anrão, Izar, Hebrom e Uziel.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 3, 'Os filhos de Anrão: Arão, Moisés e Miriã; e os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 4, 'Eleazar foi pai de Finéias, Finéias de Abisua,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 5, 'Abisua de Buqui, Buqui de Uzi,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 6, 'Uzi de Zeraías, Zeraías de Meraiote,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 7, 'Meraiote de Amarias, Amarias de Aitube,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 8, 'Aitube de Zadoque, Zadoque de Aimaaz,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 9, 'Aimaaz de Azarias, Azarias de Joanã,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 10, 'Joanã de Azarias, que exerceu o sacerdócio na casa que Salomão edificou em Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 11, 'Azarias foi pai de Amarias, Amarias de Aitube,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 12, 'Aitube de Zadoque, Zadoque de Salum,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 13, 'Salum de Hilquias, Hilquias de Azarias,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 14, 'Azarias de Seraías, Seraías de Jeozadaque;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 15, 'e Jeozadaque foi levado cativo quando o Senhor levou em cativeiro Judá e Jerusalém por intermédio de Nabucodonosor.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 16, 'Os filhos de Levi: Gérson, Coate e Merári.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 17, 'Estes são os nomes dos filhos de Gérson: Líbni e Simei.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 18, 'Os filhos de Coate: Anrão, Izar, Hebrom e Uziel.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 19, 'Os filhos de Merári: Mali e Musi. Estas são as famílias dos levitas, segundo as casas de seus pais.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 20, 'De Gérson: Líbni, de quem foi filho Jaate, de quem foi filho Zima,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 21, 'de quem foi filho Joá, de quem foi filho Ido, de quem foi filho Zerá, de quem foi filho Jeaterai:', 1, CURRENT_TIMESTAMP, false),
(13, 6, 22, 'Os filhos de Coate: Aminadabe, de quem foi filho Corá, de quem foi filho Assir,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 23, 'de quem foi filho Elcana, de quem foi filho Ebiasafe, de quem foi filho Assir,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 24, 'de quem foi filho Taate, de quem foi filho Uriel, de quem foi filho Uzias, de quem foi filho Saul.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 25, 'Os filhos de Elcana: Amasai e Aimote,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 26, 'de quem foi filho Elcana, de quem foi filho Zofai, de quem foi filho Naate,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 27, 'de quem foi filho Eliabe, de quem foi filho Jeroão, de quem foi filho Elcana.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 28, 'E os filhos de Samuel: Joel, seu primogênito, e Abias, o segundo.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 29, 'Os filhos de Merári: Mali, de quem foi filho Líbni, de quem foi filho Simei, de quem foi filho Uzá,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 30, 'de quem foi filho Siméia, de quem foi filho Hagias, de quem foi filho Asaías.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 31, 'Estes são os que Davi constituiu sobre o serviço de canto da casa do Senhor, depois: que a arca teve repouso.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 32, 'Ministravam com cântico diante do tabernáculo da tenda da revelação, até que Salomão edificou a casa do Senhor em Jerusalém; e exerciam o seu ministério segundo a sua ordem.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 33, 'São estes: pois, os que ali estavam com seus filhos: dos filhos dos coatitas, Hemã, o cantor, filho de Joel, filho de Samuel,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 34, 'filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 35, 'filho de Zufe, filho de Elcana:, filho de Maate, filho de Amasai,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 36, 'filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 37, 'filho de Taate, filho de Assir, filho de Ebiasafe, filho de Corá,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 38, 'filho de Izar, filho de Coate, filho de Levi, filho de Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 39, 'E seu irmão Asafe estava à sua direita; e era Asafe filho de Berequias, filho de Siméia,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 40, 'filho de Micael, filho de Baaséias, filho de Malquias,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 41, 'filho de Etni, filho de Zerá, filho de Adaías,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 42, 'filho de Etã, filho de Zima, filho de Simei,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 43, 'filho de Jaate, filho de Gérson, filho de Levi.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 44, 'E à esquerda estavam seus irmãos, os filhos de Merári: Etã, filho de Quísi, filho de Abdi, filho de Maluque,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 45, 'filho de Hasabias, filho de Amazias, filho de Hilquias,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 46, 'filho de Anzi, filho de Bani, filho de Semer,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 47, 'filho de Mali, filho de Musi, filho de Merári, filho de Levi.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 48, 'Mas Arão e seus irmãos, os levitas, foram designados para todo o serviço do tabernáculo da casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 49, 'Mas Arão e seus filhos ofereciam os sacrifícios sobre o altar do holocausto e o incenso sobre o altar do incenso, para todo o serviço do lugar santíssimo, e para fazer expiação a favor de Israel, conforme tudo quanto Moisés, servo de Deus, havia ordenado:', 1, CURRENT_TIMESTAMP, false),
(13, 6, 50, 'Estes foram os filhos de Arão: Eleazar, de quem foi filho Finéias, de quem foi filho Abisua,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 51, 'de quem foi filho Buqui, de quem foi filho Uzi, de quem foi filho Zeraías,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 52, 'de quem foi filho Meraiote, de quem foi filho Amarias, de quem foi filho Aitube,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 53, 'de quem foi filho Zadoque, de quem foi filho Aimaaz.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 54, 'Ora, estas foram as suas habitações, segundo os seus acampamentos nos seus termos, a saber: aos filhos de Arão, das famílias dos coatitas {porque lhes caiu a primeira sorte},', 1, CURRENT_TIMESTAMP, false),
(13, 6, 55, 'deram-lhes Hebrom, na terra de Judá, e os campos que a rodeiam;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 56, 'porém os campos da cidade e as suas aldeias, deram-nos a Calebe, filho de Jefone.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 57, 'E aos filhos de Arão deram as cidades de refúgio: Hebrom, Libna e seus campos, Jatir, Estemoa e seus campos,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 58, 'Hilem e seus campos, Debir e seus campos,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 59, 'Asã e seus campos, Bete-Senues e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 60, 'e da tribo de Benjamim: Geba e seus campos, Alemete e seus campos, Anatote e seus campos; todas as suas cidades, pelas suas famílias, foram treze.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 61, 'Mas aos filhos de Coate, aos restantes da família da tribo, por sorte caíram dez cidades da meia tribo, da metade de Manassés;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 62, 'aos filhos de Gérsom segundo as suas famílias, cairam treze cidades das tribos de Issacar, Aser, Naftali e Manassés, em Basã;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 63, 'e aos filhos de Merári, segundo as suas famílias, por sorte caíram doze cidades das tribos de Rúben Gade e Zebulom.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 64, 'Assim os filhos de Israel deram aos levitas estas cidades e seus campos.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 65, 'Deram-lhes por sorte, da tribo dos filhos de Judá, da tribo dos filhos de Simeão, e da tribo dos filhos de Benjamim, estas cidades que são mencionadas nominalmente.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 66, 'Algumas das famílias dos filhos de Coate receberam da tribo de Efraim cidades de seus termos.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 67, 'Deram-lhes as cidades de refúgio: Siquém e seus campos, na região montanhosa de Efraim, como também Gezer e seus campos.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 68, 'Jocmeão e seus campos, Bete-Horom e seus campos,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 69, 'Aijalom e seus campos, e Gate-Rimom e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 70, 'e da meia tribo de Manassés, Aner e seus campos, e Bileã e seus campos, deram-nos aos restantes da família dos filhos de Coate.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 71, 'Aos filhos de Gérson deram, da família da meia tribo de Manassés, Golã, em Basã, e seus campos, e Astarote e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 72, 'e da tribo de Issacar: Quedes e seus campos, Daberate e seus campos,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 73, 'Ramote e seus campos, e Aném e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 74, 'e da tribo de Aser: Masal e seus campos, Abdom e seus campos,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 75, 'Hucoque e seus campos, e Reobe e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 76, 'e da tribo de Naftali: Quedes, em Galiléia, e seus campos, Hamom e seus campos, e Quiriataim e seus campos.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 77, 'Aos restantes dos filhos de Merári deram, da tribo de Zebulom, Rimono e seus campos, Tabor e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 78, 'e dalém do Jordão, na altura de Jericó, ao oriente do Jordão, deram, da tribo de Rúben Bezer, no deserto, e seus campos, Jaza e seus campos,', 1, CURRENT_TIMESTAMP, false),
(13, 6, 79, 'Quedemote e seus campos, e Mefaate e seus campos;', 1, CURRENT_TIMESTAMP, false),
(13, 6, 80, 'e da tribo de Gade, Ramote, em Gileade, e seus campos, Maanaim e seus campos.', 1, CURRENT_TIMESTAMP, false),
(13, 6, 81, 'Hesbom e seus campos, e Jazer e seus campos.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 1, 'Os filhos de Issacar foram: Tola, Pua, Jasube e Sinrom, quatro.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 2, 'Os filhos de Tola: Uzi, Refaias, Jeriel, Jamai, lbsão e Semuel, chefes das suas casas paternas, da linhagem de Tola, homens valentes nas suas gerações; o seu número nos dias de Davi foi de vinte e dois mil e seiscentos.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 3, 'Os filhos de Uzi: Izraías e mais os filhos de Izraías: Micael, Obadias, Joel e Issijá, cinco, todos eles chefes.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 4, 'E houve com eles, nas suas gerações, segundo as suas casas paternas, em tropas de gente de guerra, trinta e seis mil; pois tiveram muitas mulheres e filhos.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 5, 'E seus irmãos, em todas as famílias de Issacar, varões valentes, todos contados pelas suas genealogias, foram oitenta e sete mil.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 6, 'Os filhos de Benjamim: Beiá, Bequer e Jediael, três.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 7, 'Os filhos de Belá: Ezbom, Uzi, Uziel; Jerimote e Iri, cinco chefes de casas paternas, homens valentes, os quais foram contados pelas suas genealogias vinte e dois:', 1, CURRENT_TIMESTAMP, false),
(13, 7, 8, 'Os filhos de Bequer: Zemira, Joás, Eliézer, Elioenai, Onri, Jerimote, Abias, Anatote e Alemete; todos estes foram filhos de Bequer.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 9, 'E foram contados pelas suas genealogias, segundo as suas gerações, chefes das suas casas paternas, homens valentes, vinte mil e duzentos.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 10, 'Os filhos de Jediael: Bilã, e mais os filhos de Bilã: Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis e Aisaar.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 11, 'Todos estes filhos de Jediael, segundo os chefes das casas paternas, homens valentes, foram dezessete mil e duzentos, que podiam sair no exército à peleja.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 12, 'E também Supim, e Hupim, os filhos de Ir, com Husim, o filho de Aer.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 13, 'Os filhos de Naftali: Jaziel, Guni, Jezer e salum, filho de Bila.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 14, 'Os filhos de Manassés: Asriel, que teve da sua mulher; a sua concubina, a sira, teve a Maquir, pai de Gileade;', 1, CURRENT_TIMESTAMP, false),
(13, 7, 15, 'e Maquir tomou mulheres para Hupim e Supim; a irmã dele se chamava Maacar. Foi o nome do segundo Zelofeade; e Zelofeade teve filhas.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 16, 'Maacá, mulher de Maquir, teve um filho, e chamou o seu nome Peres, e o nome de seu irmão foi Seres; e foram seus filhos: Ulão e Raquém.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 17, 'De Ulão foi filho Beda. Esses foram os filhos de Gileade, filho de Maquir, filho de Manassés.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 18, 'Sua irmã Hamolequete teve Isode, Abiezer e Maclá.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 19, 'E foram os filhos de Semida: Aiã, Siquém, Líqui e Anião. que', 1, CURRENT_TIMESTAMP, false),
(13, 7, 20, 'Os filhos de Efraim: Sutela, de quem foi filho Berede, de quem foi filho Taate, de quem foi filho Eleadá, de quem foi filho Taate,', 1, CURRENT_TIMESTAMP, false),
(13, 7, 21, 'de quem foi filho Zabade, de quem foi filho Sutela; e Ezer e Eleade, aos quais os homens de Tate, naturais da terra, mataram, por terem descido para tomar o seu gado.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 22, 'E Efraim, seu pai, os pranteou por muitos dias, pelo que seus irmãos vieram para o consolar.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 23, 'Depois juntou-se com sua mulher, e concebendo ela, teve um filho, ao qual ele deu o nome de Berias, porque as coisas iam mal na sua casa.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 24, 'Sua filha foi Seerá, que edificou a Bete-Horom, a baixa e a alta, como também a Uzem-Seerá.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 25, 'Foi seu filho Refa, como também Resefe, de quem foi filho Tela, de quem foi filho Taã,', 1, CURRENT_TIMESTAMP, false),
(13, 7, 26, 'de quem foi filho Ladã, de quem foi filho Amiúde, de quem foi filho Elisama,', 1, CURRENT_TIMESTAMP, false),
(13, 7, 27, 'de quem foi filho Num, de quem foi filho Josué:', 1, CURRENT_TIMESTAMP, false),
(13, 7, 28, 'Ora, as suas possessões e as suas habitações foram Betel e suas aldeias, e ao oriente Naarã, e ao ocidente Gezer e suas aldeias, e Siquém e suas aldeias, até Gaza e suas aldeias;', 1, CURRENT_TIMESTAMP, false),
(13, 7, 29, 'e da banda dos filhos de Manassés, Bete-Seã e suas aldeias, Taanaque e suas aldeias, Megido e suas aldeias, e Dor e suas aldeias. Nesses lugares habitaram os filhos de José, filho de Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 30, 'Os filhos de Aser: Imná, Isvá, Isvi, Berias e Sera, irmã deles:', 1, CURRENT_TIMESTAMP, false),
(13, 7, 31, 'Os filhos de Berias: Heber e Malquiel; este foi o pai de Birzavite.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 32, 'Heber foi pai de Jaflete, Somer, Hotão e Suá, irmã deles.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 33, 'Os filhos de Jaflete: Pasaque, Bimal e Asvate; esses foram os filhos de Jaflete.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 34, 'Os filhos de Semer: Aí, Roga, Jeubá e Arã:', 1, CURRENT_TIMESTAMP, false),
(13, 7, 35, 'Os filhos de seu irmão Helem: Zofa, Imna, Seles e Amal.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 36, 'Os filhos de Zofa: Suá, Harnefer, Sual, Beri, Inra,', 1, CURRENT_TIMESTAMP, false),
(13, 7, 37, 'Bezer, Hode, Samá, Silsa, Itrã e Beera.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 38, 'Os filhos de Jeter: Jefoné, Pispa e Ara.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 39, 'Os filhos de Ula: Ará, Haniel e Rízia.', 1, CURRENT_TIMESTAMP, false),
(13, 7, 40, 'Todos esses foram filhos de Aser, chefes das casas paternas, homens escolhidos e valentes, chefes dos príncipes; e o número deles, contados segundo as suas genealogias para o serviço de guerra, foi vinte e seis mil homens.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 1, 'Benjamim foi pai de Belá, seu primogênito, de Asbel o segundo, e de Aará o terceiro,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 2, 'de Noá o quarto, e de Rafa o quinto.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 3, 'Belá teve estes filhos: Adar, Gêra, Abiúde,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 4, 'Abisua, Naamã, Aoá,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 5, 'Gêra, Sefufã e Hurão.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 6, 'Estes foram os filhos de Eúde, que foram os chefes das casas paternas dos habitantes de Geba, e que foram levados cativos para Manaate;', 1, CURRENT_TIMESTAMP, false),
(13, 8, 7, 'Naamã, Aías e Gêra; este os transportou; foi ele pai de Uzá e Aiúde.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 8, 'Saaraim teve filhos na terra de Moabe, depois que despedira Husim e Baara, suas mulheres.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 9, 'E de Hodes, sua mulher, teve Jobabe, Zíbia, Messa, Malcã,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 10, 'Jeuz, Saquias e Mirma; esses foram seus filhos:, chefes de casas paternas:', 1, CURRENT_TIMESTAMP, false),
(13, 8, 11, 'De Husim teve Abitube e Elpaal.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 12, 'Os filhos de Elpaal: Eber, Misã, Semede {este edificou Ono e Lode e suas aldeias},', 1, CURRENT_TIMESTAMP, false),
(13, 8, 13, 'Berias e Sema {estes foram chefes de casas paternas dos habitantes de Aijalom, os quais afugentaram os habitantes de Gatel ,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 14, 'Aiô, Sasaque e Jerimote.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 15, 'Zebadias, Arade, Eder,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 16, 'Micael, Ispá e Joá foram filhos de Berias;', 1, CURRENT_TIMESTAMP, false),
(13, 8, 17, 'Zebadias, Mesulão, Hizqui, Heber,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 18, 'Ismerai, Izlias e Jobabe foram filhos de Elpaal;', 1, CURRENT_TIMESTAMP, false),
(13, 8, 19, 'Jaquim, Zicri, Zabdi,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 20, 'Elienai, Ziletai, Eliel,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 21, 'Adaías, Beraías e Sinrate foram filhos de Simei;', 1, CURRENT_TIMESTAMP, false),
(13, 8, 22, 'Ispã, Eber, Eliel,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 23, 'Abdom, Zicri, Hanã,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 24, 'Hananias, Elão, Antotias,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 25, 'Ifdéias e Penuel foram filhos de Sasaque;', 1, CURRENT_TIMESTAMP, false),
(13, 8, 26, 'Sanserai, Searias, Atalias,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 27, 'Jaaresias, Elias e Zicri foram filhos de Jeroão.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 28, 'Estes foram chefes de casas paternas, segundo as suas gerações, homens principais; e habitaram em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 29, 'E em Gibeão habitaram o pai de Gibeão, cuja mulher se chamava Maacá,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 30, 'e seu filho primogênito Abdom, depois Zur, Quiz, Baal, Nadabe,', 1, CURRENT_TIMESTAMP, false),
(13, 8, 31, 'Gedor, Aiô, Zequer e Miclote.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 32, 'Miclote foi pai de Siméia; também estes habitaram em Jerusalém defronte de seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 33, 'Ner foi pai de Quis, e Quis de Saul; Saul foi pai de Jônatas, Malquisua, Abinadabe e Es-Baal.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 34, 'Filho de Jônatas foi Meribe-Baal; e Meribe-Baal foi pai de Mica.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 35, 'Os filhos de Mica foram: Pitom, Meleque, Tareá e Acaz.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 36, 'Acaz foi pai de Jeoada; Jeoada foi pai de Alemete, Azmavete e Zinri; Zinri foi pai de Moza;', 1, CURRENT_TIMESTAMP, false),
(13, 8, 37, 'Moza foi pai de Bineá, de quem foi filho Rafa, de quem foi filho Eleasá, de quem foi filho Azel.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 38, 'Azel teve seis filhos, cujos nomes foram: Azricão, Bocru, Ismael, Searias, Obadias e Hanã; todos estes foram filhos de Azel.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 39, 'Os filhos de Eseque, seu irmão: Ulão, seu primogênito, Jeús o segundo, e Elifelete o terceiro.', 1, CURRENT_TIMESTAMP, false),
(13, 8, 40, 'Os filhos de Ulão foram homens heróis, valentes, e flecheiros destros; e tiveram muitos filhos, e filhos de filhos, cento e cinqüenta. Todos estes foram dos filhos de Benjamim.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 1, 'Todo o Israel, pois, foi arrolado por genealogias, que estão inscritas no livro dos reis de Israel; e Judá foi transportado para Babilônia, por causa da sua infidelidade.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 2, 'Ora, os primeiros a se restabelecerem nas suas possessões e nas suas cidades foram de Israel, os sacerdotes, os levitas, e os netinins.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 3, 'E alguns dos filhos de Judá, de Benjamim, e de Efraim e Manassés, habitaram em Jerusalém:', 1, CURRENT_TIMESTAMP, false),
(13, 9, 4, 'Utai, filho de Amiúde, filho de Onri, filho de Inri, filho de Bari, dos filhos de Pérez, filho de Judá;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 5, 'dos silonitas: Asaías o primogênito, e seus filhos;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 6, 'dos filhos de Zerá: Jeuel e seus irmãos, seiscentos e noventa;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 7, 'dos filhos de Benjamim: Salu, filho de Mesulão, filho de Hodavias, filho de Hassenua;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 8, 'Ibnéias, filho de Jeroão; Elá, filho de Uzi, filho de Mícri; Mesulão, filho de Sefatias, filho de Reuel, filho de Ibnijas;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 9, 'e seus irmãos, segundo as suas gerações, novecentos e cinqüenta e seis. Todos estes homens foram chefes de casas paternas, segundo as casas de seus pais.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 10, 'E dos sacerdotes: Jedaías, Jeoiaribe e Jaquim;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 11, 'Azarias, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote. filho de Aitube, regente da casa de Deus;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 12, 'Adaías, filho de Jeroão, filho de Pasur, filho de Malquias; Maasai, filho de Adiel, filho de Jazera, filho de Mesulão, filho de Mesilemite, filho de Imer;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 13, 'como também seus irmãos, chefes de suas casas paternas, mil setecentos e sessenta, homens capacitados para o serviço a casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 14, 'E dos levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, dos filhos de Merári:', 1, CURRENT_TIMESTAMP, false),
(13, 9, 15, 'Baquebacar, Heres, Galal, e Matanias, filho de Mica, filho de Zicri, filho de Asafe;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 16, 'Obadias, filho de Semaías, filho de Galal, filho de Jedútun; e Berequias, filho de Asa, filho de Elcana, morador das aldeias dos netofatitas.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 17, 'Foram porteiros: Salum, Acube, Talmom, Aimã, e seus irmãos, sendo Salum o chefe;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 18, 'e até aquele tempo estavam de guarda à porta do rei, que ficava ao oriente. Estes foram os porteiros para os arraiais dos filhos de Levi.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 19, 'Salum, filho de Coré, filho de Ebiasafe, filho de Corá, e seus irmãos da casa de seu pai, os coraítas estavam encarregados do serviço como guardas das entradas do tabernáculo, como seus pais também tinham sido encarregados do arraial do Senhor, sendo guardas da entrada.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 20, 'Finéias, filho de Eleazar, dantes era guia entre eles; e o Senhor era com ele.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 21, 'Zacarias, filho de Meselemias, guardava a porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 22, 'Todos estes, escolhidos para serem guardas das entradas, foram duzentos e doze; e foram contados por suas genealogias, nas suas aldeias. Davi e Samuel, o vidente, os constituíram nos seus respectivos cargos.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 23, 'Tinham, pois, eles e seus filhos o cargo das portas da casa do Senhor, a saber, da casa da tenda, como guardas.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 24, 'Os porteiros estavam aos quatro lados, ao oriente, ao ocidente, ao norte e ao sul:', 1, CURRENT_TIMESTAMP, false),
(13, 9, 25, 'Seus irmãos, que moravam nas suas aldeias, deviam de tempo em tempo vir por sete dias para servirem com eles.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 26, 'pois os quatro porteiros principais, que eram levitas, estavam encarregados das câmaras e dos tesouros da casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 27, 'E se alojavam à roda da casa de Deus. Porque a sua guarda lhes estava entregue, e tinham o encargo de abri-la cada manhã.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 28, 'Alguns deles estavam encarregados dos utensílios do serviço, pois estes por conta eram trazidos e por conta eram tirados.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 29, 'Outros estavam encarregados dos móveis e de todos os utensílios do santuário, como também da flor de farinha, do vinho, do azeite, do incenso e das especiarias.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 30, 'Os que confeccionavam as especiarias eram dos filhos dos sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 31, 'Matitias, um dos levitas, o primogênito de Salum, o coraíta, estava encarregado de tudo o que se cozia em sertãs.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 32, 'E seus irmãos, dentre os filhos dos coatitas, alguns tinham o cargo dos pães da proposição, para os prepararem de sábado em sábado.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 33, 'Estes são os cantores, chefes de casas paternas dos levitas, que moravam nas câmaras e estavam isentos de outros serviços, porque de dia e de noite se ocupavam naquele serviço.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 34, 'Estes foram chefes de casas paternas dos levitas, em suas gerações; e estes habitaram em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 35, 'Em Gibeão habitou Jeiel, pai de Hibeão {e era o nome de sua mulher Maacá};', 1, CURRENT_TIMESTAMP, false),
(13, 9, 36, 'seu filho primogênito foi Abdom; depois Zur, Quis, Baal, Ner, Nadabe,', 1, CURRENT_TIMESTAMP, false),
(13, 9, 37, 'Gedor, Aiô, Zacarias e Miclote.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 38, 'Miclote foi pai de Simeão; também estes habitaram em Jerusalém defronte d‰ seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 39, 'Ner foi pai de Quis; Quis de Saul; e Saul de Jônatas, Malquisua, Abinadabe e Es-Baal.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 40, 'Filho de Jônatas foi Meribe-Baal; Meribe-Baal foi pai de Mica.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 41, 'Os filhos de Mica: Pitom, Meleque, Tareá, e Acaz.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 42, 'Acaz foi pai de Jará; Jará foi pai de Alemete, Azmavete e Zinri; Zinri foi pai de Moza;', 1, CURRENT_TIMESTAMP, false),
(13, 9, 43, 'Moza foi pai de Bineá, de quem foi filho Refaías, de quem foi filho Eleasá, de quem foi filho Azel.', 1, CURRENT_TIMESTAMP, false),
(13, 9, 44, 'Azel teve seis filhos, cujos nomes são: Azricão, Bocru, Ismael, Searias, Obadias e Hanã; estes foram os filhos de Azel.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 1, 'Ora, os filisteus pelejaram contra Israel; e os homens de Israel, fugindo de diante dos filisteus, caíram mortos no monte Gilboa.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 2, 'Os filisteus perseguiram a Saul e seus filhos, e mataram Jônatas, Abinadabe e Malquisua, filhos de Saul.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 3, 'A peleja se agravou contra Saul, e os flecheiros o alcançaram, e ele foi ferido pelos flecheiros.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 4, 'Então disse Saul: Arranca a tua espada, e atravessa-me com ela, para que não venham estes incircuncisos e escarneçam de mim. Mas o seu escudeiro não quis, porque temia muito; então tomou Saul a sua espada, e se lançou sobre ela.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 5, 'Vendo, pois, o seu escudeiro que Saul estava morto, lançou-se também sobre sua espada, e morreu.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 6, 'Assim morreram Saul e seus três filhos; morreu toda a sua casa juntamente.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 7, 'Quando todos os homens de Israel que estavam no vale viram que Israel havia fugido, e que Saul eram mortos, abandonaram as suas cidades e fugiram, e vindo os filisteus, habitaram nelas.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 8, 'No dia seguinte, quando os filisteus vieram para despojar os mortos acharam Saul e seus filhos estirados no monte Gilboa.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 9, 'Então o despojaram, tomaram a sua cabeça e as suas armas, e enviaram mensageiros pela terra dos filisteus em redor, para levarem a boa nova a seus ídolos e ao povo.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 10, 'Puseram as armas dele na casa de seus deuses, e pregaram-lhe a cabeça na casa de Dagom.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 11, 'Quando, pois, toda a Jabes-Gileade ouviu tudo quanto os filisteus haviam feito a Saul,', 1, CURRENT_TIMESTAMP, false),
(13, 10, 12, 'todos os homens valentes se levantaram e, tomando o corpo de Saul e os corpos de seus filhos, trouxeram-nos: a Jabes; e sepultaram os seus ossos debaixo o terebinto em Jabes, e jejuaram sete dias.', 1, CURRENT_TIMESTAMP, false),
(13, 10, 13, 'Assim morreu Saul por causa da sua infidelidade para com o Senhor, porque não havia guardado a palavra do Senhor; e também porque buscou a adivinhadora para a consultar,', 1, CURRENT_TIMESTAMP, false),
(13, 10, 14, 'e não buscou ao Senhor; pelo que ele o matou, e transferiu o reino a Davi, filho de Jessé.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 1, 'Então todo o Israel se ajuntou a Davi em Hebron, dizendo: Eis que somos teus ossos e tua carne.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 2, 'Já dantes, quando Saul ainda era rei, eras tu o que fazias Israel sair, e entrar; também o Senhor teu Deus te disse: Tu apascentaras o meu povo Israel; tu serás príncipe sobre o meu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 3, 'Assim vieram todos os anciãos de Israel ao rei, a Hebrom; e Davi fez com eles um pacto em Hebrom, perante o Senhor; e ungiram a Davi rei sobre Israel, conforme a palavra do Senhor por intermédio de Samuel.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 4, 'Então Davi, com todo o Israel, partiu para Jerusalém , que é Jebus; e estavam ali os jebuseus, habitantes da terra.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 5, 'E disseram os habitantes de Jebus a Davi: Tu não entrarás aqui. Não obstante isso, Davi tomou a fortaleza de Sião, que é a cidade de Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 6, 'Davi disse: Qualquer que primeiro ferir os jebuseus será chefe e capitão. E Joabe, filho de Zeruia, subiu primeiro, pelo que foi feito chefe.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 7, 'Então Davi habitou na fortaleza, e por isso foi chamada cidade de Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 8, 'E edificou a cidade ao redor, desde Milo em diante; e Joabe reparou o resto da cidade.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 9, 'Davi tornava-se cada vez mais forte; porque o Senhor dos exércitos era com ele.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 10, 'São estes os chefes dos valentes de Davi, que o apoiaram fortemente no seu reino, com todo o Israel, para o fazerem rei, conforme a palavra do Senhor, no tocante a Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 11, 'Esta é a relação dos valentes de Davi: Jasobeão, filho dum hacmonita, o chefe dos trinta, o qual, brandindo a sua lança contra trezentos, duma só vez os matou.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 12, 'Depois dele, Eleazar, filho de Dodó, o aoíta; ele estava entre os três valentes.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 13, 'Este esteve com Davi em Pas-Damim, quando os filisteus ali se ajuntaram à peleja, onde havia um pedaço de campo cheio de cevada; e o povo fugia de diante dos filisteus.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 14, 'Mas eles se puseram no meio daquele campo, e o defenderam, e mataram os filisteus; e o Senhor os salvou com uma grande vitória.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 15, 'Três dos trinta chefes desceram à penha; a ter com Davi, na caverna de Adulão; e o exército dos filisteus estará acampado no vale de Refaim.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 16, 'Davi estava então no lugar forte, e a guarnição dos filisteus estava em Belém.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 17, 'E Davi, ofegante, exclamou: Quem me dera beber da água do poço de Belém, que está junto à porta!', 1, CURRENT_TIMESTAMP, false),
(13, 11, 18, 'Então aqueles três romperam pelo arraial dos filisteus, tiraram água do poço de Belém, que estava junto à porta, e a trouxeram a Davi; porém Davi não a quis beber, mas a derramou perante o Senhor,', 1, CURRENT_TIMESTAMP, false),
(13, 11, 19, 'dizendo: Não permita meu Deus que eu faça isso! Beberia eu o sangue da vida destes homens? Pois com perigo das suas vidas a trouxeram. Assim, não a quis beber. Isso fizeram aqueles três valentes.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 20, 'Abisai, irmão de Joabe, era o chefe dos três; o qual, brandindo a sua lança contra trezentos, os matou, e teve nome entre os três.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 21, 'Ele foi mais ilustre do que os outros dois, pelo que foi feito chefe deles; todavia não igualou aos primeiros três.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 22, 'Havia também Benaías, filho de Jeoiada, filho de um homem valente de Cabzeel, autor de grandes feitos; este matou dois filhos de Ariel de Moabe; depois desceu e matou um leão dentro duma cova, no tempo da neve.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 23, 'Matou também um egípcio, homem de grande altura, de cinco côvados. O egípcio tinha na mão uma lança como o órgão de tecelão; mas Benaías desceu contra ele com um cajado, arrancou-lhe da mão a lança e com ela o matou.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 24, 'Estas coisas fez Benaías, filho de Jeoiada, pelo que teve nome entre os três valentes.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 25, 'e o mais ilustre, contudo não igualou aos primeiros três; e Davi o pôs sobre os da sua guarda.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 26, 'Os valentes dos exércitos: Asael, irmão de Joabe; El-Hanã, filho de Dodó, de Belém;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 27, 'Samote, o harorita; Helez, o pelonita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 28, 'Ira, filho de Iques, o tecoíta; Abiezer, o anatotita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 29, 'Sibecai, o husatita; Ilai, o aoíta;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 30, 'Maarai, o netofatita; Helede, filho de Baaná, o netofatita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 31, 'Itai, filho de Ribai, de Gibeá, dos filhos de Benjamim; Benaías, o piratonita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 32, 'Hurai, dos ribeiros de Gaás; Abiel, o arbatita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 33, 'Azmavete, o baarumita; Eliabá, o saalbonita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 34, 'dos filhos de Hasem, o gizonita: Jônatas, filho de Sage, o hararita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 35, 'Aião, filho de Sacar, o hararita; Elifal, filho de Ur.', 1, CURRENT_TIMESTAMP, false),
(13, 11, 36, 'Hefer, o mequeratita; Aías, o pelonita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 37, 'Hezro, o carmelita; , Naarai, filho de Ebzai;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 38, 'Joel, irmão de Natã; Mibar, filho de Harri;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 39, 'Zeleque, o amonita; Naarai, o berotita, escudeiro de Joabe, filho de Zeniia;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 40, 'Ira, o itrita; Garebe, o itrita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 41, 'Urias, o heteu; Zabade, filho de Alai;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 42, 'Adina, filho de Siza, o rubenita, chefe dos rubenitas, e com ele trinta;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 43, 'Hanã, filho de Maacá; Jeosafá, o mitnita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 44, 'Uzias, o asteratita; Sama e Jeiel, filhos de Hotão, o aroerita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 45, 'Jediael, filho de Sínri, e Joá, seu irmão, o tizita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 46, 'Eliel, o maavita; Jeribai e Josavias, filhos de Elnaão; Itma, o moabita;', 1, CURRENT_TIMESTAMP, false),
(13, 11, 47, 'Eliel, Obede e Jaasiel, o mezobaíta', 1, CURRENT_TIMESTAMP, false),
(13, 12, 1, 'Ora, estes são os que vieram a Davi a Ziclague, estando ele ainda tolhido nos seus movimentos por causa de Saul, filho de Quis; e eram dos valentes que o ajudaram na guerra.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 2, 'Eram archeiros, e usavam tanto da mão direita como da esquerda em atirar pedras com fundas e em disparar flechas com o arco; eram dos irmãos de Saul, benjamitas.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 3, 'Aizer, o chefe, e Joás, filhos de Semaá, o Gibeátita; Jeziel e Pelete, filhos de Azmavete; Beraca e Jeú, o anatotita;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 4, 'Ismaías, o gibeonita, valente entre os trinta, e chefe deles; Jeremias, Jaaziel, Joanã e Jozabade, o gederatita;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 5, 'Eluzai, Jerimote, Bealias, Semarias e Sefatias, o harufita;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 6, 'Elcana, Issias, Azarel, Joezer e Jasobeão, os coraítas;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 7, 'e Joela e Zebadias, filhos de Jeroão de Ged or.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 8, 'Dos gaditas se passaram para Davi, ao lugar forte no deserto, homens valentes adestrados para a guerra, que sabiam manejar escudo e lança; seus rostos eram como rostos de leões, e eles eram tão ligeiros como corças sobre os montes.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 9, 'Ezer era o chefe, Obadias o segundo, Eliabe o terceiro,', 1, CURRENT_TIMESTAMP, false),
(13, 12, 10, 'Mismana o quarto, Jeremias o quinto,', 1, CURRENT_TIMESTAMP, false),
(13, 12, 11, 'Atai o sexto, Eliel o sétimo,', 1, CURRENT_TIMESTAMP, false),
(13, 12, 12, 'Joanã o oitavo, Elzabade o nono,', 1, CURRENT_TIMESTAMP, false),
(13, 12, 13, 'Jeremias o décimo, Macbanai o undécimo.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 14, 'Estes, dos filhos de Gade, foram os chefes do exército; o menor valia por cem, e o maior por mil.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 15, 'Estes são os que passaram o Jordão no mês primeiro, quando ele transbordava por todas as suas ribanceiras, e puseram em fuga todos os dois vales ao oriente e ao ocidente.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 16, 'Igualmente alguns dos filhos de Benjamim e de Judá vieram a Davi, ao lugar forte.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 17, 'Davi saiu-lhes ao encontro e lhes disse: Se viestes a mim pacificamente para me ajudar, o meu coração se unirá convosco; porém se é para me entregar aos meus inimigos, sem que haja mal nas minhas mãos, o Deus de nossos pais o veja e o repreenda.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 18, 'Então veio o espírito sobre Amasai, chefe dos trinta, que disse: Nós somos teus, ó Davi, e contigo estamos, ó filho de Jessé! Paz, paz contigo, e paz com quem te ajuda! pois que teu Deus te ajuda. E Davi os recebeu, e os fez chefes de tropas.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 19, 'Também de Manassés alguns se passaram para Davi; foi quando ele veio com os filisteus para a batalha contra Saul; todavia não os ajudou, pois os chefes dos filisteus tendo feito conselho, o despediram, dizendo: Com perigo de nossas cabeças ele se passará para Saul, seu senhor:', 1, CURRENT_TIMESTAMP, false),
(13, 12, 20, 'Voltando ele, pois, a Ziclague, passaram-se para ele, de Manassés: Adná, Jozabade, Jediael, Micael, Jozabade, Eliú e Ziletai, chefes de milhares dos de Manassés.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 21, 'E estes ajudaram a Davi contra a tropa de saqueadores, pois todos eles eram heróis valentes, e foram chefes no exército.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 22, 'De dia em dia concorriam a Davi para o ajudar, até que se fez um grande exército, como o exército de Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 23, 'Ora, estes são os números dos chefes armados para a peleja, que vieram a Davi em Hebrom, para transferir a ele o reino de Saul, conforme a palavra do Senhor:', 1, CURRENT_TIMESTAMP, false),
(13, 12, 24, 'dos filhos de Judá, que traziam escudo e lança, seis mil e oitocentos, armados para a peleja;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 25, 'dos filhos de Simeão, homens valentes para pelejar, sete mil e cem;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 26, 'dos filhos de Levi quatro mil e seiscentos;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 27, 'Jeoiada, que era o chefe da casa de Arão, e com ele três mil e setecentos;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 28, 'e Zadoque, ainda jovem, homem valente, com vinte e dois príncipes da casa de seu pai;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 29, 'dos filhos de Benjamim, irmãos de Saul, três mil, porque até então a maior parte deles se tinha conservado fiel à casa de Saul;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 30, 'dos filhos de Efraim vinte mil e oitocentos homens valentes, homens de nome nas casas de seus pais;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 31, 'da meia tribo de Manassés dezoito mil, que foram designados por nome para virem fazer Davi rei;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 32, 'dos filhos de Issacar, duzentos de seus chefes, entendidos na ciência dos tempos para saberem o que Israel devia fazer, e todos os seus irmãos sob suas ordens;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 33, 'de Zebulom, dos que podiam sair no exército, cinqüenta mil, ordenados para a peleja com todas as armas de guerra, como também destros para ordenarem a batalha, e não eram de coração dobre;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 34, 'de Naftali, mil chefes, e com eles trinta e sete mil com escudo e lança;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 35, 'dos danitas vinte e oito mil e seiscentos, destros para ordenarem a batalha;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 36, 'de Aser, dos que podiam sair no exército e ordenar a batalha, quarenta mil;', 1, CURRENT_TIMESTAMP, false),
(13, 12, 37, 'da outra banda do Jordão, dos rubenitas e gaditas, e da meia tribo de Manassés, com toda sorte de instrumentos de guerra para pelejar, cento e vinte mil.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 38, 'Todos estes, homens de guerra, que sabiam ordenar a batalha, vieram a Hebrom com inteireza de coração, para constituir Davi rei sobre todo o Israel; e também todo o resto de Israel estava de um só coração para constituir Davi rei.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 39, 'E estiveram ali com Davi três dias, comendo e bebendo, pois seus irmãos lhes tinham preparado as provisões.', 1, CURRENT_TIMESTAMP, false),
(13, 12, 40, 'Também da vizinhança, e mesmo desde Issacar, Zebulom e Naftali, trouxeram sobre jumentos, e camelos, e mulos e bois, pão, provisões de farinha, pastas de figos e cachos de passas, vinho e azeite, bois e gado miúdo em abundância; porque havia alegria em Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 1, 'Ora, Davi consultou os chefes dos milhares, e das centenas, a saber, todos os oficiais.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 2, 'E disse Davi a toda a congregação de Israel: Se bem vos parece, e se isto vem do Senhor nosso Deus, enviemos mensageiros por toda parte aos nossos outros irmãos que estão em todas as terras de Israel, e com eles aos sacerdotes e levitas nas suas cidades, e nos seus campos, para que se reunam conosco,', 1, CURRENT_TIMESTAMP, false),
(13, 13, 3, 'e tornemos a trazer para nós a arca do nosso Deus; porque não a buscamos nos dias de Saul.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 4, 'E toda a congregação concordou em que assim se fizesse; porque isso pareceu reto aos olhos de todo o povo.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 5, 'Convocou, pois, Davi todo o Israel desde Sior, o ribeiro do Egito, até a entrada de Hamate, para trazer de Quiriate-Jearim a arca de Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 6, 'E Davi, com todo o Israel, subiu a Baalá, isto é, a Quiriate-Jearim, que está em Judá, para fazer subir dali a arca de Deus, a qual se chama pelo nome do Senhor, que habita entre os querubins.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 7, 'Levaram a arca de Deus sobre um carro novo, tirando-a da casa de Abinadabe; e Uzá e Aiô guiavam o carro.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 8, 'Davi e todo o Israel alegravam-se perante Deus com todas as suas forças, cantando e tocando harpas, alaúdes, tamboris, címbalos e trombetas.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 9, 'Quando chegaram a eira de Quidom, Uzá estendeu a mão para segurar a arca, porque os bois tropeçavam.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 10, 'Então se acendeu a ira do Senhor contra Uzá, e o Senhor o feriu por ter estendido a mão à arca; e ele morreu ali perante Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 11, 'E Davi se encheu de desgosto porque o Senhor havia irrompido contra Uzá; pelo que chamou aquele lugar Pérez-Uzá, como se chama até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 12, 'Temeu Davi a Deus naquele dia, e disse: Como trarei a mim a arca de Deus?', 1, CURRENT_TIMESTAMP, false),
(13, 13, 13, 'Pelo que não trouxe a arca a si para a cidade de Davi, porém a fez retirar para a casa de Obede-Edom, o giteu.', 1, CURRENT_TIMESTAMP, false),
(13, 13, 14, 'Assim ficou a arca de Deus com a família de Obede-Edom, três meses em sua casa; e o Senhor abençoou a casa de Obede-Edom, e tudo o que lhe pertencia.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 1, 'Hirão, rei de Tiro, mandou mensageiros a Davi, e madeira de cedro, pedreiros e carpinteiros para lhe edificarem uma casa.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 2, 'Então percebeu Davi que o Senhor o tinha confirmado rei sobre Israel; porque o seu reino tinha sido muito exaltado por amor do seu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 3, 'Davi tomou em Jerusalém ainda outras mulheres, e teve ainda filhos e filhas.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 4, 'Estes, pois, são os nomes dos filhos que lhe nasceram em Jerusalém: Samua, Sobabe, Natã, Salomão,', 1, CURRENT_TIMESTAMP, false),
(13, 14, 5, 'Ibar, Elisua, Elpelete,', 1, CURRENT_TIMESTAMP, false),
(13, 14, 6, 'Nogá, Nefegue, Jafia,', 1, CURRENT_TIMESTAMP, false),
(13, 14, 7, 'Elisama, Beeliada e Elifelete.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 8, 'Quando os filisteus ouviram que Davi havia sido ungido rei sobre todo o Israel, subiram todos em busca dele; o que ouvindo Davi, logo saiu contra eles.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 9, 'Ora, os filisteus tinham vindo e feito uma arremetida pelo vale de Refaim.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 10, 'Então Davi consultou a Deus, dizendo: Subirei contra os filisteus, e nas minhas mãos os entregarás?: E o Senhor lhe disse: Sobe, porque os entregarei nas tuas mãos.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 11, 'E subiram os filisteus a Baal-Perazim, onde Davi os derrotou; e disse Davi: por minha mão Deus fez uma brecha nos meus inimigos, como uma brecha feita pelas águas. Pelo que chamaram aquele lugar Baal-Perazim:', 1, CURRENT_TIMESTAMP, false),
(13, 14, 12, 'E deixaram ali os seus deuses, que, por ordem de Davi, foram queimados a fogo.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 13, 'Mas os filisteus tornaram a fazer uma arremetida pelo vale.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 14, 'Tornou Davi a consultar a Deus, que lhe respondeu: Não subirás atrás deles; mas rodeia-os por detrás e vem sobre eles por defronte dos balsameiros;', 1, CURRENT_TIMESTAMP, false),
(13, 14, 15, 'e será que, ouvindo tu um ruído de marcha pelas copas dos balsameiros, sairás à peleja; porque Deus terá saído diante de ti para ferir o exército dos filisteus.', 1, CURRENT_TIMESTAMP, false),
(13, 14, 16, 'E fez Davi como Deus lhe ordenara; e desbarataram o exército dos filisteus desde Gibeão até Gezer:', 1, CURRENT_TIMESTAMP, false),
(13, 14, 17, 'Assim a fama de Davi se espalhou por todas aquelas terras, e o Senhor pôs o temor dele sobre todas aquelas gentes.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 1, 'Davi fez para si casas na cidade de Davi; também preparou um lugar para a arca de Deus, e armou-lhe uma tenda:', 1, CURRENT_TIMESTAMP, false),
(13, 15, 2, 'Então disse Davi: Ninguém deve levar a arca de Deus, senão os levitas; porque o Senhor os elegeu para levarem a arca de Deus, e para o servirem para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 3, 'Convocou, pois, Davi todo o Israel a Jerusalém, para fazer subir a arca do Senhor ao seu lugar, que lhe tinha preparado.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 4, 'E reuniu os filhos de Arão e os levitas.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 5, 'dos filhos de Coate, Uriel, o chefe, e de seus irmãos cento e vinte;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 6, 'dos filhos de Merári, Asaías, o chefe, e de seus irmãos duzentos e vinte;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 7, 'dos filhos de Gérson Joel, o chefe, e de seus irmãos cento e trinta;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 8, 'dos filhos de Elizafã, Semaías, o chefe, e de seus irmãos duzentos;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 9, 'dos filhos de Hebrom, Eliel, o chefe, e de seus irmãos oitenta;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 10, 'dos filhos de Uziel, Aminadabe, o chefe, e de seus irmãos cento e doze.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 11, 'Então chamou Davi os sacerdotes Zadoque e Abiatar, e os levitas Uriel, Asaías, Joel, Semaías, Eliel e Aminadabe,', 1, CURRENT_TIMESTAMP, false),
(13, 15, 12, 'e disse-lhes: Vós sois os chefes das casas paternas entre os levitas; santificai-vos, vós e vossos irmãos, para que façais subir a arca do Senhor Deus de Israel ao lugar que lhe preparei.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 13, 'Porquanto da primeira vez vós não a levastes, o Senhor fez uma brecha em nós, porque não o buscamos segundo a ordenança:', 1, CURRENT_TIMESTAMP, false),
(13, 15, 14, 'Santificaram-se, pois, os sacerdotes e os levitas para fazerem subir a arca do Senhor Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 15, 'E os levitas trouxeram a arca de Deus sobre os seus ombros, pelos varais que nela havia, como Moisés tinha ordenado, conforme a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 16, 'E Davi ordenou aos chefes dos levitas que designassem alguns de seus irmãos como cantores, para tocarem com instrumentos musicais, com alaúdes, harpas e címbalos, e levantarem a voz com alegria.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 17, 'Designaram, pois, os levitas a Hemã, filho de Joel; e dos seus irmãos, a Asafe, filho de Berequias; e dos filhos de Merári, seus irmãos, a Etã, filho de Cusaías;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 18, 'e com eles a seus irmãos da segunda ordem: Zacarias, Bene, Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaías, Maaséias, Matitias, Elifeleu e Micnéias, e Obede-Edom e Jeiel, os porteiros.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 19, 'Assim os cantores Hemã, Asafe e Etã se faziam ouvir com címbalos de bronze;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 20, 'e Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaséias e Benaías, com alaúdes adaptados ao soprano;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 21, 'e Matitias, Elifeleu, Micnéias, Obede-Edom, Jeiel e Azazias, com harpas adaptadas ao baixo, para dirigirem;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 22, 'e Quenanias, chefe dos levitas, estava encarregado dos cânticos e os dirigia, porque era entendido;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 23, 'e Berequias e Elcana eram porteiros da arca;', 1, CURRENT_TIMESTAMP, false),
(13, 15, 24, 'e Sebanias, Jeosafá, Netanel, Amasai, Zacarias, Benaías e Eliézer, os sacerdotes, tocavam as trombetas perante a arca de Deus; e Obede-Edom e Jeías eram porteiros da arca.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 25, 'Sucedeu pois que Davi, os anciãos de Israel, os capitães dos milhares foram, com alegria, para fazer subir a arca do pacto do Senhor, da casa de Obede-Edem.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 26, 'E sucedeu que, havendo Deus ajudado os levitas que levavam a arca do pacto dó Senhor, sacrificaram sete novilhos e sete carneiros.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 27, 'Davi ia vestido de um manto de linho fino, como também todos os levitas que levavam a arca, e os cantores, e juntamente com eles Quenanias, diretor do canto; Davi levava também sobre si um éfode de linho.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 28, 'Assim todo o Israel fez subir a arca do pacto do Senhor com vozes de júbilo, ao som de buzinas, trombetas e címbalos, juntamente com alaúdes e harpas.', 1, CURRENT_TIMESTAMP, false),
(13, 15, 29, 'E sucedeu que, chegando a arca do pacto do Senhor à cidade de Davi, Mical, a filha de Saul, olhou duma janela e, vendo Davi dançar e saltar, desprezou-o no seu coração.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 1, 'Trouxeram, pois, a arca de Deus e a colocaram no meio da tenda que Davi lhe tinha armado; e ofereceram holocaustos e sacrifícios pacíficos perante Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 2, 'Tendo Davi acabado de oferecer os holocaustos e sacrifícios pacíficos, abençoou o povo em nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 3, 'Então repartiu a todos em Israel, tanto a homens como a mulheres, a cada um, um pão, um pedaço de carne e um bolo de passas.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 4, 'Também designou alguns dos levitas por ministros perante a arca do Senhor, para celebrarem, e para agradecerem e louvarem ao Senhor Deus de Israel, a saber:', 1, CURRENT_TIMESTAMP, false),
(13, 16, 5, 'Asafe, o chefe, e Zacarias, o segundo depois dele; Jeiel, Semiramote, Jeiel, Matitias, Eliabe, Benaías, Obede-Edom e Jeiel, com alaúdes e com harpas; e Asafe se fazia ouvir com címbalos;', 1, CURRENT_TIMESTAMP, false),
(13, 16, 6, 'e Benaías e Jaaziel, os sacerdotes, tocavam trombetas continuamente perante a arca do pacto de Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 7, 'Foi nesse mesmo dia que Davi, pela primeira vez, ordenou que pelo ministério de Asafe e de seus irmãos se dessem ações de graças ao Senhor, nestes termos:', 1, CURRENT_TIMESTAMP, false),
(13, 16, 8, 'Louvai ao Senhor, invocai o seu nome; fazei conhecidos entre os povos os seus feitos.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 9, 'Cantai-lhe, salmodiai-lhe, falai de todas as suas obras maravilhosas.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 10, 'Gloriai-vos no seu santo nome; alegre-se o coração dos que buscam ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 11, 'Buscai ao Senhor e a sua força; buscai a sua face continuamente.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 12, 'Lembrai-vos das obras maravilhosas que ele tem feito, dos seus prodígios, e dos juízos da sua boca,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 13, 'vós, descendência de Israel, seus servos, vós, filhos de Jacó, seus eleitos.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 14, 'Ele é o Senhor nosso Deus; em toda a terra estão os seus juízos.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 15, 'Lembrai-vos perpetuamente do seu pacto, da palavra que prescreveu para mil gerações;', 1, CURRENT_TIMESTAMP, false),
(13, 16, 16, 'do pacto que fez com Abraão, do seu juramento a Isaque,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 17, 'o qual também a Jacó confirmou por estatuto, e a Israel por pacto eterno,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 18, 'dizendo: A ti te darei a terra de Canaã, quinhão da vossa herança.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 19, 'Quando eram poucos em número, sim, mui poucos, e estrangeiros na terra,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 20, 'andando de nação em nação, e dum reino para outro povo,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 21, 'a ninguém permitiu que os oprimisse, e por amor deles repreendeu reis,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 22, 'dizendo: Não toqueis os meus ungidos, e não façais mal aos meus profetas.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 23, 'Cantai ao Senhor em toda a terra; proclamai de dia em dia a sua salvação.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 24, 'Publicai entre as nações a sua gloria, entre todos os povos as suas maravilhas.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 25, 'Porque grande é o Senhor, e mui digno de louvor; também é mais temível do que todos os deuses.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 26, 'Pois todos os deuses dos povos são ídolos, porém o Senhor fez os céus.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 27, 'Diante dele há honra e majestade; há força e alegria no seu lugar.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 28, 'Tributai ao Senhor, ó famílias dos povos, tributai ao Senhor glória e força.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 29, 'Tributai ao Senhor a glória devida ao seu nome; trazei presentes, e vinde perante ele; adorai ao Senhor vestidos de trajes santos.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 30, 'Trema diante dele toda a terra; o mundo se acha firmado, de modo que se não pode abalar.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 31, 'Alegre-se o céu, e regozije-se a terra; e diga-se entre as nações: O Senhor reina.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 32, 'Brama o mar e a sua plenitude; exulte o campo e tudo o que nele há;', 1, CURRENT_TIMESTAMP, false),
(13, 16, 33, 'então jubilarão as árvores dos bosques perante o Senhor, porquanto vem julgar a terra.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 34, 'Dai graças ao Senhor, porque ele é bom; porque a sua benignidade dura para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 35, 'E dizei: Salva-nos, ó Deus da nossa salvação, e ajunta-nos, e livra-nos das nações, para que demos graças ao teu santo nome, e exultemos no teu louvor.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 36, 'Bendito seja o Senhor Deus de Israel, de eternidade a eternidade. Então todo o povo disse: Amém! e louvou ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 37, 'Davi, pois, deixou ali, diante da arca do pacto do Senhor, Asafe e seus irmãos, para ministrarem continuamente perante a arca, segundo a exigência de cada dia.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 38, 'Também deixou Obeede-Edom , com seus irmãos, sessenta e oito; Obede-Edomsa filho de Jedútum e Hosa, para serem porteiros;', 1, CURRENT_TIMESTAMP, false),
(13, 16, 39, 'e deixou Zadoque, o sacerdote, e seus irmãos, os sacerdotes, diante do tabernáculo do Senhor, no alto que havia em Gibeão,', 1, CURRENT_TIMESTAMP, false),
(13, 16, 40, 'para oferecerem holocaustos ao Senhor continuamente, pela manhã e à tarde, sobre o altar dos holocaustos; e isto segundo tudo o que está escrito na lei que o Senhor tinha ordenado a Israel;', 1, CURRENT_TIMESTAMP, false),
(13, 16, 41, 'e com eles Hemã, e Jedútum e os demais escolhidos, que tinham sido nominalmente designados, para darem graças ao Senhor, porque a sua benignidade dura para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 42, 'Estavam Hemã e Jedútun encarregados das trombetas e dos címbalos para os que os haviam de tocar, e dos outros instrumentos para os cânticos de Deus; e os filhos de Jedútun estavam à porta.', 1, CURRENT_TIMESTAMP, false),
(13, 16, 43, 'Então todo o povo se retirou, cada um para a sua casa; e Davi voltou para abençoar a sua casa.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 1, 'Tendo Davi começado a morar em sua casa, disse ao profeta Natã: Eis que eu moro numa casa de cedro, mas a arca do pacto do Senhor está debaixo de cortinas.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 2, 'Então Natã disse a Davi: Tudo quanto tens no teu coração faze, porque Deus é contigo.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 3, 'Mas sucedeu, na mesma noite, que a palavra de Deus veio à Natã, dizendo:', 1, CURRENT_TIMESTAMP, false),
(13, 17, 4, 'Vai e dize a Davi, meu servo: Assim diz o Senhor: Tu não me edificarás casa para eu habitar;', 1, CURRENT_TIMESTAMP, false),
(13, 17, 5, 'porque em nenhuma casa morei, desde o dia em que fiz subir Israel até o dia e hoje, mas fui de tenda em tenda, e de tabernáculo em tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 6, 'Por todas as partes por onde tenho andado com todo o Israel, porventura falei eu jamais uma palavra a algum dos juízes de Israel, a quem ordenei que apascentasse o meu povo, dizendo: Por que não me tendes edificado uma casa de cedro?', 1, CURRENT_TIMESTAMP, false),
(13, 17, 7, 'Agora, pois, assim dirás a meu servo Davi: Assim diz o Senhor dos exércitos: Eu te tirei do curral, de detrás das ovelhas, para que fosses chefe do meu povo Israel;', 1, CURRENT_TIMESTAMP, false),
(13, 17, 8, 'e estive contigo por onde quer que andavas, e de diante de ti exterminei todos os teus inimigos; também te farei um nome como o nome dos grandes que estão na terra.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 9, 'Designarei um lugar para o meu povo Israel, e o plantarei, para que ele habite no seu lugar, e nunca mais seja perturbado; e nunca mais debilitarão os filhos da perversidade, como dantes,', 1, CURRENT_TIMESTAMP, false),
(13, 17, 10, 'e como desde os dias em que ordenei juízes sobre o meu povo Israel; e subjugarei todos os teus inimigos. Também te declaro que o Senhor te edificará uma casa.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 11, 'Quando forem cumpridos os teus dias, para ires a teus pais, levantarei a tua descendência depois de ti, um dos teus filhos, e estabelecerei o seu reino.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 12, 'Esse me edificará casa, e eu firmarei o seu trono para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 13, 'Eu lhe serei por pai, e ele me será por filho; e a minha misericórdia não retirarei dele, como a retirei daquele que foi antes de ti;', 1, CURRENT_TIMESTAMP, false),
(13, 17, 14, 'mas o confirmarei na minha casa e no meu reino para sempre, e para sempre o seu trono será firme.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 15, 'Conforme todas estas palavras, e conforme toda esta visão, assim falou Natã a Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 16, 'Então entrou o rei Davi, sentou-se perante o Senhor, e disse: Quem sou eu, ó Senhor Deus, e que é a minha casa, para que me tenhas trazido até aqui?,', 1, CURRENT_TIMESTAMP, false),
(13, 17, 17, 'E isto foi pouco aos teus olhos, O Deus; também falaste da casa do teu servo para tempos distantes, e me consideras como a um homem ilustre, ó Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 18, 'Que mais te dirá Davi, acerca da honra feita ao teu servo? pois tu bem conheces o teu servo.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 19, 'O Senhor! por amor do teu servo, e segundo o teu coração, fizeste todas estas grandezas, tornando conhecidas todas estas grandes coisas.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 20, 'O Senhor, ninguém há semelhante a ti, e não há Deus fora de ti, segundo tudo quanto ouvimos com os nossos ouvi os.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 21, 'Também quem há como o teu povo Israel, única gente na terra a quem Deus foi remir para ser seu povo, fazendo-te nome por meio de feitos grandes e terríveis, expulsando as nações de diante do teu povo, que remiste do Egito?', 1, CURRENT_TIMESTAMP, false),
(13, 17, 22, 'Pois fizeste o teu povo Israel povo teu para sempre; e tu, Senhor, te fizeste seu Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 23, 'Agora, ó Senhor, seja confirmada para sempre a palavra que falaste acerca da teu servo, e acerca da sua casa, e faze como falaste.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 24, 'E seja o teu nome estabelecido e glorificado para sempre, e diga-se: O Senhor dos exércitos é o Deus de Israel, sim, é Deus para Israel; permaneça firme diante de ti a casa de Davi, teu servo.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 25, 'Porque tu, Deus meu, revelaste ao teu servo que lhe edificarias casa; pelo que o teu servo achou confiança para orar em tua presença.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 26, 'Agora, pois, ó Senhor, tu és Deus, e falaste este bem acerca do teu servo.', 1, CURRENT_TIMESTAMP, false),
(13, 17, 27, 'E agora foste servido abençoar a casa do teu servo, para que permaneça para sempre diante de ti; porque tu, Senhor, a abençoaste, ficará abençoada para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 1, 'Depois disto Davi derrotou os filisteus, e os subjugou e tomou das mãos deles Gate e as suas aldeias.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 2, 'Também derrotou os moabitas, e estes lhe ficaram sujeitos, pagando-lhe tributos.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 3, 'Davi derrotou também Hadadézer, rei de Zobá, junto a Hamate, quando foi estabelecer o seu domínio junto ao rio Eufrates.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 4, 'E Davi lhe tomou mil carros, sete mil cavaleiros e vinte mil homens de infantaria; e jarretou todos os cavalos dos carros; porém reservou deles para cem carros.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 5, 'E quando os sírios de Damasco vieram para ajudar a Hadadézer, rei de Zobá, Davi matou deles vinte e dois mil homens.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 6, 'Então Davi pôs guarnições entre os sírios de Damasco, e os sírios lhe ficaram sujeitos, pagando-lhe tributos; e o Senhor dava vitória a Davi, por onde quer que ia.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 7, 'Davi tomou os escudos de ouro que tinham sido dos servos de Hadadézer, e os trouxe a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 8, 'Também de Tibate, e de Cum, cidades de Hadadézer, Davi tomou muitíssimo bronze, de que Salomão fez o mar de bronze, as colunas, e os utensílios de bronze.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 9, 'Ora, quando Toú, rei de Hamate, ouviu que Davi destruíra todo o exército de Hadadézer, rei de Zobá,', 1, CURRENT_TIMESTAMP, false),
(13, 18, 10, 'mandou seu filho Hadorão ao rei Davi, para o saudar, e para o felicitar por haver pelejado contra Hadadézer e por tê-lo destruído {porque Hadadézer fazia guerra a Toú}. Enviou-lhe também toda sorte de utensílios de ouro, de prata e de bronze. l', 1, CURRENT_TIMESTAMP, false),
(13, 18, 11, 'A estes também o rei Davi consagrou ao Senhor, juntamente com a prata e o ouro que trouxera de todas as nações dos edomeus, dos moabitas, dos amonitas, dos filisteus e dos amalequitas.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 12, 'Além disso Abisai, filho de Zeruia, matou dezoito mil edomeus no Vale do Sal.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 13, 'E pôs guarnições em Edom, e todos os edomeus ficaram sujeitos a Davi; e o Senhor dava vitória a Davi, por onde quer que ia.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 14, 'Dari, pois, reinou sobre todo o Israel; e julgava, e fazia justiça a todo o seu povo.', 1, CURRENT_TIMESTAMP, false),
(13, 18, 15, 'Joabe, filho de Zeruia, tinha o cargo do exército; Jeosafá, filho de Ailude, era cronista;', 1, CURRENT_TIMESTAMP, false),
(13, 18, 16, 'Zadoque, filho de Aiuube, e Abimeleque, filho de Abiatar, eram sacerdotes; Sarsa era escrivão;', 1, CURRENT_TIMESTAMP, false),
(13, 18, 17, 'Benaías, filho de Jeoiada, tinha o cargo dos quereteus e peleteus; e os filhos de Davi eram os primeiros junto ao rei.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 1, 'Aconteceu, depois disto, que Naás, rei dos amonitas, morreu; e seu filho reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 2, 'Então disse Davi: usarei de benevolência para com Hanum, filho de Naás, porque seu pai usou de benevolência para comigo. Pelo que Davi enviou mensageiros para o consolarem acerca de seu pai. Mas quando os servos de Davi chegaram à terra dos amonitas, a Hanum, para o consolarem,', 1, CURRENT_TIMESTAMP, false),
(13, 19, 3, 'disseram os príncipes dos amonitas a Hanum: Pensas que Davi quer honrar a teu pai, porque te mandou consoladores? Não vieram ter contigo os seus servos a esquadrinhar, a transtornar e a espiar a terra?', 1, CURRENT_TIMESTAMP, false),
(13, 19, 4, 'Pelo que Hanum tomou os servos de Davi, raspou-lhes a barba, e lhes cortou as vestes pelo meio até o alto das coxas, e os despediu.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 5, 'Então foram alguns e avisaram a Davi acerca desses homens; pelo que ele mandou mensageiros ao seu encontro, pois estavam sobremaneira envergonhados. Disse o rei: Ficai em Jericó até que vos torne a crescer a barba, e então voltai.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 6, 'Vendo os amonitas que se tinham feito odiosos para com Davi, Hanum e os amonitas enviaram mil talentos de prata, para alugarem para si carros e cavaleiros de Mesopotâmia, de Arã-Maacá e de Zobá.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 7, 'E alugaram para si trinta e dois mil carros e o rei de Maacá com a sua gente, os quais vieram e se acamparam diante de Medeba; também os amonitas se ajuntaram das suas cidades e vieram para a guerra.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 8, 'Davi, quando soube disto, enviou Joabe e todo o exército de homens valentes.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 9, 'Os amonitas saíram e ordenaram a batalha à porta da cidade; porém os reis que tinham vindo se puseram à parte no campo.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 10, 'Ora, quando Joabe viu que a batalha estava ordenada contra ele pela frente e pela retaguarda, escolheu os melhores dentre os homens de Israel, e os pôs em ordem contra os sírios;', 1, CURRENT_TIMESTAMP, false),
(13, 19, 11, 'e o resto do povo entregou na mão de Abisai, seu irmão; e eles se puseram em ordem de batalha contra os amonitas.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 12, 'E disse Joabe: Se os sírios forem mais fortes do que eu, tu virás socorrer-me; e, se os amonitas forem mais fortes do que tu, então eu te socorrerei a ti.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 13, 'Esforça-te, e pelejemos varonilmente pelo nosso povo e pelas cidades do nosso Deus; e faça o Senhor o que bem lhe parecer.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 14, 'Então se chegou Joabe, e o povo que estava com ele, diante dos sírios, para a batalha; e estes fugiram de diante dele.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 15, 'Vendo, pois, os amonitas que os sírios tinham fugido, fugiram eles também de diante de Abisai, irmão de Joabe, e entraram na cidade. Então Joabe voltou para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 16, 'Ora, vendo-se os sírios derrotados diante de Israel, enviaram mensageiros, e fizeram sair os sírios que habitavam além do rio; e tinham por comandante Sofaque, chefe do exército de Hadadézer.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 17, 'Avisado disto, Davi ajuntou todo o Israel, passou o Jordão e, indo ao encontro deles, ordenou contra eles a batalha. Tendo Davi ordenado a batalha contra os sírios, pelejaram estes contra ele.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 18, 'Mas os sírios fugiram de diante de Israel; e Davi matou deles os homens de sete mil carros, e quarenta mil homens da infantaria; matou também Sofaque, chefe do exército.', 1, CURRENT_TIMESTAMP, false),
(13, 19, 19, 'Vendo, pois, os servos de Hadadézer que tinham sido derrotados diante de Israel, fizeram paz cem Davi, e serviram; e os sírios nunca mais quiseram socorrer os amonitas.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 1, 'Aconteceu pois que, na primavera, no tempo em que os reis costumam sair para a guerra, Joabe levou a flor do exército, e devastou a terra dos amonitas, e foi, e pôs cerco a Rabá; porém Davi ficou em Jerusalém. E Joabe bateu Rabá, e a destruiu.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 2, 'Tirando Davi a coroa da cabeça do rei deles, achou nela o peso dum talento de ouro, e havia nela pedras preciosas; e foi posta sobre a cabeça de Davi. E ele levou da cidade mui grande despojo.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 3, 'Também fez sair o povo que estava nela e o fez trabalhar com serras, com trilhos de ferro e com machado, e assim fez Davi a todas as cidades dos amonitas. Então voltou Davi, com todo o povo, para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 4, 'Depois disso levantou-se guerra em Gezer com os filisteus; então Sibecai, o husatita, matou Sipai, dos filhos do gigante; e eles ficaram subjugados.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 5, 'Tornou a haver guerra com os filisteus; e El-Hanã, filho de Jair, matou Lami, irmão de Golias, o giteu, cuja lança tinha a haste como órgão de tecelão,', 1, CURRENT_TIMESTAMP, false),
(13, 20, 6, 'Houve ainda outra guerra em Gate, onde havia um homem de grande estatura, que tinha vinte e quatro dedos, seis em cada mão e seis em cada pé, e que também era filho do gigante.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 7, 'Tendo ele insultado a Israel, Jônatas, filho de Siméia, irmão de Davi, o matou.', 1, CURRENT_TIMESTAMP, false),
(13, 20, 8, 'Esses nasceram ao gigante em Gate; e caíram pela mão de Davi e pela mão dos seus servos.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 1, 'Então Satanás se levantou contra Israel, e incitou Davi a numerar Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 2, 'E disse Davi a Joabe e aos príncipes de povo: Ide, cantai a Israel desde Berseba até Dã; e trazei-me a conta, para que eu saiba o número deles.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 3, 'Então disse Joabe: O Senhor acrescente ao seu povo cem vezes tanto como ele é! Porventura, é rei meu senhor, não são teus os servos de meu senhor? Por que requer isto e meu senhor. Por que traria ele culpa sobre Israel?', 1, CURRENT_TIMESTAMP, false),
(13, 21, 4, 'Todavia a palavra de rei prevaleceu contra Joabe. Pelo que saiu Joabe, e passou por todo o Israel; depois voltou para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 5, 'E Joabe deu a Davi o resultado da numeração do povo. E era todo o Israel um milhão e cem mil homens que arrancavam da espada; e de Judá quatrocentos e setenta mil homens que arrancavam da espada.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 6, 'Mas entre eles Joabe não contou os de Levi e Benjamim, porque a palavra do rei lhe foi abominável.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 7, 'E este negócio desagradou a Deus, pelo que feriu Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 8, 'Então disse Davi a Deus: Gravemente pequei em fazer tal coisa; agora porém, peço-te, tira a iniqüidade de teu servo, porque procedi mui loucamente.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 9, 'Falou o Senhor a Gade, o vidente de Davi, dizendo:', 1, CURRENT_TIMESTAMP, false),
(13, 21, 10, 'Vai, e dize a Davi: Assim diz o Senhor: Três coisas te proponho; escolhe uma delas, para que eu te faça.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 11, 'E Gade veio a Davi, e lhe disse: Assim diz o Senhor: Escolhe o que quiseres:', 1, CURRENT_TIMESTAMP, false),
(13, 21, 12, 'ou três anos de fome; ou seres por três meses consumido diante de teus adversários, enquanto a espada de teus inimigos te alcance; ou que por três dias a espada do Senhor, isto é, a peste na terra, e o anjo do Senhor façam destruição por todos os termos de Israel. Vê, pois, agora que resposta hei de levar a quem me enviou.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 13, 'Então disse Davi a Gade: Estou em grande angústia; caia eu, pois, nas mãos do Senhor, porque mui grandes são as suas misericórdias; mas que eu não caia nas mãos dos homens.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 14, 'Mandou, pois, o Senhor a peste a Israel; e caíram de Israel setenta mil homens.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 15, 'E Deus mandou um anjo a Jerusalém para a destruir; e, estando ele prestes a destrui-la, o Senhor olhou e se arrependeu daquele mal, e disse ao anjo destruidor: Basta; agora retira a tua mão. E o anjo do Senhor estava junto à eira de Ornã, o jebuseu.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 16, 'E Davi, levantando os olhos, viu o anjo do Senhor, que estava entre a terra e o céu, tendo na mão uma espada desembainhada estendida sobre Jerusalém. Então Davi e os anciãos, cobertos de sacos, se prostraram sobre os seus rostos.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 17, 'E dissemorreram Saul e seus três filhos; morreu toda a sua o povo? E eu mesmo sou o que pequei, e procedi muito mal; mas estas ovelhas, que fizeram? Seja tua mão, Senhor Deus meu, contra mim e contra a casa de meu pai, porem não contra o teu povo para castigá-lo com peste.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 18, 'Então o anjo do Senhor ordenou a Gade que dissesse a Davi para subir e levantar um altar ao Senhor na eira de Ornã, o jebuseu.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 19, 'Subiu, pois, Davi, conforme a palavra que Gade falara em nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 20, 'E, virando-se Ornã, viu o anjo; e seus quatro filhos, que estavam com ele, se esconderam. Ora, Ornã estava debulhando trigo.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 21, 'Quando Davi se vinha chegando a Ornã, este olhou e o viu e, saindo da terra, prostrou-se diante dele com o rosto em terra.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 22, 'Então disse Davi a Ornã: Dá-me o lugar da eira pelo seu valor, para eu edificar nele um altar ao Senhor, para que cesse esta praga de sobre o povo.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 23, 'Respondeu Ornã a Davi: Toma-o para ti, e faça o rei meu senhor o que lhe parecer bem. Eis que dou os bois para holocaustos, os trilhos para lenha, e o trigo para oferta de cereais; tudo dou.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 24, 'Mas o rei Davi disse a Ornã: Não, antes quero comprá-lo pelo seu valor; pois não tomarei para o Senhor o que é teu, nem oferecerei holocausto que não me custe nada.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 25, 'E Davi deu a Ornã por aquele lugar o peso de seiscentos siclos de ouro.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 26, 'Então Davi edificou ali um altar ao Senhor, e ofereceu holocaustos e ofertas pacíficas; e invocou o Senhor, o qual lhe respondeu do céu, com fogo sobre o altar de holocausto.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 27, 'E o Senhor deu ordem ao anjo, que tomou a meter a sua espada na bainha.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 28, 'Nesse mesmo tempo, vendo Davi que o Senhor lhe respondera na eira de Ornã, o jebuseu, ofereceu ali os seus sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(13, 21, 29, 'Pois o tabernáculo do Senhor que Moisés fizera no deserto, e o altar do holocausto, estavam naquele tempo no alto de Gibeão;', 1, CURRENT_TIMESTAMP, false),
(13, 21, 30, 'mas Davi não podia ir perante ele para consultar a Deus, porque estava atemorizado por causa da espada do anjo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 1, 'Então disse Davi: Esta é a casa de Senhor Deus, e este é o altar de holocausto para Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 2, 'Então Davi deu ordem que se ajuntassem os estrangeiros que estavam na terra de Israel, e encarregou pedreiros de lavrarem pedras de cantaria para edificar a casa de Deus,', 1, CURRENT_TIMESTAMP, false),
(13, 22, 3, 'Também aparelhou ferro em abundância, para os pregos das portas das entradas e para as junturas; como também bronze em abundância, sem pesá-lo;', 1, CURRENT_TIMESTAMP, false),
(13, 22, 4, 'e madeira de cedro sem conta, porque os sidonios e tírios traziam a Davi cedro em abundância', 1, CURRENT_TIMESTAMP, false),
(13, 22, 5, 'Porque dizia Davi: Salomão, meu filho, ainda é moço e tenro, e a casa que se há de edificar para o Senhor deve ser magnífica em excelência, de renome e glória em todas as terras; eu, pois, agora lhe farei os preparativos. Assim fez Davi grandes preparativos antes da sua morte.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 6, 'Então chamou a Salomão, seu filho, e lhe ordenou que edificasse uma casa ao Senhor Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 7, 'Disse Davi a Salomão: Filho meu, quanto a mim, tive em meu coração a propósito de edificar uma casa ao nome do Senhor meu Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 8, 'A palavra do Senhor, porém, veio a mim, dizendo: Tu tens derramado muito sangue, e tens feito grandes guerras; não edificarás casa ao meu nome, porquanto muito sangue tens derramado na terra, perante mim.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 9, 'Eis que te nascerá um filho, que será homem de repouso; porque lhe darei repouso de todos os seus inimigos ao redor; portanto Salomão será o seu nome, e eu darei paz e descanso a Israel nos seus dias.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 10, 'Ele edificará uma casa ao meu nome. Ele me será por filho, e eu lhe serei por pai, e confirmarei o trono de seu reino sobre Israel para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 11, 'Agora, meu filho, o Senhor seja contigo; prospera, e edifica a casa de Senhor teu Deus, como ele falou a respeito de ti.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 12, 'Tão somente te dê o Senhor prudência e entendimento para governares sobre Israel, e para guardares a lei do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 13, 'Então prosperarás, se tiveres cuidado de guardar os estatutos e os juízos que o Senhor ordenou a Moisés acerca de Israel. Esforça-te, e tem bem ânimo; não temas, nem te espantes.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 14, 'Com trabalhos penosas preparei para a casa do Senhor cem mil talentos de ouro, e um milhão de talentos de prata, e bronze e ferro que por sua abundância, não se pesou; também madeira e pedras preparei; e tu os aumentarás ainda.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 15, 'Além disso tens trabalhadores em grande número, canteiros, pedreiros e carpinteiros, e toda sorte de peritos em toda espécie de obra.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 16, 'Do ouro, da prata, da bronze e do ferro não há conta. Levanta-te, pois; mãos à obra! E o Senhor seja contigo!', 1, CURRENT_TIMESTAMP, false),
(13, 22, 17, 'Também Davi deu ordem a todos os chefes de Israel que ajudassem a Salomão, seu filho, dizendo:', 1, CURRENT_TIMESTAMP, false),
(13, 22, 18, 'Porventura não está convosco o Senhor vosso Deus, e não vos deu repouso por todos os lados? Pois entregou na minha mão os habitantes da terra; e a terra foi subjugada diante do Senhor e diante do seu povo.', 1, CURRENT_TIMESTAMP, false),
(13, 22, 19, 'Disponde, pois, agora o vosso coração e a vossa alma para buscardes ao Senhor vosso Deus; e levantai-vos, e edificai o santuário do Senhor Deus, para que a arca do pacto do Senhor e os vasos sagrados de Deus sejam trazidos, para a casa que se há de edificar ao nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 1, 'Ora, sendo Davi já velho e cheio de dias, fez Salomão, seu filho, rei sobre Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 2, 'E reuniu todos os chefes de Israel, como também os sacerdotes e levitas.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 3, 'Foram contados os levitas de trinta anos para cima; e foi o número deles, segundo o seu registo, trinta e oito mil homens.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 4, 'Deste número vinte e quatro mil promoverão a obra da casa do Senhor; seis mil servirão como oficiais e juízes;', 1, CURRENT_TIMESTAMP, false),
(13, 23, 5, 'quatro mil como porteiros; e quatro mil para louvarem ao Senhor com os instrumentos, que eu fiz para o louvar, disse Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 6, 'Davi os repartiu por turmas segundo os filhos de Levi: Gérsom, Coate e Merári.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 7, 'Dos gersonitas: Ladã e Simei.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 8, 'Os filhos de Ladã: Jeiel o chefe, Zetão e Joel, três.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 9, 'Os filhos de Simei: Selomite, Haziel e Arã, três; estes foram os chefes das casas paternas de Ladã.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 10, 'Os filhos de Simei: Jaate, Zina, Jeús e Berias; estes foram os filhos de Simei, quatro.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 11, 'Jaate era o chefe, e Ziza o segundo. Mas Jeús e Berias não tiveram muitos filhos; pelo que estes, contados juntos, se tornaram uma só casa paterna.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 12, 'Os filhos de Coate: Anrão, Izar, Hebrom e Uziel, quatro.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 13, 'Os filhos de Anrão: Arão e Moisés. Arão foi separado para consagrar as coisas santíssimas, ele e seus filhos, eternamente para queimarem incenso diante do Senhor, e o servirem, e pronunciarem bênçãos em nome de Deus para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 14, 'Mas quanto a Moisés, homem de Deus, seus filhos foram contados entre os da tribo de Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 15, 'Os filhos de Moisés: Gerson e Eliézer.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 16, 'De Gérson: Sebuel o chefe.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 17, 'De Eliézer: Reabias o chefe; e Eliézer não teve outros filhos; porém os filhos de Reabias foram muito numerosos.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 18, 'De Izar: Selomite o chefe.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 19, 'Os filhos: de Hebrom: Jerias o chefe, Amarias o segundo, Jaaziel o terceiro, e Jecameão o quarto.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 20, 'Os filhos de Uziel: Mica o chefe. Issias o segundo.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 21, 'Os filhos de Merári: Mali e Musi. Os filhos de Mali: Eleazar e Quis.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 22, 'Eleazar morreu, não tendo filhos, mas tão somente filhas; e os filhos de Quis, seus irmãos, tomaram-nas por mulheres.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 23, 'Os filhos de Musi: Mali, Eder e Jerimote, três.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 24, 'Esses são os filhos de Levi segundo as suas casas paternas, isto é, segundo os chefes das casas paternas, conforme o número dos que foram registrados pelos seus: nomes, individualmente, da idade de vinte anos para cima, os quais trabalhavam no serviço da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 25, 'Pois Davi disse: O Senhor Deus de Israel deu repouso ao seu povo; e ele habita em Jerusalém para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 26, 'Também os levitas não terão mais de levar o tabernáculo e todos os objetos pertencentes ao serviço do mesmo.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 27, 'Eis porque, segundo as ultimas palavras de Davi, foram contados os levitas da idade de vinte anos para cima.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 28, 'Porque o seu cargo seria o de assistirem aos filhos de Arão no serviço da casa do Senhor, nos átrios, e nas câmaras, e na purificação de todas as coisas sagradas, e em qualquer trabalho para o serviço da casa de Deus,', 1, CURRENT_TIMESTAMP, false),
(13, 23, 29, 'cuidando dos pães da proposição, e da flor de farinha para a oferta de cereais, quer seja de bolos ázimos, quer seja do que se assa na panela, quer seja do que é misturado com azeite, e de toda sorte de medidas e pesos;', 1, CURRENT_TIMESTAMP, false),
(13, 23, 30, 'e de estarem cada manhã em pé para render graças e louvor ao Senhor, e semelhantemente à tarde.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 31, 'e oferecerem continuamente perante o Senhor todos os holocaustos, nos sábados, nas luas novas e nas festas fixas, segundo o número ordenado.', 1, CURRENT_TIMESTAMP, false),
(13, 23, 32, 'Também teriam a seu cargo a tenda da revelação, o lugar santo, e os filhos de Arão, seus irmãos, no serviço da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 1, 'As turmas dos filhos de Arão foram estas: os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 2, 'Mas Nadabe e Abiú morreram antes de seu pai, e não tiveram filhos; por isso Eleazar e Itamar exerciam o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 3, 'E Davi, juntamente com Zadoque, dos filhos de Eleazar, e com Aimeleque, dos filhos de Itamar, os distribuiu segundo os deveres do seu serviço.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 4, 'E acharam-se mais chefes dentre os filhos de Eleazar do que dentre os filhos de Itamar; e assim foram distribuídos: dos filhos de Eleazar, chefes das casas paternas, dezesseis; e dos filhos de Itamar, segundo as suas casas paternas, oito.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 5, 'Assim foram distribuídos por sortes, tanto uns como os outros; porque havia príncipes do santuário e príncipes de Deus, tanto dentre os filhos de Eleazar, como dentre os filhos de Itamar.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 6, 'E os registrou Semaías, filho de Netanel, o escrivão dentre os levitas, diante do rei, dos príncipes, de Zadoque, o sacerdote, de Aimeleque, filho de Abiatar, e dos chefes das casas paternas entre os sacerdotes e entre os levitas, tomando-se uma casa paterna para Eleazar, e outra para Itamar.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 7, 'Assim a primeira sorte saiu a Jeoiaribe, a segunda a Jedaías,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 8, 'a terceira a Harim, a quarta a Seorim,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 9, 'a quinta a Malquias, a sexta a Miamim,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 10, 'a sétima a Hacoz, a oitava a Abias,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 11, 'a nona a Jesuá, a décima a Secanias,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 12, 'a undécima a Eliasibe, a duodécima a Jaquim,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 13, 'a décima terceira a Hupá, a décima quarta a Jesebeabe,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 14, 'a décima quinta a Bilga, a décima sexta a Imer,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 15, 'a décima sétima a Hezir, a décima oitava a Hapizes,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 16, 'a décima nona a Petaías, a vigésima a Jeezquel,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 17, 'a vigésima primeira a Jaquim, a vigésima segunda a Gamul,', 1, CURRENT_TIMESTAMP, false),
(13, 24, 18, 'a vigésima terceira a Delaías, a vigésima quarta a Maazias.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 19, 'Esta foi a distribuição deles no seu serviço, para entrarem na casa do Senhor, segundo lhes fora ordenado por Arão, seu pai, como o Senhor Deus de Israel lhe tinha mandado.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 20, 'Do restante dos filhos de Levi: dos filhos de Anrão, Subael; dos filhos de Subael, Jedeías.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 21, 'Quanto a Reabias: dos filhos de Reabias, Issijá o chefe;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 22, 'dos izaritas, Selomote; dos filhos de Selomote, Jaate;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 23, 'dos filhos de Hebrom: Jerias o chefe, Amarias o segundo, Jaaziel o terceiro, Jecameão o quarto;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 24, 'dos filhos de Uziel, Mica; dos filhos de Mica, Samir;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 25, 'o irmão de Mica, Issijá; dos filhos de Issijá, Zacarias.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 26, 'Os filhos de Merári, Mali e Musi; dos filhos de Jaazias, Beno;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 27, 'os filhos de Merári: de Jaazias: Beno, Soão, Zacur e Ibri;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 28, 'de Mali, Eleazar; e este não teve filhos.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 29, 'Quanto a Quis: dos filhos de Quis, Jerameel;', 1, CURRENT_TIMESTAMP, false),
(13, 24, 30, 'e os filhos de Musi: Mali, Eder e Jerimote. Esses foram os filhos dos levitas, segundo as suas casas paternas.', 1, CURRENT_TIMESTAMP, false),
(13, 24, 31, 'Estes também, como seus irmãos, os filhos de Arão, lançaram sortes diante do rei Davi, de Zadoque, de Aimeleque, e dos chefes das casas paternas entre os sacerdotes e entre os levitas; assim fizeram, tanto para o chefe de casa paterna, como para o seu irmão menor.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 1, 'Também Davi juntamente com os capitães do exército, separou para o serviço alguns dos filhos de Asafe, e de Hemã, e de Jedútum para profetizarem com harpas, com alaúdes, e com címbalos. Este foi o número dos homens que fizeram a obra: segundo o seu serviço:', 1, CURRENT_TIMESTAMP, false),
(13, 25, 2, 'dos filhos de Asafe: Zacur, José, Netanias e Asarela, filhos de Asafe, a cargo de Asafe, que profetizava sob as ordens do rei.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 3, 'De Jedútum os filhos de Jedútun: Gedalias, e Zeri, Jesaías, Hasabias e Matitias, seis, a cargo de seu pai, Jedútum que profetizava com a harpa, louvando ao Senhor e dando-lhe graças.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 4, 'De Hemã, os filhos de Hemã: Buquias, Matanias, Uziel, Sebuel, Jerimote, Hananias, Hanâni, Eliatá, Gidálti, e Românti-Ezer, Josbecasa, Malóti, Hotir e Maaziote.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 5, 'Todos estes foram filhos de Hemã, o vidente do rei, segundo a promessa de Deus de exaltá-lo. Deus dera a Hemã catorze filhos e três filhas.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 6, 'Todos estes estavam sob a direção de seu pai para a música na casa do Senhor, com címbalos, alaúdes e harpas para o serviço da casa de Deus. E Asafe, Jedútun e Hemã estavam sob as ordens do rei.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 7, 'Era o número deles, juntamente com seus irmãos instruídos em cantar ao Senhor, todos eles mestres, duzentos e oitenta e oito.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 8, 'E determinaram os seus cargos por sortes, todos igualmente, tanto o pequeno como o grande, assim o mestre como o discípulo.', 1, CURRENT_TIMESTAMP, false),
(13, 25, 9, 'A primeira sorte, que era de Asafe, saiu a José; a segunda a Gedalias, que com seus irmãos e filhos eram doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 10, 'a terceira a Zacur, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 11, 'a quarta a Izri, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 12, 'a quinta a Netanias, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 13, 'a sexta a Buquias, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 14, 'a sétima a Jesarela, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 15, 'a oitava a Jesaías, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 16, 'a nona a Matanias, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 17, 'a décima a Simei, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 18, 'a undécima a Azarel, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 19, 'a duodécima a Hasabias, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 20, 'a décima terceira a Subael, seus filhos: e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 21, 'a décima quarta a Matitias, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 22, 'a décima quinta a Jerimote, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 23, 'a décima sexta a Hananias, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 24, 'a décima sétima a Josbecasa, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 25, 'a décima oitava a Hanâni, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 26, 'a décima nona a Malóti, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 27, 'a vigésima a Eliatá, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 28, 'a vigésima primeira a Hotir, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 29, 'a vigésima segunda a Gidálti, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 30, 'a vigésima terceira a Maaziote, seus filhos e irmãos, doze;', 1, CURRENT_TIMESTAMP, false),
(13, 25, 31, 'a vigésima quarta a Românti-Ezer, seus filhos e irmãos, doze.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 1, 'Quanto às turmas dos porteiros: Meselemias, filho de Coré, dos filhos de Asafe.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 2, 'E foram os filhos de Meselemias: Zacarias o primogênito, Jediael o segundo, Zebadias o terceiro, Jatniel o quarto,', 1, CURRENT_TIMESTAMP, false),
(13, 26, 3, 'Elão o quinto, Jeoanã o sexto, Elioenai, o sétimo.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 4, 'Os filhos de Obede-Edom foram: Semaías o primogênito, Jeozabade o segundo, Joá o terceiro, Sacar o quarto, Netanel o quinto,', 1, CURRENT_TIMESTAMP, false),
(13, 26, 5, 'Amiel o sexto, Issacar o sétimo, Peuletai o oitavo; porque Deus o tinha abençoado.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 6, 'Também a seu filho Semaías nasceram filhos, que dominaram sobre a casa de seu pai porque foram varões valentes.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 7, 'Os filhos de Semaías: Otni, Rafael, Obede e Elzabade, com seus irmãos, homens valentes, Eliú e Semaquias.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 8, 'Todos estes foram dos filhos de Obede-Edom; eles e seus filhos e irmãos, homens capazes e de força para o serviço, eram sessenta e dois, de Obede-Edom.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 9, 'Os filhos e os irmãos de Meselemias, homens valentes, foram dezoito.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 10, 'De Hosa, dos filhos de Merári, foram filhos: Sínri o chefe {ainda que não era o primogênito, contudo seu pai o constituiu chefe},', 1, CURRENT_TIMESTAMP, false),
(13, 26, 11, 'Hilquias o segundo, Tebalias o terceiro, e Zacarias o quarto; todos os filhos e irmãos de Hosa foram treze.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 12, 'Destes se fizeram as turmas dos porteiros, isto é, dos homens principais, tendo cargos como seus irmãos, para ministrarem na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 13, 'E lançaram sortes, assim os pequenos como os grandes, segundo as suas casas paternas, para cada porta.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 14, 'E caiu a sorte do oriente a Selemias. Depois se lançou a sorte por seu filho Zacarias, conselheiro entendido, e saiu-lhe a do norte.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 15, 'A Obede-Edom a do sul; e a seus filhos a casa dos depósitos.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 16, 'A Supim e Hosa a do ocidente; perto da porta Salequete, junto ao caminho da subida, uma guarda defronte de outra guarda.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 17, 'Ao oriente estavam seis levitas, ao norte quatro por dia, ao sul quatro por dia, porém para a casa dos depósitos de dois em dois.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 18, 'Para Parbar, ao ocidente, quatro junto ao caminho, e dois junto a Parbar.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 19, 'Essas foram as turmas dos porteiros dentre os filhos dos coraítas, e dentre os filhos de Merári.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 20, 'E dos levitas, Aías tinha cargo dos tesouros da casa de Deus e dos tesouros das ofertas dedicadas.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 21, 'Quanto aos filhos de Ladã, os filhos dos gersonitas que pertencem a Ladã, chefes das casas paternas de Ladã; Jeiéli.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 22, 'Os filhos de Jeiéli: Zetão e Joel, seu irmão; estes tinham cargo dos tesouros da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 23, 'Dos anramitas, dos izaritas:, dos hebronitas, dos uzielitas.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 24, 'Sebuel, filho de Gérsom o filho de Moisés, que era chefe dos tesouros.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 25, 'Seus irmãos: de Eliézer foi filho Reabias, de quem foi filho Jesaías, de quem foi filho Jorão, de quem foi filho Zicri, de quem foi filho Selomote.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 26, 'Este Selomote e seus irmãos tinham a seu cargo todos os tesouros das ofertas dedicadas, que o rei Davi e os chefes das casas paternas, chefes de milhares, e de centenas, e chefes do exército tinham dedicado.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 27, 'Dos despojos das guerras dedicaram ofertas para consertarem a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 28, 'Também tudo quanto fora dedicado por Samuel, o vidente, Saul, filho de Quis, Abner, filho de Ner, e Joabe, filho de Zeruia, isto é, tudo quanto qualquer havia dedicado estava sob a guarda de Selomote e seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 29, 'Dos izaritas, Quenanias e seus filhos foram postos sobre Israel para os negócios de fora, como oficiais e juízes.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 30, 'Dos hebronitas foram Hasabias e seus irmãos, homens valentes, mil e setecentos, que tinham a seu cargo Israel, ao ocidente do Jordão, em todos os negócios do Senhor e no serviço do rei.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 31, 'Jerias era o chefe dos hebronitas, segundo as suas gerações conforme as casas paternas. No ano quarenta do reino de Davi foram procurados, e acharam-se entre eles varões valentes em Jazer de Gileade.', 1, CURRENT_TIMESTAMP, false),
(13, 26, 32, 'A ele e a seus irmãos, dois mil e setecentos homens valentes, chefes das casas paternas, o rei Davi constituiu sobre os rubenitas e os gaditas, e a meia tribo dos manassitas, para todos os serviços de Deus, e para todos os negócios do rei.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 1, 'Ora, os filhos de Israel segundo o seu número, os chefes das casas paternas, e os chefes dos milhares e das centenas, com os seus oficiais, que serviam ao rei em todos os negócios das turmas que entravam e saíam de mês em mês, em todos os meses do ano, eram em cada turma vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 2, 'sobre a primeira turma, no primeiro mês, estava Jasobeão, filho de Zabdiel; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 3, 'Era ele descendente de Pérez, e chefe de todos os comandantes do exército para o primeiro mês.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 4, 'Sobre a turma do segundo mês estava Dodai, o aoíta, com a sua turma, cujo chefe era Miclote; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 5, 'O terceiro comandante do exército, para o terceiro mês, era o chefe Benaías, filho do sacerdote Jeoiada; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 6, 'Este é aquele Benaías que era o varão valente entre os trinta e comandava os trinta; e da sua turma era seu filho Amizabade.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 7, 'O quarto, do quarto mês, era Asael, irmão de Joabe, e depois dele Zebadia; seu filho; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 8, 'O quinto, do quinto mês:, Samute, o israíta; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 9, 'O sexto, do sexto mês: Ira, filho de Iques, o tecoíta; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 10, 'O sétimo, do sétimo mês:, Helez, o pelonita, descendente de Efraim; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 11, 'O oitavo, do oitavo mês, Sibecai, o husatita, dos zeraítas; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 12, 'O nono, do nono mês, Abiezer, o anatotita, dos benjamitas; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 13, 'O décimo, do décimo mês, Maarai, o netofatita, dos zeraítas; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 14, 'O undécimo, do undécimo mês, Benaías, o piratonita, dos filhos de Efraim; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 15, 'O duodécimo, do duodécimo mês, Heldai, o netofatita, de Otniel; e em sua turma havia vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 16, 'Sobre as tribos de Israel estavam estes: sobre os rubenitas era chefe Eliézer, filho de Zicri; sobre os simeonitas, Sefatias, filho de Maacá;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 17, 'sobre os levitas, Hasabias, filho de Quemuel; sobre os aronitas, Zadoque;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 18, 'sobre Judá, , Eliu:, um dos irmãos de Davi; sobre Issacar, Onri, filho de Micael;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 19, 'sobre Zebulom, Ismaías, filho de Obadias; sobre Naftali, Jerimote, filho de Azrriel;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 20, 'sobre os filhos de Efraim, Oséias, filho de Azazias; sobre a meia tribo de Manassés, Joel, filho de Pedaías;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 21, 'sobre a meia tribo de Manassés em Gileade, Ido, filho de Zacarias; sobre Benjamim, Jaasiel, filho de Abner;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 22, 'sobre Dã, Azarel, filho de Jeroão. Esses eram os chefes das tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 23, 'Não tomou, porém, Davi o número dos de vinte anos para baixo, porquanto o Senhor tinha dito que havia de multiplicar Israel como as estrelas do céu.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 24, 'Joabe, filho de Zeruia, tinha começado a numerá-los, porém não acabou, porquanto viera por isso ira sobre Israel; pelo que o número não foi posto no livro das crônicas do rei Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 25, 'Sobre os tesouros do rei estava Azmavete, filho de Adiel; sobre os tesouros dos campos, das cidades, das aldeias e das torres, Jônatas, filho de Uzias;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 26, 'sobre os que faziam a obra do campo, na lavoura da terra, Ezri, filho de Quelube;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 27, 'sobre as vinhas, Simei, o ramatita; sobre o produto das vides nas adegas do vinho, Zabdi, o sifmita;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 28, 'sobre os olivais e sicômoros que havia nas campinas, Baal-Hanã, o gederita; sobre os armazéns do azeite, Joás;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 29, 'sobre o gado que pastava em Sarom, Sitrai, o saronita; sobre o gado dos vales, Safate, filho de Adlai;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 30, 'sobre os camelos, Obil, o ismaelita; sobre as jumentas, Jedeías, o meronotita;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 31, 'e sobre o gado miúdo, Jaziz, o hagrita. Todos esses eram os intendentes dos bens do rei Davi.', 1, CURRENT_TIMESTAMP, false),
(13, 27, 32, 'Jônatas, tio de Davi, era conselheiro, homem entendido, e escriba; ele e Jeiel, filho de Hacmôni, assistiam os filhos do rei;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 33, 'Aitofel era conselheiro do rei; Husai, o arquita, era amigo o rei;', 1, CURRENT_TIMESTAMP, false),
(13, 27, 34, 'depois de Aitotel, Jeoiada, filho de Benaías, e Abiatar foram conselheiros; e Joabe era chefe do exército do rei.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 1, 'Ora, Davi convocou a Jerusalém todos os chefes de Israel, os chefes das tribos, os chefes das turmas que serviam o rei, os chefes de mil, e os chefes de cem, e os intendentes de todos os bens e possessões do rei e de seus filhos, como também os oficiais e os homens mais valorosos e valentes.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 2, 'Então o rei Davi se pôs em pé, e disse: Ouvi-me, irmãos meus e povo meu. Em meu coração havia eu proposto edificar uma casa de repouso para a arca do pacto de Senhor, e para o escabelo dos pés do nosso Deus, e tinha feito os preparativos para a edificar.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 3, 'Mas Deus me disse: Tu não edificarás casa ao meu nome, porque és homem de guerra, e tens derramado muito sangue.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 4, 'Todavia o Senhor Deus de Israel escolheu-me de toda a casa de meu pai, para ser rei sobre Israel para sempre; porque a Judá escolheu por príncipe, e na casa de Judá a casa de meu pai, e entre os filhos de meu pai se agradou de mim para me fazer rei sobre todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 5, 'E, de todos os meus filhos {porque muitos filhos me deu o Senhor}, escolheu ele o meu filho Salomão para se assentar no trono do reino do Senhor sobre Israel,', 1, CURRENT_TIMESTAMP, false),
(13, 28, 6, 'e me disse: Teu filho Salomão edificará a minha casa e os meus átrios, porque o escolhi para me ser por filho, e eu lhe serei por pai.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 7, 'Estabelecerei o seu reino para sempre, se ele perseverar em cumprir os meus mandamentos e os meus juízos, como o faz no dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 8, 'Agora, pois, à vista de todo o Israel, a congregação do Senhor, e em presença de nosso Deus, que nos ouve, observai e buscai todos os mandamentos do Senhor vosso Deus, para que possuais esta boa terra, e a deixeis por herança a vossos filhos depois de, vos, para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 9, 'E tu, meu filho Salomão, conhece o Deus de teu pai, e serve-o com coração perfeito e espírito voluntário; porque o Senhor esquadrinha todos os corações, e penetra todos os desígnios e pensamentos. Se o buscares, será achado de ti; porém, se o deixares, rejeitar-te-á para sempre.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 10, 'Agora toma cuidado, porque o Senhor te escolheu para edificares uma casa para o santuário; esforça-te, e faze a obra.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 11, 'Então Davi deu a Salomão, seu filho, o modelo do alpendre com as suas casas, as suas tesourarias, os seus cenáculos e as suas recâmaras interiores, como também da casa do propiciatório;', 1, CURRENT_TIMESTAMP, false),
(13, 28, 12, 'e também o modelo de tudo o que tinha em mente para os átrios da casa do Senhor, para todas as câmaras em redor, para os tesouros da casa de Deus e para os tesouros das coisas sagradas;', 1, CURRENT_TIMESTAMP, false),
(13, 28, 13, 'também para as turmas dos sacerdotes e dos levitas, para toda a obra do serviço da casa do Senhor e para todos os vasos do serviço da casa do Senhor,', 1, CURRENT_TIMESTAMP, false),
(13, 28, 14, 'especificando o peso do ouro para os vasos de ouro, para todos os vasos de cada espécie de serviço, o peso da prata para todos os vasos de prata, para todos os vasos de cada espécie de serviço;', 1, CURRENT_TIMESTAMP, false),
(13, 28, 15, 'o peso para os castiçais de ouro e suas lâmpadas, o peso do ouro para cada castiçal e as suas lâmpadas, e o peso da prata para os castiçais de prata, para cada castiçal e as suas lâmpadas, segundo o uso de cada castiçal;', 1, CURRENT_TIMESTAMP, false),
(13, 28, 16, 'o peso do ouro para as mesas dos pães da proposição, para cada mesa; como também da prata para as mesas de prata;', 1, CURRENT_TIMESTAMP, false),
(13, 28, 17, 'e o ouro puro para os garfos, as bacias e os jarros; para as taças de ouro, o peso para cada taça; como também para as taças de prata, o peso para cada taça,', 1, CURRENT_TIMESTAMP, false),
(13, 28, 18, 'e para o altar do incenso, o peso de ouro refinado; como também o ouro para o modelo do carro dos querubins que, de asas estendidas, cobririam a arca do pacto do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 19, 'Tudo isso se me fez entender, disse Davi, por escrito da mão do Senhor, a saber, todas as obras deste modelo.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 20, 'Disse, pois, Davi a seu filho Salomão: Esforça-te e tem bom ânimo, e faze a obra; não temas, nem te desalentes, pois o Senhor Deus, meu Deus, é contigo; não te deixará, nem te desamparará, até que seja acabada toda a obra para o serviço da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(13, 28, 21, 'Eis aí as turmas dos sacerdotes e dos levitas para todo o serviço da casa de Deus; e estará contigo para toda a obra todo homem bem disposto e perito em qualquer espécie de serviço; também os chefes e todo o povo estarão inteiramente às tuas ordens.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 1, 'Disse mais o rei Davi a toda a congregação: Salomão, meu filho, o único a quem Deus escolheu, é ainda moço e tenro, e a obra é grande, porque o palácio não é para homem, mas para o Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 2, 'Eu, pois, com todas as minhas forças tenho preparado para a casa de meu Deus o ouro para as obras de ouro, a prata para as de prata, o bronze para as de bronze, o ferro para as de ferro e a madeira para as de madeira; pedras de oberilo, pedras de engaste, pedras de ornato, pedras de várias cores, toda sorte de pedras preciosas, e mármore em abundância.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 3, 'Além disso, porque pus o meu afeto na casa de meu Deus, o ouro e prata particular que tenho, eu o dou para a casa do meu Deus, afora tudo quanto tenho preparado para a casa do santuário:', 1, CURRENT_TIMESTAMP, false),
(13, 29, 4, 'três mil talentos de ouro, do ouro de Ofir, e sete mil talentos de prata refinada, para cobrir as paredes das casas;', 1, CURRENT_TIMESTAMP, false),
(13, 29, 5, 'ouro para as obras e ouro, e prata para as de prata, para toda a obra a ser feita por mão de artífices. Quem, pois, está disposto a fazer oferta voluntária, consagrando-se hoje ao Senhor?', 1, CURRENT_TIMESTAMP, false),
(13, 29, 6, 'Então os chefes das casas paternas, os chefes das tribos de Israel, e os chefes de mil e de cem, juntamente com os intendentes da obra do rei, fizeram ofertas voluntárias;', 1, CURRENT_TIMESTAMP, false),
(13, 29, 7, 'e deram para o serviço da casa de Deus cinco mil talentos e dez mil , dracmas de ouro, e dez mil talentos de prata, dezoito mil talentos de bronze, e cem mil talentos de ferro.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 8, 'E os que tinham pedras preciosas deram-nas para o tesouro da casa do Senhor, que estava ao cargo de Jeiel, o gersonita.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 9, 'E o povo se alegrou das ofertas voluntárias que estes fizeram, pois de um coração perfeito as haviam oferecido ao Senhor; e também o rei Davi teve grande alegria.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 10, 'Pelo que Davi bendisse ao Senhor na presença de toda a congregação, dizendo: Bendito és tu, ó Senhor, Deus de nosso pai Israel, de eternidade em eternidade.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 11, 'Tua é, ó Senhor, a grandeza, e o poder, e a glória, e a vitória, e a majestade, porque teu é tudo quanto há no céu e na terra; teu é, ó Senhor, o reino, e tu te exaltaste como chefe sobre todos.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 12, 'Tanto riquezas como honra vêm de ti, tu dominas sobre tudo, e na tua mão há força e poder; na tua mão está o engrandecer e o dar força a tudo.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 13, 'Agora, pois, ó nosso Deus, graças te damos, e louvamos o teu glorioso nome.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 14, 'Mas quem sou eu, e quem é o meu povo, para que pudéssemos fazer ofertas tão voluntariamente? Porque tudo vem de ti, e do que é teu to damos.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 15, 'Porque somos estrangeiros diante de ti e peregrinos, como o foram todos os nossos pais; como a sombra são os nossos dias sobre a terra, e não há permanência:', 1, CURRENT_TIMESTAMP, false),
(13, 29, 16, 'Ó Senhor, Deus nosso, toda esta abundância, que preparamos para te edificar uma casa ao teu santo nome, vem da tua mão, e é toda tua.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 17, 'E bem sei, Deus meu, que tu sondas o coração, e que te agradas da retidão. Na sinceridade de meu coração voluntariamente ofereci todas estas coisas; e agora vi com alegria que o teu povo, que se acha aqui, ofereceu voluntariamente.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 18, 'O Senhor, Deus de nossos pais Abraão, Isaque e Israel, conserva para sempre no coração do teu povo estas disposições e estes pensamentos, e encaminha o seu coração para ti.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 19, 'E a Salomão, meu filho, dá um coração perfeito, para guardar os teus mandamentos, os teus testemunhes e os teus estatuto, e para fazer todas estas coisas, e para edificar o palácio para o qual tenha providenciado.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 20, 'Então disse Davi a toda a congregação: Bendizei ao Senhor vosso Deus! E toda a congregação bendisse ao Senhor Deus de seus pais, e inclinaram-se e prostraram-se perante a Senhor e perante o rei.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 21, 'E no dia seguinte imolaram sacrifícios ao Senhor e lhe ofereceram em holocausto mil novilhos, mil carneiros, mil cordeiros, com as suas libações, e sacrifícios em abundância a favor de todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 22, 'E comeram e beberam naquele dia perante o Senhor, com grande gozo. E pela segunda vez proclamaram rei a Salomão, filho de Davi, e o ungiram ao Senhor para ser príncipe, e a Zadoque para ser sacerdote.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 23, 'Assim Salomão se assentou no trono do Senhor, como rei em lugar de seu pai Davi, e prosperou; e todo o Israel lhe prestou obediência.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 24, 'E todos os chefes, e os homens poderosos, e também todos os filhos do rei Davi se submeteram ao rei Salomão.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 25, 'E o Senhor engrandeceu muito a Salomão à vista de todo o Israel, e deu-lhe tal majestade real qual antes dele não teve nenhum rei em Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 26, 'Assim Davi, filho de Jessé, reinou sobre todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 27, 'O tempo que reinou sobre Israel foi quarenta anos; em Hebrom reinou sete anos, e em Jerusalém trinta e três.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 28, 'E morreu numa boa velhice, cheio de dias, riquezas e honra; e Salomão, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(13, 29, 29, 'Ora, os atos do rei Davi, desde os primeiros até os últimos, estão escritos nas crônicas de Samuel, o vidente, e nas crônicas do profeta Natã, e nas crônicas de Gade, o vidente,', 1, CURRENT_TIMESTAMP, false),
(13, 29, 30, 'com todo o seu reinado e o seu poder e os acontecimentos que sobrevieram a ele, a Israel, e a todos os reinos daquelas terras.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 1, 'O que era desde o princípio, o que ouvimos, o que vimos com os nossos olhos, o que contemplamos e as nossas mãos apalparam, a respeito do Verbo da vida', 1, CURRENT_TIMESTAMP, false),
(62, 1, 2, '{pois a vida foi manifestada, e nós a temos visto, e dela testificamos, e vos anunciamos a vida eterna, que estava com o Pai, e a nós foi manifestada};', 1, CURRENT_TIMESTAMP, false),
(62, 1, 3, 'sim, o que vimos e ouvimos, isso vos anunciamos, para que vós também tenhais comunhão conosco; e a nossa comunhão é com o Pai, e com seu Filho Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 4, 'Estas coisas vos escrevemos, para que o nosso gozo seja completo.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 5, 'E esta é a mensagem que dele ouvimos, e vos anunciamos: que Deus é luz, e nele não há trevas nenhumas.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 6, 'Se dissermos que temos comunhão com ele, e andarmos nas trevas, mentimos, e não praticamos a verdade;', 1, CURRENT_TIMESTAMP, false),
(62, 1, 7, 'mas, se andarmos na luz, como ele na luz está, temos comunhão uns com os outros, e o sangue de Jesus seu Filho nos purifica de todo pecado.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 8, 'Se dissermos que não temos pecado nenhum, enganamo-nos a nós mesmos, e a verdade não está em nós.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 9, 'Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça.', 1, CURRENT_TIMESTAMP, false),
(62, 1, 10, 'Se dissermos que não temos cometido pecado, fazemo-lo mentiroso, e a sua palavra não está em nós.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 1, 'Meus filhinhos, estas coisas vos escrevo, para que não pequeis; mas, se alguém pecar, temos um Advogado para com o Pai, Jesus Cristo, o justo.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 2, 'E ele é a propiciação pelos nossos pecados, e não somente pelos nossos, mas também pelos de todo o mundo.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 3, 'E nisto sabemos que o conhecemos; se guardamos os seus mandamentos.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 4, 'Aquele que diz: Eu o conheço, e não guarda os seus mandamentos, é mentiroso, e nele não está a verdade;', 1, CURRENT_TIMESTAMP, false),
(62, 2, 5, 'mas qualquer que guarda a sua palavra, nele realmente se tem aperfeiçoado o amor de Deus. E nisto sabemos que estamos nele;', 1, CURRENT_TIMESTAMP, false),
(62, 2, 6, 'aquele que diz estar nele, também deve andar como ele andou.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 7, 'Amados, não vos escrevo mandamento novo, mas um mandamento antigo, que tendes desde o princípio. Este mandamento antigo é a palavra que ouvistes.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 8, 'Contudo é um novo mandamento que vos escrevo, o qual é verdadeiro nele e em vós; porque as trevas vão passando, e já brilha a verdadeira luz.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 9, 'Aquele que diz estar na luz, e odeia a seu irmão, até agora está nas trevas.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 10, 'Aquele que ama a seu irmão permanece na luz, e nele não há tropeço.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 11, 'Mas aquele que odeia a seu irmão está nas trevas, e anda nas trevas, e não sabe para onde vai; porque as trevas lhe cegaram os olhos.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 12, 'Filhinhos, eu vos escrevo, porque os vossos pecados são perdoados por amor do seu nome.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 13, 'Pais, eu vos escrevo, porque conheceis aquele que é desde o princípio. Jovens, eu vos escrevo, porque vencestes o Maligno.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 14, 'Eu vos escrevi, meninos, porque conheceis o Pai. Eu vos escrevi, pais, porque conheceis aquele que é desde o princípio. Eu escrevi, jovens, porque sois fortes, e a palavra de Deus permanece em vós, e já vencestes o Maligno.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 15, 'Não ameis o mundo, nem o que há no mundo. Se alguém ama o mundo, o amor do Pai não está nele.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 16, 'Porque tudo o que há no mundo, a concupiscência da carne, a concupiscência dos olhos e a soberba da vida, não vem do Pai, mas sim do mundo.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 17, 'Ora, o mundo passa, e a sua concupiscência; mas aquele que faz a vontade de Deus, permanece para sempre.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 18, 'Filhinhos, esta é a última hora; e, conforme ouvistes que vem o anticristo, já muitos anticristos se têm levantado; por onde conhecemos que é a última hora.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 19, 'Saíram dentre nós, mas não eram dos nossos; porque, se fossem dos nossos, teriam permanecido conosco; mas todos eles saíram para que se manifestasse que não são dos nossos.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 20, 'Ora, vós tendes a unção da parte do Santo, e todos tendes conhecimento.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 21, 'Não vos escrevi porque não soubésseis a verdade, mas porque a sabeis, e porque nenhuma mentira vem da verdade.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 22, 'Quem é o mentiroso, senão aquele que nega que Jesus é o Cristo? Esse mesmo é o anticristo, esse que nega o Pai e o Filho.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 23, 'Qualquer que nega o Filho, também não tem o Pai; aquele que confessa o Filho, tem também o Pai.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 24, 'Portanto, o que desde o princípio ouvistes, permaneça em vós. Se em vós permanecer o que desde o princípio ouvistes, também vós permanecereis no Filho e no Pai.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 25, 'E esta é a promessa que ele nos fez: a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 26, 'Estas coisas vos escrevo a respeito daqueles que vos querem enganar.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 27, 'E quanto a vós, a unção que dele recebestes fica em vós, e não tendes necessidade de que alguém vos ensine; mas, como a sua unção vos ensina a respeito de todas as coisas, e é verdadeira, e não é mentira, como vos ensinou ela, assim nele permanecei.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 28, 'E agora, filhinhos, permanecei nele; para que, quando ele se manifestar, tenhamos confiança, e não fiquemos confundidos diante dele na sua vinda.', 1, CURRENT_TIMESTAMP, false),
(62, 2, 29, 'Se sabeis que ele é justo, sabeis que todo aquele que pratica a justiça é nascido dele.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 1, 'Vede que grande amor nos tem concedido o Pai: que fôssemos chamados filhos de Deus; e nós o somos. Por isso o mundo não nos conhece; porque não conheceu a ele.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 2, 'Amados, agora somos filhos de Deus, e ainda não é manifesto o que havemos de ser. Mas sabemos que, quando ele se manifestar, seremos semelhantes a ele; porque assim como é, o veremos.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 3, 'E todo o que nele tem esta esperança, purifica-se a si mesmo, assim como ele é puro.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 4, 'Todo aquele que vive habitualmente no pecado também vive na rebeldia, pois o pecado é rebeldia.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 5, 'E bem sabeis que ele se manifestou para tirar os pecados; e nele não há pecado.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 6, 'Todo o que permanece nele não vive pecando; todo o que vive pecando não o viu nem o conhece.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 7, 'Filhinhos, ninguém vos engane; quem pratica a justiça é justo, assim como ele é justo;', 1, CURRENT_TIMESTAMP, false),
(62, 3, 8, 'quem comete pecado é do Diabo; porque o Diabo peca desde o princípio. Para isto o Filho de Deus se manifestou: para destruir as obras do Diabo.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 9, 'Aquele que é nascido de Deus não peca habitualmente; porque a semente de Deus permanece nele, e não pode continuar no pecado, porque é nascido de Deus.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 10, 'Nisto são manifestos os filhos de Deus, e os filhos do Diabo: quem não pratica a justiça não é de Deus, nem o que não ama a seu irmão.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 11, 'Porque esta é a mensagem que ouvistes desde o princípio, que nos amemos uns aos outros,', 1, CURRENT_TIMESTAMP, false),
(62, 3, 12, 'não sendo como Caim, que era do Maligno, e matou a seu irmão. E por que o matou? Porque as suas obras eram más e as de seu irmão justas.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 13, 'Meus irmãos, não vos admireis se o mundo vos odeia.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 14, 'Nós sabemos que já passamos da morte para a vida, porque amamos os irmãos. Quem não ama permanece na morte.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 15, 'Todo o que odeia a seu irmão é homicida; e vós sabeis que nenhum homicida tem a vida eterna permanecendo nele.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 16, 'Nisto conhecemos o amor: que Cristo deu a sua vida por nós; e nós devemos dar a vida pelos irmãos.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 17, 'Quem, pois, tiver bens do mundo, e, vendo o seu irmão necessitando, lhe fechar o seu coração, como permanece nele o amor de Deus?', 1, CURRENT_TIMESTAMP, false),
(62, 3, 18, 'Filhinhos, não amemos de palavra, nem de língua, mas por obras e em verdade.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 19, 'Nisto conheceremos que somos da verdade, e diante dele tranqüilizaremos o nosso coração;', 1, CURRENT_TIMESTAMP, false),
(62, 3, 20, 'porque se o coração nos condena, maior é Deus do que o nosso coração, e conhece todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 21, 'Amados, se o coração não nos condena, temos confiança para com Deus;', 1, CURRENT_TIMESTAMP, false),
(62, 3, 22, 'e qualquer coisa que lhe pedirmos, dele a receberemos, porque guardamos os seus mandamentos, e fazemos o que é agradável à sua vista.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 23, 'Ora, o seu mandamento é este, que creiamos no nome de seu Filho Jesus Cristo, e nos amemos uns aos outros, como ele nos ordenou.', 1, CURRENT_TIMESTAMP, false),
(62, 3, 24, 'Quem guarda os seus mandamentos, em Deus permanece e Deus nele. E nisto conhecemos que ele permanece em nós: pelo Espírito que nos tem dado.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 1, 'Pedro, apóstolo de Jesus Cristo, aos peregrinos da Dispersão no Ponto, Galácia, Capadócia, Ásia e Bitínia.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 2, 'eleitos segundo a presciência de Deus Pai, na santificação do Espírito, para a obediência e aspersão do sangue de Jesus Cristo: Graça e paz vos sejam multiplicadas.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, que, segundo a sua grande misericórdia, nos regenerou para uma viva esperança, pela ressurreição de Jesus Cristo dentre os mortos,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 4, 'para uma herança incorruptível, incontaminável e imarcescível, reservada nos céus para vós,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 5, 'que pelo poder de Deus sois guardados, mediante a fé, para a salvação que está preparada para se revelar no último tempo;', 1, CURRENT_TIMESTAMP, false),
(60, 1, 6, 'na qual exultais, ainda que agora por um pouco de tempo, sendo necessário, estejais contristados por várias provações,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 7, 'para que a prova da vossa fé, mais preciosa do que o ouro que perece, embora provado pelo fogo, redunde para louvor, glória e honra na revelação de Jesus Cristo;', 1, CURRENT_TIMESTAMP, false),
(60, 1, 8, 'a quem, sem o terdes visto, amais; no qual, sem agora o verdes, mas crendo, exultais com gozo inefável e cheio de glória,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 9, 'alcançando o fim da vossa fé, a salvação das vossas almas.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 10, 'Desta salvação inquiririam e indagaram diligentemente os profetas que profetizaram da graça que para vós era destinada,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 11, 'indagando qual o tempo ou qual a ocasião que o Espírito de Cristo que estava neles indicava, ao predizer os sofrimentos que a Cristo haviam de vir, e a glória que se lhes havia de seguir.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 12, 'Aos quais foi revelado que não para si mesmos, mas para vós, eles ministravam estas coisas que agora vos foram anunciadas por aqueles que, pelo Espírito Santo enviado do céu, vos pregaram o evangelho; para as quais coisas os anjos bem desejam atentar.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 13, 'Portanto, cingindo os lombos do vosso entendimento, sede sóbrios, e esperai inteiramente na graça que se vos oferece na revelação de Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 14, 'Como filhos obedientes, não vos conformeis às concupiscências que antes tínheis na vossa ignorância;', 1, CURRENT_TIMESTAMP, false),
(60, 1, 15, 'mas, como é santo aquele que vos chamou, sede vós também santos em todo o vosso procedimento;', 1, CURRENT_TIMESTAMP, false),
(60, 1, 16, 'porquanto está escrito: Sereis santos, porque eu sou santo.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 17, 'E, se invocais por Pai aquele que, sem acepção de pessoas, julga segundo a obra de cada um, andai em temor durante o tempo da vossa peregrinação,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 18, 'sabendo que não foi com coisas corruptíveis, como prata ou ouro, que fostes resgatados da vossa vã maneira de viver, que por tradição recebestes dos vossos pais,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 19, 'mas com precioso sangue, como de um cordeiro sem defeito e sem mancha, o sangue de Cristo,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 20, 'o qual, na verdade, foi conhecido ainda antes da fundação do mundo, mas manifesto no fim dos tempos por amor de vós,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 21, 'que por ele credes em Deus, que o ressuscitou dentre os mortos e lhe deu glória, de modo que a vossa fé e esperança estivessem em Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 22, 'Já que tendes purificado as vossas almas na obediência à verdade, que leva ao amor fraternal não fingido, de coração amai-vos ardentemente uns aos outros,', 1, CURRENT_TIMESTAMP, false),
(60, 1, 23, 'tendo renascido, não de semente corruptível, mas de incorruptível, pela palavra de Deus, a qual vive e permanece.', 1, CURRENT_TIMESTAMP, false),
(60, 1, 24, 'Porque: Toda a carne é como a erva, e toda a sua glória como a flor da erva. Secou-se a erva, e caiu a sua flor;', 1, CURRENT_TIMESTAMP, false),
(60, 1, 25, 'mas a palavra do Senhor permanece para sempre. E esta é a palavra que vos foi evangelizada.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 1, 'Deixando, pois, toda a malícia, todo o engano, e fingimentos, e invejas, e toda a maledicência,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 2, 'desejai, como meninos recém-nascidos, o leite racional, sem dolo, para que por ele cresçais para a salvação,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 3, 'se é que já provastes que o Senhor é benigno.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 4, 'e, chegando-vos para ele, pedra viva, rejeitada, na verdade, pelos homens, mas, para com Deus eleita e preciosa,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 5, 'sois vós também quais pedras vivas, edificados como casa espiritual para serdes um sacerdócio santo, a fim de oferecerdes sacrifícios espirituais, aceitáveis a Deus por Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 6, 'Por isso é que se acha na Escritura: Eis que ponho em Sião a principal pedra angular, eleita e preciosa, E aquele que nele crê, não será envergonhado.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 7, 'Para vós, portanto, que credes é a honra; mas para aqueles que descrêem, A pedra que os edificadores rejeitaram, Esta foi posta como a pedra angular', 1, CURRENT_TIMESTAMP, false),
(60, 2, 8, 'e Como uma pedra de tropeço e uma rocha de escândalo; porque tropeçam na palavra, sendo desobedientes, para o que também foram postos.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 9, 'Mas vós sois a geração eleita, o sacerdócio real, a nação santa, o povo todo seu para que proclameis as grandezas daquele que vos chamou das trevas para a sua maravilhosa luz,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 10, 'vós que em outro tempo éreis não povo, mas agora sois povo de Deus, vós que não havíeis alcançado misericórdia, mas agora a tendes alcançado.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 11, 'Amados, rogo-vos como peregrinos e forasteiros, que vos abstenhais dos desejos carnais, que combatem contra a alma,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 12, 'tendo o vosso procedimento bom entre os gentios, a fim de que, naquilo em que murmuram de vós como de malfeitores, considerando-vos pelas vossas obras, glorifiquem a Deus no dia da visitação.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 13, 'Sujeitai-vos a toda autoridade humana por amor do Senhor, quer ao rei, como soberano,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 14, 'quer seja ao rei como supremo, quer seja aos governadores, como enviados por ele para castigo dos malfeitores e para louvor dos que fazem o bem.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 15, 'Porque assim é a vontade de Deus, que, fazendo o bem, façais emudecer a ignorância dos homens imprudentes,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 16, 'como livres, e não tendo a vossa liberdade para capa da malícia, mas como servos de Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 17, 'Honrai a todos, amai a irmandade, temei a Deus, respeitai ao rei.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 18, 'Servos, sede sujeitos com todo o temor a vossos senhores, não somente aos bons e moderados, mas também aos perversos.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 19, 'Pois isto é agradável, se alguém, por ser cônscio de Deus, suporta tristezas, padecendo injustamente.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 20, 'Pois que glória é, se sofreis com paciência, quando cometeis pecado, e sois por isso esbofeteados? mas se sofreis com paciência, quando fazeis o bem e por isso padeceis, isto é agradável a Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 21, 'Pois para isto fostes chamados, porquanto também Cristo padeceu por vós, deixando-vos exemplo, para que sigais as suas pisadas.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 22, 'Ele não cometeu pecado, nem tão pouco foi achado engano na sua boca,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 23, 'sendo injuriado, não injuriava, padecendo, não ameaçava, mas entregava-se àquele que julga justamente,', 1, CURRENT_TIMESTAMP, false),
(60, 2, 24, 'levando ele próprio os nossos pecados em seu corpo sobre o madeiro, a fim de que, mortos aos pecados, vivamos à justiça. Por suas feridas fostes sarados.', 1, CURRENT_TIMESTAMP, false),
(60, 2, 25, 'Pois éreis desgarrados como ovelhas, mas agora vos haveis convertido ao Pastor e Bispo das vossas almas.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 1, 'Semelhantemente vós, mulheres, sede submissas a vossos maridos; para que também, se alguns deles não obedecem à palavra, sejam ganhos sem palavra pelo procedimento de suas mulheres,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 2, 'considerando o vosso procedimento casto e com temor.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 3, 'Não seja o seu adorno o enfeite exterior dos cabelos entrançados, das guarnições de renda de ouro ou da compostura dos vestidos,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 4, 'mas seja o homem que está escondido no coração, no vestido incorruptível de um espírito manso e tranqüilo, que é de grande estima diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 5, 'Pois assim se adornavam também noutro tempo as santas mulheres que esperavam em Deus, estando sujeitas a seus maridos,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 6, 'como Sara obedeceu a Abraão, chamando-lhe senhor, da qual vos tornais filhas, se fazeis o bem e não temeis perturbação alguma.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 7, 'Igualmente vós, maridos, vivei com elas segundo a ciência, como sendo vaso mulheril mais fraco, dando-lhes honra como a herdeiras juntamente convosco da graça da vida, para que as vossas orações não sejam impedidas.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 8, 'Finalmente, sede todos de um mesmo sentimento, compassivos, cheios de amor fraternal, misericordiosos, humildes,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 9, 'não retribuindo mal por mal, nem injúria por injúria; mas, pelo contrário, bendizendo, porque para isto fostes chamados, a fim de que recebais bênção por herança.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 10, 'Pois: Quem quer amar a vida E ver os dias bons, Refreie a sua língua do mal E os seus lábios não falem engano,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 11, 'Aparte-se do mal, e faça o bem, Busque a paz e vá após dela;', 1, CURRENT_TIMESTAMP, false),
(60, 3, 12, 'Porque os olhos do Senhor estão sobre os justos E os seus ouvidos atentos às súplicas deles, Mas o rosto do Senhor está sobre os que fazem o mal.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 13, 'Quem é o que vos fará mal, se fordes zelosos do bem?', 1, CURRENT_TIMESTAMP, false),
(60, 3, 14, 'Mas também, se padecerdes por amor da justiça, bem-aventurados sereis; e não temais as suas ameaças, nem vos turbeis;', 1, CURRENT_TIMESTAMP, false),
(60, 3, 15, 'antes santificai em vossos corações a Cristo como Senhor; e estai sempre preparados para responder com mansidão e temor a todo aquele que vos pedir a razão da esperança que há em vós;', 1, CURRENT_TIMESTAMP, false),
(60, 3, 16, 'tendo uma boa consciência, para que, naquilo em que falam mal de vós, fiquem confundidos os que vituperam o vosso bom procedimento em Cristo.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 17, 'Porque melhor é sofrerdes fazendo o bem, se a vontade de Deus assim o quer, do que fazendo o mal.', 1, CURRENT_TIMESTAMP, false),
(60, 3, 18, 'Porque também Cristo morreu uma só vez pelos pecados, o justo pelos injustos, para levar-nos a Deus; sendo, na verdade, morto na carne, mas vivificado no espírito;', 1, CURRENT_TIMESTAMP, false),
(60, 3, 19, 'no qual também foi, e pregou aos espíritos em prisão;', 1, CURRENT_TIMESTAMP, false),
(60, 3, 20, 'os quais noutro tempo foram rebeldes, quando a longanimidade de Deus esperava, nos dias de Noé, enquanto se preparava a arca; na qual poucas, isto é, oito almas se salvaram através da água,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 21, 'que também agora, por uma verdadeira figura-o batismo, vos salva, o qual não é o despojamento da imundícia da carne, mas a indagação de uma boa consciência para com Deus, pela ressurreição de Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(60, 3, 22, 'que está à destra de Deus, tendo subido ao céu; havendo-se-lhe sujeitado os anjos, e as autoridades, e as potestades.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 1, 'Ora pois, já que Cristo padeceu na carne, armai-vos também vós deste mesmo pensamento; porque aquele que padeceu na carne já cessou do pecado;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 2, 'para que, no tempo que ainda vos resta na carne não continueis a viver para as concupiscências dos homens, mas para a vontade de Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 3, 'Porque é bastante que no tempo passado tenhais cumprido a vontade dos gentios, andando em dissoluções, concupiscências, borrachices, glutonarias, bebedices e abomináveis idolatrias.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 4, 'E acham estranho não correrdes com eles no mesmo desenfreamento de dissolução, blasfemando de vós;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 5, 'os quais hão de dar conta ao que está preparado para julgar os vivos e os mortos.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 6, 'Pois é por isto que foi pregado o evangelho até aos mortos, para que, na verdade, fossem julgados segundo os homens na carne, mas vivessem segundo Deus em espírito.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 7, 'Mas já está próximo o fim de todas as coisas; portanto sede sóbrios e vigiai em oração;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 8, 'tendo antes de tudo ardente amor uns para com os outros, porque o amor cobre uma multidão de pecados;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 9, 'sendo hospitaleiros uns para com os outros, sem murmuração;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 10, 'servindo uns aos outros conforme o dom que cada um recebeu, como bons despenseiros da multiforme graça de Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 11, 'Se alguém fala, fale como entregando oráculos de Deus; se alguém ministra, ministre segundo a força que Deus concede; para que em tudo Deus seja glorificado por meio de Jesus Cristo, ma quem pertencem a glória e o domínio para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 12, 'Amados, não estranheis a ardente provação que vem sobre vós para vos experimentar, como se coisa estranha vos acontecesse;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 13, 'mas regozijai-vos por serdes participantes das aflições de Cristo; para que também na revelação da sua glória vos regozijeis e exulteis.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 14, 'Se pelo nome de Cristo sois vituperados, bem-aventurados sois, porque sobre vós repousa o Espírito da glória, o Espírito de Deus.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 15, 'Que nenhum de vós, entretanto, padeça como homicida, ou ladrão, ou malfeitor, ou como quem se entremete em negócios alheios;', 1, CURRENT_TIMESTAMP, false),
(60, 4, 16, 'mas, se padece como cristão, não se envergonhe, antes glorifique a Deus neste nome.', 1, CURRENT_TIMESTAMP, false),
(60, 4, 17, 'Porque já é tempo que comece o julgamento pela casa de Deus; e se começa por nós, qual será o fim daqueles que desobedecem ao evangelho de Deus?', 1, CURRENT_TIMESTAMP, false),
(60, 4, 18, 'E se o justo dificilmente se salva, onde comparecerá o ímpio pecador?', 1, CURRENT_TIMESTAMP, false),
(60, 4, 19, 'Portanto os que sofrem segundo a vontade de Deus confiem as suas almas ao fiel Criador, praticando o bem.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 1, 'Aos anciãos, pois, que há entre vós, rogo eu, que sou ancião com eles e testemunha dos sofrimentos de Cristo, e participante da glória que se há de revelar:', 1, CURRENT_TIMESTAMP, false),
(60, 5, 2, 'Apascentai o rebanho de Deus, que está entre vós, não por força, mas espontaneamente segundo a vontade de Deus; nem por torpe ganância, mas de boa vontade;', 1, CURRENT_TIMESTAMP, false),
(60, 5, 3, 'nem como dominadores sobre os que vos foram confiados, mas servindo de exemplo ao rebanho.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 4, 'E, quando se manifestar o sumo Pastor, recebereis a imarcescível coroa da glória.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 5, 'Semelhantemente vós, os mais moços, sede sujeitos aos mais velhos. E cingi-vos todos de humildade uns para com os outros, porque Deus resiste aos soberbos, mas dá graça aos humildes.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 6, 'Humilhai-vos, pois, debaixo da potente mão de Deus, para que a seu tempo vos exalte;', 1, CURRENT_TIMESTAMP, false),
(60, 5, 7, 'lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 8, 'Sede sóbrios, vigiai. O vosso adversário, o Diabo, anda em derredor, rugindo como leão, e procurando a quem possa tragar;', 1, CURRENT_TIMESTAMP, false),
(60, 5, 9, 'ao qual resisti firmes na fé, sabendo que os mesmos sofrimentos estão-se cumprindo entre os vossos irmãos no mundo.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 10, 'E o Deus de toda a graça, que em Cristo vos chamou à sua eterna glória, depois de haverdes sofrido por um pouco, ele mesmo vos há de aperfeiçoar, confirmar e fortalecer.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 11, 'A ele seja o domínio para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 12, 'Por Silvano, nosso fiel irmão, como o considero, escravo abreviadamente, exortando e testificando que esta é a verdadeira graça de Deus; nela permanecei firmes.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 13, 'A vossa co-eleita em Babilônia vos saúda, como também meu filho Marcos.', 1, CURRENT_TIMESTAMP, false),
(60, 5, 14, 'Saudai-vos uns aos outros com ósculo de amor. Paz seja com todos vós que estais em Cristo.', 1, CURRENT_TIMESTAMP, false),
(52, 1, 1, 'Paulo, Silvano e Timóteo, à igreja dos tessalonicenses, em Deus Pai e no Senhor Jesus Cristo: Graça e paz vos sejam dadas.', 1, CURRENT_TIMESTAMP, false),
(52, 1, 2, 'Sempre damos graças a Deus por vós todos, fazendo menção de vós em nossas orações,', 1, CURRENT_TIMESTAMP, false),
(52, 1, 3, 'lembrando-nos sem cessar da vossa obra de fé, do vosso trabalho de amor e da vossa firmeza de esperança em nosso Senhor Jesus Cristo, diante de nosso Deus e Pai,', 1, CURRENT_TIMESTAMP, false),
(52, 1, 4, 'conhecendo, irmãos, amados de Deus, a vossa eleição;', 1, CURRENT_TIMESTAMP, false),
(52, 1, 5, 'porque o nosso evangelho não foi a vós somente em palavras, mas também em poder, e no Espírito Santo e em plena convicção, como bem sabeis quais fomos entre vós por amor de vós.', 1, CURRENT_TIMESTAMP, false),
(52, 1, 6, 'E vós vos tornastes imitadores nossos e do Senhor, tendo recebido a palavra em muita tribulação, com gozo do Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(52, 1, 7, 'De sorte que vos tornastes modelo para todos os crentes na Macedônia e na Acaia.', 1, CURRENT_TIMESTAMP, false),
(52, 1, 8, 'Porque, partindo de vós fez-se ouvir a palavra do Senhor, não somente na Macedônia e na Acaia, mas também em todos os lugares a vossa fé para com Deus se divulgou, de tal maneira que não temos necessidade de falar coisa alguma;', 1, CURRENT_TIMESTAMP, false),
(52, 1, 9, 'porque eles mesmos anunciam de nós qual a entrada que tivemos entre vós, e como vos convertestes dos ídolos a Deus, para servirdes ao Deus vivo e verdadeiro,', 1, CURRENT_TIMESTAMP, false),
(52, 1, 10, 'e esperardes dos céus a seu Filho, a quem ele ressuscitou dentre os mortos, a saber, Jesus, que nos livra da ira vindoura.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 1, 'Porque vós mesmos sabeis, irmãos, que a nossa entrada entre vós não foi vã;', 1, CURRENT_TIMESTAMP, false),
(52, 2, 2, 'mas, havendo anteriormente padecido e sido maltratados em Filipos, como sabeis, tivemos a confiança em nosso Deus para vos falar o evangelho de Deus em meio de grande combate.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 3, 'Porque a nossa exortação não procede de erro, nem de imundícia, nem é feita com dolo;', 1, CURRENT_TIMESTAMP, false),
(52, 2, 4, 'mas, assim como fomos aprovados por Deus para que o evangelho nos fosse confiado, assim falamos, não para agradar aos homens, mas a Deus, que prova os nossos corações.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 5, 'Pois, nunca usamos de palavras lisonjeiras, como sabeis, nem agimos com intuitos gananciosos. Deus é testemunha,', 1, CURRENT_TIMESTAMP, false),
(52, 2, 6, 'nem buscamos glória de homens, quer de vós, quer de outros, embora pudéssemos, como apóstolos de Cristo, ser-vos pesados;', 1, CURRENT_TIMESTAMP, false),
(52, 2, 7, 'antes nos apresentamos brandos entre vós, qual ama que acaricia seus próprios filhos.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 8, 'Assim nós, sendo-vos tão afeiçoados, de boa vontade desejávamos comunicar-vos não somente o evangelho de Deus, mas ainda as nossas próprias almas; porquanto vos tornastes muito amados de nós.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 9, 'Porque vos lembrais, irmãos, do nosso labor e fadiga; pois, trabalhando noite e dia, para não sermos pesados a nenhum de vós, vos pregamos o evangelho de Deus.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 10, 'Vós e Deus sois testemunhas de quão santa e irrepreensivelmente nos portamos para convosco que credes;', 1, CURRENT_TIMESTAMP, false),
(52, 2, 11, 'assim como sabeis de que modo vos tratávamos a cada um de vós, como um pai a seus filhos,', 1, CURRENT_TIMESTAMP, false),
(52, 2, 12, 'exortando-vos e consolando-vos, e instando que andásseis de um modo digno de Deus, o qual vos chama ao seu reino e glória.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 13, 'Por isso nós também, sem cessar, damos graças a Deus, porquanto vós, havendo recebido a palavra de Deus que de nós ouvistes, a recebestes, não como palavra de homens, mas {segundo ela é na verdade} como palavra de Deus, a qual também opera em vós que credes.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 14, 'Pois vós, irmãos, vos haveis feito imitadores das igrejas de Deus em Cristo Jesus que estão na Judéia; porque também padecestes de vossos próprios concidadãos o mesmo que elas padeceram dos judeus;', 1, CURRENT_TIMESTAMP, false),
(52, 2, 15, 'os quais mataram ao Senhor Jesus, bem como aos profetas, e a nós nos perseguiram, e não agradam a Deus, e são contrários a todos os homens,', 1, CURRENT_TIMESTAMP, false),
(52, 2, 16, 'e nos impedem de falar aos gentios para que sejam salvos; de modo que enchem sempre a medida de seus pecados; mas a ira caiu sobre eles afinal.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 17, 'Nós, porém, irmãos, sendo privados de vós por algum tempo, de vista, mas não de coração, tanto mais procuramos com grande desejo ver o vosso rosto;', 1, CURRENT_TIMESTAMP, false),
(52, 2, 18, 'pelo que quisemos ir ter convosco, pelo menos eu, Paulo, não somente uma vez, mas duas, e Satanás nos impediu.', 1, CURRENT_TIMESTAMP, false),
(52, 2, 19, 'Porque, qual é a nossa esperança, ou gozo, ou coroa de glória, diante de nosso Senhor Jesus na sua vinda? Porventura não o sois vós?', 1, CURRENT_TIMESTAMP, false),
(52, 2, 20, 'Na verdade vós sois a nossa glória e o nosso gozo.', 1, CURRENT_TIMESTAMP, false),
(52, 3, 1, 'Pelo que, não podendo mais suportar o cuidado por vós, achamos por bem ficar sozinhos em Atenas,', 1, CURRENT_TIMESTAMP, false),
(52, 3, 2, 'e enviamos Timóteo, nosso irmão, e ministro de Deus no evangelho de Cristo, para vos fortalecer e vos exortar acerca da vossa fé;', 1, CURRENT_TIMESTAMP, false),
(52, 3, 3, 'para que ninguém seja abalado por estas tribulações; porque vós mesmo sabeis que para isto fomos destinados;', 1, CURRENT_TIMESTAMP, false),
(52, 3, 4, 'pois, quando estávamos ainda convosco, de antemão vos declarávamos que havíamos de padecer tribulações, como sucedeu, e vós o sabeis.', 1, CURRENT_TIMESTAMP, false),
(52, 3, 5, 'Por isso também, não podendo eu esperar mais, mandei saber da vossa fé, receando que o tentador vos tivesse tentado, e o nosso trabalho se houvesse tornado inútil.', 1, CURRENT_TIMESTAMP, false),
(52, 3, 6, 'Mas agora que Timóteo acaba de regressar do vosso meio, trazendo-nos boas notícias da vossa fé e do vosso amor, dizendo que sempre nos tendes em afetuosa lembrança, anelando ver-nos assim como nós também a vós;', 1, CURRENT_TIMESTAMP, false),
(52, 3, 7, 'por isso, irmãos, em toda a nossa necessidade e tribulação, ficamos consolados acerca de vós, pela vossa fé,', 1, CURRENT_TIMESTAMP, false),
(52, 3, 8, 'porque agora vivemos, se estais firmes no Senhor.', 1, CURRENT_TIMESTAMP, false),
(52, 3, 9, 'Pois, que ação de graças podemos render a Deus por vós, por todo o gozo com que nos regozijamos por vossa causa diante do nosso Deus,', 1, CURRENT_TIMESTAMP, false),
(52, 3, 10, 'rogando incessantemente, de noite e de dia, para que possamos ver o vosso rosto e suprir o que falta à vossa fé?', 1, CURRENT_TIMESTAMP, false),
(52, 3, 11, 'Ora, o próprio Deus e Pai nosso e o nosso Senhor Jesus nos abram o caminho até vós,', 1, CURRENT_TIMESTAMP, false),
(52, 3, 12, 'e o Senhor vos faça crescer e abundar em amor uns para com os outros e para com todos, como também nós abundamos para convosco;', 1, CURRENT_TIMESTAMP, false),
(52, 3, 13, 'para vos confirmar os corações, de sorte que sejam irrepreensíveis em santidade diante de nosso Deus e Pai, na vinda de nosso Senhor Jesus com todos os seus santos.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 1, 'Finalmente, irmãos, vos rogamos e exortamos no Senhor Jesus que, como aprendestes de nós de que maneira deveis andar e agradar a Deus, assim como estais fazendo, nisso mesmo abundeis cada vez mais.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 2, 'Pois vós sabeis que preceitos vos temos dado pelo Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 3, 'Porque esta é a vontade de Deus, a saber, a vossa santificação: que vos abstenhais da prostituição,', 1, CURRENT_TIMESTAMP, false),
(52, 4, 4, 'que cada um de vós saiba possuir o seu vaso em santidade e honra,', 1, CURRENT_TIMESTAMP, false),
(52, 4, 5, 'não na paixão da concupiscência, como os gentios que não conhecem a Deus;', 1, CURRENT_TIMESTAMP, false),
(52, 4, 6, 'ninguém iluda ou defraude nisso a seu irmão, porque o Senhor é vingador de todas estas coisas, como também antes vo-lo dissemos e testificamos.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 7, 'Porque Deus não nos chamou para a imundícia, mas para a santificação.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 8, 'Portanto, quem rejeita isso não rejeita ao homem, mas sim a Deus, que vos dá o seu Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 9, 'Quanto, porém, ao amor fraternal, não necessitais de que se vos escreva, visto que vós mesmos sois instruídos por Deus a vos amardes uns aos outros;', 1, CURRENT_TIMESTAMP, false),
(52, 4, 10, 'porque certamente já o fazeis para com todos os irmãos que estão por toda a Macedônia. Exortamo-vos, porém, irmãos, a que ainda nisto abundeis cada vez mais,', 1, CURRENT_TIMESTAMP, false),
(52, 4, 11, 'e procureis viver quietos, tratar dos vossos próprios negócios, e trabalhar com vossas próprias mãos, como já vo-lo mandamos,', 1, CURRENT_TIMESTAMP, false),
(52, 4, 12, 'a fim de que andeis dignamente para com os que estão de fora, e não tenhais necessidade de coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 13, 'Não queremos, porém, irmãos, que sejais ignorantes acerca dos que já dormem, para que não vos entristeçais como os outros que não têm esperança.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 14, 'Porque, se cremos que Jesus morreu e ressurgiu, assim também aos que dormem, Deus, mediante Jesus, os tornará a trazer juntamente com ele.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 15, 'Dizemo-vos, pois, isto pela palavra do Senhor: que nós, os que ficarmos vivos para a vinda do Senhor, de modo algum precederemos os que já dormem.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 16, 'Porque o Senhor mesmo descerá do céu com grande brado, à voz do arcanjo, ao som da trombeta de Deus, e os que morreram em Cristo ressuscitarão primeiro.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 17, 'Depois nós, os que ficarmos vivos seremos arrebatados juntamente com eles, nas nuvens, ao encontro do Senhor nos ares, e assim estaremos para sempre com o Senhor.', 1, CURRENT_TIMESTAMP, false),
(52, 4, 18, 'Portanto, consolai-vos uns aos outros com estas palavras.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 1, 'Mas, irmãos, acerca dos tempos e das épocas não necessitais de que se vos escreva:', 1, CURRENT_TIMESTAMP, false),
(52, 5, 2, 'porque vós mesmos sabeis perfeitamente que o dia do Senhor virá como vem o ladrão de noite;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 3, 'pois quando estiverem dizendo: Paz e segurança! então lhes sobrevirá repentina destruição, como as dores de parto àquela que está grávida; e de modo nenhum escaparão.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 4, 'Mas vós, irmãos, não estais em trevas, para que aquele dia, como ladrão, vos surpreenda;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 5, 'porque todos vós sois filhos da luz e filhos do dia; nós não somos da noite nem das trevas;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 6, 'não durmamos, pois, como os demais, antes vigiemos e sejamos sóbrios.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 7, 'Porque os que dormem, dormem de noite, e os que se embriagam, embriagam-se de noite;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 8, 'mas nós, porque somos do dia, sejamos sóbrios, vestindo-nos da couraça da fé e do amor, e tendo por capacete a esperança da salvação;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 9, 'porque Deus não nos destinou para a ira, mas para alcançarmos a salvação por nosso Senhor Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(52, 5, 10, 'que morreu por nós, para que, quer vigiemos, quer durmamos, vivamos juntamente com ele.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 11, 'Pelo que exortai-vos uns aos outros e edificai-vos uns aos outros, como na verdade o estais fazendo.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 12, 'Ora, rogamo-vos, irmãos, que reconheçais os que trabalham entre vós, presidem sobre vós no Senhor e vos admoestam;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 13, 'e que os tenhais em grande estima e amor, por causa da sua obras. Tende paz entre vós.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 14, 'Exortamo-vos também, irmãos, a que admoesteis os insubordinados, consoleis os desanimados, ampareis os fracos e sejais longânimos para com todos.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 15, 'Vede que ninguém dê a outrem mal por mal, mas segui sempre o bem, uns para com os outros, e para com todos.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 16, 'Regozijai-vos sempre.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 17, 'Orai sem cessar.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 18, 'Em tudo dai graças; porque esta é a vontade de Deus em Cristo Jesus para convosco.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 19, 'Não extingais o Espírito;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 20, 'não desprezeis as profecias,', 1, CURRENT_TIMESTAMP, false),
(52, 5, 21, 'mas ponde tudo à prova. Retende o que é bom;', 1, CURRENT_TIMESTAMP, false),
(52, 5, 22, 'Abstende-vos de toda espécie de mal.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 23, 'E o próprio Deus de paz vos santifique completamente; e o vosso espírito, e alma e corpo sejam plenamente conservados irrepreensíveis para a vinda de nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 24, 'Fiel é o que vos chama, e ele também o fará.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 25, 'Irmãos, orai por nós.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 26, 'Saudai a todos os irmãos com ósculo santo.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 27, 'Pelo Senhor vos conjuro que esta epístola seja lida a todos os irmãos.', 1, CURRENT_TIMESTAMP, false),
(52, 5, 28, 'A graça de nosso Senhor Jesus Cristo seja convosco.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 1, 'Paulo, apóstolo de Cristo Jesus, segundo o mandado de Deus, nosso Salvador, e de Cristo Jesus, esperança nossa.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 2, 'a Timóteo, meu verdadeiro filho na fé: graça, misericórdia e paz da parte de Deus Pai e de Cristo Jesus, nosso Senhor.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 3, 'Como te roguei, quando partia para a Macedônia, que ficasse em Éfeso, para advertires a alguns que não ensinassem doutrina diversa,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 4, 'nem se preocupassem com fábulas ou genealogias intermináveis, pois que produzem antes discussões que edificação para com Deus, que se funda na fé...', 1, CURRENT_TIMESTAMP, false),
(54, 1, 5, 'Mas o fim desta admoestação é o amor que procede de um coração puro, de uma boa consciência, e de uma fé não fingida;', 1, CURRENT_TIMESTAMP, false),
(54, 1, 6, 'das quais coisas alguns se desviaram, e se entregaram a discursos vãos,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 7, 'querendo ser doutores da lei, embora não entendam nem o que dizem nem o que com tanta confiança afirmam.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 8, 'Sabemos, porém, que a lei é boa, se alguém dela usar legitimamente,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 9, 'reconhecendo que a lei não é feita para o justo, mas para os transgressores e insubordinados, os irreverentes e pecadores, os ímpios e profanos, para os parricidas, matricidas e homicidas,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 10, 'para os devassos, os sodomitas, os roubadores de homens, os mentirosos, os perjuros, e para tudo que for contrário à sã doutrina,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 11, 'segundo o evangelho da glória do Deus bendito, que me foi confiado.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 12, 'Dou graças àquele que me fortaleceu, a Cristo Jesus nosso Senhor, porque me julgou fiel, pondo-me no seu ministério,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 13, 'ainda que outrora eu era blasfemador, perseguidor, e injuriador; mas alcancei misericórdia, porque o fiz por ignorância, na incredulidade;', 1, CURRENT_TIMESTAMP, false),
(54, 1, 14, 'e a graça de nosso Senhor superabundou com a fé e o amor que há em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 15, 'Fiel é esta palavra e digna de toda a aceitação; que Cristo Jesus veio ao mundo para salvar os pecadores, dos quais sou eu o principal;', 1, CURRENT_TIMESTAMP, false),
(54, 1, 16, 'mas por isso alcancei misericórdia, para que em mim, o principal, Cristo Jesus mostrasse toda a sua longanimidade, a fim de que eu servisse de exemplo aos que haviam de crer nele para a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 17, 'Ora, ao Rei dos séculos, imortal, invisível, ao único Deus, seja honra e glória para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(54, 1, 18, 'Esta admoestação te dirijo, filho Timóteo, que segundo as profecias que houve acerca de ti, por elas pelejes a boa peleja,', 1, CURRENT_TIMESTAMP, false),
(54, 1, 19, 'conservando a fé, e uma boa consciência, a qual alguns havendo rejeitado, naufragando no tocante à fé;', 1, CURRENT_TIMESTAMP, false),
(54, 1, 20, 'e entre esses Himeneu e Alexandre, os quais entreguei a Satanás, para que aprendam a não blasfemar.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 1, 'Exorto, pois, antes de tudo que se façam súplicas, orações, intercessões, e ações de graças por todos os homens,', 1, CURRENT_TIMESTAMP, false),
(54, 2, 2, 'pelos reis, e por todos os que exercem autoridade, para que tenhamos uma vida tranqüila e sossegada, em toda a piedade e honestidade.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 3, 'Pois isto é bom e agradável diante de Deus nosso Salvador,', 1, CURRENT_TIMESTAMP, false),
(54, 2, 4, 'o qual deseja que todos os homens sejam salvos e cheguem ao pleno conhecimento da verdade.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 5, 'Porque há um só Deus, e um só Mediador entre Deus e os homens, Cristo Jesus, homem,', 1, CURRENT_TIMESTAMP, false),
(54, 2, 6, 'o qual se deu a si mesmo em resgate por todos, para servir de testemunho a seu tempo;', 1, CURRENT_TIMESTAMP, false),
(54, 2, 7, 'para o que {digo a verdade, não minto} eu fui constituído pregador e apóstolo, mestre dos gentios na fé e na verdade.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 8, 'Quero, pois, que os homens orem em todo lugar, levantando mãos santas, sem ira nem contenda.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 9, 'Quero, do mesmo modo, que as mulheres se ataviem com traje decoroso, com modéstia e sobriedade, não com tranças, ou com ouro, ou pérolas, ou vestidos custosos,', 1, CURRENT_TIMESTAMP, false),
(54, 2, 10, 'mas {como convém a mulheres que fazem profissão de servir a Deus} com boas obras.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 11, 'A mulher aprenda em silêncio com toda a submissão.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 12, 'Pois não permito que a mulher ensine, nem tenha domínio sobre o homem, mas que esteja em silêncio.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 13, 'Porque primeiro foi formado Adão, depois Eva.', 1, CURRENT_TIMESTAMP, false),
(54, 2, 14, 'E Adão não foi enganado, mas a mulher, sendo enganada, caiu em transgressão;', 1, CURRENT_TIMESTAMP, false),
(54, 2, 15, 'salvar-se-á, todavia, dando à luz filhos, se permanecer com sobriedade na fé, no amor e na santificação.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 1, 'Fiel é esta palavra: Se alguém aspira ao episcopado, excelente obra deseja.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 2, 'É necessário, pois, que o bispo seja irrepreensível, marido de uma só mulher, temperante, sóbrio, ordeiro, hospitaleiro, apto para ensinar;', 1, CURRENT_TIMESTAMP, false),
(54, 3, 3, 'não dado ao vinho, não espancador, mas moderado, inimigo de contendas, não ganancioso;', 1, CURRENT_TIMESTAMP, false),
(54, 3, 4, 'que governe bem a sua própria casa, tendo seus filhos em sujeição, com todo o respeito', 1, CURRENT_TIMESTAMP, false),
(54, 3, 5, '{pois, se alguém não sabe governar a sua própria casa, como cuidará da igreja de Deus?};', 1, CURRENT_TIMESTAMP, false),
(54, 3, 6, 'não neófito, para que não se ensoberbeça e venha a cair na condenação do Diabo.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 7, 'Também é necessário que tenha bom testemunho dos que estão de fora, para que não caia em opróbrio, e no laço do Diabo.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 8, 'Da mesma forma os diáconos sejam sérios, não de língua dobre, não dados a muito vinho, não cobiçosos de torpe ganância,', 1, CURRENT_TIMESTAMP, false),
(54, 3, 9, 'guardando o mistério da fé numa consciência pura.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 10, 'E também estes sejam primeiro provados, depois exercitem o diaconato, se forem irrepreensíveis.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 11, 'Da mesma sorte as mulheres sejam sérias, não maldizentes, temperantes, e fiéis em tudo.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 12, 'Os diáconos sejam maridos de uma só mulher, e governem bem a seus filhos e suas próprias casas.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 13, 'Porque os que servirem bem como diáconos, adquirirão para si um lugar honroso e muita confiança na fé que há em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 14, 'Escrevo-te estas coisas, embora esperando ir ver-te em breve,', 1, CURRENT_TIMESTAMP, false),
(54, 3, 15, 'para que, no caso de eu tardar, saibas como se deve proceder na casa de Deus, a qual é a igreja do Deus vivo, coluna e esteio da verdade.', 1, CURRENT_TIMESTAMP, false),
(54, 3, 16, 'E, sem dúvida alguma, grande é o mistério da piedade: Aquele que se manifestou em carne, foi justificado em espírito, visto dos anjos, pregado entre os gentios, crido no mundo, e recebido acima na glória.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 1, 'Mas o Espírito expressamente diz que em tempos posteriores alguns apostatarão da fé, dando ouvidos a espíritos enganadores, e a doutrinas de demônios,', 1, CURRENT_TIMESTAMP, false),
(54, 4, 2, 'pela hipocrisia de homens que falam mentiras e têm a sua própria consciência cauterizada,', 1, CURRENT_TIMESTAMP, false),
(54, 4, 3, 'proibindo o casamento, e ordenando a abstinência de alimentos que Deus criou para serem recebidos com ações de graças pelos que são fiéis e que conhecem bem a verdade;', 1, CURRENT_TIMESTAMP, false),
(54, 4, 4, 'pois todas as coisas criadas por Deus são boas, e nada deve ser rejeitado se é recebido com ações de graças;', 1, CURRENT_TIMESTAMP, false),
(54, 4, 5, 'porque pela palavra de Deus e pela oração são santificadas.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 6, 'Propondo estas coisas aos irmãos, serás bom ministro de Cristo Jesus, nutrido pelas palavras da fé e da boa doutrina que tens seguido;', 1, CURRENT_TIMESTAMP, false),
(54, 4, 7, 'mas rejeita as fábulas profanas e de velhas. Exercita-te a ti mesmo na piedade.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 8, 'Pois o exercício corporal para pouco aproveita, mas a piedade para tudo é proveitosa, visto que tem a promessa da vida presente e da que há de vir.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 9, 'Fiel é esta palavra e digna de toda aceitação.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 10, 'Pois para isto é que trabalhamos e lutamos, porque temos posto a nossa esperança no Deus vivo, que é o Salvador de todos os homens, especialmente dos que crêem.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 11, 'Manda estas coisas e ensina-as.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 12, 'Ninguém despreze a tua mocidade, mas sê um exemplo para os fiéis na palavra, no procedimento, no amor, na fé, na pureza.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 13, 'até que eu vá, aplica-te à leitura, à exortação, e ao ensino.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 14, 'Não negligencies o dom que há em ti, o qual te foi dado por profecia, com a imposição das mãos do presbítero.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 15, 'Ocupa-te destas coisas, dedica-te inteiramente a elas, para que o teu progresso seja manifesto a todos.', 1, CURRENT_TIMESTAMP, false),
(54, 4, 16, 'Tem cuidado de ti mesmo e do teu ensino; persevera nestas coisas; porque, fazendo isto, te salvarás, tanto a ti mesmo como aos que te ouvem.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 1, 'Não repreendas asperamente a um velho, mas admoesta-o como a um pai; aos moços, como a irmãos;', 1, CURRENT_TIMESTAMP, false),
(54, 5, 2, 'às mulheres idosas, como a mães; às moças, como a irmãs, com toda a pureza.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 3, 'Honra as viúvas que são verdadeiramente viúvas.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 4, 'Mas, se alguma viúva tiver filhos, ou netos, aprendam eles primeiro a exercer piedade para com a sua própria família, e a recompensar seus progenitores; porque isto é agradável a Deus.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 5, 'Ora, a que é verdadeiramente viúva e desamparada espera em Deus, e persevera de noite e de dia em súplicas e orações;', 1, CURRENT_TIMESTAMP, false),
(54, 5, 6, 'mas a que vive em prazeres, embora viva, está morta.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 7, 'Manda, pois, estas coisas, para que elas sejam irrepreensíveis.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 8, 'Mas, se alguém não cuida dos seus, e especialmente dos da sua família, tem negado a fé, e é pior que um incrédulo.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 9, 'Não seja inscrita como viúva nenhuma que tenha menos de sessenta anos, e só a que tenha sido mulher de um só marido,', 1, CURRENT_TIMESTAMP, false),
(54, 5, 10, 'aprovada com testemunho de boas obras, se criou filhos, se exercitou hospitalidade, se lavou os pés aos santos, se socorreu os atribulados, se praticou toda sorte de boas obras.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 11, 'Mas rejeita as viúvas mais novas, porque, quando se tornam levianas contra Cristo, querem casar-se;', 1, CURRENT_TIMESTAMP, false),
(54, 5, 12, 'tendo já a sua condenação por haverem violado a primeira fé;', 1, CURRENT_TIMESTAMP, false),
(54, 5, 13, 'e, além disto, aprendem também a ser ociosas, andando de casa em casa; e não somente ociosas, mas também faladeiras e intrigantes, falando o que não convém.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 14, 'Quero pois que as mais novas se casem, tenham filhos, dirijam a sua casa, e não dêem ocasião ao adversário de maldizer;', 1, CURRENT_TIMESTAMP, false),
(54, 5, 15, 'porque já algumas se desviaram, indo após Satanás.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 16, 'Se alguma mulher crente tem viúvas, socorra-as, e não se sobrecarregue a igreja, para que esta possa socorrer as que são verdadeiramente viúvas.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 17, 'Os anciãos que governam bem sejam tidos por dignos de duplicada honra, especialmente os que labutam na pregação e no ensino.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 18, 'Porque diz a Escritura: Não atarás a boca ao boi quando debulha. E: Digno é o trabalhador do seu salário.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 19, 'Não aceites acusação contra um ancião, senão com duas ou três testemunhas.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 20, 'Aos que vivem no pecado, repreende-os na presença de todos, para que também os outros tenham temor.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 21, 'Conjuro-te diante de Deus, e de Cristo Jesus, e dos anjos eleitos, que sem prevenção guardes estas coisas, nada fazendo com parcialidade.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 22, 'A ninguém imponhas precipitadamente as mãos, nem participes dos pecados alheios; conserva-te a ti mesmo puro.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 23, 'Não bebas mais água só, mas usa um pouco de vinho, por causa do teu estômago e das tuas freqüentes enfermidades.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 24, 'Os pecados de alguns homens são manifestos antes de entrarem em juízo, enquanto os de outros descobrem-se depois.', 1, CURRENT_TIMESTAMP, false),
(54, 5, 25, 'Da mesma forma também as boas obras são manifestas antecipadamente; e as que não o são não podem ficar ocultas.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 1, 'Todos os servos que estão debaixo do jugo considerem seus senhores dignos de toda honra, para que o nome de Deus e a doutrina não sejam blasfemados.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 2, 'E os que têm senhores crentes não os desprezem, porque são irmãos; antes os sirvam melhor, porque eles, que se utilizam do seu bom serviço, são crentes e amados. Ensina estas coisas.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 3, 'Se alguém ensina alguma doutrina diversa, e não se conforma com as sãs palavras de nosso Senhor Jesus Cristo, e com a doutrina que é segundo a piedade,', 1, CURRENT_TIMESTAMP, false),
(54, 6, 4, 'é soberbo, e nada sabe, mas delira acerca de questões e contendas de palavras, das quais nascem invejas, porfias, injúrias, suspeitas maliciosas,', 1, CURRENT_TIMESTAMP, false),
(54, 6, 5, 'disputas de homens corruptos de entendimento, e privados da verdade, cuidando que a piedade é fonte de lucro;', 1, CURRENT_TIMESTAMP, false),
(54, 6, 6, 'e, de fato, é grande fonte de lucro a piedade com o contentamento.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 7, 'Porque nada trouxe para este mundo, e nada podemos daqui levar;', 1, CURRENT_TIMESTAMP, false),
(54, 6, 8, 'tendo, porém, alimento e vestuário, estaremos com isso contentes.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 9, 'Mas os que querem tornar-se ricos caem em tentação e em laço, e em muitas concupiscências loucas e nocivas, as quais submergem os homens na ruína e na perdição.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 10, 'Porque o amor ao dinheiro é raiz de todos os males; e nessa cobiça alguns se desviaram da fé, e se traspassaram a si mesmos com muitas dores.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 11, 'Mas tu, ó homem de Deus, foge destas coisas, e segue a justiça, a piedade, a fé, o amor, a constância, a mansidão.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 12, 'Peleja a boa peleja da fé, apodera-te da vida eterna, para a qual foste chamado, tendo já feito boa confissão diante de muitas testemunhas.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 13, 'Diante de Deus, que todas as coisas vivifica, e de Cristo Jesus, que perante Pôncio Pilatos deu o testemunho da boa confissão, exorto-te', 1, CURRENT_TIMESTAMP, false),
(54, 6, 14, 'a que guardes este mandamento sem mácula e irrepreensível até a vinda de nosso Senhor Jesus Cristo;', 1, CURRENT_TIMESTAMP, false),
(54, 6, 15, 'a qual, no tempo próprio, manifestará o bem-aventurado e único soberano, Rei dos reis e Senhor dos senhores;', 1, CURRENT_TIMESTAMP, false),
(54, 6, 16, 'aquele que possui, ele só, a imortalidade, e habita em luz inacessível; a quem nenhum dos homens tem visto nem pode ver; ao qual seja honra e poder sempiterno. Amém.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 17, 'manda aos ricos deste mundo que não sejam altivos, nem ponham a sua esperança na incerteza das riquezas, mas em Deus, que nos concede abundantemente todas as coisas para delas gozarmos;', 1, CURRENT_TIMESTAMP, false),
(54, 6, 18, 'que pratiquem o bem, que se enriqueçam de boas obras, que sejam liberais e generosos,', 1, CURRENT_TIMESTAMP, false),
(54, 6, 19, 'entesourando para si mesmos um bom fundamento para o futuro, para que possam alcançar a verdadeira vida.', 1, CURRENT_TIMESTAMP, false),
(54, 6, 20, 'Ó Timóteo, guarda o depósito que te foi confiado, evitando as conversas vãs e profanas e as oposições da falsamente chamada ciência;', 1, CURRENT_TIMESTAMP, false),
(54, 6, 21, 'a qual professando-a alguns, se desviaram da fé. A graça seja convosco.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, e o irmão Timóteo, à igreja de Deus que está em Corinto, com todos os santos que estão em toda a Acaia:', 1, CURRENT_TIMESTAMP, false),
(47, 1, 2, 'Graça a vós, e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai das misericórdias e Deus de toda a consolação,', 1, CURRENT_TIMESTAMP, false),
(47, 1, 4, 'que nos consola em toda a nossa tribulação, para que também possamos consolar os que estiverem em alguma tribulação, pela consolação com que nós mesmos somos consolados por Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 5, 'Porque, como as aflições de Cristo transbordam para conosco, assim também por meio de Cristo transborda a nossa consolação.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 6, 'Mas, se somos atribulados, é para vossa consolação e salvação; ou, se somos consolados, para vossa consolação é a qual se opera suportando com paciência as mesmas aflições que nós também padecemos;', 1, CURRENT_TIMESTAMP, false),
(47, 1, 7, 'e a nossa esperança acerca de vós é firme, sabendo que, como sois participantes das aflições, assim o sereis também da consolação.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 8, 'Porque não queremos, irmãos, que ignoreis a tribulação que nos sobreveio na Ásia, pois que fomos sobremaneira oprimidos acima das nossas forças, de modo tal que até da vida desesperamos;', 1, CURRENT_TIMESTAMP, false),
(47, 1, 9, 'portanto já em nós mesmos tínhamos a sentença de morte, para que não confiássemos em nós, mas em Deus, que ressuscita os mortos;', 1, CURRENT_TIMESTAMP, false),
(47, 1, 10, 'o qual nos livrou de tão horrível morte, e livrará; em quem esperamos que também ainda nos livrará,', 1, CURRENT_TIMESTAMP, false),
(47, 1, 11, 'ajudando-nos também vós com orações por nós, para que, pela mercê que por muitas pessoas nos foi feita, por muitas também sejam dadas graças a nosso respeito.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 12, 'Porque a nossa glória é esta: o testemunho da nossa consciência, de que em santidade e sinceridade de Deus, não em sabedoria carnal, mas na graça de Deus, temos vivido no mundo, e mormente em relação a vós.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 13, 'Pois outra coisa não vos escrevemos, senão as que ledes, ou mesmo reconheceis; e espero que também até o fim as reconhecereis;', 1, CURRENT_TIMESTAMP, false),
(47, 1, 14, 'como também já em parte nos reconhecestes, que somos a vossa glória, assim vós sereis a nossa no dia do Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 15, 'E nesta confiança quis primeiro ir ter convosco, para que recebêsseis um segundo benefício;', 1, CURRENT_TIMESTAMP, false),
(47, 1, 16, 'e por vós passar à Macedônia, e da Macedônia voltar a vós, e ser por vosso intermédio encaminhado à Judéia.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 17, 'Ora, deliberando isto, usei porventura de leviandade? ou o que delibero, faço-o segundo a carne, para que haja comigo o sim, sim e o não?', 1, CURRENT_TIMESTAMP, false),
(47, 1, 18, 'Antes, como Deus é fiel, a nossa palavra a vós não é sim e não,', 1, CURRENT_TIMESTAMP, false),
(47, 1, 19, 'porque o Filho de Deus, Cristo Jesus, que entre vós foi pregado por nós, isto é, por mim, Silvano e Timóteo, não foi sim e não; mas nele houve sim.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 20, 'Pois, tantas quantas forem as promessas de Deus, nele está o sim; portanto é por ele o amém, para glória de Deus por nosso intermédio.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 21, 'Mas aquele que nos confirma convosco em Cristo, e nos ungiu, é Deus,', 1, CURRENT_TIMESTAMP, false),
(47, 1, 22, 'o qual também nos selou e nos deu como penhor o Espírito em nossos corações.', 1, CURRENT_TIMESTAMP, false),
(47, 1, 23, 'Ora, tomo a Deus por testemunha sobre a minha alma de que é para vos poupar que não fui mais a Corinto;', 1, CURRENT_TIMESTAMP, false),
(47, 1, 24, 'não que tenhamos domínio sobre a vossa fé, mas somos cooperadores de vosso gozo; pois pela fé estais firmados.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 1, 'Mas deliberei isto comigo mesmo: não ir mais ter convosco em tristeza.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 2, 'Porque, se eu vos entristeço, quem é, pois, o que me alegra, senão aquele que por mim é entristecido?', 1, CURRENT_TIMESTAMP, false),
(47, 2, 3, 'E escrevi isto mesmo, para que, chegando, eu não tenha tristeza da parte dos que deveriam alegrar-me; confiando em vós todos, que a minha alegria é a de todos vós.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 4, 'Porque em muita tribulação e angústia de coração vos escrevi, com muitas lágrimas, não para que vos entristecêsseis, mas para que conhecêsseis o amor que abundantemente vos tenho.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 5, 'Ora, se alguém tem causado tristeza, não me tem contristado a mim, mas em parte {para não ser por demais severo} a todos vós.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 6, 'Basta a esse tal esta repreensão feita pela maioria.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 7, 'De maneira que, pelo contrário, deveis antes perdoar-lhe e consolá-lo, para que ele não seja devorado por excessiva tristeza.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 8, 'Pelo que vos rogo que confirmeis para com ele o vosso amor.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 9, 'É pois para isso também que escrevi, para, por esta prova, saber se sois obedientes em tudo.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 10, 'E a quem perdoardes alguma coisa, também eu; pois, o que eu também perdoei, se é que alguma coisa tenho perdoado, por causa de vós o fiz na presença de Cristo, para que Satanás não leve vantagem sobre nós;', 1, CURRENT_TIMESTAMP, false),
(47, 2, 11, 'porque não ignoramos as suas maquinações.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 12, 'Ora, quando cheguei a Trôade para pregar o evangelho de Cristo, e quando se me abriu uma porta no Senhor,', 1, CURRENT_TIMESTAMP, false),
(47, 2, 13, 'não tive descanso no meu espírito, porque não achei ali irmão Tito; mas, despedindo-me deles, parti para a Macedônia.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 14, 'Graças, porém, a Deus que em Cristo sempre nos conduz em triunfo, e por meio de nós difunde em todo lugar o cheiro do seu conhecimento;', 1, CURRENT_TIMESTAMP, false),
(47, 2, 15, 'porque para Deus somos um aroma de Cristo, nos que se salvam e nos que se perdem.', 1, CURRENT_TIMESTAMP, false),
(47, 2, 16, 'Para uns, na verdade, cheiro de morte para morte; mas para outros cheiro de vida para vida. E para estas coisas quem é idôneo?', 1, CURRENT_TIMESTAMP, false),
(47, 2, 17, 'Porque nós não somos falsificadores da palavra de Deus, como tantos outros; mas é com sinceridade, é da parte de Deus e na presença do próprio Deus que, em Cristo, falamos.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 1, 'Começamos outra vez a recomendar-nos a nós mesmos? Ou, porventura, necessitamos, como alguns, de cartas de recomendação para vós, ou de vós?', 1, CURRENT_TIMESTAMP, false),
(47, 3, 2, 'Vós sois a nossa carta, escrita em nossos corações, conhecida e lida por todos os homens,', 1, CURRENT_TIMESTAMP, false),
(47, 3, 3, 'sendo manifestos como carta de Cristo, ministrada por nós, e escrita, não com tinta, mas com o Espírito do Deus vivo, não em tábuas de pedra, mas em tábuas de carne do coração.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 4, 'E é por Cristo que temos tal confiança em Deus;', 1, CURRENT_TIMESTAMP, false),
(47, 3, 5, 'não que sejamos capazes, por nós, de pensar alguma coisa, como de nós mesmos; mas a nossa capacidade vem de Deus,', 1, CURRENT_TIMESTAMP, false),
(47, 3, 6, 'o qual também nos capacitou para sermos ministros dum novo pacto, não da letra, mas do espírito; porque a letra mata, mas o espírito vivifica.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 7, 'Ora, se o ministério da morte, gravado com letras em pedras, veio em glória, de maneira que os filhos de Israel não podiam fixar os olhos no rosto de Moisés, por causa da glória do seu rosto, a qual se estava desvanecendo,', 1, CURRENT_TIMESTAMP, false),
(47, 3, 8, 'como não será de maior glória o ministério do espírito?', 1, CURRENT_TIMESTAMP, false),
(47, 3, 9, 'Porque, se o ministério da condenação tinha glória, muito mais excede em glória o ministério da justiça.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 10, 'Pois na verdade, o que foi feito glorioso, não o é em comparação com a glória inexcedível.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 11, 'Porque, se aquilo que se desvanecia era glorioso, muito mais glorioso é o que permanece.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 12, 'Tendo, pois, tal esperança, usamos de muita ousadia no falar.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 13, 'E não somos como Moisés, que trazia um véu sobre o rosto, para que os filhos de Isra desvanecia;', 1, CURRENT_TIMESTAMP, false),
(47, 3, 14, 'mas o entendimento lhes ficou endurecido. Pois até o dia de hoje, à leitura do velho pacto, permanece o mesmo véu, não lhes sendo revelado que em Cristo é ele abolido;', 1, CURRENT_TIMESTAMP, false),
(47, 3, 15, 'sim, até o dia de hoje, sempre que Moisés é lido, um véu está posto sobre o coração deles.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 16, 'Contudo, convertendo-se um deles ao Senhor, é-lhe tirado o véu.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 17, 'Ora, o Senhor é o Espírito; e onde está o Espírito do Senhor aí há liberdade.', 1, CURRENT_TIMESTAMP, false),
(47, 3, 18, 'Mas todos nós, com rosto descoberto, refletindo como um espelho a glória do Senhor, somos transformados de glória em glória na mesma imagem, como pelo Espírito do Senhor.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 1, 'Pelo que, tendo este ministério, assim como já alcançamos misericórdia, não desfalecemos;', 1, CURRENT_TIMESTAMP, false),
(47, 4, 2, 'pelo contrário, rejeitamos as coisas ocultas, que são vergonhosas, não andando com astúcia, nem adulterando a palavra de Deus; mas, pela manifestação da verdade, nós nos recomendamos à consciência de todos os homens diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 3, 'Mas, se ainda o nosso evangelho está encoberto, é naqueles que se perdem que está encoberto,', 1, CURRENT_TIMESTAMP, false),
(47, 4, 4, 'nos quais o deus deste século cegou os entendimentos dos incrédulos, para que lhes não resplandeça a luz do evangelho da glória de Cristo, o qual é a imagem de Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 5, 'Pois não nos pregamos a nós mesmos, mas a Cristo Jesus como Senhor; e a nós mesmos como vossos servos por amor de Jesus.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 6, 'Porque Deus, que disse: Das trevas brilhará a luz, é quem brilhou em nossos corações, para iluminação do conhecimento da glória de Deus na face de Cristo.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 7, 'Temos, porém, este tesouro em vasos de barro, para que a excelência do poder seja de Deus, e não da nossa parte.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 8, 'Em tudo somos atribulados, mas não angustiados; perplexos, mas não desesperados;', 1, CURRENT_TIMESTAMP, false),
(47, 4, 9, 'perseguidos, mas não desamparados; abatidos, mas não destruídos;', 1, CURRENT_TIMESTAMP, false),
(47, 4, 10, 'trazendo sempre no corpo o morrer de Jesus, para que também a vida de Jesus se manifeste em nossos corpos;', 1, CURRENT_TIMESTAMP, false),
(47, 4, 11, 'pois nós, que vivemos, estamos sempre entregues à morte por amor de Jesus, para que também a vida de Jesus se manifeste em nossa carne mortal.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 12, 'De modo que em nós opera a morte, mas em vós a vida.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 13, 'Ora, temos o mesmo espírito de fé, conforme está escrito: Cri, por isso falei; também nós cremos, por isso também falamos,', 1, CURRENT_TIMESTAMP, false),
(47, 4, 14, 'sabendo que aquele que ressuscitou o Senhor Jesus, nos ressuscitará a nós com Jesus, e nos apresentará convosco.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 15, 'Pois tudo é por amor de vós, para que a graça, multiplicada por meio de muitos, faça abundar a ação de graças para glória de Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 16, 'Por isso não desfalecemos; mas ainda que o nosso homem exterior se esteja consumindo, o interior, contudo, se renova de dia em dia.', 1, CURRENT_TIMESTAMP, false),
(47, 4, 17, 'Porque a nossa leve e momentânea tribulação produz para nós cada vez mais abundantemente um eterno peso de glória;', 1, CURRENT_TIMESTAMP, false),
(47, 4, 18, 'não atentando nós nas coisas que se vêem, mas sim nas que se não vêem; porque as que se vêem são temporais, enquanto as que se não vêem são eternas.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 1, 'Porque sabemos que, se a nossa casa terrestre deste tabernáculo se desfizer, temos de Deus um edifício, uma casa não feita por mãos, eterna, nos céus.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 2, 'Pois neste tabernáculo nós gememos, desejando muito ser revestidos da nossa habitação que é do céu,', 1, CURRENT_TIMESTAMP, false),
(47, 5, 3, 'se é que, estando vestidos, não formos achados nus.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 4, 'Porque, na verdade, nós, os que estamos neste tabernáculo, gememos oprimidos, porque não queremos ser despidos, mas sim revestidos, para que o mortal seja absorvido pela vida.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 5, 'Ora, quem para isto mesmo nos preparou foi Deus, o qual nos deu como penhor o Espírito.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 6, 'Temos, portanto, sempre bom ânimo, sabendo que, enquanto estamos presentes no corpo, estamos ausentes do Senhor', 1, CURRENT_TIMESTAMP, false),
(47, 5, 7, '{porque andamos por fé, e não por vista};', 1, CURRENT_TIMESTAMP, false),
(47, 5, 8, 'temos bom ânimo, mas desejamos antes estar ausentes deste corpo, para estarmos presentes com o Senhor.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 9, 'Pelo que também nos esforçamos para ser-lhe agradáveis, quer presentes, quer ausentes.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 10, 'Porque é necessário que todos nós sejamos manifestos diante do tribunal de Cristo, para que cada um receba o que fez por meio do corpo, segundo o que praticou, o bem ou o mal.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 11, 'Portanto, conhecendo o temor do Senhor, procuramos persuadir os homens; mas, a Deus já somos manifestos, e espero que também nas vossas consciências sejamos manifestos.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 12, 'Não nos recomendamos outra vez a vós, mas damo-vos ocasião de vos gloriardes por nossa causa, a fim de que tenhais resposta para os que se gloriam na aparência, e não no coração.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 13, 'Porque, se enlouquecemos, é para Deus; se conservamos o juízo, é para vós.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 14, 'Pois o amor de Cristo nos constrange, porque julgamos assim: se um morreu por todos, logo todos morreram;', 1, CURRENT_TIMESTAMP, false),
(47, 5, 15, 'e ele morreu por todos, para que os que vivem não vivam mais para si, mas para aquele que por eles morreu e ressuscitou.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 16, 'Por isso daqui por diante a ninguém conhecemos segundo a carne; e, ainda que tenhamos conhecido Cristo segundo a carne, contudo agora já não o conhecemos desse modo.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 17, 'Pelo que, se alguém está em Cristo, nova criatura é; as coisas velhas já passaram; eis que tudo se fez novo.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 18, 'Mas todas as coisas provêm de Deus, que nos reconciliou consigo mesmo por Cristo, e nos confiou o ministério da reconciliação;', 1, CURRENT_TIMESTAMP, false),
(47, 5, 19, 'pois que Deus estava em Cristo reconciliando consigo o mundo, não imputando aos homens as suas transgressões; e nos encarregou da palavra da reconciliação.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 20, 'De sorte que somos embaixadores por Cristo, como se Deus por nós vos exortasse. Rogamo-vos, pois, por Cristo que vos reconcilieis com Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 5, 21, 'Àquele que não conheceu pecado, Deus o fez pecado por nós; para que nele fôssemos feitos justiça de Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 6, 1, 'E nós, cooperando com ele, também vos exortamos a que não recebais a graça de Deus em vão;', 1, CURRENT_TIMESTAMP, false),
(47, 6, 2, '{porque diz: No tempo aceitável te escutei e no dia da salvação te socorri; eis aqui agora o tempo aceitável, eis aqui agora o dia da salvação};', 1, CURRENT_TIMESTAMP, false),
(47, 6, 3, 'não dando nós nenhum motivo de escândalo em coisa alguma, para que o nosso ministério não seja censurado.', 1, CURRENT_TIMESTAMP, false),
(47, 6, 4, 'Antes em tudo recomendando-nos como ministros de Deus; em muita perseverança, em aflições, em necessidades, em angústias,', 1, CURRENT_TIMESTAMP, false),
(47, 6, 5, 'em açoites, em prisões, em tumultos, em trabalhos, em vigílias, em jejuns,', 1, CURRENT_TIMESTAMP, false),
(47, 6, 6, 'na pureza, na ciência, na longanimidade, na bondade, no Espírito Santo, no amor não fingido,', 1, CURRENT_TIMESTAMP, false),
(47, 6, 7, 'na palavra da verdade, no poder de Deus, pelas armas da justiça à direita e à esquerda,', 1, CURRENT_TIMESTAMP, false),
(47, 6, 8, 'por honra e por desonra, por má fama e por boa fama; como enganadores, porém verdadeiros;', 1, CURRENT_TIMESTAMP, false),
(47, 6, 9, 'como desconhecidos, porém bem conhecidos; como quem morre, e eis que vivemos; como castigados, porém não mortos;', 1, CURRENT_TIMESTAMP, false),
(47, 6, 10, 'como entristecidos, mas sempre nos alegrando; como pobres, mas enriquecendo a muitos; como nada tendo, mas possuindo tudo.', 1, CURRENT_TIMESTAMP, false),
(47, 6, 11, 'Ó coríntios, a nossa boca está aberta para vós, o nosso coração está dilatado!', 1, CURRENT_TIMESTAMP, false),
(47, 6, 12, 'Não estais estreitados em nós; mas estais estreitados nos vossos próprios afetos.', 1, CURRENT_TIMESTAMP, false),
(47, 6, 13, 'Ora, em recompensa disto {falo como a filhos}, dilatai-vos também vós.', 1, CURRENT_TIMESTAMP, false),
(47, 6, 14, 'Não vos prendais a um jugo desigual com os incrédulos; pois que sociedade tem a justiça com a injustiça? ou que comunhão tem a luz com as trevas?', 1, CURRENT_TIMESTAMP, false),
(47, 6, 15, 'Que harmonia há entre Cristo e Belial? ou que parte tem o crente com o incrédulo?', 1, CURRENT_TIMESTAMP, false),
(47, 6, 16, 'E que consenso tem o santuário de Deus com ídolos? Pois nós somos santuário de Deus vivo, como Deus disse: Neles habitarei, e entre eles andarei; e eu serei o seu Deus e eles serão o meu povo.', 1, CURRENT_TIMESTAMP, false),
(47, 6, 17, 'Pelo que, saí vós do meio deles e separai-vos, diz o Senhor; e não toqueis coisa imunda, e eu vos receberei;', 1, CURRENT_TIMESTAMP, false),
(47, 6, 18, 'e eu serei para vós Pai, e vós sereis para mim filhos e filhas, diz o Senhor Todo-Poderoso.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 1, 'Ora, amados, visto que temos tais promessas, purifiquemo-nos de toda a imundícia da carne e do espírito, aperfeiçoando a santidade no temor de Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 2, 'Recebei-nos em vossos corações; a ninguém fizemos injustiça, a ninguém corrompemos, a ninguém exploramos.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 3, 'Não o digo para vos condenar, pois já tenho declarado que estais em nossos corações para juntos morrermos e juntos vivermos.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 4, 'Grande é a minha franqueza para convosco, e muito me glorio a respeito de vós; estou cheio de consolação, transbordo de gozo em todas as nossas tribulações.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 5, 'Porque, mesmo quando chegamos à Macedônia, a nossa carne não teve repouso algum; antes em tudo fomos atribulados: por fora combates, temores por dentro.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 6, 'Mas Deus, que consola os abatidos, nos consolou com a vinda de Tito;', 1, CURRENT_TIMESTAMP, false),
(47, 7, 7, 'e não somente com a sua vinda, mas também pela consolação com que foi consolado a vosso respeito, enquanto nos referia as vossas saudações, o vosso pranto, o vosso zelo por mim, de modo que ainda mais me regozijei.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 8, 'Porquanto, ainda que vos contristei com a minha carta, não me arrependo; embora antes me tivesse arrependido {pois vejo que aquela carta vos contristou, ainda que por pouco tempo},', 1, CURRENT_TIMESTAMP, false),
(47, 7, 9, 'agora folgo, não porque fostes contristados, mas porque o fostes para o arrependimento; pois segundo Deus fostes contristados, para que por nós não sofrêsseis dano em coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 10, 'Porque a tristeza segundo Deus opera arrependimento para a salvação, o qual não traz pesar; mas a tristeza do mundo opera a morte.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 11, 'Pois vêde quanto cuidado não produziu em vós isto mesmo, o serdes contristados segundo Deus! sim, que defesa própria, que indignação, que temor, que saudades, que zelo, que vingança! Em tudo provastes estar inocentes nesse negócio.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 12, 'Portanto, ainda que vos escrevi, não foi por causa do que fez o mal, nem por causa do que o sofreu, mas para que fosse manifesto, diante de Deus, o vosso grande cuidado por nós.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 13, 'Por isso temos sido consolados. E em nossa consolação nos alegramos ainda muito mais pela alegria de Tito, porque o seu espírito tem sido recreado por vós todos.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 14, 'Porque, se em alguma coisa me gloriei de vós para com ele, não fiquei envergonhado; mas como vos dissemos tudo com verdade, assim também o louvor que de vós fizemos a Tito se achou verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 15, 'E o seu entranhável afeto para convosco é mais abundante, lembrando-se da obediência de vós todos, e de como o recebestes com temor e tremor.', 1, CURRENT_TIMESTAMP, false),
(47, 7, 16, 'Regozijo-me porque em tudo tenho confiança em vós.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 1, 'Também, irmãos, vos fazemos conhecer a graça de Deus que foi dada às igrejas da Macedônia;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 2, 'como, em muita prova de tribulação, a abundância do seu gozo e sua profunda pobreza abundaram em riquezas da sua generosidade.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 3, 'Porque, dou-lhes testemunho de que, segundo as suas posses, e ainda acima das suas posses, deram voluntariamente,', 1, CURRENT_TIMESTAMP, false),
(47, 8, 4, 'pedindo-nos, com muito encarecimento, o privilégio de participarem deste serviço a favor dos santos;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 5, 'e não somente fizeram como nós esperávamos, mas primeiramente a si mesmos se deram ao Senhor, e a nós pela vontade de Deus;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 6, 'de maneira que exortamos a Tito que, assim como antes tinha começado, assim também completasse entre vós ainda esta graça.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 7, 'Ora, assim como abundais em tudo: em fé, em palavra, em ciência, em todo o zelo, no vosso amor para conosco, vede que também nesta graça abundeis.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 8, 'Não digo isto como quem manda, mas para provar, mediante o zelo de outros, a sinceridade de vosso amor;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 9, 'pois conheceis a graça de nosso Senhor Jesus Cristo, que, sendo rico, por amor de vós se fez pobre, para que pela sua pobreza fôsseis enriquecidos.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 10, 'E nisto dou o meu parecer; pois isto vos convém a vós que primeiro começastes, desde o ano passado, não só a participar mas também a querer;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 11, 'agora, pois, levai a termo a obra, para que, assim como houve a prontidão no querer, haja também o cumprir segundo o que tendes.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 12, 'Porque, se há prontidão de vontade, é aceitável segundo o que alguém tem, e não segundo o que não tem.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 13, 'Pois digo isto não para que haja alívio para outros e aperto para vós,', 1, CURRENT_TIMESTAMP, false),
(47, 8, 14, 'mas para que haja igualdade, suprindo, neste tempo presente, na vossa abundância a falta dos outros, para que também a abundância deles venha a suprir a vossa falta, e assim haja igualdade;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 15, 'como está escrito: Ao que muito colheu, não sobrou; e ao que pouco colheu, não faltou.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 16, 'Mas, graças a Deus, que pôs no coração de Tito a mesma solicitude por vós;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 17, 'pois, com efeito, aceitou a nossa exortação; mas sendo sobremodo zeloso, foi por sua própria vontade que partiu para vós.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 18, 'E juntamente com ele enviamos o irmão cujo louvor no evangelho se tem espalhado por todas as igrejas;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 19, 'e não só isto, mas também foi escolhido pelas igrejas para ser nosso companheiro de viagem no tocante a esta graça que por nós é ministrada para glória do Senhor e para provar a nossa boa vontade;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 20, 'assim evitando que alguém nos censure com referência a esta abundância, que por nós é ministrada;', 1, CURRENT_TIMESTAMP, false),
(47, 8, 21, 'pois zelamos o que é honesto, não só diante do Senhor, mas também diante dos homens.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 22, 'Com eles enviamos também outro nosso irmão, o qual muitas vezes e em muitas coisas já experimentamos ser zeloso, mas agora muito mais zeloso ainda pela muita confiança que vós tem.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 23, 'Quanto a Tito, ele é meu companheiro e cooperador para convosco; quanto a nossos irmãos, são mensageiros das igrejas, glória de Cristo.', 1, CURRENT_TIMESTAMP, false),
(47, 8, 24, 'Portanto mostrai para com eles, perante a face das igrejas, a prova do vosso amor, e da nossa glória a vosso respeito.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 1, 'Pois quanto à ministração que se faz a favor dos santos, não necessito escrever-vos;', 1, CURRENT_TIMESTAMP, false),
(47, 9, 2, 'porque bem sei a vossa prontidão, pela qual me glorio de vós perante os macedônios, dizendo que a Acaia está pronta desde o ano passado; e o vosso zelo tem estimulado muitos.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 3, 'Mas enviei estes irmãos, a fim de que neste particular não se torne vão o nosso louvor a vosso respeito; para que, como eu dizia, estejais preparados,', 1, CURRENT_TIMESTAMP, false),
(47, 9, 4, 'a fim de, se acaso alguns macedônios forem comigo, e vos acharem desaparecidos, não sermos nós envergonhados {para não dizermos vós} nesta confiança.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 5, 'Portanto, julguei necessário exortar estes irmãos que fossem adiante ter convosco, e preparassem de antemão a vossa beneficência, já há tempos prometida, para que a mesma esteja pronta como beneficência e não como por extorsão.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 6, 'Mas digo isto: Aquele que semeia pouco, pouco também ceifará; e aquele que semeia em abundância, em abundância também ceifará,', 1, CURRENT_TIMESTAMP, false),
(47, 9, 7, 'Cada um contribua segundo propôs no seu coração; não com tristeza, nem por constrangimento; porque Deus ama ao que dá com alegria.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 8, 'E Deus é poderoso para fazer abundar em vós toda a graça, a fim de que, tendo sempre, em tudo, toda a suficiência, abundeis em toda boa obra;', 1, CURRENT_TIMESTAMP, false),
(47, 9, 9, 'conforme está escrito: Espalhou, deu aos pobres; a sua justiça permanece para sempre.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 10, 'Ora, aquele que dá a semente ao que semeia, e pão para comer, também dará e multiplicará a vossa sementeira, e aumentará os frutos da vossa justiça.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 11, 'enquanto em tudo enriqueceis para toda a liberalidade, a qual por nós reverte em ações de graças a Deus.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 12, 'Porque a ministração deste serviço não só supre as necessidades dos santos, mas também transborda em muitas ações de graças a Deus;', 1, CURRENT_TIMESTAMP, false),
(47, 9, 13, 'visto como, na prova desta ministração, eles glorificam a Deus pela submissão que confessais quanto ao evangelho de Cristo, e pela liberalidade da vossa contribuição para eles, e para todos;', 1, CURRENT_TIMESTAMP, false),
(47, 9, 14, 'enquanto eles, pela oração por vós, demonstram o ardente afeto que vos têm, por causa da superabundante graça de Deus que há em vós.', 1, CURRENT_TIMESTAMP, false),
(47, 9, 15, 'Graças a Deus pelo seu dom inefável.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 1, 'Ora eu mesmo, Paulo, vos rogo pela mansidão e benignidade de Cristo, eu que, na verdade, quando presente entre vós, sou humilde, mas quando ausente, ousado para convosco;', 1, CURRENT_TIMESTAMP, false),
(47, 10, 2, 'sim, eu vos rogo que, quando estiver presente, não me veja obrigado a usar, com confiança, da ousadia que espero ter para com alguns que nos julgam como se andássemos segundo a carne.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 3, 'Porque, embora andando na carne, não militamos segundo a carne,', 1, CURRENT_TIMESTAMP, false),
(47, 10, 4, 'pois as armas da nossa milícia não são carnais, mas poderosas em Deus, para demolição de fortalezas;', 1, CURRENT_TIMESTAMP, false),
(47, 10, 5, 'derribando raciocínios e todo baluarte que se ergue contra o conhecimento de Deus, e levando cativo todo pensamento à obediência a Cristo;', 1, CURRENT_TIMESTAMP, false),
(47, 10, 6, 'e estando prontos para vingar toda desobediência, quando for cumprida a vossa obediência.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 7, 'Olhais para as coisas segundo a aparência. Se alguém confia de si mesmo que é de Cristo, pense outra vez isto consigo, que, assim como ele é de Cristo, também nós o somos.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 8, 'Pois, ainda que eu me glorie um tanto mais da nossa autoridade, a qual o Senhor nos deu para edificação, e não para vossa destruição, não me envergonharei;', 1, CURRENT_TIMESTAMP, false),
(47, 10, 9, 'para que eu não pareça como se quisera intimidar-vos por cartas.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 10, 'Porque eles dizem: As cartas dele são graves e fortes, mas a sua presença corporal é fraca, e a sua palavra desprezível.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 11, 'Considere o tal isto, que, quais somos no falar por cartas, estando ausentes, tais seremos também no fazer, estando presentes,', 1, CURRENT_TIMESTAMP, false),
(47, 10, 12, 'pois não ousamos contar-nos, ou comparar-nos com alguns, que se louvam a si mesmos; mas estes, medindo-se consigo mesmos e comparando-se consigo mesmos, estão sem entendimento.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 13, 'Nós, porém, não nos gloriaremos além da medida, mas conforme o padrão da medida que Deus nos designou para chegarmos mesmo até vós;', 1, CURRENT_TIMESTAMP, false),
(47, 10, 14, 'porque não nos estendemos além do que convém, como se não chegássemos a vós, pois já chegamos também até vós no evangelho de Cristo,', 1, CURRENT_TIMESTAMP, false),
(47, 10, 15, 'não nos gloriando além da medida em trabalhos alheios; antes tendo esperança de que, à proporção que cresce a vossa fé, seremos nós cada vez mais engrandecidos entre vós, conforme a nossa medida,', 1, CURRENT_TIMESTAMP, false),
(47, 10, 16, 'para anunciar o evangelho nos lugares que estão além de vós, e não em campo de outrem, para não nos gloriarmos no que estava já preparado.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 17, 'Aquele, porém, que se gloria, glorie-se no Senhor.', 1, CURRENT_TIMESTAMP, false),
(47, 10, 18, 'Porque não é aprovado aquele que se recomenda a si mesmo, mas sim aquele a quem o Senhor recomenda.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 1, 'Oxalá me suportásseis um pouco na minha insensatez! Sim, suportai-me ainda.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 2, 'Porque estou zeloso de vós com zelo de Deus; pois vos desposei com um só Esposo, Cristo, para vos apresentar a ele como virgem pura.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 3, 'Mas temo que, assim como a serpente enganou a Eva com a sua astúcia, assim também sejam de alguma sorte corrompidos os vossos entendimentos e se apartem da simplicidade e da pureza que há em Cristo.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 4, 'Porque, se alguém vem e vos prega outro Jesus que nós não temos pregado, ou se recebeis outro espírito que não recebestes, ou outro evangelho que não abraçastes, de boa mente o suportais!', 1, CURRENT_TIMESTAMP, false),
(47, 11, 5, 'Ora, julgo que em nada tenho sido inferior aos mais excelentes apóstolos.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 6, 'Pois ainda que seja rude na palavra, não o sou contudo na ciência; antes, por todos os modos, isto vos temos demonstrado em tudo.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 7, 'Pequei porventura, humilhando-me a mim mesmo, para que vós fôsseis exaltados, porque de graça vos anunciei o evangelho de Deus?', 1, CURRENT_TIMESTAMP, false),
(47, 11, 8, 'Outras igrejas despojei, recebendo delas salário, para vos servir;', 1, CURRENT_TIMESTAMP, false),
(47, 11, 9, 'e quando estava presente convosco, e tinha necessidade, a ninguém fui pesado; porque os irmãos, quando vieram da Macedônia, supriram a minha necessidade; e em tudo me guardei, e ainda me guardarei, de vos ser pesado.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 10, 'Como a verdade de Cristo está em mim, não me será tirada glória nas regiões da Acaia.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 11, 'Por que? Será porque não vos amo? Deus o sabe.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 12, 'Ora, o que faço e ainda farei, é para cortar ocasião aos que buscam ocasião; a fim de que, naquilo em que se gloriam, sejam achados assim como nós.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 13, 'Pois os tais são falsos apóstolos, obreiros fraudulentos, disfarçando-se em apóstolos de Cristo.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 14, 'E não é de admirar, porquanto o próprio Satanás se disfarça em anjo de luz.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 15, 'Não é muito, pois, que também os seus ministros se disfarcem em ministros da justiça; o fim dos quais será conforme as suas obras.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 16, 'Outra vez digo: ninguém me julgue insensato; mas se assim pensais, recebei-me como insensato mesmo, para que eu também me glorie um pouco.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 17, 'O que digo, não o digo segundo o Senhor, mas como por insensatez, nesta confiança de gloriar-me.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 18, 'Desde que muitos se gloriam segundo a carne, eu também me gloriarei.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 19, 'Porque, sendo vós sensatos, de boa mente tolerais os insensatos.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 20, 'Pois se alguém vos escraviza, se alguém vos devora, se alguém vos defrauda, se alguém se ensoberbece, se alguém vos fere no rosto, vós o suportais.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 21, 'Falo com vergonha, como se nós fôssemos fracos; mas naquilo em que alguém se faz ousado, com insensatez falo, também eu sou ousado.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 22, 'São hebreus? também eu; são israelitas? também eu; são descendência de Abraão? também eu;', 1, CURRENT_TIMESTAMP, false),
(47, 11, 23, 'são ministros de Cristo? falo como fora de mim, eu ainda mais; em trabalhos muito mais; em prisões muito mais; em açoites sem medida; em perigo de morte muitas vezes;', 1, CURRENT_TIMESTAMP, false),
(47, 11, 24, 'dos judeus cinco vezes recebi quarenta açoites menos um.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 25, 'Três vezes fui açoitado com varas, uma vez fui apedrejado, três vezes sofri naufrágio, uma noite e um dia passei no abismo;', 1, CURRENT_TIMESTAMP, false),
(47, 11, 26, 'em viagens muitas vezes, em perigos de rios, em perigos de salteadores, em perigos dos da minha raça, em perigos dos gentios, em perigos na cidade, em perigos no deserto, em perigos no mar, em perigos entre falsos irmãos;', 1, CURRENT_TIMESTAMP, false),
(47, 11, 27, 'em trabalhos e fadiga, em vigílias muitas vezes, em fome e sede, em jejuns muitas vezes, em frio e nudez.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 28, 'Além dessas coisas exteriores, há o que diariamente pesa sobre mim, o cuidado de todas as igrejas.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 29, 'Quem enfraquece, que eu também não enfraqueça? Quem se escandaliza, que eu me não abrase?', 1, CURRENT_TIMESTAMP, false),
(47, 11, 30, 'Se é preciso gloriar-me, gloriar-me-ei no que diz respeito à minha fraqueza.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 31, 'O Deus e Pai do Senhor Jesus, que é eternamente bendito, sabe que não minto.', 1, CURRENT_TIMESTAMP, false),
(47, 11, 32, 'Em Damasco, o que governava sob o rei Aretas guardava a cidade dos damascenos, para me prender;', 1, CURRENT_TIMESTAMP, false),
(47, 11, 33, 'mas por uma janela desceram-me num cesto, muralha abaixo; e assim escapei das suas mãos.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 1, 'É necessário gloriar-me, embora não convenha; mas passarei a visões e revelações do Senhor.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 2, 'Conheço um homem em Cristo que há catorze anos {se no corpo não sei, se fora do corpo não sei; Deus o sabe} foi arrebatado até o terceiro céu.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 3, 'Sim, conheço o tal homem {se no corpo, se fora do corpo, não sei: Deus o sabe},', 1, CURRENT_TIMESTAMP, false),
(47, 12, 4, 'que foi arrebatado ao paraíso, e ouviu palavras inefáveis, as quais não é lícito ao homem referir.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 5, 'Desse tal me gloriarei, mas de mim mesmo não me gloriarei, senão nas minhas fraquezas.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 6, 'Pois, se quiser gloriar-me, não serei insensato, porque direi a verdade;', 1, CURRENT_TIMESTAMP, false),
(47, 12, 7, 'E, para que me não exaltasse demais pela excelência das revelações, foi-me dado um espinho na carne, a saber, um mensageiro de Satanás para me esbofetear, a fim de que eu não me exalte demais;', 1, CURRENT_TIMESTAMP, false),
(47, 12, 8, 'acerca do qual três vezes roguei ao Senhor que o afastasse de mim;', 1, CURRENT_TIMESTAMP, false),
(47, 12, 9, 'e ele me disse: A minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza. Por isso, de boa vontade antes me gloriarei nas minhas fraquezas, a fim de que repouse sobre mim o poder de Cristo.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 10, 'Pelo que sinto prazer nas fraquezas, nas injúrias, nas necessidades, nas perseguições, nas angústias por amor de Cristo. Porque quando estou fraco, então é que sou forte.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 11, 'Tornei-me insensato; vós a isso me obrigastes; porque eu devia ser louvado por vós, visto que em nada fui inferior aos demais excelentes apóstolos, ainda que nada sou.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 12, 'Os sinais do meu apostolado foram, de fato, operados entre vós com toda a paciência, por sinais, prodígios e milagres.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 13, 'Pois, em que fostes feitos inferiores às outras igrejas, a não ser nisto, que eu mesmo vos não fui pesado? Perdoai-me esta injustiça.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 14, 'Eis que pela terceira vez estou pronto a ir ter convosco, e não vos serei pesado, porque não busco o que é vosso, mas sim a vós; pois não são os filhos que devem entesourar para os pais, mas os pais para os filhos.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 15, 'Eu de muito boa vontade gastarei, e me deixarei gastar pelas vossas almas. Se mais abundantemente vos amo, serei menos amado?', 1, CURRENT_TIMESTAMP, false),
(47, 12, 16, 'Mas seja assim; eu não vos fui pesado; mas, sendo astuto, vos tomei com dolo.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 17, 'Porventura vos explorei por algum daqueles que vos enviei?', 1, CURRENT_TIMESTAMP, false),
(47, 12, 18, 'Exortei a Tito, e enviei com ele o irmão. Porventura Tito vos explorou? Não andamos porventura no mesmo espírito? Não seguimos as mesmas pegadas?', 1, CURRENT_TIMESTAMP, false),
(47, 12, 19, 'Há muito, de certo, pensais que nos estamos desculpando convosco. Perante Deus, falamos em Cristo, e tudo isto, amados, é para vossa edificação.', 1, CURRENT_TIMESTAMP, false),
(47, 12, 20, 'Porque temo que, quando chegar, não vos ache quais eu vos quero, e que eu seja achado por vós qual não me quereis; que de algum modo haja contendas, invejas, iras, porfias, detrações, mexericos, orgulhos, tumultos;', 1, CURRENT_TIMESTAMP, false),
(47, 12, 21, 'e que, quando for outra vez, o meu Deus me humilhe perante vós, e chore eu sobre muitos daqueles que dantes pecaram, e ainda não se arrependeram da impureza, prostituição e lascívia que cometeram.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 1, 'É esta a terceira vez que vou ter convosco. Por boca de duas ou três testemunhas será confirmada toda palavra.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 2, 'Já o disse quando estava presente a segunda vez, e estando agora ausente torno a dizer aos que antes pecaram e a todos os mais que, se outra vez for, não os pouparei.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 3, 'visto que buscais uma prova de que Cristo fala em mim; o qual não é fraco para convosco, antes é poderoso entre vós.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 4, 'Porque, ainda que foi crucificado por fraqueza, vive contudo pelo poder de Deus. Pois nós também somos fracos nele, mas viveremos com ele pelo poder de Deus para convosco.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 5, 'Examinai-vos a vós mesmos se permaneceis na fé; provai-vos a vós mesmos. Ou não sabeis quanto a vós mesmos, que Jesus Cristo está em vós? Se não é que já estais reprovados.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 6, 'Mas espero que entendereis que nós não somos reprovados.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 7, 'Ora, rogamos a Deus que não façais mal algum, não para que nós pareçamos aprovados, mas que vós façais o bem, embora nós sejamos como reprovados.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 8, 'Porque nada podemos contra a verdade, porém, a favor da verdade.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 9, 'Pois nos regozijamos quando nós estamos fracos e vós sois fortes; e isto é o que rogamos, a saber, o vosso aperfeiçoamento.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 10, 'Portanto, escrevo estas coisas estando ausente, para que, quando estiver presente, não use de rigor, segundo a autoridade que o Senhor me deu para edificação, e não para destruição.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 11, 'Quanto ao mais, irmãos, regozijai-vos, sede perfeitos, sede consolados, sede de um mesmo parecer, vivei em paz; e o Deus de amor e de paz será convosco.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 12, 'Saudai-vos uns aos outros com ósculo santo.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 13, 'Todos os santos vos saúdam.', 1, CURRENT_TIMESTAMP, false),
(47, 13, 14, 'A graça do Senhor Jesus Cristo, e o amor de Deus, e a comunhão do Espírito Santo sejam com todos vós.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 1, 'Ora, Salomão, filho de Davi, fortaleceu-se no seu reino, e o Senhor seu Deus era com ele, e muito o engrandeceu.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 2, 'E falou Salomão a todo o Israel, aos chefes de mil e de cem, e aos juízes, e a todos os príncipes em todo o Israel, chefes das casas paternas.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 3, 'E foi Salomão, e toda a congregação com ele, ao alto que estava em Gibeão porque ali estava a tenda da revelação de Deus, que Moisés, servo do Senhor, tinha feito no deserto.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 4, 'Mas Davi tinha feito subir a arca de Deus de Quiriate-Jearim ao lugar que lhe preparara; pois lhe havia armado uma tenda em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 5, 'Também o altar de bronze feito por Bezaleel, filho de Uri, filho de Hur, estava ali diante do tabernáculo do Senhor; e Salomão e a congregação o buscavam.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 6, 'E Salomão ofereceu ali sacrifícios perante o Senhor, sobre o altar de bronze que estava junto à tenda da revelação; ofereceu sobre ele mil holocaustos.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 7, 'Naquela mesma noite Deus apareceu a Salomão, e lhe disse: Pede o que queres que eu te dê.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 8, 'E Salomão disse a Deus: Tu usaste de grande benevolência para com meu pai Davi, e a mim me fizeste rei em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 9, 'Agora, pois, ó Senhor Deus, confirme-se a tua promessa, dada a meu pai Davi; porque tu me fizeste rei sobre um povo numeroso como o pó da terra.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 10, 'Dá-me, pois, agora sabedoria e conhecimento, para que eu possa sair e entrar perante este povo; pois quem poderá julgar este teu povo, que é tão grande?', 1, CURRENT_TIMESTAMP, false),
(14, 1, 11, 'Então Deus disse a Salomão: Porquanto houve isto no teu coração, e não pediste riquezas, bens ou honra, nem a morte dos que te odeiam, nem tampouco pediste muitos dias de vida, mas pediste para ti sabedoria e conhecimento para poderes julgar o meu povo, sobre o qual te fiz reinar,', 1, CURRENT_TIMESTAMP, false),
(14, 1, 12, 'sabedoria e conhecimento te são dados; também te darei riquezas, bens e honra, quais não teve nenhum rei antes de ti, nem haverá depois de ti rei que tenha coisas semelhantes.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 13, 'Assim Salomão veio a Jerusalém, do alto que estava em Gibeão, de diante da tenda da revelação; e reinou sobre Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 14, 'Salomão ajuntou carros e cavaleiros; teve mil e quatrocentos carros e doze mil cavaleiros, que colocou nas cidades dos carros e junto de si em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 15, 'E o rei tornou o ouro e a prata tão comuns em Jerusalém como as pedras, e os cedros tantos em abundância como os sicômoros que há na baixada.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 16, 'Os cavalos que Salomão tinha eram trazidos do Egito e de Coa; e os mercadores do rei os recebiam de Coa por preço determinado.', 1, CURRENT_TIMESTAMP, false),
(14, 1, 17, 'E faziam subir e sair do Egito cada carro por seiscentos siclos de prata, e cada cavalo por cento e cinqüenta; e assim por meio deles eram exportados para todos os reis dos heteus, e para os reis da Síria.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 1, 'Ora, resolveu Salomão edificar uma casa ao nome do Senhor, como também uma casa real para si.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 2, 'Designou, pois, Salomão setenta mil homens para servirem de carregadores, e oitenta mil para cortarem pedras na montanha, e três mil e seiscentos inspetores sobre eles.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 3, 'E Salomão mandou dizer a Hurão, rei de Tiro: Como fizeste com Davi, meu pai, mandando-lhe cedros para edificar uma casa em que morasse, assim também fazem comigo.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 4, 'Eis que vou edificar uma casa ao nome do Senhor meu Deus e lha consagrar para queimar perante ele incenso aromático, para apresentar continuamente, o pão da preposição, e para oferecer os holocaustos da manhã e da tarde, nos sábados, nas luas novas e nas festas fixas do Senhor nosso Deus; o que é obrigação perpétua de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 5, 'A casa que vou edificar há de ser grande, porque o nosso Deus é maior do que todos os deuses.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 6, 'Mas quem é capaz de lhe edificar uma casa, visto que o céu e até o céu dos céus o não podem conter? E quem sou eu, para lhe edificar uma casa, a não ser para queimar incenso perante ele?', 1, CURRENT_TIMESTAMP, false),
(14, 2, 7, 'Agora, pois, envia-me um homem hábil para trabalhar em ouro, em prata, em bronze, em ferro, em púrpura, em carmesim, e em azul, e que saiba lavrar ao buril, para estar com os peritos que estão comigo em Judá e em Jerusalém, os quais Davi, meu pai, escolheu.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 8, 'Manda-me também madeiras de cedro, de cipreste, e de algumins do Líbano; porque bem sei eu que os teus servos sabem cortar madeira no Líbano; e eis que os meus servos estarão com os teus servos,', 1, CURRENT_TIMESTAMP, false),
(14, 2, 9, 'a fim de me prepararem madeiras em abundância, porque a casa que vou edificar há de ser grande e maravilhosa.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 10, 'E aos teus servos, os trabalhadores que cortarem a madeira, darei vinte mil coros de trigo malhado, vinte mil coros de cevada, vinte mil batos de vinho e vinte mil batos de azeite.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 11, 'Hurão, rei de Tiro, mandou por escrito resposta a Salomão, dizendo: Porquanto o Senhor ama o seu povo, te constituiu rei sobre ele.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 12, 'Disse mais Hurão: Bendito seja o Senhor Deus de Israel, que fez o céu e a terra, que deu ao rei Davi um filho sábio, de grande prudência e entendimento para edificar uma casa ao Senhor, e uma casa real para si.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 13, 'Agora, pois, envio um homem perito, de entendimento, a saber, Hurão-Abi,', 1, CURRENT_TIMESTAMP, false),
(14, 2, 14, 'filho duma mulher das filhas de Dã, e cujo pai foi um homem de Tiro; este sabe trabalhar em ouro, em prata, em bronze, em ferro, em pedras e em madeira, em púrpura, em azul, em linho fino, e em carmesim, e é hábil para toda obra de buril, e para toda espécie de engenhosas invenções; para que lhe seja designado um lugar juntamente com os teus peritos, e com os peritos de teu pai Davi, meu senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 15, 'Agora mande meu senhor para os seus servos o trigo, a cevada, o azeite, e o vinho, de que falou;', 1, CURRENT_TIMESTAMP, false),
(14, 2, 16, 'e nós cortaremos tanta madeira do Líbano quanta precisares, e a levaremos em jangadas pelo mar até Jope, e tu mandarás transportá-la para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 17, 'Salomão contou todos os estrangeiros que havia na terra de Israel, segundo o recenseamento que seu pai Davi fizera; e acharam-se cento e cinqüenta e três mil e seiscentos.', 1, CURRENT_TIMESTAMP, false),
(14, 2, 18, 'E deles separou setenta mil para servirem de carregadores, e oitenta mil para cortarem madeira na montanha, como também três mil e seiscentos inspetores para fazerem trabalhar o povo.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 1, 'Então Salomão começou a edificar a casa do Senhor em Jerusalém, no monte Moriá, onde o Senhor aparecera a Davi, seu pai, no lugar que Davi tinha preparado na eira de Ornã, o jebuseu.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 2, 'Começou a edificar no segundo dia do segundo mês, no quarto ano do seu reinado.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 3, 'Estes foram os fundamentos que Salomão pôs para edificar a casa de Deus. O comprimento em côvados, segundo a primitiva medida, era de sessenta côvados, e a largura de vinte côvados:', 1, CURRENT_TIMESTAMP, false),
(14, 3, 4, 'O pórtico que estava na frente tinha vinte côvados de comprimento, correspondendo à largura da casa, e a altura era de cento e vinte; e por dentro o revestiu de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 5, 'A câmara maior forrou com madeira de cipreste e a cobriu de ouro fino, no qual gravou palmas e cadeias.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 6, 'Para ornamento guarneceu a câmara de pedras preciosas; e o ouro era ouro de Parvaim.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 7, 'Também revestiu de ouro as traves e os umbrais, bem como as paredes e portas da câmara, e lavrou querubins nas paredes.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 8, 'Fez também a câmara santíssima, cujo comprimento era de vinte côvados, correspondendo à largura da casa, e a sua largura era de vinte côvados; e a revestiu de ouro fino, do peso de seiscentos talentos.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 9, 'O peso dos pregos era de cinqüenta siclos de ouro. Também revestiu de ouro os cenáculos.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 10, 'Também fez na câmara santíssima dois querubins de madeira, e os cobriu de ouro.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 11, 'As asas dos querubins tinham vinte côvados de comprimento: uma asa de um deles, tendo cinco côvados, tocava na parede da casa, e a outra asa, tendo também cinco côvados, tocava na asa do outro querubim;', 1, CURRENT_TIMESTAMP, false),
(14, 3, 12, 'também a asa deste querubim, tendo cinco côvados, tocava na parede da casa, e a outra asa, tendo igualmente cinco côvados, estava unida à asa do primeiro querubim.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 13, 'Assim as asas destes querubins se estendiam por vinte côvados; eles estavam postos em pé, com os rostos virados para a câmara.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 14, 'Também fez o véu de azul, púrpura, carmesim e linho fino; e fez bordar nele querubins.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 15, 'Diante da casa fez duas colunas de trinta e cinco côvados de altura; e o capitel que estava sobre cada uma era de cinco côvados.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 16, 'Também fez cadeias no oráculo, e as pôs sobre o alto das colunas; fez também cem romãs, as quais pôs nas cadeias.', 1, CURRENT_TIMESTAMP, false),
(14, 3, 17, 'E levantou as colunas diante do templo, uma à direita, e outra à esquerda; e chamou o nome da que estava à direita Jaquim, e o nome da que estava à esquerda Boaz.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 1, 'Além disso fez um altar de bronze de vinte côvados de comprimento, vinte de largura e dez de altura.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 2, 'Fez também o mar de fundição; era redondo e media dez côvados duma borda à outra, cinco de altura e trinta de circunferência.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 3, 'Por baixo da borda figuras de bois que cingiam o mar ao redor, dez em cada côvado, contornando-o todo; os bois estavam em duas fileiras e foram fundidos juntamente com o mar.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 4, 'O mar estava assentado sobre doze bois, três dos quais olhavam para o norte, três para o ocidente, três para o sul, e três para o oriente; e o mar estava posto sobre os bois, cujas ancas estavam todas para a banda de dentro.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 5, 'Tinha quatro dedos de grossura; e a sua borda foi feita como a borda dum copo, como a flor dum lírio; e cabiam nele mais de três mil batos.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 6, 'Fez também dez pias; e pôs cinco à direita e cinco à esquerda, para lavarem nelas; isto é, lavaram nelas o que pertencia ao holocausto. Porém o mar era para os sacerdotes se lavarem nele.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 7, 'E fez dez castiçais de ouro, segundo o que fora ordenado a respeito deles, e pô-los no templo, cinco à direita e cinco à esquerda.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 8, 'Também fez dez mesas, e pô-las no templo, cinco à direita e cinco à esquerda; e fez ainda cem bacias de ouro.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 9, 'Fez mais o átrio dos sacerdotes, e o átrio grande, e as suas portas, as quais revestiu de bronze.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 10, 'E pôs o mar ao lado direito da casa, a sudeste.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 11, 'Hurão fez ainda as caldeiras, as pás e as bacias. Assim completou Hurão a obra que fazia para o rei Salomão na casa de Deus:', 1, CURRENT_TIMESTAMP, false),
(14, 4, 12, 'as duas colunas, os globos, e os dois capitéis no alto das colunas; as duas redes para cobrir os dois globos dos capitéis que estavam no alto das colunas;', 1, CURRENT_TIMESTAMP, false),
(14, 4, 13, 'e as quatrocentas romãs para as duas redes, duas fileiras de romãs para cada rede, para cobrirem os dois globos dos capitéis que estavam em cima das colunas.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 14, 'Também fez as bases, e as pias sobre as bases;', 1, CURRENT_TIMESTAMP, false),
(14, 4, 15, 'o mar, e os doze bois debaixo dele.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 16, 'Semelhantemente as caldeiras, as pás, os garfos e todos os vasos, os fez Hurão-Abi de bronze luzente para o rei Salomão, para a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 17, 'Na campina do Jordão os fundiu o rei, na terra argilosa entre Sucote e Zeredá.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 18, 'Salomão fez todos estes vasos em grande abundância, de sorte que o peso do bronze não se podia averiguar.', 1, CURRENT_TIMESTAMP, false),
(14, 4, 19, 'Assim fez Salomão todos os vasos que eram para a casa de Deus, o altar de ouro, as mesas para os pães da proposição,', 1, CURRENT_TIMESTAMP, false),
(14, 4, 20, 'os castiçais com as suas lâmpadas, de ouro puro, para arderem perante o oráculo, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(14, 4, 21, 'as flores, as lâmpadas e as tenazes, de ouro puríssimo,', 1, CURRENT_TIMESTAMP, false),
(14, 4, 22, 'como também as espevitadeiras, as bacias, as colheres e os braseiros, de ouro puro. Quanto à entrada da casa, tanto as portas internas, do lugar santíssimo, como as portas da casa, isto é, do santuário, eram de ouro.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 1, 'Assim se completou toda a obra que Salomão fez para a casa do Senhor. Então trouxe Salomão as coisas que seu pai Davi tinha consagrado, a saber, a prata, e ouro e todos os vasos, e os pôs nos tesouros da casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 2, 'Então Salomão congregou em Jerusalém os anciãos de Israel, e todos as cabeças das tribos, os chefes das casas paternas dos filhos de Israel, para fazerem subir da cidade de Davi, que é Sião, a arca do pacto do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 3, 'E todos os homens de Israel se congregaram ao rei na festa, no sétimo mês.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 4, 'E, tendo chegado todos os anciãos de Israel; os levitas levantaram a arca;', 1, CURRENT_TIMESTAMP, false),
(14, 5, 5, 'e fizeram subir a arca, a tenda da revelação e todos os utensílios sagrados que estavam na tenda; os sacerdotes levitas os levaram.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 6, 'Então o rei Salomão e toda a congregação de Israel, que se havia reunido a ele diante da arca, sacrificavam carneiros e bois, que não se podiam contar nem numerar por causa da sua multidão.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 7, 'Assim trouxeram os sacerdotes a arca do pacto do Senhor para o seu lugar, no oráculo da casa, no lugar santíssimo, debaixo das asas dos querubins.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 8, 'Porque os querubins estendiam as asas sobre o lugar da arca, cobrindo a arca e os seus varais:', 1, CURRENT_TIMESTAMP, false),
(14, 5, 9, 'Os varais eram tão compridos que as suas pontas se viam perante o oráculo, mas não se viam de fora; e ali tem estado a arca até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 10, 'Na arca não havia coisa alguma senão as duas tábuas que Moisés ali tinha posto em Horebe, quando o Senhor fez um pacto com os filhos de Israel, ao saíram eles do Egito.', 1, CURRENT_TIMESTAMP, false),
(14, 5, 11, 'Quando os sacerdotes saíram do lugar santo {pois todos os sacerdotes que se achavam presentes se tinham santificado, sem observarem a ordem das suas turmas;', 1, CURRENT_TIMESTAMP, false),
(14, 5, 12, 'também os levitas que eram cantores, todos eles, a saber, Asafe, Remã, Jedútum e seus filhos, e seus irmãos, vestidos de linho fino, com címbalos, com alaúdes e com harpas, estavam em pé ao lado oriental do altar, e juntamente com eles cento e vinte sacerdotes, que tocavam as trombetas} ,', 1, CURRENT_TIMESTAMP, false),
(14, 5, 13, 'quando os trombeteiros e os cantores estavam acordes em fazerem ouvir uma só voz, louvando ao Senhor e dando-lhe graças, e quando levantavam a voz com trombetas, e címbalos, e outros instrumentos de música, e louvavam ao Senhor, dizendo: Porque ele é bom, porque a sua benignidade dura para sempre; então se encheu duma nuvem a casa, a saber, a casa do Senhor,', 1, CURRENT_TIMESTAMP, false),
(14, 5, 14, 'de modo que os sacerdotes não podiam ter-se em pé, para ministrar, por causa da nuvem; porque a glória do Senhor encheu a casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 1, 'Então disse Salomão: O Senhor disse que habitaria nas trevas.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 2, 'E eu te construí uma casa para morada, um lugar para a tua eterna habitação.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 3, 'Então o rei virou o rosto e abençoou toda a congregação de Israel; e toda a congregação estava em pé.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 4, 'E ele disse: Bendito seja o Senhor Deus de Israel, que pelas suas mãos cumpriu o que falou pela sua boca a Davi, meu pai, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 6, 5, 'Desde o dia em que tirei o meu povo da terra do Egito não escolhi cidade alguma de todas as tribos de Israel, para edificar nela uma casa em que estivesse o meu nome, nem escolhi homem algum para ser chefe do meu povo Israel;', 1, CURRENT_TIMESTAMP, false),
(14, 6, 6, 'mas escolhi Jerusalém para que ali estivesse o meu nome; e escolhi Davi para que estivesse sobre o meu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 7, 'Davi, meu pai, teve no seu coração o propósito de edificar uma casa ao nome do Senhor, Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 8, 'Mas o Senhor disse a Davi, meu pai: Porquanto tiveste no teu coração o propósito de edificar uma casa ao meu nome, fizeste bem em ter isto no teu coração.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 9, 'Contudo tu não edificarás a casa, mas teu filho, que há de proceder de teus lombos, esse edificará a casa ao meu nome.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 10, 'Assim cumpriu o Senhor a palavra que falou; pois eu me levantei em lugar de Davi, meu pai, e me assentei sobre o trono de Israel, como prometeu o Senhor, e edifiquei a casa ao nome do Senhor, Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 11, 'E pus nela a arca, em que está o pacto que o Senhor fez com os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 12, 'Depois Salomão se colocou diante do altar do Senhor, na presença de toda a congregação de Israel, e estendeu as mãos', 1, CURRENT_TIMESTAMP, false),
(14, 6, 13, '{pois Salomão tinha feito uma plataforma de bronze, de cinco côvados de comprimento, cinco de largura e três de altura, a qual tinha posto no meio do átrio; a ela assomou e, pondo-se de joelhos perante toda a congregação de Israel, estendeu as mãos para o céu},', 1, CURRENT_TIMESTAMP, false),
(14, 6, 14, 'e disse: Ó Senhor, Deus de Israel, não há, nem no céu nem na terra, Deus semelhante a ti, que guardas o pacto e a beneficência para com os teus servos que andam perante ti de todo o seu coração;', 1, CURRENT_TIMESTAMP, false),
(14, 6, 15, 'que cumpriste ao teu servo Davi, meu pai, o que lhe falaste; sim, pela tua boca o disseste, e pela tua mão o cumpriste, como se vê neste dia.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 16, 'Agora, pois, Senhor, Deus de Israel, cumpre ao teu servo Davi, meu pai, o que lhe promete-te, dizendo: Nunca te faltará varão diante de mim, que se assente sobre o trono de Israel; tão somente que teus filhos guardem o seu caminho para andarem na minha lei, como tu andaste diante de mim.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 17, 'Agora pois, Senhor, Deus de Israel, confirme-se a tua palavra, que falaste ao teu servo Davi.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 18, 'Mas, na verdade, habitará Deus com os homens na terra? Eis que o céu e o céu dos céus não te podem conter; quanto menos esta casa que tenho edificado!', 1, CURRENT_TIMESTAMP, false),
(14, 6, 19, 'Contudo, atende à oração e à súplica do teu servo, ó Senhor meu Deus, para ouvires o clamor e a oração que o teu servo faz diante de ti;', 1, CURRENT_TIMESTAMP, false),
(14, 6, 20, 'que dia e noite estejam os teus olhos abertos para esta casa, sim, para o lugar de que disseste que ali porias o teu nome; para ouvires a oração que o teu servo fizer neste lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 21, 'Ouve as súplicas do teu servo, e do teu povo Israel, que fizerem neste lugar; sim, ouve do lugar da tua habitação, do céu; e, ouvindo, perdoa.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 22, 'Se alguém pecar contra o seu próximo, e lhe for exigido que jure, e ele vier jurar perante o teu altar, nesta casa,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 23, 'ouve então do céu, age, e julga os teus servos: paga ao culpado, fazendo recair sobre a sua cabeça o seu proceder, e justifica ao reto, retribuindo-lhe segundo a sua retidão.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 24, 'Se o teu povo Israel for derrotado diante do inimigo, por ter pecado contra ti; e eles se converterem, e confessarem o teu nome, e orarem e fizerem súplicas diante de ti nesta casa,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 25, 'ouve então do céu, e perdoa os pecados do teu povo Israel, e torna a levá-los para a terra que lhes deste a eles e a seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 26, 'Se o céu se fechar e não houver chuva, por terem pecado contra ti; se orarem, voltados para este lugar, e confessarem o teu nome, e se converterem dos seus pecados, quando tu os afligires,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 27, 'ouve então do céu, e perdoa o pecado dos teus servos, e do teu povo Israel, ensinando-lhes o bom caminho, em que devem andar, envia chuva sobre a tua terra, que deste ao teu povo em herança.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 28, 'Se houver na terra fome ou peste, se houver crestamento ou ferrugem, gafanhotos ou lagarta; se os seus inimigos os cercarem nas suas cidades; seja qual for a praga ou doença que houver;', 1, CURRENT_TIMESTAMP, false),
(14, 6, 29, 'toda oração e toda súplica que qualquer homem ou todo o teu povo Israel fizer, conhecendo cada um a sua praga e a sua dor, e estendendo as suas mãos para esta casa,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 30, 'ouve então do céu, lugar da tua habitação, e perdoa, e dá a cada um conforme todos os seus caminhos, segundo vires o seu coração {pois tu, só tu conheces o coração dos filhos dos homens}', 1, CURRENT_TIMESTAMP, false),
(14, 6, 31, 'para que te temam e andem nos teus caminhos todos os dias que viverem na terra que deste a nossos pais.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 32, 'Assim também ao estrangeiro, que não é do teu povo Israel, quando vier de um país remoto por amor do teu grande nome, da tua mão poderosa e do teu braço estendido, vindo ele e orando nesta casa,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 33, 'ouve então do céu, lugar da tua habitação, e faze conforme tudo o que o estrangeiro te suplicar, a fim de que todos os povos da terra conheçam o teu nome, e te temam como o teu povo Israel, e saibam que pelo teu nome é chamada esta casa que edifiquei.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 34, 'Se o teu povo sair à guerra contra os seus inimigos, seja qual for o caminho por que os enviares, e orarem a ti, voltados para esta cidade que escolheste e para a casa que edifiquei ao teu nome,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 35, 'ouve então do céu a sua oração e a sua súplica, e defende a sua causa.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 36, 'Se pecarem contra ti {pois não há homem que não peque}, e tu te indignares contra eles, e os entregares ao inimigo, de modo que os levem em cativeiro para alguma terra, longínqua ou próxima;', 1, CURRENT_TIMESTAMP, false),
(14, 6, 37, 'se na terra para onde forem levados em cativeiro caírem em si, e se converterem, e na terra do seu cativeiro te suplicarem, dizendo: Pecamos, cometemos iniqüidade, procedemos perversamente;', 1, CURRENT_TIMESTAMP, false),
(14, 6, 38, 'se eles se arrependerem de todo o seu coração e de toda a sua alma, na terra do seu cativeiro, a que os tenham levado cativos, e orarem voltados para a sua terra, que deste a seus pais, e para a cidade que escolheste, e para a casa que edifiquei ao teu nome,', 1, CURRENT_TIMESTAMP, false),
(14, 6, 39, 'ouve então do céu, lugar da tua habitação, a sua oração e as suas súplicas, defende a sua causa e perdoa ao teu povo que houver pecado contra ti.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 40, 'Agora, ó meu Deus, estejam os teus olhos abertos, e os teus ouvidos atentos à oração que se fizer neste lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 41, 'Levanta-te pois agora, Senhor Deus, e vem para o lugar do teu repouso, tu e a arca da tua fortaleza; sejam os teus sacerdotes, ó Senhor Deus, vestidos de salvação, e os teus santos se regozijem no bem.', 1, CURRENT_TIMESTAMP, false),
(14, 6, 42, 'Senhor Deus, não faças virar o rosto do teu ungido; lembra-te das tuas misericórdias para com teu servo Davi!', 1, CURRENT_TIMESTAMP, false),
(14, 7, 1, 'Tendo Salomão acabado de orar, desceu fogo do céu e consumiu o holocausto e os sacrifícios; e a glória do Senhor encheu a casa.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 2, 'E os sacerdotes não podiam entrar na casa do Senhor, porque a glória do Senhor tinha enchido a sua casa.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 3, 'E todos os filhos de Israel, vendo descer o fogo, e a glória do Senhor sobre a casa, prostraram-se com o rosto em terra sobre o pavimento, adoraram ao Senhor e lhe deram graças, dizendo: Porque ele é bom; porque a sua benignidade dura para sempre.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 4, 'Então o rei e todo o povo ofereceram sacrifícios perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 5, 'E o rei Salomão ofereceu em sacrifício vinte e dois mil bois e cento e vinte mil ovelhas. Assim o rei e todo o povo consagraram a casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 6, 'Os sacerdotes estavam em pé nos seus postos, como também os levitas com os instrumentos musicais do Senhor, que o rei Davi tinha feito para dar graças ao Senhor {porque a sua benignidade dura para sempre}, quando Davi o louvava pelo ministério deles; e os sacerdotes tocavam trombetas diante deles; e todo o Israel estava em pé.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 7, 'Salomão consagrou também o meio do átrio que estava diante da casa do Senhor; porquanto ali ele ofereceu os holocaustos e a gordura das ofertas pacíficas; pois no altar de bronze que Salomão tinha feito não cabiam o holocausto, e a oferta de cereais e a gordura.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 8, 'Assim naquele tempo celebrou Salomão a festa por sete dias, e todo o Israel com ele, uma grande congregação, vinda desde a entrada de Hamate e desde o rio do Egito.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 9, 'E no oitavo dia celebraram uma assembléia solene, pois haviam celebrado por sete dias a dedicação do altar, e por sete dias a festa.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 10, 'E, no vigésimo terceiro dia do sétimo, mês, ele despediu o povo para as suas tendas, alegre e de bom ânimo pelo bem que o Senhor tinha feito a Davi e a Salomão, e a seu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 11, 'Assim Salomão acabou a casa do Senhor e a casa do rei; tudo quanto Salomão intentara fazer na casa do Senhor e na sua própria casa, ele o realizou com êxito.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 12, 'E o Senhor apareceu de noite a Salomão e lhe disse: Eu ouvi a tua oração e escolhi para mim este lugar para casa de sacrifício.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 13, 'Se eu cerrar o céu de modo que não haja chuva, ou se ordenar aos gafanhotos que consumam a terra, ou se enviar a peste entre o meu povo;', 1, CURRENT_TIMESTAMP, false),
(14, 7, 14, 'e se o meu povo, que se chama pelo meu nome, se humilhar, e orar, e buscar a minha face, e se desviar dos seus maus caminhos, então eu ouvirei do céu, e perdoarei os seus pecados, e sararei a sua terra.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 15, 'Agora estarão abertos os meus olhos e atentos os meus ouvidos à oração que se fizer neste lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 16, 'Pois agora escolhi e consagrei esta casa, para que nela esteja o meu nome para sempre; e nela estarão fixos os meus olhos e o meu coração perpetuamente.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 17, 'E, quanto a ti, se andares diante de mim como andou Davi, teu pai, fazendo conforme tudo o que te ordenei, guardando os meus estatutos e as minhas ordenanças,', 1, CURRENT_TIMESTAMP, false),
(14, 7, 18, 'então confirmarei o trono do teu reino, conforme o pacto que fiz com Davi, teu pai, dizendo: Não te faltará varão que governe em Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 19, 'Mas se vos desviardes, e deixardes os meus estatutos e os meus mandamentos, que vos tenho proposto, e fordes, e servirdes a outros deuses, e os adorardes,', 1, CURRENT_TIMESTAMP, false),
(14, 7, 20, 'então vos arrancarei da minha terra que vos dei; e esta casa que consagrei ao meu nome, lançá-la-ei da minha presença, e farei com que ela seja por provérbio e motejo entre todos os povos.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 21, 'E desta casa, que é tão exaltada, se espantará qualquer que por ela passar, e dirá: Por que fez o Senhor assim a esta terra e a esta casa.', 1, CURRENT_TIMESTAMP, false),
(14, 7, 22, 'E lhe responderão: Porquanto deixaram ao Senhor Deus de seus pais, que os tirou da terra do Egito, e se apegaram a outros deuses, e os adoraram e os serviram; por isso trouxe sobre eles todo este mal', 1, CURRENT_TIMESTAMP, false),
(14, 8, 1, 'Ao fim de vinte anos, nos quais Salomão tinha edificado a casa do Senhor e a sua própria casa', 1, CURRENT_TIMESTAMP, false),
(14, 8, 2, 'Salomão edificou as casas que Salomão tinha dado, e fez habitar nelas os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 3, 'Depois foi Salomão a Hamate-Zobá, e apoderou-se dela.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 4, 'E edificou Tadmor no deserto, e todas as cidades-armazéns, que edificou em Hamate.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 5, 'Edificou também Bete-Horom, tanto a alta como a baixa, cidades fortes, com muros, portas e ferrolhos;', 1, CURRENT_TIMESTAMP, false),
(14, 8, 6, 'como também Baalate, e todas as cidades-armazéns que Salomão tinha, e todas as cidades para os seus carros e as cidades para os seus cavaleiros, e tudo quanto Salomão desejava edificar em Jerusalém, no Líbano e em toda a terra do seu domínio.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 7, 'Quanto a todo o povo que tinha ficado dos heteus, dos amorreus, dos perizeus, dos heveus e dos jebuseus, os quais não eram de Israel;', 1, CURRENT_TIMESTAMP, false),
(14, 8, 8, 'a seus filhos, que ficaram depois deles na terra, os quais os filhos de Israel não destruíram, Salomão lhes impôs tributo de trabalho forçado, até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 9, 'Mas dos filhos de Israel Salomão não fez escravo algum para a sua obra; porém eram homens de guerra, chefes dos seus capitães, e chefes dos seus carros e dos seus cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 10, 'Estes eram os chefes dos oficiais que o rei Salomão tinha, duzentos e cinqüenta; que presidiam sobre o seu povo.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 11, 'E Salomão levou a filha do Faraó da cidade de Davi para a casa que lhe edificara; pois disse: Minha mulher não morará na casa de Davi, rei de Israel, porquanto os lugares nos quais entrou a arca do Senhor são santos.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 12, 'Então Salomão ofereceu holocaustos ao Senhor, sobre o altar do Senhor, que edificara diante do pórtico;', 1, CURRENT_TIMESTAMP, false),
(14, 8, 13, 'e isto segundo o dever de cada dia, fazendo ofertas segundo o mandamento de Moisés, nos sábados e nas luas novas, e nas três festas anuais, a saber: na festa dos pães ázimos, na festa das semanas, e na festa dos tabernáculos.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 14, 'Também, conforme a ordem de Davi, seu pai, designou as turmas dos sacerdotes para os seus cargos, como também os levitas para os seus cargos, para louvarem a Deus e ministrarem diante dos sacerdotes, como exigia o dever de cada dia, e ainda os porteiros, pelas suas turmas, a cada porta; pois assim tinha mandado Davi, o homem de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 15, 'E os sacerdotes e os levitas não se desviaram do que lhes mandou o rei, em negócio nenhum, especialmente no tocante aos tesouros.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 16, 'Assim se executou toda a obra de Salomão, desde o dia em que se lançaram os fundamentos da casa do Senhor, até se acabar. Deste modo se completou a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 17, 'Então Salomão foi a Eziom-Geber, e a Elote, à praia do mar, na terra de Edom.', 1, CURRENT_TIMESTAMP, false),
(14, 8, 18, 'E Hurão, por meio de seus servos, enviou-lhe navios, e servos práticos do mar; e eles foram com os servos de Salomão a Ofir, e de lá tomaram quatrocentos e cinqüenta talentos de ouro, e os trouxeram ao rei Salomão.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 1, 'Tendo a rainha de Sabá ouvido da fama de Salomão, veio a Jerusalém para prová-lo por enigmas; trazia consigo uma grande comitiva, e camelos carregados de especiarias, e ouro em abundância, e pedras preciosas; e vindo ter com Salomão, falou com ele de tudo o que tinha no seu coração.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 2, 'E Salomão lhe respondeu a todas as perguntas; não houve nada que Salomão não lhe soubesse explicar.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 3, 'Vendo, pois, a rainha de Sabá a sabedoria de Salomão, e a casa que ele edificara,', 1, CURRENT_TIMESTAMP, false),
(14, 9, 4, 'e as iguarias da sua mesa, e o assentar dos seus oficiais, e as funções e os trajes dos seus servos, e os seus copeiros e os trajes deles, e os holocaustos que ele oferecia na casa do Senhor, ficou estupefata.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 5, 'Então disse ao rei: Era verdade o que ouvi na minha terra acerca dos teus feitos e da tua sabedoria.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 6, 'Todavia eu não o acreditava, até que vim e os meus olhos o viram; e eis que não me contaram metade da grandeza da tua sabedoria; sobrepujaste a fama que ouvi.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 7, 'Bem-aventurados os teus homens! Bem-aventurados estes teus servos, que estão sempre diante de ti, e ouvem a tua sabedoria!', 1, CURRENT_TIMESTAMP, false),
(14, 9, 8, 'Bendito seja o Senhor teu Deus, que se agradou de ti, colocando-te sobre o seu trono, para ser rei pelo Senhor teu Deus! Porque teu Deus amou a Israel, para o estabelecer perpetuamente, por isso te constituiu rei sobre eles, para executares juízo e justiça.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 9, 'Então ela deu ao rei cento e vinte talentos de ouro, e especiarias em grande abundância, e pedras preciosas; e nunca houve tais especiarias quais a rainha de Sabá deu ao rei Salomão.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 10, 'Também os servos de Hurão, e os servos de Salomão, que de Ofir trouxeram ouro, trouxeram madeira de algumins, e pedras preciosas.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 11, 'E o rei fez, da madeira de algumins, degraus para a casa do Senhor e para a casa do rei, como também harpas e alaúdes para os cantores, quais nunca dantes se viram na terra de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 12, 'E o rei Salomão deu à rainha de Sabá tudo quanto ela desejou, tudo quanto lhe pediu, excedendo mesmo o que ela trouxera ao rei. Assim voltou e foi para a sua terra, ela e os seus servos.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 13, 'Ora, o peso do ouro que se trazia cada ano a Salomão era de seiscentos e sessenta e seis talentos,', 1, CURRENT_TIMESTAMP, false),
(14, 9, 14, 'afora o que os mercadores e negociantes traziam; também todos os reis da Arábia, e os governadores do país traziam a Salomão ouro e prata.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 15, 'E o rei Salomão fez duzentos paveses de ouro batido, empregando em cada pavês seiscentos siclos de ouro batido;', 1, CURRENT_TIMESTAMP, false),
(14, 9, 16, 'como também trezentos escudos de ouro batido, empregando em cada escudo trezentos siclos de ouro. E o rei os depositou na casa do bosque do Líbano.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 17, 'Fez mais o rei um grande trono de marfim, e o revestiu de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 18, 'O trono tinha seis degraus e um estrado de ouro, que eram ligados ao trono, e de ambos os lados tinha braços junto ao lugar do assento, e dois leões de pé junto aos braços.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 19, 'E havia doze leões em pé de um e outro lado sobre os seis degraus; outro tal não se fizera em reino algum.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 20, 'Também todos os vasos de beber do rei Salomão eram de ouro, e todos os utensílios da casa do bosque do Líbano, de ouro puro; a prata reputava-se sem valor nos dias de Salomão.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 21, 'Pois o rei tinha navios que iam a Társis com os servos de Hurão; de três em três anos os navios voltavam de Társis, trazendo ouro, prata, marfim, bugios e pavões.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 22, 'Assim excedeu o rei Salomão todos os reis da terra, em riqueza e em sabedoria.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 23, 'E todos os reis da terra buscavam a presença de Salomão para ouvirem a sabedoria que Deus lhe tinha posto no coração.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 24, 'Cada um trazia o seu presente, vasos de prata, vasos de ouro, vestidos, armaduras, especiarias, cavalos e mulos, uma quota de ano em ano.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 25, 'Teve também Salomão quatro mil manjedouras para os cavalos de seus carros, doze mil cavaleiros; e os colocou nas cidades dos carros, e junto ao rei em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 26, 'Ele dominava sobre todos os reis, desde o Rio Eufrates até a terra dos filisteus, e até o termo do Egito.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 27, 'Também o rei tornou a prata tão comum em Jerusalém como as pedras, e os cedros tantos em abundância como os sicômoros que há na baixada.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 28, 'E cavalos eram trazidos a Salomão do Egito e de todas as terras.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 29, 'Ora, o restante dos atos de Salomão, desde os primeiros até os últimos, porventura não estão escritos na história de Natã, o profeta, e na profecia de Aías, o silonita, e nas visões de Ido, o vidente, acerca de Jeroboão, filho de Nebate?', 1, CURRENT_TIMESTAMP, false),
(14, 9, 30, 'Salomão reinou em Jerusalém quarenta anos sobre todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 9, 31, 'E dormiu com seus pais, e foi sepultado na cidade de Davi, seu pai. E Roboão, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 1, 'Roboão foi a Siquém, pois todo o Israel se congregara ali para fazê-lo rei.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 2, 'E Jeroboão, filho de Nebate, que estava então no Egito para onde fugira da presença do rei Salomão, ouvindo isto, voltou do Egito.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 3, 'E mandaram chamá-lo; Jeroboão e todo o Israel vieram e falaram a Roboão, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 10, 4, 'Teu pai fez duro o nosso jugo; agora, pois, alivia a dura servidão e o pesado jugo que teu pai nos impôs, e nós te serviremos.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 5, 'Ele lhes respondeu: Daqui a três dias tornai a mim. Então o povo se foi.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 6, 'E teve o rei Roboão conselho com os anciãos, que tinham assistido diante de Salomão, seu pai, quando este ainda vivia, e perguntou-lhes: Como aconselhais vós que eu responda a este povo?', 1, CURRENT_TIMESTAMP, false),
(14, 10, 7, 'Eles lhe disseram: Se te fizeres benigno para com este povo, e lhes agradares, e lhes falares boas palavras, então eles serão teus servos para sempre.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 8, 'Mas ele deixou o conselho que os anciãos lhe deram, e teve conselho com os jovens que haviam crescido com ele, e que assistiam diante dele.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 9, 'Perguntou-lhes: Que aconselhais vós que respondamos a este povo que me falou, dizendo: Alivia o jugo que teu pai nos impôs?', 1, CURRENT_TIMESTAMP, false),
(14, 10, 10, 'E os jovens que haviam crescido com ele responderam-lhe Assim dirás a este povo, que te falou, dizendo: Teu pai fez pesado nosso jugo, mas tu o alivia de sobre nós; assim lhe falarás: o meu dedo mínimo é mais grosso do que os lombos de meu pai.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 11, 'Assim que, se meu pai vos carregou dum jugo pesado, eu ainda aumentarei o vosso jugo; meu pai vos castigou com açoites; eu, porém, vos castigarei com escorpiões.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 12, 'Veio, pois, Jeroboão com todo o povo a Roboão, ao terceiro dia, como o rei havia ordenado, dizendo: Voltai a mim ao terceiro dia.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 13, 'E o rei Roboão lhes respondeu asperamente e, deixando o conselho dos anciãos,', 1, CURRENT_TIMESTAMP, false),
(14, 10, 14, 'falou-lhes conforme o conselho dos jovens, dizendo: Meu pai fez pesado o vosso jugo, mas eu lhe acrescentarei mais; meu pai vos castigou com açoites, mas eu vos castigarei com escorpiões.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 15, 'O rei, pois, não deu ouvidos ao povo; porque esta mudança vinha de Deus, para que o Senhor confirmasse a sua palavra, a qual falara por intermédio de Aías, o silonita, a Jeroboão, filho de Nebate.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 16, 'Vendo, pois, todo o Israel que o rei não lhe dava ouvidos, respondeu-lhe dizendo: Que parte temos nós em Davi? Não temos herança no filho de Jessé: Cada um as suas tendas, ó Israel! Agora olha por tua casa, ó Davi! Então todo o Israel se foi para as suas tendas:', 1, CURRENT_TIMESTAMP, false),
(14, 10, 17, '{Mas quanto aos filhos de Israel que habitavam nas cidades de Judá, sobre eles reinou Roboão.}', 1, CURRENT_TIMESTAMP, false),
(14, 10, 18, 'Então o rei Roboão enviou-lhes Hadorão, que estava sobre a leva de tributários servis; mas os filhos de Israel o apedrejaram, de modo que morreu. E o rei Roboão se apressou a subir para o seu carro, e fugiu para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 10, 19, 'Assim se rebelou Israel contra a casa de Davi, até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 1, 'Tendo Roboão chegado a Jerusalém, convocou da casa de Judá e Benjamim cento e oitenta mil escolhidos, destros na guerra, para pelejarem contra Israel a fim de restituírem o reino a Roboão.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 2, 'Veio, porém, a palavra do Senhor a Semaías, homem de Deus, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 11, 3, 'Fala a Roboão, filho de Salomão, rei de Judá, e a todo o Israel em Judá e Benjamim, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 11, 4, 'Assim diz o Senhor: Não subireis, nem pelejareis contra os vossos irmãos; volte cada um à sua casa, porque de mim proveio isto. Ouviram, pois, a palavra do Senhor, e desistiram de ir contra Jeroboão.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 5, 'E Roboão habitou em Jerusalém, e edificou em Judá cidades para fortalezas.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 6, 'Edificou, pois, Belém, Etã, Tecoa,', 1, CURRENT_TIMESTAMP, false),
(14, 11, 7, 'Bete-Zur, Socó, Adulão,', 1, CURRENT_TIMESTAMP, false),
(14, 11, 8, 'Gate, Maressa, Zife,', 1, CURRENT_TIMESTAMP, false),
(14, 11, 9, 'Adoraim, Laquis, Azeca,', 1, CURRENT_TIMESTAMP, false),
(14, 11, 10, 'Zorá, Aijalom e Hebrom, que estão em Judá e em Benjamim, cidades fortes.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 11, 'Fortificou estas cidades e pôs nelas capitães, e armazéns de víveres, de azeite e de vinho.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 12, 'E pôs em cada cidade paveses e lanças, e fortificou-as grandemente, de sorte que reteve Judá e Benjamim.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 13, 'Também os sacerdotes e os levitas que havia em todo o Israel recorreram a ele de todos os seus termos.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 14, 'Pois os levitas deixaram os seus arrabaldes e a sua possessão, e vieram para Judá e para Jerusalém, porque Jeroboão e seus filhos os lançaram fora, para que não exercessem o ofício sacerdotal ao Senhor;', 1, CURRENT_TIMESTAMP, false),
(14, 11, 15, 'e Jeroboão constituiu para si sacerdotes, para os altos, e para os demônios, e para os bezerros que fizera.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 16, 'Além desses, de todas as tribos de Israel, os que determinaram no seu coração buscar ao Senhor Deus de Israel, também vieram a Jerusalém, para oferecerem sacrifícios ao Senhor Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 17, 'Assim fortaleceram o reino de Judá e corroboraram a Roboão, filho de Salomão, por três anos; porque durante três anos andaram no caminho de Davi e Salomão.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 18, 'Roboão tomou para si, por mulher, a Maalate, filha de Jerimote, filho de Davi; e a Abiail, filha de Eliabe, filho de Jessé,', 1, CURRENT_TIMESTAMP, false),
(14, 11, 19, 'a qual lhe deu os filhos Jeús, Semarias e Zaã.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 20, 'Depois dela tomou a Maacá, filha de Absalão; esta lhe deu Abias, Atai, Ziza e Selomite.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 21, 'Amava Roboão a Maacá, filha de Absalão, mais do que a todas as suas outras mulheres e concubinas; pois tinha tomado dezoito mulheres e sessenta concubinas, e gerou vinte e oito filhos e sessenta filhas.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 22, 'E Roboão designou Abias, filho de Maacá, chefe e príncipe entre os seus irmãos, porque queria fazê-lo rei.', 1, CURRENT_TIMESTAMP, false),
(14, 11, 23, 'Também usou de prudência, distribuindo todos os seus filhos por entre todas as terras de Judá e Benjamim, por todas as cidades fortes; e deu-lhes víveres em abundância, e procurou para eles muitas mulheres.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 1, 'E sucedeu que, quando ficou estabelecido o reino de Roboão, e havendo o rei se tornado forte, ele deixou a lei do Senhor, e com ele todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 2, 'Pelo que, no quinto ano da rei Roboão, Sisaque, rei do Egito, subiu contra Jerusalém {porque eles tinham transgredido contra o Senhor}', 1, CURRENT_TIMESTAMP, false),
(14, 12, 3, 'com mil e duzentos carros e sessenta mil cavaleiros; era inumerável a gente que vinha com ele do Egito: líbios, suquitas e etíopes;', 1, CURRENT_TIMESTAMP, false),
(14, 12, 4, 'E tomou as cidades fortificadas de Judá, e chegou até Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 5, 'Então Semaías, o profeta, foi ter com Roboão e com os príncipes de Judá que se tinham ajuntado em Jerusalém por causa de Sisaque, e disse-lhes: Assim diz o Senhor: Vós me deixastes a mim, pelo que eu também vos deixei na mão de Sisaque.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 6, 'Então se humilharam os príncipes de Israel e o rei, e disseram: O Senhor é justo.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 7, 'Quando, pois, o Senhor viu que se humilhavam, veio a palavra do Senhor a Semaías, dizendo: Humilharam-se, não os destruirei; mas dar-lhes-ei algum socorro, e o meu furor não será derramado sobre Jerusalém por mão de Sisaque.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 8, 'Todavia eles lhe serão servos, para que conheçam a diferença entre a minha servidão e a servidão dos reinos da terra.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 9, 'Subiu, pois, Sisaque, rei do Egito, contra Jerusalém, e levou os tesouros da casa do Senhor, e os tesouros da casa do rei; levou tudo. Levou até os escudos de ouro que Salomão fizera.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 10, 'E o rei Roboão fez em lugar deles escudos de bronze, e os entregou na mão dos capitães da guarda, que guardavam a porta da casa do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 11, 'E todas as vezes que o rei entrava na casa do Senhor, vinham os da guarda e os levavam; depois tornavam a pô-los na câmara da guarda.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 12, 'E humilhando-se ele, a ira do Senhor se desviou dele, de modo que não o destruiu de todo; porque ainda havia coisas boas em Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 13, 'Fortaleceu-se, pois, o rei Roboão em Jerusalém, e reinou. Roboão tinha quarenta e um anos quando começou a reinar, e reinou dezessete anos em Jerusalém, a cidade que o Senhor escolhera dentre todas as tribos de Israel, para pôr ali o seu nome. E era o nome de sua mãe Naamá, a amonita.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 14, 'Ele fez o que era mau, porquanto não dispôs o seu coração para buscar ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 15, 'Ora, os atos de Roboão, desde os primeiros até os últimos, porventura não estão escritos nas histórias de Semaías, o profeta, e de Ido, o vidente, na relação das genealogias? Houve guerra entre Roboão e Jeroboão por todos os seus dias.', 1, CURRENT_TIMESTAMP, false),
(14, 12, 16, 'E Roboão dormiu com seus pais, e foi sepultado na cidade de Davi. E Abias, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 1, 'No ano décimo oitavo do rei Jeroboão começou Abias a reinar sobre Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 2, 'Três anos reinou em Jerusalém; o nome de sua mãe era Micaías, filha de Uriel de Gibeá. E houve guerra entre Abias e Jeroboão.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 3, 'Abias dispôs-se para a peleja com um exército de varões valentes, quatrocentos mil homens escolhidos; e Jeroboão dispôs contra ele a batalha com oitocentos mil homens escolhidos, todos homens valentes.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 4, 'Então Abias pôs-se em pé em cima do monte Zemaraim, que está na região montanhosa de Efraim, e disse: Ouvi-me, Jeroboão e todo o Israel:', 1, CURRENT_TIMESTAMP, false),
(14, 13, 5, 'Porventura não vos convém saber que o Senhor Deus de Israel deu para sempre a Davi a soberania sobre Israel, a ele e a seus filhos, por um pacto de sal?', 1, CURRENT_TIMESTAMP, false),
(14, 13, 6, 'Contudo levantou-se Jeroboão, filho de Nebate, servo de Salomão, filho de Davi, e se rebelou contra seu senhor;', 1, CURRENT_TIMESTAMP, false),
(14, 13, 7, 'e ajuntaram-se a ele homens vadios filhos de Belial, e fortaleceram-se contra Roboão, filho de Salomão, sendo Roboão ainda moço e indeciso de coração, e não podendo resistir-lhes.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 8, 'E agora julgais poder resistir ao reino do Senhor, que está na mão dos filhos de Davi, visto que sois uma grande multidão, e tendes convosco os bezerros de ouro que Jeroboão vos fez para deuses.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 9, 'Não lançastes fora os sacerdotes do Senhor, filhos de Arão, e os levitas, e não fizestes para vós sacerdotes, como o fazem os povos das outras terras? Qualquer que vem a consagrar-se, trazendo um novilho e sete carneiros, logo se faz sacerdote daqueles que não são deuses.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 10, 'Mas, quanto a nós, o Senhor é nosso Deus, e nunca o deixamos. Temos sacerdotes que ministram ao Senhor, os quais são filhos de Arão, e os levitas para o seu serviço.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 11, 'Queimam perante o Senhor cada manhã e cada tarde holocausto e incenso aromático; também dispõem os pães da proposição sobre a mesa de ouro puro, e o castiçal de ouro e as suas lâmpadas para se acenderem cada tarde; porque nós temos guardado os preceitos do Senhor nosso Deus; mas vós o deixastes.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 12, 'Eis que Deus está conosco, à nossa frente, como também os seus sacerdotes com as trombetas, para tocarem alarme contra vós. O filhos de Israel, não pelejeis contra o Senhor Deus de vossos pais; porque não sereis bem sucedidos.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 13, 'Jeroboão, porém, armou uma emboscada, para dar sobre Judá pela retaguarda; de maneira que as suas tropas estavam em frente de Judá e a emboscada por detrás.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 14, 'Então os de Judá olharam para trás, e eis que tinham de pelejar por diante e pela retaguarda; então clamaram ao Senhor, e os sacerdotes tocaram as trombetas.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 15, 'E os homens de Judá deram o brado de guerra; e sucedeu que, bradando eles, Deus feriu Jeroboão e todo o Israel diante de Abias e de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 16, 'E os filhos de Israel fugiram de diante de Judá, e Deus lhos entregou nas suas mãos.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 17, 'De maneira que Abias e o seu povo fizeram grande matança entre eles; pois que caíram mortos de Israel quinhentos mil homens escolhidos.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 18, 'Assim foram humilhados os filhos de Israel naquele tempo, e os filhos de Judá prevaleceram, porque confiaram no Senhor Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 19, 'E Abias foi perseguindo Jeroboão, e tomou-lhe cidades: Betel e seus arrabaldes, Jesana e seus arrabaldes, e Efrom e seus arrabaldes.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 20, 'Jeroboão não recobrou mais a sua força nos dias de Abias; e o Senhor o feriu, e ele morreu.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 21, 'Abias, porém, se fortaleceu, e tomou para si catorze mulheres, e teve vinte e dois filhos e dezesseis filhas.', 1, CURRENT_TIMESTAMP, false),
(14, 13, 22, 'O restante dos atos de Abias, os seus caminhos e as suas palavras, estão escritos no comentário do profeta Ido.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 1, 'Abias dormiu com seus pais, e o sepultaram na cidade de Davi. E Asa, seu filho, reinou em seu lugar; nos seus dias a terra esteve em paz por dez anos.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 2, 'E Asa fez o que era bom e reto aos olhos do Senhor seu Deus;', 1, CURRENT_TIMESTAMP, false),
(14, 14, 3, 'removeu os altares estranhos, e os altos, quebrou as colunas, cortou os aserins,', 1, CURRENT_TIMESTAMP, false),
(14, 14, 4, 'e mandou a Judá que buscasse ao Senhor, Deus de seus pais, e que observasse a lei e o mandamento.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 5, 'Também removeu de todas as cidades de Judá os altos e os altares de incenso; e sob ele o reino esteve em paz.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 6, 'Edificou cidades fortificadas em Judá; porque a terra estava em paz, e não havia guerra contra ele naqueles anos, porquanto o Senhor lhe dera repouso.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 7, 'Disse, pois, a Judá: Edifiquemos estas cidades, e cerquemo-las de muros e torres, portas e ferrolhos; a terra ainda é nossa porque buscamos ao Senhor nosso Deus; nós o buscamos, e ele nos deu repouso de todos os lados. Edificaram, pois, e prosperaram.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 8, 'Ora, tinha Asa um exército de trezentos mil homens de Judá, que traziam pavês e lança; e duzentos e oitenta mil de Benjamim, que traziam escudo e atiravam com arco; todos estes eram homens valentes.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 9, 'E Zerá, o etíope, saiu contra eles, com um exército de um milhão de homens, e trezentos carros, e chegou até Maressa.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 10, 'Então Asa saiu contra ele, e ordenaram a batalha no vale de Zefatá, junto a Maressa.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 11, 'E Asa clamou ao Senhor seu Deus, dizendo: Ó Senhor, nada para ti é ajudar, quer o poderoso quer o de nenhuma força. Acuda-nos, pois, o Senhor nosso Deus, porque em ti confiamos, e no teu nome viemos contra esta multidão. Ó Senhor, tu és nosso Deus, não prevaleça contra ti o homem.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 12, 'E o Senhor desbaratou os etíopes diante de Asa e diante de Judá; e os etíopes fugiram.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 13, 'Asa e o povo que estava com ele os perseguiram até Gerar; e caíram tantos dos etíopes que já não havia neles resistência alguma; porque foram quebrantados diante do Senhor, e diante do seu exército. Os homens de Judá levaram dali mui grande despojo.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 14, 'Feriram todas as cidades nos arredores de Gerar, porque veio sobre elas o terror da parte do Senhor; e saquearam todas as cidades, pois havia nelas muito despojo.', 1, CURRENT_TIMESTAMP, false),
(14, 14, 15, 'Também feriram as malhadas do gado, e levaram ovelhas em abundância, e camelos, e voltaram para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 1, 'Então veio o Espírito de Deus sobre Azarias, filho de Odede,', 1, CURRENT_TIMESTAMP, false),
(14, 15, 2, 'que saiu ao encontro de Asa e lhe disse: Ouvi-me, Asa, e todo o Judá e Benjamim: O Senhor está convosco, enquanto vós estais com ele; se o buscardes, o achareis; mas se o deixardes, ele vos deixará.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 3, 'Ora, por muito tempo Israel esteve sem o verdadeiro Deus, sem sacerdote que o ensinasse e sem lei.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 4, 'Quando, porém, na sua angústia voltaram para o Senhor, Deus de Israel, e o buscaram, o acharam.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 5, 'E naqueles tempos não havia paz nem para o que saia, nem para o que entrava, mas grandes perturbações estavam sobre todos os habitantes daquelas terras.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 6, 'Pois nação contra nação e cidade contra cidade se despedaçavam, porque Deus as conturbara com toda sorte de aflições.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 7, 'Vós, porém, esforçai-vos, e não desfaleçam as vossas mãos; porque a vossa obra terá uma recompensa.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 8, 'Asa, tendo ouvido estas palavras, e a profecia do profeta filho de Odede, cobrou ânimo e lançou fora as abominações de toda a terra de Judá e de Benjamim, como também das cidades que tomara na região montanhosa de Efraim, e renovou o altar do Senhor, que estava diante do pórtico do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 9, 'E congregou todo o Judá e Benjamim, e os de Efraim, Manassés e Simeão que com eles peregrinavam; pois que muitos e Israel tinham vindo a ele quando viram que o Senhor seu Deus era com ele.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 10, 'Ajuntaram-se em Jerusalém no terceiro mês, no décimo quinto ano do reinado de Asa.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 11, 'E no mesmo dia ofereceram em sacrifício ao Senhor, do despojo que trouxeram, setecentos bois e sete mil ovelhas.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 12, 'E entraram no pacto de buscarem ao Senhor, Deus de seus pais, de todo o seu coração e de toda a sua alma;', 1, CURRENT_TIMESTAMP, false),
(14, 15, 13, 'e de que todo aquele que não buscasse ao Senhor, Deus de Israel, fosse morto, tanto pequeno como grande, tanto homem como mulher.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 14, 'E prestaram juramento ao Senhor em alta voz, com júbilo, ao som de trombetas e buzinas.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 15, 'E todo o Judá se alegrou deste juramento; porque de todo o seu coração juraram, e de toda a sua vontade buscaram ao Senhor, e o acharam; e o Senhor lhes deu descanso ao redor.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 16, 'O rei Asa depôs Maacá, sua mãe, para que não fosse mais rainha, porquanto ela fizera um abominável ídolo para servir de Asera, ao qual Asa derrubou e, despedaçando-o, o queimou junto ao ribeiro de Cedrom.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 17, 'Os altos, porém, não se tiraram de Israel; contudo o coração de Asa foi perfeito todos os seus dias.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 18, 'E trouxe para a casa de Deus as coisas que seu pai tinha consagrado, e as que ele mesmo tinha consagrado: prata, ouro e utensílios.', 1, CURRENT_TIMESTAMP, false),
(14, 15, 19, 'E não mais houve guerra até o ano trigésimo quinto do reinado de Asa.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 1, 'No trigésimo sexto ano do reinado de Asa, Baasa, rei de Israel, subiu contra Judá e edificou a Ramá, para não deixar ninguém sair nem entrar para Asa, rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 2, 'Então Asa tirou a prata e o ouro dos tesouros da casa do Senhor, e da casa do rei, e enviou mensageiros a Ben-Hadade, rei da Síria, que habitava em Damasco, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 16, 3, 'Haja aliança entre mim e ti, como havia entre meu pai e o teu. Eis que te envio prata e ouro; vai, pois, e rompe a sua aliança com Baasa, rei de Israel, para que se retire de mim.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 4, 'E Ben-Hadade deu ouvidos ao rei Asa, e enviou os comandantes dos seus exércitos contra as cidades de Israel, os quais feriram Ijom, Dã, Abel-Maim e todas as cidades-armazéns de Naftali.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 5, 'E tendo Baasa notícia disto, cessou de edificar a Ramá, e não continuou a sua obra.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 6, 'Então o rei Asa tomou todo o Judá, e eles levaram as pedras de Ramá, e a sua madeira, com que Baasa edificara; e com elas edificou Geba e Mizpá.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 7, 'Naquele mesmo tempo veio Hanâni, o vidente, ter com Asa, rei de Judá, e lhe disse: Porque confiaste no rei da Síria, e não confiaste no Senhor teu Deus, por isso o exército do rei da Síria escapou da tua mão.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 8, 'Porventura não foram os etíopes e os líbios um grande exército, com muitíssimos carros e cavaleiros? Confiando tu, porém, no Senhor, ele os entregou nas mãos.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 9, 'Porque, quanto ao Senhor, seus olhos passam por toda a terra, para mostrar-se forte a favor daqueles cujo coração é perfeito para com ele; nisto procedeste loucamente, pois desde agora haverá guerras contra ti.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 10, 'Então Asa, indignado contra o vidente, lançou-o na casa do tronco, porque estava enfurecido contra ele por causa disto; também nesse mesmo tempo Asa oprimiu alguns do povo.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 11, 'Eis que os atos de Asa, desde os primeiros até os últimos, estão escritos no livro dos reis de Judá e de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 12, 'No ano trinta e nove do seu reinado Asa caiu doente dos pés; e era mui grave a sua enfermidade; e nem mesmo na enfermidade buscou ao Senhor, mas aos médicos.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 13, 'E Asa dormiu com seus pais, morrendo no ano quarenta e um do seu reinado.', 1, CURRENT_TIMESTAMP, false),
(14, 16, 14, 'E o sepultaram no sepulcro que tinha cavado para si na cidade de Davi, havendo-o deitado na cama, que se enchera de perfumes e de diversas especiarias preparadas segundo a arte dos perfumistas; e destas coisas fizeram-lhe uma grande queima.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 1, 'Jeosafá, seu filho, reinou em seu lugar, e fortaleceu-se contra Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 2, 'Pôs forças armadas em todas as cidades fortes de Judá e dispôs guarnições na terra de Judá, como também nas cidades de Efraim que Asa, seu pai, tinha tomado.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 3, 'E o Senhor era com Jeosafá, porque andou conforme os primeiros caminhos de Davi, seu pai, e não buscou aos baalins;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 4, 'antes buscou ao Deus de seu pai, e andou nos seus mandamentos, e não segundo as obras de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 5, 'Por isso o Senhor confirmou o reino na sua mão; e todo o Judá trouxe presentes a Jeosafá; e ele teve riquezas e glória em abundância.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 6, 'E encorajou-se o seu coração nos caminhos do Senhor; e ele tirou de Judá os altos e os aserins.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 7, 'No terceiro ano do seu reinado enviou ele os seus príncipes, Bene-Hail, Obadias, Zacarias, Netanel e Micaías, para ensinarem nas cidades de Judá;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 8, 'e com eles os levitas Semaías, Netanias, Zebadias, Asael, Semiramote, Jônatas, Adonias, Tobias e Tobadonias e, com estes levitas, os sacerdotes Elisama e Jeorão.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 9, 'E ensinaram em Judá, levando consigo o livro da lei do Senhor; foram por todas as cidades de Judá, ensinando entre o povo.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 10, 'Então caiu o temor do Senhor sobre todos os reinos das terras que estavam ao redor de Judá, de modo que não fizeram guerra contra Jeosafá.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 11, 'Alguns dentre os filisteus traziam presentes a Jeosafá, e prata como tributo; e os árabes lhe trouxeram rebanhos: sete mil e setecentos carneiros, e sete mil e setecentos bodes.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 12, 'Assim Jeosafá ia-se tornando cada vez mais poderoso; e edificou fortalezas e cidades-armazéns em Judá;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 13, 'e teve grande quantidade de munições nas cidades de Judá, e soldados, homens valorosos, em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 14, 'Este é o número deles segundo as suas casas paternas: de Judá os comandantes de mil: o comandante Adná, com trezentos mil homens valorosos;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 15, 'após ele o comandante Jeoanã com duzentos e oitenta mil;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 16, 'após ele Amasias, filho de Zicri, que voluntariamente se entregou ao Senhor, e com ele duzentos mil valorosos;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 17, 'e de Benjamim: Eliadá, homem destemido, com duzentos mil armados de arco e de escudo;', 1, CURRENT_TIMESTAMP, false),
(14, 17, 18, 'e após ele Jeozabade, com cento e oitenta mil armados para a guerra.', 1, CURRENT_TIMESTAMP, false),
(14, 17, 19, 'Estes estavam no serviço do rei, afora os que o rei tinha posto nas cidades fortes por todo o Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 1, 'Tinha, pois, Jeosafá riquezas e glória em abundância, e aparentou-se com Acabe.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 2, 'Ao cabo de alguns anos foi ter com Acabe em Samária. E Acabe matou ovelhas e bois em abundância, para ele e para o povo que o acompanhava; e o persuadiu a subir com ele a Ramote-Gileade.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 3, 'Perguntou Acabe, rei de Israel, a Jeosafá, rei de Judá: Irás tu comigo a Ramote-Gileade? E respondeu-lhe Jeosafá: Como tu és sou eu, e o meu povo como o teu povo; seremos contigo na guerra.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 4, 'Disse mais Jeosafá ao rei de Israel: Consulta hoje a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 5, 'Então o rei de Israel ajuntou os profetas, quatrocentos homens, e lhes perguntou: Iremos à peleja contra Ramote-Gileade, ou deixarei de ir? Responderam eles: Sobe, porque Deus a entregará nas mãos do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 6, 'Disse, porém, Jeosafá: Não há aqui ainda algum profeta do Senhor a quem possamos consultar?', 1, CURRENT_TIMESTAMP, false),
(14, 18, 7, 'Ao que o rei de Israel respondeu a Jeosafá: Ainda há um homem por quem podemos consultar ao Senhor; eu, porém, o odeio, porque nunca profetiza o bem a meu respeito, mas sempre o mal; é Micaías, filho de Inlá. Mas Jeosafá disse: Não fale o rei assim.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 8, 'Então o rei de Israel chamou um eunuco, e disse: Traze aqui depressa Micaías, filho de Inlá.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 9, 'Ora, o rei de Israel e Jeosafá, rei de Judá, vestidos de seus trajes reais, estavam assentados cada um no seu trono, na praça à entrada da porta de Samária; e todos os profetas profetizavam diante deles.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 10, 'E Zedequias, filho de Quenaaná, fez para si uns chifres de ferro, e disse: Assim diz o Senhor: Com estes ferirás os sírios, até que sejam consumidos.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 11, 'E todos os profetas profetizavam o mesmo, dizendo: Sobe a Ramote-Gileade, e serás bem sucedido, pois o Senhor a entregará nas mãos do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 12, 'O mensageiro que fora chamar Micaías lhe falou, dizendo: Eis que as palavras dos profetas, a uma voz, são favoráveis ao rei: seja, pois, também a tua palavra como a de um deles, e fala o que é bom.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 13, 'Micaías, porém, disse: Vive o Senhor, que o que meu Deus me disser, isso falarei.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 14, 'Quando ele chegou à presença do rei, este lhe disse: Micaías, iremos a Ramote-Gileade à peleja, ou deixarei de ir? Respondeu ele: Subi, e sereis bem sucedidos; e eles serão entregues nas vossas mãos.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 15, 'Mas o rei lhe disse: Quantas vezes hei de conjurar-te que não me fales senão a verdade em nome do Senhor?', 1, CURRENT_TIMESTAMP, false),
(14, 18, 16, 'Respondeu ele: Vi todo o Israel disperso pelos montes, como ovelhas que não têm pastor; e disse o Senhor: Estes não têm senhor; torne em paz cada um para sua casa.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 17, 'Então o rei de Israel disse a Jeosafá: Não te disse eu que ele não profetizaria a respeito de mim o bem, porém o mal?', 1, CURRENT_TIMESTAMP, false),
(14, 18, 18, 'Prosseguiu Micaías: Ouvi, pois, a palavra do Senhor! Vi o Senhor assentado no seu trono, e todo o exército celestial em pé à sua direita e à sua esquerda.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 19, 'E o Senhor perguntou: Quem induzirá Acabe, rei de Israel, a subir, para que caia em Ramote-Gileade? E um respondia de um modo, e outro de outro.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 20, 'Então saiu um espírito, apresentou-se diante do Senhor, e disse: Eu o induzirei. Perguntou-lhe o Senhor: De que modo?', 1, CURRENT_TIMESTAMP, false),
(14, 18, 21, 'E ele disse: Eu sairei, e serei um espírito mentiroso na boca de todos os seus profetas. Ao que disse o Senhor. Tu o induzirás, e prevalecerás; sai, e faze assim.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 22, 'Agora, pois, eis que o Senhor pôs um espírito mentiroso na boca destes teus profetas; o Senhor é quem falou o mal a respeito de ti.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 23, 'Então Zedequias, filho de Quenaaná, chegando-se, feriu a Micaías na face e disse: Por que caminho passou de mim o Espírito do Senhor para falar a ti?', 1, CURRENT_TIMESTAMP, false),
(14, 18, 24, 'Respondeu Micaías: Eis que tu o verás naquele dia, quando entrares numa câmara interior para te esconderes.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 25, 'Então disse o rei de Israel: Tomai Micaías, e tornai a levá-lo a Amom, o governador da cidade, e a Joás, filho do rei,', 1, CURRENT_TIMESTAMP, false),
(14, 18, 26, 'dizendo-lhes: Assim diz o rei: Metei este homem no cárcere, e sustentai-o a pão e água até que eu volte em paz.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 27, 'Mas disse Micaías: se tu voltares em paz, o Senhor não tem falado por mim. Disse mais: Ouvi, povos todos!', 1, CURRENT_TIMESTAMP, false),
(14, 18, 28, 'Subiram, pois, o rei de Israel e Jeosafá, rei de Judá, a Ramote-Gileade.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 29, 'E disse o rei de Israel a Jeosafá: Eu me disfarçarei, e entrarei na peleja; tu, porém, veste os teus trajes reais. Disfarçou-se, pois, o rei de Israel, e eles entraram na peleja.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 30, 'Ora, o rei da Síria dera ordens aos capitães dos seus carros, dizendo: Não pelejareis nem contra pequeno nem contra grande, senão só contra o rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 31, 'Pelo que os capitães dos carros, quando viram a Jeosafá, disseram: Este é o rei de Israel. Viraram-se, pois, para pelejar contra ele; mas Jeosafá clamou, e o Senhor o socorreu, e os desviou dele.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 32, 'Pois vendo os capitães dos carros que não era o rei de Israel, deixaram de segui-lo.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 33, 'Então um homem entesou e seu arco e, atirando a esmo, feriu o rei de Israel por entre a couraça e a armadura abdominal. Pelo que ele disse ao carreteiro: Dá volta, e tira-me do exército, porque estou gravemente ferido.', 1, CURRENT_TIMESTAMP, false),
(14, 18, 34, 'E a peleja tornou-se renhida naquele dia; contudo o rei de Israel foi sustentado no carro contra os sírios até a tarde; porém ao pôr do sol morreu.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 1, 'Jeosafá, rei de Judá, voltou em paz à sua casa em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 2, 'Mas Jeú, filho de Hanâni, a vidente, saiu ao encontro do rei Jeosafá e lhe disse: Devias tu ajudar o ímpio, e amar aqueles que odeiam ao Senhor? Por isso virá sobre ti grande ira da parte do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 3, 'Contudo, alguma virtude se acha em ti, porque tiraste para fora da terra as aserotes, e dispuseste o teu coração para buscar a Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 4, 'Habitou, pois, Jeosafá em Jerusalém; e tornou a passar pelo povo desde Berseba até a região montanhosa de Efraim, fazendo com que voltasse ao Senhor Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 5, 'Estabeleceu juízes na terra, em todas as cidades fortes de Judá, de cidade em cidade;', 1, CURRENT_TIMESTAMP, false),
(14, 19, 6, 'e disse aos juízes: Vede o que fazeis; porque não julgais da parte do homem, mas da parte do Senhor, e ele está convosco no julgamento.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 7, 'Agora, pois, seja o temor do Senhor convosco; tomai cuidado no que fazeis; porque não há no Senhor nosso Deus iniqüidade, nem acepção de pessoas, nem aceitação de presentes.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 8, 'Também em Jerusalém estabeleceu Jeosafá alguns dos levitas e dos sacerdotes e dos chefes das casas paternas de Israel sobre e juízo da parte do Senhor, e sobre as causas civis. E voltaram para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 9, 'E deu-lhes ordem, dizendo: Assim procedei no temor do Senhor, com fidelidade e com coração perfeito.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 10, 'Todas as vezes que se vos submeter qualquer controvérsia da parte de vossos irmãos que habitam nas suas cidades, entre sangue e sangue, entre lei e mandamento, entre estatutos e juízos, admoestai-os a que se não façam culpados para com o Senhor, e deste modo venha grande ira sobre vós e sobre vossos irmãos. Procedei assim, e não vos fareis culpados.', 1, CURRENT_TIMESTAMP, false),
(14, 19, 11, 'E eis que Amarias, o sumo sacerdote, presidirá sobre vós em todos os negócios do Senhor; e Zebadias, filho de Ismael, príncipe da casa de Judá, em todos os negócios do rei; também os levitas serão oficiais perante vós. Procedei corajosamente e seja o Senhor com os retos.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 1, 'Depois disto sucedeu que os moabitas, e os amonitas, e com eles alguns dos meunitas vieram contra Jeosafá para lhe fazerem guerra.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 2, 'Vieram alguns homens dar notícia a Jeosafá, dizendo: Vem contra ti uma grande multidão de Edom, dalém do mar; e eis que já estão em Hazazom-Tamar, que é En-Gedi.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 3, 'Então Jeosafá teve medo, e pôs-se a buscar ao Senhor, e apregoou jejum em todo o Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 4, 'E Judá se ajuntou para pedir socorro ao Senhor; de todas as cidades de Judá vieram para buscarem ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 5, 'Jeosafá pôs-se em pé na congregação de Judá e de Jerusalém, na casa do Senhor, diante do átrio novo,', 1, CURRENT_TIMESTAMP, false),
(14, 20, 6, 'e disse: Ó Senhor, Deus de nossos pais, não és tu Deus no céu? e não és tu que governas sobre todos os reinos das nações? e na tua mão há poder e força, de modo que não há quem te possa resistir.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 7, 'Ó nosso Deus, não lançaste fora os moradores desta terra de diante do teu povo Israel, e não a deste para sempre à descendência de Abraão, teu amigo?', 1, CURRENT_TIMESTAMP, false),
(14, 20, 8, 'E habitaram nela, e nela edificaram um santuário ao teu nome, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 20, 9, 'Se algum mal nos sobrevier, espada, juízo, peste, ou fome, nós nos apresentaremos diante desta casa e diante de ti, pois teu nome está nesta casa, e clamaremos a ti em nossa aflição, e tu nos ouvirás e livrarás.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 10, 'Agora, pois, eis que os homens de Amom, de Moabe, e do monte Seir, pelos quais não permitiste que passassem os filhos de Israel, quando vinham da terra do Egito, mas deles se desviaram e não os destruíram.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 11, 'eis como nos recompensam, vindo para lançar-nos fora da tua herança, que nos fizeste herdar.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 12, 'Ó nosso Deus, não os julgarás? Porque nós não temos força para resistirmos a esta grande multidão que vem contra nós, nem sabemos o que havemos de fazer; porém os nossos olhos estão postos em ti.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 13, 'E todo o Judá estava em pé diante do Senhor, como também os seus pequeninos, as suas mulheres, e os seus filhos.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 14, 'Então veio o Espírito do Senhor no meio da congregação, sobre Jaaziel, filho de Zacarias, filho de Benaías, filho de Jeiel, filho de Matanias o levita, dos filhos de Asafe,', 1, CURRENT_TIMESTAMP, false),
(14, 20, 15, 'e disse: Dai ouvidos todo o Judá, e vós, moradores de Jerusalém, e tu, ó rei Jeosafá. Assim vos diz o Senhor: Não temais, nem vos assusteis por causa desta grande multidão, porque a peleja não é vossa, mas de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 16, 'Amanhã descereis contra eles; eis que sobem pela ladeira de Ziz, e os achareis na extremidade do vale, defronte do deserto de Jeruel.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 17, 'Nesta batalha não tereis que pelejar; postai-vos, ficai parados e vede o livramento que o Senhor vos concederá, ó Judá e Jerusalém. Não temais, nem vos assusteis; amanhã saí-lhes ao encontro, porque o Senhor está convosco.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 18, 'Então Jeosafá se prostrou com o rosto em terra; e todo o Judá e os moradores de Jerusalém se lançaram perante o Senhor, para o adorarem.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 19, 'E levantaram-se os levitas dos filhos dos coatitas e dos filhos dos coraítas, para louvarem ao Senhor Deus de Israel, em alta voz.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 20, 'Pela manhã cedo se levantaram saíram ao deserto de Tecoa; ao saírem, Jeosafá pôs-se em pé e disse: Ouvi-me, ó Judá, e vós, moradores de Jerusalém. Crede no Senhor vosso Deus, e estareis seguros; crede nos seus profetas, e sereis bem sucedidos.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 21, 'Tendo ele tomado conselho com o povo, designou os que haviam de cantar ao Senhor e louvá-lo vestidos de trajes santos, ao saírem diante do exército, e dizer: Dai graças ao Senhor, porque a sua benignidade dura para sempre.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 22, 'Ora, quando começaram a cantar e a dar louvores, o Senhor pôs emboscadas contra os homens de Amom, de Moabe e do monte Seir, que tinham vindo contra Judá; e foram desbaratados.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 23, 'Pois os homens de Amom e de Moabe se levantaram contra os moradores do monte Seir, para os destruir e exterminar; e, acabando eles com os moradores do monte Seir, ajudaram a destruir-se uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 24, 'Nisso chegou Judá à atalaia do deserto; e olharam para a multidão, e eis que eram cadáveres que jaziam por terra, não havendo ninguém escapado.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 25, 'Quando Jeosafá e o seu povo vieram para saquear os seus despojos, acharam entre eles gado em grande número, objetos de valor e roupas, assim como jóias preciosas, e tomaram para si tanto que não podiam levar mais; por três dias saquearam o despojo, porque era muito.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 26, 'Ao quarto dia eles se ajuntaram no vale de Beraca; pois ali louvaram ao Senhor. Por isso aquele lugar é chamado o vale de Beraca, até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 27, 'Então, voltando dali todos os homens de Judá e de Jerusalém com Jeosafá à frente deles, retornaram a Jerusalém com alegria; porque o Senhor os fizera regozijar-se, sobre os seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 28, 'Vieram, pois, a Jerusalém com alaúdes, com harpas e com trombetas, para a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 29, 'Então veio o temor de Deus sobre todos os reinos daqueles países, quando eles ouviram que o Senhor havia pelejado contra os inimigos de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 30, 'Assim o reino de Jeosafá ficou em paz; pois que o seu Deus lhe deu repouso ao redor.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 31, 'E Jeosafá reinou sobre Judá; era da idade de trinta e cinco anos quando começou a reinar, e reinou vinte e cinco anos em Jerusalém. E o nome de sua mãe era Azuba, filha de Sili.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 32, 'Ele andou no caminho de Asa, seu pai, e não se desviou dele, fazendo o que era reto aos olhos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 33, 'Contudo os altos não foram tirados; nem tinha o povo ainda disposto o seu coração para o Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 34, 'Ora, o restante dos atos de Jeosafá, desde os primeiros até os últimos, eis que está escrito nas crônicas de Jeú, filho de Hanâni, que estão inseridas no livro dos reis de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 35, 'Depois disto Jeosafá, rei de Judá, se aliou com Acazias, rei de Israel, que procedeu impiamente;', 1, CURRENT_TIMESTAMP, false),
(14, 20, 36, 'aliou-se com ele para construírem navios que fossem a Társis; e construíram os navios em Eziom-Geber.', 1, CURRENT_TIMESTAMP, false),
(14, 20, 37, 'Então Eliézer, filho de Dodavaú, de Maressa, profetizou contra Jeosafá, dizendo: Porquanto te aliaste com Acazias, o Senhor destruiu as tuas obras. E os navios se despedaçaram e não puderam ir a Társis.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 1, 'Depois Jeosafá dormiu com seus pais, e com eles foi sepultado na cidade de Davi. E Jeorão, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 2, 'E tinha irmãos, filhos de Jeosafá: Azarias, Jeiel, Zacarias, Asarias, Micael e Sefatias; todos estes foram filhos de Jeosafá, rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 3, 'Seu pai lhes dera grandes dádivas, em prata, em ouro e em objetos preciosos, juntamente com cidades fortes em Judá; mas o reino deu a Jeorão, porque ele era o primogênito.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 4, 'Ora, tendo Jeorão subido ao reino de seu pai, e havendo-se fortificado, matou todos os seus irmãos à espada, como também alguns dos príncipes de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 5, 'Jeorão tinha trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 6, 'E andou no caminho dos reis de Israel, como faz Acabe, porque tinha a filha de Acabe por mulher; e fazia o que parecia mal aos olhos do senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 7, 'Contudo o Senhor não quis destruir a casa de Davi, em atenção ao pacto que tinha feito com ele, e porque tinha dito que lhe daria por todos os dias uma lâmpada, a ele e a seus filhos.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 8, 'Nos dias de Jeorão os edomeus se revoltaram contra o domínio de Judá, e constituíram para si um rei.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 9, 'Pelo que Jeorão passou adiante com os seus chefes e com todos os seus carros; e, levantando-se de noite, desbaratou os edomeus, que tinham cercado a ele e aos capitães dos carros.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 10, 'Todavia os edomeus ficaram revoltados contra o domínio de Judá até o dia de hoje. Nesse mesmo tempo Libna também se revoltou contra o seu domínio, porque ele deixara ao Senhor, Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 11, 'Ele fez também altos nos montes de Judá, induziu os habitantes de Jerusalém à idolatria e impeliu Judá a prevaricar.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 12, 'Então lhe veio uma carta da parte de Elias, o profeta, que dizia: Assim diz o Senhor, Deus de Davi teu pai: Porquanto não andaste nos caminhos de Jeosafá, teu pai, e nos caminhos de Asa, rei de Judá;', 1, CURRENT_TIMESTAMP, false),
(14, 21, 13, 'mas andaste no caminho dos reis de Israel e induziste Judá e os habitantes de Jerusalém a idolatria semelhante à idolatria da casa de Acabe, e também mataste teus irmãos, da casa de teu pai, os quais eram melhores do que tu;', 1, CURRENT_TIMESTAMP, false),
(14, 21, 14, 'eis que o Senhor ferirá com uma grande praga o teu povo, os teus filhos, as tuas mulheres e toda a tua fazenda;', 1, CURRENT_TIMESTAMP, false),
(14, 21, 15, 'e tu terás uma grave enfermidade; a saber, um mal nas tuas entranhas, ate que elas saiam, de dia em dia, por causa do mal.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 16, 'E o Senhor despertou contra Jeorão o espírito dos filisteus e dos árabes que estão da banda dos etíopes.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 17, 'Estes subiram a Judá e, dando sobre ela, levaram toda a fazenda que se achou na casa do rei, como também seus filhos e suas mulheres; de modo que não lhe ficou filho algum, senão Jeoacaz, o mais moço de seus filhos.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 18, 'E depois de tudo isso o Senhor o feriu nas suas entranhas com uma enfermidade incurável.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 19, 'No decorrer do tempo, ao fim de dois anos, saíram-lhe as entranhas por causa da doença, e morreu desta horrível enfermidade. E o seu povo não lhe queimou aromas como queimara a seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 21, 20, 'Tinha trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém. Morreu sem deixar de si saudades; e o sepultaram na cidade de Davi, porém não nos sepulcros dos reis.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 1, 'Então os habitantes de Jerusalém fizeram reinar em seu lugar Acazias, seu filho mais moço, porque a tropa que viera com os árabes ao arraial tinha matado todos os mais velhos. Assim reinou Acazias, filho de Jeorão, rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 2, 'Tinha quarenta e dois anos quando começou a reinar, e reinou um ano em Jerusalém. E o nome de sua mãe era Atalia, filha de Onri.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 3, 'Ele também andou nos caminhos da casa de Acabe, porque sua mãe era sua conselheira para proceder impiamente.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 4, 'E fez o que era mau aos olhos do Senhor, como fez a casa de Acabe; porque eles eram seus conselheiros depois da morte de seu pai, para sua perdição.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 5, 'Andando nos conselhos deles foi com Jorão, filho de Acabe, rei de Israel, a guerrear contra Hazael, rei da Síria, junto a Ramote-Gileade; e os sírios feriram Jorão,', 1, CURRENT_TIMESTAMP, false),
(14, 22, 6, 'o qual voltou para curar-se em Jizreel das feridas que lhe fizeram em Ramá, quando ele pelejava contra Hazael, rei da Síria. E Acazias, filho de Jeorão, rei de Judá, desceu para visitar Jorão, filho de Acabe, em Jizreel, por estar ele doente.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 7, 'Foi por vontade de Deus que Acazias, para sua ruína visitou Jorão; pois, quando chegou, saiu com Jorão contra Jeú, filho de Ninsi, a quem o Senhor tinha ungido para exterminar a casa de Acabe.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 8, 'E quando Jeú executava juízo contra a casa de Acabe, achou os príncipes de Judá e os filhos dos irmãos de Acazias, que o serviam, e os matou.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 9, 'Depois buscou a Acazias, o qual foi preso quando se escondia em Samária, trouxeram-no a Jeú e o mataram. Então o sepultaram, pois disseram: É filho de Jeosafá, que buscou ao Senhor de toda o seu coração. E já não tinha a casa de Acazias ninguém que fosse capaz de reinar.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 10, 'Vendo Atalia, mãe de Acazias, que seu filho era morto, levantou-se e destruiu toda a estirpe real da casa de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 11, 'Mas Jeosabeate, filha do rei, tomou Joás, filho de Acazias, e o furtou dentre os filhos do rei, que estavam para ser mortos, e o pôs com a sua ama na câmara dos leitos. Assim Jeosabeate, filha do rei Jeorão, mulher do sacerdote Jeoiada e irmã de Acazias, o escondeu de Atalia, de modo que ela não o matou.', 1, CURRENT_TIMESTAMP, false),
(14, 22, 12, 'E esteve com eles seis anos, escondido na casa de Deus; e Atalia reinou sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 1, 'Ora, no sétimo ano Jeoiada, cobrando ânimo, tomou consigo em aliança os capitães de cem, Azarias, filho de Jeroão, Ismael, filho de Jeoanã, Azarias, filho de Obede, Maaséias, filho de Adaías, e Elisafaté, filho de Zicri.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 2, 'Estes percorreram a Judá, ajuntando os levitas de todas as cidades de Judá e os chefes das casas paternas de Israel; e vieram para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 3, 'E toda aquela congregação fez aliança com o rei na casa de Deus. E Jeoiada lhes disse: Eis que reinará o filho do rei, como o Senhor falou a respeito dos filhos de Davi.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 4, 'Isto é o que haveis de fazer: uma terça parte de vós, isto é, dos sacerdotes e dos levitas que entram no sábado, servirá de porteiros às entradas;', 1, CURRENT_TIMESTAMP, false),
(14, 23, 5, 'outra terça parte estará junto à casa do rei; e a outra terça parte à porta do Fundamento; e todo o povo estará nos átrios da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 6, 'Não entre, porém, ninguém na casa da Senhor, senão os sacerdotes e os levitas que ministram; estes entrarão, porque são santos; mas todo o povo guardará a ordenança do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 7, 'E os levitas cercarão o rei de todos os lados, cada um com as suas armas na mão; e qualquer que entrar na casa seja morto; mas acompanhai vós o rei, quando entrar e quando sair.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 8, 'Fizeram, pois, os levitas e todo o Judá conforme tudo o que ordenara e sacerdote Jeoiada; e tomou cada um os seus homens, tanto os que haviam de entrar no sábado como os que haviam de sair, pois o sacerdote Jeoiada não despediu as turmas.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 9, 'Também o sacerdote Jeoiada deu aos capitães de cem as lanças, os paveses e os escudos que tinham pertencido ao rei Davi, os quais estavam na casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 10, 'E dispôs todo o povo, cada um com as suas armas na mão, desde o lado direito até o lado esquerdo da casa, por entre o altar e a casa, ao redor do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 11, 'Então tiraram para fora o filho do rei e, pondo-lhe a coroa e o testemunho, o fizeram rei; e Jeoiada e seus filhos o ungiram, e disseram: Viva o rei!', 1, CURRENT_TIMESTAMP, false),
(14, 23, 12, 'Ouvindo, pois, Atalia a voz de povo que corria e louvava ao rei, veio ao povo na casa do Senhor;', 1, CURRENT_TIMESTAMP, false),
(14, 23, 13, 'e quando olhou, eis que o rei estava junto à sua coluna, à entrada, e os capitães e os trombeteiros perto do rei; e todo o povo da terra se alegrava, e tocava trombetas; e também os cantores tocavam instrumentos musicais, e dirigiam os cânticos de louvor. Então Atalia, rasgando os seus vestidos, clamou: Traição! Traição!', 1, CURRENT_TIMESTAMP, false),
(14, 23, 14, 'Nisso o sacerdote Jeoiada trouxe para fora os centuriões que estavam sobre o exército e disse-lhes: Trazei-a por entre as fileiras, e o que a seguir seja morto à espada. Pois o sacerdote dissera: Não a mateis na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 15, 'Então deitaram as mãos nela; e ela foi até a entrada da porta dos cavalos, que dá para a casa do rei, e ali a mataram.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 16, 'E Jeoiada firmou um pacto entre si e o povo todo e o rei, pelo qual seriam o povo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 17, 'Depois todo o povo entrou na casa de Baal, e a derrubaram; quebraram os seus altares e as suas imagens, e a Matã, sacerdote de Baal, mataram diante dos altares.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 18, 'E Jeoiada dispôs guardas na casa do Senhor, sob a direção dos sacerdotes levíticos a quem Davi designara na casa do Senhor para oferecerem com alegria e com cânticos os holocaustos do Senhor, como está escrito na lei de Moisés, e segundo a ordem de Davi.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 19, 'Colocou porteiros às portas da casa do Senhor, para que não entrasse nela ninguém imundo no tocante a coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 20, 'E tomou os centuriões, os nobres, os governadores do povo e todo o povo da terra; e conduziram da casa do Senhor o rei e, passando pela porta superior para a casa do rei, fizeram-no sentar no trono real.', 1, CURRENT_TIMESTAMP, false),
(14, 23, 21, 'Assim todo o povo da terra se alegrou, e a cidade ficou em paz, depois que mataram Atalia à espada.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 1, 'Tinha Joás sete anos quando começou a reinar, e reinou quarenta anos em Jerusalém. O nome de sua mãe era Zíbia, de Berseba.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 2, 'E Joás fez o que era reto aos olhos do Senhor por todos os dias do sacerdote Jeoiada.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 3, 'E tomou Jeoiada para ele duas mulheres, das quais teve filhos e filhas.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 4, 'Depois disso Joás resolveu renovar a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 5, 'Reuniu, pois, os sacerdotes e os levitas e lhes disse: Saí pelas cidades de Judá, e levantai dinheiro de todo a Israel, anualmente, para reparar a casa do vosso Deus; e vede que apresseis este negócio: contudo os levitas não o apressaram.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 6, 'Pelo que o rei chamou Jeoiada, o chefe, e lhe perguntou: Por que não tens obrigado os levitas a trazerem de Judá e de Jerusalém o imposto ordenado por Moisés, servo do Senhor, à congregação de Israel, para a tenda do testemunho?', 1, CURRENT_TIMESTAMP, false),
(14, 24, 7, 'Pois os filhos de Atalia, aquela mulher ímpia, tinham arruinado a casa de Deus; e até empregaram todas as coisas sagradas da casa do Senhor no serviço dos baalins.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 8, 'O rei, pois, deu ordem; e fizeram uma arca, e a puseram do lado de fora, à porta da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 9, 'E publicou-se em Judá e em Jerusalém que trouxessem ao Senhor o imposto que Moisés, o servo de Deus, havia ordenado a Israel no deserto.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 10, 'Então todos os príncipes e todo o povo se alegraram, e trouxeram o imposto e o lançaram na arca, até que ficou cheia.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 11, 'E quando era trazida a arca pelas mãos dos levitas ao recinto do rei, na ocasião em que viam que havia muito dinheiro, vinham o escrivão do rei e o deputado do sumo sacerdote, esvaziavam a arca e, tomando-a, tornavam a levá-la ao seu lugar. Assim faziam dia após dia, e ajuntaram dinheiro em abundância.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 12, 'E o rei e Jeoiada davam-no aos encarregados da obra da casa do Senhor; e assalariaram pedreiros e carpinteiros para renovarem a casa do Senhor, como também os que trabalhavam em ferro e em bronze para repararem a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 13, 'Assim os encarregados da obra faziam com que o serviço da reparação progredisse nas suas mãos; e restituíram a casa de Deus a seu estado anterior, e a consolidaram.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 14, 'Depois de acabarem a obra trouxeram ao rei e a Jeoiada o resto do dinheiro, e dele se fizeram utensílios para a casa do Senhor, para serem usados no ministério e nos holocaustos, e colheres, e vasos de ouro e de prata. E se ofereciam holocaustos continuamente na casa do Senhor, por todos os dias de Jeoiada.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 15, 'Jeoiada, porém, envelheceu e, cheio de dias, morreu; tinha cento e trinta anos quando morreu.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 16, 'E o sepultaram na cidade de Davi com os reis, porque tinha feito o bem em Israel, e para com Deus e sua casa.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 17, 'E depois da morte de Jeoiada vieram os príncipes de Judá e prostraram-se diante do rei; então o rei lhes deu ouvidos.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 18, 'E eles, abandonando a casa do Senhor, Deus de seus pais, serviram aos aserins e aos ídolos; de sorte que veio grande ira sobre Judá e Jerusalém por causa desta sua culpa.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 19, 'Contudo Deus enviou profetas entre eles para os fazer tornar ao Senhor, os quais protestaram contra eles; mas eles não lhes deram ouvidos.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 20, 'E o Espírito de Deus apoderou-se de Zacarias, filho do sacerdote Jeoiada, o qual se pôs em pé acima do povo, e lhes disse: Assim diz Deus: Por que transgredis os mandamentos do Senhor, de modo que não possais prosperar? Porquanto abandonastes o Senhor, também ele vos abandonou.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 21, 'Mas conspiraram contra ele e por ordem do rei, o apedrejaram no átrio da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 22, 'Assim o rei Joás não se lembrou da bondade que lhe fizera Jeoiada pai de Zacarias, antes matou-lhe o filho, o qual morrendo disse: Veja-o o Senhor, e o retribua.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 23, 'Decorrido um ano, o exército da Síria subiu contra Joás; e vieram a Judá e a Jerusalém, e destruíram dentre o povo todos os seus príncipes, e enviaram todo o seu despojo ao rei de Damasco.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 24, 'O exército dos sírios viera com poucos homens, contudo o Senhor entregou nas suas mãos um exército mui grande, porquanto abandonaram o Senhor, Deus de seus pais. Assim executaram juízo contra Joás.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 25, 'Quando os sírios se retiraram dele, deixaram-no gravemente ferido; então seus servos conspiraram contra ele por causa do sangue dos filhos do sacerdote Jeoiada, e o mataram na sua cama, e assim morreu; e o sepultaram na cidade de Davi, porém não nos sepulcros dos reis.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 26, 'Estes foram os que conspiraram contra ele Zabade, filho de Simeate a amonita, e Jeozabade, filho de Sinrite a moabita.', 1, CURRENT_TIMESTAMP, false),
(14, 24, 27, 'Ora, quanto a seus filhos, e ao grande número de oráculos pronunciados contra ele, e à restauração da casa de Deus, eis que estão escritos no comentário do livro dos reis. E Amazias, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 1, 'Amazias tinha vinte e cinco anos quando começou a reinar, e reinou vinte e nove anos em Jerusalém. E o nome de sua mãe era Jeoadã, de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 2, 'Ele fez o que era reto aos olhos do Senhor, mas não o fez com coração perfeito.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 3, 'Quando o reino já lhe tinha sido confirmado, ele matou os seus servos que tinham assassinado o rei seu pai.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 4, 'Contudo não matou os filhos deles mas fez segundo está escrito na lei: no livro de Moisés, como o Senhor ordenou, dizendo: Não morrerão os pais pelos filhos nem os filhos pelos pais; mas cada um morrerá pelo seu pecado.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 5, 'Depois Amazias congregou Judá e o colocou, segundo as suas casas paternas sob comandantes de milhares e de centenas, por todo o Judá e Benjamim; e os contou de vinte anos para cima, e achou deles trezentos mil escolhidos que podiam ir à guerra e sabiam manejar lança e escudo.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 6, 'Também de Israel tomou a soldo cem mil varões valentes, por cem talentos de prata.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 7, 'Veio ter com ele, porém, um homem de Deus, dizendo: Ó rei, não deixes ir contigo o exército de Israel, porque o Senhor não é com Israel, a saber, com todos os filhos de Efraim.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 8, 'Mas se julgas que assim serás forte para a peleja, Deus te fará cair diante do inimigo; pois Deus tem poder para ajudar e para fazer cair.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 9, 'Então perguntou Amazias ao homem de Deus: Mas que se fará dos cem talentos de prata que dei às tropas de Israel? Respondeu o homem de Deus: Mais tem o Senhor que te dar do que isso.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 10, 'Então Amazias separou as tropas que lhe tinham vindo de Efraim, para que voltassem para a sua terra; pelo que muito se acendeu a ira deles contra Judá, e voltaram para a sua terra ardendo em ira.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 11, 'Amazias, cobrando ânimo, conduziu o seu povo, e foi ao Vale do Sal, onde matou dez mil dos filhos de Seir.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 12, 'Os filhos de Judá prenderam vivos outros dez mil, e trazendo-os ao cume da rocha, lançaram-nos dali abaixo, de modo que todos foram despedaçados.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 13, 'Mas os homens das tropas que Amazias despedira, não deixando que fossem com ele à batalha, deram sobre as cidades de Judá, desde Samária até Bete-Horom, e dos seus habitantes mataram três mil, e saquearam grande despojo.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 14, 'Quando Amazias veio da matança dos edomeus, trouxe consigo os deuses dos filhos de Seir e os elevou para serem os seus deuses, prostrando-se diante deles e queimando-lhes incenso.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 15, 'Pelo que o Senhor se irou contra Amazias e lhe enviou um profeta, que lhe disse: Por que buscaste os deuses deste povo, os quais não livraram o seu próprio povo da tua mão?', 1, CURRENT_TIMESTAMP, false),
(14, 25, 16, 'Enquanto ele ainda falava com o rei, este lhe respondeu: Fizemos-te conselheiro do rei? Cala-te! Por que haverias de ser morto? Então o profeta calou, havendo dito: Sei que Deus resolveu destruir-te, porquanto fizeste isto, e não deste ouvidos a meu conselho.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 17, 'Tendo Amazias, rei de Judá, tomado conselho, mandou dizer a Jeoás, filho de Jeoacaz, filho de Jeú, rei de Israel: Vem, vejamo-nos face a face.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 18, 'Mas Jeoás, rei de Israel, mandou responder a Amazias, rei de Judá: O cardo que estava no Líbano mandou dizer ao cedro que estava no Líbano: Dá tua filha por mulher a meu filho. Mas uma fera que estava no Líbano passou e pisou o cardo.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 19, 'Tu dizes a ti mesmo: Eis que feri Edom. Assim o teu coração se eleva para te gloriares. Agora, pois, fica em tua casa; por que te meterias no mal, para caíres tu e Judá contigo?', 1, CURRENT_TIMESTAMP, false),
(14, 25, 20, 'Amazias, porém, não lhe deu ouvidos; pois isto vinha de Deus, para entregá-los na mão dos seus inimigos, porque buscaram os deuses de Edom.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 21, 'Subiu, pois, Jeoás, rei de Israel; e ele e Amazias, rei de Judá, se viram face a face em Bete-Semes, que pertence a Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 22, 'E Judá foi desbaratado diante de Israel, e fugiu cada um para a sua tenda.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 23, 'E Jeoás, rei de Israel, prendeu Amazias, rei de Judá, filho de Joás, o filho de Jeoacaz, em Bete-Semes, e o levou a Jerusalém; e derrubou o muro de Jerusalém, desde a porta de Efraim até a porta da esquina, quatrocentos côvados.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 24, 'Também tomou todo o ouro, e toda a prata, e todos os utensílios que se acharam na casa de Deus com Obede-Edom, e os tesouros da casa do rei, e os reféns, e voltou pura Samária.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 25, 'E Amazias, filho de Joás, rei de Judá, viveu quinze anos depois da morte de Jeoás, filho de Jeoacaz, rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 26, 'Quanto ao restante dos atos de Amazias, desde os primeiros até os últimos, não estão porventura escritos no livro dos reis de Judá e de Israel?', 1, CURRENT_TIMESTAMP, false),
(14, 25, 27, 'Desde o tempo em que Amazias se desviou do Senhor, conspiraram contra ele em Jerusalém, e ele fugiu para Laquis; mas perseguiram-no até Laquis, e ali o mataram.', 1, CURRENT_TIMESTAMP, false),
(14, 25, 28, 'E o trouxeram sobre cavalos e o sepultaram junto a seus pais na cidade de Davi.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 1, 'Então todo o povo de Judá tomou a Uzias, que tinha dezesseis anos, e o fizeram rei em lugar de seu pai Amazias.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 2, 'Ele edificou Elote, e a restituiu a Judá, depois que o rei dormiu com seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 3, 'Tinha Uzias dezesseis anos quando começou a reinar, e reinou cinqüenta e dois anos em Jerusalém. E o nome de sua mãe era Jecolia, de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 4, 'Ele fez o que era reto aos olhos do Senhor, conforme tudo o que fizera Amazias seu pai.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 5, 'E buscou a Deus enquanto viveu Zacarias, que o instruiu no temor de Deus; e enquanto buscou ao Senhor, Deus o fez prosperar.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 6, 'Saiu e guerreou contra os filisteus, e derrubou o muro de Gate, o muro de Jabné e o muro de Asdode; e edificou cidades no país de Asdode e entre os filisteus;', 1, CURRENT_TIMESTAMP, false),
(14, 26, 7, 'porque Deus, o ajudou contra os filisteus e contra os árabes que habitavam em Gur-Baal, e contra os meunitas.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 8, 'Os amonitas pagaram tributo a Uzias; e a sua fama se espalhou até a entrada do Egito, pois se tornou muito poderoso.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 9, 'Também Uzias edificou torres em Jerusalém, à porta da esquina, à porta do vale e ao ângulo do muro, e as fortificou.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 10, 'Edificou torres no deserto, e cavou muitos poços, porque tinha muito gado tanto nos vales como nas campinas; e tinha lavradores e vinhateiros nos montes e nos campos férteis, pois era amigo da agricultura.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 11, 'Tinha também Uzias um exército de homens destros nas armas, que saíam à guerra em tropas, segundo o número da sua resenha feita pelo escrivão Jeiel e o oficial Maaséias, sob as ordens de Hananias, um dos príncipes do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 12, 'O número total dos chefes das casas paternas, homens valorosos, era de dois mil e seiscentos.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 13, 'E sob as suas ordens havia um exército disciplinado de trezentos e sete mil e quinhentos homens, que guerreavam valorosamente, para ajudarem o rei contra os inimigos.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 14, 'Uzias proveu o exército inteiro de escudos, lanças, capacetes, couraças e arcos, e até fundas para atirar pedras.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 15, 'E em Jerusalém fabricou máquinas, inventadas por peritos, para que fossem colocadas nas torres e nos cantos das muralhas, a fim de se atirarem com elas flechas e grandes pedras. E voou a sua fama até muito longe; porque foi maravilhosamente ajudado, até que se tornou poderoso.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 16, 'Mas, quando ele se havia tornado poderoso, o seu coração se exaltou de modo que se corrompeu, e cometeu transgressões contra o Senhor, seu Deus; pois entrou no templo do Senhor para queimar incenso no altar do incenso.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 17, 'Mas o sacerdote Azarias entrou após ele, com oitenta sacerdotes do Senhor, homens valorosos,', 1, CURRENT_TIMESTAMP, false),
(14, 26, 18, 'e se opuseram ao rei Uzias, dizendo-lhe: A ti, Uzias, não compete queimar incenso perante o Senhor, mas aos sacerdotes, filhos de Arão, que foram consagrados para queimarem incenso. Sai do santuário, pois cometeste uma transgressão; e não será isto para honra tua da parte do Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 19, 'Então Uzias se indignou; e tinha na mão um incensário para queimar incenso. Indignando-se ele, pois, contra os sacerdotes, nasceu-lhe a lepra na testa, perante os sacerdotes, na casa de Senhor, junto ao altar do incenso.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 20, 'Então o sumo sacerdote Azarias olhou para ele, como também todos os sacerdotes, e eis que já estava leproso na sua testa. E apressuradamente o lançaram fora, e ele mesmo se apressou a sair, porque o Senhor o ferira.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 21, 'Assim ficou leproso o rei Uzias até o dia da sua morte; e, por ser leproso, morou numa casa separada, pois foi excluído da casa do Senhor. E Jotão, seu filho, tinha o cargo da casa do rei, julgando o povo da terra.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 22, 'Quanto ao restante dos atos de Uzias, desde os primeiros até os últimos, o profeta Isaías, filho de Amoz, o escreveu.', 1, CURRENT_TIMESTAMP, false),
(14, 26, 23, 'Assim dormiu Uzias com seus pais, e com eles o sepultaram, isto é, no campo de sepultura que era dos reis; pois disseram: ele é leproso. E Jotão, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 1, 'Tinha Jotão vinte e cinco anos quando começou a reinar, e reinou dezesseis anos em Jerusalém. E o nome de sua mãe era Jerusa, filha de Zadoque,', 1, CURRENT_TIMESTAMP, false),
(14, 27, 2, 'Ele fez o que era reto aos olhos do Senhor, conforme tudo o que fizera Uzias, seu pai; todavia não invadiu o templo do Senhor. Mas o povo ainda se corrompia.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 3, 'Ele construiu a porta superior da casa do Senhor, e edificou extensivamente sobre o muro de Ofel.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 4, 'Também edificou cidades na região montanhosa de Judá, e castelos e torres nos bosques.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 5, 'Guerreou contra o rei dos amonitas e prevaleceu sobre eles; de modo que os amonitas naquele ano lhe deram cem talentos de prata, dez mil coros de trigo e dez mil de cevada. Isso lhe trouxeram os amonitas também no segundo e no terceiro ano.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 6, 'Assim Jotão se tornou poderoso, porque dirigiu os seus caminhos na presença do Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 7, 'Ora, o restante dos atos de Jotão, e todas as suas guerras e os seus caminhos, eis que estão escritos no livro dos reis de Israel e de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 8, 'Tinha vinte e cinco anos quando começou a reinar, e reinou dezesseis anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 27, 9, 'E Jotão dormiu com seus pais, e o sepultaram na cidade de Davi. E Acaz, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 1, 'Tinha Acaz vinte anos quando começou a reinar, e reinou dezesseis anos em Jerusalém. E não fez o que era reto aos olhos do Senhor, como Davi, seu pai;', 1, CURRENT_TIMESTAMP, false),
(14, 28, 2, 'mas andou nos caminhos dos reis de Israel, e até fez imagens de fundição para os baalins.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 3, 'Também queimava incenso no vale do filho de Hinom, e queimou seus filhos no fogo, conforme as abominações das nações que o senhor expulsara de diante dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 4, 'E sacrificava e queimava incenso nos altos e nos outeiros, como também debaixo de toda árvore frondosa.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 5, 'Pelo que o Senhor seu Deus o entregou na mão do rei dos sírios, os quais o derrotaram e tomaram-lhe em cativeiro grande multidão de presos, que levaram para Damasco. Foi também entregue na mão do rei de Israel, o qual lhe infligiu grande derrota,', 1, CURRENT_TIMESTAMP, false),
(14, 28, 6, 'pois Peca, filho de Remalias, matou em Judá, num só dia cento e vinte mil todos homens valentes; porquanto haviam abandonado o Senhor, Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 7, 'E Zicri, varão poderoso de Efraim matou Maaséias, filho do rei, e Azricão, e mordomo, e Elcana, o segundo depois do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 8, 'E os filhos de Israel levaram cativos de seus irmãos duzentos mil, mulheres filhos e filhas; também saquearam deles grande despojo, que levaram para Samária.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 9, 'Mas estava ali um profeta do Senhor, cujo nome era Odede, o qual saiu ao encontro do exército que vinha para Samária, e lhe disse: Eis que, irando-se o Senhor Deus de vossos pais contra Judá, os entregou na vossa mão, e vós os matastes com uma raiva que chegou até o céu.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 10, 'E agora vós quereis sujeitar a vós os filhos de Judá e de Jerusalém, como escravos e escravas; porventura não sois vós mesmos culpados para com o Senhor vosso Deus?', 1, CURRENT_TIMESTAMP, false),
(14, 28, 11, 'Agora, pois, ouvi-me, e tornai a enviar os cativos que trouxestes dentre vossos irmãos, pois o ardor da ira do Senhor está sobre vós.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 12, 'Então alguns dos chefes dos efraimitas, a saber, Azarias, filho de Joanã, Berequias, filho de Mesilemote, Jeizquias, filho de Salum, e Amasa, filho de Hadlai, se levantaram contra os que voltavam da guerra,', 1, CURRENT_TIMESTAMP, false),
(14, 28, 13, 'e lhes disseram: Não fareis entrar aqui estes cativos; porque, além da nossa culpa contra o Senhor, o que vós quereis fazer acrescentaria mais a nossos pecados e a nossas culpas; pois já temos grande culpa, e o ardor da ira do Senhor está sobre Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 14, 'Então os homens armados deixaram os cativos e o despojo diante dos príncipes e de toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 15, 'E os homens já mencionados por nome se levantaram e tomaram os cativos, e vestiram do despojo a todos os que dentre eles estavam nus; vestiram-nos, e os calçaram, e lhes deram de comer e de beber, e os ungiram; e, levando sobre jumentos todos os que estavam fracos, conduziram-nos a Jericó, a cidade das palmeiras, a seus irmãos. Depois voltaram para Samária.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 16, 'Naquele tempo o rei Acaz mandou pedir socorro ao rei da Assíria.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 17, 'Pois de novo os edomeus, tendo invadido Judá, a derrotaram e levaram prisioneiros.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 18, 'Também os filisteus tinham invadido as cidades da baixada e do sul de Judá, e tinham tomado Bete-Semes, Aijalom, Gederote, Socó e suas aldeias, Timna e suas aldeias, e Ginzo e suas aldeias, estabelecendo-se ali.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 19, 'Pois o Senhor humilhou Judá por causa do rei Acaz, porque este se houve desenfreadamente em Judá, havendo desprezado ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 20, 'E veio a ele Tilgate-Pilneser, rei da Assíria, e o pôs em aperto, em vez de fortalecê-lo.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 21, 'Pois Acaz saqueou a casa do Senhor, e a casa do rei, e dos príncipes, e deu os despojos por tributo ao rei da Assíria; porém isso não o ajudou.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 22, 'No tempo da sua angústia houve-se com ainda maior desprezo pelo Senhor, este mesmo rei Acaz.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 23, 'Pois sacrificou aos deuses de Damasco, que o tinham derrotado, e disse: Visto que os deuses dos reis da Síria os ajudam, portanto eu lhes sacrificarei, para que me ajudem a mim. Eles, porém, foram a ruína dele e de todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 24, 'Ajuntou Acaz os utensílios da casa de Deus, fê-los em pedaços, e fechou as portas da casa do Senhor; e fez para si altares em todos os cantos de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 25, 'Também em cada cidade de Judá fez altos para queimar incenso a outros deuses, assim provocando à ira o Senhor, Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 26, 'Ora, o restante dos seus atos e de todos os seus caminhos, desde os primeiros até os últimos, eis que está escrito no livro dos reis de Judá e de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 28, 27, 'E Acaz dormiu com seus pais, e o sepultaram na cidade, em Jerusalém; pois não o puseram nos sepulcros dos reis de Israel. E Ezequias, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 1, 'Ezequias começou a reinar quando tinha vinte e cinco anos; e reinou vinte e nove anos em Jerusalém. E o nome de sua mãe era Abia, filha de Zacarias.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 2, 'Ele fez o que era reto aos olhos do Senhor, conforme tudo quanto fizera Davi, seu pai.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 3, 'Pois ele, no primeiro ano do seu reinado, no primeiro mês, abriu as portas da casa do Senhor, e as reparou.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 4, 'Fez vir os sacerdotes e os levitas e, ajuntando-os na praça oriental,', 1, CURRENT_TIMESTAMP, false),
(14, 29, 5, 'disse-lhes: Ouvi-me, ó levitas; santificai-vos agora, e santificai a casa do Senhor, Deus de vossos pais, e tirai do santo lugar a imundícia.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 6, 'Porque nossos pais se houveram traiçoeiramente, e fizeram o que era mau aos olhos do Senhor nosso Deus; deixaram-no e, desviando os seus rostos da habitação do Senhor, voltaram-lhe as costas.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 7, 'Também fecharam as portas do alpendre, apagaram as lâmpadas, e não queimaram incenso nem ofereceram holocaustos no santo lugar ao Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 8, 'Pelo que veio a ira do Senhor sobre Judá e Jerusalém, e ele os entregou para serem motivo de espanto, de admiração e de escárnio, como vós o estais vendo com os vossos olhos.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 9, 'Porque eis que nossos pais caíram à espada, e nossos filhos, nossas filhas e nossas mulheres estão por isso em cativeiro.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 10, 'Agora tenho no coração o propósito de fazer um pacto com o Senhor, Deus de Israel, para que se desvie de nós o ardor da sua ira.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 11, 'Filhos meus, não sejais negligentes, pois o Senhor vos escolheu para estardes diante dele a fim de o servir, e para serdes seus ministros e queimardes incenso.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 12, 'Então se levantaram os levitas: Maate, filho de Amasai, e Joel, filho de Azarias, dos filhos dos coatitas; e dos filhos de Merári: Quis, filho de Abdi, e Azurias, filho de Jealelel; e dos gersonitas: Joá, filho de Zima, e Edem filho de Joá;', 1, CURRENT_TIMESTAMP, false),
(14, 29, 13, 'e dos filhos de Elizafã: Sínri e Jeuel; dos filhos de Asafe; Zacarias e Matanias;', 1, CURRENT_TIMESTAMP, false),
(14, 29, 14, 'e dos filhos de Hemã: Jeuel e Simei; e dos filhos de Jedutun: Semaías e Uziel.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 15, 'Ajuntaram seus irmãos, santificaram-se e entraram conforme a ordem do rei, segundo as palavras do Senhor, para purificarem a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 16, 'Também os sacerdotes entraram na parte interior da casa do Senhor para a limparem, e tirarem para fora, ao átrio da casa do Senhor, toda a imundícia que acharem no templo do Senhor; e os levitas a tomaram e a levaram para fora, ao ribeiro de Cedrom.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 17, 'Começaram a santificá-la no primeiro dia do primeiro mês, e ao oitavo dia do mês chegaram ao alpendre do Senhor, e santificaram a casa do Senhor em oito dias; no décimo sexto dia do primeiro mês acabaram.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 18, 'Então foram ter com o rei Ezequias no palácio, e disseram: Acabamos de limpar toda a casa do Senhor, como também o altar do holocausto com todos os seus utensílios, e a mesa dos pães da proposição com todos os seus utensílios.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 19, 'Todos os utensílios que o rei Acaz, no seu reinado, lançou fora, na sua infidelidade, já os preparamos e santificamos; e eis que estão diante do altar do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 20, 'Então o rei Ezequias se levantou de madrugada, e ajuntou os príncipes da cidade e subiu à casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 21, 'E trouxeram sete novilhos, sete carneiros, sete cordeiros e sete bodes, como oferta pelo pecado a favor do reino, e do santuário e de Judá; e o rei deu ordem aos sacerdotes, filhos de Arão, que os oferecessem sobre o altar do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 22, 'Os sacerdotes pois imolaram os novilhos, e tomando o sangue o espargiram sobre o altar; também imolaram os carneiros, e espargiram o sangue sobre o altar; semelhantemente imolaram os cordeiros, e espargiram o sangue sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 23, 'Então trouxeram os bodes, como oferta pelo pecado, perante o rei e a congregação, que lhes impuseram as mãos;', 1, CURRENT_TIMESTAMP, false),
(14, 29, 24, 'e os sacerdotes os imolaram, e com o seu sangue fizeram uma oferta pelo pecado, sobre o altar, para fazer expiação por todo o Israel. Porque o rei tinha ordenado que se fizesse aquele holocausto e aquela oferta pelo pecado por todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 25, 'Também dispôs os levitas na casa do Senhor com címbalos, alaúdes e harpas conforme a ordem de Davi, e de Gade, o vidente do rei, e do profeta Natã; porque esta ordem viera do Senhor, por meio de seus profetas.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 26, 'E os levitas estavam em pé com os instrumentos de Davi, e os sacerdotes com as trombetas.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 27, 'E Ezequias ordenou que se oferecesse o holocausto sobre o altar; e quando começou o holocausto, começou também o canto do Senhor, ao som das trombetas e dos instrumentos de Davi, rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 28, 'Então toda a congregação adorava, e os cantores cantavam, e os trombeteiros tocavam; tudo isso continuou até se acabar o holocausto.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 29, 'Tendo eles acabado de fazer a oferta, o rei e todos os que estavam com ele se prostraram e adoraram.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 30, 'E o rei Ezequias e os príncipes ordenaram aos levitas que louvassem ao Senhor com as palavras de Davi, e de Asafe, o vidente. E eles cantaram louvores com alegria, e se inclinaram e adoraram.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 31, 'Então Ezequias disse: Agora que vos consagrastes ao Senhor chegai-vos e trazei sacrifícios e ofertas em ação de graças a casa do Senhor. E a congregação trouxe sacrifícios e ofertas em ação de graças, e todos os que estavam dispostos de coração trouxeram holocaustos.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 32, 'E o número dos holocaustos que a congregação trouxe foi de setenta novilhos, cem carneiros e duzentos cordeiros, tudo isso em holocausto ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 33, 'Houve também, de coisas consagradas, seiscentos bois e três mil ovelhas.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 34, 'Eram, porém, mui poucos os sacerdotes, de modo que não podiam esfolar todos os holocaustos; pelo que seus irmãos, os levitas, os ajudaram, até se acabar a obra, e até que os outros sacerdotes se santificassem, pois os levitas foram mais retos de coração, para se santificarem, do que os sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 35, 'E houve também holocaustos em abundância, juntamente com a gordura das ofertas pacíficas, e com as ofertas de libação para cada holocausto. Assim se restabeleceu o ministério da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 29, 36, 'E Ezequias regozijou-se, e com ele todo o povo, por causa daquilo que Deus tinha preparado a favor do povo; pois isto se fizera de improviso.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 1, 'Depois disso Ezequias enviou mensageiros por todo o Israel e Judá, e escreveu cartas a Efraim e a Manassés, para que viessem à casa do Senhor em Jerusalém, a fim de celebrarem a páscoa ao Senhor Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 2, 'Pois o rei tivera conselho com os príncipes e com toda a congregação em Jerusalém, para celebrarem a páscoa no segundo mês.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 3, 'Pois não a puderam celebrar no tempo próprio porque não se tinham santificado sacerdotes em número suficiente, e porque o povo não se tinha ajuntado em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 4, 'Isto pareceu bem aos olhos do rei e de toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 5, 'E decretaram que se fizesse proclamação por todo o Israel, desde Berseba até Dã para que viessem celebrar a páscoa ao Senhor, Deus de Israel, em Jerusalém; porque muitos não a tinham celebrado como está escrito.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 6, 'Foram pois, os correios com as cartas, do rei e dos, seus príncipes, por todo o Israel e Judá, segundo a ordem do rei, dizendo: Filhos de Israel, voltai para o Senhor, Deus de Abraão, de Isaque e de Israel, para que ele se volte para o restante de vós que escapastes da mão dos reis da Assíria.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 7, 'Não sejais como vossos pais e vossos irmãos, que foram infiéis para com o Senhor, Deus de seus pais, de modo que os entregou à desolação como vedes.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 8, 'Não endureçais agora a vossa cerviz, como fizeram vossos pais; mas submetei-vos ao Senhor, e entrai no seu santuário que ele santificou para sempre, e servi ao Senhor vosso Deus, para que o ardor da sua ira se desvie de vós.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 9, 'Pois, se voltardes para o Senhor, vossos irmãos e vossos filhos acharão misericórdia diante dos que os levaram cativos, e tornarão para esta terra; porque o Senhor vosso Deus é clemente e compassivo, e não desviará de vós o seu rosto, se voltardes para ele.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 10, 'Os correios, pois, foram passando de cidade em cidade, pela terra de Efraím e Manassés, até Zebulom; porém riam-se e zombavam deles.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 11, 'Todavia alguns de Aser, e de Manassés, e de Zebulom, se humilharam e vieram a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 12, 'E a mão de Deus esteve com Judá, dando-lhes um só coração para cumprirem a ordem do rei e dos príncipes conforme a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 13, 'E ajuntou-se em Jerusalém muito povo para celebrar a festa dos pães ázimos no segundo mês, uma congregação mui grande.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 14, 'E, levantando-se, tiraram os altares que havia em Jerusalém; também tiraram todos os altares de incenso, e os lançaram no ribeiro de Cedrom.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 15, 'Então imolaram a páscoa no décimo quarto dia do segundo mês; e os sacerdotes e levitas, envergonhados, santificaram-se e trouxeram holocaustos à casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 16, 'Tomaram os seus lugares, segundo a sua ordem, conforme a lei de Moisés, homem de Deus; e os sacerdotes espargiram o sangue, que recebiam da mão dos levitas.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 17, 'Pois havia muitos na congregação que não se tinham santificado; pelo que os levitas tiveram que imolar os cordeiros da páscoa por todo aquele que não estava limpo, para o santificarem ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 18, 'Porque uma multidão do povo, muitos de Efraím e Manassés, Issacar e Zebulom, não se tinham purificado, contudo comeram a páscoa, ainda que não segundo o que está escrito; pois Ezequias tinha orado por eles, dizendo: O Senhor, que é bom, perdoe todo aquele', 1, CURRENT_TIMESTAMP, false),
(14, 30, 19, 'que dispõe o seu coração para buscar a Deus, o Senhor, o Deus de seus pais, ainda que não esteja purificado segundo a purificação do santuário.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 20, 'E o Senhor ouviu Ezequias, e sarou o povo.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 21, 'E os filhos de Israel que se acharam em Jerusalém celebraram a festa dos pães ázimos por sete dias com grande alegria; e os levitas e os sacerdotes louvaram ao Senhor de dia em dia com instrumentos fortemente retinintes, cantando ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 22, 'E Ezequias falou benignamente a todos os levitas que tinham bom entendimento no serviço do Senhor. Assim comeram as ofertas da festa por sete dias, sacrificando ofertas pacíficas, e dando graças ao Senhor, Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 23, 'E, tendo toda a congregação resolvido celebrar outros sete dias, celebraram por mais sete dias com alegria.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 24, 'Pois Ezequias, rei de Judá, apresentou à congregação para os sacrifícios mil novilhos e sete mil ovelhas; e os príncipes apresentaram à congregação mil novilhos e dez mil ovelhas; e os sacerdotes se santificaram em grande número.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 25, 'E regozijaram-se toda a congregação de Judá, juntamente com os sacerdotes e levitas, e toda a congregação dos que vieram de Israel, como também os estrangeiros que vieram da terra de Israel e os que habitavam em Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 26, 'Assim houve grande alegria em Jerusalém, pois desde os dias de Salomão, filho de Davi, rei de Israel, não tinha havido coisa semelhante em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 30, 27, 'Então os levitas sacerdotes se levantaram e abençoaram o povo; e a sua voz foi ouvida, porque a sua oração chegou até a santa habitação de Deus, até o céu.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 1, 'Acabado tudo isso, todos os israelitas que ali estavam saíram às cidades de Judá e despedaçaram as colunas, cortaram os aserins, e derrubaram os altos e altares por toda a Judá e Benjamim, como também em Efraim e Manassés, até os destruírem de todo. Depois voltaram todos os filhos de Israel para as suas cidades, cada um para sua possessão.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 2, 'E Ezequias estabeleceu as turmas dos sacerdotes e levitas, turma por turma, cada um segundo o seu serviço, tanto os sacerdotes como os levitas, para os holocaustos e as ofertas pacíficas, para ministrarem, renderem ações de graças e cantarem louvores nas portas do arraial do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 3, 'A contribuição da fazenda do rei foi designada para os holocaustos: os holocaustos da manhã e da tarde, e os holocaustos dos sábados, das luas novas e das festas fixas, como está escrito na lei do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 4, 'Além disso ordenou ao povo que morava em Jerusalém que desse a porção pertencente aos sacerdotes e aos levitas, para que eles se dedicassem à lei do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 5, 'Logo que esta ordem se divulgou, os filhos de Israel trouxeram em abundância as primícias de trigo, mosto, azeite, mel e todo produto do campo; também trouxeram em abundância o dízimo de tudo.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 6, 'Os filhos de Israel e de Judá que habitavam nas cidades de Judá também trouxeram o dízimo de bois e de ovelhas, e o dízimo das coisas dedicadas que foram consagradas ao Senhor seu Deus, e depositaram-nos em montões.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 7, 'No terceiro mês começaram a formar os montões, e no sétimo mês acabaram.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 8, 'Vindo, pois, Ezequias e os príncipes, e vendo aqueles montões, bendisseram ao Senhor e ao seu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 9, 'Então perguntou Ezequias aos sacerdotes e aos levitas acerca daqueles montões.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 10, 'Respondeu-lhe Azarias, o sumo sacerdote, que era da casa de Zadoque, dizendo: Desde que o povo começou a trazer as ofertas para a casa do Senhor, tem havido o que comer e de que se fartar, e ainda nos tem sobejado bastante, porque o Senhor abençoou ao seu povo; e os sobejos constituem esta abastança.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 11, 'Então ordenou Ezequias que se preparassem câmaras na casa do Senhor; e as prepararam.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 12, 'Ali recolheram fielmente as ofertas, os dízimos e as coisas dedicadas; e tinha o cargo disto o levita Conanias, e depois dele Simei, seu irmão.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 13, 'E Jeiel, Azazias, Naate, Asael, Jerimote, Jozabade, Eliel, Ismaquias, Maate e Benaías eram superintendentes sob a direção de Conanias e de Simei, seu irmão, por decreto do rei Ezequias e de Azarias, o chefe da casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 14, 'E o levita Coré, filho de Imná, e guarda da porta oriental, estava encarregado das ofertas voluntárias que se faziam a Deus, para distribuir as ofertas do Senhor e as coisas santíssimas.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 15, 'E debaixo das suas ordens estavam Edem, Miniamim, Jesuá, Semaías, Amarias e Secanias, nas cidades dos sacerdotes, para fazerem com fidelidade a distribuição a seus irmãos, segundo as suas turmas, tanto aos pequenos como aos grandes,', 1, CURRENT_TIMESTAMP, false),
(14, 31, 16, 'exceto os que estavam contados pelas genealogias, varões da idade de três anos para cima, todos os que entravam na casa do Senhor, para o seu serviço diário nos seus cargos segundo as suas turmas.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 17, 'Quanto ao registro dos sacerdotes, era feito segundo as suas casas paternas; e o dos levitas da idade de vinte anos para cima era feito segundo os seus cargos nas suas turmas.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 18, 'Os sacerdotes eram arrolados com todos os seus pequeninos, suas mulheres, seus filhos e suas filhas, por toda a congregação; porque estes se dedicavam fielmente às coisas consagradas.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 19, 'Também para os filhos de Arão os sacerdotes que estavam nos campos dos arrabaldes das suas cidades, em cada cidade, havia homens designados por nome para distribuírem porções a todo homem entre os sacerdotes e a todos os arrolados entre os levitas.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 20, 'Assim fez Ezequias em todo o Judá; e fez o que era bom, e reto, e fiel perante o Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 31, 21, 'E toda a obra que empreendeu no serviço da casa de Deus, e de acordo com a lei e os mandamentos, para buscar a seu Deus, ele a fez de todo o seu coração e foi bem sucedido.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 1, 'Depois destas coisas e destes atos de fidelidade, veio Senaqueribe, rei da Assíria e, entrando em Judá, acampou-se contra as cidades fortes, a fim de apoderar-se delas.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 2, 'Quando Ezequias viu que Senaqueribe tinha vindo com o propósito de guerrear contra Jerusalém,', 1, CURRENT_TIMESTAMP, false),
(14, 32, 3, 'teve conselho com os seus príncipes e os seus poderosos, para que se tapassem as fontes das águas que havia fora da cidade; e eles o ajudaram.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 4, 'Assim muito povo se ajuntou e tapou todas as fontes, como também o ribeiro que corria pelo meio da terra, dizendo: Por que viriam os reis da Assíria, e achariam tantas águas?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 5, 'Ezequias, cobrando ânimo, edificou todo o muro que estava demolido, levantando torres sobre ele, fez outro muro por fora, fortificou a Milo na cidade de Davi, e fez armas e escudos em abundância.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 6, 'Então pôs oficiais de guerra sobre o povo e, congregando-os na praça junto à porta da cidade, falou-lhes ao coração, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 32, 7, 'Sede corajosos, e tende bom ânimo; não temais, nem vos espanteis, por causa do rei da Assíria, nem por causa de toda a multidão que está com ele, pois há conosco um maior do que o que está com ele.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 8, 'Com ele está um braço de carne, mas conosco o Senhor nosso Deus, para nos ajudar e para guerrear por nós. E o povo descansou nas palavras de Ezequias, rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 9, 'Depois disso Senaqueribe, rei da Assíria, enquanto estava diante de Laquis, com todas as suas forças, enviou os seus servos a Jerusalém a Ezequias, rei de Judá, e a todo o Judá que estava em Jerusalém, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 32, 10, 'Assim diz Senaqueribe, rei da Assíria: Em que confiais vós, para vos deixardes sitiar em Jerusalém?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 11, 'Porventura não vos engana Ezequias, para vos fazer morrer à fome e à sede, quando diz: O Senhor nosso Deus nos livrará das mãos do rei da Assíria?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 12, 'Esse mesmo Ezequias não lhe tirou os altos e os altares, e não ordenou a Judá e a Jerusalém, dizendo: Diante de um só altar adorareis, e sobre ele queimareis incenso?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 13, 'Não sabeis vós o que eu e meus pais temos feito a todos os povos de outras terras? Puderam de qualquer maneira os deuses das nações daquelas terras livrar a sua terra da minha mão?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 14, 'Qual é, de todos os deuses daquelas nações que meus pais destruíram, o que pôde livrar o seu povo da minha mão, para que o vosso Deus vos possa livrar da minha mão?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 15, 'Agora, pois, não vos engane Ezequias, nem vos incite assim, nem lhe deis crédito. Porque nenhum deus de nação alguma, nem de reino algum, pôde livrar o seu povo da minha mão, nem da mão de meus pais; quanto menos o vosso Deus vos poderá livrar da minha mão?', 1, CURRENT_TIMESTAMP, false),
(14, 32, 16, 'E os servos de Senaqueribe falaram ainda mais contra o Senhor Deus, e contra o seu servo Ezequias.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 17, 'Ele também escreveu cartas para blasfemar do Senhor Deus de Israel, dizendo contra ele: Assim como os deuses das nações das terras não livraram o seu povo da minha mão, assim também o Deus de Ezequias não livrará o seu povo da minha mão.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 18, 'E clamaram em alta voz, na língua dos judeus, ao povo de Jerusalém que estava em cima do muro, para os atemorizarem e os perturbarem, a fim de tomarem a cidade.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 19, 'E falaram do Deus de Jerusalém como dos deuses dos povos da terra, que são obras das mãos dos homens.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 20, 'Mas o rei Ezequias e o profeta Isaías, filho de Amoz, oraram por causa disso, e clamaram ao céu.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 21, 'Então o Senhor enviou um anjo que destruiu no arraial do rei da Assíria todos os guerreiros valentes, e os príncipes, e os chefes. Ele, pois, envergonhado voltou para a sua terra; e, quando entrou na casa de seu deus, alguns dos seus próprios filhos o mataram ali à espada.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 22, 'Assim o Senhor salvou Ezequias, e os moradores de Jerusalém, da mão de Senaqueribe, rei da Assíria, e da mão de todos; e lhes deu descanso de todos os lados.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 23, 'E muitos trouxeram presentes a Jerusalém ao Senhor, e coisas preciosas a Ezequias, rei de Judá, de modo que desde então ele foi exaltado perante os olhos de todas as nações.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 24, 'Naqueles dias Ezequias, adoecendo, estava à morte: e orou ao Senhor o qual lhe respondeu, e lhe deu um sinal.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 25, 'Mas Ezequias não correspondeu ao benefício que lhe fora feito, pois o seu coração se exaltou; pelo que veio grande ira sobre ele, e sobre Judá e Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 26, 'Todavia Ezequias humilhou-se pela soberba do seu coração, ele e os habitantes de Jerusalém; de modo que a grande ira do Senhor não veio sobre eles nos dias de Ezequias.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 27, 'E teve Ezequias riquezas e honra em grande abundância; proveu-se de tesourarias para prata, ouro, pedras preciosas, especiarias, escudos, e toda espécie de objetos desejáveis;', 1, CURRENT_TIMESTAMP, false),
(14, 32, 28, 'também de celeiros para o aumento de trigo, de vinho, e de azeite; e de estrebarias para toda a casta de animais, e de currais para os rebanhos.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 29, 'Além disso edificou para si cidades, e teve rebanhos e manadas em abundância; pois Deus lhe tinha dado muitíssima fazenda.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 30, 'Também foi Ezequias quem tapou o manancial superior das águas de Giom, fazendo-as correr em linha reta pelo lado ocidental da cidade de Davi. Ezequias, pois, prosperou em todas as suas obras.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 31, 'Contudo, no negócio dos embaixadores dos príncipes de Babilônia, que lhe foram enviados a perguntarem acerca do prodígio que fora feito na sua terra, Deus o desamparou para experimentá-lo, e para saber tudo o que havia no seu coração.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 32, 'Ora, o restante dos atos de Ezequias, e as suas boas obras, eis que estão escritos na visão do profeta Isaías, filho de Amoz, no livro dos reis de Judá e de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 32, 33, 'E Ezequias dormiu com seus pais, e o sepultaram no mais alto dos sepulcros dos filhos de Davi; e todo o Judá e os habitantes de Jerusalém lhe renderam honras na sua morte. E Manassés, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 1, 'Tinha Manassés doze anos quando começou a reinar, e reinou cinqüenta e cinco anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 2, 'E fez o que era mau aos olhos do Senhor, conforme as abominações dos povos que o Senhor lançara fora de diante dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 3, 'Pois tornou a edificar os altos que Ezequias, seu pai, tinha derribado; e levantou altares aos baalins, e fez aserotes, e adorou a todo o exército do céu, e o serviu.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 4, 'Também edificou altares na casa do Senhor, da qual o Senhor tinha dito: Em Jerusalém estará o meu nome eternamente.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 5, 'Edificou altares a todo o exército do céu, nos dois átrios da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 6, 'Além disso queimou seus filhos como sacrifício no vale do filho de Hinom; e usou de augúrios e de encantamentos, e dava-se a artes mágicas, e instituiu adivinhos e feiticeiros; sim, fez muito mal aos olhos do Senhor, para o provocar à ira.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 7, 'Também a imagem esculpida do ídolo que tinha feito, ele a colocou na casa de Deus, da qual Deus tinha dito a Davi e a Salomão, seu filho: Nesta casa, e em Jerusalém, que escolhi de todas as tribos de Israel, porei eu o meu nome para sempre;', 1, CURRENT_TIMESTAMP, false),
(14, 33, 8, 'e nunca mais removerei o pé de Israel da terra que destinei a vossos pais; contanto que tenham cuidado de fazer tudo o que eu lhes ordenei, toda a lei, os estatutos e as ordenanças dados por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 9, 'Manassés tanto fez errar a Judá e aos moradores de Jerusalém, que eles fizeram o mal ainda mais do que as nações que o Senhor tinha destruído de diante dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 10, 'Falou o Senhor a Manassés e ao seu povo, porém não deram ouvidos.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 11, 'Pelo que o Senhor trouxe sobre eles os comandantes do exército do rei da Assíria, os quais prenderam Manassés com ganchos e, amarrando-o com cadeias de bronze, o levaram para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 12, 'E estando ele angustiado, suplicou ao Senhor seu Deus, e humilhou-se muito perante o Deus de seus pais;', 1, CURRENT_TIMESTAMP, false),
(14, 33, 13, 'sim, orou a ele; e Deus se aplacou para com ele, e ouviu-lhe a súplica, e tornou a trazê-lo a Jerusalém, ao seu reino. Então conheceu Manassés que o Senhor era Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 14, 'Ora, depois disso edificou um muro do lado de fora da cidade de Davi, ao ocidente de Giom, no vale, até a entrada da porta dos peixes; e fê-lo passar ao redor de Ofel, e o levantou muito alto; também pôs oficiais do exército em todas as cidades fortificadas de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 15, 'Tirou da casa do Senhor os deuses estranhos e o ídolo, como também todos os altares que tinha edificado no monte da casa do Senhor, e em Jerusalém, e os lançou fora da cidade.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 16, 'Também reparou o altar do Senhor, e ofereceu sobre ele sacrifícios de ofertas pacíficas e de ações de graças; e ordenou a Judá que servisse ao Senhor Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 17, 'Contudo o povo ainda sacrificava nos altos, mas somente ao Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 18, 'O restante dos atos de Manassés, e a sua oração ao seu Deus, e as palavras dos videntes que lhe falaram em nome do Senhor, Deus de Israel eram os seus altares e as suas imagens, e a Matã, sacerdote de', 1, CURRENT_TIMESTAMP, false),
(14, 33, 19, 'Também a sua oração, e como Deus se aplacou para com ele, e todo o seu pecado, e a sua transgressão, e os lugares onde edificou altos e pôs os aserins e as imagens esculpidas antes de se ter humilhado, eis que estão escritos nas crônicas dos videntes.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 20, 'E dormiu Manassés com seus pais, e o sepultaram em sua casa; e Amom, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 21, 'Tinha Amom vinte e dois anos quando começou a reinar, e reinou dois anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 22, 'Fez o que era mau aos olhos do Senhor, como havia feito Manassés, seu pai Amom sacrificou a todas as imagens esculpidas que Manassés, seu pai, tinha feito, e as serviu.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 23, 'Mas não se humilhou perante o Senhor, como Manassés, seu pai, se humilhara; pelo contrário multiplicou Amom os seus delitos.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 24, 'E conspiraram contra ele os seus servos, e o mataram em sua casa.', 1, CURRENT_TIMESTAMP, false),
(14, 33, 25, 'Mas o povo da terra matou todos os que conspiraram contra o rei Amom, e fez reinar em lugar dele seu filho Josias.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 1, 'Tinha Josias oito anos quando começou a reinar, e reinou trinta e um anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 2, 'Fez o que era reto aos olhos do Senhor, e andou nos caminhos de Davi, seu pai, sem se desviar deles nem para a direita nem para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 3, 'Pois no oitavo ano do seu reinado, sendo ainda moço, começou a buscar o Deus de Davi, seu pai; e no duodécimo ano começou a purificar Judá e Jerusalém, dos altos, dos aserins e das imagens esculpidas e de fundição.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 4, 'Foram derribados na presença dele os altares dos baalins; e ele derribou os altares de incenso que estavam acima deles; os aserins e as imagens esculpidas e de fundição ele os quebrou e reduziu a pó, que espargiu sobre as sepulturas dos que lhes tinham sacrificado.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 5, 'E os ossos dos sacerdotes queimou sobre os seus altares; e purificou Judá e Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 6, 'E nas cidades de Manassés, de Efraim, de Simeão e ainda até Naftali, em seus lugares assolados ao redor,', 1, CURRENT_TIMESTAMP, false),
(14, 34, 7, 'derribou os altares, reduziu a pó os aserins e as imagens esculpidas, e cortou todos os altares de incenso por toda a terra de Israel. Então, voltou para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 8, 'No décimo oitavo ano do seu reinado, havendo já purificado a terra e a casa, ele enviou Safã, filho de Azalias, Maaséias, o governador da cidade, e Joá, filho de Joacaz, o cronista, para repararem a casa do Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 9, 'E foram ter com Hilquias, o sumo sacerdote, e entregaram o dinheiro que se tinha trazido à casa de Deus, e que os levitas, guardas da entrada, tinham recebido da mão de Manassés, de Efraim e de todo o resto de Israel, como também, de todo o Judá e Benjamim, e dos habitantes de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 10, 'E eles o entregaram nas mãos dos oficiais que eram superintendentes da casa do Senhor; estes o deram aos que faziam a obra e que trabalhavam na casa do Senhor, para consertarem e repararem a casa.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 11, 'Deram-no aos carpinteiros e aos edificadores, a fim de comprarem pedras lavradas, e madeiras para as junturas e para servirem de vigas para as casas que os reis de Judá tinham destruído.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 12, 'E os homens trabalhavam fielmente na obra; e os superintendentes sobre eles eram Jaate e Obadias, levitas, dos filhos de Merári, como também Zacarias e Mesulão, dos filhos dos coatitas, para adiantarem a obra; e todos os levitas que eram entendidos em instrumentos de música.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 13, 'Estavam sobre os carregadores e dirigiam todos os que trabalhavam em qualquer sorte de serviço; também dentre os levitas eram os escrivães, os oficiais e os porteiros.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 14, 'Ora, quando estavam tirando o dinheiro que se tinha trazido à casa do Senhor, Hilquias, o sacerdote, achou o livro da lei do Senhor dada por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 15, 'Disse Hilquias a Safã, o escrivão: Achei o livro da lei na casa do Senhor. E entregou o livro a Safã.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 16, 'Safã levou o livro ao rei, e deu conta também ao rei, dizendo: Teus servos estão fazendo tudo quanto se lhes encomendou.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 17, 'Tomaram o dinheiro que se achou na casa do Senhor, e o entregaram nas mãos dos superintendentes e nas mãos dos que fazem a obra.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 18, 'Safã, o escrivão, falou ainda ao rei, dizendo: O sacerdote Hilquias entregou-me um livro. E Safã leu nele perante o rei.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 19, 'Quando o rei ouviu as palavras da lei, rasgou as suas vestes.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 20, 'E o rei ordenou a Hilquias, a Aicão, filho de Safã, a Abdom, filho de Mica, a Safã, o escrivão, e a Asaías, servo do rei, dizendo:', 1, CURRENT_TIMESTAMP, false),
(14, 34, 21, 'Ide, consultai ao Senhor por mim e pelos que restam em Israel e em Judá, sobre as palavras deste livro que se achou; pois grande é o furor do Senhor que se tem derramado sobre nos por não terem os nossos pais guardado a palavra do Senhor, para fazerem conforme tudo quanto está escrito neste livro.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 22, 'Então Hilquias e os enviados do rei foram ter com a profetisa Hulda, mulher de Salum, filho de Tocate, filho de Hasra, o guarda das vestiduras {ela habitava então em Jerusalém na segunda parte}; e lhe falaram a esse respeito.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 23, 'E ela lhes respondeu: Assim diz o Senhor, Deus de Israel: Dizei ao homem que vos enviou a mim:', 1, CURRENT_TIMESTAMP, false),
(14, 34, 24, 'Assim diz o Senhor: Eis que trarei o mal sobre este lugar, e sobre os seus habitantes, a saber, todas as maldições que estão escritas no livro que se leu perante o rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 25, 'Porque me deixaram, e queimaram incenso a outros deuses, para me provocarem à ira com todas as obras das suas mãos; portanto o meu furor se derramará sobre este lugar, e não se apagará.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 26, 'Todavia ao rei de Judá, que vos enviou para consultar ao Senhor, assim lhe direis: Assim diz o Senhor, Deus de Israel: Quanto às palavras que ouviste,', 1, CURRENT_TIMESTAMP, false),
(14, 34, 27, 'porquanto o teu coração se enterneceu, e te humilhaste perante Deus, ouvindo as suas palavras contra este lugar e contra os seus habitantes, e te humilhaste perante mim, e rasgaste as tuas vestes, e choraste perante mim, também eu te ouvi, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 28, 'Eis que te ajuntarei a teus pais, e tu serás recolhido ao teu sepulcro em paz, e os teus olhos não verão todo o mal que hei de trazer sobre este lugar e sobre os seus habitantes. E voltaram com esta resposta ao rei.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 29, 'Então o rei mandou reunir todos os anciãos de Judá e de Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(14, 34, 30, 'e o rei subiu à casa do Senhor, com todos os homens de Judá, e os habitantes de Jerusalém, e os sacerdotes, e os levitas, e todo o povo, desde o menor até o maior; e ele leu aos ouvidos deles todas as palavras do livro do pacto, que fora encontrado na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 31, 'E o rei pôs-se em pé em seu lugar, e fez um pacto perante o Senhor, de andar após o Senhor, e de guardar os seus mandamentos, e os seus testemunhos, e os seus estatutos, de todo o coração e de toda a alma, a fim de cumprir as palavras do pacto, que estavam escritas naquele livro.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 32, 'Também fez com que todos quantos se achavam em Jerusalém e em Benjamim o firmassem; e os habitantes de Jerusalém fizeram conforme o pacto de Deus, do Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 34, 33, 'E Josias tirou todas as abominações de todas as terras que eram dos filhos de Israel; e ainda fez que todos quantos se achavam em Israel servissem ao Senhor seu Deus. E, enquanto ele viveu, não deixaram de seguir ao Senhor, Deus de seus pais.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 1, 'Então Josias celebrou a páscoa ao Senhor em Jerusalém; imolou-se o cordeiro da páscoa no décimo quarto dia do primeiro mês.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 2, 'E estabeleceu os sacerdotes nos seus cargos, e os animou a servirem na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 3, 'E disse aos levitas que ensinavam a todo o Israel e que estavam consagrados ao Senhor: Ponde a arca sagrada na casa que Salomão, filho de Davi, rei de Israel, edificou; não tereis mais esta carga sobre os vossos ombros. Agora servi ao Senhor vosso Deus e ao seu povo Israel;', 1, CURRENT_TIMESTAMP, false),
(14, 35, 4, 'preparai-vos segundo as vossas casas paternas, e segundo as vossas turmas, conforme o preceito de Davi, rei de Israel, e o de Salomão, seu filho.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 5, 'E estai no lugar santo segundo as divisões das casas paternas de vossos irmãos, os filhos do povo, e haja para cada divisão uma parte de uma família levítica.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 6, 'Também imolai a páscoa, e santificai-vos, e preparai-a para vossos irmãos, fazendo conforme a palavra do Senhor dada por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 7, 'Ora, Josias deu aos filhos do povo, a todos que ali estavam, cordeiros e cabritos do rebanho em número de trinta mil, todos para os sacrifícios da páscoa, e três mil novilhos; isto era da fazenda do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 8, 'Também os seus príncipes fizeram ofertas voluntárias ao povo, aos sacerdotes e aos levitas; Hilquias, Zacarias e Jeiel, chefes da casa de Deus, deram aos sacerdotes, para os sacrifícios da páscoa, dois mil e seiscentos cordeiros e cabritos e trezentos novilhos.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 9, 'Também Conanias, e Semaías e Netanel, seus irmãos, como também Hasabias, Jeiel e Jozabade, chefes dos levitas, apresentaram aos levitas, para os sacrifícios da páscoa, cinco mil cordeiros e cabritos e quinhentos novilhos.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 10, 'Assim se preparou o serviço, e puseram-se os sacerdotes nos seus postos, e os levitas pelas suas turmas, conforme a ordem do rei.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 11, 'Então imolaram a páscoa; e os sacerdotes espargiam o sangue que recebiam das mãos dos levitas, e estes esfolavam as reses.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 12, 'E puseram à parte os holocaustos para os distribuírem aos filhos do povo, segundo as divisões das casas paternas, a fim de que os oferecessem ao Senhor, como está escrito no livro de Moisés; e assim fizeram com os novilhos.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 13, 'Assaram a páscoa ao fogo, segundo a ordenança; e as ofertas sagradas cozeram em panelas em caldeirões e em tachos, e prontamente as repartiram entre todo o povo.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 14, 'Depois prepararam o que era preciso para si e para os sacerdotes; porque os sacerdotes, filhos de Arão, se ocuparam até a noite em oferecer os holocaustos e a gordura; pelo que os levitas prepararam para si e para os sacerdotes, filhos de Arão.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 15, 'Os cantores, filhos de Asafe, estavam no seu posto, segundo o mandado de Davi, de Asafe, de Hemã e de Jedútum vidente do rei; como também os porteiros estavam a cada porta; não precisaram se desviar do seu serviço, porquanto seus irmãos, os levitas preparavam o necessário para eles.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 16, 'Assim se estabeleceu todo o serviço do Senhor naquele dia, para celebrar a páscoa, e para oferecer holocaustos sobre o altar do Senhor, segundo a ordem do rei Josias.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 17, 'E os filhos de Israel que ali estavam celebraram a páscoa naquela ocasião e, durante sete dias, a festa dos pães ázimos.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 18, 'Nunca se celebrara em Israel uma páscoa semelhante a essa, desde os dias do profeta Samuel; e nenhum dos reis de Israel celebrara tal páscoa como a que Josias celebrou com os sacerdotes e levitas, e todo o Judá e Israel que ali estavam, e os habitantes de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 19, 'Foi no décimo oitavo ano do reinado de Josias que se celebrou esta páscoa.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 20, 'Depois de tudo isso, havendo Josias já preparado o templo, subiu Neco, rei do Egito, para guerrear contra Carquêmis, junto ao Eufrates; e Josias lhe saiu ao encontro.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 21, 'Neco, porém, mandou-lhe mensageiros, dizendo: Que tenho eu que fazer contigo, rei de Judá? Não é contra ti que venho hoje, mas contra a casa à qual faço guerra; e Deus mandou que me apressasse. Deixa de te opores a Deus, que está comigo, para que ele não te destrua.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 22, 'Todavia Josias não quis virar dele o seu rosto, mas disfarçou-se para pelejar contra ele e, não querendo ouvir as palavras de Neco, que saíram da boca de Deus, veio pelejar no vale de Megido.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 23, 'E os flecheiros atiraram ao rei Josias. Então o rei disse a seus servos: Tirai-me daqui, porque estou gravemente ferido.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 24, 'Seus servos o removeram do carro e pondo-o no seu segundo carro, o trouxeram a Jerusalém. Ele morreu, e foi sepultado nos sepulcros de seus pais. E todo o Judá e Jerusalém prantearam a Josias.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 25, 'Também Jeremias fez uma lamentação sobre Josias; e todos os cantores e cantoras têm falado de Josias nas suas lamentações até o dia de hoje; e as estabeleceram por costume em Israel; e eis que estão escritas nas Lamentações.', 1, CURRENT_TIMESTAMP, false),
(14, 35, 26, 'Ora, o restante dos atos de Josias, e as suas boas obras em conformidade com o que está escrito na lei do Senhor,', 1, CURRENT_TIMESTAMP, false),
(14, 35, 27, 'e os seus atos, desde os primeiros até os últimos, eis que estão escritos no livro dos reis de Israel e de Judá.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 1, 'O povo da terra tomou Jeoacaz, filho de Josias, e o constituiu rei em lugar de seu pai, em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 2, 'Tinha Jeoacaz vinte e três anos quando começou a reinar, e reinou três meses em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 3, 'Porquanto o rei do Egito o depôs em Jerusalém, e condenou a terra a pagar um tributo de cem talentos de prata e um talento de ouro.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 4, 'Então o rei do Egito constituiu Eliaquim, irmão de Jeoacaz, rei sobre Judá e Jerusalém, e mudou-lhe o nome em Jeoiaquim; mas a seu irmão, Jeoacaz, Neco o tomou e o levou para o Egito.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 5, 'Tinha Jeoiaquim vinte e cinco anos quando começou a reinar, e reinou onze anos em Jerusalém; e fez o que era mau aos olhos do Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 6, 'Contra ele subiu Nabucodonosor, rei de Babilônia, e o amarrou com cadeias a fim de o levar para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 7, 'Também alguns dos vasos da casa do Senhor levou Nabucodonosor para Babilônia, e pô-los no seu templo em Babilônia.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 8, 'Ora, o restante dos atos de Jeoiaquim, e as abominações que praticou, e o que se achou contra ele, eis que estão escritos no livro dos reis de Israel e de Judá. E Joaquim, seu filho, reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 9, 'Tinha Joaquim oito anos quando começou a reinar, e reinou três meses e dez dias em Jerusalém; e fez o que era mau aos olhos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 10, 'Na primavera seguinte o rei Nabucodonosor mandou que o levassem para Babilônia, juntamente com os vasos preciosos da casa do Senhor; e constituiu a Zedequias, irmão de Joaquim, rei sobre Judá e Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 11, 'Tinha Zedequias vinte e um anos quando começou a reinar, e reinou onze anos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 12, 'E fez o que era mau aos olhos do Senhor seu Deus: e não se humilhou perante o profeta Jeremias, que lhe falava da parte do Senhor.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 13, 'Também rebelou-se contra o rei Nabucodonosor, que o tinha ajuramentado por Deus. Mas endureceu a sua cerviz e se obstinou no seu coração, para não voltar ao Senhor, Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 14, 'Além disso todos os chefes dos sacerdotes e o povo aumentavam cada vez mais a sua infidelidade, seguindo todas as abominações dos gentios; e profanaram a casa do Senhor, que ele tinha santificado para si em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 15, 'E o Senhor, Deus de seus pais, falou-lhes persistentemente por intermédio de seus mensageiros, porque se compadeceu do seu povo e da sua habitação.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 16, 'Eles, porém, zombavam dos mensageiros de Deus, desprezando as suas palavras e mofando dos seus profetas, até que o furor do Senhor subiu tanto contra o seu povo, que mais nenhum remédio houve.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 17, 'Por isso fez vir sobre eles o rei dos caldeus, o qual matou os seus mancebos à espada, na casa do seu santuário, e não teve piedade nem dos mancebos, nem das donzelas, nem dos velhos nem dos decrépitos; entregou-lhos todos nas mãos.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 18, 'E todos os vasos da casa de Deus, grandes e pequenos, os tesouros da casa do Senhor, e os tesouros do rei e dos seus príncipes, tudo levou para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 19, 'Também queimaram a casa de Deus, derribaram os muros de Jerusalém, queimaram a fogo todos os seus palácios, e destruíram todos os seus vasos preciosos.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 20, 'E aos que escaparam da espada, a esses levou para Babilônia; e se tornaram servos dele e de seus filhos, até o tempo do reino da Pérsia,', 1, CURRENT_TIMESTAMP, false),
(14, 36, 21, 'para se cumprir a palavra do Senhor proferida pela boca de Jeremias, até haver a terra gozado dos seus sábados; pois por todos os dias da desolação repousou, até que os setenta anos se cumpriram.', 1, CURRENT_TIMESTAMP, false),
(14, 36, 22, 'Ora, no primeiro ano de Ciro, rei da pérsia, para que se cumprisse a palavra do Senhor proferida pela boca de Jeremias, despertou o Senhor o espírito de Ciro, rei da Pérsia, de modo que ele fez proclamar por todo o seu reino, de viva voz e também por escrito, este decreto:', 1, CURRENT_TIMESTAMP, false),
(14, 36, 23, 'Assim diz Ciro, rei da Pérsia: O Senhor Deus do céu me deu todos os reinos da terra, e me encarregou de lhe edificar uma casa em Jerusalém, que é em Judá. Quem há entre vós de todo o seu povo suba, e o Senhor seu Deus seja com ele.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 1, 'O ancião à senhora eleita, e a seus filhos, aos quais eu amo em verdade, e não somente eu, mas também todos os que conhecem a verdade,', 1, CURRENT_TIMESTAMP, false),
(63, 1, 2, 'por causa da verdade que permanece em nós, e para sempre estará conosco:', 1, CURRENT_TIMESTAMP, false),
(63, 1, 3, 'Graça, misericórdia, paz, da parte de Deus Pai e da parte de Jesus Cristo, o Filho do Pai, serão conosco em verdade e amor.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 4, 'Muito me alegro por ter achado alguns de teus filhos andando na verdade, assim como recebemos mandamento do Pai.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 5, 'E agora, senhora, rogo-te, não como te escrevendo um novo mandamento, mas aquele mesmo que desde o princípio tivemos: que nos amemos uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 6, 'E o amor é este: que andemos segundo os seus mandamentos. Este é o mandamento, como já desde o princípio ouvistes, para que nele andeis.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 7, 'Porque já muitos enganadores saíram pelo mundo, os quais não confessam que Jesus Cristo veio em carne. Tal é o enganador e o anticristo.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 8, 'Olhai por vós mesmos, para que não percais o fruto do nosso trabalho, antes recebeis plena recompensa.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 9, 'Todo aquele que vai além do ensino de Cristo e não permanece nele, não tem a Deus; quem permanece neste ensino, esse tem tanto ao Pai como ao Filho.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 10, 'Se alguém vem ter convosco, e não traz este ensino, não o recebais em casa, nem tampouco o saudeis.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 11, 'Porque quem o saúda participa de suas más obras.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 12, 'Embora tenha eu muitas coisas para vos escrever, não o quis fazer com papel e tinta; mas espero visitar-vos e falar face a face, para que o nosso gozo seja completo.', 1, CURRENT_TIMESTAMP, false),
(63, 1, 13, 'Saúdam-te os filhos de tua irmã, a eleita.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 1, 'Simão Pedro, servo e apóstolo de Jesus Cristo, aos que conosco alcançaram fé igualmente preciosa na justiça do nosso Deus e Salvador Jesus Cristo:', 1, CURRENT_TIMESTAMP, false),
(61, 1, 2, 'Graça e paz vos sejam multiplicadas no pleno conhecimento de Deus e de Jesus nosso Senhor;', 1, CURRENT_TIMESTAMP, false),
(61, 1, 3, 'visto como o seu divino poder nos tem dado tudo o que diz respeito à vida e à piedade, pelo pleno conhecimento daquele que nos chamou por sua própria glória e virtude;', 1, CURRENT_TIMESTAMP, false),
(61, 1, 4, 'pelas quais ele nos tem dado as suas preciosas e grandíssimas promessas, para que por elas vos torneis participantes da natureza divina, havendo escapado da corrupção, que pela concupiscência há no mundo.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 5, 'E por isso mesmo vós, empregando toda a diligência, acrescentai à vossa fé a virtude, e à virtude a ciência,', 1, CURRENT_TIMESTAMP, false),
(61, 1, 6, 'e à ciência o domínio próprio, e ao domínio próprio a perseverança, e à perseverança a piedade,', 1, CURRENT_TIMESTAMP, false),
(61, 1, 7, 'e à piedade a fraternidade, e à fraternidade o amor.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 8, 'Porque, se em vós houver e abundarem estas coisas, elas não vos deixarão ociosos nem infrutíferos no pleno conhecimento de nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 9, 'Pois aquele em quem não há estas coisas é cego, vendo somente o que está perto, havendo-se esquecido da purificação dos seus antigos pecados.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 10, 'Portanto, irmãos, procurai mais diligentemente fazer firme a vossa vocação e eleição; porque, fazendo isto, nunca jamais tropeçareis.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 11, 'Porque assim vos será amplamente concedida a entrada no reino eterno do nosso Senhor e Salvador Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 12, 'Pelo que estarei sempre pronto para vos lembrar estas coisas, ainda que as saibais, e estejais confirmados na verdade que já está convosco.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 13, 'E tendo por justo, enquanto ainda estou neste tabernáculo, despertar-vos com admoestações,', 1, CURRENT_TIMESTAMP, false),
(61, 1, 14, 'sabendo que brevemente hei de deixar este meu tabernáculo, assim como nosso Senhor Jesus Cristo já mo revelou.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 15, 'Mas procurarei diligentemente que também em toda ocasião depois da minha morte tenhais lembrança destas coisas.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 16, 'Porque não seguimos fábulas engenhosas quando vos fizemos conhecer o poder e a vinda de nosso Senhor Jesus Cristo, pois nós fôramos testemunhas oculares da sua majestade.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 17, 'Porquanto ele recebeu de Deus Pai honra e glória, quando pela Glória Magnífica lhe foi dirigida a seguinte voz: Este é o meu Filho amado, em quem me comprazo;', 1, CURRENT_TIMESTAMP, false),
(61, 1, 18, 'e essa voz, dirigida do céu, ouvimo-la nós mesmos, estando com ele no monte santo.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 19, 'E temos ainda mais firme a palavra profética à qual bem fazeis em estar atentos, como a uma candeia que alumia em lugar escuro, até que o dia amanheça e a estrela da alva surja em vossos corações;', 1, CURRENT_TIMESTAMP, false),
(61, 1, 20, 'sabendo primeiramente isto: que nenhuma profecia da Escritura é de particular interpretação.', 1, CURRENT_TIMESTAMP, false),
(61, 1, 21, 'Porque a profecia nunca foi produzida por vontade dos homens, mas os homens da parte de Deus falaram movidos pelo Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 1, 'Mas houve também entre o povo falsos profetas, como entre vós haverá falsos mestres, os quais introduzirão encobertamente heresias destruidoras, negando até o Senhor que os resgatou, trazendo sobre si mesmos repentina destruição.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 2, 'E muitos seguirão as suas dissoluções, e por causa deles será blasfemado o caminho da verdade;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 3, 'também, movidos pela ganância, e com palavras fingidas, eles farão de vós negócio; a condenação dos quais já de largo tempo não tarda e a sua destruição não dormita.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 4, 'Porque se Deus não poupou a anjos quando pecaram, mas lançou-os no inferno, e os entregou aos abismos da escuridão, reservando-os para o juízo;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 5, 'se não poupou ao mundo antigo, embora preservasse a Noé, pregador da justiça, com mais sete pessoas, ao trazer o dilúvio sobre o mundo dos ímpios;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 6, 'se, reduzindo a cinza as cidades de Sodoma e Gomorra, condenou-as à destruição, havendo-as posto para exemplo aos que vivessem impiamente;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 7, 'e se livrou ao justo Ló, atribulado pela vida dissoluta daqueles perversos', 1, CURRENT_TIMESTAMP, false),
(61, 2, 8, '{porque este justo, habitando entre eles, por ver e ouvir, afligia todos os dias a sua alma justa com as injustas obras deles};', 1, CURRENT_TIMESTAMP, false),
(61, 2, 9, 'também sabe o Senhor livrar da tentação os piedosos, e reservar para o dia do juízo os injustos, que já estão sendo castigados;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 10, 'especialmente aqueles que, seguindo a carne, andam em imundas concupiscências, e desprezam toda autoridade. Atrevidos, arrogantes, não receiam blasfemar das dignidades,', 1, CURRENT_TIMESTAMP, false),
(61, 2, 11, 'enquanto que os anjos, embora maiores em força e poder, não pronunciam contra eles juízo blasfemo diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 12, 'Mas estes, como criaturas irracionais, por natureza feitas para serem presas e mortas, blasfemando do que não entendem, perecerão na sua corrupção,', 1, CURRENT_TIMESTAMP, false),
(61, 2, 13, 'recebendo a paga da sua injustiça; pois que tais homens têm prazer em deleites à luz do dia; nódoas são eles e máculas, deleitando-se em suas dissimulações, quando se banqueteiam convosco;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 14, 'tendo os olhos cheios de adultério e insaciáveis no pecar; engodando as almas inconstantes, tendo um coração exercitado na ganância, filhos de maldição;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 15, 'os quais, deixando o caminho direito, desviaram-se, tendo seguido o caminho de Balaão, filho de Beor, que amou o prêmio da injustiça,', 1, CURRENT_TIMESTAMP, false),
(61, 2, 16, 'mas que foi repreendido pela sua própria transgressão: um mudo jumento, falando com voz humana, impediu a loucura do profeta.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 17, 'Estes são fontes sem água, névoas levadas por uma tempestade, para os quais está reservado o negrume das trevas.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 18, 'Porque, falando palavras arrogantes de vaidade, nas concupiscências da carne engodam com dissoluções aqueles que mal estão escapando aos que vivem no erro;', 1, CURRENT_TIMESTAMP, false),
(61, 2, 19, 'prometendo-lhes liberdade, quando eles mesmos são escravos da corrupção; porque de quem um homem é vencido, do mesmo é feito escravo.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 20, 'Porquanto se, depois de terem escapado das corrupções do mundo pelo pleno conhecimento do Senhor e Salvador Jesus Cristo, ficam de novo envolvidos nelas e vencidos, tornou-se-lhes o último estado pior que o primeiro.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 21, 'Porque melhor lhes fora não terem conhecido o caminho da justiça, do que, conhecendo-o, desviarem-se do santo mandamento que lhes fora dado.', 1, CURRENT_TIMESTAMP, false),
(61, 2, 22, 'Deste modo sobreveio-lhes o que diz este provérbio verdadeiro; Volta o cão ao seu vômito, e a porca lavada volta a revolver-se no lamaçal.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 1, 'Amados, já é esta a segunda carta que vos escrevo; em ambas as quais desperto com admoestações o vosso ânimo sincero;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 2, 'para que vos lembreis das palavras que dantes foram ditas pelos santos profetas, e do mandamento do Senhor e Salvador, dado mediante os vossos apóstolos;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 3, 'sabendo primeiro isto, que nos últimos dias virão escarnecedores com zombaria andando segundo as suas próprias concupiscências,', 1, CURRENT_TIMESTAMP, false),
(61, 3, 4, 'e dizendo: Onde está a promessa da sua vinda? porque desde que os pais dormiram, todas as coisas permanecem como desde o princípio da criação.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 5, 'Pois eles de propósito ignoram isto, que pela palavra de Deus já desde a antiguidade existiram os céus e a terra, que foi tirada da água e no meio da água subsiste;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 6, 'pelas quais coisas pereceu o mundo de então, afogado em água;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 7, 'mas os céus e a terra de agora, pela mesma palavra, têm sido guardados para o fogo, sendo reservados para o dia do juízo e da perdição dos homens ímpios.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 8, 'Mas vós, amados, não ignoreis uma coisa: que um dia para o Senhor é como mil anos, e mil anos como um dia.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 9, 'O Senhor não retarda a sua promessa, ainda que alguns a têm por tardia; porém é longânimo para convosco, não querendo que ninguém se perca, senão que todos venham a arrepender-se.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 10, 'Virá, pois, como ladrão o dia do Senhor, no qual os céus passarão com grande estrondo, e os elementos, ardendo, se dissolverão, e a terra, e as obras que nela há, serão descobertas.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 11, 'Ora, uma vez que todas estas coisas hão de ser assim dissolvidas, que pessoas não deveis ser em santidade e piedade,', 1, CURRENT_TIMESTAMP, false),
(61, 3, 12, 'aguardando, e desejando ardentemente a vinda do dia de Deus, em que os céus, em fogo se dissolverão, e os elementos, ardendo, se fundirão?', 1, CURRENT_TIMESTAMP, false),
(61, 3, 13, 'Nós, porém, segundo a sua promessa, aguardamos novos céus e uma nova terra, nos quais habita a justiça.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 14, 'Pelo que, amados, como estais aguardando estas coisas, procurai diligentemente que por ele sejais achados imaculados e irrepreensível em paz;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 15, 'e tende por salvação a longanimidade de nosso Senhor; como também o nosso amado irmão Paulo vos escreveu, segundo a sabedoria que lhe foi dada;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 16, 'como faz também em todas as suas epístolas, nelas falando acerca destas coisas, mas quais há pontos difíceis de entender, que os indoutos e inconstantes torcem, como o fazem também com as outras Escrituras, para sua própria perdição.', 1, CURRENT_TIMESTAMP, false),
(61, 3, 17, 'Vós, portanto, amados, sabendo isto de antemão, guardai-vos de que pelo engano dos homens perversos sejais juntamente arrebatados, e descaiais da vossa firmeza;', 1, CURRENT_TIMESTAMP, false),
(61, 3, 18, 'antes crescei na graça e no conhecimento de nosso Senhor e Salvador Jesus Cristo. A ele seja dada a glória, assim agora, como até o dia da eternidade.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 1, 'Depois da morte de Saul, tendo Davi voltado da derrota dos amalequitas e estando há dois dias em Ziclague,', 1, CURRENT_TIMESTAMP, false),
(10, 1, 2, 'ao terceiro dia veio um homem do arraial de Saul, com as vestes rasgadas e a cabeça coberta de terra; e, chegando ele a Davi, prostrou-se em terra e lhe fez reverência.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 3, 'Perguntou-lhe Davi: Donde vens? Ele lhe respondeu: Escapei do arraial de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 4, 'Davi ainda lhe indagou: Como foi lá isso? Dize-mo. Ao que ele lhe respondeu: O povo fugiu da batalha, e muitos do povo caíram, e morreram; também Saul e Jônatas, seu filho, foram mortos.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 5, 'Perguntou Davi ao mancebo que lhe trazia as novas: Como sabes que Saul e Jônatas, seu filho, são mortos?', 1, CURRENT_TIMESTAMP, false),
(10, 1, 6, 'Então disse o mancebo que lhe dava a notícia: Achava-me por acaso no monte Gilboa, e eis que Saul se encostava sobre a sua lança; os carros e os cavaleiros apertavam com ele.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 7, 'Nisso, olhando ele para trás, viu-me e me chamou; e eu disse: Eis-me aqui.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 8, 'Ao que ele me perguntou: Quem és tu? E eu lhe respondi: Sou amalequita.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 9, 'Então ele me disse: Chega-te a mim, e mata-me, porque uma vertigem se apoderou de mim, e toda a minha vida está ainda em mim.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 10, 'Cheguei-me, pois, a ele, e o matei, porque bem sabia eu que ele não viveria depois de ter caído; e tomei a coroa que ele tinha na cabeça, e o bracelete que trazia no braço, e os trouxe aqui a meu senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 11, 'Então pegou Davi nas suas vestes e as rasgou; e assim fizeram também todos os homens que estavam com ele;', 1, CURRENT_TIMESTAMP, false),
(10, 1, 12, 'e prantearam, e choraram, e jejuaram até a tarde por Saul, e por Jônatas, seu filho, e pelo povo do Senhor, e pela casa de Israel, porque tinham caída à espada.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 13, 'Perguntou então Davi ao mancebo que lhe trouxera a nova: Donde és tu? Respondeu ele: Sou filho de um peregrino amalequita.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 14, 'Davi ainda lhe perguntou: Como não temeste estender a mão para matares o ungido do Senhor?', 1, CURRENT_TIMESTAMP, false),
(10, 1, 15, 'Então Davi, chamando um dos mancebos, disse-lhe: chega-te, e lança-te sobre ele. E o mancebo o feriu, de sorte que morreu.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 16, 'Pois Davi lhe dissera: O teu sangue seja sobre a tua cabeça, porque a tua própria boca testificou contra ti, dizendo: Eu matei o ungido do Senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 17, 'Lamentou Davi a Saul e a Jônatas, seu filho, com esta lamentação,', 1, CURRENT_TIMESTAMP, false),
(10, 1, 18, 'mandando que fosse ensinada aos filhos de Judá; eis que está escrita no livro de Jasar:', 1, CURRENT_TIMESTAMP, false),
(10, 1, 19, 'Tua glória, ó Israel, foi morta sobre os teus altos! Como caíram os valorosos!', 1, CURRENT_TIMESTAMP, false),
(10, 1, 20, 'Não o noticieis em Gate, nem o publiqueis nas ruas de Asquelom; para que não se alegrem as filhas dos filisteus, para que não exultem as filhas dos incircuncisos.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 21, 'Vós, montes de Gilboa, nem orvalho, nem chuva caia sobre, vós, ó campos de morte; pois ali desprezivelmente foi arrojado o escudo dos valorosos, o escudo de Saul, ungido com óleo.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 22, 'Do sangue dos feridos, da gordura dos valorosos, nunca recuou o arco de Jônatas, nem voltou vazia a espada de Saul.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 23, 'Saul e Jônatas, tão queridos e amáveis na sua vida, também na sua morte não se separaram; eram mais ligeiros do que as águias, mais fortes do que os leões.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 24, 'Vós, filhas de Israel, chorai por Saul, que vos vestia deliciosamente de escarlata, que vos punha sobre os vestidos adornos de ouro.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 25, 'Como caíram os valorosos no meio da peleja!', 1, CURRENT_TIMESTAMP, false),
(10, 1, 26, 'Angustiado estou por ti, meu irmão Jônatas; muito querido me eras! Maravilhoso me era o teu amor, ultrapassando o amor de mulheres.', 1, CURRENT_TIMESTAMP, false),
(10, 1, 27, 'Como caíram os valorosos, e pereceram as armas de guerra!', 1, CURRENT_TIMESTAMP, false),
(10, 2, 1, 'Sucedeu depois disto que Davi consultou ao Senhor, dizendo: Subirei a alguma das cidades de Judá? Respondeu-lhe o Senhor: Sobe. Ainda perguntou Davi: Para onde subirei? Respondeu o Senhor: Para Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 2, 'Subiu, pois, Davi para lá, e também as suas duas mulheres, Ainoã, a jizreelita, e Abigail, que fora mulher de Nabal, e carmelita.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 3, 'Davi fez subir também os homens que estavam com ele, cada um com sua família; e habitaram nas cidades de Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 4, 'Então vieram os homens de Judá, e ali ungiram Davi rei sobre a casa de Judá. Depois informaram a Davi, dizendo: Foram os homens de Jabes-Gileade que sepultaram a Saul.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 5, 'Pelo que Davi enviou mensageiros aos homens de Jabes-Gileade, a dizer-lhes: Benditos do Senhor sejais vós, que fizestes tal benevolência, sepultando a Saul, vosso senhor!', 1, CURRENT_TIMESTAMP, false),
(10, 2, 6, 'Agora, pois, o Senhor use convosco de benevolência e fidelidade; e eu também vos retribuirei esse bem que fizestes.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 7, 'Esforcem-se, pois, agora as vossas mãos, e sede homens valorosos; porque Saul, vosso senhor, é morto, e a casa de Judá me ungiu por seu rei.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 8, 'Ora, Abner, filho de Ner, chefe do exército de Saul, tomou a Is-Bosete, filho de Saul, e o fez passar a Maanaim,', 1, CURRENT_TIMESTAMP, false),
(10, 2, 9, 'e o constituiu rei sobre Gileade, sobre os asuritas, sobre Jizreel, sobre Efraim, sobre Benjamim e sobre todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 10, 'Quarenta anos tinha Is-Bosete, filho de Saul, quando começou a reinar sobre Israel, e reinou dois anos, A casa de Judá, porém, seguia a Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 11, 'E foi o tempo que Davi reinou em Hebrom, sobre a casa de Judá, sete anos e seis meses.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 12, 'Depois Abner, filho de Ner, com os servos de Is-Bosete, filho de Saul, saiu de Maanaim para Gibeão.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 13, 'Saíram também Joabe, filho de Zeruia, e os servos de Davi, e se encontraram com eles perto do tanque de Gibeão; e pararam uns de um lado do tanque, e os outros do outro lado.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 14, 'Então disse Abner a Joabe: Levantem-se os mancebos, e se batam diante de nós. Respondeu Joabe: Levantem-se.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 15, 'Levantaram-se, pois, e passaram, em número de doze por Benjamim e por Is-Bosete, filho de Saul, e doze dos servos de Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 16, 'E cada um lançou mão da cabeça de seu contendor, e meteu-lhe a espada pela ilharga; assim caíram juntos; pelo que se chamou àquele lugar, que está junto a Gibeão, Helcate-Hazurim.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 17, 'Seguiu-se naquele dia uma crua peleja; e Abner e os homens de Israel foram derrotados diante dos servos de Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 18, 'Ora, estavam ali os três filhos de Zeruia: Joabe, Abisai, e Asael; e Asael era ligeiro de pés, como as gazelas do campo.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 19, 'Perseguiu, pois, Asael a Abner, seguindo-o sem se desviar nem para a direita nem para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 20, 'Nisso Abner, olhando para trás, perguntou: És tu Asael? Respondeu ele: Sou eu.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 21, 'Ao que lhe disse Abner: Desvia-te para a direita, ou para a esquerda, e lança mão de um dos mancebos, e toma os seus despojos. Asael, porém , não quis desviar-se de seguí-lo.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 22, 'Então Abner tornou a dizer a Asael: Desvia-te de detrás de mim; porque hei de ferir-te e dar contigo em terra? e como levantaria eu o meu rosto diante de Joabe, teu irmão?', 1, CURRENT_TIMESTAMP, false),
(10, 2, 23, 'Todavia ele recusou desviar-se; pelo que Abner o feriu com o conto da lança pelo ventre, de modo que a lança lhe saiu por detrás; e ele caiu ali, e morreu naquele mesmo lugar. E sucedeu que, todos os que chegavam ao lugar onde Asael caíra morto, paravam.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 24, 'Mas Joabe e Abisai perseguiram a Abner; e pôs-se o sol ao chegarem eles ao outeiro de Amá, que está diante de Giá, junto ao caminho do deserto de Gibeão.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 25, 'E os filhos de Benjamim se ajuntaram atrás de Abner e, formando-se num batalhão, puseram-se no cume dum outeiro.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 26, 'Então Abner gritou a Joabe, e disse: Devorará a espada para sempre? não sabes que por fim haverá amargura? até quando te demorarás em ordenar ao povo que deixe de perseguir a seus irmãos?', 1, CURRENT_TIMESTAMP, false),
(10, 2, 27, 'Respondeu Joabe: Vive Deus, que, se não tivesses falado, só amanhã cedo teria o povo cessado, cada um, de perseguir a seu irmão.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 28, 'Então Joabe tocou a buzina, e todo o povo parou; e não perseguiram mais a Israel, e tampouco pelejaram mais.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 29, 'E caminharam Abner e os seus homens toda aquela noite pela Arabá; e, passando o Jordão, caminharam por todo o Bitrom, e vieram a Maanaim.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 30, 'Voltou, pois, Joabe de seguir a Abner; e quando ajuntou todo o povo, faltavam dos servos de Davi dezenove homens, e Asael.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 31, 'Mas os servos de Davi tinham ferido dentre os de Benjamim, e dentre os homens de Abner, a trezentos e sessenta homens, de tal maneira que morreram.', 1, CURRENT_TIMESTAMP, false),
(10, 2, 32, 'E levantaram a Asael, e o sepultaram no sepulcro de seu pai, que estava em Belém. E Joabe e seus homens caminharam toda aquela noite, e amanheceu-lhes o dia em Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 1, 'Ora, houve uma longa guerra entre a casa de Saul e a casa de Davi; porém Davi se fortalecia cada vez mais, enquanto a casa de Saul cada vez mais se enfraquecia.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 2, 'Nasceram filhos a Davi em Hebrom. Seu primogênito foi Amnom, de Ainoã, a jizreelita;', 1, CURRENT_TIMESTAMP, false),
(10, 3, 3, 'o segundo Quileabe, de Abigail, que fôra mulher de Nabal, o carmelita; o terceiro Absalão, filho de Maacá, filha de Talmai, rei de Gesur;', 1, CURRENT_TIMESTAMP, false),
(10, 3, 4, 'o quarto Adonias, filho de Hagite, o quinto Sefatias, filho de Abital;', 1, CURRENT_TIMESTAMP, false),
(10, 3, 5, 'e o sexto Itreão, de Eglá, também mulher de Davi; estes nasceram a Davi em Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 6, 'Enquanto havia guerra entre a casa de Saul e a casa de Davi, Abner ia se tornando poderoso na casa de Saul:', 1, CURRENT_TIMESTAMP, false),
(10, 3, 7, 'Ora, Saul tivera uma concubina, cujo nome era Rizpa, filha de Aías. Perguntou, pois, Is-Bosete a Abner: Por que entraste à concubina de meu pai?', 1, CURRENT_TIMESTAMP, false),
(10, 3, 8, 'Então Abner, irando-se muito pelas palavras de Is-Bosete, disse: Sou eu cabeça de cão, que pertença a Judá? Ainda hoje uso de benevolência para com a casa de Saul, teu pai, e para com seus irmãos e seus amigos, e não te entreguei nas mãos de Davi; contudo tu hoje queres culpar-me no tocante a essa mulher.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 9, 'Assim faça Deus a Abner, e outro tanto, se, como o Senhor jurou a Davi, assim eu não lhe fizer,', 1, CURRENT_TIMESTAMP, false),
(10, 3, 10, 'transferindo o reino da casa de Saul, e estabelecendo o trono de Davi sobre Israel, e sobre Judá, desde Dã até Berseba.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 11, 'E Is-Bosete não pôde responder a Abner mais uma palavra, porque o temia.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 12, 'Então enviou Abner da sua parte mensageiros a Davi, dizendo: De quem é a terra? Comigo faze a tua aliança, e eis que a minha mão será contigo, para fazer tornar a ti todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 13, 'Respondeu Davi: Está bem; farei aliança contigo; mas uma coisa te exijo; não verás a minha face, se primeiro não me trouxeres Mical, filha de Saul, quando vieres ver a minha face.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 14, 'Também enviou Davi mensageiros a Is-Bosete, filho de Saul, dizendo: Entrega-me minha mulher Mical, que eu desposei por cem prepúcios de filisteus.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 15, 'Enviou, pois, Is-Bosete, e a tirou a seu marido, a Paltiel, filho de Laís,', 1, CURRENT_TIMESTAMP, false),
(10, 3, 16, 'que a seguia, chorando atrás dela até Baurim. Então lhe disse Abner: Vai-te; volta! E ele voltou.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 17, 'Falou Abner com os anciãos de Israel, dizendo: De há muito procurais fazer com que Davi reine sobre vós;', 1, CURRENT_TIMESTAMP, false),
(10, 3, 18, 'fazei-o, pois, agora, porque o Senhor falou de Davi, dizendo: Pela mão do meu servo Davi livrarei o meu povo da mão dos filisteus e da mão de todos os seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 19, 'Do mesmo modo falou Abner a Benjamim, e foi também dizer a Davi, em Hebrom, tudo o que Israel e toda a casa de Benjamim tinham resolvido.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 20, 'Abner foi ter com Davi, em Hebrom, com vinte homens; e Davi fez um banquete a Abner e aos homens que com ele estavam.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 21, 'Então disse Abner a Davi: Eu me levantarei, e irei ajuntar ao rei meu senhor todo o Israel, para que faça aliança contigo; e tu reinarás sobre tudo o que desejar a sua alma: Assim despediu Davi a Abner, e ele se foi em paz.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 22, 'Eis que os servos de Davi e Joabe voltaram de uma sortida, e traziam consigo grande despojo; mas Abner já não estava com Davi em Hebrom, porque este o tinha despedido, e ele se fora em paz.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 23, 'Quando, pois, chegaram Joabe e todo o exército que vinha com ele, disseram-lhe: Abner, filho de Ner, veio ter com o rei; e o rei o despediu, e ele se foi em paz.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 24, 'Então Joabe foi ao rei, e disse: Que fizeste? Eis que Abner veio ter contigo; por que, pois, o despediste, de maneira que se fosse assim livremente?', 1, CURRENT_TIMESTAMP, false),
(10, 3, 25, 'Bem conheces a Abner, filho de Ner; ele te veio enganar, e saber a tua saída e a tua entrada, e conhecer tudo quanto fazes.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 26, 'E Joabe, retirando-se de Davi, enviou mensageiros atrás de Abner, que o fizeram voltar do poço de Sira, sem que Davi o soubesse.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 27, 'Quando Abner voltou a Hebrom, Joabe o tomou à parte, à entrada da porta, para lhe falar em segredo; e ali, por causa do sangue de Asael, seu irmão, o feriu no ventre, de modo que ele morreu.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 28, 'Depois Davi, quando o soube, disse: Inocente para sempre sou eu, e o meu reino, para com o Senhor, no tocante ao sangue de Abner, filho de Ner.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 29, 'Caia ele sobre a cabeça de Joabe e sobre toda a casa de seu pai, e nunca falte na casa de Joabe quem tenha fluxo, ou quem seja leproso, ou quem se atenha a bordão, ou quem caia à espada, ou quem necessite de pão.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 30, 'Joabe, pois, e Abisai, seu irmão, mataram Abner, por ter ele morto a Asael, irmão deles, na peleja em Gibeão.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 31, 'Disse Davi a Joabe e a todo o povo que com ele estava: Rasgai as vossas vestes, cingi-vos de sacos e ide pranteando diante de Abner. E o rei Davi ia seguindo o féretro.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 32, 'Sepultaram Abner em Hebrom; e o rei, levantando a sua voz, chorou junto da sepultura de Abner; chorou também todo o povo.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 33, 'Pranteou o rei a Abner, dizendo: Devia Abner, porventura, morrer como morre o vilão?', 1, CURRENT_TIMESTAMP, false),
(10, 3, 34, 'As tuas mãos não estavam atadas, nem os teus pés carregados de grilhões; mas caíste como quem cai diante dos filhos da iniqüidade. Então todo o povo tornou a chorar por ele.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 35, 'Depois todo o povo veio fazer com que Davi comesse pão, sendo ainda dia; porém Davi jurou, dizendo: Assim Deus me faça e outro tanto, se, antes que o sol se ponha, eu provar pão ou qualquer outra coisa.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 36, 'Todo o povo notou isso, e pareceu-lhe bem; assim como tudo quanto o rei fez pareceu bem a todo o povo.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 37, 'Assim todo o povo e todo o Israel entenderam naquele mesmo dia que não fora a vontade do rei que matassem a Abner, filho de Ner.', 1, CURRENT_TIMESTAMP, false),
(10, 3, 38, 'Então disse o rei aos seus servos: Não sabeis que hoje caiu em Israel um príncipe, um grande homem?', 1, CURRENT_TIMESTAMP, false),
(10, 3, 39, 'E quanto a mim, hoje estou fraco, embora ungido rei; estes homens, filhos de Zeruia, são duros demais para mim. Retribua o Senhor ao malfeitor conforme a sua maldade.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 1, 'Quando Is-Bosete, filho de Saul, soube que Abner morrera em Hebrom, esvaíram-se-lhe as forças, e todo o Israel ficou perturbado.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 2, 'Tinha Is-Bosete, filho de Saul, dois homens chefes de guerrilheiros; um deles se chamava Baaná, e o outro Recabe, filhos de Rimom, o beerotita, dos filhos de Benjamim {porque também Beerote era contado de Benjamim,', 1, CURRENT_TIMESTAMP, false),
(10, 4, 3, 'tendo os beerotitas fugido para Jitaim, onde têm peregrinado até o dia de hoje}.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 4, 'Ora, Jônatas, filho de Saul, tinha um filho aleijado dos pés. Este era da idade de cinco anos quando chegaram de Jizreel as novas a respeito de Saul e Jônatas; pelo que sua ama o tomou, e fugiu; e sucedeu que, apressando-se ela a fugir, ele caiu, e ficou coxo. O seu nome era Mefibosete.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 5, 'Foram os filhos de Rimom, o beerotita, Recabe e Baanã, no maior calor de dia, e entraram em casa de Is-Bosete, estando ele deitado a dormir a sesta.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 6, 'Entraram ali até o meio da casa, como que vindo apanhar trigo, e o feriram no ventre; e Recabe e Baaná, seu irmão, escaparam.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 7, 'Porque entraram na sua casa, estando ele deitado na cama, no seu quarto de dormir, e o feriram e mataram, e cortando-lhe a cabeça, tomaram-na e andaram a noite toda pelo caminho da Arabá.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 8, 'Assim trouxeram a cabeça de Is-Bosete a Davi em Hebrom, e disseram ao rei: Eis aqui a cabeça de Is-Bosete, filho de Saul, teu inimigo, que procurava a tua morte; assim o Senhor vingou hoje ao rei meu Senhor, de Saul e da sua descendência.', 1, CURRENT_TIMESTAMP, false),
(10, 4, 9, 'Mas Davi, respondendo a Recabe e a Baaná, seu irmão, filhos de Rimom, e beerotita, disse-lhes: Vive o Senhor, que remiu a minha alma de toda a angústia!', 1, CURRENT_TIMESTAMP, false),
(10, 4, 10, 'Se àquele que me trouxe novas, dizendo: Eis que Saul é morto, cuidando que trazia boas novas, eu logo lancei mão dele, e o matei em Ziclague, sendo essa a recompensa que lhe dei pelas novas,', 1, CURRENT_TIMESTAMP, false),
(10, 4, 11, 'quanto mais quando homens cruéis mataram um homem justo em sua casa, sobre a sua cama, não requererei eu e seu sangue de vossas mãos, e não vos exterminarei da terra?', 1, CURRENT_TIMESTAMP, false),
(10, 4, 12, 'E Davi deu ordem aos seus mancebos; e eles os mataram e, cortando-lhes as mãos e os pés, os penduraram junto ao tanque em Hebrom. Tomaram, porém, a cabeça de Is-Bosete, e a sepultaram na sepultura de Abner, em Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 1, 'Então todas as tribos de Israel vieram a Davi em Hebrom e disseram: Eis-nos aqui, teus ossos e tua carne!', 1, CURRENT_TIMESTAMP, false),
(10, 5, 2, 'Além disso, outrora, quando Saul ainda reinava sobre nós, eras tu o que saías e entravas com Israel; e também o Senhor te disse: Tu apascentarás o meu povo de Israel, e tu serás chefe sobre Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 3, 'Assim, pois, todos os anciãos de Israel vieram ter com o rei em Hebrom; e o rei Davi fez aliança com eles em Hebrom, perante o Senhor; e ungiram a Davi rei sobre Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 4, 'Trinta anos tinha Davi quando começou a reinar, e reinou quarenta anos.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 5, 'Em Hebrom reinou sete anos e seis meses sobre Judá, e em Jerusalém reinou trinta e três anos sobre todo o Israel e Judá.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 6, 'Depois partiu o rei com os seus homens para Jerusalém, contra os jebuseus, que habitavam naquela terra, os quais disseram a Davi: Não entrarás aqui; os cegos e es coxos te repelirão; querendo dizer: Davi de maneira alguma entrará aqui.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 7, 'Todavia Davi tomou a fortaleza de Sião; esta é a cidade de Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 8, 'Ora, Davi disse naquele dia: Todo o que ferir os jebuseus, suba ao canal, e fira a esses coxos e cegos, a quem a alma de Davi aborrece. Por isso se diz: Nem cego nem, coxo entrara na casa.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 9, 'Assim habitou Davi na fortaleza, e chamou-a cidade de Davi; e foi levantando edifícios em redor, desde Milo para dentro.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 10, 'Davi ia-se engrandecendo cada vez mais, porque o Senhor Deus dos exércitos era com ele.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 11, 'Hirão, rei de Tiro, enviou mensageiros a Davi, e madeira de cedro, e carpinteiros e pedreiros, que edificaram para Davi uma casa.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 12, 'Entendeu, pois, Davi que o Senhor o confirmara rei sobre Israel, e que exaltara e reino dele por amar do seu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 13, 'Davi tomou ainda para si concubinas e mulheres de Jerusalém, depois que viera de Hebrom; e nasceram a Davi mais filhos e filhas.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 14, 'São estes os nomes dos que lhe nasceram em Jerusalém: Samua, Sobabe, Natã, Salomão,', 1, CURRENT_TIMESTAMP, false),
(10, 5, 15, 'Ibar, Elisua, Nefegue, Jafia,', 1, CURRENT_TIMESTAMP, false),
(10, 5, 16, 'Elisama, e Eliadá e Elifelete.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 17, 'Quando os filisteus ouviram que Davi fora ungido rei sobre Israel, subiram todos em busca dele. Ouvindo isto, Davi desceu à fortaleza.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 18, 'Os filisteus vieram, e se estenderam pelo vale de Refaim.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 19, 'Pelo que Davi consultou ao Senhor, dizendo: Subirei contra os filisteus? entregar-mos-ás nas mãos? Respondeu o Senhor a Davi: Sobe, pois eu entregarei os filisteus nas tuas mãos.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 20, 'Então foi Davi a Baal-Perazim, e ali os derrotou; e disse: O Senhor rompeu os meus inimigos diante de mim, como as águas rompem barreiras. Por isso chamou o nome daquele lugar Baal-Perazim.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 21, 'Os filisteus deixaram lá os seus ídolos, e Davi e os seus homens os levaram.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 22, 'Tornaram ainda os filisteus a subir, e se espalharam pelo vale de Refaim.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 23, 'E Davi consultou ao Senhor, que respondeu: Não subirás; mas rodeia-os por detrás, e virás sobre eles por defronte dos balsameiros.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 24, 'E há de ser que, ouvindo tu o ruído de marcha pelas copas dos balsameiros, então te apressarás, porque é o Senhor que sai diante de ti, a ferir o arraial dos filisteus.', 1, CURRENT_TIMESTAMP, false),
(10, 5, 25, 'Fez, pois, Davi como o Senhor lhe havia ordenado; e feriu os filisteus desde Geba, até chegar a Gezer.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 1, 'Tornou Davi a ajuntar todos os escolhidos de Israel, em número de trinta mil.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 2, 'Depois levantou-se Davi, e partiu para Baal-Judá com todo o povo que tinha consigo, para trazerem dali para cima a arca de Deus, a qual é chamada pelo Nome, o nome do Senhor dos exércitos, que se assenta sobre os querubins.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 3, 'Puseram a arca de Deus em um carro novo, e a levaram da casa de Abinadabe, que estava sobre o outeiro; e Uzá e Aiô, filhos de Abinadabe, guiavam o carro novo.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 4, 'Foram, pois, levando-o da casa de Abinadabe, que estava sobre o outeiro, com a arca de Deus; e Aiô ia adiante da arca.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 5, 'E Davi, e toda a casa de Israel, tocavam perante o Senhor, com toda sorte de instrumentos de pau de faia, como também com harpas, saltérios, tamboris, pandeiros e címbalos.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 6, 'Quando chegaram à eira de Nacom, Uzá estendeu a mão à arca de Deus, e pegou nela, porque os bois tropeçaram.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 7, 'Então a ira do Senhor se acendeu contra Uzá, e Deus o feriu ali; e Uzá morreu ali junto à arca de Deus.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 8, 'E Davi se contristou, porque o Senhor abrira rotura em Uzá; e passou-se a chamar àquele lugar, Pérez-Uzá, até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 9, 'Davi, pois, teve medo do Senhor naquele dia, e disse: Como virá a mim a arca do Senhor?', 1, CURRENT_TIMESTAMP, false),
(10, 6, 10, 'E não quis levar a arca do Senhor para a cidade de Davi; mas fê-la entrar na casa de Obede-Edom, o gitita.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 11, 'E ficou a arca do Senhor três meses na casa de Obede-Edom, o gitita, e o Senhor o abençoou e a toda a sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 12, 'Então informaram a Davi, dizendo: O Senhor abençoou a casa de Obede-Edom, e tudo quanto é dele, por causa da arca de Deus. Foi, pois, Davi, e com alegria fez subir a arca de Deus, da casa de Obede-Edom para a cidade de Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 13, 'Quando os que levavam a arca do Senhor tinham dado seis passos, ele sacrificou um boi e um animal cevado.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 14, 'E Davi dançava com todas as suas forças diante do Senhor; e estava Davi cingido dum éfode de linho.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 15, 'Assim Davi e toda a casa de Israel subiam, trazendo a arca do Senhor com júbilo e ao som de trombetas.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 16, 'Quando entrava a arca do Senhor na cidade de Davi, Mical, filha de Saul, estava olhando pela janela; e, vendo ao rei Davi saltando e dançando diante do senhor, o desprezou no seu coração.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 17, 'Introduziram, pois, a arca do Senhor, e a puseram no seu lugar, no meio da tenda que Davi lhe armara; e Davi ofereceu holocaustos e ofertas pacíficas perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 18, 'Quando Davi acabou de oferecer os holocaustos e ofertas pacíficas, abençoou o povo em nome do Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 19, 'Depois repartiu a todo o povo, a toda a multidão de Israel, tanto a homens como a mulheres, a cada um, um bolo de pão, um bom pedaço de carne e um bolo de passas. Em seguida todo o povo se retirou, cada um para sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 20, 'Então Davi voltou para abençoar a sua casa; e Mical, filha de Saul, saiu a encontrar-se com Davi, e disse: Quão honrado foi o rei de Israel, descobrindo-se hoje aos olhos das servas de seus servos, como sem pejo se descobre um indivíduo qualquer.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 21, 'Disse, porém, Davi a Mical: Perante o Senhor, que teu escolheu a mim de preferência a teu pai e a toda a sua casa, estabelecendo-me por chefe sobre o povo do Senhor, sobre Israel, sim, foi perante Senhor que dancei; e perante ele ainda hei de dançar', 1, CURRENT_TIMESTAMP, false),
(10, 6, 22, 'Também ainda mais do que isso me envilecerei, e me humilharei aos meus olhos; mas das servas, de quem falaste, delas serei honrado.', 1, CURRENT_TIMESTAMP, false),
(10, 6, 23, 'E Mical, filha de Saul não teve filhos, até o dia de sua morte.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 1, 'Ora, estando o rei Davi em sua casa e tendo-lhe dado o Senhor descanso de todos os seus inimigos em redor,', 1, CURRENT_TIMESTAMP, false),
(10, 7, 2, 'disse ele ao profeta Natã: Eis que eu moro numa casa de cedro, enquanto que a arca de Deus dentro de uma tenda.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 3, 'Respondeu Natã ao rei: Vai e faze tudo quanto está no teu coração, porque o Senhor é contigo.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 4, 'Mas naquela mesma noite a palavra do Senhor veio a Natã, dizendo:', 1, CURRENT_TIMESTAMP, false),
(10, 7, 5, 'Vai, e dize a meu servo Davi: Assim diz o Senhor: Edificar-me-ás tu uma casa para eu nela habitar?', 1, CURRENT_TIMESTAMP, false),
(10, 7, 6, 'Porque em casa nenhuma habitei, desde o dia em que fiz subir do Egito os filhos de Israel até o dia de hoje, mas tenho andado em tenda e em tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 7, 'E em todo lugar em que tenho andado com todos os filhos de Israel, falei porventura, alguma palavra a qualquer das suas tribos a que mandei apascentar o meu povo de Israel, dizendo: por que não me edificais uma casa de cedro?', 1, CURRENT_TIMESTAMP, false),
(10, 7, 8, 'Agora, pois, assim dirás ao meu servo Davi: Assim diz o Senhor dos exércitos: Eu te tomei da malhada, de detrás das ovelhas, para que fosses príncipe sobre o meu povo, sobre Israel;', 1, CURRENT_TIMESTAMP, false),
(10, 7, 9, 'e fui contigo, por onde quer que foste, e destruí a todos os teus inimigos diante de ti; e te farei um grande nome, como o nome dos grandes que há na terra.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 10, 'Também designarei lugar para o meu povo, para Israel, e o plantarei ali, para que ele habite no seu lugar, e não mais seja perturbado, e nunca mais os filhos da iniqüidade o aflijam, como dantes,', 1, CURRENT_TIMESTAMP, false),
(10, 7, 11, 'e como desde o dia em que ordenei que houvesse juízes sobre o meu povo Israel. A ti, porém, darei descanso de todos os teus inimigos. Também o Senhor te declara que ele te fará casa.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 12, 'Quando teus dias forem completos, e vieres a dormir com teus pais, então farei levantar depois de ti um dentre a tua descendência, que sair das tuas entranhas, e estabelecerei o seu reino.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 13, 'Este edificará uma casa ao meu nome, e eu estabelecerei para sempre o trono do seu reino.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 14, 'Eu lhe serei pai, e ele me será filho. E, se vier a transgredir, castigá-lo-ei com vara de homens, e com açoites de filhos de homens;', 1, CURRENT_TIMESTAMP, false),
(10, 7, 15, 'mas não retirarei dele a minha benignidade como a retirei de Saul, a quem tirei de diante de ti.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 16, 'A tua casa, porém, e o teu reino serão firmados para sempre diante de ti; teu trono será estabelecido para sempre.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 17, 'Conforme todas estas palavras, e conforme toda esta visão, assim falou Natã a Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 18, 'Então entrou o rei Davi, e sentou-se perante o Senhor, e disse: Quem sou eu, Senhor Jeová, e que é a minha casa, para me teres trazido até aqui?', 1, CURRENT_TIMESTAMP, false),
(10, 7, 19, 'E isso ainda foi pouco aos teus olhos, Senhor Jeová, senão que também falaste da casa do teu servo para tempos distantes; e me tens mostrado gerações futuras, ó Senhor Jeová?', 1, CURRENT_TIMESTAMP, false),
(10, 7, 20, 'Que mais te poderá dizer Davi. pois tu conheces bem o teu servo, ó Senhor Jeová.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 21, 'Por causa da tua palavra, e segundo o teu coração, fizeste toda esta grandeza, revelando-a ao teu servo.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 22, 'Portanto és grandioso, ó Senhor Jeová, porque ninguém há semelhante a ti, e não há Deus senão tu só, segundo tudo o que temos ouvido com os nossos ouvidos.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 23, 'Que outra nação na terra é semelhante a teu povo Israel, a quem tu, ó Deus, foste resgatar para te ser povo, para te fazeres um nome, e para fazeres a seu favor estas grandes e terríveis coisas para a tua terra, diante do teu povo, que tu resgataste para ti do Egito, desterrando nações e seus deuses?', 1, CURRENT_TIMESTAMP, false),
(10, 7, 24, 'Assim estabeleceste o teu povo Israel por teu povo para sempre, e tu, Senhor, te fizeste o seu Deus.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 25, 'Agora, pois, o Senhor Jeová, confirma para sempre a palavra que falaste acerca do teu servo e acerca da sua casa, e faze como tens falado,', 1, CURRENT_TIMESTAMP, false),
(10, 7, 26, 'para que seja engrandecido o teu nome para sempre, e se diga: O Senhor dos exércitos é Deus sobre Israel; e a casa do teu servo será estabelecida diante de ti.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 27, 'Pois tu, Senhor dos exércitos, Deus de Israel, fizeste uma revelação ao teu servo, dizendo: Edificar-te-ei uma casa. Por isso o teu servo se animou a fazer-te esta oração.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 28, 'Agora, pois, Senhor Jeová, tu és Deus, e as tuas palavras são verdade, e tens prometido a teu servo este bem.', 1, CURRENT_TIMESTAMP, false),
(10, 7, 29, 'Sê, pois, agora servido de abençoar a casa do teu servo, para que subsista para sempre diante de ti; pois tu, ó Senhor Jeová, o disseste; e com a tua bênção a casa do teu servo será, abençoada para sempre.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 1, 'Sucedeu depois disso que Davi derrotou os filisteus, e os sujeitou; e Davi tomou a Metegue-Ama das mãos dos filisteus.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 2, 'Também derrotou os moabitas, e os mediu com cordel, fazendo-os deitar por terra; e mediu dois cordéis para os matar, e um cordel inteiro para os deixar com vida. Ficaram assim os moabitas por servos de Davi, pagando-lhe tributos.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 3, 'Davi também derrotou a Hadadézer, filho de Reobe, rei de Zobá, quando este ia estabelecer o seu domínio sobre o rio Eufrates.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 4, 'E tomou-lhe Davi mil e setecentos cavaleiros e vinte mil homens de infantaria; e Davi jarretou a todos os cavalos dos carros, reservando apenas cavalos para cem carros.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 5, 'Os sírios de Damasco vieram socorrer a Hadadézer, rei de Zobá, mas Davi matou deles vinte e dois mil homens.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 6, 'Então Davi pôs guarnições em Síria de Damasco, e os sírios ficaram por servos de Davi, pagando-lhe tributos. E o Senhor lhe dava a vitória por onde quer que ia.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 7, 'E Davi tomou os escudos de ouro que os servos de Hadadézer usavam, e os trouxe para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 8, 'De Betá e de Berotai, cidades de Hadadézer, o rei Davi tomou grande quantidade de bronze.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 9, 'Quando Toí, rei de Hamate, ouviu que Davi ferira todo o exército de Hadadézer,', 1, CURRENT_TIMESTAMP, false),
(10, 8, 10, 'mandou-lhe seu filho Jorão para saudá-lo, e para felicitá-lo por haver pelejado contra Hadadézer e o haver derrotado; pois Hadadézer de contínuo fazia guerra a Toí. E Jorão trouxe consigo vasos de prata de ouro e de bronze,', 1, CURRENT_TIMESTAMP, false),
(10, 8, 11, 'os quais o rei Davi consagrou ao Senhor, como já havia consagrado a prata e o ouro de todas as nações que sujeitara.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 12, 'da Síria, de Moabe, dos amonitas, dos filisteus, de Amaleque e dos despojos de Hadadézer, filho de Reobe, rei de Zobá.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 13, 'Assim Davi ganhou nome para si. E quando voltou, matou no Vale do Sal a dezoito mil edomitas.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 14, 'E pôs guarnições em Edom; pô-las em todo o Edom, e todos os edomitas tornaram-se servos de Davi. E o Senhor lhe dava a vitória por onde quer que ia.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 15, 'Reinou, pois, Davi sobre todo o Israel, e administrava a justiça e a eqüidade a todo o seu povo.', 1, CURRENT_TIMESTAMP, false),
(10, 8, 16, 'Joabe, filho de Zeruia, estava sobre o exército; Jeosafá, filho de Ailude, era cronista;', 1, CURRENT_TIMESTAMP, false),
(10, 8, 17, 'Zadoque, filho de Aitube, e Aimeleque, filho de Abiatar, eram sacerdotes; Seraías era escrivão;', 1, CURRENT_TIMESTAMP, false),
(10, 8, 18, 'Benaías, filho de Jeoiada, tinha o cargo dos quereteus e peleteus; e os filhos de Davi eram ministros de estado.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 1, 'Disse Davi: Resta ainda alguém da casa de Saul, para que eu use de benevolência para com ele por amor de Jônatas?', 1, CURRENT_TIMESTAMP, false),
(10, 9, 2, 'E havia um servo da casa de Saul, cujo nome era Ziba; e o chamaram à presença de Davi. perguntou-lhe o rei: Tu és Ziba? Respondeu ele: Teu servo!', 1, CURRENT_TIMESTAMP, false),
(10, 9, 3, 'Prosseguiu o rei: Não há ainda alguém da casa de Saul para que eu possa usar com ele da benevolência de Deus? Então disse Ziba ao rei: Ainda há um filho de Jônatas, aleijado dos pés.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 4, 'Perguntou-lhe o rei: Onde está. Respondeu Ziba ao rei: Está em casa de Maquir, filho de Amiel, em Lo-Debar.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 5, 'Então mandou o rei Davi, e o tomou da casa de Maquir, filho de Amiel, em Lo-Debar.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 6, 'E Mefibosete, filho de Jônatas, filho de Saul, veio a Davi e, prostrando-se com o rosto em terra, lhe fez reverência. E disse Davi: Mefibosete! Respondeu ele: Eis aqui teu servo.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 7, 'Então lhe disse Davi: Não temas, porque de certo usarei contigo de benevolência por amor de Jônatas, teu pai, e te restituirei todas as terras de Saul, teu pai; e tu sempre comerás à minha mesa.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 8, 'Então Mefibosete lhe fez reverência, e disse: Que é o teu servo, para teres olhado para um cão morto tal como eu?', 1, CURRENT_TIMESTAMP, false),
(10, 9, 9, 'Então chamou Davi a Ziba, servo de Saul, e disse-lhe: Tudo o que pertencia a Saul, e a toda a sua casa, tenho dado ao filho de teu senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 10, 'Cultivar-lhe-ás, pois, a terra, tu e teus filhos, e teus servos; e recolherás os frutos, para que o filho de teu senhor tenha pão para comer; mas Mefibosete, filho de teu senhor, comerá sempre à minha mesa. Ora, tinha Ziba quinze filhos e vinte servos.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 11, 'Respondeu Ziba ao rei: Conforme tudo quanto meu senhor, o rei, manda a seu servo, assim o fará ele. Disse o rei: Quanto a Mefibosete, ele comerá à minha mesa como um dos filhos do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 12, 'E tinha Mefibosete um filho pequeno, cujo nome era Mica. E todos quantos moravam em casa de Ziba eram servos de Mefibosete.', 1, CURRENT_TIMESTAMP, false),
(10, 9, 13, 'Morava, pois, Mefibosete em Jerusalém, porquanto sempre comia à mesa do rei. E era coxo de ambos os pés.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 1, 'Depois disto morreu o rei dos amonitas, e seu filho Hanum reinou em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 2, 'Então disse Davi: usarei de benevolência para com Hanum, filho de Naás, como seu pai usou de benevolência para comigo. Davi, pois, enviou os seus servos para o consolar acerca de seu pai; e foram os servos de Davi à terra dos amonitas.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 3, 'Então disseram os príncipes dos amonitas a seu senhor, Hanum: Pensas, porventura, que foi para honrar teu pai que Davi te enviou consoladores? Não te enviou antes os seus servos para reconhecerem esta cidade e para a espiarem, a fim de transtorná-la?', 1, CURRENT_TIMESTAMP, false),
(10, 10, 4, 'Pelo que Hanum tomou os servos de Davi, rapou-lhes metade da barba, cortou-lhes metade dos vestidos, até as nádegas, e os despediu.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 5, 'Quando isso foi dito a Davi, enviou ele mensageiros a encontrá-los, porque aqueles homens estavam sobremaneira envergonhados; e mandou dizer-lhes: Deixai-vos estar em Jericó, até que vos torne a crescer a barba, e então voltai.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 6, 'Vendo, pois, os amonitas que se haviam feito abomináveis para com Davi, enviaram e alugaram dos sírios de Bete-Reobe e dos sírios de Bete-Reobe e dos sírios de Sobá vinte mil homens de infantaria, e do rei de Maacá mil homens, e dos homens de Tobe doze mil.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 7, 'O que ouvindo Davi, enviou contra eles a Joabe com todo o exército dos valentes.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 8, 'E saíram os amonitas, e ordenaram a batalha a entrada da porta; mas os sírios de Zobá e de Reobe, e os homens de Tobe e de Maacá estavam à parte no campo.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 9, 'Vendo, pois, Joabe que a batalha estava preparada contra ele pela frente e pela retaguarda, escolheu alguns homens dentre a flor do exército de Israel, e formou-os em linha contra os sírios;', 1, CURRENT_TIMESTAMP, false),
(10, 10, 10, 'e entregou o resto do povo a seu irmão Abisai, para que o formasse em linha contra os amonitas.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 11, 'E disse-lhe: Se os sírios forem mais fortes do que eu, tu me virás em socorro; e se os amonitas forem mais fortes do que tu, eu irei em teu socorro.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 12, 'Tem bom ânimo, e sejamos corajosos pelo nosso povo, e pelas cidades de nosso Deus; e faça o Senhor o que bem lhe parecer.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 13, 'Então Joabe e o povo que estava com ele travaram a peleja contra os sírios; e estes fugiram diante dele.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 14, 'E, vendo os amonitas que os sírios fugiam, também eles fugiram de diante de Abisai, e entraram na cidade. Então Joabe voltou dos amonitas e veio para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 15, 'Os sírios, vendo que tinham sido derrotados diante de Israel, trataram de refazer-se.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 16, 'E Hadadézer mandou que viessem os sírios que estavam da outra banda do rio; e eles vieram a Helã, tendo à sua frente Sobaque, chefe do exército de Hadadézer.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 17, 'Davi, informado disto, ajuntou todo o Israel e, passando o Jordão, foi a Helã; e os sírios se puseram em ordem contra Davi, e pelejaram contra ele.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 18, 'Os sírios, porém, fugiram de diante de Israel; e Davi matou deles os homens de setecentos carros, e quarenta mil homens de cavalaria; e feriu a Sobaque, general do exército, de sorte que ele morreu ali.', 1, CURRENT_TIMESTAMP, false),
(10, 10, 19, 'Vendo, pois, todos os reis, servos de Hadadézer, que estavam derrotados diante de Israel, fizeram paz com Israel, e o serviram. E os sírios não ousaram mais socorrer aos amonitas.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 1, 'Tendo decorrido um ano, no tempo em que os reis saem à guerra, Davi enviou Joabe, e com ele os seus servos e todo o Israel; e eles destruíram os amonitas, e sitiaram a Rabá. Porém Davi ficou em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 2, 'Ora, aconteceu que, numa tarde, Davi se levantou do seu leito e se pôs a passear no terraço da casa real; e do terraço viu uma mulher que se estava lavando; e era esta mulher mui formosa à vista.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 3, 'Tendo Davi enviado a indagar a respeito daquela mulher, disseram-lhe: Porventura não é Bate-Seba, filha de Eliã, mulher de Urias, o heteu?', 1, CURRENT_TIMESTAMP, false),
(10, 11, 4, 'Então Davi mandou mensageiros para trazê-la; e ela veio a ele, e ele se deitou com ela {pois já estava purificada da sua imundícia}; depois ela voltou para sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 5, 'A mulher concebeu; e mandou dizer a Davi: Estou grávida.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 6, 'Então Davi mandou dizer a Joabe: Envia-me Urias, o heteu. E Joabe o enviou a Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 7, 'Vindo, pois, Urias a Davi, este lhe perguntou como passava Joabe, e como estava o povo, e como ia a guerra.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 8, 'Depois disse Davi a Urias: Desce a tua casa, e lava os teus pés. E, saindo Urias da casa real, logo foi mandado após ele um presente do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 9, 'Mas Urias dormiu à porta da casa real, com todos os servos do seu senhor, e não desceu a sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 10, 'E o contaram a Davi, dizendo: Urias não desceu a sua casa. Então perguntou Davi a Urias: Não vens tu duma jornada? por que não desceste a tua casa?', 1, CURRENT_TIMESTAMP, false),
(10, 11, 11, 'Respondeu Urias a Davi: A arca, e Israel, e Judá estão em tendas; e Joabe, meu senhor, e os servos de meu senhor estão acampados ao relento; e entrarei eu na minha casa, para comer e beber, e para me deitar com minha mulher? Como vives tu, e como vive a tua alma, não farei tal coisa.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 12, 'Então disse Davi a Urias: Fica ainda hoje aqui, e amanhã te despedirei. Urias, pois, ficou em Jerusalém aquele dia e o seguinte.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 13, 'E Davi o convidou a comer e a beber na sua presença, e o embebedou; e à tarde saiu Urias a deitar-se na sua cama com os servos de seu senhor, porém não desceu a sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 14, 'Pela manhã Davi escreveu uma carta a Joabe, e mandou-lha por mão de Urias.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 15, 'Escreveu na carta: Ponde Urias na frente onde for mais renhida a peleja, e retirai-vos dele, para que seja ferido e morra.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 16, 'Enquanto Joabe sitiava a cidade, pôs Urias no lugar onde sabia que havia homens valentes.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 17, 'Quando os homens da cidade saíram e pelejaram contra Joabe, caíram alguns do povo, isto é, dos servos de Davi; morreu também Urias, o heteu.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 18, 'Então Joabe mandou dizer a Davi tudo o que sucedera na peleja;', 1, CURRENT_TIMESTAMP, false),
(10, 11, 19, 'e deu ordem ao mensageiro, dizendo: Quando tiveres acabado de contar ao rei tudo o que sucedeu nesta peleja,', 1, CURRENT_TIMESTAMP, false),
(10, 11, 20, 'caso o rei se encolerize, e te diga: Por que vos chegastes tão perto da cidade a pelejar. Não sabíeis vós que haviam de atirar do muro?', 1, CURRENT_TIMESTAMP, false),
(10, 11, 21, 'Quem matou a Abimeleque, filho de Jerubesete? Não foi uma mulher que lançou sobre ele, do alto do muro, a pedra superior dum moinho, de modo que morreu em Tebez? Por que chegastes tão perto do muro? Então dirás: Também morreu teu servo Urias, o heteu.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 22, 'Partiu, pois, o mensageiro e, tendo chegado, referiu a Davi tudo o que Joabe lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 23, 'Disse o mensageiro a Davi: Os homens ganharam uma vantagem sobre nós, e sairam contra nos ao campo; porém nos os repelimos até a entrada da porta.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 24, 'Então os flecheiros atiraram contra os teus servos desde o alto do muro, e morreram alguns servos do rei; e também morreu o teu servo Urias, o heteu.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 25, 'Disse Davi ao mensageiro: Assim dirás a Joabe: Não te preocupes com isso, pois a espada tanto devora este como aquele; aperta a tua peleja contra a cidade, e a derrota. Encoraja-o tu assim.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 26, 'Ouvindo, pois, a mulher de Urias que seu marido era morto, o chorou.', 1, CURRENT_TIMESTAMP, false),
(10, 11, 27, 'E, passado o tempo do luto, mandou Davi recolhê-la a sua casa: e ela lhe foi por mulher, e lhe deu um filho. Mas isto que Davi fez desagradou ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 1, 'O Senhor, pois, enviou Natã a Davi. E, entrando ele a ter com Davi, disse-lhe: Havia numa cidade dois homens, um rico e outro pobre.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 2, 'O rico tinha rebanhos e manadas em grande número;', 1, CURRENT_TIMESTAMP, false),
(10, 12, 3, 'mas o pobre não tinha coisa alguma, senão uma pequena cordeira que comprara e criara; ela crescera em companhia dele e de seus filhos; do seu bocado comia, do seu copo bebia, e dormia em seu regaço; e ele a tinha como filha.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 4, 'Chegou um viajante à casa do rico; e este, não querendo tomar das suas ovelhas e do seu gado para guisar para o viajante que viera a ele, tomou a cordeira do pobre e a preparou para o seu hóspede.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 5, 'Então a ira de Davi se acendeu em grande maneira contra aquele homem; e disse a Natã: Vive o Senhor, que digno de morte é o homem que fez isso.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 6, 'Pela cordeira restituirá o quádruplo, porque fez tal coisa, e não teve compaixão.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 7, 'Então disse Natã a Davi: Esse homem és tu! Assim diz o Senhor Deus de Israel: Eu te ungi rei sobre Israel, livrei-te da mão de Saul,', 1, CURRENT_TIMESTAMP, false),
(10, 12, 8, 'e te dei a casa de teu senhor, e as mulheres de teu senhor em teu seio; também te dei a casa de Israel e de Judá. E se isso fosse pouco, te acrescentaria outro tanto.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 9, 'Por que desprezaste a palavra do Senhor, fazendo o mal diante de seus olhos? A Urias, o heteu, mataste à espada, e a sua mulher tomaste para ser tua mulher; sim, a ele mataste com a espada dos amonitas.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 10, 'Agora, pois, a espada jamais se apartará da tua casa, porquanto me desprezaste, e tomaste a mulher de Urias, o heteu, para ser tua mulher.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 11, 'Assim diz o Senhor: Eis que suscitarei da tua própria casa o mal sobre ti, e tomarei tuas mulheres perante os teus olhos, e as darei a teu próximo, o qual se deitará com tuas mulheres à luz deste sol.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 12, 'Pois tu o fizeste em oculto; mas eu farei este negócio perante todo o Israel e à luz do sol.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 13, 'Então disse Davi a Natã: Pequei contra o Senhor. Tornou Natã a Davi: Também o Senhor perdoou o teu pecado; não morreras.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 14, 'Todavia, porquanto com este feito deste lugar a que os inimigos do Senhor blasfemem, o filho que te nasceu certamente morrerá.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 15, 'Então Natã foi para sua casa. Depois o Senhor feriu a criança que a mulher de Urias dera a Davi, de sorte que adoeceu gravemente.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 16, 'Davi, pois, buscou a Deus pela criança, e observou rigoroso jejum e, recolhendo-se, passava a noite toda prostrado sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 17, 'Então os anciãos da sua casa se puseram ao lado dele para o fazerem levantar-se da terra; porém ele não quis, nem comeu com eles.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 18, 'Ao sétimo dia a criança morreu; e temiam os servos de Davi dizer-lhe que a criança tinha morrido; pois diziam: Eis que, sendo a criança ainda viva, lhe falávamos, porém ele não dava ouvidos à nossa voz; como, pois, lhe diremos que a criança morreu? Poderá cometer um desatino.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 19, 'Davi, porém, percebeu que seus servos cochichavam entre si, e entendeu que a criança havia morrido; pelo que perguntou a seus servos: Morreu a criança? E eles responderam: Morreu.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 20, 'Então Davi se levantou da terra, lavou-se, ungiu-se, e mudou de vestes; e, entrando na casa do Senhor, adorou. Depois veio a sua casa, e pediu o que comer; e lho deram, e ele comeu.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 21, 'Então os seus servos lhe disseram: Que é isso que fizeste? pela criança viva jejuaste e choraste; porém depois que a criança morreu te levantaste e comeste.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 22, 'Respondeu ele: Quando a criança ainda vivia, jejuei e chorei, pois dizia: Quem sabe se o Senhor não se compadecerá de mim, de modo que viva a criança?', 1, CURRENT_TIMESTAMP, false),
(10, 12, 23, 'Todavia, agora que é morta, por que ainda jejuaria eu? Poderei eu fazê-la voltar? Eu irei para ela, porém ela não voltará para mim.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 24, 'Então consolou Davi a Bate-Seba, sua mulher, e entrou, e se deitou com ela. E teve ela um filho, e Davi lhe deu o nome de Salomão. E o Senhor o amou;', 1, CURRENT_TIMESTAMP, false),
(10, 12, 25, 'e mandou, por intermédio do profeta Natã, dar-lhe o nome de Jedidias, por amor do Senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 26, 'Ora, pelejou Joabe contra Rabá, dos amonitas, e tomou a cidade real.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 27, 'Então mandou Joabe mensageiros a Davi, e disse: Pelejei contra Rabá, e já tomei a cidade das águas.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 28, 'Ajunta, pois, agora o resto do povo, acampa contra a cidade e toma-a, para que eu não a tome e seja o meu nome aclamado sobre ela.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 29, 'Então Davi ajuntou todo o povo, e marchou para Rabá; pelejou contra ela, e a tomou.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 30, 'Também tirou a coroa da cabeça do seu rei; e o peso dela era de um talento de ouro e havia nela uma pedra preciosa; e foi posta sobre a cabeça de Davi, que levou da cidade mui grande despojo.', 1, CURRENT_TIMESTAMP, false),
(10, 12, 31, 'E, trazendo os seus habitantes, os pôs a trabalhar com serras, trilhos de ferro, machados de ferro, e em fornos de tijolos; e assim fez a todas as cidades dos amonitas. Depois voltou Davi e todo o povo para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 1, 'Ora, Absalão, filho de Davi, tinha uma irmã formosa, cujo nome era Tamar; e sucedeu depois de algum tempo que Amnom, filho de Davi enamorou-se dela.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 2, 'E angustiou-se Amnom, até adoecer, por amar, sua irmã; pois era virgem, e parecia impossível a Amnom fazer coisa alguma com ela.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 3, 'Tinha, porém, Amnom um amigo, cujo nome era Jonadabe, filho de Siméia, irmão de Davi; e era Jonadabe homem mui sagaz.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 4, 'Este lhe perguntou: Por que tu de dia para dia tanto emagreces, ó filho do rei? não mo dirás a mim? Então lhe respondeu Amnom: Amo a Tamar, irmã de Absalão, meu irmão.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 5, 'Tornou-lhe Jonadabe: Deita-te na tua cama, e finge-te doente; e quando teu pai te vier visitar, dize-lhe: Peço-te que minha irmã Tamar venha dar-me de comer, preparando a comida diante dos meus olhos, para que eu veja e coma da sua mão.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 6, 'Deitou-se, pois, Amnom, e fingiu-se doente. Vindo o rei visitá-lo, disse-lhe Amnom: Peço-te que minha irmã Tamar venha e prepare dois bolos diante dos meus olhos, para que eu coma da sua mão.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 7, 'Mandou, então, Davi a casa, a dizer a Tamar: Vai a casa de Amnom, teu irmão, e faze-lhe alguma comida.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 8, 'Foi, pois, Tamar a casa de Amnom, seu irmão; e ele estava deitado. Ela tomou massa e, amassando-a, fez bolos e os cozeu diante dos seus olhos.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 9, 'E tomou a panela, e os tirou diante dele; porém ele recusou comer. E disse Amnom: Fazei retirar a todos da minha presença. E todos se retiraram dele.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 10, 'Então disse Amnom a Tamar: Traze a comida a câmara, para que eu coma da tua mão. E Tamar, tomando os bolos que fizera, levou-os à câmara, ao seu irmão Amnom.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 11, 'Quando lhos chegou, para que ele comesse, Amnom pegou dela, e disse-lhe: Vem, deita-te comigo, minha irmã.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 12, 'Ela, porém, lhe respondeu: Não, meu irmão, não me forces, porque não se faz assim em Israel; não faças tal loucura.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 13, 'Quanto a mim, para onde levaria o meu opróbrio? E tu passarias por um dos insensatos em Israel. Rogo-te, pois, que fales ao rei, porque ele não me negará a ti.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 14, 'Todavia ele não quis dar ouvidos à sua voz; antes, sendo mais forte do que ela, forçou-a e se deitou com ela.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 15, 'Depois sentiu Amnom grande aversão por ela, pois maior era a aversão que se sentiu por ela do que o amor que lhe tivera. E disse-lhe Amnom: Levanta-te, e vai-te.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 16, 'Então ela lhe respondeu: Não há razão de me despedires; maior seria este mal do que o outro já me tens feito. Porém ele não lhe quis dar ouvidos,', 1, CURRENT_TIMESTAMP, false),
(10, 13, 17, 'mas, chamando o moço que o servia, disse-lhe: Deita fora a esta mulher, e fecha a porta após ela.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 18, 'Ora, trazia ela uma túnica talar; porque assim se vestiam as filhas virgens dos reis. Então o criado dele a deitou fora, e fechou a porta após ela.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 19, 'Pelo que Tamar, lançando cinza sobre a cabeça, e rasgando a túnica talar que trazia, pôs as mãos sobre a cabeça, e se foi andando e clamando.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 20, 'Mas Absalão, seu irmão, lhe perguntou: Esteve Amnom, teu irmão, contigo? Ora pois, minha irmã, cala-te; é teu irmão. Não se angustie o seu coração por isto. Assim ficou Tamar, desolada, em casa de Absalão, seu irmão.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 21, 'Quando o rei Davi ouviu todas estas coisas, muito se lhe acendeu a ira.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 22, 'Absalão, porém, não falou com Amnom, nem mal nem bem, porque odiava a Amnom por ter ele forçado a Tamar, sua irmã.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 23, 'Decorridos dois anos inteiros, tendo Absalão tosquiadores em Baal-Hazor, que está junto a Efraim, convidou todos os filhos do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 24, 'Foi, pois, Absalão ter com o rei, e disse: Eis que agora o teu servo faz a tosquia. Peço que o rei e os seus servos venham com o teu servo.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 25, 'O rei, porém, respondeu a Absalão: Não, meu filho, não vamos todos, para não te sermos pesados. Absalão instou com ele; todavia ele não quis ir, mas deu-lhe a sua benção.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 26, 'Disse-lhe Absalão: Ao menos, deixa ir conosco Amnom, meu irmão. O rei, porém, lhe perguntou: Para que iria ele contigo?', 1, CURRENT_TIMESTAMP, false),
(10, 13, 27, 'Mas como Absalão instasse com o rei, este deixou ir com ele Amnom, e os demais filhos do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 28, 'Ora, Absalão deu ordem aos seus servos, dizendo: Tomai sentido; quando o coração de Amnom estiver alegre do vinho, e eu vos disser: Feri a Amnom; então matai-o. Não tenhais medo; não sou eu quem vo-lo ordenou? Esforçai-vos, e sede valentes.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 29, 'E os servos de Absalão fizeram a Amnom como Absalão lhes havia ordenado. Então todos os filhos do rei se levantaram e, montando cada um no seu mulo, fugiram.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 30, 'Enquanto eles ainda estavam em caminho, chegou a Davi um rumor, segundo o qual se dizia: Absalão matou todos os filhos do rei; nenhum deles ficou.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 31, 'Então o rei se levantou e, rasgando as suas vestes, lançou-se por terra; da mesma maneira todos os seus servos que lhe assistiam rasgaram as suas vestes.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 32, 'Mas Jonadabe, filho de Siméia, irmão de Davi, disse-lhe: Não presuma o meu senhor que mataram todos os mancebos filhos do rei, porque só morreu Amnom; porque assim o tinha resolvido fazer Absalão, desde o dia em que ele forçou a Tamar, sua irmã.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 33, 'Não se lhe meta, pois, agora no coração ao rei meu senhor o pensar que morreram todos os filhos do rei; porque só morreu Amnom.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 34, 'Absalão, porém, fugiu. E o mancebo que estava de guarda, levantando os olhos, orou, e eis que vinha muito povo pelo caminho por detrás dele, ao lado do monte.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 35, 'Então disse Jonadabe ao rei: Eis aí vêm os filhos do rei; conforme a palavra de teu servo, assim sucedeu.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 36, 'Acabando ele de falar, chegaram os filhos do rei e, levantando a sua voz, choraram; e também o rei e todos os seus servos choraram amargamente.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 37, 'Absalão, porém, fugiu, e foi ter com Talmai, filho de Amiur, rei de Gesur. E Davi pranteava a seu filho todos os dias.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 38, 'Tendo Absalão fugido para Gesur, esteve ali três anos.', 1, CURRENT_TIMESTAMP, false),
(10, 13, 39, 'Então o rei Davi sentiu saudades de Absalão, pois já se tinha consolado acerca da morte de Amnom.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 1, 'Percebendo Joabe, filho de Zeruia, que o coração do rei estava inclinado para Absalão,', 1, CURRENT_TIMESTAMP, false),
(10, 14, 2, 'mandou a Tecoa trazer de lá uma mulher sagaz, e disse-lhe: Ora, finge que estás de nojo; põe vestidos de luto, não te unjas com óleo, e faze-te como uma mulher que há muitos dias chora algum morto;', 1, CURRENT_TIMESTAMP, false),
(10, 14, 3, 'vai ter com o rei, e fala-lhe desta maneira. Então Joabe lhe pôs as palavras na boca.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 4, 'A mulher tecoíta, pois, indo ter com o rei e prostrando-se com o rosto em terra, fez-lhe uma reverência e disse: Salva-me, o rei.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 5, 'Ao que lhe perguntou o rei: Que tens? Respondeu ela: Na verdade eu sou viúva; morreu meu marido.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 6, 'Tinha a tua serva dois filhos, os quais tiveram uma briga no campo e, não havendo quem os apartasse, um feriu ao outro, e o matou.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 7, 'E eis que toda a parentela se levantou contra a tua serva, dizendo: Dá-nos aquele que matou a seu irmão, para que o matemos pela vida de seu irmão, a quem ele matou, de modo que exterminemos também o herdeiro. Assim apagarão a brasa que me ficou, de sorte a não deixarem a meu marido nem nome, nem remanescente sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 8, 'Então disse o rei à mulher: Vai para tua casa, e eu darei ordem a teu respeito.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 9, 'Respondeu a mulher tecoíta ao rei: A iniqüidade, ó rei meu senhor, venha sobre mim e sobre a casa de meu pai; e fique inculpável o rei e o seu trono.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 10, 'Tornou o rei: Quem falar contra ti, traze-mo a mim, e nunca mais te tocará.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 11, 'Disse ela: Ora, lembre-se o rei do Senhor seu Deus, para que o vingador do sangue não prossiga na destruição, e não extermine a meu filho. Então disse ele: Vive o Senhor, que não há de cair no chão nem um cabelo de teu filho.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 12, 'Então disse a mulher: Permite que a tua serva fale uma palavra ao rei meu senhor. Respondeu ele: Fala.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 13, 'Ao que disse a mulher: Por que, pois, pensas tu tal coisa contra o povo de Deus? Pois, falando o rei esta palavra, fica como culpado, visto que o rei não torna a trazer o seu desterrado.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 14, 'Porque certamente morreremos, e serereos como águas derramadas na terra, que não se podem ajuntar mais; Deus, todavia, não tira a vida, mas cogita meios para que não fique banido dele o seu desterrado.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 15, 'E se eu agora vim falar esta palavra ao rei meu senhor, e porque o povo me atemorizou; pelo que dizia a tua serva: Falarei, pois, ao rei; porventura fará o rei segundo a palavra da sua serva.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 16, 'Porque o rei ouvirá, para livrar a sua serva da mão do homem que intenta exterminar da herança de Deus tanto a mim como a meu filho.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 17, 'Dizia mais a tua serva: Que a palavra do rei meu senhor me dê um descanso; porque como o anjo de Deus é o rei, meu senhor, para discernir o bem e o mal; e o Senhor teu Deus seja contigo.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 18, 'Então respondeu o rei à mulher: Peço-te que não me encubras o que eu te perguntar. Tornou a mulher: Fale agora o rei meu senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 19, 'Perguntou, pois, o rei: Não é verdade que a mão de Joabe está contigo em tudo isso? Respondeu a mulher: Vive a tua alma, ó rei meu senhor, que ninguém se poderá desviar, nem para a direita nem para a esquerda, de tudo quanto diz o rei meu senhor; porque Joabe, teu servo, é quem me deu ordem, e foi ele que pôs na boca da tua serva todas estas palavras;', 1, CURRENT_TIMESTAMP, false),
(10, 14, 20, 'para mudar a feição do negócio é que Joabe, teu servo, fez isso. Sábio, porém, é meu senhor, conforme a sabedoria do anjo de Deus, para entender tudo o que há na terra.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 21, 'Então o rei disse a Joabe: Eis que faço o que pedes; vai, pois, e faze voltar o mancebo Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 22, 'Então Joabe se prostrou com o rosto em terra e, fazendo uma reverência, abençoou o rei; e disse Joabe: Hoje conhece o teu servo que achei graça aos teus olhos, ó rei meu senhor, porque o rei fez segundo a palavra do teu servo.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 23, 'Levantou-se, pois, Joabe, foi a Gesue e trouxe Absalão para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 24, 'E disse o rei: Torne ele para sua casa, mas não venha à minha presença. Tornou, pois, Absalão para sua casa, e não foi à presença do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 25, 'Não havia em todo o Israel homem tão admirável pela sua beleza como Absalão; desde a planta do pé até o alto da cabeça não havia nele defeito algum.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 26, 'E, quando ele cortava o cabelo, o que costumava fazer no fim de cada ano, porquanto lhe pesava muito, o peso do cabelo era de duzentos siclos, segundo o peso real.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 27, 'Nasceram a Absalão três filhos, e uma filha cujo nome era Tamar; e esta era mulher formosa à vista.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 28, 'Assim ficou Absalão dois anos inteiros em Jerusalém, sem ver a face do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 29, 'Então Absalão mandou chamar Joabe, para o enviar ao rei; porém Joabe não quis vir a ele. Mandou chamá-lo segunda vez, mas ele não quis vir.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 30, 'Pelo que disse aos seus servos: Vede ali o campo de Joabe pegado ao meu, onde ele tem cevada; ide, e ponde-lhe fogo. E os servos de Absalão puseram fogo ao campo:', 1, CURRENT_TIMESTAMP, false),
(10, 14, 31, 'Então Joabe se levantou, e veio ter com Absalão, em casa, e lhe perguntou: Por que os teus servos puseram fogo ao meu campo.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 32, 'Respondeu Absalão a Joabe: Eis que enviei a ti, dizendo: Vem cá, para que te envie ao rei, a dizer-lhe: Para que vim de Gesur? Melhor me fora estar ainda lá. Agora, pois, veja eu a face do rei; e, se há em mim alguma culpa, que me mate.', 1, CURRENT_TIMESTAMP, false),
(10, 14, 33, 'Foi, pois, Joabe à presença do rei, e lho disse. Então o rei chamou Absalão, e ele entrou à presença do rei, e se prostrou com o rosto em terra diante do rei; e o rei beijou Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 1, 'Aconteceu depois disso que Absalão adquiriu para si um carro e cavalos, e cinqüenta homens que corressem adiante dele.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 2, 'E levantando-se Absalão cedo, parava ao lado do caminho da porta; e quando algum homem tinha uma demanda para, vir ao rei a juízo, Absalão o chamava a si e lhe dizia: De que cidade és tu? E, dizendo ele: De tal tribo de Israel é teu servo;', 1, CURRENT_TIMESTAMP, false),
(10, 15, 3, 'Absalão lhe dizia: Olha, a tua causa é boa e reta, porém não há da parte do rei quem te ouça.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 4, 'Dizia mais Absalão: Ah, quem me dera ser constituído juiz na terra! para que viesse ter comigo todo homem que tivesse demanda ou questão, e eu lhe faria justiça.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 5, 'Sucedia também que, quando alguém se chegava a ele para lhe fazer reverência, ele estendia a mão e, pegando nele o beijava.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 6, 'Assim fazia Absalão a todo o Israel que vinha ao rei para juízo; desse modo Absalão furtava o coração dos homens de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 7, 'Aconteceu, ao cabo de quatro anos, que Absalão disse ao rei: Deixa-me ir pagar em Hebrom o voto que fiz ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 8, 'Porque, morando eu em Gesur, na Síria, fez o teu servo um voto, dizendo: Se o Senhor, na verdade, me fizer tornar a Jerusalém, servirei ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 9, 'Então lhe disse o rei: Vai em paz. Levantou-se, pois, e foi para Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 10, 'Absalão, porém, enviou emissários por todas as tribos de Israel, dizendo: Quando ouvirdes o som da trombeta, direis: Absalão reina em Hebrom.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 11, 'E de Jerusalém foram com Absalão duzentos homens que tinham sido convidados; mas iam na sua simplicidade, pois nada sabiam daquele desígnio.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 12, 'Também Absalão, enquanto oferecia os seus sacrifícios, mandou vir da cidade de Siló, Aitofel, o gilonita, conselheiro de Davi. E a conspiração tornava-se poderosa, crescendo cada vez mais o número do povo que estava com Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 13, 'Então veio um mensageiro a Davi, dizendo: O coração de todo o Israel vai após Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 14, 'Disse, pois, Davi a todos os seus servos que estavam com ele em Jerusalém: Levantai-vos, e fujamos, porque doutra forma não poderemos escapar diante de Absalão. Apressai-vos a sair; não seja caso que ele nos apanhe de súbito, e lance sobre nós a ruína, e fira a cidade ao fio da espada.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 15, 'Então os servos do rei lhe disseram: Eis aqui os teus servos para tudo quanto determinar o rei, nosso senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 16, 'Assim saiu o rei, com todos os de sua casa, deixando, porém, dez concubinas para guardarem a casa.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 17, 'Tendo, pois, saído o rei com todo o povo, pararam na última casa:', 1, CURRENT_TIMESTAMP, false),
(10, 15, 18, 'E todos os seus servos iam ao seu lado; mas todos os quereteus, e todos os peleteus, e todos os giteus, seiscentos homens que o seguiram de Gate, caminhavam adiante do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 19, 'Disse o rei a Itai, o giteu: Por que irias tu também conosco? Volta e fica-te com o rei, porque és estrangeiro e exilado; torna a teu lugar.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 20, 'Ontem vieste, e te levaria eu hoje conosco a vaguear? Pois eu vou para onde puder ir; volta, e lei, e contigo teus irmãos; a misericórdia e a fidelidade sejam contigo.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 21, 'Respondeu, porém, Itai ao rei, e disse: Vive o Senhor, e vive o rei meu senhor, que no lugar em que estiver o rei meu senhor, seja para morte, seja para vida, aí estará também o eu servo.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 22, 'Então disse Davi a Itai: Vai, pois, e passa adiante. Assim passou Itai, o giteu, e todos os seus homens, e todos os pequeninos que havia com ele.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 23, 'Toda a terra chorava em alta voz, enquanto todo o povo passava; e o rei atravessou o ribeiro de Cedrom, e todo o povo caminhava na direção do deserto.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 24, 'E chegou Abiatar; e veio também Zadoque, e com ele todos os levitas que levavam a arca do pacto de Deus; e puseram ali a arca de Deus, até que todo o povo acabou de sair da cidade.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 25, 'Então disse o rei a Zadoque: Torna a levar a arca de Deus à cidade; pois, se eu achar graça aos olhos do Senhor, ele me fará voltar para lá, e me deixará ver a arca e a sua habitação.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 26, 'Se ele, porém, disser: Não tenho prazer em ti; eis-me aqui, faça a mim o que bem lhe parecer.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 27, 'Disse mais o rei a Zadoque, o sacerdote: Não és tu porventura vidente? volta, pois, para a cidade em paz, e contigo também teus dois filhos, Aimaaz, teu filho, e Jônatas, filho de Abiatar.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 28, 'Vede eu me demorarei nos vaus do deserto até que tenha notícias da vossa parte.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 29, 'Zadoque, pois, e Abiatar tornaram a levar para Jerusalém a arca de Deus, e ficaram ali.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 30, 'Mas Davi, subindo pela encosta do monte das Oliveiras, ia chorando; tinha a cabeça coberta, e caminhava com os pés descalços. Também todo o povo que ia com ele tinha a cabeça coberta, e subia chorando sem cessar.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 31, 'Então disseram a Davi: Aitofel está entre os que conspiraram com Absalão. Pelo que disse Davi: Ó Senhor, torna o conselho de Aitofel em loucura!', 1, CURRENT_TIMESTAMP, false),
(10, 15, 32, 'Ora, aconteceu que, chegando Davi ao cume, onde se costumava adorar a Deus, Husai, o arquita, veio encontrar-se com ele, com a roupa rasgada e a cabeça coberta de terra.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 33, 'Disse-lhe Davi: Se fores comigo, ser-me-ás pesado;', 1, CURRENT_TIMESTAMP, false),
(10, 15, 34, 'porém se voltares para a cidade, e disseres a Absalão: Eu serei, ó rei, teu servo; como fui dantes servo de teu pai, assim agora serei teu servo; dissipar-me-ás então a conselho de Aitofel.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 35, 'E não estão ali contigo Zadoque e Abiatar, sacerdotes? Portanto, tudo o que ouvires da casa do rei lhes dirás.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 36, 'Eis que estão também ali com eles seus dois filhos, Aimaaz, filho de Zadoque, e Jônatas, filho de Abiatar; por eles me avisareis de tudo o que ouvirdes.', 1, CURRENT_TIMESTAMP, false),
(10, 15, 37, 'Husai, pois, amigo de Davi, voltou para a cidade. E Absalão entrou em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 1, 'Tendo Davi passado um pouco além do cume, eis que Ziba, o moço de Mefibosete, veio encontrar-se com ele, com um par de jumentos albardados, e sobre eles duzentos pães, cem cachos de passas, e cem de frutas de verão e um odre de vinho.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 2, 'Perguntou, pois, o rei a Ziba: Que pretendes com isso? Respondeu Ziba: Os jumentos são para a casa do rei, para se montarem neles; e o pão e as frutas de verão para os moços comerem; e o vinho para os cansados no deserto beberem.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 3, 'Perguntou ainda o rei: E onde está o filho de teu senhor? Respondeu Ziba ao rei: Eis que permanece em Jerusalém, pois disse: Hoje a casa de Israel me restituirá o reino de meu pai.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 4, 'Então disse o rei a Ziba: Eis que tudo quanto pertencia a Mefibosete é teu. Ao que Ziba, inclinando-se, disse: Que eu ache graça aos teus olhos, ó rei meu senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 5, 'Tendo o rei Davi chegado a Baurim, veio saindo dali um homem da linhagem da casa de Saul, cujo nome era Simei, filho de Gêra; e, adiantando-se, proferia maldições.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 6, 'Também atirava pedras contra Davi e todos os seus servos, ainda que todo o povo e todos os valorosos iam à direita e à esquerda do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 7, 'E, amaldiçoando-o Simei, assim dizia: Sai, sai, homem sanguinário, homem de Belial!', 1, CURRENT_TIMESTAMP, false),
(10, 16, 8, 'O Senhor te deu agora a paga de todo o sangue da casa de Saul, em cujo lugar tens reinado; já entregou o Senhor o reino na mão de Absalão, teu filho; e eis-te agora na desgraça, pois és um homem sanguinário.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 9, 'Então Abisai, filho de Zeruia, disse ao rei: Por que esse cão morto amaldiçoaria ao rei meu senhor? Deixa-me passar e tirar-lhe a cabeça.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 10, 'Disse, porém, o rei: Que tenho eu convosco, filhos de Zeruia? Por ele amaldiçoar e por lhe ter dito o Senhor: Amaldiçoa a Davi; quem dirá: Por que assim fizeste?', 1, CURRENT_TIMESTAMP, false),
(10, 16, 11, 'Disse mais Davi a Abisai, e a todos os seus servos: Eis que meu filho, que saiu das minhas entranhas, procura tirar-me a vida; quanto mais ainda esse benjamita? Deixai-o; deixai que amaldiçoe, porque o Senhor lho ordenou.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 12, 'Porventura o Senhor olhará para a minha aflição, e me pagará com bem a maldição deste dia.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 13, 'Prosseguiam, pois, o seu caminho, Davi e os seus homens, enquanto Simei ia pela encosta do monte, defronte dele, caminhando e amaldiçoando, e atirava pedras contra ele, e levantava poeira.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 14, 'E o rei e todo o povo que ia com ele chegaram cansados ao Jordão; e ali descansaram.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 15, 'Absalão e todo o povo, os homens de Israel, vieram a Jerusalém; e Aitofel estava com ele.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 16, 'E chegando Husai, o arquita, amigo de Davi, a Absalão, disse-lhe: Viva o rei, viva o rei!', 1, CURRENT_TIMESTAMP, false),
(10, 16, 17, 'Absalão, porém, perguntou a Husai: E esta a tua benevolência para com o teu amigo? Por que não foste com o teu amigo?', 1, CURRENT_TIMESTAMP, false),
(10, 16, 18, 'Respondeu-lhe Husai: Não; pois aquele a quem o Senhor, e este povo, e todos os homens de Israel têm escolhido, dele serei e com ele ficarei.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 19, 'E, demais disto, a quem serviria eu? Porventura não seria a seu filho? como servi a teu pai, assim servirei a ti.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 20, 'Então disse Absalão a Aitofel: Dai o vosso conselho sobre o que devemos fazer.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 21, 'Respondeu Aitofel a Absalão: Entra às concubinas de teu pai, que ele deixou para guardarem a casa; e assim todo o Israel ouvirá que te fizeste aborrecível para com teu pai, e se fortalecerão as mãos de todos os que estão contigo.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 22, 'Estenderam, pois, para Absalão uma tenda no terraço; e entrou Absalão às concubinas de seu pai, à vista de todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 16, 23, 'E o conselho que Aitofel dava naqueles dias era como se o oráculo de Deus se consultara; tal era todo o conselho de Aitofel, tanto para com Davi como para Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 1, 'Disse mais Aitofel a Absalão: Deixa-me escolher doze mil homens, e me levantarei, e perseguirei a Davi esta noite.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 2, 'Irei sobre ele, enquanto está cansado, e fraco de mãos, e o espantarei: então fugirá todo o povo que está com ele. Ferirei tão-somente o rei;', 1, CURRENT_TIMESTAMP, false),
(10, 17, 3, 'e farei tornar a ti todo o povo, como uma noiva à casa do seu esposo; pois é a vida dum só homem que tu buscas; assim todo o povo estará em paz.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 4, 'E este conselho agradou a Absalão, e a todos os anciãos de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 5, 'Disse, porém, Absalão: Chamai agora a Husai, o arquita, e ouçamos também o que ele diz.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 6, 'Quando Husai chegou a Absalão, este lhe disse: Desta maneira falou Aitofel; faremos conforme a sua palavra? Se não, fala tu.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 7, 'Então disse Husai a Absalão: O conselho que Aitofel deu esta vez não é bom.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 8, 'Acrescentou Husai: Tu bem sabes que teu pai e os seus homens são valentes, e que estão com o espírito amargurado, como a ursa no campo, roubada dos seus cachorros; além disso teu pai é homem de guerra, e não passará a noite com o povo.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 9, 'Eis que agora está ele escondido nalguma cova, ou em qualquer outro lugar; e será que, caindo alguns no primeiro ataque, todo o que o ouvir dirá: Houve morticínio entre o povo que segue a Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 10, 'Então até o homem valente, cujo coração é como coração de leão, sem dúvida desmaiará; porque todo o Israel sabe que teu pai é valoroso, e que são valentes os que estão com ele.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 11, 'Eu, porém, aconselho que com toda a pressa se ajunte a ti todo o Israel, desde Dã até Berseba, em multidão como a areia do mar; e que tu em pessoa vás à peleja.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 12, 'Então iremos a ele, em qualquer lugar em que se achar, e desceremos sobre ele, como o orvalho cai sobre a terra; e não ficará dele e de todos os homens que estão com ele nem sequer um só.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 13, 'se ele, porém, se retirar para alguma cidade, todo o Israel trará cordas àquela cidade, e arrastá-la-emos até o ribeiro, até que não se ache ali nem uma só pedrinha', 1, CURRENT_TIMESTAMP, false),
(10, 17, 14, 'Então Absalão e todos os homens e Israel disseram: Melhor é o conselho de Husai, o arquita, do que o conselho de Aitofel: Porque assim o Senhor o ordenara, para aniquilar o bom conselho de Aitofel, a fim de trazer o mal sobre Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 15, 'Também disse Husai a Zadoque e a Abiatar, sacerdotes: Assim e assim aconselhou Aitofel a Absalão e aos anciãos de Israel; porém eu aconselhei assim e assim.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 16, 'Agora, pois, mandai apressadamente avisar a Davi, dizendo: Não passes esta noite nos vaus do deserto; mas passa sem falta à outra banda, para que não seja devorado o rei, e todo o povo que com ele está.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 17, 'Ora, Jônatas e Aimaaz estavam esperando junto a En-Rogel; e foi uma criada, e lhes avisou, para que eles fossem e o dissessem ao rei Davi; pois não deviam ser vistos entrando na cidade.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 18, 'Viu-os todavia um moço, e avisou a Absalão. Ambos, porém, partiram apressadamente, e entraram em casa de um homem, em Baurim, o qual tinha no pátio de sua casa um poço, para o qual eles desceram.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 19, 'E a mulher, tomando a tampa, colocou-a sobre a boca do poço, e espalhou grão triturado sobre ela; assim nada se soube.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 20, 'Chegando, pois, os servos de Absalão àquela casa, perguntaram à mulher: Onde estão Aimaaz e Jônatas? Respondeu-lhes a mulher: Já passaram a corrente das águas. E, havendo-os procurado sem os encontrarem, voltaram para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 21, 'Depois que eles partiram, Aimaaz e Jônatas, saindo do poço, foram e avisaram a Davi; e disseram-lhe: Levantai-vos, e passai depressa as águas, porque assim e assim aconselhou contra vós Aitofel.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 22, 'Então se levantou Davi e todo o povo que com ele estava, e passaram o Jordão; e ao raiar da manhã não faltava nem um só que não o tivesse passado.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 23, 'Vendo, pois, Aitofel que não se havia seguido o seu conselho, albardou o jumento e, partindo, foi para casa, para a sua cidade; e, tendo posto em ordem a sua casa, se enforcou e morreu; e foi sepultado na sepultura de seu pai.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 24, 'Então Davi veio a Maanaim; e Absalão passou o Jordão, ele e todos os homens de Israel com ele.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 25, 'E Absalão colocou Amasa em lugar de Joabe sobre o exército. Ora, Amasa era filho de um homem que se chamava Itra, o jizreelita, o qual entrara a Abigail, filha de Naás e irmã de Zeruia, mãe de Joabe.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 26, 'Israel e Absalão se acamparam na terra de Gileade.', 1, CURRENT_TIMESTAMP, false),
(10, 17, 27, 'Tendo Davi chegado a Maanaim, Sobi, filho de Naás, de Rabá dos filhos de Amom, e Maquir, filho de Amiel, de Lo-Debar, e Barzilai, o gileadita, de Rogelim,', 1, CURRENT_TIMESTAMP, false),
(10, 17, 28, 'tomaram camas, bacias e vasilhas de barro; trigo, cevada, farinha, grão tostado, favas, lentilhas e torradas;', 1, CURRENT_TIMESTAMP, false),
(10, 17, 29, 'mel, manteiga, ovelhas e queijos de vaca, e os trouxeram a Davi e ao povo que com ele estava, para comerem; pois diziam: O povo está faminto, cansado e sedento, no deserto.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 1, 'Então Davi contou o povo que tinha consigo, e pôs sobre ele chefes de mil e chefes de cem.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 2, 'E Davi enviou o exército, um terço sob o mando de Joabe, outro terço sob o mando de Abisai, filho de Zeruia, irmão de Joabe, e outro terço sob o mando de Itai, o giteu. E disse o rei ao povo: Eu também sairei convosco.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 3, 'Mas o povo respondeu: Não sairás; porque se fugirmos, eles não se importarão conosco; nem se importarão conosco ainda que morra metade de nós; porque tu vales por dez mil tais como nós. Melhor será que da cidade nos mandes socorro.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 4, 'Respondeu-lhes o rei: Farei o que vos parecer bem. E o rei se pôs ao lado da porta, e todo o povo saiu em centenas e em milhares.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 5, 'E o rei deu ordem a Joabe, a Abisai e a Itai, dizendo: Tratai brandamente, por amor de mim, o mancebo Absalão. E todo o povo ouviu quando o rei deu ordem a todos os chefes acerca de Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 6, 'Assim saiu o povo a campo contra Israel; e deu-se a batalha no bosque de Efraim.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 7, 'Ali o povo de Israel foi derrotado pelos servos de Davi; e naquele dia houve ali grande morticínio, de vinte mil homens.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 8, 'Pois a batalha se estendeu sobre a face de toda aquela terra, e o bosque consumiu mais gente naquele dia do que a espada.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 9, 'Por acaso Absalão se encontrou com os servos de Davi; e Absalão ia montado num mulo e, entrando o mulo debaixo dos espessos ramos de um grande carvalho, pegou-se a cabeça de Absalão no carvalho, e ele ficou pendurado entre o céu e a terra; e o mulo que estava debaixo dele passou adiante.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 10, 'um homem, vendo isso, contou-o a Joabe, dizendo: Eis que vi Absalão pendurado dum carvalho.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 11, 'Então disse Joabe ao homem que lho contara: Pois que o viste, por que não o derrubaste logo por terra? E eu te haveria dado dez siclos de prata e um cinto.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 12, 'Respondeu, porém, o homem a Joabe: Ainda que eu pudesse pesar nas minhas mãos mil siclos de prata, não estenderia a mão contra o filho do rei; pois bem ouvimos que o rei deu ordem a ti, e a Abisai, e a Itai, dizendo: Guardai-vos, cada um, de tocar no mancebo Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 13, 'E se eu tivesse procedido falsamente contra a sua vida, coisa nenhuma se esconderia ao rei, e tu mesmo te oporias a mim:', 1, CURRENT_TIMESTAMP, false),
(10, 18, 14, 'Então disse Joabe: Não posso demorar-me assim contigo aqui. E tomou na mão três dardos, e traspassou com eles o coração de Absalão, estando ele ainda vivo no meio do carvalho.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 15, 'E o cercaram dez mancebos, que levavam as armas de Joabe; e feriram a Absalão, e o mataram.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 16, 'Então tocou Joabe a buzina, e o povo voltou de perseguir a Israel; porque Joabe deteve o povo.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 17, 'E tomaram a Absalão e, lançando-o numa grande cova no bosque, levantaram sobre ele mui grande montão de pedras. E todo o Israel fugiu, cada um para a sua tenda.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 18, 'Ora, Absalão, quando ainda vivia, tinha feito levantar para si a coluna que está no vale do rei; pois dizia: Nenhum filho tenho para conservar a memória o meu nome. E deu o seu próprio nome àquela coluna, a qual até o dia de hoje se chama o Pilar de Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 19, 'Então disse Aimaaz, filho de Zadoque: Deixa-me correr, e anunciarei ao rei que o Senhor o vingou a mão e seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 20, 'Mas Joabe lhe disse: Tu não serás hoje o portador das novas; outro dia as levarás, mas hoje não darás a nova, porque é morto o filho do rei.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 21, 'Disse, porém, Joabe ao cuchita: Vai tu, e dize ao rei o que viste. O cuchita se inclinou diante de Joabe, e saiu correndo.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 22, 'Então prosseguiu Aimaaz, filho de Zadoque, e disse a Joabe: Seja o que for, deixa-me também correr após o cuchita. Respondeu Joabe: Para que agora correrias tu, meu filho, pois não receberias recompensa pelas novas?', 1, CURRENT_TIMESTAMP, false),
(10, 18, 23, 'seja o que for, disse Aimaaz, correrei. Disse-lhe, pois, Joabe: Corre. Então Aimaaz correu pelo caminho da planície, e passou adiante do cuchita.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 24, 'Ora, Davi estava sentado entre as duas portas; e a sentinela subiu ao terraço da porta junto ao muro e, levantando os olhos, viu um homem que corria só.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 25, 'Gritou, pois, a sentinela, e o disse ao rei. Respondeu o rei: Se vem só, é portador de novas. Vinha, pois, o mensageiro aproximando-se cada vez mais.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 26, 'Então a sentinela viu outro homem que corria, e gritou ao porteiro, e disse: Eis que lá vem outro homem correndo só. Então disse o rei: Também esse traz novas.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 27, 'Disse mais a sentinela: O correr do primeiro parece ser o correr de Aimaaz, filho de Zadoque. Então disse o rei: Este é homem de bem, e virá com boas novas.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 28, 'Gritou, pois, Aimaaz, e disse ao rei: Paz! E inclinou-se ao rei com o rosto em terra, e disse: Bendito seja o Senhor teu Deus, que entregou os homens que levantaram a mão contra o rei meu senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 29, 'Então perguntou o rei: Vai bem o mancebo Absalão? Respondeu Aimaaz: Quando Joabe me mandou a mim, o servo do rei, vi um grande alvoroço; porem não sei o que era.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 30, 'Disse-lhe o rei: Põe-te aqui ao lado. E ele se pôs ao lado, e esperou de pé.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 31, 'Nisso chegou o cuchita, e disse: Novas para o rei meu senhor. Pois que hoje o Senhor te vingou da mão de todos os que se levantaram contra ti.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 32, 'Então perguntou o rei ao cuchita: Vai bem o mancebo Absalão? Respondeu o cuchita: Sejam como aquele mancebo os inimigos do rei meu senhor, e todos os que se levantam contra ti para te fazerem mal.', 1, CURRENT_TIMESTAMP, false),
(10, 18, 33, 'Pelo que o rei ficou muito comovido e, subindo à sala que estava por cima da porta, pôs-se a chorar; e andando, dizia assim: Meu filho Absalão, meu filho, meu filho Absalão! quem me dera que eu morrera por ti, Absalão, meu filho, meu filho!', 1, CURRENT_TIMESTAMP, false),
(10, 19, 1, 'Disseram a Joabe: Eis que o rei está chorando e se lamentando por Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 2, 'Então a vitória se tornou naquele dia em tristeza para todo o povo, porque nesse dia o povo ouviu dizer: O rei está muito triste por causa de seu filho.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 3, 'E nesse dia o povo entrou furtivamente na cidade, como o faz quando, envergonhado, foge da peleja.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 4, 'Estava, pois, o rei com o rosto coberto, e clamava em alta voz: Meu filho Absalão, Absalão meu filho, meu filho!', 1, CURRENT_TIMESTAMP, false),
(10, 19, 5, 'Então entrou Joabe na casa onde estava o rei, e disse: Hoje envergonhaste todos os teus servos, que livraram neste dia a tua vida, a vida de teus filhos e filhas, e a vida de tuas mulheres e concubinas,', 1, CURRENT_TIMESTAMP, false),
(10, 19, 6, 'amando aos que te odeiam, e odiando aos que te amam. Porque hoje dás a entender que nada valem para ti nem chefes nem servos; pois agora entendo que se Absalão vivesse, e todos nós hoje fôssemos mortos, ficarias bem contente.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 7, 'Levanta-te, pois, agora; sai e fala ao coração de teus servos. Porque pelo Senhor te juro que, se não saíres, nem um só homem ficará contigo esta noite; e isso te será pior do que todo o mal que tem vindo sobre ti desde a tua mocidade até agora.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 8, 'Pelo que o rei se levantou, e se sentou à porta; e avisaram a todo o povo, dizendo: Eis que o rei está sentado à porta. Então todo o povo veio apresentar-se diante do rei. Ora, Israel havia fugido, cada um para a sua tenda.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 9, 'Entrementes todo o povo, em todas as tribos de Israel, andava altercando entre si, dizendo: O rei nos tirou das mãos de nossos inimigos, e nos livrou das mãos dos filisteus; e agora fugiu da terra por causa de Absalão.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 10, 'Também Absalão, a quem ungimos sobre nós, morreu na peleja. Agora, pois, porque vos calais, e não fazeis voltar o rei?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 11, 'Então o rei Davi mandou dizer a Zadoque e a Abiatar, sacerdotes: Falai aos anciãos de Judá, dizendo: Por que seríeis vós os últimos em tornar a trazer o rei para sua casa? Porque a palavra de todo o Israel tem chegado ao rei, até a sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 12, 'Vós sois meus irmãos; meus ossos e minha carne sois vós; por que, pois, seríeis os últimos em tornar a trazer o rei?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 13, 'Dizei a Amasa: Porventura não és tu meu osso e minha carne? Assim me faça Deus e outro tanto, se não fores chefe do exercito diante e mim para sempre, em lugar de Joabe.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 14, 'Assim moveu ele o coração de todos os homens de Judá, como se fosse o de um só homem; e enviaram ao rei, dizendo: Volta, com todos os teus servos.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 15, 'Então o rei voltou, e chegou até o Jordão; e Judá veio a Gilgal, para encontrar-se com o rei, a fim de fazê-lo passar o Jordão.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 16, 'Ora, apressou-se Simei, filho de Gêra, benjamita, que era de Baurim, e desceu com os homens de Judá a encontrar-se com o rei Davi;', 1, CURRENT_TIMESTAMP, false),
(10, 19, 17, 'e com ele mil homens de Benjamim, como também Ziba, servo da casa de Saul, e seus quinze filhos, e seus vinte servos com ele; desceram apressadamente ao Jordão adiante do rei,', 1, CURRENT_TIMESTAMP, false),
(10, 19, 18, 'atravessando o vau para trazer a casa do rei e para fazer o que aprouvesse a ele. Quando o rei ia passar o Jordão, Simei, filho de Gêra, se prostrou diante dele,', 1, CURRENT_TIMESTAMP, false),
(10, 19, 19, 'e lhe disse: Não me impute meu senhor à minha culpa, e não te lembres do que tão perversamente fez teu servo, no dia em que o rei meu senhor saiu de Jerusalém; não conserve o rei isso no coração.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 20, 'Porque eu, teu servo, deveras confesso que pequei; por isso eis que eu sou o primeiro, de toda a casa de José, a descer ao encontro do rei meu senhor.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 21, 'Respondeu Abisai, filho de Zeruia, dizendo: Não há de ser morto Simei por haver amaldiçoado ao ungido do Senhor?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 22, 'Mas Davi disse: Que tenho eu convosco, filhos de Zeruia, para que hoje me sejais adversários? Será morto alguém hoje em Israel? pois não sei eu que hoje sou rei sobre Israel?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 23, 'Então disse o rei a Simei: Não morrerás. E o rei lho jurou.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 24, 'Também Mefibosete, filho de Saul, desceu a encontrar-se com o rei, e não cuidara dos pés, nem fizera a barba, nem lavara as suas vestes desde o dia em que o rei saíra até o dia em que voltou em paz.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 25, 'E sucedeu que, vindo ele a Jerusalém a encontrar-se com o rei, este lhe perguntou: Por que não foste comigo, Mefibosete?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 26, 'Respondeu ele: O rei meu senhor, o meu servo me enganou. Porque o teu servo dizia: Albardarei um jumento, para nele montar e ir com o rei; pois o teu servo é coxo.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 27, 'E ele acusou falsamente o teu servo diante do rei meu senhor; porém o rei meu senhor é como um anjo de Deus; faze, pois, o que bem te parecer.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 28, 'Pois toda a casa de meu pai não era senão de homens dignos de morte diante do rei meu senhor; contudo, puseste teu servo entre os que comem à tua mesa. E que direito mais tenho eu de clamar ainda ao rei.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 29, 'Ao que lhe respondeu o rei: Por que falas ainda de teus negócios? Já decidi: Tu e Ziba reparti as terras.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 30, 'Então disse Mefibosete ao rei: Deixe que ele tome tudo, uma vez que o rei meu senhor já voltou em paz à sua casa.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 31, 'Também Barzilai, o gileadita, desceu de Rogelim, e passou com o rei o Jordão, para acompanhá-lo até a outra banda do rio.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 32, 'E era Barzilai mui velho, da idade de oitenta anos; e ele tinha provido o rei de víveres enquanto este se demorara em Maanaim, pois era homem muito rico.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 33, 'Disse, pois, o rei a Barzilai: Passa tu comigo e eu te sustentarei em Jerusalém, em minha companhia.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 34, 'Barzilai, porém, respondeu ao rei: Quantos anos viverei ainda, para que suba com o rei a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 35, 'Oitenta anos tenho hoje; poderei eu discernir entre e bom e o mau? poderá o teu servo perceber sabor no que comer e beber? poderei eu mais ouvir a voz dos cantores e das cantoras? e por que será o teu servo ainda pesado ao rei meu senhor?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 36, 'O teu servo passará com o rei até um pouco além do Jordão. Por que me daria o rei tal recompensa?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 37, 'Deixa voltar o teu servo, para que eu morra na minha cidade, junto à sepultura de meu pai e de minha mãe. Mas eis aí o teu servo Quimã; passe ele com o rei meu senhor, e faze-lhe o que for do teu agrado.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 38, 'Ao que disse o rei: Quimã passará comigo, e eu lhe farei o que te parecer bem, e tudo quanto me pedires te farei.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 39, 'Havendo, pois, todo o povo passado o Jordão, e tendo passado também o rei, beijou o rei a Barzilai, e o abençoou; e este voltou para o seu lugar.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 40, 'Dali passou o rei a Gilgal, e Quimã com ele; e todo o povo de Judá, juntamente com a metade do povo de Israel, conduziu o rei.', 1, CURRENT_TIMESTAMP, false),
(10, 19, 41, 'Então todos os homens de Israel vieram ter com o rei, e lhe disseram: Por que te furtaram nossos irmãos, os homens de Judá, e fizeram passar o Jordão o rei e a sua casa, e todos os seus homens com ele?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 42, 'Responderam todos os homens de Judá aos homens de Israel: Porquanto o rei é nosso parente: Por que vos irais por isso. Acaso temos comido à custa do rei, ou nos deu ele algum presente?', 1, CURRENT_TIMESTAMP, false),
(10, 19, 43, 'Ao que os homens de Israel responderam aos homens de Judá: Dez partes temos no rei; mais temos nós em Davi do que vós. Por que, pois, fizestes pouca conta de nós. Não foi a nossa palavra a primeira, para tornar a trazer o nosso rei? Porém a palavra dos homens de Judá foi mais forte do que a palavra dos homens de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 1, 'Ora, sucedeu achar-se ali um homem de Belial, cujo nome era Sebá, filho de Bicri, homem de Benjamim, o qual tocou a buzina, e disse: Não temos parte em Davi, nem herança no filho de Jessé; cada um à sua tenda, ó Israel!', 1, CURRENT_TIMESTAMP, false),
(10, 20, 2, 'Então todos os homens de Israel se separaram de Davi, e seguiram a Sebá, filho de Bicri; porém os homens de Judá seguiram ao seu rei desde o Jordão até Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 3, 'Quando Davi chegou à sua casa em Jerusalém, tomou as dez concubinas que deixara para guardarem a casa, e as pôs numa casa, sob guarda, e as sustentava; porém não entrou a elas. Assim estiveram encerradas até o dia da sua morte, vivendo como viúvas.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 4, 'Disse então o rei a Amasa: Convoca-me dentro de três dias os homens de Judá, e apresenta-te aqui.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 5, 'Foi, pois, Amasa para convocar a Judá, porém demorou-se além do tempo que o rei lhe designara.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 6, 'Então disse Davi a Abisai: Mais mal agora nos fará Sebá, filho de Bicri, do que Absalão; toma, pois, tu os servos de teu senhor, e persegue-o, para que ele porventura não ache para si cidades fortificadas, e nos escape à nossa vista.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 7, 'Então saíram atrás dele os homens de Joabe, e os quereteus, e os peleteus, e todos os valentes; saíram de Jerusalém para perseguirem a Sebá, filho de Bicri.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 8, 'Quando chegaram à pedra grande que está junto a Gibeão, Amasa lhes veio ao encontro. Estava Joabe cingido do seu traje de guerra que vestira, e sobre ele um cinto com a espada presa aos seus lombos, na sua bainha; e, adiantando-se ele, a espada caiu da bainha.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 9, 'E disse Joabe a Amasa: Vais bem, meu irmão? E Joabe, com a mão direita, pegou da barba de Amasa, para o beijar.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 10, 'Amasa, porém, não reparou na espada que está na mão de Joabe; de sorte que este o feriu com ela no ventre, derramando-lhe por terra as entranhas, sem feri-lo segunda vez; e ele morreu. Então Joabe e Abisai, seu irmão, perseguiram a Sebá, filho de Bicri.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 11, 'Mas um homem dentre os servos de Joabe ficou junto a Amasa, e dizia: Quem favorece a Joabe, e quem é por Davi, siga a Joabe.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 12, 'E Amasa se revolvia no seu sangue no meio do caminho. E aquele homem, vendo que todo o povo parava, removeu Amasa do caminho para o campo, e lançou sobre ele um manto, porque viu que todo aquele que chegava ao pé dele parava.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 13, 'Mas removido Amasa do caminho, todos os homens seguiram a Joabe, para perseguirem a Sebá, filho de Bicri.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 14, 'Então Sebá passou por todas as tribos de Israel até Abel e Bete-Maacá; e todos os beritas, ajuntando-se, também o seguiram.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 15, 'Vieram, pois, e cercaram a Sebá em Abel de Bete-Maacá; e levantaram contra a cidade um montão, que se elevou defronte do muro; e todo o povo que estava com Joabe batia o muro para derrubá-lo.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 16, 'Então uma mulher sábia gritou de dentro da cidade: Ouvi! ouvi! Dizei a Joabe: Chega-te cá, para que eu te fale.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 17, 'Ele, pois, se chegou perto dela; e a mulher perguntou: Tu és Joabe? Respondeu ele: Sou. Ela lhe disse: Ouve as palavras de tua serva. Disse ele: Estou ouvindo.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 18, 'Então falou ela, dizendo: Antigamente costumava-se dizer: Que se peça conselho em Abel; e era assim que se punha termo às questões.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 19, 'Eu sou uma das pacíficas e das fiéis em Israel; e tu procuras destruir uma cidade que é mãe em Israel; por que, pois, devorarias a herança do Senhor?', 1, CURRENT_TIMESTAMP, false),
(10, 20, 20, 'Então respondeu Joabe, e disse: Longe, longe de mim que eu tal faça, que eu devore ou arruíne!', 1, CURRENT_TIMESTAMP, false),
(10, 20, 21, 'A coisa não é assim; porém um só homem da região montanhosa de Efraim, cujo nome é Sebá, filho de Bicri, levantou a mão contra o rei, contra Davi; entregai-me só este, e retirar-me-ei da cidade. E disse a mulher a Joabe: Eis que te será lançada a sua cabeça pelo muro.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 22, 'A mulher, na sua sabedoria, foi ter com todo o povo; e cortaram a cabeça de Sebá, filho de Bicri, e a lançaram a Joabe. Este, pois, tocou a buzina, e eles se retiraram da cidade, cada um para sua tenda. E Joabe voltou a Jerusalém, ao rei.', 1, CURRENT_TIMESTAMP, false),
(10, 20, 23, 'Ora, Joabe estava sobre todo o exército de Israel; e Benaías, filho de Jeoiada, sobre os quereteus e os peleteus;', 1, CURRENT_TIMESTAMP, false),
(10, 20, 24, 'e Adorão sobre a gente de trabalhos forçados; Jeosafá, filho de Ailude, era cronista;', 1, CURRENT_TIMESTAMP, false),
(10, 20, 25, 'Seva era escrivão; Zadoque e Abiatar, sacerdotes;', 1, CURRENT_TIMESTAMP, false),
(10, 20, 26, 'e Ira, o jairita, era o oficial-mor de Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 1, 'Nos dias de Davi houve uma fome de três anos consecutivos; pelo que Davi consultou ao Senhor; e o Senhor lhe disse: E por causa de Saul e da sua casa sanguinária, porque matou os gibeonitas.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 2, 'Então o rei chamou os gibeonitas e falou com eles {ora, os gibeonitas não eram dos filhos de Israel, mas do restante dos amorreus; e os filhos de Israel tinham feito pacto com eles; porém Saul, no seu zelo pelos filhos de Israel e de Judá, procurou feri-los};', 1, CURRENT_TIMESTAMP, false),
(10, 21, 3, 'perguntou, pois, Davi aos gibeonitas: Que quereis que eu vos faça. e como hei de fazer expiação, para que abençoeis a herança do Senhor?', 1, CURRENT_TIMESTAMP, false),
(10, 21, 4, 'Então os gibeonitas lhe disseram: Não é por prata nem ouro que temos questão com Saul e com a sua casa; nem tampouco cabe a nós matar pessoa alguma em Israel. Disse-lhes Davi: Que quereis que vos faça?', 1, CURRENT_TIMESTAMP, false),
(10, 21, 5, 'Responderam ao rei: Quanto ao homem que nos consumia, e procurava destruir-nos, de modo que não pudéssemos subsistir em termo algum de Israel,', 1, CURRENT_TIMESTAMP, false),
(10, 21, 6, 'de seus filhos se nos dêem sete homens, para que os enforquemos ao Senhor em Gibeá de Saul, o eleito do Senhor. E o rei disse: Eu os darei.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 7, 'O rei, porém, poupou a Mefibosete, filho de Jônatas, filho de Saul, por causa do juramento do Senhor que entre eles houvera, isto é, entre Davi e Jônatas, filho de Saul.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 8, 'Mas o rei tomou os dois filhos de Rizpa, filha de Aías, que ela tivera de Saul, a saber, a Armoni e a Mefibosete, como também os cinco filhos de Merabe, filha de Saul, que ela tivera de Adriel, filho de Barzilai, meolatita,', 1, CURRENT_TIMESTAMP, false),
(10, 21, 9, 'e os entregou na mão dos gibeonitas, os quais os enforcaram no monte, perante o Senhor; e os sete caíram todos juntos. Foi nos primeiros dias da sega que foram mortos, no princípio a sega da cevada.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 10, 'Então Rizpa, filha de Aías, tomando um pano de cilício, estendeu-o para si sobre uma pedra e, desde o princípio da sega até que a água caiu do céu sobre os corpos, não deixou que se aproximassem deles as aves do céu de dia, nem os animais do campo de noite:', 1, CURRENT_TIMESTAMP, false),
(10, 21, 11, 'Quando foi anunciado a Davi o que fizera Rizpa, filha de Aías, concubina de Saul,', 1, CURRENT_TIMESTAMP, false),
(10, 21, 12, 'ele foi e tomou os ossos de Saul e os de Jônatas seu filho, aos homens de Jabes-Gileade, que os haviam furtado da praça de Bete-Seã, onde os filisteus os tinham pendurado quando mataram a Saul em Gilboa;', 1, CURRENT_TIMESTAMP, false),
(10, 21, 13, 'e trouxe dali os ossos de Saul e os de Jônatas seu filho; e ajuntaram a eles também os ossos dos enforcados.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 14, 'Enterraram os ossos de Saul e de Jônatas seu filho, na terra de Benjamim, em Zela, na sepultura de Quis, seu pai; e fizeram tudo o que o rei ordenara. Depois disto Deus se aplacou para com a terra.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 15, 'De novo tiveram os filisteus uma guerra contra Israel. E desceu Davi, e com ele os seus servos; e tanto pelejara contra os filisteus, que Davi se cansou.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 16, 'E Isbi-Benobe, que era dos filhos do gigante, cuja lança tinha o peso de trezentos, siclos de bronze, e que cingia uma espada nova, intentou matar Davi.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 17, 'Porém, Abisai, filho de Zeruia, o socorreu; e, ferindo ao filisteu, o matou. Então os homens de Davi lhe juraram, dizendo: Nunca mais sairás conosco à batalha, para que não apagues a lâmpada de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 18, 'Aconteceu depois disto que houve em Gobe ainda outra peleja contra os filisteus; então Sibecai, o husatita, matou Safe, que era dos filhos do gigante.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 19, 'Houve mais outra peleja contra os filisteus em Gobe; e El-Hanã, filho de Jaaré-Oregim, o belemita, matou Golias, o giteu, de cuja lança a haste era como órgão de tecelão.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 20, 'Houve ainda também outra peleja em Gate, onde estava um homem de alta estatura, que tinha seis dedos em cada mão, e seis em cada pé, vinte e quatro por todos; também este era descendente do gigante.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 21, 'Tendo ele desafiado a Israel, Jônatas, filho de Simei, irmão de Davi, o matou.', 1, CURRENT_TIMESTAMP, false),
(10, 21, 22, 'Estes quatro nasceram ao gigante em Gate; e caíram pela mão de Davi e pela mão de seus servos.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 1, 'Davi dirigiu ao Senhor as palavras deste cântico, no dia em que o Senhor o livrou das mãos de todos os seus inimigos e das mãos de Saul, dizendo:', 1, CURRENT_TIMESTAMP, false),
(10, 22, 2, 'O Senhor é o meu rochedo, a minha fortaleza e o meu libertador.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 3, 'É meu Deus, a minha rocha, nele confiarei; é o meu escudo, e a força da minha salvação, o meu alto retiro, e o meu refúgio. O meu Salvador; da violência tu me livras.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 4, 'Ao Senhor invocarei, pois é digno de louvor; assim serei salvo dos meus inimigos.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 5, 'As ondas da morte me cercaram, as torrentes de Belial me atemorizaram.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 6, 'Cordas do Seol me cingiram, laços de morte me envolveram.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 7, 'Na minha angústia invoquei ao Senhor; sim, a meu Deus clamei; do seu templo ouviu ele a minha voz, e o meu clamor chegou aos seus ouvidos.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 8, 'Então se abalou e tremeu a terra, os fundamentos dos céus se moveram; abalaram-se porque ele se irou.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 9, 'Das suas narinas subiu fumaça, e da sua boca um fogo devorador, que pôs carvões em chamas.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 10, 'Ele abaixou os céus, e desceu; e havia escuridão debaixo dos seus pés.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 11, 'Montou num querubim, e voou; apareceu sobre as asas do vento.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 12, 'E por tendas pôs trevas ao redor de si, ajuntamento de águas, espessas nuvens do céu.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 13, 'Pelo resplendor da sua presença acenderam-se brasas de fogo.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 14, 'Do céu trovejou o Senhor, o Altíssimo fez soar a sua voz.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 15, 'Disparou flechas, e os dissipou; raios, e os desbaratou.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 16, 'Então apareceram as profundezas do mar; os fundamentos do mundo se descobriram, pela repreensão do Senhor, pelo assopro do vento das suas narinas.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 17, 'Estendeu do alto a sua mão e tomou-me; tirou-me das muitas águas.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 18, 'Livrou-me do meu possante inimigo, e daqueles que me odiavam; porque eram fortes demais para mim.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 19, 'Encontraram-me no dia da minha calamidade, porém o Senhor se fez o meu esteio.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 20, 'Conduziu-me para um lugar espaçoso; livrou-me, porque tinha prazer em mim.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 21, 'Recompensou-me o Senhor conforme a minha justiça; conforme a pureza e minhas mãos me retribuiu.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 22, 'Porque guardei os caminhos do Senhor, e não me apartei impiamente do meu Deus.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 23, 'Pois todos os seus preceitos estavam diante de mim, e dos seus estatutos não me desviei.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 24, 'Fui perfeito para com ele, e guardei-me da minha iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 25, 'Por isso me retribuiu o Senhor conforme a minha justiça, conforme a minha pureza diante dos meus olhos.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 26, 'Para com o benigno te mostras benigno; para com o perfeito te mostras perfeito,', 1, CURRENT_TIMESTAMP, false),
(10, 22, 27, 'para com o puro te mostras puro, mas para com o perverso te mostras avesso.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 28, 'Livrarás o povo que se humilha, mas teus olhos são contra os altivos, e tu os abaterás.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 29, 'Porque tu, Senhor, és a minha candeia; e o Senhor alumiará as minhas trevas.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 30, 'Pois contigo passarei pelo meio dum esquadrão; com o meu Deus transporei um muro.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 31, 'Quanto a Deus, o seu caminho é perfeito, e a palavra do Senhor é fiel; é ele o escudo de todos os que nele se refugiam.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 32, 'Pois quem é Deus, senão o Senhor? e quem é rocha, senão o nosso Deus?', 1, CURRENT_TIMESTAMP, false),
(10, 22, 33, 'Deus é a minha grande fortaleza; e ele torna perfeito o meu caminho.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 34, 'Faz ele os meus pés como os das gazelas, e me põe sobre as minhas alturas.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 35, 'Ele instrui as minhas mãos para a peleja, de modo que os meus braços podem entesar um arco de bronze.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 36, 'Também me deste o escudo da tua salvação, e tua brandura me engrandece.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 37, 'Alargaste os meus passos debaixo de mim, e não vacilaram os meus artelhos.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 38, 'Persegui os meus inimigos e os destruí, e nunca voltei atrás sem que os consumisse.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 39, 'Eu os consumi, e os atravessei, de modo que nunca mais se levantaram; sim, cairam debaixo dos meus pés.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 40, 'Pois tu me cingiste de força para a peleja; prostraste debaixo de mim os que se levantaram contra mim.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 41, 'Fizeste que me voltassem as costas os meus inimigos, aqueles que me odiavam, para que eu os destruísse.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 42, 'Olharam ao redor, mas não houve quem os salvasse; clamaram ao Senhor, mas ele não lhes respondeu.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 43, 'Então os moí como o pó da terra; como a lama das ruas os trilhei e dissipei.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 44, 'Também me livraste das contendas do meu povo; guardaste-me para ser o cabeça das nações; um povo que eu não conhecia me serviu.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 45, 'Estrangeiros, com adulação, se submeteram a mim; ao ouvirem de mim, me obedeceram.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 46, 'Os estrangeiros desfaleceram e, tremendo, sairam os seus esconderijos.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 47, 'O Senhor vive; bendita seja a minha rocha, e exaltado seja Deus, a rocha da minha salvação,', 1, CURRENT_TIMESTAMP, false),
(10, 22, 48, 'o Deus que me deu vingança, e sujeitou povos debaixo de mim,', 1, CURRENT_TIMESTAMP, false),
(10, 22, 49, 'e me tirou dentre os meus inimigos; porque tu me exaltaste sobre os meus adversários; tu me livraste do homem violento.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 50, 'Por isso, ó Senhor, louvar-te-ei entre as nações, e entoarei louvores ao teu nome.', 1, CURRENT_TIMESTAMP, false),
(10, 22, 51, 'Ele dá grande livramento a seu rei, e usa de benignidade para com o seu ungido, para com Davi e a sua descendência para sempre.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 1, 'São estas as últimas palavras de Davi: Diz Davi, filho de Jessé, diz a homem que foi exaltado, o ungido do Deus de Jacó, o suave salmista de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 2, 'O Espírito do Senhor fala por mim, e a sua palavra está na minha língua.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 3, 'Falou o Deus de Israel, a Rocha de Israel me disse: Quando um justo governa sobre os homens, quando governa no temor de Deus,', 1, CURRENT_TIMESTAMP, false),
(10, 23, 4, 'será como a luz da manhã ao sair do sol, da manhã sem nuvens, quando, depois da chuva, pelo resplendor do sol, a erva brota da terra.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 5, 'Pois não é assim a minha casa para com Deus? Porque estabeleceu comigo um pacto eterno, em tudo bem ordenado e seguro; pois não fará ele prosperar toda a minha salvação e todo o meu desejo?', 1, CURRENT_TIMESTAMP, false),
(10, 23, 6, 'Porém os ímpios todos serão como os espinhos, que se lançam fora, porque não se pode tocar neles;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 7, 'mas qualquer que os tocar se armará de ferro e da haste de uma lança; e a fogo serão totalmente queimados no mesmo lugar.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 8, 'São estes os nomes dos valentes de Davi: Josebe-Bassebete, o taquemonita; era este principal dos três; foi ele que, com a lança, matou oitocentos de uma vez.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 9, 'Depois dele Eleazar, filho de Dodó, filho de Aoí, um dos três valentes que estavam com Davi, quando desafiaram os filisteus que se haviam reunido para a peleja, enquanto os homens de Israel se retiravam.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 10, 'Este se levantou, e feriu os filisteus, até lhe cansar a mão e ficar pegada à espada; e naquele dia o Senhor operou um grande livramento; e o povo voltou para junto de Eleazar, somente para tomar o despojo.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 11, 'Depois dele era Samá, filho de Agé, o hararita. Os filisteus se haviam ajuntado em Leí, onde havia um terreno cheio de lentilhas; e o povo fugiu de diante dos filisteus.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 12, 'Samá, porém, pondo-se no meio daquele terreno, defendeu-o e matou os filisteus, e o Senhor efetuou um grande livramento.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 13, 'Também três dos trinta cabeças desceram, no tempo da sega, e foram ter com Davi, à caverna de Adulão; e a tropa dos filisteus acampara no vale de Refaim.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 14, 'Davi estava então no lugar forte, e a guarnição dos filisteus estava em Belém.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 15, 'E Davi, com saudade, exclamou: Quem me dera beber da água da cisterna que está junto a porta de Belém!', 1, CURRENT_TIMESTAMP, false),
(10, 23, 16, 'Então aqueles três valentes romperam pelo arraial dos filisteus, tiraram água da cisterna que está junto a porta de Belém, e a trouxeram a Davi; porém ele não quis bebê-la, mas derramou-a perante o Senhor;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 17, 'e disse: Longe de mim, ó Senhor, que eu tal faça! Beberia eu o sangue dos homens que foram com risco das suas vidas? De maneira que não a quis beber. Isto fizeram aqueles três valentes.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 18, 'Ora, Abisai, irmão de Joabe, filho de Zeruia, era chefe dos trinta; e este alçou a sua lança contra trezentos, e os matou, e tinha nome entre os três.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 19, 'Porventura não era este o mais nobre dentre os trinta? portanto se tornou o chefe deles; porém aos primeiros três não chegou.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 20, 'Também Benaías, filho de Jeoiada, filho dum homem de Cabzeel, valoroso e de grandes feitos, matou os dois filhos de Ariel de Moabe; depois desceu, e matou um leão dentro duma cova, no tempo da neve.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 21, 'Matou também um egípcio, homem de temível aspecto; tinha este uma lança na mão, mas Benaías desceu a ele com um cajado, arrancou-lhe da mão a lança, e com ela o matou.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 22, 'Estas coisas fez Benaías, filho de Jeoiada, pelo que teve nome entre os três valentes.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 23, 'Dentre os trinta ele era o mais afamado, porém aos três primeiros não chegou. Mas Davi o pôs sobre os seus guardas.', 1, CURRENT_TIMESTAMP, false),
(10, 23, 24, 'Asael, irmão de Joabe, era um dos trinta; El-Hanã, filho de Dodó, de Belém;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 25, 'Samá, o harodita; Elica, o harodita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 26, 'Jelez, o paltita; Ira, filho de Iques, o tecoíta;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 27, 'Abiezer, o anatotita; Mebunai, o husatita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 28, 'Zalmom, o aoíta; Maarai, o netofatita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 29, 'Helebe, filho de Baaná, o netofatita; Itai, filho de Ribai, de Gibeá dos filhos de Benjamim;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 30, 'Benaías, o piratonita; Hidai, das torrentes de Gaás;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 31, 'Abi-Albom, o arbatita; Azmavete, o barumita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 32, 'Eliabá, o saalbonita; Bene-Jásen; e Jônatas;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 33, 'Samá, o hararita; Aião, filho de Sarar, o hararita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 34, 'Elifelete, filho de Acasbai, filho do maacatita; Eliã, filho de Aitofel, o gilonita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 35, 'Hezrai, o carmelita; Paarai, o arbita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 36, 'Igal, filho de Natã, de Zobá; Bani, o gadita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 37, 'Zeleque, o amonita; Naarai, o beerotita, o que trazia as armas de Joabe, filho de Zeruia;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 38, 'Ira, o itrita; Garebe, o itrita;', 1, CURRENT_TIMESTAMP, false),
(10, 23, 39, 'Urias, o heteu; trinta e sete ao todo.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 1, 'A ira do Senhor tornou a acender-se contra Israel, e o Senhor incitou a Davi contra eles, dizendo: Vai, numera a Israel e a Judá.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 2, 'Disse, pois, o rei a Joabe, chefe do exército, que estava com ele: Percorre todas as tribos de Israel, desde Dã até Berseba, e numera o povo, para que eu saiba o seu número.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 3, 'Então disse Joabe ao rei: Ora, multiplique o Senhor teu Deus a este povo cem vezes tanto quanto agora é, e os olhos do rei meu senhor o vejam. Mas por que tem prazer nisto o rei meu senhor;', 1, CURRENT_TIMESTAMP, false),
(10, 24, 4, 'Todavia a palavra do rei prevaleceu contra Joabe, e contra os chefes do exército; Joabe, pois, saiu com os chefes do exército da presença do rei para numerar o povo de Israel.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 5, 'Tendo eles passado o Jordão, acamparam-se em Aroer, à direita da cidade que está no meio do vale de Gade e na direção de Jazer;', 1, CURRENT_TIMESTAMP, false),
(10, 24, 6, 'em seguida foram a Gileade, e a terra de Tatim-Hódsi; dali foram a Da-Jaã, e ao redor até Sidom;', 1, CURRENT_TIMESTAMP, false),
(10, 24, 7, 'depois foram à fortaleza de Tiro, e a todas as cidades dos heveus e dos cananeus; e saíram para a banda do sul de Judá, em Berseba.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 8, 'Assim, tendo percorrido todo o país, voltaram a Jerusalém, ao cabo de nove meses e vinte dias.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 9, 'Joabe, pois, deu ao rei o resultado da numeração do povo. E havia em Israel oitocentos mil homens valorosos, que arrancavam da espada; e os homens de Judá eram quinhentos mil.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 10, 'Mas o coração de Davi o acusou depois de haver ele numerado o povo; e disse Davi ao Senhor: Muito pequei no que fiz; porém agora, ó Senhor, rogo-te que perdoes a iniqüidade do teu servo, porque tenho procedido mui nesciamente.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 11, 'Quando, pois, Davi se levantou pela manhã, veio a palavra do Senhor ao profeta Gade, vidente de Davi, dizendo:', 1, CURRENT_TIMESTAMP, false),
(10, 24, 12, 'Vai, e dize a Davi: Assim diz o Senhor: Três coisas te ofereço; escolhe qual delas queres que eu te faça.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 13, 'Veio, pois, Gade a Davi, e fez-lho saber dizendo-lhe: Queres que te venham sete anos de fome na tua terra; ou que por três meses fujas diante de teus inimigos, enquanto estes te perseguirem; ou que por três dias haja peste na tua terra? Delibera agora, e vê que resposta hei de dar àquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 14, 'Respondeu Davi a Gade: Estou em grande angústia; porém caiamos nas mãos do Senhor, porque muitas são as suas misericórdias; mas nas mãos dos homens não caia eu.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 15, 'Então enviou o Senhor a peste sobre Israel, desde a manhã até o tempo determinado; e morreram do povo, desde Dã até Berseba, setenta mil homens.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 16, 'Ora, quando o anjo estendeu a mão sobre Jerusalém, para a destruir, o Senhor se arrependeu daquele mal; e disse ao anjo que fazia a destruição entre o povo: Basta; retira agora a tua mão. E o anjo do Senhor estava junto à eira de Araúna, o jebuseu.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 17, 'E, vendo Davi ao anjo que feria o povo, falou ao Senhor, dizendo: Eis que eu pequei, e procedi iniquamente; porém estas ovelhas, que fizeram? Seja, pois, a tua mão contra mim, e contra a casa de meu pai.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 18, 'Naquele mesmo dia veio Gade a Davi, e lhe disse: Sobe, levanta ao Senhor um altar na eira de Araúna, o jebuseu:', 1, CURRENT_TIMESTAMP, false),
(10, 24, 19, 'Subiu, pois, Davi, conforme a palavra de Gade, como o Senhor havia ordenado.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 20, 'E olhando Araúna, viu que vinham ter com ele o rei e os seus servos; saiu, pois, e inclinou-se diante do rei com o rosto em terra.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 21, 'Perguntou Araúna: Por que vem o rei meu senhor ao seu servo? Respondeu Davi: Para comprar de ti a eira, a fim de edificar nela um altar ao Senhor, para que a praga cesse de sobre o povo.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 22, 'Então disse Araúna a Davi: Tome e ofereça o rei meu senhor o que bem lhe parecer; eis aí os bois para o holocausto, e os trilhos e os aparelhos dos bois para lenha.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 23, 'Tudo isto, ó rei, Araúna te oferece. Disse mais Araúna ao rei: O Senhor teu Deus tome prazer em ti.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 24, 'Mas o rei disse a Araúna: Não! antes to comprarei pelo seu valor, porque não oferecerei ao Senhor meu Deus holocaustos que não me custem nada. Comprou, pois, Davi a eira e os bois por cinqüenta siclos de prata.', 1, CURRENT_TIMESTAMP, false),
(10, 24, 25, 'E edificou ali um altar ao Senhor, e ofereceu holocaustos e ofertas pacíficas. Assim o Senhor se tornou propício para com a terra, e cessou aquela praga de sobre Israel.', 1, CURRENT_TIMESTAMP, false),
(53, 1, 1, 'Paulo, Silvano e Timóteo à igreja dos tessalonicenses, em Deus nosso Pai e no Senhor Jesus Cristo:', 1, CURRENT_TIMESTAMP, false),
(53, 1, 2, 'Graças a vós, e paz da parte de Deus Pai e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(53, 1, 3, 'Sempre devemos, irmãos, dar graças a Deus por vós, como é justo, porque a vossa fé cresce muitíssimo e o amor de cada um de vós transborda de uns para com os outros.', 1, CURRENT_TIMESTAMP, false),
(53, 1, 4, 'De maneira que nós mesmos nos gloriamos de vós nas igrejas de Deus por causa da vossa constância e fé em todas as perseguições e aflições que suportais;', 1, CURRENT_TIMESTAMP, false),
(53, 1, 5, 'o que é prova clara do justo juízo de Deus, para que sejais havidos por dignos do reino de Deus, pelo qual também padeceis;', 1, CURRENT_TIMESTAMP, false),
(53, 1, 6, 'se de fato é justo diante de Deus que ele dê em paga tribulação aos que vos atribulam,', 1, CURRENT_TIMESTAMP, false),
(53, 1, 7, 'e a vós, que sois atribulados, alívio juntamente conosco, quando do céu se manifestar o Senhor Jesus com os anjos do seu poder em chama de fogo,', 1, CURRENT_TIMESTAMP, false),
(53, 1, 8, 'e tomar vingança dos que não conhecem a Deus e dos que não conhecem a Deus e dos que não obedecem ao evangelho de nosso Senhor Jesus;', 1, CURRENT_TIMESTAMP, false),
(53, 1, 9, 'os quais sofrerão, como castigo, a perdição eterna, banidos da face do senhor e da glória do seu poder,', 1, CURRENT_TIMESTAMP, false),
(53, 1, 10, 'quando naquele dia ele vier para ser glorificado nos seus santos e para ser admirado em todos os que tiverem crido {porquanto o nosso testemunho foi crido entre vós}.', 1, CURRENT_TIMESTAMP, false),
(53, 1, 11, 'Pelo que também rogamos sempre por vós, para que o nosso Deus vos faça dignos da sua vocação, e cumpra com poder todo desejo de bondade e toda obra de fé.', 1, CURRENT_TIMESTAMP, false),
(53, 1, 12, 'para que o nome de nosso Senhor Jesus seja glorificado em vós, e vós nele, segundo a graça de nosso Deus e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 1, 'Ora, quanto à vinda de nosso Senhor Jesus Cristo e à nossa reunião com ele, rogamos-vos, irmãos,', 1, CURRENT_TIMESTAMP, false),
(53, 2, 2, 'que não vos movais facilmente do vosso modo de pensar, nem vos perturbeis, quer por espírito, quer por palavra, quer por epístola como enviada de nós, como se o dia do Senhor estivesse já perto.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 3, 'Ninguém de modo algum vos engane; porque isto não sucederá sem que venha primeiro a apostasia e seja revelado o homem do pecado, o filho da perdição,', 1, CURRENT_TIMESTAMP, false),
(53, 2, 4, 'aquele que se opõe e se levanta contra tudo o que se chama Deus ou é objeto de adoração, de sorte que se assenta no santuário de Deus, apresentando-se como Deus.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 5, 'Não vos lembrais de que eu vos dizia estas coisas quando ainda estava convosco?', 1, CURRENT_TIMESTAMP, false),
(53, 2, 6, 'E agora vós sabeis o que o detém para que a seu próprio tempo seja revelado.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 7, 'Pois o mistério da iniqüidade já opera; somente há um que agora o detém até que seja posto fora;', 1, CURRENT_TIMESTAMP, false),
(53, 2, 8, 'e então será revelado esse iníquo, a quem o Senhor Jesus matará como o sopro de sua boca e destruirá com a manifestação da sua vinda;', 1, CURRENT_TIMESTAMP, false),
(53, 2, 9, 'a esse iníquo cuja vinda é segundo a eficácia de Satanás com todo o poder e sinais e prodígios de mentira,', 1, CURRENT_TIMESTAMP, false),
(53, 2, 10, 'e com todo o engano da injustiça para os que perecem, porque não receberam o amor da verdade para serem salvos.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 11, 'E por isso Deus lhes envia a operação do erro, para que creiam na mentira;', 1, CURRENT_TIMESTAMP, false),
(53, 2, 12, 'para que sejam julgados todos os que não creram na verdade, antes tiveram prazer na injustiça.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 13, 'Mas nós devemos sempre dar graças a Deus por vós, irmãos, amados do Senhor, porque Deus vos escolheu desde o princípio para a santificação do espírito e a fé na verdade,', 1, CURRENT_TIMESTAMP, false),
(53, 2, 14, 'e para isso vos chamou pelo nosso evangelho, para alcançardes a glória de nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 15, 'Assim, pois, irmãos, estai firmes e conservai as tradições que vos foram ensinadas, seja por palavra, seja por epístola nossa.', 1, CURRENT_TIMESTAMP, false),
(53, 2, 16, 'E o próprio Senhor nosso, Jesus Cristo, e Deus nosso Pai que nos amou e pela graça nos deu uma eterna consolação e boa esperança,', 1, CURRENT_TIMESTAMP, false),
(53, 2, 17, 'console os vossos corações e os confirme em toda boa obra e palavra.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 1, 'Finalmente, irmãos, orai por nós, para que a palavra do Senhor se propague e seja glorificada. como também o é entre vós,', 1, CURRENT_TIMESTAMP, false),
(53, 3, 2, 'e para que sejamos livres de homens perversos e maus; porque a fé não é de todos.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 3, 'Mas fiel é o Senhor, o qual vos confirmará e guardará do maligno.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 4, 'E, quanto a vós, confiamos no Senhor que não só fazeis, mas fareis o que vos mandamos.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 5, 'Ora, o Senhor encaminhe os vossos corações no amor de Deus e na constância de Cristo.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 6, 'mandamo-vos, irmãos, em nome do Senhor Jesus Cristo, que vos aparteis de todo irmão que anda desordenadamente, e não segundo a tradição que de nós recebestes.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 7, 'Porque vós mesmos sabeis como deveis imitar-nos, pois que não nos portamos desordenadamente entre vós,', 1, CURRENT_TIMESTAMP, false),
(53, 3, 8, 'nem comemos de graça o pão de ninguém, antes com labor e fadiga trabalhávamos noite e dia para não sermos pesados a nenhum de vós.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 9, 'Não porque não tivéssemos direito, mas para vos dar nós mesmos exemplo, para nos imitardes.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 10, 'Porque, quando ainda estávamos convosco, isto vos mandamos: se alguém não quer trabalhar, também não coma.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 11, 'Porquanto ouvimos que alguns entre vós andam desordenadamente, não trabalhando, antes intrometendo-se na vida alheia;', 1, CURRENT_TIMESTAMP, false),
(53, 3, 12, 'a esses tais, porém, ordenamos e exortamos por nosso Senhor Jesus Cristo que, trabalhando sossegadamente, comam o seu próprio pão.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 13, 'Vós, porém, irmãos, não vos canseis de fazer o bem.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 14, 'Mas, se alguém não obedecer à nossa palavra por esta carta, notai-o e não tenhais relações com ele, para que se envergonhe;', 1, CURRENT_TIMESTAMP, false),
(53, 3, 15, 'todavia não o considereis como inimigo, mas admoestai-o como irmão.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 16, 'Ora, o próprio Senhor da paz vos dê paz sempre e de toda maneira. O Senhor seja com todos vós.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 17, 'Esta saudação é de próprio punho, de Paulo, o que é o sinal em cada epístola; assim escrevo.', 1, CURRENT_TIMESTAMP, false),
(53, 3, 18, 'A graça de nosso Senhor Jesus Cristo seja com todos vós.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, segundo a promessa da vida que está em Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(55, 1, 2, 'a Timóteo, amado filho: Graça, misericórdia e paz da parte de Deus Pai e de Cristo Jesus nosso Senhor.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 3, 'Dou graças a Deus, a quem desde os meus antepassados sirvo com uma consciência pura, de que sem cessar faço menção de ti em minhas súplicas de noite e de dia;', 1, CURRENT_TIMESTAMP, false),
(55, 1, 4, 'e, recordando-me das tuas lágrimas, desejo muito ver-te, para me encher de gozo;', 1, CURRENT_TIMESTAMP, false),
(55, 1, 5, 'trazendo à memória a fé não fingida que há em ti, a qual habitou primeiro em tua avó Loide, e em tua mãe Eunice e estou certo de que também habita em ti.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 6, 'Por esta razão te lembro que despertes o dom de Deus, que há em ti pela imposição das minhas mãos.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 7, 'Porque Deus não nos deu o espírito de covardia, mas de poder, de amor e de moderação.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 8, 'Portanto não te envergonhes do testemunho de nosso Senhor, nem de mim, que sou prisioneiro seu; antes participa comigo dos sofrimentos do evangelho segundo o poder de Deus,', 1, CURRENT_TIMESTAMP, false),
(55, 1, 9, 'que nos salvou, e chamou com uma santa vocação, não segundo as nossas obras, mas segundo o seu próprio propósito e a graça que nos foi dada em Cristo Jesus antes dos tempos eternos,', 1, CURRENT_TIMESTAMP, false),
(55, 1, 10, 'e que agora se manifestou pelo aparecimento de nosso Salvador Cristo Jesus, o qual destruiu a morte, e trouxe à luz a vida e a imortalidade pelo evangelho,', 1, CURRENT_TIMESTAMP, false),
(55, 1, 11, 'do qual fui constituído pregador, apóstolo e mestre.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 12, 'Por esta razão sofro também estas coisas, mas não me envergonho; porque eu sei em quem tenho crido, e estou certo de que ele é poderoso para guardar o meu depósito até aquele dia.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 13, 'Conserva o modelo das sãs palavras que de mim tens ouvido na fé e no amor que há em Cristo Jesus;', 1, CURRENT_TIMESTAMP, false),
(55, 1, 14, 'guarda o bom depósito com o auxílio do Espírito Santo, que habita em nós.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 15, 'Bem sabes isto, que me abandonaram todos os que estão na Ásia, entre eles Fígelo e Hermógenes.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 16, 'O Senhor conceda misericórdia à casa de Onesíforo, porque muitas vezes ele me recreou, e não se envergonhou das minhas cadeias;', 1, CURRENT_TIMESTAMP, false),
(55, 1, 17, 'antes quando veio a Roma, diligentemente me procurou e me achou.', 1, CURRENT_TIMESTAMP, false),
(55, 1, 18, 'O Senhor lhe conceda que naquele dia ache misericórdia diante do Senhor. E quantos serviços prestou em Éfeso melhor o sabes tu.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 1, 'Tu, pois, meu filho, fortifica-te na graça que há em Cristo Jesus;', 1, CURRENT_TIMESTAMP, false),
(55, 2, 2, 'e o que de mim ouviste de muitas testemunhas, transmite-o a homens fiéis, que sejam idôneos para também ensinarem os outros.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 3, 'Sofre comigo como bom soldado de Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 4, 'Nenhum soldado em serviço se embaraça com negócios desta vida, a fim de agradar àquele que o alistou para a guerra.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 5, 'E também se um atleta lutar nos jogos públicos, não será coroado se não lutar legitimamente.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 6, 'O lavrador que trabalha deve ser o primeiro a gozar dos frutos.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 7, 'Considera o que digo, porque o Senhor te dará entendimento em tudo.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 8, 'Lembra-te de Jesus Cristo, ressurgido dentre os mortos, descendente de Davi, segundo o meu evangelho,', 1, CURRENT_TIMESTAMP, false),
(55, 2, 9, 'pelo qual sofro a ponto de ser preso como malfeitor; mas a palavra de Deus não está presa.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 10, 'Por isso, tudo suporto por amor dos eleitos, para que também eles alcancem a salvação que há em Cristo Jesus com glória eterna.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 11, 'Fiel é esta palavra: Se, pois, já morremos com ele, também com ele viveremos;', 1, CURRENT_TIMESTAMP, false),
(55, 2, 12, 'se perseveramos, com ele também reinaremos; se o negarmos, também ele nos negará;', 1, CURRENT_TIMESTAMP, false),
(55, 2, 13, 'se somos infiéis, ele permanece fiel; porque não pode negar-se a si mesmo.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 14, 'Lembra-lhes estas coisas, conjurando-os diante de Deus que não tenham contendas de palavras, que para nada aproveitam, senão para subverter os ouvintes.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 15, 'Procura apresentar-te diante de Deus aprovado, como obreiro que não tem de que se envergonhar, que maneja bem a palavra da verdade.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 16, 'Mas evita as conversas vãs e profanas; porque os que delas usam passarão a impiedade ainda maior,', 1, CURRENT_TIMESTAMP, false),
(55, 2, 17, 'e as suas palavras alastrarão como gangrena; entre os quais estão Himeneu e Fileto,', 1, CURRENT_TIMESTAMP, false),
(55, 2, 18, 'que se desviaram da verdade, dizendo que a ressurreição é já passada, e assim pervertem a fé a alguns.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 19, 'Todavia o firme fundamento de Deus permanece, tendo este selo: O Senhor conhece os seus, e: Aparte-se da injustiça todo aquele que profere o nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 20, 'Ora, numa grande casa, não somente há vasos de ouro e de prata, mas também de madeira e de barro; e uns, na verdade, para uso honroso, outros, porém, para uso desonroso.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 21, 'Se, pois, alguém se purificar destas coisas, será vaso para honra, santificado e útil ao Senhor, preparado para toda boa obra.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 22, 'Foge também das paixões da mocidade, e segue a justiça, a fé, o amor, a paz com os que, de coração puro, invocam o Senhor.', 1, CURRENT_TIMESTAMP, false),
(55, 2, 23, 'E rejeita as questões tolas e desassisadas, sabendo que geram contendas;', 1, CURRENT_TIMESTAMP, false),
(55, 2, 24, 'e ao servo do Senhor não convém contender, mas sim ser brando para com todos, apto para ensinar, paciente;', 1, CURRENT_TIMESTAMP, false),
(55, 2, 25, 'corrigindo com mansidão os que resistem, na esperança de que Deus lhes conceda o arrependimento para conhecerem plenamente a verdade,', 1, CURRENT_TIMESTAMP, false),
(55, 2, 26, 'e que se desprendam dos laços do Diabo {por quem haviam sido presos}, para cumprirem a vontade de Deus.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 1, 'Sabe, porém, isto, que nos últimos dias sobrevirão tempos penosos;', 1, CURRENT_TIMESTAMP, false),
(55, 3, 2, 'pois os homens serão amantes de si mesmos, gananciosos, presunçosos, soberbos, blasfemos, desobedientes a seus pais, ingratos, ímpios,', 1, CURRENT_TIMESTAMP, false),
(55, 3, 3, 'sem afeição natural, implacáveis, caluniadores, incontinentes, cruéis, inimigos do bem,', 1, CURRENT_TIMESTAMP, false),
(55, 3, 4, 'traidores, atrevidos, orgulhosos, mais amigos dos deleites do que amigos de Deus,', 1, CURRENT_TIMESTAMP, false),
(55, 3, 5, 'tendo aparência de piedade, mas negando-lhe o poder. Afasta-te também desses.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 6, 'Porque deste número são os que se introduzem pelas casas, e levam cativas mulheres néscias carregadas de pecados, levadas de várias concupiscências;', 1, CURRENT_TIMESTAMP, false),
(55, 3, 7, 'sempre aprendendo, mas nunca podendo chegar ao pleno conhecimento da verdade.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 8, 'E assim como Janes e Jambres resistiram a Moisés, assim também estes resistem à verdade, sendo homens corruptos de entendimento e réprobos quanto à fé.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 9, 'Não irão, porém, avante; porque a todos será manifesta a sua insensatez, como também o foi a daqueles.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 10, 'Tu, porém, tens observado a minha doutrina, procedimento, intenção, fé, longanimidade, amor, perseverança,', 1, CURRENT_TIMESTAMP, false),
(55, 3, 11, 'as minhas perseguições e aflições, quais as que sofri em Antioquia, em Icônio, em Listra; quantas perseguições suportei! e de todas o Senhor me livrou.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 12, 'E na verdade todos os que querem viver piamente em Cristo Jesus padecerão perseguições.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 13, 'Mas os homens maus e impostores irão de mal a pior, enganando e sendo enganados.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 14, 'Tu, porém, permanece naquilo que aprendeste, e de que foste inteirado, sabendo de quem o tens aprendido,', 1, CURRENT_TIMESTAMP, false),
(55, 3, 15, 'e que desde a infância sabes as sagradas letras, que podem fazer-te sábio para a salvação, pela que há em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(55, 3, 16, 'Toda Escritura é divinamente inspirada e proveitosa para ensinar, para repreender, para corrigir, para instruir em justiça;', 1, CURRENT_TIMESTAMP, false),
(55, 3, 17, 'para que o homem de Deus seja perfeito, e perfeitamente preparado para toda boa obra.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 1, 'Conjuro-te diante de Deus e de Cristo Jesus, que há de julgar os vivos e os mortos, pela sua vinda e pelo seu reino;', 1, CURRENT_TIMESTAMP, false),
(55, 4, 2, 'prega a palavra, insta a tempo e fora de tempo, admoesta, repreende, exorta, com toda longanimidade e ensino.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 3, 'Porque virá tempo em que não suportarão a sã doutrina; mas, tendo grande desejo de ouvir coisas agradáveis, ajuntarão para si mestres segundo os seus próprios desejos,', 1, CURRENT_TIMESTAMP, false),
(55, 4, 4, 'e não só desviarão os ouvidos da verdade, mas se voltarão às fábulas.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 5, 'Tu, porém, sê sóbrio em tudo, sofre as aflições, faze a obra de um evangelista, cumpre o teu ministério.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 6, 'Quanto a mim, já estou sendo derramado como libação, e o tempo da minha partida está próximo.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 7, 'Combati o bom combate, acabei a carreira, guardei a fé.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 8, 'Desde agora, a coroa da justiça me está guardada, a qual o Senhor, justo juiz, me dará naquele dia; e não somente a mim, mas também a todos os que amarem a sua vinda.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 9, 'Procura vir ter comigo breve;', 1, CURRENT_TIMESTAMP, false),
(55, 4, 10, 'pois Demas me abandonou, tendo amado o mundo presente, e foi para Tessalônica, Crescente para a Galácia, Tito para a Dalmácia;', 1, CURRENT_TIMESTAMP, false),
(55, 4, 11, 'só Lucas está comigo. Toma a Marcos e traze-o contigo, porque me é muito útil para o ministério.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 12, 'Quanto a Tíquico, enviei-o a Éfeso.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 13, 'Quando vieres traze a capa que deixei em Trôade, em casa de Carpo, e os livros, especialmente os pergaminhos.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 14, 'Alexandre, o latoeiro, me fez muito mal; o Senhor lhe retribuirá segundo as suas obras.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 15, 'Tu também guarda-te dele; porque resistiu muito às nossas palavras.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 16, 'Na minha primeira defesa ninguém me assistiu, antes todos me desampararam. Que isto não lhes seja imputado.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 17, 'Mas o Senhor esteve ao meu lado e me fortaleceu, para que por mim fosse cumprida a pregação, e a ouvissem todos os gentios; e fiquei livre da boca do leão,', 1, CURRENT_TIMESTAMP, false),
(55, 4, 18, 'E o Senhor me livrará de toda má obra, e me levará salvo para o seu reino celestial; a quem seja glória para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 19, 'Saúda a Prisca e a Áquila e à casa de Onesíforo.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 20, 'Erasto ficou em Corinto; a Trófimo deixei doente em Mileto.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 21, 'Apressa-te a vir antes do inverno. Saúdam-te Êubulo, Pudente, Lino, Cláudia, e todos os irmãos.', 1, CURRENT_TIMESTAMP, false),
(55, 4, 22, 'O Senhor seja com o teu espírito. A graça seja convosco. ^Z', 1, CURRENT_TIMESTAMP, false),
(64, 1, 1, 'O ancião ao amado Gaio, a quem eu amo em verdade.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 2, 'Amado, desejo que te vá bem em todas as coisas, e que tenhas saúde, assim como bem vai à tua alma.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 3, 'Porque muito me alegrei quando os irmãos vieram e testificaram da tua verdade, como tu andas na verdade.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 4, 'Não tenho maior gozo do que este: o de ouvir que os meus filhos andam na verdade.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 5, 'Amado, procedes fielmente em tudo o que fazes para com os irmãos, especialmente para com os estranhos,', 1, CURRENT_TIMESTAMP, false),
(64, 1, 6, 'os quais diante da igreja testificaram do teu amor; aos quais, se os encaminhares na sua viagem de um modo digno de Deus, bem farás;', 1, CURRENT_TIMESTAMP, false),
(64, 1, 7, 'porque por amor do Nome saíram, sem nada aceitar dos gentios.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 8, 'Portanto aos tais devemos acolher, para que sejamos cooperadores da verdade.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 9, 'Escrevi alguma coisa à igreja; mas Diótrefes, que gosta de ter entre eles a primazia, não nos recebe.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 10, 'Pelo que, se eu aí for, trarei à memória as obras que ele faz, proferindo contra nós palavras maliciosas; e, não contente com isto, ele não somente deixa de receber os irmãos, mas aos que os querem receber ele proíbe de o fazerem e ainda os exclui da igreja.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 11, 'Amado, não imites o mal, mas o bem. Quem faz o bem é de Deus; mas quem faz o mal não tem visto a Deus.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 12, 'De Demétrio, porém, todos, e até a própria verdade, dão testemunho; e nós também damos testemunho; e sabes que o nosso testemunho é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 13, 'Tinha eu muitas coisas que te escrever, mas não o quero fazer com tinta e pena.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 14, 'Espero, porém, ver-te brevemente, e falaremos face a face.', 1, CURRENT_TIMESTAMP, false),
(64, 1, 15, 'Paz seja contigo. Os amigos te saúdam. Saúda os amigos nominalmente.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 1, 'No segundo ano do rei Dario, no sexto mês, no primeiro dia do mês, veio a palavra do Senhor, por intermédio do profeta Ageu, a Zorobabel, governador de Judá, filho de Sealtiel, e a Josué, o sumo sacerdote, filho de Jeozadaque, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 1, 2, 'Assim fala o Senhor dos exércitos, dizendo: Este povo diz: Não veio ainda o tempo, o tempo de se edificar a casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 3, 'Veio, pois, a palavra do Senhor, por intermédio do profeta Ageu, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 1, 4, 'Acaso é tempo de habitardes nas vossas casas forradas, enquanto esta casa fica desolada?', 1, CURRENT_TIMESTAMP, false),
(37, 1, 5, 'Ora pois, assim diz o Senhor dos exércitos: Considerai os vossos caminhos.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 6, 'Tendes semeado muito, e recolhido pouco; comeis, mas não vos fartais; bebeis, mas não vos saciais; vestis-vos, mas ninguém se aquece; e o que recebe salário, recebe-o para o meter num saco furado.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 7, 'Assim diz o Senhor dos exércitos: Considerai os vossos caminhos.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 8, 'Subi ao monte, e trazei madeira, e edificai a casa; e dela me deleitarei, e serei glorificado, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 9, 'Esperastes o muito, mas eis que veio a ser pouco; e esse pouco, quando o trouxestes para casa, eu o dissipei com um assopro. Por que causa? diz o Senhor dos exércitos. Por causa da minha casa, que está em ruínas, enquanto correis, cada um de vós, à sua própria casa.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 10, 'Por isso os céus por cima de vós retêm o orvalho, e a terra retém os seus frutos.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 11, 'E mandei vir a seca sobre a terra, e sobre as colinas, sobre o trigo e o mosto e o azeite, e sobre tudo o que a terra produz; como também sobre os homens e os animais, e sobre todo o seu trabalho.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 12, 'Então Zorobabel, filho de Sealtiel, e o sumo sacerdote Josué, filho de Jeozadaque, juntamente com todo o resto do povo, obedeceram a voz do Senhor seu Deus, e as palavras do profeta Ageu, como o Senhor seu Deus o tinha enviado; e temeu o povo diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 13, 'Então Ageu, o mensageiro do Senhor, falou ao povo, conforme a mensagem do Senhor, dizendo: Eu sou convosco, e diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(37, 1, 14, 'E o Senhor suscitou o espírito do governador de Judá Zorobabel, filho de Sealtiel, e o espírito do sumo sacerdote Josué, filho de Jeozadaque, e o espírito de todo o resto do povo; e eles vieram, e começaram a trabalhar na casa do Senhor dos exércitos, seu Deus,', 1, CURRENT_TIMESTAMP, false),
(37, 1, 15, 'ao vigésimo quarto dia do sexto mês.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 1, 'No segundo ano do rei Dario, no sétimo mês, ao vigésimo primeiro do mês, veio a palavra do Senhor por intermédio do profeta Ageu, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 2, 2, 'Fala agora ao governador de Judá, Zorobabel, filho de Sealtiel, e ao sumo sacerdote Josué, filho de Jeozadaque, e ao resto do povo, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 2, 3, 'Quem há entre vós, dos sobreviventes, que viu esta casa na sua primeira glória? Em que estado a vedes agora? Não é como nada em vossos olhos?', 1, CURRENT_TIMESTAMP, false),
(37, 2, 4, 'Ora, pois, esforça-te, Zorobabel, diz o Senhor, e esforça-te, sumo sacerdote Josué, filho de Jeozadaque, e esforçai-vos, todo o povo da terra, diz o Senhor, e trabalhai; porque eu sou convosco, diz o Senhor dos exércitos,', 1, CURRENT_TIMESTAMP, false),
(37, 2, 5, 'segundo o pacto que fiz convosco, quando saístes do Egito, e o meu Espírito habita no meio de vós; não temais.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 6, 'Pois assim diz o Senhor dos exércitos; Ainda uma vez, daqui a pouco, e abalarei os céus e a terra, o mar e a terra seca.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 7, 'Abalarei todas as nações; e as coisas preciosas de todas as nações virão, e encherei de glória esta casa, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 8, 'Minha é a prata, e meu é o ouro, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 9, 'A glória desta última casa será maior do que a da primeira, diz o Senhor dos exércitos; e neste lugar darei a paz, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 10, 'Ao vigésimo quarto dia do mês nono, no segundo ano de Dario, veio a palavra do Senhor ao profeta Ageu, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 2, 11, 'Assim diz o Senhor dos exércitos: Pergunta agora aos sacerdotes, acerca da lei, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 2, 12, 'Se alguém levar na aba de suas vestes carne santa, e com a sua aba tocar no pão, ou no guisado, ou no vinho, ou no azeite, ou em qualquer outro mantimento, ficará este santificado? E os sacerdotes responderam: Não.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 13, 'Então perguntou Ageu: Se alguém, que for contaminado pelo contato com o corpo morto, tocar nalguma destas coisas, ficará ela imunda? E os sacerdotes responderam: Ficará imunda.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 14, 'Ao que respondeu Ageu, dizendo: Assim é este povo, e assim é esta nação diante de mim, diz o Senhor; assim é toda a obra das suas mãos; e tudo o que ali oferecem imundo é.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 15, 'Agora considerai o que acontece desde aquele dia. Antes que se lançasse pedra sobre pedra no templo do Senhor,', 1, CURRENT_TIMESTAMP, false),
(37, 2, 16, 'quando alguém vinha a um montão de trigo de vinte medidas, havia somente dez; quando vinha ao lagar para tirar cinqüenta, havia somente vinte.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 17, 'Feri-vos com mangra, e com ferrugem, e com saraiva, em todas as obras das vossas mãos; e não houve entre vós quem voltasse para mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 18, 'Considerai, pois, eu vos rogo, desde este dia em diante, desde o vigésimo quarto dia do mês nono, desde o dia em que se lançaram os alicerces do templo do Senhor, sim, considerai essas coisas.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 19, 'Está ainda semente no celeiro? A videira, a figueira, a romeira, e a oliveira ainda não dão os seus frutos? Desde este dia hei de vos abençoar.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 20, 'Veio pela segunda vez a palavra do Senhor a Ageu, aos vinte e quatro do mês, dizendo:', 1, CURRENT_TIMESTAMP, false),
(37, 2, 21, 'Fala a Zorobabel, governador de Judá, dizendo: Abalarei os céus e a terra;', 1, CURRENT_TIMESTAMP, false),
(37, 2, 22, 'e derrubarei o trono dos reinos, e destruirei a força dos reinos das nações; destruirei o carro e os que nele andam; os cavalos e os seus cavaleiros cairão, cada um pela espada do seu irmão.', 1, CURRENT_TIMESTAMP, false),
(37, 2, 23, 'Naquele dia, diz o Senhor dos exércitos, tomar-te-ei, ó Zorobabel, servo meu, filho de Sealtiel, diz o Senhor, e te farei como um anel de selar; porque te escolhi, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 1, 'As palavras de Amós, que estava entre os pastores de Tecoa, o que ele viu a respeito de Israel, nos dias de Uzias, rei de Judá, e nos dias de Jeroboão, filho de Joás, rei de Israel, dois anos antes do terremoto.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 2, 'Disse ele: O Senhor brama de Sião, e de Jerusalém faz ouvir a sua voz; os prados dos pastores lamentam, seca-se o cume do Carmelo.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 3, 'Assim diz o senhor: Por três transgressões de Damasco, sim, por quatro, não retirarei o castigo; porque trilharam a Gileade com trilhos de ferro.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 4, 'Por isso porei fogo à casa de Hazael, e ele consumirá os palácios de Ben-Hadade.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 5, 'Quebrarei o ferrolho de Damasco, e exterminarei o morador do vale de Ávem e de Bete-Éden aquele que tem o cetro; e o povo da Síria será levado em cativeiro a Quir, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 6, 'Assim diz o Senhor: Por três transgressões de Gaza, sim, por quatro, não retirarei o castigo; porque levaram cativo todo o povo para o entregarem a Edom.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 7, 'Por isso porei fogo ao muro de Gaza, e ele consumirá os seus palácios.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 8, 'De Asdode exterminarei o morador, e de Asquelom aquele que tem o cetro; tornarei a minha mão contra Ecrom; e o resto dos filisteus perecerá, diz o Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 9, 'Assim diz o Senhor: Por três transgressões de Tiro, sim, por quatro, não retirarei o castigo; porque entregaram todos os cativos a Edom, e não se lembraram da aliança dos irmãos.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 10, 'por isso porei fogo ao muro de Tiro, e ele consumirá os seus palácios.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 11, 'Assim diz o Senhor: Por três transgressões de Edom, sim, por quatro, não retirarei o castigo; porque perseguiu a seu irmão à espada, e baniu toda a compaixão; e a sua ira despedaçou eternamente, e conservou a sua indignação para sempre.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 12, 'Por isso porei fogo a Temã, o qual consumirá os palácios de Bozra.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 13, 'Assim diz o Senhor: Por três transgressões dos filhos de Amom, sim por quatro, não retirarei o castigo; porque fenderam o ventre às grávidas de Gileade, para dilatarem os seus termos.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 14, 'Por isso porei fogo ao muro de Rabá, fogo que lhe consumirá os palácios, com alarido no dia da batalha, com tempestade no dia do turbilhão.', 1, CURRENT_TIMESTAMP, false),
(30, 1, 15, 'E o seu rei irá para o cativeiro, ele e os seus príncipes juntamente, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 1, 'Assim diz o Senhor: Por três transgressões de Moabe, sim, por quatro, não retirarei o castigo; porque queimou os ossos do rei de Edom, até os reduzir a cal.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 2, 'Por isso porei fogo a Moabe, e ele consumirá os palácios de Queriote; e Moabe morrerá com grande estrondo, com alarido, e som de trombeta.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 3, 'E exterminarei o juiz do meio dele, e matarei com ele todos os seus príncipes, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 4, 'Assim diz o Senhor: Por três transgressões de Judá, sim, por quatro, não retirarei o castigo; porque rejeitaram a lei do Senhor, e não guardaram os seus estatutos, antes se deixaram enganar por suas próprias mentiras, após as quais andaram seus pais.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 5, 'Por isso porei fogo a Judá, e ele consumirá os palácios de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 6, 'Assim diz o Senhor: Por três transgressões de Israel, sim, por quatro, não retirarei o castigo; porque vendem o justo por dinheiro, e o necessitado por um par de sapatos.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 7, 'Pisam a cabeça dos pobres no pó da terra, pervertem o caminho dos mansos; um homem e seu pai entram à mesma moça, assim profanando o meu santo nome.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 8, 'Também se deitam junto a qualquer altar sobre roupas empenhadas, e na casa de seu Deus bebem o vinho dos que têm sido multados.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 9, 'Contudo eu destruí o amorreu diante deles, a altura do qual era como a dos cedros, e cuja força era como a dos carvalhos; mas destruí o seu fruto por cima, e as suas raízes por baixo.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 10, 'Outrossim vos fiz subir da terra do Egito, e quarenta anos vos guiei no deserto, para que possuísseis a terra do amorreu.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 11, 'E dentre vossos filhos suscitei profetas, e dentre os vossos mancebos, nazireus. Acaso não é isso assim, filhos de Israel? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 12, 'Mas vós aos nazireus destes vinho a beber, e aos profetas ordenastes, dizendo: Não profetizeis.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 13, 'Eis que eu vos apertarei no vosso lugar como se aperta um carro cheio de feixes.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 14, 'Assim de nada valerá a fuga ao ágil, nem o forte corroborará a sua força, nem o valente salvará a sua vida.', 1, CURRENT_TIMESTAMP, false),
(30, 2, 15, 'E não ficará em pé o que maneja o arco, nem o ligeiro de pés se livrará, nem tampouco se livrara o que vai montado a cavalo;', 1, CURRENT_TIMESTAMP, false),
(30, 2, 16, 'e aquele que é corajoso entre os valentes fugirá nu naquele dia, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 1, 'Ouvi esta palavra que o Senhor fala contra vós, filhos de Israel, contra toda a família que fiz subir da terra do Egito, dizendo:', 1, CURRENT_TIMESTAMP, false),
(30, 3, 2, 'De todas as famílias da terra só a vós vos tenho conhecido; portanto eu vos punirei por todas as vossas iniqüidades.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 3, 'Acaso andarão dois juntos, se não estiverem de acordo?', 1, CURRENT_TIMESTAMP, false),
(30, 3, 4, 'Bramirá o leão no bosque, sem que tenha presa? Fará ouvir a sua voz o leão novo no seu covil, se nada tiver apanhado?', 1, CURRENT_TIMESTAMP, false),
(30, 3, 5, 'Cairá a ave no laço em terra, se não houver armadilha para ela? levantar-se-á da terra o laço, sem que tenha apanhado alguma coisa?', 1, CURRENT_TIMESTAMP, false),
(30, 3, 6, 'Tocar-se-á a trombeta na cidade, e o povo não estremecerá? Sucederá qualquer mal à cidade, sem que o Senhor o tenha feito?', 1, CURRENT_TIMESTAMP, false),
(30, 3, 7, 'Certamente o Senhor Deus não fará coisa alguma, sem ter revelado o seu segredo aos seus servos, os profetas.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 8, 'Bramiu o leão, quem não temerá? Falou o Senhor Deus, quem não profetizará?', 1, CURRENT_TIMESTAMP, false),
(30, 3, 9, 'Proclamai nos palácios de Asdode, e nos palácios da terra do Egito, e dizei: Ajuntai-vos sobre os montes de Samária, e vede que grandes alvoroços nela há, e que opressões no meio dela.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 10, 'Pois não sabem fazer o que é reto, diz o Senhor, aqueles que entesouram nos seus palácios a violência e a destruição.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 11, 'Portanto, o Senhor Deus diz assim: um inimigo cercará a tua terra; derrubará a tua fortaleza, e os teus palácios serão saqueados.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 12, 'Assim diz o Senhor: Como o pastor livra da boca do leão as duas pernas, ou um pedacinho da orelha, assim serão livrados os filhos de Israel que habitam em Samária, junto com um canto do leito e um pedaço da cama.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 13, 'Ouvi, e protestai contra a casa de Jacó, diz o Senhor Deus, o Deus dos exércitos:', 1, CURRENT_TIMESTAMP, false),
(30, 3, 14, 'Pois no dia em que eu punir as transgressões de Israel, também castigarei os altares de Betel; e as pontas do altar serão cortadas, e cairão por terra.', 1, CURRENT_TIMESTAMP, false),
(30, 3, 15, 'Derribarei a casa de inverno juntamente com a casa de verão; as casas de marfim perecerão, e as grandes casas terão fim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 1, 'Ouvi esta palavra, vós, vacas de Basã, que estais no monte de Samária, que oprimis os pobres, que esmagais os necessitados, que dizeis a vossos maridos: Dai cá, e bebamos.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 2, 'Jurou o Senhor Deus, pela sua santidade, que dias estão para vir sobre vós, em que vos levarão com anzóis, e aos que sairdes por último com anzóis de pesca.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 3, 'E saireis pelas brechas, cada qual em frente de si, e sereis lançadas para Harmom, diz o senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 4, 'Vinde a Betel, e transgredi; a Gilgal, e multiplicai as transgressões; e cada manhã trazei os vossos sacrifícios, e de três em três dias os vossos dízimos.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 5, 'E oferecei sacrifício de louvores do que é levedado, e apregoai ofertas voluntárias, publicai-as; pois disso gostais, ó filhos de Israel, diz o Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 6, 'Por isso também vos dei limpeza de dentes em todas as vossas cidades, e falta de pão em todos os vossos lugares; contudo não vos convertestes a mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 7, 'Além disso, retive de vós a chuva, quando ainda faltavam três meses para a ceifa; e fiz que chovesse sobre uma cidade, e que não chovesse sobre outra cidade; sobre um campo choveu, mas o outro, sobre o qual não choveu, secou-se.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 8, 'Andaram errantes duas ou três cidades, indo a outra cidade para beberem água, mas não se saciaram; contudo não vos convertestes a mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 9, 'Feri-vos com crestamento e ferrugem; a multidão das vossas hortas, e das vossas vinhas, e das vossas figueiras, e das vossas oliveiras, foi devorada pela locusta; contudo não vos convertestes a mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 10, 'Enviei a peste contra vós, à maneira de Egito; os vossos mancebos matei à espada, e os vossos cavalos deixei levar presos, e o fedor do vosso arraial fiz subir aos vossos narizes; contudo não vos convertestes a mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 11, 'Subverti alguns dentre vós, como Deus subverteu a Sodoma e Gomorra, e ficastes sendo como um tição arrebatado do incêndio; contudo não vos convertestes a mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 12, 'Portanto assim te farei, ó Israel, e porque isso te farei, prepara-te, ó Israel, para te encontrares com o teu Deus.', 1, CURRENT_TIMESTAMP, false),
(30, 4, 13, 'Porque é ele o que forma os montes, e cria o vento, e declara ao homem qual seja o seu pensamento, o que faz da manhã trevas, e anda sobre os lugares altos da terra; o Senhor, o Deus dos exércitos é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 1, 'Ouvi esta palavra que levanto como lamentação sobre vós, ó casa de Israel.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 2, 'A virgem de Israel caiu; nunca mais tornará a levantar-se; desamparada jaz na sua terra; não há quem a levante.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 3, 'Porque assim diz o Senhor Deus: A cidade da qual saem mil terá de resto cem, e aquela da qual saem cem terá dez para a casa de Israel.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 4, 'Pois assim diz o Senhor à casa de Israel: Buscai-me, e vivei.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 5, 'Mas não busqueis a Betel, nem entreis em Gilgal, nem passeis a Berseba; porque Gilgal certamente irá ao cativeiro, e Betel será desfeita em nada.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 6, 'Buscai ao Senhor, e vivei; para que ele não irrompa na casa de José como fogo e a consuma, e não haja em Betel quem o apague.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 7, 'Vós que converteis o juízo em alosna, e deitais por terra a justiça,', 1, CURRENT_TIMESTAMP, false),
(30, 5, 8, 'procurai aquele que fez as Plêiades e o Oriom, e torna a sombra da noite em manhã, e transforma o dia em noite; o que chama as águas do mar, e as derrama sobre a terra; o Senhor é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 9, 'O que faz vir súbita destruição sobre o forte, de sorte que vem a ruína sobre a fortaleza.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 10, 'Eles odeiam ao que na porta os repreende, e abominam ao que fala a verdade.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 11, 'Portanto, visto que pisais o pobre, e dele exigis tributo de trigo, embora tenhais edificado casas de pedras lavradas, não habitareis nelas; e embora tenhais plantado vinhas desejáveis, não bebereis do seu vinho.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 12, 'Pois sei que são muitas as vossas transgressões, e graves os vossos pecados; afligis o justo, aceitais peitas, e na porta negais o direito aos necessitados.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 13, 'Portanto, o que for prudente guardará silêncio naquele tempo, porque o tempo será mau.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 14, 'Buscai o bem, e não o mal, para que vivais; e assim o Senhor, o Deus dos exércitos, estará convosco, como dizeis.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 15, 'Aborrecei o mal, e amai o bem, e estabelecei o juízo na porta. Talvez o Senhor, o Deus dos exércitos, tenha piedade do resto de José.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 16, 'Portanto, assim diz o Senhor Deus dos exércitos, o Senhor: Em todas as praças haverá pranto, e em todas as ruas dirão: Ai! ai! E ao lavrador chamarão para choro, e para pranto os que souberem prantear.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 17, 'E em todas as vinhas haverá pranto; porque passarei pelo meio de ti, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 18, 'Ai de vós que desejais o dia do Senhor! Para que quereis vós este dia do Senhor? Ele é trevas e não luz.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 19, 'E como se um homem fugisse de diante do leão, e se encontrasse com ele o urso; ou como se, entrando em casa, encostasse a mão à parede, e o mordesse uma cobra.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 20, 'Não será, pois, o dia do Senhor trevas e não luz? não será completa escuridade, sem nenhum resplendor?', 1, CURRENT_TIMESTAMP, false),
(30, 5, 21, 'Aborreço, desprezo as vossas festas, e não me deleito nas vossas assembléias solenes.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 22, 'Ainda que me ofereçais holocaustos, juntamente com as vossas ofertas de cereais, não me agradarei deles; nem atentarei para as ofertas pacíficas de vossos animais cevados.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 23, 'Afasta de mim o estrépito dos teus cânticos, porque não ouvirei as melodias das tuas liras.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 24, 'Corra, porém, a justiça como as águas, e a retidão como o ribeiro perene.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 25, 'Oferecestes-me vós sacrifícios e oblações no deserto por quarenta anos, ó casa de Israel?', 1, CURRENT_TIMESTAMP, false),
(30, 5, 26, 'Sim, levastes Sicute, vosso rei, e Quium, vosso deus-estrela, imagens que fizestes para vos mesmos.', 1, CURRENT_TIMESTAMP, false),
(30, 5, 27, 'Portanto vos levarei cativos para além de Damasco, diz o Senhor, cujo nome é o Deus dos Exércitos.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 1, 'Ai dos que vivem sossegados em Sião, e dos que estão seguros no monte de Samária, dos homens notáveis da principal das nações, e aos quais vem a casa de Israel!', 1, CURRENT_TIMESTAMP, false),
(30, 6, 2, 'Passai a Calné, e vede; e dali ide à grande Hamate; depois descei a Gate dos filisteus; porventura são melhores que estes reinos? ou são maiores os seus termos do que os vossos termos?', 1, CURRENT_TIMESTAMP, false),
(30, 6, 3, 'ó vós que afastais o dia mau e fazeis que se aproxime o assento da violência.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 4, 'Ai dos que dormem em camas de marfim, e se estendem sobre os seus leitos, e comem os cordeiros tirados do rebanho, e os bezerros do meio do curral;', 1, CURRENT_TIMESTAMP, false),
(30, 6, 5, 'que garganteiam ao som da lira, e inventam para si instrumentos músicos, assim como Davi;', 1, CURRENT_TIMESTAMP, false),
(30, 6, 6, 'que bebem vinho em taças, e se ungem com o mais excelente óleo; mas não se afligem por causa da ruína de José!', 1, CURRENT_TIMESTAMP, false),
(30, 6, 7, 'Portanto agora irão em cativeiro entre os primeiros que forem cativos; e cessarão os festins dos banqueteadores.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 8, 'Jurou o Senhor Deus por si mesmo, diz o Senhor Deus dos exércitos: Abomino a soberba de Jacó, e odeio os seus palácios; por isso entregarei a cidade e tudo o que nela há.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 9, 'E se ficarem de resto dez homens numa casa, morrerão.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 10, 'Quando o parente de alguém, aquele que o queima, o tomar para levar-lhe os ossos para fora da casa, e disser ao que estiver no mais interior da casa: Está ainda alguém contigo? e este responder: Ninguém; então lhe dirá ele: Cala-te, porque não devemos fazer menção do nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 11, 'Pois eis que o Senhor ordena, e a casa grande será despedaçada, e a casa pequena reduzida a fragmentos.', 1, CURRENT_TIMESTAMP, false),
(30, 6, 12, 'Acaso correrão cavalos pelos rochedos? Lavrar-se-á ali com bois? Mas vós haveis tornado o juízo em fel, e o fruto da justiça em alosna;', 1, CURRENT_TIMESTAMP, false),
(30, 6, 13, 'vós que vos alegrais de nada, vós que dizeis: Não nos temos nós tornado poderosos por nossa própria força?', 1, CURRENT_TIMESTAMP, false),
(30, 6, 14, 'Pois eis que eu levantarei contra vós, ó casa de Israel, uma nação, diz o Senhor Deus dos exércitos, e ela vos oprimirá, desde a entrada de Hamate até o ribeiro da Arabá.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 1, 'O Senhor Deus assim me fez ver: e eis que ele formava gafanhotos no princípio do rebentar da erva serôdia, e eis que era a erva serôdia depois da segada do rei.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 2, 'E quando eles tinham comido completamente a erva da terra, eu disse: Senhor Deus, perdoa, peço-te; como subsistirá Jacó? pois ele é pequeno.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 3, 'Então o Senhor se arrependeu disso. Não acontecerá, disse o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 4, 'Assim me mostrou o Senhor Deus: eis que o Senhor Deus ordenava que por meio do fogo se decidisse o pleito; o fogo, pois, consumiu o grande abismo, e também queria consumir a terra.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 5, 'Então eu disse: Senhor Deus, cessa agora; como subsistirá Jacó? pois ele é pequeno.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 6, 'Também disso se arrependeu o Senhor. Nem isso acontecerá, disse o Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 7, 'Mostrou-me também assim: eis que o senhor estava junto a um muro levantado a prumo, e tinha um prumo na mão.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 8, 'Perguntou-me o Senhor: Que vês tu, Amós? Respondi: Um prumo. Então disse o Senhor: Eis que eu porei o prumo no meio do meu povo Israel; nunca mais passarei por ele.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 9, 'Mas os altos de Isaque serão assolados, e destruídos os santuários de Israel; e levantar-me-ei com a espada contra a casa de Jeroboão.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 10, 'Então Amazias, o sacerdote de Betel, mandou dizer a Jeroboão, rei de Israel: Amós tem conspirado contra ti no meio da casa de Israel; a terra não poderá suportar todas as suas palavras.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 11, 'Pois assim diz Amós: Jeroboão morrerá à espada, e Israel certamente será levado cativo para fora da sua terra.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 12, 'Depois Amazias disse a Amós: Vai-te, ó vidente, foge para a terra de Judá, e ali come o pão, e ali profetiza;', 1, CURRENT_TIMESTAMP, false),
(30, 7, 13, 'mas em Betel daqui por diante não profetizarás mais, porque é o santuário do rei, e é templo do reino.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 14, 'E respondeu Amós, e disse a Amazias: Eu não sou profeta, nem filho de profeta, mas boieiro, e cultivador de sicômoros.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 15, 'Mas o Senhor me tirou de após o gado, e o Senhor me disse: Vai, profetiza ao meu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 16, 'Agora, pois, ouve a palavra do Senhor: Tu dizes: Não profetizes contra Israel, nem fales contra a casa de Isaque.', 1, CURRENT_TIMESTAMP, false),
(30, 7, 17, 'Portanto assim diz o Senhor: Tua mulher se prostituirá na cidade, e teus filhos e tuas filhas cairão à espada, e a tua terra será repartida a cordel; e tu morrerás numa terra imunda, e Israel certamente será levado cativo para fora da sua terra.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 1, 'O Senhor Deus assim me fez ver: e eis aqui um cesto de frutos do verão.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 2, 'E disse: Que vês, Amós? Eu respondi: um cesto de frutos do verão. Então o Senhor me disse: Chegou o fim sobre o meu povo Israel; nunca mais passarei por ele.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 3, 'Mas os cânticos do templo serão gritos de dor naquele dia, diz o Senhor Deus; muitos serão os cadáveres; em todos os lugares serão lançados fora em silêncio.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 4, 'Ouvi isto, vós que pisais os necessitados, e destruís os miseráveis da terra,', 1, CURRENT_TIMESTAMP, false),
(30, 8, 5, 'dizendo: Quando passará a lua nova, para vendermos o grão? e o sábado, para expormos o trigo, diminuindo a medida, e aumentando o preço, e procedendo dolosamente com balanças enganadoras,', 1, CURRENT_TIMESTAMP, false),
(30, 8, 6, 'para comprarmos os pobres por dinheiro, e os necessitados por um par de sapatos, e para vendermos o refugo do trigo?', 1, CURRENT_TIMESTAMP, false),
(30, 8, 7, 'Jurou o Senhor pela glória de Jacó: Certamente nunca me esquecerei de nenhuma das suas obras.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 8, 'Por causa disso não estremecerá a terra? e não chorará todo aquele que nela habita? Certamente se levantará ela toda como o Nilo, e será agitada, e diminuirá como o Nilo do Egito.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 9, 'E sucederá, naquele dia, diz o Senhor Deus, que farei que o sol se ponha ao meio dia, e em pleno dia cobrirei a terra de trevas.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 10, 'E tornarei as vossas festas em luto, e todos os vossos cânticos em lamentações; porei saco sobre todos os lombos, e calva sobre toda cabeça; e farei que isso seja como o luto por um filho único, e o seu fim como dia de amarguras.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 11, 'Eis que vêm os dias, diz o Senhor Deus, em que enviarei fome sobre a terra; não fome de pão, nem sede de água, mas de ouvir as palavras do Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 12, 'Andarão errantes de mar a mar, e do norte até o oriente; correrão por toda parte, buscando a palavra do Senhor, e não a acharão.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 13, 'Naquele dia as virgens formosas e os mancebos desmaiarão de sede.', 1, CURRENT_TIMESTAMP, false),
(30, 8, 14, 'Os que juram pelo pecado de Samária, dizendo: Pela vida do teu deus, ó Dã; e: Pelo caminho de Berseba; esses mesmos cairão, e não se levantarão mais.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 1, 'Vi o Senhor, que estava junto ao altar; e me disse: Fere os capitéis, para que estremeçam os umbrais; e faze tudo em pedaços sobre a cabeça de todos eles; e eu matarei à espada até o último deles; nenhum deles conseguirá fugir, nenhum deles escapará.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 2, 'Ainda que cavem até o Seol, dali os tirará a minha mão; ainda que subam ao céu, dali os farei descer.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 3, 'Ainda que se escondam no cume do Carmelo, buscá-los-ei, e dali os tirarei; e, ainda que se ocultem aos meus olhos no fundo do mar, ali darei ordem à serpente, e ela os morderá.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 4, 'Também ainda que vão para o cativeiro diante de seus inimigos, ali darei ordem à espada, e ela os matará; enfim eu porei os meus olhos sobre eles para o mal, e não para o bem.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 5, 'Pois o Senhor, o Deus dos exércitos, é o que toca a terra, e ela se derrete, e pranteiam todos os que nela habitam; e ela toda se levanta como o Nilo, e diminui como o Nilo do Egito.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 6, 'Ele é o que edifica as suas câmaras no céu, e funda sobre a terra a sua abóbada; que chama as águas do mar, e as derrama sobre a terra; o Senhor é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 7, 'Não sois vós para comigo, ó filhos de Israel, como os filhos dos etíopes? diz o Senhor; não fiz eu subir a Israel da terra do Egito, e aos filisteus de Caftor, e aos sírios de Quir?', 1, CURRENT_TIMESTAMP, false),
(30, 9, 8, 'Eis que os olhos do Senhor Deus estão contra este reino pecador, e eu o destruirei de sobre a face da terra; contudo não destruirei de todo a casa de Jacó, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 9, 'Pois eis que darei ordens, e sacudirei a casa de Israel em todas as nações, assim como se sacode grão no crivo; todavia não cairá sobre a terra um só grão.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 10, 'Morrerão à espada todos os pecadores do meu povo, os quais dizem: O mal não nos alcançará, nem nos encontrará.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 11, 'Naquele dia tornarei a levantar o tabernáculo de Davi, que está caído, e repararei as suas brechas, e tornarei a levantar as suas ruínas, e as reedificarei como nos dias antigos;', 1, CURRENT_TIMESTAMP, false),
(30, 9, 12, 'para que eles possuam o resto de Edom, e todas as nações que são chamadas pelo meu nome, diz o Senhor, que faz estas coisas.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 13, 'Eis que vêm os dias, diz o Senhor, em que o que lavra alcançará ao que sega, e o que pisa as uvas ao que lança a semente; :e os montes destilarão mosto, e todos os outeiros se derreterão.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 14, 'Também trarei do cativeiro o meu povo Israel; e eles reedificarão as cidades assoladas, e nelas habitarão; plantarão vinhas, e beberão o seu vinho; e farão pomares, e lhes comerão o fruto.', 1, CURRENT_TIMESTAMP, false),
(30, 9, 15, 'Assim os plantarei na sua terra, e não serão mais arrancados da sua terra que lhes dei, diz o senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 1, 'Revelação de Jesus Cristo, que Deus lhe deu para mostrar aos seus servos as coisas que brevemente devem acontecer; e, enviando-as pelo seu anjo, as notificou a seu servo João;', 1, CURRENT_TIMESTAMP, false),
(66, 1, 2, 'o qual testificou da palavra de Deus, e do testemunho de Jesus Cristo, de tudo quanto viu.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 3, 'Bem-aventurado aquele que lê e bem-aventurados os que ouvem as palavras desta profecia e guardam as coisas que nela estão escritas; porque o tempo está próximo.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 4, 'João, às sete igrejas que estão na Ásia: Graça a vós e paz da parte daquele que é, e que era, e que há de vir, e da dos sete espíritos que estão diante do seu trono;', 1, CURRENT_TIMESTAMP, false),
(66, 1, 5, 'e da parte de Jesus Cristo, que é a fiel testemunha, o primogênito dos mortos e o Príncipe dos reis da terra. Àquele que nos ama, e pelo seu sangue nos libertou dos nossos pecados,', 1, CURRENT_TIMESTAMP, false),
(66, 1, 6, 'e nos fez reino, sacerdotes para Deus, seu Pai, a ele seja glória e domínio pelos séculos dos séculos. Amém.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 7, 'Eis que vem com as nuvens, e todo olho o verá, até mesmo aqueles que o traspassaram; e todas as tribos da terra se lamentarão sobre ele. Sim. Amém.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 8, 'Eu sou o Alfa e o Ômega, diz o Senhor Deus, aquele que é, e que era, e que há de vir, o Todo-Poderoso.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 9, 'Eu, João, irmão vosso e companheiro convosco na aflição, no reino, e na perseverança em Jesus, estava na ilha chamada Patmos por causa da palavra de Deus e do testemunho de Jesus.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 10, 'Eu fui arrebatado em espírito no dia do Senhor, e ouvi por detrás de mim uma grande voz, como de trombeta,', 1, CURRENT_TIMESTAMP, false),
(66, 1, 11, 'que dizia: O que vês, escreve-o num livro, e envia-o às sete igrejas: a Éfeso, a Esmirna, a Pérgamo, a Tiatira, a Sardes, a Filadélfia e a Laodicéia.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 12, 'E voltei-me para ver quem falava comigo. E, ao voltar-me, vi sete candeeiros de ouro,', 1, CURRENT_TIMESTAMP, false),
(66, 1, 13, 'e no meio dos candeeiros um semelhante a filho de homem, vestido de uma roupa talar, e cingido à altura do peito com um cinto de ouro;', 1, CURRENT_TIMESTAMP, false),
(66, 1, 14, 'e a sua cabeça e cabelos eram brancos como lã branca, como a neve; e os seus olhos como chama de fogo;', 1, CURRENT_TIMESTAMP, false),
(66, 1, 15, 'e os seus pés, semelhantes a latão reluzente que fora refinado numa fornalha; e a sua voz como a voz de muitas águas.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 16, 'Tinha ele na sua destra sete estrelas; e da sua boca saía uma aguda espada de dois gumes; e o seu rosto era como o sol, quando resplandece na sua força.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 17, 'Quando o vi, caí a seus pés como morto; e ele pôs sobre mim a sua destra, dizendo: Não temas; eu sou o primeiro e o último.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 18, 'Eu sou o que vivo; fui morto, mas eis aqui estou vivo para todo o sempre! e tenho as chaves da morte e do inferno.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 19, 'Escreve, pois, as coisas que tens visto, e as que são, e as que depois destas hão de suceder.', 1, CURRENT_TIMESTAMP, false),
(66, 1, 20, 'Eis o mistério das sete estrelas, que viste na minha destra, e dos sete candeeiros de ouro: as estrelas são os anjos das sete igrejas, e os sete candeeiros são as sete igrejas.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 1, 'Ao anjo da igreja em Éfeso escreve: Isto diz aquele que tem na sua destra as sete estrelas, que anda no meio dos sete candeeiros de ouro:', 1, CURRENT_TIMESTAMP, false),
(66, 2, 2, 'Conheço as tuas obras, e o teu trabalho, e a tua perseverança; sei que não podes suportar os maus, e que puseste à prova os que se dizem apóstolos e não o são, e os achaste mentirosos;', 1, CURRENT_TIMESTAMP, false),
(66, 2, 3, 'e tens perseverança e por amor do meu nome sofreste, e não desfaleceste.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 4, 'Tenho, porém, contra ti que deixaste o teu primeiro amor.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 5, 'Lembra-te, pois, donde caíste, e arrepende-te, e pratica as primeiras obras; e se não, brevemente virei a ti, e removerei do seu lugar o teu candeeiro, se não te arrependeres.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 6, 'Tens, porém, isto, que aborreces as obras dos nicolaítas, as quais eu também aborreço.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 7, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas. Ao que vencer, dar-lhe-ei a comer da árvore da vida, que está no paraíso de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 8, 'Ao anjo da igreja em Esmirna escreve: Isto diz o primeiro e o último, que foi morto e reviveu:', 1, CURRENT_TIMESTAMP, false),
(66, 2, 9, 'Conheço a tua tribulação e a tua pobreza {mas tu és rico}, e a blasfêmia dos que dizem ser judeus, e não o são, porém são sinagoga de Satanás.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 10, 'Não temas o que hás de padecer. Eis que o Diabo está para lançar alguns de vós na prisão, para que sejais provados; e tereis uma tribulação de dez dias. Sê fiel até a morte, e dar-te-ei a coroa da vida.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 11, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas. O que vencer, de modo algum sofrerá o dado da segunda morte.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 12, 'Ao anjo da igreja em Pérgamo escreve: Isto diz aquele que tem a espada aguda de dois gumes:', 1, CURRENT_TIMESTAMP, false),
(66, 2, 13, 'Sei onde habitas, que é onde está o trono de Satanás; mas reténs o meu nome e não negaste a minha fé, mesmo nos dias de Antipas, minha fiel testemunha, o qual foi morto entre vós, onde Satanás habita.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 14, 'entretanto, algumas coisas tenho contra ti; porque tens aí os que seguem a doutrina de Balaão, o qual ensinava Balaque a lançar tropeços diante dos filhos de Israel, introduzindo-os a comerem das coisas sacrificadas a ídolos e a se prostituírem.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 15, 'Assim tens também alguns que de igual modo seguem a doutrina dos nicolaítas.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 16, 'Arrepende-te, pois; ou se não, virei a ti em breve, e contra eles batalharei com a espada da minha boca.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 17, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas. Ao que vencer darei do maná escondido, e lhe darei uma pedra branca, e na pedra um novo nome escrito, o qual ninguém conhece senão aquele que o recebe.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 18, 'Ao anjo da igreja em Tiatira escreve: Isto diz o Filho de Deus, que tem os olhos como chama de fogo, e os pés semelhantes a latão reluzente:', 1, CURRENT_TIMESTAMP, false),
(66, 2, 19, 'Conheço as tuas obras, e o teu amor, e a tua fé, e o teu serviço, e a tua perseverança, e sei que as tuas últimas obras são mais numerosas que as primeiras.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 20, 'Mas tenho contra ti que toleras a mulher Jezabel, que se diz profetisa; ela ensina e seduz os meus servos a se prostituírem e a comerem das coisas sacrificadas a ídolos;', 1, CURRENT_TIMESTAMP, false),
(66, 2, 21, 'e dei-lhe tempo para que se arrependesse; e ela não quer arrepender-se da sua prostituição.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 22, 'Eis que a lanço num leito de dores, e numa grande tribulação os que cometem adultério com ela, se não se arrependerem das obras dela;', 1, CURRENT_TIMESTAMP, false),
(66, 2, 23, 'e ferirei de morte a seus filhos, e todas as igrejas saberão que eu sou aquele que esquadrinha os rins e os corações; e darei a cada um de vós segundo as suas obras.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 24, 'Digo-vos, porém, a vós os demais que estão em Tiatira, a todos quantos não têm esta doutrina, e não conhecem as chamadas profundezas de Satanás, que outra carga vos não porei;', 1, CURRENT_TIMESTAMP, false),
(66, 2, 25, 'mas o que tendes, retende-o até que eu venha.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 26, 'Ao que vencer, e ao que guardar as minhas obras até o fim, eu lhe darei autoridade sobre as nações,', 1, CURRENT_TIMESTAMP, false),
(66, 2, 27, 'e com vara de ferro as regerá, quebrando-as do modo como são quebrados os vasos do oleiro, assim como eu recebi autoridade de meu Pai;', 1, CURRENT_TIMESTAMP, false),
(66, 2, 28, 'também lhe darei a estrela da manhã.', 1, CURRENT_TIMESTAMP, false),
(66, 2, 29, 'Quem tem ouvidos, ouça o que o Espírito dia às igrejas.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 1, 'Ao anjo da igreja em Sardes escreve: Isto diz aquele que tem os sete espíritos de Deus, e as estrelas: Conheço as tuas obras; tens nome de que vives, e estás morto.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 2, 'Sê vigilante, e confirma o restante, que estava para morrer; porque não tenho achado as tuas obras perfeitas diante do meu Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 3, 'Lembra-te, portanto, do que tens recebido e ouvido, e guarda-o, e arrepende-te. Pois se não vigiares, virei como um ladrão, e não saberás a que hora sobre ti virei.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 4, 'Mas também tens em Sardes algumas pessoas que não contaminaram as suas vestes e comigo andarão vestidas de branco, porquanto são dignas.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 5, 'O que vencer será assim vestido de vestes brancas, e de maneira nenhuma riscarei o seu nome do livro da vida; antes confessarei o seu nome diante de meu Pai e diante dos seus anjos.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 6, 'Quem tem ouvidos, ouça o que o espírito diz às igrejas.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 7, 'Ao anjo da igreja em Filadélfia escreve: Isto diz o que é santo, o que é verdadeiro, o que tem a chave de Davi; o que abre, e ninguém fecha; e fecha, e ninguém abre:', 1, CURRENT_TIMESTAMP, false),
(66, 3, 8, 'Conheço as tuas obras {eis que tenho posto diante de ti uma porta aberta, que ninguém pode fechar}, que tens pouca força, entretanto guardaste a minha palavra e não negaste o meu nome.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 9, 'Eis que farei aos da sinagoga de Satanás, aos que se dizem judeus, e não o são, mas mentem, eis que farei que venham, e adorem prostrados aos teus pés, e saibam que eu te amo.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 10, 'Porquanto guardaste a palavra da minha perseverança, também eu te guardarei da hora da provação que há de vir sobre o mundo inteiro, para pôr à prova os que habitam sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 11, 'Venho sem demora; guarda o que tens, para que ninguém tome a tua coroa.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 12, 'A quem vencer, eu o farei coluna no templo do meu Deus, donde jamais sairá; e escreverei sobre ele o nome do meu Deus, e o nome da cidade do meu Deus, a nova Jerusalém, que desce do céu, da parte do meu Deus, e também o meu novo nome.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 13, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 14, 'Ao anjo da igreja em Laodicéia escreve: Isto diz o Amém, a testemunha fiel e verdadeira, o princípio da criação de Deus:', 1, CURRENT_TIMESTAMP, false),
(66, 3, 15, 'Conheço as tuas obras, que nem és frio nem quente; oxalá foras frio ou quente!', 1, CURRENT_TIMESTAMP, false),
(66, 3, 16, 'Assim, porque és morno, e não és quente nem frio, vomitar-te-ei da minha boca.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 17, 'Porquanto dizes: Rico sou, e estou enriquecido, e de nada tenho falta; e não sabes que és um coitado, e miserável, e pobre, e cego, e nu;', 1, CURRENT_TIMESTAMP, false),
(66, 3, 18, 'aconselho-te que de mim compres ouro refinado no fogo, para que te enriqueças; e vestes brancas, para que te vistas, e não seja manifesta a vergonha da tua nudez; e colírio, a fim de ungires os teus olhos, para que vejas.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 19, 'Eu repreendo e castigo a todos quantos amo: sê pois zeloso, e arrepende-te.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 20, 'Eis que estou à porta e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei em sua casa, e com ele cearei, e ele comigo.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 21, 'Ao que vencer, eu lhe concederei que se assente comigo no meu trono.', 1, CURRENT_TIMESTAMP, false),
(66, 3, 22, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.', 1, CURRENT_TIMESTAMP, false),
(66, 4, 1, 'Depois destas coisas, olhei, e eis que estava uma porta aberta no céu, e a primeira voz que ouvira, voz como de trombeta, falando comigo, disse: Sobe aqui, e mostrar-te-ei as coisas que depois destas devem acontecer.', 1, CURRENT_TIMESTAMP, false),
(66, 4, 2, 'Imediatamente fui arrebatado em espírito, e eis que um trono estava posto no céu, e um assentado sobre o trono;', 1, CURRENT_TIMESTAMP, false),
(66, 4, 3, 'e aquele que estava assentado era, na aparência, semelhante a uma pedra de jaspe e sárdio; e havia ao redor do trono um arco-íris semelhante, na aparência, à esmeralda.', 1, CURRENT_TIMESTAMP, false),
(66, 4, 4, 'Havia também ao redor do trono vinte e quatro tronos; e sobre os tronos vi assentados vinte e quatro anciãos, vestidos de branco, que tinham nas suas cabeças coroas de ouro.', 1, CURRENT_TIMESTAMP, false),
(66, 4, 5, 'E do trono saíam relâmpagos, e vozes, e trovões; e diante do trono ardiam sete lâmpadas de fogo, as quais são os sete espíritos de Deus;', 1, CURRENT_TIMESTAMP, false),
(66, 4, 6, 'também havia diante do trono como que um mar de vidro, semelhante ao cristal; e ao redor do trono, um ao meio de cada lado, quatro seres viventes cheios de olhos por diante e por detrás;', 1, CURRENT_TIMESTAMP, false),
(66, 4, 7, 'e o primeiro ser era semelhante a um leão; o segundo ser, semelhante a um touro; tinha o terceiro ser o rosto como de homem; e o quarto ser era semelhante a uma águia voando.', 1, CURRENT_TIMESTAMP, false),
(66, 4, 8, 'Os quatro seres viventes tinham, cada um, seis asas, e ao redor e por dentro estavam cheios de olhos; e não têm descanso nem de noite, dizendo: Santo, Santo, Santo é o Senhor Deus, o Todo-Poderoso, aquele que era, e que é, e que há de vir.', 1, CURRENT_TIMESTAMP, false),
(66, 4, 9, 'E, sempre que os seres viventes davam glória e honra e ações de graças ao que estava assentado sobre o trono, ao que vive pelos séculos dos séculos,', 1, CURRENT_TIMESTAMP, false),
(66, 4, 10, 'os vinte e quatro anciãos prostravam-se diante do que estava assentado sobre o trono, e adoravam ao que vive pelos séculos dos séculos; e lançavam as suas coroas diante do trono, dizendo:', 1, CURRENT_TIMESTAMP, false),
(66, 4, 11, 'Digno és, Senhor nosso e Deus nosso, de receber a glória e a honra e o poder; porque tu criaste todas as coisas, e por tua vontade existiram e foram criadas.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 1, 'Vi na destra do que estava assentado sobre o trono um livro escrito por dentro e por fora, bem selado com sete selos.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 2, 'Vi também um anjo forte, clamando com grande voz: Quem é digno de abrir o livro e de romper os seus selos?', 1, CURRENT_TIMESTAMP, false),
(66, 5, 3, 'E ninguém no céu, nem na terra, nem debaixo da terra, podia abrir o livro, nem olhar para ele.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 4, 'E eu chorava muito, porque não fora achado ninguém digno de abrir o livro nem de olhar para ele.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 5, 'E disse-me um dentre os anciãos: Não chores; eis que o Leão da tribo de Judá, a raiz de Davi, venceu para abrir o livro e romper os sete selos.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 6, 'Nisto vi, entre o trono e os quatro seres viventes, no meio dos anciãos, um Cordeiro em pé, como havendo sido morto, e tinha sete chifres e sete olhos, que são os sete espíritos de Deus, enviados por toda a terra.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 7, 'E veio e tomou o livro da destra do que estava assentado sobre o trono.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 8, 'Logo que tomou o livro, os quatro seres viventes e os vinte e quatro anciãos prostraram-se diante do Cordeiro, tendo cada um deles uma harpa e taças de ouro cheias de incenso, que são as orações dos santos.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 9, 'E cantavam um cântico novo, dizendo: Digno és de tomar o livro, e de abrir os seus selos; porque foste morto, e com o teu sangue compraste para Deus homens de toda tribo, e língua, e povo e nação;', 1, CURRENT_TIMESTAMP, false),
(66, 5, 10, 'e para o nosso Deus os fizeste reino, e sacerdotes; e eles reinarão sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 11, 'E olhei, e vi a voz de muitos anjos ao redor do trono e dos seres viventes e dos anciãos; e o número deles era miríades de miríades; e o número deles era miríades de miríades e milhares de milhares,', 1, CURRENT_TIMESTAMP, false),
(66, 5, 12, 'que com grande voz diziam: Digno é o Cordeiro, que foi morto, de receber o poder, e riqueza, e sabedoria, e força, e honra, e glória, e louvor.', 1, CURRENT_TIMESTAMP, false),
(66, 5, 13, 'Ouvi também a toda criatura que está no céu, e na terra, e debaixo da terra, e no mar, e a todas as coisas que neles há, dizerem: Ao que está assentado sobre o trono, e ao Cordeiro, seja o louvor, e a honra, e a glória, e o domínio pelos séculos dos séculos:', 1, CURRENT_TIMESTAMP, false),
(66, 5, 14, 'e os quatro seres viventes diziam: Amém. E os anciãos prostraram-se e adoraram.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 1, 'E vi quando o Cordeiro abriu um dos sete selos, e ouvi um dos quatro seres viventes dizer numa voz como de trovão: Vem!', 1, CURRENT_TIMESTAMP, false),
(66, 6, 2, 'Olhei, e eis um cavalo branco; e o que estava montado nele tinha um arco; e foi-lhe dada uma coroa, e saiu vencendo, e para vencer.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 3, 'Quando ele abriu o segundo selo, ouvi o segundo ser vivente dizer: Vem!', 1, CURRENT_TIMESTAMP, false),
(66, 6, 4, 'E saiu outro cavalo, um cavalo vermelho; e ao que estava montado nele foi dado que tirasse a paz da terra, de modo que os homens se matassem uns aos outros; e foi-lhe dada uma grande espada.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 5, 'Quando abriu o terceiro selo, ouvi o terceiro ser vivente dizer: Vem! E olhei, e eis um cavalo preto; e o que estava montado nele tinha uma balança na mão.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 6, 'E ouvi como que uma voz no meio dos quatro seres viventes, que dizia: Um queniz de trigo por um denário, e três quenizes de cevada por um denário; e não danifiques o azeite e o vinho.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 7, 'Quando abriu o quarto selo, ouvi a voz do quarto ser vivente dizer: Vem!', 1, CURRENT_TIMESTAMP, false),
(66, 6, 8, 'E olhei, e eis um cavalo amarelo, e o que estava montado nele chamava-se Morte; e o inferno seguia com ele; e foi-lhe dada autoridade sobre a quarta parte da terra, para matar com a espada, e com a fome, e com a peste, e com as feras da terra.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 9, 'Quando abriu o quinto selo, vi debaixo do altar as almas dos que tinham sido mortos por causa da palavra de Deus e por causa do testemunho que deram.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 10, 'E clamaram com grande voz, dizendo: Até quando, ó Soberano, santo e verdadeiro, não julgas e vingas o nosso sangue dos que habitam sobre a terra?.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 11, 'E foram dadas a cada um deles compridas vestes brancas e foi-lhes dito que repousassem ainda por um pouco de tempo, até que se completasse o número de seus conservos, que haviam de ser mortos, como também eles o foram.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 12, 'E vi quando abriu o sexto selo, e houve um grande terremoto; e o sol tornou-se negro como saco de cilício, e a lua toda tornou-se como sangue;', 1, CURRENT_TIMESTAMP, false),
(66, 6, 13, 'e as estrelas do céu caíram sobre a terra, como quando a figueira, sacudida por um vento forte, deixa cair os seus figos verdes.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 14, 'E o céu recolheu-se como um livro que se enrola; e todos os montes e ilhas foram removidos dos seus lugares.', 1, CURRENT_TIMESTAMP, false),
(66, 6, 15, 'E os reis da terra, e os grandes, e os chefes militares, e os ricos, e os poderosos, e todo escravo, e todo livre, se esconderam nas cavernas e nas rochas das montanhas;', 1, CURRENT_TIMESTAMP, false),
(66, 6, 16, 'e diziam aos montes e aos rochedos: Caí sobre nós, e escondei-nos da face daquele que está assentado sobre o trono, e da ira do Cordeiro;', 1, CURRENT_TIMESTAMP, false),
(66, 6, 17, 'porque é vindo o grande dia da ira deles; e quem poderá subsistir?', 1, CURRENT_TIMESTAMP, false),
(66, 7, 1, 'Depois disto vi quatro anjos em pé nos quatro cantos da terra, retendo os quatro ventos da terra, para que nenhum vento soprasse sobre a terra, nem sobre o mar, nem contra árvore alguma.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 2, 'E vi outro anjo subir do lado do sol nascente, tendo o selo do Deus vivo; e clamou com grande voz aos quatro anjos, quem fora dado que danificassem a terra e o mar,', 1, CURRENT_TIMESTAMP, false),
(66, 7, 3, 'dizendo: Não danifiques a terra, nem o mar, nem as árvores, até que selemos na sua fronte os servos do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 4, 'E ouvi o número dos que foram assinalados com o selo, cento e quarenta e quatro mil de todas as tribos dos filhos de Israel:', 1, CURRENT_TIMESTAMP, false),
(66, 7, 5, 'da tribo de Judá havia doze mil assinalados; da tribo de Rúben, doze mil; da tribo de Gade, doze mil;', 1, CURRENT_TIMESTAMP, false),
(66, 7, 6, 'da tribo de Aser, doze mil; da tribo de Naftali, doze mil; da tribo de Manassés, doze mil;', 1, CURRENT_TIMESTAMP, false),
(66, 7, 7, 'da tribo de Simeão, doze mil; da tribo de Levi, doze mil; da tribo de Issacar, doze mil;', 1, CURRENT_TIMESTAMP, false),
(66, 7, 8, 'da tribo de Zabulom, doze mil; da tribo de José, doze mil; da tribo de Benjamim, doze mil assinalados.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 9, 'Depois destas coisas olhei, e eis uma grande multidão, que ninguém podia contar, de todas as nações, tribos, povos e línguas, que estavam em pé diante do trono e em presença do Cordeiro, trajando compridas vestes brancas, e com palmas nas mãos;', 1, CURRENT_TIMESTAMP, false),
(66, 7, 10, 'e clamavam com grande voz: Salvação ao nosso Deus, que está assentado sobre o trono, e ao Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 11, 'E todos os anjos estavam em pé ao redor do trono e dos anciãos e dos quatro seres viventes, e prostraram-se diante do trono sobre seus rostos, e adoraram a Deus,', 1, CURRENT_TIMESTAMP, false),
(66, 7, 12, 'dizendo: Amém. Louvor, e glória, e sabedoria, e ações de graças, e honra, e poder, e força ao nosso Deus, pelos séculos dos séculos. Amém.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 13, 'E um dos anciãos me perguntou: Estes que trajam as compridas vestes brancas, quem são eles e donde vieram?', 1, CURRENT_TIMESTAMP, false),
(66, 7, 14, 'Respondi-lhe: Meu Senhor, tu sabes. Disse-me ele: Estes são os que vêm da grande tribulação, e levaram as suas vestes e as branquearam no sangue do Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 15, 'Por isso estão diante do trono de Deus, e o servem de dia e de noite no seu santuário; e aquele que está assentado sobre o trono estenderá o seu tabernáculo sobre eles.', 1, CURRENT_TIMESTAMP, false),
(66, 7, 16, 'Nunca mais terão fome, nunca mais terão sede; nem cairá sobre eles o sol, nem calor algum;', 1, CURRENT_TIMESTAMP, false),
(66, 7, 17, 'porque o Cordeiro que está no meio, diante do trono, os apascentará e os conduzirá às fontes das águas da vida; e Deus lhes enxugará dos olhos toda lágrima.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 1, 'Quando abriu o sétimo selo, fez-se silêncio no céu, quase por meia hora.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 2, 'E vi os sete anjos que estavam em pé diante de Deus, e lhes foram dadas sete trombetas.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 3, 'Veio outro anjo, e pôs-se junto ao altar, tendo um incensário de ouro; e foi-lhe dado muito incenso, para que o oferecesse com as orações de todos os santos sobre o altar de ouro que está diante do trono.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 4, 'E da mão do anjo subiu diante de Deus a fumaça do incenso com as orações dos santos.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 5, 'Depois do anjo tomou o incensário, encheu-o do fogo do altar e o lançou sobre a terra; e houve trovões, vozes, relâmpagos e terremoto.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 6, 'Então os sete anjos que tinham as sete trombetas prepararam-se para tocar.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 7, 'O primeiro anjo tocou a sua trombeta, e houve saraiva e fogo misturado com sangue, que foram lançados na terra; e foi queimada a terça parte da terra, a terça parte das árvores, e toda a erva verde.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 8, 'O segundo anjo tocou a sua trombeta, e foi lançado no mar como que um grande monte ardendo em fogo, e tornou-se em sangue a terça parte do mar.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 9, 'E morreu a terça parte das criaturas viventes que havia no mar, e foi destruída a terça parte dos navios.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 10, 'O terceiro anjo tocou a sua trombeta, e caiu do céu uma grande estrela, ardendo como uma tocha, e caiu sobre a terça parte dos rios, e sobre as fontes das águas.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 11, 'O nome da estrela era Absinto; e a terça parte das águas tornou-se em absinto, e muitos homens morreram das águas, porque se tornaram amargas.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 12, 'O quarto anjo tocou a sua trombeta, e foi ferida a terça parte do sol, a terça parte da lua, e a terça parte das estrelas; para que a terça parte deles se escurecesse, e a terça parte do dia não brilhante, e semelhantemente a da noite.', 1, CURRENT_TIMESTAMP, false),
(66, 8, 13, 'E olhei, e ouvi uma águia que, voando pelo meio do céu, dizia com grande voz: Ai, ai, ai dos que habitam sobre a terra! por causa dos outros toques de trombeta dos três anjos que ainda vão tocar.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 1, 'O quinto anjo tocou a sua trombeta, e vi uma estrela que do céu caíra sobre a terra; e foi-lhe dada a chave do poço do abismo.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 2, 'E abriu o poço do abismo, e subiu fumaça do poço, como fumaça de uma grande fornalha; e com a fumaça do poço escureceram-se o sol e o ar.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 3, 'Da fumaça saíram gafanhotos sobre a terra; e foi-lhes dado poder, como o que têm os escorpiões da terra.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 4, 'Foi-lhes dito que não fizessem dano à erva da terra, nem a verdura alguma, nem a árvore alguma, mas somente aos homens que não têm na fronte o selo de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 5, 'Foi-lhes permitido, não que os matassem, mas que por cinco meses os atormentassem. E o seu tormento era semelhante ao tormento do escorpião, quando fere o homem.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 6, 'Naqueles dias os homens buscarão a morte, e de modo algum a acharão; e desejarão morrer, e a morte fugirá deles.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 7, 'A aparência dos gafanhotos era semelhante à de cavalos aparelhados para a guerra; e sobre as suas cabeças havia como que umas coroas semelhantes ao ouro; e os seus rostos eram como rostos de homens.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 8, 'Tinham cabelos como cabelos de mulheres, e os seus dentes eram como os de leões.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 9, 'Tinham couraças como couraças de ferro; e o ruído das suas asas era como o ruído de carros de muitos cavalos que correm ao combate.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 10, 'Tinham caudas com ferrões, semelhantes às caudas dos escorpiões; e nas suas caudas estava o seu poder para fazer dano aos homens por cinco meses.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 11, 'Tinham sobre si como rei o anjo do abismo, cujo nome em hebraico é Abadom e em grego Apoliom.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 12, 'Passado é já um ai; eis que depois disso vêm ainda dois ais.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 13, 'O sexto anjo tocou a sua trombeta; e ouvi uma voz que vinha das quatro pontas do altar de ouro que estava diante de Deus,', 1, CURRENT_TIMESTAMP, false),
(66, 9, 14, 'a qual dizia ao sexto anjo, que tinha a trombeta: Solta os quatro anjos que se acham presos junto do grande rio Eufrates.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 15, 'E foram soltos os quatro anjos que haviam sido preparados para aquela hora e dia e mês e ano, a fim de matarem a terça parte dos homens.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 16, 'O número dos exércitos dos cavaleiros era de duas miríades de miríades; pois ouvi o número deles.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 17, 'E assim vi os cavalos nesta visão: os que sobre eles estavam montados tinham couraças de fogo, e de jacinto, e de enxofre; e as cabeças dos cavalos eram como cabeças de leões; e de suas bocas saíam fogo, fumaça e enxofre.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 18, 'Por estas três pragas foi morta a terça parte dos homens, isto é, pelo fogo, pela fumaça e pelo enxofre, que saíam das suas bocas.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 19, 'Porque o poder dos cavalos estava nas suas bocas e nas suas caudas. Porquanto as suas caudas eram semelhantes a serpentes, e tinham cabeças, e com elas causavam dano.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 20, 'Os outros homens, que não foram mortos por estas pragas, não se arrependeram das obras das suas mãos, para deixarem de adorar aos demônios, e aos ídolos de ouro, de prata, de bronze, de pedra e de madeira, que nem podem ver, nem ouvir, nem andar.', 1, CURRENT_TIMESTAMP, false),
(66, 9, 21, 'Também não se arrependeram dos seus homicídios, nem das suas feitiçarias, nem da sua prostituição, nem dos seus furtos.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 1, 'E vi outro anjo forte que descia do céu, vestido de uma nuvem; por cima da sua cabeça estava o arco-íris; o seu rosto era como o sol, e os seus pés como colunas de fogo,', 1, CURRENT_TIMESTAMP, false),
(66, 10, 2, 'e tinha na mão um livrinho aberto. Pôs o seu pé direito sobre o mar, e o esquerdo sobre a terra,', 1, CURRENT_TIMESTAMP, false),
(66, 10, 3, 'e clamou com grande voz, assim como ruge o leão; e quando clamou, os sete trovões fizeram soar as suas vozes.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 4, 'Quando os sete trovões acabaram de soar eu já ia escrever, mas ouvi uma voz do céu, que dizia: Sela o que os sete trovões falaram, e não o escrevas.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 5, 'O anjo que vi em pé sobre o mar e sobre a terra levantou a mão direita ao céu,', 1, CURRENT_TIMESTAMP, false),
(66, 10, 6, 'e jurou por aquele que vive pelos séculos dos séculos, o qual criou o céu e o que nele há, e a terra e o que nela há, e o mar e o que nele há, que não haveria mais demora,', 1, CURRENT_TIMESTAMP, false),
(66, 10, 7, 'mas que nos dias da voz do sétimo anjo, quando este estivesse para tocar a trombeta, se cumpriria o mistério de Deus, como anunciou aos seus servos, os profetas.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 8, 'A voz que eu do céu tinha ouvido tornou a falar comigo, e disse: Vai, e toma o livro que está aberto na mão do anjo que se acha em pé sobre o mar e sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 9, 'E fui ter com o anjo e lhe pedi que me desse o livrinho. Disse-me ele: Toma-o, e come-o; ele fará amargo o teu ventre, mas na tua boca será doce como mel.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 10, 'Tomei o livrinho da mão do anjo, e o comi; e na minha boca era doce como mel; mas depois que o comi, o meu ventre ficou amargo.', 1, CURRENT_TIMESTAMP, false),
(66, 10, 11, 'Então me disseram: Importa que profetizes outra vez a muitos povos, e nações, e línguas, e reis.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 1, 'Foi-me dada uma cana semelhante a uma vara; e foi-me dito: Levanta-te, mede o santuário de Deus, e o altar, e os que nele adoram.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 2, 'Mas deixa o átrio que está fora do santuário, e não o meças; porque foi dado aos gentios; e eles pisarão a cidade santa por quarenta e dois meses.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 3, 'E concederei às minhas duas testemunhas que, vestidas de saco, profetizem por mil duzentos e sessenta dias.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 4, 'Estas são as duas oliveiras e os dois candeeiros que estão diante do Senhor da terra.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 5, 'E, se alguém lhes quiser fazer mal, das suas bocas sairá fogo e devorará os seus inimigos; pois se alguém lhes quiser fazer mal, importa que assim seja morto.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 6, 'Elas têm poder para fechar o céu, para que não chova durante os dias da sua profecia; e têm poder sobre as águas para convertê-las em sangue, e para ferir a terra com toda sorte de pragas, quantas vezes quiserem.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 7, 'E, quando acabarem o seu testemunho, a besta que sobe do abismo lhes fará guerra e as vencerá e matará.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 8, 'E jazerão os seus corpos na praça da grande cidade, que espiritualmente se chama Sodoma e Egito, onde também o seu Senhor foi crucificado.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 9, 'Homens de vários povos, e tribos e línguas, e nações verão os seus corpos por três dias e meio, e não permitirão que sejam sepultados.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 10, 'E os que habitam sobre a terra se regozijarão sobre eles, e se alegrarão; e mandarão presentes uns aos outros, porquanto estes dois profetas atormentaram os que habitam sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 11, 'E depois daqueles três dias e meio o espírito de vida, vindo de Deus, entrou neles, e puseram-se sobre seus pés, e caiu grande temor sobre os que os viram.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 12, 'E ouviram uma grande voz do céu, que lhes dizia: Subi para cá. E subiram ao céu em uma nuvem; e os seus inimigos os viram.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 13, 'E naquela hora houve um grande terremoto, e caiu a décima parte da cidade, e no terremoto foram mortos sete mil homens; e os demais ficaram atemorizados, e deram glória ao Deus do céu.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 14, 'É passado o segundo ai; eis que cedo vem o terceiro.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 15, 'E tocou o sétimo anjo a sua trombeta, e houve no céu grandes vozes, que diziam: O reino do mundo passou a ser de nosso Senhor e do seu Cristo, e ele reinará pelos séculos dos séculos.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 16, 'E os vinte e quatro anciãos, que estão assentados em seus tronos diante de Deus, prostraram-se sobre seus rostos e adoraram a Deus,', 1, CURRENT_TIMESTAMP, false),
(66, 11, 17, 'dizendo: Graças te damos, Senhor Deus Todo-Poderoso, que és, e que eras, porque tens tomado o teu grande poder, e começaste a reinar.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 18, 'Iraram-se, na verdade, as nações; então veio a tua ira, e o tempo de serem julgados os mortos, e o tempo de dares recompensa aos teus servos, os profetas, e aos santos, e aos que temem o teu nome, a pequenos e a grandes, e o tempo de destruíres os que destroem a terra.', 1, CURRENT_TIMESTAMP, false),
(66, 11, 19, 'Abriu-se o santuário de Deus que está no céu, e no seu santuário foi vista a arca do seu pacto; e houve relâmpagos, vozes e trovões, e terremoto e grande saraivada.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 1, 'E viu-se um grande sinal no céu: uma mulher vestida do sol, tendo a lua debaixo dos seus pés, e uma coroa de doze estrelas sobre a sua cabeça.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 2, 'E estando grávida, gritava com as dores do parto, sofrendo tormentos para dar à luz.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 3, 'Viu-se também outro sinal no céu: eis um grande dragão vermelho que tinha sete cabeças e dez chifres, e sobre as suas cabeças sete diademas;', 1, CURRENT_TIMESTAMP, false),
(66, 12, 4, 'a sua cauda levava após si a terça parte das estrelas do céu, e lançou-as sobre a terra; e o dragão parou diante da mulher que estava para dar à luz, para que, dando ela à luz, lhe devorasse o filho.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 5, 'E deu à luz um filho, um varão que há de reger todas as nações com vara de ferro; e o seu filho foi arrebatado para Deus e para o seu trono.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 6, 'E a mulher fugiu para o deserto, onde já tinha lugar preparado por Deus, para que ali fosse alimentada durante mil duzentos e sessenta dias.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 7, 'Então houve guerra no céu: Miguel e os seus anjos batalhavam contra o dragão. E o dragão e os seus anjos batalhavam,', 1, CURRENT_TIMESTAMP, false),
(66, 12, 8, 'mas não prevaleceram, nem mais o seu lugar se achou no céu.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 9, 'E foi precipitado o grande dragão, a antiga serpente, que se chama o Diabo e Satanás, que engana todo o mundo; foi precipitado na terra, e os seus anjos foram precipitados com ele.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 10, 'Então, ouvi uma grande voz no céu, que dizia: Agora é chegada a salvação, e o poder, e o reino do nosso Deus, e a autoridade do seu Cristo; porque já foi lançado fora o acusador de nossos irmãos, o qual diante do nosso Deus os acusava dia e noite.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 11, 'E eles o venceram pelo sangue do Cordeiro e pela palavra do seu testemunho; e não amaram as suas vidas até a morte.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 12, 'Pelo que alegrai-vos, ó céus, e vós que neles habitais. Mas ai da terra e do mar! porque o Diabo desceu a vós com grande ira, sabendo que pouco tempo lhe resta.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 13, 'Quando o dragão se viu precipitado na terra, perseguiu a mulher que dera à luz o filho varão.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 14, 'E foram dadas à mulher as duas asas da grande águia, para que voasse para o deserto, ao seu lugar, onde é sustentada por um tempo, e tempos, e metade de um tempo, fora da vista da serpente.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 15, 'E a serpente lançou da sua boca, atrás da mulher, água como um rio, para fazer que ela fosse arrebatada pela corrente.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 16, 'A terra, porém acudiu à mulher; e a terra abriu a boca, e tragou o rio que o dragão lançara da sua boca.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 17, 'E o dragão irou-se contra a mulher, e foi fazer guerra aos demais filhos dela, os que guardam os mandamentos de Deus, e mantêm o testemunho de Jesus.', 1, CURRENT_TIMESTAMP, false),
(66, 12, 18, 'E o dragão parou sobre a areia do mar.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 1, 'Então vi subir do mar uma besta que tinha dez chifres e sete cabeças, e sobre os seus chifres dez diademas, e sobre as suas cabeças nomes de blasfêmia.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 2, 'E a besta que vi era semelhante ao leopardo, e os seus pés como os de urso, e a sua boca como a de leão; e o dragão deu-lhe o seu poder e o seu trono e grande autoridade.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 3, 'Também vi uma de suas cabeças como se fora ferida de morte, mas a sua ferida mortal foi curada. Toda a terra se maravilhou, seguindo a besta,', 1, CURRENT_TIMESTAMP, false),
(66, 13, 4, 'e adoraram o dragão, porque deu à besta a sua autoridade; e adoraram a besta, dizendo: Quem é semelhante à besta? quem poderá batalhar contra ela?', 1, CURRENT_TIMESTAMP, false),
(66, 13, 5, 'Foi-lhe dada uma boca que proferia arrogâncias e blasfêmias; e deu-se-lhe autoridade para atuar por quarenta e dois meses.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 6, 'E abriu a boca em blasfêmias contra Deus, para blasfemar do seu nome e do seu tabernáculo e dos que habitam no céu.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 7, 'Também lhe foi permitido fazer guerra aos santos, e vencê-los; e deu-se-lhe autoridade sobre toda tribo, e povo, e língua e nação.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 8, 'E adorá-la-ão todos os que habitam sobre a terra, esses cujos nomes não estão escritos no livro do Cordeiro que foi morto desde a fundação do mundo.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 9, 'Se alguém tem ouvidos, ouça.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 10, 'Se alguém leva em cativeiro, em cativeiro irá; se alguém matar à espada, necessário é que à espada seja morto. Aqui está a perseverança e a fé dos santos.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 11, 'E vi subir da terra outra besta, e tinha dois chifres semelhantes aos de um cordeiro; e falava como dragão.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 12, 'Também exercia toda a autoridade da primeira besta na sua presença; e fazia que a terra e os que nela habitavam adorassem a primeira besta, cuja ferida mortal fora curada.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 13, 'E operava grandes sinais, de maneira que fazia até descer fogo do céu à terra, à vista dos homens;', 1, CURRENT_TIMESTAMP, false),
(66, 13, 14, 'e, por meio dos sinais que lhe foi permitido fazer na presença da besta, enganava os que habitavam sobre a terra e lhes dizia que fizessem uma imagem à besta que recebera a ferida da espada e vivia.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 15, 'Foi-lhe concedido também dar fôlego à imagem da besta, para que a imagem da besta falasse, e fizesse que fossem mortos todos os que não adorassem a imagem da besta.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 16, 'E fez que a todos, pequenos e grandes, ricos e pobres, livres e escravos, lhes fosse posto um sinal na mão direita, ou na fronte,', 1, CURRENT_TIMESTAMP, false),
(66, 13, 17, 'para que ninguém pudesse comprar ou vender, senão aquele que tivesse o sinal, ou o nome da besta, ou o número do seu nome.', 1, CURRENT_TIMESTAMP, false),
(66, 13, 18, 'Aqui há sabedoria. Aquele que tem entendimento, calcule o número da besta; porque é o número de um homem, e o seu número é seiscentos e sessenta e seis.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 1, 'E olhei, e eis o Cordeiro em pé sobre o Monte Sião, e com ele cento e quarenta e quatro mil, que traziam na fronte escrito o nome dele e o nome de seu Pai.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 2, 'E ouvi uma voz do céu, como a voz de muitas águas, e como a voz de um grande trovão e a voz que ouvi era como de harpistas, que tocavam as suas harpas.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 3, 'E cantavam um cântico novo diante do trono, e diante dos quatro seres viventes e dos anciãos; e ninguém podia aprender aquele cântico, senão os cento e quarenta e quatro mil, aqueles que foram comprados da terra.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 4, 'Estes são os que não se contaminaram com mulheres; porque são virgens. Estes são os que seguem o Cordeiro para onde quer que vá. Estes foram comprados dentre os homens para serem as primícias para Deus e para o Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 5, 'E na sua boca não se achou engano; porque são irrepreensíveis.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 6, 'E vi outro anjo voando pelo meio do céu, e tinha um evangelho eterno para proclamar aos que habitam sobre a terra e a toda nação, e tribo, e língua, e povo,', 1, CURRENT_TIMESTAMP, false),
(66, 14, 7, 'dizendo com grande voz: Temei a Deus, e dai-lhe glória; porque é chegada a hora do seu juízo; e adorai aquele que fez o céu, e a terra, e o mar, e as fontes das águas.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 8, 'Um segundo anjo o seguiu, dizendo: Caiu, caiu a grande Babilônia, que a todas as nações deu a beber do vinho da ira da sua prostituição.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 9, 'Seguiu-os ainda um terceiro anjo, dizendo com grande voz: Se alguém adorar a besta, e a sua imagem, e receber o sinal na fronte, ou na mão,', 1, CURRENT_TIMESTAMP, false),
(66, 14, 10, 'também o tal beberá do vinho da ira de Deus, que se acha preparado sem mistura, no cálice da sua ira; e será atormentado com fogo e enxofre diante dos santos anjos e diante do Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 11, 'A fumaça do seu tormento sobe para todo o sempre; e não têm repouso nem de dia nem de noite os que adoram a besta e a sua imagem, nem aquele que recebe o sinal do seu nome.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 12, 'Aqui está a perseverança dos santos, daqueles que guardam os mandamentos de Deus e a fé em Jesus.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 13, 'Então ouvi uma voz do céu, que dizia: Escreve: Bem-aventurados os mortos que desde agora morrem no Senhor. Sim, diz o Espírito, para que descansem dos seus trabalhos, pois as suas obras os acompanham.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 14, 'E olhei, e eis uma nuvem branca, e assentado sobre a nuvem um semelhante a filho de homem, que tinha sobre a cabeça uma coroa de ouro, e na mão uma foice afiada.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 15, 'E outro anjo saiu do santuário, clamando com grande voz ao que estava assentado sobre a nuvem: Lança a tua foice e ceifa, porque é chegada a hora de ceifar, porque já a seara da terra está madura.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 16, 'Então aquele que estava assentado sobre a nuvem meteu a sua foice à terra, e a terra foi ceifada.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 17, 'Ainda outro anjo saiu do santuário que está no céu, o qual também tinha uma foice afiada.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 18, 'E saiu do altar outro anjo, que tinha poder sobre o fogo, e clamou com grande voz ao que tinha a foice afiada, dizendo: Lança a tua foice afiada, e vindima os cachos da vinha da terra, porque já as suas uvas estão maduras.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 19, 'E o anjo meteu a sua foice à terra, e vindimou as uvas da vinha da terra, e lançou-as no grande lagar da ira de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 14, 20, 'E o lagar foi pisado fora da cidade, e saiu sangue do lagar até os freios dos cavalos, pelo espaço de mil e seiscentos estádios.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 1, 'Vi no céu ainda outro sinal, grande e admirável: sete anjos, que tinham as sete últimas pragas; porque nelas é consumada a ira de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 2, 'E vi como que um mar de vidro misturado com fogo; e os que tinham vencido a besta e a sua imagem e o número do seu nome estavam em pé junto ao mar de vidro, e tinham harpas de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 3, 'E cantavam o cântico de Moisés, servo de Deus, e o cântico do Cordeiro, dizendo: Grandes e admiráveis são as tuas obras, ó Senhor Deus Todo-Poderoso; justos e verdadeiros são os teus caminhos, ó Rei dos séculos.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 4, 'Quem não te temerá, Senhor, e não glorificará o teu nome? Pois só tu és santo; por isso todas as nações virão e se prostrarão diante de ti, porque os teus juízos são manifestos.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 5, 'Depois disto olhei, e abriu-se o santuário do tabernáculo do testemunho no céu;', 1, CURRENT_TIMESTAMP, false),
(66, 15, 6, 'e saíram do santuário os sete anjos que tinham as sete pragas, vestidos de linho puro e resplandecente, e cingidos, à altura do peito com cintos de ouro.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 7, 'Um dos quatro seres viventes deu aos sete anjos sete taças de ouro, cheias da ira do Deus que vive pelos séculos dos séculos.', 1, CURRENT_TIMESTAMP, false),
(66, 15, 8, 'E o santuário se encheu de fumaça pela glória de Deus e pelo seu poder; e ninguém podia entrar no santuário, enquanto não se consumassem as sete pragas dos sete anjos.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 1, 'E ouvi, vinda do santuário, uma grande voz, que dizia aos sete anjos: Ide e derramai sobre a terra as sete taças, da ira de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 2, 'Então foi o primeiro e derramou a sua taça sobre a terra; e apareceu uma chaga ruim e maligna nos homens que tinham o sinal da besta e que adoravam a sua imagem.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 3, 'O segundo anjo derramou a sua taça no mar, que se tornou em sangue como de um morto, e morreu todo ser vivente que estava no mar.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 4, 'O terceiro anjo derramou a sua taça nos rios e nas fontes das águas, e se tornaram em sangue.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 5, 'E ouvi o anjo das águas dizer: Justo és tu, que és e que eras, o Santo; porque julgaste estas coisas;', 1, CURRENT_TIMESTAMP, false),
(66, 16, 6, 'porque derramaram o sangue de santos e de profetas, e tu lhes tens dado sangue a beber; eles o merecem.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 7, 'E ouvi uma voz do altar, que dizia: Na verdade, ó Senhor Deus Todo-Poderoso, verdadeiros e justos são os teus juízos.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 8, 'O quarto anjo derramou a sua taça sobre o sol, e foi-lhe permitido que abrasasse os homens com fogo.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 9, 'E os homens foram abrasados com grande calor; e blasfemaram o nome de Deus, que tem poder sobre estas pragas; e não se arrependeram para lhe darem glória.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 10, 'O quinto anjo derramou a sua taça sobre o trono da besta, e o seu reino se fez tenebroso; e os homens mordiam de dor as suas línguas.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 11, 'E por causa das suas dores, e por causa das suas chagas, blasfemaram o Deus do céu; e não se arrependeram das suas obras.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 12, 'O sexto anjo derramou a sua taça sobre o grande rio Eufrates; e a sua água secou-se, para que se preparasse o caminho dos reis que vêm do oriente.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 13, 'E da boca do dragão, e da boca da besta, e da boca do falso profeta, vi saírem três espíritos imundos, semelhantes a rãs.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 14, 'Pois são espíritos de demônios, que operam sinais; os quais vão ao encontro dos reis de todo o mundo, para os congregar para a batalha do grande dia do Deus Todo-Poderoso.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 15, '{Eis que venho como ladrão. Bem-aventurado aquele que vigia, e guarda as suas vestes, para que não ande nu, e não se veja a sua nudez.}', 1, CURRENT_TIMESTAMP, false),
(66, 16, 16, 'E eles os congregaram no lugar que em hebraico se chama Armagedom.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 17, 'O sétimo anjo derramou a sua taça no ar; e saiu uma grande voz do santuário, da parte do trono, dizendo: Está feito.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 18, 'E houve relâmpagos e vozes e trovões; houve também um grande terremoto, qual nunca houvera desde que há homens sobre a terra, terremoto tão forte quão grande;', 1, CURRENT_TIMESTAMP, false),
(66, 16, 19, 'e a grande cidade fendeu-se em três partes, e as cidades das nações caíram; e Deus lembrou-se da grande Babilônia, para lhe dar o cálice do vinho do furor da sua ira.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 20, 'Todas ilhas fugiram, e os montes não mais se acharam.', 1, CURRENT_TIMESTAMP, false),
(66, 16, 21, 'E sobre os homens caiu do céu uma grande saraivada, pedras quase do peso de um talento; e os homens blasfemaram de Deus por causa da praga da saraivada; porque a sua praga era mui grande.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 1, 'Veio um dos sete anjos que tinham as sete taças, e falou comigo, dizendo: Vem, mostrar-te-ei a condenação da grande prostituta que está assentada sobre muitas águas;', 1, CURRENT_TIMESTAMP, false),
(66, 17, 2, 'com a qual se prostituíram os reis da terra; e os que habitam sobre a terra se embriagaram com o vinho da sua prostituição.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 3, 'Então ele me levou em espírito a um deserto; e vi uma mulher montada numa besta cor de escarlata, que estava cheia de nomes de blasfêmia, e que tinha sete cabeças e dez chifres.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 4, 'A mulher estava vestida de púrpura e de escarlata, e adornada de ouro, pedras preciosas e pérolas; e tinha na mão um cálice de ouro, cheio das abominações, e da imundícia da prostituição;', 1, CURRENT_TIMESTAMP, false),
(66, 17, 5, 'e na sua fronte estava escrito um nome simbólico: A grande Babilônia, a mãe das prostituições e das abominações da terra.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 6, 'E vi que a mulher estava embriagada com o sangue dos santos e com o sangue dos mártires de Jesus. Quando a vi, maravilhei-me com grande admiração.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 7, 'Ao que o anjo me disse: Por que te admiraste? Eu te direi o mistério da mulher, e da besta que a leva, a qual tem sete cabeças e dez chifres.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 8, 'A besta que viste era e já não é; todavia está para subir do abismo, e vai-se para a perdição; e os que habitam sobre a terra e cujos nomes não estão escritos no livro da vida desde a fundação do mundo se admirarão, quando virem a besta que era e já não é, e que tornará a vir.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 9, 'Aqui está a mente que tem sabedoria. As sete cabeças são sete montes, sobre os quais a mulher está assentada;', 1, CURRENT_TIMESTAMP, false),
(66, 17, 10, 'são também sete reis: cinco já caíram; um existe; e o outro ainda não é vindo; e quando vier, deve permanecer pouco tempo.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 11, 'A besta que era e já não é, é também o oitavo rei, e é dos sete, e vai-se para a perdição.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 12, 'Os dez chifres que viste são dez reis, os quais ainda não receberam o reino, mas receberão autoridade, como reis, por uma hora, juntamente com a besta.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 13, 'Estes têm um mesmo intento, e entregarão o seu poder e autoridade à besta.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 14, 'Estes combaterão contra o Cordeiro, e o Cordeiro os vencerá, porque é o Senhor dos senhores e o Rei dos reis; vencerão também os que estão com ele, os chamados, e eleitos, e fiéis.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 15, 'Disse-me ainda: As águas que viste, onde se assenta a prostituta, são povos, multidões, nações e línguas.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 16, 'E os dez chifres que viste, e a besta, estes odiarão a prostituta e a tornarão desolada e nua, e comerão as suas carnes, e a queimarão no fogo.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 17, 'Porque Deus lhes pôs nos corações o executarem o intento dele, chegarem a um acordo, e entregarem à besta o seu reino, até que se cumpram as palavras de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 17, 18, 'E a mulher que viste é a grande cidade que reina sobre os reis da terra.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 1, 'Depois destas coisas vi descer do céu outro anjo que tinha grande autoridade, e a terra foi iluminada com a sua glória.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 2, 'E ele clamou com voz forte, dizendo: Caiu, caiu a grande Babilônia, e se tornou morada de demônios, e guarida de todo espírito imundo, e guarida de toda ave imunda e detestável.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 3, 'Porque todas as nações têm bebido do vinho da ira da sua prostituição, e os reis da terra se prostituíram com ela; e os mercadores da terra se enriqueceram com a abundância de suas delícias.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 4, 'Ouvi outra voz do céu dizer: Sai dela, povo meu, para que não sejas participante dos sete pecados, e para que não incorras nas suas pragas.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 5, 'Porque os seus pecados se acumularam até o céu, e Deus se lembrou das iniqüidades dela.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 6, 'Tornai a dar-lhe como também ela vos tem dado, e retribuí-lhe em dobro conforme as suas obras; no cálice em que vos deu de beber dai-lhe a ela em dobro.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 7, 'Quanto ela se glorificou, e em delícias esteve, tanto lhe dai de tormento e de pranto; pois que ela diz em seu coração: Estou assentada como rainha, e não sou viúva, e de modo algum verei o pranto.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 8, 'Por isso, num mesmo dia virão as suas pragas, a morte, e o pranto, e a fome; e será consumida no fogo; porque forte é o Senhor Deus que a julga.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 9, 'E os reis da terra, que com ela se prostituíram e viveram em delícias, sobre ela chorarão e prantearão, quando virem a fumaça do seu incêndio;', 1, CURRENT_TIMESTAMP, false),
(66, 18, 10, 'e, estando de longe por medo do tormento dela, dirão: Ai! ai da grande cidade, Babilônia, a cidade forte! pois numa só hora veio o teu julgamento.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 11, 'E sobre ela choram e lamentam os mercadores da terra; porque ninguém compra mais as suas mercadorias:', 1, CURRENT_TIMESTAMP, false),
(66, 18, 12, 'mercadorias de ouro, de prata, de pedras preciosas, de pérolas, de linho fino, de púrpura, de seda e de escarlata; e toda espécie de madeira odorífera, e todo objeto de marfim, de madeira preciosíssima, de bronze, de ferro e de mármore;', 1, CURRENT_TIMESTAMP, false),
(66, 18, 13, 'e canela, especiarias, perfume, mirra e incenso; e vinho, azeite, flor de farinha e trigo; e gado, ovelhas, cavalos e carros; e escravos, e até almas de homens.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 14, 'Também os frutos que a tua alma cobiçava foram-se de ti; e todas as coisas delicadas e suntuosas se foram de ti, e nunca mais se acharão.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 15, 'Os mercadores destas coisas, que por ela se enriqueceram, ficarão de longe por medo do tormento dela, chorando e lamentando,', 1, CURRENT_TIMESTAMP, false),
(66, 18, 16, 'dizendo: Ai! ai da grande cidade, da que estava vestida de linho fino, de púrpura, de escarlata, e adornada com ouro, e pedras preciosas, e pérolas! porque numa só hora foram assoladas tantas riquezas.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 17, 'E todo piloto, e todo o que navega para qualquer porto e todos os marinheiros, e todos os que trabalham no mar se puseram de longe;', 1, CURRENT_TIMESTAMP, false),
(66, 18, 18, 'e, contemplando a fumaça do incêndio dela, clamavam: Que cidade é semelhante a esta grande cidade?', 1, CURRENT_TIMESTAMP, false),
(66, 18, 19, 'E lançaram pó sobre as suas cabeças, e clamavam, chorando e lamentando, dizendo: Ai! ai da grande cidade, na qual todos os que tinham naus no mar se enriqueceram em razão da sua opulência! porque numa só hora foi assolada.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 20, 'Exulta sobre ela, ó céu, e vós, santos e apóstolos e profetas; porque Deus vindicou a vossa causa contra ela.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 21, 'Um forte anjo levantou uma pedra, qual uma grande mó, e lançou-a no mar, dizendo: Com igual ímpeto será lançada Babilônia, a grande cidade, e nunca mais será achada.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 22, 'E em ti não se ouvirá mais o som de harpistas, de músicos, de flautistas e de trombeteiros; e nenhum artífice de arte alguma se achará mais em ti; e em ti não mais se ouvirá ruído de mó;', 1, CURRENT_TIMESTAMP, false),
(66, 18, 23, 'e luz de candeia não mais brilhará em ti, e voz de noivo e de noiva não mais em ti se ouvirá; porque os teus mercadores eram os grandes da terra; porque todas as nações foram enganadas pelas tuas feitiçarias.', 1, CURRENT_TIMESTAMP, false),
(66, 18, 24, 'E nela se achou o sangue dos profetas, e dos santos, e de todos os que foram mortos na terra.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 1, 'Depois destas coisas, ouvi no céu como que uma grande voz de uma imensa multidão, que dizia: Aleluia! A salvação e a glória e o poder pertencem ao nosso Deus;', 1, CURRENT_TIMESTAMP, false),
(66, 19, 2, 'porque verdadeiros e justos são os seus juízos, pois julgou a grande prostituta, que havia corrompido a terra com a sua prostituição, e das mãos dela vingou o sangue dos seus servos.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 3, 'E outra vez disseram: Aleluia. E a fumaça dela sobe pelos séculos dos séculos.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 4, 'Então os vinte e quatro anciãos e os quatro seres viventes prostraram-se e adoraram a Deus que está assentado no trono, dizendo: Amém. Aleluia!', 1, CURRENT_TIMESTAMP, false),
(66, 19, 5, 'E saiu do trono uma voz, dizendo: Louvai o nosso Deus, vós, todos os seus servos, e vós que o temeis, assim pequenos como grandes.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 6, 'Também ouvi uma voz como a de grande multidão, como a voz de muitas águas, e como a voz de fortes trovões, que dizia: Aleluia! porque já reina o Senhor nosso Deus, o Todo-Poderoso.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 7, 'Regozijemo-nos, e exultemos, e demos-lhe a glória; porque são chegadas as bodas do Cordeiro, e já a sua noiva se preparou,', 1, CURRENT_TIMESTAMP, false),
(66, 19, 8, 'e foi-lhe permitido vestir-se de linho fino, resplandecente e puro; pois o linho fino são as obras justas dos santos.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 9, 'E disse-me: Escreve: Bem-aventurados aqueles que são chamados à ceia das bodas do Cordeiro. Disse-me ainda: Estas são as verdadeiras palavras de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 10, 'Então me lancei a seus pés para adorá-lo, mas ele me disse: Olha, não faças tal: sou conservo teu e de teus irmãos, que têm o testemunho de Jesus; adora a Deus; pois o testemunho de Jesus é o espírito da profecia.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 11, 'E vi o céu aberto, e eis um cavalo branco; e o que estava montado nele chama-se Fiel e Verdadeiro; e julga a peleja com justiça.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 12, 'Os seus olhos eram como chama de fogo; sobre a sua cabeça havia muitos diademas; e tinha um nome escrito, que ninguém sabia senão ele mesmo.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 13, 'Estava vestido de um manto salpicado de sangue; e o nome pelo qual se chama é o Verbo de Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 14, 'Seguiam-no os exércitos que estão no céu, em cavalos brancos, e vestidos de linho fino, branco e puro.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 15, 'Da sua boca saía uma espada afiada, para ferir com ela as nações; ele as regerá com vara de ferro; e ele mesmo é o que pisa o lagar do vinho do furor da ira do Deus Todo-Poderoso.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 16, 'No manto, sobre a sua coxa tem escrito o nome: Rei dos reis e Senhor dos senhores.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 17, 'E vi um anjo em pé no sol; e clamou com grande voz, dizendo a todas as aves que voavam pelo meio do céu: Vinde, ajuntai-vos para a grande ceia de Deus,', 1, CURRENT_TIMESTAMP, false),
(66, 19, 18, 'para comerdes carnes de reis, carnes de comandantes, carnes de poderosos, carnes de cavalos e dos que neles montavam, sim, carnes de todos os homens, livres e escravos, pequenos e grandes.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 19, 'E vi a besta, e os reis da terra, e os seus exércitos reunidos para fazerem guerra àquele que estava montado no cavalo, e ao seu exército.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 20, 'E a besta foi presa, e com ela o falso profeta que fizera diante dela os sinais com que enganou os que receberam o sinal da besta e os que adoraram a sua imagem. Estes dois foram lançados vivos no lago de fogo que arde com enxofre.', 1, CURRENT_TIMESTAMP, false),
(66, 19, 21, 'E os demais foram mortos pela espada que saía da boca daquele que estava montado no cavalo; e todas as aves se fartaram das carnes deles.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 1, 'E vi descer do céu um anjo, que tinha a chave do abismo e uma grande cadeia na sua mão.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 2, 'Ele prendeu o dragão, a antiga serpente, que é o Diabo e Satanás, e o amarrou por mil anos.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 3, 'Lançou-o no abismo, o qual fechou e selou sobre ele, para que não enganasse mais as nações até que os mil anos se completassem. Depois disto é necessário que ele seja solto por um pouco de tempo.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 4, 'Então vi uns tronos; e aos que se assentaram sobre eles foi dado o poder de julgar; e vi as almas daqueles que foram degolados por causa do testemunho de Jesus e da palavra de Deus, e que não adoraram a besta nem a sua imagem, e não receberam o sinal na fronte nem nas mãos; e reviveram, e reinaram com Cristo durante mil anos.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 5, 'Mas os outros mortos não reviveram, até que os mil anos se completassem. Esta é a primeira ressurreição.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 6, 'Bem-aventurado e santo é aquele que tem parte na primeira ressurreição; sobre estes não tem poder a segunda morte; mas serão sacerdotes de Deus e de Cristo, e reinarão com ele durante os mil anos.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 7, 'Ora, quando se completarem os mil anos, Satanás será solto da sua prisão,', 1, CURRENT_TIMESTAMP, false),
(66, 20, 8, 'e sairá a enganar as nações que estão nos quatro cantos da terra, Gogue e Magogue, cujo número é como a areia do mar, a fim de ajuntá-las para a batalha.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 9, 'E subiram sobre a largura da terra, e cercaram o arraial dos santos e a cidade querida; mas desceu fogo do céu, e os devorou;', 1, CURRENT_TIMESTAMP, false),
(66, 20, 10, 'e o Diabo, que os enganava, foi lançado no lago de fogo e enxofre, onde estão a besta e o falso profeta; e de dia e de noite serão atormentados pelos séculos dos séculos.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 11, 'E vi um grande trono branco e o que estava assentado sobre ele, de cuja presença fugiram a terra e o céu; e não foi achado lugar para eles.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 12, 'E vi os mortos, grandes e pequenos, em pé diante do trono; e abriram-se uns livros; e abriu-se outro livro, que é o da vida; e os mortos foram julgados pelas coisas que estavam escritas nos livros, segundo as suas obras.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 13, 'O mar entregou os mortos que nele havia; e a morte e o além entregaram os mortos que neles havia; e foram julgados, cada um segundo as suas obras.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 14, 'E a morte e o inferno foram lançados no lago de fogo. Esta é a segunda morte, o lago de fogo.', 1, CURRENT_TIMESTAMP, false),
(66, 20, 15, 'E todo aquele que não foi achado inscrito no livro da vida, foi lançado no lago de fogo.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 1, 'E vi um novo céu e uma nova terra. Porque já se foram o primeiro céu e a primeira terra, e o mar já não existe.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 2, 'E vi a santa cidade, a nova Jerusalém, que descia do céu da parte de Deus, adereçada como uma noiva ataviada para o seu noivo.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 3, 'E ouvi uma grande voz, vinda do trono, que dizia: Eis que o tabernáculo de Deus está com os homens, pois com eles habitará, e eles serão o seu povo, e Deus mesmo estará com eles.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 4, 'Ele enxugará de seus olhos toda lágrima; e não haverá mais morte, nem haverá mais pranto, nem lamento, nem dor; porque já as primeiras coisas são passadas.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 5, 'E o que estava assentado sobre o trono disse: Eis que faço novas todas as coisas. E acrescentou: Escreve; porque estas palavras são fiéis e verdadeiras.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 6, 'Disse-me ainda: está cumprido: Eu sou o Alfa e o Ômega, o princípio e o fim. A quem tiver sede, de graça lhe darei a beber da fonte da água da vida.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 7, 'Aquele que vencer herdará estas coisas; e eu serei seu Deus, e ele será meu filho.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 8, 'Mas, quanto aos medrosos, e aos incrédulos, e aos abomináveis, e aos homicidas, e aos adúlteros, e aos feiticeiros, e aos idólatras, e a todos os mentirosos, a sua parte será no lago ardente de fogo e enxofre, que é a segunda morte.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 9, 'E veio um dos sete anjos que tinham as sete taças cheias das sete últimas pragas, e falou comigo, dizendo: Vem, mostrar-te-ei a noiva, a esposa do Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 10, 'E levou-me em espírito a um grande e alto monte, e mostrou-me a santa cidade de Jerusalém, que descia do céu da parte de Deus,', 1, CURRENT_TIMESTAMP, false),
(66, 21, 11, 'tendo a glória de Deus; e o seu brilho era semelhante a uma pedra preciosíssima, como se fosse jaspe cristalino;', 1, CURRENT_TIMESTAMP, false),
(66, 21, 12, 'e tinha um grande e alto muro com doze portas, e nas portas doze anjos, e nomes escritos sobre elas, que são os nomes das doze tribos dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 13, 'Ao oriente havia três portas, ao norte três portas, ao sul três portas, e ao ocidente três portas.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 14, 'O muro da cidade tinha doze fundamentos, e neles estavam os nomes dos doze apóstolos do Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 15, 'E aquele que falava comigo tinha por medida uma cana de ouro, para medir a cidade, as suas portas e o seu muro.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 16, 'A cidade era quadrangular; e o seu comprimento era igual à sua largura. E mediu a cidade com a cana e tinha ela doze mil estádios; e o seu cumprimento, largura e altura eram iguais.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 17, 'Também mediu o seu muro, e era de cento e quarenta e quatro côvados, segundo a medida de homem, isto é, de anjo.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 18, 'O muro era construído de jaspe, e a cidade era de ouro puro, semelhante a vidro límpido.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 19, 'Os fundamentos do muro da cidade estavam adornados de toda espécie de pedras preciosas. O primeiro fundamento era de jaspe; o segundo, de safira; o terceiro, de calcedônia; o quarto, de esmeralda;', 1, CURRENT_TIMESTAMP, false),
(66, 21, 20, 'o quinto, de sardônica; o sexto, de sárdio; o sétimo, de crisólito; o oitavo, de berilo; o nono, de topázio; o décimo, de crisópraso; o undécimo, de jacinto; o duodécimo, de ametista.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 21, 'As doze portas eram doze pérolas: cada uma das portas era de uma só pérola; e a praça da cidade era de ouro puro, transparente como vidro.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 22, 'Nela não vi santuário, porque o seu santuário é o Senhor Deus Todo-Poderoso, e o Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 23, 'A cidade não necessita nem do sol, nem da lua, para que nela resplandeçam, porém a glória de Deus a tem alumiado, e o Cordeiro é a sua lâmpada.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 24, 'As nações andarão à sua luz; e os reis da terra trarão para ela a sua glória.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 25, 'As suas portas não se fecharão de dia, e noite ali não haverá;', 1, CURRENT_TIMESTAMP, false),
(66, 21, 26, 'e a ela trarão a glória e a honra das nações.', 1, CURRENT_TIMESTAMP, false),
(66, 21, 27, 'E não entrará nela coisa alguma impura, nem o que pratica abominação ou mentira; mas somente os que estão inscritos no livro da vida do Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 1, 'E mostrou-me o rio da água da vida, claro como cristal, que procedia do trono de Deus e do Cordeiro.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 2, 'No meio da sua praça, e de ambos os lados do rio, estava a árvore da vida, que produz doze frutos, dando seu fruto de mês em mês; e as folhas da árvore são para a cura das nações.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 3, 'Ali não haverá jamais maldição. Nela estará o trono de Deus e do Cordeiro, e os seus servos o servirão,', 1, CURRENT_TIMESTAMP, false),
(66, 22, 4, 'e verão a sua face; e nas suas frontes estará o seu nome.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 5, 'E ali não haverá mais noite, e não necessitarão de luz de lâmpada nem de luz do sol, porque o Senhor Deus os alumiará; e reinarão pelos séculos dos séculos.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 6, 'E disse-me: Estas palavras são fiéis e verdadeiras; e o Senhor, o Deus dos espíritos dos profetas, enviou o seu anjo, para mostrar aos seus servos as coisas que em breve hão de acontecer.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 7, 'Eis que cedo venho! Bem-aventurado aquele que guarda as palavras da profecia deste livro.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 8, 'Eu, João, sou o que ouvi e vi estas coisas. E quando as ouvi e vi, prostrei-me aos pés do anjo que mas mostrava, para o adorar.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 9, 'Mas ele me disse: Olha, não faças tal; porque eu sou conservo teu e de teus irmãos, os profetas, e dos que guardam as palavras deste livro. Adora a Deus.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 10, 'Disse-me ainda: Não seles as palavras da profecia deste livro; porque próximo está o tempo.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 11, 'Quem é injusto, faça injustiça ainda: e quem está sujo, suje-se ainda; e quem é justo, faça justiça ainda; e quem é santo, santifique-se ainda.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 12, 'Eis que cedo venho e está comigo a minha recompensa, para retribuir a cada um segundo a sua obra.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 13, 'Eu sou o Alfa e o Ômega, o primeiro e o derradeiro, o princípio e o fim.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 14, 'Bem-aventurados aqueles que lavam as suas vestes {no sangue do Cordeiro} para que tenham direito à arvore da vida, e possam entrar na cidade pelas portas.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 15, 'Ficarão de fora os cães, os feiticeiros, os adúlteros, os homicidas, os idólatras, e todo o que ama e pratica a mentira.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 16, 'Eu, Jesus, enviei o meu anjo para vos testificar estas coisas a favor das igrejas. Eu sou a raiz e a geração de Davi, a resplandecente estrela da manhã.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 17, 'E o Espírito e a noiva dizem: Vem. E quem ouve, diga: Vem. E quem tem sede, venha; e quem quiser, receba de graça a água da vida.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 18, 'Eu testifico a todo aquele que ouvir as palavras da profecia deste livro: Se alguém lhes acrescentar alguma coisa, Deus lhe acrescentará as pragas que estão escritas neste livro;', 1, CURRENT_TIMESTAMP, false),
(66, 22, 19, 'e se alguém tirar qualquer coisa das palavras do livro desta profecia, Deus lhe tirará a sua parte da árvore da vida, e da cidade santa, que estão descritas neste livro.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 20, 'Aquele que testifica estas coisas diz: Certamente cedo venho. Amém; vem, Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(66, 22, 21, 'A graça do Senhor Jesus seja com todos.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 1, 'Fiz o primeiro tratado, ó Teófilo, acerca de tudo quanto Jesus começou a fazer e ensinar,', 1, CURRENT_TIMESTAMP, false),
(44, 1, 2, 'até o dia em que foi levado para cima, depois de haver dado mandamento, pelo Espírito Santo, aos apóstolos que escolhera;', 1, CURRENT_TIMESTAMP, false),
(44, 1, 3, 'aos quais também, depois de haver padecido, se apresentou vivo, com muitas provas infalíveis, aparecendo-lhes por espaço de quarenta dias, e lhes falando das coisas concernentes ao reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 4, 'Estando com eles, ordenou-lhes que não se ausentassem de Jerusalém, mas que esperassem a promessa do Pai, a qual {disse ele} de mim ouvistes.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 5, 'Porque, na verdade, João batizou em água, mas vós sereis batizados no Espírito Santo, dentro de poucos dias.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 6, 'Aqueles, pois, que se haviam reunido perguntavam-lhe, dizendo: Senhor, é nesse tempo que restauras o reino a Israel?', 1, CURRENT_TIMESTAMP, false),
(44, 1, 7, 'Respondeu-lhes: A vós não vos compete saber os tempos ou as épocas, que o Pai reservou à sua própria autoridade.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 8, 'Mas recebereis poder, ao descer sobre vós o Espírito Santo, e ser-me-eis testemunhas, tanto em Jerusalém, como em toda a Judéia e Samária, e até os confins da terra.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 9, 'Tendo ele dito estas coisas, foi levado para cima, enquanto eles olhavam, e uma nuvem o recebeu, ocultando-o a seus olhos.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 10, 'Estando eles com os olhos fitos no céu, enquanto ele subia, eis que junto deles apareceram dois varões vestidos de branco,', 1, CURRENT_TIMESTAMP, false),
(44, 1, 11, 'os quais lhes disseram: Varões galileus, por que ficais aí olhando para o céu? Esse Jesus, que dentre vós foi elevado para o céu, há de vir assim como para o céu o vistes ir.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 12, 'Então voltaram para Jerusalém, do monte chamado das Oliveiras, que está perto de Jerusalém, à distância da jornada de um sábado.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 13, 'E, entrando, subiram ao cenáculo, onde permaneciam Pedro e João, Tiago e André, Felipe e Tomé, Bartolomeu e Mateus; Tiago, filho de Alfeu, Simão o Zelote, e Judas, filho de Tiago.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 14, 'Todos estes perseveravam unanimemente em oração, com as mulheres, e Maria, mãe de Jesus, e com os irmãos dele.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 15, 'Naqueles dias levantou-se Pedro no meio dos irmãos, sendo o número de pessoas ali reunidas cerca de cento e vinte, e disse:', 1, CURRENT_TIMESTAMP, false),
(44, 1, 16, 'Irmãos, convinha que se cumprisse a escritura que o Espírito Santo predisse pela boca de Davi, acerca de Judas, que foi o guia daqueles que prenderam a Jesus;', 1, CURRENT_TIMESTAMP, false),
(44, 1, 17, 'pois ele era contado entre nós e teve parte neste ministério.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 18, '{Ora, ele adquiriu um campo com o salário da sua iniqüidade; e precipitando-se, caiu prostrado e arrebentou pelo meio, e todas as suas entranhas se derramaram.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 19, 'E tornou-se isto conhecido de todos os habitantes de Jerusalém; de maneira que na própria língua deles esse campo se chama Acéldama, isto é, Campo de Sangue.}', 1, CURRENT_TIMESTAMP, false),
(44, 1, 20, 'Porquanto no livro dos Salmos está escrito: Fique deserta a sua habitação, e não haja quem nela habite; e: Tome outro o seu ministério.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 21, 'É necessário, pois, que dos varões que conviveram conosco todo o tempo em que o Senhor Jesus andou entre nós,', 1, CURRENT_TIMESTAMP, false),
(44, 1, 22, 'começando desde o batismo de João até o dia em que dentre nós foi levado para cima, um deles se torne testemunha conosco da sua ressurreição.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 23, 'E apresentaram dois: José, chamado Barsabás, que tinha por sobrenome o Justo, e Matias.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 24, 'E orando, disseram: Tu, Senhor, que conheces os corações de todos, mostra qual destes dois tens escolhido', 1, CURRENT_TIMESTAMP, false),
(44, 1, 25, 'para tomar o lugar neste ministério e apostolado, do qual Judas se desviou para ir ao seu próprio lugar.', 1, CURRENT_TIMESTAMP, false),
(44, 1, 26, 'Então deitaram sortes a respeito deles e caiu a sorte sobre Matias, e por voto comum foi ele contado com os onze apóstolos.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 1, 'Ao cumprir-se o dia de Pentecostes, estavam todos reunidos no mesmo lugar.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 2, 'De repente veio do céu um ruído, como que de um vento impetuoso, e encheu toda a casa onde estavam sentados.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 3, 'E lhes apareceram umas línguas como que de fogo, que se distribuíam, e sobre cada um deles pousou uma.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 4, 'E todos ficaram cheios do Espírito Santo, e começaram a falar noutras línguas, conforme o Espírito lhes concedia que falassem.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 5, 'Habitavam então em Jerusalém judeus, homens piedosos, de todas as nações que há debaixo do céu.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 6, 'Ouvindo-se, pois, aquele ruído, ajuntou-se a multidão; e estava confusa, porque cada um os ouvia falar na sua própria língua.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 7, 'E todos pasmavam e se admiravam, dizendo uns aos outros: Pois quê! não são galileus todos esses que estão falando?', 1, CURRENT_TIMESTAMP, false),
(44, 2, 8, 'Como é, pois, que os ouvimos falar cada um na própria língua em que nascemos?', 1, CURRENT_TIMESTAMP, false),
(44, 2, 9, 'Nós, partos, medos, e elamitas; e os que habitamos a Mesopotâmia, a Judéia e a Capadócia, o Ponto e a Ásia,', 1, CURRENT_TIMESTAMP, false),
(44, 2, 10, 'a Frígia e a Panfília, o Egito e as partes da Líbia próximas a Cirene, e forasteiros romanos, tanto judeus como prosélitos,', 1, CURRENT_TIMESTAMP, false),
(44, 2, 11, 'cretenses e árabes-ouvímo-los em nossas línguas, falar das grandezas de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 12, 'E todos pasmavam e estavam perplexos, dizendo uns aos outros: Que quer dizer isto?', 1, CURRENT_TIMESTAMP, false),
(44, 2, 13, 'E outros, zombando, diziam: Estão cheios de mosto.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 14, 'Então Pedro, pondo-se em pé com os onze, levantou a voz e disse-lhes: Varões judeus e todos os que habitais em Jerusalém, seja-vos isto notório, e escutai as minhas palavras.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 15, 'Pois estes homens não estão embriagados, como vós pensais, visto que é apenas a terceira hora do dia.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 16, 'Mas isto é o que foi dito pelo profeta Joel:', 1, CURRENT_TIMESTAMP, false),
(44, 2, 17, 'E acontecerá nos últimos dias, diz o Senhor, que derramarei do meu Espírito sobre toda a carne; e os vossos filhos e as vossas filhas profetizarão, os vossos mancebos terão visões, os vossos anciãos terão sonhos;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 18, 'e sobre os meus servos e sobre as minhas servas derramarei do meu Espírito naqueles dias, e eles profetizarão.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 19, 'E mostrarei prodígios em cima no céu; e sinais embaixo na terra, sangue, fogo e vapor de fumaça.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 20, 'O sol se converterá em trevas, e a lua em sangue, antes que venha o grande e glorioso dia do Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 21, 'E acontecerá que todo aquele que invocar o nome do Senhor será salvo.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 22, 'Varões israelitas, escutai estas palavras: A Jesus, o nazareno, varão aprovado por Deus entre vós com milagres, prodígios e sinais, que Deus por ele fez no meio de vós, como vós mesmos bem sabeis;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 23, 'a este, que foi entregue pelo determinado conselho e presciência de Deus, vós matastes, crucificando-o pelas mãos de iníquos;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 24, 'ao qual Deus ressuscitou, rompendo os grilhões da morte, pois não era possível que fosse retido por ela.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 25, 'Porque dele fala Davi: Sempre via diante de mim o Senhor, porque está à minha direita, para que eu não seja abalado;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 26, 'por isso se alegrou o meu coração, e a minha língua exultou; e além disso a minha carne há de repousar em esperança;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 27, 'pois não deixarás a minha alma no inferno, nem permitirás que o teu Santo veja a corrupção;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 28, 'fizeste-me conhecer os caminhos da vida; encher-me-ás de alegria na tua presença.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 29, 'Irmãos, seja-me permitido dizer-vos livremente acerca do patriarca Davi, que ele morreu e foi sepultado, e entre nós está até hoje a sua sepultura.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 30, 'Sendo, pois, ele profeta, e sabendo que Deus lhe havia prometido com juramento que faria sentar sobre o seu trono um dos seus descendentes,', 1, CURRENT_TIMESTAMP, false),
(44, 2, 31, 'prevendo isto, Davi falou da ressurreição de Cristo, que a sua alma não foi deixada no inferno, nem a sua carne viu a corrupção.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 32, 'Ora, a este Jesus, Deus ressuscitou, do que todos nós somos testemunhas.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 33, 'De sorte que, exaltado pela destra de Deus, e tendo recebido do Pai a promessa do Espírito Santo, derramou isto que vós agora vedes e ouvis.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 34, 'Porque Davi não subiu aos céus, mas ele próprio declara: Disse o Senhor ao meu Senhor: Assenta-te à minha direita,', 1, CURRENT_TIMESTAMP, false),
(44, 2, 35, 'até que eu ponha os teus inimigos por escabelo de teus pés.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 36, 'Saiba pois com certeza toda a casa de Israel que a esse mesmo Jesus, a quem vós crucificastes, Deus o fez Senhor e Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 37, 'E, ouvindo eles isto, compungiram-se em seu coração, e perguntaram a Pedro e aos demais apóstolos: Que faremos, irmãos?', 1, CURRENT_TIMESTAMP, false),
(44, 2, 38, 'Pedro então lhes respondeu: Arrependei-vos, e cada um de vós seja batizado em nome de Jesus Cristo, para remissão de vossos pecados; e recebereis o dom do Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 39, 'Porque a promessa vos pertence a vós, a vossos filhos, e a todos os que estão longe: a quantos o Senhor nosso Deus chamar.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 40, 'E com muitas outras palavras dava testemunho, e os exortava, dizendo: salvai-vos desta geração perversa.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 41, 'De sorte que foram batizados os que receberam a sua palavra; e naquele dia agregaram-se quase três mil almas;', 1, CURRENT_TIMESTAMP, false),
(44, 2, 42, 'e perseveravam na doutrina dos apóstolos e na comunhão, no partir do pão e nas orações.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 43, 'Em cada alma havia temor, e muitos prodígios e sinais eram feitos pelos apóstolos.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 44, 'Todos os que criam estavam unidos e tinham tudo em comum.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 45, 'E vendiam suas propriedades e bens e os repartiam por todos, segundo a necessidade de cada um.', 1, CURRENT_TIMESTAMP, false),
(44, 2, 46, 'E, perseverando unânimes todos os dias no templo, e partindo o pão em casa, comiam com alegria e singeleza de coração,', 1, CURRENT_TIMESTAMP, false),
(44, 2, 47, 'louvando a Deus, e caindo na graça de todo o povo. E cada dia acrescentava-lhes o Senhor os que iam sendo salvos.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 1, 'Pedro e João subiam ao templo à hora da oração, a nona.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 2, 'E, era carregado um homem, coxo de nascença, o qual todos os dias punham à porta do templo, chamada Formosa, para pedir esmolas aos que entravam.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 3, 'Ora, vendo ele a Pedro e João, que iam entrando no templo, pediu que lhe dessem uma esmola.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 4, 'E Pedro, com João, fitando os olhos nele, disse: Olha para nós.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 5, 'E ele os olhava atentamente, esperando receber deles alguma coisa.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 6, 'Disse-lhe Pedro: Não tenho prata nem ouro; mas o que tenho, isso te dou; em nome de Jesus Cristo, o nazareno, anda.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 7, 'Nisso, tomando-o pela mão direita, o levantou; imediatamente os seus pés e artelhos se firmaram', 1, CURRENT_TIMESTAMP, false),
(44, 3, 8, 'e, dando ele um salto, pôs-se em pé. Começou a andar e entrou com eles no templo, andando, saltando e louvando a Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 9, 'Todo o povo, ao vê-lo andar e louvar a Deus,', 1, CURRENT_TIMESTAMP, false),
(44, 3, 10, 'reconhecia-o como o mesmo que estivera sentado a pedir esmola à Porta Formosa do templo; e todos ficaram cheios de pasmo e assombro, pelo que lhe acontecera.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 11, 'Apegando-se o homem a Pedro e João, todo o povo correu atônito para junto deles, ao pórtico chamado de Salomão.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 12, 'Pedro, vendo isto, disse ao povo: Varões israelitas, por que vos admirais deste homem? Ou, por que fitais os olhos em nós, como se por nosso próprio poder ou piedade o tivéssemos feito andar?', 1, CURRENT_TIMESTAMP, false),
(44, 3, 13, 'O Deus de Abraão, de Isaque e de Jacó, o Deus de nossos pais, glorificou a seu Servo Jesus, a quem vós entregastes e perante a face de Pilatos negastes, quando este havia resolvido soltá-lo.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 14, 'Mas vós negastes o Santo e Justo, e pedistes que se vos desse um homicida;', 1, CURRENT_TIMESTAMP, false),
(44, 3, 15, 'e matastes o Autor da vida, a quem Deus ressuscitou dentre os mortos, do que nós somos testemunhas.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 16, 'E pela fé em seu nome fez o seu nome fortalecer a este homem que vedes e conheceis; sim, a fé, que vem por ele, deu a este, na presença de todos vós, esta perfeita saúde.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 17, 'Agora, irmãos, eu sei que o fizestes por ignorância, como também as vossas autoridades.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 18, 'Mas Deus assim cumpriu o que já dantes pela boca de todos os seus profetas havia anunciado que o seu Cristo havia de padecer.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 19, 'Arrependei-vos, pois, e convertei-vos, para que sejam apagados os vossos pecados, de sorte que venham os tempos de refrigério, da presença do Senhor,', 1, CURRENT_TIMESTAMP, false),
(44, 3, 20, 'e envie ele o Cristo, que já dantes vos foi indicado, Jesus,', 1, CURRENT_TIMESTAMP, false),
(44, 3, 21, 'ao qual convém que o céu receba até os tempos da restauração de todas as coisas, das quais Deus falou pela boca dos seus santos profetas, desde o princípio.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 22, 'Pois Moisés disse: Suscitar-vos-á o Senhor vosso Deus, dentre vossos irmãos, um profeta semelhante a mim; a ele ouvireis em tudo quanto vos disser.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 23, 'E acontecerá que toda alma que não ouvir a esse profeta, será exterminada dentre o povo.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 24, 'E todos os profetas, desde Samuel e os que sucederam, quantos falaram, também anunciaram estes dias.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 25, 'Vós sois os filhos dos profetas e do pacto que Deus fez com vossos pais, dizendo a Abraão: Na tua descendência serão abençoadas todas as famílias da terra.', 1, CURRENT_TIMESTAMP, false),
(44, 3, 26, 'Deus suscitou a seu Servo, e a vós primeiramente vo-lo enviou para que vos abençoasse, desviando-vos, a cada um, das vossas maldades.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 1, 'Enquanto eles estavam falando ao povo, sobrevieram-lhes os sacerdotes, o capitão do templo e os saduceus,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 2, 'doendo-se muito de que eles ensinassem o povo, e anunciassem em Jesus a ressurreição dentre os mortos,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 3, 'deitaram mão neles, e os encerraram na prisão até o dia seguinte; pois era já tarde.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 4, 'Muitos, porém, dos que ouviram a palavra, creram, e se elevou o número dos homens a quase cinco mil.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 5, 'No dia seguinte, reuniram-se em Jerusalém as autoridades, os anciãos, os escribas,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 6, 'e Anás, o sumo sacerdote, e Caifás, João, Alexandre, e todos quantos eram da linhagem do sumo sacerdote.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 7, 'E, pondo-os no meio deles, perguntaram: Com que poder ou em nome de quem fizestes vós isto?', 1, CURRENT_TIMESTAMP, false),
(44, 4, 8, 'Então Pedro, cheio do Espírito Santo, lhes disse: Autoridades do povo e vós, anciãos,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 9, 'se nós hoje somos inquiridos acerca do benefício feito a um enfermo, e do modo como foi curado,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 10, 'seja conhecido de vós todos, e de todo o povo de Israel, que em nome de Jesus Cristo, o nazareno, aquele a quem vós crucificastes e a quem Deus ressuscitou dentre os mortos, nesse nome está este aqui, são diante de vós.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 11, 'Ele é a pedra que foi rejeitada por vós, os edificadores, a qual foi posta como pedra angular.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 12, 'E em nenhum outro há salvação; porque debaixo do céu nenhum outro nome há, dado entre os homens, em que devamos ser salvos.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 13, 'Então eles, vendo a intrepidez de Pedro e João, e tendo percebido que eram homens iletrados e indoutos, se admiravam; e reconheciam que haviam estado com Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 14, 'E vendo em pé com eles o homem que fora curado, nada tinham que dizer em contrário.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 15, 'Todavia, mandando-os sair do sinédrio, conferenciaram entre si,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 16, 'dizendo: Que havemos de fazer a estes homens? porque a todos os que habitam em Jerusalém é manifesto que por eles foi feito um sinal notório, e não o podemos negar.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 17, 'Mas, para que não se divulgue mais entre o povo, ameacemo-los para que de ora em diante não falem neste nome a homem algum.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 18, 'E, chamando-os, ordenaram-lhes que absolutamente não falassem nem ensinassem em nome de Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 19, 'Mas Pedro e João, respondendo, lhes disseram: Julgai vós se é justo diante de Deus ouvir-nos antes a vós do que a Deus;', 1, CURRENT_TIMESTAMP, false),
(44, 4, 20, 'pois nós não podemos deixar de falar das coisas que temos visto e ouvido.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 21, 'Mas eles ainda os ameaçaram mais, e, não achando motivo para os castigar, soltaram-nos, por causa do povo; porque todos glorificavam a Deus pelo que acontecera;', 1, CURRENT_TIMESTAMP, false),
(44, 4, 22, 'pois tinha mais de quarenta anos o homem em quem se operara esta cura milagrosa.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 23, 'E soltos eles, foram para os seus, e contaram tudo o que lhes haviam dito os principais sacerdotes e os anciãos.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 24, 'Ao ouvirem isto, levantaram unanimemente a voz a Deus e disseram: Senhor, tu que fizeste o céu, a terra, o mar, e tudo o que neles há;', 1, CURRENT_TIMESTAMP, false),
(44, 4, 25, 'que pelo Espírito Santo, por boca de nosso pai Davi, teu servo, disseste: Por que se enfureceram os gentios, e os povos imaginaram coisas vãs?', 1, CURRENT_TIMESTAMP, false),
(44, 4, 26, 'Levantaram-se os reis da terra, e as autoridades ajuntaram-se à uma, contra o Senhor e contra o seu Ungido.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 27, 'Porque verdadeiramente se ajuntaram, nesta cidade, contra o teu santo Servo Jesus, ao qual ungiste, não só Herodes, mas também Pôncio Pilatos com os gentios e os povos de Israel;', 1, CURRENT_TIMESTAMP, false),
(44, 4, 28, 'para fazerem tudo o que a tua mão e o teu conselho predeterminaram que se fizesse.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 29, 'Agora pois, ó Senhor, olha para as suas ameaças, e concede aos teus servos que falem com toda a intrepidez a tua palavra,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 30, 'enquanto estendes a mão para curar e para que se façam sinais e prodígios pelo nome de teu santo Servo Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 31, 'E, tendo eles orado, tremeu o lugar em que estavam reunidos; e todos foram cheios do Espírito Santo, e anunciavam com intrepidez a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 32, 'Da multidão dos que criam, era um só o coração e uma só a alma, e ninguém dizia que coisa alguma das que possuía era sua própria, mas todas as coisas lhes eram comuns.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 33, 'Com grande poder os apóstolos davam testemunho da ressurreição do Senhor Jesus, e em todos eles havia abundante graça.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 34, 'Pois não havia entre eles necessitado algum; porque todos os que possuíam terras ou casas, vendendo-as, traziam o preço do que vendiam e o depositavam aos pés dos apóstolos.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 35, 'E se repartia a qualquer um que tivesse necessidade.', 1, CURRENT_TIMESTAMP, false),
(44, 4, 36, 'Então José, cognominado pelos apóstolos Barnabé {que quer dizer, filho de consolação}, levita, natural de Chipre,', 1, CURRENT_TIMESTAMP, false),
(44, 4, 37, 'possuindo um campo, vendeu-o, trouxe o preço e o depositou aos pés dos apóstolos.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 1, 'Mas um certo homem chamado Ananias, com Safira, sua mulher, vendeu uma propriedade,', 1, CURRENT_TIMESTAMP, false),
(44, 5, 2, 'e reteve parte do preço, sabendo-o também sua mulher; e levando a outra parte, a depositou aos pés dos apóstolos.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 3, 'Disse então Pedro: Ananias, por que encheu Satanás o teu coração, para que mentisses ao Espírito Santo e retivesses parte do preço do terreno?', 1, CURRENT_TIMESTAMP, false),
(44, 5, 4, 'Enquanto o possuías, não era teu? e vendido, não estava o preço em teu poder? Como, pois, formaste este desígnio em teu coração? Não mentiste aos homens, mas a Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 5, 'E Ananias, ouvindo estas palavras, caiu e expirou. E grande temor veio sobre todos os que souberam disto.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 6, 'Levantando-se os moços, cobriram-no e, transportando-o para fora, o sepultaram.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 7, 'Depois de um intervalo de cerca de três horas, entrou também sua mulher, não sabendo o que havia acontecido.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 8, 'E perguntou-lhe Pedro: Dize-me: Vendestes por tanto aquele terreno? E ela respondeu: Sim, por tanto.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 9, 'Então Pedro lhe disse: Por que é que combinastes entre vós provar o Espírito do Senhor? Eis aí à porta os pés dos que sepultaram o teu marido, e te levarão também a ti.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 10, 'Imediatamente ela caiu aos pés dele e expirou. E entrando os moços, acharam-na morta e, levando-a para fora, sepultaram-na ao lado do marido.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 11, 'Sobreveio grande temor a toda a igreja e a todos os que ouviram estas coisas.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 12, 'E muitos sinais e prodígios eram feitos entre o povo pelas mãos dos apóstolos. E estavam todos de comum acordo no pórtico de Salomão.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 13, 'Dos outros, porém, nenhum ousava ajuntar-se a eles; mas o povo os tinha em grande estima;', 1, CURRENT_TIMESTAMP, false),
(44, 5, 14, 'e cada vez mais se agregavam crentes ao Senhor em grande número tanto de homens como de mulheres,', 1, CURRENT_TIMESTAMP, false),
(44, 5, 15, 'a ponto de transportarem os enfermos para as ruas, e os porem em leitos e macas, para que ao passar Pedro, ao menos sua sombra cobrisse alguns deles.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 16, 'Também das cidades circunvizinhas afluía muita gente a Jerusalém, conduzindo enfermos e atormentados de espíritos imundos, os quais eram todos curados.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 17, 'Levantando-se o sumo sacerdote e todos os que estavam com ele {isto é, a seita dos saduceus}, encheram-se de inveja,', 1, CURRENT_TIMESTAMP, false),
(44, 5, 18, 'deitaram mão nos apóstolos, e os puseram na prisão pública.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 19, 'Mas de noite um anjo do Senhor abriu as portas do cárcere e, tirando-os para fora, disse:', 1, CURRENT_TIMESTAMP, false),
(44, 5, 20, 'Ide, apresentai-vos no templo, e falai ao povo todas as palavras desta vida.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 21, 'Ora, tendo eles ouvido isto, entraram de manhã cedo no templo e ensinavam. Chegando, porém o sumo sacerdote e os que estavam com ele, convocaram o sinédrio, com todos os anciãos dos filhos de Israel, e enviaram guardas ao cárcere para trazê-los.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 22, 'Mas os guardas, tendo lá ido, não os acharam na prisão; e voltando, lho anunciaram,', 1, CURRENT_TIMESTAMP, false),
(44, 5, 23, 'dizendo: Achamos realmente o cárcere fechado com toda a segurança, e as sentinelas em pé às portas; mas, abrindo-as, a ninguém achamos dentro.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 24, 'E quando o capitão do templo e os principais sacerdotes ouviram estas palavras ficaram perplexos acerca deles e do que viria a ser isso.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 25, 'Então chegou alguém e lhes anunciou: Eis que os homens que encerrastes na prisão estão no templo, em pé, a ensinar o povo.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 26, 'Nisso foi o capitão com os guardas e os trouxe, não com violência, porque temiam ser apedrejados pelo povo.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 27, 'E tendo-os trazido, os apresentaram ao sinédrio. E o sumo sacerdote os interrogou, dizendo:', 1, CURRENT_TIMESTAMP, false),
(44, 5, 28, 'Não vos admoestamos expressamente que não ensinásseis nesse nome? e eis que enchestes Jerusalém dessa vossa doutrina e quereis lançar sobre nós o sangue desse homem.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 29, 'Respondendo Pedro e os apóstolos, disseram: Importa antes obedecer a Deus que aos homens.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 30, 'O Deus de nossos pais ressuscitou a Jesus, ao qual vós matastes, suspendendo-o no madeiro;', 1, CURRENT_TIMESTAMP, false),
(44, 5, 31, 'sim, Deus, com a sua destra, o elevou a Príncipe e Salvador, para dar a Israel o arrependimento e remissão de pecados.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 32, 'E nós somos testemunhas destas coisas, e bem assim o Espírito Santo, que Deus deu àqueles que lhe obedecem.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 33, 'Ora, ouvindo eles isto, se enfureceram e queriam matá-los.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 34, 'Mas, levantando-se no sinédrio certo fariseu chamado Gamaliel, doutor da lei, acatado por todo o povo, mandou que por um pouco saíssem aqueles homens;', 1, CURRENT_TIMESTAMP, false),
(44, 5, 35, 'e prosseguiu: Varões israelitas, acautelai-vos a respeito do que estais para fazer a estes homens.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 36, 'Porque, há algum tempo, levantou-se Teudas, dizendo ser alguém; ao qual se ajuntaram uns quatrocentos homens; mas ele foi morto, e todos quantos lhe obedeciam foram dispersos e reduzidos a nada.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 37, 'Depois dele levantou-se Judas, o galileu, nos dias do recenseamento, e levou muitos após si; mas também este pereceu, e todos quantos lhe obedeciam foram dispersos.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 38, 'Agora vos digo: Dai de mão a estes homens, e deixai-os, porque este conselho ou esta obra, caso seja dos homens, se desfará;', 1, CURRENT_TIMESTAMP, false),
(44, 5, 39, 'mas, se é de Deus, não podereis derrotá-los; para que não sejais, porventura, achados até combatendo contra Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 40, 'Concordaram, pois, com ele, e tendo chamado os apóstolos, açoitaram-nos e mandaram que não falassem em nome de Jesus, e os soltaram.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 41, 'Retiraram-se pois da presença do sinédrio, regozijando-se de terem sido julgados dignos de sofrer afronta pelo nome de Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 5, 42, 'E todos os dias, no templo e de casa em casa, não cessavam de ensinar, e de anunciar a Jesus, o Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 1, 'Ora, naqueles dias, crescendo o número dos discípulos, houve uma murmuração dos helenistas contra os hebreus, porque as viúvas daqueles estavam sendo esquecidas na distribuição diária.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 2, 'E os doze, convocando a multidão dos discípulos, disseram: Não é razoável que nós deixemos a palavra de Deus e sirvamos às mesas.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 3, 'Escolhei, pois, irmãos, dentre vós, sete homens de boa reputação, cheios do Espírito Santo e de sabedoria, aos quais encarreguemos deste serviço.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 4, 'Mas nós perseveraremos na oração e no ministério da palavra.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 5, 'O parecer agradou a todos, e elegeram a Estevão, homem cheio de fé e do Espírito Santo, Filipe, Prócoro, Nicanor, Timão, Pármenas, e Nicolau, prosélito de Antioquia,', 1, CURRENT_TIMESTAMP, false),
(44, 6, 6, 'e os apresentaram perante os apóstolos; estes, tendo orado, lhes impuseram as mãos.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 7, 'E divulgava-se a palavra de Deus, de sorte que se multiplicava muito o número dos discípulos em Jerusalém e muitos sacerdotes obedeciam à fé.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 8, 'Ora, Estêvão, cheio de graça e poder, fazia prodígios e grandes sinais entre o povo.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 9, 'Levantaram-se, porém, alguns que eram da sinagoga chamada dos libertos, dos cireneus, dos alexandrinos, dos da Cilícia e da Ásia, e disputavam com Estêvão;', 1, CURRENT_TIMESTAMP, false),
(44, 6, 10, 'e não podiam resistir à sabedoria e ao Espírito com que falava.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 11, 'Então subornaram uns homens para que dissessem: Temo-lo ouvido proferir palavras blasfemas contra Moisés e contra Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 12, 'Assim excitaram o povo, os anciãos, e os escribas; e investindo contra ele, o arrebataram e o levaram ao sinédrio;', 1, CURRENT_TIMESTAMP, false),
(44, 6, 13, 'e apresentaram falsas testemunhas que diziam: Este homem não cessa de proferir palavras contra este santo lugar e contra a lei;', 1, CURRENT_TIMESTAMP, false),
(44, 6, 14, 'porque nós o temos ouvido dizer que esse Jesus, o nazareno, há de destruir este lugar e mudar os costumes que Moisés nos transmitiu.', 1, CURRENT_TIMESTAMP, false),
(44, 6, 15, 'Então todos os que estavam assentados no sinédrio, fitando os olhos nele, viram o seu rosto como de um anjo.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 1, 'E disse o sumo sacerdote: Porventura são assim estas coisas?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 2, 'Estêvão respondeu: Irmãos e pais, ouvi. O Deus da glória apareceu a nosso pai Abraão, estando ele na Mesopotâmia, antes de habitar em Harã,', 1, CURRENT_TIMESTAMP, false),
(44, 7, 3, 'e disse-lhe: Sai da tua terra e dentre a tua parentela, e dirige-te à terra que eu te mostrar.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 4, 'Então saiu da terra dos caldeus e habitou em Harã. Dali, depois que seu pai faleceu, Deus o trouxe para esta terra em que vós agora habitais.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 5, 'E não lhe deu nela herança, nem sequer o espaço de um pé; mas prometeu que lha daria em possessão, e depois dele à sua descendência, não tendo ele ainda filho.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 6, 'Pois Deus disse que a sua descendência seria peregrina em terra estranha e que a escravizariam e maltratariam por quatrocentos anos.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 7, 'Mas eu julgarei a nação que os tiver escravizado, disse Deus; e depois disto sairão, e me servirão neste lugar.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 8, 'E deu-lhe o pacto da circuncisão; assim então gerou Abraão a Isaque, e o circuncidou ao oitavo dia; e Isaque gerou a Jacó, e Jacó aos doze patriarcas.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 9, 'Os patriarcas, movidos de inveja, venderam José para o Egito; mas Deus era com ele,', 1, CURRENT_TIMESTAMP, false),
(44, 7, 10, 'e o livrou de todas as suas tribulações, e lhe deu graça e sabedoria perante Faraó, rei do Egito, que o constituiu governador sobre o Egito e toda a sua casa.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 11, 'Sobreveio então uma fome a todo o Egito e Canaã, e grande tribulação; e nossos pais não achavam alimentos.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 12, 'Mas tendo ouvido Jacó que no Egito havia trigo, enviou ali nossos pais pela primeira vez.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 13, 'E na segunda vez deu-se José a conhecer a seus irmãos, e a sua linhagem tornou-se manifesta a Faraó.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 14, 'Então José mandou chamar a seu pai Jacó, e a toda a sua parentela-setenta e cinco almas.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 15, 'Jacó, pois, desceu ao Egito, onde morreu, ele e nossos pais;', 1, CURRENT_TIMESTAMP, false),
(44, 7, 16, 'e foram transportados para Siquém e depositados na sepultura que Abraão comprara por certo preço em prata aos filhos de Emor, em Siquém.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 17, 'Enquanto se aproximava o tempo da promessa que Deus tinha feito a Abraão, o povo crescia e se multiplicava no Egito;', 1, CURRENT_TIMESTAMP, false),
(44, 7, 18, 'até que se levantou ali outro rei, que não tinha conhecido José.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 19, 'Usando esse de astúcia contra a nossa raça, maltratou a nossos pais, ao ponto de fazê-los enjeitar seus filhos, para que não vivessem.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 20, 'Nesse tempo nasceu Moisés, e era mui formoso, e foi criado três meses em casa de seu pai.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 21, 'Sendo ele enjeitado, a filha de Faraó o recolheu e o criou como seu próprio filho.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 22, 'Assim Moisés foi instruído em toda a sabedoria dos egípcios, e era poderoso em palavras e obras.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 23, 'Ora, quando ele completou quarenta anos, veio-lhe ao coração visitar seus irmãos, os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 24, 'E vendo um deles sofrer injustamente, defendeu-o, e vingou o oprimido, matando o egípcio.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 25, 'Cuidava que seus irmãos entenderiam que por mão dele Deus lhes havia de dar a liberdade; mas eles não entenderam.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 26, 'No dia seguinte apareceu-lhes quando brigavam, e quis levá-los à paz, dizendo: Homens, sois irmãos; por que vos maltratais um ao outro?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 27, 'Mas o que fazia injustiça ao seu próximo o repeliu, dizendo: Quem te constituiu senhor e juiz sobre nós?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 28, 'Acaso queres tu matar-me como ontem mataste o egípcio?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 29, 'A esta palavra fugiu Moisés, e tornou-se peregrino na terra de Madiã, onde gerou dois filhos.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 30, 'E passados mais quarenta anos, apareceu-lhe um anjo no deserto do monte Sinai, numa chama de fogo no meio de uma sarça.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 31, 'Moisés, vendo isto, admirou-se da visão; e, aproximando-se ele para observar, soou a voz do Senhor:', 1, CURRENT_TIMESTAMP, false),
(44, 7, 32, 'Eu sou o deus de teus pais, o Deus de Abraão, de Isaque e de Jacó. E Moisés ficou trêmulo e não ousava olhar.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 33, 'Disse-lhe então o Senhor: Tira as alparcas dos teus pés, porque o lugar em que estás é terra santa.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 34, 'Vi, com efeito, a aflição do meu povo no Egito, ouvi os seus gemidos, e desci para livrá-lo. Agora pois vem, e enviar-te-ei ao Egito.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 35, 'A este Moisés que eles haviam repelido, dizendo: Quem te constituiu senhor e juiz? a este enviou Deus como senhor e libertador, pela mão do anjo que lhe aparecera na sarça.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 36, 'Foi este que os conduziu para fora, fazendo prodígios e sinais na terra do Egito, e no Mar Vermelho, e no deserto por quarenta anos.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 37, 'Este é o Moisés que disse aos filhos de Israel: Deus vos suscitará dentre vossos irmãos um profeta como eu.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 38, 'Este é o que esteve na congregação no deserto, com o anjo que lhe falava no monte Sinai, e com nossos pais, o qual recebeu palavras de vida para vo-las dar;', 1, CURRENT_TIMESTAMP, false),
(44, 7, 39, 'ao qual os nossos pais não quiseram obedecer, antes o rejeitaram, e em seus corações voltaram ao Egito,', 1, CURRENT_TIMESTAMP, false),
(44, 7, 40, 'dizendo a Arão: Faze-nos deuses que vão adiante de nós; porque a esse Moisés que nos tirou da terra do Egito, não sabemos o que lhe aconteceu.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 41, 'Fizeram, pois, naqueles dias o bezerro, e ofereceram sacrifício ao ídolo, e se alegravam nas obras das suas mãos.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 42, 'Mas Deus se afastou, e os abandonou ao culto das hostes do céu, como está escrito no livro dos profetas: Porventura me oferecestes vítimas e sacrifícios por quarenta anos no deserto, ó casa de Israel?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 43, 'Antes carregastes o tabernáculo de Moloque e a estrela do deus Renfã, figuras que vós fizestes para adorá-las. Desterrar-vos-ei pois, para além da Babilônia.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 44, 'Entre os nossos pais no deserto estava o tabernáculo do testemunho, como ordenara aquele que disse a Moisés que o fizesse segundo o modelo que tinha visto;', 1, CURRENT_TIMESTAMP, false),
(44, 7, 45, 'o qual nossos pais, tendo-o por sua vez recebido, o levaram sob a direção de Josué, quando entraram na posse da terra das nações que Deus expulsou da presença dos nossos pais, até os dias de Davi,', 1, CURRENT_TIMESTAMP, false),
(44, 7, 46, 'que achou graça diante de Deus, e pediu que lhe fosse dado achar habitação para o Deus de Jacó.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 47, 'Entretanto foi Salomão quem lhe edificou uma casa;', 1, CURRENT_TIMESTAMP, false),
(44, 7, 48, 'mas o Altíssimo não habita em templos feitos por mãos de homens, como diz o profeta:', 1, CURRENT_TIMESTAMP, false),
(44, 7, 49, 'O céu é meu trono, e a terra o escabelo dos meus pés. Que casa me edificareis, diz o Senhor, ou qual o lugar do meu repouso?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 50, 'Não fez, porventura, a minha mão todas estas coisas?', 1, CURRENT_TIMESTAMP, false),
(44, 7, 51, 'Homens de dura cerviz, e incircuncisos de coração e ouvido, vós sempre resistis ao Espírito Santo; como o fizeram os vossos pais, assim também vós.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 52, 'A qual dos profetas não perseguiram vossos pais? Até mataram os que dantes anunciaram a vinda do Justo, do qual vós agora vos tornastes traidores e homicidas,', 1, CURRENT_TIMESTAMP, false),
(44, 7, 53, 'vós, que recebestes a lei por ordenação dos anjos, e não a guardastes.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 54, 'Ouvindo eles isto, enfureciam-se em seus corações, e rangiam os dentes contra Estêvão.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 55, 'Mas ele, cheio do Espírito Santo, fitando os olhos no céu, viu a glória de Deus, e Jesus em pé à direita de Deus,', 1, CURRENT_TIMESTAMP, false),
(44, 7, 56, 'e disse: Eis que vejo os céus abertos, e o Filho do homem em pé à direita de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 57, 'Então eles gritaram com grande voz, taparam os ouvidos, e arremeteram unânimes contra ele', 1, CURRENT_TIMESTAMP, false),
(44, 7, 58, 'e, lançando-o fora da cidade, o apedrejavam. E as testemunhas depuseram as suas vestes aos pés de um mancebo chamado Saulo.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 59, 'Apedrejavam, pois, a Estêvão que orando, dizia: Senhor Jesus, recebe o meu espírito.', 1, CURRENT_TIMESTAMP, false),
(44, 7, 60, 'E pondo-se de joelhos, clamou com grande voz: Senhor, não lhes imputes este pecado. Tendo dito isto, adormeceu. E Saulo consentia na sua morte.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 1, 'Naquele dia levantou-se grande perseguição contra a igreja que estava em Jerusalém; e todos exceto os apóstolos, foram dispersos pelas regiões da Judéia e da Samária.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 2, 'E uns homens piedosos sepultaram a Estêvão, e fizeram grande pranto sobre ele.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 3, 'Saulo porém, assolava a igreja, entrando pelas casas e, arrastando homens e mulheres, os entregava à prisão.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 4, 'No entanto os que foram dispersos iam por toda parte, anunciando a palavra.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 5, 'E descendo Filipe à cidade de Samária, pregava-lhes a Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 6, 'As multidões escutavam, unânimes, as coisas que Filipe dizia, ouvindo-o e vendo os sinais que operava;', 1, CURRENT_TIMESTAMP, false),
(44, 8, 7, 'pois saíam de muitos possessos os espíritos imundos, clamando em alta voz; e muitos paralíticos e coxos foram curados;', 1, CURRENT_TIMESTAMP, false),
(44, 8, 8, 'pelo que houve grande alegria naquela cidade.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 9, 'Ora, estava ali certo homem chamado Simão, que vinha exercendo naquela cidade a arte mágica, fazendo pasmar o povo da Samária, e dizendo ser ele uma grande personagem;', 1, CURRENT_TIMESTAMP, false),
(44, 8, 10, 'ao qual todos atendiam, desde o menor até o maior, dizendo: Este é o Poder de Deus que se chama Grande.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 11, 'Eles o atendiam porque já desde muito tempo os vinha fazendo pasmar com suas artes mágicas.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 12, 'Mas, quando creram em Filipe, que lhes pregava acerca do reino de Deus e do nome de Jesus, batizavam-se homens e mulheres.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 13, 'E creu até o próprio Simão e, sendo batizado, ficou de contínuo com Filipe; e admirava-se, vendo os sinais e os grandes milagres que se faziam.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 14, 'Os apóstolos, pois, que estavam em Jerusalém, tendo ouvido que os da Samária haviam recebido a palavra de Deus, enviaram-lhes Pedro e João;', 1, CURRENT_TIMESTAMP, false),
(44, 8, 15, 'os quais, tendo descido, oraram por eles, para que recebessem o Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 16, 'Porque sobre nenhum deles havia ele descido ainda; mas somente tinham sido batizados em nome do Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 17, 'Então lhes impuseram as mãos, e eles receberam o Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 18, 'Quando Simão viu que pela imposição das mãos dos apóstolos se dava o Espírito Santo, ofereceu-lhes dinheiro,', 1, CURRENT_TIMESTAMP, false),
(44, 8, 19, 'dizendo: Dai-me também a mim esse poder, para que aquele sobre quem eu impuser as mãos, receba o Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 20, 'Mas disse-lhe Pedro: Vá tua prata contigo à perdição, pois cuidaste adquirir com dinheiro o dom de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 21, 'Tu não tens parte nem sorte neste ministério, porque o teu coração não é reto diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 22, 'Arrepende-te, pois, dessa tua maldade, e roga ao Senhor para que porventura te seja perdoado o pensamento do teu coração;', 1, CURRENT_TIMESTAMP, false),
(44, 8, 23, 'pois vejo que estás em fel de amargura, e em laços de iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 24, 'Respondendo, porém, Simão, disse: Rogai vós por mim ao Senhor, para que nada do que haveis dito venha sobre mim.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 25, 'Eles, pois, havendo testificado e falado a palavra do Senhor, voltando para Jerusalém, evangelizavam muitas aldeias dos samaritanos.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 26, 'Mas um anjo do Senhor falou a Filipe, dizendo: Levanta-te, e vai em direção do sul pelo caminho que desce de Jerusalém a Gaza, o qual está deserto.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 27, 'E levantou-se e foi; e eis que um etíope, eunuco, mordomo-mor de Candace, rainha dos etíopes, o qual era superintendente de todos os seus tesouros e tinha ido a Jerusalém para adorar,', 1, CURRENT_TIMESTAMP, false),
(44, 8, 28, 'regressava e, sentado no seu carro, lia o profeta Isaías.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 29, 'Disse o Espírito a Filipe: Chega-te e ajunta-te a esse carro.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 30, 'E correndo Filipe, ouviu que lia o profeta Isaías, e disse: Entendes, porventura, o que estás lendo?', 1, CURRENT_TIMESTAMP, false),
(44, 8, 31, 'Ele respondeu: Pois como poderei entender, se alguém não me ensinar? e rogou a Filipe que subisse e com ele se sentasse.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 32, 'Ora, a passagem da Escritura que estava lendo era esta: Foi levado como a ovelha ao matadouro, e, como está mudo o cordeiro diante do que o tosquia, assim ele não abre a sua boca.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 33, 'Na sua humilhação foi tirado o seu julgamento; quem contará a sua geração? porque a sua vida é tirada da terra.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 34, 'Respondendo o eunuco a Filipe, disse: Rogo-te, de quem diz isto o profeta? de si mesmo, ou de algum outro?', 1, CURRENT_TIMESTAMP, false),
(44, 8, 35, 'Então Filipe tomou a palavra e, começando por esta escritura, anunciou-lhe a Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 36, 'E indo eles caminhando, chegaram a um lugar onde havia água, e disse o eunuco: Eis aqui água; que impede que eu seja batizado?', 1, CURRENT_TIMESTAMP, false),
(44, 8, 37, '{E disse Felipe: é lícito, se crês de todo o coração. E, respondendo ele, disse: Creio que Jesus Cristo é o Filho de Deus.}', 1, CURRENT_TIMESTAMP, false),
(44, 8, 38, 'mandou parar o carro, e desceram ambos à água, tanto Filipe como o eunuco, e Filipe o batizou.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 39, 'Quando saíram da água, o Espírito do Senhor arrebatou a Filipe, e não o viu mais o eunuco, que jubiloso seguia o seu caminho.', 1, CURRENT_TIMESTAMP, false),
(44, 8, 40, 'Mas Filipe achou-se em Azoto e, indo passando, evangelizava todas as cidades, até que chegou a Cesaréia.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 1, 'Saulo, porém, respirando ainda ameaças e mortes contra os discípulos do Senhor, dirigiu-se ao sumo sacerdote,', 1, CURRENT_TIMESTAMP, false),
(44, 9, 2, 'e pediu-lhe cartas para Damasco, para as sinagogas, a fim de que, caso encontrasse alguns do Caminho, quer homens quer mulheres, os conduzisse presos a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 3, 'Mas, seguindo ele viagem e aproximando-se de Damasco, subitamente o cercou um resplendor de luz do céu;', 1, CURRENT_TIMESTAMP, false),
(44, 9, 4, 'e, caindo por terra, ouviu uma voz que lhe dizia: Saulo, Saulo, por que me persegues?', 1, CURRENT_TIMESTAMP, false),
(44, 9, 5, 'Ele perguntou: Quem és tu, Senhor? Respondeu o Senhor: Eu sou Jesus, a quem tu persegues;', 1, CURRENT_TIMESTAMP, false),
(44, 9, 6, 'mas levanta-te e entra na cidade, e lá te será dito o que te cumpre fazer.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 7, 'Os homens que viajavam com ele quedaram-se emudecidos, ouvindo, na verdade, a voz, mas não vendo ninguém.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 8, 'Saulo levantou-se da terra e, abrindo os olhos, não via coisa alguma; e, guiando-o pela mão, conduziram-no a Damasco.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 9, 'E esteve três dias sem ver, e não comeu nem bebeu.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 10, 'Ora, havia em Damasco certo discípulo chamado Ananias; e disse-lhe o Senhor em visão: Ananias! Respondeu ele: Eis-me aqui, Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 11, 'Ordenou-lhe o Senhor: Levanta-te, vai à rua chamada Direita e procura em casa de Judas um homem de Tarso chamado Saulo; pois eis que ele está orando;', 1, CURRENT_TIMESTAMP, false),
(44, 9, 12, 'e viu um homem chamado Ananias entrar e impor-lhe as mãos, para que recuperasse a vista.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 13, 'Respondeu Ananias: Senhor, a muitos ouvi acerca desse homem, quantos males tem feito aos teus santos em Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(44, 9, 14, 'e aqui tem poder dos principais sacerdotes para prender a todos os que invocam o teu nome.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 15, 'Disse-lhe, porém, o Senhor: Vai, porque este é para mim um vaso escolhido, para levar o meu nome perante os gentios, e os reis, e os filhos de Israel;', 1, CURRENT_TIMESTAMP, false),
(44, 9, 16, 'pois eu lhe mostrarei quanto lhe cumpre padecer pelo meu nome.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 17, 'Partiu Ananias e entrou na casa e, impondo-lhe as mãos, disse: Irmão Saulo, o Senhor Jesus, que te apareceu no caminho por onde vinhas, enviou-me para que tornes a ver e sejas cheio do Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 18, 'Logo lhe caíram dos olhos como que umas escamas, e recuperou a vista: então, levantando-se, foi batizado.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 19, 'E, tendo tomado alimento, ficou fortalecido. Depois demorou-se alguns dias com os discípulos que estavam em Damasco;', 1, CURRENT_TIMESTAMP, false),
(44, 9, 20, 'e logo nas sinagogas pregava a Jesus, que este era o filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 21, 'Todos os seus ouvintes pasmavam e diziam: Não é este o que em Jerusalém perseguia os que invocavam esse nome, e para isso veio aqui, para os levar presos aos principais sacerdotes?', 1, CURRENT_TIMESTAMP, false),
(44, 9, 22, 'Saulo, porém, se fortalecia cada vez mais e confundia os judeus que habitavam em Damasco, provando que Jesus era o Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 23, 'Decorridos muitos dias, os judeus deliberaram entre si matá-lo.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 24, 'Mas as suas ciladas vieram ao conhecimento de Saulo. E como eles guardavam as portas de dia e de noite para tirar-lhe a vida,', 1, CURRENT_TIMESTAMP, false),
(44, 9, 25, 'os discípulos, tomando-o de noite, desceram-no pelo muro, dentro de um cesto.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 26, 'Tendo Saulo chegado a Jerusalém, procurava juntar-se aos discípulos; mas todos o temiam, não crendo que fosse discípulo.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 27, 'Então Barnabé, tomando-o consigo, o levou aos apóstolos, e lhes contou como no caminho ele vira o Senhor e que este lhe falara, e como em Damasco pregara ousadamente em nome de Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 28, 'Assim andava com eles em Jerusalém, entrando e saindo,', 1, CURRENT_TIMESTAMP, false),
(44, 9, 29, 'e pregando ousadamente em nome do Senhor. Falava e disputava também com os helenistas; mas procuravam matá-lo.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 30, 'Os irmãos, porém, quando o souberam, acompanharam-no até Cesaréia e o enviaram a Tarso.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 31, 'Assim, pois, a igreja em toda a Judéia, Galiléia e Samária, tinha paz, sendo edificada, e andando no temor do Senhor; e, pelo auxílio do Espírito Santo, se multiplicava.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 32, 'E aconteceu que, passando Pedro por toda parte, veio também aos santos que habitavam em Lida.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 33, 'Achou ali certo homem, chamado Enéias, que havia oito anos jazia numa cama, porque era paralítico.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 34, 'Disse-lhe Pedro: Enéias, Jesus Cristo te cura; levanta e faze a tua cama. E logo se levantou.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 35, 'E viram-no todos os que habitavam em Lida e Sarona, os quais se converteram ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 36, 'Havia em Jope uma discípula por nome Tabita, que traduzido quer dizer Dorcas, a qual estava cheia de boas obras e esmolas que fazia.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 37, 'Ora, aconteceu naqueles dias que ela, adoecendo, morreu; e, tendo-a lavado, a colocaram no cenáculo.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 38, 'Como Lida era perto de Jope, ouvindo os discípulos que Pedro estava ali, enviaram-lhe dois homens, rogando-lhe: Não te demores em vir ter conosco.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 39, 'Pedro levantou-se e foi com eles; quando chegou, levaram-no ao cenáculo; e todas as viúvas o cercaram, chorando e mostrando-lhe as túnicas e vestidos que Dorcas fizera enquanto estava com elas.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 40, 'Mas Pedro, tendo feito sair a todos, pôs-se de joelhos e orou; e voltando-se para o corpo, disse: Tabita, levanta-te. Ela abriu os olhos e, vendo a Pedro, sentou-se.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 41, 'Ele, dando-lhe a mão, levantou-a e, chamando os santos e as viúvas, apresentou-lha viva.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 42, 'Tornou-se isto notório por toda a Jope, e muitos creram no Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 9, 43, 'Pedro ficou muitos dias em Jope, em casa de um curtidor chamado Simão.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 1, 'Um homem em Cesaréia, por nome Cornélio, centurião da corte chamada italiana,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 2, 'piedoso e temente a Deus com toda a sua casa, e que fazia muitas esmolas ao povo e de contínuo orava a Deus,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 3, 'cerca da hora nona do dia, viu claramente em visão um anjo de Deus, que se dirigia para ele e lhe dizia: Cornélio!', 1, CURRENT_TIMESTAMP, false),
(44, 10, 4, 'Este, fitando nele os olhos e atemorizado, perguntou: Que é, Senhor? O anjo respondeu-lhe: As tuas orações e as tuas esmolas têm subido para memória diante de Deus;', 1, CURRENT_TIMESTAMP, false),
(44, 10, 5, 'agora, pois, envia homens a Jope e manda chamar a Simão, que tem por sobrenome Pedro;', 1, CURRENT_TIMESTAMP, false),
(44, 10, 6, 'este se acha hospedado com um certo Simão, curtidor, cuja casa fica à beira-mar. {Ele te dirá o que deves fazer.}', 1, CURRENT_TIMESTAMP, false),
(44, 10, 7, 'Logo que se retirou o anjo que lhe falava, Cornélio chamou dois dos seus domésticos e um piedoso soldado dos que estavam a seu serviço;', 1, CURRENT_TIMESTAMP, false),
(44, 10, 8, 'e, havendo contado tudo, os enviou a Jope.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 9, 'No dia seguinte, indo eles seu caminho e estando já perto da cidade, subiu Pedro ao eirado para orar, cerca de hora sexta.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 10, 'E tendo fome, quis comer; mas enquanto lhe preparavam a comida, sobreveio-lhe um êxtase,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 11, 'e via o céu aberto e um objeto descendo, como se fosse um grande lençol, sendo baixado pelas quatro pontas sobre a terra,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 12, 'no qual havia de todos os quadrúpedes e répteis da terra e aves do céu.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 13, 'E uma voz lhe disse: Levanta-te, Pedro, mata e come.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 14, 'Mas Pedro respondeu: De modo nenhum, Senhor, porque nunca comi coisa alguma comum e imunda.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 15, 'Pela segunda vez lhe falou a voz: Não chames tu comum ao que Deus purificou.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 16, 'Sucedeu isto por três vezes; e logo foi o objeto recolhido ao céu.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 17, 'Enquanto Pedro refletia, perplexo, sobre o que seria a visão que tivera, eis que os homens enviados por Cornélio, tendo perguntado pela casa de Simão, pararam à porta.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 18, 'E, chamando, indagavam se ali estava hospedado Simão, que tinha por sobrenome Pedro.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 19, 'Estando Pedro ainda a meditar sobre a visão, o Espírito lhe disse: Eis que dois homens te procuram.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 20, 'Levanta-te, pois, desce e vai com eles, nada duvidando; porque eu tos enviei.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 21, 'E descendo Pedro ao encontro desses homens, disse: Sou eu a quem procurais; qual é a causa por que viestes?', 1, CURRENT_TIMESTAMP, false),
(44, 10, 22, 'Eles responderam: O centurião Cornélio, homem justo e temente a Deus e que tem bom testemunho de toda a nação judaica, foi avisado por um santo anjo para te chamar à sua casa e ouvir as tuas palavras.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 23, 'Pedro, pois, convidando-os a entrar, os hospedou. No dia seguinte levantou-se e partiu com eles, e alguns irmãos, dentre os de Jope, o acompanharam.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 24, 'No outro dia entrou em Cesaréia. E Cornélio os esperava, tendo reunido os seus parentes e amigos mais íntimos.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 25, 'Quando Pedro ia entrar, veio-lhe Cornélio ao encontro e, prostrando-se a seus pés, o adorou.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 26, 'Mas Pedro o ergueu, dizendo: Levanta-te, que eu também sou homem.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 27, 'E conversando com ele, entrou e achou muitos reunidos,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 28, 'e disse-lhes: Vós bem sabeis que não é lícito a um judeu ajuntar-se ou chegar-se a estrangeiros; mas Deus mostrou-me que a nenhum homem devo chamar comum ou imundo;', 1, CURRENT_TIMESTAMP, false),
(44, 10, 29, 'pelo que, sendo chamado, vim sem objeção. Pergunto pois: Por que razão mandastes chamar-me?', 1, CURRENT_TIMESTAMP, false),
(44, 10, 30, 'Então disse Cornélio: Faz agora quatro dias que eu estava orando em minha casa à hora nona, e eis que diante de mim se apresentou um homem com vestiduras resplandecentes,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 31, 'e disse: Cornélio, a tua oração foi ouvida, e as tuas esmolas estão em memória diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 32, 'Envia, pois, a Jope e manda chamar a Simão, que tem por sobrenome Pedro; ele está hospedado em casa de Simão, curtidor, à beira-mar.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 33, 'Portanto mandei logo chamar-te, e bem fizeste em vir. Agora pois estamos todos aqui presentes diante de Deus, para ouvir tudo quanto te foi ordenado pelo Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 34, 'Então Pedro, tomando a palavra, disse: Na verdade reconheço que Deus não faz acepção de pessoas;', 1, CURRENT_TIMESTAMP, false),
(44, 10, 35, 'mas que lhe é aceitável aquele que, em qualquer nação, o teme e pratica o que é justo.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 36, 'A palavra que ele enviou aos filhos de Israel, anunciando a paz por Jesus Cristo {este é o Senhor de todos}.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 37, 'esta palavra, vós bem sabeis, foi proclamada por toda a Judéia, começando pela Galiléia, depois do batismo que João pregou,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 38, 'concernente a Jesus de Nazaré, como Deus o ungiu com o Espírito Santo e com poder; o qual andou por toda parte, fazendo o bem e curando a todos os oprimidos do Diabo, porque Deus era com ele.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 39, 'Nós somos testemunhas de tudo quanto fez, tanto na terra dos judeus como em Jerusalém; ao qual mataram, pendurando-o num madeiro.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 40, 'A este ressuscitou Deus ao terceiro dia e lhe concedeu que se manifestasse,', 1, CURRENT_TIMESTAMP, false),
(44, 10, 41, 'não a todo povo, mas às testemunhas que Deus antes ordenara; a nós, que comemos e bebemos juntamente com ele depois que ressurgiu dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 42, 'Este nos mandou pregar ao povo, e testificar que ele é o que por Deus foi constituído juiz dos vivos e dos mortos.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 43, 'A ele todos os profetas dão testemunho de que todo o que nele crê receberá a remissão dos pecados pelo seu nome.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 44, 'Enquanto Pedro ainda dizia estas coisas, desceu o Espírito Santo sobre todos os que ouviam a palavra.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 45, 'Os crentes que eram de circuncisão, todos quantos tinham vindo com Pedro, maravilharam-se de que também sobre os gentios se derramasse o dom do Espírito Santo;', 1, CURRENT_TIMESTAMP, false),
(44, 10, 46, 'porque os ouviam falar línguas e magnificar a Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 10, 47, 'Respondeu então Pedro: Pode alguém porventura recusar a água para que não sejam batizados estes que também, como nós, receberam o Espírito Santo?', 1, CURRENT_TIMESTAMP, false),
(44, 10, 48, 'Mandou, pois, que fossem batizados em nome de Jesus Cristo. Então lhe rogaram que ficasse com eles por alguns dias.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 1, 'Ora, ouviram os apóstolos e os irmãos que estavam na Judéia que também os gentios haviam recebido a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 2, 'E quando Pedro subiu a Jerusalém, disputavam com ele os que eram da circuncisão,', 1, CURRENT_TIMESTAMP, false),
(44, 11, 3, 'dizendo: Entraste em casa de homens incircuncisos e comeste com eles.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 4, 'Pedro, porém, começou a fazer-lhes uma exposição por ordem, dizendo:', 1, CURRENT_TIMESTAMP, false),
(44, 11, 5, 'Estava eu orando na cidade de Jope, e em êxtase tive uma visão; descia um objeto, como se fosse um grande lençol, sendo baixado do céu pelas quatro pontas, e chegou perto de mim.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 6, 'E, fitando nele os olhos, o contemplava, e vi quadrúpedes da terra, feras, répteis e aves do céu.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 7, 'Ouvi também uma voz que me dizia: Levanta-te, Pedro, mata e come.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 8, 'Mas eu respondi: De modo nenhum, Senhor, pois nunca em minha boca entrou coisa alguma comum e imunda.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 9, 'Mas a voz respondeu-me do céu segunda vez: Não chames tu comum ao que Deus purificou.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 10, 'Sucedeu isto por três vezes; e tudo tornou a recolher-se ao céu.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 11, 'E eis que, nesse momento, pararam em frente à casa onde estávamos três homens que me foram enviados de Cesaréia.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 12, 'Disse-me o Espírito que eu fosse com eles, sem hesitar; e também estes seis irmãos foram comigo e entramos na casa daquele homem.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 13, 'E ele nos contou como vira em pé em sua casa o anjo, que lhe dissera: Envia a Jope e manda chamar a Simão, que tem por sobrenome Pedro,', 1, CURRENT_TIMESTAMP, false),
(44, 11, 14, 'o qual te dirá palavras pelas quais serás salvo, tu e toda a tua casa.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 15, 'Logo que eu comecei a falar, desceu sobre eles o Espírito Santo, como também sobre nós no princípio.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 16, 'Lembrei-me então da palavra do Senhor, como disse: João, na verdade, batizou com água; mas vós sereis batizados no Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 17, 'Portanto, se Deus lhes deu o mesmo dom que dera também a nós, ao crermos no Senhor Jesus Cristo, quem era eu, para que pudesse resistir a Deus?', 1, CURRENT_TIMESTAMP, false),
(44, 11, 18, 'Ouvindo eles estas coisas, apaziguaram-se e glorificaram a Deus, dizendo: Assim, pois, Deus concedeu também aos gentios o arrependimento para a vida.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 19, 'Aqueles, pois, que foram dispersos pela tribulação suscitada por causa de Estêvão, passaram até a Fenícia, Chipre e Antioquia, não anunciando a ninguém a palavra, senão somente aos judeus.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 20, 'Havia, porém, entre eles alguns cíprios e cirenenses, os quais, entrando em Antioquia, falaram também aos gregos, anunciando o Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 21, 'E a mão do Senhor era com eles, e grande número creu e se converteu ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 22, 'Chegou a notícia destas coisas aos ouvidos da igreja em Jerusalém; e enviaram Barnabé a Antioquia;', 1, CURRENT_TIMESTAMP, false),
(44, 11, 23, 'o qual, quando chegou e viu a graça de Deus, se alegrou, e exortava a todos a perseverarem no Senhor com firmeza de coração;', 1, CURRENT_TIMESTAMP, false),
(44, 11, 24, 'porque era homem de bem, e cheio do Espírito Santo e de fé. E muita gente se uniu ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 25, 'Partiu, pois, Barnabé para Tarso, em busca de Saulo;', 1, CURRENT_TIMESTAMP, false),
(44, 11, 26, 'e tendo-o achado, o levou para Antioquia. E durante um ano inteiro reuniram-se naquela igreja e instruíram muita gente; e em Antioquia os discípulos pela primeira vez foram chamados cristãos.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 27, 'Naqueles dias desceram profetas de Jerusalém para Antioquia;', 1, CURRENT_TIMESTAMP, false),
(44, 11, 28, 'e levantando-se um deles, de nome Ágabo, dava a entender pelo Espírito, que haveria uma grande fome por todo o mundo, a qual ocorreu no tempo de Cláudio.', 1, CURRENT_TIMESTAMP, false),
(44, 11, 29, 'E os discípulos resolveram mandar, cada um conforme suas posses, socorro aos irmãos que habitavam na Judéia;', 1, CURRENT_TIMESTAMP, false),
(44, 11, 30, 'o que eles com efeito fizeram, enviando-o aos anciãos por mão de Barnabé e Saulo.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 1, 'Por aquele mesmo tempo o rei Herodes estendeu as mãos sobre alguns da igreja, para os maltratar;', 1, CURRENT_TIMESTAMP, false),
(44, 12, 2, 'e matou à espada Tiago, irmão de João.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 3, 'Vendo que isso agradava aos judeus, continuou, mandando prender também a Pedro. {Eram então os dias dos pães ázimos.}', 1, CURRENT_TIMESTAMP, false),
(44, 12, 4, 'E, havendo-o prendido, lançou-o na prisão, entregando-o a quatro grupos de quatro soldados cada um para o guardarem, tencionando apresentá-lo ao povo depois da páscoa.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 5, 'Pedro, pois, estava guardado na prisão; mas a igreja orava com insistência a Deus por ele.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 6, 'Ora quando Herodes estava para apresentá-lo, nessa mesma noite estava Pedro dormindo entre dois soldados, acorrentado com duas cadeias e as sentinelas diante da porta guardavam a prisão.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 7, 'E eis que sobreveio um anjo do Senhor, e uma luz resplandeceu na prisão; e ele, tocando no lado de Pedro, o despertou, dizendo: Levanta-te depressa. E caíram-lhe das mãos as cadeias.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 8, 'Disse-lhe ainda o anjo: Cinge-te e calça as tuas sandálias. E ele o fez. Disse-lhe mais; Cobre-te com a tua capa e segue-me.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 9, 'Pedro, saindo, o seguia, mesmo sem compreender que era real o que se fazia por intermédio de um anjo, julgando que era uma visão.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 10, 'Depois de terem passado a primeira e a segunda sentinela, chegaram à porta de ferro, que dá para a cidade, a qual se lhes abriu por si mesma; e tendo saído, passaram uma rua, e logo o anjo se apartou dele.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 11, 'Pedro então, tornando a si, disse: Agora sei verdadeiramente que o Senhor enviou o seu anjo, e me livrou da mão de Herodes e de toda a expectativa do povo dos judeus.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 12, 'Depois de assim refletir foi à casa de Maria, mãe de João, que tem por sobrenome Marcos, onde muitas pessoas estavam reunidas e oravam.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 13, 'Quando ele bateu ao portão do pátio, uma criada chamada Rode saiu a escutar;', 1, CURRENT_TIMESTAMP, false),
(44, 12, 14, 'e, reconhecendo a voz de Pedro, de gozo não abriu o portão, mas, correndo para dentro, anunciou que Pedro estava lá fora.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 15, 'Eles lhe disseram: Estás louca. Ela, porém, assegurava que assim era. Eles então diziam: É o seu anjo.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 16, 'Mas Pedro continuava a bater, e, quando abriram, viram-no e pasmaram.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 17, 'Mas ele, acenando-lhes com a mão para que se calassem, contou-lhes como o Senhor o tirara da prisão, e disse: Anunciai isto a Tiago e aos irmãos. E, saindo, partiu para outro lugar.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 18, 'Logo que amanheceu, houve grande alvoroço entre os soldados sobre o que teria sido feito de Pedro.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 19, 'E Herodes, tendo-o procurado e não o achando, inquiriu as sentinelas e mandou que fossem justiçadas; e descendo da Judéia para Cesaréia, demorou-se ali.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 20, 'Ora, Herodes estava muito irritado contra os de Tiro e de Sidom; mas estes, vindo de comum acordo ter com ele e obtendo a amizade de Blasto, camareiro do rei, pediam paz, porquanto o seu país se abastecia do país do rei.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 21, 'Num dia designado, Herodes, vestido de trajes reais, sentou-se no trono e dirigia-lhes a palavra.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 22, 'E o povo exclamava: É a voz de um deus, e não de um homem.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 23, 'No mesmo instante o anjo do Senhor o feriu, porque não deu glória a Deus; e, comido de vermes, expirou.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 24, 'E a palavra de Deus crescia e se multiplicava.', 1, CURRENT_TIMESTAMP, false),
(44, 12, 25, 'Barnabé e Saulo, havendo terminado aquele serviço, voltaram de Jerusalém, levando consigo a João, que tem por sobrenome Marcos.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 1, 'Ora, na igreja em Antioquia havia profetas e mestres, a saber: Barnabé, Simeão, chamado Níger, Lúcio de Cirene, Manaém, colaço de Herodes o tetrarca, e Saulo.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 2, 'Enquanto eles ministravam perante o Senhor e jejuavam, disse o Espírito Santo: Separai-me a Barnabé e a Saulo para a obra a que os tenho chamado.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 3, 'Então, depois que jejuaram, oraram e lhes impuseram as mãos, os despediram.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 4, 'Estes, pois, enviados pelo Espírito Santo, desceram a Selêucia e dali navegaram para Chipre.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 5, 'Chegados a Salamina, anunciavam a palavra de Deus nas sinagogas dos judeus, e tinham a João como auxiliar.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 6, 'Havendo atravessado a ilha toda até Pafos, acharam um certo mago, falso profeta, judeu, chamado Bar-Jesus,', 1, CURRENT_TIMESTAMP, false),
(44, 13, 7, 'que estava com o procônsul Sérgio Paulo, homem sensato. Este chamou a Barnabé e Saulo e mostrou desejo de ouvir a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 8, 'Mas resistia-lhes Elimas, o encantador {porque assim se interpreta o seu nome}, procurando desviar a fé do procônsul.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 9, 'Todavia Saulo, também chamado Paulo, cheio do Espírito Santo, fitando os olhos nele,', 1, CURRENT_TIMESTAMP, false),
(44, 13, 10, 'disse: ó filho do diabo, cheio de todo o engano e de toda a malícia, inimigo de toda a justiça, não cessarás de perverter os caminhos retos do Senhor?', 1, CURRENT_TIMESTAMP, false),
(44, 13, 11, 'Agora eis a mão do Senhor sobre ti, e ficarás cego, sem ver o sol por algum tempo. Imediatamente caiu sobre ele uma névoa e trevas e, andando à roda, procurava quem o guiasse pela mão.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 12, 'Então o procônsul, vendo o que havia acontecido, creu, maravilhando-se da doutrina do Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 13, 'Tendo Paulo e seus companheiros navegado de Pafos, chegaram a Perge, na Panfília. João, porém, apartando-se deles, voltou para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 14, 'Mas eles, passando de Perge, chegaram a Antioquia da Psídia; e entrando na sinagoga, no dia de sábado, sentaram-se.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 15, 'Depois da leitura da lei e dos profetas, os chefes da sinagoga mandaram dizer-lhes: Irmãos, se tendes alguma palavra de exortação ao povo, falai.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 16, 'Então Paulo se levantou e, pedindo silêncio com a mão, disse: Varões israelitas, e os que temeis a Deus, ouvi:', 1, CURRENT_TIMESTAMP, false),
(44, 13, 17, 'O Deus deste povo de Israel escolheu a nossos pais, e exaltou o povo, sendo eles estrangeiros na terra do Egito, de onde os tirou com braço poderoso,', 1, CURRENT_TIMESTAMP, false),
(44, 13, 18, 'e suportou-lhes os maus costumes no deserto por espaço de quase quarenta anos;', 1, CURRENT_TIMESTAMP, false),
(44, 13, 19, 'e, havendo destruído as sete nações na terra de Canaã, deu-lhes o território delas por herança durante cerca de quatrocentos e cinquenta anos.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 20, 'Depois disto, deu-lhes juízes até o profeta Samuel.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 21, 'Então pediram um rei, e Deus lhes deu por quarenta anos a Saul, filho de Cis, varão da tribo de Benjamim.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 22, 'E tendo deposto a este, levantou-lhes como rei a Davi, ao qual também, dando testemunho, disse: Achei a Davi, filho de Jessé, homem segundo o meu coração, que fará toda a minha vontade.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 23, 'Da descendência deste, conforme a promessa, trouxe Deus a Israel um Salvador, Jesus;', 1, CURRENT_TIMESTAMP, false),
(44, 13, 24, 'havendo João, antes do aparecimento dele, pregado a todo o povo de Israel o batismo de arrependimento.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 25, 'Mas João, quando completava a carreira, dizia: Quem pensais vós que eu sou? Eu não sou o Cristo, mas eis que após mim vem aquele a quem não sou digno de desatar as alparcas dos pés.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 26, 'Irmãos, filhos da estirpe de Abraão, e os que dentre vós temem a Deus, a nós é enviada a palavra desta salvação.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 27, 'Pois, os que habitam em Jerusalém e as suas autoridades, porquanto não conheceram a este Jesus, condenando-o, cumpriram as mesmas palavras dos profetas que se ouvem ler todos os sábados.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 28, 'E, se bem que não achassem nele nenhuma causa de morte, pediram a Pilatos que ele fosse morto.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 29, 'Quando haviam cumprido todas as coisas que dele estavam escritas, tirando-o do madeiro, o puseram na sepultura;', 1, CURRENT_TIMESTAMP, false),
(44, 13, 30, 'mas Deus o ressuscitou dentre os mortos;', 1, CURRENT_TIMESTAMP, false),
(44, 13, 31, 'e ele foi visto durante muitos dias por aqueles que com ele subiram da Galiléia a Jerusalém, os quais agora são suas testemunhas para com o povo.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 32, 'E nós vos anunciamos as boas novas da promessa, feita aos pais,', 1, CURRENT_TIMESTAMP, false),
(44, 13, 33, 'a qual Deus nos tem cumprido, a nós, filhos deles, levantando a Jesus, como também está escrito no salmo segundo: Tu és meu Filho, hoje te gerei.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 34, 'E no tocante a que o ressuscitou dentre os mortos para nunca mais tornar à corrupção, falou Deus assim: Dar-vos-ei as santas e fiéis bênçãos de Davi;', 1, CURRENT_TIMESTAMP, false),
(44, 13, 35, 'pelo que ainda em outro salmo diz: Não permitirás que o teu Santo veja a corrupção.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 36, 'Porque Davi, na verdade, havendo servido a sua própria geração pela vontade de Deus, dormiu e foi depositado junto a seus pais e experimentou corrupção.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 37, 'Mas aquele a quem Deus ressuscitou nenhuma corrupção experimentou.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 38, 'Seja-vos pois notório, varões, que por este se vos anuncia a remissão dos pecados.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 39, 'E de todas as coisas de que não pudestes ser justificados pela lei de Moisés, por ele é justificado todo o que crê.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 40, 'Cuidai pois que não venha sobre vós o que está dito nos profetas:', 1, CURRENT_TIMESTAMP, false),
(44, 13, 41, 'Vede, ó desprezadores, admirai-vos e desaparecei; porque realizo uma obra em vossos dias, obra em que de modo algum crereis, se alguém vo-la contar.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 42, 'Quando iam saindo, rogavam que estas palavras lhes fossem repetidas no sábado seguinte.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 43, 'E, despedida a sinagoga, muitos judeus e prosélitos devotos seguiram a Paulo e Barnabé, os quais, falando-lhes, os exortavam a perseverarem na graça de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 44, 'No sábado seguinte reuniu-se quase toda a cidade para ouvir a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 45, 'Mas os judeus, vendo as multidões, encheram-se de inveja e, blasfemando, contradiziam o que Paulo falava.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 46, 'Então Paulo e Barnabé, falando ousadamente, disseram: Era mister que a vós se pregasse em primeiro lugar a palavra de Deus; mas, visto que a rejeitais, e não vos julgais dignos da vida eterna, eis que nos viramos para os gentios;', 1, CURRENT_TIMESTAMP, false),
(44, 13, 47, 'porque assim nos ordenou o Senhor: Eu te pus para luz dos gentios, a fim de que sejas para salvação até os confins da terra.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 48, 'Os gentios, ouvindo isto, alegravam-se e glorificavam a palavra do Senhor; e creram todos quantos haviam sido destinados para a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 49, 'E divulgava-se a palavra do Senhor por toda aquela região.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 50, 'Mas os judeus incitaram as mulheres devotas de alta posição e os principais da cidade, suscitaram uma perseguição contra Paulo e Barnabé, e os lançaram fora dos seus termos.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 51, 'Mas estes, sacudindo contra eles o pó dos seus pés, partiram para Icônio.', 1, CURRENT_TIMESTAMP, false),
(44, 13, 52, 'Os discípulos, porém, estavam cheios de alegria e do Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 1, 'Em Icônio entraram juntos na sinagoga dos judeus e falaram de tal modo que creu uma grande multidão tanto de judeus como de gregos.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 2, 'Mas os judeus incrédulos excitaram e irritaram os ânimos dos gentios contra os irmãos.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 3, 'Eles, entretanto, se demoraram ali por muito tempo, falando ousadamente acerca do Senhor, o qual dava testemunho à palavra da sua graça, concedendo que por suas mãos se fizessem sinais e prodígios.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 4, 'E se dividiu o povo da cidade; uns eram pelos judeus, e outros pelos apóstolos.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 5, 'E, havendo um motim tanto dos gentios como dos judeus, juntamente com as suas autoridades, para os ultrajarem e apedrejarem,', 1, CURRENT_TIMESTAMP, false),
(44, 14, 6, 'eles, sabendo-o, fugiram para Listra e Derbe, cidades da Licaônia, e a região circunvizinha;', 1, CURRENT_TIMESTAMP, false),
(44, 14, 7, 'e ali pregavam o evangelho.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 8, 'Em Listra estava sentado um homem aleijado dos pés, coxo de nascença e que nunca tinha andado.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 9, 'Este ouvia falar Paulo, que, fitando nele os olhos e vendo que tinha fé para ser curado,', 1, CURRENT_TIMESTAMP, false),
(44, 14, 10, 'disse em alta voz: Levanta-te direito sobre os teus pés. E ele saltou, e andava.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 11, 'As multidões, vendo o que Paulo fizera, levantaram a voz, dizendo em língua licaônica: Fizeram-se os deuses semelhantes aos homens e desceram até nós.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 12, 'A Barnabé chamavam Júpiter e a Paulo, Mercúrio, porque era ele o que dirigia a palavra.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 13, 'O sacerdote de Júpiter, cujo templo estava em frente da cidade, trouxe para as portas touros e grinaldas e, juntamente com as multidões, queria oferecer-lhes sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 14, 'Quando, porém, os apóstolos Barnabé e Paulo ouviram isto, rasgaram as suas vestes e saltaram para o meio da multidão, clamando', 1, CURRENT_TIMESTAMP, false),
(44, 14, 15, 'e dizendo: Senhores, por que fazeis estas coisas? Nós também somos homens, de natureza semelhante à vossa, e vos anunciamos o evangelho para que destas práticas vãs vos convertais ao Deus vivo, que fez o céu, a terra, o mar, e tudo quanto há neles;', 1, CURRENT_TIMESTAMP, false),
(44, 14, 16, 'o qual nos tempos passados permitiu que todas as nações andassem nos seus próprios caminhos.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 17, 'Contudo não deixou de dar testemunho de si mesmo, fazendo o bem, dando-vos chuvas do céu e estações frutíferas, enchendo-vos de mantimento, e de alegria os vossos corações.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 18, 'E dizendo isto, com dificuldade impediram as multidões de lhes oferecerem sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 19, 'Sobrevieram, porém, judeus de Antioquia e de Icônio e, havendo persuadido as multidões, apedrejaram a Paulo, e arrastaram-no para fora da cidade, cuidando que estava morto.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 20, 'Mas quando os discípulos o rodearam, ele se levantou e entrou na cidade. No dia seguinte partiu com Barnabé para Derbe.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 21, 'E, tendo anunciado o evangelho naquela cidade e feito muitos discípulos, voltaram para Listra, Icônio e Antioquia,', 1, CURRENT_TIMESTAMP, false),
(44, 14, 22, 'confirmando as almas dos discípulos, exortando-os a perseverarem na fé, dizendo que por muitas tribulações nos é necessário entrar no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 23, 'E, havendo-lhes feito eleger anciãos em cada igreja e orado com jejuns, os encomendaram ao Senhor em quem haviam crido.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 24, 'Atravessando então a Pisídia, chegaram à Panfília.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 25, 'E, tendo anunciado a palavra em Perge, desceram a Atália.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 26, 'E dali navegaram para Antioquia, donde tinham sido encomendados à graça de Deus para a obra que acabavam de cumprir.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 27, 'Quando chegaram e reuniram a igreja, relataram tudo quanto Deus fizera por meio deles, e como abrira aos gentios a porta da fé.', 1, CURRENT_TIMESTAMP, false),
(44, 14, 28, 'E ficaram ali não pouco tempo, com os discípulos.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 1, 'Então alguns que tinham descido da Judéia ensinavam aos irmãos: Se não vos circuncidardes, segundo o rito de Moisés, não podeis ser salvos.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 2, 'Tendo Paulo e Barnabé contenda e não pequena discussão com eles, os irmãos resolveram que Paulo e Barnabé e mais alguns dentre eles subissem a Jerusalém, aos apóstolos e aos anciãos, por causa desta questão.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 3, 'Eles, pois, sendo acompanhados pela igreja por um trecho do caminho, passavam pela Fenícia e por Samária, contando a conversão dos gentios; e davam grande alegria a todos os irmãos.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 4, 'E, quando chegaram a Jerusalém, foram recebidos pela igreja e pelos apóstolos e anciãos, e relataram tudo quanto Deus fizera por meio deles.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 5, 'Mas alguns da seita dos fariseus, que tinham crido, levantaram-se dizendo que era necessário circuncidá-los e mandar-lhes observar a lei de Moisés.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 6, 'Congregaram-se pois os apóstolos e os anciãos para considerar este assunto.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 7, 'E, havendo grande discussão, levantou-se Pedro e disse-lhes: Irmãos, bem sabeis que já há muito tempo Deus me elegeu dentre vós, para que os gentios ouvissem da minha boca a palavra do evangelho e cressem.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 8, 'E Deus, que conhece os corações, testemunhou a favor deles, dando-lhes o Espírito Santo, assim como a nós;', 1, CURRENT_TIMESTAMP, false),
(44, 15, 9, 'e não fez distinção alguma entre eles e nós, purificando os seus corações pela fé.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 10, 'Agora, pois, por que tentais a Deus, pondo sobre a cerviz dos discípulos um jugo que nem nossos pais nem nós pudemos suportar?', 1, CURRENT_TIMESTAMP, false),
(44, 15, 11, 'Mas cremos que somos salvos pela graça do Senhor Jesus, do mesmo modo que eles também.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 12, 'Então toda a multidão se calou e escutava a Barnabé e a Paulo, que contavam quantos sinais e prodígios Deus havia feito por meio deles entre os gentios.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 13, 'Depois que se calaram, Tiago, tomando a palavra, disse: Irmãos, ouvi-me:', 1, CURRENT_TIMESTAMP, false),
(44, 15, 14, 'Simão relatou como primeiramente Deus visitou os gentios para tomar dentre eles um povo para o seu Nome.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 15, 'E com isto concordam as palavras dos profetas; como está escrito:', 1, CURRENT_TIMESTAMP, false),
(44, 15, 16, 'Depois disto voltarei, e reedificarei o tabernáculo de Davi, que está caído; reedificarei as suas ruínas, e tornarei a levantá-lo;', 1, CURRENT_TIMESTAMP, false),
(44, 15, 17, 'para que o resto dos homens busque ao Senhor, sim, todos os gentios, sobre os quais é invocado o meu nome,', 1, CURRENT_TIMESTAMP, false),
(44, 15, 18, 'diz o Senhor que faz estas coisas, que são conhecidas desde a antiguidade.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 19, 'Por isso, julgo que não se deve perturbar aqueles, dentre os gentios, que se convertem a Deus,', 1, CURRENT_TIMESTAMP, false),
(44, 15, 20, 'mas escrever-lhes que se abstenham das contaminações dos ídolos, da prostituição, do que é sufocado e do sangue.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 21, 'Porque Moisés, desde tempos antigos, tem em cada cidade homens que o preguem, e cada sábado é lido nas sinagogas.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 22, 'Então pareceu bem aos apóstolos e aos anciãos com toda a igreja escolher homens dentre eles e enviá-los a Antioquia com Paulo e Barnabé, a saber: Judas, chamado Barsabás, e Silas, homens influentes entre os irmãos.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 23, 'E por intermédio deles escreveram o seguinte: Os apóstolos e os anciãos, irmãos, aos irmãos dentre os gentios em Antioquia, na Síria e na Cicília, saúde.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 24, 'Portanto ouvimos que alguns dentre nós, aos quais nada mandamos, vos têm perturbado com palavras, confundindo as vossas almas,', 1, CURRENT_TIMESTAMP, false),
(44, 15, 25, 'pareceu-nos bem, tendo chegado a um acordo, escolher alguns homens e enviá-los com os nossos amados Barnabé e Paulo,', 1, CURRENT_TIMESTAMP, false),
(44, 15, 26, 'homens que têm exposto as suas vidas pelo nome de nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 27, 'Enviamos portanto Judas e Silas, os quais também por palavra vos anunciarão as mesmas coisas.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 28, 'Porque pareceu bem ao Espírito Santo e a nós não vos impor maior encargo além destas coisas necessárias:', 1, CURRENT_TIMESTAMP, false),
(44, 15, 29, 'Que vos abstenhais das coisas sacrificadas aos ídolos, e do sangue, e da carne sufocada, e da prostituição; e destas coisas fareis bem de vos guardar. Bem vos vá.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 30, 'Então eles, tendo-se despedido, desceram a Antioquia e, havendo reunido a assembléia, entregaram a carta.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 31, 'E, quando a leram, alegraram-se pela consolação.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 32, 'Depois Judas e Silas, que também eram profetas, exortaram os irmãos com muitas palavras e os fortaleceram.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 33, 'E, tendo-se demorado ali por algum tempo, foram pelos irmãos despedidos em paz, de volta aos que os haviam mandado.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 34, '{Mas pareceu bem a Silas ficar ali.}', 1, CURRENT_TIMESTAMP, false),
(44, 15, 35, 'Mas Paulo e Barnabé demoraram-se em Antioquia, ensinando e pregando com muitos outros a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 36, 'Decorridos alguns dias, disse Paulo a Barnabé: Tornemos a visitar os irmãos por todas as cidades em que temos anunciado a palavra do Senhor, para ver como vão.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 37, 'Ora, Barnabé queria que levassem também a João, chamado Marcos.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 38, 'Mas a Paulo não parecia razoável que tomassem consigo aquele que desde a Panfília se tinha apartado deles e não os tinha acompanhado no trabalho.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 39, 'E houve entre eles tal desavença que se separaram um do outro, e Barnabé, levando consigo a Marcos, navegou para Chipre.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 40, 'Mas Paulo, tendo escolhido a Silas, partiu encomendado pelos irmãos à graça do Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 15, 41, 'E passou pela Síria e Cilícia, fortalecendo as igrejas.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 1, 'Chegou também a Derbe e Listra. E eis que estava ali certo discípulo por nome Timóteo, filho de uma judia crente, mas de pai grego;', 1, CURRENT_TIMESTAMP, false),
(44, 16, 2, 'do qual davam bom testemunho os irmãos em Listra e Icônio.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 3, 'Paulo quis que este fosse com ele e, tomando-o, o circuncidou por causa dos judeus que estavam naqueles lugares; porque todos sabiam que seu pai era grego.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 4, 'Quando iam passando pelas cidades, entregavam aos irmãos, para serem observadas, as decisões que haviam sido tomadas pelos apóstolos e anciãos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 5, 'Assim as igrejas eram confirmadas na fé, e dia a dia cresciam em número.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 6, 'Atravessaram a região frígio-gálata, tendo sido impedidos pelo Espírito Santo de anunciar a palavra na Ásia;', 1, CURRENT_TIMESTAMP, false),
(44, 16, 7, 'e tendo chegado diante da Mísia, tentavam ir para Bitínia, mas o Espírito de Jesus não lho permitiu.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 8, 'Então, passando pela Mísia, desceram a Trôade.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 9, 'De noite apareceu a Paulo esta visão: estava ali em pé um homem da Macedônia, que lhe rogava: Passa à Macedônia e ajuda-nos.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 10, 'E quando ele teve esta visão, procurávamos logo partir para a Macedônia, concluindo que Deus nos havia chamado para lhes anunciarmos o evangelho.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 11, 'Navegando, pois, de Trôade, fomos em direitura a Samotrácia, e no dia seguinte a Neápolis;', 1, CURRENT_TIMESTAMP, false),
(44, 16, 12, 'e dali para Filipos, que é a primeira cidade desse distrito da Macedônia, e colônia romana; e estivemos alguns dias nessa cidade.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 13, 'No sábado saímos portas afora para a beira do rio, onde julgávamos haver um lugar de oração e, sentados, falávamos às mulheres ali reunidas.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 14, 'E certa mulher chamada Lídia, vendedora de púrpura, da cidade de Tiatira, e que temia a Deus, nos escutava e o Senhor lhe abriu o coração para atender às coisas que Paulo dizia.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 15, 'Depois que foi batizada, ela e a sua casa, rogou-nos, dizendo: Se haveis julgado que eu sou fiel ao Senhor, entrai em minha casa, e ficai ali. E nos constrangeu a isso.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 16, 'Ora, aconteceu que quando íamos ao lugar de oração, nos veio ao encontro uma jovem que tinha um espírito adivinhador, e que, adivinhando, dava grande lucro a seus senhores.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 17, 'Ela, seguindo a Paulo e a nós, clamava, dizendo: São servos do Deus Altíssimo estes homens que vos anunciam um caminho de salvação.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 18, 'E fazia isto por muitos dias. Mas Paulo, perturbado, voltou-se e disse ao espírito: Eu te ordeno em nome de Jesus Cristo que saias dela. E na mesma hora saiu.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 19, 'Ora, vendo seus senhores que a esperança do seu lucro havia desaparecido, prenderam a Paulo e Silas, e os arrastaram para uma praça à presença dos magistrados.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 20, 'E, apresentando-os aos magistrados, disseram: Estes homens, sendo judeus, estão perturbando muito a nossa cidade,', 1, CURRENT_TIMESTAMP, false),
(44, 16, 21, 'e pregam costumes que não nos é lícito receber nem praticar, sendo nós romanos.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 22, 'A multidão levantou-se à uma contra eles, e os magistrados, rasgando-lhes os vestidos, mandaram açoitá-los com varas.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 23, 'E, havendo-lhes dado muitos açoites, os lançaram na prisão, mandando ao carcereiro que os guardasse com segurança.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 24, 'Ele, tendo recebido tal ordem, os lançou na prisão interior e lhes segurou os pés no tronco.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 25, 'Pela meia-noite Paulo e Silas oravam e cantavam hinos a Deus, enquanto os presos os escutavam.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 26, 'De repente houve um tão grande terremoto que foram abalados os alicerces do cárcere, e logo se abriram todas as portas e foram soltos os grilhões de todos.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 27, 'Ora, o carcereiro, tendo acordado e vendo abertas as portas da prisão, tirou a espada e ia suicidar-se, supondo que os presos tivessem fugido.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 28, 'Mas Paulo bradou em alta voz, dizendo: Não te faças nenhum mal, porque todos aqui estamos.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 29, 'Tendo ele pedido luz, saltou dentro e, todo trêmulo, se prostrou ante Paulo e Silas', 1, CURRENT_TIMESTAMP, false),
(44, 16, 30, 'e, tirando-os para fora, disse: Senhores, que me é necessário fazer para me salvar?', 1, CURRENT_TIMESTAMP, false),
(44, 16, 31, 'Responderam eles: Crê no Senhor Jesus e serás salvo, tu e tua casa.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 32, 'Então lhe pregaram a palavra de Deus, e a todos os que estavam em sua casa.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 33, 'Tomando-os ele consigo naquela mesma hora da noite, lavou-lhes as feridas; e logo foi batizado, ele e todos os seus.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 34, 'Então os fez subir para sua casa, pôs-lhes a mesa e alegrou-se muito com toda a sua casa, por ter crido em Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 35, 'Quando amanheceu, os magistrados mandaram quadrilheiros a dizer: Soltai aqueles homens.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 36, 'E o carcereiro transmitiu a Paulo estas palavras, dizendo: Os magistrados mandaram que fosseis soltos; agora, pois, saí e ide em paz.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 37, 'Mas Paulo respondeu-lhes: Açoitaram-nos publicamente sem sermos condenados, sendo cidadãos romanos, e nos lançaram na prisão, e agora encobertamente nos lançam fora? De modo nenhum será assim; mas venham eles mesmos e nos tirem.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 38, 'E os quadrilheiros foram dizer aos magistrados estas palavras, e estes temeram quando ouviram que eles eram romanos;', 1, CURRENT_TIMESTAMP, false),
(44, 16, 39, 'vieram, pediram-lhes desculpas e, tirando-os para fora, rogavam que se retirassem da cidade.', 1, CURRENT_TIMESTAMP, false),
(44, 16, 40, 'Então eles saíram da prisão, entraram em casa de Lídia, e, vendo os irmãos, os confortaram, e partiram.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 1, 'Tendo passado por Anfípolis e Apolônia, chegaram a Tessalônica, onde havia uma sinagoga dos judeus.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 2, 'Ora, Paulo, segundo o seu costume, foi ter com eles; e por três sábados discutiu com eles as Escrituras,', 1, CURRENT_TIMESTAMP, false),
(44, 17, 3, 'expondo e demonstrando que era necessário que o Cristo padecesse e ressuscitasse dentre os mortos; este Jesus que eu vos anuncio, dizia ele, é o Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 4, 'E alguns deles ficaram persuadidos e aderiram a Paulo e Silas, bem como grande multidão de gregos devotos e não poucas mulheres de posição.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 5, 'Mas os judeus, movidos de inveja, tomando consigo alguns homens maus dentre os vadios e ajuntando o povo, alvoroçavam a cidade e, assaltando a casa de Jáson, os procuravam para entregá-los ao povo.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 6, 'Porém, não os achando, arrastaram Jáson e alguns irmãos à presença dos magistrados da cidade, clamando: Estes que têm transtornado o mundo chegaram também aqui,', 1, CURRENT_TIMESTAMP, false),
(44, 17, 7, 'os quais Jáson acolheu; e todos eles procedem contra os decretos de César, dizendo haver outro rei, que é Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 8, 'Assim alvoroçaram a multidão e os magistrados da cidade, que ouviram estas coisas.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 9, 'Tendo, porém, recebido fiança de Jáson e dos demais, soltaram-nos.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 10, 'E logo, de noite, os irmãos enviaram Paulo e Silas para Beréia; tendo eles ali chegado, foram à sinagoga dos judeus.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 11, 'Ora, estes eram mais nobres do que os de Tessalônica, porque receberam a palavra com toda avidez, examinando diariamente as Escrituras para ver se estas coisas eram assim.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 12, 'De sorte que muitos deles creram, bem como bom número de mulheres gregas de alta posição e não poucos homens.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 13, 'Mas, logo que os judeus de Tessalônica souberam que também em Beréia era anunciada por Paulo a palavra de Deus, foram lá agitar e sublevar as multidões.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 14, 'Imediatamente os irmãos fizeram sair a Paulo para que fosse até o mar; mas Silas e Timóteo ficaram ali.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 15, 'E os que acompanhavam a Paulo levaram-no até Atenas e, tendo recebido ordem para Silas e Timóteo a fim de que estes fossem ter com ele o mais depressa possível, partiram.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 16, 'Enquanto Paulo os esperava em Atenas, revoltava-se nele o seu espírito, vendo a cidade cheia de ídolos.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 17, 'Argumentava, portanto, na sinagoga com os judeus e os gregos devotos, e na praça todos os dias com os que se encontravam ali.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 18, 'Ora, alguns filósofos epicureus e estóicos disputavam com ele. Uns diziam: Que quer dizer este paroleiro? E outros: Parece ser pregador de deuses estranhos; pois anunciava a boa nova de Jesus e a ressurreição.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 19, 'E, tomando-o, o levaram ao Areópago, dizendo: Poderemos nós saber que nova doutrina é essa de que falas?', 1, CURRENT_TIMESTAMP, false),
(44, 17, 20, 'Pois tu nos trazes aos ouvidos coisas estranhas; portanto queremos saber o que vem a ser isto.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 21, 'Ora, todos os atenienses, como também os estrangeiros que ali residiam, de nenhuma outra coisa se ocupavam senão de contar ou de ouvir a última novidade.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 22, 'Então Paulo, estando de pé no meio do Areópago, disse: Varões atenienses, em tudo vejo que sois excepcionalmente religiosos;', 1, CURRENT_TIMESTAMP, false),
(44, 17, 23, 'porque, passando eu e observando os objetos do vosso culto, encontrei também um altar em que estava escrito: AO DEUS DESCONHECIDO. Esse, pois, que vós honrais sem o conhecer, é o que vos anuncio.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 24, 'O Deus que fez o mundo e tudo o que nele há, sendo ele Senhor do céu e da terra, não habita em templos feitos por mãos de homens;', 1, CURRENT_TIMESTAMP, false),
(44, 17, 25, 'nem tampouco é servido por mãos humanas, como se necessitasse de alguma coisa; pois ele mesmo é quem dá a todos a vida, a respiração e todas as coisas;', 1, CURRENT_TIMESTAMP, false),
(44, 17, 26, 'e de um só fez todas as raças dos homens, para habitarem sobre toda a face da terra, determinando-lhes os tempos já dantes ordenados e os limites da sua habitação;', 1, CURRENT_TIMESTAMP, false),
(44, 17, 27, 'para que buscassem a Deus, se porventura, tateando, o pudessem achar, o qual, todavia, não está longe de cada um de nós;', 1, CURRENT_TIMESTAMP, false),
(44, 17, 28, 'porque nele vivemos, e nos movemos, e existimos; como também alguns dos vossos poetas disseram: Pois dele também somos geração.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 29, 'Sendo nós, pois, geração de Deus, não devemos pensar que a divindade seja semelhante ao ouro, ou à prata, ou à pedra esculpida pela arte e imaginação do homem.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 30, 'Mas Deus, não levando em conta os tempos da ignorância, manda agora que todos os homens em todo lugar se arrependam;', 1, CURRENT_TIMESTAMP, false),
(44, 17, 31, 'porquanto determinou um dia em que com justiça há de julgar o mundo, por meio do varão que para isso ordenou; e disso tem dado certeza a todos, ressuscitando-o dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 32, 'Mas quando ouviram falar em ressurreição de mortos, uns escarneciam, e outros diziam: Acerca disso te ouviremos ainda outra vez.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 33, 'Assim Paulo saiu do meio deles.', 1, CURRENT_TIMESTAMP, false),
(44, 17, 34, 'Todavia, alguns homens aderiram a ele, e creram, entre os quais Dionísio, o areopagita, e uma mulher por nome Dâmaris, e com eles outros.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 1, 'Depois disto Paulo partiu de Atenas e chegou a Corinto.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 2, 'E encontrando um judeu por nome Áqüila, natural do Ponto, que pouco antes viera da Itália, e Priscila, sua mulher {porque Cláudio tinha decretado que todos os judeus saíssem de Roma}, foi ter com eles,', 1, CURRENT_TIMESTAMP, false),
(44, 18, 3, 'e, por ser do mesmo ofício, com eles morava, e juntos trabalhavam; pois eram, por ofício, fabricantes de tendas.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 4, 'Ele discutia todos os sábados na sinagoga, e persuadia a judeus e gregos.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 5, 'Quando Silas e Timóteo desceram da Macedônia, Paulo dedicou-se inteiramente à palavra, testificando aos judeus que Jesus era o Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 6, 'Como estes, porém, se opusessem e proferissem injúrias, sacudiu ele as vestes e disse-lhes: O vosso sangue seja sobre a vossa cabeça; eu estou limpo, e desde agora vou para os gentios.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 7, 'E saindo dali, entrou em casa de um homem temente a Deus, chamado Tito Justo, cuja casa ficava junto da sinagoga.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 8, 'Crispo, chefe da sinagoga, creu no Senhor com toda a sua casa; e muitos dos coríntios, ouvindo, criam e eram batizados.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 9, 'E de noite disse o Senhor em visão a Paulo: Não temas, mas fala e não te cales;', 1, CURRENT_TIMESTAMP, false),
(44, 18, 10, 'porque eu estou contigo e ninguém te acometerá para te fazer mal, pois tenho muito povo nesta cidade.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 11, 'E ficou ali um ano e seis meses, ensinando entre eles a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 12, 'Sendo Gálio procônsul da Acaia, levantaram-se os judeus de comum acordo contra Paulo, e o levaram ao tribunal,', 1, CURRENT_TIMESTAMP, false),
(44, 18, 13, 'dizendo: Este persuade os homens a render culto a Deus de um modo contrário à lei.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 14, 'E, quando Paulo estava para abrir a boca, disse Gálio aos judeus: Se de fato houvesse, ó judeus, algum agravo ou crime perverso, com razão eu vos sofreria;', 1, CURRENT_TIMESTAMP, false),
(44, 18, 15, 'mas, se são questões de palavras, de nomes, e da vossa lei, disso cuidai vós mesmos; porque eu não quero ser juiz destas coisas.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 16, 'E expulsou-os do tribunal.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 17, 'Então todos agarraram Sóstenes, chefe da sinagoga, e o espancavam diante do tribunal; e Gálio não se importava com nenhuma dessas coisas.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 18, 'Paulo, tendo ficado ali ainda muitos dias, despediu-se dos irmãos e navegou para a Síria, e com ele Priscila e Áqüila, havendo rapado a cabeça em Cencréia, porque tinha voto.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 19, 'E eles chegaram a Éfeso, onde Paulo os deixou; e tendo entrado na sinagoga, discutia com os judeus.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 20, 'Estes rogavam que ficasse por mais algum tempo, mas ele não anuiu,', 1, CURRENT_TIMESTAMP, false),
(44, 18, 21, 'antes se despediu deles, dizendo: Se Deus quiser, de novo voltarei a vós; e navegou de Éfeso.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 22, 'Tendo chegado a Cesaréia, subiu a Jerusalém e saudou a igreja, e desceu a Antioquia.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 23, 'E, tendo demorado ali algum tempo, partiu, passando sucessivamente pela região da Galácia e da Frígia, fortalecendo a todos os discípulos.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 24, 'Ora, chegou a Éfeso certo judeu chamado Apolo, natural de Alexandria, homem eloqüente e poderoso nas Escrituras.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 25, 'Era ele instruído no caminho do Senhor e, sendo fervoroso de espírito, falava e ensinava com precisão as coisas concernentes a Jesus, conhecendo entretanto somente o batismo de João.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 26, 'Ele começou a falar ousadamente na sinagoga: mas quando Priscila e Áqüila o ouviram, levaram-no consigo e lhe expuseram com mais precisão o caminho de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 27, 'Querendo ele passar à Acáia, os irmãos o animaram e escreveram aos discípulos que o recebessem; e tendo ele chegado, auxiliou muito aos que pela graça haviam crido.', 1, CURRENT_TIMESTAMP, false),
(44, 18, 28, 'Pois com grande poder refutava publicamente os judeus, demonstrando pelas escrituras que Jesus era o Cristo.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 1, 'E sucedeu que, enquanto Apolo estava em Corinto, Paulo tendo atravessado as regiões mais altas, chegou a Éfeso e, achando ali alguns discípulos,', 1, CURRENT_TIMESTAMP, false),
(44, 19, 2, 'perguntou-lhes: Recebestes vós o Espírito Santo quando crestes? Responderam-lhe eles: Não, nem sequer ouvimos que haja Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 3, 'Tornou-lhes ele: Em que fostes batizados então? E eles disseram: No batismo de João.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 4, 'Mas Paulo respondeu: João administrou o batismo do arrependimento, dizendo ao povo que cresse naquele que após ele havia de vir, isto é, em Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 5, 'Quando ouviram isso, foram batizados em nome do Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 6, 'Havendo-lhes Paulo imposto as mãos, veio sobre eles o Espírito Santo, e falavam em línguas e profetizavam.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 7, 'E eram ao todo uns doze homens.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 8, 'Paulo, entrando na sinagoga, falou ousadamente por espaço de três meses, discutindo e persuadindo acerca do reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 9, 'Mas, como alguns deles se endurecessem e não obedecessem, falando mal do Caminho diante da multidão, apartou-se deles e separou os discípulos, discutindo diariamente na escola de Tirano.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 10, 'Durou isto por dois anos; de maneira que todos os que habitavam na Ásia, tanto judeus como gregos, ouviram a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 11, 'E Deus pelas mãos de Paulo fazia milagres extraordinários,', 1, CURRENT_TIMESTAMP, false),
(44, 19, 12, 'de sorte que lenços e aventais eram levados do seu corpo aos enfermos, e as doenças os deixavam e saíam deles os espíritos malignos.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 13, 'Ora, também alguns dos exorcistas judeus, ambulantes, tentavam invocar o nome de Jesus sobre os que tinham espíritos malignos, dizendo: Esconjuro-vos por Jesus a quem Paulo prega.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 14, 'E os que faziam isto eram sete filhos de Ceva, judeu, um dos principais sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 15, 'Respondendo, porém, o espírito maligno, disse: A Jesus conheço, e sei quem é Paulo; mas vós, quem sois?', 1, CURRENT_TIMESTAMP, false),
(44, 19, 16, 'Então o homem, no qual estava o espírito maligno, saltando sobre eles, apoderou-se de dois e prevaleceu contra eles, de modo que, nus e feridos, fugiram daquela casa.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 17, 'E isto tornou-se conhecido de todos os que moravam em Éfeso, tanto judeus como gregos; e veio temor sobre todos eles, e o nome do Senhor Jesus era engrandecido.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 18, 'E muitos dos que haviam crido vinham, confessando e revelando os seus feitos.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 19, 'Muitos também dos que tinham praticado artes mágicas ajuntaram os seus livros e os queimaram na presença de todos; e, calculando o valor deles, acharam que montava a cinqüenta mil moedas de prata.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 20, 'Assim a palavra do Senhor crescia poderosamente e prevalecia.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 21, 'Cumpridas estas coisas, Paulo propôs, em seu espírito, ir a Jerusalém, passando pela Macedônia e pela Acaia, porque dizia: Depois de haver estado ali, é-me necessário ver também Roma.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 22, 'E, enviando à Macedônia dois dos que o auxiliavam, Timóteo e Erasto, ficou ele por algum tempo na Ásia.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 23, 'Por esse tempo houve um não pequeno alvoroço acerca do Caminho.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 24, 'Porque certo ourives, por nome Demétrio, que fazia da prata miniaturas do templo de Diana, proporcionava não pequeno negócio aos artífices,', 1, CURRENT_TIMESTAMP, false),
(44, 19, 25, 'os quais ele ajuntou, bem como os oficiais de obras semelhantes, e disse: Senhores, vós bem sabeis que desta indústria nos vem a prosperidade,', 1, CURRENT_TIMESTAMP, false),
(44, 19, 26, 'e estais vendo e ouvindo que não é só em Éfeso, mas em quase toda a Ásia, este Paulo tem persuadido e desviado muita gente, dizendo não serem deuses os que são feitos por mãos humanas.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 27, 'E não somente há perigo de que esta nossa profissão caia em descrédito, mas também que o templo da grande deusa Diana seja estimado em nada, vindo mesmo a ser destituída da sua majestade aquela a quem toda a Ásia e o mundo adoram.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 28, 'Ao ouvirem isso, encheram-se de ira, e clamavam, dizendo: Grande é a Diana dos efésios!', 1, CURRENT_TIMESTAMP, false),
(44, 19, 29, 'A cidade encheu-se de confusão, e todos à uma correram ao teatro, arrebatando a Gaio e a Aristarco, macedônios, companheiros de Paulo na viagem.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 30, 'Querendo Paulo apresentar-se ao povo, os discípulos não lho permitiram.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 31, 'Também alguns dos asiarcas, sendo amigos dele, mandaram rogar-lhe que não se arriscasse a ir ao teatro.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 32, 'Uns, pois, gritavam de um modo, outros de outro; porque a assembléia estava em confusão, e a maior parte deles nem sabia por que causa se tinham ajuntado.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 33, 'Então tiraram dentre a turba a Alexandre, a quem os judeus impeliram para a frente; e Alexandre, acenando com a mão, queria apresentar uma defesa ao povo.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 34, 'Mas quando perceberam que ele era judeu, todos a uma voz gritaram por quase duas horas: Grande é a Diana dos efésios!', 1, CURRENT_TIMESTAMP, false),
(44, 19, 35, 'Havendo o escrivão conseguido apaziguar a turba, disse: Varões efésios, que homem há que não saiba que a cidade dos efésios é a guardadora do templo da grande deusa Diana, e da imagem que caiu de Júpiter?', 1, CURRENT_TIMESTAMP, false),
(44, 19, 36, 'Ora, visto que estas coisas não podem ser contestadas, convém que vos aquieteis e nada façais precipitadamente.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 37, 'Porque estes homens que aqui trouxestes, nem são sacrílegos nem blasfemadores da nossa deusa.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 38, 'Todavia, se Demétrio e os artífices que estão com ele têm alguma queixa contra alguém, os tribunais estão abertos e há procônsules: que se acusem uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 39, 'E se demandais alguma outra coisa, averiguar-se-á em legítima assembléia.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 40, 'Pois até corremos perigo de sermos acusados de sedição pelos acontecimentos de hoje, não havendo motivo algum com que possamos justificar este ajuntamento.', 1, CURRENT_TIMESTAMP, false),
(44, 19, 41, 'E, tendo dito isto, despediu a assembléia.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 1, 'Depois que cessou o alvoroço, Paulo mandou chamar os discípulos e, tendo-os exortado, despediu-se e partiu para a Macedônia.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 2, 'E, havendo andado por aquelas regiões, exortando os discípulos com muitas palavras, veio à Grécia.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 3, 'Depois de passar ali três meses, visto terem os judeus armado uma cilada contra ele quando ia embarcar para a Síria, determinou voltar pela Macedônia.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 4, 'Acompanhou-o Sópater de Beréia, filho de Pirro; bem como dos de Tessalônica, Aristarco e Segundo; Gaio de Derbe e Timóteo; e dos da Ásia, Tíquico e Trófimo.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 5, 'Estes porém, foram adiante e nos esperavam em Trôade.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 6, 'E nós, depois dos dias dos pães ázimos, navegamos de Filipos, e em cinco dias fomos ter com eles em Trôade, onde nos detivemos sete dias.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 7, 'No primeiro dia da semana, tendo-nos reunido a fim de partir o pão, Paulo, que havia de sair no dia seguinte, falava com eles, e prolongou o seu discurso até a meia-noite.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 8, 'Ora, havia muitas luzes no cenáculo onde estávamos reunidos.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 9, 'E certo jovem, por nome Êutico, que estava sentado na janela, tomado de um sono profundo enquanto Paulo prolongava ainda mais o seu sermão, vencido pelo sono caiu do terceiro andar abaixo, e foi levantado morto.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 10, 'Tendo Paulo descido, debruçou-se sobre ele e, abraçando-o, disse: Não vos perturbeis, pois a sua alma está nele.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 11, 'Então subiu, e tendo partido o pão e comido, ainda lhes falou largamente até o romper do dia; e assim partiu.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 12, 'E levaram vivo o jovem e ficaram muito consolados.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 13, 'Nós, porém, tomando a dianteira e embarcando, navegamos para Assôs, onde devíamos receber a Paulo, porque ele, havendo de ir por terra, assim o ordenara.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 14, 'E, logo que nos alcançou em Assôs, recebemo-lo a bordo e fomos a Mitilene;', 1, CURRENT_TIMESTAMP, false),
(44, 20, 15, 'e navegando dali, chegamos no dia imediato defronte de Quios, no outro aportamos a Samos e {e tendo-nos demorado em Trogílio, chegamos,} no dia seguinte a Mileto.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 16, 'Porque Paulo havia determinado passar ao largo de Éfeso, para não se demorar na Ásia; pois se apressava para estar em Jerusalém no dia de Pentecostes, se lhe fosse possível.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 17, 'De Mileto mandou a Éfeso chamar os anciãos da igreja.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 18, 'E, tendo eles chegado, disse-lhes: Vós bem sabeis de que modo me tenho portado entre vós sempre, desde o primeiro dia em que entrei na Ásia,', 1, CURRENT_TIMESTAMP, false),
(44, 20, 19, 'servindo ao Senhor com toda a humildade, e com lágrimas e provações que pelas ciladas dos judeus me sobrevieram;', 1, CURRENT_TIMESTAMP, false),
(44, 20, 20, 'como não me esquivei de vos anunciar coisa alguma que útil seja, ensinando-vos publicamente e de casa em casa,', 1, CURRENT_TIMESTAMP, false),
(44, 20, 21, 'testificando, tanto a judeus como a gregos, o arrependimento para com Deus e a fé em nosso Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 22, 'Agora, eis que eu, constrangido no meu espírito, vou a Jerusalém, não sabendo o que ali acontecerá,', 1, CURRENT_TIMESTAMP, false),
(44, 20, 23, 'senão o que o Espírito Santo me testifica, de cidade em cidade, dizendo que me esperam prisões e tribulações,', 1, CURRENT_TIMESTAMP, false),
(44, 20, 24, 'mas em nada tenho a minha vida como preciosa para mim, contando que complete a minha carreira e o ministério que recebi do Senhor Jesus, para dar testemunho do evangelho da graça de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 25, 'E eis agora, sei que nenhum de vós, por entre os quais passei pregando o reino de Deus, jamais tornará a ver o meu rosto.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 26, 'Portanto, no dia de hoje, vos protesto que estou limpo do sangue de todos.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 27, 'Porque não me esquivei de vos anunciar todo o conselho de Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 28, 'Cuidai pois de vós mesmos e de todo o rebanho sobre o qual o Espírito Santo vos constituiu bispos, para apascentardes a igreja de Deus, que ele adquiriu com seu próprio sangue.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 29, 'Eu sei que depois da minha partida entrarão no meio de vós lobos cruéis que não pouparão rebanho,', 1, CURRENT_TIMESTAMP, false),
(44, 20, 30, 'e que dentre vós mesmos se levantarão homens, falando coisas perversas para atrair os discípulos após si.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 31, 'Portanto vigiai, lembrando-vos de que por três anos não cessei noite e dia de admoestar com lágrimas a cada um de vós.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 32, 'Agora pois, vos encomendo a Deus e à palavra da sua graça, àquele que é poderoso para vos edificar e dar herança entre todos os que são santificados.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 33, 'De ninguém cobicei prata, nem ouro, nem vestes.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 34, 'Vós mesmos sabeis que estas mãos proveram as minhas necessidades e as dos que estavam comigo.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 35, 'Em tudo vos dei o exemplo de que assim trabalhando, é necessário socorrer os enfermos, recordando as palavras do Senhor Jesus, porquanto ele mesmo disse: Coisa mais bem-aventurada é dar do que receber.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 36, 'Havendo dito isto, pôs-se de joelhos, e orou com todos eles.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 37, 'E levantou-se um grande pranto entre todos, e lançando-se ao pescoço de Paulo, beijavam-no.', 1, CURRENT_TIMESTAMP, false),
(44, 20, 38, 'Entristecendo-se principalmente pela palavra que dissera, que não veriam mais o seu rosto. E eles o acompanharam até o navio.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 1, 'E assim aconteceu que, separando-nos deles, navegamos e, correndo em direitura, chegamos a Cós, e no dia seguinte a Rodes, e dali a Pátara.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 2, 'Achando um navio que seguia para a Fenícia, embarcamos e partimos.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 3, 'E quando avistamos Chipre, deixando-a á esquerda, navegamos para a Síria e chegamos a Tiro, pois o navio havia de ser descarregado ali.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 4, 'Havendo achado os discípulos, demoramo-nos ali sete dias; e eles pelo Espírito diziam a Paulo que não subisse a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 5, 'Depois de passarmos ali aqueles dias, saímos e seguimos a nossa viagem, acompanhando-nos todos, com suas mulheres e filhos, até fora da cidade; e, postos de joelhos na praia, oramos,', 1, CURRENT_TIMESTAMP, false),
(44, 21, 6, 'e despedindo-nos uns dos outros, embarcamos, e eles voltaram para casa.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 7, 'Concluída a nossa viagem de Tiro, chegamos a Ptolemaida; e, havendo saudado os irmãos, passamos um dia com eles.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 8, 'Partindo no dia seguinte, fomos a Cesaréia; e entrando em casa de Felipe, o evangelista, que era um dos sete, ficamos com ele.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 9, 'Tinha este quatro filhas virgens que profetizavam.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 10, 'Demorando-nos ali por muitos dias, desceu da Judéia um profeta, de nome Ágabo;', 1, CURRENT_TIMESTAMP, false),
(44, 21, 11, 'e vindo ter conosco, tomou a cinta de Paulo e, ligando os seus próprios pés e mãos, disse: Isto diz o Espírito Santo: Assim os judeus ligarão em Jerusalém o homem a quem pertence esta cinta, e o entregarão nas mãos dos gentios.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 12, 'Quando ouvimos isto, rogamos-lhe, tanto nós como os daquele lugar, que não subisse a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 13, 'Então Paulo respondeu: Que fazeis chorando e magoando-me o coração? Porque eu estou pronto não só a ser ligado, mas ainda a morrer em Jerusalém pelo nome do Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 14, 'E, como não se deixasse persuadir, dissemos: Faça-se a vontade do Senhor; e calamo-nos.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 15, 'Depois destes dias, havendo feito os preparativos, fomos subindo a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 16, 'E foram também conosco alguns discípulos de Cesaréia, levando consigo um certo Mnáson, cíprio, discípulo antigo, com quem nos havíamos de hospedar.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 17, 'E chegando nós a Jerusalém, os irmãos nos receberam alegremente.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 18, 'No dia seguinte Paulo foi em nossa companhia ter com Tiago, e compareceram todos os anciãos.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 19, 'E, havendo-os saudado, contou-lhes uma por uma as coisas que por seu ministério Deus fizera entre os gentios.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 20, 'Ouvindo eles isto, glorificaram a Deus, e disseram-lhe: Bem vês, irmãos, quantos milhares há entre os judeus que têm crido, e todos são zelosos da lei.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 21, 'Têm sido informados a teu respeito que ensinas todos os judeus que estão entre os gentios a se apartarem de Moisés, dizendo que não circuncidem seus filhos, nem andem segundo os costumes da lei.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 22, 'Que se há de fazer, pois? Certamente saberão que és chegado.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 23, 'Faze, pois, o que te vamos dizer: Temos quatro homens que fizeram voto;', 1, CURRENT_TIMESTAMP, false),
(44, 21, 24, 'toma estes contigo, e santifica-te com eles, e faze por eles as despesas para que rapem a cabeça; e saberão todos que é falso aquilo de que têm sido informados a teu respeito, mas que também tu mesmo andas corretamente, guardando a lei.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 25, 'Todavia, quanto aos gentios que têm crido já escrevemos, dando o parecer que se abstenham do que é sacrificado a os ídolos, do sangue, do sufocado e da prostituição.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 26, 'Então Paulo, no dia seguinte, tomando consigo aqueles homens, purificou-se com eles e entrou no templo, notificando o cumprimento dos dias da purificação, quando seria feita a favor de cada um deles a respectiva oferta.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 27, 'Mas quando os sete dias estavam quase a terminar, os judeus da Ásia, tendo-o visto no templo, alvoroçaram todo o povo e agarraram-no,', 1, CURRENT_TIMESTAMP, false),
(44, 21, 28, 'clamando: Varões israelitas, acudi; este é o homem que por toda parte ensina a todos contra o povo, contra a lei, e contra este lugar; e ainda, além disso, introduziu gregos no templo, e tem profanado este santo lugar.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 29, 'Antes tinham visto com ele na cidade a Trófimo de Éfeso, e pensavam que Paulo o introduzira no templo.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 30, 'Alvoroçou-se toda a cidade, e houve ajuntamento do povo; e agarrando a Paulo, arrastaram-no para fora do templo, e logo as portas se fecharam.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 31, 'E, procurando eles matá-lo, chegou ao comandante da corte o aviso de que Jerusalém estava toda em confusão;', 1, CURRENT_TIMESTAMP, false),
(44, 21, 32, 'o qual, tomando logo consigo soldados e centuriões, correu para eles; e quando viram o comandante e os soldados, cessaram de espancar a Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 33, 'Então aproximando-se o comandante, prendeu-o e mandou que fosse acorrentado com duas cadeias, e perguntou quem era e o que tinha feito.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 34, 'E na multidão uns gritavam de um modo, outros de outro; mas, não podendo por causa do alvoroço saber a verdade, mandou conduzi-lo à fortaleza.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 35, 'E sucedeu que, chegando às escadas, foi ele carregado pelos soldados por causa da violência da turba.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 36, 'Pois a multidão o seguia, clamando: Mata-o!', 1, CURRENT_TIMESTAMP, false),
(44, 21, 37, 'Quando estava para ser introduzido na fortaleza, disse Paulo ao comandante: É-me permitido dizer-te alguma coisa? Respondeu ele: Sabes o grego?', 1, CURRENT_TIMESTAMP, false),
(44, 21, 38, 'Não és porventura o egípcio que há poucos dias fez uma sedição e levou ao deserto os quatro mil sicários?', 1, CURRENT_TIMESTAMP, false),
(44, 21, 39, 'Mas Paulo lhe disse: Eu sou judeu, natural de Tarso, cidade não insignificante da Cilícia; rogo-te que me permitas falar ao povo.', 1, CURRENT_TIMESTAMP, false),
(44, 21, 40, 'E, havendo-lho permitido o comandante, Paulo, em pé na escada, fez sinal ao povo com a mão; e, feito grande silêncio, falou em língua hebraica, dizendo:', 1, CURRENT_TIMESTAMP, false),
(44, 22, 1, 'Irmãos e pais, ouvi a minha defesa, que agora faço perante vós.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 2, 'Ora, quando ouviram que lhes falava em língua hebraica, guardaram ainda maior silêncio. E ele prosseguiu:', 1, CURRENT_TIMESTAMP, false),
(44, 22, 3, 'Eu sou judeu, nascido em Tarso da Cilícia, mas criado nesta cidade, instruído aos pés de Gamaliel, conforme a precisão da lei de nossos pais, sendo zeloso para com Deus, assim como o sois todos vós no dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 4, 'E persegui este Caminho até a morte, algemando e metendo em prisões tanto a homens como a mulheres,', 1, CURRENT_TIMESTAMP, false),
(44, 22, 5, 'do que também o sumo sacerdote me é testemunha, e assim todo o conselho dos anciãos; e, tendo recebido destes cartas para os irmãos, seguia para Damasco, com o fim de trazer algemados a Jerusalém aqueles que ali estivessem, para que fossem castigados.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 6, 'Aconteceu, porém, que, quando caminhava e ia chegando perto de Damasco, pelo meio-dia, de repente, do céu brilhou-me ao redor uma grande luz.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 7, 'Caí por terra e ouvi uma voz que me dizia: Saulo, Saulo, por que me persegues?', 1, CURRENT_TIMESTAMP, false),
(44, 22, 8, 'Eu respondi: Quem és tu, Senhor? Disse-me: Eu sou Jesus, o nazareno, a quem tu persegues.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 9, 'E os que estavam comigo viram, em verdade, a luz, mas não entenderam a voz daquele que falava comigo.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 10, 'Então perguntei: Senhor que farei? E o Senhor me disse: Levanta-te, e vai a Damasco, onde se te dirá tudo o que te é ordenado fazer.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 11, 'Como eu nada visse por causa do esplendor daquela luz, guiado pela mão dos que estavam comigo cheguei a Damasco.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 12, 'Um certo Ananias, varão piedoso conforme a lei, que tinha bom testemunho de todos os judeus que ali moravam,', 1, CURRENT_TIMESTAMP, false),
(44, 22, 13, 'vindo ter comigo, de pé ao meu lado, disse-me: Saulo, irmão, recobra a vista. Naquela mesma hora, recobrando a vista, eu o vi.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 14, 'Disse ele: O Deus de nossos pais de antemão te designou para conhecer a sua vontade, ver o Justo, e ouvir a voz da sua boca.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 15, 'Porque hás de ser sua testemunha para com todos os homens do que tens visto e ouvido.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 16, 'Agora por que te demoras? Levanta-te, batiza-te e lava os teus pecados, invocando o seu nome.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 17, 'Aconteceu que, tendo eu voltado para Jerusalém, enquanto orava no templo, achei-me em êxtase,', 1, CURRENT_TIMESTAMP, false),
(44, 22, 18, 'e vi aquele que me dizia: Apressa-te e sai logo de Jerusalém; porque não receberão o teu testemunho acerca de mim.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 19, 'Disse eu: Senhor, eles bem sabem que eu encarcerava e açoitava pelas sinagogas os que criam em ti.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 20, 'E quando se derramava o sangue de Estêvão, tua testemunha, eu também estava presente, consentindo na sua morte e guardando as capas dos que o matavam.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 21, 'Disse-me ele: Vai, porque eu te enviarei para longe, aos gentios.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 22, 'Ora, escutavam-no até esta palavra, mas então levantaram a voz, dizendo: Tira do mundo tal homem, porque não convém que viva.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 23, 'Gritando eles e arrojando de si as capas e lançando pó para o ar,', 1, CURRENT_TIMESTAMP, false),
(44, 22, 24, 'o comandante mandou que levassem Paulo para dentro da fortaleza, ordenando que fosse interrogado debaixo de açoites, para saber por que causa assim clamavam contra ele.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 25, 'Quando o haviam atado com as correias, disse Paulo ao centurião que ali estava: É-vos lícito açoitar um cidadão romano, sem ser ele condenado?', 1, CURRENT_TIMESTAMP, false),
(44, 22, 26, 'Ouvindo isto, foi o centurião ter com o comandante e o avisou, dizendo: Vê o que estás para fazer, pois este homem é romano.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 27, 'Vindo o comandante, perguntou-lhe: Dize-me: és tu romano? Respondeu ele: Sim sou.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 28, 'Tornou o comandante: Eu por grande soma de dinheiro adquiri este direito de cidadão. Paulo disse: Mas eu o sou de nascimento.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 29, 'Imediatamente, pois se apartaram dele aqueles que o iam interrogar; e até o comandante, tendo sabido que Paulo era romano, atemorizou-se porque o havia ligado.', 1, CURRENT_TIMESTAMP, false),
(44, 22, 30, 'No dia seguinte, querendo saber ao certo a causa por que ele era acusado pelos judeus, soltou-o das prisões, e mandou que se reunissem os principais sacerdotes e todo o sinédrio; e, trazendo Paulo, apresentou-o diante deles.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 1, 'Fitando Paulo os olhos no sinédrio, disse: Varões irmãos, até o dia de hoje tenho andado diante de Deus com toda a boa consciência.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 2, 'Mas o sumo sacerdote, Ananias, mandou aos que estavam junto dele que o ferissem na boca.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 3, 'Então Paulo lhe disse: Deus te ferirá a ti, parede branqueada; tu estás aí sentado para julgar-me segundo a lei, e contra a lei mandas que eu seja ferido?', 1, CURRENT_TIMESTAMP, false),
(44, 23, 4, 'Os que estavam ali disseram: Injurias o sumo sacerdote de Deus?', 1, CURRENT_TIMESTAMP, false),
(44, 23, 5, 'Disse Paulo: Não sabia, irmãos, que era o sumo sacerdote; porque está escrito: Não dirás mal do príncipe do teu povo.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 6, 'Sabendo Paulo que uma parte era de saduceus e outra de fariseus, clamou no sinédrio: Varões irmãos, eu sou fariseu, filho de fariseus; é por causa da esperança da ressurreição dos mortos que estou sendo julgado.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 7, 'Ora, dizendo ele isto, surgiu dissensão entre os fariseus e saduceus; e a multidão se dividiu.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 8, 'Porque os saduceus dizem que não há ressurreição, nem anjo, nem espírito; mas os fariseus reconhecem uma e outra coisa.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 9, 'Daí procedeu grande clamor; e levantando-se alguns da parte dos fariseus, altercavam, dizendo: Não achamos nenhum mal neste homem. E se algum espírito ou anjo lhe falou, não resistamos a Deus.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 10, 'E avolumando-se a dissenção, o comandante, temendo que Paulo fosse por eles despedaçado, mandou que os soldados descessem e o tirassem do meio deles e o levassem para a fortaleza.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 11, 'Na noite seguinte, apresentou-se-lhe o Senhor e disse: Tem bom ânimo: porque, como deste testemunho de mim em Jerusalém, assim importa que o dês também em Roma.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 12, 'Quando já era dia, coligaram-se os judeus e juraram sob pena de maldição que não comeriam nem beberiam enquanto não matassem a Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 13, 'Eram mais de quarenta os que fizeram esta conjuração;', 1, CURRENT_TIMESTAMP, false),
(44, 23, 14, 'e estes foram ter com os principais sacerdotes e anciãos, e disseram: Conjuramo-nos sob pena de maldição a não provarmos coisa alguma até que matemos a Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 15, 'Agora, pois, vós, com o sinédrio, rogai ao comandante que o mande descer perante vós como se houvésseis de examinar com mais precisão a sua causa; e nós estamos prontos para matá-lo antes que ele chegue.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 16, 'Mas o filho da irmã de Paulo, tendo sabido da cilada, foi, entrou na fortaleza e avisou a Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 17, 'Chamando Paulo um dos centuriões, disse: Leva este moço ao comandante, porque tem alguma coisa que lhe comunicar.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 18, 'Tomando-o ele, pois, levou-o ao comandante e disse: O preso Paulo, chamando-me, pediu-me que trouxesse à tua presença este moço, que tem alguma coisa a dizer-te.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 19, 'O comandante tomou-o pela mão e, retirando-se à parte, perguntou-lhe em particular: Que é que tens a contar-me?', 1, CURRENT_TIMESTAMP, false),
(44, 23, 20, 'Disse ele: Os judeus combinaram rogar-te que amanhã mandes Paulo descer ao sinédrio, como que tendo de inquirir com mais precisão algo a seu respeito.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 21, 'Tu, pois, não te deixes persuadir por eles; porque mais de quarenta homens dentre eles armaram ciladas, os quais juraram sob pena de maldição não comerem nem beberem até que o tenham morto; e agora estão aprestados, esperando a tua promessa.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 22, 'Então o comandante despediu o moço, ordenando-lhe que a ninguém dissesse que lhe havia contado aquilo.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 23, 'Chamando dois centuriões, disse: Aprontai para a terceira hora da noite duzentos soldados de infantaria, setenta de cavalaria e duzentos lanceiros para irem até Cesaréia.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 24, 'E mandou que aparelhassem cavalgaduras para que Paulo montasse, a fim de o levarem salvo ao governador Félix.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 25, 'E escreveu-lhe uma carta nestes termos:', 1, CURRENT_TIMESTAMP, false),
(44, 23, 26, 'Cláudio Lísias, ao excelentíssimo governador Félix, saúde.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 27, 'Este homem foi preso pelos judeus, e estava a ponto de ser morto por eles quando eu sobrevim com a tropa e o livrei ao saber que era romano.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 28, 'Querendo saber a causa por que o acusavam, levei-o ao sinédrio deles;', 1, CURRENT_TIMESTAMP, false),
(44, 23, 29, 'e achei que era acusado de questões da lei deles, mas que nenhum crime havia nele digno de morte ou prisão.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 30, 'E quando fui informado que haveria uma cilada contra o homem, logo to enviei, intimando também aos acusadores que perante ti se manifestem contra ele. Passa bem.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 31, 'Os soldados, pois, conforme lhes fora mandado, tomando a Paulo, o levaram de noite a Antipátride.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 32, 'Mas no dia seguinte, deixando aos de cavalaria irem com ele, voltaram à fortaleza;', 1, CURRENT_TIMESTAMP, false),
(44, 23, 33, 'os quais, logo que chegaram a Cesaréia e entregaram a carta ao governador, apresentaram-lhe também Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 23, 34, 'Tendo lido a carta, o governador perguntou de que província ele era; e, sabendo que era da Cilícia, disse:', 1, CURRENT_TIMESTAMP, false),
(44, 23, 35, 'Ouvir-te-ei quando chegarem também os teus acusadores; e mandou que fosse guardado no pretório de Herodes.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 1, 'Cinco dias depois o sumo sacerdote Ananias desceu com alguns anciãos e um certo Tertulo, orador, os quais fizeram, perante o governador, queixa contra Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 2, 'Sendo este chamado, Tertulo começou a acusá-lo, dizendo:', 1, CURRENT_TIMESTAMP, false),
(44, 24, 3, 'Visto que por ti gozamos de muita paz e por tua providência são continuamente feitas reformas nesta nação, em tudo e em todo lugar reconhecemo-lo com toda a gratidão, ó excelentíssimo Félix.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 4, 'Mas, para que não te detenha muito rogo-te que, conforme a tua eqüidade, nos ouças por um momento.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 5, 'Temos achado que este homem é uma peste, e promotor de sedições entre todos os judeus, por todo o mundo, e chefe da seita dos nazarenos;', 1, CURRENT_TIMESTAMP, false),
(44, 24, 6, 'o qual tentou profanar o templo; e nós o prendemos, e conforme a nossa lei o quisemos julgar.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 7, 'Mas sobrevindo o comandante Lísias no-lo tirou dentre as mãos com grande violência,', 1, CURRENT_TIMESTAMP, false),
(44, 24, 8, 'mandando aos acusadores que viessem a ti; e dele tu mesmo, examinando-o, poderás certificar-te de tudo aquilo de que o acusamos.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 9, 'Os judeus também concordam na acusação, afirmando que estas coisas eram assim.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 10, 'Paulo, tendo-lhe o governador feito sinal que falasse, respondeu: Porquanto sei que há muitos anos és juiz sobre esta nação, com bom ânimo faço a minha defesa,', 1, CURRENT_TIMESTAMP, false),
(44, 24, 11, 'pois bem podes verificar que não há mais de doze dias subi a Jerusalém para adorar,', 1, CURRENT_TIMESTAMP, false),
(44, 24, 12, 'e que não me acharam no templo discutindo com alguém nem amotinando o povo, quer nas sinagogas quer na cidade.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 13, 'Nem te podem provar as coisas de que agora me acusam.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 14, 'Mas confesso-te isto: que, seguindo o caminho a que eles chamam seita, assim sirvo ao Deus de nossos pais, crendo tudo quanto está escrito na lei e nos profetas.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 15, 'Tendo esperança em Deus, como estes mesmos também esperam, de que há de haver ressurreição tanto dos justos como dos injustos.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 16, 'Por isso procuro sempre ter uma consciência sem ofensas diante de Deus e dos homens.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 17, 'Vários anos depois vim trazer à minha nação esmolas e ofertas.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 18, 'Ocupado nestas coisas, me acharam já santificado no templo não em ajuntamento, nem com tumulto, alguns judeus da Ásia,', 1, CURRENT_TIMESTAMP, false),
(44, 24, 19, 'os quais deviam comparecer diante de ti e acusar-me se tivessem alguma coisa contra mim;', 1, CURRENT_TIMESTAMP, false),
(44, 24, 20, 'ou estes mesmos digam que iniqüidade acharam, quando compareci perante o sinédrio,', 1, CURRENT_TIMESTAMP, false),
(44, 24, 21, 'a não ser acerca desta única palavra que, estando no meio deles, bradei: Por causa da ressurreição dos mortos é que hoje estou sendo julgado por vós.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 22, 'Félix, porém, que era bem informado a respeito do Caminho, adiou a questão, dizendo: Quando o comandante Lísias tiver descido, então tomarei inteiro conhecimento da vossa causa.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 23, 'E ordenou ao centurião que Paulo ficasse detido, mas fosse tratado com brandura e que a nenhum dos seus proibisse servi-lo.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 24, 'Alguns dias depois, vindo Félix com sua mulher Drusila, que era judia, mandou chamar a Paulo, e ouviu-o acerca da fé em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 25, 'E discorrendo ele sobre a justiça, o domínio próprio e o juízo vindouro, Félix ficou atemorizado e respondeu: Por ora vai-te, e quando tiver ocasião favorável, eu te chamarei.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 26, 'Esperava ao mesmo tempo que Paulo lhe desse dinheiro, pelo que o mandava chamar mais freqüentemente e conversava com ele.', 1, CURRENT_TIMESTAMP, false),
(44, 24, 27, 'Mas passados dois anos, teve Félix por sucessor a Pórcio Festo; e querendo Félix agradar aos judeus, deixou a Paulo preso.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 1, 'Tendo, pois, entrado Festo na província, depois de três dias subiu de Cesaréia a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 2, 'E os principais sacerdotes e os mais eminentes judeus fizeram-lhe queixa contra Paulo e, em detrimento deste,', 1, CURRENT_TIMESTAMP, false),
(44, 25, 3, 'lhe rogavam o favor de o mandar a Jerusalém, armando ciladas para o matarem no caminho.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 4, 'Mas Festo respondeu que Paulo estava detido em Cesaréia, e que ele mesmo brevemente partiria para lá.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 5, 'Portanto, disse ele às autoridades dentre vós desçam comigo e, se há nesse homem algum crime, acusem-no.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 6, 'Tendo-se demorado entre eles não mais de oito ou dez dias, desceu a Cesaréia; e no dia seguinte, sentando-se no tribunal, mandou trazer Paulo.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 7, 'Tendo ele comparecido, rodearam-no os judeus que haviam descido de Jerusalém, trazendo contra ele muitas e graves acusações, que não podiam provar.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 8, 'Paulo, porém, respondeu em sua defesa: Nem contra a lei dos judeus, nem contra o templo, nem contra César, tenho pecado em coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 9, 'Todavia Festo, querendo agradar aos judeus, respondendo a Paulo, disse: Queres subir a Jerusalém e ali ser julgado perante mim acerca destas coisas?', 1, CURRENT_TIMESTAMP, false),
(44, 25, 10, 'Mas Paulo disse: Estou perante o tribunal de César, onde devo ser julgado; nenhum mal fiz aos judeus, como muito bem sabes.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 11, 'Se, pois, sou malfeitor e tenho cometido alguma coisa digna de morte, não recuso morrer; mas se nada há daquilo de que estes me acusam, ninguém me pode entregar a eles; apelo para César.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 12, 'Então Festo, tendo falado com o conselho, respondeu: Apelaste para César; para César irás.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 13, 'Passados alguns dias, o rei Agripa e Berenice vieram a Cesaréia em visita de saudação a Festo.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 14, 'E, como se demorassem ali muitos dias, Festo expôs ao rei o caso de Paulo, dizendo: Há aqui certo homem que foi deixado preso por Félix,', 1, CURRENT_TIMESTAMP, false),
(44, 25, 15, 'a respeito do qual, quando estive em Jerusalém, os principais sacerdotes e os anciãos dos judeus me fizeram queixas, pedindo sentença contra ele;', 1, CURRENT_TIMESTAMP, false),
(44, 25, 16, 'aos quais respondi que não é costume dos romanos condenar homem algum sem que o acusado tenha presentes os seus acusadores e possa defender-se da acusação.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 17, 'Quando então eles se haviam reunido aqui, sem me demorar, no dia seguinte sentei-me no tribunal e mandei trazer o homem;', 1, CURRENT_TIMESTAMP, false),
(44, 25, 18, 'contra o qual os acusadores, levantando-se, não apresentaram acusação alguma das coisas perversas que eu suspeitava;', 1, CURRENT_TIMESTAMP, false),
(44, 25, 19, 'tinham, porém, contra ele algumas questões acerca da sua religião e de um tal Jesus defunto, que Paulo afirmava estar vivo.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 20, 'E, estando eu perplexo quanto ao modo de investigar estas coisas, perguntei se não queria ir a Jerusalém e ali ser julgado no tocante às mesmas.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 21, 'Mas apelando Paulo para que fosse reservado ao julgamento do imperador, mandei que fosse detido até que o enviasse a César.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 22, 'Então Agripa disse a Festo: Eu bem quisera ouvir esse homem. Respondeu-lhe ele: Amanhã o ouvirás.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 23, 'No dia seguinte vindo Agripa e Berenice, com muito aparato, entraram no auditório com os chefes militares e homens principais da cidade; então, por ordem de Festo, Paulo foi trazido.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 24, 'Disse Festo: Rei Agripa e vós todos que estais presentes conosco, vedes este homem por causa de quem toda a multidão dos judeus, tanto em Jerusalém como aqui, recorreu a mim, clamando que não convinha que ele vivesse mais.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 25, 'Eu, porém, achei que ele não havia praticado coisa alguma digna de morte; mas havendo ele apelado para o imperador, resolvi remeter-lho.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 26, 'Do qual não tenho coisa certa que escreva a meu senhor, e por isso perante vós o trouxe, principalmente perante ti, ó rei Agripa, para que, depois de feito o interrogatório, tenha eu alguma coisa que escrever.', 1, CURRENT_TIMESTAMP, false),
(44, 25, 27, 'Porque não me parece razoável enviar um preso, e não notificar as acusações que há contra ele.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 1, 'Depois Agripa disse a Paulo: É-te permitido fazer a tua defesa. Então Paulo, estendendo a mão, começou a sua defesa:', 1, CURRENT_TIMESTAMP, false),
(44, 26, 2, 'Sinto-me feliz, ó rei Agripa, em poder defender-me hoje perante ti de todas as coisas de que sou acusado pelos judeus;', 1, CURRENT_TIMESTAMP, false),
(44, 26, 3, 'mormente porque és versado em todos os costumes e questões que há entre os judeus; pelo que te rogo que me ouças com paciência.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 4, 'A minha vida, pois, desde a mocidade, o que tem sido sempre entre o meu povo e em Jerusalém, sabem-na todos os judeus,', 1, CURRENT_TIMESTAMP, false),
(44, 26, 5, 'pois me conhecem desde o princípio e, se quiserem, podem dar testemunho de que, conforme a mais severa seita da nossa religião, vivi fariseu.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 6, 'E agora estou aqui para ser julgado por causa da esperança da promessa feita por Deus a nossos pais,', 1, CURRENT_TIMESTAMP, false),
(44, 26, 7, 'a qual as nossas doze tribos, servindo a Deus fervorosamente noite e dia, esperam alcançar; é por causa desta esperança, ó rei, que eu sou acusado pelos judeus.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 8, 'Por que é que se julga entre vós incrível que Deus ressuscite os mortos?', 1, CURRENT_TIMESTAMP, false),
(44, 26, 9, 'Eu, na verdade, cuidara que devia praticar muitas coisas contra o nome de Jesus, o nazareno;', 1, CURRENT_TIMESTAMP, false),
(44, 26, 10, 'o que, com efeito, fiz em Jerusalém. Pois havendo recebido autoridade dos principais dos sacerdotes, não somente encerrei muitos dos santos em prisões, como também dei o meu voto contra eles quando os matavam.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 11, 'E, castigando-os muitas vezes por todas as sinagogas, obrigava-os a blasfemar; e enfurecido cada vez mais contra eles, perseguia-os até nas cidades estrangeiras.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 12, 'Indo com este encargo a Damasco, munido de poder e comissão dos principais sacerdotes,', 1, CURRENT_TIMESTAMP, false),
(44, 26, 13, 'ao meio-dia, ó rei vi no caminho uma luz do céu, que excedia o esplendor do sol, resplandecendo em torno de mim e dos que iam comigo.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 14, 'E, caindo nós todos por terra, ouvi uma voz que me dizia em língua hebráica: Saulo, Saulo, por que me persegues? Dura coisa te é recalcitrar contra os aguilhões.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 15, 'Disse eu: Quem és, Senhor? Respondeu o Senhor: Eu sou Jesus, a quem tu persegues;', 1, CURRENT_TIMESTAMP, false),
(44, 26, 16, 'mas levanta-te e põe-te em pé; pois para isto te apareci, para te fazer ministro e testemunha tanto das coisas em que me tens visto como daquelas em que te hei de aparecer;', 1, CURRENT_TIMESTAMP, false),
(44, 26, 17, 'livrando-te deste povo e dos gentios, aos quais te envio,', 1, CURRENT_TIMESTAMP, false),
(44, 26, 18, 'para lhes abrir os olhos a fim de que se convertam das trevas à luz, e do poder de Satanás a Deus, para que recebam remissão de pecados e herança entre aqueles que são santificados pela fé em mim.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 19, 'Pelo que, ó rei Agripa, não fui desobediente à visão celestial,', 1, CURRENT_TIMESTAMP, false),
(44, 26, 20, 'antes anunciei primeiramente aos que estão em Damasco, e depois em Jerusalém, e por toda a terra da Judéia e também aos gentios, que se arrependessem e se convertessem a Deus, praticando obras dignas de arrependimento.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 21, 'Por causa disto os judeus me prenderam no templo e procuravam matar-me.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 22, 'Tendo, pois, alcançado socorro da parte de Deus, ainda até o dia de hoje permaneço, dando testemunho tanto a pequenos como a grandes, não dizendo nada senão o que os profetas e Moisés disseram que devia acontecer;', 1, CURRENT_TIMESTAMP, false),
(44, 26, 23, 'isto é, como o Cristo devia padecer, e como seria ele o primeiro que, pela ressurreição dos mortos, devia anunciar a luz a este povo e também aos gentios.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 24, 'Fazendo ele deste modo a sua defesa, disse Festo em alta voz: Estás louco, Paulo; as muitas letras te fazem delirar.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 25, 'Mas Paulo disse: Não deliro, ó excelentíssimo Festo, antes digo palavras de verdade e de perfeito juízo.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 26, 'Porque o rei, diante de quem falo com liberdade, sabe destas coisas, pois não creio que nada disto lhe é oculto; porque isto não se fez em qualquer canto.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 27, 'Crês tu nos profetas, ó rei Agripa? Sei que crês.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 28, 'Disse Agripa a Paulo: Por pouco me persuades a fazer-me cristão.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 29, 'Respondeu Paulo: Prouvera a Deus que, ou por pouco ou por muito, não somente tu, mas também todos quantos hoje me ouvem, se tornassem tais qual eu sou, menos estas cadeias.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 30, 'E levantou-se o rei, e o governador, e Berenice, e os que com eles estavam sentados,', 1, CURRENT_TIMESTAMP, false),
(44, 26, 31, 'e retirando-se falavam uns com os outros, dizendo: Este homem não fez nada digno de morte ou prisão.', 1, CURRENT_TIMESTAMP, false),
(44, 26, 32, 'Então Agripa disse a Festo: Este homem bem podia ser solto, se não tivesse apelado para César.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 1, 'E, como se determinou que navegássemos para a Itália, entregaram Paulo e alguns outros presos a um centurião por nome Júlio, da corte augusta.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 2, 'E, embarcando em um navio de Adramítio, que estava prestes a navegar em demanda dos portos pela costa da Ásia, fizemo-nos ao mar, estando conosco Aristarco, macedônio de Tessalônica.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 3, 'No dia seguinte chegamos a Sidom, e Júlio, tratando Paulo com bondade, permitiu-lhe ir ver os amigos e receber deles os cuidados necessários.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 4, 'Partindo dali, fomos navegando a sotavento de Chipre, porque os ventos eram contrários.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 5, 'Tendo atravessado o mar ao longo da Cilícia e Panfília, chegamos a Mirra, na Lícia.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 6, 'Ali o centurião achou um navio de Alexandria que navegava para a Itália, e nos fez embarcar nele.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 7, 'Navegando vagarosamente por muitos dias, e havendo chegado com dificuldade defronte de Cnido, não nos permitindo o vento ir mais adiante, navegamos a sotavento de Creta, à altura de Salmone;', 1, CURRENT_TIMESTAMP, false),
(44, 27, 8, 'e, costeando-a com dificuldade, chegamos a um lugar chamado Bons Portos, perto do qual estava a cidade de Laséia.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 9, 'Havendo decorrido muito tempo e tendo-se tornado perigosa a navegação, porque já havia passado o jejum, Paulo os advertia,', 1, CURRENT_TIMESTAMP, false),
(44, 27, 10, 'dizendo-lhes: Senhores, vejo que a viagem vai ser com avaria e muita perda não só para a carga e o navio, mas também para as nossas vidas.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 11, 'Mas o centurião dava mais crédito ao piloto e ao dono do navio do que às coisas que Paulo dizia.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 12, 'E não sendo o porto muito próprio para invernar, os mais deles foram de parecer que daí se fizessem ao mar para ver se de algum modo podiam chegar a Fênice, um porto de Creta que olha para o nordeste e para o sueste, para ali invernar.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 13, 'Soprando brandamente o vento sul, e supondo eles terem alcançado o que desejavam, levantaram ferro e iam costeando Creta bem de perto.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 14, 'Mas não muito depois desencadeou-se do lado da ilha um tufão de vento chamado euro-aquilão;', 1, CURRENT_TIMESTAMP, false),
(44, 27, 15, 'e, sendo arrebatado o navio e não podendo navegar contra o vento, cedemos à sua força e nos deixávamos levar.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 16, 'Correndo a sota-vento de uma pequena ilha chamada Clauda, somente a custo pudemos segurar o batel,', 1, CURRENT_TIMESTAMP, false),
(44, 27, 17, 'o qual recolheram, usando então os meios disponíveis para cingir o navio; e, temendo que fossem lançados na Sirte, arriaram os aparelhos e se deixavam levar.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 18, 'Como fôssemos violentamente açoitados pela tempestade, no dia seguinte começaram a alijar a carga ao mar.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 19, 'E ao terceiro dia, com as próprias mãos lançaram os aparelhos do navio.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 20, 'Não aparecendo por muitos dia nem sol nem estrelas, e sendo nós ainda batidos por grande tempestade, fugiu-nos afinal toda a esperança de sermos salvos.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 21, 'Havendo eles estado muito tempo sem comer, Paulo, pondo-se em pé no meio deles, disse: Senhores, devíeis ter-me ouvido e não ter partido de Creta, para evitar esta avaria e perda.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 22, 'E agora vos exorto a que tenhais bom ânimo, pois não se perderá vida alguma entre vós, mas somente o navio.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 23, 'Porque esta noite me apareceu um anjo do Deus de quem eu sou e a quem sirvo,', 1, CURRENT_TIMESTAMP, false),
(44, 27, 24, 'dizendo: Não temas, Paulo, importa que compareças perante César, e eis que Deus te deu todos os que navegam contigo.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 25, 'Portanto, senhores, tende bom ânimo; pois creio em Deus que há de suceder assim como me foi dito.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 26, 'Contudo é necessário irmos dar em alguma ilha.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 27, 'Quando chegou a décima quarta noite, sendo nós ainda impelidos pela tempestade no mar de Ádria, pela meia-noite, suspeitaram os marinheiros a proximidade de terra;', 1, CURRENT_TIMESTAMP, false),
(44, 27, 28, 'e lançando a sonda, acharam vinte braças; passando um pouco mais adiante, e tornando a lançar a sonda, acharam quinze braças.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 29, 'Ora, temendo irmos dar em rochedos, lançaram da popa quatro âncoras, e esperaram ansiosos que amanhecesse.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 30, 'Procurando, entrementes, os marinheiros fugir do navio, e tendo arriado o batel ao mar sob pretexto de irem lançar âncoras pela proa,', 1, CURRENT_TIMESTAMP, false),
(44, 27, 31, 'disse Paulo ao centurião e aos soldados: Se estes não ficarem no navio, não podereis salvar-vos.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 32, 'Então os soldados cortaram os cabos do batel e o deixaram cair.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 33, 'Enquanto amanhecia, Paulo rogava a todos que comessem alguma coisa, dizendo: É já hoje o décimo quarto dia que esperais e permaneceis em jejum, não havendo provado coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 34, 'Rogo-vos, portanto, que comais alguma coisa, porque disso depende a vossa segurança; porque nem um cabelo cairá da cabeça de qualquer de vós.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 35, 'E, havendo dito isto, tomou o pão, deu graças a Deus na presença de todos e, partindo-o começou a comer.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 36, 'Então todos cobraram ânimo e se puseram também a comer.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 37, 'Éramos ao todo no navio duzentas e setenta e seis almas.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 38, 'Depois de saciados com a comida, começaram a aliviar o navio, alijando o trigo no mar.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 39, 'Quando amanheceu, não reconheciam a terra; divisavam, porém, uma enseada com uma praia, e consultavam se poderiam nela encalhar o navio.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 40, 'Soltando as âncoras, deixaram-nas no mar, largando ao mesmo tempo as amarras do leme; e, içando ao vento a vela da proa, dirigiram-se para a praia.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 41, 'Dando, porém, num lugar onde duas correntes se encontravam, encalharam o navio; e a proa, encravando-se, ficou imóvel, mas a popa se desfazia com a força das ondas.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 42, 'Então o parecer dos soldados era que matassem os presos para que nenhum deles fugisse, escapando a nado.', 1, CURRENT_TIMESTAMP, false),
(44, 27, 43, 'Mas o centurião, querendo salvar a Paulo, estorvou-lhes este intento; e mandou que os que pudessem nadar fossem os primeiros a lançar-se ao mar e alcançar a terra;', 1, CURRENT_TIMESTAMP, false),
(44, 27, 44, 'e que os demais se salvassem, uns em tábuas e outros em quaisquer destroços do navio. Assim chegaram todos à terra salvos.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 1, 'Estando já salvos, soubemos então que a ilha se chamava Malta.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 2, 'Os indígenas usaram conosco de não pouca humanidade; pois acenderam uma fogueira e nos recolheram a todos por causa da chuva que caía, e por causa do frio.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 3, 'Ora havendo Paulo ajuntado e posto sobre o fogo um feixe de gravetos, uma víbora, fugindo do calor, apegou-se-lhe à mão.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 4, 'Quando os indígenas viram o réptil pendente da mão dele, diziam uns aos outros: Certamente este homem é homicida, pois, embora salvo do mar, a Justiça não o deixa viver.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 5, 'Mas ele, sacudindo o réptil no fogo, não sofreu mal nenhum.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 6, 'Eles, porém, esperavam que Paulo viesse a inchar ou a cair morto de repente; mas tendo esperado muito tempo e vendo que nada de anormal lhe sucedia, mudaram de parecer e diziam que era um deus.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 7, 'Ora, nos arredores daquele lugar havia umas terras que pertenciam ao homem principal da ilha, por nome Públio, o qual nos recebeu e hospedou bondosamente por três dias.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 8, 'Aconteceu estar de cama, enfermo de febre e disenteria, o pai de Públio; Paulo foi visitá-lo, e havendo orado, impôs-lhe as mãos, e o curou.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 9, 'Feito isto, vinham também os demais enfermos da ilha, e eram curados;', 1, CURRENT_TIMESTAMP, false),
(44, 28, 10, 'e estes nos distinguiram com muitas honras; e, ao embarcarmos, puseram a bordo as coisas que nos eram necessárias.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 11, 'Passados três meses, partimos em um navio de Alexandria que invernara na ilha, o qual tinha por insígnia Castor e Pólux.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 12, 'E chegando a Siracusa, ficamos ali três dias;', 1, CURRENT_TIMESTAMP, false),
(44, 28, 13, 'donde, costeando, viemos a Régio; e, soprando no dia seguinte o vento sul, chegamos em dois dias a Putéoli,', 1, CURRENT_TIMESTAMP, false),
(44, 28, 14, 'onde, achando alguns irmãos, fomos convidados a ficar com eles sete dias; e depois nos dirigimos a Roma.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 15, 'Ora, os irmãos da lá, havendo recebido notícias nossas, vieram ao nosso encontro até a praça de Ápio e às Três Vendas, e Paulo, quando os viu, deu graças a Deus e cobrou ânimo.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 16, 'Quando chegamos a Roma, {o centurião entregou os presos ao general do exército, mas,} a Paulo se lhe permitiu morar à parte, com o soldado que o guardava.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 17, 'Passados três dias, ele convocou os principais dentre os judeus; e reunidos eles, disse-lhes: Varões irmãos, não havendo eu feito nada contra o povo, ou contra os ritos paternos, vim contudo preso desde Jerusalém, entregue nas mãos dos romanos;', 1, CURRENT_TIMESTAMP, false),
(44, 28, 18, 'os quais, havendo-me interrogado, queriam soltar-me, por não haver em mim crime algum que merecesse a morte.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 19, 'Mas opondo-se a isso os judeus, vi-me obrigado a apelar para César, não tendo, contudo, nada de que acusar a minha nação.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 20, 'Por esta causa, pois, vos convidei, para vos ver e falar; porque pela esperança de Israel estou preso com esta cadeia.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 21, 'Mas eles lhe disseram: Nem recebemos da Judéia cartas a teu respeito, nem veio aqui irmão algum que contasse ou dissesse mal de ti.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 22, 'No entanto bem quiséramos ouvir de ti o que pensas; porque, quanto a esta seita, notório nos é que em toda parte é impugnada.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 23, 'Havendo-lhe eles marcado um dia, muitos foram ter com ele à sua morada, aos quais desde a manhã até a noite explicava com bom testemunho o reino de Deus e procurava persuadí-los acerca de Jesus, tanto pela lei de Moisés como pelos profetas.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 24, 'Uns criam nas suas palavras, mas outros as rejeitavam.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 25, 'E estando discordes entre si, retiraram-se, havendo Paulo dito esta palavra: Bem falou o Espírito Santo aos vossos pais pelo profeta Isaías,', 1, CURRENT_TIMESTAMP, false),
(44, 28, 26, 'dizendo: Vai a este povo e dize: Ouvindo, ouvireis, e de maneira nenhuma entendereis; e vendo, vereis, e de maneira nenhuma percebereis.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 27, 'Porque o coração deste povo se endureceu, e com os ouvidos ouviram tardamente, e fecharam os olhos; para que não vejam com os olhos, nem ouçam com os ouvidos, nem entendam com o coração nem se convertam e eu os cure.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 28, 'Seja-vos pois notório que esta salvação de Deus é enviada aos gentios, e eles ouvirão.', 1, CURRENT_TIMESTAMP, false),
(44, 28, 29, '{E, havendo ele dito isto, partiram os judeus, tendo entre si grande contenda.}', 1, CURRENT_TIMESTAMP, false),
(44, 28, 30, 'E morou dois anos inteiros na casa que alugara, e recebia a todos os que o visitavam,', 1, CURRENT_TIMESTAMP, false),
(44, 28, 31, 'pregando o reino de Deus e ensinando as coisas concernentes ao Senhor Jesus Cristo, com toda a liberdade, sem impedimento algum.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 1, 'O cântico dos cânticos, que é de Salomão.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 2, 'Beije-me ele com os beijos da sua boca; porque melhor é o seu amor do que o vinho.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 3, 'Suave é o cheiro dos teus perfumes; como perfume derramado é o teu nome; por isso as donzelas te amam.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 4, 'Leva-me tu; correremos após ti. O rei me introduziu nas suas recâmaras; em ti nos alegraremos e nos regozijaremos; faremos menção do teu amor mais do que do vinho; com razão te amam.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 5, 'Eu sou morena, mas formosa, ó filhas de Jerusalém, como as tendas de Quedar, como as cortinas de Salomão.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 6, 'Não repareis em eu ser morena, porque o sol crestou-me a tez; os filhos de minha mãe indignaram-se contra mim, e me puseram por guarda de vinhas; a minha vinha, porém, não guardei.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 7, 'Dize-me, ó tu, a quem ama a minha alma: Onde apascentas o teu rebanho, onde o fazes deitar pelo meio-dia; pois, por que razão seria eu como a que anda errante pelos rebanhos de teus companheiros?', 1, CURRENT_TIMESTAMP, false),
(22, 1, 8, 'Se não o sabes, ó tu, a mais formosa entre as mulheres, vai seguindo as pisadas das ovelhas, e apascenta os teus cabritos junto às tendas dos pastores.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 9, 'A uma égua dos carros de Faraó eu te comparo, ó amada minha.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 10, 'Formosas são as tuas faces entre as tuas tranças, e formoso o teu pescoço com os colares.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 11, 'Nós te faremos umas tranças de ouro, marchetadas de pontinhos de prata.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 12, 'Enquanto o rei se assentava à sua mesa, dava o meu nardo o seu cheiro.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 13, 'O meu amado é para mim como um saquitel de mirra, que repousa entre os meus seios.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 14, 'O meu amado é para mim como um ramalhete de hena nas vinhas de En-Gedi.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 15, 'Eis que és formosa, ó amada minha, eis que és formosa; os teus olhos são como pombas.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 16, 'Eis que és formoso, ó amado meu, como amável és também; o nosso leito é viçoso.', 1, CURRENT_TIMESTAMP, false),
(22, 1, 17, 'As traves da nossa casa são de cedro, e os caibros de cipreste.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 1, 'Eu sou a rosa de Sarom, o lírio dos vales.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 2, 'Qual o lírio entre os espinhos, tal é a minha amada entre as filhas.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 3, 'Qual a macieira entre as árvores do bosque, tal é o meu amado entre os filhos; com grande gozo sentei-me à sua sombra; e o seu fruto era doce ao meu paladar.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 4, 'Levou-me à sala do banquete, e o seu estandarte sobre mim era o amor.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 5, 'Sustentai-me com passas, confortai-me com maçãs, porque desfaleço de amor.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 6, 'A sua mão esquerda esteja debaixo da minha cabeça, e a sua mão direita me abrace.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 7, 'Conjuro-vos, ó filhas de Jerusalém, pelas gazelas e cervas do campo, que não acordeis nem desperteis o amor, até que ele o queira.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 8, 'A voz do meu amado! eis que vem aí, saltando sobre os montes, pulando sobre os outeiros.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 9, 'O meu amado é semelhante ao gamo, ou ao filho do veado; eis que está detrás da nossa parede, olhando pelas janelas, lançando os olhos pelas grades.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 10, 'Fala o meu amado e me diz: Levanta-te, amada minha, formosa minha, e vem.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 11, 'Pois eis que já passou o inverno; a chuva cessou, e se foi;', 1, CURRENT_TIMESTAMP, false),
(22, 2, 12, 'aparecem as flores na terra; já chegou o tempo de cantarem as aves, e a voz da rola ouve-se em nossa terra.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 13, 'A figueira começa a dar os seus primeiros figos; as vides estão em flor e exalam o seu aroma. Levanta-te, amada minha, formosa minha, e vem.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 14, 'Pomba minha, que andas pelas fendas das penhas, no oculto das ladeiras, mostra-me o teu semblante faze-me ouvir a tua voz; porque a tua voz é doce, e o teu semblante formoso.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 15, 'Apanhai-nos as raposas, as raposinhas, que fazem mal às vinhas; pois as nossas vinhas estão em flor.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 16, 'O meu amado é meu, e eu sou dele; ele apascenta o seu rebanho entre os lírios.', 1, CURRENT_TIMESTAMP, false),
(22, 2, 17, 'Antes que refresque o dia, e fujam as sombras, volta, amado meu, e faze-te semelhante ao gamo ou ao filho dos veados sobre os montes de Beter.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 1, 'De noite, em meu leito, busquei aquele a quem ama a minha alma; busquei-o, porém não o achei.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 2, 'Levantar-me-ei, pois, e rodearei a cidade; pelas ruas e pelas praças buscarei aquele a quem ama a minha alma. Busquei-o, porém não o achei.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 3, 'Encontraram-me os guardas que rondavam pela cidade; eu lhes perguntei: Vistes, porventura, aquele a quem ama a minha alma?', 1, CURRENT_TIMESTAMP, false),
(22, 3, 4, 'Apenas me tinha apartado deles, quando achei aquele a quem ama a minha alma; detive-o, e não o deixei ir embora, até que o introduzi na casa de minha mãe, na câmara daquela que me concebeu:', 1, CURRENT_TIMESTAMP, false),
(22, 3, 5, 'Conjuro-vos, ó filhos de Jerusalém, pelas gazelas e cervas do campo, que não acordeis, nem desperteis o amor, até que ele o queira.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 6, 'Que é isso que sobe do deserto, como colunas de fumaça, perfumado de mirra, de incenso, e de toda sorte de pós aromáticos do mercador?', 1, CURRENT_TIMESTAMP, false),
(22, 3, 7, 'Eis que é a liteira de Salomão; estão ao redor dela sessenta valentes, dos valentes de Israel,', 1, CURRENT_TIMESTAMP, false),
(22, 3, 8, 'todos armados de espadas, destros na guerra, cada um com a sua espada a cinta, por causa dos temores noturnos.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 9, 'O rei Salomão fez para si um palanquim de madeira do Líbano.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 10, 'Fez-lhe as colunas de prata, o estrado de ouro, o assento de púrpura, o interior carinhosamente revestido pelas filhas de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(22, 3, 11, 'Saí, ó filhas de Sião, e contemplai o rei Salomão com a coroa de que sua mãe o coroou no dia do seu desposório, no dia do júbilo do seu coração.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 1, 'Como és formosa, amada minha, eis que és formosa! os teus olhos são como pombas por detrás do teu véu; o teu cabelo é como o rebanho de cabras que descem pelas colinas de Gileade.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 2, 'Os teus dentes são como o rebanho das ovelhas tosquiadas, que sobem do lavadouro, e das quais cada uma tem gêmeos, e nenhuma delas é desfilhada.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 3, 'Os teus lábios são como um fio de escarlate, e a tua boca e formosa; as tuas faces são como as metades de uma romã por detrás do teu véu.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 4, 'O teu pescoço é como a torre de Davi, edificada para sala de armas; no qual pendem mil broquéis, todos escudos de guerreiros valentes.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 5, 'Os teus seios são como dois filhos gêmeos da gazela, que se apascentam entre os lírios.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 6, 'Antes que refresque o dia e fujam as sombras, irei ao monte da mirra e ao outeiro do incenso.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 7, 'Tu és toda formosa, amada minha, e em ti não há mancha.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 8, 'Vem comigo do Líbano, noiva minha, vem comigo do Líbano. Olha desde o cume de Amana, desde o cume de Senir e de Hermom, desde os covis dos leões, desde os montes dos leopardos.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 9, 'Enlevaste-me o coração, minha irmã, noiva minha; enlevaste-me o coração com um dos teus olhares, com um dos colares do teu pescoço.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 10, 'Quão doce é o teu amor, minha irmã, noiva minha! quanto melhor é o teu amor do que o vinho! e o aroma dos teus ungüentos do que o de toda sorte de especiarias!', 1, CURRENT_TIMESTAMP, false),
(22, 4, 11, 'Os teus lábios destilam o mel, noiva minha; mel e leite estão debaixo da tua língua, e o cheiro dos teus vestidos é como o cheiro do Líbano.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 12, 'Jardim fechado é minha irmã, minha noiva, sim, jardim fechado, fonte selada.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 13, 'Os teus renovos são um pomar de romãs, com frutos excelentes; a hena juntamente com nardo,', 1, CURRENT_TIMESTAMP, false),
(22, 4, 14, 'o nardo, e o açafrão, o cálamo, e o cinamomo, com toda sorte de árvores de incenso; a mirra e o aloés, com todas as principais especiarias.', 1, CURRENT_TIMESTAMP, false),
(22, 4, 15, 'És fonte de jardim, poço de águas vivas, correntes que manam do Líbano!', 1, CURRENT_TIMESTAMP, false),
(22, 4, 16, 'Levanta-te, vento norte, e vem tu, vento sul; assopra no meu jardim, espalha os seus aromas. Entre o meu amado no seu jardim, e coma os seus frutos excelentes!', 1, CURRENT_TIMESTAMP, false),
(22, 5, 1, 'Venho ao meu jardim, minha irmã, noiva minha, para colher a minha mirra com o meu bálsamo, para comer o meu favo com o meu mel, e beber o meu vinho com o meu leite. Comei, amigos, bebei abundantemente, ó amados.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 2, 'Eu dormia, mas o meu coração velava. Eis a voz do meu amado! Está batendo: Abre-me, minha irmã, amada minha, pomba minha, minha imaculada; porque a minha cabeça está cheia de orvalho, os meus cabelos das gotas da noite.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 3, 'Já despi a minha túnica; como a tornarei a vestir? já lavei os meus pés; como os tornarei a sujar?', 1, CURRENT_TIMESTAMP, false),
(22, 5, 4, 'O meu amado meteu a sua mão pela fresta da porta, e o meu coração estremeceu por amor dele.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 5, 'Eu me levantei para abrir ao meu amado; e as minhas mãos destilavam mirra, e os meus dedos gotejavam mirra sobre as aldravas da fechadura.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 6, 'Eu abri ao meu amado, mas ele já se tinha retirado e ido embora. A minha alma tinha desfalecido quando ele falara. Busquei-o, mas não o pude encontrar; chamei-o, porém ele não me respondeu.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 7, 'Encontraram-me os guardas que rondavam pela cidade; espancaram-me, feriram-me; tiraram-me o manto os guardas dos muros.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 8, 'Conjuro-vos, ó filhas de Jerusalém, se encontrardes o meu amado, que lhe digais que estou enferma de amor.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 9, 'Que é o teu amado mais do que outro amado, ó tu, a mais formosa entre as mulheres? Que é o teu amado mais do que outro amado, para que assim nos conjures?', 1, CURRENT_TIMESTAMP, false),
(22, 5, 10, 'O meu amado é cândido e rubicundo, o primeiro entre dez mil.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 11, 'A sua cabeça é como o ouro mais refinado, os seus cabelos são crespos, pretos como o corvo.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 12, 'Os seus olhos são como pombas junto às correntes das águas, lavados em leite, postos em engaste.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 13, 'As suas faces são como um canteiro de bálsamo, os montões de ervas aromáticas; e os seus lábios são como lírios que gotejam mirra.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 14, 'Os seus braços são como cilindros de ouro, guarnecidos de crisólitas; e o seu corpo é como obra de marfim, coberta de safiras.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 15, 'As suas pernas como colunas de mármore, colocadas sobre bases de ouro refinado; o seu semblante como o Líbano, excelente como os cedros.', 1, CURRENT_TIMESTAMP, false),
(22, 5, 16, 'O seu falar é muitíssimo suave; sim, ele é totalmente desejável. Tal é o meu amado, e tal o meu amigo, ó filhas de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 1, 'Para onde foi o teu amado, ó tu, a mais formosa entre as mulheres? para onde se retirou o teu amado, a fim de que o busquemos juntamente contigo?', 1, CURRENT_TIMESTAMP, false),
(22, 6, 2, 'O meu amado desceu ao seu jardim, aos canteiros de bálsamo, para apascentar o rebanho nos jardins e para colher os lírios.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 3, 'Eu sou do meu amado, e o meu amado é meu; ele apascenta o rebanho entre os lírios.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 4, 'Formosa és, amada minha, como Tirza, aprazível como Jerusalém, imponente como um exército com bandeiras.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 5, 'Desvia de mim os teus olhos, porque eles me perturbam. O teu cabelo é como o rebanho de cabras que descem pelas colinas de Gileade.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 6, '0s teus dentes são como o rebanho de ovelhas que sobem do lavadouro, e das quais cada uma tem gêmeos, e nenhuma delas é desfilhada.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 7, 'As tuas faces são como as metades de uma romã, por detrás do teu véu.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 8, 'Há sessenta rainhas, oitenta concubinas, e virgens sem número.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 9, 'Mas uma só é a minha pomba, a minha imaculada; ela e a única de sua mãe, a escolhida da que a deu à luz. As filhas viram-na e lhe chamaram bem-aventurada; viram-na as rainhas e as concubinas, e louvaram-na.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 10, 'Quem é esta que aparece como a alva do dia, formosa como a lua, brilhante como o sol, imponente como um exército com bandeiras?', 1, CURRENT_TIMESTAMP, false),
(22, 6, 11, 'Desci ao jardim das nogueiras, para ver os renovos do vale, para ver se floresciam as vides e se as romanzeiras estavam em flor.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 12, 'Antes de eu o sentir, pôs-me a minha alma nos carros do meu nobre povo.', 1, CURRENT_TIMESTAMP, false),
(22, 6, 13, 'Volta, volta, ó Sulamita; volta, volta, para que nós te vejamos. Por que quereis olhar para a Sulamita como para a dança de Maanaim?', 1, CURRENT_TIMESTAMP, false),
(22, 7, 1, 'Quão formosos são os teus pés nas sandálias, ó filha de príncipe! Os contornos das tuas coxas são como jóias, obra das mãos de artista.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 2, 'O teu umbigo como uma taça redonda, a que não falta bebida; o teu ventre como montão de trigo, cercado de lírios.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 3, 'Os teus seios são como dois filhos gêmeos da gazela.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 4, 'O teu pescoço como a torre de marfim; os teus olhos como as piscinas de Hesbom, junto à porta de Bate-Rabim; o teu nariz é como torre do Líbano, que olha para Damasco.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 5, 'A tua cabeça sobre ti é como o monte Carmelo, e os cabelos da tua cabeça como a púrpura; o rei está preso pelas tuas tranças.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 6, 'Quão formosa, e quão aprazível és, ó amor em delícias!', 1, CURRENT_TIMESTAMP, false),
(22, 7, 7, 'Essa tua estatura é semelhante à palmeira, e os teus seios aos cachos de uvas.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 8, 'Disse eu: Subirei à palmeira, pegarei em seus ramos; então sejam os teus seios como os cachos da vide, e o cheiro do teu fôlego como o das maçãs,', 1, CURRENT_TIMESTAMP, false),
(22, 7, 9, 'e os teus beijos como o bom vinho para o meu amado, que se bebe suavemente, e se escoa pelos lábios e dentes.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 10, 'Eu sou do meu amado, e o seu amor é por mim.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 11, 'Vem, ó amado meu, saiamos ao campo, passemos as noites nas aldeias.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 12, 'Levantemo-nos de manhã para ir às vinhas, vejamos se florescem as vides, se estão abertas as suas flores, e se as romanzeiras já estão em flor; ali te darei o meu amor.', 1, CURRENT_TIMESTAMP, false),
(22, 7, 13, 'As mandrágoras exalam perfume, e às nossas portas há toda sorte de excelentes frutos, novos e velhos; eu os guardei para ti, ó meu amado.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 1, 'Ah! quem me dera que foras como meu irmão, que mamou os seios de minha mãe! quando eu te encontrasse lá fora, eu te beijaria; e não me desprezariam!', 1, CURRENT_TIMESTAMP, false),
(22, 8, 2, 'Eu te levaria e te introduziria na casa de minha mãe, e tu me instruirias; eu te daria a beber vinho aromático, o mosto das minhas romãs.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 3, 'A sua mão esquerda estaria debaixo da minha cabeça, e a sua direita me abraçaria.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 4, 'Conjuro-vos, ó filhas de Jerusalém, que não acordeis nem desperteis o amor, até que ele o queira.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 5, 'Quem é esta que sobe do deserto, e vem encostada ao seu amado? Debaixo da macieira te despertei; ali esteve tua mãe com dores; ali esteve com dores aquela que te deu à luz.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 6, 'Põe-me como selo sobre o teu coração, como selo sobre o teu braço; porque o amor é forte como a morte; o ciúme é cruel como o Seol; a sua chama é chama de fogo, verdadeira labareda do Senhor.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 7, 'As muitas águas não podem apagar o amor, nem os rios afogá-lo. Se alguém oferecesse todos os bens de sua casa pelo amor, seria de todo desprezado.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 8, 'Temos uma irmã pequena, que ainda não tem seios; que faremos por nossa irmã, no dia em que ela for pedida em casamento?', 1, CURRENT_TIMESTAMP, false),
(22, 8, 9, 'Se ela for um muro, edificaremos sobre ela uma torrezinha de prata; e, se ela for uma porta, cercá-la-emos com tábuas de cedro.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 10, 'Eu era um muro, e os meus seios eram como as suas torres; então eu era aos seus olhos como aquela que acha paz.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 11, 'Teve Salomão uma vinha em Baal-Hamom; arrendou essa vinha a uns guardas; e cada um lhe devia trazer pelo seu fruto mil peças de prata.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 12, 'A minha vinha que me pertence está diante de mim; tu, ó Salomão, terás as mil peças de prata, e os que guardam o fruto terão duzentas.', 1, CURRENT_TIMESTAMP, false),
(22, 8, 13, 'Ó tu, que habitas nos jardins, os companheiros estão atentos para ouvir a tua voz; faze-me, pois, também ouvi-la:', 1, CURRENT_TIMESTAMP, false),
(22, 8, 14, 'Vem depressa, amado meu, e faze-te semelhante ao gamo ou ao filho da gazela sobre os montes dos aromas.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, e o irmão Timóteo,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 2, 'aos santos e fiéis irmãos em Cristo que estão em Colossos: Graças a vós, e paz da parte de Deus nosso Pai.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 3, 'Graças damos a Deus, Pai de nosso Senhor Jesus Cristo, orando sempre por vós,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 4, 'desde que ouvimos falar da vossa fé em Cristo Jesus, e do amor que tendes a todos os santos,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 5, 'por causa da esperança que vos está reservada nos céus, da qual antes ouvistes pela palavra da verdade do evangelho,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 6, 'que já chegou a vós, como também está em todo o mundo, frutificando e crescendo, assim como entre vós desde o dia em que ouvistes e conhecestes a graça de Deus em verdade,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 7, 'segundo aprendestes de Epafras, nosso amado conservo, que por nós é fiel ministro de Cristo.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 8, 'O qual também nos declarou o vosso amor no Espírito.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 9, 'Por esta razão, nós também, desde o dia em que ouvimos, não cessamos de orar por vós, e de pedir que sejais cheios do pleno conhecimento da sua vontade, em toda a sabedoria e entendimento espiritual;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 10, 'para que possais andar de maneira digna do Senhor, agradando-lhe em tudo, frutificando em toda boa obra, e crescendo no conhecimento de Deus,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 11, 'corroborados com toda a fortaleza, segundo o poder da sua glória, para toda a perseverança e longanimidade com gozo;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 12, 'dando graças ao Pai que vos fez idôneos para participar da herança dos santos na luz,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 13, 'e que nos tirou do poder das trevas, e nos transportou para o reino do seu Filho amado;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 14, 'em quem temos a redenção, a saber, a remissão dos pecados;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 15, 'o qual é imagem do Deus invisível, o primogênito de toda a criação;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 16, 'porque nele foram criadas todas as coisas nos céus e na terra, as visíveis e as invisíveis, sejam tronos, sejam dominações, sejam principados, sejam potestades; tudo foi criado por ele e para ele.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 17, 'Ele é antes de todas as coisas, e nele subsistem todas as coisas;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 18, 'também ele é a cabeça do corpo, da igreja; é o princípio, o primogênito dentre os mortos, para que em tudo tenha a preeminência,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 19, 'porque aprouve a Deus que nele habitasse toda a plenitude,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 20, 'e que, havendo por ele feito a paz pelo sangue da sua cruz, por meio dele reconciliasse consigo mesmo todas as coisas, tanto as que estão na terra como as que estão nos céus.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 21, 'A vós também, que outrora éreis estranhos, e inimigos no entendimento pelas vossas obras más,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 22, 'agora contudo vos reconciliou no corpo da sua carne, pela morte, a fim de perante ele vos apresentar santos, sem defeito e irrepreensíveis,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 23, 'se é que permaneceis na fé, fundados e firmes, não vos deixando apartar da esperança do evangelho que ouvistes, e que foi pregado a toda criatura que há debaixo do céu, e do qual eu, Paulo, fui constituído ministro.', 1, CURRENT_TIMESTAMP, false),
(51, 1, 24, 'Agora me regozijo no meio dos meus sofrimentos por vós, e cumpro na minha carne o que resta das aflições de Cristo, por amor do seu corpo, que é a igreja;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 25, 'da qual eu fui constituído ministro segundo a dispensação de Deus, que me foi concedida para convosco, a fim de cumprir a palavra de Deus,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 26, 'o mistério que esteve oculto dos séculos, e das gerações; mas agora foi manifesto aos seus santos,', 1, CURRENT_TIMESTAMP, false),
(51, 1, 27, 'a quem Deus quis fazer conhecer quais são as riquezas da glória deste mistério entre os gentios, que é Cristo em vós, a esperança da glória;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 28, 'o qual nós anunciamos, admoestando a todo homem, e ensinando a todo homem em toda a sabedoria, para que apresentemos todo homem perfeito em Cristo;', 1, CURRENT_TIMESTAMP, false),
(51, 1, 29, 'para isso também trabalho, lutando segundo a sua eficácia, que opera em mim poderosamente.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 1, 'Pois quero que saibais quão grande luta tenho por vós, e pelos que estão em Laodicéia, e por quantos não viram a minha pessoa;', 1, CURRENT_TIMESTAMP, false),
(51, 2, 2, 'para que os seus corações sejam animados, estando unidos em amor, e enriquecidos da plenitude do entendimento para o pleno conhecimento do mistério de Deus-Cristo,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 3, 'no qual estão escondidos todos os tesouros da sabedoria e da ciência.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 4, 'Digo isto, para que ninguém vos engane com palavras persuasivas.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 5, 'Porque ainda que eu esteja ausente quanto ao corpo, contudo em espírito estou convosco, regozijando-me, e vendo a vossa ordem e a firmeza da vossa fé em Cristo.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 6, 'Portanto, assim como recebestes a Cristo Jesus, o Senhor, assim também nele andai,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 7, 'arraigados e edificados nele, e confirmados na fé, assim como fostes ensinados, abundando em ação de graças.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 8, 'Tendo cuidado para que ninguém vos faça presa sua, por meio de filosofias e vãs sutilezas, segundo a tradição dos homens, segundo os rudimentos do mundo, e não segundo Cristo;', 1, CURRENT_TIMESTAMP, false),
(51, 2, 9, 'porque nele habita corporalmente toda a plenitude da divindade,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 10, 'e tendes a vossa plenitude nele, que é a cabeça de todo principado e potestade,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 11, 'no qual também fostes circuncidados com a circuncisão não feita por mãos no despojar do corpo da carne, a saber, a circuncisão de Cristo;', 1, CURRENT_TIMESTAMP, false),
(51, 2, 12, 'tendo sido sepultados com ele no batismo, no qual também fostes ressuscitados pela fé no poder de Deus, que o ressuscitou dentre os mortos;', 1, CURRENT_TIMESTAMP, false),
(51, 2, 13, 'e a vós, quando estáveis mortos nos vossos delitos e na incircuncisão da vossa carne, vos vivificou juntamente com ele, perdoando-nos todos os delitos;', 1, CURRENT_TIMESTAMP, false),
(51, 2, 14, 'e havendo riscado o escrito de dívida que havia contra nós nas suas ordenanças, o qual nos era contrário, removeu-o do meio de nós, cravando-o na cruz;', 1, CURRENT_TIMESTAMP, false),
(51, 2, 15, 'e, tendo despojado os principados e potestades, os exibiu publicamente e deles triunfou na mesma cruz.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 16, 'Ninguém, pois, vos julgue pelo comer, ou pelo beber, ou por causa de dias de festa, ou de lua nova, ou de sábados,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 17, 'que são sombras das coisas vindouras; mas o corpo é de Cristo.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 18, 'Ninguém atue como árbitro contra vós, afetando humildade ou culto aos anjos, firmando-se em coisas que tenha visto, inchado vãmente pelo seu entendimento carnal,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 19, 'e não retendo a Cabeça, da qual todo o corpo, provido e organizado pelas juntas e ligaduras, vai crescendo com o aumento concedido por Deus.', 1, CURRENT_TIMESTAMP, false),
(51, 2, 20, 'Se morrestes com Cristo quanto aos rudimentos do mundo, por que vos sujeitais ainda a ordenanças, como se vivêsseis no mundo,', 1, CURRENT_TIMESTAMP, false),
(51, 2, 21, 'tais como: não toques, não proves, não manuseies', 1, CURRENT_TIMESTAMP, false),
(51, 2, 22, '{as quais coisas todas hão de perecer pelo uso}, segundo os preceitos e doutrinas dos homens?', 1, CURRENT_TIMESTAMP, false),
(51, 2, 23, 'As quais têm, na verdade, alguma aparência de sabedoria em culto voluntário, humildade fingida, e severidade para com o corpo, mas não têm valor algum no combate contra a satisfação da carne.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 1, 'Se, pois, fostes ressuscitados juntamente com Cristo, buscai as coisas que são de cima, onde Cristo está assentado à destra de Deus.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 2, 'Pensai nas coisas que são de cima, e não nas que são da terra;', 1, CURRENT_TIMESTAMP, false),
(51, 3, 3, 'porque morrestes, e a vossa vida está escondida com Cristo em Deus.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 4, 'Quando Cristo, que é a nossa vida, se manifestar, então também vós vos manifestareis com ele em glória.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 5, 'Exterminai, pois, as vossas inclinações carnais; a prostituição, a impureza, a paixão, a vil concupiscência, e a avareza, que é idolatria;', 1, CURRENT_TIMESTAMP, false),
(51, 3, 6, 'pelas quais coisas vem a ira de Deus sobre os filhos da desobediência;', 1, CURRENT_TIMESTAMP, false),
(51, 3, 7, 'nas quais também em outro tempo andastes, quando vivíeis nelas;', 1, CURRENT_TIMESTAMP, false),
(51, 3, 8, 'mas agora despojai-vos também de tudo isto: da ira, da cólera, da malícia, da maledicência, das palavras torpes da vossa boca;', 1, CURRENT_TIMESTAMP, false),
(51, 3, 9, 'não mintais uns aos outros, pois que já vos despistes do homem velho com os seus feitos,', 1, CURRENT_TIMESTAMP, false),
(51, 3, 10, 'e vos vestistes do novo, que se renova para o pleno conhecimento, segundo a imagem daquele que o criou;', 1, CURRENT_TIMESTAMP, false),
(51, 3, 11, 'onde não há grego nem judeu, circuncisão nem incircuncisão, bárbaro, cita, escravo ou livre, mas Cristo é tudo em todos.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 12, 'Revestí-vos, pois, como eleitos de Deus, santos e amados, de coração compassivo, de benignidade, humildade, mansidão, longanimidade,', 1, CURRENT_TIMESTAMP, false),
(51, 3, 13, 'suportando-vos e perdoando-vos uns aos outros, se alguém tiver queixa contra outro; assim como o Senhor vos perdoou, assim fazei vós também.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 14, 'E, sobre tudo isto, revestí-vos do amor, que é o vínculo da perfeição.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 15, 'E a paz de Cristo, para a qual também fostes chamados em um corpo, domine em vossos corações; e sede agradecidos.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 16, 'A palavra de Cristo habite em vós ricamente, em toda a sabedoria; ensinai-vos e admoestai-vos uns aos outros, com salmos, hinos e cânticos espirituais, louvando a Deus com gratidão em vossos corações.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 17, 'E tudo quanto fizerdes por palavras ou por obras, fazei-o em nome do Senhor Jesus, dando por ele graças a Deus Pai.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 18, 'Vós, mulheres, sede submissas a vossos maridos, como convém no Senhor.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 19, 'Vós, maridos, amai a vossas mulheres, e não as trateis asperamente.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 20, 'Vós, filhos, obedecei em tudo a vossos pais; porque isto é agradável ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 21, 'Vós, pais, não irriteis a vossos filhos, para que não fiquem desanimados.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 22, 'Vós, servos, obedecei em tudo a vossos senhores segundo a carne, não servindo somente à vista como para agradar aos homens, mas em singeleza de coração, temendo ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 23, 'E tudo quanto fizerdes, fazei-o de coração, como ao Senhor, e não aos homens,', 1, CURRENT_TIMESTAMP, false),
(51, 3, 24, 'sabendo que do Senhor recebereis como recompensa a herança; servi a Cristo, o Senhor.', 1, CURRENT_TIMESTAMP, false),
(51, 3, 25, 'Pois quem faz injustiça receberá a paga da injustiça que fez; e não há acepção de pessoas.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 1, 'Vós, senhores, dai a vossos servos o que é de justiça e eqüidade, sabendo que também vós tendes um Senhor no céu.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 2, 'Perseverai na oração, velando nela com ações de graças,', 1, CURRENT_TIMESTAMP, false),
(51, 4, 3, 'orando ao mesmo tempo também por nós, para que Deus nos abra uma porta à palavra, a fim de falarmos o mistério de Cristo, pelo qual também estou preso,', 1, CURRENT_TIMESTAMP, false),
(51, 4, 4, 'para que eu o manifeste como devo falar.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 5, 'Andai em sabedoria para com os que estão de fora, usando bem cada oportunidade.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 6, 'A vossa palavra seja sempre com graça, temperada com sal, para saberdes como deveis responder a cada um.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 7, 'Tíquico, o irmão amado, fiel ministro e conservo no Senhor, vos fará conhecer a minha situação;', 1, CURRENT_TIMESTAMP, false),
(51, 4, 8, 'o qual vos envio para este mesmo fim, para que saibais o nosso estado e ele conforte os vossos corações,', 1, CURRENT_TIMESTAMP, false),
(51, 4, 9, 'juntamente com Onésimo, fiel e amado irmão, que é um de vós; eles vos farão saber tudo o que aqui se passa.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 10, 'Saúda-vos Aristarco, meu companheiro de prisão, e Marcos, o primo de Barnabé {a respeito do qual recebestes instruções; se for ter convosco, recebei-o},', 1, CURRENT_TIMESTAMP, false),
(51, 4, 11, 'e Jesus, que se chama Justo, sendo unicamente estes, dentre a circuncisão, os meus cooperadores no reino de Deus; os quais têm sido para mim uma consolação.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 12, 'Saúda-vos Epafras, que é um de vós, servo de Cristo Jesus, e que sempre luta por vós nas suas orações, para que permaneçais perfeitos e plenamente seguros em toda a vontade de Deus.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 13, 'Pois dou-lhe testemunho de que tem grande zelo por vós, como também pelos que estão em Laodicéia, e pelos que estão em Hierápolis.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 14, 'Saúda-vos Lucas, o médico amado, e Demas.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 15, 'Saudai aos irmãos que estão em Laodicéia, e a Ninfas e a igreja que está em sua casa.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 16, 'Depois que for lida esta carta entre vós, fazei que o seja também na igreja dos laodicenses; e a de Laodicéia lede-a vós também.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 17, 'E dizei a Arquipo: Cuida do ministério que recebestes no Senhor, para o cumprires.', 1, CURRENT_TIMESTAMP, false),
(51, 4, 18, 'Esta saudação é de próprio punho, de Paulo. Lembrai-vos das minhas cadeias. A graça seja convosco.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 1, 'No ano terceiro do reinado de Jeoiaquim, rei de Judá, veio Nabucodonosor, rei de Babilônia, a Jerusalém, e a sitiou.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 2, 'E o Senhor lhe entregou nas mãos a Jeoiaquim, rei de Judá, e uma parte dos vasos da casa de Deus; e ele os levou para a terra de Sinar, para a casa do seu deus; e os pôs na casa do tesouro do seu deus.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 3, 'Então disse o rei a Aspenaz, chefe dos seus eunucos que trouxesse alguns dos filhos de Israel, dentre a linhagem real e dos nobres,', 1, CURRENT_TIMESTAMP, false),
(27, 1, 4, 'jovens em quem não houvesse defeito algum, de bela aparência, dotados de sabedoria, inteligência e instrução, e que tivessem capacidade para assistirem no palácio do rei; e que lhes ensinasse as letras e a língua dos caldeus.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 5, 'E o rei lhes determinou a porção diária das iguarias do rei, e do vinho que ele bebia, e que assim fossem alimentados por três anos; para que no fim destes pudessem estar diante do rei.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 6, 'Ora, entre eles se achavam, dos filhos de Judá, Daniel, Hananias, Misael e Azarias.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 7, 'Mas o chefe dos eunucos lhes pôs outros nomes, a saber: a Daniel, o de Beltessazar; a Hananias, o de Sadraque; a Misael, o de Mesaque; e a Azarias, o de Abednego.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 8, 'Daniel, porém, propôs no seu coração não se contaminar com a porção das iguarias do rei, nem com o vinho que ele bebia; portanto pediu ao chefe dos eunucos que lhe concedesse não se contaminar.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 9, 'Ora, Deus fez com que Daniel achasse graça e misericórdia diante do chefe dos eunucos.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 10, 'E disse o chefe dos eunucos a Daniel: Tenho medo do meu senhor, o rei, que determinou a vossa comida e a vossa bebida; pois veria ele os vossos rostos mais abatidos do que os dos outros jovens da vossa idade? Assim poríeis em perigo a minha cabeça para com o rei.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 11, 'Então disse Daniel ao despenseiro a quem o chefe dos eunucos havia posto sobre Daniel, Hananias, Misael e Azarias:', 1, CURRENT_TIMESTAMP, false),
(27, 1, 12, 'Experimenta, peço-te, os teus servos dez dias; e que se nos dêem legumes a comer e água a beber.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 13, 'Então se examine na tua presença o nosso semblante e o dos jovens que comem das iguarias reais; e conforme vires procederás para com os teus servos.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 14, 'Assim ele lhes atendeu o pedido, e os experimentou dez dias.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 15, 'E, ao fim dos dez dias, apareceram os seus semblantes melhores, e eles estavam mais gordos do que todos os jovens que comiam das iguarias reais.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 16, 'Pelo que o despenseiro lhes tirou as iguarias e o vinho que deviam beber, e lhes dava legumes.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 17, 'Ora, quanto a estes quatro jovens, Deus lhes deu o conhecimento e a inteligência em todas as letras e em toda a sabedoria; e Daniel era entendido em todas as visões e todos os sonhos.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 18, 'E ao fim dos dias, depois dos quais o rei tinha ordenado que fossem apresentados, o chefe dos eunucos os apresentou diante de Nabucodonosor.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 19, 'Então o rei conversou com eles; e entre todos eles não foram achados outros tais como Daniel, Hananias, Misael e Azarias; por isso ficaram assistindo diante do rei.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 20, 'E em toda matéria de sabedoria e discernimento, a respeito da qual lhes perguntou o rei, este os achou dez vezes mais doutos do que todos os magos e encantadores que havia em todo o seu reino.', 1, CURRENT_TIMESTAMP, false),
(27, 1, 21, 'Assim Daniel continuou até o primeiro ano do rei Ciro.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 1, 'Ora no segundo ano do reinado de Nabucodonosor, teve este uns sonhos; e o seu espírito se perturbou, e passou-se-lhe o sono.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 2, 'Então o rei mandou chamar os magos, os encantadores, os adivinhadores, e os caldeus, para que declarassem ao rei os seus sonhos; eles vieram, pois, e se apresentaram diante do rei.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 3, 'E o rei lhes disse: Tive um sonho, e para saber o sonho está perturbado o meu espírito.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 4, 'Os caldeus disseram ao rei em aramaico: Ó rei, vive eternamente; dize o sonho a teus servos, e daremos a interpretação', 1, CURRENT_TIMESTAMP, false),
(27, 2, 5, 'Respondeu o rei, e disse aos caldeus: Esta minha palavra é irrevogável se não me fizerdes saber o sonho e a sua interpretação, sereis despedaçados, e as vossas casas serão feitas um monturo;', 1, CURRENT_TIMESTAMP, false),
(27, 2, 6, 'mas se vós me declarardes o sonho e a sua interpretação, recebereis de mim dádivas, recompensas e grande honra. Portanto declarai-me o sonho e a sua interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 7, 'Responderam pela segunda vez: Diga o rei o sonho a seus servos, e daremos a interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 8, 'Respondeu o rei, e disse: Bem sei eu que vós quereis ganhar tempo; porque vedes que a minha palavra é irrevogável.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 9, 'se não me fizerdes saber o sonho, uma só sentença será a vossa; pois vós preparastes palavras mentirosas e perversas para as proferirdes na minha presença, até que se mude o tempo. portanto dizei-me o sonho, para que eu saiba que me podeis dar a sua interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 10, 'Responderam os caldeus na presença do rei, e disseram: Não há ninguém sobre a terra que possa cumprir a palavra do rei; pois nenhum rei, por grande e poderoso que fosse, tem exigido coisa semelhante de algum mago ou encantador, ou caldeu.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 11, 'A coisa que o rei requer é difícil, e ninguém há que a possa declarar ao rei, senão os deuses, cuja morada não é com a carne mortal.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 12, 'Então o rei muito se irou e enfureceu, e ordenou que matassem a todos os sábios de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 13, 'saiu, pois, o decreto, segundo o qual deviam ser mortos os sábios; e buscaram a Daniel e aos seus companheiros, para que fossem mortos.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 14, 'Então Daniel falou avisada e prudentemente a Arioque, capitão da guarda do rei, que tinha saído para matar os sábios de Babilônia;', 1, CURRENT_TIMESTAMP, false),
(27, 2, 15, 'pois disse a Arioque, capitão do rei: Por que é o decreto do rei tão urgente? Então Arioque explicou o caso a Daniel.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 16, 'Ao que Daniel se apresentou ao rei e pediu que lhe designasse o prazo, para que desse ao rei a interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 17, 'Então Daniel foi para casa, e fez saber o caso a Hananias, Misael e Azarias, seus companheiros,', 1, CURRENT_TIMESTAMP, false),
(27, 2, 18, 'para que pedissem misericórdia ao Deus do céu sobre este mistério, a fim de que Daniel e seus companheiros não perecessem, juntamente com o resto dos sábios de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 19, 'Então foi revelado o mistério a Daniel numa visão de noite; pelo que Daniel louvou o Deus do céu.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 20, 'Disse Daniel: Seja bendito o nome de Deus para todo o sempre, porque são dele a sabedoria e a força.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 21, 'Ele muda os tempos e as estações; ele remove os reis e estabelece os reis; é ele quem dá a sabedoria aos sábios e o entendimento aos entendidos.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 22, 'Ele revela o profundo e o escondido; conhece o que está em trevas, e com ele mora a luz.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 23, 'Ó Deus de meus pais, a ti dou graças e louvor porque me deste sabedoria e força; e agora me fizeste saber o que te pedimos; pois nos fizeste saber este assunto do rei.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 24, 'Por isso Daniel foi ter com Arioque, ao qual o rei tinha constituído para matar os sábios de Babilônia; entrou, e disse-lhe assim: Não mates os sábios de Babilônia; introduze-me na presença do rei, e lhe darei a interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 25, 'Então Arioque depressa introduziu Daniel à presença do rei, e disse-lhe assim: Achei dentre os filhos dos cativos de Judá um homem que fará saber ao rei a interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 26, 'Respondeu o rei e disse a Daniel, cujo nome era Beltessazar: Podes tu fazer-me saber o sonho que tive e a sua interpretação?', 1, CURRENT_TIMESTAMP, false),
(27, 2, 27, 'Respondeu Daniel na presença do rei e disse: O mistério que o rei exigiu, nem sábios, nem encantadores, nem magos, nem adivinhadores lhe podem revelar;', 1, CURRENT_TIMESTAMP, false),
(27, 2, 28, 'mas há um Deus no céu, o qual revela os mistérios; ele, pois, fez saber ao rei Nabucodonosor o que há de suceder nos últimos dias. O teu sonho e as visões que tiveste na tua cama são estas:', 1, CURRENT_TIMESTAMP, false),
(27, 2, 29, 'Estando tu, ó rei, na tua cama, subiram os teus pensamentos sobre o que havia de suceder no futuro. Aquele, pois, que revela os mistérios te fez saber o que há de ser.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 30, 'E a mim me foi revelado este mistério, não por ter eu mais sabedoria que qualquer outro vivente, mas para que a interpretação se fizesse saber ao rei, e para que entendesses os pensamentos do teu coração.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 31, 'Tu, ó rei, na visão olhaste e eis uma grande estátua. Esta estátua, imensa e de excelente esplendor, estava em pé diante de ti; e a sua aparência era terrível.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 32, 'A cabeça dessa estátua era de ouro fino; o peito e os braços de prata; o ventre e as coxas de bronze;', 1, CURRENT_TIMESTAMP, false),
(27, 2, 33, 'as pernas de ferro; e os pés em parte de ferro e em parte de barro.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 34, 'Estavas vendo isto, quando uma pedra foi cortada, sem auxílio de mãos, a qual feriu a estátua nos pés de ferro e de barro, e os esmiuçou.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 35, 'Então foi juntamente esmiuçado o ferro, o barro, o bronze, a prata e o ouro, os quais se fizeram como a pragana das eiras no estio, e o vento os levou, e não se podia achar nenhum vestígio deles; a pedra, porém, que feriu a estátua se tornou uma grande montanha, e encheu toda a terra.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 36, 'Este é o sonho; agora diremos ao rei a sua interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 37, 'Tu, ó rei, és rei de reis, a quem o Deus do céu tem dado o reino, o poder, a força e a glória;', 1, CURRENT_TIMESTAMP, false),
(27, 2, 38, 'e em cuja mão ele entregou os filhos dos homens, onde quer que habitem, os animais do campo e as aves do céu, e te fez reinar sobre todos eles; tu és a cabeça de ouro.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 39, 'Depois de ti se levantará outro reino, inferior ao teu; e um terceiro reino, de bronze, o qual terá domínio sobre toda a terra.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 40, 'E haverá um quarto reino, forte como ferro, porquanto o ferro esmiúça e quebra tudo; como o ferro quebra todas as coisas, assim ele quebrantará e esmiuçará.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 41, 'Quanto ao que viste dos pés e dos dedos, em parte de barro de oleiro, e em parte de ferro, isso será um reino dividido; contudo haverá nele alguma coisa da firmeza do ferro, pois que viste o ferro misturado com barro de lodo.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 42, 'E como os dedos dos pés eram em parte de ferro e em parte de barro, assim por uma parte o reino será forte, e por outra será frágil.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 43, 'Quanto ao que viste do ferro misturado com barro de lodo, misturar-se-ão pelo casamento; mas não se ligarão um ao outro, assim como o ferro não se mistura com o barro.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 44, 'Mas, nos dias desses reis, o Deus do céu suscitará um reino que não será jamais destruído; nem passará a soberania deste reino a outro povo; mas esmiuçará e consumirá todos esses reinos, e subsistirá para sempre.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 45, 'Porquanto viste que do monte foi cortada uma pedra, sem auxílio de mãos, e ela esmiuçou o ferro, o bronze, o barro, a prata e o ouro, o grande Deus faz saber ao rei o que há de suceder no futuro. Certo é o sonho, e fiel a sua interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 46, 'Então o rei Nabucodonosor caiu com o rosto em terra, e adorou a Daniel, e ordenou que lhe oferecessem uma oblação e perfumes suaves.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 47, 'Respondeu o rei a Daniel, e disse: Verdadeiramente, o vosso Deus é Deus dos deuses, e o Senhor dos reis, e o revelador dos mistérios, pois pudeste revelar este mistério.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 48, 'Então o rei engrandeceu a Daniel, e lhe deu muitas e grandes dádivas, e o pôs por governador sobre toda a província de Babilônia, como também o fez chefe principal de todos os sábios de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(27, 2, 49, 'A pedido de Daniel, o rei constituiu superintendentes sobre os negócios da província de Babilônia a Sadraque, Mesaque e Abednego; mas Daniel permaneceu na corte do rei.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 1, 'O rei Nabucodonosor fez uma estátua de ouro, a altura da qual era de sessenta côvados, e a sua largura de seis côvados; levantou-a no campo de Dura, na província de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 2, 'Então o rei Nabucodonosor mandou ajuntar os sátrapas, os prefeitos, os governadores, os conselheiros, os tesoureiros, os juízes, os magistrados, e todos os oficiais das províncias, para que viessem à dedicação da estátua que ele fizera levantar.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 3, 'Então se ajuntaram os sátrapas, os prefeitos, os governadores, os conselheiros, os tesoureiros, os juízes, os magistrados, e todos os oficiais das províncias, para a dedicação da estátua que o rei Nabucodonosor fizera levantar; e estavam todos em pé diante da imagem.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 4, 'E o pregoeiro clamou em alta voz: Ordena-se a vós, ó povos, nações e gentes de todas as línguas:', 1, CURRENT_TIMESTAMP, false),
(27, 3, 5, 'Logo que ouvirdes o som da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de foles, e de toda a sorte de música, prostrar-vos-eis, e adorareis a imagem de ouro que o rei Nabucodonosor tem levantado.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 6, 'E qualquer que não se prostrar e não a adorar, será na mesma hora lançado dentro duma fornalha de fogo ardente.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 7, 'Portanto, no mesmo instante em que todos os povos ouviram o som da trombeta, da flauta, da harpa, da cítara, do saltério, e de toda a sorte de música, se prostraram todos os povos, nações e línguas, e adoraram a estátua de ouro que o rei Nabucodonosor tinha levantado.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 8, 'Ora, nesse tempo se chegaram alguns homens caldeus, e acusaram os judeus.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 9, 'E disseram ao rei Nabucodonosor: Ó rei, vive eternamente.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 10, 'Tu, ó rei, fizeste um decreto, pelo qual todo homem que ouvisse o som da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de foles, e de toda a sorte de música, se prostraria e adoraria a estátua de ouro;', 1, CURRENT_TIMESTAMP, false),
(27, 3, 11, 'e qualquer que não se prostrasse e adorasse seria lançado numa fornalha de fogo ardente.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 12, 'Há uns homens judeus, que tu constituíste sobre os negócios da província de Babilônia: Sadraque, Mesaque e Abednego; estes homens, ó rei, não fizeram caso de ti; a teus deuses não servem, nem adoram a estátua de ouro que levantaste.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 13, 'Então Nabucodonosor, na sua ira e fúria, mandou chamar Sadraque, Mesaque e Abednego. Logo estes homens foram trazidos perante o rei.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 14, 'Falou Nabucodonosor, e lhes disse: E verdade, ó Sadraque, Mesaque e Abednego, que vós não servis a meus deuses nem adorais a estátua de ouro que levantei?', 1, CURRENT_TIMESTAMP, false),
(27, 3, 15, 'Agora, pois, se estais prontos, quando ouvirdes o som da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de foles, e de toda a sorte de música, para vos prostrardes e adorardes a estátua que fiz, bom é; mas, se não a adorardes, sereis lançados, na mesma hora, dentro duma fornalha de fogo ardente; e quem é esse deus que vos poderá livrar das minhas mãos?', 1, CURRENT_TIMESTAMP, false),
(27, 3, 16, 'Responderam Sadraque, Mesaque e Abednego, e disseram ao rei: Ó Nabucodonosor, não necessitamos de te responder sobre este negócio.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 17, 'Eis que o nosso Deus a quem nós servimos pode nos livrar da fornalha de fogo ardente; e ele nos livrará da tua mão, ó rei.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 18, 'Mas se não, fica sabendo, ó rei, que não serviremos a teus deuses nem adoraremos a estátua de ouro que levantaste.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 19, 'Então Nabucodonosor se encheu de raiva, e se lhe mudou o aspecto do semblante contra Sadraque, Mesaque e Abednego; e deu ordem para que a fornalha se aquecesse sete vezes mais do que se costumava aquecer;', 1, CURRENT_TIMESTAMP, false),
(27, 3, 20, 'e ordenou a uns homens valentes do seu exército, que atassem a Sadraque, Mesaque e Abednego, e os lançassem na fornalha de fogo ardente.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 21, 'Então estes homens foram atados, vestidos de seus mantos, suas túnicas, seus turbantes e demais roupas, e foram lançados na fornalha de fogo ardente.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 22, 'Ora, tão urgente era a ordem do rei e a fornalha estava tão quente, que a chama do fogo matou os homens que carregaram a Sadraque, Mesaque e Abednego.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 23, 'E estes três, Sadraque, Mesaque e Abednego, caíram atados dentro da fornalha de fogo ardente.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 24, 'Então o rei Nabucodonosor se espantou, e se levantou depressa; falou, e disse aos seus conselheiros: Não lançamos nós dentro do fogo três homens atados? Responderam ao rei: É verdade, ó rei.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 25, 'Disse ele: Eu, porém, vejo quatro homens soltos, que andam passeando dentro do fogo, e nenhum dano sofrem; e o aspecto do quarto é semelhante a um filho dos deuses.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 26, 'Então chegando-se Nabucodonosor à porta da fornalha de fogo ardente, falou, dizendo: Sadraque, Mesaque e Abednego, servos do Deus Altíssimo, saí e vinde! Logo Sadraque, Mesaque e Abednego saíram do meio do fogo.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 27, 'E os sátrapas, os prefeitos, os governadores, e os conselheiros do rei, estando reunidos, viram que o fogo não tinha tido poder algum sobre os corpos destes homens, nem foram chamuscados os cabelos da sua cabeça, nem sofreram mudança os seus mantos, nem sobre eles tinha passado o cheiro de fogo.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 28, 'Falou Nabucodonosor, e disse: Bendito seja o Deus de Sadraque, Mesaque e Abednego, o qual enviou o seu anjo e livrou os seus servos, que confiaram nele e frustraram a ordem do rei, escolhendo antes entregar os seus corpos, do que servir ou adorar a deus algum, senão o seu Deus.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 29, 'Por mim, pois, é feito um decreto, que todo o povo, nação e língua que proferir blasfêmia contra o Deus de Sadraque, Mesaque e Abednego, seja despedaçado, e as suas casas sejam feitas um monturo; porquanto não há outro deus que possa livrar desta maneira.', 1, CURRENT_TIMESTAMP, false),
(27, 3, 30, 'Então o rei fez prosperar a Sadraque, Mesaque e Abednego na província de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 1, 'Nabucodonosor rei, a todos os povos, nações, e línguas, que moram em toda a terra: Paz vos seja multiplicada.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 2, 'Pareceu-me bem fazer conhecidos os sinais e maravilhas que Deus, o Altíssimo, tem feito para comigo.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 3, 'Quão grandes são os seus sinais, e quão poderosas as suas maravilhas! O seu reino é um reino sempiterno, e o seu domínio de geração em geração.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 4, 'Eu, Nabucodonosor, estava sossegado em minha casa, e próspero no meu palácio.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 5, 'Tive um sonho que me espantou; e estando eu na minha cama, os pensamentos e as visões da minha cabeça me perturbaram.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 6, 'Portanto expedi um decreto, que fossem introduzidos à minha presença todos os sábios de Babilônia, para que me fizessem saber a interpretação do sonho.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 7, 'Então entraram os magos, os encantadores, os caldeus, e os adivinhadores, e lhes contei o sonho; mas não me fizeram saber a interpretação do mesmo.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 8, 'Por fim entrou na minha presença Daniel, cujo nome é Beltessazar, segundo o nome do meu deus, e no qual há o espírito dos deuses santos; e eu lhe contei o sonho, dizendo:', 1, CURRENT_TIMESTAMP, false),
(27, 4, 9, 'Ó Beltessazar, chefe dos magos, porquanto eu sei que há em ti o espírito dos deuses santos, e nenhum mistério te é difícil, dize-me as visões do meu sonho que tive e a sua interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 10, 'Eram assim as visões da minha cabeça, estando eu na minha cama: eu olhava, e eis uma árvore no meio da terra, e grande era a sua altura;', 1, CURRENT_TIMESTAMP, false),
(27, 4, 11, 'crescia a árvore, e se fazia forte, de maneira que a sua altura chegava até o céu, e era vista até os confins da terra.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 12, 'A sua folhagem era formosa, e o seu fruto abundante, e havia nela sustento para todos; debaixo dela os animais do campo achavam sombra, e as aves do céu faziam morada nos seus ramos, e dela se mantinha toda a carne.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 13, 'Eu via isso nas visões da minha cabeça, estando eu na minha cama, e eis que um vigia, um santo, descia do céu.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 14, 'Ele clamou em alta voz e disse assim: Derrubai a árvore, e cortai-lhe os ramos, sacudi as suas folhas e espalhai o seu fruto; afugentem-se os animais de debaixo dela, e as aves dos seus ramos.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 15, 'Contudo deixai na terra o tronco com as suas raízes, numa cinta de ferro e de bronze, no meio da tenra relva do campo; e seja molhado do orvalho do céu, e seja a sua porção com os animais na erva da terra.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 16, 'Seja mudada a sua mente, para que não seja mais a de homem, e lhe seja dada mente de animal; e passem sobre ele sete tempos.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 17, 'Esta sentença é por decreto dos vigias, e por mandado dos santos; a fim de que conheçam os viventes que o Altíssimo tem domínio sobre o reino dos homens, e o dá a quem quer, e até o mais humilde dos homens constitui sobre eles.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 18, 'Este sonho eu, rei Nabucodonosor, o vi. Tu, pois, Beltessazar, dize a interpretação; porquanto todos os sábios do meu reino não puderam fazer-me saber a interpretação; mas tu podes; pois há em ti o espírito dos deuses santos.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 19, 'Então Daniel, cujo nome era Beltessazar, esteve atônito por algum tempo, e os seus pensamentos o perturbaram. Falou, pois, o rei e disse: Beltessazar, não te espante o sonho, nem a sua interpretação. Respondeu Beltessazar, e disse: Senhor meu, seja o sonho para os que te odeiam, e a sua interpretação para os teus inimigos:', 1, CURRENT_TIMESTAMP, false),
(27, 4, 20, 'A árvore que viste, que cresceu, e se fez forte, cuja altura chegava até o céu, e que era vista por toda a terra;', 1, CURRENT_TIMESTAMP, false),
(27, 4, 21, 'cujas folhas eram formosas, e o seu fruto abundante, e em que para todos havia sustento, debaixo da qual os animais do campo achavam sombra, e em cujos ramos habitavam as aves do céu;', 1, CURRENT_TIMESTAMP, false),
(27, 4, 22, 'és ,tu, ó rei, que cresceste, e te fizeste forte; pois a tua grandeza cresceu, e chegou até o céu, e o teu domínio até a extremidade da terra.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 23, 'E quanto ao que viu o rei, um vigia, um santo, que descia do céu, e que dizia: Cortai a árvore, e destruí-a; contudo deixai na terra o tronco com as suas raízes, numa cinta de ferro e de bronze, no meio da tenra relva do campo; e seja molhado do orvalho do céu, e seja a sua porção com os animais do campo, até que passem sobre ele sete tempos;', 1, CURRENT_TIMESTAMP, false),
(27, 4, 24, 'esta é a interpretação, ó rei é o decreto do Altíssimo, que é vindo sobre o rei, meu senhor:', 1, CURRENT_TIMESTAMP, false),
(27, 4, 25, 'serás expulso do meio dos homens, e a tua morada será com os animais do campo, e te farão comer erva como os bois, e serás molhado do orvalho do céu, e passar-se-ão sete tempos por cima de ti; até que conheças que o Altíssimo tem domínio sobre o reino dos homens, e o dá a quem quer.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 26, 'E quanto ao que foi dito, que deixassem o tronco com as raízes da árvore, o teu reino voltará para ti, depois que tiveres conhecido que o céu reina.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 27, 'Portanto, ó rei, aceita o meu conselho, e põe fim aos teus pecados, praticando a justiça, e às tuas iniqüidades, usando de misericórdia com os pobres, se, porventura, se prolongar a tua tranqüilidade.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 28, 'Tudo isso veio sobre o rei Nabucodonosor.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 29, 'Ao cabo de doze meses, quando passeava sobre o palácio real de Babilônia,', 1, CURRENT_TIMESTAMP, false),
(27, 4, 30, 'falou o rei, e disse: Não é esta a grande Babilônia que eu edifiquei para a morada real, pela força do meu poder, e para a glória da minha majestade?', 1, CURRENT_TIMESTAMP, false),
(27, 4, 31, 'Ainda estava a palavra na boca do rei, quando caiu uma voz do céu: A ti se diz, ó rei Nabucodonosor: Passou de ti o reino.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 32, 'E serás expulso do meio dos homens, e a tua morada será com os animais do campo; far-te-ão comer erva como os bois, e passar-se-ão sete tempos sobre ti, até que conheças que o Altíssimo tem domínio sobre o reino dos homens, e o dá a quem quer.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 33, 'Na mesma hora a palavra se cumpriu sobre Nabucodonosor, e foi expulso do meio dos homens, e comia erva como os bois, e o seu corpo foi molhado do orvalho do céu, até que lhe cresceu o cabelo como as penas da águia, e as suas unhas como as das aves:', 1, CURRENT_TIMESTAMP, false),
(27, 4, 34, 'Mas ao fim daqueles dias eu, Nabucodonosor, levantei ao céu os meus olhos, e voltou a mim o meu entendimento, e eu bendisse o Altíssimo, e louvei, e glorifiquei ao que vive para sempre; porque o seu domínio é um domínio sempiterno, e o seu reino é de geração em geração.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 35, 'E todos os moradores da terra são reputados em nada; e segundo a sua vontade ele opera no exército do céu e entre os moradores da terra; não há quem lhe possa deter a mão, nem lhe dizer: Que fazes?', 1, CURRENT_TIMESTAMP, false),
(27, 4, 36, 'No mesmo tempo voltou a mim o meu entendimento; e para a glória do meu reino voltou a mim a minha majestade e o meu resplendor. Buscaram-me os meus conselheiros e os meus grandes; e fui restabelecido no meu reino, e foi-me acrescentada excelente grandeza.', 1, CURRENT_TIMESTAMP, false),
(27, 4, 37, 'Agora, pois, eu, Nabucodonosor, louvo, e exalço, e glorifico ao Rei do céu; porque todas as suas obras são retas, e os seus caminhos justos, e ele pode humilhar aos que andam na soberba.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 1, 'O rei Belsazar deu um grande banquete a mil dos seus grandes, e bebeu vinho na presença dos mil.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 2, 'Havendo Belsazar provado o vinho, mandou trazer os vasos de ouro e de prata que Nabucodonosor, seu pai, tinha tirado do templo que estava em Jerusalém, para que bebessem por eles o rei, e os seus grandes, as suas mulheres e concubinas.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 3, 'Então trouxeram os vasos de ouro que foram tirados do templo da casa de Deus, que estava em Jerusalém, e beberam por eles o rei, os seus grandes, as suas mulheres e concubinas.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 4, 'Beberam vinho, e deram louvores aos deuses de ouro, e de prata, de bronze, de ferro, de madeira, e de pedra.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 5, 'Na mesma hora apareceram uns dedos de mão de homem, e escreviam, defronte do castiçal, na caiadura da parede do palácio real; e o rei via a parte da mão que estava escrevendo.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 6, 'Mudou-se, então, o semblante do rei, e os seus pensamentos o perturbaram; as juntas dos seus lombos se relaxaram, e os seus joelhos batiam um no outro.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 7, 'E ordenou o rei em alta voz, que se introduzissem os encantadores, os caldeus e os adivinhadores; e falou o rei, e disse aos sábios de Babilônia: Qualquer que ler esta escritura, e me declarar a sua interpretação, será vestido de púrpura, e trará uma cadeia de ouro ao pescoço, e no reino será o terceiro governante.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 8, 'Então entraram todos os sábios do rei; mas não puderam ler o escrito, nem fazer saber ao rei a sua interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 9, 'Nisto ficou o rei Belsazar muito perturbado, e se lhe mudou o semblante; e os seus grandes estavam perplexos.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 10, 'Ora a rainha, por causa das palavras do rei e dos seus grandes, entrou na casa do banquete; e a rainha disse: Ó rei, vive para sempre; não te perturbem os teus pensamentos, nem se mude o teu semblante.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 11, 'Há no teu reino um homem que tem o espírito dos deuses santos; e nos dias de teu pai se achou nele luz, e inteligência, e sabedoria, como a sabedoria dos deuses; e teu pai, o rei Nabucodonosor, sim, teu pai, ó rei, o constituiu chefe dos magos, dos encantadores, dos caldeus, e dos adivinhadores;', 1, CURRENT_TIMESTAMP, false),
(27, 5, 12, 'porquanto se achou neste Daniel um espírito excelente, e conhecimento e entendimento para interpretar sonhos, explicar enigmas e resolver dúvidas, ao qual o rei pôs o nome de Beltessazar. Chame-se, pois, agora Daniel, e ele dará a interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 13, 'Então Daniel foi introduzido à presença do rei. Falou o rei, e disse à Daniel: És tu aquele Daniel, um dos cativos de Judá, que o rei, meu pai, trouxe de Judá?', 1, CURRENT_TIMESTAMP, false),
(27, 5, 14, 'Tenho ouvido dizer a teu respeito que o espírito dos deuses está em ti, e que em ti se acham a luz, o entendimento e a excelente sabedoria.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 15, 'Acabam de ser introduzidos à minha presença os sábios, os encantadores, para lerem o escrito, e me fazerem saber a sua interpretação; mas não puderam dar a interpretação destas palavras.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 16, 'Ouvi dizer, porém, a teu respeito que podes dar interpretações e resolver dúvidas. Agora, pois, se puderes ler esta escritura e fazer-me saber a sua interpretação, serás vestido de púrpura, e terás cadeia de ouro ao pescoço, e no reino serás o terceiro governante.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 17, 'Então respondeu Daniel, e disse na presença do rei: Os teus presentes fiquem contigo, e dá os teus prêmios a outro; todavia vou ler ao rei o escrito, e lhe farei saber a interpretação.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 18, 'O Altíssimo Deus, ó rei, deu a Nabucodonosor, teu pai, o reino e a grandeza, glória e majestade;', 1, CURRENT_TIMESTAMP, false),
(27, 5, 19, 'e por causa da grandeza que lhe deu, todos os povos, nações, e línguas tremiam e temiam diante dele; a quem queria matava, e a quem queria conservava em vida; a quem queria exaltava, e a quem queria abatia.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 20, 'Mas quando o seu coração se elevou, e o seu espírito se endureceu para se haver arrogantemente, foi derrubado do seu trono real, e passou dele a sua glória.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 21, 'E foi expulso do meio dos filhos dos homens, e o seu coração foi feito semelhante aos dos animais, e a sua morada foi com os jumentos monteses; deram-lhe a comer erva como aos bois, e do orvalho do céu foi molhado o seu corpo, até que conheceu que o Altíssimo Deus tem domínio sobre o reino dos homens, e a quem quer constitui sobre ele.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 22, 'E tu, Belsazar, que és seu filho, não humilhaste o teu coração, ainda que soubeste tudo isso;', 1, CURRENT_TIMESTAMP, false),
(27, 5, 23, 'porém te elevaste contra o Senhor do céu; pois foram trazidos a tua presença os vasos da casa dele, e tu, os teus grandes, as tua mulheres e as tuas concubinas, bebestes vinho neles; além disso, deste louvores aos deuses de prata, de ouro, de bronze, de ferro, de madeira e de pedra, que não vêem, não ouvem, nem sabem; mas a Deus, em cuja mão está a tua vida, e de quem são todos os teus caminhos, a ele não glorificaste.:', 1, CURRENT_TIMESTAMP, false),
(27, 5, 24, 'Então dele foi enviada aquela parte da mão que traçou o escrito.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 25, 'Esta, pois, é a escritura que foi traçada: MENE, MENE, TEQUEL, UFARSlM.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 26, 'Esta é a interpretação daquilo: MENE: Contou Deus o teu reino, e o acabou.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 27, 'TEQUEL: Pesado foste na balança, e foste achado em falta.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 28, 'PERES: Dividido está o teu reino, e entregue aos medos e persas.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 29, 'Então Belsazar deu ordem, e vestiram a Daniel de púrpura, puseram-lhe uma cadeia de ouro ao pescoço, e proclamaram a respeito dele que seria o terceiro em autoridade no reino.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 30, 'Naquela mesma noite Belsazar, o rei dos caldeus, foi morto.', 1, CURRENT_TIMESTAMP, false),
(27, 5, 31, 'E Dario, o medo, recebeu o reino, tendo cerca de sessenta e dois anos de idade.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 1, 'Pareceu bem a Dario constituir sobre o reino cento e vinte sátrapas, que estivessem por todo o reino;', 1, CURRENT_TIMESTAMP, false),
(27, 6, 2, 'e sobre eles três presidentes, dos quais Daniel era um; a fim de que estes sátrapas lhes dessem conta, e que o rei não sofresse dano.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 3, 'Então o mesmo Daniel sobrepujava a estes presidentes e aos sátrapas; porque nele havia um espírito excelente; e o rei pensava constituí-lo sobre todo o reino:', 1, CURRENT_TIMESTAMP, false),
(27, 6, 4, 'Nisso os presidentes e os sátrapas procuravam achar ocasião contra Daniel a respeito do reino mas não podiam achar ocasião ou falta alguma; porque ele era fiel, e não se achava nele nenhum erro nem falta.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 5, 'Pelo que estes homens disseram: Nunca acharemos ocasião alguma contra este Daniel, a menos que a procuremos no que diz respeito a lei do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 6, 'Então os presidentes e os sátrapas foram juntos ao rei, e disseram-lhe assim: Ó rei Dario, vive para sempre.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 7, 'Todos os presidentes do reino, os prefeitos e os sátrapas, os conselheiros e os governadores, concordaram em que o rei devia baixar um decreto e publicar o respectivo interdito, que qualquer que, por espaço de trinta dias, fizer uma petição a qualquer deus, ou a qualquer homem, exceto a ti, ó rei, seja lançado na cova dos leões.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 8, 'Agora pois, ó rei, estabelece o interdito, e assina o edital, para que não seja mudado, conforme a lei dos medos e dos persas, que não se pode revogar.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 9, 'Em virtude disto o rei Dario assinou o edital e o interdito.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 10, 'Quando Daniel soube que o edital estava assinado, entrou em sua casa, no seu quarto em cima, onde estavam abertas as janelas que davam para o lado de Jerusalém; e três vezes no dia se punha de joelhos e orava, e dava graças diante do seu Deus, como também antes costumava fazer.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 11, 'Então aqueles homens foram juntos, e acharam a Daniel orando e suplicando diante do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 12, 'Depois se foram à presença do rei e lhe perguntaram no tocante ao interdito real: Porventura não assinaste um interdito pelo qual todo homem que fizesse uma petição a qualquer deus, ou a qualquer homem por espaço de trinta dias, exceto a ti, ó rei, fosse lançado na cova dos leões? Respondeu o rei, e disse: Esta palavra é certa, conforme a lei dos medos e dos persas, que não se pode revogar.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 13, 'Então responderam ao rei, dizendo-lhe Esse Daniel, que é dos exilados de Judá, e não tem feito caso de ti, ó rei, nem do interdito que assinaste; antes três vezes por dia faz a sua oração.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 14, 'Ouvindo então o rei a notícia, ficou muito penalizado, e a favor de Daniel propôs dentro do seu coração livrá-lo; e até o pôr do sol trabalhou para o salvar.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 15, 'Nisso aqueles homens foram juntos ao rei, e lhe disseram: Sabe, ó rei, que é lei dos medos e persas que nenhum interdito ou decreto que o rei estabelecer, se pode mudar.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 16, 'Então o rei deu ordem, e trouxeram Daniel, e o lançaram na cova dos leões. Ora, disse o rei a Daniel: O teu Deus, a quem tu continuamente serves, ele te livrará.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 17, 'E uma pedra foi trazida e posta sobre a boca da cova; e o rei a selou com o seu anel e com o anel dos seus grandes, para que no tocante a Daniel nada se mudasse:', 1, CURRENT_TIMESTAMP, false),
(27, 6, 18, 'Depois o rei se dirigiu para o seu palácio, e passou a noite em jejum; e não foram trazidos à sua presença instrumentos de música, e fugiu dele o sono.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 19, 'Então o rei se levantou ao romper do dia, e foi com pressa à cova dos leões.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 20, 'E, chegando-se à cova, chamou por Daniel com voz triste; e disse o rei a Daniel: Ó Daniel, servo do Deus vivo, dar-se-ia o caso que o teu Deus, a quem tu continuamente serves, tenha podido livrar-te dos leões?', 1, CURRENT_TIMESTAMP, false),
(27, 6, 21, 'Então Daniel falou ao rei: Ó rei, vive para sempre.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 22, 'O meu Deus enviou o seu anjo, e fechou a boca dos leões, e eles não me fizeram mal algum; porque foi achada em mim inocência diante dele; e também diante de ti, ó rei, não tenho cometido delito algum.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 23, 'Então o rei muito se alegrou, e mandou tirar a Daniel da cova. Assim foi tirado Daniel da cova, e não se achou nele lesão alguma, porque ele havia confiado em seu Deus.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 24, 'E o rei deu ordem, e foram trazidos aqueles homens que tinham acusado Daniel, e foram lançados na cova dos leões, eles, seus filhos e suas mulheres; e ainda não tinham chegado ao fundo da cova quando os leões se apoderaram deles, e lhes esmigalharam todos os ossos.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 25, 'Então o rei Dario escreveu a todos os povos, nações e línguas que moram em toda a terra: Paz vos seja multiplicada.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 26, 'Com isto faço um decreto, pelo qual em todo o domínio do meu reino os homens tremam e temam perante o Deus de Daniel; porque ele é o Deus vivo, e permanece para sempre; e o seu reino nunca será destruído; o seu domínio durará até o fim.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 27, 'Ele livra e salva, e opera sinais e maravilhas no céu e na terra; foi ele quem livrou Daniel do poder dos leões.', 1, CURRENT_TIMESTAMP, false),
(27, 6, 28, 'Este Daniel, pois, prosperou no reinado de Dario, e no reinado de Ciro, o persa.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 1, 'No primeiro ano de Belsazar, rei de Babilônia, teve Daniel, na sua cama, um sonho e visões da sua cabeça. Então escreveu o sonho, e relatou a suma das coisas.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 2, 'Falou Daniel, e disse: Eu estava olhando, numa visão noturna, e eis que os quatro ventos do céu agitavam o Mar Grande.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 3, 'E quatro grandes animais, diferentes uns dos outros, subiam do mar.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 4, 'O primeiro era como leão, e tinha asas de águia; enquanto eu olhava, foram-lhe arrancadas as asas, e foi levantado da terra, e posto em dois pés como um homem; e foi-lhe dado um coração de homem.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 5, 'Continuei olhando, e eis aqui o segundo animal, semelhante a um urso, o qual se levantou de um lado, tendo na boca três costelas entre os seus dentes; e foi-lhe dito assim: Levanta-te, devora muita carne.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 6, 'Depois disto, continuei olhando, e eis aqui outro, semelhante a um leopardo, e tinha nas costas quatro asas de ave; tinha também este animal quatro cabeças; e foi-lhe dado domínio.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 7, 'Depois disto, eu continuava olhando, em visões noturnas, e eis aqui o quarto animal, terrível e espantoso, e muito forte, o qual tinha grandes dentes de ferro; ele devorava e fazia em pedaços, e pisava aos pés o que sobejava; era diferente de todos os animais que apareceram antes dele, e tinha dez chifres.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 8, 'Eu considerava os chifres, e eis que entre eles subiu outro chifre, pequeno, diante do qual três dos primeiros chifres foram arrancados; e eis que neste chifre havia olhos, como os de homem, e uma boca que falava grandes coisas.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 9, 'Eu continuei olhando, até que foram postos uns tronos, e um ancião de dias se assentou; o seu vestido era branco como a neve, e o cabelo da sua cabeça como lã puríssima; o seu trono era de chamas de fogo, e as rodas dele eram fogo ardente.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 10, 'Um rio de fogo manava e saía de diante dele; milhares de milhares o serviam, e miríades de miríades assistiam diante dele. Assentou-se para o juízo, e os livros foram abertos.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 11, 'Então estive olhando, por causa da voz das grandes palavras que o chifre proferia; estive olhando até que o animal foi morto, e o seu corpo destruído; pois ele foi entregue para ser queimado pelo fogo.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 12, 'Quanto aos outros animais, foi-lhes tirado o domínio; todavia foi-lhes concedida prolongação de vida por um prazo e mais um tempo.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 13, 'Eu estava olhando nas minhas visões noturnas, e eis que vinha com as nuvens do céu um como filho de homem; e dirigiu-se ao ancião de dias, e foi apresentado diante dele.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 14, 'E foi-lhe dado domínio, e glória, e um reino, para que todos os povos, nações e línguas o servissem; o seu domínio é um domínio eterno, que não passará, e o seu reino tal, que não será destruído.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 15, 'Quanto a mim, Daniel, o meu espírito foi abatido dentro do corpo, e as visões da minha cabeça me perturbavam.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 16, 'Cheguei-me a um dos que estavam perto, e perguntei-lhe a verdadeira significação de tudo isso. Ele me respondeu e me fez saber a interpretação das coisas.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 17, 'Estes grandes animais, que são quatro, são quatro reis, que se levantarão da terra.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 18, 'Mas os santos do Altíssimo receberão o reino e o possuirão para todo o sempre, sim, para todo o sempre.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 19, 'Então tive desejo de conhecer a verdade a respeito do quarto animal, que era diferente de todos os outros, sobremodo terrível, com dentes de ferro e unhas de bronze; o qual devorava, fazia em pedaços, e pisava aos pés o que sobrava;', 1, CURRENT_TIMESTAMP, false),
(27, 7, 20, 'e também a respeito dos dez chifres que ele tinha na cabeça, e do outro que subiu e diante do qual caíram três, isto é, daquele chifre que tinha olhos, e uma boca que falava grandes coisas, e parecia ser mais robusto do que os seus companheiros.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 21, 'Enquanto eu olhava, eis que o mesmo chifre fazia guerra contra os santos, e prevalecia contra eles,', 1, CURRENT_TIMESTAMP, false),
(27, 7, 22, 'até que veio o ancião de dias, e foi executado o juízo a favor dos santos do Altíssimo; e chegou o tempo em que os santos possuíram o reino.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 23, 'Assim me disse ele: O quarto animal será um quarto reino na terra, o qual será diferente de todos os reinos; devorará toda a terra, e a pisará aos pés, e a fará em pedaços.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 24, 'Quanto aos dez chifres, daquele mesmo reino se levantarão dez reis; e depois deles se levantará outro, o qual será diferente dos primeiros, e abaterá a três reis.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 25, 'Proferirá palavras contra o Altíssimo, e consumirá os santos do Altíssimo; cuidará em mudar os tempos e a lei; os santos lhe serão entregues na mão por um tempo, e tempos, e metade de um tempo.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 26, 'Mas o tribunal se assentará em juízo, e lhe tirará o domínio, para o destruir e para o desfazer até o fim.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 27, 'O reino, e o domínio, e a grandeza dos reinos debaixo de todo o céu serão dados ao povo dos santos do Altíssimo. O seu reino será um reino eterno, e todos os domínios o servirão, e lhe obedecerão.', 1, CURRENT_TIMESTAMP, false),
(27, 7, 28, 'Aqui é o fim do assunto. Quanto a mim, Daniel, os meus pensamentos muito me perturbaram e o meu semblante se mudou; mas guardei estas coisas no coração.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 1, 'No ano terceiro do reinado do rei Belsazar apareceu-me uma visão, a mim, Daniel, depois daquela que me apareceu no princípio.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 2, 'E na visão que tive, parecia-me que eu estava na cidadela de Susã, na província de Elão; e conforme a visão, eu estava junto ao rio Ulai.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 3, 'Levantei os olhos, e olhei, e eis que estava em pé diante do rio um carneiro, que tinha dois chifres; e os dois chifres eram altos; mas um era mais alto do que o outro, e o mais alto subiu por último.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 4, 'Vi que o carneiro dava marradas para o ocidente, e para o norte e para o sul; e nenhum dos animais lhe podia resistir, nem havia quem pudesse livrar-se do seu poder; ele, porém, fazia conforme a sua vontade, e se engrandecia.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 5, 'E, estando eu considerando, eis que um bode vinha do ocidente sobre a face de toda a terra, mas sem tocar no chão; e aquele bode tinha um chifre notável entre os olhos.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 6, 'E dirigiu-se ao carneiro que tinha os dois chifres, ao qual eu tinha visto em pé diante do rio, e correu contra ele no furor da sua força.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 7, 'Vi-o chegar perto do carneiro; e, movido de cólera contra ele, o feriu, e lhe quebrou os dois chifres; não havia força no carneiro para lhe resistir, e o bode o lançou por terra, e o pisou aos pés; também não havia quem pudesse livrar o carneiro do seu poder.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 8, 'O bode, pois, se engrandeceu sobremaneira; e estando ele forte, aquele grande chifre foi quebrado, e no seu lugar outros quatro também notáveis nasceram para os quatro ventos do céu.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 9, 'Ainda de um deles saiu um chifre pequeno, o qual cresceu muito para o sul, e para o oriente, e para a terra formosa;', 1, CURRENT_TIMESTAMP, false),
(27, 8, 10, 'e se engrandeceu até o exército do céu; e lançou por terra algumas das estrelas desse exército, e as pisou.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 11, 'Sim, ele se engrandeceu até o príncipe do exército; e lhe tirou o holocausto contínuo, e o lugar do seu santuário foi deitado abaixo.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 12, 'E o exército lhe foi entregue, juntamente com o holocausto contínuo, por causa da transgressão; lançou a verdade por terra; e fez o que era do seu agrado, e prosperou.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 13, 'Depois ouvi um santo que falava; e disse outro santo àquele que falava: Até quando durará a visão relativamente ao holocausto contínuo e à transgressão assoladora, e à entrega do santuário e do exército, para serem pisados?', 1, CURRENT_TIMESTAMP, false),
(27, 8, 14, 'Ele me respondeu: Até duas mil e trezentas tardes e manhãs; então o santuário será purificado.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 15, 'Havendo eu, Daniel, tido a visão, procurei entendê-la, e eis que se me apresentou como que uma semelhança de homem.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 16, 'E ouvi uma voz de homem entre as margens do Ulai, a qual gritou, e disse: Gabriel, faze que este homem entenda a visão.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 17, 'Veio, pois, perto de onde eu estava; e vindo ele, fiquei amedrontado, e caí com o rosto em terra. Mas ele me disse: Entende, filho do homem, pois esta visão se refere ao tempo do fim.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 18, 'Ora, enquanto ele falava comigo, caí num profundo sono, com o rosto em terra; ele, porém, me tocou, e me pôs em pé.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 19, 'e disse: Eis que te farei saber o que há de acontecer no último tempo da ira; pois isso pertence ao determinado tempo do fim.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 20, 'Aquele carneiro que viste, o qual tinha dois chifres, são estes os reis da Média e da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 21, 'Mas o bode peludo é o rei da Grécia; e o grande chifre que tinha entre os olhos é o primeiro rei.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 22, 'O ter sido quebrado, levantando-se quatro em lugar dele, significa que quatro reinos se levantarão da mesma nação, porém não com a força dele.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 23, 'Mas, no fim do reinado deles, quando os transgressores tiverem chegado ao cúmulo, levantar-se-á um rei, feroz de semblante e que entende enigmas.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 24, 'Grande será o seu poder, mas não de si mesmo; e destruirá terrivelmente, e prosperará, e fará o que lhe aprouver; e destruirá os poderosos e o povo santo.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 25, 'Pela sua sutileza fará prosperar o engano na sua mão; no seu coração se engrandecerá, e destruirá a muitos que vivem em segurança; e se levantará contra o príncipe dos príncipes; mas será quebrado sem intervir mão de homem.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 26, 'E a visão da tarde e da manhã, que foi dita, é verdadeira. Tu, porém, cerra a visão, porque se refere a dias mui distantes.', 1, CURRENT_TIMESTAMP, false),
(27, 8, 27, 'E eu, Daniel, desmaiei, e estive enfermo alguns dias; então me levantei e tratei dos negócios do rei. E espantei-me acerca da visão, pois não havia quem a entendesse.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 1, 'No ano primeiro de Dario, filho de Assuero, da linhagem dos medos, o qual foi constituído rei sobre o reino dos caldeus.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 2, 'no ano primeiro do seu reinado, eu, Daniel, entendi pelos livros que o número de anos, de que falara o Senhor ao profeta Jeremias, que haviam de durar as desolações de Jerusalém, era de setenta anos.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 3, 'Eu, pois, dirigi o meu rosto ao Senhor Deus, para o buscar com oração e súplicas, com jejum, e saco e cinza.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 4, 'E orei ao Senhor meu Deus, e confessei, e disse: Ó Senhor, Deus grande e tremendo, que guardas o pacto e a misericórdia para com os que te amam e guardam os teus mandamentos;', 1, CURRENT_TIMESTAMP, false),
(27, 9, 5, 'pecamos e cometemos iniqüidades, procedemos impiamente, e fomos rebeldes, apartando-nos dos teus preceitos e das tuas ordenanças.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 6, 'Não demos ouvidos aos teus servos, os profetas, que em teu nome falaram aos nossos reis, nossos príncipes, e nossos pais, como também a todo o povo da terra.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 7, 'A ti, ó Senhor, pertence a justiça, porém a nós a confusão de rosto, como hoje se vê; aos homens de Judá, e aos moradores de Jerusalém, e a todo o Israel; aos de perto e aos de longe, em todas as terras para onde os tens lançado por causa das suas transgressões que cometeram contra ti.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 8, 'Ó Senhor, a nós pertence a confusão de rosto, aos nossos reis, aos nossos príncipes, e a nossos pais, porque temos pecado contra ti.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 9, 'Ao Senhor, nosso Deus, pertencem a misericórdia e o perdão; pois nos rebelamos contra ele,', 1, CURRENT_TIMESTAMP, false),
(27, 9, 10, 'e não temos obedecido à voz do Senhor, nosso Deus, para andarmos nas suas leis, que nos deu por intermédio de seus servos, os profetas.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 11, 'Sim, todo o Israel tem transgredido a tua lei, desviando-se, para não obedecer à tua voz; por isso a maldição, o juramento que está escrito na lei de Moisés, servo de Deus, se derramou sobre nós; porque pecamos contra ele.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 12, 'E ele confirmou a sua palavra, que falou contra nós, e contra os nossos juízes que nos julgavam, trazendo sobre nós um grande mal; porquanto debaixo de todo o céu nunca se fez como se tem feito a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 13, 'Como está escrito na lei de Moisés, todo este mal nos sobreveio; apesar disso, não temos implorado o favor do Senhor nosso Deus, para nos convertermos das nossas iniqüidades, e para alcançarmos discernimento na tua verdade.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 14, 'por isso, o Senhor vigiou sobre o mal, e o trouxe sobre nós; pois justo é o Senhor, nosso Deus, em todas as obras que faz; e nós não temos obedecido à sua voz.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 15, 'Na verdade, ó Senhor, nosso Deus, que tiraste o teu povo da terra do Egito com mão poderosa, e te adquiriste nome como hoje se vê, temos pecado, temos procedido impiamente.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 16, 'e Senhor, segundo todas as tuas justiças, apartem-se a tua ira e o teu furor da tua cidade de Jerusalém, do teu santo monte; porquanto por causa dos nossos pecados, e por causa das iniqüidades de nossos pais, tornou-se Jerusalém e o teu povo um opróbrio para todos os que estão em redor de nós.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 17, 'Agora, pois, ó Deus nosso, ouve a oração do teu servo, e as suas súplicas, e sobre o teu santuário assolado faze resplandecer o teu rosto, por amor do Senhor.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 18, 'Inclina, ó Deus meu, os teus ouvidos, e ouve; abre os teus olhos, e olha para a nossa desolação, e para a cidade que é chamada pelo teu nome; pois não lançamos as nossas súplicas perante a tua face fiados em nossas justiças, mas em tuas muitas misericórdias.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 19, 'Ó Senhor, ouve; ó Senhor, perdoa; ó Senhor, atende-nos e põe mãos à obra sem tardar, por amor de ti mesmo, ó Deus meu, porque a tua cidade e o teu povo se chamam pelo teu nome.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 20, 'Enquanto estava eu ainda falando e orando, e confessando o meu pecado, e o pecado do meu povo Israel, e lançando a minha súplica perante a face do Senhor, meu Deus, pelo monte santo do meu Deus,', 1, CURRENT_TIMESTAMP, false),
(27, 9, 21, 'sim enquanto estava eu ainda falando na oração, o varão Gabriel, que eu tinha visto na minha visão ao princípio, veio voando rapidamente, e tocou-me à hora da oblação da tarde.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 22, 'Ele me instruiu, e falou comigo, dizendo: Daniel, vim agora para fazer-te sábio e entendido.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 23, 'No princípio das tuas súplicas, saiu a ordem, e eu vim, para to declarar, pois és muito amado; considera, pois, a palavra e entende a visão.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 24, 'Setenta semanas estão decretadas sobre o teu povo, e sobre a tua santa cidade, para fazer cessar a transgressão, para dar fim aos pecados, e para expiar a iniqüidade, e trazer a justiça eterna, e selar a visão e a profecia, e para ungir o santíssimo.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 25, 'Sabe e entende: desde a saída da ordem para restaurar e para edificar Jerusalém até o ungido, o príncipe, haverá sete semanas, e sessenta e duas semanas; com praças e tranqueiras se reedificará, mas em tempos angustiosos.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 26, 'E depois de sessenta e duas semanas será cortado o ungido, e nada lhe subsistirá; e o povo do príncipe que há de vir destruirá a cidade e o santuário, e o seu fim será com uma inundação; e até o fim haverá guerra; estão determinadas assolações.', 1, CURRENT_TIMESTAMP, false),
(27, 9, 27, 'E ele fará um pacto firme com muitos por uma semana; e na metade da semana fará cessar o sacrifício e a oblação; e sobre a asa das abominações virá o assolador; e até a destruição determinada, a qual será derramada sobre o assolador.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 1, 'No ano terceiro de Ciro, rei da Pérsia, foi revelada uma palavra a Daniel, cujo nome se chama Beltessazar, uma palavra verdadeira concernente a um grande conflito; e ele entendeu esta palavra, e teve entendimento da visão.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 2, 'Naqueles dias eu, Daniel, estava pranteando por três semanas inteiras.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 3, 'Nenhuma coisa desejável comi, nem carne nem vinho entraram na minha boca, nem me ungi com ungüento, até que se cumpriram as três semanas completas.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 4, 'No dia vinte e quatro do primeiro mês, estava eu à borda do grande rio, o Tigre;', 1, CURRENT_TIMESTAMP, false),
(27, 10, 5, 'levantei os meus olhos, e olhei, e eis um homem vestido de linho e os seus lombos cingidos com ouro fino de Ufaz;', 1, CURRENT_TIMESTAMP, false),
(27, 10, 6, 'o seu corpo era como o berilo, e o seu rosto como um relâmpago; os seus olhos eram como tochas de fogo, e os seus braços e os seus pés como o brilho de bronze polido; e a voz das suas palavras como a voz duma multidão.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 7, 'Ora, só eu, Daniel, vi aquela visão; pois os homens que estavam comigo não a viram: não obstante, caiu sobre eles um grande temor, e fugiram para se esconder.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 8, 'Fiquei pois eu só a contemplar a grande visão, e não ficou força em mim; desfigurou-se a feição do meu rosto, e não retive força alguma.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 9, 'Contudo, ouvi a voz das suas palavras; e, ouvindo o som das suas palavras, eu caí num profundo sono, com o rosto em terra.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 10, 'E eis que uma mão me tocou, e fez com que me levantasse, tremendo, sobre os meus joelhos e sobre as palmas das minhas mãos.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 11, 'E me disse: Daniel, homem muito amado, entende as palavras que te vou dizer, e levanta-te sobre os teus pés; pois agora te sou enviado. Ao falar ele comigo esta palavra, pus-me em pé tremendo.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 12, 'Então me disse: Não temas, Daniel; porque desde o primeiro dia em que aplicaste o teu coração a compreender e a humilhar-te perante o teu Deus, são ouvidas as tuas palavras, e por causa das tuas palavras eu vim.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 13, 'Mas o príncipe do reino da Pérsia me resistiu por vinte e um dias; e eis que Miguel, um dos primeiros príncipes, veio para ajudar-me, e eu o deixei ali com os reis da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 14, 'Agora vim, para fazer-te entender o que há de suceder ao teu povo nos derradeiros dias; pois a visão se refere a dias ainda distantes.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 15, 'Ao falar ele comigo estas palavras, abaixei o rosto para a terra e emudeci.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 16, 'E eis que um que tinha a semelhança dos filhos dos homens me tocou os lábios; então abri a boca e falei, e disse àquele que estava em pé diante de mim: Senhor meu, por causa da visão sobrevieram-me dores, e não retenho força alguma.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 17, 'Como, pois, pode o servo do meu Senhor falar com o meu Senhor? pois, quanto a mim, desde agora não resta força em mim, nem fôlego ficou em mim.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 18, 'Então tornou a tocar-me um que tinha a semelhança dum homem, e me consolou.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 19, 'E disse: Não temas, homem muito amado; paz seja contigo; sê forte, e tem bom ânimo. E quando ele falou comigo, fiquei fortalecido, e disse: Fala, meu senhor, pois me fortaleceste.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 20, 'Ainda disse ele: Sabes por que eu vim a ti? Agora tornarei a pelejar contra o príncipe dos persas; e, saindo eu, eis que virá o príncipe da Grécia.', 1, CURRENT_TIMESTAMP, false),
(27, 10, 21, 'Contudo eu te declararei o que está gravado na escritura da verdade; e ninguém há que se esforce comigo contra aqueles, senão Miguel, vosso príncipe.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 1, 'Eu, pois, no primeiro ano de Dario, medo, levantei-me para o animar e fortalecer.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 2, 'E agora te declararei a verdade: Eis que ainda se levantarão três reis na Pérsia, e o quarto será muito mais rico do que todos eles; e tendo-se tornado forte por meio das suas riquezas, agitará todos contra o reino da Grécia.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 3, 'Depois se levantará um rei poderoso, que reinará com grande domínio, e fará o que lhe aprouver.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 4, 'Mas, estando ele em pé, o seu reino será quebrado, e será repartido para os quatro ventos do céu; porém não para os seus descendentes, nem tampouco segundo o poder com que reinou; porque o seu reino será arrancado, e passará a outros que não eles.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 5, 'O rei do sul será forte, como também um dos seus príncipes; e este será mais forte do que ele, e reinará, e grande será o seu domínio,', 1, CURRENT_TIMESTAMP, false),
(27, 11, 6, 'mas, ao cabo de anos, eles se aliarão; e a filha do rei do sul virá ao rei do norte para fazer um tratado. Ela, porém, não conservara a força de seu braço; nem subsistirá ele, nem o seu braço; mas será ela entregue, e bem assim os que a tiverem trazido, e seu pai, e o que a fortalecia naqueles tempos.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 7, 'Mas dum renovo das raízes dela um se levantará em seu lugar, e virá ao exército, e entrará na fortaleza do rei do norte, e operará contra eles e prevalecerá.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 8, 'Também os seus deuses, juntamente com as suas imagens de fundição, com os seus vasos preciosos de prata e ouro, ele os levará cativos para o Egito; e por alguns anos ele deixará de atacar ao rei do norte.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 9, 'E entrará no reino do rei do sul, mas voltará para a sua terra.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 10, 'Mas seus filhos intervirão, e reunirão uma multidão de grandes forças; a qual avançará, e inundará, e passará para adiante; e, voltando, levará a guerra até a sua fortaleza.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 11, 'Então o rei do sul se exasperará, e sairá, e pelejará contra ele, contra o rei do norte; este porá em campo grande multidão, e a multidão será entregue na mão daquele.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 12, 'E a multidão será levada, e o coração dele se exaltará; mas, ainda que derrubará miríades, não prevalecerá.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 13, 'Porque o rei do norte tornará, e porá em campo uma multidão maior do que a primeira; e ao cabo de tempos, isto é, de anos, avançará com grande exército e abundantes provisões.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 14, 'E, naqueles tempos, muitos se levantarão contra o rei do sul; e os violentos dentre o teu povo se levantarão para cumprir a visão, mas eles cairão.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 15, 'Assim virá o rei do norte, e levantará baluartes, e tomará uma cidade bem fortificada; e as forças do sul não poderão resistir, nem o seu povo escolhido, pois não haverá força para resistir.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 16, 'O que, porém, há de vir contra ele fará o que lhe aprouver, e ninguém poderá resistir diante dele; ele se fincará na terra gloriosa, tendo-a inteiramente sob seu poder.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 17, 'E firmará o propósito de vir com toda a força do seu reino, e entrará em acordo com ele, e lhe dará a filha de mulheres, para ele a corromper; ela, porém, não subsistirá, nem será para ele.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 18, 'Depois disso virará o seu rosto para as ilhas, e tomará muitas; mas um príncipe fará cessar o seu opróbrio contra ele, e ainda fará recair sobre ele o seu opróbrio.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 19, 'Virará então o seu rosto para as fortalezas da sua própria terra, mas tropeçará, e cairá, e não será achado.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 20, 'Então no seu lugar se levantará quem fará passar um exator de tributo pela glória do reino; mas dentro de poucos dias será quebrantado, e isto sem ira e sem batalha.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 21, 'Depois se levantará em seu lugar um homem vil, ao qual não tinham dado a majestade real; mas ele virá caladamente, e tomará o reino com lisonja.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 22, 'E as forças inundantes serão varridas de diante dele, e serão quebrantadas, como também o príncipe do pacto.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 23, 'E, depois de feita com ele a aliança, usará de engano; e subirá, e se tornará forte com pouca gente.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 24, 'Virá também em tempo de segurança sobre os lugares mais férteis da província; e fará o que nunca fizeram seus pais, nem os pais de seus pais; espalhará entre eles a presa, os despojos e os bens; e maquinará os seus projetos contra as fortalezas, mas por certo tempo.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 25, 'E suscitará a sua força e a sua coragem contra o rei do sul com um grande exército; e o rei do sul sairá à guerra com um grande e mui poderoso exército, mas não subsistirá, pois maquinarão projetos contra ele.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 26, 'E os que comerem os seus manjares o quebrantarão; e o exército dele será varrido por uma inundação, e cairão muitos traspassados.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 27, 'Também estes dois reis terão o coração atento para fazerem o mal, e assentados à mesma mesa falarão a mentira; esta, porém, não prosperará, porque ainda virá o fim no tempo determinado.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 28, 'Então tornará para a sua terra com muitos bens; e o seu coração será contra o santo pacto; e fará o que lhe aprouver, e tornará para a sua terra.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 29, 'No tempo determinado voltará, e entrará no sul; mas não sucederá desta vez como na primeira.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 30, 'Porque virão contra ele navios de Quitim, que lhe causarão tristeza; por isso voltará, e se indignará contra o santo pacto, e fará como lhe aprouver. Voltará e atenderá aos que tiverem abandonado o santo pacto.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 31, 'E estarão ao lado dele forças que profanarão o santuário, isto é, a fortaleza, e tirarão o holocausto contínuo, estabelecendo a abominação desoladora.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 32, 'Ainda aos violadores do pacto ele perverterá com lisonjas; mas o povo que conhece ao seu Deus se tornará forte, e fará proezas.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 33, 'Os entendidos entre o povo ensinarão a muitos; todavia por muitos dias cairão pela espada e pelo fogo, pelo cativeiro e pelo despojo.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 34, 'Mas, caindo eles, serão ajudados com pequeno socorro; muitos, porém, se ajuntarão a eles com lisonjas.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 35, 'Alguns dos entendidos cairão para serem acrisolados, purificados e embranquecidos, até o fim do tempo; pois isso ainda será para o tempo determinado.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 36, 'e o rei fará conforme lhe aprouver; exaltar-se-á, e se engrandecerá sobre todo deus, e contra o Deus dos deuses falará coisas espantosas; e será próspero, até que se cumpra a indignação: pois aquilo que está determinado será feito.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 37, 'E não terá respeito aos deuses de seus pais, nem ao amado das mulheres, nem a qualquer outro deus; pois sobre tudo se engrandecerá.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 38, 'Mas em seu lugar honrará ao deus das fortalezas; e a um deus a quem seus pais não conheceram, ele o honrará com ouro e com prata, com pedras preciosas e com coisas agradáveis.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 39, 'E haver-se-á com os castelos fortes com o auxílio dum deus estranho; aos que o reconhecerem, multiplicará a glória; e os fará reinar sobre muitos, e lhes repartirá a terra por preço.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 40, 'Ora, no fim do tempo, o rei do sul lutará com ele; e o rei do norte virá como turbilhão contra ele, com carros e cavaleiros, e com muitos navios; e entrará nos países, e os inundará, e passará para adiante.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 41, 'Entrará na terra gloriosa, e dezenas de milhares cairão; mas da sua mão escaparão estes: Edom e Moabe, e as primícias dos filhos de Amom.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 42, 'E estenderá a sua mão contra os países; e a terra do Egito não escapará.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 43, 'Apoderar-se-á dos tesouros de ouro e de prata, e de todas as coisas preciosas do Egito; os líbios e os etíopes o seguirão.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 44, 'Mas os rumores do oriente e do norte o espantarão; e ele sairá com grande furor, para destruir e extirpar a muitos.', 1, CURRENT_TIMESTAMP, false),
(27, 11, 45, 'E armará as tendas do seu palácio entre o mar grande e o glorioso monte santo; contudo virá ao seu fim, e não haverá quem o socorra.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 1, 'Naquele tempo se levantará Miguel, o grande príncipe, que se levanta a favor dos filhos do teu povo; e haverá um tempo de tribulação, qual nunca houve, desde que existiu nação até aquele tempo; mas naquele tempo livrar-se-á o teu povo, todo aquele que for achado escrito no livro.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 2, 'E muitos dos que dormem no pó da terra ressuscitarão, uns para a vida eterna, e outros para vergonha e desprezo eterno.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 3, 'Os que forem sábios, pois, resplandecerão como o fulgor do firmamento; e os que converterem a muitos para a justiça, como as estrelas sempre e eternamente.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 4, 'Tu, porém, Daniel, cerra as palavras e sela o livro, até o fim do tempo; muitos correrão de uma parte para outra, e a ciência se multiplicará.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 5, 'Então eu, Daniel, olhei, e eis que estavam em pé outros dois, um de uma banda à beira do rio, e o outro da outra banda à beira do rio.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 6, 'E perguntei ao homem vestido de linho, que estava por cima das águas do rio: Quanto tempo haverá até o fim destas maravilhas?', 1, CURRENT_TIMESTAMP, false),
(27, 12, 7, 'E ouvi o homem vestido de linho, que estava por cima das águas do rio, quando levantou ao céu a mão direita e a mão esquerda, e jurou por aquele que vive eternamente que isso seria para um tempo, dois tempos, e metade de um tempo. E quando tiverem acabado de despedaçar o poder do povo santo, cumprir-se-ão todas estas coisas.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 8, 'Eu, pois, ouvi, mas não entendi; por isso perguntei: Senhor meu, qual será o fim destas coisas?', 1, CURRENT_TIMESTAMP, false),
(27, 12, 9, 'Ele respondeu: Vai-te, Daniel, porque estas palavras estão cerradas e seladas até o tempo do fim.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 10, 'Muitos se purificarão, e se embranquecerão, e serão acrisolados; mas os ímpios procederão impiamente; e nenhum deles entenderá; mas os sábios entenderão.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 11, 'E desde o tempo em que o holocausto contínuo for tirado, e estabelecida a abominação desoladora, haverá mil duzentos e noventa dias.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 12, 'Bem-aventurado é o que espera e chega aos mil trezentos e trinta e cinco dias.', 1, CURRENT_TIMESTAMP, false),
(27, 12, 13, 'Tu, porém, vai-te, até que chegue o fim; pois descansarás, e estarás no teu quinhão ao fim dos dias.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 1, 'Estas são as palavras que Moisés falou a todo Israel além do Jordão, no deserto, na Arabá defronte de Sufe, entre Parã, Tofel, Labã, Hazerote e Di-Zaabe.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 2, 'São onze dias de viagem desde Horebe, pelo caminho da montanha de Seir, até Cades-Barnéia.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 3, 'No ano quadragésimo, no mês undécimo, no primeiro dia do mês, Moisés falou aos filhos de Israel, conforme tudo o que o senhor lhes mandara por seu intermédio,', 1, CURRENT_TIMESTAMP, false),
(5, 1, 4, 'depois que derrotou a Siom, rei dos amorreus, que habitava em Hesbom, e a Ogue, rei de Basã, que habitava em Astarote, em Edrei.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 5, 'Além do Jordão, na terra de Moabe, Moisés se pôs a explicar esta lei, e disse:', 1, CURRENT_TIMESTAMP, false),
(5, 1, 6, 'O Senhor nosso Deus nos falou em Horebe, dizendo: Assaz vos haveis demorado neste monte.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 7, 'Voltai-vos, ponde-vos a caminho, e ide à região montanhosa dos amorreus, e a todos os lugares vizinhos, na Arabá, na região montanhosa, no vale e no sul; à beira do mar, à terra dos cananeus, e ao Líbano, até o grande rio, o rio Eufrates.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 8, 'Eis que tenho posto esta terra diante de vós; entrai e possuí a terra que o Senhor prometeu com juramento dar a vossos pais, Abraão, Isaque, e Jacó, a eles e à sua descendência depois deles.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 9, 'Nesse mesmo tempo eu vos disse: Eu sozinho não posso levar-vos,', 1, CURRENT_TIMESTAMP, false),
(5, 1, 10, 'o Senhor vosso Deus já vos tem multiplicado, e eis que hoje sois tão numerosos como as estrelas do céu.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 11, 'O Senhor Deus de vossos pais vos faça mil vezes mais numerosos do que sois; e vos abençoe, como vos prometeu.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 12, 'Como posso eu sozinho suportar o vosso peso, as vossas cargas e as vossas contendas?', 1, CURRENT_TIMESTAMP, false),
(5, 1, 13, 'Tomai-vos homens sábios, entendidos e experimentados, segundo as vossas tribos, e eu os porei como cabeças sobre vós.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 14, 'Então me respondestes: bom fazermos o que disseste.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 15, 'Tomei, pois, os cabeças de vossas tribos, homens sábios e experimentados, e os constituí por cabeças sobre vós, chefes de mil, chefes de cem, chefes de cinqüenta e chefes de dez, por oficiais, segundo as vossas tribos.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 16, 'E no mesmo tempo ordenei a vossos juízes, dizendo: Ouvi as causas entre vossos irmãos, e julgai com justiça entre o homem e seu irmão, ou o estrangeiro que está com ele.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 17, 'Não fareis acepção de pessoas em juízo; de um mesmo modo ouvireis o pequeno e o grande; não temereis a face de ninguém, porque o juízo é de Deus; e a causa que vos for difícil demais, a trareis a mim, e eu a ouvirei.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 18, 'Assim naquele tempo vos ordenei todas as coisas que devíeis fazer.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 19, 'Então partimos de Horebe, e caminhamos por todo aquele grande e terrível deserto que vistes, pelo caminho das montanhas dos amorreus, como o Senhor nosso Deus nos ordenara; e chegamos a Cades-Barnéia.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 20, 'Então eu vos disse: Chegados sois às montanhas dos amorreus, que o Senhor nosso Deus nos dá.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 21, 'Eis aqui o Senhor teu Deus tem posto esta terra diante de ti; sobe, apodera-te dela, como te falou o Senhor Deus de teus pais; não temas, e não te assustes.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 22, 'Então todos vós vos chegastes a mim, e dissestes: Mandemos homens adiante de nós, para que nos espiem a terra e, de volta, nos ensinem o caminho pelo qual devemos subir, e as cidades a que devemos ir.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 23, 'Isto me pareceu bem; de modo que dentre vós tomei doze homens, de cada tribo um homem;', 1, CURRENT_TIMESTAMP, false),
(5, 1, 24, 'foram-se eles e, subindo as montanhas, chegaram até o vale de Escol e espiaram a terra.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 25, 'Tomaram do fruto da terra nas mãos, e no-lo trouxeram; e nos informaram, dizendo: Boa é a terra que nos dá o Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 26, 'Todavia, vós não quisestes subir, mas fostes rebeldes ao mandado do Senhor nosso Deus;', 1, CURRENT_TIMESTAMP, false),
(5, 1, 27, 'e murmurastes nas vossas tendas, e dissestes: Porquanto o Senhor nos odeia, tirou-nos da terra do Egito para nos entregar nas mãos dos amorreus, a fim de nos destruir.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 28, 'Para onde estamos nós subindo? nossos irmãos fizeram com que se derretesse o nosso coração, dizendo: Maior e mais alto é o povo do que nós; as cidades são grandes e fortificadas até o céu; e também vimos ali os filhos dos anaquins.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 29, 'Então eu vos disse: Não vos atemorizeis, e não tenhais medo deles.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 30, 'O Senhor vosso Deus, que vai adiante de vós, ele pelejará por vós, conforme tudo o que tem feito por vós diante dos vossos olhos, no Egito,', 1, CURRENT_TIMESTAMP, false),
(5, 1, 31, 'como também no deserto, onde vistes como o Senhor vosso Deus vos levou, como um homem leva seu filho, por todo o caminho que andastes, até chegardes a este lugar.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 32, 'Mas nem ainda assim confiastes no Senhor vosso Deus,', 1, CURRENT_TIMESTAMP, false),
(5, 1, 33, 'que ia adiante de vós no caminho, de noite no fogo e de dia na nuvem, para vos achar o lugar onde devíeis acampar, e para vos mostrar o caminho por onde havíeis de andar.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 34, 'Ouvindo, pois, o Senhor a voz das vossas palavras, indignou-se e jurou, dizendo:', 1, CURRENT_TIMESTAMP, false),
(5, 1, 35, 'Nenhum dos homens desta geração perversa verá a boa terra que prometi com juramento dar a vossos pais,', 1, CURRENT_TIMESTAMP, false),
(5, 1, 36, 'salvo Calebe, filho de Jefoné; ele a verá, e a terra que pisou darei a ele e a seus filhos, porquanto perseverou em seguir ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 37, 'Também contra mim o Senhor se indignou por vossa causa, dizendo: Igualmente tu lá não entrarás.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 38, 'Josué, filho de Num, que te serve, ele ali entrará; anima-o, porque ele fará que Israel a receba por herança.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 39, 'E vossos pequeninos, dos quais dissestes que seriam por presa, e vossos filhos que hoje não conhecem nem o bem nem o mal, esses lá entrarão, a eles a darei e eles a possuirão.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 40, 'Quanto a vós, porém, virai-vos, e parti para o deserto, pelo caminho do Mar Vermelho.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 41, 'Então respondestes, e me dissestes: Pecamos contra o Senhor; nós subiremos e pelejaremos, conforme tudo o que nos ordenou o Senhor nosso Deus. Vós, pois, vos armastes, cada um, dos vossos instrumentos de guerra, e temerariamente propusestes subir a montanha.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 42, 'E disse-me o Senhor: Dize-lhes: Não subais nem pelejeis, pois não estou no meio de vós; para que não sejais feridos diante de vossos inimigos.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 43, 'Assim vos falei, mas não ouvistes; antes fostes rebeldes à ordem do Senhor e, agindo presunçosamente, subistes à montanha.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 44, 'E os amorreus, que habitavam naquela montanha, vos saíram ao encontro e, perseguindo-vos como fazem as abelhas, vos destroçaram desde Seir até Horma.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 45, 'Voltastes, pois, e chorastes perante o Senhor; mas o Senhor não ouviu a vossa voz, nem para vós inclinou os ouvidos.', 1, CURRENT_TIMESTAMP, false),
(5, 1, 46, 'Assim foi grande a vossa demora em Cades, pois ali vos demorastes muitos dias.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 1, 'Depois viramo-nos, e caminhamos para o deserto, pelo caminho do Mar Vermelho, como o Senhor me tinha dito, e por muitos dias rodeamos o monte Seir.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 2, 'Então o Senhor me disse:', 1, CURRENT_TIMESTAMP, false),
(5, 2, 3, 'Basta de rodeardes este monte; virai-vos para o norte.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 4, 'Dá ordem ao povo, dizendo: Haveis de passar pelo território de vossos irmãos, os filhos de Esaú, que habitam em Seir; e eles terão medo de vós. Portanto guardai-vos bem;', 1, CURRENT_TIMESTAMP, false),
(5, 2, 5, 'não contendais com eles, porque não vos darei da sua terra nem sequer o que pisar a planta de um pé; porquanto a Esaú dei o monte Seir por herança.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 6, 'Comprareis deles por dinheiro mantimento para comerdes, como também comprareis deles água para beberdes.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 7, 'Pois o Senhor teu Deus te há abençoado em toda obra das tuas mãos; ele tem conhecido o teu caminho por este grande deserto; estes quarenta anos o Senhor teu Deus tem estado contigo; nada te há faltado.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 8, 'Assim, pois, passamos por nossos irmãos, os filhos de Esaú, que habitam em Seir, desde o caminho da Arabá de Elate e de Eziom-Geber: Depois nos viramos e passamos pelo caminho do deserto de Moabe.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 9, 'Então o Senhor me disse: Não molestes aos de Moabe, e não contendas com eles em peleja, porque nada te darei da sua terra por herança; porquanto dei Ar por herança aos filhos de Ló.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 10, '{Antes haviam habitado nela os emins, povo grande e numeroso, e alto como os anaquins;', 1, CURRENT_TIMESTAMP, false),
(5, 2, 11, 'eles também são considerados refains como os anaquins; mas os moabitas lhes chamam emins.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 12, 'Outrora os horeus também habitaram em Seir; porém os filhos de Esaú os desapossaram, e os destruíram de diante de si, e habitaram no lugar deles, assim come Israel fez à terra da sua herança, que o Senhor lhe deu.}', 1, CURRENT_TIMESTAMP, false),
(5, 2, 13, 'Levantai-vos agora, e passai o ribeiro de Zerede. Passamos, pois, o ribeiro de Zerede.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 14, 'E os dias que caminhamos, desde Cades-Barnéia até passarmos o ribeiro de Zerede, foram trinta e oito anos, até que toda aquela geração dos homens de guerra se consumiu do meio do arraial, como o Senhor lhes jurara.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 15, 'Também foi contra eles a mão do Senhor, para os destruir do meio do arraial, até os haver consumido.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 16, 'Ora, sucedeu que, sendo já consumidos pela morte todos os homens de guerra dentre o povo,', 1, CURRENT_TIMESTAMP, false),
(5, 2, 17, 'o Senhor me disse:', 1, CURRENT_TIMESTAMP, false),
(5, 2, 18, 'Hoje passarás por Ar, o limite de Moabe;', 1, CURRENT_TIMESTAMP, false),
(5, 2, 19, 'e quando chegares defronte dos amonitas, não os molestes, e com eles não contendas, porque nada te darei da terra dos amonitas por herança; porquanto aos filhos de Ló a dei por herança.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 20, '{Também essa é considerada terra de refains; outrora habitavam nela refains, mas os amonitas lhes chamam zanzumins,', 1, CURRENT_TIMESTAMP, false),
(5, 2, 21, 'povo grande e numeroso, e alto como os anaquins; mas o Senhor os destruiu de diante dos amonitas; e estes, tendo-os desapossado, habitaram no lugar deles;', 1, CURRENT_TIMESTAMP, false),
(5, 2, 22, 'assim como fez pelos filhos de Esaú, que habitam em Seir, quando de diante deles destruiu os horeus; e os filhos de Esaú, havendo-os desapossado, habitaram no lugar deles até hoje.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 23, 'Também os caftorins, que saíram de Caftor, destruíram os aveus, que habitavam em aldeias até Gaza, e habitaram no lugar deles.}', 1, CURRENT_TIMESTAMP, false),
(5, 2, 24, 'Levantai-vos, parti e passai o ribeiro de Arnom; eis que entreguei nas tuas mãos a Siom, o amorreu, rei de Hesbom, e à sua terra; começa a te apoderares dela, contendendo com eles em peleja.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 25, 'Neste dia começarei a meter terror e medo de ti aos povos que estão debaixo de todo o céu; os quais, ao ouvirem a tua fama, tremerão e se angustiarão por causa de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 26, 'Então, do deserto de Quedemote, mandei mensageiros a Siom, rei de Hesbom, com palavras de paz, dizendo:', 1, CURRENT_TIMESTAMP, false),
(5, 2, 27, 'Deixa-me passar pela tua terra; somente pela estrada irei, não me desviando nem para a direita nem para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 28, 'Por dinheiro me venderás mantimento, para que eu coma; e por dinheiro me darás a água, para que eu beba. Tão-somente deixa-me passar a pé,', 1, CURRENT_TIMESTAMP, false),
(5, 2, 29, 'assim como me fizeram os filhos de Esaú, que habitam em Seir, e os moabitas que habitam em Ar; até que eu passe o Jordão para a terra que o Senhor nosso Deus nos dá.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 30, 'Mas Siom, rei de Hesbom, não nos quis deixar passar por sua terra, porquanto o Senhor teu Deus lhe endurecera o espírito, e lhe fizera obstinado o coração, para to entregar nas mãos, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 31, 'Disse-me, pois, o Senhor: Eis aqui, comecei a entregar-te Siom e a sua terra; começa, pois, a te apoderares dela, para possuíres a sua terra por herança.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 32, 'Então Siom nos saiu ao encontro, ele e todo o seu povo, à peleja, em Jaza;', 1, CURRENT_TIMESTAMP, false),
(5, 2, 33, 'e o Senhor nosso Deus no-lo entregou, e o ferimos a ele, e a seus filhos, e a todo o seu povo.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 34, 'Também naquele tempo lhe tomamos todas as cidades, e fizemos perecer a todos, homens, mulheres e pequeninos, não deixando sobrevivente algum;', 1, CURRENT_TIMESTAMP, false),
(5, 2, 35, 'somente tomamos por presa o gado para nós, juntamente com o despojo das cidades que havíamos tomado.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 36, 'Desde Aroer, que está à borda do vale do Arnom, e desde a cidade que está no vale, até Gileade, nenhuma cidade houve tão alta que de nós escapasse; tudo o Senhor nosso Deus no-lo entregou.', 1, CURRENT_TIMESTAMP, false),
(5, 2, 37, 'Somente à terra dos amonitas não chegastes, nem a parte alguma da borda do ribeiro de Jaboque, nem a cidade alguma da região montanhosa, nem a coisa alguma que o Senhor nosso Deus proibira.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 1, 'Depois nos viramos e subimos pelo caminho de Basã; e Ogue, rei de Basã, nos saiu ao encontro, ele e todo o seu povo, à peleja, em Edrei.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 2, 'Então o Senhor me disse: Não o temas, porque to entreguei nas mãos, a ele e a todo o seu povo, e a sua terra; e farás a ele como fizeste a Siom, rei dos amorreus, que habitava em Hesbom.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 3, 'Assim o Senhor nosso Deus nos entregou nas mãos também a Ogue, rei de Basã, e a todo o seu povo; de maneira que o ferimos, até que não lhe ficou sobrevivente algum.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 4, 'E naquele tempo tomamos todas as suas cidades; nenhuma cidade houve que não lhes tomássemos: sessenta cidades, toda a região de Argobe, o reino de Ogue em Basã,', 1, CURRENT_TIMESTAMP, false),
(5, 3, 5, 'cidades estas todas fortificadas com altos muros, portas e ferrolhos, além de muitas cidades sem muros.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 6, 'E destruímo-las totalmente, como fizéramos a Siom, rei de Hesbom, fazendo perecer a todos, homens, mulheres e pequeninos.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 7, 'Mas todo o gado e o despojo das cidades, tomamo-los por presa para nós.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 8, 'Assim naquele tempo tomamos a terra da mão daqueles dois reis dos amorreus, que estavam além do Jordão, desde o rio Arnom até o monte Hermom', 1, CURRENT_TIMESTAMP, false),
(5, 3, 9, '{ao Hermom os sidônios chamam Siriom, e os amorreus chamam-lhe Senir} ,', 1, CURRENT_TIMESTAMP, false),
(5, 3, 10, 'todas as cidades do planalto, e todo o Gileade, e todo o Basã, até Salca e Edrei, cidades do reino de Ogue em Basã.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 11, 'Porque só Ogue, rei de Basã, ficou de resto dos refains; eis que o seu leito, um leito de ferro, não está porventura em Rabá dos amonitas? o seu comprimento é de nove côvados, e de quatro côvados a sua largura, segundo o côvado em uso.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 12, 'Naquele tempo, pois, tomamos essa terra por possessão. Desde Aroer, que está junto do vale do Arnom, e a metade da região montanhosa de Gileade, com as suas cidades, dei aos nibenitas e gaditas;', 1, CURRENT_TIMESTAMP, false),
(5, 3, 13, 'e dei à meia tribo de Manassés o resto de Gileade, como também todo o Basã, o reino de Ogue, isto é, toda a região de Argobe com todo o Basã. {O mesmo se chamava a terra dos refains.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 14, 'Jair, filho de Manassés, tomou toda a região de Argobe, até a fronteira dos resuritas e dos maacatitas, e lhes chamou, inclusive o Basã, pelo seu nome, Havote-Jair, até hoje}.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 15, 'E a Maquir dei Gileade.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 16, 'Mas aos rubenitas e gaditas dei desde Gileade até o vale do Arnom, tanto o meio do vale como a sua borda, e até o ribeiro de Jaboque, o termo dos amonitas;', 1, CURRENT_TIMESTAMP, false),
(5, 3, 17, 'como também a Arabá, com o Jordão por termo, desde Quinerete até o mar da Arabá, o Mar Salgado, pelas faldas de Pisga para o oriente.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 18, 'No mesmo tempo também vos ordenei, dizendo: O Senhor vosso Deus vos deu esta terra, para a possuirdes; vós, todos os homens valentes, passareis armados adiante de vossos irmãos, os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 19, 'Tão-somente vossas mulheres, e vossos pequeninos, e vosso gado {porque eu sei que tendes muito gado} ficarão nas cidades que já vos dei;', 1, CURRENT_TIMESTAMP, false),
(5, 3, 20, 'até que o Senhor dê descanso a vossos irmãos como a vós, e eles também possuam a terra que o Senhor vosso Deus lhes dá além do Jordão: Então voltareis cada qual à sua herança que já vos tenho dado.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 21, 'Também dei ordem a Josué no mesmo tempo, dizendo: Os teus olhos viram tudo o que o Senhor vosso Deus tem feito a esses dois reis; assim fará o Senhor a todos os reinos a que tu estás passando.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 22, 'Não tenhais medo deles, porque o Senhor vosso Deus é o que peleja por nós.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 23, 'Também roguei ao Senhor nesse tempo, dizendo:', 1, CURRENT_TIMESTAMP, false),
(5, 3, 24, 'Ó Senhor Jeová, tu já começaste a mostrar ao teu servo a tua grandeza e a tua forte mão; pois, que Deus há no céu ou na terra, que possa fazer segundo as tuas obras, e segundo os teus grandes feitos?', 1, CURRENT_TIMESTAMP, false),
(5, 3, 25, 'Rogo-te que me deixes passar, para que veja essa boa terra que está além do Jordão, essa boa região montanhosa, e o Líbano!', 1, CURRENT_TIMESTAMP, false),
(5, 3, 26, 'Mas o Senhor indignou-se muito contra mim por causa de vós, e não me ouviu; antes me disse: Basta; não me fales mais nisto.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 27, 'sobe ao cume do Pisga, e levanta os olhos para o ocidente, para o norte, para o sul e para o oriente, e contempla com os teus olhos; porque não passarás este Jordão.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 28, 'Mas dá ordens a Josué, anima-o, e fortalece-o, porque ele passará adiante deste povo, e o levará a possuir a terra que tu verás.', 1, CURRENT_TIMESTAMP, false),
(5, 3, 29, 'Assim ficamos no vale defronte de Bete-Peor.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 1, 'Agora, pois, ó Israel, ouve os estatutos e os preceitos que eu vos ensino, para os observardes, a fim de que vivais, e entreis e possuais a terra que o Senhor Deus de vossos pais vos dá.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 2, 'Não acrescentareis à palavra que vos mando, nem diminuireis dela, para que guardeis os mandamentos do Senhor vosso Deus, que eu vos mando.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 3, 'Os vossos olhos viram o que o Senhor fez por causa de Baal-Peor; pois a todo homem que seguiu a Baal-Peor, o Senhor vosso Deus o consumiu do meio de vós.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 4, 'Mas vós, que vos apegastes ao Senhor vosso Deus, todos estais hoje vivos.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 5, 'Eis que vos ensinei estatutos e preceitos, como o Senhor meu Deus me ordenou, para que os observeis no meio da terra na qual estais entrando para a possuirdes.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 6, 'Guardai-os e observai-os, porque isso é a vossa sabedoria e o vosso entendimento à vista dos povos, que ouvirão todos estes, estatutos, e dirão: Esta grande nação é deveras povo sábio e entendido.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 7, 'Pois que grande nação há que tenha deuses tão chegados a si como o é a nós o Senhor nosso Deus todas as vezes que o invocamos?', 1, CURRENT_TIMESTAMP, false),
(5, 4, 8, 'E que grande nação há que tenha estatutos e preceitos tão justos como toda esta lei que hoje ponho perante vós?', 1, CURRENT_TIMESTAMP, false),
(5, 4, 9, 'Tão-somente guarda-te a ti mesmo, e guarda bem a tua alma, para que não te esqueças das coisas que os teus olhos viram, e que elas não se apaguem do teu coração todos os dias da tua vida; porém as contarás a teus filhos, e aos filhos de teus filhos;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 10, 'o dia em que estiveste perante o Senhor teu Deus em Horebe, quando o Senhor me disse: Ajunta-me este povo, e os farei ouvir as minhas palavras, e aprendê-las-ão, para me temerem todos os dias que na terra viverem, e as ensinarão a seus filhos.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 11, 'Então vós vos chegastes, e vos pusestes ao pé do monte; e o monte ardia em fogo até o meio do céu, e havia trevas, e nuvens e escuridão.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 12, 'E o Senhor vos falou do meio do fogo; ouvistes o som de palavras, mas não vistes forma alguma; tão-somente ouvistes uma voz.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 13, 'Então ele vos anunciou o seu pacto, o qual vos ordenou que observásseis, isto é, os dez mandamentos; e os escreveu em duas tábuas de pedra.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 14, 'Também o Senhor me ordenou ao mesmo tempo que vos ensinasse estatutos e preceitos, para que os cumprísseis na terra a que estais passando para a possuirdes.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 15, 'Guardai, pois, com diligência as vossas almas, porque não vistes forma alguma no dia em que o Senhor vosso Deus, em Horebe, falou convosco do meio do fogo;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 16, 'para que não vos corrompais, fazendo para vós alguma imagem esculpida, na forma de qualquer figura, semelhança de homem ou de mulher;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 17, 'ou semelhança de qualquer animal que há na terra, ou de qualquer ave que voa pelo céu;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 18, 'ou semelhança de qualquer animal que se arrasta sobre a terra, ou de qualquer peixe que há nas águas debaixo da terra;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 19, 'e para que não suceda que, levantando os olhos para o céu, e vendo o sol, a lua e as estrelas, todo esse exército do céu, sejais levados a vos inclinardes perante eles, prestando culto a essas coisas que o Senhor vosso Deus repartiu a todos os povos debaixo de todo o céu.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 20, 'Mas o Senhor vos tomou, e vos tirou da fornalha de ferro do Egito, a fim de lhe serdes um povo hereditário, como hoje o sois.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 21, 'O Senhor se indignou contra mim por vossa causa, e jurou que eu não passaria o Jordão, e que não entraria na boa terra que o Senhor vosso Deus vos dá por herança;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 22, 'mas eu tenho de morrer nesta terra; não poderei passar o Jordão; porém vós o passareis, e possuireis essa boa terra.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 23, 'Guardai-vos de que vos esqueçais do pacto do Senhor vosso Deus, que ele fez convosco, e não façais para vós nenhuma imagem esculpida, semelhança de alguma coisa que o Senhor vosso Deus vos proibiu.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 24, 'Porque o Senhor vosso Deus é um fogo consumidor, um Deus zeloso.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 25, 'Quando, pois, tiverdes filhos, e filhos de filhos, e envelhecerdes na terra, e vos corromperdes, fazendo alguma imagem esculpida, semelhança de alguma coisa, e praticando o que é mau aos olhos do Senhor vosso Deus, para o provocar a ira,-', 1, CURRENT_TIMESTAMP, false),
(5, 4, 26, 'hoje tomo por testemunhas contra vós o céu e a terra, bem cedo perecereis da terra que, passado o Jordão, ides possuir. Não prolongareis os vossos dias nela, antes sereis de todo destruídos.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 27, 'E o Senhor vos espalhará entre os povos, e ficareis poucos em número entre as nações para as quais o Senhor vos conduzirá.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 28, 'Lá servireis a deuses que são obra de mãos de homens, madeira e pedra, que não vêem, nem ouvem, nem comem, nem cheiram.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 29, 'Mas de lá buscarás ao Senhor teu Deus, e o acharás, quando o buscares de todo o teu coração e de toda a tua alma.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 30, 'Quando estiveres em angústia, e todas estas coisas te alcançarem, então nos últimos dias voltarás para o Senhor teu Deus, e ouvirás a sua voz;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 31, 'porquanto o Senhor teu Deus é Deus misericordioso, e não te desamparará, nem te destruirá, nem se esquecerá do pacto que jurou a teus pais.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 32, 'Agora, pois, pergunta aos tempos passados que te precederam desde o dia em que Deus criou o homem sobre a terra, desde uma extremidade do céu até a outra, se aconteceu jamais coisa tão grande como esta, ou se jamais se ouviu coisa semelhante?', 1, CURRENT_TIMESTAMP, false),
(5, 4, 33, 'Ou se algum povo ouviu a voz de Deus falar do meio do fogo, como tu a ouviste, e ainda ficou vivo?', 1, CURRENT_TIMESTAMP, false),
(5, 4, 34, 'Ou se Deus intentou ir tomar para si uma nação do meio de outra nação, por meio de provas, de sinais, de maravilhas, de peleja, de mão poderosa, de braço estendido, bem como de grandes espantos, segundo tudo quanto fez a teu favor o Senhor teu Deus, no Egito, diante dos teus olhos?', 1, CURRENT_TIMESTAMP, false),
(5, 4, 35, 'A ti te foi mostrado para que soubesses que o Senhor é Deus; nenhum outro há senão ele.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 36, 'Do céu te fez ouvir a sua voz, para te instruir, e sobre a terra te mostrou o seu grande fogo, do meio do qual ouviste as suas palavras.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 37, 'E, porquanto amou a teus pais, não somente escolheu a sua descendência depois deles, mas também te tirou do Egito com a sua presença e com a sua grande força;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 38, 'para desapossar de diante de ti nações maiores e mais poderosas do que tu, para te introduzir na sua terra e te dar por herança, como neste dia se vê.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 39, 'Pelo que hoje deves saber e considerar no teu coração que só o Senhor é Deus, em cima no céu e embaixo na terra; não há nenhum outro.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 40, 'E guardarás os seus estatutos e os seus mandamentos, que eu te ordeno hoje, para que te vá bem a ti, e a teus filhos depois de ti, e para que prolongues os dias na terra que o Senhor teu Deus te dá, para todo o sempre.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 41, 'Então Moisés separou três cidades além do Jordão, para o nascente,', 1, CURRENT_TIMESTAMP, false),
(5, 4, 42, 'para que se refugiasse ali o homicida que involuntariamente tivesse matado o seu próximo a quem dantes não tivesse ódio algum; para que, refugiando-se numa destas cidades, vivesse:', 1, CURRENT_TIMESTAMP, false),
(5, 4, 43, 'a Bezer, no deserto, no planalto, para os rubenitas; a Ramote, em Gileade, para os paditas; e a Golã, em Basã, para os manassitas.', 1, CURRENT_TIMESTAMP, false),
(5, 4, 44, 'Esta é a lei que Moisés propôs aos filhos de Israel;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 45, 'estes são os testemunhos, os estatutos e os preceitos que Moisés falou aos filhos de Israel, depois que saíram do Egito,', 1, CURRENT_TIMESTAMP, false),
(5, 4, 46, 'além do Jordão, no vale defronte de Bete-Peor, na terra de Siom, rei dos amorreus, que habitava em Hesbom, a quem Moisés e os filhos de Israel derrotaram, depois que saíram do Egito;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 47, 'pois tomaram a terra deles em possessão, como também a terra de Ogue, rei de Basã, sendo esses os dois reis dos amorreus, que estavam além do Jordão, para o nascente;', 1, CURRENT_TIMESTAMP, false),
(5, 4, 48, 'desde Aroer, que está à borda do ribeiro de Arnom, até o monte de Siom, que é Hermom,', 1, CURRENT_TIMESTAMP, false),
(5, 4, 49, 'e toda a Arabá, além do Jordão, para o oriente, até o mar da Arabá, pelas faldas de Pisga.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 1, 'Chamou, pois, Moisés a todo o Israel, e disse-lhes: Ouve, ó Israel, os estatutos e preceitos que hoje vos falo aos ouvidos, para que os aprendais e cuideis em os cumprir.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 2, 'O Senhor nosso Deus fez um pacto conosco em Horebe.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 3, 'Não com nossos pais fez o Senhor esse pacto, mas conosco, sim, com todos nós que hoje estamos aqui vivos.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 4, 'Face a face falou o Senhor conosco no monte, do meio o fogo', 1, CURRENT_TIMESTAMP, false),
(5, 5, 5, '{estava eu nesse tempo entre o Senhor e vós, para vos anunciar a palavra do Senhor; porque tivestes medo por causa do fogo, e não subistes ao monte} , dizendo ele:', 1, CURRENT_TIMESTAMP, false),
(5, 5, 6, 'Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 7, 'Não terás outros deuses diante de mim.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 8, 'Não farás para ti imagem esculpida, nem figura alguma do que há em cima no céu, nem embaixo na terra, nem nas águas debaixo da terra;', 1, CURRENT_TIMESTAMP, false),
(5, 5, 9, 'não te encurvarás diante delas, nem as servirás; porque eu, o Senhor teu Deus, sou Deus zeloso, que visito a iniqüidade dos pais nos filhos até a terceira e quarta geração daqueles que me odeiam,', 1, CURRENT_TIMESTAMP, false),
(5, 5, 10, 'e uso de misericórdia com milhares dos que me amam e guardam os meus mandamentos.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 11, 'Não tomarás o nome do Senhor teu Deus em vão; porque o Senhor não terá por inocente aquele que tomar o seu nome em vão.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 12, 'Guarda o dia do sábado, para o santificar, como te ordenou o senhor teu Deus;', 1, CURRENT_TIMESTAMP, false),
(5, 5, 13, 'seis dias trabalharás, e farás todo o teu trabalho;', 1, CURRENT_TIMESTAMP, false),
(5, 5, 14, 'mas o sétimo dia é o sábado do Senhor teu Deus; nesse dia não farás trabalho algum, nem tu, nem teu filho, nem tua filha, nem o teu servo, nem a tua serva, nem o teu boi, nem o teu jumento, nem animal algum teu, nem o estrangeiro que está dentro das tuas portas; para que o teu servo e a tua serva descansem assim como tu.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 15, 'Lembra-te de que foste servo na terra do Egito, e que o Senhor teu Deus te tirou dali com mão forte e braço estendido; pelo que o Senhor teu Deus te ordenou que guardasses o dia do sábado.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 16, 'Honra a teu pai e a tua mãe, como o senhor teu Deus te ordenou, para que se prolonguem os teus dias, e para que te vá bem na terra que o Senhor teu Deus te dá.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 17, 'Não matarás.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 18, 'Não adulterarás.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 19, 'Não furtarás.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 20, 'Não dirás falso testemunho contra o teu próximo.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 21, 'Não cobiçarás a mulher do teu próximo; não desejarás a casa do teu próximo; nem o seu campo, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma do teu próximo.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 22, 'Essas palavras falou o senhor a toda a vossa assembléia no monte, do meio do fogo, da nuvem e da escuridão, com grande voz; e nada acrescentou. E escreveu-as em duas tábuas de pedra, que ele me deu.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 23, 'Mas quando ouvistes a voz do meio das trevas, enquanto ardia o monte em fogo, viestes ter comigo, mesmo todos os cabeças das vossas tribos, e vossos anciãos,', 1, CURRENT_TIMESTAMP, false),
(5, 5, 24, 'e dissestes: Eis que o Senhor nosso Deus nos fez ver a sua glória e a sua grandeza, e ouvimos a sua voz do meio do fogo; hoje vimos que Deus fala com o homem, e este ainda continua vivo.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 25, 'Agora, pois, por que havemos de morrer? Este grande fogo nos consumirá; se ainda mais ouvirmos a voz do Senhor nosso Deus, morreremos.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 26, 'Porque, quem há de toda a carne, que tenha ouvido a voz do Deus vivente a falar do meio do fogo, como nós a ouvimos, e ainda continue vivo?', 1, CURRENT_TIMESTAMP, false),
(5, 5, 27, 'Chega-te tu, e ouve tudo o que o Senhor nosso Deus falar; e tu nos dirás tudo o que ele te disser; assim o ouviremos e o cumpriremos.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 28, 'Ouvindo, pois, o Senhor as vossas palavras, quando me faláveis, disse-me: Eu ouvi as palavras deste povo, que eles te disseram; falaram bem em tudo quanto disseram.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 29, 'Quem dera que eles tivessem tal coração que me temessem, e guardassem em todo o tempo todos os meus mandamentos, para que bem lhes fosse a eles, e a seus filhos para sempre!', 1, CURRENT_TIMESTAMP, false),
(5, 5, 30, 'Vai, dize-lhes: Voltai às vossas tendas.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 31, 'Tu, porém, deixa-te ficar aqui comigo, e eu te direi todos os mandamentos, estatutos e preceitos que tu lhes hás de ensinar, para que eles os cumpram na terra que eu lhes dou para a possuírem.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 32, 'Olhai, pois, que façais como vos ordenou o Senhor vosso Deus; não vos desviareis nem para a direita nem para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(5, 5, 33, 'Andareis em todo o caminho que vos ordenou a Senhor vosso Deus, para que vivais e bem vos suceda, e prolongueis os vossos dias na terra que haveis de possuir.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 1, 'Estes, pois, são os mandamentos, os estatutos e os preceitos que o Senhor teu Deus mandou ensinar-te, a fim de que os cumprisses na terra a que estás passando: para a possuíres;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 2, 'para que temas ao Senhor teu Deus, e guardes todos os seus estatutos e mandamentos, que eu te ordeno, tu, e teu filho, e o filho de teu filho, todos os dias da tua vida, e para que se prolonguem os teus dias.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 3, 'Ouve, pois, ó Israel, e atenta em que os guardes, para que te vá bem, e muito te multipliques na terra que mana leite e mel, como te prometeu o Senhor Deus de teus pais.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 4, 'Ouve, ó Israel; o Senhor nosso Deus é o único Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 5, 'Amarás, pois, ao Senhor teu Deus de todo o teu coração, de toda a tua alma e de todas as tuas forças.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 6, 'E estas palavras, que hoje te ordeno, estarão no teu coração;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 7, 'e as ensinarás a teus filhos, e delas falarás sentado em tua casa e andando pelo caminho, ao deitar-te e ao levantar-te.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 8, 'Também as atarás por sinal na tua mão e te serão por frontais entre os teus olhos;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 9, 'e as escreverás nos umbrais de tua casa, e nas tuas portas.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 10, 'Quando, pois, o Senhor teu Deus te introduzir na terra que com juramento prometeu a teus pais, Abraão, Isaque e Jacó, que te daria, com grandes e boas cidades, que tu não edificaste,', 1, CURRENT_TIMESTAMP, false),
(5, 6, 11, 'e casas cheias de todo o bem, as quais tu não encheste, e poços cavados, que tu não cavaste, vinhas e olivais, que tu não plantaste, e quando comeres e te fartares;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 12, 'guarda-te, que não te esqueças do Senhor, que te tirou da terra do Egito, da casa da servidão.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 13, 'Temerás ao Senhor teu Deus e o servirás, e pelo seu nome jurarás.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 14, 'Não seguirás outros deuses, os deuses dos povos que houver à roda de ti;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 15, 'porque o Senhor teu Deus é um Deus zeloso no meio de ti; para que a ira do Senhor teu Deus não se acenda contra ti, e ele te destrua de sobre a face da terra.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 16, 'Não tentareis o Senhor vosso Deus, como o tentastes em Massá.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 17, 'Diligentemente guardarás os mandamentos do Senhor teu Deus, como também os seus testemunhos, e seus estatutos, que te ordenou.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 18, 'Também praticarás o que é reto e bom aos olhos do Senhor, para que te vá bem, e entres, e possuas a boa terra, a qual o Senhor prometeu com juramento a teus pais;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 19, 'para que lance fora de diante de ti todos os teus inimigos, como disse o Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 20, 'Quando teu filho te perguntar no futuro, dizendo: Que significam os testemunhos, estatutos e preceitos que o Senhor nosso Deus vos ordenou?', 1, CURRENT_TIMESTAMP, false),
(5, 6, 21, 'responderás a teu filho: Éramos servos de Faraó no Egito, porém o Senhor, com mão forte, nos tirou de lá;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 22, 'e, aos nossos olhos, o Senhor fez sinais e maravilhas grandes e penosas contra o Egito, contra Faraó e contra toda a sua casa;', 1, CURRENT_TIMESTAMP, false),
(5, 6, 23, 'mas nos tirou de lá, para nos introduzir e nos dar a terra que com juramento prometera a nossos pais.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 24, 'Pelo que o Senhor nos ordenou que observássemos todos estes estatutos, que temêssemos o Senhor nosso Deus, para o nosso bem em todo o tempo, a fim de que ele nos preservasse em vida, assim como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(5, 6, 25, 'E será justiça para nós, se tivermos cuidado de cumprir todos estes mandamentos perante o Senhor nosso Deus, como ele nos ordenou.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 1, 'Quando o Senhor teu Deus te houver introduzido na terra a que vais a fim de possuí-la, e tiver lançado fora de diante de ti muitas nações, a saber, os heteus, os girgaseus, os amorreus, os cananeus, os perizeus, os heveus e os jebuseus, sete nações mais numerosas e mais poderosas do que tu;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 2, 'e quando o Senhor teu Deus as tiver entregue, e as ferires, totalmente as destruirás; não farás com elas pacto algum, nem terás piedade delas;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 3, 'não contrairás com elas matrimônios; não darás tuas filhas a seus filhos, e não tomarás suas filhas para teus filhos;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 4, 'pois fariam teus filhos desviarem-se de mim, para servirem a outros deuses; e a ira do Senhor se acenderia contra vós, e depressa vos consumiria.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 5, 'Mas assim lhes fareis: Derrubareis os seus altares, quebrareis as suas colunas, cortareis os seus aserins, e queimareis a fogo as suas imagens esculpidas.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 6, 'Porque tu és povo santo ao Senhor teu Deus; o Senhor teu Deus te escolheu, a fim de lhe seres o seu próprio povo, acima de todos os povos que há sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 7, 'O Senhor não tomou prazer em vós nem vos escolheu porque fôsseis mais numerosos do que todos os outros povos, pois éreis menos em número do que qualquer povo;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 8, 'mas, porque o Senhor vos amou, e porque quis guardar o juramento que fizera a vossos pais, foi que vos tirou com mão forte e vos resgatou da casa da servidão, da mão de Faraó, rei do Egito.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 9, 'Saberás, pois, que o Senhor teu Deus é que é Deus, o Deus fiel, que guarda o pacto e a misericórdia, até mil gerações, aos que o amam e guardam os seus mandamentos;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 10, 'e que retribui diretamente aos que o odeiam, para os destruir; não será remisso para quem o odeia, diretamente lhe retribuirá.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 11, 'Guardarás, pois, os mandamentos, os estatutos e os preceitos que eu hoje te ordeno, para os cumprires.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 12, 'Sucederá, pois, que, por ouvirdes estes preceitos, e os guardardes e cumprirdes, o Senhor teu Deus te guardará o pacto e a misericórdia que com juramento prometeu a teus pais;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 13, 'ele te amará, te abençoará e te fará multiplicar; abençoará o fruto do teu ventre, e o fruto da tua terra, o teu grão, o teu mosto e o teu azeite, a criação das tuas vacas, e as crias dos teus rebanhos, na terra que com juramento prometeu a teus pais te daria.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 14, 'Bendito serás mais do que todos os povos; não haverá estéril no meio de ti, seja homem, seja mulher, nem entre os teus animais.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 15, 'E o Senhor desviará de ti toda enfermidade; não porá sobre ti nenhuma das más doenças dos egípcios, que bem conheces; no entanto as porás sobre todos os que te odiarem.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 16, 'Consumirás todos os povos que o Senhor teu Deus te entregar; os teus olhos não terão piedade deles; e não servirás a seus deuses, pois isso te seria por laço.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 17, 'Se disseres no teu coração: Estas nações são mais numerosas do que eu; como as poderei desapossar?', 1, CURRENT_TIMESTAMP, false),
(5, 7, 18, 'delas não terás medo; antes lembrarte-ás do que o Senhor teu Deus fez a Faraó e a todos os egípcios;', 1, CURRENT_TIMESTAMP, false),
(5, 7, 19, 'das grandes provas que os teus olhos viram, e dos sinais, e das maravilhas, e da mão forte, e do braço estendido, com que o Senhor teu Deus te tirou: Assim fará o Senhor teu Deus a todos os povos, diante dos quais tu temes.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 20, 'Além disso o Senhor teu Deus mandará entre eles vespões, até que pereçam os restantes que se tiverem escondido de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 21, 'Não te espantes diante deles, porque o Senhor teu Deus está no meio de ti, Deus grande e terrível.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 22, 'E o Senhor teu Deus lançará fora de diante de ti, pouco a pouco, estas nações; não poderás destruí-las todas de pronto, para que as feras do campo não se multipliquem contra ti.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 23, 'E o Senhor as entregará a ti, e lhes infligirá uma grande derrota, até que sejam destruídas.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 24, 'Também os seus reis te entregará nas tuas mãos, e farás desaparecer o nome deles de debaixo do céu; nenhum te poderá resistir, até que os tenhas destruído.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 25, 'As imagens esculpidas de seus deuses queimarás a fogo; não cobiçarás a prata nem o ouro que estão sobre elas, nem deles te apropriarás, para que não te enlaces neles; pois são abominação ao Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 7, 26, 'Não meterás, pois, uma abominação em tua casa, para que não sejas anátema, semelhante a ela; de todo a detestarás, e de todo a abominarás, pois é anátema.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 1, 'Todos os mandamentos que hoje eu vos ordeno cuidareis de observar, para que vivais, e vos multipliqueis, e entreis, e possuais a terra que o Senhor, com juramento, prometeu a vossos pais.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 2, 'E te lembrarás de todo o caminho pelo qual o Senhor teu Deus tem te conduzido durante estes quarenta anos no deserto, a fim de te humilhar e te provar, para saber o que estava no teu coração, se guardarias ou não os seus mandamentos.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 3, 'Sim, ele te humilhou, e te deixou ter fome, e te sustentou com o maná, que nem tu nem teus pais conhecíeis; para te dar a entender que o homem não vive só de pão, mas de tudo o que sai da boca do Senhor, disso vive o homem.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 4, 'Não se envelheceram as tuas vestes sobre ti, nem se inchou o teu pé, nestes quarenta anos.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 5, 'Saberás, pois, no teu coração que, como um homem corrige a seu filho, assim te corrige o Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 6, 'E guardarás os mandamentos de Senhor teu Deus, para andares nos seus caminhos, e para o temeres.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 7, 'Porque o Senhor teu Deus te está introduzindo numa boa terra, terra de ribeiros de águas, de fontes e de nascentes, que brotam nos vales e nos outeiros;', 1, CURRENT_TIMESTAMP, false),
(5, 8, 8, 'terra de trigo e cevada; de vides, figueiras e romeiras; terra de oliveiras, de azeite e de mel;', 1, CURRENT_TIMESTAMP, false),
(5, 8, 9, 'terra em que comerás o pão sem escassez, e onde não te faltará coisa alguma; terra cujas pedras são ferro, e de cujos montes poderás cavar o cobre.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 10, 'Comerás, pois, e te fartarás, e louvarás ao Senhor teu Deus pela boa terra que te deu.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 11, 'Guarda-te, que não te esqueças do Senhor teu Deus, deixando de observar os seus mandamentos, os seus preceitos e os seus estatutos, que eu hoje te ordeno;', 1, CURRENT_TIMESTAMP, false),
(5, 8, 12, 'para não suceder que, depois de teres comido e estares farto, depois de teres edificado boas casas e estares morando nelas,', 1, CURRENT_TIMESTAMP, false),
(5, 8, 13, 'depois de se multiplicarem as tuas manadas e es teus rebanhos, a tua prata e o teu ouro, sim, depois de se multiplicar tudo quanto tens,', 1, CURRENT_TIMESTAMP, false),
(5, 8, 14, 'se exalte e teu coração e te esqueças do Senhor teu Deus, que te tirou da terra o Egito, da casa da servidão;', 1, CURRENT_TIMESTAMP, false),
(5, 8, 15, 'que te conduziu por aquele grande e terrível deserto de serpentes abrasadoras e de escorpiões, e de terra árida em que não havia água, e onde te fez sair água da rocha pederneira;', 1, CURRENT_TIMESTAMP, false),
(5, 8, 16, 'que no deserto te alimentou com o maná, que teus pais não conheciam; a fim de te humilhar e te provar, para nos teus últimos dias te fazer bem;', 1, CURRENT_TIMESTAMP, false),
(5, 8, 17, 'e digas no teu coração: A minha força, e a fortaleza da minha mão me adquiriram estas riquezas.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 18, 'Antes te lembrarás do Senhor teu Deus, porque ele é o que te dá força para adquirires riquezas; a fim de confirmar o seu pacto, que jurou a teus pais, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 19, 'Sucederá, porém, que, se de qualquer maneira te esqueceres de Senhor teu Deus, e se seguires após outros deuses, e os servires, e te encurvares perante eles, testifico hoje contra ti que certamente perecerás.', 1, CURRENT_TIMESTAMP, false),
(5, 8, 20, 'Como as nações que o Senhor vem destruindo diante de vós, assim vós perecereis, por não quererdes ouvir a voz do Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 1, 'Ouve, ó Israel: hoje tu vais passar o Jordão para entrares para desapossares nações maiores e mais fortes do que tu, cidades grandes e muradas até o céu;', 1, CURRENT_TIMESTAMP, false),
(5, 9, 2, 'um povo grande e alto, filhos dos anaquins, que tu conhecestes, e dos quais tens ouvido dizer: Quem poderá resistir aos filhos de Anaque?', 1, CURRENT_TIMESTAMP, false),
(5, 9, 3, 'Sabe, pois, hoje que o Senhor teu Deus é o que passa adiante de ti como um fogo consumidor; ele os destruirá, e os subjugará diante de ti; e tu os lançarás fora, e cedo os desfarás, como o Senhor te prometeu.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 4, 'Depois que o Senhor teu Deus os tiver lançado fora de diante de ti, não digas no teu coração: por causa da minha justiça é que o Senhor me introduziu nesta terra para a possuir. Porque pela iniqüidade destas nações é que o Senhor as lança fora de diante de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 5, 'Não é por causa da tua justiça, nem pela retidão do teu coração que entras a possuir a sua terra, mas pela iniqüidade destas nações o Senhor teu Deus as lança fora de diante de ti, e para confirmar a palavra que o Senhor teu Deus jurou a teus pais, Abraão, Isaque e Jacó.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 6, 'Sabe, pois, que não é por causa da tua justiça que o Senhor teu Deus te dá esta boa terra para a possuíres, pois tu és povo de dura cerviz.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 7, 'Lembra-te, e não te esqueças, de como provocaste à ira o Senhor teu Deus no deserto; desde o dia em que saíste da terra do Egito, até que chegaste a este lugar, foste rebelde contra o Senhor;', 1, CURRENT_TIMESTAMP, false),
(5, 9, 8, 'também em Horebe provocastes à ira o Senhor, e o Senhor se irou contra vós para vos destruir.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 9, 'Quando subi ao monte a receber as tábuas de pedra, as tábuas do pacto que o Senhor fizera convosco, fiquei no monte quarenta dias e quarenta noites; não comi pão, nem bebi água.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 10, 'E o Senhor me deu as duas tábuas de pedra, escritas com o dedo de Deus; e nelas estavam escritas todas aquelas palavras que o Senhor tinha falado convosco no monte, do meio do fogo, no dia da assembléia.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 11, 'Sucedeu, pois, que ao fim dos quarenta dias e quarenta noites, o Senhor me deu as duas tábuas de pedra, as tábuas do pacto.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 12, 'E o Senhor me disse: Levanta-te, desce logo daqui, porque o teu povo, que tiraste do Egito, já se corrompeu; cedo se desviaram do caminho que eu lhes ordenei; fizeram para si uma imagem de fundição.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 13, 'Disse-me ainda o Senhor: Atentei para este povo, e eis que ele é povo de dura cerviz;', 1, CURRENT_TIMESTAMP, false),
(5, 9, 14, 'deixa-me que o destrua, e apague o seu nome de debaixo do céu; e farei de ti nação mais poderosa e mais numerosa do que esta.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 15, 'Então me virei, e desci do monte, o qual ardia em fogo; e as duas tábuas do pacto estavam nas minhas duas mãos.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 16, 'Olhei, e eis que havíeis pecado contra o Senhor vosso Deus; tínheis feito para vós um bezerro de fundição; depressa vos tínheis desviado do caminho que o Senhor vos ordenara.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 17, 'Peguei então das duas tábuas e, arrojando-as das minhas mãos, quebrei-as diante dos vossos olhos.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 18, 'Prostrei-me perante o Senhor, como antes, quarenta dias e quarenta noites; não comi pão, nem bebi água, por causa de todo o vosso pecado que havíeis cometido, fazendo o que era mau aos olhos do Senhor, para o provocar a ira.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 19, 'Porque temi por causa da ira e do furor com que o Senhor estava irado contra vós para vos destruir; porém ainda essa vez o Senhor me ouviu.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 20, 'O Senhor se irou muito contra Arão para o destruir; mas também orei a favor de Arão ao mesmo tempo.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 21, 'Então eu tomei o vosso pecado, o bezerro que tínheis feito, e o queimei a fogo e o pisei, moendo-o bem, até que se desfez em pó; e o seu pó lancei no ribeiro que descia do monte.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 22, 'Igualmente em Taberá, e em Massá, e em Quibrote-Hataavá provocastes à ira o Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 23, 'Quando também o Senhor vos enviou de Cades-Barnéia, dizendo: Subi, e possuí a terra que vos dei; vós vos rebelastes contra o mandado do Senhor vosso Deus, e não o crestes, e não obedecestes à sua voz.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 24, 'Tendes sido rebeldes contra o Senhor desde o dia em que vos conheci.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 25, 'Assim me prostrei perante o Senhor; quarenta dias e quarenta noites estive prostrado, porquanto o Senhor ameaçara destruir-vos.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 26, 'Orei ao Senhor, dizendo: ó Senhor Jeová, não destruas o teu povo, a tua herança, que resgataste com a tua grandeza, que tiraste do Egito com mão forte.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 27, 'Lembra-te dos teus servos, Abraão, Isaque e Jacó; não atentes para a dureza deste povo, nem para a sua iniqüidade, nem para o seu pecado;', 1, CURRENT_TIMESTAMP, false),
(5, 9, 28, 'para que o povo da terra de onde nos tiraste não diga: Porquanto o Senhor não pôde introduzi-los na terra que lhes prometera, passou a odiá-los, e os tirou para os matar no deserto.', 1, CURRENT_TIMESTAMP, false),
(5, 9, 29, 'Todavia são eles o teu povo, a sua herança, que tiraste com a sua grande força e com o teu braço estendido.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 1, 'Naquele mesmo tempo me disse o Senhor: Alisa duas tábuas de pedra, como as primeiras, e sobe a mim ao monte, e faze uma arca de madeira.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 2, 'Nessas tábuas escreverei as palavras que estavam nas primeiras tábuas, que quebras-te, e as porás na arca.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 3, 'Assim, fiz ume arca de madeira de acácia, alisei duas tábuas de pedra, como as primeiras, e subi ao monte com as duas tábuas nas mãos.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 4, 'Então o Senhor escreveu nas tábuas, conforme a primeira escritura, os dez mandamentos, que ele vos falara no monte, do meio do fogo, no dia da assembléia; e o Senhor mas deu a mim.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 5, 'Virei-me, pois, desci do monte e pus as tábuas na arca que fizera; e ali estão, como o Senhor me ordenou.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 6, '{Ora, partiram os filhos de Israel de Beerote-Bene-Jaacã para Mosera. Ali faleceu Arão e foi sepultado; e Eleazar, seu filho, administrou o sacerdócio em seu lugar.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 7, 'Dali partiram para Gudgoda, e de Gudgoda para Jotbatá, terra de ribeiros de águas.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 8, 'Por esse tempo o Senhor separou a tribo de Levi, para levar a arca do pacto do Senhor, para estar diante do Senhor, servindo-o, e para abençoar em seu nome até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 9, 'Pelo que Levi não tem parte nem herança com seus irmãos; o Senhor é a sua herança, como o Senhor teu Deus lhe disse.}', 1, CURRENT_TIMESTAMP, false),
(5, 10, 10, 'Também, como antes, eu estive no monte quarenta dias e quarenta noites; e o Senhor me ouviu ainda essa vez; o Senhor não te quis destruir;', 1, CURRENT_TIMESTAMP, false),
(5, 10, 11, 'antes disse-me o Senhor: Levanta-te, põe-te a caminho diante do povo; eles entrarão e possuirão a terra que com juramento prometi a seus pais lhes daria.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 12, 'Agora, pois, ó Israel, que é que o Senhor teu Deus requer de ti, senão que temas o Senhor teu Deus, que andes em todos os seus caminhos, e o ames, e sirvas ao Senhor teu Deus de todo o teu coração e de toda a tua alma,', 1, CURRENT_TIMESTAMP, false),
(5, 10, 13, 'que guardes os mandamentos do Senhor, e os seus estatutos, que eu hoje te ordeno para o teu bem?', 1, CURRENT_TIMESTAMP, false),
(5, 10, 14, 'Eis que do Senhor teu Deus são o céu e o céu dos céus, a terra e tudo o que nela há.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 15, 'Entretanto o Senhor se afeiçoou a teus pais para os amar; e escolheu a sua descendência depois deles, isto é, a vós, dentre todos os povos, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 16, 'Circuncidai, pois, o prepúcio do vosso coração, e não mais endureçais a vossa cerviz.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 17, 'Pois o Senhor vosso Deus, é o Deus dos deuses, e o Senhor dos senhores, o Deus grande, poderoso e terrível, que não faz acepção de pessoas, nem recebe peitas;', 1, CURRENT_TIMESTAMP, false),
(5, 10, 18, 'que faz justiça ao órfão e à viúva, e ama o estrangeiro, dando-lhe pão e roupa.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 19, 'Pelo que amareis o estrangeiro, pois fostes estrangeiros na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 20, 'Ao Senhor teu Deus temerás; a ele servirás, e a ele te apegarás, e pelo seu nome; jurarás.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 21, 'Ele é o teu louvor e o teu Deus, que te fez estas grandes e terríveis coisas que os teus olhos têm visto.', 1, CURRENT_TIMESTAMP, false),
(5, 10, 22, 'Com setenta almas teus pais desceram ao Egito; e agora o Senhor teu Deus te fez, em número, como as estrelas do céu.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 1, 'Amarás, pois, ao Senhor teu Deus, e guardarás as suas ordenanças, os seus estatutos, os seus preceitos e os seus mandamentos, por todos os dias.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 2, 'Considerai hoje {pois não falo com vossos filhos, que não conheceram, nem viram} a instrução do Senhor vosso Deus, a sua grandeza, a sua mão forte, e o seu braço estendido;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 3, 'os seus sinais, as suas obras, que fez no meio do Egito a Faraó, rei do Egito, e a toda a sua terra;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 4, 'o que fez ao exército dos egípcios, aos seus cavalos e aos seus carros; como fez passar sobre eles as águas do Mar Vermelho, quando vos perseguiam, e como o Senhor os destruiu até o dia de hoje;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 5, 'o que vos fez no deserto, até chegardes a este lugar;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 6, 'e o que fez a Datã e a Abirão, filhos de Eliabe, filho de Rúben; como a terra abriu a sua boca e os tragou com as suas casas e as suas tendas, e bem assim todo ser vivente que lhes pertencia, no meia de todo o Israel;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 7, 'porquanto os vossos olhos são os que viram todas as grandes obras que fez o Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 8, 'Guardareis, pois, todos os mandamentos que eu vos ordeno hoje, para que sejais fortes, e entreis, e ocupeis a terra a que estais passando para a possuirdes;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 9, 'e para que prolongueis os dias nessa terra que o Senhor, com juramento, prometeu dar a vossos pais e à sua descendência, terra que mana leite e mel.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 10, 'Pois a terra na qual estais entrando para a possuirdes não é como a terra do Egito, de onde saístes, em que semeáveis a vossa semente, e a regáveis com o vosso pé, como a uma horta;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 11, 'mas a terra a que estais passando para a possuirdes é terra de montes e de vales; da chuva do céu bebe as águas;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 12, 'terra de que o Senhor teu Deus toma cuidado; os olhos do Senhor teu Deus estão sobre ela continuamente, desde o princípio até o fim do ano.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 13, 'E há de ser que, se diligentemente obedeceres a meus mandamentos que eu hoje te ordeno, de amar ao Senhor teu Deus, e de o servir de todo o teu coração e de toda a tua alma,', 1, CURRENT_TIMESTAMP, false),
(5, 11, 14, 'darei a chuva da tua terra a seu tempo, a temporã e a serôdia, para que recolhas o teu grão, o teu mosto e o teu azeite;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 15, 'e darei erva no teu campo para o teu gado, e comerás e fartar-te-ás.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 16, 'Guardai-vos para que o vosso coração não se engane, e vos desvieis, e sirvais a outros deuses, e os adoreis;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 17, 'e a ira do Senhor se acenda contra vós, e feche ele o céu, e não caia chuva, e a terra não dê o seu fruto, e cedo pereçais da boa terra que o Senhor vos dá.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 18, 'Ponde, pois, estas minhas palavras no vosso coração e na vossa alma; atá-las-eis por sinal na vossa mão, e elas vos serão por frontais entre os vossos olhos;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 19, 'e ensiná-las-eis a vossos filhos, falando delas sentados em vossas casas e andando pelo caminho, ao deitar-vos e ao levantar-vos;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 20, 'e escrevê-las-eis nos umbrais de vossas casas, e nas vossas portas;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 21, 'para que se multipliquem os vossos dias e os dias de vossos filhos na terra que o Senhor, com juramento, prometeu dar a vossos pais, enquanto o céu cobrir a terra.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 22, 'Porque, se diligentemente guardardes todos estes mandamentos que eu vos ordeno, se amardes ao Senhor vosso Deus, e andardes em todos os seus caminhos, e a ele vos apegardes,', 1, CURRENT_TIMESTAMP, false),
(5, 11, 23, 'também o Senhor lançará fora de diante de vós todas estas nações, e possuireis nações maiores e mais poderosas do que vós.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 24, 'Todo lugar que pisar a planta do vosso pé será vosso; o vosso termo se estenderá do deserto ao Líbano, e do rio, o rio Eufrates, até o mar ocidental.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 25, 'Ninguém vos poderá resistir; o Senhor vosso Deus porá o medo e o terror de vós sobre toda a terra que pisardes, assim como vos disse.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 26, 'Vede que hoje eu ponho diante de vós a bênção e a maldição:', 1, CURRENT_TIMESTAMP, false),
(5, 11, 27, 'A bênção, se obedecerdes aos mandamentos do Senhor vosso Deus, que eu hoje vos ordeno;', 1, CURRENT_TIMESTAMP, false),
(5, 11, 28, 'porém a maldição, se não obedecerdes aos mandamentos do Senhor vosso Deus, mas vos desviardes do caminho que eu hoje vos ordeno, para seguirdes outros deuses que nunca conhecestes.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 29, 'Ora, quando o Senhor teu Deus te introduzir na terra a que vais para possuí-la, pronunciarás a bênção sobre o monte Gerizim, e a maldição sobre o monte Ebal.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 30, 'Porventura não estão eles além do Jordão, atrás do caminho do pôr do sol, na terra dos cananeus, que habitam na Arabá defronte de Gilgal, junto aos carvalhos de Moré?', 1, CURRENT_TIMESTAMP, false),
(5, 11, 31, 'Porque estais a passar o Jordão para entrardes a possuir a terra que o Senhor vosso Deus vos dá; e a possuireis, e nela habitareis.', 1, CURRENT_TIMESTAMP, false),
(5, 11, 32, 'Tende, pois, cuidado em observar todos os estatutos e os preceitos que eu hoje vos proponho.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 1, 'São estes os estatutos e os preceitos que tereis cuidado em observar na terra que o Senhor Deus de vossos pais vos deu para a possuirdes por todos os dias que viverdes sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 2, 'Certamente destruireis todos os lugares em que as nações que haveis de subjugar serviram aos seus deuses, sobre as altas montanhas, sobre os outeiros, e debaixo de toda árvore frondosa;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 3, 'e derrubareis os seus altares, quebrareis as suas colunas, queimareis a fogo os seus aserins, abatereis as imagens esculpidas dos seus deuses e apagareis o seu nome daquele lugar.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 4, 'Não fareis assim para com o Senhor vosso Deus;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 5, 'mas recorrereis ao lugar que o Senhor vosso Deus escolher de todas as vossas tribos para ali pôr o seu nome, para sua habitação, e ali vireis.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 6, 'A esse lugar trareis os vossos holocaustos e sacrifícios, e os vossos dízimos e a oferta alçada da vossa mão, e os vossos votos e ofertas voluntárias, e os primogênitos das vossas vacas e ovelhas;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 7, 'e ali comereis perante o Senhor vosso Deus, e vos alegrareis, vós e as vossas casas, em tudo em que puserdes a vossa mão, no que o Senhor vosso Deus vos tiver abençoado.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 8, 'Não fareis conforme tudo o que hoje fazemos aqui, cada qual tudo o que bem lhe parece aos olhos.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 9, 'Porque até agora não entrastes no descanso e na herança que o Senhor vosso Deus vos dá;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 10, 'mas quando passardes o Jordão, e habitardes na terra que o senhor vosso Deus vos faz herdar, ele vos dará repouso de todos os vossos inimigos em redor, e morareis seguros.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 11, 'Então haverá um lugar que o Senhor vosso Deus escolherá para ali fazer habitar o seu nome; a esse lugar trareis tudo o que eu vos ordeno: os vossos holocaustos e sacrifícios, os vossos dízimos, a oferta alçada da vossa mão, e tudo o que de melhor oferecerdes ao Senhor em cumprimento dos votos que fizerdes.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 12, 'E vos alegrareis perante o Senhor vosso Deus, vós, vossos filhos e vossas filhas, vossos servos e vossas servas, bem como o levita que está dentro das vossas portas, pois convosco não tem parte nem herança.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 13, 'Guarda-te de ofereceres os teus holocaustos em qualquer lugar que vires;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 14, 'mas no lugar que o Senhor escolher numa das tuas tribos, ali oferecerás os teus holocaustos, e ali farás tudo o que eu te ordeno.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 15, 'Todavia, conforme todo o teu desejo, poderás degolar, e comer carne dentro das tuas portas, segundo a bênção do Senhor teu Deus que ele te houver dado; tanto o imundo como o limpo comerão dela, como da gazela e do veado;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 16, 'tão-somente não comerás do sangue; sobre a terra o derramarás como água.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 17, 'Dentro das tuas portas não poderás comer o dízimo do teu grão, do teu mosto e do teu azeite, nem os primogênitos das tuas vacas e das tuas ovelhas, nem qualquer das tuas ofertas votivas, nem as tuas ofertas voluntárias, nem a oferta alçada da tua mão;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 18, 'mas os comerás perante o Senhor teu Deus, no lugar que ele escolher, tu, teu filho, tua filha, o teu servo, a tua serva, e bem assim e levita que está dentre das tuas portas; e perante o Senhor teu Deus te alegrarás em tudo em que puseres a mão.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 19, 'Guarda-te, que não desampares o levita por todos os dias que viveres na tua terra.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 20, 'Quando o Senhor teu Deus dilatar os teus termos, como te prometeu, e tu disseres: Comerei carne {porquanto tens desejo de comer carne}; conforme todo o teu desejo poderás comê-la.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 21, 'Se estiver longe de ti o lugar que o Senhor teu Deus escolher para ali pôr o seu nome, então degolarás do teu gado e do teu rebanho, que o Senhor te houver dado, como te ordenei; e poderás comer dentro das tuas portas, conforme todo o teu desejo.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 22, 'Como se come a gazela e o veado, assim comerás dessas carnes; o imundo e o limpo igualmente comerão delas.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 23, 'Tão-somente guarda-te de comeres o sangue; pois o sangue é a vida; pelo que não comerás a vida com a carne.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 24, 'Não o comerás; sobre a terra o derramarás como água.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 25, 'Não o comerás, para que te vá bem a ti, a teus filhos depois de ti, quando fizeres o que é reto aos olhos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 26, 'Somente tomarás as coisas santas que tiveres, e as tuas ofertas votivas, e irás ao lugar que o Senhor escolher;', 1, CURRENT_TIMESTAMP, false),
(5, 12, 27, 'oferecerás os teus holocaustos, a carne e o sangue sobre o altar do Senhor teu Deus; e o sangue dos teus sacrifícios se derramará sobre o altar do Senhor teu Deus, porém a carne comerás.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 28, 'Ouve e guarda todas estas palavras que eu te ordeno, para que te vá bem a ti, e a teus filhos depois de ti, para sempre, se fizeres o que é bom e reto aos olhos do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 29, 'Quando o Senhor teu Deus exterminar de diante de ti as nações aonde estás entrando para as possuir, e as desapossares e habitares na sua terra,', 1, CURRENT_TIMESTAMP, false),
(5, 12, 30, 'guarda-te para que não te enlaces para as seguires, depois que elas forem destruídas diante de ti; e que não perguntes acerca dos seus deuses, dizendo: De que modo serviam estas nações os seus deuses? pois do mesmo modo também farei eu.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 31, 'Não farás assim para com o Senhor teu Deus; porque tudo o que é abominável ao Senhor, e que ele detesta, fizeram elas para com os seus deuses; pois até seus filhos e suas filhas queimam no fogo aos seus deuses.', 1, CURRENT_TIMESTAMP, false),
(5, 12, 32, 'Tudo o que eu te ordeno, observarás; nada lhe acrescentarás nem diminuirás.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 1, 'Se levantar no meio de vós profeta, ou sonhador de sonhos, e vos anunciar um sinal ou prodígio,', 1, CURRENT_TIMESTAMP, false),
(5, 13, 2, 'e suceder o sinal ou prodígio de que vos houver falado, e ele disser: Vamos após outros deuses que nunca conhecestes, e sirvamo-los,', 1, CURRENT_TIMESTAMP, false),
(5, 13, 3, 'não ouvireis as palavras daquele profeta, ou daquele sonhador; porquanto o Senhor vosso Deus vos está provando, para saber se amais o Senhor vosso Deus de todo o vosso coração e de toda a vossa alma.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 4, 'Após o Senhor vosso Deus andareis, e a ele temereis; os seus mandamentos guardareis, e a sua voz ouvireis; a ele servireis, e a ele vos apegareis.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 5, 'E aquele profeta, ou aquele sonhador, morrerá, pois falou rebeldia contra o Senhor vosso Deus, que vos tirou da terra do Egito e vos resgatou da casa da servidão, para vos desviar do caminho em que o Senhor vosso Deus vos ordenou que andásseis; assim exterminareis o mal do meio vós.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 6, 'Quando teu irmão, filho da tua mãe, ou teu filho, ou tua filha, ou a mulher do teu seio, ou teu amigo que te é como a tua alma, te incitar em segredo, dizendo: Vamos e sirvamos a outros deuses!-deuses que nunca conheceste, nem tu nem teus pais,', 1, CURRENT_TIMESTAMP, false),
(5, 13, 7, 'dentre os deuses dos povos que estão em redor de ti, perto ou longe de ti, desde uma extremidade da terra até a outra-', 1, CURRENT_TIMESTAMP, false),
(5, 13, 8, 'não consentirás com ele, nem o ouvirás, nem o teu olho terá piedade dele, nem o pouparás, nem o esconderás,', 1, CURRENT_TIMESTAMP, false),
(5, 13, 9, 'mas certamente o matarás; a tua mão será a primeira contra ele para o matar, e depois a mão de todo o povo;', 1, CURRENT_TIMESTAMP, false),
(5, 13, 10, 'e o apedrejarás, até que morra, pois procurou apartar-te do Senhor teu Deus, que te tirou da terra do Egito, da casa da servidão.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 11, 'Todo o Israel o ouvirá, e temerá, e não se tornará a praticar semelhante iniqüidade no meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 12, 'Se, a respeito de alguma das tuas cidades que o Senhor teu Deus te dá para ali habitares, ouvires dizer:', 1, CURRENT_TIMESTAMP, false),
(5, 13, 13, 'Uns homens, filhos de Belial, saindo do meio de ti, incitaram os moradores da sua cidade, dizendo: Vamos, e sirvamos a outros deuses!-deuses que nunca conheceste-', 1, CURRENT_TIMESTAMP, false),
(5, 13, 14, 'então inquirirás e investigarás, perguntando com diligência; e se for verdade, se for certo que se fez tal abominação no meio de ti,', 1, CURRENT_TIMESTAMP, false),
(5, 13, 15, 'certamente ferirás ao fio da espada os moradores daquela cidade, destruindo a ela e a tudo o que nela houver, até os animais.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 16, 'E ajuntarás todo o seu despojo no meio da sua praça; e a cidade e todo o seu despojo queimarás totalmente para o Senhor teu Deus, e será montão perpétuo; nunca mais será edificada.', 1, CURRENT_TIMESTAMP, false),
(5, 13, 17, 'Não se te pegará às mãos nada do anátema; para que o Senhor se aparte do ardor da sua ira, e te faça misericórdia, e tenha piedade de ti, e te multiplique; como jurou a teus pais,', 1, CURRENT_TIMESTAMP, false),
(5, 13, 18, 'se ouvires a voz do Senhor teu Deus, para guardares todos os seus mandamentos, que eu hoje te ordeno, para fazeres o que é reto aos olhos do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 1, 'Filhos sois do Senhor vosso Deus; não vos cortareis a vós mesmos, nem abrireis calva entre vossos olhos por causa de algum morto.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 2, 'Porque és povo santo ao Senhor teu Deus, e o Senhor te escolheu para lhe seres o seu próprio povo, acima de todos os povos que há sobre a face da terra.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 3, 'Nenhuma coisa abominável comereis.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 4, 'Estes são os animais que comereis: o boi, a ovelha, a cabra,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 5, 'o veado, a gazela, o cabrito montês, a cabra montesa, o antílope, o órix e a ovelha montesa.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 6, 'Dentre os animais, todo o que tem a unha fendida, dividida em duas, e que rumina, esse podereis comer.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 7, 'Porém, dos que ruminam, ou que têm a unha fendida, não podereis comer os seguintes: o camelo, a lebre e o querogrilo, porque ruminam, mas não têm a unha fendida; imundos vos serão;', 1, CURRENT_TIMESTAMP, false),
(5, 14, 8, 'nem o porco, porque tem unha fendida, mas não rumina; imundo vos será. Não comereis da carne destes, e não tocareis nos seus cadáveres.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 9, 'Isto podereis comer de tudo o que há nas águas: tudo o que tem barbatanas e escamas podereis comer;', 1, CURRENT_TIMESTAMP, false),
(5, 14, 10, 'mas tudo o que não tem barbatanas nem escamas não comereis; imundo vos será.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 11, 'De todas as aves limpas podereis comer.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 12, 'Mas estas são as de que não comereis: a águia, o quebrantosso, o xofrango,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 13, 'o açor, o falcão, o milhafre segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 14, 'todo corvo segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 15, 'o avestruz, o mocho, a gaivota, o gavião segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 16, 'o bufo, a coruja, o porfirião,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 17, 'o pelicano, o abutre, o corvo marinho,', 1, CURRENT_TIMESTAMP, false),
(5, 14, 18, 'a cegonha, a garça segundo a sua espécie, a poupa e o morcego.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 19, 'Também todos os insetos alados vos serão imundos; não se comerão.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 20, 'De todas as aves limpas podereis comer.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 21, 'Não comerás nenhum animal que tenha morrido por si; ao peregrino que está dentro das tuas portas o darás a comer, ou o venderás ao estrangeiro; porquanto és povo santo ao Senhor teu Deus. Não cozerás o cabrito no leite de sua mãe.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 22, 'Certamente darás os dízimos de todo o produto da tua semente que cada ano se recolher do campo.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 23, 'E, perante o Senhor teu Deus, no lugar que escolher para ali fazer habitar o seu nome, comerás os dízimos do teu grão, do teu mosto e do teu azeite, e os primogênitos das tuas vacas e das tuas ovelhas; para que aprendas a temer ao Senhor teu Deus por todos os dias.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 24, 'Mas se o caminho te for tão comprido que não possas levar os dízimos, por estar longe de ti o lugar que Senhor teu Deus escolher para ali por o seu nome, quando o Senhor teu Deus te tiver abençoado;', 1, CURRENT_TIMESTAMP, false),
(5, 14, 25, 'então vende-os, ata o dinheiro na tua mão e vai ao lugar que o Senhor teu Deus escolher.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 26, 'E aquele dinheiro darás por tudo o que desejares, por bois, por ovelhas, por vinho, por bebida forte, e por tudo o que te pedir a tua alma; comerás ali perante o Senhor teu Deus, e te regozijarás, tu e a tua casa.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 27, 'Mas não desampararás o levita que está dentro das tuas portas, pois não tem parte nem herança contigo.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 28, 'Ao fim de cada terceiro ano levarás todos os dízimos da tua colheita do mesmo ano, e os depositarás dentro das tuas portas.', 1, CURRENT_TIMESTAMP, false),
(5, 14, 29, 'Então virá o levita {pois nem parte nem herança tem contigo}, o peregrino, o órfão, e a viúva, que estão dentro das tuas portas, e comerão, e fartar-se-ão; para que o Senhor teu Deus te abençoe em toda obra que as tuas mãos fizerem.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 1, 'Ao fim de cada sete anos farás remissão.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 2, 'E este é o modo da remissão: todo credor remitirá o que tiver emprestado ao seu próximo; não o exigirá do seu próximo ou do seu irmão, pois a remissão do Senhor é apregoada.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 3, 'Do estrangeiro poderás exigi-lo; mas o que é teu e estiver em poder de teu irmão, a tua mão o remitirá.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 4, 'Contudo não haverá entre ti pobre algum {pois o Senhor certamente te abençoará na terra que o Senhor teu Deus te dá por herança, para a possuíres},', 1, CURRENT_TIMESTAMP, false),
(5, 15, 5, 'contanto que ouças diligentemente a voz do Senhor teu Deus para cuidares em cumprir todo este mandamento que eu hoje te ordeno.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 6, 'Porque o Senhor teu Deus te abençoará, como te prometeu; assim, emprestarás a muitas nações, mas não tomarás empréstimos; e dominarás sobre muitas nações, porém elas não dominarão sobre ti.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 7, 'Quando no meio de ti houver algum pobre, dentre teus irmãos, em qualquer das tuas cidades na terra que o Senhor teu Deus te dá, não endurecerás o teu coração, nem fecharás a mão a teu irmão pobre;', 1, CURRENT_TIMESTAMP, false),
(5, 15, 8, 'antes lhe abrirás a tua mão, e certamente lhe emprestarás o que lhe falta, quanto baste para a sua necessidade.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 9, 'Guarda-te, que não haja pensamento vil no teu coração e venhas a dizer: Vai-se aproximando o sétimo ano, o ano da remissão; e que o teu olho não seja maligno para com teu irmão pobre, e não lhe dês nada; e que ele clame contra ti ao Senhor, e haja em ti pecado.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 10, 'Livremente lhe darás, e não fique pesaroso o teu coração quando lhe deres; pois por esta causa te abençoará o Senhor teu Deus em toda a tua obra, e em tudo no que puseres a mão.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 11, 'Pois nunca deixará de haver pobres na terra; pelo que eu te ordeno, dizendo: Livremente abrirás a mão para o teu irmão, para o teu necessitado, e para o teu pobre na tua terra.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 12, 'Se te for vendido um teu irmão hebreu ou irmã hebréia, seis anos te servirá, mas na sétimo ano o libertarás.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 13, 'E, quando o libertares, não o deixarás ir de mãos vazias;', 1, CURRENT_TIMESTAMP, false),
(5, 15, 14, 'liberalmente o fornecerás do teu rebanho, e da tua eira, e do teu lagar; conforme o Senhor teu Deus tiver abençoado te darás.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 15, 'Pois lembrar-te-ás de que foste servo na terra do Egito, e de que o Senhor teu Deus te resgatou; pelo que eu hoje te ordeno isso.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 16, 'Mas se ele te disser: Não sairei de junto de ti; porquanto te ama a ti e a tua casa, por estar bem contigo;', 1, CURRENT_TIMESTAMP, false),
(5, 15, 17, 'então tomarás uma sovela, e lhe furarás a orelha contra a porta, e ele será teu servo para sempre; e também assim farás à tua serva.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 18, 'Não seja duro aos teus olhos de teres de libertá-lo, pois seis anos te prestou serviço equivalente ao dobro do salário dum mercenário; e o Senhor teu Deus te abençoará em tudo o que fizeres.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 19, 'Todo primogênito que nascer das tuas vacas e das tuas ovelhas santificarás ao Senhor teu Deus; com o primogênito do teu boi não trabalharás, nem tosquiarás o primogênito das tuas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 20, 'Perante o Senhor teu Deus os comerás, tu e a tua casa, de ano em ano, no lugar que o Senhor escolher.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 21, 'Mas se nele houver algum defeito, como se for coxo, ou cego, ou tiver qualquer outra deformidade, não o sacrificarás ao Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 22, 'Nas tuas portas o comerás; o imundo e o limpo igualmente o comerão, como da gazela ou do veado.', 1, CURRENT_TIMESTAMP, false),
(5, 15, 23, 'Somente do seu sangue não comerás; sobre a terra o derramarás como água.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 1, 'Guarda o mês de abibe, e celebra a páscoa ao Senhor teu Deus; porque no mês de abibe, de noite, o Senhor teu Deus tirou-te do Egito.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 2, 'Então, das ovelhas e das vacas, sacrificarás a páscoa ao Senhor teu Deus, no lugar que o Senhor escolher para ali fazer habitar o seu nome.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 3, 'Nela não comerás pão levedado; por sete dias comerás pães ázimos, pão de aflição {porquanto apressadamente saíste da terra do Egito}, para que te lembres do dia da tua saída da terra do Egito, todos os dias da tua vida.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 4, 'O fermento não aparecerá contigo por sete dias em todos os teus termos; também da carne que sacrificares à tarde, no primeiro dia, nada ficará até pela manhã.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 5, 'Não poderás sacrificar a páscoa em qualquer uma das tuas cidades que o Senhor teu Deus te dá,', 1, CURRENT_TIMESTAMP, false),
(5, 16, 6, 'mas no lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome; ali sacrificarás a páscoa à tarde, ao pôr do sol, ao tempo determinado da tua saída do Egito.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 7, 'Então a cozerás, e comerás no lugar que o Senhor teu Deus escolher; depois, pela manhã, voltarás e irás às tuas tendas.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 8, 'Seis dias comerás pães ázimos, e no sétimo dia haverá assembléia solene ao Senhor teu Deus; nele nenhum trabalho farás.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 9, 'Sete semanas contarás; desde o dia em que começares a meter a foice na seara, começarás a contar as sete semanas.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 10, 'Depois celebrarás a festa das semanas ao Senhor teu Deus segundo a medida da oferta voluntária da tua mão, que darás conforme o Senhor teu Deus te houver abençoado.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 11, 'E te regozijarás perante o Senhor teu Deus, tu, teu filho e tua filha, teu servo e tua serva, o levita que está dentro das tuas portas, o peregrino, o órfão e a viúva que estão no meio de ti, no lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 12, 'Também te lembrarás de que foste servo no Egito, e guardarás estes estatutos, e os cumpriras.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 13, 'A festa dos tabernáculos celebrarás por sete dias, quando tiveres colhido da tua eira e do teu lagar.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 14, 'E na tua festa te regozijarás, tu, teu filho e tua filha, teu servo e tua serva, e o levita, o peregrino, o órfão e a viúva que estão dentro das tuas portas.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 15, 'sete dias celebrarás a festa ao Senhor teu Deus, no lugar que o senhor escolher; porque o Senhor teu Deus te há de abençoar em toda a tua colheita, e em todo trabalho das tuas mãos; pelo que estarás de todo alegre.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 16, 'Três vezes no ano todos os teus homens aparecerão perante o Senhor teu Deus, no lugar que ele escolher: na festa dos pães ázimos, na festa das semanas, e na festa dos tabernáculos. Não aparecerão vazios perante o Senhor;', 1, CURRENT_TIMESTAMP, false),
(5, 16, 17, 'cada qual oferecerá conforme puder, conforme a bênção que o Senhor teu Deus lhe houver dado.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 18, 'Juízes e oficiais porás em todas as tuas cidades que o Senhor teu Deus te dá, segundo as tuas tribos, para que julguem o povo com justiça.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 19, 'Não torcerás o juízo; não farás acepção de pessoas, nem receberás peitas; porque a peita cega os olhos dos sábios, e perverte a causa dos justos.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 20, 'A justiça, somente a justiça seguirás, para que vivas, e possuas em herança a terra que o Senhor teu Deus te dá.', 1, CURRENT_TIMESTAMP, false),
(5, 16, 21, 'Não plantarás nenhuma árvore como asera, ao pé do altar do Senhor teu Deus, que fizeres,', 1, CURRENT_TIMESTAMP, false),
(5, 16, 22, 'nem levantarás para ti coluna, coisas que o Senhor teu Deus detesta.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 1, 'Ao Senhor teu Deus não sacrificarás boi ou ovelha em que haja defeito ou qualquer deformidade; pois isso é abominação ao senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 2, 'Se no meio de ti, em alguma das tuas cidades que te dá o Senhor teu Deus, for encontrado algum homem ou mulher que tenha feito o que é mau aos olhos do Senhor teu Deus, transgredindo o seu pacto,', 1, CURRENT_TIMESTAMP, false),
(5, 17, 3, 'que tenha ido e servido a outros deuses, adorando-os, a eles, ou ao sol, ou à lua, ou a qualquer astro do exército do céu {o que não ordenei},', 1, CURRENT_TIMESTAMP, false),
(5, 17, 4, 'e isso te for denunciado, e o ouvires, então o inquirirás bem; e eis que, sendo realmente verdade que se fez tal abominação em Israel,', 1, CURRENT_TIMESTAMP, false),
(5, 17, 5, 'então levarás às tuas portas o homem, ou a mulher, que tiver cometido esta maldade, e apedrejarás o tal homem, ou mulher, até que morra.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 6, 'Pela boca de duas ou de três testemunhas, será morto o que houver de morrer; pela boca duma só testemunha não morrerá.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 7, 'A mão das testemunhas será a primeira contra ele, para matá-lo, e depois a mão de todo o povo; assim exterminarás o mal do meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 8, 'Se alguma causa te for difícil demais em juízo, entre sangue e sangue, entre demanda e demanda, entre ferida e ferida, tornando-se motivo de controvérsia nas tuas portas, então te levantarás e subirás ao lugar que o Senhor teu Deus escolher;', 1, CURRENT_TIMESTAMP, false),
(5, 17, 9, 'virás aos levitas sacerdotes, e ao juiz que houver nesses dias, e inquirirás; e eles te anunciarão a sentença da juízo.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 10, 'Depois cumprirás fielmente a sentença que te anunciarem no lugar que o Senhor escolher; e terás cuidado de fazer conforme tudo o que te ensinarem.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 11, 'Conforme o teor da lei que te ensinarem, e conforme o juízo que pronunciarem, farás da palavra que te disserem não te desviarás, nem para a direita nem para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 12, 'O homem que se houver soberbamente, não dando ouvidos ao sacerdote, que está ali para servir ao Senhor teu Deus, nem ao juiz, esse homem morrerá; assumirá de Israel o mal.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 13, 'E todo o povo, ouvindo isso, temerá e nunca mais se ensoberbecerá.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 14, 'Quando entrares na terra que o Senhor teu Deus te dá, e a possuíres e, nela habitando, disseres: Porei sobre mim um rei, como o fazem todas as nações que estão em redor de mim;', 1, CURRENT_TIMESTAMP, false),
(5, 17, 15, 'porás certamente sobre ti como rei aquele que o Senhor teu Deus escolher. Porás um dentre teus irmãos como rei sobre ti; não poderás pôr sobre ti um estrangeiro, homem que não seja de teus irmãos.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 16, 'Ele, porém, não multiplicará para si cavalos, nem fará voltar o povo ao Egito, para multiplicar cavalos; pois o Senhor vos tem dito: Nunca mais voltareis por este caminho.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 17, 'Tampouco multiplicará para si mulheres, para que o seu coração não se desvie; nem multiplicará muito para si a prata e o ouro.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 18, 'Será também que, quando se assentar sobre o trono do seu reino, escreverá para si, num livro, uma cópia desta lei, do exemplar que está diante dos levitas sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(5, 17, 19, 'E o terá consigo, e nele lerá todos os dias da sua vida, para que aprenda a temer ao Senhor seu Deus, e a guardar todas as palavras desta lei, e estes estatutos, a fim de os cumprir;', 1, CURRENT_TIMESTAMP, false),
(5, 17, 20, 'para que seu coração não se exalte sobre seus irmãos, e não se aparte do mandamento, nem para a direita nem para a esquerda; a fim de que prolongue os seus dias no seu reino, ele e seus filhos, no meio de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 1, 'Os levitas sacerdotes, e toda a tribo de Levi, não terão parte nem herança com Israel. Comerão das ofertas queimadas do Senhor e da herança dele.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 2, 'Não terão herança no meio de seus irmãos; o Senhor é a sua herança, como lhes tem dito.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 3, 'Este, pois, será o direito dos sacerdotes, a receber do povo, dos que oferecerem sacrifícios de boi ou de ovelha: o ofertante dará ao sacerdote a espádua, as queixadas e o bucho.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 4, 'Ao sacerdote darás as primícias do teu grão, do teu mosto e do teu azeite, e as primícias da tosquia das tuas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 5, 'Porque o Senhor teu Deus o escolheu dentre todas as tribos, para assistir e ministrar em nome do Senhor, ele e seus filhos, para sempre.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 6, 'Se um levita, saindo de alguma das tuas cidades de todo o Israel em que ele estiver habitando, vier com todo o desejo da sua alma ao lugar que o Senhor escolher,', 1, CURRENT_TIMESTAMP, false),
(5, 18, 7, 'e ministrar em nome do Senhor seu Deus, como o fazem todos os seus irmãos, os levitas, que assistem ali perante o Senhor,', 1, CURRENT_TIMESTAMP, false),
(5, 18, 8, 'comerá porção igual à deles, fora a das vendas do seu patrimônio.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 9, 'Quando entrares na terra que o Senhor teu Deus te dá, não aprenderás a fazer conforme as abominações daqueles povos.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 10, 'Não se achará no meio de ti quem faça passar pelo fogo o seu filho ou a sua filha, nem adivinhador, nem prognosticador, nem agoureiro, nem feiticeiro,', 1, CURRENT_TIMESTAMP, false),
(5, 18, 11, 'nem encantador, nem quem consulte um espírito adivinhador, nem mágico, nem quem consulte os mortos;', 1, CURRENT_TIMESTAMP, false),
(5, 18, 12, 'pois todo aquele que faz estas coisas é abominável ao Senhor, e é por causa destas abominações que o Senhor teu Deus os lança fora de diante de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 13, 'Perfeito serás para com o Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 14, 'Porque estas nações, que hás de possuir, ouvem os prognosticadores e os adivinhadores; porém, quanto a ti, o Senhor teu Deus não te permitiu tal coisa.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 15, 'O Senhor teu Deus te suscitará do meio de ti, dentre teus irmãos, um profeta semelhante a mim; a ele ouvirás;', 1, CURRENT_TIMESTAMP, false),
(5, 18, 16, 'conforme tudo o que pediste ao Senhor teu Deus em Horebe, no dia da assembléia, dizendo: Não ouvirei mais a voz do Senhor meu Deus, nem mais verei este grande fogo, para que não morra.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 17, 'Então o Senhor me disse: Falaram bem naquilo que disseram.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 18, 'Do meio de seus irmãos lhes suscitarei um profeta semelhante a ti; e porei as minhas palavras na sua boca, e ele lhes falará tudo o que eu lhe ordenar.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 19, 'E de qualquer que não ouvir as minhas palavras, que ele falar em meu nome, eu exigirei contas.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 20, 'Mas o profeta que tiver a presunção de falar em meu nome alguma palavra que eu não tenha mandado falar, ou o que falar em nome de outros deuses, esse profeta morrerá.', 1, CURRENT_TIMESTAMP, false),
(5, 18, 21, 'E, se disseres no teu coração: Como conheceremos qual seja a palavra que o Senhor falou?', 1, CURRENT_TIMESTAMP, false),
(5, 18, 22, 'Quando o profeta falar em nome do Senhor e tal palavra não se cumprir, nem suceder assim, esta é a palavra que o Senhor não falou; com presunção a falou o profeta; não o temerás.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 1, 'Quando o Senhor teu Deus desarraigar as nações cuja terra ele te dá, e tu as desapossares, e morares nas suas cidades e nas suas casas,', 1, CURRENT_TIMESTAMP, false),
(5, 19, 2, 'designarás para ti no meio da terra que o Senhor teu Deus te dá para a possuíres, três cidades;', 1, CURRENT_TIMESTAMP, false),
(5, 19, 3, 'preparar-lhe-ás caminhos, e partirás em três os termos da tua terra, que o Senhor teu Deus te dará em herança; isto será para que todo homicida se acolha nessas cidades.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 4, 'Este, pois é o caso no tocante ao homicida que se acolher ali para que viva: aquele que involuntariamente matar o seu próximo, a quem dantes não odiava;', 1, CURRENT_TIMESTAMP, false),
(5, 19, 5, 'como, por exemplo, aquele que entrar com o seu próximo no bosque para cortar lenha e, pondo força na sua mão com o machado para cortar a árvore, o ferro saltar do cabo e ferir o seu próximo de sorte que venha a morrer; o tal se acolherá a uma dessas cidades, e viverá;', 1, CURRENT_TIMESTAMP, false),
(5, 19, 6, 'para que o vingador do sangue não persiga o homicida, enquanto estiver abrasado o seu coração, e o alcance, por ser comprido o caminho, e lhe tire a vida, não havendo nele culpa de morte, pois que dantes não odiava o seu próximo.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 7, 'Pelo que eu te deu esta ordem: Três cidades designarás para ti.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 8, 'E, se o Senhor teu Deus dilatar os teus termos, como jurou a teus pais, e te der toda a terra que prometeu dar a teus pais', 1, CURRENT_TIMESTAMP, false),
(5, 19, 9, '{quando guardares, para o cumprires, todo este mandamento que eu hoje te ordeno, de amar o Senhor teu Deus e de andar sempre nos seus caminhos}, então acrescentarás a estas três, mais três cidades;', 1, CURRENT_TIMESTAMP, false),
(5, 19, 10, 'para que não se derrame sangue inocente no meio da tua terra, que o Senhor teu Deus te dá por herança, e não haja sangue sobre ti.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 11, 'Mas se alguém, odiando a seu próximo e lhe armando ciladas, se levantar contra ele e o ferir de modo que venha a morrer, e se acolher a alguma destas cidades,', 1, CURRENT_TIMESTAMP, false),
(5, 19, 12, 'então os anciãos da sua cidade, mandando tirá-lo dali, o entregarão nas mãos do vingador do sangue, para que morra.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 13, 'O teu olho não terá piedade dele; antes tirarás de Israel o sangue inocente, para que te vá bem.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 14, 'Não removerás os marcos do teu próximo, colocados pelos teus antecessores na tua herança que receberás, na terra que o Senhor teu Deus te dá para a possuíres.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 15, 'uma só testemunha não se levantará contra alguém por qualquer iniqüidade, ou por qualquer pecado, seja qual for o pecado cometido; pela boca de duas ou de três testemunhas se estabelecerá o fato.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 16, 'Se uma testemunha iníqua se levantar contra alguém, para o acusar de transgressão,', 1, CURRENT_TIMESTAMP, false),
(5, 19, 17, 'então aqueles dois homens que tiverem a demanda se apresentarão perante o Senhor, diante dos sacerdotes e dos juízes que houver nesses dias.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 18, 'E os juízes inquirirão cuidadosamente; e eis que, sendo a testemunha falsa, e falso o testemunho que deu contra seu irmão,', 1, CURRENT_TIMESTAMP, false),
(5, 19, 19, 'far-lhe-ás como ele cuidava fazer a seu irmão; e assim exterminarás o mal do meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 20, 'Os restantes, ouvindo isso, temerão e nunca mais cometerão semelhante mal no meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 19, 21, 'O teu olho não terá piedade dele; vida por vida, olho por olho, dente por dente, mão por mão, pé por pé.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 1, 'Quando saíres à peleja, contra teus inimigos, e vires cavalos, e carros, e povo mais numeroso do que tu, deles não terás temor, pois contigo está o Senhor teu Deus que te fez subir da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 2, 'Quando estiveres para entrar na peleja, o sacerdote se chegará e falará ao povo,', 1, CURRENT_TIMESTAMP, false),
(5, 20, 3, 'e lhe dirá: Ouvi, é Israel; vós estais hoje para entrar na peleja contra os vossos inimigos; não se amoleça o vosso coração; não temais nem tremais, nem vos aterrorizeis diante deles;', 1, CURRENT_TIMESTAMP, false),
(5, 20, 4, 'pois e Senhor vosso Deus é o que vai convosco, a pelejar por vós contra os vossos inimigos, para vos salvar.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 5, 'Então os oficiais falarão ao povo, dizendo: Qual é o homem que edificou casa nova e ainda não a dedicou? vá, e torne para casa; não suceda que morra na peleja e outro a dedique.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 6, 'E qual é o homem que plantou uma vinha e ainda não a desfrutou, vá, e torne para casa; não suceda que morra na peleja e outro a desfrute.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 7, 'Também qual é e homem que está desposado com uma mulher e ainda não a recebeu? vá, e torne para casa; não suceda que morra na peleja e outro a receba.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 8, 'Assim continuarão os oficiais a falar ao povo, dizendo: Qual é o homem medroso e de coração tímido? vá, e torne para casa, a fim de que o coração de seus irmãos não se derreta como o seu coração.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 9, 'Então, tendo os oficiais, acabado de falar ao povo, designarão chefes das tropas para estarem à frente do povo.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 10, 'Quando te aproximares duma cidade para combatê-la, apregoar-lhe-ás paz.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 11, 'Se ela te responder em paz, e te abrir as portas, todo o povo que se achar nela será sujeito a trabalhos forçados e te servirá.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 12, 'Se ela, pelo contrário, não fizer paz contigo, mas guerra, então a sitiarás,', 1, CURRENT_TIMESTAMP, false),
(5, 20, 13, 'e logo que o Senhor teu Deus a entregar nas tuas mãos, passarás ao fio da espada todos os homens que nela houver;', 1, CURRENT_TIMESTAMP, false),
(5, 20, 14, 'porém as mulheres, os pequeninos, os animais e tudo o que houver na cidade, todo o seu despojo, tomarás por presa; e comerás o despojo dos teus inimigos, que o Senhor teu Deus te deu.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 15, 'Assim farás a todas as cidades que estiverem mais longe de ti, que não são das cidades destas nações.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 16, 'Mas, das cidades destes povos, que o Senhor teu Deus te dá em herança, nada que tem fôlego deixarás com vida;', 1, CURRENT_TIMESTAMP, false),
(5, 20, 17, 'antes destruí-los-ás totalmente: aos heteus, aos amorreus, aos cananeus, aos perizeus, aos heveus, e aos jebuseus; como Senhor teu Deus te ordenou;', 1, CURRENT_TIMESTAMP, false),
(5, 20, 18, 'para que não vos ensinem a fazer conforme todas as abominações que eles fazem a seus deuses, e assim pequeis contra o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 20, 19, 'Quando sitiares uma cidade por muitos dias, pelejando contra ela para a tomar, não destruirás o seu arvoredo, metendo nele o machado, porque dele poderás comer; pelo que não o cortarás; porventura a árvore do campo é homem, para que seja sitiada por ti?', 1, CURRENT_TIMESTAMP, false),
(5, 20, 20, 'Somente as árvores que souberes não serem árvores cujo fruto se pode comer, é que destruirás e cortarás, e contra a cidade que guerrear contra ti edificarás baluartes, até que seja vencida.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 1, 'Se na terra que o Senhor teu Deus te dá para a possuíres, for encontrado algum morto caído no campo, sem que se saiba quem o matou,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 2, 'sairão os teus anciãos e os teus juízes, e medirão as distâncias dali até as cidades que estiverem em redor do morto;', 1, CURRENT_TIMESTAMP, false),
(5, 21, 3, 'e será que, na cidade mais próxima do morto, os anciãos da mesma tomarão uma novilha da manada, que ainda não tenha trabalhado nem tenha puxado na canga,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 4, 'trarão a novilha a um vale de águas correntes, que nunca tenha sido lavrado nem semeado, e ali, naquele vale, quebrarão o pescoço à novilha.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 5, 'Então se achegarão os sacerdotes, filhos de Levi; pois o Senhor teu Deus os escolheu para o servirem, e para abençoarem em nome do Senhor; e segundo a sua sentença se determinará toda demanda e todo ferimento;', 1, CURRENT_TIMESTAMP, false),
(5, 21, 6, 'e todos os anciãos da mesma cidade, a mais próxima do morto, lavarão as mãos sobre a novilha cujo pescoço foi quebrado no vale,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 7, 'e, protestando, dirão: As nossas mãos não derramaram este sangue, nem os nossos olhos o viram.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 8, 'Perdoa, ó Senhor, ao teu povo Israel, que tu resgataste, e não ponhas o sangue inocente no meio de teu povo Israel. E aquele sangue lhe será perdoado.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 9, 'Assim tirarás do meio de ti o sangue inocente, quando fizeres o que é reto aos olhos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 10, 'Quando saíres à peleja contra os teus inimigos, e o Senhor teu Deus os entregar nas tuas mãos, e os levares cativos,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 11, 'se vires entre os cativas uma mulher formosa à vista e, afeiçoando-te a ela, quiseres tomá-la por mulher,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 12, 'então a trarás para a tua casa; e ela, tendo rapado a cabeça, cortado as unhas,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 13, 'e despido as vestes do seu cativeiro, ficará na tua casa, e chorará a seu pai e a sua mãe um mês inteiro; depois disso estarás com ela, e serás seu marido e ela será tua mulher.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 14, 'E, se te enfadares dela, deixá-la-ás ir à sua vontade; mas de modo nenhum a venderás por dinheiro, nem a tratarás como escrava, porque a humilhaste.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 15, 'Se um homem tiver duas mulheres, uma a quem ama e outra a quem despreza, e ambas lhe tiverem dado filhos, e o filho primogênito for da desprezada,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 16, 'quando fizer herdar a seus filhos o que tiver, não poderá dar a primogenitura ao filho da amada, preferindo-o ao filha da desprezada, que é o primogênito;', 1, CURRENT_TIMESTAMP, false),
(5, 21, 17, 'mas ao filho da aborrecida reconhecerá por primogênito, dando-lhe dobrada porção de tudo quanto tiver, porquanto ele é as primícias da sua força; o direito da primogenitura é dele.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 18, 'Se alguém tiver um filho contumaz e rebelde, que não obedeça à voz de seu pai e à voz de sua mãe, e que, embora o castiguem, não lhes dê ouvidos,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 19, 'seu pai e sua mãe, pegando nele, o levarão aos anciãos da sua cidade, e à porta do seu lugar;', 1, CURRENT_TIMESTAMP, false),
(5, 21, 20, 'e dirão aos anciãos da cidade: Este nosso filho é contumaz e rebelde; não dá ouvidos à nossa voz; é comilão e beberrão.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 21, 'Então todos os homens da sua cidade o apedrejarão, até que morra; assim exterminarás o mal do meio de ti; e todo o Israel, ouvindo isso, temerá.', 1, CURRENT_TIMESTAMP, false),
(5, 21, 22, 'Se um homem tiver cometido um pecado digno de morte, e for morto, e o tiveres pendurado num madeiro,', 1, CURRENT_TIMESTAMP, false),
(5, 21, 23, 'o seu cadáver não permanecerá toda a noite no madeiro, mas certamente o enterrarás no mesmo dia; porquanto aquele que é pendurado é maldito de Deus. Assim não contaminarás a tua terra, que o Senhor teu Deus te dá em herança.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 1, 'Se vires extraviado o boi ou a ovelha de teu irmão, não te desviarás deles; sem falta os reconduzirás a teu irmão.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 2, 'E se teu irmão não estiver perto de ti ou não o conheceres, levá-los-ás para tua casa e ficarão contigo até que teu irmão os venha procurar; então lhes restituirás.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 3, 'Assim farás também com o seu jumento, bem como com as suas vestes, e com toda coisa que teu irmão tiver perdido e tu achares; não te poderás desviar deles.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 4, 'Se vires o jumento ou o boi de teu irmão caídos no caminho, não te desviarás deles; sem falta o ajudarás a levantá-los.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 5, 'Não haverá traje de homem na mulher, e não vestirá o homem vestido de mulher, porque qualquer que faz isto é abominação ao Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 6, 'Se encontrares pelo caminho, numa árvore ou no chão, um ninho de ave com passarinhos ou ovos, e a mãe posta sobre os passarinhos, ou sobre os ovos, não temerás a mãe com os filhotes;', 1, CURRENT_TIMESTAMP, false),
(5, 22, 7, 'sem falta deixarás ir a mãe, porém os filhotes poderás tomar; para que te vá bem, e para que prolongues os teus dias.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 8, 'Quando edificares uma casa nova, farás no terraço um parapeito, para que não tragas sangue sobre a tua casa, se alguém dali cair.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 9, 'Não semearás a tua vinha de duas espécies de semente, para que não fique sagrado todo o produto, tanto da semente que semeares como do fruto da vinha.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 10, 'Não lavrarás com boi e jumento juntamente.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 11, 'Não te vestirás de estofo misturado, de lã e linho juntamente.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 12, 'Porás franjas nos quatro cantos da tua manta, com que te cobrires.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 13, 'Se um homem tomar uma mulher por esposa, e, tendo coabitado com ela, vier a desprezá-la,', 1, CURRENT_TIMESTAMP, false),
(5, 22, 14, 'e lhe atribuir coisas escandalosas, e contra ela divulgar má fama, dizendo: Tomei esta mulher e, quando me cheguei a ela, não achei nela os sinais da virgindade;', 1, CURRENT_TIMESTAMP, false),
(5, 22, 15, 'então o pai e a mãe da moça tomarão os sinais da virgindade da moça, e os levarão aos anciãos da cidade, à porta;', 1, CURRENT_TIMESTAMP, false),
(5, 22, 16, 'e o pai da moça dirá aos anciãos: Eu dei minha filha por mulher a este homem, e agora ele a despreza,', 1, CURRENT_TIMESTAMP, false),
(5, 22, 17, 'e eis que lhe atribuiu coisas escandalosas, dizendo: Não achei na tua filha os sinais da virgindade; porém eis aqui os sinais da virgindade de minha filha. E eles estenderão a roupa diante dos anciãos da cidade.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 18, 'Então os anciãos daquela cidade, tomando o homem, o castigarão,', 1, CURRENT_TIMESTAMP, false),
(5, 22, 19, 'e, multando-o em cem siclos de prata, os darão ao pai da moça, porquanto divulgou má fama sobre uma virgem de Israel. Ela ficará sendo sua mulher, e ele por todos os seus dias não poderá repudiá-la.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 20, 'Se, porém, esta acusação for confirmada, não se achando na moça os sinais da virgindade,', 1, CURRENT_TIMESTAMP, false),
(5, 22, 21, 'levarão a moça à porta da casa de seu pai, e os homens da sua cidade a apedrejarão até que morra; porque fez loucura em Israel, prostituindo-se na casa de seu pai. Assim exterminarás o mal do meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 22, 'Se um homem for encontrado deitado com mulher que tenha marido, morrerão ambos, o homem que se tiver deitado com a mulher, e a mulher. Assim exterminarás o mal de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 23, 'Se houver moça virgem desposada e um homem a achar na cidade, e se deitar com ela,', 1, CURRENT_TIMESTAMP, false),
(5, 22, 24, 'trareis ambos à porta daquela cidade, e os apedrejareis até que morram: a moça, porquanto não gritou na cidade, e o homem, porquanto humilhou a mulher do seu próximo. Assim exterminarás o mal do meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 25, 'Mas se for no campo que o homem achar a moça que é desposada, e o homem a forçar, e se deitar com ela, morrerá somente o homem que se deitou com ela;', 1, CURRENT_TIMESTAMP, false),
(5, 22, 26, 'porém, à moça não farás nada. Não há na moça pecado digno de morte; porque, como no caso de um homem que se levanta contra o seu próximo e lhe tira a vida, assim é este caso;', 1, CURRENT_TIMESTAMP, false),
(5, 22, 27, 'pois ele a achou no campo; a moça desposada gritou, mas não houve quem a livrasse. em juízo, entre sangue', 1, CURRENT_TIMESTAMP, false),
(5, 22, 28, 'Se um homem achar uma moça virgem não desposada e, pegando nela, deitar-se com ela, e forem apanhados,', 1, CURRENT_TIMESTAMP, false),
(5, 22, 29, 'o homem que se deitou com a moça dará ao pai dela cinqüenta siclos de prata, e porquanto a humilhou, ela ficará sendo sua mulher; não a poderá repudiar por todos os seus dias.', 1, CURRENT_TIMESTAMP, false),
(5, 22, 30, 'Nenhum homem tomará a mulher de seu pai, e não levantará a cobertura de seu pai.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 1, 'Aquele a quem forem trilhados os testículos, ou for cortado o membro viril, não entrará na assembléia do Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 2, 'Nenhum bastardo entrará na assembléia do Senhor; nem ainda a sua décima geração entrará na assembléia do Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 3, 'Nenhum amonita nem moabita entrará na assembléia do Senhor; nem ainda a sua décima geração entrará jamais na assembléia do Senhor;', 1, CURRENT_TIMESTAMP, false),
(5, 23, 4, 'porquanto não saíram com pão e água a receber-vos no caminho, quando saíeis do Egito; e, porquanto alugaram contra ti a Balaão, filho de Beor, de Petor, da Mesopotâmia, para te amaldiçoar.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 5, 'Contudo o Senhor teu Deus não quis ouvir a Balaão, antes trocou-te a maldição em bênção; porquanto o Senhor teu Deus te amava.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 6, 'Não lhes procurarás nem paz nem prosperidade por todos os teus dias para sempre.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 7, 'Não abominarás o edomeu, pois é teu irmão; nem abominarás o egípcio, pois peregrino foste na sua terra.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 8, 'Os filhos que lhes nascerem na terceira geração entrarão na assembléia do Senhor.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 9, 'Quando te acampares contra os teus inimigos, então te guardarás de toda coisa má.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 10, 'Se houver no meio de ti alguém que por algum acidente noturno não estiver limpo, sairá fora do arraial; não entrará no meio dele.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 11, 'Porém, ao cair da tarde, ele se lavará em água; e depois do sol posto, entrará no meio do arraial.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 12, 'Também terás um lugar fora do arraial, para onde sairás.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 13, 'Entre os teus utensílios terás uma pá; e quando te assentares lá fora, então com ela cavarás e, virando-te, cobrirás o teu excremento;', 1, CURRENT_TIMESTAMP, false),
(5, 23, 14, 'porquanto o Senhor teu Deus anda no meio do teu arraial, para te livrar, e para te entregar a ti os teus inimigos; pelo que o teu arraial será santo, para que ele não veja coisa impura em ti, e de ti se aparte.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 15, 'Não entregarás a seu senhor o servo que, fugindo dele, se tiver acolhido a ti;', 1, CURRENT_TIMESTAMP, false),
(5, 23, 16, 'contigo ficará, no meio de ti, no lugar que escolher em alguma das tuas cidades, onde lhe agradar; não o oprimirás.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 17, 'Não haverá dentre as filhas de Israel quem se prostitua no serviço do templo, nem dentre os filhos de Israel haverá quem o faça;', 1, CURRENT_TIMESTAMP, false),
(5, 23, 18, 'não trarás o salário da prostituta nem o aluguel do sodomita para a casa do Senhor teu Deus por qualquer voto, porque uma e outra coisa são igualmente abomináveis ao Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 19, 'Do teu irmão não exigirás juros; nem de dinheiro, nem de comida, nem de qualquer outra coisa que se empresta a juros.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 20, 'Do estrangeiro poderás exigir juros; porém do teu irmão não os exigirás, para que o Senhor teu Deus te abençoe em tudo a que puseres a mão, na terra à qual vais para a possuíres.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 21, 'Quando fizeres algum voto ao Senhor teu Deus, não tardarás em cumpri-lo; porque o Senhor teu Deus certamente o requererá de ti, e em ti haverá pecado.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 22, 'Se, porém, te abstiveres de fazer voto, não haverá pecado em ti.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 23, 'O que tiver saído dos teus lábios guardarás e cumprirás, tal como voluntariamente o votaste ao Senhor teu Deus, prometendo-o pela tua boca.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 24, 'Quando entrares na vinha do teu próximo, poderás comer uvas conforme o teu desejo, até te fartares, porém não as porás no teu alforje.', 1, CURRENT_TIMESTAMP, false),
(5, 23, 25, 'Quando entrares na seara do teu próximo, poderás colher espigas com a mão, porém não meterás a foice na seara do teu próximo.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 1, 'Quando um homem tomar uma mulher e se casar com ela, se ela não achar graça aos seus olhos, por haver ele encontrado nela coisa vergonhosa, far-lhe-á uma carta de divórcio e lha dará na mão, e a despedirá de sua casa.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 2, 'Se ela, pois, saindo da casa dele, for e se casar com outro homem,', 1, CURRENT_TIMESTAMP, false),
(5, 24, 3, 'e este também a desprezar e, fazendo-lhe carta de divórcio, lha der na mão, e a despedir de sua casa; ou se este último homem, que a tomou para si por mulher, vier a morrer;', 1, CURRENT_TIMESTAMP, false),
(5, 24, 4, 'então seu primeiro marido que a despedira, não poderá tornar a tomá-la por mulher, depois que foi contaminada; pois isso é abominação perante o Senhor. Não farás pecar a terra que o Senhor teu Deus te dá por herança.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 5, 'Quando um homem for recém-casado não sairá à guerra, nem se lhe imporá cargo público; por um ano inteiro ficará livre na sua casa, para se regozijar com a sua mulher, que tomou.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 6, 'Ninguém tomará em penhor as duas mós, nem mesmo a mó de cima, pois se penhoraria assim a vida.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 7, 'Se for descoberto alguém que, havendo furtado um dentre os seus irmãos, dos filhos de Israel, e tenha escravizado, ou vendido, esse ladrão morrerá. Assim exterminarás o mal do meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 8, 'No tocante à praga da lepra, toma cuidado de observar diligentemente tudo o que te ensinarem os levitas sacerdotes; segundo lhes tenho ordenado, assim cuidarás de fazer.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 9, 'Lembra-te do que o Senhor teu Deus fez a Miriã no caminho, quando saíste do Egito.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 10, 'Quando emprestares alguma coisa ao teu próximo, não entrarás em sua casa para lhe tirar o penhor;', 1, CURRENT_TIMESTAMP, false),
(5, 24, 11, 'ficarás do lado de fora, e o homem, a quem fizeste o empréstimo, te trará para fora o penhor.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 12, 'E se ele for pobre, não te deitarás com o seu penhor;', 1, CURRENT_TIMESTAMP, false),
(5, 24, 13, 'ao pôr do sol, sem falta lhe restituirás o penhor, para que durma na sua roupa, e te abençoe; e isso te será justiça diante do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 14, 'Não oprimirás o trabalhador pobre e necessitado, seja ele de teus irmãos, ou seja dos estrangeiros que estão na tua terra e dentro das tuas portas.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 15, 'No mesmo dia lhe pagarás o seu salário, e isso antes que o sol se ponha; porquanto é pobre e está contando com isso; para que não clame contra ti ao Senhor, e haja em ti pecado.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 16, 'Não se farão morrer os pais pelos filhos, nem os filhos pelos pais; cada qual morrerá pelo seu próprio pecado.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 17, 'Não perverterás o direito do estrangeiro nem do órfão; nem tomarás em penhor o vestido da viúva.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 18, 'Lembrar-te-ás de que foste escravo no Egito, e de que o Senhor teu Deus te resgatou dali; por isso eu te dou este mandamento para o cumprires.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 19, 'Quando no teu campo fizeres a tua sega e esqueceres um molho no campo, não voltarás para tomá-lo; para o estrangeiro para o órfão, e para a viúva será, para que o Senhor teu Deus te abençoe em todas as obras das tuas mãos.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 20, 'Quando bateres a tua oliveira, não voltarás para colher o fruto dos ramos; para o estrangeiro, para o órfão, e para a viúva será.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 21, 'Quando vindimares a tua vinha, não voltarás para rebuscá-la; para o estrangeiro, para o órfão, e para a viúva será.', 1, CURRENT_TIMESTAMP, false),
(5, 24, 22, 'E lembrar-te-ás de que foste escravo na terra do Egito; por isso eu te dou este mandamento para o cumprires.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 1, 'Se houver contenda entre alguns, e vierem a juízo para serem julgados, justificar-se-á ao inocente, e ao culpado condenar-se-á.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 2, 'E se o culpado merecer açoites, o juiz fará que ele se deite e seja açoitado na sua presença, de acordo com a gravidade da sua culpa.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 3, 'Até quarenta açoites lhe poderá dar, não mais; para que, porventura, se lhe der mais açoites do que estes, teu irmão não fique envilecido aos teus olhos.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 4, 'Não atarás a boca ao boi quando estiver debulhando.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 5, 'Se irmãos morarem juntos, e um deles morrer sem deixar filho, a mulher do falecido não se casará com homem estranho, de fora; seu cunhado estará com ela, e a tomará por mulher, fazendo a obrigação de cunhado para com ela.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 6, 'E o primogênito que ela lhe der sucederá ao nome do irmão falecido, para que o nome deste não se apague de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 7, 'Mas, se o homem não quiser tomar sua cunhada, esta subirá à porta, aos anciãos, e dirá: Meu cunhado recusa suscitar a seu irmão nome em Israel; não quer cumprir para comigo o dever de cunhado.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 8, 'Então os anciãos da sua cidade o chamarão, e falarão com ele. Se ele persistir, e disser: Não quero tomá-la;', 1, CURRENT_TIMESTAMP, false),
(5, 25, 9, 'sua cunhada se chegará a ele, na presença dos anciãos, e lhe descalçará o sapato do pé, e lhe cuspirá ao rosto, e dirá: Assim se fará ao homem que não edificar a casa de seu irmão.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 10, 'E sua casa será chamada em Israel a casa do descalçado.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 11, 'Quando pelejarem dois homens, um contra o outro, e a mulher de um chegar para livrar a seu marido da mão daquele que o fere, e ela, estendendo a mão, lhe pegar pelas suas vergonhas,', 1, CURRENT_TIMESTAMP, false),
(5, 25, 12, 'decepar-lhe-á a mão; o teu olho não terá piedade dela.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 13, 'Não terás na tua bolsa pesos diferentes, um grande e um pequeno.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 14, 'Não terás na tua casa duas efas, uma grande e uma pequena.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 15, 'Terás peso inteiro e justo; terás efa inteira e justa; para que se prolonguem os teus dias na terra que o Senhor teu Deus te dá.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 16, 'Porque é abominável ao Senhor teu Deus todo aquele que faz tais coisas, todo aquele que pratica a injustiça.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 17, 'Lembra-te do que te fez Amaleque no caminho, quando saías do Egito;', 1, CURRENT_TIMESTAMP, false),
(5, 25, 18, 'como te saiu ao encontro no caminho e feriu na tua retaguarda todos os fracos que iam após ti, estando tu cansado e afadigado; e não temeu a Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 25, 19, 'Quando, pois, o Senhor teu Deus te houver dado repouso de todos os teus inimigos em redor, na terra que o Senhor teu Deus te dá por herança para a possuíres, apagarás a memória de Amaleque de debaixo do céu; não te esquecerás.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 1, 'Também, quando tiveres entrado na terra que o Senhor teu Deus te dá por herança, e a possuíres, e nela habitares,', 1, CURRENT_TIMESTAMP, false),
(5, 26, 2, 'tomarás das primícias de todos os frutos do solo que trouxeres da terra que o senhor teu Deus te dá, e as porás num cesto, e irás ao lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 3, 'E irás ao sacerdote que naqueles dias estiver de serviço, e lhe dirás: Hoje declaro ao Senhor teu Deus que entrei na terra que o senhor com juramento prometeu a nossos pais que nos daria.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 4, 'O sacerdote, pois, tomará o cesto da tua mão, e o porá diante do altar do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 5, 'E perante o Senhor teu Deus dirás: Arameu prestes a perecer era meu pai; e desceu ao Egito com pouca gente, para ali morar; e veio a ser ali uma nação grande, forte e numerosa.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 6, 'Mas os egípcios nos maltrataram e nos afligiram, e nos impuseram uma dura servidão.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 7, 'Então clamamos ao Senhor Deus de nossos pais, e o Senhor ouviu a nossa voz, e atentou para a nossa aflição, o nosso trabalho, e a nossa opressão;', 1, CURRENT_TIMESTAMP, false),
(5, 26, 8, 'e o Senhor nos tirou do Egito com mão forte e braço estendido, com grande espanto, e com sinais e maravilhas;', 1, CURRENT_TIMESTAMP, false),
(5, 26, 9, 'e nos trouxe a este lugar, e nos deu esta terra, terra que mana leite e mel.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 10, 'E eis que agora te trago as primícias dos frutos da terra que tu, ó Senhor, me deste. Então as porás perante o Senhor teu Deus, e o adorarás;', 1, CURRENT_TIMESTAMP, false),
(5, 26, 11, 'e te alegrarás por todo o bem que o Senhor teu Deus te tem dado a ti e à tua casa, tu e o levita, e o estrangeiro que está no meio de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 12, 'Quando acabares de separar todos os dízimos da tua colheita do terceiro ano, que é o ano dos dízimos, dá-los-ás ao levita, ao estrangeiro, ao órfão e à viúva, para que comam dentro das tuas portas, e se fartem.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 13, 'E dirás perante o Senhor teu Deus: Tirei da minha casa as coisas consagradas, e as dei ao levita, ao estrangeiro, ao órfão e à viúva, conforme todos os teus mandamentos que me tens ordenado; não transgredi nenhum dos teus mandamentos, nem deles me esqueci.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 14, 'Delas não comi no meu luto, nem delas tirei coisa alguma estando eu imundo, nem delas dei para algum morto; ouvi a voz do senhor meu Deus; conforme tudo o que me ordenaste, tenho feito.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 15, 'Olha desde a tua santa habitação, desde o céu, e abençoa o teu povo de Israel, e a terra que nos deste, como juraste a nossos pais, terra que mana leite e mel.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 16, 'Neste dia o Senhor teu Deus te manda observar estes estatutos e preceitos; portanto os guardarás e os observarás com todo o teu coração e com toda a tua alma.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 17, 'Hoje declaraste ao Senhor que ele te será por Deus, e que andarás nos seus caminhos, e guardarás os seus estatutos, os seus mandamentos e os seus preceitos, e darás ouvidos à sua voz.', 1, CURRENT_TIMESTAMP, false),
(5, 26, 18, 'Outrossim, o Senhor hoje te declarou que lhe serás por seu próprio povo, como te tem dito, e que deverás guardar todos os seus mandamentos;', 1, CURRENT_TIMESTAMP, false),
(5, 26, 19, 'para assim te exaltar em honra, em fama e em glória sobre todas as nações que criou; e para que sejas um povo santo ao Senhor teu Deus, como ele disse.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 1, 'Moisés, com os anciãos de Israel, deu ordem ao povo, dizendo: Guardai todos estes mandamentos que eu hoje vos ordeno.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 2, 'E no dia em que passares o Jordão para a terra que o Senhor teu Deus te dá, levantarás umas pedras grandes e as caiarás.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 3, 'E escreverás nelas todas as palavras desta lei, quando tiveres passado para entrar na terra que o Senhor teu Deus te dá, terra que mana leite e mel, como o Senhor, o Deus de teus pais, te prometeu.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 4, 'Quando, pois, houverdes passado o Jordão, levantareis no monte Ebal estas pedras, como eu hoje vos ordeno, e as caiareis.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 5, 'Também ali edificarás um altar ao Senhor teu Deus, um altar de pedras; não alçarás ferramenta sobre elas.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 6, 'De pedras brutas edificarás o altar do Senhor teu Deus, e sobre ele oferecerás holocaustos ao Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 7, 'Também sacrificarás ofertas pacíficas, e ali comerás, e te alegrarás perante o Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 8, 'Naquelas pedras escreverás todas as palavras desta lei, gravando-as bem nitidamente.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 9, 'Falou mais Moisés, e os levitas sacerdotes, a todo o Israel, dizendo: Guarda silêncio, e ouve, ó Israel! hoje vieste a ser o povo do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 10, 'Portanto obedecerás à voz do Senhor teu Deus, e cumprirás os seus mandamentos e os seus estatutos, que eu hoje te ordeno.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 11, 'Nesse mesmo dia Moisés deu ordem ao povo, dizendo:', 1, CURRENT_TIMESTAMP, false),
(5, 27, 12, 'Quando houverdes passado o Jordão, estes estarão sobre o monte Gerizim, para abençoarem o povo: Simeão, Levi, Judá, Issacar, José e Benjamim;', 1, CURRENT_TIMESTAMP, false),
(5, 27, 13, 'e estes estarão sobre o monte Ebal para pronunciarem a maldição: Rúben, Gade, Aser, Zebulom, Dã e Naftali.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 14, 'E os levitas dirão em alta voz a todos os homens de Israel:', 1, CURRENT_TIMESTAMP, false),
(5, 27, 15, 'Maldito o homem que fizer imagem esculpida, ou fundida, abominação ao Senhor, obra da mão do artífice, e a puser em um lugar escondido. E todo o povo, respondendo, dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 16, 'Maldito aquele que desprezar a seu pai ou a sua mãe. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 17, 'Maldito aquele que remover os marcos do seu próximo. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 18, 'Maldito aquele que fizer que o cego erre do caminho. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 19, 'Maldito aquele que perverter o direito do estrangeiro, do órfão e da viúva. E todo o povo dirá: Amém,', 1, CURRENT_TIMESTAMP, false),
(5, 27, 20, 'Maldito aquele que se deitar com a mulher de seu pai, porquanto levantou a cobertura de seu pai. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 21, 'Maldito aquele que se deitar com algum animal. E todo o povo dirá: Amem.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 22, 'Maldito aquele que se deitar com sua irmã, filha de seu pai, ou filha de sua mãe. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 23, 'Maldito aquele que se deitar com sua sogra. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 24, 'Maldito aquele que ferir ao seu próximo em oculto. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 25, 'Maldito aquele que receber peita para matar uma pessoa inocente. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 27, 26, 'Maldito aquele que não confirmar as palavras desta lei, para as cumprir. E todo o povo dirá: Amém.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 1, 'Se ouvires atentamente a voz do Senhor teu Deus, tendo cuidado de guardar todos os seus mandamentos que eu hoje te ordeno, o Senhor teu Deus te exaltará sobre todas as nações da terra;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 2, 'e todas estas bênçãos virão sobre ti e te alcançarão, se ouvires a voz do Senhor teu Deus:', 1, CURRENT_TIMESTAMP, false),
(5, 28, 3, 'Bendito serás na cidade, e bendito serás no campo.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 4, 'Bendito o fruto do teu ventre, e o fruto do teu solo, e o fruto dos teus animais, e as crias das tuas vacas e das tuas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 5, 'Bendito o teu cesto, e a tua amassadeira.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 6, 'Bendito serás quando entrares, e bendito serás quando saíres.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 7, 'O Senhor entregará, feridos diante de ti, os teus inimigos que se levantarem contra ti; por um caminho sairão contra ti, mas por sete caminhos rugirão da tua presença.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 8, 'O Senhor mandará que a bênção esteja contigo nos teus celeiros e em tudo a que puseres a tua mão; e te abençoará na terra que o Senhor teu Deus te dá.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 9, 'O Senhor te confirmará para si por povo santo, como te jurou, se guardares os mandamentos do Senhor teu Deus e andares nos seus caminhos.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 10, 'Assim todos os povos da terra verão que és chamado pelo nome do Senhor, e terão temor de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 11, 'E o Senhor te fará prosperar grandemente no fruto do teu ventre, no fruto dos teus animais e no fruto do teu solo, na terra que o Senhor, com juramento, prometeu a teus pais te dar.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 12, 'O Senhor te abrirá o seu bom tesouro, o céu, para dar à tua terra a chuva no seu tempo, e para abençoar todas as obras das tuas mãos; e emprestarás a muitas nações, porém tu não tomarás emprestado.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 13, 'E o Senhor te porá por cabeça, e não por cauda; e só estarás por cima, e não por baixo; se obedeceres aos mandamentos do Senhor teu Deus, que eu hoje te ordeno, para os guardar e cumprir,', 1, CURRENT_TIMESTAMP, false),
(5, 28, 14, 'não te desviando de nenhuma das palavras que eu hoje te ordeno, nem para a direita nem para a esquerda, e não andando após outros deuses, para os servires.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 15, 'Se, porém, não ouvires a voz do Senhor teu Deus, se não cuidares em cumprir todos os seus mandamentos e os seus estatutos, que eu hoje te ordeno, virão sobre ti todas estas maldições, e te alcançarão:', 1, CURRENT_TIMESTAMP, false),
(5, 28, 16, 'Maldito serás na cidade, e maldito serás no campo.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 17, 'Maldito o teu cesto, e a tua amassadeira.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 18, 'Maldito o fruto do teu ventre, e o fruto do teu solo, e as crias das tuas vacas e das tuas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 19, 'Maldito serás ao entrares, e maldito serás ao saíres.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 20, 'O Senhor mandará sobre ti a maldição, a derrota e o desapontamento, em tudo a que puseres a mão para fazer, até que sejas destruído, e até que repentinamente pereças, por causa da maldade das tuas obras, pelas quais me deixaste.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 21, 'O Senhor fará pegar em ti a peste, até que te consuma da terra na qual estás entrando para a possuíres.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 22, 'O Senhor te ferirá com a tísica e com a febre, com a inflamação, com o calor forte, com a seca, com crestamento e com ferrugem, que te perseguirão até que pereças', 1, CURRENT_TIMESTAMP, false),
(5, 28, 23, 'O céu que está sobre a tua cabeça será de bronze, e a terra que está debaixo de ti será de ferro.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 24, 'O Senhor dará por chuva à tua terra pó; do céu descerá sobre ti a poeira, ate que sejas destruído.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 25, 'O Senhor fará que sejas ferido diante dos teus inimigos; por um caminho sairás contra eles, e por sete caminhos fugirás deles; e serás espetáculo horrendo a todos os reinos da terra.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 26, 'Os teus cadáveres servirão de pasto a todas as aves do céu, e aos animais da terra, e não haverá quem os enxote.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 27, 'O Senhor te ferirá com as úlceras do Egito, com tumores, com sarna e com coceira, de que não possas curar-te;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 28, 'o Senhor te ferirá com loucura, com cegueira, e com pasmo de coração.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 29, 'Apalparás ao meio-dia como o cego apalpa nas trevas, e não prosperarás nos teus caminhos; serás oprimido e roubado todos os dias, e não haverá quem te salve.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 30, 'Desposar-te-ás com uma mulher, porém outro homem dormirá com ela; edificarás uma casa, porém não morarás nela; plantarás uma vinha, porém não a desfrutarás.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 31, 'O teu boi será morto na tua presença, porém dele não comerás; o teu jumento será roubado diante de ti, e não te será restituído a ti; as tuas ovelhas serão dadas aos teus inimigos, e não haverá quem te salve.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 32, 'Teus filhos e tuas filhas serão dados a outro povo, os teus olhos o verão, e desfalecerão de saudades deles todo o dia; porém não haverá poder na tua mão.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 33, 'O fruto da tua terra e todo o teu trabalho comê-los-á um povo que nunca conheceste; e serás oprimido e esmagado todos os dias.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 34, 'E enlouquecerás pelo que hás de ver com os teus olhos.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 35, 'Com úlceras malignas, de que não possas sarar, o Senhor te ferirá nos joelhos e nas pernas, sim, desde a planta do pé até o alto da cabeça.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 36, 'O Senhor te levará a ti e a teu rei, que tiveres posto sobre ti, a uma nação que não conheceste, nem tu nem teus pais; e ali servirás a outros deuses, ao pau e à pedra.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 37, 'E virás a ser por pasmo, provérbio e ludíbrio entre todos os povos a que o Senhor te levar.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 38, 'Levarás muita semente para o teu campo, porem colherás pouco; porque o gafanhoto a consumirá.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 39, 'Plantarás vinhas, e as cultivarás, porém não lhes beberás o vinho, nem colherás as uvas; porque o bicho as devorará.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 40, 'Terás oliveiras em todos os teus termos, porém não te ungirás com azeite; porque a azeitona te cairá da oliveira.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 41, 'Filhos e filhas gerarás, porém não te pertencerão; porque irão em cativeiro.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 42, 'Todo o teu arvoredo e o fruto do teu solo consumi-los-á o gafanhoto.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 43, 'O estrangeiro que está no meio de ti se elevará cada vez mais sobre ti, e tu cada vez mais descerás;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 44, 'ele emprestará a ti, porém tu não emprestarás a ele; ele será a cabeça, e tu serás a cauda.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 45, 'Todas estas maldições virão sobre ti, e te perseguirão, e te alcançarão, até que sejas destruído, por não haveres dado ouvidos à voz do Senhor teu Deus, para guardares os seus mandamentos, e os seus estatutos, que te ordenou.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 46, 'Estarão sobre ti por sinal e por maravilha, como também sobre a tua descendência para sempre.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 47, 'Por não haveres servido ao Senhor teu Deus com gosto e alegria de coração, por causa da abundância de tudo,', 1, CURRENT_TIMESTAMP, false),
(5, 28, 48, 'servirás aos teus inimigos, que o Senhor enviará contra ti, em fome e sede, e em nudez, e em falta de tudo; e ele porá sobre o teu pescoço um jugo de ferro, até que te haja destruído.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 49, 'O Senhor levantará contra ti de longe, da extremidade da terra, uma nação que voa como a águia, nação cuja língua não entenderás;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 50, 'nação de rosto feroz, que não respeitará ao velho, nem se compadecerá do moço;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 51, 'e comerá o fruto dos teus animais e o fruto do teu solo, até que sejas destruído; e não te deixará grão, nem mosto, nem azeite, nem as crias das tuas vacas e das tuas ovelhas, até que te faça perecer;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 52, 'e te sitiará em todas as tuas portas, até que em toda a tua terra venham a cair os teus altos e fortes muros, em que confiavas; sim, te sitiará em todas as tuas portas, em toda a tua terra que o Senhor teu Deus te deu.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 53, 'E, no cerco e no aperto com que os teus inimigos te apertarão, comerás o fruto do teu ventre, a carne de teus filhos e de tuas filhas, que o Senhor teu Deus te houver dado.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 54, 'Quanto ao homem mais mimoso e delicado no meio de ti, o seu olho será mesquinho para com o seu irmão, para com a mulher de seu regaço, e para com os filhos que ainda lhe ficarem de resto;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 55, 'de sorte que não dará a nenhum deles da carne de seus filhos que ele comer, porquanto nada lhe terá ficado de resto no cerco e no aperto com que o teu inimigo te apertará em todas as tuas portas.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 56, 'Igualmente, quanto à mulher mais mimosa e delicada no meio de ti, que de mimo e delicadeza nunca tentou pôr a planta de seu pé sobre a terra, será mesquinho o seu olho para com o homem de seu regaço, para com seu filho, e para com sua filha;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 57, 'também ela será mesquinha para com as suas páreas, que saírem dentre os seus pés, e para com os seus filhos que tiver; porque os comerá às escondidas pela falta de tudo, no cerco e no aperto com que o teu inimigo te apertará nas tuas portas.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 58, 'Se não tiveres cuidado de guardar todas as palavras desta lei, que estão escritas neste livro, para temeres este nome glorioso e temível, o Senhor teu Deus;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 59, 'então o Senhor fará espantosas as tuas pragas, e as pragas da tua descendência, grandes e duradouras pragas, e enfermidades malignas e duradouras;', 1, CURRENT_TIMESTAMP, false),
(5, 28, 60, 'e fará tornar sobre ti todos os males do Egito, de que tiveste temor; e eles se apegarão a ti.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 61, 'Também o Senhor fará vir a ti toda enfermidade, e toda praga que não está escrita no livro desta lei, até que sejas destruído.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 62, 'Assim ficareis poucos em número, depois de haverdes sido em multidão como as estrelas do céu; porquanto não deste ouvidos à voz do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 63, 'E será que, assim como o Senhor se deleitava em vós, para fazer-vos o bem e multiplicar-vos, assim o Senhor se deleitará em destruir-vos e consumir-vos; e sereis desarraigados da terra na qual estais entrando para a possuirdes.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 64, 'E o Senhor vos espalhará entre todos os povos desde uma extremidade da terra até a outra; e ali servireis a outros deuses que não conhecestes, nem vós nem vossos pais, deuses de pau e de pedra.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 65, 'E nem ainda entre estas nações descansarás, nem a planta de teu pé terá repouso; mas o Senhor ali te dará coração tremente, e desfalecimento de olhos, e desmaio de alma.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 66, 'E a tua vida estará como em suspenso diante de ti; e estremecerás de noite e de dia, e não terás segurança da tua própria vida.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 67, 'Pela manhã dirás: Ah! quem me dera ver a tarde; E à tarde dirás: Ah! quem me dera ver a manhã! pelo pasmo que terás em teu coração, e pelo que verás com os teus olhos.', 1, CURRENT_TIMESTAMP, false),
(5, 28, 68, 'E o Senhor te fará voltar ao Egito em navios, pelo caminho de que te disse: Nunca mais o verás. Ali vos poreis a venda como escravos e escravas aos vossos inimigos, mas não haverá quem vos compre.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 1, 'Estas são as palavras do pacto que o Senhor ordenou a Moisés que fizesse com os filhos de Israel na terra de Moabe, além do pacto que fizera com eles em Horebe.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 2, 'Chamou, pois, Moisés a todo o Israel, e disse-lhes: Vistes tudo quanto o Senhor fez perante vossos olhos, na terra do Egito, a Faraó, a todos os seus servos e a toda a sua terra;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 3, 'as grandes provas que os teus olhos viram, os sinais e aquelas grandes maravilhas.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 4, 'Mas até hoje o Senhor não vos tem dado um coração para entender, nem olhos para ver, nem ouvidos para ouvir.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 5, 'Quarenta anos vos fiz andar pelo deserto; não se envelheceu sobre vós a vossa roupa, nem o sapato no vosso pé.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 6, 'Pão não comestes, vinho e bebida forte não bebestes; para que soubésseis que eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 7, 'Quando, pois, viemos a este lugar, Siom, rei de Hesbom, e Ogue, rei de Basã, nos saíram ao encontro, à peleja, e nós os ferimos;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 8, 'e lhes tomamos a terra, e a demos por herança aos rubenitas, aos gaditas e à meia tribo dos manassitas.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 9, 'Guardai, pois, as palavras deste pacto e cumpri-as, para que prospereis em tudo quanto fizerdes.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 10, 'Vós todos estais hoje perante o Senhor vosso Deus: os vossos cabeças, as vossas tribos, os vossos anciãos e os vossos oficiais, a saber, todos os homens de Israel,', 1, CURRENT_TIMESTAMP, false),
(5, 29, 11, 'os vossos pequeninos, as vossas mulheres, e o estrangeiro que está no meio do vosso arraial, tanto o rachador da vossa lenha como o tirador da vossa água;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 12, 'para entrardes no pacto do Senhor vosso Deus, e no seu juramento que o Senhor vosso Deus hoje faz convosco;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 13, 'para que hoje vos estabeleça por seu povo, e ele vos seja por Deus, como vos disse e como prometeu com juramento a vossos pais, a Abraão, a Isaque e a Jacó.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 14, 'Ora, não é somente convosco que faço este pacto e este juramento,', 1, CURRENT_TIMESTAMP, false),
(5, 29, 15, 'mas é com aquele que hoje está aqui conosco perante o Senhor nosso Deus, e também com aquele que hoje não está aqui conosco', 1, CURRENT_TIMESTAMP, false),
(5, 29, 16, '{porque vós sabeis como habitamos na terra do Egito, e como passamos pelo meio das nações, pelas quais passastes;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 17, 'e vistes as suas abominações, os seus ídolos de pau e de pedra, de prata e de ouro, que havia entre elas};', 1, CURRENT_TIMESTAMP, false),
(5, 29, 18, 'para que entre vós não haja homem, nem mulher, nem família, nem tribo, cujo coração hoje se desvie do Senhor nosso Deus, e vá servir aos deuses dessas nações; para que entre vós não haja raiz que produza veneno e fel,', 1, CURRENT_TIMESTAMP, false),
(5, 29, 19, 'e aconteça que alguém, ouvindo as palavras deste juramento, se abençoe no seu coração, dizendo: Terei paz, ainda que ande na teimosia do meu coração para acrescentar à sede a bebedeira.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 20, 'O Senhor não lhe quererá perdoar, pelo contrário fumegará contra esse homem a ira do Senhor, e o seu zelo, e toda maldição escrita neste livro pousará sobre ele, e o Senhor lhe apagará o nome de debaixo do céu.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 21, 'Assim o Senhor o separará para mal, dentre todas as tribos de Israel, conforme todas as maldições do pacto escrito no livro desta lei.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 22, 'Pelo que a geração vindoura-os vossos filhos que se levantarem depois de vós-e o estrangeiro que vier de terras remotas dirão, ao verem as pragas desta terra, e as suas doenças, com que o Senhor a terá afligido,', 1, CURRENT_TIMESTAMP, false),
(5, 29, 23, 'e que toda a sua terra é enxofre e sal e abrasamento, de sorte que não será semeada, e nada produzirá, nem nela crescerá erva alguma, assim como foi a destruição de Sodoma e de Gomorra, de Admá e de Zeboim, que o Senhor destruiu na sua ira e no seu furor;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 24, 'sim, todas as nações dirão: Por que fez o Senhor assim com esta terra? Que significa o furor de tamanha ira?', 1, CURRENT_TIMESTAMP, false),
(5, 29, 25, 'Então se dirá: Porquanto deixaram o pacto do Senhor, o Deus de seus pais, que tinha feito com eles, quando os tirou da terra do Egito;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 26, 'e se foram e serviram a outros deuses, e os adoraram; deuses que eles não tinham conhecido, e que lhes não foram dados;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 27, 'por isso é que a ira do Senhor se acendeu contra esta terra, para trazer sobre ela toda maldição que está escrita neste livro;', 1, CURRENT_TIMESTAMP, false),
(5, 29, 28, 'e o Senhor os arrancou da sua terra com ira, com furor e com grande indignação, e os lançou em outra terra, como neste dia se vê.', 1, CURRENT_TIMESTAMP, false),
(5, 29, 29, 'As coisas encobertas pertencem ao Senhor nosso Deus, mas as reveladas nos pertencem a nós e a nossos filhos para sempre, para que observemos todas as palavras desta lei.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 1, 'Quando te sobrevierem todas estas coisas, a bênção ou a maldição, que pus diante de ti, e te recordares delas entre todas as nações para onde o Senhor teu Deus te houver lançado,', 1, CURRENT_TIMESTAMP, false),
(5, 30, 2, 'e te converteres ao Senhor teu Deus, e obedeceres à sua voz conforme tudo o que eu te ordeno hoje, tu e teus filhos, de todo o teu coração e de toda a tua alma,', 1, CURRENT_TIMESTAMP, false),
(5, 30, 3, 'o Senhor teu Deus te fará voltar do teu cativeiro, e se compadecerá de ti, e tornará a ajuntar-te dentre todos os povos entre os quais te houver espalhado o senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 4, 'Ainda que o teu desterro tenha sido para a extremidade do céu, desde ali te ajuntará o Senhor teu Deus, e dali te tomará;', 1, CURRENT_TIMESTAMP, false),
(5, 30, 5, 'e o Senhor teu Deus te trará à terra que teus pais possuíram, e a possuirás; e te fará bem, e te multiplicará mais do que a teus pais.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 6, 'Também o Senhor teu Deus circuncidará o teu coração, e o coração de tua descendência, a fim de que ames ao Senhor teu Deus de todo o teu coração e de toda a tua alma, para que vivas.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 7, 'E o Senhor teu Deus porá todas estas maldições sobre os teus inimigos, sobre aqueles que te tiverem odiado e perseguido.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 8, 'Tu te tornarás, pois, e obedecerás à voz do Senhor, e observarás todos os seus mandamentos que eu hoje te ordeno.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 9, 'Então o Senhor teu Deus te fará prosperar grandemente em todas as obras das tuas mãos, no fruto do teu ventre, e no fruto dos teus animais, e no fruto do teu solo; porquanto o Senhor tornará a alegrar-se em ti para te fazer bem, como se alegrou em teus pais;', 1, CURRENT_TIMESTAMP, false),
(5, 30, 10, 'quando obedeceres à voz do Senhor teu Deus, guardando os seus mandamentos e os seus estatutos, escritos neste livro da lei; quando te converteres ao Senhor teu Deus de todo o teu coração e de toda a tua alma.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 11, 'Porque este mandamento, que eu hoje te ordeno, não te é difícil demais, nem tampouco está longe de ti.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 12, 'Não está no céu para dizeres: Quem subirá por nós ao céu, e no-lo trará, e no-lo fará ouvir, para que o cumpramos?', 1, CURRENT_TIMESTAMP, false),
(5, 30, 13, 'Nem está além do mar, para dizeres: Quem passará por nós além do mar, e no-lo trará, e no-lo fará ouvir, para que o cumpramos?', 1, CURRENT_TIMESTAMP, false),
(5, 30, 14, 'Mas a palavra está mui perto de ti, na tua boca, e no teu coração, para a cumprires.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 15, 'Vê que hoje te pus diante de ti a vida e o bem, a morte e o mal.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 16, 'Se guardares o mandamento que eu hoje te ordeno de amar ao Senhor teu Deus, de andar nos seus caminhos, e de guardar os seus mandamentos, os seus estatutos e os seus preceitos, então viverás, e te multiplicarás, e o Senhor teu Deus te abençoará na terra em que estás entrando para a possuíres.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 17, 'Mas se o teu coração se desviar, e não quiseres ouvir, e fores seduzido para adorares outros deuses, e os servires,', 1, CURRENT_TIMESTAMP, false),
(5, 30, 18, 'declaro-te hoje que certamente perecerás; não prolongarás os dias na terra para entrar na qual estás passando o Jordão, a fim de a possuíres.', 1, CURRENT_TIMESTAMP, false),
(5, 30, 19, 'O céu e a terra tomo hoje por testemunhas contra ti de que te pus diante de ti a vida e a morte, a bênção e a maldição; escolhe, pois, a vida, para que vivas, tu e a tua descendência,', 1, CURRENT_TIMESTAMP, false),
(5, 30, 20, 'amando ao Senhor teu Deus, obedecendo à sua voz, e te apegando a ele; pois ele é a tua vida, e o prolongamento dos teus dias; e para que habites na terra que o Senhor prometeu com juramento a teus pais, a Abraão, a Isaque e a Jacó, que lhes havia de dar.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 1, 'Prosseguindo Moisés, falou ainda estas palavras a todo o Israel,', 1, CURRENT_TIMESTAMP, false),
(5, 31, 2, 'dizendo-lhes: Cento e vinte anos tenho eu hoje. Já não posso mais sair e entrar; e o Senhor me disse: Não passarás este Jordão.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 3, 'O Senhor teu Deus passará adiante de ti; ele destruirá estas nações de diante de ti, para que as possuas. Josué passará adiante de ti, como o Senhor disse.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 4, 'E o Senhor lhes fará como fez a Siom e a Ogue, reis dos amorreus, e à sua terra, aos quais destruiu.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 5, 'Quando, pois, o Senhor vo-los entregar, fareis com eles conforme todo o mandamento que vos tenho ordenado.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 6, 'Sede fortes e corajosos; não temais, nem vos atemorizeis diante deles; porque o Senhor vosso Deus é quem vai convosco. Não vos deixará, nem vos desamparará.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 7, 'Então chamou Moisés a Josué, e lhe disse à vista de todo o Israel: Sê forte e corajoso, porque tu entrarás com este povo na terra que o Senhor, com juramento, prometeu a teus pais lhes daria; e tu os farás herdá-la.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 8, 'O Senhor, pois, é aquele que vai adiante de ti; ele será contigo, não te deixará, nem te desamparará. Não temas, nem te espantes.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 9, 'Moisés escreveu esta lei, e a entregou aos sacerdotes, filhos de Levi, que levavam a arca do pacto do Senhor, e a todos os anciãos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 10, 'Também Moisés lhes deu ordem, dizendo: Ao fim de cada sete anos, no tempo determinado do ano da remissão, na festa dos tabernáculos,', 1, CURRENT_TIMESTAMP, false),
(5, 31, 11, 'quando todo o Israel vier a comparecer perante ao Senhor teu Deus, no lugar que ele escolher, lereis esta lei diante de todo o Israel, para todos ouvirem.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 12, 'Congregai o povo, homens, mulheres e pequeninos, e os estrangeiros que estão dentro das vossas portas, para que ouçam e aprendam, e temam ao Senhor vosso Deus, e tenham cuidado de cumprir todas as palavras desta lei;', 1, CURRENT_TIMESTAMP, false),
(5, 31, 13, 'e que seus filhos que não a souberem ouçam, e aprendam a temer ao Senhor vosso Deus, todos os dias que viverdes sobre a terra a qual estais passando o Jordão para possuir.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 14, 'Também disse o Senhor a Moisés: Eis que vem chegando o dia em que hás de morrer. Chama a Josué, e apresentai-vos na tenda da revelação, para que eu lhe dê ordens. Assim foram Moisés e Josué, e se apresentaram na tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 15, 'Então o Senhor apareceu na tenda, na coluna de nuvem; e a coluna de nuvem parou sobre a porta da tenda.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 16, 'E disse o Senhor a Moisés: Eis que dormirás com teus pais; e este povo se levantará, e se prostituirá indo após os deuses estranhos da terra na qual está entrando, e me deixará, e quebrará o meu pacto, que fiz com ele.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 17, 'Então se acenderá a minha ira naquele dia contra ele, e eu o deixarei, e dele esconderei o meu rosto, e ele será devorado. Tantos males e angústias o alcançarão, que dirá naquele dia: Não é, porventura, por não estar o meu Deus comigo, que me sobrevieram estes males?', 1, CURRENT_TIMESTAMP, false),
(5, 31, 18, 'Esconderei pois, totalmente o meu rosto naquele dia, por causa de todos os males que ele tiver feito, por se haver tornado para outros deuses.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 19, 'Agora, pois, escrevei para vós este cântico, e ensinai-o aos filhos de Israel; ponde-o na sua boca, para que este cântico me sirva por testemunha contra o povo de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 20, 'Porque o introduzirei na terra que, com juramento, prometi a seus pais, terra que mana leite e mel; comerá, fartar-se-á, e engordará; então, tornando-se para outros deuses, os servirá, e me desprezará, violando o meu pacto.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 21, 'E será que, quando lhe sobrevierem muitos males e angústias, então este cântico responderá contra ele por testemunha, pois não será esquecido da boca de sua descendência; porquanto conheço a sua imaginação, o que ele maquina hoje, antes de eu o ter introduzido na terra que lhe prometi com juramento.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 22, 'Assim Moisés escreveu este cântico naquele dia, e o ensinou aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 23, 'E ordenou o Senhor a Josué, filho de Num, dizendo: sê forte e corajoso, porque tu introduzirás os filhos de Israel na terra que, com juramento, lhes prometi; e eu serei contigo.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 24, 'Ora, tendo Moisés acabado de escrever num livro todas as palavras desta lei,', 1, CURRENT_TIMESTAMP, false),
(5, 31, 25, 'deu ordem aos levitas que levavam a arca do pacto do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(5, 31, 26, 'Tomai este livro da lei, e ponde-o ao lado da arca do pacto do Senhor vosso Deus, para que ali esteja por testemunha contra vós.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 27, 'Porque conheço a vossa rebeldia e a vossa dura cerviz; eis que, vivendo eu ainda hoje convosco, rebeldes fostes contra o Senhor; e quanto mais depois da minha morte!', 1, CURRENT_TIMESTAMP, false),
(5, 31, 28, 'Congregai perante mim todos os anciãos das vossas tribos, e vossos oficiais, para que eu fale estas palavras aos seus ouvidos, e tome por testemunhas contra eles o céu e a terra.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 29, 'Porque eu sei que depois da minha morte certamente vos corrompereis, e vos desviareis do caminho que vos ordenei; então este mal vos sobrevirá nos últimos dias, quando fizerdes o que é mau aos olhos do Senhor, para o provocar à ira com a obra das vossas mãos.', 1, CURRENT_TIMESTAMP, false),
(5, 31, 30, 'Então Moisés proferiu todas as palavras deste cântico, ouvindo-o toda a assembléia de Israel:', 1, CURRENT_TIMESTAMP, false),
(5, 32, 1, 'Inclinai os ouvidos, ó céus, e falarei; e ouça a terra as palavras da minha boca.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 2, 'Caia como a chuva a minha doutrina; destile a minha palavra como o orvalho, como chuvisco sobre a erva e como chuvas sobre a relva.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 3, 'Porque proclamarei o nome do Senhor; engrandecei o nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 4, 'Ele é a Rocha; suas obras são perfeitas, porque todos os seus caminhos são justos; Deus é fiel e sem iniqüidade; justo e reto é ele.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 5, 'Corromperam-se contra ele; não são seus filhos, e isso é a sua mancha; geração perversa e depravada é.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 6, 'É assim que recompensas ao Senhor, povo louco e insensato? não é ele teu pai, que te adquiriu, que te fez e te estabeleceu?', 1, CURRENT_TIMESTAMP, false),
(5, 32, 7, 'Lembra-te dos dias da antigüidade, atenta para os anos, geração por geração; pergunta a teu pai, e ele te informará, aos teus anciãos, e eles to dirão.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 8, 'Quando o Altíssimo dava às nações a sua herança, quando separava os filhos dos homens, estabeleceu os termos dos povos conforme o número dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 9, 'Porque a porção do Senhor é o seu povo; Jacó é a parte da sua herança.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 10, 'Achou-o numa terra deserta, e num erma de solidão e horrendos uivos; cercou-o de proteção; cuidou dele, guardando-o como a menina do seu olho.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 11, 'Como a águia desperta o seu ninho, adeja sobre os seus filhos e, estendendo as suas asas, toma-os, e os leva sobre as suas asas,', 1, CURRENT_TIMESTAMP, false),
(5, 32, 12, 'assim só o Senhor o guiou, e não havia com ele deus estranho.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 13, 'Ele o fez cavalgar sobre as alturas da terra, e comer os frutos do campo; também o fez chupar mel da rocha e azeite da dura pederneira,', 1, CURRENT_TIMESTAMP, false),
(5, 32, 14, 'coalhada das vacas e leite das ovelhas, com a gordura dos cordeiros, dos carneiros de Basã, e dos bodes, com o mais fino trigo; e por vinho bebeste o sangue das uvas.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 15, 'E Jesurum, engordando, recalcitrou {tu engordaste, tu te engrossaste e te cevaste}; então abandonou a Deus, que o fez, e desprezou a Rocha da sua salvação.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 16, 'Com deuses estranhos o moveram a zelos; com abominações o provocaram à ira:', 1, CURRENT_TIMESTAMP, false),
(5, 32, 17, 'Ofereceram sacrifícios aos demônios, não a Deus, a deuses que não haviam conhecido, deuses novos que apareceram há pouco, aos quais os vossos pais não temeram.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 18, 'Olvidaste a Rocha que te gerou, e te esqueceste do Deus que te formou.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 19, 'Vendo isto, o Senhor os desprezou, por causa da provocação que lhe fizeram seus filhos e suas filhas;', 1, CURRENT_TIMESTAMP, false),
(5, 32, 20, 'e disse: Esconderei deles o meu rosto, verei qual será o seu fim, porque geração perversa são eles, filhos em quem não há fidelidade.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 21, 'A zelos me provocaram cem aquilo que não é Deus, com as suas vaidades me provocaram à ira; portanto eu os provocarei a zelos com aquele que não é povo, com uma nação insensata os despertarei à ira.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 22, 'Porque um fogo se acendeu na minha ira, e arde até o mais profundo do Seol, e devora a terra com o seu fruto, e abrasa os fundamentos dos montes.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 23, 'Males amontoarei sobre eles, esgotarei contra eles as minhas setas.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 24, 'Consumidos serão de fome, devorados de raios e de amarga destruição; e contra eles enviarei dentes de feras, juntamente com o veneno dos que se arrastam no pó.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 25, 'Por fora devastará a espada, e por dentro o pavor, tanto ao mancebo como à virgem, assim à criança de peito como ao homem encanecido.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 26, 'Eu teria dito: Por todos os cantos os espalharei, farei cessar a sua memória dentre os homens,', 1, CURRENT_TIMESTAMP, false),
(5, 32, 27, 'se eu não receasse a vexação da parte do inimigo, para que os seus adversários, iludindo-se, não dissessem: A nossa mão está exaltada; não foi o Senhor quem fez tudo isso.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 28, 'Porque são gente falta de conselhos, e neles não há entendimento.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 29, 'Se eles fossem sábios, entenderiam isso, e atentariam para o seu fim!', 1, CURRENT_TIMESTAMP, false),
(5, 32, 30, 'Como poderia um só perseguir mil, e dois fazer rugir dez mil, se a sua Rocha não os vendera, e o Senhor não os entregara?', 1, CURRENT_TIMESTAMP, false),
(5, 32, 31, 'Porque a sua rocha não é como a nossa Rocha, sendo até os nossos inimigos juízes disso.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 32, 'Porque a sua vinha é da vinha de Sodoma e dos campos de Gomorra; as suas uvas são uvas venenosas, seus cachos são amargos.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 33, 'O seu vinho é veneno de serpentes, e peçonha cruel de víboras.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 34, 'Não está isto encerrado comigo? selado nos meus tesouros?', 1, CURRENT_TIMESTAMP, false),
(5, 32, 35, 'Minha é a vingança e a recompensa, ao tempo em que resvalar o seu pé; porque o dia da sua ruína está próximo, e as coisas que lhes hão de suceder se apressam a chegar.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 36, 'Porque o Senhor vindicará ao seu povo, e se arrependerá no tocante aos seus servos, quando vir que o poder deles já se foi, e que não resta nem escravo nem livre.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 37, 'Então dirá: Onde estão os seus deuses, a rocha em que se refugiavam,', 1, CURRENT_TIMESTAMP, false),
(5, 32, 38, 'os que comiam a gordura dos sacrifícios deles e bebiam o vinho das suas ofertas de libação? Levantem-se eles, e vos ajudem, a fim de que haja agora refúgio para vós.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 39, 'Vede agora que eu, eu o sou, e não há outro deus além de mim; eu faço morrer e eu faço viver; eu firo e eu saro; e não há quem possa livrar da minha mão.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 40, 'Pois levanto a minha mão ao céu, e digo: Como eu vivo para sempre,', 1, CURRENT_TIMESTAMP, false),
(5, 32, 41, 'se eu afiar a minha espada reluzente, e a minha mão travar do juízo, então retribuirei vingança aos meus adversários, e recompensarei aos que me odeiam.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 42, 'De sangue embriagarei as minhas setas, e a minha espada devorará carne; do sangue dos mortes e dos cativos, das cabeças cabeludas dos inimigos', 1, CURRENT_TIMESTAMP, false),
(5, 32, 43, 'Aclamai, ó nações, com alegria, o povo dele, porque ele vingará o sangue dos seus servos; aos seus adversários retribuirá vingança, e fará expiação pela sua terra e pelo seu povo.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 44, 'Veio, pois, Moisés, e proferiu todas as palavras deste cântico na presença do povo, ele e Oséias, filho de Num.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 45, 'E, acabando Moisés de falar todas essas palavras a todo o Israel,', 1, CURRENT_TIMESTAMP, false),
(5, 32, 46, 'disse-lhes: Aplicai o vosso coração a todas as palavras que eu hoje vos testifico, as quais haveis de recomendar a vossos filhos, para que tenham cuidado de cumprir todas as palavras desta lei.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 47, 'Porque esta palavra não vos é vã, mas é a vossa vida, e por esta mesma palavra prolongareis os dias na terra à qual ides, passando o Jordão, para a possuir.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 48, 'Naquele mesmo dia falou o Senhor a Moisés, dizendo:', 1, CURRENT_TIMESTAMP, false),
(5, 32, 49, 'Sobe a este monte de Abarim, ao monte Nebo, que está na terra de Moabe, defronte de Jericó, e vê a terra de Canaã, que eu dou aos filhos de Israel por possessão;', 1, CURRENT_TIMESTAMP, false),
(5, 32, 50, 'e morre no monte a que vais subir, e recolhe-te ao teu povo; assim como Arão, teu irmão, morreu no monte Hor, e se recolheu ao seu povo;', 1, CURRENT_TIMESTAMP, false),
(5, 32, 51, 'porquanto pecastes contra mim no meio dos filhos de Israel, junto às águas de Meribá de Cades, no deserto de Zim, pois não me santificastes no meio dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 32, 52, 'Pelo que verás a terra diante de ti, porém lá não entrarás, na terra que eu dou aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 1, 'Esta é a bênção com que Moisés, homem de Deus, abençoou os filhos de Israel antes da sua morte.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 2, 'Disse ele: O Senhor veio do Sinai, e de Seir raiou sobre nós; resplandeceu desde o monte Parã, e veio das miríades de santos; à sua direita havia para eles o fogo da lei.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 3, 'Na verdade ama o seu povo; todos os seus santos estão na sua mão; postos serão no meio, entre os teus pés, e cada um receberá das tuas palavras.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 4, 'Moisés nos prescreveu uma lei, uma herança para a assembléia de Jacó.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 5, 'E tornou-se rei em Jesurum, quando se congregaram os cabeças do povo juntamente com as tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 6, 'Viva Rúben, e não morra; e não sejam poucos os seus homens.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 7, 'E isto é o que disse de Judá: Ouve, ó Senhor, a voz de Judá e introduze-o no meio do seu povo; com as suas mãos pelejou por si; sê tu o seu auxílio contra os seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 8, 'De Levi disse: Sejam teu Tumim e teu Urim para o teu homem santo, que provaste em Massá, com quem contendeste junto às águas de Meribá;', 1, CURRENT_TIMESTAMP, false),
(5, 33, 9, 'aquele que disse de seu pai e de sua mãe: Nunca os vi, e não reconheceu a seus irmãos, e não conheceu a seus filhos; pois esses levitas guardaram a tua palavra e observaram o teu pacto.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 10, 'Ensinarão os teus preceitos a Jacó, e a tua lei a Israel; chegarão incenso ao seu nariz, e porão holocausto sobre o teu altar.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 11, 'Abençoa o seu poder, ó Senhor, e aceita a obra das suas mãos; fere os lombos dos que se levantam contra ele e o odeiam, para que nunca mais se levantem.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 12, 'De Benjamim disse: O amado do Senhor habitará seguro junto a ele; e o Senhor o cercará o dia todo, e ele habitará entre os seus ombros.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 13, 'De José disse: Abençoada pelo Senhor seja a sua terra, com os mais excelentes dons do céu, com o orvalho, e com as águas do abismo que jaz abaixo;', 1, CURRENT_TIMESTAMP, false),
(5, 33, 14, 'com os excelentes frutos do sol, e com os excelentes produtos dos meses;', 1, CURRENT_TIMESTAMP, false),
(5, 33, 15, 'com as coisas mais excelentes dos montes antigos, e com as coisas excelentes dos outeiros eternos;', 1, CURRENT_TIMESTAMP, false),
(5, 33, 16, 'com as coisas excelentes da terra, e com a sua plenitude, e com a benevolência daquele que habitava na sarça; venha tudo isso sobre a cabeça de José, sobre o alto da cabeça daquele que é príncipe entre seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 17, 'Eis o seu novilho primogênito; ele tem majestade; e os seus chifres são chifres de boi selvagem; com eles rechaçará todos os povos, sim, todas as extremidades da terra. Tais são as miríades de Efraim, e tais são os milhares de Manassés.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 18, 'De Zebulom disse: Zebulom, alegra-te nas tuas saídas; e tu, Issacar, nas tuas tendas.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 19, 'Eles chamarão os povos ao monte; ali oferecerão sacrifícios de justiça, porque chuparão a abundância dos mares e os tesouros escondidos da areia.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 20, 'De Gade disse: Bendito aquele que faz dilatar a Gade; habita como a leoa, e despedaça o braço, e o alto da cabeça.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 21, 'Ele se proveu da primeira parte, porquanto ali estava reservada a porção do legislador; pelo que veio com os chefes do povo, executou a justiça do Senhor e os seus juízos para com Israel.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 22, 'De Dã disse: Dã é cachorro de leão, que salta de Basã.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 23, 'De Naftali disse: ó Naftali, saciado de favores, e farto da bênção do Senhor, possui o lago e o sul.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 24, 'De Aser disse: Bendito seja Aser dentre os filhos de Israel; seja o favorecido de seus irmãos; e mergulhe em azeite o seu pé;', 1, CURRENT_TIMESTAMP, false),
(5, 33, 25, 'de ferro e de bronze sejam os teus ferrolhos; e como os teus dias, assim seja a tua força.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 26, 'Não há outro, ó Jesurum, semelhante a Deus, que cavalga sobre o céu para a tua ajuda, e na sua majestade sobre as mais altas nuvens.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 27, 'O Deus eterno é a tua habitação, e por baixo estão os braços eternos; ele lançou o inimigo de diante de ti e disse: Destrói-o.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 28, 'Israel pois habitará seguro, a fonte de Jacó a sós, na terra de grão e de mosto; e o seu céu gotejará o orvalho.', 1, CURRENT_TIMESTAMP, false),
(5, 33, 29, 'Feliz és tu, ó Israel! quem é semelhante a ti? um povo salvo pelo Senhor, o escudo do teu socorro, e a espada da tua majestade; pelo que os teus inimigos te serão sujeitos, e tu pisarás sobre as suas alturas.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 1, 'Então subiu Moisés das planícies de Moabe ao monte Nebo, ao cume de Pisga, que está defronte de Jericó; e o Senhor mostrou-lhe toda a terra desde Gileade até Dã,', 1, CURRENT_TIMESTAMP, false),
(5, 34, 2, 'todo o Naftali, a terra de Efraim e Manassés, toda a terra de Judá, até o mar ocidental,', 1, CURRENT_TIMESTAMP, false),
(5, 34, 3, 'o Negebe, e a planície do vale de Jericó, a cidade das palmeiras, até Zoar.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 4, 'E disse-lhe o Senhor: Esta é a terra que prometi com juramento a Abraão, a Isaque e a Jacó, dizendo: À tua descendência a darei. Eu te fiz vê-la com os teus olhos, porém para lá não passarás.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 5, 'Assim Moisés, servo do Senhor, morreu ali na terra de Moabe, conforme o dito do Senhor,', 1, CURRENT_TIMESTAMP, false),
(5, 34, 6, 'que o sepultou no vale, na terra de Moabe, defronte de Bete-Peor; e ninguém soube até hoje o lugar da sua sepultura.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 7, 'Tinha Moisés cento e vinte anos quando morreu; não se lhe escurecera a vista, nem se lhe fugira o vigor.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 8, 'Os filhos de Israel prantearam a Moisés por trinta dias nas planícies de Moabe; e os dias do pranto no luto por Moisés se cumpriram.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 9, 'Ora, Josué, filho de Num, foi cheio do espírito de sabedoria, porquanto Moisés lhe tinha imposto as mãos; assim se filhos de Israel lhe obedeceram , e fizeram como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(5, 34, 10, 'E nunca mais se levantou em Israel profeta como Moisés, a quem o Senhor conhecesse face a face,', 1, CURRENT_TIMESTAMP, false),
(5, 34, 11, 'nem semelhante em todos os sinais e maravilhas que o Senhor o enviou para fazer na terra do Egito, a Faraó: e a todos os seus servos, e a toda a sua terra;', 1, CURRENT_TIMESTAMP, false),
(5, 34, 12, 'e em tudo o que Moisés operou com mão forte, e com grande espanto, aos olhos de todo o Israel.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 1, 'Palavras do pregador, filho de Davi, rei em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 2, 'Vaidade de vaidades, diz o pregador; vaidade de vaidades, tudo é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 3, 'Que proveito tem o homem, de todo o seu trabalho, com que se afadiga debaixo do sol?', 1, CURRENT_TIMESTAMP, false),
(21, 1, 4, 'Uma geração vai-se, e outra geração vem, mas a terra permanece para sempre.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 5, 'O sol nasce, e o sol se põe, e corre de volta ao seu lugar donde nasce.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 6, 'O vento vai para o sul, e faz o seu giro vai para o norte; volve-se e revolve-se na sua carreira, e retoma os seus circuitos.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 7, 'Todos os ribeiros vão para o mar, e contudo o mar não se enche; ao lugar para onde os rios correm, para ali continuam a correr.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 8, 'Todas as coisas estão cheias de cansaço; ninguém o pode exprimir: os olhos não se fartam de ver, nem os ouvidos se enchem de ouvir.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 9, 'O que tem sido, isso é o que há de ser; e o que se tem feito, isso se tornará a fazer; nada há que seja novo debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 10, 'Há alguma coisa de que se possa dizer: Voê, isto é novo? ela já existiu nos séculos que foram antes de nós.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 11, 'Já não há lembrança das gerações passadas; nem das gerações futuras haverá lembrança entre os que virão depois delas.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 12, 'Eu, o pregador, fui rei sobre Israel em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 13, 'E apliquei o meu coração a inquirir e a investigar com sabedoria a respeito de tudo quanto se faz debaixo do céu; essa enfadonha ocupação deu Deus aos filhos dos homens para nela se exercitarem.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 14, 'Atentei para todas as obras que se e fazem debaixo do sol; e eis que tudo era vaidade e desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 15, 'O que é torto não se pode endireitar; o que falta não se pode enumerar.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 16, 'Falei comigo mesmo, dizendo: Eis que eu me engrandeci, e sobrepujei em sabedoria a todos os que houve antes de mim em Jerusalém; na verdade, tenho tido larga experiência da sabedoria e do conhecimento.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 17, 'E apliquei o coração a conhecer a sabedoria e a conhecer os desvarios e as loucuras; e vim a saber que também isso era desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 1, 18, 'Porque na muita sabedoria há muito enfado; e o que aumenta o conhecimento aumenta a tristeza.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 1, 'Disse eu a mim mesmo: Ora vem, eu te provarei com a alegria; portanto goza o prazer; mas eis que também isso era vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 2, 'Do riso disse: Está doido; e da alegria: De que serve estar.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 3, 'Busquei no meu coração como estimular com vinho a minha carne, sem deixar de me guiar pela sabedoria, e como me apoderar da estultícia, até ver o que era bom que os filhos dos homens fizessem debaixo do céu, durante o número dos dias de sua vida.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 4, 'Fiz para mim obras magníficas: edifiquei casas, plantei vinhas;', 1, CURRENT_TIMESTAMP, false),
(21, 2, 5, 'fiz hortas e jardins, e plantei neles árvores frutíferas de todas as espécies.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 6, 'Fiz tanques de águas, para deles regar o bosque em que reverdeciam as árvores.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 7, 'Comprei servos e servas, e tive servos nascidos em casa; também tive grandes possessões de gados e de rebanhos, mais do que todos os que houve antes de mim em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 8, 'Ajuntei também para mim prata e ouro, e tesouros dos reis e das províncias; provi-me de cantores e cantoras, e das delícias dos filhos dos homens, concubinas em grande número.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 9, 'Assim me engrandeci, e me tornei mais rico do que todos os que houve antes de mim em Jerusalém; perseverou também comigo a minha sabedoria.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 10, 'E tudo quanto desejaram os meus olhos não lho neguei, nem privei o meu coração de alegria alguma; pois o meu coração se alegrou por todo o meu trabalho, e isso foi o meu proveito de todo o meu trabalho.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 11, 'Então olhei eu para todas as obras que as minhas mãos haviam feito, como também para o trabalho que eu aplicara em fazê-las; e eis que tudo era vaidade e desejo vão, e proveito nenhum havia debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 12, 'Virei-me para contemplar a sabedoria, e a loucura, e a estultícia; pois que fará o homem que seguir ao rei? O mesmo que já se fez!', 1, CURRENT_TIMESTAMP, false),
(21, 2, 13, 'Então vi eu que a sabedoria é mais excelente do que a estultícia, quanto a luz é mais excelente do que as trevas.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 14, 'Os olhos do sábio estão na sua cabeça, mas o louco anda em trevas; contudo percebi que a mesma coisa lhes sucede a ambos.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 15, 'Pelo que eu disse no meu coração: Como acontece ao estulto, assim me sucederá a mim; por que então busquei eu mais a sabedoria; Então respondi a mim mesmo que também isso era vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 16, 'Pois do sábio, bem como do estulto, a memória não durará para sempre; porquanto de tudo, nos dias futuros, total esquecimento haverá. E como morre o sábio, assim morre o estulto!', 1, CURRENT_TIMESTAMP, false),
(21, 2, 17, 'Pelo que aborreci a vida, porque a obra que se faz debaixo do sol me era penosa; sim, tudo é vaidade e desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 18, 'Também eu aborreci todo o meu trabalho em que me afadigara debaixo do sol, visto que tenho de deixá-lo ao homem que virá depois de mim.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 19, 'E quem sabe se será sábio ou estulto? Contudo, ele se assenhoreará de todo o meu trabalho em que me afadiguei, e em que me houve sabiamente debaixo do sol; também isso é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 20, 'Pelo que eu me volvi e entreguei o meu coração ao desespero no tocante a todo o trabalho em que me afadigara debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 21, 'Porque há homem cujo trabalho é feito com sabedoria, e ciência, e destreza; contudo, deixará o fruto do seu labor para ser porção de quem não trabalhou nele; também isso é vaidade e um grande mal.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 22, 'Pois, que alcança o homem com todo o seu trabalho e com a fadiga em que ele anda trabalhando debaixo do sol?', 1, CURRENT_TIMESTAMP, false),
(21, 2, 23, 'Porque todos os seus dias são dores, e o seu trabalho é vexação; nem de noite o seu coração descansa. Também isso é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 24, 'Não há nada melhor para o homem do que comer e beber, e fazer que a sua alma goze do bem do seu trabalho. Vi que também isso vem da mão de Deus.', 1, CURRENT_TIMESTAMP, false),
(21, 2, 25, 'Pois quem pode comer, ou quem pode gozar. melhor do que eu?', 1, CURRENT_TIMESTAMP, false),
(21, 2, 26, 'Porque ao homem que lhe agrada, Deus dá sabedoria, e conhecimento, e alegria; mas ao pecador dá trabalho, para que ele ajunte e amontoe, a fim de dá-lo àquele que agrada a Deus: Também isso é vaidade e desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 1, 'Tudo tem a sua ocasião própria, e há tempo para todo propósito debaixo do céu.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 2, 'Há tempo de nascer, e tempo de morrer; tempo de plantar, e tempo de arrancar o que se plantou;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 3, 'tempo de matar, e tempo de curar; tempo de derribar, e tempo de edificar;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 4, 'tempo de chorar, e tempo de rir; tempo de prantear, e tempo de dançar;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 5, 'tempo de espalhar pedras, e tempo de ajuntar pedras; tempo de abraçar, e tempo de abster-se de abraçar;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 6, 'tempo de buscar, e tempo de perder; tempo de guardar, e tempo de deitar fora;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 7, 'tempo de rasgar, e tempo de coser; tempo de estar calado, e tempo de falar;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 8, 'tempo de amar, e tempo de odiar; tempo de guerra, e tempo de paz.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 9, 'Que proveito tem o trabalhador naquilo em que trabalha?', 1, CURRENT_TIMESTAMP, false),
(21, 3, 10, 'Tenho visto o trabalho penoso que Deus deu aos filhos dos homens para nele se exercitarem.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 11, 'Tudo fez formoso em seu tempo; também pôs na mente do homem a idéia da eternidade, se bem que este não possa descobrir a obra que Deus fez desde o princípio até o fim.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 12, 'Sei que não há coisa melhor para eles do que se regozijarem e fazerem o bem enquanto viverem;', 1, CURRENT_TIMESTAMP, false),
(21, 3, 13, 'e também que todo homem coma e beba, e goze do bem de todo o seu trabalho é dom de Deus.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 14, 'Eu sei que tudo quanto Deus faz durará eternamente; nada se lhe pode acrescentar, e nada se lhe pode tirar; e isso Deus faz para que os homens temam diante dele:', 1, CURRENT_TIMESTAMP, false),
(21, 3, 15, 'O que é, já existiu; e o que há de ser, também já existiu; e Deus procura de novo o que já se passou.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 16, 'Vi ainda debaixo do sol que no lugar da retidão estava a impiedade; e que no lugar da justiça estava a impiedade ainda.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 17, 'Eu disse no meu coração: Deus julgará o justo e o ímpio; porque há um tempo para todo propósito e para toda obra.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 18, 'Disse eu no meu coração: Isso é por causa dos filhos dos homens, para que Deus possa prová-los, e eles possam ver que são em si mesmos como os brutos.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 19, 'Pois o que sucede aos filhos dos homens, isso mesmo também sucede aos brutos; uma e a mesma coisa lhes sucede; como morre um, assim morre o outro; todos têm o mesmo fôlego; e o homem não tem vantagem sobre os brutos; porque tudo é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 20, 'Todos vão para um lugar; todos são pó, e todos ao pó tornarão.', 1, CURRENT_TIMESTAMP, false),
(21, 3, 21, 'Quem sabe se o espírito dos filhos dos homens vai para cima, e se o espírito dos brutos desce para a terra?', 1, CURRENT_TIMESTAMP, false),
(21, 3, 22, 'Pelo que tenho visto que não há coisa melhor do que alegrar-se o homem nas suas obras; porque esse é o seu quinhão; pois quem o fará voltar para ver o que será depois dele?', 1, CURRENT_TIMESTAMP, false),
(21, 4, 1, 'Depois volvi-me, e atentei para todas as opressões que se fazem debaixo do sol; e eis as lágrimas dos oprimidos, e eles não tinham consolador; do lado dos seus opressores havia poder; mas eles não tinham consolador.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 2, 'Pelo que julguei mais felizes os que já morreram, do que os que vivem ainda.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 3, 'E melhor do que uns e outros é aquele que ainda não é, e que não viu as más obras que se fazem debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 4, 'Também vi eu que todo trabalho e toda destreza em obras provêm da inveja que o homem tem do seu próximo. Também isso é e vaidade e desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 5, 'O tolo cruza as mãos, e come a sua; própria carne.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 6, 'Melhor é um punhado com tranqüilidade do que ambas as mãos cheias com trabalho e vão desejo.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 7, 'Outra vez me volvi, e vi vaidade debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 8, 'Há um que é só, não tendo parente; não tem filho nem irmão e, contudo, de todo o seu trabalho não há fim, nem os seus olhos se fartam de riquezas. E ele não pergunta: Para quem estou trabalhando e privando do bem a minha alma? Também isso é vaidade a e enfadonha ocupação.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 9, 'Melhor é serem dois do que um, porque têm melhor paga do seu trabalho.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 10, 'Pois se caírem, um levantará o seu companheiro; mas ai do que estiver só, pois, caindo, não haverá outro que o levante.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 11, 'Também, se dois dormirem juntos, eles se aquentarão; mas um só como se aquentará?', 1, CURRENT_TIMESTAMP, false),
(21, 4, 12, 'E, se alguém quiser prevalecer contra um, os dois lhe resistirão; e o cordão de três dobras não se quebra tão depressa.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 13, 'Melhor é o mancebo pobre e sábio do que o rei velho e insensato, que não se deixa mais admoestar,', 1, CURRENT_TIMESTAMP, false),
(21, 4, 14, 'embora tenha saído do cárcere para reinar, ou tenha nascido pobre no seu próprio reino.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 15, 'Vi a todos os viventes que andavam debaixo do sol, e eles estavam com o mancebo, o sucessor, que havia de ficar no lugar do rei.', 1, CURRENT_TIMESTAMP, false),
(21, 4, 16, 'Todo o povo, à testa do qual se achava, era inumerável; contudo os que lhe sucederam não se regozijarão a respeito dele. Na verdade também isso é vaidade e desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 1, 'Guarda o teu pé, quando fores à casa de Deus; porque chegar-se para ouvir é melhor do que oferecer sacrifícios de tolos; pois não sabem que fazem mal.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 2, 'Não te precipites com a tua boca, nem o teu coração se apresse a pronunciar palavra alguma na presença de Deus; porque Deus está no céu, e tu estás sobre a terra; portanto sejam poucas as tuas palavras.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 3, 'Porque, da multidão de trabalhos vêm os sonhos, e da multidão de palavras, a voz do tolo.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 4, 'Quando a Deus fizeres algum voto, não tardes em cumpri-lo; porque não se agrada de tolos. O que votares, paga-o.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 5, 'Melhor é que não votes do que votares e não pagares.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 6, 'Não consintas que a tua boca faça pecar a tua carne, nem digas na presença do anjo que foi erro; por que razão se iraria Deus contra a tua voz, e destruiria a obra das tuas mãos?', 1, CURRENT_TIMESTAMP, false),
(21, 5, 7, 'Porque na multidão dos sonhos há vaidades e muitas palavras; mas tu teme a Deus.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 8, 'Se vires em alguma província opressão de pobres, e a perversão violenta do direito e da justiça, não te maravilhes de semelhante caso. Pois quem está altamente colocado tem superior que o vigia; e há mais altos ainda sobre eles.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 9, 'O proveito da terra é para todos; até o rei se serve do campo.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 10, 'Quem ama o dinheiro não se fartará de dinheiro; nem o que ama a riqueza se fartará do ganho; também isso é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 11, 'Quando se multiplicam os bens, multiplicam-se também os que comem; e que proveito tem o seu dono senão o de vê-los com os seus olhos?', 1, CURRENT_TIMESTAMP, false),
(21, 5, 12, 'Doce é o sono do trabalhador, quer coma pouco quer muito; mas a saciedade do rico não o deixa dormir.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 13, 'Há um grave mal que vi debaixo do sol: riquezas foram guardadas por seu dono para o seu próprio dano;', 1, CURRENT_TIMESTAMP, false),
(21, 5, 14, 'e as mesmas riquezas se perderam por qualquer má aventura; e havendo algum filho nada fica na sua mão.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 15, 'Como saiu do ventre de sua mãe, assim também se irá, nu como veio; e nada tomará do seu trabalho, que possa levar na mão.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 16, 'Ora isso é um grave mal; porque justamente como veio, assim há de ir; e que proveito lhe vem de ter trabalhado para o vento,', 1, CURRENT_TIMESTAMP, false),
(21, 5, 17, 'e de haver passado todos os seus dias nas trevas, e de haver padecido muito enfado, enfermidades e aborrecimento?', 1, CURRENT_TIMESTAMP, false),
(21, 5, 18, 'Eis aqui o que eu vi, uma boa e bela coisa: alguém comer e beber, e gozar cada um do bem de todo o seu trabalho, com que se afadiga debaixo do sol, todos os dias da vida que Deus lhe deu; pois esse é o seu quinhão.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 19, 'E quanto ao homem a quem Deus deu riquezas e bens, e poder para desfrutá-los, receber o seu quinhão, e se regozijar no seu trabalho, isso é dom de Deus.', 1, CURRENT_TIMESTAMP, false),
(21, 5, 20, 'Pois não se lembrará muito dos dias da sua vida; porque Deus lhe enche de alegria o coração.', 1, CURRENT_TIMESTAMP, false),
(21, 6, 1, 'Há um mal que tenho visto debaixo do sol, e que pesa muito sobre o homem:', 1, CURRENT_TIMESTAMP, false),
(21, 6, 2, 'um homem a quem Deus deu riquezas, bens e honra, de maneira que nada lhe falta de tudo quanto ele deseja, contudo Deus não lhe dá poder para daí comer, antes o estranho lho come; também isso é vaidade e grande mal.', 1, CURRENT_TIMESTAMP, false),
(21, 6, 3, 'Se o homem gerar cem filhos, e viver muitos anos, de modo que os dias da sua vida sejam muitos, porém se a sua alma não se fartar do bem, e além disso não tiver sepultura, digo que um aborto é melhor do que ele;', 1, CURRENT_TIMESTAMP, false),
(21, 6, 4, 'porquanto debalde veio, e em trevas se vai, e de trevas se cobre o seu nome;', 1, CURRENT_TIMESTAMP, false),
(21, 6, 5, 'e ainda que nunca viu o sol, nem o conheceu, mais descanso tem do que o tal;', 1, CURRENT_TIMESTAMP, false),
(21, 6, 6, 'e embora vivesse duas vezes mil anos, mas não gozasse o bem. Não vão todos para um mesmo lugar?', 1, CURRENT_TIMESTAMP, false),
(21, 6, 7, 'Todo o trabalho do homem é para a sua boca, e contudo não se satisfaz o seu apetite.', 1, CURRENT_TIMESTAMP, false),
(21, 6, 8, 'Pois, que vantagem tem o sábio sobre o tolo? e que tem o pobre que sabe andar perante os vivos?', 1, CURRENT_TIMESTAMP, false),
(21, 6, 9, 'Melhor é a vista dos olhos do que o vaguear da cobiça; também isso é vaidade, e desejo vão.', 1, CURRENT_TIMESTAMP, false),
(21, 6, 10, 'Seja qualquer o que for, já há muito foi chamado pelo seu nome; e sabe-se que é homem; e ele não pode contender com o que é mais forte do que ele.', 1, CURRENT_TIMESTAMP, false),
(21, 6, 11, 'Visto que as muitas palavras aumentam a vaidade, que vantagem tira delas o homem?', 1, CURRENT_TIMESTAMP, false),
(21, 6, 12, 'Porque, quem sabe o que é bom nesta vida para o homem, durante os poucos dias da sua vida vã, os quais gasta como sombra? pois quem declarará ao homem o que será depois dele debaixo do sol?', 1, CURRENT_TIMESTAMP, false),
(21, 7, 1, 'Melhor é o bom nome do que o melhor ungüento, e o dia da morte do que o dia do nascimento.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 2, 'Melhor é ir à casa onde há luto do que ir a casa onde há banquete; porque naquela se vê o fim de todos os homens, e os vivos o aplicam ao seu coração.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 3, 'Melhor é a mágoa do que o riso, porque a tristeza do rosto torna melhor o coração.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 4, 'O coração dos sábios está na casa do luto, mas o coração dos tolos na casa da alegria.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 5, 'Melhor é ouvir a repreensão do sábio do que ouvir alguém a canção dos tolos.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 6, 'Pois qual o crepitar dos espinhos debaixo da panela, tal é o riso do tolo; também isso é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 7, 'Verdadeiramente a opressão faz endoidecer até o sábio, e a peita corrompe o coração.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 8, 'Melhor é o fim duma coisa do que o princípio; melhor é o paciente do que o arrogante.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 9, 'Não te apresses no teu espírito a irar-te, porque a ira abriga-se no seio dos tolos.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 10, 'Não digas: Por que razão foram os dias passados melhores do que estes; porque não provém da sabedoria esta pergunta.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 11, 'Tão boa é a sabedoria como a herança, e mesmo de mais proveito para os que vêem o sol.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 12, 'Porque a sabedoria serve de defesa, como de defesa serve o dinheiro; mas a excelência da sabedoria é que ela preserva a vida de quem a possui.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 13, 'Considera as obras de Deus; porque quem poderá endireitar o que ele fez torto?', 1, CURRENT_TIMESTAMP, false),
(21, 7, 14, 'No dia da prosperidade regozija-te, mas no dia da adversidade considera; porque Deus fez tanto este como aquele, para que o homem nada descubra do que há de vir depois dele.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 15, 'Tudo isto vi nos dias da minha vaidade: há justo que perece na sua justiça, e há ímpio que prolonga os seus dias na sua maldade.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 16, 'Não sejas demasiadamente justo, nem demasiadamente sábio; por que te destruirias a ti mesmo?', 1, CURRENT_TIMESTAMP, false),
(21, 7, 17, 'Não sejas demasiadamente ímpio, nem sejas tolo; por que morrerias antes do teu tempo?', 1, CURRENT_TIMESTAMP, false),
(21, 7, 18, 'Bom é que retenhas isso, e que também daquilo não retires a tua mão; porque quem teme a Deus escapa de tudo isso.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 19, 'A sabedoria fortalece ao sábio mais do que dez governadores que haja na cidade.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 20, 'Pois não há homem justo sobre a terra, que faça o bem, e nunca peque.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 21, 'Não escutes a todas as palavras que se disserem, para que não venhas a ouvir o teu servo amaldiçoar-te;', 1, CURRENT_TIMESTAMP, false),
(21, 7, 22, 'pois tu sabes também que muitas vezes tu amaldiçoaste a outros.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 23, 'Tudo isto provei-o pela sabedoria; e disse: Far-me-ei sábio; porém a sabedoria ainda ficou longe de mim.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 24, 'Longe está o que já se foi, e profundíssimo; quem o poderá achar?', 1, CURRENT_TIMESTAMP, false),
(21, 7, 25, 'Eu me volvi, e apliquei o meu coração para saber, e inquirir, e buscar a sabedoria e a razão de tudo, e para conhecer que a impiedade é insensatez e que a estultícia é loucura.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 26, 'E eu achei uma coisa mais amarga do que a morte, a mulher cujo coração são laços e redes, e cujas mãos são grilhões; quem agradar a Deus escapará dela; mas o pecador virá a ser preso por ela.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 27, 'Vedes aqui, isto achei, diz o pregador, conferindo uma coisa com a outra para achar a causa;', 1, CURRENT_TIMESTAMP, false),
(21, 7, 28, 'causa que ainda busco, mas não a achei; um homem entre mil achei eu, mas uma mulher entre todas, essa não achei.', 1, CURRENT_TIMESTAMP, false),
(21, 7, 29, 'Eis que isto tão-somente achei: que Deus fez o homem reto, mas os homens buscaram muitos artifícios.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 1, 'Quem é como o sábio? e quem sabe a interpretação das coisas? A sabedoria do homem faz brilhar o seu rosto, e com ela a dureza do seu rosto se transforma.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 2, 'Eu digo: Observa o mandamento do rei, e isso por causa do juramento a Deus.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 3, 'Não te apresses a sair da presença dele; nem persistas em alguma coisa má; porque ele faz tudo o que lhe agrada.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 4, 'Porque a palavra do rei é suprema; e quem lhe dirá: que fazes?', 1, CURRENT_TIMESTAMP, false),
(21, 8, 5, 'Quem guardar o mandamento não experimentará nenhum mal; e o coração do sábio discernirá o tempo e o juízo.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 6, 'Porque para todo propósito há tempo e juízo; porquanto a miséria do homem pesa sobre ele.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 7, 'Porque não sabe o que há de suceder; pois quem lho dará a entender como há de ser?', 1, CURRENT_TIMESTAMP, false),
(21, 8, 8, 'Nenhum homem há que tenha domínio sobre o espírito, para o reter; nem que tenha poder sobre o dia da morte; nem há licença em tempo de guerra; nem tampouco a impiedade livrará aquele que a ela está entregue.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 9, 'Tudo isto tenho observado enquanto aplicava o meu coração a toda obra que se faz debaixo do sol; tempo há em que um homem tem domínio sobre outro homem para o seu próprio dano.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 10, 'Vi também os ímpios sepultados, os que antes entravam e saíam do lugar santo; e foram esquecidos na cidade onde haviam assim procedido; também isso é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 11, 'Porquanto não se executa logo o juízo sobre a má obra, o coração dos filhos dos homens está inteiramente disposto para praticar o mal.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 12, 'Ainda que o pecador faça o mal cem vezes, e os dias se lhe prolonguem, contudo eu sei com certeza que bem sucede aos que temem a Deus, porque temem diante dele;', 1, CURRENT_TIMESTAMP, false),
(21, 8, 13, 'ao ímpio, porém, não irá bem, e ele não prolongará os seus dias, que são como a sombra; porque ele não teme diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 14, 'Ainda há outra vaidade que se faz sobre a terra: há justos a quem sucede segundo as obras dos ímpios, e há ímpios a quem sucede segundo as obras dos justos. Eu disse que também isso é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 15, 'Exalto, pois, a alegria, porquanto o homem nenhuma coisa melhor tem debaixo do sol do que comer, beber e alegrar-se; porque isso o acompanhará no seu trabalho nos dias da sua vida que Deus lhe dá debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 8, 16, 'Quando apliquei o meu coração a conhecer a sabedoria, e a ver o trabalho que se faz sobre a terra {pois homens há que nem de dia nem de noite conseguem dar sono aos seus olhos},', 1, CURRENT_TIMESTAMP, false),
(21, 8, 17, 'então contemplei toda obra de Deus, e vi que o homem não pode compreender a obra que se faz debaixo do sol; pois por mais que o homem trabalhe para a descobrir, não a achará; embora o sábio queira conhecê-la, nem por isso a poderá compreender.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 1, 'Deveras a tudo isto apliquei o meu coração, para claramente entender tudo isto: que os justos, e os sábios, e as suas obras, estão nas mãos de Deus; se é amor ou se é ódio, não o sabe o homem; tudo passa perante a sua face.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 2, 'Tudo sucede igualmente a todos: o mesmo sucede ao justo e ao ímpio, ao bom e ao mau, ao puro e ao impuro; assim ao que sacrifica como ao que não sacrifica; assim ao bom como ao pecador; ao que jura como ao que teme o juramento.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 3, 'Este é o mal que há em tudo quanto se faz debaixo do sol: que a todos sucede o mesmo. Também o coração dos filhos dos homens está cheio de maldade; há desvarios no seu coração durante a sua vida, e depois se vão aos mortos.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 4, 'Ora, para aquele que está na companhia dos vivos há esperança; porque melhor é o cão vivo do que o leão morto.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 5, 'Pois os vivos sabem que morrerão, mas os mortos não sabem coisa nenhuma, nem tampouco têm eles daí em diante recompensa; porque a sua memória ficou entregue ao esquecimento.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 6, 'Tanto o seu amor como o seu ódio e a sua inveja já pereceram; nem têm eles daí em diante parte para sempre em coisa alguma do que se faz debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 7, 'Vai, pois, come com alegria o teu pão .e bebe o teu vinho com coração contente; pois há muito que Deus se agrada das tuas obras.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 8, 'Sejam sempre alvas as tuas vestes, e nunca falte o óleo sobre a tua cabeça.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 9, 'Goza a vida com a mulher que amas, todos os dias da tua vida vã, os quais Deus te deu debaixo do sol, todos os dias da tua vida vã; porque este é o teu quinhão nesta vida, e do teu trabalho, que tu fazes debaixo do sol.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 10, 'Tudo quanto te vier à mão para fazer, faze-o conforme as tuas forças; porque no Seol, para onde tu vais, não há obra, nem projeto, nem conhecimento, nem sabedoria alguma.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 11, 'Observei ainda e vi que debaixo do sol não é dos ligeiros a carreira, nem dos fortes a peleja, nem tampouco dos sábios o pão, nem ainda dos prudentes a riqueza, nem dos entendidos o favor; mas que a ocasião e a sorte ocorrem a todos.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 12, 'Pois o homem não conhece a sua hora. Como os peixes que se apanham com a rede maligna, e como os passarinhos que se prendem com o laço, assim se enlaçam também os filhos dos homens no mau tempo, quando este lhes sobrevém de repente.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 13, 'Também vi este exemplo de sabedoria debaixo do sol, que me pareceu grande:', 1, CURRENT_TIMESTAMP, false),
(21, 9, 14, 'Houve uma pequena cidade em que havia poucos homens; e veio contra ela um grande rei, e a cercou e levantou contra ela grandes tranqueiras.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 15, 'Ora, achou-se nela um sábio pobre, que livrou a cidade pela sua sabedoria; contudo ninguém se lembrou mais daquele homem pobre.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 16, 'Então disse eu: Melhor é a sabedoria do que a força; todavia a sabedoria do pobre é desprezada, e as suas palavras não são ouvidas.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 17, 'As palavras dos sábios ouvidas em silêncio valem mais do que o clamor de quem governa entre os tolos.', 1, CURRENT_TIMESTAMP, false),
(21, 9, 18, 'Melhor é a sabedoria do que as armas de guerra; mas um só pecador faz grande dano ao bem.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 1, 'As moscas mortas fazem com que o ungüento do perfumista emita mau cheiro; assim um pouco de estultícia pesa mais do que a sabedoria e a honra.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 2, 'O coração do sábio o inclina para a direita, mas o coração do tolo o inclina para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 3, 'E, até quando o tolo vai pelo caminho, falta-lhe o entendimento, e ele diz a todos que é tolo.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 4, 'Se levantar contra ti o espírito do governador, não deixes o teu lugar; porque a deferência desfaz grandes ofensas.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 5, 'Há um mal que vi debaixo do sol, semelhante a um erro que procede do governador:', 1, CURRENT_TIMESTAMP, false),
(21, 10, 6, 'a estultícia está posta em grande dignidade, e os ricos estão assentados em lugar humilde.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 7, 'Tenho visto servos montados a cavalo, e príncipes andando a pé como servos.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 8, 'Aquele que abrir uma cova, nela cairá; e quem romper um muro, uma cobra o morderá.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 9, 'Aquele que tira pedras é maltratado por elas, e o que racha lenha corre perigo nisso.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 10, 'Se estiver embotado o ferro, e não se afiar o corte, então se deve pôr mais força; mas a sabedoria é proveitosa para dar prosperidade.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 11, 'Se a cobra morder antes de estar encantada, não há vantagem no encantador.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 12, 'As palavras da boca do sábio são cheias de graça, mas os lábios do tolo o devoram.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 13, 'O princípio das palavras da sua boca é estultícia, e o fim do seu discurso é loucura perversa.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 14, 'O tolo multiplica as palavras, todavia nenhum homem sabe o que há de ser; e quem lhe poderá declarar o que será depois dele?', 1, CURRENT_TIMESTAMP, false),
(21, 10, 15, 'O trabalho do tolo o fatiga, de sorte que não sabe ir à cidade.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 16, 'Ai de ti, ó terra, quando o teu rei é criança, e quando os teus príncipes banqueteiam de manhã!', 1, CURRENT_TIMESTAMP, false),
(21, 10, 17, 'Bem-aventurada tu, ó terra, quando o teu rei é filho de nobres, e quando os teus príncipes comem a tempo, para refazerem as forças, e não para bebedice!', 1, CURRENT_TIMESTAMP, false),
(21, 10, 18, 'Pela preguiça se enfraquece o teto, e pela frouxidão das mãos a casa tem goteiras.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 19, 'Para rir é que se dá banquete, e o vinho alegra a vida; e por tudo o dinheiro responde.', 1, CURRENT_TIMESTAMP, false),
(21, 10, 20, 'Nem ainda no teu pensamento amaldições o rei; nem tampouco na tua recâmara amaldiçoes o rico; porque as aves dos céus levarão a voz, e uma criatura alada dará notícia da palavra.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 1, 'Lança o teu pão sobre as águas, porque depois de muitos dias o acharás.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 2, 'Reparte com sete, e ainda até com oito; porque não sabes que mal haverá sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 3, 'Estando as nuvens cheias de chuva, derramam-na sobre a terra. Caindo a árvore para o sul, ou para o norte, no lugar em que a árvore cair, ali ficará.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 4, 'Quem observa o vento, não semeará, e o que atenta para as nuvens não segará.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 5, 'Assim como tu não sabes qual o caminho do vento, nem como se formam os ossos no ventre da que está grávida, assim também não sabes as obras de Deus, que faz todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 6, 'Pela manhã semeia a tua semente, e à tarde não retenhas a tua mão; pois tu não sabes qual das duas prosperará, se esta, se aquela, ou se ambas serão, igualmente boas.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 7, 'Doce é a luz, e agradável é aos olhos ver o sol.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 8, 'Se, pois, o homem viver muitos anos, regozije-se em todos eles; contudo lembre-se dos dias das trevas, porque hão de ser muitos. Tudo quanto sucede é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 9, 'Alegra-te, mancebo, na tua mocidade, e anime-te o teu coração nos dias da tua mocidade, e anda pelos caminhos do teu coração, e pela vista dos teus olhos; sabe, porém, que por todas estas coisas Deus te trará a juízo.', 1, CURRENT_TIMESTAMP, false),
(21, 11, 10, 'Afasta, pois, do teu coração o desgosto, remove da tua carne o mal; porque a mocidade e a aurora da vida são vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 1, 'Lembra-te também do teu Criador nos dias da tua mocidade, antes que venham os maus dias, e cheguem os anos em que dirás: Não tenho prazer neles;', 1, CURRENT_TIMESTAMP, false),
(21, 12, 2, 'antes que se escureçam o sol e a luz, e a lua, e as estrelas, e tornem a vir as nuvens depois da chuva;', 1, CURRENT_TIMESTAMP, false),
(21, 12, 3, 'no dia em que tremerem os guardas da casa, e se curvarem os homens fortes, e cessarem os moedores, por já serem poucos, e se escurecerem os que olham pelas janelas,', 1, CURRENT_TIMESTAMP, false),
(21, 12, 4, 'e as portas da rua se fecharem; quando for baixo o ruído da moedura, e nos levantarmos à voz das aves, e todas as filhas da música ficarem abatidas;', 1, CURRENT_TIMESTAMP, false),
(21, 12, 5, 'como também quando temerem o que é alto, e houver espantos no caminho; e florescer a amendoeira, e o gafanhoto for um peso, e falhar o desejo; porque o homem se vai à sua casa eterna, e os pranteadores andarão rodeando pela praça;', 1, CURRENT_TIMESTAMP, false),
(21, 12, 6, 'antes que se rompa a cadeia de prata, ou se quebre o copo de ouro, ou se despedace o cântaro junto à fonte, ou se desfaça a roda junto à cisterna,', 1, CURRENT_TIMESTAMP, false),
(21, 12, 7, 'e o pó volte para a terra como o era, e o espírito volte a Deus que o deu.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 8, 'Vaidade de vaidades, diz o pregador, tudo é vaidade.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 9, 'Além de ser sábio, o pregador também ensinou ao povo o conhecimento, meditando, e estudando, e pondo em ordem muitos provérbios.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 10, 'Procurou o pregador achar palavras agradáveis, e escreveu com acerto discursos plenos de verdade.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 11, 'As palavras dos sábios são como aguilhões; e como pregos bem fixados são as palavras coligidas dos mestres, as quais foram dadas pelo único pastor.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 12, 'Além disso, filho meu, sê avisado. De fazer muitos livros não há fim; e o muito estudar é enfado da carne.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 13, 'Este é o fim do discurso; tudo já foi ouvido: Teme a Deus, e guarda os seus mandamentos; porque isto é todo o dever do homem.', 1, CURRENT_TIMESTAMP, false),
(21, 12, 14, 'Porque Deus há de trazer a juízo toda obra, e até tudo o que está encoberto, quer seja bom, quer seja mau.', 1, CURRENT_TIMESTAMP, false),
(49, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, aos santos que estão em Éfeso, e fiéis em Cristo Jesus:', 1, CURRENT_TIMESTAMP, false),
(49, 1, 2, 'Graça a vós, e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(49, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o qual nos abençoou com todas as bênçãos espirituais nas regiões celestes em Cristo;', 1, CURRENT_TIMESTAMP, false),
(49, 1, 4, 'como também nos elegeu nele antes da fundação do mundo, para sermos santos e irrepreensíveis diante dele em amor;', 1, CURRENT_TIMESTAMP, false),
(49, 1, 5, 'e nos predestinou para sermos filhos de adoção por Jesus Cristo, para si mesmo, segundo o beneplácito de sua vontade,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 6, 'para o louvor da glória da sua graça, a qual nos deu gratuitamente no Amado;', 1, CURRENT_TIMESTAMP, false),
(49, 1, 7, 'em quem temos a redenção pelo seu sangue, a redenção dos nossos delitos, segundo as riquezas da sua graça,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 8, 'que ele fez abundar para conosco em toda a sabedoria e prudência,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 9, 'fazendo-nos conhecer o mistério da sua vontade, segundo o seu beneplácito, que nele propôs', 1, CURRENT_TIMESTAMP, false),
(49, 1, 10, 'para a dispensação da plenitude dos tempos, de fazer convergir em Cristo todas as coisas, tanto as que estão nos céus como as que estão na terra,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 11, 'nele, digo, no qual também fomos feitos herança, havendo sido predestinados conforme o propósito daquele que faz todas as coisas segundo o conselho da sua vontade,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 12, 'com o fim de sermos para o louvor da sua glória, nós, os que antes havíamos esperado em Cristo;', 1, CURRENT_TIMESTAMP, false),
(49, 1, 13, 'no qual também vós, tendo ouvido a palavra da verdade, o evangelho da vossa salvação, e tendo nele também crido, fostes selados com o Espírito Santo da promessa,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 14, 'o qual é o penhor da nossa herança, para redenção da possessão de Deus, para o louvor da sua glória.', 1, CURRENT_TIMESTAMP, false),
(49, 1, 15, 'Por isso também eu, tendo ouvido falar da fé que entre vós há no Senhor Jesus e do vosso amor para com todos os santos,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 16, 'não cesso de dar graças por vós, lembrando-me de vós nas minhas orações,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 17, 'para que o Deus de nosso Senhor Jesus Cristo, o Pai da glória, vos dê o espírito de sabedoria e de revelação no pleno conhecimento dele;', 1, CURRENT_TIMESTAMP, false),
(49, 1, 18, 'sendo iluminados os olhos do vosso coração, para que saibais qual seja a esperança da sua vocação, e quais as riquezas da glória da sua herança nos santos,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 19, 'e qual a suprema grandeza do seu poder para conosco, os que cremos, segundo a operação da força do seu poder,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 20, 'que operou em Cristo, ressuscitando-o dentre os mortos e fazendo-o sentar-se à sua direita nos céus,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 21, 'muito acima de todo principado, e autoridade, e poder, e domínio, e de todo nome que se nomeia, não só neste século, mas também no vindouro;', 1, CURRENT_TIMESTAMP, false),
(49, 1, 22, 'e sujeitou todas as coisas debaixo dos seus pés, e para ser cabeça sobre todas as coisas o deu à igreja,', 1, CURRENT_TIMESTAMP, false),
(49, 1, 23, 'que é o seu corpo, o complemento daquele que cumpre tudo em todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 1, 'Ele vos vivificou, estando vós mortos nos vossos delitos e pecados,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 2, 'nos quais outrora andastes, segundo o curso deste mundo, segundo o príncipe das potestades do ar, do espírito que agora opera nos filhos de desobediência,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 3, 'entre os quais todos nós também antes andávamos nos desejos da nossa carne, fazendo a vontade da carne e dos pensamentos; e éramos por natureza filhos da ira, como também os demais.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 4, 'Mas Deus, sendo rico em misericórdia, pelo seu muito amor com que nos amou,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 5, 'estando nós ainda mortos em nossos delitos, nos vivificou juntamente com Cristo {pela graça sois salvos},', 1, CURRENT_TIMESTAMP, false),
(49, 2, 6, 'e nos ressuscitou juntamente com ele, e com ele nos fez sentar nas regiões celestes em Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 7, 'para mostrar nos séculos vindouros a suprema riqueza da sua graça, pela sua bondade para conosco em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 8, 'Porque pela graça sois salvos, por meio da fé, e isto não vem de vós, é dom de Deus;', 1, CURRENT_TIMESTAMP, false),
(49, 2, 9, 'não vem das obras, para que ninguém se glorie.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 10, 'Porque somos feitura sua, criados em Cristo Jesus para boas obras, as quais Deus antes preparou para que andássemos nelas.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 11, 'Portanto, lembrai-vos que outrora vós, gentios na carne, chamam circuncisão, feita pela mão dos homens,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 12, 'estáveis naquele tempo sem Cristo, separados da comunidade de Israel, e estranhos aos pactos da promessa, não tendo esperança, e sem Deus no mundo.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 13, 'Mas agora, em Cristo Jesus, vós, que antes estáveis longe, já pelo sangue de Cristo chegastes perto.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 14, 'Porque ele é a nossa paz, o qual de ambos os povos fez um; e, derrubando a parede de separação que estava no meio, na sua carne desfez a inimizade,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 15, 'isto é, a lei dos mandamentos contidos em ordenanças, para criar, em si mesmo, dos dois um novo homem, assim fazendo a paz,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 16, 'e pela cruz reconciliar ambos com Deus em um só corpo, tendo por ela matado a inimizade;', 1, CURRENT_TIMESTAMP, false),
(49, 2, 17, 'e, vindo, ele evangelizou paz a vós que estáveis longe, e paz aos que estavam perto;', 1, CURRENT_TIMESTAMP, false),
(49, 2, 18, 'porque por ele ambos temos acesso ao Pai em um mesmo Espírito.', 1, CURRENT_TIMESTAMP, false),
(49, 2, 19, 'Assim, pois, não sois mais estrangeiros, nem forasteiros, antes sois concidadãos dos santos e membros da família de Deus,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 20, 'edificados sobre o fundamento dos apóstolos e dos profetas, sendo o próprio Cristo Jesus a principal pedra da esquina;', 1, CURRENT_TIMESTAMP, false),
(49, 2, 21, 'no qual todo o edifício bem ajustado cresce para templo santo no Senhor,', 1, CURRENT_TIMESTAMP, false),
(49, 2, 22, 'no qual também vós juntamente sois edificados para morada de Deus no Espírito.', 1, CURRENT_TIMESTAMP, false),
(49, 3, 1, 'Por esta razão eu, Paulo, o prisioneiro de Cristo Jesus por amor de vós gentios...', 1, CURRENT_TIMESTAMP, false),
(49, 3, 2, 'Se é que tendes ouvido a dispensação da graça de Deus, que para convosco me foi dada;', 1, CURRENT_TIMESTAMP, false),
(49, 3, 3, 'como pela revelação me foi manifestado o mistério, conforme acima em poucas palavras vos escrevi,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 4, 'pelo que, quando ledes, podeis perceber a minha compreensão do mistério de Cristo,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 5, 'o qual em outras gerações não foi manifestado aos filhos dos homens, como se revelou agora no Espírito aos seus santos apóstolos e profetas,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 6, 'a saber, que os gentios são co-herdeiros e membros do mesmo corpo e co-participantes da promessa em Cristo Jesus por meio do evangelho;', 1, CURRENT_TIMESTAMP, false),
(49, 3, 7, 'do qual fui feito ministro, segundo o dom da graça de Deus, que me foi dada conforme a operação do seu poder.', 1, CURRENT_TIMESTAMP, false),
(49, 3, 8, 'A mim, o mínimo de todos os santos, me foi dada esta graça de anunciar aos gentios as riquezas inescrutáveis de Cristo,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 9, 'e demonstrar a todos qual seja a dispensação do mistério que desde os séculos esteve oculto em Deus, que tudo criou,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 10, 'para que agora seja manifestada, por meio da igreja, aos principados e potestades nas regiões celestes,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 11, 'segundo o eterno propósito que fez em Cristo Jesus nosso Senhor,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 12, 'no qual temos ousadia e acesso em confiança, pela nossa fé nele.', 1, CURRENT_TIMESTAMP, false),
(49, 3, 13, 'Portanto vos peço que não desfaleçais diante das minhas tribulações por vós, as quais são a vossa glória.', 1, CURRENT_TIMESTAMP, false),
(49, 3, 14, 'Por esta razão dobro os meus joelhos perante o Pai,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 15, 'do qual toda família nos céus e na terra toma o nome,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 16, 'para que, segundo as riquezas da sua glória, vos conceda que sejais robustecidos com poder pelo seu Espírito no homem interior;', 1, CURRENT_TIMESTAMP, false),
(49, 3, 17, 'que Cristo habite pela fé nos vossos corações, a fim de que, estando arraigados e fundados em amor,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 18, 'possais compreender, com todos os santos, qual seja a largura, e o comprimento, e a altura, e a profundidade,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 19, 'e conhecer o amor de Cristo, que excede todo o entendimento, para que sejais cheios até a inteira plenitude de Deus.', 1, CURRENT_TIMESTAMP, false),
(49, 3, 20, 'Ora, àquele que é poderoso para fazer tudo muito mais abundantemente além daquilo que pedimos ou pensamos, segundo o poder que em nós opera,', 1, CURRENT_TIMESTAMP, false),
(49, 3, 21, 'a esse seja glória na igreja e em Cristo Jesus, por todas as gerações, para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 1, 'Rogo-vos, pois, eu, o prisioneiro no Senhor, que andeis como é digno da vocação com que fostes chamados,', 1, CURRENT_TIMESTAMP, false),
(49, 4, 2, 'com toda a humildade e mansidão, com longanimidade, suportando-vos uns aos outros em amor,', 1, CURRENT_TIMESTAMP, false),
(49, 4, 3, 'procurando diligentemente guardar a unidade do Espírito no vínculo da paz.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 4, 'Há um só corpo e um só Espírito, como também fostes chamados em uma só esperança da vossa vocação;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 5, 'um só Senhor, uma só fé, um só batismo;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 6, 'um só Deus e Pai de todos, o qual é sobre todos, e por todos e em todos.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 7, 'Mas a cada um de nós foi dada a graça conforme a medida do dom de Cristo.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 8, 'Por isso foi dito: Subindo ao alto, levou cativo o cativeiro, e deu dons aos homens.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 9, 'Ora, isto-ele subiu-que é, senão que também desceu às partes mais baixas da terra?', 1, CURRENT_TIMESTAMP, false),
(49, 4, 10, 'Aquele que desceu é também o mesmo que subiu muito acima de todos os céus, para cumprir todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 11, 'E ele deu uns como apóstolos, e outros como profetas, e outros como evangelistas, e outros como pastores e mestres,', 1, CURRENT_TIMESTAMP, false),
(49, 4, 12, 'tendo em vista o aperfeiçoamento dos santos, para a obra do ministério, para edificação do corpo de Cristo;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 13, 'até que todos cheguemos à unidade da fé e do pleno conhecimento do Filho de Deus, ao estado de homem feito, à medida da estatura da plenitude de Cristo;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 14, 'para que não mais sejamos meninos, inconstantes, levados ao redor por todo vento de doutrina, pela fraudulência dos homens, pela astúcia tendente à maquinação do erro;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 15, 'antes, seguindo a verdade em amor, cresçamos em tudo naquele que é a cabeça, Cristo,', 1, CURRENT_TIMESTAMP, false),
(49, 4, 16, 'do qual o corpo inteiro bem ajustado, e ligado pelo auxílio de todas as juntas, segundo a justa operação de cada parte, efetua o seu crescimento para edificação de si mesmo em amor.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 17, 'Portanto digo isto, e testifico no Senhor, para que não mais andeis como andam os gentios, na verdade da sua mente,', 1, CURRENT_TIMESTAMP, false),
(49, 4, 18, 'entenebrecidos no entendimento, separados da vida de Deus pela ignorância que há neles, pela dureza do seu coração;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 19, 'os quais, tendo-se tornado insensíveis, entregaram-se à lascívia para cometerem com avidez toda sorte de impureza.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 20, 'Mas vós não aprendestes assim a Cristo.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 21, 'se é que o ouvistes, e nele fostes instruídos, conforme é a verdade em Jesus,', 1, CURRENT_TIMESTAMP, false),
(49, 4, 22, 'a despojar-vos, quanto ao procedimento anterior, do velho homem, que se corrompe pelas concupiscências do engano;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 23, 'a vos renovar no espírito da vossa mente;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 24, 'e a vos revestir do novo homem, que segundo Deus foi criado em verdadeira justiça e santidade.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 25, 'Pelo que deixai a mentira, e falai a verdade cada um com o seu próximo, pois somos membros uns dos outros.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 26, 'Irai-vos, e não pequeis; não se ponha o sol sobre a vossa ira;', 1, CURRENT_TIMESTAMP, false),
(49, 4, 27, 'nem deis lugar ao Diabo.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 28, 'Aquele que furtava, não furte mais; antes trabalhe, fazendo com as mãos o que é bom, para que tenha o que repartir com o que tem necessidade.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 29, 'Não saia da vossa boca nenhuma palavra torpe, mas ó a que seja boa para a necessária edificação, a fim de que ministre graça aos que a ouvem.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 30, 'E não entristeçais o Espírito Santo de Deus, no qual fostes selados para o dia da redenção.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 31, 'Toda a amargura, e cólera, e ira, e gritaria, e blasfêmia sejam tiradas dentre vós, bem como toda a malícia.', 1, CURRENT_TIMESTAMP, false),
(49, 4, 32, 'Antes sede bondosos uns para com os outros, compassivos, perdoando-vos uns aos outros, como também Deus vos perdoou em Cristo.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 1, 'Sede pois imitadores de Deus, como filhos amados;', 1, CURRENT_TIMESTAMP, false),
(49, 5, 2, 'e andai em amor, como Cristo também vos amou, e se entregou a si mesmo por nós, como oferta e sacrifício a Deus, em cheiro suave.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 3, 'Mas a prostituição, e toda sorte de impureza ou cobiça, nem sequer se nomeie entre vós, como convém a santos,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 4, 'nem baixeza, nem conversa tola, nem gracejos indecentes, coisas essas que não convêm; mas antes ações de graças.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 5, 'Porque bem sabeis isto: que nenhum devasso, ou impuro, ou avarento, o qual é idólatra, tem herança no reino de Cristo e de Deus.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 6, 'Ninguém vos engane com palavras vãs; porque por estas coisas vem a ira de Deus sobre os filhos da desobediência.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 7, 'Portanto não sejais participantes com eles;', 1, CURRENT_TIMESTAMP, false),
(49, 5, 8, 'pois outrora éreis trevas, mas agora sois luz no Senhor; andai como filhos da luz', 1, CURRENT_TIMESTAMP, false),
(49, 5, 9, '{pois o fruto da luz está em toda a bondade, e justiça e verdade},', 1, CURRENT_TIMESTAMP, false),
(49, 5, 10, 'provando o que é agradável ao Senhor;', 1, CURRENT_TIMESTAMP, false),
(49, 5, 11, 'e não vos associeis às obras infrutuosas das trevas, antes, porém, condenai-as;', 1, CURRENT_TIMESTAMP, false),
(49, 5, 12, 'porque as coisas feitas por eles em oculto, até o dizê-las é vergonhoso.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 13, 'Mas todas estas coisas, sendo condenadas, se manifestam pela luz, pois tudo o que se manifesta é luz.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 14, 'Pelo que diz: Desperta, tu que dormes, e levanta-te dentre os mortos, e Cristo te iluminará.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 15, 'Portanto, vede diligentemente como andais, não como néscios, mas como sábios,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 16, 'usando bem cada oportunidade, porquanto os dias são maus.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 17, 'Por isso, não sejais insensatos, mas entendei qual seja a vontade do Senhor.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 18, 'E não vos embriagueis com vinho, no qual há devassidão, mas enchei-vos do Espírito,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 19, 'falando entre vós em salmos, hinos, e cânticos espirituais, cantando e salmodiando ao Senhor no vosso coração,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 20, 'sempre dando graças por tudo a Deus, o Pai, em nome de nosso Senhor Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 21, 'sujeitando-vos uns aos outros no temor de Cristo.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 22, 'Vós, mulheres, submetei-vos a vossos maridos, como ao Senhor;', 1, CURRENT_TIMESTAMP, false),
(49, 5, 23, 'porque o marido é a cabeça da mulher, como também Cristo é a cabeça da igreja, sendo ele próprio o Salvador do corpo.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 24, 'Mas, assim como a igreja está sujeita a Cristo, assim também as mulheres o sejam em tudo a seus maridos.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 25, 'Vós, maridos, amai a vossas mulheres, como também Cristo amou a igreja, e a si mesmo se entregou por ela,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 26, 'a fim de a santificar, tendo-a purificado com a lavagem da água, pela palavra,', 1, CURRENT_TIMESTAMP, false),
(49, 5, 27, 'para apresentá-la a si mesmo igreja gloriosa, sem mácula, nem ruga, nem qualquer coisa semelhante, mas santa e irrepreensível.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 28, 'Assim devem os maridos amar a suas próprias mulheres, como a seus próprios corpos. Quem ama a sua mulher, ama-se a si mesmo.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 29, 'Pois nunca ninguém aborreceu a sua própria carne, antes a nutre e preza, como também Cristo à igreja;', 1, CURRENT_TIMESTAMP, false),
(49, 5, 30, 'porque somos membros do seu corpo.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 31, 'Por isso deixará o homem a seu pai e a sua mãe, e se unirá à sua mulher, e serão os dois uma só carne.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 32, 'Grande é este mistério, mas eu falo em referência a Cristo e à igreja.', 1, CURRENT_TIMESTAMP, false),
(49, 5, 33, 'Todavia também vós, cada um de per si, assim ame a sua própria mulher como a si mesmo, e a mulher reverencie a seu marido.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 1, 'Vós, filhos, sede obedientes a vossos pais no Senhor, porque isto é justo.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 2, 'Honra a teu pai e a tua mãe {que é o primeiro mandamento com promessa},', 1, CURRENT_TIMESTAMP, false),
(49, 6, 3, 'para que te vá bem, e sejas de longa vida sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 4, 'E vós, pais, não provoqueis à ira vossos filhos, mas criai-os na disciplina e admoestação do Senhor.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 5, 'Vós, servos, obedecei a vossos senhores segundo a carne, com temor e tremor, na sinceridade de vosso coração, como a Cristo,', 1, CURRENT_TIMESTAMP, false),
(49, 6, 6, 'não servindo somente à vista, como para agradar aos homens, mas como servos de Cristo, fazendo de coração a vontade de Deus,', 1, CURRENT_TIMESTAMP, false),
(49, 6, 7, 'servindo de boa vontade como ao Senhor, e não como aos homens.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 8, 'Sabendo que cada um, seja escravo, seja livre, receberá do Senhor todo bem que fizer.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 9, 'E vós, senhores, fazei o mesmo para com eles, deixando as ameaças, sabendo que o Senhor tanto deles como vosso está no céu, e que para com ele não há acepção de pessoas.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 10, 'Finalmente, fortalecei-vos no Senhor e na força do seu poder.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 11, 'Revesti-vos de toda a armadura de Deus, para poderdes permanecer firmes contra as ciladas do Diabo;', 1, CURRENT_TIMESTAMP, false),
(49, 6, 12, 'pois não é contra carne e sangue que temos que lutar, mas sim contra os principados, contra as potestades, conta os príncipes do mundo destas trevas, contra as hostes espirituais da iniqüidade nas regiões celestes.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 13, 'Portanto tomai toda a armadura de Deus, para que possais resistir no dia mau e, havendo feito tudo, permanecer firmes.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 14, 'Estai, pois, firmes, tendo cingidos os vossos lombos com a verdade, e vestida a couraça da justiça,', 1, CURRENT_TIMESTAMP, false),
(49, 6, 15, 'e calçando os pés com a preparação do evangelho da paz,', 1, CURRENT_TIMESTAMP, false),
(49, 6, 16, 'tomando, sobretudo, o escudo da fé, com o qual podereis apagar todos os dardos inflamados do Maligno.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 17, 'Tomai também o capacete da salvação, e a espada do Espírito, que é a palavra de Deus;', 1, CURRENT_TIMESTAMP, false),
(49, 6, 18, 'com toda a oração e súplica orando em todo tempo no Espírito e, para o mesmo fim, vigiando com toda a perseverança e súplica, por todos os santos,', 1, CURRENT_TIMESTAMP, false),
(49, 6, 19, 'e por mim, para que me seja dada a palavra, no abrir da minha boca, para, com intrepidez, fazer conhecido o mistério do evangelho,', 1, CURRENT_TIMESTAMP, false),
(49, 6, 20, 'pelo qual sou embaixador em cadeias, para que nele eu tenha coragem para falar como devo falar.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 21, 'Ora, para que vós também possais saber como estou e o que estou fazendo, Tíquico, irmão amado e fiel ministro no Senhor, vos informará de tudo;', 1, CURRENT_TIMESTAMP, false),
(49, 6, 22, 'o qual vos envio para este mesmo fim, para que saibais do nosso estado, e ele vos conforte o coração.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 23, 'Paz seja com os irmãos, e amor com fé, da parte de Deus Pai e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(49, 6, 24, 'A graça seja com todos os que amam a nosso Senhor Jesus Cristo com amor incorruptível.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 1, 'No primeiro ano de Ciro, rei da Pérsia, para que se cumprisse a palavra do Senhor proferida pela boca de Jeremias, despertou o Senhor o espírito de Ciro, rei da Pérsia, de modo que ele fez proclamar por todo o seu reino, de viva voz e também por escrito, este decreto:', 1, CURRENT_TIMESTAMP, false),
(15, 1, 2, 'Assim diz Ciro, rei da Pérsia: O Senhor Deus do céu me deu todos os reinos da terra, e me encarregou de lhe edificar uma casa em Jerusalém, que é em Judá.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 3, 'Quem há entre vós de todo o seu povo {seja seu Deus com ele} suba para Jerusalém, que é em Judá, e edifique a casa do Senhor, Deus de Israel; ele é o Deus que habita em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 4, 'E todo remanescente, seja qual for o lugar em que é peregrino, seja ajudado pelos homens desse lugar com prata, com ouro, com bens e com animais, afora a oferta voluntária para a casa de Deus, que está em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 5, 'Então se levantaram os chefes das casas paternas de Judá e Benjamim e os sacerdotes, e os levitas, todos aqueles cujo espírito Deus despertara, para subirem a edificar a casa do Senhor, que está em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 6, 'E todos os seus vizinhos os ajudaram com utensílios de prata, com ouro, com bens, com animais e com coisas preciosas, afora tudo o que se ofereceu voluntariamente.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 7, 'Também o rei Ciro tirou os utensílios que pertenciam à casa do Senhor e que Nabucodonosor tinha trazido de Jerusalém e posto na casa de seus deuses.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 8, 'Ciro, rei da Pérsia, tirou-os pela mão de Mitredate, o tesoureiro, que os entregou contados a Sesbazar, príncipe de Judá.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 9, 'Este é o número deles: Trinta bacias de ouro, mil bacias de prata, vinte e nove incensários,', 1, CURRENT_TIMESTAMP, false),
(15, 1, 10, 'trinta taças de ouro, quatrocentas e dez taças de prata e mil outros utensílios.', 1, CURRENT_TIMESTAMP, false),
(15, 1, 11, 'Todos os utensílios de ouro e de prata foram cinco mil e quatrocentos; todos estes levou Sesbazar, quando os do cativeiro foram conduzidos de Babilônia para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 1, 'Estes são os filhos da província que subiram do cativeiro, dentre os exilados, a quem Nabucodonosor, rei de Babilônia, tinha levado para Babilônia, e que voltaram para Jerusalém e para Judá, cada um para a sua cidade;', 1, CURRENT_TIMESTAMP, false),
(15, 2, 2, 'os quais vieram com Zorobabel Jesuá Neemias, Seraías, Reelaías, Mordecai, Bilsã, Mizpar, Bigvai, Reum e Baaná. O número dos homens do povo de Israel.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 3, 'Os filhos de Parós, dois mil cento e setenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 4, 'Os filhos de Sefatias, trezentos e setenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 5, 'Os filhos de Ará, setecentos e setenta e cinco.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 6, 'Os filhos de Paate-Moabe, dos filhos de Jesuá e de Joabe, dois mil oitocentos e doze.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 7, 'Os filhos de Elão, mil duzentos e cinqüenta e quatro.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 8, 'Os filhos de Zatu, novecentos e quarenta e cinco.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 9, 'Os filhos de Zacai, setecentos e sessenta.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 10, 'Os filhos de Bani, seiscentos e quarenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 11, 'Os filhos de Bebai, seiscentos e vinte e três.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 12, 'Os filhos de Azgade, mil duzentos e vinte e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 13, 'Os filhos de Adonicão, seiscentos e sessenta e seis.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 14, 'Os filhos de Bigvai, dois mil e cinqüenta e seis.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 15, 'Os filhos de Adim, quatrocentos e cinqüenta e quatro.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 16, 'Os filhos de Ater, de Ezequias, noventa e oito.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 17, 'Os filhos de Bezai, trezentos e vinte e três.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 18, 'Os filhos de Jora, cento e doze.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 19, 'Os filhos de Hasum, duzentos e vinte e três.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 20, 'Os filhos de Gibar, noventa e cinco.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 21, 'Os filhos de Belém, cento e vinte e três.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 22, 'Os homens de Netofá, cinqüenta e seis.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 23, 'Os homens de Anatote, cento e vinte e oito.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 24, 'Os filhos de Azmavete, quarenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 25, 'Os filhos de Quiriate-Arim, de Cefira e de Beerote, setecentos e quarenta e três', 1, CURRENT_TIMESTAMP, false),
(15, 2, 26, 'Os filhos de Ramá e de Gaba, seiscentos e vinte e um.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 27, 'Os homens de Micmás, cento e vinte e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 28, 'Os homens de Betel e de Ai, duzentos e vinte e três.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 29, 'Os filhos de Nebo, cinqüenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 30, 'Os filhos de Magbis, cento e cinqüenta e seis.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 31, 'Os filhos do outro Elão, mil duzentos e cinqüenta e quatro.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 32, 'Os filhos de Harim, trezentos e vinte.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 33, 'Os filhos de Lode, de Hadide e de Ono, setecentos e vinte e cinco.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 34, 'Os filhos de Jericó, trezentos e quarenta e cinco.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 35, 'Os filhos de Senaá, três mil seiscentos e trinta.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 36, 'Os sacerdotes: os filhos de Jedaías, da casa de Jesuá, novecentos e setenta e três.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 37, 'Os filhos de Imer, mil e cinqüenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 38, 'Os filhos de Pasur, mil duzentos e quarenta e sete.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 39, 'Os filhos de Harim, mil e dezessete.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 40, 'Os levitas os filhos de Jesuá, e de Cadmiel, dos filhos de , Hodavias, setenta e quatro.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 41, 'Os cantores: os filhos de Asafe, cento e vinte e oito.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 42, 'Os filhos dos porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai, ao todo, cento e trinta e nove.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 43, 'Os netinins: os filhos de Ziá, os filhos de Hasufa, os filhos de Tabaote,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 44, 'os filhos de Querós, os filhos de Siá, os filhos de Padom,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 45, 'os filhos de Lebana, os filhos de Hagaba, os filhos de Acube,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 46, 'os filhos de Hagabe, os filhos de Sanlai, os filhos de Hanã,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 47, 'os filhos de Gidel, os filhos de Gaar, os filhos de Reaías,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 48, 'os filhos de Rezin, os filhos de Necoda, os filhos de Gazão,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 49, 'os filhos de Uzá, os filhos de Paséia, os filhos de Besai,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 50, 'os filhos de Asná, os filhos de Meunim, os filhos dos nefusins,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 51, 'os filhos de Baquebuque, os filhos de Hacufa, os filhos de Hurur,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 52, 'os filhos de Bazlute, os filhos de Meída, os filhos de Harsa,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 53, 'os filhos de Barcos, os filhos de Sísera, os filhos de Tamá,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 54, 'os filhos de Nezias, os filhos de Hatifa.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 55, 'Os filhos dos servos de Salomão: os filhos de Sotai, os filhos de Soferete, os filhos de Peruda,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 56, 'os filhos de Jaalá, os filhos de Darcom, os filhos de Gidel,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 57, 'os filhos de Sefatias, os filhos de Hatil, os filhos de Poquerete-Hazebaim os filhos de Ami.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 58, 'Todos os netinins e os filhos dos servos de Salomão foram trezentos e noventa e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 59, 'Estes foram os que subiram de Tel-Mela, de Tel-Harsa, de Querube, de Adã e de Imer; porém não puderam provar que as suas casas paternas e sua linhagem eram de Israel:', 1, CURRENT_TIMESTAMP, false),
(15, 2, 60, 'os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e cinqüenta e dois.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 61, 'E dos filhos dos sacerdotes: os filhos de Habaías, os filhos de Hacoz, os filhos de Barzilai, que tomou mulher das filhas de Barzilai, o gileadita, e que foi chamado do seu nome.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 62, 'Estes procuraram o seu registro entre os que estavam arrolados nas genealogias, mas não foi encontrado; pelo que, por imundos, foram excluídos do sacerdócio;', 1, CURRENT_TIMESTAMP, false),
(15, 2, 63, 'e o governador lhes intimou que não comessem das coisas santíssimas, até que se levantasse um sacerdote com Urim e Tumim.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 64, 'Toda esta congregação junta somava quarenta e dois mil trezentos e sessenta,', 1, CURRENT_TIMESTAMP, false),
(15, 2, 65, 'afora os seus servos, e as suas servas, que foram sete mil trezentos e trinta e sete; também havia duzentos cantores e cantoras.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 66, 'Os seus cavalos eram setecentos e trinta e seis; os seus mulos, duzentos e quarenta e cinco;', 1, CURRENT_TIMESTAMP, false),
(15, 2, 67, 'os seus camelos, quatrocentos e trinta e cinco; os jumentos, seis mil setecentos e vinte.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 68, 'Alguns dos chefes das casas paternas, vindo à casa do Senhor em Jerusalém, deram ofertas voluntárias para a casa de Deus, para a edificarem no seu lugar;', 1, CURRENT_TIMESTAMP, false),
(15, 2, 69, 'conforme as suas posses, deram para a tesouraria da obra, em ouro sessenta e um mil dáricos, e em prata cinco mil minas, e cem vestes sacerdotais.', 1, CURRENT_TIMESTAMP, false),
(15, 2, 70, 'Ora, os sacerdotes e os levitas, e alguns do povo, tanto os cantores como os porteiros e os netinins, habitaram nas suas cidades, e todo o Israel nas suas cidades.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 1, 'Quando chegou o sétimo mês, estando já os filhos de Israel nas suas cidades, ajuntou-se o povo, como um só homem, em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 2, 'Então se levantou Jesuá, filho de Jozadaque, com seus irmãos, os sacerdotes, e Zorobabel, filho de Sealtiel, e seus irmãos; e edificaram o altar do Deus de Israel, para oferecerem sobre ele holocaustos, como está escrito na lei de Moisés, homem de Deus.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 3, 'Colocaram o altar sobre a sua base {pois o terror estava sobre eles por causa dos povos das terras e ofereceram sobre ele holocaustos ao Senhor, holocaustos pela manhã e à tarde.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 4, 'E celebraram a festa dos tabernáculos como está escrito, e ofereceram holocaustos diários segundo o número ordenado para cada dia,', 1, CURRENT_TIMESTAMP, false),
(15, 3, 5, 'e em seguida o holocausto contínuo, e os das luas novas e de todas as festas fixas do Senhor, como também os de qualquer que fazia oferta voluntária ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 6, 'Desde o primeiro dia do sétimo mês começaram a oferecer holocaustos ao Senhor; porém ainda não haviam sido lançados os alicerces do templo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 7, 'Deram dinheiro aos pedreiros e aos carpinteiros; como também comida e bebida, e azeite aos sidônios, e aos tírios, para trazerem do Líbano madeira de cedro ao mar, para Jope, segundo a concessão que lhes tinha feito Ciro, rei da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 8, 'Ora, no segundo ano da sua vinda à casa de Deus em Jerusalém, no segundo mês, Zorobabel, filho de Sealtiel, e Jesuá, filho de Jozadaque, e os outros seus irmãos, os sacerdotes e os levitas, e todos os que vieram do cativeiro para Jerusalém, deram início à obra e constituíram os levitas da idade de vinte anos para cima, para superintenderem a obra da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 9, 'Então se levantaram Jesuá com seus filhos e seus irmãos, Cadmiel e seus filhos, os filhos de Judá, como um só homem, para superintenderem os que faziam a obra na casa de Deus; como também os filhos de Henadade, com seus filhos e seus irmãos, os levitas.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 10, 'Quando os edificadores lançaram os alicerces do templo do Senhor, os sacerdotes trajando suas vestes, apresentaram-se com trombetas, e os levitas, filhos de Asafe, com címbalos, para louvarem ao Senhor, segundo a ordem de Davi, rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 11, 'E cantavam a revezes, louvando ao Senhor e dando-lhe graças com estas palavras: Porque ele é bom; porque a sua benignidade dura para sempre sobre Israel. E todo o povo levantou grande brado, quando louvaram ao Senhor, por se terem lançado os alicerces da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(15, 3, 12, 'Muitos, porém, dos sacerdotes e dos levitas, e dos chefes das casas paternas, os idosos que tinham visto a primeira casa, choraram em altas vozes quando, a sua vista, foi lançado o fundamento desta casa; também muitos gritaram de júbilo;', 1, CURRENT_TIMESTAMP, false),
(15, 3, 13, 'de maneira que não podia o povo distinguir as vozes do júbilo das vozes do choro do povo; porque o povo bradava em tão altas vozes que o som se ouvia de mui longe.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 1, 'Ora, ouvindo os adversários de Judá e de Benjamim que os que tornaram do cativeiro edificavam o templo ao Senhor, Deus de Israel,', 1, CURRENT_TIMESTAMP, false),
(15, 4, 2, 'chegaram-se a Zorobabel e aos chefes das casas paternas, e disseram-lhes: Deixai-nos edificar convosco; pois, como vós, buscamos o vosso Deus; como também nós lhe temos sacrificado desde os dias de Esar-Hadom, rei da Assíria, que nos fez subir para aqui.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 3, 'Responderam-lhes, porém, Zorobabel e Jesuá e os outros chefes das casas paternas de Israel: Não convém que vós e nós edifiquemos casa a nosso Deus: mas nós sozinhos a edificaremos ao Senhor, Deus de Israel, como nos ordenou o rei Ciro, rei da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 4, 'Então o povo da terra debilitava as mãos do povo de Judá, e os inquietava, impedindo-os de edificar;', 1, CURRENT_TIMESTAMP, false),
(15, 4, 5, 'e assalariaram contra eles conselheiros para frustrarem o seu plano, por todos os dias de Ciro, rei da Pérsia, até o reinado de Dario, rei da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 6, 'No reinado de Assuero, no princípio do seu reino, escreveram uma acusação contra os habitantes de Judá e de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 7, 'Também nos dias de Artaxerxes escreveram Bislão, Mitredate, Tabeel, e os companheiros destes, a Artaxerxes, rei da Pérsia; e a carta foi escrita em caracteres aramaicos, e traduzida na língua aramaica.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 8, 'Reum, o comandante, e Sinsai, o escrivão, escreveram uma carta contra Jerusalém, ao rei Artaxerxes, do teor seguinte,', 1, CURRENT_TIMESTAMP, false),
(15, 4, 9, 'isto é, escreveram Reum, o comandante, Sinsai, o escrivão, e os seus companheiros, os juízes, os governadores, os oficiais, os persas, os homens de Ereque, os babilônios, os susanquitas, isto é, os elamitas,', 1, CURRENT_TIMESTAMP, false),
(15, 4, 10, 'e as demais nações que o grande e afamado Osnapar transportou, e que fez habitar na cidade de Samária e no restante da província dalém do Rio.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 11, 'Eis, pois, a cópia da carta que mandaram ao rei Artaxerxes: Teus servos, os homens de além do Rio, assim escrevem:', 1, CURRENT_TIMESTAMP, false),
(15, 4, 12, 'Saiba o rei que os judeus que subiram de ti a nós foram a Jerusalém e estão reedificando aquela rebelde e malvada cidade, e vão restaurando os seus muros e reparando os seus fundamentos.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 13, 'Agora saiba o rei que, se aquela cidade for reedificada e os muros forem restaurados, eles não pagarão nem tributo, nem imposto, nem pedágio; e assim se danificará a fazenda dos reis.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 14, 'Agora, visto que comemos do sal do palácio, e não nos convém ver a desonra do rei, por isso mandamos dar aviso ao rei,', 1, CURRENT_TIMESTAMP, false),
(15, 4, 15, 'para que se busque no livro das crônicas de teus pais; e acharás no livro das crônicas e saberás que aquela é uma cidade rebelde, e danosa a reis e províncias, e que nela houve rebelião em tempos antigos; por isso é que ela foi destruída.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 16, 'Nós, pois, estamos avisando ao rei que, se aquela cidade for reedificada e os seus muros forem restaurados, não terás porção alguma a oeste do Rio.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 17, 'Então o rei enviou esta resposta a Reum, o comandante, e a Sinsai, o escrivão, e aos demais seus companheiros, que habitavam em Samária e no restante do país a oeste do Rio: Paz.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 18, 'A carta que nos enviastes foi claramente lida na minha presença.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 19, 'E, ordenando-o eu, buscaram e acharam que desde tempos antigos aquela cidade se tem levantado contra os reis, e que nela se tem feito rebelião e sedição.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 20, 'E tem havido reis poderosos sobre Jerusalém, os quais dominavam igualmente toda a província dalém do Rio; e a eles se pagavam tributos, impostos e pedágio.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 21, 'Agora, pois, dai ordem para que aqueles homens parem, a fim de que não seja edificada aquela cidade até que eu dê ordem.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 22, 'E guardai-vos de serdes remissos nisto; não suceda que o dano cresça em prejuízo dos reis.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 23, 'Então, logo que a cópia da carta do rei Artaxerxes foi lida perante Reum e Sinsai, o escrivão, e seus companheiros, foram eles apressadamente a Jerusalém, aos judeus, e os impediram à força e com violência.', 1, CURRENT_TIMESTAMP, false),
(15, 4, 24, 'Então cessou a obra da casa de Deus, que estava em Jerusalém, ficando interrompida até o segundo ano do reinado de Dario, rei da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 1, 'Ora, os profetas Ageu e Zacarias, filho de Ido, profetizaram aos judeus que estavam em Judá e em Jerusalém; em nome do Deus de Israel lhes profetizaram.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 2, 'Então se levantaram Zorobabel, filho de Sealtiel, e Jesuá, filho de Jozadaque, e começaram a edificar a casa de Deus, que está em Jerusalém; e com eles estavam os profetas de Deus, que os ajudavam.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 3, 'Naquele tempo vieram ter com eles Tatenai, o governador da província a oeste do Rio, e Setar-Bozenai, e os seus companheiros, e assim lhes perguntaram: Quem vos deu ordem para edificar esta casa, e completar este muro?', 1, CURRENT_TIMESTAMP, false),
(15, 5, 4, 'Ainda lhes perguntaram: Quais são os nomes dos homens que constróem este edifício?', 1, CURRENT_TIMESTAMP, false),
(15, 5, 5, 'Os olhos do seu Deus, porém, estavam sobre os anciãos dos judeus, de modo que eles não os impediram, até que o negócio se comunicasse a Dario, e então chegasse resposta por carta sobre isso.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 6, 'A cópia da carta que Tatenai, o governador da província a oeste do Rio, e Setar-Bozenai, e os seus companheiros, os governadores, que estavam deste lado do Rio, enviaram ao rei Dario;', 1, CURRENT_TIMESTAMP, false),
(15, 5, 7, 'enviaram-lhe um relatório, no qual estava escrito: Ao rei Dario toda a paz.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 8, 'Saiba o rei que nós fomos à província de Judá, à casa do grande Deus, a qual se edifica com grandes pedras, e já a madeira está sendo posta nas paredes, e esta obra vai-se fazendo com diligência, e se adianta em suas mãos.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 9, 'Então perguntamos àqueles anciãos, falando-lhes assim: Quem vos deu ordem para edificar esta casa, e completar este muro?', 1, CURRENT_TIMESTAMP, false),
(15, 5, 10, 'Além disso lhes perguntamos pelos seus nomes, para tos declararmos, isto é, para te escrevermos os nomes dos homens que entre eles são os chefes.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 11, 'E esta é a resposta que nos deram: Nós somos servos do Deus do céu e da terra, e reedificamos a casa que há muitos anos foi edificada, a qual um grande rei de Israel edificou e acabou.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 12, 'Mas depois que nossos pais provocaram à ira o Deus do céu, ele os entregou na mão de Nabucodonosor, o caldeu, rei de Babilônia, o qual destruiu esta casa, e transportou o povo para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 13, 'Porém, no primeiro ano de Ciro, rei de Babilônia, o rei Ciro baixou decreto para que esta casa de Deus fosse reedificada.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 14, 'E até os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tinha tomado do templo que estava em Jerusalém e levado para o templo de Babilônia, o rei Siro os tirou do templo de Babilônia, e eles foram entregues a um homem cujo nome era Sesbazar, a quem ele tinha constituído governador;', 1, CURRENT_TIMESTAMP, false),
(15, 5, 15, 'e disse-lhe: Toma estes utensílios, vai, e leva-os para o templo que está em Jerusalém, e reedifique-se a casa de Deus no seu lugar.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 16, 'Então veio o dito Sesbazar, e lançou os fundamentos da casa de Deus, que está em Jerusalém; de então para cá ela vem sendo edificada, não estando ainda concluída.', 1, CURRENT_TIMESTAMP, false),
(15, 5, 17, 'Agora, pois, se parece bem ao rei, busque-se nos arquivos reais, ali em Babilônia, para ver se é verdade haver um decreto do rei Ciro para se reedificar esta casa de Deus em Jerusalém, e sobre isto nos faça o rei saber a sua vontade.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 1, 'Então o rei Dario o decretou, e foi feita uma busca nos arquivos onde se guardavam os tesouros em Babilônia.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 2, 'E em Ecbatana, a capital, que está na província da Média, se achou um rolo, e nele estava escrito um memorial, que dizia assim:', 1, CURRENT_TIMESTAMP, false),
(15, 6, 3, 'No primeiro ano do rei Ciro, o rei Ciro baixou um decreto com respeito à casa de Deus em Jerusalém: Seja edificada a casa, o lugar em que se oferecem sacrifícios, e sejam os seus fundamentos bem firmes; a sua altura será de sessenta côvados, e a sua largura de sessenta côvados,', 1, CURRENT_TIMESTAMP, false),
(15, 6, 4, 'com três carreiras de grandes pedras, e uma carreira de madeira nova; e a despesa se fará do tesouro do rei.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 5, 'Além disso sejam restituídos os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tirou do templo em Jerusalém e levou para Babilônia, e que se tornem a levar para o templo em Jerusalém, cada um para o seu lugar, e tu os porás na casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 6, 'Agora, pois, Tatenai, governador de além do Rio, Setar-Bozenai, e os vossos companheiros, os governadores, que estais além do Rio, retirai-vos desse lugar;', 1, CURRENT_TIMESTAMP, false),
(15, 6, 7, 'deixai de impedir a obra desta casa de Deus; edifiquem o governador dos judeus e os seus anciãos esta casa de Deus no seu lugar.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 8, 'Além disso, por mim se decreta o que haveis de fazer para com esses anciãos dos judeus, para a edificação desta casa de Deus, a saber, que da fazenda do rei, dos tributos da província dalém do Rio, se pague prontamente a estes homens toda a despesa.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 9, 'Igualmente o que for necessário, como novilhos, carneiros e cordeiros, para holocaustos ao Deus do céu; também trigo, sal, vinho e azeite, segundo a palavra dos sacerdotes que estão em Jerusalém, dê-se-lhes isso de dia em dia sem falta;', 1, CURRENT_TIMESTAMP, false),
(15, 6, 10, 'para que ofereçam sacrifícios de cheiro suave ao Deus do céu, e orem pela vida do rei e de seus filhos.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 11, 'Também por mim se decreta que a todo homem que alterar este decreto, se arranque uma viga da sua casa e que ele seja pregado nela; e da sua casa se faça por isso um monturo.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 12, 'O Deus, pois, que fez habitar ali o seu nome derribe todos os reis e povos que estenderem a mão para alterar o decreto e para destruir esta casa de Deus, que está em Jerusalém. Eu, Dario, baixei o decreto. Que com diligência se execute.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 13, 'Então Tatenai, o governador a oeste do Rio, Setar-Bozenai, e os seus companheiros executaram com toda a diligência o que mandara o rei Dario.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 14, 'Assim os anciãos dos judeus iam edificando e prosperando pela profecia de Ageu o profeta e de Zacarias, filho de Ido. Edificaram e acabaram a casa de acordo com o mandado do Deus de Israel, e de acordo com o decreto de Ciro, e de Dario, e de Artaxerxes, rei da Pérsia.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 15, 'E acabou-se esta casa no terceiro dia do mês de Adar, no sexto ano do reinado do rei Dario.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 16, 'E os filhos de Israel, os sacerdotes e os levitas, e o resto dos filhos do cativeiro fizeram a dedicação desta casa de Deus com alegria.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 17, 'Ofereceram para a dedicação desta casa de Deus cem novilhos, duzentos carneiros e quatrocentos cordeiros; e como oferta pelo pecado por todo o Israel, doze bodes, segundo o número das tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 18, 'E puseram os sacerdotes nas suas divisões e os levitas nas suas turmas, para o serviço de Deus em Jerusalém, conforme o que está escrito no livro de Moisés.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 19, 'E os que vieram do cativeiro celebraram a páscoa no dia catorze do primeiro mês.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 20, 'Pois os sacerdotes e levitas se tinham purificado como se fossem um só homem; todos estavam limpos. E imolaram o cordeiro da páscoa para todos os filhos do cativeiro, e para seus irmãos, os sacerdotes, e para si mesmos.', 1, CURRENT_TIMESTAMP, false),
(15, 6, 21, 'Assim comeram a páscoa os filhos de Israel que tinham voltado do cativeiro, com todos os que, unindo-se a eles, se apartaram da imundícia das nações da terra para buscarem o Senhor, Deus de Israel;', 1, CURRENT_TIMESTAMP, false),
(15, 6, 22, 'e celebraram a festa dos pães ázimos por sete dias com alegria; porque o Senhor os tinha alegrado, tendo mudado o coração do rei da Assíria a favor deles, para lhes fortalecer as mãos na obra da casa de Deus, o Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 1, 'Ora, depois destas coisas, no reinado de Artaxerxes, rei da Pérsia, Esdras, filho de Seraías, filho de Azarias, filho de Hilquias,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 2, 'filho de Salum, filho de Zadoque, filho de Aitube,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 3, 'filho de Amarias, filho de Azarias, filho de Meraiote,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 4, 'filho de Zeraías, filho de Uzi, filho de Buqui,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 5, 'filho de Abisua, filho de Finéias, filho de Eleazar, filho de Arão, o sumo sacerdote,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 6, 'este Esdras subiu de Babilônia. E ele era escriba hábil na lei de Moisés, que o Senhor Deus de Israel tinha dado; e segundo a mão de Senhor seu Deus, que estava sobre ele, o rei lhe deu tudo quanto lhe pedira.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 7, 'Também subiram a Jerusalém alguns dos filhos de Israel, dos sacerdotes, dos levitas, dos cantores, dos porteiros e dos netinins, no sétimo ano do rei Artaxerxes.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 8, 'No quinto mês Esdras chegou a Jerusalém, no sétimo ano deste rei.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 9, 'Pois no primeiro dia do primeiro mês ele partiu de Babilônia e no primeiro dia do quinto mês chegou a Jerusalém, graças à mão benéfica do seu Deus sobre ele.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 10, 'Porque Esdras tinha preparado o seu coração para buscar e cumprir a lei do Senhor, e para ensinar em Israel os seus estatutos e as suas ordenanças.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 11, 'Esta é, pois, a cópia da carta que o rei Artaxerxes deu a Esdras, o sacerdote, o escriba instruído nas palavras dos mandamentos do Senhor e dos seus estatutos para Israel:', 1, CURRENT_TIMESTAMP, false),
(15, 7, 12, 'Artaxerxes, rei dos reis, ao sacerdote Esdras, escriba da lei do Deus do céu: Saudações.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 13, 'Por mim se decreta que no meu reino todo aquele do povo de Israel, e dos seus sacerdotes e levitas, que quiser ir a Jerusalém, vá contigo.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 14, 'Porquanto és enviado da parte do rei e dos seus sete conselheiros para indagares a respeito de Judá e de Jerusalém, conforme a lei do teu Deus, a qual está na tua mão;', 1, CURRENT_TIMESTAMP, false),
(15, 7, 15, 'e para levares a prata e o ouro que o rei e os seus conselheiros voluntariamente deram ao Deus de Israel cuja habitação está em Jerusalém,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 16, 'com toda a prata e o ouro que achares em toda a província de Babilônia, e com as ofertas voluntárias do povo e dos sacerdotes, que voluntariamente as oferecerem para a casa do seu Deus, que está em Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(15, 7, 17, 'portanto com toda a diligência comprarás com este dinheiro novilhos, carneiros, e cordeiros, com as suas ofertas de cereais e as suas ofertas de libações, e os oferecerás sobre o altar da casa do vosso Deus, que está em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 18, 'Também o que a ti e a teus irmãos parecer bem fazerdes do resto da prata e do ouro, o fareis conforme a vontade do vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 19, 'Os vasos que te foram dados para o serviço da casa do teu Deus, entrega-os todos perante ele, o Deus de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 20, 'E tudo o mais que for necessário para a casa do teu Deus, e que te convenha dar, o darás da casa dos tesouros do rei.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 21, 'E eu, o rei Artaxerxes, decreto a todos os tesoureiros que estão na província dalém do Rio, que tudo quanto vos exigir o sacerdote Esdras, escriba da lei do Deus do céu, prontamente se lhe conceda,', 1, CURRENT_TIMESTAMP, false),
(15, 7, 22, 'até cem talentos de prata cem coros de trigo, cem batos de vinho, cem batos de azeite, e sal à vontade.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 23, 'Tudo quanto for ordenado pelo Deus do céu, isso precisamente se faça para a casa do Deus do céu; pois, por que haveria ira sobre o reino do rei e de seus filhos?', 1, CURRENT_TIMESTAMP, false),
(15, 7, 24, 'Também vos notificamos acerca de todos os sacerdotes e levitas, cantores, porteiros, netinins, e outros servos desta casa de Deus, que não será lícito exigir-lhes nem tributo, nem imposto, nem pedágio.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 25, 'E tu, Esdras, conforme a sabedoria do teu Deus, que possuis, constitui magistrados e juízes, que julguem todo o povo que está na província dalém do Rio, isto é, todos os que conhecem as leis do teu Deus; e ensina-as ao que não as conhece.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 26, 'E todo aquele que não observar a lei do teu Deus e a lei do rei, com zelo se lhe execute a justiça: quer seja morte, quer desterro, quer confiscação de bens, quer prisão.', 1, CURRENT_TIMESTAMP, false),
(15, 7, 27, 'Bendito seja o Senhor Deus de nossos pais, que pôs no coração do rei este desejo de ornar a casa do Senhor, que está em Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(15, 7, 28, 'e que estendeu sobre mim a sua benevolência perante o rei e os seus conselheiros e perante todos os príncipes poderosos do rei. Assim encorajado pela mão do Senhor, meu Deus, que estava sobre mim, ajuntei dentre Israel alguns dos homens principais para subirem comigo.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 1, 'Estes, pois, são os chefes de suas casas paternas, e esta é a genealogia dos que subiram comigo de Babilônia no reinado do rei Artaxerxes:', 1, CURRENT_TIMESTAMP, false),
(15, 8, 2, 'Dos filhos de Finéias, Gérson; dos filhos de Itamar, Daniel; dos filhos de Davi, Hatus;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 3, 'dos filhos de Secanias, dos filhos de Parós, Zacarias; e com ele, segundo as genealogias dos varões, se contaram cento e cinqüenta;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 4, 'dos filhos de Paate-Moabe, Elioenai, filho de Zeraías, e com ele duzentos homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 5, 'dos filhos de Zatu, Secanias, o filho de Jaaziel, e com ele trezentos homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 6, 'dos filhos de Adim, Ebede, filho de Jônatas, e com ele cinqüenta homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 7, 'dos filhos de Elão, Jesaías, filho de Atalias, e com ele setenta homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 8, 'dos filhos de Sefatias, Zebadias, filho de Micael, e com ele oitenta homens; e', 1, CURRENT_TIMESTAMP, false),
(15, 8, 9, 'dos filhos de Joabe, Obadias, filho de Jeiel, e com ele duzentos e dezoito homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 10, 'dos filhos de Bani, Selomite, o filho de Josifias, e com ele cento e sessenta homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 11, 'dos filhos de Bebai, Zacarias, o filho de Bebai, e com ele vinte e oito homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 12, 'dos filhos de Azgade, Joanã, o filho de Hacatã, e com ele cento e dez homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 13, 'dos filhos de Adonicão, que eram os últimos, eis os seus nomes: Elifelete, Jeuel e Semaías, e com eles sessenta homens;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 14, 'e dos filhos de Bigvai, Utai e Zabude, e com eles setenta homens.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 15, 'Ajuntei-os à margem do rio que corre para Ava; e ficamos ali acampados três dias. Então passei em revista o povo e os sacerdotes, e não achei ali nenhum dos filhos de Levi.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 16, 'Mandei, pois, chamar Eliézer, Ariel, Semaías, Elnatã, Jaribe, Elnatã, Natã, Zacarias e Mesulão, os chefes, como também, Joiaribe e Elnatã, que eram mestres.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 17, 'E os enviei a Ido, chefe em Casífia, e lhes pus na boca palavras para dizerem a Ido e aos seus irmãos, os netinins, em Casífia, que nos trouxessem ministros para a casa do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 18, 'E, pela boa mão de nosso Deus sobre nós, trouxeram-nos um homem entendido, dos filhos de Mali, filho de Levi, filho de Israel; e Serebias, com os seus filhos e irmãos, dezoito;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 19, 'e Hasabias, e com ele Jesaías, dos filhos de Merári, com seus irmãos e os filhos deles, vinte;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 20, 'e dos netinins, que Davi e os príncipes tinham dado para o serviço dos levitas, duzentos e vinte, todos eles mencionados por nome.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 21, 'Então proclamei um jejum ali junto ao rio Ava, para nos humilharmos diante do nosso Deus, a fim de lhe pedirmos caminho seguro para nós, para nossos pequeninos, e para toda a nossa fazenda.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 22, 'Pois tive vergonha de pedir ao rei uma escolta de soldados, e cavaleiros para nos defenderem do inimigo pelo caminho, porquanto havíamos dito ao rei: A mão do nosso Deus é sobre todos os que o buscam, para o bem deles; mas o seu poder e a sua ira estão contra todos os que o deixam.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 23, 'Nós, pois, jejuamos, e pedimos isto ao nosso Deus; e ele atendeu às nossas orações.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 24, 'Então separei doze dos principais dentre os sacerdotes: Serebias e Hasabias, e com eles dez dos seus irmãos;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 25, 'e pesei-lhes a prata, o ouro e os vasos, a oferta para a casa do nosso Deus, que o rei, os seus conselheiros, os seus príncipes e todo o Israel que estava ali haviam oferecido;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 26, 'entreguei-lhes nas mãos seiscentos e cinqüenta talentos de prata, e em vasos de prata cem talentos; e cem talentos de ouro;', 1, CURRENT_TIMESTAMP, false),
(15, 8, 27, 'e vinte taças de ouro no valor de mil dáricos, e dois vasos de bronze claro e brilhante, tão precioso como o ouro.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 28, 'E disse-lhes: Vós sois santos ao Senhor, e santos são estes vasos; como também esta prata e este ouro são ofertas voluntárias, oferecidas ao Senhor, Deus de vossos pais.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 29, 'Vigiai, pois, e guardai-os até que os peseis na presença dos principais dos sacerdotes e dos levitas, e dos príncipes das casas paternas de Israel, em Jerusalém, nas câmaras da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 30, 'Então os sacerdotes e os levitas receberam o peso da prata, e do ouro, e dos vasos, a fim de os trazerem para Jerusalém, para a casa do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 31, 'Então partimos do rio Ava, no dia doze do primeiro mês, a fim de irmos para Jerusalém; e a mão do nosso Deus estava sobre nós, e ele nos livrou da mão dos inimigos, e dos que nos armavam ciladas pelo caminho.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 32, 'Chegamos, pois, a Jerusalém, e repousamos ali três dias.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 33, 'No quarto dia se pesou a prata, e o ouro, e os vasos, na casa do nosso Deus, para as mãos de Meremote filho do sacerdote Urias; e com ele estava Eleazar, filho de Finéias, e com eles os levitas Jozabade, filho de Jesuá, e Noadias, filho de Binuí.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 34, 'Tudo foi entregue por número e peso; e o peso de tudo foi registrado na ocasião.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 35, 'Os exilados que tinham voltado do cativeiro ofereceram holocaustos ao Deus de Israel: doze novilhos por todo o Israel, noventa e seis carneiros, setenta e sete cordeiros, e doze bodes em oferta pelo pecado; tudo em holocausto ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(15, 8, 36, 'Então entregaram os editos do rei aos sátrapas do rei, e aos governadores a oeste do Rio; e estes ajudaram o povo e a casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 1, 'Ora, logo que essas coisas foram terminadas, vieram ter comigo os príncipes, dizendo: O povo de Israel, e os sacerdotes, e os levitas, não se têm separado dos povos destas terras, das abominações dos cananeus, dos heteus, dos perizeus, dos jebuseus, dos amonitas, dos moabitas, dos egípcios e dos amorreus;', 1, CURRENT_TIMESTAMP, false),
(15, 9, 2, 'pois tomaram das suas filhas para si e para seus filhos; de maneira que a raça santa se tem misturado com os povos de outras terras; e até os oficiais e magistrados foram os primeiros nesta transgressão.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 3, 'Ouvindo eu isto, rasguei a minha túnica e o meu manto, e arranquei os cabelos da minha cabeça e da minha barba, e me sentei atônito.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 4, 'Então se ajuntaram a mim todos os que tremiam das palavras do Deus de Israel por causa da transgressão dos do cativeiro; porém eu permaneci sentado atônito até a oblação da tarde.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 5, 'A hora da oblação da tarde levantei-me da minha humilhação, e com a túnica e o manto rasgados, pus-me de joelhos, estendi as mãos ao Senhor meu Deus,', 1, CURRENT_TIMESTAMP, false),
(15, 9, 6, 'e disse: Ó meu Deus! Estou confuso e envergonhado, para levantar o meu rosto a ti, meu Deus; porque as nossas iniqüidades se multiplicaram sobre a nossa cabeça, e a nossa culpa tem crescido até o céu.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 7, 'Desde os dias de nossos pais até o dia de hoje temos estado em grande culpa, e por causa das nossas iniqüidades fomos entregues, nós, os nossos reis e os nossos sacerdotes, na mão dos reis das terras, à espada, ao cativeiro, à rapina e à confusão do rosto, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 8, 'Agora, por um pequeno momento se manifestou a graça da parte do Senhor, nosso Deus, para nos deixar um restante que escape, e para nos dar estabilidade no seu santo lugar, a fim de que o nosso Deus nos alumie os olhos, e nos dê um pouco de refrigério em nossa escravidão;', 1, CURRENT_TIMESTAMP, false),
(15, 9, 9, 'pois somos escravos; contudo o nosso Deus não nos abandonou em nossa escravidão, mas estendeu sobre nós a sua benevolência perante os reis da Pérsia, para nos dar a vida, a fim de levantarmos a casa do nosso Deus e repararmos as suas assolações, e para nos dar um abrigo em Judá e em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 10, 'Agora, ó nosso Deus, que diremos depois disto? Pois temos deixado os teus mandamentos,', 1, CURRENT_TIMESTAMP, false),
(15, 9, 11, 'os quais ordenaste por intermédio de teus servos, os profetas, dizendo: A terra em que estais entrando para a possuir, é uma terra imunda pelas imundícias dos povos das terras, pelas abominações com que, na sua corrupção, a encheram duma extremidade à outra.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 12, 'Por isso não deis vossas filhas a seus filhos, e não tomeis suas filhas para vossos filhos, nem procureis jamais a sua paz ou a sua prosperidade; para que sejais fortes e comais o bem da terra, e a deixeis por herança a vossos filhos para sempre.', 1, CURRENT_TIMESTAMP, false),
(15, 9, 13, 'E depois de tudo o que nos tem sucedido por causa das nossas más obras, e da nossa grande culpa, ainda assim tu, ó nosso Deus, nos tens castigado menos do que merecem as nossas iniqüidades, e ainda nos deixaste este remanescente;', 1, CURRENT_TIMESTAMP, false),
(15, 9, 14, 'tornaremos, pois, agora a violar os teus mandamentos, e a aparentar-nos com os povos que cometem estas abominações? Não estarias tu indignado contra nós até de todo nos consumires, de modo que não ficasse restante, nem quem escapasse?', 1, CURRENT_TIMESTAMP, false),
(15, 9, 15, 'Ó Senhor Deus de Israel, justo és, pois ficamos qual um restante que escapou, como hoje se vê. Eis que estamos diante de ti em nossa culpa; e, por causa disto, ninguém há que possa subsistir na tua presença.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 1, 'Ora, enquanto Esdras orava e fazia confissão, chorando e prostrando-se diante da casa de Deus, ajuntou-se a ele, de Israel, uma grande congregação de homens, mulheres, e crianças; pois o povo chorava amargamente.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 2, 'Então Seeanias, filho de Jeiel, um dos filhos de Elão, dirigiu-se a Esdras, dizendo: Nós temos sido infiéis para com o nosso Deus, e casamos com mulheres estrangeiras dentre os povos da terra; contudo, no tocante a isto, ainda há esperança para Israel.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 3, 'Agora, pois, façamos um pacto com o nosso Deus, de que despediremos todas as mulheres e os que delas são nascidos, conforme o conselho do meu Senhor, e dos que tremem ao mandamento do nosso Deus; e faça-se conforme a lei.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 4, 'Levanta-te; pois a ti pertence este negócio, e nós somos contigo; tem bom ânimo, e faze-o.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 5, 'Então Esdras se levantou, e ajuramentou os principais dos sacerdotes, os levitas, e todo o Israel, de que fariam conforme esta palavra; e eles juraram.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 6, 'Em seguida Esdras se levantou de diante da casa de Deus, e entrou na câmara de Joanã, filho de Eliasibe; e, chegando lá, não comeu pão, nem bebeu água, porque pranteava por causa da infidelidade dos do cativeiro.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 7, 'E fizeram passar pregão por Judá e Jerusalém, a todos os que vieram do cativeiro, para que se ajuntassem em Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(15, 10, 8, 'e que todo aquele que dentro de três dias não viesse, segundo o conselho dos oficiais e dos anciãos, toda a sua fazenda se pusesse em interdito, e fosse ele excluído da congregação dos que voltaram do cativeiro.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 9, 'Pelo que todos os homens de Judá e de Benjamim dentro de três dias se ajuntaram em Jerusalém. Era o nono mês, aos vinte dias do mês; e todo o povo se assentou na praça diante da casa de Deus, tremendo por causa deste negócio e por causa das grandes chuvas.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 10, 'Então se levantou Esdras, o sacerdote, e disse-lhes: Vós tendes transgredido, e casastes com mulheres estrangeiras, aumentando a culpa de Israel.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 11, 'Agora, pois, fazei confissão ao Senhor, Deus de vossos pais, e fazei o que é do seu agrado; separai-vos dos povos das terras, e das mulheres estrangeiras.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 12, 'E toda a congregação respondeu em alta voz: Conforme as tuas palavras havemos de fazer.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 13, 'Porém o povo é muito; também é tempo de grandes chuvas, e não se pode estar aqui fora. Isso não é obra de um dia nem de dois, pois somos muitos os que transgredimos neste negócio.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 14, 'Ponham-se os nossos oficiais por toda a congregação, e todos os que em nossas cidades casaram com mulheres estrangeiras venham em tempos apontados, e com eles os anciãos e juízes de cada cidade, até que se desvie de nós o ardor da ira do nosso Deus no tocante a este negócio.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 15, '{Somente Jônatas, filho de Asael, e, filho de Ticvá, se opuseram a isso; e Mesulão, e Sabetai, o levita, os apoiaram.}', 1, CURRENT_TIMESTAMP, false),
(15, 10, 16, 'Assim o fizeram os que tornaram do cativeiro: foram indicados o sacerdote Esdras e certos homens, cabeças de casas paternas, segundo as suas casas paternas, cada um designado por nome; e assentaram-se no primeiro dia do décimo mês, para averiguar este negócio.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 17, 'E no primeiro dia do primeiro mês acabaram de tratar de todos os homens que tinham casado com mulheres estrangeiras.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 18, 'Entre os filhos dos sacerdotes acharam-se estes que tinham casado com mulheres estrangeiras: dos filhos de Jesuá, filho de Jozadaque, e seus irmãos, Maaséias, Eliézer, Jaribe e Gedalias.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 19, 'E deram a sua mão, comprometendo-se a despedirem suas mulheres; e, achando-se culpados, ofereceram um carneiro do rebanho pela sua culpa.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 20, 'Dos filhos de Imer: Hanâni e Zebadias.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 21, 'Dos filhos de Harim: Maaséias, Elias, Semaías, Jeiel e Uzias.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 22, 'E dos filhos de Pasur: Elioenai, Maaséias, Ismael, Netanel, Jozabade e Elasa.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 23, 'Dos levitas: Jozabade, Simei, Quelaías {este é Quelita} , Petaías, Judá e Eliézer.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 24, 'Dos cantores: Eliasibe. Dos porteiros: Salum, Telem e îri.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 25, 'E de Israel, dos filhos de Parós: Ramias, Izias, Malquias, Miamim, Eleazar, Hasabias e Benaías.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 26, 'Dos filhos de Elão: Matanias, Zacarias, Jeiel, Abdi, Jerimote e Elias.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 27, 'Dos filhos de Zatu: Elioenai, Eliasibe, Matanias, Jerimote, Zabade e Aziza.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 28, 'Dos filhos de Bebai: Jeoanã, Hananias, Zabai e Atlai.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 29, 'Dos filhos de Bani: Mesulão, Maluque, Adaías, Jasube, Seal e Jerimote.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 30, 'Dos filhos de Paate-Moabe: Adná, Quelal, Benaías, Maaséias, Matanias, Bezaleel, Binuí e Manassés.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 31, 'Dos filhos de Harim: Eliézer, Issijá, Malquias, Semaías, Simeão,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 32, 'Benjamim, Maluque e Semarias.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 33, 'Dos filhos de Hasum: Matenai, Matatá, Zabade, Elifelete, Jeremai, Manassés e Simei.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 34, 'Dos filhos de Bani: Maadai, Anrão e Uel,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 35, 'Benaías, Bedéias, Queluí,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 36, 'Vanias, Meremote, Eliasibe,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 37, 'Matanias, Matenai e Jaasu.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 38, 'Dos filhos de Binuí: Simei,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 39, 'Selemias, Natã, Adaías,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 40, 'Macnadbai, Sasai, Sarai,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 41, 'Azarel, Selemias, Semarias,', 1, CURRENT_TIMESTAMP, false),
(15, 10, 42, 'Salum, Amarias e José.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 43, 'Dos filhos de Nebo: Jeiel, Matitias, Zabade, Zebina, Jadai, Joel e Benaías.', 1, CURRENT_TIMESTAMP, false),
(15, 10, 44, 'Todos estes tinham tomado mulheres estrangeiras; e se despediram das mulheres e dos filhos.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 1, 'Sucedeu nos dias de Assuero, o Assuero que reinou desde a Índia até a Etiópia, sobre cento e vinte e seis províncias,', 1, CURRENT_TIMESTAMP, false),
(17, 1, 2, 'que, estando o rei Assuero assentado no seu trono do seu reino em Susã, a capital,', 1, CURRENT_TIMESTAMP, false),
(17, 1, 3, 'no terceiro ano de seu reinado, deu um banquete a todos os seus príncipes e seus servos, estando assim perante ele o poder da Pérsia e da Média, os nobres e os oficiais das províncias.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 4, 'Nessa ocasião ostentou as riquezas do seu glorioso reino, e o esplendor da sua excelente grandeza, por muitos dias, a saber cento e oitenta dias.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 5, 'E, acabado aqueles dias, deu o rei um banquete a todo povo que se achava em Susã, a capital, tanto a grandes como a pequenos, por sete dias, no pátio do jardim do palácio real.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 6, 'As cortinas eram de pano branco verde e azul celeste, atadas com cordões de linho fino e de púrpura a argola de prata e a colunas de mármore; os leitos eram de ouro e prata sobre um pavimento mosaico de pórfiro, de mármore, de madrepérola e de pedras preciosas.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 7, 'Dava-se de beber em copos de ouro, os quais eram diferentes uns dos outros; e havia vinho real em abundância, segundo a generosidade do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 8, 'E bebiam como estava prescrito, sem constrangimento; pois o rei tinha ordenado a todos os oficiais do palácio que fizessem conforme a vontade de cada um.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 9, 'Também a rainha Vasti deu um banquete às mulheres no palácio do rei Assuero.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 10, 'Ao sétimo dia, o rei, estando já o seu coração alegre do vinho, mandou a Meumã, Bizta, Harbona, Bigta, Abagta, Zétar e Carcás, os sete eunucos que serviam na presença do rei Assuero,', 1, CURRENT_TIMESTAMP, false),
(17, 1, 11, 'que introduzissem à presença do rei a rainha Vasti, com a coroa real, para mostrar aos povos e aos príncipes a sua formosura, pois era formosíssima.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 12, 'A rainha Vasti, porém, recusou atender à ordem do rei dada por intermédio dos eunucos; pelo que o rei muito se enfureceu, e se inflamou de ira.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 13, 'Então perguntou o rei aos sábios que conheciam os tempos {pois assim se tratavam os negócios do rei, na presença de todos os que sabiam a lei e o direito;', 1, CURRENT_TIMESTAMP, false),
(17, 1, 14, 'e os mais chegados a ele eram: Carsena, Setar, Admata, Társis, Meres, Marsena, Memucã, os sete príncipes da Pérsia e da Média, que viam o rosto do rei e ocupavam os primeiros assentos no reino}', 1, CURRENT_TIMESTAMP, false),
(17, 1, 15, 'o que se devia fazer, segundo a lei, à rainha Vasti, por não haver cumprido a ordem do rei Assuero dada por intermédio dos eunucos.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 16, 'Respondeu Memucã na presença do rei e dos príncipes: Não somente contra o rei pecou a rainha Vasti, mas também contra todos os príncipes, e contra todos os povos que há em todas as províncias do rei Assuero.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 17, 'Pois o que a rainha fez chegará ao conhecimento de todas as mulheres, induzindo-as a desprezarem seus maridos quando se disser: O rei Assuero mandou que introduzissem à sua presença a rainha Vasti, e ela não veio.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 18, 'E neste mesmo dia as princesas da Pérsia e da Média, sabendo do que fez a rainha, dirão o mesmo a todos os príncipes do rei; e assim haverá muito desprezo e indignação.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 19, 'Se bem parecer ao rei, saia da sua parte um edito real, e escreva-se entre as leis dos persas e dos medos para que não seja alterado, que Vasti não entre mais na presença do rei Assuero, e dê o rei os seus direitos de rainha a outra que seja melhor do que ela.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 20, 'E quando o decreto que o rei baixar for publicado em todo o seu reino, grande como é, todas as mulheres darão honra a seus maridos, tanto aos nobres como aos humildes.', 1, CURRENT_TIMESTAMP, false),
(17, 1, 21, 'Pareceu bem este conselho ao rei e aos príncipes; e o rei fez conforme a palavra de Memucã,', 1, CURRENT_TIMESTAMP, false),
(17, 1, 22, 'enviando cartas a todas as províncias do rei, a cada província segundo o seu modo de escrever e a cada povo segundo a sua língua, mandando que cada homem fosse senhor em sua casa, e que falasse segundo a língua de seu povo.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 1, 'Passadas estas coisas e aplacada a ira do rei Assuero, lembrou-se ele de Vasti, do que ela fizera e do que se decretara a seu respeito.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 2, 'Então disseram os servos do rei que lhe ministravam: Busquem-se para o rei moças virgens e formosas.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 3, 'Ponha o rei em todas as províncias do seu reino oficiais que ajuntem todas as moças virgens e formosas em Susã, a capital, na casa das mulheres, sob a custódia de Hegai, eunuco do rei, guarda das mulheres; e dêem-se-lhes os seus cosméticos.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 4, 'E a donzela que agradar ao rei seja rainha em lugar de Vasti. E isso pareceu bem ao rei;  e ele assim fez.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 5, 'Havia então em Susã, a capital, certo judeu, benjamita, cujo nome era Mordecai, filho de Jair, filho de Simei, filho de Quis,', 1, CURRENT_TIMESTAMP, false),
(17, 2, 6, 'que tinha sido levado de Jerusalém com os cativos que foram deportados com Jeconias, rei de Judá, o qual Nabucodonosor, rei de Babilônia, transportara.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 7, 'Criara ele Hadassa, isto é, Ester, filha de seu tio, pois não tinha ela nem pai nem mãe; e era donzela esbelta e formosa;  e, morrendo seu pai e sua mãe, Mordecai a tomara por filha.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 8, 'Tendo se divulgado a ordem do rei e o seu edito, e ajuntando-se muitas donzelas em Susã, a capital, sob a custódia de Hegai, levaram também Ester ao palácio do rei, à custódia de Hegai, guarda das mulheres.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 9, 'E a donzela gradou-lhe, e alcançou o favor dele; pelo que ele se apressou em dar-lhe os cosméticos e os devidos alimentos, como também sete donzelas escolhidas do palácio do rei;  e a fez passar com as suas donzelas ao melhor lugar na casa das mulheres.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 10, 'Ester, porém, não tinha declarado o seu povo nem a sua parentela, pois Mordecai lhe tinha ordenado que não o declarasse.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 11, 'E cada dia Mordecai passeava diante do pátio da casa das mulheres, para lhe informar como Ester passava e do que lhe sucedia.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 12, 'Ora, quando chegava a vez de cada donzela vir ao Rei Assuero, depois que fora feito a cada uma segundo prescrito para as mulheres, por doze meses {pois assim se cumpriam os dias de seus preparativos, a saber, seis meses com óleo de mirra, e seis meses com especiarias e ungüentos em uso entre as mulheres};', 1, CURRENT_TIMESTAMP, false),
(17, 2, 13, 'desta maneira vinha a donzela ao rei: dava-lhe tudo quanto ela quisesse para levar consigo da casa das mulheres para o palácio do rei;', 1, CURRENT_TIMESTAMP, false),
(17, 2, 14, 'à tarde ela entrava, e pela manhã voltava para a segunda casa das mulheres, à custódia de Saasgaz, eunuco do rei, guarda das concubinas; ela não tornava mais ao rei, salvo se o rei desejasse, e fosse ela chamada por nome.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 15, 'Ora, quando chegou a vez de Ester, filha de Abiail, tio de Mordecai, que a tomara por sua filha, para ir ao rei, coisa nenhuma pediu senão o que indicou Hegai, eunuco do rei, guarda das mulheres. Mas Ester alcançava graça aos olhos de todos quantos a viam.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 16, 'Ester foi levada ao rei Assuero, ao palácio real, no décimo mês, que é o mês de tebete, no sétimo ano de seu reinado.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 17, 'E o rei amou a Ester mais do que a todas mulheres, e ela alcançou graça e favor diante dele mais do que todas as virgens; de sorte que lhe pôs sobre a cabeça a coroa real, e afez rainha em lugar de Vasti.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 18, 'Então o rei deu um grande banquete a todos os seus príncipes e aos seus servos; era um banquete em honra de Ester;  e concedeu alívio às províncias, e fez presentes com régia liberalidade.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 19, 'Quando pela segunda vez se ajuntavam as virgens, Mordecai estava sentado à porta do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 20, 'Ester, porém, como Mordecai lhe ordenara, não tinha declarado a sua parentela nem o seu povo: porque obedecia as ordens de Mordecai como quando estava sendo criada em casa dele.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 21, 'Naqueles dias, estando Mordecai sentado à porta do rei, dois eunucos do rei, os guardas da porta, Bigtã e Teres, se indignaram e procuravam tirar a vida ao rei Assuero.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 22, 'E veio isto ao conhecimento de Mordecai, que revelou à rainha Ester; e Ester o disse ao rei em nome de Mordecai.', 1, CURRENT_TIMESTAMP, false),
(17, 2, 23, 'Quando se investigou o negócio e se achou ser verdade, ambos foram enforcados; e isso foi escrito no livro das crônicas perante o rei.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 1, 'Depois destas coisas o rei Assuero engrandeceu a Hamã, filho de Hamedata, o agagita, e o exaltou, pondo-lhe o assento acima dos de todos os príncipes que estavam com ele.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 2, 'E todos os servos do rei que estavam à porta do rei se inclinavam e se prostravam perante Hamã, porque assim ordenara o rei a seu respeito: porém Mordecai não se inclinava nem se prostrava.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 3, 'Então os servos do rei que estavam à porta do rei disseram a Mordecai: Por que transgrides a ordem do rei?', 1, CURRENT_TIMESTAMP, false),
(17, 3, 4, 'E sucedeu que, dizendo-lhe eles isso dia após dia, e não lhes dando ele ouvidos, o fizeram saber a Hamã, para verem se o procedimento de Mordecai seria tolerado; pois ele lhes tinha declarado que era judeu.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 5, 'Vendo, pois, Hamã que Mordecai não se inclinava nem se prostrava diante dele, encheu-se de furor.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 6, 'Mas, achou pouco tirar a vida somente a Mordecai; porque lhe haviam declarado o povo de Mordecai.  Por esse motivo Hamã procurou destruir todos os judeus, o povo de Mordecai, que havia em todo o reino de Assuero.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 7, 'No primeiro mês, que é o mês de nisã, no ano duodécimo do rei Assuero, se lançou Pur, isto é, a sorte, perante Hamã, para cada dia e para mês, até o duodécimo, que é o mês de adar.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 8, 'E Hamã disse ao rei Assuero: Existe espalhado e disperso entre os povos em todas as províncias do teu reino um povo, cujas leis são diferentes das leis de todos os povos, e que não cumprem as leis do rei;  pelo que não convém ao rei tolerá-lo.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 9, 'Se bem parecer ao rei, decrete-se que seja destruído; e eu pagarei dez mil talentos de prata aos encarregados dos negócios do rei, para os recolherem ao tesouro do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 10, 'Então o rei tirou do seu dedo o anel, e o deu a Hamã, filho de Hamedata, o agagita, o inimigo dos judeus;', 1, CURRENT_TIMESTAMP, false),
(17, 3, 11, 'e disse o rei a Hamã: Essa prata te é dada, como também esse povo, para fazeres dele o que bem parecer aos teus olhos.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 12, 'Então foram chamados os secretários do rei no primeiro mês, no dia treze do mesmo e, conforme tudo, quando Hamã ordenou, se escreveu aos sátrapas do rei, e aos governadores que havia sobre todas as províncias, e aos príncipes de todos os povos; a cada província segundo o seu modo de escrever, e a cada povo segundo a sua língua;  em nome do rei Assuero se escreveu, e com o anel do rei se selou.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 13, 'Entiaram-se as cartas pelos correios a todas províncias do rei, para que destruíssem, matassem, e fizessem perecer todos os judeus, moços e velhos, crianças e mulheres, em um mesmo dia, a treze do duodécimo mês, que é o mês de adar, e para que lhes saqueassem os bens.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 14, 'Uma cópia do documento havia de ser publicada como decreto em cada província, para que todos os povos estivessem preparados para aquele dia.', 1, CURRENT_TIMESTAMP, false),
(17, 3, 15, 'Os correios saíram às pressas segundo a ordem do rei, e o decreto foi proclamado em Susã, a capital. Então, o rei e Hamã se assentaram a beber, mas a cidade de Susã estava perplexa.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 1, 'Quando Mordecai soube tudo quanto se havia passado, rasgou as suas vestes, vestiu-se de saco e de cinza, e saiu pelo meio da cidade, clamando com grande e amargo clamor;', 1, CURRENT_TIMESTAMP, false),
(17, 4, 2, 'e chegou até diante da porta do rei, pois ninguém vestido de saco podia entrar elas portas do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 3, 'Em todas as províncias aonde chegava a ordem do rei, e o seu decreto, havia entre os judeus grande pranto, com jejum, e choro, e lamentação; e muitos se deitavam em saco e em cinza.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 4, 'Quando vieram as moças de Ester e os eunucos lho fizeram saber, a rainha muito se entristeceu; e enviou roupa para Mordecai, a fim de que, despindo-lhe o saco, lha vestissem; ele, porém, não a aceitou.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 5, 'Então Ester mandou chamar Hataque, um dos eunucos do rei, que este havia designado para a servir, e o mandou ir ter com Mordecai para saber que era aquilo, e por que era.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 6, 'Hataque, pois, saiu a ter com Mordecai à praça da cidade, diante da porta do rei;', 1, CURRENT_TIMESTAMP, false),
(17, 4, 7, 'e Mordecai lhe fez saber tudo quanto lhe tinha sucedido, como também a soma exata do dinheiro que Hamã prometera pagar ao tesouro do rei pela destruição dos judeus.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 8, 'Também lhe deu a cópia do decreto escrito que se publicara em Susã para os destruir, para que a mostrasse a Ester, e lha explicasse, ordenando-lhe que fosse ter com o rei, e lhe pedisse misericórdia e lhe fizesse súplica ao seu povo.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 9, 'Veio, pois, Hataque, e referiu a Ester as palavras de Mordecai.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 10, 'Então falou Ester a Hataque, mandando-o dizer a Mordecai:', 1, CURRENT_TIMESTAMP, false),
(17, 4, 11, 'Todos os servos do rei, e o povo das províncias do rei, bem sabem que, para todo homem ou mulher que entrar à presença do rei no pátio interior sem ser chamado, não há senão uma sentença, a de morte, a menos que o rei estenda para ele o cetro de ouro, para que viva; mas eu já há trinta dias não sou chamada para entrar a ter com o rei.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 12, 'E referiram a Mordecai as palavras de Ester.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 13, 'Então Mordecai mandou que respondessem a Ester: Não imagines que, por estares no palácio do rei, terás mais sorte para escapar do que todos os outros judeus.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 14, 'Pois, se de todo te calares agora, de outra parte se levantarão socorro e livramento para os judeus, mas tu e a casa de teu pai perecereis; e quem sabe se não foi para tal tempo como este que chegaste ao reino?', 1, CURRENT_TIMESTAMP, false),
(17, 4, 15, 'De novo Ester mandou-os responder a Mordecai:', 1, CURRENT_TIMESTAMP, false),
(17, 4, 16, 'Vai, ajunta todos os judeus que se acham em Susã, e jejuai por mim, e não comais nem bebais por três dias, nem de noite nem de dia; e eu e as minhas moças também assim jejuaremos.  Depois irei ter com o rei, ainda que isso não é segundo a lei;  e se eu perecer, pereci.', 1, CURRENT_TIMESTAMP, false),
(17, 4, 17, 'Então Mordecai foi e fez conforme tudo quanto Ester lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 1, 'Ao terceiro dia Ester se vestiu de trajes reais, e se pôs no pátio interior do palácio do rei, defronte da sala do rei; e o rei estava assentado sobre o seu trono, na sala real, defronte da entrada.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 2, 'E sucedeu que, vendo o rei à rainha Ester, que estava em pé no pátio, ela alcançou favor dele; e o rei estendeu para Ester o cetro de ouro que tinha na sua mão.  Ester, pois, chegou-se e tocou na ponta do cetro.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 3, 'Então o rei lhe disse: O que é, rainha Ester?  qual é a tua petição?  Até metade do reino se te dará.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 4, 'Ester respondeu: Se parecer bem ao rei, venha hoje com Hamã ao banquete que tenho preparado para o rei.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 5, 'Então disse o rei: Fazei Hamã apressar-se para que se cumpra a vontade de Ester.  Vieram, pois, o rei e Hamã ao banquete que Ester tinha preparado.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 6, 'De novo disse o rei a Ester, no banquete do vinho: Qual é a tua petição?  e ser-te-á concedida;  e qual é o teu rogo?  e se te dará, ainda que seja metade do reino.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 7, 'Ester respondeu, dizendo; Eis a minha petição e o meu rogo:', 1, CURRENT_TIMESTAMP, false),
(17, 5, 8, 'Se tenho alcançado favor do rei, e se parecer bem ao rei concerder-me a minha petição e cumprir o meu rogo, venha o rei com Hamã ao banquete que lhes hei de preparar, e amanhã farei conforme a palavra do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 9, 'Então naquele dia Hamã saiu alegre e de bom ânimo; porém, vendo Mordecai à porta do rei, e que ele não se levantava nem tremia diante dele, Hamã se encheu de furor contra Mordecai.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 10, 'Contudo Hamã se refreou, e foi para casa; enviou e mandou vir os seus amigos, e Zéres, sua mulher.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 11, 'E contou-lhes Hamã a glória de suas riquezas, a multidão de seus filhos, e tudo em que o rei o tinha engrandecido, e como o havia exaltado sobre os príncipes e servos do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 12, 'E acrescentou: Tampouco a rainha Ester a ninguém fez vir com o rei ao banquete que preparou, senão a mim;  e também para amanhã estou convidado por ela juntamente com o rei.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 13, 'Todavia tudo isso não me satisfaz, enquanto eu vir o judeu Mordecai sentado à porta do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 5, 14, 'Então lhe disseram Zéres, sua mulher, e todos os seus amigos: Faça-se uma forca de cinqüenta côvados de altura, e pela manhã dize ao rei que nela seja enforcado Mordecai;  e então entra alegre com o rei para o banquete.  E este conselho agradou a Hamã, que mandou fazer a forca.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 1, 'Naquela mesma noite fugiu do rei o sono; então ele mandou trazer o livro de registro das crônicas, as quais se leram diante do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 2, 'E achou-se escrito que Mordecai tinha denunciado Bigtã e Teres, dois dos eunucos do rei, guardas da porta, que tinham procurado tirar a vida ao rei Assuero.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 3, 'E o rei perguntou: Que honra, ou dignidade, foi conferida a Mordecai por Isso?  Responderam os moços do rei que o serviam:  Coisa nenhuma se lhe fez.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 4, 'Então disse o rei: Quem está no pátio?  Ora, Hamã acabara de entrar no pátio exterior do palácio real para falar com o rei, a fim de que se enforcasse Mordecai na forca que lhe tinha preparado.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 5, 'E os servos do rei lhe responderam: Eis que Hamã está esperando no pátio.  E disse o rei que entrasse.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 6, 'Hamã, pois, entrou. Perguntou-lhe o rei:  Que se fará ao homem a quem o rei se agrada honrar?  Então Hamã disse consigo mesmo:  A quem se agradaria o rei honrar mais do que a mim?', 1, CURRENT_TIMESTAMP, false),
(17, 6, 7, 'Pelo que disse Hamã ao rei: Para o homem a quem o rei se agrada honrar,', 1, CURRENT_TIMESTAMP, false),
(17, 6, 8, 'sejam trazidos trajes reais que o rei tenha usado, e o cavalo em que o rei costuma andar, e ponha-se-lhe na cabeça uma coroa real;', 1, CURRENT_TIMESTAMP, false),
(17, 6, 9, 'sejam entregues os trajes e o cavalo à mão dum dos príncipes mais nobres do rei, e vistam deles aquele homem a quem o rei se agrada honrar, e façam-no andar montado pela praça da cidade, e proclamem diante dele: Assim se faz ao homem a quem o rei se agrada honrar!', 1, CURRENT_TIMESTAMP, false),
(17, 6, 10, 'Então disse o rei a Hamã: Apressa-te, toma os trajes e o cavalo como disseste, e faze assim para com o judeu Mordecai, que está sentado à porta do rei;  e não deixes falhar coisa alguma de tudo quanto disseste.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 11, 'Hamã, pois, tomou os trajes e o cavalo e vestiu a Mordecai, e o fez andar montado pela praça da cidade, e proclamou diante dele: Assim se faz ao homem a quem o rei se agrada honrar!', 1, CURRENT_TIMESTAMP, false),
(17, 6, 12, 'Depois disto Mordecai voltou para a porta do rei; porém Hamã se recolheu a toda pressa para sua casa, lamentando-se e de cabeça coberta.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 13, 'E contou Hamã a Zerés, sua mulher, e a todos os seus amigos tudo quanto lhe tinha sucedido. Então os seus sábios e Zerés, sua mulher, lhe disseram:  Se Mordecai, diante de quem já começaste a cair, é da linhagem dos judeus, não prevalecerás contra ele, antes certamente cairás diante dele.', 1, CURRENT_TIMESTAMP, false),
(17, 6, 14, 'Enquanto estes ainda falavam com ele, chegaram os eunucos do rei, e se apressaram a levar Hamã ao banquete que Ester preparara.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 1, 'Entraram, pois, o rei e Hamã para se banquetearem com a rainha Ester.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 2, 'Ainda outra vez disse o rei a Ester, no segundo dia, durante o banquete do vinho: Qual é a tua petição, rainha Ester?  e ser-te-á concedida;  e qual é o teu rogo?  Até metade do reino se te dará.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 3, 'Então respondeu a rainha Ester, e disse: Ó rei!  se eu tenho alcançado o teu favor, e se parecer bem ao rei, seja-me concedida a minha vida, eis a minha petição, e o meu povo, eis o meu rogo;', 1, CURRENT_TIMESTAMP, false),
(17, 7, 4, 'porque fomos vendidos, eu e o meu povo, para sermos destruídos, mortos e exterminados; se ainda por servos e por servas nos tivessem vendido, eu teria me calado, ainda que o adversário não poderia ter compensado a perda do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 5, 'Então falou o rei Assuero, e disse à rainha Ester: Quem é e onde está esse, cujo coração o instigou a fazer assim?', 1, CURRENT_TIMESTAMP, false),
(17, 7, 6, 'Respondeu Ester: Um adversário e inimigo, este perverso Hamã!  Então Hamã ficou aterrorizado perante o rei e a rainha.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 7, 'E o rei, no seu furor, se levantou do banquete do vinho e entrou no jardim do palácio; Hamã, porém, ficou para rogar à rainha Ester pela sua vida, porque viu que já o mal lhe estava determinado pelo rei.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 8, 'Ora, o rei voltou do jardim do palácio à sala do banquete do vinho; e Hamã havia caído prostrado sobre o leito em que estava Ester.  Então disse o rei:  Porventura quereria ele também violar a rainha perante mim na minha própria casa?  Ao sair essa palavra da boca do rei, cobriram a Hamã o rosto.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 9, 'Então disse Harbona, um dos eunucos que serviam diante do rei: Eis que a forca de cinqüenta côvados de altura que Hamã fizera para Mordecai, que falara em defesa do rei, está junto à casa de Hamã.  Então disse o rei:  Enforcai-o nela.', 1, CURRENT_TIMESTAMP, false),
(17, 7, 10, 'Enforcaram-no, pois, na forca que ele tinha preparado para Mordecai. Então o furor do rei se aplacou.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 1, 'Naquele mesmo dia deu o rei Assuero à rainha Ester a casa de Hamã, o inimigo dos judeus. E Mordecai apresentou-se perante o rei, pois Ester tinha declarado o que ele era.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 2, 'O rei tirou o seu anel que ele havia tomado a Hamã, e o deu a Mordecai. E Ester encarregou Mordecai da casa de Hamã.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 3, 'Tornou Ester a falar perante o rei e, lançando-se-lhe aos pés, com lágrimas suplicou que revogasse a maldade de Hamã, o agagita, e o intento que este projetara contra os judeus.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 4, 'Então o rei estendeu para Ester o cetro de ouro. Ester, pois, levantou-se e, pondo-se em pé diante do rei,', 1, CURRENT_TIMESTAMP, false),
(17, 8, 5, 'disse: Se parecer bem ao rei, e se eu tenho alcançado o seu favor, e se este negócio é reto diante do rei, e se eu lhe agrado, escreva-se que se revoguem as cartas concebidas por Hamã, filho de Hamedata, o agagita, as quais ele escreveu para destruir os judeus que há em todas as províncias do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 6, 'Pois como poderei ver a calamidade que sobrevirá ao meu povo? ou como poderei ver a destruição da minha parentela?', 1, CURRENT_TIMESTAMP, false),
(17, 8, 7, 'Então disse o rei Assuero à rainha Ester e ao judeu Mordecai: Eis que dei a Ester a casa de Hamã, e a ele enforcaram, porquanto estenderá as mãos contra os judeus.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 8, 'Escrevei vós também a respeito dos judeus, em nome do rei, como vos parecer bem, e selai-o com o anel do rei; pois um documento escrito em nome do rei e selado com o anel do rei não se pode revogar.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 9, 'Então foram chamados os secretários do rei naquele mesmo tempo, no terceiro mês, que é o mês de sivã, no vigésimo terceiro dia; e se escreveu conforme tudo quanto Mordecai ordenou a respeito dos judeus, aos sátrapas, aos governadores e aos príncipes das províncias, que se estendem da Índia até a Etiópia, cento e vinte e sete províncias, a cada província segundo o seu modo de escrever, e a cada povo conforme a sua língua; como também aos judeus segundo o seu modo de escrever e conforme a tua língua.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 10, 'Mordecai escreveu as cartas em nome do rei Assuero e, selando-as com anel do rei, enviou-as pela mão dos correios montados, que cavalgavam sobre ginetes que se usavam no serviço real e que eram da coudelaria do rei.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 11, 'Nestas cartas o rei concedia aos judeus que havia em cada cidade que se reunissem e se dispusessem para defenderem as suas vidas, e para destruírem, matarem e esterminarem todas as forças do povo e da província que os quisessem assaltar, juntamente com os seus pequeninos e as suas mulheres, e que saqueassem os seus bens,', 1, CURRENT_TIMESTAMP, false),
(17, 8, 12, 'num mesmo dia, em todas as províncias do rei Assuero, do dia treze do duodécimo mês, que é o mês de adar.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 13, 'E uma cópia da carta, que seria divulgada como decreto em todas as províncias, foi publicada entre todos os povos, para que os judeus estivessem preparados para aquele dia, a fim de se vingarem de seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 14, 'Partiram, pois, os correios montados em ginetes que se usavam no serviço real, apressados e impelidos pela ordem do rei; e foi proclamado o decreto em Susã, a capital.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 15, 'Então Mordecai saiu da presença do rei, vestido de um traje real azul celeste e branco, trazendo uma grande coroa de ouro, e um manto de linho fino e de púrpura, e a cidade de Susã exultou e se alegrou.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 16, 'E para os judeus houve luz e alegria, gozo e honra.', 1, CURRENT_TIMESTAMP, false),
(17, 8, 17, 'Também em toda a província, e em toda cidade, aonde chegava a ordem do rei ao seu decreto, havia entre os judeus alegria e gozo, banquetes e festas; e muitos, dentre os povos da terra, se fizeram judeus, pois o medo dos judeus tinha caído sobre eles.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 1, 'Ora, no duodécimo mês que é o mês de adar, no dia treze do mês, em que a ordem do rei e o seu decreto estavam para se executar, no dia em que os inimigos dos judeus esperavam assenhorar-se deles, sucedeu o contrário, de modo que os judeus foram os que se assenhorearam do que os odiavam.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 2, 'Ajuntaram-se, pois os judeus nas suas cidades, em todas as províncias do rei Assuero, para pôr as mãos naqueles que procuravam o seu mal; e ninguém podia resistir-lhes, porque o medo deles caíra sobre todos aqueles povos.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 3, 'E todos os príncipes das províncias, os sátrapas, os governadores e os que executavam os negócios do rei auxiliavam aos judeus, porque tinha caído sobre eles o medo de Mordecai.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 4, 'Pois Mordecai era grande na casa do rei, e a sua fama se espalhava por todas as províncias, porque o homem ia se tornando cada vez mais poderoso.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 5, 'Feriram, pois, os judeus a todos os seus inimigos a golpes de espada, matando-os e destruindo-os; e aos que os odiavam trataram como quiseram.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 6, 'E em Susã, a capital, os judeus mataram e destruíram quinhentos homens;', 1, CURRENT_TIMESTAMP, false),
(17, 9, 7, 'como também mataram Parsandata, Dalfom, Aspata,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 8, 'E a Porata, e a Adália, e a Aridata,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 9, 'Parmasta, Arisai, Aridai e Vaizata,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 10, 'os dez filhos de Hamã, filho de Hamedata, o inimigo dos judeus; porém ao despojo não estenderam a mão.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 11, 'Nesse mesmo dia veio ao conhecimento do rei o número dos mortos em Susã, a capital.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 12, 'E disse o rei à rainha Ester: Em Susã, a capital, os judeus mataram e destruíram quinhentos homens e os dez filhos de Hamã; que não teriam feito nas demais províncias do rei? Agora, qual é a tua petição? e te será concedida; e qual é ainda o teu rogo? e atender-se-á.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 13, 'Respondeu Ester: Se parecer bem ao rei, conceda aos judeus se acham em Susã que façam ainda amanhã conforme o decreto de hoje; e que os dez filhos de Hamã sejam pendurados na forca.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 14, 'Então o rei mandou que assim se fizesse; e foi publicado em edito em Susã, e os dez filhos de Hamã foram dependurados.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 15, 'Os judeus que se achavam em Susã reuniram-se também no dia catorze do mês de adar, e mataram em Susã trezentos homens; porém ao despojo não estenderam a mão.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 16, 'Da mesma sorte os demais judeus que se achavam nas províncias do rei se reuniram e se dispuseram em defesa das suas vidas, e tiveram repouso dos seus inimigos, matando dos que os odiavam setenta e cinco mil; porém ao despojo não estenderam a mão.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 17, 'Sucedeu isso no dia treze do mês de adar e no dia catorze descansaram, e o fizeram dia de banquetes e de alegria.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 18, 'Mas os judeus que se achavam em Susã se ajuntaram no dia treze como também no dia catorze; e descansaram no dia quinze, fazendo-o dia de banquetes e de alegria.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 19, 'Portanto os judeus das aldeias, que habitam nas cidades não muradas, fazem do dia catorze do mês de adar dia de alegria e de banquetes, e de festas, e dia de mandarem porções escolhidas uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 20, 'Mordecai escreveu estas coisas, e enviou cartas a todos os judeus que se achavam em todas as províncias do rei Assuero, aos de perto e aos de longe,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 21, 'ordenando-lhes que guardassem o dia catorze do mês de adar e o dia quinze do mesmo, todos os anos,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 22, 'como os dias em que os judeus tiveram repouso dos seus inimigos, e o mês em que se lhes mudou a tristeza em alegria, e o pranto em dia de festa, a fim de que os fizessem dias de banquetes e de alegria, e de mandarem porções escolhidas uns aos outros, e dádivas aos pobres.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 23, 'E os judeus se comprometeram a fazer como já tinham começado, e como Mordecai lhes tinha escrito;', 1, CURRENT_TIMESTAMP, false),
(17, 9, 24, 'porque Hamã, filho de Hamedata, o agagita, o inimigo de todos os judeus, tinha intentado destruir os judeus, e tinha lançado Pur, isto é, a sorte, para os assolar e destruir;', 1, CURRENT_TIMESTAMP, false),
(17, 9, 25, 'mas quando isto veio perante o rei, ordenou ele por cartas que o mau intento que Hamã formara contra os judeus recaísse sobre a sua cabeça, e que ele e seus filhos fossem pendurados na forca.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 26, 'Por isso aqueles dias se chamaram Purim, segundo o nome Pur. portanto, por causa de todas as palavras daquela carta, e do que tinham testemunhado nesse sentido, e do que lhes havia sucedido,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 27, 'os judeus concordaram e se comprometeram por si, sua descendência, e por todos os que haviam de unir-se com eles, a não deixarem de guardar estes dois dias, conforme o que se escreveras a respeito deles, e segundo o seu tempo determinado, todos os anos;', 1, CURRENT_TIMESTAMP, false),
(17, 9, 28, 'e a fazerem com que esses dias fossem lembrados e guardados por toda geração, família, província e cidade; e que esses dias de Purim não fossem revogados entre os judeus, e que a memória deles nunca perecesse dentre a sua descendência.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 29, 'Então a rainha Ester, filha de Abiail, e o judeu Mordecai escreveram cartas com toda a autoridade para confirmar esta segunda carta a respeito de Purim,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 30, 'e enviaram-nas a todos os judeus, às cento e vinte e sete províncias do reino de Assuero, com palavras de paz e de verdade,', 1, CURRENT_TIMESTAMP, false),
(17, 9, 31, 'para confirmar esses dias de Purim nos seus tempos determinados, como o judeu Mordecai e a rainha Ester lhes tinham ordenado, e como eles se haviam obrigado por si e pela sua descendência no tocante a seus jejuns e suas lamentações.', 1, CURRENT_TIMESTAMP, false),
(17, 9, 32, 'A ordem de Ester confirmou o que dizia respeito ao Purim; e foi isso registrado nos anais.', 1, CURRENT_TIMESTAMP, false),
(17, 10, 1, 'O rei Assuero impôs tributo à terra e às ilhas do mar.', 1, CURRENT_TIMESTAMP, false),
(17, 10, 2, 'Quanto a todos os atos do seu poder e do seu valor, e a narrativa completa da grandeza de Mordecai, com que o rei o exaltou, porventura não estão eles escritos no livro dos anais dos reis da Média e da Pérsia?', 1, CURRENT_TIMESTAMP, false),
(17, 10, 3, 'Pois o judeu Mordecai foi o segundo depois do rei Assuero, e grande entre os judeus, e estimado pela multidão de seus irmãos, porque procurava o bem-estar do seu povo, e falava pela paz de toda sua nação.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 1, 'Ora, estes são os nomes dos filhos de Israel, que entraram no Egito; entraram com Jacó, cada um com a sua família:', 1, CURRENT_TIMESTAMP, false),
(2, 1, 2, 'Rúben, Simeão, Levi, e Judá;', 1, CURRENT_TIMESTAMP, false),
(2, 1, 3, 'Issacar, Zebulom e Benjamim;', 1, CURRENT_TIMESTAMP, false),
(2, 1, 4, 'Dã e Naftali, Gade e Aser.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 5, 'Todas as almas, pois, que procederam da coxa de Jacó, foram setenta; José, porém, já estava no Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 6, 'Morreu, pois, José, e todos os seus irmãos, e toda aquela geração.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 7, 'Depois os filhos de Israel frutificaram e aumentaram muito, multiplicaram-se e tornaram-se sobremaneira fortes, de modo que a terra se encheu deles.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 8, 'Entrementes se levantou sobre o Egito um novo rei, que não conhecera a José.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 9, 'Disse ele ao seu povo: Eis que o povo de Israel é mais numeroso e mais forte do que nos.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 10, 'Eia, usemos de astúcia para com ele, para que não se multiplique, e aconteça que, vindo guerra, ele também se ajunte com os nossos inimigos, e peleje contra nós e se retire da terra.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 11, 'Portanto puseram sobre eles feitores, para os afligirem com suas cargas. Assim os israelitas edificaram para Faraó cidades armazéns, Pitom e Ramessés.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 12, 'Mas quanto mais os egípcios afligiam o povo de Israel, tanto mais este se multiplicava e se espalhava; de maneira que os egípcios se enfadavam por causa dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 13, 'Por isso os egípcios faziam os filhos de Israel servir com dureza;', 1, CURRENT_TIMESTAMP, false),
(2, 1, 14, 'assim lhes amarguravam a vida com pesados serviços em barro e em tijolos, e com toda sorte de trabalho no campo, enfim com todo o seu serviço, em que os faziam servir com dureza.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 15, 'Falou o rei do Egito às parteiras das hebréias, das quais uma se chamava Sifrá e a outra Puá,', 1, CURRENT_TIMESTAMP, false),
(2, 1, 16, 'dizendo: Quando ajudardes no parto as hebréias, e as virdes sobre os assentos, se for filho, matá-lo-eis; mas se for filha, viverá.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 17, 'As parteiras, porém, temeram a Deus e não fizeram como o rei do Egito lhes ordenara, antes conservavam os meninos com vida.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 18, 'Pelo que o rei do Egito mandou chamar as parteiras e as interrogou: Por que tendes feito isto e guardado os meninos com vida?', 1, CURRENT_TIMESTAMP, false),
(2, 1, 19, 'Responderam as parteiras a Faraó: É que as mulheres hebréias não são como as egípcias; pois são vigorosas, e já têm dado à luz antes que a parteira chegue a elas.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 20, 'Portanto Deus fez bem às parteiras. E o povo se aumentou, e se fortaleceu muito.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 21, 'Também aconteceu que, como as parteiras temeram a Deus, ele lhes estabeleceu as casas.', 1, CURRENT_TIMESTAMP, false),
(2, 1, 22, 'Então ordenou Faraó a todo o seu povo, dizendo: A todos os filhos que nascerem lançareis no rio, mas a todas as filhas guardareis com vida.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 1, 'Foi-se um homem da casa de Levi e casou com uma filha de Levi.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 2, 'A mulher concebeu e deu à luz um filho; e, vendo que ele era formoso, escondeu-o três meses.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 3, 'Não podendo, porém, escondê-lo por mais tempo, tomou para ele uma arca de juncos, e a revestiu de betume e pez; e, pondo nela o menino, colocou-a entre os juncos a margem do rio.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 4, 'E sua irmã postou-se de longe, para saber o que lhe aconteceria.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 5, 'A filha de Faraó desceu para banhar-se no rio, e as suas criadas passeavam à beira do rio. Vendo ela a arca no meio os juncos, mandou a sua criada buscá-la.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 6, 'E abrindo-a, viu a criança, e eis que o menino chorava; então ela teve compaixão dele, e disse: Este é um dos filhos dos hebreus.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 7, 'Então a irmã do menino perguntou à filha de Faraó: Queres que eu te vá chamar uma ama dentre as hebréias, para que crie este menino para ti?', 1, CURRENT_TIMESTAMP, false),
(2, 2, 8, 'Respondeu-lhe a filha de Faraó: Vai. Foi, pois, a moça e chamou a mãe do menino.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 9, 'Disse-lhe a filha de Faraó: Leva este menino, e cria-mo; eu te darei o teu salário. E a mulher tomou o menino e o criou.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 10, 'Quando, pois, o menino era já grande, ela o trouxe à filha de Faraó, a qual o adotou; e lhe chamou Moisés, dizendo: Porque das águas o tirei.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 11, 'Ora, aconteceu naqueles dias que, sendo Moisés já homem, saiu a ter com seus irmãos e atentou para as suas cargas; e viu um egípcio que feria a um hebreu dentre, seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 12, 'Olhou para um lado e para outro, e vendo que não havia ninguém ali, matou o egípcio e escondeu-o na areia.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 13, 'Tornou a sair no dia seguinte, e eis que dois hebreus contendiam; e perguntou ao que fazia a injustiça: Por que feres a teu próximo?', 1, CURRENT_TIMESTAMP, false),
(2, 2, 14, 'Respondeu ele: Quem te constituiu a ti príncipe e juiz sobre nós? Pensas tu matar-me, como mataste o egípcio? Temeu, pois, Moisés e disse: Certamente o negócio já foi descoberto.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 15, 'E quando Faraó soube disso, procurou matar a Moisés. Este, porém, fugiu da presença de Faraó, e foi habitar na terra de Midiã; e sentou-se junto a um poço.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 16, 'O sacerdote de Midiã tinha sete filhas, as quais vieram tirar água, e encheram os tanques para dar de beber ao rebanho de seu pai.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 17, 'Então vieram os pastores, e as expulsaram dali; Moisés, porém, levantou-se e as defendeu, e deu de beber ao rebanho delas.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 18, 'Quando elas voltaram a Reuel, seu pai, este lhes perguntou: como é que hoje voltastes tão cedo?', 1, CURRENT_TIMESTAMP, false),
(2, 2, 19, 'Responderam elas: um egípcio nos livrou da mão dos pastores; e ainda tirou água para nós e deu de beber ao rebanho.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 20, 'E ele perguntou a suas filhas: Onde está ele; por que deixastes lá o homem? chamai-o para que coma pão.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 21, 'Então Moisés concordou em morar com aquele homem, o qual lhe deu sua filha Zípora.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 22, 'E ela deu à luz um filho, a quem ele chamou Gérson, porque disse: Peregrino sou em terra estrangeira.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 23, 'No decorrer de muitos dias, morreu o rei do Egito; e os filhos de Israel gemiam debaixo da servidão; pelo que clamaram, e subiu a Deus o seu clamor por causa dessa servidão.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 24, 'Então Deus, ouvindo-lhes os gemidos, lembrou-se do seu pacto com Abraão, com Isaque e com Jacó.', 1, CURRENT_TIMESTAMP, false),
(2, 2, 25, 'E atentou Deus para os filhos de Israel; e Deus os conheceu.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 1, 'Ora, Moisés estava apascentando o rebanho de Jetro, seu sogro, sacerdote de Midiã; e levou o rebanho para trás do deserto, e chegou a Horebe, o monte de Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 2, 'E apareceu-lhe o anjo do Senhor em uma chama de fogo do meio duma sarça. Moisés olhou, e eis que a sarça ardia no fogo, e a sarça não se consumia;', 1, CURRENT_TIMESTAMP, false),
(2, 3, 3, 'pelo que disse: Agora me virarei para lá e verei esta maravilha, e por que a sarça não se queima.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 4, 'E vendo o Senhor que ele se virara para ver, chamou-o do meio da sarça, e disse: Moisés, Moisés! Respondeu ele: Eis-me aqui.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 5, 'Prosseguiu Deus: Não te chegues para cá; tira os sapatos dos pés; porque o lugar em que tu estás é terra santa.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 6, 'Disse mais: Eu sou o Deus de teu pai, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó. E Moisés escondeu o rosto, porque temeu olhar para Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 7, 'Então disse o Senhor: Com efeito tenho visto a aflição do meu povo, que está no Egito, e tenho ouvido o seu clamor por causa dos seus exatores, porque conheço os seus sofrimentos;', 1, CURRENT_TIMESTAMP, false),
(2, 3, 8, 'e desci para o livrar da mão dos egípcios, e para o fazer subir daquela terra para uma terra boa e espaçosa, para uma terra que mana leite e mel; para o lugar do cananeu, do heteu, do amorreu, do perizeu, do heveu e do jebuseu.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 9, 'E agora, eis que o clamor dos filhos de Israel é vindo a mim; e também tenho visto a opressão com que os egípcios os oprimem.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 10, 'Agora, pois, vem e eu te enviarei a Faraó, para que tireis do Egito o meu povo, os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 11, 'Então Moisés disse a Deus: Quem sou eu, para que vá a Faraó e tire do Egito os filhos de Israel?', 1, CURRENT_TIMESTAMP, false),
(2, 3, 12, 'Respondeu-lhe Deus: Certamente eu serei contigo; e isto te será por sinal de que eu te enviei: Quando houveres tirado do Egito o meu povo, servireis a Deus neste monte.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 13, 'Então disse Moisés a Deus: Eis que quando eu for aos filhos de Israel, e lhes disser: O Deus de vossos pais me enviou a vós; e eles me perguntarem: Qual é o seu nome? Que lhes direi?', 1, CURRENT_TIMESTAMP, false),
(2, 3, 14, 'Respondeu Deus a Moisés: EU SOU O QUE SOU. Disse mais: Assim dirás aos olhos de Israel: EU SOU me enviou a vós.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 15, 'E Deus disse mais a Moisés: Assim dirás aos filhos de Israel: O Senhor, o Deus de vossos pais, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó, me enviou a vós; este é o meu nome eternamente, e este é o meu memorial de geração em geração.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 16, 'Vai, ajunta os anciãos de Israel e dize-lhes: O Senhor, o Deus de vossos pais, o Deus de Abraão, de Isaque e de Jacó, apareceu-me, dizendo: certamente vos tenho visitado e visto o que vos tem sido feito no Egito;', 1, CURRENT_TIMESTAMP, false),
(2, 3, 17, 'e tenho dito: Far-vos-ei subir da aflição do Egito para a terra do cananeu, do heteu, do amorreu, do perizeu, do heveu e do jebuseu, para uma terra que mana leite e mel.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 18, 'E ouvirão a tua voz; e ireis, tu e os anciãos de Israel, ao rei do Egito, e dir-lhe-eis: O Senhor, o Deus dos hebreus, encontrou-nos. Agora, pois, deixa-nos ir caminho de três dias para o deserto para que ofereçamos sacrifícios ao Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 19, 'Eu sei, porém, que o rei do Egito não vos deixará ir, a não ser por uma forte mão.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 20, 'Portanto estenderei a minha mão, e ferirei o Egito com todas as minhas maravilhas que farei no meio dele. Depois vos deixará ir.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 21, 'E eu darei graça a este povo aos olhos dos egípcios; e acontecerá que, quando sairdes, não saireis vazios.', 1, CURRENT_TIMESTAMP, false),
(2, 3, 22, 'Porque cada mulher pedirá à sua vizinha e à sua hóspeda jóias de prata e jóias de ouro, bem como vestidos, os quais poreis sobre vossos filhos e sobre vossas filhas; assim despojareis os egípcios.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 1, 'Então respondeu Moisés: Mas eis que não me crerão, nem ouvirão a minha voz, pois dirão: O Senhor não te apareceu.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 2, 'Ao que lhe perguntou o Senhor: Que é isso na tua mão. Disse Moisés: uma vara.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 3, 'Ordenou-lhe o Senhor: Lança-a no chão. Ele a lançou no chão, e ela se tornou em cobra; e Moisés fugiu dela.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 4, 'Então disse o Senhor a Moisés: Estende a mão e pega-lhe pela cauda {estendeu ele a mão e lhe pegou, e ela se tornou em vara na sua mão};', 1, CURRENT_TIMESTAMP, false),
(2, 4, 5, 'para que eles creiam que te apareceu o Senhor, o Deus de seus pais, o Deus de Abraão, o Deus de Isaque e o Deus de Jacó.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 6, 'Disse-lhe mais o Senhor: Mete agora a mão no seio. E meteu a mão no seio. E quando a tirou, eis que a mão estava leprosa, branca como a neve.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 7, 'Disse-lhe ainda: Torna a meter a mão no seio. {E tornou a meter a mão no seio; depois tirou-a do seio, e eis que se tornara como o restante da sua carne.}', 1, CURRENT_TIMESTAMP, false),
(2, 4, 8, 'E sucederá que, se eles não te crerem, nem atentarem para o primeiro sinal, crerão ao segundo sinal.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 9, 'E se ainda não crerem a estes dois sinais, nem ouvirem a tua voz, então tomarás da água do rio, e a derramarás sobre a terra seca; e a água que tomares do rio tornar-se-á em sangue sobre a terra seca.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 10, 'Então disse Moisés ao Senhor: Ah, Senhor! eu não sou eloqüente, nem o fui dantes, nem ainda depois que falaste ao teu servo; porque sou pesado de boca e pesado de língua.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 11, 'Ao que lhe replicou o Senhor: Quem faz a boca do homem? ou quem faz o mudo, ou o surdo, ou o que vê, ou o cego?. Não sou eu, o Senhor?', 1, CURRENT_TIMESTAMP, false),
(2, 4, 12, 'Vai, pois, agora, e eu serei com a tua boca e te ensinarei o que hás de falar.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 13, 'Ele, porém, respondeu: Ah, Senhor! envia, peço-te, por mão daquele a quem tu hás de enviar.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 14, 'Então se acendeu contra Moisés a ira do Senhor, e disse ele: Não é Arão, o levita, teu irmão? eu sei que ele pode falar bem. Eis que ele também te sai ao encontro, e vendo-te, se alegrará em seu coração.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 15, 'Tu, pois, lhe falarás, e porás as palavras na sua boca; e eu serei com a tua boca e com a dele, e vos ensinarei o que haveis de fazer.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 16, 'E ele falará por ti ao povo; assim ele te será por boca, e tu lhe serás por Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 17, 'Tomarás, pois, na tua mão esta vara, com que hás de fazer os sinais.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 18, 'Então partiu Moisés, e voltando para Jetro, seu sogro, disse-lhe: Deixa-me, peço-te, voltar a meus irmãos, que estão no Egito, para ver se ainda vivem. Disse, pois, Jetro a Moisés: Vai-te em paz.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 19, 'Disse também o Senhor a Moisés em Midiã: Vai, volta para o Egito; porque morreram todos os que procuravam tirar-te a vida.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 20, 'Tomou, pois, Moisés sua mulher e seus filhos, e os fez montar num jumento e tornou à terra do Egito; e Moisés levou a vara de Deus na sua mão.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 21, 'Disse ainda o Senhor a Moisés: Quando voltares ao Egito, vê que faças diante de Faraó todas as maravilhas que tenho posto na tua mão; mas eu endurecerei o seu coração, e ele não deixará ir o povo.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 22, 'Então dirás a Faraó: Assim diz o Senhor: Israel é meu filho, meu primogênito;', 1, CURRENT_TIMESTAMP, false),
(2, 4, 23, 'e eu te tenho dito: Deixa ir: meu filho, para que me sirva. mas tu recusaste deixá-lo ir; eis que eu matarei o teu filho, o teu primogênito.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 24, 'Ora, sucedeu no caminho, numa estalagem, que o Senhor o encontrou, e quis matá-lo.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 25, 'Então Zípora tomou uma faca de pedra, circuncidou o prepúcio de seu filho e, lançando-o aos pés de Moisés, disse: Com efeito, és para mim um esposo sanguinário.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 26, 'O Senhor, pois, o deixou. Ela disse: Esposo sanguinário, por causa da circuncisão.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 27, 'Disse o Senhor a Arão: Vai ao deserto, ao encontro de Moisés. E ele foi e, encontrando-o no monte de Deus, o beijou:', 1, CURRENT_TIMESTAMP, false),
(2, 4, 28, 'E relatou Moisés a Arão todas as palavras com que o Senhor o enviara e todos os sinais que lhe mandara.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 29, 'Então foram Moisés e Arão e ajuntaram todos os anciãos dos filhos de Israel;', 1, CURRENT_TIMESTAMP, false),
(2, 4, 30, 'e Arão falou todas as palavras que o Senhor havia dito a Moisés e fez os sinais perante os olhos do povo.', 1, CURRENT_TIMESTAMP, false),
(2, 4, 31, 'E o povo creu; e quando ouviram que o Senhor havia visitado os filhos de Israel e que tinha visto a sua aflição, inclinaram-se, e adoraram.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 1, 'Depois foram Moisés e Arão e disseram a Faraó: Assim diz o Senhor, o Deus de Israel: Deixa ir o meu povo, para que me celebre uma festa no deserto.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 2, 'Mas Faraó respondeu: Quem é o Senhor, para que eu ouça a sua voz para deixar ir Israel? Não conheço o Senhor, nem tampouco deixarei ir Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 3, 'Então eles ainda falaram: O Deus dos hebreus nos encontrou; portanto deixa-nos, pedimos-te, ir caminho de três dias ao deserto, e oferecer sacrifícios ao Senhor nosso Deus, para que ele não venha sobre nós com pestilência ou com espada.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 4, 'Respondeu-lhes de novo o rei do Egito: Moisés e Arão, por que fazeis o povo cessar das suas obras? Ide às vossas cargas.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 5, 'Disse mais Faraó: Eis que o povo da terra já é muito, e vós os fazeis abandonar as suas cargas.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 6, 'Naquele mesmo dia Faraó deu ordem aos exatores do povo e aos seus oficiais, dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 5, 7, 'Não tornareis a dar, como dantes, palha ao povo, para fazer tijolos; vão eles mesmos, e colham palha para si.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 8, 'Também lhes imporeis a conta dos tijolos que dantes faziam; nada diminuireis dela; porque eles estão ociosos; por isso clamam, dizendo: Vamos, sacrifiquemos ao nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 9, 'Agrave-se o serviço sobre esses homens, para que se ocupem nele e não dêem ouvidos a palavras mentirosas.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 10, 'Então saíram os exatores do povo e seus oficiais, e disseram ao povo: Assim diz Faraó: Eu não vos darei palha;', 1, CURRENT_TIMESTAMP, false),
(2, 5, 11, 'ide vós mesmos, e tomai palha de onde puderdes achá-la; porque nada se diminuirá de vosso serviço.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 12, 'Então o povo se espalhou por toda parte do Egito a colher restolho em lugar de palha.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 13, 'E os exatores os apertavam, dizendo: Acabai a vossa obra, a tarefa do dia no seu dia, como quando havia palha.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 14, 'E foram açoitados os oficiais dos filhos de Israel, postos sobre eles pelos exatores de Faraó, que reclamavam: Por que não acabastes nem ontem nem hoje a vossa tarefa, fazendo tijolos como dantes?', 1, CURRENT_TIMESTAMP, false),
(2, 5, 15, 'Pelo que os oficiais dos filhos de Israel foram e clamaram a Faraó, dizendo: Porque tratas assim a teus servos?', 1, CURRENT_TIMESTAMP, false),
(2, 5, 16, 'Palha não se dá a teus servos, e nos dizem: Fazei tijolos; e eis que teus servos são açoitados; porém o teu povo é que tem a culpa.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 17, 'Mas ele respondeu: Estais ociosos, estais ociosos; por isso dizeis: vamos, sacrifiquemos ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 18, 'Portanto, ide, trabalhai; palha, porém, não se vos dará; todavia, dareis a conta dos tijolos.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 19, 'Então os oficiais dos filhos de Israel viram-se em aperto, porquanto se lhes dizia: Nada diminuireis dos vossos tijolos, da tarefa do dia no seu dia.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 20, 'Ao saírem da presença de Faraó depararam com Moisés e Arão que vinham ao encontro deles,', 1, CURRENT_TIMESTAMP, false),
(2, 5, 21, 'e disseram-lhes: Olhe o Senhor para vós, e julgue isso, porquanto fizestes o nosso caso repelente diante de Faraó e diante de seus servos, metendo-lhes nas mãos uma espada para nos matar.', 1, CURRENT_TIMESTAMP, false),
(2, 5, 22, 'Então, tornando-se Moisés ao Senhor, disse: Senhor! por que trataste mal a este povo? por que me enviaste?', 1, CURRENT_TIMESTAMP, false),
(2, 5, 23, 'Pois desde que me apresentei a Faraó para falar em teu nome, ele tem maltratado a este povo; e de nenhum modo tens livrado o teu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 1, 'Então disse o Senhor a Moisés: Agora verás o que hei de fazer a Faraó; pois por uma poderosa mão os deixará ir, sim, por uma poderosa mão os lançará de sua terra.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 2, 'Falou mais Deus a Moisés, e disse-lhe: Eu sou Jeová.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 3, 'Apareci a Abraão, a Isaque e a Jacó, como o Deus Todo-Poderoso; mas pelo meu nome Jeová, não lhes fui conhecido.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 4, 'Estabeleci o meu pacto com eles para lhes dar a terra de Canaã, a terra de suas peregrinações, na qual foram peregrinos.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 5, 'Ademais, tenho ouvido o gemer dos filhos de Israel, aos quais os egípcios vêm escravizando; e lembrei-me do meu pacto.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 6, 'Portanto dize aos filhos de Israel: Eu sou Jeová; eu vos tirarei de debaixo das cargas dos egípcios, livrar-vos-ei da sua servidão, e vos resgatarei com braço estendido e com grandes juízos.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 7, 'Eu vos tomarei por meu povo e serei vosso Deus; e vós sabereis que eu sou Jeová vosso Deus, que vos tiro de debaixo das cargas dos egípcios.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 8, 'Eu vos introduzirei na terra que jurei dar a Abraão, a Isaque e a Jacó; e vo-la darei por herança. Eu sou Jeová.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 9, 'Assim falou Moisés aos filhos de Israel, mas eles não lhe deram ouvidos, por causa da angústia de espírito e da dura servidão.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 10, 'Falou mais o Senhor a Moisés, dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 6, 11, 'Vai, fala a Faraó, rei do Egito, que deixe sair os filhos de Israel da sua terra.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 12, 'Moisés, porém, respondeu perante o Senhor, dizendo: Eis que os filhos de Israel não me têm ouvido: como, pois, me ouvirá Faraó a mim, que sou incircunciso de lábios?', 1, CURRENT_TIMESTAMP, false),
(2, 6, 13, 'Todavia o Senhor falou a Moisés e a Arão, e deu-lhes mandamento para os filhos de Israel, e para Faraó, rei do Egito, a fim de tirarem os filhos de Israel da terra do Egito..', 1, CURRENT_TIMESTAMP, false),
(2, 6, 14, 'Estes são os cabeças das casas de seus pais: Os filhos de Rúben o primogênito de Israel: Hanoque e Palu, Hezrom e Carmi; estas são as famílias de Rúben.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 15, 'E os filhos de Simeão: Jemuel, Jamim, Oade, Jaquim, Zoar e Saul, filho de uma cananéia; estas são as famílias de Simeão.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 16, 'E estes são os nomes dos filhos de Levi, segundo as suas gerações: Gérson, Coate e Merári; e os anos da vida de Levi foram cento e trinta e sete anos.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 17, 'Os filhos de Gérson: Líbni e Simei, segundo as suas famílias.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 18, 'Os filhos de Coate: Anrão, Izar, Hebrom e Uziel; e os anos da vida de Coate foram cento e trinta e três anos.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 19, 'Os filhos de Merari: Mali e Musi; estas são as famílias de Levi, segundo as suas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 20, 'Ora, Anrão tomou por mulher a Joquebede, sua tia; e ela lhe deu Arão e Moisés; e os anos da vida de Anrão foram cento e trinta e sete anos.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 21, 'Os filhos de Izar: Corá, Nofegue e Zicri.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 22, 'Os filhos de Uziel: Misael, Elzafã e Sitri.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 23, 'Arão tomou por mulher a Eliseba, filha de Aminadabe, irmã de Nasom; e ela lhe deu Nadabe, Abiú, Eleazar e Itamar.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 24, 'Os filhos de Corá: Assir, Elcana e Abiasafe; estas são as famílias dos coraítas.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 25, 'Eleazar, filho de Arão, tomou por mulher uma das filhas de Putiel; e ela lhe deu Finéias; estes são os chefes das casa, paternas dos levitas, segundo as suas famílias.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 26, 'Estes são Arão e Moisés, aos quais o Senhor disse: Tirai os filhos de Israel da terra do Egito, segundo os seus exércitos.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 27, 'Foram eles os que falaram a Faraó, rei do Egito, a fim de tirarem do Egito os filhos de Israel; este Moisés e este Arão.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 28, 'No dia em que o Senhor falou a Moisés na terra do Egito,', 1, CURRENT_TIMESTAMP, false),
(2, 6, 29, 'disse o Senhor a Moisés: Eu sou Jeová; dize a Faraó, rei do Egito, tudo quanto eu te digo.', 1, CURRENT_TIMESTAMP, false),
(2, 6, 30, 'Respondeu Moisés perante o Senhor: Eis que eu sou incircunciso de lábios; como, pois, me ouvirá Faraó;', 1, CURRENT_TIMESTAMP, false),
(2, 7, 1, 'Então disse o Senhor a Moisés: Eis que te tenho posto como Deus a Faraó, e Arão, teu irmão, será o teu profeta.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 2, 'Tu falarás tudo o que eu te mandar; e Arão, teu irmão, falará a Faraó, que deixe ir os filhos de Israel da sua terra.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 3, 'Eu, porém, endurecerei o coração de Faraó e multiplicarei na terra do Egito os meus sinais e as minhas maravilhas.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 4, 'Mas Faraó não vos ouvirá; e eu porei minha mão sobre o Egito, e tirarei os meus exércitos, o meu povo, os filhos de Israel, da terra do Egito, com grandes juízos.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 5, 'E os egípcios saberão que eu sou o Senhor, quando estender a minha mão sobre o Egito, e tirar os filhos de Israel do meio deles.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 6, 'Assim fizeram Moisés e Arão; como o Senhor lhes ordenara, assim fizeram.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 7, 'Tinha Moisés oitenta anos, e Arão oitenta e três, quando falaram a Faraó.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 8, 'Falou, pois, o Senhor a Moisés e Arão:', 1, CURRENT_TIMESTAMP, false),
(2, 7, 9, 'Quando Faraó vos disser: Apresentai da vossa parte algum milagre; dirás a Arão: Toma a tua vara, e lança-a diante de Faraó, para que se torne em serpente.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 10, 'Então Moisés e Arão foram ter com Faraó, e fizeram assim como o Senhor ordenara. Arão lançou a sua vara diante de Faraó e diante dos seus servos, e ela se tornou em serpente.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 11, 'Faraó também mandou vir os sábios e encantadores; e eles, os magos do Egito, também fizeram o mesmo com os seus encantamentos.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 12, 'Pois cada um deles lançou a sua vara, e elas se tornaram em serpentes; mas a vara de Arão tragou as varas deles.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 13, 'Endureceu-se, porém, o coração de Faraó, e ele não os ouviu, como o Senhor tinha dito.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 14, 'Então disse o Senhor a Moisés: Obstinou-se o coração de Faraó; ele recusa deixar ir o povo.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 15, 'Vai ter com Faraó pela manhã; eis que ele sairá às águas; pôr-te-ás à beira do rio para o encontrar, e tomarás na mão a vara que se tomou em serpente.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 16, 'E lhe dirás: O Senhor, o Deus dos hebreus, enviou-me a ti para dizer-te: Deixa ir o meu povo, para que me sirva no deserto; porém eis que até agora não o tens ouvido.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 17, 'Assim diz o Senhor: Nisto saberás que eu sou o Senhor: Eis que eu, com esta vara que tenho na mão, ferirei as águas que estão no rio, e elas se tornarão em sangue.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 18, 'E os peixes que estão no rio morrerão, e o rio cheirará mal; e os egípcios terão nojo de beber da água do rio.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 19, 'Disse mais o Senhor a Moisés: Dize a Arão: Toma a tua vara, e estende a mão sobre as águas do Egito, sobre as suas correntes, sobre os seus rios, e sobre as suas lagoas e sobre todas as suas águas empoçadas, para que se tornem em sangue; e haverá sangue por toda a terra do Egito, assim nos vasos de madeira como nos de pedra.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 20, 'Fizeram Moisés e Arão como lhes ordenara o Senhor; Arão, levantando a vara, feriu as águas que estavam no rio, diante dos olhos de Faraó, e diante dos olhos de seus servos; e todas as águas do rio se tornaram em sangue.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 21, 'De modo que os peixes que estavam no rio morreram, e o rio cheirou mal, e os egípcios não podiam beber da água do rio; e houve sangue por toda a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 22, 'Mas o mesmo fizeram também os magos do Egito com os seus encantamentos; de maneira que o coração de Faraó se endureceu, e não os ouviu, como o Senhor tinha dito.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 23, 'Virou-se Faraó e entrou em sua casa, e nem ainda a isto tomou a sério.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 24, 'Todos os egípcios, pois, cavaram junto ao rio, para achar água que beber; porquanto não podiam beber da água do rio.', 1, CURRENT_TIMESTAMP, false),
(2, 7, 25, 'Assim se passaram sete dias, depois que o Senhor ferira o rio.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 1, 'Então disse o Senhor a Moisés: Vai a Faraó, e dize-lhe: Assim diz o Senhor: Deixa ir o meu povo, para que me sirva.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 2, 'Mas se recusares deixá-lo ir, eis que ferirei com rãs todos os teus termos.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 3, 'O rio produzirá rãs em abundância, que subirão e virão à tua casa, e ao teu dormitório, e sobre a tua cama, e às casas dos teus servos, e sobre o teu povo, e aos teus fornos, e às tuas amassadeiras.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 4, 'Sim, as rãs subirão sobre ti, e sobre o teu povo, e sobre todos os teus servos.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 5, 'Disse mais o Senhor a Moisés: Dize a Arão: Estende a tua mão com a vara sobre as correntes, e sobre os rios, e sobre as lagoas, e faze subir rãs sobre a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 6, 'Arão, pois, estendeu a mão sobre as águas do Egito, e subiram rãs, que cobriram a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 7, 'Então os magos fizeram o mesmo com os seus encantamentos, e fizeram subir rãs sobre a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 8, 'Chamou, pois, Faraó a Moisés e a Arão, e disse: Rogai ao Senhor que tire as rãs de mim e do meu povo; depois deixarei ir o povo, para que ofereça sacrifícios ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 9, 'Respondeu Moisés a Faraó: Digna-te dizer-me quando é que hei de rogar por ti, e pelos teus servos, e por teu povo, para tirar as rãs de ti, e das tuas casas, de sorte que fiquem somente no rio?.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 10, 'Disse Faraó: Amanhã. E Moisés disse: Seja conforme a tua palavra, para que saibas que ninguém há como o Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 11, 'As rãs, pois, se apartarão de ti, e das tuas casas, e dos teus servos, e do teu povo; ficarão somente no rio.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 12, 'Então saíram Moisés e Arão da presença de Faraó; e Moisés clamou ao Senhor por causa das rãs que tinha trazido sobre Faraó.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 13, 'O Senhor, pois, fez conforme a palavra de Moisés; e as rãs morreram nas casas, nos pátios, e nos campos.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 14, 'E ajuntaram-nas em montes, e a terra, cheirou mal.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 15, 'Mas vendo Faraó que havia descanso, endureceu o seu coração, e não os ouviu, como o Senhor tinha dito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 16, 'Disse mais o Senhor a Moisés: Dize a Arão: Estende a tua vara, e fere o pó da terra, para que se torne em piolhos por toda a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 17, 'E assim fizeram. Arão estendeu a sua mão com a vara, e feriu o pó da terra, e houve piolhos nos homens e nos animais; todo o pó da terra se tornou em piolhos em toda a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 18, 'Também os magos fizeram assim com os seus encantamentos para produzirem piolhos, mas não puderam. E havia piolhos, nos homens e nos animais.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 19, 'Então disseram os magos a Faraó: Isto é o dedo de Deus. No entanto o coração de Faraó se endureceu, e não os ouvia, como o Senhor tinha dito.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 20, 'Disse mais o Senhor a Moisés: levanta-te pela manhã cedo e põe-te diante de Faraó:; eis que ele sairá às águas; e dize-lhe: Assim diz o Senhor: Deixa ir o meu povo, para que me sirva.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 21, 'Porque se não deixares ir o meu povo., eis que enviarei enxames de moscas sobre ti, e sobre os teus servos, e sobre o teu povo, e nas tuas casas; e as casas dos egípcios se encherão destes enxames, bem como a terra em que eles estiverem.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 22, 'Mas naquele dia separarei a terra de Gósem em que o meu povo habita, a fim de que nela não haja enxames de moscas, para que saibas que eu sou o Senhor no meio desta terra.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 23, 'Assim farei distinção entre o meu povo e o teu povo; amanhã se fará este milagre.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 24, 'O Senhor, pois, assim fez. Entraram grandes enxames de moscas na casa de Faraó e nas casas dos seus servos; e em toda parte do Egito a terra foi assolada pelos enxames de moscas.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 25, 'Então chamou Faraó a Moisés e a Arão, e disse: Ide, e oferecei sacrifícios ao vosso Deus nesta terra.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 26, 'Respondeu Moisés: Não convém que assim se faça, porque é abominação aos egípcios o que havemos de oferecer ao Senhor nosso Deus. Sacrificando nós a abominação dos egípcios perante os seus olhos, não nos apedrejarão eles?', 1, CURRENT_TIMESTAMP, false),
(2, 8, 27, 'Havemos de ir caminho de três dias ao deserto, para que ofereçamos sacrifícios ao Senhor nosso Deus, como ele nos ordenar.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 28, 'Então disse Faraó: Eu vos deixarei ir, para que ofereçais sacrifícios ao Senhor vosso Deus no deserto; somente não ireis muito longe; e orai por mim.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 29, 'Respondeu Moisés: Eis que saio da tua presença e orarei ao Senhor, que estes enxames de moscas se apartem amanhã de Faraó, dos seus servos, e do seu povo; somente não torne mais Faraó a proceder dolosamente, não deixando ir o povo para oferecer sacrifícios ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 30, 'Então saiu Moisés da presença de Faraó, e orou ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 31, 'E fez o Senhor conforme a palavra de Moisés, e apartou os enxames de moscas de Faraó, dos seus servos, e do seu povo; não ficou uma sequer.', 1, CURRENT_TIMESTAMP, false),
(2, 8, 32, 'Mas endureceu Faraó ainda esta vez o seu coração, e não deixou ir o povo.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 1, 'Depois o Senhor disse a Moisés: Vai a Faraó e dize-lhe: Assim diz o Senhor, o Deus dos hebreus: Deixa ir o meu povo, para que me sirva.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 2, 'Porque, se recusares deixá-los ir, e ainda os retiveres,', 1, CURRENT_TIMESTAMP, false),
(2, 9, 3, 'eis que a mão do Senhor será sobre teu gado, que está no campo: sobre os cavalos, sobre os jumentos, sobre os camelos, sobre os bois e sobre as ovelhas; haverá uma pestilência muito grave.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 4, 'Mas o Senhor fará distinção entre o gado de Israel e o gado do Egito; e não morrerá nada de tudo o que pertence aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 5, 'E o Senhor assinalou certo tempo, dizendo: Amanhã fará o Senhor isto na terra.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 6, 'Fez, pois, o Senhor isso no dia seguinte; e todo gado dos egípcios morreu; porém do gado dos filhos de Israel não morreu nenhum.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 7, 'E Faraó mandou ver, e eis que do gado dos israelitas não morrera sequer um. Mas o coração de Faraó se obstinou, e não deixou ir o povo.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 8, 'Então disse o Senhor a Moisés e a Arão: Tomai as mãos cheias de cinza do forno, e Moisés a espalhe para o céu diante dos olhos de Faraó;', 1, CURRENT_TIMESTAMP, false),
(2, 9, 9, 'e ela se tornará em pó fino sobre toda a terra do Egito, e haverá tumores que arrebentarão em úlceras nos homens e no gado, por toda a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 10, 'E eles tomaram cinza do forno, e apresentaram-se diante de Faraó; e Moisés a espalhou para o céu, e ela se tomou em tumores que arrebentavam em úlceras nos homens e no gado.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 11, 'Os magos não podiam manter-se diante de Moisés, por causa dos tumores; porque havia tumores nos magos, e em todos os egípcios.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 12, 'Mas o Senhor endureceu o coração de Faraó, e este não os ouviu, como o Senhor tinha dito a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 13, 'Então disse o Senhor a Moisés: Levanta-te pela manhã cedo, põe-te diante de Faraó, e dize-lhe: Assim diz o Senhor, o Deus dos hebreus: Deixa ir o meu povo, para que me sirva;', 1, CURRENT_TIMESTAMP, false),
(2, 9, 14, 'porque desta vez enviarei todas as a minhas pragas sobre o teu coração, e sobre os teus servos, e sobre o teu povo, para que saibas que não há outro como eu em toda a terra.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 15, 'Agora, por pouco, teria eu estendido a mão e ferido a ti e ao teu povo com pestilência, e tu terias sido destruído da terra;', 1, CURRENT_TIMESTAMP, false),
(2, 9, 16, 'mas, na verdade, para isso te hei mantido com vida, para te mostrar o meu poder, e para que o meu nome seja anunciado em toda a terra.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 17, 'Tu ainda te exaltas contra o meu povo, não o deixando ir?', 1, CURRENT_TIMESTAMP, false),
(2, 9, 18, 'Eis que amanhã, por este tempo, s farei chover saraiva tão grave qual nunca houve no Egito, desde o dia em que foi fundado até agora.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 19, 'Agora, pois, manda recolher o teu gado e tudo o que tens no campo; porque sobre todo homem e animal que se acharem no campo, e não se recolherem à casa, cairá a saraiva, e morrerão.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 20, 'Quem dos servos de Faraó temia a o palavra do Senhor, fez Fugir os seus servos e o seu gado para as casas;', 1, CURRENT_TIMESTAMP, false),
(2, 9, 21, 'mas aquele que não se importava com a palavra do Senhor, deixou os seus servos e o seu gado no campo.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 22, 'Então disse o Senhor a Moisés: Estende a tua mão para o céu, para que caia saraiva em toda a terra do Egito, sobre os homens e sobre os animais, e sobre toda a erva do campo na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 23, 'E Moisés estendeu a sua vara para o céu, e o Senhor enviou trovões e saraiva, e fogo desceu à terra; e o Senhor fez chover saraiva sobre a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 24, 'Havia, pois, saraiva misturada com fogo, saraiva tão grave qual nunca houvera em toda a terra do Egito, desde que veio a ser uma nação.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 25, 'E a saraiva feriu, em toda a terra do Egito, tudo quanto havia no campo, tanto homens como animais; feriu também toda erva do campo, e quebrou todas as árvores do campo.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 26, 'Somente na terra de Gósem onde se achavam os filhos de Israel, não houve saraiva.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 27, 'Então Faraó mandou chamar Moisés e Arão, e disse-lhes: Esta vez pequei; o Senhor é justo, mas eu e o meu povo somos a ímpios.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 28, 'Orai ao Senhor; pois já bastam estes trovões da parte de Deus e esta saraiva; eu vos deixarei ir, e não permanecereis mais, aqui.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 29, 'Respondeu-lhe Moisés: Logo que eu tiver saído da cidade estenderei minhas mãos ao Senhor; os trovões cessarão, e não haverá, mais saraiva, para que saibas que a terra é do Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 30, 'Todavia, quanto a ti e aos teus servos, eu sei que ainda não temereis diante do Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 31, 'Ora, o linho e a cevada foram danificados, porque a cevada já estava na espiga, e o linho em flor;', 1, CURRENT_TIMESTAMP, false),
(2, 9, 32, 'mas não foram danificados o trigo e o centeio, porque não estavam crescidos.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 33, 'Saiu, pois, Moisés da cidade, da presença de Faraó, e estendeu as mãos ao Senhor; e cessaram os trovões e a saraiva, e a chuva não caiu mais sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 34, 'Vendo Faraó que a chuva, a saraiva e os trovões tinham cessado, continuou a pecar, e endureceu o seu coração, ele e os seus servos.', 1, CURRENT_TIMESTAMP, false),
(2, 9, 35, 'Assim, o coração de Faraó se endureceu, e não deixou ir os filhos de Israel, como o Senhor tinha dito por Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 1, 'Depois disse o Senhor a Moisés: vai a Faraó; porque tenho endurecido o seu coração, e o coração de seus servos, para manifestar estes meus sinais no meio deles,', 1, CURRENT_TIMESTAMP, false),
(2, 10, 2, 'e para que contes aos teus filhos, e aos filhos de teus filhos, as coisas que fiz no Egito, e os meus sinais que operei entre eles; para que vós saibais que eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 3, 'Foram, pois, Moisés e Arão a Faraó, e disseram-lhe: Assim diz o Senhor, o Deus dos hebreus: Até quando recusarás humilhar-te diante de mim? Deixa ir o meu povo, para que me sirva;', 1, CURRENT_TIMESTAMP, false),
(2, 10, 4, 'mas se tu recusares deixar ir o meu povo, eis que amanhã trarei gafanhotos aos teus termos;', 1, CURRENT_TIMESTAMP, false),
(2, 10, 5, 'e eles cobrirão a face da terra, de sorte que não se poderá ver a terra e comerão o resto do que escapou, o que vos ficou da saraiva; também comerão toda árvore que vos cresce no campo;', 1, CURRENT_TIMESTAMP, false),
(2, 10, 6, 'e encherão as tuas casas, as casas de todos os teus servos e as casas de todos os egípcios, como nunca viram teus pais nem os pais de teus pais, desde o dia em que apareceram na terra até o dia de hoje. E virou-se, e saiu da presença de Faraó.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 7, 'Então os servos de Faraó lhe disseram: Até quando este homem nos há de ser por laço? deixa ir os homens, para que sirvam ao Senhor seu Deus; porventura não sabes ainda que o Egito está destruído?', 1, CURRENT_TIMESTAMP, false),
(2, 10, 8, 'Pelo que Moisés e Arão foram levados outra vez a Faraó, e ele lhes disse: Ide, servi ao Senhor vosso Deus. Mas quais são os que hão de ir?', 1, CURRENT_TIMESTAMP, false),
(2, 10, 9, 'Respondeu-lhe Moisés: Havemos de ir com os nossos jovens e com os nossos velhos; com os nossos filhos e com as nossas filhas, com os nossos rebanhos e com o nosso gado havemos de ir; porque temos de celebrar uma festa ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 10, 'Replicou-lhes Faraó: Seja o Senhor convosco, se eu vos deixar ir a vós e a vossos pequeninos! Olhai, porque há mal diante de vós.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 11, 'Não será assim; agora, ide vós, os homens, e servi ao Senhor, pois isso é o que pedistes: E foram expulsos da presença de Faraó.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 12, 'Então disse o Senhor a Moisés: Quanto aos gafanhotos, estende a tua mão sobre a terra do Egito, para que venham eles sobre a terra do Egito e comam toda erva da terra, tudo o que deixou a saraiva.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 13, 'Então estendeu Moisés sua vara sobre a terra do Egito, e o Senhor trouxe sobre a terra um vento oriental todo aquele dia e toda aquela noite; e, quando amanheceu, o vento oriental trouxe os gafanhotos.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 14, 'Subiram, pois, os gafanhotos sobre toda a terra do Egito e pousaram sobre todos os seus termos; tão numerosos foram, que antes destes nunca houve tantos, nem depois deles haverá.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 15, 'Pois cobriram a face de toda a terra, de modo que a terra se escureceu; e comeram toda a erva da terra e todo o fruto das árvores, que deixara a saraiva; nada verde ficou, nem de árvore nem de erva do campo, por toda a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 16, 'Então Faraó mandou apressadamente chamar Moisés e Arão, e lhes disse: Pequei contra o Senhor vosso Deus, e contra vós.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 17, 'Agora: pois, perdoai-me peço-vos somente esta vez o meu pecado, e orai ao Senhor vosso Deus que tire de mim mais esta morte.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 18, 'Saiu, pois, Moisés da presença de Faraó, e orou ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 19, 'Então o Senhor trouxe um vento ocidental fortíssimo, o qual levantou os gafanhotos e os lançou no Mar Vermelho; não ficou um só gafanhoto em todos os termos do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 20, 'O Senhor, porém, endureceu o coração de Faraó, e este não deixou ir os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 21, 'Então disse o Senhor a Moisés: Estende a mão para o céu, para que haja trevas sobre a terra do Egito, trevas que se possam apalpar.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 22, 'Estendeu, pois, Moisés a mão para o céu, e houve trevas espessas em toda a terra do Egito por três dias.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 23, 'Não se viram uns aos outros, e ninguém se levantou do seu lugar por três dias; mas para todos os filhos de Israel havia luz nas suas habitações.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 24, 'Então mandou Faraó chamar Moisés, e disse: Ide, servi ao Senhor; somente fiquem os vossos rebanhos e o vosso gado; mas vão juntamente convosco os vossos pequeninos.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 25, 'Moisés, porém, disse: Tu também nos tens de dar nas mãos sacrifícios e holocaustos, para que possamos oferecer sacrifícios ao Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 26, 'E também o nosso gado há de ir conosco; nem uma unha ficará; porque dele havemos de tomar para servir ao Senhor nosso Deus; porque não sabemos com que havemos de servir ao Senhor, até que cheguemos lá.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 27, 'O Senhor, porém, endureceu o coração de Faraó, e este não os quis deixar ir:', 1, CURRENT_TIMESTAMP, false),
(2, 10, 28, 'Disse, pois, Faraó a Moisés: Retira-te de mim, guarda-te que não mais vejas o meu rosto; porque no dia em que me vires o rosto morrerás.', 1, CURRENT_TIMESTAMP, false),
(2, 10, 29, 'Respondeu Moisés: Disseste bem; eu nunca mais verei o teu rosto.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 1, 'Disse o Senhor a Moisés: Ainda mais uma praga trarei sobre Faraó, e sobre o Egito; depois ele vos deixará ir daqui; e, deixando vos ir a todos, com efeito vos expulsará daqui.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 2, 'Fala agora aos ouvidos do povo, que cada homem peça ao seu vizinho, e cada mulher à sua vizinha, jóias de prata e jóias de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 3, 'E o Senhor deu ao povo graça aos olhos dos egípcios. Além disso o varão Moisés era mui grande na terra do Egito, aos olhos dos servos de Faraó e aos olhos do povo.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 4, 'Depois disse Moisés a Faraó: Assim diz o Senhor: À meia-noite eu sairei pelo meio do Egito;', 1, CURRENT_TIMESTAMP, false),
(2, 11, 5, 'e todos os primogênitos na terra do Egito morrerão, desde o primogênito de Faraó, que se assenta sobre o seu trono, até o primogênito da serva que está detrás da mó, e todos os primogênitos dos animais.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 6, 'Pelo que haverá grande clamor em toda a terra do Egito, como nunca houve nem haverá jamais.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 7, 'Mas contra os filhos de Israel nem mesmo um cão moverá a sua língua, nem contra homem nem contra animal; para que saibais que o Senhor faz distinção entre os egípcios e os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 8, 'Então todos estes teus servos descerão a mim, e se inclinarão diante de mim, dizendo: Sai tu, e todo o povo que te segue as pisadas. Depois disso eu sairei. E Moisés saiu da presença de Faraó ardendo em ira.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 9, 'Pois o Senhor dissera a Moisés: Faraó não vos ouvirá, para que as minhas maravilhas se multipliquem na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 11, 10, 'E Moisés e Arão fizeram todas estas maravilhas diante de Faraó; mas o Senhor endureceu o coração de Faraó, que não deixou ir da sua terra os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 1, 'Ora, o Senhor falou a Moisés e a Arão na terra do Egito, dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 12, 2, 'Este mês será para vós o princípio dos meses; este vos será o primeiro dos meses do ano.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 3, 'Falai a toda a congregação de Israel, dizendo: Ao décimo dia deste mês tomará cada um para si um cordeiro, segundo as casas dos pais, um cordeiro para cada família.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 4, 'Mas se a família for pequena demais para um cordeiro, tomá-lo-á juntamente com o vizinho mais próximo de sua casa, conforme o número de almas; conforme ao comer de cada um, fareis a conta para o cordeiro.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 5, 'O cordeiro, ou cabrito, será sem defeito, macho de um ano, o qual tomareis das ovelhas ou das cabras,', 1, CURRENT_TIMESTAMP, false),
(2, 12, 6, 'e o guardareis até o décimo quarto dia deste mês; e toda a assembléia da congregação de Israel o matará à tardinha:', 1, CURRENT_TIMESTAMP, false),
(2, 12, 7, 'Tomarão do sangue, e pô-lo-ão em ambos os umbrais e na verga da porta, nas casas em que o comerem.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 8, 'E naquela noite comerão a carne assada ao fogo, com pães ázimos; com ervas amargosas a comerão.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 9, 'Não comereis dele cru, nem cozido em água, mas sim assado ao fogo; a sua cabeça com as suas pernas e com a sua fressura.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 10, 'Nada dele deixareis até pela manhã; mas o que dele ficar até pela manhã, queimá-lo-eis no fogo.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 11, 'Assim pois o comereis: Os vossos lombos cingidos, os vossos sapatos nos pés, e o vosso cajado na mão; e o comereis apressadamente; esta é a páscoa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 12, 'Porque naquela noite passarei pela terra do Egito, e ferirei todos os primogênitos na terra do Egito, tanto dos homens como dos animais; e sobre todos os deuses do Egito executarei juízos; eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 13, 'Mas o sangue vos será por sinal nas casas em que estiverdes; vendo eu o sangue, passarei por cima de vós, e não haverá entre vós praga para vos destruir, quando eu ferir a terra do Egito. :', 1, CURRENT_TIMESTAMP, false),
(2, 12, 14, 'E este dia vos será por memorial, e celebrá-lo-eis por festa ao Senhor; através das vossas gerações o celebrareis por estatuto perpétuo.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 15, 'Por sete dias comereis pães ázimos; logo ao primeiro dia tirareis o fermento das vossas casas, porque qualquer que comer pão levedado, entre o primeiro e o sétimo dia, esse será cortado de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 16, 'E ao primeiro dia haverá uma santa convocação; também ao sétimo dia tereis uma santa convocação; neles não se fará trabalho algum, senão o que diz respeito ao que cada um houver de comer; somente isso poderá ser feito por vós.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 17, 'Guardareis, pois, a festa dos pães ázimos, porque nesse mesmo dia tirei vossos exércitos da terra do Egito; pelo que guardareis este dia através das vossas gerações por estatuto perpétuo.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 18, 'No primeiro mês, aos catorze dias do mês, à tarde, comereis pães ázimos até vinte e um do mês à tarde.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 19, 'Por sete dias não se ache fermento algum nas vossas casas; porque qualquer que comer pão levedado, esse será cortado da congregação de Israel, tanto o peregrino como o natural da terra.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 20, 'Nenhuma coisa levedada comereis; em todas as vossas habitações comereis pães ázimos.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 21, 'Chamou, pois, Moisés todos os anciãos de Israel, e disse-lhes: Ide e tomai-vos cordeiros segundo as vossas famílias, e imolai a páscoa.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 22, 'Então tomareis um molho de hissopo, embebê-lo-eis no sangue que estiver na bacia e marcareis com ele a verga da porta e os dois umbrais; mas nenhum de vós sairá da porta da sua casa até pela manhã.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 23, 'Porque o Senhor passará para ferir aos egípcios; e, ao ver o sangue na verga da porta e em ambos os umbrais, o Senhor passará aquela porta, e não deixará o destruidor entrar em vossas casas para vos ferir.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 24, 'Portanto guardareis isto por estatuto para vós e para vossos filhos, para sempre.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 25, 'Quando, pois, tiverdes entrado na terra que o Senhor vos dará, como tem prometido, guardareis este culto.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 26, 'E quando vossos filhos vos perguntarem: Que quereis dizer com este culto?', 1, CURRENT_TIMESTAMP, false),
(2, 12, 27, 'Respondereis: Este é o sacrifício da páscoa do Senhor, que passou as casas dos filhos de Israel no Egito, quando feriu os egípcios, e livrou as nossas casas. Então o povo inclinou-se e adorou.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 28, 'E foram os filhos de Israel, e fizeram isso; como o Senhor ordenara a Moisés e a Arão, assim fizeram.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 29, 'E aconteceu que à meia-noite o Senhor feriu todos os primogênitos na terra do Egito, desde o primogênito de Faraó, que se assentava em seu trono, até o primogênito do cativo que estava no cárcere, e todos os primogênitos dos animais.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 30, 'E Faraó levantou-se de noite, ele e todos os seus servos, e todos os egípcios; e fez-se grande clamor no Egito, porque não havia casa em que não houvesse um morto.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 31, 'Então Faraó chamou Moisés e Arão de noite, e disse: Levantai-vos, saí do meio do meu povo, tanto vós como os filhos de Israel; e ide servir ao Senhor, como tendes dito.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 32, 'Levai também convosco os vossos rebanhos e o vosso gado, como tendes dito; e ide, e abençoai-me também a mim.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 33, 'E os egípcios apertavam ao povo, e apressando-se por lançá-los da terra; porque diziam: Estamos todos mortos.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 34, 'Ao que o povo tomou a massa, antes que ela levedasse, e as amassadeiras atadas e em seus vestidos, sobre os ombros.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 35, 'Fizeram, pois, os filhos de Israel conforme a palavra de Moisés, e pediram aos egípcios jóias de prata, e jóias de ouro, e vestidos.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 36, 'E o Senhor deu ao povo graça aos olhos dos egípcios, de modo que estes lhe davam o que pedia; e despojaram aos egípcios.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 37, 'Assim viajaram os filhos de Israel de a Ramessés a Sucote, cerca de seiscentos mil homens de pé, sem contar as crianças.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 38, 'Também subiu com eles uma grande mistura de gente; e, em rebanhos e manadas, uma grande quantidade de gado.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 39, 'E cozeram bolos ázimos da massa que levaram do Egito, porque ela não se tinha levedado, porquanto foram lançados do Egito; e não puderam deter-se, nem haviam preparado comida.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 40, 'Ora, o tempo que os filhos de Israel moraram no Egito foi de quatrocentos e trinta anos.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 41, 'E aconteceu que, ao fim de quatrocentos e trinta anos, naquele mesmo dia, todos os exércitos do Senhor saíram da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 42, 'Esta é uma noite que se deve guardar ao Senhor, porque os tirou da terra do Egito; esta é a noite do Senhor, que deve ser guardada por todos os filhos de Israel através das suas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 43, 'Disse mais o Senhor a Moisés e a Arão: Esta é a ordenança da páscoa; nenhum, estrangeiro comerá dela;', 1, CURRENT_TIMESTAMP, false),
(2, 12, 44, 'mas todo escravo comprado por dinheiro, depois que o houveres circuncidado, comerá dela.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 45, 'O forasteiro e o assalariado não comerão dela.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 46, 'Numa só casa se comerá o cordeiro; não levareis daquela carne fora da casa nem lhe quebrareis osso algum.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 47, 'Toda a congregação de Israel a observará.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 48, 'Quando, porém, algum estrangeiro peregrinar entre vós e quiser celebrar a páscoa ao Senhor, circuncidem-se todos os seus varões; então se chegará e a celebrará, e será como o natural da terra; mas nenhum incircunciso comerá dela.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 49, 'Haverá uma mesma lei para o natural e para o estrangeiro que peregrinar entre vós.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 50, 'Assim, pois, fizeram todos os filhos de Israel; como o Senhor ordenara a Moisés e a Arão, assim fizeram.', 1, CURRENT_TIMESTAMP, false),
(2, 12, 51, 'E naquele mesmo dia o Senhor tirou os filhos de Israel da terra do Egito, segundo os seus exércitos.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 1, 'Então falou o Senhor a Moisés, dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 13, 2, 'Santifica-me todo primogênito, todo o que abrir a madre de sua mãe entre os filhos de Israel, assim de homens como de animais; porque meu é.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 3, 'E Moisés disse ao povo: Lembrai-vos deste dia, em que saístes do Egito, da casa da servidão; pois com mão forte o Senhor vos tirou daqui; portanto não se comerá pão levedado.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 4, 'Hoje, no mês de abibe, vós saís.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 5, 'Quando o Senhor te houver introduzido na terra dos cananeus, dos heteus, dos amorreus, dos heveus e dos jebuseus, que ele jurou a teus pais que te daria, terra que mana leite e mel, guardarás este culto neste mês.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 6, 'Sete dias comerás pães ázimos, e ao sétimo dia haverá uma festa ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 7, 'Sete dias se comerão pães ázimos, e o levedado não se verá contigo, nem ainda fermento será visto em todos os teus termos.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 8, 'Naquele dia contarás a teu filho, dizendo: Isto é por causa do que o Senhor me fez, quando eu saí do Egito;', 1, CURRENT_TIMESTAMP, false),
(2, 13, 9, 'e te será por sinal sobre tua mão e por memorial entre teus olhos, para que a lei do Senhor esteja em tua boca; porquanto com mão forte o Senhor te tirou do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 10, 'Portanto guardarás este estatuto a seu tempo, de ano em ano.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 11, 'Também quando o Senhor te houver introduzido na terra dos cananeus, como jurou a ti e a teus pais, quando te houver dado,', 1, CURRENT_TIMESTAMP, false),
(2, 13, 12, 'separarás para o Senhor tudo o que abrir a madre, até mesmo todo primogênito dos teus animais; os machos serão do Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 13, 'Mas todo primogênito de jumenta resgatarás com um cordeiro; e, se o não quiseres resgatar, quebrar-lhe-ás a cerviz:; e todo primogênito do homem entre teus filhos resgatarás.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 14, 'E quando teu filho te perguntar no futuro, dizendo: Que é isto? responder-lhe-ás: O Senhor, com mão forte, nos tirou do Egito, da casa da servidão.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 15, 'Porque sucedeu que, endurecendo-se Faraó, para não nos deixar ir, o Senhor matou todos os primogênitos na terra do Egito, tanto os primogênitos dos homens como os primogênitos dos animais; por isso eu sacrifico ao Senhor todos os primogênitos, sendo machos; mas a todo primogênito de meus filhos eu resgato.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 16, 'E isto será por sinal sobre tua mão, e por frontais entre os teus olhos, porque o Senhor, com mão forte, nos tirou do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 17, 'Ora, quando Faraó deixou ir o povo, Deus não o conduziu pelo caminho da terra dos filisteus, se bem que fosse mais perto; porque Deus disse: Para que porventura o povo não se arrependa, vendo a guerra, e volte para o Egito;', 1, CURRENT_TIMESTAMP, false),
(2, 13, 18, 'mas Deus fez o povo rodear pelo caminho do deserto perto do Mar Vermelho; e os filhos de Israel subiram armados da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 19, 'Moisés levou consigo os ossos de José, porquanto havia este solenemente ajuramentado os filhos de Israel, dizendo: Certamente Deus vos visitará; e vós haveis de levar daqui convosco os meus ossos.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 20, 'Assim partiram de Sucote, e acamparam-se em Etã, à entrada do deserto.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 21, 'E o Senhor ia adiante deles, de dia numa coluna e os dois para os guiar pelo caminho, e de noite numa coluna de fogo para os alumiar, a fim de que caminhassem de dia e de noite.', 1, CURRENT_TIMESTAMP, false),
(2, 13, 22, 'Não desaparecia de diante do povo a coluna de nuvem de dia, nem a coluna de fogo de noite.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 1, 'Disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 14, 2, 'Fala aos filhos de Israel que se voltem e se acampem diante de Pi-Hairote, entre Migdol e o mar, diante de Baal-Zefom; em frente dele assentareis o acampamento junto ao mar.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 3, 'Então Faraó dirá dos filhos de Israel: Eles estão embaraçados na terra, o deserto os encerrou.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 4, 'Eu endurecerei o coração de Faraó, e ele os perseguirá; glorificar-me-ei em Faraó, e em todo o seu exército; e saberão os egípcios que eu sou o Senhor. E eles fizeram assim.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 5, 'Quando, pois, foi anunciado ao rei do Egito que o povo havia fugido, mudou-se o coração de Faraó, e dos seus servos, contra o povo, e disseram: Que é isso que fizemos, permitindo que Israel saísse e deixasse de nos servir?', 1, CURRENT_TIMESTAMP, false),
(2, 14, 6, 'E Faraó aprontou o seu carro, e tomou consigo o seu povo;', 1, CURRENT_TIMESTAMP, false),
(2, 14, 7, 'tomou também seiscentos carros escolhidos e todos os carros do Egito, e capitães sobre todos eles.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 8, 'Porque o Senhor endureceu o coração de Faraó, rei do Egito, e este perseguiu os filhos de Israel; pois os filhos de Israel saíam afoitamente.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 9, 'Os egípcios, com todos os cavalos e carros de Faraó, e os seus cavaleiros e o seu exército, os perseguiram e os alcançaram acampados junto ao mar, perto de Pi-Hairote, diante de Baal-Zefom.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 10, 'Quando Faraó se aproximava, os filhos de Israel levantaram os olhos, e eis que os egípcios marchavam atrás deles; pelo que tiveram muito medo os filhos de Israel e clamaram ao Senhor:', 1, CURRENT_TIMESTAMP, false),
(2, 14, 11, 'e disseram a Moisés: Foi porque não havia sepulcros no Egito que de lá nos tiraste para morrermos neste deserto? Por que nos fizeste isto, tirando-nos do Egito?', 1, CURRENT_TIMESTAMP, false),
(2, 14, 12, 'Não é isto o que te dissemos no Egito: Deixa-nos, que sirvamos aos egípcios? Pois melhor nos fora servir aos egípcios, do que morrermos no deserto.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 13, 'Moisés, porém, disse ao povo: Não temais; estai quietos, e vede o livramento do Senhor, que ele hoje vos fará; porque aos egípcios que hoje vistes, nunca mais tornareis a ver;', 1, CURRENT_TIMESTAMP, false),
(2, 14, 14, 'o Senhor pelejará por vós; e vós vos calareis.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 15, 'Então disse o Senhor a Moisés: Por que clamas a mim? dize aos filhos de Israel que marchem.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 16, 'E tu, levanta a tua vara, e estende a mão sobre o mar e fende-o, para que os filhos de Israel passem pelo meio do mar em seco.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 17, 'Eis que eu endurecerei o coração dos egípcios, e estes entrarão atrás deles; e glorificar-me-ei em Faraó e em todo o seu exército, nos seus carros e nos seus cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 18, 'E os egípcios saberão que eu sou o Senhor, quando me tiver glorificado em Faraó, nos seus carros e nos seus cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 19, 'Então o anjo de Deus, que ia adiante do exército de Israel, se retirou e se pôs atrás deles; também a coluna de nuvem se retirou de diante deles e se pôs atrás,', 1, CURRENT_TIMESTAMP, false),
(2, 14, 20, 'colocando-se entre o campo dos egípcios e o campo dos israelitas; assim havia nuvem e trevas; contudo aquela clareava a noite para Israel; de maneira que em toda a noite não se aproximou um do outro.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 21, 'Então Moisés estendeu a mão sobre o mar; e o Senhor fez retirar o mar por um forte vento oriental toda aquela noite, e fez do mar terra seca, e as águas foram divididas.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 22, 'E os filhos de Israel entraram pelo meio do mar em seco; e as águas foram-lhes qual muro à sua direita e à sua esquerda.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 23, 'E os egípcios os perseguiram, e entraram atrás deles até o meio do mar, com todos os cavalos de Faraó, os seus carros e os seus cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 24, 'Na vigília da manhã, o Senhor, na coluna do fogo e da nuvem, olhou para o campo dos egípcios, e alvoroçou o campo dos egípcios;', 1, CURRENT_TIMESTAMP, false),
(2, 14, 25, 'embaraçou-lhes as rodas dos carros, e fê-los andar dificultosamente; de modo que os egípcios disseram: Fujamos de diante de Israel, porque o Senhor peleja por eles contra os egípcios.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 26, 'Nisso o Senhor disse a Moisés: Estende a mão sobre o mar, para que as águas se tornem sobre os egípcios, sobre os seus carros e sobre os seus cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 27, 'Então Moisés estendeu a mão sobre o mar, e o mar retomou a sua força ao amanhecer, e os egípcios fugiram de encontro a ele; assim o Senhor derribou os egípcios no meio do mar.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 28, 'As águas, tornando, cobriram os carros e os cavaleiros, todo o exército de Faraó, que atrás deles havia entrado no mar; não ficou nem sequer um deles.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 29, 'Mas os filhos de Israel caminharam a pé enxuto pelo meio do mar; as águas foram-lhes qual muro à sua direita e à sua esquerda.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 30, 'Assim o Senhor, naquele dia, salvou Israel da mão dos egípcios; e Israel viu os egípcios mortos na praia do mar.', 1, CURRENT_TIMESTAMP, false),
(2, 14, 31, 'E viu Israel a grande obra que o Senhor operara contra os egípcios; pelo que o povo temeu ao Senhor, e creu no Senhor e em Moisés, seu servo.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 1, 'Então cantaram Moisés e os filhos de Israel este cântico ao Senhor, dizendo: Cantarei ao Senhor, porque gloriosamente triunfou; lançou no mar o cavalo e o seu cavaleiro.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 2, 'O Senhor é a minha força, e o meu cântico; ele se tem tornado a minha salvação; é ele o meu Deus, portanto o louvarei; é o Deus de meu pai, por isso o exaltarei.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 3, 'O Senhor é homem de guerra; Jeová é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 4, 'Lançou no mar os carros de Faraó e o seu exército; os seus escolhidos capitães foram submersos no Mar Vermelho.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 5, 'Os abismos os cobriram; desceram às profundezas como pedra.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 6, 'A tua destra, ó Senhor, é gloriosa em poder; a tua destra, ó Senhor, destroça o inimigo.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 7, 'Na grandeza da tua excelência derrubas os que se levantam contra ti; envias o teu furor, que os devora como restolho.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 8, 'Ao sopro dos teus narizes amontoaram-se as águas, as correntes pararam como montão; os abismos coalharam-se no coração do mar.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 9, 'O inimigo dizia: Perseguirei, alcançarei, repartirei os despojos; deles se satisfará o meu desejo; arrancarei a minha espada, a minha mão os destruirá.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 10, 'Sopraste com o teu vento, e o mar os cobriu; afundaram-se como chumbo em grandes águas.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 11, 'Quem entre os deuses é como tu, ó Senhor? a quem é como tu poderoso em santidade, admirável em louvores, operando maravilhas?', 1, CURRENT_TIMESTAMP, false),
(2, 15, 12, 'Estendeste a mão direita, e a terra os tragou.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 13, 'Na tua beneficência guiaste o povo que remiste; na tua força o conduziste à tua santa habitação.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 14, 'Os povos ouviram e estremeceram; dores apoderaram-se dos a habitantes da Filístia.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 15, 'Então os príncipes de Edom se pasmaram; dos poderosos de Moabe apoderou-se um tremor; derreteram-se todos os habitantes de Canaã.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 16, 'Sobre eles caiu medo, e pavor; pela grandeza do teu braço emudeceram como uma pedra, até que o teu povo passasse, ó Senhor, até que passasse este povo que adquiriste.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 17, 'Tu os introduzirás, e os plantarás no monte da tua herança, no lugar que tu, ó Senhor, aparelhaste para a tua habitação, no santuário, ó Senhor, que as tuas mãos estabeleceram.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 18, 'O Senhor reinará eterna e perpetuamente.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 19, 'Porque os cavalos de Faraó, com os seus carros e com os seus cavaleiros, entraram no mar, e o Senhor fez tornar as águas do mar sobre eles, mas os filhos de Israel passaram em seco pelo meio do mar.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 20, 'Então Miriã, a profetisa, irmã de Arão, tomou na mão um tamboril, e todas as mulheres saíram atrás dela com tamboris, e com danças.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 21, 'E Miriã lhes respondia: Cantai ao Senhor, porque gloriosamente triunfou; lançou no mar o cavalo com o seu cavaleiro.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 22, 'Depois Moisés fez partir a Israel do Mar Vermelho, e saíram para o deserto de Sur; caminharam três dias no deserto, e não acharam água.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 23, 'E chegaram a Mara, mas não podiam beber das suas águas, porque eram amargas; por isso chamou-se o lugar Mara.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 24, 'E o povo murmurou contra Moisés, dizendo: Que havemos de beber?', 1, CURRENT_TIMESTAMP, false),
(2, 15, 25, 'Então clamou Moisés ao Senhor, e o Senhor mostrou-lhe uma árvore, e Moisés lançou-a nas águas, as quais se tornaram doces. Ali Deus lhes deu um estatuto e uma ordenança, e ali os provou,', 1, CURRENT_TIMESTAMP, false),
(2, 15, 26, 'dizendo: Se ouvires atentamente a voz do Senhor teu Deus, e fizeres o que é reto diante de seus olhos, e inclinares os ouvidos aos seus mandamentos, e guardares todos os seus estatutos, sobre ti não enviarei nenhuma das enfermidades que enviei sobre os egípcios; porque eu sou o Senhor que te sara.', 1, CURRENT_TIMESTAMP, false),
(2, 15, 27, 'Então vieram a Elim, onde havia doze fontes de água e setenta palmeiras; e ali, junto das águas, acamparam.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 1, 'Depois partiram de Elim; e veio toda a congregação dos filhos de Israel ao deserto de Sim, que está entre Elim e Sinai, aos quinze dias do segundo mês depois que saíram da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 2, 'E toda a congregação dos filhos de Israel murmurou contra Moisés e contra Arão no deserto.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 3, 'Pois os filhos de Israel lhes disseram: Quem nos dera que tivéssemos morrido pela mão do Senhor na terra do Egito, quando estávamos sentados junto às panelas de carne, quando comíamos pão até fartar! porque nos tendes tirado para este deserto, para matardes de fome a toda esta multidão.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 4, 'Então disse o Senhor a Moisés: Eis que vos farei chover pão do céu; e sairá o povo e colherá diariamente a porção para cada dia, para que eu o prove se anda em minha lei ou não.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 5, 'Mas ao sexto dia prepararão o que colherem; e será o dobro do que colhem cada dia.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 6, 'Disseram, pois, Moisés e Arão a todos os filhos de Israel: tarde sabereis que o Senhor é quem vos tirou da terra do Egito,', 1, CURRENT_TIMESTAMP, false),
(2, 16, 7, 'e amanhã vereis a glória do Senhor, porquanto ele ouviu as vossas murmurações contra o Senhor; e quem somos nós, para que murmureis contra nós?', 1, CURRENT_TIMESTAMP, false),
(2, 16, 8, 'Disse mais Moisés: Isso será quando o Senhor à tarde vos der carne para comer, e pela manhã pão a fartar, porquanto o Senhor ouve as vossas murmurações, com que murmurais contra ele; e quem somos nós? As vossas murmurações não são contra nós, mas sim contra o Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 9, 'Depois disse Moisés a Arão: Dize a toda a congregação dos filhos de Israel: Chegai-vos à presença do Senhor, porque ele ouviu as vossas murmurações.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 10, 'E quando Arão falou a toda a congregação dos filhos de Israel, estes olharam para o deserto, e eis que a glória do Senhor, apareceu na nuvem.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 11, 'Então o Senhor falou a Moisés, dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 16, 12, 'Tenho ouvido as murmurações dos filhos de Israel; dize-lhes: À tardinha comereis carne, e pela manhã vos fartareis de pão; e sabereis que eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 13, 'E aconteceu que à tarde subiram codornizes, e cobriram o arraial; e pela manhã havia uma camada de orvalho ao redor do arraial.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 14, 'Quando desapareceu a camada de orvalho, eis que sobre a superfície do deserto estava uma coisa miúda, semelhante a escamas, coisa miúda como a geada sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 15, 'E, vendo-a os filhos de Israel, disseram uns aos outros: Que é isto? porque não sabiam o que era. Então lhes disse Moisés: Este é o pão que o Senhor vos deu para comer.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 16, 'Isto é o que o Senhor ordenou: Colhei dele cada um conforme o que pode comer; um gômer para cada cabeça, segundo o número de pessoas; cada um tomará para os que se acharem na sua tenda.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 17, 'Assim o fizeram os filhos de Israel; e colheram uns mais e outros menos.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 18, 'Quando, porém, o mediam com o gômer, nada sobejava ao que colhera muito, nem faltava ao que colhera pouco; colhia cada um tanto quanto podia comer.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 19, 'Também disse-lhes Moisés: Ninguém deixe dele para amanhã.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 20, 'Eles, porém, não deram ouvidos a Moisés, antes alguns dentre eles deixaram dele para o dia seguinte; e criou bichos, e cheirava mal; por isso indignou-se Moisés contra eles.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 21, 'Colhiam-no, pois, pela manhã, cada um conforme o que podia comer; porque, vindo o calor do sol, se derretia.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 22, 'Mas ao sexto dia colheram pão em dobro, dois gômeres para cada um; pelo que todos os principais da congregação vieram, e contaram-no a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 23, 'E ele lhes disse: Isto é o que o Senhor tem dito: Amanhã é repouso, sábado santo ao Senhor; o que quiserdes assar ao forno, assai-o, e o que quiserdes cozer em água, cozei-o em água; e tudo o que sobejar, ponde-o de lado para vós, guardando-o para amanhã.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 24, 'Guardaram-no, pois, até o dia seguinte, como Moisés tinha ordenado; e não cheirou mal, nem houve nele bicho algum.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 25, 'Então disse Moisés: Comei-o hoje, porquanto hoje é o sábado do Senhor; hoje não o achareis no campo.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 26, 'Seis dias o colhereis, mas o sétimo dia é o sábado; nele não haverá.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 27, 'Mas aconteceu ao sétimo dia que saíram alguns do povo para o colher, e não o acharam.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 28, 'Então disse o Senhor a Moisés: Até quando recusareis guardar os meus mandamentos e as minhas leis?', 1, CURRENT_TIMESTAMP, false),
(2, 16, 29, 'Vede, visto que o Senhor vos deu o sábado, por isso ele no sexto dia vos dá pão para dois dias; fique cada um no seu lugar, não saia ninguém do seu lugar no sétimo dia.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 30, 'Assim repousou o povo no sétimo dia.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 31, 'A casa de Israel deu-lhe o nome de maná. Era como semente de coentro; era branco, e tinha o sabor de bolos de mel.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 32, 'E disse Moisés: Isto é o que o Senhor ordenou: Dele enchereis um gômer, o qual se guardará para as vossas gerações, para que elas vejam o pão que vos dei a comer no deserto, quando eu vos tirei da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 33, 'Disse também Moisés a Arão: Toma um vaso, mete nele um gômer cheio de maná e põe-no diante do Senhor, a fim de que seja guardado para as vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 34, 'Como o Senhor tinha ordenado a Moisés, assim Arão o pôs diante do testemunho, para ser guardado.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 35, 'Ora, os filhos de Israel comeram o maná quarenta anos, até que chegaram a uma terra habitada; comeram o maná até que chegaram aos termos da terra de Canaã.', 1, CURRENT_TIMESTAMP, false),
(2, 16, 36, 'Um gômer é a décima parte de uma efa.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 1, 'Partiu toda a congregação dos filhos de Israel do deserto de Sim, pelas suas jornadas, segundo o mandamento do Senhor, e acamparam em Refidim; e não havia ali água para o povo beber.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 2, 'Então o povo contendeu com Moisés, dizendo: Dá-nos água para beber. Respondeu-lhes Moisés: Por que contendeis comigo? por que tentais ao Senhor?', 1, CURRENT_TIMESTAMP, false),
(2, 17, 3, 'Mas o povo, tendo sede ali, murmurou contra Moisés, dizendo: Por que nos fizeste subir do Egito, para nos matares de sede, a nós e aos nossos filhos, e ao nosso gado?', 1, CURRENT_TIMESTAMP, false),
(2, 17, 4, 'Pelo que Moisés, clamando ao Senhor, disse: Que hei de fazer a este povo? daqui a pouco me apedrejará.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 5, 'Então disse o Senhor a Moisés: Passa adiante do povo, e leva contigo alguns dos anciãos de Israel; toma na mão a tua vara, com que feriste o rio, e vai-te.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 6, 'Eis que eu estarei ali diante de ti sobre a rocha, em Horebe; ferirás a rocha, e dela sairá água para que o povo possa beber. Assim, pois fez Moisés à vista dos anciãos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 7, 'E deu ao lugar o nome de Massá e Meribá, por causa da contenda dos filhos de Israel, e porque tentaram ao Senhor, dizendo: Está o Senhor no meio de nós, ou não?', 1, CURRENT_TIMESTAMP, false),
(2, 17, 8, 'Então veio Amaleque, e pelejou contra e Israel em Refidim.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 9, 'Pelo que disse Moisés a Josué: Escolhe-nos homens, e sai, peleja contra Amaleque; e amanhã eu estarei sobre o cume do outeiro, tendo na mão a vara de Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 10, 'Fez, pois, Josué como Moisés lhe dissera, e pelejou contra Amaleque; e Moisés, Arão, e Hur subiram ao cume do outeiro.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 11, 'E acontecia que quando Moisés levantava a mão, prevalecia Israel; mas quando ele abaixava a mão, prevalecia Amaleque.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 12, 'As mãos de Moisés, porém, ficaram cansadas; por isso tomaram uma pedra, e a puseram debaixo dele, e ele sentou-se nela; Arão e Hur sustentavam-lhe as mãos, um de um lado e o outro do outro; assim ficaram as suas mãos firmes até o pôr do sol.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 13, 'Assim Josué prostrou a Amaleque e a seu povo, ao fio da espada.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 14, 'Então disse o Senhor a Moisés: Escreve isto para memorial num livro, e relata-o aos ouvidos de Josué; que eu hei de riscar totalmente a memória de Amaleque de debaixo do céu.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 15, 'Pelo que Moisés edificou um altar, ao qual chamou Jeová-Níssi.', 1, CURRENT_TIMESTAMP, false),
(2, 17, 16, 'E disse: Porquanto jurou o Senhor que ele fará guerra contra Amaleque de geração em geração.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 1, 'Ora Jetro, sacerdote de Midiã, sogro de Moisés, ouviu todas as coisas que Deus tinha feito a Moisés e a Israel, seu povo, como o Senhor tinha tirado a Israel do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 2, 'E Jetro, sogro de Moisés, tomou a Zípora, a mulher de Moisés, depois que este lha enviara,', 1, CURRENT_TIMESTAMP, false),
(2, 18, 3, 'e aos seus dois filhos, dos quais um se chamava Gérson; porque disse Moisés: Fui peregrino em terra estrangeira;', 1, CURRENT_TIMESTAMP, false),
(2, 18, 4, 'e o outro se chamava Eliézer; porque disse: O Deus de meu pai foi minha ajuda, e me livrou da espada de Faraó.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 5, 'Veio, pois, Jetro, o sogro de Moisés, com os filhos e a mulher deste, a Moisés, no deserto onde se tinha acampado, junto ao monte de Deus;', 1, CURRENT_TIMESTAMP, false),
(2, 18, 6, 'e disse a Moisés: Eu, teu sogro Jetro, venho a ti, com tua mulher e seus dois filhos com ela.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 7, 'Então saiu Moisés ao encontro de seu sogro, inclinou-se diante dele e o beijou; perguntaram um ao outro como estavam, e entraram na tenda.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 8, 'Depois Moisés contou a seu sogro tudo o que o Senhor tinha feito a Faraó e aos egípcios por amor de Israel, todo o trabalho que lhes sobreviera no caminho, e como o Senhor os livrara.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 9, 'E alegrou-se Jetro por todo o bem que o Senhor tinha feito a Israel, livrando-o da mão dos egípcios,', 1, CURRENT_TIMESTAMP, false),
(2, 18, 10, 'e disse: Bendito seja o Senhor, que vos livrou da mão dos egípcios e da mão de Faraó; que livrou o povo de debaixo da mão dos egípcios.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 11, 'Agora sei que o Senhor é maior que todos os deuses; até naquilo em que se houveram arrogantemente contra o povo.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 12, 'Então Jetro, o sogro de Moisés, tomou holocausto e sacrifícios para Deus; e veio Arão, e todos os anciãos de Israel, para comerem pão com o sogro de Moisés diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 13, 'No dia seguinte assentou-se Moisés para julgar o povo; e o povo estava em pé junto de Moisés desde a manhã até a tarde.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 14, 'Vendo, pois, o sogro de Moisés tudo o que ele fazia ao povo, perguntou: Que é isto que tu fazes ao povo? por que te assentas só, permanecendo todo o povo junto de ti desde a manhã até a tarde?', 1, CURRENT_TIMESTAMP, false),
(2, 18, 15, 'Respondeu Moisés a seu sogro: É por que o povo vem a mim para consultar a Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 16, 'Quando eles têm alguma questão, vêm a mim; e eu julgo entre um e outro e lhes declaro os estatutos de Deus e as suas leis.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 17, 'O sogro de Moisés, porém, lhe replicou: Não é bom o que fazes.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 18, 'certamente desfalecerás, assim tu, como este povo que está contigo; porque isto te é pesado demais; tu só não o podes fazer.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 19, 'Ouve agora a minha voz; eu te aconselharei, e seja Deus contigo: sê tu pelo povo diante de Deus, e leva tu as causas a Deus;', 1, CURRENT_TIMESTAMP, false),
(2, 18, 20, 'ensinar-lhes-ás os estatutos e as leis, e lhes mostrarás o caminho em que devem andar, e a obra que devem fazer.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 21, 'Além disto procurarás dentre todo o povo homens de capacidade, tementes a Deus, homens verazes, que aborreçam a avareza, e os porás sobre eles por chefes de mil, chefes de cem, chefes de cinqüenta e chefes de dez;', 1, CURRENT_TIMESTAMP, false),
(2, 18, 22, 'e julguem eles o povo em todo o tempo. Que a ti tragam toda causa grave, mas toda causa pequena eles mesmos a julguem; assim a ti mesmo te aliviarás da carga, e eles a levarão contigo.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 23, 'Se isto fizeres, e Deus to mandar, poderás então subsistir; assim também todo este povo irá em paz para o seu lugar.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 24, 'E Moisés deu ouvidos à voz de seu sogro, e fez tudo quanto este lhe dissera;', 1, CURRENT_TIMESTAMP, false),
(2, 18, 25, 'e escolheu Moisés homens capazes dentre todo o Israel, e os pôs por cabeças sobre o povo: chefes de mil, chefes de cem, chefes de cinqüenta e chefes de dez.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 26, 'Estes, pois, julgaram o povo em todo o tempo; as causas graves eles as trouxeram a Moisés; mas toda causa pequena, julgaram-na eles mesmos.', 1, CURRENT_TIMESTAMP, false),
(2, 18, 27, 'Então despediu Moisés a seu sogro, o qual se foi para a sua terra.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 1, 'No terceiro mês depois que os filhos de Israel haviam saído da terra do Egito, no mesmo dia chegaram ao deserto de Sinai.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 2, 'Tendo partido de Refidim, entraram no deserto de Sinai, onde se acamparam; Israel, pois, ali acampou-se em frente do monte.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 3, 'Então subiu Moisés a Deus, e do monte o Senhor o chamou, dizendo: Assim falarás à casa de Jacó, e anunciarás aos filhos de Israel:', 1, CURRENT_TIMESTAMP, false),
(2, 19, 4, 'Vós tendes visto o que fiz: aos egípcios, como vos levei sobre asas de águias, e vos trouxe a mim.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 5, 'Agora, pois, se atentamente ouvirdes a minha voz e guardardes o meu pacto, então sereis a minha possessão peculiar dentre todos os povos, porque minha é toda a terra;', 1, CURRENT_TIMESTAMP, false),
(2, 19, 6, 'e vós sereis para mim reino sacerdotal e nação santa. São estas as palavras que falarás aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 7, 'Veio, pois, Moisés e, tendo convocado os anciãos do povo, expôs diante deles todas estas palavras, que o Senhor lhe tinha ordenado.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 8, 'Ao que todo o povo respondeu a uma voz: Tudo o que o Senhor tem falado, faremos. E relatou Moisés ao Senhor as palavras do povo.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 9, 'Então disse o Senhor a Moisés: Eis que eu virei a ti em uma nuvem espessa, para que o povo ouça, quando eu falar contigo, e também para que sempre te creia. Porque Moisés tinha anunciado as palavras do seu povo ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 10, 'Disse mais o Senhor a Moisés: Vai ao povo, e santifica-os hoje e amanhã; lavem eles os seus vestidos,', 1, CURRENT_TIMESTAMP, false),
(2, 19, 11, 'e estejam prontos para o terceiro dia; porquanto no terceiro dia descerá o Senhor diante dos olhos de todo o povo sobre o monte Sinai.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 12, 'Também marcarás limites ao povo em redor, dizendo: Guardai-vos, não subais ao monte, nem toqueis o seu termo; todo aquele que tocar o monte será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 13, 'Mão alguma tocará naquele que o fizer, mas ele será apedrejado ou asseteado; quer seja animal, quer seja homem, não viverá. Quando soar a buzina longamente, subirão eles até o pé do monte.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 14, 'Então Moisés desceu do monte ao povo, e santificou o povo; e lavaram os seus vestidos.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 15, 'E disse ele ao povo: Estai prontos para o terceiro dia; e não vos chegueis a mulher.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 16, 'Ao terceiro dia, ao amanhecer, houve trovões, relâmpagos, e uma nuvem espessa sobre o monte; e ouviu-se um sonido de buzina mui forte, de maneira que todo o povo que estava no arraial estremeceu.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 17, 'E Moisés levou o povo fora do arraial ao encontro de Deus; e puseram-se ao pé do monte.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 18, 'Nisso todo o monte Sinai fumegava, porque o Senhor descera sobre ele em fogo; e a fumaça subiu como a fumaça de uma fornalha, e todo o monte tremia fortemente.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 19, 'E, crescendo o sonido da buzina cada vez mais, Moisés falava, e Deus lhe respondia por uma voz.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 20, 'E, tendo o Senhor descido sobre o monte Sinai, sobre o cume do monte, chamou a Moisés ao cume do monte; e Moisés subiu.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 21, 'Então disse o Senhor a Moisés: Desce, adverte ao povo, para não suceder que traspasse os limites até o Senhor, a fim de ver, e muitos deles pereçam.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 22, 'Ora, santifiquem-se também os sacerdotes, que se chegam ao Senhor, para que o Senhor não se lance sobre eles.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 23, 'Respondeu Moisés ao Senhor: O povo não poderá subir ao monte Sinai, porque tu nos tens advertido, dizendo: Marca limites ao redor do monte, e santifica-o.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 24, 'Ao que lhe disse o Senhor: Vai, desce; depois subirás tu, e Arão contigo; os sacerdotes, porém, e o povo não traspassem os limites para subir ao Senhor, para que ele não se lance sobre eles.', 1, CURRENT_TIMESTAMP, false),
(2, 19, 25, 'Então Moisés desceu ao povo, e disse-lhes isso.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 1, 'Então falou Deus todas estas palavras, dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 20, 2, 'Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 3, 'Não terás outros deuses diante de mim.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 4, 'Não farás para ti imagem esculpida, nem figura alguma do que há em cima no céu, nem em baixo na terra, nem nas águas debaixo da terra.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 5, 'Não te encurvarás diante delas, nem as servirás; porque eu, o Senhor teu Deus, sou Deus zeloso, que visito a iniqüidade dos pais nos filhos até a terceira e quarta geração daqueles que me odeiam.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 6, 'e uso de misericórdia com milhares dos que me amam e guardam os meus mandamentos.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 7, 'Não tomarás o nome do Senhor teu Deus em vão; porque o Senhor não terá por inocente aquele que tomar o seu nome em vão.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 8, 'Lembra-te do dia do sábado, para o santificar.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 9, 'Seis dias trabalharás, e farás todo o teu trabalho;', 1, CURRENT_TIMESTAMP, false),
(2, 20, 10, 'mas o sétimo dia é o sábado do Senhor teu Deus. Nesse dia não farás trabalho algum, nem tu, nem teu filho, nem tua filha, nem o teu servo, nem a tua serva, nem o teu animal, nem o estrangeiro que está dentro das tuas portas.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 11, 'Porque em seis dias fez o Senhor o céu e a terra, o mar e tudo o que neles há, e ao sétimo dia descansou; por isso o Senhor abençoou o dia do sábado, e o santificou.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 12, 'Honra a teu pai e a tua mãe, para que se prolonguem os teus dias na terra que o Senhor teu Deus te dá.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 13, 'Não matarás.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 14, 'Não adulterarás.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 15, 'Não furtarás.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 16, 'Não dirás falso testemunho contra o teu próximo.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 17, 'Não cobiçarás a casa do teu próximo, não cobiçarás a mulher do teu próximo, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma do teu próximo.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 18, 'Ora, todo o povo presenciava os trovões, e os relâmpagos, e o sonido da buzina, e o monte a fumegar; e o povo, vendo isso, estremeceu e pôs-se de longe.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 19, 'E disseram a Moisés: Fala-nos tu mesmo, e ouviremos; mas não fale Deus conosco, para que não morramos.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 20, 'Respondeu Moisés ao povo: Não temais, porque Deus veio para vos provar, e para que o seu temor esteja diante de vós, a fim de que não pequeis.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 21, 'Assim o povo estava em pé de longe; Moisés, porém, se chegou às trevas espessas onde Deus estava.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 22, 'Então disse o Senhor a Moisés: Assim dirás aos filhos de Israel: Vós tendes visto que do céu eu vos falei.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 23, 'Não fareis outros deuses comigo; deuses de prata, ou deuses de ouro, não os fareis para vós.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 24, 'um altar de terra me farás, e sobre ele sacrificarás os teus holocaustos, e as tuas ofertas pacíficas, as tuas ovelhas e os teus bois. Em todo lugar em que eu fizer recordar o meu nome, virei a ti e te abençoarei.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 25, 'E se me fizeres um altar de pedras, não o construirás de pedras lavradas; pois se sobre ele levantares o teu buril, profaná-lo-ás.', 1, CURRENT_TIMESTAMP, false),
(2, 20, 26, 'Também não subirás ao meu altar por degraus, para que não seja ali exposta a tua nudez.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 1, 'Estes são os estatutos que lhes proporás:', 1, CURRENT_TIMESTAMP, false),
(2, 21, 2, 'Se comprares um servo hebreu, seis anos servirá; mas ao sétimo sairá forro, de graça.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 3, 'Se entrar sozinho, sozinho sairá; se tiver mulher, então com ele sairá sua mulher.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 4, 'Se seu senhor lhe houver dado uma mulher e ela lhe houver dado filhos ou filhas, a mulher e os filhos dela serão de seu senhor e ele sairá sozinho.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 5, 'Mas se esse servo expressamente disser: Eu amo a meu senhor, a minha mulher e a meus filhos, não quero sair forro;', 1, CURRENT_TIMESTAMP, false),
(2, 21, 6, 'então seu senhor o levará perante os juízes, e o fará chegar à porta, ou ao umbral da porta, e o seu senhor lhe furará a orelha com uma sovela; e ele o servirá para sempre.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 7, 'Se um homem vender sua filha para ser serva, ela não sairá como saem os servos.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 8, 'Se ela não agradar ao seu senhor, de modo que não se despose com ela, então ele permitirá que seja resgatada; vendê-la a um povo estrangeiro, não o poderá fazer, visto ter usado de dolo para com ela.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 9, 'Mas se a desposar com seu filho, fará com ela conforme o direito de filhas.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 10, 'Se lhe tomar outra, não diminuirá e o mantimento daquela, nem o seu vestido, nem o seu direito conjugal.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 11, 'E se não lhe cumprir estas três obrigações, ela sairá de graça, sem dar dinheiro.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 12, 'Quem ferir a um homem, de modo que este morra, certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 13, 'Se, porém, lhe não armar ciladas, mas Deus lho entregar nas mãos, então te designarei um lugar, para onde ele fugirá.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 14, 'No entanto, se alguém se levantar deliberadamente contra seu próximo para o matar à traição, tirá-lo-ás do meu altar, para que morra.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 15, 'Quem ferir a seu pai, ou a sua mãe, certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 16, 'Quem furtar algum homem, e o vender, ou mesmo se este for achado na sua mão, certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 17, 'Quem amaldiçoar a seu pai ou a sua mãe, certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 18, 'Se dois homens brigarem e um ferir ao outro com pedra ou com o punho, e este não morrer, mas cair na cama,', 1, CURRENT_TIMESTAMP, false),
(2, 21, 19, 'se ele tornar a levantar-se e andar fora sobre o seu bordão, então aquele que o feriu será absolvido; somente lhe pagará o tempo perdido e fará que ele seja completamente curado.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 20, 'Se alguém ferir a seu servo ou a sua serva com pau, e este morrer debaixo da sua mão, certamente será castigado;', 1, CURRENT_TIMESTAMP, false),
(2, 21, 21, 'mas se sobreviver um ou dois dias, não será castigado; porque é dinheiro seu.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 22, 'Se alguns homens brigarem, e um ferir uma mulher grávida, e for causa de que aborte, não resultando, porém, outro dano, este certamente será multado, conforme o que lhe impuser o marido da mulher, e pagará segundo o arbítrio dos juízes;', 1, CURRENT_TIMESTAMP, false),
(2, 21, 23, 'mas se resultar dano, então darás vida por vida,', 1, CURRENT_TIMESTAMP, false),
(2, 21, 24, 'olho por olho, dente por dente, mão por mão, pé por pé,', 1, CURRENT_TIMESTAMP, false),
(2, 21, 25, 'queimadura por queimadura, ferida por ferida, golpe por golpe.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 26, 'Se alguém ferir o olho do seu servo ou o olho da sua serva e o cegar, deixá-lo-á ir forro por causa do olho.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 27, 'Da mesma sorte se tirar o dente do seu servo ou o dente da sua serva, deixá-lo-á ir forro por causa do dente.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 28, 'Se um boi escornear um homem ou uma mulher e este morrer, certamente será apedrejado o boi e a sua carne não se comerá; mas o dono do boi será absolvido.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 29, 'Mas se o boi dantes era escorneador, e o seu dono, tendo sido disso advertido, não o guardou, o boi, matando homem ou mulher, será apedrejado, e também o seu dono será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 30, 'Se lhe for imposto resgate, então dará como redenção da sua vida tudo quanto lhe for imposto;', 1, CURRENT_TIMESTAMP, false),
(2, 21, 31, 'quer tenha o boi escorneado a um filho, quer a uma filha, segundo este julgamento lhe será feito.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 32, 'Se o boi escornear um servo, ou uma serva, dar-se-á trinta siclos de prata ao seu senhor, e o boi será apedrejado.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 33, 'Se alguém descobrir uma cova, ou se alguém cavar uma cova e não a cobrir, e nela cair um boi ou um jumento,', 1, CURRENT_TIMESTAMP, false),
(2, 21, 34, 'o dono da cova dará indenização; pagá-la-á em dinheiro ao dono do animal morto, mas este será seu.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 35, 'Se o boi de alguém ferir de morte o boi do seu próximo, então eles venderão o boi vivo e repartirão entre si o dinheiro da venda, e o morto também dividirão entre si.', 1, CURRENT_TIMESTAMP, false),
(2, 21, 36, 'Ou se for notório que aquele boi dantes era escorneador, e seu dono não o guardou, certamente pagará boi por boi, porém o morto será seu.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 1, 'Se alguém furtar um boi {ou uma ovelha}, e o matar ou vender, por um boi pagará cinco bois, e por uma ovelha quatro ovelhas.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 2, 'Se o ladrão for achado a minar uma casa, e for ferido de modo que morra, o que o feriu não será réu de sangue;', 1, CURRENT_TIMESTAMP, false),
(2, 22, 3, 'mas se o sol houver saído sobre o ladrão, o que o feriu será réu de sangue. O ladrão certamente dará indenização; se nada possuir, será então vendido por seu furto.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 4, 'Se o furto for achado vivo na sua mão, seja boi, ou jumento, ou ovelha, pagará ele o dobro.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 5, 'Se alguém fizer pastar o seu animal num campo ou numa vinha, e se soltar o seu animal e este pastar no campo de outrem, do melhor do seu próprio campo e do melhor da sua própria vinha fará restituição.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 6, 'Se alastrar um fogo e pegar nos espinhos, de modo que sejam destruídas as medas de trigo, ou a seara, ou o campo, aquele que acendeu o fogo certamente dará, indenização.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 7, 'Se alguém entregar ao seu próximo dinheiro, ou objetos, para guardar, e isso for furtado da casa desse homem, o ladrão, se for achado, pagará o dobro.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 8, 'Se o ladrão não for achado, então o dono da casa irá à presença dos juizes para se verificar se não meteu a mão nos bens do seu próximo.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 9, 'Em todo caso de transgressão, seja a respeito de boi, ou de jumento, ou de ovelhas, ou de vestidos, ou de qualquer coisa perdida de que alguém disser que é sua, a causa de ambas as partes será levada perante os juízes; aquele a quem os juízes condenarem pagará o dobro ao seu próximo.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 10, 'Se alguém entregar a seu próximo para guardar um jumento, ou boi, ou ovelha, ou outro qualquer animal, e este morrer, ou for aleijado, ou arrebatado, ninguém o vendo,', 1, CURRENT_TIMESTAMP, false),
(2, 22, 11, 'então haverá o juramento do Senhor entre ambos, para ver se o guardador não meteu a mão nos bens do seu próximo; e o dono aceitará o juramento, e o outro não fará restituição.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 12, 'Se, porém, o animal lhe tiver sido furtado, fará restituirão ao seu dono.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 13, 'Se tiver sido dilacerado, trá-lo-á em testemunho disso; não dará indenização pelo dilacerado.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 14, 'Se alguém pedir emprestado a seu próximo algum animal, e este for danificado ou morrer, não estando presente o seu dono, certamente dará indenização;', 1, CURRENT_TIMESTAMP, false),
(2, 22, 15, 'se o dono estiver presente, o outro não dará indenização; se tiver sido alugado, o aluguel responderá por qualquer dano.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 16, 'Se alguém seduzir uma virgem que não for desposada, e se deitar com ela, certamente pagará por ela o dote e a terá por mulher.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 17, 'Se o pai dela inteiramente recusar dar-lha, pagará ele em dinheiro o que for o dote das virgens.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 18, 'Não permitirás que viva uma feiticeira.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 19, 'Todo aquele que se deitar com animal, certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 20, 'Quem sacrificar a qualquer deus, a não ser tão-somente ao Senhor, será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 21, 'Ao estrangeiro não maltratarás, nem o oprimirás; pois vós fostes estrangeiros na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 22, 'A nenhuma viúva nem órfão afligireis.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 23, 'Se de algum modo os afligirdes, e eles clamarem a mim, eu certamente ouvirei o seu clamor;', 1, CURRENT_TIMESTAMP, false),
(2, 22, 24, 'e a minha ira se acenderá, e vos matarei à espada; vossas mulheres ficarão viúvas, e vossos filhos órfãos.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 25, 'Se emprestares dinheiro ao meu povo, ao pobre que está contigo, não te haverás com ele como credor; não lhe imporás juros.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 26, 'Ainda que chegues a tomar em penhor o vestido do teu próximo, lho restituirás antes do pôr do sol;', 1, CURRENT_TIMESTAMP, false),
(2, 22, 27, 'porque é a única cobertura que tem; é o vestido da sua pele; em que se deitaria ele? Quando pois clamar a mim, eu o ouvirei, porque sou misericordioso.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 28, 'Aos juízes não maldirás, nem amaldiçoarás ao governador do teu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 29, 'Não tardarás em trazer ofertas da tua ceifa e dos teus lagares. O primogênito de teus filhos me darás.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 30, 'Assim farás com os teus bois e com as tuas ovelhas; sete dias ficará a cria com a mãe; ao oitavo dia ma darás.', 1, CURRENT_TIMESTAMP, false),
(2, 22, 31, 'Ser-me-eis homens santos; portanto não comereis carne que por feras tenha sido despedaçada no campo; aos cães a lançareis.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 1, 'Não levantarás falso boato, e não pactuarás com o ímpio, para seres testemunha injusta.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 2, 'Não seguirás a multidão para fazeres o mal; nem numa demanda darás testemunho, acompanhando a maioria, para perverteres a justiça;', 1, CURRENT_TIMESTAMP, false),
(2, 23, 3, 'nem mesmo ao pobre favorecerás na sua demanda.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 4, 'Se encontrares desgarrado o boi do teu inimigo, ou o seu jumento, sem falta lho reconduzirás.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 5, 'Se vires deitado debaixo da sua carga o jumento daquele que te odeia, não passarás adiante; certamente o ajudarás a levantá-lo.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 6, 'Não perverterás o direito do teu pobre na sua demanda.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 7, 'Guarda-te de acusares falsamente, e não matarás o inocente e justo; porque não justificarei o ímpio.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 8, 'Também não aceitarás peita, porque a peita cega os que têm vista, e perverte as palavras dos justos.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 9, 'Outrossim, não oprimirás o estrangeiro; pois vós conheceis o coração do estrangeiro, porque fostes estrangeiros na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 10, 'Seis anos semearás tua terra, e recolherás os seus frutos;', 1, CURRENT_TIMESTAMP, false),
(2, 23, 11, 'mas no sétimo ano a deixarás descansar e ficar em pousio, para que os pobres do teu povo possam comer, e do que estes deixarem comam os animais do campo. Assim farás com a tua vinha e com o teu olival.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 12, 'Seis dias farás os teus trabalhos, mas ao sétimo dia descansarás; para que descanse o teu boi e o teu jumento, e para que tome alento o filho da tua escrava e o estrangeiro.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 13, 'Em tudo o que vos tenho dito, andai apercebidos. Do nome de outros deuses nem fareis menção; nunca se ouça da vossa boca o nome deles.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 14, 'Três vezes no ano me celebrarás festa:', 1, CURRENT_TIMESTAMP, false),
(2, 23, 15, 'A festa dos pães ázimos guardarás: sete dias comerás pães ázimos como te ordenei, ao tempo apontado no mês de abibe, porque nele saíste do Egito; e ninguém apareça perante mim de mãos vazias;', 1, CURRENT_TIMESTAMP, false),
(2, 23, 16, 'também guardarás a festa da sega, a das primícias do teu trabalho, que houveres semeado no campo; igualmente guardarás a festa da colheita à saída do ano, quando tiveres colhido do campo os frutos do teu trabalho.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 17, 'Três vezes no ano todos os teus homens aparecerão diante do Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 18, 'Não oferecerás o sangue do meu sacrifício com pão levedado, nem ficará da noite para a manhã a gordura da minha festa.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 19, 'As primícias dos primeiros frutos da tua terra trarás à casa do Senhor teu Deus. Não cozerás o cabrito no leite de sua mãe.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 20, 'Eis que eu envio um anjo adiante de ti, para guardar-te pelo caminho, e conduzir-te ao lugar que te tenho preparado.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 21, 'Anda apercebido diante dele, e ouve a sua voz; não sejas rebelde contra ele, porque não perdoará a tua rebeldia; pois nele está o meu nome.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 22, 'Mas se, na verdade, ouvires a sua voz, e fizeres tudo o que eu disser, então serei inimigo dos teus inimigos, e adversário dos teus adversários.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 23, 'Porque o meu anjo irá adiante de ti, e te introduzirá na terra dos amorreus, dos heteus, dos perizeus, dos cananeus, dos heveus e dos jebuseus; e eu os aniquilarei.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 24, 'Não te inclinarás diante dos seus deuses, nem os servirás, nem farás conforme as suas obras; Antes os derrubarás totalmente, e quebrarás de todo as suas colunas.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 25, 'Servireis, pois, ao Senhor vosso Deus, e ele abençoará o vosso pão e a vossa água; e eu tirarei do meio de vós as enfermidades.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 26, 'Na tua terra não haverá mulher que aborte, nem estéril; o número dos teus dias completarei.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 27, 'Enviarei o meu terror adiante de ti, pondo em confusão todo povo em cujas terras entrares, e farei que todos os teus inimigos te voltem as costas.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 28, 'Também enviarei na tua frente vespas, que expulsarão de diante de ti os heveus, os cananeus e os heteus.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 29, 'Não os expulsarei num só ano, para que a terra não se torne em deserto, e as feras do campo não se multipliquem contra ti.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 30, 'Pouco a pouco os lançarei de diante de ti, até que te multipliques e possuas a terra por herança.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 31, 'E fixarei os teus limites desde o Mar Vermelho até o mar dos filisteus, e desde o deserto até o rio; porque hei de entregar nas tuas mãos os moradores da terra, e tu os expulsarás de diante de ti.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 32, 'Não farás pacto algum com eles, nem com os seus deuses.', 1, CURRENT_TIMESTAMP, false),
(2, 23, 33, 'Não habitarão na tua terra, para que não te façam pecar contra mim; pois se servires os seus deuses, certamente isso te será um laço.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 1, 'Depois disse Deus a Moisés: Subi ao Senhor, tu e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel, e adorai de longe.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 2, 'Só Moisés se chegará ao Senhor; os, outros não se chegarão; nem o povo subirá com ele.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 3, 'Veio, pois, Moisés e relatou ao povo todas as palavras do Senhor e todos os estatutos; então todo o povo respondeu a uma voz: Tudo o que o Senhor tem falado faremos.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 4, 'Então Moisés escreveu todas as palavras do Senhor e, tendo-se levantado de manhã cedo, edificou um altar ao pé do monte, e doze colunas, segundo as doze tribos de Israel,', 1, CURRENT_TIMESTAMP, false),
(2, 24, 5, 'e enviou certos mancebos dos filhos de Israel, os quais ofereceram holocaustos, e sacrificaram ao Senhor sacrifícios pacíficos, de bois.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 6, 'E Moisés tomou a metade do sangue, e a pôs em bacias; e a outra metade do sangue espargiu sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 7, 'Também tomou o livro do pacto e o leu perante o povo; e o povo disse: Tudo o que o Senhor tem falado faremos, e obedeceremos.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 8, 'Então tomou Moisés aquele sangue, e espargiu-o sobre o povo e disse: Eis aqui o sangue do pacto que o Senhor tem feito convosco no tocante a todas estas coisas.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 9, 'Então subiram Moisés e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel,', 1, CURRENT_TIMESTAMP, false),
(2, 24, 10, 'e viram o Deus de Israel, e debaixo de seus pés havia como que uma calçada de pedra de safira, que parecia com o próprio céu na sua pureza.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 11, 'Deus, porém, não estendeu a sua mão contra os nobres dos filhos de Israel; eles viram a Deus, e comeram e beberam.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 12, 'Depois disse o Senhor a Moisés: Sobe a mim ao monte, e espera ali; e dar-te-ei tábuas de pedra, e a lei, e os mandamentos que tenho escrito, para lhos ensinares.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 13, 'E levantando-se Moisés com Josué, seu servidor, subiu ao monte de Deus,', 1, CURRENT_TIMESTAMP, false),
(2, 24, 14, 'tendo dito aos anciãos: Esperai-nos aqui, até que tornemos a vós; eis que Arão e Hur ficam convosco; quem tiver alguma questão, se chegará a eles.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 15, 'E tendo Moisés subido ao monte, a nuvem cobriu o monte.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 16, 'Também a glória do Senhor repousou sobre o monte Sinai, e a nuvem o cobriu por seis dias; e ao sétimo dia, do meio da nuvem, Deus chamou a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 17, 'Ora, a aparência da glória do Senhor era como um fogo consumidor no cume do monte, aos olhos dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 24, 18, 'Moisés, porém, entrou no meio da nuvem, depois que subiu ao monte; e Moisés esteve no monte quarenta dias e quarenta noites.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 1, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 25, 2, 'Fala aos filhos de Israel que me tragam uma oferta alçada; de todo homem cujo coração se mover voluntariamente, dele tomareis a minha oferta alçada.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 3, 'E esta é a oferta alçada que tomareis deles: ouro, prata, bronze,', 1, CURRENT_TIMESTAMP, false),
(2, 25, 4, 'estofo azul, púrpura, carmesim, linho fino, pêlos de cabras,', 1, CURRENT_TIMESTAMP, false),
(2, 25, 5, 'peles de carneiros tintas de vermelho, peles de golfinhos, madeira de acácia,', 1, CURRENT_TIMESTAMP, false),
(2, 25, 6, 'azeite para a luz, especiarias para o óleo da unção e para o incenso aromático,', 1, CURRENT_TIMESTAMP, false),
(2, 25, 7, 'pedras de ônix, e pedras de engaste para o éfode e para o peitoral.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 8, 'E me farão um santuário, para que eu habite no meio deles.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 9, 'Conforme a tudo o que eu te mostrar para modelo do tabernáculo, e para modelo de todos os seus móveis, assim mesmo o fareis.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 10, 'Também farão uma arca de madeira ,de acácia; o seu comprimento será de dois côvados e meio, e a sua largura de um côvado e meio, e de um côvado e meio a sua altura.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 11, 'E cobri-la-ás de ouro puro, por dentro e por fora a cobrirás; e farás sobre ela uma moldura de ouro ao redor;', 1, CURRENT_TIMESTAMP, false),
(2, 25, 12, 'e fundirás para ela quatro argolas de ouro, que porás nos quatro cantos dela; duas argolas de um lado e duas do outro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 13, 'Também farás varais de madeira de acácia, que cobrirás de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 14, 'Meterás os varais nas argolas, aos lados da arca, para se levar por eles a arca.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 15, 'Os varais permanecerão nas argolas da arca; não serão tirados dela.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 16, 'E porás na arca o testemunho, que eu te darei.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 17, 'Igualmente farás um propiciatório, de ouro puro; o seu comprimento será de dois côvados e meio, e a sua largura de um côvado e meio.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 18, 'Farás também dois querubins de ouro; de ouro batido os farás, nas duas extremidades do propiciatório.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 19, 'Farás um querubim numa extremidade e o outro querubim na outra extremidade; de uma só peça com o propiciatório fareis os querubins nas duas extremidades dele.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 20, 'Os querubins estenderão as suas asas por cima do propiciatório, cobrindo-o com as asas, tendo as faces voltadas um para o outro; as faces dos querubins estarão voltadas para o propiciatório.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 21, 'E porás o propiciatório em cima da arca; e dentro da arca porás o testemunho que eu te darei.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 22, 'E ali virei a ti, e de cima do propiciatório, do meio dos dois querubins que estão sobre a arca do testemunho, falarei contigo a respeito de tudo o que eu te ordenar no tocante aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 23, 'Também farás uma mesa de madeira de acácia; o seu comprimento será de dois côvados, a sua largura de um côvado e a sua altura de um côvado e meio;', 1, CURRENT_TIMESTAMP, false),
(2, 25, 24, 'cobri-la-ás de ouro puro, e lhe farás uma moldura de ouro ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 25, 'Também lhe farás ao redor uma guarnição de quatro dedos de largura, e ao redor na guarnição farás uma moldura de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 26, 'Também lhe farás quatro argolas de ouro, e porás as argolas nos quatro cantos, que estarão sobre os quatro pés.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 27, 'Junto da guarnição estarão as argolas, como lugares para os varais, para se levar a mesa.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 28, 'Farás, pois, estes varais de madeira de acácia, e os cobrirás de ouro; e levar-se-á por eles a mesa.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 29, 'Também farás os seus pratos, as suas colheres, os seus cântaros e as suas tigelas com que serão oferecidas as libações; de ouro puro os farás.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 30, 'E sobre a mesa porás os pães da o proposição perante mim para sempre.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 31, 'Também farás um candelabro de ouro puro; de ouro batido se fará o candelabro, tanto o seu pedestal como a sua haste; os seus copos, os seus cálices e as suas corolas formarão com ele uma só peça.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 32, 'E de seus lados sairão seis braços: três de um lado, e três do outro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 33, 'Em um braço haverá três copos a modo de flores de amêndoa, com cálice e corola; também no outro braço três copos a modo de flores de amêndoa, com cálice e corola; assim se farão os seis braços que saem do candelabro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 34, 'Mas na haste central haverá quatro copos a modo de flores de amêndoa, com os seus cálices e as suas corolas,', 1, CURRENT_TIMESTAMP, false),
(2, 25, 35, 'e um cálice debaixo de dois braços, formando com a haste uma só peça; outro cálice debaixo de dois outros braços, de uma só peça com a haste; e ainda outro cálice debaixo de dois outros braços, de uma só peça com a haste; assim será para os seis braços que saem do candelabro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 36, 'Os seus cálices e os seus braços formarão uma só peça com a haste; o todo será de obra batida de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 37, 'Também lhe farás sete lâmpadas, as quais se acenderão para alumiar defronte dele.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 38, 'Os seus espevitadores e os seus cinzeiros serão de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 39, 'De um talento de ouro puro se fará o candelabro, com todos estes utensílios.', 1, CURRENT_TIMESTAMP, false),
(2, 25, 40, 'Atenta, pois, que os faças conforme o seu modelo, que te foi mostrado no monte.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 1, 'O tabernáculo farás de dez cortinas de linho fino torcido, e de estofo azul, púrpura, e carmesim; com querubins as farás, obra de artífice.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 2, 'O comprimento de cada cortina será de vinte e oito côvados, e a largura de quatro côvados; todas as cortinas serão da mesma medida.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 3, 'Cinco cortinas serão enlaçadas, cada uma à outra; e as outras cinco serão enlaçadas da mesma maneira.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 4, 'Farás laçadas de estofo azul na orla da última cortina do primeiro grupo; assim também farás na orla da primeira cortina do segundo grupo;', 1, CURRENT_TIMESTAMP, false),
(2, 26, 5, 'a saber, cinqüenta laçadas na orla de uma cortina, e cinqüenta laçadas na orla da outra; as laçadas serão contrapostas uma à outra.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 6, 'Farás cinqüenta colchetes de ouro, e prenderás com eles as cortinas, uma à outra; assim o tabernáculo virá a ser um todo.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 7, 'Farás também cortinas de pêlos de cabras para servirem de tenda sobre o tabernáculo; onze destas cortinas farás.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 8, 'O comprimento de cada cortina será de trinta côvados, e a largura de cada cortina de quatro côvados; as onze cortinas serão da mesma medida.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 9, 'E ajuntarás cinco cortinas em um grupo, e as outras seis cortinas em outro grupo; e dobrarás a sexta cortina na frente da tenda.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 10, 'E farás cinqüenta laçadas na orla da última cortina do primeiro grupo, e outras cinqüenta laçadas na orla da primeira cortina do segundo grupo.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 11, 'Farás também cinqüenta colchetes de bronze, e meterás os colchetes nas laçadas, e assim ajuntarás a tenda, para que venha a ser um todo.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 12, 'E o resto que sobejar das cortinas da tenda, a saber, a meia cortina que sobejar, penderá aos fundos do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 13, 'E o côvado que sobejar de um lado e de outro no comprimento das cortinas da tenda, penderá de um e de outro lado do tabernáculo, para cobri-lo.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 14, 'Farás também para a tenda uma coberta de peles de carneiros, tintas de vermelho, e por cima desta uma coberta de peles de golfinhos.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 15, 'Farás também as tábuas para o tabernáculo de madeira de acácia, as quais serão colocadas verticalmente.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 16, 'O comprimento de cada tábua será de dez côvados, e a sua largura de um côvado e meio.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 17, 'Duas couceiras terá cada tábua, unidas uma à outra por travessas; assim farás com todas as tábuas do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 18, 'Ao fazeres as tábuas para o tabernáculo, farás vinte delas para o lado meridional.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 19, 'Farás também quarenta bases de prata debaixo das vinte tábuas; duas bases debaixo de uma tábua, para as suas duas couceiras, e duas bases debaixo de outra, para as duas couceiras dela.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 20, 'Também para o outro lado do tabernáculo, o que dá para o norte, farás vinte tábuas,', 1, CURRENT_TIMESTAMP, false),
(2, 26, 21, 'com as suas quarenta bases de prata; duas bases debaixo de uma tábua e duas debaixo de outra.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 22, 'E para o lado posterior do tabernáculo, o que dá para o ocidente, farás seis tábuas.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 23, 'Farás também duas tábuas para os cantos do tabernáculo no lado posterior.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 24, 'Por baixo serão duplas, do mesmo modo se estendendo inteiras até a primeira argola em cima; assim se fará com as duas tábuas; elas serão para os dois cantos.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 25, 'Haverá oito tábuas com as suas dezesseis bases de prata: duas bases debaixo de uma tábua e duas debaixo de outra.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 26, 'Farás também travessões de madeira de acácia; cinco para as tábuas de um lado do tabernáculo,', 1, CURRENT_TIMESTAMP, false),
(2, 26, 27, 'e cinco para as tábuas do outro lado do tabernáculo, bem como o azeite para a luz, especiarias para o óleo da unção e para o para o ocidente.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 28, 'O travessão central passará ao meio das tábuas, de uma extremidade à outra.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 29, 'E cobrirás de ouro as tábuas, e de ouro farás as suas argolas, como lugares para os travessões; também os travessões cobrirás de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 30, 'Então levantarás o tabernáculo conforme o modelo que te foi mostrado no monte.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 31, 'Farás também um véu de azul, púrpura, carmesim, e linho fino torcido; com querubins, obra de artífice, se fará;', 1, CURRENT_TIMESTAMP, false),
(2, 26, 32, 'e o suspenderás sobre quatro colunas de madeira de acácia, cobertas de ouro; seus colchetes serão de ouro, sobre quatro bases de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 33, 'Pendurarás o véu debaixo dos colchetes, e levarás para dentro do véu a arca do testemunho; este véu vos fará separação entre o lugar santo e o santo dos santos.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 34, 'Porás o propiciatório sobre a arca do testemunho no santo dos santos;', 1, CURRENT_TIMESTAMP, false),
(2, 26, 35, 'colocarás a mesa fora do véu, e o candelabro defronte da mesa, para o lado sul do tabernáculo; e porás a mesa para o lado norte.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 36, 'Farás também para a porta da tenda um reposteiro de azul, púrpura, carmesim: e linho fino torcido, obra de bordador.', 1, CURRENT_TIMESTAMP, false),
(2, 26, 37, 'E para o reposteiro farás cinco colunas de madeira de acácia, cobrindo-as de ouro {os seus colchetes também serão de ouro}, e para elas fundirás cinco bases de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 1, 'Farás também o altar de madeira de acácia; de cinco côvados será o comprimento, de cinco côvados a largura {será quadrado o altar}, e de três côvados a altura.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 2, 'E farás as suas pontas nos seus quatro cantos; as suas pontas formarão uma só peça com o altar; e o cobrirás de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 3, 'Far-lhe-ás também os cinzeiros, para recolher a sua cinza, e as pás, e as bacias, e os garfos e os braseiros; todos os seus utensílios farás de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 4, 'Far-lhe-ás também um crivo de bronze em forma de rede, e farás para esta rede quatro argolas de bronze nos seus quatro cantos,', 1, CURRENT_TIMESTAMP, false),
(2, 27, 5, 'e a porás em baixo da borda em volta do altar, de maneira que a rede chegue até o meio do altar.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 6, 'Farás também varais para o altar, varais de madeira de acácia, e os cobrirás de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 7, 'Os varais serão metidos nas argolas, e estarão de um e de outro lado do altar, quando for levado.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 8, 'Ôco, de tábuas, o farás; como se te mostrou no monte, assim o farão.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 9, 'Farás também o átrio do tabernáculo. No lado que dá para o sul o átrio terá cortinas de linho fino torcido, de cem côvados de comprimento.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 10, 'As suas colunas serão vinte, e vinte as suas bases, todas de bronze; os colchetes das colunas e as suas faixas serão de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 11, 'Assim também ao longo do lado do norte haverá cortinas de cem côvados de comprimento, e serão vinte as suas colunas e vinte as bases destas, todas de bronze; os colchetes das colunas e as suas faixas serão de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 12, 'E na largura do átrio do lado do ocidente haverá cortinas de cinqüenta côvados; serão dez as suas colunas, e dez as bases destas.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 13, 'Semelhantemente a largura do átrio do lado que dá para o nascente será de cinqüenta côvados.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 14, 'As cortinas para um lado da porta serão de quinze côvados; três serão as suas colunas, e três as bases destas.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 15, 'E de quinze côvados serão as cortinas para o outro lado; as suas colunas serão três, e três as bases destas.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 16, 'Também à porta do átrio haverá um reposteiro de vinte côvados, de azul, púrpura, carmesim, e linho fino torcido, obra de bordador; as suas colunas serão quatro, e quatro as bases destas.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 17, 'Todas as colunas do átrio ao redor serão cingidas de faixas de prata; os seus colchetes serão de prata, porém as suas bases de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 18, 'O comprimento do átrio será de cem côvados, e a largura, por toda a extensão, de cinqüenta, e a altura de cinco côvados; as cortinas serão de linho fino torcido; e as bases das colunas de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 19, 'Todos os utensílios do tabernáculo em todo o seu serviço, e todas as suas estacas, e todas as estacas do átrio, serão de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 20, 'Ordenarás aos filhos de Israel que te tragam azeite puro de oliveiras, batido, para o candeeiro, para manter uma lâmpada acesa continuamente.', 1, CURRENT_TIMESTAMP, false),
(2, 27, 21, 'Na tenda da revelação, fora do véu que está diante do testemunho, Arão e seus filhos a conservarão em ordem, desde a tarde até pela manhã, perante o Senhor; este será um estatuto perpétuo para os filhos de Israel pelas suas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 1, 'Depois farás chegar a ti teu irmão Arão, e seus filhos com ele, dentre os filhos de Israel, para me administrarem o ofício sacerdotal; a saber: Arão, Nadabe e Abiú, Eleazar e Itamar, os filhos de Arão.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 2, 'Farás vestes sagradas para Arão, teu irmão, para glória e ornamento.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 3, 'Falarás a todos os homens hábeis, a quem eu tenha enchido do espírito de sabedoria, que façam as vestes de Arão para santificá-lo, a fim de que me administre o ofício sacerdotal.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 4, 'Estas pois são as vestes que farão: um peitoral, um éfode, um manto, uma túnica bordada, uma mitra e um cinto; farão, pois, as vestes sagradas para Arão, teu irmão, e para seus filhos, a fim de me administrarem o ofício sacerdotal.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 5, 'E receberão o ouro, o azul, a púrpura, o carmesim e o linho fino,', 1, CURRENT_TIMESTAMP, false),
(2, 28, 6, 'e farão o éfode de ouro, azul, púrpura, carmesim e linho fino torcido, obra de desenhista.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 7, 'Terá duas ombreiras, que se unam às suas duas pontas, para que seja unido.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 8, 'E o cinto de obra esmerada do éfode, que estará sobre ele, formando com ele uma só peça, será de obra semelhante de ouro, azul, púrpura, carmesim e linho fino torcido.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 9, 'E tomarás duas pedras de berilo, e gravarás nelas os nomes dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 10, 'Seis dos seus nomes numa pedra, e os seis nomes restantes na outra pedra, segundo a ordem do seu nascimento.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 11, 'Conforme a obra de lapidário, como a gravura de um selo, gravarás as duas pedras, com os nomes dos filhos de Israel; guarnecidas de engastes de ouro as farás.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 12, 'E porás as duas pedras nas ombreiras do éfode, para servirem de pedras de memorial para os filhos de Israel; assim sobre um e outro ombro levará Arão diante do Senhor os seus nomes como memorial.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 13, 'Farás também engastes de ouro,', 1, CURRENT_TIMESTAMP, false),
(2, 28, 14, 'e duas cadeiazinhas de ouro puro; como cordas as farás, de obra trançada; e aos engastes fixarás as cadeiazinhas de obra trançada.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 15, 'Farás também o peitoral do juízo, obra de artífice; conforme a obra do éfode o farás; de ouro, de azul, de púrpura, de carmesim, e de linho fino torcido o farás.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 16, 'Quadrado e duplo, será de um palmo o seu comprimento, e de um palmo a sua largura.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 17, 'E o encherás de pedras de engaste, em quatro fileiras: a primeira será de uma cornalina, um topázio e uma esmeralda;', 1, CURRENT_TIMESTAMP, false),
(2, 28, 18, 'a segunda fileira será de uma granada, uma safira e um ônix;', 1, CURRENT_TIMESTAMP, false),
(2, 28, 19, 'a terceira fileira será de um jacinto, uma ágata e uma ametista;', 1, CURRENT_TIMESTAMP, false),
(2, 28, 20, 'e a quarta fileira será de uma crisólita, um berilo e um jaspe; elas serão guarnecidas de ouro nos seus engastes.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 21, 'Serão, pois, as pedras segundo os nomes dos filhos de Israel, doze segundo os seus nomes; serão como a gravura de um selo, cada uma com o seu nome, para as doze tribos.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 22, 'Também farás sobre o peitoral cadeiazinhas como cordas, obra de trança, de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 23, 'Igualmente sobre o peitoral farás duas argolas de ouro, e porás as duas argolas nas duas extremidades do peitoral.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 24, 'Então meterás as duas cadeiazinhas de ouro, de obra trançada, nas duas argolas nas extremidades do peitoral;', 1, CURRENT_TIMESTAMP, false),
(2, 28, 25, 'e as outras duas pontas das duas cadeiazinhas de obra trançada meterás nos dois engastes, e as porás nas ombreiras do éfode, na parte dianteira dele.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 26, 'Farás outras duas argolas de ouro, e as porás nas duas extremidades do peitoral, na sua borda que estiver junto ao lado interior do éfode.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 27, 'Farás mais duas argolas de ouro, e as porás nas duas ombreiras do éfode, para baixo, na parte dianteira, junto à costura, e acima do cinto de obra esmerada do éfode.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 28, 'E ligarão o peitoral, pelas suas argolas, às argolas do éfode por meio de um cordão azul, de modo que fique sobre o cinto de obra esmerada do éfode e não se separe o peitoral do éfode.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 29, 'Assim Arão levará os nomes dos filhos de Israel no peitoral do juízo sobre o seu coração, quando entrar no lugar santo, para memorial diante do Senhor continuamente.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 30, 'Também porás no peitoral do juízo o Urim e o Tumim, para que estejam sobre o coração de Arão, quando entrar diante do Senhor; assim Arão levará o juízo dos filhos de Israel sobre o seu coração diante do Senhor continuamente.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 31, 'Também farás o manto do éfode todo de azul.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 32, 'No meio dele haverá uma abertura para a cabeça; esta abertura terá um debrum de obra tecida ao redor, como a abertura de cota de malha, para que não se rompa.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 33, 'E nas suas abas, em todo o seu redor, farás romãs de azul, púrpura e carmesim, e campainhas de ouro, entremeadas com elas ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 34, 'uma campainha de ouro, e uma romã, outra campainha de ouro, e outra romã, haverá nas abas do manto ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 35, 'E estará sobre Arão quando ministrar, para que se ouça o sonido ao entrar ele no lugar santo diante do Senhor e ao sair, para que ele não morra.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 36, 'Também farás uma lâmina de ouro puro, e nela gravarás como a gravura de um selo: SANTO AO SENHOR.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 37, 'Pô-la-ás em um cordão azul, de maneira que esteja na mitra; bem na frente da mitra estará.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 38, 'E estará sobre a testa de Arão, e Arão levará a iniqüidade das coisas santas, que os filhos de Israel consagrarem em todas as suas santas ofertas; e estará continuamente na sua testa, para que eles sejam aceitos diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 39, 'Também tecerás a túnica enxadrezada de linho fino; bem como de linho fino farás a mitra; e farás o cinto, obra de bordador.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 40, 'Também para os filhos de Arão farás túnicas; e far-lhes-ás cintos; também lhes farás tiaras, para glória e ornamento.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 41, 'E vestirás com eles a Arão, teu irmão, e também a seus filhos, e os ungirás e consagrarás, e os santificarás, para que me administrem o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 42, 'Faze-lhes também calções de linho, para cobrirem a carne nua; estender-se-ão desde os lombos até as coxas.', 1, CURRENT_TIMESTAMP, false),
(2, 28, 43, 'E estarão sobre Arão e sobre seus filhos, quando entrarem na tenda da revelação, ou quando chegarem ao altar para ministrar no lugar santo, para que não levem iniqüidade e morram; isto será estatuto perpétuo para ele e para a sua descendência depois dele.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 1, 'Isto é o que lhes farás para os santificar, para que me administrem o sacerdócio: Toma um novilho e dois carneiros sem defeito,', 1, CURRENT_TIMESTAMP, false),
(2, 29, 2, 'e pão ázimo, e bolos ázimos, amassados com azeite, e coscorões ázimos, untados com azeite; de flor de farinha de trigo os farás;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 3, 'e os porás num cesto, e os trarás no cesto, com o novilho e os dois carneiros.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 4, 'Então farás chegar Arão e seus filhos à porta da tenda da revelação e os lavarás, com água.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 5, 'Depois tomarás as vestes, e vestirás a Arão da túnica e do manto do éfode, e do éfode mesmo, e do peitoral, e lhe cingirás o éfode com o seu cinto de obra esmerada;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 6, 'e pôr-lhe-ás a mitra na cabeça; e sobre a mitra porás a coroa de santidade;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 7, 'então tomarás o óleo da unção e, derramando-lho sobre a cabeça, o ungirás.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 8, 'Depois farás chegar seus filhos, e lhes farás vestir túnicas,', 1, CURRENT_TIMESTAMP, false),
(2, 29, 9, 'e os cingirás com cintos, a Arão e a seus filhos, e lhes atarás as tiaras. Por estatuto perpétuo eles terão o sacerdócio; consagrarás, pois, a Arão e a seus filhos.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 10, 'Farás chegar o novilho diante da tenda da revelação, e Arão e seus filhos porão as mãos sobre a cabeça do novilho;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 11, 'e imolarás o novilho perante o Senhor, à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 12, 'Depois tomarás do sangue do novilho, e com o dedo o porás sobre as pontas do altar, e todo o sangue restante derramarás à base do altar.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 13, 'Também tomarás toda a gordura que cobre as entranhas, o redenho do fígado, os dois rins e a gordura que houver neles, e queimá-los-ás sobre o altar;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 14, 'mas a carne do novilho, o seu couro e o seu excremento queimarás fora do arraial; é sacrifício pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 15, 'Depois tomarás um carneiro, e Arão e seus filhos porão as mãos sobre a cabeça dele,', 1, CURRENT_TIMESTAMP, false),
(2, 29, 16, 'e imolarás o carneiro e, tomando o seu sangue, o espargirás sobre o altar ao redor;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 17, 'e partirás o carneiro em suas partes, e lavarás as suas entranhas e as suas pernas, e as porás sobre as suas partes e sobre a sua cabeça.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 18, 'Assim queimarás todo o carneiro sobre o altar; é um holocausto para o Senhor; é cheiro suave, oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 19, 'e imolarás o carneiro, e tomarás do seu sangue, e o porás sobre a ponta da orelha direita de Arão e sobre a ponta da orelha direita de seus filhos, como também sobre o dedo polegar da sua mão direita e sobre o dedo polegar do seu pé direito; e espargirás o sangue sobre o altar ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 20, 'Então tomarás do sangue que estará sobre o altar, e do óleo da unção, e os espargirás sobre Arão e sobre as suas vestes, e sobre seus filhos, e sobre as vestes de seus filhos com ele; assim ele será santificado e as suas vestes, também seus filhos e as vestes de seus filhos com ele.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 21, 'Depois tomarás do carneiro a gordura e a cauda gorda, a gordura que cobre as entranhas e o redenho do fígado, os dois rins com a gordura que houver neles e a coxa direita {porque é carneiro de consagração},', 1, CURRENT_TIMESTAMP, false),
(2, 29, 22, 'e uma fogaça de pão, um bolo de pão azeitado e um coscorão do cesto dos pães ázimos que estará diante do Senhor,', 1, CURRENT_TIMESTAMP, false),
(2, 29, 23, 'e uma fogaça de pão, um bolo de pão azeitado e um coscorão do cesto dos pães ázimos que estará diante do Senhor,', 1, CURRENT_TIMESTAMP, false),
(2, 29, 24, 'e tudo porás nas mãos de Arão, e nas mãos de seus filhos; e por oferta de movimento o moverás perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 25, 'Depois o tomarás das suas mãos e o queimarás no altar sobre o holocausto, por cheiro suave perante o Senhor; é oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 26, 'Também tomarás o peito do carneiro de consagração, que é de Arão, e por oferta de movimento o moverás perante o Senhor; e isto será a tua porção.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 27, 'E santificarás o peito da oferta de movimento e a coxa da oferta alçada, depois de movida e alçada, isto é, aquilo do carneiro de consagração que for de Arão e de seus filhos;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 28, 'e isto será para Arão e para seus filhos a porção de direito, para sempre, da parte dos filhos de Israel, porque é oferta alçada; e oferta alçada será dos filhos de Israel, dos sacrifícios das suas ofertas pacíficas, oferta alçada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 29, 'As vestes sagradas de Arão ficarão para seus filhos depois dele, para nelas serem ungidos e sagrados.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 30, 'Sete dias os vestirá aquele que de seus filhos for sacerdote em seu lugar, quando entrar na tenda da revelação para ministrar no lugar santo.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 31, 'Também tomarás o carneiro de consagração e cozerás a sua carne em lugar santo.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 32, 'E Arão e seus filhos comerão a carne do carneiro, e o pão que está no cesto, à porta da tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 33, 'e comerão as coisas com que for feita expiação, para consagrá-los, e para santificá-los; mas delas o estranho não comerá, porque são santas.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 34, 'E se sobejar alguma coisa da carne da consagração, ou do pão, até pela manhã, o que sobejar queimarás no fogo; não se comerá, porque é santo.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 35, 'Assim, pois, farás a Arão e a seus filhos conforme tudo o que te hei ordenado; por sete dias os sagrarás.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 36, 'Também cada dia oferecerás para expiação o novilho de sacrifício pelo pecado; e purificarás o altar, fazendo expiação por ele; e o ungirás para santificá-lo.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 37, 'Sete dias farás expiação pelo altar, e o santificarás; e o altar será santíssimo; tudo o que tocar o altar será santo.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 38, 'Isto, pois, é o que oferecerás sobre o altar: dois cordeiros de um ano cada dia continuamente.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 39, 'Um cordeiro oferecerás pela manhã, e o outro cordeiro oferecerás à tardinha;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 40, 'com um cordeiro a décima parte de uma efa de flor de farinha, misturada com a quarta parte de um him de azeite batido, e para libação a quarta parte de um him de vinho.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 41, 'E o outro cordeiro oferecerás à tardinha, e com ele farás oferta de cereais como com a oferta da manhã, e conforme a sua oferta de libação, por cheiro suave; oferta queimada é ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 42, 'Este será o holocausto contínuo por vossas gerações, à porta da tenda da revelação, perante o Senhor, onde vos encontrarei, para falar contigo ali.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 43, 'E ali virei aos filhos de Israel; e a tenda será santificada pela minha glória;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 44, 'santificarei a tenda da revelação e o altar; também santificarei a Arão e seus filhos, para que me administrem o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(2, 29, 45, 'Habitarei no meio dos filhos de Israel, e serei o seu Deus;', 1, CURRENT_TIMESTAMP, false),
(2, 29, 46, 'e eles saberão que eu sou o Senhor seu Deus, que os tirei da terra do Egito, para habitar no meio deles; eu sou o Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 1, 'Farás um altar para queimar o incenso; de madeira de acácia o farás.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 2, 'O seu comprimento será de um côvado, e a sua largura de um côvado; será quadrado; e de dois côvados será a sua altura; as suas pontas formarão uma só peça com ele.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 3, 'De ouro puro o cobrirás, tanto a face superior como as suas paredes ao redor, e as suas pontas; e lhe farás uma moldura de ouro ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 4, 'Também lhe farás duas argolas de ouro debaixo da sua moldura; nos dois cantos de ambos os lados as farás; e elas servirão de lugares para os varais com que o altar será levado.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 5, 'Farás também os varais de madeira de acácia e os cobrirás de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 6, 'E porás o altar diante do véu que está junto à arca do testemunho, diante do propiciatório, que se acha sobre o testemunho, onde eu virei a ti.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 7, 'E Arão queimará sobre ele o incenso das especiarias; cada manhã, quando puser em ordem as lâmpadas, o queimará.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 8, 'Também quando acender as lâmpadas à tardinha, o queimará; este será incenso perpétuo perante o Senhor pelas vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 9, 'Não oferecereis sobre ele incenso estranho, nem holocausto, nem oferta de cereais; nem tampouco derramareis sobre ele ofertas de libação.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 10, 'E uma vez no ano Arão fará expiação sobre as pontas do altar; com o sangue do sacrifício de expiação de pecado, fará expiação sobre ele uma vez no ano pelas vossas gerações; santíssimo é ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 11, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 30, 12, 'Quando fizeres o alistamento dos filhos de Israel para sua enumeração, cada um deles dará ao Senhor o resgate da sua alma, quando os alistares; para que não haja entre eles praga alguma por ocasião do alistamento.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 13, 'Dará cada um, ao ser alistado, meio siclo, segundo o siclo do santuário {este siclo é de vinte jeiras}; meio siclo é a oferta ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 14, 'Todo aquele que for alistado, de vinte anos para cima, dará a oferta do Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 15, 'O rico não dará mais, nem o pobre dará menos do que o meio siclo, quando derem a oferta do Senhor, para fazerdes expiação por vossas almas.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 16, 'E tomarás o dinheiro da expiação dos filhos de Israel, e o designarás para o serviço da tenda da revelação, para que sirva de memorial a favor dos filhos de Israel diante do Senhor, para fazerdes expiação por vossas almas.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 17, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 30, 18, 'Farás também uma pia de bronze com a sua base de bronze, para lavatório; e a porás entre a tenda da revelação e o altar, e nela deitarás água,', 1, CURRENT_TIMESTAMP, false),
(2, 30, 19, 'com a qual Arão e seus filhos lavarão as mãos e os pés;', 1, CURRENT_TIMESTAMP, false),
(2, 30, 20, 'quando entrarem na tenda da revelação lavar-se-ão com água, para que não morram, ou quando se chegarem ao altar para ministrar, para fazer oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 21, 'Lavarão, pois, as mãos e os pés, para que não morram; e isto lhes será por estatuto perpétuo a ele e à sua descendência pelas suas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 22, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 30, 23, 'Também toma das principais especiarias, da mais pura mirra quinhentos siclos, de canela aromática a metade, a saber, duzentos e cinqüenta siclos, de cálamo aromático duzentos e cinqüenta siclos,', 1, CURRENT_TIMESTAMP, false),
(2, 30, 24, 'de cássia quinhentos siclos, segundo o siclo do santuário, e de azeite de oliveiras um him.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 25, 'Disto farás um óleo sagrado para as unções, um perfume composto segundo a arte do perfumista; este será o óleo sagrado para as unções.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 26, 'Com ele ungirás a tenda da revelação, a arca do testemunho,', 1, CURRENT_TIMESTAMP, false),
(2, 30, 27, 'a mesa com todos os seus utensílios, o candelabro com os seus utensílios, o altar de incenso,', 1, CURRENT_TIMESTAMP, false),
(2, 30, 28, 'a altar do holocausto com todos os seus utensílios, o altar de incenso,', 1, CURRENT_TIMESTAMP, false),
(2, 30, 29, 'Assim santificarás estas coisas, para que sejam santíssimas; tudo o que as tocar será santo.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 30, 'Também ungirás a Arão e seus filhos, e os santificarás para me administrarem o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 31, 'E falarás aos filhos de Israel, dizendo: Este me será o óleo sagrado para as unções por todas as vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 32, 'Não se ungirá com ele carne de homem; nem fareis outro de semelhante composição; sagrado é, e para vós será sagrado.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 33, 'O homem que compuser um perfume como este, ou que com ele ungir a um estranho, será extirpado do seu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 34, 'Disse mais o Senhor a Moisés: Toma especiarias aromáticas: estoraque, onicha e gálbano, especiarias aromáticas com incenso puro; de cada uma delas tomarás peso igual;', 1, CURRENT_TIMESTAMP, false),
(2, 30, 35, 'e disto farás incenso, um perfume segundo a arte do perfumista, temperado com sal, puro e santo;', 1, CURRENT_TIMESTAMP, false),
(2, 30, 36, 'e uma parte dele reduzirás a pó e o porás diante do testemunho, na tenda da revelação onde eu virei a ti; coisa santíssima vos será.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 37, 'Ora, o incenso que fareis conforme essa composição, não o fareis para vós mesmos; santo vos será para o Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 30, 38, 'O homem que fizer tal como este para o cheirar, será extirpado do seu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 1, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 31, 2, 'Eis que eu tenho chamado por nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá,', 1, CURRENT_TIMESTAMP, false),
(2, 31, 3, 'e o enchi do espírito de Deus, no tocante à sabedoria, ao entendimento, à ciência e a todo ofício,', 1, CURRENT_TIMESTAMP, false),
(2, 31, 4, 'para inventar obras artísticas, e trabalhar em ouro, em prata e em bronze,', 1, CURRENT_TIMESTAMP, false),
(2, 31, 5, 'e em lavramento de pedras para engastar, e em entalhadura de madeira, enfim para trabalhar em todo ofício.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 6, 'E eis que eu tenho designado com ele a Aoliabe, filho de Aisamaque, da tribo de Dã, e tenho dado sabedoria ao coração de todos os homens hábeis, para fazerem tudo o que te hei ordenado,', 1, CURRENT_TIMESTAMP, false),
(2, 31, 7, 'a saber: a tenda da revelação, a arca do testemunho, o propiciatório que estará sobre ela, e todos os móveis da tenda;', 1, CURRENT_TIMESTAMP, false),
(2, 31, 8, 'a mesa com os seus utensílios, o candelabro de ouro puro com todos os seus utensílios, o altar do incenso,', 1, CURRENT_TIMESTAMP, false),
(2, 31, 9, 'o altar do holocausto com todos os seus utensílios, e a pia com a sua base;', 1, CURRENT_TIMESTAMP, false),
(2, 31, 10, 'as vestes finamente tecidas, as vestes sagradas de Arão, o sacerdote, e as de seus filhos, para administrarem o sacerdócio;', 1, CURRENT_TIMESTAMP, false),
(2, 31, 11, 'o óleo da unção, e o incenso aromático para o lugar santo; eles farão conforme tudo o que te hei mandado.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 12, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 31, 13, 'Falarás também aos filhos de Israel, dizendo: Certamente guardareis os meus sábados; porquanto isso é um sinal entre mim e vós pelas vossas gerações; para que saibais que eu sou o Senhor, que vos santifica.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 14, 'Portanto guardareis o sábado, porque santo é para vós; aquele que o profanar certamente será morto; porque qualquer que nele fizer algum trabalho, aquela alma será exterminada do meio do seu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 15, 'Seis dias se trabalhará, mas o sétimo dia será o sábado de descanso solene, santo ao Senhor; qualquer que no dia do sábado fizer algum trabalho, certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 16, 'Guardarão, pois, o sábado os filhos de Israel, celebrando-o nas suas gerações como pacto perpétuo. ,', 1, CURRENT_TIMESTAMP, false),
(2, 31, 17, 'Entre mim e os filhos de Israel será ele um sinal para sempre; porque em seis dias fez o Senhor o céu e a terra, e ao sétimo dia descansou, e achou refrigério.', 1, CURRENT_TIMESTAMP, false),
(2, 31, 18, 'E deu a Moisés, quando acabou de falar com ele no monte Sinai, as duas tábuas do testemunho, tábuas de pedra, escritas pelo dedo de Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 1, 'Mas o povo, vendo que Moisés tardava em descer do monte, acercou-se de Arão, e lhe disse: Levanta-te, faze-nos um deus que vá adiante de nós; porque, quanto a esse Moisés, o homem que nos tirou da terra do Egito, não sabemos o que lhe aconteceu.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 2, 'E Arão lhes disse: Tirai os pendentes de ouro que estão nas orelhas de vossas mulheres, de vossos filhos e de vossas filhas, e trazei-mos.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 3, 'Então todo o povo, tirando os pendentes de ouro que estavam nas suas orelhas, os trouxe a Arão;', 1, CURRENT_TIMESTAMP, false),
(2, 32, 4, 'ele os recebeu de suas mãos, e com um buril deu forma ao ouro, e dele fez um bezerro de fundição. Então eles exclamaram: Eis aqui, ó Israel, o teu deus, que te tirou da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 5, 'E Arão, vendo isto, edificou um altar diante do bezerro e, fazendo uma proclamação, disse: Amanhã haverá festa ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 6, 'No dia seguinte levantaram-se cedo, ofereceram holocaustos, e trouxeram ofertas pacíficas; e o povo sentou-se a comer e a beber; depois levantou-se para folgar.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 7, 'Então disse o Senhor a Moisés: Vai, desce; porque o teu povo, que fizeste subir da terra do Egito, se corrompeu;', 1, CURRENT_TIMESTAMP, false),
(2, 32, 8, 'depressa se desviou do caminho que eu lhe ordenei; eles fizeram para si um bezerro de fundição, e adoraram-no, e lhe ofereceram sacrifícios, e disseram: Eis aqui, ó Israel, o teu deus, que te tirou da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 9, 'Disse mais o Senhor a Moisés: Tenho observado este povo, e eis que é povo de dura cerviz.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 10, 'Agora, pois, deixa-me, para que a minha ira se acenda contra eles, e eu os consuma; e eu farei de ti uma grande nação.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 11, 'Moisés, porém, suplicou ao Senhor seu Deus, e disse: Ó Senhor, por que se acende a tua ira contra o teu povo, que tiraste da terra do Egito com grande força e com forte mão?', 1, CURRENT_TIMESTAMP, false),
(2, 32, 12, 'Por que hão de falar os egípcios, dizendo: Para mal os tirou, para matá-los nos montes, e para destruí-los da face da terra?. Torna-te da tua ardente ira, e arrepende-te deste mal contra o teu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 13, 'Lembra-te de Abraão, de Isaque, e de Israel, teus servos, aos quais por ti mesmo juraste, e lhes disseste: Multiplicarei os vossos descendentes como as estrelas do céu, e lhes darei toda esta terra de que tenho falado, e eles a possuirão por herança para sempre.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 14, 'Então o Senhor se arrependeu do mal que dissera que havia de fazer ao seu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 15, 'E virou-se Moisés, e desceu do monte com as duas tábuas do testemunho na mão, tábuas escritas de ambos os lados; de um e de outro lado estavam escritas.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 16, 'E aquelas tábuas eram obra de Deus; também a escritura era a mesma escritura de Deus, esculpida nas tábuas.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 17, 'Ora, ouvindo Josué a voz do povo que jubilava, disse a Moisés: Alarido de guerra há no arraial.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 18, 'Respondeu-lhe Moisés: Não é alarido dos vitoriosos, nem alarido dos vencidos, mas é a voz dos que cantam que eu ouço.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 19, 'Chegando ele ao arraial e vendo o bezerro e as danças, acendeu-se-lhe a ira, e ele arremessou das mãos as tábuas, e as despedaçou ao pé do monte.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 20, 'Então tomou o bezerro que tinham feito, e queimou-o no fogo; e, moendo-o até que se tornou em pó, o espargiu sobre a água, e deu-o a beber aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 21, 'E perguntou Moisés a Arão: Que te fez este povo, que sobre ele trouxeste tamanho pecado?.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 22, 'Ao que respondeu Arão: Não se acenda a ira do meu senhor; tu conheces o povo, como ele é inclinado ao mal.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 23, 'Pois eles me disseram: Faze-nos um deus que vá adiante de nós; porque, quanto a esse Moisés, o homem que nos tirou da terra do Egito, não sabemos o que lhe aconteceu.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 24, 'Então eu lhes disse: Quem tem ouro, arranque-o. Assim mo deram; e eu o lancei no fogo, e saiu este bezerro.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 25, 'Quando, pois, Moisés viu que o povo estava desenfreado {porque Arão o havia desenfreado, para escárnio entre os seus inimigos},', 1, CURRENT_TIMESTAMP, false),
(2, 32, 26, 'pôs-se em pé à entrada do arraial, e disse: Quem está ao lado do Senhor, venha a mim. Ao que se ajuntaram a ele todos os filhos de Levi.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 27, 'Então ele lhes disse: Assim diz o Senhor, o Deus de Israel: Cada um ponha a sua espada sobre a coxa; e passai e tornai pelo arraial de porta em porta, e mate cada um a seu irmão, e cada um a seu amigo, e cada um a seu vizinho.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 28, 'E os filhos de Levi fizeram conforme a palavra de Moisés; e caíram do povo naquele dia cerca de três mil homens.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 29, 'Porquanto Moisés tinha dito: Consagrai-vos hoje ao Senhor; porque cada um será contra o seu filho, e contra o seu irmão; para que o Senhor vos conceda hoje uma bênção.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 30, 'No dia seguinte disse Moisés ao povo Vós tendes cometido grande pecado; agora porém subirei ao Senhor; porventura farei expiação por vosso pecado.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 31, 'Assim tornou Moisés ao Senhor, e disse: Oh! este povo cometeu um grande pecado, fazendo para si um deus de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 32, 'Agora, pois, perdoa o seu pecado; ou se não, risca-me do teu livro, que tens escrito.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 33, 'Então disse o Senhor a Moisés: Aquele que tiver pecado contra mim, a este riscarei do meu livro.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 34, 'Vai pois agora, conduze este povo para o lugar de que te hei dito; eis que o meu anjo irá adiante de ti; porém no dia da minha visitação, sobre eles visitarei o seu pecado.', 1, CURRENT_TIMESTAMP, false),
(2, 32, 35, 'Feriu, pois, o Senhor ao povo, por ter feito o bezerro que Arão formara.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 1, 'Disse mais o Senhor a Moisés: Vai, sobe daqui, tu e o povo que fizeste subir da terra do Egito, para a terra a respeito da qual jurei a Abraão, a Isaque, e a Jacó, dizendo: À tua descendência a darei.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 2, 'E enviarei um anjo adiante de ti {e lançarei fora os cananeus, e os amorreus, e os heteus, e os perizeus, e os heveus, e os jebuseus},', 1, CURRENT_TIMESTAMP, false),
(2, 33, 3, 'para uma terra que mana leite e mel; porque eu não subirei no meio de ti, porquanto és povo de cerviz dura; para que não te consuma eu no caminho.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 4, 'E quando o povo ouviu esta má notícia, pôs-se a prantear, e nenhum deles vestiu os seus atavios.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 5, 'Pois o Senhor tinha dito a Moisés: Dize aos filhos de Israel: És um povo de dura cerviz; se por um só momento eu subir no meio de ti, te consumirei; portanto agora despe os teus atavios, para que eu saiba o que te hei de fazer.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 6, 'Então os filhos de Israel se despojaram dos seus atavios, desde o monte Horebe em diante.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 7, 'Ora, Moisés costumava tomar a tenda e armá-la fora do arraial, bem longe do arraial; e chamou-lhe a tenda da revelação. E todo aquele que buscava ao Senhor saía à tenda da revelação, que estava fora do arraial.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 8, 'Quando Moisés saía à tenda, levantava-se todo o povo e ficava em pé cada um à porta da sua tenda, e olhava a Moisés pelas costas, até entrar ele na tenda.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 9, 'E quando Moisés entrava na tenda, a coluna de nuvem descia e ficava à porta da tenda; e o Senhor falava com Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 10, 'Assim via todo o povo a coluna de nuvem que estava à porta da tenda, e todo o povo, levantando-se, adorava, cada um à porta da sua tenda.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 11, 'E falava o Senhor a Moisés face a face, como qualquer fala com o seu amigo. Depois tornava Moisés ao arraial; mas o seu servidor, o mancebo Josué, filho de Num, não se apartava da tenda.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 12, 'E Moisés disse ao Senhor: Eis que tu me dizes: Faze subir a este povo; porém não me fazes saber a quem hás de enviar comigo. Disseste também: Conheço-te por teu nome, e achaste graça aos meus olhos.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 13, 'Se eu, pois, tenho achado graça aos teus olhos, rogo-te que agora me mostres os teus caminhos, para que eu te conheça, a fim de que ache graça aos teus olhos; e considera que esta nação é teu povo.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 14, 'Respondeu-lhe o Senhor: Eu mesmo irei contigo, e eu te darei descanso.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 15, 'Então Moisés lhe disse: Se tu mesmo não fores conosco, não nos faças subir daqui.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 16, 'Como, pois, se saberá agora que tenho achado graça aos teus olhos, eu e o teu povo? acaso não é por andares tu conosco, de modo a sermos separados, eu e o teu povo, de todos os povos que há sobre a face da terra;', 1, CURRENT_TIMESTAMP, false),
(2, 33, 17, 'Ao que disse o Senhor a Moisés: Farei também isto que tens dito; porquanto achaste graça aos meus olhos, e te conheço pelo teu nome.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 18, 'Moisés disse ainda: Rogo-te que me mostres a tua glória.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 19, 'Respondeu-lhe o Senhor: Eu farei passar toda a minha bondade diante de ti, e te proclamarei o meu nome Jeová; e terei misericórdia de quem eu tiver misericórdia, e me compadecerei de quem me compadecer.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 20, 'E disse mais: Não poderás ver a minha face, porquanto homem nenhum pode ver a minha face e viver.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 21, 'Disse mais o Senhor: Eis aqui um lugar junto a mim; aqui, sobre a penha, te porás.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 22, 'E quando a minha glória passar, eu te porei numa fenda da penha, e te cobrirei com a minha mão, até que eu haja passado.', 1, CURRENT_TIMESTAMP, false),
(2, 33, 23, 'Depois, quando eu tirar a mão, me verás pelas costas; porém a minha face não se verá.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 1, 'Então disse o Senhor a Moisés: Lavra duas tábuas de pedra, como as primeiras; e eu escreverei nelas as palavras que estavam nas primeiras tábuas, que tu quebraste.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 2, 'Prepara-te para amanhã, e pela manhã sobe ao monte Sinai, e apresenta-te a mim ali no cume do monte.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 3, 'Mas ninguém suba contigo, nem apareça homem algum em todo o monte; nem mesmo se apascentem defronte dele ovelhas ou bois.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 4, 'Então Moisés lavrou duas tábuas de pedra, como as primeiras; e, levantando-se de madrugada, subiu ao monte Sinai, como o Senhor lhe tinha ordenado, levando na mão as duas tábuas de pedra.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 5, 'O Senhor desceu numa nuvem e, pondo-se ali junto a ele, proclamou o nome Jeová.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 6, 'Tendo o Senhor passado perante Moisés, proclamou: Jeová, Jeová, Deus misericordioso e compassivo, tardio em irar-se e grande em beneficência e verdade;', 1, CURRENT_TIMESTAMP, false),
(2, 34, 7, 'que usa de beneficência com milhares; que perdoa a iniqüidade, a transgressão e o pecado; que de maneira alguma terá por inocente o culpado; que visita a iniqüidade dos pais sobre os filhos e sobre os filhos dos filhos até a terceira e quarta geração.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 8, 'Então Moisés se apressou a inclinar-se à terra, e adorou,', 1, CURRENT_TIMESTAMP, false),
(2, 34, 9, 'dizendo: Senhor, se agora tenho achado graça aos teus olhos, vá o Senhor no meio de nós; porque este é povo de dura cerviz:; e perdoa a nossa iniqüidade e o nosso pecado, e toma-nos por tua herança.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 10, 'Então disse o Senhor: Eis que eu faço um pacto; farei diante de todo o teu povo maravilhas quais nunca foram feitas em toda a terra, nem dentro de nação alguma; e todo este povo, no meio do qual estás, verá a obra do Senhor; porque coisa terrível é o que faço contigo.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 11, 'Guarda o que eu te ordeno hoje: eis que eu lançarei fora de diante de ti os amorreus, os cananeus, os heteus, os perizeus, os heveus e os jebuseus.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 12, 'Guarda-te de fazeres pacto com os habitantes da terra em que hás de entrar, para que isso não seja por laço no meio de ti.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 13, 'Mas os seus altares derrubareis, e as suas colunas quebrareis, e os seus aserins cortareis', 1, CURRENT_TIMESTAMP, false),
(2, 34, 14, '{porque não adorarás a nenhum outro deus; pois o Senhor, cujo nome é Zeloso, é Deus zeloso},', 1, CURRENT_TIMESTAMP, false),
(2, 34, 15, 'para que não faças pacto com os habitantes da terra, a fim de que quando se prostituírem após os seus deuses, e sacrificarem aos seus deuses, tu não sejas convidado por eles, e não comas do seu sacrifício;', 1, CURRENT_TIMESTAMP, false),
(2, 34, 16, 'e não tomes mulheres das suas filhas para os teus filhos, para que quando suas filhas se prostituírem após os seus deuses, não façam que também teus filhos se prostituam após os seus deuses.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 17, 'Não farás para ti deuses de fundição.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 18, 'A festa dos pães ázimos guardarás; sete dias comerás pães ázimos, como te ordenei, ao tempo apontado no mês de abibe; porque foi no mês de abibe que saíste do Egito.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 19, 'Tudo o que abre a madre é meu; até todo o teu gado, que seja macho, que abre a madre de vacas ou de ovelhas;', 1, CURRENT_TIMESTAMP, false),
(2, 34, 20, 'o jumento, porém, que abrir a madre, resgatarás com um cordeiro; mas se não quiseres resgatá-lo, quebrar-lhe-ás a cerviz. Resgatarás todos os primogênitos de teus filhos. E ninguém aparecerá diante de mim com as mãos vazias.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 21, 'Seis dias trabalharás, mas ao sétimo dia descansarás; na aradura e na sega descansarás.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 22, 'Também guardarás a festa das semanas, que é a festa das primícias da ceifa do trigo, e a festa da colheita no fim do ano.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 23, 'Três vezes no ano todos os teus varões aparecerão perante o Senhor Jeová, Deus do Israel;', 1, CURRENT_TIMESTAMP, false),
(2, 34, 24, 'porque eu lançarei fora as nações de diante de ti, e alargarei as tuas fronteiras; ninguém cobiçará a tua terra, quando subires para aparecer três vezes no ano diante do Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 25, 'Não sacrificarás o sangue do meu sacrifício com pão levedado, nem o sacrifício da festa da páscoa ficará da noite para a manhã.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 26, 'As primeiras das primícias da tua terra trarás à casa do Senhor teu Deus. Não cozerás o cabrito no leite de sua mãe.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 27, 'Disse mais o Senhor a Moisés: Escreve estas palavras; porque conforme o teor destas palavras tenho feito pacto contigo e com Israel.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 28, 'E Moisés esteve ali com o Senhor quarenta dias e quarenta noites; não comeu pão, nem bebeu água, e escreveu nas tábuas as palavras do pacto, os dez mandamentos.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 29, 'Quando Moisés desceu do monte Sinai, trazendo nas mãos as duas tábuas do testemunho, sim, quando desceu do monte, Moisés não sabia que a pele do seu rosto resplandecia, por haver Deus falado com ele.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 30, 'Quando, pois, Arão e todos os filhos de Israel olharam para Moisés, eis que a pele do seu rosto resplandecia, pelo que tiveram medo de aproximar-se dele.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 31, 'Então Moisés os chamou, e Arão e todos os príncipes da congregação tornaram a ele; e Moisés lhes falou.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 32, 'Depois chegaram também todos os filhos de Israel, e ele lhes ordenou tudo o que o Senhor lhe falara no monte Sinai.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 33, 'Assim que Moisés acabou de falar com eles, pôs um véu sobre o rosto.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 34, 'Mas, entrando Moisés perante o Senhor, para falar com ele, tirava o véu até sair; e saindo, dizia aos filhos de Israel o que lhe era ordenado.', 1, CURRENT_TIMESTAMP, false),
(2, 34, 35, 'Assim, pois, viam os filhos de Israel o rosto de Moisés, e que a pele do seu rosto resplandecia; e tornava Moisés a pôr o véu sobre o seu rosto, até entrar para falar com Deus.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 1, 'Então Moisés convocou toda a congregação dos filhos de Israel, e disse-lhes: Estas são as palavras que o Senhor ordenou que cumprísseis.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 2, 'Seis dias se trabalhará, mas o sétimo dia vos será santo, sábado de descanso solene ao Senhor; todo aquele que nele fizer qualquer trabalho será morto.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 3, 'Não acendereis fogo em nenhuma das vossas moradas no dia do sábado.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 4, 'Disse mais Moisés a toda a congregação dos filhos de Israel: Esta é a palavra que o Senhor ordenou dizendo:', 1, CURRENT_TIMESTAMP, false),
(2, 35, 5, 'Tomai de entre vós uma oferta para o Senhor; cada um cujo coração é voluntariamente disposto a trará por oferta alçada ao Senhor: ouro, prata e bronze,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 6, 'como também azul, púrpura, carmesim, linho fino, pelos de cabras,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 7, 'peles de carneiros tintas de vermelho, peles de golfinhos, madeira de acácia,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 8, 'azeite para a luz, especiarias para o óleo da unção e para o incenso aromático,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 9, 'pedras de berilo e pedras de engaste para o éfode e para o peitoral.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 10, 'E venham todos os homens hábeis entre vós, e façam tudo o que o Senhor tem ordenado:', 1, CURRENT_TIMESTAMP, false),
(2, 35, 11, 'o tabernáculo, a sua tenda e a sua coberta, os seus colchetes e as suas tábuas, os seus travessões, as suas colunas e as suas bases;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 12, 'a arca e os seus varais, o propiciatório, e o véu e reposteiro;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 13, 'a mesa e os seus varais, todos os seus utensílios, e os pães da proposição;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 14, 'o candelabro para a luz, os seus utensílios, as suas lâmpadas, e o azeite para a luz;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 15, 'o altar do incenso e os seus varais, o óleo da unção e o incenso aromático, e o reposteiro da porta para a entrada do tabernáculo;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 16, 'o altar do holocausto com o seu crivo de bronze, os seus varais, e todos os seus utensílios; a pia e a sua base;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 17, 'as cortinas do átrio, as suas colunas e as suas bases, o reposteiro para a porta do átrio;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 18, 'as estacas do tabernáculo, as estacas do átrio, e as suas cordas;', 1, CURRENT_TIMESTAMP, false),
(2, 35, 19, 'as vestes finamente tecidas, para o uso no ministério no lugar santo, as vestes sagradas de Arão, o sacerdote, e as vestes de seus filhos, para administrarem o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 20, 'Então toda a congregação dos filhos de Israel saiu da presença de Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 21, 'E veio todo homem cujo coração o moveu, e todo aquele cujo espírito o estimulava, e trouxeram a oferta alçada do Senhor para a obra da tenda da revelação, e para todo o serviço dela, e para as vestes sagradas.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 22, 'Vieram, tanto homens como mulheres, todos quantos eram bem dispostos de coração, trazendo broches, pendentes, anéis e braceletes, sendo todos estes jóias de ouro; assim veio todo aquele que queria fazer oferta de ouro ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 23, 'E todo homem que possuía azul, púrpura, carmesim, linho fino, pelos de cabras, peles de carneiros tintas de vermelho, ou peles de golfinhos, os trazia.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 24, 'Todo aquele que tinha prata ou metal para oferecer, o trazia por oferta alçada ao Senhor; e todo aquele que possuía madeira de acácia, a trazia para qualquer obra do serviço.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 25, 'E todas as mulheres hábeis fiavam com as mãos, e traziam o que tinham fiado, o azul e a púrpura, o carmesim e o linho fino.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 26, 'E todas as mulheres hábeis que quisessem fiavam os pelos das cabras.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 27, 'Os príncipes traziam pedras de berilo e pedras de engaste para o éfode e para o peitoral,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 28, 'e as especiarias e o azeite para a luz, para o óleo da unção e para o incenso aromático.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 29, 'Trouxe uma oferta todo homem e mulher cujo coração voluntariamente se moveu a trazer alguma coisa para toda a obra que o senhor ordenara se fizesse por intermédio de Moisés; assim trouxeram os filhos de Israel uma oferta voluntária ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 30, 'Depois disse Moisés aos filhos de Israel: Eis que o Senhor chamou por nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 31, 'e o encheu do espírito de Deus, no tocante à sabedoria, ao entendimento, à ciência e a todo ofício,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 32, 'para inventar obras artísticas, para trabalhar em ouro, em prata e em bronze,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 33, 'em lavramento de pedras para engastar, em entalhadura de madeira, enfim, para trabalhar em toda obra fina.', 1, CURRENT_TIMESTAMP, false),
(2, 35, 34, 'Também lhe dispôs o coração para ensinar a outros; a ele e a Aoliabe, filho de Aisamaque, da tribo de Dã,', 1, CURRENT_TIMESTAMP, false),
(2, 35, 35, 'a estes encheu de sabedoria do coração para exercerem todo ofício, seja de gravador, de desenhista, de bordador em azul, púrpura, carmesim e linho fino, de tecelão, enfim, dos que exercem qualquer ofício e dos que inventam obras artísticas.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 1, 'Assim trabalharam Bezalel e Aoliabe, e todo homem hábil, a quem o Senhor deu sabedoria e entendimento, para saberem exercer todo ofício para o serviço do santuário, conforme tudo o que o Senhor tem ordenado.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 2, 'Então Moisés chamou a Bezalel e a Aoliabe, e a todo homem hábil, em cujo coração Deus tinha posto sabedoria, isto é, a todo aquele cujo coração o moveu a se chegar à obra para fazê-la;', 1, CURRENT_TIMESTAMP, false),
(2, 36, 3, 'e receberam de Moisés toda a oferta alçada, que os filhos de Israel tinham do para a obra do serviço do santuário, para fazê-la; e ainda eles lhe traziam cada manhã ofertas voluntárias.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 4, 'Então todos os sábios que faziam toda a obra do santuário vieram, cada um da obra que fazia,', 1, CURRENT_TIMESTAMP, false),
(2, 36, 5, 'e disseram a Moisés: O povo traz muito mais do que é necessário para o serviço da obra que o Senhor ordenou se fizesse.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 6, 'Pelo que Moisés deu ordem, a qual fizeram proclamar por todo o arraial, dizendo: Nenhum homem, nem mulher, faça mais obra alguma para a oferta alçada do santuário. Assim o povo foi proibido de trazer mais.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 7, 'Porque o material que tinham era bastante para toda a obra, e ainda sobejava.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 8, 'Assim todos os homens hábeis, dentre os que trabalhavam na obra, fizeram o tabernáculo de dez cortinas de linho fino torcido, de azul, de púrpura e de carmesim, com querubins, obra de artífice.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 9, 'O comprimento de cada cortina era de vinte e oito côvados, e a largura de quatro côvados; todas as cortinas eram da mesma medida.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 10, 'Ligaram cinco cortinas uma com outra; e as outras cinco da mesma maneira.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 11, 'Fizeram laçadas de azul na orla da última cortina do primeiro grupo; assim, também fizeram na orla da primeira cortina do segundo grupo.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 12, 'Cinqüenta laçadas fizeram na orla de uma cortina, e cinqüenta laçadas na orla da outra, do segundo grupo; as laçadas eram contrapostas uma à outra.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 13, 'Também fizeram cinqüenta colchetes de ouro, e com estes colchetes uniram as cortinas, uma com outra; e o tabernáculo veio a ser um todo.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 14, 'Fizeram também cortinas de pelos de cabras para servirem de tenda sobre o tabernáculo; onze cortinas fizeram.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 15, 'O comprimento de cada cortina era de trinta côvados, e a largura de quatro côvados; as onze cortinas eram da mesma medida.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 16, 'uniram cinco destas cortinas à parte, e as outras seis à parte.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 17, 'Fizeram cinqüenta laçadas na orla da última cortina do primeiro grupo, e cinqüenta laçadas na orla da primeira cortina do segundo grupo.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 18, 'Fizeram também cinqüenta colchetes de bronze, para ajuntar a tenda, para que viesse a ser um todo.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 19, 'Fizeram para a tenda uma cobertura de peles de carneiros tintas de vermelho, e por cima desta uma cobertura de peles de golfinhos.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 20, 'Também fizeram, de madeira de acácia, as tábuas para o tabernáculo, as quais foram colocadas verticalmente.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 21, 'O comprimento de cada tábua era de dez côvados, e a largura de um côvado e meio.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 22, 'Cada tábua tinha duas couceiras, unidas uma à outra; assim fizeram com todas as tábuas do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 23, 'Assim, pois, fizeram as tábuas para o tabernáculo; vinte tábuas para o lado que dá para o sul;', 1, CURRENT_TIMESTAMP, false),
(2, 36, 24, 'e fizeram quarenta bases de prata para se pôr debaixo das vinte tábuas: duas bases debaixo de uma tábua para as suas duas couceiras, e duas debaixo de outra, para as duas couceiras dela.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 25, 'Também para o segundo lado do tabernáculo, o que dá para o norte, fizeram vinte tábuas,', 1, CURRENT_TIMESTAMP, false),
(2, 36, 26, 'com as suas quarenta bases de prata, duas bases debaixo de uma tábua, e duas bases debaixo de outra.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 27, 'Para o lado posterior do tabernáculo, o que dá para o ocidente, fizeram seis tábuas.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 28, 'E para os dois cantos do tabernáculo no lado posterior, fizeram mais duas tábuas.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 29, 'Por baixo eram duplas, do mesmo modo se estendendo até a primeira argola, em cima; assim fizeram com as duas tábuas nos dois cantos.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 30, 'Assim havia oito tábuas com as suas bases de prata, a saber, dezesseis bases, duas debaixo de cada tábua.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 31, 'Fizeram também travessões de madeira de acácia: cinco travessões para as tábuas de um lado do tabernáculo,', 1, CURRENT_TIMESTAMP, false),
(2, 36, 32, 'e cinco para as tábuas do outro lado do tabernáculo, e outros cinco para as tábuas do tabernáculo no lado posterior, o que dá para o ocidente.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 33, 'Fizeram que o travessão do meio passasse ao meio das tábuas duma extremidade até a outra.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 34, 'E cobriram as tábuas de ouro, e de ouro fizeram as suas argolas como lugares para os travessões; também os travessões cobriu de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 35, 'Fizeram então o véu de azul, púrpura, carmesim e linho fino torcido; com querubins, obra de artífice, o fizeram.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 36, 'E fizeram-lhe quatro colunas de madeira de acácia e as cobriram de ouro; e seus colchetes fizeram de ouro; e fundiram-lhes quatro bases de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 36, 37, 'Fizeram também para a porta da tenda um reposteiro de azul, púrpura, carmesim e linho fino torcido, obra de bordador,', 1, CURRENT_TIMESTAMP, false),
(2, 36, 38, 'com as suas cinco colunas e os seus colchetes; e de ouro cobriu os seus capitéis e as suas faixas; e as suas cinco bases eram de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 1, 'Fez também Bezalel a arca de madeira de acácia; o seu comprimento era de dois côvados e meio, a sua largura de um côvado e meio, e a sua altura de um côvado e meio.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 2, 'Cobriu-a de ouro puro por dentro e por fora, fez-lhe uma moldura de ouro ao redor,', 1, CURRENT_TIMESTAMP, false),
(2, 37, 3, 'e fundiu-lhe quatro argolas de ouro nos seus quatro cantos, duas argolas num lado e duas no outro.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 4, 'Também fez varais de madeira de acácia, e os cobriu de ouro;', 1, CURRENT_TIMESTAMP, false),
(2, 37, 5, 'e meteu os varais pelas argolas aos lados da arca, para se levar a arca.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 6, 'Fez também um propiciatório de ouro puro; o seu comprimento era de dois côvados e meio, e a sua largura de um côvado e meio.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 7, 'Fez também dois querubins de ouro; de ouro batido os fez nas duas extremidades do propiciatório,', 1, CURRENT_TIMESTAMP, false),
(2, 37, 8, 'um querubim numa extremidade, e o outro querubim na outra; de uma só peça com o propiciatório fez os querubins nas duas extremidades dele.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 9, 'E os querubins estendiam as suas asas por cima do propiciatório, cobrindo-o com as asas, tendo as faces voltadas um para o outro; para o propiciatório estavam voltadas as faces dos querubins.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 10, 'Fez também a mesa de madeira de acácia; o seu comprimento era de dois côvados, a sua largura de um côvado, e a sua altura de um côvado e meio.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 11, 'cobriu-a de ouro puro, e fez-lhe uma moldura de ouro ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 12, 'Fez-lhe também ao redor uma guarnição de quatro dedos de largura, e ao redor na guarnição fez uma moldura de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 13, 'Fundiu-lhe também nos quatro cantos que estavam sobre os seus quatro pés.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 14, 'Junto da guarnição estavam as argolas para os lugares dos varais, para se levar a mesa.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 15, 'Fez também estes varais de madeira de acácia, e os cobriu de ouro, para se levar a mesa.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 16, 'E de ouro puro fez os utensílios que haviam de estar sobre a mesa, os seus pratos e as suas colheres, as suas tigelas e os seus cântaros, com que se haviam de oferecer as libações.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 17, 'Fez também o candelabro de ouro puro; de ouro batido fez o candelabro, tanto o seu pedestal como a sua haste; os seus copos, os seus cálices e as suas corolas formavam com ele uma só peça.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 18, 'Dos seus lados saíam seis braços: três de um lado do candelabro e três do outro lado.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 19, 'Em um braço havia três copos a modo de flores de amêndoa, com cálice e corola; igualmente no outro braço três copos a modo de flores de amêndoa, com cálice e corola; assim se fez com os seis braços que saíam do candelabro.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 20, 'Mas na haste central havia quatro copos a modo de flores de amêndoa, com os seus cálices e as suas corolas;', 1, CURRENT_TIMESTAMP, false),
(2, 37, 21, 'também havia um cálice debaixo de dois braços, formando com a haste uma só peça, e outro cálice debaixo de dois outros braços, de uma só peça com a haste, e ainda outro cálice debaixo de dois outros braços, de uma só peça com a haste; e assim se fez para os seis braços que saíam da haste.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 22, 'Os seus cálices e os seus braços formavam uma só peça com a haste; o todo era uma obra batida de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 23, 'Também de ouro puro lhe fez as lâmpadas, em número de sete, com os seus espevitadores e os seus cinzeiros.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 24, 'De um talento de ouro puro fez o candelabro e todos os seus utensílios.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 25, 'De madeira de acácia fez o altar do incenso; de um côvado era o seu comprimento, e de um côvado a sua largura, quadrado, e de dois côvados a sua altura; as suas pontas formavam uma só peça com ele.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 26, 'Cobriu-o de ouro puro, tanto a face superior como as suas paredes ao redor, e as suas pontas, e fez-lhe uma moldura de ouro ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 27, 'Fez-lhe também duas argolas de ouro debaixo da sua moldura, nos dois cantos de ambos os lados, como lugares dos varais, para com eles se levar o altar.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 28, 'E os varais fez de madeira de acácia, e os cobriu de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 37, 29, 'Também fez o óleo sagrado da unção, e o incenso aromático, puro, qual obra do perfumista.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 1, 'Fez também o altar do holocausto de madeira de acácia; de cinco côvados era o seu comprimento e de cinco côvados a sua largura, quadrado, e de três côvados a sua altura.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 2, 'E fez-lhe pontas nos seus quatro cantos; as suas pontas formavam uma só peça com ele; e cobriu-o de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 3, 'Fez também todos os utensílios do altar: os cinzeiros, as pás, as bacias, os garfos e os braseiros; todos os seus utensílios fez de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 4, 'Fez também para o altar um crivo de bronze em forma de rede, em baixo da borda ao redor, chegando ele até o meio do altar.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 5, 'E fundiu quatro argolas para as quatro extremidades do crivo de bronze, como lugares dos varais.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 6, 'E fez os varais de madeira de acácia, e os cobriu de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 7, 'E meteu os varais pelas argolas aos lados do altar, para com eles se levar o altar; fê-lo oco, de tábuas.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 8, 'Fez também a pia de bronze com a sua base de bronze, dos espelhos das mulheres que se reuniam e ministravam à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 9, 'Fez também o átrio. Para o lado meridional as cortinas eram de linho fino torcido, de cem côvados de comprimento.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 10, 'As suas colunas eram vinte, e vinte as suas bases, todas de bronze; os colchetes das colunas e as suas faixas eram de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 11, 'Para o lado setentrional as cortinas eram de cem côvados; as suas colunas eram vinte, e vinte as suas bases, todas de bronze; os colchetes das colunas e as suas faixas eram de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 12, 'Para o lado ocidental as cortinas eram de cinqüenta côvados; as suas colunas eram dez, e as suas bases dez; os colchetes das colunas e as suas faixas eram de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 13, 'E para o lado oriental eram as cortinas de cinqüenta côvados.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 14, 'As cortinas para um lado da porta eram de quinze côvados; as suas colunas eram três e as suas bases três.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 15, 'Do mesmo modo para o outro lado; de um e de outro lado da porta do átrio havia cortinas de quinze côvados; as suas colunas eram três e as suas bases três.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 16, 'Todas as cortinas do átrio ao redor eram de linho fino torcido.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 17, 'As bases das colunas eram de bronze; os colchetes das colunas e as suas faixas eram de prata; o revestimento dos seus capitéis era de prata; e todas as colunas do átrio eram cingidas de faixas de prata.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 18, 'O reposteiro da porta do átrio era de azul, púrpura, carmesim e linho fino torcido, obra de bordador; o comprimento era de vinte côvados, e a altura, na largura, de cinco côvados, conforme a altura das cortinas do átrio.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 19, 'As suas colunas eram quatro, e quatro as suas bases, todas de bronze; os seus colchetes eram de prata, como também o revestimento dos capitéis, e as suas faixas.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 20, 'E todas as estacas do tabernáculo e do átrio ao redor eram de bronze.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 21, 'Esta é a enumeração das coisas para o tabernáculo, a saber, o tabernáculo do testemunho, que por ordem de Moisés foram contadas para o ministério dos levitas, por intermédio de Itamar, filho de Arão, o sacerdote.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 22, 'Fez, pois, Bezalel, filho de Uri, filho de Hur, da tribo de Judá, tudo quanto o Senhor tinha ordenado a Moisés;', 1, CURRENT_TIMESTAMP, false),
(2, 38, 23, 'e com ele Aoliabe, filho de Aisamaque, da tribo de Dã, gravador, desenhista, e bordador em azul, púrpura, carmesim e linho fino.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 24, 'Todo o ouro gasto na obra, em toda a obra do santuário, a saber, o ouro da oferta, foi vinte e nove talentos e setecentos e trinta siclos, conforme o siclo do santuário.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 25, 'A prata dos arrolados da congregação montou em cem talentos e mil setecentos setenta e cinco siclos, conforme o siclo do santuário;', 1, CURRENT_TIMESTAMP, false),
(2, 38, 26, 'um beca para cada cabeça, isto é, meio siclo, conforme o siclo do santuário, de todo aquele que passava para os arrolados, da idade de vinte anos e acima, que foram seiscentos e três mil quinhentos e cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 27, 'E houve cem talentos de prata para fundir as bases do santuário e as bases do véu; para cem bases eram cem talentos, um talento para cada base.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 28, 'Mas dos mil setecentos e setenta e cinco siclos, fez colchetes para as colunas, e cobriu os seus capitéis e fez-lhes as faixas.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 29, 'E o bronze da oferta foi setenta talentos e dois mil e quatrocentos siclos.', 1, CURRENT_TIMESTAMP, false),
(2, 38, 30, 'Dele fez as bases da porta da tenda da revelação, o altar de bronze, e o crivo de bronze para ele, todos os utensílios do altar,', 1, CURRENT_TIMESTAMP, false),
(2, 38, 31, 'as bases do átrio ao redor e as bases da porta do átrio, todas as estacas do tabernáculo e todas as estacas do átrio ao redor.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 1, 'Fizeram também de azul, púrpura e carmesim as vestes, finamente tecidas, para ministrar no lugar santo, e fizeram as vestes sagradas para Arão, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 2, 'Assim se fez o éfode de ouro, azul, púrpura, carmesim e linho fino torcido;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 3, 'bateram o ouro em lâminas delgadas, as quais cortaram em fios, para entretecê-lo no azul, na púrpura, no carmesim e no linho fino, em obra de desenhista;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 4, 'fizeram-lhe ombreiras que se uniam; assim pelos seus dois cantos superiores foi ele unido.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 5, 'E o cinto da obra esmerada do éfode, que estava sobre ele, formava com ele uma só peça e era de obra semelhante, de ouro, azul, púrpura, carmesim e linho fino torcido, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 6, 'Também prepararam as pedras de berilo, engastadas em ouro, lavradas como a gravura de um selo, com os nomes dos filhos de Israel;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 7, 'as quais puseram sobre as ombreiras do éfode para servirem de pedras de memorial para os filhos de Israel, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 8, 'Fez-se também o peitoral de obra de desenhista, semelhante à obra do éfode, de ouro, azul, púrpura, carmesim e linho fino torcido.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 9, 'Quadrado e duplo fizeram o peitoral; o seu comprimento era de um palmo, e a sua largura de um palmo, sendo ele dobrado.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 10, 'E engastaram nele quatro fileiras de pedras: a primeira delas era de um sárdio, um topázio e uma esmeralda;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 11, 'a segunda fileira era de uma granada, uma safira e um ônix;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 12, 'a terceira fileira era de um jacinto, uma ágata e uma ametista;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 13, 'e a quarta fileira era de uma crisólita, um berilo e um jaspe; eram elas engastadas nos seus engastes de ouro.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 14, 'Estas pedras, pois, eram doze, segundo os nomes dos filhos de Israel; eram semelhantes a gravuras de selo, cada uma com o nome de uma das doze tribos.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 15, 'Também fizeram sobre o peitoral cadeiazinhas, semelhantes a cordas, obra de trança, de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 16, 'Fizeram também dois engastes de ouro e duas argolas de ouro, e fixaram as duas argolas nas duas extremidades do peitoral.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 17, 'E meteram as duas cadeiazinhas de trança de ouro nas duas argolas, nas extremidades do peitoral.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 18, 'E as outras duas pontas das duas cadeiazinhas de trança meteram nos dois engastes, e as puseram sobre as ombreiras do éfode, na parte dianteira dele.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 19, 'Fizeram outras duas argolas de ouro, que puseram nas duas extremidades do peitoral, na sua borda que estava junto ao éfode por dentro.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 20, 'Fizeram mais duas argolas de ouro, que puseram nas duas ombreiras do éfode, debaixo, na parte dianteira dele, junto à sua costura, acima do cinto de obra esmerada do éfode.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 21, 'E ligaram o peitoral, pelas suas argolas, às argolas do éfode por meio de um cordão azul, para que estivesse sobre o cinto de obra esmerada do éfode, e o peitoral não se separasse do éfode, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 22, 'Fez-se também o manto do éfode de obra tecida, todo de azul,', 1, CURRENT_TIMESTAMP, false),
(2, 39, 23, 'e a abertura do manto no meio dele, como a abertura de cota de malha; esta abertura tinha um debrum em volta, para que não se rompesse.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 24, 'Nas abas do manto fizeram romãs de azul, púrpura e carmesim, de fio torcido.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 25, 'Fizeram também campainhas de ouro puro, pondo as campainhas nas abas do manto ao redor, entremeadas com as romãs;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 26, 'uma campainha e uma romã, outra campainha e outra romã, nas abas do manto ao redor, para uso no ministério, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 27, 'Fizeram também as túnicas de linho fino, de obra tecida, para Arão e para seus filhos,', 1, CURRENT_TIMESTAMP, false),
(2, 39, 28, 'e a mitra de linho fino, e o ornato das tiaras de linho fino, e os calções de linho fino torcido,', 1, CURRENT_TIMESTAMP, false),
(2, 39, 29, 'e o cinto de linho fino torcido, e de azul, púrpura e carmesim, obra de bordador, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 30, 'Fizeram também, de ouro puro, a lâmina da coroa sagrada, e nela gravaram uma inscrição como a gravura de um selo: SANTO AO SENHOR.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 31, 'E a ela ataram um cordão azul, para prendê-la à parte superior da mitra, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 32, 'Assim se acabou toda a obra do tabernáculo da tenda da revelação; e os filhos de Israel fizeram conforme tudo o que o Senhor ordenara a Moisés; assim o fizeram.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 33, 'Depois trouxeram a Moisés o tabernáculo, a tenda e todos os seus utensílios, os seus colchetes, as suas tábuas, os seus travessões, as suas colunas e as suas bases;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 34, 'e a cobertura de peles de carneiros tintas de vermelho, e a cobertura de peles de golfinhos, e o véu do reposteiro;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 35, 'a arca do testemunho com os seus varais, e o propiciatório;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 36, 'a mesa com todos os seus utensílios, e os pães da proposição;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 37, 'o candelabro puro com suas lâmpadas todas em ordem, com todos os seus utensílios, e o azeite para a luz;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 38, 'também o altar de ouro, o óleo da unção e o incenso aromático, e o reposteiro para a porta da tenda;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 39, 'o altar de bronze e o seu crivo de bronze, os seus varais, e todos os seus utensílios; a pia e a sua base;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 40, 'as cortinas do átrio, as suas colunas e as suas bases, e o reposteiro para a porta do átrio, as suas cordas e as suas estacas, e todos os utensílios do serviço do tabernáculo, para a tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(2, 39, 41, 'as vestes finamente tecidas para uso no ministério no lugar santo, e as vestes sagradas para Arão, o sacerdote, e as vestes para seus filhos, para administrarem o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 42, 'Conforme tudo o que o Senhor ordenara a Moisés, assim fizeram os filhos de Israel toda a obra.', 1, CURRENT_TIMESTAMP, false),
(2, 39, 43, 'Viu, pois, Moisés toda a obra, e eis que a tinham feito; como o Senhor ordenara, assim a fizeram; então Moisés os abençoou.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 1, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(2, 40, 2, 'No primeiro mês, no primeiro dia do mês, levantarás o tabernáculo da tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(2, 40, 3, 'e porás nele a arca do testemunho, e resguardaras a arca com o véu.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 4, 'Depois colocarás nele a mesa, e porás em ordem o que se deve pôr em ordem nela; também colocarás nele o candelabro, e acenderás as suas lâmpadas.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 5, 'E porás o altar de ouro para o incenso diante da arca do testemunho; então pendurarás o reposteiro da porta do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 6, 'E porás o altar do holocausto diante da porta do tabernáculo da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 7, 'E porás a pia entre a tenda da revelação e o altar, e nela deitarás água.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 8, 'Depois levantarás as cortinas do átrio ao redor, e pendurarás o reposteiro da porta do átrio.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 9, 'Então tomarás o óleo da unção e ungirás o tabernáculo, e tudo o que há nele; e o santificarás, a ele e a todos os seus móveis; e será santo.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 10, 'Ungirás também o altar do holocausto, e todos os seus utensílios, e santificarás o altar; e o altar será santíssimo.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 11, 'Então ungirás a pia e a sua base, e a santificarás.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 12, 'E farás chegar Arão e seus filhos à porta da tenda da revelação, e os lavarás com água.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 13, 'E vestirás Arão das vestes sagradas, e o ungirás, e o santificarás, para que me administre o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 14, 'Também farás chegar seus filhos, e os vestirás de túnicas,', 1, CURRENT_TIMESTAMP, false),
(2, 40, 15, 'e os ungirás como ungiste a seu pai, para que me administrem o sacerdócio, e a sua unção lhes será por sacerdócio perpétuo pelas suas gerações.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 16, 'E Moisés fez conforme tudo o que o Senhor lhe ordenou; assim o fez.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 17, 'E no primeiro mês do segundo ano, no primeiro dia do mês, o tabernáculo foi levantado.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 18, 'Levantou, pois, Moisés o tabernáculo: lançou as suas bases; armou as suas tábuas e nestas meteu os seus travessões; levantou as suas colunas;', 1, CURRENT_TIMESTAMP, false),
(2, 40, 19, 'estendeu a tenda por cima do tabernáculo, e pôs a cobertura da tenda sobre ela, em cima, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 20, 'Então tomou o testemunho e pô-lo na arca, ajustou à arca os varais, e pôs-lhe o propiciatório em cima.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 21, 'Depois introduziu a arca no tabernáculo, e pendurou o véu do reposteiro, e assim resguardou a arca do testemunho, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 22, 'Pôs também a mesa na tenda da revelação, ao lado do tabernáculo para o norte, fora do véu,', 1, CURRENT_TIMESTAMP, false),
(2, 40, 23, 'e sobre ela pôs em ordem o pão perante o Senhor, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 24, 'Pôs também na tenda da revelação o candelabro defronte da mesa, ao lado do tabernáculo para o sul,', 1, CURRENT_TIMESTAMP, false),
(2, 40, 25, 'e acendeu as lâmpadas perante o Senhor, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 26, 'Pôs o altar de ouro na tenda da revelação diante do véu,', 1, CURRENT_TIMESTAMP, false),
(2, 40, 27, 'e sobre ele queimou o incenso de especiarias aromáticas, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 28, 'Pendurou o reposteiro à: porta do tabernáculo,', 1, CURRENT_TIMESTAMP, false),
(2, 40, 29, 'e pôs o altar do holocausto à porta do tabernáculo da tenda da revelação, e sobre ele ofereceu o holocausto e a oferta de cereais, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 30, 'Depois: colocou a pia entre a tenda da revelação e o altar, e nela deitou água para a as abluções.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 31, 'E junto dela Moisés, e Arão e seus filhos lavaram as mãos e os pés.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 32, 'Quando entravam na tenda da revelação, e quando chegavam ao altar, lavavam-se, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 33, 'Levantou também as cortinas do átrio ao redor do tabernáculo e do altar e pendurou o reposteiro da porta do átrio. Assim Moisés acabou a obra.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 34, 'Então a nuvem cobriu a tenda da revelação, e a glória do Senhor encheu o tabernáculo;', 1, CURRENT_TIMESTAMP, false),
(2, 40, 35, 'de maneira que Moisés não podia entrar na tenda da revelação, porquanto a nuvem repousava sobre ela, e a glória do Senhor enchia o tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 36, 'Quando, pois, a nuvem se levantava de sobre o tabernáculo, prosseguiam os filhos de Israel, em todas as suas jornadas;', 1, CURRENT_TIMESTAMP, false),
(2, 40, 37, 'se a nuvem, porém, não se levantava, não caminhavam até o dia em que ela se levantasse.', 1, CURRENT_TIMESTAMP, false),
(2, 40, 38, 'Porquanto a nuvem do Senhor estava de dia sobre o tabernáculo, e o fogo estava de noite sobre ele, perante os olhos de toda a casa de Israel, em todas as suas jornadas.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 1, 'Paulo, prisioneiro de Cristo Jesus, e o irmão Timóteo, ao amado Filemom, nosso companheiro de trabalho,', 1, CURRENT_TIMESTAMP, false),
(57, 1, 2, 'e à nossa irmã Áfia, e a Arquipo, nosso companheiro de lutas, e à igreja que está em tua casa:', 1, CURRENT_TIMESTAMP, false),
(57, 1, 3, 'Graças a vós, e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 4, 'Sempre dou graças ao meu Deus, lembrando-me de ti nas minhas orações,', 1, CURRENT_TIMESTAMP, false),
(57, 1, 5, 'ao ouvir falar do amor e da fé que tens para com o Senhor Jesus e para com todos os santos;', 1, CURRENT_TIMESTAMP, false),
(57, 1, 6, 'para que a comunicação da tua fé se torne eficaz, no pleno conhecimento de todo o bem que em nós há para com Cristo.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 7, 'Pois tive grande gozo e consolação no teu amor, porque por ti, irmão, os corações dos santos têm sido reanimados.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 8, 'Pelo que, embora tenha em Cristo plena liberdade para te mandar o que convém,', 1, CURRENT_TIMESTAMP, false),
(57, 1, 9, 'todavia prefiro rogar-te por esse teu amor, sendo eu como sou, Paulo o velho, e agora até prisioneiro de Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(57, 1, 10, 'sim, rogo-te por meu filho Onésimo, que gerei nas minhas prisões;', 1, CURRENT_TIMESTAMP, false),
(57, 1, 11, 'o qual outrora te foi inútil, mas agora a ti e a mim é muito útil;', 1, CURRENT_TIMESTAMP, false),
(57, 1, 12, 'eu to torno a enviar, a ele que é o meu próprio coração.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 13, 'Eu bem quisera retê-lo comigo, para que em teu lugar me servisse nas prisões do evangelho;', 1, CURRENT_TIMESTAMP, false),
(57, 1, 14, 'mas sem o teu consentimento nada quis fazer, para que o teu benefício não fosse como por força, mas, sim, espontâneo.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 15, 'Porque bem pode ser que ele se tenha separado de ti por algum tempo, para que o recobrasses para sempre,', 1, CURRENT_TIMESTAMP, false),
(57, 1, 16, 'não já como escravo, antes mais do que escravo, como irmão amado, particularmente de mim, e quanto mais de ti, tanto na carne como também no Senhor.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 17, 'Assim pois, se me tens por companheiro, recebe-o como a mim mesmo.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 18, 'E, se te fez algum dano, ou te deve alguma coisa, lança-o minha conta.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 19, 'Eu, Paulo, de meu próprio punho o escrevo, eu o pagarei, para não te dizer que ainda a ti mesmo a mim te deves.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 20, 'Sim, irmão, eu quisera regozijar-me de ti no Senhor; reanima o meu coração em Cristo.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 21, 'Escrevo-te confiado na tua obediência, sabendo que farás ainda mais do que peço.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 22, 'E ao mesmo tempo, prepara-me também pousada, pois espero que pelas vossas orações hei de ser concedido.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 23, 'Saúda-te Epafras, meu companheiro de prisão em Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(57, 1, 24, 'assim como Marcos, Aristarco, Demas e Lucas, meus cooperadores.', 1, CURRENT_TIMESTAMP, false),
(57, 1, 25, 'A graça do Senhor Jesus Cristo seja com o vosso espírito.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 1, 'Paulo e Timóteo, servos de Cristo Jesus, a todos os santos em Cristo Jesus que estão em Filipos, com os bispos e diáconos:', 1, CURRENT_TIMESTAMP, false),
(50, 1, 2, 'Graça a vós, e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 3, 'Dou graças ao meu Deus todas as vezes que me lembro de vós,', 1, CURRENT_TIMESTAMP, false),
(50, 1, 4, 'fazendo sempre, em todas as minhas orações, súplicas por todos vós com alegria', 1, CURRENT_TIMESTAMP, false),
(50, 1, 5, 'pela vossa cooperação a favor do evangelho desde o primeiro dia até agora;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 6, 'tendo por certo isto mesmo, que aquele que em vós começou a boa obra a aperfeiçoará até o dia de Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(50, 1, 7, 'como tenho por justo sentir isto a respeito de vós todos, porque vos retenho em meu coração, pois todos vós sois participantes comigo da graça, tanto nas minhas prisões como na defesa e confirmação do evangelho.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 8, 'Pois Deus me é testemunha de que tenho saudades de todos vós, na terna misericórdia de Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 9, 'E isto peço em oração: que o vosso amor aumente mais e mais no pleno conhecimento e em todo o discernimento,', 1, CURRENT_TIMESTAMP, false),
(50, 1, 10, 'para que aproveis as coisas excelentes, a fim de que sejais sinceros, e sem ofensa até o dia de Cristo;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 11, 'cheios do fruto de justiça, que vem por meio de Jesus Cristo, para glória e louvor de Deus.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 12, 'E quero, irmãos, que saibais que as coisas que me aconteceram têm antes contribuído para o progresso do evangelho;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 13, 'de modo que se tem tornado manifesto a toda a guarda pretoriana e a todos os demais, que é por Cristo que estou em prisões;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 14, 'também a maior parte dos irmãos no Senhor, animados pelas minhas prisões, são muito mais corajosos para falar sem temor a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 15, 'Verdade é que alguns pregam a Cristo até por inveja e contenda, mas outros o fazem de boa mente;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 16, 'estes por amor, sabendo que fui posto para defesa do evangelho;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 17, 'mas aqueles por contenda anunciam a Cristo, não sinceramente, julgando suscitar aflição às minhas prisões.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 18, 'Mas que importa? contanto que, de toda maneira, ou por pretexto ou de verdade, Cristo seja anunciado, nisto me regozijo, sim, e me regozijarei;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 19, 'porque sei que isto me resultará em salvação, pela vossa súplica e pelo socorro do Espírito de Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(50, 1, 20, 'segundo a minha ardente expectativa e esperança, de que em nada serei confundido; antes, com toda a ousadia, Cristo será, tanto agora como sempre, engrandecido no meu corpo, seja pela vida, seja pela morte.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 21, 'Porque para mim o viver é Cristo, e o morrer é lucro.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 22, 'Mas, se o viver na carne resultar para mim em fruto do meu trabalho, não sei então o que hei de escolher.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 23, 'Mas de ambos os lados estou em aperto, tendo desejo de partir e estar com Cristo, porque isto é ainda muito melhor;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 24, 'todavia, por causa de vós, julgo mais necessário permanecer na carne.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 25, 'E, tendo esta confiança, sei que ficarei, e permanecerei com todos vós para vosso progresso e gozo na fé;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 26, 'para que o motivo de vos gloriardes cresça por mim em Cristo Jesus, pela minha presença de novo convosco.', 1, CURRENT_TIMESTAMP, false),
(50, 1, 27, 'Somente portai-vos, dum modo digno do evangelho de Cristo, para que, quer vá e vos veja, quer esteja ausente, ouça acerca de vós que permaneceis firmes num só espírito, combatendo juntamente com uma só alma pela fé do evangelho;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 28, 'e que em nada estais atemorizados pelos adversários, o que para eles é indício de perdição, mas para vós de salvação, e isso da parte de Deus;', 1, CURRENT_TIMESTAMP, false),
(50, 1, 29, 'pois vos foi concedido, por amor de Cristo, não somente o crer nele, mas também o padecer por ele,', 1, CURRENT_TIMESTAMP, false),
(50, 1, 30, 'tendo o mesmo combate que já em mim tendes visto e agora ouvis que está em mim.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 1, 'Portanto, se há alguma exortação em Cristo, se alguma consolação de amor, se alguma comunhão do Espírito, se alguns entranháveis afetos e compaixões,', 1, CURRENT_TIMESTAMP, false),
(50, 2, 2, 'completai o meu gozo, para que tenhais o mesmo modo de pensar, tendo o mesmo amor, o mesmo ânimo, pensando a mesma coisa;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 3, 'nada façais por contenda ou por vanglória, mas com humildade cada um considere os outros superiores a si mesmo;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 4, 'não olhe cada um somente para o que é seu, mas cada qual também para o que é dos outros.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 5, 'Tende em vós aquele sentimento que houve também em Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(50, 2, 6, 'o qual, subsistindo em forma de Deus, não considerou o ser igual a Deus coisa a que se devia aferrar,', 1, CURRENT_TIMESTAMP, false),
(50, 2, 7, 'mas esvaziou-se a si mesmo, tomando a forma de servo, tornando-se semelhante aos homens;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 8, 'e, achado na forma de homem, humilhou-se a si mesmo, tornando-se obediente até a morte, e morte de cruz.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 9, 'Pelo que também Deus o exaltou soberanamente, e lhe deu o nome que é sobre todo nome;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 10, 'para que ao nome de Jesus se dobre todo joelho dos que estão nos céus, e na terra, e debaixo da terra,', 1, CURRENT_TIMESTAMP, false),
(50, 2, 11, 'e toda língua confesse que Jesus Cristo é Senhor, para glória de Deus Pai.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 12, 'De sorte que, meus amados, do modo como sempre obedecestes, não como na minha presença somente, mas muito mais agora na minha ausência, efetuai a vossa salvação com temor e tremor;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 13, 'porque Deus é o que opera em vós tanto o querer como o efetuar, segundo a sua boa vontade.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 14, 'Fazei todas as coisas sem murmurações nem contendas;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 15, 'para que vos torneis irrepreensíveis e sinceros, filhos de Deus imaculados no meio de uma geração corrupta e perversa, entre a qual resplandeceis como luminares no mundo,', 1, CURRENT_TIMESTAMP, false),
(50, 2, 16, 'retendo a palavra da vida; para que no dia de Cristo eu tenha motivo de gloriar-me de que não foi em vão que corri nem em vão que trabalhei.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 17, 'Contudo, ainda que eu seja derramado como libação sobre o sacrifício e serviço da vossa fé, folgo e me regozijo com todos vós;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 18, 'e pela mesma razão folgai vós também e regozijai-vos comigo.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 19, 'Ora, espero no Senhor Jesus enviar-vos em breve Timóteo, para que também eu esteja de bom ânimo, sabendo as vossas notícias.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 20, 'Porque nenhum outro tenho de igual sentimento, que sinceramente cuide do vosso bem-estar.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 21, 'Pois todos buscam o que é seu, e não o que é de Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 22, 'Mas sabeis que provas deu ele de si; que, como filho ao pai, serviu comigo a favor do evangelho.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 23, 'A este, pois, espero enviar logo que eu tenha visto como há de ser o meu caso;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 24, 'confio, porém, no Senhor, que também eu mesmo em breve irei.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 25, 'Julguei, contudo, necessário enviar-vos Epafrodito, meu irmão, e cooperador, e companheiro nas lutas, e vosso enviado para me socorrer nas minhas necessidades;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 26, 'porquanto ele tinha saudades de vós todos, e estava angustiado por terdes ouvido que estivera doente.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 27, 'Pois de fato esteve doente e quase à morte; mas Deus se compadeceu dele, e não somente dele, mas também de mim, para que eu não tivesse tristeza sobre tristeza.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 28, 'Por isso vo-lo envio com mais urgência, para que, vendo-o outra vez, vos regozijeis, e eu tenha menos tristeza.', 1, CURRENT_TIMESTAMP, false),
(50, 2, 29, 'Recebei-o, pois, no Senhor com todo o gozo, e tende em honra a homens tais como ele;', 1, CURRENT_TIMESTAMP, false),
(50, 2, 30, 'porque pela obra de Cristo chegou até as portas da morte, arriscando a sua vida para suprir-me o que faltava do vosso serviço.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 1, 'Quanto ao mais, irmãos meus, regozijai-vos no Senhor. Não me é penoso a mim escrever-vos as mesmas coisas, e a vós vos dá segurança.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 2, 'Acautelai-vos dos cães; acautelai-vos dos maus obreiros; acautelai-vos da falsa circuncisão.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 3, 'Porque a circuncisão somos nós, que servimos a Deus em espírito, e nos gloriamos em Cristo Jesus, e não confiamos na carne.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 4, 'Se bem que eu poderia até confiar na carne. Se algum outro julga poder confiar na carne, ainda mais eu:', 1, CURRENT_TIMESTAMP, false),
(50, 3, 5, 'circuncidado ao oitavo dia, da linhagem de Israel, da tribo de Benjamim, hebreu de hebreus; quanto à lei fui fariseu;', 1, CURRENT_TIMESTAMP, false),
(50, 3, 6, 'quanto ao zelo, persegui a igreja; quanto à justiça que há na lei, fui irrepreensível.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 7, 'Mas o que para mim era lucro passei a considerá-lo como perda por amor de Cristo;', 1, CURRENT_TIMESTAMP, false),
(50, 3, 8, 'sim, na verdade, tenho também como perda todas as coisas pela excelência do conhecimento de Cristo Jesus, meu Senhor; pelo qual sofri a perda de todas estas coisas, e as considero como refugo, para que possa ganhar a Cristo,', 1, CURRENT_TIMESTAMP, false),
(50, 3, 9, 'e seja achado nele, não tendo como minha justiça a que vem da lei, mas a que vem pela fé em Cristo, a saber, a justiça que vem de Deus pela fé;', 1, CURRENT_TIMESTAMP, false),
(50, 3, 10, 'para conhecê-lo, e o poder da sua ressurreição e a e a participação dos seus sofrimentos, conformando-me a ele na sua morte,', 1, CURRENT_TIMESTAMP, false),
(50, 3, 11, 'para ver se de algum modo posso chegar à ressurreição dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 12, 'Não que já a tenha alcançado, ou que seja perfeito; mas vou prosseguindo, para ver se poderei alcançar aquilo para o que fui também alcançado por Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 13, 'Irmãos, quanto a mim, não julgo que o haja alcançado; mas uma coisa faço, e é que, esquecendo-me das coisas que atrás ficam, e avançando para as que estão adiante,', 1, CURRENT_TIMESTAMP, false),
(50, 3, 14, 'prossigo para o alvo pelo prêmio da vocação celestial de Deus em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 15, 'Pelo que todos quantos somos perfeitos tenhamos este sentimento; e, se sentis alguma coisa de modo diverso, Deus também vo-lo revelará.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 16, 'Mas, naquela medida de perfeição a que já chegamos, nela prossigamos.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 17, 'Irmãos, sede meus imitadores, e atentai para aqueles que andam conforme o exemplo que tendes em nós;', 1, CURRENT_TIMESTAMP, false),
(50, 3, 18, 'porque muitos há, dos quais repetidas vezes vos disse, e agora vos digo até chorando, que são inimigos da cruz de Cristo;', 1, CURRENT_TIMESTAMP, false),
(50, 3, 19, 'cujo fim é a perdição; cujo deus é o ventre; e cuja glória assenta no que é vergonhoso; os quais só cuidam das coisas terrenas.', 1, CURRENT_TIMESTAMP, false),
(50, 3, 20, 'Mas a nossa pátria está nos céus, donde também aguardamos um Salvador, o Senhor Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(50, 3, 21, 'que transformará o corpo da nossa humilhação, para ser conforme ao corpo da sua glória, segundo o seu eficaz poder de até sujeitar a si todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 1, 'Portanto, meus amados e saudosos irmãos, minha alegria e coroa, permanecei assim firmes no Senhor, amados.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 2, 'Rogo a Evódia, e rogo a Síntique, que sintam o mesmo no Senhor.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 3, 'E peço também a ti, meu verdadeiro companheiro, que as ajudes, porque trabalharam comigo no evangelho, e com Clemente, e com os outros meus cooperadores, cujos nomes estão no livro da vida.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 4, 'Regozijai-vos sempre no Senhor; outra vez digo, regozijai-vos.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 5, 'Seja a vossa moderação conhecida de todos os homens. Perto está o Senhor.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 6, 'Não andeis ansiosos por coisa alguma; antes em tudo sejam os vossos pedidos conhecidos diante de Deus pela oração e súplica com ações de graças;', 1, CURRENT_TIMESTAMP, false),
(50, 4, 7, 'e a paz de Deus, que excede todo o entendimento, guardará os vossos corações e os vossos pensamentos em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 8, 'Quanto ao mais, irmãos, tudo o que é verdadeiro, tudo o que é honesto, tudo o que é justo, tudo o que é puro, tudo o que é amável, tudo o que é de boa fama, se há alguma virtude, e se há algum louvor, nisso pensai.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 9, 'O que também aprendestes, e recebestes, e ouvistes, e vistes em mim, isso praticai; e o Deus de paz será convosco.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 10, 'Ora, muito me regozijo no Senhor por terdes finalmente renovado o vosso cuidado para comigo; do qual na verdade andáveis lembrados, mas vos faltava oportunidade.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 11, 'Não digo isto por causa de necessidade, porque já aprendi a contentar-me com as circunstâncias em que me encontre.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 12, 'Sei passar falta, e sei também ter abundância; em toda maneira e em todas as coisas estou experimentado, tanto em ter fartura, como em passar fome; tanto em ter abundância, como em padecer necessidade.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 13, 'Posso todas as coisas naquele que me fortalece.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 14, 'Todavia fizestes bem em tomar parte na minha aflição.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 15, 'Também vós sabeis, ó filipenses, que, no princípio do evangelho, quando parti da Macedônia, nenhuma igreja comunicou comigo no sentido de dar e de receber, senão vós somente;', 1, CURRENT_TIMESTAMP, false),
(50, 4, 16, 'porque estando eu ainda em Tessalônica, não uma só vez, mas duas, mandastes suprir-me as necessidades.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 17, 'Não que procure dádivas, mas procuro o fruto que cresça para a vossa conta.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 18, 'Mas tenho tudo; tenho-o até em abundância; cheio estou, depois que recebi de Epafrodito o que da vossa parte me foi enviado, como cheiro suave, como sacrifício aceitável e aprazível a Deus.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 19, 'Meu Deus suprirá todas as vossas necessidades segundo as suas riquezas na glória em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 20, 'Ora, a nosso Deus e Pai seja dada glória pelos séculos dos séculos. Amém.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 21, 'Saudai a cada um dos santos em Cristo Jesus. Os irmãos que estão comigo vos saúdam.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 22, 'Todos os santos vos saúdam, especialmente os que são da casa de César.', 1, CURRENT_TIMESTAMP, false),
(50, 4, 23, 'A graça do Senhor Jesus Cristo seja com o vosso espírito.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 1, 'Paulo, apóstolo {não da parte dos homens, nem por intermédio de homem algum, mas sim por Jesus Cristo, e por Deus Pai, que o ressuscitou dentre os mortos},', 1, CURRENT_TIMESTAMP, false),
(48, 1, 2, 'e todos os irmãos que estão comigo, às igrejas da Galácia:', 1, CURRENT_TIMESTAMP, false),
(48, 1, 3, 'Graça a vós, e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(48, 1, 4, 'o qual se deu a si mesmo por nossos pecados, para nos livrar do presente século mau, segundo a vontade de nosso Deus e Pai,', 1, CURRENT_TIMESTAMP, false),
(48, 1, 5, 'a quem seja a glória para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 6, 'Estou admirado de que tão depressa estejais desertando daquele que vos chamou na graça de Cristo, para outro evangelho,', 1, CURRENT_TIMESTAMP, false),
(48, 1, 7, 'o qual não é outro; senão que há alguns que vos perturbam e querem perverter o evangelho de Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 8, 'Mas, ainda que nós mesmos ou um anjo do céu vos pregasse outro evangelho além do que já vos pregamos, seja anátema.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 9, 'Como antes temos dito, assim agora novamente o digo: Se alguém vos pregar outro evangelho além do que já recebestes, seja anátema.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 10, 'Pois busco eu agora o favor dos homens, ou o favor de Deus? ou procuro agradar aos homens? se estivesse ainda agradando aos homens, não seria servo de Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 11, 'Mas faço-vos saber, irmãos, que o evangelho que por mim foi anunciado não é segundo os homens;', 1, CURRENT_TIMESTAMP, false),
(48, 1, 12, 'porque não o recebi de homem algum, nem me foi ensinado; mas o recebi por revelação de Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 13, 'Pois já ouvistes qual foi outrora o meu procedimento no judaísmo, como sobremaneira perseguia a igreja de Deus e a assolava,', 1, CURRENT_TIMESTAMP, false),
(48, 1, 14, 'e na minha nação excedia em judaísmo a muitos da minha idade, sendo extremamente zeloso das tradições de meus pais.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 15, 'Mas, quando aprouve a Deus, que desde o ventre de minha mãe me separou, e me chamou pela sua graça,', 1, CURRENT_TIMESTAMP, false),
(48, 1, 16, 'revelar seu Filho em mim, para que eu o pregasse entre os gentios, não consultei carne e sangue,', 1, CURRENT_TIMESTAMP, false),
(48, 1, 17, 'nem subi a Jerusalém para estar com os que já antes de mim eram apóstolos, mas parti para a Arábia, e voltei outra vez a Damasco.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 18, 'Depois, passados três anos, subi a Jerusalém para visitar a Cefas, e demorei com ele quinze dias.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 19, 'Mas não vi a nenhum outro dos apóstolos, senão a Tiago, irmão do Senhor.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 20, 'Ora, acerca do que vos escrevo, eis que diante de Deus testifico que não minto.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 21, 'Depois fui para as regiões da Síria e da Cilícia.', 1, CURRENT_TIMESTAMP, false),
(48, 1, 22, 'Não era conhecido de vista das igrejas de Cristo na Judéia;', 1, CURRENT_TIMESTAMP, false),
(48, 1, 23, 'mas somente tinham ouvido dizer: Aquele que outrora nos perseguia agora prega a fé que antes procurava destruir;', 1, CURRENT_TIMESTAMP, false),
(48, 1, 24, 'e glorificavam a Deus a respeito de mim.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 1, 'Depois, passados catorze anos, subi outra vez a Jerusalém com Barnabé, levando também comigo a Tito.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 2, 'E subi devido a uma revelação, e lhes expus o evangelho que prego entre os gentios, mas em particular aos que eram de destaque, para que de algum modo não estivesse correndo ou não tivesse corrido em vão.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 3, 'Mas nem mesmo Tito, que estava comigo, embora sendo grego, foi constrangido a circuncidar-se;', 1, CURRENT_TIMESTAMP, false),
(48, 2, 4, 'e isto por causa dos falsos irmãos intrusos, os quais furtivamente entraram a espiar a nossa liberdade, que temos em Cristo Jesus, para nos escravizar;', 1, CURRENT_TIMESTAMP, false),
(48, 2, 5, 'aos quais nem ainda por uma hora cedemos em sujeição, para que a verdade do evangelho permanecesse entre vós.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 6, 'Ora, daqueles que pareciam ser alguma coisa {quais outrora tenham sido, nada me importa; Deus não aceita a aparência do homem}, esses, digo, que pareciam ser alguma coisa, nada me acrescentaram;', 1, CURRENT_TIMESTAMP, false),
(48, 2, 7, 'antes, pelo contrário, quando viram que o evangelho da incircuncisão me fora confiado, como a Pedro o da circuncisão', 1, CURRENT_TIMESTAMP, false),
(48, 2, 8, '{porque aquele que operou a favor de Pedro para o apostolado da circuncisão, operou também a meu favor para com os gentios},', 1, CURRENT_TIMESTAMP, false),
(48, 2, 9, 'e quando conheceram a graça que me fora dada, Tiago, Cefas e João, que pareciam ser as colunas, deram a mim e a Barnabé as destras de comunhão, para que nós fôssemos aos gentios, e eles à circuncisão;', 1, CURRENT_TIMESTAMP, false),
(48, 2, 10, 'recomendando-nos somente que nos lembrássemos dos pobres; o que também procurei fazer com diligência.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 11, 'Quando, porém, Cefas veio a Antioquia, resisti-lhe na cara, porque era repreensível.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 12, 'Pois antes de chegarem alguns da parte de Tiago, ele comia com os gentios; mas quando eles chegaram, se foi retirando e se apartava deles, temendo os que eram da circuncisão.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 13, 'E os outros judeus também dissimularam com ele, de modo que até Barnabé se deixou levar pela sua dissimulação.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 14, 'Mas, quando vi que não andavam retamente conforme a verdade do evangelho, disse a Cefas perante todos: Se tu, sendo judeu, vives como os gentios, e não como os judeus, como é que obrigas os gentios a viverem como judeus?', 1, CURRENT_TIMESTAMP, false),
(48, 2, 15, 'Nós, judeus por natureza e não pecadores dentre os gentios,', 1, CURRENT_TIMESTAMP, false),
(48, 2, 16, 'sabendo, contudo, que o homem não é justificado por obras da lei, mas sim, pela fé em Cristo Jesus, temos também crido em Cristo Jesus para sermos justificados pela fé em Cristo, e não por obras da lei; pois por obras da lei nenhuma carne será justificada.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 17, 'Mas se, procurando ser justificados em Cristo, fomos nós mesmos também achados pecadores, é porventura Cristo ministro do pecado? De modo nenhum.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 18, 'Porque, se torno a edificar aquilo que destruí, constituo-me a mim mesmo transgressor.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 19, 'Pois eu pela lei morri para a lei, a fim de viver para Deus.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 20, 'Já estou crucificado com Cristo; e vivo, não mais eu, mas Cristo vive em mim; e a vida que agora vivo na carne, vivo-a na fé no filho de Deus, o qual me amou, e se entregou a si mesmo por mim.', 1, CURRENT_TIMESTAMP, false),
(48, 2, 21, 'Não faço nula a graça de Deus; porque, se a justiça vem mediante a lei, logo Cristo morreu em vão.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 1, 'Ó insensatos gálatas! quem vos fascinou a vós, ante cujos olhos foi representado Jesus Cristo como crucificado?', 1, CURRENT_TIMESTAMP, false),
(48, 3, 2, 'Só isto quero saber de vós: Foi por obras da lei que recebestes o Espírito, ou pelo ouvir com fé?', 1, CURRENT_TIMESTAMP, false),
(48, 3, 3, 'Sois vós tão insensatos? tendo começado pelo Espírito, é pela carne que agora acabareis?', 1, CURRENT_TIMESTAMP, false),
(48, 3, 4, 'Será que padecestes tantas coisas em vão? Se é que isso foi em vão.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 5, 'Aquele pois que vos dá o Espírito, e que opera milagres entre vós, acaso o faz pelas obras da lei, ou pelo ouvir com fé?', 1, CURRENT_TIMESTAMP, false),
(48, 3, 6, 'Assim como Abraão creu a Deus, e isso lhe foi imputado como justiça.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 7, 'Sabei, pois, que os que são da fé, esses são filhos de Abraão.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 8, 'Ora, a Escritura, prevendo que Deus havia de justificar pela fé os gentios, anunciou previamente a boa nova a Abraão, dizendo: Em ti serão abençoadas todas as nações.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 9, 'De modo que os que são da fé são abençoados com o crente Abraão.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 10, 'Pois todos quantos são das obras da lei estão debaixo da maldição; porque escrito está: Maldito todo aquele que não permanece em todas as coisas que estão escritas no livro da lei, para fazê-las.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 11, 'É evidente que pela lei ninguém é justificado diante de Deus, porque: O justo viverá da fé;', 1, CURRENT_TIMESTAMP, false),
(48, 3, 12, 'ora, a lei não é da fé, mas: O que fizer estas coisas, por elas viverá.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 13, 'Cristo nos resgatou da maldição da lei, fazendo-se maldição por nós; porque está escrito: Maldito todo aquele que for pendurado no madeiro;', 1, CURRENT_TIMESTAMP, false),
(48, 3, 14, 'para que aos gentios viesse a bênção de Abraão em Jesus Cristo, a fim de que nós recebêssemos pela fé a promessa do Espírito.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 15, 'Irmãos, como homem falo. Um testamento, embora de homem, uma vez confirmado, ninguém o anula, nem lhe acrescenta coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 16, 'Ora, a Abraão e a seu descendente foram feitas as promessas; não diz: E a seus descendentes, como falando de muitos, mas como de um só: E a teu descendente, que é Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 17, 'E digo isto: Ao testamento anteriormente confirmado por Deus, a lei, que veio quatrocentos e trinta anos depois, não invalida, de forma a tornar inoperante a promessa.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 18, 'Pois se da lei provém a herança, já não provém mais da promessa; mas Deus, pela promessa, a deu gratuitamente a Abraão.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 19, 'Logo, para que é a lei? Foi acrescentada por causa das transgressões, até que viesse o descendente a quem a promessa tinha sido feita; e foi ordenada por meio de anjos, pela mão de um mediador.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 20, 'Ora, o mediador não o é de um só, mas Deus é um só.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 21, 'É a lei, então, contra as promessas de Deus? De modo nenhum; porque, se fosse dada uma lei que pudesse vivificar, a justiça, na verdade, teria sido pela lei.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 22, 'Mas a Escritura encerrou tudo debaixo do pecado, para que a promessa pela fé em Jesus Cristo fosse dada aos que crêem.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 23, 'Mas, antes que viesse a fé, estávamos guardados debaixo da lei, encerrados para aquela fé que se havia de revelar.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 24, 'De modo que a lei se tornou nosso aio, para nos conduzir a Cristo, a fim de que pela fé fôssemos justificados.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 25, 'Mas, depois que veio a fé, já não estamos debaixo de aio.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 26, 'Pois todos sois filhos de Deus pela fé em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 27, 'Porque todos quantos fostes batizados em Cristo vos revestistes de Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 28, 'Não há judeu nem grego; não há escravo nem livre; não há homem nem mulher; porque todos vós sois um em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(48, 3, 29, 'E, se sois de Cristo, então sois descendência de Abraão, e herdeiros conforme a promessa.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 1, 'Ora, digo que por todo o tempo em que o herdeiro é menino, em nada difere de um servo, ainda que seja senhor de tudo;', 1, CURRENT_TIMESTAMP, false),
(48, 4, 2, 'mas está debaixo de tutores e curadores até o tempo determinado pelo pai.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 3, 'Assim também nós, quando éramos meninos, estávamos reduzidos à servidão debaixo dos rudimentos do mundo;', 1, CURRENT_TIMESTAMP, false),
(48, 4, 4, 'mas, vindo a plenitude dos tempos, Deus enviou seu Filho, nascido de mulher, nascido debaixo de lei,', 1, CURRENT_TIMESTAMP, false),
(48, 4, 5, 'para resgatar os que estavam debaixo de lei, a fim de recebermos a adoção de filhos.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 6, 'E, porque sois filhos, Deus enviou aos nossos corações o Espírito de seu Filho, que clama: Aba, Pai.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 7, 'Portanto já não és mais servo, mas filho; e se és filho, és também herdeiro por Deus.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 8, 'Outrora, quando não conhecíeis a Deus, servíeis aos que por natureza não são deuses;', 1, CURRENT_TIMESTAMP, false),
(48, 4, 9, 'agora, porém, que já conheceis a Deus, ou, melhor, sendo conhecidos por Deus, como tornais outra vez a esses rudimentos fracos e pobres, aos quais de novo quereis servir?', 1, CURRENT_TIMESTAMP, false),
(48, 4, 10, 'Guardais dias, e meses, e tempos, e anos.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 11, 'Temo a vosso respeito não haja eu trabalhado em vão entre vós.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 12, 'Irmãos, rogo-vos que vos torneis como eu, porque também eu me tornei como vós. Nenhum mal me fizestes;', 1, CURRENT_TIMESTAMP, false),
(48, 4, 13, 'e vós sabeis que por causa de uma enfermidade da carne vos anunciei o evangelho a primeira vez,', 1, CURRENT_TIMESTAMP, false),
(48, 4, 14, 'e aquilo que na minha carne era para vós uma tentação, não o desprezastes nem o repelistes, antes me recebestes como a um anjo de Deus, mesmo como a Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 15, 'Onde está, pois, aquela vossa satisfação? Porque vos dou testemunho de que, se possível fora, teríeis arrancado os vossos olhos, e mos teríeis dado.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 16, 'Tornei-me acaso vosso inimigo, porque vos disse a verdade?', 1, CURRENT_TIMESTAMP, false),
(48, 4, 17, 'Eles vos procuram zelosamente não com bons motivos, mas querem vos excluir, para que zelosamente os procureis a eles.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 18, 'No que é bom, é bom serdes sempre procurados, e não só quando estou presente convosco.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 19, 'Meus filhinhos, por quem de novo sinto as dores de parto, até que Cristo seja formado em vós;', 1, CURRENT_TIMESTAMP, false),
(48, 4, 20, 'eu bem quisera estar presente convosco agora, e mudar o tom da minha voz; porque estou perplexo a vosso respeito.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 21, 'Dizei-me, os que quereis estar debaixo da lei, não ouvis vós a lei?', 1, CURRENT_TIMESTAMP, false),
(48, 4, 22, 'Porque está escrito que Abraão teve dois filhos, um da escrava, e outro da livre.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 23, 'Todavia o que era da escrava nasceu segundo a carne, mas, o que era da livre, por promessa.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 24, 'O que se entende por alegoria: pois essas mulheres são dois pactos; um do monte Sinai, que dá à luz filhos para a servidão, e que é Agar.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 25, 'Ora, esta Agar é o monte Sinai na Arábia e corresponde à Jerusalém atual, pois é escrava com seus filhos.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 26, 'Mas a Jerusalém que é de cima é livre; a qual é nossa mãe.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 27, 'Pois está escrito: Alegra-te, estéril, que não dás à luz; esforça-te e clama, tu que não estás de parto; porque mais são os filhos da desolada do que os da que tem marido.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 28, 'Ora vós, irmãos, sois filhos da promessa, como Isaque.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 29, 'Mas, como naquele tempo o que nasceu segundo a carne perseguia ao que nasceu segundo o Espírito, assim é também agora.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 30, 'Que diz, porém, a Escritura? Lança fora a escrava e seu filho, porque de modo algum o filho da escrava herdará com o filho da livre.', 1, CURRENT_TIMESTAMP, false),
(48, 4, 31, 'Pelo que, irmãos, não somos filhos da escrava, mas da livre.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 1, 'Para a liberdade Cristo nos libertou; permanecei, pois, firmes e não vos dobreis novamente a um jogo de escravidão.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 2, 'Eis que eu, Paulo, vos digo que, se vos deixardes circuncidar, Cristo de nada vos aproveitará.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 3, 'E de novo testifico a todo homem que se deixa circuncidar, que está obrigado a guardar toda a lei.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 4, 'Separados estais de Cristo, vós os que vos justificais pela lei; da graça decaístes.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 5, 'Nós, entretanto, pelo Espírito aguardamos a esperança da justiça que provém da fé.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 6, 'Porque em Cristo Jesus nem a circuncisão nem a incircuncisão vale coisa alguma; mas sim a fé que opera pelo amor.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 7, 'Corríeis bem; quem vos impediu de obedecer à verdade?', 1, CURRENT_TIMESTAMP, false),
(48, 5, 8, 'Esta persuasão não vem daquele que vos chama.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 9, 'Um pouco de fermento leveda a massa toda.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 10, 'Confio de vós, no Senhor, que de outro modo não haveis de pensar; mas aquele que vos perturba, seja quem for, sofrerá a condenação.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 11, 'Eu, porém, irmãos, se é que prego ainda a circuncisão, por que ainda sou perseguido? Nesse caso o escândalo da cruz estaria aniquilado.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 12, 'Oxalá se mutilassem aqueles que vos andam inquietando.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 13, 'Porque vós, irmãos, fostes chamados à liberdade. Mas não useis da liberdade para dar ocasião à carne, antes pelo amor servi-vos uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 14, 'Pois toda a lei se cumpre numa só palavra, a saber: Amarás ao teu próximo como a ti mesmo.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 15, 'Se vós, porém, vos mordeis e devorais uns aos outros, vede não vos consumais uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 16, 'Digo, porém: Andai pelo Espírito, e não haveis de cumprir a cobiça da carne.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 17, 'Porque a carne luta contra o Espírito, e o Espírito contra a carne; e estes se opõem um ao outro, para que não façais o que quereis.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 18, 'Mas, se sois guiados pelo Espírito, não estais debaixo da lei.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 19, 'Ora, as obras da carne são manifestas, as quais são: a prostituição, a impureza, a lascívia,', 1, CURRENT_TIMESTAMP, false),
(48, 5, 20, 'a idolatria, a feitiçaria, as inimizades, as contendas, os ciúmes, as iras, as facções, as dissensões, os partidos,', 1, CURRENT_TIMESTAMP, false),
(48, 5, 21, 'as invejas, as bebedices, as orgias, e coisas semelhantes a estas, contra as quais vos previno, como já antes vos preveni, que os que tais coisas praticam não herdarão o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 22, 'Mas o fruto do Espírito é: o amor, o gozo, a paz, a longanimidade, a benignidade, a bondade, a fidelidade.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 23, 'a mansidão, o domínio próprio; contra estas coisas não há lei.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 24, 'E os que são de Cristo Jesus crucificaram a carne com as suas paixões e concupiscências.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 25, 'Se vivemos pelo Espírito, andemos também pelo Espírito.', 1, CURRENT_TIMESTAMP, false),
(48, 5, 26, 'Não nos tornemos vangloriosos, provocando-nos uns aos outros, invejando-nos uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 1, 'Irmãos, se um homem chegar a ser surpreendido em algum delito, vós que sois espirituais corrigi o tal com espírito de mansidão; e olha por ti mesmo, para que também tu não sejas tentado.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 2, 'Levai as cargas uns dos outros, e assim cumprireis a lei de Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 3, 'Pois, se alguém pensa ser alguma coisa, não sendo nada, engana-se a si mesmo.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 4, 'Mas prove cada um a sua própria obra, e então terá motivo de glória somente em si mesmo, e não em outrem;', 1, CURRENT_TIMESTAMP, false),
(48, 6, 5, 'porque cada qual levará o seu próprio fardo.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 6, 'E o que está sendo instruído na palavra, faça participante em todas as boas coisas aquele que o instrui.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 7, 'Não vos enganeis; Deus não se deixa escarnecer; pois tudo o que o homem semear, isso também ceifará.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 8, 'Porque quem semeia na sua carne, da carne ceifará a corrupção; mas quem semeia no Espírito, do Espírito ceifará a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 9, 'E não nos cansemos de fazer o bem, porque a seu tempo ceifaremos, se não houvermos desfalecido.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 10, 'Então, enquanto temos oportunidade, façamos bem a todos, mas principalmente aos domésticos da fé.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 11, 'Vede com que grandes letras vos escrevo com minha própria mão.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 12, 'Todos os que querem ostentar boa aparência na carne, esses vos obrigam a circuncidar-vos, somente para não serem perseguidos por causa da cruz de Cristo.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 13, 'Porque nem ainda esses mesmos que se circuncidam guardam a lei, mas querem que vos circuncideis, para se gloriarem na vossa carne.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 14, 'Mas longe esteja de mim gloriar-me, a não ser na cruz de nosso Senhor Jesus Cristo, pela qual o mundo está crucificado para mim e eu para o mundo.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 15, 'Pois nem a circuncisão nem a incircuncisão é coisa alguma, mas sim o ser uma nova criatura.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 16, 'E a todos quantos andarem conforme esta norma, paz e misericórdia sejam sobre eles e sobre o Israel de Deus.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 17, 'Daqui em diante ninguém me moleste; porque eu trago no meu corpo as marcas de Jesus.', 1, CURRENT_TIMESTAMP, false),
(48, 6, 18, 'A graça de nosso Senhor Jesus Cristo seja, irmãos, com o vosso espírito. Amém.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 1, 'O oráculo que o profeta Habacuque viu.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 2, 'Até quando Senhor, clamarei eu, e tu não escutarás? ou gritarei a ti: Violência! e não salvarás?', 1, CURRENT_TIMESTAMP, false),
(35, 1, 3, 'Por que razão me fazes ver a iniqüidade, e a opressão? Pois a destruição e a violência estão diante de mim; há também contendas, e o litígio é suscitado.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 4, 'Por esta causa a lei se afrouxa, e a justiça nunca se manifesta; porque o ímpio cerca o justo, de sorte que a justiça é pervertida.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 5, 'Vede entre as nações, e olhai; maravilhai-vos e admirai-vos; porque realizo em vossos dias uma obra, que vós não acreditareis, quando vos for contada.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 6, 'Pois eis que suscito os caldeus, essa nação feroz e impetuosa, que marcha sobre a largura da terra para se apoderar de moradas que não são suas.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 7, 'Ela é terrível e espantosa; dela mesma sai o seu juízo e a sua dignidade.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 8, 'Os seis cavalos são mais ligeiros do que os leopardos, se mais ferozes do que os lobos a tarde; os seus cavaleiros espalham-se por toda a parte; sim, os seus cavaleiros vêm de longe; voam como a águia que se apressa a devorar.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 9, 'Eles todos vêm com violência; a sua vanguarda irrompe como o vento oriental; eles ajuntam cativos como areia.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 10, 'Escarnecem dos reis, e dos príncipes fazem zombaria; eles se riem de todas as fortalezas; porque, amontoando terra, as tomam.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 11, 'Então passam impetuosamente, como um vento, e seguem, mas eles são culpados, esses cujo próprio poder e o seu deus.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 12, 'Não és tu desde a eternidade, ó Senhor meu Deus, meu santo? Nós não morreremos. Ó Senhor, para juízo puseste este povo; e tu, ó Rocha, o estabeleceste para correção.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 13, 'Tu que és tão puro de olhos que não podes ver o mal, e que não podes contemplar a perversidade, por que olhas pára os que procedem aleivosamente, e te calas enquanto o ímpio devora aquele que e mais justo do que ele.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 14, 'E farias os homens como os peixes do mar, como os répteis, que não têm quem os governe,', 1, CURRENT_TIMESTAMP, false),
(35, 1, 15, 'Ele a todos levanta com o anzol, apanha-os com a sua rede; e os ajunta na sua rede varredoura; por isso ele se alegra e se regozija.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 16, 'Por isso sacrifica à sua rede, e queima incenso à sua varredoura; porque por elas enriquece a sua porção, e abundante a sua comida.', 1, CURRENT_TIMESTAMP, false),
(35, 1, 17, 'Porventura por isso continuara esvaziando a sua rede e matando sem piedade os povos?', 1, CURRENT_TIMESTAMP, false),
(35, 2, 1, 'Sobre a minha torre de vigia me colocarei e sobre a fortaleza me apresentarei e vigiarei, para ver o que me dirá, e o que eu responderei no tocante, a minha queixa.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 2, 'Então o Senhor me respondeu , e disse: Escreve a visão e torna-se bem legível sobre tábuas, para que a possa ler quem passa correndo.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 3, 'Pois a visão é ainda para o tempo determinado, e até o fim falará, e não mentirá. Ainda que se demore, espera-o; porque certamente virá, não tardará.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 4, 'Eis o soberbo! A sua alma não é reta nele; mas o justo pela sua fé viverá.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 5, 'Além disso, o vinho é traidor; o homem soberbo não permanece. Ele alarga como o Seol o seu desejo; como a morte, nunca se pode fartar, mas ajunta a si todas as nações, e congrega a si todos os povos.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 6, 'Não levantarão, pois, todos estes contra ele um provérbio e um dito zombador? E dirão: Ai daquele que acumula o que não é seu! {até quando?} e daquele que se carrega a si mesmo de penhores!', 1, CURRENT_TIMESTAMP, false),
(35, 2, 7, 'Não se levantarão de repente os teus credores? e não despertarão os que te farão tremer? Então lhes servirás tu de despojo.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 8, 'Visto como despojaste muitas nações, os demais povos te despojarão a ti, por causa do sangue dos homens, e da violência para com á terra, a cidade, e todos os que nela habitam.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 9, 'Ai daquele que adquire para a sua casa lucros criminosos, para pôr o seu ninho no alto, a fim de se livrar das garras da calamidade!', 1, CURRENT_TIMESTAMP, false),
(35, 2, 10, 'Vergonha maquinaste para a tua casa; destruindo tu a muitos povos, pecaste contra a tua alma.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 11, 'pois a pedra clamará da parede, e a trave lhe responderá do madeiramento.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 12, 'Ai daquele que edifica a cidade com sangue, e que funda a cidade com iniqüidade!', 1, CURRENT_TIMESTAMP, false),
(35, 2, 13, 'Acaso não procede do Senhor dos exércitos que os povos trabalhem para o fogo e as nações se cansem em vão?', 1, CURRENT_TIMESTAMP, false),
(35, 2, 14, 'Pois a terra se encherá do conhecimento da glória do Senhor, como as águas cobrem o mar.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 15, 'Ai daquele que da de beber ao seu próximo, adicionando à bebida o seu furor, e que o embebeda para ver a sua nudez!', 1, CURRENT_TIMESTAMP, false),
(35, 2, 16, 'Serás farto de ignomínia em lugar de honra; bebe tu também, e sê como um incurcunciso; o cálice da mão direita do Senhor se chegará a ti, e ignomínia cairá sobre a tua glória.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 17, 'Pois a violência cometida contra o Líbano te cobrirá, e bem assim a destruição das feras te amedrontará por causa do sangue dos homens, e da violência para com a terra, a cidade e todos os que nele habitam.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 18, 'Que aproveita a imagem esculpida, tendo-a esculpido o seu artífice? a imagem de fundição, que ensina a mentira? Pois o artífice confia na sua própria obra, quando forma ídolos mudos.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 19, 'Ai daquele que diz ao pau: Acorda; e à pedra muda: Desperta! Pode isso ensinar? Eis que está coberto de ouro e de prata, e dentro dele não há espírito algum.', 1, CURRENT_TIMESTAMP, false),
(35, 2, 20, 'Mas o Senhor está no seu santo templo; cale-se diante dele toda a terra; cale-se diante dele toda a terra.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 1, 'Oração do profeta Habacuque, à moda de sigionote.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 2, 'Eu ouvi, Senhor, a tua fama, e temi; aviva, ó Senhor, a tua obra no meio dos anos; faze que ela seja conhecida no meio dos anos; na ira lembra-te da misericórdia.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 3, 'Deus veio de Temã, e do monte Parã o Santo. [Selá]. A sua glória cobriu os céus, e a terra encheu-se do seu louvor.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 4, 'E o seu resplendor é como a luz, da sua mão saem raios brilhantes, e ali está o esconderijo da sua força.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 5, 'Adiante dele vai a peste, e por detrás a praga ardente.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 6, 'Pára, e mede a terra; olha, e sacode as nações; e os montes perpétuos se espalham, os outeiros eternos se abatem; assim é o seu andar desde a eternidade.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 7, 'Vejo as tendas de Cusã em aflição; tremem as cortinas da terra de Midiã.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 8, 'Acaso é contra os rios que o Senhor está irado? E contra os ribeiros a tua ira, ou contra o mar o teu furor, visto que andas montado nos teus cavalos, nos teus carros de vitória?', 1, CURRENT_TIMESTAMP, false),
(35, 3, 9, 'Descoberto de todo está o teu arco; a tua aljava está cheia de flechas. {Selá} Tu fendes a terra com rios.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 10, 'Os montes te vêem, e se contorcem; inundação das águas passa; o abismo faz ouvir a sua voz, e levanta bem alto as suas mãos.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 11, 'O sol e a lua param nas suas moradas, ante o lampejo das tuas flechas volantes, e ao brilho intenso da tua lança fulgurante.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 12, 'com indignação marchas pela terra, com ira trilhas as nações.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 13, 'Tu sais para o socorro do teu povo, para salvamento dos teus ungidos. Tu despedaças a cabeça da casa do ímpio, descobrindo-lhe de todo os fundamentos. {selá}', 1, CURRENT_TIMESTAMP, false),
(35, 3, 14, 'Traspassas a cabeça dos seus guerreiros com as suas próprias lanças; eles me acometem como turbilhão para me espalharem; alegram-se, como se estivessem para devorar o pobre em segredo.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 15, 'Tu com os teus cavalos marchas pelo mar, pelo montão de grandes águas.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 16, 'Ouvindo-o eu, o meu ventre se comove, ao seu ruído tremem os meus lábios; entra a podridão nos meus ossos, vacilam os meus passos; em silêncio, pois, aguardarei o dia da angústia que há de vir sobre o povo', 1, CURRENT_TIMESTAMP, false),
(35, 3, 17, 'Ainda que a figueira não floresça, nem haja fruto nas vides; ainda que falhe o produto da oliveira, e os campos não produzam mantimento; ainda que o rebanho seja exterminado da malhada e nos currais não haja gado.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 18, 'todavia eu me alegrarei no Senhor, exultarei no Deus da minha salvação.', 1, CURRENT_TIMESTAMP, false),
(35, 3, 19, 'O Senhor Deus é minha força, ele fará os meus pés como os da corça, e me fará andar sobre os meus lugares altos. {Ao regente de música. Para instrumentos de cordas.}', 1, CURRENT_TIMESTAMP, false),
(58, 1, 1, 'Havendo Deus antigamente falado muitas vezes, e de muitas maneiras, aos pais, pelos profetas,', 1, CURRENT_TIMESTAMP, false),
(58, 1, 2, 'nestes últimos dias a nós nos falou pelo Filho, a quem constituiu herdeiro de todas as coisas, e por quem fez também o mundo;', 1, CURRENT_TIMESTAMP, false),
(58, 1, 3, 'sendo ele o resplendor da sua glória e a expressa imagem do seu Ser, e sustentando todas as coisas pela palavra do seu poder, havendo ele mesmo feito a purificação dos pecados, assentou-se à direita da Majestade nas alturas,', 1, CURRENT_TIMESTAMP, false),
(58, 1, 4, 'feito tanto mais excelente do que os anjos, quanto herdou mais excelente nome do que eles.', 1, CURRENT_TIMESTAMP, false),
(58, 1, 5, 'Pois a qual dos anjos disse jamais: Tu és meu Filho, hoje te gerei? E outra vez: Eu lhe serei Pai, e ele me será Filho?', 1, CURRENT_TIMESTAMP, false),
(58, 1, 6, 'E outra vez, ao introduzir no mundo o primogênito, diz: E todos os anjos de Deus o adorem.', 1, CURRENT_TIMESTAMP, false),
(58, 1, 7, 'Ora, quanto aos anjos, diz: Quem de seus anjos faz ventos, e de seus ministros labaredas de fogo.', 1, CURRENT_TIMESTAMP, false),
(58, 1, 8, 'Mas do Filho diz: O teu trono, ó Deus, subsiste pelos séculos dos séculos, e cetro de eqüidade é o cetro do teu reino.', 1, CURRENT_TIMESTAMP, false),
(58, 1, 9, 'Amaste a justiça e odiaste a iniqüidade; por isso Deus, o teu Deus, te ungiu com óleo de alegria, mais do que a teus companheiros;', 1, CURRENT_TIMESTAMP, false),
(58, 1, 10, 'e: Tu, Senhor, no princípio fundaste a terra, e os céus são obras de tuas mãos;', 1, CURRENT_TIMESTAMP, false),
(58, 1, 11, 'eles perecerão, mas tu permaneces; e todos eles, como roupa, envelhecerão,', 1, CURRENT_TIMESTAMP, false),
(58, 1, 12, 'e qual um manto os enrolarás, e como roupa se mudarão; mas tu és o mesmo, e os teus anos não acabarão.', 1, CURRENT_TIMESTAMP, false),
(58, 1, 13, 'Mas a qual dos anjos disse jamais: Assenta-te à minha direita até que eu ponha os teus inimigos por escabelo de teus pés?', 1, CURRENT_TIMESTAMP, false),
(58, 1, 14, 'Não são todos eles espíritos ministradores, enviados para servir a favor dos que hão de herdar a salvação?', 1, CURRENT_TIMESTAMP, false),
(58, 2, 1, 'Por isso convém atentarmos mais diligentemente para as coisas que ouvimos, para que em tempo algum nos desviemos delas.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 2, 'Pois se a palavra falada pelos anjos permaneceu firme, e toda transgressão e desobediência recebeu justa retribuição,', 1, CURRENT_TIMESTAMP, false),
(58, 2, 3, 'como escaparemos nós, se descuidarmos de tão grande salvação? A qual, tendo sido anunciada inicialmente pelo Senhor, foi-nos depois confirmada pelos que a ouviram:', 1, CURRENT_TIMESTAMP, false),
(58, 2, 4, 'testificando Deus juntamente com eles, por sinais e prodígios, e por múltiplos milagres e dons do Espírito Santo, distribuídos segundo a sua vontade.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 5, 'Porque não foi aos anjos que Deus sujeitou o mundo vindouro, de que falamos.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 6, 'Mas em certo lugar testificou alguém dizendo: Que é o homem, para que te lembres dele? ou o filho do homem, para que o visites?', 1, CURRENT_TIMESTAMP, false),
(58, 2, 7, 'Fizeste-o um pouco menor que os anjos, de glória e de honra o coroaste,', 1, CURRENT_TIMESTAMP, false),
(58, 2, 8, 'todas as coisas lhe sujeitaste debaixo dos pés. Ora, visto que lhe sujeitou todas as coisas, nada deixou que não lhe fosse sujeito. Mas agora ainda não vemos todas as coisas sujeitas a ele;', 1, CURRENT_TIMESTAMP, false),
(58, 2, 9, 'vemos, porém, aquele que foi feito um pouco menor que os anjos, Jesus, coroado de glória e honra, por causa da paixão da morte, para que, pela graça de Deus, provasse a morte por todos.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 10, 'Porque convinha que aquele, para quem são todas as coisas, e por meio de quem tudo existe, em trazendo muitos filhos à glória, aperfeiçoasse pelos sofrimentos o autor da salvação deles.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 11, 'Pois tanto o que santifica como os que são santificados, vêm todos de um só; por esta causa ele não se envergonha de lhes chamar irmãos,', 1, CURRENT_TIMESTAMP, false),
(58, 2, 12, 'dizendo: Anunciarei o teu nome a meus irmãos, cantar-te-ei louvores no meio da congregação.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 13, 'E outra vez: Porei nele a minha confiança. E ainda: Eis-me aqui, e os filhos que Deus me deu.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 14, 'Portanto, visto como os filhos são participantes comuns de carne e sangue, também ele semelhantemente participou das mesmas coisas, para que pela morte derrotasse aquele que tinha o poder da morte, isto é, o Diabo;', 1, CURRENT_TIMESTAMP, false),
(58, 2, 15, 'e livrasse todos aqueles que, com medo da morte, estavam por toda a vida sujeitos à escravidão.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 16, 'Pois, na verdade, não presta auxílio aos anjos, mas sim à descendência de Abraão.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 17, 'Pelo que convinha que em tudo fosse feito semelhante a seus irmãos, para se tornar um sumo sacerdote misericordioso e fiel nas coisas concernentes a Deus, a fim de fazer propiciação pelos pecados do povo.', 1, CURRENT_TIMESTAMP, false),
(58, 2, 18, 'Porque naquilo que ele mesmo, sendo tentado, padeceu, pode socorrer aos que são tentados.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 1, 'Pelo que, santos irmãos, participantes da vocação celestial, considerai o Apóstolo e Sumo Sacerdote da nossa confissão, Jesus,', 1, CURRENT_TIMESTAMP, false),
(58, 3, 2, 'como ele foi fiel ao que o constituiu, assim como também o foi Moisés em toda a casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 3, 'Pois ele é tido por digno de tanto maior glória do que Moisés, quanto maior honra do que a casa tem aquele que a edificou.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 4, 'Porque toda casa é edificada por alguém, mas quem edificou todas as coisas é Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 5, 'Moisés, na verdade, foi fiel em toda a casa de Deus, como servo, para testemunho das coisas que se haviam de anunciar;', 1, CURRENT_TIMESTAMP, false),
(58, 3, 6, 'mas Cristo o é como Filho sobre a casa de Deus; a qual casa somos nós, se tão-somente conservarmos firmes até o fim a nossa confiança e a glória da esperança.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 7, 'Pelo que, como diz o Espírito Santo: Hoje, se ouvirdes a sua voz,', 1, CURRENT_TIMESTAMP, false),
(58, 3, 8, 'não endureçais os vossos corações, como na provocação, no dia da tentação no deserto,', 1, CURRENT_TIMESTAMP, false),
(58, 3, 9, 'onde vossos pais me tentaram, pondo-me à prova, e viram por quarenta anos as minhas obras.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 10, 'Por isto me indignei contra essa geração, e disse: Estes sempre erram em seu coração, e não chegaram a conhecer os meus caminhos.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 11, 'Assim jurei na minha ira: Não entrarão no meu descanso.', 1, CURRENT_TIMESTAMP, false),
(58, 3, 12, 'Vede, irmãos, que nunca se ache em qualquer de vós um perverso coração de incredulidade, para se apartar do Deus vivo;', 1, CURRENT_TIMESTAMP, false),
(58, 3, 13, 'antes exortai-vos uns aos outros todos os dias, durante o tempo que se chama Hoje, para que nenhum de vós se endureça pelo engano do pecado;', 1, CURRENT_TIMESTAMP, false),
(58, 3, 14, 'porque nos temos tornado participantes de Cristo, se é que guardamos firme até o fim a nossa confiança inicial;', 1, CURRENT_TIMESTAMP, false),
(58, 3, 15, 'enquanto se diz: Hoje, se ouvirdes a sua voz, não endureçais os vossos corações, como na provocação;', 1, CURRENT_TIMESTAMP, false),
(58, 3, 16, 'pois quais os que, tendo-a ouvido, o provocaram? Não foram, porventura, todos os que saíram do Egito por meio de Moisés?', 1, CURRENT_TIMESTAMP, false),
(58, 3, 17, 'E contra quem se indignou por quarenta anos? Não foi porventura contra os que pecaram, cujos corpos caíram no deserto?', 1, CURRENT_TIMESTAMP, false),
(58, 3, 18, 'E a quem jurou que não entrariam no seu descanso, senão aos que foram desobedientes?', 1, CURRENT_TIMESTAMP, false),
(58, 3, 19, 'E vemos que não puderam entrar por causa da incredulidade.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 1, 'Portanto, tendo-nos sido deixada a promessa de entrarmos no seu descanso, temamos não haja algum de vós que pareça ter falhado.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 2, 'Porque também a nós foram pregadas as boas novas, assim como a eles; mas a palavra da pregação nada lhes aproveitou, porquanto não chegou a ser unida com a fé, naqueles que a ouviram.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 3, 'Porque nós, os que temos crido, é que entramos no descanso, tal como disse: Assim jurei na minha ira: Não entrarão no meu descanso; embora as suas obras estivessem acabadas desde a fundação do mundo;', 1, CURRENT_TIMESTAMP, false),
(58, 4, 4, 'pois em certo lugar disse ele assim do sétimo dia: E descansou Deus, no sétimo dia, de todas as suas obras;', 1, CURRENT_TIMESTAMP, false),
(58, 4, 5, 'e outra vez, neste lugar: Não entrarão no meu descanso.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 6, 'Visto, pois, restar que alguns entrem nele, e que aqueles a quem anteriormente foram pregadas as boas novas não entraram por causa da desobediência,', 1, CURRENT_TIMESTAMP, false),
(58, 4, 7, 'determina outra vez um certo dia, Hoje, dizendo por Davi, depois de tanto tempo, como antes fora dito: Hoje, se ouvirdes a sua voz, não endureçais os vossos corações.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 8, 'Porque, se Josué lhes houvesse dado descanso, não teria falado depois disso de outro dia.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 9, 'Portanto resta ainda um repouso sabático para o povo de Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 10, 'Pois aquele que entrou no descanso de Deus, esse também descansou de suas obras, assim como Deus das suas.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 11, 'Ora, à vista disso, procuremos diligentemente entrar naquele descanso, para que ninguém caia no mesmo exemplo de desobediência.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 12, 'Porque a palavra de Deus é viva e eficaz, e mais cortante do que qualquer espada de dois gumes, e penetra até a divisão de alma e espírito, e de juntas e medulas, e é apta para discernir os pensamentos e intenções do coração.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 13, 'E não há criatura alguma encoberta diante dele; antes todas as coisas estão nuas e patentes aos olhos daquele a quem havemos de prestar contas.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 14, 'Tendo, portanto, um grande sumo sacerdote, Jesus, Filho de Deus, que penetrou os céus, retenhamos firmemente a nossa confissão.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 15, 'Porque não temos um sumo sacerdote que não possa compadecer-se das nossas fraquezas; porém um que, como nós, em tudo foi tentado, mas sem pecado.', 1, CURRENT_TIMESTAMP, false),
(58, 4, 16, 'Cheguemo-nos, pois, confiadamente ao trono da graça, para que recebamos misericórdia e achemos graça, a fim de sermos socorridos no momento oportuno.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 1, 'Porque todo sumo sacerdote tomado dentre os homens é constituído a favor dos homens nas coisas concernentes a Deus, para que ofereça dons e sacrifícios pelos pecados,', 1, CURRENT_TIMESTAMP, false),
(58, 5, 2, 'podendo ele compadecer-se devidamente dos ignorantes e errados, porquanto também ele mesmo está rodeado de fraqueza.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 3, 'E por esta razão deve ele, tanto pelo povo como também por si mesmo, oferecer sacrifício pelos pecados.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 4, 'Ora, ninguém toma para si esta honra, senão quando é chamado por Deus, como o foi Arão.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 5, 'assim também Cristo não se glorificou a si mesmo, para se fazer sumo sacerdote, mas o glorificou aquele que lhe disse: Tu és meu Filho, hoje te gerei;', 1, CURRENT_TIMESTAMP, false),
(58, 5, 6, 'como também em outro lugar diz: Tu és sacerdote para sempre, segundo a ordem de Melquisedeque.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 7, 'O qual nos dias da sua carne, tendo oferecido, com grande clamor e lágrimas, orações e súplicas ao que podia livrar da morte, e tendo sido ouvido por causa da sua reverência,', 1, CURRENT_TIMESTAMP, false),
(58, 5, 8, 'ainda que era Filho, aprendeu a obediência por meio daquilo que sofreu;', 1, CURRENT_TIMESTAMP, false),
(58, 5, 9, 'e, tendo sido aperfeiçoado, veio a ser autor de eterna salvação para todos os que lhe obedecem,', 1, CURRENT_TIMESTAMP, false),
(58, 5, 10, 'sendo por Deus chamado sumo sacerdote, segundo a ordem de Melquisedeque.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 11, 'Sobre isso temos muito que dizer, mas de difícil interpretação, porquanto vos tornastes tardios em ouvir.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 12, 'Porque, desde a infância sabes as sagradas letras, que podem necessitais de que se vos torne a ensinar os princípios elementares dos oráculos de Deus, e vos haveis feito tais que precisais de leite, e não de alimento sólido.', 1, CURRENT_TIMESTAMP, false),
(58, 5, 13, 'Ora, qualquer que se alimenta de leite é inexperiente na palavra da justiça, pois é criança;', 1, CURRENT_TIMESTAMP, false),
(58, 5, 14, 'mas o alimento sólido é para os adultos, os quais têm, pela prática, as faculdades exercitadas para discernir tanto o bem como o mal.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 1, 'Pelo que deixando os rudimentos da doutrina de Cristo, prossigamos até a perfeição, não lançando de novo o fundamento de arrependimento de obras mortas e de fé em Deus,', 1, CURRENT_TIMESTAMP, false),
(58, 6, 2, 'e o ensino sobre batismos e imposição de mãos, e sobre ressurreição de mortos e juízo eterno.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 3, 'E isso faremos, se Deus o permitir.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 4, 'Porque é impossível que os que uma vez foram iluminados, e provaram o dom celestial, e se fizeram participantes do Espírito Santo,', 1, CURRENT_TIMESTAMP, false),
(58, 6, 5, 'e provaram a boa palavra de Deus, e os poderes do mundo vindouro,', 1, CURRENT_TIMESTAMP, false),
(58, 6, 6, 'e depois caíram, sejam outra vez renovados para arrependimento; visto que, quanto a eles, estão crucificando de novo o Filho de Deus, e o expondo ao vitupério.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 7, 'Pois a terra que embebe a chuva, que cai muitas vezes sobre ela, e produz erva proveitosa para aqueles por quem é lavrada, recebe a bênção da parte de Deus;', 1, CURRENT_TIMESTAMP, false),
(58, 6, 8, 'mas se produz espinhos e abrolhos, é rejeitada, e perto está da maldição; o seu fim é ser queimada.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 9, 'Mas de vós, ó amados, esperamos coisas melhores, e que acompanham a salvação, ainda que assim falamos.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 10, 'Porque Deus não é injusto, para se esquecer da vossa obra, e do amor que para com o seu nome mostrastes, porquanto servistes aos santos, e ainda os servis.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 11, 'E desejamos que cada um de vós mostre o mesmo zelo até o fim, para completa certeza da esperança;', 1, CURRENT_TIMESTAMP, false),
(58, 6, 12, 'para que não vos torneis indolentes, mas sejais imitadores dos que pela fé e paciência herdam as promessas.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 13, 'Porque, quando Deus fez a promessa a Abraão, visto que não tinha outro maior por quem jurar, jurou por si mesmo,', 1, CURRENT_TIMESTAMP, false),
(58, 6, 14, 'dizendo: Certamente te abençoarei, e grandemente te multiplicarei.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 15, 'E assim, tendo Abraão esperado com paciência, alcançou a promessa.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 16, 'Pois os homens juram por quem é maior do que eles, e o juramento para confirmação é, para eles, o fim de toda contenda.', 1, CURRENT_TIMESTAMP, false),
(58, 6, 17, 'assim que, querendo Deus mostrar mais abundantemente aos herdeiros da promessa a imutabilidade do seu conselho, se interpôs com juramento;', 1, CURRENT_TIMESTAMP, false),
(58, 6, 18, 'para que por duas coisas imutáveis, nas quais é impossível que Deus minta, tenhamos poderosa consolação, nós, os que nos refugiamos em lançar mão da esperança proposta;', 1, CURRENT_TIMESTAMP, false),
(58, 6, 19, 'a qual temos como âncora da alma, segura e firme, e que penetra até o interior do véu;', 1, CURRENT_TIMESTAMP, false),
(58, 6, 20, 'aonde Jesus, como precursor, entrou por nós, feito sacerdote para sempre, segundo a ordem de Melquisedeque.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 1, 'Porque este Melquisedeque, rei de Salém, sacerdote do Deus Altíssimo, que saiu ao encontro de Abraão quando este regressava da matança dos reis, e o abençoou,', 1, CURRENT_TIMESTAMP, false),
(58, 7, 2, 'a quem também Abraão separou o dízimo de tudo {sendo primeiramente, por interpretação do seu nome, rei de justiça, e depois também rei de Salém, que é rei de paz;', 1, CURRENT_TIMESTAMP, false),
(58, 7, 3, 'sem pai, sem mãe, sem genealogia, não tendo princípio de dias nem fim de vida, mas feito semelhante ao Filho de Deus}, permanece sacerdote para sempre.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 4, 'Considerai, pois, quão grande era este, a quem até o patriarca Abraão deu o dízimo dentre os melhores despojos.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 5, 'E os que dentre os filhos de Levi recebem o sacerdócio têm ordem, segundo a lei, de tomar os dízimos do povo, isto é, de seus irmãos, ainda que estes também tenham saído dos lombos de Abraão;', 1, CURRENT_TIMESTAMP, false),
(58, 7, 6, 'mas aquele cuja genealogia não é contada entre eles, tomou dízimos de Abraão, e abençoou ao que tinha as promessas.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 7, 'Ora, sem contradição alguma, o menor é abençoado pelo maior.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 8, 'E aqui certamente recebem dízimos homens que morrem; ali, porém, os recebe aquele de quem se testifica que vive.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 9, 'E, por assim dizer, por meio de Abraão, até Levi, que recebe dízimos, pagou dízimos,', 1, CURRENT_TIMESTAMP, false),
(58, 7, 10, 'porquanto ele estava ainda nos lombos de seu pai quando Melquisedeque saiu ao encontro deste.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 11, 'De sorte que, se a perfeição fosse pelo sacerdócio levítico {pois sob este o povo recebeu a lei}, que necessidade havia ainda de que outro sacerdote se levantasse, segundo a ordem de Melquisedeque, e que não fosse contado segundo a ordem de Arão?', 1, CURRENT_TIMESTAMP, false),
(58, 7, 12, 'Pois, mudando-se o sacerdócio, necessariamente se faz também mudança da lei.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 13, 'Porque aquele, de quem estas coisas se dizem, pertence a outra tribo, da qual ninguém ainda serviu ao altar,', 1, CURRENT_TIMESTAMP, false),
(58, 7, 14, 'visto ser manifesto que nosso Senhor procedeu de Judá, tribo da qual Moisés nada falou acerca de sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 15, 'E ainda muito mais manifesto é isto, se à semelhança de Melquisedeque se levanta outro sacerdote,', 1, CURRENT_TIMESTAMP, false),
(58, 7, 16, 'que não foi feito conforme a lei de um mandamento carnal, mas segundo o poder duma vida indissolúvel.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 17, 'Porque dele assim se testifica: Tu és sacerdote para sempre, segundo a ordem de Melquisedeque.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 18, 'Pois, com efeito, o mandamento anterior é ab-rogado por causa da sua fraqueza e inutilidade', 1, CURRENT_TIMESTAMP, false),
(58, 7, 19, '{pois a lei nenhuma coisa aperfeiçoou}, e desta sorte é introduzida uma melhor esperança, pela qual nos aproximamos de Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 20, 'E visto como não foi sem prestar juramento {porque, na verdade, aqueles, sem juramento, foram feitos sacerdotes,', 1, CURRENT_TIMESTAMP, false),
(58, 7, 21, 'mas este com juramento daquele que lhe disse: Jurou o Senhor, e não se arrependerá: Tu és sacerdote para sempre},', 1, CURRENT_TIMESTAMP, false),
(58, 7, 22, 'de tanto melhor pacto Jesus foi feito fiador.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 23, 'E, na verdade, aqueles foram feitos sacerdotes em grande número, porque pela morte foram impedidos de permanecer,', 1, CURRENT_TIMESTAMP, false),
(58, 7, 24, 'mas este, porque permanece para sempre, tem o seu sacerdócio perpétuo.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 25, 'Portanto, pode também salvar perfeitamente os que por ele se chegam a Deus, porquanto vive sempre para interceder por eles.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 26, 'Porque nos convinha tal sumo sacerdote, santo, inocente, imaculado, separado dos pecadores, e feito mais sublime que os céus;', 1, CURRENT_TIMESTAMP, false),
(58, 7, 27, 'que não necessita, como os sumos sacerdotes, de oferecer cada dia sacrifícios, primeiramente por seus próprios pecados, e depois pelos do povo; porque isto fez ele, uma vez por todas, quando se ofereceu a si mesmo.', 1, CURRENT_TIMESTAMP, false),
(58, 7, 28, 'Porque a lei constitui sumos sacerdotes a homens que têm fraquezas, mas a palavra do juramento, que veio depois da lei, constitui ao Filho, para sempre aperfeiçoado.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 1, 'Ora, do que estamos dizendo, o ponto principal é este: Temos um sumo sacerdote tal, que se assentou nos céus à direita do trono da Majestade,', 1, CURRENT_TIMESTAMP, false),
(58, 8, 2, 'ministro do santuário, e do verdadeiro tabernáculo, que o Senhor fundou, e não o homem.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 3, 'Porque todo sumo sacerdote é constituído para oferecer dons e sacrifícios; pelo que era necessário que esse sumo sacerdote também tivesse alguma coisa que oferecer.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 4, 'Ora, se ele estivesse na terra, nem seria sacerdote, havendo já os que oferecem dons segundo a lei,', 1, CURRENT_TIMESTAMP, false),
(58, 8, 5, 'os quais servem àquilo que é figura e sombra das coisas celestiais, como Moisés foi divinamente avisado, quando estava para construir o tabernáculo; porque lhe foi dito: Olha, faze conforme o modelo que no monte se te mostrou.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 6, 'Mas agora alcançou ele ministério tanto mais excelente, quanto é mediador de um melhor pacto, o qual está firmado sobre melhores promessas.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 7, 'Pois, se aquele primeiro fora sem defeito, nunca se teria buscado lugar para o segundo.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 8, 'Porque repreendendo-os, diz: Eis que virão dias, diz o Senhor, em que estabelecerei com a casa de Israel e com a casa de Judá um novo pacto.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 9, 'Não segundo o pacto que fiz com seus pais no dia em que os tomei pela mão, para os tirar da terra do Egito; pois não permaneceram naquele meu pacto, e eu para eles não atentei, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 10, 'Ora, este é o pacto que farei com a casa de Israel, depois daqueles dias, diz o Senhor; porei as minhas leis no seu entendimento, e em seu coração as escreverei; eu serei o seu Deus, e eles serão o meu povo;', 1, CURRENT_TIMESTAMP, false),
(58, 8, 11, 'e não ensinará cada um ao seu concidadão, nem cada um ao seu irmão, dizendo: Conhece ao Senhor; porque todos me conhecerão, desde o menor deles até o maior.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 12, 'Porque serei misericordioso para com suas iniquidades, e de seus pecados não me lembrarei mais.', 1, CURRENT_TIMESTAMP, false),
(58, 8, 13, 'Dizendo: Novo pacto, ele tornou antiquado o primeiro. E o que se torna antiquado e envelhece, perto está de desaparecer.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 1, 'Ora, também o primeiro pacto tinha ordenanças de serviço sagrado, e um santuário terrestre.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 2, 'Pois foi preparada uma tenda, a primeira, na qual estavam o candeeiro, e a mesa, e os pães da proposição; a essa se chama o santo lugar;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 3, 'mas depois do segundo véu estava a tenda que se chama o santo dos santos,', 1, CURRENT_TIMESTAMP, false),
(58, 9, 4, 'que tinha o incensário de ouro, e a arca do pacto, toda coberta de ouro em redor; na qual estava um vaso de ouro, que continha o maná, e a vara de Arão, que tinha brotado, e as tábuas do pacto;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 5, 'e sobre a arca os querubins da glória, que cobriam o propiciatório; das quais coisas não falaremos agora particularmente.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 6, 'Ora, estando estas coisas assim preparadas, entram continuamente na primeira tenda os sacerdotes, celebrando os serviços sagrados;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 7, 'mas na segunda só o sumo sacerdote, uma vez por ano, não sem sangue, o qual ele oferece por si mesmo e pelos erros do povo;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 8, 'dando o Espírito Santo a entender com isso, que o caminho do santuário não está descoberto, enquanto subsiste a primeira tenda,', 1, CURRENT_TIMESTAMP, false),
(58, 9, 9, 'que é uma parábola para o tempo presente, conforme a qual se oferecem tanto dons como sacrifícios que, quanto à consciência, não podem aperfeiçoar aquele que presta o culto;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 10, 'sendo somente, no tocante a comidas, e bebidas, e várias abluções, umas ordenanças da carne, impostas até um tempo de reforma.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 11, 'Mas Cristo, tendo vindo como sumo sacerdote dos bens já realizados, por meio do maior e mais perfeito tabernáculo {não feito por mãos, isto é, não desta criação},', 1, CURRENT_TIMESTAMP, false),
(58, 9, 12, 'e não pelo sangue de bodes e novilhos, mas por seu próprio sangue, entrou uma vez por todas no santo lugar, havendo obtido uma eterna redenção.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 13, 'Porque, se a aspersão do sangue de bodes e de touros, e das cinzas duma novilha santifica os contaminados, quanto à purificação da carne,', 1, CURRENT_TIMESTAMP, false),
(58, 9, 14, 'quanto mais o sangue de Cristo, que pelo Espírito eterno se ofereceu a si mesmo imaculado a Deus, purificará das obras mortas a vossa consciência, para servirdes ao Deus vivo?', 1, CURRENT_TIMESTAMP, false),
(58, 9, 15, 'E por isso é mediador de um novo pacto, para que, intervindo a morte para remissão das transgressões cometidas debaixo do primeiro pacto, os chamados recebam a promessa da herança eterna.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 16, 'Pois onde há testamento, necessário é que intervenha a morte do testador.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 17, 'Porque um testamento não tem torça senão pela morte, visto que nunca tem valor enquanto o testador vive.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 18, 'Pelo que nem o primeiro pacto foi consagrado sem sangue;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 19, 'porque, havendo Moisés anunciado a todo o povo todos os mandamentos segundo a lei, tomou o sangue dos novilhos e dos bodes, com água, lã purpúrea e hissopo e aspergiu tanto o próprio livro como todo o povo,', 1, CURRENT_TIMESTAMP, false),
(58, 9, 20, 'dizendo: este é o sangue do pacto que Deus ordenou para vós.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 21, 'Semelhantemente aspergiu com sangue também o tabernáculo e todos os vasos do serviço sagrado.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 22, 'E quase todas as coisas, segundo a lei, se purificam com sangue; e sem derramamento de sangue não há remissão.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 23, 'Era necessário, portanto, que as figuras das coisas que estão no céu fossem purificadas com tais sacrifícios, mas as próprias coisas celestiais com sacrifícios melhores do que estes.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 24, 'Pois Cristo não entrou num santuário feito por mãos, figura do verdadeiro, mas no próprio céu, para agora comparecer por nós perante a face de Deus;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 25, 'nem também para se oferecer muitas vezes, como o sumo sacerdote de ano em ano entra no santo lugar com sangue alheio;', 1, CURRENT_TIMESTAMP, false),
(58, 9, 26, 'doutra forma, necessário lhe fora padecer muitas vezes desde a fundação do mundo; mas agora, na consumação dos séculos, uma vez por todas se manifestou, para aniquilar o pecado pelo sacrifício de si mesmo.', 1, CURRENT_TIMESTAMP, false),
(58, 9, 27, 'E, como aos homens está ordenado morrerem uma só vez, vindo depois o juízo,', 1, CURRENT_TIMESTAMP, false),
(58, 9, 28, 'assim também Cristo, oferecendo-se uma só vez para levar os pecados de muitos, aparecerá segunda vez, sem pecado, aos que o esperam para salvação.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 1, 'Porque a lei, tendo a sombra dos bens futuros, e não a imagem exata das coisas, não pode nunca, pelos mesmos sacrifícios que continuamente se oferecem de ano em ano, aperfeiçoar os que se chegam a Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 2, 'Doutra maneira, não teriam deixado de ser oferecidos? pois tendo sido uma vez purificados os que prestavam o culto, nunca mais teriam consciência de pecado.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 3, 'Mas nesses sacrifícios cada ano se faz recordação dos pecados,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 4, 'porque é impossível que o sangue de touros e de bodes tire pecados.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 5, 'Pelo que, entrando no mundo, diz: Sacrifício e oferta não quiseste, mas um corpo me preparaste;', 1, CURRENT_TIMESTAMP, false),
(58, 10, 6, 'não te deleitaste em holocaustos e oblações pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 7, 'Então eu disse: Eis-me aqui {no rol do livro está escrito de mim} para fazer, ó Deus, a tua vontade.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 8, 'Tendo dito acima: Sacrifício e ofertas e holocaustos e oblações pelo pecado não quiseste, nem neles te deleitaste {os quais se oferecem segundo a lei};', 1, CURRENT_TIMESTAMP, false),
(58, 10, 9, 'agora disse: Eis-me aqui para fazer a tua vontade. Ele tira o primeiro, para estabelecer o segundo.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 10, 'É nessa vontade dele que temos sido santificados pela oferta do corpo de Jesus Cristo, feita uma vez para sempre.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 11, 'Ora, todo sacerdote se apresenta dia após dia, ministrando e oferecendo muitas vezes os mesmos sacrifícios, que nunca podem tirar pecados;', 1, CURRENT_TIMESTAMP, false),
(58, 10, 12, 'mas este, havendo oferecido um único sacrifício pelos pecados, assentou-se para sempre à direita de Deus,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 13, 'daí por diante esperando, até que os seus inimigos sejam postos por escabelo de seus pés.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 14, 'Pois com uma só oferta tem aperfeiçoado para sempre os que estão sendo santificados.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 15, 'E o Espírito Santo também no-lo testifica, porque depois de haver dito:', 1, CURRENT_TIMESTAMP, false),
(58, 10, 16, 'Este é o pacto que farei com eles depois daqueles dias, diz o Senhor: Porei as minhas leis em seus corações, e as escreverei em seu entendimento; acrescenta:', 1, CURRENT_TIMESTAMP, false),
(58, 10, 17, 'E não me lembrarei mais de seus pecados e de suas iniqüidades.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 18, 'Ora, onde há remissão destes, não há mais oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 19, 'Tendo pois, irmãos, ousadia para entrarmos no santíssimo lugar, pelo sangue de Jesus,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 20, 'pelo caminho que ele nos inaugurou, caminho novo e vivo, através do véu, isto é, da sua carne,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 21, 'e tendo um grande sacerdote sobre a casa de Deus,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 22, 'cheguemo-nos com verdadeiro coração, em inteira certeza de fé; tendo o coração purificado da má consciência, e o corpo lavado com água limpa,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 23, 'retenhamos inabalável a confissão da nossa esperança, porque fiel é aquele que fez a promessa;', 1, CURRENT_TIMESTAMP, false),
(58, 10, 24, 'e consideremo-nos uns aos outros, para nos estimularmos ao amor e às boas obras,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 25, 'não abandonando a nossa congregação, como é costume de alguns, antes admoestando-nos uns aos outros; e tanto mais, quanto vedes que se vai aproximando aquele dia.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 26, 'Porque se voluntariamente continuarmos no pecado, depois de termos recebido o pleno conhecimento da verdade, já não resta mais sacrifício pelos pecados,', 1, CURRENT_TIMESTAMP, false),
(58, 10, 27, 'mas uma expectação terrível de juízo, e um ardor de fogo que há de devorar os adversários.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 28, 'Havendo alguém rejeitado a lei de Moisés, morre sem misericórdia, pela palavra de duas ou três testemunhas;', 1, CURRENT_TIMESTAMP, false),
(58, 10, 29, 'de quanto maior castigo cuidais vós será julgado merecedor aquele que pisar o Filho de Deus, e tiver por profano o sangue do pacto, com que foi santificado, e ultrajar ao Espírito da graça?', 1, CURRENT_TIMESTAMP, false),
(58, 10, 30, 'Pois conhecemos aquele que disse: Minha é a vingança, eu retribuirei. E outra vez: O Senhor julgará o seu povo.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 31, 'Horrenda coisa é cair nas mãos do Deus vivo.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 32, 'Lembrai-vos, porém, dos dias passados, em que, depois de serdes iluminados, suportastes grande combate de aflições;', 1, CURRENT_TIMESTAMP, false),
(58, 10, 33, 'pois por um lado fostes feitos espetáculo tanto por vitupérios como por tribulações, e por outro vos tornastes companheiros dos que assim foram tratados.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 34, 'Pois não só vos compadecestes dos que estavam nas prisões, mas também com gozo aceitastes a espoliação dos vossos bens, sabendo que vós tendes uma possessão melhor e permanente.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 35, 'Não lanceis fora, pois, a vossa confiança, que tem uma grande recompensa.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 36, 'Porque necessitais de perseverança, para que, depois de haverdes feito a vontade de Deus, alcanceis a promessa.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 37, 'Pois ainda em bem pouco tempo aquele que há de vir virá, e não tardará.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 38, 'Mas o meu justo viverá da fé; e se ele recuar, a minha alma não tem prazer nele.', 1, CURRENT_TIMESTAMP, false),
(58, 10, 39, 'Nós, porém, não somos daqueles que recuam para a perdição, mas daqueles que crêem para a conservação da alma.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 1, 'Ora, a fé é o firme fundamento das coisas que se esperam, e a prova das coisas que não se vêem.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 2, 'Porque por ela os antigos alcançaram bom testemunho.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 3, 'Pela fé entendemos que os mundos foram criados pela palavra de Deus; de modo que o visível não foi feito daquilo que se vê.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 4, 'Pela fé Abel ofereceu a Deus mais excelente sacrifício que Caim, pelo qual alcançou testemunho de que era justo, dando Deus testemunho das suas oferendas, e por meio dela depois de morto, ainda fala.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 5, 'Pela fé Enoque foi trasladado para não ver a morte; e não foi achado, porque Deus o trasladara; pois antes da sua trasladação alcançou testemunho de que agradara a Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 6, 'Ora, sem fé é impossível agradar a Deus; porque é necessário que aquele que se aproxima de Deus creia que ele existe, e que é galardoador dos que o buscam.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 7, 'Pela fé Noé, divinamente avisado das coisas que ainda não se viam, sendo temente a Deus, preparou uma arca para o salvamento da sua família; e por esta fé condenou o mundo, e tornou-se herdeiro da justiça que é segundo a fé.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 8, 'Pela fé Abraão, sendo chamado, obedeceu, saindo para um lugar que havia de receber por herança; e saiu, sem saber para onde ia.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 9, 'Pela fé peregrinou na terra da promessa, como em terra alheia, habitando em tendas com Isaque e Jacó, herdeiros com ele da mesma promessa;', 1, CURRENT_TIMESTAMP, false),
(58, 11, 10, 'porque esperava a cidade que tem os fundamentos, da qual o arquiteto e edificador é Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 11, 'Pela fé, até a própria Sara recebeu a virtude de conceber um filho, mesmo fora da idade, porquanto teve por fiel aquele que lho havia prometido.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 12, 'Pelo que também de um, e esse já amortecido, descenderam tantos, em multidão, como as estrelas do céu, e como a areia inumerável que está na praia do mar.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 13, 'Todos estes morreram na fé, sem terem alcançado as promessas; mas tendo-as visto e saudado, de longe, confessaram que eram estrangeiros e peregrinos na terra.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 14, 'Ora, os que tais coisas dizem, mostram que estão buscando uma pátria.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 15, 'E se, na verdade, se lembrassem daquela donde haviam saído, teriam oportunidade de voltar.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 16, 'Mas agora desejam uma pátria melhor, isto é, a celestial. Pelo que também Deus não se envergonha deles, de ser chamado seu Deus, porque já lhes preparou uma cidade.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 17, 'Pela fé Abraão, sendo provado, ofereceu Isaque; sim, ia oferecendo o seu unigênito aquele que recebera as promessas,', 1, CURRENT_TIMESTAMP, false),
(58, 11, 18, 'e a quem se havia dito: Em Isaque será chamada a tua descendência,', 1, CURRENT_TIMESTAMP, false),
(58, 11, 19, 'julgando que Deus era poderoso para até dos mortos o ressuscitar; e daí também em figura o recobrou.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 20, 'Pela fé Isaque abençoou Jacó e a Esaú, no tocante às coisas futuras.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 21, 'Pela fé Jacó, quando estava para morrer, abençoou cada um dos filhos de José, e adorou, inclinado sobre a extremidade do seu bordão.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 22, 'Pela fé José, estando próximo o seu fim, fez menção da saída dos filhos de Israel, e deu ordem acerca de seus ossos.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 23, 'Pela fé Moisés, logo ao nascer, foi escondido por seus pais durante três meses, porque viram que o menino era formoso; e não temeram o decreto do rei.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 24, 'Pela fé Moisés, sendo já homem, recusou ser chamado filho da filha de Faraó,', 1, CURRENT_TIMESTAMP, false),
(58, 11, 25, 'escolhendo antes ser maltratado com o povo de Deus do que ter por algum tempo o gozo do pecado,', 1, CURRENT_TIMESTAMP, false),
(58, 11, 26, 'tendo por maiores riquezas o opróbrio de Cristo do que os tesouros do Egito; porque tinha em vista a recompensa.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 27, 'Pela fé deixou o Egito, não temendo a ira do rei; porque ficou firme, como quem vê aquele que é invisível.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 28, 'Pela fé celebrou a páscoa e a aspersão do sangue, para que o destruidor dos primogênitos não lhes tocasse.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 29, 'Pela fé os israelitas atravessaram o Mar Vermelho, como por terra seca; e tentando isso os egípcios, foram afogados.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 30, 'Pela fé caíram os muros de Jericó, depois de rodeados por sete dias.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 31, 'Pela fé Raabe, a meretriz, não pereceu com os desobedientes, tendo acolhido em paz os espias.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 32, 'E que mais direi? Pois me faltará o tempo, se eu contar de Gideão, de Baraque, de Sansão, de Jefté, de Davi, de Samuel e dos profetas;', 1, CURRENT_TIMESTAMP, false),
(58, 11, 33, 'os quais por meio da fé venceram reinos, praticaram a justiça, alcançaram promessas, fecharam a boca dos leões,', 1, CURRENT_TIMESTAMP, false),
(58, 11, 34, 'apagaram a força do fogo, escaparam ao fio da espada, da fraqueza tiraram forças, tornaram-se poderosos na guerra, puseram em fuga exércitos estrangeiros.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 35, 'As mulheres receberam pela ressurreição os seus mortos; uns foram torturados, não aceitando o seu livramento, para alcançarem uma melhor ressurreição;', 1, CURRENT_TIMESTAMP, false),
(58, 11, 36, 'e outros experimentaram escárnios e açoites, e ainda cadeias e prisões.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 37, 'Foram apedrejados e tentados; foram serrados ao meio; morreram ao fio da espada; andaram vestidos de peles de ovelhas e de cabras, necessitados, aflitos e maltratados', 1, CURRENT_TIMESTAMP, false),
(58, 11, 38, '{dos quais o mundo não era digno}, errantes pelos desertos e montes, e pelas covas e cavernas da terra.', 1, CURRENT_TIMESTAMP, false),
(58, 11, 39, 'E todos estes, embora tendo recebido bom testemunho pela fé, contudo não alcançaram a promessa;', 1, CURRENT_TIMESTAMP, false),
(58, 11, 40, 'visto que Deus provera alguma coisa melhor a nosso respeito, para que eles, sem nós, não fossem aperfeiçoados.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 1, 'Portanto, nós também, pois estamos rodeados de tão grande nuvem de testemunhas, deixemos todo embaraço, e o pecado que tão de perto nos rodeia, e corramos com perseverança a carreira que nos está proposta,', 1, CURRENT_TIMESTAMP, false),
(58, 12, 2, 'fitando os olhos em Jesus, autor e consumador da nossa fé, o qual, pelo gozo que lhe está proposto, suportou a cruz, desprezando a ignomínia, e está assentado à direita do trono de Deus.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 3, 'Considerai, pois aquele que suportou tal contradição dos pecadores contra si mesmo, para que não vos canseis, desfalecendo em vossas almas.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 4, 'Ainda não resististes até o sangue, combatendo contra o pecado;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 5, 'e já vos esquecestes da exortação que vos admoesta como a filhos: Filho meu, não desprezes a correção do Senhor, nem te desanimes quando por ele és repreendido;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 6, 'pois o Senhor corrige ao que ama, e açoita a todo o que recebe por filho.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 7, 'É para disciplina que sofreis; Deus vos trata como a filhos; pois qual é o filho a quem o pai não corrija?', 1, CURRENT_TIMESTAMP, false),
(58, 12, 8, 'Mas, se estais sem disciplina, da qual todos se têm tornado participantes, sois então bastardos, e não filhos.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 9, 'Além disto, tivemos nossos pais segundo a carne, para nos corrigirem, e os olhávamos com respeito; não nos sujeitaremos muito mais ao Pai dos espíritos, e viveremos?', 1, CURRENT_TIMESTAMP, false),
(58, 12, 10, 'Pois aqueles por pouco tempo nos corrigiam como bem lhes parecia, mas este, para nosso proveito, para sermos participantes da sua santidade.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 11, 'Na verdade, nenhuma correção parece no momento ser motivo de gozo, porém de tristeza; mas depois produz um fruto pacífico de justiça nos que por ele têm sido exercitados.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 12, 'Portanto levantai as mãos cansadas, e os joelhos vacilantes,', 1, CURRENT_TIMESTAMP, false),
(58, 12, 13, 'e fazei veredas direitas para os vossos pés, para que o que é manco não se desvie, antes seja curado.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 14, 'Segui a paz com todos, e a santificação, sem a qual ninguém verá o Senhor,', 1, CURRENT_TIMESTAMP, false),
(58, 12, 15, 'tendo cuidado de que ninguém se prive da graça de Deus, e de que nenhuma raiz de amargura, brotando, vos perturbe, e por ela muitos se contaminem;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 16, 'e ninguém seja devasso, ou profano como Esaú, que por uma simples refeição vendeu o seu direito de primogenitura.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 17, 'Porque bem sabeis que, querendo ele ainda depois herdar a bênção, foi rejeitado; porque não achou lugar de arrependimento, ainda que o buscou diligentemente com lágrimas.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 18, 'Pois não tendes chegado ao monte palpável, aceso em fogo, e à escuridão, e às trevas, e à tempestade,', 1, CURRENT_TIMESTAMP, false),
(58, 12, 19, 'e ao sonido da trombeta, e à voz das palavras, a qual os que a ouviram rogaram que não se lhes falasse mais;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 20, 'porque não podiam suportar o que se lhes mandava: Se até um animal tocar o monte, será apedrejado.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 21, 'E tão terrível era a visão, que Moisés disse: Estou todo aterrorizado e trêmulo.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 22, 'Mas tendes chegado ao Monte Sião, e à cidade do Deus vivo, à Jerusalém celestial, a miríades de anjos;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 23, 'à universal assembléia e igreja dos primogênitos inscritos nos céus, e a Deus, o juiz de todos, e aos espíritos dos justos aperfeiçoados;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 24, 'e a Jesus, o mediador de um novo pacto, e ao sangue da aspersão, que fala melhor do que o de Abel.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 25, 'Vede que não rejeiteis ao que fala; porque, se não escaparam aqueles quando rejeitaram o que sobre a terra os advertia, muito menos escaparemos nós, se nos desviarmos daquele que nos adverte lá dos céus;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 26, 'a voz do qual abalou então a terra; mas agora tem ele prometido, dizendo: Ainda uma vez hei de abalar não só a terra, mas também o céu.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 27, 'Ora, esta palavra-Ainda uma vez-significa a remoção das coisas abaláveis, como coisas criadas, para que permaneçam as coisas inabaláveis.', 1, CURRENT_TIMESTAMP, false),
(58, 12, 28, 'Pelo que, recebendo nós um reino que não pode ser abalado, retenhamos a graça, pela qual sirvamos a Deus agradavelmente, com reverência e temor;', 1, CURRENT_TIMESTAMP, false),
(58, 12, 29, 'pois o nosso Deus é um fogo consumidor.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 1, 'Permaneça o amor fraternal.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 2, 'Não vos esqueçais da hospitalidade, porque por ela alguns, sem o saberem, hospedaram anjos.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 3, 'Lembrai-vos dos presos, como se estivésseis presos com eles, e dos maltratados, como sendo-o vós mesmos também no corpo.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 4, 'Honrado seja entre todos o matrimônio e o leito sem mácula; pois aos devassos e adúlteros, Deus os julgará.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 5, 'Seja a vossa vida isenta de ganância, contentando-vos com o que tendes; porque ele mesmo disse: Não te deixarei, nem te desampararei.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 6, 'De modo que com plena confiança digamos: O Senhor é quem me ajuda, não temerei; que me fará o homem?', 1, CURRENT_TIMESTAMP, false),
(58, 13, 7, 'Lembrai-vos dos vossos guias, os quais vos falaram a palavra de Deus, e, atentando para o êxito da sua carreira, imitai-lhes a fé.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 8, 'Jesus Cristo é o mesmo, ontem, e hoje, e eternamente.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 9, 'Não vos deixeis levar por doutrinas várias e estranhas; porque bom é que o coração se fortifique com a graça, e não com alimentos, que não trouxeram proveito algum aos que com eles se preocuparam.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 10, 'Temos um altar, do qual não têm direito de comer os que servem ao tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 11, 'Porque os corpos dos animais, cujo sangue é trazido para dentro do santo lugar pelo sumo sacerdote como oferta pelo pecado, são queimados fora do arraial.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 12, 'Por isso também Jesus, para santificar o povo pelo seu próprio sangue, sofreu fora da porta.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 13, 'Saiamos pois a ele fora do arraial, levando o seu opróbrio.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 14, 'Porque não temos aqui cidade permanente, mas buscamos a vindoura.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 15, 'Por ele, pois, ofereçamos sempre a Deus sacrifício de louvor, isto é, o fruto dos lábios que confessam o seu nome.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 16, 'Mas não vos esqueçais de fazer o bem e de repartir com outros, porque com tais sacrifícios Deus se agrada.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 17, 'Obedecei a vossos guias, sendo-lhes submissos; porque velam por vossas almas como quem há de prestar contas delas; para que o façam com alegria e não gemendo, porque isso não vos seria útil.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 18, 'Orai por nós, porque estamos persuadidos de que temos boa consciência, sendo desejosos de, em tudo, portar-nos corretamente.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 19, 'E com instância vos exorto a que o façais, para que eu mais depressa vos seja restituído.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 20, 'Ora, o Deus de paz, que pelo sangue do pacto eterno tornou a trazer dentre os mortos a nosso Senhor Jesus, grande pastor das ovelhas,', 1, CURRENT_TIMESTAMP, false),
(58, 13, 21, 'vos aperfeiçoe em toda boa obra, para fazerdes a sua vontade, operando em nós o que perante ele é agradável, por meio de Jesus Cristo, ao qual seja glória para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 22, 'Rogo-vos, porém, irmãos, que suporteis estas palavras de exortação, pois vos escrevi em poucas palavras.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 23, 'Sabei que o irmão Timóteo já está solto, com o qual, se ele vier brevemente, vos verei.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 24, 'Saudai a todos os vossos guias e a todos os santos. Os de Itália vos saúdam.', 1, CURRENT_TIMESTAMP, false),
(58, 13, 25, 'A graça seja com todos vós.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 1, 'As palavras de Jeremias, filho de Hilquias, um dos sacerdotes que estavam em Anatote, na terra de Benjamim;', 1, CURRENT_TIMESTAMP, false),
(24, 1, 2, 'ao qual veio a palavra do Senhor, nos dias de Josias, filho de Amom, rei de Judá, no décimo terceiro ano do seu reinado;', 1, CURRENT_TIMESTAMP, false),
(24, 1, 3, 'e lhe veio também nos dias de Jeoiaquim, filho de Josias, rei de Judá, até o fim do ano undécimo de Zedequias, filho de Josias, rei de Judá, até que Jerusalém foi levada em cativeiro no quinto mês.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 4, 'Ora veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 1, 5, 'Antes que eu te formasse no ventre te conheci, e antes que saísses da madre te santifiquei; às nações te dei por profeta.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 6, 'Então disse eu: Ah, Senhor Deus! Eis que não sei falar; porque sou um menino.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 7, 'Mas o Senhor me respondeu: Não digas: Eu sou um menino; porque a todos a quem eu te enviar, irás; e tudo quanto te mandar dirás.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 8, 'Não temas diante deles; pois eu seu contigo para te livrar, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 9, 'Então estendeu o Senhor a mão, e tocou-me na boca; e disse-me o Senhor: Eis que ponho as minhas palavras na tua boca.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 10, 'Olha, ponho-te neste dia sobre as nações, e sobre os reinos, para arrancares e derribares, para destruíres e arruinares; e também para edificares e plantares.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 11, 'E veio a mim a palavra do Senhor, dizendo: Que é que vês, Jeremias? Eu respondi: Vejo uma vara de amendoeira.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 12, 'Então me disse o Senhor: Viste bem; porque eu velo sobre a minha palavra para a cumprir.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 13, 'Veio a mim a palavra do Senhor segunda vez, dizendo: Que é que vês? E eu disse: Vejo uma panela a ferver, que se apresenta da banda do norte.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 14, 'Ao que me disse o Senhor: Do norte se estenderá o mal sobre todos os habitantes da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 15, 'Pois estou convocando todas as famílias dos reinos do norte, diz o Senhor; e, vindo, porá cada um o seu trono à entrada das portas de Jerusalém, e contra todos os seus muros em redor e contra todas as cidades de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 16, 'E pronunciarei contra eles os meus juízos, por causa de toda a sua malícia; pois me deixaram a mim, e queimaram incenso a deuses estranhos, e adoraram as obras das suas mãos.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 17, 'Tu, pois, cinge os teus lombos, e levanta-te, e dêem-lhes tudo quanto eu te ordenar; não desanimes diante deles, para que eu não te desanime diante deles.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 18, 'Eis que hoje te ponho como cidade fortificada, e como coluna de ferro e muros de bronze contra toda a terra, contra os reis de Judá, contra os seus príncipes, contra os seus sacerdotes, e contra o povo da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 1, 19, 'E eles pelejarão contra ti, mas não prevalecerão; porque eu sou contigo, diz o Senhor, para te livrar.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 1, 'Veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 2, 2, 'Vai, e clama aos ouvidos de Jerusalém, dizendo: Assim diz o Senhor: Lembro-me, a favor de ti, da devoção da tua mocidade, do amor dos teus desposórios, de como me seguiste no deserto, numa terra não semeada.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 3, 'Então Israel era santo para o Senhor, primícias da sua novidade; todos os que o devoravam eram tidos por culpados; o mal vinha sobre eles, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 4, 'Ouvi a palavra do Senhor, ó casa de Jacó, e todas as famílias da casa de Israel;', 1, CURRENT_TIMESTAMP, false),
(24, 2, 5, 'assim diz o Senhor: Que injustiça acharam em mim vossos pais, para se afastarem de mim, indo após a vaidade, e tornando-se levianos?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 6, 'Eles não perguntaram: Onde está o Senhor, que nos fez subir da terra do Egito? que nos enviou através do deserto, por uma terra de charnecas e de covas, por uma terra de sequidão e densas trevas, por uma terra em que ninguém transitava, nem morava?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 7, 'E eu vos introduzi numa terra fértil, para comerdes o seu fruto e o seu bem; mas quando nela entrastes, contaminastes a minha terra, e da minha herança fizestes uma abominação.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 8, 'Os sacerdotes não disseram: Onde está o Senhor? E os que tratavam da lei não me conheceram, e os governadores prevaricaram contra mim, e os profetas profetizaram por Baal, e andaram após o que é de nenhum proveito.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 9, 'Portanto ainda contenderei convosco, diz o Senhor; e até com os filhos de vossos filhos contenderei.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 10, 'Pois passai às ilhas de Quitim, e vede; enviai a Quedar, e atentai bem; vede se jamais sucedeu coisa semelhante.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 11, 'Acaso trocou alguma nação os seus deuses, que contudo não são deuses? Mas o meu povo trocou a sua glória por aquilo que é de nenhum proveito.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 12, 'Espantai-vos disto, ó céus, e horrorizai-vos! ficai verdadeiramente desolados, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 13, 'Porque o meu povo fez duas maldades: a mim me deixaram, o manancial de águas vivas, e cavaram para si cisternas, cisternas rotas, que não retêm as águas.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 14, 'Acaso é Israel um servo? E ele um escravo nascido em casa? Por que, pois, veio a ser presa?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 15, 'Os leões novos rugiram sobre ele, e levantaram a sua voz; e fizeram da terra dele uma desolação; as suas cidades se queimaram, e ninguém habita nelas.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 16, 'Até os filhos de Mênfis e de Tapanes te quebraram o alto da cabeça.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 17, 'Porventura não trouxeste isso sobre ti mesmo, deixando o Senhor teu Deus no tempo em que ele te guiava pelo caminho?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 18, 'Agora, pois, que te importa a ti o caminho do Egito, para beberes as águas do Nilo? e que te importa a ti o caminho da Assíria, para beberes as águas do Eufrates?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 19, 'A tua malícia te castigará, e as tuas apostasias te repreenderão; sabe, pois, e vê, que má e amarga coisa é o teres deixado o Senhor teu Deus, e o não haver em ti o temor de mim, diz o Senhor Deus dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 20, 'Já há muito quebraste o teu jugo, e rompeste as tuas ataduras, e disseste: Não servirei: Pois em todo outeiro alto e debaixo de toda árvore frondosa te deitaste, fazendo-te prostituta.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 21, 'Todavia eu mesmo te plantei como vide excelente, uma semente inteiramente fiel; como, pois, te tornaste para mim uma planta degenerada, de vida estranha?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 22, 'Pelo que, ainda que te laves com salitre, e uses muito sabão, a mancha da tua iniqüidade está diante de mim, diz o Senhor Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 23, 'Como dizes logo: Não estou contaminada nem andei após Baal? Vê o teu caminho no vale, conhece o que fizeste; dromedária ligeira és, que anda torcendo os seus caminhos;', 1, CURRENT_TIMESTAMP, false),
(24, 2, 24, 'asna selvagem acostumada ao deserto e que no ardor do cio sorve o vento; quem lhe pode impedir o desejo? Dos que a buscarem, nenhum precisa cansar-se; pois no mês dela, achá-la-ão.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 25, 'Evita que o teu pé ande descalço, e que a tua garganta tenha sede. Mas tu dizes: Não há esperança; porque tenho amado os estranhos, e após eles andarei.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 26, 'Como fica confundido o ladrão quando o apanham, assim se confundem os da casa de Israel; eles, os seus reis, os seus príncipes, e os seus sacerdotes, e os seus profetas,', 1, CURRENT_TIMESTAMP, false),
(24, 2, 27, 'que dizem ao pau: Tu és meu pai; e à pedra: Tu me geraste. Porque me viraram as costas, e não o rosto; mas no tempo do seu aperto dir-me-ão: Levanta-te, e salvamos.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 28, 'Mas onde estão os teus deuses que fizeste para ti? Que se levantem eles, se te podem livrar no tempo da tua tribulação; porque os teus deuses, ó Judá, são tão numerosos como as tuas cidades.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 29, 'Por que disputais comigo? Todos vós transgredistes contra mim diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 30, 'Em vão castiguei os vossos filhos; eles não aceitaram a correção; a vossa espada devorou os vossos profetas como um leão destruidor.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 31, 'Ó geração, considerai vós a palavra do Senhor: Porventura tenho eu sido para Israel um deserto? ou uma terra de espessa escuridão? Por que pois diz o meu povo: Andamos à vontade; não tornaremos mais a ti?', 1, CURRENT_TIMESTAMP, false),
(24, 2, 32, 'Porventura esquece-se a virgem dos seus enfeites, ou a esposa dos seus cendais? todavia o meu povo se esqueceu de mim por inumeráveis dias.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 33, 'Como ornamentas o teu caminho, para buscares o amor! de sorte que até às malignas ensinaste os teus caminhos.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 34, 'Até nas orlas dos teus vestidos se achou o sangue dos pobres inocentes; e não foi no lugar do arrombamento que os achaste; mas apesar de todas estas coisas,', 1, CURRENT_TIMESTAMP, false),
(24, 2, 35, 'ainda dizes: Eu sou inocente; certamente a sua ira se desviou de mim. Eis que entrarei em juízo contigo, porquanto dizes: Não pequei.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 36, 'Por que te desvias tanto, mudando o teu caminho? Também pelo Egito serás envergonhada, como já foste envergonhada pela Assíria.', 1, CURRENT_TIMESTAMP, false),
(24, 2, 37, 'Também daquele sairás com as mães sobre a tua cabeça; porque o Senhor rejeitou as tuas confianças, e não prosperarás com elas.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 1, 'Eles dizem: Se um homem despedir sua mulher, e ela se desligar dele, e se ajuntar a outro homem, porventura tornará ele mais para ela? Não se poluiria de todo aquela terra? Ora, tu te maculaste com muitos amantes; mas ainda assim, torna para mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 2, 'Levanta os teus olhos aos altos escalvados, e vê: onde é o lugar em que não te prostituíste? Nos caminhos te assentavas, esperando-os, como o árabe no deserto. Manchaste a terra com as tuas devassidões e com a tua malícia.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 3, 'Pelo que foram retidas as chuvas copiosas, e não houve chuva tardia; contudo tens a fronte de uma prostituta, e não queres ter vergonha.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 4, 'Não me invocaste há pouco, dizendo: Pai meu, tu és o guia da minha mocidade;', 1, CURRENT_TIMESTAMP, false),
(24, 3, 5, 'Reterá ele para sempre a sua ira? ou indignar-se-á continuamente? Eis que assim tens dito; porém tens feito todo o mal que pudeste.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 6, 'Disse-me mais o Senhor nos dias do rei Josias: Viste, porventura, o que fez a apóstata Israel, como se foi a todo monte alto, e debaixo de toda árvore frondosa, e ali andou prostituindo-se?', 1, CURRENT_TIMESTAMP, false),
(24, 3, 7, 'E eu disse: Depois que ela tiver feito tudo isso, voltará para mim. Mas não voltou; e viu isso a sua aleivosa irmã Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 8, 'Sim viu que, por causa de tudo isso, por ter cometido adultério a pérfida Israel, a despedi, e lhe dei o seu libelo de divórcio, que a aleivosa Judá, sua irmã, não temeu; mas se foi e também ela mesma se prostituiu.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 9, 'E pela leviandade da sua prostituição contaminou a terra, porque adulterou com a pedra e com o pau.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 10, 'Contudo, apesar de tudo isso a sua aleivosa irmã Judá não voltou para mim de todo o seu coração, mas fingidamente, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 11, 'E o Senhor me disse: A pérfida Israel mostrou-se mais justa do que a aleivosa Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 12, 'Vai, pois, e apregoa estas palavras para a banda do norte, e diz: Volta, ó pérfida Israel, diz o Senhor. Não olharei em era para ti; porque misericordioso sou, diz o Senhor, e não conservarei para sempre a minha ira.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 13, 'Somente reconhece a tua iniqüidade: que contra o Senhor teu Deus transgrediste, e estendeste os teus favores para os estranhos debaixo de toda árvore frondosa, e não deste ouvidos à minha voz, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 14, 'Voltai, ó filhos pérfidos, diz o Senhor; porque eu sou como esposo para vós; e vos tomarei, a um de uma cidade, e a dois de uma família; e vos levarei a Sião;', 1, CURRENT_TIMESTAMP, false),
(24, 3, 15, 'e vos darei pastores segundo o meu coração, os quais vos apascentarão com ciência e com inteligência.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 16, 'E quando vos tiverdes multiplicado e frutificado na terra, naqueles dias, diz o Senhor, nunca mais se dirá: A arca do pacto do Senhor; nem lhes virá ela ao pensamento; nem dela se lembrarão; nem a visitarão; nem se fará mais.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 17, 'Naquele tempo chamarão a Jerusalém o trono do Senhor; e todas as nações se ajuntarão a ela, em nome do Senhor, a Jerusalém; e não mais andarão obstinadamente segundo o propósito do seu coração maligno.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 18, 'Naqueles dias andará a casa de Judá com a casa de Israel; e virão juntas da terra do norte, para a terra que dei em herança a vossos pais.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 19, 'Pensei como te poria entre os filhos, e te daria a terra desejável, a mais formosa herança das nações. Também pensei que me chamarias meu Pai, e que de mim não te desviarias.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 20, 'Deveras, como a mulher se aparta aleivosamente do seu marido, assim aleivosamente te houveste comigo, ó casa de Israel, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 21, 'Nos altos escalvados se ouve uma voz, o pranto e as súplicas dos filhos de Israel; porque perverteram o seu caminho, e se esqueceram do Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 22, 'Voltai, ó filhos infiéis, eu curarei a vossa infidelidade. Responderam eles: Eis-nos aqui, vimos a ti, porque tu és o Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 23, 'Certamente em vão se confia nos outeiros e nas orgias nas montanhas; deveras no Senhor nosso Deus está a salvação de Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 24, 'A coisa vergonhosa, porém, devorou o trabalho de nossos pais desde a nossa mocidade os seus rebanhos e os seus gados os seus filhos e as suas filhas.', 1, CURRENT_TIMESTAMP, false),
(24, 3, 25, 'Deitemo-nos em nossa vergonha, e cubra-nos a nossa confusão, porque temos pecado contra o Senhor nosso Deus, nós e nossos pais, desde a nossa mocidade até o dia de hoje; e não demos ouvidos à voz do Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 1, 'Se voltares, ó Israel, diz o Senhor, se voltares para mim e tirares as tuas abominações de diante de mim, e não andares mais vagueando;', 1, CURRENT_TIMESTAMP, false),
(24, 4, 2, 'e se jurares: Como vive o Senhor, na verdade, na justiça e na retidão; então nele se bendirão as nações, e nele se gloriarão.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 3, 'Porque assim diz o Senhor aos homens de Judá e a Jerusalém: Lavrai o vosso terreno alqueivado, e não semeeis entre espinhos.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 4, 'Circuncidai-vos ao Senhor, e tirai os prepúcios do vosso coração, ó homens de Judá e habitadores de Jerusalém, para que a minha indignação não venha a sair como fogo, e arda de modo que ninguém o possa apagar, por causa da maldade das vossas obras.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 5, 'Anunciai em Judá, e publicai em Jerusalém; e dizei: Tocai a trombeta na terra; gritai em alta voz, dizendo: Ajuntai-vos, e entremos nas cidades fortificadas.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 6, 'Arvorai um estandarte no caminho para Sião; buscai refúgio, não demoreis; porque eu trago do norte um mal, sim, uma grande destruição.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 7, 'Subiu um leão da sua ramada, um destruidor de nações; ele já partiu, saiu do seu lugar para fazer da tua terra uma desolação, a fim de que as tuas cidades sejam assoladas, e ninguém habite nelas.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 8, 'Por isso cingi-vos de saco, lamentai, e uivai, porque o ardor da ira do Senhor não se desviou de nós.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 9, 'Naquele dia, diz o Senhor, desfalecerá o coração do rei e o coração dos príncipes; os sacerdotes pasmarão, e os profetas se maravilharão.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 10, 'Então disse eu: Ah, Senhor Deus! verdadeiramente trouxeste grande ilusão a este povo e a Jerusalém, dizendo: Tereis paz; entretanto a espada penetra-lhe até a alma.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 11, 'Naquele tempo se dirá a este povo e a Jerusalém: Um vento abrasador, vindo dos altos escalvados no deserto, aproxima-se da filha do meu povo, não para cirandar, nem para alimpar,', 1, CURRENT_TIMESTAMP, false),
(24, 4, 12, 'mas um vento forte demais para isto virá da minha parte; agora também pronunciarei eu juízos contra eles.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 13, 'Eis que vem subindo como nuvens, como o redemoinho são os seus carros; os seus cavalos são mais ligeiros do que as águias. Ai de nós! pois estamos arruinados!', 1, CURRENT_TIMESTAMP, false),
(24, 4, 14, 'Lava o teu coração da maldade, ó Jerusalém, para que sejas salva; até quando permanecerão em ti os teus maus pensamentos?', 1, CURRENT_TIMESTAMP, false),
(24, 4, 15, 'Porque uma voz anuncia desde Dã, e proclama a calamidade desde o monte de Efraim.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 16, 'Anunciai isto às nações; eis, proclamai contra Jerusalém que vigias vêm de uma terra remota; eles levantam a voz contra as cidades de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 17, 'Como guardas de campo estão contra ela ao redor; porquanto ela se rebelou contra mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 18, 'O teu caminho e as tuas obras te trouxeram essas coisas; essa e a tua iniquidade, e amargosa é, chegando até o coração.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 19, 'Ah, entranhas minhas, entranhas minhas! Eu me torço em dores! Paredes do meu coração! O meu coração se aflige em mim. Não posso calar; porque tu, ó minha alma, ouviste o som da trombeta e o alarido da guerra.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 20, 'Destruição sobre destruição se apregoa; porque já toda a terra está assolada; de repente são destruídas as minhas tendas, e as minhas cortinas num momento.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 21, 'Até quando verei o estandarte, e ouvirei a voz da trombeta?', 1, CURRENT_TIMESTAMP, false),
(24, 4, 22, 'Deveras o meu povo é insensato, já me não conhece; são filhos obtusos, e não entendidos; são sábios para fazerem o mal, mas não sabem fazer o bem.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 23, 'Observei a terra, e eis que era sem forma e vazia; também os céus, e não tinham a sua luz.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 24, 'Observei os montes, e eis que estavam tremendo; e todos os outeiros estremeciam.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 25, 'Observei e eis que não havia homem algum, e todas as aves do céu tinham fugido.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 26, 'Vi também que a terra fértil era um deserto, e todas as suas cidades estavam derrubadas diante do Senhor, diante do furor da sua ira.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 27, 'Pois assim diz o Senhor: Toda a terra ficará assolada; de todo, porém, não a consumirei.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 28, 'Por isso lamentará a terra, e os céus em cima se enegrecerão; porquanto assim o disse eu, assim o propus, e não me arrependi, nem me desviarei disso.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 29, 'Ao clamor dos cavaleiros e dos flecheiros fogem todas as cidades; entram pelas matas, e trepam pelos penhascos; todas as cidades ficam desamparadas, e já ninguém habita nelas.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 30, 'Agora, pois, ó assolada, que farás? Embora te vistas de escarlate, e te adornes com enfeites de ouro, embora te pintes em volta dos olhos com antimônio, debalde te farias bela; os teus amantes te desprezam, e procuram tirar-te a vida.', 1, CURRENT_TIMESTAMP, false),
(24, 4, 31, 'Pois ouvi uma voz, como a de mulher que está de parto, a angústia como a de quem dá à luz o seu primeiro filho; a voz da filha de Sião, ofegante, que estende as mãos, dizendo: Ai de mim agora! porque a minha alma desfalece por causa dos assassinos.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 1, 'Dai voltas às ruas de Jerusalém, e vede agora, e informai-vos, e buscai pelas suas praças a ver se podeis achar um homem, se há alguém que pratique a justiça, que busque a verdade; e eu lhe perdoarei a ela.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 2, 'E ainda que digam: Vive o Senhor; de certo falsamente juram.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 3, 'Ó Senhor, acaso não atentam os teus olhos para a verdade? feriste-os, porém não lhes doeu; consumiste-os, porém recusaram receber a correção; endureceram as suas faces mais do que uma rocha; recusaram-se a voltar.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 4, 'Então disse eu: Deveras eles são uns pobres; são insensatos, pois não sabem o caminho do Senhor, nem a justiça do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 5, 'Irei aos grandes, e falarei com eles; porque eles sabem o caminho do Senhor, e a justiça do seu Deus; mas aqueles de comum acordo quebraram o jugo, e romperam as ataduras.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 6, 'Por isso um leão do bosque os matará, um lobo dos desertos os destruirá; um leopardo vigia contra as suas cidades; todo aquele que delas sair será despedaçado; porque são muitas as suas transgressões, e multiplicadas as suas apostasias.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 7, 'Como poderei perdoar-te? pois teus filhos me abandonaram a mim, e juraram pelos que não são deuses; quando eu os tinha fartado, adulteraram, e em casa de meretrizes se ajuntaram em bandos.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 8, 'Como cavalos de lançamento bem nutridos, andavam rinchando cada um à mulher do seu próximo.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 9, 'Acaso não hei de castigá-los por causa destas coisas? diz o Senhor; ou não hei de vingar-me de uma nação como esta?', 1, CURRENT_TIMESTAMP, false),
(24, 5, 10, 'Subi aos seus muros, e destruí-os; não façais, porém, uma destruição final; tirai os seus ramos; porque não são do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 11, 'Porque aleivosissimamente se houveram contra mim a casa de Israel e a casa de Judá, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 12, 'Negaram ao Senhor, e disseram: Não é ele; nenhum mal nos sobrevirá; nem veremos espada nem fome.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 13, 'E até os profetas se farão como vento, e a palavra não está com eles; assim se lhes fará.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 14, 'Portanto assim diz o Senhor, o Deus dos exércitos: Porquanto proferis tal palavra, eis que converterei em fogo as minhas palavras na tua boca, e este povo em lenha, de modo que o fogo o consumirá.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 15, 'Eis que trago sobre vós uma nação de longe, ó casa de Israel, diz o Senhor; é uma nação durável, uma nação antiga, uma nação cuja língua ignoras, e não entenderás o que ela falar.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 16, 'A sua aljava é como uma sepultura aberta; todos eles são valentes.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 17, 'E comerão a tua sega e o teu pão, que teus filhos e tuas filhas haviam de comer; comerão os teus rebanhos e o teu gado; comerão a tua vide e a tua figueira; as tuas cidades fortificadas, em que confias, abatê-las-ão à espada.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 18, 'Contudo, ainda naqueles dias, diz o Senhor, não farei de vós uma destruição final.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 19, 'E quando disserdes: Por que nos fez o Senhor nosso Deus todas estas coisas? então lhes dirás: Como vós me deixastes, e servistes deuses estranhos na vossa terra, assim servireis estrangeiros, em terra que não e vossa.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 20, 'Anunciai isto na casa de Jacó, e proclamai-o em Judá, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 5, 21, 'Ouvi agora isto, ó povo insensato e sem entendimento, que tendes olhos e não vedes, que tendes ouvidos e não ouvis:', 1, CURRENT_TIMESTAMP, false),
(24, 5, 22, 'Não me temeis a mim? diz o Senhor; não tremeis diante de mim, que pus a areia por limite ao mar, por ordenança eterna, que ele não pode passar? Ainda que se levantem as suas ondas, não podem prevalecer; ainda que bramem, não a podem traspassar.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 23, 'Mas este povo é de coração obstinado e rebelde; rebelaram-se e foram-se.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 24, 'E não dizem no seu coração: Temamos agora ao Senhor nosso Deus, que dá chuva, tanto a temporã como a tardia, a seu tempo, e nos conserva as semanas determinadas da sega.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 25, 'As vossas iniqüidades desviaram estas coisas, e os vossos pecados apartaram de vos o bem.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 26, 'Porque ímpios se acham entre o meu povo; andam espiando, como espreitam os passarinheiros. Armam laços, apanham os homens.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 27, 'Qual gaiola cheia de pássaros, assim as suas casas estão cheias de dolo; por isso se engrandeceram, e enriqueceram.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 28, 'Engordaram-se, estão nédios; também excedem o limite da maldade; não julgam com justiça a causa dos órfãos, para que prospere, nem defendem o direito dos necessitados.', 1, CURRENT_TIMESTAMP, false),
(24, 5, 29, 'Acaso não hei de trazer o castigo por causa destas coisas? diz o senhor; ou não hei de vingar-me de uma nação como esta?', 1, CURRENT_TIMESTAMP, false),
(24, 5, 30, 'Coisa espantosa e horrenda tem-se feito na terra:', 1, CURRENT_TIMESTAMP, false),
(24, 5, 31, 'os profetas profetizam falsamente, e os sacerdotes dominam por intermédio deles; e o meu povo assim o deseja. Mas que fareis no fim disso?', 1, CURRENT_TIMESTAMP, false),
(24, 6, 1, 'Fugi para segurança vossa, filhos de Benjamim, do meio de Jerusalém! Tocai a buzina em Tecoa, e levantai o sinal sobre Bete-Haquerem; porque do norte vem surgindo um grande mal, sim, uma grande destruição.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 2, 'A formosa e delicada, a filha de Sião, eu a exterminarei.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 3, 'Contra ela virão pastores com os seus rebanhos; levantarão contra ela as suas tendas em redor e apascentarão, cada um no seu lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 4, 'Preparai a guerra contra ela; levantai-vos, e subamos ao meio-dia. Ai de nós! que já declina o dia, que já se vão estendendo as sombras da tarde.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 5, 'Levantai-vos, e subamos de noite, e destruamos os seus palácios.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 6, 'Porque assim diz o Senhor dos exércitos: Cortai as suas árvores, e levantai uma tranqueira contra Jerusalém. Esta é a cidade que há de ser castigada; só opressão há no meio dela.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 7, 'Como o poço conserva frescas as suas águas, assim ela conserva fresca a sua maldade; violência e estrago se ouvem nela; enfermidade e feridas há diante de mim continuadamente.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 8, 'Sê avisada, ó Jerusalém, para que não me aparte de ti; para que eu não te faça uma assolação, uma terra não habitada.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 9, 'Assim diz o Senhor dos exércitos: Na verdade respigarão o resto de Israel como uma vinha; torna a tua mão, como o vindimador, aos ramos.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 10, 'A quem falarei e testemunharei, para que ouçam? eis que os seus ouvidos estão incircuncisos, e eles não podem ouvir; eis que a palavra do Senhor se lhes tornou em opróbrio; nela não têm prazer.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 11, 'Pelo que estou cheio de furor do Senhor; estou cansado de o conter; derrama-o sobre os meninos pelas ruas, e sobre a assembléia dos jovens também; porque até o marido com a mulher serão presos, e o velho com o que está cheio de dias.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 12, 'As suas casas passarão a outros, como também os seus campos e as suas mulheres; porque estenderei a minha mão contra os habitantes da terra, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 13, 'Porque desde o menor deles até o maior, cada um se dá à avareza; e desde o profeta até o sacerdote, cada um procede perfidamente.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 14, 'Também se ocupam em curar superficialmente a ferida do meu povo, dizendo: Paz, paz; quando não há paz.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 15, 'Porventura se envergonharam por terem cometido abominação? Não, de maneira alguma; nem tampouco sabem que coisa é envergonhar-se. Portanto cairão entre os que caem; quando eu os visitar serão derribados, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 16, 'Assim diz o Senhor: Ponde-vos nos caminhos, e vede, e perguntai pelas veredas antigas, qual é o bom caminho, e andai por ele; e achareis descanso para as vossas almas. Mas eles disseram: Não andaremos nele.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 17, 'Também pus atalaias sobre vós dizendo: Estai atentos à voz da buzina. Mas disseram: Não escutaremos.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 18, 'Portanto ouvi, vós, nações, e informa-te tu, ó congregação, do que se faz entre eles!', 1, CURRENT_TIMESTAMP, false),
(24, 6, 19, 'Ouve tu, ó terra! Eis que eu trarei o mal sobre este povo, o próprio fruto dos seus pensamentos; porque não estão atentos às minhas palavras; e quanto à minha lei, rejeitaram-na.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 20, 'Para que, pois, me vem o incenso de Sabá, ou a melhor cana aromática de terras remotas? Vossos holocaustos não são aceitáveis, nem me agradam os vossos sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 21, 'Portanto assim diz o Senhor: Eis que armarei tropeços a este povo, e tropeçarão neles pais e filhos juntamente; o vizinho e o seu amigo perecerão.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 22, 'Assim diz o Senhor: Eis que um povo vem da terra do norte, e uma grande nação se levanta das extremidades da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 23, 'Arco e lança trarão; são cruéis, e não usam de misericórdia; a sua voz ruge como o mar, e em cavalos vêm montados, dispostos como homens para a batalha, contra ti, ó filha de Sião.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 24, 'Ao ouvirmos a notícia disso, afrouxam-se as nossas mãos; apoderam-se de nós angústia e dores, como as de parturiente.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 25, 'Não saiais ao campo, nem andeis pelo caminho; porque espada do inimigo e espanto há por todos os lados.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 26, 'Ó filha do meu povo, cingi-te de saco, e revolve-te na cinza; pranteia como por um filho único, em pranto de grande amargura; porque de repente virá o destruidor sobre nós.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 27, 'Por acrisolador e examinador te pus entre o meu povo, para que proves e examines o seu caminho.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 28, 'Todos eles são os mais rebeldes, e andam espalhando calúnias; são bronze e ferro; todos eles andam corruptamente.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 29, 'Já o fole se queimou; o chumbo se consumiu com o fogo; debalde continuam a fundição, pois os maus não são arrancados.', 1, CURRENT_TIMESTAMP, false),
(24, 6, 30, 'Prata rejeitada lhes chamam, porque o Senhor os rejeitou.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 1, 'A palavra que da parte do Senhor veio a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 7, 2, 'Põe-te à porta da casa do Senhor, e proclama ali esta palavra, e dize: Ouvi a palavra do Senhor, todos de Judá, os que entrais por estas portas, para adorardes ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 3, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Emendai os vossos caminhos e as vossas obras, e vos farei habitar neste lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 4, 'Não vos fieis em palavras falsas, dizendo: Templo do Senhor, templo do Senhor, templo do Senhor são estes.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 5, 'Mas, se deveras emendardes os vossos caminhos e as vossas obras; se deveras executardes a justiça entre um homem e o seu próximo;', 1, CURRENT_TIMESTAMP, false),
(24, 7, 6, 'se não oprimirdes o estrangeiro, e o órfão, e a viúva, nem derramardes sangue inocente neste lugar, nem andardes após outros deuses para vosso próprio mal,', 1, CURRENT_TIMESTAMP, false),
(24, 7, 7, 'então eu vos farei habitar neste lugar, na terra que dei a vossos pais desde os tempos antigos e para sempre.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 8, 'Eis que vós confiais em palavras falsas, que para nada são proveitosas.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 9, 'Furtareis vós, e matareis, e cometereis adultério, e jurareis falsamente, e queimareis incenso a Baal, e andareis após outros deuses que não conhecestes,', 1, CURRENT_TIMESTAMP, false),
(24, 7, 10, 'e então vireis, e vos apresentareis diante de mim nesta casa, que se chama pelo meu nome, e direis: Somos livres para praticardes ainda todas essas abominações?', 1, CURRENT_TIMESTAMP, false),
(24, 7, 11, 'Tornou-se, pois, esta casa, que se chama pelo meu nome, uma caverna de salteadores aos vossos olhos? Eis que eu, eu mesmo, vi isso, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 12, 'Mas ide agora ao meu lugar, que estava em Siló, onde, ao princípio, fiz habitar o meu nome, e vede o que lhe fiz, por causa da maldade do meu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 13, 'Agora, pois, porquanto fizestes todas estas obras, diz o Senhor, e quando eu vos falei insistentemente, vós não ouvistes, e quando vos chamei, não respondestes,', 1, CURRENT_TIMESTAMP, false),
(24, 7, 14, 'farei também a esta casa, que se chama pelo meu nome, na qual confiais, e a este lugar, que vos dei a vós e a vossos pais, como fiz a Siló.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 15, 'E eu vos lançarei da minha presença, como lancei todos os vossos irmãos, toda a linhagem de Efraim.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 16, 'Tu, pois, não ores por este povo, nem levantes por ele clamor ou oração, nem me importunes; pois eu não te ouvirei.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 17, 'Não vês tu o que eles andam fazendo nas cidades de Judá, e nas ruas de Jerusalém?', 1, CURRENT_TIMESTAMP, false),
(24, 7, 18, 'Os filhos apanham a lenha, e os pais acendem o fogo, e as mulheres amassam a farinha para fazerem bolos à rainha do céu, e oferecem libações a outros deuses, a fim de me provocarem à ira.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 19, 'Acaso é a mim que eles provocam à ira? diz o Senhor; não se provocam a si mesmos, para a sua própria confusão?', 1, CURRENT_TIMESTAMP, false),
(24, 7, 20, 'Portanto assim diz o Senhor Deus: Eis que a minha ira e o meu furor se derramarão sobre este lugar, sobre os homens e sobre os animais, sobre as árvores do campo e sobre os frutos da terra; sim, acender-se-á, e não se apagará.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 21, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Ajuntai os vossos holocaustos aos vossos sacrifícios, e comei a carne.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 22, 'Pois não falei a vossos pais no dia em que os tirei da terra do Egito, nem lhes ordenei coisa alguma acerca de holocaustos ou sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 23, 'Mas isto lhes ordenei: Dai ouvidos à minha voz, e eu serei o vosso Deus, e vós sereis o meu povo; andai em todo o caminho que eu vos mandar, para que vos vá bem.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 24, 'Mas não ouviram, nem inclinaram os seus ouvidos; porém andaram nos seus próprios conselhos, no propósito do seu coração malvado; e andaram para trás, e não para diante.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 25, 'Desde o dia em que vossos pais saíram da terra do Egito, até hoje, tenho-vos enviado insistentemente todos os meus servos, os profetas, dia após dia;', 1, CURRENT_TIMESTAMP, false),
(24, 7, 26, 'contudo não me deram ouvidos, nem inclinaram os seus ouvidos, mas endureceram a sua cerviz. Fizeram pior do que seus pais.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 27, 'Dir-lhes-ás pois todas estas palavras, mas não te darão ouvidos; chamá-los-ás, mas não te responderão.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 28, 'E lhes dirás: Esta é a nação que não obedeceu a voz do Senhor seu Deus e não aceitou a correção; já pereceu a verdade, e está exterminada da sua boca.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 29, 'Corta os teus cabelos, Jerusalém, e lança-os fora, e levanta um pranto sobre os altos escalvados; porque o Senhor já rejeitou e desamparou esta geração, objeto do seu furor.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 30, 'Porque os filhos de Judá fizeram o que era mau aos meus olhos, diz o Senhor; puseram as suas abominações na casa que se chama pelo meu nome, para a contaminarem.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 31, 'E edificaram os altos de Tofete, que está no Vale do filho de Hinom, para queimarem no fogo a seus filhos e a suas filhas, o que nunca ordenei, nem me veio à mente.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 32, 'Portanto, eis que vêm os dias, diz o Senhor, em que não se chamará mais Tofete, nem Vale do filho de Hinom, mas o Vale da Matança; pois enterrarão em Tofete, por não haver mais outro lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 33, 'E os cadáveres deste povo servirão de pasto às aves do céu e aos animais da terra; e ninguém os enxotará.', 1, CURRENT_TIMESTAMP, false),
(24, 7, 34, 'E farei cessar nas cidades de Judá, e nas ruas de Jerusalém, a voz de gozo e a voz de alegria, a voz de noivo e a voz de noiva; porque a terra se tornará em desolação.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 1, 'Naquele tempo, diz o Senhor, tirarão para fora das suas sepulturas os ossos dos reis de Judá, e os ossos dos seus príncipes, e os ossos dos sacerdotes, e os ossos dos profetas, e os ossos dos habitantes de Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(24, 8, 2, 'e serão expostos ao sol, e à lua, e a todo o exército do céu, a quem eles amaram, e a quem serviram , e após quem andaram, e a quem buscaram, e a quem adoraram; não serão recolhidos nem sepultados; serão como esterco sobre a face da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 3, 'E será escolhida antes a morte do que a vida por todos os que restarem desta raça maligna, que ficarem em todos os lugares onde os lancei, diz o senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 4, 'Dize-lhes mais: Assim diz o Senhor: porventura cairão os homens, e não se levantarão? desviar-se-ão, e não voltarão?', 1, CURRENT_TIMESTAMP, false),
(24, 8, 5, 'Por que, pois, se desvia este povo de Jerusalém com uma apostasia contínua? ele retém o engano, recusa-se a voltar.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 6, 'Eu escutei e ouvi; não falam o que é reto; ninguém há que se arrependa da sua maldade, dizendo: Que fiz eu? Cada um se desvia na sua carreira, como um cavalo que arremete com ímpeto na batalha.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 7, 'Até a cegonha no céu conhece os seus tempos determinados; e a rola, a andorinha, e o grou observam o tempo da sua arribação; mas o meu povo não conhece a ordenança do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 8, 'Como pois dizeis: Nós somos sábios, e a lei do Senhor está conosco? Mas eis que a falsa pena dos escribas a converteu em mentira.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 9, 'Os sábios são envergonhados, espantados e presos; rejeitaram a palavra do Senhor; que sabedoria, pois, têm eles?', 1, CURRENT_TIMESTAMP, false),
(24, 8, 10, 'Portanto darei suas mulheres a outros, e os seus campos aos conquistadores; porque desde o menor até o maior, cada um deles se dá à avareza; desde o profeta até o sacerdote, cada qual usa de falsidade.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 11, 'E curam a ferida da filha de meu povo levianamente, dizendo: Paz, paz; quando não há paz.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 12, 'Porventura se envergonham de terem cometido abominação? Não; de maneira alguma se envergonham, nem sabem que coisa é envergonhar-se. Portanto cairão entre os que caem; e no tempo em que eu os visitar, serão derribados, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 13, 'Quando eu os colheria, diz o Senhor, já não há uvas na vide, nem figos na figueira; até a folha está caída; e aquilo mesmo que lhes dei se foi deles.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 14, 'Por que nos assentamos ainda? juntai-vos e entremos nas cidades fortes, e ali pereçamos; pois o Senhor nosso Deus nos destinou a perecer e nos deu a beber água de fel; porquanto pecamos contra o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 15, 'Esperamos a paz, porém não chegou bem algum; e o tempo da cura, e eis o terror.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 16, 'Já desde Dã se ouve o resfolegar dos seus cavalos; a terra toda estremece à voz dos rinchos dos seus ginetes; porque vêm e devoram a terra e quanto nela há, a cidade e os que nela habitam.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 17, 'Pois eis que envio entre vós serpentes, basiliscos, contra os quais não há encantamento; e eles vos morderão, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 18, 'Oxalá que eu pudesse consolar-me na minha tristeza! O meu coração desfalece dentro de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 19, 'Eis o clamor da filha do meu povo, de toda a extensão da terra; Não está o Senhor em Sião? Não está nela o seu rei? Por que me provocaram a ira com as suas imagens esculpidas, com vaidades estranhas?', 1, CURRENT_TIMESTAMP, false),
(24, 8, 20, 'Passou a sega, findou o verão, e nós não estamos salvos.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 21, 'Estou quebrantado pela ferida da filha do meu povo; ando de luto; o espanto apoderou-se de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 8, 22, 'Porventura não há bálsamo em Gileade? ou não se acha lá médico? Por que, pois, não se realizou a cura da filha do meu povo?', 1, CURRENT_TIMESTAMP, false),
(24, 9, 1, 'Oxalá a minha cabeça se tornasse em águas, e os meus olhos numa fonte de lágrimas, para que eu chorasse de dia e de noite os mortos da filha do meu povo!', 1, CURRENT_TIMESTAMP, false),
(24, 9, 2, 'Oxalá que eu tivesse no deserto uma estalagem de viandantes, para poder deixar o meu povo, e me apartar dele! porque todos eles são adúlteros, um bando de aleivosos.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 3, 'E encurvam a língua, como se fosse o seu arco, para a mentira; fortalecem-se na terra, mas não para a verdade; porque avançam de malícia em malícia, e a mim me não conhecem, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 4, 'Guardai-vos cada um do seu próximo, e de irmão nenhum vos fieis; porque todo irmão não faz mais do que enganar, e todo próximo anda caluniando.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 5, 'E engana cada um a seu próximo, e nunca fala a verdade; ensinaram a sua língua a falar a mentira; andam-se cansando em praticar a iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 6, 'A tua habitação está no meio do engano; pelo engano recusam-se a conhecer-me, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 7, 'Portanto assim diz o Senhor dos exércitos: Eis que eu os fundirei e os provarei; pois, de que outra maneira poderia proceder com a filha do meu povo?', 1, CURRENT_TIMESTAMP, false),
(24, 9, 8, 'uma flecha mortífera é a língua deles; fala engano; com a sua boca fala cada um de paz com o seu próximo, mas no coração arma-lhe ciladas.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 9, 'Não hei de castigá-los por estas coisas? diz o Senhor; ou não me vingarei de uma nação tal como esta?', 1, CURRENT_TIMESTAMP, false),
(24, 9, 10, 'Pelos montes levantai choro e pranto, e pelas pastagens do deserto lamentação; porque já estão queimadas, de modo que ninguém passa por elas; nem se ouve mugido de gado; desde as aves dos céus até os animais, fugiram e se foram.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 11, 'E farei de Jerusalém montões de pedras, morada de chacais, e das cidades de Judá farei uma desolação, de sorte que fiquem sem habitantes.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 12, 'Quem é o homem sábio, que entenda isto? e a quem falou a boca do Senhor, para que o possa anunciar? Por que razão pereceu a terra, e se queimou como um deserto, de sorte que ninguém passa por ela?', 1, CURRENT_TIMESTAMP, false),
(24, 9, 13, 'E diz o Senhor: porque deixaram a minha lei, que lhes pus diante, e não deram ouvidos à minha voz, nem andaram nela,', 1, CURRENT_TIMESTAMP, false),
(24, 9, 14, 'antes andaram obstinadamente segundo o seu próprio coração, e após baalins, como lhes ensinaram os seus pais.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 15, 'Portanto assim diz o Senhor dos exércitos, Deus de Israel: Eis que darei de comer losna a este povo, e lhe darei a beber água de fel.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 16, 'Também os espalharei por entre nações que nem eles nem seus pais conheceram; e mandarei a espada após eles, até que venha a consumi-los.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 17, 'Assim diz o Senhor dos exércitos: Considerai, e chamai as carpideiras, para que venham; e mandai procurar mulheres hábeis, para que venham também;', 1, CURRENT_TIMESTAMP, false),
(24, 9, 18, 'e se apressem, e levantem o seu lamento sobre nós, para que se desfaçam em lágrimas os nossos olhos, e as nossas pálpebras destilem águas.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 19, 'Porque uma voz de pranto se ouviu de Sião: Como estamos arruinados! Estamos mui envergonhados, por termos deixado a terra, e por terem eles transtornado as nossas moradas.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 20, 'Contudo ouvi, vós, mulheres, a palavra do Senhor, e recebam os vossos ouvidos a palavra da sua boca; e ensinai a vossas filhas o pranto, e cada uma à sua vizinha a lamentação.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 21, 'Pois a morte subiu pelas nossas janelas, e entrou em nossos palácios, para exterminar das ruas as crianças, e das praças os mancebos.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 22, 'Fala: Assim diz o Senhor: Até os cadáveres dos homens cairão como esterco sobre a face do campo, e como gavela atrás do segador, e não há quem a recolha.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 23, 'Assim diz o Senhor: Não se glorie o sábio na sua sabedoria, nem se glorie o forte na sua força; não se glorie o rico nas suas riquezas;', 1, CURRENT_TIMESTAMP, false),
(24, 9, 24, 'mas o que se gloriar, glorie-se nisto: em entender, e em me conhecer, que eu sou o Senhor, que faço benevolência, juízo e justiça na terra; porque destas coisas me agrado, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 9, 25, 'Eis que vêm dias, diz o Senhor, em que castigarei a todo circuncidado pela sua incircuncisão:', 1, CURRENT_TIMESTAMP, false),
(24, 9, 26, 'ao Egito, a Judá e a Edom, aos filhos de Amom e a Moabe, e a todos os que cortam os cantos da sua cabeleira e habitam no deserto; pois todas as nações são incircuncisas, e toda a casa de Israel é incircuncisa de coração.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 1, 'Ouvi a palavra que o Senhor vos fala a vós, ó casa de Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 2, 'Assim diz o Senhor: Não aprendais o caminho das nações, nem vos espanteis com os sinais do céu; porque deles se espantam as nações,', 1, CURRENT_TIMESTAMP, false),
(24, 10, 3, 'pois os costumes dos povos são vaidade; corta-se do bosque um madeiro e se lavra com machado pelas mãos do artífice.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 4, 'Com prata e com ouro o enfeitam, com pregos e com martelos o firmam, para que não se mova.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 5, 'São como o espantalho num pepinal, e não podem falar; necessitam de quem os leve, porquanto não podem andar. Não tenhais receio deles, pois não podem fazer o mal, nem tampouco têm poder de fazer o bem.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 6, 'Ninguém há semelhante a ti, ó Senhor; és grande, e grande é o teu nome em poder.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 7, 'Quem te não temeria a ti, ó Rei das nações? pois a ti se deve o temor; porquanto entre todos os sábios das nações, e em todos os seus reinos ninguém há semelhante a ti.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 8, 'Mas eles todos são embrutecidos e loucos; a instrução dos ídolos é como o madeiro.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 9, 'Trazem de Társis prata em chapas, e ouro de Ufaz, trabalho do artífice, e das mãos do fundidor; seus vestidos são de azul e púrpura; obra de peritos são todos eles.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 10, 'Mas o Senhor é o verdadeiro Deus; ele é o Deus vivo e o Rei eterno, ao seu furor estremece a terra, e as nações não podem suportar a sua indignação.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 11, 'Assim lhes direis: Os deuses que não fizeram os céus e a terra, esses perecerão da terra e de debaixo dos céus.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 12, 'Ele fez a terra pelo seu poder; ele estabeleceu o mundo por sua sabedoria e com a sua inteligência estendeu os céus.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 13, 'Quando ele faz soar a sua voz, logo há tumulto de águas nos céus, e ele faz subir das extremidades da terra os vapores; faz os relâmpagos para a chuva, e dos seus tesouros faz sair o vento.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 14, 'Todo homem se embruteceu e não tem conhecimento; da sua imagem esculpida envergonha-se todo fundidor; pois as suas imagens fundidas são falsas, e nelas não há fôlego.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 15, 'Vaidade são, obra de enganos; no tempo da sua visitação virão a perecer.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 16, 'Não é semelhante a estes aquele que é a porção de Jacó; porque ele é o que forma todas as coisas, e Israel é a tribo da sua herança. Senhor dos exércitos é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 17, 'Tira do chão a tua trouxa, ó tu que habitas em lugar sitiado.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 18, 'Pois assim diz o Senhor: Eis que desta vez arrojarei como se fora com uma funda os moradores da terra, e os angustiarei, para que venham a senti-lo.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 19, 'Ai de mim, por causa do meu quebrantamento! a minha chaga me causa grande dor; mas eu havia dito: Certamente isto é minha enfermidade, e eu devo suporta-la.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 20, 'A minha tenda está destruída, e todas as minhas cordas estão rompidas; os meus filhos foram-se de mim, e não existem; ninguém há mais que estire a minha tenda, e que levante as minhas cortinas.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 21, 'Pois os pastores se embruteceram, e não buscaram ao Senhor; por isso não prosperaram, e todos os seus rebanhos se acham dispersos.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 22, 'Eis que vem uma voz de rumor, um grande tumulto da terra do norte, para fazer das cidades de Judá uma assolação, uma morada de chacais.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 23, 'Eu sei, ó Senhor, que não é do homem o seu caminho; nem é do homem que caminha o dirigir os seus passos.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 24, 'Corrige-me, ó Senhor, mas com medida justa; não na tua ira, para que não me reduzas a nada.', 1, CURRENT_TIMESTAMP, false),
(24, 10, 25, 'Derrama a tua indignação sobre as nações que não te conhecem, e sobre as famílias que não invocam o teu nome; porque devoraram a Jacó; sim, devoraram-no e consumiram-no, e assolaram a sua morada.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 1, 'A palavra que veio a Jeremias, da parte do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 11, 2, 'Ouvi as palavras deste pacto, e falai aos homens de Judá, e aos habitantes de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 3, 'Dize-lhes pois: Assim diz o Senhor, o Deus de Israel: Maldito o homem que não ouvir as palavras deste pacto,', 1, CURRENT_TIMESTAMP, false),
(24, 11, 4, 'que ordenei a vossos pais no dia em que os tirei da terra do Egito, da fornalha de ferro, dizendo: Ouvi a minha voz, e fazei conforme a tudo que vos mando; assim vós sereis o meu povo, e eu serei o vosso Deus;', 1, CURRENT_TIMESTAMP, false),
(24, 11, 5, 'para que eu confirme o juramento que fiz a vossos pais de dar-lhes uma terra que manasse leite e mel, como se vê neste dia. Então eu respondi, e disse: Amém, ó Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 6, 'Disse-me, pois, o Senhor: Proclama todas estas palavras nas cidades de Judá, e nas ruas de Jerusalém, dizendo: Ouvi as palavras deste pacto, e cumpri-as.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 7, 'Porque com instância admoestei a vossos pais, no dia em que os tirei da terra do Egito, até o dia de hoje, protestando persistentemente e dizendo: Ouvi a minha voz.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 8, 'Mas não ouviram, nem inclinaram os seus ouvidos; antes andaram cada um na obstinação do seu coração malvado; pelo que eu trouxe sobre eles todas as palavras deste pacto, as quais lhes ordenei que cumprissem, mas não o fizeram.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 9, 'Disse-me mais o Senhor: Uma conspiração se achou entre os homens de Judá, e entre os habitantes de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 10, 'Tornaram às iniqüidades de seus primeiros pais, que recusaram ouvir as minhas palavras; até se foram após outros deuses para os servir; a casa de Israel e a casa de Judá quebrantaram o meu pacto, que fiz com seus pais.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 11, 'Portanto assim diz o Senhor: Eis que estou trazendo sobre eles uma calamidade de que não poderão escapar; clamarão a mim, mas eu não os ouvirei.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 12, 'Então irão as cidades de Judá e os habitantes de Jerusalém e clamarão aos deuses a que eles queimam incenso; estes, porém, de maneira alguma os livrarão no tempo da sua calamidade.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 13, 'Pois, segundo o número das tuas cidades, são os teus deuses, ó Judá; e, segundo o número das ruas de Jerusalém, tendes levantado altares à impudência, altares para queimardes incenso a Baal.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 14, 'Tu, pois, não ores por este povo, nem levantes por eles clamor nem oração; porque não os ouvirei no tempo em que eles clamarem a mim por causa da sua calamidade.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 15, 'Que direito tem a minha amada na minha casa, visto que com muitos tem cometido grande abominação, e as carnes santas se desviaram de ti? Quando tu fazes mal, então andas saltando de prazer.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 16, 'Denominou-te o Senhor oliveira verde, formosa por seus deliciosos frutos; mas agora, à voz dum grande tumulto, acendeu fogo nela, e se quebraram os seus ramos.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 17, 'Porque o Senhor dos exércitos, que te plantou, pronunciou contra ti uma calamidade, por causa do grande mal que a casa de Israel e a casa de Judá fizeram, pois me provocaram à ira, queimando incenso a Baal.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 18, 'E o Senhor mo fez saber, e eu o soube; então me fizeste ver as suas ações.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 19, 'Mas eu era como um manso cordeiro, que se leva à matança; não sabia que era contra mim que maquinavam, dizendo: Destruamos a árvore com o seu fruto, e cortemo-lo da terra dos viventes, para que não haja mais memória do seu nome.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 20, 'Mas, ó Senhor dos exércitos, justo Juiz, que provas o coração e a mente, permite que eu veja a tua vingança sobre eles; pois a ti descobri a minha causa.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 21, 'Portanto assim diz o Senhor acerca dos homens de Anatote, que procuram a tua vida, dizendo: Não profetizes no nome do Senhor, para que não morras às nossas mãos;', 1, CURRENT_TIMESTAMP, false),
(24, 11, 22, 'por isso assim diz o Senhor dos exércitos: Eis que eu os punirei; os mancebos morrerão à espada, os seus filhos e as suas filhas morrerão de fome.', 1, CURRENT_TIMESTAMP, false),
(24, 11, 23, 'E não ficará deles um resto; pois farei vir sobre os homens de Anatote uma calamidade, sim, o ano da sua punição.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 1, 'Justo és, ó Senhor, ainda quando eu pleiteio contigo; contudo pleitearei a minha causa diante de ti. Por que prospera o caminho dos ímpios? Por que vivem em paz todos os que procedem aleivosamente?', 1, CURRENT_TIMESTAMP, false),
(24, 12, 2, 'Plantaste-os, e eles se arraigaram; medram, dão também fruto; chegado estás à sua boca, porém longe do seu coração.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 3, 'Mas tu, ó Senhor, me conheces, tu me vês, e provas o meu coração para contigo; tira-os como a ovelhas para o matadouro, e separa-os para o dia da matança.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 4, 'Até quando lamentará a terra, e se secará a erva de todo o campo? Por causa da maldade dos que nela habitam, perecem os animais e as aves; porquanto disseram: Ele não verá o nosso fim.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 5, 'Se te fatigas correndo com homens que vão a pé, então como poderás competir com cavalos? Se foges numa terra de paz, como hás de fazer na soberba do Jordão?', 1, CURRENT_TIMESTAMP, false),
(24, 12, 6, 'Pois até os teus irmãos, e a casa de teu pai, eles mesmos se houveram aleivosamente contigo; eles mesmos clamam após ti em altas vozes. Não te fies neles, ainda que te digam coisas boas.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 7, 'Desamparei a minha casa, abandonei a minha herança; entreguei a amada da minha alma na mão de seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 8, 'Tornou-se a minha herança para mim como leão numa floresta; levantou a sua voz contra mim, por isso eu a odeio.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 9, 'Acaso é para mim a minha herança como uma ave de rapina de varias cores? Andam as aves de rapina contra ela em redor? Ide, pois, ajuntai a todos os animais do campo, trazei-os para a devorarem.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 10, 'Muitos pastores destruíram a minha vinha, pisaram o meu quinhão; tornaram em desolado deserto o meu quinhão aprazível.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 11, 'Em assolação o tornaram; ele, desolado, clama a mim. Toda a terra está assolada, mas ninguém toma isso a peito.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 12, 'Sobre todos os altos escalvados do deserto vieram destruidores, porque a espada do Senhor devora desde uma até outra extremidade da terra; não há paz para nenhuma carne.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 13, 'Semearam trigo, mas segaram espinhos; cansaram-se, mas de nada se aproveitaram; haveis de ser envergonhados das vossas colheitas, por causa do ardor da ira do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 14, 'Assim diz o Senhor acerca de todos os meus maus vizinhos, que tocam a minha herança que fiz herdar ao meu povo Israel: Eis que os arrancarei da sua terra, e a casa de Judá arrancarei do meio deles.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 15, 'E depois de os haver eu arrancado, tornarei, e me compadecerei deles, e os farei voltar cada um à sua herança, e cada um à sua terra.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 16, 'E será que, se diligentemente aprenderem os caminhos do meu povo, jurando pelo meu nome: Vive o Senhor; como ensinaram o meu povo a jurar por Baal; então edificar-se-ão no meio do meu povo.', 1, CURRENT_TIMESTAMP, false),
(24, 12, 17, 'Mas, se não quiserem ouvir, totalmente arrancarei a tal nação, e a farei perecer, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 1, 'Assim me disse o Senhor: Vai, e compra-te um cinto de linho, e põe-no sobre os teus lombos, mas não o metas na água.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 2, 'E comprei o cinto, conforme a palavra do Senhor, e o pus sobre os meus lombos.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 3, 'Então me veio a palavra do Senhor pela segunda vez, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 13, 4, 'Toma o cinto que compraste e que trazes sobre os teus lombos, e levanta-te, vai ao Eufrates, e esconde-o ali na fenda duma rocha.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 5, 'Fui, pois, e escondi-o junto ao Eufrates, como o Senhor me havia ordenado.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 6, 'E passados muitos dias, me disse o Senhor: Levanta-te, vai ao Eufrates, e toma dali o cinto que te ordenei que escondesses ali.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 7, 'Então fui ao Eufrates, e cavei, e tomei o cinto do lugar onde e havia escondido; e eis que o cinto tinha apodrecido, e para nada prestava.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 8, 'Então veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 13, 9, 'Assim diz o Senhor: Do mesmo modo farei apodrecer a soberba de Judá, e a grande soberba de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 10, 'Este povo maligno, que se recusa a ouvir as minhas palavras, que caminha segundo a teimosia do seu coração, e que anda após deuses alheios, para os servir, e para os adorar, será tal como este cinto, que para nada presta.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 11, 'Pois, assim como se liga o cinto aos lombos do homem, assim eu liguei a mim toda a casa de Israel, e toda a casa de Judá, diz o Senhor, para me serem por povo, e por nome, e por louvor, e por glória; mas não quiseram ouvir:', 1, CURRENT_TIMESTAMP, false),
(24, 13, 12, 'Pelo que lhes dirás esta palavra: Assim diz o Senhor Deus de Israel: Todo o odre se encherá de vinho. E dir-te-ão: Acaso não sabemos nós muito bem que todo o odre se encherá de vinho?', 1, CURRENT_TIMESTAMP, false),
(24, 13, 13, 'Então lhes dirás: Assim diz o Senhor: Eis que eu encherei de embriaguez a todos os habitantes desta terra, mesmo aos reis que se assentam sobre o trono de Davi, e aos sacerdotes, e aos profetas, e a todos os habitantes de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 14, 'E atirá-los-ei uns contra os outros, mesmo os pais juntamente com os filhos, diz o Senhor; não terei pena nem pouparei, nem terei deles compaixão para não os destruir.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 15, 'Escutai, e inclinai os ouvidos; não vos ensoberbeçais, porque o Senhor falou.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 16, 'Dai glória ao Senhor vosso Deus, antes que venha a escuridão e antes que tropecem vossos pés nos montes tenebrosos; antes que, esperando vós luz, ele a mude em densas trevas, e a reduza a profunda escuridão.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 17, 'Mas, se não ouvirdes, a minha alma chorará em oculto, por causa da vossa soberba; e amargamente chorarão os meus olhos, e se desfarão em lágrimas, porque o rebanho do Senhor se vai levado cativo.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 18, 'Dize ao rei e à rainha-mãe: Humilhai-vos, sentai-vos no chão; porque de vossas cabeças já caiu a coroa de vossa glória.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 19, 'As cidades do Negebe estão fechadas, e não há quem as abra; todo o Judá é levado cativo, sim, inteiramente cativo.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 20, 'Levantai os vossos olhos, e vede os que vêm do norte; onde está o rebanho que se te deu, o teu lindo rebanho?', 1, CURRENT_TIMESTAMP, false),
(24, 13, 21, 'Que dirás, quando ele puser sobre ti como cabeça os que ensinaste a serem teus amigos? Não te tomarão as dores, como as duma mulher que está de parto?', 1, CURRENT_TIMESTAMP, false),
(24, 13, 22, 'Se disseres no teu coração: Por que me sobrevieram estas coisas? Pela multidão das tuas iniqüidades se descobriram as tuas fraldas, e os teus calcanhares sofrem violência.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 23, 'pode o etíope mudar a sua pele, ou o leopardo as suas malhas? então podereis também vós fazer o bem, habituados que estais a fazer o mal.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 24, 'Pelo que os espalharei como o restolho que passa arrebatado pelo vento do deserto.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 25, 'Esta é a tua sorte, a porção que te é medida por mim, diz o Senhor; porque te esqueceste de mim, e confiaste em mentiras.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 26, 'Assim também eu levantarei as tuas fraldas sobre o teu rosto, e aparecerá a tua ignominia.', 1, CURRENT_TIMESTAMP, false),
(24, 13, 27, 'Os teus adultérios, e os teus rinchos, e a enormidade da tua prostituição, essas abominações tuas, eu as tenho visto sobre os outeiros no campo. Ai de ti, Jerusalém! até quando não te purificarás?', 1, CURRENT_TIMESTAMP, false),
(24, 14, 1, 'A palavra do Senhor, que veio a Jeremias, a respeito da seca.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 2, 'Judá chora, e as suas portas estão enfraquecidas; eles se sentam de luto no chão; e o clamor de Jerusalém já vai subindo.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 3, 'E os seus nobres mandam os seus inferiores buscar água; estes vão às cisternas, e não acham água; voltam com os seus cântaros vazios; ficam envergonhados e confundidos, e cobrem as suas cabeças.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 4, 'Por causa do solo ressecado, pois que não havia chuva sobre a terra, os lavradores ficam envergonhados e cobrem as suas cabeças.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 5, 'Pois até a cerva no campo pare, e abandona sua cria, porquanto não há erva.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 6, 'E os asnos selvagens se põem nos altos escalvados e, ofegantes, sorvem o ar como os chacais; desfalecem os seus olhos, porquanto não ha erva.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 7, 'Posto que as nossas iniqüidades testifiquem contra nós, ó Senhor, opera tu por amor do teu nome; porque muitas são as nossas rebeldias; contra ti havemos pecado.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 8, 'Ó esperança de Israel, e Redentor seu no tempo da angústia! por que serias como um estrangeiro na terra? e como o viandante que arma a sua tenda para passar a noite?', 1, CURRENT_TIMESTAMP, false),
(24, 14, 9, 'Por que serias como homem surpreendido, como valoroso que não pode livrar? Mas tu estás no meio de nós, Senhor, e nós somos chamados pelo teu nome; não nos desampares.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 10, 'Assim diz o Senhor acerca deste povo: Pois que tanto gostaram de andar errantes, e não detiveram os seus pés, por isso o Senhor não os aceita, mas agora se lembrará da iniqüidade deles, e visitará os seus pecados.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 11, 'Disse-me ainda o Senhor: Não rogues por este povo para seu bem.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 12, 'Quando jejuarem, não ouvirei o seu clamor, e quando oferecerem holocaustos e oblações, não me agradarei deles; antes eu os consumirei pela espada, e pela fome e pela peste.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 13, 'Então disse eu: Ah! Senhor Deus, eis que os profetas lhes dizem: Não vereis espada, e não tereis fome; antes vos darei paz verdadeira neste lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 14, 'E disse-me o Senhor: Os profetas profetizam mentiras em meu nome; não os enviei, nem lhes dei ordem, nem lhes falei. Visão falsa, adivinhação, vaidade e o engano do seu coração é o que eles vos profetizam.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 15, 'Portanto assim diz o Senhor acerca dos profetas que profetizam em meu nome, sem que eu os tenha mandado, e que dizem: Nem espada, nem fome haverá nesta terra: À espada e à fome serão consumidos esses profetas.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 16, 'E o povo a quem eles profetizam será lançado nas ruas de Jerusalém, por causa da fome e da espada; e não haverá quem os sepulte a eles, a suas mulheres, a seus filhos e a suas filhas; porque derramarei sobre eles a sua maldade.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 17, 'Portanto lhes dirás esta palavra: Os meus olhos derramem lágrimas de noite e de dia, e não cessem; porque a virgem filha do meu povo está gravemente ferida, de mui dolorosa chaga.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 18, 'Se eu saio ao campo, eis os mortos à espada, e, se entro na cidade, eis os debilitados pela fome; o profeta e o sacerdote percorrem a terra, e nada sabem.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 19, 'Porventura já de todo rejeitaste a Judá? Aborrece a tua alma a Sião? Por que nos feriste, de modo que não há cura para nós? Aguardamos a paz, e não chegou bem algum; e o tempo da cura, e eis o pavor!', 1, CURRENT_TIMESTAMP, false),
(24, 14, 20, 'Ah, Senhor! reconhecemos a nossa impiedade e a iniqüidade de nossos pais; pois contra ti havemos pecado.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 21, 'Não nos desprezes, por amor do teu nome; não tragas opróbrio sobre o trono da tua glória; lembra-te, e não anules o teu pacto conosco.', 1, CURRENT_TIMESTAMP, false),
(24, 14, 22, 'Há, porventura, entre os deuses falsos das nações, algum que faça chover? Ou podem os céus dar chuvas? Não és tu, ó Senhor, nosso Deus? Portanto em ti esperaremos; pois tu tens feito todas estas coisas.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 1, 'Disse-me, porém, o Senhor: Ainda que Moisés e Samuel se pusessem diante de mim, não poderia estar a minha alma com este povo. Lança-os de diante da minha face, e saiam eles.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 2, 'E quando te perguntarem: Para onde iremos? dir-lhes-ás: Assim diz o Senhor: Os que para a morte, para a morte; e os que para a espada, para a espada; e os que para a fome, para a fome; e os que para o cativeiro, para o cativeiro.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 3, 'Pois os visitarei com quatro gêneros de destruidores, diz o Senhor: com espada para matar, e com cães, para os dilacerarem, e com as aves do céu e os animais da terra, para os devorarem e destruírem.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 4, 'Entregá-los-ei para serem um espetáculo horrendo perante todos os reinos da terra, por causa de Manassés, filho de Ezequias, rei de Judá, por tudo quanto fez em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 5, 'Pois quem se compadecerá de ti, ó Jerusalém? ou quem se entristecerá por ti? Quem se desviará para perguntar pela tua paz?', 1, CURRENT_TIMESTAMP, false),
(24, 15, 6, 'Tu me rejeitaste, diz o Senhor, voltaste para trás; por isso estenderei a minha mão contra ti, e te destruirei; estou cansado de me abrandar.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 7, 'E os padejei com a pá nas portas da terra; desfilhei, destruí o meu povo; não voltaram dos seus caminhos.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 8, 'As suas viúvas mais se me têm multiplicado do que a areia dos mares; trouxe ao meio-dia um destruidor sobre eles, até sobre a mãe de jovens; fiz que caísse de repente sobre ela angústia e terrores.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 9, 'A que dava à luz sete se enfraqueceu: expirou a sua alma; pôs-se-lhe o sol sendo ainda dia; ela se confundiu, e se envergonhou; e os que ficarem deles eu os entregarei à espada, diante dos seus inimigos, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 10, 'Ai de mim, minha mãe! porque me deste à luz, homem de rixas e homem de contendas para toda a terra. Nunca lhes emprestei com usura, nem eles me emprestaram a mim com usura, todavia cada um deles me amaldiçoa.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 11, 'Assim seja, ó Senhor, se jamais deixei de suplicar-te pelo bem deles, ou de rogar-te pelo inimigo no tempo da calamidade e no tempo da angústia.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 12, 'Pode alguém quebrar o ferro, o ferro do Norte, e o bronze?', 1, CURRENT_TIMESTAMP, false),
(24, 15, 13, 'As tuas riquezas e os teus tesouros, eu os entregarei sem preço ao saque; e isso por todos os teus pecados, mesmo em todos os teus limites.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 14, 'E farei que sirvas os teus inimigos numa terra que não conheces; porque o fogo se acendeu em minha ira, e sobre vós arderá.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 15, 'Tu, ó Senhor, me conheces; lembra-te de mim, visita-me, e vinga-me dos meus perseguidores; não me arrebates, por tua longanimidade. Sabe que por amor de ti tenho sofrido afronta.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 16, 'Acharam-se as tuas palavras, e eu as comi; e as tuas palavras eram para mim o gozo e alegria do meu coração; pois levo o teu nome, ó Senhor Deus dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 17, 'Não me assentei na roda dos que se alegram, nem me regozijei. Sentei-me a sós sob a tua mão, pois me encheste de indignação.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 18, 'Por que é perpétua a minha dor, e incurável a minha ferida, que se recusa a ser curada? Serás tu para mim como ribeiro ilusório e como águas inconstantes?', 1, CURRENT_TIMESTAMP, false),
(24, 15, 19, 'Portanto assim diz o Senhor: Se tu voltares, então te restaurarei, para estares diante de mim; e se apartares o precioso do vil, serás como a minha boca; tornem-se eles a ti, mas não voltes tu a eles.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 20, 'E eu te porei contra este povo como forte muro de bronze; eles pelejarão contra ti, mas não prevalecerão contra ti; porque eu sou contigo para te salvar, para te livrar, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 15, 21, 'E arrebatar-te-ei da mão dos iníquos, e livrar-te-ei da mão dos cruéis.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 1, 'E veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 16, 2, 'Não tomarás a ti mulher, nem terás filhos nem filhas neste lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 3, 'Pois assim diz o Senhor acerca dos filhos e das filhas que nascerem neste lugar, acerca de suas mães, que os tiverem, e de seus pais que os gerarem nesta terra:', 1, CURRENT_TIMESTAMP, false),
(24, 16, 4, 'Morrerão de enfermidades dolorosas, e não serão pranteados nem sepultados; serão como esterco sobre a face da terra; pela espada e pela fome serão consumidos, e os seus cadáveres servirão de pasto para as aves do céu e para os animais da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 5, 'Pois assim diz o Senhor: Não entres na casa que está de luto, nem vás a lamentá-los, nem te compadeças deles; porque deste povo, diz o Senhor, retirei a minha paz, benignidade e misericórdia.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 6, 'E morrerão nesta terra tanto grandes como pequenos; não serão sepultados, e não os prantearão, nem se farão por eles incisões, nem por eles se raparão os cabelos;', 1, CURRENT_TIMESTAMP, false),
(24, 16, 7, 'nem pão se dará aos que estiverem de luto, para os consolar sobre os mortos; nem se lhes dará a beber o copo da consolação pelo pai ou pela mãe.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 8, 'Não entres na casa do banquete, para te assentares com eles a comer e a beber.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 9, 'Pois assim diz o Senhor dos exércitos, o Deus de Israel: Eis que perante os vossos olhos, e em vossos dias, farei cessar deste lugar a voz de gozo e a voz de alegria, a voz do noivo e a voz da noiva.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 10, 'E quando anunciares a este povo todas estas palavras, e eles te disserem: Por que pronuncia o Senhor sobre :nós todo este grande mal? Qual é a nossa iniqüidade? Qual é o pecado que cometemos contra o Senhor nosso Deus?', 1, CURRENT_TIMESTAMP, false),
(24, 16, 11, 'Então lhes dirás: Porquanto vossos pais me deixaram, diz o Senhor, e se foram após outros deuses, e os serviram e adoraram, e a mim me deixaram, e não guardaram a minha lei;', 1, CURRENT_TIMESTAMP, false),
(24, 16, 12, 'e vós fizestes pior do que vossos pais; pois eis que andais, cada um de vós, após o pensamento obstinado do seu mau coração, recusando ouvir-me a mim;', 1, CURRENT_TIMESTAMP, false),
(24, 16, 13, 'portanto eu vos lançarei fora desta terra, para uma terra que não conhecestes, nem vós nem vossos pais; e ali servireis a deuses estranhos de dia e de noite; pois não vos concederei favor algum.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 14, 'Portanto, eis que dias vêm, diz o Senhor, em que não se dirá mais: Vive o Senhor: que fez subir os filhos de Israel da terra do Egito;', 1, CURRENT_TIMESTAMP, false),
(24, 16, 15, 'mas sim: Vive o Senhor, que fez subir os filhos de Israel da terra do norte, e de todas as terras para onde os tinha lançado; porque eu os farei voltar à sua terra, que dei a seus pais.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 16, 'Eis que mandarei vir muitos pescadores, diz o Senhor, os quais os pescarão; e depois mandarei vir muitos caçadores, os quais os caçarão de todo monte, e de todo outeiro, e até das fendas das rochas.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 17, 'Pois os meus olhos estão sobre todos os seus caminhos; não se acham eles escondidos da minha face, nem está a sua iniqüidade encoberta aos meus olhos.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 18, 'E eu retribuirei em dobro a sua iniqüidade e o seu pecado, porque contaminaram a minha terra com os vultos inertes dos seus ídolos detestáveis, e das suas abominações encheram a minha herança.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 19, 'Ó Senhor, força minha e fortaleza minha, e refúgio meu no dia da angústia, a ti virão as nações desde as extremidades da terra, e dirão: Nossos pais herdaram só mentiras, e vaidade, em que não havia proveito.', 1, CURRENT_TIMESTAMP, false),
(24, 16, 20, 'Pode um homem fazer para si deuses? Esses tais não são deuses!', 1, CURRENT_TIMESTAMP, false),
(24, 16, 21, 'Portanto, eis que lhes farei conhecer, sim desta vez lhes farei conhecer o meu poder e a minha força; e saberão que o meu nome é Jeová.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 1, 'O pecado de Judá está escrito com um ponteiro de ferro; com ponta de diamante está gravado na tábua do seu coração e nas pontas dos seus altares;', 1, CURRENT_TIMESTAMP, false),
(24, 17, 2, 'enquanto seus filhos se lembram dos seus altares, e dos seus aserins, junto às árvores frondosas, sobre os altos outeiros,', 1, CURRENT_TIMESTAMP, false),
(24, 17, 3, 'nas montanhas no campo aberto, a tua riqueza e todos os teus tesouros dá-los-ei como despojo por causa do pecado, em todos os teus termos.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 4, 'Assim tu, por ti mesmo, te privarás da tua herança que te dei; e far-te-ei servir os teus inimigos, na terra que não conheces; porque acendeste um fogo na minha ira, o qual arderá para sempre.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 5, 'Assim diz o Senhor: Maldito o varão que confia no homem, e faz da carne o seu braço, e aparta o seu coração do Senhor!', 1, CURRENT_TIMESTAMP, false),
(24, 17, 6, 'Pois é como o junípero no deserto, e não verá vir bem algum; antes morará nos lugares secos do deserto, em terra salgada e inabitada.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 7, 'Bendito o varão que confia no Senhor, e cuja esperança é o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 8, 'Porque é como a árvore plantada junto às águas, que estende as suas raízes para o ribeiro, e não receia quando vem o calor, mas a sua folha fica verde; e no ano de sequidão não se afadiga, nem deixa de dar fruto.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 9, 'Enganoso é o coração, mais do que todas as coisas, e perverso; quem o poderá conhecer?', 1, CURRENT_TIMESTAMP, false),
(24, 17, 10, 'Eu, o Senhor, esquadrinho a mente, eu provo o coração; e isso para dar a cada um segundo os seus caminhos e segundo o fruto das suas ações.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 11, 'Como a perdiz que ajunta pintainhos que não são do seu ninho, assim é aquele que ajunta riquezas, mas não retamente; no meio de seus dias as deixará, e no seu fim se mostrará insensato.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 12, 'Um trono glorioso, posto bem alto desde o princípio, é o lugar do nosso santuário.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 13, 'Ó Senhor, esperança de Israel, todos aqueles que te abandonarem serão envergonhados. Os que se apartam de ti serão escritos sobre a terra; porque abandonam o Senhor, a fonte das águas vivas.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 14, 'Cura-me, ó Senhor, e serei curado; salva-me, e serei salvo; pois tu és o meu louvor.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 15, 'Eis que eles me dizem: Onde está a palavra do Senhor? venha agora.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 16, 'Quanto a mim, não instei contigo para enviares sobre eles o mal, nem tampouco desejei o dia calamitoso; tu o sabes; o que saiu dos meus lábios estava diante de tua face.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 17, 'Não me sejas por espanto; meu refúgio és tu no dia da calamidade.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 18, 'Envergonhem-se os que me perseguem, mas não me envergonhe eu; assombrem-se eles, mas não me assombre eu; traze sobre eles o dia da calamidade, e destrói-os com dobrada destruição.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 19, 'Assim me disse o Senhor: Vai, e põe-te na porta de Benjamim, pela qual entram os reis de Judá, e pela qual saem, como também em todas as portas de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 20, 'E dize-lhes: Ouvi a palavra do Senhor, vós, reis de Judá e todo o Judá, e todos os moradores de Jerusalém, que entrais por estas portas;', 1, CURRENT_TIMESTAMP, false),
(24, 17, 21, 'assim diz o Senhor: Guardai-vos a vós mesmos, e não tragais cargas no dia de sábado, nem as introduzais pelas portas de Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(24, 17, 22, 'nem tireis cargas de vossas casas no dia de sábado, nem façais trabalho algum; antes santificai o dia de sábado, como eu ordenei a vossos pais.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 23, 'Mas eles não escutaram, nem inclinaram os seus ouvidos; antes endureceram a sua cerviz, para não ouvirem, e para não receberem instrução.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 24, 'Mas se vós diligentemente me ouvirdes, diz o Senhor, não introduzindo cargas pelas portas desta cidade no dia de sábado, e santificardes o dia de sábado, não fazendo nele trabalho algum,', 1, CURRENT_TIMESTAMP, false),
(24, 17, 25, 'então entrarão pelas portas desta cidade reis e príncipes, que se assentem sobre o trono de Davi, andando em carros e montados em cavalos, eles e seus príncipes, os homens de Judá, e os moradores de Jerusalém; e esta cidade será para sempre habitada.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 26, 'E virão das cidades de Judá, e dos arredores de Jerusalém, e da terra de Benjamim, e da planície, e da região montanhosa, e do e sul, trazendo à casa do Senhor holocaustos, e sacrifícios, e ofertas de cereais, e incenso, trazendo também sacrifícios de ação de graças.', 1, CURRENT_TIMESTAMP, false),
(24, 17, 27, 'Mas, se não me ouvirdes, para santificardes o dia de sábado, e para não trazerdes carga alguma, quando entrardes pelas portas de Jerusalém no dia de sábado, então acenderei fogo nas suas portas, o qual consumirá os palácios de Jerusalém, e não se apagará.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 1, 'A palavra que veio do Senhor a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 18, 2, 'Levanta-te, e desce à casa do oleiro, e lá te farei ouvir as minhas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 3, 'Desci, pois, à casa do oleiro, e eis que ele estava ocupado com a sua obra sobre as rodas.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 4, 'Como o vaso, que ele fazia de barro, se estragou na mão do oleiro, tornou a fazer dele outro vaso, conforme pareceu bem aos seus olhos fazer.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 5, 'Então veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 18, 6, 'Não poderei eu fazer de vós como fez este oleiro, ó casa de Israel? diz o Senhor. Eis que, como o barro na mão do oleiro, assim sois vós na minha mão, ó casa de Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 7, 'Se em qualquer tempo eu falar acerca duma nação, e acerca dum reino, para arrancar, para derribar e para destruir,', 1, CURRENT_TIMESTAMP, false),
(24, 18, 8, 'e se aquela nação, contra a qual falar, se converter da sua maldade, também eu me arrependerei do mal que intentava fazer-lhe.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 9, 'E se em qualquer tempo eu falar acerca duma nação e acerca dum reino, para edificar e para plantar,', 1, CURRENT_TIMESTAMP, false),
(24, 18, 10, 'se ela fizer o mal diante dos meus olhos, não dando ouvidos à minha voz, então me arrependerei do bem que lhe intentava fazer.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 11, 'Ora pois, fala agora aos homens de Judá, e aos moradores de Jerusalém, dizendo: Assim diz o senhor: Eis que estou forjando mal contra vós, e projeto um plano contra vós; convertei-vos pois agora cada um do seu mau caminho, e emendai os vossos caminhos e as vossas ações.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 12, 'Mas eles dizem: Não há esperança; porque após os nossos projetos andaremos, e cada um fará segundo o propósito obstinado do seu mau coração.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 13, 'Portanto assim diz o Senhor: Perguntai agora entre as nações quem ouviu tais coisas? coisa mui horrenda fez a virgem de Israel!', 1, CURRENT_TIMESTAMP, false),
(24, 18, 14, 'Acaso desaparece a neve do Líbano dos penhascos do Siriom? Serão esgotadas as águas frias que vêm dos montes?', 1, CURRENT_TIMESTAMP, false),
(24, 18, 15, 'Contudo o meu povo se tem esquecido de mim, queimando incenso a deuses falsos; fizeram-se tropeçar nos seus caminhos, e nas veredas antigas, para que andassem por atalhos não aplainados;', 1, CURRENT_TIMESTAMP, false),
(24, 18, 16, 'para fazerem da sua terra objeto de espanto e de perpétuos assobios; todo aquele que passa por ela se espanta, e meneia a cabeça.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 17, 'Com vento oriental os espalharei diante do inimigo; mostrar-lhes-ei as costas e não o rosto, no dia da sua calamidade.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 18, 'Então disseram: Vinde, e maquinemos projetos contra Jeremias; pois não perecerá a lei do sacerdote, nem o conselho do sábio, nem a palavra do profeta. Vinde, e ataquemo-lo com a língua, e não atendamos a nenhuma das suas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 19, 'Atende-me, ó Senhor, e ouve a voz dos que contendem comigo.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 20, 'Porventura pagar-se-á mal por bem? Contudo cavaram uma cova para a minha vida. Lembra-te de que eu compareci na tua presença, para falar a favor deles, para desviar deles a tua indignação.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 21, 'Portanto entrega seus filhos à fome, e entrega-os ao poder da espada, e sejam suas mulheres roubadas dos filhos, e fiquem viúvas; e sejam seus maridos feridos de morte, e os seus jovens mortos à espada na peleja.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 22, 'Seja ouvido o clamor que vem de suas casas, quando de repente trouxeres tropas sobre eles; porque cavaram uma cova para prender-me e armaram laços aos meus pés.', 1, CURRENT_TIMESTAMP, false),
(24, 18, 23, 'Mas tu, ó Senhor, sabes todo o seu conselho contra mim para matar-me. Não perdoes a sua iniquidade, nem apagues o seu pecado de diante da tua face; mas sejam transtornados diante de ti; trata-os assim no tempo da tua ira.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 1, 'Assim disse o Senhor: Vai, e compra uma botija de oleiro, e leva contigo alguns anciãos do povo e alguns anciãos dos sacerdotes;', 1, CURRENT_TIMESTAMP, false),
(24, 19, 2, 'e sai ao vale do filho de Hinom, que está à entrada da Porta Harsite, e apregoa ali as palavras que eu te disser;', 1, CURRENT_TIMESTAMP, false),
(24, 19, 3, 'e dirás: Ouvi a palavra do Senhor, ó reis de Judá, e moradores de Jerusalém. Assim diz o Senhor dos exércitos, o Deus de Israel: Eis que trarei sobre este lugar uma calamidade tal que fará retinir os ouvidos de quem quer que dela ouvir.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 4, 'Porquanto me deixaram, e profanaram este lugar, queimando nele incenso a outros deuses, que nunca conheceram, nem eles nem seus pais, nem os reis de Judá; e encheram este lugar de sangue de inocentes.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 5, 'E edificaram os altos de Baal, para queimarem seus filhos no fogo em holocaustos a Baal; o que nunca lhes ordenei, nem falei, nem entrou no meu pensamento.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 6, 'Por isso eis que dias vêm, diz o Senhor, em que este lugar não se chamara mais Tofete, nem o vale do filho de Hinom, mas o vale da matança.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 7, 'E tornarei vão o conselho de Judá e de Jerusalém neste lugar, e os farei cair à espada diante de seus inimigos e pela mão dos que procuram tirar-lhes a vida. Darei os seus cadáveres por pasto as aves do céu e aos animais da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 8, 'E farei esta cidade objeto de espanto e de assobios; todo aquele que passar por ela se espantará, e assobiará, por causa de todas as suas pragas.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 9, 'E lhes farei comer a carne de seus filhos, e a carne de suas filhas, e comerá cada um a carne do seu próximo, no cerco e no aperto em que os apertarão os seus inimigos, e os que procuram tirar-lhes a vida.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 10, 'Então quebrarás a botija à vista dos homens que foram contigo,', 1, CURRENT_TIMESTAMP, false),
(24, 19, 11, 'e lhes dirás: Assim diz o Senhor dos exércitos: Deste modo quebrarei eu a este povo, e a esta cidade, como se quebra o vaso do oleiro, de sorte que não pode mais refazer-se; e os enterrarão em Tofete, porque não haverá outro lugar para os enterrar.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 12, 'Assim farei a este lugar e aos seus moradores, diz o Senhor; sim, porei esta cidade como Tofete.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 13, 'E as casas de Jerusalém, e as casas dos reis de Judá, serão imundas como o lugar de Tofete, como também todas as casas, sobre cujos terraços queimaram incenso a todo o exército dos céus, e ofereceram libações a deuses estranhos.', 1, CURRENT_TIMESTAMP, false),
(24, 19, 14, 'Então voltou Jeremias de Tofete, aonde o tinha enviado o Senhor a profetizar; e pôs-se em pé no átrio da casa do Senhor, e disse a todo o povo:', 1, CURRENT_TIMESTAMP, false),
(24, 19, 15, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Eis que trarei sobre esta cidade, e sobre todas as suas cercanias, todo o mal que pronunciei contra ela, porquanto endureceram a sua cerviz, para não ouvirem as minhas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 1, 'Ora Pasur, filho de Imer, o sacerdote, que era superintendente da casa do Senhor, ouviu Jeremias profetizar estas coisas.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 2, 'Então feriu Pasur ao profeta Jeremias, e o meteu no cepo que está na porta superior de Benjamim, na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 3, 'No dia seguinte, quando Pasur o tirou do cepo Jeremias lhe disse: O Senhor não te chama Pasur, mas Magor-Missabibe.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 4, 'Porque assim diz o Senhor: Eis que farei de ti um terror para ti mesmo, e para todos os teus amigos. Eles cairão à espada de seus inimigos, e teus olhos o verão. Entregarei Judá todo na mão do rei de Babilônia; ele os levará cativos para Babilônia, e matá-los-á à espada.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 5, 'Também entregarei todas as riquezas desta cidade, todos os seus lucros, e todas as suas coisas preciosas, sim, todos os tesouros dos reis de Judá na mão de seus inimigos, que os saquearão e, tomando-os, os levarão a Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 6, 'E tu, Pasur, e todos os moradores da tua casa ireis para o cativeiro; e virás para Babilônia, e ali morrerás, e ali serás sepultado, tu, e todos os teus amigos, aos quais profetizaste falsamente.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 7, 'Seduziste-me, ó Senhor, e deixei-me seduzir; mais forte foste do que eu, e prevaleceste; sirvo de escárnio o dia todo; cada um deles zomba de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 8, 'Pois sempre que falo, grito, clamo: Violência e destruição; porque se tornou a palavra do Senhor um opróbrio para mim, e um ludíbrio o dia todo.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 9, 'Se eu disser: Não farei menção dele, e não falarei mais no seu nome, então há no meu coração um como fogo ardente, encerrado nos meus ossos, e estou fatigado de contê-lo, e não posso mais.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 10, 'Pois ouço a difamação de muitos, terror por todos os lados! Denunciai-o! Denunciemo-lo! dizem todos os meus íntimos amigos, aguardando o meu manquejar; bem pode ser que se deixe enganar; então prevaleceremos contra ele e nos vingaremos dele.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 11, 'Mas o Senhor está comigo como um guerreiro valente; por isso tropeçarão os meus perseguidores, e não prevalecerão; ficarão muito confundidos, porque não alcançarão êxito, sim, terão uma confusão perpétua que nunca será esquecida.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 12, 'Tu pois, ó Senhor dos exércitos, que provas o justo, e vês os pensamentos e o coração, permite que eu veja a tua vingança sobre eles; porque te confiei a minha causa.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 13, 'Cantai ao Senhor, louvai ao Senhor; pois livrou a alma do necessitado da mão dos malfeitores.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 14, 'Maldito o dia em que nasci; não seja bendito o dia em que minha mãe me deu à luz.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 15, 'Maldito o homem que deu as novas a meu pai, dizendo: Nasceu-te um filho, alegrando-o com isso grandemente.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 16, 'E seja esse homem como as cidades que o senhor destruiu sem piedade; e ouça ele um clamor pela manhã, e um alarido ao meio-dia.', 1, CURRENT_TIMESTAMP, false),
(24, 20, 17, 'Por que não me matou na madre? assim minha mãe teria sido a minha sepultura, e teria ficado grávida perpetuamente!', 1, CURRENT_TIMESTAMP, false),
(24, 20, 18, 'Por que saí da madre, para ver trabalho e tristeza, e para que se consumam na vergonha os meus dias?', 1, CURRENT_TIMESTAMP, false),
(24, 21, 1, 'A palavra que veio a Jeremias da parte do Senhor, quando o rei Zedequias lhe enviou Pasur, filho de Malquias, e Sofonias, filho de Maaséias, o sacerdote, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 21, 2, 'Pergunta agora por nós ao Senhor, por que Nabucodonosor, rei de Babilônia, guerreia contra nós; porventura o Senhor nos tratará segundo todas as suas maravilhas, e fará que o rei se retire de nós.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 3, 'Então Jeremias lhes respondeu: Assim direis a Zedequias:', 1, CURRENT_TIMESTAMP, false),
(24, 21, 4, 'Assim diz o Senhor, o Deus de Israel: Eis que virarei contra vos as armas de guerra, que estão nas vossas mãos, com que vós pelejais contra o rei de Babilônia e contra os caldeus, que vos estão sitiando ao redor dos muros, e ajuntá-los-ei no meio desta cidade.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 5, 'E eu mesmo pelejarei contra vós com mão estendida, e com braço forte, e em ira, e em furor, e em grande indignação.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 6, 'E ferirei os habitantes desta cidade, tanto os homens como os animais; de grande peste morrerão.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 7, 'E depois disso, diz o Senhor, entregarei Zedequias, rei de Judá, e seus servos, e o povo, e os que desta cidade restarem da peste, e da espada, e da fome, sim entregá-los-ei na mão de Nabucodonosor, rei de Babilônia, e na mão de seus inimigos, e na mão dos que procuram tirar-lhes a vida; e ele os passará ao fio da espada; não os poupará, nem se compadecerá, nem terá misericórdia.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 8, 'E a este povo dirás: Assim diz o Senhor: Eis que ponho diante de vós o caminho da vida e o caminho da morte.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 9, 'O que ficar nesta cidade há de morrer à espada, ou de fome, ou de peste; mas o que sair, e se render aos caldeus, que vos cercam, viverá, e terá a sua vida por despojo.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 10, 'Porque pus o meu rosto contra esta cidade para mal, e não para bem, diz o Senhor; na mão do rei de Babilônia se entregará, e ele a queimará a fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 11, 'E à casa do rei de Judá dirás: Ouvi a palavra do Senhor:', 1, CURRENT_TIMESTAMP, false),
(24, 21, 12, 'O casa de Davi, assim diz o Senhor: Executai justiça pela manhã, e livrai o espoliado da mão do opressor, para que não saia o meu furor como fogo, e se acenda, sem que haja quem o apague, por causa da maldade de vossas ações.', 1, CURRENT_TIMESTAMP, false),
(24, 21, 13, 'Eis que eu sou contra ti, ó moradora do vale, ó rocha da campina, diz o Senhor; contra vós que dizeis: Quem descerá contra nós? ou: Quem entrará nas nossas moradas?', 1, CURRENT_TIMESTAMP, false),
(24, 21, 14, 'E eu vos castigarei segundo o fruto das vossas ações, diz o Senhor; e no seu bosque acenderei fogo que consumirá a tudo o que está em redor dela.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 1, 'Assim diz o Senhor: Desce à casa do rei de Judá, e anuncia ali esta palavra.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 2, 'E dize: Ouve a palavra do Senhor, ó rei de Judá, que te assentas no trono de Davi; ouvi, tu, e os teus servos, e o teu povo, que entrais por estas portas.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 3, 'Assim diz o Senhor: Exercei o juízo e a justiça, e livrai o espoliado da mão do opressor. Não façais nenhum mal ou violência ao estrangeiro, nem ao órfão, nem a viúva; não derrameis sangue inocente neste lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 4, 'Pois se deveras cumprirdes esta palavra, entrarão pelas portas desta casa reis que se assentem sobre o trono de Davi, andando em carros e montados em cavalos, eles, e os seus servos, e o seu povo.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 5, 'Mas se não derdes ouvidos a estas palavras, por mim mesmo tenho jurado, diz o Senhor, que esta casa se tornará em assolação.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 6, 'Pois assim diz o Senhor acerca da casa do rei de Judá: Tu és para mim Gileade, e a cabeça do Líbano; todavia certamente farei de ti um deserto e cidades desabitadas.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 7, 'E prepararei contra ti destruidores, cada um com as suas armas; os quais cortarão os teus cedros escolhidos, e os lançarão no fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 8, 'E muitas nações passarão por esta cidade, e dirá cada um ao seu companheiro: Por que procedeu o Senhor assim com esta grande cidade?', 1, CURRENT_TIMESTAMP, false),
(24, 22, 9, 'Então responderão: Porque deixaram o pacto do Senhor seu Deus, e adoraram a outros deuses, e os serviram.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 10, 'Não choreis o morto, nem o lastimeis; mas chorai amargamente aquele que sai; porque não voltará mais, nem verá a terra onde nasceu.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 11, 'Pois assim diz o Senhor acerca de Salum, filho de Josias, rei de Judá, que reinou em lugar de Josias seu pai, que saiu deste lugar: Nunca mais voltará para cá,', 1, CURRENT_TIMESTAMP, false),
(24, 22, 12, 'mas no lugar para onde o levaram cativo morrerá, e nunca mais verá esta terra.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 13, 'Ai daquele que edifica a sua casa com iniqüidade, e os seus aposentos com injustiça; que se serve do trabalho do seu próximo sem remunerá-lo, e não lhe dá o salário;', 1, CURRENT_TIMESTAMP, false),
(24, 22, 14, 'que diz: Edificarei para mim uma casa espaçosa, e aposentos largos; e que lhe abre janelas, forrando-a de cedro, e pintando-a de vermelhão.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 15, 'Acaso reinarás tu, porque procuras exceder no uso de cedro? O teu pai não comeu e bebeu, e não exercitou o juízo e a justiça? Por isso lhe sucedeu bem.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 16, 'Julgou a causa do pobre e necessitado; então lhe sucedeu bem. Porventura não é isso conhecer-me? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 17, 'Mas os teus olhos e o teu coração não atentam senão para a tua ganância, e para derramar sangue inocente, e para praticar a opressão e a violência.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 18, 'Portanto assim diz o Senhor acerca de Jeoiaquim, filho de Josias, rei de Judá: Não o lamentarão, dizendo: Ai, meu irmão! ou: Ai, minha irmã! nem o lamentarão, dizendo: Ai, Senhor! ou: Ai, sua majestade!', 1, CURRENT_TIMESTAMP, false),
(24, 22, 19, 'Com a sepultura de jumento será sepultado, sendo arrastado e lançado fora das portas de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 20, 'Sobe ao Líbano, e clama, e levanta a tua voz em Basã, e clama desde Abarim; porque são destruídos todos os teus namorados.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 21, 'Falei contigo no tempo da tua prosperidade; mas tu disseste: Não escutarei. Este tem sido o teu caminho, desde a tua mocidade, o não obedeceres à minha voz.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 22, 'O vento apascentará todos os teus pastores, e os teus namorados irão para o cativeiro; certamente então te confundirás,', 1, CURRENT_TIMESTAMP, false),
(24, 22, 23, 'e tu, que habitas no Líbano, aninhada nos cedros, como hás de gemer, quando te vierem as dores, os ais como da que está de parto!', 1, CURRENT_TIMESTAMP, false),
(24, 22, 24, 'Vivo eu, diz o Senhor, ainda que Conias, filho de Jeoiaquim, rei de Judá, fosse o anel do selo da minha mão direita, contudo eu dali te arrancaria;', 1, CURRENT_TIMESTAMP, false),
(24, 22, 25, 'e te entregaria na mão dos que procuram tirar-te a vida, e na mão daqueles diante dos quais tu temes, a saber, na mão de Nabucodonosor, rei de Babilônia, e na mão dos caldeus.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 26, 'A ti e a tua mãe, que te deu à luz, lançar-vos-ei para uma terra estranha, em que não nascestes, e ali morrereis.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 27, 'Mas à terra para a qual eles almejam voltar, para lá não voltarão.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 28, 'E este homem Conias algum vaso desprezado e quebrado, um vaso de que ninguém se agrada? Por que razão foram ele e a sua linhagem arremessados e arrojados para uma terra que não conhecem?', 1, CURRENT_TIMESTAMP, false),
(24, 22, 29, 'Ó terra, terra, terra; ouve a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 22, 30, 'Assim diz o Senhor: Escrevei que este homem fica sem filhos, homem que não prosperará nos seus dias; pois nenhum da sua linhagem prosperará para assentar-se sobre o trono de Davi e reinar daqui em diante em Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 1, 'Ai dos pastores que destroem e dispersam as ovelhas do meu pasto, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 2, 'Portanto assim diz o Senhor, o Deus de Israel, acerca dos pastores que apascentam o meu povo: Vós dispersastes as minhas ovelhas, e as afugentastes, e não as visitastes. Eis que visitarei sobre vós a maldade das vossas ações, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 3, 'E eu mesmo recolherei o resto das minhas ovelhas de todas as terras para onde as tiver afugentado, e as farei voltar aos seus apriscos; e frutificarão, e se multiplicarão.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 4, 'E levantarei sobre elas pastores que as apascentem, e nunca mais temerão, nem se assombrarão, e nem uma delas faltará, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 5, 'Eis que vêm dias, diz o Senhor, em que levantarei a Davi um Renovo justo; e, sendo rei, reinará e procederá sabiamente, executando o juízo e a justiça na terra.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 6, 'Nos seus dias Judá será salvo, e Israel habitará seguro; e este é o nome de que será chamado: O SENHOR JUSTIÇA NOSSA.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 7, 'Portanto, eis que vêm dias, diz o Senhor, em que nunca mais dirão: Vive o Senhor, que tirou os filhos de Israel da terra do Egito;', 1, CURRENT_TIMESTAMP, false),
(24, 23, 8, 'mas: Vive o Senhor, que tirou e que trouxe a linhagem da casa de Israel da terra do norte, e de todas as terras para onde os tinha arrojado; e eles habitarão na sua terra.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 9, 'Quanto aos profetas. O meu coração está quebrantado dentro de mim; todos os meus ossos estremecem; sou como um homem embriagado, e como um homem vencido do vinho, por causa do Senhor, e por causa das suas santas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 10, 'Pois a terra está cheia de adúlteros; por causa da maldição a terra chora, e os pastos do deserto se secam. A sua carreira é má, e a sua força não é reta.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 11, 'Porque tanto o profeta como o sacerdote são profanos; até na minha casa achei a sua maldade, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 12, 'Portanto o seu caminho lhes será como veredas escorregadias na escuridão; serão empurrados e cairão nele; porque trarei sobre eles mal, o ano mesmo da sua punição, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 13, 'Nos profetas de Samária bem vi eu insensatez; profetizavam da parte de Baal, e faziam errar o meu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 14, 'Mas nos profetas de Jerusalém vejo uma coisa horrenda: cometem adultérios, e andam com falsidade, e fortalecem as mãos dos malfeitores, de sorte que não se convertam da sua maldade; eles têm-se tornado para mim como Sodoma, e os moradores dela como Gomorra.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 15, 'Portanto assim diz o Senhor dos exércitos acerca dos profetas: Eis que lhes darei a comer losna, e lhes farei beber águas de fel; porque dos profetas de Jerusalém saiu a contaminação sobre toda a terra.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 16, 'Assim diz o Senhor dos exércitos: Não deis ouvidos as palavras dos profetas, que vos profetizam a vós, ensinando-vos vaidades; falam da visão do seu coração, não da boca do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 17, 'Dizem continuamente aos que desprezam a palavra do Senhor: Paz tereis; e a todo o que anda na teimosia do seu coração, dizem: Não virá mal sobre vós.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 18, 'Pois quem dentre eles esteve no concílio do Senhor, para que percebesse e ouvisse a sua palavra, ou quem esteve atento e escutou a sua palavra?', 1, CURRENT_TIMESTAMP, false),
(24, 23, 19, 'Eis a tempestade do Senhor! A sua indignação, qual tempestade devastadora, já saiu; descarregar-se-á sobre a cabeça dos ímpios.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 20, 'Não retrocederá a ira do Senhor, até que ele tenha executado e cumprido os seus desígnios. Nos últimos dias entendereis isso claramente.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 21, 'Não mandei esses profetas, contudo eles foram correndo; não lhes falei a eles, todavia eles profetizaram.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 22, 'Mas se tivessem assistido ao meu concílio, então teriam feito o meu povo ouvir as minhas palavras, e o teriam desviado do seu mau caminho, e da maldade das suas ações.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 23, 'Sou eu apenas Deus de perto, diz o Senhor, e não também Deus de longe?', 1, CURRENT_TIMESTAMP, false),
(24, 23, 24, 'Esconder-se-ia alguém em esconderijos, de modo que eu não o veja? diz o Senhor. Porventura não encho eu o céu e a terra? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 25, 'Tenho ouvido o que dizem esses profetas que profetizam mentiras em meu nome, dizendo: Sonhei, sonhei.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 26, 'Até quando se achará isso no coração dos profetas que profetizam mentiras, e que profetizam do engano do seu próprio coração?', 1, CURRENT_TIMESTAMP, false),
(24, 23, 27, 'Os quais cuidam fazer com que o meu povo se esqueça do meu nome pelos seus sonhos que cada um conta ao seu próximo, assim como seus pais se esqueceram do meu nome por causa de Baal.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 28, 'O profeta que tem um sonho conte o sonho; e aquele que tem a minha palavra, fale fielmente a minha palavra. Que tem a palha com o trigo? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 29, 'Não é a minha palavra como fogo, diz o Senhor, e como um martelo que esmiúça a pedra?', 1, CURRENT_TIMESTAMP, false),
(24, 23, 30, 'Portanto, eis que eu sou contra os profetas, diz o Senhor, que furtam as minhas palavras, cada um ao seu próximo.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 31, 'Eis que eu sou contra os profetas, diz o Senhor, que usam de sua própria linguagem, e dizem: Ele disse.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 32, 'Eis que eu sou contra os que profetizam sonhos mentirosos, diz o Senhor, e os contam, e fazem errar o meu povo com as suas mentiras e com a sua vã jactância; pois eu não os enviei, nem lhes dei ordem; e eles não trazem proveito algum a este povo, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 33, 'Quando pois te perguntar este povo, ou um profeta, ou um sacerdote, dizendo: Qual é a profecia do Senhor? Então lhes dirás: Qual a profecia! que eu vos arrojarei, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 34, 'E, quanto ao profeta, e ao sacerdote, e ao povo, que disser: A profecia do Senhor; eu castigarei aquele homem e a sua casa.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 35, 'Assim direis, cada um ao seu próximo, e cada um ao seu irmão: Que respondeu o Senhor? e: Que falou o Senhor?', 1, CURRENT_TIMESTAMP, false),
(24, 23, 36, 'Mas nunca mais fareis menção da profecia do Senhor, porque a cada um lhe servirá de profecia a sua própria palavra; pois torceis as palavras do Deus vivo, do Senhor dos exércitos, o nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 23, 37, 'Assim dirás ao profeta: Que te respondeu o Senhor? e: Que falou o Senhor?', 1, CURRENT_TIMESTAMP, false),
(24, 23, 38, 'Se, porém, disserdes: A profecia do Senhor; assim diz o Senhor: Porque dizeis esta palavra: A profecia do Senhor, quando eu mandei dizer-vos: Não direis: A profecia do Senhor;', 1, CURRENT_TIMESTAMP, false),
(24, 23, 39, 'por isso, eis que certamente eu vos levantarei, e vos lançarei fora da minha presença, a vós e a cidade que vos dei a vós e a vossos pais;', 1, CURRENT_TIMESTAMP, false),
(24, 23, 40, 'e porei sobre vós perpétuo opróbrio, e eterna vergonha, que não será esquecida.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 1, 'Fez-me o Senhor ver, e vi dois cestos de figos, postos diante do templo do Senhor. Sucedeu isso depois que Nabucodonosor, rei de Babilônia, levara em cativeiro a Jeconias, filho de Jeoiaquim, rei de Judá, e os príncipes de Judá, e os carpinteiros, e os ferreiros de Jerusalém, e os trouxera a Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 2, 'Um cesto tinha figos muito bons, como os figos temporãos; mas o outro cesto tinha figos muito ruins, que não se podiam comer, de ruins que eram.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 3, 'E perguntou-me o Senhor: Que vês tu, Jeremias? E eu respondi: Figos; os figos bons, muito bons, e os ruins, muito ruins, que não se podem comer, de ruins que são.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 4, 'Então veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 24, 5, 'Assim diz o Senhor, o Deus de Israel: Como a estes bons figos, assim atentarei com favor para os exilados de Judá, os quais eu enviei deste lugar para a terra dos caldeus.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 6, 'Porei os meus olhos sobre eles, para seu bem, e os farei voltar a esta terra. Edificá-los-ei, e não os demolirei; e plantá-los-ei, e não os arrancarei.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 7, 'E dar-lhes-ei coração para que me conheçam, que eu sou o Senhor; e eles serão o meu povo, e eu serei o seu Deus; pois se voltarão para mim de todo o seu coração.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 8, 'E como os figos ruins, que não se podem comer, de ruins que são, certamente assim diz o Senhor: Do mesmo modo entregarei Zedequias, rei de Judá, e os seus príncipes, e o resto de Jerusalém, que ficou de resto nesta terra, e os que habitam na terra do Egito;', 1, CURRENT_TIMESTAMP, false),
(24, 24, 9, 'eu farei que sejam espetáculo horrendo, uma ofensa para todos os reinos da terra, um opróbrio e provérbio, um escárnio, e uma maldição em todos os lugares para onde os arrojarei.', 1, CURRENT_TIMESTAMP, false),
(24, 24, 10, 'E enviarei entre eles a espada, a fome e a peste, até que sejam consumidos de sobre a terra que lhes dei a eles e a seus pais.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 1, 'A palavra que veio a Jeremias acerca de todo o povo de Judá, no ano quarto de Jeoiaquim, filho de Josias, rei de Judá {que era o primeiro ano de Nabucodonosor, rei de Babilônia,}', 1, CURRENT_TIMESTAMP, false),
(24, 25, 2, 'a qual anunciou o profeta Jeremias a todo o povo de Judá, e a todos os habitantes de Jerusalém, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 25, 3, 'Desde o ano treze de Josias, filho de Amom, rei de Judá, até o dia de hoje, período de vinte e três anos, tem vindo a mim a palavra do Senhor, e vo-la tenho anunciado, falando-vos insistentemente; mas vós não tendes escutado.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 4, 'Também o Senhor vos tem enviado com insistência todos os seus servos, os profetas mas vós não escutastes, nem inclinastes os vossos ouvidos para ouvir,', 1, CURRENT_TIMESTAMP, false),
(24, 25, 5, 'quando vos diziam: Convertei-vos agora cada um do seu mau caminho, e da maldade das suas ações, e habitai na terra que o Senhor vos deu e a vossos pais, desde os tempos antigos e para sempre;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 6, 'e não andeis após deuses alheios para os servirdes, e para os adorardes, nem me provoqueis à ira com a obra de vossas mãos; e não vos farei mal algum.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 7, 'Todavia não me escutastes, diz o Senhor, mas me provocastes à ira com a obra de vossas mãos, para vosso mal.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 8, 'Portanto assim diz o Senhor dos exércitos: Visto que não escutastes as minhas palavras', 1, CURRENT_TIMESTAMP, false),
(24, 25, 9, 'eis que eu enviarei, e tomarei a todas as famílias do Norte, diz o Senhor, como também a Nabucodonosor, rei de Babilônia, meu servo, e os trarei sobre esta terra, e sobre os seus moradores, e sobre todas estas nações em redor. e os destruirei totalmente, e farei que sejam objeto de espanto, e de assobio, e de perpétuo opróbrio.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 10, 'E farei cessar dentre eles a voz de gozo e a voz de alegria, a voz do noivo e a voz da noiva, o som das mós e a luz do candeeiro.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 11, 'E toda esta terra virá a ser uma desolação e um espanto; e estas nações servirão ao rei de Babilônia setenta anos.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 12, 'Acontecerá, porém, que quando se cumprirem os setenta anos, castigarei o rei de Babilônia, e esta nação, diz o Senhor, castigando a sua iniqüidade, e a terra dos caldeus; farei dela uma desolação perpetua.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 13, 'E trarei sobre aquela terra todas as minhas palavras, que tenho proferido contra ela, tudo quanto está escrito neste livro, que profetizou Jeremias contra todas as nações.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 14, 'Porque deles, sim, deles mesmos muitas nações e grandes reis farão escravos; assim lhes retribuirei segundo os seus feitos, e segundo as obras das suas mãos.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 15, 'Pois assim me disse o Senhor, o Deus de Israel: Toma da minha mão este cálice do vinho de furor, e faze que dele bebam todas as nações, às quais eu te enviar.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 16, 'Beberão, e cambalearão, e enlouquecerão, por causa da espada, que eu enviarei entre eles.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 17, 'Então tomei o cálice da mão do Senhor, e fiz que bebessem todas as nações, às quais o Senhor me enviou:', 1, CURRENT_TIMESTAMP, false),
(24, 25, 18, 'a Jerusalém, e às cidades de Judá, e aos seus reis, e aos seus príncipes, para fazer deles uma desolação, um espanto, um assobio e uma maldição, como hoje se vê;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 19, 'a Faraó, rei do Egito, e a seus servos, e a seus príncipes, e a todo o seu povo;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 20, 'e a todo o povo misto, e a todos os reis da terra de Uz, e a todos os reis da terra dos filisteus, a Asquelom, a Gaza, a Ecrom, e ao que resta de Asdode;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 21, 'e a Edom, a Moabe, e aos filhos de Amom;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 22, 'e a todos os reis de Tiro, e a todos os reis de Sidom, e aos reis das terras dalém do mar;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 23, 'a Dedã, a Tema, a Buz e a todos os que habitam nos últimos cantos da terra;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 24, 'a todos os reis da Arábia, e a todos os reis do povo misto que habita no deserto;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 25, 'a todos os reis de Zinri, a todos os reis de Elão, e a todos os reis da Média;', 1, CURRENT_TIMESTAMP, false),
(24, 25, 26, 'a todos os reis do Norte, os de perto e os de longe, tanto um como o outro, e a todos os reinos da terra, que estão sobre a face da terra; e o rei de Sesaque beberá depois deles.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 27, 'Pois lhes dirás: Assim diz o Senhor dos exércitos, o Deus de Israel: Bebei, e embebedai-vos, e vomitai, e caí, e não torneis a levantar, por causa da espada que eu vos enviarei.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 28, 'Se recusarem tomar o copo da tua mão para beber, então lhes dirás: Assim diz o Senhor dos exércitos: Certamente bebereis.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 29, 'Pois eis que sobre a cidade que se chama pelo meu nome, eu começo a trazer a calamidade; e haveis vós de ficar totalmente impunes? Não ficareis impunes; porque eu chamo a espada sobre todos os moradores da terra, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 30, 'Tu pois lhes profetizarás todas estas palavras, e lhes dirás: O Senhor desde o alto bramirá, e fará ouvir a sua voz desde a sua santa morada; bramirá fortemente contra a sua habitação; dará brados, como os que pisam as uvas, contra todos os moradores da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 31, 'Chegará o estrondo até a extremidade da terra, porque o Senhor tem contenda com as nações, entrará em juízo com toda a carne; quanto aos ímpios, ele os entregará a espada, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 32, 'Assim diz o Senhor dos exércitos: Eis que o mal passa de nação para nação, e grande tempestade se levantará dos confins da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 33, 'E os mortos do Senhor naquele dia se encontrarão desde uma extremidade da terra até a outra; não serão pranteados, nem recolhidos, nem sepultados; mas serão como esterco sobre a superfície da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 34, 'Uivai, pastores, e clamai; e revolvei-vos na cinza, vós que sois os principais do rebanho; pois já se cumpriram os vossos dias para serdes mortos, e eu vos despedaçarei, e vós então caireis como carneiros escolhidos.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 35, 'E não haverá refúgio para os pastores, nem lugar para onde escaparem os principais do rebanho.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 36, 'Eis a voz de grito dos pastores, o uivo dos principais do rebanho; porque o Senhor está devastando o pasto deles.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 37, 'E as suas malhadas pacíficas são reduzidas a silêncio, por causa do furor da ira do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 25, 38, 'Deixou como leão o seu covil; porque a sua terra se tornou em desolação, por causa do furor do opressor, e por causa do furor da sua ira.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 1, 'No princípio do reino de Jeoiaquim, filho de Josias, rei de Judá, veio da parte do Senhor esta palavra, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 26, 2, 'Assim diz o Senhor: Põe-te no átrio da casa do Senhor e dize a todas as cidades de Judá que vêm adorar na casa do Senhor, todas as palavras que te mando que lhes fales; não omitas uma só palavra.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 3, 'Bem pode ser que ouçam, e se convertam cada um do seu mau caminho, para que eu desista do mal que intento fazer-lhes por causa da maldade das suas ações.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 4, 'Dize-lhes pois: Assim diz o Senhor: Se não me derdes ouvidos para andardes na minha lei, que pus diante de vós,', 1, CURRENT_TIMESTAMP, false),
(24, 26, 5, 'e para ouvirdes as palavras dos meus servos, os profetas, que eu com insistência vos envio, mas não ouvistes;', 1, CURRENT_TIMESTAMP, false),
(24, 26, 6, 'então farei que esta casa seja como Siló, e farei desta cidade uma maldição para todas as nações da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 7, 'E ouviram os sacerdotes, e os profetas, e todo o povo, a Jeremias, anunciando estas palavras na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 8, 'Tendo Jeremias acabado de dizer tudo quanto o Senhor lhe havia ordenado que dissesse a todo o povo, pegaram nele os sacerdotes, e os profetas, e todo o povo, dizendo: Certamente morrerás.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 9, 'Por que profetizaste em nome do Senhor, dizendo: Será como Siló esta casa, e esta cidade ficará assolada e desabitada? E ajuntou-se todo o povo contra Jeremias, na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 10, 'Quando os príncipes de Judá ouviram estas coisas, subiram da casa do rei à casa do Senhor, e se assentaram à entrada da porta nova do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 11, 'Então falaram os sacerdotes e os profetas aos príncipes e a todo povo, dizendo: Este homem é réu de morte, porque profetizou contra esta cidade, como ouvistes com os vossos próprios ouvidos.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 12, 'E falou Jeremias a todos os príncipes e a todo o povo, dizendo: O Senhor enviou-me a profetizar contra esta casa, e contra esta cidade, todas as palavras que ouvistes.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 13, 'Agora, pois, melhorai os vossos caminhos e as vossas ações, e ouvi a voz do Senhor vosso Deus, e o Senhor desistirá do mal que falou contra vós.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 14, 'Quanto a mim, eis que estou nas vossas mãos; fazei de mim conforme o que for bom e reto aos vossos olhos.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 15, 'Sabei, porém, com certeza que, se me matardes a mim, trareis sangue inocente sobre vós, e sobre esta cidade, e sobre os seus habitantes; porque, na verdade, o Senhor me enviou a vós, para dizer aos vossos ouvidos todas estas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 16, 'Então disseram os príncipes e todo o povo aos sacerdotes e aos profetas: Este homem não é réu de morte, porque em nome do Senhor, nosso Deus, nos falou.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 17, 'Também se levantaram alguns dos anciãos da terra, e falaram a toda a assembléia do povo, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 26, 18, 'Miquéias, o morastita, profetizou nos dias de Ezequias, rei de Judá, e falou a todo o povo de Judá, dizendo: Assim diz o Senhor dos exércitos: Sião será lavrada como um campo, e Jerusalém se tornará em montões de ruínas, e o monte desta casa como os altos de um bosque.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 19, 'Mataram-no, porventura, Ezequias, rei de Judá, e todo o Judá? Antes não temeu este ao Senhor, e não implorou o favor do Senhor? e não se arrependeu o Senhor do mal que falara contra eles? Mas nós estamos fazendo um grande mal contra as nossas almas.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 20, 'Também houve outro homem que profetizava em nome do Senhor: Urias, filho de Semaías, de Quiriate-Jearim, o qual profetizou contra esta cidade, e contra esta terra, conforme todas as palavras de Jeremias;', 1, CURRENT_TIMESTAMP, false),
(24, 26, 21, 'e quando o rei Jeoiaquim, e todos os seus valentes, e todos os príncipes, ouviram as palavras dele, procurou o rei matá-lo; mas quando Urias o ouviu, temeu, e fugiu, e foi para o Egito;', 1, CURRENT_TIMESTAMP, false),
(24, 26, 22, 'mas o rei Jeoiaquim enviou ao Egito certos homens; Elnatã, filho de Acbor, e outros com ele,', 1, CURRENT_TIMESTAMP, false),
(24, 26, 23, 'os quais tiraram a Urias do Egito, e o trouxeram ao rei Jeoiaquim, que o matou à espada, e lançou o seu cadáver nas sepulturas da plebe.', 1, CURRENT_TIMESTAMP, false),
(24, 26, 24, 'Porém Aicão, filho de Safã, deu apoio a Jeremias, de sorte que não foi entregue na mão do povo, para ser morto.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 1, 'No princípio do reinado de Zedequias, filho de Josias, rei de Judá, veio esta palavra a Jeremias da parte do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 27, 2, 'Assim me disse o Senhor: Faze-te brochas e canzis e põe-nos ao teu pescoço.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 3, 'Depois envia-os ao rei de Edom, e ao rei de Moabe, e ao rei dos filhos de Amom, e ao rei de Tiro, e ao rei de Sidom, pela mão dos mensageiros que são vindos a Jerusalém a ter com zedequias, rei de Judá;', 1, CURRENT_TIMESTAMP, false),
(24, 27, 4, 'e lhes darás uma mensagem para seus senhores, dizendo: Assim diz o Senhor dos exércitos, o Deus de Israel: Assim direis a vossos senhores:', 1, CURRENT_TIMESTAMP, false),
(24, 27, 5, 'Sou eu que, com o meu grande poder e o meu braço estendido, fiz a terra com os homens e os animais que estão sobre a face da terra; e a dou a quem me apraz.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 6, 'E agora eu entreguei todas estas terras na mão de Nabucodonosor, rei de Babilônia, meu servo; e ainda até os animais do campo lhe dei, para que o sirvam.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 7, 'Todas as nações o servirão a ele, e a seu filho, e ao filho de seu filho, até que venha o tempo da sua própria terra; e então muitas nações e grandes reis se servirão dele.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 8, 'A nação e o reino que não servirem a Nabucodonosor, rei de Babilônia, e que não puserem o seu pescoço debaixo do jugo do rei de Babilônia, punirei com a espada, com a fome, e com a peste a essa nação, diz o Senhor, até que eu os tenha consumido pela mão dele.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 9, 'Não deis ouvidos, pois, aos vossos profetas, e aos vossos adivinhadores, e aos vossos sonhos, e aos vossos agoureiros, e aos vossos encantadores, que vos dizem: Não servireis o rei de Babilônia;', 1, CURRENT_TIMESTAMP, false),
(24, 27, 10, 'porque vos profetizam a mentira, para serdes removidos para longe da vossa terra, e eu vos expulsarei dela, e vós perecereis.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 11, 'Mas a nação que meter o seu pescoço sob o jugo do rei de Babilônia, e o servir, eu a deixarei na sua terra, diz o Senhor; e lavrá-la-á e habitará nela.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 12, 'E falei com Zedequias, rei de Judá, conforme todas estas palavras: Metei os vossos pescoços no jugo do rei de Babilônia, e servi-o, a ele e ao seu povo, e vivei.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 13, 'Por que morrereis tu e o teu povo, à espada, de fome, e de peste, como o Senhor disse acerca da nação que não servir ao rei de Babilônia?', 1, CURRENT_TIMESTAMP, false),
(24, 27, 14, 'Não deis ouvidos às palavras dos profetas que vos dizem: Não servireis ao rei de Babilônia; porque vos profetizam a mentira.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 15, 'Pois não os enviei, diz o Senhor, mas eles profetizam falsamente em meu nome; para que eu vos lance fora, e venhais a perecer, vós e os profetas que vos profetizam.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 16, 'Então falei aos sacerdotes, e a todo este povo, dizendo: Assim diz o Senhor: Não deis ouvidos às palavras dos vossos profetas, que vos profetizam dizendo: Eis que os utensílios da casa do senhor cedo voltarão de Babilônia; pois eles vos profetizam a mentira.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 17, 'Não lhes deis ouvidos; servi ao rei de Babilônia, e vivei. Por que se tornaria esta cidade em assolação?', 1, CURRENT_TIMESTAMP, false),
(24, 27, 18, 'Se, porém, são profetas, e se está com eles a palavra do Senhor, intercedam agora junto ao Senhor dos exércitos, para que os utensílios que ficaram na casa do Senhor, e na casa do rei de Judá, e em Jerusalém, não vão para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 27, 19, 'Pois assim diz o Senhor dos exércitos acerca das colunas, e do mar, e das bases, e dos demais utensílios que ficaram na cidade,', 1, CURRENT_TIMESTAMP, false),
(24, 27, 20, 'os quais Nabucodonosor, rei de Babilônia, não levou, quando transportou de Jerusalém para Babilônia a Jeconias, filho de Jeoiaquim, rei de Judá, como também a todos os nobres de Judá e de Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(24, 27, 21, 'assim pois diz o Senhor dos exércitos, o Deus de Israel, acerca dos utensílios que ficaram na casa do Senhor, e na casa do rei de Judá, e em Jerusalém:', 1, CURRENT_TIMESTAMP, false),
(24, 27, 22, 'Para Babilônia serão levados, e ali ficarão até o dia em que eu os visitar, diz o Senhor; então os farei subir, e os restituirei a este lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 1, 'E sucedeu no mesmo ano, no princípio do reinado de Zedequias, rei de Judá, no ano quarto, no mês quinto, que Hananias, filho de Azur, o profeta de Gibeão, me falou, na casa do Senhor, na presença dos sacerdotes e de todo o povo dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 28, 2, 'Assim fala o Senhor dos exércitos, o Deus de Israel, dizendo: Eu quebrarei o jugo do rei de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 3, 'Dentro de dois anos, eu tornarei a trazer a este lugar todos os utensílios da casa do Senhor, que deste lugar tomou Nabucodonosor, rei de Babilônia, levando-os para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 4, 'Também a Jeconias, filho de Jeoiaquim rei de Judá, e a todos os do cativeiro de, Judá, que entraram em Babilônia, eu os tornarei a trazer a este lugar, diz o Senhor; porque hei de quebrar o jugo do rei de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 5, 'Então falou o profeta Jeremias ao profeta Hananias, na presença dos sacerdotes, e na presença de todo o povo que estava na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 6, 'Disse pois Jeremias, o profeta: Amém! assim faça o Senhor; cumpra o Senhor as tuas palavras, que profetizaste, e torne ele a trazer os utensílios da casa do Senhor, e todos os do cativeiro, de Babilônia para este lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 7, 'Mas ouve agora esta palavra, que eu falo aos teus ouvidos e aos ouvidos de todo o povo:', 1, CURRENT_TIMESTAMP, false),
(24, 28, 8, 'Os profetas que houve antes de mim e antes de ti, desde a antigüidade, profetizaram contra muitos países e contra grandes reinos, acerca de guerra, de fome e de peste.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 9, 'Quanto ao profeta que profetuar de paz, quando se cumprir a palavra desse profeta, então será conhecido que o Senhor na verdade enviou o profeta.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 10, 'Então o profeta Hananias tomou o canzil do pescoço do profeta Jeremias e o quebrou.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 11, 'E falou Hananias na presença de todo o povo, dizendo: Isto diz o Senhor: Assim dentro de dois anos quebrarei o jugo de Nabucodonosor, rei de Babilônia, de sobre o pescoço de todas as nações. E Jeremias, o profeta, se foi seu caminho.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 12, 'Então veio a palavra do Senhor a Jeremias, depois de ter o profeta Hananias quebrado o jugo de sobre o pescoço do profeta Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 28, 13, 'Vai, e fala a Hananias, dizendo: Assim diz o Senhor: Jugos de madeira quebraste, mas em vez deles farei jugos de ferro', 1, CURRENT_TIMESTAMP, false),
(24, 28, 14, 'Pois assim diz o Senhor dos exércitos o Deus de Israel Jugo de ferro pus sobre o, pescoço de todas estas nações, para servirem a Nabucodonosor, rei de Babilônia, e o servirão; e até os animais do campo lhe dei.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 15, 'Então disse o profeta Jeremias ao profeta Hananias: Ouve agora, Hananias: O Senhor não te enviou, mas tu fazes que este povo confie numa mentira.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 16, 'Pelo que assim diz o Senhor: Eis que te lançarei de sobre a face da terra. Este ano morrerás, porque pregaste rebelião contra o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 28, 17, 'Morreu, pois, Hananias, o profeta, no mesmo ano, no sétimo mês.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 1, 'Ora, são estas as palavras da carta que Jeremias, o profeta, enviou de Jerusalém, aos que restavam dos anciãos do cativeiro, como também aos sacerdotes, e aos profetas, e a todo o povo, que Nabucodonosor levara cativos de Jerusalém para Babilônia,', 1, CURRENT_TIMESTAMP, false),
(24, 29, 2, 'depois de terem saído de Jerusalém o rei Jeconias, e a rainha-mãe, e os eunucos, e os príncipes de Judá e Jerusalém e os artífices e os ferreiros.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 3, 'Veio por mão de Elasa, filho de Safã, e de Gemarias, filho de Hilquias, os quais Zedequias, rei de Judá, enviou a Babilônia, a Nabucodonosor, rei de Babilônia; eis as palavras da carta:', 1, CURRENT_TIMESTAMP, false),
(24, 29, 4, 'Assim diz o Senhor dos exércitos, o Deus de Israel, a todos os do cativeiro, que eu fiz levar cativos de Jerusalém para Babilônia:', 1, CURRENT_TIMESTAMP, false),
(24, 29, 5, 'Edificai casas e habitai-as; plantai jardins, e comei o seu fruto.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 6, 'Tomai mulheres e gerai filhos e filhas; também tomai mulheres para vossos filhos, e dai vossas filhas a maridos, para que tenham filhos e filhas; assim multiplicai-vos ali, e não vos diminuais.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 7, 'E procurai a paz da cidade, para a qual fiz que fôsseis levados cativos, e orai por ela ao Senhor: porque na sua paz vós tereis paz.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 8, 'Pois assim diz o Senhor dos exércitos, o Deus de Israel: Não vos enganem os vossos profetas que estão no meio de vós, nem os vossos adivinhadores; nem deis ouvidos aos vossos sonhos, que vós sonhais;', 1, CURRENT_TIMESTAMP, false),
(24, 29, 9, 'porque eles vos profetizam falsamente em meu nome; não os enviei, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 10, 'Porque assim diz o Senhor: Certamente que passados setenta anos em Babilônia, eu vos visitarei, e cumprirei sobre vós a minha boa palavra, tornando a trazer-vos a este lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 11, 'Pois eu bem sei os planos que estou projetando para vós, diz o Senhor; planos de paz, e não de mal, para vos dar um futuro e uma esperança.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 12, 'Então me invocareis, e ireis e orareis a mim, e eu vos ouvirei.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 13, 'Buscar-me-eis, e me achareis, quando me buscardes de todo o vosso coração.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 14, 'E serei achado de vós, diz o Senhor, e farei voltar os vossos cativos, e congregarvos-ei de todas as nações, e de todos os lugares para onde vos lancei, diz o Senhor; e tornarei a trazer-vos ao lugar de onde vos transportei.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 15, 'Porque dizeis: O Senhor nos levantou profetas em Babilônia;', 1, CURRENT_TIMESTAMP, false),
(24, 29, 16, 'portanto assim diz o Senhor a respeito do rei que se assenta no trono de Davi, e de todo o povo que habita nesta cidade, vossos irmãos, que não saíram convosco para o cativeiro;', 1, CURRENT_TIMESTAMP, false),
(24, 29, 17, 'assim diz o Senhor dos exércitos: Eis que enviarei entre eles a espada, a fome e a peste e fá-los-ei como a figos péssimos, que não se podem comer, de ruins que são.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 18, 'E persegui-los-ei com a espada, com a fome e com a peste; farei que sejam um espetáculo de terror para todos os reinos da terra, e para serem um motivo de execração, de espanto, de assobio, e de opróbrio entre todas as nações para onde os tiver lançado,', 1, CURRENT_TIMESTAMP, false),
(24, 29, 19, 'porque não deram ouvidos às minhas palavras, diz o Senhor, as quais lhes enviei com insistência pelos meus servos, os profetas; mas vós não escutastes, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 20, 'Ouvi, pois, a palavra do Senhor, vós todos os do cativeiro que enviei de Jerusalém para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 21, 'Assim diz o Senhor dos exércitos, o Deus de Israel, acerca de Acabe, filho de Colaías, e de Zedequias, filho de Maaséias, que vos profetizam falsamente em meu nome: Eis que os entregarei na mão de Nabucodonosor, rei de Babilônia, e ele os matará diante dos vossos olhos.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 22, 'E por causa deles será formulada uma maldição por todos os exilados de Judá que estão em Babilônia, dizendo: O Senhor te faça como a Zedequias, e como a Acabe, os quais o rei de Babilônia assou no fogo;', 1, CURRENT_TIMESTAMP, false),
(24, 29, 23, 'porque fizeram insensatez em Israel, cometendo adultério com as mulheres de seus próximos, e anunciando falsamente em meu nome palavras que não lhes mandei. Eu o sei, e sou testemunha disso, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 24, 'E a Semaías, o neelamita, falarás, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 29, 25, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Porquanto enviaste em teu próprio nome cartas a todo o povo que está em Jerusalém, como também a Sofonias, filho de Maaséias, o sacerdote, e a todos os sacerdotes, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 29, 26, 'O Senhor te pôs por sacerdote em lugar de Jeoiada, o sacerdote, para que fosses encarregado da casa do Senhor, sobre todo homem obsesso que profetiza, para o lançares na prisão e no tronco;', 1, CURRENT_TIMESTAMP, false),
(24, 29, 27, 'agora, pois, por que não repreendeste a Jeremias, o anatotita, que vos profetiza?', 1, CURRENT_TIMESTAMP, false),
(24, 29, 28, 'Pois que até nos mandou dizer em Babilônia: O cativeiro muito há de durar; edificai casas, e habitai-as; e plantai jardins, e comei do seu fruto.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 29, 'E lera Sofonias, o sacerdote, esta carta aos ouvidos de Jeremias, o profeta.', 1, CURRENT_TIMESTAMP, false),
(24, 29, 30, 'Então veio a palavra do Senhor a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 29, 31, 'Manda a todos os do cativeiro, dizendo: Assim diz o Senhor acerca de Semaías, o neelamita: Porquanto Semaías vos profetizou, quando eu não o enviei, e vos fez confiar numa mentira,', 1, CURRENT_TIMESTAMP, false),
(24, 29, 32, 'portanto assim diz o Senhor: Eis que castigarei a Semaías, o neelamita, e a sua descendência; ele não terá varão que habite entre este povo, nem verá ele o bem que hei de fazer ao meu povo, diz o Senhor, porque pregou rebelião contra o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 1, 'A palavra que do Senhor veio a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 30, 2, 'Assim diz o Senhor, Deus de Israel: Escreve num livro todas as palavras que te falei;', 1, CURRENT_TIMESTAMP, false),
(24, 30, 3, 'pois eis que vêm os dias, diz o Senhor, em que farei voltar do cativeiro o meu povo Israel e Judá, diz o Senhor; e tornarei a trazê-los à terra que dei a seus pais, e a possuirão.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 4, 'E estas são as palavras que disse o Senhor, acerca de Israel e de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 5, 'Assim, pois, diz o Senhor: Ouvimos uma voz de tremor, de temor mas não de paz.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 6, 'Perguntai, pois, e vede, se um homem pode dar à luz. Por que, pois, vejo a cada homem com as mãos sobre os lombos como a que está de parto? Por que empalideceram todos os rostos?', 1, CURRENT_TIMESTAMP, false),
(24, 30, 7, 'Ah! porque aquele dia é tão grande, que não houve outro semelhante! É tempo de angústia para Jacó; todavia, há de ser livre dela.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 8, 'E será naquele dia, diz o Senhor dos exércitos, que eu quebrarei o jugo de sobre o seu pescoço, e romperei as suas brochas. Nunca mais se servirão dele os estrangeiros;', 1, CURRENT_TIMESTAMP, false),
(24, 30, 9, 'mas ele servirá ao Senhor, seu Deus, como também a Davi, seu rei, que lhe levantarei.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 10, 'Não temas pois tu, servo meu, Jacó, diz o Senhor, nem te espantes, ó Israel; pois eis que te livrarei de terras longínquas, e à tua descendência da terra do seu cativeiro; e Jacó voltará, e ficará tranqüilo e sossegado, e não haverá quem o atemorize.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 11, 'Porque eu sou contigo, diz o Senhor, para te salvar; porquanto darei fim cabal a todas as nações entre as quais te espalhei; a ti, porém, não darei fim, mas castigar-te-ei com medida justa, e de maneira alguma te terei por inocente.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 12, 'Porque assim diz o Senhor: Incurável é a tua fratura, e gravíssima a tua ferida.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 13, 'Não há quem defenda a tua causa; para a tua ferida não há remédio nem cura.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 14, 'Todos os teus amantes se esqueceram de ti; não te procuram; pois te feri com ferida de inimigo, e com castigo de quem é cruel, porque é grande a tua culpa, e têm-se multiplicado os teus pecados.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 15, 'Por que gritas por causa da tua fratura? tua dor é incurável. Por ser grande a tua culpa, e por se terem multiplicado os teus pecados, é que te fiz estas coisas.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 16, 'Portanto todos os que te devoram serão devorados, e todos os teus adversários irão, todos eles, para o cativeiro; e os que te roubam serão roubados, e a todos os que te saqueiam entregarei ao saque.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 17, 'Pois te restaurarei a saúde e te sararei as feridas, diz o Senhor; porque te chamaram a repudiada, dizendo: É Sião, à qual já ninguém procura.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 18, 'Assim diz o Senhor: Eis que acabarei o cativeiro das tendas de Jacó, e apiedarme-ei das suas moradas; e a cidade será reedificada sobre o seu montão, e o palácio permanecerá como habitualmente.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 19, 'E sairá deles ação de graças e a voz dos que se alegram; e multiplicá-los-ei, e não serão diminuídos; glorificá-los-ei, e não serão apoucados.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 20, 'E seus filhos serão como na antigüidade, e a sua congregação será estabelecida diante de mim, e castigarei todos os seus opressores.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 21, 'E o seu príncipe será deles, e o seu governador sairá do meio deles; e o farei aproximar, e ele se chegará a mim. Pois quem por si mesmo ousaria chegar-se a mim? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 22, 'E vós sereis o meu povo, e eu serei o vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 23, 'Eis a tempestade do Senhor! A sua indignação já saiu, uma tempestade varredora; cairá cruelmente sobre a cabeça dos ímpios.', 1, CURRENT_TIMESTAMP, false),
(24, 30, 24, 'Não retrocederá o furor da ira do Senhor, até que ele tenha executado, e até que tenha cumprido os desígnios do seu coração. Nos últimos dias entendereis isso.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 1, 'Naquele tempo, diz o Senhor, serei o Deus de todas as famílias de Israel, e elas serão o meu povo.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 2, 'Assim diz o Senhor: O povo que escapou da espada achou graça no deserto. Eu irei e darei descanso a Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 3, 'De longe o Senhor me apareceu, dizendo: Pois que com amor eterno te amei, também com benignidade te atraí.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 4, 'De novo te edificarei, e serás edificada ó virgem de Israel! ainda serás adornada com os teus adufes, e sairás nas danças dos que se alegram.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 5, 'Ainda plantarás vinhas nos montes de Samária; os plantadores plantarão e gozarão dos frutos.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 6, 'Pois haverá um dia em que gritarão os vigias sobre o monte de Efraim: Levantai-vos, e subamos a Sião, ao Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 7, 'Pois assim diz o Senhor: Cantai sobre Jacó com alegria, e exultai por causa da principal das nações; proclamai, cantai louvores, e dizei: Salva, Senhor, o teu povo, o resto de Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 8, 'Eis que os trarei da terra do norte e os congregarei das extremidades da terra; e com eles os cegos e aleijados, as mulheres grávidas e as de parto juntamente; em grande companhia voltarão para cá.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 9, 'Virão com choro, e com súplicas os levarei; guiá-los-ei aos ribeiros de águas, por caminho direito em que não tropeçarão; porque sou um pai para Israel, e Efraim é o meu primogênito.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 10, 'Ouvi a palavra do Senhor, ó nações, e anunciai-a nas longínquas terras marítimas, e dizei: Aquele que espalhou a Israel o congregará e o guardará, como o pastor ao seu rebanho.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 11, 'Pois o Senhor resgatou a Jacó, e o livrou da mão do que era mais forte do que ele.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 12, 'E virão, e cantarão de júbilo nos altos de Sião, e ficarão radiantes pelos bens do Senhor, pelo trigo, o mosto, e o azeite, pelos cordeiros e os bezerros; e a sua vida será como um jardim regado, e nunca mais desfalecerão.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 13, 'Então a virgem se alegrará na dança, como também os mancebos e os velhos juntamente; porque tornarei o seu pranto em gozo, e os consolarei, e lhes darei alegria em lugar de tristeza.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 14, 'E saciarei de gordura a alma dos sacerdotes, e o meu povo se fartará dos meus bens, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 15, 'Assim diz o Senhor: Ouviu-se um clamor em Ramá, lamentação e choro amargo. Raquel chora a seus filhos, e não se deixa consolar a respeito deles, porque já não existem.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 16, 'Assim diz o Senhor: Reprime a tua voz do choro, e das lágrimas os teus olhos; porque há galardão para o teu trabalho, diz o Senhor, e eles voltarão da terra do inimigo.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 17, 'E há esperança para o teu futuro, diz o Senhor; pois teus filhos voltarão para os seus termos.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 18, 'Bem ouvi eu que Efraim se queixava, dizendo: Castigaste-me e fui castigado, como novilho ainda não domado; restaura-me, para que eu seja restaurado, pois tu és o Senhor meu Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 19, 'Na verdade depois que me desviei, arrependi-me; e depois que fui instruído, bati na minha coxa; fiquei confundido e envergonhado, porque suportei o opróbrio da minha mocidade.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 20, 'Não é Efraim meu filho querido? filhinho em quem me deleito? Pois quantas vezes falo contra ele, tantas vezes me lembro dele solicitamente; por isso se comovem por ele as minhas entranhas; deveras me compadecerei dele, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 21, 'Põe-te marcos, faze postes que te guiem; dirige a tua atenção à estrada, ao caminho pelo qual foste; regressa, ó virgem de Israel, regressa a estas tuas cidades.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 22, 'Até quando andarás errante, ó filha rebelde? pois o senhor criou uma coisa nova na terra: uma mulher protege a um varão.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 23, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Ainda dirão esta palavra na terra de Judá, e nas suas cidades, quando eu acabar o seu cativeiro: O Senhor te abençoe, ó morada de justiça, ó monte de santidade!', 1, CURRENT_TIMESTAMP, false),
(24, 31, 24, 'E nela habitarão Judá, e todas as suas cidades juntamente; como também os lavradores e os que pastoreiam os rebanhos.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 25, 'Pois saciarei a alma cansada, e fartarei toda alma desfalecida.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 26, 'Nisto acordei, e olhei; e o meu sono foi doce para mim.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 27, 'Eis que os dias vêm, diz o Senhor, em que semearei de homens e de animais a casa de Israel e a casa de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 28, 'E será que, como vigiei sobre eles para arrancar e derribar, para transtornar, destruir, e afligir, assim vigiarei sobre eles para edificar e para plantar, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 29, 'Naqueles dias não dirão mais: Os pais comeram uvas verdes, e os dentes dos filhos se embotaram.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 30, 'Pelo contrário, cada um morrerá pela sua própria iniqüidade; de todo homem que comer uvas verdes, é que os dentes se embotarão.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 31, 'Eis que os dias vêm, diz o Senhor, em que farei um pacto novo com a casa de Israel e com a casa de Judá,', 1, CURRENT_TIMESTAMP, false),
(24, 31, 32, 'não conforme o pacto que fiz com seus pais, no dia em que os tomei pela mão, para os tirar da terra do Egito, esse meu pacto que eles invalidaram, apesar de eu os haver desposado, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 33, 'Mas este é o pacto que farei com a casa de Israel depois daqueles dias, diz o Senhor: Porei a minha lei no seu interior, e a escreverei no seu coração; e eu serei o seu Deus e eles serão o meu povo.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 34, 'E não ensinarão mais cada um a seu próximo, nem cada um a seu irmão, dizendo: Conhecei ao Senhor; porque todos me conhecerão, desde o menor deles até o maior, diz o Senhor; pois lhes perdoarei a sua iniqüidade, e não me lembrarei mais dos seus pecados.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 35, 'Assim diz o Senhor, que dá o sol para luz do dia, e a ordem estabelecida da lua e das estrelas para luz da noite, que agita o mar, de modo que bramem as suas ondas; o Senhor dos exércitos é o seu nome:', 1, CURRENT_TIMESTAMP, false),
(24, 31, 36, 'Se esta ordem estabelecida falhar diante de mim, diz o Senhor, deixará também a linhagem de Israel de ser uma nação diante de mim para sempre.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 37, 'Assim diz o Senhor: Se puderem ser medidos os céus lá em cima, e sondados os fundamentos da terra cá em baixo, também eu rejeitarei toda a linhagem de Israel, por tudo quanto eles têm feito, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 38, 'Eis que vêm os dias, diz o Senhor, em que esta cidade será reedificada para o Senhor, desde a torre de Hananel até a porta da esquina.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 39, 'E a linha de medir estender-se-á para diante, até o outeiro de Garebe, e dará volta até Goa.', 1, CURRENT_TIMESTAMP, false),
(24, 31, 40, 'E o vale inteiro dos cadáveres e da cinza, e todos os campos até o ribeiro de Cedrom, até a esquina da porta dos cavalos para o oriente, tudo será santo ao Senhor; nunca mais será arrancado nem derribado.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 1, 'A palavra que veio a Jeremias da parte do Senhor, no ano décimo de Zedequias, rei de Judá, o qual foi o ano dezoito de Nabucodonosor.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 2, 'Ora, cercava então o exército do rei de Babilônia a Jerusalém; e Jeremias, o profeta, se achava encerrado no pátio da guarda que estava na casa do rei de Judá;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 3, 'pois Zedequias, rei de Judá, o havia encarcerado, dizendo: Por que profetizas , dizendo: Assim diz o Senhor: Eis que entrego esta cidade na mão do rei de Babilônia, e ele a tomará;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 4, 'e Zedequias, rei de Judá, não escapará das mãos dos caldeus, mas certamente será entregue na mão do rei de Babilônia, e com ele falará boca a boca, e os seus olhos verão os olhos dele;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 5, 'e ele levará para Babilônia a Zedequias, que ali estará até que eu o visite, diz o Senhor, e, ainda que pelejeis contra os caldeus, não ganhareis?', 1, CURRENT_TIMESTAMP, false),
(24, 32, 6, 'Disse pois Jeremias: Veio a mim a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 32, 7, 'Eis que Hanamel, filho de Salum, teu tio, virá a ti, dizendo: Compra o meu campo que está em Anatote, pois tens o direito de resgate; a ti compete comprá-lo.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 8, 'Veio, pois, a mim Hanamel, filho de meu tio, segundo a palavra do Senhor, ao pátio da guarda, e me disse: Compra o meu campo que está em Anatote, na terra de Benjamim; porque teu é o direito de herança e teu é o de resgate; compra-o para ti. Então entendi que isto era a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 9, 'Comprei, pois, de Hanamel, filho de meu tio, o campo que está em Anatote; e pesei-lhe o dinheiro, dezessete siclos de prata.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 10, 'Assinei a escritura e a selei, chamei testemunhas, e pesei-lhe o dinheiro numa balança.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 11, 'E tomei a escritura da compra, que continha os termos e as condições, tanto a que estava selada, como a cópia que estava aberta,', 1, CURRENT_TIMESTAMP, false),
(24, 32, 12, 'e as dei a Baruque, filho de Nerias, filho de Maséias, na presença de Hanamel, filho de meu tio, e na presença das testemunhas que subscreveram a escritura da compra, à vista de todos os judeus que estavam sentados no pátio da guarda.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 13, 'E dei ordem a Banique, na presença deles, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 32, 14, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Toma estas escrituras de compra, tanto a selada, como a aberta, e mete-as num vaso de barro, para que se possam conservar muitos dias;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 15, 'pois assim diz o Senhor dos exércitos, o Deus de Israel: Ainda se comprarão casas, e campos, e vinhas nesta terra.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 16, 'E depois que dei a escritura da compra a Banique, filho de Nerias, orei ao Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 32, 17, 'Ah! Senhor Deus! És tu que fizeste os céus e a terra com o teu grande poder, e com o teu braço estendido! Nada há que te seja demasiado difícil!', 1, CURRENT_TIMESTAMP, false),
(24, 32, 18, 'Usas de benignidade para com milhares e tornas a iniqüidade dos pais ao seio dos filhos depois deles; tu és o grande, o poderoso Deus cujo nome é o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 19, 'Grande em conselho, e poderoso em obras, cujos olhos estão abertos sobre todos os caminhos dos filhos dos homens, para dares a cada um segundo os seus caminhos e segundo o fruto das suas obras;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 20, 'puseste sinais e maravilhas na terra do Egito até o dia de hoje, tanto em Israel, como entre os outros homens; e te fizeste um nome, qual tu tens neste dia.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 21, 'E tiraste o teu povo Israel da terra do Egito, com sinais e com maravilhas, e com mão forte, e com braço estendido, e com grande terror;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 22, 'e lhes deste esta terra, que juraste a seus pais que lhes havias de dar, terra que mana leite e mel.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 23, 'E entraram nela, e a possuíram; mas não obedeceram à tua voz, nem andaram na tua lei; de tudo o que lhes mandaste fazer, eles não fizeram nada; pelo que ordenaste lhes sucedesse todo este mal.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 24, 'Eis aqui os valados! já vieram contra a cidade para tomá-la e a cidade está entregue na mão dos caldeus que pelejam contra ela, pela espada, pela fome e pela peste. O que disseste se cumpriu, e eis aqui o estás presenciando.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 25, 'Contudo tu me disseste, ó Senhor Deus: Compra-te o campo por dinheiro, e chama testemunhas, embora a cidade já esteja dada na mão dos caldeus:', 1, CURRENT_TIMESTAMP, false),
(24, 32, 26, 'Então veio a palavra do Senhor a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 32, 27, 'Eis que eu sou o Senhor, o Deus de toda a carne; acaso há alguma coisa demasiado difícil para mim?', 1, CURRENT_TIMESTAMP, false),
(24, 32, 28, 'Portanto assim diz o Senhor: Eis que eu entrego esta cidade na mão dos caldeus, e na mão de Nabucodonosor, rei de Babilônia, e ele a tomará.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 29, 'E os caldeus que pelejam contra esta cidade entrarão nela, e lhe porão fogo, e a queimarão, juntamente com as casas sobre cujos terraços queimaram incenso a Baal e ofereceram libações a outros deuses, para me provocarem a ira.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 30, 'Pois os filhos de Israel e os filhos de Judá têm feito desde a sua mocidade tão somente o que era mau aos meus olhos; pois os filhos de Israel nada têm feito senão provocar-me à ira com as obras das suas mãos, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 31, 'Na verdade esta cidade, desde o dia em que a edificaram e até o dia de hoje, tem provocado a minha ira e o meu furor, de sorte que eu a removerei de diante de mim,', 1, CURRENT_TIMESTAMP, false),
(24, 32, 32, 'por causa de toda a maldade dos filhos de Israel e dos filhos de Judá, que fizeram para me provocarem à ira, eles e os seus reis, os seus príncipes, os seus sacerdotes e os seus profetas, como também os homens de Judá e os moradores de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 33, 'E viraram para mim as costas, e não o rosto; ainda que eu os ensinava, com insistência, eles não deram ouvidos para receberem instrução.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 34, 'Mas puseram as suas abominações na casa que se chama pelo meu nome, para a profanarem.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 35, 'Também edificaram os altos de Baal, que estão no vale do filho de Hinom, para fazerem passar seus filhos e suas filhas pelo fogo a Moloque; o que nunca lhes ordenei, nem me passou pela mente, que fizessem tal abominação, para fazerem pecar a Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 36, 'E por isso agora assim diz o Senhor, o Deus de Israel, acerca desta cidade, da qual vós dizeis: Já está dada na mão do rei de Babilônia, pela espada, e pela fome, e pela peste:', 1, CURRENT_TIMESTAMP, false),
(24, 32, 37, 'Eis que eu os congregarei de todos os países para onde os tenho lançado na minha ira, e no meu furor e na minha grande indignação; e os tornarei a trazer a este lugar, e farei que habitem nele seguramente.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 38, 'E eles serão o meu povo, e eu serei o seu Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 39, 'E lhes darei um só coração, e um só caminho, para que me temam para sempre, para seu bem e o bem de seus filhos, depois deles;', 1, CURRENT_TIMESTAMP, false),
(24, 32, 40, 'e farei com eles um pacto eterno de não me desviar de fazer-lhes o bem; e porei o meu temor no seu coração, para que nunca se apartem de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 41, 'E alegrar-me-ei por causa deles, fazendo-lhes o bem; e os plantarei nesta terra, com toda a fidelidade do meu coração e da minha alma.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 42, 'Pois assim diz o Senhor: Como eu trouxe sobre este povo todo este grande mal, assim eu trarei sobre eles todo o bem que lhes tenho prometido.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 43, 'E comprar-se-ão campos nesta terra, da qual vós dizeis: E uma desolação, sem homens nem animais; está entregue na mão dos caldeus.', 1, CURRENT_TIMESTAMP, false),
(24, 32, 44, 'Comprarão campos por dinheiro, assinarão escrituras e as selarão, e chamarão testemunhas, na terra de Benjamim, e nos lugares ao redor de Jerusalém, e nas cidades de Judá e nas cidades da região montanhosa, e nas cidades das planícies e nas cidades do Sul porque os farei voltar do cativeiro, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 1, 'E veio a palavra do Senhor a Jeremias, segunda vez, estando ele ainda encarcerado no pátio da guarda, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 33, 2, 'Assim diz o Senhor que faz isto, o Senhor que forma isto, para o estabelecer; o Senhor é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 3, 'Clama a mim, e responder-te-ei, e anunciar-te-ei coisas grandes e ocultas, que não sabes.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 4, 'Pois assim diz o Senhor, o Deus de Israel, acerca das casas desta cidade, e acerca das casas dos reis de Judá, que foram demolidas para fazer delas uma defesa contra os valados e contra a espada;', 1, CURRENT_TIMESTAMP, false),
(24, 33, 5, 'entrementes os caldeus estão entrando a pelejar para os encher de cadáveres de homens que ferirei na minha ira e no meu furor; porquanto escondi o meu rosto desta cidade, por causa de toda a sua maldade.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 6, 'Eis que lhe trarei a ela saúde e cura, e os sararei, e lhes manifestarei abundância de paz e de segurança.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 7, 'E farei voltar do cativeiro os exilados de Judá e de Israel, e os edificarei como ao princípio.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 8, 'E os purificarei de toda a iniqüidade do seu pecado contra mim; e perdoarei todas as suas iniqüidades, com que pecaram e transgrediram contra mim.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 9, 'E esta cidade me servirá de nome de gozo, de louvor e de glória, diante de todas as nações da terra que ouvirem de todo o bem que eu lhe faço; e espantar-se-ão e perturbar-se-ão por causa de todo o bem, e por causa de toda a paz que eu lhe dou.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 10, 'Assim diz o Senhor: Neste lugar do qual vós dizeis: E uma desolação, sem homens nem animais, sim, nas cidades de Judá, e nas ruas de Jerusalém, que estão assoladas, sem homens, sem moradores e sem animais, ainda se ouvira', 1, CURRENT_TIMESTAMP, false),
(24, 33, 11, 'a voz de gozo e a voz de alegria, a voz de noivo e a voz de noiva, e a voz dos que dizem: Dai graças ao Senhor dos exércitos, porque bom é o Senhor, porque a sua benignidade dura para sempre; também se ouvirá a voz dos que trazem à casa do Senhor sacrifícios de ação de graças. Pois farei voltar a esta terra os seus exilados como no princípio, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 12, 'Assim diz o Senhor dos exércitos: Ainda neste lugar, que está deserto, sem homens, e sem animais, e em todas as suas cidades, haverá uma morada de pastores que façam repousar aos seus rebanhos.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 13, 'Nas cidades da região montanhosa, nas cidades das planícies, e nas cidades do sul, e na terra de Benjamim, e nos contornos de Jerusalém, e nas cidades de Judá, ainda passarão os rebanhos pelas mãos dos contadores, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 14, 'Eis que vêm os dias, diz o Senhor, em que cumprirei a boa palavra que falei acerca da casa de Israel e acerca da casa de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 15, 'Naqueles dias e naquele tempo farei que brote a Davi um Renovo de justiça; ele executará juízo e justiça na terra.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 16, 'Naqueles dias Judá será salvo e Jerusalém habitará em segurança; e este é o nome que lhe chamarão: O SENHOR É NOSSA JUSTIÇA.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 17, 'Pois assim diz o Senhor: Nunca faltará a Davi varão que se assente sobre o trono da casa de Israel;', 1, CURRENT_TIMESTAMP, false),
(24, 33, 18, 'nem aos sacerdotes levíticos faltará varão diante de mim para oferecer holocaustos, e queimar ofertas de cereais e oferecer sacrifícios continuamente.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 19, 'E veio a palavra do Senhor a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 33, 20, 'Assim diz o Senhor: se puderdes invalidar o meu pacto com o dia, e o meu pacto com a noite, de tal modo que não haja dia e noite a seu tempo,', 1, CURRENT_TIMESTAMP, false),
(24, 33, 21, 'também se poderá invalidar o meu pacto com Davi, meu servo, para que não tenha filho que reine no seu trono; como também o pacto com os sacerdotes levíticos, meus ministros.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 22, 'Assim como não se pode contar o exército dos céus, nem medir-se a areia do mar, assim multiplicarei a descendência de Davi, meu servo, e os levitas, que ministram diante de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 23, 'E veio ainda a palavra do Senhor a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 33, 24, 'Acaso não observaste o que este povo está dizendo: As duas famílias que o Senhor escolheu, agora as rejeitou? Assim desprezam o meu povo, como se não fora um povo diante deles.', 1, CURRENT_TIMESTAMP, false),
(24, 33, 25, 'Assim diz o Senhor: Se o meu pacto com o dia e com a noite não permanecer, e se eu não tiver determinado as ordenanças dos céus e da terra,', 1, CURRENT_TIMESTAMP, false),
(24, 33, 26, 'também rejeitarei a descendência de Jacó, e de Davi, meu servo, de modo que não tome da sua descendência os que dominem sobre a descendência de Abraão, Isaque, e Jacó; pois eu os farei voltar do seu cativeiro, e apiedar-me-ei deles.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 1, 'A palavra que da parte do Senhor veio a Jeremias, quando Nabucodonosor, rei de Babilônia, e todo o seu exército, e todos os reinos da terra que estavam sob o domínio da sua mão, e todos os povos, pelejavam contra Jerusalém, e contra todas as suas cidades, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 34, 2, 'Assim diz o Senhor, Deus de Israel: Vai, e fala a Zedequias, rei de Judá, e dize-lhe: Assim diz o Senhor: Eis que estou prestes a entregar esta cidade na mão do rei de Babilônia, o qual a queimará a fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 3, 'E tu não escaparás da sua mão; mas certamente serás preso e entregue na sua mão; e teus olhos verão os olhos do rei de Babilônia, e ele te falará boca a boca, e irás a Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 4, 'Todavia ouve a palavra do Senhor, ó Zedequias, rei de Judá; assim diz o Senhor acerca de ti: Não morrerás à espada;', 1, CURRENT_TIMESTAMP, false),
(24, 34, 5, 'em paz morrerás, e como queimavam perfumes a teus pais, os reis precedentes, que foram antes de ti, assim tos queimarão a ti; e te prantearão, dizendo: Ah Senhor! Pois eu disse a palavra, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 6, 'E anunciou Jeremias, o profeta, a Zedequias, rei de Judá, todas estas palavras, em Jerusalém,', 1, CURRENT_TIMESTAMP, false),
(24, 34, 7, 'quando o exército do rei de Babilônia pelejava contra Jerusalém, e contra todas as cidades de Judá, que ficaram de resto, contra Laquis e contra Azeca; porque dentre as cidades de Judá, só estas haviam ficado como cidades fortificadas.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 8, 'A palavra que da parte do Senhor veio a Jeremias, depois que o rei Zedequias fez um pacto com todo o povo que estava em Jerusalém, para lhe fazer proclamação de liberdade,', 1, CURRENT_TIMESTAMP, false),
(24, 34, 9, 'para que cada um libertasse o seu escravo, e cada um a sua escrava, hebreu ou hebréia, de maneira que ninguém se servisse mais dos judeus, seus irmãos, como escravos.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 10, 'E obedeceram todos os príncipes e todo o povo que haviam entrado no pacto de libertarem cada qual o seu escravo, e cada qual a sua escrava, de maneira a não se servirem mais deles, sim, obedeceram e os libertaram.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 11, 'Mas depois se arrependeram, e fizeram voltar os escravos e as escravas que haviam libertado, e tornaram a escravizá-los.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 12, 'Veio, pois, a palavra do Senhor a Jeremias, da parte do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 34, 13, 'Assim diz o Senhor, Deus de Israel: Eu fiz um pacto com vossos pais, no dia em que os tirei da terra do Egito, da casa da servidão, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 34, 14, 'Ao fim de sete anos libertareis cada um a seu irmão hebreu, que te for vendido, e te houver servido seis anos, e despedi-lo-ás livre de ti; mas vossos pais não me ouviram, nem inclinaram os seus ouvidos.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 15, 'E vos havíeis hoje arrependido, e tínheis feito o que é reto aos meus olhos, proclamando liberdade cada um ao seu próximo; e tínheis feito diante de mim um pacto, na casa que se chama pelo meu nome;', 1, CURRENT_TIMESTAMP, false),
(24, 34, 16, 'mudastes, porém, e profanastes o meu nome, e fizestes voltar cada um o seu escravo, e cada um a sua escrava, que havíeis deixado ir livres à vontade deles; e os sujeitastes de novo à servidão.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 17, 'Portanto assim diz o Senhor: Vós não me ouvistes a mim, para proclamardes a liberdade, cada um ao seu irmão, e cada um ao seu próximo. Eis, pois, que eu vos proclamo a liberdade, diz o Senhor, para a espada, para a peste e para a fome; e farei que sejais um espetáculo de terror a todos os reinos da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 18, 'Entregarei os homens que traspassaram o meu pacto, e não cumpriram as palavras do pacto que fizeram diante de mim com o bezerro que dividiram em duas partes, passando pelo meio das duas porções.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 19, 'Os príncipes de Judá, os príncipes de Jerusalém, os eunucos, os sacerdotes, e todo o povo da terra, os mesmos que passaram pelo meio das porções do bezerro,', 1, CURRENT_TIMESTAMP, false),
(24, 34, 20, 'entregá-los-ei, digo, na mão de seus inimigos, e na mão dos que procuram a sua morte. Os cadáveres deles servirão de pasto para as aves do céu e para os animais da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 21, 'E a Zedequias, rei de Judá, e seus príncipes entregarei na mão de seus inimigos e na mão dos que procuram a sua morte, e na mão do exército do rei de Babilônia, os quais já se retiraram de vós.', 1, CURRENT_TIMESTAMP, false),
(24, 34, 22, 'Eis que eu darei ordem, diz o Senhor, e os farei tornar a esta cidade, e pelejarão contra ela, e a tomarão, e a queimarão a fogo; e das cidades de Judá farei uma assolação, de sorte que ninguém habite nelas.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 1, 'A palavra que da parte do Senhor veio a Jeremias, nos dias de Jeoiaquim, filho de Josias, rei de Judá, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 35, 2, 'Vai à casa dos recabitas, e fala com eles, introduzindo-os na casa do Senhor, em uma das câmaras, e lhes oferece vinho a beber.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 3, 'Então tomei a Jaazanias, filho de Jeremias, filho de Habazínias, e a seus irmãos, e a todos os seus filhos, e a toda a casa dos recabitas,', 1, CURRENT_TIMESTAMP, false),
(24, 35, 4, 'e os introduzi na casa do Senhor, na câmara dos filhos de Hanã, filho de Jigdalias, homem de Deus, a qual estava junto à câmara dos príncipes que ficava sobre a câmara de Maaséias, filho de Salum, guarda do vestíbulo;', 1, CURRENT_TIMESTAMP, false),
(24, 35, 5, 'e pus diante dos filhos da casa dos recabitas taças cheias de vinho, e copos, e disse-lhes: Bebei vinho.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 6, 'Eles, porém, disseram: Não beberemos vinho, porque Jonadabe, filho de Recabe, nosso pai, nos ordenou, dizendo: Nunca jamais bebereis vinho, nem vós nem vossos filhos;', 1, CURRENT_TIMESTAMP, false),
(24, 35, 7, 'não edificareis casa, nem semeareis semente, nem plantareis vinha, nem a possuireis; mas habitareis em tendas todos os vossos dias; para que vivais muitos dias na terra em que andais peregrinando.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 8, 'Obedecemos pois à voz de Jonadabe, filho de Recabe, nosso pai, em tudo quanto nos ordenou, de não bebermos vinho em todos os nossos dias, nem nós, nem nossas mulheres, nem nossos filhos, nem nossas filhas;', 1, CURRENT_TIMESTAMP, false),
(24, 35, 9, 'nem de edificarmos casas para nossa habitação; nem de possuirmos vinha, nem campo, nem semente;', 1, CURRENT_TIMESTAMP, false),
(24, 35, 10, 'mas habitamos em tendas, e assim obedecemos e fazemos conforme tudo quanto nos ordenou Jonadabe, nosso pai.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 11, 'Sucedeu, porém, que, quando subia Nabucodonosor, rei de Babilônia, contra esta terra, dissemos: Vinde, e vamo-nos a Jerusalém, por causa do exército dos caldeus, e por causa do exército dos sírios; e assim habitamos em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 12, 'Então veio a palavra do Senhor a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 35, 13, 'Assim diz o Senhor dos exércitos, o Deus de Israel: Vai, e dize aos homens de Judá e aos moradores de Jerusalém: Acaso não aceitareis instrução, para ouvirdes as minhas palavras? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 14, 'As palavras de Jonadabe, filho de Recabe, pelas quais ordenou a seus filhos que não bebessem vinho, foram guardadas; pois não o têm bebido até o dia de hoje, porque obedecem o mandamento de seu pai; a mim, porém, que vos tenho falado a vós, com insistência, vós não me ouvistes.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 15, 'Também vos tenho enviado, insistentemente, todos os meus servos, os profetas, dizendo: Convertei-vos agora, cada um do seu mau caminho, e emendai as vossas ações, e não vades após outros deuses para os servir, e assim habitareis na terra que vos dei a vós e a vossos pais; mas não inclinastes o vosso ouvido, nem me obedecestes a mim.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 16, 'Os filhos de Jonadabe, filho de Recabe, guardaram o mandamento de seu pai que ele lhes ordenou, mas este povo não me obedeceu;', 1, CURRENT_TIMESTAMP, false),
(24, 35, 17, 'por isso assim diz o Senhor, o Deus dos exércitos, o Deus de Israel: Eis que trarei sobre Judá, e sobre todos os moradores de Jerusalém, todo o mal que pronunciei contra eles; pois lhes tenho falado, e não ouviram; e clamei a eles, e não responderam.', 1, CURRENT_TIMESTAMP, false),
(24, 35, 18, 'E à casa dos recabitas disse Jeremias: Assim diz o Senhor dos exércitos, o Deus de Israel: Pois que obedecestes ao mandamento de Jonadabe, vosso pai, guardando todos os seus mandamentos e fazendo conforme tudo quanto vos ordenou;', 1, CURRENT_TIMESTAMP, false),
(24, 35, 19, 'portanto assim diz o Senhor dos exércitos, Deus de Israel: Nunca jamais faltará varão a Jonadabe, filho de Recabe, que assista diante de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 1, 'Sucedeu pois no ano quarto de Jeoiaquim, filho de Josias, rei de Judá, que da parte do Senhor veio esta palavra a Jeremias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 36, 2, 'Toma o rolo dum livro, e escreve nele todas as palavras que te hei falado contra Israel, contra Judá e contra todas as nações, desde o dia em que eu te falei, desde os dias de Josias até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 3, 'Ouvirão talvez os da casa de Judá todo o mal que eu intento fazer-lhes; para que cada qual se converta do seu mau caminho, a fim de que eu perdoe a sua iniqüidade e o seu pecado.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 4, 'Então Jeremias chamou a Baruque, filho de Nerias; e escreveu Baruque, no rolo dum livro, enquanto Jeremias lhas ditava, todas as palavras que o Senhor lhe havia falado.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 5, 'E Jeremias deu ordem a Banique, dizendo: Eu estou impedido; não posso entrar na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 6, 'Entra pois tu e, pelo rolo que escreveste enquanto eu ditava, lê as palavras do Senhor aos ouvidos do povo, na casa do Senhor, no dia de jejum; e também as lerás aos ouvidos de todo o Judá que vem das suas cidades.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 7, 'Pode ser que caia a sua súplica diante do Senhor, e se converta cada um do seu mau caminho; pois grande é a ira e o furor que o Senhor tem manifestado contra este povo.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 8, 'E fez Baruque, filho de Nerias, conforme tudo quanto lhe havia ordenado Jeremias, o profeta, lendo no livro as palavras do Senhor na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 9, 'No quinto ano de Jeoiaquim, filho de Josias, rei de Judá, no mês nono, todo o povo em Jerusalém, como também todo o povo que vinha das cidades de Judá a Jerusalém, apregoaram um jejum diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 10, 'Leu, pois, Banique no livro as palavras de Jeremias, na casa do Senhor, na câmara de Gemarias, filho de Safã, o escriba, no átrio superior, à entrada da porta nova da casa do Senhor, aos ouvidos de todo o povo.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 11, 'E, ouvindo Micaías, filho de Gemarias, filho de Safã, todas as palavras do Senhor, naquele livro,', 1, CURRENT_TIMESTAMP, false),
(24, 36, 12, 'desceu à casa do rei, à câmara do escriba. E eis que todos os príncipes estavam ali assentados: Elisama, o escriba, e Delaías, filho de Semaías, e Elnatã, filho de Acbor, e Gemarias, filho de Safã, e Zedequias, filho de Hananias, e todos os outros príncipes.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 13, 'E Micaías anunciou-lhes todas as palavras que ouvira, quando Baruque leu o livro aos ouvidos do povo.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 14, 'Então todos os príncipes mandaram Jeúdi, filho de Netanias, filho Selemias, filho de Cuche, a Baruque, para lhe dizer: O rolo que leste aos ouvidos do povo, toma-o na tua mão, e vem. E Banique, filho de Nerias, tomou o rolo na sua mão, e foi ter com eles.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 15, 'E disseram-lhe: Assenta-te agora, e lê-o aos nossos ouvidos. E Baruque o leu aos ouvidos deles.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 16, 'Ouvindo eles todas aquelas palavras, voltaram-se temerosos uns para os outros, e disseram a Banique: Sem dúvida alguma temos que anunciar ao rei todas estas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 17, 'E disseram a Baruque: Declara-nos agora como escreveste todas estas palavras. Ele as ditava?', 1, CURRENT_TIMESTAMP, false),
(24, 36, 18, 'E disse-lhes Baruque: Sim, da sua boca ele me ditava todas estas palavras, e eu com tinta as escrevia no livro.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 19, 'Então disseram os príncipes a Banique: Vai, esconde-te tu e Jeremias; e ninguém saiba onde estais.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 20, 'E foram ter com o rei ao átrio; mas depositaram o rolo na câmara de Elisama, o escriba, e anunciaram aos ouvidos do rei todas aquelas palavras.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 21, 'Então enviou o rei a Jeúdi para trazer o rolo; e Jeúdi tomou-o da câmara de Elisama, o escriba, e o leu aos ouvidos do rei e aos ouvidos de todos os príncipes que estavam em torno do rei.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 22, 'Ora, era o nono mês e o rei estava assentado na casa de inverno, e diante dele estava um braseiro aceso.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 23, 'E havendo Jeúdi lido três ou quatro colunas, o rei as cortava com o canivete do escrivão, e as lançava no fogo que havia no braseiro, até que todo o rolo se consumiu no fogo que estava sobre o braseiro.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 24, 'E não temeram, nem rasgaram os seus vestidos, nem o rei nem nenhum dos seus servos que ouviram todas aquelas palavras', 1, CURRENT_TIMESTAMP, false),
(24, 36, 25, 'e, posto que Elnatã, Delaías e Gema rias tivessem insistido com o rei que não queimasse o rolo, contudo ele não lhes deu ouvidos.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 26, 'Antes deu ordem o rei a Jerameel, filho do rei, e a Seraías, filho de Azriel, e a Selemias, filho de Abdeel, que prendessem a Baruque, o escrivão, e a Jeremias, o profeta; mas o Senhor os escondera.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 27, 'Depois que o rei queimara o rolo com as palavras que Banique escrevera da boca de Jeremias, veio a Jeremias a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 36, 28, 'Toma ainda outro rolo, e escreve nele todas aquelas palavras que estavam no primeiro rolo, que Jeoiaquim, rei de Judá, queimou.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 29, 'E a Jeoiaquim, rei de Judá, dirás: Assim diz o Senhor: Tu queimaste este rolo, dizendo: Por que escreveste nele anunciando: Certamente virá o rei da Babilônia, e destruirá esta terra e fará cessar nela homens e animais?,', 1, CURRENT_TIMESTAMP, false),
(24, 36, 30, 'Portanto assim diz o Senhor acerca de Jeoiaquim, rei de Judá: Não terá quem se assente sobre o trono de Davi, e será lançado o seu cadáver ao calor de dia, e à geada de noite.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 31, 'E castigá-lo-ei a ele, e a sua descendência e os seus servos, por causa da sua iniqüidade; e trarei sobre ele e sobre os moradores de Jerusalém, e sobre os homens de Judá, todo o mal que tenho pronunciado contra eles, e que não ouviram.', 1, CURRENT_TIMESTAMP, false),
(24, 36, 32, 'Tomou, pois, Jeremias outro rolo, e o deu a Baruque, filho de Nerias, o escrivão, o qual escreveu nele, enquanto Jeremias ditava, todas as palavras do livro que Jeoiaquim, rei de Judá, tinha queimado no fogo; e ainda se lhes acrescentaram muitas palavras semelhantes.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 1, 'E Zedequias, filho de Josias, a quem Nabucodonosor, rei de Babilônia, constituiu rei na terra de Judá, reinou em lugar de Conias, filho de Jeoiaquim.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 2, 'Mas nem ele, nem os seus servos, nem o povo da terra escutaram as palavras do Senhor que este falou por intermédio de Jeremias o profeta.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 3, 'Contudo mandou o rei Zedequias a Jeucal filho de Selemias, e a Sofonias, filho de Maaséias, o sacerdote, ao profeta Jeremias, para lhe dizerem: Roga agora por nós ao Senhor nosso Deus,', 1, CURRENT_TIMESTAMP, false),
(24, 37, 4, 'Ora, Jeremias entrava e saía entre o povo; pois ainda não o tinham encerrado na prisão.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 5, 'E o exército de Faraó saíra do Egito; quando, pois, os caldeus que estavam sitiando Jerusalém, ouviram esta notícia, retiraram-se de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 6, 'Então veio a Jeremias, o profeta, a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 37, 7, 'Assim diz o Senhor, Deus de Israel: Assim direis ao rei de Judá, que vos enviou a mim, para me consultar: Eis que o exército de Faraó, que saiu em vosso socorro, voltará para a sua terra no Egito.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 8, 'E voltarão os caldeus, e pelejarão contra esta cidade, e a tomarão, e a queimarão a fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 9, 'Assim diz o Senhor: Não vos enganeis a vós mesmos, dizendo: Sem dúvida os caldeus se retirarão de nós; pois não se retirarão.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 10, 'Porque ainda que derrotásseis a todo o exército dos caldeus que peleja contra vós, e entre eles só ficassem homens feridos, contudo se levantariam, cada um na sua tenda, e queimariam a fogo esta cidade.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 11, 'Ora, quando se retirou de Jerusalém o exército dos caldeus, por causa do exército de Iearaó,', 1, CURRENT_TIMESTAMP, false),
(24, 37, 12, 'saiu Jeremias de Jerusalém, a fim de ir à terra de Benjamim, para receber ali a sua parte no meio do povo.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 13, 'E quando ele estava à porta de Benjamim, achava-se ali um capitão da guarda, cujo nome era Jurias, filho de Selemias, filho de Hananias, o qual prendeu a Jeremias, o profeta, dizendo: Tu estás desertando para os caldeus.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 14, 'E Jeremias disse: Isso é falso, não estou desertando para os caldeus. Mas ele não lhe deu ouvidos, de modo que prendeu a Jeremias e o levou aos príncipes.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 15, 'E os príncipes ficaram muito irados contra Jeremias, de sorte que o açoitaram e o meteram no cárcere, na casa de Jônatas, o escrivão, porquanto a tinham transformado em cárcere.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 16, 'Tendo Jeremias entrado nas celas do calabouço, e havendo ficado ali muitos dias,', 1, CURRENT_TIMESTAMP, false),
(24, 37, 17, 'o rei Zedequias mandou soltá-lo e lhe perguntou em sua casa, em segredo: Há alguma palavra da parte do Senhor? Respondeu Jeremias: Há. E acrescentou: Na mão do rei de Babilônia serás entregue.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 18, 'Disse mais Jeremias ao rei Zedequias: Em que tenho pecado contra ti, e contra os teus servos, e contra este povo, para que me pusésseis na prisão?', 1, CURRENT_TIMESTAMP, false),
(24, 37, 19, 'Onde estão agora os vossos profetas que vos profetizavam, dizendo: O rei de Babilônia não virá contra vós nem contra esta terra?', 1, CURRENT_TIMESTAMP, false),
(24, 37, 20, 'Ora, pois, ouve agora, ó rei, meu senhor: seja aceita agora a minha súplica diante de ti; não me faças tornar à casa de Jônatas, o escriba, para que eu não venha a morrer ali.', 1, CURRENT_TIMESTAMP, false),
(24, 37, 21, 'Então ordenou o rei Zedequias que pusessem a Jeremias no átrio da guarda; e deram-lhe um bolo de pão cada dia, da rua dos padeiros, até que se gastou todo o pão da cidade. Assim ficou Jeremias no átrio da guarda.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 1, 'Ouviram, pois, Sefatias, filho de Matã, e Gedalias, filho de Pasur, e Jeucal, filho de Selemias, e Pasur, filho de Malquias, as palavras que anunciava Jeremias a todo o povo, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 38, 2, 'Assim diz o Senhor: O que ficar nesta cidade morrerá à espada, de fome e de peste; mas o que sair para os caldeus viverá; pois a sua vida lhe será por despojo, e vivera.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 3, 'Assim diz o Senhor: Esta cidade infalivelmente será entregue na mão do exército do rei de Babilônia, e ele a tomará.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 4, 'E disseram os príncipes ao rei: Morra este homem, visto que ele assim enfraquece as mãos dos homens de guerra que restam nesta cidade, e as mãos de todo o povo, dizendo-lhes tais palavras; porque este homem não busca a paz para este povo, porem o seu mal.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 5, 'E disse o rei Zedequias: Eis que ele está na vossa mão; porque não é o rei que possa coisa alguma contra vós.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 6, 'Então tomaram a Jeremias, e o lançaram na cisterna de Malquias, filho do rei, que estava no átrio da guarda; e desceram Jeremias com cordas; mas na cisterna não havia água, senão lama, e atolou-se Jeremias na lama.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 7, 'Quando Ebede-Meleque, o etíope, um eunuco que então estava na casa do rei, ouviu que tinham metido Jeremias na cisterna, o rei estava assentado à porta de Benjamim.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 8, 'Saiu, pois, Ebede-Meleque da casa do rei, e falou ao rei, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 38, 9, 'o rei, senhor meu, estes homens fizeram mal em tudo quanto fizeram a Jeremias, o profeta, lançando-o na cisterna; de certo morrerá no lugar onde se acha, por causa da fome, pois não há mais pão na cidade.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 10, 'Deu ordem, então, o rei a Ebede-Meleque, o etíope, dizendo: Toma contigo daqui três homens, e tira Jeremias, o profeta, da cisterna, antes que morra.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 11, 'Assim Ebede-Meleque tomou consigo os homens, e entrou na casa do rei, debaixo da tesouraria, e tomou dali uns trapos velhos e rotos, e roupas velhas, e desceu-os a Jeremias na cisterna por meio de cordas.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 12, 'E disse Ebede-Meleque, o etíope, a Jeremias: Põe agora estes trapos velhos e rotos, debaixo dos teus sovacos, entre os braços e as cordas. E Jeremias assim o fez.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 13, 'E tiraram Jeremias com as cordas, e o alçaram da cisterna; e ficou Jeremias no átrio da guarda.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 14, 'Então mandou o rei Zedequias e fez vir à sua presença Jeremias, o profeta, à terceira entrada do templo do Senhor; e disse o rei a Jeremias: Vou perguntar-te uma coisa; não me encubras nada.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 15, 'E disse Jeremias a Zedequias: Se eu te declarar, acaso não me matarás? E se eu te aconselhar, não me ouvirás.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 16, 'Então jurou o rei Zedequias a Jeremias, em segredo, dizendo: Vive o Senhor, que nos fez esta alma, que não te matarei nem te entregarei na mão destes homens que procuram a tua morte.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 17, 'Então Jeremias disse a Zedequias: Assim diz o Senhor, Deus dos exércitos, Deus de Israel: Se te renderes aos príncipes do rei de Babilônia, será poupada a tua vida, e esta cidade não se queimará a fogo, e viverás tu e a tua casa.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 18, 'Mas, se não saíres aos príncipes do rei de Babilônia, então será entregue esta cidade na mão dos caldeus, e eles a queimarão a fogo, e tu não escaparás da sua mão.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 19, 'E disse o rei Zedequias a Jeremias: Receio-me dos judeus que se passaram para os caldeus, que seja entregue na mão deles, e escarneçam de mim.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 20, 'Jeremias, porém, disse: Não te entregarão. Ouve, peço-te, a voz do Senhor, conforme a qual eu te falo; e bem te irá, e poupar-se-á a tua vida.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 21, 'Mas, se tu recusares sair, esta é a palavra que me mostrou o Senhor:', 1, CURRENT_TIMESTAMP, false),
(24, 38, 22, 'Eis que todas as mulheres que ficaram na casa do rei de Judá serão levadas aos príncipes do rei de Babilônia, e elas mesmas dirão: Os teus pacificadores te incitaram e prevaleceram contra ti; e agora que se atolaram os teus pés na lama, voltaram atrás.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 23, 'Todas as tuas mulheres e os teus filhos serão levados para fora aos caldeus; e tu não escaparás da sua mão, mas pela mão do rei de Babilônia serás preso, e esta cidade será queimada a fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 24, 'Então disse Zedequias a Jeremias: Ninguém saiba estas palavras, e não morrerás.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 25, 'Se os príncipes ouvirem que falei contigo, e vierem ter contigo e te disserem: Declara-nos agora o que disseste ao rei e o que o rei te disse; não no-lo encubras, e não te mataremos;', 1, CURRENT_TIMESTAMP, false),
(24, 38, 26, 'então lhes dirás: Eu lancei a minha súplica diante do rei, que não me fizesse tornar à casa de Jônatas, para morrer ali.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 27, 'Então vieram todos os príncipes a Jeremias, e o interrogaram; e ele lhes respondeu conforme todas as palavras que o rei lhe havia ordenado; assim cessaram de falar com ele, pois a coisa não foi percebida.', 1, CURRENT_TIMESTAMP, false),
(24, 38, 28, 'E ficou Jeremias no átrio da guarda, até o dia em que Jerusalém foi tomada.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 1, 'No ano nono de Zedequias, rei de Judá, no décimo mês, veio Nabucodonosor, rei de Babilônia, e todo o seu exército contra Jerusalém, e a cercaram.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 2, 'No ano undécimo de Zedequias, no quarto mês, aos nove do mês, fez-se uma brecha na cidade.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 3, 'E entraram todos os príncipes do rei de Babilônia, e sentaram-se na porta do meio, os quais eram Nergal-Sarezer, Sangar-Nebo, Sarsequim, Rabe-Sáris Nergal Sarezer, Rabe-Maque, juntamente, com todo o resto dos príncipes do rei de Babilônia', 1, CURRENT_TIMESTAMP, false),
(24, 39, 4, 'E sucedeu que, vendo-os Zedequias, rei de Judá, e todos os homens de guerra, fugiram, saindo da cidade de noite pelo caminho do jardim do rei, pela porta entre os dois muros; e seguiram pelo caminho da Arabá.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 5, 'Mas o exército dos caldeus os perseguiu; e eles alcançaram a Zedequias nas campinas de Jericó; e, prendendo-o, levaram-no a Nabucodonosor rei de Babilônia, a Ribla, na terra de Hamate; e o rei o sentenciou.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 6, 'E o rei de Babilônia matou os filhos de Zedequias em Ribla, à sua vista; também matou o rei de Babilônia a todos os nobres de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 7, 'Cegou os olhos a Zedequias, e o atou com cadeias de bronze, para levá-lo a Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 8, 'Os caldeus incendiaram a casa do rei e as casas do povo, e derribaram os muros de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 9, 'Então, ao resto do povo, que ficara na cidade, aos desertores que se tinham passado para ele e ao resto do povo que havia ficado, levou-os Nebuzaradão, capitão da guarda, para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 10, 'Mas aos pobres dentre o povo, que não tinham nada, Nebuzaradão, capitão da guarda, deixou-os ficar na terra de Judá; e ao mesmo tempo lhes deu vinhas e campos.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 11, 'Ora Nabucodonosor, rei de Babilônia, havia ordenado acerca de Jeremias, a Nebuzaradão, capitão dos da guarda, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 39, 12, 'Toma-o, e trata-o bem, e não lhe faças mal algum; mas como ele te disser, assim procederás para com ele.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 13, 'Pelo que Nebuzaradão, capitão da guarda, Nebusazbã, Rabe-Sáris, Nergal-Sarezer, Rabe-Maeue, e todos os príncipes do rei de Babilônia', 1, CURRENT_TIMESTAMP, false),
(24, 39, 14, 'mandaram retirar Jeremias do átrio da guarda, e o entregaram a Gedalias, filho de Aicão, filho de Safã, para que o levasse para casa; assim ele habitou entre o povo.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 15, 'Ora, a palavra do Senhor viera a Jeremias, estando ele ainda encarcerado no átrio da guarda, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 39, 16, 'Vai, e fala a Ebede-Meleque, o etíope, dizendo: Assim diz o Senhor dos exércitos, Deus de Israel: Eis que eu cumprirei as minhas palavras sobre esta cidade para mal e não para bem; e se cumprirão diante de ti naquele dia.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 17, 'A ti, porém, eu livrarei naquele dia, diz o Senhor, e não serás entregue na mão dos homens a quem temes.', 1, CURRENT_TIMESTAMP, false),
(24, 39, 18, 'Pois certamente te salvarei, e não cairás à espada, mas a tua vida terás por despojo, porquanto confiaste em mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 1, 'A palavra que veio a Jeremias da parte do Senhor, depois que Nebuzaradão, capitão da guarda, o deixara ir de Ramá, quando o havia tomado, estando ele atado com cadeias no meio de todos os do cativeiro de Jerusalém e de Judá, que estavam sendo levados cativos para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 2, 'Ora o capitão da guarda levou Jeremias, e lhe disse: O Senhor teu Deus pronunciou este mal contra este lugar;', 1, CURRENT_TIMESTAMP, false),
(24, 40, 3, 'e o Senhor o trouxe, e fez como havia dito; porque pecastes contra o Senhor, e não obedecestes à sua voz, portanto vos sucedeu tudo isto.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 4, 'Agora pois, eis que te solto hoje das cadeias que estão sobre as tuas mãos. Se te apraz vir comigo para Babilônia, vem, e eu velarei por ti; mas, se não te apraz vir comigo para Babilônia, deixa de vir. Olha, toda a terra está diante de ti; para onde te parecer bem e conveniente ir, para ali vai.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 5, 'Se assim quiseres, volta a Gedalias, filho de Aicão filho de Safã e a quem o rei de Babilônia constituiu governador das cidades de Judá, e habita com ele no meio do povo; ou vai para qualquer outra parte que te aprouver ir. E deu-lhe o capitão da guarda sustento para o caminho, e um presente, e o deixou ir.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 6, 'Assim veio Jeremias a Gedalias, filho de Aicão, a Mizpá, e habitou com ele no meio do povo que havia ficado na terra.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 7, 'Ouvindo pois todos os chefes das forças que estavam no campo, eles e os seus homens, que o rei de Babilônia havia constituído a Gedalias, filho de Aicão, governador da terra, e que lhe havia confiado homens, mulheres e crianças, os mais pobres da terra, que não foram levados cativos para Babilônia,', 1, CURRENT_TIMESTAMP, false),
(24, 40, 8, 'vieram ter com Gedalias, a Mizpá; e eram: Ismael, filho de Netanias, e Joanã e Jônatas, filhos de Careá, e Seraías, filho de Tanumete, e os filhos de Efai, o netofatita, e Jezanias, filho do maacatita, eles e os seus homens.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 9, 'E jurou Gedalias, filho de Aicão, filho de Safã, eles e pôs seus homens, dizendo: Não temais servir aos caldeus; habitai na terra, e servi o rei de Babilônia, e bem vos terá.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 10, 'Quanto a mim, eis que habito em Mizpá, para vos representar diante dos caldeus que vierem a nós; vós, porém, colhei o vinho e os frutos de verão, e o azeite, e metei-os nos vossos vasos, e habitai nas vossas cidades, que tomastes.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 11, 'Do mesmo modo, quando todos os judeus que estavam em Moabe, e entre os filhos de Amom, e em Edom, e os que havia em todos os países, ouviram que o rei de Babilônia havia deixado um resto em Judá, e que havia posto sobre eles a Guedalias, o de Aicão, filho de Safã;', 1, CURRENT_TIMESTAMP, false),
(24, 40, 12, 'voltaram, então, todos os judeus de todos os lugares para onde foram arrojados, e vieram para a terra de Judá, a Gedalias, a Mizpá, e colheram vinho e frutos do verão com muita abundância.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 13, 'Joanã, filho de Careá, e todos os chefes das forças que estavam no campo vieram ter com Gedalias, a Mizpá,', 1, CURRENT_TIMESTAMP, false),
(24, 40, 14, 'e disseram-lhe: Sabes que Baalis, rei dos filhos de Amom, enviou a Ismael, filho de Netanias, para te tirar a vida? Mas não lhes deu crédito Gedalias, filho de Aicão.', 1, CURRENT_TIMESTAMP, false),
(24, 40, 15, 'Todavia Joanã, filho de Careá, falou a Gedalias em segredo, em Mizpá, dizendo: Deixa, peço-te, que eu vá e mate a Ismael, filho de Netanias, sem que ninguém o saiba. Por que razão te tiraria ele a vida, de modo que fossem dispersos todos os judeus que se têm congregado a ti, e perecesse o resto de Judá?', 1, CURRENT_TIMESTAMP, false),
(24, 40, 16, 'Mas disse Gedalias, filho de Aicão, a Joanã, filho de Careá: Não faças tal coisa; pois falas falsamente contra Ismael.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 1, 'Sucedeu, porém, no mês sétimo, que veio Ismael, filho de Netanias, filho de Elisama, de sangue real, e um dos nobres do rei, e dez homens com ele, a Gedalias, filho de Aicão, a Mizpá; e eles comeram pão juntos ali em Mizpá.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 2, 'E levantou-se Ismael, filho de Netanias, com os dez homens que estavam com ele, e feriram a Gedalias, filho de Aicão, filho de Safã, à espada, matando assim aquele que o rei de Babilônia havia posto por governador sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 3, 'Matou também Ismael a todos os judeus que estavam com Gedalias, em Mizpá, como também aos soldados caldeus que se achavam ali.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 4, 'Sucedeu pois no dia seguinte, depois que ele matara a Gedalias, sem ninguém o saber,', 1, CURRENT_TIMESTAMP, false),
(24, 41, 5, 'que vieram de Siquém, de Siló e de Samária, oitenta homens, com a barba rapada, e os vestidos rasgados e tendo as carnes retalhadas, trazendo nas mãos ofertas de cereais e incenso, para os levarem à casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 6, 'E, saindo-lhes ao encontro Ismael, filho de Netanias, desde Mizpá, ia chorando; e sucedeu que, encontrando-os, lhes disse: Vinde a Gedalias, filho de Aicão.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 7, 'Chegando eles, porém, até o meio da cidade, Ismael, filho de Netanias, e os homens que estavam com ele mataram-nos e os lançaram num poço.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 8, 'Mas entre eles se acharam dez homens que disseram a Ismael: Não nos mates a nós, porque temos escondidos no campo depósitos de trigo, cevada, azeite e mel. E ele por isso os deixou, e não os matou entre seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 9, 'E o poço em que Ismael lançou todos os cadáveres dos homens que matara por causa de Gedalias é o mesmo que fez o rei Asa, por causa de Baasa, rei de Israel; foi esse mesmo que Ismael, filho de Netanias, encheu de mortos.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 10, 'E Ismael levou cativo a todo o resto do povo que estava em Mizpá: as filhas do rei, e todo o povo que ficara em Mizpá, que Nebuzaradão, capitão da guarda, havia confiado a Gedalias, filho de Aicão; e levou-os cativos Ismael, filho de Netanias, e se foi para passar aos filhos de Amom.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 11, 'Ouvindo, porém, Joanã, filho de Careá, e todos os chefes das forças que estavam com ele, todo o mal que havia feito Ismael, filho de Netanias,', 1, CURRENT_TIMESTAMP, false),
(24, 41, 12, 'tomaram todos os seus homens e foram pelejar contra Ismael, filho de Netanias; e o acharam ao pé das grandes águas que há em Gibeão.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 13, 'E todo o povo que estava com Ismael se alegrou quando viu a Joanã, filho de Careá, e a todos os chefes das forças, que vinham com ele.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 14, 'E todo o povo que Ismael levara cativo de Mizpá virou as costas, e voltou, e foi para Joanã, filho de Careá.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 15, 'Mas Ismael, filho de Netanias, com oito homens, escapou de Joanã e se foi para os filhos de Amom.', 1, CURRENT_TIMESTAMP, false),
(24, 41, 16, 'Então Joanã, filho de Careá, e todos os chefes das forças que estavam com ele, tomaram a todo o resto do povo que Ismael, filho de Netanias, tinha levado cativo de Mizpá, depois que matara Gedalias, filho de Aicão, a saber, aos soldados, as mulheres, aos meninos e aos eunucos, que Joanã havia recobrado de Gibeão,', 1, CURRENT_TIMESTAMP, false),
(24, 41, 17, 'e partiram, indo habitar Gerute-Quimã, que está perto de Belém, para dali entrarem no Egito,', 1, CURRENT_TIMESTAMP, false),
(24, 41, 18, 'por causa dos caldeus; pois os temiam, por ter Ismael, filho de Netanias, matado a Gedalias, filho de Aicão, a quem o rei de Babilônia tinha posto por governador sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 1, 'Então chegaram todos os chefes das forças, e Joanã, filho de Careá, e Jezanias, filho de Hosaías, e todo o povo, desde o menor até o maior,', 1, CURRENT_TIMESTAMP, false),
(24, 42, 2, 'e disseram a Jeremias, o profeta: Seja aceita, pedimos-te, a nossa súplica diante de ti, e roga ao Senhor teu Deus, por nós e por todo este resto; porque de muitos restamos somente uns poucos, assim como nos vêem os teus olhos;', 1, CURRENT_TIMESTAMP, false),
(24, 42, 3, 'para que o Senhor teu Deus nos ensine o caminho por onde havemos de andar e aquilo que havemos de fazer.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 4, 'Respondeu-lhes Jeremias o profeta: Eu vos tenho ouvido; eis que orarei ao Senhor vosso Deus conforme as vossas palavras; e o que o Senhor vos responder, eu vo-lo declararei; não vos ocultarei nada.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 5, 'Então eles disseram a Jeremias: Seja o Senhor entre nós testemunha verdadeira e fiel, se assim não fizermos conforme toda a palavra com que te enviar a nós o Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 6, 'Seja ela boa, ou seja má, à voz do Senhor nosso Deus, a quem te enviamos, obedeceremos, para que nos suceda bem, obedecendo à voz do Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 7, 'Ao fim de dez dias veio a palavra do Senhor a Jeremias.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 8, 'Então chamou a Joanã, filho de Careá, e a todos os chefes das forças que havia com ele, e a todo o povo, desde o menor até o maior,', 1, CURRENT_TIMESTAMP, false),
(24, 42, 9, 'e lhes disse: Assim diz o Senhor, Deus de Israel, a quem me enviastes para apresentar a vossa súplica diante dele:', 1, CURRENT_TIMESTAMP, false),
(24, 42, 10, 'Se de boa mente habitardes nesta terra, então vos edificarei, e não vos derrubarei; e vos plantarei, e não vos arrancarei; porque estou arrependido do mal que vos tenho feito.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 11, 'Não temais o rei de Babilônia, a quem vós temeis; não o temais, diz o Senhor; pois eu sou convosco, para vos salvar e para vos livrar da sua mão.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 12, 'E vos concederei misericórdia, para que ele tenha misericórdia de vós, e vos faça habitar na vossa terra.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 13, 'Mas se vós disserdes: Não habitaremos nesta terra; não obedecendo à voz do Senhor vosso Deus,', 1, CURRENT_TIMESTAMP, false),
(24, 42, 14, 'e dizendo: Não; antes iremos para a terra do Egito, onde não veremos guerra, nem ouviremos o som de trombeta, nem teremos fome de pão, e ali habitaremos;', 1, CURRENT_TIMESTAMP, false),
(24, 42, 15, 'nesse caso ouvi a palavra do Senhor, ó resto de Judá: Assim diz o Senhor dos exércitos, Deus de Israel: Se vós de todo vos propuserdes a entrar no Egito, e entrardes para lá peregrinar,', 1, CURRENT_TIMESTAMP, false),
(24, 42, 16, 'então a espada que vós temeis vos alcançará ali na terra do Egito, e a fome que vós receais vos seguirá de perto mesmo no Egito, e ali morrereis.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 17, 'Assim sucederá a todos os homens que se propuserem a entrar no Egito, a fim de lá peregrinarem: morrerão à espada, de fome, e de peste; e deles não haverá quem reste ou escape do mal que eu trarei sobre eles.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 18, 'Pois assim diz o Senhor dos exércitos, Deus de Israel: Como se derramou a minha ira e a minha indignação sobre os habitantes de Jerusalém, assim se derramará a minha indignação sobre vós, quando entrardes no Egito. Sereis um espetáculo de execração, e de espanto, e de maldição, e de opróbrio; e não vereis mais este lugar.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 19, 'Falou o Senhor acerca de vós, ó resto de Judá: Não entreis no Egito. Tende por certo que hoje vos tenho avisado.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 20, 'Porque vós vos enganastes a vós mesmos; pois me enviastes ao Senhor vosso Deus, dizendo: Roga por nós ao Senhor nosso Deus, e conforme tudo o que disser o Senhor Deus nosso, declara-no-lo assim, e o faremos.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 21, 'E vo-lo tenho declarado hoje, mas não destes ouvidos à voz do Senhor vosso Deus em coisa alguma pela qual ele me enviou a vos.', 1, CURRENT_TIMESTAMP, false),
(24, 42, 22, 'Agora pois sabei por certo que morrereis à espada, de fome e de peste no mesmo lugar onde desejais ir para lá peregrinardes.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 1, 'Tendo Jeremias acabado de falar a todo o povo todas as palavras do Senhor seu Deus, aquelas palavras com as quais o Senhor seu Deus lho havia enviado,', 1, CURRENT_TIMESTAMP, false),
(24, 43, 2, 'então falaram Azarias, filho de Hosaías, e Joanã, filho de Careá, e todos os homens soberbos, dizendo a Jeremias: Tu dizes mentiras; o Senhor nosso Deus não te enviou a dizer: Não entreis no Egito para ali peregrinardes;', 1, CURRENT_TIMESTAMP, false),
(24, 43, 3, 'mas Baruque, filho de Nerias, é que te incita contra nós, para nos entregar na mão dos caldeus, para eles nos matarem, ou para nos levarem cativos para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 4, 'Não obedeceu pois Joanã, filho de Careá, nem nenhum de todos os príncipes dos exércitos, nem o povo todo, à voz do Senhor, para ficarem na terra de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 5, 'Mas Joanã, filho de Careá, e todos os chefes das forças tomaram a todo o resto de Judá, que havia voltado dentre todas as nações, para onde haviam sido arrojados, com o fim de peregrinarem na terra de Judá;', 1, CURRENT_TIMESTAMP, false),
(24, 43, 6, 'aos homens, às mulheres, às crianças, e às filhas do rei, e a toda pessoa que Nebuzaradão, capitão da guarda, deixara com Gedalias, filho de Aicão, filho de Safã, como também a Jeremias, o profeta, e a Baruque, filho de Nerias;', 1, CURRENT_TIMESTAMP, false),
(24, 43, 7, 'e entraram na terra do Egito; pois não obedeceram à voz do Senhor; assim vieram até Tapanes.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 8, 'Então veio a palavra do Senhor a Jeremias, em Tapanes, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 43, 9, 'Toma na tua mão pedras grandes, e esconde-as com barro no pavimento que está à entrada da casa de Faraó em Tapanes, à vista dos homens de Judá;', 1, CURRENT_TIMESTAMP, false),
(24, 43, 10, 'e dize-lhes: Assim diz o Senhor dos exércitos, Deus de Israel: Eis que eu enviarei, e tomarei a Nabucodonosor, rei de Babilônia, meu servo, e porei o seu trono sobre estas pedras que escondi; e ele estenderá o seu pavilhão real sobre elas.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 11, 'Virá, e ferirá a terra do Egito, entregando à morte quem é para a morte, ao cativeiro quem é para o cativeiro, e à espada.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 12, 'E lançarei fogo às casas dos deuses do Egito; e ele os queimará e os levará cativos; e ornar-se-á da terra do Egito, como se veste o pastor com a sua roupa; e sairá dali em paz.', 1, CURRENT_TIMESTAMP, false),
(24, 43, 13, 'E quebrará as colunas de Bete-Semes, que está na terra do Egito; e as casas dos deuses do Egito queimará a fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 1, 'A palavra que veio a Jeremias, acerca de todos os judeus, que habitavam na terra do Egito, em Migdol, em Tapanes, em Mênfis, e no país de Patros:', 1, CURRENT_TIMESTAMP, false),
(24, 44, 2, 'Assim diz o Senhor dos exércitos, Deus de Israel: Vós vistes todo o mal que fiz cair sobre Jerusalém, e sobre todas as cidades de Judá; e eis que elas são hoje uma desolação, e ninguém nelas habita;', 1, CURRENT_TIMESTAMP, false),
(24, 44, 3, 'por causa da sua maldade que fizeram, para me irarem, indo queimar incenso, e servir a outros deuses, a quem eles nunca conheceram, nem eles, nem vós, nem vossos pais.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 4, 'Todavia eu vos enviei persistentemente todos os meus servos, os profetas, para vos dizer: Ora, não façais esta coisa abominável que odeio!', 1, CURRENT_TIMESTAMP, false),
(24, 44, 5, 'Mas eles não escutaram, nem inclinaram os seus ouvidos, para se converterem da sua maldade, para não queimarem incenso a outros deuses.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 6, 'Pelo que se derramou a minha indignação e a minha ira, e acendeu-se nas cidades de Judá, e nas ruas de Jerusalém; e elas tornaram-se em deserto e em desolação, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 7, 'Agora, pois, assim diz o Senhor, Deus dos exércitos, Deus de Israel: Por que fazeis vós tão grande mal contra vós mesmos, para desarraigardes o homem e a mulher, a criança e o que mama, dentre vós, do meio de Judá, a fim de não vos deixardes ali resto algum;', 1, CURRENT_TIMESTAMP, false),
(24, 44, 8, 'irando-me com as obras de vossas mãos, queimando incenso a outros deuses na terra do Egito, aonde vós entrastes para lá peregrinardes, para que sejais exterminados, e para que sirvais de maldição e de opróbrio entre todas as nações da terra?', 1, CURRENT_TIMESTAMP, false),
(24, 44, 9, 'Esquecestes já as maldades de vossos pais, as maldades dos reis de Judá, as maldades das suas mulheres, as vossas maldades e as maldades das vossas mulheres, cometidas na terra de Judá e nas ruas de Jerusalém?', 1, CURRENT_TIMESTAMP, false),
(24, 44, 10, 'Não se humilharam até o dia de hoje, nem temeram, nem andaram na minha lei, nem nos meus estatutos, que pus diante de vós e diante de vossos pais.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 11, 'Portanto assim diz o Senhor dos exércitos, Deus de Israel: Eis que eu ponho o meu rosto contra vós para mal, e para desarraigar todo o Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 12, 'E tomarei os que restam de Judá, os quais puseram o seu rosto para entrar na terra do Egito, a fim de lá peregrinarem, e todos eles serão consumidos; na terra do Egito cairão; à espada, e de fome serão consumidos; desde o menor até o maior morrerão à espada e de fome; e tornar-se-ão um espetáculo de execração, de espanto, de maldição e de opróbrio.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 13, 'Pois castigarei os que habitam na terra do Egito, como castiguei Jerusalém, com a espada, a fome e a peste.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 14, 'De maneira que, da parte remanescente de Judá que entrou na terra do Egito a fim de lá peregrinar, não haverá quem escape e fique para tornar à terra de Judá, à qual era seu grande desejo voltar, para ali habitar; mas não voltarão, senão um pugilo de fugitivos.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 15, 'Então responderam a Jeremias todos os homens que sabiam que suas mulheres queimavam incenso a outros deuses, e todas as mulheres que estavam presentes, uma grande multidão, a saber, todo o povo que habitava na terra do Egito, em Patros, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 44, 16, 'Quanto à palavra que nos anunciaste em nome do Senhor, não te obedeceremos a ti;', 1, CURRENT_TIMESTAMP, false),
(24, 44, 17, 'mas certamente cumpriremos toda a palavra que saiu da nossa boca, de queimarmos incenso à rainha do céu, e de lhe oferecermos libações, como nós e nossos pais, nossos reis e nossos príncipes, temos feito, nas cidades de Judá, e nas ruas de Jerusalém; então tínhamos fartura de pão, e prosperávamos, e não vimos mal algum.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 18, 'Mas desde que cessamos de queimar incenso à rainha do céu, e de lhe oferecer libações, temos tido falta de tudo, e temos sido consumidos pela espada e pela fome.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 19, 'E nós, as mulheres, quando queimávamos incenso à rainha do céu, e lhe oferecíamos libações, acaso lhe fizemos bolos para a adorar e lhe oferecemos libações sem nossos maridos?', 1, CURRENT_TIMESTAMP, false),
(24, 44, 20, 'Então disse Jeremias a todo o povo, aos homens e às mulheres, e a todo o povo que lhe havia dado essa resposta, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 44, 21, 'Porventura não se lembrou o Senhor, e não lhe veio à mente o incenso que queimastes nas cidades de Judá e nas ruas de Jerusalém, vós e vossos pais, vossos reis e vossos príncipes, como também o povo da terra?', 1, CURRENT_TIMESTAMP, false),
(24, 44, 22, 'O Senhor não podia por mais tempo suportar a maldade das vossas ações, as abominações que cometestes; pelo que se tornou a vossa terra em desolação, e em espanto, e em maldição, sem habitantes, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 23, 'Porquanto queimastes incenso, e pecastes contra o Senhor, não obedecendo à voz do Senhor, nem andando na sua lei, nos seus estatutos e nos seus testemunhos; por isso vos sobreveio este mal, como se vê neste dia.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 24, 'Disse mais Jeremias a todo o povo e a todas as mulheres: Ouvi a palavra do Senhor, vós, todo o Judá, que estais na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 25, 'Assim fala o Senhor dos exércitos, Deus de Israel, dizendo: Vós e vossas mulheres falastes por vossa boca, e com as vossas mãos o cumpristes, dizendo: Certamente cumpriremos os nossos votos que fizemos, de queimarmos incenso à rainha do céu e de lhe derramarmos libações; confirmai, pois, os vossos votos, e cumpri-os!', 1, CURRENT_TIMESTAMP, false),
(24, 44, 26, 'Ouvi, pois, a palavra do Senhor, todos os de Judá que habitais na terra do Egito: Eis que eu juro pelo meu grande nome, diz o Senhor, que nunca mais será pronunciado o meu nome pela boca de nenhum homem de Judá em toda a terra do Egito, dizendo: Como vive o Senhor Deus!', 1, CURRENT_TIMESTAMP, false),
(24, 44, 27, 'Eis que velarei sobre eles para o mal, e não para o bem; e serão consumidos todos os homens de Judá que estão na terra do Egito, pela espada e pela fome, até que de todo se acabem.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 28, 'E os que escaparem da espada voltarão da terra do Egito para a terra de Judá, poucos em número; e saberá todo o resto de Judá que entrou na terra do Egito para peregrinar ali, se subsistirá a minha palavra ou a sua.', 1, CURRENT_TIMESTAMP, false),
(24, 44, 29, 'E isto vos servirá de sinal, diz o Senhor, de que eu vos castigarei neste lugar, para que saibais que certamente subsistirão as minhas palavras contra vós para o mal:', 1, CURRENT_TIMESTAMP, false),
(24, 44, 30, 'Assim diz o Senhor: Eis que eu entregarei Faraó-Hofra, rei do Egito, na mão de seus inimigos, e na mão dos que procuram a sua morte; como entreguei Zedequias, rei de Judá, na mão de Nabucodonosor, rei de Babilônia, seu inimigo, e que procurava a sua morte.', 1, CURRENT_TIMESTAMP, false),
(24, 45, 1, 'A palavra que Jeremias, o profeta, falou a Banique, filho de Nerias, quando este escrevia num livro as palavras ditadas por Jeremias, no quarto ano de Jeoiaquim, filho de Josias, rei de Judá:', 1, CURRENT_TIMESTAMP, false),
(24, 45, 2, 'Assim diz o Senhor, Deus de Israel, acerca de ti ó Baruque.', 1, CURRENT_TIMESTAMP, false),
(24, 45, 3, 'Disseste: Ai de mim agora! porque me acrescentou o Senhor tristeza à minha dor; estou cansado do meu gemer, e não acho descanso.', 1, CURRENT_TIMESTAMP, false),
(24, 45, 4, 'Isto lhe dirás: Assim diz o Senhor: Eis que estou a demolir o que edifiquei, e a arrancar o que plantei, e isso em toda esta terra.', 1, CURRENT_TIMESTAMP, false),
(24, 45, 5, 'E procuras tu grandezas para ti mesmo? Não as busques; pois eis que estou trazendo o mal sobre toda a raça, diz o Senhor; porém te darei a tua vida por despojo, em todos os lugares para onde fores.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 1, 'A palavra do Senhor, que veio a Jeremias, o profeta, acerca das nações.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 2, 'Acerca do Egito: a respeito do exército de Faraó-Neco, rei do Egito, que estava junto ao rio Eufrates em Carquêmis, ao qual Nabucodonosor, rei de Babilônia, derrotou no quarto ano de Jeoiaquim, filho de Josias, rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 3, 'Preparai o escudo e o pavês, e chegai-vos para a peleja.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 4, 'Aparelhai os cavalos, e montai, cavaleiros! Apresentai-vos com elmos; açacalai as lanças; vesti-vos de couraças.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 5, 'Por que razão os vejo espantados e voltando as costas? Os seus heróis estão abatidos, e vão fugindo, sem olharem para trás; terror há por todos os lados, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 6, 'Não pode fugir o ligeiro, nem escapar o herói; para a banda do norte, junto ao rio Eufrates, tropeçaram e caíram.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 7, 'Quem é este que vem subindo como o Nilo, como rios cujas águas se agitam?', 1, CURRENT_TIMESTAMP, false),
(24, 46, 8, 'O Egito é que vem subindo como o Nilo, e como rios cujas águas se agitam; e ele diz: Subirei, cobrirei a terra; destruirei a cidade e os que nela habitam.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 9, 'Subi, ó cavalos; e estrondeai, ó carros; e saiam valentes: Cuche e Pute, que manejam o escudo, e os de Lude, que manejam e entesam o arco.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 10, 'Porque aquele dia é o dia do Senhor Deus dos exércitos, dia de vingança para ele se vingar dos seus adversários. A espada devorará, e se fartará, e se embriagará com o sangue deles; pois o Senhor Deus dos exércitos tem um sacrifício na terra do Norte junto ao rio Eufrates.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 11, 'Sobe a Gileade, e toma bálsamo, ó virgem filha do Egito; debalde multiplicas remédios; não há cura para ti.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 12, 'As nações ouviram falar da tua vergonha, e a terra está cheia do teu clamor; porque o valente tropeçou no valente e ambos juntos cairam.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 13, 'A palavra que falou o Senhor a Jeremias, o profeta, acerca da vinda de Nabucodonosor, rei de Babilônia, para ferir a terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 14, 'Anunciai-o no Egito, proclamai isto em Migdol; proclamai-o também em Mênfis, e em Tapanes; dizei: Apresenta-te, e prepara-te; porque a espada devorará o que está ao redor de ti.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 15, 'Por que está derribado o teu valente? Ele não ficou em pé, porque o Senhor o abateu.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 16, 'Fez tropeçar a multidão; caíram uns sobre os outros, e disseram: Levanta-te, e voltemos para o nosso povo, para a terra do nosso nascimento, por causa da espada que oprime.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 17, 'Clamaram ali: Faraó, rei do Egito, é apenas um som; deixou passar o tempo assinalado.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 18, 'Vivo eu, diz o Rei, cujo nome é o Senhor dos exércitos, que certamente como o Tabor entre os montes, e como o Carmelo junto ao mar, assim ele vira.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 19, 'Prepara-te para ires para o cativeiro, ó moradora filha do Egito; porque Mênfis será tornada em desolação, e será incendiada, até que ninguém mais aí more.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 20, 'Novilha mui formosa é o Egito; mas já lhe vem do Norte um tavão.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 21, 'Até os seus mercenários no meio dela são como bezerros cevados; mas também eles viraram as costas, fugiram juntos, não ficaram firmes; porque veio sobre eles o dia da sua ruína e o tempo da sua punição.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 22, 'A sua voz irá como a da serpente; porque marcharão com um exército, e virão contra ela com machados, como cortadores de lenha.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 23, 'Cortarão o seu bosque, diz o Senhor, embora seja impenetrável; porque se multiplicaram mais do que os gafanhotos; são inumeráveis.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 24, 'A filha do Egito será envergonhada; será entregue na mão do povo do Norte.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 25, 'Diz o Senhor dos exércitos, o Deus de Israel: Eis que eu castigarei a Amom de Tebas, e a Faraó, e ao Egito, juntamente com os seus deuses e os seus reis, sim, ao próprio Faraó, e aos que nele confiam.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 26, 'E os entregarei na mão dos que procuram a sua morte, na mão de Nabucodonosor, rei de Babilônia, e na mão dos seus servos; mas depois será habitada, como nos dias antigos, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 27, 'Mas não temas tu, servo meu, Jacó, nem te espantes, ó Israel; pois eis que te livrarei mesmo de longe, e a tua descendência da terra do seu cativeiro; e Jacó voltará, e ficará tranqüilo e sossegado, e não haverá quem o atemorize.', 1, CURRENT_TIMESTAMP, false),
(24, 46, 28, 'Tu não temas, servo meu, Jacó, diz o senhor; porque estou contigo; pois destruirei totalmente todas as nações para onde te arrojei; mas a ti não te destruirei de todo, mas castigar-te-ei com justiça, e de modo algum te deixarei impune.', 1, CURRENT_TIMESTAMP, false),
(24, 47, 1, 'A palavra do Senhor que veio a Jeremias, o profeta, acerca dos filisteus, antes que Faraó ferisse a Gaza.', 1, CURRENT_TIMESTAMP, false),
(24, 47, 2, 'Assim diz o Senhor: Eis que do Norte se levantam as águas, e tornar-se-ão em torrente trasbordante, e alagarão a terra e quanto há nela, a cidade e os que nela habitam; os homens clamarão, e todos os habitantes da terra uivarão,', 1, CURRENT_TIMESTAMP, false),
(24, 47, 3, 'ao ruído estrepitoso das unhas dos seus fortes cavalos, ao barulho de seus carros, ao estrondo das suas rodas; os pais não atendem aos filhos, por causa da fraqueza das mãos,', 1, CURRENT_TIMESTAMP, false),
(24, 47, 4, 'por causa do dia que vem para destruir a todos os filisteus, para cortar de Tiro e de Sidom todo o resto que os socorra; pois o Senhor destruirá os filisteus, o resto da ilha de Caftor.', 1, CURRENT_TIMESTAMP, false),
(24, 47, 5, 'A calvície é vinda sobre Gaza; foi desarraigada Asquelom, bem como o resto do seu vale; até quando te sarjarás?', 1, CURRENT_TIMESTAMP, false),
(24, 47, 6, 'Ah espada do Senhor! até quando deixarás de repousar? volta para a tua bainha; descansa, e aquieta-te.', 1, CURRENT_TIMESTAMP, false),
(24, 47, 7, 'Como podes estar quieta, se o Senhor te deu uma ordem? Contra Asquelom, e contra o litoral, é que ele a enviou.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 1, 'Acerca de Moabe. Assim diz o Senhor dos exércitos, Deus de Israel: Ai de Nebo, porque foi destruída; envergonhada está Quiriataim, já é tomada; Misgabe está envergonhada e espantada.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 2, 'O louvor de Moabe já não existe mais; em Hesbom projetaram mal contra ela, dizendo: Vinde, e exterminemo-la, para que não mais seja nação; também tu, ó Madmém, serás destruída; a espada te perseguirá.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 3, 'Voz de grito de Horonaim, ruína e grande destruição!', 1, CURRENT_TIMESTAMP, false),
(24, 48, 4, 'Está destruído Moabe; seus filhinhos fizeram ouvir um clamor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 5, 'Pois pela subida de Luíte eles vão subindo com choro contínuo; porque na descida de Horonaim, ouviram a angústia do grito da destruição.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 6, 'Fugi, salvai a vossa vida! Sede como o asno selvagem no deserto.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 7, 'Pois, porquanto confiaste nas tuas obras e nos teus tesouros, também tu serás tomada; e Quemós sairá para o cativeiro, os seus sacerdotes e os seus príncipes juntamente.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 8, 'Porque virá o destruidor sobre cada uma das cidades e nenhuma escapará, e perecerá o vale, e destruir-se-á a planície, como disse o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 9, 'Dai asas a Moabe, porque voando sairá; e as suas cidades se tornarão em desolação, sem habitante.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 10, 'Maldito aquele que fizer a obra do Senhor negligentemente, e maldito aquele que vedar do sangue a sua espada!', 1, CURRENT_TIMESTAMP, false),
(24, 48, 11, 'Moabe tem estado sossegado desde a sua mocidade, e tem repousado como vinho sobre as fezes; não foi deitado de vasilha em vasilha, nem foi para o cativeiro; por isso permanece nele o seu sabor, e o seu cheiro não se altera.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 12, 'Portanto, eis que os dias vêm, diz o Senhor, em que lhe enviarei derramadores que o derramarão; e despejarão as suas vasilhas, e despedaçarão os seus jarros.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 13, 'E Moabe terá vergonha de Quemós, como se envergonhou a casa de Israel de Betel, sua confiança.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 14, 'Como direis: Somos valentes e homens fortes para a guerra?', 1, CURRENT_TIMESTAMP, false),
(24, 48, 15, 'Já subiu o destruidor de Moabe e das suas cidades, e os seus mancebos escolhidos desceram à matança, diz o Rei, cujo nome é o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 16, 'A calamidade de Moabe está perto e muito se apressa o seu mal.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 17, 'Condoei-vos dele todos os que estais em seu redor, e todos os que sabeis o seu nome; dizei: Como se quebrou a vara forte, o cajado formoso!', 1, CURRENT_TIMESTAMP, false),
(24, 48, 18, 'Desce da tua glória, e senta-te no pó, ó moradora, filha de Dibom; porque o destruidor de Moabe subiu contra ti, e desfez as tuas fortalezas.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 19, 'Põe-te junto ao caminho, e espia, ó moradora do Aroer; pergunta ao que foge, e à que escapa: Que sucedeu?', 1, CURRENT_TIMESTAMP, false),
(24, 48, 20, 'Moabe está envergonhado, porque foi quebrantado; uivai e gritai; anunciai em Arnom que Moabe está destruído.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 21, 'Também o julgamento é vindo sobre a terra da planície; sobre Holom, Jaza, e Mefaate;', 1, CURRENT_TIMESTAMP, false),
(24, 48, 22, 'sobre Dibom, Nebo, e Bete-Diblataim;', 1, CURRENT_TIMESTAMP, false),
(24, 48, 23, 'sobre Quiriataim, Bete-Gamul, e BeteMeom;', 1, CURRENT_TIMESTAMP, false),
(24, 48, 24, 'sobre Queriote, e Bozra, e todas as cidades da terra de Moabe, as de longe e as de perto.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 25, 'Está cortado o poder de Moabe, e quebrantado o seu braço, diz o senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 26, 'Embriagai-o, porque contra o Senhor se engrandeceu; e Moabe se revolverá no seu vômito, e ele também se tornará objeto de escárnio.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 27, 'Pois não se tornou também Israel objeto de escárnio para ti? Porventura foi achado entre ladrões para que, sempre que falas dele, meneies a cabeça?', 1, CURRENT_TIMESTAMP, false),
(24, 48, 28, 'Deixai as cidades, e habitai no rochedo, ó moradores de Moabe; e sede como a pomba que se aninha nos lados da boca da caverna.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 29, 'Temos ouvido da soberba de Moabe, que é soberbíssimo; da sua sobrançaria, do seu orgulho, da sua arrogância, e da altivez do seu coração.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 30, 'Eu conheço, diz o Senhor, a sua insolência, mas isso nada é; as suas jactâncias nada têm efetuado.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 31, 'Por isso uivarei por Moabe; sim, gritarei por todo o Moabe; pelos homens de Quir-Heres lamentarei.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 32, 'Com choro maior do que o de Jazer chorar-te-ei, ó vide de Sibma; os teus ramos passaram o mar, chegaram até o mar de Jazer; mas o destruidor caiu sobre os teus frutos de verão, e sobre a tua vindima.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 33, 'Tirou-se, pois, a alegria e o regozijo do campo fértil e da terra de Moabe; e fiz que o vinho cessasse dos lagares; já não pisam uvas com júbilo; o brado não é o de júbilo', 1, CURRENT_TIMESTAMP, false),
(24, 48, 34, 'O grito de Hesbom e Eleale se ouve até Jaza; fazem ouvir a sua voz desde Zoar até Horonaim, e até Eglate-Selíssia; pois também as águas do Ninrim virão a ser uma desolação.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 35, 'Demais, farei desaparecer de Moabe, diz o Senhor, aquele que sacrifica nos altos, e queima incenso a seus deuses.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 36, 'Por isso geme como flauta o meu coração por Moabe, e como flauta geme o meu coração pelos homens de Quir-Heres; porquanto a abundância que ajuntou se perdeu.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 37, 'Pois toda cabeça é tosquiada, e toda barba rapada; sobre todas as mãos há sarjaduras, e sobre os lombos sacos.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 38, 'Sobre todos os eirados de Moabe e nas suas ruas há um pranto geral; porque quebrei a Moabe, como a um vaso que não agrada, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 39, 'Como está quebrantrado! como uivam! como virou Moabe as costas envergonhado! assim se tornou Moabe objeto de escárnio e de espanto para todos os que estão em redor dele.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 40, 'Pois assim diz o Senhor: Eis que alguém voará como a águia, e estenderá as suas asas contra Moabe.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 41, 'Tomadas serão as cidades, e ocupadas as fortalezas; e naquele dia será o coração dos valentes de Moabe como o coração da mulher em suas dores de parto.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 42, 'E Moabe será destruído, para que não seja povo, porque se engrandeceu contra o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 43, 'Temor, e cova, e laço estão sobre ti, ó morador de Moabe, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 44, 'O que fugir do temor cairá na cova, e o que sair da cova ficará preso no laço; pois trarei sobre ele, sobre Moabe, o ano do seu castigo, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 45, 'Os que fugiram ficam parados sem forças à sombra de Hesbom; mas fogo saiu de Hesbom, e a labareda do meio de Siom, e devorou a fronte de Moabe e o alto da cabeça dos turbulentos.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 46, 'Ai de ti, Moabe! pereceu o povo de Quemós; pois teus filhos foram levados cativos, e tuas filhas para o cativeiro.', 1, CURRENT_TIMESTAMP, false),
(24, 48, 47, 'Contudo nos últimos dias restaurarei do cativeiro a Moabe, diz o Senhor. Até aqui o juizo de Moabe.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 1, 'A respeito dos filhos de Amom. Assim diz o Senhor: Acaso Israel não tem filhos? Não tem herdeiro? Por que, então, possui Milcom a Gade, e o seu povo habita nas suas cidades?', 1, CURRENT_TIMESTAMP, false),
(24, 49, 2, 'Portanto, eis que vêm os dias, diz o Senhor, em que farei ouvir contra Rabá dos filhos de Amom o alarido de guerra, e tornar-se-á num montão de ruínas, e os seus arrabaldes serão queimados a fogo; então Israel deserdará aos que e deserdaram a ele, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 3, 'Uiva, ó Hesbom, porque é destruída Ai; clamai, ó filhas de Rabá, cingi-vos de sacos; lamentai, e dai voltas pelas sebes; porque Milcom irá em cativeiro, juntamente com os seus sacerdotes e os seus príncipes.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 4, 'Por que te glorias nos vales, teus luxuriantes vales, ó filha apóstata? que confias nos teus tesouros, dizendo: Quem virá contra mim?', 1, CURRENT_TIMESTAMP, false),
(24, 49, 5, 'Eis que farei vir sobre ti pavor, diz o Senhor Deus dos exércitos, de todos os que estão ao redor de ti; e sereis lançados fora, cada um para diante, e ninguém recolherá o desgarrado.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 6, 'Mas depois disto farei voltar do cativeiro os filhos de Amom, diz o senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 7, 'A respeito de Edom. Assim diz o Senhor dos exércitos: Acaso não há mais sabedoria em Temã? Pereceu o conselho dos entendidos? Desvaneceu-se-lhes a sabedoria?', 1, CURRENT_TIMESTAMP, false),
(24, 49, 8, 'Fugi, voltai, habitai em profundezas, ó moradores de Dedã; porque trarei sobre ele a calamidade de Esaú, o tempo em que o punirei.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 9, 'Se vindimadores viessem a ti, não deixariam alguns rabiscos? se ladrões de noite, não te danificariam só o quanto lhes bastasse?', 1, CURRENT_TIMESTAMP, false),
(24, 49, 10, 'Mas eu desnudei a Esaú, descobri os seus esconderijos, de modo que ele não se poderá esconder. E despojada a sua descendência, como também seus irmãos e seus vizinhos, e ele já não existe.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 11, 'Deixa os teus órfãos, eu os guardarei em vida; e as tuas viúvas confiem em mim.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 12, 'Pois assim diz o Senhor: Eis que os que não estavam condenados a beber o copo, certamente o beberão; e ficarias tu inteiramente impune? Não ficarás impune, mas certamente o beberás.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 13, 'Pois por mim mesmo jurei, diz o Senhor, que Bozra servirá de objeto de espanto, de opróbrio, de ruína, e de maldição; e todas as suas cidades se tornarão em desolações perpétuas.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 14, 'Eu ouvi novas da parte do Senhor, que um embaixador é enviado por entre as nações para lhes dizer: Ajuntai-vos, e vinde contra ela, e levantai-vos para a guerra.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 15, 'Pois eis que te farei pequeno entre as nações, desprezado entre os homens.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 16, 'Quanto à tua terribilidade, enganou-te a arrogância do teu coração, ó tu que habitas nas cavernas dos penhascos, que ocupas as alturas dos outeiros; ainda que ponhas o teu ninho no alto como a águia, de lá te derrubarei, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 17, 'E Edom se tornará em objeto de espanto; todo aquele que passar por ela se espantará, e assobiará por causa de todas as suas pragas.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 18, 'Como na subversão de Sodoma e Gomorra, e das cidades circunvizinhas, diz o Senhor, não habitará ninguém ali, nem peregrinará nela filho de homem.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 19, 'Eis que como leão subirá das margens do Jordão um inimigo contra a morada forte; mas de repente o farei correr dali; e ao escolhido, pô-lo-ei sobre ela. Pois quem é semelhante a mim? e quem me fixará um prazo? e quem é o pastor que me poderá resistir?', 1, CURRENT_TIMESTAMP, false),
(24, 49, 20, 'Portanto ouvi o conselho do Senhor, que ele decretou contra Edom, e os seus desígnios, que ele intentou contra os moradores de Temã: Até os mais novos do rebanho serão arrastados; certamente ele assolará as suas moradas sobre eles.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 21, 'A terra estremecerá com o estrondo da sua queda; o som do seu clamor se ouvirá até o Mar Vermelho.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 22, 'Eis que como águia subirá, e voará, e estenderá as suas asas contra Bozra; e o coração do valente de Edom naquele dia se tornará como o coração da mulher que está em dores de parto.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 23, 'A respeito de Damasco. Envergonhadas estão Hamate e Arpade, e se derretem de medo porquanto ouviram más notícias; estão agitadas como o mar, que não pode aquietar-se.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 24, 'Enfraquecida está Damasco, virou as costas para fugir, e o tremor apoderou-se dela; angústia e dores apossaram-se dela como da mulher que está de parto.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 25, 'Como está abandonada a cidade famosa, a cidade da minha alegria!', 1, CURRENT_TIMESTAMP, false),
(24, 49, 26, 'Portanto os seus jovens lhe cairão nas ruas, e todos os homens de guerra serão consumidos naquele dia, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 27, 'E acenderei fogo no muro de Damasco, o qual consumirá os palácios de Ben-Hadade.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 28, 'A respeito de Quedar, e dos reinos de Hazor, que Nabucodonosor, rei de Babilônia, feriu. Assim diz o Senhor: Levantai-vos, subi contra Quedar, e destruí os filhos do Oriente.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 29, 'As suas tendas e os seus rebanhos serão tomados; as suas cortinas serão levadas, como também todos os seus vasos, e os seus camelos; e lhes gritarão: Há terror de todos os lados!', 1, CURRENT_TIMESTAMP, false),
(24, 49, 30, 'Fugi, desviai-vos para muito longe, habitai nas profundezas, ó moradores de Hazor, diz o Senhor; porque Nabucodonosor, rei de Babilônia, tomou conselho contra vós, e formou um desígnio contra vós.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 31, 'Levantai-vos, subi contra uma nação que está sossegada, que habita descuidada, diz o Senhor; que não tem portas nem ferrolhos, que habita a sós.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 32, 'E os seus camelos serão para presa e a multidão do seu gado para despojo; e espalharei a todo o vento aqueles que cortam os cantos da sua cabeleira; e de todos os lados lhes trarei a sua calamidade, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 33, 'Assim Hazor se tornará em morada de chacais, em desolação para sempre; ninguém habitará ali, nem peregrinará nela filho de homem.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 34, 'A palavra do Senhor, que veio a Jeremias, o profeta, acerca de Elão, no princípio do reinado de Zedequias, rei de Judá, dizendo:', 1, CURRENT_TIMESTAMP, false),
(24, 49, 35, 'Assim diz o Senhor dos exércitos: Eis que eu quebrarei o arco de Elão, o principal do seu poder.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 36, 'E trarei sobre Elão os quatro ventos dos quatro cantos dos céus, e os espalharei para todos estes ventos; e não haverá nação aonde não cheguem os fugitivos de Elão.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 37, 'E farei que Elão desfaleça diante de seus inimigos e diante dos que procuram a sua morte. Farei vir sobre eles o mal, o furor da minha ira, diz o Senhor; e enviarei após eles a espada, até que eu os tenha consumido.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 38, 'E porei o meu trono em Elão, e destruirei dali rei e príncipes, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 49, 39, 'Acontecerá, porém, nos últimos dias, que restaurarei do cativeiro a Elão, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 1, 'A palavra que falou o Senhor acerca de Babilônia, acerca da terra dos caldeus, por intermédio de Jeremias o profeta.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 2, 'Anunciai entre as nações e publicai, arvorando um estandarte; sim publicai, não encubrais; dizei: Tomada está Babilônia, confundido está Bel, caído está Merodaque, confundidos estão os seus ídolos, e caídos estão os seus deuses.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 3, 'Pois do Norte sobe contra ela uma nação que fará da sua terra uma desolação, e não haverá quem nela habite; tanto os homens como os animais já fugiram e se foram.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 4, 'Naqueles dias, e naquele tempo, diz o Senhor, os filhos de Israel virão, eles e os filhos de Judá juntamente; andando e chorando virão, e buscarão ao Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 5, 'Acerca de Sião indagarão, tendo os seus rostos voltados para lá e dizendo: Vinde e uni-vos ao Senhor num pacto eterno que nunca será esquecido.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 6, 'Ovelhas perdidas têm sido o meu povo; os seus pastores as fizeram errar, e voltar aos montes; de monte para outeiro andaram, esqueceram-se do lugar de seu repouso.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 7, 'Todos os que as achavam as devoraram, e os seus adversários diziam: Culpa nenhuma teremos; porque pecaram contra o Senhor, a morada da justiça, sim, o Senhor, a esperança de seus pais.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 8, 'Fugi do meio de Babilônia, e saí da terra dos caldeus, e sede como os bodes diante do rebanho.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 9, 'Pois eis que eu suscitarei e farei subir contra Babilônia uma companhia de grandes nações da terra do Norte; e por-se-ão em ordem contra ela; dali será ela tomada. As suas flechas serão como as de valente herói; nenhuma tornará sem efeito.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 10, 'E Caldéia servirá de presa; todos os que a saquearem ficarão fartos, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 11, 'Embora vos alegreis e vos regozijeis, ó saqueadores da minha herança, embora andeis soltos como novilha que pisa a erva, e rincheis como cavalos vigorosos,', 1, CURRENT_TIMESTAMP, false),
(24, 50, 12, 'muito envergonhada será vossa mãe, ficará humilhada a que vos deu à luz; eis que ela será a última das nações, um deserto, uma terra seca e uma solidão.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 13, 'Por causa da ira do Senhor não será habitada, antes se tornará em total desolação; qualquer que passar por Babilônia se espantará, e assobiará por causa de todas as suas pragas.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 14, 'Ponde-vos em ordem para cercar Babilônia, todos os que armais arcos; atirai-lhe, não poupeis as flechas, porque ela tem pecado contra o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 15, 'Gritai contra ela rodeando-a; ela já se submeteu; caíram seus baluartes, estão derribados os seus muros. Pois esta é a vingança do Senhor; vingai-vos dela; conforme o que ela fez, assim lhe fazei a ela.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 16, 'Cortai de Babilônia o que semeia, e o que maneja a foice no tempo da sega; por causa da espada do opressor virar-se-á cada um para o seu povo, e fugirá cada qual para a sua terra.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 17, 'Cordeiro desgarrado é Israel, os leões o afugentaram; o primeiro a devorá-lo foi o rei da Assíria, e agora por último Nabucodonosor, rei de Babilônia, lhe quebrou os ossos.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 18, 'Portanto, assim diz o Senhor dos exércitos, Deus de Israel: Eis que castigarei o rei de Babilônia e a sua terra, como castiguei o rei da Assíria.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 19, 'E farei voltar Israel para a sua morada, e ele pastará no Carmelo e em Basã, e se fartará nos outeiros de Efraim e em Gileade.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 20, 'Naqueles dias, e naquele tempo, diz o Senhor, buscar-se-á a iniqüidade em Israel, e não haverá; e o pecado em Judá, e não se achará; pois perdoarei aos que eu deixar de resto.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 21, 'Sobe contra a terra de Merataim, sim, contra ela, e contra os moradores de Pecode; mata e inteiramente destrói tudo após eles, diz o Senhor, e faze conforme tudo o que te ordenei.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 22, 'Na terra há estrondo de batalha, e de grande destruição.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 23, 'Como foi cortado e quebrado o martelo de toda a terra! como se tornou Babilônia em objeto de espanto entre as nações!', 1, CURRENT_TIMESTAMP, false),
(24, 50, 24, 'Laços te armei, e também foste presa, ó Babilônia, e tu não o soubeste; foste achada, e também apanhada, porque contra o Senhor te entremeteste.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 25, 'O Senhor abriu o seu arsenal, e tirou os instrumentos da sua indignação; porque o senhor Deus dos exércitos tem uma obra a realizar na terra dos caldeus.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 26, 'Vinde contra ela dos confins da terra, abri os seus celeiros; fazei dela montões, e destruí-a de todo; nada lhe fique de resto.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 27, 'Matai a todos os seus novilhos, desçam ao degoladouro; ai deles! porque é chegado o seu dia, o tempo da sua punição.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 28, 'Eis a voz dos que fogem e escapam da terra de Babilônia para anunciarem em Sião a vingança do Senhor nosso Deus, a vingança do seu templo.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 29, 'Convocai contra Babilônia os flecheiros, todos os que armam arcos; acampai-vos contra ela em redor, ninguém escape dela. Pagai-lhe conforme a sua obra; conforme tudo o que ela fez, assim lhe fazei a ela; porque se houve arrogantemente contra o Senhor, contra o Santo de Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 30, 'Portanto cairão os seus jovens nas suas praças, e todos os seus homens de guerra serão destruídos naquele dia, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 31, 'Eis que eu sou contra ti, ó soberbo, diz o Senhor Deus dos exércitos; pois o teu dia é chegado, o tempo em que te hei de punir?', 1, CURRENT_TIMESTAMP, false),
(24, 50, 32, 'Então tropeçará o soberbo, e cairá, e ninguém haverá que o levante; e porei fogo às suas cidades, o qual consumirá tudo o que está ao seu redor.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 33, 'Assim diz o Senhor dos exércitos: Os filhos de Israel e os filhos de Judá são juntamente oprimidos; e todos os que os levaram cativos os retêm, recusam soltá-los.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 34, 'Mas o seu Redentor é forte; o Senhor dos exércitos é o seu nome. Certamente defenderá em juízo a causa deles, para dar descanso à terra, e inquietar os moradores de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 35, 'A espada virá sobre os caldeus, diz o senhor, e sobre os moradores de Babilônia, e sobre os seus príncipes, e sobre os seus sábios.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 36, 'A espada virá sobre os paroleiros, e eles ficarão insensatos; a espada virá sobre os seus valentes, e eles desfalecerão.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 37, 'A espada virá sobre os seus cavalos, e sobre os seus carros, e sobre todo o povo misto, que se acha no meio dela, e eles se tornarão como mulheres; a espada virá sobre os seus tesouros, e estes serão saqueados.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 38, 'Cairá a seca sobre as suas águas, e elas secarão; pois é uma terra de imagens esculpidas, e eles pelos seus ídolos fazem-se loucos.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 39, 'Por isso feras do deserto juntamente com lobos habitarão ali; também habitarão nela avestruzes; e nunca mais será povoada, nem será habitada de geração em geração.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 40, 'Como quando Deus subverteu a Sodoma e a Gomorra, e às suas cidades vizinhas, diz o Senhor, assim ninguém habitará ali, nem peregrinará nela filho de homem.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 41, 'Eis que um povo vem do norte; e uma grande nação e muitos reis se levantam das extremidades da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 42, 'Armam-se de arco e lança; são cruéis, e não têm piedade; a sua voz brama como o mar, e em cavalos vêm montados, dispostos como homens para a batalha, contra ti, ó filha de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 43, 'O rei de Babilônia ouviu a fama deles, e desfaleceram as suas mãos; a angústia se apoderou dele, dores, como da que está de parto.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 44, 'Eis que como leão subirá das margens do Jordão um inimigo contra a morada forte, mas de repente o farei correr dali; e ao escolhido, pô-lo-ei sobre ela. Pois quem é semelhante a mim? e quem me fixará um prazo? Quem é o pastor que me poderá resistir?', 1, CURRENT_TIMESTAMP, false),
(24, 50, 45, 'Portanto ouvi o conselho que o Senhor decretou contra Babilônia, e o propósito que formou contra a terra dos caldeus: Certamente eles, os pequenos do rebanho, serão arrastados; certamente o aprisco ficará apavorado por causa deles.', 1, CURRENT_TIMESTAMP, false),
(24, 50, 46, 'Ao estrondo da tomada de Babilônia estremece a terra; e o grito se ouve entre as nações.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 1, 'Assim diz o Senhor: Eis que levantarei um vento destruidor contra Babilônia, e contra os que habitam na Caldéia.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 2, 'E enviarei padejadores contra Babilônia, que a padejarão, e esvaziarão a sua terra, quando vierem contra ela em redor no dia da calamidade.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 3, 'Não arme o flecheiro o seu arco, nem se levante o que estiver armado da sua couraça; não perdoeis aos seus jovens; destruí completamente todo o seu exército.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 4, 'Cairão mortos na terra dos caldeus, e feridos nas ruas dela.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 5, 'Pois Israel e Judá não foram abandonados do seu Deus, o Senhor dos exércitos, ainda que a terra deles esteja cheia de culpas contra o Santo de Israel.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 6, 'Fugi do meio de Babilônia, e livre cada um a sua vida; não sejais exterminados na sua punição; pois este é o tempo da vingança do Senhor; ele lhe dará o pago.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 7, 'Na mão do Senhor a Babilônia era um copo de ouro, o qual embriagava a toda a terra; do seu vinho beberam as nações; por isso as nações estão fora de si.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 8, 'Repentinamente caiu Babilônia, e ficou arruinada; uivai sobre ela; tomai bálsamo para a sua dor, talvez sare.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 9, 'Queríamos sarar Babilônia, ela, porém, não sarou; abandonai-a, e vamo-nos, cada qual para a sua terra; pois o seu julgamento chega até o céu, e se eleva até as mais altas nuvens.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 10, 'O Senhor trouxe à luz a nossa justiça; vinde e anunciemos em Sião a obra do Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 11, 'Aguçai as flechas, preparei os escudos; o Senhor despertou o espírito dos reis dos medos; porque o seu intento contra Babilônia é para a destruir; pois esta é a vingança do Senhor, a vingança do seu templo.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 12, 'Arvorai um estandarte sobre os muros de Babilônia, reforçai a guarda, colocai sentinelas, preparai as emboscadas; porque o Senhor tanto intentou como efetuou o que tinha dito acerca dos moradores de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 13, 'Ó tu, que habitas sobre muitas águas, rica de tesouros! é chegado o teu fim, a medida da tua ganância.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 14, 'Jurou o Senhor dos exércitos por si mesmo, dizendo: Certamente te encherei de homens, como de locustas; e eles levantarão o grito de vitória sobre ti.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 15, 'É ele quem fez a terra com o seu poder, estabeleceu o mundo com a sua sabedoria, e estendeu os céus com o seu entendimento.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 16, 'À sua voz, há grande tumulto de águas nas céus, e ele faz subir os vapores desde as extremidades da terra; faz os relâmpagos para a chuva, e tira o vento dos seus tesouros.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 17, 'Embruteceu-se todo homem, de modo que não tem conhecimento; todo ourives é envergonhado pelas suas imagens esculpidas; pois as suas imagens de fundição são mentira, e não há espírito em nenhuma delas.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 18, 'Vaidade são, obra de enganos; no tempo em que eu as visitar perecerão.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 19, 'Não é semelhante a estes a porção de Jacó; porque ele é o que forma todas as coisas; e Israel é a tribo da sua herança; o Senhor dos exércitos é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 20, 'Tu me serves de martelo e de armas de guerra; contigo despedaçarei nações, e contigo destruirei os reis;', 1, CURRENT_TIMESTAMP, false),
(24, 51, 21, 'contigo despedaçarei o cavalo e o seu cavaleiro; contigo despedaçarei e carro e o que nele vai;', 1, CURRENT_TIMESTAMP, false),
(24, 51, 22, 'contigo despedaçarei o homem e a mulher; contigo despedaçarei o velho e o moço; contigo despedaçarei o mancebo e a donzela;', 1, CURRENT_TIMESTAMP, false),
(24, 51, 23, 'contigo despedaçarei o pastor e o seu rebanho; contigo despedaçarei o lavrador e a sua junta de bois; e contigo despedaçarei governadores e magistrados.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 24, 'Ante os vossos olhos pagarei a Babilônia, e a todos os moradores da Caldéia, toda a sua maldade que fizeram em Sião, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 25, 'Eis-me aqui contra ti, ó monte destruidor, diz o Senhor, que destróis toda a terra; estenderei a minha mão contra ti, e te revolverei dos penhascos abaixo, e farei de ti um monte incendiado.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 26, 'E não tomarão de ti pedra para esquina, nem pedra para fundamentos; mas desolada ficarás perpetuamente, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 27, 'Arvorai um estandarte na terra, tocai a trombeta entre as nações, preparai as nações contra ela, convocai contra ela os reinos de Arará, Mini, e Asquenaz; ponde sobre ela um capitão, fazei subir cavalos, como locustas eriçadas.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 28, 'Preparai contra ela as nações, os reis dos medos, os seus governadores e magistrados, e toda a terra do seu domínio.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 29, 'E a terra estremece e está angustiada; porque os desígnios do Senhor estão firmes contra Babilônia, para fazer da terra de Babilônia uma desolação, sem habitantes.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 30, 'Os valentes de Babilônia cessaram de pelejar, ficam nas fortalezas, desfaleceu a sua força, tornaram-se como mulheres; incendiadas são as suas moradas, quebrados os seus ferrolhos.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 31, 'Um correio corre ao encontro de outro correio, e um mensageiro ao encontro de outro mensageiro, para anunciar ao rei de Babilônia que a sua cidade está tomada de todos os lados.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 32, 'E os vaus estão ocupados, os canaviais queimados a fogo, e os homens de guerra assombrados.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 33, 'Pois assim diz o Senhor dos exércitos, o Deus de Israel: A filha de Babilônia é como a eira no tempo da debulha; ainda um pouco, e o tempo da sega lhe virá.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 34, 'Nabucodonosor, rei de Babilônia, devorou-me, esmagou-me, fez de mim um vaso vazio, qual monstro tragou-me, encheu o seu ventre do que eu tinha de delicioso; lançou-me fora.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 35, 'A violência que se me fez a mim e à minha carne venha sobre Babilônia, diga a moradora de Sião. O meu sangue caia sobre os moradores de Caldéia, diga Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 36, 'Pelo que assim diz o Senhor: Eis que defenderei a tua causa, e te vingarei; e secarei o seu mar, e farei que se esgote a sua fonte:', 1, CURRENT_TIMESTAMP, false),
(24, 51, 37, 'E Babilônia se tornará em montões, morada de chacais, objeto de espanto e assobio, sem habitante.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 38, 'Juntos rugirão como leões novos, bramarão como cachorros de leões.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 39, 'Estando eles excitados, preparar-lhes-ei um banquete, e os embriagarei, para que se regozijem, e durmam um perpétuo sono, e não despertem, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 40, 'Fá-los-ei descer como cordeiros ao matadouro, como carneiros e bodes.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 41, 'Como foi tomada Sesaque, e apanhada de surpresa a glória de toda a terra! como se tornou Babilônia um espetáculo horrendo entre as nações!', 1, CURRENT_TIMESTAMP, false),
(24, 51, 42, 'O mar subiu sobre Babilônia; coberta está com a multidão das suas ondas.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 43, 'Tornaram-se as suas cidades em ruínas, terra seca e deserta, terra em que ninguém habita, nem passa por ela filho de homem.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 44, 'E castigarei a Bel em Babilônia, e tirarei da sua boca o que ele tragou; e nunca mais concorrerão a ele as nações; o muro de Babilônia está caído.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 45, 'Saí do meio dela, ó povo meu, e salve cada um a sua vida do ardor da ira do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 46, 'Não desfaleça o vosso coração, nem temais pelo rumor que se ouvir na terra; pois virá num ano um rumor, e depois noutro ano outro rumor; e haverá violência na terra, dominador contra dominador.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 47, 'Portanto eis que vêm os dias em que executarei juízo sobre as imagens esculpidas de Babilônia; e toda a sua terra ficará envergonhada; e todos os seus traspassados cairão no meio dela.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 48, 'Então o céu e a terra, com tudo quanto neles há, jubilarão sobre Babilônia; pois do norte lhe virão os destruidores, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 49, 'Babilônia há de cair pelos mortos de Israel, assim como por Babilônia têm caído os mortos de toda a terra.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 50, 'Vós, que escapastes da espada, ide-vos, não pareis; desde terras longínquas lembrai-vos do Senhor, e suba Jerusalém à vossa mente.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 51, 'Envergonhados estamos, porque ouvimos opróbrio; a confusão nos cobriu o rosto; pois entraram estrangeiros nos santuários da casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 52, 'Portanto, eis que vêm os dias, diz o Senhor, em que executarei juízo sobre as suas imagens esculpidas; e em toda a sua terra gemerão os feridos.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 53, 'Ainda que Babilônia subisse ao céu, e ainda que fortificasse a altura da sua fortaleza, contudo de mim viriam destruidores sobre ela, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 54, 'Eis um clamor de Babilônia! de grande destruição da terra dos caldeus!', 1, CURRENT_TIMESTAMP, false),
(24, 51, 55, 'Pois o Senhor está despojando a Babilônia, e emudecendo a sua poderosa voz. Bramam as ondas do inimigo como muitas águas; ouve-se o arruído da sua voz.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 56, 'Porque o destruidor veio sobre ela, sobre Babilônia, e os seus valentes estão presos; já estão despedaçados os seus arcos; pois o Senhor é Deus das recompensas, ele certamente retribuirá.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 57, 'Embriagarei os seus príncipes e os seus sábios, os seus governadores, os seus magistrados, e os seus valentes; e dormirão um sono perpétuo, e jamais acordarão, diz o Rei, cujo nome é o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 58, 'Assim diz o Senhor dos exércitos: O largo muro de Babilônia será de todo derribado, e as suas portas altas serão abrasadas pelo fogo; e trabalharão os povos em vão, e as nações se cansarão só para o fogo.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 59, 'A palavra que Jeremias, o profeta, mandou a Seraías, filho de Nerias, filho de Maséias, quando ia com Zedequias, rei de Judá, a Babilônia, no quarto ano do seu reinado. Ora, Seraías era o camareiro-mor.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 60, 'Escreveu, pois, Jeremias num livro todo o mal que havia de vir sobre Babilônia, a saber, todas estas palavras que estão escritas acerca de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 61, 'E disse Jeremias a Seraías: Quando chegares a Babilônia, vê que leias todas estas palavras;', 1, CURRENT_TIMESTAMP, false),
(24, 51, 62, 'e dirás: Tu, Senhor, falaste a respeito deste lugar, que o havias de desarraigar, até não ficar nele morador algum, nem homem nem animal, mas que se tornaria em perpétua desolação.', 1, CURRENT_TIMESTAMP, false),
(24, 51, 63, 'E acabando tu de ler este livro, atar-lhe-ás uma pedra e o lançarás no meio do Eufrates;', 1, CURRENT_TIMESTAMP, false),
(24, 51, 64, 'e dirás: Assim será submergida Babilônia, e não se levantará, por causa do mal que vou trazer sobre ela; e eles se cansarão.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 1, 'Era Zedequias da idade de vinte e um anos quando começou a reinar, e reinou onze anos em Jerusalém. O nome de sua mãe era Hamutal, filha de Jeremias, de Libna.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 2, 'E fez o que era mau aos olhos do Senhor, conforme tudo o que fizera Jeoiaquim.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 3, 'Pois por causa da ira do Senhor, chegou-se a tal ponto em Jerusalém e Judá que ele os lançou da sua presença. E Zedequias rebelou-se contra o rei de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 4, 'No ano nono do seu reinado, no mês décimo, no décimo dia do mês, veio Nabucodonosor, rei de Babilônia, contra Jerusalém, ele e todo o seu exército, e se acamparam contra ela, e contra ela levantaram tranqueiras ao redor.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 5, 'Assim esteve cercada a cidade, até o ano undécimo do rei Zedequias.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 6, 'No quarto mês, aos nove do mês, a fome prevalecia na cidade, de tal modo que não havia pão para o povo da terra.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 7, 'Então foi aberta uma brecha na cidade; e todos os homens de guerra fugiram, e saíram da cidade de noite, pelo caminho da porta entre os dois muros, a qual está junto ao jardim do rei, enquanto os caldeus estavam ao redor da cidade; e foram pelo caminho da Arabá.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 8, 'Mas o exército dos caldeus perseguiu o rei, e alcançou a Zedequias nas campinas de Jericó; e todo o seu exército se espalhou, abandonando-o.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 9, 'Prenderam o rei, e o fizeram subir ao rei de Babilônia a Ribla na terra de Hamate, o qual lhe pronunciou a sentença.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 10, 'E o rei de Babilônia matou os filhos de Zedequias à sua vista; e também matou a todos os príncipes de Judá em Ribla.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 11, 'E cegou os olhos a Zedequias; e o atou com cadeias; e o rei de Babilônia o levou para Babilônia, e o conservou na prisão até o dia da sua morte.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 12, 'No quinto mês, no décimo dia do mês, que era o décimo nono ano do rei Nabucodonosor, rei de Babilônia, veio a Jerusalém Nebuzaradão, capitão da guarda, que assistia na presença do rei de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 13, 'E queimou a casa do Senhor, e a casa do rei; como também a todas as casas de Jerusalém, todas as casas importantes, ele as incendiou.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 14, 'E todo o exército dos caldeus, que estava com o capitão da guarda, derribou todos os muros que rodeavam Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 15, 'E os mais pobres do povo, e o resto do povo que tinha ficado na cidade, e os desertores que se haviam passado para o rei de Babilônia, e o resto dos artífices, Nebuzaradão, capitão da guarda, levou-os cativos.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 16, 'Mas dos mais pobres da terra Nebuzaradão, capitão da guarda, deixou ficar alguns, para serem vinhateiros e lavradores.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 17, 'Os caldeus despedaçaram as colunas de bronze que estavam na casa do Senhor, e as bases, e o mar de bronze, que estavam na casa do Senhor, e levaram todo o bronze para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 18, 'Também tomaram as caldeiras, as pás, as espevitadeiras, as bacias, as colheres, e todos os utensílios de bronze, com que se ministrava.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 19, 'De igual modo o capitão da guarda levou os copos, os braseiros, as bacias, as caldeiras, os castiçais, as colheres, e as tigelas. O que era de ouro, levou como ouro, e o que era de prata, como prata.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 20, 'Quanto às duas colunas, ao mar, e aos doze bois de bronze que estavam debaixo das bases, que fizera o rei Salomão para a casa do Senhor, o peso do bronze de todos estes vasos era incalculável.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 21, 'Dessas colunas, a altura de cada um era de dezoito côvados; doze côvados era a medida da sua circunferência; e era a sua espessura de quatro dedos; e era oca.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 22, 'E havia sobre ela um capitel de bronze; e a altura dum capitel era de cinco côvados, com uma rede e romãs sobre o capitel ao redor, tudo de bronze; e a segunda coluna tinha as mesmas coisas com as romãs.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 23, 'E havia noventa e seis romãs aos lados; as romãs todas, sobre a rede ao redor eram cem.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 24, 'Levou também o capitão da guarda a Seraías, o principal sacerdote, e a Sofonias, o segundo sacerdote, e os três guardas da porta;', 1, CURRENT_TIMESTAMP, false),
(24, 52, 25, 'e da cidade levou um oficial que tinha a seu cargo os homens de guerra; e a sete homens dos que assistiam ao rei e que se achavam na cidade; como também o escrivão-mor do exército, que registrava o povo da terra; e mais sessenta homens do povo da terra que se achavam no meio da cidade.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 26, 'Tomando-os pois Nebuzaradão, capitão da guarda, levou-os ao rei de Babilônia, a Ribla.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 27, 'E o rei de Babilônia os feriu e os matou em Ribla, na terra de Hamate. Assim Judá foi levado cativo para fora da sua terra.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 28, 'Este é o povo que Nabucodonosor levou cativo: no sétimo ano três mil e vinte e três judeus;', 1, CURRENT_TIMESTAMP, false),
(24, 52, 29, 'no ano décimo oitavo de Nabucodonosor, ele levou cativas de Jerusalém oitocentas e trinta e duas pessoas;', 1, CURRENT_TIMESTAMP, false),
(24, 52, 30, 'no ano vinte e três de Nabucodonosor, Nebuzaradão, capitão da guarda, levou cativas, dentre os judeus, setecentas e quarenta e cinco pessoas; todas as pessoas foram quatro mil e seiscentas.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 31, 'No ano trigésimo sétimo do cativeiro de Joaquim, rei de Judá, no mês duodécimo, aos vinte e cinco do mês, Evil-Merodaque, rei de Babilônia, no primeiro ano do seu reinado, levantou a cabeça de Joaquim, rei de Judá, e o tirou do cárcere;', 1, CURRENT_TIMESTAMP, false),
(24, 52, 32, 'e falou com ele benignamente, e pôs o trono dele acima dos tronos dos reis que estavam com ele em Babilônia;', 1, CURRENT_TIMESTAMP, false),
(24, 52, 33, 'e lhe fez mudar a roupa da sua prisão; e Joaquim comia pão na presença do rei continuamente, todos os dias da sua vida.', 1, CURRENT_TIMESTAMP, false),
(24, 52, 34, 'E, quanto à sua ração, foi-lhe dada pelo rei de Babilônia a sua porção quotidiana, até o dia da sua morte, durante todos os dias da sua vida.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 1, 'No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 2, 'Ele estava no princípio com Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 3, 'Todas as coisas foram feitas por intermédio dele, e sem ele nada do que foi feito se fez.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 4, 'Nele estava a vida, e a vida era a luz dos homens;', 1, CURRENT_TIMESTAMP, false),
(43, 1, 5, 'a luz resplandece nas trevas, e as trevas não prevaleceram contra ela.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 6, 'Houve um homem enviado de Deus, cujo nome era João.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 7, 'Este veio como testemunha, a fim de dar testemunho da luz, para que todos cressem por meio dele.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 8, 'Ele não era a luz, mas veio para dar testemunho da luz.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 9, 'Pois a verdadeira luz, que alumia a todo homem, estava chegando ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 10, 'Estava ele no mundo, e o mundo foi feito por intermédio dele, e o mundo não o conheceu.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 11, 'Veio para o que era seu, e os seus não o receberam.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 12, 'Mas, a todos quantos o receberam, aos que crêem no seu nome, deu-lhes o poder de se tornarem filhos de Deus;', 1, CURRENT_TIMESTAMP, false),
(43, 1, 13, 'os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do varão, mas de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 14, 'E o Verbo se fez carne, e habitou entre nós, cheio de graça e de verdade; e vimos a sua glória, como a glória do unigênito do Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 15, 'João deu testemunho dele, e clamou, dizendo: Este é aquele de quem eu disse: O que vem depois de mim, passou adiante de mim; porque antes de mim ele já existia.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 16, 'Pois todos nós recebemos da sua plenitude, e graça sobre graça.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 17, 'Porque a lei foi dada por meio de Moisés; a graça e a verdade vieram por Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 18, 'Ninguém jamais viu a Deus. O Deus unigênito, que está no seio do Pai, esse o deu a conhecer.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 19, 'E este foi o testemunho de João, quando os judeus lhe enviaram de Jerusalém sacerdotes e levitas para que lhe perguntassem: Quem és tu?', 1, CURRENT_TIMESTAMP, false),
(43, 1, 20, 'Ele, pois, confessou e não negou; sim, confessou: Eu não sou o Cristo.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 21, 'Ao que lhe perguntaram: Pois que? És tu Elias? Respondeu ele: Não sou. És tu o profeta? E respondeu: Não.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 22, 'Disseram-lhe, pois: Quem és? para podermos dar resposta aos que nos enviaram; que dizes de ti mesmo?', 1, CURRENT_TIMESTAMP, false),
(43, 1, 23, 'Respondeu ele: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 24, 'E os que tinham sido enviados eram dos fariseus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 25, 'Então lhe perguntaram: Por que batizas, pois, se tu não és o Cristo, nem Elias, nem o profeta?', 1, CURRENT_TIMESTAMP, false),
(43, 1, 26, 'Respondeu-lhes João: Eu batizo em água; no meio de vós está um a quem vós não conheceis.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 27, 'aquele que vem depois de mim, de quem eu não sou digno de desatar a correia da alparca.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 28, 'Estas coisas aconteceram em Betânia, além do Jordão, onde João estava batizando.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 29, 'No dia seguinte João viu a Jesus, que vinha para ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 30, 'este é aquele de quem eu disse: Depois de mim vem um varão que passou adiante de mim, porque antes de mim ele já existia.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 31, 'Eu não o conhecia; mas, para que ele fosse manifestado a Israel, é que vim batizando em água.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 32, 'E João deu testemunho, dizendo: Vi o Espírito descer do céu como pomba, e repousar sobre ele.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 33, 'Eu não o conhecia; mas o que me enviou a batizar em água, esse me disse: Aquele sobre quem vires descer o Espírito, e sobre ele permanecer, esse é o que batiza no Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 34, 'Eu mesmo vi e já vos dei testemunho de que este é o Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 35, 'No dia seguinte João estava outra vez ali, com dois dos seus discípulos', 1, CURRENT_TIMESTAMP, false),
(43, 1, 36, 'e, olhando para Jesus, que passava, disse: Eis o Cordeiro de Deus!', 1, CURRENT_TIMESTAMP, false),
(43, 1, 37, 'Aqueles dois discípulos ouviram-no dizer isto, e seguiram a Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 38, 'Voltando-se Jesus e vendo que o seguiam, perguntou-lhes: Que buscais? Disseram-lhe eles: rabi {que, traduzido, quer dizer Mestre}, onde pousas?', 1, CURRENT_TIMESTAMP, false),
(43, 1, 39, 'Respondeu-lhes: Vinde, e vereis. Foram, pois, e viram onde pousava; e passaram o dia com ele; era cerca da hora décima.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 40, 'André, irmão de Simão Pedro, era um dos dois que ouviram João falar, e que seguiram a Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 41, 'Ele achou primeiro a seu irmão Simão, e disse-lhe: Havemos achado o Messias {que, traduzido, quer dizer Cristo}.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 42, 'E o levou a Jesus. Jesus, fixando nele o olhar, disse: Tu és Simão, filho de João, tu serás chamado Cefas {que quer dizer Pedro}.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 43, 'No dia seguinte Jesus resolveu partir para a Galiléia, e achando a Felipe disse-lhe: Segue-me.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 44, 'Ora, Felipe era de Betsaida, cidade de André e de Pedro.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 45, 'Felipe achou a Natanael, e disse-lhe: Acabamos de achar aquele de quem escreveram Moisés na lei, e os profetas: Jesus de Nazaré, filho de José.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 46, 'Perguntou-lhe Natanael: Pode haver coisa bem vinda de Nazaré? Disse-lhe Felipe: Vem e vê.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 47, 'Jesus, vendo Natanael aproximar-se dele, disse a seu respeito: Eis um verdadeiro israelita, em quem não há dolo!', 1, CURRENT_TIMESTAMP, false),
(43, 1, 48, 'Perguntou-lhe Natanael: Donde me conheces? Respondeu-lhe Jesus: Antes que Felipe te chamasse, eu te vi, quando estavas debaixo da figueira.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 49, 'Respondeu-lhe Natanael: Rabi, tu és o Filho de Deus, tu és rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 50, 'Ao que lhe disse Jesus: Porque te disse: Vi-te debaixo da figueira, crês? coisas maiores do que estas verás.', 1, CURRENT_TIMESTAMP, false),
(43, 1, 51, 'E acrescentou: Em verdade, em verdade vos digo que vereis o céu aberto, e os anjos de Deus subindo e descendo sobre o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 1, 'Três dias depois, houve um casamento em Caná da Galiléia, e estava ali a mãe de Jesus;', 1, CURRENT_TIMESTAMP, false),
(43, 2, 2, 'e foi também convidado Jesus com seus discípulos para o casamento.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 3, 'E, tendo acabado o vinho, a mãe de Jesus lhe disse: Eles não têm vinho.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 4, 'Respondeu-lhes Jesus: Mulher, que tenho eu contigo? Ainda não é chegada a minha hora.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 5, 'Disse então sua mãe aos serventes: Fazei tudo quanto ele vos disser.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 6, 'Ora, estavam ali postas seis talhas de pedra, para as purificações dos judeus, e em cada uma cabiam duas ou três metretas.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 7, 'Ordenou-lhe Jesus: Enchei de água essas talhas. E encheram-nas até em cima.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 8, 'Então lhes disse: Tirai agora, e levai ao mestre-sala. E eles o fizeram.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 9, 'Quando o mestre-sala provou a água tornada em vinho, não sabendo donde era, se bem que o sabiam os serventes que tinham tirado a água, chamou o mestre-sala ao noivo', 1, CURRENT_TIMESTAMP, false),
(43, 2, 10, 'e lhe disse: Todo homem põe primeiro o vinho bom e, quando já têm bebido bem, então o inferior; mas tu guardaste até agora o bom vinho.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 11, 'Assim deu Jesus início aos seus sinais em Caná da Galiléia, e manifestou a sua glória; e os seus discípulos creram nele.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 12, 'Depois disso desceu a Cafarnaum, ele, sua mãe, seus irmãos, e seus discípulos; e ficaram ali não muitos dias.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 13, 'Estando próxima a páscoa dos judeus, Jesus subiu a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 14, 'E achou no templo os que vendiam bois, ovelhas e pombas, e também os cambistas ali sentados;', 1, CURRENT_TIMESTAMP, false),
(43, 2, 15, 'e tendo feito um azorrague de cordas, lançou todos fora do templo, bem como as ovelhas e os bois; e espalhou o dinheiro dos cambistas, e virou-lhes as mesas;', 1, CURRENT_TIMESTAMP, false),
(43, 2, 16, 'e disse aos que vendiam as pombas: Tirai daqui estas coisas; não façais da casa de meu Pai casa de negócio.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 17, 'Lembraram-se então os seus discípulos de que está escrito: O zelo da tua casa me devorará.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 18, 'Protestaram, pois, os judeus, perguntando-lhe: Que sinal de autoridade nos mostras, uma vez que fazes isto?', 1, CURRENT_TIMESTAMP, false),
(43, 2, 19, 'Respondeu-lhes Jesus: Derribai este santuário, e em três dias o levantarei.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 20, 'Disseram, pois, os judeus: Em quarenta e seis anos foi edificado este santuário, e tu o levantarás em três dias?', 1, CURRENT_TIMESTAMP, false),
(43, 2, 21, 'Mas ele falava do santuário do seu corpo.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 22, 'Quando, pois ressurgiu dentre os mortos, seus discípulos se lembraram de que dissera isto, e creram na Escritura, e na palavra que Jesus havia dito.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 23, 'Ora, estando ele em Jerusalém pela festa da páscoa, muitos, vendo os sinais que fazia, creram no seu nome.', 1, CURRENT_TIMESTAMP, false),
(43, 2, 24, 'Mas o próprio Jesus não confiava a eles, porque os conhecia a todos,', 1, CURRENT_TIMESTAMP, false),
(43, 2, 25, 'e não necessitava de que alguém lhe desse testemunho do homem, pois bem sabia o que havia no homem.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 1, 'Ora, havia entre os fariseus um homem chamado Nicodemos, um dos principais dos judeus.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 2, 'Este foi ter com Jesus, de noite, e disse-lhe: Rabi, sabemos que és Mestre, vindo de Deus; pois ninguém pode fazer estes sinais que tu fazes, se Deus não estiver com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 3, 'Respondeu-lhe Jesus: Em verdade, em verdade te digo que se alguém não nascer de novo, não pode ver o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 4, 'Perguntou-lhe Nicodemos: Como pode um homem nascer, sendo velho? porventura pode tornar a entrar no ventre de sua mãe, e nascer?', 1, CURRENT_TIMESTAMP, false),
(43, 3, 5, 'Jesus respondeu: Em verdade, em verdade te digo que se alguém não nascer da água e do Espírito, não pode entrar no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 6, 'O que é nascido da carne é carne, e o que é nascido do Espírito é espírito.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 7, 'Não te admires de eu te haver dito: Necessário vos é nascer de novo.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 8, 'O vento sopra onde quer, e ouves a sua voz; mas não sabes donde vem, nem para onde vai; assim é todo aquele que é nascido do Espírito.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 9, 'Perguntou-lhe Nicodemos: Como pode ser isto?', 1, CURRENT_TIMESTAMP, false),
(43, 3, 10, 'Respondeu-lhe Jesus: Tu és mestre em Israel, e não entendes estas coisas?', 1, CURRENT_TIMESTAMP, false),
(43, 3, 11, 'Em verdade, em verdade te digo que nós dizemos o que sabemos e testemunhamos o que temos visto; e não aceitais o nosso testemunho!', 1, CURRENT_TIMESTAMP, false),
(43, 3, 12, 'Se vos falei de coisas terrestres, e não credes, como crereis, se vos falar das celestiais?', 1, CURRENT_TIMESTAMP, false),
(43, 3, 13, 'Ora, ninguém subiu ao céu, senão o que desceu do céu, o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 14, 'E como Moisés levantou a serpente no deserto, assim importa que o Filho do homem seja levantado;', 1, CURRENT_TIMESTAMP, false),
(43, 3, 15, 'para que todo aquele que nele crê tenha a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 16, 'Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 17, 'Porque Deus enviou o seu Filho ao mundo, não para que julgasse o mundo, mas para que o mundo fosse salvo por ele.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 18, 'Quem crê nele não é julgado; mas quem não crê, já está julgado; porquanto não crê no nome do unigênito Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 19, 'E o julgamento é este: A luz veio ao mundo, e os homens amaram antes as trevas que a luz, porque as suas obras eram más.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 20, 'Porque todo aquele que faz o mal aborrece a luz, e não vem para a luz, para que as suas obras não sejam reprovadas.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 21, 'Mas quem pratica a verdade vem para a luz, a fim de que seja manifesto que as suas obras são feitas em Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 22, 'Depois disto foi Jesus com seus discípulos para a terra da Judéia, onde se demorou com eles e batizava.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 23, 'Ora, João também estava batizando em Enom, perto de Salim, porque havia ali muitas águas; e o povo ia e se batizava.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 24, 'Pois João ainda não fora lançado no cárcere.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 25, 'Surgiu então uma contenda entre os discípulos de João e um judeu acerca da purificação.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 26, 'E foram ter com João e disseram-lhe: Rabi, aquele que estava contigo além do Jordão, do qual tens dado testemunho, eis que está batizando, e todos vão ter com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 27, 'Respondeu João: O homem não pode receber coisa alguma, se não lhe for dada do céu.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 28, 'Vós mesmos me sois testemunhas de que eu disse: Não sou o Cristo, mas sou enviado adiante dele.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 29, 'Aquele que tem a noiva é o noivo; mas o amigo do noivo, que está presente e o ouve, regozija-se muito com a voz do noivo. Assim, pois, este meu gozo está completo.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 30, 'É necessário que ele cresça e que eu diminua.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 31, 'Aquele que vem de cima é sobre todos; aquele que vem da terra é da terra, e fala da terra. Aquele que vem do céu é sobre todos.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 32, 'Aquilo que ele tem visto e ouvido, isso testifica; e ninguém aceita o seu testemunho.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 33, 'Mas o que aceitar o seu testemunho, esse confirma que Deus é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 34, 'Pois aquele que Deus enviou fala as palavras de Deus; porque Deus não dá o Espírito por medida.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 35, 'O Pai ama ao Filho, e todas as coisas entregou nas suas mãos.', 1, CURRENT_TIMESTAMP, false),
(43, 3, 36, 'Quem crê no Filho tem a vida eterna; o que, porém, desobedece ao Filho não verá a vida, mas sobre ele permanece a ira de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 1, 'Quando, pois, o Senhor soube que os fariseus tinham ouvido dizer que ele, Jesus, fazia e batizava mais discípulos do que João', 1, CURRENT_TIMESTAMP, false),
(43, 4, 2, '{ainda que Jesus mesmo não batizava, mas os seus discípulos}', 1, CURRENT_TIMESTAMP, false),
(43, 4, 3, 'deixou a Judéia, e foi outra vez para a Galiléia.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 4, 'E era-lhe necessário passar por Samária.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 5, 'Chegou, pois, a uma cidade de Samária, chamada Sicar, junto da herdade que Jacó dera a seu filho José;', 1, CURRENT_TIMESTAMP, false),
(43, 4, 6, 'achava-se ali o poço de Jacó. Jesus, pois, cansado da viagem, sentou-se assim junto do poço; era cerca da hora sexta.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 7, 'Veio uma mulher de Samária tirar água. Disse-lhe Jesus: Dá-me de beber.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 8, 'Pois seus discípulos tinham ido à cidade comprar comida.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 9, 'Disse-lhe então a mulher samaritana: Como, sendo tu judeu, me pedes de beber a mim, que sou mulher samaritana? {Porque os judeus não se comunicavam com os samaritanos.}', 1, CURRENT_TIMESTAMP, false),
(43, 4, 10, 'Respondeu-lhe Jesus: Se tivesses conhecido o dom de Deus e quem é o que te diz: Dá-me de beber, tu lhe terias pedido e ele te haveria dado água viva.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 11, 'Disse-lhe a mulher: Senhor, tu não tens com que tirá-la, e o poço é fundo; donde, pois, tens essa água viva?', 1, CURRENT_TIMESTAMP, false),
(43, 4, 12, 'És tu, porventura, maior do que o nosso pai Jacó, que nos deu o poço, do qual também ele mesmo bebeu, e os filhos, e o seu gado?.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 13, 'Replicou-lhe Jesus: Todo o que beber desta água tornará a ter sede;', 1, CURRENT_TIMESTAMP, false),
(43, 4, 14, 'mas aquele que beber da água que eu lhe der nunca terá sede; pelo contrário, a água que eu lhe der se fará nele uma fonte de água que jorre para a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 15, 'Disse-lhe a mulher: Senhor, dá-me dessa água, para que não mais tenha sede, nem venha aqui tirá-la.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 16, 'Disse-lhe Jesus: Vai, chama o teu marido e vem cá.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 17, 'Respondeu a mulher: Não tenho marido. Disse-lhe Jesus: Disseste bem: Não tenho marido;', 1, CURRENT_TIMESTAMP, false),
(43, 4, 18, 'porque cinco maridos tiveste, e o que agora tens não é teu marido; isso disseste com verdade.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 19, 'Disse-lhe a mulher: Senhor, vejo que és profeta.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 20, 'Nossos pais adoraram neste monte, e vós dizeis que em Jerusalém é o lugar onde se deve adorar.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 21, 'Disse-lhe Jesus: Mulher, crê-me, a hora vem, em que nem neste monte, nem em Jerusalém adorareis o Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 22, 'Vós adorais o que não conheceis; nós adoramos o que conhecemos; porque a salvação vem dos judeus.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 23, 'Mas a hora vem, e agora é, em que os verdadeiros adoradores adorarão o Pai em espírito e em verdade; porque o Pai procura a tais que assim o adorem.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 24, 'Deus é Espírito, e é necessário que os que o adoram o adorem em espírito e em verdade.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 25, 'Replicou-lhe a mulher: Eu sei que vem o Messias {que se chama o Cristo}; quando ele vier há de nos anunciar todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 26, 'Disse-lhe Jesus: Eu o sou, eu que falo contigo.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 27, 'E nisto vieram os seus discípulos, e se admiravam de que estivesse falando com uma mulher; todavia nenhum lhe perguntou: Que é que procuras? ou: Por que falas com ela?', 1, CURRENT_TIMESTAMP, false),
(43, 4, 28, 'Deixou, pois, a mulher o seu cântaro, foi à cidade e disse àqueles homens:', 1, CURRENT_TIMESTAMP, false),
(43, 4, 29, 'Vinde, vede um homem que me disse tudo quanto eu tenho feito; será este, porventura, o Cristo?', 1, CURRENT_TIMESTAMP, false),
(43, 4, 30, 'Saíram, pois, da cidade e vinham ter com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 31, 'Entrementes os seus discípulos lhe rogavam, dizendo: Rabi, come.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 32, 'Ele, porém, respondeu: Uma comida tenho para comer que vós não conheceis.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 33, 'Então os discípulos diziam uns aos outros: Acaso alguém lhe trouxe de comer?', 1, CURRENT_TIMESTAMP, false),
(43, 4, 34, 'Disse-lhes Jesus: A minha comida é fazer a vontade daquele que me enviou, e completar a sua obra.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 35, 'Não dizeis vós: Ainda há quatro meses até que venha a ceifa? Ora, eu vos digo: levantai os vossos olhos, e vede os campos, que já estão brancos para a ceifa.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 36, 'Quem ceifa já está recebendo recompensa e ajuntando fruto para a vida eterna; para que o que semeia e o que ceifa juntamente se regozijem.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 37, 'Porque nisto é verdadeiro o ditado: Um é o que semeia, e outro o que ceifa.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 38, 'Eu vos enviei a ceifar onde não trabalhaste; outros trabalharam, e vós entrastes no seu trabalho.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 39, 'E muitos samaritanos daquela cidade creram nele, por causa da palavra da mulher, que testificava: Ele me disse tudo quanto tenho feito.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 40, 'Indo, pois, ter com ele os samaritanos, rogaram-lhe que ficasse com eles; e ficou ali dois dias.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 41, 'E muitos mais creram por causa da palavra dele;', 1, CURRENT_TIMESTAMP, false),
(43, 4, 42, 'e diziam à mulher: Já não é pela tua palavra que nós cremos; pois agora nós mesmos temos ouvido e sabemos que este é verdadeiramente o Salvador do mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 43, 'Passados os dois dias partiu dali para a Galiléia.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 44, 'Porque Jesus mesmo testificou que um profeta não recebe honra na sua própria pátria.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 45, 'Assim, pois, que chegou à Galiléia, os galileus o receberam, porque tinham visto todas as coisas que fizera em Jerusalém na ocasião da festa; pois também eles tinham ido à festa.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 46, 'Foi, então, outra vez a Caná da Galiléia, onde da água fizera vinho. Ora, havia um oficial do rei, cujo filho estava enfermo em Cafarnaum.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 47, 'Quando ele soube que Jesus tinha vindo da Judéia para a Galiléia, foi ter com ele, e lhe rogou que descesse e lhe curasse o filho; pois estava à morte.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 48, 'Então Jesus lhe disse: Se não virdes sinais e prodígios, de modo algum crereis.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 49, 'Rogou-lhe o oficial: Senhor, desce antes que meu filho morra.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 50, 'Respondeu-lhe Jesus: Vai, o teu filho vive. E o homem creu na palavra que Jesus lhe dissera, e partiu.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 51, 'Quando ele já ia descendo, saíram-lhe ao encontro os seus servos, e lhe disseram que seu filho vivia.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 52, 'Perguntou-lhes, pois, a que hora começara a melhorar; ao que lhe disseram: Ontem à hora sétima a febre o deixou.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 53, 'Reconheceu, pois, o pai ser aquela hora a mesma em que Jesus lhe dissera: O teu filho vive; e creu ele e toda a sua casa.', 1, CURRENT_TIMESTAMP, false),
(43, 4, 54, 'Foi esta a segunda vez que Jesus, ao voltar da Judéia para a Galiléia, ali operou sinal.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 1, 'Depois disso havia uma festa dos judeus; e Jesus subiu a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 2, 'Ora, em Jerusalém, próximo à porta das ovelhas, há um tanque, chamado em hebraico Betesda, o qual tem cinco alpendres.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 3, 'Nestes jazia grande multidão de enfermos, cegos, mancos e ressicados {esperando o movimento da água.}', 1, CURRENT_TIMESTAMP, false),
(43, 5, 4, '{Porquanto um anjo descia em certo tempo ao tanque, e agitava a água; então o primeiro que ali descia, depois do movimento da água, sarava de qualquer enfermidade que tivesse.}', 1, CURRENT_TIMESTAMP, false),
(43, 5, 5, 'Achava-se ali um homem que, havia trinta e oito anos, estava enfermo.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 6, 'Jesus, vendo-o deitado e sabendo que estava assim havia muito tempo, perguntou-lhe: Queres ficar são?', 1, CURRENT_TIMESTAMP, false),
(43, 5, 7, 'Respondeu-lhe o enfermo: Senhor, não tenho ninguém que, ao ser agitada a água, me ponha no tanque; assim, enquanto eu vou, desce outro antes de mim.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 8, 'Disse-lhe Jesus: Levanta-te, toma o teu leito e anda.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 9, 'Imediatamente o homem ficou são; e, tomando o seu leito, começou a andar. Ora, aquele dia era sábado.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 10, 'Pelo que disseram os judeus ao que fora curado: Hoje é sábado, e não te é lícito carregar o leito.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 11, 'Ele, porém, lhes respondeu: Aquele que me curou, esse mesmo me disse: Toma o teu leito e anda.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 12, 'Perguntaram-lhe, pois: Quem é o homem que te disse: Toma o teu leito e anda?', 1, CURRENT_TIMESTAMP, false),
(43, 5, 13, 'Mas o que fora curado não sabia quem era; porque Jesus se retirara, por haver muita gente naquele lugar.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 14, 'Depois Jesus o encontrou no templo, e disse-lhe: Olha, já estás curado; não peques mais, para que não te suceda coisa pior.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 15, 'Retirou-se, então, o homem, e contou aos judeus que era Jesus quem o curara.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 16, 'Por isso os judeus perseguiram a Jesus, porque fazia estas coisas no sábado.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 17, 'Mas Jesus lhes respondeu: Meu Pai trabalha até agora, e eu trabalho também.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 18, 'Por isso, pois, os judeus ainda mais procuravam matá-lo, porque não só violava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 19, 'Disse-lhes, pois, Jesus: Em verdade, em verdade vos digo que o Filho de si mesmo nada pode fazer, senão o que vir o Pai fazer; porque tudo quanto ele faz, o Filho o faz igualmente.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 20, 'Porque o Pai ama ao Filho, e mostra-lhe tudo o que ele mesmo faz; e maiores obras do que estas lhe mostrará, para que vos maravilheis.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 21, 'Pois, assim como o Pai levanta os mortos e lhes dá vida, assim também o Filho dá vida a quem ele quer.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 22, 'Porque o Pai a ninguém julga, mas deu ao Filho todo o julgamento,', 1, CURRENT_TIMESTAMP, false),
(43, 5, 23, 'para que todos honrem o Filho, assim como honram o Pai. Quem não honra o Filho, não honra o Pai que o enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 24, 'Em verdade, em verdade vos digo que quem ouve a minha palavra, e crê naquele que me enviou, tem a vida eterna e não entra em juízo, mas já passou da morte para a vida.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 25, 'Em verdade, em verdade vos digo que vem a hora, e agora é, em que os mortos ouvirão a voz do Filho de Deus, e os que a ouvirem viverão.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 26, 'Pois assim como o Pai tem vida em si mesmo, assim também deu ao Filho ter vida em si mesmos;', 1, CURRENT_TIMESTAMP, false),
(43, 5, 27, 'e deu-lhe autoridade para julgar, porque é o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 28, 'Não vos admireis disso, porque vem a hora em que todos os que estão nos sepulcros ouvirão a sua voz e sairão:', 1, CURRENT_TIMESTAMP, false),
(43, 5, 29, 'os que tiverem feito o bem, para a ressurreição da vida, e os que tiverem praticado o mal, para a ressurreição do juízo.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 30, 'Eu não posso de mim mesmo fazer coisa alguma; como ouço, assim julgo; e o meu juízo é justo, porque não procuro a minha vontade, mas a vontade daquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 31, 'Se eu der testemunho de mim mesmo, o meu testemunho não é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 32, 'Outro é quem dá testemunho de mim; e sei que o testemunho que ele dá de mim é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 33, 'Vós mandastes mensageiros a João, e ele deu testemunho da verdade;', 1, CURRENT_TIMESTAMP, false),
(43, 5, 34, 'eu, porém, não recebo testemunho de homem; mas digo isto para que sejais salvos.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 35, 'Ele era a lâmpada que ardia e alumiava; e vós quisestes alegrar-vos por um pouco de tempo com a sua luz.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 36, 'Mas o testemunho que eu tenho é maior do que o de João; porque as obras que o Pai me deu para realizar, as mesmas obras que faço dão testemunho de mim que o Pai me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 37, 'E o Pai que me enviou, ele mesmo tem dado testemunho de mim. Vós nunca ouvistes a sua voz, nem vistes a sua forma;', 1, CURRENT_TIMESTAMP, false),
(43, 5, 38, 'e a sua palavra não permanece em vós; porque não credes naquele que ele enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 39, 'Examinais as Escrituras, porque julgais ter nelas a vida eterna; e são elas que dão testemunho de mim;', 1, CURRENT_TIMESTAMP, false),
(43, 5, 40, 'mas não quereis vir a mim para terdes vida!', 1, CURRENT_TIMESTAMP, false),
(43, 5, 41, 'Eu não recebo glória da parte dos homens;', 1, CURRENT_TIMESTAMP, false),
(43, 5, 42, 'mas bem vos conheço, que não tendes em vós o amor de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 43, 'Eu vim em nome de meu Pai, e não me recebeis; se outro vier em seu próprio nome, a esse recebereis.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 44, 'Como podeis crer, vós que recebeis glória uns dos outros e não buscais a glória que vem do único Deus?', 1, CURRENT_TIMESTAMP, false),
(43, 5, 45, 'Não penseis que eu vos hei de acusar perante o Pai. Há um que vos acusa, Moisés, em quem vós esperais.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 46, 'Pois se crêsseis em Moisés, creríeis em mim; porque de mim ele escreveu.', 1, CURRENT_TIMESTAMP, false),
(43, 5, 47, 'Mas, se não credes nos escritos, como crereis nas minhas palavras?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 1, 'Depois disto partiu Jesus para o outro lado do mar da Galiléia, também chamado de Tiberíades.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 2, 'E seguia-o uma grande multidão, porque via os sinais que operava sobre os enfermos.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 3, 'Subiu, pois, Jesus ao monte e sentou-se ali com seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 4, 'Ora, a páscoa, a festa dos judeus, estava próxima.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 5, 'Então Jesus, levantando os olhos, e vendo que uma grande multidão vinha ter com ele, disse a Felipe: Onde compraremos pão, para estes comerem?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 6, 'Mas dizia isto para o experimentar; pois ele bem sabia o que ia fazer.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 7, 'Respondeu-lhe Felipe: Duzentos denários de pão não lhes bastam, para que cada um receba um pouco.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 8, 'Ao que lhe disse um dos seus discípulos, André, irmão de Simão Pedro:', 1, CURRENT_TIMESTAMP, false),
(43, 6, 9, 'Está aqui um rapaz que tem cinco pães de cevada e dois peixinhos; mas que é isto para tantos?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 10, 'Disse Jesus: Fazei reclinar-se o povo. Ora, naquele lugar havia muita relva. Reclinaram-se aí, pois, os homens em número de quase cinco mil.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 11, 'Jesus, então, tomou os pães e, havendo dado graças, repartiu-os pelos que estavam reclinados; e de igual modo os peixes, quanto eles queriam.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 12, 'E quando estavam saciados, disse aos seus discípulos: Recolhei os pedaços que sobejaram, para que nada se perca.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 13, 'Recolheram-nos, pois e encheram doze cestos de pedaços dos cinco pães de cevada, que sobejaram aos que haviam comido.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 14, 'Vendo, pois, aqueles homens o sinal que Jesus operara, diziam: este é verdadeiramente o profeta que havia de vir ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 15, 'Percebendo, pois, Jesus que estavam prestes a vir e levá-lo à força para o fazerem rei, tornou a retirar-se para o monte, ele sozinho.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 16, 'Ao cair da tarde, desceram os seus discípulos ao mar;', 1, CURRENT_TIMESTAMP, false),
(43, 6, 17, 'e, entrando num barco, atravessavam o mar em direção a Cafarnaum; enquanto isso, escurecera e Jesus ainda não tinha vindo ter com eles;', 1, CURRENT_TIMESTAMP, false),
(43, 6, 18, 'ademais, o mar se empolava, porque soprava forte vento.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 19, 'Tendo, pois, remado uns vinte e cinco ou trinta estádios, viram a Jesus andando sobre o mar e aproximando-se do barco; e ficaram atemorizados.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 20, 'Mas ele lhes disse: Sou eu; não temais.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 21, 'Então eles de boa mente o receberam no barco; e logo o barco chegou à terra para onde iam.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 22, 'No dia seguinte, a multidão que ficara no outro lado do mar, sabendo que não houvera ali senão um barquinho, e que Jesus não embarcara nele com seus discípulos, mas que estes tinham ido sós', 1, CURRENT_TIMESTAMP, false),
(43, 6, 23, '{contudo, outros barquinhos haviam chegado a Tiberíades para perto do lugar onde comeram o pão, havendo o Senhor dado graças};', 1, CURRENT_TIMESTAMP, false),
(43, 6, 24, 'quando, pois, viram que Jesus não estava ali nem os seus discípulos, entraram eles também nos barcos, e foram a Cafarnaum, em busca de Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 25, 'E, achando-o no outro lado do mar, perguntaram-lhe: Rabi, quando chegaste aqui?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 26, 'Respondeu-lhes Jesus: Em verdade, em verdade vos digo que me buscais, não porque vistes sinais, mas porque comestes do pão e vos saciastes.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 27, 'Trabalhai, não pela comida que perece, mas pela comida que permanece para a vida eterna, a qual o Filho do homem vos dará; pois neste, Deus, o Pai, imprimiu o seu selo.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 28, 'Pergutaram-lhe, pois: Que havemos de fazer para praticarmos as obras de Deus?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 29, 'Jesus lhes respondeu: A obra de Deus é esta: Que creiais naquele que ele enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 30, 'Perguntaram-lhe, então: Que sinal, pois, fazes tu, para que o vejamos e te creiamos? Que operas tu?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 31, 'Nossos pais comeram o maná no deserto, como está escrito: Do céu deu-lhes pão a comer.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 32, 'Respondeu-lhes Jesus: Em verdade, em verdade vos digo: Não foi Moisés que vos deu o pão do céu; mas meu Pai vos dá o verdadeiro pão do céu.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 33, 'Porque o pão de Deus é aquele que desce do céu e dá vida ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 34, 'Disseram-lhe, pois: Senhor, dá-nos sempre desse pão.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 35, 'Declarou-lhes Jesus. Eu sou o pão da vida; aquele que vem a mim, de modo algum terá fome, e quem crê em mim jamais terá sede.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 36, 'Mas como já vos disse, vós me tendes visto, e contudo não credes.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 37, 'Todo o que o Pai me dá virá a mim; e o que vem a mim de maneira nenhuma o lançarei fora.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 38, 'Porque eu desci do céu, não para fazer a minha vontade, mas a vontade daquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 39, 'E a vontade do que me enviou é esta: Que eu não perca nenhum de todos aqueles que me deu, mas que eu o ressuscite no último dia.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 40, 'Porquanto esta é a vontade de meu Pai: Que todo aquele que vê o Filho e crê nele, tenha a vida eterna; e eu o ressuscitarei no último dia.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 41, 'Murmuravam, pois, dele os judeus, porque dissera: Eu sou o pão que desceu do céu;', 1, CURRENT_TIMESTAMP, false),
(43, 6, 42, 'e perguntavam: Não é Jesus, o filho de José, cujo pai e mãe nós conhecemos? Como, pois, diz agora: Desci do céu?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 43, 'Respondeu-lhes Jesus: Não murmureis entre vós.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 44, 'Ninguém pode vir a mim, se o Pai que me enviou não o trouxer; e eu o ressuscitarei no último dia.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 45, 'Está escrito nos profetas: E serão todos ensinados por Deus. Portanto todo aquele que do Pai ouviu e aprendeu vem a mim.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 46, 'Não que alguém tenha visto o Pai, senão aquele que é vindo de Deus; só ele tem visto o Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 47, 'Em verdade, em verdade vos digo: Aquele que crê tem a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 48, 'Eu sou o pão da vida.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 49, 'Vossos pais comeram o maná no deserto e morreram.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 50, 'Este é o pão que desce do céu, para que o que dele comer não morra.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 51, 'Eu sou o pão vivo que desceu do céu; se alguém comer deste pão, viverá para sempre; e o pão que eu darei pela vida do mundo é a minha carne.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 52, 'Disputavam, pois, os judeus entre si, dizendo: Como pode este dar-nos a sua carne a comer?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 53, 'Disse-lhes Jesus: Em verdade, em verdade vos digo: Se não comerdes a carne do Filho do homem, e não beberdes o seu sangue, não tereis vida em vós mesmos.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 54, 'Quem come a minha carne e bebe o meu sangue tem a vida eterna; e eu o ressuscitarei no último dia.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 55, 'Porque a minha carne verdadeiramente é comida, e o meu sangue verdadeiramente é bebida.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 56, 'Quem come a minha carne e bebe o meu sangue permanece em mim e eu nele.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 57, 'Assim como o Pai, que vive, me enviou, e eu vivo pelo Pai, assim, quem de mim se alimenta, também viverá por mim.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 58, 'Este é o pão que desceu do céu; não é como o caso de vossos pais, que comeram o maná e morreram; quem comer este pão viverá para sempre.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 59, 'Estas coisas falou Jesus quando ensinava na sinagoga em Cafarnaum.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 60, 'Muitos, pois, dos seus discípulos, ouvindo isto, disseram: Duro é este discurso; quem o pode ouvir?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 61, 'Mas, sabendo Jesus em si mesmo que murmuravam disto os seus discípulos, disse-lhes: Isto vos escandaliza?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 62, 'Que seria, pois, se vísseis subir o Filho do homem para onde primeiro estava?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 63, 'O espírito é o que vivifica, a carne para nada aproveita; as palavras que eu vos tenho dito são espírito e são vida.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 64, 'Mas há alguns de vós que não crêem. Pois Jesus sabia, desde o princípio, quem eram os que não criam, e quem era o que o havia de entregar.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 65, 'E continuou: Por isso vos disse que ninguém pode vir a mim, se pelo Pai lhe não for concedido.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 66, 'Por causa disso muitos dos seus discípulos voltaram para trás e não andaram mais com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 67, 'Perguntou então Jesus aos doze: Quereis vós também retirar-vos?', 1, CURRENT_TIMESTAMP, false),
(43, 6, 68, 'Respondeu-lhe Simão Pedro: Senhor, para quem iremos nós? Tu tens as palavras da vida eterna.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 69, 'E nós já temos crido e bem sabemos que tu és o Santo de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 70, 'Respondeu-lhes Jesus: Não vos escolhi a vós os doze? Contudo um de vós é o diabo.', 1, CURRENT_TIMESTAMP, false),
(43, 6, 71, 'Referia-se a Judas, filho de Simão Iscariotes; porque era ele o que o havia de entregar, sendo um dos doze.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 1, 'Depois disto andava Jesus pela Galiléia; pois não queria andar pela Judéia, porque os judeus procuravam matá-lo.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 2, 'Ora, estava próxima a festa dos judeus, a dos tabernáculos.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 3, 'Disseram-lhe, então, seus irmãos: Retira-te daqui e vai para a Judéia, para que também os teus discípulos vejam as obras que fazes.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 4, 'Porque ninguém faz coisa alguma em oculto, quando procura ser conhecido. Já que fazes estas coisas, manifesta-te ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 5, 'Pois nem seus irmãos criam nele.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 6, 'Disse-lhes, então, Jesus: Ainda não é chegado o meu tempo; mas o vosso tempo sempre está presente.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 7, 'O mundo não vos pode odiar; mas ele me odeia a mim, porquanto dele testifico que as suas obras são más.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 8, 'Subi vós à festa; eu não subo ainda a esta festa, porque ainda não é chegado o meu tempo.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 9, 'E, havendo-lhes dito isto, ficou na Galiléia.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 10, 'Mas quando seus irmãos já tinham subido à festa, então subiu ele também, não publicamente, mas como em secreto.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 11, 'Ora, os judeus o procuravam na festa, e perguntavam: Onde está ele?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 12, 'E era grande a murmuração a respeito dele entre as multidões. Diziam alguns: Ele é bom. Mas outros diziam: não, antes engana o povo.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 13, 'Todavia ninguém falava dele abertamente, por medo dos judeus.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 14, 'Estando, pois, a festa já em meio, subiu Jesus ao templo e começou a ensinar.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 15, 'Então os judeus se admiravam, dizendo: Como sabe este letras, sem ter estudado?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 16, 'Respondeu-lhes Jesus: A minha doutrina não é minha, mas daquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 17, 'Se alguém quiser fazer a vontade de Deus, há de saber se a doutrina é dele, ou se eu falo por mim mesmo.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 18, 'Quem fala por si mesmo busca a sua própria glória; mas o que busca a glória daquele que o enviou, esse é verdadeiro, e não há nele injustiça.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 19, 'Não vos deu Moisés a lei? no entanto nenhum de vós cumpre a lei. Por que procurais matar-me?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 20, 'Respondeu a multidão: Tens demônio; quem procura matar-te?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 21, 'Replicou-lhes Jesus: Uma só obra fiz, e todos vós admirais por causa disto.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 22, 'Moisés vos ordenou a circuncisão {não que fosse de Moisés, mas dos pais}, e no sábado circuncidais um homem.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 23, 'Ora, se um homem recebe a circuncisão no sábado, para que a lei de Moisés não seja violada, como vos indignais contra mim, porque no sábado tornei um homem inteiramente são?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 24, 'Não julgueis pela aparência mas julgai segundo o reto juízo.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 25, 'Diziam então alguns dos de Jerusalém: Não é este o que procuram matar?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 26, 'E eis que ele está falando abertamente, e nada lhe dizem. Será que as autoridades realmente o reconhecem como o Cristo?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 27, 'Entretanto sabemos donde este é; mas, quando vier o Cristo, ninguém saberá donde ele é.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 28, 'Jesus, pois, levantou a voz no templo e ensinava, dizendo: Sim, vós me conheceis, e sabeis donde sou; contudo eu não vim de mim mesmo, mas aquele que me enviou é verdadeiro, o qual vós não conheceis.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 29, 'Mas eu o conheço, porque dele venho, e ele me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 30, 'Procuravam, pois, prendê-lo; mas ninguém lhe deitou as mãos, porque ainda não era chegada a sua hora.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 31, 'Contudo muitos da multidão creram nele, e diziam: Será que o Cristo, quando vier, fará mais sinais do que este tem feito?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 32, 'Os fariseus ouviram a multidão murmurar estas coisas a respeito dele; e os principais sacerdotes e os fariseus mandaram guardas para o prenderem.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 33, 'Disse, pois, Jesus: Ainda um pouco de tempo estou convosco, e depois vou para aquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 34, 'Vós me buscareis, e não me achareis; e onde eu estou, vós não podeis vir.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 35, 'Disseram, pois, os judeus uns aos outros: Para onde irá ele, que não o acharemos? Irá, porventura, à Dispersão entre os gregos, e ensinará os gregos?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 36, 'Que palavra é esta que disse: Buscar-me-eis, e não me achareis; e, Onde eu estou, vós não podeis vir?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 37, 'Ora, no seu último dia, o grande dia da festa, Jesus pôs-se em pé e clamou, dizendo: Se alguém tem sede, venha a mim e beba.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 38, 'Quem crê em mim, como diz a Escritura, do seu interior correrão rios de água viva.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 39, 'Ora, isto ele disse a respeito do Espírito que haviam de receber os que nele cressem; pois o Espírito ainda não fora dado, porque Jesus ainda não tinha sido glorificado.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 40, 'Então alguns dentre o povo, ouvindo essas palavras, diziam: Verdadeiramente este é o profeta.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 41, 'Outros diziam: Este é o Cristo; mas outros replicavam: Vem, pois, o Cristo da Galiléia?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 42, 'Não diz a Escritura que o Cristo vem da descendência de Davi, e de Belém, a aldeia donde era Davi?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 43, 'Assim houve uma dissensão entre o povo por causa dele.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 44, 'Alguns deles queriam prendê-lo; mas ninguém lhe pôs as mãos.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 45, 'Os guardas, pois, foram ter com os principais dos sacerdotes e fariseus, e estes lhes perguntaram: Por que não o trouxestes?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 46, 'Responderam os guardas: Nunca homem algum falou assim como este homem.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 47, 'Replicaram-lhes, pois, os fariseus: Também vós fostes enganados?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 48, 'Creu nele porventura alguma das autoridades, ou alguém dentre os fariseus?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 49, 'Mas esta multidão, que não sabe a lei, é maldita.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 50, 'Nicodemos, um deles, que antes fora ter com Jesus, perguntou-lhes:', 1, CURRENT_TIMESTAMP, false),
(43, 7, 51, 'A nossa lei, porventura, julga um homem sem primeiro ouvi-lo e ter conhecimento do que ele faz?', 1, CURRENT_TIMESTAMP, false),
(43, 7, 52, 'Responderam-lhe eles: És tu também da Galiléia? Examina e vê que da Galiléia não surge profeta.', 1, CURRENT_TIMESTAMP, false),
(43, 7, 53, '{E cada um foi para sua casa.}', 1, CURRENT_TIMESTAMP, false),
(43, 8, 1, 'Mas Jesus foi para o Monte das Oliveiras.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 2, 'Pela manhã cedo voltou ao templo, e todo o povo vinha ter com ele; e Jesus, sentando-se o ensinava.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 3, 'Então os escribas e fariseus trouxeram-lhe uma mulher apanhada em adultério; e pondo-a no meio,', 1, CURRENT_TIMESTAMP, false),
(43, 8, 4, 'disseram-lhe: Mestre, esta mulher foi apanhada em flagrante adultério.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 5, 'Ora, Moisés nos ordena na lei que as tais sejam apedrejadas. Tu, pois, que dizes?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 6, 'Isto diziam eles, tentando-o, para terem de que o acusar. Jesus, porém, inclinando-se, começou a escrever no chão com o dedo.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 7, 'Mas, como insistissem em perguntar-lhe, ergueu-se e disse-lhes: Aquele dentre vós que está sem pecado seja o primeiro que lhe atire uma pedra.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 8, 'E, tornando a inclinar-se, escrevia na terra.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 9, 'Quando ouviram isto foram saindo um a um, a começar pelos mais velhos, até os últimos; ficou só Jesus, e a mulher ali em pé.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 10, 'Então, erguendo-se Jesus e não vendo a ninguém senão a mulher, perguntou-lhe: Mulher, onde estão aqueles teus acusadores? Ninguém te condenou?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 11, 'Respondeu ela: Ninguém, Senhor. E disse-lhe Jesus: Nem eu te condeno; vai-te, e não peques mais.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 12, 'Então Jesus tornou a falar-lhes, dizendo: Eu sou a luz do mundo; quem me segue de modo algum andará em trevas, mas terá a luz da vida.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 13, 'Disseram-lhe, pois, os fariseus: Tu dás testemunho de ti mesmo; o teu testemunho não é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 14, 'Respondeu-lhes Jesus: Ainda que eu dou testemunho de mim mesmo, o meu testemunho é verdadeiro; porque sei donde vim, e para onde vou; mas vós não sabeis donde venho, nem para onde vou.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 15, 'Vós julgais segundo a carne; eu a ninguém julgo.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 16, 'E, mesmo que eu julgue, o meu juízo é verdadeiro; porque não sou eu só, mas eu e o Pai que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 17, 'Ora, na vossa lei está escrito que o testemunho de dois homens é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 18, 'Sou eu que dou testemunho de mim mesmo, e o Pai que me enviou, também dá testemunho de mim.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 19, 'Perguntavam-lhe, pois: Onde está teu pai? Jesus respondeu: Não me conheceis a mim, nem a meu Pai; se vós me conhecêsseis a mim, também conheceríeis a meu Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 20, 'Essas palavras proferiu Jesus no lugar do tesouro, quando ensinava no templo; e ninguém o prendeu, porque ainda não era chegada a sua hora.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 21, 'Disse-lhes, pois, Jesus outra vez: Eu me retiro; buscar-me-eis, e morrereis no vosso pecado. Para onde eu vou, vós não podeis ir.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 22, 'Então diziam os judeus: Será que ele vai suicidar-se, pois diz: Para onde eu vou, vós não podeis ir?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 23, 'Disse-lhes ele: Vós sois de baixo, eu sou de cima; vós sois deste mundo, eu não sou deste mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 24, 'Por isso vos disse que morrereis em vossos pecados; porque, se não crerdes que eu sou, morrereis em vossos pecados.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 25, 'Perguntavam-lhe então: Quem és tu? Respondeu-lhes Jesus: Exatamente o que venho dizendo que sou.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 26, 'Muitas coisas tenho que dizer e julgar acerca de vós; mas aquele que me enviou é verdadeiro; e o que dele ouvi, isso falo ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 27, 'Eles não perceberam que lhes falava do Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 28, 'Prosseguiu, pois, Jesus: Quando tiverdes levantado o Filho do homem, então conhecereis que eu sou, e que nada faço de mim mesmo; mas como o Pai me ensinou, assim falo.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 29, 'E aquele que me enviou está comigo; não me tem deixado só; porque faço sempre o que é do seu agrado.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 30, 'Falando ele estas coisas, muitos creram nele.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 31, 'Dizia, pois, Jesus aos judeus que nele creram: Se vós permanecerdes na minha palavra, verdadeiramente sois meus discípulos;', 1, CURRENT_TIMESTAMP, false),
(43, 8, 32, 'e conhecereis a verdade, e a verdade vos libertará.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 33, 'Responderam-lhe: Somos descendentes de Abraão, e nunca fomos escravos de ninguém; como dizes tu: Sereis livres?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 34, 'Replicou-lhes Jesus: Em verdade, em verdade vos digo que todo aquele que comete pecado é escravo do pecado.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 35, 'Ora, o escravo não fica para sempre na casa; o filho fica para sempre.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 36, 'Se, pois, o Filho vos libertar, verdadeiramente sereis livres.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 37, 'Bem sei que sois descendência de Abraão; contudo, procurais matar-me, porque a minha palavra não encontra lugar em vós.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 38, 'Eu falo do que vi junto de meu Pai; e vós fazeis o que também ouvistes de vosso pai.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 39, 'Responderam-lhe: Nosso pai é Abraão. Disse-lhes Jesus: Se sois filhos de Abraão, fazei as obras de Abraão.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 40, 'Mas agora procurais matar-me, a mim que vos falei a verdade que de Deus ouvi; isso Abraão não fez.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 41, 'Vós fazeis as obras de vosso pai. Replicaram-lhe eles: Nós não somos nascidos de prostituição; temos um Pai, que é Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 42, 'Respondeu-lhes Jesus: Se Deus fosse o vosso Pai, vós me amaríeis, porque eu saí e vim de Deus; pois não vim de mim mesmo, mas ele me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 43, 'Por que não compreendeis a minha linguagem? é porque não podeis ouvir a minha palavra.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 44, 'Vós tendes por pai o Diabo, e quereis satisfazer os desejos de vosso pai; ele é homicida desde o princípio, e nunca se firmou na verdade, porque nele não há verdade; quando ele profere mentira, fala do que lhe é próprio; porque é mentiroso, e pai da mentira.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 45, 'Mas porque eu digo a verdade, não me credes.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 46, 'Quem dentre vós me convence de pecado? Se digo a verdade, por que não me credes?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 47, 'Quem é de Deus ouve as palavras de Deus; por isso vós não as ouvis, porque não sois de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 48, 'Responderam-lhe os judeus: Não dizemos com razão que és samaritano, e que tens demônio?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 49, 'Jesus respondeu: Eu não tenho demônio; antes honro a meu Pai, e vós me desonrais.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 50, 'Eu não busco a minha glória; há quem a busque, e julgue.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 51, 'Em verdade, em verdade vos digo que, se alguém guardar a minha palavra, nunca verá a morte.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 52, 'Disseram-lhe os judeus: Agora sabemos que tens demônios. Abraão morreu, e também os profetas; e tu dizes: Se alguém guardar a minha palavra, nunca provará a morte!', 1, CURRENT_TIMESTAMP, false),
(43, 8, 53, 'Porventura és tu maior do que nosso pai Abraão, que morreu? Também os profetas morreram; quem pretendes tu ser?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 54, 'Respondeu Jesus: Se eu me glorificar a mim mesmo, a minha glória não é nada; quem me glorifica é meu Pai, do qual vós dizeis que é o vosso Deus;', 1, CURRENT_TIMESTAMP, false),
(43, 8, 55, 'e vós não o conheceis; mas eu o conheço; e se disser que não o conheço, serei mentiroso como vós; mas eu o conheço, e guardo a sua palavra.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 56, 'Abraão, vosso pai, exultou por ver o meu dia; viu-o, e alegrou-se.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 57, 'Disseram-lhe, pois, os judeus: Ainda não tens cinqüenta anos, e viste Abraão?', 1, CURRENT_TIMESTAMP, false),
(43, 8, 58, 'Respondeu-lhes Jesus: Em verdade, em verdade vos digo que antes que Abraão existisse, eu sou.', 1, CURRENT_TIMESTAMP, false),
(43, 8, 59, 'Então pegaram em pedras para lhe atirarem; mas Jesus ocultou-se, e saiu do templo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 1, 'E passando Jesus, viu um homem cego de nascença.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 2, 'Perguntaram-lhe os seus discípulos: Rabi, quem pecou, este ou seus pais, para que nascesse cego?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 3, 'Respondeu Jesus: Nem ele pecou nem seus pais; mas foi para que nele se manifestem as obras de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 4, 'Importa que façamos as obras daquele que me enviou, enquanto é dia; vem a noite, quando ninguém pode trabalhar.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 5, 'Enquanto estou no mundo, sou a luz do mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 6, 'Dito isto, cuspiu no chão e com a saliva fez lodo, e untou com lodo os olhos do cego,', 1, CURRENT_TIMESTAMP, false),
(43, 9, 7, 'e disse-lhe: Vai, lava-te no tanque de Siloé {que significa Enviado}. E ele foi, lavou-se, e voltou vendo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 8, 'Então os vizinhos e aqueles que antes o tinham visto, quando mendigo, perguntavam: Não é este o mesmo que se sentava a mendigar?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 9, 'Uns diziam: É ele. E outros: Não é, mas se parece com ele. Ele dizia: Sou eu.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 10, 'Perguntaram-lhe, pois: Como se te abriram os olhos?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 11, 'Respondeu ele: O homem que se chama Jesus fez lodo, untou-me os olhos, e disse-me: Vai a Siloé e lava-te. Fui, pois, lavei-me, e fiquei vendo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 12, 'E perguntaram-lhe: Onde está ele? Respondeu: Não sei.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 13, 'Levaram aos fariseus o que fora cego.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 14, 'Ora, era sábado o dia em que Jesus fez o lodo e lhe abriu os olhos.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 15, 'Então os fariseus também se puseram a perguntar-lhe como recebera a vista. Respondeu-lhes ele: Pôs-me lodo sobre os olhos, lavei-me e vejo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 16, 'Por isso alguns dos fariseus diziam: Este homem não é de Deus; pois não guarda o sábado. Diziam outros: Como pode um homem pecador fazer tais sinais? E havia dissensão entre eles.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 17, 'Tornaram, pois, a perguntar ao cego: Que dizes tu a respeito dele, visto que te abriu os olhos? E ele respondeu: É profeta.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 18, 'Os judeus, porém, não acreditaram que ele tivesse sido cego e recebido a vista, enquanto não chamaram os pais do que fora curado,', 1, CURRENT_TIMESTAMP, false),
(43, 9, 19, 'e lhes perguntaram: É este o vosso filho, que dizeis ter nascido cego? Como, pois, vê agora?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 20, 'Responderam seus pais: Sabemos que este é o nosso filho, e que nasceu cego;', 1, CURRENT_TIMESTAMP, false),
(43, 9, 21, 'mas como agora vê, não sabemos; ou quem lhe abriu os olhos, nós não sabemos; perguntai a ele mesmo; tem idade; ele falará por si mesmo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 22, 'Isso disseram seus pais, porque temiam os judeus, porquanto já tinham estes combinado que se alguém confessasse ser Jesus o Cristo, fosse expulso da sinagoga.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 23, 'Por isso é que seus pais disseram: Tem idade, perguntai-lho a ele mesmo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 24, 'Então chamaram pela segunda vez o homem que fora cego, e lhe disseram: Dá glória a Deus; nós sabemos que esse homem é pecador.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 25, 'Respondeu ele: Se é pecador, não sei; uma coisa sei: eu era cego, e agora vejo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 26, 'Perguntaram-lhe pois: Que foi que te fez? Como te abriu os olhos?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 27, 'Respondeu-lhes: Já vo-lo disse, e não atendestes; para que o quereis tornar a ouvir? Acaso também vós quereis tornar-vos discípulos dele?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 28, 'Então o injuriaram, e disseram: Discípulo dele és tu; nós porém, somos discípulos de Moisés.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 29, 'Sabemos que Deus falou a Moisés; mas quanto a este, não sabemos donde é.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 30, 'Respondeu-lhes o homem: Nisto, pois, está a maravilha: não sabeis donde ele é, e entretanto ele me abriu os olhos;', 1, CURRENT_TIMESTAMP, false),
(43, 9, 31, 'sabemos que Deus não ouve a pecadores; mas, se alguém for temente a Deus, e fizer a sua vontade, a esse ele ouve.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 32, 'Desde o princípio do mundo nunca se ouviu que alguém abrisse os olhos a um cego de nascença.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 33, 'Se este não fosse de Deus, nada poderia fazer.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 34, 'Replicaram-lhe eles: Tu nasceste todo em pecados, e vens nos ensinar a nós? E expulsaram-no.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 35, 'Soube Jesus que o haviam expulsado; e achando-o perguntou-lhe: Crês tu no Filho do homem?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 36, 'Respondeu ele: Quem é, senhor, para que nele creia?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 37, 'Disse-lhe Jesus: Já o viste, e é ele quem fala contigo.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 38, 'Disse o homem: Creio, Senhor! E o adorou.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 39, 'Prosseguiu então Jesus: Eu vim a este mundo para juízo, a fim de que os que não vêem vejam, e os que vêem se tornem cegos.', 1, CURRENT_TIMESTAMP, false),
(43, 9, 40, 'Alguns fariseus que ali estavam com ele, ouvindo isso, perguntaram-lhe: Porventura somos nós também cegos?', 1, CURRENT_TIMESTAMP, false),
(43, 9, 41, 'Respondeu-lhes Jesus: Se fosseis cegos, não teríeis pecado; mas como agora dizeis: Nós vemos, permanece o vosso pecado.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 1, 'Em verdade, em verdade vos digo: quem não entra pela porta no aprisco das ovelhas, mas sobe por outra parte, esse é ladrão e salteador.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 2, 'Mas o que entra pela porta é o pastor das ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 3, 'A este o porteiro abre; e as ovelhas ouvem a sua voz; e ele chama pelo nome as suas ovelhas, e as conduz para fora.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 4, 'Depois de conduzir para fora todas as que lhe pertencem, vai adiante delas, e as ovelhas o seguem, porque conhecem a sua voz;', 1, CURRENT_TIMESTAMP, false),
(43, 10, 5, 'mas de modo algum seguirão o estranho, antes fugirão dele, porque não conhecem a voz dos estranhos.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 6, 'Jesus propôs-lhes esta parábola, mas eles não entenderam o que era que lhes dizia.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 7, 'Tornou, pois, Jesus a dizer-lhes: Em verdade, em verdade vos digo: eu sou a porta das ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 8, 'Todos quantos vieram antes de mim são ladrões e salteadores; mas as ovelhas não os ouviram.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 9, 'Eu sou a porta; se alguém entrar a casa; o filho fica entrará e sairá, e achará pastagens.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 10, 'O ladrão não vem senão para roubar, matar e destruir; eu vim para que tenham vida e a tenham em abundância.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 11, 'Eu sou o bom pastor; o bom pastor dá a sua vida pelas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 12, 'Mas o que é mercenário, e não pastor, de quem não são as ovelhas, vendo vir o lobo, deixa as ovelhas e foge; e o lobo as arrebata e dispersa.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 13, 'Ora, o mercenário foge porque é mercenário, e não se importa com as ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 14, 'Eu sou o bom pastor; conheço as minhas ovelhas, e elas me conhecem,', 1, CURRENT_TIMESTAMP, false),
(43, 10, 15, 'assim como o Pai me conhece e eu conheço o Pai; e dou a minha vida pelas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 16, 'Tenho ainda outras ovelhas que não são deste aprisco; a essas também me importa conduzir, e elas ouvirão a minha voz; e haverá um rebanho e um pastor.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 17, 'Por isto o Pai me ama, porque dou a minha vida para a retomar.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 18, 'Ninguém ma tira de mim, mas eu de mim mesmo a dou; tenho autoridade para a dar, e tenho autoridade para retomá-la. Este mandamento recebi de meu Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 19, 'Por causa dessas palavras, houve outra dissensão entre os judeus.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 20, 'E muitos deles diziam: Tem demônio, e perdeu o juízo; por que o escutais?', 1, CURRENT_TIMESTAMP, false),
(43, 10, 21, 'Diziam outros: Essas palavras não são de quem está endemoninhado; pode porventura um demônio abrir os olhos aos cegos?', 1, CURRENT_TIMESTAMP, false),
(43, 10, 22, 'Celebrava-se então em Jerusalém a festa da dedicação. E era inverno.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 23, 'Andava Jesus passeando no templo, no pórtico de Salomão.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 24, 'Rodearam-no, pois, os judeus e lhe perguntavam: Até quando nos deixarás perplexos? Se tu és o Cristo, dize-no-lo abertamente.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 25, 'Respondeu-lhes Jesus: Já vo-lo disse, e não credes. As obras que eu faço em nome de meu Pai, essas dão testemunho de mim.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 26, 'Mas vós não credes, porque não sois das minhas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 27, 'As minhas ovelhas ouvem a minha voz, e eu as conheço, e elas me seguem;', 1, CURRENT_TIMESTAMP, false),
(43, 10, 28, 'eu lhes dou a vida eterna, e jamais perecerão; e ninguém as arrebatará da minha mão.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 29, 'Meu Pai, que mas deu, é maior do que todos; e ninguém pode arrebatá-las da mão de meu Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 30, 'Eu e o Pai somos um.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 31, 'Os judeus pegaram então outra vez em pedras para o apedrejar.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 32, 'Disse-lhes Jesus: Muitas obras boas da parte de meu Pai vos tenho mostrado; por qual destas obras ides apedrejar-me?', 1, CURRENT_TIMESTAMP, false),
(43, 10, 33, 'Responderam-lhe os judeus: Não é por nenhuma obra boa que vamos apedrejar-te, mas por blasfêmia; e porque, sendo tu homem, te fazes Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 34, 'Tornou-lhes Jesus: Não está escrito na vossa lei: Eu disse: Vós sois deuses?', 1, CURRENT_TIMESTAMP, false),
(43, 10, 35, 'Se a lei chamou deuses àqueles a quem a palavra de Deus foi dirigida {e a Escritura não pode ser anulada},', 1, CURRENT_TIMESTAMP, false),
(43, 10, 36, 'àquele a quem o Pai santificou, e enviou ao mundo, dizeis vós: Blasfemas; porque eu disse: Sou Filho de Deus?', 1, CURRENT_TIMESTAMP, false),
(43, 10, 37, 'Se não faço as obras de meu Pai, não me acrediteis.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 38, 'Mas se as faço, embora não me creiais a mim, crede nas obras; para que entendais e saibais que o Pai está em mim e eu no Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 39, 'Outra vez, pois, procuravam prendê-lo; mas ele lhes escapou das mãos.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 40, 'E retirou-se de novo para além do Jordão, para o lugar onde João batizava no princípio; e ali ficou.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 41, 'Muitos foram ter com ele, e diziam: João, na verdade, não fez sinal algum, mas tudo quanto disse deste homem era verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 10, 42, 'E muitos ali creram nele.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 1, 'Ora, estava enfermo um homem chamado Lázaro, de Betânia, aldeia de Maria e de sua irmã Marta.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 2, 'E Maria, cujo irmão Lázaro se achava enfermo, era a mesma que ungiu o Senhor com bálsamo, e lhe enxugou os pés com os seus cabelos.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 3, 'Mandaram, pois, as irmãs dizer a Jesus: Senhor, eis que está enfermo aquele que tu amas.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 4, 'Jesus, porém, ao ouvir isto, disse: Esta enfermidade não é para a morte, mas para glória de Deus, para que o Filho de Deus seja glorificado por ela.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 5, 'Ora, Jesus amava a Marta, e a sua irmã, e a Lázaro.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 6, 'Quando, pois, ouviu que estava enfermo, ficou ainda dois dias no lugar onde se achava.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 7, 'Depois disto, disse a seus discípulos: Vamos outra vez para Judéia.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 8, 'Disseram-lhe eles: Rabi, ainda agora os judeus procuravam apedrejar-te, e voltas para lá?', 1, CURRENT_TIMESTAMP, false),
(43, 11, 9, 'Respondeu Jesus: Não são doze as horas do dia? Se alguém andar de dia, não tropeça, porque vê a luz deste mundo;', 1, CURRENT_TIMESTAMP, false),
(43, 11, 10, 'mas se andar de noite, tropeça, porque nele não há luz.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 11, 'E, tendo assim falado, acrescentou: Lázaro, o nosso amigo, dorme, mas vou despertá-lo do sono.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 12, 'Disseram-lhe, pois, os discípulos: Senhor, se dorme, ficará bom.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 13, 'Mas Jesus falara da sua morte; eles, porém, entenderam que falava do repouso do sono.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 14, 'Então Jesus lhes disse claramente: Lázaro morreu;', 1, CURRENT_TIMESTAMP, false),
(43, 11, 15, 'e, por vossa causa, folgo de que eu lá não estivesse, para que creiais; mas vamos ter com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 16, 'Disse, pois, Tomé, chamado Dídimo, aos seus condiscípulos: Vamos nós também, para morrermos com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 17, 'Chegando pois Jesus, encontrou-o já com quatro dias de sepultura.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 18, 'Ora, Betânia distava de Jerusalém cerca de quinze estádios.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 19, 'E muitos dos judeus tinham vindo visitar Marta e Maria, para as consolar acerca de seu irmão.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 20, 'Marta, pois, ao saber que Jesus chegava, saiu-lhe ao encontro; Maria, porém, ficou sentada em casa.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 21, 'Disse, pois, Marta a Jesus: Senhor, se meu irmão não teria morrido.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 22, 'E mesmo agora sei que tudo quanto pedires a Deus, Deus to concederá.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 23, 'Respondeu-lhe Jesus: Teu irmão há de ressurgir.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 24, 'Disse-lhe Marta: Sei que ele há de ressurgir na ressurreição, no último dia.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 25, 'Declarou-lhe Jesus: Eu sou a ressurreição e a vida; quem crê em mim, ainda que morra, viverá;', 1, CURRENT_TIMESTAMP, false),
(43, 11, 26, 'e todo aquele que vive, e crê em mim, jamais morrerá. Crês isto?', 1, CURRENT_TIMESTAMP, false),
(43, 11, 27, 'Respondeu-lhe Marta: Sim, Senhor, eu creio que tu és o Cristo, o Filho de Deus, que havia de vir ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 28, 'Dito isto, retirou-se e foi chamar em segredo a Maria, sua irmã, e lhe disse: O Mestre está aí, e te chama.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 29, 'Ela, ouvindo isto, levantou-se depressa, e foi ter com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 30, 'Pois Jesus ainda não havia entrado na aldeia, mas estava no lugar onde Marta o encontrara.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 31, 'Então os judeus que estavam com Maria em casa e a consolavam, vendo-a levantar-se apressadamente e sair, seguiram-na, pensando que ia ao sepulcro para chorar ali.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 32, 'Tendo, pois, Maria chegado ao lugar onde Jesus estava, e vendo-a, lançou-se-lhe aos pés e disse: Senhor, se tu estiveras aqui, meu irmão não teria morrido.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 33, 'Jesus, pois, quando a viu chorar, e chorarem também os judeus que com ela vinham, comoveu-se em espírito, e perturbou-se,', 1, CURRENT_TIMESTAMP, false),
(43, 11, 34, 'e perguntou: Onde o puseste? Responderam-lhe: Senhor, vem e vê.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 35, 'Jesus chorou.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 36, 'Disseram então os judeus: Vede como o amava.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 37, 'Mas alguns deles disseram: Não podia ele, que abriu os olhos ao cego, fazer também que este não morreste?', 1, CURRENT_TIMESTAMP, false),
(43, 11, 38, 'Jesus, pois, comovendo-se outra vez, profundamente, foi ao sepulcro; era uma gruta, e tinha uma pedra posta sobre ela.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 39, 'Disse Jesus: Tirai a pedra. Marta, irmã do defunto, disse-lhe: Senhor, já cheira mal, porque está morto há quase quatro dias.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 40, 'Respondeu-lhe Jesus: Não te disse que, se creres, verás a glória de Deus?', 1, CURRENT_TIMESTAMP, false),
(43, 11, 41, 'Tiraram então a pedra. E Jesus, levantando os olhos ao céu, disse: Pai, graças te dou, porque me ouviste.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 42, 'Eu sabia que sempre me ouves; mas por causa da multidão que está em redor é que assim falei, para que eles creiam que tu me enviaste.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 43, 'E, tendo dito isso, clamou em alta voz: Lázaro, vem para fora!', 1, CURRENT_TIMESTAMP, false),
(43, 11, 44, 'Saiu o que estivera morto, ligados os pés e as mãos com faixas, e o seu rosto envolto num lenço. Disse-lhes Jesus: Desligai-o e deixai-o ir.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 45, 'Muitos, pois, dentre os judeus que tinham vindo visitar Maria, e que tinham visto o que Jesus fizera, creram nele.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 46, 'Mas alguns deles foram ter com os fariseus e disseram-lhes o que Jesus tinha feito.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 47, 'Então os principais sacerdotes e os fariseus reuniram o sinédrio e diziam: Que faremos? porquanto este homem vem operando muitos sinais.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 48, 'Se o deixarmos assim, todos crerão nele, e virão os romanos, e nos tirarão tanto o nosso lugar como a nossa nação.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 49, 'Um deles, porém, chamado Caifás, que era sumo sacerdote naquele ano, disse-lhes: Vós nada sabeis,', 1, CURRENT_TIMESTAMP, false),
(43, 11, 50, 'nem considerais que vos convém que morra um só homem pelo povo, e que não pereça a nação toda.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 51, 'Ora, isso não disse ele por si mesmo; mas, sendo o sumo sacerdote naquele ano, profetizou que Jesus havia de morrer pela nação,', 1, CURRENT_TIMESTAMP, false),
(43, 11, 52, 'e não somente pela nação, mas também para congregar num só corpo os filhos de Deus que estão dispersos.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 53, 'Desde aquele dia, pois, tomavam conselho para o matarem.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 54, 'De sorte que Jesus já não andava manifestamente entre os judeus, mas retirou-se dali para a região vizinha ao deserto, a uma cidade chamada Efraim; e ali demorou com os seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 55, 'Ora, estava próxima a páscoa dos judeus, e dessa região subiram muitos a Jerusalém, antes da páscoa, para se purificarem.', 1, CURRENT_TIMESTAMP, false),
(43, 11, 56, 'Buscavam, pois, a Jesus e diziam uns aos outros, estando no templo: Que vos parece? Não virá ele à festa?', 1, CURRENT_TIMESTAMP, false),
(43, 11, 57, 'Ora, os principais sacerdotes e os fariseus tinham dado ordem que, se alguém soubesse onde ele estava, o denunciasse, para que o prendessem.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 1, 'Veio, pois, Jesus seis dias antes da páscoa, a Betânia, onde estava Lázaro, a quem ele ressuscitara dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 2, 'Deram-lhe ali uma ceia; Marta servia, e Lázaro era um dos que estavam à mesa com ele.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 3, 'Então Maria, tomando uma libra de bálsamo de nardo puro, de grande preço, ungiu os pés de Jesus, e os enxugou com os seus cabelos; e encheu-se a casa do cheiro do bálsamo.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 4, 'Mas Judas Iscariotes, um dos seus discípulos, aquele que o havia de trair disse:', 1, CURRENT_TIMESTAMP, false),
(43, 12, 5, 'Por que não se vendeu este bálsamo por trezentos denários e não se deu aos pobres?', 1, CURRENT_TIMESTAMP, false),
(43, 12, 6, 'Ora, ele disse isto, não porque tivesse cuidado dos pobres, mas porque era ladrão e, tendo a bolsa, subtraía o que nela se lançava.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 7, 'Respondeu, pois Jesus: Deixa-a; para o dia da minha preparação para a sepultura o guardou;', 1, CURRENT_TIMESTAMP, false),
(43, 12, 8, 'porque os pobres sempre os tendes convosco; mas a mim nem sempre me tendes.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 9, 'E grande número dos judeus chegou a saber que ele estava ali: e afluiram, não só por causa de Jesus mas também para verem a Lázaro, a quem ele ressuscitara dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 10, 'Mas os principais sacerdotes deliberaram matar também a Lázaro;', 1, CURRENT_TIMESTAMP, false),
(43, 12, 11, 'porque muitos, por causa dele, deixavam os judeus e criam em Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 12, 'No dia seguinte, as grandes multidões que tinham vindo à festa, ouvindo dizer que Jesus vinha a Jerusalém,', 1, CURRENT_TIMESTAMP, false),
(43, 12, 13, 'tomaram ramos de palmeiras, e saíram-lhe ao encontro, e clamavam: Hosana! Bendito o que vem em nome do Senhor! Bendito o rei de Israel!', 1, CURRENT_TIMESTAMP, false),
(43, 12, 14, 'E achou Jesus um jumentinho e montou nele, conforme está escrito:', 1, CURRENT_TIMESTAMP, false),
(43, 12, 15, 'Não temas, ó filha de Sião; eis que vem teu Rei, montado sobre o filho de uma jumenta.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 16, 'Os seus discípulos, porém, a princípio não entenderam isto; mas quando Jesus foi glorificado, então eles se lembraram de que estas coisas estavam escritas a respeito dele, e de que assim lhe fizeram.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 17, 'Dava-lhe, pois, testemunho a multidão que estava com ele quando chamara a Lázaro da sepultura e o ressuscitara dentre os mortos;', 1, CURRENT_TIMESTAMP, false),
(43, 12, 18, 'e foi por isso que a multidão lhe saiu ao encontro, por ter ouvido que ele fizera este sinal.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 19, 'De sorte que os fariseus disseram entre si: Vedes que nada aproveitais? eis que o mundo inteiro vai após ele.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 20, 'Ora, entre os que tinham subido a adorar na festa havia alguns gregos.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 21, 'Estes, pois, dirigiram-se a Felipe, que era de Betsaida da Galiléia, e rogaram-lhe, dizendo: Senhor, queríamos ver a Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 22, 'Felipe foi dizê-lo a André, e então André e Felipe foram dizê-lo a Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 23, 'Respondeu-lhes Jesus: É chegada a hora de ser glorificado o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 24, 'Em verdade, em verdade vos digo: Se o grão de trigo caindo na terra não morrer, fica ele só; mas se morrer, dá muito fruto.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 25, 'Quem ama a sua vida, perdê-la-á; e quem neste mundo odeia a sua vida, guardá-la-á para a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 26, 'Se alguém me quiser servir, siga-me; e onde eu estiver, ali estará também o meu servo; se alguém me servir, o Pai o honrará.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 27, 'Agora a minha alma está perturbada; e que direi eu? Pai, salva-me desta hora? Mas para isto vim a esta hora.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 28, 'Pai, glorifica o teu nome. Veio, então, do céu esta voz: Já o tenho glorificado, e outra vez o glorificarei.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 29, 'A multidão, pois, que ali estava, e que a ouvira, dizia ter havido um trovão; outros diziam: Um anjo lhe falou.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 30, 'Respondeu Jesus: Não veio esta voz por minha causa, mas por causa de vós.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 31, 'Agora é o juízo deste mundo; agora será expulso o príncipe deste mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 32, 'E eu, quando for levantado da terra, todos atrairei a mim.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 33, 'Isto dizia, significando de que modo havia de morrer.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 34, 'Respondeu-lhe a multidão: Nós temos ouvido da lei que o Cristo permanece para sempre; e como dizes tu: Importa que o Filho do homem seja levantado? Quem é esse Filho do homem?', 1, CURRENT_TIMESTAMP, false),
(43, 12, 35, 'Disse-lhes então Jesus: Ainda por um pouco de tempo a luz está entre vós. Andai enquanto tendes a luz, para que as trevas não vos apanhem; pois quem anda nas trevas não sabe para onde vai.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 36, 'Enquanto tendes a luz, crede na luz, para que vos torneis filhos da luz. Havendo Jesus assim falado, retirou-se e escondeu-se deles.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 37, 'E embora tivesse operado tantos sinais diante deles, não criam nele;', 1, CURRENT_TIMESTAMP, false),
(43, 12, 38, 'para que se cumprisse a palavra do profeta Isaías: Senhor, quem creu em nossa pregação? e aquem foi revelado o braço do Senhor?', 1, CURRENT_TIMESTAMP, false),
(43, 12, 39, 'Por isso não podiam crer, porque, como disse ainda Isaías:', 1, CURRENT_TIMESTAMP, false),
(43, 12, 40, 'Cegou-lhes os olhos e endureceu-lhes o coração, para que não vejam com os olhos e entendam com o coração, e se convertam, e eu os cure.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 41, 'Estas coisas disse Isaías, porque viu a sua glória, e dele falou.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 42, 'Contudo, muitos dentre as próprias autoridades creram nele; mas por causa dos fariseus não o confessavam, para não serem expulsos da sinagoga;', 1, CURRENT_TIMESTAMP, false),
(43, 12, 43, 'porque amaram mais a glória dos homens do que a glória de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 44, 'Clamou Jesus, dizendo: Quem crê em mim, crê, não em mim, mas naquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 45, 'E quem me vê a mim, vê aquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 46, 'Eu, que sou a luz, vim ao mundo, para que todo aquele que crê em mim não permaneça nas trevas.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 47, 'E, se alguém ouvir as minhas palavras, e não as guardar, eu não o julgo; pois eu vim, não para julgar o mundo, mas para salvar o mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 48, 'Quem me rejeita, e não recebe as minhas palavras, já tem quem o julgue; a palavra que tenho pregado, essa o julgará no último dia.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 49, 'Porque eu não falei por mim mesmo; mas o Pai, que me enviou, esse me deu mandamento quanto ao que dizer e como falar.', 1, CURRENT_TIMESTAMP, false),
(43, 12, 50, 'E sei que o seu mandamento é vida eterna. Aquilo, pois, que eu falo, falo-o exatamente como o Pai me ordenou.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 1, 'Antes da festa da páscoa, sabendo Jesus que era chegada a sua hora de passar deste mundo para o Pai, e havendo amado os seus que estavam no mundo, amou-os até o fim.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 2, 'Enquanto ceavam, tendo já o Diabo posto no coração de Judas, filho de Simão Iscariotes, que o traísse,', 1, CURRENT_TIMESTAMP, false),
(43, 13, 3, 'Jesus, sabendo que o Pai lhe entregara tudo nas mãos, e que viera de Deus e para Deus voltava,', 1, CURRENT_TIMESTAMP, false),
(43, 13, 4, 'levantou-se da ceia, tirou o manto e, tomando uma toalha, cingiu-se.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 5, 'Depois deitou água na bacia e começou a lavar os pés aos discípulos, e a enxugar-lhos com a toalha com que estava cingido.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 6, 'Chegou, pois, a Simão Pedro, que lhe disse: Senhor, lavas-me os pés a mim?', 1, CURRENT_TIMESTAMP, false),
(43, 13, 7, 'Respondeu-lhe Jesus: O que eu faço, tu não o sabes agora; mas depois o entenderás.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 8, 'Tornou-lhe Pedro: Nunca me lavarás os pés. Replicou-lhe Jesus: Se eu não te lavar, não tens parte comigo.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 9, 'Disse-lhe Simão Pedro: Senhor, não somente os meus pés, mas também as mãos e a cabeça.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 10, 'Respondeu-lhe Jesus: Aquele que se banhou não necessita de lavar senão os pés, pois no mais está todo limpo; e vós estais limpos, mas não todos.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 11, 'Pois ele sabia quem o estava traindo; por isso disse: Nem todos estais limpos.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 12, 'Ora, depois de lhes ter lavado os pés, tomou o manto, tornou a reclinar-se à mesa e perguntou-lhes: Entendeis o que vos tenho feito?', 1, CURRENT_TIMESTAMP, false),
(43, 13, 13, 'Vós me chamais Mestre e Senhor; e dizeis bem, porque eu o sou.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 14, 'Ora, se eu, o Senhor e Mestre, vos lavei os pés, também vós deveis lavar os pés uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 15, 'Porque eu vos dei exemplo, para que, como eu vos fiz, façais vós também.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 16, 'Em verdade, em verdade vos digo: Não é o servo maior do que o seu senhor, nem o enviado maior do que aquele que o enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 17, 'Se sabeis estas coisas, bem-aventurados sois se as praticardes.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 18, 'Não falo de todos vós; eu conheço aqueles que escolhi; mas para que se cumprisse a escritura: O que comia do meu pão, levantou contra mim o seu calcanhar.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 19, 'Desde já no-lo digo, antes que suceda, para que, quando suceder, creiais que eu sou.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 20, 'Em verdade, em verdade vos digo: Quem receber aquele que eu enviar, a mim me recebe; e quem me recebe a mim, recebe aquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 21, 'Tendo Jesus dito isto, turbou-se em espírito, e declarou: Em verdade, em verdade vos digo que um de vós me há de trair.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 22, 'Os discípulos se entreolhavam, perplexos, sem saber de quem ele falava.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 23, 'Ora, achava-se reclinado sobre o peito de Jesus um de seus discípulos, aquele a quem Jesus amava.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 24, 'A esse, pois, fez Simão Pedro sinal, e lhe pediu: Pergunta-lhe de quem é que fala.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 25, 'Aquele discípulo, recostando-se assim ao peito de Jesus, perguntou-lhe: Senhor, quem é?', 1, CURRENT_TIMESTAMP, false),
(43, 13, 26, 'Respondeu Jesus: É aquele a quem eu der o pedaço de pão molhado. Tendo, pois, molhado um bocado de pão, deu-o a Judas, filho de Simão Iscariotes.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 27, 'E, logo após o bocado, entrou nele Satanás. Disse-lhe, pois, Jesus: O que fazes, faze-o depressa.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 28, 'E nenhum dos que estavam à mesa percebeu a que propósito lhe disse isto;', 1, CURRENT_TIMESTAMP, false),
(43, 13, 29, 'pois, como Judas tinha a bolsa, pensavam alguns que Jesus lhe queria dizer: Compra o que nos é necessário para a festa; ou, que desse alguma coisa aos pobres.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 30, 'Então ele, tendo recebido o bocado saiu logo. E era noite.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 31, 'Tendo ele, pois, saído, disse Jesus: Agora é glorificado o Filho do homem, e Deus é glorificado nele;', 1, CURRENT_TIMESTAMP, false),
(43, 13, 32, 'se Deus é glorificado nele, também Deus o glorificará em si mesmo, e logo o há de glorificar.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 33, 'Filhinhos, ainda por um pouco estou convosco. Procurar-me-eis; e, como eu disse aos judeus, também a vós o digo agora: Para onde eu vou, não podeis vós ir.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 34, 'Um novo mandamento vos dou: que vos ameis uns aos outros; assim como eu vos amei a vós, que também vós vos ameis uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 35, 'Nisto conhecerão todos que sois meus discípulos, se tiverdes amor uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 36, 'Perguntou-lhe Simão Pedro: Senhor, para onde vais? Respondeu Jesus; Para onde eu vou, não podes agora seguir-me; mais tarde, porém, me seguirás.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 37, 'Disse-lhe Pedro: Por que não posso seguir-te agora? Por ti darei a minha vida.', 1, CURRENT_TIMESTAMP, false),
(43, 13, 38, 'Respondeu Jesus: Darás a tua vida por mim? Em verdade, em verdade te digo: Não cantará o galo até que me tenhas negado três vezes.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 1, 'Não se turbe o vosso coração; credes em Deus, crede também em mim.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 2, 'Na casa de meu Pai há muitas moradas; se não fosse assim, eu vo-lo teria dito; vou preparar-vos lugar.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 3, 'E, se eu for e vos preparar lugar, virei outra vez, e vos tomarei para mim mesmo, para que onde eu estiver estejais vós também.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 4, 'E para onde eu vou vós conheceis o caminho.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 5, 'Disse-lhe Tomé: Senhor, não sabemos para onde vais; e como podemos saber o caminho?', 1, CURRENT_TIMESTAMP, false),
(43, 14, 6, 'Respondeu-lhe Jesus: Eu sou o caminho, e a verdade, e a vida; ninguém vem ao Pai, senão por mim.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 7, 'Se vós me conhecêsseis a mim, também conheceríeis a meu Pai; e já desde agora o conheceis, e o tendes visto.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 8, 'Disse-lhe Felipe: Senhor, mostra-nos o Pai, e isso nos basta.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 9, 'Respondeu-lhe Jesus: Há tanto tempo que estou convosco, e ainda não me conheces, Felipe? Quem me viu a mim, viu o Pai; como dizes tu: Mostra-nos o Pai?', 1, CURRENT_TIMESTAMP, false),
(43, 14, 10, 'Não crês tu que eu estou no Pai, e que o Pai está em mim? As palavras que eu vos digo, não as digo por mim mesmo; mas o Pai, que permanece em mim, é quem faz as suas obras.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 11, 'Crede-me que eu estou no Pai, e que o Pai está em mim; crede ao menos por causa das mesmas obras.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 12, 'Em verdade, em verdade vos digo: Aquele que crê em mim, esse também fará as obras que eu faço, e as fará maiores do que estas; porque eu vou para o Pai;', 1, CURRENT_TIMESTAMP, false),
(43, 14, 13, 'e tudo quanto pedirdes em meu nome, eu o farei, para que o Pai seja glorificado no Filho.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 14, 'Se me pedirdes alguma coisa em meu nome, eu a farei.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 15, 'Se me amardes, guardareis os meus mandamentos.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 16, 'E eu rogarei ao Pai, e ele vos dará outro Ajudador, para que fique convosco para sempre.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 17, 'a saber, o Espírito da verdade, o qual o mundo não pode receber; porque não o vê nem o conhece; mas vós o conheceis, porque ele habita convosco, e estará em vós.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 18, 'Não vos deixarei órfãos; voltarei a vós.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 19, 'Ainda um pouco, e o mundo não me verá mais; mas vós me vereis, porque eu vivo, e vós vivereis.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 20, 'Naquele dia conhecereis que estou em meu Pai, e vós em mim, e eu em vós.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 21, 'Aquele que tem os meus mandamentos e os guarda, esse é o que me ama; e aquele que me ama será amado de meu Pai, e eu o amarei, e me manifestarei a ele.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 22, 'Perguntou-lhe Judas {não o Iscariotes}: O que houve, Senhor, que te hás de manifestar a nós, e não ao mundo?', 1, CURRENT_TIMESTAMP, false),
(43, 14, 23, 'Respondeu-lhe Jesus: Se alguém me amar, guardará a minha palavra; e meu Pai o amará, e viremos a ele, e faremos nele morada.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 24, 'Quem não me ama, não guarda as minhas palavras; ora, a palavra que estais ouvindo não é minha, mas do Pai que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 25, 'Estas coisas vos tenho falado, estando ainda convosco.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 26, 'Mas o Ajudador, o Espírito Santo a quem o Pai enviará em meu nome, esse vos ensinará todas as coisas, e vos fará lembrar de tudo quanto eu vos tenho dito.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 27, 'Deixo-vos a paz, a minha paz vos dou; eu não vo-la dou como o mundo a dá. Não se turbe o vosso coração, nem se atemorize.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 28, 'Ouvistes que eu vos disse: Vou, e voltarei a vós. Se me amásseis, alegrar-vos-íeis de que eu vá para o Pai; porque o Pai é maior do que eu.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 29, 'Eu vo-lo disse agora, antes que aconteça, para que, quando acontecer, vós creiais.', 1, CURRENT_TIMESTAMP, false),
(43, 14, 30, 'Já não falarei muito convosco, porque vem o príncipe deste mundo, e ele nada tem em mim;', 1, CURRENT_TIMESTAMP, false),
(43, 14, 31, 'mas, assim como o Pai me ordenou, assim mesmo faço, para que o mundo saiba que eu amo o Pai. Levantai-vos, vamo-nos daqui.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 1, 'Eu sou a videira verdadeira, e meu Pai é o viticultor.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 2, 'Toda vara em mim que não dá fruto, ele a corta; e toda vara que dá fruto, ele a limpa, para que dê mais fruto.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 3, 'Vós já estais limpos pela palavra que vos tenho falado.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 4, 'Permanecei em mim, e eu permanecerei em vós; como a vara de si mesma não pode dar fruto, se não permanecer na videira, assim também vós, se não permanecerdes em mim.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 5, 'Eu sou a videira; vós sois as varas. Quem permanece em mim e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 6, 'Quem não permanece em mim é lançado fora, como a vara, e seca; tais varas são recolhidas, lançadas no fogo e queimadas.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 7, 'Se vós permanecerdes em mim, e as minhas palavras permanecerem em vós, pedi o que quiserdes, e vos será feito.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 8, 'Nisto é glorificado meu Pai, que deis muito fruto; e assim sereis meus discípulos.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 9, 'Como o Pai me amou, assim também eu vos amei; permanecei no meu amor.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 10, 'Se guardardes os meus mandamentos, permanecereis no meu amor; do mesmo modo que eu tenho guardado os mandamentos de meu Pai, e permaneço no seu amor.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 11, 'Estas coisas vos tenho dito, para que o meu gozo permaneça em vós, e o vosso gozo seja completo.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 12, 'O meu mandamento é este: Que vos ameis uns aos outros, assim como eu vos amei.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 13, 'Ninguém tem maior amor do que este, de dar alguém a sua vida pelos seus amigos.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 14, 'Vós sois meus amigos, se fizerdes o que eu vos mando.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 15, 'Já não vos chamo servos, porque o servo não sabe o que faz o seu senhor; mas chamei-vos amigos, porque tudo quanto ouvi de meu Pai vos dei a conhecer.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 16, 'Vós não me escolhestes a mim mas eu vos escolhi a vós, e vos designei, para que vades e deis frutos, e o vosso fruto permaneça, a fim de que tudo quanto pedirdes ao Pai em meu nome, ele vo-lo conceda.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 17, 'Isto vos mando: que vos ameis uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 18, 'Se o mundo vos odeia, sabei que, primeiro do que a vós, me odiou a mim.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 19, 'Se fôsseis do mundo, o mundo amaria o que era seu; mas, porque não sois do mundo, antes eu vos escolhi do mundo, por isso é que o mundo vos odeia.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 20, 'Lembrai-vos da palavra que eu vos disse: Não é o servo maior do que o seu senhor. Se a mim me perseguiram, também vos perseguirão a vós; se guardaram a minha palavra, guardarão também a vossa.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 21, 'Mas tudo isto vos farão por causa do meu nome, porque não conhecem aquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 22, 'Se eu não viera e não lhes falara, não teriam pecado; agora, porém, não têm desculpa do seu pecado.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 23, 'Aquele que me odeia a mim, odeia também a meu Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 24, 'Se eu entre eles não tivesse feito tais obras, quais nenhum outro fez, não teriam pecado; mas agora, não somente viram, mas também odiaram tanto a mim como a meu Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 25, 'Mas isto é para que se cumpra a palavra que está escrita na sua lei: Odiaram-me sem causa.', 1, CURRENT_TIMESTAMP, false),
(43, 15, 26, 'Quando vier o Ajudador, que eu vos enviarei da parte do Pai, o Espírito da verdade, que do Pai procede, esse dará testemunho de mim;', 1, CURRENT_TIMESTAMP, false),
(43, 15, 27, 'e também vós dareis testemunho, porque estais comigo desde o princípio.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 1, 'Tenho-vos dito estas coisas para que não vos escandalizeis.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 2, 'Expulsar-vos-ão das sinagogas; ainda mais, vem a hora em que qualquer que vos matar julgará prestar um serviço a Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 3, 'E isto vos farão, porque não conheceram ao Pai nem a mim.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 4, 'Mas tenho-vos dito estas coisas, a fim de que, quando chegar aquela hora, vos lembreis de que eu vo-las tinha dito. Não vo-las disse desde o princípio, porque estava convosco.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 5, 'Agora, porém, vou para aquele que me enviou; e nenhum de vós me pergunta: Para onde vais?', 1, CURRENT_TIMESTAMP, false),
(43, 16, 6, 'Antes, porque vos disse isto, o vosso coração se encheu de tristeza.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 7, 'Todavia, digo-vos a verdade, convém-vos que eu vá; pois se eu não for, o Ajudador não virá a vós; mas, se eu for, vo-lo enviarei.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 8, 'E quando ele vier, convencerá o mundo do pecado, da justiça e do juízo:', 1, CURRENT_TIMESTAMP, false),
(43, 16, 9, 'do pecado, porque não crêem em mim;', 1, CURRENT_TIMESTAMP, false),
(43, 16, 10, 'da justiça, porque vou para meu Pai, e não me vereis mais,', 1, CURRENT_TIMESTAMP, false),
(43, 16, 11, 'e do juízo, porque o príncipe deste mundo já está julgado.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 12, 'Ainda tenho muito que vos dizer; mas vós não o podeis suportar agora.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 13, 'Quando vier, porém, aquele, o Espírito da verdade, ele vos guiará a toda a verdade; porque não falará por si mesmo, mas dirá o que tiver ouvido, e vos anunciará as coisas vindouras.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 14, 'Ele me glorificará, porque receberá do que é meu, e vo-lo anunciará.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 15, 'Tudo quanto o Pai tem é meu; por isso eu vos disse que ele, recebendo do que é meu, vo-lo anunciará.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 16, 'Um pouco, e já não me vereis; e outra vez um pouco, e ver-me-eis.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 17, 'Então alguns dos seus discípulos perguntaram uns para os outros: Que é isto que nos diz? Um pouco, e não me vereis; e outra vez um pouco, e ver-me-eis; e: Porquanto vou para o Pai?', 1, CURRENT_TIMESTAMP, false),
(43, 16, 18, 'Diziam pois: Que quer dizer isto: Um pouco? Não compreendemos o que ele está dizendo.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 19, 'Percebeu Jesus que o queriam interrogar, e disse-lhes: Indagais entre vós acerca disto que disse: Um pouco, e não me vereis; e outra vez um pouco, e ver-me-eis?', 1, CURRENT_TIMESTAMP, false),
(43, 16, 20, 'Em verdade, em verdade, vos digo que vós chorareis e vos lamentareis, mas o mundo se alegrará; vós estareis tristes, porém a vossa tristeza se converterá em alegria.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 21, 'A mulher, quando está para dar à luz, sente tristeza porque é chegada a sua hora; mas, depois de ter dado à luz a criança, já não se lembra da aflição, pelo gozo de haver um homem nascido ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 22, 'Assim também vós agora, na verdade, tendes tristeza; mas eu vos tornarei a ver, e alegrar-se-á o vosso coração, e a vossa alegria ninguém vo-la tirará.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 23, 'Naquele dia nada me perguntareis. Em verdade, em verdade vos digo que tudo quanto pedirdes ao Pai, ele vo-lo concederá em meu nome.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 24, 'Até agora nada pedistes em meu nome; pedi, e recebereis, para que o vosso gozo seja completo.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 25, 'Disse-vos estas coisas por figuras; chega, porém, a hora em que vos não falarei mais por figuras, mas abertamente vos falarei acerca do Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 26, 'Naquele dia pedireis em meu nome, e não vos digo que eu rogarei por vós ao Pai;', 1, CURRENT_TIMESTAMP, false),
(43, 16, 27, 'pois o Pai mesmo vos ama; visto que vós me amastes e crestes que eu saí de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 28, 'Saí do Pai, e vim ao mundo; outra vez deixo o mundo, e vou para o Pai.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 29, 'Disseram os seus discípulos: Eis que agora falas abertamente, e não por figura alguma.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 30, 'Agora conhecemos que sabes todas as coisas, e não necessitas de que alguém te interrogue. Por isso cremos que saíste de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 31, 'Respondeu-lhes Jesus: Credes agora?', 1, CURRENT_TIMESTAMP, false),
(43, 16, 32, 'Eis que vem a hora, e já é chegada, em que vós sereis dispersos cada um para o seu lado, e me deixareis só; mas não estou só, porque o Pai está comigo.', 1, CURRENT_TIMESTAMP, false),
(43, 16, 33, 'Tenho-vos dito estas coisas, para que em mim tenhais paz. No mundo tereis tribulações; mas tende bom ânimo, eu venci o mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 1, 'Depois de assim falar, Jesus, levantando os olhos ao céu, disse: Pai, é chegada a hora; glorifica a teu Filho, para que também o Filho te glorifique;', 1, CURRENT_TIMESTAMP, false),
(43, 17, 2, 'assim como lhe deste autoridade sobre toda a carne, para que dê a vida eterna a todos aqueles que lhe tens dado.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 3, 'E a vida eterna é esta: que te conheçam a ti, como o único Deus verdadeiro, e a Jesus Cristo, aquele que tu enviaste.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 4, 'Eu te glorifiquei na terra, completando a obra que me deste para fazer.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 5, 'Agora, pois, glorifica-me tu, ó Pai, junto de ti mesmo, com aquela glória que eu tinha contigo antes que o mundo existisse.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 6, 'Manifestei o teu nome aos homens que do mundo me deste. Eram teus, e tu mos deste; e guardaram a tua palavra.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 7, 'Agora sabem que tudo quanto me deste provém de ti;', 1, CURRENT_TIMESTAMP, false),
(43, 17, 8, 'porque eu lhes dei as palavras que tu me deste, e eles as receberam, e verdadeiramente conheceram que saí de ti, e creram que tu me enviaste.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 9, 'Eu rogo por eles; não rogo pelo mundo, mas por aqueles que me tens dado, porque são teus;', 1, CURRENT_TIMESTAMP, false),
(43, 17, 10, 'todas as minhas coisas são tuas, e as tuas coisas são minhas; e neles sou glorificado.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 11, 'Eu não estou mais no mundo; mas eles estão no mundo, e eu vou para ti. Pai santo, guarda-os no teu nome, o qual me deste, para que eles sejam um, assim como nós.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 12, 'Enquanto eu estava com eles, eu os guardava no teu nome que me deste; e os conservei, e nenhum deles se perdeu, senão o filho da perdição, para que se cumprisse a Escritura.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 13, 'Mas agora vou para ti; e isto falo no mundo, para que eles tenham a minha alegria completa em si mesmos.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 14, 'Eu lhes dei a tua palavra; e o mundo os odiou, porque não são do mundo, assim como eu não sou do mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 15, 'Não rogo que os tires do mundo, mas que os guardes do Maligno.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 16, 'Eles não são do mundo, assim como eu não sou do mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 17, 'Santifica-os na verdade, a tua palavra é a verdade.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 18, 'Assim como tu me enviaste ao mundo, também eu os enviarei ao mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 19, 'E por eles eu me santifico, para que também eles sejam santificados na verdade.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 20, 'E rogo não somente por estes, mas também por aqueles que pela sua palavra hão de crer em mim;', 1, CURRENT_TIMESTAMP, false),
(43, 17, 21, 'para que todos sejam um; assim como tu, ó Pai, és em mim, e eu em ti, que também eles sejam um em nós; para que o mundo creia que tu me enviaste.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 22, 'E eu lhes dei a glória que a mim me deste, para que sejam um, como nós somos um;', 1, CURRENT_TIMESTAMP, false),
(43, 17, 23, 'eu neles, e tu em mim, para que eles sejam perfeitos em unidade, a fim de que o mundo conheça que tu me enviaste, e que os amaste a eles, assim como me amaste a mim.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 24, 'Pai, desejo que onde eu estou, estejam comigo também aqueles que me tens dado, para verem a minha glória, a qual me deste; pois que me amaste antes da fundação do mundo.', 1, CURRENT_TIMESTAMP, false),
(43, 17, 25, 'Pai justo, o mundo não te conheceu, mas eu te conheço; conheceram que tu me enviaste;', 1, CURRENT_TIMESTAMP, false),
(43, 17, 26, 'e eu lhes fiz conhecer o teu nome, e lho farei conhecer ainda; para que haja neles aquele amor com que me amaste, e também eu neles esteja.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 1, 'Tendo Jesus dito isto, saiu com seus discípulos para o outro lado do ribeiro de Cedrom, onde havia um jardim, e com eles ali entrou.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 2, 'Ora, Judas, que o traía, também conhecia aquele lugar, porque muitas vezes Jesus se reunira ali com os discípulos.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 3, 'Tendo, pois, Judas tomado a corte e uns guardas da parte dos principais sacerdotes e fariseus, chegou ali com lanternas archotes e armas.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 4, 'Sabendo, pois, Jesus tudo o que lhe havia de suceder, adiantou-se e perguntou-lhes: A quem buscais?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 5, 'Responderam-lhe: A Jesus, o nazareno. Disse-lhes Jesus: Sou eu. E Judas, que o traía, também estava com eles.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 6, 'Quando Jesus lhes disse: Sou eu, recuaram, e caíram por terra.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 7, 'Tornou-lhes então a perguntar: A quem buscais? e responderam: A Jesus, o nazareno.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 8, 'Replicou-lhes Jesus: Já vos disse que sou eu; se, pois, é a mim que buscais, deixai ir estes;', 1, CURRENT_TIMESTAMP, false),
(43, 18, 9, 'para que se cumprisse a palavra que dissera: Dos que me tens dado, nenhum deles perdi.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 10, 'Então Simão Pedro, que tinha uma espada, desembainhou-a e feriu o servo do sumo sacerdote, cortando-lhe a orelha direita. O nome do servo era Malco.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 11, 'Disse, pois, Jesus a Pedro: Mete a tua espada na bainha; não hei de beber o cálice que o Pai me deu?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 12, 'Então a escolta, e o comandante, e os guardas dos judeus prenderam a Jesus, e o maniataram.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 13, 'E conduziram-no primeiramente a Anás; pois era sogro de Caifás, sumo sacerdote naquele ano.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 14, 'Ora, Caifás era quem aconselhara aos judeus que convinha morrer um homem pelo povo.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 15, 'Simão Pedro e outro discípulo seguiam a Jesus. Este discípulo era conhecido do sumo sacerdote, e entrou com Jesus no pátio do sumo sacerdote,', 1, CURRENT_TIMESTAMP, false),
(43, 18, 16, 'enquanto Pedro ficava da parte de fora, à porta. Saiu, então, o outro discípulo que era conhecido do sumo sacerdote, falou à porteira, e levou Pedro para dentro.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 17, 'Então a porteira perguntou a Pedro: Não és tu também um dos discípulos deste homem? Respondeu ele: Não sou.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 18, 'Ora, estavam ali os servos e os guardas, que tinham acendido um braseiro e se aquentavam, porque fazia frio; e também Pedro estava ali em pé no meio deles, aquentando-se.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 19, 'Então o sumo sacerdote interrogou Jesus acerca dos seus discípulos e da sua doutrina.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 20, 'Respondeu-lhe Jesus: Eu tenho falado abertamente ao mundo; eu sempre ensinei nas sinagogas e no templo, onde todos os judeus se congregam, e nada falei em oculto.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 21, 'Por que me perguntas a mim? pergunta aos que me ouviram o que é que lhes falei; eis que eles sabem o que eu disse.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 22, 'E, havendo ele dito isso, um dos guardas que ali estavam deu uma bofetada em Jesus, dizendo: É assim que respondes ao sumo sacerdote?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 23, 'Respondeu-lhe Jesus: Se falei mal, dá testemunho do mal; mas, se bem, por que me feres?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 24, 'Então Anás o enviou, maniatado, a Caifás, o sumo sacerdote.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 25, 'E Simão Pedro ainda estava ali, aquentando-se. Perguntaram-lhe, pois: Não és também tu um dos seus discípulos? Ele negou, e disse: Não sou.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 26, 'Um dos servos do sumo sacerdote, parente daquele a quem Pedro cortara a orelha, disse: Não te vi eu no jardim com ele?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 27, 'Pedro negou outra vez, e imediatamente o galo cantou.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 28, 'Depois conduziram Jesus da presença de Caifás para o pretório; era de manhã cedo; e eles não entraram no pretório, para não se contaminarem, mas poderem comer a páscoa.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 29, 'Então Pilatos saiu a ter com eles, e perguntou: Que acusação trazeis contra este homem?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 30, 'Responderam-lhe: Se ele não fosse malfeitor, não to entregaríamos.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 31, 'Disse-lhes, então, Pilatos: Tomai-o vós, e julgai-o segundo a vossa lei. Disseram-lhe os judeus: A nós não nos é lícito tirar a vida a ninguém.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 32, 'Isso foi para que se cumprisse a palavra que dissera Jesus, significando de que morte havia de morrer.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 33, 'Pilatos, pois, tornou a entrar no pretório, chamou a Jesus e perguntou-lhe: És tu o rei dos judeus?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 34, 'Respondeu Jesus: Dizes isso de ti mesmo, ou foram outros que to disseram de mim?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 35, 'Replicou Pilatos: Porventura sou eu judeu? O teu povo e os principais sacerdotes entregaram-te a mim; que fizeste?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 36, 'Respondeu Jesus: O meu reino não é deste mundo; se o meu reino fosse deste mundo, pelejariam os meus servos, para que eu não fosse entregue aos judeus; entretanto o meu reino não é daqui.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 37, 'Perguntou-lhe, pois, Pilatos: Logo tu és rei? Respondeu Jesus: Tu dizes que eu sou rei. Eu para isso nasci, e para isso vim ao mundo, a fim de dar testemunho da verdade. Todo aquele que é da verdade ouve a minha voz.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 38, 'Perguntou-lhe Pilatos: Que é a verdade? E dito isto, de novo saiu a ter com os judeus, e disse-lhes: Não acho nele crime algum.', 1, CURRENT_TIMESTAMP, false),
(43, 18, 39, 'Tendes, porém, por costume que eu vos solte alguém por ocasião da páscoa; quereis, pois, que vos solte o rei dos judeus?', 1, CURRENT_TIMESTAMP, false),
(43, 18, 40, 'Então todos tornaram a clamar dizendo: Este não, mas Barrabás. Ora, Barrabás era salteador.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 1, 'Nisso, pois, Pilatos tomou a Jesus, e mandou açoitá-lo.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 2, 'E os soldados, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça, e lhe vestiram um manto de púrpura;', 1, CURRENT_TIMESTAMP, false),
(43, 19, 3, 'e chegando-se a ele, diziam: Salve, rei dos judeus! e davam-lhe bofetadas.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 4, 'Então Pilatos saiu outra vez, e disse-lhes: Eis aqui vo-lo trago fora, para que saibais que não acho nele crime algum.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 5, 'Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura. E disse-lhes Pilatos: Eis o homem!', 1, CURRENT_TIMESTAMP, false),
(43, 19, 6, 'Quando o viram os principais sacerdotes e os guardas, clamaram, dizendo: Crucifica-o! Crucifica-o! Disse-lhes Pilatos: Tomai-o vós, e crucificai-o; porque nenhum crime acho nele.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 7, 'Responderam-lhe os judeus: Nós temos uma lei, e segundo esta lei ele deve morrer, porque se fez Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 8, 'Ora, Pilatos, quando ouviu esta palavra, mais atemorizado ficou;', 1, CURRENT_TIMESTAMP, false),
(43, 19, 9, 'e entrando outra vez no pretório, perguntou a Jesus: Donde és tu? Mas Jesus não lhe deu resposta.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 10, 'Disse-lhe, então, Pilatos: Não me respondes? não sabes que tenho autoridade para te soltar, e autoridade para te crucificar?', 1, CURRENT_TIMESTAMP, false),
(43, 19, 11, 'Respondeu-lhe Jesus: Nenhuma autoridade terias sobre mim, se de cima não te fora dado; por isso aquele que me entregou a ti, maior pecado tem.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 12, 'Daí em diante Pilatos procurava soltá-lo; mas os judeus clamaram: Se soltares a este, não és amigo de César; todo aquele que se faz rei é contra César.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 13, 'Pilatos, pois, quando ouviu isto, trouxe Jesus para fora e sentou-se no tribunal, no lugar chamado Pavimento, e em hebraico Gabatá.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 14, 'Ora, era a preparação da páscoa, e cerca da hora sexta. E disse aos judeus: Eis o vosso rei.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 15, 'Mas eles clamaram: Tira-o! tira-o! crucifica-o! Disse-lhes Pilatos: Hei de crucificar o vosso rei? responderam, os principais sacerdotes: Não temos rei, senão César.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 16, 'Então lho entregou para ser crucificado.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 17, 'Tomaram, pois, a Jesus; e ele, carregando a sua própria cruz, saiu para o lugar chamado Caveira, que em hebraico se chama Gólgota,', 1, CURRENT_TIMESTAMP, false),
(43, 19, 18, 'onde o crucificaram, e com ele outros dois, um de cada lado, e Jesus no meio.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 19, 'E Pilatos escreveu também um título, e o colocou sobre a cruz; e nele estava escrito: JESUS O NAZARENO, O REI DOS JUDEUS.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 20, 'Muitos dos judeus, pois, leram este título; porque o lugar onde Jesus foi crucificado era próximo da cidade; e estava escrito em hebraico, latim e grego.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 21, 'Diziam então a Pilatos os principais sacerdotes dos judeus: Não escrevas: O rei dos judeus; mas que ele disse: Sou rei dos judeus.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 22, 'Respondeu Pilatos: O que escrevi, escrevi.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 23, 'Tendo, pois, os soldados crucificado a Jesus, tomaram as suas vestes, e fizeram delas quatro partes, para cada soldado uma parte. Tomaram também a túnica; ora a túnica não tinha costura, sendo toda tecida de alto a baixo.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 24, 'Pelo que disseram uns aos outros: Não a rasguemos, mas lancemos sortes sobre ela, para ver de quem será {para que se cumprisse a escritura que diz: Repartiram entre si as minhas vestes, e lançaram sortes}. E, de fato, os soldados assim fizeram.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 25, 'Estavam em pé, junto à cruz de Jesus, sua mãe, e a irmã de sua mãe, e Maria, mulher de Clôpas, e Maria Madalena.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 26, 'Ora, Jesus, vendo ali sua mãe, e ao lado dela o discípulo a quem ele amava, disse a sua mãe: Mulher, eis aí o teu filho.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 27, 'Então disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua casa.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 28, 'Depois, sabendo Jesus que todas as coisas já estavam consumadas, para que se cumprisse a Escritura, disse: Tenho sede.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 29, 'Estava ali um vaso cheio de vinagre. Puseram, pois, numa cana de hissopo uma esponja ensopada de vinagre, e lha chegaram à boca.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 30, 'Então Jesus, depois de ter tomado o vinagre, disse: está consumado. E, inclinando a cabeça, entregou o espírito.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 31, 'Ora, os judeus, como era a preparação, e para que no sábado não ficassem os corpos na cruz, pois era grande aquele dia de sábado, rogaram a Pilatos que se lhes quebrassem as pernas, e fossem tirados dali.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 32, 'Foram então os soldados e, na verdade, quebraram as pernas ao primeiro e ao outro que com ele fora crucificado;', 1, CURRENT_TIMESTAMP, false),
(43, 19, 33, 'mas vindo a Jesus, e vendo que já estava morto, não lhe quebraram as pernas;', 1, CURRENT_TIMESTAMP, false),
(43, 19, 34, 'contudo um dos soldados lhe furou o lado com uma lança, e logo saiu sangue e água.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 35, 'E é quem viu isso que dá testemunho, e o seu testemunho é verdadeiro; e sabe que diz a verdade, para que também vós creiais.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 36, 'Porque isto aconteceu para que se cumprisse a escritura: Nenhum dos seus ossos será quebrado.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 37, 'Também há outra escritura que diz: Olharão para aquele que traspassaram.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 38, 'Depois disto, José de Arimatéia, que era discípulo de Jesus, embora oculto por medo dos judeus, rogou a Pilatos que lhe permitisse tirar o corpo de Jesus; e Pilatos lho permitiu. Então foi e o tirou.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 39, 'E Nicodemos, aquele que anteriormente viera ter com Jesus de noite, foi também, levando cerca de cem libras duma mistura de mirra e aloés.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 40, 'Tomaram, pois, o corpo de Jesus, e o envolveram em panos de linho com as especiarias, como os judeus costumavam fazer na preparação para a sepultura.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 41, 'No lugar onde Jesus foi crucificado havia um jardim, e nesse jardim um sepulcro novo, em que ninguém ainda havia sido posto.', 1, CURRENT_TIMESTAMP, false),
(43, 19, 42, 'Ali, pois, por ser a véspera do sábado dos judeus, e por estar perto aquele sepulcro, puseram a Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 1, 'No primeiro dia da semana Maria Madalena foi ao sepulcro de madrugada, sendo ainda escuro, e viu que a pedra fora removida do sepulcro.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 2, 'Correu, pois, e foi ter com Simão Pedro, e o outro discípulo, a quem Jesus amava, e disse-lhes: Tiraram do sepulcro o Senhor, e não sabemos onde o puseram.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 3, 'Saíram então Pedro e o outro discípulo e foram ao sepulcro.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 4, 'Corriam os dois juntos, mas o outro discípulo correu mais ligeiro do que Pedro, e chegou primeiro ao sepulcro;', 1, CURRENT_TIMESTAMP, false),
(43, 20, 5, 'e, abaixando-se viu os panos de linho ali deixados, todavia não entrou.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 6, 'Chegou, pois, Simão Pedro, que o seguia, e entrou no sepulcro e viu os panos de linho ali deixados,', 1, CURRENT_TIMESTAMP, false),
(43, 20, 7, 'e que o lenço, que estivera sobre a cabeça de Jesus, não estava com os panos, mas enrolado num lugar à parte.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 8, 'Então entrou também o outro discípulo, que chegara primeiro ao sepulcro, e viu e creu.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 9, 'Porque ainda não entendiam a escritura, que era necessário que ele ressurgisse dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 10, 'Tornaram, pois, os discípulos para casa.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 11, 'Maria, porém, estava em pé, diante do sepulcro, a chorar. Enquanto chorava, abaixou-se a olhar para dentro do sepulcro,', 1, CURRENT_TIMESTAMP, false),
(43, 20, 12, 'e viu dois anjos vestidos de branco sentados onde jazera o corpo de Jesus, um à cabeceira e outro aos pés.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 13, 'E perguntaram-lhe eles: Mulher, por que choras? Respondeu-lhes: Porque tiraram o meu Senhor, e não sei onde o puseram.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 14, 'Ao dizer isso, voltou-se para trás, e viu a Jesus ali em pé, mas não sabia que era Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 15, 'Perguntou-lhe Jesus: Mulher, por que choras? A quem procuras? Ela, julgando que fosse o jardineiro, respondeu-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 16, 'Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe em hebraico: Raboni!-que quer dizer, Mestre.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 17, 'Disse-lhe Jesus: Deixa de me tocar, porque ainda não subi ao Pai; mas vai a meus irmãos e dize-lhes que eu subo para meu Pai e vosso Pai, meu Deus e vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 18, 'E foi Maria Madalena anunciar aos discípulos: Vi o Senhor!-e que ele lhe dissera estas coisas.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 19, 'Chegada, pois, a tarde, naquele dia, o primeiro da semana, e estando os discípulos reunidos com as portas cerradas por medo dos judeus, chegou Jesus, pôs-se no meio e disse-lhes: Paz seja convosco.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 20, 'Dito isto, mostrou-lhes as mãos e o lado. Alegraram-se, pois, os discípulos ao verem o Senhor.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 21, 'Disse-lhes, então, Jesus segunda vez: Paz seja convosco; assim como o Pai me enviou, também eu vos envio a vós.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 22, 'E havendo dito isso, assoprou sobre eles, e disse-lhes: Recebei o Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 23, 'Àqueles a quem perdoardes os pecados, são-lhes perdoados; e àqueles a quem os retiverdes, são-lhes retidos.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 24, 'Ora, Tomé, um dos doze, chamado Dídimo, não estava com eles quando veio Jesus.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 25, 'Diziam-lhe, pois, ou outros discípulos: Vimos o Senhor. Ele, porém, lhes respondeu: Se eu não vir o sinal dos cravos nas mãos, e não meter a mão no seu lado, de maneira nenhuma crerei.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 26, 'Oito dias depois estavam os discípulos outra vez ali reunidos, e Tomé com eles. Chegou Jesus, estando as portas fechadas, pôs-se no meio deles e disse: Paz seja convosco.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 27, 'Depois disse a Tomé: Chega aqui o teu dedo, e vê as minhas mãos; chega a tua mão, e mete-a no meu lado; e não mais sejas incrédulo, mas crente.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 28, 'Respondeu-lhe Tomé: Senhor meu, e Deus meu!', 1, CURRENT_TIMESTAMP, false),
(43, 20, 29, 'Disse-lhe Jesus: Porque me viste, creste? Bem-aventurados os que não viram e creram.', 1, CURRENT_TIMESTAMP, false),
(43, 20, 30, 'Jesus, na verdade, operou na presença de seus discípulos ainda muitos outros sinais que não estão escritos neste livro;', 1, CURRENT_TIMESTAMP, false),
(43, 20, 31, 'estes, porém, estão escritos para que creiais que Jesus é o Cristo, o Filho de Deus, e para que, crendo, tenhais vida em seu nome.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 1, 'Depois disto manifestou-se Jesus outra vez aos discípulos junto do mar de Tiberíades; e manifestou-se deste modo:', 1, CURRENT_TIMESTAMP, false),
(43, 21, 2, 'Estavam juntos Simão Pedro, Tomé, chamado Dídimo, Natanael, que era de Caná da Galiléia, os filhos de Zebedeu, e outros dois dos seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 3, 'Disse-lhes Simão Pedro: Vou pescar. Responderam-lhe: Nós também vamos contigo. Saíram e entraram no barco; e naquela noite nada apanharam.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 4, 'Mas ao romper da manhã, Jesus se apresentou na praia; todavia os discípulos não sabiam que era ele.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 5, 'Disse-lhes, pois, Jesus: Filhos, não tendes nada que comer? Responderam-lhe: Não.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 6, 'Disse-lhes ele: Lançai a rede à direita do barco, e achareis. Lançaram-na, pois, e já não a podiam puxar por causa da grande quantidade de peixes.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 7, 'Então aquele discípulo a quem Jesus amava disse a Pedro: Senhor. Quando, pois, Simão Pedro ouviu que era o Senhor, cingiu-se com a túnica, porque estava despido, e lançou-se ao mar;', 1, CURRENT_TIMESTAMP, false),
(43, 21, 8, 'mas os outros discípulos vieram no barquinho, puxando a rede com os peixes, porque não estavam distantes da terra senão cerca de duzentos côvados.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 9, 'Ora, ao saltarem em terra, viram ali brasas, e um peixe posto em cima delas, e pão.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 10, 'Disse-lhes Jesus: Trazei alguns dos peixes que agora apanhastes.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 11, 'Entrou Simão Pedro no barco e puxou a rede para terra, cheia de cento e cinqüenta e três grandes peixes; e, apesar de serem tantos, não se rompeu a rede.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 12, 'Disse-lhes Jesus: Vinde, comei. Nenhum dos discípulos ousava perguntar-lhe: Quem és tu? sabendo que era o Senhor.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 13, 'Chegou Jesus, tomou o pão e deu-lho, e semelhantemente o peixe.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 14, 'Foi esta a terceira vez que Jesus se manifestou aos seus discípulos, depois de ter ressurgido dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 15, 'Depois de terem comido, perguntou Jesus a Simão Pedro: Simão Pedro: Simão, filho de João, amas-me mais do que estes? Respondeu-lhe: Sim, Senhor; tu sabes que te amo. Disse-lhe: Apascenta os meus cordeirinhos.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 16, 'Tornou a perguntar-lhe: Simão, filho de João, amas-me? Respondeu-lhe: Sim, Senhor; tu sabes que te amo. Disse-lhe: Pastoreia as minhas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 17, 'Perguntou-lhe terceira vez: Simão, filho de João, amas-me? Entristeceu-se Pedro por lhe ter perguntado pela terceira vez: Amas-me? E respondeu-lhe: Senhor, tu sabes todas as coisas; tu sabes que te amo. Disse-lhe Jesus: Apascenta as minhas ovelhas.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 18, 'Em verdade, em verdade te digo que, quando eras mais moço, te cingias a ti mesmo, e andavas por onde querias; mas, quando fores velho, estenderás as mãos e outro te cingirá, e te levará para onde tu não queres.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 19, 'Ora, isto ele disse, significando com que morte havia Pedro de glorificar a Deus. E, havendo dito isto, ordenou-lhe: Segue-me.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 20, 'E Pedro, virando-se, viu que o seguia aquele discípulo a quem Jesus amava, o mesmo que na ceia se recostara sobre o peito de Jesus e perguntara: Senhor, quem é o que te trai?', 1, CURRENT_TIMESTAMP, false),
(43, 21, 21, 'Ora, vendo Pedro a este, perguntou a Jesus: Senhor, e deste que será?', 1, CURRENT_TIMESTAMP, false),
(43, 21, 22, 'Respondeu-lhe Jesus: Se eu quiser que ele fique até que eu venha, que tens tu com isso? Segue-me tu.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 23, 'Divulgou-se, pois, entre os irmãos este dito, que aquele discípulo não havia de morrer. Jesus, porém, não disse que não morreria, mas: se eu quiser que ele fique até que eu venha, que tens tu com isso?', 1, CURRENT_TIMESTAMP, false),
(43, 21, 24, 'Este é o discípulo que dá testemunho destas coisas e as escreveu; e sabemos que o seu testemunho é verdadeiro.', 1, CURRENT_TIMESTAMP, false),
(43, 21, 25, 'E ainda muitas outras coisas há que Jesus fez; as quais, se fossem escritas uma por uma, creio que nem ainda no mundo inteiro caberiam os livros que se escrevessem.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 1, 'Ora veio a palavra do Senhor a Jonas, filho de Amitai, dizendo:', 1, CURRENT_TIMESTAMP, false),
(32, 1, 2, 'Levanta-te, vai à grande cidade de Nínive, e clama contra ela, porque a sua malícia subiu até mim.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 3, 'Jonas, porém, levantou-se para fugir da presença do Senhor para Társis. E, descendo a Jope, achou um navio que ia para Társis; pagou, pois, a sua passagem, e desceu para dentro dele, para ir com eles para Társis, da presença do Senhor.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 4, 'Mas o Senhor lançou sobre o mar um grande vento, e fez-se no mar uma grande tempestade, de modo que o navio estava a ponto de se despedaçar.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 5, 'Então os marinheiros tiveram medo, e clamavam cada um ao seu deus, e alijaram ao mar a carga que estava no navio, para o aliviarem; Jonas, porém, descera ao porão do navio; e, tendo-se deitado, dormia um profundo sono.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 6, 'O mestre do navio, pois, chegou-se a ele, e disse-lhe: Que estás fazendo, ó tu que dormes? Levanta-te, clama ao teu deus; talvez assim ele se lembre de nós, para que não pereçamos.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 7, 'E dizia cada um ao seu companheiro: Vinde, e lancemos sortes, para sabermos por causa de quem nos sobreveio este mal. E lançaram sortes, e a sorte caiu sobre Jonas.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 8, 'Então lhe disseram: Declara-nos tu agora, por causa de quem nos sobreveio este mal. Que ocupação é a tua? Donde vens? Qual é a tua terra? E de que povo és tu?', 1, CURRENT_TIMESTAMP, false),
(32, 1, 9, 'Respondeu-lhes ele: Eu sou hebreu, e temo ao Senhor, o Deus do céu, que fez o mar e a terra seca.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 10, 'Então estes homens se encheram de grande temor, e lhe disseram: Que é isso que fizeste? pois sabiam os homens que fugia da presença do Senhor, porque ele lho tinha declarado.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 11, 'Ainda lhe perguntaram: Que te faremos nós, para que o mar se nos acalme? Pois o mar se ia tornando cada vez mais tempestuoso.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 12, 'Respondeu-lhes ele: Levantai-me, e lançai-me ao mar, e o mar se vos aquietará; porque eu sei que por minha causa vos sobreveio esta grande tempestade.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 13, 'Entretanto os homens se esforçavam com os remos para tornar a alcançar a terra; mas não podiam, porquanto o mar se ia embravecendo cada vez mais contra eles.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 14, 'Por isso clamaram ao Senhor, e disseram: Nós te rogamos, ó Senhor, que não pereçamos por causa da vida deste homem, e que não ponhas sobre nós o sangue inocente; porque tu, Senhor, fizeste como te aprouve.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 15, 'Então levantaram a Jonas, e o lançaram ao mar; e cessou o mar da sua fúria.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 16, 'Temeram, pois, os homens ao Senhor com grande temor; e ofereceram sacrifícios ao Senhor, e fizeram votos.', 1, CURRENT_TIMESTAMP, false),
(32, 1, 17, 'Então o Senhor deparou um grande peixe, para que tragasse a Jonas; e esteve Jonas três dias e três noites nas entranhas do peixe.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 1, 'E orou Jonas ao Senhor, seu Deus, lá das entranhas do peixe;', 1, CURRENT_TIMESTAMP, false),
(32, 2, 2, 'e disse: Na minha angústia clamei ao senhor, e ele me respondeu; do ventre do Seol gritei, e tu ouviste a minha voz.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 3, 'Pois me lançaste no profundo, no coração dos mares, e a corrente das águas me cercou; todas as tuas ondas e as tuas vagas passaram por cima de mim.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 4, 'E eu disse: Lançado estou de diante dos teus olhos; como tornarei a olhar para o teu santo templo?', 1, CURRENT_TIMESTAMP, false),
(32, 2, 5, 'As águas me cercaram até a alma, o abismo me rodeou, e as algas se enrolaram na minha cabeça.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 6, 'Eu desci até os fundamentos dos montes; a terra encerrou-me para sempre com os seus ferrolhos; mas tu, Senhor meu Deus, fizeste subir da cova a minha vida.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 7, 'Quando dentro de mim desfalecia a minha alma, eu me lembrei do Senhor; e entrou a ti a minha oração, no teu santo templo.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 8, 'Os que se apegam aos vãos ídolos afastam de si a misericórdia.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 9, 'Mas eu te oferecerei sacrifício com a voz de ação de graças; o que votei pagarei. Ao Senhor pertence a salvação.', 1, CURRENT_TIMESTAMP, false),
(32, 2, 10, 'Falou, pois, o Senhor ao peixe, e o peixe vomitou a Jonas na terra.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 1, 'Pela segunda vez veio a palavra do Senhor a Jonas, dizendo:', 1, CURRENT_TIMESTAMP, false),
(32, 3, 2, 'Levanta-te, e vai à grande cidade de Nínive, e lhe proclama a mensagem que eu te ordeno.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 3, 'Levantou-se, pois, Jonas, e foi a Nínive, segundo a palavra do Senhor. Ora, Nínive era uma grande cidade, de três dias de jornada.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 4, 'E começou Jonas a entrar pela cidade, fazendo a jornada dum dia, e clamava, dizendo: Ainda quarenta dias, e Nínive será subvertida.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 5, 'E os homens de Nínive creram em Deus; e proclamaram um jejum, e vestiram-se de saco, desde o maior deles até o menor.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 6, 'A notícia chegou também ao rei de Nínive; e ele se levantou do seu trono e, despindo-se do seu manto e cobrindo-se de saco, sentou-se sobre cinzas.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 7, 'E fez uma proclamação, e a publicou em Nínive, por decreto do rei e dos seus nobres, dizendo: Não provem coisa alguma nem homens, nem animais, nem bois, nem ovelhas; não comam, nem bebam água;', 1, CURRENT_TIMESTAMP, false),
(32, 3, 8, 'mas sejam cobertos de saco, tanto os homens como os animais, e clamem fortemente a Deus; e convertam-se, cada um do seu mau caminho, e da violência que há nas suas mãos.', 1, CURRENT_TIMESTAMP, false),
(32, 3, 9, 'Quem sabe se voltará Deus, e se arrependerá, e se apartará do furor da sua ira, de sorte que não pereçamos?', 1, CURRENT_TIMESTAMP, false),
(32, 3, 10, 'Viu Deus o que fizeram, como se converteram do seu mau caminho, e Deus se arrependeu do mal que tinha dito lhes faria, e não o fez.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 1, 'Mas isso desagradou extremamente a Jonas, e ele ficou irado.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 2, 'E orou ao Senhor, e disse: Ah! Senhor! não foi isso o que eu disse, estando ainda na minha terra? Por isso é que me apressei a fugir para Társis, pois eu sabia que és Deus compassivo e misericordioso, longânimo e grande em benignidade, e que te arrependes do mal.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 3, 'Agora, ó Senhor, tira-me a vida, pois melhor me é morrer do que viver.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 4, 'Respondeu o senhor: É razoável essa tua ira?', 1, CURRENT_TIMESTAMP, false),
(32, 4, 5, 'Então Jonas saiu da cidade, e sentou-se ao oriente dela; e ali fez para si uma barraca, e se sentou debaixo dela, à sombra, até ver o que aconteceria à cidade.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 6, 'E fez o Senhor Deus nascer uma aboboreira, e fê-la crescer por cima de Jonas, para que lhe fizesse sombra sobre a cabeça, a fim de o livrar do seu enfado; de modo que Jonas se alegrou em extremo por causa da aboboreira.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 7, 'Mas Deus enviou um bicho, no dia seguinte ao subir da alva, o qual feriu a aboboreira, de sorte que esta se secou.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 8, 'E aconteceu que, aparecendo o sol, Deus mandou um vento calmoso oriental; e o sol bateu na cabeça de Jonas, de maneira que ele desmaiou, e desejou com toda a sua alma morrer, dizendo: Melhor me é morrer do que viver.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 9, 'Então perguntou Deus a Jonas: É razoável essa tua ira por causa da aboboreira? Respondeu ele: É justo que eu me enfade a ponto de desejar a morte.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 10, 'Disse, pois, o Senhor: Tens compaixão da aboboreira, na qual não trabalhaste, nem a fizeste crescer; que numa noite nasceu, e numa noite pereceu.', 1, CURRENT_TIMESTAMP, false),
(32, 4, 11, 'E não hei de eu ter compaixão da grande cidade de Nínive em que há mais de cento e vinte mil pessoas que não sabem discernir entre a sua mão direita e a esquerda, e também muito gado?', 1, CURRENT_TIMESTAMP, false),
(65, 1, 1, 'Judas, servo de Jesus Cristo, e irmão de Tiago, aos chamados, amados em Deus Pai, e guardados em Jesus Cristo:', 1, CURRENT_TIMESTAMP, false),
(65, 1, 2, 'Misericórdia, paz e amor vos sejam multiplicados.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 3, 'Amados, enquanto eu empregava toda a diligência para escrever-vos acerca da salvação que nos é comum, senti a necessidade de vos escrever, exortando-vos a pelejar pela fé que de uma vez para sempre foi entregue aos santos.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 4, 'Porque se introduziram furtivamente certos homens, que já desde há muito estavam destinados para este juízo, homens ímpios, que convertem em dissolução a graça de nosso Deus, e negam o nosso único Soberano e Senhor, Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 5, 'Ora, quero lembrar-vos, se bem que já de uma vez para sempre soubestes tudo isto, que, havendo o Senhor salvo um povo, tirando-o da terra do Egito, destruiu depois os que não creram;', 1, CURRENT_TIMESTAMP, false),
(65, 1, 6, 'aos anjos que não guardaram o seu principado, mas deixaram a sua própria habitação, ele os tem reservado em prisões eternas na escuridão para o juízo do grande dia,', 1, CURRENT_TIMESTAMP, false),
(65, 1, 7, 'assim como Sodoma e Gomorra, e as cidades circunvizinhas, que, havendo-se prostituído como aqueles anjos, e ido após outra carne, foram postas como exemplo, sofrendo a pena do fogo eterno.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 8, 'Contudo, semelhantemente também estes falsos mestres, sonhando, contaminam a sua carne, rejeitam toda autoridade e blasfemam das dignidades.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 9, 'Mas quando o arcanjo Miguel, discutindo com o Diabo, disputava a respeito do corpo de Moisés, não ousou pronunciar contra ele juízo de maldição, mas disse: O Senhor te repreenda', 1, CURRENT_TIMESTAMP, false),
(65, 1, 10, 'Estes, porém, blasfemam de tudo o que não entendem; e, naquilo que compreendem de modo natural, como os seres irracionais, mesmo nisso se corrompem.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 11, 'Ai deles! porque foram pelo caminho de Caim, e por amor do lucro se atiraram ao erro de Balaão, e pereceram na rebelião de Coré.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 12, 'Estes são os escolhidos em vossos ágapes, quando se banqueteiam convosco, pastores que se apascentam a si mesmos sem temor; são nuvens sem água, levadas pelos ventos; são árvores sem folhas nem fruto, duas vezes mortas, desarraigadas;', 1, CURRENT_TIMESTAMP, false),
(65, 1, 13, 'ondas furiosas do mar, espumando as suas próprias torpezas, estrelas errantes, para as quais tem sido reservado para sempre o negrume das trevas.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 14, 'Para estes também profetizou Enoque, o sétimo depois de Adão, dizendo: Eis que veio o Senhor com os seus milhares de santos,', 1, CURRENT_TIMESTAMP, false),
(65, 1, 15, 'para executar juízo sobre todos e convencer a todos os ímpios de todas as obras de impiedade, que impiamente cometeram, e de todas as duras palavras que ímpios pecadores contra ele proferiram.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 16, 'Estes são murmuradores, queixosos, andando segundo as suas concupiscências; e a sua boca diz coisas muito arrogantes, adulando pessoas por causa do interesse.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 17, 'Mas vós, amados, lembrai-vos das palavras que foram preditas pelos apóstolos de nosso Senhor Jesus Cristo;', 1, CURRENT_TIMESTAMP, false),
(65, 1, 18, 'os quais vos diziam: Nos últimos tempos haverá escarnecedores, andando segundo as suas ímpias concupiscências.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 19, 'Estes são os que causam divisões; são sensuais, e não têm o Espírito.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 20, 'Mas vós, amados, edificando-vos sobre a vossa santíssima fé, orando no Espírito Santo,', 1, CURRENT_TIMESTAMP, false),
(65, 1, 21, 'conservai-vos no amor de Deus, esperando a misericórdia de nosso Senhor Jesus Cristo para a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 22, 'E apiedai-vos de alguns que estão na dúvida,', 1, CURRENT_TIMESTAMP, false),
(65, 1, 23, 'e salvai-os, arrebatando-os do fogo; e de outros tende misericórdia com temor, abominação até a túnica manchada pela carne.', 1, CURRENT_TIMESTAMP, false),
(65, 1, 24, 'Ora, àquele que é poderoso para vos guardar de tropeçar, e apresentar-vos ante a sua glória imaculados e jubilosos,', 1, CURRENT_TIMESTAMP, false),
(65, 1, 25, 'ao único Deus, nosso Salvador, por Jesus Cristo nosso Senhor, glória, majestade, domínio e poder, antes de todos os séculos, e agora, e para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 1, 'Como está sentada solitária a cidade que era tão populosa! tornou-se como viúva a que era grande entre as nações! A que era princesa entre as províncias tornou-se avassalada!', 1, CURRENT_TIMESTAMP, false),
(25, 1, 2, 'Chora amargamente de noite, e as lágrimas lhe correm pelas faces; não tem quem a console entre todos os seus amantes; todos os seus amigos se houveram aleivosamente com ela; tornaram-se seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 3, 'Judá foi para o cativeiro para sofrer aflição e dura servidão; ela habita entre as nações, não acha descanso; todos os seus perseguidores a alcançaram nas suas angústias.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 4, 'Os caminhos de Sião pranteiam, porque não há quem venha à assembléia solene; todas as suas portas estão desoladas; os seus sacerdotes suspiram; as suas virgens estão tristes, e ela mesma sofre amargamente.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 5, 'Os seus adversários a dominam, os seus inimigos prosperam; porque o Senhor a afligiu por causa da multidão das suas transgressões; os seus filhinhos marcharam para o cativeiro adiante do adversário.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 6, 'E da filha de Sião já se foi todo o seu esplendor; os seus príncipes ficaram sendo como cervos que não acham pasto e caminham sem força adiante do perseguidor.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 7, 'Lembra-se Jerusalém, nos dias da sua aflição e dos seus exílios, de todas as suas preciosas coisas, que tivera desde os tempos antigos; quando caía o seu povo na mão do adversário, e não havia quem a socorresse, os adversários a viram, e zombaram da sua ruína.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 8, 'Jerusalém gravemente pecou, por isso se fez imunda; todos os que a honravam a desprezam, porque lhe viram a nudez; ela também suspira e se volta para trás.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 9, 'A sua imundícia estava nas suas fraldas; não se lembrava do seu fim; por isso foi espantosamente abatida; não há quem a console; vê, Senhor, a minha aflição; pois o inimigo se tem engrandecido.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 10, 'Estendeu o adversário a sua mão a todas as coisas preciosas dela; pois ela viu entrar no seu santuário as nações, acerca das quais ordenaste que não entrassem na tua congregação.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 11, 'Todo o seu povo anda gemendo, buscando o pão; deram as suas coisas mais preciosas a troco de mantimento para refazerem as suas forças. Vê, Senhor, e contempla, pois me tornei desprezível.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 12, 'Não vos comove isto a todos vós que passais pelo caminho? Atendei e vede se há dor igual a minha dor, que veio sobre mim, com que o Senhor me afligiu, no dia do furor da sua ira.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 13, 'Desde o alto enviou fogo que entra nos meus ossos, o qual se assenhoreou deles; estendeu uma rede aos meus pés, fez-me voltar para trás, tornou-me desolada e desfalecida o dia todo.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 14, 'O jugo das minhas transgressões foi atado; pela sua mão elas foram entretecidas e postas sobre o meu pescoço; ele abateu a minha força; entregou-me o Senhor nas mãos daqueles a quem eu não posso resistir.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 15, 'O Senhor desprezou todos os meus valentes no meio de mim; convocou contra mim uma assembléia para esmagar os meus mancebos; o Senhor pisou como num lagar a virgem filha de Judá.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 16, 'Por estas coisas vou chorando; os meus olhos, os meus olhos se desfazem em águas; porque está longe de mim um consolador que pudesse renovar o meu ânimo; os meus filhos estão desolados, porque prevaleceu o inimigo.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 17, 'Estende Sião as suas mãos, não há quem a console; ordenou o Senhor acerca de Jacó que fossem inimigos os que estão em redor dele; Jerusalém se tornou entre eles uma coisa imunda.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 18, 'Justo é o Senhor, pois me rebelei contra os seus mandamentos; ouvi, rogo-vos, todos os povos, e vede a minha dor; para o cativeiro foram-se as minhas virgens e os meus mancebos.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 19, 'Chamei os meus amantes, mas eles me enganaram; os meus sacerdotes e os meus anciãos expiraram na cidade, enquanto buscavam para si mantimento, para refazerem as suas forças.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 20, 'Olha, Senhor, porque estou angustiada; turbadas estão as minhas entranhas; o meu coração está transtornado dentro de mim; porque gravemente me rebelei. Na rua me desfilha a espada, em casa é como a morte.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 21, 'Ouviram como estou gemendo; mas não há quem me console; todos os meus inimigos souberam do meu mal; alegram-se de que tu o determinaste; mas, em trazendo tu o dia que anunciaste, eles se tornarão semelhantes a mim.', 1, CURRENT_TIMESTAMP, false),
(25, 1, 22, 'Venha toda a sua maldade para a tua presença, e faze-lhes como me fizeste a mim por causa de todas as minhas transgressões; pois muitos são os meus gemidos, e desfalecido está o meu coração.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 1, 'Como cobriu o Senhor de nuvens na sua ira a filha de Sião! derrubou do céu à terra a glória de Israel, e no dia da sua ira não se lembrou do escabelo de seus pés.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 2, 'Devorou o Senhor sem piedade todas as moradas de Jacó; derrubou no seu furor as fortalezas da filha de Judá; abateu-as até a terra. Tratou como profanos o reino e os seus príncipes.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 3, 'No furor da sua ira cortou toda a força de Israel; retirou para trás a sua destra de diante do inimigo; e ardeu contra Jacó, como labareda de fogo que tudo consome em redor.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 4, 'Armou o seu arco como inimigo, firmou a sua destra como adversário, e matou todo o que era formoso aos olhos; derramou a sua indignação como fogo na tenda da filha de Sião.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 5, 'Tornou-se o Senhor como inimigo; devorou a Israel, devorou todos os seus palácios, destruiu as suas fortalezas, e multiplicou na filha de Judá o pranto e a lamentação.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 6, 'E arrancou a sua cabana com violência, como se fosse a de uma horta; destruiu o seu lugar de assembléia; o Senhor entregou ao esquecimento em Sião a assembléia solene e o sábado; e na indignação da sua ira rejeitou com desprezo o rei e o sacerdote.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 7, 'Desprezou o Senhor o seu altar, detestou o seu santuário; entregou na mão do inimigo os muros dos seus palácios; deram-se gritos na casa do Senhor, como em dia de reunião solene.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 8, 'Resolveu o Senhor destruir o muro da filha de Sião; estendeu o cordel, não reteve a sua mão de fazer estragos; fez gemer o antemuro e o muro; eles juntamente se enfraquecem.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 9, 'Sepultadas na terra estão as suas portas; ele destruiu e despedaçou os ferrolhos dela; o seu rei e os seus príncipes estão entre as nações; não há lei; também os seus profetas não recebem visão alguma da parte do Senhor.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 10, 'Estão sentados no chão os anciãos da filha de Sião, e ficam calados; lançaram pó sobre as suas cabeças; cingiram sacos; as virgens de Jerusalém abaixaram as suas cabeças até o chão.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 11, 'Já se consumiram os meus olhos com lágrimas, turbada está a minha alma, o meu coração se derrama de tristeza por causa do quebrantamento da filha do meu povo; porquanto desfalecem os meninos e as crianças de peito pelas ruas da cidade.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 12, 'Ao desfalecerem, como feridos, pelas ruas da cidade, ao exalarem as suas almas no regaço de suas mães, perguntam a elas: Onde está o trigo e o vinho?', 1, CURRENT_TIMESTAMP, false),
(25, 2, 13, 'Que testemunho te darei, a que te compararei, ó filha de Jerusalém? A quem te assemelharei, para te consolar, ó virgem filha de Sião? pois grande como o mar é a tua ferida; quem te poderá curar?', 1, CURRENT_TIMESTAMP, false),
(25, 2, 14, 'Os teus profetas viram para ti visões falsas e insensatas; e não manifestaram a tua iniqüidade, para te desviarem do cativeiro; mas viram para ti profecias vãs e coisas que te levaram ao exílio.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 15, 'Todos os que passam pelo caminho batem palmas contra ti; eles assobiam e meneiam a cabeça sobre a filha de Jerusalém, dizendo: E esta a cidade que denominavam a perfeição da formosura, o gozo da terra toda?', 1, CURRENT_TIMESTAMP, false),
(25, 2, 16, 'Todos os teus inimigos abrem as suas bocas contra ti, assobiam, e rangem os dentes; dizem: Devoramo-la; certamente este e o dia que esperávamos; achamo-lo, vimo-lo.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 17, 'Fez o Senhor o que intentou; cumpriu a sua palavra, que ordenou desde os dias da antigüidade; derrubou, e não se apiedou; fez que o inimigo se alegrasse por tua causa, exaltou o poder dos teus adversários.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 18, 'Clama ao Senhor, ó filha de Sião; corram as tuas lágrimas, como um ribeiro, de dia e de noite; não te dês repouso, nem descansem os teus olhos.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 19, 'Levanta-te, clama de noite no princípio das vigias; derrama o teu coração como águas diante do Senhor! Levanta a ele as tuas mãos, pela vida de teus filhinhos, que desfalecem de fome à entrada de todas as ruas.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 20, 'Vê, ó Senhor, e considera a quem assim tens tratado! Acaso comerão as mulheres o fruto de si mesmas, as crianças que trazem nos braços? ou matar-se-á no santuário do Senhor o sacerdote e o profeta?', 1, CURRENT_TIMESTAMP, false),
(25, 2, 21, 'Jazem por terra nas ruas o moço e o velho; as minhas virgens e os meus jovens vieram a cair à espada; tu os mataste no dia da tua ira; trucidaste-os sem misericórdia.', 1, CURRENT_TIMESTAMP, false),
(25, 2, 22, 'Convocaste de toda a parte os meus terrores, como no dia de assembléia solene; não houve no dia da ira do Senhor quem escapasse ou ficasse; aqueles que eu trouxe nas mãos e criei, o meu inimigo os consumiu.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 1, 'Eu sou o homem que viu a aflição causada pela vara do seu furor.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 2, 'Ele me guiou e me fez andar em trevas e não na luz.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 3, 'Deveras fez virar e revirar a sua mão contra mim o dia todo.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 4, 'Fez envelhecer a minha carne e a minha pele; quebrou-me os ossos.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 5, 'Levantou trincheiras contra mim, e me cercou de fel e trabalho.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 6, 'Fez-me habitar em lugares tenebrosos, como os que estavam mortos há muito.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 7, 'Cercou-me de uma sebe de modo que não posso sair; agravou os meus grilhões.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 8, 'Ainda quando grito e clamo por socorro, ele exclui a minha oração.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 9, 'Fechou os meus caminhos com pedras lavradas, fez tortuosas as minhas veredas.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 10, 'Fez-se-me como urso de emboscada, um leão em esconderijos.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 11, 'Desviou os meus caminhos, e fez-me em pedaços; deixou-me desolado.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 12, 'Armou o seu arco, e me pôs como alvo à flecha.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 13, 'Fez entrar nos meus rins as flechas da sua aljava.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 14, 'Fui feito um objeto de escárnio para todo o meu povo, e a sua canção o dia todo.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 15, 'Encheu-me de amarguras, fartou-me de absinto.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 16, 'Quebrou com pedrinhas de areia os meus dentes, cobriu-me de cinza.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 17, 'Alongaste da paz a minha alma; esqueci-me do que seja a felicidade.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 18, 'Digo, pois: Já pereceu a minha força, como também a minha esperança no Senhor.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 19, 'Lembra-te da minha aflição e amargura, do absinto e do fel.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 20, 'Minha alma ainda os conserva na memória, e se abate dentro de mim.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 21, 'Torno a trazer isso à mente, portanto tenho esperança.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 22, 'A benignidade do Senhor jamais acaba, as suas misericórdias não têm fim;', 1, CURRENT_TIMESTAMP, false),
(25, 3, 23, 'renovam-se cada manhã. Grande é a tua fidelidade.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 24, 'A minha porção é o Senhor, diz a minha alma; portanto esperarei nele.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 25, 'Bom é o Senhor para os que esperam por ele, para a alma que o busca.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 26, 'Bom é ter esperança, e aguardar em silêncio a salvação do Senhor.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 27, 'Bom é para o homem suportar o jugo na sua mocidade.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 28, 'Que se assente ele, sozinho, e fique calado, porquanto Deus o pôs sobre ele.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 29, 'Ponha a sua boca no pó; talvez ainda haja esperança.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 30, 'Dê a sua face ao que o fere; farte-se de afronta.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 31, 'Pois o Senhor não rejeitará para sempre.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 32, 'Embora entristeça a alguém, contudo terá compaixão segundo a grandeza da sua misericórdia.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 33, 'Porque não aflige nem entristece de bom grado os filhos dos homens.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 34, 'Pisar debaixo dos pés a todos os presos da terra,', 1, CURRENT_TIMESTAMP, false),
(25, 3, 35, 'perverter o direito do homem perante a face do Altíssimo,', 1, CURRENT_TIMESTAMP, false),
(25, 3, 36, 'subverter o homem no seu pleito, não são do agrado do senhor.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 37, 'Quem é aquele que manda, e assim acontece, sem que o Senhor o tenha ordenado?', 1, CURRENT_TIMESTAMP, false),
(25, 3, 38, 'Não sai da boca do Altíssimo tanto o mal como o bem?', 1, CURRENT_TIMESTAMP, false),
(25, 3, 39, 'Por que se queixaria o homem vivente, o varão por causa do castigo dos seus pecados?', 1, CURRENT_TIMESTAMP, false),
(25, 3, 40, 'Esquadrinhemos os nossos caminhos, provemo-los, e voltemos para o Senhor.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 41, 'Levantemos os nossos corações com as mãos para Deus no céu dizendo;', 1, CURRENT_TIMESTAMP, false),
(25, 3, 42, 'Nós transgredimos, e fomos rebeldes, e não perdoaste,', 1, CURRENT_TIMESTAMP, false),
(25, 3, 43, 'Cobriste-te de ira, e nos perseguiste; mataste, não te apiedaste.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 44, 'Cobriste-te de nuvens, para que não passe a nossa oração.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 45, 'Como escória e refugo nos puseste no meio dos povos.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 46, 'Todos os nossos inimigos abriram contra nós a sua boca.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 47, 'Temor e cova vieram sobre nós, assolação e destruição.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 48, 'Torrentes de águas correm dos meus olhos, por causa da destruição da filha do meu povo.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 49, 'Os meus olhos derramam lágrimas, e não cessam, sem haver intermissão,', 1, CURRENT_TIMESTAMP, false),
(25, 3, 50, 'até que o Senhor atente e veja desde o céu.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 51, 'Os meus olhos me afligem, por causa de todas as filhas da minha cidade.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 52, 'Como ave me caçaram os que, sem causa, são meus inimigos.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 53, 'Atiraram-me vivo na masmorra, e lançaram pedras sobre mim.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 54, 'Águas correram sobre a minha cabeça; eu disse: Estou cortado.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 55, 'Invoquei o teu nome, Senhor, desde a profundeza da masmorra.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 56, 'Ouviste a minha voz; não escondas o teu ouvido ao meu suspiro, ao meu clamor.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 57, 'Tu te aproximaste no dia em que te invoquei; disseste: Não temas.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 58, 'Pleiteaste, Senhor, a minha causa; remiste a minha vida.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 59, 'Viste, Senhor, a injustiça que sofri; julga tu a minha causa.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 60, 'Viste toda a sua vingança, todos os seus desígnios contra mim.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 61, 'Ouviste as suas afrontas, Senhor, todos os seus desígnios contra mim,', 1, CURRENT_TIMESTAMP, false),
(25, 3, 62, 'os lábios e os pensamentos dos que se levantam contra mim o dia todo.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 63, 'Observa-os ao assentarem-se e ao levantarem-se; eu sou a sua canção.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 64, 'Tu lhes darás a recompensa, Senhor, conforme a obra das suas mãos.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 65, 'Tu lhes darás dureza de coração, maldição tua sobre eles.', 1, CURRENT_TIMESTAMP, false),
(25, 3, 66, 'Na tua ira os perseguirás, e os destruirás de debaixo dos teus céus, ó Senhor.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 1, 'Como se escureceu o ouro! como se mudou o ouro puríssimo! como estão espalhadas as pedras do santuário pelas esquinas de todas as ruas!', 1, CURRENT_TIMESTAMP, false),
(25, 4, 2, 'Os preciosos filhos de Sião, comparáveis a ouro puro, como são agora reputados por vasos de barro, obra das mãos de oleiro!', 1, CURRENT_TIMESTAMP, false),
(25, 4, 3, 'Até os chacais abaixam o peito, dão de mamar aos seus filhos; mas a filha do meu povo tornou-se cruel como os avestruzes no deserto.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 4, 'A língua do que mama fica pegada pela sede ao seu paladar; os meninos pedem pão, e ninguém lho reparte.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 5, 'Os que comiam iguarias delicadas desfalecem nas ruas; os que se criavam em escarlata abraçam monturos.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 6, 'Pois maior é a iniqüidade da filha do meu povo do que o pecado de Sodoma, a qual foi subvertida como num momento, sem que mão alguma lhe tocasse.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 7, 'Os seus nobres eram mais alvos do que a neve, mais brancos do que o leite, eram mais ruivos de corpo do que o coral, e a sua formosura era como a de safira.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 8, 'Mas agora escureceu-se o seu parecer mais do que o negrume; eles não são reconhecidos nas ruas; a sua pele se lhes pegou aos ossos; secou-se, tornou-se como um pau. .', 1, CURRENT_TIMESTAMP, false),
(25, 4, 9, 'Os mortos à espada eram mais ditosos do que os mortos à fome, pois estes se esgotavam, como traspassados, por falta dos frutos dos campos.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 10, 'As mãos das mulheres compassivas cozeram os próprios filhos; estes lhes serviram de alimento na destruição da filha do meu povo.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 11, 'Deu o Senhor cumprimento ao seu furor, derramou o ardor da sua ira; e acendeu um fogo em Sião, que consumiu os seus fundamentos.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 12, 'Não creram os reis da terra, bem como nenhum dos moradores do mundo, que adversário ou inimigo pudesse entrar pelas portas de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 13, 'Isso foi por causa dos pecados dos seus profetas e das iniqüidades dos seus sacerdotes, que derramaram no meio dela o sangue dos justos.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 14, 'Vagueiam como cegos pelas ruas; andam contaminados de sangue, de tal sorte que não se lhes pode tocar nas roupas.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 15, 'Desviai-vos! imundo! gritavam-lhes; desviai-vos, desviai-vos, não toqueis! Quando fugiram, e andaram, vagueando, dizia-se entre as nações: Nunca mais morarão aqui.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 16, 'A ira do Senhor os espalhou; ele nunca mais tornará a olhar para eles; não respeitaram a pessoa dos sacerdotes, nem se compadeceram dos velhos.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 17, 'Os nossos olhos desfaleciam, esperando o nosso vão socorro. em vigiando olhávamos para uma nação, que não podia, livrai.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 18, 'Espiaram os nossos passos, de maneira que não podíamos andar pelas nossas ruas; o nosso fim estava perto; estavam contados os nossos dias, porque era chegado o nosso fim.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 19, 'Os nossos perseguidores foram mais ligeiros do que as águias do céu; sobre os montes nos perseguiram, no deserto nos armaram ciladas.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 20, 'O fôlego da nossa vida, o ungido do Senhor, foi preso nas covas deles, o mesmo de quem dizíamos: Debaixo da sua sombra viveremos entre as nações.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 21, 'Regozija-te, e alegra-te, ó filha de Edom, que habitas na terra de Uz; o cálice te passará a ti também; embebedar-te-ás, e te descobrirás.', 1, CURRENT_TIMESTAMP, false),
(25, 4, 22, 'Já se cumpriu o castigo da tua iniqüidade, ó filha de Sião; ele nunca mais te levará para o cativeiro; ele visitará a tua iniqüidade, ó filha de Edom; descobrirá os teus pecados.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 1, 'Lembra-te, Senhor, do que nos tem sucedido; considera, e olha para o nosso opróbrio.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 2, 'A nossa herdade passou a estranhos, e as nossas casas a forasteiros.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 3, 'órfãos somos sem pai, nossas mães são como viuvas.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 4, 'A nossa água por dinheiro a bebemos, por preço vem a nossa lenha.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 5, 'Os nossos perseguidores estão sobre os nossos pescoços; estamos cansados, e não temos descanso.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 6, 'Aos egípcios e aos assírios estendemos as mãos, para nos fartarmos de pão.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 7, 'Nossos pais pecaram, e já não existem; e nós levamos as suas iniqüidades.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 8, 'Escravos dominam sobre nós; ninguém há que nos arranque da sua mão.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 9, 'Com perigo de nossas vidas obtemos o nosso pão, por causa da espada do deserto.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 10, 'Nossa pele está abraseada como um forno, por causa do ardor da fome.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 11, 'Forçaram as mulheres em Sião, as virgens nas cidades de Judá.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 12, 'Príncipes foram enforcados pelas mãos deles; as faces dos anciãos não foram respeitadas.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 13, 'Mancebos levaram a mó; meninos tropeçaram sob fardos de lenha.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 14, 'Os velhos já não se assentam nas portas, os mancebos já não cantam.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 15, 'Cessou o gozo de nosso coração; converteu-se em lamentação a nossa dança.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 16, 'Caiu a coroa da nossa cabeça; ai de nós. porque pecamos.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 17, 'Portanto desmaiou o nosso coração; por isso se escureceram os nossos olhos.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 18, 'Pelo monte de Sião, que está assolado, andam os chacais.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 19, 'Tu, Senhor, permaneces eternamente; e o teu trono subsiste de geração em geração.', 1, CURRENT_TIMESTAMP, false),
(25, 5, 20, 'Por que te esquecerias de nós para sempre, por que nos desampararias por tanto tempo?', 1, CURRENT_TIMESTAMP, false),
(25, 5, 21, 'Converte-nos a ti, Senhor, e seremos convertidos; renova os nossos dias como dantes;', 1, CURRENT_TIMESTAMP, false),
(25, 5, 22, 'se é que não nos tens de todo rejeitado, se é que não estás sobremaneira irado contra nos.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 1, 'Ora, chamou o Senhor a Moisés e, da tenda da revelação, lhe disse:', 1, CURRENT_TIMESTAMP, false),
(3, 1, 2, 'Fala aos filhos de Israel e dize-lhes: Quando algum de vós oferecer oferta ao Senhor, oferecereis as vossas ofertas do gado, isto é, do gado vacum e das ovelhas.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 3, 'Se a sua oferta for holocausto de gado vacum, oferecerá ele um macho sem defeito; à porta da tenda da revelação o oferecerá, para que ache favor perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 4, 'Porá a sua mão sobre a cabeça do holocausto, e este será aceito a favor dele, para a sua expiação.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 5, 'Depois imolará o novilho perante o Senhor; e os filhos de Arão, os sacerdotes, oferecerão o sangue, e espargirão o sangue em redor sobre o altar que está à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 6, 'Então esfolará o holocausto, e o partirá nos seus pedaços.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 7, 'E os filhos de Arão, o sacerdote, porão fogo sobre o altar, pondo em ordem a lenha sobre o fogo;', 1, CURRENT_TIMESTAMP, false),
(3, 1, 8, 'também os filhos de Arão, os sacerdotes, porão em ordem os pedaços, a cabeça e a gordura, sobre a lenha que está no fogo em cima do altar;', 1, CURRENT_TIMESTAMP, false),
(3, 1, 9, 'a fressura, porém, e as pernas, ele as lavará com água; e o sacerdote queimará tudo isso sobre o altar como holocausto, oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 10, 'Se a sua oferta for holocausto de gado miúdo, seja das ovelhas seja das cabras, oferecerá ele um macho sem defeito,', 1, CURRENT_TIMESTAMP, false),
(3, 1, 11, 'e o imolará ao lado do altar que dá para o norte, perante o Senhor; e os filhos de Arão, os sacerdotes, espargirão o sangue em redor sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 12, 'Então o partirá nos seus pedaços, juntamente com a cabeça e a gordura; e o sacerdote os porá em ordem sobre a lenha que está no fogo sobre o altar;', 1, CURRENT_TIMESTAMP, false),
(3, 1, 13, 'a fressura, porém, e as pernas, ele as lavará com água; e o sacerdote oferecerá tudo isso, e o queimará sobre o altar; holocausto é, oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 14, 'Se a sua oferta ao Senhor for holocausto tirado de aves, então de rolas ou de pombinhos oferecerá a sua oferta.', 1, CURRENT_TIMESTAMP, false),
(3, 1, 15, 'E o sacerdote a trará ao altar, tirar-lhe-á a cabeça e a queimará sobre o altar; e o seu sangue será espremido na parede do altar;', 1, CURRENT_TIMESTAMP, false),
(3, 1, 16, 'e o seu papo com as suas penas tirará e o lançará junto ao altar, para o lado do oriente, no lugar da cinza;', 1, CURRENT_TIMESTAMP, false),
(3, 1, 17, 'e fendê-la-á junto às suas asas, mas não a partirá; e o sacerdote a queimará em cima do altar sobre a lenha que está no fogo; holocausto é, oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 1, 'Quando alguém fizer ao Senhor uma oferta de cereais, a sua oferta será de flor de farinha; deitará nela azeite, e sobre ela porá incenso;', 1, CURRENT_TIMESTAMP, false),
(3, 2, 2, 'e a trará aos filhos de Arão, os sacerdotes, um dos quais lhe tomará um punhado da flor de farinha e do azeite com todo o incenso, e o queimará sobre o altar por oferta memorial, oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 3, 'O que restar da oferta de cereais pertencerá a Arão e a seus filhos; é coisa santíssima entre as ofertas queimadas ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 4, 'Quando fizerdes oferta de cereais assada ao forno, será de bolos ázimos de flor de farinha, amassados com azeite, e coscorões ázimos untados com azeite.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 5, 'E se a tua oferta for oferta de cereais assada na assadeira, será de flor de farinha sem fermento, amassada com azeite.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 6, 'Em pedaços a partirás, e sobre ela deitarás azeite; é oferta de cereais.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 7, 'E se a tua oferta for oferta de cereais cozida na frigideira, far-se-á de flor de farinha com azeite.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 8, 'Então trarás ao Senhor a oferta de cereais que for feita destas coisas; e será apresentada ao sacerdote, o qual a levará ao altar.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 9, 'E o sacerdote tomará da oferta de cereais o memorial dela, e o queimará sobre o altar; é oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 10, 'E o que restar da oferta de cereais pertencerá a Arão e a seus filhos; é coisa santíssima entre as ofertas queimadas ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 11, 'Nenhuma oferta de cereais, que fizerdes ao Senhor, será preparada com fermento; porque não queimareis fermento algum nem mel algum como oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 12, 'Como oferta de primícias oferecê-los-eis ao Senhor; mas sobre o altar não subirão por cheiro suave.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 13, 'Todas as suas ofertas de cereais temperarás com sal; não deixarás faltar a elas o sal do pacto do teu Deus; em todas as tuas ofertas oferecerás sal.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 14, 'Se fizeres ao Senhor oferta de cereais de primícias, oferecerás, como oferta de cereais das tuas primícias, espigas tostadas ao fogo, isto é, o grão trilhado de espigas verdes.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 15, 'Sobre ela deitarás azeite, e lhe porás por cima incenso; é oferta de cereais.', 1, CURRENT_TIMESTAMP, false),
(3, 2, 16, 'O sacerdote queimará o memorial dela, isto é, parte do grão trilhado e parte do azeite com todo o incenso; é oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 1, 'Se a oferta de alguém for sacrifício pacífico: se a fizer de gado vacum, seja macho ou fêmea, oferecê-la-á sem defeito diante do Senhor;', 1, CURRENT_TIMESTAMP, false),
(3, 3, 2, 'porá a mão sobre a cabeça da sua oferta e a imolará à porta da tenda da revelação; e os filhos de Arão, os sacerdotes, espargirão o sangue sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 3, 'Então, do sacrifício de oferta pacífica, fará uma oferta queimada ao Senhor; a gordura que cobre a fressura, sim, toda a gordura que está sobre ela,', 1, CURRENT_TIMESTAMP, false),
(3, 3, 4, 'os dois rins e a gordura que está sobre eles, e a que está junto aos lombos, e o redenho que está sobre o fígado, juntamente com os rins, ele os tirará.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 5, 'E os filhos de Arão queimarão isso sobre o altar, em cima do holocausto que está sobre a lenha no fogo; é oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 6, 'E se a sua oferta por sacrifício pacífico ao Senhor for de gado miúdo, seja macho ou fêmea, sem defeito o oferecerá.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 7, 'Se oferecer um cordeiro por sua oferta, oferecê-lo-á perante o Senhor;', 1, CURRENT_TIMESTAMP, false),
(3, 3, 8, 'e porá a mão sobre a cabeça da sua oferta, e a imolará diante da tenda da revelação; e os filhos de Arão espargirão o sangue sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 9, 'Então, do sacrifício de oferta pacífica, fará uma oferta queimada ao Senhor; a gordura da oferta, a cauda gorda inteira, tirá-la-á junto ao espinhaço; e a gordura que cobre a fressura, sim, toda a gordura que está sobre ela,', 1, CURRENT_TIMESTAMP, false),
(3, 3, 10, 'os dois rins e a gordura que está sobre eles, e a que está junto aos lombos, e o redenho que está sobre o fígado, juntamente com os rins, tirá-los-á.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 11, 'E o sacerdote queimará isso sobre o altar; é o alimento da oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 12, 'E se a sua oferta for uma cabra, perante o Senhor a oferecerá;', 1, CURRENT_TIMESTAMP, false),
(3, 3, 13, 'e lhe porá a mão sobre a cabeça, e a imolará diante da tenda da revelação; e os filhos de Arão espargirão o sangue da cabra sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 14, 'Depois oferecerá dela a sua oferta, isto é, uma oferta queimada ao Senhor; a gordura que cobre a fressura, sim, toda a gordura que está sobre ela,', 1, CURRENT_TIMESTAMP, false),
(3, 3, 15, 'os dois rins e a gordura que está sobre eles, e a que está junto aos lombos, e o redenho que está sobre o fígado, juntamente com os rins, tirá-los-á.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 16, 'E o sacerdote queimará isso sobre o altar; é o alimento da oferta queimada, de cheiro suave. Toda a gordura pertencerá ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 3, 17, 'Estatuto perpétuo, pelas vossas gerações, em todas as vossas habitações, será isto: nenhuma gordura nem sangue algum comereis.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 4, 2, 'Fala aos filhos de Israel, dizendo: Se alguém pecar por ignorância no tocante a qualquer das coisas que o Senhor ordenou que não se fizessem, fazendo qualquer delas;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 3, 'se for o sacerdote ungido que pecar, assim tornando o povo culpado, oferecerá ao Senhor, pelo pecado que cometeu, um novilho sem defeito como oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 4, 'Trará o novilho à porta da tenda da revelação, perante o Senhor; porá a mão sobre a cabeça do novilho e o imolará perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 5, 'Então o sacerdote ungido tomará do sangue do novilho, e o trará à tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 6, 'e, molhando o dedo no sangue, espargirá do sangue sete vezes perante o Senhor, diante do véu do santuário.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 7, 'Também o sacerdote porá daquele sangue perante o Senhor, sobre as pontas do altar do incenso aromático, que está na tenda da revelação; e todo o resto do sangue do novilho derramará à base do altar do holocausto, que está à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 8, 'E tirará toda a gordura do novilho da oferta pelo pecado; a gordura que cobre a fressura, sim, toda a gordura que está sobre ela,', 1, CURRENT_TIMESTAMP, false),
(3, 4, 9, 'os dois rins e a gordura que está sobre eles, e a que está junto aos lombos, e o redenho que está sobre o fígado, juntamente com os rins, tirá-los-á,', 1, CURRENT_TIMESTAMP, false),
(3, 4, 10, 'assim como se tira do boi do sacrifício pacífico; e o sacerdote os queimará sobre o altar do holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 11, 'Mas o couro do novilho, e toda a sua carne, com a cabeça, as pernas, a fressura e o excremento,', 1, CURRENT_TIMESTAMP, false),
(3, 4, 12, 'enfim, o novilho todo, levá-lo-á para fora do arraial a um lugar limpo, em que se lança a cinza, e o queimará sobre a lenha; onde se lança a cinza, aí se queimará.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 13, 'Se toda a congregação de Israel errar, sendo isso oculto aos olhos da assembléia, e eles tiverem feito qualquer de todas as coisas que o Senhor ordenou que não se fizessem, assim tornando-se culpados;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 14, 'quando o pecado que cometeram for conhecido, a assembléia oferecerá um novilho como oferta pelo pecado, e o trará diante da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 15, 'Os anciãos da congregação porão as mãos sobre a cabeça do novilho perante o Senhor; e imolar-se-á o novilho perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 16, 'Então o sacerdote ungido trará do sangue do novilho à tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 17, 'e o sacerdote molhará o dedo no sangue, e o espargirá sete vezes perante o Senhor, diante do véu.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 18, 'E do sangue porá sobre as pontas do altar, que está perante o Senhor, na tenda da revelação; e todo o resto do sangue derramará à base do altar do holocausto, que está diante da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 19, 'E tirará dele toda a sua gordura, e queimá-la-á sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 20, 'Assim fará com o novilho; como fez ao novilho da oferta pelo pecado, assim fará a este; e o sacerdote fará expiação por eles, e eles serão perdoados.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 21, 'Depois levará o novilho para fora do arraial, e o queimará como queimou o primeiro novilho; é oferta pelo pecado da assembléia.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 22, 'Quando um príncipe pecar, fazendo por ignorância qualquer das coisas que o Senhor seu Deus ordenou que não se fizessem, e assim se tornar culpado;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 23, 'se o pecado que cometeu lhe for notificado, então trará por sua oferta um bode, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 24, 'porá a mão sobre a cabeça do bode e o imolará no lugar em que se imola o holocausto, perante o Senhor; é oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 25, 'Depois o sacerdote, com o dedo, tomará do sangue da oferta pelo pecado e pô-lo-á sobre as pontas do altar do holocausto; então o resto do sangue derramará à base do altar do holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 26, 'Também queimará sobre o altar toda a sua gordura como a gordura do sacrifício da oferta pacífica; assim o sacerdote fará por ele expiação do seu pecado, e ele será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 27, 'E se alguém dentre a plebe pecar por ignorância, fazendo qualquer das coisas que o Senhor ordenou que não se fizessem, e assim se tornar culpado;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 28, 'se o pecado que cometeu lhe for notificado, então trará por sua oferta uma cabra, sem defeito, pelo pecado cometido;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 29, 'porá a mão sobre a cabeça da oferta pelo pecado, e a imolará no lugar do holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 30, 'Depois o sacerdote, com o dedo, tomará do sangue da oferta, e o porá sobre as pontas do altar do holocausto; e todo o resto do sangue derramará à base do altar.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 31, 'Tirará toda a gordura, como se tira a gordura do sacrifício pacífico, e a queimará sobre o altar, por cheiro suave ao Senhor; e o sacerdote fará expiação por ele, e ele será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 32, 'Ou, se pela sua oferta trouxer uma cordeira como oferta pelo pecado, sem defeito a trará;', 1, CURRENT_TIMESTAMP, false),
(3, 4, 33, 'porá a mão sobre a cabeça da oferta pelo pecado, e a imolará por oferta pelo pecado, no lugar em que se imola o holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 34, 'Depois o sacerdote, com o dedo, tomará do sangue da oferta pelo pecado, e o porá sobre as pontas do altar do holocausto; então todo o resto do sangue da oferta derramará à base do altar.', 1, CURRENT_TIMESTAMP, false),
(3, 4, 35, 'Tirará toda a gordura, como se tira a gordura do cordeiro do sacrifício pacífico e a queimará sobre o altar, em cima das ofertas queimadas do Senhor; assim o sacerdote fará por ele expiação do pecado que cometeu, e ele será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 1, 'Se alguém, tendo-se ajuramentado como testemunha, pecar por não denunciar o que viu, ou o que soube, levará a sua iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 2, 'Se alguém tocar alguma coisa imunda, seja cadáver de besta-fera imunda, seja cadáver de gado imundo, seja cadáver de réptil imundo, embora faça sem se aperceber, contudo será ele imundo e culpado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 3, 'Se alguém, sem se aperceber tocar a imundícia de um homem, seja qual for a imundícia com que este se tornar imundo, quando o souber será culpado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 4, 'Se alguém, sem se aperceber, jurar temerariamente com os seus lábios fazer mal ou fazer bem, em tudo o que o homem pronunciar temerariamente com juramento, quando o souber, culpado será numa destas coisas.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 5, 'Deverá, pois, quando for culpado numa destas coisas, confessar aquilo em que houver pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 6, 'E como sua oferta pela culpa, ele trará ao Senhor, pelo pecado que cometeu, uma fêmea de gado miúdo; uma cordeira, ou uma cabrinha, trará como oferta pelo pecado; e o sacerdote fará por ele expiação do seu pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 7, 'Mas, se as suas posses não bastarem para gado miúdo, então trará ao Senhor, como sua oferta pela culpa por aquilo em que houver pecado, duas rolas, ou dois pombinhos; um como oferta pelo pecado, e o outro como holocausto;', 1, CURRENT_TIMESTAMP, false),
(3, 5, 8, 'e os trará ao sacerdote, o qual oferecerá primeiro aquele que é para a oferta pelo pecado, e com a unha lhe fenderá a cabeça junto ao pescoço, mas não o partirá;', 1, CURRENT_TIMESTAMP, false),
(3, 5, 9, 'e do sangue da oferta pelo pecado espargirá sobre a parede do altar, porém o que restar, daquele sangue espremer-se-á à base do altar; é oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 10, 'E do outro fará holocausto conforme a ordenança; assim o sacerdote fará expiação por ele do pecado que cometeu, e ele será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 11, 'Se, porém, as suas posses não bastarem para duas rolas, ou dois pombinhos, então, como oferta por aquilo em que houver pecado, trará a décima parte duma efa de flor de farinha como oferta pelo pecado; não lhe deitará azeite nem lhe porá em cima incenso, porquanto é oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(3, 5, 12, 'e o trará ao sacerdote, o qual lhe tomará um punhado como o memorial da oferta, e a queimará sobre o altar em cima das ofertas queimadas do Senhor; é oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 13, 'Assim o sacerdote fará por ele expiação do seu pecado, que houver cometido em alguma destas coisas, e ele será perdoado; e o restante pertencerá ao sacerdote, como a oferta de cereais.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 14, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 5, 15, 'Se alguém cometer uma transgressão, e pecar por ignorância nas coisas sagradas do Senhor, então trará ao Senhor, como a sua oferta pela culpa, um carneiro sem defeito, do rebanho, conforme a tua avaliação em siclos de prata, segundo o siclo do santuário, para oferta pela culpa.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 16, 'Assim fará restituição pelo pecado que houver cometido na coisa sagrada, e ainda lhe acrescentará a quinta parte, e a dará ao sacerdote; e com o carneiro da oferta pela culpa, o sacerdote fará expiação por ele, e ele será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 17, 'Se alguém pecar, fazendo qualquer de todas as coisas que o Senhor ordenou que não se fizessem, ainda que não o soubesse, contudo será ele culpado, e levará a sua iniqüidade;', 1, CURRENT_TIMESTAMP, false),
(3, 5, 18, 'e como oferta pela culpa trará ao sacerdote um carneiro sem defeito, do rebanho, conforme a tua avaliação; e o sacerdote fará por ele expiação do erro que involuntariamente houver cometido sem o saber; e ele será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 5, 19, 'É oferta pela culpa; certamente ele se tornou culpado diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 1, 'Disse ainda o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 6, 2, 'Se alguém pecar e cometer uma transgressão contra o Senhor, e se houver dolosamente para com o seu próximo no tocante a um depósito, ou penhor, ou roubo, ou tiver oprimido a seu próximo;', 1, CURRENT_TIMESTAMP, false),
(3, 6, 3, 'se achar o perdido, e nisso se houver dolosamente e jurar falso; ou se fizer qualquer de todas as coisas em que o homem costuma pecar;', 1, CURRENT_TIMESTAMP, false),
(3, 6, 4, 'se, pois, houver pecado e for culpado, restituirá o que roubou, ou o que obteve pela opressão, ou o depósito que lhe foi dado em guarda, ou o perdido que achou,', 1, CURRENT_TIMESTAMP, false),
(3, 6, 5, 'ou qualquer coisa sobre que jurou falso; por inteiro o restituirá, e ainda a isso acrescentará a quinta parte; a quem pertence, lho dará no dia em que trouxer a sua oferta pela culpa.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 6, 'E como a sua oferta pela culpa, trará ao Senhor um carneiro sem defeito, do rebanho; conforme a tua avaliação para oferta pela culpa trá-lo-á ao sacerdote;', 1, CURRENT_TIMESTAMP, false),
(3, 6, 7, 'e o sacerdote fará expiação por ele diante do Senhor, e ele será perdoado de todas as coisas que tiver feito, nas quais se tenha tornado culpado.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 8, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 6, 9, 'Dá ordem a Arão e a seus filhos, dizendo: Esta é a lei do holocausto: o holocausto ficará a noite toda, até pela manhã, sobre a lareira do altar, e nela se conservará aceso o fogo do altar.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 10, 'E o sacerdote vestirá a sua veste de linho, e vestirá as calças de linho sobre a sua carne; e levantará a cinza, quando o fogo houver consumido o holocausto sobre o altar, e a porá junto ao altar.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 11, 'Depois despirá as suas vestes, e vestirá outras vestes; e levará a cinza para fora do arraial a um lugar limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 12, 'O fogo sobre o altar se conservará aceso; não se apagará. O sacerdote acenderá lenha nele todos os dias pela manhã, e sobre ele porá em ordem o holocausto, e queimará a gordura das ofertas pacíficas.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 13, 'O fogo se conservará continuamente aceso sobre o altar; não se apagará.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 14, 'Esta é a lei da oferta de cereais: os filhos de Arão a oferecerão perante o Senhor diante do altar.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 15, 'O sacerdote tomará dela um punhado, isto é, da flor de farinha da oferta de cereais e do azeite da mesma, e todo o incenso que estiver sobre a oferta de cereais, e os queimará sobre o altar por cheiro suave ao Senhor, como o memorial da oferta.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 16, 'E Arão e seus filhos comerão o restante dela; comê-lo-ão sem fermento em lugar santo; no átrio da tenda da revelação o comerão.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 17, 'Levedado não se cozerá. Como a sua porção das minhas ofertas queimadas lho tenho dado; coisa santíssima é, como a oferta pelo pecado, e como a oferta pela culpa.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 18, 'Todo varão entre os filhos de Arão comerá dela, como a sua porção das ofertas queimadas do Senhor; estatuto perpétuo será para as vossas gerações; tudo o que as tocar será santo.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 19, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 6, 20, 'Esta é a oferta de Arão e de seus filhos, a qual oferecerão ao Senhor no dia em que ele for ungido: a décima parte duma efa de flor de farinha, como oferta de cereais, perpetuamente, a metade dela pela amanhã, e a outra metade à tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 21, 'Numa assadeira se fará com azeite; bem embebida a trarás; em pedaços cozidos oferecerás a oferta de cereais por cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 22, 'Também o sacerdote que, de entre seus filhos, for ungido em seu lugar, a oferecerá; por estatuto perpétuo será ela toda queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 23, 'Assim toda oferta de cereais do sacerdote será totalmente queimada; não se comerá.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 24, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 6, 25, 'Fala a Arão e a seus filhos, dizendo: Esta é a lei da oferta pelo pecado: no lugar em que se imola o holocausto se imolará a oferta pelo pecado perante o Senhor; coisa santíssima é.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 26, 'O sacerdote que a oferecer pelo pecado a comerá; comê-la-á em lugar santo, no átrio da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 27, 'Tudo o que tocar a carne da oferta será santo; e quando o sangue dela for espargido sobre qualquer roupa, lavarás em lugar santo a roupa sobre a qual ele tiver sido espargido.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 28, 'Mas o vaso de barro em que for cozida será quebrado; e se for cozida num vaso de bronze, este será esfregado, e lavado, na água.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 29, 'Todo varão entre os sacerdotes comerá dela; coisa santíssima é.', 1, CURRENT_TIMESTAMP, false),
(3, 6, 30, 'Contudo não se comerá nenhuma oferta pelo pecado, da qual uma parte do sangue é trazida dentro da tenda da revelação, para fazer expiação no lugar santo; no fogo será queimada.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 1, 'Esta é a lei da oferta pela culpa: coisa santíssima é.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 2, 'No lugar em que imolam o holocausto, imolarão a oferta pela culpa, e o sangue dela se espargirá sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 3, 'Dela se oferecerá toda a gordura: a cauda gorda, e a gordura que cobre a fressura,', 1, CURRENT_TIMESTAMP, false),
(3, 7, 4, 'os dois rins e a gordura que está sobre eles, e a que está junto aos lombos, e o redenho sobre o fígado, juntamente com os rins, os tirará;', 1, CURRENT_TIMESTAMP, false),
(3, 7, 5, 'e o sacerdote os queimará sobre o altar em oferta queimada ao Senhor; é uma oferta pela culpa.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 6, 'Todo varão entre os sacerdotes comerá dela; num lugar santo se comerá; coisa santíssima é.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 7, 'Como é a oferta pelo pecado, assim será a oferta pela culpa; há uma só lei para elas, a saber, pertencerá ao sacerdote que com ela houver feito expiação.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 8, 'Também o sacerdote que oferecer o holocausto de alguém terá para si o couro do animal que tiver oferecido.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 9, 'Igualmente toda oferta de cereais que se assar ao forno, como tudo o que se preparar na frigideira e na assadeira, pertencerá ao sacerdote que a oferecer.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 10, 'Também toda oferta de cereais, seja ela amassada com azeite, ou seja seca, pertencerá a todos os filhos de Arão, tanto a um como a outro.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 11, 'Esta é a lei do sacrifício das ofertas pacíficas que se oferecerá ao Senhor:', 1, CURRENT_TIMESTAMP, false),
(3, 7, 12, 'Se alguém o oferecer por oferta de ação de graças, com o sacrifício de ação de graças oferecerá bolos ázimos amassados com azeite, e coscorões ázimos untados com azeite, e bolos amassados com azeite, de flor de farinha, bem embebidos.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 13, 'Com os bolos oferecerá pão levedado como sua oferta, com o sacrifício de ofertas pacíficas por ação de graças.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 14, 'E dele oferecerá um de cada oferta por oferta alçada ao Senhor, o qual pertencerá ao sacerdote que espargir o sangue da oferta pacífica.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 15, 'Ora, a carne do sacrifício de ofertas pacíficas por ação de graças se comerá no dia do seu oferecimento; nada se deixará dela até pela manhã.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 16, 'Se, porém, o sacrifício da sua oferta for voto, ou oferta voluntária, no dia em que for oferecido se comerá, e no dia seguinte se comerá o que dele ficar;', 1, CURRENT_TIMESTAMP, false),
(3, 7, 17, 'mas o que ainda ficar da carne do sacrifício até o terceiro dia será queimado no fogo.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 18, 'Se alguma parte da carne do sacrifício da sua oferta pacífica se comer ao terceiro dia, aquele sacrifício não será aceito, nem será imputado àquele que o tiver oferecido; coisa abominável será, e quem dela comer levará a sua iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 19, 'A carne que tocar alguma coisa imunda não se comerá; será queimada no fogo; mas da outra carne, qualquer que estiver limpo comerá dela;', 1, CURRENT_TIMESTAMP, false),
(3, 7, 20, 'todavia, se alguma pessoa, estando imunda, comer a carne do sacrifício da oferta pacífica, que pertence ao Senhor, essa pessoa será extirpada do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 21, 'E, se alguma pessoa, tendo tocado alguma coisa imunda, como imundícia de homem, ou gado imundo, ou qualquer abominação imunda, comer da carne do sacrifício da oferta pacífica, que pertence ao Senhor, essa pessoa será extirpada do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 22, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 7, 23, 'Fala aos filhos de Israel, dizendo: Nenhuma gordura de boi, nem de carneiro, nem de cabra comereis.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 24, 'Todavia pode-se usar a gordura do animal que morre por si mesmo, e a gordura do que é dilacerado por feras, para qualquer outro fim; mas de maneira alguma comereis dela.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 25, 'Pois quem quer que comer da gordura do animal, do qual se oferecer oferta queimada ao Senhor, sim, a pessoa que dela comer será extirpada do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 26, 'E nenhum sangue comereis, quer de aves, quer de gado, em qualquer das vossas habitações.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 27, 'Toda pessoa que comer algum sangue será extirpada do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 28, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 7, 29, 'Fala aos filhos de Israel, dizendo: Quem oferecer sacrifício de oferta pacífica ao Senhor trará ao Senhor a respectiva oblação da sua oferta pacífica.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 30, 'Com as próprias mãos trará as ofertas queimadas do Senhor; o peito com a gordura trará, para movê-lo por oferta de movimento perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 31, 'E o sacerdote queimará a gordura sobre o altar, mas o peito pertencerá a Arão e a seus filhos.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 32, 'E dos sacrifícios das vossas ofertas pacíficas, dareis a coxa direita ao sacerdote por oferta alçada.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 33, 'Aquele dentre os filhos de Arão que oferecer o sangue da oferta pacífica, e a gordura, esse terá a coxa direita por sua porção;', 1, CURRENT_TIMESTAMP, false),
(3, 7, 34, 'porque o peito movido e a coxa alçada tenho tomado dos filhos de Israel, dos sacrifícios das suas ofertas pacíficas, e os tenho dado a Arão, o sacerdote, e a seus filhos, como sua porção, para sempre, da parte dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 35, 'Esta é a porção sagrada de Arão e a porção sagrada de seus filhos, das ofertas queimadas do Senhor, desde o dia em que ele os apresentou para administrar o sacerdócio ao Senhor;', 1, CURRENT_TIMESTAMP, false),
(3, 7, 36, 'a qual o Senhor, no dia em que os ungiu, ordenou que se lhes desse da parte dos filhos de Israel; é a sua porção para sempre, pelas suas gerações.', 1, CURRENT_TIMESTAMP, false),
(3, 7, 37, 'Esta é a lei do holocausto, da oferta de cereais, da oferta pelo pecado, da oferta pela culpa, da oferta das consagrações, e do sacrifício das ofertas pacíficas;', 1, CURRENT_TIMESTAMP, false),
(3, 7, 38, 'a qual o Senhor entregou a Moisés no monte Sinai, no dia em que este estava ordenando aos filhos de Israel que oferecessem as suas ofertas ao Senhor, no deserto de Sinai.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 8, 2, 'Toma a Arão e a seus filhos com ele, e os vestidos, e o óleo da unção, e o novilho da oferta pelo pecado, e os dois carneiros, e o cesto de pães ázimos,', 1, CURRENT_TIMESTAMP, false),
(3, 8, 3, 'e reúne a congregação toda à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 4, 'Fez, pois, Moisés como o Senhor lhe ordenara; e a congregação se reuniu à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 5, 'E disse Moisés à congregação: Isto é o que o Senhor ordenou que se fizesse.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 6, 'Então Moisés fez chegar Arão e seus filhos, e os lavou com água,', 1, CURRENT_TIMESTAMP, false),
(3, 8, 7, 'e vestiu Arão com a túnica, cingiu-o com o cinto, e vestiu-lhe o manto, e pôs sobre ele o éfode, e cingiu-o com o cinto de obra esmerada, e com ele lhe apertou o éfode.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 8, 'Colocou-lhe, então, o peitoral, no qual pôs o Urim e o Tumim;', 1, CURRENT_TIMESTAMP, false),
(3, 8, 9, 'e pôs sobre a sua cabeça a mitra, e sobre esta, na parte dianteira, pôs a lâmina de ouro, a coroa sagrada; como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 10, 'Então Moisés, tomando o óleo da unção, ungiu o tabernáculo e tudo o que nele havia, e os santificou;', 1, CURRENT_TIMESTAMP, false),
(3, 8, 11, 'e dele espargiu sete vezes sobre o altar, e ungiu o altar e todos os seus utensílios, como também a pia e a sua base, para santificá-los.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 12, 'Em seguida derramou do óleo da unção sobre a cabeça de Arão, e ungiu-o, para santificá-lo.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 13, 'Depois Moisés fez chegar aos filhos de Arão, e os vestiu de túnicas, e os cingiu com cintos, e lhes atou tiaras; como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 14, 'Então fez chegar o novilho da oferta pelo pecado; e Arão e seus filhos puseram as mãos sobre a cabeça do novilho da oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(3, 8, 15, 'e, depois de imolar o novilho, Moisés tomou o sangue, e pôs dele com o dedo sobre as pontas do altar em redor, e purificou o altar; depois derramou o resto do sangue à base do altar, e o santificou, para fazer expiação por ele.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 16, 'Então tomou toda a gordura que estava na fressura, e o redenho do fígado, e os dois rins com a sua gordura, e os queimou sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 17, 'Mas o novilho com o seu couro, com a sua carne e com o seu excremento, queimou-o com fogo fora do arraial; como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 18, 'Depois fez chegar o carneiro do holocausto; e Arão e seus filhos puseram as mãos sobre a cabeça do carneiro.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 19, 'Havendo imolado o carneiro, Moisés espargiu o sangue sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 20, 'Partiu também o carneiro nos seus pedaços, e queimou dele a cabeça, os pedaços e a gordura.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 21, 'Mas a fressura e as pernas lavou com água; então Moisés queimou o carneiro todo sobre o altar; era holocausto de cheiro suave, uma oferta queimada ao Senhor; como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 22, 'Depois fez chegar o outro carneiro, o carneiro da consagração; e Arão e seus filhos puseram as mãos sobre a cabeça do carneiro;', 1, CURRENT_TIMESTAMP, false),
(3, 8, 23, 'e tendo Moisés imolado o carneiro, tomou do sangue deste e o pôs sobre a ponta da orelha direita de Arão, sobre o polegar da sua mão direita, e sobre o polegar do seu pé direito.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 24, 'Moisés fez chegar também os filhos de Arão, e pôs daquele sangue sobre a ponta da orelha direita deles, e sobre o polegar da sua mão direita, e sobre o polegar do seu pé direito; e espargiu o sangue sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 25, 'E tomou a gordura, e a cauda gorda, e toda a gordura que estava na fressura, e o redenho do fígado, e os dois rins com a sua gordura, e a coxa direita;', 1, CURRENT_TIMESTAMP, false),
(3, 8, 26, 'também do cesto dos pães ázimos, que estava diante do Senhor, tomou um bolo ázimo, e um bolo de pão azeitado, e um coscorão, e os pôs sobre a gordura e sobre a coxa direita;', 1, CURRENT_TIMESTAMP, false),
(3, 8, 27, 'e pôs tudo nas mãos de Arão e de seus filhos, e o ofereceu por oferta movida perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 28, 'Então Moisés os tomou das mãos deles, e os queimou sobre o altar em cima do holocausto; os quais eram uma consagração, por cheiro suave, oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 29, 'Em seguida tomou Moisés o peito, e o ofereceu por oferta movida perante o Senhor; era a parte do carneiro da consagração que tocava a Moisés, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 30, 'Tomou Moisés também do óleo da unção, e do sangue que estava sobre o altar, e o espargiu sobre Arão e suas vestes, e sobre seus filhos e as vestes de seus filhos com ele; e assim santificou tanto a Arão e suas vestes, como a seus filhos e as vestes de seus filhos com ele.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 31, 'E disse Moisés a Arão e seus filhos: Cozei a carne à porta da tenda da revelação; e ali a comereis com o pão que está no cesto da consagração, como ordenei, dizendo: Arão e seus filhos a comerão.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 32, 'Mas o que restar da carne e do pão, queimá-lo-eis ao fogo.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 33, 'Durante sete dias não saireis da porta da tenda da revelação, até que se cumpram os dias da vossa consagração; porquanto por sete dias ele vos consagrará.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 34, 'Como se fez neste dia, assim o senhor ordenou que se proceda, para fazer expiação por vós.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 35, 'Permanecereis, pois, à porta da tenda da revelação dia e noite por sete dias, e guardareis as ordenanças do Senhor, para que não morrais; porque assim me foi ordenado.', 1, CURRENT_TIMESTAMP, false),
(3, 8, 36, 'E Arão e seus filhos fizeram todas as coisas que o Senhor ordenara por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 1, 'Ora, ao dia oitavo, Moisés chamou a Arão e seus filhos, e os anciãos de Israel,', 1, CURRENT_TIMESTAMP, false),
(3, 9, 2, 'e disse a Arão: Toma um bezerro tenro para oferta pelo pecado, e um carneiro para holocausto, ambos sem defeito, e oferece-os perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 3, 'E falarás aos filhos de Israel, dizendo: Tomai um bode para oferta pelo pecado; e um bezerro e um cordeiro, ambos de um ano, e sem defeito, como holocausto;', 1, CURRENT_TIMESTAMP, false),
(3, 9, 4, 'também um boi e um carneiro para ofertas pacíficas, para sacrificar perante o Senhor e oferta de cereais, amassada com azeite; porquanto hoje o Senhor vos aparecerá.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 5, 'Então trouxeram até a entrada da tenda da revelação o que Moisés ordenara, e chegou-se toda a congregação, e ficou de pé diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 6, 'E disse Moisés: Esta é a coisa que o Senhor ordenou que fizésseis; e a glória do Senhor vos aparecerá.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 7, 'Depois disse Moisés a Arão: Chega-te ao altar, e apresenta a tua oferta pelo pecado e o teu holocausto, e faze expiação por ti e pelo povo; também apresenta a oferta do povo, e faze expiação por ele, como ordenou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 8, 'Arão, pois, chegou-se ao altar, e imolou o bezerro que era a sua própria oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 9, 'Os filhos de Arão trouxeram-lhe o sangue; e ele molhou o dedo no sangue, e o pôs sobre as pontas do altar, e derramou o sangue à base do altar;', 1, CURRENT_TIMESTAMP, false),
(3, 9, 10, 'mas a gordura, e os rins, e o redenho do fígado, tirados da oferta pelo pecado, queimou-os sobre o altar, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 11, 'E queimou ao fogo fora do arraial a carne e o couro.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 12, 'Depois imolou o holocausto, e os filhos de Arão lhe entregaram o sangue, e ele o espargiu sobre o altar em redor.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 13, 'Também lhe entregaram o holocausto, pedaço por pedaço, e a cabeça; e ele os queimou sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 14, 'E lavou a fressura e as pernas, e as queimou sobre o holocausto no altar.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 15, 'Então apresentou a oferta do povo e, tomando o bode que era a oferta pelo pecado do povo, imolou-o e o ofereceu pelo pecado, como fizera com o primeiro.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 16, 'Apresentou também o holocausto, e o ofereceu segundo a ordenança.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 17, 'E apresentou a oferta de cereais e, tomando dela um punhado, queimou-o sobre o altar, além do holocausto da manhã.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 18, 'Imolou também o boi e o carneiro em sacrifício de oferta pacífica pelo povo; e os filhos de Arão entregaram-lhe o sangue, que ele espargiu sobre o altar em redor,', 1, CURRENT_TIMESTAMP, false),
(3, 9, 19, 'como também a gordura do boi e do carneiro, a cauda gorda, e o que cobre a fressura, e os rins, e o redenho do fígado;', 1, CURRENT_TIMESTAMP, false),
(3, 9, 20, 'e puseram a gordura sobre os peitos, e ele queimou a gordura sobre o altar;', 1, CURRENT_TIMESTAMP, false),
(3, 9, 21, 'mas os peitos e a coxa direita, ofereceu-os Arão por oferta movida perante o Senhor, como Moisés tinha ordenado.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 22, 'Depois Arão, levantando as mãos para o povo, o abençoou e desceu, tendo acabado de oferecer a oferta pelo pecado, o holocausto e as ofertas pacíficas.', 1, CURRENT_TIMESTAMP, false),
(3, 9, 23, 'E Moisés e Arão entraram na tenda da revelação; depois saíram, e abençoaram o povo; e a glória do Senhor apareceu a todo o povo,', 1, CURRENT_TIMESTAMP, false),
(3, 9, 24, 'pois saiu fogo de diante do Senhor, e consumiu o holocausto e a gordura sobre o altar; o que vendo todo o povo, jubilaram e prostraram-se sobre os seus rostos.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 1, 'Ora, Nadabe, e Abiú, filhos de Arão, tomaram cada um o seu incensário e, pondo neles fogo e sobre ele deitando incenso, ofereceram fogo estranho perante o Senhor, o que ele não lhes ordenara.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 2, 'Então saiu fogo de diante do Senhor, e os devorou; e morreram perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 3, 'Disse Moisés a Arão: Isto é o que o Senhor falou, dizendo: Serei santificado naqueles que se chegarem a mim, e serei glorificado diante de todo o povo. Mas Arão guardou silêncio.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 4, 'E Moisés chamou a Misael e a Elzafã, filhos de Uziel, tio de Arão, e disse-lhes: Chegai-vos, levai vossos irmãos de diante do santuário, para fora do arraial.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 5, 'Chegaram-se, pois, e levaram-nos como estavam, nas próprias túnicas, para fora do arraial, como Moisés lhes dissera.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 6, 'Então disse Moisés a Arão, e a seus filhos Eleazar e Itamar: Não descubrais as vossas cabeças, nem rasgueis as vossas vestes, para que não morrais, nem venha a ira sobre toda a congregação; mas vossos irmãos, toda a casa de Israel, lamentem este incêndio que o Senhor acendeu.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 7, 'E não saireis da porta da tenda da revelação, para que não morrais; porque está sobre vós o óleo da unção do Senhor. E eles fizeram conforme a palavra de Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 8, 'Falou também o Senhor a Arão, dizendo:', 1, CURRENT_TIMESTAMP, false),
(3, 10, 9, 'Não bebereis vinho nem bebida forte, nem tu nem teus filhos contigo, quando entrardes na tenda da revelação, para que não morrais; estatuto perpétuo será isso pelas vossas gerações,', 1, CURRENT_TIMESTAMP, false),
(3, 10, 10, 'não somente para fazer separação entre o santo e o profano, e entre o imundo e o limpo,', 1, CURRENT_TIMESTAMP, false),
(3, 10, 11, 'mas também para ensinar aos filhos de Israel todos os estatutos que o Senhor lhes tem dado por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 12, 'Também disse Moisés a Arão, e a Eleazar e Itamar, seus filhos que lhe ficaram: Tomai a oferta de cereais que resta das ofertas queimadas do Senhor, e comei-a sem levedura junto do altar, porquanto é coisa santíssima.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 13, 'Comê-la-eis em lugar santo, porque isto é a tua porção, e a porção de teus filhos, das ofertas queimadas do Senhor; porque assim me foi ordenado.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 14, 'Também o peito da oferta movida e a coxa da oferta alçada, comê-los-eis em lugar limpo, tu, e teus filhos e tuas filhas contigo; porquanto são eles dados como tua porção, e como porção de teus filhos, dos sacrifícios das ofertas pacíficas dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 15, 'Trarão a coxa da oferta alçada e o peito da oferta movida juntamente com as ofertas queimadas da gordura, para movê-los como oferta movida perante o Senhor; isso te pertencerá como porção, a ti e a teus filhos contigo, para sempre, como o Senhor tem ordenado.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 16, 'E Moisés buscou diligentemente o bode da oferta pelo pecado, e eis que já tinha sido queimado; pelo que se indignou grandemente contra Eleazar e contra Itamar, os filhos que de Arão ficaram, e lhes disse:', 1, CURRENT_TIMESTAMP, false),
(3, 10, 17, 'Por que não comestes a oferta pelo pecado em lugar santo, visto que é coisa santíssima, e o Senhor a deu a vós para levardes a iniqüidade da congregação, para fazerdes expiação por eles diante do Senhor?', 1, CURRENT_TIMESTAMP, false),
(3, 10, 18, 'Eis que não se trouxe o seu sangue para dentro do santuário; certamente a devíeis ter comido em lugar santo, como eu havia ordenado.', 1, CURRENT_TIMESTAMP, false),
(3, 10, 19, 'Então disse Arão a Moisés: Eis que hoje ofereceram a sua oferta pelo pecado e o seu holocausto perante o Senhor, e tais coisas como essas me têm acontecido; se eu tivesse comido hoje a oferta pelo pecado, porventura teria sido isso coisa agradável aos olhos do Senhor?', 1, CURRENT_TIMESTAMP, false),
(3, 10, 20, 'Ouvindo Moisés isto, pareceu-lhe razoável.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 1, 'Falou o Senhor a Moisés e a Arão, dizendo-lhes:', 1, CURRENT_TIMESTAMP, false),
(3, 11, 2, 'Dizei aos filhos de Israel: Estes são os animais que podereis comer dentre todos os animais que há sobre a terra:', 1, CURRENT_TIMESTAMP, false),
(3, 11, 3, 'dentre os animais, todo o que tem a unha fendida, de sorte que se divide em duas, o que rumina, esse podereis comer.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 4, 'Os seguintes, contudo, não comereis, dentre os que ruminam e dentre os que têm a unha fendida: o camelo, porque rumina mas não tem a unha fendida, esse vos será imundo;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 5, 'o querogrilo, porque rumina mas não tem a unha fendida, esse vos será imundo;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 6, 'a lebre, porque rumina mas não tem a unha fendida, essa vos será imunda;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 7, 'e o porco, porque tem a unha fendida, de sorte que se divide em duas, mas não rumina, esse vos será imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 8, 'Da sua carne não comereis, nem tocareis nos seus cadáveres; esses vos serão imundos.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 9, 'Estes são os que podereis comer de todos os que há nas águas: todo o que tem barbatanas e escamas, nas águas, nos mares e nos rios, esse podereis comer.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 10, 'Mas todo o que não tem barbatanas, nem escamas, nos mares e nos rios, todo réptil das águas, e todos os animais que vivem nas águas, estes vos serão abomináveis,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 11, 'tê-los-eis em abominação; da sua carne não comereis, e abominareis os seus cadáveres.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 12, 'Tudo o que não tem barbatanas nem escamas, nas águas, será para vós abominável.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 13, 'Dentre as aves, a estas abominareis; não se comerão, serão abomináveis: a águia, o quebrantosso, o xofrango,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 14, 'o açor, o falcão segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 15, 'todo corvo segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 16, 'o avestruz, o mocho, a gaivota, o gavião segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 17, 'o bufo, o corvo marinho, a coruja,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 18, 'o porfirião, o pelicano, o abutre,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 19, 'a cegonha, a garça segundo a sua, espécie, a poupa e o morcego.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 20, 'Todos os insetos alados que andam sobre quatro pés, serão para vós uma abominação.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 21, 'Contudo, estes há que podereis comer de todos os insetos alados que andam sobre quatro pés: os que têm pernas sobre os seus pés, para saltar com elas sobre a terra;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 22, 'isto é, deles podereis comer os seguintes: o gafanhoto segundo a sua espécie, o solham segundo a sua espécie, o hargol segundo a sua espécie e o hagabe segundo a sua espécie.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 23, 'Mas todos os outros insetos alados que têm quatro pés, serão para vós uma abominação.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 24, 'Também por eles vos tornareis imundos; qualquer que tocar nos seus cadáveres, será imundo até a tarde,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 25, 'e quem levar qualquer parte dos seus cadáveres, lavará as suas vestes, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 26, 'Todo animal que tem unhas fendidas, mas cuja fenda não as divide em duas, e que não rumina, será para vós imundo; qualquer que tocar neles será imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 27, 'Todos os plantígrados dentre os quadrúpedes, esses vos serão imundos; qualquer que tocar nos seus cadáveres será imundo até a tarde,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 28, 'e o que levar os seus cadáveres lavará as suas vestes, e será imundo até a tarde; eles serão para vós imundos.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 29, 'Estes também vos serão por imundos entre os animais que se arrastam sobre a terra: a doninha, o rato, o crocodilo da terra segundo a sua espécie,', 1, CURRENT_TIMESTAMP, false),
(3, 11, 30, 'o musaranho, o crocodilo da água, a lagartixa, o lagarto e a toupeira.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 31, 'Esses vos serão imundos dentre todos os animais rasteiros; qualquer que os tocar, depois de mortos, será imundo até a tarde;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 32, 'e tudo aquilo sobre o que cair o cadáver de qualquer deles será imundo; seja vaso de madeira, ou vestidura, ou pele, ou saco, seja qualquer instrumento com que se faz alguma obra, será metido na água, e será imundo até a tarde; então será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 33, 'E quanto a todo vaso de barro dentro do qual cair algum deles, tudo o que houver nele será imundo, e o vaso quebrareis.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 34, 'Todo alimento depositado nele, que se pode comer, sobre o qual vier água, será imundo; e toda bebida que se pode beber, sendo depositada em qualquer destes vasos será imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 35, 'E tudo aquilo sobre o que cair: alguma parte dos cadáveres deles será imundo; seja forno, seja fogão, será quebrado; imundos são, portanto para vós serão imundos.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 36, 'Contudo, uma fonte ou cisterna, em que há depósito de água, será limpa; mas quem tocar no cadáver será imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 37, 'E, se dos seus cadáveres cair alguma coisa sobre alguma semente que se houver de semear, esta será limpa;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 38, 'mas se for deitada água sobre a semente, e se dos cadáveres cair alguma coisa sobre ela, então ela será para vós imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 39, 'E se morrer algum dos animais de que vos é lícito comer, quem tocar no seu cadáver será imundo até a tarde;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 40, 'e quem comer do cadáver dele lavará as suas vestes, e será imundo até a tarde; igualmente quem levar o cadáver dele lavará as suas vestes, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 41, 'Também todo animal rasteiro que se move sobre a terra será abominação; não se comerá.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 42, 'Tudo o que anda sobre o ventre, tudo o que anda sobre quatro pés, e tudo o que tem muitos pés, enfim todos os animais rasteiros que se movem sobre a terra, desses não comereis, porquanto são abomináveis.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 43, 'Não vos tomareis abomináveis por nenhum animal rasteiro, nem neles vos contaminareis, para não vos tornardes imundos por eles.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 44, 'Porque eu sou o Senhor vosso Deus; portanto santificai-vos, e sede santos, porque eu sou santo; e não vos contaminareis com nenhum animal rasteiro que se move sobre a terra;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 45, 'porque eu sou o Senhor, que vos fiz subir da terra do Egito, para ser o vosso Deus, sereis pois santos, porque eu sou santo.', 1, CURRENT_TIMESTAMP, false),
(3, 11, 46, 'Esta é a lei sobre os animais e as aves, e sobre toda criatura vivente que se move nas águas e toda criatura que se arrasta sobre a terra;', 1, CURRENT_TIMESTAMP, false),
(3, 11, 47, 'para fazer separação entre o imundo e o limpo, e entre os animais que se podem comer e os animais que não se podem comer.', 1, CURRENT_TIMESTAMP, false),
(3, 12, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 12, 2, 'Fala aos filhos de Israel, dizendo: Se uma mulher conceber e tiver um menino, será imunda sete dias; assim como nos dias da impureza da sua enfermidade, será imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 12, 3, 'E no dia oitavo se circuncidará ao menino a carne do seu prepúcio.', 1, CURRENT_TIMESTAMP, false),
(3, 12, 4, 'Depois permanecerá ela trinta e três dias no sangue da sua purificação; em nenhuma coisa sagrada tocará, nem entrará no santuário até que se cumpram os dias da sua purificação.', 1, CURRENT_TIMESTAMP, false),
(3, 12, 5, 'Mas, se tiver uma menina, então será imunda duas semanas, como na sua impureza; depois permanecerá sessenta e seis dias no sangue da sua purificação.', 1, CURRENT_TIMESTAMP, false),
(3, 12, 6, 'E, quando forem cumpridos os dias da sua purificação, seja por filho ou por filha, trará um cordeiro de um ano para holocausto, e um pombinho ou uma rola para oferta pelo pecado, à porta da tenda da revelação, o ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 12, 7, 'o qual o oferecerá perante o Senhor, e fará, expiação por ela; então ela será limpa do fluxo do seu sangue. Esta é a lei da que der à luz menino ou menina.', 1, CURRENT_TIMESTAMP, false),
(3, 12, 8, 'Mas, se as suas posses não bastarem para um cordeiro, então tomará duas rolas, ou dois pombinhos: um para o holocausto e outro para a oferta pelo pecado; assim o sacerdote fará expiação por ela, e ela será limpa.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 1, 'Falou mais o Senhor a Moisés e a Arão, dizendo:', 1, CURRENT_TIMESTAMP, false),
(3, 13, 2, 'Quando um homem tiver na pele da sua carne inchação, ou pústula, ou mancha lustrosa, e esta se tornar na sua pele como praga de lepra, então será levado a Arão o sacerdote, ou a um de seus filhos, os sacerdotes,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 3, 'e o sacerdote examinará a praga na pele da carne. Se o pêlo na praga se tiver tornado branco, e a praga parecer mais profunda que a pele, é praga de lepra; o sacerdote, verificando isto, o declarará imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 4, 'Mas, se a mancha lustrosa na sua pele for branca, e não parecer mais profunda que a pele, e o pêlo não se tiver tornado branco, o sacerdote encerrará por sete dias aquele que tem a praga.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 5, 'Ao sétimo dia o sacerdote o examinará; se a praga, na sua opinião, tiver parado e não se tiver estendido na pele, o sacerdote o encerrará por outros sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 6, 'Ao sétimo dia o sacerdote o examinará outra vez; se a praga tiver escurecido, não se tendo estendido na pele, o sacerdote o declarará limpo; é uma pústula. O homem lavará as suas vestes, e será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 7, 'Mas se a pústula se estender muito na pele, depois de se ter mostrado ao sacerdote para a sua purificação, mostrar-se-á de novo ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 8, 'o qual o examinará; se a pústula se tiver estendido na pele, o sacerdote o declarará imundo; é lepra.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 9, 'Quando num homem houver praga de lepra, será ele levado ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 10, 'o qual o examinará; se houver na pele inchação branca que tenha tornado branco o pêlo, e houver carne viva na inchação,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 11, 'lepra inveterada é na sua pele. Portanto, o sacerdote o declarará imundo; não o encerrará, porque imundo é.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 12, 'Se a lepra se espalhar muito na pele, e cobrir toda a pele do que tem a praga, desde a cabeça até os pés, quanto podem ver os olhos do sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 13, 'este o examinará; e, se a lepra tiver coberto a carne toda, declarará limpo o que tem a praga; ela toda se tornou branca; o homem é limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 14, 'Mas no dia em que nele aparecer carne viva será imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 15, 'Examinará, pois, o sacerdote a carne viva, e declarará o homem imundo; a carne viva é imunda; é lepra.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 16, 'Ou, se a carne viva mudar, e ficar de novo branca, ele virá ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 17, 'e este o examinará; se a praga se tiver tornado branca, o sacerdote declarará limpo o que tem a praga; limpo está.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 18, 'Quando também a carne tiver na sua pele alguma úlcera, se esta sarar,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 19, 'e em seu lugar vier inchação branca ou mancha lustrosa, tirando a vermelho, mostrar-se-á ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 20, 'e este a examinará; se ela parecer mais profunda que a pele, e o pêlo se tiver tornado branco, o sacerdote declarará imundo o homem; é praga de lepra, que brotou na úlcera.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 21, 'Se, porém, o sacerdote a examinar, e nela não houver pêlo branco e não estiver mais profunda que a pele, mas tiver escurecido, o sacerdote encerrará por sete dias o homem.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 22, 'Se ela se estender na pele, o sacerdote o declarará imundo; é praga.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 23, 'Mas se a mancha lustrosa parar no seu lugar, não se estendendo, é a cicatriz da úlcera; o sacerdote, pois, o declarará limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 24, 'Ou, quando na pele da carne houver queimadura de fogo, e a carne viva da queimadura se tornar em mancha lustrosa, tirando a vermelho ou branco,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 25, 'o sacerdote a examinará, e se o pêlo na mancha lustrosa se tiver tornado branco, e ela parecer mais profunda que a pele, é lepra; brotou na queimadura; portanto o sacerdote o declarará imundo; é praga de lepra.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 26, 'Mas se o sacerdote a examinar, e na mancha lustrosa não houver pêlo branco, nem estiver mais profunda que a pele, mas tiver escurecido, o sacerdote o encerrará por sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 27, 'Ao sétimo dia o sacerdote o examinará. Se ela se houver estendido na pele, o sacerdote o declarará imundo; é praga de lepra.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 28, 'Mas se a mancha lustrosa tiver parado no seu lugar, não se estendendo na pele, e tiver escurecido, é a inchação da queimadura; portanto o sacerdote o declarará limpo; porque é a cicatriz da queimadura.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 29, 'E quando homem {ou mulher} tiver praga na cabeça ou na barba,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 30, 'o sacerdote examinará a praga, e se ela parecer mais profunda que a pele, e nela houver pêlo fino amarelo, o sacerdote o declarará imundo; é tinha, é lepra da cabeça ou da barba.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 31, 'Mas se o sacerdote examinar a praga da tinha, e ela não parecer mais profunda que a pele, e nela não houver pêlo preto, o sacerdote encerrará por sete dias o que tem a praga da tinha.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 32, 'Ao sétimo dia o sacerdote examinará a praga; se a tinha não se tiver estendido, e nela não houver pêlo amarelo, nem a tinha parecer mais profunda que a pele,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 33, 'o homem se rapará, mas não rapará a tinha; e o sacerdote encerrará por mais sete dias o que tem a tinha.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 34, 'Ao sétimo dia o sacerdote examinará a tinha; se ela não se houver estendido na pele, e não parecer mais profunda que a pele, o sacerdote declarará limpo o homem; o qual lavará as suas vestes, e será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 35, 'Mas se, depois da sua purificação, a tinha estender na pele,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 36, 'o sacerdote o examinará; se a tinha se tiver estendido na pele, o sacerdote não buscará pêlo amarelo; o homem está imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 37, 'Mas se a tinha, a seu ver, tiver parado, e nela tiver crescido pêlo preto, a tinha terá sarado; limpo está o homem; portanto o sacerdote o declarará limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 38, 'Quando homem {ou mulher} tiver na pele da sua carne manchas lustrosas, isto é, manchas lustrosas brancas,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 39, 'o sacerdote as examinará; se essas manchas lustrosas forem brancas tirando a escuro, é impigem que brotou na pele; o homem é limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 40, 'Quando a cabeça do homem se pelar, ele é calvo; contudo é limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 41, 'E, se a frente da sua cabeça se pelar, ele é meio calvo; contudo é limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 42, 'Mas se na calva, ou na meia calva, houver praga branca tirando a vermelho, é lepra que lhe está brotando na calva ou na meia calva.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 43, 'Então o sacerdote o examinará, e se a inchação da praga na calva ou na meia calva for branca tirando a vermelho, como parece a lepra na pele da carne,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 44, 'leproso é aquele homem, é imundo; o sacerdote certamente o declarará imundo; na sua cabeça está a praga.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 45, 'Também as vestes do leproso, em quem está a praga, serão rasgadas; ele ficará com a cabeça descoberta e de cabelo solto, mas cobrirá o bigode, e clamará: Imundo, imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 46, 'Por todos os dias em que a praga estiver nele, será imundo; imundo é; habitará só; a sua habitação será fora do arraial.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 47, 'Quando também houver praga de lepra em alguma vestidura, seja em vestidura de lã ou em vestidura de linho,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 48, 'quer na urdidura, quer na trama, seja de linho ou seja de lã; ou em pele, ou em qualquer obra de pele;', 1, CURRENT_TIMESTAMP, false),
(3, 13, 49, 'se a praga na vestidura, quer na urdidura, quer na trama, ou na pele, ou em qualquer coisa de pele, for verde ou vermelha, é praga de lepra, pelo que se mostrará ao sacerdote;', 1, CURRENT_TIMESTAMP, false),
(3, 13, 50, 'o sacerdote examinará a praga, e encerrará por sete dias aquilo que tem a praga.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 51, 'Ao sétimo dia examinará a praga; se ela se houver estendido na vestidura, quer na urdidura, quer na trama, ou na pele, seja qual for a obra em que se empregue, a praga é lepra roedora; é imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 52, 'Pelo que se queimará aquela vestidura, seja a urdidura ou a trama, seja de lã ou de linho, ou qualquer obra de pele, em que houver a praga, porque é lepra roedora; queimar-se-á ao fogo.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 53, 'Mas se o sacerdote a examinar, e ela não se tiver estendido na vestidura, seja na urdidura, seja na trama, ou em qualquer obra de pele,', 1, CURRENT_TIMESTAMP, false),
(3, 13, 54, 'o sacerdote ordenará que se lave aquilo, em que está a praga, e o encerrará por mais sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 55, 'O sacerdote examinará a praga, depois de lavada, e se ela não tiver mudado de cor, nem se tiver estendido, é imunda; no fogo a queimarás; é praga penetrante, seja por dentro, seja por fora.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 56, 'Mas se o sacerdote a examinar, e a praga tiver escurecido, depois de lavada, então a rasgará da vestidura, ou da pele, ou da urdidura, ou da trama;', 1, CURRENT_TIMESTAMP, false),
(3, 13, 57, 'se ela ainda aparecer na vestidura, seja na urdidura, seja na trama, ou em qualquer coisa de pele, é lepra brotante; no fogo queimarás aquilo em que há a praga.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 58, 'Mas a vestidura, quer a urdidura, quer a trama, ou qualquer coisa de pele, que lavares, e de que a praga se retirar, se lavará segunda vez, e será limpa.', 1, CURRENT_TIMESTAMP, false),
(3, 13, 59, 'Esta é a lei da praga da lepra na vestidura de lã, ou de linho, quer na urdidura, quer na rama, ou em qualquer coisa de pele, para declará-la limpa, ou para declará-la imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 1, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 14, 2, 'Esta será a lei do leproso no dia da sua purificação: será levado ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 3, 'e este sairá para fora do arraial, e o examinará; se a praga do leproso tiver sarado,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 4, 'o sacerdote ordenará que, para aquele que se há de purificar, se tomem duas aves vivas e limpas, pau de cedro, carmesim e hissopo.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 5, 'Mandará também que se imole uma das aves num vaso de barro sobre águas vivas.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 6, 'Tomará a ave viva, e com ela o pau de cedro, o carmesim e o hissopo, os quais molhará, juntamente com a ave viva, no sangue da ave que foi imolada sobre as águas vivas;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 7, 'e o espargirá sete vezes sobre aquele que se há de purificar da lepra; então o declarará limpo, e soltará a ave viva sobre o campo aberto.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 8, 'Aquele que se há de purificar lavará as suas vestes, rapará todo o seu pêlo e se lavará em água; assim será limpo. Depois entrará no arraial, mas ficará fora da sua tenda por sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 9, 'Ao sétimo dia rapará todo o seu pêlo, tanto a cabeça como a barba e as sobrancelhas, sim, rapará todo o pêlo; também lavará as suas vestes, e banhará o seu corpo em água; assim será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 10, 'Ao oitavo dia tomará dois cordeiros sem defeito, e uma cordeira sem defeito, de um ano, e três décimos de efa de flor de farinha para oferta de cereais, amassada com azeite, e um logue de azeite;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 11, 'e o sacerdote que faz a purificação apresentará o homem que se há de purificar, bem como aquelas coisas, perante o Senhor, à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 12, 'E o sacerdote tomará um dos cordeiros, o oferecerá como oferta pela culpa; e, tomando também o logue de azeite, os moverá por oferta de movimento perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 13, 'E imolará o cordeiro no lugar em que se imola a oferta pelo pecado e o holocausto, no lugar santo; porque, como a oferta pelo pecado pertence ao sacerdote, assim também a oferta pela culpa; é coisa santíssima.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 14, 'Então o sacerdote tomará do sangue da oferta pela culpa e o porá sobre a ponta da orelha direita daquele que se há de purificar, e sobre o dedo polegar da sua mão direita, e sobre o dedo polegar do seu pé direito.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 15, 'Tomará também do logue de azeite, e o derramará na palma da sua própria mão esquerda;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 16, 'então molhará o dedo direito no azeite que está na mão esquerda, e daquele azeite espargirá com o dedo sete vezes perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 17, 'Do restante do azeite que está na sua mão, o sacerdote porá sobre a ponta da orelha direita daquele que se há de purificar, e sobre o dedo polegar da sua mão direita, e sobre o dedo polegar do seu pé direito, por cima do sangue da oferta pela culpa;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 18, 'e o restante do azeite que está na sua mão, pô-lo-á sobre a cabeça daquele que se há de purificar; assim o sacerdote fará expiação por ele perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 19, 'Também o sacerdote oferecerá a oferta pelo pecado, e fará expiação por aquele que se há de purificar por causa a sua imundícia; e depois imolará o holocausto,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 20, 'e oferecerá o holocausto e a oferta de cereais sobre o altar; assim o sacerdote fará expiação por ele, e ele será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 21, 'Mas se for pobre, e as suas posses não bastarem para tanto, tomará um cordeiro para oferta pela culpa como oferta de movimento, para fazer expiação por ele, um décimo de efa de flor de farinha amassada com azeite, para oferta de cereais, um logue de azeite,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 22, 'e duas rolas ou dois pombinhos, conforme suas posses permitirem; dos quais um será oferta pelo pecado, e o outro holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 23, 'Ao oitavo dia os trará, para a sua purificação, ao sacerdote, à porta da tenda da revelação, perante o Senhor;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 24, 'e o sacerdote tomará o cordeiro da oferta pela culpa, e o logue de azeite, e os moverá por oferta de movimento perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 25, 'Então imolará o cordeiro da oferta pela culpa e, tomando do sangue da oferta pela culpa, pô-lo-á sobre a ponta da orelha direita daquele que se há de purificar, e sobre o dedo polegar da sua mão direita, e sobre o dedo polegar do seu pé direito.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 26, 'Também o sacerdote derramará do azeite na palma da sua própria mão esquerda;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 27, 'e com o dedo direito espargirá do azeite que está na mão esquerda, sete vezes perante o Senhor;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 28, 'igualmente, do azeite que está na mão, porá na ponta da orelha direita daquele que se há de purificar, e no dedo polegar da sua mão direita, e no dedo polegar do seu pé direito, em cima do lugar do sangue da oferta pela culpa;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 29, 'e o restante do azeite que está na mão porá sobre a cabeça daquele que se há de purificar, para fazer expiação por ele perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 30, 'Então oferecerá uma das rolas ou um dos pombinhos, conforme as suas posses lhe permitirem,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 31, 'sim, conforme as suas posses, um para oferta pelo pecado, e o outro como holocausto, juntamente com a oferta de cereais; assim fará o sacerdote, perante o Senhor, expiação por aquele que se há de purificar.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 32, 'Esta é a lei daquele em quem estiver a praga da lepra, e cujas posses não lhe permitirem apresentar a oferta estipulada para a sua purificação.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 33, 'Disse mais o Senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(3, 14, 34, 'Quando tiverdes entrado na terra de Canaã, que vos dou em possessão, e eu puser a praga da lepra em alguma casa da terra da vossa possessão,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 35, 'aquele a quem pertencer a casa virá e informará ao sacerdote, dizendo: Parece-me que há como que praga em minha casa.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 36, 'E o sacerdote ordenará que despejem a casa, antes que entre para examinar a praga, para que não se torne imundo tudo o que está na casa; depois entrará o sacerdote para examinar a casa;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 37, 'examinará a praga, e se ela estiver nas paredes da casa em covinhas verdes ou vermelhas, e estas parecerem mais profundas que a superfície,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 38, 'o sacerdote, saindo daquela casa, deixá-la-á fechada por sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 39, 'Ao sétimo dia voltará o sacerdote e a examinará; se a praga se tiver estendido nas paredes da casa,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 40, 'o sacerdote ordenará que arranquem as pedras em que estiver a praga, e que as lancem fora da cidade, num lugar imundo;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 41, 'e fará raspar a casa por dentro ao redor, e o pó que houverem raspado deitarão fora da cidade, num lugar imundo;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 42, 'depois tomarão outras pedras, e as porão no lugar das primeiras; e outra argamassa se tomará, e se rebocará a casa.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 43, 'Se, porém, a praga tornar a brotar na casa, depois de arrancadas as pedras, raspada a casa e de novo rebocada,', 1, CURRENT_TIMESTAMP, false),
(3, 14, 44, 'o sacerdote entrará, e a examinará; se a praga se tiver estendido na casa, lepra roedora há na casa; é imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 45, 'Portanto se derrubará a casa, as suas pedras, e a sua madeira, como também toda a argamassa da casa, e se levará tudo para fora da cidade, a um lugar imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 46, 'Aquele que entrar na casa, enquanto estiver fechada, será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 47, 'Aquele que se deitar na casa lavará, as suas vestes; e quem comer na casa lavara as suas vestes.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 48, 'Mas, tornando o sacerdote a entrar, e examinando a casa, se a praga não se tiver estendido nela, depois de ter sido rebocada, o sacerdote declarará limpa a casa, porque a praga está curada.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 49, 'E, para purificar a casa, tomará duas aves, pau de cedro, carmesim e hissopo;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 50, 'imolará uma das aves num vaso de barro sobre águas vivas;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 51, 'tomará o pau de cedro, o hissopo, o carmesim e a ave viva, e os molhará no sangue da ave imolada e nas águas vivas, e espargirá a casa sete vezes;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 52, 'assim purificará a casa com o sangue da ave, com as águas vivas, com a ave viva, com o pau de cedro, com o hissopo e com o carmesim;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 53, 'mas soltará a ave viva para fora da cidade para o campo aberto; assim fará expiação pela casa, e ela será limpa.', 1, CURRENT_TIMESTAMP, false),
(3, 14, 54, 'Esta é a lei de toda sorte de praga de lepra e de tinha;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 55, 'da lepra das vestes e das casas;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 56, 'da inchação, das pústulas e das manchas lustrosas;', 1, CURRENT_TIMESTAMP, false),
(3, 14, 57, 'para ensinar quando alguma coisa será imunda, e quando será limpa. Esta é a lei da lepra.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 1, 'Disse ainda o Senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(3, 15, 2, 'Falai aos filhos de Israel, e dizei-lhes: Qualquer homem que tiver fluxo da sua carne, por causa do seu fluxo será imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 3, 'Esta, pois, será a sua imundícia por causa do seu fluxo: se a sua carne vasa o seu fluxo, ou se a sua carne estanca o seu fluxo, esta é a sua imundícia.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 4, 'Toda cama em que se deitar aquele que tiver fluxo será imunda; e toda coisa sobre o que se sentar, será imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 5, 'E, qualquer que tocar na cama dele lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 6, 'E aquele que se sentar sobre aquilo em que se sentou o que tem o fluxo, lavará as suas vestes, e se banhará em água; e será imundo até a tarde,', 1, CURRENT_TIMESTAMP, false),
(3, 15, 7, 'Também aquele que tocar na carne do que tem o fluxo, lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 8, 'Quando o que tem o fluxo cuspir sobre um limpo, então lavará este as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 9, 'Também toda sela, em que cavalgar o que tem o fluxo, será imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 10, 'E qualquer que tocar em alguma coisa que tiver estado debaixo dele será imundo até a tarde; e aquele que levar alguma dessas coisas, lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 11, 'Também todo aquele em quem tocar o que tiver o fluxo, sem haver antes lavado as mãos em água, lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 12, 'Todo vaso de barro em que tocar o que tiver o fluxo será quebrado; porém todo vaso de madeira será lavado em água.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 13, 'Quando, pois, o que tiver o fluxo e ficar limpo do seu fluxo, contará para si sete dias para a sua purificação, lavará as suas vestes, banhará o seu corpo em águas vivas, e será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 14, 'Ao oitavo dia tomará para si duas rolas, ou dois pombinhos, e virá perante o Senhor, à porta da tenda da revelação, e os dará ao sacerdote,', 1, CURRENT_TIMESTAMP, false),
(3, 15, 15, 'o qual os oferecerá, um para oferta pelo pecado, e o outro para holocausto; e assim o sacerdote fará por ele expiação perante o Senhor, por causa do seu fluxo.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 16, 'Também se sair de um homem o seu sêmen banhará o seu corpo todo em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 17, 'E toda vestidura, e toda pele sobre que houver sêmen serão lavadas em água, e serão imundas até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 18, 'Igualmente quanto à mulher com quem o homem se deitar com sêmen ambos se banharão em água, e serão imundos até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 19, 'Mas a mulher, quando tiver fluxo, e o fluxo na sua carne for sangue, ficará na sua impureza por sete dias, e qualquer que nela tocar será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 20, 'E tudo aquilo sobre o que ela se deitar durante a sua impureza, será imundo; e tudo sobre o que se sentar, será imundo.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 21, 'Também qualquer que tocar na sua cama, lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 22, 'E quem tocar em alguma coisa, sobre o que ela se tiver sentado, lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 23, 'Se o sangue estiver sobre a cama, ou sobre alguma coisa em que ela se sentar, quando alguém tocar nele, será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 24, 'E se, com efeito, qualquer homem se deitar com ela, e a sua imundícia ficar sobre ele, imundo será por sete dias; também toda cama, sobre que ele se deitar, será imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 25, 'Se uma mulher tiver um fluxo de sangue por muitos dias fora do tempo da sua impureza, ou quando tiver fluxo de sangue por mais tempo do que a sua impureza, por todos os dias do fluxo da sua imundícia será como nos dias da sua impureza; imunda será.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 26, 'Toda cama sobre que ela se deitar durante todos os dias do seu fluxo ser-lhe-á como a cama da sua impureza; e toda coisa sobre que se sentar será imunda, conforme a imundícia da sua impureza.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 27, 'E qualquer que tocar nessas coisas será imundo; portanto lavará as suas vestes, e se banhará em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 28, 'Quando ela ficar limpa do seu fluxo, contará para si sete dias, e depois será limpa.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 29, 'Ao oitavo dia tomará para si duas rolas, ou dois pombinhos, e os trará ao sacerdote, à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 30, 'Então o sacerdote oferecerá um deles para oferta pelo pecado, e o outro para holocausto; e o sacerdote fará por ela expiação perante o Senhor, por causa do fluxo da sua imundícia.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 31, 'Assim separareis os filhos de Israel da sua imundícia, para que não morram na sua imundícia, contaminando o meu tabernáculo, que está no meio deles.', 1, CURRENT_TIMESTAMP, false),
(3, 15, 32, 'Esta é a lei daquele que tem o fluxo e daquele de quem sai o sêmen de modo que por eles se torna imundo;', 1, CURRENT_TIMESTAMP, false),
(3, 15, 33, 'como também da mulher enferma com a sua impureza e daquele que tem o fluxo, tanto do homem como da mulher, e do homem que se deita com mulher imunda.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 1, 'Falou o Senhor a Moisés, depois da morte dos dois filhos de Arão, que morreram quando se chegaram diante do Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 2, 'Disse, pois, o Senhor a Moisés: Dize a Arão, teu irmão, que não entre em todo tempo no lugar santo, para dentro do véu, diante do propiciatório que está sobre a arca, para que não morra; porque aparecerei na nuvem sobre o propiciatório.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 3, 'Com isto entrará Arão no lugar santo: com um novilho, para oferta pelo pecado, e um carneiro para holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 4, 'Vestirá ele a túnica sagrada de linho, e terá as calças de linho sobre a sua carne, e cingir-se-á com o cinto de linho, e porá na cabeça a mitra de linho; essas são as vestes sagradas; por isso banhará o seu corpo em água, e as vestirá.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 5, 'E da congregação dos filhos de Israel tomará dois bodes para oferta pelo pecado e um carneiro para holocausto.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 6, 'Depois Arão oferecerá o novilho da oferta pelo pecado, o qual será para ele, e fará expiação por si e pela sua casa.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 7, 'Também tomará os dois bodes, e os porá perante o Senhor, à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 8, 'E Arão lançará sortes sobre os dois bodes: uma pelo Senhor, e a outra por Azazel.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 9, 'Então apresentará o bode sobre o qual cair a sorte pelo Senhor, e o oferecerá como oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(3, 16, 10, 'mas o bode sobre que cair a sorte para Azazel será posto vivo perante o Senhor, para fazer expiação com ele a fim de enviá-lo ao deserto para Azazel.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 11, 'Arão, pois, apresentará o novilho da oferta pelo pecado, que é por ele, e fará expiação por si e pela sua casa; e imolará o novilho que é a sua oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 12, 'Então tomará um incensário cheio de brasas de fogo de sobre o altar, diante do Senhor, e dois punhados de incenso aromático bem moído, e os trará para dentro do véu;', 1, CURRENT_TIMESTAMP, false),
(3, 16, 13, 'e porá o incenso sobre o fogo perante o Senhor, a fim de que a nuvem o incenso cubra o propiciatório, que está sobre o testemunho, para que não morra.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 14, 'Tomará do sangue do novilho, e o espargirá com o dedo sobre o propiciatório ao lado oriental; e perante o propiciatório espargirá do sangue sete vezes com o dedo.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 15, 'Depois imolará o bode da oferta pelo pecado, que é pelo povo, e trará o sangue o bode para dentro do véu; e fará com ele como fez com o sangue do novilho, espargindo-o sobre o propiciatório, e perante o propiciatório;', 1, CURRENT_TIMESTAMP, false),
(3, 16, 16, 'e fará expiação pelo santuário por causa das imundícias dos filhos de Israel e das suas transgressões, sim, de todos os seus pecados. Assim também fará pela tenda da revelação, que permanece com eles no meio das suas imundícias.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 17, 'Nenhum homem estará na tenda da revelação quando Arão entrar para fazer expiação no lugar santo, até que ele saia, depois de ter feito expiação por si mesmo, e pela sua casa, e por toda a congregação de Israel.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 18, 'Então sairá ao altar, que está perante o Senhor, e fará expiação pelo altar; tomará do sangue do novilho, e do sangue do bode, e o porá sobre as pontas do altar ao redor.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 19, 'E do sangue espargirá com o dedo sete vezes sobre o altar, purificando-o e santificando-o das imundícias dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 20, 'Quando Arão houver acabado de fazer expiação pelo lugar santo, pela tenda da revelação, e pelo altar, apresentará o bode vivo;', 1, CURRENT_TIMESTAMP, false),
(3, 16, 21, 'e, pondo as mãos sobre a cabeça do bode vivo, confessará sobre ele todas as iniqüidades dos filhos de Israel, e todas as suas transgressões, sim, todos os seus pecados; e os porá sobre a cabeça do bode, e enviá-lo-á para o deserto, pela mão de um homem designado para isso.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 22, 'Assim aquele bode levará sobre si todas as iniqüidades deles para uma região solitária; e esse homem soltará o bode no deserto.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 23, 'Depois Arão entrará na tenda da revelação, e despirá as vestes de linho, que havia vestido quando entrara no lugar santo, e ali as deixará.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 24, 'E banhará o seu corpo em água num lugar santo, e vestirá as suas próprias vestes; então sairá e oferecerá o seu holocausto, e o holocausto do povo, e fará expiação por si e pelo povo.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 25, 'Também queimará sobre o altar a gordura da oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 26, 'E aquele que tiver soltado o bode para Azazel lavará as suas vestes, e banhará o seu corpo em água, e depois entrará no arraial.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 27, 'Mas o novilho da oferta pelo pecado e o bode da oferta pelo pecado, cujo sangue foi trazido para fazer expiação no lugar santo, serão levados para fora do arraial; e lhes queimarão no fogo as peles, a carne e o excremento.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 28, 'Aquele que os queimar lavará as suas vestes, banhara o seu corpo em água, e depois entrará no arraial.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 29, 'Também isto vos será por estatuto perpétuo: no sétimo mês, aos dez do mês, afligireis as vossas almas, e não fareis trabalho algum, nem o natural nem o estrangeiro que peregrina entre vos;', 1, CURRENT_TIMESTAMP, false),
(3, 16, 30, 'porque nesse dia se fará expiação por vós, para purificar-vos; de todos os vossos pecados sereis purificados perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 31, 'Será sábado de descanso solene para vós, e afligireis as vossas almas; é estatuto perpétuo.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 32, 'E o sacerdote que for ungido e que for sagrado para administrar o sacerdócio no lugar de seu pai, fará a expiação, havendo vestido as vestes de linho, isto é, as vestes sagradas;', 1, CURRENT_TIMESTAMP, false),
(3, 16, 33, 'assim fará expiação pelo santuário; também fará expiação pela tenda da revelação e pelo altar; igualmente fará expiação e pelos sacerdotes e por todo o povo da congregação.', 1, CURRENT_TIMESTAMP, false),
(3, 16, 34, 'Isto vos será por estatuto perpétuo, para fazer expiação uma vez no ano pelos filhos de Israel por causa de todos os seus pecados. E fez Arão como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 17, 2, 'Fala a Arão e aos seus filhos, e a s todos os filhos de Israel, e dize-lhes: Isto é o que o Senhor tem ordenado:', 1, CURRENT_TIMESTAMP, false),
(3, 17, 3, 'Qualquer homem da casa de Israel que imolar boi, ou cordeiro, ou cabra, no arraial, ou fora do arraial,', 1, CURRENT_TIMESTAMP, false),
(3, 17, 4, 'e não o trouxer à porta da tenda da revelação, para o oferecer como oferta ao Senhor diante do tabernáculo do Senhor, a esse homem será imputado o sangue; derramou sangue, pelo que será extirpado do seu povo;', 1, CURRENT_TIMESTAMP, false),
(3, 17, 5, 'a fim de que os filhos de Israel tragam os seus sacrifícios, que oferecem no campo, isto é, a fim de que os tragam ao Senhor, à porta da tenda da revelação, ao sacerdote, e os ofereçam por sacrifícios de ofertas, pacíficas ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 6, 'E o sacerdote espargirá o sangue sobre o altar do Senhor, à porta da tenda da revelação, e queimará a gordura por cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 7, 'E nunca mais oferecerão os seus sacrifícios aos sátiros, após os quais eles se prostituem; isso lhes será por estatuto perpétuo pelas suas gerações.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 8, 'Dir-lhes-ás pois: Qualquer homem da casa de Israel, ou dos estrangeiros que entre vós peregrinam, que oferecer holocausto ou sacrifício,', 1, CURRENT_TIMESTAMP, false),
(3, 17, 9, 'e não o trouxer à porta da tenda da revelação, para oferecê-lo ao Senhor, esse homem será extirpado do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 10, 'Também, qualquer homem da casa de Israel, ou dos estrangeiros que peregrinam entre eles, que comer algum sangue, contra aquela alma porei o meu rosto, e a extirparei do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 11, 'Porque a vida da carne está no sangue; pelo que vo-lo tenho dado sobre o altar, para fazer expiação pelas vossas almas; porquanto é o sangue que faz expiação, em virtude da vida.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 12, 'Portanto tenho dito aos filhos de Israel: Nenhum de vós comerá sangue; nem o estrangeiro que peregrina entre vós comerá sangue.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 13, 'Também, qualquer homem dos filhos de Israel, ou dos estrangeiros que peregrinam entre eles, que apanhar caça de fera ou de ave que se pode comer, derramará o sangue dela e o cobrirá com pó.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 14, 'Pois, quanto à vida de toda a carne, o seu sangue é uma e a mesma coisa com a sua vida; por isso eu disse aos filhos de Israel: Não comereis o sangue de nenhuma carne, porque a vida de toda a carne é o seu sangue; qualquer que o comer será extirpado.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 15, 'E todo homem, quer natural quer estrangeiro, que comer do que morre por si ou do que é dilacerado por feras, lavará as suas vestes, e se banhará em água, e será imundo até a tarde; depois será limpo.', 1, CURRENT_TIMESTAMP, false),
(3, 17, 16, 'Mas, se não as lavar, nem banhar o seu corpo, levará sobre si a sua iniquidade', 1, CURRENT_TIMESTAMP, false),
(3, 18, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 18, 2, 'Fala aos filhos de Israel, e dize-lhes: Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 3, 'Não fareis segundo as obras da terra do Egito, em que habitastes; nem fareis segundo as obras da terra de Canaã, para a qual eu vos levo; nem andareis segundo os seus estatutos.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 4, 'Os meus preceitos observareis, e os meus estatutos guardareis, para andardes neles. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 5, 'Guardareis, pois, os meus estatutos e as minhas ordenanças, pelas quais o homem, observando-as, viverá. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 6, 'Nenhum de vós se chegará àquela que lhe é próxima por sangue, para descobrir a sua nudez. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 7, 'Não descobrirás a nudez de teu pai, nem tampouco a de tua mãe; ela é tua mãe, não descobrirás a sua nudez.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 8, 'Não descobrirás a nudez da mulher de teu pai; é nudez de teu pai.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 9, 'A nudez de tua irmã por parte de pai ou por parte de mãe, quer nascida em casa ou fora de casa, não a descobrirás.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 10, 'Nem tampouco descobrirás a nudez da filha de teu filho, ou da filha de tua filha; porque é tua nudez.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 11, 'A nudez da filha da mulher de teu pai, gerada de teu pai, a qual é tua irmã, não a descobrirás.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 12, 'Não descobrirás a nudez da irmã de teu pai; ela é parenta chegada de teu pai.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 13, 'Não descobrirás a nudez da irmã de tua mãe, pois ela é parenta chegada de tua mãe.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 14, 'Não descobrirás a nudez do irmão de teu pai; não te chegarás à sua mulher; ela é tua tia.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 15, 'Não descobrirás a nudez de tua nora; ,ela é mulher de teu filho; não descobrirás a sua nudez.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 16, 'Não descobrirás a nudez da mulher de teu irmão; é a nudez de teu irmão.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 17, 'Não descobrirás a nudez duma mulher e de sua filha. Não tomarás a filha de seu filho, nem a filha de sua filha, para descobrir a sua nudez; são parentas chegadas; é maldade.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 18, 'E não tomarás uma mulher juntamente com sua irmã, durante a vida desta, para tornar-lha rival, descobrindo a sua nudez ao lado da outra.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 19, 'Também não te chegarás a mulher enquanto for impura em virtude da sua imundícia, para lhe descobrir a nudez.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 20, 'Nem te deitarás com a mulher de teu próximo, contaminando-te com ela.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 21, 'Não oferecerás a Moloque nenhum dos teus filhos, fazendo-o passar pelo fogo; nem profanarás o nome de teu Deus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 22, 'Não te deitarás com varão, como se fosse mulher; é abominação.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 23, 'Nem te deitarás com animal algum, contaminando-te com ele; nem a mulher se porá perante um animal, para ajuntar-se com ele; é confusão.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 24, 'Não vos contamineis com nenhuma dessas coisas, porque com todas elas se contaminaram as nações que eu expulso de diante de vós;', 1, CURRENT_TIMESTAMP, false),
(3, 18, 25, 'e, porquanto a terra está contaminada, eu visito sobre ela a sua iniqüidade, e a terra vomita os seus habitantes.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 26, 'Vós, pois, guardareis os meus estatutos e os meus preceitos, e nenhuma dessas abominações fareis, nem o natural, nem o estrangeiro que peregrina entre vós', 1, CURRENT_TIMESTAMP, false),
(3, 18, 27, '{porque todas essas abominações cometeram os homens da terra, que nela estavam antes de vós, e a terra ficou contaminada};', 1, CURRENT_TIMESTAMP, false),
(3, 18, 28, 'para que a terra não seja contaminada por vós e não vos vomite também a vós, como vomitou a nação que nela estava antes de vós.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 29, 'Pois qualquer que cometer alguma dessas abominações, sim, aqueles que as cometerem serão extirpados do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 18, 30, 'Portanto guardareis o meu mandamento, de modo que não caiais em nenhum desses abomináveis costumes que antes de vós foram seguidos, e para que não vos contamineis com eles. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 19, 2, 'Fala a toda a congregação dos filhos de Israel, e dize-lhes: Sereis santos, porque eu, o Senhor vosso Deus, sou santo.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 3, 'Temerá cada um a sua mãe e a seu pai; e guardareis os meus sábados. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 4, 'Não vos volteis para os ídolos, nem façais para vós deuses de fundição. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 5, 'Quando oferecerdes ao Senhor sacrifício de oferta pacífica, oferecê-lo-eis de modo a serdes aceitos.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 6, 'No mesmo dia, pois, em que o oferecerdes, e no dia seguinte, se comerá; mas o que sobejar até o terceiro dia será queimado no fogo.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 7, 'E se, na verdade, alguma coisa dele for comida ao terceiro dia, é coisa abominável; não será aceito.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 8, 'E qualquer que o comer levará sobre si a sua iniqüidade, porquanto profanou a coisa santa do Senhor; por isso tal alma será extirpada do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 9, 'Quando fizeres a colheita da tua terra, não segarás totalmente os cantos do teu campo, nem colherás as espigas caídas da tua sega.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 10, 'Semelhantemente não rabiscarás a tua vinha, nem colherás os bagos caídos da tua vinha; deixá-los-ás para o pobre e para o estrangeiro. Eu sou o senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 11, 'Não furtareis; não enganareis, nem mentireis uns aos outros;', 1, CURRENT_TIMESTAMP, false),
(3, 19, 12, 'não jurareis falso pelo meu nome, assim profanando o nome do vosso Deus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 13, 'Não oprimirás o teu próximo, nem o roubarás; a paga do jornaleiro não ficará contigo até pela manhã.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 14, 'Não amaldiçoarás ao surdo, nem porás tropeço diante do cego; mas temerás a teu Deus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 15, 'Não farás injustiça no juízo; não farás acepção da pessoa do pobre, nem honrarás o poderoso; mas com justiça julgarás o teu próximo.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 16, 'Não andarás como mexeriqueiro entre o teu povo; nem conspirarás contra o sangue do teu próximo. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 17, 'Não odiarás a teu irmão no teu coração; não deixarás de repreender o teu próximo, e não levarás sobre ti pecado por causa dele.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 18, 'Não te vingarás nem guardarás ira contra os filhos do teu povo; mas amarás o teu próximo como a ti mesmo. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 19, 'Guardareis os meus estatutos. Não permitirás que se cruze o teu gado com o de espécie diversa; não semearás o teu campo com semente diversa; nem vestirás roupa tecida de materiais diversos.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 20, 'E, quando um homem se deitar com uma mulher que for escrava, desposada com um homem, e que não for resgatada, nem se lhe houver dado liberdade, então ambos serão açoitados; não morrerão, pois ela não era livre.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 21, 'E como a sua oferta pela culpa, trará o homem ao Senhor, à porta da tenda da revelação, um carneiro para expiação de culpa;', 1, CURRENT_TIMESTAMP, false),
(3, 19, 22, 'e, com o carneiro da oferta pela culpa, o sacerdote fará expiação por ele perante o Senhor, pelo pecado que cometeu; e este lhe será perdoado.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 23, 'Quando tiverdes entrado na terra e tiverdes plantado toda qualidade de árvores para delas comerdes, tereis o seu fruto como incircunciso; por três anos ele vos será como incircunciso; dele não se comerá.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 24, 'No quarto ano, porém, todo o seu o fruto será santo, para oferta de louvor ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 25, 'E partindo do quinto ano comereis o seu fruto; para que elas vos aumentem a sua produção. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 26, 'Não comereis coisa alguma com o sangue; não usareis de encantamentos, nem de agouros.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 27, 'Não cortareis o cabelo, arredondando os cantos da vossa cabeça, nem desfigurareis os cantos da vossa barba.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 28, 'Não fareis lacerações na vossa carne pelos mortos; nem no vosso corpo imprimireis qualquer marca. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 29, 'Não profanarás a tua filha, fazendo-a prostituir-se; para que a terra não se prostitua e não se encha de maldade.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 30, 'Guardareis os meus sábados, e o meu santuário reverenciareis. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 31, 'Não vos voltareis para os que consultam os mortos nem para os feiticeiros; não os busqueis para não ficardes contaminados por eles. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 32, 'Diante das cãs te levantarás, e honrarás a face do ancião, e temerás o teu Deus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 33, 'Quando um estrangeiro peregrinar convosco na vossa terra, não o maltratareis.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 34, 'Como um natural entre vós será o estrangeiro que peregrinar convosco; amá-lo-eis como a vós mesmos; pois estrangeiros fostes na terra do Egito. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 35, 'Não cometereis injustiça no juízo, nem na vara, nem no peso, nem na medida.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 36, 'Balanças justas, pesos justos, efa justa, e justo him tereis. Eu sou o Senhor vosso Deus, que vos tirei da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(3, 19, 37, 'Pelo que guardareis todos os meus estatutos e todos os meus preceitos, e os cumprireis. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 20, 2, 'Também dirás aos filhos de Israel: Qualquer dos filhos de Israel, ou dos estrangeiros peregrinos em Israel, que der de seus filhos a Moloque, certamente será morto; o povo da terra o apedrejará.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 3, 'Eu porei o meu rosto contra esse homem, e o extirparei do meio do seu povo; porquanto eu de seus filhos a Moloque, assim contaminando o meu santuário e profanando o meu santo nome.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 4, 'E, se o povo da terra de alguma maneira esconder os olhos para não ver esse homem, quando der de seus filhos a Moloque, e não matar,', 1, CURRENT_TIMESTAMP, false),
(3, 20, 5, 'eu porei o meu rosto contra esse homem, e contra a sua família, e o extirparei do meio do seu povo, bem como a todos os que forem após ele, prostituindo-se após Moloque.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 6, 'Quanto àquele que se voltar para os que consultam os mortos e para os feiticeiros, prostituindo-se após eles, porei o meu rosto contra aquele homem, e o extirparei do meio do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 7, 'Portanto santificai-vos, e sede santos, pois eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 8, 'Guardai os meus estatutos, e cumpri-os. Eu sou o Senhor, que vos santifico.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 9, 'Qualquer que amaldiçoar a seu pai ou a sua mãe, certamente será morto; amaldiçoou a seu pai ou a sua mãe; o seu sangue será sobre ele.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 10, 'O homem que adulterar com a mulher de outro, sim, aquele que adulterar com a mulher do seu próximo, certamente será morto, tanto o adúltero, como a adúltera.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 11, 'O homem que se deitar com a mulher de seu pai terá descoberto a nudez de seu pai; ambos os adúlteros certamente serão mortos; o seu sangue será sobre eles.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 12, 'Se um homem se deitar com a sua nora, ambos certamente serão mortos; cometeram uma confusão; o seu sangue será sobre eles.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 13, 'Se um homem se deitar com outro homem, como se fosse com mulher, ambos terão praticado abominação; certamente serão mortos; o seu sangue será sobre eles.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 14, 'Se um homem tomar uma mulher e a mãe dela, é maldade; serão queimados no fogo, tanto ele quanto elas, para que não haja maldade no meio de vós.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 15, 'Se um homem se ajuntar com um animal, certamente será morto; também matareis o animal.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 16, 'Se uma mulher se chegar a algum animal, para ajuntar-se com ele, matarás a mulher e bem assim o animal; certamente serão mortos; o seu sangue será sobre eles:', 1, CURRENT_TIMESTAMP, false),
(3, 20, 17, 'Se um homem tomar a sua irmã, por parte de pai, ou por parte de mãe, e vir a nudez dela, e ela a dele, é torpeza; portanto serão extirpados aos olhos dos filhos do seu povo; terá descoberto a nudez de sua irmã; levará sobre si a sua iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 18, 'Se um homem se deitar com uma mulher no tempo da enfermidade dela, e lhe descobrir a nudez, descobrindo-lhe também a fonte, e ela descobrir a fonte do seu sangue, ambos serão extirpados do meio do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 19, 'Não descobrirás a nudez da irmã de tua mãe, ou da irmã de teu pai, porquanto isso será descobrir a sua parenta chegada; levarão sobre si a sua iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 20, 'Se um homem se deitar com a sua tia, terá descoberto a nudez de seu tio; levarão sobre si o seu pecado; sem filhos morrerão.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 21, 'Se um homem tomar a mulher de seu irmão, é imundícia; terá descoberto a nudez de seu irmão; sem filhos ficarão.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 22, 'Guardareis, pois, todos os meus estatutos e todos os meus preceitos, e os cumprireis; a fim de que a terra, para a qual eu vos levo, para nela morardes, não vos vomite.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 23, 'E não andareis nos costumes dos povos que eu expulso de diante de vós; porque eles fizeram todas estas coisas, e eu os abominei.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 24, 'Mas a vós vos tenho dito: Herdareis a sua terra, e eu vo-la darei para a possuirdes, terra que mana leite e mel. Eu sou o Senhor vosso Deus, que vos separei dos povos.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 25, 'Fareis, pois, diferença entre os animais limpos e os imundos, e entre as aves imundas e as limpas; e não fareis abomináveis as vossas almas por causa de animais, ou de aves, ou de qualquer coisa de tudo de que está cheia a terra, as quais coisas apartei de vós como imundas.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 26, 'E sereis para mim santos; porque eu, o Senhor, sou santo, e vos separei dos povos, para serdes meus.', 1, CURRENT_TIMESTAMP, false),
(3, 20, 27, 'O homem ou mulher que consultar os mortos ou for feiticeiro, certamente será morto. Serão apedrejados, e o seu sangue será sobre eles.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 1, 'Depois disse o senhor a Moisés: Fala aos sacerdotes, filhos de Arão, e dize-lhes: O sacerdote não se contaminará por causa dum morto entre o seu povo,', 1, CURRENT_TIMESTAMP, false),
(3, 21, 2, 'salvo por um seu parente mais chegado: por sua mãe ou por seu pai, por seu filho ou por sua filha, por seu irmão,', 1, CURRENT_TIMESTAMP, false),
(3, 21, 3, 'ou por sua irmã virgem, que lhe é chegada, que ainda não tem marido; por ela também pode contaminar-se.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 4, 'O sacerdote, sendo homem principal entre o seu povo, não se profanará, assim contaminando-se.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 5, 'Não farão os sacerdotes calva na cabeça, e não raparão os cantos da barba, nem farão lacerações na sua carne.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 6, 'santos serão para seu Deus, e não profanarão o nome do seu Deus; porque oferecem as ofertas queimadas do senhor, que são o pão do seu Deus; portanto serão santos.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 7, 'Não tomarão mulher prostituta ou desonrada, nem tomarão mulher repudiada de seu marido; pois o sacerdote é santo para seu Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 8, 'Portanto o santificarás; porquanto oferece o pão do teu Deus, santo te será; pois eu, o Senhor, que vos santifico, sou santo.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 9, 'E se a filha dum sacerdote se profanar, tornando-se prostituta, profana a seu pai; no fogo será queimada.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 10, 'Aquele que é sumo sacerdote entre seus irmãos, sobre cuja cabeça foi derramado o óleo da unção, e que foi consagrado para vestir as vestes sagradas, não descobrirá a cabeça nem rasgará a sua vestidura;', 1, CURRENT_TIMESTAMP, false),
(3, 21, 11, 'e não se chegará a cadáver algum; nem sequer por causa de seu pai ou de sua, mãe se contaminará;', 1, CURRENT_TIMESTAMP, false),
(3, 21, 12, 'não sairá do santuário, nem profanará o santuário do seu Deus; pois a coroa do óleo da unção do seu Deus está sobre ele. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 13, 'E ele tomará por esposa uma mulher na sua virgindade.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 14, 'Viúva, ou repudiada, ou desonrada, ou prostituta, destas não tomará; mas virgem do seu povo tomará por mulher.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 15, 'E não profanará a sua descendência entre o seu povo; porque eu sou o Senhor que o santifico.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 16, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 21, 17, 'Fala a Arão, dizendo: Ninguém dentre os teus descendentes, por todas as suas gerações, que tiver defeito, se chegará para oferecer o pão do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 18, 'Pois nenhum homem que tiver algum defeito se chegará: como homem cego, ou coxo, ou de nariz chato, ou de membros demasiadamente compridos,', 1, CURRENT_TIMESTAMP, false),
(3, 21, 19, 'ou homem que tiver o pé quebrado, ou a mão quebrada,', 1, CURRENT_TIMESTAMP, false),
(3, 21, 20, 'ou for corcunda, ou anão, ou que tiver belida, ou sarna, ou impigens, ou que tiver testículo lesado;', 1, CURRENT_TIMESTAMP, false),
(3, 21, 21, 'nenhum homem dentre os descendentes de Arão, o sacerdote, que tiver algum defeito, se chegará para oferecer as ofertas queimadas do Senhor; ele tem defeito; não se chegará para oferecer o pão do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 22, 'Comerá do pão do seu Deus, tanto do santíssimo como do santo;', 1, CURRENT_TIMESTAMP, false),
(3, 21, 23, 'contudo, não entrará até o véu, nem se chegará ao altar, porquanto tem defeito; para que não profane os meus santuários; porque eu sou o Senhor que os santifico.', 1, CURRENT_TIMESTAMP, false),
(3, 21, 24, 'Moisés, pois, assim falou a Arão e a seus filhos, e a todos os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 1, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 22, 2, 'Dize a Arão e a seus filhos que se abstenham das coisas sagradas dos filhos de Israel, as quais eles a mim me santificam, e que não profanem o meu santo nome. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 3, 'Dize-lhes: Todo homem dentre os vossos descendentes pelas vossas gerações que, tendo sobre si a sua imundícia, se chegar às coisas sagradas que os filhos de Israel santificam ao Senhor, aquela alma será extirpada da minha presença. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 4, 'Ninguém dentre os descendentes de Arão que for leproso, ou tiver fluxo, comerá das coisas sagradas, até que seja limpo. Também o que tocar em alguma coisa tornada imunda por causa e um morto, ou aquele de quem sair o sêmen', 1, CURRENT_TIMESTAMP, false),
(3, 22, 5, 'ou qualquer que tocar em algum animal que se arrasta, pelo qual se torne imundo, ou em algum homem, pelo qual se torne imundo, seja qual for a sua imundícia,', 1, CURRENT_TIMESTAMP, false),
(3, 22, 6, 'o homem que tocar em tais coisas será imundo até a tarde, e não comerá das coisas sagradas, mas banhará o seu corpo em água', 1, CURRENT_TIMESTAMP, false),
(3, 22, 7, 'e, posto o sol, então será limpo; depois comerá das coisas sagradas, porque isso é o seu pão.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 8, 'Do animal que morrer por si, ou do que for dilacerado por feras, não comerá o homem, para que não se contamine com ele. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 9, 'Guardarão, pois, o meu mandamento, para que, havendo-o profanado, não levem pecado sobre si e morram nele. Eu sou o Senhor que os santifico.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 10, 'Também nenhum estranho comerá das coisas sagradas; nem o hóspede do sacerdote, nem o jornaleiro, comerá delas.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 11, 'Mas aquele que o sacerdote tiver comprado com o seu dinheiro, e o nascido na sua casa, esses comerão do seu pão.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 12, 'Se a filha de um sacerdote se casar com um estranho, ela não comerá da oferta alçada das coisas sagradas.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 13, 'Mas quando a filha do sacerdote for viúva ou repudiada, e não tiver filhos, e houver tornado para a casa de seu pai, como na sua mocidade, do pão de seu pai comerá; mas nenhum estranho comerá dele.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 14, 'Se alguém por engano comer a coisa sagrada, repô-la-á, acrescida da quinta parte, e a dará ao sacerdote como a coisa sagrada.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 15, 'Assim não profanarão as coisas sagradas dos filhos de Israel, que eles oferecem ao Senhor,', 1, CURRENT_TIMESTAMP, false),
(3, 22, 16, 'nem os farão levar sobre si a iniqüidade que envolve culpa, comendo as suas coisas sagradas; pois eu sou o Senhor que as santifico.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 17, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 22, 18, 'Fala a Arão, e a seus filhos, e a todos os filhos de Israel, e dize-lhes: Todo homem da casa de Israel, ou dos estrangeiros em Israel, que oferecer a sua oferta, seja dos seus votos, seja das suas ofertas voluntárias que oferecerem ao Senhor em holocausto,', 1, CURRENT_TIMESTAMP, false),
(3, 22, 19, 'para que sejais aceitos, oferecereis macho sem defeito, ou dos novilhos, ou dos cordeiros, ou das cabras.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 20, 'Nenhuma coisa, porém, que tiver defeito oferecereis, porque não será aceita a vosso favor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 21, 'E, quando alguém oferecer sacrifício de oferta pacífica ao Senhor para cumprir um voto, ou para oferta voluntária, seja do gado vacum, seja do gado miúdo, o animal será perfeito, para que seja aceito; nenhum defeito haverá nele.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 22, 'O cego, ou quebrado, ou aleijado, ou que tiver úlceras, ou sarna, ou impigens, estes não oferecereis ao Senhor, nem deles poreis oferta queimada ao Senhor sobre o altar.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 23, 'Todavia, um novilho, ou um cordeiro, que tenha algum membro comprido ou curto demais, poderás oferecer por oferta voluntária, mas para cumprir voto não será aceito.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 24, 'Não oferecereis ao Senhor um animal que tiver testículo machucado, ou moído, ou arrancado, ou lacerado; não fareis isso na vossa terra.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 25, 'Nem da mão do estrangeiro oferecereis de alguma dessas coisas o pão do vosso Deus; porque a sua corrupção nelas está; há defeito nelas; não serão aceitas a vosso favor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 26, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 22, 27, 'Quando nascer um novilho, ou uma ovelha, ou uma cabra, por sete dias ficará debaixo de sua mãe; depois, desde o dia oitavo em diante, será aceito por oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 28, 'Também, seja vaca ou seja ovelha, não a imolareis a ela e à sua cria, ambas no mesmo dia.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 29, 'E, quando oferecerdes ao Senhor sacrifício de ação de graças, oferecê-lo-eis de modo a serdes aceitos.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 30, 'No mesmo dia se comerá; nada deixareis ficar dele até pela manhã. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 31, 'Guardareis os meus mandamentos, e os cumprireis. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 22, 32, 'Não profanareis o meu santo nome, e serei santificado no meio dos filhos de Israel. Eu sou o Senhor que vos santifico,', 1, CURRENT_TIMESTAMP, false),
(3, 22, 33, 'que vos tirei da terra do Egito para ser o vosso Deus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 1, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 2, 'Fala aos filhos de Israel, e dize-lhes: As festas fixas do Senhor, que proclamareis como santas convocações, são estas:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 3, 'Seis dias se fará trabalho, mas o sétimo dia é o sábado do descanso solene, uma santa convocação; nenhum trabalho fareis; é sábado do Senhor em todas as vossas habitações.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 4, 'São estas as festas fixas do Senhor, santas convocações, que proclamareis no seu tempo determinado:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 5, 'No mês primeiro, aos catorze do mês, à tardinha, é a páscoa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 6, 'E aos quinze dias desse mês é a festa dos pães ázimos do Senhor; sete dias comereis pães ázimos.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 7, 'No primeiro dia tereis santa convocação; nenhum trabalho servil fareis.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 8, 'Mas por sete dias oferecereis oferta queimada ao Senhor; ao sétimo dia haverá santa convocação; nenhum trabalho servil fareis.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 9, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 10, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra que eu vos dou, e segardes a sua sega, então trareis ao sacerdote um molho das primícias da vossa sega;', 1, CURRENT_TIMESTAMP, false),
(3, 23, 11, 'e ele moverá o molho perante o Senhor, para que sejais aceitos. No dia seguinte ao sábado o sacerdote o moverá.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 12, 'E no dia em que moverdes o molho, oferecereis um cordeiro sem defeito, de um ano, em holocausto ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 13, 'Sua oferta de cereais será dois décimos de efa de flor de farinha, amassada com azeite, para oferta queimada em cheiro suave ao Senhor; e a sua oferta de libação será de vinho, um quarto de him.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 14, 'E não comereis pão, nem trigo torrado, nem espigas verdes, até aquele mesmo dia, em que trouxerdes a oferta do vosso Deus; é estatuto perpétuo pelas vossas gerações, em todas as vossas habitações.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 15, 'Contareis para vós, desde o dia depois do sábado, isto é, desde o dia em que houverdes trazido o molho da oferta de movimento, sete semanas inteiras;', 1, CURRENT_TIMESTAMP, false),
(3, 23, 16, 'até o dia seguinte ao sétimo sábado, contareis cinqüenta dias; então oferecereis nova oferta de cereais ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 17, 'Das vossas habitações trareis, para oferta de movimento, dois pães de dois décimos de efa; serão de flor de farinha, e levedados se cozerão; são primícias ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 18, 'Com os pães oferecereis sete cordeiros sem defeito, de um ano, um novilho e dois carneiros; serão holocausto ao Senhor, com as respectivas ofertas de cereais e de libação, por oferta queimada de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 19, 'Também oferecereis um bode para oferta pelo pecado, e dois cordeiros de um ano para sacrifício de ofertas pacíficas.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 20, 'Então o sacerdote os moverá, juntamente com os pães das primícias, por oferta de movimento perante o Senhor, com os dois cordeiros; santos serão ao Senhor para uso do sacerdote.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 21, 'E fareis proclamação nesse mesmo dia, pois tereis santa convocação; nenhum trabalho servil fareis; é estatuto perpétuo em todas as vossas habitações pelas vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 22, 'Quando fizeres a sega da tua terra, não segarás totalmente os cantos do teu campo, nem colherás as espigas caídas da tua sega; para o pobre e para o estrangeiro as deixarás. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 23, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 24, 'Fala aos filhos de Israel: No sétimo mês, no primeiro dia do mês, haverá para vós descanso solene, em memorial, com sonido de trombetas, uma santa convocação.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 25, 'Nenhum trabalho servil fareis, e oferecereis oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 26, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 27, 'Ora, o décimo dia desse sétimo mês será o dia da expiação; tereis santa convocação, e afligireis as vossas almas; e oferecereis oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 28, 'Nesse dia não fareis trabalho algum; porque é o dia da expiação, para nele fazer-se expiação por vós perante o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 29, 'Pois toda alma que não se afligir nesse dia, será extirpada do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 30, 'Também toda alma que nesse dia fizer algum trabalho, eu a destruirei do meio do seu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 31, 'Não fareis nele trabalho algum; isso será estatuto perpétuo pelas vossas gerações em todas as vossas habitações.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 32, 'Sábado de descanso vos será, e afligireis as vossas almas; desde a tardinha do dia nono do mês até a outra tarde, guardareis o vosso sábado.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 33, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 23, 34, 'Fala aos filhos de Israel, dizendo: Desde o dia quinze desse sétimo mês haverá a festa dos tabernáculos ao Senhor por sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 35, 'No primeiro dia haverá santa convocação; nenhum trabalho servil fareis.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 36, 'Por sete dias oferecereis ofertas queimadas ao Senhor; ao oitavo dia tereis santa convocação, e oferecereis oferta queimada ao Senhor; será uma assembléia solene; nenhum trabalho servil fareis.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 37, 'Estas são as festas fixas do Senhor, que proclamareis como santas convocações, para oferecer-se ao Senhor oferta queimada, holocausto e oferta de cereais, sacrifícios e ofertas de libação, cada qual em seu dia próprio;', 1, CURRENT_TIMESTAMP, false),
(3, 23, 38, 'além dos sábados do Senhor, e além dos vossos dons, e além de todos os vossos votos, e além de todas as vossas ofertas voluntárias que derdes ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 39, 'Desde o dia quinze do sétimo mês, quando tiverdes colhido os frutos da terra, celebrareis a festa do Senhor por sete dias; no primeiro dia haverá descanso solene, e no oitavo dia haverá descanso solene.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 40, 'No primeiro dia tomareis para vós o fruto de árvores formosas, folhas de palmeiras, ramos de árvores frondosas e salgueiros de ribeiras; e vos alegrareis perante o Senhor vosso Deus por sete dias.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 41, 'E celebrá-la-eis como festa ao Senhor por sete dias cada ano; estatuto perpétuo será pelas vossas gerações; no mês sétimo a celebrareis.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 42, 'Por sete dias habitareis em tendas de ramos; todos os naturais em Israel habitarão em tendas de ramos,', 1, CURRENT_TIMESTAMP, false),
(3, 23, 43, 'para que as vossas gerações saibam que eu fiz habitar em tendas de ramos os filhos de Israel, quando os tirei da terra do Egito. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 23, 44, 'Assim declarou Moisés aos filhos de Israel as festas fixas do Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 24, 2, 'Ordena aos filhos de Israel que te tragam, para o candeeiro, azeite de oliveira, puro, batido, a fim de manter uma lâmpada acesa continuamente.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 3, 'Arão a conservará em ordem perante o Senhor, continuamente, desde a tarde até a manhã, fora do véu do testemunho, na tenda da revelação; será estatuto perpétuo pelas vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 4, 'Sobre o candelabro de ouro puro conservará em ordem as lâmpadas perante o Senhor continuamente.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 5, 'Também tomarás flor de farinha, e dela cozerás doze pães; cada pão será de dois décimos de efa.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 6, 'E pô-los-ás perante o Senhor, em duas fileiras, seis em cada fileira, sobre a mesa de ouro puro.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 7, 'Sobre cada fileira porás incenso puro, para que seja sobre os pães como memorial, isto é, como oferta queimada ao Senhor;', 1, CURRENT_TIMESTAMP, false),
(3, 24, 8, 'em cada dia de sábado, isso se porá em ordem perante o Senhor continuamente; e, a favor dos filhos de Israel, um pacto perpétuo.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 9, 'Pertencerão os pães a Arão e a seus filhos, que os comerão em lugar santo, por serem coisa santíssima para eles, das ofertas queimadas ao Senhor por estatuto perpétuo.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 10, 'Naquele tempo apareceu no meio dos filhos de Israel o filho duma mulher israelita, o qual era filho dum egípcio; e o filho da israelita e um homem israelita pelejaram no arraial;', 1, CURRENT_TIMESTAMP, false),
(3, 24, 11, 'e o filho da mulher israelita blasfemou o Nome, e praguejou; pelo que o trouxeram a Moisés. Ora, o nome de sua mãe era Selomite, filha de Dibri, da tribo de Dã.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 12, 'Puseram-no, pois, em detenção, até que se lhes fizesse declaração pela boca do Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 13, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 24, 14, 'Tira para fora do arraial o que tem blasfemado; todos os que o ouviram porão as mãos sobre a cabeça dele, e toda a congregação o apedrejará.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 15, 'E dirás aos filhos de Israel: Todo homem que amaldiçoar o seu Deus, levará sobre si o seu pecado.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 16, 'E aquele que blasfemar o nome do Senhor, certamente será morto; toda a congregação certamente o apedrejará. Tanto o estrangeiro como o natural, que blasfemar o nome do Senhor, será morto.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 17, 'Quem matar a alguém, certamente será morto;', 1, CURRENT_TIMESTAMP, false),
(3, 24, 18, 'e quem matar um animal, fará restituição por ele, vida por vida.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 19, 'Se alguém desfigurar o seu próximo, como ele fez, assim lhe será feito:', 1, CURRENT_TIMESTAMP, false),
(3, 24, 20, 'quebradura por quebradura, olho por olho, dente por dente; como ele tiver desfigurado algum homem, assim lhe será feito.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 21, 'Quem, pois, matar um animal, fará restituição por ele; mas quem matar um homem, será morto.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 22, 'uma mesma lei tereis, tanto para o estrangeiro como para o natural; pois eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 24, 23, 'Então falou Moisés aos filhos de Israel. Depois eles levaram para fora do arraial aquele que tinha blasfemado e o apedrejaram. Fizeram, pois, os filhos de Israel como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 1, 'Disse mais o Senhor a Moisés no monte Sinai:', 1, CURRENT_TIMESTAMP, false),
(3, 25, 2, 'Fala aos filhos de Israel e dize-lhes: Quando tiverdes entrado na terra que eu vos dou, a terra guardará um sábado ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 3, 'Seis anos semearás a tua terra, e seis anos podarás a tua vinha, e colherás os seus frutos;', 1, CURRENT_TIMESTAMP, false),
(3, 25, 4, 'mas no sétimo ano haverá sábado de descanso solene para a terra, um sábado ao Senhor; não semearás o teu campo, nem podarás a tua vinha.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 5, 'O que nascer de si mesmo da tua sega não segarás, e as uvas da tua vide não tratada não vindimarás; ano de descanso solene será para a terra.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 6, 'Mas os frutos do sábado da terra vos serão por alimento, a ti, e ao teu servo, e à tua serva, e ao teu jornaleiro, e ao estrangeiro que peregrina contigo,', 1, CURRENT_TIMESTAMP, false),
(3, 25, 7, 'e ao teu gado, e aos animais que estão na tua terra; todo o seu produto será por mantimento.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 8, 'Também contarás sete sábados de anos, sete vezes sete anos; de maneira que os dias dos sete sábados de anos serão quarenta e nove anos.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 9, 'Então, no décimo dia do sétimo mês, farás soar fortemente a trombeta; no dia da expiação fareis soar a trombeta por toda a vossa terra.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 10, 'E santificareis o ano qüinquagésimo, e apregoareis liberdade na terra a todos os seus habitantes; ano de jubileu será para vós; pois tornareis, cada um à sua possessão, e cada um à sua família.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 11, 'Esse ano qüinquagésimo será para vós jubileu; não semeareis, nem segareis o que nele nascer de si mesmo, nem nele vindimareis as uvas das vides não tratadas.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 12, 'Porque é jubileu; santo será para vós; diretamente do campo comereis o seu produto.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 13, 'Nesse ano do jubileu tornareis, cada um à sua possessão.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 14, 'Se venderdes alguma coisa ao vosso próximo ou a comprardes da mão do vosso próximo, não vos defraudareis uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 15, 'Conforme o número de anos desde o jubileu é que comprarás ao teu próximo, e conforme o número de anos das colheitas é que ele te venderá.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 16, 'Quanto mais forem os anos, tanto mais aumentarás o preço, e quanto menos forem os anos, tanto mais abaixarás o preço; porque é o número das colheitas que ele te vende.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 17, 'Nenhum de vós oprimirá ao seu próximo; mas temerás o teu Deus; porque eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 18, 'Pelo que observareis os meus estatutos, e guardareis os meus preceitos e os cumprireis; assim habitareis seguros na terra.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 19, 'Ela dará o seu fruto, e comereis a fartar; e nela habitareis seguros.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 20, 'Se disserdes: Que comeremos no sétimo ano, visto que não haveremos de semear, nem fazer a nossa colheita?', 1, CURRENT_TIMESTAMP, false),
(3, 25, 21, 'então eu mandarei a minha bênção sobre vós no sexto ano, e a terra produzirá fruto bastante para os três anos.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 22, 'No oitavo ano semeareis, e comereis da colheita velha; até o ano nono, até que venha a colheita nova, comereis da velha.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 23, 'Também não se venderá a terra em perpetuidade, porque a terra é minha; pois vós estais comigo como estrangeiros e peregrinos:', 1, CURRENT_TIMESTAMP, false),
(3, 25, 24, 'Portanto em toda a terra da vossa possessão concedereis que seja remida a terra.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 25, 'Se teu irmão empobrecer e vender uma parte da sua possessão, virá o seu parente mais chegado e remirá o que seu irmão vendeu.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 26, 'E se alguém não tiver remidor, mas ele mesmo tiver enriquecido e achado o que basta para o seu resgate,', 1, CURRENT_TIMESTAMP, false),
(3, 25, 27, 'contará os anos desde a sua venda, e o que ficar do preço da venda restituirá ao homem a quem a vendeu, e tornará à sua possessão.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 28, 'Mas, se as suas posses não bastarem para reavê-la, aquilo que tiver vendido ficará na mão do comprador até o ano do jubileu; porém no ano do jubileu sairá da posse deste, e aquele que vendeu tornará à sua possessão.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 29, 'Se alguém vender uma casa de moradia em cidade murada, poderá remi-la dentro de um ano inteiro depois da sua venda; durante um ano inteiro terá o direito de a remir.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 30, 'Mas se, passado um ano inteiro, não tiver sido resgatada, essa casa que está na cidade murada ficará, em perpetuidade, pertencendo ao que a comprou, e à sua descendência; não sairá o seu poder no jubileu.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 31, 'Todavia as casas das aldeias que não têm muro ao redor serão consideradas como o campo da terra; poderão ser remidas, e sairão do poder do comprador no jubileu.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 32, 'Também, no tocante às cidades dos levitas, às casas das cidades da sua possessão, terão eles direito perpétuo de remi-las.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 33, 'E se alguém comprar dos levitas uma casa, a casa comprada e a cidade da sua possessão sairão do poder do comprador no jubileu; porque as casas das cidades dos levitas são a sua possessão no meio dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 34, 'Mas o campo do arrabalde das suas cidades não se poderá vender, porque lhes é possessão perpétua.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 35, 'Também, se teu irmão empobrecer ao teu lado, e lhe enfraquecerem as mãos, sustentá-lo-ás; como estrangeiro e peregrino viverá contigo.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 36, 'Não tomarás dele juros nem ganho, mas temerás o teu Deus, para que teu irmão viva contigo.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 37, 'Não lhe darás teu dinheiro a juros, nem os teus víveres por lucro.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 38, 'Eu sou o Senhor vosso Deus, que vos tirei da terra do Egito, para vos dar a terra de Canaã, para ser o vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 39, 'Também, se teu irmão empobrecer ao teu lado e vender-se a ti, não o farás servir como escravo.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 40, 'Como jornaleiro, como peregrino estará ele contigo; até o ano do jubileu te servirá;', 1, CURRENT_TIMESTAMP, false),
(3, 25, 41, 'então sairá do teu serviço, e com ele seus filhos, e tornará à sua família, à possessão de seus pais.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 42, 'Porque são meus servos, que tirei da terra do Egito; não serão vendidos como escravos.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 43, 'Não dominarás sobre ele com rigor, mas temerás o teu Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 44, 'E quanto aos escravos ou às escravas que chegares a possuir, das nações que estiverem ao redor de vós, delas é que os comprareis.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 45, 'Também os comprareis dentre os filhos dos estrangeiros que peregrinarem entre vós, tanto dentre esses como dentre as suas famílias que estiverem convosco, que tiverem eles gerado na vossa terra; e vos serão por possessão.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 46, 'E deixá-los-eis por herança aos vossos filhos depois de vós, para os herdarem como possessão; desses tomareis os vossos escravos para sempre; mas sobre vossos irmãos, os filhos de Israel, não dominareis com rigor, uns sobre os outros.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 47, 'Se um estrangeiro ou peregrino que estiver contigo se tornar rico, e teu irmão, que está com ele, empobrecer e vender-se ao estrangeiro ou peregrino que está contigo, ou à linhagem da família do estrangeiro,', 1, CURRENT_TIMESTAMP, false),
(3, 25, 48, 'depois que se houver vendido, poderá ser remido; um de seus irmãos o poderá remir;', 1, CURRENT_TIMESTAMP, false),
(3, 25, 49, 'ou seu tio, ou o filho de seu tio, ou qualquer parente chegado da sua família poderá remi-lo; ou, se ele se tiver tornado rico, poderá remir-se a si mesmo.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 50, 'E com aquele que o comprou fará a conta desde o ano em que se vendeu a ele até o ano do jubileu; e o preço da sua venda será conforme o número dos anos; conforme os dias de um jornaleiro estará com ele.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 51, 'Se ainda faltarem muitos anos, conforme os mesmos restituirá, do dinheiro pelo qual foi comprado, o preço da sua redenção;', 1, CURRENT_TIMESTAMP, false),
(3, 25, 52, 'e se faltarem poucos anos até o ano do jubileu, fará a conta com ele; segundo o número dos anos restituirá o preço da sua redenção.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 53, 'Como servo contratado de ano em ano, estará com o comprador; o qual não dominará sobre ele com rigor diante dos teus olhos.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 54, 'E, se não for remido por nenhum desses meios, sairá livre no ano do jubileu, e com ele seus filhos.', 1, CURRENT_TIMESTAMP, false),
(3, 25, 55, 'Porque os filhos de Israel são meus servos; eles são os meus servos que tirei da terra do Egito. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 1, 'Não fareis para vós ídolos, nem para vós levantareis imagem esculpida, nem coluna, nem poreis na vossa terra pedra com figuras, para vos inclinardes a ela; porque eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 2, 'Guardareis os meus sábados, e reverenciareis o meu santuário. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 3, 'Se andardes nos meus estatutos, e guardardes os meus mandamentos e os cumprires,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 4, 'eu vos darei as vossas chuvas a seu tempo, e a terra dará o seu produto, e as árvores do campo darão os seus frutos;', 1, CURRENT_TIMESTAMP, false),
(3, 26, 5, 'a debulha vos continuará até a vindima, e a vindima até a semeadura; comereis o vosso pão a fartar, e habitareis seguros na vossa terra.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 6, 'Também darei paz na terra, e vos deitareis, e ninguém vos amedrontará. Farei desaparecer da terra os animais nocivos, e pela vossa terra não passará espada.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 7, 'Perseguireis os vossos inimigos, e eles cairão à espada diante de vós.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 8, 'Cinco de vós perseguirão a um cento deles, e cem de vós perseguirão a dez mil; e os vossos inimigos cairão à espada diante de vos.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 9, 'Outrossim, olharei para vós, e vos farei frutificar, e vos multiplicarei, e confirmarei o meu pacto convosco.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 10, 'E comereis da colheita velha por longo tempo guardada, até afinal a removerdes para dar lugar à nova.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 11, 'Também porei o meu tabernáculo no meio de vós, e a minha alma não vos abominará.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 12, 'Andarei no meio de vós, e serei o vosso Deus, e vós sereis o meu povo.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 13, 'Eu sou o Senhor vosso Deus, que vos tirei da terra dos egípcios, para que não fôsseis seus escravos; e quebrei os canzis do vosso jugo, e vos fiz andar erguidos.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 14, 'Mas, se não me ouvirdes, e não cumprirdes todos estes mandamentos,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 15, 'e se rejeitardes os meus estatutos, e a vossa alma desprezar os meus preceitos, de modo que não cumprais todos os meus mandamentos, mas violeis o meu pacto,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 16, 'então eu, com efeito, vos farei isto: porei sobre vós o terror, a tísica e a febre ardente, que consumirão os olhos e farão definhar a vida; em vão semeareis a vossa semente, pois os vossos inimigos a comerão.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 17, 'Porei o meu rosto contra vós, e sereis feridos diante de vossos inimigos; os que vos odiarem dominarão sobre vós, e fugireis sem que ninguém vos persiga.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 18, 'Se nem ainda com isto me ouvirdes, prosseguirei em castigar-vos sete vezes mais, por causa dos vossos pecados.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 19, 'Pois quebrarei a soberba do vosso poder, e vos farei o céu como ferro e a terra como bronze.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 20, 'Em vão se gastará a vossa força, porquanto a vossa terra não dará o seu produto, nem as árvores da terra darão os seus frutos.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 21, 'Ora, se andardes contrariamente para comigo, e não me quiseres ouvir, trarei sobre vos pragas sete vezes mais, conforme os vossos pecados.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 22, 'Enviarei para o meio de vós as feras do campo, as quais vos desfilharão, e destruirão o vosso gado, e vos reduzirão a pequeno número; e os vossos caminhos se tornarão desertos.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 23, 'Se nem ainda com isto quiserdes voltar a mim, mas continuardes a andar contrariamente para comigo,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 24, 'eu também andarei contrariamente para convosco; e eu, eu mesmo, vos ferirei sete vezes mais, por causa dos vossos pecados.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 25, 'Trarei sobre vós a espada, que executará a vingança do pacto, e vos aglomerareis nas vossas cidades; então enviarei a peste entre vós, e sereis entregues na mão do inimigo.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 26, 'Quando eu vos quebrar o sustento do pão, dez mulheres cozerão o vosso pão num só forno, e de novo vo-lo entregarão por peso; e comereis, mas não vos fartareis.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 27, 'Se nem ainda com isto me ouvirdes, mas continuardes a andar contrariamente para comigo,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 28, 'também eu andarei contrariamente para convosco com furor; e vos castigarei sete vezes mais, por causa dos vossos pecados.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 29, 'E comereis a carne de vossos filhos e a carne de vossas filhas.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 30, 'Destruirei os vossos altos, derrubarei as vossas imagens do sol, e lançarei os vossos cadáveres sobre os destroços dos vossos ídolos; e a minha alma vos abominará.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 31, 'Reduzirei as vossas cidades a deserto, e assolarei os vossos santuários, e não cheirarei o vosso cheiro suave.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 32, 'Assolarei a terra, e sobre ela pasmarão os vossos inimigos que nela habitam.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 33, 'Espalhar-vos-ei por entre as nações e, desembainhando a espada, vos perseguirei; a vossa terra será assolada, e as vossas cidades se tornarão em deserto.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 34, 'Então a terra folgará nos seus sábados, todos os dias da sua assolação, e vós estareis na terra dos vossos inimigos; nesse tempo a terra descansará, e folgará nos seus sábados.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 35, 'Por todos os dias da assolação descansará, pelos dias que não descansou nos vossos sábados, quando nela habitáveis.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 36, 'E, quanto aos que de vós ficarem, eu lhes meterei pavor no coração nas terras dos seus inimigos; e o ruído de uma folha agitada os porá em fuga; fugirão como quem foge da espada, e cairão sem que ninguém os persiga;', 1, CURRENT_TIMESTAMP, false),
(3, 26, 37, 'sim, embora não haja quem os persiga, tropeçarão uns sobre os outros como diante da espada; e não podereis resistir aos vossos inimigos.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 38, 'Assim perecereis entre as nações, e a terra dos vossos inimigos vos devorará;', 1, CURRENT_TIMESTAMP, false),
(3, 26, 39, 'e os que de vós ficarem definharão pela sua iniqüidade nas terras dos vossos inimigos, como também pela iniqüidade de seus pais.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 40, 'Então confessarão a sua iniqüidade, e a iniqüidade de seus pais, com as suas transgressões, com que transgrediram contra mim; igualmente confessarão que, por terem andado contrariamente para comigo,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 41, 'eu também andei contrariamente para com eles, e os trouxe para a terra dos seus inimigos. Se então o seu coração incircunciso se humilhar, e tomarem por bem o castigo da sua iniqüidade,', 1, CURRENT_TIMESTAMP, false),
(3, 26, 42, 'eu me lembrarei do meu pacto com Jacó, do meu pacto com Isaque, e do meu pacto com Abraão; e bem assim da terra me lembrarei.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 43, 'A terra também será deixada por eles e folgará nos seus sábados, sendo assolada por causa deles; e eles tomarão por bem o castigo da sua iniqüidade, em razão mesmo de que rejeitaram os meus preceitos e a sua alma desprezou os meus estatutos.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 44, 'Todavia, ainda assim, quando eles estiverem na terra dos seus inimigos, não os rejeitarei nem os abominarei a ponto de consumi-los totalmente e quebrar o meu pacto com eles; porque eu sou o Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 45, 'Antes por amor deles me lembrarei do pacto com os seus antepassados, que tirei da terra do Egito perante os olhos das nações, para ser o seu Deus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 26, 46, 'São esses os estatutos, os preceitos e as leis que o Senhor firmou entre si e os filhos de Israel, no monte Sinai, por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(3, 27, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando alguém fizer ao Senhor um voto especial que envolve pessoas, o voto será cumprido segundo a tua avaliação das pessoas.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 3, 'Se for de um homem, desde a idade de vinte até sessenta anos, a tua avaliação será de cinqüenta siclos de prata, segundo o siclo do santuário.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 4, 'Se for mulher, a tua avaliação será de trinta siclos.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 5, 'Se for de cinco anos até vinte, a tua avaliação do homem será de vinte siclos, e da mulher dez siclos.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 6, 'Se for de um mês até cinco anos, a tua avaliação do homem será de cinco siclos de prata, e da mulher três siclos de prata.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 7, 'Se for de sessenta anos para cima, a tua avaliação do homem será de quinze siclos, e da mulher dez siclos.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 8, 'Mas, se for mais pobre do que a tua avaliação, será apresentado perante o sacerdote, que o avaliará conforme as posses daquele que tiver feito o voto.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 9, 'Se for animal dos que se oferecem em oferta ao Senhor, tudo quanto der dele ao Senhor será santo.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 10, 'Não o mudará, nem o trocará, bom por mau, ou mau por bom; mas se de qualquer maneira trocar animal por animal, tanto um como o outro será santo.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 11, 'Se for algum animal imundo, dos que não se oferecem em oferta ao Senhor, apresentará o animal diante do sacerdote;', 1, CURRENT_TIMESTAMP, false),
(3, 27, 12, 'e o sacerdote o avaliará, seja bom ou seja mau; segundo tu, sacerdote, o avaliares, assim será.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 13, 'Mas, se o homem, com efeito, quiser remi-lo, acrescentará a quinta parte sobre a tua avaliação.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 14, 'Quando alguém santificar a sua casa para ser santa ao Senhor, o sacerdote a avaliará, seja boa ou seja má; como o sacerdote a avaliar, assim será.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 15, 'Mas, se aquele que a tiver santificado quiser remir a sua casa, então acrescentará a quinta parte do dinheiro sobre a tua avaliação, e terá a casa.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 16, 'Se alguém santificar ao Senhor uma parte do campo da sua possessão, então a tua avaliação será segundo a sua sementeira: um terreno que leva um hômer de semente de cevada será avaliado em cinqüenta siclos de prata.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 17, 'Se ele santificar o seu campo a partir do ano do jubileu, conforme a tua avaliação ficará.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 18, 'Mas se santificar o seu campo depois do ano do jubileu, o sacerdote lhe calculará o dinheiro conforme os anos que restam até o ano do jubileu, e assim será feita a tua avaliação.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 19, 'Se aquele que tiver santificado o campo, com efeito, quiser remi-lo, acrescentará a quinta parte do dinheiro da tua avaliação, e lhe ficará assegurado o campo.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 20, 'Se não o quiser remir, ou se houver vendido o campo a outrem, nunca mais poderá ser remido.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 21, 'Mas o campo, quando sair livre no ano do jubileu, será santo ao Senhor, como campo consagrado; a possessão dele será do sacerdote.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 22, 'Se alguém santificar ao Senhor um campo que tiver comprado, o qual não for parte do campo da sua possessão,', 1, CURRENT_TIMESTAMP, false),
(3, 27, 23, 'o sacerdote lhe contará o valor da tua avaliação até o ano do jubileu; e no mesmo dia dará a tua avaliação, como coisa santa ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 24, 'No ano do jubileu o campo tornará àquele de quem tiver sido comprado, isto é, àquele a quem pertencer a possessão do campo.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 25, 'Ora, toda tua avaliação se fará conforme o siclo do santuário; o siclo será de vinte jeiras.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 26, 'Contudo o primogênito dum animal, que por ser primogênito já pertence ao senhor, ninguém o santificará; seja boi ou gado miúdo, pertence ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 27, 'Mas se o primogênito for dum animal imundo, remir-se-á segundo a tua avaliação, e a esta se acrescentará a quinta parte; e se não for remido, será vendido segundo a tua avaliação.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 28, 'Todavia, nenhuma coisa consagrada ao Senhor por alguém, daquilo que possui, seja homem, ou animal, ou campo da sua possessão, será vendida nem será remida; toda coisa consagrada será santíssima ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 29, 'Nenhuma pessoa que dentre os homens for devotada será resgatada; certamente será morta.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 30, 'Também todos os dízimos da terra, quer dos cereais, quer do fruto das árvores, pertencem ao senhor; santos são ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 31, 'Se alguém quiser remir uma parte dos seus dízimos, acrescentar-lhe-á a quinta parte.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 32, 'Quanto a todo dízimo do gado e do rebanho, de tudo o que passar debaixo da vara, esse dízimo será santo ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 33, 'Não se examinará se é bom ou mau, nem se trocará; mas se, com efeito, se trocar, tanto um como o outro será santo; não serão remidos.', 1, CURRENT_TIMESTAMP, false),
(3, 27, 34, 'são esses os mandamentos que o Senhor ordenou a Moisés, para os filhos de Israel, no monte Sinai.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 1, 'Visto que muitos têm empreendido fazer uma narração coordenada dos fatos que entre nós se realizaram,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 2, 'segundo no-los transmitiram os que desde o princípio foram testemunhas oculares e ministros da palavra,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 3, 'também a mim, depois de haver investido tudo cuidadosamente desde o começo, pareceu-me bem, ó excelentíssimo Teófilo, escrever-te uma narração em ordem.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 4, 'para que conheças plenamente a verdade das coisas em que foste instruído.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 5, 'Houve nos dias do Rei Herodes, rei da Judéia, um sacerdote chamado Zacarias, da turma de Abias; e sua mulher era descendente de Arão, e chamava-se Isabel.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 6, 'Ambos eram justos diante de Deus, andando irrepreensíveis em todos os mandamentos e preceitos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 7, 'Mas não tinham filhos, porque Isabel era estéril, e ambos avançados em idade.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 8, 'Ora, estando ele a exercer as funções sacerdotais perante Deus, na ordem da sua turma,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 9, 'segundo o costume do sacerdócio, coube-lhe por sorte entrar no santuário do Senhor, para oferecer o incenso;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 10, 'e toda a multidão do povo orava da parte de fora, à hora do incenso.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 11, 'Apareceu-lhe, então, um anjo do Senhor, em pé à direita do altar do incenso.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 12, 'E Zacarias, vendo-o, ficou turbado, e o temor o assaltou.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 13, 'Mas o anjo lhe disse: Não temais, Zacarias; porque a tua oração foi ouvida, e Isabel, tua mulher, te dará à luz um filho, e lhe porás o nome de João;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 14, 'e terás alegria e regozijo, e muitos se alegrarão com o seu nascimento;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 15, 'porque ele será grande diante do Senhor; não beberá vinho, nem bebida forte; e será cheio do Espírito Santo já desde o ventre de sua mãe;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 16, 'converterá muitos dos filhos de Israel ao Senhor seu Deus;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 17, 'irá adiante dele no espírito e poder de Elias, para converter os corações dos pais aos filhos, e os rebeldes à prudência dos justos, a fim de preparar para o Senhor um povo apercebido.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 18, 'Disse então Zacarias ao anjo: Como terei certeza disso? pois eu sou velho, e minha mulher também está avançada em idade.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 19, 'Ao que lhe respondeu o anjo: Eu sou Gabriel, que assisto diante de Deus, e fui enviado para te falar e te dar estas boas novas;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 20, 'e eis que ficarás mudo, e não poderás falar até o dia em que estas coisas aconteçam; porquanto não creste nas minhas palavras, que a seu tempo hão de cumprir-se.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 21, 'O povo estava esperando Zacarias, e se admirava da sua demora no santuário.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 22, 'Quando saiu, porém, não lhes podia falar, e perceberam que tivera uma visão no santuário. E falava-lhes por acenos, mas permanecia mudo.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 23, 'E, terminados os dias do seu ministério, voltou para casa.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 24, 'Depois desses dias Isabel, sua mulher, concebeu, e por cinco meses se ocultou, dizendo:', 1, CURRENT_TIMESTAMP, false),
(42, 1, 25, 'Assim me fez o Senhor nos dias em que atentou para mim, a fim de acabar com o meu opróbrio diante dos homens.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 26, 'Ora, no sexto mês, foi o anjo Gabriel enviado por Deus a uma cidade da Galiléia, chamada Nazaré,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 27, 'a uma virgem desposada com um varão cujo nome era José, da casa de Davi; e o nome da virgem era Maria.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 28, 'E, entrando o anjo onde ela estava disse: Salve, agraciada; o Senhor é contigo.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 29, 'Ela, porém, ao ouvir estas palavras, turbou-se muito e pôs-se a pensar que saudação seria essa.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 30, 'Disse-lhe então o anjo: Não temas, Maria; pois achaste graça diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 31, 'Eis que conceberás e darás à luz um filho, ao qual porás o nome de Jesus.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 32, 'Este será grande e será chamado filho do Altíssimo; o Senhor Deus lhe dará o trono de Davi seu pai;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 33, 'e reinará eternamente sobre a casa de Jacó, e o seu reino não terá fim.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 34, 'Então Maria perguntou ao anjo: Como se fará isso, uma vez que não conheço varão?', 1, CURRENT_TIMESTAMP, false),
(42, 1, 35, 'Respondeu-lhe o anjo: Virá sobre ti o Espírito Santo, e o poder do Altíssimo te cobrirá com a sua sombra; por isso o que há de nascer será chamado santo, Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 36, 'Eis que também Isabel, tua parenta concebeu um filho em sua velhice; e é este o sexto mês para aquela que era chamada estéril;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 37, 'porque para Deus nada será impossível.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 38, 'Disse então Maria. Eis aqui a serva do Senhor; cumpra-se em mim segundo a tua palavra. E o anjo ausentou-se dela.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 39, 'Naqueles dias levantou-se Maria, foi apressadamente à região montanhosa, a uma cidade de Judá,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 40, 'entrou em casa de Zacarias e saudou a Isabel.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 41, 'Ao ouvir Isabel a saudação de Maria, saltou a criancinha no seu ventre, e Isabel ficou cheia do Espírito Santo,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 42, 'e exclamou em alta voz: Bendita és tu entre as mulheres, e bendito é o fruto do teu ventre!', 1, CURRENT_TIMESTAMP, false),
(42, 1, 43, 'E donde me provém isto, que venha visitar-me a mãe do meu Senhor?', 1, CURRENT_TIMESTAMP, false),
(42, 1, 44, 'Pois logo que me soou aos ouvidos a voz da tua saudação, a criancinha saltou de alegria dentro de mim.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 45, 'Bem-aventurada aquela que creu que se hão de cumprir as coisas que da parte do Senhor lhe foram ditas.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 46, 'Disse então Maria: A minha alma engrandece ao Senhor,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 47, 'e o meu espírito exulta em Deus meu Salvador;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 48, 'porque atentou na condição humilde de sua serva. Desde agora, pois, todas as gerações me chamarão bem-aventurada,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 49, 'porque o Poderoso me fez grandes coisas; e santo é o seu nome.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 50, 'E a sua misericórdia vai de geração em geração sobre os que o temem.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 51, 'Com o seu braço manifestou poder; dissipou os que eram soberbos nos pensamentos de seus corações;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 52, 'depôs dos tronos os poderosos, e elevou os humildes.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 53, 'Aos famintos encheu de bens, e vazios despediu os ricos.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 54, 'Auxiliou a Isabel, seu servo, lembrando-se de misericórdia', 1, CURRENT_TIMESTAMP, false),
(42, 1, 55, '{como falou a nossos pais} para com Abraão e a sua descendência para sempre.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 56, 'E Maria ficou com ela cerca de três meses; e depois voltou para sua casa.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 57, 'Ora, completou-se para Isabel o tempo de dar à luz, e teve um filho.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 58, 'Ouviram seus vizinhos e parentes que o Senhor lhe multiplicara a sua misericórdia, e se alegravam com ela.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 59, 'Sucedeu, pois, no oitavo dia, que vieram circuncidar o menino; e queriam dar-lhe o nome de seu pai, Zacarias.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 60, 'Respondeu, porém, sua mãe: De modo nenhum, mas será chamado João.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 61, 'Ao que lhe disseram: Ninguém há na tua parentela que se chame por este nome.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 62, 'E perguntaram por acenos ao pai como queria que se chamasse.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 63, 'E pedindo ele uma tabuinha, escreveu: Seu nome é João. E todos se admiraram.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 64, 'Imediatamente a boca se lhe abriu, e a língua se lhe soltou; louvando a Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 65, 'Então veio temor sobre todos os seus vizinhos; e em toda a região montanhosa da Judéia foram divulgadas todas estas coisas.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 66, 'E todos os que delas souberam as guardavam no coração, dizendo: Que virá a ser, então, este menino? Pois a mão do Senhor estava com ele.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 67, 'Zacarias, seu pai, ficou cheio do Espírito Santo e profetizou, dizendo:', 1, CURRENT_TIMESTAMP, false),
(42, 1, 68, 'Bendito, seja o Senhor Deus de Israel, porque visitou e remiu o seu povo,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 69, 'e para nós fez surgir uma salvação poderosa na casa de Davi, seu servo;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 70, 'assim como desde os tempos antigos tem anunciado pela boca dos seus santos profetas;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 71, 'para nos livrar dos nossos inimigos e da mão de todos os que nos odeiam;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 72, 'para usar de misericórdia com nossos pais, e lembrar-se do seu santo pacto', 1, CURRENT_TIMESTAMP, false),
(42, 1, 73, 'e do juramento que fez a Abrão, nosso pai,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 74, 'de conceder-nos que, libertados da mão de nossos inimigos, o servíssemos sem temor,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 75, 'em santidade e justiça perante ele, todos os dias da nossa vida.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 76, 'E tu, menino, serás chamado profeta do Altíssimo, porque irás ante a face do Senhor, a preparar os seus caminhos;', 1, CURRENT_TIMESTAMP, false),
(42, 1, 77, 'para dar ao seu povo conhecimento da salvação, na remissão dos seus pecados,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 78, 'graças à entranhável misericórdia do nosso Deus, pela qual nos há de visitar a aurora lá do alto,', 1, CURRENT_TIMESTAMP, false),
(42, 1, 79, 'para alumiar aos que jazem nas trevas e na sombra da morte, a fim de dirigir os nossos pés no caminho da paz.', 1, CURRENT_TIMESTAMP, false),
(42, 1, 80, 'Ora, o menino crescia, e se robustecia em espírito; e habitava nos desertos até o dia da sua manifestação a Israel.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 1, 'Naqueles dias saiu um decreto da parte de César Augusto, para que todo o mundo fosse recenseado.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 2, 'Este primeiro recenseamento foi feito quando Quirínio era governador da Síria.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 3, 'E todos iam alistar-se, cada um à sua própria cidade.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 4, 'Subiu também José, da Galiléia, da cidade de Nazaré, à cidade de Davi, chamada Belém, porque era da casa e família de Davi,', 1, CURRENT_TIMESTAMP, false),
(42, 2, 5, 'a fim de alistar-se com Maria, sua esposa, que estava grávida.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 6, 'Enquanto estavam ali, chegou o tempo em que ela havia de dar à luz,', 1, CURRENT_TIMESTAMP, false),
(42, 2, 7, 'e teve a seu filho primogênito; envolveu-o em faixas e o deitou em uma manjedoura, porque não havia lugar para eles na estalagem.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 8, 'Ora, havia naquela mesma região pastores que estavam no campo, e guardavam durante as vigílias da noite o seu rebanho.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 9, 'E um anjo do Senhor apareceu-lhes, e a glória do Senhor os cercou de resplendor; pelo que se encheram de grande temor.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 10, 'O anjo, porém, lhes disse: Não temais, porquanto vos trago novas de grande alegria que o será para todo o povo:', 1, CURRENT_TIMESTAMP, false),
(42, 2, 11, 'É que vos nasceu hoje, na cidade de Davi, o Salvador, que é Cristo, o Senhor.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 12, 'E isto vos será por sinal: Achareis um menino envolto em faixas, e deitado em uma manjedoura.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 13, 'Então, de repente, apareceu junto ao anjo grande multidão da milícia celestial, louvando a Deus e dizendo:', 1, CURRENT_TIMESTAMP, false),
(42, 2, 14, 'Glória a Deus nas maiores alturas, e paz na terra entre os homens de boa vontade.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 15, 'E logo que os anjos se retiraram deles para o céu, diziam os pastores uns aos outros: Vamos já até Belém, e vejamos isso que aconteceu e que o Senhor nos deu a conhecer.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 16, 'Foram, pois, a toda a pressa, e acharam Maria e José, e o menino deitado na manjedoura;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 17, 'e, vendo-o, divulgaram a palavra que acerca do menino lhes fora dita;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 18, 'e todos os que a ouviram se admiravam do que os pastores lhes diziam.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 19, 'Maria, porém, guardava todas estas coisas, meditando-as em seu coração.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 20, 'E voltaram os pastores, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, como lhes fora dito.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 21, 'Quando se completaram os oito dias para ser circuncidado o menino, foi-lhe dado o nome de Jesus, que pelo anjo lhe fora posto antes de ser concebido.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 22, 'Terminados os dias da purificação, segundo a lei de Moisés, levaram-no a Jerusalém, para apresentá-lo ao Senhor', 1, CURRENT_TIMESTAMP, false),
(42, 2, 23, '{conforme está escrito na lei do Senhor: Todo primogênito será consagrado ao Senhor},', 1, CURRENT_TIMESTAMP, false),
(42, 2, 24, 'e para oferecerem um sacrifício segundo o disposto na lei do Senhor: um par de rolas, ou dois pombinhos.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 25, 'Ora, havia em Jerusalém um homem cujo nome era Simeão; e este homem, justo e temente a Deus, esperava a consolação de Israel; e o Espírito Santo estava sobre ele.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 26, 'E lhe fora revelado pelo Espírito Santo que ele não morreria antes de ver o Cristo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 27, 'Assim pelo Espírito foi ao templo; e quando os pais trouxeram o menino Jesus, para fazerem por ele segundo o costume da lei,', 1, CURRENT_TIMESTAMP, false),
(42, 2, 28, 'Simeão o tomou em seus braços, e louvou a Deus, e disse:', 1, CURRENT_TIMESTAMP, false),
(42, 2, 29, 'Agora, Senhor, despedes em paz o teu servo, segundo a tua palavra;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 30, 'pois os meus olhos já viram a tua salvação,', 1, CURRENT_TIMESTAMP, false),
(42, 2, 31, 'a qual tu preparaste ante a face de todos os povos;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 32, 'luz para revelação aos gentios, e para glória do teu povo Israel.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 33, 'Enquanto isso, seu pai e sua mãe se admiravam das coisas que deles se diziam.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 34, 'E Simeão os abençoou, e disse a Maria, mãe do menino: Eis que este é posto para queda e para levantamento de muitos em Israel, e para ser alvo de contradição,', 1, CURRENT_TIMESTAMP, false),
(42, 2, 35, 'sim, e uma espada traspassará a tua própria alma, para que se manifestem os pensamentos de muitos corações.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 36, 'Havia também uma profetisa, Ana, filha de Fanuel, da tribo de Aser. Era já avançada em idade, tendo vivido com o marido sete anos desde a sua virgindade;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 37, 'e era viúva, de quase oitenta e quatro anos. Não se afastava do templo, servindo a Deus noite e dia em jejuns e orações.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 38, 'Chegando ela na mesma hora, deu graças a Deus, e falou a respeito do menino a todos os que esperavam a redenção de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 39, 'Assim que cumpriram tudo segundo a lei do Senhor, voltaram à Galiléia, para sua cidade de Nazaré.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 40, 'E o menino ia crescendo e fortalecendo-se, ficando cheio de sabedoria; e a graça de Deus estava sobre ele.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 41, 'Ora, seus pais iam todos os anos a Jerusalém, à festa da páscoa.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 42, 'Quando Jesus completou doze anos, subiram eles segundo o costume da festa;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 43, 'e, terminados aqueles dias, ao regressarem, ficou o menino Jesus em Jerusalém sem o saberem seus pais;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 44, 'julgando, porém, que estivesse entre os companheiros de viagem, andaram caminho de um dia, e o procuravam entre os parentes e conhecidos;', 1, CURRENT_TIMESTAMP, false),
(42, 2, 45, 'e não o achando, voltaram a Jerusalém em busca dele.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 46, 'E aconteceu que, passados três dias, o acharam no templo, sentado no meio dos doutores, ouvindo-os, e interrogando-os.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 47, 'E todos os que o ouviam se admiravam da sua inteligência e das suas respostas.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 48, 'Quando o viram, ficaram maravilhados, e disse-lhe sua mãe: Filho, por que procedeste assim para conosco? Eis que teu pai e eu ansiosos te procurávamos.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 49, 'Respondeu-lhes ele: Por que me procuráveis? Não sabíeis que eu devia estar na casa de meu Pai?', 1, CURRENT_TIMESTAMP, false),
(42, 2, 50, 'Eles, porém, não entenderam as palavras que lhes dissera.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 51, 'Então, descendo com eles, foi para Nazaré, e era-lhes sujeito. E sua mãe guardava todas estas coisas em seu coração.', 1, CURRENT_TIMESTAMP, false),
(42, 2, 52, 'E crescia Jesus em sabedoria, em estatura e em graça diante de Deus e dos homens.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 1, 'No décimo quinto ano do reinado de Tibério César, sendo Pôncio Pilatos governador da Judéia, Herodes tetrarca da Galiléia, seu irmão Filipe tetrarca da região da Ituréia e de Traconites, e Lisânias tetrarca de Abilene,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 2, 'sendo Anás e Caifás sumos sacerdotes, veio a palavra de Deus a João, filho de Zacarias, no deserto.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 3, 'E ele percorreu toda a circunvizinhança do Jordão, pregando o batismo de arrependimento para remissão de pecados;', 1, CURRENT_TIMESTAMP, false),
(42, 3, 4, 'como está escrito no livro das palavras do profeta Isaías: Voz do que clama no deserto: Preparai o caminho do Senhor; endireitai as suas veredas.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 5, 'Todo vale se encherá, e se abaixará todo monte e outeiro; o que é tortuoso se endireitará, e os caminhos escabrosos se aplanarão;', 1, CURRENT_TIMESTAMP, false),
(42, 3, 6, 'e toda a carne verá a salvação de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 7, 'João dizia, pois, às multidões que saíam para ser batizadas por ele: Raça de víboras, quem vos ensina a fugir da ira vindoura?', 1, CURRENT_TIMESTAMP, false),
(42, 3, 8, 'Produzi, pois, frutos dignos de arrependimento; e não comeceis a dizer em vós mesmos: Temos por pai a Abrão; porque eu vos digo que até destas pedras Deus pode suscitar filhos a Abrão.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 9, 'Também já está posto o machado à raiz das árvores; toda árvore, pois, que não produz bom fruto, é cortada e lançada no fogo.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 10, 'Ao que lhe perguntavam as multidões: Que faremos, pois?', 1, CURRENT_TIMESTAMP, false),
(42, 3, 11, 'Respondia-lhes então: Aquele que tem duas túnicas, reparta com o que não tem nenhuma, e aquele que tem alimentos, faça o mesmo.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 12, 'Chegaram também uns publicanos para serem batizados, e perguntaram-lhe: Mestre, que havemos nós de fazer?', 1, CURRENT_TIMESTAMP, false),
(42, 3, 13, 'Respondeu-lhes ele: Não cobreis além daquilo que vos foi prescrito.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 14, 'Interrogaram-no também uns soldados: E nós, que faremos? Disse-lhes: A ninguém queirais extorquir coisa alguma; nem deis denúncia falsa; e contentai-vos com o vosso soldo.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 15, 'Ora, estando o povo em expectativa e arrazoando todos em seus corações a respeito de João, se porventura seria ele o Cristo,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 16, 'respondeu João a todos, dizendo: Eu, na verdade, vos batizo em água, mas vem aquele que é mais poderoso do que eu, de quem não sou digno de desatar a correia das alparcas; ele vos batizará no Espírito Santo e em fogo.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 17, 'A sua pá ele tem na mão para limpar bem a sua eira, e recolher o trigo ao seu celeiro; mas queimará a palha em fogo inextinguível.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 18, 'Assim pois, com muitas outras exortações ainda, anunciava o evangelho ao povo.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 19, 'Mas o tetrarca Herodes, sendo repreendido por ele por causa de Herodias, mulher de seu irmão, e por todas as maldades que havia feito,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 20, 'acrescentou a todas elas ainda esta, a de encerrar João no cárcere.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 21, 'Quando todo o povo fora batizado, tendo sido Jesus também batizado, e estando ele a orar, o céu se abriu;', 1, CURRENT_TIMESTAMP, false),
(42, 3, 22, 'e o Espírito Santo desceu sobre ele em forma corpórea, como uma pomba; e ouviu-se do céu esta voz: Tu és o meu Filho amado; em ti me comprazo.', 1, CURRENT_TIMESTAMP, false),
(42, 3, 23, 'Ora, Jesus, ao começar o seu ministério, tinha cerca de trinta anos; sendo {como se cuidava} filho de José, filho de Eli;', 1, CURRENT_TIMESTAMP, false),
(42, 3, 24, 'Eli de Matate, Matate de Levi, Levi de Melqui, Melqui de Janai, Janai de José,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 25, 'José de Matatias, Matatias de Amós, Amós de Naum, Naum de Esli, Esli de Nagai,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 26, 'Nagai de Maate, Maate de Matatias, Matatias de Semei, Semei de Joseque, Joseque de Jodá,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 27, 'Jodá de Joanã, Joanã de Resa, Resa de Zorobabel, Zorobabel de Salatiel, Salatiel de Neri,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 28, 'Neri de Melqui, Melqui de Adi, Adi de Cosão, Cosão de Elmodã, Elmodão de Er,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 29, 'Er de Josué, Josué de Eliézer, Eliézer de Jorim, Jorim de Matate, Matate de Levi,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 30, 'Levi de Simeão, Simeão de Judá, Judá de José, José de Jonã, Jonã de Eliaquim,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 31, 'Eliaquim de Meleá, Meleá de Mená, Mená de Matatá, Matatá de Natã, Natã de Davi,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 32, 'Davi de Jessé, Jessé de Obede, Obede de Boaz, Boaz de Salá, Salá de Nasom,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 33, 'Nasom de Aminadabe, Aminadabe de Admim, Admim de Arni, Arni de Esrom, Esrom de Farés, Farés de Judá,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 34, 'Judá de Jacó, Jacó de Isaque, Isaque de Abraão, Abraão de Tará, Tará de Naor,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 35, 'Naor de Seruque, Seruque de Ragaú, Ragaú de Faleque, Faleque de Eber, Eber de Salá,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 36, 'Salá de Cainã, Cainã de Arfaxade, Arfaxade de Sem, Sem de Noé, Noé de Lameque,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 37, 'Lameque de Matusalém, Matusalém de Enoque, Enoque de Jarede, Jarede de Maleleel, Maleleel de Cainã,', 1, CURRENT_TIMESTAMP, false),
(42, 3, 38, 'Cainã de Enos, Enos de Sete, Sete de Adão, e Adão de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 1, 'Jesus, pois, cheio do Espírito Santo, voltou do Jordão; e era levado pelo Espírito no deserto,', 1, CURRENT_TIMESTAMP, false),
(42, 4, 2, 'durante quarenta dias, sendo tentado pelo Diabo. E naqueles dias não comeu coisa alguma; e terminados eles, teve fome.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 3, 'Disse-lhe então o Diabo: Se tu és Filho de Deus, manda a esta pedra que se torne em pão.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 4, 'Jesus, porém, lhe respondeu: Está escrito: Nem só de pão viverá o homem.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 5, 'Então o Diabo, levando-o a um lugar elevado, mostrou-lhe num relance todos os reinos do mundo.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 6, 'E disse-lhe: Dar-te-ei toda a autoridade e glória destes reinos, porque me foi entregue, e a dou a quem eu quiser;', 1, CURRENT_TIMESTAMP, false),
(42, 4, 7, 'se tu, me adorares, será toda tua.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 8, 'Respondeu-lhe Jesus: Está escrito: Ao Senhor teu Deus adorarás, e só a ele servirás.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 9, 'Então o levou a Jerusalém e o colocou sobre o pináculo do templo e lhe disse: Se tu és Filho de Deus, lança-te daqui abaixo;', 1, CURRENT_TIMESTAMP, false),
(42, 4, 10, 'porque está escrito: Aos seus anjos ordenará a teu respeito, que te guardem;', 1, CURRENT_TIMESTAMP, false),
(42, 4, 11, 'e: eles te susterão nas mãos, para que nunca tropeces em alguma pedra.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 12, 'Respondeu-lhe Jesus: Dito está: Não tentarás o Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 13, 'Assim, tendo o Diabo acabado toda sorte de tentação, retirou-se dele até ocasião oportuna.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 14, 'Então voltou Jesus para a Galiléia no poder do Espírito; e a sua fama correu por toda a circunvizinhança.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 15, 'Ensinava nas sinagogas deles, e por todos era louvado.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 16, 'Chegando a Nazaré, onde fora criado; entrou na sinagoga no dia de sábado, segundo o seu costume, e levantou-se para ler.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 17, 'Foi-lhe entregue o livro do profeta Isaías; e abrindo-o, achou o lugar em que estava escrito:', 1, CURRENT_TIMESTAMP, false),
(42, 4, 18, 'O Espírito do Senhor está sobre mim, porquanto me ungiu para anunciar boas novas aos pobres; enviou-me para proclamar libertação aos cativos, e restauração da vista aos cegos, para pôr em liberdade os oprimidos,', 1, CURRENT_TIMESTAMP, false),
(42, 4, 19, 'e para proclamar o ano aceitável do Senhor.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 20, 'E fechando o livro, devolveu-o ao assistente e sentou-se; e os olhos de todos na sinagoga estavam fitos nele.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 21, 'Então começou a dizer-lhes: Hoje se cumpriu esta escritura aos vossos ouvidos.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 22, 'E todos lhe davam testemunho, e se admiravam das palavras de graça que saíam da sua boca; e diziam: Este não é filho de José?', 1, CURRENT_TIMESTAMP, false),
(42, 4, 23, 'Disse-lhes Jesus: Sem dúvida me direis este provérbio: Médico, cura-te a ti mesmo; Tudo o que ouvimos teres feito em Cafarnaum, faze-o também aqui na tua terra.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 24, 'E prosseguiu: Em verdade vos digo que nenhum profeta é aceito na sua terra.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 25, 'Em verdade vos digo que muitas viúvas havia em Israel nos dias de Elias, quando céu se fechou por três anos e seis meses, de sorte que houve grande fome por toda a terra;', 1, CURRENT_TIMESTAMP, false),
(42, 4, 26, 'e a nenhuma delas foi enviado Elias, senão a uma viúva em Serepta de Sidom.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 27, 'Também muitos leprosos havia em Israel no tempo do profeta Elizeu, mas nenhum deles foi purificado senão Naamã, o sírio.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 28, 'Todos os que estavam na sinagoga, ao ouvirem estas coisas, ficaram cheios de ira.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 29, 'e, levantando-se, expulsaram-no da cidade e o levaram até o despenhadeiro do monte em que a sua cidade estava edificada, para dali o precipitarem.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 30, 'Ele, porém, passando pelo meio deles, seguiu o seu caminho.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 31, 'Então desceu a Cafarnaum, cidade da Galiléia, e os ensinava no sábado.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 32, 'e maravilharam-se da sua doutrina, porque a sua palavra era com autoridade.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 33, 'Havia na sinagoga um homem que tinha o espírito de um demônio imundo; e gritou em alta voz:', 1, CURRENT_TIMESTAMP, false),
(42, 4, 34, 'Ah! que temos nós contigo, Jesus, nazareno? vieste destruir-nos? Bem sei quem é: o Santo de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 35, 'Mas Jesus o repreendeu, dizendo: Cala-te, e sai dele. E o demônio, tendo-o lançado por terra no meio do povo, saiu dele sem lhe fazer mal algum.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 36, 'E veio espanto sobre todos, e falavam entre si, perguntando uns aos outros: Que palavra é esta, pois com autoridade e poder ordena aos espíritos imundos, e eles saem?', 1, CURRENT_TIMESTAMP, false),
(42, 4, 37, 'E se divulgava a sua fama por todos os lugares da circunvizinhança.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 38, 'Ora, levantando-se Jesus, saiu da sinagoga e entrou em casa de Simão; e estando a sogra de Simão enferma com muita febre, rogaram-lhe por ela.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 39, 'E ele, inclinando-se para ela, repreendeu a febre, e esta a deixou. Imediatamente ela se levantou e os servia.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 40, 'Ao pôr do sol, todos os que tinham enfermos de várias doenças lhos traziam; e ele punha as mãos sobre cada um deles e os curava.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 41, 'Também de muitos saíam demônios, gritando e dizendo: Tu és o Filho de Deus. Ele, porém, os repreendia, e não os deixava falar; pois sabiam que ele era o Cristo.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 42, 'Ao romper do dia saiu, e foi a um lugar deserto; e as multidões procuravam-no e, vindo a ele, queriam detê-lo, para que não se ausentasse delas.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 43, 'Ele, porém, lhes disse: É necessário que também às outras cidades eu anuncie o evangelho do reino de Deus; porque para isso é que fui enviado.', 1, CURRENT_TIMESTAMP, false),
(42, 4, 44, 'E pregava nas sinagogas da Judéia.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 1, 'Certa vez, quando a multidão apertava Jesus para ouvir a palavra de Deus, ele estava junto ao lago de Genezaré;', 1, CURRENT_TIMESTAMP, false),
(42, 5, 2, 'e viu dois barcos junto à praia do lago; mas os pescadores haviam descido deles, e estavam lavando as redes.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 3, 'Entrando ele num dos barcos, que era o de Simão, pediu-lhe que o afastasse um pouco da terra; e, sentando-se, ensinava do barco as multidões.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 4, 'Quando acabou de falar, disse a Simão: Faze-te ao largo e lançai as vossas redes para a pesca.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 5, 'Ao que disse Simão: Mestre, trabalhamos a noite toda, e nada apanhamos; mas, sobre tua palavra, lançarei as redes.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 6, 'Feito isto, apanharam uma grande quantidade de peixes, de modo que as redes se rompiam.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 7, 'Acenaram então aos companheiros que estavam no outro barco, para virem ajudá-los. Eles, pois, vieram, e encheram ambos os barcos, de maneira tal que quase iam a pique.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 8, 'Vendo isso Simão Pedro, prostrou-se aos pés de Jesus, dizendo: Retira-te de mim, Senhor, porque sou um homem pecador.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 9, 'Pois, à vista da pesca que haviam feito, o espanto se apoderara dele e de todos os que com ele estavam,', 1, CURRENT_TIMESTAMP, false),
(42, 5, 10, 'bem como de Tiago e João, filhos de Zebedeu, que eram sócios de Simão. Disse Jesus a Simão: Não temas; de agora em diante serás pescador de homens.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 11, 'E, levando eles os barcos para a terra, deixaram tudo e o seguiram.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 12, 'Estando ele numa das cidades, apareceu um homem cheio de lepra que, vendo a Jesus, prostrou-se com o rosto em terra e suplicou-lhe: Senhor, se quiseres, bem podes tornar-me limpo.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 13, 'Jesus, pois, estendendo a mão, tocou-lhe, dizendo: Quero; sê limpo. No mesmo instante desapareceu dele a lepra.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 14, 'Ordenou-lhe, então, que a ninguém contasse isto. Mas vai, disse ele, mostra-te ao sacerdote e faze a oferta pela tua purificação, conforme Moisés determinou, para lhes servir de testemunho.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 15, 'A sua fama, porém, se divulgava cada vez mais, e grandes multidões se ajuntavam para ouvi-lo e serem curadas das suas enfermidades.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 16, 'Mas ele se retirava para os desertos, e ali orava.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 17, 'Um dia, quando ele estava ensinando, achavam-se ali sentados fariseus e doutores da lei, que tinham vindo de todas as aldeias da Galiléia e da Judéia, e de Jerusalém; e o poder do Senhor estava com ele para curar.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 18, 'E eis que uns homens, trazendo num leito um paralítico, procuravam introduzi-lo e pô-lo diante dele.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 19, 'Mas, não achando por onde o pudessem introduzir por causa da multidão, subiram ao eirado e, por entre as telhas, o baixaram com o leito, para o meio de todos, diante de Jesus.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 20, 'E vendo-lhes a fé, disse ele: Homem, são-te perdoados os teus pecados.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 21, 'Então os escribas e os fariseus começaram a arrazoar, dizendo: Quem é este que profere blasfêmias? Quem é este que profere blasfêmias? Quem pode perdoar pecados, senão só Deus?', 1, CURRENT_TIMESTAMP, false),
(42, 5, 22, 'Jesus, porém, percebendo os seus pensamentos, respondeu, e disse-lhes: Por que arrazoais em vossos corações?', 1, CURRENT_TIMESTAMP, false),
(42, 5, 23, 'Qual é mais fácil? dizer: São-te perdoados os teus pecados; ou dizer: Levanta-te, e anda?', 1, CURRENT_TIMESTAMP, false),
(42, 5, 24, 'Ora, para que saibais que o Filho do homem tem sobre a terra autoridade para perdoar pecados {disse ao paralítico}, a ti te digo: Levanta-te, toma o teu leito e vai para tua casa.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 25, 'Imediatamente se levantou diante deles, tomou o leito em que estivera deitado e foi para sua casa, glorificando a Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 26, 'E, tomados de pasmo, todos glorificavam a Deus; e diziam, cheios de temor: Hoje vimos coisas extraordinárias.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 27, 'Depois disso saiu e, vendo um publicano chamado Levi, sentado na coletoria, disse-lhe: Segue-me.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 28, 'Este, deixando tudo, levantou-se e o seguiu.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 29, 'Deu-lhe então Levi um lauto banquete em sua casa; havia ali grande número de publicanos e outros que estavam com eles à mesa.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 30, 'Murmuravam, pois, os fariseus e seus escribas contra os discípulos, perguntando: Por que comeis e bebeis com publicanos e pecadores?', 1, CURRENT_TIMESTAMP, false),
(42, 5, 31, 'Respondeu-lhes Jesus: Não necessitam de médico os sãos, mas sim os enfermos;', 1, CURRENT_TIMESTAMP, false),
(42, 5, 32, 'eu não vim chamar justos, mas pecadores, ao arrependimento.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 33, 'Disseram-lhe eles: Os discípulos de João jejuam freqüentemente e fazem orações, como também os dos fariseus, mas os teus comem e bebem.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 34, 'Respondeu-lhes Jesus: Podeis, porventura, fazer jejuar os convidados às núpcias enquanto o noivo está com eles?', 1, CURRENT_TIMESTAMP, false),
(42, 5, 35, 'Dias virão, porém, em que lhes será tirado o noivo; naqueles dias, sim hão de jejuar.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 36, 'Propôs-lhes também uma parábola: Ninguém tira um pedaço de um vestido novo para o coser em vestido velho; do contrário, não somente rasgará o novo, mas também o pedaço do novo não condirá com o velho.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 37, 'E ninguém deita vinho novo em odres velhos; do contrário, o vinho novo romperá os odres e se derramará, e os odres se perderão;', 1, CURRENT_TIMESTAMP, false),
(42, 5, 38, 'mas vinho novo deve ser deitado em odres novos.', 1, CURRENT_TIMESTAMP, false),
(42, 5, 39, 'E ninguém, tendo bebido o velho, quer o novo; porque diz: O velho é bom.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 1, 'E sucedeu que, num dia de sábado, passava Jesus pelas searas; e seus discípulos iam colhendo espigas e, debulhando-as com as mãos, as comiam.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 2, 'Alguns dos fariseus, porém, perguntaram; Por que estais fazendo o que não é lícito fazer nos sábados?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 3, 'E Jesus, respondendo-lhes, disse: Nem ao menos tendes lido o que fez Davi quando teve fome, ele e seus companheiros?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 4, 'Como entrou na casa de Deus, tomou os pães da proposição, dos quais não era lícito comer senão só aos sacerdotes, e deles comeu e deu também aos companheiros?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 5, 'Também lhes disse: O Filho do homem é Senhor do sábado.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 6, 'Ainda em outro sábado entrou na sinagoga, e pôs-se a ensinar. Estava ali um homem que tinha a mão direita atrofiada.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 7, 'E os escribas e os fariseus observavam-no, para ver se curaria em dia de sábado, para acharem de que o acusar.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 8, 'Mas ele, conhecendo-lhes os pensamentos, disse ao homem que tinha a mão atrofiada: Levanta-te, e fica em pé aqui no maio. E ele, levantando-se, ficou em pé.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 9, 'Disse-lhes, então, Jesus: Eu vos pergunto: É lícito no sábado fazer bem, ou fazer mal? salvar a vida, ou tirá-la?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 10, 'E olhando para todos em redor, disse ao homem: Estende a tua mão. Ele assim o fez, e a mão lhe foi restabelecida.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 11, 'Mas eles se encheram de furor; e uns com os outros conferenciam sobre o que fariam a Jesus.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 12, 'Naqueles dias retirou-se para o monte a fim de orar; e passou a noite toda em oração a Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 13, 'Depois do amanhecer, chamou seus discípulos, e escolheu doze dentre eles, aos quais deu também o nome de apóstolos:', 1, CURRENT_TIMESTAMP, false),
(42, 6, 14, 'Simão, ao qual também chamou Pedro, e André, seu irmão; Tiago e João; Filipe e Bartolomeu;', 1, CURRENT_TIMESTAMP, false),
(42, 6, 15, 'Mateus e Tomé; Tiago, filho de Alfeu, e Simão, chamado Zelote;', 1, CURRENT_TIMESTAMP, false),
(42, 6, 16, 'Judas, filho de Tiago; e Judas Iscariotes, que veio a ser o traidor.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 17, 'E Jesus, descendo com eles, parou num lugar plano, onde havia não só grande número de seus discípulos, mas também grande multidão do povo, de toda a Judéia e Jerusalém, e do litoral de Tiro e de Sidom, que tinham vindo para ouvi-lo e serem curados das suas doenças;', 1, CURRENT_TIMESTAMP, false),
(42, 6, 18, 'e os que eram atormentados por espíritos imundos ficavam curados.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 19, 'E toda a multidão procurava tocar-lhe; porque saía dele poder que curava a todos.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 20, 'Então, levantando ele os olhos para os seus discípulos, dizia: Bem-aventurados vós, os pobres, porque vosso é o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 21, 'Bem-aventurados vós, que agora tendes fome, porque sereis fartos. Bem-aventurados vós, que agora chorais, porque haveis de rir.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 22, 'Bem-aventurados sereis quando os homens vos odiarem, e quando vos expulsarem da sua companhia, e vos injuriarem, e rejeitarem o vosso nome como indigno, por causa do Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 23, 'Regozijai-vos nesse dia e exultai, porque eis que é grande o vosso galardão no céu; pois assim faziam os seus pais aos profetas.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 24, 'Mas ai de vós que sois ricos! porque já recebestes a vossa consolação.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 25, 'Ai de vós, os que agora estais fartos! porque tereis fome. Ai de vós, os que agora rides! porque vos lamentareis e chorareis.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 26, 'Ai de vós, quando todos os homens vos louvarem! porque assim faziam os seus pais aos falsos profetas.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 27, 'Mas a vós que ouvis, digo: Amai a vossos inimigos, fazei bem aos que vos odeiam,', 1, CURRENT_TIMESTAMP, false),
(42, 6, 28, 'bendizei aos que vos maldizem, e orai pelos que vos caluniam.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 29, 'Ao que te ferir numa face, oferece-lhe também a outra; e ao que te houver tirado a capa, não lhe negues também a túnica.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 30, 'Dá a todo o que te pedir; e ao que tomar o que é teu, não lho reclames.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 31, 'Assim como quereis que os homens vos façam, do mesmo modo lhes fazei vós também.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 32, 'Se amardes aos que vos amam, que mérito há nisso? Pois também os pecadores amam aos que os amam.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 33, 'E se fizerdes bem aos que vos fazem bem, que mérito há nisso? Também os pecadores fazem o mesmo.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 34, 'E se emprestardes àqueles de quem esperais receber, que mérito há nisso? Também os pecadores emprestam aos pecadores, para receberem outro tanto.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 35, 'Amai, porém a vossos inimigos, fazei bem e emprestai, nunca desanimado; e grande será a vossa recompensa, e sereis filhos do Altíssimo; porque ele é benigno até para com os integrantes e maus.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 36, 'Sede misericordiosos, como também vosso Pai é misericordioso.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 37, 'Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; perdoai, e sereis perdoados.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 38, 'Dai, e ser-vos-á dado; boa medida, recalcada, sacudida e transbordando vos deitarão no regaço; porque com a mesma medida com que medis, vos medirão a vós.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 39, 'E propôs-lhes também uma parábola: Pode porventura um cego guiar outro cego? não cairão ambos no barranco?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 40, 'Não é o discípulo mais do que o seu mestre; mas todo o que for bem instruído será como o seu mestre.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 41, 'Por que vês o argueiro no olho de teu irmão, e não reparas na trave que está no teu próprio olho?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 42, 'Ou como podes dizer a teu irmão: Irmão, deixa-me tirar o argueiro que está no teu olho, não vendo tu mesmo a trave que está no teu? Hipócrita! tira primeiro a trave do teu olho; e então verás bem para tirar o argueiro que está no olho de teu irmão.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 43, 'Porque não há árvore boa que dê mau fruto nem tampouco árvore má que dê bom fruto.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 44, 'Porque cada árvore se conhece pelo seu próprio fruto; pois dos espinheiros não se colhem figos, nem dos abrolhos se vindimam uvas.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 45, 'O homem bom, do bom tesouro do seu coração tira o bem; e o homem mau, do seu mau tesouro tira o mal; pois do que há em abundância no coração, disso fala a boca.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 46, 'E por que me chamais: Senhor, Senhor, e não fazeis o que eu vos digo?', 1, CURRENT_TIMESTAMP, false),
(42, 6, 47, 'Todo aquele que vem a mim, e ouve as minhas palavras, e as pratica, eu vos mostrarei a quem é semelhante:', 1, CURRENT_TIMESTAMP, false),
(42, 6, 48, 'É semelhante ao homem que, edificando uma casa, cavou, abriu profunda vala, e pôs os alicerces sobre a rocha; e vindo a enchente, bateu com ímpeto a torrente naquela casa, e não a pôde abalar, porque tinha sido bem edificada.', 1, CURRENT_TIMESTAMP, false),
(42, 6, 49, 'Mas o que ouve e não pratica é semelhante a um homem que edificou uma casa sobre terra, sem alicerces, na qual bateu com ímpeto a torrente, e logo caiu; e foi grande a ruína daquela casa.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 1, 'Quando acabou de proferir todas estas palavras aos ouvidos do povo, entrou em Cafarnaum.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 2, 'E um servo de certo centurião, de quem era muito estimado, estava doente, quase à morte.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 3, 'O centurião, pois, ouvindo falar de Jesus, enviou-lhes uns anciãos dos judeus, a pedir-lhe que viesse curar o seu servo.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 4, 'E chegando eles junto de Jesus, rogavam-lhe com instância, dizendo: É digno de que lhe concedas isto;', 1, CURRENT_TIMESTAMP, false),
(42, 7, 5, 'porque ama à nossa nação, e ele mesmo nos edificou a sinagoga.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 6, 'Ia, pois, Jesus com eles; mas, quando já estava perto da casa, enviou o centurião uns amigos a dizer-lhe: Senhor, não te incomodes; porque não sou digno de que entres debaixo do meu telhado;', 1, CURRENT_TIMESTAMP, false),
(42, 7, 7, 'por isso nem ainda me julguei digno de ir à tua presença; dize, porém, uma palavra, e seja o meu servo curado.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 8, 'Pois também eu sou homem sujeito à autoridade, e tenho soldados às minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 9, 'Jesus, ouvindo isso, admirou-se dele e, voltando-se para a multidão que o seguia, disse: Eu vos afirmo que nem mesmo em Israel encontrei tamanha fé.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 10, 'E voltando para casa os que haviam sido enviados, encontraram o servo com saúde.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 11, 'Pouco depois seguiu ele viagem para uma cidade chamada Naim; e iam com ele seus discípulos e uma grande multidão.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 12, 'Quando chegou perto da porta da cidade, eis que levavam para fora um defunto, filho único de sua mãe, que era viúva; e com ela ia uma grande multidão da cidade.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 13, 'Logo que o Senhor a viu, encheu-se de compaixão por ela, e disse-lhe: Não chores.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 14, 'Então, chegando-se, tocou no esquife e, quando pararam os que o levavam, disse: Moço, a ti te digo: Levanta-te.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 15, 'O que estivera morto sentou-se e começou a falar. Então Jesus o entregou à sua mãe.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 16, 'O medo se apoderou de todos, e glorificavam a Deus, dizendo: Um grande profeta se levantou entre nós; e: Deus visitou o seu povo.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 17, 'E correu a notícia disto por toda a Judéia e por toda a região circunvizinha.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 18, 'Ora, os discípulos de João anunciaram-lhe todas estas coisas.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 19, 'E João, chamando a dois deles, enviou-os ao Senhor para perguntar-lhe: És tu aquele que havia de vir, ou havemos de esperar outro?', 1, CURRENT_TIMESTAMP, false),
(42, 7, 20, 'Quando aqueles homens chegaram junto dele, disseram: João, o Batista, enviou-nos a perguntar-te: És tu aquele que havia de vir, ou havemos de esperar outro?', 1, CURRENT_TIMESTAMP, false),
(42, 7, 21, 'Naquela mesma hora, curou a muitos de doenças, de moléstias e de espíritos malignos; e deu vista a muitos cegos.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 22, 'Então lhes respondeu: Ide, e contai a João o que tens visto e ouvido: os cegos vêem, os coxos andam, os leprosos são purificados, e os surdos ouvem; os mortos são ressuscitados, e aos pobres é anunciado o evangelho.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 23, 'E bem-aventurado aquele que não se escandalizar de mim.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 24, 'E, tendo-se retirado os mensageiros de João, Jesus começou a dizer às multidões a respeito de João: Que saístes a ver no deserto? um caniço agitado pelo vento?', 1, CURRENT_TIMESTAMP, false),
(42, 7, 25, 'Mas que saístes a ver? um homem trajado de vestes luxuosas? Eis que aqueles que trajam roupas preciosas, e vivem em delícias, estão nos paços reais.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 26, 'Mas que saístes a ver? um profeta? Sim, vos digo, e muito mais do que profeta.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 27, 'Este é aquele de quem está escrito: Eis aí envio ante a tua face o meu mensageiro, que há de preparar adiante de ti o teu caminho.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 28, 'Pois eu vos digo que, entre os nascidos de mulher, não há nenhum maior do que João; mas aquele que é o menor no reino de Deus é maior do que ele.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 29, 'E todo o povo que o ouviu, e até os publicanos, reconheceram a justiça de Deus, recebendo o batismo de João.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 30, 'Mas os fariseus e os doutores da lei rejeitaram o conselho de Deus quando a si mesmos, não sendo batizados por ele.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 31, 'A que, pois, compararei os homens desta geração, e a que são semelhantes?', 1, CURRENT_TIMESTAMP, false),
(42, 7, 32, 'São semelhantes aos meninos que, sentados nas praças, gritam uns para os outros: Tocamo-vos flauta, e não dançastes; cantamos lamentações, e não chorastes.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 33, 'Porquanto veio João, o Batista, não comendo pão nem bebendo vinho, e dizeis: Tem demônio;', 1, CURRENT_TIMESTAMP, false),
(42, 7, 34, 'veio o Filho do homem, comendo e bebendo, e dizeis: Eis aí um comilão e bebedor de vinho, amigo de publicanos e pecadores.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 35, 'Mas a sabedoria é justificada por todos os seus filhos.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 36, 'Um dos fariseus convidou-o para comer com ele; e entrando em casa do fariseu, reclinou-se à mesa.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 37, 'E eis que uma mulher pecadora que havia na cidade, quando soube que ele estava à mesa em casa do fariseu, trouxe um vaso de alabastro com bálsamo;', 1, CURRENT_TIMESTAMP, false),
(42, 7, 38, 'e estando por detrás, aos seus pés, chorando, começou a regar-lhe os pés com lágrimas e os enxugava com os cabelos da sua cabeça; e beijava-lhe os pés e ungia-os com o bálsamo.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 39, 'Mas, ao ver isso, o fariseu que o convidara falava consigo, dizendo: Se este homem fosse profeta, saberia quem e de que qualidade é essa mulher que o toca, pois é uma pecadora.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 40, 'E respondendo Jesus, disse-lhe: Simão, tenho uma coisa a dizer-te. Respondeu ele: Dize-a, Mestre.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 41, 'Certo credor tinha dois devedores; um lhe devia quinhentos denários, e outro cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 42, 'Não tendo eles com que pagar, perdoou a ambos. Qual deles, pois, o amará mais?', 1, CURRENT_TIMESTAMP, false),
(42, 7, 43, 'Respondeu Simão: Suponho que é aquele a quem mais perdoou. Replicou-lhe Jesus: Julgaste bem.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 44, 'E, voltando-se para a mulher, disse a Simão: Vês tu esta mulher? Entrei em tua casa, e não me deste água para os pés; mas esta com suas lágrimas os regou e com seus cabelos os enxugou.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 45, 'Não me deste ósculo; ela, porém, desde que entrei, não tem cessado de beijar-me os pés.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 46, 'Não me ungiste a cabeça com óleo; mas esta com bálsamo ungiu-me os pés.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 47, 'Por isso te digo: Perdoados lhe são os pecados, que são muitos; porque ela muito amou; mas aquele a quem pouco se perdoa, pouco ama.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 48, 'E disse a ela: Perdoados são os teus pecados.', 1, CURRENT_TIMESTAMP, false),
(42, 7, 49, 'Mas os que estavam com ele à mesa começaram a dizer entre si: Quem é este que até perdoa pecados?', 1, CURRENT_TIMESTAMP, false),
(42, 7, 50, 'Jesus, porém, disse à mulher: A tua fé te salvou; vai-te em paz.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 1, 'Logo depois disso, andava Jesus de cidade em cidade, e de aldeia em aldeia, pregando e anunciando o evangelho do reino de Deus; e iam com ele os doze,', 1, CURRENT_TIMESTAMP, false),
(42, 8, 2, 'bem como algumas mulheres que haviam sido curadas de espíritos malignos e de enfermidades: Maria, chamada Madalena, da qual tinham saído sete demônios.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 3, 'Joana, mulher de Cuza, procurador de Herodes, Susana, e muitas outras que os serviam com os seus bens.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 4, 'Ora, ajuntando-se uma grande multidão, e vindo ter com ele gente de todas as cidades, disse Jesus por parábola:', 1, CURRENT_TIMESTAMP, false),
(42, 8, 5, 'Saiu o semeador a semear a sua semente. E quando semeava, uma parte da semente caiu à beira do caminho; e foi pisada, e as aves do céu a comeram.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 6, 'Outra caiu sobre pedra; e, nascida, secou-se porque não havia umidade.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 7, 'E outra caiu no meio dos espinhos; e crescendo com ela os espinhos, sufocaram-na.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 8, 'Mas outra caiu em boa terra; e, nascida, produziu fruto, cem por um. Dizendo ele estas coisas, clamava: Quem tem ouvidos para ouvir, ouça.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 9, 'Perguntaram-lhe então seus discípulos o que significava essa parábola.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 10, 'Respondeu ele: A vós é dado conhecer os mistérios do reino de Deus; mas aos outros se fala por parábolas; para que vendo, não vejam, e ouvindo, não entendam.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 11, 'É, pois, esta a parábola: A semente é a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 12, 'Os que estão à beira do caminho são os que ouvem; mas logo vem o Diabo e tira-lhe do coração a palavra, para que não suceda que, crendo, sejam salvos.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 13, 'Os que estão sobre a pedra são os que, ouvindo a palavra, a recebem com alegria; mas estes não têm raiz, apenas crêem por algum tempo, mas na hora da provação se desviam.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 14, 'A parte que caiu entre os espinhos são os que ouviram e, indo seu caminho, são sufocados pelos cuidados, riquezas, e deleites desta vida e não dão fruto com perfeição.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 15, 'Mas a que caiu em boa terra são os que, ouvindo a palavra com coração reto e bom, a retêm e dão fruto com perseverança.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 16, 'Ninguém, pois, acende uma candeia e a cobre com algum vaso, ou a põe debaixo da cama; mas põe-na no velador, para que os que entram vejam a luz.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 17, 'Porque não há coisa encoberta que não haja de manifestar-se, nem coisa secreta que não haja de saber-se e vir à luz.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 18, 'Vede, pois, como ouvis; porque a qualquer que tiver lhe será dado, e a qualquer que não tiver, até o que parece ter lhe será tirado.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 19, 'Vieram, então, ter com ele sua mãe e seus irmãos, e não podiam aproximar-se dele por causa da multidão.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 20, 'Foi-lhe dito: Tua mãe e teus irmãos estão lá fora, e querem ver-te.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 21, 'Ele, porém, lhes respondeu: Minha mãe e meus irmãos são estes que ouvem a palavra de Deus e a observam.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 22, 'Ora, aconteceu certo dia que entrou num barco com seus discípulos, e disse-lhes: Passemos à outra margem do lago. E partiram.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 23, 'Enquanto navegavam, ele adormeceu; e desceu uma tempestade de vento sobre o lago; e o barco se enchia de água, de sorte que perigavam.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 24, 'Chegando-se a ele, o despertaram, dizendo: Mestre, Mestre, estamos perecendo. E ele, levantando-se, repreendeu o vento e a fúria da água; e cessaram, e fez-se bonança.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 25, 'Então lhes perguntou: Onde está a vossa fé? Eles, atemorizados, admiraram-se, dizendo uns aos outros: Quem, pois, é este, que até aos ventos e à água manda, e lhe obedecem?', 1, CURRENT_TIMESTAMP, false),
(42, 8, 26, 'Apontaram à terra dos gerasenos, que está defronte da Galiléia.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 27, 'Logo que saltou em terra, saiu-lhe ao encontro um homem da cidade, possesso de demônios, que havia muito tempo não vestia roupa, nem morava em casa, mas nos sepulcros.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 28, 'Quando ele viu a Jesus, gritou, prostrou-se diante dele, e com grande voz exclamou: Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? Rogo-te que não me atormentes.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 29, 'Porque Jesus ordenara ao espírito imundo que saísse do homem. Pois já havia muito tempo que se apoderara dele; e guardavam-no preso com grilhões e cadeias; mas ele, quebrando as prisões, era impelido pelo demônio para os desertos.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 30, 'Perguntou-lhe Jesus: Qual é o teu nome? Respondeu ele: Legião; porque tinham entrado nele muitos demônios.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 31, 'E rogavam-lhe que não os mandasse para o abismo.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 32, 'Ora, andava ali pastando no monte uma grande manada de porcos; rogaram-lhe, pois que lhes permitisse entrar neles, e lho permitiu.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 33, 'E tendo os demônios saído do homem, entraram nos porcos; e a manada precipitou-se pelo despenhadeiro no lago, e afogou-se.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 34, 'Quando os pastores viram o que acontecera, fugiram, e foram anunciá-lo na cidade e nos campos.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 35, 'Saíram, pois, a ver o que tinha acontecido, e foram ter com Jesus, a cujos pés acharam sentado, vestido e em perfeito juízo, o homem de quem havia saído os demônios; e se atemorizaram.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 36, 'Os que tinham visto aquilo contaram-lhes como fora curado o endemoninhado.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 37, 'Então todo o povo da região dos gerasenos rogou-lhe que se retirasse deles; porque estavam possuídos de grande medo. Pelo que ele entrou no barco, e voltou.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 38, 'Pedia-lhe, porém, o homem de quem haviam saído os demônios que o deixasse estar com ele; mas Jesus o despediu, dizendo:', 1, CURRENT_TIMESTAMP, false),
(42, 8, 39, 'Volta para tua casa, e conta tudo quanto Deus te fez. E ele se retirou, publicando por toda a cidade tudo quanto Jesus lhe fizera.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 40, 'Quando Jesus voltou, a multidão o recebeu; porque todos o estavam esperando.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 41, 'E eis que veio um homem chamado Jairo, que era chefe da sinagoga; e prostrando-se aos pés de Jesus, rogava-lhe que fosse a sua casa;', 1, CURRENT_TIMESTAMP, false),
(42, 8, 42, 'porque tinha uma filha única, de cerca de doze anos, que estava à morte. Enquanto, pois, ele ia, apertavam-no as multidões.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 43, 'E certa mulher, que tinha uma hemorragia havia doze anos {e gastara com os médicos todos os seus haveres} e por ninguém pudera ser curada,', 1, CURRENT_TIMESTAMP, false),
(42, 8, 44, 'chegando-se por detrás, tocou-lhe a orla do manto, e imediatamente cessou a sua hemorragia.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 45, 'Perguntou Jesus: Quem é que me tocou? Como todos negassem, disse-lhe Pedro: Mestre, as multidões te apertam e te oprimem.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 46, 'Mas disse Jesus: Alguém me tocou; pois percebi que de mim saiu poder.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 47, 'Então, vendo a mulher que não passara despercebida, aproximou-se tremendo e, prostrando-se diante dele, declarou-lhe perante todo o povo a causa por que lhe havia tocado, e como fora imediatamente curada.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 48, 'Disse-lhe ele: Filha, a tua fé te salvou; vai-te em paz.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 49, 'Enquanto ainda falava, veio alguém da casa do chefe da sinagoga dizendo: A tua filha já está morta; não incomodes mais o Mestre.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 50, 'Jesus, porém, ouvindo-o, respondeu-lhe: Não temas: crê somente, e será salva.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 51, 'Tendo chegado à casa, a ninguém deixou entrar com ele, senão a Pedro, João, Tiago, e o pai e a mãe da menina.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 52, 'E todos choravam e pranteavam; ele, porém, disse: Não choreis; ela não está morta, mas dorme.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 53, 'E riam-se dele, sabendo que ela estava morta.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 54, 'Então ele, tomando-lhe a mão, exclamou: Menina, levanta-te.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 55, 'E o seu espírito voltou, e ela se levantou imediatamente; e Jesus mandou que lhe desse de comer.', 1, CURRENT_TIMESTAMP, false),
(42, 8, 56, 'E seus pais ficaram maravilhados; e ele mandou-lhes que a ninguém contassem o que havia sucedido.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 1, 'Reunindo os doze, deu-lhes poder e autoridade sobre todos os demônios, e para curarem doenças;', 1, CURRENT_TIMESTAMP, false),
(42, 9, 2, 'e enviou-os a pregar o reino de Deus, e fazer curas,', 1, CURRENT_TIMESTAMP, false),
(42, 9, 3, 'dizendo-lhes: Nada leveis para o caminho, nem bordão, nem alforje, nem pão, nem dinheiro; nem tenhais duas túnicas.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 4, 'Em qualquer casa em que entrardes, nela ficai, e dali partireis.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 5, 'Mas, onde quer que não vos receberem, saindo daquela cidade, sacudi o pó dos vossos pés, em testemunho contra eles.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 6, 'Saindo, pois, os discípulos percorreram as aldeias, anunciando o evangelho e fazendo curas por toda parte.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 7, 'Ora, o tetrarca Herodes soube de tudo o que se passava, e ficou muito perplexo, porque diziam uns: João ressuscitou dos mortos;', 1, CURRENT_TIMESTAMP, false),
(42, 9, 8, 'outros: Elias apareceu; e outros: Um dos antigos profetas se levantou.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 9, 'Herodes, porém, disse: A João eu mandei degolar; quem é, pois, este a respeito de quem ouço tais coisas? E procurava vê-lo.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 10, 'Quando os apóstolos voltaram, contaram-lhe tudo o que havia feito. E ele, levando-os consigo, retirou-se à parte para uma cidade chamada Betsaida.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 11, 'Mas as multidões, percebendo isto, seguiram-no; e ele as recebeu, e falava-lhes do reino de Deus, e sarava os que necessitavam de cura.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 12, 'Ora, quando o dia começava a declinar, aproximando-se os doze, disseram-lhe: Despede a multidão, para que, indo às aldeias e aos sítios em redor, se hospedem, e achem o que comer; porque aqui estamos em lugar deserto.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 13, 'Mas ele lhes disse: Dai-lhes vós de comer. Responderam eles: Não temos senão cinco pães e dois peixes; salvo se nós formos comprar comida para todo este povo.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 14, 'Pois eram cerca de cinco mil homens. Então disse a seus discípulos: Fazei-os reclinar-se em grupos de cerca de cinqüenta cada um.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 15, 'Assim o fizeram, mandando que todos se reclinassem.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 16, 'E tomando Jesus os cinco pães e os dois peixes, e olhando para o céu, os abençoou e partiu, e os entregava aos seus discípulos para os porem diante da multidão.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 17, 'Todos, pois, comeram e se fartaram; e foram levantados, do que lhes sobejou, doze cestos de pedaços.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 18, 'Enquanto ele estava orando à parte achavam-se com ele somente seus discípulos; e perguntou-lhes: Quem dizem as multidões que eu sou?', 1, CURRENT_TIMESTAMP, false),
(42, 9, 19, 'Responderam eles: Uns dizem: João, o Batista; outros: Elias; e ainda outros, que um dos antigos profetas se levantou.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 20, 'Então lhes perguntou: Mas vós, quem dizeis que eu sou? Respondendo Pedro, disse: O Cristo de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 21, 'Jesus, porém, advertindo-os, mandou que não contassem isso a ninguém;', 1, CURRENT_TIMESTAMP, false),
(42, 9, 22, 'e disse-lhes: É necessário que o Filho do homem padeça muitas coisas, que seja rejeitado pelos anciãos, pelos principais sacerdotes e escribas, que seja morto, e que ao terceiro dia ressuscite.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 23, 'Em seguida dizia a todos: Se alguém quer vir após mim, negue-se a si mesmo, tome cada dia a sua cruz, e siga-me.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 24, 'Pois quem quiser salvar a sua vida, perdê-la-á; mas quem perder a sua vida por amor de mim, esse a salvará.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 25, 'Pois, que aproveita ao homem ganhar o mundo inteiro, e perder-se, ou prejudicar-se a si mesmo?', 1, CURRENT_TIMESTAMP, false),
(42, 9, 26, 'Porque, quem se envergonhar de mim e das minhas palavras, dele se envergonhará o Filho do homem, quando vier na sua glória, e na do Pai e dos santos anjos.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 27, 'Mas em verdade vos digo: Alguns há, dos que estão aqui, que de modo nenhum provarão a morte até que vejam o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 28, 'Cerca de oito dias depois de ter proferido essas palavras, tomou Jesus consigo a Pedro, a João e a Tiago, e subiu ao monte para orar.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 29, 'Enquanto ele orava, mudou-se a aparência do seu rosto, e a sua roupa tornou-se branca e resplandecente.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 30, 'E eis que estavam falando com ele dois varões, que eram Moisés e Elias,', 1, CURRENT_TIMESTAMP, false),
(42, 9, 31, 'os quais apareceram com glória, e falavam da sua partida que estava para cumprir-se em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 32, 'Ora, Pedro e os que estavam com ele se haviam deixado vencer pelo sono; despertando, porém, viram a sua glória e os dois varões que estavam com ele.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 33, 'E, quando estes se apartavam dele, disse Pedro a Jesus: Mestre, bom é estarmos nós aqui: façamos, pois, três cabanas, uma para ti, uma para Moisés, e uma para Elias, não sabendo o que dizia.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 34, 'Enquanto ele ainda falava, veio uma nuvem que os cobriu; e se atemorizaram ao entrarem na nuvem.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 35, 'E da nuvem saiu uma voz que dizia: Este é o meu Filho, o meu eleito; a ele ouvi.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 36, 'Ao soar esta voz, Jesus foi achado sozinho; e eles calaram-se, e por aqueles dias não contaram a ninguém nada do que tinham visto.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 37, 'No dia seguinte, quando desceram do monte, veio-lhe ao encontro uma grande multidão.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 38, 'E eis que um homem dentre a multidão clamou, dizendo: Mestre, peço-te que olhes para meu filho, porque é o único que tenho;', 1, CURRENT_TIMESTAMP, false),
(42, 9, 39, 'pois um espírito se apodera dele, fazendo-o gritar subitamente, convulsiona-o até escumar e, mesmo depois de o ter quebrantado, dificilmente o larga.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 40, 'E roguei aos teus discípulos que o expulsassem, mas não puderam.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 41, 'Respondeu Jesus: ó geração incrédula e perversa! até quando estarei convosco e vos sofrerei? Traze-me cá o teu filho.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 42, 'Ainda quando ele vinha chegando, o demônio o derribou e o convulsionou; mas Jesus repreendeu o espírito imundo, curou o menino e o entregou a seu pai.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 43, 'E todos se maravilhavam da majestade de Deus. E admirando-se todos de tudo o que Jesus fazia, disse ele a seus discípulos:', 1, CURRENT_TIMESTAMP, false),
(42, 9, 44, 'Ponde vós estas palavras em vossos ouvidos; pois o Filho do homem está para ser entregue nas mãos dos homens.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 45, 'Eles, porém, não entendiam essa palavra, cujo sentido lhes era encoberto para que não o compreendessem; e temiam interrogá-lo a esse respeito.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 46, 'E suscitou-se entre eles uma discussão sobre qual deles seria o maior.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 47, 'Mas Jesus, percebendo o pensamento de seus corações, tomou uma criança, pô-la junto de si,', 1, CURRENT_TIMESTAMP, false),
(42, 9, 48, 'e disse-lhes: Qualquer que receber esta criança em meu nome, a mim me recebe; e qualquer que me receber a mim, recebe aquele que me enviou; pois aquele que entre vós todos é o menor, esse é grande.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 49, 'Disse-lhe João: Mestre, vimos um homem que em teu nome expulsava demônios; e lho proibimos, porque não segue conosco.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 50, 'Respondeu-lhe Jesus: Não lho proibais; porque quem não é contra vós é por vós.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 51, 'Ora, quando se completavam os dias para a sua assunção, manifestou o firme propósito de ir a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 52, 'Enviou, pois, mensageiros adiante de si. Indo eles, entraram numa aldeia de samaritanos para lhe prepararem pousada.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 53, 'Mas não o receberam, porque viajava em direção a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 54, 'Vendo isto os discípulos Tiago e João, disseram: Senhor, queres que mandemos descer fogo do céu para os consumir {como Elias também fez?}', 1, CURRENT_TIMESTAMP, false),
(42, 9, 55, 'Ele porém, voltando-se, repreendeu-os, {e disse: Vós não sabeis de que espírito sois.}', 1, CURRENT_TIMESTAMP, false),
(42, 9, 56, '{Pois o Filho do Homem não veio para destruir as vidas dos homens, mas para salvá-las.} E foram para outra aldeia.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 57, 'Quando iam pelo caminho, disse-lhe um homem: Seguir-te-ei para onde quer que fores.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 58, 'Respondeu-lhe Jesus: As raposas têm covis, e as aves do céu têm ninhos; mas o Filho do homem não tem onde reclinar a cabeça.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 59, 'E a outro disse: Segue-me. Ao que este respondeu: Permite-me ir primeiro sepultar meu pai.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 60, 'Replicou-lhe Jesus: Deixa os mortos sepultar os seus próprios mortos; tu, porém, vai e anuncia o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 61, 'Disse também outro: Senhor, eu te seguirei, mas deixa-me despedir primeiro dos que estão em minha casa.', 1, CURRENT_TIMESTAMP, false),
(42, 9, 62, 'Jesus, porém, lhe respondeu: Ninguém que lança mão do arado e olha para trás é apto para o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 1, 'Depois disso designou o Senhor outros setenta, e os enviou adiante de si, de dois em dois, a todas as cidades e lugares aonde ele havia de ir.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 2, 'E dizia-lhes: Na verdade, a seara é grande, mas os trabalhadores são poucos; rogai, pois, ao Senhor da seara que mande trabalhadores para a sua seara.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 3, 'Ide; eis que vos envio como cordeiros ao meio de lobos.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 4, 'Não leveis bolsa, nem alforge, nem alparcas; e a ninguém saudeis pelo caminho.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 5, 'Em qualquer casa em que entrardes, dizei primeiro: Paz seja com esta casa.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 6, 'E se ali houver um filho da paz, repousará sobre ele a vossa paz; e se não, voltará para vós.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 7, 'Ficai nessa casa, comendo e bebendo do que eles tiverem; pois digno é o trabalhador do seu salário. Não andeis de casa em casa.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 8, 'Também, em qualquer cidade em que entrardes, e vos receberem, comei do que puserem diante de vós.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 9, 'Curai os enfermos que nela houver, e dizer-lhes: É chegado a vós o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 10, 'Mas em qualquer cidade em que entrardes, e vos não receberem, saindo pelas ruas, dizei:', 1, CURRENT_TIMESTAMP, false),
(42, 10, 11, 'Até o pó da vossa cidade, que se nos pegou aos pés, sacudimos contra vós. Contudo, sabei isto: que o reino de Deus é chegado.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 12, 'Digo-vos que naquele dia haverá menos rigor para Sodoma, do que para aquela cidade.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 13, 'Ai de ti, Corazim! ai de ti, Betsaida! Porque, se em Tiro e em Sidom se tivessem operado os milagres que em vós se operaram, há muito, sentadas em cilício e cinza, elas se teriam arrependido.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 14, 'Contudo, para Tiro e Sidom haverá menos rigor no juízo do que para vós.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 15, 'E tu, Cafarnaum, porventura serás elevada até o céu? até o inferno descerás.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 16, 'Quem vos ouve, a mim me ouve; e quem vos rejeita, a mim me rejeita; e quem a mim me rejeita, rejeita aquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 17, 'Voltaram depois os setenta com alegria, dizendo: Senhor, em teu nome, até os demônios se nos submetem.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 18, 'Respondeu-lhes ele: Eu via Satanás, como raio, cair do céu.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 19, 'Eis que vos dei autoridade para pisar serpentes e escorpiões, e sobre todo o poder do inimigo; e nada vos fará dano algum.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 20, 'Contudo, não vos alegreis porque se vos submetem os espíritos; alegrai-vos antes por estarem os vossos nomes escritos nos céus.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 21, 'Naquela mesma hora exultou Jesus no Espírito Santo, e disse: Graças te dou, ó Pai, Senhor do céu e da terra, porque ocultaste estas coisas aos sábios e entendidos, e as revelaste aos pequeninos; sim, ó Pai, porque assim foi do teu agrado.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 22, 'Todas as coisas me foram entregues por meu Pai; e ninguém conhece quem é o Filho senão o Pai, nem quem é o Pai senão o Filho, e aquele a quem o Filho o quiser revelar.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 23, 'E voltando-se para os discípulos, disse-lhes em particular: Bem-aventurados os olhos que vêem o que vós vedes.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 24, 'Pois vos digo que muitos profetas e reis desejaram ver o que vós vedes, e não o viram; e ouvir o que ouvis, e não o ouviram.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 25, 'E eis que se levantou certo doutor da lei e, para o experimentar, disse: Mestre, que farei para herdar a vida eterna?', 1, CURRENT_TIMESTAMP, false),
(42, 10, 26, 'Perguntou-lhe Jesus: Que está escrito na lei? Como lês tu?', 1, CURRENT_TIMESTAMP, false),
(42, 10, 27, 'Respondeu-lhe ele: Amarás ao Senhor teu Deus de todo o teu coração, de toda a tua alma, de todas as tuas forças e de todo o teu entendimento, e ao teu próximo como a ti mesmo.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 28, 'Tornou-lhe Jesus: Respondeste bem; faze isso, e viverás.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 29, 'Ele, porém, querendo justificar-se, perguntou a Jesus: E quem é o meu próximo?', 1, CURRENT_TIMESTAMP, false),
(42, 10, 30, 'Jesus, prosseguindo, disse: Um homem descia de Jerusalém a Jericó, e caiu nas mãos de salteadores, os quais o despojaram e espancando-o, se retiraram, deixando-o meio morto.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 31, 'Casualmente, descia pelo mesmo caminho certo sacerdote; e vendo-o, passou de largo.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 32, 'De igual modo também um levita chegou àquele lugar, viu-o, e passou de largo.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 33, 'Mas um samaritano, que ia de viagem, chegou perto dele e, vendo-o, encheu-se de compaixão;', 1, CURRENT_TIMESTAMP, false),
(42, 10, 34, 'e aproximando-se, atou-lhe as feridas, deitando nelas azeite e vinho; e pondo-o sobre a sua cavalgadura, levou-o para uma estalagem e cuidou dele.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 35, 'No dia seguinte tirou dois denários, deu-os ao hospedeiro e disse-lhe: Cuida dele; e tudo o que gastares a mais, eu to pagarei quando voltar.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 36, 'Qual, pois, destes três te parece ter sido o próximo daquele que caiu nas mãos dos salteadores?', 1, CURRENT_TIMESTAMP, false),
(42, 10, 37, 'Respondeu o doutor da lei: Aquele que usou de misericórdia para com ele. Disse-lhe, pois, Jesus: Vai, e faze tu o mesmo.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 38, 'Ora, quando iam de caminho, entrou Jesus numa aldeia; e certa mulher, por nome Marta, o recebeu em sua casa.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 39, 'Tinha esta uma irmã chamada Maria, a qual, sentando-se aos pés do Senhor, ouvia a sua palavra.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 40, 'Marta, porém, andava preocupada com muito serviço; e aproximando-se, disse: Senhor, não se te dá que minha irmã me tenha deixado a servir sozinha? Dize-lhe, pois, que me ajude.', 1, CURRENT_TIMESTAMP, false),
(42, 10, 41, 'Respondeu-lhe o Senhor: Marta, Marta, estás ansiosa e perturbada com muitas coisas;', 1, CURRENT_TIMESTAMP, false),
(42, 10, 42, 'entretanto poucas são necessárias, ou mesmo uma só; e Maria escolheu a boa parte, a qual não lhe será tirada.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 1, 'Estava Jesus em certo lugar orando e, quando acabou, disse-lhe um dos seus discípulos: Senhor, ensina-nos a orar, como também João ensinou aos seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 2, 'Ao que ele lhes disse: Quando orardes, dizei: Pai, santificado seja o teu nome; venha o teu reino;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 3, 'dá-nos cada dia o nosso pão cotidiano;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 4, 'e perdoa-nos os nossos pecados, pois também nós perdoamos a todo aquele que nos deve; e não nos deixes entrar em tentação, {mas livra-nos do mal.}', 1, CURRENT_TIMESTAMP, false),
(42, 11, 5, 'Disse-lhes também: Se um de vós tiver um amigo, e se for procurá-lo à meia-noite e lhe disser: Amigo, empresta-me três pães,', 1, CURRENT_TIMESTAMP, false),
(42, 11, 6, 'pois que um amigo meu, estando em viagem, chegou a minha casa, e não tenho o que lhe oferecer;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 7, 'e se ele, de dentro, responder: Não me incomodes; já está a porta fechada, e os meus filhos estão comigo na cama; não posso levantar-me para te atender;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 8, 'digo-vos que, ainda que se levante para lhos dar por ser seu amigo, todavia, por causa da sua importunação, se levantará e lhe dará quantos pães ele precisar.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 9, 'Pelo que eu vos digo: Pedi, e dar-se-vos-á; buscai e achareis; batei, e abrir-se-vos-á;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 10, 'pois todo o que pede, recebe; e quem busca acha; e ao que bate, abrir-se-lhe-á.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 11, 'E qual o pai dentre vós que, se o filho lhe pedir pão, lhe dará uma pedra? Ou, se lhe pedir peixe, lhe dará por peixe uma serpente?', 1, CURRENT_TIMESTAMP, false),
(42, 11, 12, 'Ou, se pedir um ovo, lhe dará um escorpião?', 1, CURRENT_TIMESTAMP, false),
(42, 11, 13, 'Se vós, pois, sendo maus, sabeis dar boas dádivas aos vossos filhos, quanto mais dará o Pai celestial o Espírito Santo àqueles que lho pedirem?', 1, CURRENT_TIMESTAMP, false),
(42, 11, 14, 'Estava Jesus expulsando um demônio, que era mudo; e aconteceu que, saindo o demônio, o mudo falou; e as multidões se admiraram.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 15, 'Mas alguns deles disseram: É por Belzebu, o príncipe dos demônios, que ele expulsa os demônios.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 16, 'E outros, experimentando-o, lhe pediam um sinal do céu.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 17, 'Ele, porém, conhecendo-lhes os pensamentos, disse-lhes: Todo reino dividido contra si mesmo será assolado, e casa sobre casa cairá.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 18, 'Ora, pois, se Satanás está dividido contra si mesmo, como subsistirá o seu reino? Pois dizeis que eu expulso dos demônios por Belzebu.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 19, 'E, se eu expulso os demônios por Belzebu, por quem os expulsam os vossos filhos? Por isso eles mesmos serão os vossos juizes.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 20, 'Mas, se é pelo dedo de Deus que eu expulso os demônios, logo é chegado a vós o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 21, 'Quando o valente guarda, armado, a sua casa, em segurança estão os seus bens;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 22, 'mas, sobrevindo outro mais valente do que ele, e vencendo-o, tira-lhe toda a armadura em que confiava, e reparte os seus despojos.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 23, 'Quem não é comigo, é contra mim; e quem comigo não ajunta, espalha.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 24, 'Ora, havendo o espírito imundo saindo do homem, anda por lugares áridos, buscando repouso; e não o encontrando, diz: Voltarei para minha casa, donde saí.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 25, 'E chegando, acha-a varrida e adornada.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 26, 'Então vai, e leva consigo outros sete espíritos piores do que ele e, entrando, habitam ali; e o último estado desse homem vem a ser pior do que o primeiro.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 27, 'Ora, enquanto ele dizia estas coisas, certa mulher dentre a multidão levantou a voz e lhe disse: Bem-aventurado o ventre que te trouxe e os peitos em que te amamentaste.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 28, 'Mas ele respondeu: Antes bem-aventurados os que ouvem a palavra de Deus, e a observam.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 29, 'Como afluíssem as multidões, começou ele a dizer: Geração perversa é esta; ela pede um sinal; e nenhum sinal se lhe dará, senão o de Jonas;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 30, 'porquanto, assim como Jonas foi sinal para os ninivitas, também o Filho do homem o será para esta geração.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 31, 'A rainha do sul se levantará no juízo com os homens desta geração, e os condenará; porque veio dos confins da terra para ouvir a sabedoria de Salomão; e eis, aqui quem é maior do que Salomão.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 32, 'Os homens de Nínive se levantarão no juízo com esta geração, e a condenarão; porque se arrependeram com a pregação de Jonas; e eis aqui quem é maior do que Jonas.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 33, 'Ninguém, depois de acender uma candeia, a põe em lugar oculto, nem debaixo do alqueire, mas no velador, para que os que entram vejam a luz.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 34, 'A candeia do corpo são os olhos. Quando, pois, os teus olhos forem bons, todo o teu corpo será luminoso; mas, quando forem maus, o teu corpo será tenebroso.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 35, 'Vê, então, que a luz que há em ti não sejam trevas.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 36, 'Se, pois, todo o teu corpo estiver iluminado, sem ter parte alguma em trevas, será inteiramente luminoso, como quando a candeia te alumia com o seu resplendor.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 37, 'Acabando Jesus de falar, um fariseu o convidou para almoçar com ele; e havendo Jesus entrado, reclinou-se à mesa.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 38, 'O fariseu admirou-se, vendo que ele não se lavara antes de almoçar.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 39, 'Ao que o Senhor lhe disse: Ora vós, os fariseus, limpais o exterior do corpo e do prato; mas o vosso interior do copo e do prato; mas o vosso interior está cheio de rapina e maldade.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 40, 'Loucos! quem fez o exterior, não fez também o inferior?', 1, CURRENT_TIMESTAMP, false),
(42, 11, 41, 'Dai, porém, de esmola o que está dentro do copo e do prato, e eis que todas as coisas vos serão limpas.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 42, 'Mas ai de vós, fariseus! porque dais o dízimo da hortelã, e da arruda, e de toda hortaliça, e desprezais a justiça e o amor de Deus. Ora, estas coisas importava fazer, sem deixar aquelas.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 43, 'Ai de vós, fariseus! porque gostais dos primeiros assentos nas sinagogas, e das saudações nas praças.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 44, 'Ai de vós! porque sois como as sepulturas que não aparecem, sobre as quais andam os homens sem o saberem.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 45, 'Disse-lhe, então, um dos doutores da lei: Mestre, quando dizes isso, também nos afrontas a nós.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 46, 'Ele, porém, respondeu: Ai de vós também, doutores da lei! porque carregais os homens com fardos difíceis de suportar, e vós mesmos nem ainda com um dos vossos dedos tocais nesses fardos.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 47, 'Ai de vós! porque edificais os túmulos dos profetas, e vossos pais os mataram.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 48, 'Assim sois testemunhas e aprovais as obras de vossos pais; porquanto eles os mataram, e vós lhes edificais os túmulos.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 49, 'Por isso diz também a sabedoria de Deus: Profetas e apóstolos lhes mandarei; e eles matarão uns, e perseguirão outros;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 50, 'para que a esta geração se peçam contas do sangue de todos os profetas que, desde a fundação do mundo, foi derramado;', 1, CURRENT_TIMESTAMP, false),
(42, 11, 51, 'desde o sangue de Abel, até o sangue de Zacarias, que foi morto entre o altar e o santuário; sim, eu vos digo, a esta geração se pedirão contas.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 52, 'Ai de vós, doutores da lei! porque tirastes a chave da ciência; vós mesmos não entrastes, e impedistes aos que entravam.', 1, CURRENT_TIMESTAMP, false),
(42, 11, 53, 'Ao sair ele dali, começaram os escribas e os fariseus a apertá-lo fortemente, e a interrogá-lo acerca de muitas coisas,', 1, CURRENT_TIMESTAMP, false),
(42, 11, 54, 'armando-lhe ciladas, a fim de o apanharem em alguma coisa que dissesse.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 1, 'Ajuntando-se entretanto muitos milhares de pessoas, de sorte que se atropelavam uns aos outros, começou Jesus a dizer primeiro aos seus discípulos: Acautelai-vos do fermento dos fariseus, que é a hipocrisia.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 2, 'Mas nada há encoberto, que não haja de ser descoberto; nem oculto, que não haja de ser conhecido.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 3, 'Porquanto tudo o que em trevas dissestes, à luz será ouvido; e o que falaste ao ouvido no gabinete, dos eirados será apregoado.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 4, 'Digo-vos, amigos meus: Não temais os que matam o corpo, e depois disso nada mais podem fazer.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 5, 'Mas eu vos mostrarei a quem é que deveis temer; temei aquele que, depois de matar, tem poder para lançar no inferno; sim, digo, a esse temei.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 6, 'Não se vendem cinco passarinhos por dois asses? E nenhum deles está esquecido diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 7, 'Mas até os cabelos da vossa cabeça estão todos contados. Não temais, pois mais valeis vós do que muitos passarinhos.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 8, 'E digo-vos que todo aquele que me confessar diante dos homens, também o Filho do homem o confessará diante dos anjos de Deus;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 9, 'mas quem me negar diante dos homens, será negado diante dos anjos de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 10, 'E a todo aquele que proferir uma palavra contra o Filho do homem, isso lhe será perdoado; mas ao que blasfemar contra o Espírito Santo, não lhe será perdoado.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 11, 'Quando, pois, vos levarem às sinagogas, aos magistrados e às autoridades, não estejais solícitos de como ou do que haveis de responder, nem do que haveis de dizer.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 12, 'Porque o Espírito Santo vos ensinará na mesma hora o que deveis dizer.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 13, 'Disse-lhe alguém dentre a multidão: Mestre, dize a meu irmão que reparte comigo a herança.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 14, 'Mas ele lhe respondeu: Homem, quem me constituiu a mim juiz ou repartidor entre vós?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 15, 'E disse ao povo: Acautelai-vos e guardai-vos de toda espécie de cobiça; porque a vida do homem não consiste na abundância das coisas que possui.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 16, 'Propôs-lhes então uma parábola, dizendo: O campo de um homem rico produzira com abundância;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 17, 'e ele arrazoava consigo, dizendo: Que farei? Pois não tenho onde recolher os meus frutos.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 18, 'Disse então: Farei isto: derribarei os meus celeiros e edificarei outros maiores, e ali recolherei todos os meus cereais e os meus bens;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 19, 'e direi à minha alma: Alma, tens em depósito muitos bens para muitos anos; descansa, come, bebe, regala-te.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 20, 'Mas Deus lhe disse: Insensato, esta noite te pedirão a tua alma; e o que tens preparado, para quem será?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 21, 'Assim é aquele que para si ajunta tesouros, e não é rico para com Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 22, 'E disse aos seus discípulos: Por isso vos digo: Não estejais ansiosos quanto à vossa vida, pelo que haveis de comer, nem quanto ao corpo, pelo que haveis de vestir.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 23, 'Pois a vida é mais do que o alimento, e o corpo mais do que o vestuário.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 24, 'Considerai os corvos, que não semeiam nem ceifam; não têm despensa nem celeiro; contudo, Deus os alimenta. Quanto mais não valeis vós do que as aves!', 1, CURRENT_TIMESTAMP, false),
(42, 12, 25, 'Ora, qual de vós, por mais ansioso que esteja, pode acrescentar um côvado à sua estatura?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 26, 'Porquanto, se não podeis fazer nem as coisas mínimas, por que estais ansiosos pelas outras?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 27, 'Considerai os lírios, como crescem; não trabalham, nem fiam; contudo vos digo que nem mesmo Salomão, em toda a sua glória, se vestiu como um deles.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 28, 'Se, pois, Deus assim veste a erva que hoje está no campo e amanhã é lançada no forno, quanto mais vós, homens de pouca fé?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 29, 'Não procureis, pois, o que haveis de comer, ou o que haveis de beber, e não andeis preocupados.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 30, 'Porque a todas estas coisas os povos do mundo procuram; mas vosso Pai sabe que precisais delas.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 31, 'Buscai antes o seu reino, e estas coisas vos serão acrescentadas.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 32, 'Não temas, ó pequeno rebanho! porque a vosso Pai agradou dar-vos o reino.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 33, 'Vendei o que possuís, e dai esmolas. Fazei para vós bolsas que não envelheçam; tesouro nos céus que jamais acabe, aonde não chega ladrão e a traça não rói.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 34, 'Porque, onde estiver o vosso tesouro, aí estará também o vosso coração.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 35, 'Estejam cingidos os vossos lombos e acesas as vossas candeias;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 36, 'e sede semelhantes a homens que esperam o seu senhor, quando houver de voltar das bodas, para que, quando vier e bater, logo possam abrir-lhe.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 37, 'Bem-aventurados aqueles servos, aos quais o senhor, quando vier, achar vigiando! Em verdade vos digo que se cingirá, e os fará reclinar-se à mesa e, chegando-se, os servirá.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 38, 'Quer venha na segunda vigília, quer na terceira, bem-aventurados serão eles, se assim os achar.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 39, 'Sabei, porém, isto: se o dono da casa soubesse a que hora havia de vir o ladrão, vigiaria e não deixaria minar a sua casa.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 40, 'Estai vós também apercebidos; porque, numa hora em que não penseis, virá o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 41, 'Então Pedro perguntou: Senhor, dizes essa parábola a nós, ou também a todos?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 42, 'Respondeu o Senhor: Qual é, pois, o mordomo fiel e prudente, que o Senhor porá sobre os seus servos, para lhes dar a tempo a ração?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 43, 'Bem-aventurado aquele servo a quem o seu senhor, quando vier, achar fazendo assim.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 44, 'Em verdade vos digo que o porá sobre todos os seus bens.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 45, 'Mas, se aquele servo disser em teu coração: O meu senhor tarda em vir; e começar a espancar os criados e as criadas, e a comer, a beber e a embriagar-se,', 1, CURRENT_TIMESTAMP, false),
(42, 12, 46, 'virá o senhor desse servo num dia em que não o espera, e numa hora de que não sabe, e cortá-lo-á pelo meio, e lhe dará a sua parte com os infiéis.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 47, 'O servo que soube a vontade do seu senhor, e não se aprontou, nem fez conforme a sua vontade, será castigado com muitos açoites;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 48, 'mas o que não a soube, e fez coisas que mereciam castigo, com poucos açoites será castigado. Daquele a quem muito é dado, muito se lhe requererá; e a quem muito é confiado, mais ainda se lhe pedirá.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 49, 'Vim lançar fogo à terra; e que mais quero, se já está aceso?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 50, 'Há um batismo em que hei de ser batizado; e como me angustio até que venha a cumprir-se!', 1, CURRENT_TIMESTAMP, false),
(42, 12, 51, 'Cuidais vós que vim trazer paz à terra? Não, eu vos digo, mas antes dissensão:', 1, CURRENT_TIMESTAMP, false),
(42, 12, 52, 'pois daqui em diante estarão cinco pessoas numa casa divididas, três contra duas, e duas contra três;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 53, 'estarão divididos: pai contra filho, e filho contra pai; mãe contra filha, e filha contra mãe; sogra contra nora, e nora contra sogra.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 54, 'Dizia também às multidões: Quando vedes subir uma nuvem do ocidente, logo dizeis: Lá vem chuva; e assim sucede;', 1, CURRENT_TIMESTAMP, false),
(42, 12, 55, 'e quando vedes soprar o vento sul dizeis; Haverá calor; e assim sucede.', 1, CURRENT_TIMESTAMP, false),
(42, 12, 56, 'Hipócritas, sabeis discernir a face da terra e do céu; como não sabeis então discernir este tempo?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 57, 'E por que não julgais também por vós mesmos o que é justo?', 1, CURRENT_TIMESTAMP, false),
(42, 12, 58, 'Quando, pois, vais com o teu adversário ao magistrado, procura fazer as pazes com ele no caminho; para que não suceda que ele te arraste ao juiz, e o juiz te entregue ao meirinho, e o meirinho te lance na prisão', 1, CURRENT_TIMESTAMP, false),
(42, 12, 59, 'Digo-te que não sairás dali enquanto não pagares o derradeiro lepto.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 1, 'Ora, naquele mesmo tempo estavam presentes alguns que lhe falavam dos galileus cujo sangue Pilatos misturara com os sacrifícios deles.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 2, 'Respondeu-lhes Jesus: Pensais vós que esses foram maiores pecadores do que todos os galileus, por terem padecido tais coisas?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 3, 'Não, eu vos digo; antes, se não vos arrependerdes, todos de igual modo perecereis.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 4, 'Ou pensais que aqueles dezoito, sobre os quais caiu a torre de Siloé e os matou, foram mais culpados do que todos os outros habitantes de Jerusalém?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 5, 'Não, eu vos digo; antes, se não vos arrependerdes, todos de igual modo perecereis.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 6, 'E passou a narrar esta parábola: Certo homem tinha uma figueira plantada na sua vinha; e indo procurar fruto nela, e não o achou.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 7, 'Disse então ao viticultor: Eis que há três anos venho procurar fruto nesta figueira, e não o acho; corta-a; para que ocupa ela ainda a terra inutilmente?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 8, 'Respondeu-lhe ele: Senhor, deixa-a este ano ainda, até que eu cave em derredor, e lhe deite estrume;', 1, CURRENT_TIMESTAMP, false),
(42, 13, 9, 'e se no futuro der fruto, bem; mas, se não, cortá-la-ás.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 10, 'Jesus estava ensinando numa das sinagogas no sábado.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 11, 'E estava ali uma mulher que tinha um espírito de enfermidade havia já dezoito anos; e andava encurvada, e não podia de modo algum endireitar-se.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 12, 'Vendo-a Jesus, chamou-a, e disse-lhe: Mulher, estás livre da tua enfermidade;', 1, CURRENT_TIMESTAMP, false),
(42, 13, 13, 'e impôs-lhe as mãos e imediatamente ela se endireitou, e glorificava a Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 14, 'Então o chefe da sinagoga, indignado porque Jesus curara no sábado, tomando a palavra disse à multidão: Seis dias há em que se deve trabalhar; vinde, pois, neles para serdes curados, e não no dia de sábado.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 15, 'Respondeu-lhe, porém, o Senhor: Hipócritas, no sábado não desprende da manjedoura cada um de vós o seu boi, ou jumento, para o levar a beber?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 16, 'E não devia ser solta desta prisão, no dia de sábado, esta que é filha de Abraão, a qual há dezoito anos Satanás tinha presa?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 17, 'E dizendo ele essas coisas, todos os seus adversário ficavam envergonhados; e todo o povo se alegrava por todas as coisas gloriosas que eram feitas por ele.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 18, 'Ele, pois, dizia: A que é semelhante o reino de Deus, e a que o compararei?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 19, 'É semelhante a um grão de mostarda que um homem tomou e lançou na sua horta; cresceu, e fez-se árvore, e em seus ramos se aninharam as aves do céu.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 20, 'E disse outra vez: A que compararei o reino de Deus?', 1, CURRENT_TIMESTAMP, false),
(42, 13, 21, 'É semelhante ao fermento que uma mulher tomou e misturou com três medidas de farinha, até ficar toda ela levedada.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 22, 'Assim percorria Jesus as cidades e as aldeias, ensinando, e caminhando para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 23, 'E alguém lhe perguntou: Senhor, são poucos os que se salvam? Ao que ele lhes respondeu:', 1, CURRENT_TIMESTAMP, false),
(42, 13, 24, 'Porfiai por entrar pela porta estreita; porque eu vos digo que muitos procurarão entrar, e não poderão.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 25, 'Quando o dono da casa se tiver levantado e cerrado a porta, e vós começardes, de fora, a bater à porta, dizendo: Senhor, abre-nos; e ele vos responder: Não sei donde vós sois;', 1, CURRENT_TIMESTAMP, false),
(42, 13, 26, 'então começareis a dizer: Comemos e bebemos na tua presença, e tu ensinaste nas nossas ruas;', 1, CURRENT_TIMESTAMP, false),
(42, 13, 27, 'e ele vos responderá: Não sei donde sois; apartai-vos de mim, vós todos os que praticais a iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 28, 'Ali haverá choro e ranger de dentes quando virdes Abraão, Isaque, Jacó e todos os profetas no reino de Deus, e vós lançados fora.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 29, 'Muitos virão do oriente e do ocidente, do norte e do sul, e reclinar-se-ão à mesa no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 30, 'Pois há últimos que serão primeiros, e primeiros que serão últimos.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 31, 'Naquela mesma hora chegaram alguns fariseus que lhe disseram: Sai, e retira-te daqui, porque Herodes quer matar-te.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 32, 'Respondeu-lhes Jesus: Ide e dizei a essa raposa: Eis que vou expulsando demônios e fazendo curas, hoje e amanhã, e no terceiro dia serei consumado.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 33, 'Importa, contudo, caminhar hoje, amanhã, e no dia seguinte; porque não convém que morra um profeta fora de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 13, 34, 'Jerusalém, Jerusalém, que matas os profetas, e apedrejas os que a ti são enviados! Quantas vezes quis eu ajuntar os teus filhos, como a galinha ajunta a sua ninhada debaixo das asas, e não quiseste!', 1, CURRENT_TIMESTAMP, false),
(42, 13, 35, 'Eis aí, abandonada vos é a vossa casa. E eu vos digo que não me vereis até que venha o tempo em que digais: Bendito aquele que vem em nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 1, 'Tendo Jesus entrado, num sábado, em casa de um dos chefes dos fariseus para comer pão, eles o estavam observando.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 2, 'Achava-se ali diante dele certo homem hidrópico.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 3, 'E Jesus, tomando a palavra, falou aos doutores da lei e aos fariseus, e perguntou: É lícito curar no sábado, ou não?', 1, CURRENT_TIMESTAMP, false),
(42, 14, 4, 'Eles, porém, ficaram calados. E Jesus, pegando no homem, o curou, e o despediu.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 5, 'Então lhes perguntou: Qual de vós, se lhe cair num poço um filho, ou um boi, não o tirará logo, mesmo em dia de sábado?', 1, CURRENT_TIMESTAMP, false),
(42, 14, 6, 'A isto nada puderam responder.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 7, 'Ao notar como os convidados escolhiam os primeiros lugares, propôs-lhes esta parábola:', 1, CURRENT_TIMESTAMP, false),
(42, 14, 8, 'Quando por alguém fores convidado às bodas, não te reclines no primeiro lugar; não aconteça que esteja convidado outro mais digno do que tu;', 1, CURRENT_TIMESTAMP, false),
(42, 14, 9, 'e vindo o que te convidou a ti e a ele, te diga: Dá o lugar a este; e então, com vergonha, tenhas de tomar o último lugar.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 10, 'Mas, quando fores convidado, vai e reclina-te no último lugar, para que, quando vier o que te convidou, te diga: Amigo, sobe mais para cima. Então terás honra diante de todos os que estiverem contigo à mesa.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 11, 'Porque todo o que a si mesmo se exaltar será humilhado, e aquele que a si mesmo se humilhar será exaltado.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 12, 'Disse também ao que o havia convidado: Quando deres um jantar, ou uma ceia, não convides teus amigos, nem teus irmãos, nem teus parentes, nem os vizinhos ricos, para que não suceda que também eles te tornem a convidar, e te seja isso retribuído.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 13, 'Mas quando deres um banquete, convida os pobres, os aleijados, os mancos e os cegos;', 1, CURRENT_TIMESTAMP, false),
(42, 14, 14, 'e serás bem-aventurado; porque eles não têm com que te retribuir; pois retribuído te será na ressurreição dos justos.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 15, 'Ao ouvir isso um dos que estavam com ele à mesa, disse-lhe: Bem-aventurado aquele que comer pão no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 16, 'Jesus, porém, lhe disse: Certo homem dava uma grande ceia, e convidou a muitos.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 17, 'E à hora da ceia mandou o seu servo dizer aos convidados: vinde, porque tudo já está preparado.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 18, 'Mas todos à uma começaram a escusar-se. Disse-lhe o primeiro: Comprei um campo, e preciso ir vê-lo; rogo-te que me dês por escusado.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 19, 'Outro disse: Comprei cinco juntas de bois, e vou experimentá-los; rogo-te que me dês por escusado.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 20, 'Ainda outro disse: Casei-me e portanto não posso ir.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 21, 'Voltou o servo e contou tudo isto a seu senhor: Então o dono da casa, indignado, disse a seu servo: Sai depressa para as ruas e becos da cidade e traze aqui os pobres, os aleijados, os cegos e os coxos.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 22, 'Depois disse o servo: Senhor, feito está como o ordenaste, e ainda há lugar.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 23, 'Respondeu o senhor ao servo: Sai pelos caminhos e valados, e obriga-os a entrar, para que a minha casa se encha.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 24, 'Pois eu vos digo que nenhum daqueles homens que foram convidados provará a minha ceia.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 25, 'Ora, iam com ele grandes multidões; e, voltando-se, disse-lhes:', 1, CURRENT_TIMESTAMP, false),
(42, 14, 26, 'Se alguém vier a mim, e não aborrecer a pai e mãe, a mulher e filhos, a irmãos e irmãs, e ainda também à própria vida, não pode ser meu discípulo.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 27, 'Quem não leva a sua cruz e não me segue, não pode ser meu discípulo.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 28, 'Pois qual de vós, querendo edificar uma torre, não se senta primeiro a calcular as despesas, para ver se tem com que a acabar?', 1, CURRENT_TIMESTAMP, false),
(42, 14, 29, 'Para não acontecer que, depois de haver posto os alicerces, e não a podendo acabar, todos os que a virem comecem a zombar dele,', 1, CURRENT_TIMESTAMP, false),
(42, 14, 30, 'dizendo: Este homem começou a edificar e não pode acabar.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 31, 'Ou qual é o rei que, indo entrar em guerra contra outro rei, não se senta primeiro a consultar se com dez mil pode sair ao encontro do que vem contra ele com vinte mil?', 1, CURRENT_TIMESTAMP, false),
(42, 14, 32, 'No caso contrário, enquanto o outro ainda está longe, manda embaixadores, e pede condições de paz.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 33, 'Assim, pois, todo aquele dentre vós que não renuncia a tudo quanto possui, não pode ser meu discípulo.', 1, CURRENT_TIMESTAMP, false),
(42, 14, 34, 'Bom é o sal; mas se o sal se tornar insípido, com que se há de restaurar-lhe o sabor?', 1, CURRENT_TIMESTAMP, false),
(42, 14, 35, 'Não presta nem para terra, nem para adubo; lançam-no fora. Quem tem ouvidos para ouvir, ouça.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 1, 'Ora, chegavam-se a ele todos os publicanos e pecadores para o ouvir.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 2, 'E os fariseus e os escribas murmuravam, dizendo: Este recebe pecadores, e come com eles.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 3, 'Então ele lhes propôs esta parábola:', 1, CURRENT_TIMESTAMP, false),
(42, 15, 4, 'Qual de vós é o homem que, possuindo cem ovelhas, e perdendo uma delas, não deixa as noventa e nove no deserto, e não vai após a perdida até que a encontre?', 1, CURRENT_TIMESTAMP, false),
(42, 15, 5, 'E achando-a, põe-na sobre os ombros, cheio de júbilo;', 1, CURRENT_TIMESTAMP, false),
(42, 15, 6, 'e chegando a casa, reúne os amigos e vizinhos e lhes diz: Alegrai-vos comigo, porque achei a minha ovelha que se havia perdido.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 7, 'Digo-vos que assim haverá maior alegria no céu por um pecador que se arrepende, do que por noventa e nove justos que não necessitam de arrependimento.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 8, 'Ou qual é a mulher que, tendo dez dracmas e perdendo uma dracma, não acende a candeia, e não varre a casa, buscando com diligência até encontrá-la?', 1, CURRENT_TIMESTAMP, false),
(42, 15, 9, 'E achando-a, reúne as amigas e vizinhas, dizendo: Alegrai-vos comigo, porque achei a dracma que eu havia perdido.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 10, 'Assim, digo-vos, há alegria na presença dos anjos de Deus por um só pecador que se arrepende.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 11, 'Disse-lhe mais: Certo homem tinha dois filhos.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 12, 'O mais moço deles disse ao pai: Pai, dá-me a parte dos bens que me toca. Repartiu-lhes, pois, os seus haveres.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 13, 'Poucos dias depois, o filho mais moço ajuntando tudo, partiu para um país distante, e ali desperdiçou os seus bens, vivendo dissolutamente.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 14, 'E, havendo ele dissipado tudo, houve naquela terra uma grande fome, e começou a passar necessidades.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 15, 'Então foi encontrar-se a um dos cidadãos daquele país, o qual o mandou para os seus campos a apascentar porcos.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 16, 'E desejava encher o estômago com as alfarrobas que os porcos comiam; e ninguém lhe dava nada.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 17, 'Caindo, porém, em si, disse: Quantos empregados de meu pai têm abundância de pão, e eu aqui pereço de fome!', 1, CURRENT_TIMESTAMP, false),
(42, 15, 18, 'Levantar-me-ei, irei ter com meu pai e dir-lhe-ei: Pai, pequei contra o céu e diante de ti;', 1, CURRENT_TIMESTAMP, false),
(42, 15, 19, 'já não sou digno de ser chamado teu filho; trata-me como um dos teus empregados.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 20, 'Levantou-se, pois, e foi para seu pai. Estando ele ainda longe, seu pai o viu, encheu-se de compaixão e, correndo, lançou-se-lhe ao pescoço e o beijou.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 21, 'Disse-lhe o filho: Pai, pequei conta o céu e diante de ti; já não sou digno de ser chamado teu filho.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 22, 'Mas o pai disse aos seus servos: Trazei depressa a melhor roupa, e vesti-lha, e ponde-lhe um anel no dedo e alparcas nos pés;', 1, CURRENT_TIMESTAMP, false),
(42, 15, 23, 'trazei também o bezerro, cevado e matai-o; comamos, e regozijemo-nos,', 1, CURRENT_TIMESTAMP, false),
(42, 15, 24, 'porque este meu filho estava morto, e reviveu; tinha-se perdido, e foi achado. E começaram a regozijar-se.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 25, 'Ora, o seu filho mais velho estava no campo; e quando voltava, ao aproximar-se de casa, ouviu a música e as danças;', 1, CURRENT_TIMESTAMP, false),
(42, 15, 26, 'e chegando um dos servos, perguntou-lhe que era aquilo.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 27, 'Respondeu-lhe este: Chegou teu irmão; e teu pai matou o bezerro cevado, porque o recebeu são e salvo.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 28, 'Mas ele se indignou e não queria entrar. Saiu então o pai e instava com ele.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 29, 'Ele, porém, respondeu ao pai: Eis que há tantos anos te sirvo, e nunca transgredi um mandamento teu; contudo nunca me deste um cabrito para eu me regozijar com meus amigos;', 1, CURRENT_TIMESTAMP, false),
(42, 15, 30, 'vindo, porém, este teu filho, que desperdiçou os teus bens com as meretrizes, mataste-lhe o bezerro cevado.', 1, CURRENT_TIMESTAMP, false),
(42, 15, 31, 'Replicou-lhe o pai: Filho, tu sempre estás comigo, e tudo o que é meu é teu;', 1, CURRENT_TIMESTAMP, false),
(42, 15, 32, 'era justo, porém, regozijarmo-nos e alegramo-nos, porque este teu irmão estava morto, e reviveu; tinha-se perdido, e foi achado.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 1, 'Dizia Jesus também aos seus discípulos: Havia certo homem rico, que tinha um mordomo; e este foi acusado perante ele de estar dissipando os seus bens.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 2, 'Chamou-o, então, e lhe disse: Que é isso que ouço dizer de ti? Presta contas da tua mordomia; porque já não podes mais ser meu mordomo.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 3, 'Disse, pois, o mordomo consigo: Que hei de fazer, já que o meu senhor me tira a mordomia? Para cavar, não tenho forças; de mendigar, tenho vergonha.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 4, 'Agora sei o que vou fazer, para que, quando for desapossado da mordomia, me recebam em suas casas.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 5, 'E chamando a si cada um dos devedores do seu senhor, perguntou ao primeiro: Quanto deves ao meu senhor?', 1, CURRENT_TIMESTAMP, false),
(42, 16, 6, 'Respondeu ele: Cem cados de azeite. Disse-lhe então: Toma a tua conta, senta-te depressa e escreve cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 7, 'Perguntou depois a outro: E tu, quanto deves? Respondeu ele: Cem coros de trigo. E disse-lhe: Toma a tua conta e escreve oitenta.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 8, 'E louvou aquele senhor ao injusto mordomo por haver procedido com sagacidade; porque os filhos deste mundo são mais sagazes para com a sua geração do que os filhos da luz.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 9, 'Eu vos digo ainda: Granjeai amigos por meio das riquezas da injustiça; para que, quando estas vos faltarem, vos recebam eles nos tabernáculos eternos.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 10, 'Quem é fiel no pouco, também é fiel no muito; quem é injusto no pouco, também é injusto no muito.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 11, 'Se, pois, nas riquezas injustas não fostes fiéis, quem vos confiará as verdadeiras?', 1, CURRENT_TIMESTAMP, false),
(42, 16, 12, 'E se no alheio não fostes fiéis, quem vos dará o que é vosso?', 1, CURRENT_TIMESTAMP, false),
(42, 16, 13, 'Nenhum servo pode servir dois senhores; porque ou há de odiar a um e amar ao outro, o há de odiar a um e amar ao outro, o há de dedicar-se a um e desprezar o outro. Não podeis servir a Deus e às riquezas.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 14, 'Os fariseus, que eram gananciosos, ouviam todas essas coisas e zombavam dele.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 15, 'E ele lhes disse: Vós sois os que vos justificais a vós mesmos diante dos homens, mas Deus conhece os vossos corações; porque o que entre os homens é elevado, perante Deus é abominação.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 16, 'A lei e os profetas vigoraram até João; desde então é anunciado o evangelho do reino de Deus, e todo homem forceja por entrar nele.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 17, 'É, porém, mais fácil passar o céu e a terra do que cair um til da lei.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 18, 'Todo aquele que repudia sua mulher e casa com outra, comete adultério; e quem casa com a que foi repudiada pelo marido, também comete adultério.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 19, 'Ora, havia um homem rico que se vestia de púrpura e de linho finíssimo, e todos os dias se regalava esplendidamente.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 20, 'Ao seu portão fora deitado um mendigo, chamado Lázaro, todo coberto de úlceras;', 1, CURRENT_TIMESTAMP, false),
(42, 16, 21, 'o qual desejava alimentar-se com as migalhas que caíam da mesa do rico; e os próprios cães vinham lamber-lhe as úlceras.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 22, 'Veio a morrer o mendigo, e foi levado pelos anjos para o seio de Abraão; morreu também o rico, e foi sepultado.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 23, 'No inferno, ergueu os olhos, estando em tormentos, e viu ao longe a Abraão, e a Lázaro no seu seio.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 24, 'E, clamando, disse: Pai Abraão, tem misericórdia de mim, e envia-me Lázaro, para que molhe na água a ponta do dedo e me refresque a língua, porque estou atormentado nesta chama.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 25, 'Disse, porém, Abraão: Filho, lembra-te de que em tua vida recebeste os teus bens, e Lázaro de igual modo os males; agora, porém, ele aqui é consolado, e tu atormentado.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 26, 'E além disso, entre nós e vós está posto um grande abismo, de sorte que os que quisessem passar daqui para vós não poderiam, nem os de lá passar para nós.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 27, 'Disse ele então: Rogo-te, pois, ó pai, que o mandes à casa de meu pai,', 1, CURRENT_TIMESTAMP, false),
(42, 16, 28, 'porque tenho cinco irmãos; para que lhes dê testemunho, a fim de que não venham eles também para este lugar de tormento.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 29, 'Disse-lhe Abraão: Têm Moisés e os profetas; ouçam-nos.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 30, 'Respondeu ele: Não! pai Abraão; mas, se alguém dentre os mortos for ter com eles, hão de se arrepender.', 1, CURRENT_TIMESTAMP, false),
(42, 16, 31, 'Abraão, porém, lhe disse: Se não ouvem a Moisés e aos profetas, tampouco acreditarão, ainda que ressuscite alguém dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 1, 'Disse Jesus a seus discípulos: É impossível que não venham tropeços, mas ai daquele por quem vierem!', 1, CURRENT_TIMESTAMP, false),
(42, 17, 2, 'Melhor lhe fora que se lhe pendurasse ao pescoço uma pedra de moinho e fosse lançado ao mar, do que fazer tropeçar um destes pequeninos.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 3, 'Tende cuidado de vós mesmos; se teu irmão pecar, repreende-o; e se ele se arrepender, perdoa-lhe.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 4, 'Mesmo se pecar contra ti sete vezes no dia, e sete vezes vier ter contigo, dizendo: Arrependo-me; tu lhe perdoarás.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 5, 'Disseram então os apóstolos ao Senhor: Aumenta-nos a fé.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 6, 'Respondeu o Senhor: Se tivésseis fé como um grão de mostarda, diríeis a esta amoreira: Desarraiga-te, e planta-te no mar; e ela vos obedeceria.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 7, 'Qual de vós, tendo um servo a lavrar ou a apascentar gado, lhe dirá, ao voltar ele do campo: chega-te já, e reclina-te à mesa?', 1, CURRENT_TIMESTAMP, false),
(42, 17, 8, 'Não lhe dirá antes: Prepara-me a ceia, e cinge-te, e serve-me, até que eu tenha comido e bebido, e depois comerás tu e beberás?', 1, CURRENT_TIMESTAMP, false),
(42, 17, 9, 'Porventura agradecerá ao servo, porque este fez o que lhe foi mandado?', 1, CURRENT_TIMESTAMP, false),
(42, 17, 10, 'Assim também vós, quando fizerdes tudo o que vos for mandado, dizei: Somos servos inúteis; fizemos somente o que devíamos fazer.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 11, 'E aconteceu que, indo ele a Jerusalém, passava pela divisa entre a Samária e a Galiléia.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 12, 'Ao entrar em certa aldeia, saíram-lhe ao encontro dez leprosos, os quais pararam de longe,', 1, CURRENT_TIMESTAMP, false),
(42, 17, 13, 'e levantaram a voz, dizendo: Jesus, Mestre, tem compaixão de nós!', 1, CURRENT_TIMESTAMP, false),
(42, 17, 14, 'Ele, logo que os viu, disse-lhes: Ide, e mostrai-vos aos sacerdotes. E aconteceu que, enquanto iam, ficaram limpos.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 15, 'Um deles, vendo que fora curado, voltou glorificando a Deus em alta voz;', 1, CURRENT_TIMESTAMP, false),
(42, 17, 16, 'e prostrou-se com o rosto em terra aos pés de Jesus, dando-lhe graças; e este era samaritano.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 17, 'Perguntou, pois, Jesus: Não foram limpos os dez? E os nove, onde estão?', 1, CURRENT_TIMESTAMP, false),
(42, 17, 18, 'Não se achou quem voltasse para dar glória a Deus, senão este estrangeiro?', 1, CURRENT_TIMESTAMP, false),
(42, 17, 19, 'E disse-lhe: Levanta-te, e vai; a tua fé te salvou.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 20, 'Sendo Jesus interrogado pelos fariseus sobre quando viria o reino de Deus, respondeu-lhes: O reino de Deus não vem com aparência exterior;', 1, CURRENT_TIMESTAMP, false),
(42, 17, 21, 'nem dirão: Ei-lo aqui! ou: Ei-lo ali! pois o reino de Deus está dentro de vós.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 22, 'Então disse aos discípulos: Dias virão em que desejareis ver um dos dias do Filho do homem, e não o vereis.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 23, 'Dir-vos-ão: Ei-lo ali! ou: Ei-lo aqui! não vades, nem os sigais;', 1, CURRENT_TIMESTAMP, false),
(42, 17, 24, 'pois, assim como o relâmpago, fuzilando em uma extremidade do céu, ilumina até a outra extremidade, assim será também o Filho do homem no seu dia.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 25, 'Mas primeiro é necessário que ele padeça muitas coisas, e que seja rejeitado por esta geração.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 26, 'Como aconteceu nos dias de Noé, assim também será nos dias do Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 27, 'Comiam, bebiam, casavam e davam-se em casamento, até o dia em que Noé entrou na arca, e veio o dilúvio e os destruiu a todos.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 28, 'Como também da mesma forma aconteceu nos dias de Ló: comiam, bebiam, compravam, vendiam, plantavam e edificavam;', 1, CURRENT_TIMESTAMP, false),
(42, 17, 29, 'mas no dia em que Ló saiu de Sodoma choveu do céu fogo e enxofre, e os destruiu a todos;', 1, CURRENT_TIMESTAMP, false),
(42, 17, 30, 'assim será no dia em que o Filho do homem se há de manifestar.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 31, 'Naquele dia, quem estiver no eirado, tendo os seus bens em casa, não desça para tirá-los; e, da mesma sorte, o que estiver no campo, não volte para trás.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 32, 'Lembrai-vos da mulher de Ló.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 33, 'Qualquer que procurar preservar a sua vida, perdê-la-á, e qualquer que a perder, conservá-la-á.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 34, 'Digo-vos: Naquela noite estarão dois numa cama; um será tomado, e o outro será deixado.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 35, 'Duas mulheres estarão juntas moendo; uma será tomada, e a outra será deixada.', 1, CURRENT_TIMESTAMP, false),
(42, 17, 36, '{Dois homens estarão no campo; um será tomado, e o outro será deixado.}', 1, CURRENT_TIMESTAMP, false),
(42, 17, 37, 'Perguntaram-lhe: Onde, Senhor? E respondeu-lhes: Onde estiver o corpo, aí se ajuntarão também os abutres.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 1, 'Contou-lhes também uma parábola sobre o dever de orar sempre, e nunca desfalecer.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 2, 'dizendo: Havia em certa cidade um juiz que não temia a Deus, nem respeitava os homens.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 3, 'Havia também naquela mesma cidade uma viúva que ia ter com ele, dizendo: Faze-me justiça contra o meu adversário.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 4, 'E por algum tempo não quis atendê-la; mas depois disse consigo: Ainda que não temo a Deus, nem respeito os homens,', 1, CURRENT_TIMESTAMP, false),
(42, 18, 5, 'todavia, como esta viúva me incomoda, hei de fazer-lhe justiça, para que ela não continue a vir molestar-me.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 6, 'Prosseguiu o Senhor: Ouvi o que diz esse juiz injusto.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 7, 'E não fará Deus justiça aos seus escolhidos, que dia e noite clamam a ele, já que é longânimo para com eles?', 1, CURRENT_TIMESTAMP, false),
(42, 18, 8, 'Digo-vos que depressa lhes fará justiça. Contudo quando vier o Filho do homem, porventura achará fé na terra?', 1, CURRENT_TIMESTAMP, false),
(42, 18, 9, 'Propôs também esta parábola a uns que confiavam em si mesmos, crendo que eram justos, e desprezavam os outros:', 1, CURRENT_TIMESTAMP, false),
(42, 18, 10, 'Dois homens subiram ao templo para orar; um fariseu, e o outro publicano.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 11, 'O fariseu, de pé, assim orava consigo mesmo: ó Deus, graças te dou que não sou como os demais homens, roubadores, injustos, adúlteros, nem ainda com este publicano.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 12, 'Jejuo duas vezes na semana, e dou o dízimo de tudo quanto ganho.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 13, 'Mas o publicano, estando em pé de longe, nem ainda queria levantar os olhos ao céu, mas batia no peito, dizendo: ó Deus, sê propício a mim, o pecador!', 1, CURRENT_TIMESTAMP, false),
(42, 18, 14, 'Digo-vos que este desceu justificado para sua casa, e não aquele; porque todo o que a si mesmo se exaltar será humilhado; mas o que a si mesmo se humilhar será exaltado.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 15, 'Traziam-lhe também as crianças, para que as tocasse; mas os discípulos, vendo isso, os repreendiam.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 16, 'Jesus, porém, chamando-as para si, disse: Deixai vir a mim as crianças, e não as impeçais, porque de tais é o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 17, 'Em verdade vos digo que, qualquer que não receber o reino de Deus como criança, de modo algum entrará nele.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 18, 'E perguntou-lhe um dos principais: Bom Mestre, que hei de fazer para herdar a vida eterna?', 1, CURRENT_TIMESTAMP, false),
(42, 18, 19, 'Respondeu-lhe Jesus: Por que me chamas bom? Ninguém é bom, senão um, que é Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 20, 'Sabes os mandamentos: Não adulterarás; não matarás; não furtarás; não dirás falso testemunho; honra a teu pai e a tua mãe.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 21, 'Replicou o homem: Tudo isso tenho guardado desde a minha juventude.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 22, 'Quando Jesus ouviu isso, disse-lhe: Ainda te falta uma coisa; vende tudo quanto tens e reparte-o pelos pobres, e terás um tesouro no céu; e vem, segue-me.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 23, 'Mas, ouvindo ele isso, encheu-se de tristeza; porque era muito rico.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 24, 'E Jesus, vendo-o assim, disse: Quão dificilmente entrarão no reino de Deus os que têm riquezas!', 1, CURRENT_TIMESTAMP, false),
(42, 18, 25, 'Pois é mais fácil um camelo passar pelo fundo duma agulha, do que entrar um rico no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 26, 'Então os que ouviram isso disseram: Quem pode, então, ser salvo?', 1, CURRENT_TIMESTAMP, false),
(42, 18, 27, 'Respondeu-lhes: As coisas que são impossíveis aos homens são possíveis a Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 28, 'Disse-lhe Pedro: Eis que nós deixamos tudo, e te seguimos.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 29, 'Respondeu-lhes Jesus: Em verdade vos digo que ninguém há que tenha deixado casa, ou mulher, ou irmãos, ou pais, ou filhos, por amor do reino de Deus,', 1, CURRENT_TIMESTAMP, false),
(42, 18, 30, 'que não haja de receber no presente muito mais, e no mundo vindouro a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 31, 'Tomando Jesus consigo os doze, disse-lhes: Eis que subimos a Jerusalém e se cumprirá no filho do homem tudo o que pelos profetas foi escrito;', 1, CURRENT_TIMESTAMP, false),
(42, 18, 32, 'pois será entregue aos gentios, e escarnecido, injuriado e cuspido;', 1, CURRENT_TIMESTAMP, false),
(42, 18, 33, 'e depois de o açoitarem, o matarão; e ao terceiro dia ressurgirá.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 34, 'Mas eles não entenderam nada disso; essas palavras lhes eram obscuras, e não percebiam o que lhes dizia.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 35, 'Ora, quando ele ia chegando a Jericó, estava um cego sentado junto do caminho, mendigando.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 36, 'Este, pois, ouvindo passar a multidão, perguntou que era aquilo.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 37, 'Disseram-lhe que Jesus, o nazareno, ia passando.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 38, 'Então ele se pôs a clamar, dizendo: Jesus, Filho de Davi, tem compaixão de mim!', 1, CURRENT_TIMESTAMP, false),
(42, 18, 39, 'E os que iam à frente repreendiam-no, para que se calasse; ele, porém, clamava ainda mais: Filho de Davi, tem compaixão de mim!', 1, CURRENT_TIMESTAMP, false),
(42, 18, 40, 'Parou, pois, Jesus, e mandou que lho trouxessem. Tendo ele chegado, perguntou-lhe:', 1, CURRENT_TIMESTAMP, false),
(42, 18, 41, 'Que queres que te faça? Respondeu ele: Senhor, que eu veja.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 42, 'Disse-lhe Jesus: Vê; a tua fé te salvou.', 1, CURRENT_TIMESTAMP, false),
(42, 18, 43, 'Imediatamente recuperou a vista, e o foi seguindo, gloficando a Deus. E todo o povo, vendo isso, dava louvores a Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 1, 'Tendo Jesus entrado em Jericó, ia atravessando a cidade.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 2, 'Havia ali um homem chamado Zaqueu, o qual era chefe de publicanos e era rico.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 3, 'Este procurava ver quem era Jesus, e não podia, por causa da multidão, porque era de pequena estatura.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 4, 'E correndo adiante, subiu a um sicômoro a fim de vê-lo, porque havia de passar por ali.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 5, 'Quando Jesus chegou àquele lugar, olhou para cima e disse-lhe: Zaqueu, desce depressa; porque importa que eu fique hoje em tua casa.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 6, 'Desceu, pois, a toda a pressa, e o recebeu com alegria.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 7, 'Ao verem isso, todos murmuravam, dizendo: Entrou para ser hóspede de um homem pecador.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 8, 'Zaqueu, porém, levantando-se, disse ao Senhor: Eis aqui, Senhor, dou aos pobres metade dos meus bens; e se em alguma coisa tenho defraudado alguém, eu lho restituo quadruplicado.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 9, 'Disse-lhe Jesus: Hoje veio a salvação a esta casa, porquanto também este é filho de Abraão.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 10, 'Porque o Filho do homem veio buscar e salvar o que se havia perdido.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 11, 'Ouvindo eles isso, prosseguiu Jesus, e contou uma parábola, visto estar ele perto de Jerusalém, e pensarem eles que o reino de Deus se havia de manifestar imediatamente.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 12, 'Disse pois: Certo homem nobre partiu para uma terra longínqua, a fim de tomar posse de um reino e depois voltar.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 13, 'E chamando dez servos seus, deu-lhes dez minas, e disse-lhes: Negociai até que eu venha.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 14, 'Mas os seus concidadãos odiavam-no, e enviaram após ele uma embaixada, dizendo: Não queremos que este homem reine sobre nós.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 15, 'E sucedeu que, ao voltar ele, depois de ter tomado posse do reino, mandou chamar aqueles servos a quem entregara o dinheiro, a fim de saber como cada um havia negociado.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 16, 'Apresentou-se, pois, o primeiro, e disse: Senhor, a tua mina rendeu dez minas.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 17, 'Respondeu-lhe o senhor: Bem está, servo bom! porque no mínimo foste fiel, sobre dez cidades terás autoridade.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 18, 'Veio o segundo, dizendo: Senhor, a tua mina rendeu cinco minas.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 19, 'A este também respondeu: Sê tu também sobre cinco cidades.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 20, 'E veio outro, dizendo: Senhor, eis aqui a tua mina, que guardei num lenço;', 1, CURRENT_TIMESTAMP, false),
(42, 19, 21, 'pois tinha medo de ti, porque és homem severo; tomas o que não puseste, e ceifas o que não semeaste.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 22, 'Disse-lhe o Senhor: Servo mau! pela tua boca te julgarei; sabias que eu sou homem severo, que tomo o que não pus, e ceifo o que não semeei;', 1, CURRENT_TIMESTAMP, false),
(42, 19, 23, 'por que, pois, não puseste o meu dinheiro no barco? então vindo eu, o teria retirado com os juros.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 24, 'E disse aos que estavam ali: Tirai-lhe a mina, e dai-a ao que tem as dez minas.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 25, 'Responderam-lhe eles: Senhor, ele tem dez minas.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 26, 'Pois eu vos digo que a todo o que tem, dar-se-lhe-á; mas ao que não tem, até aquilo que tem ser-lhe-á tirado.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 27, 'Quanto, porém, àqueles meus inimigos que não quiseram que eu reinasse sobre eles, trazei-os aqui, e matai-os diante de mim.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 28, 'Tendo Jesus assim falado, ia caminhando adiante deles, subindo para Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 29, 'Ao aproximar-se de Betfagé e de Betânia, junto do monte que se chama das Oliveiras, enviou dois dos discípulos,', 1, CURRENT_TIMESTAMP, false),
(42, 19, 30, 'dizendo-lhes: Ide à aldeia que está defronte, e aí, ao entrar, achareis preso um jumentinho em que ninguém jamais montou; desprendei-o e trazei-o.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 31, 'Se alguém vos perguntar: Por que o desprendeis? respondereis assim: O Senhor precisa dele.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 32, 'Partiram, pois, os que tinham sido enviados, e acharam conforme lhes dissera.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 33, 'Enquanto desprendiam o jumentinho, os seus donos lhes perguntaram: Por que desprendeis o jumentinho?', 1, CURRENT_TIMESTAMP, false),
(42, 19, 34, 'Responderam eles: O Senhor precisa dele.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 35, 'Trouxeram-no, pois, a Jesus e, lançando os seus mantos sobre o jumentinho, fizeram que Jesus montasse.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 36, 'E, enquanto ele ia passando, outros estendiam no caminho os seus mantos.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 37, 'Quando já ia chegando à descida do Monte das Oliveiras, toda a multidão dos discípulos, regozijando-se, começou a louvar a Deus em alta voz, por todos os milagres que tinha visto,', 1, CURRENT_TIMESTAMP, false),
(42, 19, 38, 'dizendo: Bendito o Rei que vem em nome do Senhor; paz no céu, e glória nas alturas.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 39, 'Nisso, disseram-lhe alguns dos fariseus dentre a multidão: Mestre, repreende os teus discípulos.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 40, 'Ao que ele respondeu: Digo-vos que, se estes se calarem, as pedras clamarão.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 41, 'E quando chegou perto e viu a cidade, chorou sobre ela,', 1, CURRENT_TIMESTAMP, false),
(42, 19, 42, 'dizendo: Ah! se tu conhecesses, ao menos neste dia, o que te poderia trazer a paz! mas agora isso está encoberto aos teus olhos.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 43, 'Porque dias virão sobre ti em que os teus inimigos te cercarão de trincheiras, e te sitiarão, e te apertarão de todos os lados,', 1, CURRENT_TIMESTAMP, false),
(42, 19, 44, 'e te derribarão, a ti e aos teus filhos que dentro de ti estiverem; e não deixarão em ti pedra sobre pedra, porque não conheceste o tempo da tua visitação.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 45, 'Então, entrando ele no templo, começou a expulsar os que ali vendiam,', 1, CURRENT_TIMESTAMP, false),
(42, 19, 46, 'dizendo-lhes: Está escrito: A minha casa será casa de oração; vós, porém, a fizestes covil de salteadores.', 1, CURRENT_TIMESTAMP, false),
(42, 19, 47, 'E todos os dias ensinava no templo; mas os principais sacerdotes, os escribas, e os principais do povo procuravam matá-lo;', 1, CURRENT_TIMESTAMP, false),
(42, 19, 48, 'mas não achavam meio de o fazer; porque todo o povo ficava enlevado ao ouvi-lo.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 1, 'Num desses dias, quando Jesus ensinava o povo no templo, e anunciava o evangelho, sobrevieram os principais sacerdotes e os escribas, com os anciãos.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 2, 'e falaram-lhe deste modo: Dize-nos, com que autoridade fazes tu estas coisas? Ou, quem é o que te deu esta autoridade?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 3, 'Respondeu-lhes ele: Eu também vos farei uma pergunta; dizei-me, pois:', 1, CURRENT_TIMESTAMP, false),
(42, 20, 4, 'O batismo de João era do céu ou dos homens?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 5, 'Ao que eles arrazoavam entre si: Se dissermos: do céu, ele dirá: Por que não crestes?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 6, 'Mas, se dissermos: Dos homens, todo o povo nos apedrejará; pois está convencido de que João era profeta.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 7, 'Responderam, pois, que não sabiam donde era.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 8, 'Replicou-lhes Jesus: Nem eu vos digo com que autoridade faço estas coisas.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 9, 'Começou então a dizer ao povo esta parábola: Um homem plantou uma vinha, arrendou-a a uns lavradores, e ausentou-se do país por muito tempo.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 10, 'No tempo próprio mandou um servo aos lavradores, para que lhe dessem dos frutos da vinha; mas os lavradores, espancando-o, mandaram-no embora de mãos vazias.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 11, 'Tornou a mandar outro servo; mas eles espancaram também a este e, afrontando-o, mandaram-no embora de mãos vazias.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 12, 'E mandou ainda um terceiro; mas feriram também a este e lançaram-no fora.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 13, 'Disse então o senhor da vinha: Que farei? Mandarei o meu filho amado; a ele talvez respeitarão.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 14, 'Mas quando os lavradores o viram, arrazoaram entre si, dizendo: Este é o herdeiro; matemo-lo, para que a herança seja nossa.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 15, 'E lançando-o fora da vinha, o mataram. Que lhes fará, pois, o senhor da vinha?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 16, 'Virá e destruirá esses lavradores, e dará a vinha a outros. Ouvindo eles isso, disseram: Tal não aconteça!', 1, CURRENT_TIMESTAMP, false),
(42, 20, 17, 'Mas Jesus, olhando para eles, disse: Pois, que quer dizer isto que está escrito: A pedra que os edificadores rejeitaram, essa foi posta como pedra angular?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 18, 'Todo o que cair sobre esta pedra será despedaçado; mas aquele sobre quem ela cair será reduzido a pó.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 19, 'Ainda na mesma hora os escribas e os principais sacerdotes, percebendo que contra eles proferira essa parábola, procuraram deitar-lhe as mãos, mas temeram o povo.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 20, 'E, aguardando oportunidade, mandaram espias, os quais se fingiam justos, para o apanharem em alguma palavra, e o entregarem à jurisdição e à autoridade do governador.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 21, 'Estes, pois, o interrogaram, dizendo: Mestre, sabemos que falas e ensinas retamente, e que não consideras a aparência da pessoa, mas ensinas segundo a verdade o caminho de Deus;', 1, CURRENT_TIMESTAMP, false),
(42, 20, 22, 'é-nos lícito dar tributo a César, ou não?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 23, 'Mas Jesus, percebendo a astúcia deles, disse-lhes:', 1, CURRENT_TIMESTAMP, false),
(42, 20, 24, 'Mostrai-me um denário. De quem é a imagem e a inscrição que ele tem? Responderam: De César.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 25, 'Disse-lhes então: Dai, pois, a César o que é de César, e a Deus o que é de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 26, 'E não puderam apanhá-lo em palavra alguma diante do povo; e admirados da sua resposta, calaram-se.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 27, 'Chegaram então alguns dos saduceus, que dizem não haver ressurreição, e perguntaram-lhe:', 1, CURRENT_TIMESTAMP, false),
(42, 20, 28, 'Mestre, Moisés nos deixou escrito que se morrer alguém, tendo mulher mas não tendo filhos, o irmão dele case com a viúva, e suscite descendência ao irmão.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 29, 'Havia, pois, sete irmãos. O primeiro casou-se e morreu sem filhos;', 1, CURRENT_TIMESTAMP, false),
(42, 20, 30, 'então o segundo, e depois o terceiro, casaram com a viúva;', 1, CURRENT_TIMESTAMP, false),
(42, 20, 31, 'e assim todos os sete, e morreram, sem deixar filhos.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 32, 'Depois morreu também a mulher.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 33, 'Portanto, na ressurreição, de qual deles será ela esposa, pois os sete por esposa a tiveram?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 34, 'Respondeu-lhes Jesus: Os filhos deste mundo casaram-se e dão-se em casamento;', 1, CURRENT_TIMESTAMP, false),
(42, 20, 35, 'mas os que são julgados dignos de alcançar o mundo vindouro, e a ressurreição dentre os mortos, nem se casam nem se dão em casamento;', 1, CURRENT_TIMESTAMP, false),
(42, 20, 36, 'porque já não podem mais morrer; pois são iguais aos anjos, e são filhos de Deus, sendo filhos da ressurreição.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 37, 'Mas que os mortos hão de ressurgir, o próprio Moisés o mostrou, na passagem a respeito da sarça, quando chama ao Senhor; Deus de Abraão, e Deus de Isaque, e Deus de Jacó.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 38, 'Ora, ele não é Deus de mortos, mas de vivos; porque para ele todos vivem.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 39, 'Responderam alguns dos escribas: Mestre, disseste bem.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 40, 'Não ousavam, pois, perguntar-lhe mais coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 41, 'Jesus, porém, lhes perguntou: Como dizem que o Cristo é filho de Davi?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 42, 'Pois o próprio Davi diz no livro dos Salmos: Disse o Senhor ao meu Senhor: Assenta-te à minha direita,', 1, CURRENT_TIMESTAMP, false),
(42, 20, 43, 'até que eu ponha os teus inimigos por escabelo dos teus pés.', 1, CURRENT_TIMESTAMP, false),
(42, 20, 44, 'Logo Davi lhe chama Senhor como, pois, é ele seu filho?', 1, CURRENT_TIMESTAMP, false),
(42, 20, 45, 'Enquanto todo o povo o ouvia, disse Jesus aos seus discípulos:', 1, CURRENT_TIMESTAMP, false),
(42, 20, 46, 'Guardai-vos dos escribas, que querem andar com vestes compridas, e gostam das saudações nas praças, dos primeiros assentos nas sinagogas, e dos primeiros lugares nos banquetes;', 1, CURRENT_TIMESTAMP, false),
(42, 20, 47, 'que devoram as casas das viúvas, fazendo, por pretexto, longas orações; estes hão de receber maior condenação.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 1, 'Jesus, levantando os olhos, viu os ricos deitarem as suas ofertas no cofre;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 2, 'viu também uma pobre viúva lançar ali dois leptos;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 3, 'e disse: Em verdade vos digo que esta pobre viúva deu mais do que todos;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 4, 'porque todos aqueles deram daquilo que lhes sobrava; mas esta, da sua pobreza, deu tudo o que tinha para o seu sustento.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 5, 'E falando-lhe alguns a respeito do templo, como estava ornado de formosas pedras e dádivas, disse ele:', 1, CURRENT_TIMESTAMP, false),
(42, 21, 6, 'Quanto a isto que vedes, dias virão em que não se deixará aqui pedra sobre pedra, que não seja derribada.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 7, 'Perguntaram-lhe então: Mestre, quando, pois, sucederão estas coisas? E que sinal haverá, quando elas estiverem para se cumprir?', 1, CURRENT_TIMESTAMP, false),
(42, 21, 8, 'Respondeu então ele: Acautelai-vos; não sejais enganados; porque virão muitos em meu nome, dizendo: Sou eu; e: O tempo é chegado; não vades após eles.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 9, 'Quando ouvirdes de guerras e tumultos, não vos assusteis; pois é necessário que primeiro aconteçam essas coisas; mas o fim não será logo.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 10, 'Então lhes disse: Levantar-se-á nação contra nação, e reino contra reino;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 11, 'e haverá em vários lugares grandes terremotos, e pestes e fomes; haverá também coisas espantosas, e grandes sinais do céu.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 12, 'Mas antes de todas essas coisas vos hão de prender e perseguir, entregando-vos às sinagogas e aos cárceres, e conduzindo-vos à presença de reis e governadores, por causa do meu nome.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 13, 'Isso vos acontecerá para que deis testemunho.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 14, 'Proponde, pois, em vossos corações não premeditar como haveis de fazer a vossa defesa;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 15, 'porque eu vos darei boca e sabedoria, a que nenhum dos vossos adversário poderá resistir nem contradizer.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 16, 'E até pelos pais, e irmãos, e parentes, e amigos sereis entregues; e matarão alguns de vós;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 17, 'e sereis odiados de todos por causa do meu nome.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 18, 'Mas não se perderá um único cabelo da vossa cabeça.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 19, 'Pela vossa perseverança ganhareis as vossas almas.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 20, 'Mas, quando virdes Jerusalém cercada de exércitos, sabei então que é chegada a sua desolação.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 21, 'Então, os que estiverem na Judéia fujam para os montes; os que estiverem dentro da cidade, saiam; e os que estiverem nos campos não entrem nela.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 22, 'Porque dias de vingança são estes, para que se cumpram todas as coisas que estão escritas.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 23, 'Ai das que estiverem grávidas, e das que amamentarem naqueles dias! porque haverá grande angústia sobre a terra, e ira contra este povo.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 24, 'E cairão ao fio da espada, e para todas as nações serão levados cativos; e Jerusalém será pisada pelos gentios, até que os tempos destes se completem.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 25, 'E haverá sinais no sol, na lua e nas estrelas; e sobre a terra haverá angústia das nações em perplexidade pelo bramido do mar e das ondas.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 26, 'os homens desfalecerão de terror, e pela expectação das coisas que sobrevirão ao mundo; porquanto os poderes do céu serão abalados.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 27, 'Então verão vir o Filho do homem em uma nuvem, com poder e grande glória.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 28, 'Ora, quando essas coisas começarem a acontecer, exultai e levantai as vossas cabeças, porque a vossa redenção se aproxima.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 29, 'Propôs-lhes então uma parábola: Olhai para a figueira, e para todas as árvores;', 1, CURRENT_TIMESTAMP, false),
(42, 21, 30, 'quando começam a brotar, sabeis por vós mesmos, ao vê-las, que já está próximo o verão.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 31, 'Assim também vós, quando virdes acontecerem estas coisas, sabei que o reino de Deus está próximo.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 32, 'Em verdade vos digo que não passará esta geração até que tudo isso se cumpra.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 33, 'Passará o céu e a terra, mas as minhas palavras jamais passarão.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 34, 'Olhai por vós mesmos; não aconteça que os vossos corações se carreguem de glutonaria, de embriaguez, e dos cuidados da vida, e aquele dia vos sobrevenha de improviso como um laço.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 35, 'Porque há de vir sobre todos os que habitam na face da terra.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 36, 'Vigiai, pois, em todo o tempo, orando, para que possais escapar de todas estas coisas que hão de acontecer, e estar em pé na presença do Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 37, 'Ora, de dia ensinava no templo, e à noite, saindo, pousava no monte chamado das Oliveiras.', 1, CURRENT_TIMESTAMP, false),
(42, 21, 38, 'E todo o povo ia ter com ele no templo, de manhã cedo, para o ouvir.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 1, 'Aproximava-se a festa dos pães ázimos, que se chama a páscoa.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 2, 'E os principais sacerdotes e os escribas andavam procurando um modo de o matar; pois temiam o povo.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 3, 'Entrou então Satanás em Judas, que tinha por sobrenome Iscariotes, que era um dos doze;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 4, 'e foi ele tratar com os principais sacerdotes e com os capitães de como lho entregaria.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 5, 'Eles se alegraram com isso, e convieram em lhe dar dinheiro.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 6, 'E ele concordou, e buscava ocasião para lho entregar sem alvoroço.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 7, 'Ora, chegou o dia dos pães ázimos, em que se devia imolar a páscoa;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 8, 'e Jesus enviou a Pedro e a João, dizendo: Ide, preparai-nos a páscoa, para que a comamos.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 9, 'Perguntaram-lhe eles: Onde queres que a preparemos?', 1, CURRENT_TIMESTAMP, false),
(42, 22, 10, 'Respondeu-lhes: Quando entrardes na cidade, sair-vos-á ao encontro um homem, levando um cântaro de água; segui-o até a casa em que ele entrar.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 11, 'E direis ao dono da casa: O Mestre manda perguntar-te: Onde está o aposento em que hei de comer a páscoa com os meus discípulos?', 1, CURRENT_TIMESTAMP, false),
(42, 22, 12, 'Então ele vos mostrará um grande cenáculo mobiliado; aí fazei os preparativos.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 13, 'Foram, pois, e acharam tudo como lhes dissera e prepararam a páscoa.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 14, 'E, chegada a hora, pôs-se Jesus à mesa, e com ele os apóstolos.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 15, 'E disse-lhes: Tenho desejado ardentemente comer convosco esta páscoa, antes da minha paixão;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 16, 'pois vos digo que não a comerei mais até que ela se cumpra no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 17, 'Então havendo recebido um cálice, e tendo dado graças, disse: Tomai-o, e reparti-o entre vós;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 18, 'porque vos digo que desde agora não mais beberei do fruto da videira, até que venha o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 19, 'E tomando pão, e havendo dado graças, partiu-o e deu-lho, dizendo: Isto é o meu corpo, que é dado por vós; fazei isto em memória de mim.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 20, 'Semelhantemente, depois da ceia, tomou o cálice, dizendo: Este cálice é o novo pacto em meu sangue, que é derramado por vós.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 21, 'Mas eis que a mão do que me trai está comigo à mesa.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 22, 'Porque, na verdade, o Filho do homem vai segundo o que está determinado; mas ai daquele homem por quem é traído!', 1, CURRENT_TIMESTAMP, false),
(42, 22, 23, 'Então eles começaram a perguntar entre si qual deles o que ia fazer isso.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 24, 'Levantou-se também entre eles contenda, sobre qual deles parecia ser o maior.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 25, 'Ao que Jesus lhes disse: Os reis dos gentios dominam sobre eles, e os que sobre eles exercem autoridade são chamados benfeitores.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 26, 'Mas vós não sereis assim; antes o maior entre vós seja como o mais novo; e quem governa como quem serve.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 27, 'Pois qual é maior, quem está à mesa, ou quem serve? porventura não é quem está à mesa? Eu, porém, estou entre vós como quem serve.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 28, 'Mas vós sois os que tendes permanecido comigo nas minhas provações;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 29, 'e assim como meu Pai me conferiu domínio, eu vo-lo confiro a vós;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 30, 'para que comais e bebais à minha mesa no meu reino, e vos senteis sobre tronos, julgando as doze tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 31, 'Simão, Simão, eis que Satanás vos pediu para vos cirandar como trigo;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 32, 'mas eu roguei por ti, para que a tua fé não desfaleça; e tu, quando te converteres, fortalece teus irmãos.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 33, 'Respondeu-lhe Pedro: Senhor, estou pronto a ir contigo tanto para a prisão como para a morte.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 34, 'Tornou-lhe Jesus: Digo-te, Pedro, que não cantará hoje o galo antes que três vezes tenhas negado que me conheces.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 35, 'E perguntou-lhes: Quando vos mandei sem bolsa, alforje, ou alparcas, faltou-vos porventura alguma coisa? Eles responderam: Nada.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 36, 'Disse-lhes pois: Mas agora, quem tiver bolsa, tome-a, como também o alforje; e quem não tiver espada, venda o seu manto e compre-a.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 37, 'Porquanto vos digo que importa que se cumpra em mim isto que está escrito: E com os malfeitores foi contado. Pois o que me diz respeito tem seu cumprimento.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 38, 'Disseram eles: Senhor, eis aqui duas espadas. Respondeu-lhes: Basta.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 39, 'Então saiu e, segundo o seu costume, foi para o Monte das Oliveiras; e os discípulos o seguiam.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 40, 'Quando chegou àquele lugar, disse-lhes: Orai, para que não entreis em tentação.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 41, 'E apartou-se deles cerca de um tiro de pedra; e pondo-se de joelhos, orava,', 1, CURRENT_TIMESTAMP, false),
(42, 22, 42, 'dizendo: Pai, se queres afasta de mim este cálice; todavia não se faça a minha vontade, mas a tua.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 43, 'Então lhe apareceu um anjo do céu, que o confortava.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 44, 'E, posto em agonia, orava mais intensamente; e o seu suor tornou-se como grandes gotas de sangue, que caíam sobre o chão.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 45, 'Depois, levantando-se da oração, veio para os seus discípulos, e achou-os dormindo de tristeza;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 46, 'e disse-lhes: Por que estais dormindo? Lenvantai-vos, e orai, para que não entreis em tentação.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 47, 'E estando ele ainda a falar, eis que surgiu uma multidão; e aquele que se chamava Judas, um dos doze, ia adiante dela, e chegou-se a Jesus para o beijar.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 48, 'Jesus, porém, lhe disse: Judas, com um beijo trais o Filho do homem?', 1, CURRENT_TIMESTAMP, false),
(42, 22, 49, 'Quando os que estavam com ele viram o que ia suceder, disseram: Senhor, feri-los-emos a espada?', 1, CURRENT_TIMESTAMP, false),
(42, 22, 50, 'Então um deles feriu o servo do sumo sacerdote, e cortou-lhe a orelha direita.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 51, 'Mas Jesus disse: Deixei-os; basta. E tocando-lhe a orelha, o curou.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 52, 'Então disse Jesus aos principais sacerdotes, oficiais do templo e anciãos, que tinham ido contra ele: Saístes, como a um salteador, com espadas e varapaus?', 1, CURRENT_TIMESTAMP, false),
(42, 22, 53, 'Todos os dias estava eu convosco no templo, e não estendestes as mãos contra mim; mas esta é a vossa hora e o poder das trevas.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 54, 'Então, prendendo-o, o levaram e o introduziram na casa do sumo sacerdote; e Pedro seguia-o de longe.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 55, 'E tendo eles acendido fogo no meio do pátio e havendo-se sentado à roda, sentou-se Pedro entre eles.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 56, 'Mas Pedro o negou, dizendo: Mulher, não o conheço.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 57, 'Daí a pouco, outro o viu, e disse: Tu também és um deles. Mas Pedro disse: Homem, não sou.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 58, 'E, tendo passado quase uma hora, outro afirmava, dizendo: Certamente este também estava com ele, pois é galileu.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 59, 'Mas Pedro respondeu: Homem, não sei o que dizes. E imediatamente estando ele ainda a falar, cantou o galo.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 60, 'Virando-se o Senhor, olhou para Pedro; e Pedro lembrou-se da palavra do Senhor, como lhe havia dito: Hoje, antes que o galo cante, três vezes me negarás.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 61, 'E, havendo saído, chorou amargamente.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 62, 'Os homens que detinham Jesus zombavam dele, e feriam-no;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 63, 'e, vendando-lhe os olhos, perguntavam, dizendo: Profetiza, quem foi que te bateu?', 1, CURRENT_TIMESTAMP, false),
(42, 22, 64, 'E, blasfemando, diziam muitas outras coisas contra ele.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 65, 'Logo que amanheceu reuniu-se a assembléia dos anciãos do povo, tanto os principais sacerdotes como os escribas, e o conduziam ao sinédrio deles, onde lhe disseram:', 1, CURRENT_TIMESTAMP, false),
(42, 22, 66, 'Se tu és o Cristo, dize-no-lo. Replicou-lhes ele: Se eu vo-lo disser, não o crereis;', 1, CURRENT_TIMESTAMP, false),
(42, 22, 67, 'e se eu vos interrogar, de modo algum me respondereis.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 68, 'Mas desde agora estará assentado o Filho do homem à mão direita do poder de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 69, 'Ao que perguntaram todos: Logo, tu és o Filho de Deus? Respondeu-lhes: Vós dizeis que eu sou.', 1, CURRENT_TIMESTAMP, false),
(42, 22, 70, 'Então disseram: Por que ainda temos necessidade de testemunho? pois nós mesmos o ouvimos da sua própria boca.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 1, 'E levantando-se toda a multidão deles, conduziram Jesus a Pilatos.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 2, 'E começaram a acusá-lo, dizendo: Achamos este homem pervertendo a nossa nação, proibindo dar o tributo a César, e dizendo ser ele mesmo Cristo, rei.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 3, 'Pilatos, pois, perguntou-lhe: És tu o rei dos judeus? Respondeu-lhe Jesus: É como dizes.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 4, 'Então disse Pilatos aos principais sacerdotes, e às multidões: Não acho culpa alguma neste homem.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 5, 'Eles, porém, insistiam ainda mais, dizendo: Alvoroça o povo ensinando por toda a Judéia, começando desde a Galiléia até aqui.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 6, 'Então Pilatos, ouvindo isso, perguntou se o homem era galileu;', 1, CURRENT_TIMESTAMP, false),
(42, 23, 7, 'e, quando soube que era da jurisdição de Herodes, remeteu-o a Herodes, que também naqueles dias estava em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 8, 'Ora, quando Herodes viu a Jesus, alegrou-se muito; pois de longo tempo desejava vê-lo, por ter ouvido falar a seu respeito; e esperava ver algum sinal feito por ele;', 1, CURRENT_TIMESTAMP, false),
(42, 23, 9, 'e fazia-lhe muitas perguntas; mas ele nada lhe respondeu.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 10, 'Estavam ali os principais sacerdotes, e os escribas, acusando-o com grande veemência.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 11, 'Herodes, porém, com os seus soldados, desprezou-o e, escarnecendo dele, vestiu-o com uma roupa resplandecente e tornou a enviá-lo a Pilatos.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 12, 'Nesse mesmo dia Pilatos e Herodes tornaram-se amigos; pois antes andavam em inimizade um com o outro.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 13, 'Então Pilatos convocou os principais sacerdotes, as autoridades e o povo,', 1, CURRENT_TIMESTAMP, false),
(42, 23, 14, 'e disse-lhes: Apresentastes-me este homem como pervertedor do povo; e eis que, interrogando-o diante de vós, não achei nele nenhuma culpa, das de que o acusais;', 1, CURRENT_TIMESTAMP, false),
(42, 23, 15, 'nem tampouco Herodes, pois no-lo tornou a enviar; e eis que não tem feito ele coisa alguma digna de morte.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 16, 'Castigá-lo-ei, pois, e o soltarei.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 17, '{E era-lhe necessário soltar-lhes um pela festa.}', 1, CURRENT_TIMESTAMP, false),
(42, 23, 18, 'Mas todos clamaram à uma, dizendo: Fora com este, e solta-nos Barrabás!', 1, CURRENT_TIMESTAMP, false),
(42, 23, 19, 'Ora, Barrabás fora lançado na prisão por causa de uma sedição feita na cidade, e de um homicídio.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 20, 'Mais uma vez, pois, falou-lhes Pilatos, querendo soltar a Jesus.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 21, 'Eles, porém, bradavam, dizendo: Crucifica-o! crucifica-o!', 1, CURRENT_TIMESTAMP, false),
(42, 23, 22, 'Falou-lhes, então, pela terceira vez: Pois, que mal fez ele? Não achei nele nenhuma culpa digna de morte. Castigá-lo-ei, pois, e o soltarei.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 23, 'Mas eles instavam com grandes brados, pedindo que fosse crucificado. E prevaleceram os seus clamores.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 24, 'Então Pilatos resolveu atender-lhes o pedido;', 1, CURRENT_TIMESTAMP, false),
(42, 23, 25, 'e soltou-lhes o que fora lançado na prisão por causa de sedição e de homicídio, que era o que eles pediam; mas entregou Jesus à vontade deles.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 26, 'Quando o levaram dali tomaram um certo Simão, cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse após Jesus.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 27, 'Seguia-o grande multidão de povo e de mulheres, as quais o pranteavam e lamentavam.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 28, 'Jesus, porém, voltando-se para elas, disse: Filhas de Jerusalém, não choreis por mim; chorai antes por vós mesmas, e por vossos filhos.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 29, 'Porque dias hão de vir em que se dirá: Bem-aventuradas as estéreis, e os ventres que não geraram, e os peitos que não amamentaram!', 1, CURRENT_TIMESTAMP, false),
(42, 23, 30, 'Então começarão a dizer aos montes: Caí sobre nós; e aos outeiros: Cobri-nos.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 31, 'Porque, se isto se faz no lenho verde, que se fará no seco?', 1, CURRENT_TIMESTAMP, false),
(42, 23, 32, 'E levavam também com ele outros dois, que eram malfeitores, para serem mortos.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 33, 'Quando chegaram ao lugar chamado Caveira, ali o crucificaram, a ele e também aos malfeitores, um à direita e outro à esquerda.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 34, 'Jesus, porém, dizia: Pai, perdoa-lhes; porque não sabem o que fazem. Então repartiram as vestes dele, deitando sortes sobre elas.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 35, 'E o povo estava ali a olhar. E as próprias autoridades zombavam dele, dizendo: Aos outros salvou; salve-se a si mesmo, se é o Cristo, o escolhido de Deus.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 36, 'Os soldados também o escarneciam, chegando-se a ele, oferecendo-lhe vinagre,', 1, CURRENT_TIMESTAMP, false),
(42, 23, 37, 'e dizendo: Se tu és o rei dos judeus, salva-te a ti mesmo.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 38, 'Por cima dele estava esta inscrição {em letras gregas, romanas e hebraicas:} ESTE É O REI DOS JUDEUS.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 39, 'Então um dos malfeitores que estavam pendurados, blasfemava dele, dizendo: Não és tu o Cristo? salva-te a ti mesmo e a nós.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 40, 'Respondendo, porém, o outro, repreendia-o, dizendo: Nem ao menos temes a Deus, estando na mesma condenação?', 1, CURRENT_TIMESTAMP, false),
(42, 23, 41, 'E nós, na verdade, com justiça; porque recebemos o que os nossos feitos merecem; mas este nenhum mal fez.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 42, 'Então disse: Jesus, lembra-te de mim, quando entrares no teu reino.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 43, 'Respondeu-lhe Jesus: Em verdade te digo que hoje estarás comigo no paraíso.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 44, 'Era já quase a hora sexta, e houve trevas em toda a terra até a hora nona, pois o sol se escurecera;', 1, CURRENT_TIMESTAMP, false),
(42, 23, 45, 'e rasgou-se ao meio o véu do santuário.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 46, 'Jesus, clamando com grande voz, disse: Pai, nas tuas mãos entrego o meu espírito. E, havendo dito isso, expirou.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 47, 'Quando o centurião viu o que acontecera, deu glória a Deus, dizendo: Na verdade, este homem era justo.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 48, 'E todas as multidões que presenciaram este espetáculo, vendo o que havia acontecido, voltaram batendo no peito.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 49, 'Entretanto, todos os conhecidos de Jesus, e as mulheres que o haviam seguido desde a Galiléia, estavam de longe vendo estas coisas.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 50, 'Então um homem chamado José, natural de Arimatéia, cidade dos judeus, membro do sinédrio, homem bom e justo,', 1, CURRENT_TIMESTAMP, false),
(42, 23, 51, 'o qual não tinha consentido no conselho e nos atos dos outros, e que esperava o reino de Deus,', 1, CURRENT_TIMESTAMP, false),
(42, 23, 52, 'chegando a Pilatos, pediu-lhe o corpo de Jesus;', 1, CURRENT_TIMESTAMP, false),
(42, 23, 53, 'e tirando-o da cruz, envolveu-o num pano de linho, e pô-lo num sepulcro escavado em rocha, onde ninguém ainda havia sido posto.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 54, 'Era o dia da preparação, e ia começar o sábado.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 55, 'E as mulheres que tinham vindo com ele da Galiléia, seguindo a José, viram o sepulcro, e como o corpo foi ali depositado.', 1, CURRENT_TIMESTAMP, false),
(42, 23, 56, 'Então voltaram e prepararam especiarias e ungüentos. E no sábado repousaram, conforme o mandamento.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 1, 'Mas já no primeiro dia da semana, bem de madrugada, foram elas ao sepulcro, levando as especiarias que tinham preparado.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 2, 'E acharam a pedra revolvida do sepulcro.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 3, 'Entrando, porém, não acharam o corpo do Senhor Jesus.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 4, 'E, estando elas perplexas a esse respeito, eis que lhes apareceram dois varões em vestes resplandecentes;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 5, 'e ficando elas atemorizadas e abaixando o rosto para o chão, eles lhes disseram: Por que buscais entre os mortos aquele que vive?', 1, CURRENT_TIMESTAMP, false),
(42, 24, 6, 'Ele não está aqui, mas ressurgiu. Lembrai-vos de como vos falou, estando ainda na Galiléia.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 7, 'dizendo: Importa que o Filho do homem seja entregue nas mãos de homens pecadores, e seja crucificado, e ao terceiro dia ressurja.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 8, 'Lembraram-se, então, das suas palavras;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 9, 'e, voltando do sepulcro, anunciaram todas estas coisas aos onze e a todos os demais.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 10, 'E eram Maria Madalena, e Joana, e Maria, mãe de Tiago; também as outras que estavam com elas relataram estas coisas aos apóstolos.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 11, 'E pareceram-lhes como um delírio as palavras das mulheres e não lhes deram crédito.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 12, 'Mas Pedro, levantando-se, correu ao sepulcro; e, abaixando-se, viu somente os panos de linho; e retirou-se, admirando consigo o que havia acontecido.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 13, 'Nesse mesmo dia, iam dois deles para uma aldeia chamada Emaús, que distava de Jerusalém sessenta estádios;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 14, 'e iam comentando entre si tudo aquilo que havia sucedido.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 15, 'Enquanto assim comentavam e discutiam, o próprio Jesus se aproximou, e ia com eles;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 16, 'mas os olhos deles estavam como que fechados, de sorte que não o reconheceram.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 17, 'Então ele lhes perguntou: Que palavras são essas que, caminhando, trocais entre vós? Eles então pararam tristes.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 18, 'E um deles, chamado Cleopas, respondeu-lhe: És tu o único peregrino em Jerusalém que não soube das coisas que nela têm sucedido nestes dias?', 1, CURRENT_TIMESTAMP, false),
(42, 24, 19, 'Ao que ele lhes perguntou: Quais? Disseram-lhe: As que dizem respeito a Jesus, o nazareno, que foi profeta, poderoso em obras e palavras diante de Deus e de todo o povo.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 20, 'e como os principais sacerdotes e as nossas autoridades e entregaram para ser condenado à morte, e o crucificaram.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 21, 'Ora, nós esperávamos que fosse ele quem havia de remir Israel; e, além de tudo isso, é já hoje o terceiro dia desde que essas coisas aconteceram.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 22, 'Verdade é, também, que algumas mulheres do nosso meio nos encheram de espanto; pois foram de madrugada ao sepulcro', 1, CURRENT_TIMESTAMP, false),
(42, 24, 23, 'e, não achando o corpo dele voltaram, declarando que tinham tido uma visão de anjos que diziam estar ele vivo.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 24, 'Além disso, alguns dos que estavam conosco foram ao sepulcro, e acharam ser assim como as mulheres haviam dito; a ele, porém, não o viram.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 25, 'Então ele lhes disse: ó néscios, e tardos de coração para crerdes tudo o que os profetas disseram!', 1, CURRENT_TIMESTAMP, false),
(42, 24, 26, 'Porventura não importa que o Cristo padecesse essas coisas e entrasse na sua glória?', 1, CURRENT_TIMESTAMP, false),
(42, 24, 27, 'E, começando por Moisés, e por todos os profetas, explicou-lhes o que dele se achava em todas as Escrituras.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 28, 'Quando se aproximaram da aldeia para onde iam, ele fez como quem ia para mais longe.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 29, 'Eles, porém, o constrangeram, dizendo: Fica conosco; porque é tarde, e já declinou o dia. E entrou para ficar com eles.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 30, 'Estando com eles à mesa, tomou o pão e o abençoou; e, partindo-o, lho dava.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 31, 'Abriram-se-lhes então os olhos, e o reconheceram; nisto ele desapareceu de diante deles.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 32, 'E disseram um para o outro: Porventura não se nos abrasava o coração, quando pelo caminho nos falava, e quando nos abria as Escrituras?', 1, CURRENT_TIMESTAMP, false),
(42, 24, 33, 'E na mesma hora levantaram-se e voltaram para Jerusalém, e encontraram reunidos os onze e os que estavam com eles,', 1, CURRENT_TIMESTAMP, false),
(42, 24, 34, 'os quais diziam: Realmente o Senhor ressurgiu, e apareceu a Simão.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 35, 'Então os dois contaram o que acontecera no caminho, e como se lhes fizera conhecer no partir do pão.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 36, 'Enquanto ainda falavam nisso, o próprio Jesus se apresentou no meio deles, e disse-lhes: Paz seja convosco.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 37, 'Mas eles, espantados e atemorizados, pensavam que viam algum espírito.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 38, 'Ele, porém, lhes disse: Por que estais perturbados? e por que surgem dúvidas em vossos corações?', 1, CURRENT_TIMESTAMP, false),
(42, 24, 39, 'Olhai as minhas mãos e os meus pés, que sou eu mesmo; apalpai-me e vede; porque um espírito não tem carne nem ossos, como percebeis que eu tenho.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 40, 'E, dizendo isso, mostrou-lhes as mãos e os pés.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 41, 'Não acreditando eles ainda por causa da alegria, e estando admirados, perguntou-lhes Jesus: Tendes aqui alguma coisa que comer?', 1, CURRENT_TIMESTAMP, false),
(42, 24, 42, 'Então lhe deram um pedaço de peixe assado,', 1, CURRENT_TIMESTAMP, false),
(42, 24, 43, 'o qual ele tomou e comeu diante deles.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 44, 'Depois lhe disse: São estas as palavras que vos falei, estando ainda convosco, que importava que se cumprisse tudo o que de mim estava escrito na Lei de Moisés, nos Profetas e nos Salmos.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 45, 'Então lhes abriu o entendimento para compreenderem as Escrituras;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 46, 'e disse-lhes: Assim está escrito que o Cristo padecesse, e ao terceiro dia ressurgisse dentre os mortos;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 47, 'e que em seu nome se pregasse o arrependimento para remissão dos pecados, a todas as nações, começando por Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 48, 'Vós sois testemunhas destas coisas.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 49, 'E eis que sobre vós envio a promessa de meu Pai; ficai porém, na cidade, até que do alto sejais revestidos de poder.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 50, 'Então os levou fora, até Betânia; e levantando as mãos, os abençoou.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 51, 'E aconteceu que, enquanto os abençoava, apartou-se deles; e foi elevado ao céu.', 1, CURRENT_TIMESTAMP, false),
(42, 24, 52, 'E, depois de o adorarem, voltaram com grande júbilo para Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(42, 24, 53, 'e estavam continuamente no templo, bendizendo a Deus.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 1, 'A palavra do Senhor a Israel, por intermédio de Malaquias.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 2, 'Eu vos tenho amado, diz o Senhor. Mas vós dizeis: Em que nos tens amado? Acaso não era Esaú irmão de Jacó? diz o Senhor; todavia amei a Jacó,', 1, CURRENT_TIMESTAMP, false),
(39, 1, 3, 'e aborreci a Esaú; e fiz dos seus montes uma desolação, e dei a sua herança aos chacais do deserto.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 4, 'Ainda que Edom diga: Arruinados estamos, porém tornaremos e edificaremos as ruínas; assim diz o Senhor dos exércitos: Eles edificarão, eu, porém, demolirei; e lhes chamarão: Termo de impiedade, e povo contra quem o Senhor está irado para sempre.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 5, 'E os vossos olhos o verão, e direis: Engrandecido é o Senhor ainda além dos termos de Israel.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 6, 'O filho honra o pai, e o servo ao seu amo; se eu, pois, sou pai, onde está a minha honra? e se eu sou amo, onde está o temor de mim? diz o Senhor dos exércitos a vós, ó sacerdotes, que desprezais o meu nome. E vós dizeis: Em que temos nós desprezado o teu nome?', 1, CURRENT_TIMESTAMP, false),
(39, 1, 7, 'Ofereceis sobre o meu altar pão profano, e dizeis: Em que te havemos profanado? Nisto que pensais, que a mesa do Senhor é desprezível.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 8, 'Pois quando ofereceis em sacrifício um animal cego, isso não é mau? E quando ofereceis o coxo ou o doente, isso não é mau? Ora apresenta-o ao teu governador; terá ele agrado em ti? ou aceitará ele a tua pessoa? diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 9, 'Agora, pois, suplicai o favor de Deus, para que se compadeça de nós. Com tal oferta da vossa mão, aceitará ele a vossa pessoa? diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 10, 'Oxalá que entre vós houvesse até um que fechasse as portas para que não acendesse debalde o fogo do meu altar. Eu não tenho prazer em vós, diz o Senhor dos exércitos, nem aceitarei oferta da vossa mão.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 11, 'Mas desde o nascente do sol até o poente é grande entre as nações o meu nome; e em todo lugar se oferece ao meu nome incenso, e uma oblação pura; porque o meu nome é grande entre as nações, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 12, 'Mas vós o profanais, quando dizeis: A mesa do Senhor é profana, e o seu produto, isto é, a sua comida, é desprezível.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 13, 'Dizeis também: Eis aqui, que canseira! e o lançastes ao desprezo, diz o Senhor dos exércitos; e tendes trazido o que foi roubado, e o coxo e o doente; assim trazeis a oferta. Aceitaria eu isso de vossa mão? diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(39, 1, 14, 'Mas seja maldito o enganador que, tendo animal macho no seu rebanho, o vota, e sacrifica ao Senhor o que tem mácula; porque eu sou grande Rei, diz o Senhor dos exércitos, e o meu nome é temível entre as nações.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 1, 'Agora, ó sacerdotes, este mandamento e para vós.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 2, 'Se não ouvirdes, e se não propuserdes no vosso coração dar honra ao meu nome, diz o Senhor dos exércitos, enviarei a maldição contra vós, e amaldiçoarei as vossas bênçãos; e já as tenho amaldiçoado, porque não aplicais a isso o vosso coração.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 3, 'Eis que vos reprovarei a posteridade, e espalharei sobre os vossos rostos o esterco, sim, o esterco dos vossos sacrifícios; e juntamente com este sereis levados para fora.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 4, 'Então sabereis que eu vos enviei este mandamento, para que o meu pacto fosse com Levi, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 5, 'Meu pacto com ele foi de vida e de paz; e eu lhas dei para que me temesse; e ele me temeu, e assombrou-se por causa do meu nome.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 6, 'A lei da verdade esteve na sua boca, e a impiedade não se achou nos seus lábios; ele andou comigo em paz e em retidão, e da iniqüidade apartou a muitos.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 7, 'Pois os lábios do sacerdote devem guardar o conhecimento, e da sua boca devem os homens procurar a instrução, porque ele é o mensageiro do Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 8, 'Mas vós vos desviastes do caminho; a muitos fizestes tropeçar na lei; corrompestes o pacto de Levi, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 9, 'Por isso também eu vos fiz desprezíveis, e indignos diante de todo o povo, visto que não guardastes os meus caminhos, mas fizestes acepção de pessoas na lei.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 10, 'Não temos nós todos um mesmo Pai? não nos criou um mesmo Deus? por que nos havemos aleivosamente uns para com outros, profanando o pacto de nossos pais?', 1, CURRENT_TIMESTAMP, false),
(39, 2, 11, 'Judá se tem havido aleivosamente, e abominação se cometeu em Israel e em Jerusalém; porque Judá profanou o santuário do Senhor, o qual ele ama, e se casou com a filha de deus estranho.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 12, 'O Senhor extirpará das tendas de Jacó o homem que fizer isto, o que vela, e o que responde, e o que oferece dons ao Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 13, 'Ainda fazeis isto: cobris o altar do Senhor de lágrimas, de choros e de gemidos, porque ele não olha mais para a oferta, nem a aceitará com prazer da vossa mão.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 14, 'Todavia perguntais: Por que? Porque o Senhor tem sido testemunha entre ti e a mulher da tua mocidade, para com a qual procedeste deslealmente sendo ela a tua companheira e a mulher da tua aliança.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 15, 'E não fez ele somente um, ainda que lhe sobejava espírito? E por que somente um? Não é que buscava descendência piedosa? Portanto guardai-vos em vosso espírito, e que ninguém seja infiel para com a mulher da sua mocidade.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 16, 'Pois eu detesto o divórcio, diz o Senhor Deus de Israel, e aquele que cobre de violência o seu vestido; portanto cuidai de vós mesmos, diz o Senhor dos exércitos; e não sejais infiéis.', 1, CURRENT_TIMESTAMP, false),
(39, 2, 17, 'Tendes enfadado ao Senhor com vossas palavras; e ainda dizeis: Em que o havemos enfadado? Nisto que dizeis: Qualquer que faz o mal passa por bom aos olhos do Senhor, e desses é que ele se agrada; ou: Onde está o Deus do juízo?', 1, CURRENT_TIMESTAMP, false),
(39, 3, 1, 'Eis que eu envio o meu mensageiro, e ele há de preparar o caminho diante de mim; e de repente virá ao seu templo o Senhor, a quem vós buscais, e o anjo do pacto, a quem vós desejais; eis que ele vem, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 2, 'Mas quem suportará o dia da sua vinda? e quem subsistirá, quando ele aparecer? Pois ele será como o fogo de fundidor e como o sabão de lavandeiros;', 1, CURRENT_TIMESTAMP, false),
(39, 3, 3, 'assentar-se-á como fundidor e purificador de prata; e purificará os filhos de Levi, e os refinará como ouro e como prata, até que tragam ao Senhor ofertas em justiça.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 4, 'Então a oferta de Judá e de Jerusalém será agradável ao Senhor, como nos dias antigos, e como nos primeiros anos.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 5, 'E chegar-me-ei a vós para juízo; e serei uma testemunha veloz contra os feiticeiros, contra os adúlteros, contra os que juram falsamente, contra os que defraudam o trabalhador em seu salário, a viúva, e o órfão, e que pervertem o direito do estrangeiro, e não me temem, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 6, 'Pois eu, o Senhor, não mudo; por isso vós, ó filhos de Jacó, não sois consumidos.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 7, 'Desde os dias de vossos pais vos desviastes dos meus estatutos, e não os guardastes. Tornai vós para mim, e eu tornarei para vós diz o Senhor dos exércitos. Mas vós dizeis: Em que havemos de tornar?', 1, CURRENT_TIMESTAMP, false),
(39, 3, 8, 'Roubará o homem a Deus? Todavia vós me roubais, e dizeis: Em que te roubamos? Nos dízimos e nas ofertas alçadas.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 9, 'Vós sois amaldiçoados com a maldição; porque a mim me roubais, sim, vós, esta nação toda.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 10, 'Trazei todos os dízimos à casa do tesouro, para que haja mantimento na minha casa, e depois fazei prova de mim, diz o Senhor dos exércitos, se eu não vos abrir as janelas do céu, e não derramar sobre vós tal bênção, que dela vos advenha a maior abastança.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 11, 'Também por amor de vós reprovarei o devorador, e ele não destruirá os frutos da vossa terra; nem a vossa vide no campo lançará o seu fruto antes do tempo, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 12, 'E todas as nações vos chamarão bem-aventurados; porque vós sereis uma terra deleitosa, diz o Senhor dos Exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 13, 'As vossas palavras foram agressivas para mim, diz o Senhor. Mas vós dizeis: Que temos falado contra ti?', 1, CURRENT_TIMESTAMP, false),
(39, 3, 14, 'Vós tendes dito: inútil é servir a Deus. Que nos aproveita termos cuidado em guardar os seus preceitos, e em andar de luto diante do Senhor dos exércitos?', 1, CURRENT_TIMESTAMP, false),
(39, 3, 15, 'Ora pois, nós reputamos por bem-aventurados os soberbos; também os que cometem impiedade prosperam; sim, eles tentam a Deus, e escapam.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 16, 'Então aqueles que temiam ao Senhor falaram uns aos outros; e o Senhor atentou e ouviu, e um memorial foi escrito diante dele, para os que temiam ao Senhor, e para os que se lembravam do seu nome.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 17, 'E eles serão meus, diz o Senhor dos exércitos, minha possessão particular naquele dia que prepararei; poupá-los-ei, como um homem poupa a seu filho, que o serve.', 1, CURRENT_TIMESTAMP, false),
(39, 3, 18, 'Então vereis outra vez a diferença entre o justo e o ímpio; entre o que serve a Deus, e o que o não serve.', 1, CURRENT_TIMESTAMP, false),
(39, 4, 1, 'Pois eis que aquele dia vem ardendo como fornalha; todos os soberbos, e todos os que cometem impiedade, serão como restolho; e o dia que está para vir os abrasará, diz o Senhor dos exércitos, de sorte que não lhes deixará nem raiz nem ramo.', 1, CURRENT_TIMESTAMP, false),
(39, 4, 2, 'Mas para vós, os que temeis o meu nome, nascerá o sol da justiça, trazendo curas nas suas asas; e vós saireis e saltareis como bezerros da estrebaria.', 1, CURRENT_TIMESTAMP, false),
(39, 4, 3, 'E pisareis os ímpios, porque se farão cinza debaixo das plantas de vossos pés naquele dia que prepararei, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(39, 4, 4, 'Lembrai-vos da lei de Moisés, meu servo, a qual lhe mandei em Horebe para todo o Israel, a saber, estatutos e ordenanças.', 1, CURRENT_TIMESTAMP, false),
(39, 4, 5, 'Eis que eu vos enviarei o profeta Elias, antes que venha o grande e terrível dia do Senhor;', 1, CURRENT_TIMESTAMP, false),
(39, 4, 6, 'e ele converterá o coração dos pais aos filhos, e o coração dos filhos a seus pais; para que eu não venha, e fira a terra com maldição.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 1, 'Princípio do evangelho de Jesus Cristo, Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 2, 'Conforme está escrito no profeta Isaías: Eis que envio ante a tua face o meu mensageiro, que há de preparar o teu caminho;', 1, CURRENT_TIMESTAMP, false),
(41, 1, 3, 'voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas;', 1, CURRENT_TIMESTAMP, false),
(41, 1, 4, 'assim apareceu João, o Batista, no deserto, pregando o batismo de arrependimento para remissão dos pecados.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 5, 'E saíam a ter com ele toda a terra da Judéia, e todos os moradores de Jerusalém; e eram por ele batizados no rio Jordão, confessando os seus pecados.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 6, 'Ora, João usava uma veste de pêlos de camelo, e um cinto de couro em torno de seus lombos, e comia gafanhotos e mel silvestre.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 7, 'E pregava, dizendo: Após mim vem aquele que é mais poderoso do que eu, de quem não sou digno de, inclinando-me, desatar a correia das alparcas.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 8, 'Eu vos batizei em água; ele, porém, vos batizará no Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 9, 'E aconteceu naqueles dias que veio Jesus de Nazaré da Galiléia, e foi batizado por João no Jordão.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 10, 'E logo, quando saía da água, viu os céus se abrirem, e o Espírito, qual pomba, a descer sobre ele;', 1, CURRENT_TIMESTAMP, false),
(41, 1, 11, 'e ouviu-se dos céus esta voz: Tu és meu Filho amado; em ti me comprazo.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 12, 'Imediatamente o Espírito o impeliu para o deserto.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 13, 'E esteve no deserto quarenta dias sentado tentado por Satanás; estava entre as feras, e os anjos o serviam.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 14, 'Ora, depois que João foi entregue, veio Jesus para a Galiléia pregando o evangelho de Deus', 1, CURRENT_TIMESTAMP, false),
(41, 1, 15, 'e dizendo: O tempo está cumprido, e é chegado o reino de Deus. Arrependei-vos, e crede no evangelho.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 16, 'E, andando junto do mar da Galiléia, viu a Simão, e a André, irmão de Simão, os quais lançavam a rede ao mar, pois eram pescadores.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 17, 'Disse-lhes Jesus: Vinde após mim, e eu farei que vos torneis pescadores de homens.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 18, 'Então eles, deixando imediatamente as suas redes, o seguiram.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 19, 'E ele, passando um pouco adiante, viu Tiago, filho de Zebedeu, e João, seu irmão, que estavam no barco, consertando as redes,', 1, CURRENT_TIMESTAMP, false),
(41, 1, 20, 'e logo os chamou; eles, deixando seu pai Zebedeu no barco com os empregados, o seguiram.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 21, 'Entraram em Cafarnaum; e, logo no sábado, indo ele à sinagoga, pôs-se a ensinar.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 22, 'E maravilhavam-se da sua doutrina, porque os ensinava como tendo autoridade, e não como os escribas.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 23, 'Ora, estava na sinagoga um homem possesso dum espírito imundo, o qual gritou:', 1, CURRENT_TIMESTAMP, false),
(41, 1, 24, 'Que temos nós contigo, Jesus, nazareno? Vieste destruir-nos? Bem sei quem és: o Santo de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 25, 'Mas Jesus o repreendeu, dizendo: Cala-te, e sai dele.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 26, 'Então o espírito imundo, convulsionando-o e clamando com grande voz, saiu dele.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 27, 'E todos se maravilharam a ponto de perguntarem entre si, dizendo: Que é isto? Uma nova doutrina com autoridade! Pois ele ordena aos espíritos imundos, e eles lhe obedecem!', 1, CURRENT_TIMESTAMP, false),
(41, 1, 28, 'E logo correu a sua fama por toda a região da Galiléia.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 29, 'Em seguida, saiu da sinagoga e foi a casa de Simão e André com Tiago e João.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 30, 'A sogra de Simão estava de cama com febre, e logo lhe falaram a respeito dela.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 31, 'Então Jesus, chegando-se e tomando-a pela mão, a levantou; e a febre a deixou, e ela os servia.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 32, 'Sendo já tarde, tendo-se posto o sol, traziam-lhe todos os enfermos, e os endemoninhados;', 1, CURRENT_TIMESTAMP, false),
(41, 1, 33, 'e toda a cidade estava reunida à porta;', 1, CURRENT_TIMESTAMP, false),
(41, 1, 34, 'e ele curou muitos doentes atacados de diversas moléstias, e expulsou muitos demônios; mas não permitia que os demônios falassem, porque o conheciam.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 35, 'De madrugada, ainda bem escuro, levantou-se, saiu e foi a um lugar deserto, e ali orava.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 36, 'Foram, pois, Simão e seus companheiros procurá-lo;', 1, CURRENT_TIMESTAMP, false),
(41, 1, 37, 'quando o encontraram, disseram-lhe: Todos te buscam.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 38, 'Respondeu-lhes Jesus: Vamos a outras partes, às povoações vizinhas, para que eu pregue ali também; pois para isso é que vim.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 39, 'Foi, então, por toda a Galiléia, pregando nas sinagogas deles e expulsando os demônios.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 40, 'E veio a ele um leproso que, de joelhos, lhe rogava, dizendo: Se quiseres, bem podes tornar-me limpo.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 41, 'Jesus, pois, compadecido dele, estendendo a mão, tocou-o e disse-lhe: Quero; sê limpo.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 42, 'Imediatamente desapareceu dele a lepra e ficou limpo.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 43, 'E Jesus, advertindo-o secretamente, logo o despediu,', 1, CURRENT_TIMESTAMP, false),
(41, 1, 44, 'dizendo-lhe: Olha, não digas nada a ninguém; mas vai, mostra-te ao sacerdote e oferece pela tua purificação o que Moisés determinou, para lhes servir de testemunho.', 1, CURRENT_TIMESTAMP, false),
(41, 1, 45, 'Ele, porém, saindo dali, começou a publicar o caso por toda parte e a divulgá-lo, de modo que Jesus já não podia entrar abertamente numa cidade, mas conservava-se fora em lugares desertos; e de todos os lados iam ter com ele.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 1, 'Alguns dias depois entrou Jesus outra vez em Cafarnaum, e soube-se que ele estava em casa.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 2, 'Ajuntaram-se, pois, muitos, a ponta de não caberem nem mesmo diante da porta; e ele lhes anunciava a palavra.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 3, 'Nisso vieram alguns a trazer-lhe um paralítico, carregado por quatro;', 1, CURRENT_TIMESTAMP, false),
(41, 2, 4, 'e não podendo aproximar-se dele, por causa da multidão, descobriram o telhado onde estava e, fazendo uma abertura, baixaram o leito em que jazia o paralítico.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 5, 'E Jesus, vendo-lhes a fé, disse ao paralítico: Filho, perdoados são os teus pecados.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 6, 'Ora, estavam ali sentados alguns dos escribas, que arrazoavam em seus corações, dizendo:', 1, CURRENT_TIMESTAMP, false),
(41, 2, 7, 'Por que fala assim este homem? Ele blasfema. Quem pode perdoar pecados senão um só, que é Deus?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 8, 'Mas Jesus logo percebeu em seu espírito que eles assim arrazoavam dentro de si, e perguntou-lhes: Por que arrazoais desse modo em vossos corações?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 9, 'Qual é mais fácil? dizer ao paralítico: Perdoados são os teus pecados; ou dizer: Levanta-te, toma o teu leito, e anda?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 10, 'Ora, para que saibais que o Filho do homem tem sobre a terra autoridade para perdoar pecados { disse ao paralítico },', 1, CURRENT_TIMESTAMP, false),
(41, 2, 11, 'a ti te digo, levanta-te, toma o teu leito, e vai para tua casa.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 12, 'Então ele se levantou e, tomando logo o leito, saiu à vista de todos; de modo que todos pasmavam e glorificavam a Deus, dizendo: Nunca vimos coisa semelhante.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 13, 'Outra vez saiu Jesus para a beira do mar; e toda a multidão ia ter com ele, e ele os ensinava.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 14, 'Quando ia passando, viu a Levi, filho de Alfeu, sentado na coletoria, e disse-lhe: Segue-me. E ele, levantando-se, o seguiu.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 15, 'Ora, estando Jesus à mesa em casa de Levi, estavam também ali reclinados com ele e seus discípulos muitos publicanos e pecadores; pois eram em grande número e o seguiam.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 16, 'Vendo os escribas dos fariseus que comia com os publicanos e pecadores, perguntavam aos discípulos: Por que é que ele como com os publicanos e pecadores?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 17, 'Jesus, porém, ouvindo isso, disse-lhes: Não necessitam de médico os sãos, mas sim os enfermos; eu não vim chamar justos, mas pecadores.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 18, 'Ora, os discípulos de João e os fariseus estavam jejuando; e foram perguntar-lhe: Por que jejuam os discípulos de João e os dos fariseus, mas os teus discípulos não jejuam?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 19, 'Respondeu-lhes Jesus: Podem, porventura, jejuar os convidados às núpcias, enquanto está com eles o noivo? Enquanto têm consigo o noivo não podem jejuar;', 1, CURRENT_TIMESTAMP, false),
(41, 2, 20, 'dias virão, porém, em que lhes será tirado o noivo; nesses dias, sim hão de jejuar.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 21, 'Ninguém cose remendo de pano novo em vestido velho; do contrário o remendo novo tira parte do velho, e torna-se maior a rotura.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 22, 'E ninguém deita vinho novo em odres velhos; do contrário, o vinho novo romperá os odres, e perder-se-á o vinho e também os odres; mas deita-se vinho novo em odres novos.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 23, 'E sucedeu passar ele num dia de sábado pelas searas; e os seus discípulos, caminhando, começaram a colher espigas.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 24, 'E os fariseus lhe perguntaram: Olha, por que estão fazendo no sábado o que não é lícito?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 25, 'Respondeu-lhes ele: Acaso nunca lestes o que fez Davi quando se viu em necessidade e teve fome, ele e seus companheiros?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 26, 'Como entrou na casa de Deus, no tempo do sumo sacerdote Abiatar, e comeu dos pães da proposição, dos quais não era lícito comer senão aos sacerdotes, e deu também aos companheiros?', 1, CURRENT_TIMESTAMP, false),
(41, 2, 27, 'E prosseguiu: O sábado foi feito por causa do homem, e não o homem por causa do sábado.', 1, CURRENT_TIMESTAMP, false),
(41, 2, 28, 'Pelo que o Filho do homem até do sábado é Senhor.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 1, 'Outra vez entrou numa sinagoga, e estava ali um homem que tinha uma das mãos atrofiada.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 2, 'E observavam-no para ver se no sábado curaria o homem, a fim de o acusarem.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 3, 'E disse Jesus ao homem que tinha a mão atrofiada: Levanta-te e vem para o meio.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 4, 'Então lhes perguntou: É lícito no sábado fazer bem, ou fazer mal? salvar a vida ou matar? Eles, porém, se calaram.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 5, 'E olhando em redor para eles com indignação, condoendo-se da dureza dos seus corações, disse ao homem: Estende a tua mão. Ele estendeu, e lhe foi restabelecida.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 6, 'E os fariseus, saindo dali, entraram logo em conselho com os herodianos contra ele, para o matarem.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 7, 'Jesus, porém, se retirou com os seus discípulos para a beira do mar; e uma grande multidão dos da Galiléia o seguiu; também da Judéia,', 1, CURRENT_TIMESTAMP, false),
(41, 3, 8, 'e de Jerusalém, da Iduméia e de além do Jordão, e das regiões de Tiro e de Sidom, grandes multidões, ouvindo falar de tudo quanto fazia, vieram ter com ele.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 9, 'Recomendou, pois, a seus discípulos que se lhe preparasse um barquinho, por causa da multidão, para que não o apertasse;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 10, 'porque tinha curado a muitos, de modo que todos quantos tinham algum mal arrojavam-se a ele para lhe tocarem.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 11, 'E os espíritos imundos, quando o viam, prostravam-se diante dele e clamavam, dizendo: Tu és o Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 12, 'E ele lhes advertia com insistência que não o dessem a conhecer.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 13, 'Depois subiu ao monte, e chamou a si os que ele mesmo queria; e vieram a ele.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 14, 'Então designou doze para que estivessem com ele, e os mandasse a pregar;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 15, 'e para que tivessem autoridade de expulsar os demônios.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 16, 'Designou, pois, os doze, a saber: Simão, a quem pôs o nome de Pedro;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 17, 'Tiago, filho de Zebedeu, e João, irmão de Tiago, aos quais pôs o nome de Boanerges, que significa: Filhos do trovão;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 18, 'André, Filipe, Bartolomeu, Mateus, Tomé, Tiago, filho de Alfeu, Tadeu, Simão, o cananeu,', 1, CURRENT_TIMESTAMP, false),
(41, 3, 19, 'e Judas Iscariotes, aquele que o traiu.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 20, 'Depois entrou numa casa. E afluiu outra vez a multidão, de tal modo que nem podiam comer.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 21, 'Quando os seus ouviram isso, saíram para o prender; porque diziam: Ele está fora de si.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 22, 'E os escribas que tinham descido de Jerusalém diziam: Ele está possesso de Belzebu; e: É pelo príncipe dos demônios que expulsa os demônios.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 23, 'Então Jesus os chamou e lhes disse por parábolas: Como pode Satanás expulsar Satanás?', 1, CURRENT_TIMESTAMP, false),
(41, 3, 24, 'Pois, se um reino se dividir contra si mesmo, tal reino não pode subsistir;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 25, 'ou, se uma casa se dividir contra si mesma, tal casa não poderá subsistir;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 26, 'e se Satanás se tem levantado contra si mesmo, e está dividido, tampouco pode ele subsistir; antes tem fim.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 27, 'Pois ninguém pode entrar na casa do valente e roubar-lhe os bens, se primeiro não amarrar o valente; e então lhe saqueará a casa.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 28, 'Em verdade vos digo: Todos os pecados serão perdoados aos filhos dos homens, bem como todas as blasfêmias que proferirem;', 1, CURRENT_TIMESTAMP, false),
(41, 3, 29, 'mas aquele que blasfemar contra o Espírito Santo, nunca mais terá perdão, mas será réu de pecado eterno.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 30, 'Porquanto eles diziam: Está possesso de um espírito imundo.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 31, 'Chegaram então sua mãe e seus irmãos e, ficando da parte de fora, mandaram chamá-lo.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 32, 'E a multidão estava sentada ao redor dele, e disseram-lhe: Eis que tua mãe e teus irmãos estão lá fora e te procuram.', 1, CURRENT_TIMESTAMP, false),
(41, 3, 33, 'Respondeu-lhes Jesus, dizendo: Quem é minha mãe e meus irmãos!', 1, CURRENT_TIMESTAMP, false),
(41, 3, 34, 'E olhando em redor para os que estavam sentados à roda de si, disse: Eis aqui minha mãe e meus irmãos!', 1, CURRENT_TIMESTAMP, false),
(41, 3, 35, 'Pois aquele que fizer a vontade de Deus, esse é meu irmão, irmã e mãe.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 1, 'Outra vez começou a ensinar à beira do mar. E reuniu-se a ele tão grande multidão que ele entrou num barco e sentou-se nele, sobre o mar; e todo o povo estava em terra junto do mar.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 2, 'Então lhes ensinava muitas coisas por parábolas, e lhes dizia no seu ensino:', 1, CURRENT_TIMESTAMP, false),
(41, 4, 3, 'Ouvi: Eis que o semeador saiu a semear;', 1, CURRENT_TIMESTAMP, false),
(41, 4, 4, 'e aconteceu que, quando semeava, uma parte da semente caiu à beira do caminho, e vieram as aves e a comeram.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 5, 'Outra caiu no solo pedregoso, onde não havia muita terra: e logo nasceu, porque não tinha terra profunda;', 1, CURRENT_TIMESTAMP, false),
(41, 4, 6, 'mas, saindo o sol, queimou-se; e, porque não tinha raiz, secou-se.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 7, 'E outra caiu entre espinhos; e cresceram os espinhos, e a sufocaram; e não deu fruto.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 8, 'Mas outras caíram em boa terra e, vingando e crescendo, davam fruto; e um grão produzia trinta, outro sessenta, e outro cem.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 9, 'E disse-lhes: Quem tem ouvidos para ouvir, ouça.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 10, 'Quando se achou só, os que estavam ao redor dele, com os doze, interrogaram-no acerca da parábola.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 11, 'E ele lhes disse: A vós é confiado o mistério do reino de Deus, mas aos de fora tudo se lhes diz por parábolas;', 1, CURRENT_TIMESTAMP, false),
(41, 4, 12, 'para que vendo, vejam, e não percebam; e ouvindo, ouçam, e não entendam; para que não se convertam e sejam perdoados.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 13, 'Disse-lhes ainda: Não percebeis esta parábola? como pois entendereis todas as parábolas?', 1, CURRENT_TIMESTAMP, false),
(41, 4, 14, 'O semeador semeia a palavra.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 15, 'E os que estão junto do caminho são aqueles em quem a palavra é semeada; mas, tendo-a eles ouvido, vem logo Satanás e tira a palavra que neles foi semeada.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 16, 'Do mesmo modo, aqueles que foram semeados nos lugares pedregosos são os que, ouvindo a palavra, imediatamente com alegria a recebem;', 1, CURRENT_TIMESTAMP, false),
(41, 4, 17, 'mas não têm raiz em si mesmos, antes são de pouca duração; depois, sobrevindo tribulação ou perseguição por causa da palavra, logo se escandalizam.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 18, 'Outros ainda são aqueles que foram semeados entre os espinhos; estes são os que ouvem a palavra;', 1, CURRENT_TIMESTAMP, false),
(41, 4, 19, 'mas os cuidados do mundo, a sedução das riquezas e a cobiça doutras coisas, entrando, sufocam a palavra, e ela fica infrutífera.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 20, 'Aqueles outros que foram semeados em boa terra são os que ouvem a palavra e a recebem, e dão fruto, a trinta, a sessenta, e a cem, por um.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 21, 'Disse-lhes mais: Vem porventura a candeia para se meter debaixo do alqueire, ou debaixo da cama? não é antes para se colocar no velador?', 1, CURRENT_TIMESTAMP, false),
(41, 4, 22, 'Porque nada está encoberto senão para ser manifesto; e nada foi escondido senão para vir à luz.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 23, 'Se alguém tem ouvidos para ouvir, ouça.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 24, 'Também lhes disse: Atendei ao que ouvis. Com a medida com que medis vos medirão a vós, e ainda se vos acrescentará.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 25, 'Pois ao que tem, ser-lhe-á dado; e ao que não tem, até aquilo que tem ser-lhe-á tirado.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 26, 'Disse também: O reino de Deus é assim como se um homem lançasse semente à terra,', 1, CURRENT_TIMESTAMP, false),
(41, 4, 27, 'e dormisse e se levantasse de noite e de dia, e a semente brotasse e crescesse, sem ele saber como.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 28, 'A terra por si mesma produz fruto, primeiro a erva, depois a espiga, e por último o grão cheio na espiga.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 29, 'Mas assim que o fruto amadurecer, logo lhe mete a foice, porque é chegada a ceifa.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 30, 'Disse ainda: A que assemelharemos o reino de Deus? ou com que parábola o representaremos?', 1, CURRENT_TIMESTAMP, false),
(41, 4, 31, 'É como um grão de mostarda que, quando se semeia, é a menor de todas as sementes que há na terra;', 1, CURRENT_TIMESTAMP, false),
(41, 4, 32, 'mas, tendo sido semeado, cresce e faz-se a maior de todas as hortaliças e cria grandes ramos, de tal modo que as aves do céu podem aninhar-se à sua sombra.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 33, 'E com muitas parábolas tais lhes dirigia a palavra, conforme podiam compreender.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 34, 'E sem parábola não lhes falava; mas em particular explicava tudo a seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 35, 'Naquele dia, quando já era tarde, disse-lhes: Passemos para o outro lado.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 36, 'E eles, deixando a multidão, o levaram consigo, assim como estava, no barco; e havia com ele também outros barcos.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 37, 'E se levantou grande tempestade de vento, e as ondas batiam dentro do barco, de modo que já se enchia.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 38, 'Ele, porém, estava na popa dormindo sobre a almofada; e despertaram-no, e lhe perguntaram: Mestre, não se te dá que pereçamos?', 1, CURRENT_TIMESTAMP, false),
(41, 4, 39, 'E ele, levantando-se, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te. E cessou o vento, e fez-se grande bonança.', 1, CURRENT_TIMESTAMP, false),
(41, 4, 40, 'Então lhes perguntou: Por que sois assim tímidos? Ainda não tendes fé?', 1, CURRENT_TIMESTAMP, false),
(41, 4, 41, 'Encheram-se de grande temor, e diziam uns aos outros: Quem, porventura, é este, que até o vento e o mar lhe obedecem?', 1, CURRENT_TIMESTAMP, false),
(41, 5, 1, 'Chegaram então ao outro lado do mar, à terra dos gerasenos.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 2, 'E, logo que Jesus saíra do barco, lhe veio ao encontro, dos sepulcros, um homem com espírito imundo,', 1, CURRENT_TIMESTAMP, false),
(41, 5, 3, 'o qual tinha a sua morada nos sepulcros; e nem ainda com cadeias podia alguém prendê-lo;', 1, CURRENT_TIMESTAMP, false),
(41, 5, 4, 'porque, tendo sido muitas vezes preso com grilhões e cadeias, as cadeias foram por ele feitas em pedaços, e os grilhões em migalhas; e ninguém o podia domar;', 1, CURRENT_TIMESTAMP, false),
(41, 5, 5, 'e sempre, de dia e de noite, andava pelos sepulcros e pelos montes, gritando, e ferindo-se com pedras,', 1, CURRENT_TIMESTAMP, false),
(41, 5, 6, 'Vendo, pois, de longe a Jesus, correu e adorou-o;', 1, CURRENT_TIMESTAMP, false),
(41, 5, 7, 'e, clamando com grande voz, disse: Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? conjuro-te por Deus que não me atormentes.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 8, 'Pois Jesus lhe dizia: Sai desse homem, espírito imundo.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 9, 'E perguntou-lhe: Qual é o teu nome? Respondeu-lhe ele: Legião é o meu nome, porque somos muitos.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 10, 'E rogava-lhe muito que não os enviasse para fora da região.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 11, 'Ora, andava ali pastando no monte uma grande manada de porcos.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 12, 'Rogaram-lhe, pois, os demônios, dizendo: Manda-nos para aqueles porcos, para que entremos neles.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 13, 'E ele lho permitiu. Saindo, então, os espíritos imundos, entraram nos porcos; e precipitou-se a manada, que era de uns dois mil, pelo despenhadeiro no mar, onde todos se afogaram.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 14, 'Nisso fugiram aqueles que os apascentavam, e o anunciaram na cidade e nos campos; e muitos foram ver o que era aquilo que tinha acontecido.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 15, 'Chegando-se a Jesus, viram o endemoninhado, o que tivera a legião, sentado, vestido, e em perfeito juízo; e temeram.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 16, 'E os que tinham visto aquilo contaram-lhes como havia acontecido ao endemoninhado, e acerca dos porcos.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 17, 'Então começaram a rogar-lhe que se retirasse dos seus termos.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 18, 'E, entrando ele no barco, rogava-lhe o que fora endemoninhado que o deixasse estar com ele.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 19, 'Jesus, porém, não lho permitiu, mas disse-lhe: Vai para tua casa, para os teus, e anuncia-lhes o quanto o Senhor te fez, e como teve misericórdia de ti.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 20, 'Ele se retirou, pois, e começou a publicar em Decápolis tudo quanto lhe fizera Jesus; e todos se admiravam.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 21, 'Tendo Jesus passado de novo no barco para o outro lado, ajuntou-se a ele uma grande multidão; e ele estava à beira do mar.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 22, 'Chegou um dos chefes da sinagoga, chamado Jairo e, logo que viu a Jesus, lançou-se-lhe aos pés.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 23, 'e lhe rogava com instância, dizendo: Minha filhinha está nas últimas; rogo-te que venhas e lhe imponhas as mãos para que sare e viva.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 24, 'Jesus foi com ele, e seguia-o uma grande multidão, que o apertava.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 25, 'Ora, certa mulher, que havia doze anos padecia de uma hemorragia,', 1, CURRENT_TIMESTAMP, false),
(41, 5, 26, 'e que tinha sofrido bastante às mãos de muitos médicos, e despendido tudo quanto possuía sem nada aproveitar, antes indo a pior,', 1, CURRENT_TIMESTAMP, false),
(41, 5, 27, 'tendo ouvido falar a respeito de Jesus, veio por detrás, entre a multidão, e tocou-lhe o manto;', 1, CURRENT_TIMESTAMP, false),
(41, 5, 28, 'porque dizia: Se tão-somente tocar-lhe as vestes, ficaria curada.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 29, 'E imediatamente cessou a sua hemorragia; e sentiu no corpo estar já curada do seu mal.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 30, 'E logo Jesus, percebendo em si mesmo que saíra dele poder, virou-se no meio da multidão e perguntou: Quem me tocou as vestes?', 1, CURRENT_TIMESTAMP, false),
(41, 5, 31, 'Responderam-lhe os seus discípulos: Vês que a multidão te aperta, e perguntas: Quem me tocou?', 1, CURRENT_TIMESTAMP, false),
(41, 5, 32, 'Mas ele olhava em redor para ver a que isto fizera.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 33, 'Então a mulher, atemorizada e trêmula, cônscia do que nela se havia operado, veio e prostrou-se diante dele, e declarou-lhe toda a verdade.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 34, 'Disse-lhe ele: Filha, a tua fé te salvou; vai-te em paz, e fica livre desse teu mal.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 35, 'Enquanto ele ainda falava, chegaram pessoas da casa do chefe da sinagoga, a quem disseram: A tua filha já morreu; por que ainda incomodas o Mestre?', 1, CURRENT_TIMESTAMP, false),
(41, 5, 36, 'O que percebendo Jesus, disse ao chefe da sinagoga: Não temas, crê somente.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 37, 'E não permitiu que ninguém o acompanhasse, senão Pedro, Tiago, e João, irmão de Tiago.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 38, 'Quando chegaram a casa do chefe da sinagoga, viu Jesus um alvoroço, e os que choravam e faziam grande pranto.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 39, 'E, entrando, disse-lhes: Por que fazeis alvoroço e chorais? a menina não morreu, mas dorme.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 40, 'E riam-se dele; porém ele, tendo feito sair a todos, tomou consigo o pai e a mãe da menina, e os que com ele vieram, e entrou onde a menina estava.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 41, 'E, tomando a mão da menina, disse-lhe: Talita cumi, que, traduzido, é: Menina, a ti te digo, levanta-te.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 42, 'Imediatamente a menina se levantou, e pôs-se a andar, pois tinha doze anos. E logo foram tomados de grande espanto.', 1, CURRENT_TIMESTAMP, false),
(41, 5, 43, 'Então ordenou-lhes expressamente que ninguém o soubesse; e mandou que lhe dessem de comer.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 1, 'Saiu Jesus dali, e foi para a sua terra, e os seus discípulos o seguiam.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 2, 'Ora, chegando o sábado, começou a ensinar na sinagoga; e muitos, ao ouvi-lo, se maravilhavam, dizendo: Donde lhe vêm estas coisas? e que sabedoria é esta que lhe é dada? e como se fazem tais milagres por suas mãos?', 1, CURRENT_TIMESTAMP, false),
(41, 6, 3, 'Não é este o carpinteiro, filho de Maria, irmão de Tiago, de José, de Judas e de Simão? e não estão aqui entre nós suas irmãs? E escandalizavam-se dele.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 4, 'Então Jesus lhes dizia: Um profeta não fica sem honra senão na sua terra, entre os seus parentes, e na sua própria casa.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 5, 'E não podia fazer ali nenhum milagre, a não ser curar alguns poucos enfermos, impondo-lhes as mãos.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 6, 'E admirou-se da incredulidade deles. Em seguida percorria as aldeias circunvizinhas, ensinando.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 7, 'E chamou a si os doze, e começou a enviá-los a dois e dois, e dava-lhes poder sobre os espíritos imundos;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 8, 'ordenou-lhes que nada levassem para o caminho, senão apenas um bordão; nem pão, nem alforje, nem dinheiro no cinto;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 9, 'mas que fossem calçados de sandálias, e que não vestissem duas túnicas.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 10, 'Dizia-lhes mais: Onde quer que entrardes numa casa, ficai nela até sairdes daquele lugar.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 11, 'E se qualquer lugar não vos receber, nem os homens vos ouvirem, saindo dali, sacudi o pó que estiver debaixo dos vossos pés, em testemunho conta eles.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 12, 'Então saíram e pregaram que todos se arrependessem;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 13, 'e expulsavam muitos demônios, e ungiam muitos enfermos com óleo, e os curavam.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 14, 'E soube disso o rei Herodes {porque o nome de Jesus se tornara célebre}, e disse: João, o Batista, ressuscitou dos mortos; e por isso estes poderes milagrosos operam nele.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 15, 'Mas outros diziam: É Elias. E ainda outros diziam: É profeta como um dos profetas.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 16, 'Herodes, porém, ouvindo isso, dizia: É João, aquele a quem eu mandei degolar: ele ressuscitou.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 17, 'Porquanto o próprio Herodes mandara prender a João, e encerrá-lo maniatado no cárcere, por causa de Herodias, mulher de seu irmão Filipe; porque ele se havia casado com ela.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 18, 'Pois João dizia a Herodes: Não te é lícito ter a mulher de teu irmão.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 19, 'Por isso Herodias lhe guardava rancor e queria matá-lo, mas não podia;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 20, 'porque Herodes temia a João, sabendo que era varão justo e santo, e o guardava em segurança; e, ao ouvi-lo, ficava muito perplexo, contudo de boa mente o escutava.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 21, 'Chegado, porém, um dia oportuno quando Herodes no seu aniversário natalício ofereceu um banquete aos grandes da sua corte, aos principais da Galiléia,', 1, CURRENT_TIMESTAMP, false),
(41, 6, 22, 'entrou a filha da mesma Herodias e, dançando, agradou a Herodes e aos convivas. Então o rei disse à jovem: Pede-me o que quiseres, e eu to darei.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 23, 'E jurou-lhe, dizendo: Tudo o que me pedires te darei, ainda que seja metade do meu reino.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 24, 'Tendo ela saído, perguntou a sua mãe: Que pedirei? Ela respondeu: A cabeça de João, o Batista.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 25, 'E tornando logo com pressa à presença do rei, pediu, dizendo: Quero que imediatamente me dês num prato a cabeça de João, o Batista.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 26, 'Ora, entristeceu-se muito o rei; todavia, por causa dos seus juramentos e por causa dos que estavam à mesa, não lha quis negar.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 27, 'O rei, pois, enviou logo um soldado da sua guarda com ordem de trazer a cabeça de João. Então ele foi e o degolou no cárcere,', 1, CURRENT_TIMESTAMP, false),
(41, 6, 28, 'e trouxe a cabeça num prato e a deu à jovem, e a jovem a deu à sua mãe.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 29, 'Quando os seus discípulos ouviram isso, vieram, tomaram o seu corpo e o puseram num sepulcro.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 30, 'Reuniram-se os apóstolos com Jesus e contaram-lhe tudo o que tinham feito e ensinado.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 31, 'Ao que ele lhes disse: Vinde vós, à parte, para um lugar deserto, e descansai um pouco. Porque eram muitos os que vinham e iam, e não tinham tempo nem para comer.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 32, 'Retiraram-se, pois, no barco para um lugar deserto, à parte.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 33, 'Muitos, porém, os viram partir, e os reconheceram; e para lá correram a pé de todas as cidades, e ali chegaram primeiro do que eles.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 34, 'E Jesus, ao desembarcar, viu uma grande multidão e compadeceu-se deles, porque eram como ovelhas que não têm pastor; e começou a ensinar-lhes muitas coisas.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 35, 'Estando a hora já muito adiantada, aproximaram-se dele seus discípulos e disseram: O lugar é deserto, e a hora já está muito adiantada;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 36, 'despede-os, para que vão aos sítios e às aldeias, em redor, e comprem para si o que comer.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 37, 'Ele, porém, lhes respondeu: Dai-lhes vós de comer. Então eles lhe perguntaram: Havemos de ir comprar duzentos denários de pão e dar-lhes de comer?', 1, CURRENT_TIMESTAMP, false),
(41, 6, 38, 'Ao que ele lhes disse: Quantos pães tendes? Ide ver. E, tendo-se informado, responderam: Cinco pães e dois peixes.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 39, 'Então lhes ordenou que a todos fizessem reclinar-se, em grupos, sobre a relva verde.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 40, 'E reclinaram-se em grupos de cem e de cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 41, 'E tomando os cinco pães e os dois peixes, e erguendo os olhos ao céu, os abençoou; partiu os pães e os entregava a seus discípulos para lhos servirem; também repartiu os dois peixes por todos.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 42, 'E todos comeram e se fartaram.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 43, 'Em seguida, recolheram doze cestos cheios dos pedaços de pão e de peixe.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 44, 'Ora, os que comeram os pães eram cinco mil homens.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 45, 'Logo em seguida obrigou os seus discípulos a entrar no barco e passar adiante, para o outro lado, a Betsaida, enquanto ele despedia a multidão.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 46, 'E, tendo-a despedido, foi ao monte para orar.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 47, 'Chegada a tardinha, estava o barco no meio do mar, e ele sozinho em terra.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 48, 'E, vendo-os fatigados a remar, porque o vento lhes era contrário, pela quarta vigília da noite, foi ter com eles, andando sobre o mar; e queria passar-lhes adiante;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 49, 'eles, porém, ao vê-lo andando sobre o mar, pensaram que era um fantasma e gritaram;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 50, 'porque todos o viram e se assustaram; mas ele imediatamente falou com eles e disse-lhes: Tende ânimo; sou eu; não temais.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 51, 'E subiu para junto deles no barco, e o vento cessou; e ficaram, no seu íntimo, grandemente pasmados;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 52, 'pois não tinham compreendido o milagre dos pães, antes o seu coração estava endurecido.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 53, 'E, terminada a travessia, chegaram à terra em Genezaré, e ali atracaram.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 54, 'Logo que desembarcaram, o povo reconheceu a Jesus;', 1, CURRENT_TIMESTAMP, false),
(41, 6, 55, 'e correndo eles por toda aquela região, começaram a levar nos leitos os que se achavam enfermos, para onde ouviam dizer que ele estava.', 1, CURRENT_TIMESTAMP, false),
(41, 6, 56, 'Onde quer, pois, que entrava, fosse nas aldeias, nas cidades ou nos campos, apresentavam os enfermos nas praças, e rogavam-lhe que os deixasse tocar ao menos a orla do seu manto; e todos os que a tocavam ficavam curados.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 1, 'Foram ter com Jesus os fariseus, e alguns dos escribas vindos de Jerusalém,', 1, CURRENT_TIMESTAMP, false),
(41, 7, 2, 'e repararam que alguns dos seus discípulos comiam pão com as mãos impuras, isto é, por lavar.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 3, 'Pois os fariseus, e todos os judeus, guardando a tradição dos anciãos, não comem sem lavar as mãos cuidadosamente;', 1, CURRENT_TIMESTAMP, false),
(41, 7, 4, 'e quando voltam do mercado, se não se purificarem, não comem. E muitas outras coisas há que receberam para observar, como a lavagem de copos, de jarros e de vasos de bronze.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 5, 'Perguntaram-lhe, pois, os fariseus e os escribas: Por que não andam os teus discípulos conforme a tradição dos anciãos, mas comem o pão com as mãos por lavar?', 1, CURRENT_TIMESTAMP, false),
(41, 7, 6, 'Respondeu-lhes: Bem profetizou Isaías acerca de vós, hipócritas, como está escrito: Este povo honra-me com os lábios; o seu coração, porém, está longe de mim;', 1, CURRENT_TIMESTAMP, false),
(41, 7, 7, 'mas em vão me adoram, ensinando doutrinas que são preceitos de homens.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 8, 'Vós deixais o mandamento de Deus, e vos apegais à tradição dos homens.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 9, 'Disse-lhes ainda: Bem sabeis rejeitar o mandamento de Deus, para guardardes a vossa tradição.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 10, 'Pois Moisés disse: Honra a teu pai e a tua mãe; e: Quem maldisser ao pai ou à mãe, certamente morrerá.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 11, 'Mas vós dizeis: Se um homem disser a seu pai ou a sua mãe: Aquilo que poderias aproveitar de mim é Corbã, isto é, oferta ao Senhor,', 1, CURRENT_TIMESTAMP, false),
(41, 7, 12, 'não mais lhe permitis fazer coisa alguma por seu pai ou por sua mãe,', 1, CURRENT_TIMESTAMP, false),
(41, 7, 13, 'invalidando assim a palavra de Deus pela vossa tradição que vós transmitistes; também muitas outras coisas semelhantes fazeis.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 14, 'E chamando a si outra vez a multidão, disse-lhes: Ouvi-me vós todos, e entendei.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 15, 'Nada há fora do homem que, entrando nele, possa contaminá-lo; mas o que sai do homem, isso é que o contamina.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 16, '{Se alguém tem ouvidos para ouvir, ouça.}', 1, CURRENT_TIMESTAMP, false),
(41, 7, 17, 'Depois, quando deixou a multidão e entrou em casa, os seus discípulos o interrogaram acerca da parábola.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 18, 'Respondeu-lhes ele: Assim também vós estais sem entender? Não compreendeis que tudo o que de fora entra no homem não o pode contaminar,', 1, CURRENT_TIMESTAMP, false),
(41, 7, 19, 'porque não lhe entra no coração, mas no ventre, e é lançado fora? Assim declarou puros todos os alimentos.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 20, 'E prosseguiu: O que sai do homem , isso é que o contamina.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 21, 'Pois é do interior, do coração dos homens, que procedem os maus pensamentos, as prostituições, os furtos, os homicídios, os adultérios,', 1, CURRENT_TIMESTAMP, false),
(41, 7, 22, 'a cobiça, as maldades, o dolo, a libertinagem, a inveja, a blasfêmia, a soberba, a insensatez;', 1, CURRENT_TIMESTAMP, false),
(41, 7, 23, 'todas estas más coisas procedem de dentro e contaminam o homem.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 24, 'Levantando-se dali, foi para as regiões de Tiro e Sidom. E entrando numa casa, não queria que ninguém o soubesse, mas não pode ocultar-se;', 1, CURRENT_TIMESTAMP, false),
(41, 7, 25, 'porque logo, certa mulher, cuja filha estava possessa de um espírito imundo, ouvindo falar dele, veio e prostrou-se-lhe aos pés;', 1, CURRENT_TIMESTAMP, false),
(41, 7, 26, '{ora, a mulher era grega, de origem siro-fenícia} e rogava-lhe que expulsasse de sua filha o demônio.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 27, 'Respondeu-lhes Jesus: Deixa que primeiro se fartem os filhos; porque não é bom tomar o pão dos filhos e lança-lo aos cachorrinhos.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 28, 'Ela, porém, replicou, e disse-lhe: Sim, Senhor; mas também os cachorrinhos debaixo da mesa comem das migalhas dos filhos.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 29, 'Então ele lhe disse: Por essa palavra, vai; o demônio já saiu de tua filha.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 30, 'E, voltando ela para casa, achou a menina deitada sobre a cama, e que o demônio já havia saído.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 31, 'Tendo Jesus partido das regiões de Tiro, foi por Sidom até o mar da Galiléia, passando pelas regiões de Decápolis.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 32, 'E trouxeram-lhe um surdo, que falava dificilmente; e rogaram-lhe que pusesse a mão sobre ele.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 33, 'Jesus, pois, tirou-o de entre a multidão, à parte, meteu-lhe os dedos nos ouvidos e, cuspindo, tocou-lhe na língua;', 1, CURRENT_TIMESTAMP, false),
(41, 7, 34, 'e erguendo os olhos ao céu, suspirou e disse-lhe: Efatá; isto é Abre-te.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 35, 'E abriram-se-lhe os ouvidos, a prisão da língua se desfez, e falava perfeitamente.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 36, 'Então lhes ordenou Jesus que a ninguém o dissessem; mas, quando mais lho proibia, tanto mais o divulgavam.', 1, CURRENT_TIMESTAMP, false),
(41, 7, 37, 'E se maravilhavam sobremaneira, dizendo: Tudo tem feito bem; faz até os surdos ouvir e os mudos falar.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 1, 'Naqueles dias, havendo de novo uma grande multidão, e não tendo o que comer, chamou Jesus os discípulos e disse-lhes:', 1, CURRENT_TIMESTAMP, false),
(41, 8, 2, 'Tenho compaixão da multidão, porque já faz três dias que eles estão comigo, e não têm o que comer.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 3, 'Se eu os mandar em jejum para suas casas, desfalecerão no caminho; e alguns deles vieram de longe.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 4, 'E seus discípulos lhe responderam: Donde poderá alguém satisfazê-los de pão aqui no deserto?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 5, 'Perguntou-lhes Jesus: Quantos pães tendes? Responderam: Sete.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 6, 'Logo mandou ao povo que se sentasse no chão; e tomando os sete pães e havendo dado graças, partiu-os e os entregava a seus discípulos para que os distribuíssem; e eles os distribuíram pela multidão.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 7, 'Tinham também alguns peixinhos, os quais ele abençoou, e mandou que estes também fossem distribuídos.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 8, 'Comeram, pois, e se fartaram; e dos pedaços que sobejavam levantaram sete alcofas.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 9, 'Ora, eram cerca de quatro mil homens. E Jesus os despediu.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 10, 'E, entrando logo no barco com seus discípulos, foi para as regiões de Dalmanuta.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 11, 'Saíram os fariseus e começaram a discutir com ele, pedindo-lhe um sinal do céu, para o experimentarem.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 12, 'Ele, suspirando profundamente em seu espírito, disse: Por que pede esta geração um sinal? Em verdade vos digo que a esta geração não será dado sinal algum.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 13, 'E, deixando-os, tornou a embarcar e foi para o outro lado.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 14, 'Ora, eles se esqueceram de levar pão, e no barco não tinham consigo senão um pão.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 15, 'E Jesus ordenou-lhes, dizendo: Olhai, guardai-vos do fermento dos fariseus e do fermento de Herodes.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 16, 'Pelo que eles arrazoavam entre si porque não tinham pão.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 17, 'E Jesus, percebendo isso, disse-lhes: Por que arrazoais por não terdes pão? não compreendeis ainda, nem entendeis? tendes o vosso coração endurecido?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 18, 'Tendo olhos, não vedes? e tendo ouvidos, não ouvis? e não vos lembrais?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 19, 'Quando parti os cinco pães para os cinco mil, quantos cestos cheios de pedaços levantastes? Responderam-lhe: Doze.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 20, 'E quando parti os sete para os quatro mil, quantas alcofas cheias de pedaços levantastes? Responderam-lhe: Sete.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 21, 'E ele lhes disse: Não entendeis ainda?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 22, 'Então chegaram a Betsaída. E trouxeram-lhe um cego, e rogaram-lhe que o tocasse.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 23, 'Jesus, pois, tomou o cego pela mão, e o levou para fora da aldeia; e cuspindo-lhe nos olhos, e impondo-lhe as mãos, perguntou-lhe: Vês alguma coisa?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 24, 'E, levantando ele os olhos, disse: Estou vendo os homens; porque como árvores os vejo andando.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 25, 'Então tornou a pôr-lhe as mãos sobre os olhos; e ele, olhando atentamente, ficou restabelecido, pois já via nitidamente todas as coisas.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 26, 'Depois o mandou para casa, dizendo: Mas não entres na aldeia.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 27, 'E saiu Jesus com os seus discípulos para as aldeias de Cesaréia de Filipe, e no caminho interrogou os discípulos, dizendo: Quem dizem os homens que eu sou?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 28, 'Responderam-lhe eles: Uns dizem: João, o Batista; outros: Elias; e ainda outros: Algum dos profetas.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 29, 'Então lhes perguntou: Mas vós, quem dizeis que eu sou? Respondendo, Pedro lhe disse: Tu és o Cristo.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 30, 'E ordenou-lhes Jesus que a ninguém dissessem aquilo a respeito dele.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 31, 'Começou então a ensinar-lhes que era necessário que o Filho do homem padecesse muitas coisas, que fosse rejeitado pelos anciãos e principais sacerdotes e pelos escribas, que fosse morto, e que depois de três dias ressurgisse.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 32, 'E isso dizia abertamente. Ao que Pedro, tomando-o à parte, começou a repreendê-lo.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 33, 'Mas ele, virando-se olhando para seus discípulos, repreendeu a Pedro, dizendo: Para trás de mim, Satanás; porque não cuidas das coisas que são de Deus, mas sim das que são dos homens.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 34, 'E chamando a si a multidão com os discípulos, disse-lhes: Se alguém quer vir após mim, negue-se a si mesmo, tome a sua cruz, e siga-me.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 35, 'Pois quem quiser salvar a sua vida, perdê-la-á; mas quem perder a sua vida por amor de mim e do evangelho, salvá-la-á.', 1, CURRENT_TIMESTAMP, false),
(41, 8, 36, 'Pois que aproveita ao homem ganhar o mundo inteiro e perder a sua vida?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 37, 'Ou que diria o homem em troca da sua vida?', 1, CURRENT_TIMESTAMP, false),
(41, 8, 38, 'Porquanto, qualquer que, entre esta geração adúltera e pecadora, se envergonhar de mim e das minhas palavras, também dele se envergonhará o Filho do homem quando vier na glória de seu Pai com os santos anjos.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 1, 'Disse-lhes mais: Em verdade vos digo que, dos que aqui estão, alguns há que de modo nenhum provarão a morte até que vejam o reino de Deus já chegando com poder.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 2, 'Seis dias depois tomou Jesus consigo a Pedro, a Tiago, e a João, e os levou à parte sós, a um alto monte; e foi transfigurado diante deles;', 1, CURRENT_TIMESTAMP, false),
(41, 9, 3, 'as suas vestes tornaram-se resplandecentes, extremamente brancas, tais como nenhum lavandeiro sobre a terra as poderia branquear.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 4, 'E apareceu-lhes Elias com Moisés, e falavam com Jesus.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 5, 'Pedro, tomando a palavra, disse a Jesus: Mestre, bom é estarmos aqui; façamos, pois, três cabanas, uma para ti, outra para Moisés, e outra para Elias.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 6, 'Pois não sabia o que havia de dizer, porque ficaram atemorizados.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 7, 'Nisto veio uma nuvem que os cobriu, e dela saiu uma voz que dizia: Este é o meu Filho amado; a ele ouvi.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 8, 'De repente, tendo olhado em redor, não viram mais a ninguém consigo, senão só a Jesus.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 9, 'Enquanto desciam do monte, ordenou-lhes que a ninguém contassem o que tinham visto, até que o Filho do homem ressurgisse dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 10, 'E eles guardaram o caso em segredo, indagando entre si o que seria o ressurgir dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 11, 'Então lhe perguntaram: Por que dizem os escribas que é necessário que Elias venha primeiro?', 1, CURRENT_TIMESTAMP, false),
(41, 9, 12, 'Respondeu-lhes Jesus: Na verdade Elias havia de vir primeiro, a restaurar todas as coisas; e como é que está escrito acerca do Filho do homem que ele deva padecer muito a ser aviltado?', 1, CURRENT_TIMESTAMP, false),
(41, 9, 13, 'Digo-vos, porém, que Elias já veio, e fizeram-lhe tudo quanto quiseram, como dele está escrito.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 14, 'Quando chegaram aonde estavam os discípulos, viram ao redor deles uma grande multidão, e alguns escribas a discutirem com eles.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 15, 'E logo toda a multidão, vendo a Jesus, ficou grandemente surpreendida; e correndo todos para ele, o saudavam.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 16, 'Perguntou ele aos escribas: Que é que discutis com eles?', 1, CURRENT_TIMESTAMP, false),
(41, 9, 17, 'Respondeu-lhe um dentre a multidão: Mestre, eu te trouxe meu filho, que tem um espírito mudo;', 1, CURRENT_TIMESTAMP, false),
(41, 9, 18, 'e este, onde quer que o apanha, convulsiona-o, de modo que ele espuma, range os dentes, e vai definhando; e eu pedi aos teus discípulos que o expulsassem, e não puderam.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 19, 'Ao que Jesus lhes respondeu: ó geração incrédula! até quando estarei convosco? até quando vos hei de suportar? Trazei-mo.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 20, 'Então lho trouxeram; e quando ele viu a Jesus, o espírito imediatamente o convulsionou; e o endemoninhado, caindo por terra, revolvia-se espumando.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 21, 'E perguntou Jesus ao pai dele: Há quanto tempo sucede-lhe isto? Respondeu ele: Desde a infância;', 1, CURRENT_TIMESTAMP, false),
(41, 9, 22, 'e muitas vezes o tem lançado no fogo, e na água, para o destruir; mas se podes fazer alguma coisa, tem compaixão de nós e ajuda-nos.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 23, 'Ao que lhe disse Jesus: Se podes!-tudo é possível ao que crê.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 24, 'Imediatamente o pai do menino, clamando, {com lágrimas} disse: Creio! Ajuda a minha incredulidade.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 25, 'E Jesus, vendo que a multidão, correndo, se aglomerava, repreendeu o espírito imundo, dizendo: Espírito mudo e surdo, eu te ordeno: Sai dele, e nunca mais entres nele.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 26, 'E ele, gritando, e agitando-o muito, saiu; e ficou o menino como morto, de modo que a maior parte dizia: Morreu.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 27, 'Mas Jesus, tomando-o pela mão, o ergueu; e ele ficou em pé.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 28, 'E quando entrou em casa, seus discípulos lhe perguntaram à parte: Por que não pudemos nós expulsá-lo?', 1, CURRENT_TIMESTAMP, false),
(41, 9, 29, 'Respondeu-lhes: Esta casta não sai de modo algum, salvo à força de oração {e jejum.}', 1, CURRENT_TIMESTAMP, false),
(41, 9, 30, 'Depois, tendo partido dali, passavam pela Galiléia, e ele não queria que ninguém o soubesse;', 1, CURRENT_TIMESTAMP, false),
(41, 9, 31, 'porque ensinava a seus discípulos, e lhes dizia: O Filho do homem será entregue nas mãos dos homens, que o matarão; e morto ele, depois de três dias ressurgirá.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 32, 'Mas eles não entendiam esta palavra, e temiam interrogá-lo.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 33, 'Chegaram a Cafarnaum. E estando ele em casa, perguntou-lhes: Que estáveis discutindo pelo caminho?', 1, CURRENT_TIMESTAMP, false),
(41, 9, 34, 'Mas eles se calaram, porque pelo caminho haviam discutido entre si qual deles era o maior.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 35, 'E ele, sentando-se, chamou os doze e lhes disse: se alguém quiser ser o primeiro, será o derradeiro de todos e o servo de todos.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 36, 'Então tomou uma criança, pô-la no meio deles e, abraçando-a, disse-lhes:', 1, CURRENT_TIMESTAMP, false),
(41, 9, 37, 'Qualquer que em meu nome receber uma destas crianças, a mim me recebe; e qualquer que me recebe a mim, recebe não a mim mas àquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 38, 'Disse-lhe João: Mestre, vimos um homem que em teu nome expulsava demônios, e nós lho proibimos, porque não nos seguia.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 39, 'Jesus, porém, respondeu: Não lho proibais; porque ninguém há que faça milagre em meu nome e possa logo depois falar mal de mim;', 1, CURRENT_TIMESTAMP, false),
(41, 9, 40, 'pois quem não é contra nós, é por nós.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 41, 'Porquanto qualquer que vos der a beber um copo de água em meu nome, porque sois de Cristo, em verdade vos digo que de modo algum perderá a sua recompensa.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 42, 'Mas qualquer que fizer tropeçar um destes pequeninos que crêem em mim, melhor lhe fora que se lhe pendurasse ao pescoço uma pedra de moinho, e que fosse lançado no mar.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 43, 'E se a tua mão te fizer tropeçar, corta-a; melhor é entrares na vida aleijado, do que, tendo duas mãos, ires para o inferno, para o fogo que nunca se apaga.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 44, '{onde o seu verme não morre, e o fogo não se apaga.}', 1, CURRENT_TIMESTAMP, false),
(41, 9, 45, 'Ou, se o teu pé te fizer tropeçar, corta-o; melhor é entrares coxo na vida, do que, tendo dois pés, seres lançado no inferno.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 46, '{onde o seu verme não morre, e o fogo não se apaga.}', 1, CURRENT_TIMESTAMP, false),
(41, 9, 47, 'Ou, se o teu olho te fizer tropeçar, lança-o fora; melhor é entrares no reino de Deus com um só olho, do que, tendo dois olhos, seres lançado no inferno.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 48, 'onde o seu verme não morre, e o fogo não se apaga.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 49, 'Porque cada um será salgado com fogo.', 1, CURRENT_TIMESTAMP, false),
(41, 9, 50, 'Bom é o sal; mas, se o sal se tornar insípido, com que o haveis de temperar? Tende sal em vós mesmos, e guardai a paz uns com os outros.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 1, 'Levantando-se Jesus, partiu dali para os termos da Judéia, e para além do Jordão; e do novo as multidões se reuniram em torno dele; e tornou a ensiná-las, como tinha por costume.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 2, 'Então se aproximaram dele alguns fariseus e, para o experimentarem, lhe perguntaram: É lícito ao homem repudiar sua mulher?', 1, CURRENT_TIMESTAMP, false),
(41, 10, 3, 'Ele, porém, respondeu-lhes: Que vos ordenou Moisés?', 1, CURRENT_TIMESTAMP, false),
(41, 10, 4, 'Replicaram eles: Moisés permitiu escrever carta de divórcio, e repudiar a mulher.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 5, 'Disse-lhes Jesus: Pela dureza dos vossos corações ele vos deixou escrito esse mandamento.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 6, 'Mas desde o princípio da criação, Deus os fez homem e mulher.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 7, 'Por isso deixará o homem a seu pai e a sua mãe, {e unir-se-á à sua mulher,}', 1, CURRENT_TIMESTAMP, false),
(41, 10, 8, 'e serão os dois uma só carne; assim já não são mais dois, mas uma só carne.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 9, 'Porquanto o que Deus ajuntou, não o separe o homem.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 10, 'Em casa os discípulos interrogaram-no de novo sobre isso.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 11, 'Ao que lhes respondeu: Qualquer que repudiar sua mulher e casar com outra comete adultério contra ela;', 1, CURRENT_TIMESTAMP, false),
(41, 10, 12, 'e se ela repudiar seu marido e casar com outro, comete adultério.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 13, 'Então lhe traziam algumas crianças para que as tocasse; mas os discípulos o repreenderam.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 14, 'Jesus, porém, vendo isto, indignou-se e disse-lhes: Deixai vir a mim as crianças, e não as impeçais, porque de tais é o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 15, 'Em verdade vos digo que qualquer que não receber o reino de Deus como criança, de maneira nenhuma entrará nele.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 16, 'E, tomando-as nos seus braços, as abençoou, pondo as mãos sobre elas.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 17, 'Ora, ao sair para se pôr a caminho, correu para ele um homem, o qual se ajoelhou diante dele e lhe perguntou: Bom Mestre, que hei de fazer para herdar a vida eterna?', 1, CURRENT_TIMESTAMP, false),
(41, 10, 18, 'Respondeu-lhe Jesus: Por que me chamas bom? ninguém é bom, senão um que é Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 19, 'Sabes os mandamentos: Não matarás; não adulterarás; não furtarás; não dirás falso testemunho; a ninguém defraudarás; honra a teu pai e a tua mãe.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 20, 'Ele, porém, lhe replicou: Mestre, tudo isso tenho guardado desde a minha juventude.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 21, 'E Jesus, olhando para ele, o amou e lhe disse: Uma coisa te falta; vai vende tudo quanto tens e dá-o aos pobres, e terás um tesouro no céu; e vem, segue-me.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 22, 'Mas ele, pesaroso desta palavra, retirou-se triste, porque possuía muitos bens.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 23, 'Então Jesus, olhando em redor, disse aos seus discípulos: Quão dificilmente entrarão no reino de Deus os que têm riquezas!', 1, CURRENT_TIMESTAMP, false),
(41, 10, 24, 'E os discípulos se maravilharam destas suas palavras; mas Jesus, tornando a falar, disse-lhes: Filhos, quão difícil é {para os que confiam nas riquezas} entrar no reino de Deus!', 1, CURRENT_TIMESTAMP, false),
(41, 10, 25, 'É mais fácil um camelo passar pelo fundo de uma agulha, do que entrar um rico no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 26, 'Com isso eles ficaram sobremaneira maravilhados, dizendo entre si: Quem pode, então, ser salvo?', 1, CURRENT_TIMESTAMP, false),
(41, 10, 27, 'Jesus, fixando os olhos neles, respondeu: Para os homens é impossível, mas não para Deus; porque para Deus tudo é possível.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 28, 'Pedro começou a dizer-lhe: Eis que nós deixamos tudo e te seguimos.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 29, 'Respondeu Jesus: Em verdade vos digo que ninguém há, que tenha deixado casa, ou irmãos, ou irmãs, ou mãe, ou pai, ou filhos, ou campos, por amor de mim e do evangelho,', 1, CURRENT_TIMESTAMP, false),
(41, 10, 30, 'que não receba cem vezes tanto, já neste tempo, em casas, e irmãos, e irmãs, e mães, e filhos, e campos, com perseguições; e no mundo vindouro a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 31, 'Mas muitos que são primeiros serão últimos; e muitos que são últimos serão primeiros.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 32, 'Ora, estavam a caminho, subindo para Jerusalém; e Jesus ia adiante deles, e eles se maravilhavam e o seguiam atemorizados. De novo tomou consigo os doze e começou a contar-lhes as coisas que lhe haviam de sobrevir,', 1, CURRENT_TIMESTAMP, false),
(41, 10, 33, 'dizendo: Eis que subimos a Jerusalém, e o Filho do homem será entregue aos principais sacerdotes e aos escribas; e eles o condenarão à morte, e o entregarão aos gentios;', 1, CURRENT_TIMESTAMP, false),
(41, 10, 34, 'e hão de escarnecê-lo e cuspir nele, e açoitá-lo, e matá-lo; e depois de três dias ressurgirá.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 35, 'Nisso aproximaram-se dele Tiago e João, filhos de Zebedeu, dizendo-lhe: Mestre, queremos que nos faças o que te pedirmos.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 36, 'Ele, pois, lhes perguntou: Que quereis que eu vos faça?', 1, CURRENT_TIMESTAMP, false),
(41, 10, 37, 'Responderam-lhe: Concede-nos que na tua glória nos sentemos, um à tua direita, e outro à tua esquerda.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 38, 'Mas Jesus lhes disse: Não sabeis o que pedis; podeis beber o cálice que eu bebo, e ser batizados no batismo em que eu sou batizado?', 1, CURRENT_TIMESTAMP, false),
(41, 10, 39, 'E lhe responderam: Podemos. Mas Jesus lhes disse: O cálice que eu bebo, haveis de bebê-lo, e no batismo em que eu sou batizado, haveis de ser batizados;', 1, CURRENT_TIMESTAMP, false),
(41, 10, 40, 'mas o sentar-se à minha direita, ou à minha esquerda, não me pertence concedê-lo; mas isso é para aqueles a quem está reservado.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 41, 'E ouvindo isso os dez, começaram a indignar-se contra Tiago e João.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 42, 'Então Jesus chamou-os para junto de si e lhes disse: Sabeis que os que são reconhecidos como governadores dos gentios, deles se assenhoreiam, e que sobre eles os seus grandes exercem autoridade.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 43, 'Mas entre vós não será assim; antes, qualquer que entre vós quiser tornar-se grande, será esse o que vos sirva;', 1, CURRENT_TIMESTAMP, false),
(41, 10, 44, 'e qualquer que entre vós quiser ser o primeiro, será servo de todos.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 45, 'Pois também o Filho do homem não veio para ser servido, mas para servir, e para dar a sua vida em resgate de muitos.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 46, 'Depois chegaram a Jericó. E, ao sair ele de Jericó com seus discípulos e uma grande multidão, estava sentado junto do caminho um mendigo cego, Bartimeu filho de Timeu.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 47, 'Este, quando ouviu que era Jesus, o nazareno, começou a clamar, dizendo: Jesus, Filho de Davi, tem compaixão de mim!', 1, CURRENT_TIMESTAMP, false),
(41, 10, 48, 'E muitos o repreendiam, para que se calasse; mas ele clamava ainda mais: Filho de Davi, tem compaixão de mim.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 49, 'Parou, pois, Jesus e disse: Chamai-o. E chamaram o cego, dizendo-lhe: Tem bom ânimo; levanta-te, ele te chama.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 50, 'Nisto, lançando de si a sua capa, de um salto se levantou e foi ter com Jesus.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 51, 'Perguntou-lhe o cego: Que queres que te faça? Respondeu-lhe o cego: Mestre, que eu veja.', 1, CURRENT_TIMESTAMP, false),
(41, 10, 52, 'Disse-lhe Jesus: Vai, a tua fé te salvou. E imediatamente recuperou a vista, e foi seguindo pelo caminho.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 1, 'Ora, quando se aproximavam de Jerusalém, de Betfagé e de Betânia, junto do Monte das Oliveiras, enviou Jesus dois dos seus discípulos', 1, CURRENT_TIMESTAMP, false),
(41, 11, 2, 'e disse-lhes: Ide à aldeia que está defronte de vós; e logo que nela entrardes, encontrareis preso um jumentinho, em que ainda ninguém montou; desprendei-o e trazei-o.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 3, 'E se alguém vos perguntar: Por que fazeis isso? respondei: O Senhor precisa dele, e logo tornará a enviá-lo para aqui.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 4, 'Foram, pois, e acharam o jumentinho preso ao portão do lado de fora na rua, e o desprenderam.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 5, 'E alguns dos que ali estavam lhes perguntaram: Que fazeis, desprendendo o jumentinho?', 1, CURRENT_TIMESTAMP, false),
(41, 11, 6, 'Responderam como Jesus lhes tinha mandado; e lho deixaram levar.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 7, 'Então trouxeram a Jesus o jumentinho e lançaram sobre ele os seus mantos; e Jesus montou nele.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 8, 'Muitos também estenderam pelo caminho os seus mantos, e outros, ramagens que tinham cortado nos campos.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 9, 'E tanto os que o precediam como os que o seguiam, clamavam: Hosana! bendito o que vem em nome do Senhor!', 1, CURRENT_TIMESTAMP, false),
(41, 11, 10, 'Bendito o reino que vem, o reino de nosso pai Davi! Hosana nas alturas!', 1, CURRENT_TIMESTAMP, false),
(41, 11, 11, 'Tendo Jesus entrado em Jerusalém, foi ao templo; e tendo observado tudo em redor, como já fosse tarde, saiu para Betânia com os doze.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 12, 'No dia seguinte, depois de saírem de Betânia teve fome,', 1, CURRENT_TIMESTAMP, false),
(41, 11, 13, 'e avistando de longe uma figueira que tinha folhas, foi ver se, porventura, acharia nela alguma coisa; e chegando a ela, nada achou senão folhas, porque não era tempo de figos.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 14, 'E Jesus, falando, disse à figueira: Nunca mais coma alguém fruto de ti. E seus discípulos ouviram isso.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 15, 'Chegaram, pois, a Jerusalém. E entrando ele no templo, começou a expulsar os que ali vendiam e compravam; e derribou as mesas dos cambistas, e as cadeiras dos que vendiam pombas;', 1, CURRENT_TIMESTAMP, false),
(41, 11, 16, 'e não consentia que ninguém atravessasse o templo levando qualquer utensílio;', 1, CURRENT_TIMESTAMP, false),
(41, 11, 17, 'e ensinava, dizendo-lhes: Não está escrito: A minha casa será chamada casa de oração para todas as nações? Vós, porém, a tendes feito covil de salteadores.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 18, 'Ora, os principais sacerdotes e os escribas ouviram isto, e procuravam um modo de o matar; pois o temiam, porque toda a multidão se maravilhava da sua doutrina.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 19, 'Ao cair da tarde, saíam da cidade.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 20, 'Quando passavam na manhã seguinte, viram que a figueira tinha secado desde as raízes.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 21, 'Então Pedro, lembrando-se, disse-lhe: Olha, Mestre, secou-se a figueira que amaldiçoaste.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 22, 'Respondeu-lhes Jesus: Tende fé em Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 23, 'Em verdade vos digo que qualquer que disser a este monte: Ergue-te e lança-te no mar; e não duvidar em seu coração, mas crer que se fará aquilo que diz, assim lhe será feito.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 24, 'Por isso vos digo que tudo o que pedirdes em oração, crede que o recebereis, e tê-lo-eis.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 25, 'Quando estiverdes orando, perdoai, se tendes alguma coisa contra alguém, para que também vosso Pai que está no céu, vos perdoe as vossas ofensas.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 26, '{Mas, se vós não perdoardes, também vosso Pai, que está no céu, não vos perdoará as vossas ofensas.}', 1, CURRENT_TIMESTAMP, false),
(41, 11, 27, 'Vieram de novo a Jerusalém. E andando Jesus pelo templo, aproximaram-se dele os principais sacerdotes, os escribas e os anciãos,', 1, CURRENT_TIMESTAMP, false),
(41, 11, 28, 'que lhe perguntaram: Com que autoridade fazes tu estas coisas? ou quem te deu autoridade para fazê-las?', 1, CURRENT_TIMESTAMP, false),
(41, 11, 29, 'Respondeu-lhes Jesus: Eu vos perguntarei uma coisa; respondei-me, pois, e eu vos direi com que autoridade faço estas coisas.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 30, 'O batismo de João era do céu, ou dos homens? respondei-me.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 31, 'Ao que eles arrazoavam entre si: Se dissermos: Do céu, ele dirá: Então por que não o crestes?', 1, CURRENT_TIMESTAMP, false),
(41, 11, 32, 'Mas diremos, porventura: Dos homens?-É que temiam o povo; porque todos verdadeiramente tinham a João como profeta.', 1, CURRENT_TIMESTAMP, false),
(41, 11, 33, 'Responderam, pois, a Jesus: Não sabemos. Replicou-lhes ele: Nem eu vos digo com que autoridade faço estas coisas.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 1, 'Então começou Jesus a falar-lhes por parábolas. Um homem plantou uma vinha, cercou-a com uma sebe, cavou um lagar, e edificou uma torre; depois arrendou-a a uns lavradores e ausentou-se do país.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 2, 'No tempo próprio, enviou um servo aos lavradores para que deles recebesse do fruto da vinha.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 3, 'Mas estes, apoderando-se dele, o espancaram e o mandaram embora de mãos vazias.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 4, 'E tornou a enviar-lhes outro servo; e a este feriram na cabeça e o ultrajaram.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 5, 'Então enviou ainda outro, e a este mataram; e a outros muitos, dos quais a uns espancaram e a outros mataram.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 6, 'Ora, tinha ele ainda um, o seu filho amado; a este lhes enviou por último, dizendo: A meu filho terão respeito.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 7, 'Mas aqueles lavradores disseram entre si: Este é o herdeiro; vinde, matemo-lo, e a herança será nossa.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 8, 'E, agarrando-o, o mataram, e o lançaram fora da vinha.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 9, 'Que fará, pois, o senhor da vinha? Virá e destruirá os lavradores, e dará a vinha a outros.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 10, 'Nunca lestes esta escritura: A pedra que os edificadores rejeitaram, essa foi posta como pedra angular;', 1, CURRENT_TIMESTAMP, false),
(41, 12, 11, 'pelo Senhor foi feito isso, e é maravilhoso aos nossos olhos?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 12, 'Procuravam então prendê-lo, mas temeram a multidão, pois perceberam que contra eles proferira essa parábola; e, deixando-o, se retiraram.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 13, 'Enviaram-lhe então alguns dos fariseus e dos herodianos, para que o apanhassem em alguma palavra.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 14, 'Aproximando-se, pois, disseram-lhe: Mestre, sabemos que és verdadeiro, e de ninguém se te dá; porque não olhas à aparência dos homens, mas ensinas segundo a verdade o caminho de Deus; é lícito dar tributo a César, ou não? Daremos, ou não daremos?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 15, 'Mas Jesus, percebendo a hipocrisia deles, respondeu-lhes: Por que me experimentais? trazei-me um denário para que eu o veja.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 16, 'E eles lho trouxeram. Perguntou-lhes Jesus: De quem é esta imagem e inscrição? Responderam-lhe: De César.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 17, 'Disse-lhes Jesus: Dai, pois, a César o que é de César, e a Deus o que é de Deus. E admiravam-se dele.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 18, 'Então se aproximaram dele alguns dos saduceus, que dizem não haver ressurreição, e lhe perguntaram, dizendo:', 1, CURRENT_TIMESTAMP, false),
(41, 12, 19, 'Mestre, Moisés nos deixou escrito que se morrer alguém, deixando mulher sem deixar filhos, o irmão dele case com a mulher, e suscite descendência ao irmão.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 20, 'Ora, havia sete irmãos; o primeiro casou-se e morreu sem deixar descendência;', 1, CURRENT_TIMESTAMP, false),
(41, 12, 21, 'o segundo casou-se com a viúva, e morreu, não deixando descendência; e da mesma forma, o terceiro; e assim os sete, e não deixaram descendência.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 22, 'Depois de todos, morreu também a mulher.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 23, 'Na ressurreição, de qual deles será ela esposa, pois os sete por esposa a tiveram?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 24, 'Respondeu-lhes Jesus: Porventura não errais vós em razão de não compreenderdes as Escrituras nem o poder de Deus?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 25, 'Porquanto, ao ressuscitarem dos mortos, nem se casam, nem se dão em casamento; pelo contrário, são como os anjos nos céus.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 26, 'Quanto aos mortos, porém, serem ressuscitados, não lestes no livro de Moisés, onde se fala da sarça, como Deus lhe disse: Eu sou o Deus de Abraão, o Deus de Isaque e o Deus de Jacó?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 27, 'Ora, ele não é Deus de mortos, mas de vivos. Estais em grande erro.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 28, 'Aproximou-se dele um dos escribas que os ouvira discutir e, percebendo que lhes havia respondido bem, perguntou-lhe: Qual é o primeiro de todos os mandamentos?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 29, 'Respondeu Jesus: O primeiro é: Ouve, Israel, o Senhor nosso Deus é o único Senhor.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 30, 'Amarás, pois, ao Senhor teu Deus de todo o teu coração, de toda a tua alma, de todo o teu entendimento e de todas as tuas forças.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 31, 'E o segundo é este: Amarás ao teu próximo como a ti mesmo. Não há outro mandamento maior do que esses.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 32, 'Ao que lhe disse o escriba: Muito bem, Mestre; com verdade disseste que ele é um, e fora dele não há outro;', 1, CURRENT_TIMESTAMP, false),
(41, 12, 33, 'e que amá-lo de todo o coração, de todo o entendimento e de todas as forças, e amar o próximo como a si mesmo, é mais do que todos os holocaustos e sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 34, 'E Jesus, vendo que havia respondido sabiamente, disse-lhe: Não estás longe do reino de Deus. E ninguém ousava mais interrogá-lo.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 35, 'Por sua vez, Jesus, enquanto ensinava no templo, perguntou: Como é que os escribas dizem que o Cristo é filho de Davi?', 1, CURRENT_TIMESTAMP, false),
(41, 12, 36, 'O próprio Davi falou, movido pelo Espírito Santo: Disse o Senhor ao meu Senhor: Assenta-te à minha direita, até que eu ponha os teus inimigos debaixo dos teus pés.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 37, 'Davi mesmo lhe chama Senhor; como é ele seu filho? E a grande multidão o ouvia com prazer.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 38, 'E prosseguindo ele no seu ensino, disse: Guardai-vos dos escribas, que gostam de andar com vestes compridas, e das saudações nas praças,', 1, CURRENT_TIMESTAMP, false),
(41, 12, 39, 'e dos primeiros assentos nas sinagogas, e dos primeiros lugares nos banquetes,', 1, CURRENT_TIMESTAMP, false),
(41, 12, 40, 'que devoram as casas das viúvas, e por pretexto fazem longas orações; estes hão de receber muito maior condenação.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 41, 'E sentando-se Jesus defronte do cofre das ofertas, observava como a multidão lançava dinheiro no cofre; e muitos ricos deitavam muito.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 42, 'Vindo, porém, uma pobre viúva, lançou dois leptos, que valiam um quadrante.', 1, CURRENT_TIMESTAMP, false),
(41, 12, 43, 'E chamando ele os seus discípulos, disse-lhes: Em verdade vos digo que esta pobre viúva deu mais do que todos os que deitavam ofertas no cofre;', 1, CURRENT_TIMESTAMP, false),
(41, 12, 44, 'porque todos deram daquilo que lhes sobrava; mas esta, da sua pobreza, deu tudo o que tinha, mesmo todo o seu sustento.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 1, 'Quando saía do templo, disse-lhe um dos seus discípulos: Mestre, olha que pedras e que edifícios!', 1, CURRENT_TIMESTAMP, false),
(41, 13, 2, 'Ao que Jesus lhe disse: Vês estes grandes edifícios? Não se deixará aqui pedra sobre pedra que não seja derribada.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 3, 'Depois estando ele sentado no Monte das Oliveiras, defronte do templo, Pedro, Tiago, João e André perguntaram-lhe em particular:', 1, CURRENT_TIMESTAMP, false),
(41, 13, 4, 'Dize-nos, quando sucederão essas coisas, e que sinal haverá quando todas elas estiverem para se cumprir?', 1, CURRENT_TIMESTAMP, false),
(41, 13, 5, 'Então Jesus começou a dizer-lhes: Acautelai-vos; ninguém vos engane;', 1, CURRENT_TIMESTAMP, false),
(41, 13, 6, 'muitos virão em meu nome, dizendo: Sou eu; e a muitos enganarão.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 7, 'Quando, porém, ouvirdes falar em guerras e rumores de guerras, não vos perturbeis; forçoso é que assim aconteça: mas ainda não é o fim.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 8, 'Pois se levantará nação contra nação, e reino contra reino; e haverá terremotos em diversos lugares, e haverá fomes. Isso será o princípio das dores.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 9, 'Mas olhai por vós mesmos; pois por minha causa vos hão de entregar aos sinédrios e às sinagogas, e sereis açoitados; também sereis levados perante governadores e reis, para lhes servir de testemunho.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 10, 'Mas importa que primeiro o evangelho seja pregado entre todas as nações.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 11, 'Quando, pois, vos conduzirem para vos entregar, não vos preocupeis com o que haveis de dizer; mas, o que vos for dado naquela hora, isso falai; porque não sois vós que falais, mas sim o Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 12, 'Um irmão entregará à morte a seu irmão, e um pai a seu filho; e filhos se levantarão contra os pais e os matarão.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 13, 'E sereis odiados de todos por causa do meu nome; mas aquele que perseverar até o fim, esse será salvo.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 14, 'Ora, quando vós virdes a abominação da desolação estar onde não deve estar {quem lê, entenda}, então os que estiverem na Judéia fujam para os montes;', 1, CURRENT_TIMESTAMP, false),
(41, 13, 15, 'quem estiver no eirado não desça, nem entre para tirar alguma coisa da sua casa;', 1, CURRENT_TIMESTAMP, false),
(41, 13, 16, 'e quem estiver no campo não volte atrás para buscar a sua capa.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 17, 'Mas ai das que estiverem grávidas, e das que amamentarem naqueles dias!', 1, CURRENT_TIMESTAMP, false),
(41, 13, 18, 'Orai, pois, para que isto não suceda no inverno;', 1, CURRENT_TIMESTAMP, false),
(41, 13, 19, 'porque naqueles dias haverá uma tribulação tal, qual nunca houve desde o princípio da criação, que Deus criou, até agora, nem jamais haverá.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 20, 'Se o Senhor não abreviasse aqueles dias, ninguém se salvaria mas ele, por causa dos eleitos que escolheu, abreviou aqueles dias.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 21, 'Então, se alguém vos disser: Eis aqui o Cristo! ou: Ei-lo ali! não acrediteis.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 22, 'Porque hão de surgir falsos cristos e falsos profetas, e farão sinais e prodígios para enganar, se possível, até os escolhidos.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 23, 'Ficai vós, pois, de sobreaviso; eis que de antemão vos tenho dito tudo.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 24, 'Mas naqueles dias, depois daquela tribulação, o sol escurecerá, e a lua não dará a sua luz;', 1, CURRENT_TIMESTAMP, false),
(41, 13, 25, 'as estrelas cairão do céu, e os poderes que estão nos céus, serão abalados.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 26, 'Então verão vir o Filho do homem nas nuvens, com grande poder e glória.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 27, 'E logo enviará os seus anjos, e ajuntará os seus eleitos, desde os quatro ventos, desde a extremidade da terra até a extremidade do céu.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 28, 'Da figueira, pois, aprendei a parábola: Quando já o seu ramo se torna tenro e brota folhas, sabeis que está próximo o verão.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 29, 'Assim também vós, quando virdes sucederem essas coisas, sabei que ele está próximo, mesmo às portas.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 30, 'Em verdade vos digo que não passará esta geração, até que todas essas coisas aconteçam.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 31, 'Passará o céu e a terra, mas as minhas palavras não passarão.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 32, 'Quanto, porém, ao dia e à hora, ninguém sabe, nem os anjos no céu nem o Filho, senão o Pai.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 33, 'Olhai! vigiai! porque não sabeis quando chegará o tempo.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 34, 'É como se um homem, devendo viajar, ao deixar a sua casa, desse autoridade aos seus servos, a cada um o seu trabalho, e ordenasse também ao porteiro que vigiasse.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 35, 'Vigiai, pois; porque não sabeis quando virá o senhor da casa; se à tarde, se à meia-noite, se ao cantar do galo, se pela manhã;', 1, CURRENT_TIMESTAMP, false),
(41, 13, 36, 'para que, vindo de improviso, não vos ache dormindo.', 1, CURRENT_TIMESTAMP, false),
(41, 13, 37, 'O que vos digo a vós, a todos o digo: Vigiai.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 1, 'Ora, dali a dois dias era a páscoa e a festa dos pães ázimos; e os principais sacerdotes e os escribas andavam buscando como prender Jesus a traição, para o matarem.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 2, 'Pois eles diziam: Não durante a festa, para que não haja tumulto entre o povo.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 3, 'Estando ele em Betânia, reclinado à mesa em casa de Simão, o leproso, veio uma mulher que trazia um vaso de alabastro cheio de bálsamo de nardo puro, de grande preço; e, quebrando o vaso, derramou-lhe sobre a cabeça o bálsamo.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 4, 'Mas alguns houve que em si mesmos se indignaram e disseram: Para que se fez este desperdício do bálsamo?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 5, 'Pois podia ser vendido por mais de trezentos denários que se dariam aos pobres. E bramavam contra ela.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 6, 'Jesus, porém, disse: Deixai-a; por que a molestais? Ela praticou uma boa ação para comigo.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 7, 'Porquanto os pobres sempre os tendes convosco e, quando quiserdes, podeis fazer-lhes bem; a mim, porém, nem sempre me tendes.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 8, 'ela fez o que pode; antecipou-se a ungir o meu corpo para a sepultura.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 9, 'Em verdade vos digo que, em todo o mundo, onde quer que for pregado o evangelho, também o que ela fez será contado para memória sua.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 10, 'Então Judas Iscariotes, um dos doze, foi ter com os principais sacerdotes para lhes entregar Jesus.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 11, 'Ouvindo-o eles, alegraram-se, e prometeram dar-lhe dinheiro. E buscava como o entregaria em ocasião oportuna.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 12, 'Ora, no primeiro dia dos pães ázimos, quando imolavam a páscoa, disseram-lhe seus discípulos: Aonde queres que vamos fazer os preparativos para comeres a páscoa?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 13, 'Enviou, pois, dois dos seus discípulos, e disse-lhes: Ide à cidade, e vos sairá ao encontro um homem levando um cântaro de água; seguí-o;', 1, CURRENT_TIMESTAMP, false),
(41, 14, 14, 'e, onde ele entrar, dizei ao dono da casa: O Mestre manda perguntar: Onde está o meu aposento em que hei de comer a páscoa com os meus discípulos?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 15, 'E ele vos mostrará um grande cenáculo mobiliado e pronto; aí fazei-nos os preparativos.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 16, 'Partindo, pois, os discípulos, foram à cidade, onde acharam tudo como ele lhes dissera, e prepararam a páscoa.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 17, 'Ao anoitecer chegou ele com os doze.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 18, 'E, quando estavam reclinados à mesa e comiam, disse Jesus: Em verdade vos digo que um de vós, que comigo come, há de trair-me.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 19, 'Ao que eles começaram a entristecer-se e a perguntar-lhe um após outro: Porventura sou eu?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 20, 'Respondeu-lhes: É um dos doze, que mete comigo a mão no prato.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 21, 'Pois o Filho do homem vai, conforme está escrito a seu respeito; mas ai daquele por quem o Filho do homem é traído! bom seria para esse homem se não houvera nascido.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 22, 'Enquanto comiam, Jesus tomou pão e, abençoando-o, o partiu e deu-lho, dizendo: Tomai; isto é o meu corpo.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 23, 'E tomando um cálice, rendeu graças e deu-lho; e todos beberam dele.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 24, 'E disse-lhes: Isto é o meu sangue, o sangue do pacto, que por muitos é derramado.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 25, 'Em verdade vos digo que não beberei mais do fruto da videira, até aquele dia em que o beber, novo, no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 26, 'E, tendo cantado um hino, saíram para o Monte das Oliveiras.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 27, 'Disse-lhes então Jesus: Todos vós vos escandalizareis; porque escrito está: Ferirei o pastor, e as ovelhas se dispersarão.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 28, 'Todavia, depois que eu ressurgir, irei adiante de vós para a Galiléia.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 29, 'Ao que Pedro lhe disse: Ainda que todos se escandalizem, nunca, porém, eu.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 30, 'Replicou-lhe Jesus: Em verdade te digo que hoje, nesta noite, antes que o galo cante duas vezes, três vezes tu me negarás.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 31, 'Mas ele repetia com veemência: Ainda que me seja necessário morrer contigo, de modo nenhum te negarei. Assim também diziam todos.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 32, 'Então chegaram a um lugar chamado Getsêmani, e disse Jesus a seus discípulos: Sentai-vos aqui, enquanto eu oro.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 33, 'E levou consigo a Pedro, a Tiago e a João, e começou a ter pavor e a angustiar-se;', 1, CURRENT_TIMESTAMP, false),
(41, 14, 34, 'e disse-lhes: A minha alma está triste até a morte; ficai aqui e vigiai.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 35, 'E adiantando-se um pouco, prostrou-se em terra; e orava para que, se fosse possível, passasse dele aquela hora.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 36, 'E dizia: Aba, Pai, tudo te é possível; afasta de mim este cálice; todavia não seja o que eu quero, mas o que tu queres.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 37, 'Voltando, achou-os dormindo; e disse a Pedro: Simão, dormes? não pudeste vigiar uma hora?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 38, 'Vigiai e orai, para que não entreis em tentação; o espírito, na verdade, está pronto, mas a carne é fraca.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 39, 'Retirou-se de novo e orou, dizendo as mesmas palavras.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 40, 'E voltando outra vez, achou-os dormindo, porque seus olhos estavam carregados; e não sabiam o que lhe responder.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 41, 'Ao voltar pela terceira vez, disse-lhes: Dormi agora e descansai.-Basta; é chegada a hora. Eis que o Filho do homem está sendo entregue nas mãos dos pecadores.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 42, 'Levantai-vos, vamo-nos; eis que é chegado aquele que me trai.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 43, 'E logo, enquanto ele ainda falava, chegou Judas, um dos doze, e com ele uma multidão com espadas e varapaus, vinda da parte dos principais sacerdotes, dos escribas e dos anciãos.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 44, 'Ora, o que o traía lhes havia dado um sinal, dizendo: Aquele que eu beijar, esse é; prendei-o e levai-o com segurança.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 45, 'E, logo que chegou, aproximando-se de Jesus, disse: Rabi! E o beijou.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 46, 'Ao que eles lhes lançaram as mãos, e o prenderam.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 47, 'Mas um dos que ali estavam, puxando da espada, feriu o servo do sumo sacerdote e cortou-lhe uma orelha.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 48, 'Disse-lhes Jesus: Saístes com espadas e varapaus para me prender, como a um salteador?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 49, 'Todos os dias estava convosco no templo, a ensinar, e não me prendestes; mas isto é para que se cumpram as Escrituras.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 50, 'Nisto, todos o deixaram e fugiram.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 51, 'Ora, seguia-o certo jovem envolto em um lençol sobre o corpo nu; e o agarraram.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 52, 'Mas ele, largando o lençol, fugiu despido.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 53, 'Levaram Jesus ao sumo sacerdote, e ajuntaram-se todos os principais sacerdotes, os anciãos e os escribas.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 54, 'E Pedro o seguiu de longe até dentro do pátio do sumo sacerdote, e estava sentado com os guardas, aquentando-se ao fogo.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 55, 'Os principais sacerdotes testemunho contra Jesus para o matar, e não o achavam.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 56, 'Porque contra ele muitos depunham falsamente, mas os testemunhos não concordavam.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 57, 'Levantaram-se por fim alguns que depunham falsamente contra ele, dizendo:', 1, CURRENT_TIMESTAMP, false),
(41, 14, 58, 'Nós o ouvimos dizer: Eu destruirei este santuário, construído por mãos de homens, e em três dias edificarei outro, não feito por mãos de homens.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 59, 'E nem assim concordava o seu testemunho.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 60, 'Levantou-se então o sumo sacerdote no meio e perguntou a Jesus: Não respondes coisa alguma? Que é que estes depõem conta ti?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 61, 'Ele, porém, permaneceu calado, e nada respondeu. Tornou o sumo sacerdote a interrogá-lo, perguntando-lhe: És tu o Cristo, o Filho do Deus bendito?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 62, 'Respondeu Jesus: Eu o sou; e vereis o Filho do homem assentado à direita do Poder e vindo com as nuvens do céu.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 63, 'Então o sumo sacerdote, rasgando as suas vestes, disse: Para que precisamos ainda de testemunhas?', 1, CURRENT_TIMESTAMP, false),
(41, 14, 64, 'Acabais de ouvir a blasfêmia; que vos parece? E todos o condenaram como réu de morte.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 65, 'E alguns começaram a cuspir nele, e a cobrir-lhe o rosto, e a dar-lhe socos, e a dizer-lhe: Profetiza. E os guardas receberam-no a bofetadas.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 66, 'Ora, estando Pedro em baixo, no átrio, chegou uma das criadas do sumo sacerdote', 1, CURRENT_TIMESTAMP, false),
(41, 14, 67, 'e, vendo a Pedro, que se estava aquentando, encarou-o e disse: Tu também estavas com o nazareno, esse Jesus.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 68, 'Mas ele o negou, dizendo: Não sei nem compreendo o que dizes. E saiu para o alpendre.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 69, 'E a criada, vendo-o, começou de novo a dizer aos que ali estavam: Esse é um deles.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 70, 'Mas ele o negou outra vez. E pouco depois os que ali estavam disseram novamente a Pedro: Certamente tu és um deles; pois és também galileu.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 71, 'Ele, porém, começou a praguejar e a jurar: Não conheço esse homem de quem falais.', 1, CURRENT_TIMESTAMP, false),
(41, 14, 72, 'Nesse instante o galo cantou pela segunda vez. E Pedro lembrou-se da palavra que lhe dissera Jesus: Antes que o galo cante duas vezes, três vezes me negarás. E caindo em si, começou a chorar.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 1, 'Logo de manhã tiveram conselho os principais sacerdotes com os anciãos, os escribas e todo o sinédrio; e maniatando a Jesus, o levaram e o entregaram a Pilatos.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 2, 'Pilatos lhe perguntou: És tu o rei dos judeus? Respondeu-lhe Jesus: É como dizes.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 3, 'e os principais dos sacerdotes o acusavam de muitas coisas.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 4, 'Tornou Pilatos a interrogá-lo, dizendo: Não respondes nada? Vê quantas acusações te fazem.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 5, 'Mas Jesus nada mais respondeu, de maneira que Pilatos se admirava.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 6, 'Ora, por ocasião da festa costumava soltar-lhes um preso qualquer que eles pedissem.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 7, 'E havia um, chamado Barrabás, preso com outros sediciosos, os quais num motim haviam cometido um homicídio.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 8, 'E a multidão subiu e começou a pedir o que lhe costumava fazer.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 9, 'Ao que Pilatos lhes perguntou: Quereis que vos solte o rei dos judeus?', 1, CURRENT_TIMESTAMP, false),
(41, 15, 10, 'Pois ele sabia que por inveja os principais sacerdotes lho haviam entregado.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 11, 'Mas os principais sacerdotes incitaram a multidão a pedir que lhes soltasse antes a Barrabás.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 12, 'E Pilatos, tornando a falar, perguntou-lhes: Que farei então daquele a quem chamais reis dos judeus?', 1, CURRENT_TIMESTAMP, false),
(41, 15, 13, 'Novamente clamaram eles: Crucifica-o!', 1, CURRENT_TIMESTAMP, false),
(41, 15, 14, 'Disse-lhes Pilatos: Mas que mal fez ele? Ao que eles clamaram ainda mais: Crucifica-o!', 1, CURRENT_TIMESTAMP, false),
(41, 15, 15, 'Então Pilatos, querendo satisfazer a multidão, soltou-lhe Barrabás; e tendo mandado açoitar a Jesus, o entregou para ser crucificado.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 16, 'Os soldados, pois, levaram-no para dentro, ao pátio, que é o pretório, e convocaram toda a corte;', 1, CURRENT_TIMESTAMP, false),
(41, 15, 17, 'vestiram-no de púrpura e puseram-lhe na cabeça uma coroa de espinhos que haviam tecido;', 1, CURRENT_TIMESTAMP, false),
(41, 15, 18, 'e começaram a saudá-lo: Salve, rei dos judeus!', 1, CURRENT_TIMESTAMP, false),
(41, 15, 19, 'Davam-lhe com uma cana na cabeça, cuspiam nele e, postos de joelhos, o adoravam.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 20, 'Depois de o terem assim escarnecido, despiram-lhe a púrpura, e lhe puseram as vestes. Então o levaram para fora, a fim de o crucificarem.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 21, 'E obrigaram certo Simão, cireneu, pai de Alexandre e de Rufo, que por ali passava, vindo do campo, a carregar-lhe a cruz.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 22, 'Levaram-no, pois, ao lugar do Gólgota, que quer dizer, lugar da Caveira.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 23, 'E ofereciam-lhe vinho misturado com mirra; mas ele não o tomou.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 24, 'Então o crucificaram, e repartiram entre si as vestes dele, lançando sortes sobre elas para ver o que cada um levaria.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 25, 'E era a hora terceira quando o crucificaram.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 26, 'Por cima dele estava escrito o título da sua acusação: O REI DOS JUDEUS.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 27, 'Também, com ele, crucificaram dois salteadores, um à sua direita, e outro à esquerda.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 28, '{E cumpriu-se a escritura que diz: E com os malfeitores foi contado.}', 1, CURRENT_TIMESTAMP, false),
(41, 15, 29, 'E os que iam passando blasfemavam dele, meneando a cabeça e dizendo: Ah! tu que destróis o santuário e em três dias o reedificas.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 30, 'salva-te a ti mesmo, descendo da cruz.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 31, 'De igual modo também os principais sacerdotes, com os escribas, escarnecendo-o, diziam entre si: A outros salvou; a si mesmo não pode salvar;', 1, CURRENT_TIMESTAMP, false),
(41, 15, 32, 'desça agora da cruz o Cristo, o rei de Israel, para que vejamos e creiamos, Também os que com ele foram crucificados o injuriavam.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 33, 'E, chegada a hora sexta, houve trevas sobre a terra, até a hora nona.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 34, 'E, à hora nona, bradou Jesus em alta voz: Eloí, Eloí, lamá, sabactani? que, traduzido, é: Deus meu, Deus meu, por que me desamparaste?', 1, CURRENT_TIMESTAMP, false),
(41, 15, 35, 'Alguns dos que ali estavam, ouvindo isso, diziam: Eis que chama por Elias.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 36, 'Correu um deles, ensopou uma esponja em vinagre e, pondo-a numa cana, dava-lhe de beber, dizendo: Deixai, vejamos se Elias virá tirá-lo.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 37, 'Mas Jesus, dando um grande brado, expirou.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 38, 'Então o véu do santuário se rasgou em dois, de alto a baixo.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 39, 'Ora, o centurião, que estava defronte dele, vendo-o assim expirar, disse: Verdadeiramente este homem era filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 40, 'Também ali estavam algumas mulheres olhando de longe, entre elas Maria Madalena, Maria, mãe de Tiago o Menor e de José, e Salomé;', 1, CURRENT_TIMESTAMP, false),
(41, 15, 41, 'as quais o seguiam e o serviam quando ele estava na Galiléia; e muitas outras que tinham subido com ele a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 42, 'Ao cair da tarde, como era o dia da preparação, isto é, a véspera do sábado,', 1, CURRENT_TIMESTAMP, false),
(41, 15, 43, 'José de Arimatéia, ilustre membro do sinédrio, que também esperava o reino de Deus, cobrando ânimo foi Pilatos e pediu o corpo de Jesus.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 44, 'Admirou-se Pilatos de que já tivesse morrido; e chamando o centurião, perguntou-lhe se, de fato, havia morrido.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 45, 'E, depois que o soube do centurião, cedeu o cadáver a José;', 1, CURRENT_TIMESTAMP, false),
(41, 15, 46, 'o qual, tendo comprado um pano de linho, tirou da cruz o corpo, envolveu-o no pano e o depositou num sepulcro aberto em rocha; e rolou uma pedra para a porta do sepulcro.', 1, CURRENT_TIMESTAMP, false),
(41, 15, 47, 'E Maria Madalena e Maria, mãe de José, observavam onde fora posto.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 1, 'Ora, passado o sábado, Maria Madalena, Maria, mãe de Tiago, e Salomé, compraram aromas para irem ungi-lo.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 2, 'E, no primeiro dia da semana, foram ao sepulcro muito cedo, ao levantar do sol.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 3, 'E diziam umas às outras: Quem nos revolverá a pedra da porta do sepulcro?', 1, CURRENT_TIMESTAMP, false),
(41, 16, 4, 'Mas, levantando os olhos, notaram que a pedra, que era muito grande, já estava revolvida;', 1, CURRENT_TIMESTAMP, false),
(41, 16, 5, 'e entrando no sepulcro, viram um moço sentado à direita, vestido de alvo manto; e ficaram atemorizadas.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 6, 'Ele, porém, lhes disse: Não vos atemorizeis; buscais a Jesus, o nazareno, que foi crucificado; ele ressurgiu; não está aqui; eis o lugar onde o puseram.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 7, 'Mas ide, dizei a seus discípulos, e a Pedro, que ele vai adiante de vós para a Galiléia; ali o vereis, como ele vos disse.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 8, 'E, saindo elas, fugiram do sepulcro, porque estavam possuídas de medo e assombro; e não disseram nada a ninguém, porque temiam.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 9, 'Ora, havendo Jesus ressurgido cedo no primeiro dia da semana, apareceu primeiramente a Maria Madalena, da qual tinha expulsado sete demônios.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 10, 'Foi ela anunciá-lo aos que haviam andado com ele, os quais estavam tristes e chorando;', 1, CURRENT_TIMESTAMP, false),
(41, 16, 11, 'e ouvindo eles que vivia, e que tinha sido visto por ela, não o creram.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 12, 'Depois disso manifestou-se sob outra forma a dois deles que iam de caminho para o campo,', 1, CURRENT_TIMESTAMP, false),
(41, 16, 13, 'os quais foram anunciá-lo aos outros; mas nem a estes deram crédito.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 14, 'Por último, então, apareceu aos onze, estando eles reclinados à mesa, e lançou-lhes em rosto a sua incredulidade e dureza de coração, por não haverem dado crédito aos que o tinham visto já ressurgido.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 15, 'E disse-lhes: Ide por todo o mundo, e pregai o evangelho a toda criatura.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 16, 'Quem crer e for batizado será salvo; mas quem não crer será condenado.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 17, 'E estes sinais acompanharão aos que crerem: em meu nome expulsarão demônios; falarão novas línguas;', 1, CURRENT_TIMESTAMP, false),
(41, 16, 18, 'pegarão em serpentes; e se beberem alguma coisa mortífera, não lhes fará dano algum; e porão as mãos sobre os enfermos, e estes serão curados.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 19, 'Ora, o Senhor, depois de lhes ter falado, foi recebido no céu, e assentou-se à direita de Deus.', 1, CURRENT_TIMESTAMP, false),
(41, 16, 20, 'Eles, pois, saindo, pregaram por toda parte, cooperando com eles o Senhor, e confirmando a palavra com os sinais que os acompanhavam.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 1, 'Livro da genealogia de Jesus Cristo, filho de Davi, filho de Abraão.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 2, 'A Abraão nasceu Isaque; a Isaque nasceu Jacó; a Jacó nasceram Judá e seus irmãos;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 3, 'a Judá nasceram, de Tamar, Farés e Zará; a Farés nasceu Esrom; a Esrom nasceu Arão;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 4, 'a Arão nasceu Aminadabe; a Aminadabe nasceu Nasom; a Nasom nasceu Salmom;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 5, 'a Salmom nasceu, de Raabe, Booz; a Booz nasceu, de Rute, Obede; a Obede nasceu Jessé;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 6, 'e a Jessé nasceu o rei Davi. A Davi nasceu Salomão da que fora mulher de Urias;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 7, 'a Salomão nasceu Roboão; a Roboão nasceu Abias; a nasceu Abias nasceu Asafe;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 8, 'a Asafe nasceu Josafá; a Josafá nasceu Jorão; a Jorão Ozias;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 9, 'a Ozias nasceu Joatão; a Joatão nasceu Acaz; a Acaz nasceu Ezequias;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 10, 'a Ezequias nasceu Manassés; a Manassés nasceu Amom; a Amom nasceu Josias;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 11, 'a Josias nasceram Jeconias e seus irmãos, no tempo da deportação para Babilônia.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 12, 'Depois da deportação para Babilônia nasceu a Jeconias, Salatiel; a Salatiel nasceu Zorobabel;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 13, 'a Zorobabel nasceu Abiúde; a Abiúde nasceu Eliaquim; a Eliaquim nasceu Azor;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 14, 'a Azor nasceu Sadoque; a Sadoque nasceu Aquim; a Aquim nasceu Eliúde;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 15, 'a Eliúde nasceu Eleazar; a Eleazar nasceu Matã; a Matã nasceu Jacó;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 16, 'e a Jacó nasceu José, marido de Maria, da qual nasceu JESUS, que se chama Cristo.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 17, 'De sorte que todas as gerações, desde Abraão até Davi, são catorze gerações; e desde Davi até a deportação para Babilônia, catorze gerações; e desde a deportação para Babilônia até o Cristo, catorze gerações.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 18, 'Ora, o nascimento de Jesus Cristo foi assim: Estando Maria, sua mãe, desposada com José, antes de se ajuntarem, ela se achou ter concebido do Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 19, 'E como José, seu esposo, era justo, e não a queria infamar, intentou deixá-la secretamente.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 20, 'E, projetando ele isso, eis que em sonho lhe apareceu um anjo do Senhor, dizendo: José, filho de Davi, não temas receber a Maria, tua mulher, pois o que nela se gerou é do Espírito Santo;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 21, 'ela dará à luz um filho, a quem chamarás JESUS; porque ele salvará o seu povo dos seus pecados.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 22, 'Ora, tudo isso aconteceu para que se cumprisse o que fora dito da parte do Senhor pelo profeta:', 1, CURRENT_TIMESTAMP, false),
(40, 1, 23, 'Eis que a virgem conceberá e dará à luz um filho, o qual será chamado EMANUEL, que traduzido é: Deus conosco.', 1, CURRENT_TIMESTAMP, false),
(40, 1, 24, 'E José, tendo despertado do sono, fez como o anjo do Senhor lhe ordenara, e recebeu sua mulher;', 1, CURRENT_TIMESTAMP, false),
(40, 1, 25, 'e não a conheceu enquanto ela não deu à luz um filho; e pôs-lhe o nome de JESUS.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 1, 'Tendo, pois, nascido Jesus em Belém da Judéia, no tempo do rei Herodes, eis que vieram do oriente a Jerusalém uns magos que perguntavam:', 1, CURRENT_TIMESTAMP, false),
(40, 2, 2, 'Onde está aquele que é nascido rei dos judeus? pois do oriente vimos a sua estrela e viemos adorá-lo.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 3, 'O rei Herodes, ouvindo isso, perturbou-se, e com ele toda a Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(40, 2, 4, 'e, reunindo todos os principais sacerdotes e os escribas do povo, perguntava-lhes onde havia de nascer o Cristo.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 5, 'Responderam-lhe eles: Em Belém da Judéia; pois assim está escrito pelo profeta:', 1, CURRENT_TIMESTAMP, false),
(40, 2, 6, 'E tu, Belém, terra de Judá, de modo nenhum és a menor entre as principais cidades de Judá; porque de ti sairá o Guia que há de apascentar o meu povo de Israel.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 7, 'Então Herodes chamou secretamente os magos, e deles inquiriu com precisão acerca do tempo em que a estrela aparecera;', 1, CURRENT_TIMESTAMP, false),
(40, 2, 8, 'e enviando-os a Belém, disse-lhes: Ide, e perguntai diligentemente pelo menino; e, quando o achardes, participai-mo, para que também eu vá e o adore.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 9, 'Tendo eles, pois, ouvido o rei, partiram; e eis que a estrela que tinham visto quando no oriente ia adiante deles, até que, chegando, se deteve sobre o lugar onde estava o menino.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 10, 'Ao verem eles a estrela, regozijaram-se com grande alegria.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 11, 'E entrando na casa, viram o menino com Maria sua mãe e, prostrando-se, o adoraram; e abrindo os seus tesouros, ofertaram-lhe dádivas: ouro incenso e mirra.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 12, 'Ora, sendo por divina revelação avisados em sonhos para não voltarem a Herodes, regressaram à sua terra por outro caminho.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 13, 'E, havendo eles se retirado, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, foge para o Egito, e ali fica até que eu te fale; porque Herodes há de procurar o menino para o matar.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 14, 'Levantou-se, pois, tomou de noite o menino e sua mãe, e partiu para o Egito.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 15, 'e lá ficou até a morte de Herodes, para que se cumprisse o que fora dito da parte do Senhor pelo profeta: Do Egito chamei o meu Filho.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 16, 'Cumpriu-se então o que fora dito pelo profeta Jeremias:', 1, CURRENT_TIMESTAMP, false),
(40, 2, 17, 'Em Ramá se ouviu uma voz, lamentação e grande pranto: Raquel chorando os seus filhos, e não querendo ser consolada, porque eles já não existem.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 18, 'Mas tendo morrido Herodes, eis que um anjo do Senhor apareceu em sonho a José no Egito,', 1, CURRENT_TIMESTAMP, false),
(40, 2, 19, 'dizendo: Levanta-te, toma o menino e sua mãe e vai para a terra de Israel; porque já morreram os que procuravam a morte do menino.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 20, 'Então ele se levantou, tomou o menino e sua mãe e foi para a terra de Israel.', 1, CURRENT_TIMESTAMP, false),
(40, 2, 21, 'Ouvindo, porém, que Arquelau reinava na Judéia em lugar de seu pai Herodes, temeu ir para lá; mas avisado em sonho por divina revelação, retirou-se para as regiões da Galiléia,', 1, CURRENT_TIMESTAMP, false),
(40, 2, 22, 'e foi habitar numa cidade chamada Nazaré; para que se cumprisse o que fora dito pelos profetas: Ele será chamado nazareno.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 1, 'Naqueles dias apareceu João, o Batista, pregando no deserto da Judéia,', 1, CURRENT_TIMESTAMP, false),
(40, 3, 2, 'dizendo: Arrependei-vos, porque é chegado o reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 3, 'Porque este é o anunciado pelo profeta Isaías, que diz: Voz do que clama no deserto; Preparai o caminho do Senhor, endireitai as suas veredas.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 4, 'Ora, João usava uma veste de pelos de camelo, e um cinto de couro em torno de seus lombos; e alimentava-se de gafanhotos e mel silvestre.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 5, 'Então iam ter com ele os de Jerusalém, de toda a Judéia, e de toda a circunvizinhança do Jordão,', 1, CURRENT_TIMESTAMP, false),
(40, 3, 6, 'e eram por ele batizados no rio Jordão, confessando os seus pecados.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 7, 'Mas, vendo ele muitos dos fariseus e dos saduceus que vinham ao seu batismo, disse-lhes: Raça de víboras, quem vos ensinou a fugir da ira vindoura?', 1, CURRENT_TIMESTAMP, false),
(40, 3, 8, 'Produzi, pois, frutos dignos de arrependimento,', 1, CURRENT_TIMESTAMP, false),
(40, 3, 9, 'e não queirais dizer dentro de vós mesmos: Temos por pai a Abraão; porque eu vos digo que mesmo destas pedras Deus pode suscitar filhos a Abraão.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 10, 'E já está posto o machado á raiz das árvores; toda árvore, pois que não produz bom fruto, é cortada e lançada no fogo.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 11, 'Eu, na verdade, vos batizo em água, na base do arrependimento; mas aquele que vem após mim é mais poderoso do que eu, que nem sou digno de levar-lhe as alparcas; ele vos batizará no Espírito Santo, e em fogo.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 12, 'A sua pá ele tem na mão, e limpará bem a sua eira; recolherá o seu trigo ao celeiro, mas queimará a palha em fogo inextinguível.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 13, 'Então veio Jesus da Galiléia ter com João, junto do Jordão, para ser batizado por ele.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 14, 'Mas João o impedia, dizendo: Eu é que preciso ser batizado por ti, e tu vens a mim?', 1, CURRENT_TIMESTAMP, false),
(40, 3, 15, 'Jesus, porém, lhe respondeu: Consente agora; porque assim nos convém cumprir toda a justiça. Então ele consentiu.', 1, CURRENT_TIMESTAMP, false),
(40, 3, 16, 'Batizado que foi Jesus, saiu logo da água; e eis que se lhe abriram os céus, e viu o Espírito Santo de Deus descendo como uma pomba e vindo sobre ele;', 1, CURRENT_TIMESTAMP, false),
(40, 3, 17, 'e eis que uma voz dos céus dizia: Este é o meu Filho amado, em quem me comprazo.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 1, 'Então foi conduzido Jesus pelo Espírito ao deserto, para ser tentado pelo Diabo.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 2, 'E, tendo jejuado quarenta dias e quarenta noites, depois teve fome.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 3, 'Chegando, então, o tentador, disse-lhe: Se tu és Filho de Deus manda que estas pedras se tornem em pães.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 4, 'Mas Jesus lhe respondeu: Está escrito: Nem só de pão viverá o homem, mas de toda palavra que sai da boca de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 5, 'Então o Diabo o levou à cidade santa, colocou-o sobre o pináculo do templo,', 1, CURRENT_TIMESTAMP, false),
(40, 4, 6, 'e disse-lhe: Se tu és Filho de Deus, lança-te daqui abaixo; porque está escrito: Aos seus anjos dará ordens a teu respeito; e: eles te susterão nas mãos, para que nunca tropeces em alguma pedra.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 7, 'Replicou-lhe Jesus: Também está escrito: Não tentarás o Senhor teu Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 8, 'Novamente o Diabo o levou a um monte muito alto; e mostrou-lhe todos os reinos do mundo, e a glória deles;', 1, CURRENT_TIMESTAMP, false),
(40, 4, 9, 'e disse-lhe: Tudo isto te darei, se, prostrado, me adorares.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 10, 'Então ordenou-lhe Jesus: Vai-te, Satanás; porque está escrito: Ao Senhor teu Deus adorarás, e só a ele servirás.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 11, 'Então o Diabo o deixou; e eis que vieram os anjos e o serviram.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 12, 'Ora, ouvindo Jesus que João fora entregue, retirou-se para a Galiléia;', 1, CURRENT_TIMESTAMP, false),
(40, 4, 13, 'e, deixando Nazaré, foi habitar em Cafarnaum, cidade marítima, nos confins de Zabulom e Naftali;', 1, CURRENT_TIMESTAMP, false),
(40, 4, 14, 'para que se cumprisse o que fora dito pelo profeta Isaías:', 1, CURRENT_TIMESTAMP, false),
(40, 4, 15, 'A terra de Zabulom e a terra de Naftali, o caminho do mar, além do Jordão, a Galiléia dos gentios,', 1, CURRENT_TIMESTAMP, false),
(40, 4, 16, 'o povo que estava sentado em trevas viu uma grande luz; sim, aos que estavam sentados na região da sombra da morte, a estes a luz raiou.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 17, 'Desde então começou Jesus a pregar, e a dizer: Arrependei-vos, porque é chegado o reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 18, 'E Jesus, andando ao longo do mar da Galiléia, viu dois irmãos - Simão, chamado Pedro, e seu irmão André, os quais lançavam a rede ao mar, porque eram pescadores.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 19, 'Disse-lhes: Vinde após mim, e eu vos farei pescadores de homens.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 20, 'Eles, pois, deixando imediatamente as redes, o seguiram.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 21, 'E, passando mais adiante, viu outros dois irmãos - Tiago, filho de Zebedeu, e seu irmão João, no barco com seu pai Zebedeu, consertando as redes; e os chamou.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 22, 'Estes, deixando imediatamente o barco e seu pai, seguiram-no.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 23, 'E percorria Jesus toda a Galiléia, ensinando nas sinagogas, pregando o evangelho do reino, e curando todas as doenças e enfermidades entre o povo.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 24, 'Assim a sua fama correu por toda a Síria; e trouxeram-lhe todos os que padeciam, acometidos de várias doenças e tormentos, os endemoninhados, os lunáticos, e os paralíticos; e ele os curou.', 1, CURRENT_TIMESTAMP, false),
(40, 4, 25, 'De sorte que o seguiam grandes multidões da Galiléia, de Decápolis, de Jerusalém, da Judéia, e dalém do Jordão.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 1, 'Jesus, pois, vendo as multidões, subiu ao monte; e, tendo se assentado, aproximaram-se os seus discípulos,', 1, CURRENT_TIMESTAMP, false),
(40, 5, 2, 'e ele se pôs a ensiná-los, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 5, 3, 'Bem-aventurados os humildes de espírito, porque deles é o reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 4, 'Bem-aventurados os que choram, porque eles serão consolados.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 5, 'Bem-aventurados os mansos, porque eles herdarão a terra.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 6, 'Bem-aventurados os que têm fome e sede de justiça porque eles serão fartos.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 7, 'Bem-aventurados os misericordiosos, porque eles alcançarão misericórdia.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 8, 'Bem-aventurados os limpos de coração, porque eles verão a Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 9, 'Bem-aventurados os pacificadores, porque eles serão chamados filhos de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 10, 'Bem-aventurados os que são perseguidos por causa da justiça, porque deles é o reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 11, 'Bem-aventurados sois vós, quando vos injuriarem e perseguiram e, mentindo, disserem todo mal contra vós por minha causa.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 12, 'Alegrai-vos e exultai, porque é grande o vosso galardão nos céus; porque assim perseguiram aos profetas que foram antes de vós.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 13, 'Vós sois o sal da terra; mas se o sal se tornar insípido, com que se há de restaurar-lhe o sabor? para nada mais presta, senão para ser lançado fora, e ser pisado pelos homens.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 14, 'Vós sois a luz do mundo. Não se pode esconder uma cidade situada sobre um monte;', 1, CURRENT_TIMESTAMP, false),
(40, 5, 15, 'nem os que acendem uma candeia a colocam debaixo do alqueire, mas no velador, e assim ilumina a todos que estão na casa.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 16, 'Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras, e glorifiquem a vosso Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 17, 'Não penseis que vim destruir a lei ou os profetas; não vim destruir, mas cumprir.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 18, 'Porque em verdade vos digo que, até que o céu e a terra passem, de modo nenhum passará da lei um só i ou um só til, até que tudo seja cumprido.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 19, 'Qualquer, pois, que violar um destes mandamentos, por menor que seja, e assim ensinar aos homens, será chamado o menor no reino dos céus; aquele, porém, que os cumprir e ensinar será chamado grande no reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 20, 'Pois eu vos digo que, se a vossa justiça não exceder a dos escribas e fariseus, de modo nenhum entrareis no reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 21, 'Ouvistes que foi dito aos antigos: Não matarás; e, Quem matar será réu de juízo.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 22, 'Eu, porém, vos digo que todo aquele que se encolerizar contra seu irmão, será réu de juízo; e quem disser a seu irmão: Raca, será réu diante do sinédrio; e quem lhe disser: Tolo, será réu do fogo do inferno.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 23, 'Portanto, se estiveres apresentando a tua oferta no altar, e aí te lembrares de que teu irmão tem alguma coisa contra ti,', 1, CURRENT_TIMESTAMP, false),
(40, 5, 24, 'deixa ali diante do altar a tua oferta, e vai conciliar-te primeiro com teu irmão, e depois vem apresentar a tua oferta.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 25, 'Concilia-te depressa com o teu adversário, enquanto estás no caminho com ele; para que não aconteça que o adversário te entregue ao guarda, e sejas lançado na prisão.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 26, 'Em verdade te digo que de maneira nenhuma sairás dali enquanto não pagares o último ceitil.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 27, 'Ouvistes que foi dito: Não adulterarás.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 28, 'Eu, porém, vos digo que todo aquele que olhar para uma mulher para a cobiçar, já em seu coração cometeu adultério com ela.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 29, 'Se o teu olho direito te faz tropeçar, arranca-o e lança-o de ti; pois te é melhor que se perca um dos teus membros do que seja todo o teu corpo lançado no inferno.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 30, 'E, se a tua mão direita te faz tropeçar, corta-a e lança-a de ti; pois te é melhor que se perca um dos teus membros do que vá todo o teu corpo para o inferno.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 31, 'Também foi dito: Quem repudiar sua mulher, dê-lhe carta de divórcio.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 32, 'Eu, porém, vos digo que todo aquele que repudia sua mulher, a não ser por causa de infidelidade, a faz adúltera; e quem casar com a repudiada, comete adultério.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 33, 'Outrossim, ouvistes que foi dito aos antigos: Não jurarás falso, mas cumprirás para com o Senhor os teus juramentos.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 34, 'Eu, porém, vos digo que de maneira nenhuma jureis; nem pelo céu, porque é o trono de Deus;', 1, CURRENT_TIMESTAMP, false),
(40, 5, 35, 'nem pela terra, porque é o escabelo de seus pés; nem por Jerusalém, porque é a cidade do grande Rei;', 1, CURRENT_TIMESTAMP, false),
(40, 5, 36, 'nem jures pela tua cabeça, porque não podes tornar um só cabelo branco ou preto.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 37, 'Seja, porém, o vosso falar: Sim, sim; não, não; pois o que passa daí, vem do Maligno.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 38, 'Ouvistes que foi dito: Olho por olho, e dente por dente.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 39, 'Eu, porém, vos digo que não resistais ao homem mau; mas a qualquer que te bater na face direita, oferece-lhe também a outra;', 1, CURRENT_TIMESTAMP, false),
(40, 5, 40, 'e ao que quiser pleitear contigo, e tirar-te a túnica, larga-lhe também a capa;', 1, CURRENT_TIMESTAMP, false),
(40, 5, 41, 'e, se qualquer te obrigar a caminhar mil passos, vai com ele dois mil.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 42, 'Dá a quem te pedir, e não voltes as costas ao que quiser que lhe emprestes.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 43, 'Ouvistes que foi dito: Amarás ao teu próximo, e odiarás ao teu inimigo.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 44, 'Eu, porém, vos digo: Amai aos vossos inimigos, e orai pelos que vos perseguem;', 1, CURRENT_TIMESTAMP, false),
(40, 5, 45, 'para que vos torneis filhos do vosso Pai que está nos céus; porque ele faz nascer o seu sol sobre maus e bons, e faz chover sobre justos e injustos.', 1, CURRENT_TIMESTAMP, false),
(40, 5, 46, 'Pois, se amardes aos que vos amam, que recompensa tereis? não fazem os publicanos também o mesmo?', 1, CURRENT_TIMESTAMP, false),
(40, 5, 47, 'E, se saudardes somente os vossos irmãos, que fazeis demais? não fazem os gentios também o mesmo?', 1, CURRENT_TIMESTAMP, false),
(40, 5, 48, 'Sede vós, pois, perfeitos, como é perfeito o vosso Pai celestial.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 1, 'Guardai-vos de fazer as vossas boas obras diante dos homens, para serdes vistos por eles; de outra sorte não tereis recompensa junto de vosso Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 2, 'Quando, pois, deres esmola, não faças tocar trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem glorificados pelos homens. Em verdade vos digo que já receberam a sua recompensa.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 3, 'Mas, quando tu deres esmola, não saiba a tua mão esquerda o que faz a direita;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 4, 'para que a tua esmola fique em secreto; e teu Pai, que vê em secreto, te recompensará.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 5, 'E, quando orardes, não sejais como os hipócritas; pois gostam de orar em pé nas sinagogas, e às esquinas das ruas, para serem vistos pelos homens. Em verdade vos digo que já receberam a sua recompensa.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 6, 'Mas tu, quando orares, entra no teu quarto e, fechando a porta, ora a teu Pai que está em secreto; e teu Pai, que vê em secreto, te recompensará.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 7, 'E, orando, não useis de vãs repetições, como os gentios; porque pensam que pelo seu muito falar serão ouvidos.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 8, 'Não vos assemelheis, pois, a eles; porque vosso Pai sabe o que vos é necessário, antes de vós lho pedirdes.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 9, 'Portanto, orai vós deste modo: Pai nosso que estás nos céus, santificado seja o teu nome;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 10, 'venha o teu reino, seja feita a tua vontade, assim na terra como no céu;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 11, 'o pão nosso de cada dia nos dá hoje;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 12, 'e perdoa-nos as nossas dívidas, assim como nós também temos perdoado aos nossos devedores;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 13, 'e não nos deixes entrar em tentação; mas livra-nos do mal. {Porque teu é o reino e o poder, e a glória, para sempre, Amém.}', 1, CURRENT_TIMESTAMP, false),
(40, 6, 14, 'Porque, se perdoardes aos homens as suas ofensas, também vosso Pai celestial vos perdoará a vós;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 15, 'se, porém, não perdoardes aos homens, tampouco vosso Pai perdoará vossas ofensas.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 16, 'Quando jejuardes, não vos mostreis contristados como os hipócritas; porque eles desfiguram os seus rostos, para que os homens vejam que estão jejuando. Em verdade vos digo que já receberam a sua recompensa.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 17, 'Tu, porém, quando jejuares, unge a tua cabeça, e lava o teu rosto,', 1, CURRENT_TIMESTAMP, false),
(40, 6, 18, 'para não mostrar aos homens que estás jejuando, mas a teu Pai, que está em secreto; e teu Pai, que vê em secreto, te recompensará.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 19, 'Não ajunteis para vós tesouros na terra; onde a traça e a ferrugem os consomem, e onde os ladrões minam e roubam;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 20, 'mas ajuntai para vós tesouros no céu, onde nem a traça nem a ferrugem os consumem, e onde os ladrões não minam nem roubam.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 21, 'Porque onde estiver o teu tesouro, aí estará também o teu coração.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 22, 'A candeia do corpo são os olhos; de sorte que, se os teus olhos forem bons, todo teu corpo terá luz;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 23, 'se, porém, os teus olhos forem maus, o teu corpo será tenebroso. Se, portanto, a luz que em ti há são trevas, quão grandes são tais trevas!', 1, CURRENT_TIMESTAMP, false),
(40, 6, 24, 'Ninguém pode servir a dois senhores; porque ou há de odiar a um e amar o outro, ou há de dedicar-se a um e desprezar o outro. Não podeis servir a Deus e às riquezas.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 25, 'Por isso vos digo: Não estejais ansiosos quanto à vossa vida, pelo que haveis de comer, ou pelo que haveis de beber; nem, quanto ao vosso corpo, pelo que haveis de vestir. Não é a vida mais do que o alimento, e o corpo mais do que o vestuário?', 1, CURRENT_TIMESTAMP, false),
(40, 6, 26, 'Olhai para as aves do céu, que não semeiam, nem ceifam, nem ajuntam em celeiros; e vosso Pai celestial as alimenta. Não valeis vós muito mais do que elas?', 1, CURRENT_TIMESTAMP, false),
(40, 6, 27, 'Ora, qual de vós, por mais ansioso que esteja, pode acrescentar um côvado à sua estatura?', 1, CURRENT_TIMESTAMP, false),
(40, 6, 28, 'E pelo que haveis de vestir, por que andais ansiosos? Olhai para os lírios do campo, como crescem; não trabalham nem fiam;', 1, CURRENT_TIMESTAMP, false),
(40, 6, 29, 'contudo vos digo que nem mesmo Salomão em toda a sua glória se vestiu como um deles.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 30, 'Pois, se Deus assim veste a erva do campo, que hoje existe e amanhã é lançada no forno, quanto mais a vós, homens de pouca fé?', 1, CURRENT_TIMESTAMP, false),
(40, 6, 31, 'Portanto, não vos inquieteis, dizendo: Que havemos de comer? ou: Que havemos de beber? ou: Com que nos havemos de vestir?', 1, CURRENT_TIMESTAMP, false),
(40, 6, 32, '{Pois a todas estas coisas os gentios procuram.} Porque vosso Pai celestial sabe que precisais de tudo isso.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 33, 'Mas buscai primeiro o seu reino e a sua justiça, e todas estas coisas vos serão acrescentadas.', 1, CURRENT_TIMESTAMP, false),
(40, 6, 34, 'Não vos inquieteis, pois, pelo dia de amanhã; porque o dia de amanhã cuidará de si mesmo. Basta a cada dia o seu mal.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 1, 'Não julgueis, para que não sejais julgados.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 2, 'Porque com o juízo com que julgais, sereis julgados; e com a medida com que medis vos medirão a vós.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 3, 'E por que vês o argueiro no olho do teu irmão, e não reparas na trave que está no teu olho?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 4, 'Ou como dirás a teu irmão: Deixa-me tirar o argueiro do teu olho, quando tens a trave no teu?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 5, 'Hipócrita! tira primeiro a trave do teu olho; e então verás bem para tirar o argueiro do olho do teu irmão.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 6, 'Não deis aos cães o que é santo, nem lanceis aos porcos as vossas pérolas, para não acontecer que as calquem aos pés e, voltando-se, vos despedacem.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 7, 'Pedí, e dar-se-vos-á; buscai, e achareis; batei e abrir-se-vos-á.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 8, 'Pois todo o que pede, recebe; e quem busca, acha; e ao que bate, abrir-se-lhe-á.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 9, 'Ou qual dentre vós é o homem que, se seu filho lhe pedir pão, lhe dará uma pedra?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 10, 'Ou, se lhe pedir peixe, lhe dará uma serpente?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 11, 'Se vós, pois, sendo maus, sabeis dar boas dádivas a vossos filhos, quanto mais vosso Pai, que está nos céus, dará boas coisas aos que lhas pedirem?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 12, 'Portanto, tudo o que vós quereis que os homens vos façam, fazei-lho também vós a eles; porque esta é a lei e os profetas.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 13, 'Entrai pela porta estreita; porque larga é a porta, e espaçoso o caminho que conduz à perdição, e muitos são os que entram por ela;', 1, CURRENT_TIMESTAMP, false),
(40, 7, 14, 'e porque estreita é a porta, e apertado o caminho que conduz à vida, e poucos são os que a encontram.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 15, 'Guardai-vos dos falsos profetas, que vêm a vós disfarçados em ovelhas, mas interiormente são lobos devoradores.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 16, 'Pelos seus frutos os conhecereis. Colhem-se, porventura, uvas dos espinheiros, ou figos dos abrolhos?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 17, 'Assim, toda árvore boa produz bons frutos; porém a árvore má produz frutos maus.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 18, 'Uma árvore boa não pode dar maus frutos; nem uma árvore má dar frutos bons.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 19, 'Toda árvore que não produz bom fruto é cortada e lançada no fogo.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 20, 'Portanto, pelos seus frutos os conhecereis.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 21, 'Nem todo o que me diz: Senhor, Senhor! entrará no reino dos céus, mas aquele que faz a vontade de meu Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 22, 'Muitos me dirão naquele dia: Senhor, Senhor, não profetizamos nós em teu nome? e em teu nome não expulsamos demônios? e em teu nome não fizemos muitos milagres?', 1, CURRENT_TIMESTAMP, false),
(40, 7, 23, 'Então lhes direi claramente: Nunca vos conheci; apartai-vos de mim, vós que praticais a iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 24, 'Todo aquele, pois, que ouve estas minhas palavras e as põe em prática, será comparado a um homem prudente, que edificou a casa sobre a rocha.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 25, 'E desceu a chuva, correram as torrentes, sopraram os ventos, e bateram com ímpeto contra aquela casa; contudo não caiu, porque estava fundada sobre a rocha.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 26, 'Mas todo aquele que ouve estas minhas palavras, e não as põe em prática, será comparado a um homem insensato, que edificou a sua casa sobre a areia.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 27, 'E desceu a chuva, correram as torrentes, sopraram os ventos, e bateram com ímpeto contra aquela casa, e ela caiu; e grande foi a sua queda.', 1, CURRENT_TIMESTAMP, false),
(40, 7, 28, 'Ao concluir Jesus este discurso, as multidões se maravilhavam da sua doutrina;', 1, CURRENT_TIMESTAMP, false),
(40, 7, 29, 'porque as ensinava como tendo autoridade, e não como os escribas.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 1, 'Quando Jesus desceu do monte, grandes multidões o seguiam.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 2, 'E eis que veio um leproso e o adorava, dizendo: Senhor, se quiseres, podes tornar-me limpo.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 3, 'Jesus, pois, estendendo a mão, tocou-o, dizendo: Quero; sê limpo. No mesmo instante ficou purificado da sua lepra.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 4, 'Disse-lhe então Jesus: Olha, não contes isto a ninguém; mas vai, mostra-te ao sacerdote, e apresenta a oferta que Moisés determinou, para lhes servir de testemunho.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 5, 'Tendo Jesus entrado em Cafarnaum, chegou-se a ele um centurião que lhe rogava, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 8, 6, 'Senhor, o meu criado jaz em casa paralítico, e horrivelmente atormentado.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 7, 'Respondeu-lhe Jesus: Eu irei, e o curarei.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 8, 'O centurião, porém, replicou-lhe: Senhor, não sou digno de que entres debaixo do meu telhado; mas somente dize uma palavra, e o meu criado há de sarar.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 9, 'Pois também eu sou homem sujeito à autoridade, e tenho soldados às minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 10, 'Jesus, ouvindo isso, admirou-se, e disse aos que o seguiam: Em verdade vos digo que a ninguém encontrei em Israel com tamanha fé.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 11, 'Também vos digo que muitos virão do oriente e do ocidente, e reclinar-se-ão à mesa de Abraão, Isaque e Jacó, no reino dos céus;', 1, CURRENT_TIMESTAMP, false),
(40, 8, 12, 'mas os filhos do reino serão lançados nas trevas exteriores; ali haverá choro e ranger de dentes.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 13, 'Então disse Jesus ao centurião: Vai-te, e te seja feito assim como creste. E naquela mesma hora o seu criado sarou.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 14, 'Ora, tendo Jesus entrado na casa de Pedro, viu a sogra deste de cama; e com febre.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 15, 'E tocou-lhe a mão, e a febre a deixou; então ela se levantou, e o servia.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 16, 'Caída a tarde, trouxeram-lhe muitos endemoninhados; e ele com a sua palavra expulsou os espíritos, e curou todos os enfermos;', 1, CURRENT_TIMESTAMP, false),
(40, 8, 17, 'para que se cumprisse o que fora dito pelo profeta Isaías: Ele tomou sobre si as nossas enfermidades, e levou as nossas doenças.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 18, 'Vendo Jesus uma multidão ao redor de si, deu ordem de partir para o outro lado do mar.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 19, 'E, aproximando-se um escriba, disse-lhe: Mestre, seguir-te-ei para onde quer que fores.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 20, 'Respondeu-lhe Jesus: As raposas têm covis, e as aves do céu têm ninhos; mas o Filho do homem não tem onde reclinar a cabeça.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 21, 'E outro de seus discípulos lhe disse: Senhor, permite-me ir primeiro sepultar meu pai.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 22, 'Jesus, porém, respondeu-lhe: Segue-me, e deixa os mortos sepultar os seus próprios mortos.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 23, 'E, entrando ele no barco, seus discípulos o seguiram.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 24, 'E eis que se levantou no mar tão grande tempestade que o barco era coberto pelas ondas; ele, porém, estava dormindo.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 25, 'Os discípulos, pois, aproximando-se, o despertaram, dizendo: Salva-nos, Senhor, que estamos perecendo.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 26, 'Ele lhes respondeu: Por que temeis, homens de pouca fé? Então, levantando-se repreendeu os ventos e o mar, e seguiu-se grande bonança.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 27, 'E aqueles homens se maravilharam, dizendo: Que homem é este, que até os ventos e o mar lhe obedecem?', 1, CURRENT_TIMESTAMP, false),
(40, 8, 28, 'Tendo ele chegado ao outro lado, à terra dos gadarenos, saíram-lhe ao encontro dois endemoninhados, vindos dos sepulcros; tão ferozes eram que ninguém podia passar por aquele caminho.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 29, 'E eis que gritaram, dizendo: Que temos nós contigo, Filho de Deus? Vieste aqui atormentar-nos antes do tempo?', 1, CURRENT_TIMESTAMP, false),
(40, 8, 30, 'Ora, a alguma distância deles, andava pastando uma grande manada de porcos.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 31, 'E os demônios rogavam-lhe, dizendo: Se nos expulsas, manda-nos entrar naquela manada de porcos.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 32, 'Disse-lhes Jesus: Ide. Então saíram, e entraram nos porcos; e eis que toda a manada se precipitou pelo despenhadeiro no mar, perecendo nas águas.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 33, 'Os pastores fugiram e, chegando à cidade, divulgaram todas estas coisas, e o que acontecera aos endemoninhados.', 1, CURRENT_TIMESTAMP, false),
(40, 8, 34, 'E eis que toda a cidade saiu ao encontro de Jesus; e vendo-o, rogaram-lhe que se retirasse dos seus termos.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 1, 'E entrando Jesus num barco, passou para o outro lado, e chegou à sua própria cidade.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 2, 'E eis que lhe trouxeram um paralítico deitado num leito. Jesus, pois, vendo-lhes a fé, disse ao paralítico: Tem ânimo, filho; perdoados são os teus pecados.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 3, 'E alguns dos escribas disseram consigo: Este homem blasfema.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 4, 'Mas Jesus, conhecendo-lhes os pensamentos, disse: Por que pensais o mal em vossos corações?', 1, CURRENT_TIMESTAMP, false),
(40, 9, 5, 'Pois qual é mais fácil? dizer: Perdoados são os teus pecados, ou dizer: Levanta-te e anda?', 1, CURRENT_TIMESTAMP, false),
(40, 9, 6, 'Ora, para que saibais que o Filho do homem tem sobre a terra autoridade para perdoar pecados {disse então ao paralítico}: Levanta-te, toma o teu leito, e vai para tua casa.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 7, 'E este, levantando-se, foi para sua casa.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 8, 'E as multidões, vendo isso, temeram, e glorificaram a Deus, que dera tal autoridade aos homens.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 9, 'Partindo Jesus dali, viu sentado na coletoria um homem chamado Mateus, e disse-lhe: Segue-me. E ele, levantando-se, o seguiu.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 10, 'Ora, estando ele à mesa em casa, eis que chegaram muitos publicanos e pecadores, e se reclinaram à mesa juntamente com Jesus e seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 11, 'E os fariseus, vendo isso, perguntavam aos discípulos: Por que come o vosso Mestre com publicanos e pecadores?', 1, CURRENT_TIMESTAMP, false),
(40, 9, 12, 'Jesus, porém, ouvindo isso, respondeu: Não necessitam de médico os sãos, mas sim os enfermos.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 13, 'Ide, pois, e aprendei o que significa: Misericórdia quero, e não sacrifícios. Porque eu não vim chamar justos, mas pecadores.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 14, 'Então vieram ter com ele os discípulos de João, perguntando: Por que é que nós e os fariseus jejuamos, mas os teus discípulos não jejuam?', 1, CURRENT_TIMESTAMP, false),
(40, 9, 15, 'Respondeu-lhes Jesus: Podem porventura ficar tristes os convidados às núpcias, enquanto o noivo está com eles? Dias virão, porém, em que lhes será tirado o noivo, e então hão de jejuar.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 16, 'Ninguém põe remendo de pano novo em vestido velho; porque semelhante remendo tira parte do vestido, e faz-se maior a rotura.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 17, 'Nem se deita vinho novo em odres velhos; do contrário se rebentam, derrama-se o vinho, e os odres se perdem; mas deita-se vinho novo em odres novos, e assim ambos se conservam.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 18, 'Enquanto ainda lhes dizia essas coisas, eis que chegou um chefe da sinagoga e o adorou, dizendo: Minha filha acaba de falecer; mas vem, impõe-lhe a tua mão, e ela viverá.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 19, 'Levantou-se, pois, Jesus, e o foi seguindo, ele e os seus discípulos.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 20, 'E eis que certa mulher, que havia doze anos padecia de uma hemorragia, chegou por detrás dele e tocou-lhe a orla do manto;', 1, CURRENT_TIMESTAMP, false),
(40, 9, 21, 'porque dizia consigo: Se eu tão-somente tocar-lhe o manto, ficarei sã.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 22, 'Mas Jesus, voltando-se e vendo-a, disse: Tem ânimo, filha, a tua fé te salvou. E desde aquela hora a mulher ficou sã.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 23, 'Quando Jesus chegou à casa daquele chefe, e viu os tocadores de flauta e a multidão em alvoroço,', 1, CURRENT_TIMESTAMP, false),
(40, 9, 24, 'disse; Retirai-vos; porque a menina não está morta, mas dorme. E riam-se dele.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 25, 'Tendo-se feito sair o povo, entrou Jesus, tomou a menina pela mão, e ela se levantou.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 26, 'E espalhou-se a notícia disso por toda aquela terra.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 27, 'Partindo Jesus dali, seguiram-no dois cegos, que clamavam, dizendo: Tem compaixão de nós, Filho de Davi.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 28, 'E, tendo ele entrado em casa, os cegos se aproximaram dele; e Jesus perguntou-lhes: Credes que eu posso fazer isto? Responderam-lhe eles: Sim, Senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 29, 'Então lhes tocou os olhos, dizendo: Seja-vos feito segundo a vossa fé.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 30, 'E os olhos se lhes abriram. Jesus ordenou-lhes terminantemente, dizendo: Vede que ninguém o saiba.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 31, 'Eles, porém, saíram, e divulgaram a sua fama por toda aquela terra.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 32, 'Enquanto esses se retiravam, eis que lhe trouxeram um homem mudo e endemoninhado.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 33, 'E, expulso o demônio, falou o mudo e as multidões se admiraram, dizendo: Nunca tal se viu em Israel.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 34, 'Os fariseus, porém, diziam: É pelo príncipe dos demônios que ele expulsa os demônios.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 35, 'E percorria Jesus todas as cidades e aldeias, ensinando nas sinagogas, pregando o evangelho do reino, e curando toda sorte de doenças e enfermidades.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 36, 'Vendo ele as multidões, compadeceu-se delas, porque andavam desgarradas e errantes, como ovelhas que não têm pastor.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 37, 'Então disse a seus discípulos: Na verdade, a seara é grande, mas os trabalhadores são poucos.', 1, CURRENT_TIMESTAMP, false),
(40, 9, 38, 'Rogai, pois, ao Senhor da seara que mande trabalhadores para a sua seara.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 1, 'E, chamando a si os seus doze discípulos, deu-lhes autoridade sobre os espíritos imundos, para expulsarem, e para curarem toda sorte de doenças e enfermidades.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 2, 'Ora, os nomes dos doze apóstolos são estes: primeiro, Simão, chamado Pedro, e André, seu irmão; Tiago, filho de Zebedeu, e João, seu irmão;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 3, 'Felipe e Bartolomeu; Tomé e Mateus, o publicano; Tiago, filho de Alfeu, e Tadeu;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 4, 'Simão Cananeu, e Judas Iscariotes, aquele que o traiu.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 5, 'A estes doze enviou Jesus, e ordenou-lhes, dizendo: Não ireis aos gentios, nem entrareis em cidade de samaritanos;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 6, 'mas ide antes às ovelhas perdidas da casa de Israel;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 7, 'e indo, pregai, dizendo: É chegado o reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 8, 'Curai os enfermos, ressuscitai os mortos, limpai os leprosos, expulsai os demônios; de graça recebestes, de graça dai.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 9, 'Não vos provereis de ouro, nem de prata, nem de cobre, em vossos cintos;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 10, 'nem de alforje para o caminho, nem de duas túnicas, nem de alparcas, nem de bordão; porque digno é o trabalhador do seu alimento.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 11, 'Em qualquer cidade ou aldeia em que entrardes, procurai saber quem nela é digno, e hospedai-vos aí até que vos retireis.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 12, 'E, ao entrardes na casa, saudai-a;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 13, 'se a casa for digna, desça sobre ela a vossa paz; mas, se não for digna, torne para vós a vossa paz.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 14, 'E, se ninguém vos receber, nem ouvir as vossas palavras, saindo daquela casa ou daquela cidade, sacudi o pó dos vossos pés.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 15, 'Em verdade vos digo que, no dia do juízo, haverá menos rigor para a terra de Sodoma e Gomorra do que para aquela cidade.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 16, 'Eis que vos envio como ovelhas ao meio de lobos; portanto, sede prudentes como as serpentes e simples como as pombas.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 17, 'Acautelai-vos dos homens; porque eles vos entregarão aos sinédrios, e vos açoitarão nas suas sinagogas;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 18, 'e por minha causa sereis levados à presença dos governadores e dos reis, para lhes servir de testemunho, a eles e aos gentios.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 19, 'Mas, quando vos entregarem, não cuideis de como, ou o que haveis de falar; porque naquela hora vos será dado o que haveis de dizer.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 20, 'Porque não sois vós que falais, mas o Espírito de vosso Pai é que fala em vós.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 21, 'Um irmão entregará à morte a seu irmão, e um pai a seu filho; e filhos se levantarão contra os pais e os matarão.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 22, 'E sereis odiados de todos por causa do meu nome, mas aquele que perseverar até o fim, esse será salvo.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 23, 'Quando, porém, vos perseguirem numa cidade, fugi para outra; porque em verdade vos digo que não acabareis de percorrer as cidades de Israel antes que venha o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 24, 'Não é o discípulo mais do que o seu mestre, nem o servo mais do que o seu senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 25, 'Basta ao discípulo ser como seu mestre, e ao servo como seu senhor. Se chamaram Belzebu ao dono da casa, quanto mais aos seus domésticos?', 1, CURRENT_TIMESTAMP, false),
(40, 10, 26, 'Portanto, não os temais; porque nada há encoberto que não haja de ser descoberto, nem oculto que não haja de ser conhecido.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 27, 'O que vos digo às escuras, dizei-o às claras; e o que escutais ao ouvido, dos eirados pregai-o.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 28, 'E não temais os que matam o corpo, e não podem matar a alma; temei antes aquele que pode fazer perecer no inferno tanto a alma como o corpo.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 29, 'Não se vendem dois passarinhos por um asse? e nenhum deles cairá em terra sem a vontade de vosso Pai.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 30, 'E até mesmo os cabelos da vossa cabeça estão todos contados.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 31, 'Não temais, pois; mais valeis vós do que muitos passarinhos.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 32, 'Portanto, todo aquele que me confessar diante dos homens, também eu o confessarei diante de meu Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 33, 'Mas qualquer que me negar diante dos homens, também eu o negarei diante de meu Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 34, 'Não penseis que vim trazer paz à terra; não vim trazer paz, mas espada.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 35, 'Porque eu vim pôr em dissensão o homem contra seu pai, a filha contra sua mãe, e a nora contra sua sogra;', 1, CURRENT_TIMESTAMP, false),
(40, 10, 36, 'e assim os inimigos do homem serão os da sua própria casa.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 37, 'Quem ama o pai ou a mãe mais do que a mim não é digno de mim; e quem ama o filho ou a filha mais do que a mim não é digno de mim.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 38, 'E quem não toma a sua cruz, e não segue após mim, não é digno de mim.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 39, 'Quem achar a sua vida perdê-la-á, e quem perder a sua vida por amor de mim achá-la-á.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 40, 'Quem vos recebe, a mim me recebe; e quem me recebe a mim, recebe aquele que me enviou.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 41, 'Quem recebe um profeta na qualidade de profeta, receberá a recompensa de profeta; e quem recebe um justo na qualidade de justo, receberá a recompensa de justo.', 1, CURRENT_TIMESTAMP, false),
(40, 10, 42, 'E aquele que der até mesmo um copo de água fresca a um destes pequeninos, na qualidade de discípulo, em verdade vos digo que de modo algum perderá a sua recompensa.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 1, 'Tendo acabado Jesus de dar instruções aos seus doze discípulos, partiu dali a ensinar e a pregar nas cidades da região.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 2, 'Ora, quando João no cárcere ouviu falar das obras do Cristo, mandou pelos seus discípulos perguntar-lhe:', 1, CURRENT_TIMESTAMP, false),
(40, 11, 3, 'És tu aquele que havia de vir, ou havemos de esperar outro?', 1, CURRENT_TIMESTAMP, false),
(40, 11, 4, 'Respondeu-lhes Jesus: Ide contar a João as coisas que ouvis e vedes:', 1, CURRENT_TIMESTAMP, false),
(40, 11, 5, 'os cegos vêem, e os coxos andam; os leprosos são purificados, e os surdos ouvem; os mortos são ressuscitados, e aos pobres é anunciado o evangelho.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 6, 'E bem-aventurado é aquele que não se escandalizar de mim.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 7, 'Ao partirem eles, começou Jesus a dizer às multidões a respeito de João: que saístes a ver no deserto? um caniço agitado pelo vento?', 1, CURRENT_TIMESTAMP, false),
(40, 11, 8, 'Mas que saístes a ver? um homem trajado de vestes luxuosas? Eis que aqueles que trajam vestes luxuosas estão nas casas dos reis.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 9, 'Mas por que saístes? para ver um profeta? Sim, vos digo, e muito mais do que profeta.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 10, 'Este é aquele de quem está escrito: Eis aí envio eu ante a tua face o meu mensageiro, que há de preparar adiante de ti o teu caminho.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 11, 'Em verdade vos digo que, entre os nascidos de mulher, não surgiu outro maior do que João, o Batista; mas aquele que é o menor no reino dos céus é maior do que ele.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 12, 'E desde os dias de João, o Batista, até agora, o reino dos céus é tomado a força, e os violentos o tomam de assalto.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 13, 'Pois todos os profetas e a lei profetizaram até João.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 14, 'E, se quereis dar crédito, é este o Elias que havia de vir.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 15, 'Quem tem ouvidos, ouça.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 16, 'Mas, a quem compararei esta geração? É semelhante aos meninos que, sentados nas praças, clamam aos seus companheiros:', 1, CURRENT_TIMESTAMP, false),
(40, 11, 17, 'Tocamo-vos flauta, e não dançastes; cantamos lamentações, e não pranteastes.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 18, 'Porquanto veio João, não comendo nem bebendo, e dizem: Tem demônio.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 19, 'Veio o Filho do homem, comendo e bebendo, e dizem: Eis aí um comilão e bebedor de vinho, amigo de publicanos e pecadores. Entretanto a sabedoria é justificada pelas suas obras.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 20, 'Então começou ele a lançar em rosto às cidades onde se operara a maior parte dos seus milagres, o não se haverem arrependido, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 11, 21, 'Ai de ti, Corazin! ai de ti, Betsaida! porque, se em Tiro e em Sidom, se tivessem operado os milagres que em vós se operaram, há muito elas se teriam arrependido em cilício e em cinza.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 22, 'Contudo, eu vos digo que para Tiro e Sidom haverá menos rigor, no dia do juízo, do que para vós.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 23, 'E tu, Cafarnaum, porventura serás elevada até o céu? até o inferno descerás; porque, se em Sodoma se tivessem operado os milagres que em ti se operaram, teria ela permanecido até hoje.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 24, 'Contudo, eu vos digo que no dia do juízo haverá menos rigor para a terra de Sodoma do que para ti.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 25, 'Naquele tempo falou Jesus, dizendo: Graças te dou, ó Pai, Senhor do céu e da terra, porque ocultaste estas coisas aos sábios e entendidos, e as revelaste aos pequeninos.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 26, 'Sim, ó Pai, porque assim foi do teu agrado.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 27, 'Todas as coisas me foram entregues por meu Pai; e ninguém conhece plenamente o Filho, senão o Pai; e ninguém conhece plenamente o Pai, senão o Filho, e aquele a quem o Filho o quiser revelar.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 28, 'Vinde a mim, todos os que estai cansados e oprimidos, e eu vos aliviarei.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 29, 'Tomai sobre vós o meu jugo, e aprendei de mim, que sou manso e humilde de coração; e achareis descanso para as vossas almas.', 1, CURRENT_TIMESTAMP, false),
(40, 11, 30, 'Porque o meu jugo é suave, e o meu fardo e leve.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 1, 'Naquele tempo passou Jesus pelas searas num dia de sábado; e os seus discípulos, sentindo fome, começaram a colher espigas, e a comer.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 2, 'Os fariseus, vendo isso, disseram-lhe: Eis que os teus discípulos estão fazendo o que não é lícito fazer no sábado.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 3, 'Ele, porém, lhes disse: Acaso não lestes o que fez Davi, quando teve fome, ele e seus companheiros?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 4, 'Como entrou na casa de Deus, e como eles comeram os pães da proposição, que não lhe era lícito comer, nem a seus companheiros, mas somente aos sacerdotes?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 5, 'Ou não lestes na lei que, aos sábados, os sacerdotes no templo violam o sábado, e ficam sem culpa?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 6, 'Digo-vos, porém, que aqui está o que é maior do que o templo.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 7, 'Mas, se vós soubésseis o que significa: Misericórdia quero, e não sacrifícios, não condenaríeis os inocentes.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 8, 'Porque o Filho do homem até do sábado é o Senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 9, 'Partindo dali, entrou Jesus na sinagoga deles.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 10, 'E eis que estava ali um homem que tinha uma das mãos atrofiadas; e eles, para poderem acusar a Jesus, o interrogaram, dizendo: É lícito curar nos sábados?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 11, 'E ele lhes disse: Qual dentre vós será o homem que, tendo uma só ovelha, se num sábado ela cair numa cova, não há de lançar mão dela, e tirá-la?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 12, 'Ora, quanto mais vale um homem do que uma ovelha! Portanto, é lícito fazer bem nos sábados.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 13, 'Então disse àquele homem: estende a tua mão. E ele a estendeu, e lhe foi restituída sã como a outra.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 14, 'Os fariseus, porém, saindo dali, tomaram conselho contra ele, para o matarem.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 15, 'Jesus, percebendo isso, retirou-se dali. Acompanharam-no muitos; e ele curou a todos,', 1, CURRENT_TIMESTAMP, false),
(40, 12, 16, 'e advertiu-lhes que não o dessem a conhecer;', 1, CURRENT_TIMESTAMP, false),
(40, 12, 17, 'para que se cumprisse o que foi dito pelo profeta Isaías:', 1, CURRENT_TIMESTAMP, false),
(40, 12, 18, 'Eis aqui o meu servo que escolhi, o meu amado em quem a minha alma se compraz; porei sobre ele o meu espírito, e ele anunciará aos gentios o juízo.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 19, 'Não contenderá, nem clamará, nem se ouvirá pelas ruas a sua voz.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 20, 'Não esmagará a cana quebrada, e não apagará o morrão que fumega, até que faça triunfar o juízo;', 1, CURRENT_TIMESTAMP, false),
(40, 12, 21, 'e no seu nome os gentios esperarão.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 22, 'Trouxeram-lhe então um endemoninhado cego e mudo; e ele o curou, de modo que o mudo falava e via.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 23, 'E toda a multidão, maravilhada, dizia: É este, porventura, o Filho de Davi?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 24, 'Mas os fariseus, ouvindo isto, disseram: Este não expulsa os demônios senão por Belzebu, príncipe dos demônios.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 25, 'Jesus, porém, conhecendo-lhes os pensamentos, disse-lhes: Todo reino dividido contra si mesmo é devastado; e toda cidade, ou casa, dividida contra si mesma não subsistirá.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 26, 'Ora, se Satanás expulsa a Satanás, está dividido contra si mesmo; como subsistirá, pois, o seus reino?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 27, 'E, se eu expulso os demônios por Belzebu, por quem os expulsam os vossos filhos? Por isso, eles mesmos serão os vossos juízes.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 28, 'Mas, se é pelo Espírito de Deus que eu expulso os demônios, logo é chegado a vós o reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 29, 'Ou, como pode alguém entrar na casa do valente, e roubar-lhe os bens, se primeiro não amarrar o valente? e então lhe saquear a casa.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 30, 'Quem não é comigo é contra mim; e quem comigo não ajunta, espalha.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 31, 'Portanto vos digo: Todo pecado e blasfêmia se perdoará aos homens; mas a blasfêmia contra o Espírito não será perdoada.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 32, 'Se alguém disser alguma palavra contra o Filho do homem, isso lhe será perdoado; mas se alguém falar contra o Espírito Santo, não lhe será perdoado, nem neste mundo, nem no vindouro.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 33, 'Ou fazei a árvore boa, e o seu fruto bom; ou fazei a árvore má, e o seu fruto mau; porque pelo fruto se conhece a árvore.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 34, 'Raça de víboras! como podeis vós falar coisas boas, sendo maus? pois do que há em abundância no coração, disso fala a boca.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 35, 'O homem bom, do seu bom tesouro tira coisas boas, e o homem mau do mau tesouro tira coisas más.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 36, 'Digo-vos, pois, que de toda palavra fútil que os homens disserem, hão de dar conta no dia do juízo.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 37, 'Porque pelas tuas palavras serás justificado, e pelas tuas palavras serás condenado.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 38, 'Então alguns dos escribas e dos fariseus, tomando a palavra, disseram: Mestre, queremos ver da tua parte algum sinal.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 39, 'Mas ele lhes respondeu: Uma geração má e adúltera pede um sinal; e nenhum sinal se lhe dará, senão o do profeta Jonas;', 1, CURRENT_TIMESTAMP, false),
(40, 12, 40, 'pois, como Jonas esteve três dias e três noites no ventre do grande peixe, assim estará o Filho do homem três dias e três noites no seio da terra.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 41, 'Os ninivitas se levantarão no juízo com esta geração, e a condenarão; porque se arrependeram com a pregação de Jonas. E eis aqui quem é maior do que Jonas.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 42, 'A rainha do sul se levantará no juízo com esta geração, e a condenará; porque veio dos confins da terra para ouvir a sabedoria de Salomão. E eis aqui quem é maior do que Salomão.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 43, 'Ora, havendo o espírito imundo saído do homem, anda por lugares áridos, buscando repouso, e não o encontra.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 44, 'Então diz: Voltarei para minha casa, donde saí. E, chegando, acha-a desocupada, varrida e adornada.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 45, 'Então vai e leva consigo outros sete espíritos piores do que ele e, entretanto, habitam ali; e o último estado desse homem vem a ser pior do que o primeiro. Assim há de acontecer também a esta geração perversa.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 46, 'Enquanto ele ainda falava às multidões, estavam do lado de fora sua mãe e seus irmãos, procurando falar-lhe.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 47, 'Disse-lhe alguém: Eis que estão ali fora tua mãe e teus irmãos, e procuram falar contigo.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 48, 'Ele, porém, respondeu ao que lhe falava: Quem é minha mãe? e quem são meus irmãos?', 1, CURRENT_TIMESTAMP, false),
(40, 12, 49, 'E, estendendo a mão para os seus discípulos disse: Eis aqui minha mãe e meus irmãos.', 1, CURRENT_TIMESTAMP, false),
(40, 12, 50, 'Pois qualquer que fizer a vontade de meu Pai que está nos céus, esse é meu irmão, irmã e mãe.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 1, 'No mesmo dia, tendo Jesus saído de casa, sentou-se à beira do mar;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 2, 'e reuniram-se a ele grandes multidões, de modo que entrou num barco, e se sentou; e todo o povo estava em pé na praia.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 3, 'E falou-lhes muitas coisas por parábolas, dizendo: Eis que o semeador saiu a semear.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 4, 'e quando semeava, uma parte da semente caiu à beira do caminho, e vieram as aves e comeram.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 5, 'E outra parte caiu em lugares pedregosos, onde não havia muita terra: e logo nasceu, porque não tinha terra profunda;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 6, 'mas, saindo o sol, queimou-se e, por não ter raiz, secou-se.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 7, 'E outra caiu entre espinhos; e os espinhos cresceram e a sufocaram.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 8, 'Mas outra caiu em boa terra, e dava fruto, um a cem, outro a sessenta e outro a trinta por um.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 9, 'Quem tem ouvidos, ouça.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 10, 'E chegando-se a ele os discípulos, perguntaram-lhe: Por que lhes falas por parábolas?', 1, CURRENT_TIMESTAMP, false),
(40, 13, 11, 'Respondeu-lhes Jesus: Porque a vós é dado conhecer os mistérios do reino dos céus, mas a eles não lhes é dado;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 12, 'pois ao que tem, dar-se-lhe-á, e terá em abundância; mas ao que não tem, até aquilo que tem lhe será tirado.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 13, 'Por isso lhes falo por parábolas; porque eles, vendo, não vêem; e ouvindo, não ouvem nem entendem.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 14, 'E neles se cumpre a profecia de Isaías, que diz: Ouvindo, ouvireis, e de maneira alguma entendereis; e, vendo, vereis, e de maneira alguma percebereis.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 15, 'Porque o coração deste povo se endureceu, e com os ouvidos ouviram tardiamente, e fecharam os olhos, para que não vejam com os olhos, nem ouçam com os ouvidos, nem entendam com o coração, nem se convertam, e eu os cure.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 16, 'Mas bem-aventurados os vossos olhos, porque vêem, e os vossos ouvidos, porque ouvem.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 17, 'Pois, em verdade vos digo que muitos profetas e justos desejaram ver o que vedes, e não o viram; e ouvir o que ouvis, e não o ouviram.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 18, 'Ouvi, pois, vós a parábola do semeador.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 19, 'A todo o que ouve a palavra do reino e não a entende, vem o Maligno e arrebata o que lhe foi semeado no coração; este é o que foi semeado à beira do caminho.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 20, 'E o que foi semeado nos lugares pedregosos, este é o que ouve a palavra, e logo a recebe com alegria;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 21, 'mas não tem raiz em si mesmo, antes é de pouca duração; e sobrevindo a angústia e a perseguição por causa da palavra, logo se escandaliza.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 22, 'E o que foi semeado entre os espinhos, este é o que ouve a palavra; mas os cuidados deste mundo e a sedução das riquezas sufocam a palavra, e ela fica infrutífera.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 23, 'Mas o que foi semeado em boa terra, este é o que ouve a palavra, e a entende; e dá fruto, e um produz cem, outro sessenta, e outro trinta.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 24, 'Propôs-lhes outra parábola, dizendo: O reino dos céus é semelhante ao homem que semeou boa semente no seu campo;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 25, 'mas, enquanto os homens dormiam, veio o inimigo dele, semeou joio no meio do trigo, e retirou-se.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 26, 'Quando, porém, a erva cresceu e começou a espigar, então apareceu também o joio.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 27, 'Chegaram, pois, os servos do proprietário, e disseram-lhe: Senhor, não semeaste no teu campo boa semente? Donde, pois, vem o joio?', 1, CURRENT_TIMESTAMP, false),
(40, 13, 28, 'Respondeu-lhes: Algum inimigo é quem fez isso. E os servos lhe disseram: Queres, pois, que vamos arrancá-lo?', 1, CURRENT_TIMESTAMP, false),
(40, 13, 29, 'Ele, porém, disse: Não; para que, ao colher o joio, não arranqueis com ele também o trigo.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 30, 'Deixai crescer ambos juntos até a ceifa; e, por ocasião da ceifa, direi aos ceifeiros: Ajuntai primeiro o joio, e atai-o em molhos para o queimar; o trigo, porém, recolhei-o no meu celeiro.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 31, 'Propôs-lhes outra parábola, dizendo: O reino dos céus é semelhante a um grão de mostarda que um homem tomou, e semeou no seu campo;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 32, 'o qual é realmente a menor de todas as sementes; mas, depois de ter crescido, é a maior das hortaliças, e faz-se árvore, de sorte que vêm as aves do céu, e se aninham nos seus ramos.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 33, 'Outra parábola lhes disse: O reino dos céus é semelhante ao fermento que uma mulher tomou e misturou com três medidas de farinha, até ficar tudo levedado.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 34, 'Todas estas coisas falou Jesus às multidões por parábolas, e sem parábolas nada lhes falava;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 35, 'para que se cumprisse o que foi dito pelo profeta: Abrirei em parábolas a minha boca; publicarei coisas ocultas desde a fundação do mundo.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 36, 'Então Jesus, deixando as multidões, entrou em casa. E chegaram-se a ele os seus discípulos, dizendo: Explica-nos a parábola do joio do campo.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 37, 'E ele, respondendo, disse: O que semeia a boa semente é o Filho do homem;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 38, 'o campo é o mundo; a boa semente são os filhos do reino; o joio são os filhos do maligno;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 39, 'o inimigo que o semeou é o Diabo; a ceifa é o fim do mundo, e os celeiros são os anjos.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 40, 'Pois assim como o joio é colhido e queimado no fogo, assim será no fim do mundo.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 41, 'Mandará o Filho do homem os seus anjos, e eles ajuntarão do seu reino todos os que servem de tropeço, e os que praticam a iniqüidade,', 1, CURRENT_TIMESTAMP, false),
(40, 13, 42, 'e lançá-los-ão na fornalha de fogo; ali haverá choro e ranger de dentes.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 43, 'Então os justos resplandecerão como o sol, no reino de seu Pai. Quem tem ouvidos, ouça.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 44, 'O reino dos céus é semelhante a um tesouro escondido no campo, que um homem, ao descobri-lo, esconde; então, movido de gozo, vai, vende tudo quanto tem, e compra aquele campo.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 45, 'Outrossim, o reino dos céus é semelhante a um negociante que buscava boas pérolas;', 1, CURRENT_TIMESTAMP, false),
(40, 13, 46, 'e encontrando uma pérola de grande valor, foi, vendeu tudo quanto tinha, e a comprou.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 47, 'Igualmente, o reino dos céus é semelhante a uma rede lançada ao mar, e que apanhou toda espécie de peixes.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 48, 'E, quando cheia, puxaram-na para a praia; e, sentando-se, puseram os bons em cestos; os ruins, porém, lançaram fora.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 49, 'Assim será no fim do mundo: sairão os anjos, e separarão os maus dentre os justos,', 1, CURRENT_TIMESTAMP, false),
(40, 13, 50, 'e lançá-los-ão na fornalha de fogo; ali haverá choro e ranger de dentes.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 51, 'Entendestes todas estas coisas? Disseram-lhe eles: Entendemos.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 52, 'E disse-lhes: Por isso, todo escriba que se fez discípulo do reino dos céus é semelhante a um homem, proprietário, que tira do seu tesouro coisas novas e velhas.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 53, 'E Jesus, tendo concluído estas parábolas, se retirou dali.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 54, 'E, chegando à sua terra, ensinava o povo na sinagoga, de modo que este se maravilhava e dizia: Donde lhe vem esta sabedoria, e estes poderes milagrosos?', 1, CURRENT_TIMESTAMP, false),
(40, 13, 55, 'Não é este o filho do carpinteiro? e não se chama sua mãe Maria, e seus irmãos Tiago, José, Simão, e Judas?', 1, CURRENT_TIMESTAMP, false),
(40, 13, 56, 'E não estão entre nós todas as suas irmãs? Donde lhe vem, pois, tudo isto?', 1, CURRENT_TIMESTAMP, false),
(40, 13, 57, 'E escandalizavam-se dele. Jesus, porém, lhes disse: Um profeta não fica sem honra senão na sua terra e na sua própria casa.', 1, CURRENT_TIMESTAMP, false),
(40, 13, 58, 'E não fez ali muitos milagres, por causa da incredulidade deles.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 1, 'Naquele tempo Herodes, o tetrarca, ouviu a fama de Jesus,', 1, CURRENT_TIMESTAMP, false),
(40, 14, 2, 'e disse aos seus cortesãos: Este é João, o Batista; ele ressuscitou dentre os mortos, e por isso estes poderes milagrosos operam nele.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 3, 'Pois Herodes havia prendido a João, e, maniatando-o, o guardara no cárcere, por causa de Herodias, mulher de seu irmão Felipe;', 1, CURRENT_TIMESTAMP, false),
(40, 14, 4, 'porque João lhe dizia: Não te é lícito possuí-la.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 5, 'E queria matá-lo, mas temia o povo; porque o tinham como profeta.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 6, 'Festejando-se, porém, o dia natalício de Herodes, a filha de Herodias dançou no meio dos convivas, e agradou a Herodes,', 1, CURRENT_TIMESTAMP, false),
(40, 14, 7, 'pelo que este prometeu com juramento dar-lhe tudo o que pedisse.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 8, 'E instigada por sua mãe, disse ela: Dá-me aqui num prato a cabeça de João, o Batista.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 9, 'Entristeceu-se, então, o rei; mas, por causa do juramento, e dos que estavam à mesa com ele, ordenou que se lhe desse,', 1, CURRENT_TIMESTAMP, false),
(40, 14, 10, 'e mandou degolar a João no cárcere;', 1, CURRENT_TIMESTAMP, false),
(40, 14, 11, 'e a cabeça foi trazida num prato, e dada à jovem, e ela a levou para a sua mãe.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 12, 'Então vieram os seus discípulos, levaram o corpo e o sepultaram; e foram anunciá-lo a Jesus.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 13, 'Jesus, ouvindo isto, retirou-se dali num barco, para um, lugar deserto, à parte; e quando as multidões o souberam, seguiram-no a pé desde as cidades.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 14, 'E ele, ao desembarcar, viu uma grande multidão; e, compadecendo-se dela, curou os seus enfermos.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 15, 'Chegada a tarde, aproximaram-se dele os discípulos, dizendo: O lugar é deserto, e a hora é já passada; despede as multidões, para que vão às aldeias, e comprem o que comer.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 16, 'Jesus, porém, lhes disse: Não precisam ir embora; dai-lhes vós de comer.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 17, 'Então eles lhe disseram: Não temos aqui senão cinco pães e dois peixes.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 18, 'E ele disse: trazei-mos aqui.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 19, 'Tendo mandado às multidões que se reclinassem sobre a relva, tomou os cinco pães e os dois peixes e, erguendo os olhos ao céu, os abençoou; e partindo os pães, deu-os aos discípulos, e os discípulos às multidões.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 20, 'Todos comeram e se fartaram; e dos pedaços que sobejaram levantaram doze cestos cheios.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 21, 'Ora, os que comeram foram cerca de cinco mil homens, além de mulheres e crianças.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 22, 'Logo em seguida obrigou os seus discípulos a entrar no barco, e passar adiante dele para o outro lado, enquanto ele despedia as multidões.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 23, 'Tendo-as despedido, subiu ao monte para orar à parte. Ao anoitecer, estava ali sozinho.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 24, 'Entrementes, o barco já estava a muitos estádios da terra, açoitado pelas ondas; porque o vento era contrário.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 25, 'À quarta vigília da noite, foi Jesus ter com eles, andando sobre o mar.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 26, 'Os discípulos, porém, ao vê-lo andando sobre o mar, assustaram-se e disseram: É um fantasma. E gritaram de medo.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 27, 'Jesus, porém, imediatamente lhes falou, dizendo: Tende ânimo; sou eu; não temais.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 28, 'Respondeu-lhe Pedro: Senhor! se és tu, manda-me ir ter contigo sobre as águas.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 29, 'Disse-lhe ele: Vem. Pedro, descendo do barco, e andando sobre as águas, foi ao encontro de Jesus.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 30, 'Mas, sentindo o vento, teve medo; e, começando a submergir, clamou: Senhor, salva-me.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 31, 'Imediatamente estendeu Jesus a mão, segurou-o, e disse-lhe: Homem de pouca fé, por que duvidaste?', 1, CURRENT_TIMESTAMP, false),
(40, 14, 32, 'E logo que subiram para o barco, o vento cessou.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 33, 'Então os que estavam no barco adoraram-no, dizendo: Verdadeiramente tu és Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 34, 'Ora, terminada a travessia, chegaram à terra em Genezaré.', 1, CURRENT_TIMESTAMP, false),
(40, 14, 35, 'Quando os homens daquele lugar o reconheceram, mandaram por toda aquela circunvizinhança, e trouxeram-lhe todos os enfermos;', 1, CURRENT_TIMESTAMP, false),
(40, 14, 36, 'e rogaram-lhe que apenas os deixasse tocar a orla do seu manto; e todos os que a tocaram ficaram curados.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 1, 'Então chegaram a Jesus uns fariseus e escribas vindos de Jerusalém, e lhe perguntaram:', 1, CURRENT_TIMESTAMP, false),
(40, 15, 2, 'Por que transgridem os teus discípulos a tradição dos anciãos? pois não lavam as mãos, quando comem.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 3, 'Ele, porém, respondendo, disse-lhes: E vós, por que transgredis o mandamento de Deus por causa da vossa tradição?', 1, CURRENT_TIMESTAMP, false),
(40, 15, 4, 'Pois Deus ordenou: Honra a teu pai e a tua mãe; e, Quem maldisser a seu pai ou a sua mãe, certamente morrerá.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 5, 'Mas vós dizeis: Qualquer que disser a seu pai ou a sua mãe: O que poderias aproveitar de mim é oferta ao Senhor; esse de modo algum terá de honrar a seu pai.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 6, 'E assim por causa da vossa tradição invalidastes a palavra de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 7, 'Hipócritas! bem profetizou Isaias a vosso respeito, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 15, 8, 'Este povo honra-me com os lábios; o seu coração, porém, está longe de mim.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 9, 'Mas em vão me adoram, ensinando doutrinas que são preceitos de homem.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 10, 'E, clamando a si a multidão, disse-lhes: Ouvi, e entendei:', 1, CURRENT_TIMESTAMP, false),
(40, 15, 11, 'Não é o que entra pela boca que contamina o homem; mas o que sai da boca, isso é o que o contamina.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 12, 'Então os discípulos, aproximando-se dele, perguntaram-lhe: Sabes que os fariseus, ouvindo essas palavras, se escandalizaram?', 1, CURRENT_TIMESTAMP, false),
(40, 15, 13, 'Respondeu-lhes ele: Toda planta que meu Pai celestial não plantou será arrancada.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 14, 'Deixai-os; são guias cegos; ora, se um cego guiar outro cego, ambos cairão no barranco.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 15, 'E Pedro, tomando a palavra, disse-lhe: Explica-nos essa parábola.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 16, 'Respondeu Jesus: Estai vós também ainda sem entender?', 1, CURRENT_TIMESTAMP, false),
(40, 15, 17, 'Não compreendeis que tudo o que entra pela boca desce pelo ventre, e é lançado fora?', 1, CURRENT_TIMESTAMP, false),
(40, 15, 18, 'Mas o que sai da boca procede do coração; e é isso o que contamina o homem.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 19, 'Porque do coração procedem os maus pensamentos, homicídios, adultérios, prostituição, furtos, falsos testemunhos e blasfêmias.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 20, 'São estas as coisas que contaminam o homem; mas o comer sem lavar as mãos, isso não o contamina.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 21, 'Ora, partindo Jesus dali, retirou-se para as regiões de Tiro e Sidom.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 22, 'E eis que uma mulher cananéia, provinda daquelas cercania, clamava, dizendo: Senhor, Filho de Davi, tem compaixão de mim, que minha filha está horrivelmente endemoninhada.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 23, 'Contudo ele não lhe respondeu palavra. Chegando-se, pois, a ele os seus discípulos, rogavam-lhe, dizendo: Despede-a, porque vem clamando atrás de nós.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 24, 'Respondeu-lhes ele: Não fui enviado senão às ovelhas perdidas da casa de Israel.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 25, 'Então veio ela e, adorando-o, disse: Senhor, socorre-me.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 26, 'Ele, porém, respondeu: Não é bom tomar o pão dos filhos e lançá-lo aos cachorrinhos.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 27, 'Ao que ela disse: Sim, Senhor, mas até os cachorrinhos comem das migalhas que caem da mesa dos seus donos.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 28, 'Então respondeu Jesus, e disse-lhe: ó mulher, grande é a tua fé! seja-te feito como queres. E desde aquela hora sua filha ficou sã.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 29, 'Partindo Jesus dali, chegou ao pé do mar da Galiléia; e, subindo ao monte, sentou-se ali.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 30, 'E vieram a ele grandes multidões, trazendo consigo coxos, aleijados, cegos, mudos, e outros muitos, e lhos puseram aos pés; e ele os curou;', 1, CURRENT_TIMESTAMP, false),
(40, 15, 31, 'de modo que a multidão se admirou, vendo mudos a falar, aleijados a ficar sãos, coxos a andar, cegos a ver; e glorificaram ao Deus de Israel.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 32, 'Jesus chamou os seus discípulos, e disse: Tenho compaixão da multidão, porque já faz três dias que eles estão comigo, e não têm o que comer; e não quero despedi-los em jejum, para que não desfaleçam no caminho.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 33, 'Disseram-lhe os discípulos: Donde nos viriam num deserto tantos pães, para fartar tamanha multidão?', 1, CURRENT_TIMESTAMP, false),
(40, 15, 34, 'Perguntou-lhes Jesus: Quantos pães tendes? E responderam: Sete, e alguns peixinhos.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 35, 'E tendo ele ordenado ao povo que se sentasse no chão,', 1, CURRENT_TIMESTAMP, false),
(40, 15, 36, 'tomou os sete pães e os peixes, e havendo dado graças, partiu-os, e os entregava aos discípulos, e os discípulos á multidão.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 37, 'Assim todos comeram, e se fartaram; e do que sobejou dos pedaços levantaram sete alcofas cheias.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 38, 'Ora, os que tinham comido eram quatro mil homens além de mulheres e crianças.', 1, CURRENT_TIMESTAMP, false),
(40, 15, 39, 'E havendo Jesus despedido a multidão, entrou no barco, e foi para os confins de Magadã.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 1, 'Então chegaram a ele os fariseus e os saduceus e, para o experimentarem, pediram-lhe que lhes mostrasse algum sinal do céu.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 2, 'Mas ele respondeu, e disse-lhes: Ao cair da tarde, dizeis: Haverá bom tempo, porque o céu está rubro.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 3, 'E pela manhã: Hoje haverá tempestade, porque o céu está de um vermelho sombrio. Ora, sabeis discernir o aspecto do céu, e não podeis discernir os sinais dos tempos?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 4, 'Uma geração má e adúltera pede um sinal, e nenhum sinal lhe será dado, senão o de Jonas. E, deixando-os, retirou-se.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 5, 'Quando os discípulos passaram para o outro lado, esqueceram-se de levar pão.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 6, 'E Jesus lhes disse: Olhai, e acautelai-vos do fermento dos fariseus e dos saduceus.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 7, 'Pelo que eles arrazoavam entre si, dizendo: É porque não trouxemos pão.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 8, 'E Jesus, percebendo isso, disse: Por que arrazoais entre vós por não terdes pão, homens de pouca fé?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 9, 'Não compreendeis ainda, nem vos lembrais dos cinco pães para os cinco mil, e de quantos cestos levantastes?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 10, 'Nem dos sete pães para os quatro mil, e de quantas alcofas levantastes?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 11, 'Como não compreendeis que não nos falei a respeito de pães? Mas guardai-vos do fermento dos fariseus e dos saduceus.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 12, 'Então entenderam que não dissera que se guardassem, do fermento dos pães, mas da doutrina dos fariseus e dos saduceus.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 13, 'Tendo Jesus chegado às regiões de Cesaréia de Felipe, interrogou os seus discípulos, dizendo: Quem dizem os homens ser o Filho do homem?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 14, 'Responderam eles: Uns dizem que é João, o Batista; outros, Elias; outros, Jeremias, ou algum dos profetas.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 15, 'Mas vós, perguntou-lhes Jesus, quem dizeis que eu sou?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 16, 'Respondeu-lhe Simão Pedro: Tu és o Cristo, o Filho do Deus vivo.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 17, 'Disse-lhe Jesus: Bem-aventurado és tu, Simão Barjonas, porque não foi carne e sangue que to revelou, mas meu Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 18, 'Pois também eu te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja, e as portas do inferno não prevalecerão contra ela;', 1, CURRENT_TIMESTAMP, false),
(40, 16, 19, 'dar-te-ei as chaves do reino dos céus; o que ligares, pois, na terra será ligado nos céus, e o que desligares na terra será desligado nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 20, 'Então ordenou aos discípulos que a ninguém dissessem que ele era o Cristo.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 21, 'Desde então começou Jesus Cristo a mostrar aos seus discípulos que era necessário que ele fosse a Jerusalém, que padecesse muitas coisas dos anciãos, dos principais sacerdotes, e dos escribas, que fosse morto, e que ao terceiro dia ressuscitasse.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 22, 'E Pedro, tomando-o à parte, começou a repreendê-lo, dizendo: Tenha Deus compaixão de ti, Senhor; isso de modo nenhum te acontecerá.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 23, 'Ele, porém, voltando-se, disse a Pedro: Para trás de mim, Satanás, que me serves de escândalo; porque não estás pensando nas coisas que são de Deus, mas sim nas que são dos homens.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 24, 'Então disse Jesus aos seus discípulos: Se alguém quer vir após mim, negue-se a si mesmo, tome a sua cruz, e siga-me;', 1, CURRENT_TIMESTAMP, false),
(40, 16, 25, 'pois, quem quiser salvar a sua vida por amor de mim perdê-la-á; mas quem perder a sua vida por amor de mim, achá-la-á.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 26, 'Pois que aproveita ao homem se ganhar o mundo inteiro e perder a sua vida? ou que dará o homem em troca da sua vida?', 1, CURRENT_TIMESTAMP, false),
(40, 16, 27, 'Porque o Filho do homem há de vir na glória de seu Pai, com os seus anjos; e então retribuirá a cada um segundo as suas obras.', 1, CURRENT_TIMESTAMP, false),
(40, 16, 28, 'Em verdade vos digo, alguns dos que aqui estão de modo nenhum provarão a morte até que vejam vir o Filho do homem no seu reino.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 1, 'Seis dias depois, tomou Jesus consigo a Pedro, a Tiago e a João, irmão deste, e os conduziu à parte a um alto monte;', 1, CURRENT_TIMESTAMP, false),
(40, 17, 2, 'e foi transfigurado diante deles; o seu rosto resplandeceu como o sol, e as suas vestes tornaram-se brancas como a luz.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 3, 'E eis que lhes apareceram Moisés e Elias, falando com ele.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 4, 'Pedro, tomando a palavra, disse a Jesus: Senhor, bom é estarmos aqui; se queres, farei aqui três cabanas, uma para ti, outra para Moisés, e outra para Elias.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 5, 'Estando ele ainda a falar, eis que uma nuvem luminosa os cobriu; e dela saiu uma voz que dizia: Este é o meu Filho amado, em quem me comprazo; a ele ouvi.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 6, 'Os discípulos, ouvindo isso, caíram com o rosto em terra, e ficaram grandemente atemorizados.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 7, 'Chegou-se, pois, Jesus e, tocando-os, disse: Levantai-vos e não temais.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 8, 'E, erguendo eles os olhos, não viram a ninguém senão a Jesus somente.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 9, 'Enquanto desciam do monte, Jesus lhes ordenou: A ninguém conteis a visão, até que o Filho do homem seja levantado dentre os mortos.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 10, 'Perguntaram-lhe os discípulos: Por que dizem então os escribas que é necessário que Elias venha primeiro?', 1, CURRENT_TIMESTAMP, false),
(40, 17, 11, 'Respondeu ele: Na verdade Elias havia de vir e restaurar todas as coisas;', 1, CURRENT_TIMESTAMP, false),
(40, 17, 12, 'digo-vos, porém, que Elias já veio, e não o reconheceram; mas fizeram-lhe tudo o que quiseram. Assim também o Filho do homem há de padecer às mãos deles.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 13, 'Então entenderam os discípulos que lhes falava a respeito de João, o Batista.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 14, 'Quando chegaram à multidão, aproximou-se de Jesus um homem que, ajoelhando-se diante dele, disse:', 1, CURRENT_TIMESTAMP, false),
(40, 17, 15, 'Senhor, tem compaixão de meu filho, porque é epiléptico e sofre muito; pois muitas vezes cai no fogo, e muitas vezes na água.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 16, 'Eu o trouxe aos teus discípulos, e não o puderam curar.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 17, 'E Jesus, respondendo, disse: ó geração incrédula e perversa! até quando estarei convosco? até quando vos sofrerei? Trazei-mo aqui.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 18, 'Então Jesus repreendeu ao demônio, o qual saiu de menino, que desde aquela hora ficou curado.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 19, 'Depois os discípulos, aproximando-se de Jesus em particular, perguntaram-lhe: Por que não pudemos nós expulsá-lo?', 1, CURRENT_TIMESTAMP, false),
(40, 17, 20, 'Disse-lhes ele: Por causa da vossa pouca fé; pois em verdade vos digo que, se tiverdes fé como um grão de mostarda direis a este monte: Passa daqui para acolá, e ele há de passar; e nada vos será impossível.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 21, '{mas esta casta de demônios não se expulsa senão à força de oração e de jejum.}', 1, CURRENT_TIMESTAMP, false),
(40, 17, 22, 'Ora, achando-se eles na Galiléia, disse-lhes Jesus: O Filho do homem está para ser entregue nas mãos dos homens;', 1, CURRENT_TIMESTAMP, false),
(40, 17, 23, 'e matá-lo-ão, e ao terceiro dia ressurgirá. E eles se entristeceram grandemente.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 24, 'Tendo eles chegado a Cafarnaum, aproximaram-se de Pedro os que cobravam as didracmas, e lhe perguntaram: O vosso mestre não paga as didracmas?', 1, CURRENT_TIMESTAMP, false),
(40, 17, 25, 'Disse ele: Sim. Ao entrar Pedro em casa, Jesus se lhe antecipou, perguntando: Que te parece, Simão? De quem cobram os reis da terra imposto ou tributo? dos seus filhos, ou dos alheios?', 1, CURRENT_TIMESTAMP, false),
(40, 17, 26, 'Quando ele respondeu: Dos alheios, disse-lhe Jesus: Logo, são isentos os filhos.', 1, CURRENT_TIMESTAMP, false),
(40, 17, 27, 'Mas, para que não os escandalizemos, vai ao mar, lança o anzol, tira o primeiro peixe que subir e, abrindo-lhe a boca, encontrarás um estáter; toma-o, e dá-lho por mim e por ti.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 1, 'Naquela hora chegaram-se a Jesus os discípulos e perguntaram: Quem é o maior no reino dos céus?', 1, CURRENT_TIMESTAMP, false),
(40, 18, 2, 'Jesus, chamando uma criança, colocou-a no meio deles,', 1, CURRENT_TIMESTAMP, false),
(40, 18, 3, 'e disse: Em verdade vos digo que se não vos converterdes e não vos fizerdes como crianças, de modo algum entrareis no reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 4, 'Portanto, quem se tornar humilde como esta criança, esse é o maior no reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 5, 'E qualquer que receber em meu nome uma criança tal como esta, a mim me recebe.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 6, 'Mas qualquer que fizer tropeçar um destes pequeninos que crêem em mim, melhor lhe fora que se lhe pendurasse ao pescoço uma pedra de moinho, e se submergisse na profundeza do mar.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 7, 'Ai do mundo, por causa dos tropeços! pois é inevitável que venham; mas ai do homem por quem o tropeço vier!', 1, CURRENT_TIMESTAMP, false),
(40, 18, 8, 'Se, pois, a tua mão ou o teu pé te fizer tropeçar, corta-o, lança-o de ti; melhor te é entrar na vida aleijado, ou coxo, do que, tendo duas mãos ou dois pés, ser lançado no fogo eterno.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 9, 'E, se teu olho te fizer tropeçar, arranca-o, e lança-o de ti; melhor te é entrar na vida com um só olho, do que tendo dois olhos, ser lançado no inferno de fogo.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 10, 'Vede, não desprezeis a nenhum destes pequeninos; pois eu vos digo que os seus anjos nos céus sempre vêm a face de meu Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 11, '{Porque o Filho do homem veio salvar o que se havia perdido.}', 1, CURRENT_TIMESTAMP, false),
(40, 18, 12, 'Que vos parece? Se alguém tiver cem ovelhas, e uma delas se extraviar, não deixará as noventa e nove nos montes para ir buscar a que se extraviou?', 1, CURRENT_TIMESTAMP, false),
(40, 18, 13, 'E, se acontecer achá-la, em verdade vos digo que maior prazer tem por esta do que pelas noventa e nove que não se extraviaram.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 14, 'Assim também não é da vontade de vosso Pai que está nos céus, que venha a perecer um só destes pequeninos.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 15, 'Ora, se teu irmão pecar, vai, e repreende-o entre ti e ele só; se te ouvir, terás ganho teu irmão;', 1, CURRENT_TIMESTAMP, false),
(40, 18, 16, 'mas se não te ouvir, leva ainda contigo um ou dois, para que pela boca de duas ou três testemunhas toda palavra seja confirmada.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 17, 'Se recusar ouvi-los, dize-o à igreja; e, se também recusar ouvir a igreja, considera-o como gentio e publicano.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 18, 'Em verdade vos digo: Tudo quanto ligardes na terra será ligado no céu; e tudo quanto desligardes na terra será desligado no céu.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 19, 'Ainda vos digo mais: Se dois de vós na terra concordarem acerca de qualquer coisa que pedirem, isso lhes será feito por meu Pai, que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 20, 'Pois onde se acham dois ou três reunidos em meu nome, aí estou eu no meio deles.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 21, 'Então Pedro, aproximando-se dele, lhe perguntou: Senhor, até quantas vezes pecará meu irmão contra mim, e eu hei de perdoar? Até sete?', 1, CURRENT_TIMESTAMP, false),
(40, 18, 22, 'Respondeu-lhe Jesus: Não te digo que até sete; mas até setenta vezes sete.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 23, 'Por isso o reino dos céus é comparado a um rei que quis tomar contas a seus servos;', 1, CURRENT_TIMESTAMP, false),
(40, 18, 24, 'e, tendo começado a tomá-las, foi-lhe apresentado um que lhe devia dez mil talentos;', 1, CURRENT_TIMESTAMP, false),
(40, 18, 25, 'mas não tendo ele com que pagar, ordenou seu senhor que fossem vendidos, ele, sua mulher, seus filhos, e tudo o que tinha, e que se pagasse a dívida.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 26, 'Então aquele servo, prostrando-se, o reverenciava, dizendo: Senhor, tem paciência comigo, que tudo te pagarei.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 27, 'O senhor daquele servo, pois, movido de compaixão, soltou-o, e perdoou-lhe a dívida.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 28, 'Saindo, porém, aquele servo, encontrou um dos seus conservos, que lhe devia cem denários; e, segurando-o, o sufocava, dizendo: Paga o que me deves.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 29, 'Então o seu companheiro, caindo-lhe aos pés, rogava-lhe, dizendo: Tem paciência comigo, que te pagarei.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 30, 'Ele, porém, não quis; antes foi encerrá-lo na prisão, até que pagasse a dívida.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 31, 'Vendo, pois, os seus conservos o que acontecera, contristaram-se grandemente, e foram revelar tudo isso ao seu senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 32, 'Então o seu senhor, chamando-o á sua presença, disse-lhe: Servo malvado, perdoei-te toda aquela dívida, porque me suplicaste;', 1, CURRENT_TIMESTAMP, false),
(40, 18, 33, 'não devias tu também ter compaixão do teu companheiro, assim como eu tive compaixão de ti?', 1, CURRENT_TIMESTAMP, false),
(40, 18, 34, 'E, indignado, o seu senhor o entregou aos verdugos, até que pagasse tudo o que lhe devia.', 1, CURRENT_TIMESTAMP, false),
(40, 18, 35, 'Assim vos fará meu Pai celestial, se de coração não perdoardes, cada um a seu irmão.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 1, 'Tendo Jesus concluído estas palavras, partiu da Galiléia, e foi para os confins da Judéia, além do Jordão;', 1, CURRENT_TIMESTAMP, false),
(40, 19, 2, 'e seguiram-no grandes multidões, e curou-os ali.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 3, 'Aproximaram-se dele alguns fariseus que o experimentavam, dizendo: É lícito ao homem repudiar sua mulher por qualquer motivo?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 4, 'Respondeu-lhe Jesus: Não tendes lido que o Criador os fez desde o princípio homem e mulher,', 1, CURRENT_TIMESTAMP, false),
(40, 19, 5, 'e que ordenou: Por isso deixará o homem pai e mãe, e unir-se-á a sua mulher; e serão os dois uma só carne?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 6, 'Assim já não são mais dois, mas um só carne. Portanto o que Deus ajuntou, não o separe o homem.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 7, 'Responderam-lhe: Então por que mandou Moisés dar-lhe carta de divórcio e repudiá-la?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 8, 'Disse-lhes ele: Pela dureza de vossos corações Moisés vos permitiu repudiar vossas mulheres; mas não foi assim desde o princípio.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 9, 'Eu vos digo porém, que qualquer que repudiar sua mulher, a não ser por causa de infidelidade, e casar com outra, comete adultério; {e o que casar com a repudiada também comete adultério.}', 1, CURRENT_TIMESTAMP, false),
(40, 19, 10, 'Disseram-lhe os discípulos: Se tal é a condição do homem relativamente à mulher, não convém casar.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 11, 'Ele, porém, lhes disse: Nem todos podem aceitar esta palavra, mas somente aqueles a quem é dado.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 12, 'Porque há eunucos que nasceram assim; e há eunucos que pelos homens foram feitos tais; e outros há que a si mesmos se fizeram eunucos por causa do reino dos céus. Quem pode aceitar isso, aceite-o.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 13, 'Então lhe trouxeram algumas crianças para que lhes impusesse as mãos, e orasse; mas os discípulos os repreenderam.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 14, 'Jesus, porém, disse: Deixai as crianças e não as impeçais de virem a mim, porque de tais é o reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 15, 'E, depois de lhes impor as mãos, partiu dali.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 16, 'E eis que se aproximou dele um jovem, e lhe disse: Mestre, que bem farei para conseguir a vida eterna?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 17, 'Respondeu-lhe ele: Por que me perguntas sobre o que é bom? Um só é bom; mas se é que queres entrar na vida, guarda os mandamentos.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 18, 'Perguntou-lhe ele: Quais? Respondeu Jesus: Não matarás; não adulterarás; não furtarás; não dirás falso testemunho;', 1, CURRENT_TIMESTAMP, false),
(40, 19, 19, 'honra a teu pai e a tua mãe; e amarás o teu próximo como a ti mesmo.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 20, 'Disse-lhe o jovem: Tudo isso tenho guardado; que me falta ainda?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 21, 'Disse-lhe Jesus: Se queres ser perfeito, vai, vende tudo o que tens e dá-o aos pobres, e terás um tesouro no céu; e vem, segue-me.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 22, 'Mas o jovem, ouvindo essa palavra, retirou-se triste; porque possuía muitos bens.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 23, 'Disse então Jesus aos seus discípulos: Em verdade vos digo que um rico dificilmente entrará no reino dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 24, 'E outra vez vos digo que é mais fácil um camelo passar pelo fundo duma agulha, do que entrar um rico no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 25, 'Quando os seus discípulos ouviram isso, ficaram grandemente maravilhados, e perguntaram: Quem pode, então, ser salvo?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 26, 'Jesus, fixando neles o olhar, respondeu: Aos homens é isso impossível, mas a Deus tudo é possível.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 27, 'Então Pedro, tomando a palavra, disse-lhe: Eis que nós deixamos tudo, e te seguimos; que recompensa, pois, teremos nós?', 1, CURRENT_TIMESTAMP, false),
(40, 19, 28, 'Ao que lhe disse Jesus: Em verdade vos digo a vós que me seguistes, que na regeneração, quando o Filho do homem se assentar no trono da sua glória, sentar-vos-eis também vós sobre doze tronos, para julgar as doze tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 29, 'E todo o que tiver deixado casas, ou irmãos, ou irmãs, ou pai, ou mãe, ou filhos, ou terras, por amor do meu nome, receberá cem vezes tanto, e herdará a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(40, 19, 30, 'Entretanto, muitos que são primeiros serão últimos; e muitos que são últimos serão primeiros.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 1, 'Porque o reino dos céus é semelhante a um homem, proprietário, que saiu de madrugada a contratar trabalhadores para a sua vinha.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 2, 'Ajustou com os trabalhadores o salário de um denário por dia, e mandou-os para a sua vinha.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 3, 'Cerca da hora terceira saiu, e viu que estavam outros, ociosos, na praça,', 1, CURRENT_TIMESTAMP, false),
(40, 20, 4, 'e disse-lhes: Ide também vós para a vinha, e dar-vos-ei o que for justo. E eles foram.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 5, 'Outra vez saiu, cerca da hora sexta e da nona, e fez o mesmo.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 6, 'Responderam-lhe eles: Porque ninguém nos contratou. Disse-lhes ele: Ide também vós para a vinha.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 7, 'Responderam-lhe eles: Porque ninguém nos contratou. Disse-lhes ele: Ide também vós para a vinha.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 8, 'Ao anoitecer, disse o senhor da vinha ao seu mordomo: Chama os trabalhadores, e paga-lhes o salário, começando pelos últimos até os primeiros.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 9, 'Chegando, pois, os que tinham ido cerca da hora undécima, receberam um denário cada um.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 10, 'Vindo, então, os primeiros, pensaram que haviam de receber mais; mas do mesmo modo receberam um denário cada um.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 11, 'E ao recebê-lo, murmuravam contra o proprietário, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 20, 12, 'Estes últimos trabalharam somente uma hora, e os igualastes a nós, que suportamos a fadiga do dia inteiro e o forte calor.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 13, 'Mas ele, respondendo, disse a um deles: Amigo, não te faço injustiça; não ajustaste comigo um denário?', 1, CURRENT_TIMESTAMP, false),
(40, 20, 14, 'Toma o que é teu, e vai-te; eu quero dar a este último tanto como a ti.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 15, 'Não me é lícito fazer o que quero do que é meu? Ou é mau o teu olho porque eu sou bom?', 1, CURRENT_TIMESTAMP, false),
(40, 20, 16, 'Assim os últimos serão primeiros, e os primeiros serão últimos.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 17, 'Estando Jesus para subir a Jerusalém, chamou à parte os doze e no caminho lhes disse:', 1, CURRENT_TIMESTAMP, false),
(40, 20, 18, 'Eis que subimos a Jerusalém, e o Filho do homem será entregue aos principais sacerdotes e aos escribas, e eles o condenarão à morte,', 1, CURRENT_TIMESTAMP, false),
(40, 20, 19, 'e o entregarão aos gentios para que dele escarneçam, e o açoitem e crucifiquem; e ao terceiro dia ressuscitará.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 20, 'Aproximou-se dele, então, a mãe dos filhos de Zebedeu, com seus filhos, ajoelhando-se e fazendo-lhe um pedido.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 21, 'Perguntou-lhe Jesus: Que queres? Ela lhe respondeu: Concede que estes meus dois filhos se sentem, um à tua direita e outro à tua esquerda, no teu reino.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 22, 'Jesus, porém, replicou: Não sabeis o que pedis; podeis beber o cálice que eu estou para beber? Responderam-lhe: Podemos.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 23, 'Então lhes disse: O meu cálice certamente haveis de beber; mas o sentar-se à minha direita e à minha esquerda, não me pertence concedê-lo; mas isso é para aqueles para quem está preparado por meu Pai.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 24, 'E ouvindo isso os dez, indignaram-se contra os dois irmãos.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 25, 'Jesus, pois, chamou-os para junto de si e lhes disse: Sabeis que os governadores dos gentios os dominam, e os seus grandes exercem autoridades sobre eles.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 26, 'Não será assim entre vós; antes, qualquer que entre vós quiser tornar-se grande, será esse o que vos sirva;', 1, CURRENT_TIMESTAMP, false),
(40, 20, 27, 'e qualquer que entre vós quiser ser o primeiro, será vosso servo;', 1, CURRENT_TIMESTAMP, false),
(40, 20, 28, 'assim como o Filho do homem não veio para ser servido, mas para servir, e para dar a sua vida em resgate de muitos.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 29, 'Saindo eles de Jericó, seguiu-o uma grande multidão;', 1, CURRENT_TIMESTAMP, false),
(40, 20, 30, 'e eis que dois cegos, sentados junto do caminho, ouvindo que Jesus passava, clamaram, dizendo: Senhor, Filho de Davi, tem compaixão de nós.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 31, 'E a multidão os repreendeu, para que se calassem; eles, porém, clamaram ainda mais alto, dizendo: Senhor, Filho de Davi, tem compaixão de nós.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 32, 'E Jesus, parando, chamou-os e perguntou: Que quereis que vos faça?', 1, CURRENT_TIMESTAMP, false),
(40, 20, 33, 'Disseram-lhe eles: Senhor, que se nos abram os olhos.', 1, CURRENT_TIMESTAMP, false),
(40, 20, 34, 'E Jesus, movido de compaixão, tocou-lhes os olhos, e imediatamente recuperaram a vista, e o seguiram.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 1, 'Quando se aproximaram de Jerusalém, e chegaram a Betfagé, ao Monte das Oliveiras, enviou Jesus dois discípulos, dizendo-lhes:', 1, CURRENT_TIMESTAMP, false),
(40, 21, 2, 'Ide à aldeia que está defronte de vós, e logo encontrareis uma jumenta presa, e um jumentinho com ela; desprendei-a, e trazei-mos.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 3, 'E, se alguém vos disser alguma coisa, respondei: O Senhor precisa deles; e logo os enviará.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 4, 'Ora, isso aconteceu para que se cumprisse o que foi dito pelo profeta:', 1, CURRENT_TIMESTAMP, false),
(40, 21, 5, 'Dizei à filha de Sião: Eis que aí te vem o teu Rei, manso e montado em um jumento, em um jumentinho, cria de animal de carga.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 6, 'Indo, pois, os discípulos e fazendo como Jesus lhes ordenara,', 1, CURRENT_TIMESTAMP, false),
(40, 21, 7, 'trouxeram a jumenta e o jumentinho, e sobre eles puseram os seus mantos, e Jesus montou.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 8, 'E a maior parte da multidão estendeu os seus mantos pelo caminho; e outros cortavam ramos de árvores, e os espalhavam pelo caminho.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 9, 'E as multidões, tanto as que o precediam como as que o seguiam, clamavam, dizendo: Hosana ao Filho de Davi! bendito o que vem em nome do Senhor! Hosana nas alturas!', 1, CURRENT_TIMESTAMP, false),
(40, 21, 10, 'Ao entrar ele em Jerusalém, agitou-se a cidade toda e perguntava: Quem é este?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 11, 'E as multidões respondiam: Este é o profeta Jesus, de Nazaré da Galiléia.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 12, 'Então Jesus entrou no templo, expulsou todos os que ali vendiam e compravam, e derribou as mesas dos cambistas e as cadeiras dos que vendiam pombas;', 1, CURRENT_TIMESTAMP, false),
(40, 21, 13, 'e disse-lhes: Está escrito: A minha casa será chamada casa de oração; vós, porém, a fazeis covil de salteadores.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 14, 'E chegaram-se a ele no templo cegos e coxos, e ele os curou.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 15, 'Vendo, porém, os principais sacerdotes e os escribas as maravilhas que ele fizera, e os meninos que clamavam no templo: Hosana ao Filho de Davi, indignaram-se,', 1, CURRENT_TIMESTAMP, false),
(40, 21, 16, 'e perguntaram-lhe: Ouves o que estes estão dizendo? Respondeu-lhes Jesus: Sim; nunca lestes: Da boca de pequeninos e de criancinhas de peito tiraste perfeito louvor?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 17, 'E deixando-os, saiu da cidade para Betânia, e ali passou a noite.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 18, 'Ora, de manhã, ao voltar à cidade, teve fome;', 1, CURRENT_TIMESTAMP, false),
(40, 21, 19, 'e, avistando uma figueira à beira do caminho, dela se aproximou, e não achou nela senão folhas somente; e disse-lhe: Nunca mais nasça fruto de ti. E a figueira secou imediatamente.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 20, 'Quando os discípulos viram isso, perguntaram admirados: Como é que imediatamente secou a figueira?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 21, 'Jesus, porém, respondeu-lhes: Em verdade vos digo que, se tiverdes fé e não duvidardes, não só fareis o que foi feito à figueira, mas até, se a este monte disserdes: Ergue-te e lança-te no mar, isso será feito;', 1, CURRENT_TIMESTAMP, false),
(40, 21, 22, 'e tudo o que pedirdes na oração, crendo, recebereis.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 23, 'Tendo Jesus entrado no templo, e estando a ensinar, aproximaram-se dele os principais sacerdotes e os anciãos do povo, e perguntaram: Com que autoridade fazes tu estas coisas? e quem te deu tal autoridade?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 24, 'Respondeu-lhes Jesus: Eu também vos perguntarei uma coisa; se ma disserdes, eu de igual modo vos direi com que autoridade faço estas coisas.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 25, 'O batismo de João, donde era? do céu ou dos homens? Ao que eles arrazoavam entre si: Se dissermos: Do céu, ele nos dirá: Então por que não o crestes?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 26, 'Mas, se dissermos: Dos homens, tememos o povo; porque todos consideram João como profeta.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 27, 'Responderam, pois, a Jesus: Não sabemos. Disse-lhe ele: Nem eu vos digo com que autoridade faço estas coisas.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 28, 'Mas que vos parece? Um homem tinha dois filhos, e, chegando-se ao primeiro, disse: Filho, vai trabalhar hoje na vinha.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 29, 'Ele respondeu: Sim, senhor; mas não foi.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 30, 'Chegando-se, então, ao segundo, falou-lhe de igual modo; respondeu-lhe este: Não quero; mas depois, arrependendo-se, foi.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 31, 'Qual dos dois fez a vontade do pai? Disseram eles: O segundo. Disse-lhes Jesus: Em verdade vos digo que os publicanos e as meretrizes entram adiante de vós no reino de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 32, 'Pois João veio a vós no caminho da justiça, e não lhe deste crédito, mas os publicanos e as meretrizes lho deram; vós, porém, vendo isto, nem depois vos arrependestes para crerdes nele.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 33, 'Ouvi ainda outra parábola: Havia um homem, proprietário, que plantou uma vinha, cercou-a com uma sebe, cavou nela um lagar, e edificou uma torre; depois arrendou-a a uns lavradores e ausentou-se do país.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 34, 'E quando chegou o tempo dos frutos, enviou os seus servos aos lavradores, para receber os seus frutos.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 35, 'E os lavradores, apoderando-se dos servos, espancaram um, mataram outro, e a outro apedrejaram.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 36, 'Depois enviou ainda outros servos, em maior número do que os primeiros; e fizeram-lhes o mesmo.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 37, 'Por último enviou-lhes seu filho, dizendo: A meu filho terão respeito.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 38, 'Mas os lavradores, vendo o filho, disseram entre si: Este é o herdeiro; vinde, matemo-lo, e apoderemo-nos da sua herança.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 39, 'E, agarrando-o, lançaram-no fora da vinha e o mataram.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 40, 'Quando, pois, vier o senhor da vinha, que fará àqueles lavradores?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 41, 'Responderam-lhe eles: Fará perecer miseravelmente a esses maus, e arrendará a vinha a outros lavradores, que a seu tempo lhe entreguem os frutos.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 42, 'Disse-lhes Jesus: Nunca lestes nas Escrituras: A pedra que os edificadores rejeitaram, essa foi posta como pedra angular; pelo Senhor foi feito isso, e é maravilhoso aos nossos olhos?', 1, CURRENT_TIMESTAMP, false),
(40, 21, 43, 'Portanto eu vos digo que vos será tirado o reino de Deus, e será dado a um povo que dê os seus frutos.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 44, 'E quem cair sobre esta pedra será despedaçado; mas aquele sobre quem ela cair será reduzido a pó.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 45, 'Os principais sacerdotes e os fariseus, ouvindo essas parábolas, entenderam que era deles que Jesus falava.', 1, CURRENT_TIMESTAMP, false),
(40, 21, 46, 'E procuravam prendê-lo, mas temeram o povo, porquanto este o tinha por profeta.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 1, 'Então Jesus tornou a falar-lhes por parábolas, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 22, 2, 'O reino dos céus é semelhante a um rei, que celebrou as bodas de seu filho.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 3, 'Enviou os seus servos a chamar os convidados para a festa, e estes não quiseram vir.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 4, 'Enviou ainda outros servos com este recado: Dizei aos convidados: Tenho já preparado o meu banquete; as minhas reses e os meus cevados estão mortos, e tudo está pronto; vinde às bodas.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 5, 'Mas eles não fizeram caso e foram, um para o seu campo, outro para o seu negócio;', 1, CURRENT_TIMESTAMP, false),
(40, 22, 6, 'e os outros, agarrando os servos, os ultrajaram e mataram.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 7, 'Irou-se o rei, e mandou as suas tropas exterminar aqueles assassinos e incendiar a sua cidade.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 8, 'Então disse aos servos: As bodas estão preparadas, mas os convidados não eram dignos;', 1, CURRENT_TIMESTAMP, false),
(40, 22, 9, 'ide, pois, às encruzilhadas dos caminhos e chamai para as bodas a quantos encontrardes.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 10, 'Indo aqueles servos pelos caminhos, reuniram todos os que encontraram, maus e bons; e a sala nupcial ficou cheia de convivas.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 11, 'Mas entrando o rei para ver os convivas, notou ali um homem que não trajava veste nupcial,', 1, CURRENT_TIMESTAMP, false),
(40, 22, 12, 'e perguntou-lhe: Amigo, como entraste aqui sem veste nupcial? Ele, porém, emudeceu.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 13, 'Então o rei disse aos servos: Atai-o de pés e mãos, e lançai-o nas trevas exteriores; ali haverá o choro e o ranger de dentes.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 14, 'Pois muitos são chamados, mas poucos escolhidos.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 15, 'Então os fariseus se retiraram e consultaram entre si como o apanhariam em alguma palavra;', 1, CURRENT_TIMESTAMP, false),
(40, 22, 16, 'Enviaram os seus discípulos, juntamente com os herodianos, a perguntar: Mestre, sabemos que és verdadeiro e que ensinas o caminho de Deus segundo a verdade, e não se te dá de ninguém, porque não te deixas levar de respeitos humanos;', 1, CURRENT_TIMESTAMP, false),
(40, 22, 17, 'dize-nos, pois, qual é o teu parecer; é lícito ou não pagar o tributo a César?', 1, CURRENT_TIMESTAMP, false),
(40, 22, 18, 'Porém Jesus, tendo percebido a malícia deles, respondeu-lhes: Por que me experimentais, hipócritas?', 1, CURRENT_TIMESTAMP, false),
(40, 22, 19, 'Mostrai-me uma moeda de tributo. Trouxeram-lhe um denário.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 20, 'Ele perguntou: De quem é esta efígie e inscrição?', 1, CURRENT_TIMESTAMP, false),
(40, 22, 21, 'Responderam: De César. Então lhes disse Jesus: Dai, pois, a César o que é de César, e a Deus o que é de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 22, 'Ao ouvirem isto, admiraram-se e, deixando-o, foram-se.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 23, 'No mesmo dia vieram alguns saduceus, que dizem não haver ressurreição, e o interrogaram, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 22, 24, 'Mestre, Moisés disse: Se alguém morrer sem deixar filhos, seu irmão casará com a viúva e dará sucessão ao falecido.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 25, 'Ora havia entre nós sete irmãos: o primeiro, depois de ter casado, morreu e, não havendo sucessão, deixou sua mulher a seu irmão;', 1, CURRENT_TIMESTAMP, false),
(40, 22, 26, 'do mesmo modo também o segundo e o terceiro, até o sétimo.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 27, 'Depois de todos eles morreu a mulher.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 28, 'Na ressurreição, pois, a qual dos sete pertencerá a mulher? porque todos foram casados com ela.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 29, 'Respondeu-lhes Jesus: Errais, não sabendo as Escrituras, nem o poder de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 30, 'Pois na ressurreição nem os homens casam, nem as mulheres são dadas em casamento porém são como os anjos no céu.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 31, 'E, quanto à ressurreição dos mortos, não lestes o que foi dito por Deus:', 1, CURRENT_TIMESTAMP, false),
(40, 22, 32, 'Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó? Ora, ele não é Deus de mortos, mas de vivos.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 33, 'E as multidões, ouvindo isso, se maravilhavam da sua doutrina.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 34, 'Os fariseus, quando souberam, que ele fizera emudecer os saduceus, reuniram-se todos;', 1, CURRENT_TIMESTAMP, false),
(40, 22, 35, 'e um deles, doutor da lei, para o experimentar, interrogou-o, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 22, 36, 'Mestre, qual é o grande mandamento na lei?', 1, CURRENT_TIMESTAMP, false),
(40, 22, 37, 'Respondeu-lhe Jesus: Amarás ao Senhor teu Deus de todo o teu coração, de toda a tua alma, e de todo o teu entendimento.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 38, 'Este é o grande e primeiro mandamento.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 39, 'E o segundo, semelhante a este, é: Amarás ao teu próximo como a ti mesmo.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 40, 'Destes dois mandamentos dependem toda a lei e os profetas.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 41, 'Ora, enquanto os fariseus estavam reunidos, interrogou-os Jesus, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 22, 42, 'Que pensais vós do Cristo? De quem é filho? Responderam-lhe: De Davi.', 1, CURRENT_TIMESTAMP, false),
(40, 22, 43, 'Replicou-lhes ele: Como é então que Davi, no Espírito, lhe chama Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 22, 44, 'Disse o Senhor ao meu Senhor: Assenta-te à minha direita, até que eu ponha os teus inimigos de baixo dos teus pés?', 1, CURRENT_TIMESTAMP, false),
(40, 22, 45, 'Se Davi, pois, lhe chama Senhor, como é ele seu filho?', 1, CURRENT_TIMESTAMP, false),
(40, 22, 46, 'E ninguém podia responder-lhe palavra; nem desde aquele dia jamais ousou alguém interrogá-lo.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 1, 'Então falou Jesus às multidões e aos seus discípulos, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 23, 2, 'Na cadeira de Moisés se assentam os escribas e fariseus.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 3, 'Portanto, tudo o que vos disserem, isso fazei e observai; mas não façais conforme as suas obras; porque dizem e não praticam.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 4, 'Pois atam fardos pesados e difíceis de suportar, e os põem aos ombros dos homens; mas eles mesmos nem com o dedo querem movê-los.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 5, 'Todas as suas obras eles fazem a fim de serem vistos pelos homens; pois alargam os seus filactérios, e aumentam as franjas dos seus mantos;', 1, CURRENT_TIMESTAMP, false),
(40, 23, 6, 'gostam do primeiro lugar nos banquetes, das primeiras cadeiras nas sinagogas,', 1, CURRENT_TIMESTAMP, false),
(40, 23, 7, 'das saudações nas praças, e de serem chamados pelos homens: Rabi.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 8, 'Vós, porém, não queirais ser chamados Rabi; porque um só é o vosso Mestre, e todos vós sois irmãos.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 9, 'E a ninguém sobre a terra chameis vosso pai; porque um só é o vosso Pai, aquele que está nos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 10, 'Nem queirais ser chamados guias; porque um só é o vosso Guia, que é o Cristo.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 11, 'Mas o maior dentre vós há de ser vosso servo.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 12, 'Qualquer, pois, que a si mesmo se exaltar, será humilhado; e qualquer que a si mesmo se humilhar, será exaltado.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 13, 'Mas ai de vós, escribas e fariseus, hipócritas! porque fechais aos homens o reino dos céus; pois nem vós entrais, nem aos que entrariam permitis entrar.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 14, '{Ai de vós, escribas e fariseus, hipócritas! porque devorais as casas das viúvas e sob pretexto fazeis longas orações; por isso recebereis maior condenação.}', 1, CURRENT_TIMESTAMP, false),
(40, 23, 15, 'Ai de vós, escribas e fariseus, hipócritas! porque percorreis o mar e a terra para fazer um prosélito; e, depois de o terdes feito, o tornais duas vezes mais filho do inferno do que vós.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 16, 'Ai de vós, guias cegos! que dizeis: Quem jurar pelo ouro do santuário, esse fica obrigado ao que jurou.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 17, 'Insensatos e cegos! Pois qual é o maior; o ouro, ou o santuário que santifica o ouro?', 1, CURRENT_TIMESTAMP, false),
(40, 23, 18, 'E: Quem jurar pelo altar, isso nada é; mas quem jurar pela oferta que está sobre o altar, esse fica obrigado ao que jurou.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 19, 'Cegos! Pois qual é maior: a oferta, ou o altar que santifica a oferta?', 1, CURRENT_TIMESTAMP, false),
(40, 23, 20, 'Portanto, quem jurar pelo altar jura por ele e por tudo quanto sobre ele está;', 1, CURRENT_TIMESTAMP, false),
(40, 23, 21, 'e quem jurar pelo santuário jura por ele e por aquele que nele habita;', 1, CURRENT_TIMESTAMP, false),
(40, 23, 22, 'e quem jurar pelo céu jura pelo trono de Deus e por aquele que nele está assentado.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 23, 'Ai de vós, escribas e fariseus, hipócritas! porque dais o dízimo da hortelã, do endro e do cominho, e tendes omitido o que há de mais importante na lei, a saber, a justiça, a misericórdia e a fé; estas coisas, porém, devíeis fazer, sem omitir aquelas.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 24, 'Guias cegos! que coais um mosquito, e engolis um camelo.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 25, 'Ai de vós, escribas e fariseus, hipócritas! porque limpais o exterior do copo e do prato, mas por dentro estão cheios de rapina e de intemperança.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 26, 'Fariseu cego! limpa primeiro o interior do copo, para que também o exterior se torne limpo.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 27, 'Ai de vós, escribas e fariseus, hipócritas! porque sois semelhantes aos sepulcros caiados, que por fora realmente parecem formosos, mas por dentro estão cheios de ossos e de toda imundícia.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 28, 'Assim também vós exteriormente pareceis justos aos homens, mas por dentro estais cheios de hipocrisia e de iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 29, 'Ai de vós, escribas e fariseus, hipócritas! porque edificais os sepulcros dos profetas e adornais os monumentos dos justos,', 1, CURRENT_TIMESTAMP, false),
(40, 23, 30, 'e dizeis: Se tivéssemos vivido nos dias de nossos pais, não teríamos sido cúmplices no derramar o sangue dos profetas.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 31, 'Assim, vós testemunhais contra vós mesmos que sois filhos daqueles que mataram os profetas.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 32, 'Enchei vós, pois, a medida de vossos pais.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 33, 'Serpentes, raça de víboras! como escapareis da condenação do inferno?', 1, CURRENT_TIMESTAMP, false),
(40, 23, 34, 'Portanto, eis que eu vos envio profetas, sábios e escribas: e a uns deles matareis e crucificareis; e a outros os perseguireis de cidade em cidade;', 1, CURRENT_TIMESTAMP, false),
(40, 23, 35, 'para que sobre vós caia todo o sangue justo, que foi derramado sobre a terra, desde o sangue de Abel, o justo, até o sangue de Zacarias, filho de Baraquias, que mataste entre o santuário e o altar.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 36, 'Em verdade vos digo que todas essas coisas hão de vir sobre esta geração.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 37, 'Jerusalém, Jerusalém, que matas os profetas, apedrejas os que a ti são enviados! quantas vezes quis eu ajuntar os teus filhos, como a galinha ajunta os seus pintos debaixo das asas, e não o quiseste!', 1, CURRENT_TIMESTAMP, false),
(40, 23, 38, 'Eis aí abandonada vos é a vossa casa.', 1, CURRENT_TIMESTAMP, false),
(40, 23, 39, 'Pois eu vos declaro que desde agora de modo nenhum me vereis, até que digais: Bendito aquele que vem em nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 1, 'Ora, Jesus, tendo saído do templo, ia-se retirando, quando se aproximaram dele os seus discípulos, para lhe mostrarem os edifícios do templo.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 2, 'Mas ele lhes disse: Não vedes tudo isto? Em verdade vos digo que não se deixará aqui pedra sobre pedra que não seja derribada.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 3, 'E estando ele sentado no Monte das Oliveiras, chegaram-se a ele os seus discípulos em particular, dizendo: Declara-nos quando serão essas coisas, e que sinal haverá da tua vinda e do fim do mundo.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 4, 'Respondeu-lhes Jesus: Acautelai-vos, que ninguém vos engane.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 5, 'Porque muitos virão em meu nome, dizendo: Eu sou o Cristo; a muitos enganarão.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 6, 'E ouvireis falar de guerras e rumores de guerras; olhai não vos perturbeis; porque forçoso é que assim aconteça; mas ainda não é o fim.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 7, 'Porquanto se levantará nação contra nação, e reino contra reino; e haverá fomes e terremotos em vários lugares.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 8, 'Mas todas essas coisas são o princípio das dores.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 9, 'Então sereis entregues à tortura, e vos matarão; e sereis odiados de todas as nações por causa do meu nome.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 10, 'Nesse tempo muitos hão de se escandalizar, e trair-se uns aos outros, e mutuamente se odiarão.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 11, 'Igualmente hão de surgir muitos falsos profetas, e enganarão a muitos;', 1, CURRENT_TIMESTAMP, false),
(40, 24, 12, 'e, por se multiplicar a iniqüidade, o amor de muitos esfriará.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 13, 'Mas quem perseverar até o fim, esse será salvo.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 14, 'E este evangelho do reino será pregado no mundo inteiro, em testemunho a todas as nações, e então virá o fim.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 15, 'Quando, pois, virdes estar no lugar santo a abominação de desolação, predita pelo profeta Daniel {quem lê, entenda},', 1, CURRENT_TIMESTAMP, false),
(40, 24, 16, 'então os que estiverem na Judéia fujam para os montes;', 1, CURRENT_TIMESTAMP, false),
(40, 24, 17, 'quem estiver no eirado não desça para tirar as coisas de sua casa,', 1, CURRENT_TIMESTAMP, false),
(40, 24, 18, 'e quem estiver no campo não volte atrás para apanhar a sua capa.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 19, 'Mas ai das que estiverem grávidas, e das que amamentarem naqueles dias!', 1, CURRENT_TIMESTAMP, false),
(40, 24, 20, 'Orai para que a vossa fuga não suceda no inverno nem no sábado;', 1, CURRENT_TIMESTAMP, false),
(40, 24, 21, 'porque haverá então uma tribulação tão grande, como nunca houve desde o princípio do mundo até agora, nem jamais haverá.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 22, 'E se aqueles dias não fossem abreviados, ninguém se salvaria; mas por causa dos escolhidos serão abreviados aqueles dias.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 23, 'Se, pois, alguém vos disser: Eis aqui o Cristo! ou: Ei-lo aí! não acrediteis;', 1, CURRENT_TIMESTAMP, false),
(40, 24, 24, 'porque hão de surgir falsos cristos e falsos profetas, e farão grandes sinais e prodígios; de modo que, se possível fora, enganariam até os escolhidos.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 25, 'Eis que de antemão vo-lo tenho dito.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 26, 'Portanto, se vos disserem: Eis que ele está no deserto; não saiais; ou: Eis que ele está no interior da casa; não acrediteis.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 27, 'Porque, assim como o relâmpago sai do oriente e se mostra até o ocidente, assim será também a vinda do filho do homem.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 28, 'Pois onde estiver o cadáver, aí se ajuntarão os abutres.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 29, 'Logo depois da tribulação daqueles dias, escurecerá o sol, e a lua não dará a sua luz; as estrelas cairão do céu e os poderes dos céus serão abalados.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 30, 'Então aparecerá no céu o sinal do Filho do homem, e todas as tribos da terra se lamentarão, e verão vir o Filho do homem sobre as nuvens do céu, com poder e grande glória.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 31, 'E ele enviará os seus anjos com grande clangor de trombeta, os quais lhe ajuntarão os escolhidos desde os quatro ventos, de uma à outra extremidade dos céus.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 32, 'Aprendei, pois, da figueira a sua parábola: Quando já o seu ramo se torna tenro e brota folhas, sabeis que está próximo o verão.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 33, 'Igualmente, quando virdes todas essas coisas, sabei que ele está próximo, mesmo às portas.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 34, 'Em verdade vos digo que não passará esta geração sem que todas essas coisas se cumpram.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 35, 'Passará o céu e a terra, mas as minhas palavras jamais passarão.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 36, 'Daquele dia e hora, porém, ninguém sabe, nem os anjos do céu, nem o Filho, senão só o Pai.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 37, 'Pois como foi dito nos dias de Noé, assim será também a vinda do Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 38, 'Porquanto, assim como nos dias anteriores ao dilúvio, comiam, bebiam, casavam e davam-se em casamento, até o dia em que Noé entrou na arca,', 1, CURRENT_TIMESTAMP, false),
(40, 24, 39, 'e não o perceberam, até que veio o dilúvio, e os levou a todos; assim será também a vinda do Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 40, 'Então, estando dois homens no campo, será levado um e deixado outro;', 1, CURRENT_TIMESTAMP, false),
(40, 24, 41, 'estando duas mulheres a trabalhar no moinho, será levada uma e deixada a outra.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 42, 'Vigiai, pois, porque não sabeis em que dia vem o vosso Senhor;', 1, CURRENT_TIMESTAMP, false),
(40, 24, 43, 'sabei, porém, isto: se o dono da casa soubesse a que vigília da noite havia de vir o ladrão, vigiaria e não deixaria minar a sua casa.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 44, 'Por isso ficai também vós apercebidos; porque numa hora em que não penseis, virá o Filho do homem.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 45, 'Quem é, pois, o servo fiel e prudente, que o senhor pôs sobre os seus serviçais, para a tempo dar-lhes o sustento?', 1, CURRENT_TIMESTAMP, false),
(40, 24, 46, 'Bem-aventurado aquele servo a quem o seu senhor, quando vier, achar assim fazendo.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 47, 'Em verdade vos digo que o porá sobre todos os seus bens.', 1, CURRENT_TIMESTAMP, false),
(40, 24, 48, 'Mas se aquele outro, o mau servo, disser no seu coração: Meu senhor tarda em vir,', 1, CURRENT_TIMESTAMP, false),
(40, 24, 49, 'e começar a espancar os seus conservos, e a comer e beber com os ébrios,', 1, CURRENT_TIMESTAMP, false),
(40, 24, 50, 'virá o senhor daquele servo, num dia em que não o espera, e numa hora de que não sabe,', 1, CURRENT_TIMESTAMP, false),
(40, 24, 51, 'e cortá-lo-á pelo meio, e lhe dará a sua parte com os hipócritas; ali haverá choro e ranger de dentes.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 1, 'Então o reino dos céus será semelhante a dez virgens que, tomando as suas lâmpadas, saíram ao encontro do noivo.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 2, 'Cinco delas eram insensatas, e cinco prudentes.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 3, 'Ora, as insensatas, tomando as lâmpadas, não levaram azeite consigo.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 4, 'As prudentes, porém, levaram azeite em suas vasilhas, juntamente com as lâmpadas.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 5, 'E tardando o noivo, cochilaram todas, e dormiram.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 6, 'Mas à meia-noite ouviu-se um grito: Eis o noivo! saí-lhe ao encontro!', 1, CURRENT_TIMESTAMP, false),
(40, 25, 7, 'Então todas aquelas virgens se levantaram, e prepararam as suas lâmpadas.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 8, 'E as insensatas disseram às prudentes: Dai-nos do vosso azeite, porque as nossas lâmpadas estão se apagando.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 9, 'Mas as prudentes responderam: não; pois de certo não chegaria para nós e para vós; ide antes aos que o vendem, e comprai-o para vós.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 10, 'E, tendo elas ido comprá-lo, chegou o noivo; e as que estavam preparadas entraram com ele para as bodas, e fechou-se a porta.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 11, 'Depois vieram também as outras virgens, e disseram: Senhor, Senhor, abre-nos a porta.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 12, 'Ele, porém, respondeu: Em verdade vos digo, não vos conheço.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 13, 'Vigiai pois, porque não sabeis nem o dia nem a hora.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 14, 'Porque é assim como um homem que, ausentando-se do país, chamou os seus servos e lhes entregou os seus bens:', 1, CURRENT_TIMESTAMP, false),
(40, 25, 15, 'a um deu cinco talentos, a outro dois, e a outro um, a cada um segundo a sua capacidade; e seguiu viagem.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 16, 'O que recebera cinco talentos foi imediatamente negociar com eles, e ganhou outros cinco;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 17, 'da mesma sorte, o que recebera dois ganhou outros dois;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 18, 'mas o que recebera um foi e cavou na terra e escondeu o dinheiro do seu senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 19, 'Ora, depois de muito tempo veio o senhor daqueles servos, e fez contas com eles.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 20, 'Então chegando o que recebera cinco talentos, apresentou-lhe outros cinco talentos, dizendo: Senhor, entregaste-me cinco talentos; eis aqui outros cinco que ganhei.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 21, 'Disse-lhe o seu senhor: Muito bem, servo bom e fiel; sobre o pouco foste fiel, sobre muito te colocarei; entra no gozo do teu senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 22, 'Chegando também o que recebera dois talentos, disse: Senhor, entregaste-me dois talentos; eis aqui outros dois que ganhei.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 23, 'Disse-lhe o seu senhor: Muito bem, servo bom e fiel; sobre o pouco foste fiel, sobre muito te colocarei; entra no gozo do teu senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 24, 'Chegando por fim o que recebera um talento, disse: Senhor, eu te conhecia, que és um homem duro, que ceifas onde não semeaste, e recolhes onde não joeiraste;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 25, 'e, atemorizado, fui esconder na terra o teu talento; eis aqui tens o que é teu.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 26, 'Ao que lhe respondeu o seu senhor: Servo mau e preguiçoso, sabias que ceifo onde não semeei, e recolho onde não joeirei?', 1, CURRENT_TIMESTAMP, false),
(40, 25, 27, 'Devias então entregar o meu dinheiro aos banqueiros e, vindo eu, tê-lo-ia recebido com juros.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 28, 'Tirai-lhe, pois, o talento e dai ao que tem os dez talentos.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 29, 'Porque a todo o que tem, dar-se-lhe-á, e terá em abundância; mas ao que não tem, até aquilo que tem ser-lhe-á tirado.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 30, 'E lançai o servo inútil nas trevas exteriores; ali haverá choro e ranger de dentes.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 31, 'Quando, pois vier o Filho do homem na sua glória, e todos os anjos com ele, então se assentará no trono da sua glória;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 32, 'e diante dele serão reunidas todas as nações; e ele separará uns dos outros, como o pastor separa as ovelhas dos cabritos;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 33, 'e porá as ovelhas à sua direita, mas os cabritos à esquerda.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 34, 'Então dirá o Rei aos que estiverem à sua direita: Vinde, benditos de meu Pai. Possuí por herança o reino que vos está preparado desde a fundação do mundo;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 35, 'Pois tive fome, e destes-me de comer; tive sede, e destes-me de beber; era forasteiro, e recolhestes-me;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 36, 'estava nu, e vestistes-me; enfermo, e visitastes-me; preso, e viestes ver-me.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 37, 'Então perguntarão os justos: Senhor, quando te vimos faminto, e te demos de comer; ou com sede, e te demos de beber?', 1, CURRENT_TIMESTAMP, false),
(40, 25, 38, 'Quando te vimos forasteiro, e te recolhemos; ou nu, e te vestimos?', 1, CURRENT_TIMESTAMP, false),
(40, 25, 39, 'Quando te vimos enfermo, ou preso, e fomos visitar-te?', 1, CURRENT_TIMESTAMP, false),
(40, 25, 40, 'O Rei responderá: Em verdade vos digo que quantas vezes o fizestes a um destes meus irmãos mais pequeninos, a mim o fizestes.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 41, 'Dirá também aos que estiverem à sua esquerda: Apartai-vos de mim, malditos, para o fogo eterno, destinado ao Diabo e seus anjos.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 42, 'Pois tive fome, e não me destes de comer; tive sede e não me destes de beber;', 1, CURRENT_TIMESTAMP, false),
(40, 25, 43, 'era forasteiro, e não me recolhestes; estava nu, e não me vestistes; enfermo e preso, e não me visitastes.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 44, 'Também eles perguntarão: Senhor, quando te vimos faminto, com sede, forasteiro, nu, enfermo, ou preso, e não te servimos?', 1, CURRENT_TIMESTAMP, false),
(40, 25, 45, 'Então lhes responderá: Em verdade vos digo que quantas vezes o deixastes de fazer a um destes mais pequeninos, a mim o deixastes de fazer.', 1, CURRENT_TIMESTAMP, false),
(40, 25, 46, 'Irão estes para o suplício eterno, porém os justos para a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 1, 'E havendo Jesus concluído todas estas palavras, disse aos seus discípulos:', 1, CURRENT_TIMESTAMP, false),
(40, 26, 2, 'Sabeis que de hoje a dois dias celebrar-se-á a páscoa, e o Filho do homem será entregue para ser crucificado.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 3, 'Depois se reuniram os principais sacerdotes e os anciãos do povo no pátio da casa do sumo sacerdote, chamado Caifás;', 1, CURRENT_TIMESTAMP, false),
(40, 26, 4, 'e deliberaram prender a Jesus à traição e tirar-lhe a vida.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 5, 'Mas diziam: Durante a festa, não; para que não haja tumulto entre o povo.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 6, 'Estando Jesus em Betânia, em casa de Simão, o leproso,', 1, CURRENT_TIMESTAMP, false),
(40, 26, 7, 'chegou-se a ele uma mulher que trazia um vaso de alabastro com precioso perfume, e lho derramou sobre a cabeça, quando ele estava à mesa.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 8, 'Vendo isto, seus discípulos indignaram-se e disseram:', 1, CURRENT_TIMESTAMP, false),
(40, 26, 9, 'Para que este desperdício? Pois o perfume podia ser vendido por muito dinheiro, e ser este dado aos pobres.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 10, 'Mas Jesus, percebendo isto, disse-lhes: Por que molestais essa mulher? ela me fez uma boa obra.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 11, 'Pois os pobres sempre os tendes convosco, mas a mim nem sempre me tendes;', 1, CURRENT_TIMESTAMP, false),
(40, 26, 12, 'derramando ela este perfume sobre o meu corpo, fê-lo para a minha sepultura.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 13, 'Em verdade vos digo que onde quer que for pregado em todo o mundo este Evangelho, será também contado para memória sua o que ela fez.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 14, 'Então um dos doze, chamado Judas Iscariotes, foi ter com os principais sacerdotes,', 1, CURRENT_TIMESTAMP, false),
(40, 26, 15, 'e lhes disse: Que me quereis dar e eu vo-lo entregarei? Eles lhe pesaram trinta moedas de prata.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 16, 'Desde então Judas buscava oportunidade para o entregar.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 17, 'Ora, no primeiro dia dos pães ázimos, vieram os discípulos a Jesus, e perguntaram: Onde queres que façamos os preparativos para comeres a páscoa?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 18, 'Respondeu-lhes: Ide à cidade ter com certo homem, e dizei-lhe que o Mestre diz: O meu tempo está próximo; em tua casa celebrarei a páscoa com meus discípulos.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 19, 'Eles fizeram como Jesus lhes havia ordenado, e prepararam a páscoa.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 20, 'À tarde estava ele sentado à mesa com os doze discípulos.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 21, 'Enquanto comiam, declarou Jesus: Em verdade vos digo que um de vós me trairá.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 22, 'Eles, muitíssimo contristados, começaram um por um a perguntar-lhe: Porventura sou eu, Senhor?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 23, 'Ele respondeu: O que põe comigo a mão no prato, esse é o que me trairá.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 24, 'O Filho do homem vai-se, segundo está escrito a seu respeito, mas ai daquele por quem o Filho do homem é traído! melhor fora para esse homem se não houvesse nascido.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 25, 'Judas, que o traiu, perguntou: Porventura sou eu, Mestre? Respondeu-lhe Jesus: Tu o disseste.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 26, 'Enquanto comiam, Jesus tomou o pão e, abençoando-o, o partiu e o deu aos discípulos, dizendo: Tomai, comei; isto é o meu corpo.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 27, 'Tomando o cálice, rendeu graças e deu-lho, dizendo: Bebei dele todos;', 1, CURRENT_TIMESTAMP, false),
(40, 26, 28, 'porque este é o meu sangue, o sangue da aliança, que é derramado por muitos para remissão de pecados.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 29, 'Mas digo-vos que desta hora em diante não beberei deste fruto da videira, até aquele dia em que o hei de beber novo convosco no reino de meu Pai.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 30, 'E tendo cantado um hino, saíram para o Monte das Oliveiras.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 31, 'Então Jesus lhes disse: Todos vós esta noite vos escandalizareis de mim; pois está escrito: Ferirei o pastor, e as ovelhas do rebanho se dispersarão.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 32, 'Todavia, depois que eu ressurgir, irei adiante de vós para a Galiléia.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 33, 'Mas Pedro, respondendo, disse-lhe: Ainda que todos se escandalizem de ti, eu nunca me escandalizarei.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 34, 'Disse-lhe Jesus: Em verdade te digo que esta noite, antes que o galo cante três vezes me negarás.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 35, 'Respondeu-lhe Pedro: Ainda que me seja necessário morrer contigo, de modo algum te negarei. E o mesmo disseram todos os discípulos.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 36, 'Então foi Jesus com eles a um lugar chamado Getsêmani, e disse aos discípulos: Sentai-vos aqui, enquanto eu vou ali orar.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 37, 'E levando consigo Pedro e os dois filhos de Zebedeu, começou a entristecer-se e a angustiar-se.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 38, 'Então lhes disse: A minha alma está triste até a morte; ficai aqui e vigiai comigo.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 39, 'E adiantando-se um pouco, prostrou-se com o rosto em terra e orou, dizendo: Meu Pai, se é possível, passa de mim este cálice; todavia, não seja como eu quero, mas como tu queres.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 40, 'Voltando para os discípulos, achou-os dormindo; e disse a Pedro: Assim nem uma hora pudestes vigiar comigo?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 41, 'Vigiai e orai, para que não entreis em tentação; o espírito, na verdade, está pronto, mas a carne é fraca.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 42, 'Retirando-se mais uma vez, orou, dizendo: Pai meu, se este cálice não pode passar sem que eu o beba, faça-se a tua vontade.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 43, 'E, voltando outra vez, achou-os dormindo, porque seus olhos estavam carregados.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 44, 'Deixando-os novamente, foi orar terceira vez, repetindo as mesmas palavras.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 45, 'Então voltou para os discípulos e disse-lhes: Dormi agora e descansai. Eis que é chegada a hora, e o Filho do homem está sendo entregue nas mãos dos pecadores.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 46, 'Levantai-vos, vamo-nos; eis que é chegado aquele que me trai.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 47, 'E estando ele ainda a falar, eis que veio Judas, um dos doze, e com ele grande multidão com espadas e varapaus, vinda da parte dos principais sacerdotes e dos anciãos do povo.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 48, 'Ora, o que o traía lhes havia dado um sinal, dizendo: Aquele que eu beijar, esse é: prendei-o.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 49, 'E logo, aproximando-se de Jesus disse: Salve, Rabi. E o beijou.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 50, 'Jesus, porém, lhe disse: Amigo, a que vieste? Nisto, aproximando-se eles, lançaram mão de Jesus, e o prenderam.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 51, 'E eis que um dos que estavam com Jesus, estendendo a mão, puxou da espada e, ferindo o servo do sumo sacerdote, cortou-lhe uma orelha.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 52, 'Então Jesus lhe disse: Mete a tua espada no seu lugar; porque todos os que lançarem mão da espada, à espada morrerão.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 53, 'Ou pensas tu que eu não poderia rogar a meu Pai, e que ele não me mandaria agora mesmo mais de doze legiões de anjos?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 54, 'Como, pois, se cumpririam as Escrituras, que dizem que assim convém que aconteça?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 55, 'Disse Jesus à multidão naquela hora: Saístes com espadas e varapaus para me prender, como a um salteador? Todos os dias estava eu sentado no templo ensinando, e não me prendestes.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 56, 'Mas tudo isso aconteceu para que se cumprissem as Escrituras dos profetas. Então todos os discípulos, deixando-o fugiram.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 57, 'Aqueles que prenderam a Jesus levaram-no à presença do sumo sacerdote Caifás, onde os escribas e os anciãos estavam reunidos.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 58, 'E Pedro o seguia de longe até o pátio do sumo sacerdote; e entrando, sentou-se entre os guardas, para ver o fim.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 59, 'Ora, os principais sacerdotes e todo o sinédrio buscavam falso testemunho contra Jesus, para poderem entregá-lo à morte;', 1, CURRENT_TIMESTAMP, false),
(40, 26, 60, 'e não achavam, apesar de se apresentarem muitas testemunhas falsas. Mas por fim compareceram duas,', 1, CURRENT_TIMESTAMP, false),
(40, 26, 61, 'e disseram: Este disse: Posso destruir o santuário de Deus, e reedificá-lo em três dias.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 62, 'Levantou-se então o sumo sacerdote e perguntou-lhe: Nada respondes? Que é que estes depõem contra ti?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 63, 'Jesus, porém, guardava silêncio. E o sumo sacerdote disse-lhe: Conjuro-te pelo Deus vivo que nos digas se tu és o Cristo, o Filho do Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 64, 'Respondeu-lhe Jesus: É como disseste; contudo vos digo que vereis em breve o Filho do homem assentado à direita do Poder, e vindo sobre as nuvens do céu.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 65, 'Então o sumo sacerdote rasgou as suas vestes, dizendo: Blasfemou; para que precisamos ainda de testemunhas? Eis que agora acabais de ouvir a sua blasfêmia.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 66, 'Que vos parece? Responderam eles: É réu de morte.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 67, 'Então uns lhe cuspiram no rosto e lhe deram socos;', 1, CURRENT_TIMESTAMP, false),
(40, 26, 68, 'e outros o esbofetearam, dizendo: Profetiza-nos, ó Cristo, quem foi que te bateu?', 1, CURRENT_TIMESTAMP, false),
(40, 26, 69, 'Ora, Pedro estava sentado fora, no pátio; e aproximou-se dele uma criada, que disse: Tu também estavas com Jesus, o galileu.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 70, 'Mas ele negou diante de todos, dizendo: Não sei o que dizes.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 71, 'E saindo ele para o vestíbulo, outra criada o viu, e disse aos que ali estavam: Este também estava com Jesus, o nazareno.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 72, 'E ele negou outra vez, e com juramento: Não conheço tal homem.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 73, 'E daí a pouco, aproximando-se os que ali estavam, disseram a Pedro: Certamente tu também és um deles pois a tua fala te denuncia.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 74, 'Então começou ele a praguejar e a jurar, dizendo: Não conheço esse homem. E imediatamente o galo cantou.', 1, CURRENT_TIMESTAMP, false),
(40, 26, 75, 'E Pedro lembrou-se do que dissera Jesus: Antes que o galo cante, três vezes me negarás. E, saindo dali, chorou amargamente.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 1, 'Ora, chegada a manhã, todos os principais sacerdotes e os anciãos do povo entraram em conselho contra Jesus, para o matarem;', 1, CURRENT_TIMESTAMP, false),
(40, 27, 2, 'e, maniatando-o, levaram-no e o entregaram a Pilatos, o governador.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 3, 'Então Judas, aquele que o traíra, vendo que Jesus fora condenado, devolveu, compungido, as trinta moedas de prata aos anciãos, dizendo:', 1, CURRENT_TIMESTAMP, false),
(40, 27, 4, 'Pequei, traindo o sangue inocente. Responderam eles: Que nos importa? Seja isto lá contigo.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 5, 'E tendo ele atirado para dentro do santuário as moedas de prata, retirou-se, e foi enforcar-se.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 6, 'Os principais sacerdotes, pois, tomaram as moedas de prata, e disseram: Não é lícito metê-las no cofre das ofertas, porque é preço de sangue.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 7, 'E, tendo deliberado em conselho, compraram com elas o campo do oleiro, para servir de cemitério para os estrangeiros.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 8, 'Por isso tem sido chamado aquele campo, até o dia de hoje, Campo de Sangue.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 9, 'Cumpriu-se, então, o que foi dito pelo profeta Jeremias: Tomaram as trinta moedas de prata, preço do que foi avaliado, a quem certos filhos de Israel avaliaram,', 1, CURRENT_TIMESTAMP, false),
(40, 27, 10, 'e deram-nas pelo campo do oleiro, assim como me ordenou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 11, 'Jesus, pois, ficou em pé diante do governador; e este lhe perguntou: És tu o rei dos judeus? Respondeu-lhe Jesus: É como dizes.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 12, 'Mas ao ser acusado pelos principais sacerdotes e pelos anciãos, nada respondeu.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 13, 'Perguntou-lhe então Pilatos: Não ouves quantas coisas testificam contra ti?', 1, CURRENT_TIMESTAMP, false),
(40, 27, 14, 'E Jesus não lhe respondeu a uma pergunta sequer; de modo que o governador muito se admirava.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 15, 'Ora, por ocasião da festa costumava o governador soltar um preso, escolhendo o povo aquele que quisesse.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 16, 'Nesse tempo tinham um preso notório, chamado Barrabás.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 17, 'Portanto, estando o povo reunido, perguntou-lhe Pilatos: Qual quereis que vos solte? Barrabás, ou Jesus, chamado o Cristo?', 1, CURRENT_TIMESTAMP, false),
(40, 27, 18, 'Pois sabia que por inveja o haviam entregado.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 19, 'E estando ele assentado no tribunal, sua mulher mandou dizer-lhe: Não te envolvas na questão desse justo, porque muito sofri hoje em sonho por causa dele.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 20, 'Mas os principais sacerdotes e os anciãos persuadiram as multidões a que pedissem Barrabás e fizessem morrer Jesus.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 21, 'O governador, pois, perguntou-lhes: Qual dos dois quereis que eu vos solte? E disseram: Barrabás.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 22, 'Tornou-lhes Pilatos: Que farei então de Jesus, que se chama Cristo? Disseram todos: Seja crucificado.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 23, 'Pilatos, porém, disse: Pois que mal fez ele? Mas eles clamavam ainda mais: Seja crucificado.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 24, 'Ao ver Pilatos que nada conseguia, mas pelo contrário que o tumulto aumentava, mandando trazer água, lavou as mãos diante da multidão, dizendo: Sou inocente do sangue deste homem; seja isso lá convosco.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 25, 'E todo o povo respondeu: O seu sangue caia sobre nós e sobre nossos filhos.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 26, 'Nisso os soldados do governador levaram Jesus ao pretório, e reuniram em torno dele toda a corte.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 27, 'E, despindo-o, vestiram-lhe um manto escarlate;', 1, CURRENT_TIMESTAMP, false),
(40, 27, 28, 'e tecendo uma coroa de espinhos, puseram-lha na cabeça, e na mão direita uma cana, e ajoelhando-se diante dele, o escarneciam, dizendo: Salve, rei dos judeus!', 1, CURRENT_TIMESTAMP, false),
(40, 27, 29, 'E, cuspindo nele, tiraram-lhe a cana, e davam-lhe com ela na cabeça.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 30, 'Depois de o terem escarnecido, despiram-lhe o manto, puseram-lhe as suas vestes, e levaram-no para ser crucificado.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 31, 'Ao saírem, encontraram um homem cireneu, chamado Simão, a quem obrigaram a levar a cruz de Jesus.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 32, 'Quando chegaram ao lugar chamado Gólgota, que quer dizer, lugar da Caveira,', 1, CURRENT_TIMESTAMP, false),
(40, 27, 33, 'deram-lhe a beber vinho misturado com fel; mas ele, provando-o, não quis beber.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 34, 'Então, depois de o crucificarem, repartiram as vestes dele, lançando sortes, {para que se cumprisse o que foi dito pelo profeta: Repartiram entre si as minhas vestes, e sobre a minha túnica deitaram sortes.}', 1, CURRENT_TIMESTAMP, false),
(40, 27, 35, 'E, sentados, ali o guardavam.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 36, 'Puseram-lhe por cima da cabeça a sua acusação escrita: ESTE É JESUS, O REI DOS JUDEUS.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 37, 'Então foram crucificados com ele dois salteadores, um à direita, e outro à esquerda.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 38, 'E os que iam passando blasfemavam dele, meneando a cabeça', 1, CURRENT_TIMESTAMP, false),
(40, 27, 39, 'e dizendo: Tu, que destróis o santuário e em três dias o reedificas, salva-te a ti mesmo; se és Filho de Deus, desce da cruz.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 40, 'De igual modo também os principais sacerdotes, com os escribas e anciãos, escarnecendo, diziam:', 1, CURRENT_TIMESTAMP, false),
(40, 27, 41, 'A outros salvou; a si mesmo não pode salvar. Rei de Israel é ele; desça agora da cruz, e creremos nele;', 1, CURRENT_TIMESTAMP, false),
(40, 27, 42, 'confiou em Deus, livre-o ele agora, se lhe quer bem; porque disse: Sou Filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 43, 'O mesmo lhe lançaram em rosto também os salteadores que com ele foram crucificados.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 44, 'E, desde a hora sexta, houve trevas sobre toda a terra, até a hora nona.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 45, 'Cerca da hora nona, bradou Jesus em alta voz, dizendo: Eli, Eli, lamá sabactani; isto é, Deus meu, Deus meu, por que me desamparaste?', 1, CURRENT_TIMESTAMP, false),
(40, 27, 46, 'Alguns dos que ali estavam, ouvindo isso, diziam: Ele chama por Elias.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 47, 'E logo correu um deles, tomou uma esponja, ensopou-a em vinagre e, pondo-a numa cana, dava-lhe de beber.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 48, 'Os outros, porém, disseram: Deixa, vejamos se Elias vem salvá-lo.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 49, 'De novo bradou Jesus com grande voz, e entregou o espírito.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 50, 'E eis que o véu do santuário se rasgou em dois, de alto a baixo; a terra tremeu, as pedras se fenderam,', 1, CURRENT_TIMESTAMP, false),
(40, 27, 51, 'os sepulcros se abriram, e muitos corpos de santos que tinham dormido foram ressuscitados;', 1, CURRENT_TIMESTAMP, false),
(40, 27, 52, 'e, saindo dos sepulcros, depois da ressurreição dele, entraram na cidade santa, e apareceram a muitos.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 53, 'ora, o centurião e os que com ele guardavam Jesus, vendo o terremoto e as coisas que aconteciam, tiveram grande temor, e disseram: Verdadeiramente este era filho de Deus.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 54, 'Também estavam ali, olhando de longe, muitas mulheres que tinham seguido Jesus desde a Galiléia para o ouvir;', 1, CURRENT_TIMESTAMP, false),
(40, 27, 55, 'entre as quais se achavam Maria Madalena, Maria, mãe de Tiago e de José, e a mãe dos filhos de Zebedeu.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 56, 'Ao cair da tarde, veio um homem rico de Arimatéia, chamado José, que também era discípulo de Jesus.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 57, 'Esse foi a Pilatos e pediu o corpo de Jesus. Então Pilatos mandou que lhe fosse entregue.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 58, 'E José, tomando o corpo, envolveu-o num pano limpo, de linho,', 1, CURRENT_TIMESTAMP, false),
(40, 27, 59, 'e depositou-o no seu sepulcro novo, que havia aberto em rocha; e, rodando uma grande pedra para a porta do sepulcro, retirou-se.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 60, 'Mas achavam-se ali Maria Madalena e a outra Maria, sentadas defronte do sepulcro.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 61, 'No dia seguinte, isto é, o dia depois da preparação, reuniram-se os principais sacerdotes e os fariseus perante Pilatos,', 1, CURRENT_TIMESTAMP, false),
(40, 27, 62, 'e disseram: Senhor, lembramo-nos de que aquele embusteiro, quando ainda vivo, afirmou: Depois de três dias ressurgirei.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 63, 'Manda, pois, que o sepulcro seja guardado com segurança até o terceiro dia; para não suceder que, vindo os discípulos, o furtem e digam ao povo: Ressurgiu dos mortos; e assim o último embuste será pior do que o primeiro.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 64, 'Disse-lhes Pilatos: Tendes uma guarda; ide, tornai-o seguro, como entendeis.', 1, CURRENT_TIMESTAMP, false),
(40, 27, 65, 'Foram, pois, e tornaram seguro o sepulcro, selando a pedra, e deixando ali a guarda.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 1, 'No fim do sábado, quando já despontava o primeiro dia da semana, Maria Madalena e a outra Maria foram ver o sepulcro.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 2, 'E eis que houvera um grande terremoto; pois um anjo do Senhor descera do céu e, chegando-se, removera a pedra e estava sentado sobre ela.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 3, 'o seu aspecto era como um relâmpago, e as suas vestes brancas como a neve.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 4, 'E de medo dele tremeram os guardas, e ficaram como mortos.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 5, 'Mas o anjo disse às mulheres: Não temais vós; pois eu sei que buscais a Jesus, que foi crucificado.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 6, 'Não está aqui, porque ressurgiu, como ele disse. Vinde, vede o lugar onde jazia;', 1, CURRENT_TIMESTAMP, false),
(40, 28, 7, 'e ide depressa, e dizei aos seus discípulos que ressurgiu dos mortos; e eis que vai adiante de vós para a Galiléia; ali o vereis. Eis que vo-lo tenho dito.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 8, 'E, partindo elas pressurosamente do sepulcro, com temor e grande alegria, correram a anunciá-lo aos discípulos.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 9, 'E eis que Jesus lhes veio ao encontro, dizendo: Salve. E elas, aproximando-se, abraçaram-lhe os pés, e o adoraram.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 10, 'Então lhes disse Jesus: Não temais; ide dizer a meus irmãos que vão para a Galiléia; ali me verão.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 11, 'Ora, enquanto elas iam, eis que alguns da guarda foram à cidade, e contaram aos principais sacerdotes tudo quanto havia acontecido.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 12, 'E congregados eles com os anciãos e tendo consultado entre si, deram muito dinheiro aos soldados,', 1, CURRENT_TIMESTAMP, false),
(40, 28, 13, 'e ordenaram-lhes que dissessem: Vieram de noite os seus discípulos e, estando nós dormindo, furtaram-no.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 14, 'E, se isto chegar aos ouvidos do governador, nós o persuadiremos, e vos livraremos de cuidado.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 15, 'Então eles, tendo recebido o dinheiro, fizeram como foram instruídos. E essa história tem-se divulgado entre os judeus até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 16, 'Partiram, pois, os onze discípulos para a Galiléia, para o monte onde Jesus lhes designara.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 17, 'Quando o viram, o adoraram; mas alguns duvidaram.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 18, 'E, aproximando-se Jesus, falou-lhes, dizendo: Foi-me dada toda a autoridade no céu e na terra.', 1, CURRENT_TIMESTAMP, false),
(40, 28, 19, 'Portanto ide, fazei discípulos de todas as nações, batizando-os em nome do Pai, e do Filho, e do Espírito Santo;', 1, CURRENT_TIMESTAMP, false),
(40, 28, 20, 'ensinando-os a observar todas as coisas que eu vos tenho mandado; e eis que eu estou convosco todos os dias, até a consumação dos séculos.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 1, 'A palavra do Senhor que veio a Miquéias, morastita, nos dias de Jotão Acaz e Ezequias reis de Judá a qual ele viu sobre Samária e Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 2, 'Ouvi, todos os povos; presta atenção, ó terra, e tudo o que nela há; e seja testemunha contra vós o Senhor Deus, o Senhor desde o seu santo templo.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 3, 'Porque eis que o Senhor está a sair do seu lugar, e descerá, e andará sobre as alturas da terra.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 4, 'Os montes debaixo dele se derreterão, e os vales se fenderão, como a cera diante do fogo, como as águas que se precipitam por um declive.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 5, 'Sucede tudo isso por causa da transgressão de Jacó, e por causa dos pecados da casa de Israel. Qual é a transgressão de Jacó? não é Samária? e quais os altos de Judá? não é Jerusalém?', 1, CURRENT_TIMESTAMP, false),
(33, 1, 6, 'Por isso farei de Samária um montão de pedras do campo, uma terra de plantar vinhas; e farei rebolar as suas pedras para o vale, e descobrirei os seus fundamentos.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 7, 'Todas as suas imagens esculpidas serão despedaçadas, todos os seus salários serão queimados pelo fogo, e de todos os seus ídolos farei uma assolação; porque pelo salário de prostituta os ajuntou, e em salário de prostituta se tornarão.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 8, 'Por isso lamentarei e uivarei, andarei despojado e nu farei lamentação como de chacais, e pranto como de avestruzes.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 9, 'Pois as suas feridas são incuráveis, e o mal chegou até Judá; estendeu-se até a porta do meu povo, até Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 10, 'Não o anuncieis em Gate, em Aco não choreis; em Bete-Le-Afra revolvei-vos no pó.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 11, 'Passa, ó moradora de Safir, em vergonhosa nudez; a moradora de Zaanã não saiu; o pranto de Bete-Ezel tomará de vós a sua morada.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 12, 'Pois a moradora de Marote espera ansiosamente pelo bem; porque desceu do Senhor o mal até a porta de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 13, 'Ata ao carro o cavalo ligeiro, ó moradora de Laquis; esta foi o princípio do pecado para a filha de Sião; pois em ti se acharam as transgressões de Israel.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 14, 'Por isso darás a Moresete-Gate presentes de despedida; as casas de Aczibe se tornarão em engano para os reis de Israel.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 15, 'Ainda trarei a ti, o moradora de Maressa, aquele que te possuirá; chegará até Adulão a glória de Israel.', 1, CURRENT_TIMESTAMP, false),
(33, 1, 16, 'Faze-te calva e tosquia-te por causa dos filhos das tuas delícias; alarga a tua calva como a águia, porque de ti serão levados para o cativeiro.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 1, 'Ai daqueles que nas suas camas maquinam a iniqüidade e planejam o mal! quando raia o dia, põem-no por obra, pois está no poder da sua mão.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 2, 'E cobiçam campos, e os arrebatam, e casas, e as tomam; assim fazem violência a um homem e à sua casa, a uma pessoa e à sua herança.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 3, 'Portanto, assim diz o Senhor. Eis que contra esta família maquino um mal, de que não retirareis os vossos pescoços; e não andareis arrogantemente; porque o tempo será mau.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 4, 'Naquele dia surgirá contra vós um motejo, e se levantará pranto lastimoso, dizendo: Nós estamos inteiramente despojados; a porção do meu povo ele a troca; como ele a remove de mim! aos rebeldes reparte os nossos campos.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 5, 'Portanto, não terás tu na congregação do Senhor quem lance o cordel pela sorte', 1, CURRENT_TIMESTAMP, false),
(33, 2, 6, 'Não profetizeis; assim profetizam eles, não se deve profetizar tais coisas; não nos alcançará o opróbrio.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 7, 'Acaso dir-se-á isso, ó casa de Jacó: tem-se restringido o Espírito do Senhor? são estas as suas obras? e não é assim que fazem bem as minhas palavras ao que anda retamente?', 1, CURRENT_TIMESTAMP, false),
(33, 2, 8, 'Mas há pouco se levantou o meu povo como um inimigo; de sobre a vestidura arrancais o manto aos que passam seguros, como homens contrários à guerra.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 9, 'As mulheres do meu povo, vós as lançais das suas casas agradáveis; dos seus filhinhos tirais para sempre a minha glória.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 10, 'Levantai-vos, e ide-vos, pois este não é lugar de descanso; por causa da imundícia que traz destruição, sim, destruição enorme.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 11, 'Se algum homem, andando em espírito de falsidade, mentir, dizendo: Eu te profetizarei acerca do vinho e da bebida forte; será esse tal o profeta deste povo.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 12, 'Certamente te ajuntarei todo, ó Jacó; certamente congregarei o restante de Israel; pô-los-ei todos juntos, como ovelhas no curral, como rebanho no meio do seu pasto; farão estrondo por causa da multidão dos homens.', 1, CURRENT_TIMESTAMP, false),
(33, 2, 13, 'Subirá diante deles aquele que abre o caminho; eles romperão, e entrarão pela porta, e sairão por ela; e o rei irá adiante deles, e o Senhor à testa deles.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 1, 'E disse eu: Ouvi, peço-vos, ó chefes de Jacó, e vós, ó príncipes da casa de Israel: não é a vós que pertence saber a justiça?', 1, CURRENT_TIMESTAMP, false),
(33, 3, 2, 'A vós que aborreceis o bem, e amais o mal, que arrancais a pele de cima deles, e a carne de cima dos seus ossos,', 1, CURRENT_TIMESTAMP, false),
(33, 3, 3, 'os que também comeis a carne do meu povo e lhes arrancais a pele, e lhes esmiuçais os ossos, e os repartis em pedaços como para a panela e como carne dentro do caldeirão.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 4, 'Então clamarão ao Senhor; ele, porém, não lhes responderá, antes esconderá deles a sua face naquele tempo, conforme eles fizeram mal nas suas obras.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 5, 'Assim diz o Senhor a respeito dos profetas que fazem errar o meu povo, que clamam: Paz! enquanto têm o que comer, mas preparam a guerra contra aquele que nada lhes mete na boca.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 6, 'Portanto se vos fará noite sem visão; e trevas sem adivinhação haverá para vós. Assim se porá o sol sobre os profetas, e sobre eles, obscurecerá o dia.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 7, 'E os videntes se envergonharão, e os adivinhadores se confundirão; sim, todos eles cobrirão os seus lábios, porque não haverá resposta de Deus.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 8, 'Quanto a mim, estou cheio do poder do Espírito do Senhor, assim como de justiça e de coragem, para declarar a Jacó a sua transgressão e a Israel o seu pecado.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 9, 'Ouvi agora isto, vós chefes da casa de Jacó, e vós governantes da casa de Israel, que abominais a justiça e perverteis tudo o que é direito,', 1, CURRENT_TIMESTAMP, false),
(33, 3, 10, 'edificando a Sião com sangue, e a Jerusalém com iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 11, 'Os seus chefes dão as sentenças por peitas, e os seus sacerdotes ensinam por interesse, e os seus profetas adivinham por dinheiro; e ainda se encostam ao Senhor, dizendo: Não está o Senhor no meio de nós? nenhum mal nos sobrevirá.', 1, CURRENT_TIMESTAMP, false),
(33, 3, 12, 'Portanto, por causa de vós, Sião será lavrada como um campo, e Jerusalém se tornará em montões de pedras, e o monte desta casa em lugares altos dum bosque.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 1, 'Mas nos últimos dias acontecerá que o monte da casa do Senhor será estabelecido como o mais alto dos montes, e se exalçará sobre os outeiros, e a ele concorram os povos.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 2, 'E irão muitas nações, e dirão: Vinde, e subamos ao monte do Senhor, e à casa do Deus de Jacó, para que nos ensine os seus caminhos, de sorte que andemos nas suas veredas; porque de Sião sairá a lei, e de Jerusalém a palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 3, 'E julgará entre muitos povos, e arbitrará entre nações poderosas e longínquas; e converterão as suas espadas em relhas de arado, e as suas lanças em podadeiras; uma nação não levantará a espada contra outra nação, nem aprenderão mais a guerra.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 4, 'Mas assentar-se-á cada um debaixo da sua videira, e debaixo da sua figueira, e não haverá quem os espante, porque a boca do Senhor dos exércitos o disse.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 5, 'Pois todos os povos andam, cada um em nome do seu deus; mas nós andaremos para todo o sempre em o nome do Senhor nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 6, 'Naquele dia, diz o Senhor, congregarei a que coxeava, e recolherei a que tinha sido expulsa, e a que eu afligi.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 7, 'E da que coxeava farei um resto, e da que tinha sido arrojada para longe, uma nação poderosa; e o Senhor reinará sobre eles no monte Sião, desde agora e para sempre.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 8, 'E a ti, ó torre do rebanho, outeiro da filha de Sião, a ti virá, sim, a ti virá o primeiro domínio, o reino da filha de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 9, 'E agora, por que fazes tão grande pranto? Não há em ti rei? pereceu o teu conselheiro, de modo que se apoderaram de ti dores, como da que está de parto,', 1, CURRENT_TIMESTAMP, false),
(33, 4, 10, 'Sofre dores e trabalha, ó filha de Sião, como a que está de parto; porque agora sairás da cidade, e morarás no campo, e virás até Babilônia. Ali, porém serás livrada; ali te remirá o Senhor da mão de teus inimigos.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 11, 'Agora se congregaram muitas nações contra ti, que dizem: Seja ela profanada, e vejam o nossos olhos o seu desejo sobre Sião.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 12, 'Mas, não sabem os pensamentos do Senhor, nem entendem o seu conselho; porque as ajuntou como gavelas para dentro da eira.', 1, CURRENT_TIMESTAMP, false),
(33, 4, 13, 'Levanta-te, e debulha, ó filha de Sião, porque eu farei de ferro o teu chifre, e de bronze as tuas unhas; e esmiuçarás a muitos povos; e dedicarás o seu ganho ao Senhor, e os seus bens ao Senhor de toda a terra.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 1, 'Agora, ajunta-te em tropas, ó filha de tropas; pôr-se-á cerco contra nós; ferirão com a vara no queixo ao juiz de Israel.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 2, 'Mas tu, Belém Efrata, posto que pequena para estar entre os milhares de Judá, de ti é que me sairá aquele que há de reinar em Israel, e cujas saídas são desde os tempos antigos, desde os dias da eternidade.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 3, 'Portanto os entregará até o tempo em que a que está de parto tiver dado à luz; então o resto de seus irmãos voltará aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 4, 'E ele permanecerá, e apascentará o povo na força do Senhor, na excelência do nome do Senhor seu Deus; e eles permanecerão, porque agora ele será grande até os fins da terra.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 5, 'E este será a nossa paz. Quando a Assíria entrar em nossa terra, e quando pisar em nossos palácios, então suscitaremos contra ela sete pastores e oito príncipes dentre os homens.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 6, 'Esses consumirão a terra da Assíria à espada, e a terra de Ninrode nas suas entradas. Assim ele nos livrará da Assíria, quando entrar em nossa terra, e quando calcar os nossos termos.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 7, 'E o resto de Jacó estará no meio de muitos povos, como orvalho da parte do Senhor, como chuvisco sobre a erva, que não espera pelo homem, nem aguarda filhos de homens.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 8, 'Também o resto de Jacó estará entre as nações, no meio de muitos povos, como um leão entre os animais do bosque, como um leão novo entre os rebanhos de ovelhas, o qual, quando passar, as pisará e despedaçará, sem que haja quem as livre.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 9, 'A tua mão será exaltada sobre os teus adversários e serão exterminados todos os seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 10, 'Naquele dia, diz o Senhor, exterminarei do meio de ti os teus cavalos, e destruirei os teus carros;', 1, CURRENT_TIMESTAMP, false),
(33, 5, 11, 'destruirei as cidade da tua terra, e derribarei todas as tuas fortalezas.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 12, 'Tirarei as feitiçarias da tua mão, e não terás adivinhadores;', 1, CURRENT_TIMESTAMP, false),
(33, 5, 13, 'arrancarei do meio de ti as tuas imagens esculpidas e as tuas colunas; e não adorarás mais a obra das tuas mãos.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 14, 'Do meio de ti arrancarei os teus aserins, e destruirei as tuas cidades.', 1, CURRENT_TIMESTAMP, false),
(33, 5, 15, 'E com ira e com furor exercerei vingança sobre as nações que não obedeceram.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 1, 'Ouvi agora o que diz o Senhor: Levanta-te, contende perante os montes, e ouçam os outeiros a tua voz.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 2, 'Ouvi, montes, a demanda do Senhor, e vós, fundamentos duradouros da terra; porque o Senhor tem uma demanda com o seu povo e com Israel entrará em juízo.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 3, 'Ó povo meu, que é que te tenho feito? e em que te enfadei? testifica contra mim.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 4, 'Pois te fiz subir da terra do Egito, e da casa da servidão te remi; e enviei adiante de ti a Moisés, Arão e Miriã.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 5, 'Povo meu, lembra-te agora da consulta de Balaque, rei de Meabe, e do que lhe respondeu Balaão, filho de Beor, e do que sucedeu desde Sitini até Gilgal, para que conheças as justiças do Senhor.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 6, 'Com que me apresentarei diante do Senhor, e me prostrarei perante o Deus excelso? Apresentar-me-ei diante dele com holocausto, com bezerros de um ano?', 1, CURRENT_TIMESTAMP, false),
(33, 6, 7, 'Agradar-se-á o Senhor de milhares de carneiros, ou de miríades de ribeiros de azeite? Darei o meu primogênito pela minha transgressão, o fruto das minhas entranhas pelo pecado da minha alma?', 1, CURRENT_TIMESTAMP, false),
(33, 6, 8, 'Ele te declarou, ó homem, o que é bom; e que é o que o Senhor requer de ti, senão que pratiques a justiça, e ames a benevolência, e andes humildemente com o teu Deus?', 1, CURRENT_TIMESTAMP, false),
(33, 6, 9, 'A voz do Senhor clama à cidade, e o que é sábio temerá o teu nome. Escutai a vara, e quem a ordenou.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 10, 'Porventura ainda há na casa do ímpio tesouros de impiedade? e a efa desfalcada, que é detestável?', 1, CURRENT_TIMESTAMP, false),
(33, 6, 11, 'Justificarei ao que tem balanças falsas, e uma bolsa de pesos enganosos?', 1, CURRENT_TIMESTAMP, false),
(33, 6, 12, 'Pois os ricos da cidade estão cheios de violência, e os seus habitantes falam mentiras, e a língua deles é enganosa na sua boca.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 13, 'Assim eu também te enfraquecerei, ferindo-te e assolando-te, por causa dos teus pecados.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 14, 'Tu comerás, mas não te fartarás; e a tua fome estará sempre contigo; removerás os teus bens, mas nada livrarás; e aquilo que livrares, eu o entregarei à espada.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 15, 'Tu semearás, mas não segarás; pisarás a azeitona, mas não te ungirás de azeite; e pisarás a vindima, mas não beberás o vinho.', 1, CURRENT_TIMESTAMP, false),
(33, 6, 16, 'Porque se observam os estatutos de Onri, e todas as obras da casa de Acabe, e vós andais nos conselhos deles; para que eu faça de ti uma desolação, e dos seus habitantes um assobio. Assim trareis sobre vós o opróbrio do meu povo.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 1, 'Ai de mim! porque estou feito como quando são colhidas as frutas do verão, como os rabiscos da vindima; não há cacho de uvas para comer, nem figo temporão que a minha alma deseja.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 2, 'Pereceu da terra o homem piedoso; e entre os homens não há um que seja reto; todos armam ciladas para sangue; caça cada um a seu irmão com uma rede.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 3, 'As suas mãos estão sobre o mal para o fazerem diligentemente; o príncipe e o juiz exigem a peita, e o grande manifesta o desejo mau da sua alma; e assim todos eles tecem o mal.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 4, 'O melhor deles é como um espinho; o mais reto é pior do que uma sebe de espinhos. Veio o dia dos seus vigias, a saber, a sua punição; agora começará a sua confusão.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 5, 'Não creiais no amigo, nem confieis no companheiro; guarda as portas da tua boca daquela que repousa no teu seio.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 6, 'Pois o filho despreza o pai, a filha se levanta contra a mãe, a nora contra a sogra; os inimigos do homem são os da própria casa.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 7, 'Eu, porém, confiarei no Senhor; esperarei no Deus da minha salvação. O meu Deus me ouvirá.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 8, 'Não te alegres, inimiga minha, a meu respeito; quando eu cair, levantar-me-ei; quando me sentar nas trevas, o Senhor será a minha luz.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 9, 'Sofrerei a indignação do Senhor, porque tenho pecado contra ele; até que ele julgue a minha causa, e execute o meu direito. Ele me tirará para a luz, e eu verei a sua justiça.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 10, 'E a minha inimiga verá isso, e cobri-la-á a confusão, a ela que me disse: Onde está o Senhor teu Deus? Os meus olhos a contemplarão; agora ela será pisada como a lama das ruas.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 11, 'É dia de reedificar os teus muros! Naquele dia será dilatado grandemente o teu termo.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 12, 'Naquele dia virão a ti da Assíria e das cidades do Egito, e do Egito até o Rio, e de mar a mar, e de montanha a montanha.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 13, 'Mas a terra será entregue à desolação por causa dos seus moradores, por causa do fruto das suas obras.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 14, 'Apascenta com a tua vara o teu povo, o rebanho da tua herança, que habita a sós no bosque, no meio do Carmelo; apascentem-se em Basã e Gileade, como nos dias antigos.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 15, 'Eu lhes mostrarei maravilhas, como nos dias da tua saída da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 16, 'As nações o verão, e envergonhar-se-ão, por causa de todo o seu poder; porão a mão sobre a boca, e os seus ouvidos ficarão surdos.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 17, 'Lamberão o pó como serpentes; como répteis da terra, tremendo, sairão dos seus esconderijos; com pavor virão ao Senhor nosso Deus, e terão medo de ti.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 18, 'Quem é Deus semelhante a ti, que perdoas a iniqüidade, e que te esqueces da transgressão do resto da tua herança? O Senhor não retém a sua ira para sempre, porque ele se deleita na benignidade.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 19, 'Tornará a apiedar-se de nós; pisará aos pés as nossas iniqüidades. Tu lançarás todos os nossos pecados nas profundezas do mar.', 1, CURRENT_TIMESTAMP, false),
(33, 7, 20, 'Mostrarás a Jacó a fidelidade, e a Abraão a benignidade, conforme juraste a nossos pais desde os dias antigos.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 1, 'Oráculo acerca de Nínive. Livro da visão de Naum, o elcosita.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 2, 'O Senhor é um Deus zeloso e vingador; o Senhor é vingador e cheio de indignação; o Senhor toma vingança contra os seus adversários, e guarda a ira contra os seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 3, 'O Senhor é tardio em irar-se, e de grande poder, e ao culpado de maneira alguma terá por inocente; o Senhor tem o seu caminho no turbilhão e na tempestade, e as nuvens são o pó dos seus pés.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 4, 'Ele repreende o mar, e o faz secar, e esgota todos os rios; desfalecem Basã e Carmelo, e a flor do Líbano murcha.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 5, 'Os montes tremem perante ele, e os outeiros se derretem; e a terra fica devastada diante dele, sim, o mundo, e todos os que nele habitam.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 6, 'Quem pode manter-se diante do seu furor? e quem pode subsistir diante do ardor da sua ira? a sua cólera se derramou como um fogo, e por ele as rochas são fendidas.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 7, 'O Senhor é bom, uma fortaleza no dia da angústia; e conhece os que nele confiam.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 8, 'E com uma inundação transbordante acabará duma vez com o lugar dela; e até para dentro das trevas perseguirá os seus inimigos.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 9, 'Que é o que projetais vós contra o Senhor? Ele destruirá de vez; não se levantará por duas vezes a angústia.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 10, 'Pois ainda que eles se entrelacem como os espinhos, e se saturem de vinho como bêbados, serão inteiramente consumidos como restolho seco.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 11, 'Não saiu de ti um que maquinava o mal contra o Senhor, aconselhando maldade?', 1, CURRENT_TIMESTAMP, false),
(34, 1, 12, 'Assim diz o Senhor: Por mais intatos que sejam, e por mais numerosos, assim mesmo serão exterminados e passarão. Ainda que te afligi, não te afligirei mais.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 13, 'Mas agora quebrarei o seu jugo de sobre ti, e romperei as tuas cadeias.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 14, 'Contra ti, porém, o Senhor deu ordem que não haja mais linhagem do teu nome; da casa dos teus deuses exterminarei as imagens de escultura e as de fundição; farei o teu sepulcro, porque és vil.', 1, CURRENT_TIMESTAMP, false),
(34, 1, 15, 'Eis sobre os montes os pés do que traz boas novas, do que anuncia a paz! Celebra as tuas festas, ó Judá, cumpre os teus votos, porque o ímpio não tornará mais a passar por ti; ele é inteiramente exterminado.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 1, 'O destruidor sobe contra ti. Guarda tu a fortaleza, vigia o caminho, robustece os lombos, arregimenta bem as tuas forças.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 2, 'Pois o Senhor restaura a excelência de Jacó, qual a excelência de Israel; porque os saqueadores os despojaram e destruíram os seus sarmentos.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 3, 'Os escudos dos seus valentes estão vermelhos, os homens valorosos estão vestidos de escarlate; os carros resplandecem como o aço no dia da sua preparação, e as lanças são brandidas.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 4, 'Os carros andam furiosamente nas ruas; cruzam as praças em todas as direções; parecem como tochas, e correm como os relâmpagos.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 5, 'Ele se lembra dos seus nobres; eles tropeçam na sua marcha; apressam-se para chegar ao muro de cidade, arma-se a manta.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 6, 'As portas dos rios abrem-se, e o palácio está em confusão.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 7, 'E está decretado: ela é despida , e levada cativa; e as suas servas gemem como pombas, batendo em seus peitos.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 8, 'Nínive desde que existe tem sido como um tanque de águas; elas, porém, fogem agora: parai, parai, clama-se; mas ninguém olhara para trás.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 9, 'Saqueai a prata, saqueai o ouro; pois não ha fim dos tesouros; abastança há de todas as coisas preciosas.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 10, 'Ela está vazia, esgotada e devastada; derrete-se o coração, tremem os joelhos, e em todos os lombos há dor; o rosto de todos eles empalidece.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 11, 'Onde está agora o covil dos leões, e a habitação dos leões novos, onde andavam o leão, e a leoa, e o cachorro do leão, sem haver ninguém que os espantasse?', 1, CURRENT_TIMESTAMP, false),
(34, 2, 12, 'O leão arrebatava o que bastava para os seus cachorros, e estrangulava a presa para as suas leoas, e enchia de presas as suas cavernas, e de rapina os seus covis.', 1, CURRENT_TIMESTAMP, false),
(34, 2, 13, 'Eis que eu estou contra ti, diz o Senhor dos exércitos, e queimarei na fumaça os teus carros, e a espada devorará os teus leões novos; e exterminarei da terra a tua presa; e não se ouvira mais a voz dos teus embaixadores.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 1, 'Ai da cidade ensangüentada! Ela está toda cheia de mentiras e de rapina! da presa não há fim!', 1, CURRENT_TIMESTAMP, false),
(34, 3, 2, 'Eis o estrépito do açoite, e o estrondo das rodas, os cavalos que curveteiam e os carros que saltam;', 1, CURRENT_TIMESTAMP, false),
(34, 3, 3, 'o cavaleiro que monta, a espada rutilante, a lança reluzente, a, multidão de mortos, o montão de cadáveres, e defuntos inumeráveis; tropeçam nos cadáveres;', 1, CURRENT_TIMESTAMP, false),
(34, 3, 4, 'tudo isso por causa da multidão dos adultérios, da meretriz formosa, da mestra das feitiçarias, que vende nações por seus deleites, e famílias pelas suas feitiçarias.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 5, 'Eis que eu estou contra ti, diz o Senhor dos exércitos; e levantarei as tuas fraldas sobre a tua face; e às nações mostrarei a tua nudez, e seus reinos a tua vergonha.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 6, 'Lançarei sobre ti imundícias e te tratarei com desprezo, e te porei como espetáculo.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 7, 'E há de ser todos os que te virem fugirão de ti, e dirão: Nínive esta destruída; quem terá compaixão dela? Donde te buscarei consoladores?', 1, CURRENT_TIMESTAMP, false),
(34, 3, 8, 'És tu melhor do que Tebas, que se sentava à beira do Nilo, cercada de águas, tendo por baluarte o mar, e as águas por muralha,', 1, CURRENT_TIMESTAMP, false),
(34, 3, 9, 'Etiópia e Egito eram a sua força, que era inesgotável; Pute e Líbia eram teus aliados.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 10, 'Todavia ela foi levada, foi para o cativeiro; também os seus pequeninos foram despedaçados nas entradas de todas as ruas, e sobre os seus nobres lançaram sortes, e todos os seus grandes foram presos em grilhões.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 11, 'Tu também serás embriagada, e ficarás escondida; e buscarás um refúgio do inimigo.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 12, 'Todas as tuas fortalezas serão como figueiras com figos temporãos; sendo eles sacudidos, caem na boca do que os há de comer.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 13, 'Eis que as tuas tropas no meio de ti são como mulheres; as portas da tua terra estão de todo abertas aos teus inimigos; o fogo consome os teus ferrolhos.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 14, 'Tira água para o tempo do cerco; reforça as tuas fortalezas; entra no lodo, pisa o barro, pega na forma para os tijolos.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 15, 'O fogo ali te consumirá; a espada te exterminará; ela te devorará como a locusta. Multiplica-te como a locusta, multiplica-te como o gafanhoto.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 16, 'Multiplicaste os teus negociantes mais do que as estrelas do céu; a locusta estende as asas e sai voando.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 17, 'Os teus príncipes são como os gafanhotos, e os teus chefes como enxames de gafanhotos, que se acampam nas sebes nos dias de frio; em subindo o sol voam, e não se sabe o lugar em que estão.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 18, 'Os teus pastores dormitam, ó rei da Assíria; os teus nobres dormem, o teu povo está espalhado pelos montes, sem que haja quem o ajunte.', 1, CURRENT_TIMESTAMP, false),
(34, 3, 19, 'Não há cura para a tua ferida; a tua chaga é grave. Todos os que ouvirem a tua fama baterão as palmas sobre ti; porque, sobre quem não tem passado continuamente a tua malícia?', 1, CURRENT_TIMESTAMP, false),
(16, 1, 1, 'Palavras de Neemias, filho de Hacalias. Ora, sucedeu no mês de quisleu, no ano vigésimo, estando eu em Susã, a capital,', 1, CURRENT_TIMESTAMP, false),
(16, 1, 2, 'que veio Hanâni, um de meus irmãos, com alguns de Judá; e perguntei-lhes pelos judeus que tinham escapado e que restaram do cativeiro, e acerca de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(16, 1, 3, 'Eles me responderam: Os restantes que ficaram do cativeiro, lá na província estão em grande aflição e opróbrio; também está derribado o muro de Jerusalém, e as suas portas queimadas a fogo.', 1, CURRENT_TIMESTAMP, false),
(16, 1, 4, 'Tendo eu ouvido estas palavras, sentei-me e chorei, e lamentei por alguns dias; e continuei a jejuar e orar perante o Deus do céu,', 1, CURRENT_TIMESTAMP, false),
(16, 1, 5, 'e disse: Ó Senhor, Deus do céu, Deus grande e temível, que guardas o pacto e usas de misericórdia para com aqueles que te amam e guardam os teus mandamentos:', 1, CURRENT_TIMESTAMP, false),
(16, 1, 6, 'Estejam atentos os teus ouvidos e abertos os teus olhos, para ouvires a oração do teu servo, que eu hoje faço perante ti, dia e noite, pelos filhos de Israel, teus servos, confessando eu os pecados dos filhos de Israel, que temos cometido contra ti; sim, eu e a casa de meu pai pecamos;', 1, CURRENT_TIMESTAMP, false),
(16, 1, 7, 'na verdade temos procedido perversamente contra ti, e não temos guardado os mandamentos, nem os estatutos, nem os juízos, que ordenaste a teu servo Moisés.', 1, CURRENT_TIMESTAMP, false),
(16, 1, 8, 'Lembra-te, pois, da palavra que ordenaste a teu servo Moisés, dizendo: Se vós transgredirdes, eu vos espalharei por entre os povos;', 1, CURRENT_TIMESTAMP, false),
(16, 1, 9, 'mas se vos converterdes a mim, e guardardes os meus mandamentos e os cumprirdes, ainda que os vossos rejeitados estejam na extremidade do céu, de lá os ajuntarei e os trarei para o lugar que tenho escolhido para ali fazer habitar o meu nome.', 1, CURRENT_TIMESTAMP, false),
(16, 1, 10, 'Eles são os teus servos e o teu povo, que resgataste com o teu grande poder e com a tua mão poderosa.', 1, CURRENT_TIMESTAMP, false),
(16, 1, 11, 'Ó Senhor, que estejam atentos os teus ouvidos à oração do teu servo, e à oração dos teus servos que se deleitam em temer o teu nome; e faze prosperar hoje o teu servo, e dá-lhe graça perante este homem. {Era eu então copeiro do rei.}', 1, CURRENT_TIMESTAMP, false),
(16, 2, 1, 'Sucedeu, pois, no mês de nisã, no ano vigésimos do rei Artaxerxes, quando o vinho estava posto diante dele, que eu apanhei o vinho e o dei ao rei. Ora, eu nunca estivera triste na sua presença.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 2, 'E o rei me disse: Por que está triste o teu rosto, visto que não estás doente? Não é isto senão tristeza de coração. Então temi sobremaneira.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 3, 'e disse ao rei: Viva o rei para sempre! Como não há de estar triste o meu rosto, estando na cidade, o lugar dos sepulcros de meus pais, assolada, e tendo sido consumidas as suas portas pelo fogo?', 1, CURRENT_TIMESTAMP, false),
(16, 2, 4, 'Então o rei me perguntou: Que me pedes agora? Orei, pois, ao Deus do céu,', 1, CURRENT_TIMESTAMP, false),
(16, 2, 5, 'e disse ao rei: Se for do agrado do rei, e se teu servo tiver achado graça diante de ti, peço-te que me envies a Judá, à cidade dos sepulcros de meus pais, para que eu a reedifique.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 6, 'Então o rei, estando a rainha assentada junto a ele, me disse: Quanto durará a tua viagem, e quando voltarás? E aprouve ao rei enviar-me, apontando-lhe eu certo prazo.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 7, 'Eu disse ainda ao rei: Se for do agrado do rei, dêem-se-me cartas para os governadores dalém do Rio, para que me permitam passar até que eu chegue a Judá;', 1, CURRENT_TIMESTAMP, false),
(16, 2, 8, 'como também uma carta para Asafe, guarda da floresta do rei, a fim de que me dê madeira para as vigas das portas do castelo que pertence à casa, e para o muro da cidade, e para a casa que eu houver de ocupar. E o rei mas deu, graças à mão benéfica do meu Deus sobre mim.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 9, 'Então fui ter com os governadores dalém do Rio, e lhes entreguei as cartas do rei. Ora, o rei tinha enviado comigo oficiais do exército e cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 10, 'O que ouvindo Sambalate, o horonita, e Tobias, o servo amonita, ficaram extremamente agastados de que alguém viesse a procurar o bem dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 11, 'Cheguei, pois, a Jerusalém, e estive ali três dias.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 12, 'Então de noite me levantei, eu e uns poucos homens comigo; e não declarei a ninguém o que o meu deus pusera no coração para fazer por Jerusalém. Não havia comigo animal algum, senão aquele que eu montava.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 13, 'Assim saí de noite pela porta do vale, até a fonte do dragão, e até a porta do monturo, e contemplei os muros de Jerusalém, que estavam demolidos, e as suas portas, que tinham sido consumidas pelo fogo.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 14, 'E passei adiante até a porta da fonte, e à piscina do rei; porém não havia lugar por onde pudesse passar o animal que eu montava.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 15, 'Ainda de noite subi pelo ribeiro, e contemplei o muro; e virando, entrei pela porta do vale, e assim voltei.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 16, 'E não souberam os magistrados aonde eu fora nem o que eu fazia; pois até então eu não havia declarado coisa alguma, nem aos judeus, nem aos sacerdotes, nem aos nobres, nem aos magistrados, nem aos demais que faziam a obra.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 17, 'Então eu lhes disse: Bem vedes vós o triste estado em que estamos, como Jerusalém está assolada, e as suas portas queimadas a fogo; vinde, pois, e edifiquemos o muro de Jerusalém, para que não estejamos mais em opróbrio.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 18, 'Então lhes declarei como a mão do meu Deus me fora favorável, e bem assim as palavras que o rei me tinha dito. Eles disseram: Levantemo-nos, e edifiquemos. E fortaleceram as mãos para a boa obra.', 1, CURRENT_TIMESTAMP, false),
(16, 2, 19, 'O que ouvindo Sambalate, o horonita, e Tobias, o servo amonita, e Gesem, o arábio, zombaram de nós, desprezaram-nos e disseram: O que é isso que fazeis? Quereis rebelar-vos contra o rei?', 1, CURRENT_TIMESTAMP, false),
(16, 2, 20, 'Então lhes respondi: O Deus do céu é que nos fará prosperar; e nós, seus servos, nos levantaremos e edificaremos: mas vós não tendes parte, nem direito, nem memorial em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 1, 'Então se levantou Eliasibe, o sumo sacerdote, juntamente com os seus irmãos, os sacerdotes, e edificaram a porta das ovelhas, a qual consagraram, e lhe assentaram os batentes. Consagraram-na até a torre dos cem, até a torre de Henanel.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 2, 'E junto a ele edificaram os homens de Jericó; também ao lado destes edificou Zacur, o filho de Inri.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 3, 'Os filhos de Hassenaá edificaram a porta dos peixes, colocaram-lhe as vigas, e lhe assentaram os batentes, com seus ferrolhos e trancas.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 4, 'Ao seu lado fez os reparos Meremote, filho de Urias, filho de Hacoz; ao seu lado Mesulão, filho de Berequias, filho de Mesezabel; ao seu lado Zadoque, filho de Baaná;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 5, 'ao lado destes repararam os tecoítas; porém os seus nobres não meteram o pescoço os serviço do Senhor.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 6, 'Joiada, filho de Paséia, e Mesulão, filho de Besodéias, repararam a porta velha, colocaram-lhe as vigas, e lhe assentaram os batentes com seus ferrolhos e trancas.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 7, 'Junto deles fizeram os reparos Melatias, o gibeonita, e Jadom, o meronotita, homens de Gibeão e de Mizpá, que pertenciam ao domínio do governador dalém do Rio;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 8, 'ao seu lado Uziel, filho de Haraías, um dos ourives; ao lado dele Hananias, um dos perfumistas; e fortificaram Jerusalém até o muro largo.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 9, 'Ao seu lado fez os reparos Refaías, filho de Hur, governador da metade do distrito de Jerusalém;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 10, 'ao seu lado Jedaías, filho de Harumafe, defronte de sua casa; ao seu lado Hatus, filho de Hasabnéias.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 11, 'Malquias, filho de Harim, e Hassube, filho de Paate-Moabe, repararam outra parte, como também a torre dos fornos;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 12, 'e ao seu lado Salum, filho de Haloés, governador da outra metade do distrito de Jerusalém, ele e as suas filhas.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 13, 'A porta do vale, repararam-na Hanum e os moradores de Zanoa; estes a edificaram, e lhe assentaram os batentes, com seus ferrolhos e trancas, como também mil côvados de muro até a porto do monturo.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 14, 'A porta do monturo, reparou-a Malquias, filho de Recabe, governador do distrito Bete-Haquerem; este a edificou, e lhe assentou os batentes com seus ferrolhos e trancas.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 15, 'A porta da fonte, reparou-a Salum, filho de Col-Hoze, governador do distrito de Mizpá; edificou-a e a cobriu, e lhe assentou os batentes, com seus ferrolhos e trancas; edificou também o muro da piscina de Selá, do jardim do rei, até os degraus que descem da cidade de Davi.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 16, 'Depois dele Neemias, filho de Azbuque, governador da metade do distrito de Bete-Zur, fez os reparos até defronte dos sepulcros de Davi, até a piscina artificial, e até a casa dos homens poderosos.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 17, 'Depois dele fizeram os reparos os levitas: Reum, filho de Bani, e ao seu lado, Hasabias, governador da metade do distrito de Queila, por seu distrito;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 18, 'depois dele seus irmãos, Bavai, filho de Henadade, governador da outra metade do distrito de Queila.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 19, 'Ao seu lado Ézer, filho de Jesuá, governador de Mizpá, reparou outra parte, defronte da subida para a casa das armas, no ângulo.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 20, 'Depois dele reparou Baruque, filho de Zabai, outra parte, desde o ângulo até a porta da casa de Eliasibe, o sumo sacerdote.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 21, 'Depois dele reparou Meremote, filho de Urias, filho de Hacoz, outra parte, deste a porta da casa de Eliasibe até a extremidade da mesma.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 22, 'Depois dele fizeram os reparos os sacerdotes que habitavam na campina;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 23, 'depois Benjamim e Hassube, defronte da sua casa; depois deles Azarias, filho de Maaséias, filho de Ananias, junto à sua casa.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 24, 'Depois dele reparou Binuí, filho de Henadade, outra porte, desde a casa de Azarias até o ângulo e até a esquina.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 25, 'Palal, filho de Uzai, reparou defronte do ângulo, e a torre que se projeta da casa real superior, que está junto ao átrio da guarda; depois dele Pedaías, filho de Parós.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 26, '{Ora, os netinins habitavam em Ofel, até defronte da porta das águas, para o oriente, e até a torre que se projeta.}', 1, CURRENT_TIMESTAMP, false),
(16, 3, 27, 'Depois repararam os tecoítas outra parte, defronte da grande torre que se projeta, e até o muro de Ofel.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 28, 'Para cima da porta dos cavalos fizeram os reparos os sacerdotes, cada um defronte da sua casa;', 1, CURRENT_TIMESTAMP, false),
(16, 3, 29, 'depois dele Zadoque, filho de Imer, defronte de sua casa; e depois dele Semaías, filho de Secanias, guarda da porta oriental.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 30, 'Depois dele repararam outra parte Hananias, filho de Selemias, e Hanum, o sexto filho de Zalafe. Depois dele reparou Mesulão, filho de Berequias, uma parte defronte da sua câmara.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 31, 'Depois dele reparou Malquias, um dos ourives, uma parte até a casa dos netinins e dos mercadores, defronte da porta da guarda, e até a câmara superior da esquina.', 1, CURRENT_TIMESTAMP, false),
(16, 3, 32, 'E entre a câmara da esquina e a porta das ovelhas repararam os ourives e os mercadores.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 1, 'Ora, quando Sambalate ouviu que edificávamos o muro, ardeu em ira, indignou-se muito e escarneceu dos judeus;', 1, CURRENT_TIMESTAMP, false),
(16, 4, 2, 'e falou na presença de seus irmãos e do exército de Samária, dizendo: Que fazem estes fracos judeus? Fortificar-se-ão? Oferecerão sacrifícios? Acabarão a obra num só dia? Vivificarão dos montões de pó as pedras que foram queimadas?', 1, CURRENT_TIMESTAMP, false),
(16, 4, 3, 'Ora, estava ao lado dele Tobias, o amonita, que disse: Ainda que edifiquem, vindo uma raposa derrubará o seu muro de pedra.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 4, 'Ouve, ó nosso Deus, pois somos tão desprezados; faze recair o opróbrio deles sobre as suas cabaças, e faze com que eles sejam um despojo numa terra de cativeiro.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 5, 'Não cubras a sua iniquidade, e não se risque de diante de ti o seu pecado, pois que te provocaram à ira na presença dos edificadores.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 6, 'Assim edificamos o muro; e todo o muro se completou até a metade da sua altura; porque o coração do povo se inclinava a trabalhar.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 7, 'Mas, ouvindo Sambalate e Tobias, e os arábios, o amonitas e os asdoditas, que ia avante a reparação dos muros de Jerusalém e que já as brechas se começavam a fechar, iraram-se sobremodo;', 1, CURRENT_TIMESTAMP, false),
(16, 4, 8, 'e coligaram-se todos, para virem guerrear contra Jerusalém e fazer confusão ali.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 9, 'Nós, porém, oramos ao nosso Deus, e pusemos guarda contra eles de dia e de noite.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 10, 'Então disse Judá: Desfalecem as forças dos carregadores, e há muito escombro; não poderemos edificar o muro.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 11, 'E os nossos inimigos disseram: Nada saberão nem verão, até que entremos no meio deles, e os matemos, e façamos cessar a obra.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 12, 'Mas sucedeu que, vindo os judeus que habitavam entre eles, dez vezes nos disseram: De todos os lugares de onde moram subirão contra nós.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 13, 'Pelo que nos lugares baixos por detrás do muro e nos lugares abertos, dispus o povo segundo suas famílias com as suas espadas, com as suas lanças, e com os seus arcos.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 14, 'Olhei, levantei-me, e disse aos nobres, aos magistrados e ao resto do povo: Não os temais! Lembrai-vos do Senhor, grande e temível, e pelejai por vossos irmãos, vossos filhos, vossas filhas, vossas mulheres e vossas casas.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 15, 'Quando os nossos inimigos souberam que nós tínhamos sido avisados, e que Deus tinha dissipado o conselho deles, todos voltamos ao muro, cada um para a sua obra.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 16, 'Desde aquele dia metade dos meus moços trabalhavam na obra, e a outra metade empunhava as lanças, os escudos, os arcos, e as couraças; e os chefes estavam por detrás de toda a casa de Judá.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 17, 'Os que estavam edificando o muro, e os carregadores que levavam as cargas, cada um com uma das mãos fazia a obra e com a outra segurava a sua arma;', 1, CURRENT_TIMESTAMP, false),
(16, 4, 18, 'e cada um dos edificadores trazia a sua espada à cinta, e assim edificavam. E o que tocava a trombeta estava no meu lado.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 19, 'Disse eu aos nobres, aos magistrados e ao resto do povo: Grande e extensa é a obra, e nós estamos separados no muro, longe uns dos outros;', 1, CURRENT_TIMESTAMP, false),
(16, 4, 20, 'em qualquer lugar em que ouvirdes o som da trombeta, ali vos ajuntareis conosco. O nosso Deus pelejará por nós.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 21, 'Assim trabalhávamos na obra; e metade deles empunhava as lanças desde a subida da alva até o sair das estrelas.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 22, 'Também nesse tempo eu disse ao povo: Cada um com o seu moço pernoite em Jerusalém, para que de noite nos sirvam de guardas, e de dia trabalhem.', 1, CURRENT_TIMESTAMP, false),
(16, 4, 23, 'Desta maneira nem eu, nem meus irmãos, nem meus moços, nem os homens da guarda que me acompanhavam largávamos as nossas vestes; cada um ia com a arma à sua direita.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 1, 'Então se levantou um grande clamor do povo e de suas mulheres contra os judeus, seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 2, 'Pois havia alguns que diziam: Nós, nossos filhos e nossas filhas somos muitos; que se nos dê trigo, para que comamos e vivamos.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 3, 'Também havia os que diziam: Estamos empenhando nossos campos, as nossas vinhas e as nossas casas, para conseguirmos trigo durante esta fome.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 4, 'Havia ainda outros que diziam: Temos tomado dinheiro emprestado até para o tributo do rei sobre os nossos campos e as nossas vinhas.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 5, 'Ora, a nossa carne é como a carne de nossos irmãos, e nossos filhos como os filhos deles; e eis que estamos sujeitando nossos filhos e nossas filhas para serem servos, e algumas de nossas filhas já estão reduzidas à escravidão. Não está em nosso poder evitá-lo, pois outros têm os nossos campos e as nossas vinhas.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 6, 'Ouvindo eu, pois, o seu clamor, e estas palavras, muito me indignei.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 7, 'Então consultei comigo mesmo; depois contendi com do nobres e com os magistrados, e disse-lhes: Estais tomando juros, cada um de seu irmão. E ajuntei contra eles uma grande assembléia.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 8, 'E disse-lhes: Nós, segundo as nossas posses, temos resgatado os judeus, nossos irmãos, que foram vendidos às nações; e vós venderíeis os vossos irmãos, ou seriam vendidos a nós? Então se calaram, e não acharam o que responder.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 9, 'Disse mais: Não é bom o que fazeis; porventura não devíeis andar no temor do nosso Deus, por causa do opróbrio dos povos, os nosso inimigos?', 1, CURRENT_TIMESTAMP, false),
(16, 5, 10, 'Também eu, meus irmãos e meus moços lhes temos emprestado dinheiro e trigo. Deixemos, peço-vos este ganho.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 11, 'Restituí-lhes hoje os seus campos, as suas vinhas, os seus olivais e as suas casas, como também a centésima parte do dinheiro, do trigo, do mosto e do azeite, que deles tendes exigido.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 12, 'Então disseram: Nós lho restituiremos, e nada lhes pediremos; faremos assim como dizes. Então, chamando os sacerdotes, fi-los jurar que fariam conforme prometeram.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 13, 'Também sacudi as minhas vestes, e disse: Assim sacuda Deus da sua casa e do seu trabalho todo homem que não cumprir esta promessa; assim mesmo seja ele sacudido e despojado. E toda a congregação disse: Amém! E louvaram ao Senhor; e o povo fez conforme a sua promessa.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 14, 'Além disso, desde o dia em que fui nomeado seu governador na terra de Judá, desde o ano vinte até o anos trinta e dois do rei Artaxerxes, isto é, por doze anos, nem eu nem meus irmãos comemos o pão devido ao governador.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 15, 'Mas os primeiros governadores, que foram antes de mim, oprimiram o povo, e tomaram-lhe pão e vinho e, além disso, quarenta siclos de prata; e até os seus moços dominavam sobre o povo. Porém eu assim não fiz, por causa do temor de Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 16, 'Também eu prossegui na obra deste muro, e terra nenhuma compramos; e todos os meus moços se ajuntaram ali para a obra.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 17, 'Sentavam-se à minha mesa cento e cinqüenta homens dentre os judeus e os magistrados, além dos que vinham ter conosco dentre as nações que estavam ao redor de nós.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 18, 'Ora, o que se preparava para cada dia era um boi e seis ovelhas escolhidas; também se preparavam aves e, de dez em dez dias, provisão de toda qualidade de vinho. Todavia, nem por isso exigi o pão devido ao governador, porquanto a servidão deste povo era pesada.', 1, CURRENT_TIMESTAMP, false),
(16, 5, 19, 'Lembra-te de mim para teu bem, ó meu Deus, e de tudo quanto tenho feito em prol deste povo.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 1, 'Quando Sambalate, Tobias e Gesem, o arábio, e o resto dos nossos inimigos souberam que eu já tinha edificado o muro e que nele já não havia brecha alguma, ainda que até este tempo não tinha posto as portas nos portais,', 1, CURRENT_TIMESTAMP, false),
(16, 6, 2, 'Sambalate e Gesem mandaram dizer-me: Vem, encontremo-nos numa das aldeias da planície de Ono. Eles, porém, intentavam fazer-me mal.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 3, 'E enviei-lhes mensageiros a dizer: Estou fazendo uma grande obra, de modo que não poderei descer. Por que cessaria esta obra, enquanto eu a deixasse e fosse ter convosco?', 1, CURRENT_TIMESTAMP, false),
(16, 6, 4, 'Do mesmo modo mandaram dizer-se quatro vezes; e do mesmo modo lhes respondi.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 5, 'Então Sambalate, ainda pela quinta vez, me enviou o seu moço com uma carta aberta na mão,', 1, CURRENT_TIMESTAMP, false),
(16, 6, 6, 'na qual estava escrito: Entre as nações se ouviu, e Gesem o diz, que tu e os judeus intentais revoltar-vos, e por isso tu estás edificando o muro, e segundo se diz, queres fazer-te rei deles;', 1, CURRENT_TIMESTAMP, false),
(16, 6, 7, 'e que constituíste profetas para proclamarem a respeito de ti em Jerusalém: Há rei em Judá. Ora, estas coisas chegarão aos ouvidos do rei; vem pois, agora e consultemos juntamente.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 8, 'Então mandei dizer-lhe: De tudo o que dizes, coisa nenhuma sucedeu, mas tu mesmo o inventas.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 9, 'Pois todos eles nos procuravam atemorizar, dizendo: As suas mãos hão de largar a obra, e não se efetuará. Mas agora, ó Deus, fortalece as minhas mãos.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 10, 'Fui à casa de Semaías, filho de Delaías, filho de Meetabel, que estava em recolhimento; e disse ele: Ajuntemo-nos na casa de Deus, dentro do templo, e fechemos as suas portas, pois virão matar-te; sim, de noite virão matar-te.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 11, 'Eu, porém, respondi: Um homem como eu fugiria? e quem há que, sendo tal como eu, possa entrar no templo e viver? De maneira nenhuma entrarei.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 12, 'E percebi que não era Deus que o enviara; mas ele pronunciou essa profecia contra mim, porquanto Tobias e Sambalate o haviam subornado.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 13, 'Eles o subornaram para me atemorizar, a fim de que eu assim fizesse, e pecasse, para que tivessem de que me infamar, e assim vituperassem.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 14, 'Lembra-te, meu Deus, de Tobias e de Sambalate, conforme estas suas obras, e também da profetisa Noadias, e dos demais profetas que procuravam atemorizar-me.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 15, 'Acabou-se, pois, o muro aos vinte e cinco do mês de elul, em cinqüenta e dois dias.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 16, 'Quando todos os nosso inimigos souberam disso, todos os povos que havia em redor de nós temeram, e abateram-se muito em seu próprio conceito; pois perceberam que fizemos esta obra com o auxílio do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 17, 'Além disso, naqueles dias o nobres de Judá enviaram muitas cartas a Tobias, e as cartas de Tobias vinham para eles.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 18, 'Pois muitos em Judá estavam ligados a ele por juramento, por ser ele genro de Secanias, filho de Ará, e por haver seu filho Joanã casado com a filha de Mesulão, filho de Berequias.', 1, CURRENT_TIMESTAMP, false),
(16, 6, 19, 'Também as boas ações dele contavam perante mim, e as minhas palavras transmitiam a ele. Tobias, pois, escrevia cartas para me atemorizar.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 1, 'Ora, depois que o muro foi edificado, tendo eu assentado as portas, e havendo sido designados os porteiros, os cantores e os levitas,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 2, 'pus Hanâni, meu irmão, e Hananias, governador do castelo, sobre Jerusalém; pois ele era homem fiel e temente a Deus, mais do que muitos;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 3, 'e eu lhes disse: Não se abram as portas de Jerusalém até que o sol aqueça; e enquanto os guardas estiverem nos postos se fechem e se tranquem as portas; e designei dentre os moradores de Jerusalém guardas, cada um por seu turno, e cada um diante da sua casa.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 4, 'Ora, a cidade era larga e grande, mas o povo dentro dela era pouco, e ainda as casa não estavam edificadas.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 5, 'Então o meu Deus me pôs no coração que ajuntasse os nobres, os magistrados e o povo, para registrar as genealogias. E achei o livro da genealogia dos que tinham subido primeiro e achei escrito nele o seguinte:', 1, CURRENT_TIMESTAMP, false),
(16, 7, 6, 'Este são os filhos da província que subiram do cativeiro dentre os exilados, que Nabucodonosor, rei da Babilônia, transportara e que voltaram para Jerusalém e para Judá, cada um para a sua cidade,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 7, 'os quais vieram com Zorobabel, Jesuá, Neemias, Azarias, Raamias, Naamâni, Mordecai, Bilsã, Misperete, Bigvai, Neum e Baaná. Este é o número dos homens do povo de Israel:', 1, CURRENT_TIMESTAMP, false),
(16, 7, 8, 'foram os filhos de Parós, dois mil cento e setenta e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 9, 'os filhos de Sefatias, trezentos e setenta e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 10, 'os filhos de Ará, seiscentos e cinqüenta e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 11, 'os filhos de Paate-Moabe, dos filhos de Jesuá e de Joabe, dois mil oitocentos e dezoito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 12, 'os filhos de Elão, mil duzentos e cinqüenta e quatro;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 13, 'os filhos de Zatu, oitocentos e quarenta e cinco;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 14, 'os filhos de Zacai, setecentos e sessenta;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 15, 'os filhos de Binuí, seiscentos e quarenta e oito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 16, 'os filhos de Bebai, seiscentos e vinte e oito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 17, 'os filhos de Azgade, dois mil trezentos e vinte e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 18, 'os filhos de Adonicão, seiscentos e sessenta e sete;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 19, 'os filhos de Bigvai, dois mil e sessenta e sete;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 20, 'os filhos de Adim, seiscentos e cinqüenta e cinco;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 21, 'os filhos de Ater, de Ezequias, noventa e oito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 22, 'os filhos de Hasum, trezentos e vinte e oito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 23, 'os filhos de Bezai, trezentos e vinte e quatro;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 24, 'os filhos de Harife, cento e doze;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 25, 'os filhos de Gibeão, noventa e cinco;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 26, 'os filhos de Belém e de Netofá, cento e oitenta e oito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 27, 'os homens de Anatote, cento e vinte e oito;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 28, 'os homens de Bete-Azmavete, quarenta e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 29, 'os homens de Quiriate-Jeriam, de Cefira, e de Beerote, setecentos e quarenta e três;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 30, 'os homens de Ramá e Gaba, seiscentos e vinte e um;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 31, 'os homens de Micmás, cento e vinte e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 32, 'os homens de Betel e Ai, cento e vinte e três;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 33, 'os homens do outro Nebo, cinqüenta e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 34, 'os filhos do outro Elão, mil duzentos e cinqüenta e quatro;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 35, 'os filhos de Harim, trezentos e vinte;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 36, 'os filhos de Jericó, trezentos e quarenta e cinco;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 37, 'os filhos de Lode, de hadide e de Ono, setecentos e vinte e um;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 38, 'os filhos de Senaá, três mil novecentos e trinta.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 39, 'Os sacerdotes: os filhos de Jedaías, da casa de Jesuá, novecentos e setenta e três;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 40, 'os filhos de Imer, mil e cinqüenta e dois;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 41, 'os filhos de Pasur, mil duzentos e quarenta e sete;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 42, 'os filhos de Harim, mil e dezessete;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 43, 'Os levitas: os filhos de Jesuá, de Cadmiel, dos filhos de Hodevá, setenta e quatro.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 44, 'Os cantores: os filhos de Asafe, cento e quarenta e oito.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 45, 'Os porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai, cento e trinta e oito.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 46, 'Os netinis: os filhos de Ziá, os filhos de Hasufa, os filhos de Tabaote,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 47, 'os filhos de Querós, os filhos de Siá, os filhos de Padom,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 48, 'os filhos de Lebana, os filhos de Hagaba, os filhos de Salmai,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 49, 'os filhos de Hanã, os filhos de Gidel, os filhos de Gaar,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 50, 'os filhos de Recaías, os filhos de Rezim, os filhos de Necoda,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 51, 'os filhos de Gazão, os filhos de Uzá, os filhos de Paséia,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 52, 'os filhos de Besai, os filhos de Meunim, os filhos de Nefusesim,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 53, 'os filhos de Baquebuque, os filhos de Hacufa, os filhos de Hacur,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 54, 'os filhos de Bazlite, os filhos de Meída, os filhos de Harsa,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 55, 'os filhos de Barcos, os filhos de Sísera, os filhos de Tamá,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 56, 'os filhos de Nezias, os filhos de Hatifa,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 57, 'os filhos dos servos de Salomão: os filhos de Sotai, os filhos de Soforete, os filhos de Perida,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 58, 'os filhos de Jaala, os filhos de Darcom, os filhos de Gidel,', 1, CURRENT_TIMESTAMP, false),
(16, 7, 59, 'os filhos de Sefatias, os filhos de Hatil, os filhos de Paquerete-Hazebaim e os filhos de Amom.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 60, 'Todos os netinins e os filhos dos servos de Salomão, eram trezentos e noventa e dois.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 61, 'Estes foram os que subiram de Tel-Mela, Tel-Harsa, Querube, Adom, e Imer; porém não puderam provar que as suas casas paternas e as sua linhagem eram de Israel:', 1, CURRENT_TIMESTAMP, false),
(16, 7, 62, 'os filhos de Dalaías, os filhos de Tobias, os filhos de Necoda, seiscentos e quarenta e dois.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 63, 'E dos sacerdotes: os filhos de Hobaías, os filhos Hacoz, os filhos de Barzilai, que tomara por mulher uma das filhas Barzilai, o gileadita, e que foi chamado do seu nome.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 64, 'Estes buscaram o seu registro entre os arrolados nos registros genealógicos, mas não foi encontrado; pelo que, tidos por imundos, foram excluídos do sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 65, 'E o governador lhes disse que não comesse das coisas sagradas, até que se levantasse um sacerdote com Urim e Tumim.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 66, 'Toda esta congregação junta somava quarenta e dois mil trezentos e sessenta;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 67, 'afora os seus servos e as suas servas, que foram sete mil trezentos e trinta e sete; e tinham duzentos e quarenta e cinco cantores e cantoras.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 68, 'Os seus cavalos foram setecentos e trinta e seis; os seus mulos, duzentos e quarenta e cinco;', 1, CURRENT_TIMESTAMP, false),
(16, 7, 69, 'os seus camelos, quatrocentos e trinta e cinco; e os seus jumentos, seis mil setecentos e vinte.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 70, 'Ora, alguns dos cabeças das casas paternas contribuíram para a obra. O governador deu para a tesouraria mil dários de ouro, cinqüenta bacias, e quinhentas e trinta vestes sacerdotais.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 71, 'E alguns dos cabeças das casas paternas deram para a tesouraria da obra vinte mil dáricos de ouro, e duas mil e duzentas minas de prata.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 72, 'O que o resto do povo deu foram vinte mil dáricos de ouro, duas mil minas de prata, e sessenta e sete vestes sacerdotais.', 1, CURRENT_TIMESTAMP, false),
(16, 7, 73, 'Os sacerdotes, os levitas, os porteiros, os cantores, alguns dentre o povo, os netinins e todo o Israel habitaram nas suas cidades. Quando chegou o sétimo mês, já se achavam os filhos de Israel nas suas cidades.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 1, 'Então todo o povo se ajuntou como um só homem, na praça diante da porta das águas; e disseram a Esdras, o escriba, que trouxesse o livro da lei de Moisés, que o Senhor tinha ordenado a Israel.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 2, 'E Esdras, o sacerdote, trouxe a lei perante a congregação, tanto de homens como de mulheres, e de todos os que podiam ouvir com entendimento, no primeiro dia do sétimo mês.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 3, 'E leu nela diante da praça que está fronteira à porta das águas, desde a alva até o meio-dia, na presença dos homens e das mulheres, e dos que podiam entender; e os ouvidos de todo o povo estavam atentos ao livro da lei.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 4, 'Esdras, o escriba, ficava em pé sobre um estrado de madeira, que fizeram para esse fim e estavam em pé junto a ele, à sua direita, Matitias, Sema, Ananías, Urias, Hilquias e Maaséias; e à sua esquerda, Pedaías, Misael, Malquias, Hasum, Hasbadana, Zacarias e Mesulão.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 5, 'E Esdras abriu o livro à vista de todo o povo {pois estava acima de todo o povo}; e, abrindo-o ele, todo o povo se pôs em pé.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 6, 'Então Esdras bendisse ao Senhor, o grande Deus; e todo povo, levantando as mãos, respondeu: Amém! amém! E, inclinando-se, adoraram ao Senhor, com os rostos em terra.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 7, 'Também Jesuá, Bani, Serebias, Jamim, Acube; Sabetai, Hodias, Maaséias, Quelita, Azarias, Jozabade, Hanã, Pelaías e os levitas explicavam ao povo a lei; e o povo estava em pé no seu lugar.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 8, 'Assim leram no livro, na lei de Deus, distintamente; e deram o sentido, de modo que se entendesse a leitura.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 9, 'E Neemias, que era o governador, e Esdras, sacerdote e escriba, e os levitas que ensinavam o povo, disseram a todo o povo: Este dia é consagrado ao Senhor vosso Deus; não pranteeis nem choreis. Pois todo o povo chorava, ouvindo as palavras da lei.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 10, 'Disse-lhes mais: Ide, comei as gorduras, e bebei as doçuras, e enviai porções aos que não têm nada preparado para si; porque este dia é consagrado ao nosso Senhor. Portanto não vos entristeçais, pois a alegria do Senhor é a vossa força.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 11, 'Os levitas, pois, fizeram calar todo o povo, dizendo: Calai-vos, porque este dia é santo; por isso não vos entristeçais.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 12, 'Então todo o povo se foi para comer e beber, e para enviar porções, e para fazer grande regozijo, porque tinha entendido as palavras que lhe foram referidas.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 13, 'Ora, no dia seguinte ajuntaram-se os cabeças das casas paternas de todo o povo, os sacerdotes e os levitas, na presença de Esdras, o escriba, para examinarem as palavras da lei;', 1, CURRENT_TIMESTAMP, false),
(16, 8, 14, 'e acharam escrito na lei que o Senhor, por intermédio de Moisés, ordenara que os filhos de Israel habitassem em cabanas durante a festa do sétimo mês;', 1, CURRENT_TIMESTAMP, false),
(16, 8, 15, 'e que publicassem e fizessem passar pregão por todas as suas cidades, e em ramos de oliveiras, de zambujeiros e de murtas, folhas de palmeiras, e ramos de outras árvores frondosas, para fazerdes cabanas, como está escrito.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 16, 'Saiu, pois, o povo e trouxe os ramos; e todos fizeram para si cabanas, cada um no eirado da sua casa, nos seus pátios, nos átrios da casa de Deus, na praça da porta das águas, e na praça da porta de Efraim.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 17, 'E toda a comunidade dos que tinham voltado do cativeiro fez cabanas, e habitaram nelas; pois não tinham feito assim os filhos de Israel desde os dias de Josué, filho de Num, até aquele dia. E houve mui grande regozijo.', 1, CURRENT_TIMESTAMP, false),
(16, 8, 18, 'E Esdras leu no livro da lei de Deus todos os dias, desde o primeiro até o último; e celebraram a festa por sete dias, e no oitavo dia houve uma assembléia solene, segundo a ordenança.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 1, 'Ora, no dia vinte e quatro desse mês, se ajuntaram os filhos de Israel em jejum, vestidos de sacos e com terra sobre as cabeças.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 2, 'E os da linhagem de Israel se apartaram de todos os estrangeiros, puseram-se em pé e confessaram os seus pecados e as iniquidades de seus pais.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 3, 'E, levantando-se no seu lugar, leram no livro da lei do Senhor seu Deus, uma quarta parte do dia; e outra quarta parte fizeram confissão, e adoraram ao Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 4, 'Então Jesuá, Bani, Cadmiel, Sebanias, Buni, Serebias, Bani e Quenâni se puseram em pé sobre os degraus dos levitas, e clamaram em alta voz ao Senhor seu Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 5, 'E os levitas Jesuá, Cadmiel, Bani, Hasabnéias, Serebias, Hodias, Sebanias e Petaías disseram: Levantai-vos, bendizei ao Senhor vosso Deus de eternidade em eternidade. Bendito seja o teu glorioso nome, que está exaltado sobre toda benção e louvor.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 6, 'Tu, só tu, és Senhor; tu fizeste o céu e o céu dos céus, juntamente com todo o seu exército, a terra e tudo quanto nela existe, os mares e tudo quanto neles já, e tu os conservas a todos, e o exército do céu te adora.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 7, 'Tu és o Senhor, o Deus que elegeste a Abrão, e o tiraste de Ur dos caldeus, e lhe puseste por nome Abraão;', 1, CURRENT_TIMESTAMP, false),
(16, 9, 8, 'e achaste o seu coração fiel perante ti, e fizeste com ele o pacto de que darias à sua descendência a terra dos cananeus, dos heteus, dos amorreus, dos perizeus, dos jebuseus e dos girgaseus; e tu cumpriste as tuas palavras, pois és justo.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 9, 'Também viste a aflição de nossos pais no Egito, e ouviste o seu clamor junto ao Mar Vermelho;', 1, CURRENT_TIMESTAMP, false),
(16, 9, 10, 'e o operaste sinais e prodígios contra Faraó; e contra todos os seus servos, e contra todo o povo da sua terra; pois sabias com que soberba eles os haviam tratado;  e assim adquiriste renome, como hoje se vê.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 11, 'Fendente o mar diante deles, de modo que passaram pelo meio do mar, em seco; e lançaste os seus perseguidores nas profundezas, como uma pedra nas águas impetuosas.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 12, 'Além disso tu os guiaste de dia por uma coluna de nuvem e de noite por uma coluna de fogo, para os alumiares no caminho por onde haviam de ir.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 13, 'Desceste sobre o monte Sinai, do céu falaste com eles, e lhes deste juízos retos e leis verdadeiras, bons estatutos e mandamentos;', 1, CURRENT_TIMESTAMP, false),
(16, 9, 14, 'o teu santo sábado lhes fizeste conhecer; e lhes ordenaste mandamentos e estatutos e uma lei, por intermédio de teu servo Moisés.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 15, 'Do céu lhes deste pão quando tiveram fome, e da rocha fizeste brotar água quando tiveram sede; e lhes ordenaste que entrassem para possuir a terra que com juramento lhes havias prometido dar.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 16, 'Eles, porém, os nossos pais, se houveram soberbamente e endureceram a cerviz, e não deram ouvidos aos teus mandamentos,', 1, CURRENT_TIMESTAMP, false),
(16, 9, 17, 'recusando ouvir-te e não se lembrando das tuas maravilhas, que fizeste no meio deles; antes endureceram a cerviz e, na sua rebeldia, levantaram um chefe, a fim de voltarem para sua servidão.  Tu, porém, és um Deus pronto para perdoar, clemente e misericordioso, tardio em irar-te e grande em beneficência, e não os abandonaste.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 18, 'Ainda mesmo quando eles fizeram para si um bezerro de fundição, e disseram: Este é o teu Deus, que te tirou do Egito, e cometeram grandes blasfêmias,', 1, CURRENT_TIMESTAMP, false),
(16, 9, 19, 'todavia tu, pela multidão das tuas misericórdias, não os abandonaste no deserto. A coluna de nuvem não se apartou deles de dia, para os guiar pelo caminho, nem a coluna de fogo de noite, para lhes alumiar o caminho por onde haviam de ir.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 20, 'Também lhes deste o teu bom espírito para os ensinar, e o teu maná não retiraste da tua boca, e água lhes deste quando tiveram sede.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 21, 'Sim, por quarenta anos os sustentaste no deserto; não lhes faltou coisa alguma;  a sua roupa não envelheceu, e o seus pés não se incharam.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 22, 'Além disso lhes deste reinos e povos, que lhes repartiste em porções; assim eles possuíram a terra de Siom, a saber;  a terra do rei de Hesbom, e a terra de Ogue, rei de Basã.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 23, 'Outrossim mulplicaste os seus filhos como as estrelas do céu, e os introduziste na terra de que tinhas dito a seus pais que nela entrariam para a possuírem.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 24, 'Os filhos, pois, entraram e possuíram a terra; e abateste perante eles, os moradores da terra, os cananeus, e lhos entregaste nas mãos, como também os seus reis, e os povos da terra, para fazerem deles conforme a sua vontade.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 25, 'Tomaram cidades fortificadas e uma terra fértil, e possuíram casas cheias de toda sorte de coisas boas, cisternas cavadas, vinhas e olivais, e árvores frutíferas em abundância; comeram, pois, fartaram-se e engordaram, e viveram em delícias, pela tua grande bondade.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 26, 'Não obstante foram desobedientes, e se rebelaram contra ti; lançaram a tua lei para trás das costas, e mataram os teus profetas que protestavam contra eles para que voltassem a ti; assim cometeram grandes provocações.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 27, 'Pelo que os entregaste nas mãos dos seus adversários, que os afligiram; mas no templo da sua angústia, quando eles clamaram a ti, tu os ouviste do céu; e segundo a multidão das tuas misericórdias lhes deste libertadores que os libertaram das mãos de seus adversários.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 28, 'Mas, tendo alcançado repouso, tornavam a fazer o mal diante de ti,; portanto tu os deixavas nas mãos dos seus inimigos, de modo que estes dominassem sobre eles; todavia quando eles voltavam e clamavam a ti, tu os ouvias do céu, e segundo a tua misericórdia os livraste muitas vezes;', 1, CURRENT_TIMESTAMP, false),
(16, 9, 29, 'e testemunhaste contra eles, para os fazerdes voltar para a tua lei; contudo eles se houveram soberbamente, e não deram ouvidos aos teus mandamentos, mas pecaram contra os teus juízos, pelos quais viverá o homem que os cumprir; viraram o ombro, endureceram a cerviz e não quiseram ouvir.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 30, 'Não obstante, por muitos anos os aturaste, e testemunhaste contra eles pelo teu Espírito, por intermédio dos teus profetas; todavia eles não quiseram dar ouvidos; pelo que os entregaste nas mãos dos povos de outras terras.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 31, 'Contudo pela tua grande misericórdia não os destruíste de todo, nem os abandonaste, porque és um Deus clemente e misericordioso.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 32, 'Agora, pois, ó nosso Deus, Deus grande, poderoso e temível, que guardas o pacto e a beneficência, não tenhas em pouca conta toda a aflição que nos alcançou a nós, a nossos reis, a nossos príncipes, a nossos sacerdotes, a nossos profetas, a nossos pais e a todo o teu povo, desde os dias dos reis da Assíria até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 33, 'Tu, porém, és justo em tudo quanto tem vindo sobre nós; pois tu fielmente procedeste, mas nós perversamente.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 34, 'Os nossos reis, os nossos príncipes, os nossos sacerdotes, e os nossos pais não têm guardado a tua lei, nem têm dado ouvidos aos teus mandamentos e aos teus testemunhos, com que testificaste contra eles.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 35, 'Porque eles, no seu reino, na muita abundância de bens que lhes deste, na terra espaçosa e fértil que puseste diante deles, não te serviram, nem se converteram de suas más obras.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 36, 'Eis que hoje somo escravos; e quanto à terra que deste a nossos pais, para comerem o seu fruto e o seu bem, eis que somos escravos nela.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 37, 'E ela multiplica os seus produtos para os reis que puseste sobre nós por causa dos nossos pecados; também eles dominam sobre os nossos corpos e sobre o nosso gado como bem lhes apraz, e estamos em grande angústia.', 1, CURRENT_TIMESTAMP, false),
(16, 9, 38, 'Contudo, por causa de tudo isso firmamos um pacto e o escrevemos; e selam-no os nossos príncipes, os nossos levitas e os nossos sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 1, 'Os que selaram foram: Neemias, o governador, filho de Hacalias, Zedequias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 2, 'Seraías, Azarias, Jeremias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 3, 'Pasur, Amarias, Malquias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 4, 'Hatus, Sebanias, Maluque,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 5, 'Harim, Meremote, Obadias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 6, 'Daniel, Ginetom, Baruque,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 7, 'Mesulão, Abias, Miamim,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 8, 'Maazias, Bilgai e Semaías; estes foram os sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 9, 'E os levitas: Jesuá, filho de Azanias, Binuí, dos filhos de Henadade, Cadmiel,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 10, 'e seus irmãos, Sebanias, Hodias, Quelita, Pelaías, Hanã,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 11, 'Mica, Reobe, Hasabias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 12, 'Zacur, Serebias, Sebanias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 13, 'Hodias, Bani e Benínu.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 14, 'Os chefes do povo: Parós, Paate-Moabe, Elão, Zatu, Bani,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 15, 'Buni, Azgade, Bebai,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 16, 'Adonias, Bigvai, Adim,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 17, 'Ater, Ezequias, Azur,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 18, 'Hodias, Asum, Bezai,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 19, 'Harife, Anotote, Nobai,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 20, 'Magpias, Mesulão, Hezir,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 21, 'Mesezabel, Zadoque, Jadua,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 22, 'Pelatias, Hanã, Anaías,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 23, 'Oséias, Hananias, Ananías,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 24, 'Haloés, Pilá, Sobeque,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 25, 'Reum, Hasabna, Maaséias,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 26, 'Aías, Hanã, Anã,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 27, 'Maluque, Harim e Baaná.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 28, 'E o resto do povo, os sacerdotes, os porteiros, os cantores, os netinins, e todos os que se tinham separado dos povos de outras terras para seguir a lei de Deus, suas mulheres, seus filhos e suas filhas, todos os que tinham conhecimento e entendimento,', 1, CURRENT_TIMESTAMP, false),
(16, 10, 29, 'aderiram a seus irmãos, os seus nobres, e convieram num juramento sob pena de maldição de que andariam na lei de Deus, a qual foi dada por intermédio de Moisés, servo de Deus, e de que guardariam e cumpririam todos os mandamentos do Senhor, nosso Senhor, e os seus juízos e os seus estatutos;', 1, CURRENT_TIMESTAMP, false),
(16, 10, 30, 'de que não daríamos as nossas filhas aos povos da terra, nem tomaríamos as filhas deles para os nossos filhos;', 1, CURRENT_TIMESTAMP, false),
(16, 10, 31, 'de que, se os povos da terra trouxessem no dia de sábado qualquer mercadoria ou quaisquer cereais para venderem, nada lhes compraríamos no sábado, nem em dia santificado; e de que abriríamos mão do produto do sétimo ano e da cobrança nele de todas as dívidas.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 32, 'Também sobre nós impusemos ordenanças, obrigando-nos a dar a cada ano a terça parte dum siclo para o serviço da casa do nosso Deus;', 1, CURRENT_TIMESTAMP, false),
(16, 10, 33, 'para os pães da proposição, para a contínua oferta de cereais, para o contínuo holocausto dos sábados e das luas novas, para as festas fixas, para as coisas sagradas, para as ofertas pelo pecado a fim de fazer expiação por Israel, e para toda a obra da casa do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 34, 'E nós, os sacerdotes, os levitas e o povo lançamos sortes acerca da oferta da lenha que havíamos de trazer à casa do nosso Deus, segundo as nossas casas paternas, a tempos determinados, de ano em ano, para se queimar sobre o altar do Senhor nosso Deus, como está escrito na lei.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 35, 'Também nos obrigamos a trazer de ano em ano à casa do Senhor as primícias de todos os frutos de todas as árvores;', 1, CURRENT_TIMESTAMP, false),
(16, 10, 36, 'e a trazer os primogênitos dos nossos filhos, e os do nosso gado, como está escrito na lei, e os primogênitos das nossas manadas e dos nossos rebanhos à casa do nosso Deus, aos sacerdotes que ministram na casa do nosso Deus;', 1, CURRENT_TIMESTAMP, false),
(16, 10, 37, 'e as primícias da nossa mas, e as nossas ofertas alçadas, e o fruto de toda sorte de árvores, para as câmaras da casa de nosso Deus; e os dízimos da nossa terra aos levitas; pois eles, os levitas, recebem os dízimos em todas as cidades por onde temos lavoura.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 38, 'E o sacerdote, filho de Arão, deve estar com os levitas quando estes receberem os dízimos; e os levitas devem trazer o dízimo dos dízimos à casa do nosso Deus, para as câmaras, dentro da tesouraria.', 1, CURRENT_TIMESTAMP, false),
(16, 10, 39, 'Pois os filhos de Israel e os filhos de Levi devem trazer ofertas alçadas dos cereais, do mosto e do azeite para aquelas câmaras, em que estão os utensílios do santuário, como também os sacerdotes que ministram, e os porteiros, e os cantores; e assim não negligenciarmos a casa do nosso Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 1, 'Ora, os príncipes do povo habitaram em Jerusalém; e o restante do povo lançou sortes, para atirar um de cada dez que habitasse na santa cidade de Jerusalém, ficando nove nas outras cidades.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 2, 'E o povo bendisse todos os homens que voluntariamente se ofereceram para habitar em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 3, 'Estes, pois, são os chefes da província que habitaram em Jerusalém; porém nas cidades de Judá habitou cada um na sua possessão, nas suas cidades, a saber, Israel, os sacerdotes, os levitas, os netinins e os filhos dos servos de Salomão.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 4, 'E habitaram em Jerusalém alguns dos filhos de Judá e dos filhos de Benjamim. Dos filhos de Judá: Ataías, filho de Uzias, filho de Zacarias, filho de Amarias, filho de Sefatias, filho de Maalelel, dos filhos de Pérez;', 1, CURRENT_TIMESTAMP, false),
(16, 11, 5, 'e Maaséias, filho de Baruque, filho de Col-Hoze, filho de Hazaías, filho de Adaías, filho de Joiaribe, filho de Zacarias, filho de Silôni.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 6, 'Todos os filhos de Pérez que habitaram em Jerusalém foram quatrocentos e sessenta e oito homens valentes.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 7, 'São estes os filhos de Benjamim: Salu, filho de Mesulão, filho de Joede, filho de Pedaías, filho de Colaías, filho de Maaséias, filho de Itiel, filho de Jesaías.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 8, 'E depois dele Gabai, Salai, ...novecentos e vinte e oito.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 9, 'Joel, filho de Zicri, superintendente sobre eles; e Judá, filho de Senua, o segundo sobre a cidade.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 10, 'Dos sacerdotes: Jedaías, filho de Joiaribe, Jaquim,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 11, 'Seraías, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Altube, príncipe sobre a casa de Deus;', 1, CURRENT_TIMESTAMP, false),
(16, 11, 12, 'e seus irmãos que faziam a obra da casa, oitocentos e vinte e dois; e Adaías, filho de Jeroão, filho de Pelalias, filho de Anzi, filho de Zacarias, filha de Pasur, filho de Malquias,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 13, 'e seus irmãos, cabeças de casas paternas, duzentos e quarenta e dois; e Amassai, filho de Azarel, filho de Aazai, filho de Mesilemote, filho de Imer,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 14, 'e os irmãos deles, homens valentes, cento e vinte e oito; e o superintendente sobre eles era Zabdiel, filho de Hagedolim.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 15, 'Dos levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, filho de Buni;', 1, CURRENT_TIMESTAMP, false),
(16, 11, 16, 'Sabetai e Jozabade, dos cabeças dos levitas, presidiam o serviço externo da casa de Deus;', 1, CURRENT_TIMESTAMP, false),
(16, 11, 17, 'Matanias, filho de Mica, filho de Zabdi, filho de Asafe, o dirigente que iniciava as ações de graças na oração, e Baquebuquias, o segundo entre seus irmãos; depois Abda, filho de Samua, filho de Galal, filho de Jedútun.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 18, 'Todos os levitas na santa cidade foram duzentos e oitenta e quatro.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 19, 'Também os porteiros, Acube, Talmom, e seus irmãos, os guardas das portas, foram cento e sessenta e dois.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 20, 'O resto de Israel e dos sacerdotes e levitas, habitou em todas as cidades de Judá, cada um na sua herança.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 21, 'Os netinins, porém, habitaram em Ofel; e Ziá e Gispa presidiram sobre eles.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 22, 'O superintendente dos levitas em Jerusalém era Uzi, filho de Bani, filho de Hasabias, filho de Matanias, filho de Mica, dos filhos de Asafe, os cantores; ele estava encarregado do serviço da casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 23, 'Pois havia uma ordem da parte do rei acerca deles, e uma norma para os cantores, estabelecendo o dever de cada dia.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 24, 'E Petaías, filho de Mesezabel, dos filhos de Zerá, filho de Judá, estava às ordens do rei, em todos os negócios concernentes ao povo.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 25, 'E quanto às aldeias com os seus campos, alguns dos filhos de Judá habitaram em Quiriate-Arba e seus arrabaldes, em Dibom e seus arrabaldes, e em Jecabzeel e suas aldeias;', 1, CURRENT_TIMESTAMP, false),
(16, 11, 26, 'em Jesuá, em Molada, em Bete-Pelete,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 27, 'Em Hazar-Sual, em Berseba e seus arrabaldes,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 28, 'em Ziclague, em Mecona e seus arrabaldes,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 29, 'em En-Rimom, em Zorá, em Jarmute,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 30, 'em Zanoa, em Adulão e suas aldeias, em Laquis e seus campos, e em Azeca e seus arrabaldes. Acamparam-se, pois, desde Berseba até o vale do Hinom.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 31, 'Os filhos de Benjamim também habitaram desde Geba em diante, em Micmás e Aíja, em Betel e seus arrabaldes,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 32, 'em Anatote, em Nobe, em Ananias,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 33, 'em Hazor, em Ramá, em Gitaim,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 34, 'em Hadide, em Zeboim, em Nebalate,', 1, CURRENT_TIMESTAMP, false),
(16, 11, 35, 'em Lode, e em Ono, vale dos artífices.', 1, CURRENT_TIMESTAMP, false),
(16, 11, 36, 'E dos levitas que habitavam em Judá, algumas turmas foram unidas a Benjamim.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 1, 'Ora, estes são os sacerdotes e os levitas que subiram com Zorobabel, filho de Sealtiel, e com Jesuá: Seraías, Jeremias, Esdras,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 2, 'Amarias, Maluque, Hatus,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 3, 'Ido, Ginetói, Abias,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 4, 'Secanias, Reum, Meremote,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 5, 'Miamim, Maadias, Bilga,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 6, 'Semaías, Joiaribe, Jedaías,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 7, 'Salu, Amoque, Hilquias e Jedaías; estes foram os chefes dos sacerdotes e de seus irmãos, nos dias de Jesuá.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 8, 'E os levitas: Jesuá, Binuí, Cadmiel, Serebias, Judá, Matanias; este e seus irmãos dirigiam os louvores.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 9, 'E Baquebuquias e Uni, seus irmãos, estavam defronte deles segundo os seus cargos.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 10, 'Jesuá foi pai de Joiaquim, Joiaquim de Eliasibe, Eliasibe de Joiada,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 11, 'Joiada de Jonatã, e Jonatã de Jadua.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 12, 'E nos dias de Joiaquim foram sacerdotes, chefes das casas paternas: por Seraías, Meraías; por Jeremias, Hananias;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 13, 'por Esdras, Mesulão; por Amarias, Jeoanã;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 14, 'por Malúqui, Jonatã; por Sebanias, José;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 15, 'por Harim, Adná; por Meraiote, Helcai;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 16, 'por Ido, Zacarias; por Gineton, Mesulão;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 17, 'por Abias, Zicri; por Miniamim, por Moadias, Piltai;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 18, 'por Bilga, Samua; por Semaías, Jeonatã;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 19, 'por Joiaribe, Matenai; por Jedaías, Uzi;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 20, 'por Salai, Calai; por Amoque, Eber;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 21, 'por Hilquias, Hasabias; por Jedaías, Netanel.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 22, 'Nos dias de Eliasibe, Joiada, Joanã e Jadua foram inscritos, dos levitas, os chefes das casas paternas; e assim também os dos sacerdotes, no reinado de Dário, o persa.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 23, 'Os filhos de Levi, chefes de casas paternas, foram inscritos no livro das crônicas, até os dias de Joanã, filho de Eliasibe.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 24, 'Foram, pois, os chefes dos levitas: Hasabias, Serebias, Jesuá, filho de Cadmiel, e seus irmãos que ficavam defronte deles, turma contra turma, para louvarem e darem graças, segundo a ordem de Davi, homem de Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 25, 'Matanias, Baquebuquias, Obadias, Mesulão, Talmom, e Acube eram porteiros, e faziam a guarda junto aos celeiros das portas.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 26, 'Estes viveram nos dias de Joiaquim, filho de Jesuá, filho de Jozadaque, como também nos dias de Neemias, o governador, e do sacerdote Esdras, o escriba.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 27, 'Ora, na dedicação dos muros de Jerusalém buscaram os levitas de todos os lugares, para os trazerem a Jerusalém, a fim de celebrarem a dedicação com alegria e com ações de graças, e com canto, címbalos, alaúdes e harpas.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 28, 'Ajuntaram-se os filhos dos cantores, tanto da campina dos arredores de Jerusalém, como das aldeias do netofatitas;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 29, 'como também de Bete-Gilgal, e dos campos de Geba e Azmavete; pois os cantores tinham edificado para si aldeias ao redor de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 30, 'E os sacerdotes e os levitas se purificaram, e purificaram o povo, as portas e o muro.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 31, 'Então fiz subir os príncipes de Judá sobre o muro, e constituí duas grandes companhias para darem graças e andarem em procissão, uma das quais foi para a direita sobre o muro, em direção à porta do monturo;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 32, 'e após ela seguiam Hosaías, e a metade dos príncipes de Judá,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 33, 'e Azarias, Esdras, Mesulão,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 34, 'Judá, Benjamim, Semaías, e Jeremias;', 1, CURRENT_TIMESTAMP, false),
(16, 12, 35, 'e dos filhos dos sacerdotes, levando trombetas, Zacarias, filho de Jonatã, filho de Semaías, filho de Matanias, filho de Micaías, filho de Zacur, filho de Asafe.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 36, 'e seus irmãos, Semaías, Azarel, Milalai, Gilalai, Maai, Netanel, Judá e Hanâni, com os instrumento musicais de Davi, homem de Deus; e Esdras, o escriba, ia adiante deles.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 37, 'À entrada da porta da fonte subiram diretamente as escadas da cidade de Davi onde começa a subida do muro, acima da casa de Davi, até a porta das águas a leste.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 38, 'A outra companhia dos que davam graças foi para a esquerda, seguindo-os eu com a metade do povo, sobre o muro, passando pela torre dos fornos até a muralha larga,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 39, 'e seguindo por cima da porta de Efraim, e da porta velha, e da porta dos peixes, e pela torre de Hananel, e a torre dos Cem até a porta das ovelhas; e pararam à porta da guarda.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 40, 'Assim as duas companhias dos que davam graças pararam na casa de Deus, como também eu e a metade dos magistrados que estavam comigo,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 41, 'e os sacerdotes Eliaquim, Maaséias, Miniamim, Micaías, Elioenai, Zacarias e Hananias, com trombetas,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 42, 'com também Maaséias, Semaías, Eleazar, Uzi, Jeoanã, Malquias, Elão, e Ézer; e os cantores cantavam, tendo Jezraías por dirigente.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 43, 'Naquele dia ofereceram grandes sacrifícios, e se alegraram, pois Deus lhes dera motivo de grande alegria; também as mulheres e as crianças se alegraram, de modo que o júbilo de Jerusalém se fez ouvir longe.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 44, 'No mesmo dia foram nomeados homens sobre as câmaras do tesouro para as ofertas alçadas, as primícias e os dízimos, para nelas recolherem, dos campos, das cidades, os quinhões designados pela lei para os sacerdotes e para os levitas; pois Judá se alegrava por estarem os sacerdotes e os levitas no seu posto,', 1, CURRENT_TIMESTAMP, false),
(16, 12, 45, 'observando os preceitos do seu Deus, e os da purificação, como também o fizeram os cantores e porteiros, conforme a ordem de Davi e de seu filho Salomão.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 46, 'Pois desde a antigüidade, já nos dias de Davi e de Asafe, havia um chefe dos cantores, e havia cânticos de louvor e de ação de graça a Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 12, 47, 'Pelo que todo o Israel, nos dias de Zorobabel e nos dias de Neemias, dava aos cantores e aos porteiros as suas porções destinadas aos levitas, e os levitas separavam as porções destinadas aos filhos de Arão.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 1, 'Naquele dia leu-se o livro de Moisés, na presença do povo, e achou-se escrito nele que os amonitas e os moabitas não entrassem jamais na assembléias de Deus;', 1, CURRENT_TIMESTAMP, false),
(16, 13, 2, 'porquanto não tinham saído ao encontro dos filhos de Israel com pão e água, mas contra eles assalariaram Balaão para os amaldiçoar; contudo o nosso Deus converteu a maldição em benção.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 3, 'Ouvindo eles esta lei, apartaram de Israel toda a multidão mista.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 4, 'Ora, antes disto Eliasibe, sacerdote, encarregado das câmaras da casa de nosso Deus, se aparentara com Tobias,', 1, CURRENT_TIMESTAMP, false),
(16, 13, 5, 'e lhe fizera uma câmara grande, onde dantes se recolhiam as ofertas de cereais, o incenso, os utensílios, os dízimos dos cereais, do mosto e do azeite, que eram dados por ordenança aos levitas, aos cantores e aos porteiros, como também as ofertas alçadas para os sacerdotes.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 6, 'Mas durante todo este tempo não estava eu em Jerusalém, porque no ano trinta e dois de Artaxerxes, rei da Babilônia, fui ter com o rei; mas a cabo de alguns dias pedi licença ao rei,', 1, CURRENT_TIMESTAMP, false),
(16, 13, 7, 'e vim a Jerusalém; e soube do mal que Eliasibe fizera em servir a Tobias, preparando-lhe uma câmara nos átrios da casa de Deus.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 8, 'Isso muito me desagradou; pelo que lancei todos os móveis da casa de Tobias fora da câmara.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 9, 'Então, por minha ordem purificaram as câmaras; e tornei a trazer para ali os utensílios da casa de Deus, juntamente com as ofertas de cereais e o incenso.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 10, 'Também soube que os quinhões dos levitas não se lhes davam, de maneira que os levitas e os cantores, que faziam o serviço, tinham fugido cada um para o seu campo.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 11, 'Então contendi com os magistrados e disse: Por que se abandonou a casa de Deus? Eu, pois, ajuntei os levitas e os cantores e os restaurei no seu posto.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 12, 'Então todo o Judá trouxe para os celeiros os dízimos dos cereais, do mosto e do azeite.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 13, 'E por tesoureiros pus sobre os celeiros Selemias, o sacerdote, e Zadoque, o escrivão, e Pedaías, dentre os levitas, e como ajudante deles Hanã, filho de Zacur, filho de Matanias, porque foram achados fiéis; e se lhes encarregou de fazerem a distribuição entre seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 14, 'Por isto, Deus meu, lembra-te de mim, e não risques as beneficências que eu tenho feito para a casa do meu Deus e para o serviço dela.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 15, 'Naqueles dias vi em Judá homens que pisavam lugares no sábado, e traziam molhos, que carregavam sobre jumentos; vi também vinho, uvas e figos, e toda sorte de cargas, que eles traziam a Jerusalém no dia de sábado; e protestei contra eles quanto ao dia em que estavam vendendo mantimentos.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 16, 'E em Jerusalém habitavam homens de Tiro, os quais traziam peixes e toda sorte de mercadorias, que vendiam no sábado aos filhos de Judá, e em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 17, 'Então contendi com os nobres de Judá, e lhes disse: Que mal é este que fazeis, profanando o dia de sábado?', 1, CURRENT_TIMESTAMP, false),
(16, 13, 18, 'Porventura não fizeram vossos pais assim, e não trouxe nosso Deus todo este mal sobre nós e sobre esta cidade? Contudo vós ainda aumentais a ira sobre Israel, profanando o sábado.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 19, 'E sucedeu que, ao começar a fazer-se escuro nas portas de Jerusalém, antes do sábado, eu ordenei que elas fossem fechadas, e mandei que não as abrissem até passar o sábado e pus às portas alguns de meus moços, para que nenhuma carga entrasse no dia de sábado.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 20, 'Então os negociantes e os vendedores de toda sorte de mercadorias passaram a noite fora de Jerusalém, uma ou duas vezes.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 21, 'Protestei, pois, contra eles, dizendo-lhes: Por que passais a noite defronte do muro? Se outra vez o fizerdes, hei de lançar mão em vós. Daquele tempo em diante não vieram no sábado.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 22, 'Também ordenei aos levitas que se purificassem, e viessem guardar as portas, para santificar o sábado. Nisso também, Deus meu, lembra-te de mim, e perdoa-me segundo a abundância da tua misericórdia.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 23, 'Vi também naqueles dias judeus que tinham casado com mulheres asdoditas, amonitas, e moabitas;', 1, CURRENT_TIMESTAMP, false),
(16, 13, 24, 'e seus filhos falavam no meio asdodita, e não podiam falar judaico, senão segundo a língua de seu povo.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 25, 'Contendi com eles, e os amaldiçoei; espanquei alguns deles e, arrancando-lhes os cabelos, os fiz jurar por Deus, e lhes disse: Não darei vossas filhas a seus filhos, e não tomareis suas filhas para vossos filhos, nem para vós mesmos.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 26, 'Não pecou nisso Salomão, rei de Israel? Entre muitas nações não havia rei semelhante a ele, e ele era amado de seu Deus, e Deus o constituiu rei sobre todo o Israel. Contudo mesmo a ele as mulheres estrangeiras o fizeram pecar.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 27, 'E dar-vos-íamos nós ouvidos, para fazermos todo este grande mal, esta infidelidade contra o nosso Deus, casando com mulheres estrangeiras?', 1, CURRENT_TIMESTAMP, false),
(16, 13, 28, 'Também um dos filhos de Joiada, filho do sumo sacerdote Eliasibe, era genro de Sambalate, o horonita, pelo que o afugentei de mim.', 1, CURRENT_TIMESTAMP, false),
(16, 13, 29, '(falta este versículo)', 1, CURRENT_TIMESTAMP, false),
(16, 13, 30, 'Assim os purifiquei de tudo que era estrangeiro, e determinei os cargos para os sacerdotes e para os levitas, cada um na sua função;', 1, CURRENT_TIMESTAMP, false),
(16, 13, 31, 'como também o que diz respeito à oferta da lenha em tempos determinados, e bem assim às primícias. Lembra-te de mim, Deus meu, para o meu bem.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 1, 'Falou o Senhor a Moisés no deserto de Sinai, na tenda da revelação, no primeiro dia do segundo mês, no segundo ano depois da saída dos filhos de Israel da terra do Egito, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 1, 2, 'Tomai a soma de toda a congregação dos filhos de Israel, segundo as suas famílias, segundo as casas de seus pais, conforme o número dos nomes de todo homem, cabeça por cabeça;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 3, 'os da idade de vinte anos para cima, isto é, todos os que em Israel podem sair à guerra, a esses contareis segundo os seus exércitos, tu e Arão.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 4, 'Estará convosco de cada tribo um homem que seja cabeça da casa de seus pais.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 5, 'Estes, pois, são os nomes dos homens que vos assistirão: de Rúben Elizur, filho de Sedeur;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 6, 'de Simeão, Selumiel, filho de Zurisadai;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 7, 'de Judá, Nasom, filho de Aminadabe;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 8, 'de Issacar, Netanel, filho de Zuar;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 9, 'de Zebulom, Eliabe, filho de Helom;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 10, 'dos filhos de José: de Efraim, Elisama, filho de Amiúde; de Manassés, Gamaliel, filho de Pedazur;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 11, 'de Benjamim, Abidã, filho de Gideôni;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 12, 'de Dã, Aizer, filho de Amisadai;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 13, 'de Aser, Pagiel, filho de Ocrã;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 14, 'de Gade, Eliasafe, filho de o Deuel;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 15, 'de Naftali, Airá, Filho de Enã.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 16, 'São esses os que foram chamados da congregação, os príncipes das tribos de seus pais, os cabeças dos milhares de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 17, 'Então tomaram Moisés e Arão a esses homens que são designados por nome;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 18, 'e, tendo ajuntado toda a congregação no primeiro dia do segundo mês, declararam a linhagem deles segundo as suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, cabeça por cabeça;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 19, 'como o Senhor ordenara a Moisés, assim este os contou no deserto de Sinai.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 20, 'Os filhos de Rúben o primogênito de Israel, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes, cabeça por cabeça, todo homem de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 21, 'os que foram contados deles, da tribo de Rúben eram quarenta e seis mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 22, 'Dos filhos de Simeão, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes, cabeça por cabeça, todo homem de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 23, 'os que foram contados deles, da tribo de Simeão, eram cinqüenta e nove mil e trezentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 24, 'Dos filhos de Gade, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair a guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 25, 'os que foram contados deles, da tribo de Gade, eram quarenta e cinco mil seiscentos e cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 26, 'Dos filhos de Judá, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair a guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 27, 'os que foram contados deles, da tribo de Judá, eram setenta e quatro mil e seiscentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 28, 'Dos filhos de Issacar, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair a guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 29, 'os que foram contados deles, da tribo de Issacar, eram cinqüenta e quatro mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 30, 'Dos filhos de Zebulom, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair a guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 31, 'os que foram contados deles, da tribo de Zebulom, eram cinqüenta e sete mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 32, 'Dos filhos de José: dos filhos de Efraim, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 33, 'os que foram contados deles, da tribo de Efraim, eram quarenta mil e quinhentos;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 34, 'e dos filhos de Manassés, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 35, 'os que foram contados deles, da tribo de Manassés, eram trinta e dois mil e duzentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 36, 'Dos filhos de Benjamim, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 37, 'os que foram contados deles, da tribo de Benjamim, eram trinta e cinco mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 38, 'Dos filhos de Dã, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 39, 'os que foram contados deles, da tribo de Dã, eram sessenta e dois mil e setecentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 40, 'Dos filhos de Aser, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o numero dos nomes dos de vinte anos para cima, todos os que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 41, 'os que foram contados deles, da tribo de Aser, eram quarenta e um mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 42, 'Dos filhos de Naftali, as suas gerações, pelas suas famílias, segundo as casas de seus pais, conforme o número dos nomes dos de vinte anos para cima, todos os que podiam sair a guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 43, 'os que foram contados deles, da tribo de Naftali, eram cinqüenta e três mil e quatrocentos,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 44, 'São esses os que foram contados por Moisés e Arão, e pelos príncipes de Israel, sendo estes doze homens e representando cada um a casa de seus pais.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 45, 'Assim todos os que foram contados dos filhos de Israel, segundo as casas de seus pais, de vinte anos para cima, todos os de Israel que podiam sair à guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 1, 46, 'sim, todos os que foram contados eram : seiscentos e três mil quinhentos e cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 47, 'Mas os levitas, segundo a tribo de e seus pais, não foram contados entre eles;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 48, 'porquanto o Senhor dissera a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 1, 49, 'Somente não contarás a tribo de Levi, nem tomarás a soma deles entre os filhos de Israel;', 1, CURRENT_TIMESTAMP, false),
(4, 1, 50, 'mas tu põe os levitas sobre o tabernáculo do testemunho, sobre todos os seus móveis, e sobre tudo o que lhe pertence. Eles levarão o tabernáculo e todos os seus móveis, e o administrarão; e acampar-se-ão ao redor do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 51, 'Quando o tabernáculo houver de partir, os levitas o desarmarão; e quando o tabernáculo se houver de assentar, os levitas o armarão; e o estranho que se chegar será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 52, 'Os filhos de Israel acampar-se-ão, cada um no seu arraial, e cada um junto ao seu estandarte, segundo os seus exércitos.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 53, 'Mas os levitas acampar-se-ão ao redor do tabernáculo do testemunho, para que não suceda acender-se ira contra a congregação dos filhos de Israel; pelo que os levitas terão o cuidado da guarda do tabernáculo do testemunho.', 1, CURRENT_TIMESTAMP, false),
(4, 1, 54, 'Assim fizeram os filhos de Israel; conforme tudo o que o Senhor ordenara a Moisés, assim o fizeram.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 1, 'Disse o Senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 2, 2, 'Os filhos de Israel acampar-se-ão, cada um junto ao seu estandarte, com as insígnias das casas de seus pais; ao redor, de frente para a tenda da revelação, se acamparão.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 3, 'Ao lado oriental se acamparão os do estandarte do arraial de Judá, segundo os seus exércitos; e Nasom, filho de Aminadabe, será o príncipe dos filhos de Judá.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 4, 'E o seu exército, os que foram contados deles, era de setenta e quatro mil e seiscentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 5, 'Junto a eles se acamparão os da tribo de Issacar; e Netanel, filho de Zuar, será o príncipe dos filhos de Issacar.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 6, 'E o seu exército, os que foram contados deles, era de cinqüenta e quatro mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 7, 'Depois a tribo de Zebulom; e Eliabe, filho de Helom, será o príncipe dos filhos de Zebulom.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 8, 'E o seu exército, os que foram contados deles, era de cinqüenta e sete mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 9, 'Todos os que foram contados do arraial de Judá eram cento e oitenta e seis mil e quatrocentos, segundo os seus exércitos. Esses marcharão primeiro.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 10, 'O estandarte do arraial de Rúben segundo os seus exércitos, estará para a banda do sul; e Elizur, filho de Sedeur, será o príncipe dos filhos de Rúben.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 11, 'E o seu exército, os que foram contados deles, era de quarenta e seis mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 12, 'Junto a ele se acamparão os da tribo de Simeão; e Selumiel, filho de Zurisadai, será o príncipe dos filhos de Simeão.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 13, 'E o seu exército, os que foram contados deles, era de cinqüenta e nove mil e trezentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 14, 'Depois a tribo de Gade; e Eliasafe, filho de Reuel, será o príncipe dos filhos de Gade.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 15, 'E o seu exército, os que foram contados deles, era de quarenta e cinco mil seiscentos e cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 16, 'Todos os que foram contados do arraial de Rúben eram cento e cinqüenta e um mil quatrocentos e cinqüenta, segundo os seus exércitos. Esses marcharão em segundo lugar.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 17, 'Então partirá a tenda da revelação com o arraial dos levitas no meio dos arraiais; como se acamparem, assim marcharão, cada um no seu lugar, segundo os seus estandartes.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 18, 'Para a banda do ocidente estará o estandarte do arraial de Efraim, segundo os seus exércitos; e Elisama, filho de Amiúde, será o príncipe dos filhos de Efraim.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 19, 'E o seu exército, os que foram contados deles, era de quarenta mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 20, 'Junto a eles estará a tribo de Manassés; e Gamaliel, filho de Pedazur, será o príncipe dos filhos de Manassés.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 21, 'E o seu exército, os que foram contados deles, era de trinta e dois mil e duzentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 22, 'Depois a tribo de Benjamim; e Abidã, filho de Gideôni, será o príncipe dos filhos de Benjamim.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 23, 'E o seu exército, os que foram contados deles, era de trinta e cinco mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 24, 'Todos os que foram contados o arraial de Efraim eram cento e oito mil e cem, segundo os seus exércitos. Esses marcharão em terceiro lugar.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 25, 'Para a banda do norte estará o estandarte do arraial de Dã, segundo os seus exércitos; e Aiezer, filho de Amisadai, será o príncipe dos filhos de Dã.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 26, 'E o seu exército, os que foram contados deles, era de sessenta e dois mil e setecentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 27, 'Junto a eles se acamparão os da tribo de Aser; e Pagiel, filho de Ocrã, será o príncipe dos filhos de Aser.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 28, 'E o seu exército, os que foram contados deles, era de quarenta e um mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 29, 'Depois a tribo de Naftali; e Airá, filho de Enã, será o príncipe dos filhos de Naftali.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 30, 'E o seu exército, os que foram contados deles, era de cinqüenta e três mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 31, 'Todos os que foram contados do arraial de Dã eram cento e cinqüenta e sete mil e seiscentos. Esses marcharão em último lugar, segundo os seus estandartes.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 32, 'São esses os que foram contados dos filhos de Israel, segundo as casas de seus pais; todos os que foram contados dos arraiais segundo os seus exércitos, eram seiscentos e três mil quinhentos e cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 33, 'Os levitas, porém, não foram contados entre os filhos de Israel, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 2, 34, 'Assim fizeram os filhos de Israel, conforme tudo o que o Senhor ordenara a Moisés; acamparam-se segundo os seus estandartes, e marcharam, cada qual segundo as suas famílias, segundo as casas de seus pais.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 1, 'Estas, pois, eram as gerações de Arão e de Moisés, no dia em que o Senhor falou com Moisés no monte Sinai.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 2, 'Os nomes dos filhos de Arão são estes: o primogênito, Nadabe; depois Abiú, Eleazar e Itamar.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 3, 'São esses os nomes dos filhos de Arão, dos sacerdotes que foram ungidos, a quem ele consagrou para administrarem o sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 4, 'Mas Nadabe e Abiú morreram perante o Senhor, quando ofereceram fogo estranho perante o Senhor no deserto de Sinai, e não tiveram filhos; porém Eleazar e Itamar administraram o sacerdócio diante de Arão, seu pai.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 5, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 3, 6, 'Faze chegar a tribo de Levi, e põe-nos diante de Arão, o sacerdote, para que o sirvam;', 1, CURRENT_TIMESTAMP, false),
(4, 3, 7, 'eles cumprirão o que é devido a ele e a toda a congregação, diante da tenda da revelação, fazendo o serviço do tabernáculo;', 1, CURRENT_TIMESTAMP, false),
(4, 3, 8, 'cuidarão de todos os móveis da tenda da revelação, e zelarão pelo cumprimento dos deveres dos filhos de Israel, fazendo o serviço do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 9, 'Darás, pois, os levitas a Arão e a seus filhos; de todo lhes são dados da parte dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 10, 'Mas a Arão e a seus filhos ordenarás que desempenhem o seu sacerdócio; e o estranho que se chegar será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 11, 'Disse mais o senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 3, 12, 'Eu, eu mesmo tenho tomado os levitas do meio dos filhos de Israel, em lugar de todo primogênito, que abre a madre, entre os filhos de Israel; e os levitas serão meus,', 1, CURRENT_TIMESTAMP, false),
(4, 3, 13, 'porque todos os primogênitos são meus. No dia em que feri a todos os primogênitos na terra do Egito, santifiquei para mim todos os primogênitos em Israel, tanto dos homens como dos animais; meus serão. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 14, 'Disse mais o Senhor a Moisés no deserto de Sinai:', 1, CURRENT_TIMESTAMP, false),
(4, 3, 15, 'Conta os filhos de Levi, segundo as casas de seus pais, pelas suas famílias; contarás todo homem da idade de um mês, para cima.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 16, 'E Moisés os contou conforme o mandado do Senhor, como lhe fora ordenado.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 17, 'Estes, pois, foram os filhos de Levi, pelos seus nomes: Gérson, Coate e Merári.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 18, 'E estes são os nomes dos filhos de Gérson pelas suas famílias: Líbni e Simei.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 19, 'E os filhos de Coate, pelas suas famílias: Anrão, Izar, Hebrom e Uziel.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 20, 'E os filhos de Merári, pelas suas famílias: Mali e Musi. São essas as famílias dos levitas, segundo as casas de seus pais.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 21, 'De Gérson era a família dos libnitas e a família dos simeítas. São estas as famílias dos gersonitas.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 22, 'Os que deles foram contados, segundo o número de todos os homens da idade de um mês para cima, sim, os que deles foram c contados eram sete mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 23, 'As famílias dos gersonitas acampar-se-ão atrás do tabernáculo, ao ocidente.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 24, 'E o príncipe da casa paterna dos gersonitas será Eliasafe, filho de Lael.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 25, 'E os filhos de Gérson terão a seu cargo na tenda da revelação o tabernáculo e a tenda, a sua coberta e o reposteiro da porta da tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 3, 26, 'e as cortinas do átrio, e o reposteiro da porta do átrio, que está junto ao tabernáculo e junto ao altar, em redor, como também as suas cordas para todo o seu serviço.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 27, 'De Coate era a família dos anramitas, e a família dos izaritas, e a família dos hebronitas, e a família dos uzielitas; são estas as famílias dos coatitas.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 28, 'Segundo o número de todos os homens da idade de um mês para cima, eram oito mil e seiscentos os que tinham a seu cargo o santuário.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 29, 'As famílias dos filhos de Coate acampar-se-ão ao lado do tabernáculo para a banda do sul.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 30, 'E o príncipe da casa paterna das famílias dos coatitas será Elizafã, filho de Uziel.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 31, 'Eles terão a seu cargo a arca e a mesa, o candelabro, os altares e os utensílios do santuário com que ministram, e o reposteiro com todo o seu serviço.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 32, 'E o príncipe dos príncipes de Levi será Eleazar, filho de Arão, o sacerdote; ele terá a superintendência dos que têm a seu cargo o santuário.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 33, 'De Merári era a família dos malitas e a família dos musitas; são estas as famílias de Merári.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 34, 'Os que deles foram contados, segundo o número de todos os homens de um mês para cima, eram seis mil e duzentos.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 35, 'E o príncipe da casa paterna das famílias de Merári será Zuriel, filho de Abiail; eles se acamparão ao lado do tabernáculo, para a banda do norte.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 36, 'Por designação os filhos de Merári terão a seu cargo as armações do tabernáculo e os seus travessões, as suas colunas e as suas bases, e todos os seus pertences, com todo o seu serviço,', 1, CURRENT_TIMESTAMP, false),
(4, 3, 37, 'e as colunas do átrio em redor e as suas bases, as suas estacas e as suas cordas.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 38, 'Diante do tabernáculo, para a banda do oriente, diante da tenda da revelação, acampar-se-ão Moisés, e Arão com seus filhos, que terão a seu cargo o santuário, para zelarem pelo cumprimento dos deveres dos filhos de Israel; e o estranho que se chegar será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 39, 'Todos os que foram contados dos levitas, que Moisés e Arão contaram por mandado do Senhor, segundo as suas famílias, todos os homens de um mês para cima, eram vinte e dois mil.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 40, 'Disse mais o Senhor a Moisés: Conta todos os primogênitos dos filhos de Israel, da idade de um mês para cima, e toma o número dos seus nomes.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 41, 'E para mim tomarás os levitas {eu sou o Senhor} em lugar de todos os primogênitos dos filhos de Israel, e o gado dos levitas em lugar de todos os primogênitos entre o gado de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 42, 'Moisés, pois, contou, como o Senhor lhe ordenara, todos os primogênitos entre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 43, 'E todos os primogênitos, pelo número dos nomes, da idade de um mês para cima, segundo os que foram contados deles, eram vinte e dois mil duzentos e setenta e três.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 44, 'Disse ainda mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 3, 45, 'Toma os levitas em lugar de todos os primogênitos entre os filhos de Israel, e o gado dos levitas em lugar do gado deles; porquanto os levitas serão meus. Eu sou o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 46, 'Pela redenção dos duzentos e setenta e três primogênitos dos filhos de Israel, que excedem o número dos levitas,', 1, CURRENT_TIMESTAMP, false),
(4, 3, 47, 'receberás por cabeça cinco siclos; conforme o siclo do santuário os receberás {o siclo tem vinte jeiras},', 1, CURRENT_TIMESTAMP, false),
(4, 3, 48, 'e darás a Arão e a seus filhos o dinheiro da redenção dos que excedem o número entre eles.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 49, 'Então Moisés recebeu o dinheiro da redenção dos que excederam o número dos que foram remidos pelos levitas;', 1, CURRENT_TIMESTAMP, false),
(4, 3, 50, 'dos primogênitos dos filhos de Israel recebeu o dinheiro, mil trezentos e sessenta e cinco siclos, segundo o siclo do santuário.', 1, CURRENT_TIMESTAMP, false),
(4, 3, 51, 'E Moisés deu o dinheiro da redenção a Arão e a seus filhos, conforme o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 1, 'Disse mais o Senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 4, 2, 'Tomai a soma dos filhos de Coate, dentre os filhos de Levi, pelas suas famílias, segundo as casas de seus pais,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 3, 'da idade de trinta anos para cima até os cinqüenta anos, de todos os que entrarem no serviço para fazerem o trabalho na tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 4, 'Este será o serviço dos filhos de Coate; na tenda da revelação, no tocante as coisas santíssimas:', 1, CURRENT_TIMESTAMP, false),
(4, 4, 5, 'Quando partir o arraial, Arão e seus filhos entrarão e, abaixando o véu do reposteiro, com ele cobrirão a arca do testemunho;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 6, 'por-lhe-ão por cima uma coberta de peles de golfinhos, e sobre ela estenderão um pano todo de azul, e lhe meterão os varais.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 7, 'Sobre a mesa dos pães da proposição estenderão um pano de azul, e sobre ela colocarão os pratos, as colheres, as tigelas e os cântaros para as ofertas de libação; também o pão contínuo estará sobre ela.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 8, 'Depois estender-lhe-ão por cima um pano de carmesim, o qual cobrirão com uma coberta de peles de golfinhos, e meterão à mesa os varais.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 9, 'Então tomarão um pano de azul, e cobrirão o candelabro da luminária, as suas lâmpadas, os seus espevitadores, os seus cinzeiros, e todos os seus vasos do azeite, com que o preparam;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 10, 'e o envolverão, juntamente com todos os seus utensílios, em uma coberta de peles de golfinhos, e o colocarão sobre os varais.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 11, 'Sobre o altar de ouro estenderão um pano de azul, e com uma coberta de peles de golfinhos o cobrirão, e lhe meterão os varais.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 12, 'Também tomarão todos os utensílios do ministério, com que servem no santuário, envolvê-los-ão num pano de azul e, cobrindo-os com uma coberta de peles de golfinhos, os colocarão sobre os varais.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 13, 'E, tirando as cinzas do altar, estenderão sobre ele um pano de púrpura;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 14, 'colocarão nele todos os utensílios com que o servem: os seus braseiros, garfos, as pás e as bacias, todos os utensílios do altar; e sobre ele estenderão uma coberta de peles de golfinhos, e lhe meterão os varais.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 15, 'Quando Arão e seus filhos, ao partir o arraial, acabarem de cobrir o santuário e todos os seus móveis, os filhos de Coate virão para levá-lo; mas nas coisas sagradas não tocarão, para que não morram; esse é o cargo dos filhos de Coate na tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 16, 'Eleazar, filho de Arão, o sacerdote, terá a seu cargo o azeite da luminária, o incenso aromático, a oferta contínua de cereais e o óleo da unção; isto é, terá a seu cargo todo o tabernáculo, e tudo o que nele há, o santuário e os seus móveis.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 17, 'Disse mais o Senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 4, 18, 'Não cortareis a tribo das famílias dos coatitas do meio dos levitas;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 19, 'mas isto lhes fareis, para que vivam e não morram, quando se aproximarem das coisas santíssimas: Arão e seus filhos entrarão e lhes designarão a cada um o seu serviço e o seu cargo;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 20, 'mas eles não entrarão a ver, nem por um momento, as coisas sagradas, para que não morram.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 21, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 4, 22, 'Toma também a soma dos filhos de Gérsom segundo as casas de seus pais, segundo as suas famílias;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 23, 'da idade de trinta anos para cima até os cinqüenta os contarás, a todos os que entrarem no serviço para fazerem o trabalho na tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 24, 'Este será o serviço das famílias dos gersonitas, ao servirem e ao levarem as cargas:', 1, CURRENT_TIMESTAMP, false),
(4, 4, 25, 'levarão as cortinas do tabernáculo, a tenda da revelação, a sua coberta, a coberta de peles de golfinhos, que está por cima, o reposteiro da porta da tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 26, 'as cortinas do átrio, o reposteiro da porta do átrio, que está junto ao tabernáculo e junto ao altar em redor, as suas cordas, e todos os instrumentos do seu serviço; enfim tudo quanto se houver de fazer no tocante a essas coisas, nisso hão de servir.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 27, 'Todo o trabalho dos filhos dos gersonitas, em todo o seu cargo, e em todo o seu serviço, será segundo o mandado de Arão e de seus filhos; e lhes designareis os cargos em que deverão servir.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 28, 'Este é o serviço das famílias dos filhos dos gersonitas na tenda da revelação; e o seu trabalho estará sob a direção de Itamar, filho de Arão, o sacerdote.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 29, 'Quanto aos filhos de Merári, contá-los-ás segundo as suas famílias, segundo as casas e seus pais;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 30, 'da idade de trinta anos para cima até os cinqüenta os contarás, a todos os que entrarem no serviço para fazerem o trabalho da tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 31, 'Este será o seu encargo, segundo todo o seu serviço na tenda da revelação: as armações do tabernáculo e os seus varais, as suas colunas e as suas bases,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 32, 'como também as colunas do átrio em redor e as suas bases, as suas estacas e as suas cordas, com todos os seus objetos, e com todo o seu serviço; e por nome lhes designareis os objetos que ficarão a seu cargo.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 33, 'Este é o serviço das famílias dos filhos de Merári, segundo todo o seu trabalho na tenda da revelação, sob a direção de Itamar, filho de Arão, o sacerdote.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 34, 'Moisés, pois, e Arão e os príncipes da congregação contaram os filhos dos coatitas, segundo as suas famílias, segundo as casas e seus pais,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 35, 'da idade de trinta anos para cima até os cinqüenta, todos os que entraram no serviço para o trabalho na tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(4, 4, 36, 'os que deles foram contados, pois, segundo as suas famílias, eram dois mil setecentos e cinqüenta.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 37, 'Esses são os que foram contados das famílias dos coatitas, isto é, todos os que haviam de servir na tenda da revelação, aos quais Moisés e Arão contaram, conforme o mandado do Senhor por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 38, 'Semelhantemente os que foram contados dos filhos de Gérsom segundo as suas famílias, segundo as casas de seus pais,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 39, 'da idade de trinta anos para cima até os cinqüenta, todos os que entraram no serviço, para o trabalho na tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 40, 'os que deles foram contados, segundo as suas famílias, segundo as casas de seus pais, eram dois mil seiscentos e trinta.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 41, 'Esses são os que foram contados das famílias dos filhos de Gérsom todos os que haviam de servir na tenda da revelação, aos quais Moisés e Arão contaram, conforme o mandado do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 42, 'E os que foram contados das famílias dos filhos de Merári, segundo as suas famílias, segundo as casas de seus pais,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 43, 'da idade de trinta anos para cima até os cinqüenta, todos os que entraram no serviço, para o trabalho na tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 44, 'os que deles foram contados, segundo as suas famílias, eram três mil e duzentos.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 45, 'Esses são os que foram contados das famílias dos filhos de Merári, aos quais Moisés e Arão contaram, conforme o mandado do Senhor por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 46, 'Todos os que foram contados dos levitas, aos quais contaram Moisés e Arão e os príncipes de Israel, segundo as suas famílias, segundo as casas de seus pais,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 47, 'da idade de trinta anos para cima até os cinqüenta, todos os que entraram no serviço para trabalharem e para levarem cargas na tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 4, 48, 'os que deles foram contados eram oito mil quinhentos e oitenta.', 1, CURRENT_TIMESTAMP, false),
(4, 4, 49, 'Conforme o mandado do Senhor foram contados por Moisés, cada qual segundo o seu serviço, e segundo o seu cargo; assim foram contados por ele, como o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 5, 2, 'Ordena aos filhos de Israel que lancem para fora do arraial a todo leproso, e a todo o que padece fluxo, e a todo o que está oriundo por ter tocado num morto;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 3, 'tanto homem como mulher os lançareis para fora, sim, para fora do arraial os lançareis; para que não contaminem o seu arraial, no meio do qual eu habito.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 4, 'Assim fizeram os filhos de Israel, lançando-os para fora do arraial; como o Senhor falara a Moisés, assim fizeram os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 5, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 5, 6, 'Dize aos filhos de Israel: Quando homem ou mulher pecar contra o seu próximo, transgredindo os mandamentos do Senhor, e tornando-se assim culpado,', 1, CURRENT_TIMESTAMP, false),
(4, 5, 7, 'confessará o pecado que tiver cometido, e pela sua culpa fará plena restituição, e ainda lhe acrescentará a sua quinta parte; e a dará àquele contra quem se fez culpado.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 8, 'Mas, se esse homem não tiver parente chegado, a quem se possa fazer a restituição pela culpa, esta será feita ao Senhor, e será do sacerdote, além do carneiro da expiação com que se fizer expiação por ele.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 9, 'Semelhantemente toda oferta alçada de todas as coisas consagradas dos filhos de Israel, que estes trouxerem ao sacerdote, será dele.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 10, 'Enfim, as coisas consagradas de cada um serão do sacerdote; tudo o que alguém lhe der será dele.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 11, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 5, 12, 'Fala aos filhos de Israel, e dize-lhes: Se a mulher de alguém se desviar pecando contra ele,', 1, CURRENT_TIMESTAMP, false),
(4, 5, 13, 'e algum homem se deitar com ela, sendo isso oculto aos olhos de seu marido e conservado encoberto, se ela se tiver contaminado, e contra ela não houver testemunha, por não ter sido apanhada em flagrante;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 14, 'se o espírito de ciúmes vier sobre ele, e de sua mulher tiver ciúmes, por ela se haver contaminado, ou se sobre ele vier o espírito de ciúmes, e de sua mulher tiver ciúmes, mesmo que ela não se tenha contaminado;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 15, 'o homem trará sua mulher perante o sacerdote, e juntamente trará a sua oferta por ela, a décima parte de uma efa de farinha de cevada, sobre a qual não deitará azeite nem porá incenso; porquanto é oferta de cereais por ciúmes, oferta memorativa, que traz a iniqüidade à memória.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 16, 'O sacerdote fará a mulher chegar, e a porá perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 17, 'E o sacerdote tomará num vaso de barro água sagrada; também tomará do pó que houver no chão do tabernáculo, e o deitará na água.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 18, 'Então apresentará a mulher perante o Senhor, e descobrirá a cabeça da mulher, e lhe porá na mão a oferta de cereais memorativa, que é a oferta de cereais por ciúmes; e o sacerdote terá na mão a água de amargura, que traz consigo a maldição;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 19, 'e a fará jurar, e dir-lhe-á: Se nenhum homem se deitou contigo, e se não te desviaste para a imundícia, violando o voto conjugal, sejas tu livre desta água de amargura, que traz consigo a maldição;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 20, 'mas se te desviaste, violando o voto conjugal, e te contaminaste, e algum homem que não é teu marido se deitou contigo,-', 1, CURRENT_TIMESTAMP, false),
(4, 5, 21, 'então o sacerdote, fazendo que a mulher tome o juramento de maldição, lhe dirá: O Senhor te ponha por maldição e praga no meio do teu povo, fazendo-te o Senhor consumir-se a tua coxa e inchar o teu ventre;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 22, 'e esta água que traz consigo a maldição entrará nas tuas entranhas, para te fazer inchar o ventre, e te fazer consumir-se a coxa. Então a mulher dirá: Amém, amém.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 23, 'Então o sacerdote escreverá estas maldições num livro, e na água de amargura as apagará;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 24, 'e fará que a mulher beba a água de amargura, que traz consigo a maldição; e a água que traz consigo a maldição entrará nela para se tornar amarga.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 25, 'E o sacerdote tomará da mão da mulher a oferta de cereais por ciúmes, e moverá a oferta de cereais perante o Senhor, e a trará ao altar;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 26, 'também tomará um punhado da oferta de cereais como memorial da oferta, e o queimará sobre o altar, e depois fará que a mulher beba a água.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 27, 'Quando ele tiver feito que ela beba a água, sucederá que, se ela se tiver contaminado, e tiver pecado contra seu marido, a água, que traz consigo a maldição, entrará nela, tornando-se amarga; inchar-lhe-á o ventre e a coxa se lhe consumirá; e a mulher será por maldição no meio do seu povo.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 28, 'E, se a mulher não se tiver contaminado, mas for inocente, então será livre, e conceberá filhos.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 29, 'Esta é a lei dos ciúmes, no tocante à mulher que, violando o voto conjugal, se desviar e for contaminada;', 1, CURRENT_TIMESTAMP, false),
(4, 5, 30, 'ou no tocante ao homem sobre quem vier o espírito de ciúmes, e se enciumar de sua mulher; ele apresentará a mulher perante o Senhor, e o sacerdote cumprirá para com ela toda esta lei.', 1, CURRENT_TIMESTAMP, false),
(4, 5, 31, 'Esse homem será livre da iniqüidade; a mulher, porém, levará sobre si a sua iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 6, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando alguém, seja homem, seja mulher, fizer voto especial de nazireu, a fim de se separar para o Senhor,', 1, CURRENT_TIMESTAMP, false),
(4, 6, 3, 'abster-se-á de vinho e de bebida forte; não beberá, vinagre de vinho, nem vinagre de bebida forte, nem bebida alguma feita de uvas, nem comerá uvas frescas nem secas.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 4, 'Por todos os dias do seu nazireado não comerá de coisa alguma que se faz da uva, desde os caroços até as cascas.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 5, 'Por todos os dias do seu voto de nazireado, navalha não passará sobre a sua cabeça; até que se cumpram os dias pelos quais ele se tenha separado para o Senhor, será santo; deixará crescer as guedelhas do cabelo da sua cabeça.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 6, 'Por todos os dias da sua separação para o Senhor, não se aproximará de cadáver algum.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 7, 'Não se contaminará nem por seu pai, nem por sua mãe, nem por seu irmão, nem por sua irmã, quando estes morrerem; porquanto o nazireado do seu Deus está sobre a sua cabeça:', 1, CURRENT_TIMESTAMP, false),
(4, 6, 8, 'Por todos os dias do seu nazireado será santo ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 9, 'Se alguém morrer subitamente junto dele, contaminando-se assim a cabeça do seu nazireado, rapará a sua cabera no dia da sua purificação, ao sétimo dia a rapará.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 10, 'Ao oitavo dia trará duas rolas ou dois pombinhos, ao sacerdote, à porta da tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(4, 6, 11, 'e o sacerdote oferecerá um como oferta pelo pecado, e o outro como holocausto, e fará expiação por esse que pecou no tocante ao morto; assim naquele mesmo dia santificará a sua cabeça.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 12, 'Então separará ao Senhor os dias do seu nazireado, e para oferta pela culpa trará um cordeiro de um ano; mas os dias antecedentes serão perdidos, porquanto o seu nazireado foi contaminado.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 13, 'Esta, pois, é a lei do nazireu: no dia em que se cumprirem os dias do seu nazireado ele será trazido à porta da tenda da revelação,', 1, CURRENT_TIMESTAMP, false),
(4, 6, 14, 'e oferecerá a sua oferta ao Senhor: um cordeiro de um ano, sem defeito, como holocausto, e uma cordeira de um ano, sem defeito, como oferta pelo pecado, e um carneiro sem defeito como oferta pacífica;', 1, CURRENT_TIMESTAMP, false),
(4, 6, 15, 'e um cesto de pães ázimos, bolos de flor de farinha amassados com azeite como também as respectivas ofertas de cereais e de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 16, 'E o sacerdote os apresentará perante o Senhor, e oferecerá a oferta pelo pecado, e o holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 6, 17, 'também oferecerá o carneiro em sacrifício de oferta pacífica ao Senhor, com o cesto de pães ázimos e as respectivas ofertas de cereais e de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 18, 'Então o nazireu, à porta da tenda da revelação, rapará o cabelo do seu nazireado, tomá-lo-á e o porá sobre o fogo que está debaixo do sacrifício das ofertas pacíficas.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 19, 'Depois o sacerdote tomará a espádua cozida do carneiro, e um pão ázimo do cesto, e um coscorão ázimo, e os porá nas mãos do nazireu, depois de haver este rapado o cabelo do seu nazireado;', 1, CURRENT_TIMESTAMP, false),
(4, 6, 20, 'e o sacerdote os moverá como oferta de movimento perante o Senhor; isto é santo para o sacerdote, juntamente com o peito da oferta de movimento, e com a espádua da oferta alçada; e depois o nazireu poderá beber vinho.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 21, 'Esta é a lei do que fizer voto de nazireu, e da sua oferta ao Senhor pelo seu nazireado, afora qualquer outra coisa que as suas posses lhe permitirem oferecer; segundo o seu voto, que fizer, assim fará conforme a lei o seu nazireado.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 22, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 6, 23, 'Fala a Arão, e a seus filhos, dizendo: Assim abençoareis os filhos de Israel; dir-lhes-eis:', 1, CURRENT_TIMESTAMP, false),
(4, 6, 24, 'O Senhor te abençoe e te guarde;', 1, CURRENT_TIMESTAMP, false),
(4, 6, 25, 'o Senhor faça resplandecer o seu rosto sobre ti, e tenha misericórdia de ti;', 1, CURRENT_TIMESTAMP, false),
(4, 6, 26, 'o Senhor levante sobre ti o seu rosto, e te dê a paz.', 1, CURRENT_TIMESTAMP, false),
(4, 6, 27, 'Assim porão o meu nome sobre os filhos de Israel, e eu os abençoarei.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 1, 'No dia em que Moisés acabou de levantar o tabernáculo, tendo-o ungido e santificado juntamente com todos os seus móveis, bem como o altar e todos os seus utensílios, depois de ungi-los e santificá-los,', 1, CURRENT_TIMESTAMP, false),
(4, 7, 2, 'os príncipes de Israel, cabeças das casas de seus pais, fizeram as suas ofertas. Estes eram os príncipes das tribos, os que estavam sobre os que foram contados.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 3, 'Trouxeram eles a sua oferta perante o Senhor: seis carros cobertos, e doze bois; por dois príncipes um carro, e por cada um, um boi; e os apresentaram diante do tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 4, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 7, 5, 'Recebe-os deles, para serem utilizados no serviço da tenda da revelação; e os darás aos levitas, a cada qual segundo o seu serviço:', 1, CURRENT_TIMESTAMP, false),
(4, 7, 6, 'Assim Moisés recebeu os carros e os bois, e os deu aos levitas.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 7, 'Dois carros e quatro bois deu aos filhos de Gérson segundo o seu serviço;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 8, 'e quatro carros e oito bois deu aos filhos de Merári, segundo o seu serviço, sob as ordens de Itamar, filho de Arão, o sacerdote.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 9, 'Mas aos filhos de Coate não deu nenhum, porquanto lhes pertencia o serviço de levar o santuário, e o levavam aos ombros.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 10, 'Os príncipes fizeram também oferta para a dedicação do altar, no dia em que foi ungido; e os príncipes apresentaram as suas ofertas perante o altar.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 11, 'E disse o Senhor a Moisés: Cada príncipe oferecerá a sua oferta, cada qual no seu dia, para a dedicação do altar.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 12, 'O que ofereceu a sua oferta no primeiro dia foi Nasom, filho de Aminadabe, da tribo de Judá.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 13, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambas cheias de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 14, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 15, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 16, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 17, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Nasom, filho de Aminadabe.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 18, 'No segundo dia fez a sua oferta Netanel, filho de Zuar, príncipe de Issacar.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 19, 'E como sua oferta ofereceu uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 20, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 21, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 22, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 23, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Netanel, filho de Zuar.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 24, 'No terceiro dia fez a sua oferta Eliabe, filho de Helom, príncipe dos filhos de Zebulom.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 25, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 26, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 27, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 28, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 29, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Eliabe, filho de Helom.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 30, 'No quarto dia fez a sua oferta Elizur, filho de Sedeur, príncipe dos filhos de Rúben.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 31, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 32, 'uma colher de ouro de dez siclos, cheio de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 33, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 34, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 35, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Elizur, filho de Sedeur.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 36, 'No quinto dia fez a sua oferta Selumiel, filho de Zurisadai, príncipe dos filhos de Simeão.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 37, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 38, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 39, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 40, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 41, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Selumiel, filho de Zurisadai.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 42, 'No sexto dia fez a sua oferta Eliasafe, filho de Deuel, príncipe dos filhos de Gade.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 43, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 44, 'uma colher de ouro do dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 45, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto; ,', 1, CURRENT_TIMESTAMP, false),
(4, 7, 46, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 47, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Eliasafe, filho de Deuel,', 1, CURRENT_TIMESTAMP, false),
(4, 7, 48, 'No sétimo dia fez a sua oferta Elisama, filho de Amiúde, príncipe dos filhos de Efraim.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 49, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassado com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 50, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 51, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 52, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 53, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Elisama, filho de Amiúde.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 54, 'No oitavo dia fez a sua oferta Gamaliel, filho de Pedazur, príncipe dos filhos de Manassés.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 55, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 56, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 57, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 58, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 59, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Gamaliel, filho de Pedazur.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 60, 'No dia nono fez a sua oferta Abidã, filho de Gideôni, príncipe dos filhos de Benjamim.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 61, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 62, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 63, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 64, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 65, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Abidã, filho de Gideôni.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 66, 'No décimo dia fez a sua oferta Aiezer, filho de Amisadai, príncipe filhos de Dã.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 67, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 68, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 69, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 70, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 71, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Aiezer, filho de Amisadai.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 72, 'No dia undécimo fez a sua oferta Pagiel, filho de Ocrã, príncipe dos filhos de Aser.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 73, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 74, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 75, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 76, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 77, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta do Pagiel, filho do Ocrã.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 78, 'No duodécimo dia fez a sua oferta Airá, filho de Enã, príncipe dos filhos de Naftali.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 79, 'A sua oferta foi uma salva de prata do peso de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de cereais;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 80, 'uma colher de ouro de dez siclos, cheia de incenso;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 81, 'um novilho, um carneiro, um cordeiro de um ano, para holocausto;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 82, 'um bode para oferta pelo pecado;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 83, 'e para sacrifício de ofertas pacíficas dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Airá, filho de Enã.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 84, 'Esta foi a oferta dedicatória do altar, feita pelos príncipes de Israel, no dia em que foi ungido: doze salvas de prata, doze bacias de prata, doze colheres de ouro,', 1, CURRENT_TIMESTAMP, false),
(4, 7, 85, 'pesando cada salva de prata cento e trinta siclos, e cada bacia setenta; toda a prata dos vasos foi dois mil e quatrocentos siclos, segundo o siclo do santuário;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 86, 'doze colheres de ouro cheias de incenso, pesando cada colher dez siclos, segundo o siclo do santuário; todo o ouro das colheres foi cento e vinte siclos.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 87, 'Todos os animais para holocausto foram doze novilhos, doze carneiros, e doze cordeiros de um ano, com as respectivas ofertas de cereais; e para oferta pelo pecado, doze bodes;', 1, CURRENT_TIMESTAMP, false),
(4, 7, 88, 'e todos os animais para sacrifício das ofertas pacíficas foram vinte e quatro novilhos, sessenta carneiros, sessenta bodes, e sessenta cordeiros de um ano. Esta foi a oferta dedicatória do altar depois que foi ungido.', 1, CURRENT_TIMESTAMP, false),
(4, 7, 89, 'Quando Moisés entrava na tenda da revelação para falar com o Senhor, ouvia a voz que lhe falava de cima do propiciatório, que está sobre a arca do testemunho entre os dois querubins; assim ele lhe falava.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 8, 2, 'Fala a Arão, e dize-lhe: Quando acenderes as lâmpadas, as sete lâmpadas alumiarão o espaço em frente do candelabro.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 3, 'Arão, pois, assim fez; acendeu as lâmpadas do candelabro de modo que alumiassem o espaço em frente do mesmo, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 4, 'Esta era a obra do candelabro, obra de ouro batido; desde o seu pedestal até as suas corolas, era ele de ouro batido; conforme o modelo que o Senhor mostrara a Moisés, assim ele tinha feito o candelabro.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 5, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 8, 6, 'Toma os levitas do meio dos filhos de Israel, e purifica-os;', 1, CURRENT_TIMESTAMP, false),
(4, 8, 7, 'e assim lhes farás, para os purificar: esparge sobre eles a água da purificação; e eles farão passar a navalha sobre todo o seu corpo, e lavarão os seus vestidos, e se purificarão.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 8, 'Depois tomarão um novilho, com a sua oferta de cereais de flor de farinha amassada com azeite; e tomarás tu outro novilho para oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 9, 'Também farás chegar os levitas perante a tenda da revelação, e ajuntarás toda a congregação dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 10, 'Apresentarás, pois, os levitas perante o Senhor, e os filhos do Israel porão as suas mãos sobre os levitas.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 11, 'E Arão oferecerá os levitas perante o Senhor como oferta de movimento, da parte dos filhos de Israel, para que sirvam no ministério do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 12, 'Os levitas porão as suas mãos sobre a cabeça dos novilhos; então tu sacrificarás um como oferta pelo pecado, e o outro como holocausto ao Senhor, para fazeres expiação pelos levitas.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 13, 'E porás os levitas perante Arão, e perante os seus filhos, e os oferecerás como oferta de movimento ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 14, 'Assim separarás os levitas do meio dos filhos de Israel; e os levitas serão meus.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 15, 'Depois disso os levitas entrarão para fazerem o serviço da tenda da revelação, depois de os teres purificado e oferecido como oferta de movimento.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 16, 'Porquanto eles me são dados inteiramente dentre os filhos de Israel; em lugar de todo aquele que abre a madre, isto é, do primogênito de todos os filhos de Israel, para mim os tenho tomado.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 17, 'Porque meu é todo primogênito entre os filhos de Israel, tanto entre os homens como entre os animais; no dia em que, na terra do Egito, feri a todo primogênito, os santifiquei para mim.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 18, 'Mas tomei os levitas em lugar de todos os primogênitos entre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 19, 'Dentre os filhos de Israel tenho dado os levitas a Arão e a seus filhos, para fazerem o serviço dos filhos de Israel na tenda da revelação, e para fazerem expiação por eles, a fim de que não haja praga entre eles, quando se aproximarem do santuário.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 20, 'Assim Moisés e Arão e toda a congregação dos filhos de Israel fizeram aos levitas; conforme tudo o que o Senhor ordenara a Moisés no tocante aos levitas, assim os filhos de Israel lhes fizeram.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 21, 'Os levitas, pois, purificaram-se, e lavaram os seus vestidos; e Arão os ofereceu como oferta de movimento perante o Senhor, e fez expiação por eles, para purificá-los.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 22, 'Depois disso entraram os levitas, para fazerem o seu serviço na tenda da revelação, perante Arão e seus filhos; como o Senhor ordenara a Moisés acerca dos levitas, assim lhes fizeram.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 23, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 8, 24, 'Este será o encargo dos levitas: Da idade de vinte e cinco anos para cima entrarão para se ocuparem no serviço a tenda da revelação;', 1, CURRENT_TIMESTAMP, false),
(4, 8, 25, 'e aos cinqüenta anos de idade sairão desse serviço e não servirão mais.', 1, CURRENT_TIMESTAMP, false),
(4, 8, 26, 'Continuarão a servir, porém, com seus irmãos na tenda da revelação, orientando-os no cumprimento dos seus encargos; mas não farão trabalho. Assim farás para com os levitas no tocante aos seus cargos.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 1, 'Também falou o Senhor a Moisés no deserto de Sinai, no primeiro mês do segundo ano depois que saíram da terra do Egito, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 9, 2, 'Celebrem os filhos de Israel a páscoa a seu tempo determinado.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 3, 'No dia catorze deste mês, à tardinha, a seu tempo determinado, a celebrareis; segundo todos os seus estatutos, e segundo todas as suas ordenanças a celebrareis.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 4, 'Disse, pois, Moisés aos filhos de Israel que celebrassem a páscoa.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 5, 'Então celebraram a páscoa no dia catorze do primeiro mês, à tardinha, no deserto de Sinai; conforme tudo o que o Senhor ordenara a Moisés, assim fizeram os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 6, 'Ora, havia alguns que se achavam imundos por terem tocado o cadáver de um homem, de modo que não podiam celebrar a páscoa naquele dia; pelo que no mesmo dia se chegaram perante Moisés e Arão;', 1, CURRENT_TIMESTAMP, false),
(4, 9, 7, 'e aqueles homens disseram-lhes: Estamos imundos por havermos tocado o cadáver de um homem; por que seríamos privados de oferecer a oferta do Senhor a seu tempo determinado no meio dos filhos de Israel?', 1, CURRENT_TIMESTAMP, false),
(4, 9, 8, 'Respondeu-lhes Moisés: Esperai, para que eu ouça o que o Senhor há de ordenar acerca de vós.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 9, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 9, 10, 'Fala aos filhos de Israel, dizendo: Se alguém dentre vós, ou dentre os vossos descendentes estiver imundo por ter tocado um cadáver, ou achar-se longe, em viagem, contudo ainda celebrará a páscoa ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 11, 'No segundo mês, no dia: catorze, à tardinha, a celebrarão; comê-la-ão com pães ázimos e ervas amargas.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 12, 'Dela não deixarão nada até pela manhã, nem quebrarão dela osso algum; segundo todo o estatuto da páscoa a celebrarão.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 13, 'Mas o homem que, estando limpo e não se achando em viagem, deixar de celebrar a páscoa, essa alma será extirpada do seu povo; porquanto não ofereceu a oferta do Senhor a seu tempo determinado, tal homem levará o seu pecado.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 14, 'Também se um estrangeiro peregrinar entre vós e celebrar a páscoa ao Senhor, segundo o estatuto da páscoa e segundo a sua ordenança a celebrará; haverá um só estatuto, quer para o estrangeiro, quer para o natural da terra.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 15, 'No dia em que foi levantado o tabernáculo, a nuvem cobriu o tabernáculo, isto é, a própria tenda do testemunho; e desde a tarde até pela manhã havia sobre o tabernáculo uma aparência de fogo.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 16, 'Assim acontecia de contínuo: a nuvem o cobria, e de noite havia aparência de fogo.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 17, 'Mas sempre que a nuvem se alçava de sobre a tenda, os filhos de Israel partiam; e no lugar em que a nuvem parava, ali os filhos de Israel se acampavam.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 18, 'À ordem do Senhor os filhos de Israel partiam, e à ordem do Senhor se acampavam; por todos os dias em que a nuvem parava sobre o tabernáculo eles ficavam acampados.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 19, 'E, quando a nuvem se detinha sobre o tabernáculo muitos dias, os filhos de Israel cumpriam o mandado do Senhor, e não partiam.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 20, 'Às vezes a nuvem ficava poucos dias sobre o tabernáculo; então à ordem do Senhor permaneciam acampados, e à ordem do Senhor partiam.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 21, 'Outras vezes ficava a nuvem desde a tarde até pela manhã; e quando pela manhã a nuvem se alçava, eles partiam; ou de dia ou de noite, alçando-se a nuvem, partiam.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 22, 'Quer fosse por dois dias, quer por um mês, quer por mais tempo, que a nuvem se detinha sobre o tabernáculo, enquanto ficava sobre ele os filhos de Israel permaneciam acampados, e não partiam; mas, alçando-se ela, eles partiam.', 1, CURRENT_TIMESTAMP, false),
(4, 9, 23, 'À ordem do Senhor se acampavam, e à ordem do Senhor partiam; cumpriam o mandado do Senhor, que ele lhes dera por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 10, 2, 'Faze-te duas trombetas de prata; de obra batida as farás, e elas te servirão para convocares a congregação, e para ordenares a partida dos arraiais.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 3, 'Quando se tocarem as trombetas, toda a congregação se ajuntará a ti à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 4, 'Mas quando se tocar uma só, a ti se congregarão os príncipes, os cabeças dos milhares de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 5, 'Quando se tocar retinindo, partirão os arraiais que estão acampados da banda do oriente.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 6, 'Mas quando se tocar retinindo, pela segunda, vez, partirão os arraiais que estão acampados da banda do sul; para as partidas dos arraiais se tocará retinindo.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 7, 'Mas quando se houver de reunir a congregação, tocar-se-á sem retinir:', 1, CURRENT_TIMESTAMP, false),
(4, 10, 8, 'Os filhos de Arão, sacerdotes, tocarão as trombetas; e isto vos será por estatuto perpétuo nas vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 9, 'Ora, quando na vossa terra sairdes à guerra contra o inimigo que vos estiver oprimindo, fareis retinir as trombetas; e perante o Senhor vosso Deus sereis tidos em memória, e sereis salvos dos vossos inimigos.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 10, 'Semelhantemente, no dia da vossa alegria, nas vossas festas fixas, e nos princípios dos vossos meses, tocareis as trombetas sobre os vossos holocaustos, e sobre os sacrifícios de vossas ofertas pacíficas; e eles vos serão por memorial perante vosso Deus. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 11, 'Ora, aconteceu, no segundo ano, no segundo mês, aos vinte do mês, que a nuvem se alçou de sobre o tabernáculo da congregação.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 12, 'Partiram, pois, os filhos de Israel do deserto de Sinai para as suas jornadas; e a nuvem parou ,no deserto de Parã.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 13, 'Assim iniciaram a primeira caminhada, à ordem do Senhor por intermédio de Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 10, 14, 'partiu primeiramente o estandarte do arraial dos filhos de Judá segundo os seus exércitos; sobre o seu exército estava Nasom, filho de Aminadabe;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 15, 'sobre o exército da tribo dos filhos de Issacar, Netanel, filho de Zuar;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 16, 'e sobre o exército da tribo dos filhos de Zebulom, Eliabe, filho de Helom.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 17, 'Então o tabernáculo foi desarmado, e os filhos de Gérson e os filhos de Merári partiram, levando o tabernáculo.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 18, 'Depois partiu o estandarte do arraial de Rúben segundo os seus exércitos; sobre o seu exército estava Elizur, filho de Sedeur;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 19, 'sobre o exército da tribo dos filhos de Simeão, Selumiel, filho de Zurisadai;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 20, 'e sobre o exército da tribo dos filhos de Gade, Eliasafe, filho de Deuel.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 21, 'Então partiram os coatitas, levando o santuário; e os outros erigiam o tabernáculo, enquanto estes vinham.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 22, 'Depois partiu o estandarte do arraial dos filhos de Efraim segundo os seus exércitos; sobre o seu exército estava Elisama, filho de Amiúde;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 23, 'sobre o exército da tribo dos filhos de Manassés, Gamaliel, filho de Pedazur;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 24, 'e sobre o exército da tribo dos filhos de Benjamim, Abidã, filho de Gideôni.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 25, 'Então partiu o estandarte do arraial dos filhos de Dã, que era a retaguarda de todos os arraiais, segundo os seus exércitos; sobre o seu exército estava Aiezer, filho de Amisadai;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 26, 'sobre o exército da tribo dos filhos de Aser, Pagiel, filho de Ocrã;', 1, CURRENT_TIMESTAMP, false),
(4, 10, 27, 'e sobre o exército da tribo dos filhos de Naftali, Airá, filho de Enã.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 28, 'Tal era a ordem de partida dos filhos de Israel segundo os seus exércitos, quando partiam.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 29, 'Disse então Moisés a Hobabe, filho de Reuel, o midianita, sogro de Moisés: Nós caminhamos para aquele lugar de que o Senhor disse: Vo-lo darei. Vai conosco, e te faremos bem; porque o Senhor falou bem acerca de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 30, 'Respondeu ele: Não irei; antes irei à minha terra e à minha parentela.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 31, 'Tornou-lhe Moisés: Ora, não nos deixes, porquanto sabes onde devamos acampar no deserto; de olhos nos serviras.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 32, 'Se, pois, vieres conosco, o bem que o Senhor nos fizer, também nós faremos a ti.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 33, 'Assim partiram do monte do Senhor caminho de três dias; e a arca do pacto do Senhor ia adiante deles, para lhes buscar lugar de descanso.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 34, 'E a nuvem do Senhor ia sobre eles de dia, quando partiam do arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 35, 'Quando, pois, a arca partia, dizia Moisés: Levanta-te, Senhor, e dissipados sejam os teus inimigos, e fujam diante de ti os que te odeiam.', 1, CURRENT_TIMESTAMP, false),
(4, 10, 36, 'E, quando ela pousava, dizia: Volta, ó Senhor, para os muitos milhares de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 1, 'Depois o povo tornou-se queixoso, falando o que era mau aos ouvidos do Senhor; e quando o Senhor o ouviu, acendeu-se a sua ira; o fogo do Senhor irrompeu entre eles, e devorou as extremidades do arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 2, 'Então o povo clamou a Moisés, e Moisés orou ao Senhor, e o fogo se apagou.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 3, 'Pelo que se chamou aquele lugar Taberá, porquanto o fogo do Senhor se acendera entre eles.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 4, 'Ora, o vulgo que estava no meio deles veio a ter grande desejo; pelo que os filhos de Israel também tornaram a chorar, e disseram: Quem nos dará carne a comer?', 1, CURRENT_TIMESTAMP, false),
(4, 11, 5, 'Lembramo-nos dos peixes que no Egito comíamos de graça, e dos pepinos, dos melões, dos porros, das cebolas e dos alhos.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 6, 'Mas agora a nossa alma se seca; coisa nenhuma há senão este maná diante dos nossos olhos.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 7, 'E era o maná como a semente do coentro, e a sua aparência como a aparência de bdélio.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 8, 'O povo espalhava-se e o colhia, e, triturando-o em moinhos ou pisando-o num gral, em panelas o cozia, e dele fazia bolos; e o seu sabor era como o sabor de azeite fresco.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 9, 'E, quando o orvalho descia de noite sobre o arraial, sobre ele descia também o maná.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 10, 'Então Moisés ouviu chorar o povo, todas as suas famílias, cada qual à porta da sua tenda; e a ira do Senhor grandemente se acendeu; e aquilo pareceu mal aos olhos de Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 11, 'Disse, pois, Moisés ao Senhor: Por que fizeste mal a teu servo, e por que não achei graça aos teus olhos, pois que puseste sobre mim o peso de todo este povo.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 12, 'Concebi eu porventura todo este povo? dei-o eu à luz, para que me dissesses: Leva-o ao teu colo, como a ama leva a criança de peito, para a terra que com juramento prometeste a seus pais?', 1, CURRENT_TIMESTAMP, false),
(4, 11, 13, 'Donde teria eu carne para dar a todo este povo? porquanto choram diante de mim, dizendo: Dá-nos carne a comer.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 14, 'Eu só não posso: levar a todo este povo, porque me é pesado demais.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 15, 'Se tu me hás de tratar assim, mata-me, peço-te, se tenho achado graça aos teus olhos; e não me deixes ver a minha miséria.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 16, 'Disse então o Senhor a Moisés: Ajunta-me setenta homens dos anciãos de Israel, que sabes serem os anciãos do povo e seus oficiais; e os trarás perante a tenda da revelação, para que estejam ali contigo.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 17, 'Então descerei e ali falarei contigo, e tirarei do espírito que está sobre ti, e o porei sobre eles; e contigo levarão eles o peso do povo para que tu não o leves só.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 18, 'E dirás ao povo: Santificai-vos para amanhã, e comereis carne; porquanto chorastes aos ouvidos do Senhor, dizendo: Quem nos dará carne a comer? pois bem nos ia no Egito. Pelo que o Senhor vos dará carne, e comereis.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 19, 'Não comereis um dia, nem dois dias, nem cinco dias, nem dez dias, nem vinte dias;', 1, CURRENT_TIMESTAMP, false),
(4, 11, 20, 'mas um mês inteiro, até vos sair pelas narinas, até que se vos torne coisa nojenta; porquanto rejeitastes ao Senhor, que está no meio de vós, e chorastes diante dele, dizendo: Por que saímos do Egito?', 1, CURRENT_TIMESTAMP, false),
(4, 11, 21, 'Respondeu Moisés: Seiscentos mil homens de pé é este povo no meio do qual estou; todavia tu tens dito: Dar-lhes-ei carne, e comerão um mês inteiro.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 22, 'Matar-se-ão para eles rebanhos e gados, que lhes bastem? ou ajuntar-se-ão, para eles todos os peixes do mar, que lhes bastem?', 1, CURRENT_TIMESTAMP, false),
(4, 11, 23, 'Pelo que replicou o Senhor a Moisés: Porventura tem-se encurtado a mão do Senhor? agora mesmo verás se a minha palavra se há de cumprir ou não.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 24, 'Saiu, pois, Moisés, e relatou ao povo as palavras do Senhor; e ajuntou setenta homens dentre os anciãos do povo e os colocou ao redor da tenda.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 25, 'Então o Senhor desceu: na nuvem, e lhe falou; e, tirando do espírito que estava sobre ele, pô-lo sobre aqueles setenta anciãos; e aconteceu que, quando o espírito repousou sobre eles profetizaram, mas depois nunca mais o fizeram.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 26, 'Mas no arraial ficaram dois homens; chamava-se um Eldade, e o outro Medade; e repousou sobre eles: o espírito, porquanto estavam entre os inscritos, ainda que não saíram para irem à tenda; e profetizavam no arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 27, 'Correu, pois, um moço, e anunciou a Moisés: Eldade e Medade profetizaram no arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 28, 'Então Josué, filho de Num, servidor de Moisés, um dos seus mancebos escolhidos, respondeu e disse: Meu Senhor Moisés, proíbe-lho.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 29, 'Moisés, porém, lhe disse: Tens tu ciúmes por mim? Oxalá que do povo do Senhor todos fossem profetas, que o Senhor pusesse o seu espírito sobre eles!', 1, CURRENT_TIMESTAMP, false),
(4, 11, 30, 'Depois Moisés se recolheu ao arraial, ele e os anciãos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 31, 'Soprou, então, um vento da parte do Senhor e, do lado do mar, trouxe codornizes que deixou cair junto ao arraial quase caminho de um dia de um e de outro lado, à roda do arraial, a cerca de dois côvados da terra.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 32, 'Então o povo, levantando-se, colheu as codornizes por todo aquele dia e toda aquela noite, e por todo o dia seguinte; o que colheu menos, colheu dez hômeres. E as estenderam para si ao redor do arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 33, 'Quando a carne ainda estava entre os seus dentes, antes que fosse mastigada, acendeu-se a ira do Senhor contra o povo, e feriu o Senhor ao povo com uma praga, mui grande.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 34, 'Pelo que se chamou aquele lugar Quibrote-Taavá, porquanto ali enterraram o povo que tivera o desejo.', 1, CURRENT_TIMESTAMP, false),
(4, 11, 35, 'De Quibrote-Taavá partiu o povo para Hazerote; e demorou-se em Hazerote.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 1, 'Ora, falaram Miriã e Arão contra Moisés, por causa da mulher cuchita que este tomara; porquanto tinha tomado uma mulher cuchita.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 2, 'E disseram: Porventura falou o Senhor somente por Moisés? Não falou também por nós? E o Senhor o ouviu.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 3, 'Ora, Moisés era homem mui manso, mais do que todos os homens que havia sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 4, 'E logo o Senhor disse a Moisés, a Arão e a Miriã: Saí vos três à tenda da revelação. E saíram eles três.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 5, 'Então o Senhor desceu em uma coluna de nuvem, e se pôs à porta da tenda; depois chamou a Arão e a Miriã, e os dois acudiram.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 6, 'Então disse: Ouvi agora as minhas palavras: se entre vós houver profeta, eu, o Senhor, a ele me farei conhecer em visão, em sonhos falarei com ele.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 7, 'Mas não é assim com o meu servo Moisés, que é fiel em toda a minha casa;', 1, CURRENT_TIMESTAMP, false),
(4, 12, 8, 'boca a boca falo com ele, claramente e não em enigmas; pois ele contempla a forma do Senhor. Por que, pois, não temestes falar contra o meu servo, contra Moisés?', 1, CURRENT_TIMESTAMP, false),
(4, 12, 9, 'Assim se acendeu a ira do Senhor contra eles; e ele se retirou;', 1, CURRENT_TIMESTAMP, false),
(4, 12, 10, 'também a nuvem se retirou de sobre a tenda; e eis que Miriã se tornara leprosa, branca como a neve; e olhou Arão para Miriã e eis que estava leprosa.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 11, 'Pelo que Arão disse a Moisés: Ah, meu senhor! rogo-te não ponhas sobre nós este pecado, porque procedemos loucamente, e pecamos.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 12, 'Não seja ela como um morto que, ao sair do ventre de sua mãe, tenha a sua carne já meio consumida.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 13, 'Clamou, pois, Moisés ao Senhor, dizendo: Ó Deus, rogo-te que a cures.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 14, 'Respondeu o Senhor a Moisés: Se seu pai lhe tivesse cuspido na cara não seria envergonhada por sete dias? Esteja fechada por sete dias fora do arraial, e depois se recolherá outra vez.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 15, 'Assim Miriã esteve fechada fora do arraial por sete dias; e o povo não partiu, enquanto Miriã não se recolheu de novo.', 1, CURRENT_TIMESTAMP, false),
(4, 12, 16, 'Mas depois o povo partiu de Hazerote, e acampou-se no deserto de Parã.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 1, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 13, 2, 'Envia homens que espiem a terra de Canaã, que eu hei de dar aos filhos de Israel. De cada tribo de seus pais enviarás um homem, sendo cada qual príncipe entre eles.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 3, 'Moisés, pois, enviou-os do deserto de Parã, segundo a ordem do Senhor; eram todos eles homens principais dentre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 4, 'E estes são os seus nomes: da tribo de Rúben, Samua, filho de Zacur;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 5, 'da tribo de Simeão, Safate, filho de Hori;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 6, 'da tribo de Judá, Calebe, filho de Jefoné;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 7, 'da tribo de Issacar, Ioal, filho de José;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 8, 'da tribo de Efraim, Oséias, filho de Num;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 9, 'da tribo de Benjamim, Palti, filho de Rafu;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 10, 'da tribo de Zebulom, Gadiel, filho de Sódi;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 11, 'da tribo de José, pela tribo de Manassés, Gadi, filho de Susi;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 12, 'da tribo de Dã, Amiel, filho de Gemali;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 13, 'da tribo de Aser, Setur, filho de Micael;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 14, 'da tribo de Naftali, Nabi, filho de Vofsi;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 15, 'da tribo de Gade, Geuel, filho de Maqui.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 16, 'Estes são os nomes dos homens que Moisés enviou a espiar a terra. Ora, a Oséias, filho de Num, Moisés chamou Josué.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 17, 'Enviou-os, pois, Moisés a espiar: a terra de Canaã, e disse-lhes: Subi por aqui para o Negebe, e penetrai nas montanhas;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 18, 'e vede a terra, que tal é; e o povo que nela habita, se é forte ou fraco, se pouco ou muito;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 19, 'que tal é a terra em que habita, se boa ou má; que tais são as cidades em que habita, se arraiais ou fortalezas;', 1, CURRENT_TIMESTAMP, false),
(4, 13, 20, 'e que tal é a terra, se gorda ou magra; se nela há árvores, ou não; e esforçai-vos, e tomai do fruto da terra. Ora, a estação era a das uvas temporãs.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 21, 'Assim subiram, e espiaram a terra desde o deserto de Zim, até Reobe, à entrada de Hamate.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 22, 'E subindo para o Negebe, vieram até Hebrom, onde estavam Aimã, Sesai e Talmai, filhos de Anaque. {Ora, Hebrom foi edificada sete anos antes de Zoã no Egito. }', 1, CURRENT_TIMESTAMP, false),
(4, 13, 23, 'Depois vieram até e vale de Escol, e dali cortaram um ramo de vide com um só cacho, o qual dois homens trouxeram sobre uma verga; trouxeram também romãs e figos.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 24, 'Chamou-se aquele lugar o vale de Escol, por causa do cacho que dali cortaram os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 25, 'Ao fim de quarenta dias voltaram de espiar a terra.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 26, 'E, chegando, apresentaram-se a Moisés e a Arão, e a toda a congregação dos filhos de Israel, no deserto de Parã, em Cades; e deram-lhes notícias, a eles e a toda a congregação, e mostraram-lhes o fruto da terra.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 27, 'E, dando conta a Moisés, disseram: Fomos à terra a que nos enviaste. Ela, em verdade, mana leite e mel; e este é o seu fruto.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 28, 'Contudo o povo que habita nessa terra é poderoso, e as cidades são fortificadas e mui grandes. Vimos também ali os filhos de Anaque.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 29, 'Os amalequitas habitam na terra do Negebe; os heteus, os jebuseus e os amorreus habitam nas montanhas; e os cananeus habitam junto do mar, e ao longo do rio Jordão.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 30, 'Então Calebe, fazendo calar o povo perante Moisés, disse: Subamos animosamente, e apoderemo-nos dela; porque bem poderemos prevalecer contra ela.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 31, 'Disseram, porém, os homens que subiram com ele: Não poderemos subir contra aquele povo, porque é mais forte do que nos.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 32, 'Assim, perante os filhos de Israel infamaram a terra que haviam espiado, dizendo: A terra, pela qual passamos para espiá-la, é terra que devora os seus habitantes; e todo o povo que vimos nela são homens de grande estatura.', 1, CURRENT_TIMESTAMP, false),
(4, 13, 33, 'Também vimos ali os nefilins, isto é, os filhos de Anaque, que são descendentes dos nefilins; éramos aos nossos olhos como gafanhotos; e assim também éramos aos seus olhos.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 1, 'Então toda a congregação levantou a voz e gritou; e o povo chorou naquela noite.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 2, 'E todos os filhos de Israel murmuraram contra Moisés e Arão; e toda a congregação lhes disse: Antes tivéssemos morrido na terra do Egito, ou tivéssemos morrido neste deserto!', 1, CURRENT_TIMESTAMP, false),
(4, 14, 3, 'Por que nos traz o Senhor a esta terra para cairmos à espada? Nossas mulheres e nossos pequeninos serão por presa. Não nos seria melhor voltarmos para o Egito?', 1, CURRENT_TIMESTAMP, false),
(4, 14, 4, 'E diziam uns aos outros: Constituamos um por chefe o voltemos para o Egito.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 5, 'Então Moisés e Arão caíram com os rostos por terra perante toda a assembléia da congregação dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 6, 'E Josué, filho de Num, e Calebe, filho de Jefoné, que eram dos que espiaram a terra, rasgaram as suas vestes;', 1, CURRENT_TIMESTAMP, false),
(4, 14, 7, 'e falaram a toda a congregação dos filhos de Israel, dizendo: A terra, pela qual passamos para a espiar, é terra muitíssimo boa.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 8, 'Se o Senhor se agradar de nós, então nos introduzirá nesta terra e no-la dará; terra que mana leite e mel.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 9, 'Tão somente não sejais rebeldes contra o Senhor, e não temais o povo desta terra, porquanto são eles nosso pão. Retirou-se deles a sua defesa, e o Senhor está conosco; não os temais.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 10, 'Mas toda a congregação disse que fossem apedrejados. Nisso a glória do Senhor apareceu na tenda da revelação a todos os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 11, 'Disse então o Senhor a Moisés: Até quando me desprezará este povo e até quando não crerá em mim, apesar de todos os sinais que tenho feito no meio dele?', 1, CURRENT_TIMESTAMP, false),
(4, 14, 12, 'Com pestilência o ferirei, e o rejeitarei; e farei de ti uma nação maior e mais forte do que ele.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 13, 'Respondeu Moisés ao Senhor: Assim os egípcios o ouvirão, eles, do meio dos quais, com a tua força, fizeste subir este povo,', 1, CURRENT_TIMESTAMP, false),
(4, 14, 14, 'e o dirão aos habitantes desta terra. Eles ouviram que tu, ó Senhor, estás no meio deste povo; pois tu, ó Senhor, és visto face a face, e a tua nuvem permanece sobre eles, e tu vais adiante deles numa coluna de nuvem de dia, e numa coluna de fogo de noite.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 15, 'E se matares este povo como a um só homem, então as nações que têm ouvido da tua fama, dirão:', 1, CURRENT_TIMESTAMP, false),
(4, 14, 16, 'Porquanto o Senhor não podia introduzir este povo na terra que com juramento lhe prometera, por isso os matou no deserto.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 17, 'Agora, pois, rogo-te que o poder do meu Senhor se engrandeça, segundo tens dito:', 1, CURRENT_TIMESTAMP, false),
(4, 14, 18, 'O Senhor é tardio em irar-se, e grande em misericórdia; perdoa a iniqüidade e a transgressão; ao culpado não tem por inocente, mas visita a iniqüidade dos pais nos filhos até a terceira e a quarta geração.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 19, 'Perdoa, rogo-te, a iniqüidade deste povo, segundo a tua grande misericórdia, como o tens perdoado desde o Egito até, aqui.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 20, 'Disse-lhe o Senhor: Conforme a tua palavra lhe perdoei;', 1, CURRENT_TIMESTAMP, false),
(4, 14, 21, 'tão certo, porém, como eu vivo, e como a glória do Senhor encherá toda a terra,', 1, CURRENT_TIMESTAMP, false),
(4, 14, 22, 'nenhum de todos os homens que viram a minha glória e os sinais que fiz no Egito e no deserto, e todavia me tentaram estas dez vezes, não obedecendo à minha voz,', 1, CURRENT_TIMESTAMP, false),
(4, 14, 23, 'nenhum deles verá a terra que com juramento prometi o seus pais; nenhum daqueles que me desprezaram a verá.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 24, 'Mas o meu servo Calebe, porque nele houve outro espírito, e porque perseverou em seguir-me, eu o introduzirei na terra em que entrou, e a sua posteridade a possuirá.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 25, 'Ora, os amalequitas e os cananeus habitam no vale; tornai-vos amanhã, e caminhai para o deserto em direção ao Mar Vermelho.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 26, 'Depois disse o Senhor a Moisés e Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 14, 27, 'Até quando sofrerei esta má congregação, que murmura contra mim? tenho ouvido as murmurações dos filhos de Israel, que eles fazem contra mim.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 28, 'Dize-lhes: Pela minha vida, diz o Senhor, certamente conforme o que vos ouvi falar, assim vos hei de fazer:', 1, CURRENT_TIMESTAMP, false),
(4, 14, 29, 'neste deserto cairão os vossos cadáveres; nenhum de todos vós que fostes contados, segundo toda a vossa conta, de vinte anos para cima, que contra mim murmurastes,', 1, CURRENT_TIMESTAMP, false),
(4, 14, 30, 'certamente nenhum de vós entrará na terra a respeito da qual jurei que vos faria habitar nela, salvo Calebe, filho de Jefoné, e Josué, filho de Num.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 31, 'Mas aos vossos pequeninos, dos quais dissestes que seriam por presa, a estes introduzirei na terra, e eles conhecerão a terra que vós rejeitastes.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 32, 'Quanto a vós, porém, os vossos cadáveres cairão neste deserto;', 1, CURRENT_TIMESTAMP, false),
(4, 14, 33, 'e vossos filhos serão pastores no deserto quarenta anos, e levarão sobre si as vossas infidelidades, até que os vossos cadáveres se consumam neste deserto.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 34, 'Segundo o número dos dias em que espiastes a terra, a saber, quarenta dias, levareis sobre vós as vossas iniqüidades por quarenta anos, um ano por um dia, e conhecereis a minha oposição.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 35, 'Eu, o Senhor, tenho falado; certamente assim o farei a toda esta má congregação, aos que se sublevaram contra mim; neste deserto se consumirão, e aqui morrerão.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 36, 'Ora, quanto aos homens que Moisés mandara a espiar a terra e que, voltando, fizeram murmurar toda a congregação contra ele, infamando a terra,', 1, CURRENT_TIMESTAMP, false),
(4, 14, 37, 'aqueles mesmos homens que infamaram a terra morreram de praga perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 38, 'Mas Josué, filho de Num, e Calebe, filho de Jefoné, que eram dos homens que foram espiar a terra, ficaram com vida.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 39, 'Então Moisés falou estas palavras a todos os filhos de Israel, pelo que o povo se entristeceu muito.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 40, 'Eles, pois, levantando-se de manhã cedo, subiram ao cume do monte, e disseram: Eis-nos aqui; subiremos ao lugar que o Senhor tem dito; porquanto havemos pecado.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 41, 'Respondeu Moisés: Ora, por que transgredis o mandado do Senhor, visto que isso não prosperará?', 1, CURRENT_TIMESTAMP, false),
(4, 14, 42, 'Não subais, pois o Senhor não está no meio de vós; para que não sejais feridos diante dos vossos inimigos.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 43, 'Porque os amalequitas e os cananeus estão ali diante da vossa face, e caireis à espada; pois, porquanto vos desviastes do Senhor, o Senhor não estará convosco.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 44, 'Contudo, temerariamente subiram eles ao cume do monte; mas a arca do pacto do Senhor, e Moisés, não se apartaram do arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 14, 45, 'Então desceram os amalequitas e os cananeus, que habitavam na montanha, e os feriram, derrotando-os até Horma.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 1, 'Depois disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 15, 2, 'Fala aos filhos de Israel e díze-lhes: Quando entrardes na terra da vossa habitação, que eu vos hei de dar,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 3, 'e ao Senhor fizerdes, do gado eu do rebanho, oferta queimada, holocausto ou sacrifício, para cumprir um voto, ou como oferta voluntária, para fazer nas vossos festas fixas um cheiro suave ao Senhor,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 4, 'Então aquele que fizer a sua oferta, fará ao Senhor uma oferta de cereais de um décimo de efa de flor de farinha, misturada com a quarta parte de um him de azeite;', 1, CURRENT_TIMESTAMP, false),
(4, 15, 5, 'e de vinho para a oferta de libação prepararás a quarta parte de um him para o holocausto, ou para o sacrifício, para cada cordeiro;', 1, CURRENT_TIMESTAMP, false),
(4, 15, 6, 'e para cada carneiro prepararás como oferta de cereais, dois décimos de efa de flor de farinha, misturada com a terça parte de um him de azeite;', 1, CURRENT_TIMESTAMP, false),
(4, 15, 7, 'e de vinho para a oferta de libação oferecerás a terça parte de um him em cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 8, 'Também, quando preparares novilho para holocausto ou sacrifício, para cumprir um voto, ou um sacrifício de ofertas pacíficas ao Senhor,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 9, 'com o novilho oferecerás uma oferta de cereais de três décimos de efa, de flor de farinha, misturada com a metade de um him de azeite;', 1, CURRENT_TIMESTAMP, false),
(4, 15, 10, 'e de vinho para a oferta de libação oferecerás a metade de um him como oferta queimada em cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 11, 'Assim se fará com cada novilho, ou carneiro, ou com cada um dos cordeiros ou dos cabritos.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 12, 'Segundo o número que oferecerdes, assim fareis com cada um deles.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 13, 'Todo natural assim fará estas coisas, ao oferecer oferta queimada em cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 14, 'Também se peregrinar convosco algum estrangeiro, ou quem quer que estiver entre vos nas vossas gerações, e ele oferecer uma oferta queimada de cheiro suave ao Senhor, como vós fizerdes, assim fará ele.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 15, 'Quanto à assembléia, haverá um mesmo estatuto para vós e para o estrangeiro que peregrinar convosco, estatuto perpétuo nas vossas gerações; como vós, assim será o peregrino perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 16, 'Uma mesma lei e uma mesma ordenança haverá para vós e para o estrangeiro que peregrinar convosco.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 17, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 15, 18, 'Fala aos filhos de Israel, e dize-lhes: Depois de terdes entrado na terra em que vos hei de introduzir,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 19, 'será que, ao comerdes do pão da terra, oferecereis ao Senhor uma oferta alçada.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 20, 'Das primícias da vossa massa oferecereis um bolo em oferta alçada; como a oferta alçada da eira, assim o oferecereis.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 21, 'Das primícias das vossas massas dareis ao Senhor oferta alçada durante as vossas gerações.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 22, 'Igualmente, quando vierdes a errar, e não observardes todos esses mandamentos, que o Senhor tem falado a Moisés,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 23, 'sim, tudo quanto o Senhor vos tem ordenado por intermédio do Moisés, desde o dia em que o Senhor começou a dar os seus mandamentos, e daí em diante pelas vossas gerações,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 24, 'será que, quando se fizer alguma coisa sem querer, e isso for encoberto aos olhos da congregação, toda a congregação oferecerá um novilho para holocausto em cheiro suave ao Senhor, juntamente com a oferta de cereais do mesmo e a sua oferta de libação, segundo a ordenança, e um bode como sacrifício pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 25, 'E o sacerdote fará expiação por toda a congregação dos filhos de Israel, e eles serão perdoados; porquanto foi erro, e trouxeram a sua oferta, oferta queimada ao Senhor, e o seu sacrifício pelo pecado perante o Senhor, por causa do seu erro.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 26, 'Será, pois, perdoada toda a congregação dos filhos de Israel, bem como o estrangeiro que peregrinar entre eles; porquanto sem querer errou o povo todo.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 27, 'E, se uma só pessoa pecar sem querer, oferecerá uma cabra de um ano como sacrifício pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 28, 'E o sacerdote fará perante o Senhor expiação pela alma que peca, quando pecar sem querer; e, feita a expiação por ela, será perdoada.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 29, 'Haverá uma mesma lei para aquele que pecar sem querer, tanto para o natural entre os filhos de Israel, como para o estrangeiro que peregrinar entre eles.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 30, 'Mas a pessoa que fizer alguma coisa temerariamente, quer seja natural, quer estrangeira, blasfema ao Senhor; tal pessoa será extirpada do meio do seu povo,', 1, CURRENT_TIMESTAMP, false),
(4, 15, 31, 'por haver desprezado a palavra do Senhor, e quebrado o seu mandamento; essa alma certamente será extirpada, e sobre ela recairá a sua iniqüidade.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 32, 'Estando, pois, os filhos de Israel no deserto, acharam um homem apanhando lenha no dia de sábado.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 33, 'E os que o acharam apanhando lenha trouxeram-no a Moisés e a Arão, e a toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 34, 'E o meteram em prisão, porquanto ainda não estava declarado o que se lhe devia fazer.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 35, 'Então disse o Senhor a Moisés: certamente será morto o homem; toda a congregação o apedrejará fora do arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 36, 'Levaram-no, pois, para fora do arraial, e o apedrejaram, de modo que ele morreu; como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 37, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 15, 38, 'Fala aos filhos de Israel, e dize-lhes que façam para si franjas nas bordas das suas vestes, pelas suas gerações; e que ponham nas franjas das bordas um cordão azul.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 39, 'Tê-lo-eis nas franjas, para que o vejais, e vos lembreis de todos os mandamentos do Senhor, e os observeis; e para que não vos deixeis arrastar à infidelidade pelo vosso coração ou pela vossa vista, como antes o fazíeis;', 1, CURRENT_TIMESTAMP, false),
(4, 15, 40, 'para que vos lembreis de todos os meus mandamentos, e os observeis, e sejais santos para com o vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(4, 15, 41, 'Eu sou o senhor vosso Deus, que vos tirei da terra do Egito para ser o vosso Deus. Eu sou o Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 1, 'Ora, Corá, filho de Izar, filho de Coate, filho de Levi, juntamente com Datã e Abirão, filhos de Eliabe, e Om, filho de Pelete, filhos de Rúben, tomando certos homens,', 1, CURRENT_TIMESTAMP, false),
(4, 16, 2, 'levantaram-se perante Moisés, juntamente com duzentos e cinqüenta homens dos filhos de Israel, príncipes da congregação, chamados à assembléia, varões de renome;', 1, CURRENT_TIMESTAMP, false),
(4, 16, 3, 'e ajuntando-se contra Moisés e contra Arão, disseram-lhes: Demais é o que vos arrogais a vós, visto que toda a congregação e santa, todos eles são santos, e o Senhor está no meio deles; por que, pois, vos elevais sobre a assembléia do Senhor?', 1, CURRENT_TIMESTAMP, false),
(4, 16, 4, 'Quando Moisés ouviu isso, caiu com o rosto em terra;', 1, CURRENT_TIMESTAMP, false),
(4, 16, 5, 'depois falou a Corá e a toda a sua companhia, dizendo: Amanhã pela manhã o Senhor fará saber quem é seu, e quem é o santo, ao qual ele fará chegar a si; e aquele a quem escolher fará chegar a si.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 6, 'Fazei isto: Corá e toda a sua companhia, tomai para vós incensários;', 1, CURRENT_TIMESTAMP, false),
(4, 16, 7, 'e amanhã, pondo fogo neles, sobre eles deitai incenso perante o Senhor; e será que o homem a quem o Senhor escolher, esse será o santo; demais é o que vos arrogais a vós, filhos de Levi.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 8, 'Disse mais Moisés a Corá: Ouvi agora, filhos de Levi!', 1, CURRENT_TIMESTAMP, false),
(4, 16, 9, 'Acaso é pouco para vós que o Deus de Israel vos tenha separado da congregação de Israel, para vos fazer chegar a si, a fim de fazerdes o serviço do tabernáculo do Senhor e estardes perante a congregação para ministrar-lhe,', 1, CURRENT_TIMESTAMP, false),
(4, 16, 10, 'e te fez chegar, e contigo todos os teus irmãos, os filhos de Levi? procurais também o sacerdócio?', 1, CURRENT_TIMESTAMP, false),
(4, 16, 11, 'Pelo que tu e toda a tua companhia estais congregados contra o Senhor; e Arão, quem é ele, para que murmureis contra ele?', 1, CURRENT_TIMESTAMP, false),
(4, 16, 12, 'Então Moisés mandou chamar a Datã e a Abirão, filhos de Eliabe; eles porém responderam: Não subiremos.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 13, 'É pouco, porventura, que nos tenhas feito subir de uma terra que mana leite e mel, para nos matares no deserto, para que queiras ainda fazer-te príncipe sobre nós?', 1, CURRENT_TIMESTAMP, false),
(4, 16, 14, 'Ademais, não nos introduziste em uma terra que mana leite e mel, nem nos deste campos e vinhas em herança; porventura cegarás os olhos a estes homens? Não subiremos.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 15, 'Então Moisés irou-se grandemente, e disse ao Senhor: Não atentes para a sua oferta; nem um só jumento tenho tomado deles, nem a nenhum deles tenho feito mal.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 16, 'Disse mais Moisés a Corá: Comparecei amanhã tu e toda a tua companhia perante o Senhor; tu e eles, e Arão.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 17, 'Tome cada um o seu incensário, e ponha nele incenso; cada um traga perante o Senhor o seu incensário, duzentos e cinqüenta incensários; também tu e Arão, cada qual o seu incensário.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 18, 'Tomou, pois, cada qual o seu incensário, e nele pôs fogo, e nele deitou incenso; e se puseram à porta da tenda da revelação com Moisés e Arão.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 19, 'E Corá fez ajuntar contra eles toda o congregação à porta da tenda da revelação; então a glória do Senhor apareceu a toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 20, 'Então disse o senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 16, 21, 'Apartai-vos do meio desta congregação, para que eu, num momento, os possa consumir.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 22, 'Mas eles caíram com os rostos em terra, e disseram: ó Deus, Deus dos espíritos de toda a carne, pecará um só homem, e indignar-te-ás tu contra toda esta congregação?', 1, CURRENT_TIMESTAMP, false),
(4, 16, 23, 'Respondeu o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 16, 24, 'Fala a toda esta congregação, dizendo: Subi do derredor da habitação de Corá, Datã e Abirão.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 25, 'Então Moisés levantou-se, e foi ter com Datã e Abirão; e seguiram-nos os anciãos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 26, 'E falou à congregação, dizendo: Retirai-vos, peço-vos, das tendas desses homens ímpios, e não toqueis nada do que é seu, para que não pereçais em todos os seus pecados.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 27, 'Subiram, pois, do derredor da habitação de Corá, Datã e Abirão. E Datã e Abirão saíram, e se puseram à porta das suas tendas, juntamente com suas mulheres, e seus filhos e seus pequeninos.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 28, 'Então disse Moisés: Nisto conhecereis que o Senhor me enviou a fazer todas estas obras; pois não as tenho feito de mim mesmo.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 29, 'Se estes morrerem como morrem todos os homens, e se forem visitados como são visitados todos os homens, o Senhor não me enviou.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 30, 'Mas, se o Senhor criar alguma coisa nova, e a terra abrir a boca e os tragar com tudo o que é deles, e vivos descerem ao Seol, então compreendereis que estes homens têm desprezado o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 31, 'E aconteceu que, acabando ele de falar todas estas palavras, a terra que estava debaixo deles se fendeu;', 1, CURRENT_TIMESTAMP, false),
(4, 16, 32, 'e a terra abriu a boca e os tragou com as suas famílias, como também a todos os homens que pertenciam a Corá, e a toda a sua fazenda.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 33, 'Assim eles e tudo o que era seu desceram vivos ao Seol; e a terra os cobriu, e pereceram do meio da congregação,', 1, CURRENT_TIMESTAMP, false),
(4, 16, 34, 'E todo o Israel, que estava ao seu redor, fugiu ao clamor deles, dizendo: não suceda que a terra nos trague também a nós.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 35, 'Então saiu fogo do Senhor, e consumiu os duzentos e cinqüenta homens que ofereciam o incenso.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 36, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 16, 37, 'Dize a Eleazar, filho de Arão, o sacerdote, que tire os incensários do meio do incêndio; e espalha tu o fogo longe; porque se tornaram santos', 1, CURRENT_TIMESTAMP, false),
(4, 16, 38, 'os incensários daqueles que pecaram contra as suas almas; deles se façam chapas, de obra batida, para cobertura do altar; porquanto os trouxeram perante o Senhor, por isso se tornaram santos; e serão por sinal aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 39, 'Eleazar, pois, o sacerdote, tomou os incensários de bronze, os quais aqueles que foram queimados tinham oferecido; e os converteram em chapas para cobertura do altar,', 1, CURRENT_TIMESTAMP, false),
(4, 16, 40, 'para servir de memória aos filhos de Israel, a fim de que nenhum estranho, ninguém que não seja da descendência de Arão, se chegue para queimar incenso perante o Senhor, para que não seja como Corá e a sua companhia; conforme o Senhor dissera a Eleazar por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 41, 'Mas no dia seguinte toda a congregação dos filhos de Israel murmurou contra Moisés e Arão, dizendo: Vós matastes o povo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 42, 'E tendo-se sublevado a congregação contra Moisés e Arão, dirigiu-se para a tenda da revelação, e eis que a nuvem a cobriu, e a glória do Senhor apareceu.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 43, 'Vieram, pois, Moisés e Arão à frente da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 44, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 16, 45, 'Levantai-vos do meio desta congregação, para que eu, num momento, a possa consumir. Então caíram com o rosto em terra.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 46, 'Depois disse Moisés a Arão: Toma o teu incensário, põe nele fogo do altar, deita incenso sobre ele e leva-o depressa à congregação, e faze expiação por eles; porque grande indignação saiu do Senhor; já começou a praga.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 47, 'Tomou-o Arão, como Moisés tinha falado, e correu ao meio da congregação; e eis que já a praga havia começado entre o povo; e deitando o incenso no incensário, fez expiação pelo povo.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 48, 'E pôs-se em pé entre os mortos e os vivos, e a praga cessou.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 49, 'Ora, os que morreram da praga foram catorze mil e setecentos, além dos que morreram no caso de Corá.', 1, CURRENT_TIMESTAMP, false),
(4, 16, 50, 'E voltou Arão a Moisés à porta da tenda da revelação, pois cessara a praga.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 1, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 17, 2, 'Fala aos filhos de Israel, e toma deles uma vara para cada casa paterna de todos os seus príncipes, segundo as casas de seus pais, doze varas; e escreve o nome de cada um sobre a sua vara.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 3, 'O nome de Arão escreverás sobre a vara de Levi; porque cada cabeça das casas de seus pais terá uma vara.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 4, 'E as porás na tenda da revelação, perante o testemunho, onde venho a vós.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 5, 'Então brotará a vara do homem que eu escolher; assim farei cessar as murmurações dos filhos de Israel contra mim, com que murmuram contra vós.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 6, 'Falou, pois, Moisés aos filhos de Israel, e todos os seus príncipes deram-lhe varas, cada príncipe uma, segundo as casas de seus pais, doze varas; e entre elas estava a vara de Arão.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 7, 'E Moisés depositou as varas perante o Senhor na tenda do testemunho.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 8, 'Sucedeu, pois, no dia seguinte, que Moisés entrou na tenda do testemunho, e eis que a vara de Arão, pela casa de Levi, brotara, produzira gomos, rebentara em flores e dera amêndoas maduras.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 9, 'Então Moisés trouxe todas as varas de diante do Senhor a todos os filhos de Israel; e eles olharam, e tomaram cada um a sua vara.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 10, 'Então o Senhor disse a Moisés: Torna a pôr a vara de Arão perante o testemunho, para se guardar por sinal contra os filhos rebeldes; para que possas fazer acabar as suas murmurações contra mim, a fim de que não morram.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 11, 'Assim fez Moisés; como lhe ordenara o Senhor, assim fez.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 12, 'Então disseram os filhos de Israel a Moisés: Eis aqui, nós expiramos, perecemos, todos nós perecemos.', 1, CURRENT_TIMESTAMP, false),
(4, 17, 13, 'Todo aquele que se aproximar, sim, todo o que se aproximar do tabernáculo do Senhor, morrerá; porventura pereceremos todos?', 1, CURRENT_TIMESTAMP, false),
(4, 18, 1, 'Depois disse o Senhor a Arão: Tu e teus filhos, e a casa de teu pai contigo, levareis a iniqüidade do santuário; e tu e teus filhos contigo levareis a iniqüidade do vosso sacerdócio.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 2, 'Faze, pois, chegar contigo também teus irmãos, a tribo de Levi, a tribo de teu pai, para que se ajuntem a ti, e te sirvam; mas tu e teus filhos contigo estareis perante a tenda do testemunho.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 3, 'Eles cumprirão as tuas ordens, e assumirão o encargo de toda a tenda; mas não se chegarão aos utensílios do santuário, nem ao altar, para que não morram, assim eles, como vós.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 4, 'Mas se ajuntarão a ti, e assumirão o encargo da tenda da revelação, para todo o serviço da tenda; e o estranho não se chegará a vós.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 5, 'Vós, pois, assumireis o encargo do santuário e o encargo do altar, para que não haja outra vez furor sobre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 6, 'Eis que eu tenho tomado vossos irmãos, os levitas, do meio dos filhos de Israel; eles vos são uma dádiva, feita ao Senhor, para fazerem o serviço da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 7, 'Mas tu e teus filhos contigo cumprireis o vosso sacerdócio no tocante a tudo o que é do altar, e a tudo o que está dentro do véu; nisso servireis. Eu vos dou o sacerdócio como dádiva ministerial, e o estranho que se chegar será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 8, 'Disse mais o Senhor a Arão: Eis que eu te tenho dado as minhas ofertas alçadas, com todas as coisas santificadas dos filhos de Israel; a ti as tenho dado como porção, e a teus filhos como direito perpétuo.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 9, 'Das coisas santíssimas reservadas do fogo serão tuas todas as suas ofertas, a saber, todas as ofertas de cereais, todas as ofertas pelo pecado e todas as ofertas pela culpa, que me entregarem; estas coisas serão santíssimas para ti e para teus filhos.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 10, 'Num lugar santo as comerás; delas todo varão comerá; santas te serão.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 11, 'Também isto será teu: a oferta alçada das suas dádivas, com todas as ofertas de movimento dos filhos de Israel; a ti, a teus filhos, e a tuas filhas contigo, as tenho dado como porção, para sempre. Todo o que na tua casa estiver limpo, comerá delas.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 12, 'Tudo o que do azeite há de melhor, e tudo o que do mosto e do grão há de melhor, as primícias destes que eles derem ao Senhor, a ti as tenho dado.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 13, 'Os primeiros frutos de tudo o que houver na sua terra, que trouxerem ao Senhor, serão teus. Todo o que na tua casa estiver limpo comerá deles.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 14, 'Toda coisa consagrada em Israel será tua.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 15, 'Todo primogênito de toda a carne, que oferecerem ao Senhor, tanto de homens como de animais, será teu; contudo os primogênitos dos homens certamente remirás; também os primogênitos dos animais imundos remirás.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 16, 'Os que deles se houverem de remir, desde a idade de um mês os remirás, segundo a tua avaliação, por cinco siclos de dinheiro, segundo o siclo do santuário, que é de vinte jeiras.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 17, 'Mas o primogênito da vaca, o primogênito da ovelha, e o primogênito da cabra não remirás, porque eles são santos. Espargirás o seu sangue sobre o altar, e queimarás a sua gordura em oferta queimada, de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 18, 'E a carne deles será tua, bem como serão teus o peito da oferta de movimento e a coxa direita.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 19, 'Todas as ofertas alçadas das coisas sagradas, que os filhos de Israel oferecerem ao Senhor, eu as tenho dado a ti, a teus filhos e a tuas filhas contigo, como porção, para sempre; é um pacto perpétuo de sal perante o Senhor, para ti e para a tua descendência contigo.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 20, 'Disse também o Senhor a Arão: Na sua terra herança nenhuma terás, e no meio deles nenhuma porção terás; eu sou a tua porção e a tua herança entre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 21, 'Eis que aos filhos de Levi tenho dado todos os dízimos em Israel por herança, pelo serviço que prestam, o serviço da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 22, 'Ora, nunca mais os filhos de Israel se chegarão à tenda da revelação, para que não levem sobre si o pecado e morram.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 23, 'Mas os levitas farão o serviço da tenda da revelação, e eles levarão sobre si a sua iniqüidade; pelas vossas gerações estatuto perpétuo será; e no meio dos filhos de Israel nenhuma herança terão.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 24, 'Porque os dízimos que os filhos de Israel oferecerem ao Senhor em oferta alçada, eu os tenho dado por herança aos levitas; porquanto eu lhes disse que nenhuma herança teriam entre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 25, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 18, 26, 'Também falarás aos levitas, e lhes dirás: Quando dos filhos de Israel receberdes os dízimos, que deles vos tenho dado por herança, então desses dízimos fareis ao Senhor uma oferta alçada, o dízimo dos dízimos.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 27, 'E computar-se-á a vossa oferta alçada, como o grão da eira, e como a plenitude do lagar.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 28, 'Assim fareis ao Senhor uma oferta alçada de todos os vossos dízimos, que receberdes dos filhos de Israel; e desses dízimos dareis a oferta alçada do Senhor a Arão, o sacerdote.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 29, 'De todas as dádivas que vos forem feitas, oferecereis, do melhor delas, toda a oferta alçada do Senhor, a sua santa parte.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 30, 'Portanto lhes dirás: Quando fizerdes oferta alçada do melhor dos dízimos, será ela computada aos levitas, como a novidade da eira e como a novidade do lagar.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 31, 'E o comereis em qualquer lugar, vós e as vossas famílias; porque é a vossa recompensa pelo vosso serviço na tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 18, 32, 'Pelo que não levareis sobre vós pecado, se tiverdes alçado o que deles há de melhor; e não profanareis as coisas sagradas dos filhos de Israel, para que não morrais.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 1, 'Disse mais o Senhor a Moisés e a Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 19, 2, 'Este é o estatuto da lei que o Senhor ordenou, dizendo: Dize aos filhos de Israel que te tragam uma novilha vermelha sem defeito, que não tenha mancha, e sobre a qual não se tenha posto jugo:', 1, CURRENT_TIMESTAMP, false),
(4, 19, 3, 'Entregá-la-eis a Eleazar, o sacerdote; ele a tirará para fora do arraial, e a imolarão diante dele.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 4, 'Eleazar, o sacerdote, tomará do sangue com o dedo, e dele espargirá para a frente da tenda da revelação sete vezes.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 5, 'Então à vista dele se queimará a novilha, tanto o couro e a carne, como o sangue e o excremento;', 1, CURRENT_TIMESTAMP, false),
(4, 19, 6, 'e o sacerdote, tomando pau do cedro, hissopo e carmesim, os lançará no meio do fogo que queima a novilha.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 7, 'Então o sacerdote lavará as suas vestes e banhará o seu corpo em água; depois entrará no arraial; e o sacerdote será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 8, 'Também o que a tiver queimado lavará as suas vestes e banhará o seu corpo em água, e será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 9, 'E um homem limpo recolherá a cinza da novilha, e a depositará fora do arraial, num lugar limpo, e ficará ela guardada para a congregação dos filhos de Israel, para a água de purificação; é oferta pelo pecado.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 10, 'E o que recolher a cinza da novilha lavará as suas vestes e será imundo até a tarde; isto será por estatuto perpétuo aos filhos de Israel e ao estrangeiro que peregrina entre eles.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 11, 'Aquele que tocar o cadáver de algum homem, será imundo sete dias.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 12, 'Ao terceiro dia o mesmo se purificará com aquela água, e ao sétimo dia se tornará limpo; mas, se ao terceiro dia não se purificar, não se tornará limpo ao sétimo dia.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 13, 'Todo aquele que tocar o cadáver de algum homem que tenha morrido, e não se purificar, contamina o tabernáculo do Senhor; e essa alma será extirpada de Israel; porque a água da purificação não foi espargida sobre ele, continua imundo; a sua imundícia está ainda sobre ele.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 14, 'Esta é a lei, quando um homem morrer numa tenda: todo aquele que entrar na tenda, e todo aquele que nela estiver, será imundo sete dias.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 15, 'Também, todo vaso aberto, sobre que não houver pano atado, será imundo.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 16, 'E todo aquele que no campo tocar alguém que tenha sido morto pela espada, ou outro cadáver, ou um osso de algum homem, ou uma sepultura, será imundo sete dias.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 17, 'Para o imundo, pois, tomarão da cinza da queima da oferta pelo pecado, e sobre ela deitarão água viva num vaso;', 1, CURRENT_TIMESTAMP, false),
(4, 19, 18, 'e um homem limpo tomará hissopo, e o molhará na água, e a espargirá sobre a tenda, sobre todos os objetos e sobre as pessoas que ali estiverem, como também sobre aquele que tiver tocado o osso, ou o que foi morto, ou o que faleceu, ou a sepultura.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 19, 'Também o limpo, ao terceiro dia e ao sétimo dia, a espargirá sobre o imundo, e ao sétimo dia o purificará; e o que era imundo lavará as suas vestes, e se banhará em água, e à tarde será limpo.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 20, 'Mas o que estiver imundo e não se purificar, esse será extirpado do meio da assembléia, porquanto contaminou o santuário do Senhor; a água de purificação não foi espargida sobre ele; é imundo.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 21, 'Isto lhes será por estatuto perpétuo: o que espargir a água de purificação lavará as suas vestes; e o que tocar a água de purificação será imundo até a tarde.', 1, CURRENT_TIMESTAMP, false),
(4, 19, 22, 'E tudo quanto o imundo tocar também será imundo; e a pessoa que tocar naquilo será imunda até a tarde.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 1, 'Os filhos de Israel, a congregação toda, chegaram ao deserto de Zim no primeiro mês, e o povo ficou em Cades. Ali morreu Miriã, e ali foi sepultada.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 2, 'Ora, não havia água para a congregação; pelo que se ajuntaram contra Moisés e Arão.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 3, 'E o povo contendeu com Moisés, dizendo: Oxalá tivéssemos perecido quando pereceram nossos irmãos perante o Senhor!', 1, CURRENT_TIMESTAMP, false),
(4, 20, 4, 'Por que trouxestes a congregação do Senhor a este deserto, para que morramos aqui, nós e os nossos animais?', 1, CURRENT_TIMESTAMP, false),
(4, 20, 5, 'E por que nos fizestes subir do Egito, para nos trazer a este mau lugar? lugar onde não há semente, nem figos, nem vides, nem romãs, nem mesmo água para beber.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 6, 'Então Moisés e Arão se foram da presença da assembléia até a porta da tenda da revelação, e se lançaram com o rosto em terra; e a glória do Senhor lhes apareceu.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 7, 'E o Senhor disse a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 20, 8, 'Toma a vara, e ajunta a congregação, tu e Arão, teu irmão, e falai à rocha perante os seus olhos, que ela dê as suas águas. Assim lhes tirarás água da rocha, e darás a beber à congregação e aos seus animais.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 9, 'Moisés, pois, tomou a vara de diante do senhor, como este lhe ordenou.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 10, 'Moisés e Arão reuniram a assembléia diante da rocha, e Moisés disse-lhes: Ouvi agora, rebeldes! Porventura tiraremos água desta rocha para vós?', 1, CURRENT_TIMESTAMP, false),
(4, 20, 11, 'Então Moisés levantou a mão, e feriu a rocha duas vezes com a sua vara, e saiu água copiosamente, e a congregação bebeu, e os seus animais.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 12, 'Pelo que o Senhor disse a Moisés e a Arão: Porquanto não me crestes a mim, para me santificardes diante dos filhos de Israel, por isso não introduzireis esta congregação na terra que lhes dei.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 13, 'Estas são as águas de Meribá, porque ali os filhos de Israel contenderam com o Senhor, que neles se santificou.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 14, 'De Cades, Moisés enviou mensageiros ao rei de Edom, dizendo: Assim diz teu irmão Israel: Tu sabes todo o trabalho que nos tem sobrevindo;', 1, CURRENT_TIMESTAMP, false),
(4, 20, 15, 'como nossos pais desceram ao Egito, e nós no Egito habitamos muito tempo; e como os egípcios nos maltrataram, a nós e a nossos pais;', 1, CURRENT_TIMESTAMP, false),
(4, 20, 16, 'e quando clamamos ao Senhor, ele ouviu a nossa voz, e mandou um anjo, e nos tirou do Egito; e eis que estamos em Cades, cidade na extremidade dos teus termos.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 17, 'Deixa-nos, pois, passar pela tua terra; não passaremos pelos campos, nem pelas vinhas, nem beberemos a água dos poços; iremos pela estrada real, não nos desviando para a direita nem para a esquerda, até que tenhamos passado os teus termos.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 18, 'Respondeu-lhe Edom: Não passaras por mim, para que eu não saia com a espada ao teu encontro.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 19, 'Os filhos de Israel lhe replicaram: Subiremos pela estrada real; e se bebermos das tuas águas, eu e o meu gado, darei o preço delas; sob condição de eu nada mais fazer, deixa-me somente passar a pé.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 20, 'Edom, porém, respondeu: Não passarás. E saiu-lhe ao encontro com muita gente e com mão forte.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 21, 'Assim recusou Edom deixar Israel passar pelos seus termos; pelo que Israel se desviou dele.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 22, 'Então partiram de Cades; e os filhos de Israel, a congregação toda, chegaram ao monte Hor.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 23, 'E falou o Senhor a Moisés e a Arão no monte Hor, nos termos da terra de Edom, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 20, 24, 'Arão será recolhido a seu povo, porque não entrará na terra que dei aos filhos de Israel, porquanto fostes rebeldes contra a minha palavra no tocante às águas de Meribá.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 25, 'Toma a Arão e a Eleazar, seu filho, e faze-os subir ao monte Hor;', 1, CURRENT_TIMESTAMP, false),
(4, 20, 26, 'e despe a Arão as suas vestes, e as veste a Eleazar, seu filho, porque Arão será recolhido, e morrerá ali.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 27, 'Fez, pois, Moisés como o Senhor lhe ordenara; e subiram ao monte Hor perante os olhos de toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 28, 'Moisés despiu a Arão as vestes, e as vestiu a Eleazar, seu filho; e morreu Arão ali sobre o cume do monte; e Moisés e Eleazar desceram do monte.', 1, CURRENT_TIMESTAMP, false),
(4, 20, 29, 'Vendo, pois, toda a congregação que Arão era morto, chorou-o toda a casa de Israel por trinta dias.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 1, 'Ora, ouvindo o cananeu, rei de Arade, que habitava no Negebe, que Israel vinha pelo caminho de Atarim, pelejou contra Israel, e levou dele alguns prisioneiros.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 2, 'Então Israel fez um voto ao Senhor, dizendo: Se na verdade entregares este povo nas minhas mãos, destruirei totalmente as suas cidades.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 3, 'O Senhor, pois, ouviu a voz de Israel, e entregou-lhe os cananeus; e os israelitas os destruíram totalmente, a eles e às suas cidades; e chamou-se aquele lugar Horma.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 4, 'Então partiram do monte Hor, pelo caminho que vai ao Mar Vermelho, para rodearem a terra de Edom; e a alma do povo impacientou-se por causa do caminho.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 5, 'E o povo falou contra Deus e contra Moisés: Por que nos fizestes subir do Egito, para morrermos no deserto? pois aqui não há pão e não há água: e a nossa alma tem fastio deste miserável pão.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 6, 'Então o Senhor mandou entre o povo serpentes abrasadoras, que o mordiam; e morreu muita gente em Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 7, 'Pelo que o povo veio a Moisés, e disse: Pecamos, porquanto temos falado contra o Senhor e contra ti; ora ao Senhor para que tire de nós estas serpentes. Moisés, pois, orou pelo povo.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 8, 'Então disse o Senhor a Moisés: Faze uma serpente de bronze, e põe-na sobre uma haste; e será que todo mordido que olhar para ela viverá.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 9, 'Fez, pois, Moisés uma serpente de bronze, e pô-la sobre uma haste; e sucedia que, tendo uma serpente mordido a alguém, quando esse olhava para a serpente de bronze, vivia.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 10, 'Partiram, então, os filhos de Israel, e acamparam-se em Obote.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 11, 'Depois partiram de Obote, e acamparam-se em Ije-Abarim, no deserto que está defronte de Moabe, para o nascente.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 12, 'Dali partiram, e acamparam-se no vale de Zerede.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 13, 'E, partindo dali, acamparam-se além do Arnom, que está no deserto e sai dos termos dos amorreus; porque o Arnom é o termo de Moabe, entre Moabe e os amorreus.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 14, 'Pelo que se diz no livro das guerras do Senhor: Vaebe em Sufa, e os vales do Arnom,', 1, CURRENT_TIMESTAMP, false),
(4, 21, 15, 'e o declive dos vales, que se inclina para a situação Ar, e se encosta aos termos de Moabe', 1, CURRENT_TIMESTAMP, false),
(4, 21, 16, 'Dali vieram a Beer; esse é o poço do qual o Senhor disse a Moisés: Ajunta o povo, e lhe darei água.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 17, 'Então Israel cantou este cântico: Brota, ó poço! E vós, entoai-lhe cânticos!', 1, CURRENT_TIMESTAMP, false),
(4, 21, 18, 'Ao poço que os príncipes cavaram, que os nobres do povo escavaram com o bastão, e com os seus bordões. Do deserto vieram a Matana;', 1, CURRENT_TIMESTAMP, false),
(4, 21, 19, 'de Matana a Naaliel; de Naaliel a Bamote;', 1, CURRENT_TIMESTAMP, false),
(4, 21, 20, 'e de Bamote ao vale que está no campo de Moabe, ao cume de Pisga, que dá para o deserto.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 21, 'Então Israel mandou mensageiros a Siom, rei dos amorreus, a dizer-lhe:', 1, CURRENT_TIMESTAMP, false),
(4, 21, 22, 'Deixa-me passar pela tua terra; não nos desviaremos para os campos nem para as vinhas; as águas dos poços não beberemos; iremos pela estrada real até que tenhamos passado os teus termos.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 23, 'Siom, porém, não deixou Israel passar pelos seus termos; pelo contrário, ajuntou todo o seu povo, saiu ao encontro de Israel no deserto e, vindo a Jaza, pelejou contra ele.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 24, 'Mas Israel o feriu ao fio da espada, e apoderou-se da sua terra, desde o Arnom até o Jaboque, até os amonitas; porquanto a fronteira dos amonitas era fortificada.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 25, 'Assim Israel tomou todas as cidades dos amorreus e habitou nelas, em Hesbom e em todas as suas aldeias.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 26, 'Porque Hesbom era a cidade de Siom, rei dos amorreus, que pelejara contra o precedente rei de Moabe, e tomara da mão dele toda a sua terra até o Arnom.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 27, 'Pelo que dizem os que falam por provérbios: Vinde a Hesbom! edifique-se e estabeleça-se a cidade de Siom!', 1, CURRENT_TIMESTAMP, false),
(4, 21, 28, 'Porque fogo saiu de Hesbom, e uma chama da cidade de Siom; e devorou a Ar de Moabe, aos senhores dos altos do Arnom.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 29, 'Ai de ti, Moabe! perdido estás, povo de Quemós! Entregou seus filhos como fugitivos, e suas filhas como cativas, a Siom, rei dos amorreus.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 30, 'Nós os asseteamos; Hesbom está destruída até Dibom, e os assolamos até Nofá, que se estende até Medeba.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 31, 'Assim habitou Israel na terra dos amorreus.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 32, 'Depois Moisés mandou espiar a Jazer, e tomaram as suas aldeias e expulsaram os amorreus que ali estavam.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 33, 'Então viraram-se, e subiram pelo caminho de Basã. E Ogue, rei de Basã, saiu-lhes ao encontro, ele e todo o seu povo, para lhes dar batalha em Edrei.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 34, 'Disse, pois, o Senhor a Moisés: Não o temas, porque eu to entreguei na mão, a ele, a todo o seu povo, e à sua terra; e far-lhe-ás como fizeste a Siom, rei dos amorreus, que habitava em Hesbom.', 1, CURRENT_TIMESTAMP, false),
(4, 21, 35, 'Assim o feriram, a ele e seus filhos, e a todo o seu povo, até que nenhum lhe ficou restando; também se apoderaram da terra dele.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 1, 'Depois os filhos de Israel partiram, e acamparam-se nas planícies de Moabe, além do Jordão, na altura de Jericó.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 2, 'Ora, Balaque, filho de Zipor, viu tudo o que Israel fizera aos amorreus.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 3, 'E Moabe tinha grande medo do povo, porque era muito; e Moabe andava angustiado por causa dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 4, 'Por isso disse aos anciãos de Midiã: Agora esta multidão lamberá tudo quanto houver ao redor de nós, como o boi lambe a erva do campo. Nesse tempo Balaque, filho de Zipor, era rei de Moabe.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 5, 'Ele enviou mensageiros a Balaão, filho de Beor, a Petor, que está junto ao rio, à terra dos filhos do seu povo, a fim de chamá-lo, dizendo: Eis que saiu do Egito um povo, que cobre a face da terra e estaciona defronte de mim.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 6, 'Vem pois agora, rogo-te, amaldiçoar-me este povo, pois mais poderoso é do que eu; porventura prevalecerei, de modo que o possa ferir e expulsar da terra; porque eu sei que será abençoado aquele a quem tu abençoares, e amaldiçoado aquele a quem tu amaldiçoares.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 7, 'Foram-se, pois, os anciãos de Moabe e os anciãos de Midiã, com o preço dos encantamentos nas mãos e, chegando a Balaão, referiram-lhe as palavras de Balaque.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 8, 'Ele lhes respondeu: Passai aqui esta noite, e vos trarei a resposta, como o Senhor me falar. Então os príncipes de Moabe ficaram com Balaão.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 9, 'Então veio Deus a Balaão, e perguntou: Quem são estes homens que estão contigo?', 1, CURRENT_TIMESTAMP, false),
(4, 22, 10, 'Respondeu Balaão a Deus: Balaque, filho de Zipor, rei de Moabe, mos enviou, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 22, 11, 'Eis que o povo que saiu do Egito cobre a face da terra; vem agora amaldiçoar-mo; porventura poderei pelejar contra ele e expulsá-lo.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 12, 'E Deus disse a Balaão: Não irás com eles; não amaldiçoarás a este povo, porquanto é bendito.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 13, 'Levantando-se Balaão pela manhã, disse aos príncipes de Balaque: Ide para a vossa terra, porque o Senhor recusa deixar-me ir convosco.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 14, 'Levantaram-se, pois, os príncipes de Moabe, vieram a Balaque e disseram: Balaão recusou vir conosco.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 15, 'Balaque, porém, tornou a enviar príncipes, em maior número e mais honrados do que aqueles.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 16, 'Estes vieram a Balaão e lhe disseram: Assim diz Balaque, filho de Zipor: Rogo-te que não te demores em vir a mim,', 1, CURRENT_TIMESTAMP, false),
(4, 22, 17, 'porque grandemente te honrarei, e farei tudo o que me disseres; vem pois, rogo-te, amaldiçoar-me este povo.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 18, 'Respondeu Balaão aos servos de Balaque: Ainda que Balaque me quisesse dar a sua casa cheia de prata e de ouro, eu não poderia ir além da ordem do Senhor meu Deus, para fazer coisa alguma, nem pequena nem grande.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 19, 'Agora, pois, rogo-vos que fiqueis aqui ainda esta noite, para que eu saiba o que o Senhor me dirá mais.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 20, 'Veio, pois, Deus a Balaão, de noite, e disse-lhe: Já que esses homens te vieram chamar, levanta-te, vai com eles; todavia, farás somente aquilo que eu te disser.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 21, 'Então levantou-se Balaão pela manhã, albardou a sua jumenta, e partiu com os príncipes de Moabe.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 22, 'A ira de Deus se acendeu, porque ele ia, e o anjo do Senhor pôs-se-lhe no caminho por adversário. Ora, ele ia montado na sua jumenta, tendo consigo os seus dois servos.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 23, 'A jumenta viu o anjo do Senhor parado no caminho, com a sua espada desembainhada na mão e, desviando-se do caminho, meteu-se pelo campo; pelo que Balaão espancou a jumenta para fazê-la tornar ao caminho.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 24, 'Mas o anjo do Senhor pôs-se numa vereda entre as vinhas, havendo uma sebe de um e de outro lado.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 25, 'Vendo, pois, a jumenta o anjo do Senhor, coseu-se com a sebe, e apertou contra a sebe o pé de Balaão; pelo que ele tornou a espancá-la.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 26, 'Então o anjo do Senhor passou mais adiante, e pôs-se num lugar estreito, onde não havia caminho para se desviar nem para a direita nem para a esquerda.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 27, 'E, vendo a jumenta o anjo do Senhor, deitou-se debaixo de Balaão; e a ira de Balaão se acendeu, e ele espancou a jumenta com o bordão.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 28, 'Nisso abriu o Senhor a boca da jumenta, a qual perguntou a Balaão: Que te fiz eu, para que me espancasses estas três vezes?', 1, CURRENT_TIMESTAMP, false),
(4, 22, 29, 'Respondeu Balaão à jumenta: Porque zombaste de mim; oxalá tivesse eu uma espada na mão, pois agora te mataria.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 30, 'Tornou a jumenta a Balaão: Porventura não sou a tua jumenta, em que cavalgaste toda a tua vida até hoje? Porventura tem sido o meu costume fazer assim para contigo? E ele respondeu: Não.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 31, 'Então o Senhor abriu os olhos a Balaão, e ele viu o anjo do Senhor parado no caminho, e a sua espada desembainhada na mão; pelo que inclinou a cabeça, e prostrou-se com o rosto em terra.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 32, 'Disse-lhe o anjo do senhor: Por que já três vezes espancaste a tua jumenta? Eis que eu te saí como adversário, porquanto o teu caminho é perverso diante de mim;', 1, CURRENT_TIMESTAMP, false),
(4, 22, 33, 'a jumenta, porém, me viu, e já três vezes se desviou de diante de mim; se ela não se tivesse desviado de mim, na verdade que eu te haveria matado, deixando a ela com vida.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 34, 'Respondeu Balaão ao anjo do Senhor: pequei, porque não sabia que estavas parado no caminho para te opores a mim; e agora, se parece mal aos teus olhos, voltarei.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 35, 'Tornou o anjo do Senhor a Balaão: Vai com os homens, somente a palavra que eu te disser é que falarás. Assim Balaão seguiu com os príncipes de Balaque:', 1, CURRENT_TIMESTAMP, false),
(4, 22, 36, 'Tendo, pois, Balaque ouvido que Balaão vinha chegando, saiu-lhe ao encontro até Ir-Moabe, cidade fronteira que está à margem do Arnom.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 37, 'Perguntou Balaque a Balaão: Porventura não te enviei diligentemente mensageiros a chamar-te? por que não vieste a mim? não posso eu, na verdade, honrar-te?', 1, CURRENT_TIMESTAMP, false),
(4, 22, 38, 'Respondeu Balaão a Balaque: Eis que sou vindo a ti; porventura poderei eu agora, de mim mesmo, falar alguma coisa? A palavra que Deus puser na minha boca, essa falarei.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 39, 'E Balaão foi com Balaque, e chegaram a Quiriate-Huzote.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 40, 'Então Balaque ofereceu em sacrifício bois e ovelhas, e deles enviou a Balaão e aos príncipes que estavam com ele.', 1, CURRENT_TIMESTAMP, false),
(4, 22, 41, 'E sucedeu que, pela manhã, Balaque tomou a Balaão, e o levou aos altos de Baal, e viu ele dali a parte extrema do povo.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 1, 'Disse Balaão a Balaque: Edifica-me aqui sete altares e prepara-me aqui sete novilhos e sete carneiros.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 2, 'Fez, pois, Balaque como Balaão dissera; e Balaque e Balaão ofereceram um novilho e um carneiro sobre cada altar.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 3, 'Então Balaão disse a Balaque: Fica aqui em pé junto ao teu holocausto, e eu irei; porventura o Senhor me sairá ao encontro, e o que ele me mostrar, eu to direi. E foi a um lugar alto.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 4, 'E quando Deus se encontrou com Balaão, este lhe disse: Preparei os sete altares, e ofereci um novilho e um carneiro sobre cada altar.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 5, 'Então o senhor pôs uma palavra na boca de Balaão, e disse: Volta para Balaque, e assim falarás.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 6, 'Voltou, pois, para ele, e eis que estava em pé junto ao seu holocausto, ele e todos os príncipes de Moabe.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 7, 'Então proferiu Balaão a sua parábola, dizendo: De Arã me mandou trazer Balaque, o rei de Moabe, desde as montanhas do Oriente, dizendo: Vem, amaldiçoa-me a Jacó; vem, denuncia a Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 8, 'Como amaldiçoarei a quem Deus não amaldiçoou? e como denunciarei a quem o Senhor não denunciou?', 1, CURRENT_TIMESTAMP, false),
(4, 23, 9, 'Pois do cume das penhas o vejo, e dos outeiros o contemplo; eis que é um povo que habita só, e entre as nações não será contado.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 10, 'Quem poderá contar o pó de Jacó e o número da quarta parte de Israel? Que eu morra a morte dos justos, e seja o meu fim como o deles.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 11, 'Então disse Balaque a Balaão: Que me fizeste? Chamei-te para amaldiçoares os meus inimigos, e eis que inteiramente os abençoaste.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 12, 'E ele respondeu: Porventura não terei cuidado de falar o que o Senhor me puser na boca?', 1, CURRENT_TIMESTAMP, false),
(4, 23, 13, 'Então Balaque lhe disse: Rogo-te que venhas comigo a outro lugar, donde o poderás ver; verás somente a última parte dele, mas a todo ele não verás; e amaldiçoa-mo dali.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 14, 'Assim o levou ao campo de Zofim, ao cume de Pisga; e edificou sete altares, e ofereceu um novilho e um carneiro sobre cada altar.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 15, 'Disse Balaão a Balaque: Fica aqui em pé junto ao teu holocausto, enquanto eu vou ali ao encontro do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 16, 'E, encontrando-se o Senhor com Balaão, pôs-lhe na boca uma palavra, e disse: Volta para Balaque, e assim falarás.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 17, 'Voltou, pois, para ele, e eis que estava em pé junto ao seu holocausto, e os príncipes de Moabe com ele. Perguntou-lhe, pois, Balaque: Que falou o Senhor?', 1, CURRENT_TIMESTAMP, false),
(4, 23, 18, 'Então proferiu Balaão a sua parábola, dizendo: Levanta-te, Balaque, e ouve; escuta-me, filho de Zipor;', 1, CURRENT_TIMESTAMP, false),
(4, 23, 19, 'Deus não é homem, para que minta; nem filho do homem, para que se arrependa. Porventura, tendo ele dito, não o fará? ou, havendo falado, não o cumprirá?', 1, CURRENT_TIMESTAMP, false),
(4, 23, 20, 'Eis que recebi mandado de abençoar; pois ele tem abençoado, e eu não o posso revogar.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 21, 'Não se observa iniqüidade em Jacó, nem se vê maldade em Israel; o senhor seu Deus é com ele, no meio dele se ouve a aclamação dum rei;', 1, CURRENT_TIMESTAMP, false),
(4, 23, 22, 'É Deus que os vem tirando do Egito; as suas forças são como as do boi selvagem.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 23, 'Contra Jacó, pois, não há encantamento, nem adivinhação contra Israel. Agora se dirá de Jacó e de Israel: Que coisas Deus tem feito!', 1, CURRENT_TIMESTAMP, false),
(4, 23, 24, 'Eis que o povo se levanta como leoa, e se ergue como leão; não se deitará até que devore a presa, e beba o sangue dos que foram mortos:', 1, CURRENT_TIMESTAMP, false),
(4, 23, 25, 'Então Balaque disse a Balaão: Nem o amaldiçoes, nem tampouco o abençoes:', 1, CURRENT_TIMESTAMP, false),
(4, 23, 26, 'Respondeu, porém, Balaão a Balaque: Não te falei eu, dizendo: Tudo o que o Senhor falar, isso tenho de fazer?', 1, CURRENT_TIMESTAMP, false),
(4, 23, 27, 'Tornou Balaque a Balaão: Vem agora, e te levarei a outro lugar; porventura parecerá bem aos olhos de Deus que dali mo amaldiçoes.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 28, 'Então Balaque levou Balaão ao cume de Peor, que dá para o deserto.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 29, 'E Balaão disse a Balaque: Edifica-me aqui sete altares, e prepara-me aqui sete novilhos e sete carneiros.', 1, CURRENT_TIMESTAMP, false),
(4, 23, 30, 'Balaque, pois, fez como dissera Balaão; e ofereceu um novilho e um carneiro sobre cada altar.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 1, 'Vendo Balaão que parecia bem aos olhos do Senhor que abençoasse a Israel, não foi, como era costume, ao encontro dos encantamentos, mas voltou o rosto para o deserto.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 2, 'E, levantando Balaão os olhos, viu a Israel que se achava acampado segundo as suas tribos; e veio sobre ele o Espírito de Deus.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 3, 'Então proferiu Balaão a sua parábola, dizendo: Fala Balaão, filho de Beor; fala o homem que tem os olhos abertos;', 1, CURRENT_TIMESTAMP, false),
(4, 24, 4, 'fala aquele que ouve as palavras de Deus, o que vê a visão do Todo-Poderoso, que cai, e se lhe abrem os olhos:', 1, CURRENT_TIMESTAMP, false),
(4, 24, 5, 'Quão formosas são as tuas tendas, ó Jacó! as tuas moradas, ó Israel!', 1, CURRENT_TIMESTAMP, false),
(4, 24, 6, 'Como vales, elas se estendem; são como jardins à beira dos rios, como árvores de aloés que o Senhor plantou, como cedros junto às águas.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 7, 'De seus baldes manarão águas, e a sua semente estará em muitas águas; o seu rei se exalçará mais do que Agague, e o seu reino será exaltado.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 8, 'É Deus que os vem tirando do Egito; as suas forças são como as do boi selvagem; ele devorará as nações, seus adversários, lhes quebrará os ossos, e com as suas setas os atravessará.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 9, 'Agachou-se, deitou-se como leão, e como leoa; quem o despertará? Benditos os que te abençoarem, e malditos os que te amaldiçoarem.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 10, 'Pelo que a ira de Balaque se acendeu contra Balaão, e batendo ele as palmas, disse a Balaão: Para amaldiçoares os meus inimigos é que te chamei; e eis que já três vezes os abençoaste.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 11, 'Agora, pois, foge para o teu lugar; eu tinha dito que certamente te honraria, mas eis que o Senhor te privou dessa honra.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 12, 'Então respondeu Balaão a Balaque: Não falei eu também aos teus mensageiros, que me enviaste, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 24, 13, 'Ainda que Balaque me quisesse dar a sua casa cheia de prata e de ouro, eu não poderia ir além da ordem do Senhor, para fazer, de mim mesmo, o bem ou o mal; o que o Senhor falar, isso falarei eu?', 1, CURRENT_TIMESTAMP, false),
(4, 24, 14, 'Agora, pois, eis que me vou ao meu povo; vem, avisar-te-ei do que este povo fará ao teu povo nos últimos dias.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 15, 'Então proferiu Balaão a sua parábola, dizendo: Fala Balaão, filho de Beor; fala o homem que tem os olhos abertos;', 1, CURRENT_TIMESTAMP, false),
(4, 24, 16, 'fala aquele que ouve as palavras de Deus e conhece os desígnios do Altíssimo, que vê a visão do Todo-Poderoso, que cai, e se lhe abrem os olhos:', 1, CURRENT_TIMESTAMP, false),
(4, 24, 17, 'Eu o vejo, mas não no presente; eu o contemplo, mas não de perto; de Jacó procederá uma estrela, de Israel se levantará um cetro que ferirá os termos de Moabe, e destruirá todos os filhos de orgulho.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 18, 'E Edom lhe será uma possessão, e assim também Seir, os quais eram os seus inimigos; pois Israel fará proezas.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 19, 'De Jacó um dominará e destruirá os sobreviventes da cidade.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 20, 'Também viu Balaão a Amaleque e proferiu a sua parábola, dizendo: Amaleque era a primeira das nações, mas o seu fim será a destruição.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 21, 'E, vendo os quenitas, proferiu a sua parábola, dizendo: Firme está a tua habitação; e posto na penha está o teu ninho;', 1, CURRENT_TIMESTAMP, false),
(4, 24, 22, 'todavia será o quenita assolado, até que Assur te leve por prisioneiro.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 23, 'Proferiu ainda a sua parábola, dizendo: Ai, quem viverá, quando Deus fizer isto?', 1, CURRENT_TIMESTAMP, false),
(4, 24, 24, 'Naus virão das costas de Quitim, e afligirão a Assur; igualmente afligirão a Eber, que também será para destruição.', 1, CURRENT_TIMESTAMP, false),
(4, 24, 25, 'Então, tendo-se Balaão levantado, partiu e voltou para o seu lugar; e também Balaque se foi pelo seu caminho.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 1, 'Ora, Israel demorava-se em Sitim, e o povo começou a prostituir-se com as filhas de Moabe,', 1, CURRENT_TIMESTAMP, false),
(4, 25, 2, 'pois elas convidaram o povo aos sacrifícios dos seus deuses; e o povo comeu, e inclinou-se aos seus deuses.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 3, 'Porquanto Israel se juntou a Baal-Peor, a ira do Senhor acendeu-se contra ele.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 4, 'Disse, pois, o Senhor a Moisés: Toma todos os cabeças do povo, e enforca-os ao senhor diante do sol, para que a grande ira do Senhor se retire de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 5, 'Então Moisés disse aos juízes de Israel: Mate cada um os seus homens que se juntaram a Baal-Peor.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 6, 'E eis que veio um homem dos filhos de Israel, e trouxe a seus irmãos uma midianita à vista de Moisés e à vista de toda a congregação dos filhos de Israel, enquanto estavam chorando à porta da tenda da revelação.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 7, 'Vendo isso Finéias, filho de Eleazar, filho do sacerdote Arão, levantou-se do meio da congregação, e tomou na mão uma lança;', 1, CURRENT_TIMESTAMP, false),
(4, 25, 8, 'o foi após o israelita, e entrando na sua tenda, os atravessou a ambos, ao israelita e à mulher, pelo ventre. Então a praga cessou de sobre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 9, 'Ora, os que morreram daquela praga foram vinte e quatro mil.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 10, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 25, 11, 'Finéias, filho de Eleazar, filho do sacerdote Arão, desviou a minha ira de sobre os filhos de Israel, pois foi zeloso com o meu zelo no meio deles, de modo que no meu zelo não consumi os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 12, 'Portanto dize: Eis que lhe dou o meu pacto de paz,', 1, CURRENT_TIMESTAMP, false),
(4, 25, 13, 'e será para ele e para a sua descendência depois dele, o pacto de um sacerdócio perpétuo; porquanto foi zeloso pelo seu Deus, e fez expiação pelos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 14, 'O nome do israelita que foi morto com a midianita era Zinri, filho de Salu, príncipe duma casa paterna entre os simeonitas.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 15, 'E o nome da mulher midianita morta era Cozbi, filha de Zur; o qual era cabeça do povo duma casa paterna em Midiã.', 1, CURRENT_TIMESTAMP, false),
(4, 25, 16, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 25, 17, 'Afligi vós os midianitas e feri-os;', 1, CURRENT_TIMESTAMP, false),
(4, 25, 18, 'porque eles vos afligiram a vós com as suas ciladas com que vos enganaram no caso de Peor, e no caso de Cozbi, sua irmã, filha do príncipe de Midiã, a qual foi morta no dia da praga no caso de Peor.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 1, 'Depois daquela praga disse o Senhor a Moisés e a Eleazar, filho do sacerdote Arão:', 1, CURRENT_TIMESTAMP, false),
(4, 26, 2, 'Tomai a soma de toda a congregação dos filhos de Israel, da idade de vinte anos para cima, segundo as casas e seus pais, todos os que em Israel podem sair à guerra.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 3, 'Falaram-lhes, pois, Moisés e Eleazar o sacerdote, nas planícies de Moabe, junto ao Jordão, na altura de Jericó, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 26, 4, 'Contai o povo da idade de vinte anos para cima; como o Senhor ordenara a Moisés e aos filhos de Israel que saíram da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 5, 'Rúben, o primogênito de Israel; os filhos de Rúben: de Hanoque, a família dos hanoquitas; de Palu, a família dos paluítas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 6, 'de Hezrom, a família dos hezronitas; de Carmi, a família dos carmitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 7, 'Estas são as famílias dos rubenitas; os que foram deles contados eram quarenta e três mil setecentos e trinta.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 8, 'E o filho de Palu: Eliabe.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 9, 'Os filhos de Eliabe: Nemuel, Dato e Abirão. Estes são aqueles Datã e Abirão que foram chamados da congregação, os quais contenderam contra Moisés e contra Arão na companhia de Corá, quando contenderam contra o Senhor,', 1, CURRENT_TIMESTAMP, false),
(4, 26, 10, 'e a terra abriu a boca, e os tragou juntamente com Corá, quando pereceu aquela companhia; quando o fogo devorou duzentos e cinqüenta homens, os quais serviram de advertência.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 11, 'Todavia os filhos de Corá não morreram.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 12, 'Os filhos de Simeão, segundo as suas famílias: de Nemuel, a família dos nemuelitas; de Jamim, a família dos jaminitas; de Jaquim, a família dos jaquinitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 13, 'de Zerá, a família dos zeraítas; de Saul, a família dos saulitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 14, 'Estas são as famílias dos simeonitas, vinte e dois mil e duzentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 15, 'Os filhos de Gade, segundo as suas famílias: de Zefom, a família dos zefonitas; de Hagui, a família dos haguitas; de Suni, a família dos sunitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 16, 'de Ozni, a família dos oznitas; de Eri, a família dos eritas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 17, 'de Arode, a família dos aroditas; de Areli, a família dos arelitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 18, 'Estas são as famílias dos filhos de Gade, segundo os que foram deles contados, quarenta mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 19, 'Os filhos de Judá: Er e Onã; mas Er e Onã morreram na terra de Canaã.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 20, 'Assim os filhos de Judá, segundo as suas famílias, eram: de Selá, a família dos selanitas; de Pérez, a família dos perezitas; de Zerá, a família dos zeraítas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 21, 'E os filhos de Pérez eram: de Hezrom, a família dos hezronitas; de Hamul, a família dos hamulitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 22, 'Estas são as famílias de Judá, segundo os que foram deles contados, setenta e seis mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 23, 'Os filhos de Issacar, segundo as suas famílias: de Tola, a família dos tolaítas; de Puva, a família dos puvitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 24, 'de Jasube, a família dos jasubitas; de Sinrom, a família dos sinronitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 25, 'Estas são as famílias de Issacar, segundo os que foram deles contados, sessenta e quatro mil e trezentos:', 1, CURRENT_TIMESTAMP, false),
(4, 26, 26, 'Os filhos de Zebulom, segundo as suas famílias: de Serede, a família dos sereditas; de Elom, a família dos elonitas; de Jaleel, a família dos jaleelitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 27, 'Estas são as famílias dos zebulonitas, segundo os que foram deles contados, sessenta mil e quinhentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 28, 'Os filhos de José, segundo as suas famílias: Manassés e Efraim.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 29, 'Os filhos de Manassés: de Maquir, a família dos maquiritas; e Maquir gerou a Gileade; de Gileade, a família dos gileaditas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 30, 'Estes são os filhos de Gileade: de Iezer, a família dos iezritas; de Heleque, a família dos helequitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 31, 'de Asriel, a família dos asrielitas; de Siquém, a família dos siquemitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 32, 'e de Semida, a família dos semidaítas; e de Hefer, a família dos heferitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 33, 'Ora, Zelofeade, filho de Hefer, não tinha filhos, senão filhas; e as filhas de Zelofeade chamavam-se Macla, Noa, Hogla, Milca e Tirza.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 34, 'Estas são as famílias de Manassés; os que foram deles contados, eram cinqüenta e dois mil e setecentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 35, 'Estes são os filhos de Efraim, segundo as suas famílias: de Sutela, a família dos sutelaítas; de Bequer, a família dos bequeritas; de Taã, a família dos taanitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 36, 'E estes são os filhos de Sutela: de Erã, a família dos eranitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 37, 'Estas são as famílias dos filhos de Efraim, segundo os que foram deles contados, trinta e dois mil e quinhentos. Estes são os filhos de José, segundo as suas famílias.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 38, 'Os filhos de Benjamim, segundo as suas famílias: de Belá, a família dos belaítas; de Asbel, a família dos asbelitas; de Airão, a família dos airamitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 39, 'de Sefufã, a família dos sufamitas; de Hufão, a família dos hufamitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 40, 'E os filhos de Belá eram Arde e Naamã: de Arde a família dos arditas; de Naamã, a família dos naamitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 41, 'Estes são os filhos de Benjamim, segundo as suas famílias; os que foram deles contados, eram quarenta e cinco mil e seiscentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 42, 'Estes são os filhos de Dã, segundo as suas famílias: de Suão a família dos suamitas. Estas são as famílias de Dã, segundo as suas famílias.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 43, 'Todas as famílias dos suamitas, segundo os que foram deles contados, eram sessenta e quatro mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 44, 'Os filhos de Aser, segundo as suas famílias: de Imná, a família dos imnitas; de Isvi, a família dos isvitas; de Berias, a família dos beritas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 45, 'Dos filhos de Berias: de Heber, a família dos heberitas; de Malquiel, a família dos malquielitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 46, 'E a filha de Aser chamava-se Sera.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 47, 'Estas são as famílias dos filhos de Aser, segundo os que foram deles contados, cinqüenta e três mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 48, 'Os filhos de Naftali, segundo as suas famílias: de Jazeel, a família dos jazeelitas; de Guni, a família dos gunitas;', 1, CURRENT_TIMESTAMP, false),
(4, 26, 49, 'de Jezer, a família dos jezeritas; de Silém, a família dos silemitas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 50, 'Estas são as famílias de Naftali, segundo as suas famílias; os que foram deles contados, eram quarenta e cinco mil e quatrocentos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 51, 'Estes são os que foram contados dos filhos de Israel, seiscentos e um mil setecentos e trinta.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 52, 'Disse mais o senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 26, 53, 'A estes se repartirá a terra em herança segundo o número dos nomes.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 54, 'À tribo de muitos darás herança maior, e à de poucos darás herança menor; a cada qual se dará a sua herança segundo os que foram deles contados.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 55, 'Todavia a terra se repartirá por sortes; segundo os nomes das tribos de seus pais a herdarão.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 56, 'Segundo sair a sorte, se repartirá a herança deles entre as tribos de muitos e as de poucos.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 57, 'Também estes são os que foram contados dos levitas, segundo as suas famílias: de Gérson, a família dos gersonitas; de Coate, a família dos coatitas; de Merári, a família os meraritas.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 58, 'Estas são as famílias de Levi: a família dos libnitas, a família dos hebronitas, a família dos malitas, a família dos musitas, a família dos coraítas. Ora, Coate gerou a Anrão.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 59, 'E a mulher de Anrão chamava-se Joquebede, filha de Levi, a qual nasceu a Levi no Egito; e de Anrão ela teve Arão e Moisés, e Miriã, irmã deles.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 60, 'E a Arão nasceram Nadabe e Abiú, Eleazar e Itamar.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 61, 'Mas Nadabe e Abiú morreram quando ofereceram fogo estranho perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 62, 'E os que foram deles contados eram vinte e três mil, todos os homens da idade de um mês para cima; porque não foram contados entre os filhos de Israel, porquanto não lhes foi dada herança entre os filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 63, 'Esses são os que foram contados por Moisés e Eleazar, o sacerdote, que contaram os filhos de Israel nas planícies de Moabe, junto ao Jordão, na altura de Jericó.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 64, 'Entre esses, porém, não se achava nenhum daqueles que tinham sido contados por Moisés e Arão, o sacerdote, quando contaram os filhos de Israel no deserto de Sinai.', 1, CURRENT_TIMESTAMP, false),
(4, 26, 65, 'Porque o senhor dissera deles: Certamente morrerão no deserto; pelo que nenhum deles ficou, senão Calebe, filho de Jefoné, e Josué, filho de Num.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 1, 'Então vieram as filhas de Zelofeade, filho de Hefer, filho de Gileade, filho de Maquir, filho de Manassés, das famílias de Manassés, filho de José; e os nomes delas são estes: Macla, Noa, Hogla, Milca e Tirza;', 1, CURRENT_TIMESTAMP, false),
(4, 27, 2, 'apresentaram-se diante de Moisés, e de Eleazar, o sacerdote, e diante dos príncipes e de toda a congregação à porta da tenda da revelação, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 27, 3, 'Nosso pai morreu no deserto, e não se achou na companhia daqueles que se ajuntaram contra o Senhor, isto é, na companhia de Corá; porém morreu no seu próprio pecado, e não teve filhos.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 4, 'Por que se tiraria o nome de nosso pai dentre a sua família, por não ter tido um filho? Dai-nos possessão entre os irmãos de nosso pai.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 5, 'Moisés, pois, levou a causa delas perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 6, 'Então disse o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 27, 7, 'O que as filhas de Zelofeade falam é justo; certamente lhes darás possessão de herança entre os irmãos de seu pai; a herança de seu pai farás passar a elas.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 8, 'E dirás aos filhos de Israel: Se morrer um homem, e não tiver filho, fareis passar a sua herança à sua filha.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 9, 'E, se não tiver filha, dareis a sua herança a seus irmãos.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 10, 'Mas, se não tiver irmãos, dareis a sua herança aos irmãos de seu pai.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 11, 'Se também seu pai não tiver irmãos, então dareis a sua herança a seu parente mais chegado dentre a sua família, para que a possua; isto será para os filhos de Israel estatuto de direito, como o Senhor ordenou a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 12, 'Depois disse o Senhor a Moisés: sobe a este monte de Abarim, e vê a terra que tenho dado aos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 13, 'E, tendo-a visto, serás tu também recolhido ao teu povo, assim como o foi teu irmão Arão;', 1, CURRENT_TIMESTAMP, false),
(4, 27, 14, 'porquanto no deserto de Zim, na contenda da congregação, fostes rebeldes à minha palavra, não me santificando diante dos seus olhos, no tocante às águas {estas são as águas de Meribá de Cades, no deserto de Zim}.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 15, 'Respondeu Moisés ao Senhor:', 1, CURRENT_TIMESTAMP, false),
(4, 27, 16, 'Que o senhor, Deus dos espíritos de toda a carne, ponha um homem sobre a congregação,', 1, CURRENT_TIMESTAMP, false),
(4, 27, 17, 'o qual saia diante deles e entre diante deles, e os faça sair e os faça entrar; para que a congregação do Senhor não seja como ovelhas que não têm pastor.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 18, 'Então disse o Senhor a Moisés: Toma a Josué, filho de Num, homem em quem há o Espírito, e impõe-lhe a mão;', 1, CURRENT_TIMESTAMP, false),
(4, 27, 19, 'e apresenta-o perante Eleazar, o sacerdote, e perante toda a congregação, e dá-lhe a comissão à vista deles;', 1, CURRENT_TIMESTAMP, false),
(4, 27, 20, 'e sobre ele porás da tua glória, para que lhe obedeça toda a congregação dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 21, 'Ele, pois, se apresentará perante Eleazar, o sacerdote, o qual por ele inquirirá segundo o juízo do Urim, perante o Senhor; segundo a ordem de Eleazar sairão, e segundo a ordem de Eleazar entrarão, ele e todos os filhos de Israel, isto é, toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(4, 27, 22, 'Então Moisés fez como o Senhor lhe ordenara: tomou a Josué, apresentou-o perante Eleazar, o sacerdote, e perante toda a congregação,', 1, CURRENT_TIMESTAMP, false),
(4, 27, 23, 'impôs-lhe as mãos, e lhe deu a comissão; como o Senhor falara por intermédio de Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 28, 2, 'Ordena aos filhos de Israel, e dize-lhes: A minha oferta, o alimento para as minhas ofertas queimadas, de cheiro suave para mim, tereis cuidado para ma oferecer aos seus tempos determinados.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 3, 'Também lhes dirás: Esta é a oferta queimada que oferecereis ao Senhor: dois cordeiros de um ano, sem defeito, cada dia, em contínuo holocausto.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 4, 'Um cordeiro oferecerás pela manhã, e o outro à tardinha,', 1, CURRENT_TIMESTAMP, false),
(4, 28, 5, 'juntamente com a décima parte de uma efa de flor de farinha em oferta de cereais, misturada com a quarta parte de um him de azeite batido.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 6, 'Este é o holocausto contínuo, instituído no monte Sinai, em cheiro suave, oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 7, 'A oferta de libação do mesmo será a quarta parte de um him para um cordeiro; no lugar santo oferecerás a libação de bebida forte ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 8, 'E o outro cordeiro, oferecê-lo-ás à tardinha; com as ofertas de cereais e de libação, como o da manhã, o oferecerás, oferta queimada de cheiro suave ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 9, 'No dia de sábado oferecerás dois cordeiros de um ano, sem defeito, e dois décimos de efa de flor de farinha, misturada com azeite, em oferta de cereais, com a sua oferta de libação;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 10, 'é o holocausto de todos os sábados, além do holocausto contínuo e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 11, 'Nos princípios dos vossos meses oferecereis em holocausto ao Senhor: dois novilhos, um carneiro e sete cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 12, 'e três décimos de efa de flor de farinha, misturada com azeite, em oferta de cereais, para cada novilho; e dois décimos de efa de flor de farinha, misturada com azeite, em oferta de cereais, para o carneiro;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 13, 'e um décimo de efa de flor de farinha, misturada com azeite, em oferta de cereais, para cada cordeiro; é holocausto de cheiro suave, oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 14, 'As ofertas de libação do mesmo serão a metade de um him de vinho para um novilho, e a terça parte de um him para um carneiro, e a quarta parte de um him para um cordeiro; este é o holocausto de cada mês, por todos os meses do ano.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 15, 'Também oferecerás ao Senhor um bode como oferta pelo pecado; oferecer-se-á esse além do holocausto contínuo, com a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 16, 'No primeiro mês, aos catorze dias do mês, é a páscoa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 17, 'E aos quinze dias do mesmo mês haverá festa; por sete dias se comerão pães ázimos.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 18, 'No primeiro dia haverá santa convocação; nenhum trabalho servil fareis;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 19, 'mas oferecereis oferta queimada em holocausto ao Senhor: dois novilhos, um carneiro e sete cordeiros de um ano, todos eles sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 20, 'e a sua oferta de cereais, de flor de farinha misturada com azeite; oferecereis três décimos de efa para cada novilho, dois décimos para o carneiro,', 1, CURRENT_TIMESTAMP, false),
(4, 28, 21, 'e um décimo para cada um dos sete cordeiros;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 22, 'e em oferta pelo pecado oferecereis um bode, para fazer expiação por vos.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 23, 'Essas coisas oferecereis, além do holocausto da manhã, o qual é o holocausto contínuo.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 24, 'Assim, cada dia oferecereis, por sete dias, o alimento da oferta queimada em cheiro suave ao Senhor; oferecer-se-á além do holocausto contínuo com a sua oferta de libação;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 25, 'e no sétimo dia tereis santa convocação; nenhum trabalho servil fareis.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 26, 'Semelhantemente tereis santa convocação no dia das primícias, quando fizerdes ao Senhor oferta nova de cereais na vossa festa de semanas; nenhum trabalho servil fareis.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 27, 'Então oferecereis um holocausto em cheiro suave ao Senhor: dois novilhos, um carneiro e sete cordeiros de um ano;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 28, 'e a sua oferta de cereais, de flor de farinha misturada com azeite, três décimos de efa para cada novilho, dois décimos para o carneiro,', 1, CURRENT_TIMESTAMP, false),
(4, 28, 29, 'e um décimo para cada um dos sete cordeiros;', 1, CURRENT_TIMESTAMP, false),
(4, 28, 30, 'e um bode para fazer expiação por vós.', 1, CURRENT_TIMESTAMP, false),
(4, 28, 31, 'Além do holocausto contínuo e a sua oferta de cereais, os oferecereis, com as suas ofertas de libação; eles serão sem defeito.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 1, 'No sétimo mês, no primeiro dia do mês, tereis uma santa convocação; nenhum trabalho servil fareis; será para vós dia de sonido de trombetas.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 2, 'Oferecereis um holocausto em cheiro suave ao Senhor: um novilho, um carneiro e sete cordeiros de um ano, todos sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 3, 'e a sua oferta de cereais, de flor de farinha misturada com azeite, três décimos de efa para o novilho, dois décimos para o carneiro,', 1, CURRENT_TIMESTAMP, false),
(4, 29, 4, 'e um décimo para cada um dos sete cordeiros;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 5, 'e um bode para oferta pelo pecado, para fazer expiação por vós;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 6, 'além do holocausto do mês e a sua oferta de cereais, e do holocausto contínuo e a sua oferta de cereais, com as suas ofertas de libação, segundo a ordenança, em cheiro suave, oferta queimada ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 7, 'Também no dia dez deste sétimo mês tereis santa convocação, e afligireis as vossas almas; nenhum trabalho fareis;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 8, 'mas oferecereis um holocausto, em cheiro suave ao Senhor: um novilho, um carneiro e sete cordeiros de um ano, todos eles sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 9, 'e a sua oferta de cereais, de flor de farinha misturada com azeite, três décimos de efa para o novilho, dois décimos para o carneiro,', 1, CURRENT_TIMESTAMP, false),
(4, 29, 10, 'e um décimo para cada um dos sete cordeiros;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 11, 'e um bode para oferta pelo pecado, além da oferta pelo pecado, com a qual se faz expiação, e do holocausto contínuo com a sua oferta de cereais e as suas ofertas de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 12, 'Semelhantemente, aos quinze dias deste sétimo mês tereis santa convocação; nenhum trabalho servil fareis; mas por sete dias celebrareis festa ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 13, 'Oferecereis um holocausto em oferta queimada, de cheiro suave ao Senhor: treze novilhos, dois carneiros e catorze cordeiros de um ano, todos eles sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 14, 'e a sua oferta de cereais, de flor de farinha misturada com azeite, três décimos de efa para cada um dos treze novilhos, dois décimos para cada um dos dois carneiros,', 1, CURRENT_TIMESTAMP, false),
(4, 29, 15, 'e um décimo para cada um dos catorze cordeiros;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 16, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 17, 'No segundo dia, doze novilhos, dois carneiros, catorze cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 18, 'e a sua oferta de cereais, e as suas ofertas de libação para os novilhos, para os carneiros e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 19, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e as suas ofertas de libação:', 1, CURRENT_TIMESTAMP, false),
(4, 29, 20, 'No terceiro dia, onze novilhos, dois carneiros, catorze cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 21, 'e a sua oferta de cereais, e as suas ofertas de libação para os novilhos, para os carneiros e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 22, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 23, 'No quarto dia, dez novilhos, dois carneiros, catorze cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 24, 'e a sua oferta de cereais, e as suas ofertas de libação para os novilhos, para os carneiros e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 25, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 26, 'No quinto dia, nove novilhos, dois carneiros, catorze cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 27, 'e a sua oferta de cereais, e as suas ofertas de libação para os novilhos, para os carneiros e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 28, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 29, 'No sexto dia, oito novilhos, dois carneiros, catorze cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 30, 'e a sua oferta de cereais, e as suas ofertas de libação para os novilhos, para os carneiros e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 31, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 32, 'No sétimo dia, sete novilhos, dois carneiros, catorze cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 33, 'e a sua oferta de cereais, e as suas ofertas de libação para os novilhos, para os carneiros e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 34, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 35, 'No oitavo dia tereis assembléia solene; nenhum trabalho servil fareis;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 36, 'mas oferecereis um holocausto em oferta queimada de cheiro suave ao Senhor: um novilho, um carneiro, sete cordeiros de um ano, sem defeito;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 37, 'e a sua oferta de cereais, e as suas ofertas de libação para o novilho, para o carneiro e para os cordeiros, conforme o seu número, segundo a ordenança;', 1, CURRENT_TIMESTAMP, false),
(4, 29, 38, 'e um bode para oferta pelo pecado, além do holocausto contínuo com a sua oferta de cereais e a sua oferta de libação.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 39, 'Oferecereis essas coisas ao Senhor nas vossas festas fixas, além dos vossos votos, e das vossas ofertas voluntárias, tanto para os vossos holocaustos, como para as vossas ofertas de cereais, as vossas ofertas de libações e os vossos sacrifícios de ofertas pacíficas.', 1, CURRENT_TIMESTAMP, false),
(4, 29, 40, 'Falou, pois, Moisés aos filhos de Israel, conforme tudo o que o Senhor lhe ordenara.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 1, 'Depois disse Moisés aos cabeças das tribos dos filhos de Israel: Isto é o que o Senhor ordenou:', 1, CURRENT_TIMESTAMP, false),
(4, 30, 2, 'Quando um homem fizer voto ao Senhor, ou jurar, ligando-se com obrigação, não violará a sua palavra; segundo tudo o que sair da sua boca fará.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 3, 'Também quando uma mulher, na sua mocidade, estando ainda na casa de seu pai, fizer voto ao Senhor, e com obrigação se ligar,', 1, CURRENT_TIMESTAMP, false),
(4, 30, 4, 'e seu pai souber do seu voto e da obrigação com que se ligou, e se calar para com ela, então todos os seus votos serão válidos, e toda a obrigação com que se ligou será válida.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 5, 'Mas se seu pai lho vedar no dia em que o souber, todos os seus votos e as suas obrigações, com que se tiver ligado, deixarão de ser válidos; e o Senhor lhe perdoará, porquanto seu pai lhos vedou.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 6, 'Se ela se casar enquanto ainda estiverem sobre ela os seus votos ou o dito irrefletido dos seus lábios, com que se tiver obrigado,', 1, CURRENT_TIMESTAMP, false),
(4, 30, 7, 'e seu marido o souber e se calar para com ela no dia em que o souber, os votos dela serão válidos; e as obrigações com que se ligou serão válidas.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 8, 'Mas se seu marido lho vedar no dia em que o souber, anulará o voto que estiver sobre ela, como também o dito irrefletido dos seus lábios, com que se tiver obrigado; e o senhor lhe perdoará.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 9, 'No tocante ao voto de uma viúva ou de uma repudiada, tudo com que se obrigar ser-lhe-á válido.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 10, 'Se ela, porém, fez voto na casa de seu marido, ou se obrigou com juramento,', 1, CURRENT_TIMESTAMP, false),
(4, 30, 11, 'e seu marido o soube e se calou para com ela, não lho vedando, todos os seus votos serão válidos; e toda a obrigação com que se ligou será válida.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 12, 'Se, porém, seu marido de todo lhos anulou no dia em que os soube, deixará de ser válido tudo quanto saiu dos lábios dela, quer no tocante aos seus votos, quer no tocante àquilo a que se obrigou; seu marido lhos anulou; e o senhor lhe perdoará.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 13, 'Todo voto, e todo juramento de obrigação, que ela tiver feito para afligir a alma, seu marido pode confirmá-lo, ou pode anulá-lo.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 14, 'Se, porém, seu marido, de dia em dia, se calar inteiramente para com ela, confirma todos os votos e todas as obrigações que estiverem sobre ela; ele lhos confirmou, porquanto se calou para com ela no dia em que os soube.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 15, 'Mas se de todo lhos anular depois de os ter sabido, ele levará sobre si a iniqüidade dela.', 1, CURRENT_TIMESTAMP, false),
(4, 30, 16, 'Esses são os estatutos que o Senhor ordenou a Moisés, entre o marido e sua mulher, entre o pai e sua filha, na sua mocidade, em casa de seu pai.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 31, 2, 'Vinga os filhos de Israel dos midianitas; depois serás recolhido ao teu povo.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 3, 'Falou, pois, Moisés ao povo, dizendo: Armai homens dentre vós para a guerra, a fim de que saiam contra Midiã, para executarem a vingança do Senhor sobre Midiã.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 4, 'Enviareis à guerra mil de cada tribo entre todas as tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 5, 'Assim foram entregues dos milhares de Israel, mil de cada tribo, doze mil armados para a peleja.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 6, 'E Moisés mandou à guerra esses mil de cada tribo, e com eles Finéias, filho de Eleazar, o sacerdote, o qual levava na mão os vasos do santuário e as trombetas para tocarem o alarme.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 7, 'E pelejaram contra Midiã, como o senhor ordenara a Moisés; e mataram a todos os homens.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 8, 'Com eles mataram também os reis de Midiã, a saber, Evi, Requem, Zur, Hur e Reba, cinco reis de Midiã; igualmente mataram à espada a Balaão, filho de Beor.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 9, 'Também os filhos de Israel levaram presas as mulheres dos midianitas e os seus pequeninos; e despojaram-nos de todo o seu gado, e de todos os seus rebanhos, enfim, de todos os seus bens;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 10, 'queimaram a fogo todas as cidades em que eles habitavam e todos os seus acampamentos;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 11, 'tomaram todo o despojo e toda a presa, tanto de homens como de animais;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 12, 'e trouxeram os cativos e a presa e o despojo a Moisés, a Eleazar, o sacerdote, e à congregação dos filhos de Israel, ao arraial, nas planícies de Moabe, que estão junto do Jordão, na altura de Jericó.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 13, 'Saíram, pois, Moisés e Eleazar, o sacerdote, e todos os príncipes da congregação, ao encontro deles fora do arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 14, 'E indignou-se Moisés contra os oficiais do exército, chefes dos milhares e chefes das centenas, que vinham do serviço da guerra,', 1, CURRENT_TIMESTAMP, false),
(4, 31, 15, 'e lhes disse: Deixastes viver todas as mulheres?', 1, CURRENT_TIMESTAMP, false),
(4, 31, 16, 'Eis que estas foram as que, por conselho de Balaão, fizeram que os filhos de Israel pecassem contra o Senhor no caso de Peor, pelo que houve a praga entre a congregação do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 17, 'Agora, pois, matai todos os meninos entre as crianças, e todas as mulheres que conheceram homem, deitando-se com ele.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 18, 'Mas todas as meninas, que não conheceram homem, deitando-se com ele, deixai-as viver para vós.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 19, 'Acampai-vos por sete dias fora do arraial; todos vós, tanto o que tiver matado alguma pessoa, como o que tiver tocado algum morto, ao terceiro dia e ao sétimo dia purificai-vos, a vós e aos vossos cativos.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 20, 'Também purificai-vos no tocante a todo vestido, e todo artigo de peles, e toda obra de pelos de cabras, e todo utensílio de madeira.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 21, 'Então Eleazar, o sacerdote, disse aos homens de guerra que tinham saído à peleja: Este é o estatuto da lei que o Senhor ordenou a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 31, 22, 'o ouro, a prata, o bronze, o ferro, o estanho, o chumbo,', 1, CURRENT_TIMESTAMP, false),
(4, 31, 23, 'tudo o que pode resistir ao fogo, fálo-eis passar pelo fogo, e ficará limpo; todavia será purificado com a água de purificação; e tudo o que não pode resistir ao fogo, fá-lo-eis passar pela água.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 24, 'Também lavareis as vossas vestes ao sétimo dia, e ficareis limpos, e depois entrareis no arraial.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 25, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 31, 26, 'Faze a soma da presa que foi tomada, tanto de homens como de animais, tu e Eleazar, o sacerdote, e os cabeças das casas paternas da congregação;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 27, 'e divide-a em duas partes iguais, entre os que, hábeis na guerra, saíram à peleja, e toda a congregação.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 28, 'E tomarás para o Senhor um tributo dos homens de guerra, que saíram à peleja; um em quinhentos, assim dos homens, como dos bois, dos jumentos e dos rebanhos;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 29, 'da sua metade o tomareis, e o dareis a Eleazar, o sacerdote, para a oferta alçada do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 30, 'Mas da metade que pertence aos filhos de Israel tomarás um de cada cinqüenta, tanto dos homens, como dos bois, dos jumentos, dos rebanhos, enfim, de todos os animais, e os darás aos levitas, que estão encarregados do serviço do tabernáculo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 31, 'Fizeram, pois, Moisés e Eleazar, o sacerdote, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 32, 'Ora, a presa, o restante do despojo que os homens de guerra tomaram, foi de seiscentas e setenta e cinco mil ovelhas,', 1, CURRENT_TIMESTAMP, false),
(4, 31, 33, 'setenta e dois mil bois,', 1, CURRENT_TIMESTAMP, false),
(4, 31, 34, 'e sessenta e um mil jumentos;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 35, 'e trinta e duas mil pessoas, ao todo, do sexo feminino, que ainda se conservavam virgens.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 36, 'Assim a metade, que era a porção dos que saíram à guerra, foi em número de trezentas e trinta e sete mil e quinhentas ovelhas;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 37, 'e das ovelhas foi o tributo para o Senhor seiscentas e setenta e cinco.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 38, 'E foram os bois trinta e seis mil, dos quais foi o tributo para o Senhor setenta e dois.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 39, 'E foram os jumentos trinta mil e quinhentos, dos quais foi o tributo para o Senhor sessenta e um.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 40, 'E houve de pessoas dezesseis mil, das quais foi o tributo para o Senhor trinta e duas pessoas.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 41, 'Moisés, pois, deu a Eleazar, o sacerdote, o tributo, que era a oferta alçada do Senhor, como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 42, 'E da metade que era dos filhos de Israel, que Moisés separara da que era dos homens que pelejaram', 1, CURRENT_TIMESTAMP, false),
(4, 31, 43, '{ora, a metade que coube à congregação foi, das ovelhas, trezentas e trinta e sete mil e quinhentas;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 44, 'dos bois trinta e seis mil;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 45, 'dos jumentos trinta mil e quinhentos;', 1, CURRENT_TIMESTAMP, false),
(4, 31, 46, 'e das pessoas dezesseis mil},', 1, CURRENT_TIMESTAMP, false),
(4, 31, 47, 'isto é, da metade que era dos filhos de Israel, Moisés tomou um de cada cinqüenta, tanto dos homens como dos animais, e os deu aos levitas, que estavam encarregados do serviço do tabernáculo do Senhor; como o Senhor ordenara a Moisés.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 48, 'Então chegaram-se a Moisés os oficiais que estavam sobre os milhares do exército, os chefes de mil e os chefes de cem,', 1, CURRENT_TIMESTAMP, false),
(4, 31, 49, 'e disseram-lhe: Teus servos tomaram a soma dos homens de guerra que estiveram sob o nosso comando; e não falta nenhum de nós.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 50, 'Pelo que trouxemos a oferta do Senhor, cada um o que achou, artigos de ouro, cadeias, braceletes, anéis, arrecadas e colares, para fazer expiação pelas nossas almas perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 51, 'Assim Moisés e Eleazar, o sacerdote, tomaram deles o ouro, todo feito em jóias.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 52, 'E todo o ouro da oferta alçada que os chefes de mil e os chefes de cem fizeram ao Senhor, foi dezesseis mil setecentos e cinqüenta siclos', 1, CURRENT_TIMESTAMP, false),
(4, 31, 53, '{pois os homens de guerra haviam tomado despojo, cada um para si}.', 1, CURRENT_TIMESTAMP, false),
(4, 31, 54, 'Assim receberam Moisés e Eleazar, o sacerdote, o ouro dos chefes de mil e dos chefes de cem, e o puseram na tenda da revelação por memorial para os filhos de Israel perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 1, 'Ora, os filhos de Rúben e os filhos de Gade tinham gado em grande quantidade; e quando viram a terra de Jazer, e a terra de Gileade, e que a região era própria para o gado,', 1, CURRENT_TIMESTAMP, false),
(4, 32, 2, 'vieram os filhos de Gade e os filhos de Rúben a Moisés e a Eleazar, o sacerdote, e aos príncipes da congregação e falaram-lhes, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 32, 3, 'Atarote, Dibom, Jazer, Ninra, Hesbom, Eleale, Sebã, Nebo e Beom,', 1, CURRENT_TIMESTAMP, false),
(4, 32, 4, 'a terra que o Senhor feriu diante da congregação de Israel, é terra para gado, e os teus servos têm gado.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 5, 'Disseram mais: Se temos achado graça aos teus olhos, dê-se esta terra em possessão aos teus servos, e não nos faças passar o Jordão.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 6, 'Moisés, porém, respondeu aos filhos de Gade e aos filhos de Rúben: Irão vossos irmãos à peleja, e ficareis vós sentados aqui?', 1, CURRENT_TIMESTAMP, false),
(4, 32, 7, 'Por que, pois, desanimais o coração dos filhos de Israel, para eles não passarem à terra que o Senhor lhes deu?', 1, CURRENT_TIMESTAMP, false),
(4, 32, 8, 'Assim fizeram vossos pais, quando os mandei de Cades-Barnéia a ver a terra.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 9, 'Pois, tendo eles subido até o vale de Escol, e visto a terra, desanimaram o coração dos filhos de Israel, para que não entrassem na terra que o Senhor lhes dera.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 10, 'Então a ira do Senhor se acendeu naquele mesmo dia, e ele jurou, dizendo:', 1, CURRENT_TIMESTAMP, false),
(4, 32, 11, 'De certo os homens que subiram do Egito, de vinte anos para cima, não verão a terra que prometi com juramento a Abraão, a Isaque, e a Jacó! porquanto não perseveraram em seguir-me;', 1, CURRENT_TIMESTAMP, false),
(4, 32, 12, 'exceto Calebe, filho de Jefoné o quenezeu, e Josué, filho de Num, porquanto perseveraram em seguir ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 13, 'Assim se acendeu a ira do Senhor contra Israel, e ele os fez andar errantes no deserto quarenta anos, até que se consumiu toda aquela geração que fizera mal aos olhos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 14, 'E eis que vós, uma geração de homens pecadores, vos levantastes em lugar de vossos pais, para ainda mais aumentardes o furor da ira do Senhor contra Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 15, 'se vós vos virardes de segui-lo, também ele tornará a deixá-los no deserto; assim destruireis a todo este povo:', 1, CURRENT_TIMESTAMP, false),
(4, 32, 16, 'Então chegaram-se a ele, e disseram: Construiremos aqui currais para o nosso gado, e cidades para os nossos pequeninos;', 1, CURRENT_TIMESTAMP, false),
(4, 32, 17, 'nós, porém, nos armaremos, apressando-nos adiante dos filhos de Israel, até os levarmos ao seu lugar; e ficarão os nossos pequeninos nas cidades fortificadas, por causa dos habitantes da terra.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 18, 'Não voltaremos para nossas casas até que os filhos de Israel estejam de posse, cada um, da sua herança.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 19, 'Porque não herdaremos com eles além do Jordão, nem mais adiante; visto que já possuímos a nossa herança aquém do Jordão, ao oriente.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 20, 'Então lhes respondeu Moisés: se isto fizerdes, se vos armardes para a guerra perante o Senhor,', 1, CURRENT_TIMESTAMP, false),
(4, 32, 21, 'e cada um de vós, armado, passar o Jordão perante o Senhor, até que ele haja lançado fora os seus inimigos de diante dele,', 1, CURRENT_TIMESTAMP, false),
(4, 32, 22, 'e a terra esteja subjugada perante o senhor, então, sim, voltareis e sereis inculpáveis perante o Senhor e perante Israel; e esta terra vos será por possessão perante o Senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 23, 'Mas se não fizerdes assim, estareis pecando contra o Senhor; e estai certos de que o vosso pecado vos há de atingir.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 24, 'Edificai cidades para os vossos pequeninos, e currais para as vossas ovelhas; e cumpri o que saiu da vossa boca.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 25, 'Então os filhos de Gade e os filhos de Rúben disseram a Moisés: Como ordena meu senhor, assim farão teus servos.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 26, 'Os nossos pequeninos, as nossas mulheres, os nossos rebanhos e todo o nosso gado ficarão nas cidades de Gileade;', 1, CURRENT_TIMESTAMP, false),
(4, 32, 27, 'mas os teus servos passarão, cada um que está armado para a guerra, a pelejar perante o Senhor, como diz o meu senhor.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 28, 'Então Moisés deu ordem acerca deles a Eleazar, o sacerdote, e a Josué, filho de Num, e aos cabeças das casas paternas nas tribos dos filhos de Israel;', 1, CURRENT_TIMESTAMP, false),
(4, 32, 29, 'e disse-lhes Moisés: Se os filhos de Gade e os filhos de Rúben passarem convosco o Jordão, armado cada um para a guerra perante o Senhor, e a terra for subjugada diante de vós, então lhes dareis a terra de Gileade por possessão;', 1, CURRENT_TIMESTAMP, false),
(4, 32, 30, 'se, porém, não passarem armados convosco, terão possessões entre vós na terra de Canaã.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 31, 'Ao que responderam os filhos de Gade e os filhos de Rúben: Como o senhor disse a teus servos, assim faremos.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 32, 'Nós passaremos armados perante o senhor para a terra de Canaã, e teremos a possessão de nossa herança aquém do Jordão.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 33, 'Assim deu Moisés aos filhos de Gade e aos filhos de Rúben, e à meia tribo de Manassés, filho de José, o reino de Siom, rei dos amorreus, e o reino de Ogue, rei de Basã, a terra com as suas cidades e os respectivos territórios ao redor.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 34, 'Os filhos de Gade, pois, edificaram a Dibom, Atarote, Aroer,', 1, CURRENT_TIMESTAMP, false),
(4, 32, 35, 'Atarote-Sofã, Jazer, Jogbeá,', 1, CURRENT_TIMESTAMP, false),
(4, 32, 36, 'Bete-Ninra e Bete-Harã, cidades fortificadas; e construíram currais de ovelhas.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 37, 'E os filhos de Rúben edificaram a Hesbom, Eleale e Quiriataim;', 1, CURRENT_TIMESTAMP, false),
(4, 32, 38, 'e Nebo e Baal-Meom {mudando-lhes os nomes}, e Sibma; e deram outros nomes às cidades que edificaram.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 39, 'E os filhos de Maquir, filho de Manassés, foram a Gileade e a tomaram, e desapossaram aos amorreus que aí estavam.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 40, 'Deu, pois, Moisés a terra de Gileade a Maquir, filho de Manassés, o qual habitou nela.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 41, 'E foi Jair, filho de Manassés, e tomou as aldeias dela, e chamou-lhes Havote-Jair.', 1, CURRENT_TIMESTAMP, false),
(4, 32, 42, 'Também foi Nobá, e tomou a Quenate com as suas aldeias; e chamou-lhe Nobá, segundo o seu próprio nome.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 1, 'São estas as jornadas dos filhos de Israel, pelas quais saíram da terra do Egito, segundo os seus exércitos, sob o comando de Moisés e Arão.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 2, 'Moisés registrou os pontos de partida, segundo as suas jornadas, conforme o mandado do Senhor; e estas são as suas jornadas segundo os pontos de partida:', 1, CURRENT_TIMESTAMP, false),
(4, 33, 3, 'Partiram de Ramessés no primeiro mês, no dia quinze do mês; no dia seguinte ao da páscoa saíram os filhos de Israel afoitamente à vista de todos os egípcios,', 1, CURRENT_TIMESTAMP, false),
(4, 33, 4, 'enquanto estes enterravam a todos os seus primogênitos, a quem o Senhor havia ferido entre eles, havendo o senhor executado juízos também contra os seus deuses.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 5, 'Partiram, pois, os filhos de Israel de Ramessés, e acamparam-se em Sucote.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 6, 'Partiram de Sucote, e acamparam-se em Etã, que está na extremidade do deserto.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 7, 'Partiram de Etã, e voltando a Pi-Hairote, que está defronte de Baal-Zefom, acamparam-se diante de Migdol.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 8, 'Partiram de Pi-Hairote, e passaram pelo meio do mar ao deserto; e andaram caminho de três dias no deserto de Etã, e acamparam-se em Mara.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 9, 'Partiram de Mara, e vieram a Elim, onde havia doze fontes de água e setenta palmeiras, e acamparam-se ali.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 10, 'Partiram de Elim, e acamparam-se junto ao Mar Vermelho.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 11, 'Partiram do Mar Vermelho, e acamparam-se no deserto de Sim.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 12, 'Partiram do deserto de Sim, e acamparam-se em Dofca.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 13, 'Partiram de Dofca, e acamparam-se em Alus.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 14, 'Partiram de Alus, e acamparam-se em Refidim; porém não havia ali água para o povo beber.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 15, 'Partiram, pois, de Refidim, e acamparam-se no deserto de Sinai.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 16, 'Partiram do deserto de Sinai, e acamparam-se em Quibrote-Hataavá.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 17, 'Partiram de Quibrote-Hataavá, e acamparam-se em Hazerote.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 18, 'Partiram de Hazerote, e acamparam-se em Ritma.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 19, 'Partiram de Ritma, e acamparam-se em Rimom-Pérez.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 20, 'Partiram de Rimom-Pérez, e acamparam-se em Libna.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 21, 'Partiram de Libna, e acamparam-se em Rissa.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 22, 'Partiram de Rissa, e acamparam-se em Queelata.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 23, 'Partiram de Queelata, e acamparam-se no monte Sefer.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 24, 'Partiram do monte Sefer, e acamparam-se em Harada.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 25, 'Partiram de Harada, e acamparam-se em Maquelote.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 26, 'Partiram de Maquelote, e acamparam-se em Taate.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 27, 'Partiram de Taate, e acamparam-se em Tera.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 28, 'Partiram de Tera, e acamparam-se em Mitca.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 29, 'Partiram de Mitca, e acamparam-se em Hasmona.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 30, 'Partiram de Hasmona, e acamparam-se em Moserote.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 31, 'Partiram de Moserote, e acamparam-se em Bene-Jaacã.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 32, 'Partiram de Bene-Jaacã, e acamparam-se em Hor-Hagidgade.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 33, 'Partiram de Hor-Hagidgade, e acamparam-se em Jotbatá.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 34, 'Partiram de Jotbatá, e acamparam-se em Abrona.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 35, 'Partiram de Abrona, e acamparam-se em Eziom-Geber.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 36, 'Partiram de Eziom-Geber, e acamparam-se no deserto de Zim, que é Cades.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 37, 'Partiram de Cades, e acamparam-se no monte Hor, na fronteira da terra de Edom.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 38, 'Então Arão, o sacerdote, subiu ao monte Hor, conforme o mandado do Senhor, e ali morreu no quadragésimo ano depois da saída dos filhos de Israel da terra do Egito, no quinto mês, no primeiro dia do mês.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 39, 'E Arão tinha cento e vinte e três anos de idade, quando morreu no monte Hor.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 40, 'Ora, o cananeu, rei de Arade, que habitava o sul da terra de Canaã, ouviu que os filhos de Israel chegavam.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 41, 'Partiram do monte Hor, e acamparam-se em Zalmona.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 42, 'Partiram de Zalmona, e acamparam-se em Punom.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 43, 'Partiram de Punom, e acamparam-se em Obote.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 44, 'Partiram de Obote, e acamparam-se em Ije-Abarim, na fronteira de Moabe.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 45, 'Partiram de Ije-Abarim, e acamparam-se em Dibom-Gade.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 46, 'Partiram de Dibom-Fade, e acamparam-se em Almom-Diblataim.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 47, 'Partiram de Almom-Diblataim, e acamparam-se nos montes de Abarim, defronte de Nebo.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 48, 'e seu pai. de Moabe, junto ao Jordão, na altura de Jericó;', 1, CURRENT_TIMESTAMP, false),
(4, 33, 49, 'isto é, acamparam-se junto ao Jordão, desde Bete-Jesimote até Abel-Sitim, nas planícies de Moabe.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 50, 'Também disse o Senhor a Moisés, nas planícies de Moabe, junto ao Jordão, na altura de Jericó:', 1, CURRENT_TIMESTAMP, false),
(4, 33, 51, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes passado o Jordão para a terra de Canaã,', 1, CURRENT_TIMESTAMP, false),
(4, 33, 52, 'lançareis fora todos os habitantes da terra de diante de vós, e destruireis todas as suas pedras em que há figuras; também destruireis todas as suas imagens de fundição, e desfareis todos os seus altos;', 1, CURRENT_TIMESTAMP, false),
(4, 33, 53, 'e tomareis a terra em possessão, e nela habitareis; porquanto a vós vos tenho dado esta terra para a possuirdes.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 54, 'Herdareis a terra por meio de sortes, segundo as vossas famílias: à família que for grande, dareis uma herança maior, e à família que for pequena, dareis uma herança menor; o lugar que por sorte sair para alguém, esse lhe pertencerá; segundo as tribos de vossos pais recebereis as heranças.', 1, CURRENT_TIMESTAMP, false),
(4, 33, 55, 'Mas se não lançardes fora os habitantes da terra de diante de vós, os que deixardes ficar vos serão como espinhos nos olhos, e como abrolhos nas ilhargas, e vos perturbarão na terra em que habitardes;', 1, CURRENT_TIMESTAMP, false),
(4, 33, 56, 'e eu vos farei a vós como pensei em fazer-lhes a eles.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 1, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 34, 2, 'Dá ordem aos filhos de Israel, e dize-lhes: Quando entrardes na terra de Canaã, terra esta que vos há de cair em herança, por toda a sua extensão,', 1, CURRENT_TIMESTAMP, false),
(4, 34, 3, 'a banda do sul será desde o deserto de Zim, ao longo de Edom; e o limite do sul se estenderá da extremidade do Mar Salgado, para o oriente;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 4, 'e este limite irá rodeando para o sul da subida de Acrabim, e continuará até Zim; e, saindo ao sul de Cades-Barnéia, seguirá para Hazar-Hadar, e continuará até Azmom;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 5, 'e daí irá rodeando até o ribeiro do Egito, e terminará na praia do mar.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 6, 'Para o ocidente, o Mar Grande vos será por limite; o próprio mar será o vosso limite ocidental.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 7, 'Este será o vosso limite setentrional: desde o Mar Grande marcareis para vós até o Monte Hor;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 8, 'desde o monte Hor marcareis até a entrada de Hamate; daí ele se estenderá até Zedade;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 9, 'dali continuará até Zifrom, e irá terminar em Hazar-Enã. Este será o vosso limite setentrional.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 10, 'Marcareis o vosso limite oriental desde Hazar-Enã até Sefã;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 11, 'este limite descerá de Sefã até Ribla, ao oriente de Aim; depois irá descendo ao longo da borda do mar de Quinerete ao oriente;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 12, 'descerá ainda para o Jordão, e irá terminar no Mar Salgado. Esta será a vossa terra, segundo os seus limites em redor.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 13, 'Moisés, pois, deu ordem aos filhos de Israel, dizendo: Esta é a terra que herdareis por sortes, a qual o Senhor mandou que se desse às nove tribos e à meia tribo;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 14, 'porque a tribo dos filhos de Rúben, segundo as casas de seus pais, e a tribo dos filhos de Gade, segundo as casas de seus pais, como também a meia tribo de Manassés, já receberam a sua herança;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 15, 'isto é, duas tribos e meia já receberam a sua herança aquém do Jordão, na altura de Jericó, do lado oriental.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 16, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 34, 17, 'Estes são os nomes dos homens que vos repartirão a terra por herança: Eleazar, o sacerdote, e Josué, filho de Num;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 18, 'também tomareis de cada tribo um príncipe, para repartir a terra em herança.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 19, 'E estes são os nomes dos homens: Da tribo de Judá, Calebe, filho de Jefoné:', 1, CURRENT_TIMESTAMP, false),
(4, 34, 20, 'da tribo dos filhos de Simeão, Semuel, filho de Amiúde;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 21, 'da tribo de Benjamim, Elidá, filho de Quislom;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 22, 'da tribo dos filhos de Dã o príncipe Buqui, filho de Jógli;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 23, 'dos filhos de José: da tribo dos filhos de Manassés o príncipe Haniel, filho de Éfode;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 24, 'da tribo dos filhos de Efraim o príncipe Quemuel, filho de Siftã;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 25, 'da tribo dos filhos de Zebulom o príncipe Elizafã, filho de Parnaque;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 26, 'da tribo dos filhos de Issacar o príncipe Paltiel, filho de Azã;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 27, 'da tribo dos filhos de Aser o príncipe Aiúde, filho de Selômi;', 1, CURRENT_TIMESTAMP, false),
(4, 34, 28, 'da tribo dos filhos de Naftali o príncipe Pedael, filho de Amiúde.', 1, CURRENT_TIMESTAMP, false),
(4, 34, 29, 'Estes são aqueles a quem o Senhor ordenou que repartissem a herança pelos filhos de Israel na terra de Canaã.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 1, 'Disse mais o Senhor a Moisés nas planícies de Moabe, junto ao Jordão, na altura de Jericó:', 1, CURRENT_TIMESTAMP, false),
(4, 35, 2, 'Dá ordem aos filhos de Israel que da herança da sua possessão dêem aos levitas cidades em que habitem; também dareis aos levitas arrabaldes ao redor delas.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 3, 'Terão eles estas cidades para habitarem; e os arrabaldes delas serão para os seus gados, e para a sua fazenda, e para todos os seus animais.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 4, 'Os arrabaldes que dareis aos levitas se estenderão, do muro da cidade para fora, mil côvados em redor.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 5, 'E fora da cidade medireis para o lado oriental dois mil côvados, para o lado meridional dois mil côvados, para o lado ocidental dois mil côvados, e para o lado setentrional dois mil côvados; e a cidade estará no meio. Isso terão por arrabaldes das cidades.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 6, 'Entre as cidades que dareis aos levitas haverá seis cidades de refúgio, as quais dareis para que nelas se acolha o homicida; e além destas lhes dareis quarenta e duas cidades.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 7, 'Todas as cidades que dareis aos levitas serão quarenta e oito, juntamente com os seus arrabaldes.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 8, 'Ora, no tocante às cidades que dareis da possessão dos filhos de Israel, da tribo que for grande tomareis muitas, e da que for pequena tomareis poucas; cada uma segundo a herança que receber dará as suas cidades aos levitas.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 9, 'Disse mais o Senhor a Moisés:', 1, CURRENT_TIMESTAMP, false),
(4, 35, 10, 'Fala aos filhos de Israel, e dize-lhes: Quando passardes o Jordão para a terra de Canaã,', 1, CURRENT_TIMESTAMP, false),
(4, 35, 11, 'escolhereis para vós cidades que vos sirvam de cidades de refúgio, para que se refugie ali o homicida que tiver matado alguém involuntariamente.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 12, 'E estas cidades vos serão por refúgio do vingador, para que não morra o homicida antes de ser apresentado perante a congregação para julgamento.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 13, 'Serão seis as cidades que haveis de dar por cidades de refúgio para vós.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 14, 'Dareis três cidades aquém do Jordão, e três na terra de Canaã; cidades de refúgio serão.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 15, 'Estas seis cidades serão por refúgio aos filhos de Israel, ao estrangeiro, e ao peregrino no meio deles, para que se refugie ali todo aquele que tiver matado alguém involuntariamente.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 16, 'Mas se alguém ferir a outrem com instrumento de ferro de modo que venha a morrer, homicida é; e o homicida será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 17, 'Ou se o ferir com uma pedra na mão, que possa causar a morte, e ele morrer, homicida é; e o homicida será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 18, 'Ou se o ferir com instrumento de pau na mão, que possa causar a morte, e ele morrer, homicida é; será morto o homicida.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 19, 'O vingador do sangue matará ao homicida; ao encontrá-lo, o matará.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 20, 'Ou se alguém empurrar a outrem por ódio ou de emboscada lançar contra ele alguma coisa de modo que venha a morrer,', 1, CURRENT_TIMESTAMP, false),
(4, 35, 21, 'ou por inimizade o ferir com a mão de modo que venha a morrer, será morto aquele que o feriu; homicida é. O vingador do sangue, ao encontrá-lo, o matará.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 22, 'Mas se o empurrar acidentalmente, sem inimizade, ou contra ele lançar algum instrumento, sem ser de emboscada,', 1, CURRENT_TIMESTAMP, false),
(4, 35, 23, 'ou sobre ele atirar alguma pedra, não o vendo, e o ferir de modo que venha a morrer, sem que fosse seu inimigo nem procurasse o seu mal,', 1, CURRENT_TIMESTAMP, false),
(4, 35, 24, 'então a congregação julgará entre aquele que feriu e o vingador do sangue, segundo estas leis,', 1, CURRENT_TIMESTAMP, false),
(4, 35, 25, 'e a congregação livrará o homicida da mão do vingador do sangue, fazendo-o voltar à sua cidade de refúgio a que se acolhera; ali ficará ele morando até a morte do sumo sacerdote, que foi ungido com o óleo sagrado.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 26, 'Mas, se de algum modo o homicida sair dos limites da sua cidade de refúgio, onde se acolhera,', 1, CURRENT_TIMESTAMP, false),
(4, 35, 27, 'e o vingador do sangue o achar fora dos limites da sua cidade de refúgio, e o matar, não será culpado de sangue;', 1, CURRENT_TIMESTAMP, false),
(4, 35, 28, 'pois o homicida deverá ficar na sua cidade de refúgio até a morte do sumo sacerdote; mas depois da morte do sumo sacerdote o homicida voltará para a terra da sua possessão.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 29, 'Estas coisas vos serão por estatuto de direito pelas vossas gerações, em todos os lugares da vossa habitação.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 30, 'Todo aquele que matar alguém, será morto conforme o depoimento de testemunhas; mas uma só testemunha não deporá contra alguém, para condená-lo à morte.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 31, 'Não aceitareis resgate pela vida de um homicida que é réu de morte; porém ele certamente será morto.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 32, 'Também não aceitareis resgate por aquele que se tiver acolhido à sua cidade de refúgio, a fim de que ele possa tornar a habitar na terra antes da morte do sumo sacerdote.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 33, 'Assim não profanareis a terra da vossa habitação, porque o sangue profana a terra; e nenhuma expiação se poderá fazer pela terra por causa do sangue que nela for derramado, senão com o sangue daquele que o derramou.', 1, CURRENT_TIMESTAMP, false),
(4, 35, 34, 'Não contaminareis, pois, a terra em que haveis de habitar, no meio da qual eu também habitarei; pois eu, o Senhor, habito no meio dos filhos de Israel.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 1, 'Chegaram-se então os cabeças das casas paternas da família dos filhos de Gileade, filho de Maquir, filho de Manassés, das famílias dos filhos de José, e falaram diante de Moisés, e diante dos príncipes, cabeças das casas paternas dos filhos de Israel,', 1, CURRENT_TIMESTAMP, false),
(4, 36, 2, 'e disseram: O Senhor mandou a meu senhor que por sortes repartisse a terra em herança aos filhos de Israel; e meu senhor recebeu ordem do senhor de dar a herança do nosso irmão Zelofeade às filhas deste.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 3, 'E, se elas se casarem com os filhos das outras tribos de Israel, então a sua herança será diminuída da herança de nossos pais, e acrescentada à herança da tribo a que vierem a pertencer; assim será tirada da sorte da nossa herança.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 4, 'Vindo também o ano do jubileu dos filhos de Israel, a herança delas será acrescentada à herança da tribo a que pertencerem; assim a sua herança será tirada da herança da tribo de nossos pais.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 5, 'Então Moisés falou aos filhos de Israel, segundo a palavra do senhor, dizendo: A tribo dos filhos de José fala o que é justo.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 6, 'Isto é o que o senhor ordenou acerca das filhas de Zelofeade, dizendo: Casem com quem bem parecer aos seus olhos, contanto que se casem na família da tribo de seu pai.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 7, 'Assim a herança dos filhos de Israel não passará de tribo em tribo, pois os filhos de Israel se apegarão cada um a herança da tribo de seus pais.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 8, 'E toda filha que possuir herança em qualquer tribo dos filhos de Israel se casará com alguém da família da tribo de seu pai, para que os filhos de Israel possuam cada um a herança de seus pais.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 9, 'Assim nenhuma herança passará de uma tribo a outra, pois as tribos dos filhos de Israel se apegarão cada uma à sua herança.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 10, 'Como o Senhor ordenara a Moisés, assim fizeram as filhas de Zelofeade;', 1, CURRENT_TIMESTAMP, false),
(4, 36, 11, 'pois Macla, Tirza, Hogla, Milca e Noa, filhas de Zelofeade, se casaram com os filhos de seus tios paternos.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 12, 'Casaram-se nas famílias dos filhos de Manassés, filho de José; assim a sua herança permaneceu na tribo da família de seu pai.', 1, CURRENT_TIMESTAMP, false),
(4, 36, 13, 'São esses os mandamentos e os preceitos que o Senhor ordenou aos filhos de Israel por intermédio de Moisés nas planícies de Moabe, junto ao Jordão, na altura de Jericó.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 1, 'Visão de Obadias. Assim diz o Senhor Deus a respeito de Edom: Temos ouvido novas da parte do Senhor, e por entre as nações foi enviado um mensageiro a dizer: Levantai-vos, e levantemo-nos contra ela para a guerra.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 2, 'Eis que te farei pequeno entre as nações; serás muito desprezado.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 3, 'A soberba do teu coração te enganou, ó tu que habitas nas fendas do penhasco, na tua alta morada, que dizes no teu coração: Quem me derrubará em terra?', 1, CURRENT_TIMESTAMP, false),
(31, 1, 4, 'Embora subas ao alto como águia, e embora se ponha o teu ninho entre as estrelas, dali te derrubarei, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 5, 'Se a ti viessem ladrões, ou roubadores de noite {como estás destruído!}, não furtariam somente o que lhes bastasse? se a ti viessem os vindimadores, não deixariam umas uvas de rabisco?', 1, CURRENT_TIMESTAMP, false),
(31, 1, 6, 'Como foram rebuscados os bens de Esaú! como foram esquadrinhados os seus tesouros ocultos!', 1, CURRENT_TIMESTAMP, false),
(31, 1, 7, 'Todos os teus confederados te levaram para fora dos teus limites; os que estavam de paz contigo te enganaram, e prevaleceram contra ti; os que comem o teu pão põem debaixo de ti uma armadilha; não há em Edom entendimento.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 8, 'Acaso não acontecerá naquele dia, diz o Senhor, que farei perecer os sábios de Edom, e o entendimento do monte de Esaú?', 1, CURRENT_TIMESTAMP, false),
(31, 1, 9, 'E os teus valentes, ó Temã, estarão atemorizados, para que do monte de Esaú seja cada um exterminado pela matança.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 10, 'Por causa da violência feita a teu irmão Jacó, cobrir-te-á a confusão, e serás exterminado para sempre.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 11, 'No dia em que estiveste do lado oposto, no dia em que estranhos lhe levaram os bens, e os estrangeiros lhe entraram pelas portas e lançaram sortes sobre Jerusalém, tu mesmo eras como um deles.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 12, 'Mas tu não devias olhar com prazer para o dia de teu irmão no dia do seu desterro, nem alegrar-te sobre os filhos de Judá no dia da sua ruína, nem falar arrogantemente no dia da tribulação;', 1, CURRENT_TIMESTAMP, false),
(31, 1, 13, 'nem entrar pela porta do meu povo no dia da sua calamidade; sim, tu não devias olhar, satisfeito, para o seu mal, no dia da sua calamidade; nem lançar mão dos seus bens no dia da sua calamidade;', 1, CURRENT_TIMESTAMP, false),
(31, 1, 14, 'nem te postar nas encruzilhadas, para exterminares os que escapassem; nem entregar os que lhe restassem, no dia da tribulação.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 15, 'Porquanto o dia do Senhor está perto, sobre todas as nações, como tu fizeste, assim se fará contigo; o teu feito tornará sobre a tua cabeça.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 16, 'Pois como vós bebestes no meu santo monte, assim beberão de contínuo todas as nações; sim, beberão e sorverão, e serão como se nunca tivessem sido.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 17, 'Mas no monte de Sião haverá livramento, e ele será santo; e os da casa de Jacó possuirão as suas herdades.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 18, 'E a casa de Jacó será um fogo, e a casa de José uma chama, e a casa de Esaú restolho; aqueles se acenderão contra estes, e os consumirão; e ninguém mais restará da casa de Esaú; porque o Senhor o disse.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 19, 'Ora, os do Negebe possuirão o monte de Esaú, e os da planície, os filisteus; possuirão também os campos de Efraim, e os campos de Samária; e Benjamim possuirá a Gileade.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 20, 'Os cativos deste exército dos filhos de Israel possuirão os cananeus até Zarefate; e os cativos de Jerusalém, que estão em Sefarade, possuirão as cidades do Negebe.', 1, CURRENT_TIMESTAMP, false),
(31, 1, 21, 'Subirão salvadores ao monte de Sião para julgarem o monte de Esaú; e o reino será do Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 1, 'A palavra do Senhor, que veio a Oséias, filho de Beeri, nos dias de Uzias, Jotão, Acaz e Ezequias, reis de Judá, e nos dias de Jeroboão, filho de Joás, rei de Israel.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 2, 'Quando o Senhor falou no princípio por Oséias, disse o Senhor a Oséias: Vai, toma por esposa uma mulher de prostituições, e filhos de prostituição; porque a terra se prostituiu, apartando-se do Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 3, 'Ele se foi, pois, e tomou a Gomer, filha de Diblaim; e ela concebeu, e lhe deu um filho.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 4, 'E disse-lhe o Senhor: Põe-lhe o nome de Jizreel; porque daqui a pouco visitarei o sangue de Jizreel sobre a casa de Jeú, e farei cessar o reino da casa de Israel.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 5, 'E naquele dia quebrarei o arco de Israel no vale de Jizreel.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 6, 'E tornou ela a conceber, e deu à luz uma filha. E o Senhor disse a Oséias: Põe-lhe o nome de Lo-Ruama; porque não tornarei mais a compadecer-me da casa de Israel, nem a perdoar-lhe de maneira alguma.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 7, 'Mas da casa se Judá me compadecerei, e os salvarei pelo Senhor seu Deus, pois não os salvarei pelo arco, nem pela espada, nem pela guerra, nem pelos cavalos, nem pelos cavaleiros.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 8, 'Ora depois de haver desmamado a Lo-Ruama, concebeu e deu à luz um filho.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 9, 'E o Senhor disse: Põe-lhe o nome de Lo-Ami; porque vós não sois meu povo, nem sou eu vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 10, 'Todavia o número dos filhos de Israel será como a areia do mar, que não pode ser medida nem contada; e no lugar onde se lhes dizia: Vós não sois meu povo, se lhes dirá: Vós sois os filhos do Deus vivo.', 1, CURRENT_TIMESTAMP, false),
(28, 1, 11, 'E os filhos de Judá e os filhos de Israel juntos se congregarão, e constituirão sobre si uma só cabeça, e subirão da terra; pois grande será o dia de Jizreel.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 1, 'Dizei a vossos irmãos: Ami; e a vossas irmãs: Ruama.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 2, 'Contendei com vossa mãe, contendei; porque ela não é minha mulher, e eu não sou seu marido; para que ela afaste as suas prostituições da sua face e os seus adultérios de entre os seus seios;', 1, CURRENT_TIMESTAMP, false),
(28, 2, 3, 'para que eu não a deixe despida, e a ponha como no dia em que nasceu, e a faça como um deserto, e a torne como uma terra seca, e a mate à sede.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 4, 'Até de seus filhos não me compadecerei; porquanto são filhos de prostituições.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 5, 'porque sua mãe se prostituiu; aquela que os concebeu houve-se torpemente; porque diz: Irei após os meus amantes, que me dão o meu pão e a minha água, a minha lã e o meu linho, o meu óleo e as minhas bebidas.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 6, 'Portanto, eis que lhe cercarei o caminho com espinhos, e contra ela levantarei uma sebe, para que ela não ache as suas veredas.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 7, 'Ela irá em seguimento de seus amantes, mas não os alcançará; buscá-los-á, mas não os achará; então dirá: Irei, e voltarei a meu primeiro marido, porque melhor me ia então do que agora.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 8, 'Ora, ela não reconhece que fui eu o que lhe dei o grão, e o vinho, e o azeite, e que lhe multipliquei a prata e o ouro, que eles usaram para Baal.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 9, 'Portanto, tornarei a tirar o meu grão a seu tempo e o meu vinho no seu tempo determinado; e arrebatarei a minha lã e o meu linho, com que cobriam a sua nudez.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 10, 'E agora descobrirei a sua vileza diante dos olhos dos seus amantes, e ninguém a livrará da minha mão.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 11, 'Também farei cessar todo o seu gozo, as suas festas, as suas luas novas, e os seus sábados, e todas as suas assembléias solenes.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 12, 'E devastarei a sua vide e a sua figueira, de que ela diz: É esta a paga que me deram os meus amantes; eu, pois, farei delas um bosque, e as feras do campo as devorarão.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 13, 'Castigá-la-ei pelos dias dos baalins, nos quais elas lhes queimava incenso, e se adornava com as suas arrecadas e as suas jóias, e, indo atrás dos seus amantes, se esquecia de mim, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 14, 'Portanto, eis que eu a atrairei, e a levarei para o deserto, e lhe falarei ao coração.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 15, 'E lhe darei as suas vinhas dali, e o vale de Acor por porta de esperança; e ali responderá, como nos dias da sua mocidade, e como no dia em que subiu da terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 16, 'E naquele dia, diz o Senhor, ela me chamará meu marido; e não me chamará mais meu Baal.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 17, 'Pois da sua boca tirarei os nomes dos baalins, e não mais se fará menção desses nomes.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 18, 'Naquele dia farei por eles aliança com as feras do campo, e com as aves do céu, e com os répteis da terra; e da terra tirarei o arco, e a espada, e a guerra, e os farei deitar em segurança.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 19, 'E desposar-te-ei comigo para sempre; sim, desposar-te-ei comigo em justiça, e em juízo, e em amorável benignidade, e em misericórdias;', 1, CURRENT_TIMESTAMP, false),
(28, 2, 20, 'e desposar-te-ei comigo em fidelidade, e conhecerás ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 21, 'Naquele dia responderei, diz o Senhor; responderei aos céus, e estes responderão a terra;', 1, CURRENT_TIMESTAMP, false),
(28, 2, 22, 'a terra responderá ao trigo, e ao vinho, e ao azeite, e estes responderão a Jizreel.', 1, CURRENT_TIMESTAMP, false),
(28, 2, 23, 'E semeá-lo-ei para mim na terra, e compadecer-me-ei de Lo-Ruama; e a e Lo-Ami direi: Tu és meu povo; e ele dirá: Tu és o meu Deus.', 1, CURRENT_TIMESTAMP, false),
(28, 3, 1, 'Disse-me o Senhor: Vai outra vez, ama uma mulher, amada de seu amigo, e adúltera, como o Senhor ama os filhos de Israel, embora eles se desviem para outros deuses, e amem passas de uvas.', 1, CURRENT_TIMESTAMP, false),
(28, 3, 2, 'Assim eu comprei para mim tal mulher por quinze peças de prata, e um hômer e meio de cevada;', 1, CURRENT_TIMESTAMP, false),
(28, 3, 3, 'e lhe disse: Por muitos dias tu ficarás esperando por mim; não te prostituirás, nem serás mulher de outro homem; assim também eu esperarei por ti.', 1, CURRENT_TIMESTAMP, false),
(28, 3, 4, 'Pois os filhos de Israel ficarão por muitos dias sem rei, sem príncipe, sem sacrifício, sem coluna, e sem éfode ou terafins.', 1, CURRENT_TIMESTAMP, false),
(28, 3, 5, 'Depois tornarão os filhos de Israel, e buscarão ao Senhor, seu Deus, e a Davi, seu rei; e com temor chegarão nos últimos dias ao Senhor, e à sua bondade.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 1, 'Ouvi a palavra do Senhor, vós, filhos de Israel; pois o Senhor tem uma contenda com os habitantes da terra; porque na terra não há verdade, nem benignidade, nem conhecimento de Deus.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 2, 'Só prevalecem o perjurar, o mentir, o matar, o furtar, e o adulterar; há violências e homicídios sobre homicídios.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 3, 'Por isso a terra se lamenta, e todo o que nela mora desfalece, juntamente com os animais do campo e com as aves do céu; e até os peixes do mar perecem.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 4, 'Todavia ninguém contenda, ninguém repreenda; pois é contigo a minha contenda, ó sacerdote.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 5, 'Por isso tu tropeçarás de dia, e o profeta contigo tropeçará de noite; e destruirei a tua mãe.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 6, 'O meu povo está sendo destruído, porque lhe falta o conhecimento. Porquanto rejeitaste o conhecimento, também eu te rejeitarei, para que não sejas sacerdote diante de mim; visto que te esqueceste da lei do teu Deus, também eu me esquecerei de teus filhos.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 7, 'Quanto mais eles se multiplicaram tanto mais contra mim pecaram: eu mudarei a sua honra em vergonha.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 8, 'Alimentavam-se do pecado do meu povo, e de coração desejam a iniqüidade dele.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 9, 'Por isso, como é o povo, assim será o sacerdote; e castigá-lo-ei conforme os seus caminhos, e lhe darei a recompensa das suas obras.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 10, 'Comerão, mas não se fartarão; entregar-se-ão à luxúria, mas não se multiplicarão; porque deixaram de atentar para o Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 11, 'A incontinência, e o vinho, e o mosto tiram o entendimento.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 12, 'O meu povo consulta ao seu pau, e a sua vara lhe dá respostas, porque o espírito de luxúria os enganou, e eles, prostituindo-se, abandonam o seu Deus.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 13, 'Sacrificam sobre os cumes dos montes; e queimam incenso sobre os outeiros, debaixo do carvalho, do álamo, e do terebinto, porque é boa a sua sombra; por isso vossas filhas se prostituem, e as vossas noras adulteram.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 14, 'Eu não castigarei vossas filhas, quando se prostituem, nem vossas noras, quando adulteram; porque os homens mesmos com as prostitutas se desviam, e com as meretrizes sacrificam; pois o povo que não tem entendimento será transtornado.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 15, 'Ainda que tu, ó Israel, te queiras prostituir contudo não se faça culpado Judá; não venhais a Gilgal, e não subais a Bete-Ávem nem jureis, dizendo: Vive o Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 16, 'Porque como novilha obstinada se rebelou Israel; agora o Senhor os apascentará como a um cordeiro num lugar espaçoso.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 17, 'Efraim está entregue aos ídolos; deixa-o.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 18, 'Acabando eles de beber, lançam-se à luxúria; certamente os seus príncipes amam a vergonha.', 1, CURRENT_TIMESTAMP, false),
(28, 4, 19, 'Um vento os envolveu nas suas asas; e eles se envergonharão por causa dos seus sacrifícios.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 1, 'Ouvi isto, ó sacerdotes, e escutai, ó casa de Israel, e dai ouvidos, ó casa do rei; porque contra vós se dirige este juízo; pois que vos tornastes um laço para Mizpá, e uma rede estendida sobre o Tabor.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 2, 'Os revoltosos se aprofundaram na corrupção; mas eu os castigarei a todos eles.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 3, 'Eu conheço a Efraim, e Israel não se me esconde; porque agora te tens prostituído, ó Efraim, e Israel se contaminou.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 4, 'As suas ações não lhes permitem voltar para o seu Deus; porque o espírito da prostituição está no meio deles, e não conhecem ao Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 5, 'A soberba de Israel testifica contra eles; e Israel e Efraim cairão pela sua iniqüidade, e Judá cairá juntamente com eles.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 6, 'Eles irão com os seus rebanhos e com as suas manadas, para buscarem ao Senhor, mas não o acharão; ele se retirou deles.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 7, 'Aleivosamente se houveram contra o Senhor, porque geraram filhos estranhos; agora a festa da lua nova os consumirá, juntamente com as suas porções.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 8, 'Tocai a corneta em Gibeá, a trombeta em Ramá; soltai o alarma em Bete-Áven; após ti, ó Benjamim.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 9, 'Efraim será para assolação no dia do castigo: entre as tribos de Israel declaro o que é certo.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 10, 'Os príncipes de Judá são como os que removem os marcos; derramarei, pois, o meu furor sobre eles como água.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 11, 'Efraim está oprimido e quebrantado no juízo, porque foi do seu agrado andar após a vaidade.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 12, 'Portanto para Efraim serei como a traça e para a casa de Judá como a podridão.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 13, 'Quando Efraim viu a sua enfermidade, e Judá a sua chaga, recorreu Efraim à Assíria e enviou ao rei Jarebe; mas ele não pode curar-vos, nem sarar a vossa chaga.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 14, 'Pois para Efraim serei como um leão, e como um leão novo para a casa de Judá; eu, sim eu despedaçarei, e ir-me-ei embora; arrebatarei, e não haverá quem livre.', 1, CURRENT_TIMESTAMP, false),
(28, 5, 15, 'Irei, e voltarei para o meu lugar, até que se reconheçam culpados e busquem a minha face; estando eles aflitos, ansiosamente me buscarão.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 1, 'Vinde, e tornemos para o Senhor, porque ele despedaçou e nos sarará; fez a ferida, e no-la atará.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 2, 'Depois de dois dias nos ressuscitará: ao terceiro dia nos levantará, e viveremos diante dele.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 3, 'Conheçamos, e prossigamos em conhecer ao Senhor; a sua saída, como a alva, é certa; e ele a nós virá como a chuva, como a chuva serôdia que rega a terra.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 4, 'Que te farei, ó Efraim? que te farei, ó Judá? porque o vosso amor é como a nuvem da manhã, e como o orvalho que cedo passa.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 5, 'Por isso os abati pelos profetas; pela palavra da minha boca os matei; e os meus juízos a teu respeito sairão como a luz.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 6, 'Pois misericórdia quero, e não sacrifícios; e o conhecimento de Deus, mais do que os holocaustos.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 7, 'Eles, porém, como Adão, transgrediram o pacto; nisso eles se portaram aleivosamente contra mim.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 8, 'Gileade é cidade de malfeitores, está manchada de sangue.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 9, 'Como hordas de salteadores que espreitam alguém, assim é a companhia dos sacerdotes que matam no caminho para Siquém; sim, cometem a vilania.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 10, 'Vejo uma coisa horrenda na casa de Israel; ali está a prostituição de Efraim; Israel está contaminado.', 1, CURRENT_TIMESTAMP, false),
(28, 6, 11, 'Também para ti, ó Judá, está determinada uma ceifa. Ao querer eu trazer do cativeiro o meu povo,', 1, CURRENT_TIMESTAMP, false),
(28, 7, 1, 'ao querer eu sarar a Israel, descobrem-se a corrupção de Efraim e as maldades de Samária; porque praticam a falsidade; o ladrão entra, e a horda dos salteadores despoja por fora.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 2, 'Não consideram no seu coração que eu me lembro de toda a sua maldade; agora, pois, os cercam as suas obras; diante da minha face estão.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 3, 'Com a sua malícia alegram ao rei, e com as suas mentiras aos príncipes.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 4, 'Todos eles são adúlteros; são semelhantes ao forno aceso, cujo padeiro cessa de atear o fogo desde o amassar a massa até que seja levedada.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 5, 'E no dia do nosso rei os príncipes se tornaram doentes com a excitação do vinho; o rei estendeu a sua mão com escarnecedores.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 6, 'Pois têm preparado o coração como um forno, enquanto estão de espreita; toda a noite dorme a sua ira; pela manhã arde como fogo de chama.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 7, 'Eles estão todos quentes como um forno, e devoram os seus juízes; todos os seus reis caem; ninguém entre eles há que me invoque.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 8, 'Quanto a Efraim, ele se mistura com os povos; Efraim é um bolo que não foi virado.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 9, 'Estrangeiros lhe devoram a força, e ele não o sabe; também as cãs se espalham sobre ele, e não o sabe.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 10, 'E a soberba de Israel testifica contra ele; todavia, não voltam para o Senhor seu Deus, nem o buscam em tudo isso.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 11, 'Pois Efraim é como uma pomba, insensata, sem entendimento; invocam o Egito, vão para a Assíria.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 12, 'Quando forem, sobre eles estenderei a minha rede, e como aves do céu os farei descer; castigá-los-ei, conforme o que eles têm ouvido na sua congregação.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 13, 'Ai deles! porque se erraram de mim; destruição sobre eles! porque se rebelaram contra mim. Quisera eu remi-los, mas falam mentiras contra mim.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 14, 'Não clamam a mim de coração, mas uivam nas suas camas; para o trigo e para o mosto se ajuntam, mas contra mim se rebelam.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 15, 'Contudo fui eu que os ensinei, e lhes fortaleci os braços; entretanto maquinam o mal contra mim.', 1, CURRENT_TIMESTAMP, false),
(28, 7, 16, 'Eles voltam, mas não para o Altíssimo. Fizeram-se como um arco enganador; caem à espada os seus príncipes, por causa da insolência da sua língua; este será o seu escárnio na terra do Egito.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 1, 'Põe a trombeta à tua boca. Ele vem como águia contra a casa do Senhor; porque eles transgrediram o meu pacto, e se rebelaram contra a minha lei.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 2, 'E a mim clamam: Deus meu, nós, Israel, te conhecemos.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 3, 'Israel desprezou o bem; o inimigo persegui-lo-á.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 4, 'Eles fizeram reis, mas não por mim; constituíram príncipes, mas sem a minha aprovação; da sua prata e do seu ouro fizeram ídolos para si, para serem destruídos.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 5, 'O teu bezerro, ó Samária, é rejeitado; a minha ira se acendeu contra eles; até quando serão eles incapazes da inocência?', 1, CURRENT_TIMESTAMP, false),
(28, 8, 6, 'Pois isso procede de Israel; um artífice o fez, e não é Deus. Será desfeito em pedaços o bezerro de Samária', 1, CURRENT_TIMESTAMP, false),
(28, 8, 7, 'Porquanto semeiam o vento, hão de ceifar o turbilhão; não haverá seara, a erva não dará farinha; se a der, tragá-la-ão os estrangeiros.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 8, 'Israel foi devorado; agora está entre as nações como um vaso em que ninguém tem prazer.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 9, 'Porque subiram à Assíria, qual asno selvagem andando sozinho; mercou Efraim amores.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 10, 'Todavia, ainda que eles merquem entre as nações, eu as congregarei; já começaram a ser diminuídos por causa da carga do rei dos príncipes.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 11, 'Ainda que Efraim tem multiplicado altares, estes se lhe tornaram altares para pecar.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 12, 'Escrevi para ele miríades de coisas da minha lei; mas isso é para ele como coisa estranha.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 13, 'Quanto aos sacrifícios das minhas ofertas, eles sacrificam carne, e a comem; mas o Senhor não os aceita; agora se lembrará da iniqüidade deles, e punirá os seus pecados; eles voltarão para o Egito.', 1, CURRENT_TIMESTAMP, false),
(28, 8, 14, 'Pois Israel se esqueceu do seu Criador, e edificou palácios, e Judá multiplicou cidades fortificadas. Mas eu enviarei sobre as suas cidades um fogo que consumirá os seus castelos.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 1, 'Não te alegres, ó Israel, não exultes como os povos; pois te prostituíste, apartando-te do teu Deus; amaste a paga de meretriz sobre todas as eiras de trigo.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 2, 'A eira e o lagar não os manterão, e o vinho novo lhes faltará.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 3, 'Na terra do Senhor não permanecerão; mas Efraim tornará ao Egito, e na Assíria comerão comida imunda.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 4, 'Não derramarão libações de vinho ao Senhor, nem lhe agradarão com as suas ofertas. O pão deles será como pão de pranteadores; todos os que dele comerem serão imundos; pois o seu pão será somente para o seu apetite; não entrará na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 5, 'Que fareis vós no dia da solenidade, e no dia da festa do Senhor?', 1, CURRENT_TIMESTAMP, false),
(28, 9, 6, 'Porque, eis que eles se foram por causa da destruição, mas o Egito os recolherá, Mênfis os sepultará; as suas coisas preciosas de prata as urtigas as possuirão; espinhos crescerão nas suas tendas.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 7, 'Chegaram os dias da punição, chegaram os dias da retribuição; Israel o saberá; o profeta é um insensato, o homem possesso de espírito é um louco; por causa da abundância da tua iniqüidade e do teu grande ódio.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 8, 'O profeta é a sentinela de Efraim, o povo do meu Deus; contudo um laço de caçador de aves se acha em todos os seus caminhos, e inimizade na casa do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 9, 'Muito profundamente se corromperam, como nos dias de Gibeá; ele se lembrará das iniqüidades deles, e punirá os seus pecados.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 10, 'Achei a Israel como uvas no deserto, vi a vossos pais como a fruta temporã da figueira no seu princípio; mas eles foram para Baal-Peor, e se consagraram a essa coisa vergonhosa, e se tornaram abomináveis como aquilo que amaram.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 11, 'Quanto a Efraim, a sua glória como ave voará; não haverá nascimento, nem gravidez, nem concepção.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 12, 'Ainda que venham criar seus filhos, eu os privarei deles, para que não fique nenhum homem. Ai deles, quando deles eu me apartar!', 1, CURRENT_TIMESTAMP, false),
(28, 9, 13, 'Efraim, assim como vi a Tiro, está plantado num lugar aprazível; mas Efraim levará seus filhos ao matador.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 14, 'Dá-lhes, ó Senhor; mas que lhes darás? dá-lhes uma madre que aborte e seios ressecados.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 15, 'Toda a sua malícia se acha em Gilgal; pois ali é que lhes concebi ódio; por causa da maldade das suas obras lançá-los-ei fora de minha casa. Não os amarei mais; todos os seus príncipes são rebeldes.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 16, 'Efraim foi ferido, secou-se a sua raiz; eles não darão fruto; sim, ainda que gerem, eu matarei os frutos desejáveis do seu ventre.', 1, CURRENT_TIMESTAMP, false),
(28, 9, 17, 'O meu Deus os rejeitará, porque não o ouviram; e errantes andarão entre as nações.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 1, 'Israel é vide frondosa que dá o seu fruto; conforme a abundância do seu fruto, assim multiplicou os altares; conforme a prosperidade da terra, assim fizeram belas colunas.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 2, 'O seu coração está dividido, por isso serão culpados; ele derribará os altares deles, e lhes destruirá as colunas.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 3, 'Certamente agora dirão: Não temos rei, porque não tememos ao Senhor; e o rei, que pode ele fazer por nós?', 1, CURRENT_TIMESTAMP, false),
(28, 10, 4, 'Falam palavras vãs; juram falsamente, fazendo pactos; por isso brota o juízo como erva peçonhenta nos sulcos dos campos.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 5, 'Os moradores de Samária serão atemorizados por causa do bezerro de Bete-Áven. O seu povo se lamentará por causa dele, como também prantearão os seus sacerdotes idólatras por causa da sua glória, que se apartou dela.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 6, 'Também será ele levado para Assíria como um presente ao rei Jarebe; Efraim ficará confuso, e Israel se envergonhará por causa do seu próprio conselho.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 7, 'O rei de Samária será desfeito como a espuma sobre a face da água.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 8, 'E os altos de Áven, pecado de Israel, serão destruídos; espinhos e cardos crescerão sobre os seus altares; e dirão aos montes: Cobri-nos! e aos outeiros: Caí sobre nós!', 1, CURRENT_TIMESTAMP, false),
(28, 10, 9, 'Desde os dias de Gibeá tens pecado, ó Israel; ali permaneceram; a peleja contra os filhos da iniqüidade não os alcançará em Gibeá.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 10, 'Quando eu quiser, castigá-los-ei; e os povos se congregarão contra eles, quando forem castigados pela sua dupla transgressão.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 11, 'Porque Efraim era uma novilha domada, que gostava de trilhar; e eu poupava a formosura do seu pescoço; mas porei arreios sobre Efraim; Judá lavrará; Jacó desfará os torrões.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 12, 'Semeai para vós em justiça, colhei segundo a misericórdia; lavrai o campo alqueivado; porque é tempo de buscar ao Senhor, até que venha e chova a justiça sobre vós.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 13, 'Lavrastes a impiedade, segastes a iniqüidade, e comestes o fruto da mentira; porque confiaste no teu caminho, na multidão dos teus valentes.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 14, 'Portanto, entre o teu povo se levantará tumulto de guerra, e todas as tuas fortalezas serão destruídas, como Salmã destruiu a Bete-Arbel no dia da batalha; a mãe ali foi despedaçada juntamente com os filhos.', 1, CURRENT_TIMESTAMP, false),
(28, 10, 15, 'Assim vos fará Betel, por causa da vossa grande malícia; de madrugada será o rei de Israel totalmente destruído.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 1, 'Quando Israel era menino, eu o amei, e do Egito chamei a meu filho.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 2, 'Quanto mais eu os chamava, tanto mais se afastavam de mim; sacrificavam aos baalins, e queimavam incenso às imagens esculpidas.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 3, 'Todavia, eu ensinei aos de Efraim a andar; tomei-os nos meus braços; mas não entendiam que eu os curava.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 4, 'Atraí-os com cordas humanas, com laços de amor; e fui para eles como os que tiram o jugo de sobre as suas queixadas, e me inclinei para lhes dar de comer.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 5, 'Não voltarão para a terra do Egito; mas a Assíria será seu rei; porque recusam converter-se.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 6, 'Cairá a espada sobre as suas cidades, e consumirá os seus ferrolhos; e os devorará nas suas fortalezas.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 7, 'Porque o meu povo é inclinado a desviar-se de mim; ainda que clamem ao Altíssimo, nenhum deles o exalta.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 8, 'Como te deixaria, ó Efraim? como te entregaria, ó Israel? como te faria como Admá? ou como Zeboim? Está comovido em mim o meu coração, as minhas compaixões à uma se acendem.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 9, 'Não executarei o furor da minha ira; não voltarei para destruir a Efraim, porque eu sou Deus e não homem, o Santo no meio de ti; eu não virei com ira.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 10, 'Andarão após o Senhor; ele bramará como leão; e, bramando ele, os filhos, tremendo, virão do ocidente.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 11, 'Também, tremendo, virão como um passarinho os do Egito, e como uma pomba os da terra da Assíria; e os farei habitar em suas casas, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(28, 11, 12, 'Efraim me cercou com mentira, e a casa de Israel com engano; mas Judá ainda domina com Deus, e com o Santo está fiel.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 1, 'Efraim apascenta o vento, segue o vento oriental todo o dia; multiplica a mentira e a destruição; e fazem aliança com a Assíria, e o azeite se leva ao Egito', 1, CURRENT_TIMESTAMP, false),
(28, 12, 2, 'O Senhor também com Judá tem contenda, e castigará a Jacó segundo os seus caminhos; segundo as suas obras o recompensará.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 3, 'No ventre pegou do calcanhar de seu irmão; e na sua idade varonil lutou com Deus.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 4, 'Lutou com o anjo, e prevaleceu; chorou, e lhe fez súplicas. Em Betel o achou, e ali falou Deus com ele;', 1, CURRENT_TIMESTAMP, false),
(28, 12, 5, 'sim, o Senhor, o Deus dos exércitos; o Senhor e o seu nome.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 6, 'Tu, pois, converte-te a teu Deus; guarda a benevolência e a justiça, e em teu Deus espera sempre.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 7, 'Quanto a Canaã, tem nas mãos balança enganadora; ama a opressão.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 8, 'Diz Efraim: Certamente eu me tenho enriquecido, tenho adquirido para mim grandes bens; em todo o meu trabalho não acharão em mim iniqüidade alguma que seja pecado.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 9, 'Mas eu sou o Senhor teu Deus, desde a terra do Egito; eu ainda te farei habitar de novo em tendas, como nos dias da festa solene.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 10, 'Também falei aos profetas, e multipliquei as visões; e pelo ministério dos profetas usei de parábolas.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 11, 'Não é Gileade iniqüidade? pura vaidade são eles. Em Gilgal sacrificam bois; os seus altares são como montões de pedras nos sulcos dos campos.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 12, 'Jacó fugiu para o campo de Arã, e Israel serviu por uma mulher, sim, por uma mulher guardou o gado.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 13, 'Mas o Senhor por meio dum profeta fez subir a Israel do Egito, e por um profeta foi ele preservado.', 1, CURRENT_TIMESTAMP, false),
(28, 12, 14, 'Efraim mui amargamente provocou-lhe a ira; portanto sobre ele será deixado o seu sangue, e o seu Senhor fará cair sobre ele o seu opróbrio.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 1, 'Quando Efraim falava, tremia-se; foi exaltado em Israel; mas quando ele se fez culpado no tocante a Baal, morreu.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 2, 'E agora pecam mais e mais, e da sua prata fazem imagens fundidas, ídolos segundo o seu entendimento, todos eles obra de artífices, e dizem: Oferecei sacrifícios a estes. Homens beijam aos bezerros!', 1, CURRENT_TIMESTAMP, false),
(28, 13, 3, 'Por isso serão como a nuvem de manhã, e como o orvalho que cedo passa; como a palha que se lança fora da eira, e como a fumaça que sai pela janela.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 4, 'Todavia, eu sou o Senhor teu Deus desde a terra do Egito; portanto não conhecerás outro deus além de mim, porque não há salvador senão eu.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 5, 'Eu te conheci no deserto, em terra muito seca.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 6, 'Depois eles se fartaram em proporção do seu pasto; e estando fartos, ensoberbeceu-se-lhes o coração, por isso esqueceram de mim.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 7, 'Portanto serei para eles como leão; como leopardo espreitarei junto ao caminho;', 1, CURRENT_TIMESTAMP, false),
(28, 13, 8, 'Como ursa roubada dos seus cachorros lhes sairei ao encontro, e lhes romperei as teias do coração; e ali os devorarei como leoa; as feras do campo os despedaçarão.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 9, 'Destruir-te-ei, ó Israel; quem te pode socorrer?', 1, CURRENT_TIMESTAMP, false),
(28, 13, 10, 'Onde está agora o teu rei, para que te salve em todas as tuas cidades? e os teus juízes, dos quais disseste: Dá-me rei e príncipes?', 1, CURRENT_TIMESTAMP, false),
(28, 13, 11, 'Dei-te um rei na minha ira, e tirei-o no meu furor.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 12, 'A iniqüidade de Efraim está atada, o seu pecado está armazenado.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 13, 'Dores de mulher de parto lhe sobrevirão; ele é filho insensato; porque é tempo e não está no lugar em que deve vir à luz.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 14, 'Eu os remirei do poder do Seol, e os resgatarei da morte. Onde estão, ó morte, as tuas pragas? Onde está, ó Seol, a tua destruição? A compaixão está escondida de meus olhos.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 15, 'Ainda que ele dê fruto entre os seus irmãos, virá o vento oriental, vento do Senhor, subindo do deserto, e secar-se-á a sua nascente, e se estancará a sua fonte; ele saqueará o tesouro de todos os vasos desejáveis.', 1, CURRENT_TIMESTAMP, false),
(28, 13, 16, 'Samária levará sobre si a sua culpa, porque se rebelou contra o seu Deus; cairá à espada; seus filhinhos serão despedaçados, e as suas mulheres grávidas serão fendidas.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 1, 'Volta, ó Israel, para o Senhor teu Deus; porque pela tua iniqüidade tens caído.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 2, 'Tomai convosco palavras, e voltai para o Senhor; dizei-lhe: Tira toda a iniqüidade, e aceita o que é bom; e ofereceremos como novilhos os sacrifícios dos nossos lábios.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 3, 'Não nos salvará a Assíria, não iremos montados em cavalos; e à obra das nossas mãos já não diremos: Tu és o nosso Deus; porque em ti o órfão acha a misericórdia.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 4, 'Eu sararei a sua apostasia, eu voluntariamente os amarei; porque a minha ira se apartou deles.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 5, 'Eu serei para Israel como o orvalho; ele florescerá como o lírio, e lançará as suas raízes como o Líbano.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 6, 'Estender-se-ão as suas vergônteas, e a sua formosura será como a da oliveira, a sua fragrância como a do Líbano.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 7, 'Voltarão os que habitam à sua sombra; reverdecerão como o trigo, e florescerão como a vide; o seu renome será como o do vinho do Líbano.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 8, 'Ó Efraim, que tenho eu com os ídolos? Sou eu que respondo, e cuido de ti. Eu sou como a faia verde; de mim é achado o teu fruto.', 1, CURRENT_TIMESTAMP, false),
(28, 14, 9, 'Quem é sábio, para que entenda estas coisas? prudente, para que as saiba? porque os caminhos do Senhor são retos, e os justos andarão neles; mas os transgressores neles cairão.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 1, 'Paulo, servo de Jesus Cristo, chamado para ser apóstolo, separado para o evangelho de Deus,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 2, 'que ele antes havia prometido pelos seus profetas nas santas Escrituras,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 3, 'acerca de seu Filho, que nasceu da descendência de Davi segundo a carne,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 4, 'e que com poder foi declarado Filho de Deus segundo o espírito de santidade, pela ressurreição dentre os mortos-Jesus Cristo nosso Senhor,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 5, 'pelo qual recebemos a graça e o apostolado, por amor do seu nome, para a obediência da fé entre todos os gentios,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 6, 'entre os quais sois também vós chamados para serdes de Jesus Cristo;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 7, 'a todos os que estais em Roma, amados de Deus, chamados para serdes santos: Graça a vós, e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 8, 'Primeiramente dou graças ao meu Deus, mediante Jesus Cristo, por todos vós, porque em todo o mundo é anunciada a vossa fé.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 9, 'Pois Deus, a quem sirvo em meu espírito, no evangelho de seu Filho, me é testemunha de como incessantemente faço menção de vós,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 10, 'pedindo sempre em minhas orações que, afinal, pela vontade de Deus, se me ofereça boa ocasião para ir ter convosco.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 11, 'Porque desejo muito ver-vos, para vos comunicar algum dom espiritual, a fim de que sejais fortalecidos;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 12, 'isto é, para que juntamente convosco eu seja consolado em vós pela fé mútua, vossa e minha.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 13, 'E não quero que ignoreis, irmãos, que muitas vezes propus visitar-vos {mas até agora tenho sido impedido}, para conseguir algum fruto entre vós, como também entre os demais gentios.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 14, 'Eu sou devedor, tanto a gregos como a bárbaros, tanto a sábios como a ignorantes.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 15, 'De modo que, quanto está em mim, estou pronto para anunciar o evangelho também a vós que estais em Roma.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 16, 'Porque não me envergonho do evangelho, pois é o poder de Deus para salvação de todo aquele que crê; primeiro do judeu, e também do grego.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 17, 'Porque no evangelho é revelada, de fé em fé, a justiça de Deus, como está escrito: Mas o justo viverá da fé.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 18, 'Pois do céu é revelada a ira de Deus contra toda a impiedade e injustiça dos homens que detêm a verdade em injustiça.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 19, 'Porquanto, o que de Deus se pode conhecer, neles se manifesta, porque Deus lho manifestou.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 20, 'Pois os seus atributos invisíveis, o seu eterno poder e divindade, são claramente vistos desde a criação do mundo, sendo percebidos mediante as coisas criadas, de modo que eles são inescusáveis;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 21, 'porquanto, tendo conhecido a Deus, contudo não o glorificaram como Deus, nem lhe deram graças, antes nas suas especulações se desvaneceram, e o seu coração insensato se obscureceu.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 22, 'Dizendo-se sábios, tornaram-se estultos,', 1, CURRENT_TIMESTAMP, false),
(45, 1, 23, 'e mudaram a glória do Deus incorruptível em semelhança da imagem de homem corruptível, e de aves, e de quadrúpedes, e de répteis.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 24, 'Por isso Deus os entregou, nas concupiscências de seus corações, à imundícia, para serem os seus corpos desonrados entre si;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 25, 'pois trocaram a verdade de Deus pela mentira, e adoraram e serviram à criatura antes que ao Criador, que é bendito eternamente. Amém.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 26, 'Pelo que Deus os entregou a paixões infames. Porque até as suas mulheres mudaram o uso natural no que é contrário à natureza;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 27, 'semelhantemente, também os varões, deixando o uso natural da mulher, se inflamaram em sua sensualidade uns para como os outros, varão com varão, cometendo torpeza e recebendo em si mesmos a devida recompensa do seu erro.', 1, CURRENT_TIMESTAMP, false),
(45, 1, 28, 'E assim como eles rejeitaram o conhecimento de Deus, Deus, por sua vez, os entregou a um sentimento depravado, para fazerem coisas que não convêm;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 29, 'estando cheios de toda a injustiça, malícia, cobiça, maldade; cheios de inveja, homicídio, contenda, dolo, malignidade;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 30, 'sendo murmuradores, detratores, aborrecedores de Deus, injuriadores, soberbos, presunçosos, inventores de males, desobedientes ao pais;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 31, 'néscios, infiéis nos contratos, sem afeição natural, sem misericórdia;', 1, CURRENT_TIMESTAMP, false),
(45, 1, 32, 'os quais, conhecendo bem o decreto de Deus, que declara dignos de morte os que tais coisas praticam, não somente as fazem, mas também aprovam os que as praticam.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 1, 'Portanto, és inescusável, ó homem, qualquer que sejas, quando julgas, porque te condenas a ti mesmo naquilo em que julgas a outro; pois tu que julgas, praticas o mesmo.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 2, 'E bem sabemos que o juízo de Deus é segundo a verdade, contra os que tais coisas praticam.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 3, 'E tu, ó homem, que julgas os que praticam tais coisas, cuidas que, fazendo-as tu, escaparás ao juízo de Deus?', 1, CURRENT_TIMESTAMP, false),
(45, 2, 4, 'Ou desprezas tu as riquezas da sua benignidade, e paciência e longanimidade, ignorando que a benignidade de Deus te conduz ao arrependimento?', 1, CURRENT_TIMESTAMP, false),
(45, 2, 5, 'Mas, segundo a tua dureza e teu coração impenitente, entesouras ira para ti no dia da ira e da revelação do justo juízo de Deus,', 1, CURRENT_TIMESTAMP, false),
(45, 2, 6, 'que retribuirá a cada um segundo as suas obras;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 7, 'a saber: a vida eterna aos que, com perseverança em favor o bem, procuram glória, e honra e incorrupção;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 8, 'mas ira e indignação aos que são contenciosos, e desobedientes à iniqüidade;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 9, 'tribulação e angústia sobre a alma de todo homem que pratica o mal, primeiramente do judeu, e também do grego;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 10, 'glória, porém, e honra e paz a todo aquele que pratica o bem, primeiramente ao judeu, e também ao grego;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 11, 'pois para com Deus não há acepção de pessoas.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 12, 'Porque todos os que sem lei pecaram, sem lei também perecerão; e todos os que sob a lei pecaram, pela lei serão julgados.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 13, 'Pois não são justos diante de Deus os que só ouvem a lei; mas serão justificados os que praticam a lei', 1, CURRENT_TIMESTAMP, false),
(45, 2, 14, '{porque, quando os gentios, que não têm lei, fazem por natureza as coisas da lei, eles, embora não tendo lei, para si mesmos são lei.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 15, 'pois mostram a obra da lei escrita em seus corações, testificando juntamente a sua consciência e os seus pensamentos, quer acusando-os, quer defendendo-os},', 1, CURRENT_TIMESTAMP, false),
(45, 2, 16, 'no dia em que Deus há de julgar os segredos dos homens, por Cristo Jesus, segundo o meu evangelho.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 17, 'Mas se tu és chamado judeu, e repousas na lei, e te glorias em Deus;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 18, 'e conheces a sua vontade e aprovas as coisas excelentes, sendo instruído na lei;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 19, 'e confias que és guia dos cegos, luz dos que estão em trevas,', 1, CURRENT_TIMESTAMP, false),
(45, 2, 20, 'instruidor dos néscios, mestre de crianças, que tens na lei a forma da ciência e da verdade;', 1, CURRENT_TIMESTAMP, false),
(45, 2, 21, 'tu, pois, que ensinas a outrem, não te ensinas a ti mesmo? Tu, que pregas que não se deve furtar, furtas?', 1, CURRENT_TIMESTAMP, false),
(45, 2, 22, 'Tu, que dizes que não se deve cometer adultério, adulteras? Tu, que abominas os ídolos, roubas os templos?', 1, CURRENT_TIMESTAMP, false),
(45, 2, 23, 'Tu, que te glorias na lei, desonras a Deus pela transgressão da lei?', 1, CURRENT_TIMESTAMP, false),
(45, 2, 24, 'Assim pois, por vossa causa, o nome de Deus é blasfemado entre os gentios, como está escrito.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 25, 'Porque a circuncisão é, na verdade, proveitosa, se guardares a lei; mas se tu és transgressor da lei, a tua circuncisão tem-se tornado em incircuncisão.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 26, 'Se, pois, a incircuncisão guardar os preceitos da lei, porventura a incircuncisão não será reputada como circuncisão?', 1, CURRENT_TIMESTAMP, false),
(45, 2, 27, 'E a incircuncisão que por natureza o é, se cumpre a lei, julgará a ti, que com a letra e a circuncisão és transgressor da lei.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 28, 'Porque não é judeu o que o é exteriormente, nem é circuncisão a que o é exteriormente na carne.', 1, CURRENT_TIMESTAMP, false),
(45, 2, 29, 'Mas é judeu aquele que o é interiormente, e circuncisão é a do coração, no espírito, e não na letra; cujo louvor não provém dos homens, mas de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 1, 'Que vantagem, pois, tem o judeu? ou qual a utilidade da circuncisão?', 1, CURRENT_TIMESTAMP, false),
(45, 3, 2, 'Muita, em todo sentido; primeiramente, porque lhe foram confiados os oráculos de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 3, 'Pois quê? Se alguns foram infiéis, porventura a sua infidelidade anulará a fidelidade de Deus?', 1, CURRENT_TIMESTAMP, false),
(45, 3, 4, 'De modo nenhum; antes seja Deus verdadeiro, e todo homem mentiroso; como está escrito: Para que sejas justificado em tuas palavras, e venças quando fores julgado.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 5, 'E, se a nossa injustiça prova a justiça de Deus, que diremos? Acaso Deus, que castiga com ira, é injusto? {Falo como homem.}', 1, CURRENT_TIMESTAMP, false),
(45, 3, 6, 'De modo nenhum; do contrário, como julgará Deus o mundo?', 1, CURRENT_TIMESTAMP, false),
(45, 3, 7, 'Mas, se pela minha mentira abundou mais a verdade de Deus para sua glória, por que sou eu ainda julgado como pecador?', 1, CURRENT_TIMESTAMP, false),
(45, 3, 8, 'E por que não dizemos: Façamos o mal para que venha o bem?-como alguns caluniosamente afirmam que dizemos; a condenação dos quais é justa.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 9, 'Pois quê? Somos melhores do que eles? De maneira nenhuma, pois já demonstramos que, tanto judeus como gregos, todos estão debaixo do pecado;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 10, 'como está escrito: Não há justo, nem sequer um.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 11, 'Não há quem entenda; não há quem busque a Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 12, 'Todos se extraviaram; juntamente se fizeram inúteis. Não há quem faça o bem, não há nem um só.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 13, 'A sua garganta é um sepulcro aberto; com as suas línguas tratam enganosamente; peçonha de áspides está debaixo dos seus lábios;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 14, 'a sua boca está cheia de maldição e amargura.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 15, 'Os seus pés são ligeiros para derramar sangue.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 16, 'Nos seus caminhos há destruição e miséria;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 17, 'e não conheceram o caminho da paz.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 18, 'Não há temor de Deus diante dos seus olhos.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 19, 'Ora, nós sabemos que tudo o que a lei diz, aos que estão debaixo da lei o diz, para que se cale toda boca e todo o mundo fique sujeito ao juízo de Deus;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 20, 'porquanto pelas obras da lei nenhum homem será justificado diante dele; pois o que vem pela lei é o pleno conhecimento do pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 21, 'Mas agora, sem lei, tem-se manifestado a justiça de Deus, que é atestada pela lei e pelos profetas;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 22, 'isto é, a justiça de Deus pela fé em Jesus Cristo para todos os que crêem; pois não há distinção.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 23, 'Porque todos pecaram e destituídos estão da glória de Deus;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 24, 'sendo justificados gratuitamente pela sua graça, mediante a redenção que há em Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(45, 3, 25, 'ao qual Deus propôs como propiciação, pela fé, no seu sangue, para demonstração da sua justiça por ter ele na sua paciência, deixado de lado os delitos outrora cometidos;', 1, CURRENT_TIMESTAMP, false),
(45, 3, 26, 'para demonstração da sua justiça neste tempo presente, para que ele seja justo e também justificador daquele que tem fé em Jesus.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 27, 'Onde está logo a jactância? Foi excluída. Por que lei? Das obras? Não; mas pela lei da fé.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 28, 'concluímos pois que o homem é justificado pela fé sem as obras da lei.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 29, 'É porventura Deus somente dos judeus? Não é também dos gentios? Também dos gentios, certamente,', 1, CURRENT_TIMESTAMP, false),
(45, 3, 30, 'se é que Deus é um só, que pela fé há de justificar a circuncisão, e também por meio da fé a incircuncisão.', 1, CURRENT_TIMESTAMP, false),
(45, 3, 31, 'Anulamos, pois, a lei pela fé? De modo nenhum; antes estabelecemos a lei.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 1, 'Que diremos, pois, ter alcançado Abraão, nosso pai segundo a carne?', 1, CURRENT_TIMESTAMP, false),
(45, 4, 2, 'Porque, se Abraão foi justificado pelas obras, tem de que se gloriar, mas não diante de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 3, 'Pois, que diz a Escritura? Creu Abraão a Deus, e isso lhe foi imputado como justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 4, 'Ora, ao que trabalha não se lhe conta a recompensa como dádiva, mas sim como dívida;', 1, CURRENT_TIMESTAMP, false),
(45, 4, 5, 'porém ao que não trabalha, mas crê naquele que justifica o ímpio, a sua fé lhe é contada como justiça;', 1, CURRENT_TIMESTAMP, false),
(45, 4, 6, 'assim também Davi declara bem-aventurado o homem a quem Deus atribui a justiça sem as obras, dizendo:', 1, CURRENT_TIMESTAMP, false),
(45, 4, 7, 'Bem-aventurados aqueles cujas iniqüidades são perdoadas, e cujos pecados são cobertos.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 8, 'Bem-aventurado o homem a quem o Senhor não imputará o pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 9, 'Vem, pois, esta bem-aventurança sobre a circuncisão somente, ou também sobre a incircuncisão? Porque dizemos: A Abraão foi imputada a fé como justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 10, 'Como, pois, lhe foi imputada? Estando na circuncisão, ou na incircuncisão? Não na circuncisão, mas sim na incircuncisão.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 11, 'E recebeu o sinal da circuncisão, selo da justiça da fé que teve quando ainda não era circuncidado, para que fosse pai de todos os que crêem, estando eles na incircuncisão, a fim de que a justiça lhes seja imputada,', 1, CURRENT_TIMESTAMP, false),
(45, 4, 12, 'bem como fosse pai dos circuncisos, dos que não somente são da circuncisão, mas também andam nas pisadas daquela fé que teve nosso pai Abraão, antes de ser circuncidado.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 13, 'Porque não foi pela lei que veio a Abraão, ou à sua descendência, a promessa de que havia de ser herdeiro do mundo, mas pela justiça da fé.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 14, 'Pois, se os que são da lei são herdeiros, logo a fé é vã e a promessa é anulada.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 15, 'Porque a lei opera a ira; mas onde não há lei também não há transgressão.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 16, 'Porquanto procede da fé o ser herdeiro, para que seja segundo a graça, a fim de que a promessa seja firme a toda a descendência, não somente à que é da lei, mas também à que é da fé que teve Abraão, o qual é pai de todos nós.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 17, '{como está escrito: Por pai de muitas nações te constituí} perante aquele no qual creu, a saber, Deus, que vivifica os mortos, e chama as coisas que não são, como se já fossem.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 18, 'O qual, em esperança, creu contra a esperança, para que se tornasse pai de muitas nações, conforme o que lhe fora dito: Assim será a tua descendência;', 1, CURRENT_TIMESTAMP, false),
(45, 4, 19, 'e sem se enfraquecer na fé, considerou o seu próprio corpo já amortecido {pois tinha quase cem anos}, e o amortecimento do ventre de Sara;', 1, CURRENT_TIMESTAMP, false),
(45, 4, 20, 'contudo, à vista da promessa de Deus, não vacilou por incredulidade, antes foi fortalecido na fé, dando glória a Deus,', 1, CURRENT_TIMESTAMP, false),
(45, 4, 21, 'e estando certíssimo de que o que Deus tinha prometido, também era poderoso para o fazer.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 22, 'Pelo que também isso lhe foi imputado como justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 4, 23, 'Ora, não é só por causa dele que está escrito que lhe foi imputado;', 1, CURRENT_TIMESTAMP, false),
(45, 4, 24, 'mas também por causa de nós a quem há de ser imputado, a nós os que cremos naquele que dos mortos ressuscitou a Jesus nosso Senhor;', 1, CURRENT_TIMESTAMP, false),
(45, 4, 25, 'o qual foi entregue por causa das nossas transgressões, e ressuscitado para a nossa justificação.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 1, 'Justificados, pois, pela fé, tenhamos paz com Deus, por nosso Senhor Jesus Cristo,', 1, CURRENT_TIMESTAMP, false),
(45, 5, 2, 'por quem obtivemos também nosso acesso pela fé a esta graça, na qual estamos firmes, e gloriemo-nos na esperança da glória de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 3, 'E não somente isso, mas também gloriemo-nos nas tribulações; sabendo que a tribulação produz a perseverança,', 1, CURRENT_TIMESTAMP, false),
(45, 5, 4, 'e a perseverança a experiência, e a experiência a esperança;', 1, CURRENT_TIMESTAMP, false),
(45, 5, 5, 'e a esperança não desaponta, porquanto o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 6, 'Pois, quando ainda éramos fracos, Cristo morreu a seu tempo pelos ímpios.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 7, 'Porque dificilmente haverá quem morra por um justo; pois poderá ser que pelo homem bondoso alguém ouse morrer.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 8, 'Mas Deus dá prova do seu amor para conosco, em que, quando éramos ainda pecadores, Cristo morreu por nós.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 9, 'Logo muito mais, sendo agora justificados pelo seu sangue, seremos por ele salvos da ira.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 10, 'Porque se nós, quando éramos inimigos, fomos reconciliados com Deus pela morte de seu Filho, muito mais, estando já reconciliados, seremos salvos pela sua vida.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 11, 'E não somente isso, mas também nos gloriamos em Deus por nosso Senhor Jesus Cristo, pelo qual agora temos recebido a reconciliação.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 12, 'Portanto, assim como por um só homem entrou o pecado no mundo, e pelo pecado a morte, assim também a morte passou a todos os homens, porquanto todos pecaram.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 13, 'Porque antes da lei já estava o pecado no mundo, mas onde não há lei o pecado não é levado em conta.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 14, 'No entanto a morte reinou desde Adão até Moisés, mesmo sobre aqueles que não pecaram à semelhança da transgressão de Adão o qual é figura daquele que havia de vir.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 15, 'Mas não é assim o dom gratuito como a ofensa; porque, se pela ofensa de um morreram muitos, muito mais a graça de Deus, e o dom pela graça de um só homem, Jesus Cristo, abundou para com muitos.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 16, 'Também não é assim o dom como a ofensa, que veio por um só que pecou; porque o juízo veio, na verdade, de uma só ofensa para condenação, mas o dom gratuito veio de muitas ofensas para justificação.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 17, 'Porque, se pela ofensa de um só, a morte veio a reinar por esse, muito mais os que recebem a abundância da graça, e do dom da justiça, reinarão em vida por um só, Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 18, 'Portanto, assim como por uma só ofensa veio o juízo sobre todos os homens para condenação, assim também por um só ato de justiça veio a graça sobre todos os homens para justificação e vida.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 19, 'Porque, assim como pela desobediência de um só homem muitos foram constituídos pecadores, assim também pela obediência de um muitos serão constituídos justos.', 1, CURRENT_TIMESTAMP, false),
(45, 5, 20, 'Sobreveio, porém, a lei para que a ofensa abundasse; mas, onde o pecado abundou, superabundou a graça;', 1, CURRENT_TIMESTAMP, false),
(45, 5, 21, 'para que, assim como o pecado veio a reinar na morte, assim também viesse a reinar a graça pela justiça para a vida eterna, por Jesus Cristo nosso Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 1, 'Que diremos, pois? Permaneceremos no pecado, para que abunde a graça?', 1, CURRENT_TIMESTAMP, false),
(45, 6, 2, 'De modo nenhum. Nós, que já morremos para o pecado, como viveremos ainda nele?', 1, CURRENT_TIMESTAMP, false),
(45, 6, 3, 'Ou, porventura, ignorais que todos quantos fomos batizados em Cristo Jesus fomos batizados na sua morte?', 1, CURRENT_TIMESTAMP, false),
(45, 6, 4, 'Fomos, pois, sepultados com ele pelo batismo na morte, para que, como Cristo foi ressuscitado dentre os mortos pela glória do Pai, assim andemos nós também em novidade de vida.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 5, 'Porque, se temos sido unidos a ele na semelhança da sua morte, certamente também o seremos na semelhança da sua ressurreição;', 1, CURRENT_TIMESTAMP, false),
(45, 6, 6, 'sabendo isto, que o nosso homem velho foi crucificado com ele, para que o corpo do pecado fosse desfeito, a fim de não servirmos mais ao pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 7, 'Pois quem está morto está justificado do pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 8, 'Ora, se já morremos com Cristo, cremos que também com ele viveremos,', 1, CURRENT_TIMESTAMP, false),
(45, 6, 9, 'sabendo que, tendo Cristo ressurgido dentre os mortos, já não morre mais; a morte não mais tem domínio sobre ele.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 10, 'Pois quanto a ter morrido, de uma vez por todas morreu para o pecado, mas quanto a viver, vive para Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 11, 'Assim também vós considerai-vos como mortos para o pecado, mas vivos para Deus, em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 12, 'Não reine, portanto, o pecado em vosso corpo mortal, para obedecerdes às suas concupiscências;', 1, CURRENT_TIMESTAMP, false),
(45, 6, 13, 'nem tampouco apresenteis os vossos membros ao pecado como instrumentos de iniqüidade; mas apresentai-vos a Deus, como redivivos dentre os mortos, e os vossos membros a Deus, como instrumentos de justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 14, 'Pois o pecado não terá domínio sobre vós, porquanto não estais debaixo da lei, mas debaixo da graça.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 15, 'Pois quê? Havemos de pecar porque não estamos debaixo da lei, mas debaixo da graça? De modo nenhum.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 16, 'Não sabeis que daquele a quem vos apresentais como servos para lhe obedecer, sois servos desse mesmo a quem obedeceis, seja do pecado para a morte, ou da obediência para a justiça?', 1, CURRENT_TIMESTAMP, false),
(45, 6, 17, 'Mas graças a Deus que, embora tendo sido servos do pecado, obedecestes de coração à forma de doutrina a que fostes entregues;', 1, CURRENT_TIMESTAMP, false),
(45, 6, 18, 'e libertos do pecado, fostes feitos servos da justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 19, 'Falo como homem, por causa da fraqueza da vossa carne. Pois assim como apresentastes os vossos membros como servos da impureza e da iniqüidade para iniqüidade, assim apresentai agora os vossos membros como servos da justiça para santificação.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 20, 'Porque, quando éreis servos do pecado, estáveis livres em relação à justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 21, 'E que fruto tínheis então das coisas de que agora vos envergonhais? pois o fim delas é a morte.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 22, 'Mas agora, libertos do pecado, e feitos servos de Deus, tendes o vosso fruto para santificação, e por fim a vida eterna.', 1, CURRENT_TIMESTAMP, false),
(45, 6, 23, 'Porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus nosso Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 1, 'Ou ignorais, irmãos {pois falo aos que conhecem a lei}, que a lei tem domínio sobre o homem por todo o tempo que ele vive?', 1, CURRENT_TIMESTAMP, false),
(45, 7, 2, 'Porque a mulher casada está ligada pela lei a seu marido enquanto ele viver; mas, se ele morrer, ela está livre da lei do marido.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 3, 'De sorte que, enquanto viver o marido, será chamado adúltera, se for de outro homem; mas, se ele morrer, ela está livre da lei, e assim não será adúltera se for de outro marido.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 4, 'Assim também vós, meus irmãos, fostes mortos quanto à lei mediante o corpo de Cristo, para pertencerdes a outro, àquele que ressurgiu dentre os mortos a fim de que demos fruto para Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 5, 'Pois, quando estávamos na carne, as paixões dos pecados, suscitadas pela lei, operavam em nossos membros para darem fruto para a morte.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 6, 'Mas agora fomos libertos da lei, havendo morrido para aquilo em que estávamos retidos, para servirmos em novidade de espírito, e não na velhice da letra.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 7, 'Que diremos pois? É a lei pecado? De modo nenhum. Contudo, eu não conheci o pecado senão pela lei; porque eu não conheceria a concupiscência, se a lei não dissesse: Não cobiçarás.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 8, 'Mas o pecado, tomando ocasião, pelo mandamento operou em mim toda espécie de concupiscência; porquanto onde não há lei está morto o pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 9, 'E outrora eu vivia sem a lei; mas assim que veio o mandamento, reviveu o pecado, e eu morri;', 1, CURRENT_TIMESTAMP, false),
(45, 7, 10, 'e o mandamento que era para vida, esse achei que me era para morte.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 11, 'Porque o pecado, tomando ocasião, pelo mandamento me enganou, e por ele me matou.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 12, 'De modo que a lei é santa, e o mandamento santo, justo e bom.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 13, 'Logo o bom tornou-se morte para mim? De modo nenhum; mas o pecado, para que se mostrasse pecado, operou em mim a morte por meio do bem; a fim de que pelo mandamento o pecado se manifestasse excessivamente maligno.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 14, 'Porque bem sabemos que a lei é espiritual; mas eu sou carnal, vendido sob o pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 15, 'Pois o que faço, não o entendo; porque o que quero, isso não pratico; mas o que aborreço, isso faço.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 16, 'E, se faço o que não quero, consinto com a lei, que é boa.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 17, 'Agora, porém, não sou mais eu que faço isto, mas o pecado que habita em mim.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 18, 'Porque eu sei que em mim, isto é, na minha carne, não habita bem algum; com efeito o querer o bem está em mim, mas o efetuá-lo não está.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 19, 'Pois não faço o bem que quero, mas o mal que não quero, esse pratico.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 20, 'Ora, se eu faço o que não quero, já o não faço eu, mas o pecado que habita em mim.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 21, 'Acho então esta lei em mim, que, mesmo querendo eu fazer o bem, o mal está comigo.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 22, 'Porque, segundo o homem interior, tenho prazer na lei de Deus;', 1, CURRENT_TIMESTAMP, false),
(45, 7, 23, 'mas vejo nos meus membros outra lei guerreando contra a lei do meu entendimento, e me levando cativo à lei do pecado, que está nos meus membros.', 1, CURRENT_TIMESTAMP, false),
(45, 7, 24, 'Miserável homem que eu sou! quem me livrará do corpo desta morte?', 1, CURRENT_TIMESTAMP, false),
(45, 7, 25, 'Graças a Deus, por Jesus Cristo nosso Senhor! De modo que eu mesmo com o entendimento sirvo à lei de Deus, mas com a carne à lei do pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 1, 'Portanto, agora nenhuma condenação há para os que estão em Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 2, 'Porque a lei do Espírito da vida, em Cristo Jesus, te livrou da lei do pecado e da morte.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 3, 'Porquanto o que era impossível à lei, visto que se achava fraca pela carne, Deus enviando o seu próprio Filho em semelhança da carne do pecado, e por causa do pecado, na carne condenou o pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 4, 'para que a justa exigência da lei se cumprisse em nós, que não andamos segundo a carne, mas segundo o Espírito.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 5, 'Pois os que são segundo a carne inclinam-se para as coisas da carne; mas os que são segundo o Espírito para as coisas do Espírito.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 6, 'Porque a inclinação da carne é morte; mas a inclinação do Espírito é vida e paz.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 7, 'Porquanto a inclinação da carne é inimizade contra Deus, pois não é sujeita à lei de Deus, nem em verdade o pode ser;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 8, 'e os que estão na carne não podem agradar a Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 9, 'Vós, porém, não estais na carne, mas no Espírito, se é que o Espírito de Deus habita em vós. Mas, se alguém não tem o Espírito de Cristo, esse tal não é dele.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 10, 'Ora, se Cristo está em vós, o corpo, na verdade, está morto por causa do pecado, mas o espírito vive por causa da justiça.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 11, 'E, se o Espírito daquele que dos mortos ressuscitou a Jesus habita em vós, aquele que dos mortos ressuscitou a Cristo Jesus há de vivificar também os vossos corpos mortais, pelo seu Espírito que em vós habita.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 12, 'Portanto, irmãos, somos devedores, não à carne para vivermos segundo a carne;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 13, 'porque se viverdes segundo a carne, haveis de morrer; mas, se pelo Espírito mortificardes as obras do corpo, vivereis.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 14, 'Pois todos os que são guiados pelo Espírito de Deus, esses são filhos de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 15, 'Porque não recebestes o espírito de escravidão, para outra vez estardes com temor, mas recebestes o espírito de adoção, pelo qual clamamos: Aba, Pai!', 1, CURRENT_TIMESTAMP, false),
(45, 8, 16, 'O Espírito mesmo testifica com o nosso espírito que somos filhos de Deus;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 17, 'e, se filhos, também herdeiros, herdeiros de Deus e co-herdeiros de Cristo; se é certo que com ele padecemos, para que também com ele sejamos glorificados.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 18, 'Pois tenho para mim que as aflições deste tempo presente não se podem comparar com a glória que em nós há de ser revelada.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 19, 'Porque a criação aguarda com ardente expectativa a revelação dos filhos de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 20, 'Porquanto a criação ficou sujeita à vaidade, não por sua vontade, mas por causa daquele que a sujeitou,', 1, CURRENT_TIMESTAMP, false),
(45, 8, 21, 'na esperança de que também a própria criação há de ser liberta do cativeiro da corrupção, para a liberdade da glória dos filhos de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 22, 'Porque sabemos que toda a criação, conjuntamente, geme e está com dores de parto até agora;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 23, 'e não só ela, mas até nós, que temos as primícias do Espírito, também gememos em nós mesmos, aguardando a nossa adoração, a saber, a redenção do nosso corpo.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 24, 'Porque na esperança fomos salvos. Ora, a esperança que se vê não é esperança; pois o que alguém vê, como o espera?', 1, CURRENT_TIMESTAMP, false),
(45, 8, 25, 'Mas, se esperamos o que não vemos, com paciência o aguardamos.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 26, 'Do mesmo modo também o Espírito nos ajuda na fraqueza; porque não sabemos o que havemos de pedir como convém, mas o Espírito mesmo intercede por nós com gemidos inexprimíveis.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 27, 'E aquele que esquadrinha os corações sabe qual é a intenção do Espírito: que ele, segundo a vontade de Deus, intercede pelos santos.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 28, 'E sabemos que todas as coisas concorrem para o bem daqueles que amam a Deus, daqueles que são chamados segundo o seu propósito.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 29, 'Porque os que dantes conheceu, também os predestinou para serem conformes à imagem de seu Filho, a fim de que ele seja o primogênito entre muitos irmãos;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 30, 'e aos que predestinou, a estes também chamou; e aos que chamou, a estes também justificou; e aos que justificou, a estes também glorificou.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 31, 'Que diremos, pois, a estas coisas? Se Deus é por nós, quem será contra nós?', 1, CURRENT_TIMESTAMP, false),
(45, 8, 32, 'Aquele que nem mesmo a seu próprio Filho poupou, antes o entregou por todos nós, como não nos dará também com ele todas as coisas?', 1, CURRENT_TIMESTAMP, false),
(45, 8, 33, 'Quem intentará acusação contra os escolhidos de Deus? É Deus quem os justifica;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 34, 'Quem os condenará? Cristo Jesus é quem morreu, ou antes quem ressurgiu dentre os mortos, o qual está à direita de Deus, e também intercede por nós;', 1, CURRENT_TIMESTAMP, false),
(45, 8, 35, 'quem nos separará do amor de Cristo? a tribulação, ou a angústia, ou a perseguição, ou a fome, ou a nudez, ou o perigo, ou a espada?', 1, CURRENT_TIMESTAMP, false),
(45, 8, 36, 'Como está escrito: Por amor de ti somos entregues à morte o dia todo; fomos considerados como ovelhas para o matadouro.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 37, 'Mas em todas estas coisas somos mais que vencedores, por aquele que nos amou.', 1, CURRENT_TIMESTAMP, false),
(45, 8, 38, 'Porque estou certo de que, nem a morte, nem a vida, nem anjos, nem principados, nem coisas presentes, nem futuras, nem potestades,', 1, CURRENT_TIMESTAMP, false),
(45, 8, 39, 'nem a altura, nem a profundidade, nem qualquer outra criatura nos poderá separar do amor de Deus, que está em Cristo Jesus nosso Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 1, 'Digo a verdade em Cristo, não minto, dando testemunho comigo a minha consciência no Espírito Santo,', 1, CURRENT_TIMESTAMP, false),
(45, 9, 2, 'que tenho grande tristeza e incessante dor no meu coração.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 3, 'Porque eu mesmo desejaria ser separado de Cristo, por amor de meus irmãos, que são meus parentes segundo a carne;', 1, CURRENT_TIMESTAMP, false),
(45, 9, 4, 'os quais são israelitas, de quem é a adoção, e a glória, e os pactos, e a promulgação da lei, e o culto, e as promessas;', 1, CURRENT_TIMESTAMP, false),
(45, 9, 5, 'de quem são os patriarcas; e de quem descende o Cristo segundo a carne, o qual é sobre todas as coisas, Deus bendito eternamente. Amém.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 6, 'Não que a palavra de Deus haja falhado. Porque nem todos os que são de Israel são israelitas;', 1, CURRENT_TIMESTAMP, false),
(45, 9, 7, 'nem por serem descendência de Abraão são todos filhos; mas: Em Isaque será chamada a tua descendência.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 8, 'Isto é, não são os filhos da carne que são filhos de Deus; mas os filhos da promessa são contados como descendência.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 9, 'Porque a palavra da promessa é esta: Por este tempo virei, e Sara terá um filho.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 10, 'E não somente isso, mas também a Rebeca, que havia concebido de um, de Isaque, nosso pai', 1, CURRENT_TIMESTAMP, false),
(45, 9, 11, '{pois não tendo os gêmeos ainda nascido, nem tendo praticado bem ou mal, para que o propósito de Deus segundo a eleição permanecesse firme, não por causa das obras, mas por aquele que chama},', 1, CURRENT_TIMESTAMP, false),
(45, 9, 12, 'foi-lhe dito: O maior servirá o menor.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 13, 'Como está escrito: Amei a Jacó, e aborreci a Esaú.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 14, 'Que diremos, pois? Há injustiça da parte de Deus? De modo nenhum.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 15, 'Porque diz a Moisés: Terei misericórdia de quem me aprouver ter misericórdia, e terei compaixão de quem me aprouver ter compaixão.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 16, 'Assim, pois, isto não depende do que quer, nem do que corre, mas de Deus que usa de misericórdia.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 17, 'Pois diz a Escritura a Faraó: Para isto mesmo te levantei: para em ti mostrar o meu poder, e para que seja anunciado o meu nome em toda a terra.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 18, 'Portanto, tem misericórdia de quem quer, e a quem quer endurece.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 19, 'Dir-me-ás então. Por que se queixa ele ainda? Pois, quem resiste à sua vontade?', 1, CURRENT_TIMESTAMP, false),
(45, 9, 20, 'Mas, ó homem, quem és tu, que a Deus replicas? Porventura a coisa formada dirá ao que a formou: Por que me fizeste assim?', 1, CURRENT_TIMESTAMP, false),
(45, 9, 21, 'Ou não tem o oleiro poder sobre o barro, para da mesma massa fazer um vaso para uso honroso e outro para uso desonroso?', 1, CURRENT_TIMESTAMP, false),
(45, 9, 22, 'E que direis, se Deus, querendo mostrar a sua ira, e dar a conhecer o seu poder, suportou com muita paciência os vasos da ira, preparados para a perdição;', 1, CURRENT_TIMESTAMP, false),
(45, 9, 23, 'para que também desse a conhecer as riquezas da sua glória nos vasos de misericórdia, que de antemão preparou para a glória,', 1, CURRENT_TIMESTAMP, false),
(45, 9, 24, 'os quais somos nós, a quem também chamou, não só dentre os judeus, mas também dentre os gentios?', 1, CURRENT_TIMESTAMP, false),
(45, 9, 25, 'Como diz ele também em Oséias: Chamarei meu povo ao que não era meu povo; e amada à que não era amada.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 26, 'E sucederá que no lugar em que lhes foi dito: Vós não sois meu povo; aí serão chamados filhos do Deus vivo.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 27, 'Também Isaías exclama acerca de Israel: Ainda que o número dos filhos de Israel seja como a areia do mar, o remanescente é que será salvo.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 28, 'Porque o Senhor executará a sua palavra sobre a terra, consumando-a e abreviando-a.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 29, 'E como antes dissera Isaías: Se o Senhor dos Exércitos não nos tivesse deixado descendência, teríamos sido feitos como Sodoma, e seríamos semelhantes a Gomorra.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 30, 'Que diremos pois? Que os gentios, que não buscavam a justiça, alcançaram a justiça, mas a justiça que vem da fé.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 31, 'Mas Israel, buscando a lei da justiça, não atingiu esta lei.', 1, CURRENT_TIMESTAMP, false),
(45, 9, 32, 'Por que? Porque não a buscavam pela fé, mas como que pelas obras; e tropeçaram na pedra de tropeço;', 1, CURRENT_TIMESTAMP, false),
(45, 9, 33, 'como está escrito: Eis que eu ponho em Sião uma pedra de tropeço; e uma rocha de escândalo; e quem nela crer não será confundido.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 1, 'Irmãos, o bom desejo do meu coração e a minha súplica a Deus por Israel é para sua salvação.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 2, 'Porque lhes dou testemunho de que têm zelo por Deus, mas não com entendimento.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 3, 'Porquanto, não conhecendo a justiça de Deus, e procurando estabelecer a sua própria, não se sujeitaram à justiça de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 4, 'Pois Cristo é o fim da lei para justificar a todo aquele que crê.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 5, 'Porque Moisés escreve que o homem que pratica a justiça que vem da lei viverá por ela.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 6, 'Mas a justiça que vem da fé diz assim: Não digas em teu coração: Quem subirá ao céu? {isto é, a trazer do alto a Cristo;}', 1, CURRENT_TIMESTAMP, false),
(45, 10, 7, 'ou: Quem descerá ao abismo? {isto é, a fazer subir a Cristo dentre os mortos}.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 8, 'Mas que diz? A palavra está perto de ti, na tua boca e no teu coração; isto é, a palavra da fé, que pregamos.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 9, 'Porque, se com a tua boca confessares a Jesus como Senhor, e em teu coração creres que Deus o ressuscitou dentre os mortos, será salvo;', 1, CURRENT_TIMESTAMP, false),
(45, 10, 10, 'pois é com o coração que se crê para a justiça, e com a boca se faz confissão para a salvação.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 11, 'Porque a Escritura diz: Ninguém que nele crê será confundido.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 12, 'Porquanto não há distinção entre judeu e grego; porque o mesmo Senhor o é de todos, rico para com todos os que o invocam.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 13, 'Porque: Todo aquele que invocar o nome do Senhor será salvo.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 14, 'Como pois invocarão aquele em quem não creram? e como crerão naquele de quem não ouviram falar? e como ouvirão, se não há quem pregue?', 1, CURRENT_TIMESTAMP, false),
(45, 10, 15, 'E como pregarão, se não forem enviados? assim como está escrito: Quão formosos os pés dos que anunciam coisas boas!', 1, CURRENT_TIMESTAMP, false),
(45, 10, 16, 'Mas nem todos deram ouvidos ao evangelho; pois Isaías diz: Senhor, quem deu crédito à nossa mensagem?', 1, CURRENT_TIMESTAMP, false),
(45, 10, 17, 'Logo a fé é pelo ouvir, e o ouvir pela palavra de Cristo.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 18, 'Mas pergunto: Porventura não ouviram? Sim, por certo: Por toda a terra saiu a voz deles, e as suas palavras até os confins do mundo.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 19, 'Mas pergunto ainda: Porventura Israel não o soube? Primeiro diz Moisés: Eu vos porei em ciúmes com aqueles que não são povo, com um povo insensato vos provocarei à ira.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 20, 'E Isaías ousou dizer: Fui achado pelos que não me buscavam, manifestei-me aos que por mim não perguntavam.', 1, CURRENT_TIMESTAMP, false),
(45, 10, 21, 'Quanto a Israel, porém, diz: Todo o dia estendi as minhas mãos a um povo rebelde e contradizente.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 1, 'Pergunto, pois: Acaso rejeitou Deus ao seu povo? De modo nenhum; por que eu também sou israelita, da descendência de Abraão, da tribo de Benjamim.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 2, 'Deus não rejeitou ao seu povo que antes conheceu. Ou não sabeis o que a Escritura diz de Elias, como ele fala a Deus contra Israel, dizendo:', 1, CURRENT_TIMESTAMP, false),
(45, 11, 3, 'Senhor, mataram os teus profetas, e derribaram os teus altares; e só eu fiquei, e procuraram tirar-me a vida?', 1, CURRENT_TIMESTAMP, false),
(45, 11, 4, 'Mas que lhe diz a resposta divina? Reservei para mim sete mil varões que não dobraram os joelhos diante de Baal.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 5, 'Assim, pois, também no tempo presente ficou um remanescente segundo a eleição da graça.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 6, 'Mas se é pela graça, já não é pelas obras; de outra maneira, a graça já não é graça.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 7, 'Pois quê? O que Israel busca, isso não o alcançou; mas os eleitos alcançaram; e os outros foram endurecidos,', 1, CURRENT_TIMESTAMP, false),
(45, 11, 8, 'como está escrito: Deus lhes deu um espírito entorpecido, olhos para não verem, e ouvidos para não ouvirem, até o dia de hoje.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 9, 'E Davi diz: Torne-se-lhes a sua mesa em laço, e em armadilha, e em tropeço, e em retribuição;', 1, CURRENT_TIMESTAMP, false),
(45, 11, 10, 'escureçam-se-lhes os olhos para não verem, e tu encurva-lhes sempre as costas.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 11, 'Logo, pergunto: Porventura tropeçaram de modo que caíssem? De maneira nenhuma, antes pelo seu tropeço veio a salvação aos gentios, para os incitar à emulação.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 12, 'Ora se o tropeço deles é a riqueza do mundo, e a sua diminuição a riqueza dos gentios, quanto mais a sua plenitude!', 1, CURRENT_TIMESTAMP, false),
(45, 11, 13, 'Mas é a vós, gentios, que falo; e, porquanto sou apóstolo dos gentios, glorifico o meu ministério,', 1, CURRENT_TIMESTAMP, false),
(45, 11, 14, 'para ver se de algum modo posso incitar à emulação os da minha raça e salvar alguns deles.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 15, 'Porque, se a sua rejeição é a reconciliação do mundo, qual será a sua admissão, senão a vida dentre os mortos?', 1, CURRENT_TIMESTAMP, false),
(45, 11, 16, 'Se as primícias são santas, também a massa o é; e se a raiz é santa, também os ramos o são.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 17, 'E se alguns dos ramos foram quebrados, e tu, sendo zambujeiro, foste enxertado no lugar deles e feito participante da raiz e da seiva da oliveira,', 1, CURRENT_TIMESTAMP, false),
(45, 11, 18, 'não te glories contra os ramos; e, se contra eles te gloriares, não és tu que sustentas a raiz, mas a raiz a ti.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 19, 'Dirás então: Os ramos foram quebrados, para que eu fosse enxertado.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 20, 'Está bem; pela sua incredulidade foram quebrados, e tu pela tua fé estás firme. Não te ensoberbeças, mas teme;', 1, CURRENT_TIMESTAMP, false),
(45, 11, 21, 'porque, se Deus não poupou os ramos naturais, não te poupará a ti.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 22, 'Considera pois a bondade e a severidade de Deus: para com os que caíram, severidade; para contigo, a bondade de Deus, se permaneceres nessa bondade; do contrário também tu serás cortado.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 23, 'E ainda eles, se não permanecerem na incredulidade, serão enxertados; porque poderoso é Deus para os enxertar novamente.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 24, 'Pois se tu foste cortado do natural zambujeiro, e contra a natureza enxertado em oliveira legítima, quanto mais não serão enxertados na sua própria oliveira esses que são ramos naturais!', 1, CURRENT_TIMESTAMP, false),
(45, 11, 25, 'Porque não quero, irmãos, que ignoreis este mistério {para que não presumais de vós mesmos}: que o endurecimento veio em parte sobre Israel, até que a plenitude dos gentios haja entrado;', 1, CURRENT_TIMESTAMP, false),
(45, 11, 26, 'e assim todo o Israel será salvo, como está escrito: Virá de Sião o Libertador, e desviará de Jacó as impiedades;', 1, CURRENT_TIMESTAMP, false),
(45, 11, 27, 'e este será o meu pacto com eles, quando eu tirar os seus pecados.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 28, 'Quanto ao evangelho, eles na verdade, são inimigos por causa de vós; mas, quanto à eleição, amados por causa dos pais.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 29, 'Porque os dons e a vocação de Deus são irretratáveis.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 30, 'Pois, assim como vós outrora fostes desobedientes a Deus, mas agora alcançastes misericórdia pela desobediência deles,', 1, CURRENT_TIMESTAMP, false),
(45, 11, 31, 'assim também estes agora foram desobedientes, para também alcançarem misericórdia pela misericórdia a vós demonstrada.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 32, 'Porque Deus encerrou a todos debaixo da desobediência, a fim de usar de misericórdia para com todos.', 1, CURRENT_TIMESTAMP, false),
(45, 11, 33, 'Ó profundidade das riquezas, tanto da sabedoria, como da ciência de Deus! Quão insondáveis são os seus juízos, e quão inescrutáveis os seus caminhos!', 1, CURRENT_TIMESTAMP, false),
(45, 11, 34, 'Pois, quem jamais conheceu a mente do Senhor? ou quem se fez seu conselheiro?', 1, CURRENT_TIMESTAMP, false),
(45, 11, 35, 'Ou quem lhe deu primeiro a ele, para que lhe seja recompensado?', 1, CURRENT_TIMESTAMP, false),
(45, 11, 36, 'Porque dele, e por ele, e para ele, são todas as coisas; glória, pois, a ele eternamente. Amém.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 1, 'Rogo-vos pois, irmãos, pela compaixão de Deus, que apresenteis os vossos corpos como um sacrifício vivo, santo e agradável a Deus, que é o vosso culto racional.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 2, 'E não vos conformeis a este mundo, mas transformai-vos pela renovação da vossa mente, para que experimenteis qual seja a boa, agradável, e perfeita vontade de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 3, 'Porque pela graça que me foi dada, digo a cada um dentre vós que não tenha de si mesmo mais alto conceito do que convém; mas que pense de si sobriamente, conforme a medida da fé que Deus, repartiu a cada um.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 4, 'Pois assim como em um corpo temos muitos membros, e nem todos os membros têm a mesma função,', 1, CURRENT_TIMESTAMP, false),
(45, 12, 5, 'assim nós, embora muitos, somos um só corpo em Cristo, e individualmente uns dos outros.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 6, 'De modo que, tendo diferentes dons segundo a graça que nos foi dada, se é profecia, seja ela segundo a medida da fé;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 7, 'se é ministério, seja em ministrar; se é ensinar, haja dedicação ao ensino;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 8, 'ou que exorta, use esse dom em exortar; o que reparte, faça-o com liberalidade; o que preside, com zelo; o que usa de misericórdia, com alegria.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 9, 'O amor seja não fingido. Aborrecei o mal e apegai-vos ao bem.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 10, 'Amai-vos cordialmente uns aos outros com amor fraternal, preferindo-vos em honra uns aos outros;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 11, 'não sejais vagarosos no cuidado; sede fervorosos no espírito, servindo ao Senhor;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 12, 'alegrai-vos na esperança, sede pacientes na tribulação, perseverai na oração;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 13, 'acudi aos santos nas suas necessidades, exercei a hospitalidade;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 14, 'abençoai aos que vos perseguem; abençoai, e não amaldiçoeis;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 15, 'alegrai-vos com os que se alegram; chorai com os que choram;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 16, 'sede unânimes entre vós; não ambicioneis coisas altivas mas acomodai-vos às humildes; não sejais sábios aos vossos olhos;', 1, CURRENT_TIMESTAMP, false),
(45, 12, 17, 'a ninguém torneis mal por mal; procurai as coisas dignas, perante todos os homens.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 18, 'Se for possível, quanto depender de vós, tende paz com todos os homens.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 19, 'Não vos vingueis a vós mesmos, amados, mas dai lugar à ira de Deus, porque está escrito: Minha é a vingança, eu retribuirei, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 20, 'Antes, se o teu inimigo tiver fome, dá-lhe de comer; se tiver sede, dá-lhe de beber; porque, fazendo isto amontoarás brasas de fogo sobre a sua cabeça.', 1, CURRENT_TIMESTAMP, false),
(45, 12, 21, 'Não te deixes vencer do mal, mas vence o mal com o bem.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 1, 'Toda alma esteja sujeita às autoridades superiores; porque não há autoridade que não venha de Deus; e as que existem foram ordenadas por Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 2, 'Por isso quem resiste à autoridade resiste à ordenação de Deus; e os que resistem trarão sobre si mesmos a condenação.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 3, 'Porque os magistrados não são motivo de temor para os que fazem o bem, mas para os que fazem o mal. Queres tu, pois, não temer a autoridade? Faze o bem, e terás louvor dela;', 1, CURRENT_TIMESTAMP, false),
(45, 13, 4, 'porquanto ela é ministro de Deus para teu bem. Mas, se fizeres o mal, teme, pois não traz debalde a espada; porque é ministro de Deus, e vingador em ira contra aquele que pratica o mal.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 5, 'Pelo que é necessário que lhe estejais sujeitos, não somente por causa da ira, mas também por causa da consciência.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 6, 'Por esta razão também pagais tributo; porque são ministros de Deus, para atenderem a isso mesmo.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 7, 'Dai a cada um o que lhe é devido: a quem tributo, tributo; a quem imposto, imposto; a quem temor, temor; a quem honra, honra.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 8, 'A ninguém devais coisa alguma, senão o amor recíproco; pois quem ama ao próximo tem cumprido a lei.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 9, 'Com efeito: Não adulterarás; não matarás; não furtarás; não cobiçarás; e se há algum outro mandamento, tudo nesta palavra se resume: Amarás ao teu próximo como a ti mesmo.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 10, 'O amor não faz mal ao próximo. De modo que o amor é o cumprimento da lei.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 11, 'E isso fazei, conhecendo o tempo, que já é hora de despertardes do sono; porque a nossa salvação está agora mais perto de nós do que quando nos tornamos crentes.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 12, 'A noite é passada, e o dia é chegado; dispamo-nos, pois, das obras das trevas, e vistamo-nos, pois, das obras das trevas, e vistamo-nos das armas da luz.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 13, 'Andemos honestamente, como de dia: não em glutonarias e bebedeiras, não em impudicícias e dissoluções, não em contendas e inveja.', 1, CURRENT_TIMESTAMP, false),
(45, 13, 14, 'Mas revesti-vos do Senhor Jesus Cristo; e não tenhais cuidado da carne em suas concupiscências.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 1, 'Ora, ao que é fraco na fé, acolhei-o, mas não para condenar-lhe os escrúpulos.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 2, 'Um crê que de tudo se pode comer, e outro, que é fraco, come só legumes.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 3, 'Quem come não despreze a quem não come; e quem não come não julgue a quem come; pois Deus o acolheu.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 4, 'Quem és tu, que julgas o servo alheio? Para seu próprio senhor ele está em pé ou cai; mas estará firme, porque poderoso é o Senhor para o firmar.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 5, 'Um faz diferença entre dia e dia, mas outro julga iguais todos os dias. Cada um esteja inteiramente convicto em sua própria mente.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 6, 'Aquele que faz caso do dia, para o Senhor o faz. E quem come, para o Senhor come, porque dá graças a Deus; e quem não come, para o Senhor não come, e dá graças a Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 7, 'Porque nenhum de nós vive para si, e nenhum morre para si.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 8, 'Pois, se vivemos, para o Senhor vivemos; se morremos, para o Senhor morremos. De sorte que, quer vivamos quer morramos, somos do Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 9, 'Porque foi para isto mesmo que Cristo morreu e tornou a viver, para ser Senhor tanto de mortos como de vivos.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 10, 'Mas tu, por que julgas teu irmão? Ou tu, também, por que desprezas teu irmão? Pois todos havemos de comparecer ante o tribunal de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 11, 'Porque está escrito: Por minha vida, diz o Senhor, diante de mim se dobrará todo joelho, e toda língua louvará a Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 12, 'Assim, pois, cada um de nós dará conta de si mesmo a Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 13, 'Portanto não nos julguemos mais uns aos outros; antes o seja o vosso propósito não pôr tropeço ou escândalo ao vosso irmão.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 14, 'Eu sei, e estou certo no Senhor Jesus, que nada é de si mesmo imundo a não ser para aquele que assim o considera; para esse é imundo.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 15, 'Pois, se pela tua comida se entristece teu irmão, já não andas segundo o amor. Não faças perecer por causa da tua comida aquele por quem Cristo morreu.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 16, 'Não seja pois censurado o vosso bem;', 1, CURRENT_TIMESTAMP, false),
(45, 14, 17, 'porque o reino de Deus não consiste no comer e no beber, mas na justiça, na paz, e na alegria no Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 18, 'Pois quem nisso serve a Cristo agradável é a Deus e aceito aos homens.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 19, 'Assim, pois, sigamos as coisas que servem para a paz e as que contribuem para a edificação mútua.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 20, 'Não destruas por causa da comida a obra de Deus. Na verdade tudo é limpo, mas é um mal para o homem dar motivo de tropeço pelo comer.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 21, 'Bom é não comer carne, nem beber vinho, nem fazer outra coisa em que teu irmão tropece.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 22, 'A fé que tens, guarda-a contigo mesmo diante de Deus. Bem-aventurado aquele que não se condena a si mesmo naquilo que aprova.', 1, CURRENT_TIMESTAMP, false),
(45, 14, 23, 'Mas aquele que tem dúvidas, se come está condenado, porque o que faz não provém da fé; e tudo o que não provém da fé é pecado.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 1, 'Ora nós, que somos fortes, devemos suportar as fraquezas dos fracos, e não agradar a nós mesmos.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 2, 'Portanto cada um de nós agrade ao seu próximo, visando o que é bom para edificação.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 3, 'Porque também Cristo não se agradou a si mesmo, mas como está escrito: Sobre mim caíram as injúrias dos que te injuriavam.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 4, 'Porquanto, tudo que dantes foi escrito, para nosso ensino foi escrito, para que, pela constância e pela consolação provenientes das Escrituras, tenhamos esperança.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 5, 'Ora, o Deus de constância e de consolação vos dê o mesmo sentimento uns para com os outros, segundo Cristo Jesus.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 6, 'Para que unânimes, e a uma boca, glorifiqueis ao Deus e Pai de nosso Senhor Jesus Cristo.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 7, 'Portanto recebei-vos uns aos outros, como também Cristo nos recebeu, para glória de Deus.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 8, 'Digo pois que Cristo foi feito ministro da circuncisão, por causa da verdade de Deus, para confirmar as promessas feitas aos pais;', 1, CURRENT_TIMESTAMP, false),
(45, 15, 9, 'e para que os gentios glorifiquem a Deus pela sua misericórdia, como está escrito: Portanto eu te louvarei entre os gentios, e cantarei ao teu nome.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 10, 'E outra vez diz: Alegrai-vos, gentios, juntamente com o povo.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 11, 'E ainda: Louvai ao Senhor, todos os gentios, e louvem-no, todos os povos.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 12, 'E outra vez, diz também Isaías: Haverá a raiz de Jessé, aquele que se levanta para reger os gentios; nele os gentios esperarão.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 13, 'Ora, o Deus de esperança vos encha de todo o gozo e paz na vossa fé, para que abundeis na esperança pelo poder do Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 14, 'Eu, da minha parte, irmãos meus, estou persuadido a vosso respeito, que vós já estais cheios de bondade, cheios de todo o conhecimento e capazes, vós mesmos, de admoestar-vos uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 15, 'Mas em parte vos escrevo mais ousadamente, como para vos trazer outra vez isto à memória, por causa da graça que por Deus me foi dada,', 1, CURRENT_TIMESTAMP, false),
(45, 15, 16, 'para ser ministro de Cristo Jesus entre os gentios, ministrando o evangelho de Deus, para que sejam aceitáveis os gentios como oferta, santificada pelo Espírito Santo.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 17, 'Tenho, portanto, motivo para me gloriar em Cristo Jesus, nas coisas concernentes a Deus;', 1, CURRENT_TIMESTAMP, false),
(45, 15, 18, 'porque não ousarei falar de coisa alguma senão daquilo que Cristo por meu intermédio tem feito, para obediência da parte dos gentios, por palavra e por obras,', 1, CURRENT_TIMESTAMP, false),
(45, 15, 19, 'pelo poder de sinais e prodígios, no poder do Espírito Santo; de modo que desde Jerusalém e arredores, até a Ilíria, tenho divulgado o evangelho de Cristo;', 1, CURRENT_TIMESTAMP, false),
(45, 15, 20, 'deste modo esforçando-me por anunciar o evangelho, não onde Cristo houvera sido nomeado, para não edificar sobre fundamento alheio;', 1, CURRENT_TIMESTAMP, false),
(45, 15, 21, 'antes, como está escrito: Aqueles a quem não foi anunciado, o verão; e os que não ouviram, entenderão.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 22, 'Pelo que também muitas vezes tenho sido impedido de ir ter convosco;', 1, CURRENT_TIMESTAMP, false),
(45, 15, 23, 'mas agora, não tendo mais o que me detenha nestas regiões, e tendo já há muitos anos grande desejo de ir visitar-vos,', 1, CURRENT_TIMESTAMP, false),
(45, 15, 24, 'eu o farei quando for à Espanha; pois espero ver-vos de passagem e por vós ser encaminhado para lá, depois de ter gozado um pouco da vossa companhia.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 25, 'Mas agora vou a Jerusalém para ministrar aos santos.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 26, 'Porque pareceu bem à Macedônia e à Acaia levantar uma oferta fraternal para os pobres dentre os santos que estão em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 27, 'Isto pois lhes pareceu bem, como devedores que são para com eles. Porque, se os gentios foram participantes das bênçãos espirituais dos judeus, devem também servir a estes com as materiais.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 28, 'Tendo, pois, concluído isto, e havendo-lhes consignado este fruto, de lá, passando por vós, irei à Espanha.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 29, 'E bem sei que, quando for visitar-vos, chegarei na plenitude da bênção de Cristo.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 30, 'Rogo-vos, irmãos, por nosso Senhor Jesus Cristo e pelo amor do Espírito, que luteis juntamente comigo nas vossas orações por mim a Deus,', 1, CURRENT_TIMESTAMP, false),
(45, 15, 31, 'para que eu seja livre dos rebeldes que estão na Judéia, e que este meu ministério em Jerusalém seja aceitável aos santos;', 1, CURRENT_TIMESTAMP, false),
(45, 15, 32, 'a fim de que, pela vontade de Deus, eu chegue até vós com alegria, e possa entre vós recobrar as forças.', 1, CURRENT_TIMESTAMP, false),
(45, 15, 33, 'E o Deus de paz seja com todos vós. Amém.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 1, 'Recomendo-vos a nossa irmã Febe, que é serva da igreja que está em Cencréia;', 1, CURRENT_TIMESTAMP, false),
(45, 16, 2, 'para que a recebais no Senhor, de um modo digno dos santos, e a ajudeis em qualquer coisa que de vós necessitar; porque ela tem sido o amparo de muitos, e de mim em particular.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 3, 'Saudai a Prisca e a Áqüila, meus cooperadores em Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(45, 16, 4, 'os quais pela minha vida expuseram as suas cabeças; o que não só eu lhes agradeço, mas também todas as igrejas dos gentios.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 5, 'Saudai também a igreja que está na casa deles. Saudai a Epêneto, meu amado, que é as primícias da Ásia para Cristo.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 6, 'Saudai a Maria, que muito trabalhou por vós.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 7, 'Saudai a Andrônico e a Júnias, meus parentes e meus companheiros de prisão, os quais são bem conceituados entre os apóstolos, e que estavam em Cristo antes de mim.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 8, 'Saudai a Ampliato, meu amado no Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 9, 'Saudai a Urbano, nosso cooperador em Cristo, e a Estáquis, meu amado.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 10, 'Saudai a Apeles, aprovado em Cristo. Saudai aos da casa de Aristóbulo.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 11, 'Saudai a Herodião, meu parente. Saudai aos da casa de Narciso que estão no Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 12, 'Saudai a Trifena e a Trifosa, que trabalham no Senhor. Saudai a amada Pérside, que muito trabalhou no Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 13, 'Saudai a Rufo, eleito no Senhor, e a sua mãe e minha.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 14, 'Saudai a Asíncrito, a Flegonte, a Hermes, a Pátrobas, a Hermes, e aos irmãos que estão com eles.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 15, 'Saudai a Filólogo e a Júlia, a Nereu e a sua irmã, e a Olimpas, e a todos os santos que com eles estão.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 16, 'Saudai-vos uns aos outros com ósculo santo. Todas as igrejas de Cristo vos saúdam.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 17, 'Rogo-vos, irmãos, que noteis os que promovem dissensões e escândalos contra a doutrina que aprendestes; desviai-vos deles.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 18, 'Porque os tais não servem a Cristo nosso Senhor, mas ao seu ventre; e com palavras suaves e lisonjas enganam os corações dos inocentes.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 19, 'Pois a vossa obediência é conhecida de todos. Comprazo-me, portanto, em vós; e quero que sejais sábios para o bem, mas simples para o mal.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 20, 'E o Deus de paz em breve esmagará a Satanás debaixo dos vossos pés. A graça de nosso Senhor Jesus Cristo seja convosco.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 21, 'Saúdam-vos Timóteo, meu cooperador, e Lúcio, e Jáson, e Sosípatro, meus parentes.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 22, 'Eu, Tércio, que escrevo esta carta, vos saúdo no Senhor.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 23, 'Saúda-vos Gaio, hospedeiro meu e de toda a igreja. Saúda-vos Erasto, tesoureiro da cidade, e também o irmão Quarto.', 1, CURRENT_TIMESTAMP, false),
(45, 16, 24, '{A graça de nosso Senhor Jesus Cristo seja com todos vós. Amém.}', 1, CURRENT_TIMESTAMP, false),
(45, 16, 25, 'Ora, àquele que é poderoso para vos confirmar, segundo o meu evangelho e a pregação de Jesus Cristo, conforme a revelação do mistério guardado em silêncio desde os tempos eternos,', 1, CURRENT_TIMESTAMP, false),
(45, 16, 26, 'mas agora manifesto e, por meio das Escrituras proféticas, segundo o mandamento do Deus, eterno, dado a conhecer a todas as nações para obediência da fé;', 1, CURRENT_TIMESTAMP, false),
(45, 16, 27, 'ao único Deus sábio seja dada glória por Jesus Cristo para todo o sempre. Amém.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 1, 'Nos dias em que os juízes governavam, houve uma fome na terra; pelo que um homem de Belém de Judá saiu a peregrinar no país de Moabe, ele, sua mulher, e seus dois filhos.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 2, 'Chamava-se este homem Elimeleque, e sua mulher Noêmi, e seus dois filhos se chamavam Malom e Quiliom; eram efrateus, de Belém de Judá. Tendo entrado no país de Moabe, ficaram ali.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 3, 'E morreu Elimeleque, marido de Noêmi; e ficou ela com os seus dois filhos,', 1, CURRENT_TIMESTAMP, false),
(8, 1, 4, 'os quais se casaram com mulheres moabitas; uma destas se chamava Orfa, e a outra Rute; e moraram ali quase dez anos.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 5, 'E morreram também os dois, Malom e Quiliom, ficando assim a mulher desamparada de seus dois filhos e de seu marido.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 6, 'Então se levantou ela com as suas noras, para voltar do país de Moabe, porquanto nessa terra tinha ouvido que e Senhor havia visitado o seu povo, dando-lhe pão.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 7, 'Pelo que saiu de lugar onde estava, e com ela as duas noras. Indo elas caminhando para voltarem para a terra de Judá,', 1, CURRENT_TIMESTAMP, false),
(8, 1, 8, 'disse Noêmi às suas noras: Ide, voltai, cada uma para a casa de sua mãe; e o Senhor use convosco de benevolência, como vós o fizestes com os falecidos e comigo.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 9, 'O Senhor vos dê que acheis descanso cada uma em casa de seu marido. Quando as beijou, porém, levantaram a voz e choraram.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 10, 'E disseram-lhe: Certamente voltaremos contigo para o teu povo.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 11, 'Noêmi, porém, respondeu: Voltai, minhas filhas; porque ireis comigo? Tenho eu ainda filhos no meu ventre, para que vos viessem a ser maridos?', 1, CURRENT_TIMESTAMP, false),
(8, 1, 12, 'Voltai, filhas minhas; ide-vos, porque já sou velha demais para me casar. Ainda quando eu dissesse: Tenho esperança; ainda que esta noite tivesse marido e ainda viesse a ter filhos.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 13, 'esperá-los-íeis até que viessem a ser grandes? deter-vos-íeis por eles, sem tomardes marido? Não, filhas minhas, porque mais amargo me é a mim do que a vós mesmas; porquanto a mão do Senhor se descarregou contra mim.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 14, 'Então levantaram a voz, e tornaram a chorar; e Orfa beijou a sua sogra, porém Rute se apegou a ela.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 15, 'Pelo que disse Noêmi: Eis que tua concunhada voltou para o seu povo e para os seus deuses; volta também tu após a tua concunhada.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 16, 'Respondeu, porém, Rute: Não me instes a que te abandone e deixe de seguir-te. Porque aonde quer que tu fores, irei eu; e onde quer que pousares, ali pousarei eu; o teu povo será o meu povo, o teu Deus será o meu Deus.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 17, 'Onde quer que morreres, morrerei eu, e ali serei sepultada. Assim me faça o Senhor, e outro tanto, se outra coisa que não seja a morte me separar de ti.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 18, 'Vendo Noêmi que de todo estava resolvida a ir com ela, deixou de lhe falar nisso.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 19, 'Assim, pois, foram-se ambas, até que chegaram a Belém. E sucedeu que, ao entrarem em Belém, toda a cidade se comoveu por causa delas, e as mulheres perguntavam: É esta, porventura, Noêmi?', 1, CURRENT_TIMESTAMP, false),
(8, 1, 20, 'Ela, porém, lhes respondeu: Não me chameis Noêmi; chamai-me Mara, porque o Todo-Poderoso me encheu de amargura.', 1, CURRENT_TIMESTAMP, false),
(8, 1, 21, 'Cheia parti, porém vazia o Senhor me fez tornar. Por que, pois, me chamais Noêmi, visto que o Senhor testemunhou contra mim, e o Todo-Poderoso me afligiu?', 1, CURRENT_TIMESTAMP, false),
(8, 1, 22, 'Assim Noêmi voltou, e com ela Rute, a moabita, sua nora, que veio do país de Moabe; e chegaram a Belém no principio da sega da cevada.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 1, 'Ora, tinha Noêmi um parente de seu marido, homem poderoso e rico, da família de Elimeleque; e ele se chamava Boaz.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 2, 'Rute, a moabita, disse a Noêmi: Deixa-me ir ao campo a apanhar espigas atrás daquele a cujos olhos eu achar graça. E ela lhe respondeu: Vai, minha filha.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 3, 'Foi, pois, e chegando ao campo respigava após os segadores; e caiu-lhe em sorte uma parte do campo de Boaz, que era da família de Elimeleque.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 4, 'E eis que Boaz veio de Belém, e disse aos segadores: O Senhor seja convosco. Responderam-lhe eles: O Senhor te abençoe.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 5, 'Depois perguntou Boaz ao moço que estava posto sobre os segadores: De quem é esta moça?', 1, CURRENT_TIMESTAMP, false),
(8, 2, 6, 'Respondeu-lhe o moço: Esta é a moça moabita que voltou com Noêmi do país de Moabe.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 7, 'Disse-me ela: Deixa-me colher e ajuntar espigas por entre os molhos após os segadores: Assim ela veio, e está aqui desde pela manhã até agora, sem descansar nem sequer um pouco.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 8, 'Então disse Boaz a Rute: Escuta filha minha; não vás colher em outro campo, nem tampouco passes daqui, mas ajunta-te às minhas moças.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 9, 'Os teus olhos estarão atentos no campo que segarem, e irás após elas; não dei eu ordem aos moços, que não te molestem? Quando tiveres sede, vai aos vasos, e bebe do que os moços tiverem tirado.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 10, 'Então ela, inclinando-se e prostrando-se com o rosto em terra, perguntou-lhe: Por que achei eu graça aos teus olhos, para que faças caso de mim, sendo eu estrangeira?', 1, CURRENT_TIMESTAMP, false),
(8, 2, 11, 'Ao que lhe respondeu Boaz: Bem se me contou tudo quanto tens feito para com tua sogra depois da morte de teu marido; como deixaste a teu pai e a tua mãe, e a terra onde nasceste, e vieste para um povo que dantes não conhecias.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 12, 'O Senhor recompense o que fizeste, e te seja concedido pleno galardão da parte do Senhor Deus de Israel, sob cujas asas te vieste abrigar.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 13, 'E disse ela: Ache eu graça aos teus olhos, senhor meu, pois me consolaste, e falaste bondosamente a tua serva, não sendo eu nem mesmo como uma das tuas criadas.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 14, 'Também à hora de comer, disse-lhe Boaz: Achega-te, come do pão e molha o teu bocado no vinagre. E, sentando-se ela ao lado dos segadores, ele lhe ofereceu grão tostado, e ela comeu e ficou satisfeita, e ainda lhe sobejou.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 15, 'Quando ela se levantou para respigar, Boaz deu ordem aos seus moços, dizendo: Até entre os molhos deixai-a respirar, e não a censureis.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 16, 'Também, tirai dos molhos algumas espigas e deixai-as ficar, para que as colha, e não a repreendais.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 17, 'Assim ela respigou naquele campo até a tarde; e debulhou o que havia apanhado e foi quase uma efa de cevada.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 18, 'Então, carregando com a cevada, veio à cidade; e viu sua sogra o que ela havia apanhado. Também Rute tirou e deu-lhe o que lhe sobejara depois de fartar-se.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 19, 'Ao que lhe perguntou sua sogra: Onde respigaste hoje, e onde trabalhaste? Bendito seja aquele que fez caso de ti. E ela relatou à sua sogra com quem tinha trabalhado, e disse: O nome do homem com quem hoje trabalhei é Boaz.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 20, 'Disse Noêmi a sua nora: Bendito seja ele do Senhor, que não tem deixado de misturar a sua beneficência nem para com os vivos nem para com os mortos. Disse-lhe mais Noêmi: Esse homem é parente nosso, um dos nossos remidores.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 21, 'Respondeu Rute, a moabita: Ele me disse ainda: Seguirás de perto os meus moços até que tenham acabado toda a minha sega.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 22, 'Então disse Noêmi a sua nora, Rute: Bom é, filha minha, que saias com as suas moças, e que não te encontrem noutro campo.', 1, CURRENT_TIMESTAMP, false),
(8, 2, 23, 'Assim se ajuntou com as moças de Boaz, para respigar até e fim da sega da cevada e do trigo; e morava com a sua sogra.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 1, 'Depois lhe disse Noêmi, sua sogra: Minha filha, não te hei de buscar descanso, para que fiques bem?', 1, CURRENT_TIMESTAMP, false),
(8, 3, 2, 'Ora pois, não é Boaz, com cujas moças estiveste, de nossa parentela. Eis que esta noite ele vai joeirar a cevada na eira.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 3, 'Lava-te pois, unge-te, veste os teus melhores vestidos, e desce à eira; porém não te dês a conhecer ao homem, até que tenha acabado de comer e beber.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 4, 'E quando ele se deitar, notarás o lugar em que se deita; então entrarás, descobrir-lhe-ás os pés e te deitarás, e ele te dirá o que deves fazer.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 5, 'Respondeu-lhe Rute: Tudo quanto me disseres, farei.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 6, 'Então desceu à eira, e fez conforme tudo o que sua sogra lhe tinha ordenado.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 7, 'Havendo, pois, Boaz comido e bebido, e estando já o seu coração alegre, veio deitar-se ao pé de uma meda; e vindo ela de mansinho, descobriu-lhe os pés, e se deitou.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 8, 'Ora, pela meia-noite, o homem estremeceu, voltou-se, e viu uma mulher deitada aos seus pés.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 9, 'E perguntou ele: Quem és tu? Ao que ela respondeu: Sou Rute, tua serva; estende a tua capa sobre a tua serva, porque tu és o remidor.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 10, 'Então disse ele: Bendita sejas tu do Senhor, minha filha; mostraste agora mais bondade do que dantes, visto que após nenhum mancebo foste, quer pobre quer rico.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 11, 'Agora, pois, minha filha, não temas; tudo quanto disseres te farei, pois toda a cidade do meu povo sabe que és mulher virtuosa.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 12, 'Ora, é bem verdade que eu sou remidor, porém há ainda outro mais chegado do que eu.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 13, 'Fica-te aqui esta noite, e será que pela manhã, se ele cumprir para contigo os deveres de remidor, que o faça; mas se não os quiser cumprir, então eu o farei tão certamente como vive o Senhor; deita-te até pela manhã.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 14, 'Ficou, pois, deitada a seus pés até pela manhã, e levantou-se antes que fosse possível a uma pessoa reconhecer outra; porquanto ele disse: Não se saiba que uma mulher veio à eira.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 15, 'Disse mais: Traze aqui a capa com que te cobres, e segura-a. Segurou-a, pois, e ele as mediu seis medidas de cevada, e lhas pôs no ombro. Então ela foi para a cidade.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 16, 'Quando chegou à sua sogra, esta lhe perguntou: Como te houveste, minha filha? E ela lhe contou tudo quanto aquele homem lhe fizera.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 17, 'Disse mais: Estas seis medidas de cevada ele mas deu, dizendo: Não voltarás vazia para tua sogra.', 1, CURRENT_TIMESTAMP, false),
(8, 3, 18, 'Então disse Noêmi: Espera, minha filha, até que saibas como irá terminar o caso; porque aquele homem não descansará enquanto não tiver concluído hoje este negócio.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 1, 'Boaz subiu à porta da cidade, e assentou-se ali. Quando o remidor de que ele havia falado ia passando, disse-lhe Boaz: Meu amigo, vem cá, assenta-te aqui. Ele se virou, e se assentou.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 2, 'Então Boaz tomou dez homens dentre os anciãos da cidade, e lhes disse: Sentai-vos aqui. E eles se sentaram.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 3, 'Disse Boaz ao remidor: Noêmi, que voltou da terra dos moabitas, vendeu a parte da terra que pertencia a Elimeleque; nosso irmão.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 4, 'Resolvi informar-te disto, e dizer-te: Compra-a na presença dos que estão sentados aqui, na presença dos anciãos do meu povo; se hás de redimi-la, redime-a, e se não, declara-mo, para que o saiba, pois outro não há, senão tu, que a redima, e eu depois de ti. Então disse ele: Eu a redimirei.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 5, 'Disse, porém, Boaz: No dia em que comprares o campo da mão de Noêmi, também tomarás a Rute, a moabita, que foi mulher do falecido, para suscitar o nome dele na sua herança.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 6, 'Então disse o remidor: Não poderei redimi-lo para mim, para que não prejudique a minha própria herança; toma para ti o meu direito de remissão, porque eu não o posso fazer.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 7, 'Outrora em Israel, para confirmar qualquer negócio relativo à remissão e à permuta, o homem descalçava o sapato e o dava ao seu próximo; e isto era por testemunho em Israel.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 8, 'Dizendo, pois, o remidor a Boaz: Compra-a para ti, descalçou o sapato.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 9, 'Então Boaz disse aos anciãos e a todo o povo: Sois hoje testemunhas de que comprei tudo quanto foi de Elimeleque, e de Quiliom, e de Malom, da mão de Noêmi,', 1, CURRENT_TIMESTAMP, false),
(8, 4, 10, 'e de que também tomei por mulher a Rute, a moabita, que foi mulher de Malom, para suscitar o nome do falecido na sua herança, para que a nome dele não seja desarraigado dentre seus irmãos e da porta do seu lugar; disto sois hoje testemunhas.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 11, 'Ao que todo o povo que estava na porta e os anciãos responderam: Somos testemunhas. O Senhor faça a esta mulher, que entra na tua casa, como a Raquel e a Léia, que juntas edificaram a casa de Israel. Porta-te valorosamente em Efrata, e faze-te nome afamado em Belém.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 12, 'Também seja a tua casa como a casa de Pérez, que Tamar deu a Judá, pela posteridade que o Senhor te der desta moça.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 13, 'Assim tomou Boaz a Rute, e ela lhe foi por mulher; ele a conheceu, e o Senhor permitiu a Rute conceber, e ela teve um filho.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 14, 'Disseram então as mulheres a Noêmi: Bendito seja o Senhor, que não te deixou hoje sem remidor; e torne-se o seu nome afamado em Israel.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 15, 'Ele será restaurador da tua vida, e consolador da tua velhice, pois tua nora, que te ama, o deu à luz; ela te é melhor do que sete filhos.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 16, 'E Noêmi tomou o menino, pô-lo no seu regaço, e foi sua ama.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 17, 'E as vizinhas deram-lhe nome, dizendo: A Noêmi nasceu um filho, E chamaram ao menino Obede. Este é o pai de Jessé, pai de Davi.', 1, CURRENT_TIMESTAMP, false),
(8, 4, 18, 'São estas as gerações de Pérez: Pérez gerou a Hezrom,', 1, CURRENT_TIMESTAMP, false),
(8, 4, 19, 'Hezrom gerou a Rão, Rão gerou a Aminadabe,', 1, CURRENT_TIMESTAMP, false),
(8, 4, 20, 'Aminadabe gereu a Nasom, Nasom gerou a Salmom,', 1, CURRENT_TIMESTAMP, false),
(8, 4, 21, 'Salmom gerou a Boaz, Boaz gerou a Obede,', 1, CURRENT_TIMESTAMP, false),
(8, 4, 22, 'Obede gerou a Jessé, e Jessé gerou a Davi.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 1, 'A palavra do Senhor que veio a Sofonias, filho de Cuche, filho de Gedalias, filho de Amarias, filho de Ezequias, nos dias de Josias, filho de Amom, rei de Judá.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 2, 'Hei de consumir por completo tudo sobre a face da terra, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 3, 'Consumirei os homens e os animais; consumirei as aves do céu, e os peixes do mar, e os tropeços juntamente com os ímpios; e exterminarei os homens de sobre a face da terra, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 4, 'E estenderei a minha mão contra Judá, e contra todos os habitantes de Jerusalém; e exterminarei deste lugar o resto de Baal, e os nomes dos sacerdotes de ídolos, juntamente com os sacerdotes;', 1, CURRENT_TIMESTAMP, false),
(36, 1, 5, 'e os que sobre os telhados adoram o exército do céu, e aqueles adoradores que juram ao Senhor, e juram por Milcom;', 1, CURRENT_TIMESTAMP, false),
(36, 1, 6, 'e os que deixam de seguir ao Senhor, e os que não buscam ao Senhor, nem perguntam por ele.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 7, 'Cala-te diante do Senhor Deus, porque o dia do Senhor está perto; pois o Senhor tem preparado um sacrifício, e tem santificado os seus convidados.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 8, 'E no dia do sacrifício do Senhor castigarei os oficiais, e os filhos do rei, e todos os que se vestem de trajes estrangeiros.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 9, 'Castigarei também naquele dia todos aqueles que saltam sobre o umbral, que enchem de violência e de dolo a casa do seu senhor.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 10, 'E naquele dia, diz o Senhor, far-se-á ouvir uma voz de clamor desde a porta dos peixes, e um uivo desde a segunda parte, e grande estrépito desde os outeiros.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 11, 'Uivai vós, moradores de Mactes, porque todo o povo de Canaã está arruinado; todos os que pesam a prata são destruídos.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 12, 'E há de ser que, naquele tempo, esquadrinharei a Jerusalém com lanternas, e castigarei os homens que se embrutecem com as fezes do vinho, que dizem no seu coração: O Senhor não faz o bem nem faz o mal.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 13, 'Por isso as riquezas deles se tornarão em despojo e as suas casas em desolação; e edificarão casas, mas não habitarão nelas; e plantarão vinhas, mas não lhes beberão o vinho.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 14, 'O grande dia do Senhor está perto; sim, está perto, e se apressa muito; ei-la, amarga é a voz do dia do Senhor; clama ali o homem poderoso.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 15, 'Aquele dia é dia de indignação, dia de tribulação e de angústia, dia de alvoroço e de assolação, dia de trevas e de escuridão, dia de nuvens e de densas trevas,', 1, CURRENT_TIMESTAMP, false),
(36, 1, 16, 'dia de trombeta e de alarido contra as cidades fortificadas e contra as torres altas.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 17, 'E angustiarei os homens, e eles andarão como cegos, porque pecaram contra o Senhor; e o seu sangue se derramará como pó, e a sua carne como esterco.', 1, CURRENT_TIMESTAMP, false),
(36, 1, 18, 'Nem a sua prata nem o seu ouro os poderá livrar no dia da indignação do Senhor; mas pelo fogo do seu zelo será devorada toda a terra; porque certamente fará de todos os moradores da terra uma destruição total e apressada.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 1, 'Congregai-vos, sim, congregai-vos, ó nação sem pudor;', 1, CURRENT_TIMESTAMP, false),
(36, 2, 2, 'antes que o decreto produza efeito, e o dia passe como a pragana; antes que venha sobre vós o furor da ira do Senhor, sim, antes que venha sobre vós o dia da ira do Senhor.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 3, 'Buscai ao Senhor, vós todos os mansos da terra, que tendes posto por obra o seu juizo; buscai a justiça, buscai a mansidão; porventura sereis escondidos no dia da ira do Senhor.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 4, 'Pois Gaza será desamparada, e Asquelom assolada; Asdode ao meio-dia será expelida, e Ecrom desarraigada.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 5, 'Ai dos habitantes da borda do mar, da nação dos quereteus! A palavra do Senhor é contra vós, ó Canaã, terra dos filisteus; e eu vos destruirei, sem que fique sequer um habitante.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 6, 'E a borda do mar será de pastagens, com cabanas para os pastores, e currais para os rebanhos.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 7, 'E será a costa para o restante da casa de Judá, para que eles se apascentem ali; de tarde se deitarão nas casas de Asquelom; pois o Senhor seu Deus os visitará, e os fará tornar do seu cativeiro.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 8, 'Eu ouvi o escárnio de Moabe, e os ultrajes dos filhos de Amom, com que escarneceram do meu povo, e se engrandeceram contra o seu termo.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 9, 'Portanto diz o Senhor dos exércitos, o Deus de Israel: Tão certo como eu vivo, Moabe será como Sodoma, e os filhos de Amom como Gomorra, campo de urtigas e poços de sal, e desolação perpétua; o restante do meu povo os saqueará, e o restante da minha nação os possuíra.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 10, 'Isso terão em recompensa da sua soberba, porque usaram de escárnios, e se engrandeceram contra o povo do Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 11, 'O Senhor se mostrará terrível contra eles; pois aniquilará todos os deuses da terra, e adorá-lo-ão, cada uma desde o seu lugar, todas as ilhas das nações.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 12, 'Também vós, ó etíopes, sereis mortos pela minha espada.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 13, 'Ainda ele estenderá a mão contra o Norte, e destruirá a Assíria; e fará de Nínive uma desolação, terra árida como o deserto.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 14, 'E no meio dela se deitarão manadas, todas as feras do campo; e alojar-se-ão nos capitéis dela tanto o pelicano como o ouriço; a voz das aves se ouvirá nas janelas; e haverá desolação nos limiares; pois ele tem posto a descoberto a obra de cedro.', 1, CURRENT_TIMESTAMP, false),
(36, 2, 15, 'Esta é a cidade alegre, que vivia em segurança, que dizia no seu coração: Eu sou, e fora de mim não há outra. Como se tem ela tornado em desolação, em covil de feras! Todo o que passar por ela assobiará, e meneará a mão', 1, CURRENT_TIMESTAMP, false),
(36, 3, 1, 'Ai da rebelde e contaminada, da cidade opressora!', 1, CURRENT_TIMESTAMP, false),
(36, 3, 2, 'Não escuta a voz, não aceita a correção, não confia no Senhor, nem se aproxima do seu Deus.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 3, 'Os seus oficiais são leões rugidores no meio dela; os seus juízes são lobos da tarde, que nada deixam para o dia seguinte.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 4, 'Os seus profetas são levianos, homens aleivosos; os seus sacerdotes profanam o santuário, e fazem violência à lei.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 5, 'O Senhor é justo no meio dela; ele não comete iniqüidade; cada manhã traz o seu juízo à luz; nunca falta; o injusto, porém, não conhece a vergonha.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 6, 'Exterminei as nações, as suas torres estão assoladas; fiz desertas as suas praças a ponto de não ficar quem passe por elas; as suas cidades foram destruídas, até não ficar ninguém, até não haver quem as habite.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 7, 'Eu dizia: Certamente me temerás e aceitarás a correção; e assim a sua morada não seria destruída, conforme tudo o que eu havia determinado a respeito dela. Mas eles se levantaram de madrugada, e corromperam todas as suas obras.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 8, 'Portanto esperai-me a mim, diz o Senhor, no dia em que eu me levantar para o despojo; porque o meu intento é ajuntar nações e congregar reinos, para sobre eles derramar a minha indignação, e todo o ardor da minha ira; pois esta terra toda será consumida pelo fogo do meu zelo.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 9, 'Pois então darei lábios puros aos povos, para que todos invoquem o nome do Senhor, e o sirvam com o mesmo espírito.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 10, 'Dalém dos rios da Etiópia os meus adoradores, a saber, a filha dos meus dispersos, trarão a minha oferta.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 11, 'Naquele dia não te envergonharás de nenhuma das tuas obras, com que te rebelaste contra mim; porque então tirarei do meio de ti, os que exultam arrogantemente, e tu nunca mais te ensoberbeceras no meu santo monte.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 12, 'Mas deixarei no meio de ti um povo humilde e pobre; e eles confiarão no nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 13, 'O remanescente de Israel não cometerá iniqüidade, nem proferirá mentira, e na sua boca não se achará língua enganosa; pois serão apascentados, e se deitarão, e não haverá quem os espante.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 14, 'Canta alegremente, ó filha de Sião; rejubila, ó Israel; regozija-te, e exulta de todo o coração, ó filha de Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 15, 'O Senhor afastou os juízos que havia contra ti, lançou fora o teu inimigo; o Rei de Israel, o Senhor, está no meio de ti; não temerás daqui em diante mal algum.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 16, 'Naquele dia se dirá a Jerusalém: Não temas, ó Sião; não se enfraqueçam as tuas mãos.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 17, 'O Senhor teu Deus está no meio de ti, poderoso para te salvar; ele se deleitará em ti com alegria; renovar-te-á no seu amor, regozijar-se-á em ti com júbilo.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 18, 'Os que em tristeza suspiram pela assembléia solene, os quais te pertenciam, eu os congregarei; esses para os quais era um opróbrio o peso que estava sobre ela.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 19, 'Eis que naquele tempo procederei contra todos os que te afligem; e salvarei a que coxeia, e recolherei a que foi expulsa; e deles farei um louvor e um nome em toda a terra em que têm sido envergonhados.', 1, CURRENT_TIMESTAMP, false),
(36, 3, 20, 'Naquele tempo vos trarei, naquele tempo vos recolherei; porque farei de vós um nome e um louvor entre todos os povos da terra, quando eu tornar o vosso cativeiro diante dos vossos olhos, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 1, 'Tiago, servo de Deus e do Senhor Jesus Cristo, às doze tribos da Dispersão, saúde.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 2, 'Meus irmãos, tende por motivo de grande gozo o passardes por várias provações,', 1, CURRENT_TIMESTAMP, false),
(59, 1, 3, 'sabendo que a aprovação da vossa fé produz a perseverança;', 1, CURRENT_TIMESTAMP, false),
(59, 1, 4, 'e a perseverança tenha a sua obra perfeita, para que sejais perfeitos e completos, não faltando em coisa alguma.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 5, 'Ora, se algum de vós tem falta de sabedoria, peça-a a Deus, que a todos dá liberalmente e não censura, e ser-lhe-á dada.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 6, 'Peça-a, porém, com fé, não duvidando; pois aquele que duvida é semelhante à onda do mar, que é sublevada e agitada pelo vento.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 7, 'Não pense tal homem que receberá do Senhor alguma coisa,', 1, CURRENT_TIMESTAMP, false),
(59, 1, 8, 'homem vacilante que é, e inconstante em todos os seus caminhos.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 9, 'Mas o irmão de condição humilde glorie-se na sua exaltação,', 1, CURRENT_TIMESTAMP, false),
(59, 1, 10, 'e o rico no seu abatimento; porque ele passará como a flor da erva.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 11, 'Pois o sol se levanta em seu ardor e faz secar a erva; a sua flor cai e a beleza do seu aspecto perece; assim murchará também o rico em seus caminhos.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 12, 'Bem-aventurado o homem que suporta a provação; porque, depois de aprovado, receberá a coroa da vida, que o Senhor prometeu aos que o amam.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 13, 'Ninguém, sendo tentado, diga: Sou tentado por Deus; porque Deus não pode ser tentado pelo mal e ele a ninguém tenta.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 14, 'Cada um, porém, é tentado, quando atraído e engodado pela sua própria concupiscência;', 1, CURRENT_TIMESTAMP, false),
(59, 1, 15, 'então a concupiscência, havendo concebido, dá à luz o pecado; e o pecado, sendo consumado, gera a morte.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 16, 'Não vos enganeis, meus amados irmãos.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 17, 'Toda boa dádiva e todo dom perfeito vêm do alto, descendo do Pai das luzes, em quem não há mudança nem sombra de variação.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 18, 'Segundo a sua própria vontade, ele nos gerou pela palavra da verdade, para que fôssemos como que primícias das suas criaturas.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 19, 'Sabei isto, meus amados irmãos: Todo homem seja pronto para ouvir, tardio para falar e tardio para se irar.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 20, 'Porque a ira do homem não opera a justiça de Deus.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 21, 'Pelo que, despojando-vos de toda sorte de imundícia e de todo vestígio do mal, recebei com mansidão a palavra em vós implantada, a qual é poderosa para salvar as vossas almas.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 22, 'E sede cumpridores da palavra e não somente ouvintes, enganando-vos a vós mesmos.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 23, 'Pois se alguém é ouvinte da palavra e não cumpridor, é semelhante a um homem que contempla no espelho o seu rosto natural;', 1, CURRENT_TIMESTAMP, false),
(59, 1, 24, 'porque se contempla a si mesmo e vai-se, e logo se esquece de como era.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 25, 'Entretanto aquele que atenta bem para a lei perfeita, a da liberdade, e nela persevera, não sendo ouvinte esquecido, mas executor da obra, este será bem-aventurado no que fizer.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 26, 'Se alguém cuida ser religioso e não refreia a sua língua, mas engana o seu coração, a sua religião é vã.', 1, CURRENT_TIMESTAMP, false),
(59, 1, 27, 'A religião pura e imaculada diante de nosso Deus e Pai é esta: Visitar os órfãos e as viúvas nas suas aflições e guardar-se isento da corrupção do mundo.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 1, 'Meus irmãos, não tenhais a fé em nosso Senhor Jesus Cristo, Senhor da glória, em acepção de pessoas.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 2, 'Porque, se entrar na vossa reunião algum homem com anel de ouro no dedo e com traje esplêndido, e entrar também algum pobre com traje sórdido.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 3, 'e atentardes para o que vem com traje esplêndido e lhe disserdes: Senta-te aqui num lugar de honra; e disserdes ao pobre: Fica em pé, ou senta-te abaixo do escabelo dos meus pés,', 1, CURRENT_TIMESTAMP, false),
(59, 2, 4, 'não fazeis, porventura, distinção entre vós mesmos e não vos tornais juizes movidos de maus pensamentos?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 5, 'Ouvi, meus amados irmãos. Não escolheu Deus os que são pobres quanto ao mundo para fazê-los ricos na fé e herdeiros do reino que prometeu aos que o amam?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 6, 'Mas vós desonrastes o pobre. Porventura não são os ricos os que vos oprimem e os que vos arrastam aos tribunais?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 7, 'Não blasfemam eles o bom nome pelo qual sois chamados?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 8, 'Todavia, se estais cumprindo a lei real segundo a escritura: Amarás ao teu próximo como a ti mesmo, fazeis bem.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 9, 'Mas se fazeis acepção de pessoas, cometeis pecado, sendo por isso condenados pela lei como transgressores.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 10, 'Pois qualquer que guardar toda a lei, mas tropeçar em um só ponto, tem-se tornado culpado de todos.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 11, 'Porque o mesmo que disse: Não adulterarás, também disse: Não matarás. Ora, se não cometes adultério, mas és homicida, te hás tornado transgressor da lei.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 12, 'Falai de tal maneira e de tal maneira procedei, como havendo de ser julgados pela lei da liberdade.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 13, 'Porque o juízo será sem misericórdia para aquele que não usou de misericórdia; a misericórdia triunfa sobre o juízo.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 14, 'Que proveito há, meus irmãos se alguém disser que tem fé e não tiver obras? Porventura essa fé pode salvá-lo?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 15, 'Se um irmão ou uma irmã estiverem nus e tiverem falta de mantimento cotidiano,', 1, CURRENT_TIMESTAMP, false),
(59, 2, 16, 'e algum de vós lhes disser: Ide em paz, aquentai-vos e fartai-vos; e não lhes derdes as coisas necessárias para o corpo, que proveito há nisso?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 17, 'Assim também a fé, se não tiver obras, é morta em si mesma.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 18, 'Mas dirá alguém: Tu tens fé, e eu tenho obras; mostra-me a tua fé sem as obras, e eu te mostrarei a minha fé pelas minhas obras.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 19, 'Crês tu que Deus é um só? Fazes bem; os demônios também o crêem, e estremecem.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 20, 'Mas queres saber, ó homem insensato, que a fé sem as obras é inútil?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 21, 'Porventura não foi pelas obras que nosso pai Abraão foi justificado quando ofereceu sobre o altar seu filho Isaque?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 22, 'Vês que a fé cooperou com as suas obras, e que pelas obras a fé foi aperfeiçoada.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 23, 'E se cumpriu a escritura que diz: E creu Abraão em Deus, e isso lhe foi imputado como justiça, e foi chamado amigo de Deus.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 24, 'Vedes então que é pelas obras que o homem é justificado, e não somente pela fé.', 1, CURRENT_TIMESTAMP, false),
(59, 2, 25, 'E de igual modo não foi a meretriz Raabe também justificada pelas obras, quando acolheu os espias, e os fez sair por outro caminho?', 1, CURRENT_TIMESTAMP, false),
(59, 2, 26, 'Porque, assim como o corpo sem o espírito está morto, assim também a fé sem obras é morta.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 1, 'Meus irmãos, não sejais muitos de vós mestres, sabendo que receberemos um juízo mais severo.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 2, 'Todos tropeçamos em muitas coisas. Se alguém não tropeça em palavra, esse é homem perfeito, e capaz de refrear também todo o corpo.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 3, 'Ora, se pomos freios na boca dos cavalos, para que nos obedeçam, então conseguimos dirigir todo o seu corpo.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 4, 'Vede também os navios que, embora tão grandes e levados por impetuosos ventos, com um pequenino leme se voltam para onde quer o impulso do timoneiro.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 5, 'Assim também a língua é um pequeno membro, e se gaba de grandes coisas. Vede quão grande bosque um tão pequeno fogo incendeia.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 6, 'A língua também é um fogo; sim, a língua, qual mundo de iniqüidade, colocada entre os nossos membros, contamina todo o corpo, e inflama o curso da natureza, sendo por sua vez inflamada pelo inferno.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 7, 'Pois toda espécie tanto de feras, como de aves, tanto de répteis como de animais do mar, se doma, e tem sido domada pelo gênero humano,', 1, CURRENT_TIMESTAMP, false),
(59, 3, 8, 'mas a língua, nenhum homem a pode domar. É um mal irrefreável; está cheia de peçonha mortal.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 9, 'Com ela bendizemos ao Senhor e Pai, e com ela amaldiçoamos os homens, feitos à semelhança de Deus.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 10, 'Da mesma boca procede bênção e maldição. Não convém, meus irmãos, que se faça assim.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 11, 'Porventura a fonte deita da mesma abertura água doce e água amargosa?', 1, CURRENT_TIMESTAMP, false),
(59, 3, 12, 'Meus irmãos, pode acaso uma figueira produzir azeitonas, ou uma videira figos? Nem tampouco pode uma fonte de água salgada dar água doce.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 13, 'Quem dentre vós é sábio e entendido? Mostre pelo seu bom procedimento as suas obras em mansidão de sabedoria.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 14, 'Mas, se tendes amargo ciúme e sentimento faccioso em vosso coração, não vos glorieis, nem mintais contra a verdade.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 15, 'Essa não é a sabedoria que vem do alto, mas é terrena, animal e diabólica.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 16, 'Porque onde há ciúme e sentimento faccioso, aí há confusão e toda obra má.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 17, 'Mas a sabedoria que vem do alto é, primeiramente, pura, depois pacífica, moderada, tratável, cheia de misericórdia e de bons frutos, sem parcialidade, e sem hipocrisia.', 1, CURRENT_TIMESTAMP, false),
(59, 3, 18, 'Ora, o fruto da justiça semeia-se em paz para aqueles que promovem a paz.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 1, 'Donde vêm as guerras e contendas entre vós? Porventura não vêm disto, dos vossos deleites, que nos vossos membros guerreiam?', 1, CURRENT_TIMESTAMP, false),
(59, 4, 2, 'Cobiçais e nada tendes; logo matais. Invejais, e não podeis alcançar; logo combateis e fazeis guerras. Nada tendes, porque não pedis.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 3, 'Pedis e não recebeis, porque pedis mal, para o gastardes em vossos deleites.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 4, 'Infiéis, não sabeis que a amizade do mundo é inimizade contra Deus? Portanto qualquer que quiser ser amigo do mundo constitui-se inimigo de Deus.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 5, 'Ou pensais que em vão diz a escritura: O Espírito que ele fez habitar em nós anseia por nós até o ciúme?', 1, CURRENT_TIMESTAMP, false),
(59, 4, 6, 'Todavia, dá maior graça. Portanto diz: Deus resiste aos soberbos; dá, porém, graça aos humildes.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 7, 'Sujeitai-vos, pois, a Deus; mas resisti ao Diabo, e ele fugirá de vós.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 8, 'Chegai-vos para Deus, e ele se chegará para vós. Limpai as mãos, pecadores; e, vós de espírito vacilante, purificai os corações.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 9, 'Senti as vossas misérias, lamentai e chorai; torne-se o vosso riso em pranto, e a vossa alegria em tristeza.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 10, 'Humilhai-vos perante o Senhor, e ele vos exaltará.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 11, 'Irmãos, não faleis mal uns dos outros. Quem fala mal de um irmão, e julga a seu irmão, fala mal da lei, e julga a lei; ora, se julgas a lei, não és observador da lei, mas juiz.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 12, 'Há um só legislador e juiz, aquele que pode salvar e destruir; tu, porém, quem és, que julgas ao próximo?', 1, CURRENT_TIMESTAMP, false),
(59, 4, 13, 'E agora, vós que dizeis: Hoje ou amanhã iremos a tal cidade, lá passaremos um ano, negociaremos e ganharemos.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 14, 'No entanto, não sabeis o que sucederá amanhã. Que é a vossa vida? Sois um vapor que aparece por um pouco, e logo se desvanece.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 15, 'Em lugar disso, devíeis dizer: Se o Senhor quiser, viveremos e faremos isto ou aquilo.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 16, 'Mas agora vos jactais das vossas presunções; toda jactância tal como esta é maligna.', 1, CURRENT_TIMESTAMP, false),
(59, 4, 17, 'Aquele, pois, que sabe fazer o bem e não o faz, comete pecado.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 1, 'E agora, vós ricos, chorai e pranteai, por causa das desgraças que vos sobrevirão.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 2, 'As vossas riquezas estão apodrecidas, e as vossas vestes estão roídas pela traça.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 3, 'O vosso ouro e a vossa prata estão enferrujados; e a sua ferrugem dará testemunho contra vós, e devorará as vossas carnes como fogo. Entesourastes para os últimos dias.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 4, 'Eis que o salário que fraudulentamente retivestes aos trabalhadores que ceifaram os vossos campos clama, e os clamores dos ceifeiros têm chegado aos ouvidos do Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 5, 'Deliciosamente vivestes sobre a terra, e vos deleitastes; cevastes os vossos corações no dia da matança.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 6, 'Condenastes e matastes o justo; ele não vos resiste.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 7, 'Portanto, irmãos, sede pacientes até a vinda do Senhor. Eis que o lavrador espera o precioso fruto da terra, aguardando-o com paciência, até que receba as primeiras e as últimas chuvas.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 8, 'Sede vós também pacientes; fortalecei os vossos corações, porque a vinda do Senhor está próxima.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 9, 'Não vos queixeis, irmãos, uns dos outros, para que não sejais julgados. Eis que o juiz está à porta.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 10, 'Irmãos, tomai como exemplo de sofrimento e paciência os profetas que falaram em nome do Senhor.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 11, 'Eis que chamamos bem-aventurados os que suportaram aflições. Ouvistes da paciência de Jó, e vistes o fim que o Senhor lhe deu, porque o Senhor é cheio de misericórdia e compaixão.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 12, 'Mas, sobretudo, meus irmãos, não jureis, nem pelo céu, nem pela terra, nem façais qualquer outro juramento; seja, porém, o vosso sim, sim, e o vosso não, não, para não cairdes em condenação.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 13, 'Está aflito alguém entre vós? Ore. Está alguém contente? Cante louvores.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 14, 'Está doente algum de vós? Chame os anciãos da igreja, e estes orem sobre ele, ungido-o com óleo em nome do Senhor;', 1, CURRENT_TIMESTAMP, false),
(59, 5, 15, 'e a oração da fé salvará o doente, e o Senhor o levantará; e, se houver cometido pecados, ser-lhe-ão perdoados.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 16, 'Confessai, portanto, os vossos pecados uns aos outros, e orai uns pelos outros, para serdes curados. A súplica de um justo pode muito na sua atuação.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 17, 'Elias era homem sujeito às mesmas paixões que nós, e orou com fervor para que não chovesse, e por três anos e seis meses não choveu sobre a terra.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 18, 'E orou outra vez e o céu deu chuva, e a terra produziu o seu fruto.', 1, CURRENT_TIMESTAMP, false),
(59, 5, 19, 'Meus irmãos, se alguém dentre vós se desviar da verdade e alguém o converter,', 1, CURRENT_TIMESTAMP, false),
(59, 5, 20, 'sabei que aquele que fizer converter um pecador do erro do seu caminho salvará da morte uma alma, e cobrirá uma multidão de pecados.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 1, 'Paulo, servo de Deus, e apóstolo de Jesus Cristo, segundo a fé dos eleitos de Deus, e o pleno conhecimento da verdade que é segundo a piedade,', 1, CURRENT_TIMESTAMP, false),
(56, 1, 2, 'na esperança da vida eterna, a qual Deus, que não pode mentir, prometeu antes dos tempos eternos,', 1, CURRENT_TIMESTAMP, false),
(56, 1, 3, 'e no tempo próprio manifestou a sua palavra, mediante a pregação que me foi confiada segundo o mandamento de Deus, nosso Salvador;', 1, CURRENT_TIMESTAMP, false),
(56, 1, 4, 'a Tito, meu verdadeiro filho segundo a fé que nos é comum, graça e paz da parte de Deus Pai, e de Cristo Jesus, nosso Salvador.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 5, 'Por esta causa te deixei em Creta, para que pusesses em boa ordem o que ainda não o está, e que em cada cidade estabelecesses anciãos, como já te mandei;', 1, CURRENT_TIMESTAMP, false),
(56, 1, 6, 'alguém que seja irrepreensível, marido de uma só mulher, tendo filhos crentes que não sejam acusados de dissolução, nem sejam desobedientes.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 7, 'Pois é necessário que o bispo seja irrepreensível, como despenseiro de Deus, não soberbo, nem irascível, nem dado ao vinho, nem espancador, nem cobiçoso de torpe ganância;', 1, CURRENT_TIMESTAMP, false),
(56, 1, 8, 'mas hospitaleiro, amigo do bem, sóbrio, justo, piedoso, temperante;', 1, CURRENT_TIMESTAMP, false),
(56, 1, 9, 'retendo firme a palavra fiel, que é conforme a doutrina, para que seja poderoso, tanto para exortar na sã doutrina como para convencer os contradizentes.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 10, 'Porque há muitos insubordinados, faladores vãos, e enganadores, especialmente os da circuncisão,', 1, CURRENT_TIMESTAMP, false),
(56, 1, 11, 'aos quais é preciso tapar a boca; porque transtornam casas inteiras ensinando o que não convém, por torpe ganância.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 12, 'Um dentre eles, seu próprio profeta, disse: Os cretenses são sempre mentirosos, bestas ruins, glutões preguiçosos.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 13, 'Este testemunho é verdadeiro. Portanto repreende-os severamente, para que sejam são na fé,', 1, CURRENT_TIMESTAMP, false),
(56, 1, 14, 'não dando ouvidos a fábulas judaicas, nem a mandamentos de homens que se desviam da verdade.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 15, 'Tudo é puro para os que são puros, mas para os corrompidos e incrédulos nada é puro; antes tanto a sua mente como a sua consciência estão contaminadas.', 1, CURRENT_TIMESTAMP, false),
(56, 1, 16, 'Afirmam que conhecem a Deus, mas pelas suas obras o negam, sendo abomináveis, e desobedientes, e réprobos para toda boa obra.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 1, 'Tu, porém, fala o que convém à sã doutrina.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 2, 'Exorta os velhos a que sejam temperantes, sérios, sóbrios, sãos na fé, no amor, e na constância;', 1, CURRENT_TIMESTAMP, false),
(56, 2, 3, 'as mulheres idosas, semelhantemente, que sejam reverentes no seu viver, não caluniadoras, não dadas a muito vinho, mestras do bem,', 1, CURRENT_TIMESTAMP, false),
(56, 2, 4, 'para que ensinem as mulheres novas a amarem aos seus maridos e filhos,', 1, CURRENT_TIMESTAMP, false),
(56, 2, 5, 'a serem moderadas, castas, operosas donas de casa, bondosas, submissas a seus maridos, para que a palavra de Deus não seja blasfemada.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 6, 'Exorta semelhantemente os moços a que sejam moderados.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 7, 'Em tudo te dá por exemplo de boas obras; na doutrina mostra integridade, sobriedade,', 1, CURRENT_TIMESTAMP, false),
(56, 2, 8, 'linguagem sã e irrepreensível, para que o adversário se confunda, não tendo nenhum mal que dizer de nós.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 9, 'Exorta os servos a que sejam submissos a seus senhores em tudo, sendo-lhes agradáveis, não os contradizendo', 1, CURRENT_TIMESTAMP, false),
(56, 2, 10, 'nem defraudando, antes mostrando perfeita lealdade, para que em tudo sejam ornamento da doutrina de Deus nosso Salvador.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 11, 'Porque a graça de Deus se manifestou, trazendo salvação a todos os homens,', 1, CURRENT_TIMESTAMP, false),
(56, 2, 12, 'ensinando-nos, para que, renunciando à impiedade e às paixões mundanas, vivamos no presente mundo sóbria, e justa, e piamente,', 1, CURRENT_TIMESTAMP, false),
(56, 2, 13, 'aguardando a bem-aventurada esperança e o aparecimento da glória do nosso grande Deus e Salvador Cristo Jesus,', 1, CURRENT_TIMESTAMP, false),
(56, 2, 14, 'que se deu a si mesmo por nós para nos remir de toda a iniqüidade, e purificar para si um povo todo seu, zeloso de boas obras.', 1, CURRENT_TIMESTAMP, false),
(56, 2, 15, 'Fala estas coisas, exorta e repreende com toda autoridade. Ninguém te despreze.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 1, 'Adverte-lhes que estejam sujeitos aos governadores e autoridades, que sejam obedientes, e estejam preparados para toda boa obra,', 1, CURRENT_TIMESTAMP, false),
(56, 3, 2, 'que a ninguém infamem, nem sejam contenciosos, mas moderados, mostrando toda a mansidão para com todos os homens.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 3, 'Porque também nós éramos outrora insensatos, desobedientes, extraviados, servindo a várias paixões e deleites, vivendo em malícia e inveja odiosos e odiando-nos uns aos outros.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 4, 'Mas quando apareceu a bondade de Deus, nosso Salvador e o seu amor para com os homens,', 1, CURRENT_TIMESTAMP, false),
(56, 3, 5, 'não em virtude de obras de justiça que nós houvéssemos feito, mas segundo a sua misericórdia, nos salvou mediante o lavar da regeneração e renovação pelo Espírito Santo,', 1, CURRENT_TIMESTAMP, false),
(56, 3, 6, 'que ele derramou abundantemente sobre nós por Jesus Cristo, nosso Salvador;', 1, CURRENT_TIMESTAMP, false),
(56, 3, 7, 'para que, sendo justificados pela sua graça, fôssemos feitos herdeiros segundo a esperança da vida eterna.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 8, 'Fiel é esta palavra, e quero que a proclames com firmeza para que os que crêem em Deus procurem aplicar-se às boas obras. Essas coisas são boas e proveitosas aos homens.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 9, 'Mas evita questões tolas, genealogias, contendas e debates acerca da lei; porque são coisas inúteis e vãs.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 10, 'Ao homem faccioso, depois da primeira e segunda admoestação, evita-o,', 1, CURRENT_TIMESTAMP, false),
(56, 3, 11, 'sabendo que esse tal está pervertido, e vive pecando, e já por si mesmo está condenado.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 12, 'Quando te enviar Ártemas, ou Tíquico, apressa-te a vir ter comigo a Nicópolis; porque tenho resolvido invernar ali.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 13, 'Ajuda com empenho a Zenas, doutor da lei, e a Apolo, para que nada lhes falte na sua viagem.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 14, 'Que os nossos também aprendam a aplicar-se às boas obras, para suprir as coisas necessárias, a fim de que não sejam infrutuosos.', 1, CURRENT_TIMESTAMP, false),
(56, 3, 15, 'Saúdam-te todos os que estão comigo. Saúda aqueles que nos amam na fé. A graça seja com todos vós.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 1, 'No oitavo mês do segundo ano de Dario veio a palavra do Senhor ao profeta Zacarias, filho de Berequias, filho de Ido, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 1, 2, 'O Senhor se irou fortemente contra vossos pais.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 3, 'Portanto dize-lhes: Assim diz o Senhor dos exércitos: Tornai-vos para mim, diz o Senhor dos exércitos, e eu me tornarei para vós, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 4, 'Não sejais como vossos pais, aos quais clamavam os profetas antigos, dizendo: Assim diz o Senhor dos exércitos: Convertei-vos agora dos vossos maus caminhos e das vossas más obras; mas não ouviram, nem me atenderam, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 5, 'Vossos pais, onde estão eles? E os profetas, viverão eles para sempre?', 1, CURRENT_TIMESTAMP, false),
(38, 1, 6, 'Contudo as minhas palavras e os meus estatutos, que eu ordenei pelos profetas, meus servos, acaso não alcançaram a vossos pais? E eles se arrependeram, e disseram: Assim como o Senhor dos exércitos fez tenção de nos tratar, segundo os nossos caminhos, e segundo as nossas obras, assim ele nos tratou.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 7, 'Aos vinte e quatro dias do mês undécimo, que é o mês de sebate, no segundo ano de Dario, veio a palavra do Senhor ao profeta Zacarias, filho de Berequias, filho de Ido, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 1, 8, 'Olhei de noite, e vi um homem montado num cavalo vermelho, e ele estava parado entre as murtas que se achavam no vale; e atrás dele estavam cavalos vermelhos, baios e brancos.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 9, 'Então perguntei: Meu Senhor, quem são estes? Respondeu-me o anjo que falava comigo: Eu te mostrarei o que estes são.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 10, 'Respondeu, pois, o homem que estava parado entre as murtas, e disse: Estes são os que o Senhor tem enviado para percorrerem a terra.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 11, 'E eles responderam ao anjo do Senhor, que estava parado entre as murtas, e disseram: Nós temos percorrido a terra, e eis que a terra toda está tranqüila e em descanso.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 12, 'Então o anjo do Senhor respondeu, e disse: O Senhor dos exércitos, até quando não terás compaixão de Jerusalém, e das cidades de Judá, contra as quais estiveste indignado estes setenta anos?', 1, CURRENT_TIMESTAMP, false),
(38, 1, 13, 'Respondeu o Senhor ao anjo que falava comigo, com palavras boas, palavras consoladoras.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 14, 'O anjo, pois, que falava comigo, disse-me: Clama, dizendo: Assim diz o Senhor dos exércitos: Com grande zelo estou zelando por Jerusalém e por Sião.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 15, 'E estou grandemente indignado contra as nações em descanso; porque eu estava um pouco indignado, mas eles agravaram o mal.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 16, 'Portanto, o Senhor diz assim: Voltei-me, agora, para Jerusalém com misericórdia; nela será edificada a minha casa, diz o Senhor dos exércitos, e o cordel será estendido sobre Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 17, 'Clama outra vez, dizendo: Assim diz o Senhor dos exércitos: As minhas cidades ainda se transbordarão de bens; e o Senhor ainda consolará a Sião, e ainda escolherá a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 18, 'Levantei os meus olhos, e olhei, e eis quatro chifres.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 19, 'Eu perguntei ao anjo que falava comigo: Que é isto? Ele me respondeu: Estes são os chifres que dispersaram a Judá, a Israel e a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 20, 'O Senhor mostrou-me também quatro ferreiros.', 1, CURRENT_TIMESTAMP, false),
(38, 1, 21, 'Então perguntei: Que vêm estes a fazer? Ele respondeu, dizendo: Estes são os chifres que dispersaram Judá, de maneira que ninguém levantou a cabeça; mas estes vieram para os amedrontarem, para derrubarem os chifres das nações que levantaram os seus chifres contra a terra de Judá, a fim de a espalharem.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 1, 'Tornei a levantar os meus olhos, e olhei, e eis um homem que tinha na mão um cordel de medir.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 2, 'Então perguntei: Para onde vais tu? Respondeu-me ele: Para medir Jerusalém, a fim de ver qual é a sua largura e qual o seu comprimento.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 3, 'E eis que saiu o anjo que falava comigo, e outro anjo lhe saiu ao encontro,', 1, CURRENT_TIMESTAMP, false),
(38, 2, 4, 'e lhe disse: Corre, fala a este mancebo, dizendo: Jerusalém será habitada como as aldeias sem muros, por causa da multidão, nela, dos homens e dos animais.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 5, 'Pois eu, diz o Senhor, lhe serei um muro de fogo em redor, e eu, no meio dela, lhe serei a glória.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 6, 'Ah, ah! fugi agora da terra do norte, diz o Senhor, porque vos espalhei como os quatro ventos do céu, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 7, 'Ah! Escapai para Sião, vós que habitais com a filha de Babilônia.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 8, 'Pois assim diz o Senhor dos exércitos: Para obter a glória ele me enviou às nações que vos despojaram; porque aquele que tocar em vós toca na menina do seu olho.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 9, 'Porque eis aí levantarei a minha mão contra eles, e eles virão a ser a presa daqueles que os serviram; assim sabereis vós que o Senhor dos exércitos me enviou.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 10, 'Exulta, e alegra-te, ó filha de Sião; pois eis que venho, e habitarei no meio de ti, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 11, 'E naquele dia muitas nações se ajuntarão ao Senhor, e serão o meu povo; e habitarei no meio de ti, e saberás que o Senhor dos exércitos me enviou a ti.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 12, 'Então o Senhor possuirá a Judá como sua porção na terra santa, e ainda escolherá a Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 2, 13, 'Cale-se, toda a carne, diante do Senhor; porque ele se levantou da sua santa morada.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 1, 'Ele me mostrou o sumo sacerdote Josué, o qual estava diante do anjo do Senhor, e Satanás estava à sua mão direita, para se lhe opor.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 2, 'Mas o anjo do Senhor disse a Satanás: Que o Senhor te repreenda, ó Satanás; sim, o Senhor, que escolheu Jerusalém, te repreenda! Não é este um tição tirado do fogo?', 1, CURRENT_TIMESTAMP, false),
(38, 3, 3, 'Ora Josué, vestido de trajes sujos, estava em pé diante do anjo.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 4, 'Então falando este, ordenou aos que estavam diante dele, dizendo: Tirai-lhe estes trajes sujos. E a Josué disse: Eis que tenho feito com que passe de ti a tua iniqüidade, e te vestirei de trajes festivos.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 5, 'Também disse eu: Ponham-lhe sobre a cabeça uma mitra limpa. Puseram-lhe, pois, sobre a cabeça uma mitra limpa, e vestiram-no; e o anjo do Senhor estava ali de pe.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 6, 'E o anjo do Senhor protestou a Josué, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 3, 7, 'Assim diz o Senhor dos exércitos: Se andares nos meus caminhos, e se observares as minhas ordenanças, também tu julgarás a minha casa, e também guardarás os meus átrios, e te darei lugar entre os que estão aqui.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 8, 'Ouve, pois, Josué, sumo sacerdote, tu e os teus companheiros que se assentam diante de ti, porque são homens portentosos; eis que eu farei vir o meu servo, o Renovo.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 9, 'Pois eis aqui a pedra que pus diante de Josué; sobre esta pedra única estão sete olhos. Eis que eu esculpirei a sua escultura, diz o Senhor dos exércitos, e tirarei a iniqüidade desta terra num só dia.', 1, CURRENT_TIMESTAMP, false),
(38, 3, 10, 'Naquele dia, diz o Senhor dos exércitos, cada um de vós convidará o seu vizinho para debaixo da videira e para debaixo da figueira.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 1, 'Ora o anjo que falava comigo voltou, e me despertou, como a um homem que é despertado do seu sono;', 1, CURRENT_TIMESTAMP, false),
(38, 4, 2, 'e me perguntou: Que vês? Respondi: Olho, e eis um castiçal todo de ouro, e um vaso de azeite em cima, com sete lâmpadas, e há sete canudos que se unem às lâmpadas que estão em cima dele;', 1, CURRENT_TIMESTAMP, false),
(38, 4, 3, 'e junto a ele há duas oliveiras, uma à direita do vaso de azeite, e outra à sua esquerda.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 4, 'Então perguntei ao anjo que falava comigo: Meu senhor, que é isso?', 1, CURRENT_TIMESTAMP, false),
(38, 4, 5, 'Respondeu-me o anjo que falava comigo, e me disse: Não sabes tu o que isso é? E eu disse: Não, meu senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 6, 'Ele me respondeu, dizendo: Esta é a palavra do Senhor a Zorobabel, dizendo: Não por força nem por poder, mas pelo meu Espírito, diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 7, 'Quem és tu, ó monte grande? Diante de Zorobabel tornar-te-ás uma campina; e ele trará a pedra angular com aclamações: Graça, graça a ela.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 8, 'Ainda me veio a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 4, 9, 'As mãos de Zorobabel têm lançado os alicerces desta casa; também as suas mãos a acabarão; e saberás que o Senhor dos exércitos me enviou a vos.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 10, 'Ora, quem despreza o dia das coisas pequenas? pois estes sete se alegrarão, vendo o prumo na mão de Zorobabel. São estes os sete olhos do Senhor, que discorrem por toda a terra.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 11, 'Falei mais, e lhe perguntei: Que são estas duas oliveiras à direita e à esquerda do castiçal?', 1, CURRENT_TIMESTAMP, false),
(38, 4, 12, 'Segunda vez falei-lhe, perguntando: Que são aqueles dois ramos de oliveira, que estão junto aos dois tubos de ouro, e que vertem de si azeite dourado?', 1, CURRENT_TIMESTAMP, false),
(38, 4, 13, 'Ele me respondeu, dizendo: Não sabes o que é isso? E eu disse: Não, meu senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 4, 14, 'Então ele disse: Estes são os dois ungidos, que assistem junto ao Senhor de toda a terra.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 1, 'Tornei a levantar os meus olhos, e olhei, e eis um rolo voante.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 2, 'Perguntou-me o anjo: Que vês? Eu respondi: Vejo um rolo voante, que tem vinte côvados de comprido e dez côvados de largo.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 3, 'Então disse-me ele: Esta é a maldição que sairá pela face de toda a terra: porque daqui, conforme a maldição, será desarraigado todo o que furtar; assim como daqui será desarraigado conforme a maldição todo o que jurar falsamente.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 4, 'Mandá-la-ei, diz o Senhor dos exércitos, e a farei entrar na casa do ladrão, e na casa do que jurar falsamente pelo meu nome; e permanecerá no meio da sua casa, e a consumirá juntamente com a sua madeira e com as suas pedras.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 5, 'Então saiu o anjo, que falava comigo, e me disse: levanta agora os teus olhos, e vê que é isto que sai.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 6, 'Eu perguntei: Que é isto? Respondeu ele: Isto é uma efa que sai. E disse mais: Esta é a iniqüidade em toda a terra.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 7, 'E eis que foi levantada a tampa de chumbo, e uma mulher estava sentada no meio da efa.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 8, 'Prosseguiu o anjo: Esta é a impiedade. E ele a lançou dentro da efa, e pôs sobre a boca desta o peso de chumbo.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 9, 'Então levantei os meus olhos e olhei, e eis que vinham avançando duas mulheres com o vento nas suas asas, pois tinham asas como as da cegonha; e levantaram a efa entre a terra e o céu.', 1, CURRENT_TIMESTAMP, false),
(38, 5, 10, 'Perguntei ao anjo que falava comigo: Para onde levam elas a efa?', 1, CURRENT_TIMESTAMP, false),
(38, 5, 11, 'Respondeu-me ele: Para lhe edificarem uma casa na terra de Sinar; e, quando a casa for preparada, a efa será colocada ali no seu lugar.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 1, 'De novo levantei os meus olhos, e olhei, e eis quatro carros que saíam dentre dois montes, e estes montes eram montes de bronze.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 2, 'No primeiro carro eram cavalos vermelhos, no segundo carro cavalos pretos,', 1, CURRENT_TIMESTAMP, false),
(38, 6, 3, 'no terceiro carro cavalos brancos, e no quarto carro cavalos baios com malhas.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 4, 'Então, dirigindo-me ao anjo que falava comigo, perguntei: Que são estes, meu senhor?', 1, CURRENT_TIMESTAMP, false),
(38, 6, 5, 'Respondeu-me o anjo: Estes estão saindo aos quatro ventos do céu, depois de se apresentarem perante o Senhor de toda a terra.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 6, 'O carro em que estão os cavalos pretos sai para a terra do norte, os brancos são para o oeste, e os malhados para a terra do sul;', 1, CURRENT_TIMESTAMP, false),
(38, 6, 7, 'e os cavalos baios saíam, e procuravam ir por diante, para percorrerem a terra. E ele disse: Ide, percorrei a terra. E eles a percorriam.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 8, 'Então clamou para mim, dizendo: Eis que aqueles que saíram para a terra do norte fazem repousar na terra do norte o meu Espírito.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 9, 'Ainda me veio a palavra do Senhor, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 6, 10, 'Recebe dos que foram levados cativos, a saber, de Heldai, de Tobias, e de Jedaías, e vem tu no mesmo dia, e entra na casa de Josias, filho de Sofonias, para a qual vieram de Babilônia;', 1, CURRENT_TIMESTAMP, false),
(38, 6, 11, 'recebe, digo, prata e ouro, e faze coroas, e põe-nas na cabeça do sumo sacerdote Josué, filho de Jeozadaque;', 1, CURRENT_TIMESTAMP, false),
(38, 6, 12, 'e fala-lhe, dizendo: Assim diz o Senhor dos exércitos: Eis aqui o homem cujo nome é Renovo; ele brotará do seu lugar, e edificará o templo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 13, 'Ele mesmo edificará o templo do Senhor; receberá a honra real, assentar-se-á no seu trono, e dominará. E Josué, o sacerdote, ficará à sua direita; e haverá entre os dois o conselho de paz.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 14, 'Essas coroas servirão a Helem, e a Tobias, e a Jedaías, e a Hem, filho de Sofonias, de memorial no templo do Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 6, 15, 'E aqueles que estão longe virão, e ajudarão a edificar o templo do Senhor; e vós sabereis que o Senhor dos exércitos me tem enviado a vós; e isso sucederá, se diligentemente obedecerdes a voz do Senhor vosso Deus.', 1, CURRENT_TIMESTAMP, false),
(38, 7, 1, 'Aconteceu no ano quarto do rei Dario, que a palavra do Senhor veio a Zacarias, no dia quarto do nono mês, que é quisleu:', 1, CURRENT_TIMESTAMP, false),
(38, 7, 2, 'Ora, o povo de Betel tinha enviado Sarezer, e Regem-Meleque, e os seus homens, para suplicarem o favor do Senhor,', 1, CURRENT_TIMESTAMP, false),
(38, 7, 3, 'e para dizerem aos sacerdotes, que estavam na casa do Senhor dos exércitos, e aos profetas: Chorarei eu no quinto mês, com jejum, como o tenho feito por tantos anos?', 1, CURRENT_TIMESTAMP, false),
(38, 7, 4, 'Então a palavra do Senhor dos exércitos veio a mim, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 7, 5, 'Fala a todo o povo desta terra, e aos sacerdotes, dizendo: Quando jejuastes, e pranteastes, no quinto e no sétimo mês, durante estes setenta anos, acaso foi mesmo para mim que jejuastes?', 1, CURRENT_TIMESTAMP, false),
(38, 7, 6, 'Ou quando comeis e quando bebeis, não é para vós mesmos que comeis e bebeis?', 1, CURRENT_TIMESTAMP, false),
(38, 7, 7, 'Não eram estas as palavras que o Senhor proferiu por intermédio dos profetas antigos, quando Jerusalém estava habitada e próspera, juntamente com as suas cidades ao redor dela, e quando o Sul e a campina eram habitados?', 1, CURRENT_TIMESTAMP, false),
(38, 7, 8, 'E a palavra do Senhor veio a Zacarias, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 7, 9, 'Assim falou o Senhor dos exércitos: Executai juízo verdadeiro, mostrai bondade e compaixão cada um para com o seu irmão;', 1, CURRENT_TIMESTAMP, false),
(38, 7, 10, 'e não oprimais a viúva, nem o órfão, nem o estrangeiro, nem o pobre; e nenhum de vós intente no seu coração o mal contra o seu irmão.', 1, CURRENT_TIMESTAMP, false),
(38, 7, 11, 'Eles, porém, não quiseram escutar, e me deram o ombro rebelde, e taparam os ouvidos, para que não ouvissem.', 1, CURRENT_TIMESTAMP, false),
(38, 7, 12, 'Sim, fizeram duro como diamante o seu coração, para não ouvirem a lei, nem as palavras que o Senhor dos exércitos enviara pelo seu Espírito mediante os profetas antigos; por isso veio a grande ira do Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(38, 7, 13, 'Assim como eu clamei, e eles não ouviram, assim também eles clamaram, e eu não ouvi, diz o Senhor dos exércitos;', 1, CURRENT_TIMESTAMP, false),
(38, 7, 14, 'mas os espalhei com um turbilhão por entre todas as nações, que eles não conheceram. Assim, pois, a terra foi assolada atrás deles, de sorte que ninguém passava por ela, nem voltava; porquanto fizeram da terra desejada uma desolação.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 1, 'Depois veio a mim a palavra do Senhor dos exércitos, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 8, 2, 'Assim diz o Senhor dos exércitos: Zelo por Sião com grande zelo; e, com grande indignação, por ela estou zelando.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 3, 'Assim diz o Senhor: Voltarei para Sião, e habitarei no meio de Jerusalém; e Jerusalém chamar-se-á a cidade da verdade, e o monte do Senhor dos exércitos o monte santo.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 4, 'Assim diz o Senhor dos exércitos: Ainda nas praças de Jerusalém sentar-se-ão velhos e velhas, levando cada um na mão o seu cajado, por causa da sua muita idade.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 5, 'E as ruas da cidade se encherão de meninos e meninas, que nelas brincarão.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 6, 'Assim diz o Senhor dos exércitos: Se isto for maravilhoso aos olhos do resto deste povo naqueles dias, acaso será também maravilhoso aos meus olhos? diz o Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 7, 'Assim diz o Senhor dos exércitos: Eis que salvarei o meu povo, tirando-o da terra do oriente e da terra do ocidente;', 1, CURRENT_TIMESTAMP, false),
(38, 8, 8, 'e os trarei, e eles habitarão no meio de Jerusalém; eles serão o meu povo, e eu serei o seu Deus em verdade e em justiça.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 9, 'Assim diz o Senhor dos exércitos: Sejam fortes as vossas mãos, ó vós, que nestes dias ouvistes estas palavras da boca dos profetas, que estiveram no dia em que foi posto o fundamento da casa do Senhor dos exércitos, a fim de que o templo fosse edificado.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 10, 'Pois antes daqueles dias não havia salário para os homens, nem lhes davam ganho os animais; nem havia paz para o que saia nem para o que entrava, por causa do inimigo; porque eu incitei a todos os homens, cada um contra o seu próximo.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 11, 'Mas agora não me haverei para com o resto deste povo como nos dias passados, diz o Senhor dos exércitos;', 1, CURRENT_TIMESTAMP, false),
(38, 8, 12, 'porquanto haverá a sementeira de paz; a vide dará o seu fruto, e a terra dará a sua novidade, e os céus darão o seu orvalho; e farei que o resto deste povo herde todas essas coisas.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 13, 'E há de suceder, ó casa de Judá, e ó casa de Israel, que, assim como éreis uma maldição entre as nações, assim vos salvarei, e sereis uma bênção; não temais, mas sejam fortes as vossas mãos.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 14, 'Pois assim diz o Senhor dos exércitos: Como intentei fazer-vos o mal, quando vossos pais me provocaram a ira, diz o Senhor dos exércitos, e não me compadeci,', 1, CURRENT_TIMESTAMP, false),
(38, 8, 15, 'assim tornei a intentar nestes dias fazer o bem a Jerusalém e à casa de Judá; não temais.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 16, 'Eis as coisas que deveis fazer: Falai a verdade cada um com o seu próximo; executai juízo de verdade e de paz nas vossas portas;', 1, CURRENT_TIMESTAMP, false),
(38, 8, 17, 'e nenhum de vós intente no seu coração o mal contra o seu próximo; nem ame o juramento falso; porque todas estas são coisas que eu aborreço, diz o senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 18, 'De novo me veio a palavra do Senhor dos exércitos, dizendo:', 1, CURRENT_TIMESTAMP, false),
(38, 8, 19, 'Assim diz o Senhor dos exércitos: O jejum do quarto mês, bem como o do quinto, o do sétimo, e o do décimo mês se tornarão para a casa de Judá em regozijo, alegria, e festas alegres; amai, pois, a verdade e a paz.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 20, 'Assim diz o Senhor dos exércitos: Ainda sucederá que virão povos, e os habitantes de muitas cidades;', 1, CURRENT_TIMESTAMP, false),
(38, 8, 21, 'e os habitantes de uma cidade irão à outra, dizendo: Vamos depressa suplicar o favor do Senhor, e buscar o Senhor dos exércitos; eu também irei.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 22, 'Assim virão muitos povos, e poderosas nações, buscar em Jerusalém o Senhor dos exércitos, e suplicar a bênção do Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 8, 23, 'Assim diz o Senhor dos exércitos: Naquele dia sucederá que dez homens, de nações de todas as línguas, pegarão na orla das vestes de um judeu, dizendo: Iremos convosco, porque temos ouvido que Deus está convosco.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 1, 'A palavra do Senhor está contra a terra de Hadraque, e repousará sobre Damasco, pois ao Senhor pertencem as cidades de Arã, e todas as tribos de Israel.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 2, 'E também Hamate que confina com ela, e Tiro e Sidom, ainda que sejam mui sábias.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 3, 'Ora Tiro edificou para si fortalezas, e amontoou prata como o pó, e ouro como a lama das ruas.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 4, 'Eis que o Senhor a despojará, e ferirá o seu poder no mar; e ela será consumida pelo fogo.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 5, 'Asquelom o verá, e temerá; também Gaza, e terá grande dor; igualmente Ecrom, porque a sua esperança será iludida; e de Gaza perecerá o rei, e Asquelom não será habitada.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 6, 'Povo mestiço habitará em Asdode; e exterminarei a soberba dos filisteus.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 7, 'E da sua boca tirarei o sangue, e dentre os seus dentes as abominações; e ele também ficará como um resto para o nosso Deus; e será como chefe em Judá, e Ecrom como um jebuseu.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 8, 'Ao redor da minha casa acamparei contra o exército, para que ninguém passe, nem volte; e não passará mais por eles o opressor; pois agora vi com os meus olhos.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 9, 'Alegra-te muito, ó filha de Sião; exulta, ó filha de Jerusalém; eis que vem a ti o teu rei; ele é justo e traz a salvação; ele é humilde e vem montado sobre um jumento, sobre um jumentinho, filho de jumenta.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 10, 'De Efraim exterminarei os carros, e de Jerusalém os cavalos, e o arco de guerra será destruído, e ele anunciará paz às nações; e o seu domínio se estenderá de mar a mar, e desde o Rio até as extremidades da terra.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 11, 'Ainda quanto a ti, por causa do sangue do teu pacto, libertei os teus presos da cova em que não havia água.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 12, 'Voltai à fortaleza, ó presos de esperança; também hoje anuncio que te recompensarei em dobro.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 13, 'Pois curvei Judá por meu arco, pus-lhe Efraim por seta; suscitarei a teus filhos, ó Sião, contra os teus filhos, ó Grécia; e te farei a ti, ó Sião, como a espada de um valente.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 14, 'Por cima deles será visto o Senhor; e a sua flecha sairá como o relâmpago; e o Senhor Deus fará soar a trombeta, e irá com redemoinhos do sul.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 15, 'O Senhor dos exércitos os protegerá; e eles devorarão, e pisarão os fundibulários; também beberão o sangue deles como ao vinho; e encher-se-ão como bacias de sacrifício, como os cantos do altar.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 16, 'E o Senhor seu Deus naquele dia os salvará, como o rebanho do seu povo; porque eles serão como as pedras de uma coroa, elevadas sobre a terra dele.', 1, CURRENT_TIMESTAMP, false),
(38, 9, 17, 'Pois quão grande é a sua bondade, e quão grande é a sua formosura! o trigo fará florescer os mancebos e o mosto as donzelas.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 1, 'Pedi ao Senhor chuva no tempo da chuva serôdia, sim, ao Senhor, que faz os relâmpagos; e ele lhes dará chuvas copiosas, e a cada um erva no campo,', 1, CURRENT_TIMESTAMP, false),
(38, 10, 2, 'Pois os terafins falam vaidade, e os adivinhos vêem mentira e contam sonhos falsos; em vão procuram consolar; por isso seguem o seu caminho como ovelhas; estão aflitos, porque não há pastor.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 3, 'Contra os pastores se acendeu a minha ira, e castigarei os bodes; mas o Senhor dos exércitos visitará o seu rebanho, a casa de Judá, e o fará como o seu majestoso cavalo na peleja.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 4, 'De Judá sairá a pedra angular, dele a estaca da tenda, dele o arco de guerra, dele sairão todos os chefes.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 5, 'Eles serão como valentes que na batalha pisam aos pés os seus inimigos na lama das ruas; pelejarão, porque o Senhor esta com eles; e confundirão os que andam montados em cavalos.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 6, 'Fortalecerei a casa de Judá, e salvarei a casa de José; fá-los-ei voltar, porque me compadeço deles; e serão como se eu não os tivera rejeitado; porque eu sou o Senhor seu Deus, e os ouvirei.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 7, 'Então os de Efraim serão como um valente, e o seu coração se alegrará como pelo vinho; seus filhos o verão, e se alegrarão; o seu coração se regozijará no Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 8, 'Eu lhes assobiarei, e os ajuntarei, porque os tenho remido; e multiplicar-se-ão como dantes se multiplicavam.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 9, 'Ainda que os espalhei entre os povos, eles se lembrarão de mim em terras remotas; e, com seus filhos, viverão e voltarão.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 10, 'Pois eu os farei voltar da terra do Egito, e os congregarei da Assíria; e os trarei à terra de Gileade e do Líbano; e não se achará lugar bastante para eles.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 11, 'Passarão pelo mar de aflição, e serão feridas as ondas do mar, e todas as profundezas do Nilo se secarão; então será abatida a soberba da Assíria, e o cetro do Egito se retirará.', 1, CURRENT_TIMESTAMP, false),
(38, 10, 12, 'Eu os fortalecerei no Senhor, e andarão no seu nome, diz o Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 1, 'Abre, ó Líbano, as tuas portas para que o fogo devore os teus cedros.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 2, 'Geme, ó cipreste, porque caiu o cedro, porque os mais excelentes são destruídos; gemei, ó carvalhos de Basã, porque o bosque forte é derrubado.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 3, 'Voz de uivo dos pastores! porque a sua glória é destruída; voz de bramido de leões novos! porque foi destruída a soberba do Jordão.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 4, 'Assim diz o Senhor meu Deus: Apascenta as ovelhas destinadas para a matança,', 1, CURRENT_TIMESTAMP, false),
(38, 11, 5, 'cujos compradores as matam, e não se têm por culpados; e cujos vendedores dizem: Louvado seja o Senhor, porque hei enriquecido; e os seus pastores não têm piedade delas.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 6, 'Certamente não terei mais piedade dos moradores desta terra, diz o Senhor; mas, eis que entregarei os homens cada um na mão do seu próximo e na mão do seu rei; eles ferirão a terra, e eu não os livrarei da mão deles.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 7, 'Eu pois apascentei as ovelhas destinadas para a matança, as pobres ovelhas do rebanho. E tomei para mim duas varas: a uma chamei Graça, e à outra chamei União; e apascentei as ovelhas.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 8, 'E destruí os três pastores num mês; porque me enfadei deles, e também eles se enfastiaram de mim.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 9, 'Então eu disse: Não vos apascentarei mais; o que morrer morra, e o que for destruído seja destruído; e os que restarem, comam cada um a carne do seu próximo.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 10, 'E tomei a minha vara Graça, e a quebrei, para desfazer o meu pacto, que tinha estabelecido com todos os povos.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 11, 'Foi, pois, anulado naquele dia; assim os pobres do rebanho que me respeitavam, reconheceram que isso era palavra do Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 12, 'E eu lhes disse: Se parece bem aos vossos olhos, dai-me o que me é devido; e, se não, deixai-o. Pesaram, pois, por meu salário, trinta moedas de prata.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 13, 'Ora o Senhor disse-me: Arroja isso ao oleiro, esse belo preço em que fui avaliado por eles. E tomei as trinta moedas de prata, e as arrojei ao oleiro na casa do Senhor.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 14, 'Então quebrei a minha segunda vara União, para romper a irmandade entre Judá e Israel.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 15, 'Então o Senhor me disse: Toma ainda para ti os instrumentos de um pastor insensato.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 16, 'Pois eis que suscitarei um pastor na terra, que não cuidará das que estão perecendo, não procurará as errantes, não curará a ferida, nem apascentará a sã; mas comerá a carne das gordas, e lhes despedaçará as unhas.', 1, CURRENT_TIMESTAMP, false),
(38, 11, 17, 'Ai do pastor inútil, que abandona o rebanho! a espada lhe cairá sobre o braço e sobre o olho direito; o seu braço será de todo mirrado, e o seu olho direito será inteiramente escurecido.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 1, 'A palavra do Senhor acerca de Israel: Fala o Senhor, o que estendeu o céu, e que lançou os alicerces da terra e que formou o espírito do homem dentro dele.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 2, 'Eis que eu farei de Jerusalém um copo de atordoamento para todos os povos em redor, e também para Judá, durante o cerco contra Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 3, 'Naquele dia farei de Jerusalém uma pedra pesada para todos os povos; todos os que a erguerem, serão gravemente feridos. E ajuntar-se-ão contra ela todas as nações da terra.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 4, 'Naquele dia, diz o Senhor, ferirei de espanto a todos os cavalos, e de loucura os que montam neles. Mas sobre a casa de Judá abrirei os meus olhos, e ferirei de cegueira todos os cavalos dos povos.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 5, 'Então os chefes de Judá dirão no seu coração: Os habitantes de Jerusalém são a minha força no Senhor dos exércitos, seu Deus.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 6, 'Naquele dia porei os chefes de Judá como um braseiro ardente no meio de lenha, e como um facho entre gavelas; e eles devorarão à direita e à esquerda a todos os povos em redor; e Jerusalém será habitada outra vez no seu próprio lugar, mesmo em Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 7, 'Também o Senhor salvará primeiro as tendas de Judá, para que a glória da casa de Davi e a glória dos habitantes de Jerusalém não se engrandeçam sobre Judá.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 8, 'Naquele dia o Senhor defenderá os habitantes de Jerusalém, de sorte que o mais fraco dentre eles naquele dia será como Davi, e a casa de Davi será como Deus, como o anjo do Senhor diante deles.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 9, 'E naquele dia, tratarei de destruir todas as nações que vierem contra Jerusalém.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 10, 'Mas sobre a casa de Davi, e sobre os habitantes de Jerusalém, derramarei o espírito de graça e de súplicas; e olharão para aquele a quem traspassaram, e o prantearão como quem pranteia por seu filho único; e chorarão amargamente por ele, como se chora pelo primogênito.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 11, 'Naquele dia será grande o pranto em Jerusalém, como o pranto de Hadade-Rimom no vale de Megidom.', 1, CURRENT_TIMESTAMP, false),
(38, 12, 12, 'E a terra pranteará, cada família à parte: a família da casa de Davi à parte, e suas mulheres à parte; e a família da casa de Natã à parte, e suas mulheres à parte;', 1, CURRENT_TIMESTAMP, false),
(38, 12, 13, 'a família da casa de Levi à parte, e suas mulheres à parte; a família de Simei à parte, e suas mulheres à parte;', 1, CURRENT_TIMESTAMP, false),
(38, 12, 14, 'todas as mais famílias, cada família à parte, e suas mulheres à parte.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 1, 'Naquele dia haverá uma fonte aberta para a casa de Davi, e para os habitantes de Jerusalém, para remover o pecado e a impureza.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 2, 'Naquele dia, diz o Senhor dos exércitos, cortarei da terra os nomes dos ídolos, e deles não haverá mais memória; e também farei sair da terra os profetas e o espírito da impureza.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 3, 'E se alguém ainda profetizar, seu pai e sua mãe, que o geraram, lhe dirão: Não viverás, porque falas mentiras em o nome do Senhor; e seu pai e sua mãe, que o geraram, o traspassarão quando profetizar.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 4, 'Naquele dia os profetas se sentirão envergonhados, cada um da sua visão, quando profetizarem; nem mais se vestirão de manto de pêlos, para enganarem,', 1, CURRENT_TIMESTAMP, false),
(38, 13, 5, 'mas dirão: Não sou profeta, sou lavrador da terra; porque tenho sido escravo desde a minha mocidade.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 6, 'E se alguém lhe disser: Que feridas são essas entre as tuas mãos? Dirá ele: São as feridas com que fui ferido em casa dos meus amigos.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 7, 'Ó espada, ergue-te contra o meu pastor, e contra o varão que é o meu companheiro, diz o Senhor dos exércitos; fere ao pastor, e espalhar-se-ão as ovelhas; mas volverei a minha mão para os pequenos.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 8, 'Em toda a terra, diz o Senhor, as duas partes dela serão exterminadas, e expirarão; mas a terceira parte restará nela.', 1, CURRENT_TIMESTAMP, false),
(38, 13, 9, 'E farei passar esta terceira parte pelo fogo, e a purificarei, como se purifica a prata, e a provarei, como se prova o ouro. Ela invocará o meu nome, e eu a ouvirei; direi: É meu povo; e ela dirá: O Senhor é meu Deus.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 1, 'Eis que vem um dia do Senhor, em que os teus despojos se repartirão no meio de ti.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 2, 'Pois eu ajuntarei todas as nações para a peleja contra Jerusalém; e a cidade será tomada, e as casas serão saqueadas, e as mulheres forçadas; e metade da cidade sairá para o cativeiro mas o resto do povo não será exterminado da cidade.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 3, 'Então o Senhor sairá, e pelejará contra estas nações, como quando peleja no dia da batalha.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 4, 'Naquele dia estarão os seus pés sobre o monte das Oliveiras, que está defronte de Jerusalém para o oriente; se o monte das Oliveiras será fendido pelo meio, do oriente para o ocidente e haverá um vale muito grande; e metade do monte se removerá para o norte, e a outra metade dele para o sul.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 5, 'E fugireis pelo vale dos meus montes, pois o vale dos montes chegará até Azel; e fugireis assim como fugistes de diante do terremoto nos dias de Uzias, rei de Judá. Então virá o Senhor meu Deus, e todos os santos com ele.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 6, 'Acontecerá naquele dia, que não haverá calor, nem frio, nem geada;', 1, CURRENT_TIMESTAMP, false),
(38, 14, 7, 'porém será um dia conhecido do Senhor; nem dia nem noite será; mas até na parte da tarde haverá luz.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 8, 'Naquele dia também acontecerá que correrão de Jerusalém águas vivas, metade delas para o mar oriental, e metade delas para o mar ocidental; no verão e no inverno sucederá isso.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 9, 'E o Senhor será rei sobre toda a terra; naquele dia um será o Senhor, e um será o seu nome.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 10, 'Toda a terra em redor se tornará em planície, desde Geba até Rimom, ao sul de Jerusalém; ela será exaltada, e habitará no seu lugar, desde a porta de Benjamim até o lugar da primeira porta, até a porta da esquina, e desde a torre de Hananel até os lagares do rei', 1, CURRENT_TIMESTAMP, false),
(38, 14, 11, 'E habitarão nela, e não haverá mais maldição; mas Jerusalém habitará em segurança.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 12, 'Esta será a praga com que o Senhor ferirá todos os povos que guerrearam contra Jerusalém: apodrecer-se-á a sua carne, estando eles de pé, e se lhes apodrecerão os olhos nas suas órbitas, e a língua se lhes apodrecerá na boca,', 1, CURRENT_TIMESTAMP, false),
(38, 14, 13, 'Naquele dia também haverá da parte do Senhor um grande tumulto entre eles; e pegará cada um na mão do seu próximo, e cada um levantará a mão contra o seu próximo.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 14, 'Também Judá pelejará contra Jerusalém; e se ajuntarão as riquezas de todas as nações circunvizinhas, ouro e prata, e vestidos em grande abundância.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 15, 'Como esta praga, assim será a praga dos cavalos, dos muares, dos camelos e dos jumentos e de todos os animais que estiverem naqueles arraiais.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 16, 'Então todos os que restarem de todas as nações que vieram contra Jerusalém, subirão de ano em ano para adorarem o Rei, o Senhor dos exércitos, e para celebrarem a festa dos tabernáculos.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 17, 'E se alguma das famílias da terra não subir a Jerusalém, para adorar o Rei, o Senhor dos exércitos, não cairá sobre ela a chuva.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 18, 'E, se a família do Egito não subir, nem vier, não virá sobre ela a chuva; virá a praga com que o Senhor ferirá as nações que não subirem a celebrar a festa dos tabernáculos.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 19, 'Esse será o castigo do Egito, e o castigo de todas as nações que não subirem a celebrar a festa dos tabernáculos.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 20, 'Naquele dia se gravará sobre as campainhas dos cavalos. SANTO AO SENHOR; e as panelas na casa do Senhor serão como as bacias diante do altar.', 1, CURRENT_TIMESTAMP, false),
(38, 14, 21, 'E todas as panelas em Jerusalém e Judá serão consagradas ao Senhor dos exércitos; e todos os que sacrificarem virão, e delas tomarão, e nelas cozerão. Naquele dia não haverá mais cananeu na casa do Senhor dos exércitos.', 1, CURRENT_TIMESTAMP, false);
INSERT INTO versiculos (livro, capitulo, numero, texto, traducao_id, data_criacao, deletado) VALUES
(46, 1, 1, 'Paulo (chamado apóstolo de Jesus Cristo, pela vontade de Deus), e o irmão Sóstenes,', 2, CURRENT_TIMESTAMP, false),
(46, 1, 2, 'À igreja de Deus que está em Corinto, aos santificados em Cristo Jesus, chamados santos, com todos os que em todo o lugar invocam o nome de nosso Senhor Jesus Cristo, Senhor deles e nosso:', 2, CURRENT_TIMESTAMP, false),
(46, 1, 3, 'Graça e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 4, 'Sempre dou graças ao meu Deus por vós pela graça de Deus que vos foi dada em Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 5, 'Porque em tudo fostes enriquecidos nele, em toda a palavra e em todo o conhecimento', 2, CURRENT_TIMESTAMP, false),
(46, 1, 6, '(Como o testemunho de Cristo foi mesmo confirmado entre vós).', 2, CURRENT_TIMESTAMP, false),
(46, 1, 7, 'De maneira que nenhum dom vos falta, esperando a manifestação de nosso Senhor Jesus Cristo,', 2, CURRENT_TIMESTAMP, false),
(46, 1, 8, 'O qual vos confirmará também até ao fim, para serdes irrepreensíveis no dia de nosso Senhor Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 9, 'Fiel é Deus, pelo qual fostes chamados para a comunhão de seu Filho Jesus Cristo nosso Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 10, 'Rogo-vos, porém, irmãos, pelo nome de nosso Senhor Jesus Cristo, que digais todos uma mesma coisa, e que não haja entre vós dissensões; antes sejais unidos em um mesmo pensamento e em um mesmo parecer.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 11, 'Porque a respeito de vós, irmãos meus, me foi comunicado pelos da família de Cloé que há contendas entre vós.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 12, 'Quero dizer com isto, que cada um de vós diz: Eu sou de Paulo, e eu de Apolo, e eu de Cefas, e eu de Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 13, 'Está Cristo dividido? foi Paulo crucificado por vós? ou fostes vós batizados em nome de Paulo?', 2, CURRENT_TIMESTAMP, false),
(46, 1, 14, 'Dou graças a Deus, porque a nenhum de vós batizei, senão a Crispo e a Gaio,', 2, CURRENT_TIMESTAMP, false),
(46, 1, 15, 'Para que ninguém diga que fostes batizados em meu nome.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 16, 'E batizei também a família de Estéfanas; além destes, não sei se batizei algum outro.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 17, 'Porque Cristo enviou-me, não para batizar, mas para evangelizar; não em sabedoria de palavras, para que a cruz de Cristo se não faça vã.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 18, 'Porque a palavra da cruz é loucura para os que perecem; mas para nós, que somos salvos, é o poder de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 19, 'Porque está escrito: Destruirei a sabedoria dos sábios, E aniquilarei a inteligência dos inteligentes.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 20, 'Onde está o sábio? Onde está o escriba? Onde está o inquiridor deste século? Porventura não tornou Deus louca a sabedoria deste mundo?', 2, CURRENT_TIMESTAMP, false),
(46, 1, 21, 'Visto como na sabedoria de Deus o mundo não conheceu a Deus pela sua sabedoria, aprouve a Deus salvar os crentes pela loucura da pregação.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 22, 'Porque os judeus pedem sinal, e os gregos buscam sabedoria;', 2, CURRENT_TIMESTAMP, false),
(46, 1, 23, 'Mas nós pregamos a Cristo crucificado, que é escândalo para os judeus, e loucura para os gregos.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 24, 'Mas para os que são chamados, tanto judeus como gregos, lhes pregamos a Cristo, poder de Deus, e sabedoria de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 25, 'Porque a loucura de Deus é mais sábia do que os homens; e a fraqueza de Deus é mais forte do que os homens.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 26, 'Porque, vede, irmãos, a vossa vocação, que não são muitos os sábios segundo a carne, nem muitos os poderosos, nem muitos os nobres que são chamados.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 27, 'Mas Deus escolheu as coisas loucas deste mundo para confundir as sábias; e Deus escolheu as coisas fracas deste mundo para confundir as fortes;', 2, CURRENT_TIMESTAMP, false),
(46, 1, 28, 'E Deus escolheu as coisas vis deste mundo, e as desprezíveis, e as que não são, para aniquilar as que são;', 2, CURRENT_TIMESTAMP, false),
(46, 1, 29, 'Para que nenhuma carne se glorie perante ele.', 2, CURRENT_TIMESTAMP, false),
(46, 1, 30, 'Mas vós sois dele, em Jesus Cristo, o qual para nós foi feito por Deus sabedoria, e justiça, e santificação, e redenção;', 2, CURRENT_TIMESTAMP, false),
(46, 1, 31, 'Para que, como está escrito: Aquele que se gloria glorie-se no Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 1, 'E eu, irmãos, quando fui ter convosco, anunciando-vos o testemunho de Deus, não fui com sublimidade de palavras ou de sabedoria.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 2, 'Porque nada me propus saber entre vós, senão a Jesus Cristo, e este crucificado.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 3, 'E eu estive convosco em fraqueza, e em temor, e em grande tremor.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 4, 'E a minha palavra, e a minha pregação, não consistiram em palavras persuasivas de sabedoria humana, mas em demonstração de Espírito e de poder;', 2, CURRENT_TIMESTAMP, false),
(46, 2, 5, 'Para que a vossa fé não se apoiasse em sabedoria dos homens, mas no poder de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 6, 'Todavia falamos sabedoria entre os perfeitos; não, porém, a sabedoria deste mundo, nem dos príncipes deste mundo, que se aniquilam;', 2, CURRENT_TIMESTAMP, false),
(46, 2, 7, 'Mas falamos a sabedoria de Deus, oculta em mistério, a qual Deus ordenou antes dos séculos para nossa glória;', 2, CURRENT_TIMESTAMP, false),
(46, 2, 8, 'A qual nenhum dos príncipes deste mundo conheceu; porque, se a conhecessem, nunca crucificariam ao Senhor da glória.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 9, 'Mas, como está escrito:As coisas que o olho não viu, e o ouvido não ouviu,e não subiram ao coração do homem,são as que Deus preparou para os que o amam.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 10, 'Mas Deus no-las revelou pelo seu Espírito; porque o Espírito penetra todas as coisas, ainda as profundezas de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 11, 'Porque, qual dos homens sabe as coisas do homem, senão o espírito do homem, que nele está? Assim também ninguém sabe as coisas de Deus, senão o Espírito de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 12, 'Mas nós não recebemos o espírito do mundo, mas o Espírito que provém de Deus, para que pudéssemos conhecer o que nos é dado gratuitamente por Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 13, 'As quais também falamos, não com palavras que a sabedoria humana ensina, mas com as que o Espírito Santo ensina, comparando as coisas espirituais com as espirituais.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 14, 'Ora, o homem natural não compreende as coisas do Espírito de Deus, porque lhe parecem loucura; e não pode entendê-las, porque elas se discernem espiritualmente.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 15, 'Mas o que é espiritual discerne bem tudo, e ele de ninguém é discernido.', 2, CURRENT_TIMESTAMP, false),
(46, 2, 16, 'Porque, quem conheceu a mente do Senhor, para que possa instruí-lo? Mas nós temos a mente de Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 1, 'E eu, irmãos, não vos pude falar como a espirituais, mas como a carnais, como a meninos em Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 2, 'Com leite vos criei, e não com carne, porque ainda não podíeis, nem tampouco ainda agora podeis,', 2, CURRENT_TIMESTAMP, false),
(46, 3, 3, 'Porque ainda sois carnais; pois, havendo entre vós inveja, contendas e dissensões, não sois porventura carnais, e não andais segundo os homens?', 2, CURRENT_TIMESTAMP, false),
(46, 3, 4, 'Porque, dizendo um: Eu sou de Paulo; e outro: Eu de Apolo; porventura não sois carnais?', 2, CURRENT_TIMESTAMP, false),
(46, 3, 5, 'Pois, quem é Paulo, e quem é Apolo, senão ministros pelos quais crestes, e conforme o que o Senhor deu a cada um?', 2, CURRENT_TIMESTAMP, false),
(46, 3, 6, 'Eu plantei, Apolo regou; mas Deus deu o crescimento.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 7, 'Por isso, nem o que planta é alguma coisa, nem o que rega, mas Deus, que dá o crescimento.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 8, 'Ora, o que planta e o que rega são um; mas cada um receberá o seu galardão segundo o seu trabalho.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 9, 'Porque nós somos cooperadores de Deus; vós sois lavoura de Deus e edifício de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 10, 'Segundo a graça de Deus que me foi dada, pus eu, como sábio arquiteto, o fundamento, e outro edifica sobre ele; mas veja cada um como edifica sobre ele.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 11, 'Porque ninguém pode pôr outro fundamento além do que já está posto, o qual é Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 12, 'E, se alguém sobre este fundamento formar um edifício de ouro, prata, pedras preciosas, madeira, feno, palha,', 2, CURRENT_TIMESTAMP, false),
(46, 3, 13, 'A obra de cada um se manifestará; na verdade o dia a declarará, porque pelo fogo será descoberta; e o fogo provará qual seja a obra de cada um.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 14, 'Se a obra que alguém edificou nessa parte permanecer, esse receberá galardão.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 15, 'Se a obra de alguém se queimar, sofrerá detrimento; mas o tal será salvo, todavia como pelo fogo.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 16, 'Não sabeis vós que sois o templo de Deus e que o Espírito de Deus habita em vós?', 2, CURRENT_TIMESTAMP, false),
(46, 3, 17, 'Se alguém destruir o templo de Deus, Deus o destruirá; porque o templo de Deus, que sois vós, é santo.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 18, 'Ninguém se engane a si mesmo. Se alguém dentre vós se tem por sábio neste mundo, faça-se louco para ser sábio.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 19, 'Porque a sabedoria deste mundo é loucura diante de Deus; pois está escrito: Ele apanha os sábios na sua própria astúcia.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 20, 'E outra vez: O Senhor conhece os pensamentos dos sábios, que são vãos.', 2, CURRENT_TIMESTAMP, false),
(46, 3, 21, 'Portanto, ninguém se glorie nos homens; porque tudo é vosso;', 2, CURRENT_TIMESTAMP, false),
(46, 3, 22, 'Seja Paulo, seja Apolo, seja Cefas, seja o mundo, seja a vida, seja a morte, seja o presente, seja o futuro; tudo é vosso,', 2, CURRENT_TIMESTAMP, false),
(46, 3, 23, 'E vós de Cristo, e Cristo de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 1, 'Que os homens nos considerem como ministros de Cristo, e despenseiros dos mistérios de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 2, 'Além disso requer-se dos despenseiros que cada um se ache fiel.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 3, 'Todavia, a mim mui pouco se me dá de ser julgado por vós, ou por algum juízo humano; nem eu tampouco a mim mesmo me julgo.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 4, 'Porque em nada me sinto culpado; mas nem por isso me considero justificado, pois quem me julga é o Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 5, 'Portanto, nada julgueis antes de tempo, até que o Senhor venha, o qual também trará à luz as coisas ocultas das trevas, e manifestará os desígnios dos corações; e então cada um receberá de Deus o louvor.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 6, 'E eu, irmãos, apliquei estas coisas, por semelhança, a mim e a Apolo, por amor de vós; para que em nós aprendais a não ir além do que está escrito, não vos ensoberbecendo a favor de um contra outro.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 7, 'Porque, quem te faz diferente? E que tens tu que não tenhas recebido? E, se o recebeste, por que te glorias, como se não o houveras recebido?', 2, CURRENT_TIMESTAMP, false),
(46, 4, 8, 'Já estais fartos! já estais ricos! sem nós reinais! e quisera reinásseis para que também nós viéssemos a reinar convosco!', 2, CURRENT_TIMESTAMP, false),
(46, 4, 9, 'Porque tenho para mim, que Deus a nós, apóstolos, nos pôs por últimos, como condenados à morte; pois somos feitos espetáculo ao mundo, aos anjos, e aos homens.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 10, 'Nós somos loucos por amor de Cristo, e vós sábios em Cristo; nós fracos, e vós fortes; vós ilustres, e nós vis.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 11, 'Até esta presente hora sofremos fome, e sede, e estamos nus, e recebemos bofetadas, e não temos pousada certa,', 2, CURRENT_TIMESTAMP, false),
(46, 4, 12, 'E nos afadigamos, trabalhando com nossas próprias mãos. Somos injuriados, e bendizemos; somos perseguidos, e sofremos;', 2, CURRENT_TIMESTAMP, false),
(46, 4, 13, 'Somos blasfemados, e rogamos; até ao presente temos chegado a ser como o lixo deste mundo, e como a escória de todos.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 14, 'Não escrevo estas coisas para vos envergonhar; mas admoesto-vos como meus filhos amados.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 15, 'Porque ainda que tivésseis dez mil aios em Cristo, não teríeis, contudo, muitos pais; porque eu pelo evangelho vos gerei em Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 16, 'Admoesto-vos, portanto, a que sejais meus imitadores.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 17, 'Por esta causa vos mandei Timóteo, que é meu filho amado, e fiel no Senhor, o qual vos lembrará os meus caminhos em Cristo, como por toda a parte ensino em cada igreja.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 18, 'Mas alguns andam ensoberbecidos, como se eu não houvesse de ir ter convosco.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 19, 'Mas em breve irei ter convosco, se o Senhor quiser, e então conhecerei, não as palavras dos que andam ensoberbecidos, mas o poder.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 20, 'Porque o reino de Deus não consiste em palavras, mas em poder.', 2, CURRENT_TIMESTAMP, false),
(46, 4, 21, 'Que quereis? Irei ter convosco com vara ou com amor e espírito de mansidão?', 2, CURRENT_TIMESTAMP, false),
(46, 5, 1, 'Geralmente se ouve que há entre vós fornicação, e fornicação tal, que nem ainda entre os gentios se nomeia, como é haver quem possua a mulher de seu pai.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 2, 'Estais ensoberbecidos, e nem ao menos vos entristecestes por não ter sido dentre vós tirado quem cometeu tal ação.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 3, 'Eu, na verdade, ainda que ausente no corpo, mas presente no espírito, já determinei, como se estivesse presente, que o que tal ato praticou,', 2, CURRENT_TIMESTAMP, false),
(46, 5, 4, 'Em nome de nosso Senhor Jesus Cristo, juntos vós e o meu espírito, pelo poder de nosso Senhor Jesus Cristo,', 2, CURRENT_TIMESTAMP, false),
(46, 5, 5, 'Seja, este tal, entregue a Satanás para destruição da carne, para que o espírito seja salvo no dia do Senhor Jesus.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 6, 'Não é boa a vossa jactância. Não sabeis que um pouco de fermento faz levedar toda a massa?', 2, CURRENT_TIMESTAMP, false),
(46, 5, 7, 'Alimpai-vos, pois, do fermento velho, para que sejais uma nova massa, assim como estais sem fermento. Porque Cristo, nossa páscoa, foi sacrificado por nós.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 8, 'Por isso façamos a festa, não com o fermento velho, nem com o fermento da maldade e da malícia, mas com os ázimos da sinceridade e da verdade.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 9, 'Já por carta vos tenho escrito, que não vos associeis com os que se prostituem;', 2, CURRENT_TIMESTAMP, false),
(46, 5, 10, 'Isto não quer dizer absolutamente com os devassos deste mundo, ou com os avarentos, ou com os roubadores, ou com os idólatras; porque então vos seria necessário sair do mundo.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 11, 'Mas agora vos escrevi que não vos associeis com aquele que, dizendo-se irmão, for devasso, ou avarento, ou idólatra, ou maldizente, ou beberrão, ou roubador; com o tal nem ainda comais.', 2, CURRENT_TIMESTAMP, false),
(46, 5, 12, 'Porque, que tenho eu em julgar também os que estão de fora? Não julgais vós os que estão dentro?', 2, CURRENT_TIMESTAMP, false),
(46, 5, 13, 'Mas Deus julga os que estão de fora. Tirai pois dentre vós a esse iníquo.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 1, 'Ousa algum de vós, tendo algum negócio contra outro, ir a juízo perante os injustos, e não perante os santos?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 2, 'Não sabeis vós que os santos hão de julgar o mundo? Ora, se o mundo deve ser julgado por vós, sois porventura indignos de julgar as coisas mínimas?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 3, 'Não sabeis vós que havemos de julgar os anjos? Quanto mais as coisas pertencentes a esta vida?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 4, 'Então, se tiverdes negócios em juízo, pertencentes a esta vida, pondes para julga-los os que são de menos estima na igreja?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 5, 'Para vos envergonhar o digo. Não há, pois, entre vós sábios, nem mesmo um, que possa julgar entre seus irmãos?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 6, 'Mas o irmão vai a juízo com o irmão, e isto perante infiéis.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 7, 'Na verdade é já realmente uma falta entre vós, terdes demandas uns contra os outros. Por que não sofreis antes a injustiça? Por que não sofreis antes o dano?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 8, 'Mas vós mesmos fazeis a injustiça e fazeis o dano, e isto aos irmãos.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 9, 'Não sabeis que os injustos não hão de herdar o reino de Deus?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 10, 'Não erreis: nem os devassos, nem os idólatras, nem os adúlteros, nem os efeminados, nem os sodomitas, nem os ladrões, nem os avarentos, nem os bêbados, nem os maldizentes, nem os roubadores herdarão o reino de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 11, 'E é o que alguns têm sido; mas haveis sido lavados, mas haveis sido santificados, mas haveis sido justificados em nome do Senhor Jesus, e pelo Espírito do nosso Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 12, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm. Todas as coisas me são lícitas, mas eu não me deixarei dominar por nenhuma.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 13, 'Os alimentos são para o estômago e o estômago para os alimentos; Deus, porém, aniquilará tanto um como os outros. Mas o corpo não é para a fornicação, senão para o Senhor, e o Senhor para o corpo.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 14, 'Ora, Deus, que também ressuscitou o Senhor, nos ressuscitará a nós pelo seu poder.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 15, 'Não sabeis vós que os vossos corpos são membros de Cristo? Tomarei, pois, os membros de Cristo, e os farei membros de uma meretriz? Não, por certo.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 16, 'Ou não sabeis que o que se ajunta com a meretriz, faz-se um corpo com ela? Porque serão, disse, dois numa só carne.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 17, 'Mas o que se ajunta com o Senhor é um mesmo espírito.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 18, 'Fugi da fornicação. Todo o pecado que o homem comete é fora do corpo; mas o que fornica peca contra o seu próprio corpo.', 2, CURRENT_TIMESTAMP, false),
(46, 6, 19, 'Ou não sabeis que o vosso corpo é o templo do Espírito Santo, que habita em vós, proveniente de Deus, e que não sois de vós mesmos?', 2, CURRENT_TIMESTAMP, false),
(46, 6, 20, 'Porque fostes comprados por bom preço; glorificai, pois, a Deus no vosso corpo, e no vosso espírito, os quais pertencem a Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 1, 'Ora, quanto às coisas que me escrevestes, bom seria que o homem não tocasse em mulher;', 2, CURRENT_TIMESTAMP, false),
(46, 7, 2, 'Mas, por causa da fornicação, cada um tenha a sua própria mulher, e cada uma tenha o seu próprio marido.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 3, 'O marido pague à mulher a devida benevolência, e da mesma sorte a mulher ao marido.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 4, 'A mulher não tem poder sobre o seu próprio corpo, mas tem-no o marido; e também da mesma maneira o marido não tem poder sobre o seu próprio corpo, mas tem-no a mulher.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 5, 'Não vos priveis um ao outro, senão por consentimento mútuo por algum tempo, para vos aplicardes ao jejum e à oração; e depois ajuntai-vos outra vez, para que Satanás não vos tente pela vossa incontinência.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 6, 'Digo, porém, isto como que por permissão e não por mandamento.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 7, 'Porque quereria que todos os homens fossem como eu mesmo; mas cada um tem de Deus o seu próprio dom, um de uma maneira e outro de outra.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 8, 'Digo, porém, aos solteiros e às viúvas, que lhes é bom se ficarem como eu.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 9, 'Mas, se não podem conter-se, casem-se. Porque é melhor casar do que abrasar-se.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 10, 'Todavia, aos casados mando, não eu mas o Senhor, que a mulher não se aparte do marido.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 11, 'Se, porém, se apartar, que fique sem casar, ou que se reconcilie com o marido; e que o marido não deixe a mulher.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 12, 'Mas aos outros digo eu, não o Senhor: Se algum irmão tem mulher descrente, e ela consente em habitar com ele, não a deixe.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 13, 'E se alguma mulher tem marido descrente, e ele consente em habitar com ela, não o deixe.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 14, 'Porque o marido descrente é santificado pela mulher; e a mulher descrente é santificada pelo marido; de outra sorte os vossos filhos seriam imundos; mas agora são santos.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 15, 'Mas, se o descrente se apartar, aparte-se; porque neste caso o irmão, ou irmã, não está sujeito à servidão; mas Deus chamou-nos para a paz.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 16, 'Porque, de onde sabes, ó mulher, se salvarás teu marido? ou, de onde sabes, ó marido, se salvarás tua mulher?', 2, CURRENT_TIMESTAMP, false),
(46, 7, 17, 'E assim cada um ande como Deus lhe repartiu, cada um como o Senhor o chamou. É o que ordeno em todas as igrejas.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 18, 'É alguém chamado, estando circuncidado? fique circuncidado. É alguém chamado estando incircuncidado? não se circuncide.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 19, 'A circuncisão é nada e a incircuncisão nada é, mas, sim, a observância dos mandamentos de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 20, 'Cada um fique na vocação em que foi chamado.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 21, 'Foste chamado sendo servo? não te dê cuidado; e, se ainda podes ser livre, aproveita a ocasião.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 22, 'Porque o que é chamado pelo Senhor, sendo servo, é liberto do Senhor; e da mesma maneira também o que é chamado sendo livre, servo é de Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 23, 'Fostes comprados por bom preço; não vos façais servos dos homens.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 24, 'Irmãos, cada um fique diante de Deus no estado em que foi chamado.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 25, 'Ora, quanto às virgens, não tenho mandamento do Senhor; dou, porém, o meu parecer, como quem tem alcançado misericórdia do Senhor para ser fiel.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 26, 'Tenho, pois, por bom, por causa da instante necessidade, que é bom para o homem o estar assim.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 27, 'Estás ligado à mulher? não busques separar-te. Estás livre de mulher? não busques mulher.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 28, 'Mas, se te casares, não pecas; e, se a virgem se casar, não peca. Todavia os tais terão tribulações na carne, e eu quereria poupar-vos.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 29, 'Isto, porém, vos digo, irmãos, que o tempo se abrevia; o que resta é que também os que têm mulheres sejam como se não as tivessem;', 2, CURRENT_TIMESTAMP, false),
(46, 7, 30, 'E os que choram, como se não chorassem; e os que folgam, como se não folgassem; e os que compram, como se não possuíssem;', 2, CURRENT_TIMESTAMP, false),
(46, 7, 31, 'E os que usam deste mundo, como se dele não abusassem, porque a aparência deste mundo passa.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 32, 'E bem quisera eu que estivésseis sem cuidado. O solteiro cuida das coisas do Senhor, em como há de agradar ao Senhor;', 2, CURRENT_TIMESTAMP, false),
(46, 7, 33, 'Mas o que é casado cuida das coisas do mundo, em como há de agradar à mulher.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 34, 'Há diferença entre a mulher casada e a virgem. A solteira cuida das coisas do Senhor para ser santa, tanto no corpo como no espírito; porém, a casada cuida das coisas do mundo, em como há de agradar ao marido.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 35, 'E digo isto para proveito vosso; não para vos enlaçar, mas para o que é decente e conveniente, para vos unirdes ao Senhor sem distração alguma.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 36, 'Mas, se alguém julga que trata indignamente a sua virgem, se tiver passado a flor da idade, e se for necessário, que faça o tal o que quiser; não peca; casem-se.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 37, 'Todavia o que está firme em seu coração, não tendo necessidade, mas com poder sobre a sua própria vontade, se resolveu no seu coração guardar a sua virgem, faz bem.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 38, 'De sorte que, o que a dá em casamento faz bem; mas o que não a dá em casamento faz melhor.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 39, 'A mulher casada está ligada pela lei todo o tempo que o seu marido vive; mas, se falecer o seu marido fica livre para casar com quem quiser, contanto que seja no Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 7, 40, 'Será, porém, mais bem-aventurada se ficar assim, segundo o meu parecer, e também eu cuido que tenho o Espírito de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 1, 'Ora, no tocante às coisas sacrificadas aos ídolos, sabemos que todos temos ciência. A ciência incha, mas o amor edifica.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 2, 'E, se alguém cuida saber alguma coisa, ainda não sabe como convém saber.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 3, 'Mas, se alguém ama a Deus, esse é conhecido dele.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 4, 'Assim que, quanto ao comer das coisas sacrificadas aos ídolos, sabemos que o ídolo nada é no mundo, e que não há outro Deus, senão um só.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 5, 'Porque, ainda que haja também alguns que se chamem deuses, quer no céu quer na terra (como há muitos deuses e muitos senhores),', 2, CURRENT_TIMESTAMP, false),
(46, 8, 6, 'Todavia para nós há um só Deus, o Pai, de quem é tudo e para quem nós vivemos; e um só Senhor, Jesus Cristo, pelo qual são todas as coisas, e nós por ele.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 7, 'Mas nem em todos há conhecimento; porque alguns até agora comem, com consciência do ídolo, coisas sacrificadas ao ídolo; e a sua consciência, sendo fraca, fica contaminada.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 8, 'Ora a comida não nos faz agradáveis a Deus, porque, se comemos, nada temos de mais e, se não comemos, nada nos falta.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 9, 'Mas vede que essa liberdade não seja de alguma maneira escândalo para os fracos.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 10, 'Porque, se alguém te vir a ti, que tens ciência, sentado à mesa no templo dos ídolos, não será a consciência do que é fraco induzida a comer das coisas sacrificadas aos ídolos?', 2, CURRENT_TIMESTAMP, false),
(46, 8, 11, 'E pela tua ciência perecerá o irmão fraco, pelo qual Cristo morreu.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 12, 'Ora, pecando assim contra os irmãos, e ferindo a sua fraca consciência, pecais contra Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 8, 13, 'Por isso, se a comida escandalizar a meu irmão, nunca mais comerei carne, para que meu irmão não se escandalize.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 1, 'Não sou eu apóstolo? Não sou livre? Não vi eu a Jesus Cristo Senhor nosso? Não sois vós a minha obra no Senhor?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 2, 'Se eu não sou apóstolo para os outros, ao menos o sou para vós; porque vós sois o selo do meu apostolado no Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 3, 'Esta é minha defesa para com os que me condenam.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 4, 'Não temos nós direito de comer e beber?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 5, 'Não temos nós direito de levar conosco uma esposa crente, como também os demais apóstolos, e os irmãos do Senhor, e Cefas?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 6, 'Ou só eu e Barnabé não temos direito de deixar de trabalhar?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 7, 'Quem jamais milita à sua própria custa? Quem planta a vinha e não come do seu fruto? Ou quem apascenta o gado e não se alimenta do leite do gado?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 8, 'Digo eu isto segundo os homens? Ou não diz a lei também o mesmo?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 9, 'Porque na lei de Moisés está escrito: Não atarás a boca ao boi que trilha o grão. Porventura tem Deus cuidado dos bois?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 10, 'Ou não o diz certamente por nós? Certamente que por nós está escrito; porque o que lavra deve lavrar com esperança e o que debulha deve debulhar com esperança de ser participante.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 11, 'Se nós vos semeamos as coisas espirituais, será muito que de vós recolhamos as carnais?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 12, 'Se outros participam deste poder sobre vós, por que não, e mais justamente, nós? Mas nós não usamos deste direito; antes suportamos tudo, para não pormos impedimento algum ao evangelho de Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 13, 'Não sabeis vós que os que administram o que é sagrado comem do que é do templo? E que os que de contínuo estão junto ao altar, participam do altar?', 2, CURRENT_TIMESTAMP, false),
(46, 9, 14, 'Assim ordenou também o Senhor aos que anunciam o evangelho, que vivam do evangelho.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 15, 'Mas eu de nenhuma destas coisas usei, e não escrevi isto para que assim se faça comigo; porque melhor me fora morrer, do que alguém fazer vã esta minha glória.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 16, 'Porque, se anuncio o evangelho, não tenho de que me gloriar, pois me é imposta essa obrigação; e ai de mim, se não anunciar o evangelho!', 2, CURRENT_TIMESTAMP, false),
(46, 9, 17, 'E por isso, se o faço de boa mente, terei prêmio; mas, se de má vontade, apenas uma dispensação me é confiada.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 18, 'Logo, que prêmio tenho? Que, evangelizando, proponha de graça o evangelho de Cristo para não abusar do meu poder no evangelho.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 19, 'Porque, sendo livre para com todos, fiz-me servo de todos para ganhar ainda mais.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 20, 'E fiz-me como judeu para os judeus, para ganhar os judeus; para os que estão debaixo da lei, como se estivesse debaixo da lei, para ganhar os que estão debaixo da lei.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 21, 'Para os que estão sem lei, como se estivesse sem lei (não estando sem lei para com Deus, mas debaixo da lei de Cristo), para ganhar os que estão sem lei.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 22, 'Fiz-me como fraco para os fracos, para ganhar os fracos. Fiz-me tudo para todos, para por todos os meios chegar a salvar alguns.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 23, 'E eu faço isto por causa do evangelho, para ser também participante dele.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 24, 'Não sabeis vós que os que correm no estádio, todos, na verdade, correm, mas um só leva o prêmio? Correi de tal maneira que o alcanceis.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 25, 'E todo aquele que luta de tudo se abstém; eles o fazem para alcançar uma coroa corruptível; nós, porém, uma incorruptível.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 26, 'Pois eu assim corro, não como a coisa incerta; assim combato, não como batendo no ar.', 2, CURRENT_TIMESTAMP, false),
(46, 9, 27, 'Antes subjugo o meu corpo, e o reduzo à servidão, para que, pregando aos outros, eu mesmo não venha de alguma maneira a ficar reprovado.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 1, 'Ora, irmãos, não quero que ignoreis que nossos pais estiveram todos debaixo da nuvem, e todos passaram pelo mar.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 2, 'E todos foram batizados em Moisés, na nuvem e no mar,', 2, CURRENT_TIMESTAMP, false),
(46, 10, 3, 'E todos comeram de uma mesma comida espiritual,', 2, CURRENT_TIMESTAMP, false),
(46, 10, 4, 'E beberam todos de uma mesma bebida espiritual, porque bebiam da pedra espiritual que os seguia; e a pedra era Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 5, 'Mas Deus não se agradou da maior parte deles, por isso foram prostrados no deserto.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 6, 'E estas coisas foram-nos feitas em figura, para que não cobicemos as coisas más, como eles cobiçaram.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 7, 'Não vos façais, pois, idólatras, como alguns deles, conforme está escrito: O povo assentou-se a comer e a beber, e levantou-se para folgar.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 8, 'E não nos forniquemos, como alguns deles fizeram; e caíram num dia vinte e três mil.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 9, 'E não tentemos a Cristo, como alguns deles também tentaram, e pereceram pelas serpentes.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 10, 'E não murmureis, como também alguns deles murmuraram, e pereceram pelo destruidor.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 11, 'Ora, tudo isto lhes sobreveio como figuras, e estão escritas para aviso nosso, para quem já são chegados os fins dos séculos.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 12, 'Aquele, pois, que cuida estar em pé, olhe não caia.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 13, 'Não veio sobre vós tentação, senão humana; mas fiel é Deus, que não vos deixará tentar acima do que podeis, antes com a tentação dará também o escape, para que a possais suportar.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 14, 'Portanto, meus amados, fugi da idolatria.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 15, 'Falo como a entendidos; julgai vós mesmos o que digo.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 16, 'Porventura o cálice de bênção, que abençoamos, não é a comunhão do sangue de Cristo? O pão que partimos não é porventura a comunhão do corpo de Cristo?', 2, CURRENT_TIMESTAMP, false),
(46, 10, 17, 'Porque nós, sendo muitos, somos um só pão e um só corpo, porque todos participamos do mesmo pão.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 18, 'Vede a Israel segundo a carne; os que comem os sacrifícios não são porventura participantes do altar?', 2, CURRENT_TIMESTAMP, false),
(46, 10, 19, 'Mas que digo? Que o ídolo é alguma coisa? Ou que o sacrificado ao ídolo é alguma coisa?', 2, CURRENT_TIMESTAMP, false),
(46, 10, 20, 'Antes digo que as coisas que os gentios sacrificam, as sacrificam aos demônios, e não a Deus. E não quero que sejais participantes com os demônios.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 21, 'Não podeis beber o cálice do Senhor e o cálice dos demônios; não podeis ser participantes da mesa do Senhor e da mesa dos demônios.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 22, 'Ou irritaremos o Senhor? Somos nós mais fortes do que ele?', 2, CURRENT_TIMESTAMP, false),
(46, 10, 23, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm; todas as coisas me são lícitas, mas nem todas as coisas edificam.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 24, 'Ninguém busque o proveito próprio; antes cada um o que é de outrem.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 25, 'Comei de tudo quanto se vende no açougue, sem perguntar nada, por causa da consciência.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 26, 'Porque a terra é do Senhor e toda a sua plenitude.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 27, 'E, se algum dos infiéis vos convidar, e quiserdes ir, comei de tudo o que se puser diante de vós, sem nada perguntar, por causa da consciência.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 28, 'Mas, se alguém vos disser: Isto foi sacrificado aos ídolos, não comais, por causa daquele que vos advertiu e por causa da consciência; porque a terra é do Senhor, e toda a sua plenitude.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 29, 'Digo, porém, a consciência, não a tua, mas a do outro. Pois por que há de a minha liberdade ser julgada pela consciência de outrem?', 2, CURRENT_TIMESTAMP, false),
(46, 10, 30, 'E, se eu com graça participo, por que sou blasfemado naquilo por que dou graças?', 2, CURRENT_TIMESTAMP, false),
(46, 10, 31, 'Portanto, quer comais quer bebais, ou façais outra qualquer coisa, fazei tudo para glória de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 32, 'Portai-vos de modo que não deis escândalo nem aos judeus, nem aos gregos, nem à igreja de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 10, 33, 'Como também eu em tudo agrado a todos, não buscando o meu próprio proveito, mas o de muitos, para que assim se possam salvar.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 1, 'Sede meus imitadores, como também eu de Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 2, 'E louvo-vos, irmãos, porque em tudo vos lembrais de mim, e retendes os preceitos como vo-los entreguei.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 3, 'Mas quero que saibais que Cristo é a cabeça de todo o homem, e o homem a cabeça da mulher; e Deus a cabeça de Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 4, 'Todo o homem que ora ou profetiza, tendo a cabeça coberta, desonra a sua própria cabeça.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 5, 'Mas toda a mulher que ora ou profetiza com a cabeça descoberta, desonra a sua própria cabeça, porque é como se estivesse rapada.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 6, 'Portanto, se a mulher não se cobre com véu, tosquie-se também. Mas, se para a mulher é coisa indecente tosquiar-se ou rapar-se, que ponha o véu.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 7, 'O homem, pois, não deve cobrir a cabeça, porque é a imagem e glória de Deus, mas a mulher é a glória do homem.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 8, 'Porque o homem não provém da mulher, mas a mulher do homem.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 9, 'Porque também o homem não foi criado por causa da mulher, mas a mulher por causa do homem.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 10, 'Portanto, a mulher deve ter sobre a cabeça sinal de poderio, por causa dos anjos.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 11, 'Todavia, nem o homem é sem a mulher, nem a mulher sem o homem, no Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 12, 'Porque, como a mulher provém do homem, assim também o homem provém da mulher, mas tudo vem de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 13, 'Julgai entre vós mesmos: é decente que a mulher ore a Deus descoberta?', 2, CURRENT_TIMESTAMP, false),
(46, 11, 14, 'Ou não vos ensina a mesma natureza que é desonra para o homem ter cabelo crescido?', 2, CURRENT_TIMESTAMP, false),
(46, 11, 15, 'Mas ter a mulher cabelo crescido lhe é honroso, porque o cabelo lhe foi dado em lugar de véu.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 16, 'Mas, se alguém quiser ser contencioso, nós não temos tal costume, nem as igrejas de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 17, 'Nisto, porém, que vou dizer-vos não vos louvo; porquanto vos ajuntais, não para melhor, senão para pior.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 18, 'Porque antes de tudo ouço que, quando vos ajuntais na igreja, há entre vós dissensões; e em parte o creio.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 19, 'E até importa que haja entre vós heresias, para que os que são sinceros se manifestem entre vós.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 20, 'De sorte que, quando vos ajuntais num lugar, não é para comer a ceia do Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 21, 'Porque, comendo, cada um toma antecipadamente a sua própria ceia; e assim um tem fome e outro embriaga-se.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 22, 'Não tendes porventura casas para comer e para beber? Ou desprezais a igreja de Deus, e envergonhais os que nada têm? Que vos direi? Louvar-vos-ei? Nisto não vos louvo.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 23, 'Porque eu recebi do Senhor o que também vos ensinei: que o Senhor Jesus, na noite em que foi traído, tomou o pão;', 2, CURRENT_TIMESTAMP, false),
(46, 11, 24, 'E, tendo dado graças, o partiu e disse: Tomai, comei; isto é o meu corpo que é partido por vós; fazei isto em memória de mim.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 25, 'Semelhantemente também, depois de cear, tomou o cálice, dizendo: Este cálice é o novo testamento no meu sangue; fazei isto, todas as vezes que beberdes, em memória de mim.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 26, 'Porque todas as vezes que comerdes este pão e beberdes este cálice anunciais a morte do Senhor, até que venha.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 27, 'Portanto, qualquer que comer este pão, ou beber o cálice do Senhor indignamente, será culpado do corpo e do sangue do Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 28, 'Examine-se, pois, o homem a si mesmo, e assim coma deste pão e beba deste cálice.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 29, 'Porque o que come e bebe indignamente, come e bebe para sua própria condenação, não discernindo o corpo do Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 30, 'Por causa disto há entre vós muitos fracos e doentes, e muitos que dormem.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 31, 'Porque, se nós nos julgássemos a nós mesmos, não seríamos julgados.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 32, 'Mas, quando somos julgados, somos repreendidos pelo Senhor, para não sermos condenados com o mundo.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 33, 'Portanto, meus irmãos, quando vos ajuntais para comer, esperai uns pelos outros.', 2, CURRENT_TIMESTAMP, false),
(46, 11, 34, 'Mas, se algum tiver fome, coma em casa, para que não vos ajunteis para condenação. Quanto às demais coisas, ordená-las-ei quando for.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 1, 'Acerca dos dons espirituais, não quero, irmãos, que sejais ignorantes.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 2, 'Vós bem sabeis que éreis gentios, levados aos ídolos mudos, conforme éreis guiados.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 3, 'Portanto, vos quero fazer compreender que ninguém que fala pelo Espírito de Deus diz: Jesus é anátema, e ninguém pode dizer que Jesus é o Senhor, senão pelo Espírito Santo.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 4, 'Ora, há diversidade de dons, mas o Espírito é o mesmo.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 5, 'E há diversidade de ministérios, mas o Senhor é o mesmo.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 6, 'E há diversidade de operações, mas é o mesmo Deus que opera tudo em todos.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 7, 'Mas a manifestação do Espírito é dada a cada um, para o que for útil.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 8, 'Porque a um pelo Espírito é dada a palavra da sabedoria; e a outro, pelo mesmo Espírito, a palavra da ciência;', 2, CURRENT_TIMESTAMP, false),
(46, 12, 9, 'E a outro, pelo mesmo Espírito, a fé; e a outro, pelo mesmo Espírito, os dons de curar;', 2, CURRENT_TIMESTAMP, false),
(46, 12, 10, 'E a outro a operação de maravilhas; e a outro a profecia; e a outro o dom de discernir os espíritos; e a outro a variedade de línguas; e a outro a interpretação das línguas.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 11, 'Mas um só e o mesmo Espírito opera todas estas coisas, repartindo particularmente a cada um como quer.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 12, 'Porque, assim como o corpo é um, e tem muitos membros, e todos os membros, sendo muitos, são um só corpo, assim é Cristo também.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 13, 'Pois todos nós fomos batizados em um Espírito, formando um corpo, quer judeus, quer gregos, quer servos, quer livres, e todos temos bebido de um Espírito.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 14, 'Porque também o corpo não é um só membro, mas muitos.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 15, 'Se o pé disser: Porque não sou mão, não sou do corpo; não será por isso do corpo?', 2, CURRENT_TIMESTAMP, false),
(46, 12, 16, 'E se a orelha disser: Porque não sou olho não sou do corpo; não será por isso do corpo?', 2, CURRENT_TIMESTAMP, false),
(46, 12, 17, 'Se todo o corpo fosse olho, onde estaria o ouvido? Se todo fosse ouvido, onde estaria o olfato?', 2, CURRENT_TIMESTAMP, false),
(46, 12, 18, 'Mas agora Deus colocou os membros no corpo, cada um deles como quis.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 19, 'E, se todos fossem um só membro, onde estaria o corpo?', 2, CURRENT_TIMESTAMP, false),
(46, 12, 20, 'Assim, pois, há muitos membros, mas um corpo.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 21, 'E o olho não pode dizer à mão: Não tenho necessidade de ti; nem ainda a cabeça aos pés: Não tenho necessidade de vós.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 22, 'Antes, os membros do corpo que parecem ser os mais fracos são necessários;', 2, CURRENT_TIMESTAMP, false),
(46, 12, 23, 'E os que reputamos serem menos honrosos no corpo, a esses honramos muito mais; e aos que em nós são menos decorosos damos muito mais honra.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 24, 'Porque os que em nós são mais nobres não têm necessidade disso, mas Deus assim formou o corpo, dando muito mais honra ao que tinha falta dela;', 2, CURRENT_TIMESTAMP, false),
(46, 12, 25, 'Para que não haja divisão no corpo, mas antes tenham os membros igual cuidado uns dos outros.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 26, 'De maneira que, se um membro padece, todos os membros padecem com ele; e, se um membro é honrado, todos os membros se regozijam com ele.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 27, 'Ora, vós sois o corpo de Cristo, e seus membros em particular.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 28, 'E a uns pôs Deus na igreja, primeiramente apóstolos, em segundo lugar profetas, em terceiro doutores, depois milagres, depois dons de curar, socorros, governos, variedades de línguas.', 2, CURRENT_TIMESTAMP, false),
(46, 12, 29, 'Porventura são todos apóstolos? são todos profetas? são todos doutores? são todos operadores de milagres?', 2, CURRENT_TIMESTAMP, false),
(46, 12, 30, 'Têm todos o dom de curar? falam todos diversas línguas? interpretam todos?', 2, CURRENT_TIMESTAMP, false),
(46, 12, 31, 'Portanto, procurai com zelo os melhores dons; e eu vos mostrarei um caminho mais excelente.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 1, 'Ainda que eu falasse as línguas dos homens e dos anjos, e não tivesse amor, seria como o metal que soa ou como o sino que tine.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 2, 'E ainda que tivesse o dom de profecia, e conhecesse todos os mistérios e toda a ciência, e ainda que tivesse toda a fé, de maneira tal que transportasse os montes, e não tivesse amor, nada seria.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 3, 'E ainda que distribuísse toda a minha fortuna para sustento dos pobres, e ainda que entregasse o meu corpo para ser queimado, e não tivesse amor, nada disso me aproveitaria.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 4, 'O amor é sofredor, é benigno; o amor não é invejoso; o amor não trata com leviandade, não se ensoberbece.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 5, 'Não se porta com indecência, não busca os seus interesses, não se irrita, não suspeita mal;', 2, CURRENT_TIMESTAMP, false),
(46, 13, 6, 'Não folga com a injustiça, mas folga com a verdade;', 2, CURRENT_TIMESTAMP, false),
(46, 13, 7, 'Tudo sofre, tudo crê, tudo espera, tudo suporta.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 8, 'O amor nunca falha; mas havendo profecias, serão aniquiladas; havendo línguas, cessarão; havendo ciência, desaparecerá;', 2, CURRENT_TIMESTAMP, false),
(46, 13, 9, 'Porque, em parte, conhecemos, e em parte profetizamos;', 2, CURRENT_TIMESTAMP, false),
(46, 13, 10, 'Mas, quando vier o que é perfeito, então o que o é em parte será aniquilado.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 11, 'Quando eu era menino, falava como menino, sentia como menino, discorria como menino, mas, logo que cheguei a ser homem, acabei com as coisas de menino.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 12, 'Porque agora vemos por espelho em enigma, mas então veremos face a face; agora conheço em parte, mas então conhecerei como também sou conhecido.', 2, CURRENT_TIMESTAMP, false),
(46, 13, 13, 'Agora, pois, permanecem a fé, a esperança e o amor, estes três, mas o maior destes é o amor.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 1, 'Segui o amor, e procurai com zelo os dons espirituais, mas principalmente o de profetizar.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 2, 'Porque o que fala em língua desconhecida não fala aos homens, senão a Deus; porque ninguém o entende, e em espírito fala mistérios.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 3, 'Mas o que profetiza fala aos homens, para edificação, exortação e consolação.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 4, 'O que fala em língua desconhecida edifica-se a si mesmo, mas o que profetiza edifica a igreja.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 5, 'E eu quero que todos vós faleis em línguas, mas muito mais que profetizeis; porque o que profetiza é maior do que o que fala em línguas, a não ser que também interprete para que a igreja receba edificação.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 6, 'E agora, irmãos, se eu for ter convosco falando em línguas, que vos aproveitaria, se não vos falasse ou por meio da revelação, ou da ciência, ou da profecia, ou da doutrina?', 2, CURRENT_TIMESTAMP, false),
(46, 14, 7, 'Da mesma sorte, se as coisas inanimadas, que fazem som, seja flauta, seja cítara, não formarem sons distintos, como se conhecerá o que se toca com a flauta ou com a cítara?', 2, CURRENT_TIMESTAMP, false),
(46, 14, 8, 'Porque, se a trombeta der sonido incerto, quem se preparará para a batalha?', 2, CURRENT_TIMESTAMP, false),
(46, 14, 9, 'Assim também vós, se com a língua não pronunciardes palavras bem inteligíveis, como se entenderá o que se diz? porque estareis como que falando ao ar.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 10, 'Há, por exemplo, tanta espécie de vozes no mundo, e nenhuma delas é sem significação.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 11, 'Mas, se eu ignorar o sentido da voz, serei bárbaro para aquele a quem falo, e o que fala será bárbaro para mim.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 12, 'Assim também vós, como desejais dons espirituais, procurai abundar neles, para edificação da igreja.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 13, 'Por isso, o que fala em língua desconhecida, ore para que a possa interpretar.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 14, 'Porque, se eu orar em língua desconhecida, o meu espírito ora bem, mas o meu entendimento fica sem fruto.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 15, 'Que farei, pois? Orarei com o espírito, mas também orarei com o entendimento; cantarei com o espírito, mas também cantarei com o entendimento.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 16, 'De outra maneira, se tu bendisseres com o espírito, como dirá o que ocupa o lugar de indouto, o Amém, sobre a tua ação de graças, visto que não sabe o que dizes?', 2, CURRENT_TIMESTAMP, false),
(46, 14, 17, 'Porque realmente tu dás bem as graças, mas o outro não é edificado.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 18, 'Dou graças ao meu Deus, porque falo mais línguas do que vós todos.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 19, 'Todavia eu antes quero falar na igreja cinco palavras na minha própria inteligência, para que possa também instruir os outros, do que dez mil palavras em língua desconhecida.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 20, 'Irmãos, não sejais meninos no entendimento, mas sede meninos na malícia, e adultos no entendimento.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 21, 'Está escrito na lei: Por gente de outras línguas, e por outros lábios, falarei a este povo; e ainda assim me não ouvirão, diz o Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 22, 'De sorte que as línguas são um sinal, não para os fiéis, mas para os infiéis; e a profecia não é sinal para os infiéis, mas para os fiéis.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 23, 'Se, pois, toda a igreja se congregar num lugar, e todos falarem em línguas, e entrarem indoutos ou infiéis, não dirão porventura que estais loucos?', 2, CURRENT_TIMESTAMP, false),
(46, 14, 24, 'Mas, se todos profetizarem, e algum indouto ou infiel entrar, de todos é convencido, de todos é julgado.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 25, 'E, portanto, os segredos do seu coração ficam manifestos, e assim, lançando-se sobre o seu rosto, adorará a Deus, publicando que Deus está verdadeiramente entre vós.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 26, 'Que fareis pois, irmãos? Quando vos ajuntais, cada um de vós tem salmo, tem doutrina, tem revelação, tem língua, tem interpretação. Faça-se tudo para edificação.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 27, 'E, se alguém falar em língua desconhecida, faça-se isso por dois, ou quando muito três, e por sua vez, e haja intérprete.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 28, 'Mas, se não houver intérprete, esteja calado na igreja, e fale consigo mesmo, e com Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 29, 'E falem dois ou três profetas, e os outros julguem.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 30, 'Mas, se a outro, que estiver assentado, for revelada alguma coisa, cale-se o primeiro.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 31, 'Porque todos podereis profetizar, uns depois dos outros; para que todos aprendam, e todos sejam consolados.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 32, 'E os espíritos dos profetas estão sujeitos aos profetas.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 33, 'Porque Deus não é Deus de confusão, senão de paz, como em todas as igrejas dos santos.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 34, 'As vossas mulheres estejam caladas nas igrejas; porque não lhes é permitido falar; mas estejam sujeitas, como também ordena a lei.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 35, 'E, se querem aprender alguma coisa, interroguem em casa a seus próprios maridos; porque é vergonhoso que as mulheres falem na igreja.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 36, 'Porventura saiu dentre vós a palavra de Deus? Ou veio ela somente para vós?', 2, CURRENT_TIMESTAMP, false),
(46, 14, 37, 'Se alguém cuida ser profeta, ou espiritual, reconheça que as coisas que vos escrevo são mandamentos do Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 38, 'Mas, se alguém ignora isto, que ignore.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 39, 'Portanto, irmãos, procurai, com zelo, profetizar, e não proibais falar línguas.', 2, CURRENT_TIMESTAMP, false),
(46, 14, 40, 'Mas faça-se tudo decentemente e com ordem.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 1, 'Também vos notifico, irmãos, o evangelho que já vos tenho anunciado; o qual também recebestes, e no qual também permaneceis.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 2, 'Pelo qual também sois salvos se o retiverdes tal como vo-lo tenho anunciado; se não é que crestes em vão.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 3, 'Porque primeiramente vos entreguei o que também recebi: que Cristo morreu por nossos pecados, segundo as Escrituras,', 2, CURRENT_TIMESTAMP, false),
(46, 15, 4, 'E que foi sepultado, e que ressuscitou ao terceiro dia, segundo as Escrituras.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 5, 'E que foi visto por Cefas, e depois pelos doze.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 6, 'Depois foi visto, uma vez, por mais de quinhentos irmãos, dos quais vive ainda a maior parte, mas alguns já dormem também.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 7, 'Depois foi visto por Tiago, depois por todos os apóstolos.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 8, 'E por derradeiro de todos me apareceu também a mim, como a um abortivo.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 9, 'Porque eu sou o menor dos apóstolos, que não sou digno de ser chamado apóstolo, pois que persegui a igreja de Deus.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 10, 'Mas pela graça de Deus sou o que sou; e a sua graça para comigo não foi vã, antes trabalhei muito mais do que todos eles; todavia não eu, mas a graça de Deus, que está comigo.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 11, 'Então, ou seja eu ou sejam eles, assim pregamos e assim haveis crido.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 12, 'Ora, se se prega que Cristo ressuscitou dentre os mortos, como dizem alguns dentre vós que não há ressurreição de mortos?', 2, CURRENT_TIMESTAMP, false),
(46, 15, 13, 'E, se não há ressurreição de mortos, também Cristo não ressuscitou.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 14, 'E, se Cristo não ressuscitou, logo é vã a nossa pregação, e também é vã a vossa fé.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 15, 'E assim somos também considerados como falsas testemunhas de Deus, pois testificamos de Deus, que ressuscitou a Cristo, ao qual, porém, não ressuscitou, se, na verdade, os mortos não ressuscitam.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 16, 'Porque, se os mortos não ressuscitam, também Cristo não ressuscitou.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 17, 'E, se Cristo não ressuscitou, é vã a vossa fé, e ainda permaneceis nos vossos pecados.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 18, 'E também os que dormiram em Cristo estão perdidos.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 19, 'Se esperamos em Cristo só nesta vida, somos os mais miseráveis de todos os homens.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 20, 'Mas de fato Cristo ressuscitou dentre os mortos, e foi feito as primícias dos que dormem.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 21, 'Porque assim como a morte veio por um homem, também a ressurreição dos mortos veio por um homem.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 22, 'Porque, assim como todos morrem em Adão, assim também todos serão vivificados em Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 23, 'Mas cada um por sua ordem: Cristo as primícias, depois os que são de Cristo, na sua vinda.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 24, 'Depois virá o fim, quando tiver entregado o reino a Deus, ao Pai, e quando houver aniquilado todo o império, e toda a potestade e força.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 25, 'Porque convém que reine até que haja posto a todos os inimigos debaixo de seus pés.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 26, 'Ora, o último inimigo que há de ser aniquilado é a morte.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 27, 'Porque todas as coisas sujeitou debaixo de seus pés. Mas, quando diz que todas as coisas lhe estão sujeitas, claro está que se excetua aquele que lhe sujeitou todas as coisas.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 28, 'E, quando todas as coisas lhe estiverem sujeitas, então também o mesmo Filho se sujeitará àquele que todas as coisas lhe sujeitou, para que Deus seja tudo em todos.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 29, 'Doutra maneira, que farão os que se batizam pelos mortos, se absolutamente os mortos não ressuscitam? Por que se batizam eles então pelos mortos?', 2, CURRENT_TIMESTAMP, false),
(46, 15, 30, 'Por que estamos nós também a toda a hora em perigo?', 2, CURRENT_TIMESTAMP, false),
(46, 15, 31, 'Eu protesto que cada dia morro, gloriando-me em vós, irmãos, por Cristo Jesus nosso Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 32, 'Se, como homem, combati em Éfeso contra as bestas, que me aproveita isso, se os mortos não ressuscitam? Comamos e bebamos, que amanhã morreremos.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 33, 'Não vos enganeis: as más conversações corrompem os bons costumes.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 34, 'Vigiai justamente e não pequeis; porque alguns ainda não têm o conhecimento de Deus; digo-o para vergonha vossa.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 35, 'Mas alguém dirá: Como ressuscitarão os mortos? E com que corpo virão?', 2, CURRENT_TIMESTAMP, false),
(46, 15, 36, 'Insensato! o que tu semeias não é vivificado, se primeiro não morrer.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 37, 'E, quando semeias, não semeias o corpo que há de nascer, mas o simples grão, como de trigo, ou de outra qualquer semente.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 38, 'Mas Deus dá-lhe o corpo como quer, e a cada semente o seu próprio corpo.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 39, 'Nem toda a carne é uma mesma carne, mas uma é a carne dos homens, e outra a carne dos animais, e outra a dos peixes e outra a das aves.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 40, 'E há corpos celestes e corpos terrestres, mas uma é a glória dos celestes e outra a dos terrestres.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 41, 'Uma é a glória do sol, e outra a glória da lua, e outra a glória das estrelas; porque uma estrela difere em glória de outra estrela.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 42, 'Assim também a ressurreição dentre os mortos. Semeia-se o corpo em corrupção; ressuscitará em incorrupção.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 43, 'Semeia-se em ignomínia, ressuscitará em glória. Semeia-se em fraqueza, ressuscitará com vigor.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 44, 'Semeia-se corpo natural, ressuscitará corpo espiritual. Se há corpo natural, há também corpo espiritual.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 45, 'Assim está também escrito: O primeiro homem, Adão, foi feito em alma vivente; o último Adão em espírito vivificante.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 46, 'Mas não é primeiro o espiritual, senão o natural; depois o espiritual.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 47, 'O primeiro homem, da terra, é terreno; o segundo homem, o Senhor, é do céu.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 48, 'Qual o terreno, tais são também os terrestres; e, qual o celestial, tais também os celestiais.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 49, 'E, assim como trouxemos a imagem do terreno, assim traremos também a imagem do celestial.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 50, 'E agora digo isto, irmãos: que a carne e o sangue não podem herdar o reino de Deus, nem a corrupção herdar a incorrupção.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 51, 'Eis aqui vos digo um mistério: Na verdade, nem todos dormiremos, mas todos seremos transformados;', 2, CURRENT_TIMESTAMP, false),
(46, 15, 52, 'Num momento, num abrir e fechar de olhos, ante a última trombeta; porque a trombeta soará, e os mortos ressuscitarão incorruptíveis, e nós seremos transformados.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 53, 'Porque convém que isto que é corruptível se revista da incorruptibilidade, e que isto que é mortal se revista da imortalidade.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 54, 'E, quando isto que é corruptível se revestir da incorruptibilidade, e isto que é mortal se revestir da imortalidade, então cumprir-se-á a palavra que está escrita: Tragada foi a morte na vitória.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 55, 'Onde está, ó morte, o teu aguilhão? Onde está, ó inferno, a tua vitória?', 2, CURRENT_TIMESTAMP, false),
(46, 15, 56, 'Ora, o aguilhão da morte é o pecado, e a força do pecado é a lei.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 57, 'Mas graças a Deus que nos dá a vitória por nosso Senhor Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(46, 15, 58, 'Portanto, meus amados irmãos, sede firmes e constantes, sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão no Senhor.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 1, 'Ora, quanto à coleta que se faz para os santos, fazei vós também o mesmo que ordenei às igrejas da Galácia.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 2, 'No primeiro dia da semana cada um de vós ponha de parte o que puder ajuntar, conforme a sua prosperidade, para que não se façam as coletas quando eu chegar.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 3, 'E, quando tiver chegado, mandarei os que por cartas aprovardes, para levar a vossa dádiva a Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 4, 'E, se valer a pena que eu também vá, irão comigo.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 5, 'Irei, porém, ter convosco depois de ter passado pela macedônia (porque tenho de passar pela macedônia).', 2, CURRENT_TIMESTAMP, false),
(46, 16, 6, 'E bem pode ser que fique convosco, e passe também o inverno, para que me acompanheis aonde quer que eu for.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 7, 'Porque não vos quero agora ver de passagem, mas espero ficar convosco algum tempo, se o Senhor o permitir.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 8, 'Ficarei, porém, em Éfeso até ao Pentecostes;', 2, CURRENT_TIMESTAMP, false),
(46, 16, 9, 'Porque uma porta grande e eficaz se me abriu; e há muitos adversários.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 10, 'E, se Timóteo for, vede que esteja sem temor convosco; porque trabalha na obra do Senhor, como eu também.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 11, 'Portanto, ninguém o despreze, mas acompanhai-o em paz, para que venha ter comigo; pois o espero com os irmãos.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 12, 'E, acerca do irmão Apolo, roguei-lhe muito que fosse com os irmãos ter convosco, mas, na verdade, não teve vontade de ir agora; irá, porém, quando se lhe oferecer boa ocasião.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 13, 'Vigiai, estai firmes na fé; portai-vos varonilmente, e fortalecei-vos.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 14, 'Todas as vossas coisas sejam feitas com amor.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 15, 'Agora vos rogo, irmãos (sabeis que a família de Estéfanas é as primícias da Acaia, e que se tem dedicado ao ministério dos santos),', 2, CURRENT_TIMESTAMP, false),
(46, 16, 16, 'Que também vos sujeiteis aos tais, e a todo aquele que auxilia na obra e trabalha.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 17, 'Folgo, porém, com a vinda de Estéfanas, de Fortunato e de Acaico; porque estes supriram o que da vossa parte me faltava.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 18, 'Porque recrearam o meu espírito e o vosso. Reconhecei, pois, aos tais.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 19, 'As igrejas da Ásia vos saúdam. Saúdam-vos afetuosamente no Senhor áqüila e Priscila, com a igreja que está em sua casa.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 20, 'Todos os irmãos vos saúdam. Saudai-vos uns aos outros com ósculo santo.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 21, 'Saudação da minha própria mão, de Paulo.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 22, 'Se alguém não ama ao Senhor Jesus Cristo, seja anátema. Maranata!', 2, CURRENT_TIMESTAMP, false),
(46, 16, 23, 'A graça do Senhor Jesus Cristo seja convosco.', 2, CURRENT_TIMESTAMP, false),
(46, 16, 24, 'O meu amor seja com todos vós em Cristo Jesus. Amém.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 1, 'Adão, Sete, Enos,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 2, 'Cainã, Maalaleel, Jerede,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 3, 'Enoque, Matusalém, Lameque,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 4, 'Noé, Sem, Cão e Jafé.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 5, 'Os filhos de Jafé foram: Gomer, Magogue, Madai, Javã, Tubal, Meseque e Tiras.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 6, 'E os filhos de Gomer: Asquenaz, Rifate, Togarma.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 7, 'E os filhos de Javã: Elisá, Társis, Quitim e Dodanim.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 8, 'Os filhos de Cão: Cuxe, Mizraim, Pute e Canaã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 9, 'E os filhos de Cuxe eram: Sebá, Havilá, Sabtá, Raamá e Sabtecá; os filhos de Raamá: Sebá e Dedã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 10, 'E Cuxe gerou a Ninrode, que começou a ser poderoso na terra.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 11, 'E Mizraim gerou a Ludim e a Anamim e a Leabim e a Naftuim,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 12, 'E a Patrusim e a Casluim (dos quais procedem os filisteus) e a Caftorim.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 13, 'E Canaã gerou a Sidom seu primogênito, e a Hete,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 14, 'E aos jebuseus e aos amorreus e aos girgaseus,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 15, 'E aos heveus e aos arqueus e aos sineus,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 16, 'E aos arvadeus e aos zemareus e aos hamateus.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 17, 'E foram os filhos de Sem: Elão, Assur, Arfaxade, Lude, Arã, Uz, Hul, Geter e Meseque.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 18, 'E Arfaxade gerou a Selá e Selá gerou a Éber.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 19, 'E a Éber nasceram dois filhos: o nome de um foi Pelegue, porquanto nos seus dias se repartiu a terra, e o nome de seu irmão era Joctã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 20, 'E Joctã gerou a Almodá, a Selefe, a Hazarmavé, e a Jerá,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 21, 'E a Hadorão, a Usal, e a Dicla,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 22, 'E a Obal, a Abimael, a Sebá,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 23, 'E a Ofir, a Havilá, e a Jobabe: todos estes foram filhos de Joctã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 24, 'Sem, Arfaxade, Selá,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 25, 'Éber, Pelegue, Reú,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 26, 'Serugue, Naor, Terá,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 27, 'Abrão, que é Abraão.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 28, 'Os filhos de Abraão foram: Isaque e Ismael.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 29, 'Estas são as suas gerações: o primogênito de Ismael foi Nebaiote, e, depois, Quedar, Adbeel, Mibsão,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 30, 'Misma, Dumá, Massá, Hadade, Tema,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 31, 'Jetur, Nafis e Quedemá; estes foram os filhos de Ismael.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 32, 'Quanto aos filhos de Quetura, concubina de Abraão, esta deu à luz a Zinrã, a Jocsã, a Medã, a Midiã, a Jisbaque e a Suá; e os filhos de Jocsã foram Seba e Dedã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 33, 'E os filhos de Midiã: Efá, Efer, Enoque, Abida e Elda; todos estes foram filhos de Quetura.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 34, 'Abraão, pois, gerou a Isaque; e foram os filhos de Isaque: Esaú e Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 35, 'Os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão e Coré.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 36, 'Os filhos de Elifaz: Temã, Omar, Zefi, Gaetã, Quenaz, Timna e Amaleque.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 37, 'Os filhos de Reuel: Naate, Zerá, Samá e Mizá.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 38, 'E os filhos de Seir: Lotã, Sobal, Zibeão, Aná, Disom, Eser e Disã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 39, 'E os filhos de Lotã: Hori e Homã; e a irmã de Lotã foi Timna.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 40, 'Os filhos de Sobal eram Alvã, Manaate, Ebal, Sefi e Onã; e os filhos de Zibeão eram Aiá e Aná.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 41, 'O filho de Aná foi Disom; e os filhos de Disom foram Hanrão, Esbã, Itrã e Querã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 42, 'Os filhos de Eser eram: Bilã, Zaavã e Jaacã; os filhos de Disã eram: Uz e Arã.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 43, 'E estes são os reis que reinaram na terra de Edom, antes que reinasse rei sobre os filhos de Israel: Bela, filho de Beor, e era o nome da sua cidade Dinabá.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 44, 'E morreu Bela, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 45, 'E morreu Jobabe, e reinou em seu lugar Husão, da terra dos temanitas.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 46, 'E morreu Husão, e reinou em seu lugar Hadade, filho de Bedade; este feriu os midianitas no campo de Moabe; e era o nome da sua cidade Avite.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 47, 'E morreu Hadade, e reinou em seu lugar Samlá, de Masreca.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 48, 'E morreu Samlá, e reinou em seu lugar Saul, de Reobote, junto ao rio.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 49, 'E morreu Saul, e reinou em seu lugar Baal-Hanã, filho de Acbor.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 50, 'E, morrendo Baal-Hanã, Hadade reinou em seu lugar; e era o nome da sua cidade Paí; e o nome de sua mulher era Meetabel, filha de Matrede, filha de Me-Zaabe.', 2, CURRENT_TIMESTAMP, false),
(13, 1, 51, 'E, morrendo Hadade, foram príncipes em Edom o príncipe Timna, o príncipe Alva, o príncipe Jetete,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 52, 'O príncipe Oolibama, o príncipe Elá, o príncipe Pinom,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 53, 'O príncipe Quenaz, o príncipe Temã, o príncipe Mibzar,', 2, CURRENT_TIMESTAMP, false),
(13, 1, 54, 'O príncipe Magdiel, o príncipe Irã, estes foram os príncipes de Edom.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 1, 'Estes são os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar e Zebulom;', 2, CURRENT_TIMESTAMP, false),
(13, 2, 2, 'Dã, José e Benjamim, Naftali, Gade e Aser.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 3, 'Os filhos de Judá foram Er, e Onã, e Selá, estes três lhe nasceram da filha de Suá, a cananéia; e Er, o primogênito de Judá, foi mau aos olhos do Senhor, pelo que o matou.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 4, 'Porém Tamar, sua nora, lhe deu à luz Perez e Zerá; todos os filhos de Judá foram cinco.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 5, 'Os filhos de Perez foram Hezrom e Hamul.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 6, 'E os filhos de Zerá: Zinri, e Etã, e Hemã, e Calcol, e Dara: cinco ao todo.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 7, 'E os filhos de Carmi foram Acar, o perturbador de Israel, que pecou no anátema.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 8, 'E o filho de Etã foi Azarias.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 9, 'E os filhos de Hezrom, que lhe nasceram, foram Jerameel, e Rão, e Quelubai.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 10, 'E Rão gerou a Aminadabe, e Aminadabe gerou a Naassom, príncipe dos filhos de Judá.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 11, 'E Naassom gerou a Salma, e Salma gerou a Boaz.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 12, 'E Boaz gerou a Obede, e Obede gerou a Jessé.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 13, 'E Jessé gerou a Eliabe, seu primogênito, e Abinadabe, o segundo, e Siméia, o terceiro.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 14, 'Natanael, o quarto, Radai, o quinto.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 15, 'Ozém, o sexto, Davi, o sétimo.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 16, 'E foram suas irmãs Zeruia e Abigail; e foram os filhos de Zeruia: Abisai e Joabe, e Asael, três.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 17, 'E Abigail deu à luz a Amasa; e o pai de Amasa foi Jeter, o ismaelita.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 18, 'E Calebe, filho de Hezrom, gerou filhos de Azuba, sua mulher, e de Jeriote; e os filhos desta foram estes: Jeser, Sobabe, e Ardom.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 19, 'E morreu Azuba; e Calebe tomou para si a Efrate, da qual lhe nasceu Hur.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 20, 'E Hur gerou a Uri, e Uri gerou a Bezaleel.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 21, 'Então Hezrom coabitou com a filha de Maquir, pai de Gileade, e, sendo ele de sessenta anos, a tomou; e ela deu à luz a Segube.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 22, 'E Segube gerou a Jair; e este tinha vinte e três cidades na terra de Gileade.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 23, 'E Gesur e Arã tomaram deles as aldeias de Jair, e Quenate, e seus lugares, sessenta cidades; todos estes foram filhos de Maquir, pai de Gileade.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 24, 'E, depois da morte de Hezrom, em Calebe de Efrata, Abia, mulher de Hezrom, deu à luz a Asur, pai de Tecoa.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 25, 'E os filhos de Jerameel, primogênito de Hezrom, foram Rão, o primogênito, Buna, Orem, Ozém e Aías.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 26, 'Teve também Jerameel ainda outra mulher cujo nome era Atara; esta foi a mãe de Onã.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 27, 'E foram os filhos de Rão, primogênito de Jerameel: Maaz, Jamim, e Equer.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 28, 'E foram os filhos de Onã: Samai e Jada; e os filhos de Samai: Nadabe e Abisur.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 29, 'E o nome da mulher de Abisur era Abiail, que lhe deu a Abã e a Molide.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 30, 'E foram os filhos de Nadabe, Selede e Apaim; e Selede morreu sem filhos.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 31, 'E o filho de Apaim foi Isi; e o filho de Isi, Sesã. E o filho de Sesã, Alai.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 32, 'E os filhos de Jada, irmão de Samai, foram Jeter e Jônatas; e Jeter morreu sem filhos.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 33, 'E os filhos de Jônatas foram: Pelete e Zaza; estes foram os filhos de Jerameel.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 34, 'E Sesã não teve filhos, mas filhas; e tinha Sesã um servo egípcio, cujo nome era Jará.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 35, 'Deu, pois, Sesã sua filha por mulher a Jará, seu servo; e lhe deu à luz a Atai.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 36, 'E Atai gerou a Natã, e Natã gerou a Zabade.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 37, 'E Zabade gerou a Eflal, e Eflal gerou a Obede.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 38, 'E Obede gerou a Jeú, e Jeú gerou a Azarias.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 39, 'E Azarias gerou a Helez, e Helez gerou a Eleasá.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 40, 'E Eleasá gerou a Sismai, e Sismai gerou a Salum.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 41, 'E Salum gerou a Jecamias, e Jecamias gerou a Elisama.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 42, 'E foram os filhos de Calebe, irmão de Jerameel, Messa, seu primogênito (este foi o pai de Zife), e os filhos de Maressa, pai de Hebrom.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 43, 'E foram os filhos de Hebrom: Coré, Tápua, Requém e Sema.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 44, 'E Sema gerou a Raão, pai de Jorqueão; e Requém gerou a Samai.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 45, 'E foi o filho de Samai, Maom; e Maom foi pai de Bete-Zur.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 46, 'E Efá, a concubina de Calebe, deu à luz a Harã, a Mosa, e a Gazez; e Harã gerou a Gazez.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 47, 'E foram filhos de Jadai: Regém, Jotão, Gesã, Pelete, Efá e Saafe.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 48, 'De Maaca, concubina, Calebe gerou a Seber e a Tiraná.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 49, 'E a mulher de Saafe, pai de Madmana, deu à luz a Seva, pai de Macbena e pai de Gibeá; e foi a filha de Calebe, Acsa.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 50, 'Estes foram os filhos de Calebe, filho de Hur, o primogênito de Efrata: Sobal, pai de Quiriate-Jearim,', 2, CURRENT_TIMESTAMP, false),
(13, 2, 51, 'E Salma, pai dos belemitas, Harefe, pai de Bete-Gader.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 52, 'E foram os filhos de Sobal, pai de Quiriate-Jearim: Haroé e metade dos menuítas.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 53, 'E as famílias de Quiriate-Jearim foram os jitreus, e os puteus, e os sumateus, e os misraeus; destes saíram os zorateus, e os estaoleus.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 54, 'Os filhos de Salma foram Belém e os netofatitas, Atarote, Bete-Joabe, e metade dos manaatitas, e os zoritas.', 2, CURRENT_TIMESTAMP, false),
(13, 2, 55, 'E as famílias dos escribas que habitavam em Jabez foram os tiratitas, os simeatitas e os sucatitas; estes são os queneus, que vieram de Hamate, pai da casa de Recabe.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 1, 'E estes foram os filhos de Davi, que lhe nasceram em Hebrom: o primogênito, Amnom, de Ainoã, a jizreelita; o segundo Daniel, de Abigail, a carmelita;', 2, CURRENT_TIMESTAMP, false),
(13, 3, 2, 'O terceiro, Absalão, filho de Maaca, filha de Talmai, rei de Gesur; o quarto, Adonias, filho de Hagite;', 2, CURRENT_TIMESTAMP, false),
(13, 3, 3, 'O quinto, Sefatias, de Abital; o sexto, Itreão, de Eglá, sua mulher.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 4, 'Seis filhos lhe nasceram em Hebrom, porque ali reinou sete anos e seis meses; e trinta e três anos reinou em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 5, 'E estes lhe nasceram em Jerusalém: Siméia, e Sobabe, e Natã, e Salomão; estes quatro lhe nasceram de Bate-Sua, filha de Amiel.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 6, 'Nasceram-lhe mais Ibar, Elisama, Elifelete,', 2, CURRENT_TIMESTAMP, false),
(13, 3, 7, 'Nogá, Nefegue, Jafia,', 2, CURRENT_TIMESTAMP, false),
(13, 3, 8, 'Elisama, Eliada, e Elifelete, nove.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 9, 'Todos estes foram filhos de Davi, afora os filhos das concubinas e Tamar, irmã deles.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 10, 'E o filho de Salomão foi Roboão; de quem foi filho Abias; de quem foi filho Asa; de quem foi filho Jeosafá;', 2, CURRENT_TIMESTAMP, false),
(13, 3, 11, 'De quem foi filho Jorão; de quem foi filho Acazias; de quem foi filho Joás;', 2, CURRENT_TIMESTAMP, false),
(13, 3, 12, 'De quem foi filho Amazias; de quem foi filho Jotão;', 2, CURRENT_TIMESTAMP, false),
(13, 3, 13, 'De quem foi filho Acaz; de quem foi filho Ezequias; de quem foi filho Manassés;', 2, CURRENT_TIMESTAMP, false),
(13, 3, 14, 'De quem foi filho Amom; de quem foi filho Josias.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 15, 'E os filhos de Josias foram: o primogênito, Joanã: o segundo, Jeoiaquim; o terceiro, Zedequias; o quarto, Salum.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 16, 'E os filhos de Jeoiaquim: Jeconias, seu filho, e Zedequias, seu filho.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 17, 'E os filhos de Jeconias: Assir, e seu filho Sealtiel.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 18, 'Os filhos deste foram: Malquirão, Pedaías, Senazar, Jecamias, Hosama, e Nedabias.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 19, 'E os filhos de Pedaías: Zorobabel e Simei; e os filhos de Zorobabel: Mesulão, Hananias, e Selomite, sua irmã,', 2, CURRENT_TIMESTAMP, false),
(13, 3, 20, 'E Hasubá, Oel, Berequias, Hasadias, Jusabe-Hesede, cinco.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 21, 'E os filhos de Hananias: Pelatias e Jesaías; os filhos de Refaías, os filhos de Arnã, os filhos de Obadias, e os filhos de Secanias.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 22, 'E o filho de Secanias foi Semaías; e os filhos de Semaías: Hatus, e Igeal, e Bariá, e Nearias, e Safate, seis.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 23, 'E os filhos de Nearias: Elioenai, e Ezequias, e Azricão, três.', 2, CURRENT_TIMESTAMP, false),
(13, 3, 24, 'E os filhos de Elioenai; Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías, e Anani, sete.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 1, 'Os filhos de Judá foram: Perez, Hezrom, Carmi, Hur, e Sobal.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 2, 'E Reaías, filho de Sobal gerou a Jaate, e Jaate gerou a Aumai e a Laade; estas são as famílias dos zoratitas.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 3, 'E estes foram os filhos do pai de Etã: Jizreel, Isma e Idbas; e era o nome de sua irmã Hazelelponi.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 4, 'E mais Penuel, pai de Gedor, e Ezer, pai de Husá; estes foram os filhos de Hur, o primogênito de Efrata, pai de Belém.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 5, 'E tinha Asur, pai de Tecoa, duas mulheres: Helá e Naará.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 6, 'E Naará deu à luz a Auzão, e a Hefer, e a Temeni, e a Haastari; estes foram os filhos de Naará.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 7, 'E os filhos de Helá: Zerete, Izar e Etnã.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 8, 'E Coz gerou a Anube e a Zobeba e as famílias de Aarel, filho de Harum.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 9, 'E foi Jabez mais ilustre do que seus irmãos; e sua mãe deu-lhe o nome de Jabez, dizendo: Porquanto com dores o dei à luz.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 10, 'Porque Jabez invocou o Deus de Israel, dizendo: Se me abençoares muitíssimo, e meus termos ampliares, e a tua mão for comigo, e fizeres que do mal não seja afligido! E Deus lhe concedeu o que lhe tinha pedido.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 11, 'E Quelube, irmão de Suá, gerou a Meir; este é o pai de Estom.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 12, 'E Estom gerou a Bete-Rafa, a Pasea, e a Teina, pai de Ir-Naás; estes foram os homens de Reca.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 13, 'E foram os filhos de Quenaz: Otniel e Seraías; o filho de Otniel: Hatate.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 14, 'E Meonotai gerou a Ofra, e Seraías gerou a Joabe, pai dos do vale dos artífices; porque os dali eram artífices.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 15, 'E foram os filhos de Calebe, filho de Jefoné: Iru, Elá e Naã; e o filho de Elá: Quenaz.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 16, 'E os filhos de Jealelel: Zife, Zifa, Tiria e Asareel.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 17, 'E os filhos de Ezra: Jeter, Merede, Efer, e Jalom; e teve mais a Miriã, e Samai, e Isbá, pai de Estemoa.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 18, 'E sua mulher, Judia, deu à luz a Jerede, pai de Gedor, e a Héber, pai de Socó, e a Jecutiel, pai de Zanoa; e estes foram os filhos de Bitia, filha de Faraó, que Merede tomou.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 19, 'E foram os filhos da mulher de Hodias, irmã de Naã: Abiqueila, o garmita, Estemoa, o maacatita.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 20, 'E os filhos de Simeão: Amom, Rina, Bene-Hanã, e Tilom; e os filhos de Isi: Zoete e Bene-Zoete.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 21, 'Os filhos de Selá, filho de Judá: Er, pai de Leca, e Lada, pai de Maressa, e as famílias da casa dos que fabricavam linho fino, em casa de Asbéia.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 22, 'Como também Joquim, e os homens de Cozeba, e Joás, e Sarafe (que dominaram sobre os moabitas), e Jasubi-Leém; porém estas coisas já são antigas.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 23, 'Estes foram oleiros, e habitavam nas hortas e nos cerrados; estes ficaram ali com o rei na sua obra.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 24, 'Os filhos de Simeão foram Nemuel, Jamim, Jaribe, Zerá, e Saul,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 25, 'Cujo filho foi Salum, de quem foi filho Mibsão, de quem foi filho Misma.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 26, 'E os filhos de Misma foram: Hamuel, de quem foi filho Zacur, de quem foi filho Simei.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 27, 'E Simei teve dezesseis filhos, e seis filhas, porém seus irmãos não tiveram muitos filhos; e toda a sua família não se multiplicou tanto como as dos filhos de Judá.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 28, 'E habitaram em Berseba, e em Moladá, e em Hazar-Sual,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 29, 'E em Bila, e em Ezém, e em Tolade,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 30, 'E em Betuel, e em Hormá, e em Ziclague,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 31, 'E em Bete-Marcabote, e em Hazar-Susim, e em Bete-Biri, e em Saaraim; estas foram as suas cidades, até que Davi reinou.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 32, 'E foram as suas aldeias: Etã, Aim, Rimom, Toquém, e Asã, cinco cidades,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 33, 'E todas as suas aldeias, que estavam em redor destas cidades, até Baal. Estas foram as suas habitações e suas genealogias.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 34, 'Porém Mesobabe, e Janleque e Josa, filho de Amazias,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 35, 'E Joel, e Jeú, filho de Josibias, filho de Seraías, filho de Asiel,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 36, 'E Elioenai e Jaacobá, Jesoaías, Asaías, Adiel, Jesimiel, Benaias,', 2, CURRENT_TIMESTAMP, false),
(13, 4, 37, 'E Ziza, filho de Sifi, filho de Alom, filho de Jedaías, filho de Sinri, filho de Semaías;', 2, CURRENT_TIMESTAMP, false),
(13, 4, 38, 'Estes, registrados por seus nomes, foram príncipes nas suas famílias; e as famílias de seus pais se multiplicaram abundantemente.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 39, 'E chegaram até à entrada de Gedor, ao oriente do vale, a buscar pasto para os seus rebanhos.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 40, 'E acharam pasto fértil e terra espaçosa, e quieta, e descansada; porque os de Cão haviam habitado ali antes.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 41, 'Estes, pois, que estão descritos por seus nomes, vieram nos dias de Ezequias, rei de Judá, e derrubaram as tendas e habitações dos que se acharam ali, e as destruíram totalmente até o dia de hoje, e habitaram em seu lugar; porque ali havia pasto para os seus rebanhos.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 42, 'Também deles, dos filhos de Simeão, quinhentos homens foram às montanhas de Seir; levaram por cabeças a Pelatias, e a Nearias, e a Refaías, e a Uziel, filhos de Isi.', 2, CURRENT_TIMESTAMP, false),
(13, 4, 43, 'E feriram o restante dos que escaparam dos amalequitas, e habitaram ali até o dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 1, 'Quanto aos filhos de Rúben, o primogênito de Israel (pois ele era o primogênito; mas porque profanara a cama de seu pai, deu-se a sua primogenitura aos filhos de José, filho de Israel; de modo que não foi contado, na genealogia da primogenitura,', 2, CURRENT_TIMESTAMP, false),
(13, 5, 2, 'Porque Judá foi poderoso entre seus irmãos, e dele veio o soberano; porém a primogenitura foi de José).', 2, CURRENT_TIMESTAMP, false),
(13, 5, 3, 'Foram, pois, os filhos de Rúben, o primogênito de Israel: Enoque, Palu, Hezrom, e Carmi.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 4, 'Os filhos de Joel: Semaías, seu filho; Gogue, seu filho; Simei, seu filho;', 2, CURRENT_TIMESTAMP, false),
(13, 5, 5, 'Mica, seu filho; Reaías, seu filho; Baal, seu filho;', 2, CURRENT_TIMESTAMP, false),
(13, 5, 6, 'Beera, seu filho, o qual Tiglate-Pilneser, rei da Assíria, levou preso; este foi príncipe dos rubenitas.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 7, 'Quanto a seus irmãos pelas suas famílias, quando foram postos nas genealogias, segundo as suas descendências, tiveram por chefes Jeiel e Zacarias,', 2, CURRENT_TIMESTAMP, false),
(13, 5, 8, 'E Bela, filho de Azaz, filho de Sema, filho de Joel, que habitou em Aroer, até Nebo e Baal-Meom,', 2, CURRENT_TIMESTAMP, false),
(13, 5, 9, 'Também habitou do lado do oriente, até à entrada do deserto, desde o rio Eufrates; porque seu gado se tinha multiplicado na terra de Gileade.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 10, 'E nos dias de Saul fizeram guerra aos hagarenos, que caíram pela sua mão; e eles habitaram nas suas tendas defronte de todo o lado oriental de Gileade.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 11, 'E os filhos de Gade habitaram defronte deles, na terra de Basã, até Salcá.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 12, 'Joel foi chefe, e Safã o segundo; também Janai e Safate estavam em Basã.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 13, 'E seus irmãos, segundo as suas casas paternas, foram: Micael, Mesulão, Seba, Jorai, Jacã, Zia, e Éber, sete.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 14, 'Estes foram os filhos de Abiail filho de Huri, filho de Jaroa, filho de Gileade, filho de Micael, filho de Jesisai, filho de Jado, filho de Buz;', 2, CURRENT_TIMESTAMP, false),
(13, 5, 15, 'Aí, filho de Abdiel, filho de Guni, foi chefe da casa de seus pais.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 16, 'E habitaram em Gileade, em Basã e nos lugares da sua jurisdição; como também em todos os arrabaldes de Sarom, até aos seus termos.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 17, 'Todos estes foram registrados, segundo as suas genealogias, nos dias de Jotão, rei de Judá, e nos dias de Jeroboão, rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 18, 'Dos filhos de Rúben, e dos gaditas, e da meia tribo de Manassés, homens muito valentes, que traziam escudo e espada, e entesavam o arco, e eram destros na guerra; houve quarenta e quatro mil e setecentos e sessenta, que saíam à peleja.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 19, 'E fizeram guerra aos hagarenos, como a Jetur, e a Nafis e a Nodabe.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 20, 'E foram ajudados contra eles, e os hagarenos e todos quantos estavam com eles foram entregues em sua mão; porque, na peleja, clamaram a Deus que lhes deu ouvidos, porquanto confiaram nele.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 21, 'E levaram preso o seu gado; seus camelos, cinqüenta mil, e duzentas e cinqüenta mil ovelhas, e dois mil jumentos, e cem mil homens.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 22, 'Porque muitos caíram feridos, porque de Deus era a peleja; e habitaram em seu lugar, até ao cativeiro.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 23, 'E os filhos da meia tribo de Manassés habitaram naquela terra; multiplicaram-se desde Basã até Baal-Hermom, e Senir, e o monte de Hermom.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 24, 'E estes foram cabeças de suas casas paternas, a saber: Hefer, Isi, Eliel, Azriel, Jeremias, Hodavias, e Jadiel, homens valentes, homens de nome, e chefes das casas de seus pais.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 25, 'Porém transgrediram contra o Deus de seus pais; e se prostituíram, seguindo os deuses dos povos da terra, os quais Deus destruíra de diante deles.', 2, CURRENT_TIMESTAMP, false),
(13, 5, 26, 'Por isso o Deus de Israel suscitou o espírito de Pul, rei da Assíria, e o espírito de Tiglate-Pilneser, rei da Assíria, que os levaram presos, a saber: os rubenitas e gaditas, e a meia tribo de Manassés; e os trouxeram a Hala, e a Habor, e a Hara, e ao rio de Gozã, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 1, 'Os filhos de Levi foram: Gérson, Coate e Merari,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 2, 'E os filhos de Coate: Anrão, e Izar, e Hebrom, e Uziel.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 3, 'E os filhos de Anrão: Arão, Moisés, e Miriã; e os filhos de Arão: Nadabe, Abiú, Eleazar, e Itamar.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 4, 'E Eleazar gerou a Finéias, e Finéias gerou a Abisua,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 5, 'E Abisua gerou a Buqui, e Buqui gerou a Uzi,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 6, 'E Uzi gerou a Zeraías, e Zeraías gerou a Meraiote.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 7, 'E Meraiote gerou a Amarias, e Amarias gerou a Aitube.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 8, 'E Aitube gerou a Zadoque, e Zadoque gerou a Aimaás,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 9, 'E Aimaás gerou a Azarias, e Azarias gerou a Joanã,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 10, 'E Joanã gerou a Azarias; e este é o que exerceu o sacerdócio na casa que Salomão tinha edificado em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 11, 'E Azarias gerou a Amarias, e Amarias gerou a Aitube,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 12, 'E Aitube gerou a Zadoque, e Zadoque gerou a Salum,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 13, 'E Salum gerou a Hilquias, e Hilquias gerou a Azarias,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 14, 'E Azarias gerou a Seraías, e Seraías gerou a Jeozadaque,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 15, 'E Jeozadaque foi levado cativo quando o Senhor levou presos a Judá e a Jerusalém pela mão de Nabucodonosor.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 16, 'Os filhos de Levi foram, pois, Gérson, Coate, e Merari.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 17, 'E estes são os nomes dos filhos de Gérson: Libni e Simei.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 18, 'E os filhos de Coate: Anrão, Izar, Hebrom, e Uziel.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 19, 'Os filhos de Merari: Mali e Musi; estas são as famílias dos levitas, segundo seus pais.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 20, 'De Gérson: Libni, seu filho; Jaate, seu filho; Zima, seu filho;', 2, CURRENT_TIMESTAMP, false),
(13, 6, 21, 'Joá, seu filho; Ido, seu filho; Zerá, seu filho; Jeatarai, seu filho.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 22, 'Os filhos de Coate foram: Aminadabe, seu filho; Coré, seu filho; Assir, seu filho;', 2, CURRENT_TIMESTAMP, false),
(13, 6, 23, 'Elcana, seu filho; Ebiasafe, seu filho; Assir, seu filho;', 2, CURRENT_TIMESTAMP, false),
(13, 6, 24, 'Taate, seu filho; Uriel, seu filho; Uzias, seu filho; e Saul, seu filho.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 25, 'E os filhos de Elcana: Amasai e Aimote.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 26, 'Quanto a Elcana: os filhos de Elcana foram Zofai, seu filho; e seu filho Naate.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 27, 'Seu filho Eliabe, seu filho Jeroão, seu filho Elcana.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 28, 'E os filhos de Samuel: Joel, seu primogênito, e o segundo Abias.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 29, 'Os filhos de Merari: Mali, seu filho Libni, seu filho Simei, seu filho Uzá.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 30, 'Seu filho Siméia, seu filho Hagias, seu filho Asaías.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 31, 'Estes são, pois, os que Davi constituiu para o ofício do canto na casa do Senhor, depois que a arca teve repouso.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 32, 'E ministravam diante do tabernáculo da tenda da congregação com cantares, até que Salomão edificou a casa do Senhor em Jerusalém; e estiveram, segundo o seu costume, no seu ministério.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 33, 'Estes são, pois, os que ali estavam com seus filhos: dos filhos dos coatitas, Hemã, o cantor, filho de Joel, filho de Samuel,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 34, 'Filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 35, 'Filho de Zufe, filho de Elcana, filho de Maate, filho de Amasai,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 36, 'Filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 37, 'Filho de Taate, filho de Assir, filho de Ebiasafe, filho de Coré,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 38, 'Filho de Isar, filho de Coate, filho de Levi, filho de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 39, 'E seu irmão Asafe estava à sua direita; e era Asafe filho de Berequias, filho de Siméia,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 40, 'Filho de Micael, filho de Baaséias, filho de Malquias,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 41, 'Filho de Etni, filho de Zerá, filho de Adaías,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 42, 'Filho de Etã, filho de Zima, filho de Simei,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 43, 'Filho de Jaate, filho de Gérson, filho de Levi.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 44, 'E seus irmãos, os filhos de Merari, estavam à esquerda; a saber: Etã, filho de Quisi, filho de Abdi, filho de Maluque,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 45, 'Filho de Hasabias, filho de Amazias, filho de Hilquias,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 46, 'Filho de Anzi, filho de Bani, filho de Semer,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 47, 'Filho de Mali, filho de Musi, filho de Merari, filho de Levi.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 48, 'E seus irmãos, os levitas, foram postos para todo o ministério do tabernáculo da casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 49, 'E Arão e seus filhos ofereceram sobre o altar do holocausto e sobre o altar do incenso, por todo o serviço do lugar santíssimo, e para fazer expiação por Israel, conforme tudo quanto Moisés, servo de Deus, tinha ordenado.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 50, 'E estes foram os filhos de Arão: seu filho Eleazar, seu filho Finéias, seu filho Abisua.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 51, 'Seu filho Buqui, seu filho Uzi, seu filho Seraías,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 52, 'Seu filho Meraiote, seu filho Amarias, seu filho Aitube,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 53, 'Seu filho Zadoque, seu filho Aimaás.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 54, 'E estas foram as suas habitações, segundo os seus acampamentos, nos seus termos, a saber: dos filhos de Arão, da família dos coatitas, porque a eles caiu a sorte.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 55, 'Deram-lhes, pois, a Hebrom, na terra de Judá, e os arrabaldes que a rodeiam.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 56, 'Porém o território da cidade e as suas aldeias deram a Calebe, filho de Jefoné.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 57, 'E aos filhos de Arão deram as cidades de refúgio: Hebrom e Libna e os seus arrabaldes, e Jatir e Estemoa e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 58, 'E Hilém, e os seus arrabaldes, Debir e os seus arrabaldes,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 59, 'E Asã e os seus arrabaldes, e Bete-Semes e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 60, 'E da tribo de Benjamim, Geba e os seus arrabaldes, Alemete e os seus arrabaldes, e Anatote e os seus arrabaldes; todas as suas cidades, pelas suas famílias, foram treze.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 61, 'Mas os filhos de Coate, que restaram da sua família, tiveram, por sorte, dez cidades da meia tribo de Manassés.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 62, 'E os filhos de Gérson, segundo as suas famílias, tiveram treze cidades da tribo de Issacar, e da tribo de Aser, e da tribo de Naftali e da tribo de Manassés, em Basã.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 63, 'Os filhos de Merari, segundo as suas famílias, tiveram, por sorte, doze cidades da tribo de Rúben, e da tribo de Gade, e da tribo de Zebulom.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 64, 'Assim os filhos de Israel deram aos levitas estas cidades e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 65, 'E deram-lhes por sorte estas cidades, da tribo dos filhos de Judá, da tribo dos filhos de Simeão, e da tribo dos filhos de Benjamim, às quais deram os seus nomes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 66, 'E quanto ao mais das famílias dos filhos de Coate, se lhes deram, da tribo de Efraim as cidades dos seus termos.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 67, 'Porque lhes deram as cidades de refúgio, Siquém e os seus arrabaldes, nas montanhas de Efraim, como também Gezer e os seus arrabaldes,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 68, 'E Jocmeão e os seus arrabaldes, Bete-Horom e os seus arrabaldes,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 69, 'E Aijalom e os seus arrabaldes, Gate-Rimom e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 70, 'E da meia tribo de Manassés, Aner e os seus arrabaldes, e Bileã e os seus arrabaldes; estas cidades tiveram os que ficaram da família dos filhos de Coate.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 71, 'Os filhos de Gérson tiveram, da família da meia tribo de Manassés, Golã, em Basã, e os seus arrabaldes, e Astarote e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 72, 'E da tribo de Issacar, Quedes e os seus arrabaldes, e Daberate e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 73, 'E Ramote e os seus arrabaldes, e Aném e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 74, 'E da tribo de Aser, Masal e os seus arrabaldes, e Abdom e os seus arrabaldes,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 75, 'E Hucoque e os seus arrabaldes, e Reobe e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 76, 'E da tribo de Naftali, Quedes, em Galiléia, e os seus arrabaldes, Hamom e os seus arrabaldes e Quiriataim e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 77, 'Os que ficaram dos filhos de Merari tiveram, da tribo de Zebulom, a Rimom e os seus arrabaldes, a Tabor e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 78, 'E dalém do Jordão, na altura de Jericó, ao oriente do Jordão, da tribo de Rúben, a Bezer, no deserto, e os seus arrabaldes, e a Jaza e os seus arrabaldes,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 79, 'E a Quedemote e os seus arrabaldes, e a Mefaate e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 6, 80, 'E da tribo de Gade, a Ramote, em Gileade, e os seus arrabaldes, e Maanaim e os seus arrabaldes,', 2, CURRENT_TIMESTAMP, false),
(13, 6, 81, 'E a Hesbom e os seus arrabaldes, e a Jazer e os seus arrabaldes.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 1, 'E quanto aos filhos de Issacar, foram: Tola, Pua, Jasube e Sinrom, quatro.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 2, 'E os filhos de Tola foram: Uzi, Refaías, Jeriel, Jamai, Ibsão e Semuel, chefes das casas de seus pais, descendentes de Tola, homens valentes nas suas gerações; o seu número, nos dias de Davi, foi de vinte e dois mil e seiscentos.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 3, 'E o filho de Uzi: Izraías; e os filhos de Izraías foram: Mical, Obadias, Joel e Issias; todos estes cinco chefes.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 4, 'E houve com eles nas suas gerações, segundo as suas casas paternas, em tropas de guerra, trinta e seis mil; porque tiveram muitas mulheres e filhos.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 5, 'E seus irmãos, em todas as famílias de Issacar, homens valentes, foram oitenta e sete mil, todos contados pelas suas genealogias.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 6, 'Os filhos de Benjamim foram: Belá, e Bequer, e Jediael, três.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 7, 'E os filhos de Belá: Esbom, e Uzi, e Uziel, e Jerimote, e Iri, cinco chefes da casa dos pais, homens valentes que foram contados pelas suas genealogias, vinte e dois mil e trinta e quatro.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 8, 'E os filhos de Bequer: Zemira, Joás, Eliezer, Elioenai, Onri, Jerimote, Abias, Anatote, e Alemete; todos estes foram filhos de Bequer.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 9, 'E foram contados pelas suas genealogias, segundo as suas gerações, e chefes das casas de seus pais, homens valentes, vinte mil e duzentos.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 10, 'E foi o filho de Jediael, Bilã; e os filhos de Bilã foram Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis e Aisaar.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 11, 'Todos estes filhos de Jediael foram chefes das famílias dos pais, homens valentes, dezessete mil e duzentos, que saíam no exército à peleja.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 12, 'E Supim, e Hupim, filhos de Ir, e Husim, dos filhos de Aer.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 13, 'Os filhos de Naftali: Jaziel, e Guni, e Jezer, e Salum, filhos de Bila.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 14, 'Os filhos de Manassés: Asriel, que a mulher de Gileade concebeu (porém a sua concubina, a síria, concebeu a Maquir, pai de Gileade;', 2, CURRENT_TIMESTAMP, false),
(13, 7, 15, 'E Maquir tomou a irmã de Hupim e Supim por mulher, e era o seu nome Maaca), e foi o nome do segundo Zelofeade; e Zelofeade teve filhas.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 16, 'E Maaca, mulher de Maquir, deu à luz um filho, e chamou-o Perez; e o nome de seu irmão foi Seres; e foram seus filhos Ulão e Raquém.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 17, 'E o filho de Ulão, Bedã; estes foram os filhos de Gileade, filho de Maquir, filho de Manassés.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 18, 'E quanto à sua irmã Hamolequete, teve a Is-Hode, a Abiezer, e a Maalá.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 19, 'E foram os filhos de Semida: Aiã, Siquém, Liqui, e Anião.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 20, 'E os filhos de Efraim: Sutela, e seu filho Berede, e seu filho Taate, e seu filho Elada e seu filho Taate.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 21, 'E seu filho Zabade, e seu filho Sutela, e Ezer, e Elade; e os homens de Gate, naturais da terra, os mataram, porque desceram para tomar os seus gados.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 22, 'Por isso Efraim, seu pai, por muitos dias os chorou; e vieram seus irmãos para o consolar.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 23, 'Depois coabitou com sua mulher, e ela concebeu, e teve um filho; e chamou-o Berias; porque ia mal na sua casa.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 24, 'E sua filha foi Seerá, que edificou a Bete-Horom, a baixa e a alta, como também a Uzém-Seerá.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 25, 'E foi seu filho Refa, e Resefe, de quem foi filho Tela, de quem foi filho Taã,', 2, CURRENT_TIMESTAMP, false),
(13, 7, 26, 'De quem foi filho Ladã, de quem foi filho Amiúde, de quem foi filho Elisama,', 2, CURRENT_TIMESTAMP, false),
(13, 7, 27, 'De quem foi filho Num, de quem foi filho Josué.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 28, 'E foi a sua possessão e habitação Betel e os lugares da sua jurisdição; e ao oriente Naarã, e ao ocidente Gezer e os lugares da sua jurisdição, e Siquém e os lugares da sua jurisdição, até Gaza e os lugares da sua jurisdição;', 2, CURRENT_TIMESTAMP, false),
(13, 7, 29, 'E do lado dos filhos de Manassés, Bete-Seã e os lugares da sua jurisdição, Taanaque e os lugares da sua jurisdição, Megido e os lugares da sua jurisdição, Dor e os lugares da sua jurisdição; nestas habitaram os filhos de José, filho de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 30, 'Os filhos de Aser foram: Imná, Isvá, Isvi, Berias, e Sera, irmã deles.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 31, 'E os filhos de Berias: Héber e Malquiel; este foi o pai de Birzavite.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 32, 'E Héber gerou a Jaflete, e a Somer, e a Hotão, e a Suá, irmã deles.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 33, 'E foram os filhos de Jaflete: Pasaque, e Bimal e Asvate; estes foram os filhos de Jaflete.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 34, 'E os filhos de Semer: Ai, Roga, Jeubá, e Arã.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 35, 'E os filhos de seu irmão Helém: Zofa, e Imna, e Seles, e Amal.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 36, 'Os filhos de Zofa: Suá, e Harnefer, e Sual, e Beri, e Inra,', 2, CURRENT_TIMESTAMP, false),
(13, 7, 37, 'Bezer, Hode, Samá, Silsa, Itrã, e Beera.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 38, 'E os filhos de Jeter: Jefoné, Pispa e Ara.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 39, 'E os filhos de Ula: Ará e Haniel e Rizia.', 2, CURRENT_TIMESTAMP, false),
(13, 7, 40, 'Todos estes foram filhos de Aser, chefes das casas paternas, homens escolhidos e valentes, chefes dos príncipes, e contados nas suas genealogias, no exército para a guerra; foi seu número de vinte e seis mil homens.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 1, 'E Benjamim gerou a Belá, seu primogênito, a Asbel o segundo, e a Aará o terceiro,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 2, 'A Noá o quarto, e a Rafa o quinto.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 3, 'E Belá teve estes filhos: Adar, Gera, Abiúde,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 4, 'Abisua, Naamã, Aoá,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 5, 'Gera, Sefufá e Hurão.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 6, 'E estes foram os filhos de Eúde; que foram chefes dos pais dos moradores de Geba, e os levaram cativos a Manaate;', 2, CURRENT_TIMESTAMP, false),
(13, 8, 7, 'E Naamã, e Aías e Gera; este os transportou, e gerou a Uzá e a Aiúde.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 8, 'E Saaraim (depois de os enviar), na terra de Moabe, gerou filhos de Husim e Baara, suas mulheres.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 9, 'E de Hodes, sua mulher, gerou a Jobabe, a Zíbia, a Mesa, a Malcã,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 10, 'A Jeuz, a Saquias e a Mirma; estes foram seus filhos, chefes dos pais.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 11, 'E de Husim gerou a Abitube e a Elpaal.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 12, 'E foram os filhos de Elpaal: Éber, Misã e Semede; este edificou a Ono e a Lode e os lugares da sua jurisdição.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 13, 'E Berias e Sema foram cabeças dos pais dos moradores de Aijalom; estes afugentaram os moradores de Gate.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 14, 'E Aiô, Sasaque, Jerimote,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 15, 'Zebadias, Arade, Eder,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 16, 'Micael, Ispa e Joa foram filhos de Berias.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 17, 'Zebadias, Mesulão, Hizque, Héber,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 18, 'Ismerai, Izlias e Jobabe, filhos de Elpaal.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 19, 'Jaquim, Zicri, Zabdi,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 20, 'Elienai, Ziletai, Eliel,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 21, 'Adaías, Beraías e Sinrate, filhos de Simei.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 22, 'E Ispã, Éber, Eliel,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 23, 'Abdom, Zicri, Hanã,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 24, 'Hananias, Elão, Antotias,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 25, 'E Ifdéias, e Penuel, filhos de Sasaque;', 2, CURRENT_TIMESTAMP, false),
(13, 8, 26, 'E Sanserai, e Searias, e Atalias,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 27, 'E Jaaresias, e Elias e Zicri, filhos de Jeroão.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 28, 'Estes foram cabeças dos pais, segundo as suas gerações, chefes, e habitaram em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 29, 'E em Gibeão habitou o pai de Gibeão; e era o nome de sua mulher Maaca;', 2, CURRENT_TIMESTAMP, false),
(13, 8, 30, 'E seu filho primogênito, Abdom; depois Zur, e Quis, Baal, e Nadabe,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 31, 'E Gedor, Aiô, e Zequer,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 32, 'E Miclote gerou a Siméia; e também estes, defronte de seus irmãos, habitaram em Jerusalém com eles.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 33, 'E Ner gerou a Quis, e Quis gerou a Saul; e Saul gerou a Jônatas, a Malquisua, a Abinadabe, e a Esbaal.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 34, 'E o filho de Jônatas foi Meribe-Baal; e Meribe-Baal gerou a Mica.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 35, 'E os filhos de Mica foram: Pitom, Meleque, Tareá, e Acaz.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 36, 'E Acaz gerou a Jeoada; e Jeoada gerou a Alemete, e a Azmavete, e a Zinri; e Zinri gerou a Moza,', 2, CURRENT_TIMESTAMP, false),
(13, 8, 37, 'E Moza gerou a Bineá, cujo filho foi Rafa, de quem foi filho Eleasá, cujo filho foi Azel.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 38, 'E teve Azel seis filhos, e estes foram os seus nomes: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã; todos estes foram filhos de Azel.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 39, 'E os filhos de Ezeque, seu irmão: Ulão, seu primogênito, Jeús o segundo e Elifelete o terceiro.', 2, CURRENT_TIMESTAMP, false),
(13, 8, 40, 'E foram os filhos de Ulão homens heróis, valentes, e flecheiros destros; e tiveram muitos filhos, e filhos de filhos, cento e cinqüenta; todos estes foram dos filhos de Benjamim.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 1, 'E todo o Israel foi contado por genealogias, que estão escritas no livro dos reis de Israel; e os de Judá foram transportados a Babilônia, por causa da sua transgressão.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 2, 'E os primeiros habitantes, que moravam na sua possessão e nas suas cidades, foram os israelitas, os sacerdotes, os levitas, e os netineus.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 3, 'Porém alguns dos filhos de Judá, e dos filhos de Benjamim, e dos filhos de Efraim e Manassés, habitaram em Jerusalém:', 2, CURRENT_TIMESTAMP, false),
(13, 9, 4, 'Utai, filho de Amiúde, filho de Onri, filho de Inri, filho de Bani, dos filhos de Perez, filho de Judá;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 5, 'E dos silonitas: Asaías o primogênito, e seus filhos;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 6, 'E dos filhos de Zerá: Jeuel, e seus irmãos, seiscentos e noventa;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 7, 'E dos filhos de Benjamim: Salu, filho de Mesulão, filho de Hodavias, filho de Hassenua,', 2, CURRENT_TIMESTAMP, false),
(13, 9, 8, 'E Ibnéias, filho de Jeroão, e Elá, filho de Uzi, filho de Micri, e Mesulão, filho de Sefatias, filho de Reuel, filho de Ibnijas;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 9, 'E seus irmãos, segundo as suas gerações, novecentos e cinqüenta e seis; todos estes homens foram chefes dos pais nas casas de seus pais.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 10, 'E dos sacerdotes: Jedaías, e Jeoiaribe, e Jaquim,', 2, CURRENT_TIMESTAMP, false),
(13, 9, 11, 'E Azarias, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, maioral da casa de Deus;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 12, 'Adaías, filho de Jeroão, filho de Pasur, filho de Malquias, e Masai, filho de Adiel, filho de Jazera, filho de Mesulão, filho de Mesilemite, filho de Imer;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 13, 'Como também seus irmãos, cabeças nas casas de seus pais, mil, setecentos e sessenta, homens valentes para a obra do ministério da casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 14, 'E dos levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, dos filhos de Merari;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 15, 'E Baquebacar, Heres e Galal; e Matanias, filho de Mica, filho de Zicri, filho de Asafe;', 2, CURRENT_TIMESTAMP, false),
(13, 9, 16, 'E Obadias, filho de Semaías, filho de Galal, filho de Jedutum; e Berequias, filho de Asa, filho de Elcana, morador das aldeias dos netofatitas.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 17, 'E foram porteiros: Salum, Acube, Talmom, Aimã, e seus irmãos, cujo chefe era Salum.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 18, 'E até aquele tempo estavam de guarda à porta do rei, do lado do oriente; estes foram os porteiros dos arraiais dos filhos de Levi.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 19, 'E Salum, filho de Coré, filho de Ebiasafe, filho de Corá, e seus irmãos da casa de seu pai, os coraítas, tinham cargo da obra do ministério, e eram guardas das portas do tabernáculo, como seus pais foram responsáveis pelo arraial do Senhor, e guardas da entrada.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 20, 'Finéias, filho de Eleazar, antes era líder entre eles; e o Senhor era com ele.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 21, 'E Zacarias, filho de Meselemias, porteiro da entrada da tenda da congregação.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 22, 'Todos estes, escolhidos para serem guardas das portas, foram duzentos e doze; e foram estes, segundo as suas aldeias, postos em suas genealogias; e Davi e Samuel, o vidente, os constituíram nos seus respectivos cargos.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 23, 'Estavam, pois, eles, e seus filhos, às portas da casa do Senhor, na casa da tenda, junto aos guardas,', 2, CURRENT_TIMESTAMP, false),
(13, 9, 24, 'Os porteiros estavam aos quatro lados; ao oriente, ao ocidente, ao norte, e ao sul.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 25, 'E seus irmãos, que estavam nas suas aldeias, deviam, de tempo em tempo, vir por sete dias para servirem com eles.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 26, 'Porque havia naquele ofício quatro porteiros principais que eram levitas, e tinham o encargo das câmaras e dos tesouros da casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 27, 'E de noite ficavam em redor da casa de Deus, cuja guarda lhes tinha sido confiada, e tinham o encargo de abri-la cada manhã.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 28, 'E alguns deles estavam encarregados dos utensílios do ministério, porque por conta os traziam e por conta os tiravam.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 29, 'Porque deles havia alguns que tinham o encargo dos objetos e de todos os utensílios do santuário; como também da flor de farinha, do vinho, do azeite, do incenso, e das especiarias.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 30, 'E alguns dos filhos dos sacerdotes eram os obreiros da confecção das especiarias.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 31, 'E Matitias, dentre os levitas, o primogênito de Salum, o coraíta, tinha o encargo da obra que se fazia em sertãs.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 32, 'E alguns dos seus irmãos, dos filhos dos coatitas, tinham o encargo de preparar os pães da proposição para todos os sábados.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 33, 'Destes foram também os cantores, chefes dos pais entre os levitas, habitando nas câmaras, isentos de serviços; porque de dia e de noite estava a seu cargo ocuparem-se naquela obra.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 34, 'Estes foram cabeças dos pais entre os levitas, chefes em suas gerações; estes habitaram em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 35, 'Porém em Gibeão habitaram Jeiel, pai de Gibeão (e era o nome de sua mulher Maaca).', 2, CURRENT_TIMESTAMP, false),
(13, 9, 36, 'E seu filho primogênito Abdom; depois Zur, Quis, Baal, Ner e Nadabe,', 2, CURRENT_TIMESTAMP, false),
(13, 9, 37, 'E Gedor, Aiô, Zacarias e Miclote.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 38, 'Miclote gerou a Simeão; e também estes habitaram em Jerusalém, defronte de seus irmãos, com eles.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 39, 'E Ner gerou a Quis; e Quis gerou a Saul, Saul gerou a Jônatas, a Malquisua, a Abinadabe e a Esbaal.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 40, 'E o filho de Jônatas foi Meribe-Baal, e Meribe-Baal gerou a Mica.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 41, 'E os filhos de Mica foram: Pitom, Meleque e Taréia.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 42, 'E Acaz gerou a Jaerá, e Jaerá gerou a Alemete, a Azmavete e a Zinri; e Zinri gerou a Moza.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 43, 'E Moza gerou a Bineá, cujo filho foi Refaías, de quem foi filho Eleasá, cujo filho foi Azel.', 2, CURRENT_TIMESTAMP, false),
(13, 9, 44, 'E teve Azel seis filhos, e estes foram os seus nomes: Azricão, Bocru, Ismael, Searias, Obadias e Hanã; estes foram os filhos de Azel.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 1, 'E os filisteus pelejaram com Israel; e os homens de Israel fugiram de diante dos filisteus, e caíram mortos nas montanhas de Gilboa.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 2, 'E os filisteus perseguiram a Saul e aos seus filhos e mataram a Jônatas, a Abinadabe e a Malquisua, filhos de Saul.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 3, 'E a peleja se agravou contra Saul, e os flecheiros o alcançaram; e temeu muito aos flecheiros.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 4, 'Então disse Saul ao seu escudeiro: Arranca a tua espada, e atravessa-me com ela; para que porventura não venham estes incircuncisos e escarneçam de mim. Porém o seu escudeiro não quis, porque temia muito; então tomou Saul a espada, e se lançou sobre ela.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 5, 'Vendo, pois, o seu escudeiro que Saul estava morto, também ele se lançou sobre a espada e morreu.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 6, 'Assim morreram Saul e seus três filhos; e toda a sua casa morreu juntamente.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 7, 'E, vendo todos os homens de Israel, que estavam no vale, que haviam fugido, e que Saul e seus filhos eram mortos, deixaram as suas cidades, e fugiram; então vieram os filisteus, e habitaram nelas.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 8, 'E sucedeu que, no dia seguinte, vindo os filisteus a despojar os mortos, acharam a Saul e a seus filhos estirados nas montanhas de Gilboa.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 9, 'E o despojaram, e tomaram a sua cabeça e as suas armas, e as enviaram pela terra dos filisteus em redor, para o anunciarem a seus ídolos e ao povo.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 10, 'E puseram as suas armas na casa do seu deus, e a sua cabeça afixaram na casa de Dagom.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 11, 'Ouvindo, pois, toda a Jabes de Gileade tudo quanto os filisteus fizeram a Saul,', 2, CURRENT_TIMESTAMP, false),
(13, 10, 12, 'Então todos os homens valorosos se levantaram, e tomaram o corpo de Saul, e os corpos de seus filhos, e os trouxeram a Jabes; e sepultaram os seus ossos debaixo de um carvalho em Jabes, e jejuaram sete dias.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 13, 'Assim morreu Saul por causa da transgressão que cometeu contra o Senhor, por causa da palavra do Senhor, a qual não havia guardado; e também porque buscou a adivinhadora para a consultar.', 2, CURRENT_TIMESTAMP, false),
(13, 10, 14, 'E não buscou ao Senhor, que por isso o matou, e transferiu o reino a Davi, filho de Jessé.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 1, 'Então todo o Israel se ajuntou a Davi em Hebrom, dizendo: Eis que somos teus ossos e tua carne.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 2, 'E também outrora, sendo Saul ainda rei, eras tu o que fazias sair e entrar a Israel; também o Senhor teu Deus te disse: Tu apascentarás o meu povo Israel, e tu serás chefe sobre o meu povo Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 3, 'Também vieram todos os anciãos de Israel ao rei, a Hebrom, e Davi fez com eles aliança em Hebrom, perante o Senhor; e ungiram a Davi rei sobre Israel, conforme a palavra do Senhor pelo ministério de Samuel.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 4, 'E partiu Davi e todo o Israel para Jerusalém, que é Jebus; porque ali estavam os jebuseus, habitantes da terra.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 5, 'E disseram os habitantes de Jebus a Davi: Tu não entrarás aqui. Porém Davi ganhou a fortaleza de Sião, que é a cidade de Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 6, 'Porque disse Davi: Qualquer que primeiro ferir os jebuseus será chefe e capitão. Então Joabe, filho de Zeruia, subiu primeiro a ela; pelo que foi feito chefe.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 7, 'E Davi habitou na fortaleza; por isso foi chamada a cidade de Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 8, 'E edificou a cidade ao redor, desde Milo até ao circuito; e Joabe renovou o restante da cidade.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 9, 'E Davi tornava-se cada vez mais forte; porque o Senhor dos Exércitos era com ele.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 10, 'E estes foram os chefes dos poderosos que Davi tinha, e que o apoiaram fortemente no seu reino, com todo o Israel, para o fazerem rei, conforme a palavra do Senhor, no tocante a Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 11, 'E este é o número dos poderosos que Davi tinha: Jasobeão, hacmonita, chefe dos capitães, o qual, brandindo a sua lança contra trezentos, de uma vez os matou.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 12, 'E, depois dele Eleazar, filho de Dodó, o aoíta; ele estava entre os três poderosos.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 13, 'Este esteve com Davi em Pas-Damim, quando os filisteus ali se ajuntaram à peleja, onde havia um pedaço de campo cheio de cevada; e o povo fugiu de diante dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 14, 'E puseram-se no meio daquele campo, e o defenderam, e feriram os filisteus; e o Senhor efetuou um grande livramento.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 15, 'E três dos trinta capitães desceram à penha, a ter com Davi, na caverna de Adulão; e o exército dos filisteus estava acampado no vale de Refaim.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 16, 'E Davi estava então no lugar forte; e o alojamento dos filisteus estava então em Belém.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 17, 'E desejou Davi, e disse: Quem me dera beber da água do poço de Belém, que está junto à porta!', 2, CURRENT_TIMESTAMP, false),
(13, 11, 18, 'Então aqueles três romperam pelo acampamento dos filisteus, e tiraram água do poço de Belém, que estava junto à porta, e tomaram dela e a trouxeram a Davi; porém Davi não a quis beber, mas a derramou ao Senhor,', 2, CURRENT_TIMESTAMP, false),
(13, 11, 19, 'E disse: Nunca meu Deus permita que faça tal! Beberia eu o sangue destes homens com as suas vidas? Pois com perigo das suas vidas a trouxeram. E ele não a quis beber. Isto fizeram aqueles três homens.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 20, 'E também Abisai, irmão de Joabe, era chefe de três, o qual, brandindo a sua lança contra trezentos, os feriu; e teve nome entre os três.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 21, 'Ele foi o mais ilustre dos três, pelo que foi capitão deles; porém não igualou aos primeiros três.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 22, 'Também Benaia, filho de Joiada, filho de um homem poderoso de Cabzeel, grande em obras; ele feriu a dois heróis de Moabe; e também desceu, e feriu um leão dentro de uma cova, no tempo da neve.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 23, 'Também feriu ele a um homem egípcio, homem de grande altura, de cinco côvados; e trazia o egípcio uma lança na mão, como o órgão do tecelão; mas Benaia desceu contra ele com uma vara, e arrancou a lança da mão do egípcio, e com ela o matou.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 24, 'Estas coisas fez Benaia, filho de Joiada; pelo que teve nome entre aqueles três poderosos.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 25, 'Eis que dos trinta foi ele o mais ilustre; contudo não chegou aos primeiros três; e Davi o pôs sobre os da sua guarda.', 2, CURRENT_TIMESTAMP, false),
(13, 11, 26, 'E foram os poderosos dos exércitos: Asael, irmão de Joabe, El-Hanã, filho de Dodó, de Belém;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 27, 'Samote, o harorita; Helez, o pelonita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 28, 'Ira, filho de Iques, o tecoíta; Abiezer, o anatotita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 29, 'Sibecai, o husatita; Ilai, o aoíta;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 30, 'Maarai, o netofatita; Helede, filho de Baaná, o netofatita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 31, 'Itai, filho de Ribai, de Gileade, dos filhos de Benjamim; Benaia, o piratonita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 32, 'Hurai, do ribeiro de Gaás; Abiel, o arbatita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 33, 'Azmavete, o baarumita; Eliabe, o saalbonita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 34, 'Dos filhos de Hasém, o gizonita: Jônatas, filho de Sage, o hararita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 35, 'Aião, filho de Sacar, o hararita; Elifal, filho de Ur;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 36, 'Hefer, o mequeratita; Aías, o pelonita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 37, 'Hezro, o carmelita; Naarai, filho de Ezbai;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 38, 'Joel, irmão de Natã; Mibar, filho de Hagri;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 39, 'Zeleque, o amonita; Naarai, o beerotita, escudeiro de Joabe, filho de Zeruia;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 40, 'Ira, o itrita; Garebe, o itrita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 41, 'Urias, o heteu; Zabade, filho de Alai;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 42, 'Adina, filho de Siza, o rubenita, capitão dos rubenitas, e com ele trinta;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 43, 'Hanã, filho de Maaca; e Josafá, o mitatita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 44, 'Uzias, o asteratita; Sama e Jeiel, filhos de Hotão, o aroerita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 45, 'Jediael, filho de Sinri; e Joa, seu irmão, o tizita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 46, 'Eliel, o maavita; e Jeribai e Josavias, filhos de Elnaão; e Itma, o moabita;', 2, CURRENT_TIMESTAMP, false),
(13, 11, 47, 'Eliel, Obede, e Jaasiel, o mesobaíta.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 1, 'Estes, porém, são os que vieram a Davi, a Ziclague, estando ele ainda escondido, por causa de Saul, filho de Quis; e eram dos valentes que o ajudaram na guerra.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 2, 'Estavam armados de arco, e usavam tanto da mão direita como da esquerda em atirar pedras e em atirar flechas com o arco; eram dos irmãos de Saul, benjamitas.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 3, 'Aiezer, o chefe, e Joás, filho de Semaa, o gibeatita, e Jeziel e Pelete, filhos de Azmavete; e Beraca, e Jeú, o anatotita,', 2, CURRENT_TIMESTAMP, false),
(13, 12, 4, 'E Ismaías, o gibeonita, valente entre os trinta, líder deles; e Jeremias, e Jaaziel, e Joanã, e Jozabade, o gederatita,', 2, CURRENT_TIMESTAMP, false),
(13, 12, 5, 'Eluzai, e Jerimote, e Bealias, e Samarias, e Sefatias, o harufita,', 2, CURRENT_TIMESTAMP, false),
(13, 12, 6, 'Elcana, Issias, Azarel, Joezer, e Jasobeão, os coraítas,', 2, CURRENT_TIMESTAMP, false),
(13, 12, 7, 'E Joela, e Zabadias, filhos de Jeroão de Gedor.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 8, 'E dos gaditas se desertaram para Davi, ao lugar forte no deserto, valentes, homens de guerra para pelejar, armados com escudo e lança; e seus rostos eram como rostos de leões, e ligeiros como corças sobre os montes:', 2, CURRENT_TIMESTAMP, false),
(13, 12, 9, 'Ezer, o primeiro; Obadias, o segundo; Eliabe, o terceiro;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 10, 'Mismana, o quarto; Jeremias, o quinto;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 11, 'Atai, o sexto; Eliel, o sétimo;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 12, 'Joanã, o oitavo; Elzabade, o nono;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 13, 'Jeremias, o décimo; Macbanai, o undécimo;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 14, 'Estes, dos filhos de Gade, foram os capitães do exército; o menor tinha o encargo de cem homens e o maior de mil.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 15, 'Estes são os que passaram o Jordão no primeiro mês, quando ele transbordava por todas as suas ribanceiras, e fizeram fugir a todos os dos vales ao oriente e ao ocidente.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 16, 'Também alguns dos filhos de Benjamim e de Judá vieram a Davi, ao lugar forte.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 17, 'E Davi lhes saiu ao encontro, e lhes falou, dizendo: Se vós vindes a mim pacificamente e para me ajudar, o meu coração se unirá convosco; porém, se é para me entregar aos meus inimigos, sem que haja deslealdade nas minhas mãos, o Deus de nossos pais o veja e o repreenda.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 18, 'Então veio o espírito sobre Amasai, chefe de trinta, e disse: Nós somos teus, ó Davi, e contigo estamos, ó filho de Jessé! Paz, paz contigo, e paz com quem te ajuda, pois que teu Deus te ajuda. E Davi os recebeu, e os fez capitães das tropas.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 19, 'Também de Manassés alguns passaram para Davi, quando veio com os filisteus para a batalha contra Saul; todavia Davi não os ajudou, porque os príncipes dos filisteus, tendo feito conselho, o despediram, dizendo: À custa de nossas cabeças passará a Saul, seu senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 20, 'Voltando ele, pois, a Ziclague, passaram-se para ele, de Manassés, Adna, Jozabade, Jediael, Micael, Jozabade, Eliú, e Ziletai, capitães de milhares dos de Manassés.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 21, 'E estes ajudaram a Davi contra aquela tropa, porque todos eles eram heróis poderosos, e foram capitães no exército.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 22, 'Porque naquele tempo, dia após dia, vinham a Davi para o ajudar, até que se fez um grande exército, como o exército de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 23, 'Ora este é o número dos chefes armados para a peleja, que vieram a Davi em Hebrom, para transferir a ele o reino de Saul, conforme a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 24, 'Dos filhos de Judá, que traziam escudo e lança, seis mil e oitocentos, armados para a peleja;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 25, 'Dos filhos de Simeão, homens poderosos para pelejar, sete mil e cem;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 26, 'Dos filhos de Levi, quatro mil e seiscentos.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 27, 'Joiada, que era o líder dos de Arão, e com ele três mil e setecentos.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 28, 'E Zadoque, sendo ainda jovem, homem poderoso, com vinte e dois capitães da família de seu pai;', 2, CURRENT_TIMESTAMP, false),
(13, 12, 29, 'E dos filhos de Benjamim, irmãos de Saul, três mil; porque até então havia ainda muitos deles que eram pela casa de Saul.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 30, 'E dos filhos de Efraim, vinte mil e oitocentos homens poderosos, homens de nome nas casas de seus pais.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 31, 'E da meia tribo de Manassés, dezoito mil, que foram apontados pelos seus nomes para virem fazer rei a Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 32, 'E dos filhos de Issacar, duzentos de seus chefes, destros na ciência dos tempos, para saberem o que Israel devia fazer, e todos os seus irmãos seguiam suas ordens.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 33, 'De Zebulom, dos que podiam sair no exército, cinqüenta mil ordenados para a peleja com todas as armas de guerra; como também destros para ordenarem uma batalha, e não eram de coração dobre.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 34, 'E de Naftali, mil capitães, e com eles trinta e sete mil com escudo e lança.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 35, 'E dos danitas, ordenados para a peleja, vinte e oito mil e seiscentos.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 36, 'E de Aser, dos que podiam sair no exército, para ordenarem a batalha, quarenta mil.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 37, 'E do outro lado do Jordão, dos rubenitas e gaditas, e da meia tribo de Manassés, com toda a sorte de instrumentos de guerra para pelejar, cento e vinte mil.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 38, 'Todos estes homens de guerra, postos em ordem de batalha, vieram a Hebrom, com corações decididos, para constituírem a Davi rei sobre todo o Israel; e também todo o restante de Israel tinha o mesmo coração para constituir a Davi rei.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 39, 'E estiveram ali com Davi três dias, comendo e bebendo; porque seus irmãos lhes tinham preparado as provisões.', 2, CURRENT_TIMESTAMP, false),
(13, 12, 40, 'E também seus vizinhos de mais perto, até Issacar, e Zebulom, e Naftali, trouxeram, sobre jumentos, e sobre camelos, e sobre mulos, e sobre bois, pão, provisões de farinha, pastas de figos e cachos de passas, e vinho, e azeite, e bois, gado miúdo em abundância; porque havia alegria em Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 1, 'E Davi tomou conselho com os capitães dos milhares, e das centenas, e com todos os líderes.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 2, 'E disse Davi a toda a congregação de Israel: Se bem vos parece, e se isto vem do Senhor nosso Deus, enviemos depressa mensageiros a todos os nossos outros irmãos em todas as terras de Israel, e aos sacerdotes, e aos levitas nas suas cidades e nos seus arrabaldes, para que se reúnam conosco;', 2, CURRENT_TIMESTAMP, false),
(13, 13, 3, 'E tornemos a trazer para nós a arca do nosso Deus; porque não a buscamos nos dias de Saul.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 4, 'Então disse toda a congregação que se fizesse assim; porque este negócio pareceu reto aos olhos de todo o povo.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 5, 'Convocou, pois, Davi a todo o Israel desde Sior do Egito até chegar a Hamate; para trazer a arca de Deus de Quiriate-Jearim.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 6, 'E então Davi com todo o Israel subiu a Baalá de Quiriate-Jearim, que está em Judá, para fazer subir dali a arca de Deus, o Senhor que habita entre os querubins, sobre a qual é invocado o seu nome.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 7, 'E levaram a arca de Deus, da casa de Abinadabe, sobre um carro novo; e Uzá e Aiô guiavam o carro.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 8, 'E Davi e todo o Israel, alegraram-se perante Deus com todas as suas forças; com cânticos, e com harpas, e com saltérios, e com tamborins, e com címbalos, e com trombetas.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 9, 'E, chegando à eira de Quidom, estendeu Uzá a sua mão, para segurar a arca, porque os bois tropeçavam.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 10, 'Então se acendeu a ira do Senhor contra Uzá, e o feriu, por ter estendido a sua mão à arca; e morreu ali perante Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 11, 'E Davi se encheu de tristeza porque o Senhor havia aberto brecha em Uzá; pelo que chamou aquele lugar Perez-Uzá, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 12, 'E aquele dia temeu Davi a Deus, dizendo: Como trarei a mim a arca de Deus?', 2, CURRENT_TIMESTAMP, false),
(13, 13, 13, 'Por isso Davi não trouxe a arca a si, à cidade de Davi; porém a fez levar à casa de Obede-Edom, o giteu.', 2, CURRENT_TIMESTAMP, false),
(13, 13, 14, 'Assim ficou a arca de Deus com a família de Obede-Edom, três meses em sua casa; e o Senhor abençoou a casa de Obede-Edom, e tudo quanto tinha.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 1, 'Então Hirão, rei de Tiro, mandou mensageiros a Davi, e madeira de cedro, e pedreiros, e carpinteiros, para lhe edificarem uma casa.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 2, 'E entendeu Davi que o Senhor o tinha confirmado rei sobre Israel; porque o seu reino tinha sido muito exaltado por amor do seu povo Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 3, 'E Davi tomou ainda mais mulheres em Jerusalém; e gerou Davi ainda mais filhos e filhas.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 4, 'E estes são os nomes dos filhos que teve em Jerusalém: Samua, Sobabe, Natã, Salomão,', 2, CURRENT_TIMESTAMP, false),
(13, 14, 5, 'E Ibar, Elisua, Elpelete,', 2, CURRENT_TIMESTAMP, false),
(13, 14, 6, 'E Nogá, Nefegue, Jafia,', 2, CURRENT_TIMESTAMP, false),
(13, 14, 7, 'E Elisama, Eliada, e Elifelete.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 8, 'Ouvindo, pois, os filisteus que Davi havia sido ungido rei sobre todo o Israel, todos os filisteus subiram em busca de Davi; o que ouvindo Davi, logo saiu contra eles.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 9, 'E vindo os filisteus, se estenderam pelo vale de Refaim.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 10, 'Então consultou Davi a Deus, dizendo: Subirei contra os filisteus, e nas minhas mãos os entregarás? E o Senhor lhe disse: Sobe, porque os entregarei nas tuas mãos.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 11, 'E, subindo a Baal-Perazim, Davi ali os feriu; e disse Davi: Por minha mão Deus derrotou a meus inimigos, como se rompem as águas. Pelo que chamaram aquele lugar, Baal-Perazim.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 12, 'E deixaram ali seus deuses; e ordenou Davi que se queimassem a fogo;', 2, CURRENT_TIMESTAMP, false),
(13, 14, 13, 'Porém os filisteus tornaram, e se estenderam pelo vale.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 14, 'E tornou Davi a consultar a Deus; e disse-lhe Deus: Não subirás atrás deles; mas rodeia-os por detrás, e vem a eles por defronte das amoreiras;', 2, CURRENT_TIMESTAMP, false),
(13, 14, 15, 'E há de ser que, ouvindo tu um ruído de marcha pelas copas das amoreiras, então sairás à peleja; porque Deus terá saído diante de ti, para ferir o exército dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 16, 'E fez Davi como Deus lhe ordenara; e feriram o exército dos filisteus desde Gibeom até Gezer.', 2, CURRENT_TIMESTAMP, false),
(13, 14, 17, 'Assim se espalhou o nome de Davi por todas aquelas terras; e o Senhor pôs o temor dele sobre todas aquelas nações.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 1, 'Davi também fez casa para si na cidade de Davi; e preparou um lugar para a arca de Deus, e armou-lhe uma tenda.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 2, 'Então disse Davi: Ninguém pode levar a arca de Deus, senão os levitas; porque o Senhor os escolheu, para levar a arca de Deus, e para o servirem eternamente.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 3, 'E Davi convocou a todo o Israel em Jerusalém, para fazer subir a arca do Senhor ao seu lugar, que lhe tinha preparado.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 4, 'E Davi reuniu os filhos de Arão e os levitas:', 2, CURRENT_TIMESTAMP, false),
(13, 15, 5, 'Dos filhos de Coate: Uriel, o chefe, e de seus irmãos cento e vinte.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 6, 'Dos filhos de Merari: Asaías, o chefe, e de seus irmãos duzentos e vinte.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 7, 'Dos filhos de Gérson: Joel, o chefe, e de seus irmãos cento e trinta.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 8, 'Dos filhos de Elizafã: Semaías, o chefe, e de seus irmãos duzentos.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 9, 'Dos filhos de Hebrom: Eliel, o chefe, e de seus irmãos oitenta.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 10, 'Dos filhos de Uziel: Aminadabe, o chefe, e de seus irmãos cento e doze.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 11, 'E chamou Davi os sacerdotes Zadoque e Abiatar, e os levitas, Uriel, Asaías, Joel, Semaías, Eliel, e Aminadabe.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 12, 'E disse-lhes: Vós sois os chefes dos pais entre os levitas; santificai-vos, vós e vossos irmãos, para que façais subir a arca do Senhor Deus de Israel, ao lugar que lhe tenho preparado.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 13, 'Porquanto vós não a levastes na primeira vez, o Senhor nosso Deus fez rotura em nós, porque não o buscamos segundo a ordenança.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 14, 'Santificaram-se, pois, os sacerdotes e os levitas, para fazerem subir a arca do Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 15, 'E os filhos dos levitas trouxeram a arca de Deus sobre os seus ombros, pelas varas que nela havia, como Moisés tinha ordenado conforme a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 16, 'E disse Davi aos chefes dos levitas que constituíssem, de seus irmãos, cantores, para que com instrumentos musicais, com alaúdes, harpas e címbalos, se fizessem ouvir, levantando a voz com alegria.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 17, 'Designaram, pois, os levitas a Hemã, filho de Joel; e dos seus irmãos, Asafe, filho de Berequias; e dos filhos de Merari, seus irmãos, Etã, filho de Cusaías.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 18, 'E com eles a seus irmãos da segunda ordem: a Zacarias, Bene, Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaia, Maaséias, Matitias, Elifeleu, Micnéias, Obede-Edom, e Jeiel, os porteiros.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 19, 'E os cantores, Hemã, Asafe e Etã, se faziam ouvir com címbalos de metal;', 2, CURRENT_TIMESTAMP, false),
(13, 15, 20, 'E Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaséias, e Benaia, com alaúdes, sobre Alamote:', 2, CURRENT_TIMESTAMP, false),
(13, 15, 21, 'E Matitias, Elifeleu, Micnéias, Obede-Edom, Jeiel, e Azazias, com harpas, sobre Seminite, para sobressaírem.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 22, 'E Quenanias, chefe dos levitas, tinha o encargo de dirigir o canto; ensinava-os a entoá-lo, porque era entendido.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 23, 'E Berequias e Elcana eram porteiros da arca.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 24, 'E Sebanias, Jeosafá, Netanel, Amasai, Zacarias, Benaia, e Eliezer, os sacerdotes, tocavam as trombetas perante a arca de Deus; e Obede-Edom e Jeías eram porteiros da arca.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 25, 'Sucedeu, pois, que Davi e os anciãos de Israel, e os capitães dos milhares, foram, com alegria, para fazer subir a arca da aliança do Senhor, da casa de Obede-Edom.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 26, 'E sucedeu que, ajudando Deus os levitas que levavam a arca da aliança do Senhor, sacrificaram sete novilhos e sete carneiros.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 27, 'E Davi ia vestido de um manto de linho fino, como também todos os levitas que levavam a arca, e os cantores, e Quenanias, mestre dos cantores; também Davi levava sobre si um éfode de linho,', 2, CURRENT_TIMESTAMP, false),
(13, 15, 28, 'E todo o Israel fez subir a arca da aliança do Senhor, com júbilo, e ao som de buzinas, e de trombetas, e de címbalos, fazendo ressoar alaúdes e harpas.', 2, CURRENT_TIMESTAMP, false),
(13, 15, 29, 'E sucedeu que, chegando a arca da aliança do Senhor à cidade de Davi, Mical, a filha de Saul, olhou de uma janela, e, vendo a Davi dançar e tocar, o desprezou no seu coração.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 1, 'Trouxeram, pois, a arca de Deus, e a puseram no meio da tenda que Davi lhe tinha armado; e ofereceram holocaustos e sacrifícios pacíficos perante Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 2, 'E, acabando Davi de oferecer os holocaustos e sacrifícios pacíficos, abençoou o povo em nome do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 3, 'E repartiu a todos em Israel, tanto a homens como a mulheres, a cada um, um pão, e um bom pedaço de carne, e um frasco de vinho.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 4, 'E pôs alguns dos levitas por ministros perante a arca do Senhor; isto para recordarem, e louvarem, e celebrarem ao Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 5, 'Era Asafe, o chefe, e Zacarias o segundo depois dele; Jeiel, e Semiramote, e Jeiel, e Matitias, e Eliabe, e Benaia, e Obede-Edom, e Jeiel, com alaúdes e com harpas; e Asafe se fazia ouvir com címbalos;', 2, CURRENT_TIMESTAMP, false),
(13, 16, 6, 'Também Benaia, e Jaaziel, os sacerdotes, continuamente tocavam trombetas, perante a arca da aliança de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 7, 'Então naquele mesmo dia Davi, em primeiro lugar, deu o seguinte salmo para que, pelo ministério de Asafe e de seus irmãos, louvassem ao Senhor;', 2, CURRENT_TIMESTAMP, false),
(13, 16, 8, 'Louvai ao Senhor, invocai o seu nome, fazei conhecidas as suas obras entre os povos.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 9, 'Cantai-lhe, salmodiai-lhe, atentamente falai de todas as suas maravilhas.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 10, 'Gloriai-vos no seu santo nome; alegre-se o coração dos que buscam ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 11, 'Buscai ao Senhor e a sua força; buscai a sua face continuamente.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 12, 'Lembrai-vos das maravilhas que fez, de seus prodígios, e dos juízos da sua boca;', 2, CURRENT_TIMESTAMP, false),
(13, 16, 13, 'Vós, semente de Israel, seus servos, vós, filhos de Jacó, seus escolhidos.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 14, 'Ele é o Senhor nosso Deus; os seus juízos estão em toda a terra.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 15, 'Lembrai-vos perpetuamente da sua aliança e da palavra que prescreveu para mil gerações;', 2, CURRENT_TIMESTAMP, false),
(13, 16, 16, 'Da aliança que fez com Abraão, e do seu juramento a Isaque;', 2, CURRENT_TIMESTAMP, false),
(13, 16, 17, 'O qual também a Jacó confirmou por estatuto, e a Israel por aliança eterna,', 2, CURRENT_TIMESTAMP, false),
(13, 16, 18, 'Dizendo: A ti te darei a terra de Canaã, quinhão da vossa herança.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 19, 'Quando eram poucos homens em número, sim, mui poucos, e estrangeiros nela,', 2, CURRENT_TIMESTAMP, false),
(13, 16, 20, 'Quando andavam de nação em nação, e de um reino para outro povo,', 2, CURRENT_TIMESTAMP, false),
(13, 16, 21, 'A ninguém permitiu que os oprimisse, e por amor deles repreendeu reis, dizendo:', 2, CURRENT_TIMESTAMP, false),
(13, 16, 22, 'Não toqueis os meus ungidos, e aos meus profetas não façais mal.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 23, 'Cantai ao Senhor em toda a terra; anunciai de dia em dia a sua salvação.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 24, 'Contai entre as nações a sua glória, entre todos os povos as suas maravilhas.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 25, 'Porque grande é o Senhor, e mui digno de louvor, e mais temível é do que todos os deuses.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 26, 'Porque todos os deuses dos povos são ídolos; porém o Senhor fez os céus.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 27, 'Louvor e majestade há diante dele, força e alegria no seu lugar.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 28, 'Tributai ao Senhor, ó famílias dos povos, tributai ao Senhor glória e força.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 29, 'Tributai ao Senhor a glória de seu nome; trazei presentes, e vinde perante ele; adorai ao Senhor na beleza da sua santidade.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 30, 'Trema perante ele, trema toda a terra; pois o mundo se firmará, para que não se abale.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 31, 'Alegrem-se os céus, e regozije-se a terra; e diga-se entre as nações: O Senhor reina.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 32, 'Brame o mar com a sua plenitude; exulte o campo com tudo o que nele há;', 2, CURRENT_TIMESTAMP, false),
(13, 16, 33, 'Então jubilarão as árvores dos bosques perante o Senhor; porquanto vem julgar a terra.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 34, 'Louvai ao Senhor, porque é bom; pois a sua benignidade dura perpetuamente.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 35, 'E dizei: Salva-nos, ó Deus da nossa salvação, e ajunta-nos, e livra-nos das nações, para que louvemos o teu santo nome, e nos gloriemos no teu louvor.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 36, 'Bendito seja o Senhor Deus de Israel, de eternidade a eternidade. E todo o povo disse: Amém! E louvou ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 37, 'Então Davi deixou ali, diante da arca da aliança do Senhor, a Asafe e a seus irmãos, para ministrarem continuamente perante a arca, segundo se ordenara para cada dia.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 38, 'E mais a Obede-Edom, com seus irmãos, sessenta e oito; a este Obede-Edom, filho de Jedutum, e a Hosa, deixou por porteiros.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 39, 'E deixou a Zadoque, o sacerdote, e a seus irmãos, os sacerdotes, diante do tabernáculo do Senhor, no alto que está em Gibeom,', 2, CURRENT_TIMESTAMP, false),
(13, 16, 40, 'Para oferecerem holocaustos ao Senhor continuamente, pela manhã e à tarde, sobre o altar dos holocaustos; e isto segundo tudo o que está escrito na lei do Senhor que tinha prescrito a Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 41, 'E com eles a Hemã, e a Jedutum, e aos mais escolhidos, que foram apontados pelos seus nomes, para louvarem ao Senhor, porque a sua benignidade dura perpetuamente.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 42, 'Com eles, pois, estavam Hemã e Jedutum, com trombetas e címbalos, para os que haviam de tocar, e com outros instrumentos de música de Deus; porém os filhos de Jedutum estavam à porta.', 2, CURRENT_TIMESTAMP, false),
(13, 16, 43, 'Então todo o povo se retirou, cada um para a sua casa; e voltou Davi, para abençoar a sua casa.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 1, 'Sucedeu, pois, que, morando Davi já em sua casa, disse ao profeta Natã: Eis que moro em casa de cedro, mas a arca da aliança do SENHOR está debaixo de cortinas.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 2, 'Então Natã disse a Davi: Tudo quanto tens no teu coração faze, porque Deus é contigo.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 3, 'Mas sucedeu, na mesma noite, que a palavra de Deus veio a Natã, dizendo:', 2, CURRENT_TIMESTAMP, false),
(13, 17, 4, 'Vai, e dize a Davi meu servo: Assim diz o Senhor: Tu não me edificarás uma casa para eu morar;', 2, CURRENT_TIMESTAMP, false),
(13, 17, 5, 'Porque em casa nenhuma morei, desde o dia em que fiz subir a Israel até ao dia de hoje; mas fui de tenda em tenda, e de tabernáculo em tabernáculo.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 6, 'Por todas as partes por onde andei com todo o Israel, porventura falei alguma palavra a algum dos juízes de Israel, a quem ordenei que apascentasse o meu povo, dizendo: Por que não me edificais uma casa de cedro?', 2, CURRENT_TIMESTAMP, false),
(13, 17, 7, 'Agora, pois, assim dirás a meu servo Davi: Assim diz o Senhor dos Exércitos: Eu te tirei do curral, de detrás das ovelhas, para que fosses chefe do meu povo Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 8, 'E estive contigo por toda a parte, por onde foste, e de diante de ti exterminei todos os teus inimigos, e te fiz um nome como o nome dos grandes que estão na terra,', 2, CURRENT_TIMESTAMP, false),
(13, 17, 9, 'E ordenarei um lugar para o meu povo Israel, e o plantarei, para que habite no seu lugar, e nunca mais seja removido de uma para outra parte; e nunca mais os filhos da perversidade o debilitarão como dantes,', 2, CURRENT_TIMESTAMP, false),
(13, 17, 10, 'E desde os dias em que ordenei juízes sobre o meu povo Israel. Assim abaterei a todos os teus inimigos; também te faço saber que o Senhor te edificará uma casa.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 11, 'E há de ser que, quando forem cumpridos os teus dias, para ires a teus pais, suscitarei a tua descendência depois de ti, um dos teus filhos, e estabelecerei o seu reino.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 12, 'Este me edificará casa; e eu confirmarei o seu trono para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 13, 'Eu lhe serei por pai, e ele me será por filho; e a minha benignidade não retirarei dele, como a tirei daquele, que foi antes de ti.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 14, 'Mas o confirmarei na minha casa e no meu reino para sempre, e o seu trono será firme para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 15, 'Conforme todas estas palavras, e conforme toda esta visão, assim falou Natã a Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 16, 'Então entrou o rei Davi, e ficou perante o Senhor; e disse: Quem sou eu, Senhor Deus? e qual é a minha casa, para que me tenhas trazido até aqui?', 2, CURRENT_TIMESTAMP, false),
(13, 17, 17, 'E ainda isto, ó Deus, foi pouco aos teus olhos; pelo que falaste da casa de teu servo para tempos distantes; e trataste-me como a um homem ilustre, ó Senhor Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 18, 'Que mais te dirá Davi, acerca da honra feita a teu servo? Porém tu conheces bem a teu servo.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 19, 'Ó Senhor, por amor de teu servo, e segundo o teu coração, fizeste toda esta grandeza, para fazer notória todas estas grandes coisas.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 20, 'Senhor, ninguém há como tu, e não há Deus fora de ti, segundo tudo quanto ouvimos com os nossos ouvidos.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 21, 'E quem há como o teu povo Israel, única gente na terra, a quem Deus foi resgatar para seu povo, fazendo-te nome com coisas grandes e temerosas, lançando as nações de diante do teu povo, que resgataste do Egito?', 2, CURRENT_TIMESTAMP, false),
(13, 17, 22, 'E confirmaste o teu povo Israel para ser teu povo para sempre; e tu, Senhor, lhe foste por Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 23, 'Agora, pois, Senhor, a palavra que falaste de teu servo, e acerca da sua casa, confirma-a para sempre; e faze como falaste.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 24, 'Confirme-se e engrandeça-se o teu nome para sempre, e diga-se: O Senhor dos Exércitos é o Deus de Israel, é Deus para Israel; e permaneça firme diante de ti a casa de Davi, teu servo.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 25, 'Porque tu, Deus meu, revelaste ao ouvido de teu servo que lhe edificarias casa; pelo que o teu servo achou confiança para orar em tua presença.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 26, 'Agora, pois, Senhor, tu és o mesmo Deus, e falaste este bem acerca de teu servo.', 2, CURRENT_TIMESTAMP, false),
(13, 17, 27, 'Agora, pois, foste servido abençoar a casa de teu servo, para que permaneça para sempre diante de ti: porque tu, Senhor, a abençoaste, e ficará abençoada para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 1, 'E depois disto aconteceu que Davi derrotou os filisteus, e os sujeitou; e tomou a Gate, e os lugares da sua jurisdição, da mão dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 2, 'Também derrotou os moabitas; e os moabitas ficaram por servos de Davi, pagando tributos.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 3, 'Também Davi derrotou a Hadar-Ezer, rei de Zobá, junto a Hamate, quando ele ia estabelecer o seu domínio sobre o rio Eufrates.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 4, 'E Davi lhe tomou mil carros, e sete mil cavaleiros, e vinte mil homens de pé; e Davi jarretou todos os cavalos dos carros; porém reservou deles para cem carros.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 5, 'E vieram os sírios de Damasco a socorrer a Hadar-Ezer, rei de Zobá; porém Davi feriu dos sírios vinte e dois mil homens.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 6, 'E Davi pôs guarnições na Síria de Damasco, e os sírios ficaram por servos de Davi, pagando-lhe tributo; e o Senhor guardava a Davi, por onde quer que ia.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 7, 'E Davi tomou os escudos de ouro, que tinham os servos de Hadar-Ezer, e os trouxe a Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 8, 'Também de Tibate, e de Cum, cidades de Hadar-Ezer, tomou Davi muitíssimo cobre, de que Salomão fez o mar de cobre, e as colunas, e os utensílios de cobre.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 9, 'E ouvindo Toí, rei de Hamate, que Davi destruíra todo o exército de Hadar-Ezer, rei de Zobá,', 2, CURRENT_TIMESTAMP, false),
(13, 18, 10, 'Mandou seu filho Hadorão a Davi, para lhe perguntar como estava, e para o abençoar, por haver pelejado contra Hadar-Ezer, e por havê-lo ferido (porque Hadar-Ezer fazia guerra a Toí), enviando-lhe também toda a sorte de vasos de ouro, e de prata, e de cobre.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 11, 'Os quais Davi também consagrou ao Senhor, juntamente com a prata e ouro que trouxera de todas as demais nações: dos edomeus, e dos moabitas, e dos filhos de Amom, e dos filisteus, e dos amalequitas.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 12, 'Também Abisai, filho de Zeruia, feriu a dezoito mil edomeus no Vale do Sal.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 13, 'E pôs guarnições em Edom, e todos os edomeus ficaram por servos de Davi; e o Senhor guardava a Davi, por onde quer que ia.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 14, 'E Davi reinou sobre todo o Israel; e fazia juízo e justiça a todo o seu povo.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 15, 'E Joabe, filho de Zeruia, comandava o exército; Jeosafá, filho de Ailude, era cronista.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 16, 'E Zadoque, filho de Aitube, e Abimeleque, filho de Abiatar, eram sacerdotes; e Savsa escrivão.', 2, CURRENT_TIMESTAMP, false),
(13, 18, 17, 'E Benaia, filho de Joiada, estava sobre os quereteus e peleteus; porém os filhos de Davi eram os primeiros junto ao rei.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 1, 'E aconteceu, depois disto que Naás, rei dos filhos de Amom, morreu; e seu filho reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 2, 'Então disse Davi: Usarei de benevolência com Hanum, filho de Naás, porque seu pai usou de benevolência comigo. Por isso Davi enviou mensageiros para o consolarem acerca de seu pai. E, chegando os servos de Davi à terra dos filhos de Amom, a Hanum, para o consolarem,', 2, CURRENT_TIMESTAMP, false),
(13, 19, 3, 'Disseram os príncipes dos filhos de Amom a Hanum: Pensas porventura, que foi para honrar teu pai aos teus olhos, que Davi te mandou consoladores? Não vieram seus servos a ti, a esquadrinhar, e a transtornar, e a espiar a terra?', 2, CURRENT_TIMESTAMP, false),
(13, 19, 4, 'Por isso Hanum tomou os servos de Davi, e raspou-os, e cortou-lhes as vestes no meio até à coxa da perna, e os despediu.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 5, 'E foram-se, e avisaram a Davi acerca daqueles homens; e enviou ele mensageiros a encontrá-los; porque aqueles homens estavam sobremaneira envergonhados. Disse, pois, o rei: Deixai-vos ficar em Jericó, até que vos torne a crescer a barba, e então voltai.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 6, 'Vendo, pois, os filhos de Amom que se tinham feito odiosos para com Davi, enviou Hanum, e os filhos de Amom, mil talentos de prata para alugarem para si carros e cavaleiros da Mesopotâmia, e da Síria de Maaca, e de Zobá.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 7, 'E alugaram para si trinta e dois mil carros, e o rei de Maaca e o seu povo, e eles vieram, e se acamparam diante de Medeba; também os filhos de Amom se ajuntaram das suas cidades, e vieram para a guerra.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 8, 'O que ouvindo Davi, enviou Joabe e todo o exército dos homens valentes.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 9, 'E, saindo os filhos de Amom, ordenaram a batalha à porta da cidade; porém os reis que vieram se puseram à parte no campo.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 10, 'E, vendo Joabe que a batalha estava preparada contra ele, pela frente e pela retaguarda, separou dentre os mais escolhidos de Israel, e os ordenou contra os sírios.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 11, 'E o resto do povo entregou na mão de Abisai, seu irmão; e puseram-se em ordem de batalha contra os filhos de Amom.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 12, 'E disse: Se os sírios forem mais fortes do que eu, tu virás socorrer-me; e, se os filhos de Amom forem mais fortes do que tu, então eu te socorrerei.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 13, 'Esforça-te, e esforcemo-nos pelo nosso povo, e pelas cidades do nosso Deus, e faça o Senhor o que parecer bem aos seus olhos.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 14, 'Então se chegou Joabe, e o povo que tinha consigo, diante dos sírios, para a batalha; e fugiram de diante dele.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 15, 'Vendo, pois, os filhos de Amom que os sírios fugiram, também eles fugiram de diante de Abisai, seu irmão, e entraram na cidade; e veio Joabe para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 16, 'E, vendo os sírios que foram derrotados diante de Israel, enviaram mensageiros, e fizeram sair os sírios que habitavam do outro lado do rio; e Sofaque, capitão do exército de Hadar-Ezer, marchava diante deles.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 17, 'Do que avisado Davi, ajuntou a todo o Israel, e passou o Jordão, e foi ter com eles, e ordenou contra eles a batalha; e, tendo Davi ordenado a batalha contra os sírios, pelejaram contra ele.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 18, 'Porém os sírios fugiram de diante de Israel, e feriu Davi, dos sírios, os homens de sete mil carros, e quarenta mil homens de pé; e a Sofaque, capitão do exército, matou.', 2, CURRENT_TIMESTAMP, false),
(13, 19, 19, 'Vendo, pois, os servos de Hadar-Ezer que tinham sido feridos diante de Israel, fizeram paz com Davi, e o serviram; e os sírios nunca mais quiseram socorrer os filhos de Amom.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 1, 'Aconteceu que, no decurso de um ano, no tempo em que os reis costumam sair para a guerra, Joabe levou o exército, e destruiu a terra dos filhos de Amom, e veio, e cercou a Rabá; porém Davi ficou em Jerusalém; e Joabe feriu a Rabá, e a destruiu.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 2, 'E Davi tirou a coroa da cabeça do rei deles, e achou nela o peso de um talento de ouro, e havia nela pedras preciosas; e foi posta sobre a cabeça de Davi; e levou da cidade mui grande despojo.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 3, 'Também levou o povo que estava nela, e os fez trabalhar com a serra, e com talhadeiras de ferro e com machados; e assim fez Davi com todas as cidades dos filhos de Amom; então voltou Davi, com todo o povo, para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 4, 'E, depois disto, aconteceu que, levantando-se guerra em Gezer, com os filisteus, então Sibecai, o husatita, feriu a Sipai, dos filhos do gigante; e ficaram subjugados.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 5, 'E tornou a haver guerra com os filisteus; e El-Hanã, filho de Jair, feriu a Lami, irmão de Golias, o giteu, cuja haste da lança era como órgão de tecelão.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 6, 'E houve ainda outra guerra em Gate; onde havia um homem de grande estatura, e tinha vinte e quatro dedos, seis em cada mão, e seis em cada pé, e que também era filho do gigante.', 2, CURRENT_TIMESTAMP, false),
(13, 20, 7, 'E injuriou a Israel; porém Jônatas, filho de Simei, irmão de Davi, o feriu;', 2, CURRENT_TIMESTAMP, false),
(13, 20, 8, 'Estes nasceram ao gigante em Gate; e caíram pela mão de Davi e pela mão dos seus servos.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 1, 'Então Satanás se levantou contra Israel, e incitou Davi a numerar a Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 2, 'E disse Davi a Joabe e aos maiorais do povo: Ide, numerai a Israel, desde Berseba até Dã; e trazei-me a conta para que saiba o número deles.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 3, 'Então disse Joabe: O SENHOR acrescente ao seu povo cem vezes tanto como é; porventura, ó rei meu senhor, não são todos servos de meu senhor? Por que procura isto o meu senhor? Porque seria isto causa de delito para com Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 4, 'Porém a palavra do rei prevaleceu contra Joabe; por isso saiu Joabe, e passou por todo o Israel; então voltou para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 5, 'E Joabe deu a Davi a soma do número do povo; e era todo o Israel um milhão e cem mil homens, dos que arrancavam da espada; e de Judá quatrocentos e setenta mil homens, dos que arrancavam da espada.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 6, 'Porém os de Levi e Benjamim não contou entre eles, porque a palavra do rei foi abominável a Joabe.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 7, 'E este negócio também pareceu mau aos olhos de Deus; por isso feriu a Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 8, 'Então disse Davi a Deus: Gravemente pequei em fazer este negócio; porém agora sê servido tirar a iniqüidade de teu servo, porque procedi mui loucamente.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 9, 'Falou, pois, o Senhor a Gade, o vidente de Davi, dizendo:', 2, CURRENT_TIMESTAMP, false),
(13, 21, 10, 'Vai, e fala a Davi, dizendo: Assim diz o Senhor: Três coisas te proponho; escolhe uma delas, para que eu ta faça.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 11, 'E Gade veio a Davi, e lhe disse: Assim diz o Senhor: Escolhe para ti,', 2, CURRENT_TIMESTAMP, false),
(13, 21, 12, 'Ou três anos de fome, ou que três meses sejas consumido diante dos teus adversários, e a espada de teus inimigos te alcance, ou que três dias a espada do Senhor, isto é, a peste na terra, e o anjo do Senhor destrua todos os termos de Israel; vê, pois, agora, que resposta hei de levar a quem me enviou.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 13, 'Então disse Davi a Gade: Estou em grande angústia; caia eu, pois, nas mãos do Senhor, porque são muitíssimas as suas misericórdias; mas que eu não caia nas mãos dos homens.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 14, 'Mandou, pois, o Senhor a peste a Israel; e caíram de Israel setenta mil homens.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 15, 'E Deus mandou um anjo a Jerusalém para a destruir; e, destruindo-a ele, o Senhor olhou, e se arrependeu daquele mal, e disse ao anjo destruidor: Basta, agora retira a tua mão. E o anjo do Senhor estava junto à eira de Ornã, o jebuseu.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 16, 'E, levantando Davi os seus olhos, viu o anjo do Senhor, que estava entre a terra e o céu, com a sua espada desembainhada na sua mão estendida contra Jerusalém; então Davi e os anciãos, cobertos de sacos, se prostraram sobre os seus rostos.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 17, 'E disse Davi a Deus: Não sou eu o que disse que se contasse o povo? E eu mesmo sou o que pequei, e fiz muito mal; mas estas ovelhas que fizeram? Ah! Senhor, meu Deus, seja a tua mão contra mim, e contra a casa de meu pai, e não para castigo de teu povo.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 18, 'Então o anjo do Senhor ordenou a Gade que dissesse a Davi para subir e levantar um altar ao Senhor na eira de Ornã, o jebuseu.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 19, 'Subiu, pois, Davi, conforme a palavra de Gade, que falara em nome do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 20, 'E, virando-se Ornã, viu o anjo, e esconderam-se seus quatro filhos que estavam com ele; e Ornã estava trilhando o trigo.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 21, 'E Davi veio a Ornã; e olhou Ornã, e viu a Davi, e saiu da eira, e se prostrou perante Davi com o rosto em terra.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 22, 'E disse Davi a Ornã: Dá-me este lugar da eira, para edificar nele um altar ao Senhor; dá-mo pelo seu valor, para que cesse este castigo sobre o povo.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 23, 'Então disse Ornã a Davi: Toma-o para ti, e faça o rei meu senhor dele o que parecer bem aos seus olhos; eis que dou os bois para holocaustos, e os trilhos para lenha, e o trigo para oferta de alimentos; tudo dou.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 24, 'E disse o rei Davi a Ornã: Não, antes, pelo seu valor, a quero comprar; porque não tomarei o que é teu, para o Senhor, para que não ofereça holocausto sem custo.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 25, 'E Davi deu a Ornã, por aquele lugar, o peso de seiscentos siclos de ouro.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 26, 'Então Davi edificou ali um altar ao Senhor, e ofereceu nele holocaustos e sacrifícios pacíficos; e invocou o Senhor, o qual lhe respondeu com fogo do céu sobre o altar do holocausto.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 27, 'E o Senhor deu ordem ao anjo, e ele tornou a sua espada à bainha.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 28, 'Vendo Davi, no mesmo tempo, que o Senhor lhe respondera na eira de Ornã, o jebuseu, sacrificou ali.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 29, 'Porque o tabernáculo do Senhor, que Moisés fizera no deserto, e o altar do holocausto, estavam naquele tempo no alto de Gibeom.', 2, CURRENT_TIMESTAMP, false),
(13, 21, 30, 'E não podia Davi ir perante ele consultar a Deus; porque estava aterrorizado por causa da espada do anjo do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 1, 'E disse Davi: Esta será a casa do SENHOR Deus, e este será o altar do holocausto para Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 2, 'E deu ordem Davi que se ajuntassem os estrangeiros que estavam na terra de Israel; e ordenou cortadores de pedras, para que lavrassem pedras de cantaria, para edificar a casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 3, 'E aparelhou Davi ferro em abundância, para os pregos das portas das entradas, e para as junturas; como também cobre em abundância, que não foi pesado;', 2, CURRENT_TIMESTAMP, false),
(13, 22, 4, 'E madeira de cedro sem conta; porque os sidônios e tírios traziam a Davi madeira de cedro em abundância.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 5, 'Porque dizia Davi: Salomão, meu filho, ainda é moço e tenro, e a casa que se há de edificar para o Senhor deve ser magnífica em excelência, para nome e glória em todas as terras; eu, pois, agora lhe prepararei materiais. Assim preparou Davi materiais em abundância, antes da sua morte.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 6, 'Então chamou a Salomão seu filho, e lhe ordenou que edificasse uma casa ao Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 7, 'E disse Davi a Salomão: Filho meu, quanto a mim, tive em meu coração o propósito de edificar uma casa ao nome do Senhor meu Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 8, 'Porém, veio a mim a palavra do Senhor, dizendo: Tu derramaste sangue em abundância, e fizeste grandes guerras; não edificarás casa ao meu nome; porquanto muito sangue tens derramado na terra, perante mim.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 9, 'Eis que o filho que te nascer será homem de repouso; porque repouso lhe hei de dar de todos os seus inimigos ao redor; portanto, Salomão será o seu nome, e paz e descanso darei a Israel nos seus dias.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 10, 'Ele edificará uma casa ao meu nome, e me será por filho, e eu lhe serei por pai, e confirmarei o trono de seu reino sobre Israel, para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 11, 'Agora, pois, meu filho, o Senhor seja contigo; e prospera, e edifica a casa do Senhor teu Deus, como ele disse de ti.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 12, 'O Senhor te dê tão-somente prudência e entendimento, e te instrua acerca de Israel; e isso para guardar a lei do Senhor teu Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 13, 'Então prosperarás, se tiveres cuidado de cumprir os estatutos e os juízos, que o Senhor mandou a Moisés acerca de Israel; esforça-te, e tem bom ânimo; não temas, nem tenhas pavor.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 14, 'Eis que na minha aflição preparei para a casa do Senhor cem mil talentos de ouro, e um milhão de talentos de prata, e de cobre e de ferro que não se pesou, porque era em abundância; também madeira e pedras preparei, e tu suprirás o que faltar.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 15, 'Também tens contigo obreiros em grande número, cortadores e artífices em obra de pedra e madeira; e toda a sorte de peritos em toda a espécie de obra.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 16, 'Do ouro, da prata, e do cobre, e do ferro não há conta. Levanta-te, pois, e faze a obra, e o Senhor seja contigo.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 17, 'E Davi deu ordem a todos os príncipes de Israel que ajudassem a Salomão, seu filho, dizendo:', 2, CURRENT_TIMESTAMP, false),
(13, 22, 18, 'Porventura não está convosco o Senhor vosso Deus, e não vos deu repouso ao redor? Porque entregou na minha mão os moradores da terra; e a terra foi sujeita perante o Senhor e perante o seu povo.', 2, CURRENT_TIMESTAMP, false),
(13, 22, 19, 'Disponde, pois, agora o vosso coração e a vossa alma para buscardes ao Senhor vosso Deus; e levantai-vos, e edificai o santuário do Senhor Deus, para que a arca da aliança do Senhor, e os vasos sagrados de Deus se tragam a esta casa, que se há de edificar ao nome do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 1, 'Sendo, pois, Davi já velho, e cheio de dias, fez a Salomão, seu filho, rei sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 2, 'E reuniu a todos os príncipes de Israel, como também aos sacerdotes e levitas.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 3, 'E foram contados os levitas de trinta anos para cima; e foi o número deles, segundo as suas cabeças, trinta e oito mil homens.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 4, 'Destes havia vinte e quatro mil, para promoverem a obra da casa do Senhor, e seis mil oficiais e juízes,', 2, CURRENT_TIMESTAMP, false),
(13, 23, 5, 'E quatro mil porteiros, e quatro mil para louvarem ao Senhor com os instrumentos, que eu fiz para o louvar, disse Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 6, 'E Davi os repartiu por turnos, segundo os filhos de Levi, Gérson, Coate e Merari.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 7, 'Dos gersonitas: Ladã e Simei.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 8, 'Os filhos de Ladã: Jeiel, o chefe, e Zetã, e Joel, três.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 9, 'Os filhos de Simei: Selomite, Haziel, e Harã, três; estes foram os chefes dos pais de Ladã.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 10, 'E os filhos de Simei: Jaate, Ziza, Jeús, e Berias; estes foram os filhos de Simei, quatro.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 11, 'E Jaate era o chefe, e Ziza o segundo, mas Jeús e Berias não tiveram muitos filhos; por isso estes, sendo contados juntos se tornaram uma só família.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 12, 'Os filhos de Coate: Anrão, Izar, Hebrom, e Uziel, quatro.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 13, 'Os filhos de Anrão: Arão e Moisés; e Arão foi separado para santificar o santo dos santos, ele e seus filhos, eternamente; para incensar diante do Senhor, para o servirem, e para darem a bênção em seu nome eternamente.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 14, 'E, quanto a Moisés, homem de Deus, seus filhos foram contados entre os da tribo de Levi.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 15, 'Foram, pois, os filhos de Moisés, Gérson e Eliézer.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 16, 'Dos filhos de Gérson foi Sebuel o chefe.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 17, 'E, quanto aos filhos de Eliézer, foi Reabias o chefe; e Eliézer não teve outros filhos; porém os filhos de Reabias foram muitos.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 18, 'Dos filhos de Izar foi Selomite o chefe.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 19, 'Quanto aos filhos de Hebrom, foram Jerias o primeiro, Amarias o segundo, Jaaziel o terceiro, e Jecameão o quarto.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 20, 'Quanto aos filhos de Uziel, Mica o chefe, e Issias o segundo.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 21, 'Os filhos de Merari: Mali, e Musi; os filhos de Mali: Eleazar e Quis.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 22, 'E morreu Eleazar, e não teve filhos, porém filhas; e os filhos de Quis, seus parentes, as tomaram por mulheres.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 23, 'Os filhos de Musi: Mali, e Eder, e Jeremote, três.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 24, 'Estes são os filhos de Levi, segundo a casa de seus pais, chefes dos pais, conforme foram contados pelos seus nomes, segundo as suas cabeças, que faziam a obra do ministério da casa do Senhor, desde a idade de vinte anos para cima.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 25, 'Porque disse Davi: O Senhor Deus de Israel deu repouso ao seu povo, e habitará em Jerusalém para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 26, 'E também, quanto aos levitas, que nunca mais levassem o tabernáculo, nem algum de seus aparelhos pertencentes ao seu ministério.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 27, 'Porque, segundo as últimas palavras de Davi, foram contados os filhos de Levi da idade de vinte anos para cima:', 2, CURRENT_TIMESTAMP, false),
(13, 23, 28, 'Porque o seu cargo era assistir aos filhos de Arão no ministério da casa do Senhor, nos átrios, e nas câmaras, e na purificação de todas as coisas sagradas, e na obra do ministério da casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 23, 29, 'A saber: para os pães da proposição, e para a flor de farinha, para a oferta de alimentos, e para os coscorões ázimos, e para as sertãs, e para o tostado, e para todo o peso e medida;', 2, CURRENT_TIMESTAMP, false),
(13, 23, 30, 'E para estarem cada manhã em pé para louvarem e celebrarem ao Senhor; e semelhantemente à tarde;', 2, CURRENT_TIMESTAMP, false),
(13, 23, 31, 'E para oferecerem os holocaustos do Senhor, aos sábados, nas luas novas, e nas solenidades, segundo o seu número e costume, continuamente perante o Senhor;', 2, CURRENT_TIMESTAMP, false),
(13, 23, 32, 'E para que tivessem cuidado da guarda da tenda da congregação, e da guarda do santuário, e da guarda dos filhos de Arão, seus irmãos, no ministério da casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 1, 'E quanto aos filhos de Arão, estas foram as suas divisões: os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 2, 'E morreram Nadabe e Abiú antes de seu pai, e não tiveram filhos; e Eleazar e Itamar administravam o sacerdócio.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 3, 'E Davi, com Zadoque, dos filhos de Eleazar, e Aimeleque, dos filhos de Itamar, dividiu-os segundo o seu ofício no seu ministério.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 4, 'E acharam-se muito mais chefes dos pais entre os filhos de Eleazar do que entre os filhos de Itamar, quando os repartiram; dos filhos de Eleazar dezesseis chefes das casas paternas, mas dos filhos de Itamar, segundo as casas paternas, oito.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 5, 'E os repartiram por sortes, uns com os outros; porque houve governadores do santuário e governadores da casa de Deus, assim dentre os filhos de Eleazar, como dentre os filhos de Itamar.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 6, 'E Semaías, filho de Natanael, o escrivão dentre os levitas, os registrou perante o rei, e os príncipes, e Zadoque, o sacerdote, e Aimeleque, filho de Abiatar, e os chefes dos pais entre os sacerdotes, e entre os levitas; dentre as casas dos pais tomou-se uma para Eleazar, e outra para Itamar.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 7, 'E saiu a primeira sorte a Jeoiaribe, a segunda a Jedaías,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 8, 'A terceira a Harim, a quarta a Seorim,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 9, 'A quinta a Malquias, a sexta a Miamim,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 10, 'A sétima a Hacoz, a oitava a Abias,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 11, 'A nona a Jesua, a décima a Secanias,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 12, 'A undécima a Eliasibe, a duodécima a Jaquim,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 13, 'A décima terceira a Hupa, a décima quarta a Jesebeabe,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 14, 'A décima quinta a Bilga, a décima sexta a Imer,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 15, 'A décima sétima a Hezir, a décima oitava a Hapizes,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 16, 'A décima nona a Petaías, a vigésima a Jeezquel,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 17, 'A vigésima primeira a Jaquim, a vigésima segunda a Gamul,', 2, CURRENT_TIMESTAMP, false),
(13, 24, 18, 'A vigésima terceira a Delaías, a vigésima quarta a Maazias.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 19, 'O ofício destes no seu ministério era entrar na casa do Senhor, segundo lhes fora ordenado por Arão seu pai, como o Senhor Deus de Israel lhe tinha mandado.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 20, 'E do restante dos filhos de Levi: dos filhos de Anrão, Subael; dos filhos de Subael, Jedias.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 21, 'Quanto a Reabias: dos filhos de Reabias, Issias era o primeiro;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 22, 'Dos izaritas, Selomote; dos filhos de Selomote, Jaate;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 23, 'E dos filhos de Hebrom, Jerias o primeiro, Amarias o segundo, Jaaziel o terceiro, Jecameão o quarto;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 24, 'Dos filhos de Uziel, Mica; dos filhos de Mica, Samir;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 25, 'O irmão de Mica, Issias; dos filhos de Issias, Zacarias;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 26, 'Os filhos de Merari, Mali e Musi; dos filhos de Jaazias, Beno;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 27, 'Os filhos de Merari: de Jaazias, Beno, e Soão, e Zacur, e Ibri;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 28, 'De Mali, Eleazar; e este não teve filhos.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 29, 'Quanto a Quis: dos filhos de Quis, Jerameel;', 2, CURRENT_TIMESTAMP, false),
(13, 24, 30, 'E os filhos de Musi: Mali, e Eder, e Jerimote; estes foram os filhos dos levitas, segundo as suas casas paternas.', 2, CURRENT_TIMESTAMP, false),
(13, 24, 31, 'Estes também lançaram sortes como seus irmãos, os filhos de Arão, perante o rei Davi, e Zadoque, e Aimeleque, e os chefes das famílias entre os sacerdotes e entre os levitas; assim fizeram, tanto os pais principais como os irmãos menores.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 1, 'E Davi, juntamente com os capitães do exército, separou para o ministério os filhos de Asafe, e de Hemã, e de Jedutum, para profetizarem com harpas, com címbalos, e com saltérios; e este foi o número dos homens aptos para a obra do seu ministério:', 2, CURRENT_TIMESTAMP, false),
(13, 25, 2, 'Dos filhos de Asafe: Zacur, José, Netanias, e Asarela, filhos de Asafe; a cargo de Asafe, que profetizava debaixo das ordens do rei Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 3, 'Quanto a Jedutum, os filhos: Gedalias, Zeri, Jesaías, Hasabias, e Matitias, seis, a cargo de seu pai, Jedutum, o qual profetizava com a harpa, louvando e dando graças ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 4, 'Quanto a Hemã, os filhos: Buquias, Matanias, Uziel, Sebuel, Jerimote, Hananias, Hanani, Eliata, Gidalti, Romanti-Ezer, Josbecasa, Maloti, Hotir, e Maaziote.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 5, 'Todos estes foram filhos de Hemã, o vidente do rei nas palavras de Deus, para exaltar o seu poder; porque Deus dera a Hemã catorze filhos e três filhas.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 6, 'Todos estes estavam sob a direção de seu pai, para a música da casa do Senhor, com saltérios, címbalos e harpas, para o ministério da casa de Deus; e Asafe, Jedutum, e Hemã, estavam sob as ordens do rei.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 7, 'E era o número deles, juntamente com seus irmãos instruídos no canto ao Senhor, todos eles mestres, duzentos e oitenta e oito.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 8, 'E deitaram sortes acerca da guarda igualmente, assim o pequeno como o grande, o mestre juntamente com o discípulo.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 9, 'Saiu, pois, a primeira sorte a Asafe, a saber a José; a segunda a Gedalias; e ele, e seus irmãos, e seus filhos, ao todo eram doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 10, 'A terceira a Zacur, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 11, 'A quarta a Izri, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 12, 'A quinta a Netanias, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 13, 'A sexta a Buquias, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 14, 'A sétima a Jesarela, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 15, 'A oitava a Jesaías, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 16, 'A nona a Matanias, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 17, 'A décima a Simei, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 18, 'A undécima a Azareel, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 19, 'A duodécima a Hasabias, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 20, 'A décima terceira a Subael, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 21, 'A décima quarta a Matitias, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 22, 'A décima quinta a Jeremote, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 23, 'A décima sexta a Hananias, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 24, 'A décima sétima a Josbecasa, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 25, 'A décima oitava a Hanani, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 26, 'A décima nona a Maloti, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 27, 'A vigésima a Eliata, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 28, 'A vigésima primeira a Hotir, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 29, 'A vigésima segunda a Gidalti, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 30, 'A vigésima terceira a Maaziote, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 25, 31, 'A vigésima quarta a Romanti-Ezer, seus filhos, e seus irmãos, doze.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 1, 'Quanto às divisões dos porteiros: dos coraítas: Meselemias, filho de Coré, dos filhos de Asafe.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 2, 'E foram os filhos de Meselemias: Zacarias o primogênito, Jediael o segundo, Zebadias o terceiro, Jatniel o quarto,', 2, CURRENT_TIMESTAMP, false),
(13, 26, 3, 'Elão o quinto, Joanã o sexto, Elioenai o sétimo.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 4, 'E os filhos de Obede-Edom foram: Semaías o primogênito, Jozabade o segundo, Joá o terceiro, e Sacar o quarto, e Natanael o quinto,', 2, CURRENT_TIMESTAMP, false),
(13, 26, 5, 'Amiel o sexto, Issacar o sétimo, Peuletai o oitavo; porque Deus o tinha abençoado.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 6, 'Também a seu filho Semaías nasceram filhos, que dominaram sobre a casa de seu pai; porque foram homens valentes.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 7, 'Os filhos de Semaías: Otni, Rafael, Obede, e Elzabade, com seus irmãos, homens valentes, Eliú e Semaquias.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 8, 'Todos estes foram dos filhos de Obede-Edom; eles e seus filhos, e seus irmãos, homens valentes e de força para o ministério; ao todo sessenta e dois, de Obede-Edom.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 9, 'E os filhos e os irmãos de Meselemias, homens valentes, foram dezoito.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 10, 'E de Hosa, dentre os filhos de Merari, foram filhos: Sinri o chefe (ainda que não era o primogênito, contudo seu pai o constituiu chefe),', 2, CURRENT_TIMESTAMP, false),
(13, 26, 11, 'Hilquias o segundo, Tebalias o terceiro, Zacarias o quarto; todos os filhos e irmãos de Hosa foram treze.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 12, 'Destes se fizeram as turmas dos porteiros, alternando os principais dos homens da guarda, juntamente com os seus irmãos, para ministrarem na casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 13, 'E lançaram sortes, assim os pequenos como os grandes, segundo as casas de seus pais, para cada porta.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 14, 'E caiu a sorte do oriente a Selemias; e lançou-se a sorte por seu filho Zacarias, conselheiro entendido, e saiu-lhe a do norte.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 15, 'E para Obede-Edom a do sul; e para seus filhos a casa dos depósitos.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 16, 'Para Supim e Hosa a do ocidente, junto a porta Salequete, perto do caminho da subida; uma guarda defronte de outra guarda.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 17, 'Ao oriente seis levitas; ao norte quatro por dia, ao sul quatro por dia, porém para as casas dos depósitos de dois em dois.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 18, 'Em Parbar, ao ocidente, quatro junto ao caminho, e dois junto a Parbar.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 19, 'Estas são as turmas dos porteiros dentre os filhos dos coraítas, e dentre os filhos de Merari.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 20, 'E dos levitas: Aías tinha cargo dos tesouros da casa de Deus e dos tesouros das coisas sagradas.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 21, 'Quanto aos filhos de Ladã, os filhos dos gersonitas que pertencem a Ladã, chefes das casas paternas de Ladã: Jeieli.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 22, 'Os filhos de Jeieli: Zetã e Joel, seu irmão; estes tinham cargo dos tesouros da casa do Senhor,', 2, CURRENT_TIMESTAMP, false),
(13, 26, 23, 'Dos anramitas, dos izaritas, dos hebronitas, dos uzielitas.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 24, 'E Sebuel, filho de Gérson, o filho de Moisés, era o chefe dos tesouros.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 25, 'E seus irmãos foram, do lado de Eliézer, Reabias seu filho, e Jesaías seu filho, e Jorão seu filho, e Zicri seu filho, e Selomite, seu filho.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 26, 'Este Selomite e seus irmãos tinham a seu cargo todos os tesouros das coisas dedicadas que o rei Davi e os chefes das casas paternas, capitães de milhares, e de centenas, e capitães do exército tinham consagrado.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 27, 'Dos despojos das guerras dedicaram ofertas para repararem a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 28, 'Como também tudo quanto tinha consagrado Samuel, o vidente, e Saul filho de Quis, e Abner filho de Ner, e Joabe filho de Zeruia; tudo que qualquer havia dedicado estava debaixo da mão de Selomite e seus irmãos.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 29, 'Dos izaritas, Quenanias e seus filhos foram postos sobre Israel como oficiais e como juízes, dos negócios externos.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 30, 'Dos hebronitas foram Hasabias e seus irmãos, homens valentes, mil e setecentos, que tinham a superintendência sobre Israel, além do Jordão para o ocidente, em toda a obra do Senhor, e para o serviço do rei.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 31, 'Dos hebronitas Jerias era o chefe, segundo as suas gerações conforme as suas famílias. No ano quarenta do reino de Davi se buscaram e acharam entre eles homens valentes em Jazer de Gileade.', 2, CURRENT_TIMESTAMP, false),
(13, 26, 32, 'E seus irmãos, homens valentes, dois mil e setecentos, chefes dos pais; e o rei Davi os constituiu sobre os rubenitas e os gaditas, e a meia tribo dos manassitas, para todos os negócios de Deus, e para todos os negócios do rei.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 1, 'Estes são os filhos de Israel segundo o seu número, os chefes dos pais, e os capitães dos milhares e das centenas, com os seus oficiais, que serviam ao rei em todos os negócios das turmas que entravam e saíam de mês em mês, em todos os meses do ano; cada turma de vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 2, 'Sobre a primeira turma do primeiro mês estava Jasobeão, filho de Zabdiel; e em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 3, 'Era este dos filhos de Perez, chefe de todos os capitães dos exércitos, para o primeiro mês,', 2, CURRENT_TIMESTAMP, false),
(13, 27, 4, 'E sobre a turma do segundo mês estava Dodai, o aoíta, com a sua turma, cujo líder era Miclote; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 5, 'O terceiro capitão do exército, para o terceiro mês, era Benaia, filho de Joiada, chefe dos sacerdotes; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 6, 'Era este Benaia valente entre os trinta, e sobre os trinta; e na sua turma estava Amizabade, seu filho.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 7, 'O quarto, do quarto mês, era Asael, irmão de Joabe, e depois dele Zebadias, seu filho; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 8, 'O quinto, do quinto mês, Samute, o israíta; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 9, 'O sexto, do sexto mês, Ira, filho de Iques, o tecoíta; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 10, 'O sétimo, do sétimo mês, Helez, o pelonita, dos filhos de Efraim; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 11, 'O oitavo, do oitavo mês, Sibecai, o husatita, dos zeraítas; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 12, 'O nono, do nono mês, Abiezer, o anatotita, dos benjamitas; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 13, 'O décimo, do décimo mês, Maarai, o netofatita, dos zeraítas; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 14, 'O undécimo, do undécimo mês, Benaia, o piratonita, dos filhos de Efraim; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 15, 'O duodécimo, do duodécimo mês, Heldai, o netofatita, de Otniel; também em sua turma havia vinte e quatro mil.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 16, 'Sobre as tribos de Israel estavam: sobre os rubenitas era líder Eliezer, filho de Zicri; sobre os simeonitas, Sefatias, filho de Maaca.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 17, 'Sobre os levitas, Hasabias, filho de Quemuel; sobre os aronitas, Zadoque;', 2, CURRENT_TIMESTAMP, false),
(13, 27, 18, 'Sobre Judá, Eliú, dos irmãos de Davi; sobre Issacar, Onri, filho de Micael;', 2, CURRENT_TIMESTAMP, false),
(13, 27, 19, 'Sobre Zebulom, Ismaías, filho de Obadias; sobre Naftali, Jerimote, filho de Azriel;', 2, CURRENT_TIMESTAMP, false),
(13, 27, 20, 'Sobre os filhos de Efraim, Oséias, filho de Azazias; sobre a meia tribo de Manassés, Joel, filho de Pedaías;', 2, CURRENT_TIMESTAMP, false),
(13, 27, 21, 'Sobre a outra meia tribo de Manassés em Gileade, Ido, filho de Zacarias; sobre Benjamim, Jaasiel, filho de Abner;', 2, CURRENT_TIMESTAMP, false),
(13, 27, 22, 'Sobre Dã, Azarel, filho de Jeroão. Estes eram os príncipes das tribos de Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 23, 'Não tomou, porém, Davi o número dos de vinte anos para baixo, porquanto o Senhor tinha falado que havia de multiplicar a Israel como as estrelas do céu.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 24, 'Joabe, filho de Zeruia, tinha começado a numerá-los, porém não acabou; porquanto viera por isso grande ira sobre Israel; assim o número não se pôs no registro das crônicas do rei Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 25, 'E sobre os tesouros do rei estava Azmavete, filho de Adiel; e sobre os tesouros dos campos, das cidades, e das aldeias, e das torres, Jônatas, filho de Uzias.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 26, 'E sobre os que faziam a obra do campo, na lavoura da terra, Ezri, filho de Quelube.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 27, 'E sobre as vinhas, Simei, o ramatita; porém sobre o que das vides entrava nas adegas do vinho, Zabdi, o sifmita.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 28, 'E sobre os olivais e sicômoros que havia nas campinas, Baal-Hanã, o gederita; porém Joás sobre os armazéns do azeite.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 29, 'E sobre os gados que pastavam em Sarom, Sitrai, o saronita; porém, sobre os gados dos vales, Safate, filho de Adlai.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 30, 'E sobre os camelos, Obil, o ismaelita; e sobre as jumentas, Jedias, o meronotita.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 31, 'E sobre o gado miúdo, Jaziz, o hagrita; todos esses eram administradores da fazenda que tinha o rei Davi.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 32, 'E Jônatas, tio de Davi, era do conselho, homem entendido, e também escriba; e Jeiel, filho de Hacmoni, estava com os filhos do rei.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 33, 'E Aitofel era do conselho do rei; e Husai, o arquita, amigo do rei.', 2, CURRENT_TIMESTAMP, false),
(13, 27, 34, 'E depois de Aitofel, Joiada, filho de Benaia, e Abiatar; porém Joabe era o general do exército do rei.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 1, 'Então Davi reuniu em Jerusalém todos os príncipes de Israel, os príncipes das tribos, e os capitães das turmas, que serviam o rei, e os capitães dos milhares, e os capitães das centenas, e os administradores de toda a fazenda e possessão do rei, e de seus filhos, como também os oficiais, os poderosos, e todo o homem valente.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 2, 'E pôs-se o rei Davi em pé, e disse: Ouvi-me, irmãos meus, e povo meu; em meu coração propus eu edificar uma casa de repouso para a arca da aliança do Senhor e para o estrado dos pés do nosso Deus, e eu tinha feito o preparo para a edificar.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 3, 'Porém Deus me disse: Não edificarás casa ao meu nome, porque és homem de guerra, e derramaste muito sangue.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 4, 'E o Senhor Deus de Israel escolheu-me de toda a casa de meu pai, para que eternamente fosse rei sobre Israel; porque a Judá escolheu por soberano, e a casa de meu pai na casa de Judá; e entre os filhos de meu pai se agradou de mim para me fazer reinar sobre todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 5, 'E, de todos os meus filhos (porque muitos filhos me deu o Senhor), escolheu ele o meu filho Salomão para se assentar no trono do reino do Senhor sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 6, 'E me disse: Teu filho Salomão, ele edificará a minha casa e os meus átrios; porque o escolhi para filho, e eu lhe serei por pai.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 7, 'E estabelecerei o seu reino para sempre, se perseverar em cumprir os meus mandamentos e os meus juízos, como até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 8, 'Agora, pois, perante os olhos de todo o Israel, a congregação do Senhor, e perante os ouvidos de nosso Deus, guardai e buscai todos os mandamentos do Senhor vosso Deus, para que possuais esta boa terra, e a façais herdar a vossos filhos depois de vós, para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 9, 'E tu, meu filho Salomão, conhece o Deus de teu pai, e serve-o com um coração perfeito e com uma alma voluntária; porque esquadrinha o Senhor todos os corações, e entende todas as imaginações dos pensamentos; se o buscares, será achado de ti; porém, se o deixares, rejeitar-te-á para sempre.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 10, 'Olha, pois, agora, porque o Senhor te escolheu para edificares uma casa para o santuário; esforça-te, e faze a obra.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 11, 'E deu Davi a Salomão, seu filho, a planta do alpendre com as suas casas, e as suas tesourarias, e os seus cenáculos, e as suas recâmaras interiores, como também da casa do propiciatório.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 12, 'E também a planta de tudo quanto tinha em mente, a saber: dos átrios da casa do Senhor, e de todas as câmaras ao redor, para os tesouros da casa de Deus, e para os tesouros das coisas sagradas;', 2, CURRENT_TIMESTAMP, false),
(13, 28, 13, 'E para as turmas dos sacerdotes, e para os levitas, e para toda a obra do ministério da casa do Senhor, e para todos os utensílios do ministério da casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 14, 'E deu ouro, segundo o peso do ouro, para todos os utensílios de cada ministério; também a prata, por peso, para todos os utensílios de prata, para todos os utensílios de cada ministério.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 15, 'E o peso para os castiçais de ouro, e suas candeias de ouro segundo o peso de cada castiçal e as suas candeias; também para os castiçais de prata, segundo o peso do castiçal e as suas candeias, segundo o uso de cada castiçal.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 16, 'Também deu o ouro por peso para as mesas da proposição, para cada mesa; como também a prata para as mesas de prata.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 17, 'E ouro puro para os garfos, e para as bacias, e para os jarros, e para as taças de ouro, para cada taça seu peso; como também para as taças de prata, para cada taça seu peso.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 18, 'E para o altar do incenso, ouro purificado, por seu peso; como também o ouro para o modelo do carro, a saber, dos querubins, que haviam de estender as asas, e cobrir a arca da aliança do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 19, 'Tudo isto, disse Davi, fez-me entender o Senhor, por escrito da sua mão, a saber, todas as obras desta planta.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 20, 'E disse Davi a Salomão seu filho: Esforça-te e tem bom ânimo, e faze a obra; não temas, nem te apavores; porque o Senhor Deus, meu Deus, há de ser contigo; não te deixará, nem te desamparará, até que acabes toda a obra do serviço da casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(13, 28, 21, 'E eis que aí tens as turmas dos sacerdotes e dos levitas para todo o ministério da casa de Deus; estão também contigo, para toda a obra, voluntários com sabedoria de toda a espécie para todo o ministério; como também todos os príncipes, e todo o povo, para todos os teus mandados.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 1, 'Disse mais o rei Davi a toda a congregação: Salomão, meu filho, a quem só Deus escolheu, é ainda moço e tenro, e esta obra é grande; porque não é o palácio para homem, mas para o SENHOR Deus.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 2, 'Eu, pois, com todas as minhas forças já tenho preparado para a casa de meu Deus ouro para as obras de ouro, e prata para as de prata, e cobre para as de cobre, ferro para as de ferro e madeira para as de madeira, pedras de ônix, e as de engaste, e pedras ornamentais, e pedras de diversas cores, e toda a sorte de pedras preciosas, e pedras de mármore em abundância.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 3, 'E ainda, porque tenho afeto à casa de meu Deus, o ouro e prata particular que tenho eu dou para a casa do meu Deus, afora tudo quanto tenho preparado para a casa do santuário:', 2, CURRENT_TIMESTAMP, false),
(13, 29, 4, 'Três mil talentos de ouro de Ofir; e sete mil talentos de prata purificada, para cobrir as paredes das casas.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 5, 'Ouro para os objetos de ouro, e prata para os de prata; e para toda a obra de mão dos artífices. Quem, pois, está disposto a encher a sua mão, para oferecer hoje voluntariamente ao Senhor?', 2, CURRENT_TIMESTAMP, false),
(13, 29, 6, 'Então os chefes dos pais, e os príncipes das tribos de Israel, e os capitães de mil e de cem, até os chefes da obra do rei, voluntariamente contribuíram.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 7, 'E deram para o serviço da casa de Deus cinco mil talentos de ouro, e dez mil dracmas, e dez mil talentos de prata, e dezoito mil talentos de cobre, e cem mil talentos de ferro.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 8, 'E os que possuíam pedras preciosas, deram-nas para o tesouro da casa do Senhor, a cargo de Jeiel o gersonita.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 9, 'E o povo se alegrou porque contribuíram voluntariamente; porque, com coração perfeito, voluntariamente deram ao Senhor; e também o rei Davi se alegrou com grande alegria.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 10, 'Por isso Davi louvou ao Senhor na presença de toda a congregação; e disse Davi: Bendito és tu, Senhor Deus de Israel, nosso pai, de eternidade em eternidade.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 11, 'Tua é, Senhor, a magnificência, e o poder, e a honra, e a vitória, e a majestade; porque teu é tudo quanto há nos céus e na terra; teu é, Senhor, o reino, e tu te exaltaste por cabeça sobre todos.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 12, 'E riquezas e glória vêm de diante de ti, e tu dominas sobre tudo, e na tua mão há força e poder; e na tua mão está o engrandecer e o dar força a tudo.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 13, 'Agora, pois, ó Deus nosso, graças te damos, e louvamos o nome da tua glória.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 14, 'Porque quem sou eu, e quem é o meu povo, para que pudéssemos oferecer voluntariamente coisas semelhantes? Porque tudo vem de ti, e do que é teu to damos.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 15, 'Porque somos estrangeiros diante de ti, e peregrinos como todos os nossos pais; como a sombra são os nossos dias sobre a terra, e sem ti não há esperança.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 16, 'Senhor, nosso Deus, toda esta abundância, que preparamos, para te edificar uma casa ao teu santo nome, vem da tua mão, e é toda tua.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 17, 'E bem sei eu, Deus meu, que tu provas os corações, e que da sinceridade te agradas; eu também na sinceridade de meu coração voluntariamente dei todas estas coisas; e agora vi com alegria que o teu povo, que se acha aqui, voluntariamente te deu.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 18, 'Senhor Deus de Abraão, Isaque, e Israel, nossos pais, conserva isto para sempre no intento dos pensamentos do coração de teu povo; e encaminha o seu coração para ti.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 19, 'E a Salomão, meu filho, dá um coração perfeito, para guardar os teus mandamentos, os teus testemunhos, e os teus estatutos; e para fazer tudo, e para edificar este palácio que tenho preparado.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 20, 'Então disse Davi a toda a congregação: Agora louvai ao Senhor vosso Deus. Então toda a congregação louvou ao Senhor Deus de seus pais, e inclinaram-se, e prostraram-se perante o Senhor, e o rei.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 21, 'E ao outro dia imolaram sacrifícios ao Senhor, e ofereceram holocaustos ao Senhor, mil bezerros, mil carneiros, mil cordeiros, com as suas libações; e sacrifícios em abundância por todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 22, 'E comeram e beberam naquele dia perante o Senhor, com grande gozo; e a segunda vez fizeram rei a Salomão filho de Davi, e o ungiram ao Senhor por líder, e a Zadoque por sacerdote.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 23, 'Assim Salomão se assentou no trono do Senhor, como rei, em lugar de Davi seu pai, e prosperou; e todo o Israel lhe obedecia.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 24, 'E todos os príncipes, e os grandes, e até todos os filhos do rei Davi, se submeteram ao rei Salomão.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 25, 'E o Senhor magnificou a Salomão grandissimamente, perante os olhos de todo o Israel; e deu-lhe majestade real, qual antes dele não teve nenhum rei em Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 26, 'Assim Davi, filho de Jessé, reinou sobre todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 27, 'E foram os dias que reinou sobre Israel, quarenta anos; em Hebrom reinou sete anos, e em Jerusalém reinou trinta e três.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 28, 'E morreu numa boa velhice, cheio de dias, riquezas e glória; e Salomão, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(13, 29, 29, 'Os atos, pois, do rei Davi, assim os primeiros como os últimos, eis que estão escritos nas crônicas de Samuel, o vidente, e nas crônicas do profeta Natã, e nas crônicas de Gade, o vidente,', 2, CURRENT_TIMESTAMP, false),
(13, 29, 30, 'Juntamente com todo o seu reinado e o seu poder; e os tempos que passaram sobre ele, e sobre Israel, e sobre todos os reinos daquelas terras.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 1, 'O que era desde o princípio, o que ouvimos, o que vimos com os nossos olhos, o que temos contemplado, e as nossas mãos tocaram da Palavra da vida', 2, CURRENT_TIMESTAMP, false),
(62, 1, 2, '(Porque a vida foi manifestada, e nós a vimos, e testificamos dela, e vos anunciamos a vida eterna, que estava com o Pai, e nos foi manifestada);', 2, CURRENT_TIMESTAMP, false),
(62, 1, 3, 'O que vimos e ouvimos, isso vos anunciamos, para que também tenhais comunhão conosco; e a nossa comunhão é com o Pai, e com seu Filho Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 4, 'Estas coisas vos escrevemos, para que o vosso gozo se cumpra.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 5, 'E esta é a mensagem que dele ouvimos, e vos anunciamos: que Deus é luz, e não há nele trevas nenhumas.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 6, 'Se dissermos que temos comunhão com ele, e andarmos em trevas, mentimos, e não praticamos a verdade.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 7, 'Mas, se andarmos na luz, como ele na luz está, temos comunhão uns com os outros, e o sangue de Jesus Cristo, seu Filho, nos purifica de todo o pecado.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 8, 'Se dissermos que não temos pecado, enganamo-nos a nós mesmos, e não há verdade em nós.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 9, 'Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados, e nos purificar de toda a injustiça.', 2, CURRENT_TIMESTAMP, false),
(62, 1, 10, 'Se dissermos que não pecamos, fazemo-lo mentiroso, e a sua palavra não está em nós.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 1, 'Meus filhinhos, estas coisas vos escrevo, para que não pequeis; e, se alguém pecar, temos um Advogado para com o Pai, Jesus Cristo, o justo.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 2, 'E ele é a propiciação pelos nossos pecados, e não somente pelos nossos, mas também pelos de todo o mundo.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 3, 'E nisto sabemos que o conhecemos: se guardarmos os seus mandamentos.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 4, 'Aquele que diz: Eu conheço-o, e não guarda os seus mandamentos, é mentiroso, e nele não está a verdade.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 5, 'Mas qualquer que guarda a sua palavra, o amor de Deus está nele verdadeiramente aperfeiçoado; nisto conhecemos que estamos nele.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 6, 'Aquele que diz que está nele, também deve andar como ele andou.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 7, 'Irmãos, não vos escrevo mandamento novo, mas o mandamento antigo, que desde o princípio tivestes. Este mandamento antigo é a palavra que desde o princípio ouvistes.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 8, 'Outra vez vos escrevo um mandamento novo, que é verdadeiro nele e em vós; porque vão passando as trevas, e já a verdadeira luz ilumina.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 9, 'Aquele que diz que está na luz, e odeia a seu irmão, até agora está em trevas.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 10, 'Aquele que ama a seu irmão está na luz, e nele não há escândalo.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 11, 'Mas aquele que odeia a seu irmão está em trevas, e anda em trevas, e não sabe para onde deva ir; porque as trevas lhe cegaram os olhos.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 12, 'Filhinhos, escrevo-vos, porque pelo seu nome vos são perdoados os pecados.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 13, 'Pais, escrevo-vos, porque conhecestes aquele que é desde o princípio. Jovens, escrevo-vos, porque vencestes o maligno. Eu vos escrevo, filhos, porque conhecestes o Pai.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 14, 'Eu vos escrevi, pais, porque já conhecestes aquele que é desde o princípio. Eu vos escrevi, jovens, porque sois fortes, e a palavra de Deus está em vós, e já vencestes o maligno.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 15, 'Não ameis o mundo, nem o que no mundo há. Se alguém ama o mundo, o amor do Pai não está nele.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 16, 'Porque tudo o que há no mundo, a concupiscência da carne, a concupiscência dos olhos e a soberba da vida, não é do Pai, mas do mundo.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 17, 'E o mundo passa, e a sua concupiscência; mas aquele que faz a vontade de Deus permanece para sempre.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 18, 'Filhinhos, é já a última hora; e, como ouvistes que vem o anticristo, também agora muitos se têm feito anticristos, por onde conhecemos que é já a última hora.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 19, 'Saíram de nós, mas não eram de nós; porque, se fossem de nós, ficariam conosco; mas isto é para que se manifestasse que não são todos de nós.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 20, 'E vós tendes a unção do Santo, e sabeis todas as coisas.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 21, 'Não vos escrevi porque não soubésseis a verdade, mas porque a sabeis, e porque nenhuma mentira vem da verdade.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 22, 'Quem é o mentiroso, senão aquele que nega que Jesus é o Cristo? É o anticristo esse mesmo que nega o Pai e o Filho.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 23, 'Qualquer que nega o Filho, também não tem o Pai; mas aquele que confessa o Filho, tem também o Pai.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 24, 'Portanto, o que desde o princípio ouvistes permaneça em vós. Se em vós permanecer o que desde o princípio ouvistes, também permanecereis no Filho e no Pai.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 25, 'E esta é a promessa que ele nos fez: a vida eterna.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 26, 'Estas coisas vos escrevi acerca dos que vos enganam.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 27, 'E a unção que vós recebestes dele, fica em vós, e não tendes necessidade de que alguém vos ensine; mas, como a sua unção vos ensina todas as coisas, e é verdadeira, e não é mentira, como ela vos ensinou, assim nele permanecereis.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 28, 'E agora, filhinhos, permanecei nele; para que, quando ele se manifestar, tenhamos confiança, e não sejamos confundidos por ele na sua vinda.', 2, CURRENT_TIMESTAMP, false),
(62, 2, 29, 'Se sabeis que ele é justo, sabeis que todo aquele que pratica a justiça é nascido dele.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 1, 'Vede quão grande amor nos tem concedido o Pai, que fôssemos chamados filhos de Deus. Por isso o mundo não nos conhece; porque não o conhece a ele.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 2, 'Amados, agora somos filhos de Deus, e ainda não é manifestado o que havemos de ser. Mas sabemos que, quando ele se manifestar, seremos semelhantes a ele; porque assim como é o veremos.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 3, 'E qualquer que nele tem esta esperança purifica-se a si mesmo, como também ele é puro.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 4, 'Qualquer que comete pecado, também comete iniqüidade; porque o pecado é iniqüidade.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 5, 'E bem sabeis que ele se manifestou para tirar os nossos pecados; e nele não há pecado.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 6, 'Qualquer que permanece nele não peca; qualquer que peca não o viu nem o conheceu.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 7, 'Filhinhos, ninguém vos engane. Quem pratica justiça é justo, assim como ele é justo.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 8, 'Quem comete o pecado é do diabo; porque o diabo peca desde o princípio. Para isto o Filho de Deus se manifestou: para desfazer as obras do diabo.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 9, 'Qualquer que é nascido de Deus não comete pecado; porque a sua semente permanece nele; e não pode pecar, porque é nascido de Deus.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 10, 'Nisto são manifestos os filhos de Deus, e os filhos do diabo. Qualquer que não pratica a justiça, e não ama a seu irmão, não é de Deus.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 11, 'Porque esta é a mensagem que ouvistes desde o princípio: que nos amemos uns aos outros.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 12, 'Não como Caim, que era do maligno, e matou a seu irmão. E por que causa o matou? Porque as suas obras eram más e as de seu irmão justas.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 13, 'Meus irmãos, não vos maravilheis, se o mundo vos odeia.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 14, 'Nós sabemos que passamos da morte para a vida, porque amamos os irmãos. Quem não ama a seu irmão permanece na morte.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 15, 'Qualquer que odeia a seu irmão é homicida. E vós sabeis que nenhum homicida tem a vida eterna permanecendo nele.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 16, 'Conhecemos o amor nisto: que ele deu a sua vida por nós, e nós devemos dar a vida pelos irmãos.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 17, 'Quem, pois, tiver bens do mundo, e, vendo o seu irmão necessitado, lhe cerrar as suas entranhas, como estará nele o amor de Deus?', 2, CURRENT_TIMESTAMP, false),
(62, 3, 18, 'Meus filhinhos, não amemos de palavra, nem de língua, mas por obra e em verdade.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 19, 'E nisto conhecemos que somos da verdade, e diante dele asseguraremos nossos corações;', 2, CURRENT_TIMESTAMP, false),
(62, 3, 20, 'Sabendo que, se o nosso coração nos condena, maior é Deus do que o nosso coração, e conhece todas as coisas.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 21, 'Amados, se o nosso coração não nos condena, temos confiança para com Deus;', 2, CURRENT_TIMESTAMP, false),
(62, 3, 22, 'E qualquer coisa que lhe pedirmos, dele a receberemos, porque guardamos os seus mandamentos, e fazemos o que é agradável à sua vista.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 23, 'E o seu mandamento é este: que creiamos no nome de seu Filho Jesus Cristo, e nos amemos uns aos outros, segundo o seu mandamento.', 2, CURRENT_TIMESTAMP, false),
(62, 3, 24, 'E aquele que guarda os seus mandamentos nele está, e ele nele. E nisto conhecemos que ele está em nós, pelo Espírito que nos tem dado.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 1, 'Pedro, apóstolo de Jesus Cristo, aos estrangeiros dispersos no Ponto, Galácia, Capadócia, Ásia e Bitínia;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 2, 'Eleitos segundo a presciência de Deus Pai, em santificação do Espírito, para a obediência e aspersão do sangue de Jesus Cristo: Graça e paz vos sejam multiplicadas.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo que, segundo a sua grande misericórdia, nos gerou de novo para uma viva esperança, pela ressurreição de Jesus Cristo dentre os mortos,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 4, 'Para uma herança incorruptível, incontaminável, e que não se pode murchar, guardada nos céus para vós,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 5, 'Que mediante a fé estais guardados na virtude de Deus para a salvação, já prestes para se revelar no último tempo,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 6, 'Em que vós grandemente vos alegrais, ainda que agora importa, sendo necessário, que estejais por um pouco contristados com várias tentações,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 7, 'Para que a prova da vossa fé, muito mais preciosa do que o ouro que perece e é provado pelo fogo, se ache em louvor, e honra, e glória, na revelação de Jesus Cristo;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 8, 'Ao qual, não o havendo visto, amais; no qual, não o vendo agora, mas crendo, vos alegrais com gozo inefável e glorioso;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 9, 'Alcançando o fim da vossa fé, a salvação das vossas almas.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 10, 'Da qual salvação inquiriram e trataram diligentemente os profetas que profetizaram da graça que vos foi dada,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 11, 'Indagando que tempo ou que ocasião de tempo o Espírito de Cristo, que estava neles, indicava, anteriormente testificando os sofrimentos que a Cristo haviam de vir, e a glória que se lhes havia de seguir.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 12, 'Aos quais foi revelado que, não para si mesmos, mas para nós, eles ministravam estas coisas que agora vos foram anunciadas por aqueles que, pelo Espírito Santo enviado do céu, vos pregaram o evangelho; para as quais coisas os anjos desejam bem atentar.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 13, 'Portanto, cingindo os lombos do vosso entendimento, sede sóbrios, e esperai inteiramente na graça que se vos ofereceu na revelação de Jesus Cristo;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 14, 'Como filhos obedientes, não vos conformando com as concupiscências que antes havia em vossa ignorância;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 15, 'Mas, como é santo aquele que vos chamou, sede vós também santos em toda a vossa maneira de viver;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 16, 'Porquanto está escrito: Sede santos, porque eu sou santo.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 17, 'E, se invocais por Pai aquele que, sem acepção de pessoas, julga segundo a obra de cada um, andai em temor, durante o tempo da vossa peregrinação,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 18, 'Sabendo que não foi com coisas corruptíveis, como prata ou ouro, que fostes resgatados da vossa vã maneira de viver que por tradição recebestes dos vossos pais,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 19, 'Mas com o precioso sangue de Cristo, como de um cordeiro imaculado e incontaminado,', 2, CURRENT_TIMESTAMP, false),
(60, 1, 20, 'O qual, na verdade, em outro tempo foi conhecido, ainda antes da fundação do mundo, mas manifestado nestes últimos tempos por amor de vós;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 21, 'E por ele credes em Deus, que o ressuscitou dentre os mortos, e lhe deu glória, para que a vossa fé e esperança estivessem em Deus;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 22, 'Purificando as vossas almas pelo Espírito na obediência à verdade, para o amor fraternal, não fingido; amai-vos ardentemente uns aos outros com um coração puro;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 23, 'Sendo de novo gerados, não de semente corruptível, mas da incorruptível, pela palavra de Deus, viva, e que permanece para sempre.', 2, CURRENT_TIMESTAMP, false),
(60, 1, 24, 'Porque toda a carne é como a erva,e toda a glória do homem como a flor da erva.Secou-se a erva, e caiu a sua flor;', 2, CURRENT_TIMESTAMP, false),
(60, 1, 25, 'Mas a palavra do Senhor permanece para sempre.E esta é a palavra que entre vós foi evangelizada.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 1, 'Deixando, pois, toda a malícia, e todo o engano, e fingimentos, e invejas, e todas as murmurações,', 2, CURRENT_TIMESTAMP, false),
(60, 2, 2, 'Desejai afetuosamente, como meninos novamente nascidos, o leite racional, não falsificado, para que por ele vades crescendo;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 3, 'Se é que já provastes que o Senhor é benigno;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 4, 'E, chegando-vos para ele, pedra viva, reprovada, na verdade, pelos homens, mas para com Deus eleita e preciosa,', 2, CURRENT_TIMESTAMP, false),
(60, 2, 5, 'Vòs também, como pedras vivas, sois edificados casa espiritual e sacerdòcio santo, para oferecer sacrifícios espirituais agradáveis a Deus por Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 6, 'Por isso também na Escritura se contém:Eis que ponho em Sião a pedra principal da esquina, eleita e preciosa;e quem nela crer não será confundido.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 7, 'E assim para vòs, os que credes, é preciosa, mas, para os rebeldes,a pedra que os edificadores reprovaram,essa foi a principal da esquina,', 2, CURRENT_TIMESTAMP, false),
(60, 2, 8, 'E uma pedra de tropeço e rocha de escândalo,para aqueles que tropeçam na palavra, sendo desobedientes; para o que também foram destinados.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 9, 'Mas vòs sois a geração eleita, o sacerdòcio real, a nação santa, o povo adquirido, para que anuncieis as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 10, 'Vós, que em outro tempo não éreis povo, mas agora sois povo de Deus; que não tínheis alcançado misericórdia, mas agora alcançastes misericórdia.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 11, 'Amados, peço-vos, como a peregrinos e forasteiros, que vos abstenhais das concupiscências carnais, que combatem contra a alma;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 12, 'Tendo o vosso viver honesto entre os gentios; para que, naquilo em que falam mal de vós, como de malfeitores, glorifiquem a Deus no dia da visitação, pelas boas obras que em vós observem.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 13, 'Sujeitai-vos, pois, a toda a ordenação humana por amor do Senhor; quer ao rei, como superior;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 14, 'Quer aos governadores, como por ele enviados para castigo dos malfeitores, e para louvor dos que fazem o bem.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 15, 'Porque assim é a vontade de Deus, que, fazendo bem, tapeis a boca à ignorância dos homens insensatos;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 16, 'Como livres, e não tendo a liberdade por cobertura da malícia, mas como servos de Deus.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 17, 'Honrai a todos. Amai a fraternidade. Temei a Deus. Honrai ao rei.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 18, 'Vós, servos, sujeitai-vos com todo o temor aos senhores, não somente aos bons e humanos, mas também aos maus.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 19, 'Porque é coisa agradável, que alguém, por causa da consciência para com Deus, sofra agravos, padecendo injustamente.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 20, 'Porque, que glória será essa, se, pecando, sois esbofeteados e sofreis? Mas se, fazendo o bem, sois afligidos e o sofreis, isso é agradável a Deus.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 21, 'Porque para isto sois chamados; pois também Cristo padeceu por nós, deixando-nos o exemplo, para que sigais as suas pisadas.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 22, 'O qual não cometeu pecado, nem na sua boca se achou engano.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 23, 'O qual, quando o injuriavam, não injuriava, e quando padecia não ameaçava, mas entregava-se àquele que julga justamente;', 2, CURRENT_TIMESTAMP, false),
(60, 2, 24, 'Levando ele mesmo em seu corpo os nossos pecados sobre o madeiro, para que, mortos para os pecados, pudéssemos viver para a justiça; e pelas suas feridas fostes sarados.', 2, CURRENT_TIMESTAMP, false),
(60, 2, 25, 'Porque éreis como ovelhas desgarradas; mas agora tendes voltado ao Pastor e Bispo das vossas almas.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 1, 'Semelhantemente, vós, mulheres, sede sujeitas aos vossos próprios maridos; para que também, se alguns não obedecem à palavra, pelo porte de suas mulheres sejam ganhos sem palavra;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 2, 'Considerando a vossa vida casta, em temor.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 3, 'O enfeite delas não seja o exterior, no frisado dos cabelos, no uso de jóias de ouro, na compostura dos vestidos;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 4, 'Mas o homem encoberto no coração; no incorruptível traje de um espírito manso e quieto, que é precioso diante de Deus.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 5, 'Porque assim se adornavam também antigamente as santas mulheres que esperavam em Deus, e estavam sujeitas aos seus próprios maridos;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 6, 'Como Sara obedecia a Abraão, chamando-lhe senhor; da qual vós sois filhas, fazendo o bem, e não temendo nenhum espanto.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 7, 'Igualmente vós, maridos, coabitai com elas com entendimento, dando honra à mulher, como vaso mais fraco; como sendo vós os seus co-herdeiros da graça da vida; para que não sejam impedidas as vossas orações.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 8, 'E, finalmente, sede todos de um mesmo sentimento, compassivos, amando os irmãos, entranhavelmente misericordiosos e afáveis.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 9, 'Não tornando mal por mal, ou injúria por injúria; antes, pelo contrário, bendizendo; sabendo que para isto fostes chamados, para que por herança alcanceis a bênção.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 10, 'Porque Quem quer amar a vida, E ver os dias bons, Refreie a sua língua do mal, E os seus lábios não falem engano.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 11, 'Aparte-se do mal, e faça o bem; Busque a paz, e siga-a.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 12, 'Porque os olhos do Senhor estão sobre os justos, E os seus ouvidos atentos às suas orações; Mas o rosto do Senhor é contra os que fazem o mal.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 13, 'E qual é aquele que vos fará mal, se fordes seguidores do bem?', 2, CURRENT_TIMESTAMP, false),
(60, 3, 14, 'Mas também, se padecerdes por amor da justiça, sois bemaventurados. E não temais com medo deles, nem vos turbeis;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 15, 'Antes, santificai ao Senhor Deus em vossos corações; e estai sempre preparados para responder com mansidão e temor a qualquer que vos pedir a razão da esperança que há em vós,', 2, CURRENT_TIMESTAMP, false),
(60, 3, 16, 'Tendo uma boa consciência, para que, naquilo em que falam mal de vós, como de malfeitores, fiquem confundidos os que blasfemam do vosso bom porte em Cristo.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 17, 'Porque melhor é que padeçais fazendo bem (se a vontade de Deus assim o quer), do que fazendo mal.', 2, CURRENT_TIMESTAMP, false),
(60, 3, 18, 'Porque também Cristo padeceu uma vez pelos pecados, o justo pelos injustos, para levar-nos a Deus; mortificado, na verdade, na carne, mas vivificado pelo Espírito;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 19, 'No qual também foi, e pregou aos espíritos em prisão;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 20, 'Os quais noutro tempo foram rebeldes, quando a longanimidade de Deus esperava nos dias de Noé, enquanto se preparava a arca; na qual poucas (isto é, oito) almas se salvaram pela água;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 21, 'Que também, como uma verdadeira figura, agora vos salva, o batismo, não do despojamento da imundícia da carne, mas da indagação de uma boa consciência para com Deus, pela ressurreição de Jesus Cristo;', 2, CURRENT_TIMESTAMP, false),
(60, 3, 22, 'O qual está à destra de Deus, tendo subido ao céu, havendo-se-lhe sujeitado os anjos, e as autoridades, e as potências.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 1, 'Ora, pois, já que Cristo padeceu por nós na carne, armai-vos também vós com este mesmo pensamento, que aquele que padeceu na carne já cessou do pecado;', 2, CURRENT_TIMESTAMP, false),
(60, 4, 2, 'Para que, no tempo que vos resta na carne, não vivais mais segundo as concupiscências dos homens, mas segundo a vontade de Deus.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 3, 'Porque é bastante que no tempo passado da vida fizéssemos a vontade dos gentios, andando em dissoluções, concupiscências, borrachices, glutonarias, bebedices e abomináveis idolatrias;', 2, CURRENT_TIMESTAMP, false),
(60, 4, 4, 'E acham estranho não correrdes com eles no mesmo desenfreamento de dissolução, blasfemando de vós.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 5, 'Os quais hão de dar conta ao que está preparado para julgar os vivos e os mortos.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 6, 'Porque por isto foi pregado o evangelho também aos mortos, para que, na verdade, fossem julgados segundo os homens na carne, mas vivessem segundo Deus em espírito;', 2, CURRENT_TIMESTAMP, false),
(60, 4, 7, 'E já está próximo o fim de todas as coisas; portanto sede sóbrios e vigiai em oração.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 8, 'Mas, sobretudo, tende ardente amor uns para com os outros; porque o amor cobrirá a multidão de pecados.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 9, 'Sendo hospitaleiros uns para com os outros, sem murmurações,', 2, CURRENT_TIMESTAMP, false),
(60, 4, 10, 'Cada um administre aos outros o dom como o recebeu, como bons despenseiros da multiforme graça de Deus.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 11, 'Se alguém falar, fale segundo as palavras de Deus; se alguém administrar, administre segundo o poder que Deus dá; para que em tudo Deus seja glorificado por Jesus Cristo, a quem pertence a glória e poder para todo o sempre. Amém.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 12, 'Amados, não estranheis a ardente prova que vem sobre vós para vos tentar, como se coisa estranha vos acontecesse;', 2, CURRENT_TIMESTAMP, false),
(60, 4, 13, 'Mas alegrai-vos no fato de serdes participantes das aflições de Cristo, para que também na revelação da sua glória vos regozijeis e alegreis.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 14, 'Se pelo nome de Cristo sois vituperados, bem-aventurados sois, porque sobre vós repousa o Espírito da glória e de Deus; quanto a eles, é ele, sim, blasfemado, mas quanto a vós, é glorificado.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 15, 'Que nenhum de vós padeça como homicida, ou ladrão, ou malfeitor, ou como o que se entremete em negócios alheios;', 2, CURRENT_TIMESTAMP, false),
(60, 4, 16, 'Mas, se padece como cristão, não se envergonhe, antes glorifique a Deus nesta parte.', 2, CURRENT_TIMESTAMP, false),
(60, 4, 17, 'Porque já é tempo que comece o julgamento pela casa de Deus; e, se primeiro começa por nós, qual será o fim daqueles que são desobedientes ao evangelho de Deus?', 2, CURRENT_TIMESTAMP, false),
(60, 4, 18, 'E, se o justo apenas se salva, onde aparecerá o ímpio e o pecador?', 2, CURRENT_TIMESTAMP, false),
(60, 4, 19, 'Portanto também os que padecem segundo a vontade de Deus encomendem-lhe as suas almas, como ao fiel Criador, fazendo o bem.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 1, 'Aos presbíteros, que estão entre vós, admoesto eu, que sou também presbítero com eles, e testemunha das aflições de Cristo, e participante da glória que se há de revelar:', 2, CURRENT_TIMESTAMP, false),
(60, 5, 2, 'Apascentai o rebanho de Deus, que está entre vós, tendo cuidado dele, não por força, mas voluntariamente; nem por torpe ganância, mas de ânimo pronto;', 2, CURRENT_TIMESTAMP, false),
(60, 5, 3, 'Nem como tendo domínio sobre a herança de Deus, mas servindo de exemplo ao rebanho.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 4, 'E, quando aparecer o Sumo Pastor, alcançareis a incorruptível coroa da glória.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 5, 'Semelhantemente vós jovens, sede sujeitos aos anciãos; e sede todos sujeitos uns aos outros, e revesti-vos de humildade, porque Deus resiste aos soberbos, mas dá graça aos humildes.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 6, 'Humilhai-vos, pois, debaixo da potente mão de Deus, para que a seu tempo vos exalte;', 2, CURRENT_TIMESTAMP, false),
(60, 5, 7, 'Lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 8, 'Sede sóbrios; vigiai; porque o diabo, vosso adversário, anda em derredor, bramando como leão, buscando a quem possa tragar;', 2, CURRENT_TIMESTAMP, false),
(60, 5, 9, 'Ao qual resisti firmes na fé, sabendo que as mesmas aflições se cumprem entre os vossos irmãos no mundo.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 10, 'E o Deus de toda a graça, que em Cristo Jesus nos chamou à sua eterna glória, depois de havemos padecido um pouco, ele mesmo vos aperfeiçoe, confirme, fortifique e estabeleça.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 11, 'A ele seja a glória e o poderio para todo o sempre. Amém.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 12, 'Por Silvano, vosso fiel irmão, como cuido, escrevi brevemente, exortando e testificando que esta é a verdadeira graça de Deus, na qual estais firmes.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 13, 'A vossa co-eleita em babilônia vos saúda, e meu filho Marcos.', 2, CURRENT_TIMESTAMP, false),
(60, 5, 14, 'Saudai-vos uns aos outros com ósculo de amor. Paz seja com todos vós que estais em Cristo Jesus. Amém.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 1, 'Sendo, pois, o rei Davi já velho, e entrado em dias, cobriam-no de roupas, porém não se aquecia.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 2, 'Então disseram-lhe os seus servos: Busquem para o rei meu senhor uma moça virgem, que esteja perante o rei, e tenha cuidado dele; e durma no seu seio, para que o rei meu senhor se aqueça.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 3, 'E buscaram por todos os termos de Israel uma moça formosa, e acharam a Abisague, sunamita; e a trouxeram ao rei.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 4, 'E era a moça sobremaneira formosa; e tinha cuidado do rei, e o servia; porém o rei não a conheceu.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 5, 'Então Adonias, filho de Hagite, se levantou, dizendo: Eu reinarei. E preparou carros, e cavaleiros, e cinqüenta homens, que corressem adiante dele.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 6, 'E nunca seu pai o tinha contrariado, dizendo: Por que fizeste assim? E era ele também muito formoso de parecer; e Hagite o tivera depois de Absalão.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 7, 'E tinha entendimento com Joabe, filho de Zeruia, e com Abiatar o sacerdote; os quais o ajudavam, seguindo a Adonias.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 8, 'Porém Zadoque, o sacerdote, e Benaia, filho de Joiada, e Natã, o profeta, e Simei, e Rei, e os poderosos que Davi tinha, não estavam com Adonias.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 9, 'E matou Adonias ovelhas, e vacas, e animais cevados, junto à pedra de Zoelete, que está perto da fonte de Rogel; e convidou a todos os seus irmãos, os filhos do rei, e a todos os homens de Judá, servos do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 10, 'Porém a Natã, o profeta, e a Benaia, e aos poderosos, e a Salomão, seu irmão, não convidou.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 11, 'Então falou Natã a Bate-Seba, mãe de Salomão, dizendo: Não ouviste que Adonias, filho de Hagite, reina? E que nosso senhor Davi não o sabe?', 2, CURRENT_TIMESTAMP, false),
(11, 1, 12, 'Vem, pois, agora, e deixa-me dar-te um conselho, para que salves a tua vida, e a de Salomão teu filho.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 13, 'Vai, e chega ao rei Davi, e dize-lhe: Não juraste tu, rei senhor meu, à tua serva, dizendo: Certamente teu filho Salomão reinará depois de mim, e ele se assentará no meu trono? Por que, pois, reina Adonias?', 2, CURRENT_TIMESTAMP, false),
(11, 1, 14, 'Eis que, estando tu ainda aí falando com o rei, eu também entrarei depois de ti, e confirmarei as tuas palavras.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 15, 'E foi Bate-Seba ao rei na sua câmara; e o rei era muito velho; e Abisague, a sunamita, servia ao rei.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 16, 'E Bate-Seba inclinou a cabeça, e se prostrou perante o rei; e disse o rei: Que tens?', 2, CURRENT_TIMESTAMP, false),
(11, 1, 17, 'E ela lhe disse: Senhor meu, tu juraste à tua serva pelo Senhor teu Deus, dizendo: Salomão, teu filho, reinará depois de mim, e ele se assentará no meu trono.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 18, 'E agora eis que Adonias reina; e tu, ó rei meu senhor, não o sabes.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 19, 'E matou vacas, e animais cevados, e ovelhas em abundância, e convidou a todos os filhos do rei, e a Abiatar, o sacerdote, e a Joabe, capitão do exército, mas a teu servo Salomão não convidou.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 20, 'Porém, ó rei meu senhor, os olhos de todo o Israel estão sobre ti, para que lhe declares quem se assentará sobre o trono do rei meu senhor, depois dele.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 21, 'De outro modo sucederá que, quando o rei meu senhor dormir com seus pais, eu e Salomão meu filho seremos os culpados.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 22, 'E, estando ela ainda falando com o rei, eis que entra o profeta Natã.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 23, 'E o fizeram saber ao rei, dizendo: Eis aí está o profeta Natã. E entrou à presença do rei, e prostrou-se diante dele com o rosto em terra.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 24, 'E disse Natã: Ó rei meu senhor, disseste tu: Adonias reinará depois de mim, e ele se assentará sobre o meu trono?', 2, CURRENT_TIMESTAMP, false),
(11, 1, 25, 'Porque hoje desceu, e matou vacas, e animais cevados, e ovelhas em abundância, e convidou a todos os filhos do rei e aos capitães do exército, e a Abiatar, o sacerdote, e eis que estão comendo e bebendo perante ele; e dizem: Viva o rei Adonias.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 26, 'Porém a mim, sendo eu teu servo, e a Zadoque, o sacerdote, e a Benaia, filho de Joiada, e a Salomão, teu servo, não convidou.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 27, 'Foi feito isto da parte do rei meu senhor? E não fizeste saber a teu servo quem se assentaria no trono do rei meu senhor depois dele?', 2, CURRENT_TIMESTAMP, false),
(11, 1, 28, 'E respondeu o rei Davi, e disse: Chamai-me a Bate-Seba. E ela entrou à presença do rei; e ficou em pé diante do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 29, 'Então jurou o rei e disse: Vive o Senhor, o qual remiu a minha alma de toda a angústia,', 2, CURRENT_TIMESTAMP, false),
(11, 1, 30, 'Que, como te jurei pelo Senhor Deus de Israel, dizendo: Certamente teu filho Salomão reinará depois de mim, e ele se assentará no meu trono, em meu lugar, assim o farei no dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 31, 'Então Bate-Seba se inclinou com o rosto em terra e se prostrou diante do rei, e disse: Viva o rei Davi meu senhor para sempre.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 32, 'E disse o rei Davi: Chamai-me a Zadoque, o sacerdote, e a Natã, o profeta, e a Benaia, filho de Joiada. E eles entraram à presença do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 33, 'E o rei lhes disse: Tomai convosco os servos de vosso senhor, e fazei subir a meu filho Salomão na mula que é minha; e levai-o a Giom.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 34, 'E Zadoque, o sacerdote, com Natã, o profeta, ali o ungirão rei sobre Israel; então tocareis a trombeta, e direis: Viva o rei Salomão!', 2, CURRENT_TIMESTAMP, false),
(11, 1, 35, 'Então subireis após ele, e virá e se assentará no meu trono, e ele reinará em meu lugar; porque tenho ordenado que ele seja guia sobre Israel e sobre Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 36, 'Então Benaia, filho de Joiada, respondeu ao rei, e disse: Amém; assim o diga o SENHOR Deus do rei meu senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 37, 'Como o SENHOR foi com o rei meu senhor, assim o seja com Salomão, e faça que o seu trono seja maior do que o trono do rei Davi meu senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 38, 'Então desceu Zadoque, o sacerdote, e Natã, o profeta, e Benaia, filho de Joiada, e os quereteus, e os peleteus, e fizeram montar a Salomão na mula do rei Davi, e o levaram a Giom.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 39, 'E Zadoque, o sacerdote, tomou o chifre de azeite do tabernáculo, e ungiu a Salomão; e tocaram a trombeta, e todo o povo disse: Viva o rei Salomão!', 2, CURRENT_TIMESTAMP, false),
(11, 1, 40, 'E todo o povo subiu após ele, e o povo tocava gaitas, e alegrava-se com grande alegria; de maneira que com o seu clamor a terra retiniu.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 41, 'E o ouviu Adonias, e todos os convidados que estavam com ele, que tinham acabado de comer; também Joabe ouviu o sonido das trombetas, e disse: Por que há tal ruído de cidade alvoroçada?', 2, CURRENT_TIMESTAMP, false),
(11, 1, 42, 'Estando ele ainda falando, eis que vem Jônatas, filho de Abiatar, o sacerdote, e disse Adonias: Entra, porque és homem valente, e trarás boas novas.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 43, 'E respondeu Jônatas, e disse a Adonias: Certamente nosso senhor, rei Davi, constituiu rei a Salomão;', 2, CURRENT_TIMESTAMP, false),
(11, 1, 44, 'E o rei enviou com ele a Zadoque, o sacerdote, e a Natã, o profeta, e a Benaia, filho de Joiada, e aos quereteus e aos peleteus; e o fizeram montar na mula do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 45, 'E Zadoque, o sacerdote, e Natã, o profeta, o ungiram rei em Giom, e dali subiram alegres, e a cidade está alvoroçada; este é o clamor que ouviste.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 46, 'E também Salomão está assentado no trono do reino.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 47, 'E também os servos do rei vieram abençoar a nosso senhor, o rei Davi, dizendo: Faça teu Deus que o nome de Salomão seja melhor do que o teu nome; e faça que o seu trono seja maior do que o teu trono. E o rei se inclinou no leito.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 48, 'E também disse o rei assim: Bendito o Senhor Deus de Israel, que hoje tem dado quem se assente no meu trono, e que os meus olhos o vissem.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 49, 'Então estremeceram e se levantaram todos os convidados que estavam com Adonias; e cada um se foi ao seu caminho.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 50, 'Porém Adonias temeu a Salomão; e levantou-se, e foi, e apegou-se às pontas do altar.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 51, 'E fez-se saber a Salomão, dizendo: Eis que Adonias teme ao rei Salomão; porque eis que apegou-se às pontas do altar, dizendo: Jure-me hoje o rei Salomão que não matará o seu servo à espada.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 52, 'E disse Salomão: Se for homem de bem, nem um de seus cabelos cairá em terra; se, porém, se achar nele maldade, morrerá.', 2, CURRENT_TIMESTAMP, false),
(11, 1, 53, 'E mandou o rei Salomão, e o fizeram descer do altar; e veio, e prostrou-se perante o rei Salomão, e Salomão lhe disse: Vai para tua casa.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 1, 'E aproximaram-se os dias da morte de Davi; e deu ele ordem a Salomão, seu filho, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 2, 2, 'Eu vou pelo caminho de toda a terra; esforça-te, pois, e sê homem.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 3, 'E guarda a ordenança do Senhor teu Deus, para andares nos seus caminhos, e para guardares os seus estatutos, e os seus mandamentos, e os seus juízos, e os seus testemunhos, como está escrito na lei de Moisés; para que prosperes em tudo quanto fizeres, e para onde quer que fores.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 4, 'Para que o Senhor confirme a palavra, que falou de mim, dizendo: Se teus filhos guardarem o seu caminho, para andarem perante a minha face fielmente, com todo o seu coração e com toda a sua alma, nunca, disse, te faltará sucessor ao trono de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 5, 'E também tu sabes o que me fez Joabe, filho de Zeruia, e o que fez aos dois capitães do exército de Israel, a Abner filho de Ner, e a Amasa, filho de Jeter, os quais matou, e em paz derramou o sangue de guerra, e pôs o sangue de guerra no cinto que tinha nos lombos, e nos sapatos que trazia nos pés.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 6, 'Faze, pois, segundo a tua sabedoria, e não permitas que suas cãs desçam à sepultura em paz.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 7, 'Porém com os filhos de Barzilai, o gileadita, usarás de beneficência, e estarão entre os que comem à tua mesa, porque assim se chegaram eles a mim, quando eu fugia por causa de teu irmão Absalão.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 8, 'E eis que também contigo está Simei, filho de Gera, filho de Benjamim, de Baurim, que me maldisse com maldição atroz, no dia em que ia a Maanaim; porém ele saiu a encontrar-se comigo junto ao Jordão, e eu pelo Senhor lhe jurei, dizendo que o não mataria à espada.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 9, 'Mas agora não o tenhas por inculpável, pois és homem sábio, e bem saberás o que lhe hás de fazer para que faças com que as suas cãs desçam à sepultura com sangue.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 10, 'E Davi dormiu com seus pais, e foi sepultado na cidade de Davi.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 11, 'E foram os dias que Davi reinou sobre Israel quarenta anos: sete anos reinou em Hebrom, e em Jerusalém reinou trinta e três anos.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 12, 'E Salomão se assentou no trono de Davi, seu pai, e o seu reino se fortificou sobremaneira.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 13, 'Então veio Adonias, filho de Hagite, a Bate-Seba, mãe de Salomão; e disse ela: De paz é a tua vinda? E ele disse: É de paz.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 14, 'Então disse ele: Uma palavra tenho que dizer-te. E ela disse: Fala.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 15, 'Disse, pois, ele: Bem sabes que o reino era meu, e todo o Israel tinha posto a vista em mim para que eu viesse a reinar, contudo o reino foi transferido e veio a ser de meu irmão, porque foi feito seu pelo Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 16, 'Assim que agora uma só petição te faço; não ma rejeites. E ela lhe disse: Fala.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 17, 'E ele disse: Peço-te que fales ao rei Salomão (porque ele não te rejeitará) que me dê por mulher a Abisague, a sunamita.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 18, 'E disse Bate-Seba: Bem, eu falarei por ti ao rei.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 19, 'Assim foi Bate-Seba ao rei Salomão, a falar-lhe por Adonias; e o rei se levantou a encontrar-se com ela, e se inclinou diante dela; então se assentou no seu trono, e fez pôr uma cadeira para a sua mãe, e ela se assentou à sua direita.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 20, 'Então disse ela: Só uma pequena petição te faço; não ma rejeites. E o rei lhe disse: Pede, minha mãe, porque não ta negarei.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 21, 'E ela disse: Dê-se Abisague, a sunamita, a Adonias, teu irmão, por mulher.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 22, 'Então respondeu o rei Salomão, e disse a sua mãe: E por que pedes a Abisague, a sunamita, para Adonias? Pede também para ele o reino (porque é meu irmão maior), para ele, digo, e também para Abiatar, sacerdote, e para Joabe, filho de Zeruia.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 23, 'E jurou o rei Salomão pelo Senhor, dizendo: Assim Deus me faça, e outro tanto, se não falou Adonias esta palavra contra a sua vida.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 24, 'Agora, pois, vive o Senhor, que me confirmou, e me fez assentar no trono de Davi, meu pai, e que me tem feito casa, como tinha falado, que hoje morrerá Adonias.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 25, 'E enviou o rei Salomão pela mão de Benaia, filho de Joiada, o qual arremeteu contra ele de modo que morreu.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 26, 'E a Abiatar, o sacerdote, disse o rei: Vai para Anatote, para os teus campos, porque és homem digno de morte; porém hoje não te matarei, porquanto levaste a arca do Senhor DEUS diante de Davi, meu pai, e porquanto foste aflito em tudo quanto meu pai foi aflito.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 27, 'Lançou, pois, Salomão fora a Abiatar, para que não fosse sacerdote do Senhor, para cumprir a palavra do Senhor, que tinha falado sobre a casa de Eli em Siló.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 28, 'E chegou a notícia até Joabe (porque Joabe tinha se desviado seguindo a Adonias, ainda que não tinha se desviado seguindo a Absalão), e Joabe fugiu para o tabernáculo do Senhor, e apegou-se às pontas do altar.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 29, 'E disseram ao rei Salomão que Joabe tinha fugido para o tabernáculo do Senhor; e eis que está junto ao altar; então Salomão enviou Benaia, filho de Joiada, dizendo: Vai, arremete sobre ele.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 30, 'E foi Benaia ao tabernáculo do Senhor, e lhe disse: Assim diz o rei: Sai daí. E disse ele: Não, porém aqui morrerei. E Benaia tornou com a resposta ao rei, dizendo: Assim falou Joabe, e assim me respondeu.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 31, 'E disse-lhe o rei: Faze como ele disse, e arremete contra ele, e sepulta-o, para que tires de mim e da casa de meu pai o sangue que Joabe sem causa derramou.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 32, 'Assim o Senhor fará recair o sangue dele sobre a sua cabeça, porque deu sobre dois homens mais justos e melhores do que ele, e os matou à espada, sem que meu pai Davi o soubesse, a saber: a Abner, filho de Ner, capitão do exército de Israel, e a Amasa, filho de Jeter, capitão do exército de Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 33, 'Assim recairá o sangue destes sobre a cabeça de Joabe e sobre a cabeça da sua descendência para sempre; mas a Davi, e à sua descendência, e à sua casa, e ao seu trono, dará o Senhor paz para todo o sempre.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 34, 'E subiu Benaia, filho de Joiada, e arremeteu contra ele, e o matou; e foi sepultado em sua casa, no deserto.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 35, 'E o rei pôs a Benaia, filho de Joiada, em seu lugar sobre o exército, e a Zadoque, o sacerdote, pôs o rei em lugar de Abiatar.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 36, 'Depois mandou o rei, e chamou a Simei, e disse-lhe: Edifica-te uma casa em Jerusalém, e habita aí, e daí não saias, nem para uma nem para outra parte.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 37, 'Porque há de ser que no dia em que saíres e passares o ribeiro de Cedrom, de certo que sem dúvida morrerás; o teu sangue será sobre a tua cabeça.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 38, 'E Simei disse ao rei: Boa é essa palavra; como tem falado o rei meu senhor, assim fará o teu servo. E Simei habitou em Jerusalém muitos dias.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 39, 'Sucedeu, porém, que, ao cabo de três anos, dois servos de Simei fugiram para Aquis, filho de Maaca, rei de Gate; e deram parte a Simei, dizendo: Eis que teus servos estão em Gate.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 40, 'Então Simei se levantou, e albardou o seu jumento, e foi a Gate, ter com Aquis, em busca de seus servos; assim foi Simei, e trouxe os seus servos de Gate.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 41, 'E disseram a Salomão como Simei fora de Jerusalém a Gate, e já tinha voltado.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 42, 'Então o rei mandou chamar a Simei, e disse-lhe: Não te conjurei eu pelo Senhor, e protestei contra ti, dizendo: No dia em que saíres para uma ou outra parte, sabe de certo que, sem dúvida, morrerás? E tu me disseste: Boa é essa palavra que ouvi.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 43, 'Por que, pois, não guardaste o juramento do Senhor, nem a ordem que te dei?', 2, CURRENT_TIMESTAMP, false),
(11, 2, 44, 'Disse mais o rei a Simei: Bem sabes tu toda a maldade que o teu coração reconhece, que fizeste a Davi, meu pai; pelo que o Senhor fez recair a tua maldade sobre a tua cabeça.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 45, 'Mas o rei Salomão será abençoado, e o trono de Davi será confirmado perante o Senhor para sempre.', 2, CURRENT_TIMESTAMP, false),
(11, 2, 46, 'E o rei mandou a Benaia, filho de Joiada, o qual saiu, e arremeteu contra ele, de modo que morreu; assim foi confirmado o reino na mão de Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 1, 'E Salomão se aparentou com Faraó, rei do Egito; e tomou a filha de Faraó, e a trouxe à cidade de Davi, até que acabasse de edificar a sua casa, e a casa do SENHOR, e a muralha de Jerusalém em redor.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 2, 'Entretanto, o povo sacrificava sobre os altos; porque até àqueles dias ainda não se havia edificado casa ao nome do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 3, 'E Salomão amava ao Senhor, andando nos estatutos de Davi seu pai; somente que nos altos sacrificava, e queimava incenso.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 4, 'E foi o rei a Gibeom para lá sacrificar, porque aquele era o alto maior; mil holocaustos sacrificou Salomão naquele altar.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 5, 'E em Gibeom apareceu o Senhor a Salomão de noite em sonhos; e disse-lhe Deus: Pede o que queres que eu te dê.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 6, 'E disse Salomão: De grande beneficência usaste tu com teu servo Davi, meu pai, como também ele andou contigo em verdade, e em justiça, e em retidão de coração, perante a tua face; e guardaste-lhe esta grande beneficência, e lhe deste um filho que se assentasse no seu trono, como se vê neste dia.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 7, 'Agora, pois, ó Senhor meu Deus, tu fizeste reinar a teu servo em lugar de Davi meu pai; e sou apenas um menino pequeno; não sei como sair, nem como entrar.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 8, 'E teu servo está no meio do teu povo que elegeste; povo grande, que nem se pode contar, nem numerar, pela sua multidão.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 9, 'A teu servo, pois, dá um coração entendido para julgar a teu povo, para que prudentemente discirna entre o bem e o mal; porque quem poderia julgar a este teu tão grande povo?', 2, CURRENT_TIMESTAMP, false),
(11, 3, 10, 'E esta palavra pareceu boa aos olhos do Senhor, de que Salomão pedisse isso.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 11, 'E disse-lhe Deus: Porquanto pediste isso, e não pediste para ti muitos dias, nem pediste para ti riquezas, nem pediste a vida de teus inimigos; mas pediste para ti entendimento, para discernires o que é justo;', 2, CURRENT_TIMESTAMP, false),
(11, 3, 12, 'Eis que fiz segundo as tuas palavras; eis que te dei um coração tão sábio e entendido, que antes de ti igual não houve, e depois de ti igual não se levantará.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 13, 'E também até o que não pediste te dei, assim riquezas como glória; de modo que não haverá um igual entre os reis, por todos os teus dias.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 14, 'E, se andares nos meus caminhos, guardando os meus estatutos, e os meus mandamentos, como andou Davi teu pai, também prolongarei os teus dias.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 15, 'E acordou Salomão, e eis que era sonho. E indo a Jerusalém, pôs-se perante a arca da aliança do Senhor, e sacrificou holocausto, e preparou sacrifícios pacíficos, e fez um banquete a todos os seus servos.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 16, 'Então vieram duas mulheres prostitutas ao rei, e se puseram perante ele.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 17, 'E disse-lhe uma das mulheres: Ah! senhor meu, eu e esta mulher moramos numa casa; e tive um filho, estando com ela naquela casa.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 18, 'E sucedeu que, ao terceiro dia, depois do meu parto, teve um filho também esta mulher; estávamos juntas; nenhum estranho estava conosco na casa; somente nós duas naquela casa.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 19, 'E de noite morreu o filho desta mulher, porquanto se deitara sobre ele.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 20, 'E levantou-se à meia-noite, e tirou o meu filho do meu lado, enquanto dormia a tua serva, e o deitou no seu seio; e a seu filho morto deitou no meu seio.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 21, 'E, levantando-me eu pela manhã, para dar de mamar a meu filho, eis que estava morto; mas, atentando pela manhã para ele, eis que não era meu filho, que eu havia tido.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 22, 'Então disse a outra mulher: Não, mas o vivo é meu filho, e teu filho o morto. Porém esta disse: Não, por certo, o morto é teu filho, e meu filho o vivo. Assim falaram perante o rei.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 23, 'Então disse o rei: Esta diz: Este que vive é meu filho, e teu filho o morto; e esta outra diz: Não, por certo, o morto é teu filho e meu filho o vivo.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 24, 'Disse mais o rei: Trazei-me uma espada. E trouxeram uma espada diante do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 25, 'E disse o rei: Dividi em duas partes o menino vivo; e dai metade a uma, e metade a outra.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 26, 'Mas a mulher, cujo filho era o vivo, falou ao rei (porque as suas entranhas se lhe enterneceram por seu filho), e disse: Ah! senhor meu, dai-lhe o menino vivo, e de modo nenhum o mateis. Porém a outra dizia: Nem teu nem meu seja; dividi-o.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 27, 'Então respondeu o rei, e disse: Dai a esta o menino vivo, e de maneira nenhuma o mateis, porque esta é sua mãe.', 2, CURRENT_TIMESTAMP, false),
(11, 3, 28, 'E todo o Israel ouviu o juízo que havia dado o rei, e temeu ao rei; porque viram que havia nele a sabedoria de Deus, para fazer justiça.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 1, 'Assim foi Salomão rei sobre todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 2, 'E estes eram os príncipes que tinha: Azarias, filho de Zadoque, sacerdote;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 3, 'Eliorefe e Aías, filhos de Sisa, secretários; Jeosafá, filho de Ailude, cronista;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 4, 'Benaia, filho de Joiada, sobre o exército; e Zadoque e Abiatar eram sacerdotes;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 5, 'E Azarias, filho de Natã, sobre os provedores; e Zabude, filho de Natã, oficial-mor, amigo do rei;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 6, 'E Aisar, mordomo; Adonirão, filho de Abda, sobre o tributo.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 7, 'E tinha Salomão doze oficiais sobre todo o Israel, que proviam ao rei e à sua casa; e cada um tinha que abastecê-lo por um mês no ano.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 8, 'E estes são os seus nomes: Ben-Hur, nas montanhas de Efraim;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 9, 'Ben-Dequer em Macaz, e em Saalbim, e em Bete-Semes, e em Elom, e em Bete-Hanã;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 10, 'Ben-Hesede em Arubote; também este tinha a Socó e a toda a terra de Hefer;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 11, 'Ben-Abinadabe em todo o termo de Dor; tinha este a Tafate, filha de Salomão, por mulher;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 12, 'Baana, filho de Ailude, tinha a Taanaque, e a Megido, e a toda a Bete-Seã, que está junto a Zaretã, abaixo de Jizreel, desde Bete-Seã até Abel-Meolá, para além de Jocmeão;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 13, 'O filho de Geber, em Ramote de Gileade; tinha este as aldeias de Jair, filho de Manassés, as quais estão em Gileade; também tinha o termo de Argobe, o qual está em Basã, sessenta grandes cidades, com muros e ferrolhos de cobre;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 14, 'Ainadabe, filho de Ido, em Maanaim.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 15, 'Aimaás em Naftali; também este tomou a Basemate, filha de Salomão, por mulher;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 16, 'Baaná, filho de Husai, em Aser e em Alote;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 17, 'Jeosafá, filho de Parua, em Issacar;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 18, 'Simei, filho de Elá, em Benjamim:', 2, CURRENT_TIMESTAMP, false),
(11, 4, 19, 'Geber, filho de Uri, na terra de Gileade, a terra de Siom, rei dos amorreus, e de Ogue, rei de Basã; e só uma guarnição havia naquela terra.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 20, 'Eram, pois, os de Judá e Israel muitos, como a areia que está junto ao mar em multidão, comendo, e bebendo, e alegrando-se.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 21, 'E dominava Salomão sobre todos os reinos desde o rio até à terra dos filisteus, e até ao termo do Egito; os quais traziam presentes, e serviram a Salomão todos os dias da sua vida.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 22, 'Era, pois, o provimento de Salomão cada dia, trinta coros de flor de farinha, e sessenta coros de farinha;', 2, CURRENT_TIMESTAMP, false),
(11, 4, 23, 'Dez bois cevados, e vinte bois de pasto, e cem carneiros; afora os veados e as cabras montesas, e os corços, e aves cevadas.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 24, 'Porque dominava sobre tudo quanto havia do lado de cá do rio, Tifsa até Gaza, sobre todos os reis do lado de cá do rio; e tinha paz de todos os lados em redor dele.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 25, 'E Judá e Israel habitavam seguros, cada um debaixo da sua videira, e debaixo da sua figueira, desde Dã até Berseba, todos os dias de Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 26, 'Tinha também Salomão quarenta mil estrebarias de cavalos para os seus carros, e doze mil cavaleiros.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 27, 'Proviam, pois, estes provedores, cada um no seu mês, ao rei Salomão e a todos quantos se chegaram à mesa do rei Salomão; coisa nenhuma deixavam faltar.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 28, 'E traziam a cevada e a palha para os cavalos e para os ginetes, para o lugar onde estava, cada um segundo o seu cargo.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 29, 'E deu Deus a Salomão sabedoria, e muitíssimo entendimento, e largueza de coração, como a areia que está na praia do mar.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 30, 'E era a sabedoria de Salomão maior do que a sabedoria de todos os do oriente e do que toda a sabedoria dos egípcios.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 31, 'E era ele ainda mais sábio do que todos os homens, e do que Etã, ezraíta, e Hemã, e Calcol, e Darda, filhos de Maol; e correu o seu nome por todas as nações em redor.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 32, 'E disse três mil provérbios, e foram os seus cânticos mil e cinco.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 33, 'Também falou das árvores, desde o cedro que está no Líbano até ao hissopo que nasce na parede; também falou dos animais e das aves, e dos répteis e dos peixes.', 2, CURRENT_TIMESTAMP, false),
(11, 4, 34, 'E vinham de todos os povos a ouvir a sabedoria de Salomão, e de todos os reis da terra que tinham ouvido da sua sabedoria.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 1, 'E enviou Hirão, rei de Tiro, os seus servos a Salomão (porque ouvira que ungiram a Salomão rei em lugar de seu pai), porquanto Hirão sempre tinha amado a Davi.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 2, 'Então Salomão mandou dizer a Hirão:', 2, CURRENT_TIMESTAMP, false),
(11, 5, 3, 'Bem sabes tu que Davi, meu pai, não pôde edificar uma casa ao nome do Senhor seu Deus, por causa da guerra com que o cercaram, até que o Senhor pôs seus inimigos debaixo das plantas dos seus pés.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 4, 'Porém agora o Senhor meu Deus me tem dado descanso de todos os lados; adversário não há, nem algum mau encontro.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 5, 'E eis que eu intento edificar uma casa ao nome do Senhor meu Deus, como falou o Senhor a Davi, meu pai, dizendo: Teu filho, que porei em teu lugar no teu trono, ele edificará uma casa ao meu nome.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 6, 'Dá ordem, pois, agora, que do Líbano me cortem cedros, e os meus servos estarão com os teus servos, e eu te darei o salário dos teus servos, conforme a tudo o que disseres; porque bem sabes tu que entre nós ninguém há que saiba cortar a madeira como os sidônios.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 7, 'E aconteceu que, ouvindo Hirão as palavras de Salomão, muito se alegrou, e disse: Bendito seja hoje o Senhor, que deu a Davi um filho sábio sobre este tão grande povo.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 8, 'E enviou Hirão a Salomão, dizendo: Ouvi o que me mandaste dizer. Eu farei toda a tua vontade acerca das madeiras de cedro e de cipreste.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 9, 'Os meus servos as levarão desde o Líbano até ao mar, e eu as farei conduzir em jangadas pelo mar até ao lugar que me designares, e ali as desamarrarei; e tu as tomarás; tu também farás a minha vontade, dando sustento à minha casa.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 10, 'Assim deu Hirão a Salomão madeira de cedro e madeira de cipreste, conforme a toda a sua vontade.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 11, 'E Salomão deu a Hirão vinte mil coros de trigo, para sustento da sua casa, e vinte coros de azeite batido; isto dava Salomão a Hirão anualmente.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 12, 'Deu, pois, o Senhor a Salomão sabedoria, como lhe tinha falado; e houve paz entre Hirão e Salomão, e ambos fizeram acordo.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 13, 'E o rei Salomão fez subir uma leva de gente dentre todo o Israel, e foi a leva de gente trinta mil homens;', 2, CURRENT_TIMESTAMP, false),
(11, 5, 14, 'E os enviava ao Líbano, cada mês, dez mil por turno; um mês estavam no Líbano, e dois meses cada um em sua casa; e Adonirão estava sobre a leva de gente.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 15, 'Tinha também Salomão setenta mil que levavam as cargas, e oitenta mil que talhavam pedras nas montanhas,', 2, CURRENT_TIMESTAMP, false),
(11, 5, 16, 'Afora os chefes dos oficiais de Salomão, que estavam sobre aquela obra, três mil e trezentos, os quais davam as ordens ao povo que fazia aquela obra.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 17, 'E mandou o rei que trouxessem pedras grandes, e pedras valiosas, pedras lavradas, para fundarem a casa.', 2, CURRENT_TIMESTAMP, false),
(11, 5, 18, 'E as lavraram os edificadores de Hirão, e os giblitas; e preparavam a madeira e as pedras para edificar a casa.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 1, 'E sucedeu que no ano de quatrocentos e oitenta, depois de saírem os filhos de Israel do Egito, no ano quarto do reinado de Salomão sobre Israel, no mês de Zive (este é o mês segundo), começou a edificar a casa do SENHOR.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 2, 'E a casa que o rei Salomão edificou ao Senhor era de sessenta côvados de comprimento, e de vinte côvados de largura, e de trinta côvados de altura.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 3, 'E o pórtico diante do templo da casa era de vinte côvados de comprimento, segundo a largura da casa, e de dez côvados de largura diante da casa.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 4, 'E fez para a casa janelas de gelósias fixas.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 5, 'E edificou câmaras junto ao muro da casa, contra as paredes da casa, em redor, tanto do templo como do oráculo; e assim lhe fez câmaras laterais em redor.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 6, 'A câmara de baixo era de cinco côvados de largura, e a do meio de seis côvados de largura, e a terceira de sete côvados de largura; porque pela parte de fora da casa, em redor, fizera encostos, para que as vigas não se apoiassem nas paredes da casa.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 7, 'E edificava-se a casa com pedras preparadas, como as traziam se edificava; de maneira que nem martelo, nem machado, nem nenhum outro instrumento de ferro se ouviu na casa quando a edificavam.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 8, 'A porta da câmara do meio estava ao lado direito da casa, e por caracóis se subia à do meio, e da do meio à terceira.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 9, 'Assim, pois, edificou a casa, e a acabou; e cobriu a casa com pranchões e tabuados de cedro.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 10, 'Também edificou as câmaras em volta de toda a casa, de cinco côvados de altura, e as ligou à casa com madeira de cedro.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 11, 'Então veio a palavra do Senhor a Salomão, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 6, 12, 'Quanto a esta casa que tu edificas, se andares nos meus estatutos, e fizeres os meus juízos, e guardares todos os meus mandamentos, andando neles, confirmarei para contigo a minha palavra, a qual falei a Davi, teu pai;', 2, CURRENT_TIMESTAMP, false),
(11, 6, 13, 'E habitarei no meio dos filhos de Israel, e não desampararei o meu povo de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 14, 'Assim edificou Salomão aquela casa, e a acabou.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 15, 'Também cobriu as paredes da casa por dentro com tábuas de cedro; desde o soalho da casa até ao teto tudo cobriu com madeira por dentro; e cobriu o soalho da casa com tábuas de cipreste.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 16, 'Edificou mais vinte côvados de tábuas de cedro nos lados da casa, desde o soalho até às paredes; e por dentro lhas edificou para o oráculo, para o Santo dos Santos.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 17, 'A casa, isto é, o templo anterior tinha quarenta côvados.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 18, 'E o cedro da casa por dentro era lavrado de botões e flores abertas; tudo era cedro, pedra nenhuma se via.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 19, 'E por dentro da casa, na parte mais interior, preparou o oráculo, para pôr ali a arca da aliança do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 20, 'E o oráculo no interior era de vinte côvados de comprimento, e de vinte côvados de largura, e de vinte côvados de altura; e o revestiu de ouro puro; também revestiu de cedro o altar.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 21, 'E revestiu Salomão a casa por dentro de ouro puro; e com cadeias de ouro pôs uma cortina diante do oráculo, e o revestiu com ouro.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 22, 'Assim cobriu de ouro toda a casa, inteiramente; também cobriu de ouro todo o altar que estava diante do oráculo.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 23, 'E no oráculo fez dois querubins de madeira de oliveira, cada um da altura de dez côvados.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 24, 'E uma asa de um querubim era de cinco côvados, e a outra asa do querubim de outros cinco côvados; dez côvados havia desde a extremidade de uma das suas asas até à extremidade da outra das suas asas.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 25, 'Assim era também de dez côvados o outro querubim; ambos os querubins eram de uma mesma medida e de um mesmo talhe.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 26, 'A altura de um querubim era de dez côvados, e assim a do outro querubim.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 27, 'E pôs a estes querubins no meio da casa de dentro; e os querubins estendiam as asas, de maneira que a asa de um tocava na parede, e a asa do outro querubim tocava na outra parede; e as suas asas no meio da casa tocavam uma na outra.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 28, 'E revestiu de ouro os querubins.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 29, 'E todas as paredes da casa, em redor, lavrou de esculturas e entalhes de querubins, e de palmas, e de flores abertas, por dentro e por fora.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 30, 'Também revestiu de ouro o soalho da casa, por dentro e por fora.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 31, 'E à entrada do oráculo fez portas de madeira de oliveira; o umbral de cima com as ombreiras faziam a quinta parte da parede.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 32, 'Também as duas portas eram de madeira de oliveira; e lavrou nelas entalhes de querubins, e de palmas, e de flores abertas, os quais revestiu de ouro; também estendeu ouro sobre os querubins e sobre as palmas.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 33, 'E assim fez à porta do templo ombreiras de madeira de oliveira, da quarta parte da parede.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 34, 'E eram as duas portas de madeira de cipreste; e as duas folhas de uma porta eram dobradiças, assim como eram também dobradiças as duas folhas entalhadas das outras portas.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 35, 'E as lavrou de querubins e de palmas, e de flores abertas, e as revestiu de ouro acomodado ao lavor.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 36, 'Também edificou o pátio interior de três ordens de pedras lavradas e de uma ordem de vigas de cedro.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 37, 'No ano quarto se pôs o fundamento da casa do Senhor, no mês de Zive.', 2, CURRENT_TIMESTAMP, false),
(11, 6, 38, 'E no ano undécimo, no mês de Bul, que é o mês oitavo, se acabou esta casa com todas as suas coisas, e com tudo o que lhe convinha; e a edificou em sete anos.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 1, 'Porém a sua casa edificou Salomão em treze anos; e acabou toda a sua casa.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 2, 'Também edificou a casa do bosque do Líbano de cem côvados de comprimento, e de cinqüenta côvados de largura, e de trinta côvados de altura, sobre quatro ordens de colunas de cedro, e vigas de cedro sobre as colunas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 3, 'E por cima estava coberta de cedro sobre as vigas, que estavam sobre quarenta e cinco colunas, quinze em cada ordem.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 4, 'E havia três ordens de janelas; e uma janela estava defronte da outra janela, em três ordens.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 5, 'Também todas as portas e ombreiras quadradas eram de uma mesma vista; e uma janela estava defronte da outra, em três ordens.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 6, 'Depois fez um pórtico de colunas de cinqüenta côvados de comprimento e de trinta côvados de largura; e o pórtico estava defronte delas, e as colunas com as grossas vigas defronte delas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 7, 'Também fez o pórtico para o trono onde julgava, isto é, o pórtico do juízo, que estava revestido de cedro de soalho a soalho.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 8, 'E em sua casa, em que morava, havia outro pátio, por dentro do pórtico, de obra semelhante à deste; também para a filha de Faraó, que Salomão tomara por mulher, fez uma casa semelhante àquele pórtico.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 9, 'Todas estas coisas eram de pedras de grande valor, cortadas à medida, serradas à serra por dentro e por fora; e isto desde o fundamento até às beiras do teto, e por fora até ao grande pátio.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 10, 'Também estava fundado sobre pedras finas, pedras grandes; sobre pedras de dez côvados e pedras de oito côvados.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 11, 'E em cima delas pedras de grande valor, lavradas segundo as medidas, e madeira de cedro.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 12, 'Havia três ordens de pedras lavradas, com uma ordem de vigas de cedro; assim era também o pátio interior da casa do Senhor e o pórtico daquela casa.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 13, 'E enviou o rei Salomão um mensageiro e mandou trazer a Hirão de Tiro.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 14, 'Era ele filho de uma mulher viúva, da tribo de Naftali, e fora seu pai um homem de Tiro, que trabalhava em cobre; e era cheio de sabedoria, e de entendimento, e de ciência para fazer toda a obra de cobre; este veio ao rei Salomão, e fez toda a sua obra.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 15, 'E formou duas colunas de cobre; a altura de cada coluna era de dezoito côvados, e um fio de doze côvados cercava cada uma das colunas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 16, 'Também fez dois capitéis de fundição de cobre para pôr sobre as cabeças das colunas; de cinco côvados era a altura de um capitel, e de cinco côvados a altura do outro capitel.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 17, 'As redes eram de malhas, as ligas de obra de cadeia para os capitéis que estavam sobre a cabeça das colunas, sete para um capitel e sete para o outro capitel.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 18, 'Assim fez as colunas, juntamente com duas fileiras em redor sobre uma rede, para cobrir os capitéis que estavam sobre a cabeça das romãs, assim também fez com o outro capitel.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 19, 'E os capitéis que estavam sobre a cabeça das colunas eram de obra de lírios no pórtico, de quatro côvados.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 20, 'Os capitéis, pois, sobre as duas colunas estavam também defronte, em cima da parte globular que estava junto à rede; e duzentas romãs, em fileiras em redor, estavam também sobre o outro capitel.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 21, 'Depois levantou as colunas no pórtico do templo; e levantando a coluna direita, pôs-lhe o nome de Jaquim; e levantando a coluna esquerda, pôs-lhe o nome de Boaz.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 22, 'E sobre a cabeça das colunas estava a obra de lírios; e assim se acabou a obra das colunas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 23, 'Fez mais o mar de fundição, de dez côvados de uma borda até à outra borda, perfeitamente redondo, e de cinco côvados de alto; e um cordão de trinta côvados o cingia em redor.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 24, 'E por baixo da sua borda em redor havia botões que o cingiam; por dez côvados cercavam aquele mar em redor; duas ordens destes botões foram fundidas quando o mar foi fundido.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 25, 'E firmava-se sobre doze bois, três que olhavam para o norte, e três que olhavam para o ocidente, e três que olhavam para o sul, e três que olhavam para o oriente; e o mar estava em cima deles, e todas as suas partes posteriores para o lado de dentro.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 26, 'E a grossura era de um palmo, e a sua borda era como a de um copo, como de flor de lírios; ele levava dois mil batos.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 27, 'Fez também as dez bases de cobre; o comprimento de uma base de quatro côvados, e de quatro côvados a sua largura, e três côvados a sua altura.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 28, 'E esta era a obra das bases; tinham cintas, e as cintas estavam entre as molduras.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 29, 'E sobre as cintas que estavam entre as molduras havia leões, bois, e querubins, e sobre as molduras uma base por cima; e debaixo dos leões e dos bois junturas de obra estendida.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 30, 'E uma base tinha quatro rodas de metal, e lâminas de cobre; e os seus quatro cantos tinham suportes; debaixo da pia estavam estes suportes fundidos, do lado de cada uma das junturas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 31, 'E a boca da pia estava dentro da coroa, e de um côvado por cima; e era a sua boca redonda segundo a obra da base, de côvado e meio; e também sobre a sua boca havia entalhes, e as suas cintas eram quadradas, não redondas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 32, 'E as quatro rodas estavam debaixo das cintas, e os eixos das rodas na base; e era a altura de cada roda de côvado e meio.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 33, 'E era a obra das rodas como a obra da roda de carro; seus eixos, e suas cambas e seus cubos, e seus raios, todos eram fundidos.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 34, 'E havia quatro suportes aos quatro cantos de cada base; seus suportes saíam da base.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 35, 'E no alto de cada base havia uma peça redonda de meio côvado de altura; também sobre o alto de cada base havia asas e cintas, que saíam delas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 36, 'E nas placas de seus esteios e nas suas cintas lavrou querubins, leões, e palmas, segundo o espaço de cada uma, e outros adornos em redor.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 37, 'Conforme a esta fez as dez bases; todas tinham uma mesma fundição, uma mesma medida, e um mesmo entalhe.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 38, 'Também fez dez pias de cobre; em cada pia cabiam quarenta batos, e cada pia era de quatro côvados, e sobre cada uma das dez bases estava uma pia.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 39, 'E pôs cinco bases à direita da casa, e cinco à esquerda da casa; porém o mar pôs ao lado direito da casa para o lado do oriente, da parte do sul.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 40, 'Depois fez Hirão as pias, e as pás, e as bacias; e acabou Hirão de fazer toda a obra que fez para o rei Salomão, para a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 41, 'A saber: as duas colunas, e os globos dos capitéis que estavam sobre a cabeça das duas colunas; e as duas redes, para cobrir os dois globos dos capitéis que estavam sobre a cabeça das colunas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 42, 'E as quatrocentas romãs para as duas redes, a saber: duas carreiras de romãs para cada rede, para cobrirem os dois globos dos capitéis que estavam em cima das colunas.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 43, 'Juntamente com as dez bases, e as dez pias sobre as bases;', 2, CURRENT_TIMESTAMP, false),
(11, 7, 44, 'Como também um mar, e os doze bois debaixo daquele mar;', 2, CURRENT_TIMESTAMP, false),
(11, 7, 45, 'E os caldeirões, e as pás, e as bacias, e todos estes objetos que fez Hirão para o rei Salomão, para a casa do Senhor, todos eram de cobre polido.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 46, 'Na planície do Jordão, o rei os fundiu em terra barrenta; entre Sucote e Zaretã.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 47, 'E deixou Salomão de pesar todos os objetos, pelo seu excessivo número; nem se averiguou o peso do cobre.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 48, 'Também fez Salomão todos os objetos que convinham à casa do Senhor; o altar de ouro, e a mesa de ouro, sobre a qual estavam os pães da proposição.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 49, 'E os castiçais, cinco à direita e cinco à esquerda, diante do oráculo, de ouro finíssimo; e as flores, e as lâmpadas, e os espevitadores, também de ouro.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 50, 'Como também os vasos, e os apagadores, e as bacias, e as colheres, e os perfumadores, de ouro finíssimo; e as dobradiças para as portas da casa interior para o lugar santíssimo, e as das portas da casa do templo, também de ouro.', 2, CURRENT_TIMESTAMP, false),
(11, 7, 51, 'Assim se acabou toda a obra que fez o rei Salomão para a casa do Senhor; então trouxe Salomão as coisas que seu pai Davi havia consagrado; a prata, e o ouro, e os objetos pôs entre os tesouros da casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 1, 'Então congregou Salomão os anciãos de Israel, e todos os cabeças das tribos, os chefes dos pais dos filhos de Israel, diante de si em Jerusalém; para fazerem subir a arca da aliança do SENHOR da cidade de Davi, que é Sião.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 2, 'E todos os homens de Israel se congregaram ao rei Salomão, na ocasião da festa, no mês de Etanim, que é o sétimo mês.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 3, 'E vieram todos os anciãos de Israel; e os sacerdotes alçaram a arca.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 4, 'E trouxeram a arca do Senhor para cima, e o tabernáculo da congregação, juntamente com todos os objetos sagrados que havia no tabernáculo; assim os trouxeram para cima os sacerdotes e os levitas.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 5, 'E o rei Salomão, e toda a congregação de Israel que se congregara a ele, estava com ele diante da arca, sacrificando ovelhas e vacas, que não se podiam contar nem numerar pela sua quantidade.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 6, 'Assim trouxeram os sacerdotes a arca da aliança do Senhor ao seu lugar, ao oráculo da casa, ao lugar santíssimo, até debaixo das asas dos querubins.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 7, 'Porque os querubins estendiam ambas as asas sobre o lugar da arca; e os querubins cobriam, por cima, a arca e os seus varais.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 8, 'E os varais sobressaíram tanto, que as pontas dos varais se viam desde o santuário diante do oráculo, porém de fora não se viam; e ficaram ali até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 9, 'Na arca nada havia, senão só as duas tábuas de pedra, que Moisés ali pusera junto a Horebe, quando o Senhor fez a aliança com os filhos de Israel, saindo eles da terra do Egito.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 10, 'E sucedeu que, saindo os sacerdotes do santuário, uma nuvem encheu a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 11, 'E os sacerdotes não podiam permanecer em pé para ministrar, por causa da nuvem, porque a glória do Senhor enchera a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 12, 'Então falou Salomão: O Senhor disse que ele habitaria nas trevas.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 13, 'Certamente te edifiquei uma casa para morada, assento para a tua eterna habitação.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 14, 'Então virou o rei o seu rosto, e abençoou toda a congregação de Israel; e toda a congregação de Israel estava em pé.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 15, 'E disse: Bendito seja o Senhor Deus de Israel, que falou pela sua boca a Davi, meu pai, e pela sua mão o cumpriu, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 8, 16, 'Desde o dia em que eu tirei o meu povo Israel do Egito, não escolhi cidade alguma de todas as tribos de Israel, para edificar alguma casa para ali estabelecer o meu nome; porém escolhi a Davi, para que presidisse sobre o meu povo Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 17, 'Também Davi, meu pai, propusera em seu coração o edificar casa ao nome do Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 18, 'Porém o Senhor disse a Davi, meu pai: Porquanto propuseste no teu coração o edificar casa ao meu nome, bem fizeste em o propor no teu coração.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 19, 'Todavia tu não edificarás esta casa; porém teu filho, que sair de teus lombos, edificará esta casa ao meu nome.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 20, 'Assim confirmou o Senhor a sua palavra que falou; porque me levantei em lugar de Davi, meu pai, e me assentei no trono de Israel, como tem falado o Senhor; e edifiquei uma casa ao nome do Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 21, 'E constituí ali lugar para a arca em que está a aliança do Senhor, a qual fez com nossos pais, quando os tirou da terra do Egito.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 22, 'E pôs-se Salomão diante do altar do Senhor, na presença de toda a congregação de Israel; e estendeu as suas mãos para os céus,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 23, 'E disse: Ó Senhor Deus de Israel, não há Deus como tu, em cima nos céus nem em baixo na terra; que guardas a aliança e a beneficência a teus servos que andam com todo o seu coração diante de ti.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 24, 'Que guardaste a teu servo Davi, meu pai, o que lhe disseras; porque com a tua boca o disseste, e com a tua mão o cumpriste, como neste dia se vê.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 25, 'Agora, pois, ó Senhor Deus de Israel, guarda a teu servo Davi, meu pai, o que lhe falaste, dizendo: Não te faltará sucessor diante de mim, que se assente no trono de Israel; somente que teus filhos guardem o seu caminho, para andarem diante de mim como tu andaste diante de mim.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 26, 'Agora também, ó Deus de Israel, cumpra-se a tua palavra que disseste a teu servo Davi, meu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 27, 'Mas, na verdade, habitaria Deus na terra? Eis que os céus, e até o céu dos céus, não te poderiam conter, quanto menos esta casa que eu tenho edificado.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 28, 'Volve-te, pois, para a oração de teu servo, e para a sua súplica, ó Senhor meu Deus, para ouvires o clamor e a oração que o teu servo hoje faz diante de ti.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 29, 'Para que os teus olhos noite e dia estejam abertos sobre esta casa, sobre este lugar, do qual disseste: O meu nome estará ali; para ouvires a oração que o teu servo fizer neste lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 30, 'Ouve, pois, a súplica do teu servo, e do teu povo Israel, quando orarem neste lugar; também ouve tu no lugar da tua habitação nos céus; ouve também, e perdoa.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 31, 'Quando alguém pecar contra o seu próximo, e puserem sobre ele juramento de maldição, fazendo-o jurar, e vier juramento de maldição diante do teu altar nesta casa,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 32, 'Ouve tu, então, nos céus e age e julga a teus servos, condenando ao injusto, fazendo recair o seu proceder sobre a sua cabeça, e justificando ao justo, rendendo-lhe segundo a sua justiça.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 33, 'Quando o teu povo Israel for ferido diante do inimigo, por ter pecado contra ti, e se converterem a ti, e confessarem o teu nome, e orarem e suplicarem a ti nesta casa,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 34, 'Ouve tu então nos céus, e perdoa o pecado do teu povo Israel, e torna-o a levar à terra que tens dado a seus pais.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 35, 'Quando os céus se fechar, e não houver chuva, por terem pecado contra ti, e orarem neste lugar, e confessarem o teu nome, e se converterem dos seus pecados, havendo-os tu afligido,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 36, 'Ouve tu então nos céus, e perdoa o pecado de teus servos e do teu povo Israel, ensinando-lhes o bom caminho em que andem, e dá chuva na tua terra que deste ao teu povo em herança.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 37, 'Quando houver fome na terra, quando houver peste, quando houver queima de searas, ferrugem, gafanhotos ou pulgão, quando o seu inimigo o cercar na terra das suas portas, ou houver alguma praga ou doença,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 38, 'Toda a oração, toda a súplica, que qualquer homem de todo o teu povo Israel fizer, conhecendo cada um a chaga do seu coração, e estendendo as suas mãos para esta casa,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 39, 'Ouve tu então nos céus, assento da tua habitação, e perdoa, e age, e dá a cada um conforme a todos os seus caminhos, e segundo vires o seu coração, porque só tu conheces o coração de todos os filhos dos homens.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 40, 'Para que te temam todos os dias que viverem na terra que deste a nossos pais.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 41, 'E também ouve ao estrangeiro, que não for do teu povo Israel, quando vier de terras remotas, por amor do teu nome', 2, CURRENT_TIMESTAMP, false),
(11, 8, 42, '(Porque ouvirão do teu grande nome, e da tua forte mão, e do teu braço estendido), e vier orar voltado para esta casa,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 43, 'Ouve tu nos céus, assento da tua habitação, e faze conforme a tudo o que o estrangeiro a ti clamar, a fim de que todos os povos da terra conheçam o teu nome, para te temerem como o teu povo Israel, e para saberem que o teu nome é invocado sobre esta casa que tenho edificado.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 44, 'Quando o teu povo sair à guerra contra o seu inimigo, pelo caminho por que os enviares, e orarem ao Senhor, para o lado desta cidade, que tu elegeste, e desta casa, que edifiquei ao teu nome,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 45, 'Ouve, então, nos céus a sua oração e a sua súplica, e faze-lhes justiça.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 46, 'Quando pecarem contra ti (pois não há homem que não peque), e tu te indignares contra eles, e os entregares às mãos do inimigo, de modo que os levem em cativeiro para a terra inimiga, quer longe ou perto esteja,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 47, 'E na terra aonde forem levados em cativeiro caírem em si, e se converterem, e na terra do seu cativeiro te suplicarem, dizendo: Pecamos, e perversamente procedemos, e cometemos iniqüidade,', 2, CURRENT_TIMESTAMP, false),
(11, 8, 48, 'E se converterem a ti com todo o seu coração e com toda a sua alma, na terra de seus inimigos que os levarem em cativeiro, e orarem a ti para o lado da sua terra que deste a seus pais, para esta cidade que elegeste, e para esta casa que edifiquei ao teu nome;', 2, CURRENT_TIMESTAMP, false),
(11, 8, 49, 'Ouve então nos céus, assento da tua habitação, a sua oração e a sua súplica, e faze-lhes justiça.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 50, 'E perdoa ao teu povo que houver pecado contra ti, todas as transgressões que houverem cometido contra ti; e dá-lhes misericórdia perante aqueles que os têm cativos, para que deles tenham compaixão.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 51, 'Porque são o teu povo e a tua herança que tiraste da terra do Egito, do meio do forno de ferro.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 52, 'Para que teus olhos estejam abertos à súplica do teu servo e à súplica do teu povo Israel, a fim de os ouvires em tudo quanto clamarem a ti.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 53, 'Pois tu para tua herança os elegeste de todos os povos da terra, como tens falado pelo ministério de Moisés, teu servo, quando tiraste a nossos pais do Egito, Senhor DEUS.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 54, 'Sucedeu, pois, que, acabando Salomão de fazer ao Senhor esta oração e esta súplica, estando de joelhos e com as mãos estendidas para os céus, se levantou de diante do altar do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 55, 'E pôs-se em pé, e abençoou a toda a congregação de Israel em alta voz, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 8, 56, 'Bendito seja o Senhor, que deu repouso ao seu povo Israel, segundo tudo o que disse; nem uma só palavra caiu de todas as suas boas palavras que falou pelo ministério de Moisés, seu servo.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 57, 'O Senhor nosso Deus seja conosco, como foi com nossos pais; não nos desampare, e não nos deixe.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 58, 'Inclinando a si o nosso coração, para andar em todos os seus caminhos, e para guardar os seus mandamentos, e os seus estatutos, e os seus juízos que ordenou a nossos pais.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 59, 'E que estas minhas palavras, com que supliquei perante o Senhor, estejam perto, diante do Senhor nosso Deus, de dia e de noite, para que execute o juízo do seu servo e o juízo do seu povo Israel, a cada qual no seu dia.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 60, 'Para que todos os povos da terra saibam que o Senhor é Deus, e que não há outro.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 61, 'E seja o vosso coração inteiro para com o Senhor nosso Deus, para andardes nos seus estatutos, e guardardes os seus mandamentos como hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 62, 'E o rei e todo o Israel com ele ofereceram sacrifícios perante a face do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 63, 'E deu Salomão para o sacrifício pacífico que ofereceu ao Senhor, vinte e duas mil vacas e cento e vinte mil ovelhas; assim o rei e todos os filhos de Israel consagraram a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 64, 'No mesmo dia santificou o rei o meio do átrio que estava diante da casa do Senhor; porquanto ali preparara os holocaustos e as ofertas com a gordura dos sacrifícios pacíficos; porque o altar de cobre que estava diante da face do Senhor era muito pequeno para nele caberem os holocaustos e as ofertas, e a gordura dos sacrifícios pacíficos.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 65, 'No mesmo tempo celebrou Salomão a festa, e todo o Israel com ele, uma grande congregação, desde a entrada de Hamate até ao rio do Egito, perante a face do Senhor nosso Deus; por sete dias, e mais sete dias; catorze dias.', 2, CURRENT_TIMESTAMP, false),
(11, 8, 66, 'E no oitavo dia despediu o povo, e eles abençoaram o rei; então se foram às suas tendas, alegres e felizes de coração, por causa de todo o bem que o Senhor fizera a Davi seu servo, e a Israel seu povo.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 1, 'Sucedeu, pois, que, acabando Salomão de edificar a casa do SENHOR, e a casa do rei, e todo o desejo de Salomão, que lhe veio à vontade fazer,', 2, CURRENT_TIMESTAMP, false),
(11, 9, 2, 'O Senhor tornou a aparecer a Salomão; como lhe tinha aparecido em Gibeom.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 3, 'E o Senhor lhe disse: Ouvi a tua oração, e a súplica que fizeste perante mim; santifiquei a casa que edificaste, a fim de pôr ali o meu nome para sempre; e os meus olhos e o meu coração estarão ali todos os dias.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 4, 'E se tu andares perante mim como andou Davi, teu pai, com inteireza de coração e com sinceridade, para fazeres segundo tudo o que te mandei, e guardares os meus estatutos e os meus juízos,', 2, CURRENT_TIMESTAMP, false),
(11, 9, 5, 'Então confirmarei o trono de teu reino sobre Israel para sempre; como falei acerca de teu pai Davi, dizendo: Não te faltará sucessor sobre o trono de Israel;', 2, CURRENT_TIMESTAMP, false),
(11, 9, 6, 'Porém, se vós e vossos filhos de qualquer maneira vos apartardes de mim, e não guardardes os meus mandamentos, e os meus estatutos, que vos tenho proposto, mas fordes, e servirdes a outros deuses, e vos prostrardes perante eles,', 2, CURRENT_TIMESTAMP, false),
(11, 9, 7, 'Então destruirei a Israel da terra que lhes dei; e a esta casa, que santifiquei a meu nome, lançarei longe da minha presença; e Israel será por provérbio e motejo, entre todos os povos.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 8, 'E desta casa, que é tão exaltada, todo aquele que por ela passar pasmará, e assobiará, e dirá: Por que fez o Senhor assim a esta terra e a esta casa?', 2, CURRENT_TIMESTAMP, false),
(11, 9, 9, 'E dirão: Porque deixaram ao Senhor seu Deus, que tirou da terra do Egito a seus pais, e se apegaram a deuses alheios, e se encurvaram perante eles, e os serviram; por isso trouxe o Senhor sobre eles todo este mal.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 10, 'E sucedeu, ao fim de vinte anos, que Salomão edificara as duas casas; a casa do Senhor e a casa do rei', 2, CURRENT_TIMESTAMP, false),
(11, 9, 11, '(Para o que Hirão, rei de Tiro, trouxera a Salomão madeira de cedro e de cipreste, e ouro, segundo todo o seu desejo); então deu o rei Salomão a Hirão vinte cidades na terra da Galiléia.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 12, 'E saiu Hirão de Tiro a ver as cidades que Salomão lhe dera, porém não foram boas aos seus olhos.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 13, 'Por isso disse: Que cidades são estas que me deste, irmão meu? E chamaram-nas: Terra de Cabul, até hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 14, 'E enviara Hirão ao rei cento e vinte talentos de ouro.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 15, 'E esta é a causa do tributo que impôs o rei Salomão, para edificar a casa do Senhor e a sua casa, e Milo, e o muro de Jerusalém, como também a Hasor, e a Megido, e a Gezer.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 16, 'Porque Faraó, rei do Egito, subiu e tomou a Gezer, e a queimou a fogo, e matou os cananeus que moravam na cidade, e a deu em dote à sua filha, mulher de Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 17, 'Assim edificou Salomão a Gezer, e Bete-Horom, a baixa,', 2, CURRENT_TIMESTAMP, false),
(11, 9, 18, 'E a Baalate, e a Tadmor, no deserto daquela terra,', 2, CURRENT_TIMESTAMP, false),
(11, 9, 19, 'E a todas as cidades de provisões que Salomão tinha, e as cidades dos carros, e as cidades dos cavaleiros, e tudo o que Salomão quis edificar em Jerusalém, e no Líbano, e em toda a terra do seu domínio.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 20, 'Quanto a todo o povo que restou dos amorreus, heteus, perizeus, heveus, e jebuseus, e que não eram dos filhos de Israel,', 2, CURRENT_TIMESTAMP, false),
(11, 9, 21, 'A seus filhos, que restaram depois deles na terra, os quais os filhos de Israel não puderam destruir totalmente, Salomão os reduziu a tributo servil, até hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 22, 'Porém dos filhos de Israel não fez Salomão servo algum; porém eram homens de guerra, e seus criados, e seus príncipes, e seus capitães, e chefes dos seus carros e dos seus cavaleiros.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 23, 'Estes eram os chefes dos oficiais que estavam sobre a obra de Salomão, quinhentos e cinqüenta, que davam ordens ao povo que trabalhava na obra.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 24, 'Subiu, porém, a filha de Faraó da cidade de Davi, à sua casa, que Salomão lhe edificara; então edificou a Milo.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 25, 'E oferecia Salomão três vezes cada ano holocaustos e sacrifícios pacíficos sobre o altar que edificaram ao Senhor, e queimava incenso sobre o que estava perante o Senhor; e assim acabou a casa.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 26, 'Também o rei Salomão fez naus em Eziom-Geber, que está junto a Elate, à praia do mar de Sufe, na terra de Edom.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 27, 'E mandou Hirão com aquelas naus a seus servos, marinheiros, que sabiam do mar, com os servos de Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 9, 28, 'E vieram a Ofir, e tomaram de lá quatrocentos e vinte talentos de ouro, e os trouxeram ao rei Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 1, 'E ouvindo a rainha de Sabá a fama de Salomão, acerca do nome do SENHOR, veio prová-lo com questões difíceis.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 2, 'E chegou a Jerusalém com uma grande comitiva; com camelos carregados de especiarias, e muitíssimo ouro, e pedras preciosas; e foi a Salomão, e disse-lhe tudo quanto tinha no seu coração.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 3, 'E Salomão lhe deu resposta a todas as suas perguntas, nada houve que não lhe pudesse esclarecer.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 4, 'Vendo, pois, a rainha de Sabá toda a sabedoria de Salomão, e a casa que edificara,', 2, CURRENT_TIMESTAMP, false),
(11, 10, 5, 'E a comida da sua mesa, e o assentar de seus servos, e o estar de seus criados, e as vestes deles, e os seus copeiros, e os holocaustos que ele oferecia na casa do Senhor, ficou fora de si.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 6, 'E disse ao rei: Era verdade a palavra que ouvi na minha terra, dos teus feitos e da tua sabedoria.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 7, 'E eu não cria naquelas palavras, até que vim e os meus olhos o viram; eis que não me disseram metade; sobrepujaste em sabedoria e bens a fama que ouvi.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 8, 'Bem-aventurados os teus homens, bem-aventurados estes teus servos, que estão sempre diante de ti, que ouvem a tua sabedoria!', 2, CURRENT_TIMESTAMP, false),
(11, 10, 9, 'Bendito seja o Senhor teu Deus, que teve agrado em ti, para te pôr no trono de Israel; porque o Senhor ama a Israel para sempre, por isso te estabeleceu rei, para fazeres juízo e justiça.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 10, 'E deu ao rei cento e vinte talentos de ouro, e muitíssimas especiarias, e pedras preciosas; nunca veio especiaria em tanta abundância, como a que a rainha de Sabá deu ao rei Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 11, 'Também as naus de Hirão, que de Ofir levavam ouro, traziam de Ofir muita madeira de almugue, e pedras preciosas.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 12, 'E desta madeira de almugue fez o rei balaústres para a casa do Senhor, e para a casa do rei, como também harpas e alaúdes para os cantores; nunca veio tal madeira de almugue, nem se viu até o dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 13, 'E o rei Salomão deu à rainha de Sabá tudo o que ela desejou, tudo quanto pediu, além do que dera por sua generosidade; então voltou e partiu para a sua terra, ela e os seus servos.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 14, 'E o peso do ouro que se trazia a Salomão cada ano era de seiscentos e sessenta e seis talentos de ouro;', 2, CURRENT_TIMESTAMP, false),
(11, 10, 15, 'Além do que entrava dos negociantes, e do contrato dos especieiros, e de todos os reis da Arábia, e dos governadores da mesma terra.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 16, 'Também o rei Salomão fez duzentos paveses de ouro batido; seiscentos siclos de ouro destinou para cada pavês;', 2, CURRENT_TIMESTAMP, false),
(11, 10, 17, 'Fez também trezentos escudos de ouro batido; três arráteis de ouro destinou para cada escudo; e o rei os pôs na casa do bosque do Líbano.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 18, 'Fez mais o rei um grande trono de marfim, e o revestiu de ouro puríssimo.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 19, 'Tinha este trono seis degraus, e era o alto do trono por detrás redondo, e de ambos os lados tinha encostos até ao assento; e dois leões, em pé, juntos aos encostos.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 20, 'Também doze leões estavam ali sobre os seis degraus de ambos os lados; nunca se tinha feito obra semelhante em nenhum dos reinos.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 21, 'Também todas as taças de beber do rei Salomão eram de ouro, e todos os vasos da casa do bosque do Líbano eram de ouro puro; não havia neles prata, porque nos dias de Salomão não tinha valor algum.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 22, 'Porque o rei tinha no mar as naus de Társis, com as naus de Hirão; uma vez em três anos tornavam as naus de Társis, e traziam ouro e prata, marfim, e bugios, e pavões.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 23, 'Assim o rei Salomão excedeu a todos os reis da terra, tanto em riquezas como em sabedoria.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 24, 'E toda a terra buscava a face de Salomão, para ouvir a sabedoria que Deus tinha posto no seu coração.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 25, 'E cada um trazia o seu presente, vasos de prata e vasos de ouro, e roupas, e armaduras, e especiarias, cavalos e mulas; isso faziam de ano em ano.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 26, 'Também ajuntou Salomão carros e cavaleiros, de sorte que tinha mil e quatrocentos carros e doze mil cavaleiros; e os levou às cidades dos carros, e junto ao rei em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 27, 'E fez o rei que em Jerusalém houvesse prata como pedras; e cedros em abundância como sicômoros que estão nas planícies.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 28, 'E traziam do Egito, para Salomão, cavalos e fio de linho; e os mercadores do rei recebiam o fio de linho, por um certo preço.', 2, CURRENT_TIMESTAMP, false),
(11, 10, 29, 'E subia e saía um carro do Egito por seiscentos siclos de prata, e um cavalo por cento e cinqüenta; e assim, por meio deles, eram exportados para todos os reis dos heteus e para os reis da Síria.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 1, 'E o rei Salomão amou muitas mulheres estrangeiras, além da filha de Faraó: moabitas, amonitas, edomitas, sidônias e hetéias,', 2, CURRENT_TIMESTAMP, false),
(11, 11, 2, 'Das nações de que o Senhor tinha falado aos filhos de Israel: Não chegareis a elas, e elas não chegarão a vós; de outra maneira perverterão o vosso coração para seguirdes os seus deuses. A estas se uniu Salomão com amor.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 3, 'E tinha setecentas mulheres, princesas, e trezentas concubinas; e suas mulheres lhe perverteram o coração.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 4, 'Porque sucedeu que, no tempo da velhice de Salomão, suas mulheres lhe perverteram o coração para seguir outros deuses; e o seu coração não era perfeito para com o Senhor seu Deus, como o coração de Davi, seu pai,', 2, CURRENT_TIMESTAMP, false),
(11, 11, 5, 'Porque Salomão seguiu a Astarote, deusa dos sidônios, e Milcom, a abominação dos amonitas.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 6, 'Assim fez Salomão o que parecia mal aos olhos do Senhor; e não perseverou em seguir ao Senhor, como Davi, seu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 7, 'Então edificou Salomão um alto a Quemós, a abominação dos moabitas, sobre o monte que está diante de Jerusalém, e a Moloque, a abominação dos filhos de Amom.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 8, 'E assim fez para com todas as suas mulheres estrangeiras, as quais queimavam incenso e sacrificavam a seus deuses.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 9, 'Pelo que o Senhor se indignou contra Salomão; porquanto desviara o seu coração do Senhor Deus de Israel, o qual duas vezes lhe aparecera.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 10, 'E acerca deste assunto lhe tinha dado ordem que não seguisse a outros deuses; porém não guardou o que o Senhor lhe ordenara.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 11, 'Assim disse o Senhor a Salomão: Pois que houve isto em ti, que não guardaste a minha aliança e os meus estatutos que te mandei, certamente rasgarei de ti este reino, e o darei a teu servo.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 12, 'Todavia nos teus dias não o farei, por amor de Davi, teu pai; da mão de teu filho o rasgarei;', 2, CURRENT_TIMESTAMP, false),
(11, 11, 13, 'Porém todo o reino não rasgarei; uma tribo darei a teu filho, por amor de meu servo Davi, e por amor a Jerusalém, que tenho escolhido.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 14, 'Levantou, pois, o Senhor contra Salomão um adversário, Hadade, o edomeu; ele era da descendência do rei em Edom.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 15, 'Porque sucedeu que, estando Davi em Edom, e subindo Joabe, o capitão do exército, a enterrar os mortos, feriu a todo o homem em Edom', 2, CURRENT_TIMESTAMP, false),
(11, 11, 16, '(Porque Joabe ficou ali seis meses com todo o Israel, até que destruiu a todo o homem em Edom).', 2, CURRENT_TIMESTAMP, false),
(11, 11, 17, 'Hadade, porém, fugiu, ele e alguns homens edomeus, dos servos de seu pai, com ele, para ir ao Egito; era, porém, Hadade muito jovem.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 18, 'E levantaram-se de Midiã, e foram a Parã, e tomaram consigo homens de Parã, e foram ao Egito ter com Faraó, rei do Egito, o qual lhe deu uma casa, e lhe prometeu sustento, e lhe deu uma terra.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 19, 'E achou Hadade grande graça diante de Faraó, de maneira que lhe deu por mulher a irmã de sua mulher, a irmã de Tafnes, a rainha.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 20, 'E a irmã de Tafnes deu-lhe um filho, Genubate, o qual Tafnes criou na casa de Faraó; e Genubate estava na casa de Faraó, entre os filhos de Faraó.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 21, 'Ouvindo, pois, Hadade, no Egito, que Davi adormecera com seus pais, e que Joabe, capitão do exército, era morto, disse Hadade a Faraó: Despede-me, para que vá à minha terra.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 22, 'Porém Faraó lhe disse: Pois que te falta comigo, que procuras partir para a tua terra? E disse ele: Nada, mas todavia despede-me.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 23, 'Também Deus lhe levantou outro adversário, a Rezom, filho de Eliada, que tinha fugido de seu senhor Hadadezer, rei de Zobá,', 2, CURRENT_TIMESTAMP, false),
(11, 11, 24, 'Contra quem também ajuntou homens, e foi capitão de um esquadrão, quando Davi os matou; e, indo-se para Damasco, habitaram ali, e reinaram em Damasco.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 25, 'E foi adversário de Israel, por todos os dias de Salomão, e isto além do mal que Hadade fazia; porque detestava a Israel, e reinava sobre a Síria.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 26, 'Até Jeroboão, filho de Nebate, efrateu, de Zereda, servo de Salomão (cuja mãe era mulher viúva, por nome Zerua), também levantou a mão contra o rei.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 27, 'E esta foi a causa por que levantou a mão contra o rei: Salomão tinha edificado a Milo, e cerrou as aberturas da cidade de Davi, seu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 28, 'E o homem Jeroboão era forte e valente; e vendo Salomão a este jovem, que era laborioso, ele o pôs sobre todo o cargo da casa de José.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 29, 'Sucedeu, pois, naquele tempo que, saindo Jeroboão de Jerusalém, o profeta Aías, o silonita, o encontrou no caminho, e ele estava vestido com uma roupa nova, e os dois estavam sós no campo.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 30, 'E Aías pegou na roupa nova que tinha sobre si, e a rasgou em doze pedaços.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 31, 'E disse a Jeroboão: Toma para ti os dez pedaços, porque assim diz o Senhor Deus de Israel: Eis que rasgarei o reino da mão de Salomão, e a ti darei as dez tribos.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 32, 'Porém ele terá uma tribo, por amor de Davi, meu servo, e por amor de Jerusalém, a cidade que escolhi de todas as tribos de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 33, 'Porque me deixaram, e se encurvaram a Astarote, deusa dos sidônios, a Quemós, deus dos moabitas, e a Milcom, deus dos filhos de Amom; e não andaram pelos meus caminhos, para fazerem o que é reto aos meus olhos, a saber, os meus estatutos e os meus juízos, como Davi, seu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 34, 'Porém não tomarei nada deste reino da sua mão; mas por príncipe o ponho por todos os dias da sua vida, por amor de Davi, meu servo, a quem escolhi, o qual guardou os meus mandamentos e os meus estatutos.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 35, 'Mas da mão de seu filho tomarei o reino, e darei a ti, as dez tribos dele.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 36, 'E a seu filho darei uma tribo; para que Davi, meu servo, sempre tenha uma lâmpada diante de mim em Jerusalém, a cidade que escolhi para pôr ali o meu nome.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 37, 'E te tomarei, e reinarás sobre tudo o que desejar a tua alma; e serás rei sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 38, 'E há de ser que, se ouvires tudo o que eu te mandar, e andares pelos meus caminhos, e fizeres o que é reto aos meus olhos, guardando os meus estatutos e os meus mandamentos, como fez Davi, meu servo, eu serei contigo, e te edificarei uma casa firme, como edifiquei a Davi, e te darei Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 39, 'E por isso afligirei a descendência de Davi; todavia não para sempre.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 40, 'Assim Salomão procurou matar Jeroboão; porém Jeroboão se levantou, e fugiu para o Egito, a ter com Sisaque, rei do Egito; e esteve no Egito até que Salomão morreu.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 41, 'Quanto ao mais dos atos de Salomão, e a tudo quanto fez, e à sua sabedoria, porventura não está escrito no livro dos feitos de Salomão?', 2, CURRENT_TIMESTAMP, false),
(11, 11, 42, 'E o tempo que reinou Salomão, em Jerusalém, sobre todo o Israel foi quarenta anos.', 2, CURRENT_TIMESTAMP, false),
(11, 11, 43, 'E adormeceu Salomão com seus pais, e foi sepultado na cidade de Davi, seu pai; e Roboão, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 1, 'E foi Roboão para Siquém; porque todo o Israel se reuniu em Siquém, para o fazerem rei.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 2, 'Sucedeu que, Jeroboão, filho de Nebate, achando-se ainda no Egito, para onde fugira de diante do rei Salomão, voltou do Egito,', 2, CURRENT_TIMESTAMP, false),
(11, 12, 3, 'Porque mandaram chamá-lo; veio, pois, Jeroboão e toda a congregação de Israel, e falaram a Roboão, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 12, 4, 'Teu pai agravou o nosso jugo; agora, pois, alivia tu a dura servidão de teu pai, e o pesado jugo que nos impôs, e nós te serviremos.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 5, 'E ele lhes disse: Ide-vos até ao terceiro dia, e então voltai a mim. E o povo se foi.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 6, 'E teve o rei Roboão conselho com os anciãos que estiveram na presença de Salomão, seu pai, quando este ainda vivia, dizendo: Como aconselhais vós que se responda a este povo?', 2, CURRENT_TIMESTAMP, false),
(11, 12, 7, 'E eles lhe falaram, dizendo: Se hoje fores servo deste povo, e o servires, e respondendo-lhe, lhe falares boas palavras, todos os dias serão teus servos.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 8, 'Porém ele deixou o conselho que os anciãos lhe tinham dado, e teve conselho com os jovens que haviam crescido com ele, que estavam diante dele.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 9, 'E disse-lhes: Que aconselhais vós que respondamos a este povo, que me falou, dizendo: Alivia o jugo que teu pai nos impôs?', 2, CURRENT_TIMESTAMP, false),
(11, 12, 10, 'E os jovens que haviam crescido com ele lhe falaram: Assim dirás a este povo que te falou: Teu pai fez pesadíssimo o nosso jugo, mas tu o alivia de sobre nós; assim lhe falarás: Meu dedo mínimo é mais grosso do que os lombos de meu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 11, 'Assim que, se meu pai vos carregou de um jugo pesado, ainda eu aumentarei o vosso jugo; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 12, 'Veio, pois, Jeroboão e todo o povo, ao terceiro dia, a Roboão, como o rei havia ordenado, dizendo: Voltai a mim ao terceiro dia.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 13, 'E o rei respondeu ao povo duramente; porque deixara o conselho que os anciãos lhe haviam dado.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 14, 'E lhe falou conforme ao conselho dos jovens, dizendo: Meu pai agravou o vosso jugo, porém eu ainda aumentarei o vosso jugo; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 15, 'O rei, pois, não deu ouvidos ao povo; porque esta revolta vinha do Senhor, para confirmar a palavra que o Senhor tinha falado pelo ministério de Aías, o silonita, a Jeroboão, filho de Nebate.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 16, 'Vendo, pois, todo o Israel que o rei não lhe dava ouvidos, tornou-lhe o povo a responder, dizendo: Que parte temos nós com Davi? Não há para nós herança no filho de Jessé. Às tuas tendas, ó Israel! Provê agora a tua casa, ó Davi. Então Israel se foi às suas tendas.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 17, 'No tocante, porém, aos filhos de Israel que habitavam nas cidades de Judá, também sobre eles reinou Roboão.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 18, 'Então o rei Roboão enviou a Adorão, que estava sobre os tributos; e todo o Israel o apedrejou, e ele morreu; mas o rei Roboão se animou a subir ao carro para fugir para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 19, 'Assim se rebelaram os israelitas contra a casa de Davi, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 20, 'E sucedeu que, ouvindo todo o Israel que Jeroboão tinha voltado, enviaram, e o chamaram para a congregação, e o fizeram rei sobre todo o Israel; e ninguém seguiu a casa de Davi senão somente a tribo de Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 21, 'Vindo, pois, Roboão a Jerusalém, reuniu toda a casa de Judá e a tribo de Benjamim, cento e oitenta mil escolhidos, destros para a guerra, para pelejar contra a casa de Israel, para restituir o reino a Roboão, filho de Salomão.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 22, 'Porém veio a palavra de Deus a Semaías, homem de Deus, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 12, 23, 'Fala a Roboão, filho de Salomão, rei de Judá, e a toda a casa de Judá, e a Benjamim, e ao restante do povo, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 12, 24, 'Assim diz o Senhor: Não subireis nem pelejareis contra vossos irmãos, os filhos de Israel; volte cada um para a sua casa, porque eu é que fiz esta obra. E ouviram a palavra do Senhor, e voltaram segundo a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 25, 'E Jeroboão edificou a Siquém, no monte de Efraim, e habitou ali; e saiu dali, e edificou a Penuel.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 26, 'E disse Jeroboão no seu coração: Agora tornará o reino à casa de Davi.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 27, 'Se este povo subir para fazer sacrifícios na casa do SENHOR, em Jerusalém, o coração deste povo se tornará a seu senhor, a Roboão, rei de Judá; e me matarão, e tornarão a Roboão, rei de Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 28, 'Assim o rei tomou conselho, e fez dois bezerros de ouro; e lhes disse: Muito trabalho vos será o subir a Jerusalém; vês aqui teus deuses, ó Israel, que te fizeram subir da terra do Egito.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 29, 'E pôs um em Betel, e colocou o outro em Dã.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 30, 'E este feito se tornou em pecado; pois que o povo ia até Dã para adorar o bezerro.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 31, 'Também fez casa nos altos; e constituiu sacerdotes dos mais baixos do povo, que não eram dos filhos de Levi.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 32, 'E fez Jeroboão uma festa no oitavo mês, no dia décimo quinto do mês, como a festa que se fazia em Judá, e sacrificou no altar; semelhantemente fez em Betel, sacrificando aos bezerros que fizera; também em Betel estabeleceu sacerdotes dos altos que fizera.', 2, CURRENT_TIMESTAMP, false),
(11, 12, 33, 'E sacrificou no altar que fizera em Betel, no dia décimo quinto do oitavo mês, que ele tinha imaginado no seu coração; assim fez a festa aos filhos de Israel, e sacrificou no altar, queimando incenso.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 1, 'E eis que, por ordem do SENHOR, veio, de Judá a Betel, um homem de Deus; e Jeroboão estava junto ao altar, para queimar incenso.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 2, 'E ele clamou contra o altar por ordem do Senhor, e disse: Altar, altar! Assim diz o Senhor: Eis que um filho nascerá à casa de Davi, cujo nome será Josias, o qual sacrificará sobre ti os sacerdotes dos altos que sobre ti queimam incenso, e ossos de homens se queimarão sobre ti.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 3, 'E deu, naquele mesmo dia, um sinal, dizendo: Este é o sinal de que o Senhor falou: Eis que o altar se fenderá, e a cinza, que nele está, se derramará.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 4, 'Sucedeu, pois, que, ouvindo o rei a palavra do homem de Deus, que clamara contra o altar de Betel, Jeroboão estendeu a sua mão de sobre o altar, dizendo: Pegai-o! Mas a sua mão, que estendera contra ele, se secou, e não podia tornar a trazê-la a si.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 5, 'E o altar se fendeu, e a cinza se derramou do altar, segundo o sinal que o homem de Deus apontara por ordem do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 6, 'Então respondeu o rei, e disse ao homem de Deus: Suplica ao Senhor teu Deus, e roga por mim, para que se me restitua a minha mão. Então o homem de Deus suplicou ao Senhor, e a mão do rei se lhe restituiu, e ficou como dantes.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 7, 'E o rei disse ao homem de Deus: Vem comigo para casa, e conforta-te; e dar-te-ei um presente.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 8, 'Porém o homem de Deus disse ao rei: Ainda que me desses metade da tua casa, não iria contigo, nem comeria pão nem beberia água neste lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 9, 'Porque assim me ordenou o Senhor pela sua palavra, dizendo: Não comerás pão nem beberás água; e não voltarás pelo caminho por onde vieste.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 10, 'Assim foi por outro caminho; e não voltou pelo caminho, por onde viera a Betel.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 11, 'E morava em Betel um velho profeta; e vieram seus filhos, e contaram-lhe tudo o que o homem de Deus fizera aquele dia em Betel, e as palavras que dissera ao rei; e as contaram a seu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 12, 'E disse-lhes seu pai: Por que caminho se foi? E seus filhos lhe mostraram o caminho por onde fora o homem de Deus que viera de Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 13, 'Então disse a seus filhos: Albardai-me um jumento. E albardaram-lhe o jumento no qual ele montou.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 14, 'E foi após o homem de Deus, e achou-o assentado debaixo de um carvalho, e disse-lhe: És tu o homem de Deus que vieste de Judá? E ele disse: Sou.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 15, 'Então lhe disse: Vem comigo à casa, e come pão.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 16, 'Porém ele disse: Não posso voltar contigo, nem entrarei contigo; nem tampouco comerei pão, nem beberei contigo água neste lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 17, 'Porque me foi mandado pela palavra do Senhor: Ali não comerás pão, nem beberás água; nem voltarás pelo caminho por onde vieste.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 18, 'E ele lhe disse: Também eu sou profeta como tu, e um anjo me falou por ordem do Senhor, dizendo: Faze-o voltar contigo à tua casa, para que coma pão e beba água (porém mentiu-lhe).', 2, CURRENT_TIMESTAMP, false),
(11, 13, 19, 'Assim voltou com ele, e comeu pão em sua casa e bebeu água.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 20, 'E sucedeu que, estando eles à mesa, a palavra do Senhor veio ao profeta que o tinha feito voltar.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 21, 'E clamou ao homem de Deus, que viera de Judá, dizendo: Assim diz o Senhor: Porquanto foste rebelde à ordem do Senhor, e não guardaste o mandamento que o Senhor teu Deus te mandara,', 2, CURRENT_TIMESTAMP, false),
(11, 13, 22, 'Antes voltaste, e comeste pão e bebeste água no lugar de que o Senhor te dissera: Não comerás pão nem beberás água; o teu cadáver não entrará no sepulcro de teus pais.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 23, 'E sucedeu que, depois que comeu pão, e depois que bebeu, albardou ele o jumento para o profeta que fizera voltar.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 24, 'Este, pois, se foi, e um leão o encontrou no caminho, e o matou; e o seu cadáver ficou estendido no caminho, e o jumento estava parado junto a ele, e também o leão estava junto ao cadáver.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 25, 'E eis que alguns homens passaram, e viram o corpo lançado no caminho, como também o leão, que estava junto ao corpo; e foram, e o disseram na cidade onde o velho profeta habitava.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 26, 'E, ouvindo-o o profeta que o fizera voltar do caminho, disse: É o homem de Deus, que foi rebelde à ordem do Senhor; por isso o Senhor o entregou ao leão, que o despedaçou e matou, segundo a palavra que o Senhor lhe dissera.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 27, 'Então disse a seus filhos: Albardai-me o jumento. Eles o albardaram.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 28, 'Então foi, e achou o cadáver estendido no caminho, e o jumento e o leão, que estavam parados junto ao cadáver; e o leão não tinha devorado o corpo, nem tinha despedaçado o jumento.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 29, 'Então o profeta levantou o cadáver do homem de Deus, e pô-lo em cima do jumento levando-o consigo; assim veio o velho profeta à cidade, para o chorar e enterrar.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 30, 'E colocou o cadáver no seu próprio sepulcro; e prantearam-no, dizendo: Ah, irmão meu!', 2, CURRENT_TIMESTAMP, false),
(11, 13, 31, 'E sucedeu que, depois de o haver sepultado, disse a seus filhos: Morrendo eu, sepultai-me no sepulcro em que o homem de Deus está sepultado; ponde os meus ossos junto aos ossos dele.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 32, 'Porque certamente se cumprirá o que pela palavra do Senhor exclamou contra o altar que está em Betel, como também contra todas as casas dos altos que estão nas cidades de Samaria.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 33, 'Nem depois destas coisas deixou Jeroboão o seu mau caminho; antes, de todo o povo, tornou a constituir sacerdotes dos lugares altos; e a qualquer que queria consagrava sacerdote dos lugares altos.', 2, CURRENT_TIMESTAMP, false),
(11, 13, 34, 'E isso foi causa de pecado à casa de Jeroboão, para destruí-la e extingui-la da terra.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 1, 'Naquele tempo adoeceu Abias, filho de Jeroboão.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 2, 'E disse Jeroboão à sua mulher: Levanta-te agora, e disfarça-te, para que não conheçam que és mulher de Jeroboão; e vai a Siló. Eis que lá está o profeta Aías, o qual falou de mim, que eu seria rei sobre este povo.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 3, 'E leva contigo dez pães, e bolos, e uma botija de mel, e vai a ele; ele te declarará o que há de suceder a este menino.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 4, 'E a mulher de Jeroboão assim fez, e se levantou, e foi a Siló, e entrou na casa de Aías; e já Aías não podia ver, porque os seus olhos estavam já escurecidos por causa da sua velhice.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 5, 'Porém o Senhor disse a Aías: Eis que a mulher de Jeroboão vem consultar-te sobre seu filho, porque está doente; assim e assim lhe falarás; porque há de ser que, entrando ela, fingirá ser outra.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 6, 'E sucedeu que, ouvindo Aías o ruído de seus pés, entrando ela pela porta, disse-lhe ele: Entra, mulher de Jeroboão; por que te disfarças assim? Pois eu sou enviado a ti com duras novas.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 7, 'Vai, dize a Jeroboão: Assim diz o Senhor Deus de Israel: Porquanto te levantei do meio do povo, e te pus por príncipe sobre o meu povo de Israel,', 2, CURRENT_TIMESTAMP, false),
(11, 14, 8, 'E rasguei o reino da casa de Davi, e o dei a ti, e tu não foste como o meu servo Davi, que guardou os meus mandamentos e que andou após mim com todo o seu coração para fazer somente o que era reto aos meus olhos,', 2, CURRENT_TIMESTAMP, false),
(11, 14, 9, 'Antes tu fizeste o mal, pior do que todos os que foram antes de ti; e foste, e fizeste outros deuses e imagens de fundição, para provocar-me à ira, e me lançaste para trás das tuas costas;', 2, CURRENT_TIMESTAMP, false),
(11, 14, 10, 'Portanto, eis que trarei mal sobre a casa de Jeroboão; destruirei de Jeroboão todo o homem até ao menino, tanto o escravo como o livre em Israel; e lançarei fora os descendentes da casa de Jeroboão, como se lança fora o esterco, até que de todo se acabe.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 11, 'Quem morrer dos de Jeroboão, na cidade, os cães o comerão, e o que morrer no campo as aves do céu o comerão, porque o Senhor o disse.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 12, 'Tu, pois, levanta-te, e vai para tua casa; entrando os teus pés na cidade, o menino morrerá.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 13, 'E todo o Israel o pranteará, e o sepultará; porque de Jeroboão só este entrará em sepultura, porquanto se achou nele coisa boa para com o Senhor Deus de Israel em casa de Jeroboão.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 14, 'O Senhor, porém, levantará para si um rei sobre Israel, que destruirá a casa de Jeroboão no mesmo dia. Que digo eu? Há de ser já.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 15, 'Também o Senhor ferirá a Israel como se agita a cana nas águas; e arrancará a Israel desta boa terra que tinha dado a seus pais, e o espalhará para além do rio; porquanto fizeram os seus ídolos, provocando o Senhor à ira.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 16, 'E entregará a Israel por causa dos pecados de Jeroboão, o qual pecou, e fez pecar a Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 17, 'Então a mulher de Jeroboão se levantou, e foi, e chegou a Tirza; chegando ela ao limiar da porta, morreu o menino.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 18, 'E o sepultaram, e todo o Israel o pranteou, conforme a palavra do Senhor, a qual dissera pelo ministério de seu servo Aías, o profeta.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 19, 'Quanto ao mais dos atos de Jeroboão, como guerreou, e como reinou, eis que está escrito no livro das crônicas dos reis de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 20, 'E foram os dias que Jeroboão reinou vinte e dois anos; e dormiu com seus pais; e Nadabe, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 21, 'E Roboão, filho de Salomão, reinava em Judá; de quarenta e um anos de idade era Roboão quando começou a reinar, e dezessete anos reinou em Jerusalém, na cidade que o Senhor escolhera de todas as tribos de Israel para pôr ali o seu nome; e era o nome de sua mãe Naamá, amonita.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 22, 'E fez Judá o que era mau aos olhos do Senhor; e com os seus pecados que cometeram, provocaram-no a zelos, mais do que todos os seus pais fizeram.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 23, 'Porque também eles edificaram altos, e estátuas, e imagens de Aserá sobre todo o alto outeiro e debaixo de toda a árvore verde.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 24, 'Havia também sodomitas na terra; fizeram conforme a todas as abominações dos povos que o Senhor tinha expulsado de diante dos filhos de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 25, 'Ora, sucedeu que, no quinto ano do rei Roboão, Sisaque, rei do Egito, subiu contra Jerusalém,', 2, CURRENT_TIMESTAMP, false),
(11, 14, 26, 'E tomou os tesouros da casa do Senhor e os tesouros da casa do rei; e levou tudo. Também tomou todos os escudos de ouro que Salomão tinha feito.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 27, 'E em lugar deles fez o rei Roboão escudos de cobre, e os entregou nas mãos dos chefes da guarda que guardavam a porta da casa do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 28, 'E todas as vezes que o rei entrava na casa do Senhor, os da guarda os levavam, e depois os tornavam à câmara da guarda.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 29, 'Quanto ao mais dos atos de Roboão, e a tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá?', 2, CURRENT_TIMESTAMP, false),
(11, 14, 30, 'E houve guerra entre Roboão e Jeroboão todos os seus dias.', 2, CURRENT_TIMESTAMP, false),
(11, 14, 31, 'E Roboão dormiu com seus pais, e foi sepultado com seus pais na cidade de Davi; e era o nome de sua mãe Naamá, amonita; e Abias, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 1, 'E no décimo oitavo ano do rei Jeroboão, filho de Nebate, Abias começou a reinar sobre Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 2, 'E reinou três anos em Jerusalém; e era o nome de sua mãe Maaca, filha de Absalão.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 3, 'E andou em todos os pecados que seu pai tinha cometido antes dele; e seu coração não foi perfeito para com o Senhor seu Deus como o coração de Davi, seu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 4, 'Mas por amor de Davi o Senhor seu Deus lhe deu uma lâmpada em Jerusalém, levantando a seu filho depois dele, e confirmando a Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 5, 'Porquanto Davi tinha feito o que era reto aos olhos do Senhor, e não se tinha desviado de tudo quanto lhe ordenara em todos os dias da sua vida, senão só no negócio de Urias, o heteu.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 6, 'E houve guerra entre Roboão e Jeroboão todos os dias da sua vida.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 7, 'Quanto ao mais dos atos de Abias, e a tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá? Também houve guerra entre Abias e Jeroboão.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 8, 'E Abias dormiu com seus pais, e o sepultaram na cidade de Davi; e Asa, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 9, 'E no vigésimo ano de Jeroboão, rei de Israel, começou Asa a reinar em Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 10, 'E quarenta e um anos reinou em Jerusalém; e era o nome de sua mãe Maaca, filha de Absalão.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 11, 'E Asa fez o que era reto aos olhos do Senhor, como Davi seu pai.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 12, 'Porque tirou da terra os sodomitas, e removeu todos os ídolos que seus pais fizeram.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 13, 'E até a Maaca, sua mãe, removeu para que não fosse rainha, porquanto tinha feito um horrível ídolo a Aserá; também Asa desfez o seu ídolo horrível, e o queimou junto ao ribeiro de Cedrom.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 14, 'Os altos, porém, não foram tirados; todavia foi o coração de Asa reto para com o Senhor todos os seus dias.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 15, 'E à casa do Senhor trouxe as coisas consagradas por seu pai, e as coisas que ele mesmo consagrara; prata, ouro e vasos.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 16, 'E houve guerra entre Asa e Baasa, rei de Israel, todos os seus dias.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 17, 'Porque Baasa, rei de Israel, subiu contra Judá, e edificou a Ramá, para que a ninguém fosse permitido sair, nem entrar a ter com Asa, rei de Judá.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 18, 'Então Asa tomou toda a prata e ouro que ficaram nos tesouros da casa do Senhor, e os tesouros da casa do rei, e os entregou nas mãos de seus servos; e o rei Asa os enviou a Ben-Hadade, filho de Tabrimom, filho de Heziom, rei da Síria, que habitava em Damasco, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 15, 19, 'Haja acordo entre mim e ti, como houve entre meu pai e teu pai; eis que te mando um presente, prata e ouro; vai, e anula o teu acordo com Baasa, rei de Israel, para que se retire de sobre mim.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 20, 'E Ben-Hadade deu ouvidos ao rei Asa, e enviou os capitães dos seus exércitos contra as cidades de Israel; e feriu a Ijom, e a Dã, e a Abel-Bete-Maaca, e a toda a Quinerete, com toda a terra de Naftali.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 21, 'E sucedeu que, ouvindo-o Baasa, deixou de edificar a Ramá; e ficou em Tirza.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 22, 'Então o rei Asa fez apregoar por toda a Judá que todos, sem exceção, trouxessem as pedras de Ramá, e a sua madeira com que Baasa edificara; e com elas edificou o rei Asa a Geba de Benjamim e a Mizpá.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 23, 'Quanto ao mais de todos os atos de Asa, e a todo o seu poder, e a tudo quanto fez, e as cidades que edificou, porventura não está escrito no livro das crônicas dos reis de Judá? Porém, no tempo da sua velhice, padeceu dos pés.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 24, 'E Asa dormiu com seus pais, e foi sepultado com seus pais na cidade de Davi, seu pai; e Jeosafá, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 25, 'E Nadabe, filho de Jeroboão, começou a reinar sobre Israel no ano segundo de Asa, rei de Judá; e reinou sobre Israel dois anos.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 26, 'E fez o que era mau aos olhos do Senhor; e andou nos caminhos de seu pai, e no seu pecado com que seu pai fizera pecar a Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 27, 'E conspirou contra ele Baasa, filho de Aías, da casa de Issacar, e feriu-o Baasa em Gibetom, que era dos filisteus, quando Nadabe e todo o Israel cercavam a Gibetom.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 28, 'E matou-o, pois, Baasa no ano terceiro de Asa, rei de Judá, e reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 29, 'Sucedeu que, reinando ele, feriu a toda a casa de Jeroboão; nada de Jeroboão deixou que tivesse fôlego, até o destruir, conforme à palavra do Senhor que dissera pelo ministério de seu servo Aías, o silonita.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 30, 'Por causa dos pecados que Jeroboão cometera, e fez pecar a Israel, e por causa da provocação com que irritara ao Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 31, 'Quanto ao mais dos atos de Nadabe, e a tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 15, 32, 'E houve guerra entre Asa e Baasa, rei de Israel, todos os seus dias.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 33, 'No ano terceiro de Asa, rei de Judá, Baasa, filho de Aías, começou a reinar sobre todo o Israel em Tirza, e reinou vinte e quatro anos.', 2, CURRENT_TIMESTAMP, false),
(11, 15, 34, 'E fez o que era mau aos olhos do Senhor; e andou no caminho de Jeroboão, e no pecado com que ele tinha feito Israel pecar.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 1, 'Então veio a palavra do SENHOR a Jeú, filho de Hanani, contra Baasa, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 16, 2, 'Porquanto te levantei do pó, e te pus por príncipe sobre o meu povo Israel, e tu tens andado no caminho de Jeroboão, e tens feito pecar a meu povo Israel, irritando-me com os seus pecados,', 2, CURRENT_TIMESTAMP, false),
(11, 16, 3, 'Eis que tirarei os descendentes de Baasa, e os descendentes da sua casa, e farei a tua casa como a casa de Jeroboão, filho de Nebate.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 4, 'Quem morrer dos de Baasa, na cidade, os cães o comerão; e o que dele morrer no campo, as aves do céu o comerão.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 5, 'Quanto ao mais dos atos de Baasa, e ao que fez, e ao seu poder, porventura não está escrito no livro das crônicas dos reis de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 16, 6, 'E Baasa dormiu com seus pais, e foi sepultado em Tirza; e Elá, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 7, 'Assim veio também a palavra do Senhor, pelo ministério do profeta Jeú, filho de Hanani, contra Baasa e contra a sua casa; e isso por todo o mal que fizera aos olhos do Senhor, irritando-o com a obra de suas mãos, para ser como a casa de Jeroboão; e porque o havia ferido.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 8, 'No ano vinte e seis de Asa, rei de Judá, Elá, filho de Baasa, começou a reinar em Tirza sobre Israel; e reinou dois anos.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 9, 'E Zinri, seu servo, capitão de metade dos carros, conspirou contra ele, estando ele em Tirza, bebendo e embriagando-se em casa de Arsa, mordomo em Tirza.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 10, 'Entrou, pois, Zinri, e o feriu, e o matou, no ano vigésimo sétimo de Asa, rei de Judá; e reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 11, 'E sucedeu que, reinando ele, e estando assentado no seu trono, feriu a toda a casa de Baasa; não lhe deixou homem algum, nem a seus parentes, nem a seus amigos.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 12, 'Assim destruiu Zinri toda a casa de Baasa, conforme à palavra do Senhor que, contra Baasa, ele falara pelo ministério do profeta Jeú,', 2, CURRENT_TIMESTAMP, false),
(11, 16, 13, 'Por todos os pecados de Baasa, e os pecados de Elá, seu filho, que cometeram, e com que fizeram pecar a Israel, irritando ao Senhor Deus de Israel com as suas vaidades.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 14, 'Quanto ao mais dos atos de Elá, e a tudo quanto fez, não está escrito no livro das crônicas dos reis de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 16, 15, 'No ano vigésimo sétimo de Asa, rei de Judá, reinou Zinri sete dias em Tirza; e o povo estava acampado contra Gibetom, que era dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 16, 'E o povo que estava acampado ouviu dizer: Zinri tem conspirado, e até matou o rei. Todo o Israel pois, no mesmo dia, no arraial, constituiu rei sobre Israel a Onri, capitão do exército.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 17, 'E subiu Onri, e todo o Israel com ele, de Gibetom, e cercaram a Tirza.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 18, 'E sucedeu que Zinri, vendo que a cidade era tomada, foi ao paço da casa do rei e queimou-a sobre si; e morreu,', 2, CURRENT_TIMESTAMP, false),
(11, 16, 19, 'Por causa dos pecados que cometera, fazendo o que era mau aos olhos do Senhor, andando no caminho de Jeroboão, e no pecado que ele cometera, fazendo Israel pecar.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 20, 'Quanto ao mais dos atos de Zinri, e à conspiração que fez, porventura não está escrito no livro das crônicas dos reis de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 16, 21, 'Então o povo de Israel se dividiu em dois partidos: metade do povo seguia a Tibni, filho de Ginate, para o fazer rei, e a outra metade seguia a Onri.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 22, 'Mas o povo que seguia a Onri foi mais forte do que o povo que seguia a Tibni, filho de Ginate; e Tibni morreu, e Onri reinou.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 23, 'No ano trinta e um de Asa, rei de Judá, Onri começou a reinar sobre Israel, e reinou doze anos; e em Tirza reinou seis anos.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 24, 'E de Semer comprou o monte de Samaria por dois talentos de prata, e edificou nele; e chamou a cidade que edificou Samaria, do nome de Semer, dono do monte.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 25, 'E fez Onri o que era mau aos olhos do Senhor; e fez pior do que todos quantos foram antes dele.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 26, 'E andou em todos os caminhos de Jeroboão, filho de Nebate, como também nos pecados com que ele tinha feito pecar a Israel, irritando ao Senhor Deus de Israel com as suas vaidades.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 27, 'Quanto ao mais dos atos de Onri, ao que fez, e ao poder que manifestou, porventura não está escrito no livro das crônicas dos reis de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 16, 28, 'E Onri dormiu com seus pais, e foi sepultado em Samaria; e Acabe, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 29, 'E Acabe, filho de Onri, começou a reinar sobre Israel no ano trigésimo oitavo de Asa, rei de Judá; e reinou Acabe, filho de Onri, sobre Israel, em Samaria, vinte e dois anos.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 30, 'E fez Acabe, filho de Onri, o que era mau aos olhos do Senhor, mais do que todos os que foram antes dele.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 31, 'E sucedeu que (como se fora pouco andar nos pecados de Jeroboão, filho de Nebate) ainda tomou por mulher a Jezabel, filha de Etbaal, rei dos sidônios; e foi e serviu a Baal, e o adorou.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 32, 'E levantou um altar a Baal, na casa de Baal que edificara em Samaria.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 33, 'Também Acabe fez um ídolo; de modo que Acabe fez muito mais para irritar ao Senhor Deus de Israel, do que todos os reis de Israel que foram antes dele.', 2, CURRENT_TIMESTAMP, false),
(11, 16, 34, 'Em seus dias Hiel, o betelita, edificou a Jericó; em Abirão, seu primogênito, a fundou, e em Segube, seu filho menor, pôs as suas portas; conforme a palavra do Senhor, que falara pelo ministério de Josué, filho de Num.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 1, 'Então Elias, o tisbita, dos moradores de Gileade, disse a Acabe: Vive o SENHOR Deus de Israel, perante cuja face estou, que nestes anos nem orvalho nem chuva haverá, senão segundo a minha palavra.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 2, 'Depois veio a ele a palavra do Senhor, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 17, 3, 'Retira-te daqui, e vai para o oriente, e esconde-te junto ao ribeiro de Querite, que está diante do Jordão.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 4, 'E há de ser que beberás do ribeiro; e eu tenho ordenado aos corvos que ali te sustentem.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 5, 'Foi, pois, e fez conforme a palavra do Senhor; porque foi, e habitou junto ao ribeiro de Querite, que está diante do Jordão.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 6, 'E os corvos lhe traziam pão e carne pela manhã; como também pão e carne à noite; e bebia do ribeiro.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 7, 'E sucedeu que, passados dias, o ribeiro se secou, porque não tinha havido chuva na terra.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 8, 'Então veio a ele a palavra do Senhor, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 17, 9, 'Levanta-te, e vai para Sarepta, que é de Sidom, e habita ali; eis que eu ordenei ali a uma mulher viúva que te sustente.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 10, 'Então ele se levantou, e foi a Sarepta; e, chegando à porta da cidade, eis que estava ali uma mulher viúva apanhando lenha; e ele a chamou, e lhe disse: Traze-me, peço-te, num vaso um pouco de água que beba.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 11, 'E, indo ela a trazê-la, ele a chamou e lhe disse: Traze-me agora também um bocado de pão na tua mão.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 12, 'Porém ela disse: Vive o Senhor teu Deus, que nem um bolo tenho, senão somente um punhado de farinha numa panela, e um pouco de azeite numa botija; e vês aqui apanhei dois cavacos, e vou prepará-lo para mim e para o meu filho, para que o comamos, e morramos.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 13, 'E Elias lhe disse: Não temas; vai, faze conforme à tua palavra; porém faze dele primeiro para mim um bolo pequeno, e traze-mo aqui; depois farás para ti e para teu filho.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 14, 'Porque assim diz o Senhor Deus de Israel: A farinha da panela não se acabará, e o azeite da botija não faltará até ao dia em que o Senhor dê chuva sobre a terra.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 15, 'E ela foi e fez conforme a palavra de Elias; e assim comeu ela, e ele, e a sua casa muitos dias.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 16, 'Da panela a farinha não se acabou, e da botija o azeite não faltou; conforme a palavra do Senhor, que ele falara pelo ministério de Elias.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 17, 'E depois destas coisas sucedeu que adoeceu o filho desta mulher, dona da casa; e a sua doença se agravou muito, até que nele nenhum fôlego ficou.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 18, 'Então ela disse a Elias: Que tenho eu contigo, homem de Deus? vieste tu a mim para trazeres à memória a minha iniqüidade, e matares a meu filho?', 2, CURRENT_TIMESTAMP, false),
(11, 17, 19, 'E ele disse: Dá-me o teu filho. E ele o tomou do seu regaço, e o levou para cima, ao quarto, onde ele mesmo habitava, e o deitou em sua cama,', 2, CURRENT_TIMESTAMP, false),
(11, 17, 20, 'E clamou ao Senhor, e disse: Ó Senhor meu Deus, também até a esta viúva, com quem me hospedo, afligiste, matando-lhe o filho?', 2, CURRENT_TIMESTAMP, false),
(11, 17, 21, 'Então se estendeu sobre o menino três vezes, e clamou ao Senhor, e disse: Ó Senhor meu Deus, rogo-te que a alma deste menino torne a entrar nele.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 22, 'E o Senhor ouviu a voz de Elias; e a alma do menino tornou a entrar nele, e reviveu.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 23, 'E Elias tomou o menino, e o trouxe do quarto à casa, e o deu à sua mãe; e disse Elias: Vês aí, teu filho vive.', 2, CURRENT_TIMESTAMP, false),
(11, 17, 24, 'Então a mulher disse a Elias: Nisto conheço agora que tu és homem de Deus, e que a palavra do Senhor na tua boca é verdade.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 1, 'E sucedeu que, depois de muitos dias, a palavra do SENHOR veio a Elias, no terceiro ano, dizendo: Vai, apresenta-te a Acabe; porque darei chuva sobre a terra.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 2, 'E foi Elias apresentar-se a Acabe; e a fome era extrema em Samaria.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 3, 'E Acabe chamou a Obadias, o mordomo; e Obadias temia muito ao Senhor,', 2, CURRENT_TIMESTAMP, false),
(11, 18, 4, 'Porque sucedeu que, destruindo Jezabel os profetas do Senhor, Obadias tomou cem profetas, e de cinqüenta em cinqüenta os escondeu numa cova, e os sustentou com pão e água.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 5, 'E disse Acabe a Obadias: Vai pela terra a todas as fontes de água, e a todos os rios; pode ser que achemos erva, para que em vida conservemos os cavalos e mulas, e não percamos todos os animais.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 6, 'E repartiram entre si a terra, para a percorrerem: Acabe foi à parte por um caminho, e Obadias também foi sozinho por outro caminho.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 7, 'Estando, pois, Obadias já em caminho, eis que Elias o encontrou; e Obadias, reconhecendo-o, prostrou-se sobre o seu rosto, e disse: És tu o meu senhor Elias?', 2, CURRENT_TIMESTAMP, false),
(11, 18, 8, 'E disse-lhe ele: Eu sou; vai, e dize a teu senhor: Eis que Elias está aqui.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 9, 'Porém ele disse: Em que pequei, para que entregues a teu servo na mão de Acabe, para que me mate?', 2, CURRENT_TIMESTAMP, false),
(11, 18, 10, 'Vive o SENHOR teu Deus, que não houve nação nem reino aonde o meu senhor não mandasse em busca de ti; e dizendo eles: Aqui não está, então fazia jurar os reinos e nações, que não te haviam achado.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 11, 'E agora dizes tu: Vai, dize a teu senhor: Eis que aqui está Elias.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 12, 'E poderia ser que, apartando-me eu de ti, o Espírito do Senhor te tomasse, não sei para onde, e, vindo eu a dar as novas a Acabe, e não te achando ele, me mataria; porém eu, teu servo, temo ao Senhor desde a minha mocidade.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 13, 'Porventura não disseram a meu senhor o que fiz, quando Jezabel matava os profetas do SENHOR? Como escondi a cem homens dos profetas do SENHOR, de cinqüenta em cinqüenta, numa cova, e os sustentei com pão e água?', 2, CURRENT_TIMESTAMP, false),
(11, 18, 14, 'E agora dizes tu: Vai, dize a teu senhor: Eis que Elias está aqui; ele me mataria.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 15, 'E disse Elias: Vive o Senhor dos Exércitos, perante cuja face estou, que deveras hoje me apresentarei a ele.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 16, 'Então foi Obadias encontrar-se com Acabe, e lho anunciou; e foi Acabe encontrar-se com Elias.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 17, 'E sucedeu que, vendo Acabe a Elias, disse-lhe: És tu o perturbador de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 18, 18, 'Então disse ele: Eu não tenho perturbado a Israel, mas tu e a casa de teu pai, porque deixastes os mandamentos do Senhor, e seguistes a Baalim.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 19, 'Agora, pois, manda reunir-se a mim todo o Israel no monte Carmelo; como também os quatrocentos e cinqüenta profetas de Baal, e os quatrocentos profetas de Aserá, que comem da mesa de Jezabel.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 20, 'Então Acabe convocou todos os filhos de Israel; e reuniu os profetas no monte Carmelo.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 21, 'Então Elias se chegou a todo o povo, e disse: Até quando coxeareis entre dois pensamentos? Se o Senhor é Deus, segui-o, e se Baal, segui-o. Porém o povo nada lhe respondeu.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 22, 'Então disse Elias ao povo: Só eu fiquei por profeta do Senhor, e os profetas de Baal são quatrocentos e cinqüenta homens.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 23, 'Dêem-se-nos, pois, dois bezerros, e eles escolham para si um dos bezerros, e o dividam em pedaços, e o ponham sobre a lenha, porém não lhe coloquem fogo, e eu prepararei o outro bezerro, e o porei sobre a lenha, e não lhe colocarei fogo.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 24, 'Então invocai o nome do vosso deus, e eu invocarei o nome do Senhor; e há de ser que o deus que responder por meio de fogo esse será Deus. E todo o povo respondeu, dizendo: É boa esta palavra.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 25, 'E disse Elias aos profetas de Baal: Escolhei para vós um dos bezerros, e preparai-o primeiro, porque sois muitos, e invocai o nome do vosso deus, e não lhe ponhais fogo.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 26, 'E tomaram o bezerro que lhes dera, e o prepararam; e invocaram o nome de Baal, desde a manhã até ao meio-dia, dizendo: Ah! Baal, responde-nos! Porém nem havia voz, nem quem respondesse; e saltavam sobre o altar que tinham feito.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 27, 'E sucedeu que ao meio-dia Elias zombava deles e dizia: Clamai em altas vozes, porque ele é um deus; pode ser que esteja falando, ou que tenha alguma coisa que fazer, ou que intente alguma viagem; talvez esteja dormindo, e despertará.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 28, 'E eles clamavam em altas vozes, e se retalhavam com facas e com lancetas, conforme ao seu costume, até derramarem sangue sobre si.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 29, 'E sucedeu que, passado o meio-dia, profetizaram eles, até a hora de se oferecer o sacrifício da tarde; porém não houve voz, nem resposta, nem atenção alguma.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 30, 'Então Elias disse a todo o povo: Chegai-vos a mim. E todo o povo se chegou a ele; e restaurou o altar do Senhor, que estava quebrado.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 31, 'E Elias tomou doze pedras, conforme ao número das tribos dos filhos de Jacó, ao qual veio a palavra do Senhor, dizendo: Israel será o teu nome.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 32, 'E com aquelas pedras edificou o altar em nome do Senhor; depois fez um rego em redor do altar, segundo a largura de duas medidas de semente.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 33, 'Então armou a lenha, e dividiu o bezerro em pedaços, e o pôs sobre a lenha.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 34, 'E disse: Enchei de água quatro cântaros, e derramai-a sobre o holocausto e sobre a lenha. E disse: Fazei-o segunda vez; e o fizeram segunda vez. Disse ainda: Fazei-o terceira vez; e o fizeram terceira vez;', 2, CURRENT_TIMESTAMP, false),
(11, 18, 35, 'De maneira que a água corria ao redor do altar; e até o rego ele encheu de água.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 36, 'Sucedeu que, no momento de ser oferecido o sacrifício da tarde, o profeta Elias se aproximou, e disse: Ó Senhor Deus de Abraão, de Isaque e de Israel, manifeste-se hoje que tu és Deus em Israel, e que eu sou teu servo, e que conforme à tua palavra fiz todas estas coisas.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 37, 'Responde-me, Senhor, responde-me, para que este povo conheça que tu és o Senhor Deus, e que tu fizeste voltar o seu coração.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 38, 'Então caiu fogo do Senhor, e consumiu o holocausto, e a lenha, e as pedras, e o pó, e ainda lambeu a água que estava no rego.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 39, 'O que vendo todo o povo, caíram sobre os seus rostos, e disseram: Só o Senhor é Deus! Só o Senhor é Deus!', 2, CURRENT_TIMESTAMP, false),
(11, 18, 40, 'E Elias lhes disse: Lançai mão dos profetas de Baal, que nenhum deles escape. E lançaram mão deles; e Elias os fez descer ao ribeiro de Quisom, e ali os matou.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 41, 'Então disse Elias a Acabe: Sobe, come e bebe, porque há ruído de uma abundante chuva.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 42, 'E Acabe subiu a comer e a beber; mas Elias subiu ao cume do Carmelo, e se inclinou por terra, e pôs o seu rosto entre os seus joelhos.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 43, 'E disse ao seu servo: Sobe agora, e olha para o lado do mar. E subiu, e olhou, e disse: Não há nada. Então disse ele: Volta lá sete vezes.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 44, 'E sucedeu que, à sétima vez, disse: Eis aqui uma pequena nuvem, como a mão de um homem, subindo do mar. Então disse ele: Sobe, e dize a Acabe: Aparelha o teu carro, e desce, para que a chuva não te impeça.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 45, 'E sucedeu que, entretanto, os céus se enegreceram com nuvens e vento, e veio uma grande chuva; e Acabe subiu ao carro, e foi para Jizreel.', 2, CURRENT_TIMESTAMP, false),
(11, 18, 46, 'E a mão do Senhor estava sobre Elias, o qual cingiu os lombos, e veio correndo perante Acabe, até à entrada de Jizreel.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 1, 'E Acabe fez saber a Jezabel tudo quanto Elias havia feito, e como totalmente matara todos os profetas à espada.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 2, 'Então Jezabel mandou um mensageiro a Elias, a dizer-lhe: Assim me façam os deuses, e outro tanto, se de certo amanhã a estas horas não puser a tua vida como a de um deles.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 3, 'O que vendo ele, se levantou e, para escapar com vida, se foi, e chegando a Berseba, que é de Judá, deixou ali o seu servo.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 4, 'Ele, porém, foi ao deserto, caminho de um dia, e foi sentar-se debaixo de um zimbro; e pediu para si a morte, e disse: Já basta, ó Senhor; toma agora a minha vida, pois não sou melhor do que meus pais.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 5, 'E deitou-se, e dormiu debaixo do zimbro; e eis que então um anjo o tocou, e lhe disse: Levanta-te, come.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 6, 'E olhou, e eis que à sua cabeceira estava um pão cozido sobre as brasas, e uma botija de água; e comeu, e bebeu, e tornou a deitar-se.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 7, 'E o anjo do Senhor tornou segunda vez, e o tocou, e disse: Levanta-te e come, porque te será muito longo o caminho.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 8, 'Levantou-se, pois, e comeu e bebeu; e com a força daquela comida caminhou quarenta dias e quarenta noites até Horebe, o monte de Deus.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 9, 'E ali entrou numa caverna e passou ali a noite; e eis que a palavra do Senhor veio a ele, e lhe disse: Que fazes aqui Elias?', 2, CURRENT_TIMESTAMP, false),
(11, 19, 10, 'E ele disse: Tenho sido muito zeloso pelo Senhor Deus dos Exércitos, porque os filhos de Israel deixaram a tua aliança, derrubaram os teus altares, e mataram os teus profetas à espada, e só eu fiquei, e buscam a minha vida para ma tirarem.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 11, 'E Deus lhe disse: Sai para fora, e põe-te neste monte perante o Senhor. E eis que passava o Senhor, como também um grande e forte vento que fendia os montes e quebrava as penhas diante do Senhor; porém o Senhor não estava no vento; e depois do vento um terremoto; também o Senhor não estava no terremoto;', 2, CURRENT_TIMESTAMP, false),
(11, 19, 12, 'E depois do terremoto um fogo; porém também o Senhor não estava no fogo; e depois do fogo uma voz mansa e delicada.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 13, 'E sucedeu que, ouvindo-a Elias, envolveu o seu rosto na sua capa, e saiu para fora, e pôs-se à entrada da caverna; e eis que veio a ele uma voz, que dizia: Que fazes aqui, Elias?', 2, CURRENT_TIMESTAMP, false),
(11, 19, 14, 'E ele disse: Eu tenho sido em extremo zeloso pelo Senhor Deus dos Exércitos, porque os filhos de Israel deixaram a tua aliança, derrubaram os teus altares, e mataram os teus profetas à espada, e só eu fiquei; e buscam a minha vida para ma tirarem.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 15, 'E o Senhor lhe disse: Vai, volta pelo teu caminho para o deserto de Damasco; e, chegando lá, unge a Hazael rei sobre a Síria.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 16, 'Também a Jeú, filho de Ninsi, ungirás rei de Israel; e também a Eliseu, filho de Safate de Abel-Meolá, ungirás profeta em teu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 17, 'E há de ser que o que escapar da espada de Hazael, matá-lo-á Jeú; e o que escapar da espada de Jeú, matá-lo-á Eliseu.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 18, 'Também deixei ficar em Israel sete mil: todos os joelhos que não se dobraram a Baal, e toda a boca que não o beijou.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 19, 'Partiu, pois, Elias dali, e achou a Eliseu, filho de Safate, que andava lavrando com doze juntas de bois adiante dele, e ele estava com a duodécima; e Elias passou por ele, e lançou a sua capa sobre ele.', 2, CURRENT_TIMESTAMP, false),
(11, 19, 20, 'Então deixou ele os bois, e correu após Elias; e disse: Deixa-me beijar a meu pai e a minha mãe, e então te seguirei. E ele lhe disse: Vai, e volta; pois, que te fiz eu?', 2, CURRENT_TIMESTAMP, false),
(11, 19, 21, 'Voltou, pois, de o seguir, e tomou a junta de bois, e os matou, e com os aparelhos dos bois cozeu as carnes, e as deu ao povo, e comeram; então se levantou e seguiu a Elias, e o servia.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 1, 'E Ben-Hadade, rei da Síria, ajuntou todo o seu exército; e havia com ele trinta e dois reis, e cavalos e carros; e subiu, e cercou a Samaria, e pelejou contra ela.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 2, 'E enviou à cidade mensageiros, a Acabe, rei de Israel,', 2, CURRENT_TIMESTAMP, false),
(11, 20, 3, 'Que lhe disseram: Assim diz Ben-Hadade: A tua prata e o teu ouro são meus; e tuas mulheres e os melhores de teus filhos são meus.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 4, 'E respondeu o rei de Israel, e disse: Conforme a tua palavra, ó rei meu senhor, eu sou teu, e tudo quanto tenho.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 5, 'E tornaram a vir os mensageiros, e disseram: Assim diz Ben-Hadade: Enviei-te, na verdade, mensageiros que dissessem: Tu me hás de dar a tua prata, e o teu ouro, e as tuas mulheres e os teus filhos;', 2, CURRENT_TIMESTAMP, false),
(11, 20, 6, 'Todavia amanhã a estas horas enviarei os meus servos a ti, e esquadrinharão a tua casa, e as casas dos teus servos; e há de ser que tudo o que de precioso tiveres, eles tomarão consigo, e o levarão.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 7, 'Então o rei de Israel chamou a todos os anciãos da terra, e disse: Notai agora, e vede como este homem procura o mal; pois mandou pedir-me as mulheres, os meus filhos, a minha prata e o meu ouro, e não lhos neguei.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 8, 'E todos os anciãos e todo o povo lhe disseram: Não lhe dês ouvidos, nem consintas.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 9, 'Por isso disse aos mensageiros de Ben-Hadade: Dizei ao rei, meu senhor: Tudo o que primeiro mandaste pedir a teu servo, farei, porém isto não posso fazer. E voltaram os mensageiros, e lhe levaram a resposta.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 10, 'E Ben-Hadade enviou a ele mensageiros dizendo: Assim me façam os deuses, e outro tanto, que o pó de Samaria não bastará para encher as mãos de todo o povo que me segue.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 11, 'Porém o rei de Israel respondeu: Dizei-lhe: Não se gabe quem se cinge das armas, como aquele que as descinge.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 12, 'E sucedeu que, ouvindo ele esta palavra, estando a beber com os reis nas tendas, disse aos seus servos: Ponde-vos em ordem contra a cidade.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 13, 'E eis que um profeta se chegou a Acabe rei de Israel, e lhe disse: Assim diz o Senhor: Viste toda esta grande multidão? Eis que hoje ta entregarei nas tuas mãos, para que saibas que eu sou o Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 14, 'E disse Acabe: Por quem? E ele disse: Assim diz o Senhor: Pelos moços dos príncipes das províncias. E disse: Quem começará a peleja? E disse: Tu.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 15, 'Então contou os moços dos príncipes das províncias, e foram duzentos e trinta e dois; e depois deles contou a todo o povo, todos os filhos de Israel, sete mil.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 16, 'E saíram ao meio-dia; e Ben-Hadade estava bebendo e embriagando-se nas tendas, ele e os reis, os trinta e dois reis, que o ajudavam.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 17, 'E os moços dos príncipes das províncias saíram primeiro; e Ben-Hadade enviou espias, que lhe deram avisos, dizendo: Saíram de Samaria uns homens.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 18, 'E ele disse: Ainda que para paz saíssem, tomai-os vivos; e ainda que à peleja saíssem, tomai-os vivos.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 19, 'Saíram, pois, da cidade os moços dos príncipes das províncias, e o exército que os seguia.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 20, 'E eles feriram cada um o seu adversário, e os sírios fugiram, e Israel os perseguiu; porém Ben-Hadade, rei da Síria, escapou a cavalo, com alguns cavaleiros.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 21, 'E saiu o rei de Israel, e feriu os cavalos e os carros; e feriu os sírios com grande estrago.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 22, 'Então o profeta chegou-se ao rei de Israel e lhe disse: Vai, esforça-te, e atenta, e olha o que hás de fazer; porque no decurso de um ano o rei da Síria subirá contra ti.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 23, 'Porque os servos do rei da Síria lhe disseram: Seus deuses são deuses dos montes, por isso foram mais fortes do que nós; mas pelejemos com eles em campo raso, e por certo veremos, se não somos mais fortes do que eles!', 2, CURRENT_TIMESTAMP, false),
(11, 20, 24, 'Faze, pois, isto: tira os reis, cada um do seu lugar, e substitui-os por capitães;', 2, CURRENT_TIMESTAMP, false),
(11, 20, 25, 'E forma outro exército, igual ao exército que perdeste, cavalo por cavalo, e carro por carro, e pelejemos com eles em campo raso, e veremos se não somos mais fortes do que eles! E deu ouvidos à sua voz, e assim fez.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 26, 'E sucedeu que, passado um ano, Ben-Hadade passou revista aos sírios, e subiu a Afeque, para pelejar contra Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 27, 'Também aos filhos de Israel se passou revista, e providos de víveres marcharam contra eles; e os filhos de Israel acamparam-se defronte deles, como dois pequenos rebanhos de cabras; mas os sírios enchiam a terra.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 28, 'E chegou o homem de Deus, e falou ao rei de Israel, e disse: Assim diz o Senhor: Porquanto os sírios disseram: O Senhor é Deus dos montes, e não Deus dos vales; toda esta grande multidão entregarei nas tuas mãos; para que saibas que eu sou o Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 29, 'E sete dias estiveram acampados uns defronte dos outros; e sucedeu ao sétimo dia que a peleja começou, e os filhos de Israel feriram dos sírios cem mil homens de pé, num dia.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 30, 'E os restantes fugiram a Afeque, à cidade; e caiu o muro sobre vinte e sete mil homens, que restaram; Ben-Hadade, porém, fugiu, e veio à cidade, escondendo-se de câmara em câmara.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 31, 'Então lhe disseram os seus servos: Eis que já temos ouvido que os reis da casa de Israel são reis clementes; ponhamos, pois, sacos aos lombos, e cordas às cabeças, e saiamos ao rei de Israel; pode ser que ele te poupe a vida.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 32, 'Então cingiram sacos aos lombos e cordas às cabeças, e foram ao rei de Israel, e disseram: Diz o teu servo Ben-Hadade: Deixa-me viver. E disse Acabe: Pois ainda vive? É meu irmão.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 33, 'E aqueles homens tomaram isto por bom presságio, e apressaram-se em apanhar a sua palavra, e disseram: Teu irmão Ben-Hadade vive. E ele disse: Vinde, trazei-mo. Então Ben-Hadade foi a ele, e ele o fez subir ao carro.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 34, 'E disse ele: As cidades que meu pai tomou de teu pai tas restituirei, e faze para ti ruas em Damasco, como meu pai as fez em Samaria. E eu, respondeu Acabe, te deixarei ir com esta aliança. E fez com ele aliança e o deixou ir.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 35, 'Então um dos homens dos filhos dos profetas disse ao seu companheiro, pela palavra do Senhor: Ora fere-me. E o homem recusou feri-lo.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 36, 'E ele lhe disse: Porque não obedeceste à voz do Senhor, eis que, em te apartando de mim, um leão te ferirá. E como dele se apartou, um leão o encontrou e o feriu.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 37, 'Depois encontrou outro homem, e disse-lhe: Ora fere-me. E aquele homem deu-lhe um golpe, ferindo-o.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 38, 'Então foi o profeta, e pôs-se perante o rei no caminho; e disfarçou-se com cinza sobre os seus olhos.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 39, 'E sucedeu que, passando o rei, clamou ele ao rei, dizendo: Teu servo estava no meio da peleja, e eis que, desviando-se um homem, trouxe-me outro homem, e disse: Guarda-me este homem; se vier a faltar, será a tua vida em lugar da vida dele, ou pagarás um talento de prata.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 40, 'Sucedeu, pois, que, estando o teu servo ocupado de uma e de outra parte, eis que o homem desapareceu. Então o rei de Israel lhe disse: Esta é a tua sentença; tu mesmo a pronunciaste.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 41, 'Então ele se apressou, e tirou a cinza de sobre os seus olhos; e o rei de Israel o reconheceu, que era um dos profetas.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 42, 'E disse-lhe: Assim diz o Senhor: Porquanto soltaste da mão o homem que eu havia posto para destruição, a tua vida será em lugar da sua vida, e o teu povo em lugar do seu povo.', 2, CURRENT_TIMESTAMP, false),
(11, 20, 43, 'E foi o rei de Israel para a sua casa, desgostoso e indignado; e chegou a Samaria.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 1, 'E sucedeu depois destas coisas que, Nabote, o jizreelita, tinha uma vinha em Jizreel junto ao palácio de Acabe, rei de Samaria.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 2, 'Então Acabe falou a Nabote, dizendo: Dá-me a tua vinha, para que me sirva de horta, pois está vizinha ao lado da minha casa; e te darei por ela outra vinha melhor: ou, se for do teu agrado, dar-te-ei o seu valor em dinheiro.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 3, 'Porém Nabote disse a Acabe: Guarde-me o Senhor de que eu te dê a herança de meus pais.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 4, 'Então Acabe veio desgostoso e indignado à sua casa, por causa da palavra que Nabote, o jizreelita, lhe falara, quando disse: Não te darei a herança de meus pais. E deitou-se na sua cama, e voltou o rosto, e não comeu pão.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 5, 'Porém, vindo a ele Jezabel, sua mulher, lhe disse: Que há, que está tão desgostoso o teu espírito, e não comes pão?', 2, CURRENT_TIMESTAMP, false),
(11, 21, 6, 'E ele lhe disse: Porque falei a Nabote, o jizreelita, e lhe disse: Dá-me a tua vinha por dinheiro; ou, se te apraz, te darei outra vinha em seu lugar. Porém ele disse: Não te darei a minha vinha.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 7, 'Então Jezabel, sua mulher lhe disse: Governas tu agora no reino de Israel? Levanta-te, come pão, e alegre-se o teu coração; eu te darei a vinha de Nabote, o jizreelita.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 8, 'Então escreveu cartas em nome de Acabe, e as selou com o seu sinete; e mandou as cartas aos anciãos e aos nobres que havia na sua cidade e habitavam com Nabote.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 9, 'E escreveu nas cartas, dizendo: Apregoai um jejum, e ponde Nabote diante do povo.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 10, 'E ponde defronte dele dois filhos de Belial, que testemunhem contra ele, dizendo: Blasfemaste contra Deus e contra o rei; e trazei-o fora, e apedrejai-o para que morra.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 11, 'E os homens da sua cidade, os anciãos e os nobres que habitavam na sua cidade, fizeram como Jezabel lhes ordenara, conforme estava escrito nas cartas que lhes mandara.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 12, 'Apregoaram um jejum, e puseram a Nabote diante do povo.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 13, 'Então vieram dois homens, filhos de Belial, e puseram-se defronte dele; e os homens, filhos de Belial, testemunharam contra ele, contra Nabote, perante o povo, dizendo: Nabote blasfemou contra Deus e contra o rei. E o levaram para fora da cidade, e o apedrejaram, e morreu.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 14, 'Então mandaram dizer a Jezabel: Nabote foi apedrejado, e morreu.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 15, 'E sucedeu que, ouvindo Jezabel que já fora apedrejado Nabote, e morrera, disse a Acabe: Levanta-te, e possui a vinha de Nabote, o jizreelita, a qual te recusou dar por dinheiro; porque Nabote não vive, mas é morto.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 16, 'E sucedeu que, ouvindo Acabe, que Nabote já era morto, levantou-se para descer para a vinha de Nabote, o jizreelita, para tomar posse dela.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 17, 'Então veio a palavra do Senhor a Elias, o tisbita, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 21, 18, 'Levanta-te, desce para encontrar-te com Acabe, rei de Israel, que está em Samaria; eis que está na vinha de Nabote, aonde tem descido para possuí-la.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 19, 'E falar-lhe-ás, dizendo: Assim diz o Senhor: Porventura não mataste e tomaste a herança? Falar-lhe-ás mais, dizendo: Assim diz o Senhor: No lugar em que os cães lamberam o sangue de Nabote lamberão também o teu próprio sangue.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 20, 'E disse Acabe a Elias: Já me achaste, inimigo meu? E ele disse: Achei-te; porquanto já te vendeste para fazeres o que é mau aos olhos do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 21, 'Eis que trarei mal sobre ti, e arrancarei a tua posteridade, e arrancarei de Acabe a todo o homem, tanto o escravo como o livre em Israel;', 2, CURRENT_TIMESTAMP, false),
(11, 21, 22, 'E farei a tua casa como a casa de Jeroboão, filho de Nebate, e como a casa de Baasa, filho de Aías; por causa da provocação, com que me provocaste e fizeste pecar a Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 23, 'E também acerca de Jezabel falou o Senhor, dizendo: Os cães comerão a Jezabel junto ao antemuro de Jizreel.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 24, 'Aquele que morrer dos de Acabe, na cidade, os cães o comerão; e o que morrer no campo as aves do céu o comerão.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 25, 'Porém ninguém fora como Acabe, que se vendera para fazer o que era mau aos olhos do Senhor; porque Jezabel, sua mulher, o incitava.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 26, 'E fez grandes abominações, seguindo os ídolos, conforme a tudo o que fizeram os amorreus, os quais o Senhor lançou fora da sua possessão, de diante dos filhos de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 27, 'Sucedeu, pois, que Acabe, ouvindo estas palavras, rasgou as suas vestes, e cobriu a sua carne de saco, e jejuou; e jazia em saco, e andava mansamente.', 2, CURRENT_TIMESTAMP, false),
(11, 21, 28, 'Então veio a palavra do Senhor a Elias tisbita, dizendo:', 2, CURRENT_TIMESTAMP, false),
(11, 21, 29, 'Não viste que Acabe se humilha perante mim? Por isso, porquanto se humilha perante mim, não trarei este mal nos seus dias, mas nos dias de seu filho o trarei sobre a sua casa.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 1, 'E estiveram quietos três anos, não havendo guerra entre a Síria e Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 2, 'Porém no terceiro ano sucedeu que Jeosafá, rei de Judá, desceu para avistar-se com o rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 3, 'E o rei de Israel disse aos seus servos: Não sabeis vós que Ramote de Gileade é nossa, e nós estamos quietos, sem a tomar da mão do rei da Síria?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 4, 'Então perguntou a Jeosafá: Irás tu comigo à peleja a Ramote de Gileade? E disse Jeosafá ao rei de Israel: Serei como tu, e o meu povo como o teu povo, e os meus cavalos como os teus cavalos.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 5, 'Disse mais Jeosafá ao rei de Israel: Peço-te, consulta hoje a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 6, 'Então o rei de Israel reuniu os profetas até quase quatrocentos homens, e disse-lhes: Irei à peleja contra Ramote de Gileade, ou deixarei de ir? E eles disseram: Sobe, porque o Senhor a entregará na mão do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 7, 'Disse, porém, Jeosafá: Não há aqui ainda algum profeta do Senhor, ao qual possamos consultar?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 8, 'Então disse o rei de Israel a Jeosafá: Ainda há um homem por quem podemos consultar ao Senhor; porém eu o odeio, porque nunca profetiza de mim o que é bom, mas só o mal; este é Micaías, filho de Inlá. E disse Jeosafá: Não fale o rei assim.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 9, 'Então o rei de Israel chamou um oficial, e disse: Traze-me depressa a Micaías, filho de Inlá.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 10, 'E o rei de Israel e Jeosafá, rei de Judá, estavam assentados cada um no seu trono, vestidos de trajes reais, na praça, à entrada da porta de Samaria; e todos os profetas profetizavam na sua presença.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 11, 'E Zedequias, filho de Quenaaná, fez para si uns chifres de ferro, e disse: Assim diz o Senhor: Com estes ferirás aos sírios, até de todo os consumir.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 12, 'E todos os profetas profetizaram assim, dizendo: Sobe a Ramote de Gileade, e triunfarás, porque o Senhor a entregará na mão do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 13, 'E o mensageiro que foi chamar a Micaías falou-lhe, dizendo: Vês aqui que as palavras dos profetas a uma voz predizem coisas boas para o rei; seja, pois, a tua palavra como a palavra de um deles, e fala bem.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 14, 'Porém Micaías disse: Vive o Senhor que o que o Senhor me disser isso falarei.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 15, 'E, vindo ele ao rei, o rei lhe disse: Micaías, iremos a Ramote de Gileade à peleja, ou deixaremos de ir? E ele lhe disse: Sobe, e serás bem sucedido; porque o Senhor a entregará na mão do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 16, 'E o rei lhe disse: Até quantas vezes te conjurarei, que não me fales senão a verdade em nome do Senhor?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 17, 'Então disse ele: Vi a todo o Israel disperso pelos montes, como ovelhas que não tem pastor; e disse o Senhor: Estes não têm senhor; torne cada um em paz para sua casa.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 18, 'Então o rei de Israel disse a Jeosafá: Não te disse eu, que nunca profetizará de mim o que é bom, senão só o que é mal?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 19, 'Então ele disse: Ouve, pois, a palavra do Senhor: Vi ao Senhor assentado sobre o seu trono, e todo o exército do céu estava junto a ele, à sua mão direita e à sua esquerda.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 20, 'E disse o Senhor: Quem induzirá Acabe, para que suba, e caia em Ramote de Gileade? E um dizia desta maneira e outro de outra.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 21, 'Então saiu um espírito, e se apresentou diante do Senhor, e disse: Eu o induzirei. E o Senhor lhe disse: Com quê?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 22, 'E disse ele: Eu sairei, e serei um espírito de mentira na boca de todos os seus profetas. E ele disse: Tu o induzirás, e ainda prevalecerás; sai e faze assim.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 23, 'Agora, pois, eis que o Senhor pôs o espírito de mentira na boca de todos estes teus profetas, e o Senhor falou o mal contra ti.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 24, 'Então Zedequias, filho de Quenaaná, chegou, e feriu a Micaías no queixo, e disse: Por onde saiu de mim o Espírito do Senhor para falar a ti?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 25, 'E disse Micaías: Eis que o verás naquele mesmo dia, quando entrares de câmara em câmara para te esconderes.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 26, 'Então disse o rei de Israel: Tomai a Micaías, e tornai a levá-lo a Amom, o governador da cidade e a Joás filho do rei.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 27, 'E direis: Assim diz o rei: Colocai este homem na casa do cárcere, e sustentai-o com o pão de angústia, e com água de amargura, até que eu venha em paz.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 28, 'E disse Micaías: Se tu voltares em paz, o Senhor não tem falado por mim. Disse mais: Ouvi, povos todos!', 2, CURRENT_TIMESTAMP, false),
(11, 22, 29, 'Assim o rei de Israel e Jeosafá, rei de Judá, subiram a Ramote de Gileade.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 30, 'E disse o rei de Israel a Jeosafá: Eu me disfarçarei, e entrarei na peleja; tu porém veste as tuas roupas. Disfarçou-se, pois o rei de Israel, e entrou na peleja.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 31, 'E o rei da Síria dera ordem aos capitães dos carros, que eram trinta e dois, dizendo: Não pelejareis nem contra pequeno nem contra grande, mas só contra o rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 32, 'Sucedeu que, vendo os capítães dos carros a Jeosafá, disseram eles: Certamente este é o rei de Israel. E chegaram-se a ele, para pelejar com ele; porém Jeosafá gritou.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 33, 'E sucedeu que, vendo os capitães dos carros que não era o rei de Israel, deixaram de segui-lo.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 34, 'Então um homem armou o arco, e atirou a esmo, e feriu o rei de Israel por entre as fivelas e as couraças; então ele disse ao seu carreteiro: Dá volta, e tira-me do exército, porque estou gravemente ferido.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 35, 'E a peleja foi crescendo nequele dia, e o rei foi sustentado no carro defronte dos sírios; porém ele morreu à tarde; e o sangue da ferida corria para o fundo do carro.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 36, 'E depois do sol posto passou um pregão pelo exército, dizendo: Cada um para a sua cidade, e cada um para a sua terra!', 2, CURRENT_TIMESTAMP, false),
(11, 22, 37, 'E morreu o rei, e o levaram a Samaria; e sepultaram o rei em Samaria.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 38, 'E, lavando-se o carro no tanque de Samaria, os cães lamberam o seu sangue (ora as prostitutas se lavavam ali), conforme à palavra que o Senhor tinha falado.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 39, 'Quanto ao mais dos atos de Acabe, e a tudo quanto fez, e à casa de marfim que edificou, porventura não está escrito no livro das crônicas dos reis de Israel?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 40, 'Assim dormiu Acabe com seus pais; e Acazias, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 41, 'E Jeosafá, filho de Asa, começou a reinar sobre Judá no quarto ano de Acabe, rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 42, 'E era Jeosafá da idade de trinta e cinco anos quando começou a reinar; e vinte e cinco anos reinou em Jerusalém; e era o nome de sua mãe Azuba, filha de Sili.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 43, 'E andou em todos os caminhos de seu pai Asa, não se desviou deles, fazendo o que era reto aos olhos do Senhor.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 44, 'Todavia os altos não se tiraram; ainda o povo sacrificava e queimava incenso nos altos.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 45, 'E Jeosafá esteve em paz com o rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 46, 'Quanto ao mais dos atos de Jeosafá, e ao poder que mostrou, e como guerreou, porventura não está escrito no livro das crônicas dos reis de Judá?', 2, CURRENT_TIMESTAMP, false),
(11, 22, 47, 'Também expulsou da terra o restante dos sodomitas, que ficaram nos dias de seu pai Asa.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 48, 'Então não havia rei em Edom, porém um vice-rei.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 49, 'E fez Jeosafá navios de Társis, para irem a Ofir por causa do ouro; porém não foram, porque os navios se quebraram em Eziom-Geber.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 50, 'Então Acazias, filho de Acabe, disse a Jeosafá: Vão os meus servos com os teus servos nos navios. Porém Jeosafá não quis.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 51, 'E Jeosafá dormiu com seus pais, e foi sepultado junto a eles, na cidade de Davi, seu pai; e Jeorão, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 52, 'E Acazias, filho de Acabe, começou a reinar sobre Israel, em Samaria, no ano dezessete de Jeosafá, rei de Judá; e reinou dois anos sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 53, 'E fez o que era mau aos olhos do Senhor; porque andou no caminho de seu pai, como também no caminho de sua mãe, e no caminho de Jeroboão, filho de Nebate, que fez pecar a Israel.', 2, CURRENT_TIMESTAMP, false),
(11, 22, 54, 'E serviu a Baal, e adorou-o, e provocou a ira do Senhor Deus de Israel, conforme a tudo quanto fizera seu pai.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 1, 'Houve um homem de Ramataim-Zofim, da montanha de Efraim, cujo nome era Elcana, filho de Jeroão, filho de Eliú, filho de Toú, filho de Zufe, efrateu.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 2, 'E este tinha duas mulheres: o nome de uma era Ana, e o da outra Penina. E Penina tinha filhos, porém Ana não os tinha.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 3, 'Subia, pois, este homem, da sua cidade, de ano em ano, a adorar e a sacrificar ao Senhor dos Exércitos em Siló; e estavam ali os sacerdotes do Senhor, Hofni e Finéias, os dois filhos de Eli.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 4, 'E sucedeu que no dia em que Elcana sacrificava, dava ele porções a Penina, sua mulher, e a todos os seus filhos, e a todas as suas filhas.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 5, 'Porém a Ana dava uma parte excelente; porque amava a Ana, embora o Senhor lhe tivesse cerrado a madre.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 6, 'E a sua rival excessivamente a provocava, para a irritar; porque o Senhor lhe tinha cerrado a madre.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 7, 'E assim fazia ele de ano em ano. Sempre que Ana subia à casa do Senhor, a outra a irritava; por isso chorava, e não comia.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 8, 'Então Elcana, seu marido, lhe disse: Ana, por que choras? E por que não comes? E por que está mal o teu coração? Não te sou eu melhor do que dez filhos?', 2, CURRENT_TIMESTAMP, false),
(9, 1, 9, 'Então Ana se levantou, depois que comeram e beberam em Siló; e Eli, sacerdote, estava assentado numa cadeira, junto a um pilar do templo do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 10, 'Ela, pois, com amargura de alma, orou ao Senhor, e chorou abundantemente.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 11, 'E fez um voto, dizendo: Senhor dos Exércitos! Se benignamente atentares para a aflição da tua serva, e de mim te lembrares, e da tua serva não te esqueceres, mas à tua serva deres um filho homem, ao Senhor o darei todos os dias da sua vida, e sobre a sua cabeça não passará navalha.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 12, 'E sucedeu que, perseverando ela em orar perante o Senhor, Eli observou a sua boca.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 13, 'Porquanto Ana no seu coração falava; só se moviam os seus lábios, porém não se ouvia a sua voz; pelo que Eli a teve por embriagada.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 14, 'E disse-lhe Eli: Até quando estarás tu embriagada? Aparta de ti o teu vinho.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 15, 'Porém Ana respondeu: Não, senhor meu, eu sou uma mulher atribulada de espírito; nem vinho nem bebida forte tenho bebido; porém tenho derramado a minha alma perante o SENHOR.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 16, 'Não tenhas, pois, a tua serva por filha de Belial; porque da multidão dos meus cuidados e do meu desgosto tenho falado até agora.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 17, 'Então respondeu Eli: Vai em paz; e o Deus de Israel te conceda a petição que lhe fizeste.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 18, 'E disse ela: Ache a tua serva graça aos teus olhos. Assim a mulher foi o seu caminho, e comeu, e o seu semblante já não era triste.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 19, 'E levantaram-se de madrugada, e adoraram perante o Senhor, e voltaram, e chegaram à sua casa, em Ramá, e Elcana conheceu a Ana sua mulher, e o Senhor se lembrou dela.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 20, 'E sucedeu que, passado algum tempo, Ana concebeu, e deu à luz um filho, ao qual chamou Samuel; porque, dizia ela, o tenho pedido ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 21, 'E subiu aquele homem Elcana com toda a sua casa, a oferecer ao Senhor o sacrifício anual e a cumprir o seu voto.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 22, 'Porém Ana não subiu; mas disse a seu marido: Quando o menino for desmamado, então o levarei, para que apareça perante o Senhor, e lá fique para sempre.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 23, 'E Elcana, seu marido, lhe disse: Faze o que bem te parecer aos teus olhos; fica até que o desmames; então somente confirme o Senhor a sua palavra. Assim ficou a mulher, e deu leite a seu filho, até que o desmamou.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 24, 'E, havendo-o desmamado, tomou-o consigo, com três bezerros, e um efa de farinha, e um odre de vinho, e levou-o à casa do Senhor, em Siló, e era o menino ainda muito criança.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 25, 'E degolaram um bezerro, e trouxeram o menino a Eli.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 26, 'E disse ela: Ah, meu senhor, viva a tua alma, meu senhor; eu sou aquela mulher que aqui esteve contigo, para orar ao SENHOR.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 27, 'Por este menino orava eu; e o Senhor atendeu à minha petição, que eu lhe tinha feito.', 2, CURRENT_TIMESTAMP, false),
(9, 1, 28, 'Por isso também ao Senhor eu o entreguei, por todos os dias que viver, pois ao Senhor foi pedido. E adorou ali ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 1, 'Então orou Ana, e disse: O meu coração exulta ao SENHOR, o meu poder está exaltado no SENHOR; a minha boca se dilatou sobre os meus inimigos, porquanto me alegro na tua salvação.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 2, 'Não há santo como o Senhor; porque não há outro fora de ti; e rocha nenhuma há como o nosso Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 3, 'Não multipliqueis palavras de altivez, nem saiam coisas arrogantes da vossa boca; porque o Senhor é o Deus de conhecimento, e por ele são as obras pesadas na balança.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 4, 'O arco dos fortes foi quebrado, e os que tropeçavam foram cingidos de força.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 5, 'Os fartos se alugaram por pão, e cessaram os famintos; até a estéril deu à luz sete filhos, e a que tinha muitos filhos enfraqueceu.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 6, 'O Senhor é o que tira a vida e a dá; faz descer à sepultura e faz tornar a subir dela.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 7, 'O Senhor empobrece e enriquece; abaixa e também exalta.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 8, 'Levanta o pobre do pó, e desde o monturo exalta o necessitado, para o fazer assentar entre os príncipes, para o fazer herdar o trono de glória; porque do Senhor são os alicerces da terra, e assentou sobre eles o mundo.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 9, 'Os pés dos seus santos guardará, porém os ímpios ficarão mudos nas trevas; porque o homem não prevalecerá pela força.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 10, 'Os que contendem com o Senhor serão quebrantados, desde os céus trovejará sobre eles; o Senhor julgará as extremidades da terra; e dará força ao seu rei, e exaltará o poder do seu ungido.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 11, 'Então Elcana foi a Ramá, à sua casa; porém o menino ficou servindo ao Senhor, perante o sacerdote Eli.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 12, 'Eram, porém, os filhos de Eli filhos de Belial; não conheciam ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 13, 'Porquanto o costume daqueles sacerdotes com o povo era que, oferecendo alguém algum sacrifício, estando-se cozendo a carne, vinha o moço do sacerdote, com um garfo de três dentes em sua mão;', 2, CURRENT_TIMESTAMP, false),
(9, 2, 14, 'E enfiava-o na caldeira, ou na panela, ou no caldeirão, ou na marmita; e tudo quanto o garfo tirava, o sacerdote tomava para si; assim faziam a todo o Israel que ia ali a Siló.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 15, 'Também antes de queimarem a gordura vinha o moço do sacerdote, e dizia ao homem que sacrificava: Dá essa carne para assar ao sacerdote; porque não receberá de ti carne cozida, mas crua.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 16, 'E, dizendo-lhe o homem: Queime-se primeiro a gordura de hoje, e depois toma para ti quanto desejar a tua alma, então ele lhe dizia: Não, agora a hás de dar, e, se não, por força a tomarei.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 17, 'Era, pois, muito grande o pecado destes moços perante o Senhor, porquanto os homens desprezavam a oferta do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 18, 'Porém Samuel ministrava perante o Senhor, sendo ainda jovem, vestido com um éfode de linho.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 19, 'E sua mãe lhe fazia uma túnica pequena, e de ano em ano lha trazia, quando com seu marido subia para oferecer o sacrifício anual.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 20, 'E Eli abençoava a Elcana e a sua mulher, e dizia: O Senhor te dê descendência desta mulher, pela petição que fez ao Senhor. E voltavam para o seu lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 21, 'Visitou, pois, o Senhor a Ana, que concebeu, e deu à luz três filhos e duas filhas; e o jovem Samuel crescia diante do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 22, 'Era, porém, Eli já muito velho, e ouvia tudo quanto seus filhos faziam a todo o Israel, e de como se deitavam com as mulheres que em bandos se ajuntavam à porta da tenda da congregação.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 23, 'E disse-lhes: Por que fazeis tais coisas? Pois ouço de todo este povo os vossos malefícios.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 24, 'Não, filhos meus, porque não é boa esta fama que ouço; fazeis transgredir o povo do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 25, 'Pecando homem contra homem, os juízes o julgarão; pecando, porém, o homem contra o Senhor, quem rogará por ele? Mas não ouviram a voz de seu pai, porque o Senhor os queria matar.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 26, 'E o jovem Samuel ia crescendo, e fazia-se agradável, assim para com o Senhor, como também para com os homens.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 27, 'E veio um homem de Deus a Eli, e disse-lhe: Assim diz o Senhor: Não me manifestei, na verdade, à casa de teu pai, estando eles ainda no Egito, na casa de Faraó?', 2, CURRENT_TIMESTAMP, false),
(9, 2, 28, 'E eu o escolhi dentre todas as tribos de Israel por sacerdote, para oferecer sobre o meu altar, para acender o incenso, e para trazer o éfode perante mim; e dei à casa de teu pai todas as ofertas queimadas dos filhos de Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 29, 'Por que pisastes o meu sacrifício e a minha oferta de alimentos, que ordenei na minha morada, e honras a teus filhos mais do que a mim, para vos engordardes do principal de todas as ofertas do meu povo de Israel?', 2, CURRENT_TIMESTAMP, false),
(9, 2, 30, 'Portanto, diz o Senhor Deus de Israel: Na verdade tinha falado eu que a tua casa e a casa de teu pai andariam diante de mim perpetuamente; porém agora diz o Senhor: Longe de mim tal coisa, porque aos que me honram honrarei, porém os que me desprezam serão desprezados.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 31, 'Eis que vêm dias em que cortarei o teu braço e o braço da casa de teu pai, para que não haja mais ancião algum em tua casa.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 32, 'E verás o aperto da morada de Deus, em lugar de todo o bem que houvera de fazer a Israel; nem haverá por todos os dias ancião algum em tua casa.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 33, 'O homem, porém, a quem eu não desarraigar do meu altar será para te consumir os olhos e para te entristecer a alma; e toda a multidão da tua casa morrerá quando chegar à idade varonil.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 34, 'E isto te será por sinal, a saber: o que acontecerá a teus dois filhos, a Hofni e a Finéias; ambos morrerão no mesmo dia.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 35, 'E eu suscitarei para mim um sacerdote fiel, que procederá segundo o meu coração e a minha alma, e eu lhe edificarei uma casa firme, e andará sempre diante do meu ungido.', 2, CURRENT_TIMESTAMP, false),
(9, 2, 36, 'E será que todo aquele que restar da tua casa virá a inclinar-se diante dele por uma moeda de prata e por um bocado de pão, e dirá: Rogo-te que me admitas a algum ministério sacerdotal, para que possa comer um pedaço de pão.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 1, 'E o jovem Samuel servia ao SENHOR perante Eli; e a palavra do SENHOR era de muita valia naqueles dias; não havia visão manifesta.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 2, 'E sucedeu, naquele dia, que, estando Eli deitado no seu lugar (e os seus olhos começavam a escurecer, pois não podia ver),', 2, CURRENT_TIMESTAMP, false),
(9, 3, 3, 'E estando também Samuel já deitado, antes que a lâmpada de Deus se apagasse no templo do Senhor, onde estava a arca de Deus,', 2, CURRENT_TIMESTAMP, false),
(9, 3, 4, 'O Senhor chamou a Samuel, e disse ele: Eis-me aqui.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 5, 'E correu a Eli, e disse: Eis-me aqui, porque tu me chamaste. Mas ele disse: Não te chamei eu, torna a deitar-te. E foi e se deitou.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 6, 'E o Senhor tornou a chamar outra vez a Samuel, e Samuel se levantou, e foi a Eli, e disse: Eis-me aqui, porque tu me chamaste. Mas ele disse: Não te chamei eu, filho meu, torna a deitar-te.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 7, 'Porém Samuel ainda não conhecia ao Senhor, e ainda não lhe tinha sido manifestada a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 8, 'O Senhor, pois, tornou a chamar a Samuel terceira vez, e ele se levantou, e foi a Eli, e disse: Eis-me aqui, porque tu me chamaste. Então entendeu Eli que o Senhor chamava o jovem.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 9, 'Por isso Eli disse a Samuel: Vai deitar-te e há de ser que, se te chamar, dirás: Fala, Senhor, porque o teu servo ouve. Então Samuel foi e se deitou no seu lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 10, 'Então veio o Senhor, e pôs-se ali, e chamou como das outras vezes: Samuel, Samuel. E disse Samuel: Fala, porque o teu servo ouve.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 11, 'E disse o Senhor a Samuel: Eis que vou fazer uma coisa em Israel, a qual todo o que ouvir lhe tinirão ambos os ouvidos.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 12, 'Naquele mesmo dia suscitarei contra Eli tudo quanto tenho falado contra a sua casa, começarei e acabarei.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 13, 'Porque eu já lhe fiz saber que julgarei a sua casa para sempre, pela iniqüidade que ele bem conhecia, porque, fazendo-se os seus filhos execráveis, não os repreendeu.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 14, 'Portanto, jurei à casa de Eli que nunca jamais será expiada a sua iniqüidade, nem com sacrifício, nem com oferta de alimentos.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 15, 'E Samuel ficou deitado até pela manhã, e então abriu as portas da casa do Senhor; porém temia Samuel relatar esta visão a Eli.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 16, 'Então chamou Eli a Samuel, e disse: Samuel, meu filho. E disse ele: Eis-me aqui.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 17, 'E ele disse: Qual é a palavra que te falou? Peço-te que não ma encubras; assim Deus te faça, e outro tanto, se me encobrires alguma palavra de todas as que te falou.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 18, 'Então Samuel lhe contou todas aquelas palavras, e nada lhe encobriu. E disse ele: Ele é o Senhor; faça o que bem parecer aos seus olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 19, 'E crescia Samuel, e o Senhor era com ele, e nenhuma de todas as suas palavras deixou cair em terra.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 20, 'E todo o Israel, desde Dã até Berseba, conheceu que Samuel estava confirmado por profeta do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 3, 21, 'E continuou o Senhor a aparecer em Siló; porquanto o Senhor se manifestava a Samuel em Siló pela palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 1, 'E veio a palavra de Samuel a todo o Israel; e Israel saiu à peleja contra os filisteus e acampou-se junto a Ebenézer; e os filisteus se acamparam junto a Afeque.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 2, 'E os filisteus se dispuseram em ordem de batalha, para sair contra Israel; e, estendendo-se a peleja, Israel foi ferido diante dos filisteus, porque feriram na batalha, no campo, uns quatro mil homens.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 3, 'E voltando o povo ao arraial, disseram os anciãos de Israel: Por que nos feriu o Senhor hoje diante dos filisteus? Tragamos de Siló a arca da aliança do Senhor, e venha no meio de nós, para que nos livre da mão de nossos inimigos.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 4, 'Enviou, pois, o povo a Siló, e trouxeram de lá a arca da aliança do Senhor dos Exércitos, que habita entre os querubins; e os dois filhos de Eli, Hofni e Finéias, estavam ali com a arca da aliança de Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 5, 'E sucedeu que, vindo a arca da aliança do Senhor ao arraial, todo o Israel gritou com grande júbilo, até que a terra estremeceu.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 6, 'E os filisteus, ouvindo a voz de júbilo, disseram: Que voz de grande júbilo é esta no arraial dos hebreus? Então souberam que a arca do Senhor era vinda ao arraial.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 7, 'Por isso os filisteus se atemorizaram, porque diziam: Deus veio ao arraial. E diziam mais: Ai de nós! Tal nunca jamais sucedeu antes.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 8, 'Ai de nós! Quem nos livrará da mão desses grandiosos deuses? Estes são os deuses que feriram aos egípcios com todas as pragas junto ao deserto.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 9, 'Esforçai-vos, e sede homens, ó filisteus, para que porventura não venhais a servir aos hebreus, como eles serviram a vós; sede, pois, homens, e pelejai.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 10, 'Então pelejaram os filisteus, e Israel foi ferido, fugindo cada um para a sua tenda; e foi tão grande o estrago, que caíram de Israel trinta mil homens de pé.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 11, 'E foi tomada a arca de Deus: e os dois filhos de Eli, Hofni e Finéias, morreram.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 12, 'Então correu, da batalha, um homem de Benjamim, e chegou no mesmo dia a Siló; e trazia as vestes rotas, e terra sobre a cabeça.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 13, 'E, chegando ele, eis que Eli estava assentado numa cadeira, olhando para o caminho; porquanto o seu coração estava tremendo pela arca de Deus. Entrando, pois, aquele homem a anunciar isto na cidade, toda a cidade gritou.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 14, 'E Eli, ouvindo os gritos, disse: Que alvoroço é esse? Então chegou aquele homem apressadamente, e veio, e o anunciou a Eli.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 15, 'E era Eli da idade de noventa e oito anos; e estavam os seus olhos tão escurecidos, que já não podia ver.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 16, 'E disse aquele homem a Eli: Eu sou o que venho da batalha; porque eu fugi hoje da batalha. E disse ele: Que coisa sucedeu, filho meu?', 2, CURRENT_TIMESTAMP, false),
(9, 4, 17, 'Então respondeu o que trazia as notícias, e disse: Israel fugiu de diante dos filisteus, e houve também grande matança entre o povo; e, além disso, também teus dois filhos, Hofni e Finéias, morreram, e a arca de Deus foi tomada.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 18, 'E sucedeu que, fazendo ele menção da arca de Deus, Eli caiu da cadeira para trás, ao lado da porta, e quebrou-se-lhe o pescoço e morreu; porquanto o homem era velho e pesado; e tinha ele julgado Israel quarenta anos.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 19, 'E, estando sua nora, a mulher de Finéias, grávida, e próxima ao parto, e ouvindo estas notícias, de que a arca de Deus era tomada, e de que seu sogro e seu marido morreram, encurvou-se e deu à luz; porquanto as dores lhe sobrevieram.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 20, 'E, ao tempo em que ia morrendo, disseram as mulheres que estavam com ela: Não temas, pois deste à luz um filho. Ela porém não respondeu, nem fez caso disso.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 21, 'E chamou ao menino Icabode, dizendo: De Israel se foi a glória! Porque a arca de Deus foi tomada, e por causa de seu sogro e de seu marido.', 2, CURRENT_TIMESTAMP, false),
(9, 4, 22, 'E disse: De Israel a glória é levada presa; pois é tomada a arca de Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 1, 'Os filisteus, pois, tomaram a arca de Deus e a trouxeram de Ebenézer a Asdode.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 2, 'Tomaram os filisteus a arca de Deus, e a colocaram na casa de Dagom, e a puseram junto a Dagom.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 3, 'Levantando-se, porém, de madrugada no dia seguinte, os de Asdode, eis que Dagom estava caído com o rosto em terra, diante da arca do Senhor; e tomaram a Dagom, e tornaram a pô-lo no seu lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 4, 'E, levantando-se de madrugada, no dia seguinte, pela manhã, eis que Dagom jazia caído com o rosto em terra diante da arca do Senhor; e a cabeça de Dagom e ambas as palmas das suas mãos estavam cortadas sobre o limiar; somente o tronco ficou a Dagom.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 5, 'Por isso nem os sacerdotes de Dagom, nem nenhum de todos os que entram na casa de Dagom pisam o limiar de Dagom em Asdode, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 6, 'Porém a mão do Senhor se agravou sobre os de Asdode, e os assolou; e os feriu com hemorróidas, em Asdode e nos seus termos.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 7, 'Vendo então os homens de Asdode que assim foi, disseram: Não fique conosco a arca do Deus de Israel; pois a sua mão é dura sobre nós, e sobre Dagom, nosso deus.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 8, 'Por isso enviaram mensageiros e congregaram a si todos os príncipes dos filisteus, e disseram: Que faremos nós da arca do Deus de Israel? E responderam: a arca do Deus de Israel será levada até Gate. Assim levaram para lá a arca do Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 9, 'E sucedeu que, assim que a levaram, a mão do Senhor veio contra aquela cidade, com mui grande vexame; pois feriu aos homens daquela cidade, desde o pequeno até ao grande; e tinham hemorróidas nas partes íntimas.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 10, 'Então enviaram a arca de Deus a Ecrom. Sucedeu, porém, que, vindo a arca de Deus a Ecrom, os de Ecrom exclamaram, dizendo: Transportaram para nós a arca do Deus de Israel, para nos matarem, a nós e ao nosso povo.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 11, 'E enviaram, e congregaram a todos os príncipes dos filisteus, e disseram: Enviai a arca do Deus de Israel, e torne para o seu lugar, para que não mate nem a nós nem ao nosso povo. Porque havia mortal vexame em toda a cidade, e a mão de Deus muito se agravara ali.', 2, CURRENT_TIMESTAMP, false),
(9, 5, 12, 'E os homens que não morriam eram tão atacados com hemorróidas que o clamor da cidade subia até o céu.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 1, 'Havendo, pois, estado a arca do SENHOR na terra dos filisteus sete meses,', 2, CURRENT_TIMESTAMP, false),
(9, 6, 2, 'Os filisteus chamaram os sacerdotes e os adivinhadores, dizendo: Que faremos nós com a arca do Senhor? Fazei-nos saber como a tornaremos a enviar ao seu lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 3, 'Os quais disseram: Se enviardes a arca do Deus de Israel, não a envieis vazia, porém sem falta enviareis uma oferta para a expiação da culpa; então sereis curados, e se vos fará saber porque a sua mão não se retira de vós.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 4, 'Então disseram: Qual é a expiação da culpa que lhe havemos de enviar? E disseram: Segundo o número dos príncipes dos filisteus, cinco hemorróidas de ouro e cinco ratos de ouro; porquanto a praga é uma mesma sobre todos vós e sobre todos os vossos príncipes.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 5, 'Fazei, pois, umas imagens das vossas hemorróidas e dos vossos ratos, que andam destruindo a terra, e dai glória ao Deus de Israel; porventura aliviará a sua mão de cima de vós, e de cima do vosso deus, e de cima da vossa terra.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 6, 'Por que, pois, endureceríeis o vosso coração, como os egípcios e Faraó endureceram os seus corações? Porventura depois de os haver tratado tão mal, os não deixaram ir, e eles não se foram?', 2, CURRENT_TIMESTAMP, false),
(9, 6, 7, 'Agora, pois, tomai e fazei-vos um carro novo, e tomai duas vacas com crias, sobre as quais não tenha subido o jugo, e atai as vacas ao carro, e tirai delas os seus bezerros e levai-os para casa.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 8, 'Então tomai a arca do Senhor, e ponde-a sobre o carro, e colocai, num cofre, ao seu lado, as figuras de ouro que lhe haveis de oferecer em expiação da culpa, e assim a enviareis, para que se vá.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 9, 'Vede então: Se ela subir pelo caminho do seu termo a Bete-Semes, foi ele quem nos fez este grande mal; e, se não, saberemos que não nos tocou a sua mão, e que isto nos sucedeu por acaso.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 10, 'E assim fizeram aqueles homens, e tomaram duas vacas que criavam, e as ataram ao carro; e os seus bezerros encerraram em casa.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 11, 'E puseram a arca do Senhor sobre o carro, como também o cofre com os ratos de ouro e com as imagens das suas hemorróidas.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 12, 'Então as vacas se encaminharam diretamente pelo caminho de Bete-Semes, e seguiam um mesmo caminho, andando e berrando, sem se desviarem, nem para a direita nem para a esquerda; e os príncipes dos filisteus foram atrás delas, até ao termo de Bete-Semes.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 13, 'E andavam os de Bete-Semes fazendo a sega do trigo no vale, e, levantando os seus olhos, viram a arca, e, vendo-a, se alegraram.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 14, 'E o carro veio ao campo de Josué, o bete-semita, e parou ali onde havia uma grande pedra. E fenderam a madeira do carro, e ofereceram as vacas ao Senhor em holocausto.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 15, 'E os levitas desceram a arca do Senhor, como também o cofre que estava junto a ela, em que estavam os objetos de ouro, e puseram-nos sobre aquela grande pedra; e os homens de Bete-Semes ofereceram holocaustos e sacrifícios ao Senhor no mesmo dia.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 16, 'E, vendo aquilo os cinco príncipes dos filisteus, voltaram para Ecrom no mesmo dia.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 17, 'Estas, pois, são as hemorróidas de ouro que enviaram os filisteus ao Senhor em expiação da culpa: Por Asdode uma, por Gaza outra, por Ascalom outra, por Gate outra, por Ecrom outra.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 18, 'Como também os ratos de ouro, segundo o número de todas as cidades dos filisteus, pertencentes aos cinco príncipes, desde as cidades fortificadas até às aldeias, e até Abel. A grande pedra, sobre a qual puseram a arca do Senhor, ainda está até ao dia de hoje no campo de Josué, o bete-semita.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 19, 'E o Senhor feriu os homens de Bete-Semes, porquanto olharam para dentro da arca do Senhor; feriu do povo cinqüenta mil e setenta homens; então o povo se entristeceu, porquanto o Senhor fizera tão grande estrago entre o povo.', 2, CURRENT_TIMESTAMP, false),
(9, 6, 20, 'Então disseram os homens de Bete-Semes: Quem poderia subsistir perante este santo Senhor Deus? E a quem subirá de nós?', 2, CURRENT_TIMESTAMP, false),
(9, 6, 21, 'Enviaram, pois, mensageiros aos habitantes de Quiriate-Jearim, dizendo: Os filisteus remeteram a arca do Senhor; descei, pois, e fazei-a subir para vós.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 1, 'Então vieram os homens de Quiriate-Jearim, e levaram a arca do SENHOR, e a trouxeram à casa de Abinadabe, no outeiro; e consagraram a Eleazar, seu filho, para que guardasse a arca do SENHOR.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 2, 'E sucedeu que, desde aquele dia, a arca ficou em Quiriate-Jearim, e tantos dias se passaram que até chegaram vinte anos, e lamentava toda a casa de Israel pelo Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 3, 'Então falou Samuel a toda a casa de Israel, dizendo: Se com todo o vosso coração vos converterdes ao Senhor, tirai dentre vós os deuses estranhos e os astarotes, e preparai o vosso coração ao Senhor, e servi a ele só, e vos livrará da mão dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 4, 'Então os filhos de Israel tiraram dentre si aos baalins e aos astarotes, e serviram só ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 5, 'Disse mais Samuel: Congregai a todo o Israel em Mizpá; e orarei por vós ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 6, 'E congregaram-se em Mizpá, e tiraram água, e a derramaram perante o Senhor, e jejuaram aquele dia, e disseram ali: Pecamos contra o Senhor. E julgava Samuel os filhos de Israel em Mizpá.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 7, 'Ouvindo, pois, os filisteus que os filhos de Israel estavam congregados em Mizpá, subiram os maiorais dos filisteus contra Israel; o que ouvindo os filhos de Israel, temeram por causa dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 8, 'Por isso disseram os filhos de Israel a Samuel: Não cesses de clamar ao Senhor nosso Deus por nós, para que nos livre da mão dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 9, 'Então tomou Samuel um cordeiro de mama, e sacrificou-o inteiro em holocausto ao Senhor; e clamou Samuel ao Senhor por Israel, e o Senhor lhe deu ouvidos.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 10, 'E sucedeu que, estando Samuel sacrificando o holocausto, os filisteus chegaram à peleja contra Israel; e trovejou o Senhor aquele dia com grande estrondo sobre os filisteus, e os confundiu de tal modo que foram derrotados diante dos filhos de Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 11, 'E os homens de Israel saíram de Mizpá; e perseguiram os filisteus, e os feriram até abaixo de Bete-Car.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 12, 'Então tomou Samuel uma pedra, e a pôs entre Mizpá e Sem, e chamou-lhe Ebenézer; e disse: Até aqui nos ajudou o Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 13, 'Assim os filisteus foram abatidos, e nunca mais vieram aos termos de Israel, porquanto foi a mão do Senhor contra os filisteus todos os dias de Samuel.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 14, 'E as cidades que os filisteus tinham tomado a Israel foram-lhe restituídas, desde Ecrom até Gate, e até os seus termos Israel arrebatou da mão dos filisteus; e houve paz entre Israel e entre os amorreus.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 15, 'E Samuel julgou a Israel todos os dias da sua vida.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 16, 'E ia de ano em ano, e rodeava a Betel, e a Gilgal, e a Mizpá, e julgava a Israel em todos aqueles lugares.', 2, CURRENT_TIMESTAMP, false),
(9, 7, 17, 'Porém voltava a Ramá, porque estava ali a sua casa, e ali julgava a Israel; e edificou ali um altar ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 1, 'E sucedeu que, tendo Samuel envelhecido, constituiu a seus filhos por juízes sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 2, 'E o nome do seu filho primogênito era Joel, e o nome do seu segundo, Abia; e foram juízes em Berseba.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 3, 'Porém seus filhos não andaram pelos caminhos dele, antes se inclinaram à avareza, e aceitaram suborno, e perverteram o direito.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 4, 'Então todos os anciãos de Israel se congregaram, e vieram a Samuel, a Ramá,', 2, CURRENT_TIMESTAMP, false),
(9, 8, 5, 'E disseram-lhe: Eis que já estás velho, e teus filhos não andam pelos teus caminhos; constitui-nos, pois, agora um rei sobre nós, para que ele nos julgue, como o têm todas as nações.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 6, 'Porém esta palavra pareceu mal aos olhos de Samuel, quando disseram: Dá-nos um rei, para que nos julgue. E Samuel orou ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 7, 'E disse o Senhor a Samuel: Ouve a voz do povo em tudo quanto te dizem, pois não te têm rejeitado a ti, antes a mim me têm rejeitado, para eu não reinar sobre eles.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 8, 'Conforme a todas as obras que fizeram desde o dia em que os tirei do Egito até ao dia de hoje, a mim me deixaram, e a outros deuses serviram, assim também fazem a ti.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 9, 'Agora, pois, ouve à sua voz, porém protesta-lhes solenemente, e declara-lhes qual será o costume do rei que houver de reinar sobre eles.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 10, 'E falou Samuel todas as palavras do Senhor ao povo, que lhe pedia um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 11, 'E disse: Este será o costume do rei que houver de reinar sobre vós; ele tomará os vossos filhos, e os empregará nos seus carros, e como seus cavaleiros, para que corram adiante dos seus carros.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 12, 'E os porá por chefes de mil, e de cinqüenta; e para que lavrem a sua lavoura, e façam a sua sega, e fabriquem as suas armas de guerra e os petrechos de seus carros.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 13, 'E tomará as vossas filhas para perfumistas, cozinheiras e padeiras.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 14, 'E tomará o melhor das vossas terras, e das vossas vinhas, e dos vossos olivais, e os dará aos seus servos.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 15, 'E as vossas sementes, e as vossas vinhas dizimará, para dar aos seus oficiais, e aos seus servos.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 16, 'Também os vossos servos, e as vossas servas, e os vossos melhores moços, e os vossos jumentos tomará, e os empregará no seu trabalho.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 17, 'Dizimará o vosso rebanho, e vós lhe servireis de servos.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 18, 'Então naquele dia clamareis por causa do vosso rei, que vós houverdes escolhido; mas o Senhor não vos ouvirá naquele dia.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 19, 'Porém o povo não quis ouvir a voz de Samuel; e disseram: Não, mas haverá sobre nós um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 20, 'E nós também seremos como todas as outras nações; e o nosso rei nos julgará, e sairá adiante de nós, e fará as nossas guerras.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 21, 'Ouvindo, pois, Samuel todas as palavras do povo, as repetiu aos ouvidos do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 8, 22, 'Então o Senhor disse a Samuel: Dá ouvidos à sua voz, e constitui-lhes rei. Então Samuel disse aos homens de Israel: Volte cada um à sua cidade.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 1, 'E havia um homem de Benjamim, cujo nome era Quis, filho de Abiel, filho de Zeror, filho de Becorate, filho de Afia, filho de um homem de Benjamim; homem poderoso.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 2, 'Este tinha um filho, cujo nome era Saul, moço, e tão belo que entre os filhos de Israel não havia outro homem mais belo do que ele; desde os ombros para cima sobressaía a todo o povo.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 3, 'E perderam-se as jumentas de Quis, pai de Saul; por isso disse Quis a Saul, seu filho: Toma agora contigo um dos moços, e levanta-te e vai procurar as jumentas.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 4, 'Passaram, pois, pela montanha de Efraim, e dali passaram à terra de Salisa, porém não as acharam; depois passaram à terra de Saalim, porém tampouco estavam ali; também passaram à terra de Benjamim, porém tampouco as acharam.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 5, 'Vindo eles então à terra de Zufe, Saul disse para o seu moço, com quem ele ia: Vem, e voltemos; para que porventura meu pai não deixe de inquietar-se pelas jumentas e se aflija por causa de nós.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 6, 'Porém ele lhe disse: Eis que há nesta cidade um homem de Deus, e homem honrado é; tudo quanto diz, sucede assim infalivelmente; vamo-nos agora lá; porventura nos mostrará o caminho que devemos seguir.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 7, 'Então Saul disse ao seu moço: Eis, porém, se lá formos, que levaremos então àquele homem? Porque o pão de nossos alforjes se acabou, e presente nenhum temos para levar ao homem de Deus; que temos?', 2, CURRENT_TIMESTAMP, false),
(9, 9, 8, 'E o moço tornou a responder a Saul, e disse: Eis que ainda se acha na minha mão um quarto de um siclo de prata, o qual darei ao homem de Deus, para que nos mostre o caminho', 2, CURRENT_TIMESTAMP, false),
(9, 9, 9, '(Antigamente em Israel, indo alguém consultar a Deus, dizia assim: Vinde, e vamos ao vidente; porque ao profeta de hoje, antigamente se chamava vidente).', 2, CURRENT_TIMESTAMP, false),
(9, 9, 10, 'Então disse Saul ao moço: Bem dizes; vem, pois, vamos. E foram-se à cidade onde estava o homem de Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 11, 'E, subindo eles à cidade, acharam umas moças que saíam a tirar água; e disseram-lhes: Está aqui o vidente?', 2, CURRENT_TIMESTAMP, false),
(9, 9, 12, 'E elas lhes responderam, e disseram: Sim, eis aí o tens diante de ti; apressa-te, pois, porque hoje veio à cidade; porquanto o povo tem hoje sacrifício no alto.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 13, 'Entrando vós na cidade, logo o achareis, antes que suba ao alto para comer; porque o povo não comerá, até que ele venha; porque ele é o que abençoa o sacrifício, e depois comem os convidados; subi, pois, agora, que hoje o achareis.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 14, 'Subiram, pois, à cidade; e, vindo eles no meio da cidade, eis que Samuel lhes saiu ao encontro, para subir ao alto.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 15, 'Porque o Senhor revelara isto aos ouvidos de Samuel, um dia antes que Saul viesse, dizendo:', 2, CURRENT_TIMESTAMP, false),
(9, 9, 16, 'Amanhã a estas horas te enviarei um homem da terra de Benjamim, o qual ungirás por capitão sobre o meu povo de Israel, e ele livrará o meu povo da mão dos filisteus; porque tenho olhado para o meu povo; porque o seu clamor chegou a mim.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 17, 'E quando Samuel viu a Saul, o Senhor lhe respondeu: Eis aqui o homem de quem eu te falei. Este dominará sobre o meu povo.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 18, 'E Saul se chegou a Samuel no meio da porta, e disse: Mostra-me, peço-te, onde está a casa do vidente.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 19, 'E Samuel respondeu a Saul, e disse: Eu sou o vidente; sobe diante de mim ao alto, e comei hoje comigo; e pela manhã te despedirei, e tudo quanto está no teu coração, to declararei.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 20, 'E quanto às jumentas que há três dias se te perderam, não ocupes o teu coração com elas, porque já se acharam. E para quem é todo o desejo de Israel? Porventura não é para ti, e para toda a casa de teu pai?', 2, CURRENT_TIMESTAMP, false),
(9, 9, 21, 'Então respondeu Saul, e disse: Porventura não sou eu filho de Benjamim, da menor das tribos de Israel? E a minha família a menor de todas as famílias da tribo de Benjamim? Por que, pois, me falas com semelhantes palavras?', 2, CURRENT_TIMESTAMP, false),
(9, 9, 22, 'Porém Samuel tomou a Saul e ao seu moço, e os levou à câmara; e deu-lhes lugar acima de todos os convidados, que eram uns trinta homens.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 23, 'Então disse Samuel ao cozinheiro: Dá aqui a porção que te dei, de que te disse: Põe-na à parte contigo.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 24, 'Levantou, pois, o cozinheiro a espádua, com o que havia nela, e pô-la diante de Saul; e disse Samuel: Eis que o que foi reservado está diante de ti. Come; porque se guardou para ti para esta ocasião, dizendo eu: Tenho convidado o povo. Assim comeu Saul aquele dia com Samuel.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 25, 'Então desceram do alto para a cidade; e falou com Saul sobre o eirado.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 26, 'E se levantaram de madrugada; e sucedeu que, quase ao subir da alva, chamou Samuel a Saul ao eirado, dizendo: Levanta-te, e despedir-te-ei. Levantou-se Saul, e saíram ambos para fora, ele e Samuel.', 2, CURRENT_TIMESTAMP, false),
(9, 9, 27, 'E, descendo eles para a extremidade da cidade, Samuel disse a Saul: Dize ao moço que passe adiante de nós (e passou); porém tu espera agora, e te farei ouvir a palavra de Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 1, 'Então tomou Samuel um vaso de azeite, e lho derramou sobre a cabeça, e beijou-o, e disse: Porventura não te ungiu o SENHOR por capitão sobre a sua herança?', 2, CURRENT_TIMESTAMP, false),
(9, 10, 2, 'Apartando-te hoje de mim, acharás dois homens junto ao sepulcro de Raquel, no termo de Benjamim, em Zelza, os quais te dirão: Acharam-se as jumentas que foste buscar, e eis que já o teu pai deixou o negócio das jumentas, e anda aflito por causa de vós, dizendo: Que farei eu por meu filho?', 2, CURRENT_TIMESTAMP, false),
(9, 10, 3, 'E quando dali passares mais adiante, e chegares ao carvalho de Tabor, ali te encontrarão três homens, que vão subindo a Deus a Betel; um levando três cabritos, o outro três bolos de pão e o outro um odre de vinho.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 4, 'E te perguntarão como estás, e te darão dois pães, que tomarás das suas mãos.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 5, 'Então chegarás ao outeiro de Deus, onde está a guarnição dos filisteus; e há de ser que, entrando ali na cidade, encontrarás um grupo de profetas que descem do alto, e trazem diante de si saltérios, e tambores, e flautas, e harpas; e eles estarão profetizando.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 6, 'E o Espírito do Senhor se apoderará de ti, e profetizarás com eles, e tornar-te-ás um outro homem.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 7, 'E há de ser que, quando estes sinais te vierem, faze o que achar a tua mão, porque Deus é contigo.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 8, 'Tu, porém, descerás antes de mim a Gilgal, e eis que eu descerei a ti, para sacrificar holocaustos, e para oferecer ofertas pacíficas; ali sete dias esperarás, até que eu venha a ti, e te declare o que hás de fazer.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 9, 'Sucedeu, pois, que, virando ele as costas para partir de Samuel, Deus lhe mudou o coração em outro; e todos aqueles sinais aconteceram naquele mesmo dia.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 10, 'E, chegando eles ao outeiro, eis que um grupo de profetas lhes saiu ao encontro; e o Espírito de Deus se apoderou dele, e profetizou no meio deles.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 11, 'E aconteceu que, como todos os que antes o conheciam viram que ele profetizava com os profetas, então disse o povo, cada um ao seu companheiro: Que é o que sucedeu ao filho de Quis? Está também Saul entre os profetas?', 2, CURRENT_TIMESTAMP, false),
(9, 10, 12, 'Então um homem dali respondeu, e disse: Pois quem é o pai deles? Pelo que se tornou em provérbio: Está Saul também entre os profetas?', 2, CURRENT_TIMESTAMP, false),
(9, 10, 13, 'E, acabando de profetizar, foi ao alto.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 14, 'E disse-lhe o tio de Saul, a ele e ao seu moço: Aonde fostes? E disse ele: A buscar as jumentas, e, vendo que não apareciam, fomos a Samuel.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 15, 'Então disse o tio de Saul: Declara-me, peço-te, o que vos disse Samuel?', 2, CURRENT_TIMESTAMP, false),
(9, 10, 16, 'E disse Saul a seu tio: Declarou-nos, na verdade, que as jumentas foram encontradas. Porém o negócio do reino, de que Samuel falara, não lhe declarou.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 17, 'Convocou, pois, Samuel o povo ao Senhor, em Mizpá.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 18, 'E disse aos filhos de Israel: Assim disse o Senhor Deus de Israel: Eu fiz subir a Israel do Egito, e livrei-vos da mão dos egípcios e da mão de todos os reinos que vos oprimiam.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 19, 'Mas vós tendes rejeitado hoje a vosso Deus, que vos livrou de todos os vossos males e trabalhos, e lhe tendes falado: Põe um rei sobre nós. Agora, pois, ponde-vos perante o Senhor, pelas vossas tribos e segundo os vossos milhares.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 20, 'Tendo, pois, Samuel feito chegar todas as tribos, tomou-se a tribo de Benjamim.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 21, 'E, fazendo chegar a tribo de Benjamim pelas suas famílias, tomou-se a família de Matri; e dela se tomou Saul, filho de Quis; e o buscaram, porém não se achou.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 22, 'Então tornaram a perguntar ao Senhor se aquele homem ainda viria ali. E disse o Senhor: Eis que se escondeu entre a bagagem.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 23, 'E correram, e o tomaram dali, e pôs-se no meio do povo; e era mais alto do que todo o povo desde o ombro para cima.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 24, 'Então disse Samuel a todo o povo: Vedes já a quem o Senhor escolheu? Pois em todo o povo não há nenhum semelhante a ele. Então jubilou todo o povo, e disse: Viva o rei!', 2, CURRENT_TIMESTAMP, false),
(9, 10, 25, 'E declarou Samuel ao povo o direito do reino, e escreveu-o num livro, e pô-lo perante o Senhor; então despediu Samuel a todo o povo, cada um para sua casa.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 26, 'E foi também Saul à sua casa, em Gibeá; e foram com ele do exército aqueles cujos corações Deus tocara.', 2, CURRENT_TIMESTAMP, false),
(9, 10, 27, 'Mas os filhos de Belial disseram: É este o que nos há de livrar? E o desprezaram, e não lhe trouxeram presentes; porém ele se fez como surdo.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 1, 'Então subiu Naás, amonita, e sitiou a Jabes-Gileade; e disseram todos os homens de Jabes a Naás: Faze aliança conosco, e te serviremos.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 2, 'Porém Naás, amonita, lhes disse: Com esta condição farei aliança convosco: que a todos vos arranque o olho direito, e assim ponha esta afronta sobre todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 3, 'Então os anciãos de Jabes lhe disseram: Deixa-nos por sete dias, para que enviemos mensageiros por todos os termos de Israel, e, não havendo ninguém que nos livre, então viremos a ti.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 4, 'E, vindo os mensageiros a Gibeá de Saul, falaram estas palavras aos ouvidos do povo. Então todo o povo levantou a sua voz, e chorou.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 5, 'E eis que Saul vinha do campo, atrás dos bois; e disse Saul: Que tem o povo, que chora? E contaram-lhe as palavras dos homens de Jabes.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 6, 'Então o Espírito de Deus se apoderou de Saul, ouvindo estas palavras; e acendeu-se em grande maneira a sua ira.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 7, 'E tomou uma junta de bois, e cortou-os em pedaços, e os enviou a todos os termos de Israel pelas mãos dos mensageiros, dizendo: Qualquer que não seguir a Saul e a Samuel, assim se fará aos seus bois. Então caiu o temor do Senhor sobre o povo, e saíram como um só homem.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 8, 'E contou-os em Bezeque; e houve dos filhos de Israel trezentos mil, e dos homens de Judá trinta mil.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 9, 'Então disseram aos mensageiros que vieram: Assim direis aos homens de Jabes-Gileade: Amanhã, em aquecendo o sol, vos virá livramento. Vindo, pois, os mensageiros, e anunciando-o aos homens de Jabes, se alegraram.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 10, 'E os homens de Jabes disseram aos amonitas: Amanhã sairemos a vós; então nos fareis conforme a tudo o que parecer bem aos vossos olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 11, 'E sucedeu que ao outro dia Saul pôs o povo em três companhias, e vieram ao meio do arraial pela vigília da manhã, e feriram aos amonitas até que o dia aqueceu; e sucedeu que os restantes se espalharam, de modo que não ficaram dois deles juntos.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 12, 'Então disse o povo a Samuel: Quem é aquele que dizia que Saul não reinaria sobre nós? Dai-nos aqueles homens, e os mataremos.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 13, 'Porém Saul disse: Hoje não morrerá nenhum, pois hoje tem feito o Senhor um livramento em Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 14, 'E disse Samuel ao povo: Vinde, vamos nós a Gilgal, e renovemos ali o reino.', 2, CURRENT_TIMESTAMP, false),
(9, 11, 15, 'E todo o povo partiu para Gilgal, onde proclamaram a Saul por rei perante o Senhor, e ofereceram ali ofertas pacíficas perante o Senhor; e Saul se alegrou muito ali com todos os homens de Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 1, 'Então disse Samuel a todo o Israel: Eis que ouvi a vossa voz em tudo quanto me dissestes, e constituí sobre vós um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 2, 'Agora, pois, eis que o rei vai adiante de vós. Eu já envelheci e encaneci, e eis que meus filhos estão convosco, e tenho andado diante de vós desde a minha mocidade até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 3, 'Eis-me aqui; testificai contra mim perante o Senhor, e perante o seu ungido, a quem o boi tomei, a quem o jumento tomei, e a quem defraudei, a quem tenho oprimido, e de cuja mão tenho recebido suborno e com ele encobri os meus olhos, e vo-lo restituirei.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 4, 'Então disseram: Em nada nos defraudaste, nem nos oprimiste, nem recebeste coisa alguma da mão de ninguém.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 5, 'E ele lhes disse: O Senhor seja testemunha contra vós, e o seu ungido seja hoje testemunha, que nada tendes achado na minha mão. E disse o povo: Ele é testemunha.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 6, 'Então disse Samuel ao povo: O Senhor é o que escolheu a Moisés e a Arão, e tirou a vossos pais da terra do Egito.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 7, 'Agora, pois, ponde-vos aqui em pé, e pleitearei convosco perante o Senhor, sobre todos os atos de justiça do Senhor, que fez a vós e a vossos pais.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 8, 'Havendo entrado Jacó no Egito, vossos pais clamaram ao Senhor, e o Senhor enviou a Moisés e a Arão que tiraram a vossos pais do Egito, e os fizeram habitar neste lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 9, 'Porém esqueceram-se do Senhor seu Deus; então os vendeu à mão de Sísera, capitão do exército de Hazor, e na mão dos filisteus, e na mão do rei dos moabitas, que pelejaram contra eles.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 10, 'E clamaram ao Senhor, e disseram: Pecamos, pois deixamos ao Senhor, e servimos aos baalins e astarotes; agora, pois, livra-nos da mão de nossos inimigos, e te serviremos.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 11, 'E o Senhor enviou a Jerubaal, e a Bedã, e a Jefté, e a Samuel; e livrou-vos da mão de vossos inimigos em redor, e habitastes seguros.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 12, 'E vendo vós que Naás, rei dos filhos de Amom, vinha contra vós, me dissestes: Não, mas reinará sobre nós um rei; sendo, porém, o Senhor vosso Deus, o vosso rei.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 13, 'Agora, pois, vedes aí o rei que elegestes e que pedistes; e eis que o Senhor tem posto sobre vós um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 14, 'Se temerdes ao Senhor, e o servirdes, e derdes ouvidos à sua voz, e não fordes rebeldes ao mandado do Senhor, assim vós, como o rei que reina sobre vós, seguireis o Senhor vosso Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 15, 'Mas se não derdes ouvidos à voz do Senhor, e antes fordes rebeldes ao mandado do Senhor, a mão do Senhor será contra vós, como o era contra vossos pais.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 16, 'Ponde-vos também agora aqui, e vede esta grande coisa que o Senhor vai fazer diante dos vossos olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 17, 'Não é hoje a sega do trigo? Clamarei, pois, ao Senhor, e dará trovões e chuva; e sabereis e vereis que é grande a vossa maldade, que tendes feito perante o Senhor, pedindo para vós um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 18, 'Então invocou Samuel ao Senhor, e o Senhor deu trovões e chuva naquele dia; por isso todo o povo temeu sobremaneira ao Senhor e a Samuel.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 19, 'E todo o povo disse a Samuel: Roga pelos teus servos ao Senhor teu Deus, para que não venhamos a morrer; porque a todos os nossos pecados temos acrescentado este mal, de pedirmos para nós um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 20, 'Então disse Samuel ao povo: Não temais; vós tendes cometido todo este mal; porém não vos desvieis de seguir ao Senhor, mas servi ao Senhor com todo o vosso coração.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 21, 'E não vos desvieis; pois seguiríeis as vaidades, que nada aproveitam, e tampouco vos livrarão, porque vaidades são.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 22, 'Pois o Senhor, por causa do seu grande nome, não desamparará o seu povo; porque aprouve ao Senhor fazer-vos o seu povo.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 23, 'E quanto a mim, longe de mim que eu peque contra o Senhor, deixando de orar por vós; antes vos ensinarei o caminho bom e direito.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 24, 'Tão-somente temei ao Senhor, e servi-o fielmente com todo o vosso coração; porque vede quão grandiosas coisas vos fez.', 2, CURRENT_TIMESTAMP, false),
(9, 12, 25, 'Porém, se perseverardes em fazer mal, perecereis, assim vós como o vosso rei.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 1, 'Saul reinou um ano; e no segundo ano do seu reinado sobre Israel,', 2, CURRENT_TIMESTAMP, false),
(9, 13, 2, 'Saul escolheu para si três mil homens de Israel; e estavam com Saul dois mil em Micmás e na montanha de Betel, e mil estavam com Jônatas em Gibeá de Benjamim; e o resto do povo despediu, cada um para sua casa.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 3, 'E Jônatas feriu a guarnição dos filisteus, que estava em Gibeá, o que os filisteus ouviram; pelo que Saul tocou a trombeta por toda a terra, dizendo: Ouçam os hebreus.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 4, 'Então todo o Israel ouviu dizer: Saul feriu a guarnição dos filisteus, e também Israel se fez abominável aos filisteus. Então o povo foi convocado para junto de Saul em Gilgal.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 5, 'E os filisteus se ajuntaram para pelejar contra Israel, trinta mil carros, e seis mil cavaleiros, e povo em multidão como a areia que está à beira do mar; e subiram, e se acamparam em Micmás, ao oriente de Bete-Áven.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 6, 'Vendo, pois, os homens de Israel que estavam em apuros (porque o povo estava angustiado), o povo se escondeu pelas cavernas, e pelos espinhais, e pelos penhascos, e pelas fortificações, e pelas covas.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 7, 'E alguns dos hebreus passaram o Jordão para a terra de Gade e Gileade; e, estando Saul ainda em Gilgal, todo o povo ia atrás dele tremendo.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 8, 'E esperou Saul sete dias, até ao tempo que Samuel determinara; não vindo, porém, Samuel a Gilgal, o povo se dispersava dele.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 9, 'Então disse Saul: Trazei-me aqui um holocausto, e ofertas pacíficas. E ofereceu o holocausto.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 10, 'E sucedeu que, acabando ele de oferecer o holocausto, eis que Samuel chegou; e Saul lhe saiu ao encontro, para o saudar.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 11, 'Então disse Samuel: Que fizeste? Disse Saul: Porquanto via que o povo se espalhava de mim, e tu não vinhas nos dias aprazados, e os filisteus já se tinham ajuntado em Micmás,', 2, CURRENT_TIMESTAMP, false),
(9, 13, 12, 'Eu disse: Agora descerão os filisteus sobre mim a Gilgal, e ainda à face do Senhor não orei; e constrangi-me, e ofereci holocausto.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 13, 'Então disse Samuel a Saul: Procedeste nesciamente, e não guardaste o mandamento que o Senhor teu Deus te ordenou; porque agora o Senhor teria confirmado o teu reino sobre Israel para sempre;', 2, CURRENT_TIMESTAMP, false),
(9, 13, 14, 'Porém agora não subsistirá o teu reino; já tem buscado o Senhor para si um homem segundo o seu coração, e já lhe tem ordenado o Senhor, que seja capitão sobre o seu povo, porquanto não guardaste o que o Senhor te ordenou.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 15, 'Então se levantou Samuel, e subiu de Gilgal a Gibeá de Benjamim; e Saul contou o povo que se achava com ele, uns seiscentos homens.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 16, 'E Saul e Jônatas, seu filho, e o povo que se achou com eles, ficaram em Gibeá de Benjamim; porém os filisteus se acamparam em Micmás.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 17, 'E os saqueadores saíram do campo dos filisteus em três companhias; uma das companhias foi pelo caminho de Ofra à terra de Sual.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 18, 'Outra companhia seguiu pelo caminho de Bete-Horom, e a outra companhia foi pelo caminho do termo que dá para o vale Zeboim na direção do deserto.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 19, 'E em toda a terra de Israel nem um ferreiro se achava, porque os filisteus tinham dito: Para que os hebreus não façam espada nem lança.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 20, 'Por isso todo o Israel tinha que descer aos filisteus para amolar cada um a sua relha, e a sua enxada, e o seu machado, e o seu sacho.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 21, 'Tinham porém limas para os seus sachos, e para as suas enxadas, e para as forquilhas de três dentes, e para os machados, e para consertar as aguilhadas.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 22, 'E sucedeu que, no dia da peleja, não se achou nem espada nem lança na mão de todo o povo que estava com Saul e com Jônatas; porém acharam-se com Saul e com Jônatas seu filho.', 2, CURRENT_TIMESTAMP, false),
(9, 13, 23, 'E saiu a guarnição dos filisteus ao desfiladeiro de Micmás.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 1, 'Sucedeu, pois, que um dia disse Jônatas, filho de Saul, ao moço que lhe levava as armas: Vem, passemos à guarnição dos filisteus, que está lá daquele lado. Porém não o fez saber a seu pai.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 2, 'E estava Saul à extremidade de Gibeá, debaixo da romeira que havia em Migrom; e o povo que estava com ele era uns seiscentos homens.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 3, 'E Aías, filho de Aitube, irmão de Icabode, o filho de Finéias, filho de Eli, sacerdote do Senhor em Siló, trazia o éfode; porém o povo não sabia que Jônatas tinha ido.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 4, 'E entre os desfiladeiros pelos quais Jônatas procurava passar à guarnição dos filisteus, deste lado havia uma penha aguda, e do outro lado uma penha aguda; e era o nome de uma Bozez, e o nome da outra Sené.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 5, 'Uma penha para o norte estava defronte de Micmás, e a outra para o sul, defronte de Gibeá.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 6, 'Disse, pois, Jônatas ao moço que lhe levava as armas: Vem, passemos à guarnição destes incircuncisos; porventura operará o Senhor por nós, porque para com o Senhor nenhum impedimento há de livrar com muitos ou com poucos.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 7, 'Então o seu pajem de armas lhe disse: Faze tudo o que tens no coração; segue, eis-me aqui contigo, conforme o que quiseres.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 8, 'Disse, pois, Jônatas: Eis que passaremos àqueles homens, e nos revelaremos a eles.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 9, 'Se nos disserem assim: Parai até que cheguemos a vós; então ficaremos no nosso lugar, e não subiremos a eles.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 10, 'Porém, se disserem: Subi a nós; então subiremos, pois o Senhor os tem entregado nas nossas mãos, e isto nos será por sinal.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 11, 'Revelando-se eles à guarnição dos filisteus, disseram os filisteus: Eis que já os hebreus saíram das cavernas em que se tinham escondido.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 12, 'E os homens da guarnição responderam a Jônatas e ao seu pajem de armas, e disseram: Subi a nós, e nós vos ensinaremos uma lição. E disse Jônatas ao seu pajem de armas: Sobe atrás de mim, porque o Senhor os tem entregado na mão de Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 13, 'Então subiu Jônatas com os pés e com as mãos, e o seu pajem de armas atrás dele; e os filisteus caíam diante de Jônatas, e o seu pajem de armas os matava atrás dele.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 14, 'E sucedeu esta primeira derrota, em que Jônatas e o seu pajem de armas feriram uns vinte homens, em cerca de meia jeira de terra que uma junta de bois podia lavrar.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 15, 'E houve tremor no arraial, no campo e em todo o povo; também a mesma guarnição e os saqueadores tremeram, até a terra se estremeceu porquanto era tremor de Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 16, 'Olharam, pois, as sentinelas de Saul em Gibeá de Benjamim, e eis que a multidão se dissolvia, e fugia para cá e para lá.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 17, 'Disse então Saul ao povo que estava com ele: Ora contai, e vede quem é que saiu dentre nós. E contaram, e eis que nem Jônatas nem o seu pajem de armas estavam ali.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 18, 'Então Saul disse a Aías: Traze aqui a arca de Deus (porque naquele dia estava a arca de Deus com os filhos de Israel).', 2, CURRENT_TIMESTAMP, false),
(9, 14, 19, 'E sucedeu que, estando Saul ainda falando com o sacerdote, o alvoroço que havia no arraial dos filisteus ia crescendo muito, e se multiplicava, pelo que disse Saul ao sacerdote: Retira a tua mão.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 20, 'Então Saul e todo o povo que havia com ele se reuniram, e foram à peleja; e eis que a espada de um era contra o outro, e houve mui grande tumulto.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 21, 'Também com os filisteus havia hebreus, como dantes, que subiram com eles ao arraial em redor; e também estes se ajuntaram com os israelitas que estavam com Saul e Jônatas.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 22, 'Ouvindo, pois, todos os homens de Israel que se esconderam pela montanha de Efraim que os filisteus fugiam, eles também os perseguiram de perto na peleja.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 23, 'Assim livrou o Senhor a Israel naquele dia; e o arraial passou a Bete-Áven.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 24, 'E estavam os homens de Israel já exaustos naquele dia, porquanto Saul conjurou o povo, dizendo: Maldito o homem que comer pão até à tarde, antes que me vingue de meus inimigos. Por isso todo o povo se absteve de provar pão.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 25, 'E todo o povo chegou a um bosque; e havia mel na superfície do campo.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 26, 'E, chegando o povo ao bosque, eis que havia um manancial de mel; porém ninguém chegou a mão à boca, porque o povo temia a conjuração.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 27, 'Porém Jônatas não tinha ouvido quando seu pai conjurara o povo, e estendeu a ponta da vara que tinha na mão, e a molhou no favo de mel; e, tornando a mão à boca, aclararam-se os seus olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 28, 'Então respondeu um do povo, e disse: Solenemente conjurou teu pai o povo, dizendo: Maldito o homem que comer hoje pão. Por isso o povo desfalecia.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 29, 'Então disse Jônatas: Meu pai tem turbado a terra; ora vede como se me aclararam os olhos por ter provado um pouco deste mel,', 2, CURRENT_TIMESTAMP, false),
(9, 14, 30, 'Quanto mais se o povo hoje livremente tivesse comido do despojo que achou de seus inimigos. Porém agora não foi tão grande o estrago dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 31, 'Feriram, porém, aquele dia aos filisteus, desde Micmás até Aijalom, e o povo desfaleceu em extremo.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 32, 'Então o povo se lançou ao despojo, e tomaram ovelhas, e vacas, e bezerros, e os degolaram no chão; e o povo os comeu com sangue.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 33, 'E o anunciaram a Saul, dizendo: Eis que o povo peca contra o Senhor, comendo com sangue. E disse: Aleivosamente procedestes; trazei-me aqui já uma grande pedra.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 34, 'Disse mais Saul: Dispersai-vos entre o povo, e dizei-lhes: Trazei-me cada um o seu boi, e cada um a sua ovelha, e degolai-os aqui, e comei, e não pequeis contra o Senhor, comendo com sangue. Então todo o povo trouxe de noite, cada um pela sua mão, o seu boi, e os degolaram ali.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 35, 'Então edificou Saul um altar ao Senhor; este foi o primeiro altar que edificou ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 36, 'Depois disse Saul: Desçamos de noite atrás dos filisteus, e despojemo-los, até que amanheça o dia, e não deixemos deles um só homem. E disseram: Tudo o que parecer bem aos teus olhos faze. Disse, porém, o sacerdote: Cheguemo-nos aqui a Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 37, 'Então consultou Saul a Deus, dizendo: Descerei atrás dos filisteus? Entregá-los-ás na mão de Israel? Porém aquele dia não lhe respondeu.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 38, 'Então disse Saul: Chegai-vos para cá, todos os chefes do povo, e informai-vos, e vede em que se cometeu hoje este pecado.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 39, 'Porque vive o Senhor que salva a Israel, que, ainda que seja em meu filho Jônatas, certamente morrerá. E nenhum de todo o povo lhe respondeu.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 40, 'Disse mais a todo o Israel: Vós estareis de um lado, e eu e meu filho Jônatas estaremos do outro lado. Então disse o povo a Saul: Faze o que parecer bem aos teus olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 41, 'Falou, pois, Saul ao Senhor Deus de Israel: Mostra o inocente. Então Jônatas e Saul foram tomados por sorte, e o povo saiu livre.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 42, 'Então disse Saul: Lançai a sorte entre mim e Jônatas, meu filho. E foi tomado Jônatas.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 43, 'Disse então Saul a Jônatas: Declara-me o que tens feito. E Jônatas lho declarou, e disse: Tão-somente provei um pouco de mel com a ponta da vara que tinha na mão; eis que devo morrer?', 2, CURRENT_TIMESTAMP, false),
(9, 14, 44, 'Então disse Saul: Assim me faça Deus, e outro tanto, que com certeza morrerás, Jônatas.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 45, 'Porém o povo disse a Saul: Morrerá Jônatas, que efetuou tão grande salvação em Israel? Nunca tal suceda; vive o Senhor, que não lhe há de cair no chão um só cabelo da sua cabeça! pois com Deus fez isso hoje. Assim o povo livrou a Jônatas, para que não morresse.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 46, 'E Saul deixou de seguir os filisteus; e os filisteus se foram ao seu lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 47, 'Então tomou Saul o reino sobre Israel; e pelejou contra todos os seus inimigos em redor; contra Moabe, e contra os filhos de Amom, e contra Edom, e contra os reis de Zobá, e contra os filisteus, e para onde quer que se tornava executava castigo.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 48, 'E houve-se valorosamente, e feriu aos amalequitas, e liberou a Israel da mão dos que o saqueavam.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 49, 'E os filhos de Saul eram Jônatas, e Isvi, e Malquisua; e os nomes de suas duas filhas eram estes: o da mais velha Merabe, e o da mais nova, Mical.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 50, 'E o nome da mulher de Saul, Ainoã, filha de Aimaás; e o nome do capitão do exército, Abner, filho de Ner, tio de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 51, 'E Quis, pai de Saul, e Ner, pai de Abner, eram filhos de Abiel.', 2, CURRENT_TIMESTAMP, false),
(9, 14, 52, 'E houve uma forte guerra contra os filisteus, todos os dias de Saul; por isso Saul a todos os homens valentes e valorosos que via, os agregava a si.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 1, 'Então disse Samuel a Saul: Enviou-me o SENHOR a ungir-te rei sobre o seu povo, sobre Israel; ouve, pois, agora a voz das palavras do SENHOR.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 2, 'Assim diz o Senhor dos Exércitos: Eu me recordei do que fez Amaleque a Israel; como se lhe opôs no caminho, quando subia do Egito.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 3, 'Vai, pois, agora e fere a Amaleque; e destrói totalmente a tudo o que tiver, e não lhe perdoes; porém matarás desde o homem até à mulher, desde os meninos até aos de peito, desde os bois até às ovelhas, e desde os camelos até aos jumentos.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 4, 'O que Saul convocou ao povo, e os contou em Telaim, duzentos mil homens de pé, e dez mil homens de Judá.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 5, 'Chegando, pois, Saul à cidade de Amaleque, pôs emboscada no vale.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 6, 'E disse Saul aos queneus: Ide-vos, retirai-vos e saí do meio dos amalequitas, para que não vos destrua juntamente com eles, porque vós usastes de misericórdia com todos os filhos de Israel, quando subiram do Egito. Assim os queneus se retiraram do meio dos amalequitas.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 7, 'Então feriu Saul aos amalequitas desde Havilá até chegar a Sur, que está defronte do Egito.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 8, 'E tomou vivo a Agague, rei dos amalequitas; porém a todo o povo destruiu ao fio da espada.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 9, 'E Saul e o povo pouparam a Agague, e ao melhor das ovelhas e das vacas, e as da segunda ordem, e aos cordeiros e ao melhor que havia, e não os quiseram destruir totalmente; porém a toda a coisa vil e desprezível destruíram totalmente.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 10, 'Então veio a palavra do Senhor a Samuel, dizendo:', 2, CURRENT_TIMESTAMP, false),
(9, 15, 11, 'Arrependo-me de haver posto a Saul como rei; porquanto deixou de me seguir, e não cumpriu as minhas palavras. Então Samuel se contristou, e toda a noite clamou ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 12, 'E madrugou Samuel para encontrar a Saul pela manhã: e anunciou-se a Samuel, dizendo: Já chegou Saul ao Carmelo, e eis que levantou para si uma coluna. Então voltando, passou e desceu a Gilgal.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 13, 'Veio, pois, Samuel a Saul; e Saul lhe disse: Bendito sejas tu do Senhor; cumpri a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 14, 'Então disse Samuel: Que balido, pois, de ovelhas é este aos meus ouvidos, e o mugido de vacas que ouço?', 2, CURRENT_TIMESTAMP, false),
(9, 15, 15, 'E disse Saul: De Amaleque as trouxeram; porque o povo poupou ao melhor das ovelhas, e das vacas, para as oferecer ao Senhor teu Deus; o resto, porém, temos destruído totalmente.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 16, 'Então disse Samuel a Saul: Espera, e te declararei o que o Senhor me disse esta noite. E ele disse-lhe: Fala.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 17, 'E disse Samuel: Porventura, sendo tu pequeno aos teus olhos, não foste por cabeça das tribos de Israel? E o Senhor te ungiu rei sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 18, 'E enviou-te o Senhor a este caminho, e disse: Vai, e destrói totalmente a estes pecadores, os amalequitas, e peleja contra eles, até que os aniquiles.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 19, 'Por que, pois, não deste ouvidos à voz do Senhor, antes te lançaste ao despojo, e fizeste o que parecia mau aos olhos do Senhor?', 2, CURRENT_TIMESTAMP, false),
(9, 15, 20, 'Então disse Saul a Samuel: Antes dei ouvidos à voz do Senhor, e caminhei no caminho pelo qual o Senhor me enviou; e trouxe a Agague, rei de Amaleque, e os amalequitas destruí totalmente;', 2, CURRENT_TIMESTAMP, false),
(9, 15, 21, 'Mas o povo tomou do despojo ovelhas e vacas, o melhor do interdito, para oferecer ao Senhor teu Deus em Gilgal.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 22, 'Porém Samuel disse: Tem porventura o Senhor tanto prazer em holocaustos e sacrifícios, como em que se obedeça à palavra do Senhor? Eis que o obedecer é melhor do que o sacrificar; e o atender melhor é do que a gordura de carneiros.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 23, 'Porque a rebelião é como o pecado de feitiçaria, e o porfiar é como iniqüidade e idolatria. Porquanto tu rejeitaste a palavra do Senhor, ele também te rejeitou a ti, para que não sejas rei.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 24, 'Então disse Saul a Samuel: Pequei, porquanto tenho transgredido a ordem do Senhor e as tuas palavras; porque temi ao povo, e dei ouvidos à sua voz.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 25, 'Agora, pois, rogo-te perdoa o meu pecado; e volta comigo, para que adore ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 26, 'Porém Samuel disse a Saul: Não voltarei contigo; porquanto rejeitaste a palavra do Senhor, já te rejeitou o Senhor, para que não sejas rei sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 27, 'E virando-se Samuel para se ir, ele lhe pegou pela orla da capa, e a rasgou.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 28, 'Então Samuel lhe disse: O Senhor tem rasgado de ti hoje o reino de Israel, e o tem dado ao teu próximo, melhor do que tu.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 29, 'E também aquele que é a Força de Israel não mente nem se arrepende; porquanto não é um homem para que se arrependa.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 30, 'Disse ele então: Pequei; honra-me, porém, agora diante dos anciãos do meu povo, e diante de Israel; e volta comigo, para que adore ao Senhor teu Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 31, 'Então, voltando Samuel, seguiu a Saul; e Saul adorou ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 32, 'Então disse Samuel: Trazei-me aqui a Agague, rei dos amalequitas. E Agague veio a ele animosamente; e disse Agague: Na verdade já passou a amargura da morte.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 33, 'Disse, porém, Samuel: Assim como a tua espada desfilhou as mulheres, assim ficará desfilhada a tua mãe entre as mulheres. Então Samuel despedaçou a Agague perante o Senhor em Gilgal.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 34, 'Então Samuel se foi a Ramá; e Saul subiu à sua casa, a Gibeá de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 15, 35, 'E nunca mais viu Samuel a Saul até ao dia da sua morte; porque Samuel teve dó de Saul. E o Senhor se arrependeu de haver posto a Saul rei sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 1, 'Então disse o SENHOR a Samuel: Até quando terás dó de Saul, havendo-o eu rejeitado, para que não reine sobre Israel? Enche um chifre de azeite, e vem, enviar-te-ei a Jessé o belemita; porque dentre os seus filhos me tenho provido de um rei.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 2, 'Porém disse Samuel: Como irei eu? pois, ouvindo-o Saul, me matará. Então disse o Senhor: Toma uma bezerra das vacas em tuas mãos, e dize: Vim para sacrificar ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 3, 'E convidarás a Jessé ao sacrifício; e eu te farei saber o que hás de fazer, e ungir-me-ás a quem eu te disser.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 4, 'Fez, pois, Samuel o que dissera o Senhor, e veio a Belém; então os anciãos da cidade saíram ao encontro, tremendo, e disseram: De paz é a tua vinda?', 2, CURRENT_TIMESTAMP, false),
(9, 16, 5, 'E disse ele: É de paz, vim sacrificar ao Senhor; santificai-vos, e vinde comigo ao sacrifício. E santificou ele a Jessé e a seus filhos, e os convidou ao sacrifício.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 6, 'E sucedeu que, entrando eles, viu a Eliabe, e disse: Certamente está perante o Senhor o seu ungido.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 7, 'Porém o Senhor disse a Samuel: Não atentes para a sua aparência, nem para a grandeza da sua estatura, porque o tenho rejeitado; porque o Senhor não vê como vê o homem, pois o homem vê o que está diante dos olhos, porém o Senhor olha para o coração.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 8, 'Então chamou Jessé a Abinadabe, e o fez passar diante de Samuel, o qual disse: Nem a este tem escolhido o Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 9, 'Então Jessé fez passar a Sama; porém disse: Tampouco a este tem escolhido o Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 10, 'Assim fez passar Jessé a seus sete filhos diante de Samuel; porém Samuel disse a Jessé: O Senhor não tem escolhido a estes.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 11, 'Disse mais Samuel a Jessé: Acabaram-se os moços? E disse: Ainda falta o menor, que está apascentando as ovelhas. Disse, pois, Samuel a Jessé: Manda chamá-lo, porquanto não nos assentaremos até que ele venha aqui.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 12, 'Então mandou chamá-lo e fê-lo entrar (e era ruivo e formoso de semblante e de boa presença); e disse o Senhor: Levanta-te, e unge-o, porque é este mesmo.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 13, 'Então Samuel tomou o chifre do azeite, e ungiu-o no meio de seus irmãos; e desde aquele dia em diante o Espírito do Senhor se apoderou de Davi; então Samuel se levantou, e voltou a Ramá.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 14, 'E o Espírito do Senhor se retirou de Saul, e atormentava-o um espírito mau da parte do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 15, 'Então os criados de Saul lhe disseram: Eis que agora o espírito mau da parte de Deus te atormenta;', 2, CURRENT_TIMESTAMP, false),
(9, 16, 16, 'Diga, pois, nosso senhor a seus servos, que estão na tua presença, que busquem um homem que saiba tocar harpa, e será que, quando o espírito mau da parte de Deus vier sobre ti, então ele tocará com a sua mão, e te acharás melhor.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 17, 'Então disse Saul aos seus servos: Buscai-me, pois, um homem que toque bem, e trazei-mo.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 18, 'Então respondeu um dos moços, e disse: Eis que tenho visto a um filho de Jessé, o belemita, que sabe tocar e é valente e vigoroso, e homem de guerra, e prudente em palavras, e de gentil presença; o Senhor é com ele.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 19, 'E Saul enviou mensageiros a Jessé, dizendo: Envia-me Davi, teu filho, o que está com as ovelhas.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 20, 'Então tomou Jessé um jumento carregado de pão, e um odre de vinho, e um cabrito, e enviou-os a Saul pela mão de Davi, seu filho.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 21, 'Assim Davi veio a Saul, e esteve perante ele, e o amou muito, e foi seu pajem de armas.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 22, 'Então Saul mandou dizer a Jessé: Deixa estar a Davi perante mim, pois achou graça em meus olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 16, 23, 'E sucedia que, quando o espírito mau da parte de Deus vinha sobre Saul, Davi tomava a harpa, e a tocava com a sua mão; então Saul sentia alívio, e se achava melhor, e o espírito mau se retirava dele.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 1, 'E os filisteus ajuntaram as suas forças para a guerra e congregaram-se em Socó, que está em Judá, e acamparam-se entre Socó e Azeca, no termo de Damim.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 2, 'Porém Saul e os homens de Israel se ajuntaram e acamparam no vale do carvalho, e ordenaram a batalha contra os filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 3, 'E os filisteus estavam num monte de um lado, e os israelitas estavam num monte do outro lado; e o vale estava entre eles.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 4, 'Então saiu do arraial dos filisteus um homem guerreiro, cujo nome era Golias, de Gate, que tinha de altura seis côvados e um palmo.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 5, 'Trazia na cabeça um capacete de bronze, e vestia uma couraça de escamas; e era o peso da couraça de cinco mil siclos de bronze.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 6, 'E trazia grevas de bronze por cima de seus pés, e um escudo de bronze entre os seus ombros.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 7, 'E a haste da sua lança era como o eixo do tecelão, e a ponta da sua lança de seiscentos siclos de ferro, e diante dele ia o escudeiro.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 8, 'E parou, e clamou às companhias de Israel, e disse-lhes: Para que saireis a ordenar a batalha? Não sou eu filisteu e vós servos de Saul? Escolhei dentre vós um homem que desça a mim.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 9, 'Se ele puder pelejar comigo, e me ferir, a vós seremos por servos; porém, se eu o vencer, e o ferir, então a nós sereis por servos, e nos servireis.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 10, 'Disse mais o filisteu: Hoje desafio as companhias de Israel, dizendo: Dai-me um homem, para que ambos pelejemos.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 11, 'Ouvindo então Saul e todo o Israel estas palavras do filisteu, espantaram-se, e temeram muito.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 12, 'E Davi era filho de um homem efrateu, de Belém de Judá, cujo nome era Jessé, que tinha oito filhos; e nos dias de Saul era este homem já velho e adiantado em idade entre os homens.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 13, 'Foram-se os três filhos mais velhos de Jessé, e seguiram a Saul à guerra; e eram os nomes de seus três filhos, que se foram à guerra, Eliabe, o primogênito, e o segundo Abinadabe, e o terceiro Sama.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 14, 'E Davi era o menor; e os três maiores seguiram a Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 15, 'Davi, porém, ia e voltava de Saul, para apascentar as ovelhas de seu pai em Belém.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 16, 'Chegava-se, pois, o filisteu pela manhã e à tarde; e apresentou-se por quarenta dias.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 17, 'E disse Jessé a Davi, seu filho: Toma, peço-te, para teus irmãos um efa deste grão tostado e estes dez pães, e corre a levá-los ao arraial, a teus irmãos.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 18, 'Porém estes dez queijos de leite leva ao capitão de mil; e visitarás a teus irmãos, a ver se vão bem; e tomarás o seu penhor.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 19, 'E estavam Saul, e eles, e todos os homens de Israel no vale do carvalho, pelejando com os filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 20, 'Davi então se levantou de madrugada, pela manhã, e deixou as ovelhas com um guarda, e carregou-se, e partiu, como Jessé lhe ordenara; e chegou ao lugar dos carros, quando já o exército saía em ordem de batalha, e a gritos chamavam à peleja.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 21, 'E os israelitas e filisteus se puseram em ordem, fileira contra fileira.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 22, 'E Davi deixou a carga que trouxera na mão do guarda da bagagem, e correu à batalha; e, chegando, perguntou a seus irmãos se estavam bem.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 23, 'E, estando ele ainda falando com eles, eis que vinha subindo do exército dos filisteus o homem guerreiro, cujo nome era Golias, o filisteu de Gate; e falou conforme àquelas palavras, e Davi as ouviu.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 24, 'Porém todos os homens em Israel, vendo aquele homem, fugiram de diante dele, e temiam grandemente.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 25, 'E diziam os homens de Israel: Vistes aquele homem que subiu? Pois subiu para afrontar a Israel; há de ser, pois, que, o homem que o ferir, o rei o enriquecerá de grandes riquezas, e lhe dará a sua filha, e fará livre a casa de seu pai em Israel.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 26, 'Então falou Davi aos homens que estavam com ele, dizendo: Que farão àquele homem, que ferir a este filisteu, e tirar a afronta de sobre Israel? Quem é, pois, este incircunciso filisteu, para afrontar os exércitos do Deus vivo?', 2, CURRENT_TIMESTAMP, false),
(9, 17, 27, 'E o povo lhe tornou a falar conforme àquela palavra dizendo: Assim farão ao homem que o ferir.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 28, 'E, ouvindo Eliabe, seu irmão mais velho, falar àqueles homens, acendeu-se a ira de Eliabe contra Davi, e disse: Por que desceste aqui? Com quem deixaste aquelas poucas ovelhas no deserto? Bem conheço a tua presunção, e a maldade do teu coração, que desceste para ver a peleja.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 29, 'Então disse Davi: Que fiz eu agora? Porventura não há razão para isso?', 2, CURRENT_TIMESTAMP, false),
(9, 17, 30, 'E desviou-se dele para outro, e falou conforme àquela palavra; e o povo lhe tornou a responder conforme às primeiras palavras.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 31, 'E, ouvidas as palavras que Davi havia falado, as anunciaram a Saul, que mandou chamá-lo.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 32, 'E Davi disse a Saul: Não desfaleça o coração de ninguém por causa dele; teu servo irá, e pelejará contra este filisteu.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 33, 'Porém Saul disse a Davi: Contra este filisteu não poderás ir para pelejar com ele; pois tu ainda és moço, e ele homem de guerra desde a sua mocidade.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 34, 'Então disse Davi a Saul: Teu servo apascentava as ovelhas de seu pai; e quando vinha um leão e um urso, e tomava uma ovelha do rebanho,', 2, CURRENT_TIMESTAMP, false),
(9, 17, 35, 'Eu saía após ele e o feria, e livrava-a da sua boca; e, quando ele se levantava contra mim, lançava-lhe mão da barba, e o feria e o matava.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 36, 'Assim feria o teu servo o leão, como o urso; assim será este incircunciso filisteu como um deles; porquanto afrontou os exércitos do Deus vivo.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 37, 'Disse mais Davi: O Senhor me livrou das garras do leão, e das do urso; ele me livrará da mão deste filisteu. Então disse Saul a Davi: Vai, e o Senhor seja contigo.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 38, 'E Saul vestiu a Davi de suas vestes, e pôs-lhe sobre a cabeça um capacete de bronze; e o vestiu de uma couraça.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 39, 'E Davi cingiu a espada sobre as suas vestes, e começou a andar; porém nunca o havia experimentado; então disse Davi a Saul: Não posso andar com isto, pois nunca o experimentei. E Davi tirou aquilo de sobre si.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 40, 'E tomou o seu cajado na mão, e escolheu para si cinco seixos do ribeiro, e pô-los no alforje de pastor, que trazia, a saber, no surrão, e lançou mão da sua funda; e foi aproximando-se do filisteu.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 41, 'O filisteu também vinha se aproximando de Davi; e o que lhe levava o escudo ia adiante dele.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 42, 'E, olhando o filisteu, e vendo a Davi, o desprezou, porquanto era moço, ruivo, e de gentil aspecto.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 43, 'Disse, pois, o filisteu a Davi: Sou eu algum cão, para tu vires a mim com paus? E o filisteu pelos seus deuses amaldiçoou a Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 44, 'Disse mais o filisteu a Davi: Vem a mim, e darei a tua carne às aves do céu e às bestas do campo.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 45, 'Davi, porém, disse ao filisteu: Tu vens a mim com espada, e com lança, e com escudo; porém eu venho a ti em nome do Senhor dos Exércitos, o Deus dos exércitos de Israel, a quem tens afrontado.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 46, 'Hoje mesmo o Senhor te entregará na minha mão, e ferir-te-ei, e tirar-te-ei a cabeça, e os corpos do arraial dos filisteus darei hoje mesmo às aves do céu e às feras da terra; e toda a terra saberá que há Deus em Israel;', 2, CURRENT_TIMESTAMP, false),
(9, 17, 47, 'E saberá toda esta congregação que o Senhor salva, não com espada, nem com lança; porque do Senhor é a guerra, e ele vos entregará na nossa mão.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 48, 'E sucedeu que, levantando-se o filisteu, e indo encontrar-se com Davi, apressou-se Davi, e correu ao combate, a encontrar-se com o filisteu.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 49, 'E Davi pôs a mão no alforje, e tomou dali uma pedra e com a funda lha atirou, e feriu o filisteu na testa, e a pedra se lhe encravou na testa, e caiu sobre o seu rosto em terra.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 50, 'Assim Davi prevaleceu contra o filisteu, com uma funda e com uma pedra, e feriu o filisteu, e o matou; sem que Davi tivesse uma espada na mão.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 51, 'Por isso correu Davi, e pôs-se em pé sobre o filisteu, e tomou a sua espada, e tirou-a da bainha, e o matou, e lhe cortou com ela a cabeça; vendo então os filisteus, que o seu herói era morto, fugiram.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 52, 'Então os homens de Israel e Judá se levantaram, e jubilaram, e seguiram os filisteus, até chegar ao vale, e até às portas de Ecrom; e caíram os feridos dos filisteus pelo caminho de Saaraim até Gate e até Ecrom.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 53, 'Então voltaram os filhos de Israel de perseguirem os filisteus, e despojaram os seus arraiais.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 54, 'E Davi tomou a cabeça do filisteu, e a trouxe a Jerusalém; porém pôs as armas dele na sua tenda.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 55, 'Vendo, porém, Saul, sair Davi a encontrar-se com o filisteu, disse a Abner, o capitão do exército: De quem é filho este moço, Abner? E disse Abner: Vive a tua alma, ó rei, que o não sei.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 56, 'Disse então o rei: Pergunta, pois, de quem é filho este moço.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 57, 'Voltando, pois, Davi de ferir o filisteu, Abner o tomou consigo, e o trouxe à presença de Saul, trazendo ele na mão a cabeça do filisteu.', 2, CURRENT_TIMESTAMP, false),
(9, 17, 58, 'E disse-lhe Saul: De quem és filho, jovem? E disse Davi: Filho de teu servo Jessé, belemita.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 1, 'E sucedeu que, acabando ele de falar com Saul, a alma de Jônatas se ligou com a alma de Davi; e Jônatas o amou, como à sua própria alma.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 2, 'E Saul naquele dia o tomou, e não lhe permitiu que voltasse para casa de seu pai.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 3, 'E Jônatas e Davi fizeram aliança; porque Jônatas o amava como à sua própria alma.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 4, 'E Jônatas se despojou da capa que trazia sobre si, e a deu a Davi, como também as suas vestes, até a sua espada, e o seu arco, e o seu cinto.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 5, 'E saía Davi aonde quer que Saul o enviasse e conduzia-se com prudência, e Saul o pôs sobre os homens de guerra; e era aceito aos olhos de todo o povo, e até aos olhos dos servos de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 6, 'Sucedeu, porém, que, vindo eles, quando Davi voltava de ferir os filisteus, as mulheres de todas as cidades de Israel saíram ao encontro do rei Saul, cantando e dançando, com adufes, com alegria, e com instrumentos de música.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 7, 'E as mulheres dançando e cantando se respondiam umas às outras, dizendo: Saul feriu os seus milhares, porém, Davi os seus dez milhares.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 8, 'Então Saul se indignou muito, e aquela palavra pareceu mal aos seus olhos, e disse: Dez milhares deram a Davi, e a mim somente milhares; na verdade, que lhe falta, senão só o reino?', 2, CURRENT_TIMESTAMP, false),
(9, 18, 9, 'E, desde aquele dia em diante, Saul tinha Davi em suspeita.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 10, 'E aconteceu no outro dia, que o mau espírito da parte de Deus se apoderou de Saul, e profetizava no meio da casa; e Davi tocava a harpa com a sua mão, como nos outros dias; Saul, porém, tinha na mão uma lança.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 11, 'E Saul atirou com a lança, dizendo: Encravarei a Davi na parede. Porém Davi se desviou dele por duas vezes.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 12, 'E temia Saul a Davi, porque o Senhor era com ele e se tinha retirado de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 13, 'Por isso Saul o desviou de si, e o pôs por capitão de mil; e saía e entrava diante do povo.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 14, 'E Davi se conduzia com prudência em todos os seus caminhos, e o Senhor era com ele.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 15, 'Vendo então Saul que tão prudentemente se conduzia, tinha receio dele.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 16, 'Porém todo o Israel e Judá amava a Davi, porquanto saía e entrava diante deles.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 17, 'Por isso Saul disse a Davi: Eis que Merabe, minha filha mais velha, te darei por mulher; sê-me somente filho valoroso, e guerreia as guerras do Senhor (porque Saul dizia consigo: Não seja contra ele a minha mão, mas sim a dos filisteus).', 2, CURRENT_TIMESTAMP, false),
(9, 18, 18, 'Mas Davi disse a Saul: Quem sou eu, e qual é a minha vida e a família de meu pai em Israel, para vir a ser genro do rei?', 2, CURRENT_TIMESTAMP, false),
(9, 18, 19, 'Sucedeu, porém, que ao tempo que Merabe, filha de Saul, devia ser dada a Davi, ela foi dada por mulher a Adriel, meolatita.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 20, 'Mas Mical, a outra filha de Saul amava a Davi; o que, sendo anunciado a Saul, pareceu isto bom aos seus olhos.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 21, 'E Saul disse: Eu lha darei, para que lhe sirva de laço, e para que a mão dos filisteus venha a ser contra ele. Pelo que Saul disse a Davi: Com a outra serás hoje meu genro.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 22, 'E Saul deu ordem aos seus servos: Falai em segredo a Davi, dizendo: Eis que o rei te está mui afeiçoado, e todos os seus servos te amam; agora, pois, consente em ser genro do rei.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 23, 'E os servos de Saul falaram todas estas palavras aos ouvidos de Davi. Então disse Davi: Parece-vos pouco aos vossos olhos ser genro do rei, sendo eu homem pobre e desprezível?', 2, CURRENT_TIMESTAMP, false),
(9, 18, 24, 'E os servos de Saul lhe anunciaram isto, dizendo: Foram tais as palavras que falou Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 25, 'Então disse Saul: Assim direis a Davi: O rei não tem necessidade de dote, senão de cem prepúcios de filisteus, para se tomar vingança dos inimigos do rei. Porquanto Saul tentava fazer cair a Davi pela mão dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 26, 'E anunciaram os seus servos estas palavras a Davi, e este negócio pareceu bem aos olhos de Davi, de que fosse genro do rei; porém ainda os dias não se haviam cumprido.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 27, 'Então Davi se levantou, e partiu com os seus homens, e feriu dentre os filisteus duzentos homens, e Davi trouxe os seus prepúcios, e os entregou todos ao rei, para que fosse genro do rei; então Saul lhe deu por mulher a sua filha.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 28, 'E viu Saul, e notou que o Senhor era com Davi; e Mical, filha de Saul, o amava.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 29, 'Então Saul temeu muito mais a Davi; e Saul foi todos os seus dias inimigo de Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 18, 30, 'E, saindo os príncipes dos filisteus à campanha, sucedia que Davi se conduzia com mais êxito do que todos os servos de Saul; portanto o seu nome era muito estimado.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 1, 'E falou Saul a Jônatas, seu filho, e a todos os seus servos, para que matassem a Davi. Porém Jônatas, filho de Saul, estava mui afeiçoado a Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 2, 'E Jônatas o anunciou a Davi, dizendo: Meu pai, Saul, procura matar-te, pelo que agora guarda-te pela manhã, e fica-te em oculto, e esconde-te.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 3, 'E sairei eu, e estarei à mão de meu pai no campo em que estiverdes, e eu falarei de ti a meu pai, e verei o que há, e to anunciarei.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 4, 'Então Jônatas falou bem de Davi a Saul, seu pai, e disse-lhe: Não peque o rei contra seu servo Davi, porque ele não pecou contra ti, e porque os seus feitos te são muito bons.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 5, 'Porque expôs a sua vida, e feriu aos filisteus, e fez o Senhor um grande livramento a todo o Israel; tu mesmo o viste, e te alegraste; porque, pois, pecarias contra o sangue inocente, matando a Davi, sem causa?', 2, CURRENT_TIMESTAMP, false),
(9, 19, 6, 'E Saul deu ouvidos à voz de Jônatas, e jurou Saul: Vive o Senhor, que não morrerá.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 7, 'E Jônatas chamou a Davi, e contou-lhe todas estas palavras; e Jônatas levou Davi a Saul, e esteve perante ele como antes.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 8, 'E tornou a haver guerra; e saiu Davi, e pelejou contra os filisteus, e feriu-os com grande matança, e fugiram diante dele.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 9, 'Porém o espírito mau da parte do Senhor se tornou sobre Saul, estando ele assentado em sua casa, e tendo na mão a sua lança; e tocava Davi com a mão, a harpa.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 10, 'E procurou Saul encravar a Davi na parede, porém ele se desviou de diante de Saul, o qual feriu com a lança a parede; então fugiu Davi, e escapou naquela mesma noite.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 11, 'Porém Saul mandou mensageiros à casa de Davi, que o guardassem, e o matassem pela manhã; do que Mical, sua mulher, avisou a Davi, dizendo: Se não salvares a tua vida esta noite, amanhã te matarão.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 12, 'Então Mical desceu a Davi por uma janela; e ele se foi, e fugiu, e escapou.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 13, 'E Mical tomou uma estátua e a deitou na cama, e pôs-lhe à cabeceira uma pele de cabra, e a cobriu com uma coberta.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 14, 'E, mandando Saul mensageiros que trouxessem a Davi, ela disse: Está doente.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 15, 'Então Saul tornou a mandar mensageiros que fossem a Davi, dizendo: Trazei-mo na cama, para que o mate.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 16, 'Vindo, pois, os mensageiros, eis que a estátua estava na cama, e a pele de cabra à sua cabeceira.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 17, 'Então disse Saul a Mical: Por que assim me enganaste, e deixaste ir e escapar o meu inimigo? E disse Mical a Saul: Porque ele me disse: Deixa-me ir, por que hei de eu matar-te?', 2, CURRENT_TIMESTAMP, false),
(9, 19, 18, 'Assim Davi fugiu e escapou, e foi a Samuel, em Ramá, e lhe participou tudo quanto Saul lhe fizera; e foram, ele e Samuel, e ficaram em Naiote.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 19, 'E o anunciaram a Saul, dizendo: Eis que Davi está em Naiote, em Ramá.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 20, 'Então enviou Saul mensageiros para trazerem a Davi, os quais viram uma congregação de profetas profetizando, onde estava Samuel que presidia sobre eles; e o Espírito de Deus veio sobre os mensageiros de Saul, e também eles profetizaram.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 21, 'E, avisado disto Saul, enviou outros mensageiros, e também estes profetizaram; então enviou Saul ainda uns terceiros mensageiros, os quais também profetizaram.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 22, 'Então foi também ele mesmo a Ramá, e chegou ao poço grande que estava em Secu; e, perguntando, disse: Onde estão Samuel e Davi? E disseram-lhe: Eis que estão em Naiote, em Ramá.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 23, 'Então foi para Naiote, em Ramá; e o mesmo Espírito de Deus veio sobre ele, e ia profetizando, até chegar a Naiote, em Ramá.', 2, CURRENT_TIMESTAMP, false),
(9, 19, 24, 'E ele também despiu as suas vestes, e profetizou diante de Samuel, e esteve nu por terra todo aquele dia e toda aquela noite; por isso se diz: Está também Saul entre os profetas?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 1, 'Então fugiu Davi de Naiote, em Ramá; e veio, e disse a Jônatas: Que fiz eu? Qual é o meu crime? E qual é o meu pecado diante de teu pai, que procura tirar-me a vida?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 2, 'E ele lhe disse: Tal não suceda; não morrerás; eis que meu pai não faz coisa nenhuma grande, nem pequena, sem primeiro me informar; por que, pois, meu pai me encobriria este negócio? Não será assim.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 3, 'Então Davi tornou a jurar, e disse: Teu pai sabe muito bem que achei graça em teus olhos; por isso disse: Não saiba isto Jônatas, para que não se magoe. Mas, na verdade, como vive o Senhor, e como vive a tua alma, há apenas um passo entre mim e a morte.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 4, 'E disse Jônatas a Davi: O que disser a tua alma, eu te farei.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 5, 'Disse Davi a Jônatas: Eis que amanhã é a lua nova, em que costumo assentar-me com o rei para comer; porém deixa-me ir, e esconder-me-ei no campo, até à tarde do terceiro dia.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 6, 'Se teu pai notar a minha ausência, dirás: Davi me pediu muito que o deixasse ir correndo a Belém, sua cidade; porquanto se faz lá o sacrifício anual para toda a linhagem.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 7, 'Se disser assim: Está bem; então teu servo tem paz; porém se muito se indignar, sabe que já está inteiramente determinado no mal.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 8, 'Usa, pois, de misericórdia com o teu servo, porque o fizeste entrar contigo em aliança do Senhor; se, porém, há em mim crime, mata-me tu mesmo; por que me levarias a teu pai?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 9, 'Então disse Jônatas: Longe de ti tal coisa; porém se de alguma forma soubesse que já este mal está inteiramente determinado por meu pai, para que viesse sobre ti, não to revelaria eu?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 10, 'E disse Davi a Jônatas: Quem me fará saber, se por acaso teu pai te responder asperamente?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 11, 'Então disse Jônatas a Davi: Vem e saiamos ao campo. E saíram ambos ao campo.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 12, 'E disse Jônatas a Davi: O Senhor Deus de Israel seja testemunha! Sondando eu a meu pai amanhã a estas horas, ou depois de amanhã, e eis que se houver coisa favorável para Davi, e eu então não enviar a ti, e não to fizer saber;', 2, CURRENT_TIMESTAMP, false),
(9, 20, 13, 'O Senhor faça assim com Jônatas outro tanto; que se aprouver a meu pai fazer-te mal, também to farei saber, e te deixarei partir, e irás em paz; e o Senhor seja contigo, assim como foi com meu pai.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 14, 'E, se eu então ainda viver, porventura não usarás comigo da beneficência do Senhor, para que não morra?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 15, 'Nem tampouco cortarás da minha casa a tua beneficência eternamente; nem ainda quando o Senhor desarraigar da terra a cada um dos inimigos de Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 16, 'Assim fez Jônatas aliança com a casa de Davi, dizendo: O Senhor o requeira da mão dos inimigos de Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 17, 'E Jônatas fez jurar a Davi de novo, porquanto o amava; porque o amava com todo o amor da sua alma.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 18, 'E disse-lhe Jônatas: Amanhã é a lua nova, e não te acharão no teu lugar, pois o teu assento se achará vazio.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 19, 'E, ausentando-te tu três dias, desce apressadamente, e vai àquele lugar onde te escondeste no dia do negócio; e fica-te junto à pedra de Ezel.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 20, 'E eu atirarei três flechas para aquele lado, como se atirasse ao alvo.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 21, 'E eis que mandarei o moço dizendo: Anda, busca as flechas. Se eu expressamente disser ao moço: Olha que as flechas estão para cá de ti; toma-o contigo, e vem, porque há paz para ti, e não há nada, vive o Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 22, 'Porém se disser ao moço assim: Olha que as flechas estão para lá de ti; vai-te embora, porque o Senhor te deixa ir.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 23, 'E quanto ao negócio de que eu e tu falamos, eis que o Senhor está entre mim e ti eternamente.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 24, 'Escondeu-se, pois, Davi no campo; e, sendo a lua nova, assentou-se o rei para comer pão.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 25, 'E, assentando-se o rei, como das outras vezes, no seu assento, no lugar junto à parede, Jônatas se levantou, e assentou-se Abner ao lado de Saul; e o lugar de Davi apareceu vazio.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 26, 'Porém naquele dia não disse Saul nada, porque dizia: Aconteceu-lhe alguma coisa, pela qual não está limpo; certamente não está limpo.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 27, 'Sucedeu também no outro dia, o segundo da lua nova, que o lugar de Davi apareceu vazio; disse, pois, Saul a Jônatas, seu filho: Por que não veio o filho de Jessé nem ontem nem hoje a comer pão?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 28, 'E respondeu Jônatas a Saul: Davi me pediu encarecidamente que o deixasse ir a Belém.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 29, 'Dizendo: Peço-te que me deixes ir, porquanto a nossa linhagem tem um sacrifício na cidade, e meu irmão mesmo me mandou ir; se, pois, agora tenho achado graça em teus olhos, peço-te que me deixes partir, para que veja a meus irmãos; por isso não veio à mesa do rei.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 30, 'Então se acendeu a ira de Saul contra Jônatas, e disse-lhe: Filho da mulher perversa e rebelde; não sei eu que tens escolhido o filho de Jessé, para vergonha tua e para vergonha da nudez de tua mãe?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 31, 'Porque todos os dias que o filho de Jessé viver sobre a terra nem tu estarás seguro, nem o teu reino; pelo que envia, e traze-mo nesta hora; porque é digno de morte.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 32, 'Então respondeu Jônatas a Saul, seu pai, e lhe disse: Por que há de morrer? Que tem feito?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 33, 'Então Saul atirou-lhe com a lança, para o ferir; assim entendeu Jônatas que já seu pai tinha determinado matar a Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 34, 'Por isso Jônatas, todo encolerizado, se levantou da mesa; e no segundo dia da lua nova não comeu pão; porque se magoava por causa de Davi, porque seu pai o tinha humilhado.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 35, 'E aconteceu, pela manhã, que Jônatas saiu ao campo, ao tempo que tinha ajustado com Davi, e um moço pequeno com ele.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 36, 'Então disse ao seu moço: Corre a buscar as flechas que eu atirar. Correu, pois, o moço, e ele atirou uma flecha, que fez passar além dele.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 37, 'E, chegando o moço ao lugar da flecha que Jônatas tinha atirado, gritou Jônatas atrás do moço, e disse: Não está porventura a flecha mais para lá de ti?', 2, CURRENT_TIMESTAMP, false),
(9, 20, 38, 'E tornou Jônatas a gritar atrás do moço: Apressa-te, corre, não te demores. E o moço de Jônatas apanhou as flechas, e veio a seu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 39, 'E o moço não entendeu coisa alguma; só Jônatas e Davi sabiam deste negócio.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 40, 'Então Jônatas deu as suas armas ao moço que trazia, e disse-lhe: Anda, e leva-as à cidade.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 41, 'E, indo-se o moço, levantou-se Davi do lado do sul, e lançou-se sobre o seu rosto em terra, e inclinou-se três vezes; e beijaram-se um ao outro, e choraram juntos, mas Davi chorou muito mais.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 42, 'E disse Jônatas a Davi: Vai-te em paz; o que nós temos jurado ambos em nome do Senhor, dizendo: O Senhor seja entre mim e ti, e entre a minha descendência e a tua descendência, seja perpetuamente.', 2, CURRENT_TIMESTAMP, false),
(9, 20, 43, 'Então se levantou Davi, e partiu; e Jônatas entrou na cidade.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 1, 'Então veio Davi a Nobe, ao sacerdote Aimeleque; e Aimeleque, tremendo, saiu ao encontro de Davi, e disse-lhe: Por que vens só, e ninguém contigo?', 2, CURRENT_TIMESTAMP, false),
(9, 21, 2, 'E disse Davi ao sacerdote Aimeleque: O rei me encomendou um negócio, e me disse: Ninguém saiba deste negócio, pelo qual eu te enviei, e o qual te ordenei; quanto aos moços, apontei-lhes tal e tal lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 3, 'Agora, pois, que tens à mão? Dá-me cinco pães na minha mão, ou o que se achar.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 4, 'E, respondendo o sacerdote a Davi, disse: Não tenho pão comum à mão; há, porém, pão sagrado, se ao menos os moços se abstiveram das mulheres.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 5, 'E respondeu Davi ao sacerdote, e lhe disse: As mulheres, na verdade, se nos vedaram desde ontem e anteontem; quando eu saí, os vasos dos moços eram santos; e de algum modo é pão comum, sendo que hoje santifica-se outro no vaso.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 6, 'Então o sacerdote lhe deu o pão sagrado, porquanto não havia ali outro pão senão os pães da proposição, que se tiraram de diante do Senhor, para se pôr ali pão quente no dia em que aquele se tirasse.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 7, 'Estava, porém, ali naquele dia um dos criados de Saul, detido perante o Senhor, e era seu nome Doegue, edomeu, o mais poderoso dos pastores de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 8, 'E disse Davi a Aimeleque: Não tens aqui à mão lança ou espada alguma? Porque não trouxe à mão nem a minha espada nem as minhas armas, porque o negócio do rei era apressado.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 9, 'E disse o sacerdote: A espada de Golias, o filisteu, a quem tu feriste no vale do carvalho, eis que está aqui envolta num pano detrás do éfode. Se tu a queres tomar, toma-a, porque nenhuma outra há aqui, senão aquela. E disse Davi: Não há outra semelhante; dá-ma.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 10, 'E Davi levantou-se, e fugiu aquele dia de diante de Saul, e foi a Aquis, rei de Gate.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 11, 'Porém os criados de Aquis lhe disseram: Não é este Davi, o rei da terra? Não se cantava deste nas danças, dizendo: Saul feriu os seus milhares, porém Davi os seus dez milhares?', 2, CURRENT_TIMESTAMP, false),
(9, 21, 12, 'E Davi considerou estas palavras no seu ânimo, e temeu muito diante de Aquis, rei de Gate.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 13, 'Por isso se contrafez diante dos olhos deles, e fez-se como doido entre as suas mãos, e esgravatava nas portas de entrada, e deixava correr a saliva pela barba.', 2, CURRENT_TIMESTAMP, false),
(9, 21, 14, 'Então disse Aquis aos seus criados: Eis que bem vedes que este homem está louco; por que mo trouxestes a mim?', 2, CURRENT_TIMESTAMP, false),
(9, 21, 15, 'Faltam-me a mim doidos, para que trouxésseis a este para que fizesse doidices diante de mim? Há de entrar este na minha casa?', 2, CURRENT_TIMESTAMP, false),
(9, 22, 1, 'Então Davi se retirou dali, e escapou para a caverna de Adulão; e ouviram-no seus irmãos e toda a casa de seu pai, e desceram ali para ter com ele.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 2, 'E ajuntou-se a ele todo o homem que se achava em aperto, e todo o homem endividado, e todo o homem de espírito desgostoso, e ele se fez capitão deles; e eram com ele uns quatrocentos homens.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 3, 'E foi Davi dali a Mizpá dos moabitas, e disse ao rei dos moabitas: Deixa estar meu pai e minha mãe convosco, até que saiba o que Deus há de fazer de mim.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 4, 'E trouxe-os perante o rei dos moabitas, e ficaram com ele todos os dias que Davi esteve no lugar forte.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 5, 'Porém o profeta Gade disse a Davi: Não fiques naquele lugar forte; vai, e entra na terra de Judá. Então Davi saiu, e foi para o bosque de Herete.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 6, 'E ouviu Saul que já se sabia de Davi e dos homens que estavam com ele; e estava Saul em Gibeá, debaixo de um arvoredo, em Ramá, e tinha na mão a sua lança, e todos os seus criados estavam com ele.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 7, 'Então disse Saul a todos os seus criados que estavam com ele: Ouvi, peço-vos, filhos de Benjamim, dar-vos-á também o filho de Jessé, a todos vós, terras e vinhas, e far-vos-á a todos capitães de milhares e capitães de centenas,', 2, CURRENT_TIMESTAMP, false),
(9, 22, 8, 'Para que todos vós tenhais conspirado contra mim, e ninguém há que me dê aviso de que meu filho tem feito aliança com o filho de Jessé, e nenhum dentre vós há que se doa de mim, e mo participe, pois meu filho tem contra mim sublevado a meu servo, para me armar ciladas, como se vê neste dia?', 2, CURRENT_TIMESTAMP, false),
(9, 22, 9, 'Então respondeu Doegue, o edomeu, que também estava com os criados de Saul, e disse: Vi o filho de Jessé chegar a Nobe, a Aimeleque, filho de Aitube,', 2, CURRENT_TIMESTAMP, false),
(9, 22, 10, 'O qual consultou por ele ao Senhor, e lhe deu mantimento, e lhe deu também a espada de Golias, o filisteu.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 11, 'Então o rei mandou chamar a Aimeleque, sacerdote, filho de Aitube, e a toda a casa de seu pai, os sacerdotes que estavam em Nobe; e todos eles vieram ao rei.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 12, 'E disse Saul: Ouve, peço-te, filho de Aitube. E ele disse: Eis-me aqui, senhor meu.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 13, 'Então lhe disse Saul: Por que conspirastes contra mim, tu e o filho de Jessé? Pois deste-lhe pão e espada, e consultaste por ele a Deus, para que se levantasse contra mim a armar-me ciladas, como se vê neste dia?', 2, CURRENT_TIMESTAMP, false),
(9, 22, 14, 'E respondeu Aimeleque ao rei e disse: E quem, entre todos os teus criados, há tão fiel como Davi, o genro do rei, pronto na sua obediência, e honrado na tua casa?', 2, CURRENT_TIMESTAMP, false),
(9, 22, 15, 'Comecei, porventura, hoje a consultar por ele a Deus? Longe de mim tal! Não impute o rei coisa nenhuma a seu servo, nem a toda a casa de meu pai, pois o teu servo não soube nada de tudo isso, nem muito nem pouco.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 16, 'Porém o rei disse: Aimeleque, morrerás certamente, tu e toda a casa de teu pai,', 2, CURRENT_TIMESTAMP, false),
(9, 22, 17, 'E disse o rei aos da sua guarda que estavam com ele: Virai-vos, e matai os sacerdotes do Senhor, porque também a sua mão é com Davi, e porque souberam que fugiu e não mo fizeram saber. Porém os criados do rei não quiseram estender as suas mãos para arremeter contra os sacerdotes do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 18, 'Então disse o rei a Doegue: Vira-te, e arremete contra os sacerdotes. Então se virou Doegue, o edomeu, e arremeteu contra os sacerdotes, e matou naquele dia oitenta e cinco homens que vestiam éfode de linho.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 19, 'Também a Nobe, cidade destes sacerdotes, passou a fio de espada, desde o homem até à mulher, desde os meninos até aos de peito, e até os bois, jumentos e ovelhas passou a fio de espada.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 20, 'Porém escapou um dos filhos de Aimeleque, filho de Aitube, cujo nome era Abiatar, o qual fugiu para Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 21, 'E Abiatar anunciou a Davi que Saul tinha matado os sacerdotes do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 22, 'Então Davi disse a Abiatar: Bem sabia eu naquele dia que, estando ali Doegue, o edomeu, não deixaria de o denunciar a Saul; eu dei ocasião contra todas as almas da casa de teu pai.', 2, CURRENT_TIMESTAMP, false),
(9, 22, 23, 'Fica comigo, não temas, porque quem procurar a minha morte também procurará a tua, pois estarás salvo comigo.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 1, 'E foi anunciado a Davi, dizendo: Eis que os filisteus pelejam contra Queila, e saqueiam as eiras.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 2, 'E consultou Davi ao Senhor, dizendo: Irei eu, e ferirei a estes filisteus? E disse o Senhor a Davi: Vai, e ferirás aos filisteus, e livrarás a Queila.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 3, 'Porém os homens de Davi lhe disseram: Eis que tememos aqui em Judá, quanto mais indo a Queila contra os esquadrões dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 4, 'Então Davi tornou a consultar ao Senhor, e o Senhor lhe respondeu, e disse: Levanta-te, desce a Queila, porque te dou os filisteus na tua mão.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 5, 'Então Davi partiu com os seus homens a Queila, e pelejou contra os filisteus, e levou os gados, e fez grande estrago entre eles; e Davi livrou os moradores de Queila.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 6, 'E sucedeu que, quando Abiatar, filho de Aimeleque, fugiu para Davi, a Queila, desceu com o éfode na mão.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 7, 'E foi anunciado a Saul que Davi tinha ido a Queila, e disse Saul: Deus o entregou nas minhas mãos, pois está encerrado, entrando numa cidade de portas e ferrolhos.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 8, 'Então Saul mandou chamar a todo o povo à peleja, para que descessem a Queila, para cercar a Davi e os seus homens.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 9, 'Sabendo, pois, Davi, que Saul maquinava este mal contra ele, disse a Abiatar, sacerdote: Traze aqui o éfode.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 10, 'E disse Davi: Ó Senhor, Deus de Israel, teu servo tem ouvido que Saul procura vir a Queila, para destruir a cidade por causa de mim.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 11, 'Entregar-me-ão os cidadãos de Queila na sua mão? Descerá Saul, como o teu servo tem ouvido? Ah! Senhor Deus de Israel! Faze-o saber ao teu servo. E disse o Senhor: Descerá.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 12, 'Disse mais Davi: Entregar-me-ão os cidadãos de Queila, a mim e aos meus homens, nas mãos de Saul? E disse o Senhor: Entregarão.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 13, 'Então Davi se levantou com os seus homens, uns seiscentos, e saíram de Queila, e foram-se aonde puderam; e sendo anunciado a Saul, que Davi escapara de Queila, cessou de sair contra ele.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 14, 'E Davi permaneceu no deserto, nos lugares fortes, e ficou em um monte no deserto de Zife; e Saul o buscava todos os dias, porém Deus não o entregou na sua mão.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 15, 'Vendo, pois, Davi, que Saul saíra à busca da sua vida, permaneceu no deserto de Zife, num bosque.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 16, 'Então se levantou Jônatas, filho de Saul, e foi para Davi no bosque, e confortou a sua mão em Deus;', 2, CURRENT_TIMESTAMP, false),
(9, 23, 17, 'E disse-lhe: Não temas, que não te achará a mão de Saul, meu pai; porém tu reinarás sobre Israel, e eu serei contigo o segundo; o que também Saul, meu pai, bem sabe.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 18, 'E ambos fizeram aliança perante o Senhor; Davi ficou no bosque, e Jônatas voltou para a sua casa.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 19, 'Então subiram os zifeus a Saul, a Gibeá, dizendo: Não se escondeu Davi entre nós, nos lugares fortes no bosque, no outeiro de Haquilá, que está à mão direita de Jesimom?', 2, CURRENT_TIMESTAMP, false),
(9, 23, 20, 'Agora, pois, ó rei, apressadamente desce conforme a todo o desejo da tua alma; a nós cumpre entregá-lo nas mãos do rei.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 21, 'Então disse Saul: Bendito sejais vós do Senhor, porque vos compadecestes de mim.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 22, 'Ide, pois, e diligenciai ainda mais, e sabei e notai o lugar que freqüenta, e quem o tenha visto ali; porque me foi dito que é astutíssimo.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 23, 'Por isso atentai bem, e informai-vos acerca de todos os esconderijos, em que ele se esconde; e então voltai para mim com toda a certeza, e ir-me-ei convosco; e há de ser que, se estiver naquela terra, o buscarei entre todos os milhares de Judá.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 24, 'Então se levantaram eles e se foram a Zife, adiante de Saul; Davi, porém, e os seus homens estavam no deserto de Maom, na campina, à direita de Jesimom.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 25, 'E Saul e os seus homens se foram em busca dele; o que anunciaram a Davi, que desceu para aquela penha, e ficou no deserto de Maom; o que ouvindo Saul, seguiu a Davi para o deserto de Maom.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 26, 'E Saul ia deste lado do monte, e Davi e os seus homens do outro lado do monte; e, temeroso, Davi se apressou a escapar de Saul; Saul, porém, e os seus homens cercaram a Davi e aos seus homens, para lançar mão deles.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 27, 'Então veio um mensageiro a Saul, dizendo: Apressa-te, e vem, porque os filisteus com ímpeto entraram na terra.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 28, 'Por isso Saul voltou de perseguir a Davi, e foi ao encontro dos filisteus; por esta razão aquele lugar se chamou Rochedo das Divisões.', 2, CURRENT_TIMESTAMP, false),
(9, 23, 29, 'E subiu Davi dali, e ficou nos lugares fortes de En-Gedi.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 1, 'E sucedeu que, voltando Saul de perseguir os filisteus, anunciaram-lhe, dizendo: Eis que Davi está no deserto de En-Gedi.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 2, 'Então tomou Saul três mil homens, escolhidos dentre todo o Israel, e foi em busca de Davi e dos seus homens, até sobre os cumes das penhas das cabras montesas.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 3, 'E chegou a uns currais de ovelhas no caminho, onde estava uma caverna; e entrou nela Saul, a cobrir seus pés; e Davi e os seus homens estavam nos fundos da caverna.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 4, 'Então os homens de Davi lhe disseram: Eis aqui o dia, do qual o Senhor te diz: Eis que te dou o teu inimigo nas tuas mãos, e far-lhe-ás como te parecer bem aos teus olhos. E levantou-se Davi, e mansamente cortou a orla do manto de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 5, 'Sucedeu, porém, que depois o coração doeu a Davi, por ter cortado a orla do manto de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 6, 'E disse aos seus homens: O SENHOR me guarde de que eu faça tal coisa ao meu senhor, ao ungido do SENHOR, estendendo eu a minha mão contra ele; pois é o ungido do SENHOR.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 7, 'E com estas palavras Davi conteve os seus homens, e não lhes permitiu que se levantassem contra Saul; e Saul se levantou da caverna, e prosseguiu o seu caminho.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 8, 'Depois também Davi se levantou, e saiu da caverna, e gritou por detrás de Saul, dizendo: Rei, meu senhor! E, olhando Saul para trás, Davi se inclinou com o rosto em terra, e se prostrou.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 9, 'E disse Davi a Saul: Por que dás tu ouvidos às palavras dos homens que dizem: Eis que Davi procura o teu mal?', 2, CURRENT_TIMESTAMP, false),
(9, 24, 10, 'Eis que este dia os teus olhos viram, que o SENHOR hoje te pôs em minhas mãos nesta caverna, e alguns disseram que te matasse; porém a minha mão te poupou; porque disse: Não estenderei a minha mão contra o meu senhor, pois é o ungido do SENHOR.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 11, 'Olha, pois, meu pai, vê aqui a orla do teu manto na minha mão; porque cortando-te eu a orla do manto, não te matei. Sabe, pois, e vê que não há na minha mão nem mal nem rebeldia alguma, e não pequei contra ti; porém tu andas à caça da minha vida, para ma tirares.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 12, 'Julgue o Senhor entre mim e ti, e vingue-me o Senhor de ti; porém a minha mão não será contra ti.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 13, 'Como diz o provérbio dos antigos: Dos ímpios procede a impiedade; porém a minha mão não será contra ti.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 14, 'Após quem saiu o rei de Israel? A quem persegues? A um cão morto? A uma pulga?', 2, CURRENT_TIMESTAMP, false),
(9, 24, 15, 'O Senhor, porém, será juiz, e julgará entre mim e ti, e verá, e advogará a minha causa, e me defenderá da tua mão.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 16, 'E sucedeu que, acabando Davi de falar a Saul todas estas palavras, disse Saul: É esta a tua voz, meu filho Davi? Então Saul levantou a sua voz e chorou.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 17, 'E disse a Davi: Mais justo és do que eu; pois tu me recompensaste com bem, e eu te recompensei com mal.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 18, 'E tu mostraste hoje que procedeste bem para comigo, pois o Senhor me tinha posto em tuas mãos, e tu não me mataste.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 19, 'Porque, quem há que, encontrando o seu inimigo, o deixaria ir por bom caminho? O Senhor, pois, te pague com bem, por isso que hoje me fizeste.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 20, 'Agora, pois, eis que bem sei que certamente hás de reinar, e que o reino de Israel há de ser firme na tua mão.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 21, 'Portanto agora jura-me pelo Senhor que não desarraigarás a minha descendência depois de mim, nem desfarás o meu nome da casa de meu pai.', 2, CURRENT_TIMESTAMP, false),
(9, 24, 22, 'Então jurou Davi a Saul. E foi Saul para a sua casa; porém Davi e os seus homens subiram ao lugar forte.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 1, 'E faleceu Samuel, e todo o Israel se ajuntou, e o prantearam, e o sepultaram na sua casa, em Ramá. E Davi se levantou e desceu ao deserto de Parã.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 2, 'E havia um homem em Maom, que tinha as suas possessões no Carmelo; e era este homem muito poderoso, e tinha três mil ovelhas e mil cabras; e estava tosquiando as suas ovelhas no Carmelo.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 3, 'E era o nome deste homem Nabal, e o nome de sua mulher Abigail; e era a mulher de bom entendimento e formosa; porém o homem era duro, e maligno nas obras, e era da casa de Calebe.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 4, 'E ouviu Davi no deserto que Nabal tosquiava as suas ovelhas,', 2, CURRENT_TIMESTAMP, false),
(9, 25, 5, 'E enviou Davi dez moços, e disse aos moços: Subi ao Carmelo, e, indo a Nabal, perguntai-lhe, em meu nome, como está.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 6, 'E assim direis àquele próspero: Paz tenhas, e que a tua casa tenha paz, e tudo o que tens tenha paz!', 2, CURRENT_TIMESTAMP, false),
(9, 25, 7, 'Agora, pois, tenho ouvido que tens tosquiadores. Ora, os pastores que tens estiveram conosco; agravo nenhum lhes fizemos, nem coisa alguma lhes faltou todos os dias que estiveram no Carmelo.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 8, 'Pergunta-o aos teus moços, e eles to dirão. Estes moços, pois, achem graça em teus olhos, porque viemos em boa ocasião. Dá, pois, a teus servos e a Davi, teu filho, o que achares à mão.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 9, 'Chegando, pois, os moços de Davi, e falando a Nabal todas aquelas palavras em nome de Davi, se calaram.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 10, 'E Nabal respondeu aos criados de Davi, e disse: Quem é Davi, e quem é o filho de Jessé? Muitos servos há hoje, que fogem ao seu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 11, 'Tomaria eu, pois, o meu pão, e a minha água, e a carne das minhas reses que degolei para os meus tosquiadores, e o daria a homens que eu não sei donde vêm?', 2, CURRENT_TIMESTAMP, false),
(9, 25, 12, 'Então os moços de Davi puseram-se a caminho e voltaram, e chegando, lhe anunciaram tudo conforme a todas estas palavras.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 13, 'Por isso disse Davi aos seus homens: Cada um cinja a sua espada. E cada um cingiu a sua espada, e cingiu também Davi a sua; e subiram após Davi uns quatrocentos homens, e duzentos ficaram com a bagagem.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 14, 'Porém um dentre os moços o anunciou a Abigail, mulher de Nabal, dizendo: Eis que Davi enviou mensageiros desde o deserto a saudar o nosso amo; porém ele os destratou.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 15, 'Todavia, aqueles homens têm-nos sido muito bons, e nunca fomos agravados por eles, e nada nos faltou em todos os dias que convivemos com eles quando estavam no campo.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 16, 'De muro em redor nos serviram, assim de dia como de noite, todos os dias que andamos com eles apascentando as ovelhas.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 17, 'Considera, pois, agora, e vê o que hás de fazer, porque o mal já está de todo determinado contra o nosso amo e contra toda a sua casa, e ele é um homem vil, que não há quem lhe possa falar.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 18, 'Então Abigail se apressou, e tomou duzentos pães, e dois odres de vinho, e cinco ovelhas guisadas, e cinco medidas de trigo tostado, e cem cachos de passas, e duzentas pastas de figos passados, e os pôs sobre jumentos.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 19, 'E disse aos seus moços: Ide adiante de mim, eis que vos seguirei de perto. O que, porém, não declarou a seu marido Nabal.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 20, 'E sucedeu que, andando ela montada num jumento, desceu pelo encoberto do monte, e eis que Davi e os seus homens lhe vinham ao encontro, e ela encontrou-se com eles.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 21, 'E disse Davi: Na verdade que em vão tenho guardado tudo quanto este tem no deserto, e nada lhe faltou de tudo quanto tem, e ele me pagou mal por bem.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 22, 'Assim faça Deus aos inimigos de Davi, e outro tanto, se eu deixar até amanhã de tudo o que tem, até mesmo um menino.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 23, 'Vendo, pois, Abigail a Davi, apressou-se, e desceu do jumento, e prostrou-se sobre o seu rosto diante de Davi, e se inclinou à terra.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 24, 'E lançou-se a seus pés, e disse: Ah, senhor meu, minha seja a transgressão; deixa, pois, falar a tua serva aos teus ouvidos, e ouve as palavras da tua serva.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 25, 'Meu senhor, agora não faça este homem vil, a saber, Nabal, impressão no seu coração, porque tal é ele qual é o seu nome. Nabal é o seu nome, e a loucura está com ele, e eu, tua serva, não vi os moços de meu senhor, que enviaste.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 26, 'Agora, pois, meu senhor, vive o SENHOR, e vive a tua alma, que o SENHOR te impediu de vires com sangue, e de que a tua mão te salvasse; e, agora, tais quais Nabal sejam os teus inimigos e os que procuram mal contra o meu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 27, 'E agora este é o presente que trouxe a tua serva a meu senhor; seja dado aos moços que seguem ao meu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 28, 'Perdoa, pois, à tua serva esta transgressão, porque certamente fará o SENHOR casa firme a meu senhor, porque meu senhor guerreia as guerras do SENHOR, e não se tem achado mal em ti por todos os teus dias,', 2, CURRENT_TIMESTAMP, false),
(9, 25, 29, 'E, levantando-se algum homem para te perseguir, e para procurar a tua morte, contudo a vida de meu senhor será atada no feixe dos que vivem com o SENHOR teu Deus; porém a vida de teus inimigos ele arrojará ao longe, como do meio do côncavo de uma funda.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 30, 'E há de ser que, usando o SENHOR com o meu senhor conforme a todo o bem que já tem falado de ti, e te houver estabelecido príncipe sobre Israel,', 2, CURRENT_TIMESTAMP, false),
(9, 25, 31, 'Então, meu senhor, não te será por tropeço, nem por pesar no coração, o sangue que sem causa derramaste, nem tampouco por ter se vingado o meu senhor a si mesmo; e quando o SENHOR fizer bem a meu senhor, lembra-te então da tua serva.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 32, 'Então Davi disse a Abigail: Bendito o Senhor Deus de Israel, que hoje te enviou ao meu encontro.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 33, 'E bendito o teu conselho, e bendita tu, que hoje me impediste de derramar sangue, e de vingar-me pela minha própria mão.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 34, 'Porque, na verdade, vive o Senhor Deus de Israel, que me impediu de que te fizesse mal, que se tu não te apressaras, e não me vieras ao encontro, não ficaria a Nabal até a luz da manhã nem mesmo um menino.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 35, 'Então Davi tomou da sua mão o que tinha trazido, e lhe disse: Sobe em paz à tua casa; vês aqui que tenho dado ouvidos à tua voz, e tenho aceitado a tua face.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 36, 'E, vindo Abigail a Nabal, eis que tinha em sua casa um banquete, como banquete de rei; e o coração de Nabal estava alegre nele, e ele já muito embriagado, pelo que ela não lhe deu a entender coisa alguma, pequena nem grande, até à luz da manhã.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 37, 'Sucedeu, pois, que pela manhã, estando Nabal já livre do vinho, sua mulher lhe deu a entender aquelas coisas; e se amorteceu o seu coração, e ficou ele como pedra.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 38, 'E aconteceu que, passados quase dez dias, feriu o Senhor a Nabal, e este morreu.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 39, 'E, ouvindo Davi que Nabal morrera, disse: Bendito seja o Senhor, que julgou a causa de minha afronta recebida da mão de Nabal, e deteve a seu servo do mal, fazendo o Senhor tornar o mal de Nabal sobre a sua cabeça. E mandou Davi falar a Abigail, para tomá-la por sua mulher.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 40, 'Vindo, pois, os criados de Davi a Abigail, no Carmelo, lhe falaram, dizendo: Davi nos tem mandado a ti, para te tomar por sua mulher.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 41, 'Então ela se levantou, e se inclinou com o rosto em terra, e disse: Eis que a tua serva servirá de criada para lavar os pés dos criados de meu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 42, 'E Abigail se apressou, e se levantou, e montou num jumento com as suas cinco moças que seguiam as suas pisadas; e ela seguiu os mensageiros de Davi, e foi sua mulher.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 43, 'Também tomou Davi a Ainoã de Jizreel; e ambas foram suas mulheres.', 2, CURRENT_TIMESTAMP, false),
(9, 25, 44, 'Porque Saul tinha dado sua filha Mical, mulher de Davi, a Palti, filho de Laís, o qual era de Galim.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 1, 'E vieram os zifeus a Saul, a Gibeá, dizendo: Não está Davi escondido no outeiro de Haquilá, defronte de Jesimom?', 2, CURRENT_TIMESTAMP, false),
(9, 26, 2, 'Então Saul se levantou e desceu ao deserto de Zife, e com ele três mil homens escolhidos de Israel, a buscar a Davi no deserto de Zife.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 3, 'E acampou-se Saul no outeiro de Haquilá, que está defronte de Jesimom, junto ao caminho; porém Davi ficou no deserto, e viu que Saul vinha seguindo-o no deserto.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 4, 'Pois Davi enviou espias, e soube que Saul tinha vindo.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 5, 'E Davi se levantou, e foi ao lugar onde Saul se tinha acampado; viu Davi o lugar onde se tinha deitado Saul, e Abner, filho de Ner, capitão do seu exército; e Saul estava deitado dentro do lugar dos carros, e o povo estava acampado ao redor dele.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 6, 'E dirigindo-se Davi a Aimeleque, o heteu, e a Abisai, filho de Zeruia, irmão de Joabe, disse: Quem descerá comigo a Saul ao arraial? E respondeu Abisai: Eu descerei contigo.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 7, 'Foram, pois, Davi e Abisai de noite ao povo, e eis que Saul estava deitado dormindo dentro do lugar dos carros, e a sua lança estava fincada na terra à sua cabeceira; e Abner e o povo deitavam-se ao redor dele.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 8, 'Então disse Abisai a Davi: Deus te entregou hoje nas mãos o teu inimigo; deixa-me, pois, agora encravá-lo com a lança de uma vez na terra, e não o ferirei segunda vez.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 9, 'E disse Davi a Abisai: Nenhum dano lhe faças; porque quem estendeu a sua mão contra o ungido do Senhor, e ficou inocente?', 2, CURRENT_TIMESTAMP, false),
(9, 26, 10, 'Disse mais Davi: Vive o Senhor que o Senhor o ferirá, ou o seu dia chegará em que morra, ou descerá para a batalha e perecerá.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 11, 'O Senhor me guarde, de que eu estenda a mão contra o ungido do Senhor; agora, porém, toma a lança que está à sua cabeceira e a bilha de água, e vamo-nos.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 12, 'Tomou, pois, Davi a lança e a bilha de água, da cabeceira de Saul, e foram-se; e ninguém houve que o visse, nem que o advertisse, nem que acordasse; porque todos estavam dormindo, porque da parte do Senhor havia caído sobre eles um profundo sono.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 13, 'E Davi, passando ao outro lado, pôs-se no cume do monte ao longe, de maneira que entre eles havia grande distância.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 14, 'E Davi bradou ao povo, e a Abner, filho de Ner, dizendo: Não responderás, Abner? Então Abner respondeu e disse: Quem és tu, que bradas ao rei?', 2, CURRENT_TIMESTAMP, false),
(9, 26, 15, 'Então disse Davi a Abner: Porventura não és homem? E quem há em Israel como tu? Por que, pois, não guardaste o rei, teu senhor? Porque um do povo veio para destruir o rei, teu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 16, 'Não é bom isso, que fizeste; vive o SENHOR, que sois dignos de morte, vós que não guardastes a vosso senhor, o ungido do SENHOR; vede, pois, agora onde está a lança do rei, e a bilha de água, que tinha à sua cabeceira.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 17, 'Então conheceu Saul a voz de Davi, e disse: Não é esta a tua voz, meu filho Davi? E disse Davi: É minha voz, ó rei meu senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 18, 'Disse mais: Por que persegue o meu senhor tanto o seu servo? Que fiz eu? E que maldade se acha nas minhas mãos?', 2, CURRENT_TIMESTAMP, false),
(9, 26, 19, 'Ouve, pois, agora, te rogo, rei meu senhor, as palavras de teu servo: Se o SENHOR te incita contra mim, receba ele a oferta de alimentos; se, porém, são os filhos dos homens, malditos sejam perante o SENHOR; pois eles me têm expulsado hoje para que eu não tenha parte na herança do SENHOR, dizendo: Vai, serve a outros deuses.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 20, 'Agora, pois, não se derrame o meu sangue na terra diante do Senhor; pois saiu o rei de Israel em busca de uma pulga, como quem persegue uma perdiz nos montes.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 21, 'Então disse Saul: Pequei; volta, meu filho Davi, porque não tornarei a fazer-te mal; porque foi hoje preciosa a minha vida aos teus olhos; eis que procedi loucamente, e errei grandissimamente.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 22, 'Davi então respondeu, e disse: Eis aqui a lança do rei; venha cá um dos moços, e leve-a.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 23, 'O Senhor, porém, pague a cada um a sua justiça e a sua lealdade; pois o Senhor te entregou hoje na minha mão, porém não quis estender a minha mão contra o ungido do Senhor.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 24, 'E eis que, assim como foi a tua vida hoje de tanta estima aos meus olhos, assim seja a minha vida de muita estima aos olhos do Senhor, e ele me livre de toda a tribulação.', 2, CURRENT_TIMESTAMP, false),
(9, 26, 25, 'Então Saul disse a Davi: Bendito sejas tu, meu filho Davi; pois grandes coisas farás e também prevalecerás. Então Davi se foi pelo seu caminho e Saul voltou para o seu lugar.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 1, 'Disse, porém, Davi no seu coração: Ora, algum dia ainda perecerei pela mão de Saul; não há coisa melhor para mim do que escapar apressadamente para a terra dos filisteus, para que Saul perca a esperança de mim, e cesse de me buscar por todos os termos de Israel; e assim escaparei da sua mão.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 2, 'Então Davi se levantou, e passou, com os seiscentos homens que com ele estavam, a Aquis, filho de Maoque, rei de Gate.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 3, 'E Davi ficou com Aquis em Gate, ele e os seus homens, cada um com a sua casa; Davi com ambas as suas mulheres, Ainoã, a jizreelita, e Abigail, a mulher de Nabal, o carmelita.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 4, 'E, sendo Saul avisado que Davi tinha fugido para Gate, não cuidou mais de buscá-lo.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 5, 'E disse Davi a Aquis: Se eu tenho achado graça em teus olhos, dá-me lugar numa das cidades da terra, para que ali habite; pois por que razão habitaria o teu servo contigo na cidade real?', 2, CURRENT_TIMESTAMP, false),
(9, 27, 6, 'Então lhe deu Aquis, naquele dia, a cidade de Ziclague (por isso Ziclague pertence aos reis de Judá, até ao dia de hoje).', 2, CURRENT_TIMESTAMP, false),
(9, 27, 7, 'E foi o número dos dias, que Davi habitou na terra dos filisteus, um ano e quatro meses.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 8, 'E subia Davi com os seus homens, e davam sobre os gesuritas, e os gersitas, e os amalequitas; porque antigamente foram estes os moradores da terra que se estende na direção de Sur, até à terra do Egito.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 9, 'E Davi feria aquela terra, e não dava vida nem a homem nem a mulher, e tomava ovelhas, e vacas, e jumentos, e camelos, e vestes; e voltava, e vinha a Aquis.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 10, 'E dizendo Aquis: Onde atacastes hoje? Davi dizia: Sobre o sul de Judá, e sobre o sul dos jerameelitas, e sobre o sul dos queneus.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 11, 'E Davi não deixava com vida nem a homem nem a mulher, para trazê-los a Gate, dizendo: Para que porventura não nos denunciem, dizendo: Assim Davi o fazia. E este era o seu costume por todos os dias que habitou na terra dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 27, 12, 'E Aquis confiava em Davi, dizendo: Fez-se ele por certo aborrecível para com o seu povo em Israel; por isso me será por servo para sempre.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 1, 'E sucedeu naqueles dias que, juntando os filisteus os seus exércitos à peleja, para fazer guerra contra Israel, disse Aquis a Davi: Sabe de certo que comigo sairás ao arraial, tu e os teus homens.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 2, 'Então disse Davi a Aquis: Assim saberás o que fará o teu servo. E disse Aquis a Davi: Por isso te terei por guarda da minha pessoa para sempre.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 3, 'E Samuel já estava morto, e todo o Israel o tinha chorado, e o tinha sepultado em Ramá, que era a sua cidade; e Saul tinha desterrado os adivinhos e os encantadores.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 4, 'E ajuntaram-se os filisteus, e vieram, e acamparam-se em Suném; e ajuntou Saul a todo o Israel, e se acamparam em Gilboa.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 5, 'E, vendo Saul o arraial dos filisteus, temeu, e estremeceu muito o seu coração.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 6, 'E perguntou Saul ao Senhor, porém o Senhor não lhe respondeu, nem por sonhos, nem por Urim, nem por profetas.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 7, 'Então disse Saul aos seus criados: Buscai-me uma mulher que tenha o espírito de feiticeira, para que vá a ela, e consulte por ela. E os seus criados lhe disseram: Eis que em En-Dor há uma mulher que tem o espírito de adivinhar.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 8, 'E Saul se disfarçou, e vestiu outras roupas, e foi ele com dois homens, e de noite chegaram à mulher; e disse: Peço-te que me adivinhes pelo espírito de feiticeira, e me faças subir a quem eu te disser.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 9, 'Então a mulher lhe disse: Eis aqui tu sabes o que Saul fez, como tem destruído da terra os adivinhos e os encantadores; por que, pois, me armas um laço à minha vida, para me fazeres morrer?', 2, CURRENT_TIMESTAMP, false),
(9, 28, 10, 'Então Saul lhe jurou pelo Senhor, dizendo: Vive o Senhor, que nenhum mal te sobrevirá por isso.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 11, 'A mulher então lhe disse: A quem te farei subir? E disse ele: Faze-me subir a Samuel.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 12, 'Vendo, pois, a mulher a Samuel, gritou com alta voz, e falou a Saul, dizendo: Por que me tens enganado? Pois tu mesmo és Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 13, 'E o rei lhe disse: Não temas; que é que vês? Então a mulher disse a Saul: Vejo deuses que sobem da terra.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 14, 'E lhe disse: Como é a sua figura? E disse ela: Vem subindo um homem ancião, e está envolto numa capa. Entendendo Saul que era Samuel, inclinou-se com o rosto em terra, e se prostrou.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 15, 'Samuel disse a Saul: Por que me inquietaste, fazendo-me subir? Então disse Saul: Mui angustiado estou, porque os filisteus guerreiam contra mim, e Deus se tem desviado de mim, e não me responde mais, nem pelo ministério dos profetas, nem por sonhos; por isso te chamei a ti, para que me faças saber o que hei de fazer.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 16, 'Então disse Samuel: Por que, pois, me perguntas a mim, visto que o Senhor te tem desamparado, e se tem feito teu inimigo?', 2, CURRENT_TIMESTAMP, false),
(9, 28, 17, 'Porque o Senhor tem feito para contigo como pela minha boca te disse, e o Senhor tem rasgado o reino da tua mão, e o tem dado ao teu próximo, a Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 18, 'Como tu não deste ouvidos à voz do Senhor, e não executaste o fervor da sua ira contra Amaleque, por isso o Senhor te fez hoje isto.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 19, 'E o Senhor entregará também a Israel contigo na mão dos filisteus, e amanhã tu e teus filhos estareis comigo; e o arraial de Israel o Senhor entregará na mão dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 20, 'E imediatamente Saul caiu estendido por terra, e grandemente temeu por causa daquelas palavras de Samuel; e não houve força nele; porque não tinha comido pão todo aquele dia e toda aquela noite.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 21, 'Então veio a mulher a Saul e, vendo que estava tão perturbado, disse-lhe: Eis que a tua criada deu ouvidos à tua voz, e pus a minha vida na minha mão, e ouvi as palavras que disseste.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 22, 'Agora, pois, ouve também tu as palavras da tua serva, e porei um bocado de pão diante de ti, e come, para que tenhas forças para te pores a caminho.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 23, 'Porém ele o recusou, e disse: Não comerei. Porém os seus criados e a mulher o constrangeram; e deu ouvidos à sua voz; e levantou-se do chão, e se assentou sobre uma cama.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 24, 'E tinha a mulher em casa um bezerro cevado, e se apressou, e o matou, e tomou farinha, e a amassou, e a cozeu em bolos ázimos.', 2, CURRENT_TIMESTAMP, false),
(9, 28, 25, 'E os trouxe diante de Saul e de seus criados, e comeram; depois levantaram-se e partiram naquela mesma noite.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 1, 'E ajuntaram os filisteus todos os seus exércitos em Afeque; e acamparam-se os israelitas junto à fonte que está em Jizreel.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 2, 'E os príncipes dos filisteus se foram para lá com centenas e com milhares; porém Davi e os seus homens iam com Aquis na retaguarda.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 3, 'Disseram então os príncipes dos filisteus: Que fazem aqui estes hebreus? E disse Aquis aos príncipes dos filisteus: Não é este Davi, o servo de Saul, rei de Israel, que esteve comigo há alguns dias ou anos? Coisa nenhuma achei nele desde o dia em que se revoltou, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 4, 'Porém os príncipes dos filisteus muito se indignaram contra ele; e disseram-lhe os príncipes dos filisteus: Faze voltar este homem, para que torne ao lugar em que tu o puseste, e não desça conosco à batalha, para que não se torne nosso adversário na batalha; pois, com que poderia este agradar a seu Senhor? Porventura não seria com as cabeças destes homens?', 2, CURRENT_TIMESTAMP, false),
(9, 29, 5, 'Não é este aquele Davi, de quem uns aos outros cantaram nas danças, dizendo: Saul feriu os seus milhares, porém Davi os seus dez milhares?', 2, CURRENT_TIMESTAMP, false),
(9, 29, 6, 'Então Aquis chamou a Davi e disse-lhe: Vive o Senhor, que tu és reto, e que a tua entrada e a tua saída comigo no arraial é boa aos meus olhos; porque nenhum mal em ti achei, desde o dia em que a mim vieste, até ao dia de hoje; porém aos olhos dos príncipes não agradas.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 7, 'Volta, pois, agora, e vai em paz; para que não faças mal aos olhos dos príncipes dos filisteus.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 8, 'Então Davi disse a Aquis: Por quê? Que fiz? Ou que achaste no teu servo, desde o dia em que estive diante de ti, até ao dia de hoje, para que não vá e peleje contra os inimigos do rei, meu senhor?', 2, CURRENT_TIMESTAMP, false),
(9, 29, 9, 'Respondeu, porém, Aquis, e disse a Davi: Bem o sei; e que na verdade aos meus olhos és bom como um anjo de Deus; porém disseram os príncipes dos filisteus: Não suba este conosco à batalha.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 10, 'Agora, pois, amanhã de madrugada levanta-te com os servos de teu senhor, que têm vindo contigo; e, levantando-vos pela manhã, de madrugada, e havendo luz, parti.', 2, CURRENT_TIMESTAMP, false),
(9, 29, 11, 'Então Davi de madrugada se levantou, ele e os seus homens, para partirem pela manhã, e voltarem à terra dos filisteus; e os filisteus subiram a Jizreel.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 1, 'Sucedeu, pois, que, chegando Davi e os seus homens ao terceiro dia a Ziclague, já os amalequitas tinham invadido o sul, e Ziclague, e tinham ferido a Ziclague e a tinham queimado a fogo.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 2, 'E tinham levado cativas as mulheres, e todos os que estavam nela, tanto pequenos como grandes; a ninguém, porém, mataram, tão-somente os levaram consigo, e foram o seu caminho.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 3, 'E Davi e os seus homens chegaram à cidade e eis que estava queimada a fogo, e suas mulheres, seus filhos e suas filhas tinham sido levados cativos.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 4, 'Então Davi e o povo que se achava com ele alçaram a sua voz, e choraram, até que neles não houve mais forças para chorar.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 5, 'Também as duas mulheres de Davi foram levadas cativas; Ainoã, a jizreelita, e Abigail, a mulher de Nabal, o carmelita.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 6, 'E Davi muito se angustiou, porque o povo falava de apedrejá-lo, porque a alma de todo o povo estava em amargura, cada um por causa dos seus filhos e das suas filhas; todavia Davi se fortaleceu no Senhor seu Deus.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 7, 'E disse Davi a Abiatar, o sacerdote, filho de Aimeleque: Traze-me, peço-te, aqui o éfode. E Abiatar trouxe o éfode a Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 8, 'Então consultou Davi ao Senhor, dizendo: Perseguirei eu a esta tropa? Alcançá-la-ei? E lhe disse: Persegue-a, porque decerto a alcançarás e tudo libertarás.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 9, 'Partiu, pois, Davi, ele e os seiscentos homens que com ele se achavam, e chegaram ao ribeiro de Besor, onde pararam os que ficaram atrás.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 10, 'E perseguiu-os Davi, ele e os quatrocentos homens, pois que duzentos homens ficaram, por não poderem, de cansados que estavam, passar o ribeiro de Besor.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 11, 'E acharam no campo um homem egípcio, e o trouxeram a Davi; deram-lhe pão, e comeu, e deram-lhe a beber água.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 12, 'Deram-lhe também um pedaço de massa de figos secos e dois cachos de passas, e comeu, e voltou-lhe o seu espírito, porque havia três dias e três noites que não tinha comido pão nem bebido água.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 13, 'Então Davi lhe disse: De quem és tu, e de onde és? E disse o moço egípcio: Sou servo de um homem amalequita, e meu senhor me deixou, porque adoeci há três dias.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 14, 'Nós invadimos o lado do sul dos queretitas, e o lado de Judá, e o lado do sul de Calebe, e pusemos fogo a Ziclague.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 15, 'E disse-lhe Davi: Poderias, descendo, guiar-me a essa tropa? E disse-lhe: Por Deus jura-me que não me matarás, nem me entregarás na mão de meu senhor, e, descendo, te guiarei a essa tropa.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 16, 'E, descendo, o guiou e eis que estavam espalhados sobre a face de toda a terra, comendo, e bebendo, e dançando, por todo aquele grande despojo que tomaram da terra dos filisteus e da terra de Judá.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 17, 'E feriu-os Davi, desde o crepúsculo até à tarde do dia seguinte; nenhum deles escapou, senão só quatrocentos moços que, montados sobre camelos, fugiram.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 18, 'Assim salvou Davi tudo quanto tomaram os amalequitas; também as suas duas mulheres salvou Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 19, 'E ninguém lhes faltou, desde o menor até ao maior, e até os filhos e as filhas; e também desde o despojo até tudo quanto lhes tinham tomado, tudo Davi tornou a trazer.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 20, 'Também tomou Davi todas as ovelhas e vacas, e levavam-nas adiante do outro gado, e diziam: Este é o despojo de Davi.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 21, 'E, chegando Davi aos duzentos homens que, de cansados que estavam, não puderam seguir a Davi, e que deixaram ficar no ribeiro de Besor, estes saíram ao encontro de Davi e do povo que com ele vinha; e, chegando-se Davi com o povo, os saudou em paz.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 22, 'Então todos os maus e perversos, dentre os homens que tinham ido com Davi, responderam, e disseram: Visto que não foram conosco, não lhes daremos do despojo que libertamos; mas que leve cada um sua mulher e seus filhos, e se vá.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 23, 'Porém Davi disse: Não fareis assim, irmãos meus, com o que nos deu o Senhor, que nos guardou, e entregou a tropa que contra nós vinha, nas nossas mãos.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 24, 'E quem vos daria ouvidos nisso? Porque qual é a parte dos que desceram à peleja, tal também será a parte dos que ficaram com a bagagem; igualmente repartirão.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 25, 'O que assim foi desde aquele dia em diante, porquanto o pôs por estatuto e direito em Israel até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(9, 30, 26, 'E, chegando Davi a Ziclague, enviou do despojo aos anciãos de Judá, seus amigos, dizendo: Eis aí para vós uma bênção do despojo dos inimigos do Senhor;', 2, CURRENT_TIMESTAMP, false),
(9, 30, 27, 'Aos de Betel, e aos de Ramote do sul, e aos de Jater,', 2, CURRENT_TIMESTAMP, false),
(9, 30, 28, 'E aos de Aroer, e aos de Sifmote, e aos de Estemoa,', 2, CURRENT_TIMESTAMP, false),
(9, 30, 29, 'E aos de Racal, e aos que estavam nas cidades jerameelitas e nas cidades dos queneus,', 2, CURRENT_TIMESTAMP, false),
(9, 30, 30, 'E aos de Hormá, e aos de Corasã, e aos de Ataca,', 2, CURRENT_TIMESTAMP, false),
(9, 30, 31, 'E aos de Hebrom, e a todos os lugares em que andara Davi, ele e os seus homens.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 1, 'Os filisteus, pois, pelejaram contra Israel; e os homens de Israel fugiram de diante dos filisteus, e caíram mortos na montanha de Gilboa.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 2, 'E os filisteus perseguiram a Saul e a seus filhos; e mataram a Jônatas, e a Abinadabe, e a Malquisua, filhos de Saul.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 3, 'E a peleja se agravou contra Saul, e os flecheiros o alcançaram; e muito temeu por causa dos flecheiros.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 4, 'Então disse Saul ao seu pajem de armas: Arranca a tua espada, e atravessa-me com ela, para que porventura não venham estes incircuncisos, e me atravessem e escarneçam de mim. Porém o seu pajem de armas não quis, porque temia muito; então Saul tomou a espada, e se lançou sobre ela.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 5, 'Vendo, pois, o seu pajem de armas que Saul já era morto, também ele se lançou sobre a sua espada, e morreu com ele.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 6, 'Assim faleceu Saul, e seus três filhos, e o seu pajem de armas, e também todos os seus homens morreram juntamente naquele dia.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 7, 'E, vendo os homens de Israel, que estavam deste lado do vale e deste lado do Jordão, que os homens de Israel fugiram, e que Saul e seus filhos estavam mortos, abandonaram as cidades, e fugiram; e vieram os filisteus, e habitaram nelas.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 8, 'Sucedeu, pois, que, vindo os filisteus no outro dia para despojar os mortos, acharam a Saul e a seus três filhos estirados na montanha de Gilboa.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 9, 'E cortaram-lhe a cabeça, e o despojaram das suas armas, e enviaram pela terra dos filisteus, em redor, a anunciá-lo no templo dos seus ídolos e entre o povo.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 10, 'E puseram as suas armas no templo de Astarote, e o seu corpo o afixaram no muro de Bete-Sã.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 11, 'Ouvindo então os moradores de Jabes-Gileade, o que os filisteus fizeram a Saul,', 2, CURRENT_TIMESTAMP, false),
(9, 31, 12, 'Todo o homem valoroso se levantou, e caminharam toda a noite, e tiraram o corpo de Saul e os corpos de seus filhos do muro, de Bete-Sã, e, vindo a Jabes, os queimaram.', 2, CURRENT_TIMESTAMP, false),
(9, 31, 13, 'E tomaram os seus ossos, e os sepultaram debaixo de um arvoredo, em Jabes, e jejuaram sete dias.', 2, CURRENT_TIMESTAMP, false),
(52, 1, 1, 'Paulo, e Silvano, e Timóteo, à igreja dos tessalonicenses em Deus, o Pai, e no Senhor Jesus Cristo: Graça e paz tenhais de Deus nosso Pai e do Senhor Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(52, 1, 2, 'Sempre damos graças a Deus por vós todos, fazendo menção de vós em nossas orações,', 2, CURRENT_TIMESTAMP, false),
(52, 1, 3, 'Lembrando-nos sem cessar da obra da vossa fé, do trabalho do amor, e da paciência da esperança em nosso Senhor Jesus Cristo, diante de nosso Deus e Pai,', 2, CURRENT_TIMESTAMP, false),
(52, 1, 4, 'Sabendo, amados irmãos, que a vossa eleição é de Deus;', 2, CURRENT_TIMESTAMP, false),
(52, 1, 5, 'Porque o nosso evangelho não foi a vós somente em palavras, mas também em poder, e no Espírito Santo, e em muita certeza, como bem sabeis quais fomos entre vós, por amor de vós.', 2, CURRENT_TIMESTAMP, false),
(52, 1, 6, 'E vós fostes feitos nossos imitadores, e do Senhor, recebendo a palavra em muita tribulação, com gozo do Espírito Santo.', 2, CURRENT_TIMESTAMP, false),
(52, 1, 7, 'De maneira que fostes exemplo para todos os fiéis na macedônia e Acaia.', 2, CURRENT_TIMESTAMP, false),
(52, 1, 8, 'Porque por vós soou a palavra do Senhor, não somente na macedônia e Acaia, mas também em todos os lugares a vossa fé para com Deus se espalhou, de tal maneira que já dela não temos necessidade de falar coisa alguma;', 2, CURRENT_TIMESTAMP, false),
(52, 1, 9, 'Porque eles mesmos anunciam de nós qual a entrada que tivemos para convosco, e como dos ídolos vos convertestes a Deus, para servir o Deus vivo e verdadeiro,', 2, CURRENT_TIMESTAMP, false),
(52, 1, 10, 'E esperar dos céus o seu Filho, a quem ressuscitou dentre os mortos, a saber, Jesus, que nos livra da ira futura.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 1, 'Porque vós mesmos, irmãos, bem sabeis que a nossa entrada para convosco não foi vã;', 2, CURRENT_TIMESTAMP, false),
(52, 2, 2, 'Mas, mesmo depois de termos antes padecido, e sido agravados em Filipos, como sabeis, tornamo-nos ousados em nosso Deus, para vos falar o evangelho de Deus com grande combate.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 3, 'Porque a nossa exortação não foi com engano, nem com imundícia, nem com fraudulência;', 2, CURRENT_TIMESTAMP, false),
(52, 2, 4, 'Mas, como fomos aprovados de Deus para que o evangelho nos fosse confiado, assim falamos, não como para agradar aos homens, mas a Deus, que prova os nossos corações.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 5, 'Porque, como bem sabeis, nunca usamos de palavras lisonjeiras, nem houve um pretexto de avareza; Deus é testemunha;', 2, CURRENT_TIMESTAMP, false),
(52, 2, 6, 'E não buscamos glória dos homens, nem de vós, nem de outros, ainda que podíamos, como apóstolos de Cristo, ser-vos pesados;', 2, CURRENT_TIMESTAMP, false),
(52, 2, 7, 'Antes fomos brandos entre vós, como a ama que cria seus filhos.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 8, 'Assim nós, sendo-vos tão afeiçoados, de boa vontade quiséramos comunicar-vos, não somente o evangelho de Deus, mas ainda as nossas próprias almas; porquanto nos éreis muito queridos.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 9, 'Porque bem vos lembrais, irmãos, do nosso trabalho e fadiga; pois, trabalhando noite e dia, para não sermos pesados a nenhum de vós, vos pregamos o evangelho de Deus.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 10, 'Vós e Deus sois testemunhas de quão santa, e justa, e irrepreensivelmente nos houvemos para convosco, os que crestes.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 11, 'Assim como bem sabeis de que modo vos exortávamos e consolávamos e testemunhávamos, a cada um de vós, como o pai a seus filhos;', 2, CURRENT_TIMESTAMP, false),
(52, 2, 12, 'Para que vos conduzísseis dignamente para com Deus, que vos chama para o seu reino e glória.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 13, 'Por isso também damos, sem cessar, graças a Deus, pois, havendo recebido de nós a palavra da pregação de Deus, a recebestes, não como palavra de homens, mas (segundo é, na verdade), como palavra de Deus, a qual também opera em vós, os que crestes.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 14, 'Porque vós, irmãos, haveis sido feitos imitadores das igrejas de Deus que na Judéia estão em Jesus Cristo; porquanto também padecestes de vossos próprios concidadãos o mesmo que os judeus lhes fizeram a eles,', 2, CURRENT_TIMESTAMP, false),
(52, 2, 15, 'Os quais também mataram o Senhor Jesus e os seus próprios profetas, e nos têm perseguido; e não agradam a Deus, e são contrários a todos os homens,', 2, CURRENT_TIMESTAMP, false),
(52, 2, 16, 'E nos impedem de pregar aos gentios as palavras da salvação, a fim de encherem sempre a medida de seus pecados; mas a ira de Deus caiu sobre eles até ao fim.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 17, 'Nós, porém, irmãos, sendo privados de vós por um momento de tempo, de vista, mas não do coração, tanto mais procuramos com grande desejo ver o vosso rosto;', 2, CURRENT_TIMESTAMP, false),
(52, 2, 18, 'Por isso bem quisemos uma e outra vez ir ter convosco, pelo menos eu, Paulo, mas Satanás no-lo impediu.', 2, CURRENT_TIMESTAMP, false),
(52, 2, 19, 'Porque, qual é a nossa esperança, ou gozo, ou coroa de glória? Porventura não o sois vós também diante de nosso Senhor Jesus Cristo em sua vinda?', 2, CURRENT_TIMESTAMP, false),
(52, 2, 20, 'Na verdade vós sois a nossa glória e gozo.', 2, CURRENT_TIMESTAMP, false),
(52, 3, 1, 'Por isso, não podendo esperar mais, achamos por bem ficar sozinhos em Atenas;', 2, CURRENT_TIMESTAMP, false),
(52, 3, 2, 'E enviamos Timóteo, nosso irmão, e ministro de Deus, e nosso cooperador no evangelho de Cristo, para vos confortar e vos exortar acerca da vossa fé;', 2, CURRENT_TIMESTAMP, false),
(52, 3, 3, 'Para que ninguém se comova por estas tribulações; porque vós mesmos sabeis que para isto fomos ordenados,', 2, CURRENT_TIMESTAMP, false),
(52, 3, 4, 'Pois, estando ainda convosco, vos predizíamos que havíamos de ser afligidos, como sucedeu, e vós o sabeis.', 2, CURRENT_TIMESTAMP, false),
(52, 3, 5, 'Portanto, não podendo eu também esperar mais, mandei-o saber da vossa fé, temendo que o tentador vos tentasse, e o nosso trabalho viesse a ser inútil.', 2, CURRENT_TIMESTAMP, false),
(52, 3, 6, 'Vindo, porém, agora Timóteo de vós para nós, e trazendo-nos boas novas da vossa fé e amor, e de como sempre tendes boa lembrança de nós, desejando muito ver-nos, como nós também a vós;', 2, CURRENT_TIMESTAMP, false),
(52, 3, 7, 'Por esta razão, irmãos, ficamos consolados acerca de vós, em toda a nossa aflição e necessidade, pela vossa fé,', 2, CURRENT_TIMESTAMP, false),
(52, 3, 8, 'Porque agora vivemos, se estais firmes no Senhor.', 2, CURRENT_TIMESTAMP, false),
(52, 3, 9, 'Porque, que ação de graças poderemos dar a Deus por vós, por todo o gozo com que nos regozijamos por vossa causa diante do nosso Deus,', 2, CURRENT_TIMESTAMP, false),
(52, 3, 10, 'Orando abundantemente dia e noite, para que possamos ver o vosso rosto, e supramos o que falta à vossa fé?', 2, CURRENT_TIMESTAMP, false),
(52, 3, 11, 'Ora, o mesmo nosso Deus e Pai, e nosso Senhor Jesus Cristo, encaminhem a nossa viagem para vós.', 2, CURRENT_TIMESTAMP, false),
(52, 3, 12, 'E o Senhor vos aumente, e faça crescer em amor uns para com os outros, e para com todos, como também o fazemos para convosco;', 2, CURRENT_TIMESTAMP, false),
(52, 3, 13, 'Para confirmar os vossos corações, para que sejais irrepreensíveis em santidade diante de nosso Deus e Pai, na vinda de nosso Senhor Jesus Cristo com todos os seus santos.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 1, 'Finalmente, irmãos, vos rogamos e exortamos no Senhor Jesus, que assim como recebestes de nós, de que maneira convém andar e agradar a Deus, assim andai, para que possais progredir cada vez mais.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 2, 'Porque vós bem sabeis que mandamentos vos temos dado pelo Senhor Jesus.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 3, 'Porque esta é a vontade de Deus, a vossa santificação; que vos abstenhais da fornicação;', 2, CURRENT_TIMESTAMP, false),
(52, 4, 4, 'Que cada um de vós saiba possuir o seu vaso em santificação e honra;', 2, CURRENT_TIMESTAMP, false),
(52, 4, 5, 'Não na paixão da concupiscência, como os gentios, que não conhecem a Deus.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 6, 'Ninguém oprima ou engane a seu irmão em negócio algum, porque o Senhor é vingador de todas estas coisas, como também antes vo-lo dissemos e testificamos.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 7, 'Porque não nos chamou Deus para a imundícia, mas para a santificação.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 8, 'Portanto, quem despreza isto não despreza ao homem, mas sim a Deus, que nos deu também o seu Espírito Santo.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 9, 'Quanto, porém, ao amor fraternal, não necessitais de que vos escreva, visto que vós mesmos estais instruídos por Deus que vos ameis uns aos outros;', 2, CURRENT_TIMESTAMP, false),
(52, 4, 10, 'Porque também já assim o fazeis para com todos os irmãos que estão por toda a macedônia. Exortamo-vos, porém, a que ainda nisto aumenteis cada vez mais.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 11, 'E procureis viver quietos, e tratar dos vossos próprios negócios, e trabalhar com vossas próprias mãos, como já vo-lo temos mandado;', 2, CURRENT_TIMESTAMP, false),
(52, 4, 12, 'Para que andeis honestamente para com os que estão de fora, e não necessiteis de coisa alguma.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 13, 'Não quero, porém, irmãos, que sejais ignorantes acerca dos que já dormem, para que não vos entristeçais, como os demais, que não têm esperança.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 14, 'Porque, se cremos que Jesus morreu e ressuscitou, assim também aos que em Jesus dormem, Deus os tornará a trazer com ele.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 15, 'Dizemo-vos, pois, isto, pela palavra do Senhor: que nós, os que ficarmos vivos para a vinda do Senhor, não precederemos os que dormem.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 16, 'Porque o mesmo Senhor descerá do céu com alarido, e com voz de arcanjo, e com a trombeta de Deus; e os que morreram em Cristo ressuscitarão primeiro.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 17, 'Depois nós, os que ficarmos vivos, seremos arrebatados juntamente com eles nas nuvens, a encontrar o Senhor nos ares, e assim estaremos sempre com o Senhor.', 2, CURRENT_TIMESTAMP, false),
(52, 4, 18, 'Portanto, consolai-vos uns aos outros com estas palavras.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 1, 'Mas, irmãos, acerca dos tempos e das estações, não necessitais de que se vos escreva;', 2, CURRENT_TIMESTAMP, false),
(52, 5, 2, 'Porque vós mesmos sabeis muito bem que o dia do Senhor virá como o ladrão de noite;', 2, CURRENT_TIMESTAMP, false),
(52, 5, 3, 'Pois que, quando disserem: Há paz e segurança, então lhes sobrevirá repentina destruição, como as dores de parto àquela que está grávida, e de modo nenhum escaparão.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 4, 'Mas vós, irmãos, já não estais em trevas, para que aquele dia vos surpreenda como um ladrão;', 2, CURRENT_TIMESTAMP, false),
(52, 5, 5, 'Porque todos vós sois filhos da luz e filhos do dia; nós não somos da noite nem das trevas.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 6, 'Não durmamos, pois, como os demais, mas vigiemos, e sejamos sóbrios;', 2, CURRENT_TIMESTAMP, false),
(52, 5, 7, 'Porque os que dormem, dormem de noite, e os que se embebedam, embebedam-se de noite.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 8, 'Mas nós, que somos do dia, sejamos sóbrios, vestindo-nos da couraça da fé e do amor, e tendo por capacete a esperança da salvação;', 2, CURRENT_TIMESTAMP, false),
(52, 5, 9, 'Porque Deus não nos destinou para a ira, mas para a aquisição da salvação, por nosso Senhor Jesus Cristo,', 2, CURRENT_TIMESTAMP, false),
(52, 5, 10, 'Que morreu por nós, para que, quer vigiemos, quer durmamos, vivamos juntamente com ele.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 11, 'Por isso exortai-vos uns aos outros, e edificai-vos uns aos outros, como também o fazeis.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 12, 'E rogamo-vos, irmãos, que reconheçais os que trabalham entre vós e que presidem sobre vós no Senhor, e vos admoestam;', 2, CURRENT_TIMESTAMP, false),
(52, 5, 13, 'E que os tenhais em grande estima e amor, por causa da sua obra. Tende paz entre vós.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 14, 'Rogamo-vos, também, irmãos, que admoesteis os desordeiros, consoleis os de pouco ânimo, sustenteis os fracos, e sejais pacientes para com todos.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 15, 'Vede que ninguém dê a outrem mal por mal, mas segui sempre o bem, tanto uns para com os outros, como para com todos.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 16, 'Regozijai-vos sempre.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 17, 'Orai sem cessar.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 18, 'Em tudo dai graças, porque esta é a vontade de Deus em Cristo Jesus para convosco.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 19, 'Não extingais o Espírito.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 20, 'Não desprezeis as profecias.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 21, 'Examinai tudo. Retende o bem.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 22, 'Abstende-vos de toda a aparência do mal.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 23, 'E o mesmo Deus de paz vos santifique em tudo; e todo o vosso espírito, e alma, e corpo, sejam plenamente conservados irrepreensíveis para a vinda de nosso Senhor Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 24, 'Fiel é o que vos chama, o qual também o fará.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 25, 'Irmãos, orai por nós.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 26, 'Saudai a todos os irmãos com ósculo santo.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 27, 'Pelo Senhor vos conjuro que esta epístola seja lida a todos os santos irmãos.', 2, CURRENT_TIMESTAMP, false),
(52, 5, 28, 'A graça de nosso Senhor Jesus Cristo seja convosco. Amém.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 1, 'Paulo, apóstolo de Jesus Cristo, segundo o mandado de Deus, nosso Salvador, e do Senhor Jesus Cristo, esperança nossa,', 2, CURRENT_TIMESTAMP, false),
(54, 1, 2, 'A Timóteo meu verdadeiro filho na fé: Graça, misericórdia e paz da parte de Deus nosso Pai, e da de Cristo Jesus, nosso Senhor.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 3, 'Como te roguei, quando parti para a macedônia, que ficasses em Éfeso, para advertires a alguns, que não ensinem outra doutrina,', 2, CURRENT_TIMESTAMP, false),
(54, 1, 4, 'Nem se dêem a fábulas ou a genealogias intermináveis, que mais produzem questões do que edificação de Deus, que consiste na fé; assim o faço agora.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 5, 'Ora, o fim do mandamento é o amor de um coração puro, e de uma boa consciência, e de uma fé não fingida.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 6, 'Do que, desviando-se alguns, se entregaram a vãs contendas;', 2, CURRENT_TIMESTAMP, false),
(54, 1, 7, 'Querendo ser mestres da lei, e não entendendo nem o que dizem nem o que afirmam.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 8, 'Sabemos, porém, que a lei é boa, se alguém dela usa legitimamente;', 2, CURRENT_TIMESTAMP, false),
(54, 1, 9, 'Sabendo isto, que a lei não é feita para o justo, mas para os injustos e obstinados, para os ímpios e pecadores, para os profanos e irreligiosos, para os parricidas e matricidas, para os homicidas,', 2, CURRENT_TIMESTAMP, false),
(54, 1, 10, 'Para os devassos, para os sodomitas, para os roubadores de homens, para os mentirosos, para os perjuros, e para o que for contrário à sã doutrina,', 2, CURRENT_TIMESTAMP, false),
(54, 1, 11, 'Conforme o evangelho da glória de Deus bem-aventurado, que me foi confiado.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 12, 'E dou graças ao que me tem confortado, a Cristo Jesus Senhor nosso, porque me teve por fiel, pondo-me no ministério;', 2, CURRENT_TIMESTAMP, false),
(54, 1, 13, 'A mim, que dantes fui blasfemo, e perseguidor, e injurioso; mas alcancei misericórdia, porque o fiz ignorantemente, na incredulidade.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 14, 'E a graça de nosso Senhor superabundou com a fé e amor que há em Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 15, 'Esta é uma palavra fiel, e digna de toda a aceitação, que Cristo Jesus veio ao mundo, para salvar os pecadores, dos quais eu sou o principal.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 16, 'Mas por isso alcancei misericórdia, para que em mim, que sou o principal, Jesus Cristo mostrasse toda a sua longanimidade, para exemplo dos que haviam de crer nele para a vida eterna.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 17, 'Ora, ao Rei dos séculos, imortal, invisível, ao único Deus sábio, seja honra e glória para todo o sempre. Amém.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 18, 'Este mandamento te dou, meu filho Timóteo, que, segundo as profecias que houve acerca de ti, milites por elas boa milícia;', 2, CURRENT_TIMESTAMP, false),
(54, 1, 19, 'Conservando a fé, e a boa consciência, a qual alguns, rejeitando, fizeram naufrágio na fé.', 2, CURRENT_TIMESTAMP, false),
(54, 1, 20, 'E entre esses foram Himeneu e Alexandre, os quais entreguei a Satanás, para que aprendam a não blasfemar.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 1, 'Admoesto-te, pois, antes de tudo, que se façam deprecações, orações, intercessões, e ações de graças, por todos os homens;', 2, CURRENT_TIMESTAMP, false),
(54, 2, 2, 'Pelos reis, e por todos os que estão em eminência, para que tenhamos uma vida quieta e sossegada, em toda a piedade e honestidade;', 2, CURRENT_TIMESTAMP, false),
(54, 2, 3, 'Porque isto é bom e agradável diante de Deus nosso Salvador,', 2, CURRENT_TIMESTAMP, false),
(54, 2, 4, 'Que quer que todos os homens se salvem, e venham ao conhecimento da verdade.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 5, 'Porque há um só Deus, e um só Mediador entre Deus e os homens, Jesus Cristo homem.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 6, 'O qual se deu a si mesmo em preço de redenção por todos, para servir de testemunho a seu tempo.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 7, 'Para o que (digo a verdade em Cristo, não minto) fui constituído pregador, e apóstolo, e doutor dos gentios na fé e na verdade.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 8, 'Quero, pois, que os homens orem em todo o lugar, levantando mãos santas, sem ira nem contenda.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 9, 'Que do mesmo modo as mulheres se ataviem em traje honesto, com pudor e modéstia, não com tranças, ou com ouro, ou pérolas, ou vestidos preciosos,', 2, CURRENT_TIMESTAMP, false),
(54, 2, 10, 'Mas (como convém a mulheres que fazem profissão de servir a Deus) com boas obras.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 11, 'A mulher aprenda em silêncio, com toda a sujeição.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 12, 'Não permito, porém, que a mulher ensine, nem use de autoridade sobre o marido, mas que esteja em silêncio.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 13, 'Porque primeiro foi formado Adão, depois Eva.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 14, 'E Adão não foi enganado, mas a mulher, sendo enganada, caiu em transgressão.', 2, CURRENT_TIMESTAMP, false),
(54, 2, 15, 'Salvar-se-á, porém, dando à luz filhos, se permanecer com modéstia na fé, no amor e na santificação.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 1, 'Esta é uma palavra fiel: se alguém deseja o episcopado, excelente obra deseja.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 2, 'Convém, pois, que o bispo seja irrepreensível, marido de uma mulher, vigilante, sóbrio, honesto, hospitaleiro, apto para ensinar;', 2, CURRENT_TIMESTAMP, false),
(54, 3, 3, 'Não dado ao vinho, não espancador, não cobiçoso de torpe ganância, mas moderado, não contencioso, não avarento;', 2, CURRENT_TIMESTAMP, false),
(54, 3, 4, 'Que governe bem a sua própria casa, tendo seus filhos em sujeição, com toda a modéstia', 2, CURRENT_TIMESTAMP, false),
(54, 3, 5, '(Porque, se alguém não sabe governar a sua própria casa, terá cuidado da igreja de Deus? );', 2, CURRENT_TIMESTAMP, false),
(54, 3, 6, 'Não neófito, para que, ensoberbecendo-se, não caia na condenação do diabo.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 7, 'Convém também que tenha bom testemunho dos que estão de fora, para que não caia em afronta, e no laço do diabo.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 8, 'Da mesma sorte os diáconos sejam honestos, não de língua dobre, não dados a muito vinho, não cobiçosos de torpe ganância;', 2, CURRENT_TIMESTAMP, false),
(54, 3, 9, 'Guardando o mistério da fé numa consciência pura.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 10, 'E também estes sejam primeiro provados, depois sirvam, se forem irrepreensíveis.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 11, 'Da mesma sorte as esposas sejam honestas, não maldizentes, sóbrias e fiéis em tudo.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 12, 'Os diáconos sejam maridos de uma só mulher, e governem bem a seus filhos e suas próprias casas.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 13, 'Porque os que servirem bem como diáconos, adquirirão para si uma boa posição e muita confiança na fé que há em Cristo Jesus.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 14, 'Escrevo-te estas coisas, esperando ir ver-te bem depressa;', 2, CURRENT_TIMESTAMP, false),
(54, 3, 15, 'Mas, se tardar, para que saibas como convém andar na casa de Deus, que é a igreja do Deus vivo, a coluna e firmeza da verdade.', 2, CURRENT_TIMESTAMP, false),
(54, 3, 16, 'E, sem dúvida alguma, grande é o mistério da piedade: Deus se manifestou em carne, foi justificado no Espírito, visto dos anjos, pregado aos gentios, crido no mundo, recebido acima na glória.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 1, 'Mas o Espírito expressamente diz que nos últimos tempos apostatarão alguns da fé, dando ouvidos a espíritos enganadores, e a doutrinas de demônios;', 2, CURRENT_TIMESTAMP, false),
(54, 4, 2, 'Pela hipocrisia de homens que falam mentiras, tendo cauterizada a sua própria consciência;', 2, CURRENT_TIMESTAMP, false),
(54, 4, 3, 'Proibindo o casamento, e ordenando a abstinência dos alimentos que Deus criou para os fiéis, e para os que conhecem a verdade, a fim de usarem deles com ações de graças;', 2, CURRENT_TIMESTAMP, false),
(54, 4, 4, 'Porque toda a criatura de Deus é boa, e não há nada que rejeitar, sendo recebido com ações de graças.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 5, 'Porque pela palavra de Deus e pela oração é santificada.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 6, 'Propondo estas coisas aos irmãos, serás bom ministro de Jesus Cristo, criado com as palavras da fé e da boa doutrina que tens seguido.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 7, 'Mas rejeita as fábulas profanas e de velhas, e exercita-te a ti mesmo em piedade;', 2, CURRENT_TIMESTAMP, false),
(54, 4, 8, 'Porque o exercício corporal para pouco aproveita, mas a piedade para tudo é proveitosa, tendo a promessa da vida presente e da que há de vir.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 9, 'Esta palavra é fiel e digna de toda a aceitação;', 2, CURRENT_TIMESTAMP, false),
(54, 4, 10, 'Porque para isto trabalhamos e somos injuriados, pois esperamos no Deus vivo, que é o Salvador de todos os homens, principalmente dos fiéis.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 11, 'Manda estas coisas e ensina-as.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 12, 'Ninguém despreze a tua mocidade; mas sê o exemplo dos fiéis, na palavra, no trato, no amor, no espírito, na fé, na pureza.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 13, 'Persiste em ler, exortar e ensinar, até que eu vá.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 14, 'Não desprezes o dom que há em ti, o qual te foi dado por profecia, com a imposição das mãos do presbitério.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 15, 'Medita estas coisas; ocupa-te nelas, para que o teu aproveitamento seja manifesto a todos.', 2, CURRENT_TIMESTAMP, false),
(54, 4, 16, 'Tem cuidado de ti mesmo e da doutrina. Persevera nestas coisas; porque, fazendo isto, te salvarás, tanto a ti mesmo como aos que te ouvem.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 1, 'NÃO repreendas asperamente o ancião, mas admoesta-o como a pai; aos moços como a irmãos;', 2, CURRENT_TIMESTAMP, false),
(54, 5, 2, 'As mulheres idosas, como a mães, às moças, como a irmãs, em toda a pureza.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 3, 'Honra as viúvas que verdadeiramente são viúvas.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 4, 'Mas, se alguma viúva tiver filhos, ou netos, aprendam primeiro a exercer piedade para com a sua própria família, e a recompensar seus pais; porque isto é bom e agradável diante de Deus.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 5, 'Ora, a que é verdadeiramente viúva e desamparada espera em Deus, e persevera de noite e de dia em rogos e orações;', 2, CURRENT_TIMESTAMP, false),
(54, 5, 6, 'Mas a que vive em deleites, vivendo está morta.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 7, 'Manda, pois, estas coisas, para que elas sejam irrepreensíveis.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 8, 'Mas, se alguém não tem cuidado dos seus, e principalmente dos da sua família, negou a fé, e é pior do que o infiel.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 9, 'Nunca seja inscrita viúva com menos de sessenta anos, e só a que tenha sido mulher de um só marido;', 2, CURRENT_TIMESTAMP, false),
(54, 5, 10, 'Tendo testemunho de boas obras: Se criou os filhos, se exercitou hospitalidade, se lavou os pés aos santos, se socorreu os aflitos, se praticou toda a boa obra.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 11, 'Mas não admitas as viúvas mais novas, porque, quando se tornam levianas contra Cristo, querem casar-se;', 2, CURRENT_TIMESTAMP, false),
(54, 5, 12, 'Tendo já a sua condenação por haverem aniquilado a primeira fé.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 13, 'E, além disto, aprendem também a andar ociosas de casa em casa; e não só ociosas, mas também paroleiras e curiosas, falando o que não convém.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 14, 'Quero, pois, que as que são moças se casem, gerem filhos, governem a casa, e não dêem ocasião ao adversário de maldizer;', 2, CURRENT_TIMESTAMP, false),
(54, 5, 15, 'Porque já algumas se desviaram, indo após Satanás.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 16, 'Se algum crente ou alguma crente tem viúvas, socorra-as, e não se sobrecarregue a igreja, para que se possam sustentar as que deveras são viúvas.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 17, 'Os presbíteros que governam bem sejam estimados por dignos de duplicada honra, principalmente os que trabalham na palavra e na doutrina;', 2, CURRENT_TIMESTAMP, false),
(54, 5, 18, 'Porque diz a Escritura: Não ligarás a boca ao boi que debulha. E: Digno é o obreiro do seu salário.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 19, 'Não aceites acusação contra o presbítero, senão com duas ou três testemunhas.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 20, 'Aos que pecarem, repreende-os na presença de todos, para que também os outros tenham temor.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 21, 'Conjuro-te diante de Deus, e do Senhor Jesus Cristo, e dos anjos eleitos, que sem prevenção guardes estas coisas, nada fazendo por parcialidade.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 22, 'A ninguém imponhas precipitadamente as mãos, nem participes dos pecados alheios; conserva-te a ti mesmo puro.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 23, 'Não bebas mais água só, mas usa de um pouco de vinho, por causa do teu estômago e das tuas freqüentes enfermidades.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 24, 'Os pecados de alguns homens são manifestos, precedendo o juízo; e em alguns manifestam-se depois.', 2, CURRENT_TIMESTAMP, false),
(54, 5, 25, 'Assim mesmo também as boas obras são manifestas, e as que são de outra maneira não podem ocultar-se.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 1, 'Todos os servos que estão debaixo do jugo estimem a seus senhores por dignos de toda a honra, para que o nome de Deus e a doutrina não sejam blasfemados.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 2, 'E os que têm senhores crentes não os desprezem, por serem irmãos; antes os sirvam melhor, porque eles, que participam do benefício, são crentes e amados. Isto ensina e exorta.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 3, 'Se alguém ensina alguma outra doutrina, e se não conforma com as sãs palavras de nosso Senhor Jesus Cristo, e com a doutrina que é segundo a piedade,', 2, CURRENT_TIMESTAMP, false),
(54, 6, 4, 'É soberbo, e nada sabe, mas delira acerca de questões e contendas de palavras, das quais nascem invejas, porfias, blasfêmias, ruins suspeitas,', 2, CURRENT_TIMESTAMP, false),
(54, 6, 5, 'Perversas contendas de homens corruptos de entendimento, e privados da verdade, cuidando que a piedade seja causa de ganho; aparta-te dos tais.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 6, 'Mas é grande ganho a piedade com contentamento.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 7, 'Porque nada trouxemos para este mundo, e manifesto é que nada podemos levar dele.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 8, 'Tendo, porém, sustento, e com que nos cobrirmos, estejamos com isso contentes.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 9, 'Mas os que querem ser ricos caem em tentação, e em laço, e em muitas concupiscências loucas e nocivas, que submergem os homens na perdição e ruína.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 10, 'Porque o amor ao dinheiro é a raiz de toda a espécie de males; e nessa cobiça alguns se desviaram da fé, e se traspassaram a si mesmos com muitas dores.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 11, 'Mas tu, ó homem de Deus, foge destas coisas, e segue a justiça, a piedade, a fé, o amor, a paciência, a mansidão.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 12, 'Milita a boa milícia da fé, toma posse da vida eterna, para a qual também foste chamado, tendo já feito boa confissão diante de muitas testemunhas.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 13, 'Mando-te diante de Deus, que todas as coisas vivifica, e de Cristo Jesus, que diante de Pôncio Pilatos deu o testemunho de boa confissão,', 2, CURRENT_TIMESTAMP, false),
(54, 6, 14, 'Que guardes este mandamento sem mácula e repreensão, até à aparição de nosso Senhor Jesus Cristo;', 2, CURRENT_TIMESTAMP, false),
(54, 6, 15, 'A qual a seu tempo mostrará o bem-aventurado, e único poderoso Senhor, Rei dos reis e Senhor dos senhores;', 2, CURRENT_TIMESTAMP, false),
(54, 6, 16, 'Aquele que tem, ele só, a imortalidade, e habita na luz inacessível; a quem nenhum dos homens viu nem pode ver, ao qual seja honra e poder sempiterno. Amém.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 17, 'Manda aos ricos deste mundo que não sejam altivos, nem ponham a esperança na incerteza das riquezas, mas em Deus, que abundantemente nos dá todas as coisas para delas gozarmos;', 2, CURRENT_TIMESTAMP, false),
(54, 6, 18, 'Que façam bem, enriqueçam em boas obras, repartam de boa mente, e sejam comunicáveis;', 2, CURRENT_TIMESTAMP, false),
(54, 6, 19, 'Que entesourem para si mesmos um bom fundamento para o futuro, para que possam se apoderar da vida eterna.', 2, CURRENT_TIMESTAMP, false),
(54, 6, 20, 'Ó Timóteo, guarda o depósito que te foi confiado, tendo horror aos clamores vãos e profanos e às oposições da falsamente chamada ciência,', 2, CURRENT_TIMESTAMP, false),
(54, 6, 21, 'A qual professando-a alguns, se desviaram da fé. A graça seja contigo. Amém.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 1, 'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, e o irmão Timóteo, à igreja de Deus, que está em Corinto, com todos os santos que estão em toda a Acaia.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 2, 'Graça a vós e paz da parte de Deus nosso Pai, e da do Senhor Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai das misericórdias e o Deus de toda a consolação;', 2, CURRENT_TIMESTAMP, false),
(47, 1, 4, 'Que nos consola em toda a nossa tribulação, para que também possamos consolar os que estiverem em alguma tribulação, com a consolação com que nós mesmos somos consolados por Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 5, 'Porque, como as aflições de Cristo são abundantes em nós, assim também é abundante a nossa consolação por meio de Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 6, 'Mas, se somos atribulados, é para vossa consolação e salvação; ou, se somos consolados, para vossa consolação é, a qual se opera suportando com paciência as mesmas aflições que nós também padecemos;', 2, CURRENT_TIMESTAMP, false),
(47, 1, 7, 'E a nossa esperança acerca de vós é firme, sabendo que, como sois participantes das aflições, assim o sereis também da consolação.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 8, 'Porque não queremos, irmãos, que ignoreis a tribulação que nos sobreveio na Ásia, pois que fomos sobremaneira agravados mais do que podíamos suportar, de modo tal que até da vida desesperamos.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 9, 'Mas já em nós mesmos tínha- mos a sentença de morte, para que não confiássemos em nós, mas em Deus, que ressuscita os mortos;', 2, CURRENT_TIMESTAMP, false),
(47, 1, 10, 'O qual nos livrou de tão grande morte, e livra; em quem esperamos que também nos livrará ainda,', 2, CURRENT_TIMESTAMP, false),
(47, 1, 11, 'Ajudando-nos também vós com orações por nós, para que pela mercê, que por muitas pessoas nos foi feita, por muitas também sejam dadas graças a nosso respeito.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 12, 'Porque a nossa glória é esta: o testemunho da nossa consciência, de que com simplicidade e sinceridade de Deus, não com sabedoria carnal, mas na graça de Deus, temos vivido no mundo, e de modo particular convosco.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 13, 'Porque nenhumas outras coisas vos escrevemos, senão as que já sabeis ou também reconheceis; e espero que também até ao fim as reconhecereis.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 14, 'Como também já em parte reconhecestes em nós, que somos a vossa glória, como também vós sereis a nossa no dia do Senhor Jesus.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 15, 'E com esta confiança quis primeiro ir ter convosco, para que tivésseis uma segunda graça;', 2, CURRENT_TIMESTAMP, false),
(47, 1, 16, 'E por vós passar à macedônia, e da macedônia ir outra vez ter convosco, e ser guiado por vós à Judéia.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 17, 'E, deliberando isto, usei porventura de leviandade? Ou o que delibero, o delibero segundo a carne, para que haja em mim sim, sim, e não, não?', 2, CURRENT_TIMESTAMP, false),
(47, 1, 18, 'Antes, como Deus é fiel, a nossa palavra para convosco não foi sim e não.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 19, 'Porque o Filho de Deus, Jesus Cristo, que entre vós foi pregado por nós, isto é, por mim, Silvano e Timóteo, não foi sim e não; mas nele houve sim.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 20, 'Porque todas quantas promessas há de Deus, são nele sim, e por ele o Amém, para glória de Deus por nós.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 21, 'Mas o que nos confirma convosco em Cristo, e o que nos ungiu, é Deus,', 2, CURRENT_TIMESTAMP, false),
(47, 1, 22, 'O qual também nos selou e deu o penhor do Espírito em nossos corações.', 2, CURRENT_TIMESTAMP, false),
(47, 1, 23, 'Invoco, porém, a Deus por testemunha sobre a minha alma, que para vos poupar não tenho até agora ido a Corinto;', 2, CURRENT_TIMESTAMP, false),
(47, 1, 24, 'Não que tenhamos domínio sobre a vossa fé, mas porque somos cooperadores de vosso gozo; porque pela fé estais em pé.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 1, 'Mas deliberei isto comigo mesmo: não ir mais ter convosco em tristeza.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 2, 'Porque, se eu vos entristeço, quem é que me alegrará, senão aquele que por mim foi contristado?', 2, CURRENT_TIMESTAMP, false),
(47, 2, 3, 'E escrevi-vos isto mesmo, para que, quando lá for, não tenha tristeza da parte dos que deveriam alegrar-me; confiando em vós todos, que a minha alegria é a de todos vós.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 4, 'Porque em muita tribulação e angústia do coração vos escrevi, com muitas lágrimas, não para que vos entristecêsseis, mas para que conhecêsseis o amor que abundantemente vos tenho.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 5, 'Porque, se alguém me contristou, não me contristou a mim senão em parte, para vos não sobrecarregar a vós todos.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 6, 'Basta-lhe ao tal esta repreensão feita por muitos.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 7, 'De maneira que pelo contrário deveis antes perdoar-lhe e consolá-lo, para que o tal não seja de modo algum devorado de demasiada tristeza.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 8, 'Por isso vos rogo que confirmeis para com ele o vosso amor.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 9, 'E para isso vos escrevi também, para por esta prova saber se sois obedientes em tudo.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 10, 'E a quem perdoardes alguma coisa, também eu; porque, o que eu também perdoei, se é que tenho perdoado, por amor de vós o fiz na presença de Cristo; para que não sejamos vencidos por Satanás;', 2, CURRENT_TIMESTAMP, false),
(47, 2, 11, 'Porque não ignoramos os seus ardís.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 12, 'Ora, quando cheguei a Trôade para pregar o evangelho de Cristo, e abrindo-se-me uma porta no Senhor,', 2, CURRENT_TIMESTAMP, false),
(47, 2, 13, 'Não tive descanso no meu espírito, porque não achei ali meu irmão Tito; mas, despedindo-me deles, parti para a macedônia.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 14, 'E graças a Deus, que sempre nos faz triunfar em Cristo, e por meio de nós manifesta em todo o lugar a fragrância do seu conhecimento.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 15, 'Porque para Deus somos o bom perfume de Cristo, nos que se salvam e nos que se perdem.', 2, CURRENT_TIMESTAMP, false),
(47, 2, 16, 'Para estes certamente cheiro de morte para morte; mas para aqueles cheiro de vida para vida. E para estas coisas quem é idôneo?', 2, CURRENT_TIMESTAMP, false),
(47, 2, 17, 'Porque nós não somos, como muitos, falsificadores da palavra de Deus, antes falamos de Cristo com sinceridade, como de Deus na presença de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 1, 'Porventura começamos outra vez a louvar-nos a nós mesmos? Ou necessitamos, como alguns, de cartas de recomendação para vós, ou de recomendação de vós?', 2, CURRENT_TIMESTAMP, false),
(47, 3, 2, 'Vós sois a nossa carta, escrita em nossos corações, conhecida e lida por todos os homens.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 3, 'Porque já é manifesto que vós sois a carta de Cristo, ministrada por nós, e escrita, não com tinta, mas com o Espírito do Deus vivo, não em tábuas de pedra, mas nas tábuas de carne do coração.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 4, 'E é por Cristo que temos tal confiança em Deus;', 2, CURRENT_TIMESTAMP, false),
(47, 3, 5, 'Não que sejamos capazes, por nós, de pensar alguma coisa, como de nós mesmos; mas a nossa capacidade vem de Deus,', 2, CURRENT_TIMESTAMP, false),
(47, 3, 6, 'O qual nos fez também capazes de ser ministros de um novo testamento, não da letra, mas do espírito; porque a letra mata e o espírito vivifica.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 7, 'E, se o ministério da morte, gravado com letras em pedras, veio em glória, de maneira que os filhos de Israel não podiam fitar os olhos na face de Moisés, por causa da glória do seu rosto, a qual era transitória,', 2, CURRENT_TIMESTAMP, false),
(47, 3, 8, 'Como não será de maior glória o ministério do Espírito?', 2, CURRENT_TIMESTAMP, false),
(47, 3, 9, 'Porque, se o ministério da condenação foi glorioso, muito mais excederá em glória o ministério da justiça.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 10, 'Porque também o que foi glorificado nesta parte não foi glorificado, por causa desta excelente glória.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 11, 'Porque, se o que era transitório foi para glória, muito mais é em glória o que permanece.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 12, 'Tendo, pois, tal esperança, usamos de muita ousadia no falar.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 13, 'E não somos como Moisés, que punha um véu sobre a sua face, para que os filhos de Israel não olhassem firmemente para o fim daquilo que era transitório.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 14, 'Mas os seus sentidos foram endurecidos; porque até hoje o mesmo véu está por levantar na lição do velho testamento, o qual foi por Cristo abolido;', 2, CURRENT_TIMESTAMP, false),
(47, 3, 15, 'E até hoje, quando é lido Moisés, o véu está posto sobre o coração deles.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 16, 'Mas, quando se converterem ao Senhor, então o véu se tirará.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 17, 'Ora, o Senhor é o Espírito; e onde está o Espírito do Senhor, aí há liberdade.', 2, CURRENT_TIMESTAMP, false),
(47, 3, 18, 'Mas todos nós, com rosto descoberto, refletindo como um espelho a glória do Senhor, somos transformados de glória em glória na mesma imagem, como pelo Espírito do Senhor.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 1, 'Por isso, tendo este ministério, segundo a misericórdia que nos foi feita, não desfalecemos;', 2, CURRENT_TIMESTAMP, false),
(47, 4, 2, 'Antes, rejeitamos as coisas que por vergonha se ocultam, não andando com astúcia nem falsificando a palavra de Deus; e assim nos recomendamos à consciência de todo o homem, na presença de Deus, pela manifestação da verdade.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 3, 'Mas, se ainda o nosso evangelho está encoberto, para os que se perdem está encoberto.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 4, 'Nos quais o deus deste século cegou os entendimentos dos incrédulos, para que lhes não resplandeça a luz do evangelho da glória de Cristo, que é a imagem de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 5, 'Porque não nos pregamos a nós mesmos, mas a Cristo Jesus, o Senhor; e nós mesmos somos vossos servos por amor de Jesus.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 6, 'Porque Deus, que disse que das trevas resplandecesse a luz, é quem resplandeceu em nossos corações, para iluminação do conhecimento da glória de Deus, na face de Jesus Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 7, 'Temos, porém, este tesouro em vasos de barro, para que a excelência do poder seja de Deus, e não de nós.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 8, 'Em tudo somos atribulados, mas não angustiados; perplexos, mas não desanimados.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 9, 'Perseguidos, mas não desamparados; abatidos, mas não destruídos;', 2, CURRENT_TIMESTAMP, false),
(47, 4, 10, 'Trazendo sempre por toda a parte a mortificação do Senhor Jesus no nosso corpo, para que a vida de Jesus se manifeste também nos nossos corpos;', 2, CURRENT_TIMESTAMP, false),
(47, 4, 11, 'E assim nós, que vivemos, estamos sempre entregues à morte por amor de Jesus, para que a vida de Jesus se manifeste também na nossa carne mortal.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 12, 'De maneira que em nós opera a morte, mas em vós a vida.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 13, 'E temos portanto o mesmo espírito de fé, como está escrito: Cri, por isso falei; nós cremos também, por isso também falamos.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 14, 'Sabendo que o que ressuscitou o Senhor Jesus nos ressuscitará também por Jesus, e nos apresentará convosco.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 15, 'Porque tudo isto é por amor de vós, para que a graça, multiplicada por meio de muitos, faça abundar a ação de graças para glória de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 16, 'Por isso não desfalecemos; mas, ainda que o nosso homem exterior se corrompa, o interior, contudo, se renova de dia em dia.', 2, CURRENT_TIMESTAMP, false),
(47, 4, 17, 'Porque a nossa leve e momentânea tribulação produz para nós um peso eterno de glória mui excelente;', 2, CURRENT_TIMESTAMP, false),
(47, 4, 18, 'Não atentando nós nas coisas que se vêem, mas nas que se não vêem; porque as que se vêem são temporais, e as que se não vêem são eternas.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 1, 'Porque sabemos que, se a nossa casa terrestre deste tabernáculo se desfizer, temos de Deus um edifício, uma casa não feita por mãos, eterna, nos céus.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 2, 'E por isso também gememos, desejando ser revestidos da nossa habitação, que é do céu;', 2, CURRENT_TIMESTAMP, false),
(47, 5, 3, 'Se, todavia, estando vestidos, não formos achados nus.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 4, 'Porque também nós, os que estamos neste tabernáculo, gememos carregados; não porque queremos ser despidos, mas revestidos, para que o mortal seja absorvido pela vida.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 5, 'Ora, quem para isto mesmo nos preparou foi Deus, o qual nos deu também o penhor do Espírito.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 6, 'Por isso estamos sempre de bom ânimo, sabendo que, enquanto estamos no corpo, vivemos ausentes do Senhor', 2, CURRENT_TIMESTAMP, false),
(47, 5, 7, '(Porque andamos por fé, e não por vista).', 2, CURRENT_TIMESTAMP, false),
(47, 5, 8, 'Mas temos confiança e desejamos antes deixar este corpo, para habitar com o Senhor.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 9, 'Pois que muito desejamos também ser-lhe agradáveis, quer presentes, quer ausentes.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 10, 'Porque todos devemos comparecer ante o tribunal de Cristo, para que cada um receba segundo o que tiver feito por meio do corpo, ou bem, ou mal.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 11, 'Assim que, sabendo o temor que se deve ao Senhor, persuadimos os homens à fé, mas somos manifestos a Deus; e espero que nas vossas consciências sejamos também manifestos.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 12, 'Porque não nos recomendamos outra vez a vós; mas damo-vos ocasião de vos gloriardes de nós, para que tenhais que responder aos que se gloriam na aparência e não no coração.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 13, 'Porque, se enlouquecemos, é para Deus; e, se conservamos o juízo, é para vós.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 14, 'Porque o amor de Cristo nos constrange, julgando nós assim: que, se um morreu por todos, logo todos morreram.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 15, 'E ele morreu por todos, para que os que vivem não vivam mais para si, mas para aquele que por eles morreu e ressuscitou.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 16, 'Assim que daqui por diante a ninguém conhecemos segundo a carne, e, ainda que também tenhamos conhecido Cristo segundo a carne, contudo agora já não o conhecemos deste modo.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 17, 'Assim que, se alguém está em Cristo, nova criatura é; as coisas velhas já passaram; eis que tudo se fez novo.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 18, 'E tudo isto provém de Deus, que nos reconciliou consigo mesmo por Jesus Cristo, e nos deu o ministério da reconciliação;', 2, CURRENT_TIMESTAMP, false),
(47, 5, 19, 'Isto é, Deus estava em Cristo reconciliando consigo o mundo, não lhes imputando os seus pecados; e pôs em nós a palavra da reconciliação.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 20, 'De sorte que somos embaixadores da parte de Cristo, como se Deus por nós rogasse. Rogamo-vos, pois, da parte de Cristo, que vos reconcilieis com Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 5, 21, 'Àquele que não conheceu pecado, o fez pecado por nós; para que nele fôssemos feitos justiça de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 6, 1, 'E nós, cooperando também com ele, vos exortamos a que não recebais a graça de Deus em vão', 2, CURRENT_TIMESTAMP, false),
(47, 6, 2, '(Porque diz:Ouvi-te em tempo aceitável e socorri-te no dia da salvação;eis aqui agora o tempo aceitável, eis aqui agora o dia da salvação).', 2, CURRENT_TIMESTAMP, false),
(47, 6, 3, 'Não dando nós escândalo em coisa alguma, para que o nosso ministério não seja censurado;', 2, CURRENT_TIMESTAMP, false),
(47, 6, 4, 'Antes, como ministros de Deus, tornando-nos recomendáveis em tudo; na muita paciência, nas aflições, nas necessidades, nas angústias,', 2, CURRENT_TIMESTAMP, false),
(47, 6, 5, 'Nos açoites, nas prisões, nos tumultos, nos trabalhos, nas vigílias, nos jejuns,', 2, CURRENT_TIMESTAMP, false),
(47, 6, 6, 'Na pureza, na ciência, na longanimidade, na benignidade, no Espírito Santo, no amor não fingido,', 2, CURRENT_TIMESTAMP, false),
(47, 6, 7, 'Na palavra da verdade, no poder de Deus, pelas armas da justiça, à direita e à esquerda,', 2, CURRENT_TIMESTAMP, false),
(47, 6, 8, 'Por honra e por desonra, por infâmia e por boa fama; como enganadores, e sendo verdadeiros;', 2, CURRENT_TIMESTAMP, false),
(47, 6, 9, 'Como desconhecidos, mas sendo bem conhecidos; como morrendo, e eis que vivemos; como castigados, e não mortos;', 2, CURRENT_TIMESTAMP, false),
(47, 6, 10, 'Como contristados, mas sempre alegres; como pobres, mas enriquecendo a muitos; como nada tendo, e possuindo tudo.', 2, CURRENT_TIMESTAMP, false),
(47, 6, 11, 'Ó coríntios, a nossa boca está aberta para vós, o nosso coração está dilatado.', 2, CURRENT_TIMESTAMP, false),
(47, 6, 12, 'Não estais estreitados em nós; mas estais estreitados nos vossos próprios afetos.', 2, CURRENT_TIMESTAMP, false),
(47, 6, 13, 'Ora, em recompensa disto, (falo como a filhos) dilatai-vos também vós.', 2, CURRENT_TIMESTAMP, false),
(47, 6, 14, 'Não vos prendais a um jugo desigual com os infiéis; porque, que sociedade tem a justiça com a injustiça? E que comunhão tem a luz com as trevas?', 2, CURRENT_TIMESTAMP, false),
(47, 6, 15, 'E que concórdia há entre Cristo e Belial? Ou que parte tem o fiel com o infiel?', 2, CURRENT_TIMESTAMP, false),
(47, 6, 16, 'E que consenso tem o templo de Deus com os ídolos? Porque vós sois o templo do Deus vivente, como Deus disse: Neles habitarei, e entre eles andarei; e eu serei o seu Deus e eles serão o meu povo.', 2, CURRENT_TIMESTAMP, false),
(47, 6, 17, 'Por isso saí do meio deles, e apartai-vos, diz o Senhor;E não toqueis nada imundo,E eu vos receberei;', 2, CURRENT_TIMESTAMP, false),
(47, 6, 18, 'E eu serei para vós Pai,E vós sereis para mim filhos e filhas, Diz o Senhor Todo-Poderoso.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 1, 'Ora, amados, pois que temos tais promessas, purifiquemo-nos de toda a imundícia da carne e do espírito, aperfeiçoando a santificação no temor de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 2, 'Recebei-nos em vossos corações; a ninguém agravamos, a ninguém corrompemos, de ninguém buscamos o nosso proveito.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 3, 'Não digo isto para vossa condenação; pois já antes tinha dito que estais em nossos corações para juntamente morrer e viver.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 4, 'Grande é a ousadia da minha fala para convosco, e grande a minha jactância a respeito de vós; estou cheio de consolação; transbordo de gozo em todas as nossas tribulações.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 5, 'Porque, mesmo quando chegamos à macedônia, a nossa carne não teve repouso algum; antes em tudo fomos atribulados: por fora combates, temores por dentro.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 6, 'Mas Deus, que consola os abatidos, nos consolou com a vinda de Tito.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 7, 'E não somente com a sua vinda, mas também pela consolação com que foi consolado por vós, contando-nos as vossas saudades, o vosso choro, o vosso zelo por mim, de maneira que muito me regozijei.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 8, 'Porquanto, ainda que vos contristei com a minha carta, não me arrependo, embora já me tivesse arrependido por ver que aquela carta vos contristou, ainda que por pouco tempo.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 9, 'Agora folgo, não porque fostes contristados, mas porque fostes contristados para arrependimento; pois fostes contristados segundo Deus; de maneira que por nós não padecestes dano em coisa alguma.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 10, 'Porque a tristeza segundo Deus opera arrependimento para a salvação, da qual ninguém se arrepende; mas a tristeza do mundo opera a morte.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 11, 'Porque, quanto cuidado não produziu isto mesmo em vós que, segundo Deus, fostes contristados! que apologia, que indignação, que temor, que saudades, que zelo, que vingança! Em tudo mostrastes estar puros neste negócio.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 12, 'Portanto, ainda que vos escrevi, não foi por causa do que fez o agravo, nem por causa do que sofreu o agravo, mas para que o vosso grande cuidado por nós fosse manifesto diante de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 13, 'Por isso fomos consolados pela vossa consolação, e muito mais nos alegramos pela alegria de Tito, porque o seu espírito foi recreado por vós todos.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 14, 'Porque, se nalguma coisa me gloriei de vós para com ele, não fiquei envergonhado; mas, como vos dissemos tudo com verdade, também a nossa glória para com Tito se achou verdadeira.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 15, 'E o seu entranhável afeto para convosco é mais abundante, lembrando-se da obediência de vós todos, e de como o recebestes com temor e tremor.', 2, CURRENT_TIMESTAMP, false),
(47, 7, 16, 'Regozijo-me de em tudo poder confiar em vós.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 1, 'Também, irmãos, vos fazemos conhecer a graça de Deus dada às igrejas da macedônia;', 2, CURRENT_TIMESTAMP, false),
(47, 8, 2, 'Como em muita prova de tribulação houve abundância do seu gozo, e como a sua profunda pobreza abundou em riquezas da sua generosidade.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 3, 'Porque, segundo o seu poder (o que eu mesmo testifico) e ainda acima do seu poder, deram voluntariamente.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 4, 'Pedindo-nos com muitos rogos que aceitássemos a graça e a comunicação deste serviço, que se fazia para com os santos.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 5, 'E não somente fizeram como nós esperávamos, mas a si mesmos se deram primeiramente ao Senhor, e depois a nós, pela vontade de Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 6, 'De maneira que exortamos a Tito que, assim como antes tinha começado, assim também acabasse esta graça entre vós.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 7, 'Portanto, assim como em tudo abundais em fé, e em palavra, e em ciência, e em toda a diligência, e em vosso amor para conosco, assim também abundeis nesta graça.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 8, 'Não digo isto como quem manda, mas para provar, pela diligência dos outros, a sinceridade de vosso amor.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 9, 'Porque já sabeis a graça de nosso Senhor Jesus Cristo que, sendo rico, por amor de vós se fez pobre; para que pela sua pobreza enriquecêsseis.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 10, 'E nisto dou o meu parecer; pois isto convém a vós que, desde o ano passado, começastes; e não foi só praticar, mas também querer.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 11, 'Agora, porém, completai também o já começado, para que, assim como houve a prontidão de vontade, haja também o cumprimento, segundo o que tendes.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 12, 'Porque, se há prontidão de vontade, será aceita segundo o que qualquer tem, e não segundo o que não tem.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 13, 'Mas, não digo isto para que os outros tenham alívio, e vós opressão,', 2, CURRENT_TIMESTAMP, false),
(47, 8, 14, 'Mas para igualdade; neste tempo presente, a vossa abundância supra a falta dos outros, para que também a sua abundância supra a vossa falta, e haja igualdade;', 2, CURRENT_TIMESTAMP, false),
(47, 8, 15, 'Como está escrito: O que muito colheu não teve demais; e o que pouco, não teve de menos.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 16, 'Mas, graças a Deus, que pôs a mesma solicitude por vós no coração de Tito;', 2, CURRENT_TIMESTAMP, false),
(47, 8, 17, 'Pois aceitou a exortação, e muito diligente partiu voluntariamente para vós.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 18, 'E com ele enviamos aquele irmão cujo louvor no evangelho está espalhado em todas as igrejas.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 19, 'E não só isto, mas foi também escolhido pelas igrejas para companheiro da nossa viagem, nesta graça que por nós é ministrada para glória do mesmo Senhor, e prontidão do vosso ânimo;', 2, CURRENT_TIMESTAMP, false),
(47, 8, 20, 'Evitando isto, que alguém nos vitupere por esta abundância, que por nós é ministrada;', 2, CURRENT_TIMESTAMP, false),
(47, 8, 21, 'Pois zelamos do que é honesto, não só diante do Senhor, mas também diante dos homens.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 22, 'Com eles enviamos também outro nosso irmão, o qual muitas vezes, e em muitas coisas, já experimentamos ser diligente, e agora muito mais diligente ainda pela muita confiança que em vós tem.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 23, 'Quanto a Tito, é meu companheiro, e cooperador para convosco; quanto a nossos irmãos, são embaixadores das igrejas e glória de Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 8, 24, 'Portanto, mostrai para com eles, e perante a face das igrejas, a prova do vosso amor, e da nossa glória acerca de vós.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 1, 'Quanto à administração que se faz a favor dos santos, não necessito escrever-vos;', 2, CURRENT_TIMESTAMP, false),
(47, 9, 2, 'Porque bem sei a prontidão do vosso ânimo, da qual me glorio de vós para com os macedônios; que a Acaia está pronta desde o ano passado; e o vosso zelo tem estimulado muitos.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 3, 'Mas enviei estes irmãos, para que a nossa glória, acerca de vós, não seja vã nesta parte; para que (como já disse) possais estar prontos,', 2, CURRENT_TIMESTAMP, false),
(47, 9, 4, 'A fim de, se acaso os macedônios vierem comigo, e vos acharem desapercebidos, não nos envergonharmos nós (para não dizermos vós) deste firme fundamento de glória.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 5, 'Portanto, tive por coisa necessária exortar estes irmãos, para que primeiro fossem ter convosco, e preparassem de antemão a vossa bênção, já antes anunciada, para que esteja pronta como bênção, e não como avareza.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 6, 'E digo isto: Que o que semeia pouco, pouco também ceifará; e o que semeia em abundância, em abundância ceifará.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 7, 'Cada um contribua segundo propôs no seu coração; não com tristeza, ou por necessidade; porque Deus ama ao que dá com alegria.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 8, 'E Deus é poderoso para fazer abundar em vós toda a graça, a fim de que tendo sempre, em tudo, toda a suficiência, abundeis em toda a boa obra;', 2, CURRENT_TIMESTAMP, false),
(47, 9, 9, 'Conforme está escrito:Espalhou, deu aos pobres;a sua justiça permanece para sempre.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 10, 'Ora, aquele que dá a semente ao que semeia, também vos dê pão para comer, e multiplique a vossa sementeira, e aumente os frutos da vossa justiça;', 2, CURRENT_TIMESTAMP, false),
(47, 9, 11, 'Para que em tudo enriqueçais para toda a beneficência, a qual faz que por nós se dêem graças a Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 12, 'Porque a administração deste serviço, não só supre as necessidades dos santos, mas também é abundante em muitas graças, que se dão a Deus.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 13, 'Visto como, na prova desta administração, glorificam a Deus pela submissão, que confessais quanto ao evangelho de Cristo, e pela liberalidade de vossos dons para com eles, e para com todos;', 2, CURRENT_TIMESTAMP, false),
(47, 9, 14, 'E pela sua oração por vós, tendo de vós saudades, por causa da excelente graça de Deus que em vós há.', 2, CURRENT_TIMESTAMP, false),
(47, 9, 15, 'Graças a Deus, pois, pelo seu dom inefável.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 1, 'Além disto, eu, Paulo, vos rogo, pela mansidão e benignidade de Cristo, eu que, na verdade, quando presente entre vós, sou humilde, mas ausente, ousado para convosco;', 2, CURRENT_TIMESTAMP, false),
(47, 10, 2, 'Rogo-vos, pois, que, quando estiver presente, não me veja obrigado a usar com confiança da ousadia que espero ter com alguns, que nos julgam, como se andássemos segundo a carne.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 3, 'Porque, andando na carne, não militamos segundo a carne.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 4, 'Porque as armas da nossa milícia não são carnais, mas sim poderosas em Deus para destruição das fortalezas;', 2, CURRENT_TIMESTAMP, false),
(47, 10, 5, 'Destruindo os conselhos, e toda a altivez que se levanta contra o conhecimento de Deus, e levando cativo todo o entendimento à obediência de Cristo;', 2, CURRENT_TIMESTAMP, false),
(47, 10, 6, 'E estando prontos para vingar toda a desobediência, quando for cumprida a vossa obediência.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 7, 'Olhais para as coisas segundo a aparência? Se alguém confia de si mesmo que é de Cristo, pense outra vez isto consigo, que, assim como ele é de Cristo, também nós de Cristo somos.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 8, 'Porque, ainda que eu me glorie mais alguma coisa do nosso poder, o qual o Senhor nos deu para edificação, e não para vossa destruição, não me envergonharei.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 9, 'Para que não pareça como se quisera intimidar-vos por cartas.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 10, 'Porque as suas cartas, dizem, são graves e fortes, mas a presença do corpo é fraca, e a palavra desprezível.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 11, 'Pense o tal isto, que, quais somos na palavra por cartas, estando ausentes, tais seremos também por obra, estando presentes.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 12, 'Porque não ousamos classificar-nos, ou comparar-nos com alguns, que se louvam a si mesmos; mas estes que se medem a si mesmos, e se comparam consigo mesmos, estão sem entendimento.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 13, 'Porém, não nos gloriaremos fora da medida, mas conforme a reta medida que Deus nos deu, para chegarmos até vós;', 2, CURRENT_TIMESTAMP, false),
(47, 10, 14, 'Porque não nos estendemos além do que convém, como se não houvéssemos de chegar até vós, pois já chegamos também até vós no evangelho de Cristo,', 2, CURRENT_TIMESTAMP, false),
(47, 10, 15, 'Não nos gloriando fora da medida nos trabalhos alheios; antes tendo esperança de que, crescendo a vossa fé, seremos abundantemente engrandecidos entre vós, conforme a nossa regra,', 2, CURRENT_TIMESTAMP, false),
(47, 10, 16, 'Para anunciar o evangelho nos lugares que estão além de vós e não em campo de outrem, para não nos gloriarmos no que estava já preparado.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 17, 'Aquele, porém, que se gloria, glorie-se no Senhor.', 2, CURRENT_TIMESTAMP, false),
(47, 10, 18, 'Porque não é aprovado quem a si mesmo se louva, mas, sim, aquele a quem o Senhor louva.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 1, 'Quisera eu me suportásseis um pouco na minha loucura! Suportai-me, porém, ainda.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 2, 'Porque estou zeloso de vós com zelo de Deus; porque vos tenho preparado para vos apresentar como uma virgem pura a um marido, a saber, a Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 3, 'Mas temo que, assim como a serpente enganou Eva com a sua astúcia, assim também sejam de alguma sorte corrompidos os vossos sentidos, e se apartem da simplicidade que há em Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 4, 'Porque, se alguém for pregar-vos outro Jesus que nós não temos pregado, ou se recebeis outro espírito que não recebestes, ou outro evangelho que não abraçastes, com razão o sofreríeis.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 5, 'Porque penso que em nada fui inferior aos mais excelentes apóstolos.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 6, 'E, se sou rude na palavra, não o sou contudo na ciência; mas já em todas as coisas nos temos feito conhecer totalmente entre vós.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 7, 'Pequei, porventura, humilhando-me a mim mesmo, para que vós fôsseis exaltados, porque de graça vos anunciei o evangelho de Deus?', 2, CURRENT_TIMESTAMP, false),
(47, 11, 8, 'Outras igrejas despojei eu para vos servir, recebendo delas salário; e quando estava presente convosco, e tinha necessidade, a ninguém fui pesado.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 9, 'Porque os irmãos que vieram da macedônia supriram a minha necessidade; e em tudo me guardei de vos ser pesado, e ainda me guardarei.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 10, 'Como a verdade de Cristo está em mim, esta glória não me será impedida nas regiões da Acaia.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 11, 'Por quê? Porque não vos amo? Deus o sabe.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 12, 'Mas o que eu faço o farei, para cortar ocasião aos que buscam ocasião, a fim de que, naquilo em que se gloriam, sejam achados assim como nós.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 13, 'Porque tais falsos apóstolos são obreiros fraudulentos, transfigurando-se em apóstolos de Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 14, 'E não é maravilha, porque o próprio Satanás se transfigura em anjo de luz.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 15, 'Não é muito, pois, que os seus ministros se transfigurem em ministros da justiça; o fim dos quais será conforme as suas obras.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 16, 'Outra vez digo: Ninguém me julgue insensato, ou então recebei-me como insensato, para que também me glorie um pouco.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 17, 'O que digo, não o digo segundo o Senhor, mas como por loucura, nesta confiança de gloriar-me.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 18, 'Pois que muitos se gloriam segundo a carne, eu também me gloriarei.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 19, 'Porque, sendo vós sensatos, de boa mente tolerais os insensatos.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 20, 'Pois sois sofredores, se alguém vos põe em servidão, se alguém vos devora, se alguém vos apanha, se alguém se exalta, se alguém vos fere no rosto.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 21, 'Envergonhado o digo, como se nós fôssemos fracos, mas no que qualquer tem ousadia (com insensatez falo) também eu tenho ousadia.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 22, 'São hebreus? também eu. São israelitas? também eu. São descendência de Abraão? também eu.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 23, 'São ministros de Cristo? (falo como fora de mim) eu ainda mais: em trabalhos, muito mais; em açoites, mais do que eles; em prisões, muito mais; em perigo de morte, muitas vezes.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 24, 'Recebi dos judeus cinco quarentenas de açoites menos um.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 25, 'Três vezes fui açoitado com varas, uma vez fui apedrejado, três vezes sofri naufrágio, uma noite e um dia passei no abismo;', 2, CURRENT_TIMESTAMP, false),
(47, 11, 26, 'Em viagens muitas vezes, em perigos de rios, em perigos de salteadores, em perigos dos da minha nação, em perigos dos gentios, em perigos na cidade, em perigos no deserto, em perigos no mar, em perigos entre os falsos irmãos;', 2, CURRENT_TIMESTAMP, false),
(47, 11, 27, 'Em trabalhos e fadiga, em vigílias muitas vezes, em fome e sede, em jejum muitas vezes, em frio e nudez.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 28, 'Além das coisas exteriores, me oprime cada dia o cuidado de todas as igrejas.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 29, 'Quem enfraquece, que eu também não enfraqueça? Quem se escandaliza, que eu me não abrase?', 2, CURRENT_TIMESTAMP, false),
(47, 11, 30, 'Se convém gloriar-me, gloriar-me-ei no que diz respeito à minha fraqueza.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 31, 'O Deus e Pai de nosso Senhor Jesus Cristo, que é eternamente bendito, sabe que não minto.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 32, 'Em Damasco, o que governava sob o rei Aretas pôs guardas às portas da cidade dos damascenos, para me prenderem.', 2, CURRENT_TIMESTAMP, false),
(47, 11, 33, 'E fui descido num cesto por uma janela da muralha; e assim escapei das suas mãos.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 1, 'Em verdade que não convém gloriar-me; mas passarei às visões e revelações do Senhor.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 2, 'Conheço um homem em Cristo que há catorze anos (se no corpo, não sei, se fora do corpo, não sei; Deus o sabe) foi arrebatado ao terceiro céu.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 3, 'E sei que o tal homem (se no corpo, se fora do corpo, não sei; Deus o sabe)', 2, CURRENT_TIMESTAMP, false),
(47, 12, 4, 'Foi arrebatado ao paraíso; e ouviu palavras inefáveis, que ao homem não é lícito falar.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 5, 'De alguém assim me gloriarei eu, mas de mim mesmo não me gloriarei, senão nas minhas fraquezas.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 6, 'Porque, se quiser gloriar-me, não serei néscio, porque direi a verdade; mas deixo isto, para que ninguém cuide de mim mais do que em mim vê ou de mim ouve.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 7, 'E, para que não me exaltasse pela excelência das revelações, foi-me dado um espinho na carne, a saber, um mensageiro de Satanás para me esbofetear, a fim de não me exaltar.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 8, 'Acerca do qual três vezes orei ao Senhor para que se desviasse de mim.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 9, 'E disse-me: A minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza. De boa vontade, pois, me gloriarei nas minhas fraquezas, para que em mim habite o poder de Cristo.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 10, 'Por isso sinto prazer nas fraquezas, nas injúrias, nas necessidades, nas perseguições, nas angústias por amor de Cristo. Porque quando estou fraco então sou forte.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 11, 'Fui néscio em gloriar-me; vós me constrangestes. Eu devia ter sido louvado por vós, visto que em nada fui inferior aos mais excelentes apóstolos, ainda que nada sou.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 12, 'Os sinais do meu apostolado foram manifestados entre vós com toda a paciência, por sinais, prodígios e maravilhas.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 13, 'Pois, em que tendes vós sido inferiores às outras igrejas, a não ser que eu mesmo vos não fui pesado? Perdoai-me este agravo.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 14, 'Eis aqui estou pronto para pela terceira vez ir ter convosco, e não vos serei pesado, pois que não busco o que é vosso, mas sim a vós: porque não devem os filhos entesourar para os pais, mas os pais para os filhos.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 15, 'Eu de muito boa vontade gastarei, e me deixarei gastar pelas vossas almas, ainda que, amando-vos cada vez mais, seja menos amado.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 16, 'Mas seja assim; eu não vos fui pesado mas, sendo astuto, vos tomei com dolo.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 17, 'Porventura aproveitei-me de vós por algum daqueles que vos enviei?', 2, CURRENT_TIMESTAMP, false),
(47, 12, 18, 'Roguei a Tito, e enviei com ele um irmão. Porventura Tito se aproveitou de vós? Não andamos porventura no mesmo espírito, sobre as mesmas pisadas?', 2, CURRENT_TIMESTAMP, false),
(47, 12, 19, 'Cuidais que ainda nos desculpamos convosco? Falamos em Cristo perante Deus, e tudo isto, ó amados, para vossa edificação.', 2, CURRENT_TIMESTAMP, false),
(47, 12, 20, 'Porque receio que, quando chegar, não vos ache como eu quereria, e eu seja achado de vós como não quereríeis; que de alguma maneira haja pendências, invejas, iras, porfias, detrações, mexericos, orgulhos, tumultos;', 2, CURRENT_TIMESTAMP, false),
(47, 12, 21, 'Que, quando for outra vez, o meu Deus me humilhe para convosco, e chore por muitos daqueles que dantes pecaram, e não se arrependeram da imundícia, e fornicação, e desonestidade que cometeram.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 1, 'É esta a terceira vez que vou ter convosco. Por boca de duas ou três testemunhas será confirmada toda a palavra.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 2, 'Já anteriormente o disse, e segunda vez o digo como quando estava presente; mas agora, estando ausente, o escrevo aos que antes pecaram e a todos os mais, que, se outra vez for, não lhes perdoarei;', 2, CURRENT_TIMESTAMP, false),
(47, 13, 3, 'Visto que buscais uma prova de Cristo que fala em mim, o qual não é fraco para convosco, antes é poderoso entre vós.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 4, 'Porque, ainda que foi crucificado por fraqueza, vive, contudo, pelo poder de Deus. Porque nós também somos fracos nele, mas viveremos com ele pelo poder de Deus em vós.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 5, 'Examinai-vos a vós mesmos, se permaneceis na fé; provai-vos a vós mesmos. Ou não sabeis quanto a vós mesmos, que Jesus Cristo está em vós? Se não é que já estais reprovados.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 6, 'Mas espero que entendereis que nós não somos reprovados.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 7, 'Ora, eu rogo a Deus que não façais mal algum, não para que sejamos achados aprovados, mas para que vós façais o bem, embora nós sejamos como reprovados.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 8, 'Porque nada podemos contra a verdade, senão pela verdade.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 9, 'Porque nos regozijamos de estar fracos, quando vós estais fortes; e o que desejamos é a vossa perfeição.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 10, 'Portanto, escrevo estas coisas estando ausente, para que, estando presente, não use de rigor, segundo o poder que o Senhor me deu para edificação, e não para destruição.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 11, 'Quanto ao mais, irmãos, regozijai-vos, sede perfeitos, sede consolados, sede de um mesmo parecer, vivei em paz; e o Deus de amor e de paz será convosco.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 12, 'Saudai-vos uns aos outros com ósculo santo.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 13, 'Todos os santos vos saúdam.', 2, CURRENT_TIMESTAMP, false),
(47, 13, 14, 'A graça do Senhor Jesus Cristo, e o amor de Deus, e a comunhão do Espírito Santo seja com todos vós. Amém.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 1, 'Salomão, filho de Davi, fortaleceu-se no seu reino; e o SENHOR seu Deus era com ele, e o engrandeceu sobremaneira.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 2, 'E falou Salomão a todo o Israel, aos capitães de mil e de cem, aos juízes e a todos os governadores em todo o Israel, chefes das famílias.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 3, 'E foi Salomão, e toda a congregação com ele, ao alto que estava em Gibeom, porque ali estava a tenda da congregação de Deus, que Moisés, servo do Senhor, tinha feito no deserto.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 4, 'Mas Davi tinha feito subir a arca de Deus de Quiriate-Jearim ao lugar que lhe preparara; porque lhe tinha armado uma tenda em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 5, 'Também o altar de cobre que tinha feito Bezaleel, filho de Uri, filho de Hur, estava ali diante do tabernáculo do Senhor; e Salomão e a congregação o buscavam.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 6, 'E Salomão ofereceu ali sacrifícios perante o Senhor, sobre o altar de cobre que estava na tenda da congregação; e ofereceu sobre ele mil holocaustos.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 7, 'Naquela mesma noite Deus apareceu a Salomão, e disse-lhe: Pede o que queres que eu te dê.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 8, 'E Salomão disse a Deus: Tu usaste de grande benignidade com meu pai Davi, e a mim me fizeste rei em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 9, 'Agora, pois, ó Senhor Deus, confirme-se a tua palavra, dada a meu pai Davi; porque tu me fizeste reinar sobre um povo numeroso como o pó da terra.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 10, 'Dá-me, pois, agora, sabedoria e conhecimento, para que possa sair e entrar perante este povo; pois quem poderia julgar a este tão grande povo?', 2, CURRENT_TIMESTAMP, false),
(14, 1, 11, 'Então Deus disse a Salomão: Porquanto houve isto no teu coração, e não pediste riquezas, bens, ou honra, nem a morte dos que te odeiam, nem tampouco pediste muitos dias de vida, mas pediste para ti sabedoria e conhecimento, para poderes julgar a meu povo, sobre o qual te constituí rei,', 2, CURRENT_TIMESTAMP, false),
(14, 1, 12, 'Sabedoria e conhecimento te são dados; e te darei riquezas, bens e honra, quais não teve nenhum rei antes de ti, e nem depois de ti haverá.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 13, 'Assim Salomão veio a Jerusalém, do alto que estava em Gibeom, de diante da tenda da congregação; e reinou sobre Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 14, 'E Salomão ajuntou carros e cavaleiros, e teve mil e quatrocentos carros, e doze mil cavaleiros; os quais pôs nas cidades dos carros, e junto ao rei em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 15, 'E fez o rei que houvesse ouro e prata em Jerusalém como pedras; e cedros em tanta abundância como figueiras bravas que há pelas campinas.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 16, 'E os cavalos, que tinha Salomão, eram trazidos do Egito; e os mercadores do rei os recebiam em tropas, cada uma pelo seu preço.', 2, CURRENT_TIMESTAMP, false),
(14, 1, 17, 'E faziam subir e sair do Egito cada carro por seiscentos siclos de prata, e cada cavalo por cento e cinqüenta; e assim, por meio deles eram para todos os reis dos heteus, e para os reis da Síria.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 1, 'E determinou Salomão edificar uma casa ao nome do SENHOR, como também uma casa para o seu reino.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 2, 'E designou Salomão setenta mil homens de carga, e oitenta mil que talhavam pedras na montanha, e três mil e seiscentos inspetores sobre eles.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 3, 'E Salomão mandou dizer a Hirão, rei de Tiro: Como fizeste com Davi meu pai, mandando-lhe cedros, para edificar uma casa em que morasse, assim também faze comigo.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 4, 'Eis que estou para edificar uma casa ao nome do Senhor meu Deus, para lhe consagrar, para queimar perante ele incenso aromático, e para a apresentação contínua do pão da proposição, para os holocaustos da manhã e da tarde, nos sábados e nas luas novas, e nas festividades do Senhor nosso Deus; o que é obrigação perpétua de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 5, 'E a casa que estou para edificar há de ser grande; porque o nosso Deus é maior do que todos os deuses.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 6, 'Porém, quem seria capaz de lhe edificar uma casa, visto que os céus e até os céus dos céus o não podem conter? E quem sou eu, que lhe edificasse casa, salvo para queimar incenso perante ele?', 2, CURRENT_TIMESTAMP, false),
(14, 2, 7, 'Manda-me, pois, agora um homem hábil para trabalhar em ouro, em prata, em bronze, em ferro, em púrpura, em carmesim e em azul; e que saiba lavrar ao buril, juntamente com os peritos que estão comigo em Judá e em Jerusalém, os quais Davi, meu pai, preparou.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 8, 'Manda-me também madeiras de cedro, de cipreste, e algumins do Líbano; porque bem sei eu que os teus servos sabem cortar madeira no Líbano; e eis que os meus servos estarão com os teus servos.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 9, 'E isso para prepararem muita madeira; porque a casa que estou para fazer há de ser grande e maravilhosa.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 10, 'E eis que a teus servos, os cortadores, que cortarem a madeira, darei vinte mil coros de trigo malhado, vinte mil coros de cevada, vinte mil batos de vinho e vinte mil batos de azeite.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 11, 'E Hirão, rei de Tiro, respondeu por escrito que enviou a Salomão, dizendo: Porque o Senhor tem amado o seu povo, te constituiu sobre ele rei.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 12, 'Disse mais Hirão: Bendito seja o Senhor Deus de Israel, que fez os céus e a terra; o que deu ao rei Davi um filho sábio, de grande prudência e entendimento, que edifique casa ao Senhor, e para o seu reino.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 13, 'Agora, pois, envio um homem sábio de grande entendimento, a saber, Hirão Abiú.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 14, 'Filho de uma mulher das filhas de Dã, e cujo pai foi homem de Tiro; este sabe trabalhar em ouro, em prata, em bronze, em ferro, em pedras e em madeira, em púrpura, em azul, e em linho fino, e em carmesim, e é hábil para toda a obra do buril, e para toda a espécie de invenções, qualquer coisa que se lhe propuser, juntamente com os teus peritos, e os peritos de Davi, meu senhor, teu pai.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 15, 'Agora, pois, meu senhor, mande para os seus servos o trigo, a cevada, o azeite e o vinho, de que falou;', 2, CURRENT_TIMESTAMP, false),
(14, 2, 16, 'E nós cortaremos tanta madeira no Líbano, quanta houveres mister, e ta traremos em jangadas pelo mar até Jope, e tu a farás subir a Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 17, 'E Salomão contou todos os homens estrangeiros, que havia na terra de Israel, conforme o censo com que os contara Davi seu pai; e acharam-se cento e cinqüenta e três mil e seiscentos.', 2, CURRENT_TIMESTAMP, false),
(14, 2, 18, 'E designou deles setenta mil carregadores, e oitenta mil cortadores na montanha; como também três mil e seiscentos inspetores, para fazerem trabalhar o povo.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 1, 'E começou Salomão a edificar a casa do SENHOR em Jerusalém, no monte Moriá, onde o SENHOR aparecera a Davi seu pai, no lugar que Davi tinha preparado na eira de Ornã, o jebuseu.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 2, 'E começou a edificar no segundo mês, no segundo dia, no ano quarto do seu reinado.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 3, 'E estes foram os fundamentos que Salomão pôs para edificar a casa de Deus: o comprimento em côvados, segundo a primeira medida, era de sessenta côvados, e a largura de vinte côvados.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 4, 'E o pátio, que estava na frente, tinha vinte côvados de comprimento, segundo a largura da casa, e a altura era de cento e vinte; e por dentro o revestiu com ouro puro.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 5, 'E a casa grande forrou com madeira de faia; e então a revestiu com ouro fino; e fez sobre ela palmas e cadeias.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 6, 'Também a casa adornou de pedras preciosas, para ornamento; e o ouro era ouro de Parvaim.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 7, 'Também na casa revestiu, com ouro, as traves, os umbrais, as suas paredes e as suas portas; e lavrou querubins nas paredes.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 8, 'Fez mais a casa do lugar santíssimo, cujo comprimento, segundo a largura da casa, era de vinte côvados, e também a largura de vinte côvados; e revestiu-a de ouro fino, do peso de seiscentos talentos.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 9, 'O peso dos pregos era de cinqüenta siclos de ouro; e as câmaras cobriu de ouro.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 10, 'Também fez na casa do lugar santíssimo dois querubins de obra móvel, e cobriu-os de ouro.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 11, 'E, quanto às asas dos querubins, o seu comprimento era de vinte côvados; a asa de um deles, de cinco côvados, e tocava na parede da casa; e a outra asa de cinco côvados, e tocava na asa do outro querubim.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 12, 'Também a asa do outro querubim era de cinco côvados, e tocava na parede da casa; era também a outra asa de cinco côvados, que tocava na asa do outro querubim.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 13, 'E as asas destes querubins se estendiam vinte côvados; e estavam postos em pé, e os seus rostos virados para a casa.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 14, 'Também fez o véu de azul, púrpura, carmesim e linho fino; e pôs sobre ele querubins;', 2, CURRENT_TIMESTAMP, false),
(14, 3, 15, 'Fez também, diante da casa, duas colunas de trinta e cinco côvados de altura; e o capitel, que estava sobre cada uma, era de cinco côvados.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 16, 'Também fez cadeias no oráculo, e as pôs sobre as cabeças das colunas; fez também cem romãs, as quais pôs entre as cadeias.', 2, CURRENT_TIMESTAMP, false),
(14, 3, 17, 'E levantou as colunas diante do templo, uma à direita, e outra à esquerda; e chamou o nome da que estava à direita Jaquim, e o nome da que estava à esquerda Boaz.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 1, 'Também fez um altar de metal, de vinte côvados de comprimento, de vinte côvados de largura e de dez côvados de altura.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 2, 'Fez também o mar de fundição, de dez côvados de uma borda até a outra, redondo, e de cinco côvados de altura; cingia-o ao redor um cordão de trinta côvados.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 3, 'E por baixo dele havia figuras de bois, que cingiam o mar ao redor, dez em cada côvado, contornando-o; e tinha duas fileiras de bois, fundidos juntamente com o mar.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 4, 'E o mar estava posto sobre doze bois; três que olhavam para o norte, três que olhavam para o ocidente, três que olhavam para o sul e três que olhavam para o oriente; e o mar estava posto sobre eles; e as suas partes posteriores estavam todas para o lado de dentro.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 5, 'E tinha um palmo de grossura, e a sua borda foi feita como a borda de um copo, ou como uma flor-de-lis, da capacidade de três mil batos.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 6, 'Também fez dez pias; e pôs cinco à direita e cinco à esquerda, para lavarem nelas; o que pertencia ao holocausto o lavavam nelas; porém o mar era para que os sacerdotes se lavassem nele.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 7, 'Fez também dez castiçais de ouro, segundo a sua forma, e pô-los no templo, cinco à direita, e cinco à esquerda.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 8, 'Também fez dez mesas, e pô-las no templo, cinco à direita e cinco à esquerda; também fez cem bacias de ouro.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 9, 'Fez mais o pátio dos sacerdotes, e o grande átrio; como também as portas para o pátio, as quais revestiu de cobre.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 10, 'E pôs o mar ao lado direito, para o lado do oriente, na direção do sul.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 11, 'Também Hirão fez as caldeiras, as pás e as bacias. Assim acabou Hirão de fazer a obra, que fazia para o rei Salomão, na casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 12, 'As duas colunas, os globos, e os dois capitéis sobre as cabeças das colunas; e as duas redes, para cobrir os dois globos dos capitéis, que estavam sobre a cabeça das colunas.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 13, 'E as quatrocentas romãs para as duas redes; duas carreiras de romãs para cada rede, para cobrirem os dois globos dos capitéis que estavam em cima das colunas.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 14, 'Também fez as bases; e as pias pôs sobre as bases;', 2, CURRENT_TIMESTAMP, false),
(14, 4, 15, 'Um mar, e os doze bois debaixo dele;', 2, CURRENT_TIMESTAMP, false),
(14, 4, 16, 'Semelhantemente as caldeiras, as pás, os garfos e todos os seus utensílios, fez Hirão Abiú ao rei Salomão, para a casa do Senhor, de cobre polido.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 17, 'Na campina do Jordão os fundiu o rei, na terra argilosa, entre Sucote e Zeredá.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 18, 'E fez Salomão todos estes objetos em grande abundância, que não se podia averiguar o peso do cobre.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 19, 'Fez também Salomão todos os objetos que eram para a casa de Deus, como também o altar de ouro, e as mesas, sobre as quais estavam os pães da proposição.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 20, 'E os castiçais com as suas lâmpadas de ouro finíssimo, para as acenderem segundo o costume, perante o oráculo.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 21, 'E as flores, as lâmpadas e os espevitadores eram de ouro, do mais finíssimo ouro.', 2, CURRENT_TIMESTAMP, false),
(14, 4, 22, 'Como também os apagadores, as bacias, as colheres e os incensários de ouro finíssimo; e quanto à entrada da casa, as suas portas de dentro do lugar santíssimo, e as portas da casa do templo, eram de ouro.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 1, 'Assim se acabou toda a obra que Salomão fez para a casa do SENHOR; então trouxe Salomão as coisas que seu pai Davi havia consagrado, a prata, o ouro e todos os objetos, e pô-los entre os tesouros da casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 2, 'Então Salomão congregou em Jerusalém os anciãos de Israel, e todos os chefes das tribos, os chefes dos pais entre os filhos de Israel, para fazerem subir a arca da aliança do Senhor, da cidade de Davi, que é Sião.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 3, 'E todos os homens de Israel se congregaram ao rei na ocasião da festa, que foi no sétimo mês.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 4, 'E vieram todos os anciãos de Israel; e os levitas levantaram a arca.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 5, 'E fizeram subir a arca, e a tenda da congregação, com todos os objetos sagrados, que estavam na tenda; os sacerdotes e os levitas os fizeram subir.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 6, 'Então o rei Salomão e toda a congregação de Israel, que se tinha reunido com ele diante da arca, sacrificaram carneiros e bois, que não se podiam contar, nem numerar, por causa da sua abundância.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 7, 'Assim trouxeram os sacerdotes a arca da aliança do Senhor ao seu lugar, ao oráculo da casa, ao lugar santíssimo, até debaixo das asas dos querubins.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 8, 'Porque os querubins estendiam ambas as asas sobre o lugar da arca, e os querubins cobriam, por cima, a arca e os seus varais.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 9, 'Então os varais sobressaíam para que as pontas dos varais da arca se vissem perante o oráculo, mas não se vissem de fora; e ali tem estado até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 10, 'Na arca não havia coisa alguma senão as duas tábuas, que Moisés tinha posto em Horebe, quando o Senhor fez aliança com os filhos de Israel, saíndo eles do Egito.', 2, CURRENT_TIMESTAMP, false),
(14, 5, 11, 'E sucedeu que, saindo os sacerdotes do santuário (porque todos os sacerdotes, que ali se acharam, se santificaram, sem respeitarem as suas turmas,', 2, CURRENT_TIMESTAMP, false),
(14, 5, 12, 'E os levitas, que eram cantores, todos eles, de Asafe, de Hemã, de Jedutum, de seus filhos e de seus irmãos, vestidos de linho fino, com címbalos, com saltérios e com harpas, estavam em pé para o oriente do altar; e com eles até cento e vinte sacerdotes, que tocavam as trombetas).', 2, CURRENT_TIMESTAMP, false),
(14, 5, 13, 'E aconteceu que, quando eles uniformemente tocavam as trombetas, e cantavam, para fazerem ouvir uma só voz, bendizendo e louvando ao Senhor; e levantando eles a voz com trombetas, címbalos, e outros instrumentos musicais, e louvando ao Senhor, dizendo: Porque ele é bom, porque a sua benignidade dura para sempre, então a casa se encheu de uma nuvem, a saber, a casa do Senhor;', 2, CURRENT_TIMESTAMP, false),
(14, 5, 14, 'E os sacerdotes não podiam permanecer em pé, para ministrar, por causa da nuvem; porque a glória do Senhor encheu a casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 1, 'Então falou Salomão: O SENHOR disse que habitaria nas trevas.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 2, 'E eu te tenho edificado uma casa para morada, e um lugar para a tua eterna habitação.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 3, 'Então o rei virou o seu rosto, e abençoou a toda a congregação de Israel, e toda a congregação de Israel estava em pé.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 4, 'E ele disse: Bendito seja o Senhor Deus de Israel, que falou pela sua boca a Davi meu pai; e pelas suas mãos o cumpriu, dizendo:', 2, CURRENT_TIMESTAMP, false),
(14, 6, 5, 'Desde o dia em que tirei a meu povo da terra do Egito, não escolhi cidade alguma de todas as tribos de Israel, para edificar nela uma casa em que estivesse o meu nome; nem escolhi homem algum para ser líder do meu povo, Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 6, 'Porém escolhi a Jerusalém para que ali estivesse o meu nome; e escolhi a Davi, para que estivesse sobre o meu povo Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 7, 'Também Davi meu pai teve no seu coração o edificar uma casa ao nome do Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 8, 'Porém o Senhor disse a Davi, meu pai: Porquanto tiveste no teu coração o edificar uma casa ao meu nome, bem fizeste de ter isto no teu coração.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 9, 'Contudo tu não edificarás a casa, mas teu filho, que há de proceder de teus lombos, esse edificará a casa ao meu nome.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 10, 'Assim confirmou o Senhor a sua palavra, que falou; porque eu me levantei em lugar de Davi meu pai, e me assentei sobre o trono de Israel, como o Senhor disse, e edifiquei a casa ao nome do Senhor Deus de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 11, 'E pus nela a arca, em que está a aliança que o Senhor fez com os filhos de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 12, 'E pôs-se em pé, perante o altar do Senhor, na presença de toda a congregação de Israel, e estendeu as suas mãos.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 13, 'Porque Salomão tinha feito uma plataforma de metal, de cinco côvados de comprimento, de cinco côvados de largura e de três côvados de altura, e a tinha posto no meio do pátio, e pôs-se em pé sobre ela, e ajoelhou-se em presença de toda a congregação de Israel, e estendeu as suas mãos para o céu.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 14, 'E disse: Ó Senhor Deus de Israel, não há Deus semelhante a ti, nem nos céus nem na terra; que guardas a aliança e a beneficência aos teus servos que caminham perante ti de todo o seu coração.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 15, 'Que guardaste ao teu servo Davi, meu pai, o que lhe falaste; porque tu pela tua boca o disseste, e pela tua mão o cumpriste, como se vê neste dia.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 16, 'Agora, pois, Senhor Deus de Israel, guarda ao teu servo Davi, meu pai, o que falaste, dizendo: Nunca homem algum será cortado de diante de mim, que se assente sobre o trono de Israel; tão-somente que teus filhos guardem seu caminho, andando na minha lei, como tu andaste diante de mim.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 17, 'E agora, Senhor Deus de Israel, cumpra-se a tua palavra, que disseste ao teu servo Davi.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 18, 'Mas, na verdade, habitará Deus com os homens na terra? Eis que os céus, e o céu dos céus, não te podem conter, quanto menos esta casa que tenho edificado?', 2, CURRENT_TIMESTAMP, false),
(14, 6, 19, 'Atende, pois, à oração do teu servo, e à sua súplica, ó Senhor meu Deus; para ouvires o clamor, e a oração, que o teu servo faz perante ti.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 20, 'Que os teus olhos estejam dia e noite abertos sobre este lugar, de que disseste que ali porias o teu nome; para ouvires a oração que o teu servo orar neste lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 21, 'Ouve, pois, as súplicas do teu servo, e do teu povo Israel, que fizerem neste lugar; e ouve tu do lugar da tua habitação, desde os céus; ouve pois, e perdoa.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 22, 'Quando alguém pecar contra o seu próximo, e lhe impuser juramento de maldição, fazendo-o jurar, e o juramento de maldição vier perante o teu altar, nesta casa,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 23, 'Ouve tu, então, desde os céus, e age e julga a teus servos, condenando ao ímpio, retribuindo o seu proceder sobre a sua cabeça; e justificando ao justo, dando-lhe segundo a sua justiça.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 24, 'Quando também o teu povo Israel for ferido diante do inimigo, por ter pecado contra ti, e eles se converterem, e confessarem o teu nome, e orarem e suplicarem perante ti nesta casa,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 25, 'Então, ouve tu desde os céus, e perdoa os pecados do teu povo Israel; e torna a levá-los à terra que lhes tens dado e a seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 26, 'Quando os céus se fecharem, e não houver chuva, por terem pecado contra ti, e orarem neste lugar, e confessarem teu nome, e se converterem dos seus pecados, quando tu os afligires,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 27, 'Então, ouve tu desde os céus, e perdoa o pecado de teus servos, e do teu povo Israel, ensinando-lhes o bom caminho, em que andem; e dá chuva sobre a tua terra, que deste ao teu povo em herança.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 28, 'Quando houver fome na terra, quando houver peste, quando houver queima de seara, ou ferrugem, gafanhotos, ou lagarta, cercando-a algum dos seus inimigos nas terras das suas portas, ou quando houver qualquer praga, ou qualquer enfermidade,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 29, 'Toda a oração, e toda a súplica, que qualquer homem fizer, ou todo o teu povo Israel, conhecendo cada um a sua praga, e a sua dor, e estendendo as suas mãos para esta casa,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 30, 'Então, ouve tu desde os céus, do assento da tua habitação, e perdoa, e dá a cada um conforme a todos os seus caminhos, segundo conheces o seu coração (pois só tu conheces o coração dos filhos dos homens),', 2, CURRENT_TIMESTAMP, false),
(14, 6, 31, 'A fim de que te temam, para andarem nos teus caminhos, todos os dias que viverem na terra que deste a nossos pais.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 32, 'Assim também ao estrangeiro, que não for do teu povo Israel, quando vier de terras remotas por amor do teu grande nome, e da tua poderosa mão, e do teu braço estendido, vindo eles e orando nesta casa;', 2, CURRENT_TIMESTAMP, false),
(14, 6, 33, 'Então, ouve tu desde os céus, do assento da tua habitação, e faze conforme a tudo o que o estrangeiro te suplicar; a fim de que todos os povos da terra conheçam o teu nome, e te temam, como o teu povo Israel; e a fim de saberem que pelo teu nome é chamada esta casa que edifiquei.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 34, 'Quando o teu povo sair à guerra contra os seus inimigos, pelo caminho que os enviares, e orarem a ti para o lado desta cidade que escolheste, e desta casa, que edifiquei ao teu nome,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 35, 'Ouve, então, desde os céus a sua oração, e a sua súplica, e faze-lhes justiça.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 36, 'Quando pecarem contra ti (pois não há homem que não peque), e tu te indignares contra eles, e os entregares diante do inimigo, para que os que os cativarem os levem em cativeiro para alguma terra, remota ou vizinha,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 37, 'E na terra, para onde forem levados em cativeiro, caírem em si, e se converterem, e na terra do seu cativeiro, a ti suplicarem, dizendo: Pecamos, perversamente procedemos e impiamente agimos;', 2, CURRENT_TIMESTAMP, false),
(14, 6, 38, 'E se converterem a ti com todo o seu coração e com toda a sua alma, na terra do seu cativeiro, a que os levaram presos, e orarem para o lado da sua terra, que deste a seus pais, e para esta cidade que escolheste, e para esta casa que edifiquei ao teu nome,', 2, CURRENT_TIMESTAMP, false),
(14, 6, 39, 'Ouve, então, desde os céus, do assento da tua habitação, a sua oração e as suas súplicas, e executa o seu direito; e perdoa ao teu povo que houver pecado contra ti.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 40, 'Agora, pois, ó meu Deus, estejam os teus olhos abertos, e os teus ouvidos atentos à oração deste lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 41, 'Levanta-te, pois, agora, Senhor Deus, para o teu repouso, tu e a arca da tua fortaleza; os teus sacerdotes, ó Senhor Deus, sejam vestidos de salvação, e os teus santos se alegrem do bem.', 2, CURRENT_TIMESTAMP, false),
(14, 6, 42, 'Ó Senhor Deus, não faças virar o rosto do teu ungido; lembra-te das misericórdias de Davi teu servo.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 1, 'E acabando Salomão de orar, desceu o fogo do céu, e consumiu o holocausto e os sacrifícios; e a glória do SENHOR encheu a casa.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 2, 'E os sacerdotes não podiam entrar na casa do Senhor, porque a glória do Senhor tinha enchido a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 3, 'E todos os filhos de Israel vendo descer o fogo, e a glória do Senhor sobre a casa, encurvaram-se com o rosto em terra sobre o pavimento, e adoraram e louvaram ao Senhor, dizendo: Porque ele é bom, porque a sua benignidade dura para sempre.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 4, 'E o rei e todo o povo ofereciam sacrifícios perante o Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 5, 'E o rei Salomão ofereceu sacrifícios de bois, vinte e dois mil, e de ovelhas, cento e vinte mil; e o rei e todo o povo consagraram a casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 6, 'E os sacerdotes, serviam em seus ofícios; como também os levitas com os instrumentos musicais do Senhor, que o rei Davi tinha feito, para louvarem ao Senhor, porque a sua benignidade dura para sempre, quando Davi o louvava pelo ministério deles; e os sacerdotes tocavam as trombetas diante deles, e todo o Israel estava em pé.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 7, 'E Salomão santificou o meio do átrio, que estava diante da casa do Senhor; porquanto ali tinha ele oferecido os holocaustos e a gordura dos sacrifícios pacíficos; porque no altar de metal, que Salomão tinha feito, não podia caber o holocausto, e a oferta de alimentos, e a gordura.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 8, 'E, assim, naquele mesmo tempo celebrou Salomão a festa por sete dias e todo o Israel com ele, uma grande congregação, desde a entrada de Hamate, até ao rio do Egito.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 9, 'E no dia oitavo realizaram uma assembléia solene; porque sete dias celebraram a consagração do altar, e sete dias a festa.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 10, 'E no dia vigésimo terceiro do sétimo mês, despediu o povo para as suas tendas, alegres e de bom ânimo, pelo bem que o Senhor tinha feito a Davi, e a Salomão, e a seu povo Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 11, 'Assim Salomão acabou a casa do Senhor, e a casa do rei, e tudo quanto Salomão intentou fazer na casa do Senhor e na sua casa prosperamente o efetuou.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 12, 'E o Senhor apareceu de noite a Salomão, e disse-lhe: Ouvi a tua oração, e escolhi para mim este lugar para casa de sacrifício.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 13, 'Se eu fechar os céus, e não houver chuva; ou se ordenar aos gafanhotos que consumam a terra; ou se enviar a peste entre o meu povo;', 2, CURRENT_TIMESTAMP, false),
(14, 7, 14, 'E se o meu povo, que se chama pelo meu nome, se humilhar, e orar, e buscar a minha face e se converter dos seus maus caminhos, então eu ouvirei dos céus, e perdoarei os seus pecados, e sararei a sua terra.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 15, 'Agora estarão abertos os meus olhos e atentos os meus ouvidos à oração deste lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 16, 'Porque agora escolhi e santifiquei esta casa, para que o meu nome esteja nela perpetuamente; e nela estarão fixos os meus olhos e o meu coração todos os dias.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 17, 'E, quanto a ti, se andares diante de mim, como andou Davi teu pai, e fizeres conforme a tudo o que te ordenei, e guardares os meus estatutos e os meus juízos,', 2, CURRENT_TIMESTAMP, false),
(14, 7, 18, 'Também confirmarei o trono do teu reino, conforme a aliança que fiz com Davi, teu pai, dizendo: Não te faltará sucessor que domine em Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 19, 'Porém se vós vos desviardes, e deixardes os meus estatutos, e os meus mandamentos, que vos tenho proposto, e fordes, e servirdes a outros deuses, e vos prostrardes a eles,', 2, CURRENT_TIMESTAMP, false),
(14, 7, 20, 'Então os arrancarei da minha terra que lhes dei, e lançarei da minha presença esta casa que consagrei ao meu nome, e farei com que seja por provérbio e motejo entre todos os povos.', 2, CURRENT_TIMESTAMP, false),
(14, 7, 21, 'E desta casa, que é tão exaltada, qualquer que passar por ela se espantará e dirá: Por que fez o Senhor assim com esta terra e com esta casa?', 2, CURRENT_TIMESTAMP, false),
(14, 7, 22, 'E dirão: Porque deixaram ao Senhor Deus de seus pais, que os tirou da terra do Egito, e se deram a outros deuses, e se prostraram a eles, e os serviram; por isso ele trouxe sobre eles todo este mal.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 1, 'E sucedeu, ao fim de vinte anos, nos quais Salomão edificou a casa do SENHOR, e a sua própria casa,', 2, CURRENT_TIMESTAMP, false),
(14, 8, 2, 'Que Salomão edificou as cidades que Hirão lhe tinha dado; e fez habitar nelas os filhos de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 3, 'Depois foi Salomão a Hamate-Zobá, e a tomou.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 4, 'Também edificou a Tadmor no deserto, e todas as cidades de provisões, que edificou em Hamate.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 5, 'Edificou também a alta Bete-Horom, e a baixa Bete-Horom; cidades fortes, com muros, portas e ferrolhos;', 2, CURRENT_TIMESTAMP, false),
(14, 8, 6, 'Como também a Baalate, e todas as cidades de provisões, que Salomão tinha, e todas as cidades dos carros e as cidades dos cavaleiros; e tudo quanto, conforme ao seu desejo, Salomão quis edificar em Jerusalém, e no Líbano, e em toda a terra do seu domínio.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 7, 'Quanto a todo o povo, que tinha ficado dos heteus, amorreus, perizeus, heveus e jebuseus, que não eram de Israel,', 2, CURRENT_TIMESTAMP, false),
(14, 8, 8, 'Dos seus filhos, que ficaram depois deles na terra, os quais os filhos de Israel não destruíram, Salomão os fez tributários, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 9, 'Porém, dos filhos de Israel, Salomão não fez servos para sua obra (mas eram homens de guerra, chefes dos seus capitàes, e capitàes dos seus carros e cavaleiros),', 2, CURRENT_TIMESTAMP, false),
(14, 8, 10, 'Destes, pois, eram os chefes dos oficiais que o rei Salomão tinha, duzentos e cinqüenta, que presidiam sobre o povo.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 11, 'E Salomão fez subir a filha de Faraó da cidade de Davi para a casa que lhe tinha edificado; porque disse: Minha mulher não morará na casa de Davi, rei de Israel, porquanto santos são os lugares nos quais entrou a arca do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 12, 'Então Salomão ofereceu holocaustos ao Senhor, sobre o altar do Senhor, que tinha edificado diante do pórtico,', 2, CURRENT_TIMESTAMP, false),
(14, 8, 13, 'E isto segundo a ordem de cada dia, fazendo ofertas conforme o mandamento de Moisés, nos sábados e nas luas novas, e nas solenidades, três vezes no ano; na festa dos pães ázimos, na festa das semanas, e na festa das tendas.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 14, 'Também, conforme à ordem de Davi seu pai, designou as turmas dos sacerdotes para seus ministérios, como também as dos levitas acerca dos seus cargos, para louvarem e ministrarem diante dos sacerdotes, segundo o que estava ordenado para cada dia, e os porteiros pelas suas turmas a cada porta; porque assim tinha mandado Davi, o homem de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 15, 'E não se desviaram do mandado do rei aos sacerdotes e levitas, em negócio nenhum, nem acerca dos tesouros.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 16, 'Assim se preparou toda a obra de Salomão, desde o dia da fundação da casa do Senhor, até se acabar; e assim se concluiu a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 17, 'Então foi Salomão a Eziom-Geber, e a Elote, à praia do mar, na terra de Edom.', 2, CURRENT_TIMESTAMP, false),
(14, 8, 18, 'E enviou-lhe Hirão, por meio de seus servos, navios, e servos práticos do mar, e foram com os servos de Salomão a Ofir, e tomaram de lá quatrocentos e cinqüenta talentos de ouro; e os trouxeram ao rei Salomão.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 1, 'E ouvindo a rainha de Sabá a fama de Salomão, veio a Jerusalém, para prová-lo com questões difíceis, com um grande séquito, e com camelos carregados de especiarias; ouro em abundância e pedras preciosas; e foi a Salomão, e falou com ele de tudo o que tinha no seu coração.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 2, 'E Salomão lhe respondeu a todas as suas questões; e não houve nada que não lhe pudesse esclarecer.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 3, 'Vendo, pois, a rainha de Sabá a sabedoria de Salomão, e a casa que edificara;', 2, CURRENT_TIMESTAMP, false),
(14, 9, 4, 'E as iguarias da sua mesa, o assentar dos seus servos, o estar dos seus criados, e as vestes deles; e os seus copeiros e as vestes deles; e a sua subida pela qual ele chegava à casa do Senhor, ela ficou como fora de si.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 5, 'Então disse ao rei: Era verdade a palavra que ouvi na minha terra acerca dos teus feitos e da tua sabedoria.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 6, 'Porém não cria naquelas palavras, até que vim, e meus olhos o viram, e eis que não me disseram a metade da grandeza da tua sabedoria; sobrepujaste a fama que ouvi.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 7, 'Bem-aventurados os teus homens, e bem-aventurados estes teus servos, que estão sempre diante de ti, e ouvem a tua sabedoria!', 2, CURRENT_TIMESTAMP, false),
(14, 9, 8, 'Bendito seja o Senhor teu Deus, que se agradou de ti para te colocar no seu trono como rei para o Senhor teu Deus; porque teu Deus ama a Israel, para estabelecê-lo perpetuamente; por isso te constituiu rei sobre eles para fazeres juízo e justiça.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 9, 'E deu ao rei cento e vinte talentos de ouro, e especiarias em grande abundância, e pedras preciosas; e nunca houve tais especiarias, quais a rainha de Sabá deu ao rei Salomão.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 10, 'E também os servos de Hirão e os servos de Salomão, que de Ofir tinham trazido ouro, trouxeram madeira de algumins, e pedras preciosas.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 11, 'E, da madeira de algumins, o rei fez balaústres, para a casa do Senhor, e para a casa do rei, como também harpas e saltérios para os cantores, quais nunca dantes se viram na terra de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 12, 'E o rei Salomão deu à rainha de Sabá tudo quanto ela desejou, e tudo quanto lhe pediu, mais do que ela mesma trouxera ao rei. Assim voltou e foi para a sua terra, ela e os seus servos.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 13, 'E o peso do ouro, que vinha em um ano a Salomão, era de seiscentos e sessenta e seis talentos de ouro,', 2, CURRENT_TIMESTAMP, false),
(14, 9, 14, 'Afora o que os negociantes e mercadores traziam; também todos os reis da Arábia, e os governadores da mesma terra traziam a Salomão ouro e prata.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 15, 'Também fez o rei Salomão duzentos paveses de ouro batido; para cada pavês destinou seiscentos siclos de ouro batido.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 16, 'Como também trezentos escudos de ouro batido; para cada escudo destinou trezentos siclos de ouro; e Salomão os pôs na casa do bosque do Líbano.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 17, 'Fez mais o rei um grande trono de marfim, e o revestiu de ouro puro.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 18, 'E o trono tinha seis degraus, e um estrado de ouro, que eram ligados ao trono, e encostos de ambos os lados no lugar do assento; e dois leões estavam junto aos encostos.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 19, 'E doze leões estavam ali de ambos os lados, sobre os seis degraus; outro tal não se fez em nenhum reino.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 20, 'Também todas as taças do rei Salomão eram de ouro, e todos os vasos da casa do bosque do Líbano, de ouro puro; a prata reputava-se por nada nos dias de Salomão.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 21, 'Porque, indo os navios do rei com os servos de Hirão, a Társis, voltavam os navios de Társis, uma vez em três anos, e traziam ouro e prata, marfim, bugios e pavões.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 22, 'Assim excedeu o rei Salomão a todos os reis da terra, em riquezas e sabedoria.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 23, 'E todos os reis da terra buscavam a presença de Salomão, para ouvirem a sabedoria que Deus tinha posto no seu coração.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 24, 'E cada um trazia o seu presente, vasos de prata, e vasos de ouro, e roupas, armaduras, especiarias, cavalos e mulas; assim faziam de ano em ano.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 25, 'Teve também Salomão quatro mil estrebarias para os cavalos de seus carros, e doze mil cavaleiros; e colocou-os nas cidades dos carros, e junto ao rei em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 26, 'E dominava sobre todos os reis, desde o rio até à terra dos filisteus, e até ao termo do Egito.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 27, 'Também o rei fez que houvesse prata em Jerusalém como pedras, e cedros em tanta abundância como as figueiras bravas que há pelas campinas.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 28, 'E do Egito e de todas aquelas terras traziam cavalos a Salomão.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 29, 'Os demais atos de Salomão, tanto os primeiros como os últimos, porventura não estão escritos no livro das crônicas de Natã, o profeta, e na profecia de Aías, o silonita, e nas visões de Ido, o vidente, acerca de Jeroboão, filho de Nebate?', 2, CURRENT_TIMESTAMP, false),
(14, 9, 30, 'E reinou Salomão em Jerusalém quarenta anos sobre todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 9, 31, 'E dormiu Salomão com seus pais, e o sepultaram na cidade de Davi seu pai; e Roboão, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 1, 'E foi Roboão a Siquém, porque todo o Israel se reunira ali, para fazê-lo rei.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 2, 'Sucedeu que, ouvindo-o Jero-boão, filho de Nebate (o qual estava então no Egito para onde fugira da presença do rei Salomão), voltou do Egito,', 2, CURRENT_TIMESTAMP, false),
(14, 10, 3, 'Porque enviaram a ele, e o chamaram; e vieram, Jeroboão e todo o Israel, e falaram a Roboão dizendo:', 2, CURRENT_TIMESTAMP, false),
(14, 10, 4, 'Teu pai fez duro o nosso jugo; agora, pois, alivia tu a dura servidão de teu pai, e o pesado jugo que nos impôs, e nós te serviremos.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 5, 'E ele lhes disse: Daqui a três dias voltai a mim. Então o povo se foi.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 6, 'E tomou Roboão conselho com os anciãos, que estiveram perante Salomão seu pai, enquanto viveu, dizendo: Como aconselhais vós que se responda a este povo?', 2, CURRENT_TIMESTAMP, false),
(14, 10, 7, 'E eles lhe falaram, dizendo: Se te fizeres benigno e afável para com este povo, e lhes falares boas palavras, todos os dias serão teus servos.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 8, 'Porém ele deixou o conselho que os anciãos lhe deram; e tomou conselho com os jovens, que haviam crescido com ele, e estavam perante ele.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 9, 'E disse-lhes: Que aconselhais vós, que respondamos a este povo, que me falou, dizendo: Alivia o jugo que teu pai nos impôs?', 2, CURRENT_TIMESTAMP, false),
(14, 10, 10, 'E os jovens, que com ele haviam crescido, lhe falaram, dizendo: Assim dirás a este povo, que te falou: Teu pai agravou o nosso jugo, tu porém alivia-nos; assim, pois, lhe falarás: O meu dedo mínimo é mais grosso do que os lombos de meu pai.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 11, 'Assim que, se meu pai vos carregou de um jugo pesado, eu ainda aumentarei o vosso jugo; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 12, 'Veio, pois, Jeroboão, e todo o povo, ao terceiro dia, a Roboão, como o rei havia ordenado, dizendo: Voltai a mim ao terceiro dia.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 13, 'E o rei lhes respondeu asperamente; porque o rei Roboão deixara o conselho dos anciãos.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 14, 'E falou-lhes conforme o conselho dos jovens, dizendo: Meu pai agravou o vosso jugo, porém eu o aumentarei mais; meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 15, 'Assim o rei não deu ouvidos ao povo, porque esta mudança vinha de Deus, para que o Senhor confirmasse a sua palavra, a qual falara pelo ministério de Aías, o silonita, a Jeroboão, filho de Nebate.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 16, 'Vendo, pois, todo o Israel, que o rei não lhe dava ouvidos, tornou-lhe o povo a responder, dizendo: Que parte temos nós com Davi? Já não temos herança no filho de Jessé. Cada um à sua tenda, ó Israel! Olha agora pela tua casa, ó Davi. Assim todo o Israel se foi para as suas tendas.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 17, 'Porém, quanto aos filhos de Israel, que habitavam nas cidades de Judá, sobre eles reinou Roboão.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 18, 'Então o rei Roboão enviou a Hadorão, que tinha cargo dos tributos; porém os filhos de Israel o apedrejaram, e ele morreu. Então o rei Roboão se esforçou para subir ao seu carro, e fugiu para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 10, 19, 'Assim se rebelaram os israelitas contra a casa de Davi, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 1, 'Vindo, pois, Roboão a Jerusalém, reuniu, da casa de Judá e Benjamim, cento e oitenta mil escolhidos, destros na guerra, para pelejarem contra Israel, e para restituírem o reino a Roboão.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 2, 'Porém a palavra do Senhor veio a Semaías, homem de Deus, dizendo:', 2, CURRENT_TIMESTAMP, false),
(14, 11, 3, 'Fala a Roboão, filho de Salomão, rei de Judá, e a todo o Israel, em Judá e Benjamim, dizendo:', 2, CURRENT_TIMESTAMP, false),
(14, 11, 4, 'Assim diz o Senhor: Não subireis, nem pelejareis contra os vossos irmãos; volte cada um à sua casa; porque de mim proveio isto. E ouviram as palavras do Senhor, e desistiram de ir contra Jeroboão.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 5, 'E Roboão habitou em Jerusalém; e para defesa, edificou cidades em Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 6, 'Edificou, pois, a Belém, a Etã, e a Tecoa,', 2, CURRENT_TIMESTAMP, false),
(14, 11, 7, 'E a Bete-Zur, a Socó, a Adulão,', 2, CURRENT_TIMESTAMP, false),
(14, 11, 8, 'E a Gate, a Maressa, a Zife,', 2, CURRENT_TIMESTAMP, false),
(14, 11, 9, 'E a Adoraim, a Laquis, e a Azeca,', 2, CURRENT_TIMESTAMP, false),
(14, 11, 10, 'E a Zorá, a Aijalom, e a Hebrom, que estavam em Judá e em Benjamim; cidades fortes.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 11, 'E fortificou estas fortalezas e pôs nelas capitàes, e armazéns de víveres, de azeite, e de vinho.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 12, 'E pôs em cada cidade paveses e lanças; fortificou-as grandemente; e Judá e Benjamim pertenceram-lhe.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 13, 'Também os sacerdotes e os levitas, que havia em todo o Israel, se reuniram a ele de todos os seus termos.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 14, 'Porque os levitas deixaram os seus arrabaldes, e a sua possessão, e vieram a Judá e a Jerusalém, porque Jeroboão e seus filhos os lançaram fora para que não ministrassem ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 15, 'E ele constituiu para si sacerdotes, para os altos, para os demônios, e para os bezerros, que fizera.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 16, 'Depois desses também, de todas as tribos de Israel, os que deram o seu coração a buscarem ao Senhor Deus de Israel, vieram a Jerusalém, para oferecerem sacrifícios ao Senhor Deus de seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 17, 'Assim fortaleceram o reino de Judá e corroboraram a Roboão, filho de Salomão, por três anos; porque três anos andaram no caminho de Davi e Salomão.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 18, 'E Roboão tomou para si, por mulher, a Maalate, filha de Jerimote, filho de Davi; e Abiail, filha de Eliabe, filho de Jessé.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 19, 'A qual lhe deu filhos: Jeús, Samarias e Zaã.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 20, 'E depois dela tomou a Maaca, filha de Absalão; esta lhe deu Abias, Atai, Ziza e Selomite.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 21, 'E amava Roboão mais a Maaca, filha de Absalão, do que a todas as suas outras mulheres e concubinas; porque ele tinha tomado dezoito mulheres, e sessenta concubinas; e gerou vinte e oito filhos, e sessenta filhas.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 22, 'E Roboão designou Abias, filho de Maaca, para ser chefe e líder entre os seus irmãos, porque queria fazê-lo rei.', 2, CURRENT_TIMESTAMP, false),
(14, 11, 23, 'E usou de prudência, e de todos os seus filhos, alguns espalhou por todas as terras de Judá, e Benjamim, por todas as cidades fortes; e deu-lhes víveres em abundância; e lhes procurou muitas mulheres.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 1, 'Sucedeu que, havendo Roboão confirmado o reino, e havendo-se fortalecido, deixou a lei do SENHOR, e com ele todo o Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 2, 'E sucedeu que, no quinto ano do rei Roboão, Sisaque, rei do Egito, subiu contra Jerusalém (porque tinham transgredido contra o Senhor)', 2, CURRENT_TIMESTAMP, false),
(14, 12, 3, 'Com mil e duzentos carros e com sessenta mil cavaleiros; e era inumerável o povo que vinha com ele do Egito, de líbios, suquitas e etíopes.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 4, 'E tomou as cidades fortificadas, que Judá tinha; e chegou até Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 5, 'Então veio Semaías, o profeta, a Roboão e aos príncipes de Judá que se ajuntaram em Jerusalém por causa de Sisaque, e disse-lhes: Assim diz o Senhor: Vós me deixastes a mim, por isso também eu vos deixei na mão de Sisaque.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 6, 'Então se humilharam os príncipes de Israel, e o rei, e disseram: O Senhor é justo.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 7, 'Vendo, pois, o Senhor que se humilhavam, veio a palavra do Senhor a Semaías, dizendo: Humilharam-se, não os destruirei; antes em breve lhes darei algum socorro, para que o meu furor não se derrame sobre Jerusalém, por mão de Sisaque.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 8, 'Porém serão seus servos; para que conheçam a diferença da minha servidão e da servidão dos reinos da terra.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 9, 'Subiu, pois, Sisaque, rei do Egito, contra Jerusalém, e tomou os tesouros da casa do Senhor, e os tesouros da casa do rei; levou tudo; também tomou os escudos de ouro, que Salomão fizera.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 10, 'E fez o rei Roboão em lugar deles escudos de cobre, e os entregou na mão dos chefes da guarda, que guardavam a porta da casa do rei.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 11, 'E todas as vezes que o rei entrava na casa do Senhor, vinham os da guarda, e os levavam; depois tornavam a pô-los na câmara da guarda.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 12, 'E humilhando-se ele, a ira do Senhor se desviou dele, para que não o destruísse de todo; porque em Judá ainda havia boas coisas.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 13, 'Fortificou-se, pois, o rei Roboão em Jerusalém, e reinou; porque Roboão era da idade de quarenta e um anos, quando começou a reinar; e reinou dezessete anos em Jerusalém, a cidade que o Senhor escolheu, dentre todas as tribos de Israel, para pôr ali o seu nome; e era o nome de sua mãe Naamá, amonita.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 14, 'E fez o que era mau; porquanto não preparou o seu coração para buscar ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 15, 'Os atos, pois, de Roboão, assim os primeiros, como os últimos, porventura não estão escritos nos livros de Semaías, o profeta, e de Ido, o vidente, na relação das genealogias? E houve guerras entre Roboão e Jeroboão em todos os seus dias.', 2, CURRENT_TIMESTAMP, false),
(14, 12, 16, 'E Roboão dormiu com seus pais, e foi sepultado na cidade de Davi; e Abias, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 1, 'No ano décimo oitavo do rei Jeroboão, Abias começou a reinar sobre Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 2, 'Três anos reinou em Jerusalém; e era o nome de sua mãe Micaía, filha de Uriel de Gibeá; e houve guerra entre Abias e Jeroboão.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 3, 'E Abias ordenou a peleja com um exército de valentes guerreiros, quatrocentos mil homens escolhidos; e Jeroboão dispôs contra ele a batalha com oitocentos mil homens escolhidos, todos homens corajosos.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 4, 'E pôs-se Abias em pé em cima do monte de Zemaraim, que está na montanha de Efraim, e disse: Ouvi-me, Jeroboão e todo o Israel:', 2, CURRENT_TIMESTAMP, false),
(14, 13, 5, 'Porventura não vos convém saber que o Senhor Deus de Israel deu para sempre a Davi a soberania sobre Israel, a ele e a seus filhos, por uma aliança de sal?', 2, CURRENT_TIMESTAMP, false),
(14, 13, 6, 'Contudo levantou-se Jeroboão, filho de Nebate, servo de Salomão, filho de Davi, e se rebelou contra seu senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 7, 'E ajuntaram-se a ele homens vadios, filhos de Belial; e fortificaram-se contra Roboão, filho de Salomão, sendo Roboão ainda jovem, e terno de coração, e não lhes podia resistir.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 8, 'E agora julgais que podeis resistir ao reino do Senhor, que está na mão dos filhos de Davi, visto que sois uma grande multidão, e tendes convosco os bezerros de ouro que Jeroboão vos fez para deuses.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 9, 'Não lançastes vós fora os sacerdotes do Senhor, os filhos de Arão, e os levitas, e não fizestes para vós sacerdotes, como os povos das outras terras? Qualquer que vem a consagrar-se com um novilho e sete carneiros logo se faz sacerdote daqueles que não são deuses.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 10, 'Porém, quanto a nós, o Senhor é nosso Deus, e nunca o deixamos; e os sacerdotes que ministram ao Senhor são filhos de Arão, e os levitas se ocupam na sua obra.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 11, 'E queimam ao Senhor cada manhã e cada tarde holocaustos, incenso aromático, com os pães da proposição sobre a mesa pura, e o castiçal de ouro, e as suas lâmpadas para se acenderem cada tarde, porque nós temos cuidado do serviço do Senhor nosso Deus; porém vós o deixastes.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 12, 'E eis que Deus está conosco, à nossa frente, como também os seus sacerdotes, tocando com as trombetas, para dar alarme contra vós. Ó filhos de Israel, não pelejeis contra o Senhor Deus de vossos pais; porque não prosperareis.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 13, 'Mas Jeroboão armou uma emboscada, para dar sobre eles pela retaguarda; de maneira que estavam em frente de Judá e a emboscada por detrás deles.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 14, 'Então Judá olhou, e eis que tinham que pelejar por diante e por detrás; então clamaram ao Senhor; e os sacerdotes tocaram as trombetas.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 15, 'E os homens de Judá gritaram; e sucedeu que, gritando os homens de Judá, Deus feriu a Jeroboão e a todo o Israel diante de Abias e de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 16, 'E os filhos de Israel fugiram de diante de Judá; e Deus os entregou na sua mão.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 17, 'De maneira que Abias e o seu povo fizeram grande matança entre eles; porque caíram feridos de Israel quinhentos mil homens escolhidos.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 18, 'E foram humilhados os filhos de Israel naquele tempo; e os filhos de Judá prevaleceram, porque confiaram no Senhor Deus de seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 19, 'E Abias perseguiu Jeroboão; e tomou-lhe a Betel com os lugares da sua jurisdição, e a Jesana com os lugares da sua jurisdição, e a Efrom com os lugares da sua jurisdição.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 20, 'E Jeroboão não recobrou mais o seu poder nos dias de Abias; porém o Senhor o feriu, e morreu.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 21, 'Abias, porém, se fortificou, e tomou para si catorze mulheres, e gerou vinte e dois filhos e dezesseis filhas.', 2, CURRENT_TIMESTAMP, false),
(14, 13, 22, 'Os demais atos de Abias, tanto os seus caminhos como as suas palavras, estão escritos na história do profeta Ido.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 1, 'E Abias dormiu com seus pais, e o sepultaram na cidade de Davi, e Asa, seu filho, reinou em seu lugar; nos seus dias esteve a terra em paz dez anos.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 2, 'E Asa fez o que era bom e reto aos olhos do Senhor seu Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 3, 'Porque tirou os altares dos deuses estranhos, e os altos; e quebrou as imagens, e cortou os bosques.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 4, 'E mandou a Judá que buscasse ao Senhor Deus de seus pais, e que observasse a lei e o mandamento.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 5, 'Também tirou de todas as cidades de Judá os altos e as imagens; e sob ele o reino esteve em paz.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 6, 'E edificou cidades fortificadas em Judá; porque a terra estava quieta, e não havia guerra contra ele naqueles anos; porquanto o Senhor lhe dera repouso.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 7, 'Disse, pois, a Judá: Edifiquemos estas cidades, e cerquemo-las de muros e torres, portas e ferrolhos, enquanto a terra ainda é nossa, pois buscamos ao Senhor nosso Deus; buscamo-lo, e deu-nos repouso de todos os lados. Edificaram, pois, e prosperaram.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 8, 'Tinha Asa um exército de trezentos mil de Judá, que traziam pavês e lança; e duzentos e oitenta mil de Benjamim, que traziam escudo e atiravam com arco; todos estes eram homens valentes.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 9, 'E Zerá, o etíope, saiu contra eles, com um exército de um milhão e com trezentos carros, e chegou até Maressa.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 10, 'Então Asa saiu contra ele; e ordenaram a batalha no vale de Zefatá, junto a Maressa.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 11, 'E Asa clamou ao Senhor seu Deus, e disse: Senhor, nada para ti é ajudar, quer o poderoso quer o de nenhuma força; ajuda-nos, pois, Senhor nosso Deus, porque em ti confiamos, e no teu nome viemos contra esta multidão. Senhor, tu és nosso Deus, não prevaleça contra ti o homem.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 12, 'E o Senhor feriu os etíopes diante de Asa e diante de Judá; e os etíopes fugiram.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 13, 'E Asa, e o povo que estava com ele os perseguiram até Gerar, e caíram tantos dos etíopes, que já não havia neles resistência alguma; porque foram destruídos diante do Senhor, e diante do seu exército; e levaram dali mui grande despojo.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 14, 'E feriram todas as cidades nos arredores de Gerar, porque o terror do Senhor veio sobre elas; e saquearam todas as cidades, porque havia nelas muita presa.', 2, CURRENT_TIMESTAMP, false),
(14, 14, 15, 'Também feriram as malhadas do gado; e levaram ovelhas em abundância, e camelos, e voltaram para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 1, 'Então veio o Espírito de Deus sobre Azarias, filho de Odede.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 2, 'E saiu ao encontro de Asa, e disse-lhe: Ouvi-me, Asa, e todo o Judá e Benjamim: O Senhor está convosco, enquanto vós estais com ele, e, se o buscardes, o achareis; porém, se o deixardes, vos deixará.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 3, 'E Israel esteve por muitos dias sem o verdadeiro Deus, e sem sacerdote que o ensinasse, e sem lei.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 4, 'Mas quando na sua angústia voltaram para o Senhor Deus de Israel, e o buscaram, o acharam.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 5, 'E naqueles tempos não havia paz, nem para o que saía, nem para o que entrava, mas muitas perturbações sobre todos os habitantes daquelas terras.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 6, 'Porque nação contra nação e cidade contra cidade se despedaçavam; porque Deus os perturbara com toda a angústia.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 7, 'Mas esforçai-vos, e não desfaleçam as vossas mãos; porque a vossa obra tem uma recompensa.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 8, 'Ouvindo, pois, Asa estas palavras, e a profecia do profeta Odede, cobrou ânimo e tirou as abominações de toda a terra, de Judá e de Benjamim, como também das cidades que tomara nas montanhas de Efraim, e renovou o altar do Senhor, que estava diante do pórtico do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 9, 'E reuniu a todo o Judá, e Benjamim, e com eles os estrangeiros de Efraim e Manassés, e de Simeão; porque muitos de Israel tinham passado a ele, vendo que o Senhor seu Deus era com ele.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 10, 'E ajuntaram-se em Jerusalém no terceiro mês; no ano décimo do reinado de Asa.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 11, 'E no mesmo dia ofereceram em sacrifício ao Senhor, do despojo que trouxeram, setecentos bois e sete mil ovelhas.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 12, 'E entraram na aliança para buscarem o Senhor Deus de seus pais, com todo o seu coração, e com toda a sua alma;', 2, CURRENT_TIMESTAMP, false),
(14, 15, 13, 'E de que todo aquele que não buscasse ao Senhor Deus de Israel, morresse; assim o menor como o maior, tanto o homem como a mulher.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 14, 'E juraram ao Senhor, em alta voz, com júbilo e com trombetas e buzinas.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 15, 'E todo o Judá se alegrou deste juramento; porque de todo o seu coração juraram, e de toda a sua vontade o buscaram, e o acharam; e o Senhor lhes deu repouso ao redor.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 16, 'E também a Maaca, sua mãe, o rei Asa depôs, para que não fosse mais rainha, porquanto fizera um horrível ídolo, a Aserá; e Asa destruiu o seu horrível ídolo, e o despedaçou, e o queimou junto ao ribeiro de Cedrom.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 17, 'Os altos, porém, não foram tirados de Israel; contudo o coração de Asa foi perfeito todos os seus dias.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 18, 'E trouxe, à casa de Deus, as coisas consagradas por seu pai, e as coisas que ele mesmo tinha consagrado: prata, ouro e vasos.', 2, CURRENT_TIMESTAMP, false),
(14, 15, 19, 'E não houve guerra até ao ano trigésimo quinto do reinado de Asa.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 1, 'No trigésimo sexto ano do reinado de Asa, Baasa, rei de Israel, subiu contra Judá e edificou a Ramá, para não deixar ninguém sair, nem chegar a Asa, rei de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 2, 'Então Asa tirou a prata e o ouro dos tesouros da casa do Senhor, e da casa do rei; e enviou servos a Ben-Hadade, rei da Síria, que habitava em Damasco, dizendo:', 2, CURRENT_TIMESTAMP, false),
(14, 16, 3, 'Acordo há entre mim e ti, como houve entre meu pai e o teu; eis que te envio prata e ouro; vai, pois, e anula o teu acordo com Baasa, rei de Israel, para que se retire de sobre mim.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 4, 'E Ben-Hadade deu ouvidos ao rei Asa, e enviou os capitães dos seus exércitos, contra as cidades de Israel, e eles feriram a Ijom, a Dã, a Abel-Maim, e a todas as cidades-armazéns de Naftali.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 5, 'E sucedeu que, ouvindo-o Baasa, deixou de edificar a Ramá, e não continuou a sua obra.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 6, 'Então o rei Asa tomou a todo o Judá, e levaram as pedras de Ramá, e a sua madeira, com que Baasa edificara; e com elas edificou a Geba e a Mizpá.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 7, 'Naquele mesmo tempo veio Hanani, o vidente, a Asa, rei de Judá, e disse-lhe: Porquanto confiaste no rei da Síria, e não confiaste no Senhor teu Deus, por isso o exército do rei da Síria escapou da tua mão.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 8, 'Porventura não foram os etíopes e os líbios um grande exército, com muitíssimos carros e cavaleiros? Confiando tu, porém, no Senhor, ele os entregou nas tuas mãos.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 9, 'Porque, quanto ao Senhor, seus olhos passam por toda a terra, para mostrar-se forte para com aqueles cujo coração é perfeito para com ele; nisto, pois, procedeste loucamente porque desde agora haverá guerras contra ti.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 10, 'Porém Asa se indignou contra o vidente, e lançou-o na casa do tronco; porque estava enfurecido contra ele, por causa disto; também Asa, no mesmo tempo, oprimiu a alguns do povo.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 11, 'E eis que os atos de Asa, tanto os primeiros, como os últimos, estão escritos no livro dos reis de Judá e Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 12, 'E, no ano trinta e nove do seu reinado, Asa caiu doente de seus pés, a sua doença era em extremo grave; contudo, na sua enfermidade, não buscou ao Senhor, mas antes os médicos.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 13, 'E Asa dormiu com seus pais; e morreu no ano quarenta e um do seu reinado.', 2, CURRENT_TIMESTAMP, false),
(14, 16, 14, 'E o sepultaram no seu sepulcro, que tinha cavado para si na cidade de Davi, havendo-o deitado na cama, que se enchera de perfumes e especiarias preparadas segundo a arte dos perfumistas; e, destas coisas fizeram-lhe uma grande queima.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 1, 'E Jeosafá, seu filho, reinou em seu lugar; e fortificou-se contra Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 2, 'E pôs soldados em todas as cidades fortificadas de Judá, e estabeleceu guarnições na terra de Judá, como também nas cidades de Efraim, que Asa seu pai tinha tomado.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 3, 'E o Senhor era com Jeosafá; porque andou nos primeiros caminhos de Davi seu pai, e não buscou a Baalins.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 4, 'Antes buscou ao Deus de seu pai, andou nos seus mandamentos, e não segundo as obras de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 5, 'E o Senhor confirmou o reino na sua mão, e todo o Judá deu presentes a Jeosafá, o qual teve riquezas e glória em abundância.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 6, 'E exaltou-se o seu coração nos caminhos do Senhor e, ainda mais, tirou os altos e os bosques de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 7, 'E no terceiro ano do seu reinado enviou ele os seus príncipes, a Bene-Hail, a Obadias, a Zacarias, a Natanael e a Micaías, para ensinarem nas cidades de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 8, 'E com eles os levitas, Semaías, Netanias, Zebadias, Asael, Semiramote, Jônatas, Adonias, Tobias e Tobe-Adonias e, com estes levitas, os sacerdotes, Elisama e Jeorão.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 9, 'E ensinaram em Judá, levando consigo o livro da lei do Senhor; e foram a todas as cidades de Judá, ensinando entre o povo.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 10, 'E veio o temor do Senhor sobre todos os reinos das terras, que estavam ao redor de Judá, e não guerrearam contra Jeosafá.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 11, 'E alguns dentre os filisteus traziam presentes a Jeosafá, e prata como tributo; também os árabes lhe trouxeram gado miúdo; sete mil e setecentos carneiros, e sete mil e setecentos bodes.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 12, 'Cresceu, pois, Jeosafá grandemente em extremo e edificou fortalezas e cidades de provisões em Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 13, 'E teve muitas obras nas cidades de Judá, e homens de guerra e valentes, em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 14, 'E este é o número deles segundo as suas casas paternas; em Judá eram capitàes dos milhares: o chefe Adna, e com ele trezentos mil homens valentes;', 2, CURRENT_TIMESTAMP, false),
(14, 17, 15, 'E depois dele o capitão Joanã, e com ele duzentos e oitenta mil;', 2, CURRENT_TIMESTAMP, false),
(14, 17, 16, 'E depois Amasias, filho de Zicri, que voluntariamente se entregou ao Senhor, e com ele duzentos mil homens valentes;', 2, CURRENT_TIMESTAMP, false),
(14, 17, 17, 'E de Benjamim, Eliada, homem valente, e com ele duzentos mil, armados de arco e de escudo;', 2, CURRENT_TIMESTAMP, false),
(14, 17, 18, 'E depois dele Jozabade, e com ele cento e oitenta mil, armados para a guerra.', 2, CURRENT_TIMESTAMP, false),
(14, 17, 19, 'Estes estavam no serviço do rei; afora os que o rei tinha posto nas cidades fortes por todo o Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 1, 'Tinha, pois, Jeosafá riquezas e glória em abundância, e aparentou-se com Acabe.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 2, 'E depois de alguns anos desceu ele para Acabe em Samaria; e Acabe matou ovelhas e bois em abundância, para ele e para o povo que vinha com ele; e o persuadiu a subir com ele a Ramote de Gileade.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 3, 'Porque Acabe, rei de Israel, disse a Jeosafá, rei de Judá: Irás tu comigo a Ramote de Gileade? E ele lhe disse: Como tu és, serei eu; e o meu povo, como o teu povo; iremos contigo à guerra.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 4, 'Disse mais Jeosafá ao rei de Israel: Peço-te, consulta hoje a palavra do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 5, 'Então o rei de Israel reuniu os profetas, quatrocentos homens, e disse-lhes: Iremos à guerra contra Ramote de Gileade, ou deixarei de ir? E eles disseram: Sobe; porque Deus a entregará na mão do rei.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 6, 'Disse, porém, Jeosafá: Não há ainda aqui algum profeta do Senhor, para que o consultemos?', 2, CURRENT_TIMESTAMP, false),
(14, 18, 7, 'Então o rei de Israel disse a Jeosafá: Ainda há um homem por quem podemos consultar ao Senhor; porém eu o odeio, porque nunca profetiza de mim o que é bom, senão sempre o mal; este é Micaías, filho de Inlá. E disse Jeosafá: Não fale o rei assim.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 8, 'Então o rei de Israel chamou um oficial, e disse: Traze aqui depressa a Micaías, filho de Inlá.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 9, 'E o rei de Israel, e Jeosafá, rei de Judá, estavam assentados cada um no seu trono, vestidos com suas roupas reais, e estavam assentados na praça à entrada da porta de Samaria; e todos os profetas profetizavam na sua presença.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 10, 'E Zedequias, filho de Quenaaná, fez para si uns chifres de ferro, e disse: Assim diz o Senhor: Com estes ferirás aos sírios, até de todo os consumires.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 11, 'E todos os profetas profetizavam o mesmo, dizendo: Sobe a Ramote de Gileade, e triunfarás; porque o Senhor a dará na mão do rei.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 12, 'E o mensageiro, que foi chamar a Micaías, falou-lhe, dizendo: Eis que as palavras dos profetas, a uma voz, predizem coisas boas para o rei; seja, pois, também a tua palavra como a de um deles, e fala o que é bom.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 13, 'Porém Micaías disse: Vive o Senhor, que o que meu Deus me disser, isso falarei.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 14, 'Vindo, pois, ele ao rei, este lhe disse: Micaías, iremos a Ramote de Gileade à guerra, ou deixaremos de ir? E ele disse: Subi, e triunfarás; e serão dados na vossa mão.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 15, 'E o rei lhe disse: Até quantas vezes, te conjurarei, para que não me fales senão a verdade em nome do Senhor?', 2, CURRENT_TIMESTAMP, false),
(14, 18, 16, 'Então disse ele: Vi a todo o Israel disperso pelos montes, como ovelhas que não têm pastor; e disse o SENHOR: Estes não têm senhor; torne cada um em paz para sua casa.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 17, 'Então o rei de Israel disse a Jeosafá: Não te disse eu, que ele não profetizaria de mim o que é bom, porém sempre o mal?', 2, CURRENT_TIMESTAMP, false),
(14, 18, 18, 'Disse mais: Ouvi, pois, a palavra do Senhor: Vi ao Senhor assentado no seu trono, e todo o exército celestial em pé à sua mão direita, e à sua esquerda.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 19, 'E disse o Senhor: Quem persuadirá a Acabe rei de Israel, para que suba, e caia em Ramote de Gileade? Um dizia desta maneira, e outro de outra.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 20, 'Então saiu um espírito e se apresentou diante do Senhor, e disse: Eu o persuadirei. E o Senhor lhe disse: Com quê?', 2, CURRENT_TIMESTAMP, false),
(14, 18, 21, 'E ele disse: Eu sairei, e serei um espírito de mentira na boca de todos os seus profetas. E disse o Senhor: Tu o persuadirás, e ainda prevalecerás; sai, e faze-o assim.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 22, 'Agora, pois, eis que o Senhor pôs um espírito de mentira na boca destes teus profetas; e o Senhor falou o mal a teu respeito.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 23, 'Então Zedequias, filho de Quenaaná, chegando-se, feriu a Micaías no queixo, e disse: Por que caminho passou de mim o Espírito do Senhor para falar a ti?', 2, CURRENT_TIMESTAMP, false),
(14, 18, 24, 'E disse Micaías: Eis que o verás naquele dia, quando andares de câmara em câmara, para te esconderes.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 25, 'Então disse o rei de Israel: Tomai a Micaías, e tornai a levá-lo a Amom, o governador da cidade, e a Joás, filho do rei.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 26, 'E direis: Assim diz o rei: Colocai este homem na casa do cárcere; e sustentai-o com pão de angústia, e com água de angústia, até que eu volte em paz.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 27, 'E disse Micaías: Se voltares em paz, o Senhor não tem falado por mim. Disse mais: Ouvi, povos todos!', 2, CURRENT_TIMESTAMP, false),
(14, 18, 28, 'Subiram, pois, o rei de Israel e Jeosafá, rei de Judá, a Ramote de Gileade.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 29, 'E disse o rei de Israel a Jeosafá: Disfarçando-me eu, então entrarei na peleja; tu, porém, veste as tuas roupas reais. Disfarçou-se, pois, o rei de Israel, e entraram na peleja.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 30, 'Deu ordem, porém, o rei da Síria aos capitães dos carros que tinha, dizendo: Não pelejareis nem contra pequeno, nem contra grande; senão só contra o rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 31, 'Sucedeu que, vendo os capitães dos carros a Jeosafá, disseram: Este é o rei de Israel, e o cercaram para pelejar; porém Jeosafá clamou, e o Senhor o ajudou. E Deus os desviou dele.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 32, 'Porque sucedeu que, vendo os capitães dos carros, que não era o rei de Israel, deixaram de segui-lo.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 33, 'Então um homem armou o arco e atirou a esmo, e feriu o rei de Israel entre as junturas e a couraça; então disse ao carreteiro: Dá volta, e tira-me do exército, porque estou gravemente ferido.', 2, CURRENT_TIMESTAMP, false),
(14, 18, 34, 'E aquele dia cresceu a peleja, mas o rei de Israel susteve-se em pé no carro defronte dos sírios até à tarde; e morreu ao tempo do pôr do sol.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 1, 'E Jeosafá, rei de Judá, voltou em paz à sua casa em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 2, 'E Jeú, filho de Hanani, o vidente, saiu ao encontro do rei Jeosafá e lhe disse: Devias tu ajudar ao ímpio, e amar aqueles que odeiam ao Senhor? Por isso virá sobre ti grande ira da parte do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 3, 'Boas coisas contudo se acharam em ti; porque tiraste os bosques da terra, e preparaste o teu coração para buscar a Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 4, 'Habitou, pois, Jeosafá em Jerusalém; e tornou a passar pelo povo desde Berseba até as montanhas de Efraim, e fez com que tornassem ao Senhor Deus de seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 5, 'E estabeleceu juízes na terra, em todas as cidades fortificadas, de cidade em cidade.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 6, 'E disse aos juízes: Vede o que fazeis; porque não julgais da parte do homem, senão da parte do Senhor, e ele está convosco quando julgardes.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 7, 'Agora, pois, seja o temor do Senhor convosco; guardai-o, e fazei-o; porque não há no Senhor nosso Deus iniqüidade nem acepção de pessoas, nem aceitação de suborno.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 8, 'E também estabeleceu Jeosafá a alguns dos levitas e dos sacerdotes e dos chefes dos pais de Israel sobre o juízo do Senhor, e sobre as causas judiciais; e voltaram a Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 9, 'E deu-lhes ordem, dizendo: Assim fazei no temor do Senhor, com fidelidade, e com coração íntegro.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 10, 'E em toda a diferença que vier a vós de vossos irmãos que habitam nas suas cidades, entre sangue e sangue, entre lei e mandamento, entre estatutos e juízos, admoestai-os, que não se façam culpados para com o Senhor, e não venha grande ira sobre vós, e sobre vossos irmãos; fazei assim, e não vos fareis culpados.', 2, CURRENT_TIMESTAMP, false),
(14, 19, 11, 'E eis que Amarias, o sumo sacerdote, presidirá sobre vós em todo o negócio do Senhor; e Zebadias, filho de Ismael, líder da casa de Judá, em todo o negócio do rei; também os oficiais, os levitas, estão perante vós; esforçai-vos, pois, e fazei-o; e o Senhor será com os bons.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 1, 'E sucedeu que, depois disto, os filhos de Moabe, e os filhos de Amom, e com eles outros dos amonitas, vieram à peleja contra Jeosafá.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 2, 'Então vieram alguns que avisaram a Jeosafá, dizendo: Vem contra ti uma grande multidão dalém do mar e da Síria; e eis que já estão em Hazazom-Tamar, que é En-Gedi.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 3, 'Então Jeosafá temeu, e pôs-se a buscar o Senhor, e apregoou jejum em todo o Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 4, 'E Judá se ajuntou, para pedir socorro ao Senhor; também de todas as cidades de Judá vieram para buscar ao Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 5, 'E pôs-se Jeosafá em pé na congregação de Judá e de Jerusalém, na casa do Senhor, diante do pátio novo.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 6, 'E disse: Ah! Senhor Deus de nossos pais, porventura não és tu Deus nos céus? Não és tu que dominas sobre todos os reinos das nações? Na tua mão há força e potência, e não há quem te possa resistir.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 7, 'Porventura, ó nosso Deus, não lançaste fora os moradores desta terra de diante do teu povo Israel, e não a deste para sempre à descendência de Abraão, teu amigo?', 2, CURRENT_TIMESTAMP, false),
(14, 20, 8, 'E habitaram nela e edificaram-te nela um santuário ao teu nome, dizendo:', 2, CURRENT_TIMESTAMP, false),
(14, 20, 9, 'Se algum mal nos sobrevier, espada, juízo, peste, ou fome, nós nos apresentaremos diante desta casa e diante de ti, pois teu nome está nesta casa, e clamaremos a ti na nossa angústia, e tu nos ouvirás e livrarás.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 10, 'Agora, pois, eis que os filhos de Amom, e de Moabe e os das montanhas de Seir, pelos quais não permitiste passar a Israel, quando vinham da terra do Egito, mas deles se desviaram e não os destruíram,', 2, CURRENT_TIMESTAMP, false),
(14, 20, 11, 'Eis que nos dão o pago, vindo para lançar-nos fora da tua herança, que nos fizeste herdar.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 12, 'Ah! nosso Deus, porventura não os julgarás? Porque em nós não há força perante esta grande multidão que vem contra nós, e não sabemos o que faremos; porém os nossos olhos estão postos em ti.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 13, 'E todo o Judá estava em pé perante o Senhor, como também as suas crianças, as suas mulheres, e os seus filhos.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 14, 'Então veio o Espírito do Senhor, no meio da congregação, sobre Jaaziel, filho de Zacarias, filho de Benaia, filho de Jeiel, filho de Matanias, levita, dos filhos de Asafe,', 2, CURRENT_TIMESTAMP, false),
(14, 20, 15, 'E disse: Dai ouvidos todo o Judá, e vós, moradores de Jerusalém, e tu, ó rei Jeosafá; assim o Senhor vos diz: Não temais, nem vos assusteis por causa desta grande multidão; pois a peleja não é vossa, mas de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 16, 'Amanhã descereis contra eles; eis que sobem pela ladeira de Ziz, e os achareis no fim do vale, diante do deserto de Jeruel.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 17, 'Nesta batalha não tereis que pelejar; postai-vos, ficai parados, e vede a salvação do Senhor para convosco, ó Judá e Jerusalém. Não temais, nem vos assusteis; amanhã saí-lhes ao encontro, porque o Senhor será convosco.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 18, 'Então Jeosafá se prostrou com o rosto em terra, e todo o Judá e os moradores de Jerusalém se lançaram perante o Senhor, adorando-o.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 19, 'E levantaram-se os levitas, dos filhos dos coatitas, e dos filhos dos coratitas, para louvarem ao Senhor Deus de Israel, com voz muito alta.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 20, 'E pela manhã cedo se levantaram e saíram ao deserto de Tecoa; e, ao saírem, Jeosafá pôs-se em pé, e disse: Ouvi-me, ó Judá, e vós, moradores de Jerusalém: Crede no Senhor vosso Deus, e estareis seguros; crede nos seus profetas, e prosperareis;', 2, CURRENT_TIMESTAMP, false),
(14, 20, 21, 'E aconselhou-se com o povo, e ordenou cantores para o Senhor, que louvassem à Majestade santa, saindo diante dos armados, e dizendo: Louvai ao Senhor porque a sua benignidade dura para sempre.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 22, 'E, quando começaram a cantar e a dar louvores, o Senhor pôs emboscadas contra os filhos de Amom e de Moabe e os das montanhas de Seir, que vieram contra Judá, e foram desbaratados.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 23, 'Porque os filhos de Amom e de Moabe se levantaram contra os moradores das montanhas de Seir, para os destruir e exterminar; e, acabando eles com os moradores de Seir, ajudaram uns aos outros a destruir-se.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 24, 'Nisso chegou Judá à atalaia do deserto; e olharam para a multidão, e eis que eram corpos mortos, que jaziam em terra, e nenhum escapou.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 25, 'E vieram Jeosafá e o seu povo para saquear os seus despojos, e acharam entre eles riquezas e cadáveres em abundância, assim como objetos preciosos; e tomaram para si tanto, que não podiam levar; e três dias saquearam o despojo, porque era muito.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 26, 'E ao quarto dia se ajuntaram no vale de Beraca; pois ali louvaram ao Senhor. Por isso chamaram aquele lugar o vale de Beraca, até ao dia de hoje.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 27, 'Então voltaram todos os homens de Judá e de Jerusalém, e Jeosafá à frente deles, e tornaram a Jerusalém com alegria; porque o Senhor os alegrara sobre os seus inimigos.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 28, 'E vieram a Jerusalém com saltérios, com harpas e com trombetas, para a casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 29, 'E veio o temor de Deus sobre todos os reinos daquelas terras, ouvindo eles que o Senhor havia pelejado contra os inimigos de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 30, 'E o reino de Jeosafá ficou quieto; e o seu Deus lhe deu repouso ao redor.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 31, 'E Jeosafá reinou sobre Judá; era da idade de trinta e cinco anos quando começou a reinar e vinte e cinco anos reinou em Jerusalém; e o nome de sua mãe era Azuba, filha de Sili.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 32, 'E andou no caminho de Asa, seu pai, e não se desviou dele, fazendo o que era reto aos olhos do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 33, 'Contudo os altos não foram tirados porque o povo não tinha ainda disposto o seu coração para com o Deus de seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 34, 'Ora, o restante dos atos de Jeosafá, assim, desde os primeiros até os últimos, eis que está escrito nas notas de Jeú, filho de Hanani, que as inseriu no livro dos reis de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 35, 'Porém, depois disto, Jeosafá, rei de Judá, se aliou com Acazias, rei de Israel, que procedeu com toda a impiedade.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 36, 'E aliou-se com ele, para fazerem navios que fossem a Társis; e fizeram os navios em Eziom-Geber.', 2, CURRENT_TIMESTAMP, false),
(14, 20, 37, 'Porém Eliezer, filho de Dodava, de Maressa, profetizou contra Jeosafá, dizendo: Porquanto te aliaste com Acazias, o Senhor despedaçou as tuas obras. E os navios se quebraram, e não puderam ir a Társis.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 1, 'Depois Jeosafá dormiu com seus pais, e foi sepultado junto a eles na cidade de Davi; e Jeorão, seu filho, reinou em seu lugar.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 2, 'E teve irmãos, filhos de Jeosafá: Azarias, Jeiel, Zacarias, Asarias, Micael e Sefatias; todos estes foram filhos de Jeosafá, rei de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 3, 'E seu pai lhes deu muitos presentes de prata, de ouro e de coisas preciosíssimas, juntamente com cidades fortificadas em Judá; porém, o reino, deu a Jeorão, porquanto era o primogênito.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 4, 'E, subindo Jeorão ao reino de seu pai, e havendo-se fortificado, matou a todos os seus irmãos à espada, como também a alguns dos príncipes de Israel.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 5, 'Da idade de trinta e dois anos era Jeorão, quando começou a reinar; e reinou oito anos em Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 6, 'E andou no caminho dos reis de Israel, como fazia a casa de Acabe; porque tinha a filha de Acabe por mulher; e fazia o que era mau aos olhos do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 7, 'Porém o Senhor não quis destruir a casa de Davi, em atenção à aliança que tinha feito com Davi; e porque também tinha falado que lhe daria por todos os dias uma lâmpada, a ele e a seus filhos.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 8, 'Nos seus dias se revoltaram os edomitas contra o mando de Judá, e constituíram para si um rei.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 9, 'Por isso Jeorão passou adiante com os seus príncipes, e todos os carros com ele; levantou-se de noite, e feriu aos edomeus, que o tinham cercado, como também aos capitães dos carros.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 10, 'Todavia os edomitas se revoltaram contra o mando de Judá até ao dia de hoje; então no mesmo tempo Libna se revoltou contra o seu mando; porque deixara ao Senhor Deus de seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 11, 'Ele também fez altos nos montes de Judá; e fez com que se corrompessem os moradores de Jerusalém, e até a Judá impeliu a isso.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 12, 'Então lhe veio um escrito da parte de Elias, o profeta, que dizia: Assim diz o Senhor Deus de Davi teu pai: Porquanto não andaste nos caminhos de Jeosafá, teu pai, e nos caminhos de Asa, rei de Judá,', 2, CURRENT_TIMESTAMP, false),
(14, 21, 13, 'Mas andaste no caminho dos reis de Israel, e fizeste prostituir a Judá e aos moradores de Jerusalém, segundo a prostituição da casa de Acabe, e também mataste a teus irmãos da casa de teu pai, melhores do que tu;', 2, CURRENT_TIMESTAMP, false),
(14, 21, 14, 'Eis que o Senhor ferirá com um grande flagelo ao teu povo, aos teus filhos, às tuas mulheres e a todas as tuas fazendas.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 15, 'Tu também terás grande enfermidade por causa de uma doença em tuas entranhas, até que elas saiam, de dia em dia, por causa do mal.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 16, 'Despertou, pois, o Senhor, contra Jeorão o espírito dos filisteus e dos árabes, que estavam do lado dos etíopes.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 17, 'Estes subiram a Judá, e deram sobre ela, e levaram todos os bens que se achou na casa do rei, como também a seus filhos e a suas mulheres; de modo que não lhe deixaram filho algum, senão a Jeoacaz, o mais moço de seus filhos.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 18, 'E depois de tudo isto o Senhor o feriu nas suas entranhas com uma enfermidade incurável.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 19, 'E sucedeu que, depois de muito tempo, ao fim de dois anos, saíram-lhe as entranhas por causa da doença; e morreu daquela grave enfermidade; e o seu povo não lhe queimou aroma como queimara a seus pais.', 2, CURRENT_TIMESTAMP, false),
(14, 21, 20, 'Era da idade de trinta e dois anos quando começou a reinar, e reinou oito anos em Jerusalém; e foi sem deixar de si saudades; e sepultaram-no na cidade de Davi, porém não nos sepulcros dos reis.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 1, 'E os moradores de Jerusalém, em lugar de Jeorão, fizeram rei a Acazias, seu filho mais moço, porque a tropa, que viera com os árabes ao arraial, tinha matado a todos os mais velhos. Assim reinou Acazias, filho de Jeorão, rei de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 2, 'Era da idade de quarenta e dois anos, quando começou a reinar, e reinou um ano em Jerusalém; e era o nome de sua mãe Atalia, filha de Onri.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 3, 'Também ele andou nos caminhos da casa de Acabe, porque sua mãe era sua conselheira, para proceder impiamente.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 4, 'E fez o que era mau aos olhos do Senhor, como a casa de Acabe, porque eles eram seus conselheiros depois da morte de seu pai, para a sua perdição.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 5, 'Também andou nos conselhos deles, e foi com Jorão, filho de Acabe, rei de Israel, à peleja contra Hazael, rei da Síria, junto a Ramote de Gileade; e os sírios feriram a Jorão.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 6, 'E voltou para curar-se em Jizreel, das feridas que lhe fizeram em Ramá, pelejando contra Hazael, rei da Síria; e Acazias, filho de Jeorão, rei de Judá, desceu para ver a Jorão, filho de Acabe, em Jizreel, porque estava doente.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 7, 'Foi, pois, da vontade de Deus, que Acazias, para sua ruína, visitasse Jorão; porque chegando ele, saiu com Jorão contra Jeú, filho de Ninsi, a quem o Senhor tinha ungido para desarraigar a casa de Acabe.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 8, 'E sucedeu que, executando Jeú juízo contra a casa de Acabe, achou os príncipes de Judá e os filhos dos irmãos de Acazias, que serviam a Acazias, e os matou.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 9, 'Depois buscou a Acazias (porque se tinha escondido em Samaria), e o alcançaram, e o trouxeram a Jeú, e o mataram, e o sepultaram; porque disseram: Filho é de Jeosafá, que buscou ao Senhor com todo o seu coração. E já não tinha a casa de Acazias ninguém que tivesse força para o reino.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 10, 'Vendo, pois, Atalia, mãe de Acazias, que seu filho era morto, levantou-se e destruiu toda a descendência real da casa de Judá.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 11, 'Porém Jeosabeate, filha do rei, tomou a Joás, filho de Acazias, furtando-o dentre os filhos do rei, aos quais matavam, e o pôs com a sua ama na câmara dos leitos; assim Jeosabeate, filha do rei Jeorão, mulher do sacerdote Joiada (porque era irmã de Acazias), o escondeu de Atalia, de modo que ela não o matou.', 2, CURRENT_TIMESTAMP, false),
(14, 22, 12, 'E esteve com eles seis anos escondido na casa de Deus; e Atalia reinou sobre a terra.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 1, 'Porém no sétimo ano Joiada se animou, e tomou consigo em aliança os chefes de cem, a Azarias, filho de Jeroão, a Ismael, filho de Joanã, a Azarias, filho de Obede, a Maaséias, filho de Adaías, e a Elisafate, filho de Zicri.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 2, 'Estes percorreram a Judá e ajuntaram os levitas de todas as cidades de Judá e os chefes dos pais de Israel, e vieram para Jerusalém.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 3, 'E toda aquela congregação fez aliança com o rei na casa de Deus; e Joiada lhes disse: Eis que o filho do rei reinará, como o Senhor falou a respeito dos filhos de Davi.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 4, 'Isto é o que haveis de fazer; uma terça parte de vós, ou seja, dos sacerdotes e dos levitas que entram no sábado, serão guardas das portas;', 2, CURRENT_TIMESTAMP, false),
(14, 23, 5, 'E uma terça parte estará na casa do rei; e a outra terça parte à porta do fundamento; e todo o povo estará nos pátios da casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 6, 'Porém ninguém entre na casa do Senhor, senão os sacerdotes e os levitas que ministram; estes entrarão, porque são santos; mas todo o povo fará a guarda diante do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 7, 'E os levitas cercarão o rei de todos os lados, cada um com as suas armas na mão; e qualquer que entrar na casa será morto; porém vós estareis com o rei, quando entrar e quando sair.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 8, 'E fizeram os levitas e todo o Judá conforme a tudo o que ordenara o sacerdote Joiada; e tomou cada um os seus homens, tanto os que entravam no sábado como os que saíam no sábado; porque o sacerdote Joiada não tinha despedido as turmas.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 9, 'Também o sacerdote Joiada deu aos capitàes de cem as lanças, os escudos e as rodelas que foram do rei Davi, os quais estavam na casa de Deus.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 10, 'E dispôs todo o povo, a cada um com as suas armas na mão, desde o lado direito da casa até o lado esquerdo da casa, do lado do altar e da casa, em redor do rei.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 11, 'Então tiraram para fora ao filho do rei, e lhe puseram a coroa; deram-lhe o testemunho, e o fizeram rei; e Joiada e seus filhos o ungiram, e disseram: Viva o rei!', 2, CURRENT_TIMESTAMP, false),
(14, 23, 12, 'Ouvindo, pois, Atalia a voz do povo que concorria e louvava o rei, veio ao povo, à casa do Senhor.', 2, CURRENT_TIMESTAMP, false),
(14, 23, 13, 'E olhou, e eis que o rei estava junto à coluna, à entrada, e os priINSERT INTO versiculos (livro, capitulo, numero, texto, traducao_id, data_criacao, deletado) VALUES
(46, 1, 1, 'Paulo, chamado para ser apóstolo de Cristo Jesus pela vontade de Deus, e o irmão Sóstenes,', 3, CURRENT_TIMESTAMP, false),
(46, 1, 2, 'à igreja de Deus que está em Corinto, aos santificados em Cristo Jesus e chamados para serem santos, juntamente com todos os que, em toda parte, invocam o nome de nosso Senhor Jesus Cristo, Senhor deles e nosso:', 3, CURRENT_TIMESTAMP, false),
(46, 1, 3, 'A vocês, graça e paz da parte de Deus nosso Pai e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 4, 'Sempre dou graças a meu Deus por vocês, por causa da graça que lhes foi dada por ele em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 5, 'Pois nele vocês foram enriquecidos em tudo, em toda palavra e em todo conhecimento,', 3, CURRENT_TIMESTAMP, false),
(46, 1, 6, 'porque o testemunho de Cristo foi confirmado entre vocês,', 3, CURRENT_TIMESTAMP, false),
(46, 1, 7, 'de modo que não lhes falta nenhum dom espiritual, enquanto vocês aguardam que o nosso Senhor Jesus Cristo seja revelado.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 8, 'Ele os manterá firmes até o fim, de modo que vocês serão irrepreensíveis no dia de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 9, 'Fiel é Deus, o qual os chamou à comunhão com seu Filho Jesus Cristo, nosso Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 10, 'Irmãos, em nome de nosso Senhor Jesus Cristo suplico a todos vocês que concordem uns com os outros no que falam, para que não haja divisões entre vocês, e, sim, que todos estejam unidos num só pensamento e num só parecer.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 11, 'Meus irmãos, fui informado por alguns da casa de Cloe de que há divisões entre vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 12, 'Com isso quero dizer que cada um de vocês afirma: "Eu sou de Paulo"; "eu de Apolo"; "eu de Pedro"; e "eu de Cristo".', 3, CURRENT_TIMESTAMP, false),
(46, 1, 13, 'Acaso Cristo está dividido? Foi Paulo crucificado em favor de vocês? Foram vocês batizados em nome de Paulo?', 3, CURRENT_TIMESTAMP, false),
(46, 1, 14, 'Dou graças a Deus por não ter batizado nenhum de vocês, exceto Crispo e Gaio;', 3, CURRENT_TIMESTAMP, false),
(46, 1, 15, 'de modo que ninguém pode dizer que foi batizado em meu nome.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 16, '( Batizei também os da casa de Estéfanas; além destes, não me lembro se batizei alguém mais. )', 3, CURRENT_TIMESTAMP, false),
(46, 1, 17, 'Pois Cristo não me enviou para batizar, mas para pregar o evangelho, não com palavras de sabedoria humana, para que a cruz de Cristo não seja esvaziada. Cristo, Sabedoria e Poder de Deus', 3, CURRENT_TIMESTAMP, false),
(46, 1, 18, 'Pois a mensagem da cruz é loucura para os que estão perecendo, mas para nós, que estamos sendo salvos, é o poder de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 19, 'Pois está escrito: "Destruirei a sabedoria dos sábios e rejeitarei a inteligência dos inteligentes".', 3, CURRENT_TIMESTAMP, false),
(46, 1, 20, 'Onde está o sábio? Onde está o erudito? Onde está o questionador desta era? Acaso não tornou Deus louca a sabedoria deste mundo?', 3, CURRENT_TIMESTAMP, false),
(46, 1, 21, 'Visto que, na sabedoria de Deus, o mundo não o conheceu por meio da sabedoria humana, agradou a Deus salvar aqueles que crêem por meio da loucura da pregação.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 22, 'Os judeus pedem sinais miraculosos, e os gregos procuram sabedoria;', 3, CURRENT_TIMESTAMP, false),
(46, 1, 23, 'nós, porém, pregamos a Cristo crucificado, o qual, de fato, é escândalo para os judeus e loucura para os gentios', 3, CURRENT_TIMESTAMP, false),
(46, 1, 24, 'mas para os que foram chamados, tanto judeus como gregos, Cristo é o poder de Deus e a sabedoria de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 25, 'Porque a loucura de Deus é mais sábia que a sabedoria humana, e a fraqueza de Deus é mais forte que a força do homem.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 26, 'Irmãos, pensem no que vocês eram quando foram chamados. Poucos eram sábios segundo os padrões humanos; poucos eram poderosos; poucos eram de nobre nascimento.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 27, 'Mas Deus escolheu as coisas loucas do mundo para envergonhar os sábios, e escolheu as coisas fracas do mundo para envergonhar as fortes.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 28, 'Ele escolheu as coisas insignificantes do mundo, as desprezadas e as que nada são, para reduzir a nada as que são,', 3, CURRENT_TIMESTAMP, false),
(46, 1, 29, 'para que ninguém se vanglorie diante dele.', 3, CURRENT_TIMESTAMP, false),
(46, 1, 30, 'É, porém, por iniciativa dele que vocês estão em Cristo Jesus, o qual se tornou sabedoria de Deus para nós, isto é, justiça, santidade e redenção,', 3, CURRENT_TIMESTAMP, false),
(46, 1, 31, 'para que, como está escrito: "Quem se gloriar, glorie-se no Senhor".', 3, CURRENT_TIMESTAMP, false),
(46, 2, 1, 'Eu mesmo, irmãos, quando estive entre vocês, não fui com discurso eloqüente nem com muita sabedoria para lhes proclamar o mistério de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 2, 'Pois decidi nada saber entre vocês, a não ser Jesus Cristo, e este, crucificado.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 3, 'E foi com fraqueza, temor e com muito tremor que estive entre vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 4, 'Minha mensagem e minha pregação não consistiram de palavras persuasivas de sabedoria, mas consistiram de demonstração do poder do Espírito,', 3, CURRENT_TIMESTAMP, false),
(46, 2, 5, 'para que a fé que vocês têm não se baseasse na sabedoria humana, mas no poder de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 6, 'Entretanto, falamos de sabedoria entre os maduros, mas não da sabedoria desta era ou dos poderosos desta era, que estão sendo reduzidos a nada.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 7, 'Pelo contrário, falamos da sabedoria de Deus, do mistério que estava oculto, o qual Deus preordenou, antes do princípio das eras, para a nossa glória.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 8, 'Nenhum dos poderosos desta era o entendeu, pois, se o tivessem entendido, não teriam crucificado o Senhor da glória.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 9, 'Todavia, como está escrito: "Olho nenhum viu, ouvido nenhum ouviu, mente nenhuma imaginou o que Deus preparou para aqueles que o amam";', 3, CURRENT_TIMESTAMP, false),
(46, 2, 10, 'mas Deus o revelou a nós por meio do Espírito. O Espírito sonda todas as coisas, até mesmo as coisas mais profundas de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 11, 'Pois, quem dentre os homens conhece as coisas do homem, a não ser o espírito do homem que nele está? Da mesma forma, ninguém conhece as coisas de Deus, a não ser o Espírito de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 12, 'Nós, porém, não recebemos o espírito do mundo, mas o Espírito procedente de Deus, para que entendamos as coisas que Deus nos tem dado gratuitamente.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 13, 'Delas também falamos, não com palavras ensinadas pela sabedoria humana, mas com palavras ensinadas pelo Espírito, interpretando verdades espirituais para os que são espirituais.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 14, 'Quem não tem o Espírito não aceita as coisas que vêm do Espírito de Deus, pois lhe são loucura; e não é capaz de entendê-las, porque elas são discernidas espiritualmente.', 3, CURRENT_TIMESTAMP, false),
(46, 2, 15, 'Mas quem é espiritual discerne todas as coisas, e ele mesmo por ninguém é discernido; pois', 3, CURRENT_TIMESTAMP, false),
(46, 2, 16, '"quem conheceu a mente do Senhor para que possa instruí-lo? " Nós, porém, temos a mente de Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 1, 'Irmãos, não lhes pude falar como a espirituais, mas como a carnais, como a crianças em Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 2, 'Dei-lhes leite, e não alimento sólido, pois vocês não estavam em condições de recebê-lo. De fato, vocês ainda não estão em condições,', 3, CURRENT_TIMESTAMP, false),
(46, 3, 3, 'porque ainda são carnais. Porque, visto que há inveja e divisão entre vocês, não estão sendo carnais e agindo como mundanos?', 3, CURRENT_TIMESTAMP, false),
(46, 3, 4, 'Pois quando alguém diz: "Eu sou de Paulo", e outro: "Eu sou de Apolo", não estão sendo mundanos?', 3, CURRENT_TIMESTAMP, false),
(46, 3, 5, 'Afinal de contas, quem é Apolo? Quem é Paulo? Apenas servos por meio dos quais vocês vieram a crer, conforme o ministério que o Senhor atribuiu a cada um.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 6, 'Eu plantei, Apolo regou, mas Deus é quem fazia crescer;', 3, CURRENT_TIMESTAMP, false),
(46, 3, 7, 'de modo que nem o que planta nem o que rega são alguma coisa, mas unicamente Deus, que efetua o crescimento.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 8, 'O que planta e o que rega têm um só propósito, e cada um será recompensado de acordo com o seu próprio trabalho.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 9, 'Pois nós somos cooperadores de Deus; vocês são lavoura de Deus e edifício de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 10, 'Conforme a graça de Deus que me foi concedida, eu, como sábio construtor, lancei o alicerce, e outro está construindo sobre ele. Contudo, veja cada um como constrói.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 11, 'Porque ninguém pode colocar outro alicerce além do que já está posto, que é Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 12, 'Se alguém constrói sobre esse alicerce, usando ouro, prata, pedras preciosas, madeira, feno ou palha,', 3, CURRENT_TIMESTAMP, false),
(46, 3, 13, 'sua obra será mostrada, porque o Dia a trará à luz; pois será revelada pelo fogo, que provará a qualidade da obra de cada um.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 14, 'Se o que alguém construiu permanecer, esse receberá recompensa.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 15, 'Se o que alguém construiu se queimar, esse sofrerá prejuízo; contudo, será salvo como alguém que escapa através do fogo.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 16, 'Vocês não sabem que são santuário de Deus e que o Espírito de Deus habita em vocês?', 3, CURRENT_TIMESTAMP, false),
(46, 3, 17, 'Se alguém destruir o santuário de Deus, Deus o destruirá; pois o santuário de Deus, que são vocês, é sagrado.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 18, 'Não se enganem. Se algum de vocês pensa que é sábio segundo os padrões desta era, deve tornar-se "louco" para que se torne sábio.', 3, CURRENT_TIMESTAMP, false),
(46, 3, 19, 'Porque a sabedoria deste mundo é loucura aos olhos de Deus. Pois está escrito: "Ele apanha os sábios na astúcia deles";', 3, CURRENT_TIMESTAMP, false),
(46, 3, 20, 'e também: "O Senhor conhece os pensamentos dos sábios e sabe como são fúteis".', 3, CURRENT_TIMESTAMP, false),
(46, 3, 21, 'Portanto, ninguém se glorie em homens; porque todas as coisas são de vocês,', 3, CURRENT_TIMESTAMP, false),
(46, 3, 22, 'seja Paulo, seja Apolo, seja Pedro, seja o mundo, a vida, a morte, o presente ou o futuro; tudo é de vocês,', 3, CURRENT_TIMESTAMP, false),
(46, 3, 23, 'e vocês são de Cristo, e Cristo, de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 1, 'Portanto, que todos nos considerem como servos de Cristo e encarregados dos mistérios de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 2, 'O que se requer destes encarregados é que sejam fiéis.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 3, 'Pouco me importa ser julgado por vocês ou por qualquer tribunal humano; de fato, nem eu julgo a mim mesmo.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 4, 'Embora em nada minha consciência me acuse, nem por isso justifico a mim mesmo; o Senhor é quem me julga.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 5, 'Portanto, não julguem nada antes da hora devida; esperem até que o Senhor venha. Ele trará à luz o que está oculto nas trevas e manifestará as intenções dos corações. Nessa ocasião, cada um receberá de Deus a sua aprovação.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 6, 'Irmãos, apliquei essas coisas a mim e a Apolo por amor a vocês, para que aprendam de nós o que significa: "Não ultrapassem o que está escrito". Assim, ninguém se orgulhe a favor de um homem em detrimento de outro.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 7, 'Pois, quem torna você diferente de qualquer outra pessoa? O que você tem que não tenha recebido? E se o recebeu, por que se orgulha, como se assim não fosse?', 3, CURRENT_TIMESTAMP, false),
(46, 4, 8, 'Vocês já têm tudo o que querem! Já se tornaram ricos! Chegaram a ser reis — e sem nós! Como eu gostaria que vocês realmente fossem reis, para que nós também reinássemos com vocês!', 3, CURRENT_TIMESTAMP, false),
(46, 4, 9, 'Porque me parece que Deus nos colocou a nós, os apóstolos, em último lugar, como condenados à morte. Temo-nos tornado um espetáculo para o mundo, tanto diante de anjos como de homens.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 10, 'Nós somos loucos por causa de Cristo, mas vocês são sensatos em Cristo! Nós somos fracos, mas vocês são fortes! Vocês são respeitados, mas nós somos desprezados!', 3, CURRENT_TIMESTAMP, false),
(46, 4, 11, 'Até agora estamos passando fome, sede e necessidade de roupas, estamos sendo tratados brutalmente, não temos residência certa e', 3, CURRENT_TIMESTAMP, false),
(46, 4, 12, 'trabalhamos arduamente com nossas próprias mãos. Quando somos amaldiçoados, abençoamos; quando perseguidos, suportamos;', 3, CURRENT_TIMESTAMP, false),
(46, 4, 13, 'quando caluniados, respondemos amavelmente. Até agora nos tornamos a escória da terra, o lixo do mundo.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 14, 'Não estou tentando envergonhá-los ao escrever estas coisas, mas procuro adverti-los, como a meus filhos amados.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 15, 'Embora possam ter dez mil tutores em Cristo, vocês não têm muitos pais, pois em Cristo Jesus eu mesmo os gerei por meio do evangelho.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 16, 'Portanto, suplico-lhes que sejam meus imitadores.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 17, 'Por essa razão estou lhes enviando Timóteo, meu filho amado e fiel no Senhor, o qual lhes trará à lembrança a minha maneira de viver em Cristo Jesus, de acordo com o que eu ensino por toda parte, em todas as igrejas.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 18, 'Alguns de vocês se tornaram arrogantes, como se eu não fosse mais visitá-los.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 19, 'Mas irei muito em breve, se o Senhor permitir; então saberei não apenas o que estão falando esses arrogantes, mas que poder eles têm.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 20, 'Pois o Reino de Deus não consiste de palavras, mas de poder.', 3, CURRENT_TIMESTAMP, false),
(46, 4, 21, 'Que é que vocês querem? Devo ir a vocês com vara, ou com amor e espírito de mansidão?', 3, CURRENT_TIMESTAMP, false),
(46, 5, 1, 'Por toda parte se ouve que há imoralidade entre vocês, imoralidade que não ocorre nem entre os pagãos, a ponto de alguém de vocês possuir a mulher de seu pai.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 2, 'E vocês estão orgulhosos! Não deviam, porém, estar cheios de tristeza e expulsar da comunhão aquele que fez isso?', 3, CURRENT_TIMESTAMP, false),
(46, 5, 3, 'Apesar de eu não estar presente fisicamente, estou com vocês em espírito. E já condenei aquele que fez isso, como se estivesse presente.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 4, 'Quando vocês estiverem reunidos em nome de nosso Senhor Jesus, estando eu com vocês em espírito, estando presente também o poder de nosso Senhor Jesus Cristo,', 3, CURRENT_TIMESTAMP, false),
(46, 5, 5, 'entreguem esse homem a Satanás, para que o corpo seja destruído, e seu espírito seja salvo no dia do Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 6, 'O orgulho de vocês não é bom. Vocês não sabem que um pouco de fermento faz toda a massa ficar fermentada?', 3, CURRENT_TIMESTAMP, false),
(46, 5, 7, 'Livrem-se do fermento velho, para que sejam massa nova e sem fermento, como realmente são. Pois Cristo, nosso Cordeiro pascal, foi sacrificado.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 8, 'Por isso, celebremos a festa, não com o fermento velho, nem com o fermento da maldade e da perversidade, mas com os pães sem fermento da sinceridade e da verdade.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 9, 'Já lhes disse por carta que vocês não devem associar-se com pessoas imorais.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 10, 'Com isso não me refiro aos imorais deste mundo, nem aos avarentos, aos ladrões ou aos idólatras. Se assim fosse, vocês precisariam sair deste mundo.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 11, 'Mas agora estou lhes escrevendo que não devem associar-se com qualquer que, dizendo-se irmão, seja imoral, avarento, idólatra, caluniador, alcoólatra ou ladrão. Com tais pessoas vocês nem devem comer.', 3, CURRENT_TIMESTAMP, false),
(46, 5, 12, 'Pois, como haveria eu de julgar os de fora da igreja? Não devem vocês julgar os que estão dentro?', 3, CURRENT_TIMESTAMP, false),
(46, 5, 13, 'Deus julgará os de fora. "Expulsem esse perverso do meio de vocês".', 3, CURRENT_TIMESTAMP, false),
(46, 6, 1, 'Se algum de vocês tem queixa contra outro irmão, como ousa apresentar a causa para ser julgada pelos ímpios, em vez de levá-la aos santos?', 3, CURRENT_TIMESTAMP, false),
(46, 6, 2, 'Vocês não sabem que os santos hão de julgar o mundo? Se vocês hão de julgar o mundo, acaso não são capazes de julgar as causas de menor importância?', 3, CURRENT_TIMESTAMP, false),
(46, 6, 3, 'Vocês não sabem que haveremos de julgar os anjos? Quanto mais as coisas desta vida!', 3, CURRENT_TIMESTAMP, false),
(46, 6, 4, 'Portanto, se vocês têm questões relativas às coisas desta vida, designem para juízes os que são da igreja, mesmo que sejam os menos importantes.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 5, 'Digo isso para envergonhá-los. Acaso não há entre vocês alguém suficientemente sábio para julgar uma causa entre irmãos?', 3, CURRENT_TIMESTAMP, false),
(46, 6, 6, 'Mas, ao invés disso, um irmão vai ao tribunal contra outro irmão, e isso diante de descrentes!', 3, CURRENT_TIMESTAMP, false),
(46, 6, 7, 'O fato de haver litígios entre vocês já significa uma completa derrota. Por que não preferem sofrer a injustiça? Por que não preferem sofrer o prejuízo?', 3, CURRENT_TIMESTAMP, false),
(46, 6, 8, 'Em vez disso vocês mesmos causam injustiças e prejuízos, e isso contra irmãos!', 3, CURRENT_TIMESTAMP, false),
(46, 6, 9, 'Vocês não sabem que os perversos não herdarão o Reino de Deus? Não se deixem enganar: nem imorais, nem idólatras, nem adúlteros, nem homossexuais passivos ou ativos,', 3, CURRENT_TIMESTAMP, false),
(46, 6, 10, 'nem ladrões, nem avarentos, nem alcoólatras, nem caluniadores, nem trapaceiros herdarão o Reino de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 11, 'Assim foram alguns de vocês. Mas vocês foram lavados, foram santificados, foram justificados no nome do Senhor Jesus Cristo e no Espírito de nosso Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 12, '"Tudo me é permitido", mas nem tudo convém. "Tudo me é permitido", mas eu não deixarei que nada domine.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 13, '"Os alimentos foram feitos para o estômago e o estômago para os alimentos", mas Deus destruirá ambos. O corpo, porém, não é para a imoralidade, mas para o Senhor, e o Senhor para o corpo.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 14, 'Por seu poder, Deus ressuscitou o Senhor e também nos ressuscitará.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 15, 'Vocês não sabem que os seus corpos são membros de Cristo? Tomarei eu os membros de Cristo e os unirei a uma prostituta? De modo nenhum!', 3, CURRENT_TIMESTAMP, false),
(46, 6, 16, 'Vocês não sabem que aquele que se une a uma prostituta é um corpo com ela? Pois, como está escrito: "Os dois serão uma só carne".', 3, CURRENT_TIMESTAMP, false),
(46, 6, 17, 'Mas aquele que se une ao Senhor é um espírito com ele.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 18, 'Fujam da imoralidade sexual. Todos os outros pecados que alguém comete, fora do corpo os comete; mas quem peca sexualmente, peca contra o seu próprio corpo.', 3, CURRENT_TIMESTAMP, false),
(46, 6, 19, 'Acaso não sabem que o corpo de vocês é santuário do Espírito Santo que habita em vocês, que lhes foi dado por Deus, e que vocês não são de si mesmos?', 3, CURRENT_TIMESTAMP, false),
(46, 6, 20, 'Vocês foram comprados por alto preço. Portanto, glorifiquem a Deus com o corpo de vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 1, 'Quanto aos assuntos sobre os quais vocês escreveram, é bom que o homem não toque em mulher,', 3, CURRENT_TIMESTAMP, false),
(46, 7, 2, 'mas, por causa da imoralidade, cada um deve ter sua esposa, e cada mulher o seu próprio marido.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 3, 'O marido deve cumprir os seus deveres conjugais para com a sua mulher, e da mesma forma a mulher para com o seu marido.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 4, 'A mulher não tem autoridade sobre o seu próprio corpo, mas sim o marido. Da mesma forma, o marido não tem autoridade sobre o seu próprio corpo, mas sim a mulher.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 5, 'Não se recusem um ao outro, exceto por mútuo consentimento e durante certo tempo, para se dedicarem à oração. Depois, unam-se de novo, para que Satanás não os tente por não terem domínio próprio.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 6, 'Digo isso como concessão, e não como mandamento.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 7, 'Gostaria que todos os homens fossem como eu; mas cada um tem o seu próprio dom da parte de Deus; um de um modo, outro de outro.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 8, 'Digo, porém, aos solteiros e às viúvas: é bom que permaneçam como eu.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 9, 'Mas, se não conseguem controlar-se, devem casar-se, pois é melhor casar-se do que ficar ardendo de desejo.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 10, 'Aos casados dou este mandamento, não eu, mas o Senhor: que a esposa não se separe do seu marido.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 11, 'Mas, se o fizer, que permaneça sem se casar ou, então, reconcilie-se com o seu marido. E o marido não se divorcie da sua mulher.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 12, 'Aos outros eu mesmo digo isto, e não o Senhor: se um irmão tem mulher descrente, e ela se dispõe a viver com ele, não se divorcie dela.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 13, 'E, se uma mulher tem marido descrente, e ele se dispõe a viver com ela, não se divorcie dele.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 14, 'Pois o marido descrente é santificado por meio da mulher, e a mulher descrente é santificada por meio do marido. Se assim não fosse, seus filhos seriam impuros, mas agora são santos.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 15, 'Todavia, se o descrente separar-se, que se separe. Em tais casos, o irmão ou a irmã não fica debaixo de servidão; Deus nos chamou para vivermos em paz.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 16, 'Você, mulher, como sabe se salvará seu marido? Ou você, marido, como sabe se salvará sua mulher?', 3, CURRENT_TIMESTAMP, false),
(46, 7, 17, 'Entretanto, cada um continue vivendo na condição que o Senhor lhe designou e de acordo com o chamado de Deus. Esta é a minha ordem para todas as igrejas.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 18, 'Foi alguém chamado sendo já circunciso? Não desfaça a sua circuncisão. Foi alguém chamado sendo incircunciso? Não se circuncide.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 19, 'A circuncisão não significa nada, e a incircuncisão também nada é; o que importa é obedecer aos mandamentos de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 20, 'Cada um deve permanecer na condição em que foi chamado por Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 21, 'Foi você chamado sendo escravo? Não se incomode com isso. Mas, se você puder conseguir a liberdade, consiga-a.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 22, 'Pois aquele que, sendo escravo, foi chamado pelo Senhor, é liberto e pertence ao Senhor; semelhantemente, aquele que era livre quando foi chamado, é escravo de Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 23, 'Vocês foram comprados por alto preço; não se tornem escravos de homens.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 24, 'Irmãos, cada um deve permanecer diante de Deus na condição em que foi chamado.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 25, 'Quanto às pessoas virgens, não tenho mandamento do Senhor, mas dou meu parecer como alguém que, pela misericórdia de Deus, é digno de confiança.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 26, 'Por causa dos problemas atuais, penso que é melhor o homem permanecer como está.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 27, 'Você está casado? Não procure separar-se. Está solteiro? Não procure esposa.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 28, 'Mas, se vier a casar-se, não comete pecado; e, se uma virgem se casar, também não comete pecado. Mas aqueles que se casarem enfrentarão muitas dificuldades na vida, e eu gostaria de poupá-los disso.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 29, 'O que quero dizer é que o tempo é pouco. De agora em diante, aqueles que têm esposa, vivam como se não tivessem;', 3, CURRENT_TIMESTAMP, false),
(46, 7, 30, 'aqueles que choram, como se não chorassem; os que estão felizes, como se não estivessem; os que compram algo, como se nada possuíssem;', 3, CURRENT_TIMESTAMP, false),
(46, 7, 31, 'os que usam as coisas do mundo, como se não as usassem; porque a forma presente deste mundo está passando.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 32, 'Gostaria de vê-los livres de preocupações. O homem que não é casado preocupa-se com as coisas do Senhor, em como agradar ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 33, 'Mas o homem casado preocupa-se com as coisas deste mundo, em como agradar sua mulher,', 3, CURRENT_TIMESTAMP, false),
(46, 7, 34, 'e está dividido. Tanto a mulher não casada como a virgem preocupam-se com as coisas do Senhor, para serem santas no corpo e no espírito. Mas a casada preocupa-se com as coisas deste mundo, em como agradar seu marido.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 35, 'Estou dizendo isso para o próprio bem de vocês; não para lhes impor restrições, mas para que vocês possam viver de maneira correta, em plena consagração ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 36, 'Se alguém acha que não está tratando sua filha como é devido e que ela está numa idade madura, pelo que ele se sente obrigado a casá-la, faça como achar melhor. Com isso não peca. Deve permitir que se case.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 37, 'Contudo, o que se mantém firme no seu propósito e não é dominado por seus impulsos mas domina sua própria vontade, e resolveu manter solteira sua filha, este também faz bem.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 38, 'De modo que aquele que dá sua filha em casamento faz bem, mas o que não a dá em casamento faz melhor.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 39, 'A mulher está ligada a seu marido enquanto ele viver. Mas, se o seu marido morrer, ela estará livre para se casar com quem quiser, contanto que ele pertença ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 7, 40, 'Em meu parecer, ela será mais feliz se permanecer como está; e penso que também tenho o Espírito de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 1, 'Com respeito aos alimentos sacrificados aos ídolos, sabemos que todos temos conhecimento. O conhecimento traz orgulho, mas o amor edifica.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 2, 'Quem pensa conhecer alguma coisa, ainda não conhece como deveria.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 3, 'Mas quem ama a Deus, este é conhecido por Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 4, 'Portanto, em relação ao alimento sacrificado aos ídolos, sabemos que o ídolo não significa nada no mundo e que só existe um Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 5, 'Pois mesmo que haja os chamados deuses, quer no céu, quer na terra, ( como de fato há muitos "deuses" e muitos "senhores" ),', 3, CURRENT_TIMESTAMP, false),
(46, 8, 6, 'para nós, porém, há um único Deus, o Pai, de quem vêm todas as coisas e para quem vivemos; e um só Senhor, Jesus Cristo, por meio de quem vieram todas as coisas e por meio de quem vivemos.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 7, 'Contudo, nem todos têm esse conhecimento. Alguns, ainda habituados com os ídolos, comem esse alimento como se fosse um sacrifício idólatra; e como a consciência deles é fraca, esta fica contaminada.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 8, 'A comida, porém, não nos torna aceitáveis diante de Deus; não seremos piores se não comermos, nem melhores se comermos.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 9, 'Contudo, tenham cuidado para que o exercício da liberdade de vocês não se torne uma pedra de tropeço para os fracos.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 10, 'Pois, se alguém que tem a consciência fraca vir você que tem este conhecimento comer num templo de ídolos, não será induzido a comer do que foi sacrificado a ídolos?', 3, CURRENT_TIMESTAMP, false),
(46, 8, 11, 'Assim, esse irmão fraco, por quem Cristo morreu, é destruído por causa do conhecimento que você tem.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 12, 'Quando você peca contra seus irmãos dessa maneira, ferindo a consciência fraca deles, peca contra Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 8, 13, 'Portanto, se aquilo que eu como leva o meu irmão a pecar, nunca mais comerei carne, para não fazer meu irmão tropeçar.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 1, 'Não sou livre? Não sou apóstolo? Não vi Jesus, nosso Senhor? Não são vocês resultado do meu trabalho no Senhor?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 2, 'Ainda que eu não seja apóstolo para outros, certamente o sou para vocês! Pois vocês são o selo do meu apostolado no Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 3, 'Esta é minha defesa diante daqueles que me julgam.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 4, 'Não temos nós o direito de comer e beber?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 5, 'Não temos nós o direito de levar conosco uma esposa crente como fazem os outros apóstolos, os irmãos do Senhor e Pedro?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 6, 'Ou será que apenas eu e Barnabé não temos o direito de deixar de trabalhar para termos sustento?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 7, 'Quem serve como soldado às suas próprias custas? Quem planta uma vinha e não come do seu fruto? Quem apascenta um rebanho e não bebe do seu leite?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 8, 'Não digo isso do ponto de vista meramente humano; a Lei não diz a mesma coisa?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 9, 'Pois está escrito na Lei de Moisés: "Não amordace o boi enquanto ele estiver debulhando o cereal". Por acaso é com bois que Deus está preocupado?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 10, 'Não é certamente por nossa causa que ele o diz? Sim, isso foi escrito em nosso favor. Porque "o lavrador quando ara e o debulhador quando debulha, devem fazê-lo na esperança de participar da colheita".', 3, CURRENT_TIMESTAMP, false),
(46, 9, 11, 'Se entre vocês semeamos coisas espirituais, seria demais colhermos de vocês coisas materiais?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 12, 'Se outros têm direito de ser sustentados por vocês, não o temos nós ainda mais? Mas nós nunca usamos desse direito. Pelo contrário, suportamos tudo para não colocar obstáculo algum ao evangelho de Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 13, 'Vocês não sabem que aqueles que trabalham no templo alimentam-se das coisas do templo, e que os que servem diante do altar participam do que é oferecido no altar?', 3, CURRENT_TIMESTAMP, false),
(46, 9, 14, 'Da mesma forma o Senhor ordenou àqueles que pregam o evangelho, que vivam do evangelho.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 15, 'Mas eu não tenho usado de nenhum desses direitos. Não estou escrevendo na esperança de que vocês façam isso por mim. Prefiro morrer a permitir que alguém me prive deste meu orgulho.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 16, 'Contudo, quando prego o evangelho, não posso me orgulhar, pois me é imposta a necessidade de pregar. Ai de mim se não pregar o evangelho!', 3, CURRENT_TIMESTAMP, false),
(46, 9, 17, 'Porque, se prego de livre vontade, tenho recompensa; contudo, como prego por obrigação, estou simplesmente cumprindo uma incumbência a mim confiada.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 18, 'Qual é, pois, a minha recompensa? Apenas esta: que, pregando o evangelho, eu o apresente gratuitamente, não usando, assim, dos meus direitos ao pregá-lo.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 19, 'Porque, embora seja livre de todos, fiz-me escravo de todos, para ganhar o maior número possível de pessoas.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 20, 'Tornei-me judeu para os judeus, a fim de ganhar os judeus. Para os que estão debaixo da lei, tornei-me como se estivesse sujeito à lei, ( embora eu mesmo não esteja debaixo da lei ), a fim de ganhar os que estão debaixo da lei.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 21, 'Para os que estão sem lei, tornei-me como sem lei ( embora não esteja livre da lei de Deus, mas sim sob a lei de Cristo ), a fim de ganhar os que não têm a lei.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 22, 'Para com os fracos tornei-me fraco, para ganhar os fracos. Tornei-me tudo para com todos, para de alguma forma salvar alguns.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 23, 'Faço tudo isso por causa do evangelho, para ser co-participante dele.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 24, 'Vocês não sabem que dentre todos os que correm no estádio, apenas um ganha o prêmio? Corram de tal modo que alcancem o prêmio.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 25, 'Todos os que competem nos jogos se submetem a um treinamento rigoroso, para obter uma coroa que logo perece; mas nós o fazemos para ganhar uma coroa que dura para sempre.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 26, 'Sendo assim, não corro como quem corre sem alvo, e não luto como quem esmurra o ar.', 3, CURRENT_TIMESTAMP, false),
(46, 9, 27, 'Mas esmurro o meu corpo e faço dele meu escravo, para que, depois de ter pregado aos outros, eu mesmo não venha a ser reprovado.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 1, 'Porque não quero, irmãos, que vocês ignorem o fato de que todos os nossos antepassados estiveram sob a nuvem e todos passaram pelo mar.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 2, 'Em Moisés, todos eles foram batizados na nuvem e no mar.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 3, 'Todos comeram do mesmo alimento espiritual', 3, CURRENT_TIMESTAMP, false),
(46, 10, 4, 'e beberam da mesma bebida espiritual; pois bebiam da rocha espiritual que os acompanhava, e essa rocha era Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 5, 'Contudo, Deus não se agradou da maioria deles; por isso os seus corpos ficaram espalhados no deserto.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 6, 'Essas coisas ocorreram como exemplos para nós, para que não cobicemos coisas más, como eles fizeram.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 7, 'Não sejam idólatras, como alguns deles foram, conforme está escrito: "O povo se assentou para comer e beber, e levantou-se para se entregar à farra".', 3, CURRENT_TIMESTAMP, false),
(46, 10, 8, 'Não pratiquemos imoralidade, como alguns deles fizeram — e num só dia morreram vinte e três mil.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 9, 'Não devemos pôr o Senhor à prova, como alguns deles fizeram — e foram mortos por serpentes.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 10, 'E não se queixem, como alguns deles se queixaram — e foram mortos pelo anjo destruidor.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 11, 'Essas coisas aconteceram a eles como exemplos e foram escritas como advertência para nós, sobre quem tem chegado o fim dos tempos.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 12, 'Assim, aquele que julga estar firme, cuide-se para que não caia!', 3, CURRENT_TIMESTAMP, false),
(46, 10, 13, 'Não sobreveio a vocês tentação que não fosse comum aos homens. E Deus é fiel; ele não permitirá que vocês sejam tentados além do que podem suportar. Mas, quando forem tentados, ele lhes providenciará um escape, para que o possam suportar.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 14, 'Por isso, meus amados irmãos, fujam da idolatria.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 15, 'Estou falando a pessoas sensatas; julguem vocês mesmos o que estou dizendo.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 16, 'Não é verdade que o cálice da bênção que abençoamos é uma participação no sangue de Cristo, e que o pão que partimos é uma participação no corpo de Cristo?', 3, CURRENT_TIMESTAMP, false),
(46, 10, 17, 'Por haver um único pão, nós, que somos muitos, somos um só corpo, pois todos participamos de um único pão.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 18, 'Considerem o povo de Israel: os que comem dos sacrifícios não participam do altar?', 3, CURRENT_TIMESTAMP, false),
(46, 10, 19, 'Portanto, que estou querendo dizer? Será que o sacrifício oferecido a um ídolo é alguma coisa? Ou o ídolo é alguma coisa?', 3, CURRENT_TIMESTAMP, false),
(46, 10, 20, 'Não! Quero dizer que o que os pagãos sacrificam é oferecido aos demônios e não a Deus, e não quero que vocês tenham comunhão com os demônios.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 21, 'Vocês não podem beber do cálice do Senhor e do cálice dos demônios; não podem participar da mesa do Senhor e da mesa dos demônios.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 22, 'Porventura provocaremos o ciúme do Senhor? Somos mais fortes do que ele?', 3, CURRENT_TIMESTAMP, false),
(46, 10, 23, '"Tudo é permitido", mas nem tudo convém. "Tudo é permitido", mas nem tudo edifica.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 24, 'Ninguém deve buscar o seu próprio bem, mas sim o dos outros.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 25, 'Comam de tudo o que se vende no mercado, sem fazer perguntas por causa da consciência,', 3, CURRENT_TIMESTAMP, false),
(46, 10, 26, 'pois "do Senhor é a terra e tudo o que nela existe".', 3, CURRENT_TIMESTAMP, false),
(46, 10, 27, 'Se algum descrente o convidar para uma refeição e você quiser ir, coma de tudo o que lhe for apresentado, sem nada perguntar por causa da consciência.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 28, 'Mas se alguém lhe disser: "Isto foi oferecido em sacrifício", não coma, tanto por causa da pessoa que o comentou, como da consciência,', 3, CURRENT_TIMESTAMP, false),
(46, 10, 29, 'isto é, da consciência do outro e não da sua própria. Pois, por que minha liberdade deve ser julgada pela consciência dos outros?', 3, CURRENT_TIMESTAMP, false),
(46, 10, 30, 'Se participo da refeição com ação de graças, por que sou condenado por algo pelo qual dou graças a Deus?', 3, CURRENT_TIMESTAMP, false),
(46, 10, 31, 'Assim, quer vocês comam, bebam ou façam qualquer outra coisa, façam tudo para a glória de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 32, 'Não se tornem motivo de tropeço, nem para judeus, nem para gregos, nem para a igreja de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 10, 33, 'Também eu procuro agradar a todos de todas as formas. Porque não estou procurando o meu próprio bem, mas o bem de muitos, para que sejam salvos.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 1, 'Tornem-se meus imitadores, como eu o sou de Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 2, 'Eu os elogio por se lembrarem de mim em tudo e por se apegarem às tradições, exatamente como eu as transmiti a vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 3, 'Quero, porém, que entendam que o cabeça de todo homem é Cristo, e o cabeça da mulher é o homem, e o cabeça de Cristo é Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 4, 'Todo homem que ora ou profetiza com a cabeça coberta desonra a sua cabeça;', 3, CURRENT_TIMESTAMP, false),
(46, 11, 5, 'e toda mulher que ora ou profetiza com a cabeça descoberta desonra a sua cabeça; pois é como se a tivesse rapada.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 6, 'Se a mulher não cobre a cabeça, deve também cortar o cabelo; se, porém, é vergonhoso para a mulher ter o cabelo cortado ou rapado, ela deve cobrir a cabeça.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 7, 'O homem não deve cobrir a cabeça, visto que ele é imagem e glória de Deus; mas a mulher é glória do homem.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 8, 'Pois o homem não se originou da mulher, mas a mulher do homem;', 3, CURRENT_TIMESTAMP, false),
(46, 11, 9, 'além disso, o homem não foi criado por causa da mulher, mas a mulher por causa do homem.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 10, 'Por essa razão e por causa dos anjos, a mulher deve ter sobre a cabeça um sinal de autoridade.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 11, 'No Senhor, todavia, a mulher não é independente do homem, nem o homem independente da mulher.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 12, 'Pois, assim como a mulher proveio do homem, também o homem nasce da mulher. Mas tudo provém de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 13, 'Julguem entre vocês mesmos: é apropriado a uma mulher orar a Deus com a cabeça descoberta?', 3, CURRENT_TIMESTAMP, false),
(46, 11, 14, 'A própria natureza das coisas não lhes ensina que é uma desonra para o homem ter cabelo comprido,', 3, CURRENT_TIMESTAMP, false),
(46, 11, 15, 'e que o cabelo comprido é uma glória para a mulher? Pois o cabelo comprido foi lhe dado como manto.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 16, 'Mas se alguém quiser fazer polêmica a esse respeito, nós não temos esse costume, nem as igrejas de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 17, 'Entretanto, nisto que lhes vou dizer não os elogio, pois as reuniões de vocês mais fazem mal do que bem.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 18, 'Em primeiro lugar, ouço que, quando vocês se reúnem como igreja, há divisões entre vocês, e até certo ponto eu o creio.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 19, 'Pois é necessário que haja divergências entre vocês, para que sejam conhecidos quais dentre vocês são aprovados.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 20, 'Quando vocês se reúnem, não é para comer a ceia do Senhor,', 3, CURRENT_TIMESTAMP, false),
(46, 11, 21, 'porque cada um come sua própria ceia sem esperar pelos outros. Assim, enquanto um fica com fome, outro se embriaga.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 22, 'Será que vocês não têm casa onde comer e beber? Ou desprezam a igreja de Deus e humilham os que nada têm? Que lhes direi? Eu os elogiarei por isso? Certamente que não!', 3, CURRENT_TIMESTAMP, false),
(46, 11, 23, 'Pois recebi do Senhor o que também lhes entreguei: que o Senhor Jesus, na noite em que foi traído, tomou o pão', 3, CURRENT_TIMESTAMP, false),
(46, 11, 24, 'e, tendo dado graças, partiu-o e disse: "Isto é o meu corpo, que é dado em favor de vocês; façam isto em memória de mim".', 3, CURRENT_TIMESTAMP, false),
(46, 11, 25, 'Da mesma forma, depois da ceia ele tomou o cálice e disse: "Este cálice é a nova aliança no meu sangue; façam isto, sempre que o beberem, em memória de mim".', 3, CURRENT_TIMESTAMP, false),
(46, 11, 26, 'Porque, sempre que comerem deste pão e beberem deste cálice, vocês anunciam a morte do Senhor até que ele venha.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 27, 'Portanto, todo aquele que comer o pão ou beber o cálice do Senhor indignamente será culpado de pecar contra o corpo e o sangue do Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 28, 'Examine-se o homem a si mesmo, e então coma do pão e beba do cálice.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 29, 'Pois quem come e bebe sem discernir o corpo do Senhor, come e bebe para sua própria condenação.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 30, 'Por isso há entre vocês muitos fracos e doentes, e vários já dormiram.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 31, 'Mas, se nós nos examinássemos a nós mesmos, não receberíamos juízo.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 32, 'Quando, porém, somos julgados pelo Senhor, estamos sendo disciplinados para que não sejamos condenados com o mundo.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 33, 'Portanto, meus irmãos, quando vocês se reunirem para comer, esperem uns pelos outros.', 3, CURRENT_TIMESTAMP, false),
(46, 11, 34, 'Se alguém estiver com fome, coma em casa, para que, quando vocês se reunirem, isso não resulte em condenação. Quanto ao mais, quando eu for lhes darei instruções.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 1, 'Irmãos, quanto aos dons espirituais, não quero que vocês sejam ignorantes.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 2, 'Vocês sabem que, quando eram pagãos, de uma forma ou de outra eram fortemente atraídos e levados para os ídolos mudos.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 3, 'Por isso, eu lhes afirmo que ninguém que fala pelo Espírito de Deus diz: "Jesus seja amaldiçoado"; e ninguém pode dizer: "Jesus é Senhor", a não ser pelo Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 4, 'Há diferentes tipos de dons, mas o Espírito é o mesmo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 5, 'Há diferentes tipos de ministérios, mas o Senhor é o mesmo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 6, 'Há diferentes formas de atuação, mas é o mesmo Deus quem efetua tudo em todos.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 7, 'A cada um, porém, é dada a manifestação do Espírito, visando ao bem comum.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 8, 'Pelo Espírito, a um é dada a palavra de sabedoria; a outro, a palavra de conhecimento, pelo mesmo Espírito;', 3, CURRENT_TIMESTAMP, false),
(46, 12, 9, 'a outro, fé, pelo mesmo Espírito; a outro, dons de cura, pelo único Espírito;', 3, CURRENT_TIMESTAMP, false),
(46, 12, 10, 'a outro, poder para operar milagres; a outro, profecia; a outro, discernimento de espíritos; a outro, variedade de línguas; e ainda a outro, interpretação de línguas.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 11, 'Todas essas coisas, porém, são realizadas pelo mesmo e único Espírito, e ele as distribui individualmente, a cada um, conforme quer.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 12, 'Ora, assim como o corpo é uma unidade, embora tenha muitos membros, e todos os membros, mesmo sendo muitos, formam um só corpo, assim também com respeito a Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 13, 'Pois em um só corpo todos nós fomos batizados em um único Espírito: quer judeus, quer gregos, quer escravos, quer livres. E a todos nós foi dado beber de um único Espírito.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 14, 'O corpo não é composto de um só membro, mas de muitos.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 15, 'Se o pé disser: "Porque não sou mão, não pertenço ao corpo", nem por isso deixa de fazer parte do corpo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 16, 'E se o ouvido disser: "Porque não sou olho, não pertenço ao corpo", nem por isso deixa de fazer parte do corpo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 17, 'Se todo o corpo fosse olho, onde estaria a audição? Se todo o corpo fosse ouvido, onde estaria o olfato?', 3, CURRENT_TIMESTAMP, false),
(46, 12, 18, 'De fato, Deus dispôs cada um dos membros no corpo, segundo a sua vontade.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 19, 'Se todos fossem um só membro, onde estaria o corpo?', 3, CURRENT_TIMESTAMP, false),
(46, 12, 20, 'Assim, há muitos membros, mas um só corpo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 21, 'O olho não pode dizer à mão: "Não preciso de você! " Nem a cabeça pode dizer aos pés: "Não preciso de vocês! "', 3, CURRENT_TIMESTAMP, false),
(46, 12, 22, 'Pelo contrário, os membros do corpo que parecem mais fracos são indispensáveis,', 3, CURRENT_TIMESTAMP, false),
(46, 12, 23, 'e os membros que pensamos serem menos honrosos, tratamos com especial honra. E os membros que em nós são indecorosos são tratados com decoro especial,', 3, CURRENT_TIMESTAMP, false),
(46, 12, 24, 'enquanto os que em nós são decorosos não precisam ser tratados de maneira especial. Mas Deus estruturou o corpo dando maior honra aos membros que dela tinham falta,', 3, CURRENT_TIMESTAMP, false),
(46, 12, 25, 'a fim de que não haja divisão no corpo, mas, sim, que todos os membros tenham igual cuidado uns pelos outros.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 26, 'Quando um membro sofre, todos os outros sofrem com ele; quando um membro é honrado, todos os outros se alegram com ele.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 27, 'Ora, vocês são o corpo de Cristo, e cada um de vocês, individualmente, é membro desse corpo.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 28, 'Assim, na igreja, Deus estabeleceu primeiramente apóstolos; em segundo lugar, profetas; em terceiro lugar, mestres; depois os que realizam milagres, os que têm dom de curar, os que têm dom de prestar ajuda, os que têm dons de administração e os que falam diversas línguas.', 3, CURRENT_TIMESTAMP, false),
(46, 12, 29, 'São todos apóstolos? São todos profetas? São todos mestres? Têm todos o dom de realizar milagres?', 3, CURRENT_TIMESTAMP, false),
(46, 12, 30, 'Têm todos dons de curar? Falam todos em línguas? Todos interpretam?', 3, CURRENT_TIMESTAMP, false),
(46, 12, 31, 'Entretanto, busquem com dedicação os melhores dons. Passo agora a mostrar-lhes um caminho ainda mais excelente.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 1, 'Ainda que eu fale as línguas dos homens e dos anjos, se não tiver amor, serei como o sino que ressoa ou como o prato que retine.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 2, 'Ainda que eu tenha o dom de profecia e saiba todos os mistérios e todo o conhecimento, e tenha uma fé capaz de mover montanhas, mas não tiver amor, nada serei.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 3, 'Ainda que eu dê aos pobres tudo o que possuo e entregue o meu corpo para ser queimado, mas não tiver amor, nada disso me valerá.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 4, 'O amor é paciente, o amor é bondoso. Não inveja, não se vangloria, não se orgulha.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 5, 'Não maltrata, não procura seus interesses, não se ira facilmente, não guarda rancor.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 6, 'O amor não se alegra com a injustiça, mas se alegra com a verdade.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 7, 'Tudo sofre, tudo crê, tudo espera, tudo suporta.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 8, 'O amor nunca perece; mas as profecias desaparecerão, as línguas cessarão, o conhecimento passará.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 9, 'Pois em parte conhecemos e em parte profetizamos;', 3, CURRENT_TIMESTAMP, false),
(46, 13, 10, 'quando, porém, vier o que é perfeito, o que é imperfeito desaparecerá.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 11, 'Quando eu era menino, falava como menino, pensava como menino e raciocinava como menino. Quando me tornei homem, deixei para trás as coisas de menino.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 12, 'Agora, pois, vemos apenas um reflexo obscuro, como em espelho; mas, então, veremos face a face. Agora conheço em parte; então, conhecerei plenamente, da mesma forma como sou plenamente conhecido.', 3, CURRENT_TIMESTAMP, false),
(46, 13, 13, 'Assim, permanecem agora estes três: a fé, a esperança e o amor. O maior deles, porém, é o amor.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 1, 'Sigam o caminho do amor e busquem com dedicação os dons espirituais, principalmente o dom de profecia.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 2, 'Pois quem fala em língua não fala aos homens, mas a Deus. De fato, ninguém o entende; em espírito fala mistérios.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 3, 'Mas quem profetiza o faz para a edificação, encorajamento e consolação dos homens.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 4, 'Quem fala em língua a si mesmo se edifica, mas quem profetiza edifica a igreja.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 5, 'Gostaria que todos vocês falassem em línguas, mas prefiro que profetizem. Quem profetiza é maior do que aquele que fala em línguas, a não ser que as interprete, para que a igreja seja edificada.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 6, 'Agora, irmãos, se eu for visitá-los e falar em línguas, em que lhes serei útil, a não ser que lhes leve alguma revelação, ou conhecimento, ou profecia, ou doutrina?', 3, CURRENT_TIMESTAMP, false),
(46, 14, 7, 'Até no caso de coisas inanimadas que produzem sons, tais como a flauta ou a cítara, como alguém reconhecerá o que está sendo tocado, se os sons não forem distintos?', 3, CURRENT_TIMESTAMP, false),
(46, 14, 8, 'Além disso, se a trombeta não emitir um som claro, quem se preparará para a batalha?', 3, CURRENT_TIMESTAMP, false),
(46, 14, 9, 'Assim acontece com vocês. Se não proferirem palavras compreensíveis com a língua, como alguém saberá o que está sendo dito? Vocês estarão simplesmente falando ao ar.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 10, 'Sem dúvida, há diversos idiomas no mundo; todavia, nenhum deles é sem sentido.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 11, 'Portanto, se eu não entender o significado do que alguém está falando, serei estrangeiro para quem fala, e ele, estrangeiro para mim.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 12, 'Assim acontece com vocês. Visto que estão ansiosos por terem dons espirituais, procurem crescer naqueles que trazem a edificação para a igreja.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 13, 'Por isso, quem fala em língua, ore para que a possa interpretar.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 14, 'Pois, se oro em língua, meu espírito ora, mas a minha mente fica infrutífera.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 15, 'Então, que farei? Orarei com o espírito, mas também orarei com o entendimento; cantarei com o espírito, mas também cantarei com o entendimento.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 16, 'Se você estiver louvando a Deus em espírito, como poderá aquele que está entre os não instruídos dizer o "Amém" à sua ação de graças, visto que não sabe o que você está dizendo?', 3, CURRENT_TIMESTAMP, false),
(46, 14, 17, 'Pode ser que você esteja dando graças muito bem, mas o outro não é edificado.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 18, 'Dou graças a Deus por falar em línguas mais do que todos vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 19, 'Todavia, na igreja prefiro falar cinco palavras compreensíveis para instruir os outros a falar dez mil palavras em língua.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 20, 'Irmãos, deixem de pensar como crianças. Com respeito ao mal, sejam crianças; mas, quanto ao modo de pensar, sejam adultos.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 21, 'Pois está escrito na Lei: "Por meio de homens de outras línguas e por meio de lábios de estrangeiros falarei a este povo, mas, mesmo assim, eles não me ouvirão", diz o Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 22, 'Portanto, as línguas são um sinal para os descrentes, e não para os que crêem; a profecia, porém, é para os que crêem, e não para os descrentes.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 23, 'Assim, se toda a igreja se reunir e todos falarem em línguas, e entrarem alguns não instruídos ou descrentes não dirão que vocês estão loucos?', 3, CURRENT_TIMESTAMP, false),
(46, 14, 24, 'Mas se entrar algum descrente ou não instruído quando todos estiverem profetizando, ele por todos será convencido de que é pecador e por todos será julgado,', 3, CURRENT_TIMESTAMP, false),
(46, 14, 25, 'e os segredos do seu coração serão expostos. Assim, ele se prostrará, rosto em terra, e adorará a Deus, exclamando: "Deus realmente está entre vocês! "', 3, CURRENT_TIMESTAMP, false),
(46, 14, 26, 'Portanto, que diremos, irmãos? Quando vocês se reúnem, cada um de vocês tem um salmo, ou uma palavra de instrução, uma revelação, uma palavra em língua ou uma interpretação. Tudo seja feito para a edificação da igreja.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 27, 'Se, porém, alguém falar em língua, devem falar dois, no máximo três, e alguém deve interpretar.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 28, 'Se não houver intérprete, fique calado na igreja, falando consigo mesmo e com Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 29, 'Tratando-se de profetas, falem dois ou três, e os outros julguem cuidadosamente o que foi dito.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 30, 'Se vier uma revelação a alguém que está sentado, cale-se o primeiro.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 31, 'Pois vocês todos podem profetizar, cada um por sua vez, de forma que todos sejam instruídos e encorajados.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 32, 'Os espíritos dos profetas estão sujeitos aos profetas.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 33, 'Pois Deus não é Deus de desordem, mas de paz. Como em todas as congregações dos santos,', 3, CURRENT_TIMESTAMP, false),
(46, 14, 34, 'permaneçam as mulheres em silêncio nas igrejas, pois não lhes é permitido falar; antes permaneçam em submissão, como diz a lei.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 35, 'Se quiserem aprender alguma coisa, que perguntem a seus maridos em casa; pois é vergonhoso uma mulher falar na igreja.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 36, 'Acaso a palavra de Deus originou-se entre vocês? São vocês o único povo que ela alcançou?', 3, CURRENT_TIMESTAMP, false),
(46, 14, 37, 'Se alguém pensa que é profeta ou espiritual, reconheça que o que lhes estou escrevendo é mandamento do Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 38, 'Se ignorar isso, ele mesmo será ignorado.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 39, 'Portanto, meus irmãos, busquem com dedicação o profetizar e não proíbam o falar em línguas.', 3, CURRENT_TIMESTAMP, false),
(46, 14, 40, 'Mas tudo deve ser feito com decência e ordem.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 1, 'Irmãos, quero lembrar-lhes o evangelho que lhes preguei, o qual vocês receberam e no qual estão firmes.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 2, 'Por meio deste evangelho vocês são salvos, desde que se apeguem firmemente à palavra que lhes preguei; caso contrário, vocês têm crido em vão.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 3, 'Pois o que primeiramente lhes transmiti foi o que recebi: que Cristo morreu pelos nossos pecados, segundo as Escrituras,', 3, CURRENT_TIMESTAMP, false),
(46, 15, 4, 'foi sepultado e ressuscitou ao terceiro dia, segundo as Escrituras,', 3, CURRENT_TIMESTAMP, false),
(46, 15, 5, 'e apareceu a Pedro e depois aos Doze.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 6, 'Depois disso apareceu a mais de quinhentos irmãos de uma só vez, a maioria dos quais ainda vive, embora alguns já tenham adormecido.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 7, 'Depois apareceu a Tiago e, então, a todos os apóstolos;', 3, CURRENT_TIMESTAMP, false),
(46, 15, 8, 'depois destes apareceu também a mim, como a um que nasceu fora de tempo.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 9, 'Pois sou o menor dos apóstolos e nem sequer mereço ser chamado apóstolo, porque persegui a igreja de Deus.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 10, 'Mas, pela graça de Deus, sou o que sou, e sua graça para comigo não foi em vão; antes, trabalhei mais do que todos eles; contudo, não eu, mas a graça de Deus comigo.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 11, 'Portanto, quer tenha sido eu, quer tenham sido eles, é isto que pregamos, e é isto que vocês creram.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 12, 'Ora, se está sendo pregado que Cristo ressuscitou dentre os mortos, como alguns de vocês estão dizendo que não existe ressurreição dos mortos?', 3, CURRENT_TIMESTAMP, false),
(46, 15, 13, 'Se não há ressurreição dos mortos, então nem mesmo Cristo ressuscitou;', 3, CURRENT_TIMESTAMP, false),
(46, 15, 14, 'e, se Cristo não ressuscitou, é inútil a nossa pregação, como também é inútil a fé que vocês têm.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 15, 'Mais que isso, seremos considerados falsas testemunhas de Deus, pois contra ele testemunhamos que ressuscitou a Cristo dentre os mortos. Mas se de fato os mortos não ressuscitam, ele também não ressuscitou a Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 16, 'Pois, se os mortos não ressuscitam, nem mesmo Cristo ressuscitou.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 17, 'E, se Cristo não ressuscitou, inútil é a fé que vocês têm, e ainda estão em seus pecados.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 18, 'Neste caso, também os que dormiram em Cristo estão perdidos.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 19, 'Se é somente para esta vida que temos esperança em Cristo, dentre todos os homens somos os mais dignos de compaixão.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 20, 'Mas de fato Cristo ressuscitou dentre os mortos, sendo as primícias dentre aqueles que dormiram.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 21, 'Visto que a morte veio por meio de um só homem, também a ressurreição dos mortos veio por meio de um só homem.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 22, 'Pois da mesma forma como em Adão todos morrem, em Cristo todos serão vivificados.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 23, 'Mas cada um por sua vez: Cristo, o primeiro; depois, quando ele vier, os que lhe pertencem.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 24, 'Então virá o fim, quando ele entregar o Reino a Deus, o Pai, depois de ter destruído todo domínio, autoridade e poder.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 25, 'Pois é necessário que ele reine até que todos os seus inimigos sejam postos debaixo de seus pés.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 26, 'O último inimigo a ser destruído é a morte.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 27, 'Porque ele "tudo sujeitou debaixo de seus pés". Ora, quando se diz que "tudo" lhe foi sujeito, fica claro que isso não inclui o próprio Deus, que tudo submeteu a Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 28, 'Quando, porém, tudo lhe estiver sujeito, então o próprio Filho se sujeitará àquele que todas as coisas lhe sujeitou, a fim de que Deus seja tudo em todos.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 29, 'Se não há ressurreição, que farão aqueles que se batizam pelos mortos? Se absolutamente os mortos não ressuscitam, por que se batizam por eles?', 3, CURRENT_TIMESTAMP, false),
(46, 15, 30, 'Também nós, por que estamos nos expondo a perigos o tempo todo?', 3, CURRENT_TIMESTAMP, false),
(46, 15, 31, 'Todos os dias enfrento a morte, irmãos; isso digo pelo orgulho que tenho de vocês em Cristo Jesus, nosso Senhor.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 32, 'Se foi por meras razões humanas que lutei com feras em Éfeso, que ganhei com isso? Se os mortos não ressuscitam, "comamos e bebamos, porque amanhã morreremos".', 3, CURRENT_TIMESTAMP, false),
(46, 15, 33, 'Não se deixem enganar: "as más companhias corrompem os bons costumes".', 3, CURRENT_TIMESTAMP, false),
(46, 15, 34, 'Como justos, recuperem o bom senso e parem de pecar; pois alguns há que não têm conhecimento de Deus; digo isso para vergonha de vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 35, 'Mas alguém pode perguntar: "Como ressuscitam os mortos? Com que espécie de corpo virão? "', 3, CURRENT_TIMESTAMP, false),
(46, 15, 36, 'Insensato! O que você semeia não nasce a não ser que morra.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 37, 'Quando você semeia, não semeia o corpo que virá a ser, mas apenas uma simples semente, como de trigo ou de alguma outra coisa.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 38, 'Mas Deus lhe dá um corpo, como determinou, e a cada espécie de semente dá seu corpo apropriado.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 39, 'Nem toda carne é a mesma: os homens têm uma espécie de carne, os animais têm outra, as aves outra, e os peixes outra.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 40, 'Há corpos celestes e há também corpos terrestres; mas o esplendor dos corpos celestes é um, e o dos corpos terrestres é outro.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 41, 'Um é o esplendor do sol, outro o da lua, e outro o das estrelas; e as estrelas diferem em esplendor umas das outras.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 42, 'Assim será com a ressurreição dos mortos. O corpo que é semeado é perecível e ressuscita imperecível;', 3, CURRENT_TIMESTAMP, false),
(46, 15, 43, 'é semeado em desonra e ressuscita em glória; é semeado em fraqueza e ressuscita em poder;', 3, CURRENT_TIMESTAMP, false),
(46, 15, 44, 'é semeado um corpo natural e ressuscita um corpo espiritual. Se há corpo natural, há também corpo espiritual.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 45, 'Assim está escrito: "O primeiro homem, Adão, tornou-se um ser vivente"; o último Adão, espírito vivificante.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 46, 'Não foi o espiritual que veio antes, mas o natural; depois dele, o espiritual.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 47, 'O primeiro homem era do pó da terra; o segundo homem, do céu.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 48, 'Os que são da terra são semelhantes ao homem terreno; os que são do céu, ao homem celestial.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 49, 'Assim como tivemos a imagem do homem terreno, teremos também a imagem do homem celestial.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 50, 'Irmãos, eu lhes declaro que carne e sangue não podem herdar o Reino de Deus, nem o que é perecível pode herdar o imperecível.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 51, 'Eis que eu lhes digo um mistério: nem todos dormiremos, mas todos seremos transformados,', 3, CURRENT_TIMESTAMP, false),
(46, 15, 52, 'num momento, num abrir e fechar de olhos, ao som da última trombeta. Pois a trombeta soará, os mortos ressuscitarão incorruptíveis e nós seremos transformados.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 53, 'Pois é necessário que aquilo que é corruptível se revista de incorruptibilidade, e aquilo que é mortal, se revista de imortalidade.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 54, 'Quando, porém, o que é corruptível se revestir de incorruptibilidade, e o que é mortal, de imortalidade, então se cumprirá a palavra que está escrita: "A morte foi destruída pela vitória".', 3, CURRENT_TIMESTAMP, false),
(46, 15, 55, '"Onde está, ó morte, a sua vitória? Onde está, ó morte, o seu aguilhão? "', 3, CURRENT_TIMESTAMP, false),
(46, 15, 56, 'O aguilhão da morte é o pecado, e a força do pecado é a lei.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 57, 'Mas graças a Deus, que nos dá a vitória por meio de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(46, 15, 58, 'Portanto, meus amados irmãos, mantenham-se firmes, e que nada os abale. Sejam sempre dedicados à obra do Senhor, pois vocês sabem que, no Senhor, o trabalho de vocês não será inútil.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 1, 'Quanto à coleta para o povo de Deus, façam como ordenei às igrejas da Galácia.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 2, 'No primeiro dia da semana, cada um de vocês separe uma quantia, de acordo com a sua renda, reservando-a para que não seja preciso fazer coletas quando eu chegar.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 3, 'Então, quando eu chegar, entregarei cartas de recomendação aos homens que vocês aprovarem e os mandarei para Jerusalém com a oferta de vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 4, 'Se me parecer conveniente ir também, eles me acompanharão.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 5, 'Depois de passar pela Macedônia irei visitá-los, já que passarei por lá.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 6, 'Talvez eu permaneça com vocês durante algum tempo, ou até mesmo passe o inverno com vocês, para que me ajudem na viagem, aonde quer que eu vá.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 7, 'Desta vez não quero apenas vê-los e fazer uma visita de passagem; espero ficar algum tempo com vocês, se o Senhor permitir.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 8, 'Mas permanecerei em Éfeso até o Pentecoste,', 3, CURRENT_TIMESTAMP, false),
(46, 16, 9, 'porque se abriu para mim uma porta ampla e promissora; e há muitos adversários.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 10, 'Se Timóteo for, tomem providências para que ele não tenha nada que temer enquanto estiver com vocês, pois ele trabalha na obra do Senhor, assim como eu.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 11, 'Portanto, ninguém o despreze. Ajudem-no a prosseguir viagem em paz, para que ele possa voltar a mim. Eu o estou esperando juntamente com os irmãos.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 12, 'Quanto ao irmão Apolo, insisti que fosse visitar vocês, juntamente com os irmãos. Ele não quis de modo nenhum ir agora, mas irá quando tiver boa oportunidade.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 13, 'Estejam vigilantes, mantenham-se firmes na fé, sejam homens de coragem, sejam fortes.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 14, 'Façam tudo com amor.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 15, 'Vocês sabem que os da casa de Estéfanas foram o primeiro fruto da Acaia e que eles têm se dedicado ao serviço dos santos. Recomendo-lhes, irmãos,', 3, CURRENT_TIMESTAMP, false),
(46, 16, 16, 'que se submetam a pessoas como eles e a todos os que cooperam e trabalham conosco.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 17, 'Alegrei-me com a vinda de Estéfanas, Fortunato e Acaico, porque eles supriram o que estava faltando da parte de vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 18, 'Eles trouxeram alívio ao meu espírito, e ao de vocês também. Valorizem homens como estes.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 19, 'As igrejas da província da Ásia enviam-lhes saudações. Áqüila e Priscila os saúdam afetuosamente no Senhor, e também a igreja que se reúne na casa deles.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 20, 'Todos os irmãos daqui lhes enviam saudações. Saúdem-se uns aos outros com beijo santo.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 21, 'Eu, Paulo, escrevi esta saudação de próprio punho.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 22, 'Se alguém não ama o Senhor, seja amaldiçoado. Vem, Senhor!', 3, CURRENT_TIMESTAMP, false),
(46, 16, 23, 'A graça do Senhor Jesus seja com vocês.', 3, CURRENT_TIMESTAMP, false),
(46, 16, 24, 'Recebam o amor que tenho por todos vocês em Cristo Jesus. Amém.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 1, 'Adão, Sete, Enos,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 2, 'Cainã, Malaleel, Jarede,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 3, 'Enoque, Matusalém, Lameque, Noé.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 4, 'Estes foram os filhos de Noé: Sem, Cam e Jafé.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 5, 'Estes foram os filhos de Jafé: Gômer, Magogue, Madai, Javã, Tubal, Meseque e Tirás.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 6, 'Estes foram os filhos de Gômer: Asquenaz, Rifate e Togarma.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 7, 'Estes foram os filhos de Javã: Elisá, Társis, Quitim e Rodanim.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 8, 'Estes foram os filhos de Cam: Cuxe, Mizraim, Fute e Canaã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 9, 'Estes foram os filhos de Cuxe: Sebá, Havilá, Sabtá, Raamá e Sabtecá. Estes foram os filhos de Raamá: Sabá e Dedã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 10, 'Cuxe gerou Ninrode, o primeiro homem poderoso na terra.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 11, 'Mizraim gerou os luditas, os anamitas, os leabitas, os naftuítas,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 12, 'os patrusitas, os casluítas, dos quais se originaram os filisteus, e os caftoritas.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 13, 'Canaã gerou Sidom, seu filho mais velho, e Hete,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 14, 'como também os jebuseus, os amorreus, os girgaseus,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 15, 'os heveus, os arqueus, os sineus,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 16, 'os arvadeus, os zemareus e os hamateus.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 17, 'Estes foram os filhos de Sem: Elão, Assur, Arfaxade, Lude e Arã. Estes foram os filhos de Arã: Uz, Hul, Géter e Meseque.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 18, 'Arfaxade gerou Salá, e este gerou Héber.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 19, 'A Héber nasceram dois filhos: Um deles se chamou Pelegue, porque em sua época a terra foi dividida; seu irmão chamou-se Joctã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 20, 'Joctã gerou Almodá, Salefe, Hazarmavé, Jerá,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 21, 'Hadorão, Uzal, Dicla,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 22, 'Obal, Abimael, Sabá,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 23, 'Ofir, Havilá e Jobabe. Todos esses foram filhos de Joctã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 24, 'Sem, Arfaxade, Salá,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 25, 'Héber, Pelegue, Reú,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 26, 'Serugue, Naor, Terá', 3, CURRENT_TIMESTAMP, false),
(13, 1, 27, 'e Abrão, que é Abraão.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 28, 'Estes foram os filhos de Abraão: Isaque e Ismael.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 29, 'Foram estes os seus descendentes: Nebaiote, o filho mais velho de Ismael, Quedar, Adbeel, Mibsão,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 30, 'Misma, Dumá, Massá, Hadade, Temá,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 31, 'Jetur, Nafis e Quedemá. Esses foram os filhos de Ismael.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 32, 'Estes foram os filhos de Abraão com sua concubina Quetura: Zinrã, Jocsã, Medã, Midiã, Isbaque e Suá. Foram estes os filhos de Jocsã: Sabá e Dedã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 33, 'Foram estes os filhos de Midiã: Efá, Éfer, Enoque, Abida e Elda. Todos esses foram descendentes de Quetura.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 34, 'Abraão gerou Isaque. Estes foram os filhos de Isaque: Esaú e Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 35, 'Estes foram os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão e Corá.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 36, 'Estes foram os filhos de Elifaz: Temã, Omar, Zefô, Gaetã e Quenaz; e Amaleque, de Timna, sua concumbina.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 37, 'Estes foram os filhos de Reuel: Naate, Zerá, Samá e Mizá.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 38, 'Estes foram os filhos de Seir: Lotã, Sobal, Zibeão, Aná, Disom, Eser e Disã. Lotã tinha uma irmã chamada Timna.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 39, 'Estes foram os filhos de Lotã: Hori e Homã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 40, 'Estes foram os filhos de Sobal: Alvã, Manaate, Ebal, Sefô e Onã. Estes foram os filhos de Zibeão: Aiá e Aná.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 41, 'Este foi o filho de Aná: Disom. Estes foram os filhos de Disom: Hendã, Esbã, Itrã e Querã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 42, 'Estes foram os filhos de Eser: Bilã, Zaavã e Acã. Estes foram os filhos de Disã: Uz e Arã.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 43, 'Estes foram os reis que reinaram no território de Edom antes que os israelitas tivessem um rei: Belá, filho de Beor. Sua cidade chamava-se Dinabá.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 44, 'Belá morreu, e Jobabe, filho de Zerá, de Bozra, foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 45, 'Jobabe morreu, e Husã, da terra dos temanitas, foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 46, 'Husã morreu, e Hadade, filho de Bedade, que tinha derrotado os midianitas na terra de Moabe, foi o seu sucessor. Sua cidade chamava-se Avite.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 47, 'Hadade morreu, e Samlá de Masreca foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 48, 'Samlá morreu, e Saul, de Reobote, próxima ao Eufrates, foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 49, 'Saul morreu, e Baal-Hanã, filho de Acbor, foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 50, 'Baal-Hanã morreu, e Hadade foi o seu sucessor. Sua cidade chamava-se Paú, e o nome de sua mulher era Meetabel, filha de Matrede e neta de Mezaabe.', 3, CURRENT_TIMESTAMP, false),
(13, 1, 51, 'Após a morte de Hadade, Edom foi governada pelos seguintes chefes: Timna, Alva, Jetete,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 52, 'Oolibama, Elá, Pinom,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 53, 'Quenaz, Temã, Mibzar,', 3, CURRENT_TIMESTAMP, false),
(13, 1, 54, 'Magdiel e Irã. Foram esses os chefes de Edom.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 1, 'Estes foram os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar, Zebulom,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 2, 'Dã, José, Benjamim, Naftali, Gade e Aser.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 3, 'Estes foram os filhos de Judá: Er, Onã e Selá. Ele teve esses três filhos com uma mulher cananéia, a filha de Suá. Mas o Senhor reprovou a conduta perversa de Er, filho mais velho de Judá, e por isso o matou.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 4, 'Tamar, nora de Judá, deu-lhe os filhos Perez e Zerá. A Judá nasceram ao todo cinco filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 5, 'Estes foram os filhos de Perez: Hezrom e Hamul.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 6, 'Estes foram os filhos de Zerá: Zinri, Etã, Hemã, Calcol e Darda. Foram cinco ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 7, 'O filho de Carmi foi Acar. Ele causou desgraça a Israel ao violar a proibição de se apossar das coisas consagradas.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 8, 'Este foi o filho de Etã: Azarias.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 9, 'Os filhos que nasceram a Hezrom foram Jerameel, Rão e Calebe.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 10, 'Rão gerou Aminadabe, e Aminadabe gerou Naassom, o líder da tribo de Judá.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 11, 'Naassom gerou Salmom, Salmom gerou Boaz,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 12, 'Boaz gerou Obede, e Obede gerou Jessé.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 13, 'Jessé gerou Eliabe, o seu filho mais velho; o segundo foi Abinadabe, o terceiro Siméia,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 14, 'o quarto Natanael, o quinto Radai,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 15, 'o sexto Ozém, e o sétimo Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 16, 'As irmãs deles foram Zeruia e Abigail. Os três filhos de Zeruia foram Abisai, Joabe e Asael.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 17, 'Abigail deu à luz Amasa, filho do ismaelita Jéter.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 18, 'Calebe, filho de Hezrom, teve uma filha chamada Jeriote com sua mulher Azuba. Estes foram os filhos de Azuba: Jeser, Sobabe e Ardom.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 19, 'Quando Azuba morreu, Calebe tomou por mulher a Efrate, com quem teve Hur.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 20, 'Hur gerou Uri, e Uri gerou Bezalel.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 21, 'Depois disso, Hezrom, aos sessenta anos, tomou por mulher a filha de Maquir, pai de Gileade e ela deu-lhe um filho chamado Segube.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 22, 'Segube gerou Jair, que governou vinte e três cidades em Gileade.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 23, 'Gesur e Arã conquistaram Havote-Jair, bem como Quenate e os povoados ao redor, ao todo sessenta cidades. Todos esses foram descendentes de Maquir, pai de Gileade.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 24, 'Depois que Hezrom morreu em Calebe-Efrata, Abia, a mulher de Hezrom, deu-lhe Asur, fundador de Tecoa.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 25, 'Estes foram os filhos de Jerameel, o filho mais velho de Hezrom: Rão, o mais velho, Buna, Orém, Ozém e Aías.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 26, 'Jerameel teve outra mulher, chamada Atara, que foi a mãe de Onã.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 27, 'Estes foram os filhos de Rão, o filho mais velho de Jerameel: Maaz, Jamim e Equer.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 28, 'Estes foram os filhos de Onã: Samai e Jada. Estes foram os filhos de Samai: Nadabe e Abisur.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 29, 'O nome da mulher de Abisur era Abiail. Ela deu-lhe dois filhos: Abã e Molide.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 30, 'Estes foram os filhos de Nadabe: Selede e Apaim. Selede morreu sem filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 31, 'O filho de Apaim foi Isi, pai de Sesã, pai de Alai.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 32, 'Estes foram os filhos de Jada, irmão de Samai: Jéter e Jônatas. Jéter morreu sem filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 33, 'Estes foram os filhos de Jônatas: Pelete e Zaza. Foram esses os descendentes de Jera-meel.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 34, 'Sesã não teve filhos, apenas filhas. Tinha ele um escravo egípcio chamado Jará,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 35, 'a quem deu uma de suas filhas por mulher. E ela deu-lhe um filho chamado Atai.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 36, 'Atai gerou Natã, Natã gerou Zabade,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 37, 'Zabade gerou Eflal, Eflal gerou Obede,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 38, 'Obede gerou Jeú, Jeú gerou Azarias,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 39, 'Azarias gerou Helez, Helez gerou Eleasa,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 40, 'Eleasa gerou Sismai, Sismai gerou Salum,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 41, 'Salum gerou Jecamias, e Jecamias gerou Elisama.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 42, 'Estes foram os filhos de Calebe, irmão de Jerameel: Messa, o mais velho, que foi o pai de Zife, e seu filho Maressa, pai de Hebrom.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 43, 'Estes foram os filhos de Hebrom: Corá, Tapua, Requém e Sema.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 44, 'Sema gerou Raão, pai de Jorqueão. Requém gerou Samai.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 45, 'O filho de Samai foi Maom, e Maom foi o pai de Bete-Zur.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 46, 'A concubina de Calebe, Efá teve três filhos: Harã, Mosa e Gazez. Harã gerou Gazez.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 47, 'Estes foram os filhos de Jadai: Regém, Jotão, Gesã, Pelete, Efá e Saafe.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 48, 'A concubina de Calebe, Maaca teve dois filhos: Seber e Tiraná.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 49, 'Ela também teve Saafe, pai de Madmana, e Seva, pai de Macbena e de Gibeá. A filha de Calebe chamava-se Acsa.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 50, 'Calebe teve também estes outros descendentes: Os filhos de Hur, o filho mais velho de Efrate: Sobal, fundador de Quiriate-Jearim,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 51, 'Salma, fundador de Belém, e Harefe, fundador de Bete-Gader.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 52, 'Os descendentes de Sobal, fundador de Quiriate-Jearim: O povo de Haroé, metade dos manaatitas,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 53, 'e os clãs de Quiriate-Jearim: os itritas, os fateus, os sumateus e os misraeus. Desses descenderam os zoratitas e os estaoleus.', 3, CURRENT_TIMESTAMP, false),
(13, 2, 54, 'Os descendentes de Salma: O povo de Belém e de Atrote-Bete-Joabe, os netofatitas, metade dos manaatitas, os zoreus,', 3, CURRENT_TIMESTAMP, false),
(13, 2, 55, 'e os clãs dos escribas que viviam em Jabez: os tiratitas, os simeatitas e os sucatitas. Esses foram os queneus, descendentes de Hamate, antepassado da família de Recabe.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 1, 'Estes foram os filhos de Davi nascidos em Hebrom: O seu filho mais velho era Amnom, filho de Ainoã de Jezreel; o segundo, Daniel, de Abigail, de Carmelo;', 3, CURRENT_TIMESTAMP, false),
(13, 3, 2, 'o terceiro, Absalão, de Maaca, filha de Talmai, rei de Gesur; o quarto, Adonias, de Hagite;', 3, CURRENT_TIMESTAMP, false),
(13, 3, 3, 'o quinto, Sefatias, de Abital; e o sexto, Itreão, de sua mulher Eglá.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 4, 'São esses os seis filhos de Davi que nasceram em Hebrom, onde ele reinou sete anos e seis meses. E, em Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(13, 3, 5, 'onde Davi reinou trinta e três anos, nasceram-lhe os seguintes filhos: Siméia, Sobabe, Natã e Salomão, os quatro filhos que ele teve com Bate-Seba, filha de Amiel.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 6, 'Davi teve ainda mais nove filhos: Ibar, Elisua, Elpalete,', 3, CURRENT_TIMESTAMP, false),
(13, 3, 7, 'Nogá, Nefegue, Jafia,', 3, CURRENT_TIMESTAMP, false),
(13, 3, 8, 'Elisama, Eliada e Elifelete.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 9, 'Todos esses foram filhos de Davi, sem contar os filhos que teve com suas concubinas, e sua filha Tamar, irmã deles.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 10, 'O filho de Salomão foi Roboão; o filho de Roboão foi Abias; o filho de Abias, Asa; o filho de Asa, Josafá;', 3, CURRENT_TIMESTAMP, false),
(13, 3, 11, 'o filho de Josafá, Jeorão; o filho de Jeorão, Acazias; o filho de Acazias, Joás;', 3, CURRENT_TIMESTAMP, false),
(13, 3, 12, 'o filho de Joás, Amazias; o filho de Amazias, Azarias; o filho de Azarias, Jotão;', 3, CURRENT_TIMESTAMP, false),
(13, 3, 13, 'o filho de Jotão, Acaz; o filho de Acaz, Ezequias; o filho de Ezequias, Manassés;', 3, CURRENT_TIMESTAMP, false),
(13, 3, 14, 'o filho de Manassés, Amom; o filho de Amom, Josias.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 15, 'Os filhos de Josias foram: Joanã, o primeiro, Jeoaquim, o segundo, Zedequias, o terceiro, e Salum, o quarto.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 16, 'Os sucessores de Jeoaquim foram: Joaquim e Zedequias.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 17, 'Estes foram os filhos de Joaquim, que foi levado para o cativeiro: Sealtiel,', 3, CURRENT_TIMESTAMP, false),
(13, 3, 18, 'Malquirão, Pedaías, Senazar, Jecamias, Hosama e Nedabias.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 19, 'Estes foram os filhos de Pedaías: Zorobabel e Simei. Estes foram os filhos de Zorobabel: Mesulão, Hananias e Selomite, irmã deles.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 20, 'Teve ainda mais cinco filhos: Hasubá, Oel, Berequias, Hasadias e Jusabe-Hesede.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 21, 'Estes foram os descendentes de Hananias: Pelatias e Jesaías, e os filhos de Refaías, de Arnã, de Obadias e de Secanias.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 22, 'Estes foram os descendentes de Secanias: Semaías e seus filhos Hatus, Igal, Bariá, Nearias e Safate; seis descendentes ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 23, 'Estes foram os três filhos de Nearias: Elioenai, Ezequias e Azricão.', 3, CURRENT_TIMESTAMP, false),
(13, 3, 24, 'Estes foram os sete filhos de Elioenai: Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías e Anani.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 1, 'Estes foram os descendentes de Judá: Perez, Hezrom, Carmi, Hur e Sobal.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 2, 'Reaías, filho de Sobal, gerou Jaate, e Jaate gerou Aumai e Laade. Esses foram os clãs dos zoratitas.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 3, 'Estes foram os filhos de Etã: Jezreel, Isma e Idbás. A irmã deles chamava-se Hazelelponi.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 4, 'Depois teve Penuel, pai de Gedor, e Ézer, pai de Husá. Esses foram os descendentes de Hur, o filho mais velho de Efrate e pai de Belém.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 5, 'Asur, fundador de Tecoa, teve duas mulheres: Helá e Naará.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 6, 'Naará lhe deu Auzã, Héfer, Temeni e Haastari. Esses foram os filhos de Naará.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 7, 'Estes foram os filhos de Helá: Zerete, Zoar, Etnã', 3, CURRENT_TIMESTAMP, false),
(13, 4, 8, 'e Coz, que gerou Anube e Zobeba e os clãs de Aarel, filho de Harum.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 9, 'Jabez foi o homem mais respeitado de sua família. Sua mãe lhe deu o nome de Jabez, dizendo: "Com muitas dores o dei à luz".', 3, CURRENT_TIMESTAMP, false),
(13, 4, 10, 'Jabez orou ao Deus de Israel: "Ah, abençoa-me e aumenta as minhas terras! Que a tua mão esteja comigo, guardando-me de males e livrando-me de dores". E Deus atendeu ao seu pedido.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 11, 'Quelube, irmão de Suá, gerou Meir, pai de Estom.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 12, 'Estom gerou Bete-Rafa, Paséia e Teína, fundador de Ir-Naás. Esses habitaram em Reca.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 13, 'Estes foram os filhos de Quenaz: Otoniel e Seraías. Estes foram os filhos de Otoniel: Hatate e Meonotai.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 14, 'Meonotai gerou Ofra. Seraías gerou Joabe, fundador de Ge-Harasim que recebeu esse nome porque os seus habitantes eram artesãos.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 15, 'Estes foram os filhos de Calebe, filho de Jefoné: Iru, Elá e Naã. O filho de Elá foi Quenaz.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 16, 'Estes foram os filhos de Jealelel: Zife, Zifa, Tiria e Asareel.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 17, 'Estes foram os filhos de Ezra: Jéter, Merede, Éfer e Jalom. Merede casou-se com Bitia, filha do faraó, e teve os seguintes filhos: Miriã, Samai e Isbá, fundador de Estemoa.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 18, 'Sua mulher judia deu à luz a Jerede, fundador de Gedor, a Héber, fundador de Socó, e a Jecutiel, fundador de Zanoa.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 19, 'Estes foram os filhos da mulher de Hodias, irmã de Naã: o pai de Queila, o garmita, e Estemoa, o maacatita.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 20, 'Estes foram os filhos de Simão: Amnom, Rina, Bene-Hanã e Tilom. Estes foram os filhos de Isi: Zoete e Ben-Zoete.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 21, 'Estes foram os filhos de Selá, filho de Judá: Er, pai de Leca; Lada, pai de Maressa. Selá também foi antepassado dos clãs dos que trabalhavam com linho em Bete-Asbéia,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 22, 'de Joquim, dos homens de Cozeba, de Joás e de Sarafe, que governavam em Moabe e Jasubi-Leém. ( Estes registros são de épocas antigas. )', 3, CURRENT_TIMESTAMP, false),
(13, 4, 23, 'Eles eram oleiros e habitavam em Netaim e em Gederá, perto do rei, para quem trabalhavam.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 24, 'Estes foram os filhos de Simeão: Nemuel, Jamim, Jaribe, Zerá e Saul;', 3, CURRENT_TIMESTAMP, false),
(13, 4, 25, 'O filho de Saul era Salum, pai de Mibsão, que foi o pai de Misma.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 26, 'Estes foram os descendentes de Misma: seu filho Hamuel, pai de Zacur, que foi o pai de Simei.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 27, 'Simei teve dezesseis filhos e seis filhas, mas seus irmãos não tiveram muitos filhos; por isso todos os seus clãs não se igualam em número à tribo de Judá.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 28, 'Eles viviam em Berseba, Moladá, Hazar-Sual,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 29, 'Bila, Ezém, Tolade,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 30, 'Betuel, Hormá, Ziclague,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 31, 'Bete-Marcabote, Hazar-Susim, Bete-Biri e Saaraim. Essas foram as suas cidades até o reinado de Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 32, 'Tinham também as cinco cidades de Etã, Aim, Rimom, Toquém e Asã,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 33, 'com todos os povoados ao redor delas até Baalate. Nessas cidades viviam e mantinham um registro genealógico.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 34, 'Mesobabe, Janleque, Josa, filho de Amazias,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 35, 'Joel, Jeú, filho de Josibias, neto de Seraías e bisneto de Asiel;', 3, CURRENT_TIMESTAMP, false),
(13, 4, 36, 'também Elioenai, Jaacobá, Jesoaías, Asaías, Adiel, Jesimiel, Benaia,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 37, 'e Ziza, filho de Sifi, neto de Alom, bisneto de Jedaías, trineto de Sinri e tetraneto de Semaías.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 38, 'Essa é a lista dos líderes dos seus clãs. Suas famílias cresceram muito,', 3, CURRENT_TIMESTAMP, false),
(13, 4, 39, 'e por isso foram para os arredores de Gedor, a leste do vale, em busca de pastagens para os seus rebanhos.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 40, 'Encontraram muitas pastagens boas, numa região vasta, pacífica e tranqüila, onde alguns camitas tinham vivido anteriormente.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 41, 'Durante o reinado de Ezequias, rei de Judá, esses homens aqui alistados chegaram e atacaram os camitas e os meunitas da região e os destruíram totalmente, como até hoje se pode ver. Depois ocuparam o lugar daqueles povos, pois havia pastagens para os seus rebanhos.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 42, 'E quinhentos desses simeonitas, liderados por Pelatias, Nearias, Refaías e Uziel, filhos de Isi, invadiram as colinas de Seir.', 3, CURRENT_TIMESTAMP, false),
(13, 4, 43, 'Eles mataram o restante dos amalequitas que tinha escapado, e ali vivem até hoje.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 1, 'Estes são os filhos de Rúben, o filho mais velho de Israel. ( De fato, ele era o mais velho, mas, por ter desonrado o leito de seu pai, seus direitos de filho mais velho foram dados aos filhos de José, filho de Israel, de modo que não foi alistado nos registros genealógicos como o primeiro filho.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 2, 'Embora Judá tenha sido o mais poderoso de seus irmãos e dele tenha vindo um líder, os direitos de filho mais velho foram dados a José ).', 3, CURRENT_TIMESTAMP, false),
(13, 5, 3, 'Os filhos de Rúben, filho mais velho de Israel, foram: Enoque, Palu, Hezrom e Carmi.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 4, 'Estes foram os descendentes de Joel: Seu filho Semaías, pai de Gogue, que foi o pai de Simei,', 3, CURRENT_TIMESTAMP, false),
(13, 5, 5, 'pai de Mica, que foi o pai de Reaías, pai de Baal,', 3, CURRENT_TIMESTAMP, false),
(13, 5, 6, 'que foi o pai de Beera, a quem Tiglate-Pileser, rei da Assíria levou para o exílio. Beera era um líder da tribo de Rúben.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 7, 'Estes foram os parentes dele, de acordo com seus clãs, alistados conforme os seus registros genealógicos: Jeiel, o chefe, Zacarias', 3, CURRENT_TIMESTAMP, false),
(13, 5, 8, 'e Belá, filho de Azaz, neto de Sema e bisneto de Joel. Eles foram viver na região que vai desde Aroer até o monte Nebo e Baal-Meom.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 9, 'A leste ocuparam a terra que vai até o deserto que se estende na direção do rio Eufrates, pois os seus rebanhos tinham aumentado muito em Gileade.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 10, 'Durante o reinado de Saul eles entraram em guerra contra os hagarenos e os derrotaram, passando a ocupar o acampamento deles por toda a região a leste de Gileade.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 11, 'Ao lado da tribo de Rúben ficou a tribo de Gade, desde a região de Basã até Salcá.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 12, 'Joel foi o primeiro chefe de clãs em Basã, Safã, o segundo; os outros foram Janai e Safate.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 13, 'Estes foram os parentes deles, por famílias: Micael, Mesulão, Seba, Jorai, Jacã, Zia e Héber. Eram sete ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 14, 'Eles eram descendentes de Abiail, filho de Huri, neto de Jaroa, bisneto de Gileade e trineto de Micael, que foi filho de Jesisai, neto de Jado e bisneto de Buz.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 15, 'Aí, filho de Abdiel e neto de Guni, foi o chefe dessas famílias.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 16, 'A tribo de Gade habitou em Gileade, em Basã e seus povoados, e em toda a extensão das terras de pastagem de Sarom.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 17, 'Todos esses entraram nos registros genealógicos durante os reinados de Jotão, rei de Judá, e de Jeroboão, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 18, 'As tribos de Rúben, Gade e a metade da tribo de Manassés tinham juntas quarenta e quatro mil e setecentos e sessenta homens de combate, capazes de empunhar escudo e espada, de usar o arco, e treinados para a guerra.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 19, 'Eles entraram em guerra contra os hagarenos e seus aliados Jetur, Nafis e Nodabe.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 20, 'Durante a batalha clamaram a Deus, que os ajudou, entregando os hagarenos e todos os seus aliados nas suas mãos. Deus os atendeu, porque confiaram nele.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 21, 'Tomaram dos hagarenos o rebanho de cinqüenta mil camelos, duzentas e cinqüenta mil ovelhas e dois mil jumentos. Também fizeram cem mil prisioneiros.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 22, 'E muitos foram os inimigos mortos, pois a batalha era de Deus. Eles ocuparam aquela terra até a época do exílio.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 23, 'A metade da tribo de Manassés era numerosa e se estabeleceu na região que vai de Basã a Baal-Hermom, isto é, até Senir, o monte Hermom.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 24, 'Estes eram os chefes das famílias dessa tribo: Éfer, Isi, Eliel, Azriel, Jeremias, Hodavias e Jadiel. Eram soldados valentes, homens famosos, e chefes das famílias.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 25, 'Mas foram infiéis para com o Deus dos seus antepassados e se prostituíram, seguindo os deuses dos povos que Deus tinha destruído diante deles.', 3, CURRENT_TIMESTAMP, false),
(13, 5, 26, 'Por isso o Deus de Israel incitou Pul, que é Tiglate-Pileser, rei da Assíria, a levar as tribos de Rúben, de Gade e a metade da tribo de Manassés para Hala, para Habor, para Hara e para o rio Gozã, onde estão até hoje.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 1, 'Estes foram os filhos de Levi: Gérson, Coate e Merari.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 2, 'Estes foram os filhos de Coate: Anrão, Isar, Hebrom e Uziel.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 3, 'Estes foram os filhos de Anrão: Arão, Moisés e Miriã. Estes foram os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 4, 'Eleazar gerou Finéias, Finéias gerou Abisua,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 5, 'Abisua gerou Buqui, Buqui gerou Uzi,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 6, 'Uzi gerou Zeraías, Zeraías gerou Meraiote,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 7, 'Meraiote gerou Amarias, Amarias gerou Aitube,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 8, 'Aitube gerou Zadoque, Zadoque gerou Aimaás,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 9, 'Aimaás gerou Azarias, Azarias gerou Joanã,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 10, 'Joanã gerou Azarias que foi sacerdote no templo construído por Salomão em Jerusalém;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 11, 'Azarias gerou Amarias, Amarias gerou Aitube,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 12, 'Aitube gerou Zadoque, Zadoque gerou Salum,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 13, 'Salum gerou Hilquias, Hilquias gerou Azarias,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 14, 'Azarias gerou Seraías, e Seraías gerou Jeozadaque.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 15, 'Jeozadaque foi levado prisioneiro quando o Senhor enviou Judá e Jerusalém para o exílio por meio de Nabucodonosor.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 16, 'Estes foram os filhos de Levi: Gérson, Coate e Merari.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 17, 'Estes são os nomes dos filhos de Gérson: Libni e Simei.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 18, 'Estes foram os filhos de Coate: Anrão, Isar, Hebrom e Uziel.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 19, 'Estes foram os filhos de Merari: Mali e Musi. Estes são os clãs dos levitas alistados de acordo com os seus antepassados:', 3, CURRENT_TIMESTAMP, false),
(13, 6, 20, 'De Gérson: Seu filho Libni, que foi o pai de Jaate, pai de Zima,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 21, 'que foi o pai de Joá, pai de Ido, pai de Zerá, que foi o pai de Jeaterai.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 22, 'De Coate: Seu filho Aminadabe, pai de Corá, que foi o pai de Assir,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 23, 'pai de Elcana, pai de Ebiasafe, que foi o pai de Assir,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 24, 'pai de Taate, pai de Uriel, pai de Uzias, que foi o pai de Saul.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 25, 'De Elcana: Amasai, Aimote', 3, CURRENT_TIMESTAMP, false),
(13, 6, 26, 'e Elcana, pai de Zofai, pai de Naate,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 27, 'que foi o pai de Eliabe, pai de Jeroão, pai de Elcana, que foi o pai de Samuel.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 28, 'De Samuel: Joel, o mais velho, e Abias, o segundo.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 29, 'De Merari: Mali, pai de Libni, pai de Simei, que foi o pai de Uzá,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 30, 'pai de Siméia, pai de Hagias, que foi o pai de Asaías.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 31, 'Estes são os homens a quem Davi encarregou de dirigir os cânticos no templo do Senhor depois que a arca foi levada para lá.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 32, 'Eles ministravam o louvor diante do tabernáculo, da Tenda do Encontro, até quando Salomão construiu o templo do Senhor em Jerusalém. Eles exerciam suas funções de acordo com as normas estabelecidas.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 33, 'Estes são os que ministravam, junto com seus filhos: Dentre os coatitas: O músico Hemã, filho de Joel, filho de Samuel,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 34, 'filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 35, 'filho de Zufe, filho de Elcana, filho de Maate, filho de Amasai,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 36, 'filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias', 3, CURRENT_TIMESTAMP, false),
(13, 6, 37, 'filho de Taate, filho de Assir, filho de Ebiasafe, filho de Corá,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 38, 'filho de Isar, filho de Coate, filho de Levi, filho de Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 39, 'À direita de Hemã, ficava seu parente Asafe, filho de Berequias, filho de Siméia,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 40, 'filho de Micael, filho de Baaséias, filho de Malquias,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 41, 'filho de Etni, filho de Zerá, filho de Adaías,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 42, 'filho de Etã, filho de Zima, filho de Simei,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 43, 'filho de Jaate, filho de Gérson, filho de Levi.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 44, 'Dentre os meraritas: À esquerda de Hemã, parente dos meraritas, ficava Etã, filho de Quisi, filho de Abdi, filho de Maluque,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 45, 'filho de Hasabias, filho de Amazias, filho de Hilquias,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 46, 'filho de Anzi, filho de Bani, filho de Sêmer,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 47, 'filho de Mali, filho de Musi, filho de Merari, filho de Levi.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 48, 'Seus parentes, os outros levitas, foram encarregados de cuidar de todo o serviço do tabernáculo, o templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 49, 'Mas era Arão e seus descendentes que cuidavam dos sacrifícios no altar do holocausto e das ofertas no altar de incenso e de todo o serviço do Lugar Santíssimo, e dos sacrifícios de propiciação por Israel, conforme tudo o que Moisés, servo de Deus, tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 50, 'Estes foram os descendentes de Arão: o seu filho Eleazar, pai de Finéias, que foi o pai de Abisua,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 51, 'pai de Buqui, pai de Uzi, que foi o pai de Zeraías,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 52, 'pai de Meraiote, pai de Amarias, que foi o pai de Aitube,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 53, 'pai de Zadoque, pai de Aimaás.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 54, 'Estas foram as cidades e as regiões dadas aos levitas para nelas habitarem. Dentre os descendentes de Arão, o clã coatita foi sorteado primeiro;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 55, 'foi-lhe dada Hebrom, em Judá, com suas pastagens ao redor.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 56, 'Mas os campos e os povoados em torno da cidade foram dados a Calebe, filho de Jefoné.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 57, 'Assim os descendentes de Arão receberam Hebrom, cidade de refúgio, e Libna, Jatir, Estemoa,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 58, 'Hilém, Debir,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 59, 'Asã, Jutá e Bete-Semes, com suas respectivas pastagens.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 60, 'E da tribo de Benjamim receberam Gibeão, Geba, Alemete e Anatote, com suas respectivas pastagens. Ao todo treze cidades foram distribuídas entre os seus clãs.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 61, 'Para os demais descendentes de Coate foram sorteadas dez cidades pertencentes aos clãs da metade da tribo de Manassés.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 62, 'Para os descendentes de Gérson, clã por clã, foram sorteadas treze cidades das tribos de Issacar, de Aser e de Naftali, e da metade da tribo de Manassés que fica em Basã.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 63, 'Para os descendentes de Merari, clã por clã, foram sorteadas doze cidades das tribos de Rúben, de Gade e de Zebulom.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 64, 'Assim os israelitas deram aos levitas essas cidades com suas respectivas pastagens.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 65, 'As cidades anteriormente mencionadas dos territórios de Judá, de Simeão e de Benjamim também lhes foram dadas por sorteio.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 66, 'Alguns dos clãs coatitas receberam as seguintes cidades no território da tribo de Efraim:', 3, CURRENT_TIMESTAMP, false),
(13, 6, 67, 'Siquém, cidade de refúgio, nos montes de Efraim, e Gezer,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 68, 'Jocmeão, Bete-Horom,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 69, 'Aijalom e Gate-Rimom, com suas respectivas pastagens.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 70, 'E da metade da tribo de Manassés o restante dos clãs coatitas recebeu Aner e Bileã, com suas respectivas pastagens.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 71, 'Os gersonitas receberam as seguintes cidades: Do clã da meia tribo de Manassés, Golã, em Basã, e também Asterote, com suas respectivas pastagens;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 72, 'da tribo de Issacar, Quedes, Daberate,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 73, 'Ramote e Aném, com suas respectivas pastagens;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 74, 'da tribo de Aser, Masal, Abdom,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 75, 'Hucoque e Reobe, com suas respectivas pastagens;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 76, 'e da tribo de Naftali, Quedes, na Galiléia, Hamom e Quiriataim, com suas respectivas pastagens.', 3, CURRENT_TIMESTAMP, false),
(13, 6, 77, 'E estas foram as cidades que os outros meraritas receberam: Da tribo de Zebulom, Rimono e Tabor, com suas respectivas pastagens;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 78, 'da tribo de Rúben, do outro lado do Jordão, a leste de Jericó, Bezer, no deserto, Jaza,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 79, 'Quedemote e Mefaate, com suas respectivas pastagens;', 3, CURRENT_TIMESTAMP, false),
(13, 6, 80, 'e da tribo de Gade, Ramote, em Gileade, Maanaim,', 3, CURRENT_TIMESTAMP, false),
(13, 6, 81, 'Hesbom e Jazar, com suas respectivas pastagens.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 1, 'Estes foram os quatro filhos de Issacar: Tolá, Puá, Jasube e Sinrom.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 2, 'Estes foram os filhos de Tolá: Uzi, Refaías, Jeriel, Jamai, Ibsão e Samuel, chefes dos seus clãs. No reinado de Davi, os descendentes de Tolá alistados em suas genealogias como homens de combate chegavam a 22. 600.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 3, 'O filho de Uzi foi Israías. Estes foram os filhos de Israías: Micael, Obadias, Joel e Issias. Todos os cinco eram chefes', 3, CURRENT_TIMESTAMP, false),
(13, 7, 4, 'que tinham muitas mulheres e filhos. Por isso, conforme a genealogia de sua família, eles contavam com 36. 000 homens prontos para o combate.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 5, 'Juntamente com seus parentes, os homens de combate de todos os clãs de Issacar, conforme alistados em sua genealogia, chegavam ao todo a 87. 000.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 6, 'Estes foram os três filhos de Benjamim: Belá, Bequer e Jediael.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 7, 'Estes foram os filhos de Belá: Esbom, Uzi, Uziel, Jeremote e Iri, cinco chefes de famílias. Seu registro genealógico alistava 22. 034 homens de combate.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 8, 'Estes foram os filhos de Bequer: Zemira, Joás, Eliézer, Elioenai, Onri, Jeremote, Abias, Anatote e Alemete. Todos esses eram filhos de Bequer.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 9, 'O registro genealógico deles alistava os chefes de famílias e 20. 200 homens de combate.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 10, 'O filho de Jediael foi Bilã. Estes foram os filhos de Bilã: Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis e Aisaar.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 11, 'Todos esses descendentes de Jediael eram chefes de famílias que contavam com 17. 200 homens de combate prontos para a guerra.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 12, 'Supim e Hupim eram filhos de Ir; e Husim era filho de Aer.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 13, 'Estes foram os filhos de Naftali: Jaziel, Guni, Jezer e Silém, netos de Bila.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 14, 'Estes foram os descendentes de Manassés: Asriel, filho de sua concubina araméia, que também deu à luz Maquir, pai de Gileade.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 15, 'Maquir casou-se com Maaca, irmã de Hupim e Supim. Outro descendente de Manassés chamava-se Zelofeade, o qual só teve filhas.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 16, 'Maaca, mulher de Maquir, deu à luz um filho, a quem deu o nome de Perez. O nome de seu irmão era Seres, cujos filhos chamavam-se Ulão e Requém.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 17, 'O filho de Ulão foi Bedã. Esses foram os descendentes de Gileade, filho de Maquir, e neto de Manassés.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 18, 'Sua irmã Hamolequete deu à luz Isode, Abiezer e Maalá.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 19, 'Estes foram os filhos de Semida: Aiã, Siquém, Liqui e Anião.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 20, 'Estes foram os descendentes de Efraim: Sutela, que foi o pai de Berede, pai de Taate, pai de Eleada, que foi o pai de Taate,', 3, CURRENT_TIMESTAMP, false),
(13, 7, 21, 'pai de Zabade, pai de Sutela. Ézer e Eleade, filhos de Efraim, foram mortos por homens da cidade de Gate, quando tentavam roubar os rebanhos deles.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 22, 'Efraim chorou muitos dias por eles, e seus parentes vieram consolá-lo.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 23, 'Depois ele se deitou de novo com sua mulher, e ela engravidou e deu à luz um filho. Ele o chamou Berias, pois tinha acontecido uma desgraça em sua família.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 24, 'Sua filha chamava-se Seerá. Foi ela que fundou Bete-Horom Alta e Bete-Horom Baixa e também Uzém-Seerá.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 25, 'O filho de Berias foi Refa, pai de Resefe, que foi o pai de Telá, pai de Taã,', 3, CURRENT_TIMESTAMP, false),
(13, 7, 26, 'pai de Ladã, pai de Amiúde, que foi o pai de Elisama,', 3, CURRENT_TIMESTAMP, false),
(13, 7, 27, 'pai de Num, que foi o pai de Josué.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 28, 'Suas terras e cidades incluíam Betel e os povoados ao redor, Naarã a leste, Gezer e seus povoados a oeste, e Siquém e Aiá com os seus povoados.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 29, 'A tribo de Manassés controlava as cidades de Bete-Seã, Taanaque, Megido e Dor, com seus respectivos povoados. Os descendentes de José, filho de Israel, viviam nessas cidades.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 30, 'Estes foram os filhos de Aser: Imna, Isvá, Isvi e Berias. A irmã deles chamava-se Sera.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 31, 'Estes foram os filhos de Berias: Héber e Malquiel, que foi o pai de Birzavite.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 32, 'Héber gerou Jaflete, Somer e Hotão, e da irmã deles, Suá.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 33, 'Estes foram os filhos de Jaflete: Pasaque, Bimal e Asvate. Esses foram os filhos de Jaflete.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 34, 'Estes foram os filhos de Somer: Aí, Roga, Jeubá e Arã.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 35, 'Estes foram os filhos de Helém, irmão de Somer: Zofa, Imna, Seles e Amal.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 36, 'Estes foram os filhos de Zofa: Suá, Harnefer, Sual, Beri, Inra,', 3, CURRENT_TIMESTAMP, false),
(13, 7, 37, 'Bezer, Hode, Samá, Silsa, Itrã e Beera.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 38, 'Estes foram os filhos de Jéter: Jefoné, Pispa e Ara.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 39, 'Estes foram os filhos de Ula: Ara, Haniel e Rizia.', 3, CURRENT_TIMESTAMP, false),
(13, 7, 40, 'Todos esses foram descendentes de Aser. Eram chefes de famílias, homens escolhidos, soldados valentes e líderes de destaque. O número dos alistados para combate no exército deles chegou a 26. 000.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 1, 'Benjamim gerou Belá, seu filho mais velho; Asbel, seu segundo filho, Aará, o terceiro,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 2, 'Noá, o quarto, e Rafa, o quinto.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 3, 'Estes foram os filhos de Belá: Adar, Gera, pai de Eúde,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 4, 'Abisua, Naamã, Aoá,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 5, 'Gera, Sefufá e Hurão.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 6, 'Estes foram os descendentes de Eúde, chefes das famílias dos habitantes de Geba, que foram deportados para Manaate:', 3, CURRENT_TIMESTAMP, false),
(13, 8, 7, 'Naamã, Aías e Gera. Esse Gera, pai de Uzá e de Aiúde, foi quem os deportou.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 8, 'Depois de ter se divorciado de suas mulheres Husim e Baara, Saaraim teve filhos na terra de Moabe.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 9, 'Com sua mulher Hodes ele gerou Jobabe, Zíbia, Messa, Malcã,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 10, 'Jeús, Saquias e Mirma. Esses foram seus filhos, chefes de famílias.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 11, 'Com Husim ele gerou Abitube e Elpaal.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 12, 'Estes foram os filhos de Elpaal: Héber, Misã, Semede, que fundou Ono e Lode com seus povoados.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 13, 'Berias e Sema foram os chefes das famílias dos habitantes de Aijalom, e foram eles que expulsaram os habitantes de Gate.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 14, 'Aiô, Sasaque, Jeremote,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 15, 'Zebadias, Arade, Éder,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 16, 'Micael, Ispa e Joá foram descendentes de Berias.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 17, 'Zebadias, Mesulão, Hizqui, Héber,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 18, 'Ismerai, Izlias e Jobabe foram descendentes de Elpaal.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 19, 'Jaquim, Zicri, Zabdi,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 20, 'Elienai, Ziletai, Eliel,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 21, 'Adaías, Beraías e Sinrate foram descendentes de Simei.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 22, 'Ispã, Héber, Eliel,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 23, 'Abdom, Zicri, Hanã,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 24, 'Hananias, Elão, Antotias,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 25, 'Ifdéias e Penuel foram descendentes de Sasaque.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 26, 'Sanserai, Searias, Atalias,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 27, 'Jaaresias, Elias e Zicri foram descendentes de Jeroão.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 28, 'Todos esses foram chefes de famílias, líderes conforme alistados em suas genealogias, e moravam em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 29, 'Jeiel, pai de Gibeom morou na cidade de Gibeom. O nome de sua mulher era Maaca,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 30, 'o de seu filho mais velho, Abdom, e o de seus outros filhos, Zur, Quis, Baal, Ner, Nadabe,', 3, CURRENT_TIMESTAMP, false),
(13, 8, 31, 'Gedor, Aiô, Zequer', 3, CURRENT_TIMESTAMP, false),
(13, 8, 32, 'e Miclote, que gerou Siméia. Eles também moravam perto de seus parentes, em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 33, 'Ner gerou Quis, que gerou Saul. Saul gerou Jônatas, Malquisua, Abinadabe e Esbaal.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 34, 'O filho de Jônatas foi Meribe-Baal, que gerou Mica.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 35, 'Estes foram os filhos de Mica: Pitom, Meleque, Taréia e Acaz.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 36, 'Acaz gerou Jeoada, Jeoada gerou Alemete, Azmavete e Zinri, e Zinri gerou Mosa.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 37, 'Mosa gerou Bineá, pai de Rafa, que foi o pai de Eleasa, pai de Azel.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 38, 'Azel teve seis filhos chamados Azricão, Bocru, Ismael, Searias, Obadias e Hanã. Todos esses foram filhos de Azel.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 39, 'Estes foram os filhos de Eseque, seu irmão: Ulão, o mais velho, Jeús, o segundo e Elifelete, o terceiro.', 3, CURRENT_TIMESTAMP, false),
(13, 8, 40, 'Os filhos de Ulão eram soldados valentes e bons flecheiros. Tiveram muitos filhos e netos; eram cento e cinqüenta ao todo. Todos esses foram descendentes de Benjamim.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 1, 'Todos os israelitas foram alistados nas genealogias dos registros históricos dos reis de Israel. O povo de Judá foi levado prisioneiro para a Babilônia por sua infidelidade.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 2, 'Os primeiros a voltarem às suas propriedades e às suas cidades foram algumas pessoas do povo e alguns sacerdotes, levitas e servidores do templo.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 3, 'Os de Judá, de Benjamim e de Efraim e Manassés que se instalaram em Jerusalém foram:', 3, CURRENT_TIMESTAMP, false),
(13, 9, 4, 'Utai, filho de Amiúde, neto de Onri, bisneto de Inri e trineto de Bani, um descendente de Perez, filho de Judá.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 5, 'Dos descendentes de Selá: O primogênito Asaías com seus filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 6, 'Dos descendentes de Zerá: Jeuel. Os de Judá chegaram a 690.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 7, 'Dos benjamitas: Salu, filho de Mesulão, neto de Hodavias e bisneto de Hassenua;', 3, CURRENT_TIMESTAMP, false),
(13, 9, 8, 'Ibnéias, filho de Jeroão; Elá, filho de Uzi, filho de Micri; e Mesulão, filho de Sefatias, filho de Reuel, filho de Ibnias.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 9, 'Da tribo de Benjamim, relacionados em sua genealogia, eram 956. Todos esses homens eram chefes de suas famílias.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 10, 'Dos sacerdotes: Jedaías, Jeoiaribe, Jaquim;', 3, CURRENT_TIMESTAMP, false),
(13, 9, 11, 'Azarias, filho de Hilquias, neto de Mesulão, bisneto de Zadoque, trineto de Meraiote e tetraneto de Aitube, o líder encarregado do templo de Deus;', 3, CURRENT_TIMESTAMP, false),
(13, 9, 12, 'Adaías, filho de Jeroão, neto de Pasur e bisneto de Malquias; e Masai, filho de Adiel, neto de Jazera, bisneto de Mesulão, trineto de Mesilemite e tetraneto de Imer.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 13, 'O número de sacerdotes que eram chefes de famílias era 1. 760. Eram homens capazes, e sua responsabilidade era ministrar no templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 14, 'Dos levitas: Semaías, filho de Hassube, neto de Azricão e bisneto de Hasabias, um merarita;', 3, CURRENT_TIMESTAMP, false),
(13, 9, 15, 'Baquebacar, Heres, Galal e Matanias, filho de Mica, neto de Zicri e bisneto de Asafe;', 3, CURRENT_TIMESTAMP, false),
(13, 9, 16, 'Obadias, filho de Semaías, neto de Galal e bisneto de Jedutum; e Berequias, filho de Asa e neto de Elcana, que vivia nos povoados dos netofatitas.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 17, 'Os guardas das portas eram: Salum, o chefe, Acube, Talmom, Aimã e os irmãos deles, sendo até hoje', 3, CURRENT_TIMESTAMP, false),
(13, 9, 18, 'os guardas da porta do Rei, a leste. Salum era o chefe. Esses eram os guardas das portas que pertenciam ao acampamento dos levitas.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 19, 'Salum, filho de Coré, neto de Ebiasafe e bisneto de Corá, e seus parentes, os coreítas, guardas das portas, responsáveis por guardar as entradas da Tenda, como os seus antepassados tinham sido responsáveis por guardar a entrada da habitação do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 20, 'Naquela época, Finéias, filho de Eleazar, estivera encarregado dos guardas das portas, e o Senhor estava com ele.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 21, 'Zacarias, filho de Meselemias, era o guarda das portas da entrada da Tenda do Encontro.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 22, 'A soma total dos escolhidos para serem guardas das portas, registrados nas genealogias dos seus povoados, era de 212. Eles haviam sido designados para esses postos de confiança por Davi e pelo vidente Samuel.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 23, 'Eles e os seus descendentes foram encarregados de vigiar as portas do templo do Senhor, o templo chamado Tenda.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 24, 'Os guardas vigiavam as portas nos quatro lados: norte, sul, leste e oeste.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 25, 'Seus parentes, residentes em seus povoados, tinham que vir de tempos em tempos e trabalhar com eles por períodos de sete dias.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 26, 'Mas os quatro principais guardas das portas, que eram levitas, receberam a responsabilidade de tomar conta das salas e da tesouraria do templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 27, 'Eles passavam a noite perto do templo de Deus, pois tinham o dever de vigiá-la e de abrir as portas todas as manhãs.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 28, 'Alguns levitas estavam encarregados dos utensílios utilizados no culto no templo; eles os contavam quando eram retirados e quando eram devolvidos.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 29, 'Outros eram responsáveis pelos móveis e por todos os demais utensílios do santuário, bem como pela farinha, pelo vinho, pelo óleo, pelo incenso e pelas especiarias.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 30, 'E ainda outros cuidavam da manipulação das especiarias.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 31, 'Um levita chamado Matitias, filho mais velho do coreíta Salum, tinha a responsabilidade de assar os pães para as ofertas.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 32, 'E dentre os coatitas, seus irmãos, alguns estavam encarregados de preparar os pães que são postos sobre a mesa todo sábado.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 33, 'Os cantores, chefes de famílias levitas, permaneciam nas salas do templo e estavam isentos de outros deveres, pois dia e noite se dedicavam à sua própria tarefa.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 34, 'Todos esses eram chefes de famílias levitas, alistados como líderes em suas genealogias, e moravam em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 35, 'Jeiel, pai de Gibeom, morava em Gibeom. O nome de sua mulher era Maaca,', 3, CURRENT_TIMESTAMP, false),
(13, 9, 36, 'e o de seu filho mais velho, Abdom. Depois nasceram Zur, Quis, Baal, Ner, Nadabe,', 3, CURRENT_TIMESTAMP, false),
(13, 9, 37, 'Gedor, Aiô, Zacarias e Miclote.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 38, 'Miclote gerou Siméia. Eles também moravam perto de seus parentes em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 39, 'Ner gerou Quis, Quis gerou Saul, Saul gerou Jônatas, Malquisua, Abinadabe e Esbaal.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 40, 'Este foi o filho de Jônatas: Meribe-Baal, que gerou Mica.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 41, 'Estes foram os filhos de Mica: Pitom, Meleque, Taréia e Acaz.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 42, 'Acaz gerou Jadá, Jadá gerou Alemete, Azmavete e Zinri, e Zinri gerou Mosa.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 43, 'Mosa gerou Bineá, cujo filho foi Refaías, o filho deste foi Eleasa, pai de Azel.', 3, CURRENT_TIMESTAMP, false),
(13, 9, 44, 'Azel teve seis filhos, e os nomes deles foram: Azricão, Bocru, Ismael, Searias, Obadias e Hanã. Esses foram os filhos de Azel.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 1, 'E aconteceu que, em combate com os filisteus, os israelitas foram postos em fuga, e muitos caíram mortos no monte Gilboa.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 2, 'Os filisteus perseguiram Saul e seus filhos, e mataram Jônatas, Abinadabe e Malquisua, filhos de Saul.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 3, 'O combate foi se tornando cada vez mais violento em torno de Saul, até que os flecheiros o alcançaram e o feriram gravemente.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 4, 'Então Saul ordenou ao seu escudeiro: "Tire sua espada e mate-me com ela, senão sofrerei a vergonha de cair nas mãos desses incircuncisos". Mas o seu escudeiro estava apavorado e não quis fazê-lo. Saul, então, apanhou a própria espada e jogou-se sobre ela.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 5, 'Quando o escudeiro viu que Saul estava morto, jogou-se também sobre sua espada e morreu.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 6, 'Dessa maneira Saul e seus três filhos morreram, e, assim, toda a descendência real.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 7, 'Quando os israelitas que habitavam no vale viram que o exército tinha fugido e que Saul e seus filhos estavam mortos, fugiram abandonando suas cidades. Depois os filisteus foram ocupá-las.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 8, 'No dia seguinte, quando os filisteus foram saquear os mortos, encontraram Saul e seus filhos caídos no monte Gilboa.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 9, 'Cortaram a cabeça de Saul, pegaram suas armas e enviaram mensageiros por toda a terra dos filisteus proclamando a notícia entre os seus ídolos e o seu povo.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 10, 'Expuseram suas armas num dos templos dos seus deuses e penduraram sua cabeça no templo de Dagom.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 11, 'Quando os habitantes de Jabes-Gileade ficaram sabendo o que os filisteus haviam feito com Saul,', 3, CURRENT_TIMESTAMP, false),
(13, 10, 12, 'os mais corajosos dentre eles foram e apanharam os corpos de Saul e de seus filhos e os levaram a Jabes. Lá sepultaram seus ossos sob a Grande Árvore, e jejuaram por sete dias.', 3, CURRENT_TIMESTAMP, false),
(13, 10, 13, 'Saul morreu porque foi infiel ao Senhor; não guardou a palavra do Senhor e chegou a consultar uma médiun em busca de orientação,', 3, CURRENT_TIMESTAMP, false),
(13, 10, 14, 'em vez de consultar o Senhor. Por isso o Senhor o entregou à morte e deu o reino a Davi, filho de Jessé.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 1, 'Todo o Israel reuniu-se com Davi em Hebrom e disse: "Somos sangue do teu sangue.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 2, 'No passado, mesmo quando Saul era rei, eras tu quem liderava Israel em suas batalhas. E o Senhor, o teu Deus, te disse: ‘Você pastoreará o meu povo Israel, e será o seu governante’ ".', 3, CURRENT_TIMESTAMP, false),
(13, 11, 3, 'Então todas as autoridades de Israel foram ao encontro do rei Davi em Hebrom, e ele fez um acordo com eles em Hebrom perante o Senhor, e eles ungiram Davi rei de Israel, conforme o Senhor havia anunciado por meio de Samuel.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 4, 'Davi e todos os israelitas marcharam para Jerusalém, que é Jebus. Os jebuseus, habitantes da cidade,', 3, CURRENT_TIMESTAMP, false),
(13, 11, 5, 'disseram a Davi: "Você não entrará aqui". No entanto, Davi conquistou a fortaleza de Sião, a cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 6, 'Naquele dia Davi tinha dito: "O primeiro que atacar os jebuseus se tornará o comandante do exército". Joabe, filho de Zeruia, foi o primeiro, e por isso recebeu o comando do exército.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 7, 'Davi passou a morar na fortaleza, e por isso ela foi chamada cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 8, 'Ele reconstruiu a cidade ao redor da fortaleza, desde os muros de arrimo até os muros ao redor, e Joabe restaurou o restante da cidade.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 9, 'E Davi foi se tornando cada vez mais poderoso, pois o Senhor dos Exércitos estava com ele.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 10, 'Estes foram os chefes dos principais guerreiros de Davi, que junto com todo Israel, deram um grande apoio para estender o seu reinado a todo o país, conforme o Senhor havia prometido.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 11, 'Esta é a lista deles: Jasobeão, um hacmonita, era o chefe dos oficiais; foi ele que, empunhando sua lança, matou trezentos homens numa mesma batalha.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 12, 'Depois, Eleazar, filho de Dodô, de Aoí, um dos três principais guerreiros.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 13, 'Ele estava com Davi na plantação de cevada de Pas-Damim, onde os filisteus se reuniram para a guerra. As tropas israelitas fugiram dos filisteus,', 3, CURRENT_TIMESTAMP, false),
(13, 11, 14, 'mas eles mantiveram sua posição no meio da plantação. Eles o defenderam e feriram os filisteus, e o Senhor lhes deu uma grande vitória.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 15, 'Quando um grupo de filisteus estava acampado no vale de Refaim, três chefes do pelotão dos trinta foram encontrar Davi na rocha que há perto da caverna de Adulão.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 16, 'Estando Davi nessa fortaleza, e o destacamento filisteu em Belém,', 3, CURRENT_TIMESTAMP, false),
(13, 11, 17, 'Davi expressou seu desejo: "Quem me dera me trouxessem água da cisterna que fica junto à porta de Belém! "', 3, CURRENT_TIMESTAMP, false),
(13, 11, 18, 'Então aqueles três infiltraram-se no acampamento filisteu, tiraram água daquela cisterna e a trouxeram a Davi. Mas ele se recusou a beber; em vez disso, derramou-a como uma oferta ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 19, '"Longe de mim fazer isso, ó meu Deus! ", disse Davi. "Esta água representa o sangue desses homens que arriscaram a própria vida! " Eles arriscaram a vida para trazê-la. E não quis bebê-la. Foram essas as proezas dos três principais guerreiros.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 20, 'Abisai, o irmão de Joabe, era o chefe do batalhão dos trinta. Com uma lança enfrentou trezentos homens e os matou, tornando-se tão famoso quanto os três.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 21, 'Foi honrado duas vezes mais do que o batalhão dos trinta, e se tornou chefe deles, mas nunca igualou-se aos três principais guerreiros.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 22, 'Benaia, filho de Joiada, era um corajoso soldado de Cabzeel, e realizou grandes feitos. Matou dois dos melhores guerreiros de Moabe e, num dia de neve, desceu em uma cova e matou um leão.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 23, 'Também matou um egípcio de dois metros e vinte e cinco centímetros de altura. Embora o egípcio tivesse na mão uma lança parecida com uma lançadeira de tecelão, Benaia o enfrentou com um cajado. Arrancou a lança da mão do egípcio e com ela o matou.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 24, 'Esses foram os grandes feitos de Benaia, filho de Joiada, que também foi tão famoso quanto os três principais guerreiros de Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 25, 'Foi mais honrado do que qualquer dos trinta, mas nunca igualou-se aos três. E Davi lhe deu o comando da sua guarda pessoal.', 3, CURRENT_TIMESTAMP, false),
(13, 11, 26, 'Os outros guerreiros foram: Asael, irmão de Joabe; Elanã, filho de Dodô, de Belém;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 27, 'Samote, de Haror; Helez, de Pelom;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 28, 'Ira, filho de Iques, de Tecoa; Abiezer, de Anatote;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 29, 'Sibecai, de Husate; Ilai, de Aoí;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 30, 'Maarai, de Netofate; Helede, filho de Baaná, de Netofate;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 31, 'Itai, filho de Ribai, de Gibeá de Benjamim; Benaia, de Piratom;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 32, 'Hurai, dos riachos de Gaás; Abiel, de Arbate;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 33, 'Azmavete, de Baarum; Eliaba, de Saalbom;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 34, 'os filhos de Hasém, de Gizom; Jônatas, filho de Sage, de Harar;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 35, 'Aião, filho de Sacar, de Harar; Elifal, filho de Ur;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 36, 'Héfer, de Mequerate; Aías, de Pelom;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 37, 'Hezro, de Carmelo; Naarai, filho de Ezbai;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 38, 'Joel, irmão de Natã; Mibar, filho de Hagri;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 39, 'o amonita Zeleque; Naarai, de Beerote, escudeiro de Joabe, filho de Zeruia;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 40, 'Ira e Garebe, de Jatir;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 41, 'Urias, o hitita; Zabade, filho de Alai;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 42, 'Adina, filho de Siza, de Rúben, chefe dos rubenitas e do grupo dos trinta;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 43, 'Hanã, filho de Maaca; Josafá, de Mitene;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 44, 'Uzia, de Asterate; Sama e Jeiel, filhos de Hotão, de Aroer;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 45, 'Jediael, filho de Sinri; seu irmão, Joá, de Tiz;', 3, CURRENT_TIMESTAMP, false),
(13, 11, 46, 'Eliel, de Maave; Jeribai e Josavias, filhos de Elnaão; Itma, um moabita,', 3, CURRENT_TIMESTAMP, false),
(13, 11, 47, 'e Eliel, Obede e Jaasiel, de Mezoba.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 1, 'Estes são os que se juntaram a Davi em Ziclague, onde se escondia de Saul, filho de Quis. Eles estavam entre os combatentes que o ajudaram na guerra;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 2, 'utilizavam arco e flecha e a funda para atirar pedras tanto com a mão direita como com a esquerda; pertenciam à tribo de Benjamim e eram parentes de Saul:', 3, CURRENT_TIMESTAMP, false),
(13, 12, 3, 'Aiezer, o chefe deles, e Joás, filhos de Semaá, de Gibeate; Jeziel e Pelete, filhos de Azmavete; Beraca, Jeú, de Anatote,', 3, CURRENT_TIMESTAMP, false),
(13, 12, 4, 'e Ismaías, de Gibeom, um grande guerreiro do pelotão dos trinta, e chefe deles; Jeremias, Jaaziel, Joanã, Jozabade, de Gederate,', 3, CURRENT_TIMESTAMP, false),
(13, 12, 5, 'Eluzai, Jeremote, Bealías, Semarias e Sefatias, de Harufe;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 6, 'os coreítas Elcana, Issias, Azareel, Joezer e Jasobeão;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 7, 'e Joela e Zebadias, filhos de Jeroão de Gedor.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 8, 'Da tribo de Gade alguns aliaram-se a Davi em sua fortaleza no deserto. Eram guerreiros corajosos, prontos para o combate, e sabiam lutar com escudo e com lança. Tinham a bravura de um leão, e eram ágeis como gazelas nos montes.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 9, 'Ézer era o primeiro; Obadias, o segundo; Eliabe, o terceiro;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 10, 'Mismana, o quarto; Jeremias, o quinto;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 11, 'Atai, o sexto; Eliel, o sétimo;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 12, 'Joanã, o oitavo; Elzabade, o nono;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 13, 'Jeremias, o décimo; e Macbanai era o décimo primeiro.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 14, 'Todos esses de Gade eram chefes de exército; o menor valia por cem, e o maior enfrentava mil.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 15, 'Foram eles que atravessaram o Jordão no primeiro mês do ano, quando o rio transborda em todas as suas margens, e puseram em fuga todos os que moravam nos vales, a leste e a oeste.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 16, 'Alguns outros benjamitas e certos homens de Judá também vieram a Davi em sua fortaleza.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 17, 'Davi saiu ao encontro deles e lhes disse: "Se vocês vieram em paz, para me ajudarem, estou pronto para recebê-los. Mas, se querem trair-me e entregar-me aos meus inimigos quando minhas mãos não cometeram violência, que o Deus de nossos antepassados veja isso e julgue vocês".', 3, CURRENT_TIMESTAMP, false),
(13, 12, 18, 'Então o Espírito veio sobre Amasai, chefe do pelotão dos trinta, e ele disse: "Somos teus, ó Davi! Estamos contigo, ó filho de Jessé! Paz, paz seja contigo, e aos teus aliados, pois o teu Deus te ajudará". Davi os recebeu e os nomeou chefes de seus grupos de ataque.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 19, 'Alguns soldados de Manassés desertaram para Davi quando ele foi com os filisteus guerrear contra Saul. Mas eles não ajudaram os filisteus, porque os seus chefes os aconselharam e os mandaram embora, dizendo: "Pagaremos com a vida, caso Davi deserte e passe para Saul, seu senhor".', 3, CURRENT_TIMESTAMP, false),
(13, 12, 20, 'Estes foram os homens de Manassés que desertaram para Davi quando ele foi a Ziclague: Adna, Jozabade, Jediael, Micael, Jozabade, Eliú e Ziletai, chefes de batalhões de mil em Manassés.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 21, 'Eles ajudaram Davi contra grupos de ataque, pois todos eles eram guerreiros valentes, e eram líderes no exército dele.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 22, 'De fato, diariamente chegavam soldados para ajudar Davi, até que seu exército tornou-se tão grande como o exército de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 23, 'Este é o número dos soldados armados para a guerra que vieram a Davi em Hebrom para entregar a ele o reino de Saul, conforme o Senhor tinha dito:', 3, CURRENT_TIMESTAMP, false),
(13, 12, 24, 'Da tribo de Judá, 6. 800 armados para a guerra, com escudo e lança;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 25, 'Da tribo de Simeão, 7. 100 guerreiros prontos para o combate;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 26, 'Da tribo de Levi, 4. 600,', 3, CURRENT_TIMESTAMP, false),
(13, 12, 27, 'inclusive Joiada, líder da família de Arão, com 3. 700 homens,', 3, CURRENT_TIMESTAMP, false),
(13, 12, 28, 'e Zadoque, um jovem e valente guerreiro, com 22 oficiais de sua família;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 29, 'Da tribo de Benjamim, parentes de Saul, 3. 000, a maioria dos quais era até então fiel à família de Saul;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 30, 'Da tribo de Efraim, 20. 800 soldados valentes, famosos em seus próprios clãs;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 31, 'Da metade da tribo de Manassés, 18. 000, indicados por nome para fazerem Davi rei;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 32, 'Da tribo de Issacar, 200 chefes que sabiam como Israel devia agir em qualquer circunstância. Comandavam todos os seus parentes;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 33, 'Da tribo de Zebulom, 50. 000 soldados experientes, preparados para guerrear com qualquer tipo de arma, totalmente decididos a ajudar Davi;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 34, 'Da tribo de Naftali, 1. 000 líderes com 37. 000 homens armados de escudos e lanças;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 35, 'Da tribo de Dã, 28. 600 prontos para o combate;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 36, 'Da tribo de Aser, 40. 000 soldados experientes, preparados para o combate;', 3, CURRENT_TIMESTAMP, false),
(13, 12, 37, 'e do leste do Jordão, das tribos de Rúben e de Gade, e da metade da tribo de Manassés, 120. 000 completamente armados.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 38, 'Todos esses eram homens de combate que se apresentaram voluntariamente para servirem nas fileiras. Foram a Hebrom totalmente decididos a fazerem de Davi rei sobre todo o Israel. E todos os outros israelitas tinham esse mesmo propósito.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 39, 'Ficaram com Davi três dias, comendo e bebendo, pois as suas famílias haviam fornecido provisões para eles.', 3, CURRENT_TIMESTAMP, false),
(13, 12, 40, 'Os habitantes das tribos vizinhas e também de lugares distantes como Issacar, Zebulom e Naftali, trouxeram-lhes muitas provisões em jumentos, camelos, mulas e bois: farinha, bolos de figo, bolos de uvas passas, vinho, azeite, bois e ovelhas, pois havia grande alegria em Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 1, 'Depois de consultar todos os seus oficiais, os comandantes de mil e de cem,', 3, CURRENT_TIMESTAMP, false),
(13, 13, 2, 'Davi disse a toda a assembléia de Israel: "Se vocês estão de acordo e se esta é a vontade do Senhor nosso Deus, enviemos uma mensagem a nossos irmãos em todo o território de Israel, e também aos sacerdotes e aos levitas que estão com eles em suas cidades, para virem unir-se a nós.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 3, 'Vamos trazer de volta a arca de nosso Deus, pois não nos importamos com ela durante o reinado de Saul".', 3, CURRENT_TIMESTAMP, false),
(13, 13, 4, 'Toda a assembléia concordou, pois isso pareceu bem a todo o povo.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 5, 'Então Davi reuniu todos os israelitas, desde o rio Sior, no Egito, até Lebo-Hamate, para trazerem de Quiriate-Jearim a arca de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 6, 'Davi e todos os israelitas foram a Baalá, que é Quiriate-Jearim, em Judá, para buscar a arca de Deus, o Senhor, entronizado entre os querubins; a arca sobre a qual seu nome é invocado.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 7, 'Da casa de Abinadabe levaram a arca de Deus num carroção novo, conduzido por Uzá e Aiô.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 8, 'Davi e todos os israelitas iam dançando e cantando com todo o vigor diante de Deus, ao som de harpas, liras, tamborins, címbalos e cornetas.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 9, 'Quando chegaram à eira de Quidom, Uzá esticou o braço e segurou a arca, porque os bois haviam tropeçado.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 10, 'A ira do Senhor acendeu-se contra Uzá, e ele o feriu por ter tocado na arca. Uzá morreu ali mesmo, diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 11, 'Davi ficou contrariado porque o Senhor, em sua ira, havia fulminado Uzá. Até hoje aquele lugar é chamado Perez-Uzá.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 12, 'Naquele dia, Davi teve medo de Deus e se perguntou: "Como vou conseguir levar a arca de Deus? "', 3, CURRENT_TIMESTAMP, false),
(13, 13, 13, 'Por isso desistiu de levar a arca para a cidade de Davi. Em vez disso, levou-a para a casa de Obede-Edom, de Gate.', 3, CURRENT_TIMESTAMP, false),
(13, 13, 14, 'A arca de Deus ficou na casa dele por três meses, e o Senhor abençoou sua família e tudo o que possuía.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 1, 'Hirão, rei de Tiro, enviou a Davi uma delegação, que lhe trouxe toras de cedro, e também pedreiros e carpinteiros, para lhe construírem um palácio.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 2, 'Então Davi teve certeza de que o Senhor o confirmara como rei de Israel e que seu reino estava prosperando por amor de seu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 3, 'Em Jerusalém Davi tomou para si mais mulheres e gerou mais filhos e filhas.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 4, 'Estes são os nomes dos que lhe nasceram ali: Samua, Sobabe, Natã, Salomão,', 3, CURRENT_TIMESTAMP, false),
(13, 14, 5, 'Ibar, Elisua, Elpelete,', 3, CURRENT_TIMESTAMP, false),
(13, 14, 6, 'Nogá, Nefegue, Jafia,', 3, CURRENT_TIMESTAMP, false),
(13, 14, 7, 'Elisama, Beeliada e Elifelete.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 8, 'Quando os filisteus ficaram sabendo que Davi tinha sido ungido rei de todo o Israel, foram com todo o exército prendê-lo, mas Davi soube disso e saiu para enfrentá-los.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 9, 'Tendo os filisteus invadido o vale de Refaim,', 3, CURRENT_TIMESTAMP, false),
(13, 14, 10, 'Davi perguntou a Deus: "Devo atacar os filisteus? Tu os entregarás nas minhas mãos? " O Senhor lhe respondeu: "Vá, eu os entregarei nas suas mãos".', 3, CURRENT_TIMESTAMP, false),
(13, 14, 11, 'Então Davi e seus soldados foram a Baal-Perazim, e Davi os derrotou e disse: "Assim como as águas de uma enchente causam destruição, pelas minhas mãos Deus destruiu os meus inimigos". Então, aquele lugar passou a ser chamado Baal-Perazim.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 12, 'Como os filisteus haviam abandonado os seus ídolos ali, Davi ordenou que fossem queimados.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 13, 'Os filisteus voltaram a atacar o vale;', 3, CURRENT_TIMESTAMP, false),
(13, 14, 14, 'então Davi consultou Deus de novo, que lhe respondeu: "Não ataque pela frente, mas dê a volta por trás deles e ataque-os em frente das amoreiras.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 15, 'Assim que você ouvir um som de passos por cima das amoreiras, saia para o combate, pois este é o sinal de que Deus saiu à sua frente para ferir o exército filisteu".', 3, CURRENT_TIMESTAMP, false),
(13, 14, 16, 'E Davi fez como Deus lhe tinha ordenado, e eles derrotaram o exército filisteu, por todo o caminho, desde Gibeom até Gezer.', 3, CURRENT_TIMESTAMP, false),
(13, 14, 17, 'Assim, a fama de Davi espalhou-se por todas as terras, e o Senhor fez com que todas as nações o temessem.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 1, 'Depois de Davi ter construído casas para si na cidade de Davi, ele preparou um lugar para a arca de Deus e armou uma tenda para ela.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 2, 'Então Davi disse: "Somente os levitas poderão carregar a arca de Deus, pois o Senhor os escolheu para transportarem a arca do Senhor e para ficarem sempre ao seu serviço".', 3, CURRENT_TIMESTAMP, false),
(13, 15, 3, 'Davi reuniu todo o Israel em Jerusalém para levar a arca do Senhor para o lugar que ele lhe havia preparado.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 4, 'Reuniu também os descendentes de Arão e os levitas:', 3, CURRENT_TIMESTAMP, false),
(13, 15, 5, 'Dos descendentes de Coate, Uriel, liderando outros 120;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 6, 'dos descendentes de Merari, Asaías, liderando outros 220;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 7, 'dos descendentes de Gérson, Joel, liderando outros 130;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 8, 'dos descendentes de Elisafã, Semaías, liderando outros 200;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 9, 'dos descendentes de Hebrom, Eliel, liderando outros 80;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 10, 'dos descendentes de Uziel, Aminadabe, liderando outros 112.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 11, 'Então Davi convocou os sacerdotes Zadoque e Abiatar, e os levitas Uriel, Asaías, Joel, Semaías, Eliel e Aminadabe, e', 3, CURRENT_TIMESTAMP, false),
(13, 15, 12, 'lhes disse: "Vocês são os chefes das famílias levitas; vocês e seus companheiros levitas deverão consagrar-se e levar a arca do Senhor, o Deus de Israel, para o local que preparei para ela.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 13, 'Pelo fato de vocês não terem carregado a arca na primeira vez, a ira do Senhor nosso Deus causou destruição entre nós. Nós não o tínhamos consultado sobre como proceder".', 3, CURRENT_TIMESTAMP, false),
(13, 15, 14, 'Então os sacerdotes e os levitas se consagraram para transportar a arca do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 15, 'E os levitas carregaram a arca de Deus apoiando as varas da arca sobre os ombros, conforme Moisés tinha ordenado, de acordo com a palavra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 16, 'Davi também ordenou aos líderes dos levitas que encarregassem os músicos que havia entre eles de cantar músicas alegres, acompanhados por instrumentos musicais: liras, harpas e címbalos sonoros.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 17, 'Assim, os levitas escolheram Hemã, filho de Joel, e Asafe, um parente dele; e dentre os meraritas, seus parentes, escolheram Etã, filho de Cuxaías;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 18, 'e com eles seus parentes que estavam no segundo escalão: Zacarias, Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaia, Maaséias, Matitias, Elifeleu, Micnéias, Obede-Edom e Jeiel, os porteiros.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 19, 'Os músicos Hemã, Asafe e Etã deviam tocar os címbalos de bronze;', 3, CURRENT_TIMESTAMP, false),
(13, 15, 20, 'Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaséias e Benaia deviam tocar as liras, acompanhando o soprano,', 3, CURRENT_TIMESTAMP, false),
(13, 15, 21, 'e Matitias, Elifeleu, Micnéias, Obede-Edom, Jeiel e Azazias deviam tocar as harpas em oitava, marcando o ritmo.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 22, 'Quenanias, o chefe dos levitas, ficou encarregado dos cânticos; essa era sua responsabilidade, pois ele era capaz nisso.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 23, 'Berequias e Elcana seriam porteiros. Eles deveriam proteger a arca.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 24, 'Os sacerdotes Sebanias, Josafá, Natanael, Amasai, Zacarias, Benaia e Eliézer deviam tocar as cornetas diante da arca de Deus. Obede-Edom e Jeías também deviam ser porteiros, para vigiar a arca.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 25, 'Assim, com grande festa, foram Davi, as autoridades de Israel e os líderes de batalhões de mil buscar a arca da aliança do Senhor na casa de Obede-Edom.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 26, 'Como Deus havia poupado os levitas que carregavam a arca da aliança do Senhor, sete novilhos e sete carneiros foram sacrificados.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 27, 'E Davi vestia um manto de linho fino, assim como também todos os levitas que carregavam a arca, os músicos e Quenanias, chefe dos músicos. E Davi vestia também o colete sacerdotal de linho.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 28, 'E todo Israel acompanhou a arca da aliança do Senhor alegremente, ao som de trombetas, cornetas e címbalos, ao toque de liras e de harpas.', 3, CURRENT_TIMESTAMP, false),
(13, 15, 29, 'Aconteceu que, entrando a arca da aliança do Senhor na cidade de Davi, Mical, filha de Saul, observava de uma janela. E, ao ver o rei Davi dançando e comemorando, ela o desprezou em seu coração.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 1, 'Eles trouxeram a arca de Deus e a colocaram na tenda que Davi lhe havia preparado, e ofereceram holocaustos e sacrifícios de comunhão diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 2, 'Após oferecer os holocaustos e os sacrifícios de comunhão, Davi abençoou o povo em nome do Senhor,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 3, 'e deu um pão, um bolo de tâmaras e um bolo de uvas passas a cada homem e a cada mulher israelita.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 4, 'Davi nomeou alguns dos levitas para ministrarem diante da arca do Senhor, fazendo petições, dando graças, e louvando o Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 5, 'Desses, Asafe era o chefe, Zacarias vinha em seguida, e depois Jeiel, Semiramote, Jeiel, Matitias, Eliabe, Benaia, Obede-Edom e Jeiel. Eles deviam tocar lira e harpa, enquanto Asafe tocava os címbalos.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 6, 'Os sacerdotes Benaia e Jaaziel deviam tocar diariamente as trombetas diante da arca da aliança de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 7, 'Foi naquele dia que pela primeira vez Davi encarregou a Asafe e seus parentes de louvar ao Senhor com salmos de gratidão:', 3, CURRENT_TIMESTAMP, false),
(13, 16, 8, 'Dêem graças ao Senhor, clamem pelo seu nome, divulguem entre as nações o que ele tem feito.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 9, 'Cantem para ele, louvem-no; contem todos os seus atos maravilhosos.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 10, 'Gloriem-se no seu santo nome; alegrem-se os corações dos que buscam o Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 11, 'Olhem para o Senhor e para a sua força; busquem sempre a sua face.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 12, 'Lembrem-se das maravilhas que ele fez, dos seus prodígios e das ordenanças que pronunciou,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 13, 'ó descendentes de Israel, seu servo, ó filhos de Jacó, seus escolhidos.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 14, 'Ele é o Senhor, o nosso Deus; seus domínio alcança toda a terra.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 15, 'Para sempre se lembra da sua aliança, da palavra que ordenou para mil gerações,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 16, 'da aliança que fez com Abraão, do juramento que fez a Isaque,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 17, 'que confirmou para Jacó como um decreto, e para Israel como uma aliança eterna, dizendo:', 3, CURRENT_TIMESTAMP, false),
(13, 16, 18, '"A vocês darei a terra de Canaã, a herança que possuirão".', 3, CURRENT_TIMESTAMP, false),
(13, 16, 19, 'Quando eles ainda eram poucos, muito poucos, e estrangeiros nela,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 20, 'e vagueavam de nação em nação, de um reino a outro,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 21, 'ele não permitiu que ninguém os oprimisse; por causa deles repreendeu reis, ordenando:', 3, CURRENT_TIMESTAMP, false),
(13, 16, 22, '"Não maltratem os meus ungidos; não façam mal aos meus profetas".', 3, CURRENT_TIMESTAMP, false),
(13, 16, 23, 'Cantem ao Senhor, todas as terras! Proclamem a sua salvação dia após dia!', 3, CURRENT_TIMESTAMP, false),
(13, 16, 24, 'Anunciem a sua glória entre as nações, seus feitos maravilhosos entre todos os povos!', 3, CURRENT_TIMESTAMP, false),
(13, 16, 25, 'Pois o Senhor é grande e muitíssimo digno de louvor; ele deve ser mais temido que todos os deuses.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 26, 'Pois todos os deuses das nações não passam de ídolos, mas o Senhor fez os céus.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 27, 'O esplendor e a majestade estão diante dele; força e alegria na sua habitação.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 28, 'Dêem ao Senhor, ó famílias das nações, dêem ao Senhor glória e força.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 29, 'Dêem ao Senhor a glória devida ao seu nome. Tragam ofertas e venham à sua presença. Adorem o Senhor no esplendor da sua santidade,', 3, CURRENT_TIMESTAMP, false),
(13, 16, 30, 'tremam diante dele, todas as nações! Firmou o mundo, que não se abalará!', 3, CURRENT_TIMESTAMP, false),
(13, 16, 31, 'Que os céus se alegrem e a terra exulte, e diga-se entre as nações: "O Senhor reina! "', 3, CURRENT_TIMESTAMP, false),
(13, 16, 32, 'Ressoe o mar, e tudo o que nele existe; exultem os campos, e tudo o que neles há!', 3, CURRENT_TIMESTAMP, false),
(13, 16, 33, 'Então as árvores da floresta cantarão de alegria, cantarão diante do Senhor, pois ele vem julgar a terra.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 34, 'Rendam graças ao Senhor, pois ele é bom; o seu amor dura para sempre.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 35, 'Clamem: "Salva-nos, ó Deus, nosso Salvador! Reúne-nos e livra-nos das nações, para que demos graças ao teu santo nome e façamos do teu louvor a nossa glória".', 3, CURRENT_TIMESTAMP, false),
(13, 16, 36, 'Bendito seja o Senhor, o Deus de Israel, de eternidade a eternidade. Então todo o povo exclamou: "Amém! " e "Louvado seja o Senhor! "', 3, CURRENT_TIMESTAMP, false),
(13, 16, 37, 'Então Davi deixou Asafe e seus parentes diante da arca da aliança do Senhor para ali ministrarem regularmente, de acordo com as prescrições para cada dia.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 38, 'Também deixou Obede-Edom e seus sessenta e oito parentes para ministrarem com eles. Obede-Edom, filho de Jedutum, e também Hosa foram porteiros.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 39, 'Davi deixou o sacerdote Zadoque e seus parentes sacerdotes diante do tabernáculo do Senhor em Gibeom', 3, CURRENT_TIMESTAMP, false),
(13, 16, 40, 'para regularmente, de manhã e à tarde, apresentarem holocaustos no altar de holocaustos, de acordo com tudo o que está escrito na Lei do Senhor, que ele deu a Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 41, 'Com eles estavam Hemã e Jedutum e os outros designados para darem graças ao Senhor, exclamando: "O seu amor dura para sempre".', 3, CURRENT_TIMESTAMP, false),
(13, 16, 42, 'Hemã e Jedutum eram responsáveis pelas trombetas, pelos címbalos e pelos outros instrumentos musicais para o culto. Os filhos de Jedutum foram designados como porteiros.', 3, CURRENT_TIMESTAMP, false),
(13, 16, 43, 'Então todo o povo partiu, cada um para a sua casa, e Davi voltou para casa para abençoar sua família.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 1, 'O rei Davi já morava em seu palácio quando, certo dia disse ao profeta Natã: "Aqui estou eu, morando num palácio de cedro, enquanto a arca da aliança do Senhor permanece numa simples tenda".', 3, CURRENT_TIMESTAMP, false),
(13, 17, 2, 'Natã respondeu a Davi: "Faze o que tiveres em mente, pois Deus está contigo".', 3, CURRENT_TIMESTAMP, false),
(13, 17, 3, 'E naquela mesma noite Deus falou a Natã:', 3, CURRENT_TIMESTAMP, false),
(13, 17, 4, '"Vá dizer ao meu servo Davi que assim diz o Senhor: Não será você quem vai construir uma casa para eu morar.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 5, 'Não tenho morado em nenhuma casa, desde o dia em que tirei Israel do Egito, mas fui de uma tenda para outra, e de um tabernáculo para outro.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 6, 'Por onde tenho acompanhado todo o Israel, alguma vez perguntei a algum líder deles, a quem ordenei que pastoreasse o meu povo: Por que você não me construiu um templo de cedro? "', 3, CURRENT_TIMESTAMP, false),
(13, 17, 7, '"Agora pois, diga ao meu servo Davi: ‘Assim diz o Senhor dos Exércitos: Eu o tirei das pastagens, onde cuidava dos rebanhos, para ser o soberano do meu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 8, 'Sempre estive com você por onde você andou, e eliminei todos os seus inimigos. Agora eu o farei tão famoso quanto os homens mais importantes da terra.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 9, 'E providenciarei um lugar para o meu povo Israel e os plantarei lá, para que tenham o seu próprio lar; e não mais sejam incomodados. Povos ímpios não mais os oprimirão, como fizeram no início', 3, CURRENT_TIMESTAMP, false),
(13, 17, 10, 'e têm feito desde a época em que nomeei juízes sobre meu povo Israel. Também subjugarei todos os seus inimigos. Saiba também que eu, o Senhor, lhe estabelecerei uma dinastia.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 11, 'Quando a sua vida chegar ao fim e você se juntar aos seus antepassados, escolherei um dos seus filhos para sucedê-lo, e eu estabelecerei o reino dele.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 12, 'Será ele quem construirá um templo para mim, e eu firmarei o trono dele para sempre.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 13, 'Eu serei seu pai, e ele será meu filho. Nunca retirarei dele o meu amor, como retirei de Saul.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 14, 'Eu o farei líder do meu povo e do meu reino para sempre; seu reinado será estabelecido para sempre’. "', 3, CURRENT_TIMESTAMP, false),
(13, 17, 15, 'E Natã transmitiu a Davi tudo o que o Senhor lhe tinha falado e revelado.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 16, 'Então o rei Davi entrou no tabernáculo, assentou-se diante do Senhor, e orou: "Quem sou eu, ó Senhor Deus, e o que é a minha família, para que me trouxesses a este ponto?', 3, CURRENT_TIMESTAMP, false),
(13, 17, 17, 'E, como se isso não bastasse para ti, ó Deus, tu falaste sobre o futuro da família deste teu servo. Tens me tratado como um homem de grande importância, ó Senhor Deus".', 3, CURRENT_TIMESTAMP, false),
(13, 17, 18, '"O que mais Davi poderá dizer-te por honrares o teu servo? Tu conheces o teu servo,', 3, CURRENT_TIMESTAMP, false),
(13, 17, 19, 'ó Senhor. Por amor do teu servo e de acordo com tua vontade, realizaste este feito grandioso e tornaste conhecidas todas essas grandes promessas.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 20, '"Não há ninguém como tu, ó Senhor, nem há outro Deus além de ti, conforme tudo o que sabemos.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 21, 'E quem é como o teu povo Israel, a única nação da terra que tu, ó Deus, resgataste para ti mesmo, e assim tornaste o teu nome famoso, realizaste grandes e impressionantes maravilhas ao expulsar nações de diante do povo que libertaste do Egito?', 3, CURRENT_TIMESTAMP, false),
(13, 17, 22, 'Tu fizeste do teu povo Israel o teu povo particular para sempre, e tu, ó Senhor, te tornaste o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 23, '"Agora, Senhor, que a promessa que fizeste a respeito de teu servo e de sua descendência se confirme para sempre. Faze conforme prometeste,', 3, CURRENT_TIMESTAMP, false),
(13, 17, 24, 'para que tudo se confirme, para que o teu nome seja engrandecido para sempre e os homens digam: ‘O Senhor dos Exércitos, o Deus de Israel, é Deus para Israel! ’ E a descendência de teu servo Davi se manterá firme diante de ti.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 25, '"Tu, meu Deus, revelaste a teu servo que formarás uma dinastia para ele. Por isso teu servo achou coragem para orar a ti.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 26, 'Ó Senhor, tu és Deus! Tu fizeste essa boa promessa a teu servo.', 3, CURRENT_TIMESTAMP, false),
(13, 17, 27, 'Agora, por tua bondade, abençoa a família de teu servo, para que ela continue para sempre na tua presença; pois o que tu, Senhor, abençoas, abençoado está para sempre".', 3, CURRENT_TIMESTAMP, false),
(13, 18, 1, 'Depois disso, Davi derrotou os filisteus e os subjugou, e tirou do controle deles a cidade de Gate e seus povoados.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 2, 'Davi derrotou também os moabitas, que ficaram sujeitos a ele, pagando-lhe impostos.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 3, 'Além disso, Davi derrotou Hadadezer, rei de Zobá, nas proximidades de Hamate, quando Hadadezer tentava obter o controle na região do rio Eufrates.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 4, 'Davi se apossou de mil dos seus carros de guerra, sete mil cavaleiros e vinte mil soldados de infantaria. Ainda levou cem cavalos de carros de guerra, e aleijou todos os outros.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 5, 'Quando os arameus de Damasco vieram ajudar Hadadezer, rei de Zobá, Davi matou vinte e dois mil deles.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 6, 'Em seguida estabeleceu guarnições militares no reino dos arameus de Damasco, sujeitando-os a lhe pagarem impostos. E o Senhor dava vitórias a Davi aonde quer que ele fosse.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 7, 'Davi também levou para Jerusalém os escudos de ouro usados pelos oficiais de Hadadezer.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 8, 'De Tebá e Cum, cidades que pertenciam a Hadadezer, o rei Davi levou grande quantidade de bronze, que Salomão utilizou para fazer o tanque de bronze, as colunas e vários utensílios.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 9, 'Quando Toú, rei de Hamate, soube que Davi tinha derrotado todo o exército de Hadadezer, rei de Zobá,', 3, CURRENT_TIMESTAMP, false),
(13, 18, 10, 'enviou seu filho Hadorão ao rei Davi para saudá-lo e parabenizá-lo por sua vitória na batalha contra Hadadezer, que tinha estado em guerra com Toú. E, com Hadorão, mandou todo tipo de utensílios de ouro, de prata e de bronze.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 11, 'O rei Davi consagrou esses utensílios ao Senhor, como fizera com a prata e o ouro tomados de todas estas nações: Edom e Moabe, os amonitas e os filisteus, e Amaleque.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 12, 'Abisai, filho de Zeruia, derrotou dezoito mil edomitas no vale do Sal.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 13, 'Depois colocou guarnições militares em Edom, sujeitando todos os edomitas a Davi. O Senhor dava vitórias a Davi aonde quer que ele fosse.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 14, 'Davi reinou sobre todo o Israel, administrando o direito e a justiça a todo o seu povo.', 3, CURRENT_TIMESTAMP, false),
(13, 18, 15, 'Joabe, filho de Zeruia, era comandante do exército; Josafá, filho de Ailude, era o arquivista real;', 3, CURRENT_TIMESTAMP, false),
(13, 18, 16, 'Zadoque, filho de Aitube, e Aimeleque, filho de Abiatar, eram sacerdotes; Sausa era secretário;', 3, CURRENT_TIMESTAMP, false),
(13, 18, 17, 'Benaia, filho de Joiada, comandava os queretitas e os peletitas; e os filhos do rei Davi eram seus principais oficiais.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 1, 'Algum tempo depois, Naás, rei dos amonitas, morreu, e seu filho foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 2, 'Davi pensou: "Serei bondoso com Hanum, filho de Naás, porque seu pai foi bondoso comigo". Então Davi enviou uma delegação para transmitir a Hanum seu pesar pela morte do pai. Mas, quando os mensageiros de Davi chegaram à terra dos amonitas para expressar condolências a Hanum,', 3, CURRENT_TIMESTAMP, false),
(13, 19, 3, 'os líderes amonitas lhe disseram: "Achas que Davi está honrando teu pai ao enviar mensageiros para expressar condolências? Não é nada disso! Davi os enviou como espiões para examinar o país e destruí-lo".', 3, CURRENT_TIMESTAMP, false),
(13, 19, 4, 'Então Hanum prendeu os mensageiros de Davi, rapou-lhes a barba, cortou metade de suas roupas até as nádegas, e os mandou embora.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 5, 'Quando Davi soube disso, enviou mensageiros ao encontro deles, pois haviam sido profundamente humilhados, e lhes mandou dizer: "Fiquem em Jericó até que a barba cresça, e então voltem para casa".', 3, CURRENT_TIMESTAMP, false),
(13, 19, 6, 'Vendo Hanum e os amonitas que tinham atraído sobre si o ódio de Davi, alugaram da Mesopotâmia, de Arã Maaca e de Zobá, carros de guerra e condutores de carros, por trinta e cinco toneladas de prata.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 7, 'Alugaram trinta e dois mil carros e seus condutores, e contrataram o rei de Maaca com suas tropas, o qual veio e acampou perto de Medeba, e os amonitas foram convocados de suas cidades e partiram para a batalha.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 8, 'Ao saber disso, Davi ordenou a Joabe que marchasse com todo o exército.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 9, 'Os amonitas saíram e se puseram em posição de combate na entrada da cidade, e os reis que tinham vindo posicionaram-se em campo aberto.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 10, 'Vendo Joabe que estava cercado pelas linhas de combate, escolheu alguns dos melhores soldados de Israel e os posicionou contra os arameus.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 11, 'Pôs o restante dos homens sob o comando de seu irmão Abisai e os posicionou contra os amonitas.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 12, 'E Joabe disse a Abisai: "Se os arameus forem fortes demais para mim, venha me ajudar; mas, se os amonitas forem fortes demais para você, eu irei ajudá-lo.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 13, 'Seja forte e lutemos com bravura pelo nosso povo e pelas cidades do nosso Deus. E que o Senhor faça o que for de sua vontade".', 3, CURRENT_TIMESTAMP, false),
(13, 19, 14, 'Então Joabe e seus soldados avançaram contra os arameus, que fugiram dele.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 15, 'Quando os amonitas viram que os arameus estavam fugindo de Joabe, também fugiram de seu irmão Abisai e entraram na cidade. Assim, Joabe voltou para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 16, 'Ao perceberem os arameus que haviam sido derrotados por Israel, enviaram mensageiros para trazer arameus que viviam do outro lado do Eufrates, e Sofaque, o comandante do exército de Hadadezer, veio à frente deles.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 17, 'Informado disso, Davi reuniu todo o Israel e atravessou o Jordão; avançou contra eles e formou linhas de combate defronte deles. Mas, começado o combate,', 3, CURRENT_TIMESTAMP, false),
(13, 19, 18, 'eles fugiram de diante de Israel, e Davi matou sete mil dos seus condutores de carros de guerra e quarenta mil dos seus soldados de infantaria. Também matou Sofaque, o comandante do exército deles.', 3, CURRENT_TIMESTAMP, false),
(13, 19, 19, 'Quando os vassalos de Hadadezer viram que tinham sido derrotados por Israel, fizeram a paz com Davi e se sujeitaram a ele. E os arameus não quiseram mais ajudar os amonitas.', 3, CURRENT_TIMESTAMP, false),
(13, 20, 1, 'Na primavera seguinte, na época em que os reis saem à guerra, Joabe conduziu o seu exército até a terra dos amonitas e a arrasou. Enquanto Davi ainda estava em Jerusalém, Joabe cercou Rabá, a capital, atacou-a e deixou-a em ruínas.', 3, CURRENT_TIMESTAMP, false),
(13, 20, 2, 'Davi tirou a coroa da cabeça de Milcon, uma coroa de ouro de trinta e cinco quilos, ornamentada com pedras preciosas. E ela foi colocada na cabeça de Davi. Ele levou uma grande quantidade de bens da cidade,', 3, CURRENT_TIMESTAMP, false),
(13, 20, 3, 'e levou também os seus habitantes, designando-lhes trabalhos com serras, picaretas de ferro e machados. Davi fez assim com todas as cidades amonitas. Depois voltou com todo seu exército para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 20, 4, 'E houve depois disso uma guerra com os filisteus, em Gezer. Naquela época, Sibecai, de Husate, matou Sipai, um dos descendentes dos refains, e os filisteus foram subjugados.', 3, CURRENT_TIMESTAMP, false),
(13, 20, 5, 'Noutra batalha contra os filisteus, Elanã, filho de Jair, matou Lami, irmão de Golias, de Gate, que possuía uma lança cuja haste parecia uma lançadeira de tecelão.', 3, CURRENT_TIMESTAMP, false),
(13, 20, 6, 'Noutra batalha, em Gate, havia um homem de grande estatura e que tinha seis dedos em cada mão e seis dedos em cada pé; vinte e quatro dedos ao todo. Ele também era descendente de Rafa,', 3, CURRENT_TIMESTAMP, false),
(13, 20, 7, 'e ele desafiou Israel, mas Jônatas, filho de Siméia, irmão de Davi, o matou.', 3, CURRENT_TIMESTAMP, false),
(13, 20, 8, 'Esses eram descendentes de Rafa, em Gate, e foram mortos por Davi e seus soldados.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 1, 'Satanás levantou-se contra Israel e levou Davi a fazer um recenseamento do povo.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 2, 'Davi disse a Joabe e aos outros comandantes do exército: "Vão e contem os israelitas desde Berseba até Dã e tragam-me um relatório para que eu saiba quantos são".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 3, 'Joabe, porém, respondeu: "Que o Senhor multiplique o povo dele por cem. Ó rei, meu senhor, não são, porventura, todos eles súditos do meu senhor? Por que o meu senhor deseja fazer isso? Por que deveria trazer culpa sobre Israel? "', 3, CURRENT_TIMESTAMP, false),
(13, 21, 4, 'Mas a palavra do rei prevaleceu, de modo que Joabe partiu, percorreu todo o Israel e então voltou a Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 5, 'Joabe apresentou a Davi o relatório com o número dos homens de combate: Em todo o Israel havia um milhão e cem mil homens habilitados para o serviço militar, sendo quatrocentos e setenta mil de Judá.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 6, 'Mas Joabe não incluiu as tribos de Levi e de Benjamim na contagem, pois a ordem do rei lhe parecera absurda.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 7, 'Essa ordem foi reprovada por Deus, e por isso ele puniu Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 8, 'Então Davi disse a Deus: "Pequei gravemente com o que fiz. Agora eu te imploro que perdoes o pecado do teu servo, porque cometi uma grande loucura! "', 3, CURRENT_TIMESTAMP, false),
(13, 21, 9, 'O Senhor disse a Gade, o vidente de Davi:', 3, CURRENT_TIMESTAMP, false),
(13, 21, 10, '"Vá dizer a Davi: ‘Assim diz o Senhor: Estou lhe dando três opções. Escolha uma delas, e eu a executarei contra você’ ".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 11, 'Então Gade foi a Davi e lhe disse: "Assim diz o Senhor: ‘Escolha:', 3, CURRENT_TIMESTAMP, false),
(13, 21, 12, 'três anos de fome, três meses fugindo de seus adversários, perseguido pela espada deles, ou três dias da espada do Senhor, isto é, três dias de praga, com o anjo do Senhor assolando todas as regiões de Israel’. Decida agora como devo responder àquele que me enviou".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 13, 'Davi respondeu: "É grande a minha angustia! Prefiro cair nas mãos do Senhor, pois é grande a sua misericórdia, e não nas mãos dos homens".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 14, 'Então o Senhor enviou uma praga sobre Israel, e setenta mil homens de Israel morreram.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 15, 'E Deus enviou um anjo para destruir Jerusalém. Mas, quando o anjo ia fazê-lo, o Senhor olhou e arrependeu-se de trazer a catástrofe, e ele disse ao anjo destruidor: "Pare! Já basta! " Naquele momento o anjo do Senhor estava perto da eira de Araúna, o jebuseu.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 16, 'Davi olhou para cima e viu o anjo do Senhor entre o céu e a terra, com uma espada na mão erguida sobre Jerusalém. Então Davi e as autoridades de Israel, vestidos de luto, prostraram-se, rosto em terra.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 17, 'Davi disse a Deus: "Não fui eu que ordenei contar o povo? Fui eu que pequei e fiz o mal. Estes não passam de ovelhas. O que eles fizeram? Ó Senhor meu Deus, que o teu castigo caia sobre mim e sobre a minha família, mas não sobre o teu povo! "', 3, CURRENT_TIMESTAMP, false),
(13, 21, 18, 'Então o anjo do Senhor mandou Gade dizer a Davi que construísse um altar na eira de Araúna, o jebuseu.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 19, 'Davi foi para lá, em obediência à palavra que Gade havia falado em nome do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 20, 'Araúna estava debulhando o trigo; virando-se, viu o anjo, e ele e seus quatro filhos que estavam com ele se esconderam.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 21, 'Nisso chegou Davi e, quando Araúna o viu, saiu da eira e prostrou-se diante de Davi, rosto em terra.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 22, 'E Davi lhe pediu: "Ceda-me o terreno da sua eira para eu construir um altar em honra do Senhor, para que cesse a praga sobre o povo. Venda-me o terreno pelo preço justo".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 23, 'Mas Araúna disse a Davi: "Considera-o teu! Que o meu rei e senhor faça dele o que desejar. Eu darei os bois para os holocaustos, o debulhador para servir de lenha, e o trigo para a oferta de cereal. Tudo isso eu dou a ti".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 24, 'O rei Davi, porém, respondeu a Araúna: "Não! Faço questão de pagar o preço justo. Não darei ao Senhor aquilo que pertence a você, nem oferecerei um holocausto que não me custe nada".', 3, CURRENT_TIMESTAMP, false),
(13, 21, 25, 'Então Davi pagou a Araúna sete quilos e duzentos gramas de ouro pelo terreno.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 26, 'E Davi edificou ali um altar ao Senhor e ofereceu holocaustos e sacrifícios de comunhão. Davi invocou o Senhor, e o Senhor lhe respondeu com fogo que veio do céu sobre o altar de holocaustos.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 27, 'E o Senhor ordenou ao anjo que pusesse a espada na bainha.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 28, 'Nessa ocasião viu Davi que o Senhor lhe havia respondido na eira de Araúna, o jebuseu, e passou a oferecer sacrifícios ali.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 29, 'Naquela época, o tabernáculo do Senhor que Moisés fizera no deserto, e o altar de holocaustos, estavam em Gibeom.', 3, CURRENT_TIMESTAMP, false),
(13, 21, 30, 'Mas Davi não podia consultar a Deus lá, pois tinha medo da espada do anjo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 1, 'Então disse Davi: "Este é o lugar para o templo de Deus, o Senhor, e do altar de holocaustos para Israel".', 3, CURRENT_TIMESTAMP, false),
(13, 22, 2, 'Então Davi deu ordens para que se reunissem os estrangeiros que viviam em Israel, e dentre eles designou cortadores de pedra para prepararem pedras lavradas para a construção do templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 3, 'Ele providenciou grande quantidade de ferro para a fabricação de pregos e dobradiças para as portas, e mais bronze do que se podia pesar.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 4, 'Também providenciou mais toras de cedro do que se podia contar, pois os sidônios e os tírios haviam trazido muito cedro para Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 5, 'Davi pensava: "Meu filho Salomão é jovem e inexperiente, e o templo que será construído para o Senhor deve ser extraordinariamente magnífico, famoso e cheio de esplendor à vista de todas as nações. Por isso deixarei tudo preparado para a construção". Assim, Davi deixou tudo preparado antes de morrer.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 6, 'Davi mandou chamar seu filho Salomão e ordenou que ele construísse um templo para o Senhor, o Deus de Israel,', 3, CURRENT_TIMESTAMP, false),
(13, 22, 7, 'dizendo: "Meu filho, eu tinha no coração o propósito de construir um templo em honra do nome do Senhor, o meu Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 8, 'Mas veio a mim esta palavra do Senhor: ‘Você matou muita gente e empreendeu muitas guerras. Por isso você não construirá um templo em honra do meu nome, pois derramou muito sangue na terra, diante de mim.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 9, 'Mas você terá um filho que será um homem de paz, e eu farei com que ele tenha paz com todos os inimigos ao redor dele. Seu nome será Salomão, e eu darei paz e tranqüilidade a Israel durante o reinado dele.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 10, 'É ele que vai construir um templo em honra do meu nome. Eu serei seu pai e ele será meu filho. E eu firmarei para sempre o trono do reinado dele sobre Israel’.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 11, '"Agora, meu filho, que o Senhor seja com você, para que você consiga construir o templo do Senhor, o seu Deus, conforme ele disse que você faria.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 12, 'Que o Senhor lhe dê prudência e entendimento para que você obedeça à lei do Senhor, o seu Deus, quando ele o puser como líder de Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 13, 'E você prosperará se for cuidadoso em obedecer aos decretos e às leis que o Senhor deu a Israel por meio de Moisés. Seja forte e corajoso! Não tenha medo nem se desanime!', 3, CURRENT_TIMESTAMP, false),
(13, 22, 14, '"Com muito esforço providenciei para o templo do Senhor três mil e quinhentas toneladas de ouro, trinta e cinco mil toneladas de prata, e tanto bronze e ferro que nem dá para calcular, além de madeira e pedra. E você ainda poderá aumentar a quantidade desse material.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 15, 'Você tem muitos trabalhadores: cortadores de pedras, pedreiros e carpinteiros, bem como especialistas em todo tipo de trabalho', 3, CURRENT_TIMESTAMP, false),
(13, 22, 16, 'em ouro, prata, bronze e ferro. Agora comece o trabalho, e que o Senhor esteja com você".', 3, CURRENT_TIMESTAMP, false),
(13, 22, 17, 'Então Davi ordenou a todos os líderes de Israel que ajudassem seu filho Salomão.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 18, 'Disse ele: "Certamente o Senhor, o seu Deus, está com vocês, e lhes concedeu paz. Pois ele entregou os habitantes dessa terra em minhas mãos, e ela foi submetida ao Senhor e ao seu povo.', 3, CURRENT_TIMESTAMP, false),
(13, 22, 19, 'Agora consagrem o coração e a alma para buscarem o Senhor, o seu Deus. Comecem a construir o santuário de Deus, o Senhor, para que vocês possam trazer a arca da aliança do Senhor e os utensílios sagrados que pertencem a Deus para dentro do templo que será construído em honra do nome do Senhor".', 3, CURRENT_TIMESTAMP, false),
(13, 23, 1, 'Já envelhecido e de idade avançada, Davi fez do seu filho Salomão rei sobre Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 2, 'Ele reuniu todos os líderes de Israel, bem como os sacerdotes e os levitas.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 3, 'Os levitas de trinta anos para cima foram contados, e o número total deles chegou a trinta e oito mil.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 4, 'Davi escolheu vinte e quatro mil desses para supervisionarem o trabalho do templo do Senhor e seis mil para serem oficiais e juízes;', 3, CURRENT_TIMESTAMP, false),
(13, 23, 5, 'quatro mil para serem guardas das portas e quatro mil para louvarem o Senhor com os instrumentos musicais que Davi preparou com esse propósito.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 6, 'Davi repartiu os levitas em grupos que descendiam dos filhos de Levi, Gérson, Coate e Merari.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 7, 'Dos filhos de Gérson: Ladã e Simei.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 8, 'Estes foram os filhos de Ladã: Jeiel, o primeiro, Zetã e Joel, três ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 9, 'Estes foram os filhos de Simei: Selomote, Haziel e Harã, três ao todo. Esses foram os chefes das famílias de Ladã.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 10, 'E os filhos de Simei foram: Jaate, Ziza, Jeús e Berias. Esses foram os filhos de Simei, quatro ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 11, 'Jaate foi o primeiro e Ziza, o segundo, mas Jeús e Berias não tiveram muitos descendentes, por isso foram contados como uma única família.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 12, 'Dos filhos de Coate: Anrão, Isar, Hebrom e Uziel, quatro ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 13, 'Estes foram os filhos de Anrão: Arão e Moisés. Arão foi separado, ele e seus descendentes para sempre, para consagrar as coisas santíssimas, oferecer sacrifícios ao Senhor, ministrar diante dele e pronunciar bênçãos em seu nome, para sempre.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 14, 'Os filhos de Moisés, homem de Deus, foram contados como parte da tribo de Levi.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 15, 'Estes foram os filhos de Moisés: Gérson e Eliézer.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 16, 'Sebuel foi o chefe dos descendentes de Gérson.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 17, 'Reabias foi o chefe dos descendentes de Eliézer. Eliézer não teve nenhum outro filho, mas Reabias teve muitos filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 18, 'Selomite foi o chefe dos filhos de Isar.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 19, 'Estes foram os filhos de Hebrom: Jerias foi o primeiro, Amarias, o segundo, Jaaziel, o terceiro, e Jecameão foi o quarto.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 20, 'Estes foram os filhos de Uziel: Mica, o primeiro, e Issias, o segundo.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 21, 'Dos filhos de Merari: Mali e Musi. Estes foram os filhos de Mali: Eleazar e Quis.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 22, 'Eleazar morreu sem ter filhos, pois teve apenas filhas. Os primos delas, os filhos de Quis, casaram-se com elas.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 23, 'Estes foram os filhos de Musi: Mali, Éder e Jeremote, três ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 24, 'Esses foram os descendentes de Levi pelas suas famílias: os chefes de famílias conforme registrados por seus nomes e contados individualmente, ou seja, os de vinte anos para cima, que serviam no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 25, 'Pois Davi dissera: "Uma vez que o Senhor, o Deus de Israel, concedeu descanso ao seu povo e veio habitar para sempre em Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(13, 23, 26, 'os levitas não mais precisam carregar o tabernáculo nem os utensílios usados em seu serviço".', 3, CURRENT_TIMESTAMP, false),
(13, 23, 27, 'De acordo com as instruções finais de Davi, foram contados os levitas de vinte anos para cima.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 28, 'O dever dos levitas era ajudar os descendentes de Arão no serviço do templo do Senhor. Encarregavam-se dos pátios, das salas laterais, da purificação de todas as coisas sagradas e dos outros deveres na casa de Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 29, 'Estavam encarregados do pão consagrado, da farinha para as ofertas de cereal, dos bolos sem fermento, de assar o pão e misturar a massa, e de todos os pesos e medidas.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 30, 'Além disso, deviam se apresentar todas as manhãs e todas as tardes para agradecer e louvar ao Senhor, e fazer o mesmo', 3, CURRENT_TIMESTAMP, false),
(13, 23, 31, 'sempre que holocaustos fossem apresentados ao Senhor nos sábados, nas festas da lua nova e nas festas fixas. Deviam servir regularmente diante do Senhor, conforme o número prescrito para eles.', 3, CURRENT_TIMESTAMP, false),
(13, 23, 32, 'Dessa maneira os levitas ficaram responsáveis pela Tenda do Encontro, pelo Lugar Santo e, pela assistência aos seus irmãos, os descendentes de Arão, e pelo serviço do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 1, 'Os filhos de Arão foram assim agrupados: Os filhos de Arão foram Nadabe, Abiú, Eleazar e Itamar.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 2, 'Mas Nadabe e Abiú morreram antes de seu pai e não tiveram filhos; apenas Eleazar e Itamar serviram como sacerdotes.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 3, 'Com a ajuda de Zadoque, descendente de Eleazar, e de Aimeleque, descendente de Itamar, Davi os dividiu em grupos para que cumprissem as suas responsabilidades.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 4, 'Havia um número maior de chefes de família entre os descendentes de Eleazar do que entre os de Itamar, e por isso eles foram assim divididos: dezesseis chefes de famílias dentre os descendentes de Eleazar e oito, dentre os descendentes de Itamar.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 5, 'Eles foram divididos de maneira imparcial mediante sorteio, pois havia líderes do santuário e líderes de Deus tanto entre os descendentes de Eleazar como entre os de Itamar.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 6, 'O escriba Semaías, filho do levita Natanael, registrou os nomes deles na presença do rei, dos líderes, dos sacerdotes Zadoque e Aimeleque, filho de Abiatar, e dos chefes de famílias dos sacerdotes e dos levitas; as famílias de Eleazar e de Itamar foram sorteadas alternadamente.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 7, 'A primeira sorte caiu para Jeoiaribe, a segunda para Jedaías,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 8, 'a terceira para Harim, a quarta para Seorim,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 9, 'a quinta para Malquias, a sexta para Miamim,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 10, 'a sétima para Hacoz, a oitava para Abias,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 11, 'a nona para Jesua, a décima para Secanias,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 12, 'a décima primeira para Eliasibe, a décima segunda para Jaquim,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 13, 'a décima terceira para Hupá, a décima quarta para Jesebeabe,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 14, 'a décima quinta para Bilga, a décima sexta para Imer,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 15, 'a décima sétima para Hezir, a décima oitava para Hapises,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 16, 'a décima nona para Petaías, a vigésima para Jeezquel,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 17, 'a vigésima primeira para Jaquim, a vigésima segunda para Gamul,', 3, CURRENT_TIMESTAMP, false),
(13, 24, 18, 'a vigésima terceira para Delaías, e a vigésima quarta para Maazias.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 19, 'Conforme essa ordem eles deveriam ministrar quando entrassem no templo do Senhor, de acordo com as prescrições que Arão, antepassado deles, lhes deixou, conforme o Senhor, o Deus de Israel, havia lhe ordenado.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 20, 'Estes foram os chefes dos outros levitas: dos descendentes de Anrão: Subael; dos descendentes de Subael: Jedias.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 21, 'Quanto a Reabias, Issias foi o chefe dos seus filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 22, 'Dos descendentes de Isar: Selomote; dos filhos de Selomote: Jaate.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 23, 'Dos descendentes de Hebrom: Jerias, o primeiro, Amarias, o segundo, Jaaziel, o terceiro, e Jecameão, o quarto.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 24, 'Dos descendentes de Uziel: Mica; dos filhos de Mica: Samir.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 25, 'Dos descendentes de Issias, irmão de Mica, Zacarias.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 26, 'Dos filhos de Merari: Mali e Musi. Dos filhos de Jaazias: Beno.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 27, 'Os descendentes de Merari por Jaazias: Beno, Soão, Zacur e Ibri.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 28, 'De Mali: Eleazar, que não teve filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 29, 'De Quis: Jerameel.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 30, 'E foram estes os filhos de Musi: Mali, Éder e Jeremote. Esses foram os levitas, de acordo com as suas famílias.', 3, CURRENT_TIMESTAMP, false),
(13, 24, 31, 'Eles também tiraram sortes na presença do rei Davi e de Zadoque, de Aimeleque, e dos chefes de famílias dos sacerdotes e dos levitas, assim como fizeram seus irmãos, os descendentes de Arão. As famílias dos irmãos mais velhos foram tratadas da mesma maneira que as dos mais novos.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 1, 'Davi, junto com os comandantes do exército, separou alguns dos filhos de Asafe, de Hemã e de Jedutum para o ministério de profetizar ao som de harpas, liras e címbalos. Esta é a lista dos escolhidos para essa função:', 3, CURRENT_TIMESTAMP, false),
(13, 25, 2, 'Dos filhos de Asafe: Zacur, José, Netanias e Asarela. Os filhos de Asafe estavam sob a sua supervisão que, por sua vez, profetizava sob a supervisão do rei.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 3, 'Dos filhos de Jedutum: Gedalias, Zeri, Jesaías, Simei, Hasabias e Matitias, seis ao todo, sob a supervisão de seu pai, Jedutum, que profetizava ao som da harpa para agradecer e louvar ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 4, 'Dos filhos de Hemã: Buquias, Matanias, Uziel, Sebuel, Jeremote, Hananias, Hanani, Eliata, Gidalti, Romanti-Ézer, Josbecasa, Maloti, Hotir e Maaziote.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 5, 'Todos esses eram filhos de Hemã, o vidente do rei. Esses lhe nasceram conforme as promessas de que Deus haveria de torná-lo poderoso. E Deus deu a Hemã catorze filhos e três filhas.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 6, 'Todos esses homens estavam sob a supervisão de seus pais quando ministravam a música do templo do Senhor, com címbalos, liras e harpas, na casa de Deus. Asafe, Jedutum e Hemã estavam sob a supervisão do rei.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 7, 'Junto com seus parentes, todos capazes e preparados para o ministério do louvor do Senhor, totalizavam 288.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 8, 'Então tiraram sortes entre jovens e velhos, mestres e discípulos para designar-lhes suas responsabilidades.', 3, CURRENT_TIMESTAMP, false),
(13, 25, 9, 'A primeira sorte, caiu para José, filho de Asafe, com seus filhos e parentes; eram ao todo 12; a segunda, para Gedalias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 10, 'a terceira, para Zacur, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 11, 'a quarta, para Izri, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 12, 'a quinta, para Netanias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 13, 'a sexta, para Buquias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 14, 'a sétima, para Jesarela, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 15, 'a oitava, para Jesaías, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 16, 'a nona, para Matanias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 17, 'a décima, para Simei, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 18, 'a décima primeira, para Azareel, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 19, 'a décima segunda, para Hasabias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 20, 'a décima terceira, para Subael, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 21, 'a décima quarta, para Matitias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 22, 'a décima quinta, para Jeremote, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 23, 'a décima sexta, para Hananias, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 24, 'a décima sétima, para Josbecasa, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 25, 'a décima oitava, para Hanani, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 26, 'a décima nona, para Maloti, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 27, 'a vigésima, para Eliata, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 28, 'a vigésima primeira, para Hotir, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 29, 'a vigésima segunda, para Gidalti, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 30, 'a vigésima terceira, para Maaziote, com seus filhos e parentes, eram ao todo 12;', 3, CURRENT_TIMESTAMP, false),
(13, 25, 31, 'a vigésima quarta, para Romanti-Ézer, com seus filhos e parentes, eram ao todo 12.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 1, 'Esta é a relação dos grupos dos porteiros: Dos coreítas, Meselemias, filho de Coré, da família de Asafe.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 2, 'Foram estes os filhos de Meselemias: Zacarias, o primeiro, Jediael, o segundo, Zebadias, o terceiro, Jatniel, o quarto,', 3, CURRENT_TIMESTAMP, false),
(13, 26, 3, 'Elão, o quinto, Joanã, o sexto, e Elioenai, o sétimo.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 4, 'Foram estes os filhos de Obede-Edom: Semaías, o primeiro, Jeozabade, o segundo, Joá, o terceiro, Sacar, o quarto, Natanael, o quinto,', 3, CURRENT_TIMESTAMP, false),
(13, 26, 5, 'Amiel, o sexto, Issacar, o sétimo, e Peuletai, o oitavo. Pois Deus havia abençoado Obede-Edom.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 6, 'Seu filho Semaías também teve filhos, que foram líderes na família do seu pai, pois eram homens capazes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 7, 'Foram estes os filhos de Semaías: Otni, Rafael, Obede e Elzabade. Os parentes dele, Eliú e Semaquias, também foram homens capazes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 8, 'Todos esses foram descendentes de Obede-Edom; eles e os seus filhos e parentes eram capazes e aptos para a obra. Eram ao todo 62 descendentes de Obede-Edom.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 9, 'Meselemias teve 18 filhos e parentes chegados, todos eles homens capazes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 10, 'Foram estes os filhos de Hosa, o merarita: Sinri, que foi nomeado chefe por seu pai, mesmo não sendo o mais velho,', 3, CURRENT_TIMESTAMP, false),
(13, 26, 11, 'Hilquias, o segundo, Tebalias, o terceiro, e Zacarias, o quarto. Os filhos e parentes de Hosa foram 13 ao todo.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 12, 'Essas divisões dos porteiros, feitas pelos chefes deles; eles cumpriam tarefas no serviço do templo do Senhor, assim como seus parentes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 13, 'Tiraram sortes entre as famílias, incluindo jovens e velhos, para que cuidassem de cada porta.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 14, 'E a porta leste coube a Selemias. Então tiraram sortes para seu filho Zacarias, sábio conselheiro, e a porta norte foi sorteada para ele.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 15, 'A sorte da porta sul saiu para Obede-Edom, e a do depósito, para seus filhos.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 16, 'A sorte da porta oeste e da porta Salequete, na rua de cima, saíram para Supim e Hosa. Os guardas ficavam um ao lado do outro:', 3, CURRENT_TIMESTAMP, false),
(13, 26, 17, 'Havia seis levitas por dia no leste, quatro no norte, quatro no sul e dois de cada vez no depósito.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 18, 'Quanto ao pátio a oeste, havia quatro na rua e dois no próprio pátio.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 19, 'Foram essas as divisões dos porteiros, descendentes de Coré e Merari.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 20, 'Outros dos seus irmãos levitas estavam encarregados dos depósitos dos tesouros do templo de Deus e do depósito das dádivas sagradas.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 21, 'Os gersonitas, descendentes de Ladã, que eram chefes de famílias pertencentes a Ladã, foram Jeieli', 3, CURRENT_TIMESTAMP, false),
(13, 26, 22, 'e seus filhos Zetã e seu irmão Joel. Estavam encarregados da tesouraria do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 23, 'Dos filhos de Anrão, de Isar, de Hebrom e de Uziel:', 3, CURRENT_TIMESTAMP, false),
(13, 26, 24, 'Sebuel, um descendente de Gérson, filho de Moisés, era o oficial encarregado dos depósitos dos tesouros.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 25, 'Seus parentes por parte de Eliézer foram seu filho Reabias, que foi o pai de Jesaías, o avô de Jorão, o bisavô de Zicri, o tataravô de Selomote.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 26, 'Selomote e seus parentes estavam encarregados de todos os tesouros consagrados pelo rei Davi, pelos chefes de famílias que eram os comandantes de mil e de cem, e pelos outros líderes do exército.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 27, 'Eles consagravam parte dos despojos tomados em combate para a manutenção do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 28, 'E todas as dádivas consagradas pelo vidente Samuel e por Saul, filho de Quis, por Abner, filho de Ner, e por Joabe, filho de Zeruia, e todas as demais dádivas sagradas estavam sob os cuidados de Selomote e seus parentes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 29, 'Dos filhos de Isar, Quenanias e seus filhos ficaram responsáveis pelos negócios públicos de Israel, atuando como oficiais e juízes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 30, 'Dos filhos de Hebrom, Hasabias e seus parentes, que ficaram responsáveis em Israel, a oeste do Jordão, por todo o trabalho do Senhor e pelo serviço do rei; ao todo eram mil e setecentos homens capazes.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 31, 'De acordo com os registros genealógicos das famílias hebronitas, Jerias foi o chefe delas. No ano quarenta do reinado de Davi fez-se uma busca nos registros, e entre os descendentes de Hebrom encontraram-se homens capazes, em Jazar de Gileade.', 3, CURRENT_TIMESTAMP, false),
(13, 26, 32, 'Jerias tinha dois mil e setecentos parentes, homens capazes e chefes de famílias, que o rei Davi encarregou de todas as questões pertinentes a Deus e aos negócios do rei nas tribos de Rúben e de Gade, e da metade da tribo de Manassés.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 1, 'Esta é a lista dos israelitas, chefes de famílias, comandantes de mil e comandantes de cem; oficiais que serviam o rei na supervisão das divisões do exército que estavam de serviço mês a mês, durante o ano. Cada divisão era constituída por 24. 000 homens.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 2, 'Encarregado da primeira divisão de 24. 000 homens, para o primeiro mês, estava Jasobeão, filho de Zabdiel.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 3, 'Ele era descendente de Perez e chefe de todos os oficiais do exército para o primeiro mês.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 4, 'Encarregado da divisão para o segundo mês estava Dodai, descendente de Aoí; Miclote era o líder da sua divisão que contava 24. 000 homens.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 5, 'O terceiro comandante do exército, para o terceiro mês, foi Benaia, filho do sacerdote Joiada. Ele era chefe da sua divisão de 24. 000 homens.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 6, 'Esse Benaia foi guerreiro, chefe dos Trinta. Seu filho Amizabade estava encarregado da sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 7, 'O quarto, para o quarto mês, foi Asael, irmão de Joabe; seu filho Zebadias foi seu sucessor. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 8, 'O quinto, para o quinto mês, foi o comandante Samute, o izraíta. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 9, 'O sexto, para o sexto mês, foi Ira, filho de Iques, de Tecoa. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 10, 'O sétimo, para o sétimo mês, foi Helez, de Pelom, descendente de Efraim. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 11, 'O oitavo, para o oitavo mês, foi Sibecai, de Husate, da família de Zerá. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 12, 'O nono, para o nono mês, foi Abiezer, de Anatote, da tribo de Benjamim. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 13, 'O décimo, para o décimo mês, foi Maarai, de Netofate, da família de Zerá. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 14, 'O décimo primeiro, para o décimo primeiro mês, foi Benaia, de Piratom, descendente de Efraim. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 15, 'O décimo segundo, para o décimo segundo mês, foi Heldai, de Netofate, da família de Otoniel. Havia 24. 000 homens em sua divisão.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 16, 'Estes foram os líderes das tribos de Israel: de Rúben: Eliézer, filho de Zicri; de Simeão: Sefatias, filho de Maaca;', 3, CURRENT_TIMESTAMP, false),
(13, 27, 17, 'de Levi: Hasabias, filho de Quemuel; de Arão: Zadoque;', 3, CURRENT_TIMESTAMP, false),
(13, 27, 18, 'de Judá: Eliú, irmão de Davi; de Issacar: Onri, filho de Micael;', 3, CURRENT_TIMESTAMP, false),
(13, 27, 19, 'de Zebulom: Ismaías, filho de Obadias; de Naftali: Jeremote, filho de Azriel;', 3, CURRENT_TIMESTAMP, false),
(13, 27, 20, 'dos descendentes de Efraim: Oséias, filho de Azazias; da metade da tribo de Manassés: Joel, filho de Pedaías;', 3, CURRENT_TIMESTAMP, false),
(13, 27, 21, 'da outra metade da tribo de Manassés, em Gileade: Ido, filho de Zacarias; de Benjamim: Jaasiel, filho de Abner;', 3, CURRENT_TIMESTAMP, false),
(13, 27, 22, 'de Dã: Azareel, filho de Jeroão. Foram esses os líderes das tribos de Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 23, 'Davi não contou os homens com menos de vinte anos, pois o Senhor havia prometido tornar Israel tão numeroso quanto as estrelas do céu.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 24, 'Joabe, filho de Zeruia, começou a contar os homens, mas não pôde terminar. A ira divina caiu sobre Israel por causa desse recenseamento, e o resultado não entrou nos registros históricos do rei Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 25, 'Azmavete, filho de Adiel, estava encarregado dos tesouros do palácio. Jônatas, filho de Uzias, estava encarregado dos depósitos do rei nos distritos distantes, nas cidades, nos povoados e nas torres de sentinela.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 26, 'Ezri, filho de Quelube, estava encarregado dos trabalhadores rurais, que cultivavam a terra.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 27, 'Simei, de Ramá, estava encarregado das vinhas. Zabdi, de Sifá, estava encarregado do vinho que era armazenado em tonéis.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 28, 'Baal-Hanã, de Gederá, estava encarregado das oliveiras e das figueiras bravas, na Sefelá. Joás estava encarregado do fornecimento de azeite.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 29, 'Sitrai, de Sarom, estava encarregado dos rebanhos que pastavam em Sarom. Safate, filho de Adlai, estava encarregado dos rebanhos nos vales.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 30, 'O ismaelita Obil estava encarregado dos camelos. Jedias, de Meronote, estava encarregado dos jumentos.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 31, 'O hagareno Jaziz estava encarregado das ovelhas. Todos esses eram encarregados de cuidar dos bens do rei Davi.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 32, 'Jônatas, tio de Davi, era conselheiro; homem sábio e também escriba. Jeiel, filho de Hacmoni, cuidava dos filhos do rei.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 33, 'Aitofel era conselheiro do rei. Husai, o arquita, era amigo do rei.', 3, CURRENT_TIMESTAMP, false),
(13, 27, 34, 'Aitofel foi sucedido por Joiada, filho de Benaia, e por Abiatar. Joabe era o comandante do exército real.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 1, 'Davi reuniu em Jerusalém todos os líderes de Israel: os líderes das tribos, os líderes das divisões a serviço do rei, os comandantes de mil e de cem, e os líderes encarregados de todos os bens e rebanhos que pertenciam ao rei e a seus filhos, juntamente com os funcionários do palácio, os principais guerreiros e todos os soldados valentes.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 2, 'O rei Davi se pôs de pé e disse: "Escutem-me, meus irmãos e meu povo. Eu tinha no coração o propósito de construir um templo para nele colocar a arca da aliança do Senhor, o estrado dos pés de nosso Deus; fiz planos para construí-lo,', 3, CURRENT_TIMESTAMP, false),
(13, 28, 3, 'mas Deus me disse: ‘Você não construirá um templo em honra do meu nome, pois você é um guerreiro e matou muita gente’.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 4, '"No entanto, o Senhor, o Deus de Israel, escolheu-me dentre toda a minha família para ser rei em Israel, para sempre. Ele escolheu Judá como líder, e da tribo de Judá escolheu minha família, e entre os filhos de meu pai ele quis fazer-me rei de todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 5, 'E, dentre todos os muitos filhos que me deu, ele escolheu Salomão para sentar-se no trono de Israel, o reino do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 6, 'Ele me disse: ‘Seu filho Salomão é quem construirá o meu templo e os meus pátios, pois eu o escolhi para ser meu filho, e eu serei o pai dele.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 7, 'Firmarei para sempre o reino dele, se ele continuar a obedecer os meus mandamentos e as minhas ordenanças, como faz agora’.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 8, '"Por isso agora declaro-lhes perante todo o Israel e a assembléia do Senhor, e diante dos ouvidos de nosso Deus: Tenham o cuidado de obedecer a todos os mandamentos do Senhor, do seu Deus, para que mantenham a posse dessa boa terra e a dêem por herança aos seus descendentes para sempre.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 9, '"E você, meu filho Salomão, reconheça o Deus de seu pai, e sirva-o de todo o coração e espontaneamente, pois o Senhor sonda todos os corações e conhece a motivação dos pensamentos. Se você o buscar, o encontrará, mas, se você o abandonar, ele o rejeitará para sempre.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 10, 'Veja que o Senhor o escolheu para construir um templo que me sirva de santuário. Seja forte e mãos ao trabalho! "', 3, CURRENT_TIMESTAMP, false),
(13, 28, 11, 'Então Davi deu a seu filho Salomão a planta do pórtico do templo, para os seus edifícios, para os seus depósitos, para os andares superiores e suas salas, e para o lugar do propiciatório.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 12, 'Entregou-lhe também as plantas de tudo o que o Espírito havia posto em seu coração acerca dos pátios do templo do Senhor e de todas as salas ao redor, para os depósitos dos tesouros do templo de Deus e para os depósitos das dádivas sagradas.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 13, 'Deu-lhe instruções sobre as divisões dos sacerdotes e dos levitas, e sobre à execução de todas as tarefas no templo do Senhor, e os utensílios que seriam utilizados.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 14, 'Determinou o peso do ouro para todos os utensílios de ouro e o peso da prata para todos os utensílios de prata que seriam utilizados nas diferentes tarefas:', 3, CURRENT_TIMESTAMP, false),
(13, 28, 15, 'o peso de ouro para cada candelabro e suas lâmpadas; e o peso de prata para cada candelabro de prata e suas lâmpadas, de acordo com a finalidade de cada um;', 3, CURRENT_TIMESTAMP, false),
(13, 28, 16, 'o peso de ouro para cada mesa de pães consagrados; o peso de prata para as mesas de prata;', 3, CURRENT_TIMESTAMP, false),
(13, 28, 17, 'o peso de ouro puro para os garfos, para as bacias de aspersão e para os jarros; o peso de ouro para cada tigela de ouro; o peso de prata para cada tigela de prata;', 3, CURRENT_TIMESTAMP, false),
(13, 28, 18, 'e o peso de ouro refinado para o altar de incenso. Também lhe deu o desenho do carro dos querubins de ouro que, com suas asas estendidas, abrigam a arca da aliança do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 19, '"Tudo isso", disse Davi a Salomão, "foi me dado por escrito pela mão do Senhor, e ele me deu entendimento para executar todos esses projetos. "', 3, CURRENT_TIMESTAMP, false),
(13, 28, 20, 'E acrescentou: "Seja forte e corajoso! Mãos ao trabalho! Não tenha medo nem se desanime, pois Deus, o Senhor, o meu Deus, está com você. Ele não o deixará nem o abandonará até que se termine toda a construção do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(13, 28, 21, 'As divisões dos sacerdotes e dos levitas estão definidas para todas as tarefas que se farão no templo de Deus, e você receberá ajuda de homens peritos em todo tipo de serviço. Os líderes e todo o povo obedecerão a todas as suas ordens".', 3, CURRENT_TIMESTAMP, false),
(13, 29, 1, 'Então o rei Davi disse a toda a assembléia: "Meu filho Salomão, e só ele, foi quem Deus escolheu. Mas ele é jovem e inexperiente e a tarefa é grande, pois o palácio não será feito para homens, mas para o Senhor Deus.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 2, 'Forneci grande quantidade de recursos para o trabalho do templo do meu Deus: ouro, prata, bronze, ferro e madeira, bem como ônix para os engastes, e ainda turquesas, pedras de várias cores e todo tipo de pedras preciosas, e mármore.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 3, 'Além disso, pelo meu amor ao templo do meu Deus, agora entrego das minhas próprias riquezas, ouro e prata para o templo do meu Deus, além de tudo o que já tenho dado para este santo templo.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 4, 'Ofereço, pois, cento e cinco toneladas de ouro puro de Ofir e duzentos e quarenta e cinco toneladas de prata refinada, para o revestimento das paredes do templo,', 3, CURRENT_TIMESTAMP, false),
(13, 29, 5, 'para o trabalho em ouro e em prata, e para todo o trabalho dos artesãos. Agora, quem hoje está disposto a ofertar dádivas ao Senhor? "', 3, CURRENT_TIMESTAMP, false),
(13, 29, 6, 'Então os chefes das famílias, os líderes das tribos de Israel, os comandantes de mil e de cem, e os oficiais encarregados do trabalho do rei ofertaram espontaneamente.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 7, 'Para a obra do templo de Deus eles deram cento e setenta e cinco toneladas de ouro e dez mil moedas de ouro, trezentas e cinqüenta toneladas de prata, seiscentas e trinta toneladas de bronze e três mil e quinhentas toneladas de ferro.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 8, 'Quem tinha pedras preciosas deu-as para o depósito dos tesouros do templo do Senhor, cujo responsável era Jeiel, o gersonita.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 9, 'O povo alegrou-se diante da atitude de seus líderes, pois fizeram essas ofertas voluntariamente e de coração íntegro ao Senhor. E o rei Davi também encheu-se de alegria.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 10, 'Davi louvou o Senhor na presença de toda a assembléia, dizendo: "Bendito sejas, ó Senhor, Deus de Israel, nosso pai, de eternidade a eternidade.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 11, 'Teus, ó Senhor, são a grandeza, o poder, a glória, a majestade e o esplendor, pois tudo o que há nos céus e na terra é teu. Teu, ó Senhor, é o reino; tu estás acima de tudo.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 12, 'A riqueza e a honra vêm de ti; tu dominas sobre todas as coisas. Nas tuas mãos estão a força e o poder para exaltar e dar força a todos.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 13, 'Agora, nosso Deus, damos-te graças, e louvamos o teu glorioso nome.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 14, '"Mas quem sou eu, e quem é o meu povo para que pudéssemos contribuir tão generosamente como fizemos? Tudo vem de ti, e nós apenas te demos o que vem das tuas mãos.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 15, 'Diante de ti somos estrangeiros e forasteiros, como os nossos antepassados. Os nossos dias na terra são como uma sombra, sem esperança.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 16, 'Ó Senhor, nosso Deus, toda essa riqueza que ofertamos para construir um templo em honra do teu santo nome vem das tuas mãos, e toda ela pertence a ti.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 17, 'Sei, ó meu Deus, que sondas o coração e que te agradas com a integridade. Tudo o que dei foi espontaneamente e com integridade de coração. E agora vi com alegria com quanta disposição o teu povo, que aqui está, tem contribuído.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 18, 'Ó Senhor, Deus de nossos antepassados Abraão, Isaque e Israel, conserva para sempre este desejo no coração de teu povo, e mantém o coração deles leal a ti.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 19, 'E dá ao meu filho Salomão um coração íntegro para obedecer aos teus mandamentos, aos teus preceitos e aos teus decretos, a fim de construir este templo para o qual fiz os preparativos necessários".', 3, CURRENT_TIMESTAMP, false),
(13, 29, 20, 'Então Davi disse a toda a assembléia: "Louvem o Senhor, o seu Deus". E todos eles louvaram o Senhor, o Deus dos seus antepassados, inclinando-se e prostrando-se diante do Senhor e diante do rei.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 21, 'No dia seguinte fizeram sacrifícios ao Senhor e lhe apresentaram holocaustos: mil novilhos, mil carneiros e mil cordeiros, acompanhados de ofertas derramadas, e muitos outros sacrifícios, em favor de todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 22, 'Naquele dia, comeram e beberam com grande alegria na presença do Senhor. Então pela segunda vez proclamaram Salomão, filho de Davi, como rei, ungindo-o diante do Senhor como soberano, e Zadoque como sacerdote.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 23, 'De maneira que Salomão assentou-se como rei no trono do Senhor, em lugar de Davi, seu pai. Ele prosperou, e todo o Israel lhe obedecia.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 24, 'Todos os líderes e principais guerreiros, bem como todos os filhos do rei Davi prometeram submissão ao rei Salomão.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 25, 'O Senhor exaltou muitíssimo Salomão em todo o Israel e concedeu-lhe tal esplendor em seu reinado como nenhum rei de Israel jamais tivera.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 26, 'Davi, filho de Jessé, reinou sobre todo Israel.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 27, 'Ele reinou quarenta anos em Israel: sete anos em Hebrom e trinta e três em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 28, 'Morreu em boa velhice, tendo desfrutado vida longa, riqueza e honra. Seu filho Salomão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(13, 29, 29, 'Os feitos do rei Davi, desde o início até o fim do seu reinado, estão escritos nos registros do vidente Samuel, do profeta Natã e do vidente Gade,', 3, CURRENT_TIMESTAMP, false),
(13, 29, 30, 'incluindo os detalhes do seu reinado e do seu poder, e os acontecimentos relacionados a ele, com Israel e com os reinos das outras terras.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 1, 'O que era desde o princípio, o que ouvimos, o que vimos com os nossos olhos, o que contemplamos e as nossas mãos apalparam — isto proclamamos a respeito da Palavra da vida.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 2, 'A vida se manifestou; nós a vimos e dela testemunhamos, e proclamamos a vocês a vida eterna, que estava com o Pai e nos foi manifestada.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 3, 'Nós lhes proclamamos o que vimos e ouvimos para que vocês também tenham comunhão conosco. Nossa comunhão é com o Pai e com seu Filho Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 4, 'Escrevemos estas coisas para que a nossa alegria seja completa.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 5, 'Esta é a mensagem que dele ouvimos e transmitimos a vocês: Deus é luz; nele não há treva alguma.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 6, 'Se afirmarmos que temos comunhão com ele, mas andamos nas trevas, mentimos e não praticamos a verdade.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 7, 'Se, porém, andamos na luz, como ele está na luz, temos comunhão uns com os outros, e o sangue de Jesus, seu Filho, nos purifica de todo pecado.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 8, 'Se afirmarmos que estamos sem pecado, enganamo-nos a nós mesmos, e a verdade não está em nós.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 9, 'Se confessarmos os nossos pecados, ele é fiel e justo para perdoar os nossos pecados e nos purificar de toda injustiça.', 3, CURRENT_TIMESTAMP, false),
(62, 1, 10, 'Se afirmarmos que não temos cometido pecado, fazemos de Deus um mentiroso, e a sua palavra não está em nós.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 1, 'Meus filhinhos, escrevo-lhes estas coisas para que vocês não pequem. Se, porém, alguém pecar, temos um intercessor junto ao Pai, Jesus Cristo, o Justo.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 2, 'Ele é a propiciação pelos nossos pecados, e não somente pelos nossos, mas também pelos pecados de todo o mundo.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 3, 'Sabemos que o conhecemos, se obedecemos aos seus mandamentos.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 4, 'Aquele que diz: "Eu o conheço", mas não obedece aos seus mandamentos, é mentiroso, e a verdade não está nele.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 5, 'Mas, se alguém obedece à sua palavra, nele verdadeiramente o amor de Deus está aperfeiçoado. Desta forma sabemos que estamos nele:', 3, CURRENT_TIMESTAMP, false),
(62, 2, 6, 'aquele que afirma que permanece nele, deve andar como ele andou.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 7, 'Amados, não lhes escrevo um mandamento novo, mas um mandamento antigo, que vocês têm desde o princípio: a mensagem que ouviram.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 8, 'No entanto, eu lhes escrevo um mandamento novo, o qual é verdadeiro nele e em vocês, pois as trevas estão se dissipando e já brilha a verdadeira luz.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 9, 'Quem afirma estar na luz mas odeia seu irmão, continua nas trevas.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 10, 'Quem ama seu irmão permanece na luz, e nele não há causa de tropeço.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 11, 'Mas quem odeia seu irmão está nas trevas e anda nas trevas; não sabe para onde vai, porque as trevas o cegaram.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 12, 'Filhinhos, eu lhes escrevo porque os seus pecados foram perdoados, graças ao nome de Jesus.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 13, 'Pais, eu lhes escrevo porque vocês conhecem aquele que é desde o princípio. Jovens, eu lhes escrevo porque venceram o Maligno.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 14, 'Filhinhos, eu lhes escrevi porque vocês conhecem o Pai. Pais, eu lhes escrevi porque vocês conhecem aquele que é desde o princípio. Jovens, eu lhes escrevi, porque vocês são fortes, e em vocês a Palavra de Deus permanece e vocês venceram o Maligno.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 15, 'Não amem o mundo nem o que nele há. Se alguém amar o mundo, o amor do Pai não está nele.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 16, 'Pois tudo o que há no mundo — a cobiça da carne, a cobiça dos olhos e a ostentação dos bens — não provém do Pai, mas do mundo.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 17, 'O mundo e a sua cobiça passam, mas aquele que faz a vontade de Deus permanece para sempre.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 18, 'Filhinhos, esta é a última hora; e, assim como vocês ouviram que o anticristo está vindo, já agora muitos anticristos têm surgido. Por isso sabemos que esta é a última hora.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 19, 'Eles saíram do nosso meio, mas na realidade não eram dos nossos, pois, se fossem dos nossos, teriam permanecido conosco; o fato de terem saído mostra que nenhum deles era dos nossos.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 20, 'Mas vocês têm uma unção que procede do Santo, e todos vocês têm conhecimento.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 21, 'Não lhes escrevo porque não conhecem a verdade, mas porque vocês a conhecem e porque nenhuma mentira procede da verdade.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 22, 'Quem é o mentiroso, senão aquele que nega que Jesus é o Cristo? Este é o anticristo: aquele que nega o Pai e o Filho.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 23, 'Todo o que nega o Filho também não tem o Pai; quem confessa publicamente o Filho tem também o Pai.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 24, 'Quanto a vocês, cuidem para que aquilo que ouviram desde o princípio permaneça em vocês. Se o que ouviram desde o princípio permanecer em vocês, vocês também permanecerão no Filho e no Pai.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 25, 'E esta é a promessa que ele nos fez: a vida eterna.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 26, 'Escrevo-lhes estas coisas a respeito daqueles que os querem enganar.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 27, 'Quanto a vocês, a unção que receberam dele permanece em vocês, e não precisam que alguém os ensine; mas, como a unção dele recebida, que é verdadeira e não falsa, os ensina acerca de todas as coisas, permaneçam nele como ele os ensinou.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 28, 'Filhinhos, agora permaneçam nele para que, quando ele se manifestar, tenhamos confiança e não sejamos envergonhados diante dele na sua vinda.', 3, CURRENT_TIMESTAMP, false),
(62, 2, 29, 'Se vocês sabem que ele é justo, saibam também que todo aquele que pratica a justiça é nascido dele.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 1, 'Vejam como é grande o amor que o Pai nos concedeu: que fôssemos chamados filhos de Deus, o que de fato somos! Por isso o mundo não nos conhece, porque não o conheceu.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 2, 'Amados, agora somos filhos de Deus, e ainda não se manifestou o que havemos de ser, mas sabemos que, quando ele se manifestar, seremos semelhantes a ele, pois o veremos como ele é.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 3, 'Todo aquele que nele tem esta esperança purifica-se a si mesmo, assim como ele é puro.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 4, 'Todo aquele que pratica o pecado transgride a Lei; de fato, o pecado é a transgressão da Lei.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 5, 'Vocês sabem que ele se manifestou para tirar os nossos pecados, e nele não há pecado.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 6, 'Todo aquele que nele permanece não está no pecado. Todo aquele que está no pecado não o viu nem o conheceu.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 7, 'Filhinhos, não deixem que ninguém os engane. Aquele que pratica a justiça é justo, assim como ele é justo.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 8, 'Aquele que pratica o pecado é do diabo, porque o diabo vem pecando desde o princípio. Para isso o Filho de Deus se manifestou: para destruir as obras do diabo.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 9, 'Todo aquele que é nascido de Deus não pratica o pecado, porque a semente de Deus permanece nele; ele não pode estar no pecado, porque é nascido de Deus.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 10, 'Desta forma sabemos quem são os filhos de Deus e quem são os filhos do diabo: quem não pratica a justiça não procede de Deus; e também quem não ama seu irmão.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 11, 'Esta é a mensagem que vocês ouviram desde o princípio: que nos amemos uns aos outros.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 12, 'Não sejamos como Caim, que pertencia ao Maligno e matou seu irmão. E por que o matou? Porque suas obras eram más e as de seu irmão eram justas.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 13, 'Meus irmãos, não se admirem se o mundo os odeia.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 14, 'Sabemos que já passamos da morte para a vida porque amamos nossos irmãos. Quem não ama permanece na morte.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 15, 'Quem odeia seu irmão é assassino, e vocês sabem que nenhum assassino tem vida eterna em si mesmo.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 16, 'Nisto conhecemos o que é o amor: Jesus Cristo deu a sua vida por nós, e devemos dar a nossa vida por nossos irmãos.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 17, 'Se alguém tiver recursos materiais e, vendo seu irmão em necessidade, não se compadecer dele, como pode permanecer nele o amor de Deus?', 3, CURRENT_TIMESTAMP, false),
(62, 3, 18, 'Filhinhos, não amemos de palavra nem de boca, mas em ação e em verdade.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 19, 'Assim saberemos que somos da verdade; e tranqüilizaremos o nosso coração diante dele', 3, CURRENT_TIMESTAMP, false),
(62, 3, 20, 'quando o nosso coração nos condenar. Porque Deus é maior do que o nosso coração e sabe todas as coisas.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 21, 'Amados, se o nosso coração não nos condenar, temos confiança diante de Deus', 3, CURRENT_TIMESTAMP, false),
(62, 3, 22, 'e recebemos dele tudo o que pedimos, porque obedecemos aos seus mandamentos e fazemos o que lhe agrada.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 23, 'E este é o seu mandamento: que creiamos no nome de seu Filho Jesus Cristo e que nos amemos uns aos outros, como ele nos ordenou.', 3, CURRENT_TIMESTAMP, false),
(62, 3, 24, 'Os que obedecem aos seus mandamentos permanecem nele, e ele neles. Deste modo sabemos que ele permanece em nós: pelo Espírito que nos deu.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 1, 'Pedro, apóstolo de Jesus Cristo, aos eleitos de Deus, peregrinos dispersos no Ponto, na Galácia, na Capadócia, na província da Ásia e na Bitínia,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 2, 'escolhidos de acordo com a pré-conhecimento de Deus Pai, pela obra santificadora do Espírito, para a obediência a Jesus Cristo e a aspersão do seu sangue: Graça e paz lhes sejam multiplicadas.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo! Conforme a sua grande misericórdia, ele nos regenerou para uma esperança viva, por meio da ressurreição de Jesus Cristo dentre os mortos,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 4, 'para uma herança que jamais poderá perecer, macular-se ou perder o seu valor. Herança guardada nos céus para vocês', 3, CURRENT_TIMESTAMP, false),
(60, 1, 5, 'que, mediante a fé, são protegidos pelo poder de Deus até chegar a salvação prestes a ser revelada no último tempo.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 6, 'Nisso vocês exultam, ainda que agora, por um pouco de tempo, devam ser entristecidos por todo tipo de provação.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 7, 'Assim acontece para que fique comprovado que a fé que vocês têm, muito mais valiosa do que o ouro que perece, mesmo que refinado pelo fogo, é genuína e resultará em louvor, glória e honra, quando Jesus Cristo for revelado.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 8, 'Mesmo não o tendo visto, vocês o amam; e apesar de não o verem agora, crêem nele e exultam com alegria indizível e gloriosa,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 9, 'pois vocês estão alcançando o alvo da sua fé, a salvação das suas almas.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 10, 'Foi a respeito dessa salvação que os profetas que falaram da graça destinada a vocês investigaram e examinaram,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 11, 'procurando saber o tempo e as circunstâncias para os quais apontava o Espírito de Cristo que neles estava, quando lhes predisse os sofrimentos de Cristo e as glórias que se seguiriam àqueles sofrimentos.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 12, 'A eles foi revelado que estavam ministrando, não para si próprios, mas para vocês, quando falaram das coisas que agora lhes foram anunciadas por meio daqueles que lhes pregaram o evangelho pelo Espírito Santo enviado do céu; coisas que até os anjos anseiam observar.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 13, 'Portanto, estejam com a mente preparada, prontos para a ação; sejam sóbrios e coloquem toda a esperança na graça que lhes será dada quando Jesus Cristo for revelado.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 14, 'Como filhos obedientes, não se deixem amoldar pelos maus desejos de outrora, quando viviam na ignorância.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 15, 'Mas, assim como é santo aquele que os chamou, sejam santos vocês também em tudo o que fizerem,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 16, 'pois está escrito: "Sejam santos, porque eu sou santo".', 3, CURRENT_TIMESTAMP, false),
(60, 1, 17, 'Uma vez que vocês chamam Pai aquele que julga imparcialmente as obras de cada um, portem-se com temor durante a jornada terrena de vocês.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 18, 'Pois vocês sabem que não foi por meio de coisas perecíveis como prata ou ouro que vocês foram redimidos da sua maneira vazia de viver que lhes foi transmitida por seus antepassados,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 19, 'mas pelo precioso sangue de Cristo, como de um cordeiro sem mancha e sem defeito,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 20, 'conhecido antes da criação do mundo, revelado nestes últimos tempos em favor de vocês.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 21, 'Por meio dele vocês crêem em Deus, que o ressuscitou dentre os mortos e o glorificou, de modo que a fé e a esperança de vocês estão em Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 22, 'Agora que vocês purificaram as suas vidas pela obediência à verdade, visando ao amor fraternal e sincero, amem sinceramente uns aos outros e de todo o coração.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 23, 'Pois vocês foram regenerados, não de uma semente perecível, mas imperecível, por meio da palavra de Deus, viva e permanente.', 3, CURRENT_TIMESTAMP, false),
(60, 1, 24, 'Pois, "toda a humanidade é como a relva, e toda a sua glória, como a flor da relva; a relva murcha e cai a sua flor,', 3, CURRENT_TIMESTAMP, false),
(60, 1, 25, 'mas a palavra do Senhor permanece para sempre". Essa é a palavra que lhes foi anunciada.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 1, 'Livrem-se, pois, de toda maldade e de todo engano, hipocrisia, inveja e toda espécie de maledicência.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 2, 'Como crianças recém-nascidas, desejem de coração o leite espiritual puro, para que por meio dele cresçam para a salvação,', 3, CURRENT_TIMESTAMP, false),
(60, 2, 3, 'agora que provaram que o Senhor é bom.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 4, 'À medida que se aproximam dele, a pedra viva — rejeitada pelos homens, mas escolhida por Deus e preciosa para ele —', 3, CURRENT_TIMESTAMP, false),
(60, 2, 5, 'vocês também estão sendo utilizados como pedras vivas na edificação de uma casa espiritual para serem sacerdócio santo, oferecendo sacrifícios espirituais aceitáveis a Deus, por meio de Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 6, 'Pois assim é dito na Escritura: "Eis que ponho em Sião uma pedra angular, escolhida e preciosa, e aquele que nela confia jamais será envergonhado".', 3, CURRENT_TIMESTAMP, false),
(60, 2, 7, 'Portanto, para vocês, os que crêem, esta pedra é preciosa; mas para os que não crêem, "a pedra que os construtores rejeitaram tornou-se a pedra angular",', 3, CURRENT_TIMESTAMP, false),
(60, 2, 8, 'e, "pedra de tropeço e rocha que faz cair". Os que não crêem tropeçam, porque desobedecem à mensagem; para o que também foram destinados.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 9, 'Vocês, porém, são geração eleita, sacerdócio real, nação santa, povo exclusivo de Deus, para anunciar as grandezas daquele que os chamou das trevas para a sua maravilhosa luz.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 10, 'Antes vocês nem sequer eram povo, mas agora são povo de Deus; não haviam recebido misericórdia, mas agora a receberam.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 11, 'Amados, insisto em que, como estrangeiros e peregrinos no mundo, vocês se abstenham dos desejos carnais que guerreiam contra a alma.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 12, 'Vivam entre os pagãos de maneira exemplar para que, naquilo em que eles os acusam de praticarem o mal, observem as boas obras que vocês praticam e glorifiquem a Deus no dia da sua intervenção.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 13, 'Por causa do Senhor, sujeitem-se a toda autoridade constituída entre os homens; seja ao rei, como autoridade suprema,', 3, CURRENT_TIMESTAMP, false),
(60, 2, 14, 'seja aos governantes, como por ele enviados para punir os que praticam o mal e honrar os que praticam o bem.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 15, 'Pois é da vontade de Deus que, praticando o bem, vocês silenciem a ignorância dos insensatos.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 16, 'Vivam como pessoas livres, mas não usem a liberdade como desculpa para fazer o mal; vivam como servos de Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 17, 'Tratem a todos com o devido respeito: amem os irmãos, temam a Deus e honrem o rei.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 18, 'Escravos, sujeitem-se a seus senhores com todo o respeito, não apenas aos bons e amáveis, mas também aos maus.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 19, 'Porque é louvável que, por motivo de sua consciência para com Deus, alguém suporte aflições sofrendo injustamente.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 20, 'Pois que vantagem há em suportar açoites recebidos por terem cometido o mal? Mas se vocês suportam o sofrimento por terem feito o bem, isso é louvável diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 21, 'Para isso vocês foram chamados, pois também Cristo sofreu no lugar de vocês, deixando-lhes exemplo, para que sigam os seus passos.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 22, '"Ele não cometeu pecado algum, e nenhum engano foi encontrado em sua boca".', 3, CURRENT_TIMESTAMP, false),
(60, 2, 23, 'Quando insultado, não revidava; quando sofria, não fazia ameaças, mas entregava-se àquele que julga com justiça.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 24, 'Ele mesmo levou em seu corpo os nossos pecados sobre o madeiro, a fim de que morrêssemos para os pecados e vivêssemos para a justiça; por suas feridas vocês foram curados.', 3, CURRENT_TIMESTAMP, false),
(60, 2, 25, 'Pois vocês eram como ovelhas desgarradas, mas agora se converteram ao Pastor e Bispo de suas almas.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 1, 'Do mesmo modo, mulheres, sujeitem-se a seus maridos, a fim de que, se alguns deles não obedecem à palavra, sejam ganhos sem palavras, pelo procedimento de sua mulher,', 3, CURRENT_TIMESTAMP, false),
(60, 3, 2, 'observando a conduta honesta e respeitosa de vocês.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 3, 'A beleza de vocês não deve estar nos enfeites exteriores, como cabelos trançados e jóias de ouro ou roupas finas.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 4, 'Pelo contrário, esteja no ser interior, que não perece, beleza demonstrada num espírito dócil e tranqüilo, o que é de grande valor para Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 5, 'Pois era assim que também costumavam adornar-se as santas mulheres do passado, que colocavam a sua esperança em Deus. Elas se sujeitavam a seus maridos,', 3, CURRENT_TIMESTAMP, false),
(60, 3, 6, 'como Sara, que obedecia a Abraão e lhe chamava senhor. Dela vocês serão filhas, se praticarem o bem e não derem lugar ao medo.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 7, 'Do mesmo modo vocês, maridos, sejam sábios no convívio com suas mulheres e tratem-nas com honra, como parte mais frágil e co-herdeiras do dom da graça da vida, de forma que não sejam interrompidas as suas orações.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 8, 'Quanto ao mais, tenham todos o mesmo modo de pensar, sejam compassivos, amem-se fraternalmente, sejam misericordiosos e humildes.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 9, 'Não retribuam mal com mal nem insulto com insulto; pelo contrário, bendigam; pois para isso vocês foram chamados, para receberem bênção por herança.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 10, 'Pois, "quem quiser amar a vida e ver dias felizes, guarde a sua língua do mal e os seus lábios da falsidade.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 11, 'Afaste-se do mal e faça o bem; busque a paz com perseverança.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 12, 'Porque os olhos do Senhor estão sobre os justos e os seus ouvidos estão atentos à sua oração, mas o rosto do Senhor volta-se contra os que praticam o mal".', 3, CURRENT_TIMESTAMP, false),
(60, 3, 13, 'Quem há de maltratá-los, se vocês forem zelosos na prática do bem?', 3, CURRENT_TIMESTAMP, false),
(60, 3, 14, 'Todavia, mesmo que venham a sofrer porque praticam a justiça, vocês serão felizes. "Não temam aquilo que eles temem, não fiquem amedrontados. "', 3, CURRENT_TIMESTAMP, false),
(60, 3, 15, 'Antes, santifiquem Cristo como Senhor no coração. Estejam sempre preparados para responder a qualquer que lhes pedir a razão da esperança que há em vocês.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 16, 'Contudo, façam isso com mansidão e respeito, conservando boa consciência, de forma que os que falam maldosamente contra o bom procedimento de vocês, porque estão em Cristo, fiquem envergonhados de suas calúnias.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 17, 'É melhor sofrer por fazer o bem, se for da vontade de Deus, do que por fazer o mal.', 3, CURRENT_TIMESTAMP, false),
(60, 3, 18, 'Pois também Cristo sofreu pelos pecados uma vez por todas, o justo pelos injustos, para conduzir-nos a Deus. Ele foi morto no corpo, mas vivificado pelo Espírito,', 3, CURRENT_TIMESTAMP, false),
(60, 3, 19, 'no qual também foi e pregou aos espíritos em prisão', 3, CURRENT_TIMESTAMP, false),
(60, 3, 20, 'que há muito tempo desobederam, quando Deus esperava pacientemente nos dias de Noé, enquanto a arca era construída. Nela apenas algumas pessoas, a saber, oito, foram salvas por meio da água,', 3, CURRENT_TIMESTAMP, false),
(60, 3, 21, 'e isso é representado pelo batismo que agora também salva vocês — não a remoção da sujeira do corpo, mas o compromisso de uma boa consciência diante de Deus — por meio da ressurreição de Jesus Cristo,', 3, CURRENT_TIMESTAMP, false),
(60, 3, 22, 'que subiu ao céu e está à direita de Deus; a ele estão sujeitos anjos, autoridades e poderes.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 1, 'Portanto, uma vez que Cristo sofreu corporalmente, armem-se também do mesmo pensamento, pois aquele que sofreu em seu corpo rompeu com o pecado,', 3, CURRENT_TIMESTAMP, false),
(60, 4, 2, 'para que, no tempo que lhe resta, não viva mais para satisfazer os maus desejos humanos, mas sim para fazer a vontade de Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 3, 'No passado vocês já gastaram tempo suficiente fazendo o que agrada aos pagãos. Naquele tempo vocês viviam em libertinagem, na sensualidade, nas bebedeiras, orgias e farras, e na idolatria repugnante.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 4, 'Eles acham estranho que vocês não se lancem com eles na mesma torrente de imoralidade, e por isso os insultam.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 5, 'Contudo, eles terão que prestar contas àquele que está pronto para julgar os vivos e os mortos.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 6, 'Por isso mesmo o evangelho foi pregado também a mortos, para que eles, mesmo julgados no corpo segundo os homens, vivam pelo Espírito segundo Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 7, 'O fim de todas as coisas está próximo. Portanto, sejam criteriosos e sóbrios; dediquem-se à oração.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 8, 'Sobretudo, amem-se sinceramente uns aos outros, porque o amor perdoa muitíssimos pecados.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 9, 'Sejam mutuamente hospitaleiros, sem reclamação.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 10, 'Cada um exerça o dom que recebeu para servir aos outros, administrando fielmente a graça de Deus em suas múltiplas formas.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 11, 'Se alguém fala, faça-o como quem transmite a palavra de Deus. Se alguém serve, faça-o com a força que Deus provê, de forma que em todas as coisas Deus seja glorificado mediante Jesus Cristo, a quem sejam a glória e o poder para todo o sempre. Amém.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 12, 'Amados, não se surpreendam com o fogo que surge entre vocês para os provar, como se algo estranho lhes estivesse acontecendo.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 13, 'Mas alegrem-se à medida que participam dos sofrimentos de Cristo, para que também, quando a sua glória for revelada, vocês exultem com grande alegria.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 14, 'Se vocês são insultados por causa do nome de Cristo, felizes são vocês, pois o Espírito da glória, o Espírito de Deus, repousa sobre vocês.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 15, 'Se algum de vocês sofre, que não seja como assassino, ladrão, criminoso ou como quem se intromete em negócios alheios.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 16, 'Contudo, se sofre como cristão, não se envergonhe, mas glorifique a Deus por meio desse nome.', 3, CURRENT_TIMESTAMP, false),
(60, 4, 17, 'Pois chegou a hora de começar o julgamento pela casa de Deus; e, se começa primeiro conosco, qual será o fim daqueles que não obedecem ao evangelho de Deus?', 3, CURRENT_TIMESTAMP, false),
(60, 4, 18, 'E, "se ao justo é difícil ser salvo, que será do ímpio e pecador? "', 3, CURRENT_TIMESTAMP, false),
(60, 4, 19, 'Por isso mesmo, aqueles que sofrem de acordo com a vontade de Deus devem confiar suas vidas ao seu fiel Criador e praticar o bem.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 1, 'Portanto, apelo para os presbíteros que há entre vocês, e o faço na qualidade de presbítero como eles e testemunha dos sofrimentos de Cristo, como alguém que participará da glória a ser revelada:', 3, CURRENT_TIMESTAMP, false),
(60, 5, 2, 'Pastoreiem o rebanho de Deus que está aos seus cuidados. Olhem por ele, não por obrigação, mas de livre vontade, como Deus quer. Não façam isso por ganância, mas com o desejo de servir.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 3, 'Não ajam como dominadores dos que lhes foram confiados, mas como exemplos para o rebanho.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 4, 'Quando se manifestar o Supremo Pastor, vocês receberão a imperecível coroa da glória.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 5, 'Da mesma forma jovens, sujeitem-se aos mais velhos. Sejam todos humildes uns para com os outros, porque "Deus se opõe aos orgulhosos, mas concede graça aos humildes".', 3, CURRENT_TIMESTAMP, false),
(60, 5, 6, 'Portanto, humilhem-se debaixo da poderosa mão de Deus, para que ele os exalte no tempo devido.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 7, 'Lancem sobre ele toda a sua ansiedade, porque ele tem cuidado de vocês.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 8, 'Sejam sóbrios e vigiem. O diabo, o inimigo de vocês, anda ao redor como leão, rugindo e procurando a quem possa devorar.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 9, 'Resistam-lhe, permanecendo firmes na fé, sabendo que os irmãos que vocês têm em todo o mundo estão passando pelos mesmos sofrimentos.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 10, 'O Deus de toda a graça, que os chamou para a sua glória eterna em Cristo Jesus, depois de terem sofrido durante pouco de tempo, os restaurará, os confirmará, lhes dará forças e os porá sobre firmes alicerces.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 11, 'A ele seja o poder para todo o sempre. Amém.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 12, 'Com a ajuda de Silvano, a quem considero irmão fiel, eu lhes escrevi resumidamente, encorajando-os e testemunhando que esta é a verdadeira graça de Deus. Mantenham-se firmes na graça de Deus.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 13, 'Aquela que está em Babilônia, também eleita, envia-lhes saudações, e também Marcos, meu filho.', 3, CURRENT_TIMESTAMP, false),
(60, 5, 14, 'Saúdem uns aos outros com beijo de santo amor. Paz a todos vocês que estão em Cristo.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 1, 'Quando o rei Davi envelheceu, já de idade bem avançada, cobriam-no de cobertores, mas ele não se aquecia.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 2, 'Por isso os seus servos lhe propuseram: "Nós vamos procurar uma jovem virgem para servir e cuidar do rei. Ela se deitará ao seu lado, afim de aquecer o rei".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 3, 'Então procuraram em todo o território de Israel uma jovem que fosse bonita e encontraram Abisague, uma sunamita, e a levaram ao rei.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 4, 'A jovem, muito bonita, cuidava do rei e o servia, mas o rei não teve relações com ela.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 5, 'Ora, Adonias, cuja mãe se chamava Hagite, tomou a dianteira e disse: "Eu serei o rei". Providenciou uma carruagem e cavalos, além de cinqüenta homens para correrem à sua frente.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 6, 'Seu pai nunca o havia contrariado; nunca lhe perguntava: "Por que você age assim? " Adonias também tinha boa aparência e havia nascido depois de Absalão.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 7, 'Adonias fez acordo com Joabe, filho de Zeruia, e com o sacerdote Abiatar, e eles, o seguiram e o apoiaram.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 8, 'Mas o sacerdote Zadoque, Benaia, filho de Joiada, o profeta Natã, Simei, Reí e a guarda especial de Davi não deram apoio a Adonias.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 9, 'Então Adonias sacrificou ovelhas, bois e novilhos gordos junto à pedra de Zoelete, próximo a En-Rogel. Convidou todos os seus irmãos, filhos do rei, e todos os homens de Judá que eram conselheiros do rei,', 3, CURRENT_TIMESTAMP, false),
(11, 1, 10, 'mas não convidou o profeta Natã nem Benaia nem a guarda especial nem o seu irmão Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 11, 'Natã perguntou então a Bate-Seba, mãe de Salomão: "Você ainda não sabe que Adonias, o filho de Hagite, tornou-se rei, sem que o nosso senhor Davi ficasse sabendo?', 3, CURRENT_TIMESTAMP, false),
(11, 1, 12, 'Agora, vou dar-lhe um conselho para salvar a sua vida e também a vida do seu filho Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 13, 'Vá perguntar ao rei Davi: Ó rei, meu senhor, não juraste a esta tua serva, prometendo: ‘Tenha certeza que o seu filho Salomão me sucederá como rei, e se assentará no meu trono? ’ Por que foi então, que Adonias se tornou rei?', 3, CURRENT_TIMESTAMP, false),
(11, 1, 14, 'Enquanto você ainda estiver conversando com o rei, eu entrarei e confirmarei as suas palavras".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 15, 'Então Bate-Seba foi até o quarto do rei, já idoso, onde a sunamita Abisague cuidava dele.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 16, 'Bate-Seba ajoelhou-se e prostrou-se diante do rei. "O que você quer? ", o rei perguntou.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 17, 'Ela respondeu: "Meu senhor, tu mesmo juraste a esta tua serva, pelo Senhor o teu Deus: ‘Seu filho Salomão o sucederá como rei e se assentará no meu trono’.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 18, 'Mas agora Adonias se tornou rei, sem que o rei meu senhor o soubesse.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 19, 'Ele sacrificou muitos bois, novilhos gordos e ovelhas, e convidou todos os filhos do rei, o sacerdote Abiatar, e Joabe, o comandante do exército, mas não convidou o teu servo Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 20, 'Agora, ó rei, meu senhor, os olhos de todo o Israel estão sobre ti para saber de tua parte, quem sucederá ao rei, meu senhor, no trono.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 21, 'De outro modo, tão logo o rei, meu senhor descanse com os seus antepassados, eu e o meu filho Salomão seremos tratados como traidores".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 22, 'Ela ainda conversava com o rei, quando o profeta Natã chegou.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 23, 'Assim que informaram o rei que o profeta Natã havia chegado, ele entrou e prostrou-se, rosto em terra, diante do rei.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 24, 'E Natã lhe perguntou: "Ó rei, meu senhor, por acaso declaraste que Adonias te sucederia como rei e que ele se assentaria no teu trono?', 3, CURRENT_TIMESTAMP, false),
(11, 1, 25, 'Hoje ele foi matar muitos bois, novilhos gordos e ovelhas. Convidou todos os filhos do rei, os comandantes do exército e o sacerdote Abiatar. Agora eles estão comendo e bebendo com ele e comemorando: ‘Viva o rei Adonias! ’', 3, CURRENT_TIMESTAMP, false),
(11, 1, 26, 'Mas ele não convidou a mim, que sou teu servo, nem ao sacerdote Zadoque nem a Benaia, filho de Joiada, nem a teu servo Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 27, 'Seria isto algo que o rei, meu senhor, fez sem deixar que os seus conselheiros soubessem quem sucederia ao rei, meu senhor, no trono? "', 3, CURRENT_TIMESTAMP, false),
(11, 1, 28, 'Então o rei Davi ordenou: "Chamem Bate-Seba". Ela entrou e ficou de pé diante dele.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 29, 'O rei fez então um juramento: "Juro pelo nome do Senhor, o qual me livrou de todas as adversidades,', 3, CURRENT_TIMESTAMP, false),
(11, 1, 30, 'que sem dúvida hoje mesmo vou executar o que jurei pelo Senhor, o Deus de Israel. O seu filho Salomão me sucederá como rei e se assentará no meu trono em meu lugar".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 31, 'Então Bate-Seba prostrou-se, rosto em terra, e, ajoelhando-se diante do rei, disse: "Que o rei Davi, meu senhor, viva para sempre! "', 3, CURRENT_TIMESTAMP, false),
(11, 1, 32, 'O rei Davi ordenou: "Chamem o sacerdote Zadoque, o profeta Natã e Benaia, filho de Joiada". Quando chegaram à presença do rei,', 3, CURRENT_TIMESTAMP, false),
(11, 1, 33, 'ele os instruiu: "Levem os conselheiros do seu senhor com vocês e ponham o meu filho Salomão sobre a minha mula e levem-no a Giom.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 34, 'Ali o sacerdote Zadoque e o profeta Natã o ungirão rei sobre Israel. Então toquem a trombeta e gritem: Viva o rei Salomão!', 3, CURRENT_TIMESTAMP, false),
(11, 1, 35, 'Depois acompanhem-no, e ele virá assentar-se no meu trono e reinará em meu lugar. Eu o designei para governar Israel e Judá".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 36, 'Benaia, filho de Joiada, respondeu ao rei: "Assim se fará! Que o Senhor, o Deus do rei, meu senhor, o confirme.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 37, 'Assim como o Senhor esteve com o rei, meu senhor, também esteja ele com Salomão para que ele tenha um reinado ainda mais glorioso do que o meu senhor, o rei Davi! "', 3, CURRENT_TIMESTAMP, false),
(11, 1, 38, 'Então o sacerdote Zadoque, o profeta Natã, Benaia, filho de Joiada, os queretitas e os peletitas fizeram Salomão montar a mula do rei Davi e o escoltaram até Giom.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 39, 'O sacerdote Zadoque pegou na Tenda o chifre com óleo e ungiu Salomão. Então tocaram a trombeta e todo o povo gritou: "Viva o rei Salomão! "', 3, CURRENT_TIMESTAMP, false),
(11, 1, 40, 'E todo o povo o acompanhou, tocando flautas e comemorando, de tal forma que o chão tremia com o barulho.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 41, 'Adonias e todos os seus convidados souberam disso quando estavam terminando o banquete. Ao ouvir o toque da trombeta, Joabe perguntou: "O que significa esta gritaria, esse alvoroço na cidade? "', 3, CURRENT_TIMESTAMP, false),
(11, 1, 42, 'Falava ele ainda, quando chegou Jônatas, filho do sacerdote Abiatar. E Adonias lhe disse: "Entre, pois um homem digno como você deve estar trazendo boas notícias! "', 3, CURRENT_TIMESTAMP, false),
(11, 1, 43, '"De modo algum", respondeu Jônatas a Adonias. "Davi, o nosso rei e senhor, constituiu rei a Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 44, 'O rei enviou com ele o sacerdote Zadoque, o profeta Natã, Benaia, filho de Joiada, os queretitas e os peletitas, e eles o fizeram montar a mula do rei.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 45, 'Depois o sacerdote Zadoque e o profeta Natã o ungiram rei em Giom. De lá eles saíram comemorando, e a cidade está alvoroçada. É esse o barulho que vocês ouvem.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 46, 'Além disso, Salomão já se assentou no trono real.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 47, 'Até mesmo os oficiais do rei foram cumprimentar Davi, o nosso rei e senhor, dizendo: ‘Que o teu Deus torne o nome de Salomão mais famoso que o teu, e o seu reinado mais glorioso do que o teu! ’ E o rei curvou-se reverentemente em sua cama,', 3, CURRENT_TIMESTAMP, false),
(11, 1, 48, 'e disse: ‘Bendito seja o Senhor, o Deus de Israel, que permitiu que os meus olhos vissem hoje um sucessor em meu trono’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 49, 'Diante disso, todos os convidados de Adonias entraram em pânico e se dispersaram.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 50, 'Mas Adonias, com medo de Salomão, foi agarrar-se às pontas do altar.', 3, CURRENT_TIMESTAMP, false),
(11, 1, 51, 'Então informaram a Salomão: "Adonias está com medo do rei Salomão e está agarrado às pontas do altar. Ele diz: ‘Que o rei Salomão me jure que não matará o seu servo pela espada’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 52, 'Salomão respondeu: "Se ele se mostrar confiável, não cairá nem um só fio de cabelo da sua cabeça; mas se nele se descobrir alguma maldade, ele morrerá".', 3, CURRENT_TIMESTAMP, false),
(11, 1, 53, 'Então o rei enviou alguns soldados, e eles o fizeram descer do altar. E Adonias veio e se curvou solenemente perante o rei Salomão, que lhe disse: "Vá para casa".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 1, 'Quando se aproximava o dia de sua morte, Davi deu instruções ao seu filho Salomão:', 3, CURRENT_TIMESTAMP, false),
(11, 2, 2, '"Estou para seguir o caminho de toda a terra. Por isso, seja forte e seja homem.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 3, 'Obedeça ao que o Senhor, o seu Deus, exige: Ande nos seus caminhos e obedeça aos seus decretos, aos seus mandamentos, às suas ordenanças e aos seus testemunhos, conforme se acham escritos na Lei de Moisés; assim você prosperará em tudo o que fizer e por onde quer que for,', 3, CURRENT_TIMESTAMP, false),
(11, 2, 4, 'e o Senhor manterá a promessa que me fez: ‘Se os seus descendentes cuidarem de sua conduta, e se me seguirem fielmente de todo o coração e de toda a alma, você jamais ficará sem descendente no trono de Israel’.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 5, '"Você sabe muito bem o que Joabe, filho de Zeruia, me fez; o que fez com os dois comandantes dos exércitos de Israel, Abner, filho de Ner, e Amasa, filho de Jéter. Ele os matou, derramando sangue em tempos de paz; agiu como se estivesse em guerra, e com aquele sangue manchou o seu cinto e as suas sandálias.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 6, 'Proceda com a sabedoria que você tem, e não o deixe envelhecer e descer em paz à sepultura.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 7, '"Mas seja bondoso com os filhos de Barzilai, de Gileade, admita-os entre os que comem à mesa com você, pois eles me apoiaram quando fugi do seu irmão Absalão.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 8, '"Saiba que também está com você Simei, filho de Gera, o benjamita de Baurim. Ele lançou terríveis maldições contra mim no dia em que fui a Maanaim. Mas depois desceu ao meu encontro no Jordão e lhe prometi jurando pelo Senhor que não o mataria à espada.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 9, 'Mas, agora, não o considere inocente. Você é um homem sábio e saberá o que fazer com ele; apesar de ele já ser idoso, faça-o descer ensangüentado à sepultura".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 10, 'Então Davi descansou com os seus antepassados e foi sepultado na cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 11, 'Ele reinou quarenta anos em Israel: sete anos em Hebrom e trinta e três em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 12, 'Salomão assentou-se no trono de Davi, seu pai, e o seu reinado foi firmemente estabelecido.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 13, 'Adonias, o filho de Hagite, foi até Bate-Seba, mãe de Salomão. E esta lhe perguntou: "Você vem em paz? " Ele respondeu: "Sim".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 14, 'E acrescentou: "Tenho algo para lhe dizer". Ela disse: Fale!', 3, CURRENT_TIMESTAMP, false),
(11, 2, 15, '"Você sabe", disse ele, "que o reino era meu. Todo o Israel me via como o seu rei. Mas as circunstâncias mudaram, e o reino foi para o meu irmão; pois o Senhor o concedeu a ele.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 16, 'Agora, quero fazer-lhe um pedido e espero que não me seja negado. " Ela disse: "Fale! "', 3, CURRENT_TIMESTAMP, false),
(11, 2, 17, 'Então ele prosseguiu: "Peça, por favor, ao rei Salomão que me dê a sunamita Abisague por mulher, pois ele não deixará de atender você".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 18, '"Está bem", respondeu Bate-Seba, "falarei com o rei em seu favor. "', 3, CURRENT_TIMESTAMP, false),
(11, 2, 19, 'Quando Bate-Seba foi falar ao rei em favor de Adonias, Salomão levantou-se para recebê-la e inclinou-se diante dela. Depois assentou-se no seu trono, mandou que trouxessem um trono para a sua mãe, e ela se assentou à sua direita.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 20, '"Tenho um pequeno pedido para lhe fazer", disse ela. "Não deixe de me atender. " O rei respondeu: "Faça o pedido, minha mãe; não deixarei de atendê-lo".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 21, 'Então ela disse: "Dê a sunamita Abisague por mulher a seu irmão Adonias".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 22, 'O rei Salomão perguntou à sua mãe: "Por que você pede somente a sunamita Abisague para Adonias? Peça logo o reino para ele, para o sacerdote Abiatar e para Joabe, filho de Zeruia; afinal ele é o meu irmão mais velho! "', 3, CURRENT_TIMESTAMP, false),
(11, 2, 23, 'Então o rei Salomão jurou pelo Senhor: "Que Deus me castigue com todo o rigor, se isso que Adonias falou não lhe custar a sua própria vida!', 3, CURRENT_TIMESTAMP, false),
(11, 2, 24, 'E agora eu juro pelo nome do Senhor, que me estabeleceu no trono de meu pai Davi, e, conforme prometeu, fundou uma dinastia para mim, que hoje mesmo Adonias será morto! "', 3, CURRENT_TIMESTAMP, false),
(11, 2, 25, 'E o rei Salomão deu ordem a Benaia, filho de Joiada, e este feriu e matou Adonias.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 26, 'Ao sacerdote Abiatar o rei ordenou: "Vá para Anatote, para as suas terras! Você merece morrer, mas hoje eu não o matarei, pois você carregou a arca do Soberano Senhor diante de Davi, meu pai, e partilhou de todas as aflições dele".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 27, 'Então Salomão expulsou Abiatar do sacerdócio do Senhor, cumprindo a palavra que o Senhor tinha dito em Siló a respeito da família de Eli.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 28, 'Quando a notícia chegou a Joabe, que havia conspirado com Adonias, ainda que não com Absalão, ele fugiu para a Tenda do Senhor e agarrou-se às pontas do altar.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 29, 'Foi dito ao rei Salomão que Joabe havia se refugiado na Tenda do Senhor e estava ao lado do altar. Então Salomão ordenou a Benaia, filho de Joiada: "Vá matá-lo! "', 3, CURRENT_TIMESTAMP, false),
(11, 2, 30, 'Então Benaia entrou na Tenda do Senhor e disse a Joabe: "O rei lhe ordena que saia". "Não", respondeu ele, "Vou morrer aqui". Benaia relatou ao rei a resposta de Joabe.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 31, 'Então o rei ordenou a Benaia: "Faça o que ele diz. Mate-o e sepulte-o, e assim você retirará de mim e da minha família a culpa do sangue inocente que Joabe derramou.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 32, 'O Senhor fará recair sobre a cabeça dele o sangue que derramou: ele atacou dois homens mais justos e melhores do que ele, sem o conhecimento de meu pai Davi, e os matou à espada. Os dois homens eram Abner, filho de Ner, comandante do exército de Israel, e Amasa, filho de Jéter, comandante do exército de Judá.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 33, 'Que o sangue deles recaia sobre a cabeça de Joabe e sobre a dos seus descendentes para sempre. Mas que a paz do Senhor esteja para sempre sobre Davi, sobre os seus descendentes, sobre a sua dinastia e sobre o seu trono".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 34, 'Então Benaia, filho de Joiada, foi e atacou Joabe e o matou, e ele foi sepultado em sua casa no campo.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 35, 'No lugar dele o rei nomeou Benaia, filho de Joiada, no comando do exército, e o sacerdote Zadoque no lugar de Abiatar.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 36, 'Depois o rei mandou chamar Simei e lhe ordenou: "Construa para você uma casa em Jerusalém. Você morará nela e não poderá ir para nenhum outro lugar.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 37, 'Esteja certo de que no dia em que sair e atravessar o vale de Cedrom, você será morto; e você será responsável por sua própria morte".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 38, 'Simei respondeu ao rei: "A ordem do rei é boa! O teu servo lhe obedecerá". E Simei permaneceu em Jerusalém por muito tempo.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 39, 'Mas três anos depois, dois escravos de Simei fugiram para a casa de Aquis, filho de Maaca, rei de Gate. Alguém contou a Simei: "Seus escravos estão em Gate".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 40, 'Então Simei selou um jumento e foi até Aquis, em Gate, procurar os seus escravos. E de lá Simei trouxe os escravos de volta.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 41, 'Quando Salomão soube que Simei tinha ido a Gate e voltado a Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(11, 2, 42, 'mandou chamá-lo e lhe perguntou: "Eu não fiz você jurar pelo Senhor e não o adverti: No dia em que você for para qualquer outro lugar, esteja certo que você morrerá? E você me respondeu: ‘Esta ordem é boa! Obedecerei’.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 43, 'Por que não manteve o juramento ao Senhor e não obedeceu à ordem que lhe dei? "', 3, CURRENT_TIMESTAMP, false),
(11, 2, 44, 'E acrescentou: "No seu coração você sabe como você prejudicou o meu pai Davi. Agora o Senhor faz recair sua maldade sobre a sua cabeça.', 3, CURRENT_TIMESTAMP, false),
(11, 2, 45, 'Mas o rei Salomão será abençoado, e o trono de Davi será estabelecido perante o Senhor para sempre".', 3, CURRENT_TIMESTAMP, false),
(11, 2, 46, 'Então o rei deu ordem a Benaia, filho de Joiada, e este atacou Simei e o matou. Assim o reino ficou bem estabelecido nas mãos de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 1, 'Salomão aliou-se ao faraó, rei do Egito, casando-se com a filha dele. Ele a trouxe à cidade de Davi até terminar a construção do seu palácio e do templo do Senhor, e do muro em torno de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 2, 'O povo, porém, sacrificava nos lugares sagrados, pois ainda não tinha sido construído um templo em honra do nome do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 3, 'Salomão amava o Senhor, pois andava de acordo com os decretos do seu pai Davi; todavia oferecia sacrifícios e queimava incenso nos lugares sagrados.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 4, 'O rei Salomão foi a Gibeom para oferecer sacrifícios, pois ali ficava o principal lugar sagrado, e ofereceu naquele altar mil holocaustos.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 5, 'Em Gibeom o Senhor apareceu a Salomão num sonho, à noite, e lhe disse: "Peça-me o que quiser, e eu lhe darei".', 3, CURRENT_TIMESTAMP, false),
(11, 3, 6, 'Salomão respondeu: "Tu foste muito bondoso para com o teu servo, o meu pai Davi, pois ele foi fiel a ti, e foi justo e reto de coração. Tu sustentaste grande bondade para com ele e lhe deste um filho que hoje se assenta no seu trono.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 7, '"Agora, Senhor meu Deus, fizeste o teu servo reinar em lugar de meu pai Davi. Mas eu não passo de um jovem e não sei o que fazer.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 8, 'Teu servo está aqui entre o povo que escolheste, um povo tão grande que nem se pode contar.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 9, 'Dá, pois, ao teu servo um coração cheio de discernimento para governar o teu povo e capaz de distinguir entre o bem e o mal. Pois, quem pode governar este teu grande povo? "', 3, CURRENT_TIMESTAMP, false),
(11, 3, 10, 'O pedido que Salomão fez agradou ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 11, 'Por isso Deus lhe disse: "Já que você pediu isto e não uma vida longa nem riqueza, nem pediu a morte dos seus inimigos, mas discernimento para ministrar a justiça,', 3, CURRENT_TIMESTAMP, false),
(11, 3, 12, 'farei o que você pediu. Eu lhe darei um coração sábio e capaz de discernir, de modo que nunca houve nem haverá ninguém como você.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 13, 'Também lhe darei o que você não pediu: riquezas e fama; de forma que não haverá rei igual a você durante toda a sua vida.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 14, 'E, se você andar nos meus caminhos e obedecer aos meus decretos e aos meus mandamentos, como o seu pai Davi, eu prolongarei a sua vida".', 3, CURRENT_TIMESTAMP, false),
(11, 3, 15, 'Então Salomão acordou e percebeu que tinha sido um sonho. Depois voltou a Jerusalém, pôs-se perante a arca da aliança do Senhor, sacrificou holocaustos e apresentou ofertas de comunhão. Então deu um banquete para toda a sua corte.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 16, 'Certo dia duas prostitutas compareceram diante do rei.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 17, 'Uma delas disse: "Ah meu senhor! Esta mulher mora comigo na mesma casa. Eu dei à luz um filho e ela estava comigo na casa.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 18, 'Três dias depois de nascer o meu filho, esta mulher também deu à luz um filho. Estávamos sozinhas, e não havia mais ninguém na casa.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 19, '"Certa noite esta mulher se deitou sobre o seu filho, e ele morreu.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 20, 'Então ela se levantou no meio da noite e pegou o meu filho enquanto eu, tua serva, dormia, e o pôs ao seu lado. E pôs o filho dela, morto, ao meu lado.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 21, 'Ao levantar-me de madrugada para amamentar o meu filho, ele estava morto. Mas quando olhei bem para ele de manhã, vi que não era o filho que eu dera à luz".', 3, CURRENT_TIMESTAMP, false),
(11, 3, 22, 'A outra mulher disse: "Não! O que está vivo é meu filho; o morto é seu". Mas a primeira insistia: "Não! O morto é seu; o vivo é meu". Assim elas discutiram diante do rei.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 23, 'O rei disse: "Esta afirma: ‘Meu filho está vivo, e o seu filho está morto’, enquanto aquela diz: ‘Não! Seu filho está morto, e o meu está vivo’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 3, 24, 'Então o rei ordenou: "Tragam-me uma espada". Trouxeram-lhe.', 3, CURRENT_TIMESTAMP, false),
(11, 3, 25, 'Ele então ordenou: "Cortem a criança viva ao meio e dêem metade a uma e metade à outra".', 3, CURRENT_TIMESTAMP, false),
(11, 3, 26, 'A mãe do filho que estava vivo, movida pela compaixão materna, clamou: "Por favor, meu senhor, dê a criança viva a ela! Não a mate! " A outra, porém, disse: "Não será nem minha nem sua. Cortem-na ao meio! "', 3, CURRENT_TIMESTAMP, false),
(11, 3, 27, 'Então o rei deu o seu veredicto: "Não matem a criança! Dêem-na à primeira mulher. Ela é a mãe".', 3, CURRENT_TIMESTAMP, false),
(11, 3, 28, 'Quando todo o Israel ouviu o veredicto do rei, passou a respeitá-lo profundamente, pois viu que a sabedoria de Deus estava nele para fazer justiça.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 1, 'E assim o rei Salomão tornou-se rei sobre todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 2, 'E estes foram os seus principais assessores: Azarias, filho de Zadoque: o sacerdote;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 3, 'Eliorefe e Aías, filhos de Sisa: secretários; Josafá, filho de Ailude: arquivista real;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 4, 'Benaia, filho de Joiada: comandante do exército; Zadoque e Abiatar: sacerdotes;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 5, 'Azarias, filho de Natã: responsável pelos governadores distritais; Zabude, filho de Natã: sacerdote e conselheiro pessoal do rei;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 6, 'Aisar: responsável pelo palácio; Adonirão, filho de Abda: chefe de trabalhos forçados.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 7, 'Salomão tinha também, doze governadores distritais em todo o Israel, que forneciam provisões para o rei e para o palácio real. Cada um deles tinha que fornecer suprimentos durante um mês do ano.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 8, 'Estes são os seus nomes: Ben-Hur, nos montes de Efraim;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 9, 'Ben-Dequer, em Macaz, Saalbim, Bete-Semes e Elom-Bete-Hanã;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 10, 'Ben-Hesede, em Arubote, Socó e toda a terra de Héfer;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 11, 'Ben-Abinadabe, em Nafote-Dor. Tafate, filha de Salomão, era sua mulher;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 12, 'Baaná, filho de Ailude, em Taanaque e Megido e toda Bete-Seã, próxima de Zaretã, abaixo de Jezreel, desde Bete-Seã até Abel-Meolá, indo além dos limites de Jocmeão;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 13, 'Ben-Geder, em Ramote-Gileade e nos povoados de Jair, filho de Manassés, em Gileade, bem como o distrito de Argobe, em Basã, e as suas sessenta grandes cidades muradas com trancas de bronze nos portões;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 14, 'Ainadabe, filho de Ido, em Maanaim;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 15, 'Aimaás, em Naftali. Ele se casou com Basemate, filha de Salomão;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 16, 'Baaná, filho de Husai, em Aser e em Bealote;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 17, 'Josafá, filho de Parua, em Issacar;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 18, 'Simei, filho de Elá, em Benjamim;', 3, CURRENT_TIMESTAMP, false),
(11, 4, 19, 'Geber, filho de Uri, em Gileade, a terra de Seom, rei dos amorreus, e de Ogue, rei de Basã. Ele era o único governador desse distrito.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 20, 'Judá e Israel eram tão numerosos como a areia da praia; eles comiam, bebiam e eram felizes.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 21, 'E Salomão governava todos os reinos, desde o Rio até a terra dos filisteus, chegando até a fronteira do Egito. Esses reinos traziam tributos e foram submissos a Salomão durante toda a sua vida.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 22, 'As provisões diárias de Salomão eram trinta tonéis da melhor farinha e sessenta tonéis de farinha comum,', 3, CURRENT_TIMESTAMP, false),
(11, 4, 23, 'dez cabeças de gado engordado em cocheiras, vinte de gado engordado no pasto e cem ovelhas e bodes, bem como cervos, gazelas, corças e aves escolhidas.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 24, 'Ele governava todos os reinos a oeste do Rio, desde Tifsa até Gaza, e tinha paz em todas as fronteiras.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 25, 'Durante a vida de Salomão, Judá e Israel viveram em segurança, cada homem debaixo da sua videira e da sua figueira, desde Dã até Berseba.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 26, 'Salomão possuía quatro mil cocheiras para cavalos de carros de guerra, e doze mil cavalos.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 27, 'Todo mês um dos governadores distritais fornecia provisões ao rei Salomão e a todos os que vinham participar de sua mesa. Cuidavam para que não faltasse nada.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 28, 'Também traziam ao devido lugar suas quotas de cevada e de palha para os cavalos de carros de guerra e para os outros cavalos.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 29, 'Deus deu a Salomão sabedoria, discernimento extraordinário e uma abrangência de conhecimento tão imensurável quanto a areia do mar.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 30, 'A sabedoria de Salomão era maior do que a de todos os homens do oriente, bem como de toda a sabedoria do Egito.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 31, 'Ele era mais sábio do que qualquer outro homem, mais do que o ezraíta Etã; mais sábio do que Hemã, Calcol e Darda, filhos de Maol. E a sua fama espalhou-se por todas as nações em redor.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 32, 'Ele compôs três mil provérbios, e os seus cânticos chegaram a mil e cinco.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 33, 'Descreveu as plantas, desde o cedro do Líbano até o hissopo que brota nos muros. Também discorreu sobre os quadrúpedes, as aves, os animais que se movem rente ao chão e os peixes.', 3, CURRENT_TIMESTAMP, false),
(11, 4, 34, 'Homens de todas as nações vinham ouvir a sabedoria de Salomão. Eram enviados por todos os reis que tinham ouvido falar de sua sabedoria.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 1, 'Quando Hirão, rei de Tiro, soube que Salomão tinha sido ungido rei, mandou seus conselheiros a Salomão, pois sempre tinha sido amigo leal de Davi.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 2, 'Salomão enviou esta mensagem a Hirão:', 3, CURRENT_TIMESTAMP, false),
(11, 5, 3, '"Tu bem sabes que foi por causa das guerras travadas de todos os lados contra meu pai Davi que ele não pôde construir um templo em honra do nome do Senhor, o seu Deus, até que o Senhor pusesse os seus inimigos debaixo dos seus pés.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 4, 'Mas agora o Senhor, o meu Deus, concedeu-me paz em todas as fronteiras, e não tenho que enfrentar nem inimigos nem calamidades.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 5, 'Pretendo, por isso, construir um templo em honra do nome do Senhor, do meu Deus, conforme o Senhor disse a meu pai Davi: ‘O seu filho, a quem colocarei no trono em seu lugar, construirá o templo em honra do meu nome’.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 6, '"Agora te peço que ordenes que cortem para mim cedros do Líbano. Os meus servos trabalharão com os teus, e eu pagarei a teus servos o salário que determinares. Sabes que não há entre nós ninguém tão hábil em cortar árvores quanto os sidônios".', 3, CURRENT_TIMESTAMP, false),
(11, 5, 7, 'Hirão ficou muito alegre quando ouviu a mensagem de Salomão, e exclamou: "Bendito seja o Senhor, pois deu a Davi um filho sábio para governar essa grande nação".', 3, CURRENT_TIMESTAMP, false),
(11, 5, 8, 'E Hirão respondeu a Salomão: "Recebi a mensagem que me enviaste e atenderei ao teu pedido, enviando-lhe madeira de cedro e de pinho.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 9, 'Meus servos levarão a madeira do Líbano até o mar, e eu a farei flutuar em jangadas no mar até o lugar que me indicares. Ali eu a deixarei e tu poderás levá-la. E em troca, fornecerás alimento para a minha corte".', 3, CURRENT_TIMESTAMP, false),
(11, 5, 10, 'Assim Hirão se tornou fornecedor de toda a madeira de cedro e de pinho que Salomão desejava,', 3, CURRENT_TIMESTAMP, false),
(11, 5, 11, 'e Salomão deu a Hirão vinte mil tonéis de trigo para suprir de mantimento a sua corte, além de vinte mil tonéis de azeite de oliva puro. Era o que Salomão dava anualmente a Hirão.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 12, 'O Senhor deu sabedoria a Salomão, como lhe havia prometido. Houve paz entre Hirão e Salomão, e os dois fizeram um tratado.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 13, 'O rei Salomão arregimentou trinta mil trabalhadores de todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 14, 'Ele os mandou para o Líbano em grupos de dez mil por mês, e eles se revezavam: passavam um mês no Líbano e dois em casa. Adonirão chefiava o trabalho.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 15, 'Salomão tinha setenta mil carregadores e oitenta mil cortadores de pedra nas colinas,', 3, CURRENT_TIMESTAMP, false),
(11, 5, 16, 'bem como três mil e trezentos capatazes que supervisionavam o trabalho e comandavam os operários.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 17, 'Por ordem do rei retiravam da pedreira grandes blocos de pedra de ótima qualidade para servirem de alicerce de pedras lavradas para o templo.', 3, CURRENT_TIMESTAMP, false),
(11, 5, 18, 'Os construtores de Salomão e de Hirão e os homens de Gebal cortavam e preparavam a madeira e as pedras para a construção do templo.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 1, 'Quatrocentos e oitenta anos depois que os israelitas saíram do Egito, no quarto ano do reinado de Salomão em Israel, no mês de zive, o segundo mês, ele começou a construir o templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 2, 'O templo que o rei Salomão construiu para o Senhor media vinte e sete metros de comprimento, nove metros de largura e treze metros e meio de altura.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 3, 'O pórtico da entrada do santuário tinha a largura do templo, que era de nove metros, e avançava quatro metros e meio à frente do templo.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 4, 'Ele fez para o templo, janelas com grades estreitas.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 5, 'Junto às paredes do átrio principal e do santuário interior, construiu uma estrutura em torno do edifício, na qual havia salas laterais.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 6, 'O andar inferior tinha dois metros e vinte e cinco centímetros de largura, o andar intermediário tinha dois metros e setenta centímetros e o terceiro andar tinha três metros e quinze centímetros. Ele fez saliências de apoio nas paredes externas do templo, de modo que não houve necessidade de perfurar as paredes.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 7, 'Na construção do templo só foram usados blocos lavrados nas pedreiras, e não se ouviu no templo nenhum barulho de martelo, nem de talhadeira, nem de qualquer outra ferramenta de ferro durante a sua construção.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 8, 'A entrada para o andar inferior ficava no lado sul do templo; uma escada conduzia até o andar intermediário e dali ao terceiro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 9, 'Assim ele construiu o templo e o terminou, fazendo-lhe um forro com vigas e tábuas de cedro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 10, 'E fez as salas laterais ao longo de todo o templo. Cada uma tinha dois metros e vinte e cinco centímetros de altura, e elas estavam ligadas ao templo por vigas de cedro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 11, 'E a palavra do Senhor veio a Salomão dizendo:', 3, CURRENT_TIMESTAMP, false),
(11, 6, 12, '"Quanto a este templo que você está construindo, se você seguir os meus decretos, executar os meus juízos e obedecer a todos os meus mandamentos, cumprirei por meio de você a promessa que fiz ao seu pai Davi,', 3, CURRENT_TIMESTAMP, false),
(11, 6, 13, 'viverei no meio dos israelitas e não abandonarei Israel, o meu povo".', 3, CURRENT_TIMESTAMP, false),
(11, 6, 14, 'E assim Salomão concluiu a construção do templo.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 15, 'Forrou as paredes do templo por dentro com tábuas de cedro, cobrindo-as desde o chão até o teto, e fez o soalho do templo com tábuas de pinho.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 16, 'Separou nove metros na parte de trás do templo, fazendo uma divisão com tábuas de cedro, do chão ao teto, para formar dentro do templo o santuário interno, o Lugar Santíssimo.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 17, 'O átrio principal em frente dessa sala media dezoito metros de comprimento.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 18, 'O interior do templo era de cedro, com figuras entalhadas de frutos e flores abertas. Tudo era de cedro; não se via pedra alguma.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 19, 'Preparou também o santuário interno no templo para ali colocar a arca da aliança do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 20, 'O santuário interno tinha nove metros de comprimento, nove de largura e nove de altura. Ele revestiu o interior de ouro puro, e também revestiu de ouro o altar de cedro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 21, 'Salomão cobriu o interior do templo de ouro puro, e estendeu correntes de ouro em frente do santuário interno, que também foi revestido de ouro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 22, 'Assim, revestiu de ouro todo o interior do templo e também o altar que pertencia ao santuário interno.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 23, 'No santuário interno ele esculpiu dois querubins de madeira de oliveira, cada um com quatro metros e meio de altura.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 24, 'As asas abertas dos querubins mediam dois metros e vinte e cinco centímetros: quatro metros e meio da ponta de uma asa à ponta da outra.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 25, 'Os dois querubins tinham a mesma medida e a mesma forma.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 26, 'A altura de cada querubim era de quatro metros e meio.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 27, 'Ele colocou os querubins, com as asas abertas, no santuário interno do templo. A asa de um querubim encostava numa parede, e a do outro encostava na outra. As suas outras asas encostavam uma na outra no meio do santuário.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 28, 'Ele revestiu os querubins de ouro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 29, 'Nas paredes ao redor do templo, tanto na parte interna como na externa, ele esculpiu querubins, tamareiras e flores abertas.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 30, 'Também revestiu de ouro os pisos, tanto na parte interna como na externa do templo.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 31, 'Para a entrada do santuário interno fez portas de oliveira com batentes de cinco lados.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 32, 'E nas duas portas de madeira de oliveira esculpiu querubins, tamareiras e flores abertas, e revestiu os querubins e as tamareiras de ouro batido.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 33, 'Também fez pilares de quatro lados, de madeira de oliveira para a entrada do templo.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 34, 'Fez também duas portas de pinho, cada uma com duas folhas que se articulavam por meio de dobradiças.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 35, 'Entalhou figuras de querubins, de tamareiras e de flores abertas nas portas e as revestiu todas igualmente de ouro batido.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 36, 'E construiu o pátio interno com três camadas de pedra lavrada e uma de vigas de cedro.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 37, 'O alicerce do templo do Senhor foi lançado no mês de zive do quarto ano.', 3, CURRENT_TIMESTAMP, false),
(11, 6, 38, 'No mês de bul, o oitavo mês, do décimo primeiro ano, o templo foi terminado em todos os seus detalhes, de acordo com as suas especificações. Ele levou sete anos para construí-lo.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 1, 'Salomão levou treze anos para terminar a construção do seu palácio.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 2, 'Ele construiu o Palácio da Floresta do Líbano com quarenta e cinco metros de comprimento, vinte e dois metros e meio de largura e treze metros e meio de altura, sustentado por quatro fileiras de colunas de cedro sobre as quais apoiavam-se vigas de cedro aparelhadas.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 3, 'O forro que ficava sobre as vigas que se apoiavam nas colunas era de cedro, eram quarenta e cinco vigas, quinze por fileira.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 4, 'Havia janelas dispostas de três em três, uma em frente da outra.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 5, 'Todas as portas tinham estrutura retangular; ficavam na parte da frente, dispostas de três em três, uma em frente da outra.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 6, 'Fez um pórtico de colunas de vinte e dois metros e meio de comprimento e treze metros e meio de largura. Em frente havia outro pórtico com colunas e uma cobertura que se estendia além das colunas.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 7, 'Construiu a Sala do Trono, isto é, a Sala da Justiça, onde iria julgar, e revestiu-a de cedro desde o teto até o chão.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 8, 'E o palácio para sua moradia, no outro pátio, tinha um formato semelhante. Salomão fez também um palácio como esse para a filha do faraó, com quem tinha se casado.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 9, 'Todas essas construções, desde o lado externo até o grande pátio e do alicerce até o beiral, foram feitas de pedra de qualidade superior, cortadas sob medida e desbastadas com uma serra nos lados interno e externo.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 10, 'Os alicerces foram lançados com pedras grandes de qualidade superior, algumas medindo quatro metros e meio e outras três metros e sessenta centímetros.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 11, 'Na parte de cima havia pedras de qualidade superior, cortadas sob medida, e vigas de cedro.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 12, 'O grande pátio era cercado por um muro de três camadas de pedras lavradas e uma camada de vigas de cedro aparelhadas, da mesma maneira que o pátio interior do templo do Senhor, com o seu pórtico.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 13, 'O rei Salomão enviara mensageiros a Tiro e trouxera Hurão,', 3, CURRENT_TIMESTAMP, false),
(11, 7, 14, 'filho de uma viúva da tribo de Naftali e de um cidadão de Tiro, um artífice em bronze. Hurão era extremamente hábil, experiente e sabia fazer todo tipo de trabalho em bronze. Apresentou-se ao rei Salomão e fez depois todo o trabalho que lhe foi designado.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 15, 'Ele fundiu duas colunas de bronze, cada uma com oito metros e dez centímetros de altura e cinco metros e quarenta centímetros de circunferência, medidas pelo fio apropriado.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 16, 'Também fez dois capitéis de bronze fundido para colocar no alto das colunas; cada capitel tinha dois metros e vinte e cinco centímetros de altura.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 17, 'Conjuntos de correntes entrelaçadas ornamentavam os capitéis no alto das colunas, sete em cada capitel.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 18, 'Fez também romãs em duas fileiras que circundavam cada conjunto de correntes para cobrir os capitéis no alto das colunas. Fez o mesmo com cada capitel.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 19, 'Os capitéis no alto das colunas do pórtico tinham o formato de lírios, com um metro e oitenta centímetros de altura.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 20, 'Nos capitéis das duas colunas, acima da parte que tinha formato de taça, perto do conjunto de correntes, havia duzentas romãs enfileiradas ao redor.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 21, 'Ele levantou as colunas na frente do pórtico do templo. Deu o nome de Jaquim à coluna ao sul e de Boaz à coluna ao norte.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 22, 'Os capitéis no alto tinham a forma de lírios. E assim completou-se o trabalho das colunas.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 23, 'Fez o tanque de metal fundido, redondo, medindo quatro metros e meio de diâmetro e dois metros e vinte e cinco centímetros de altura. Era preciso um fio de treze metros e meio para medir a sua circunferência.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 24, 'Abaixo da borda e ao seu redor havia duas fileiras de frutos, de cinco em cinco centímetros, fundidas numa só peça com o tanque.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 25, 'O tanque ficava sobre doze touros, três voltados para o norte, três para o oeste, três para o sul e três para o leste. Ficava em cima deles, e as pernas traseiras dos touros eram voltadas para o centro.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 26, 'A espessura do tanque era de quatro dedos, e sua borda era como a borda de um cálice, como uma flor de lírio. Tinha capacidade de quarenta mil litros.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 27, 'Também fez dez carrinhos de bronze; cada um tinha um metro e oitenta centímetros de comprimento e de largura, e um metro e trinta e cinco centímetros de altura.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 28, 'Os carrinhos eram feitos assim: Tinham placas laterais presas a armações.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 29, 'Nas placas, entre as armações, havia figuras de leões, bois e querubins: Sobre as armações, acima e abaixo dos leões e bois, havia grinaldas de metal batido.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 30, 'Em cada carrinho havia quatro rodas de bronze com eixos de bronze, cada um com uma bacia apoiada em quatro pés e fundida ao lado de cada grinalda.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 31, 'Do lado de dentro do carrinho havia uma abertura circular com quarenta e cinco centímetros de profundidade. Essa abertura era redonda, e com sua base media setenta centímetros. Havia esculturas em torno da abertura. As placas dos carrinhos eram quadradas, e não redondas.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 32, 'As quatro rodas ficavam sob as placas, e os eixos das rodas ficavam presos ao estrado. O diâmetro de cada roda era de setenta centímetros.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 33, 'As rodas eram feitas como rodas de carros; os eixos, os aros, os raios e os cubos eram todos de metal fundido.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 34, 'Havia quatro cabos que se projetavam do carrinho, um em cada canto.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 35, 'No alto do carrinho havia uma lâmina circular de vinte e dois centímetros de comprimento. Os apoios e as placas estavam fixados no alto do carrinho.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 36, 'Ele esculpiu figuras de querubins, leões e tamareiras na superfície dos apoios e nas placas, em cada espaço disponível, com grinaldas ao redor.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 37, 'Foi assim que fez os dez carrinhos. Foram todos fundidos nos mesmos moldes e eram idênticos no tamanho e na forma.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 38, 'Depois ele fez dez pias de bronze, cada uma com capacidade de oitocentos litros, medindo um metro e oitenta centímetros de diâmetro; uma pia para cada um dos dez carrinhos.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 39, 'Ele pôs cinco carrinhos no lado sul do templo e cinco no lado norte. Pôs o tanque no lado sul, no canto sudeste do templo.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 40, 'Também fez os jarros, as pás e as bacias para aspersão. Assim, Hurão completou todo o trabalho de que fora encarregado pelo rei Salomão, no templo do Senhor:', 3, CURRENT_TIMESTAMP, false),
(11, 7, 41, 'as duas colunas; os dois capitéis em forma de taça no alto das colunas; os dois conjuntos de correntes que decoravam os dois capitéis;', 3, CURRENT_TIMESTAMP, false),
(11, 7, 42, 'as quatrocentas romãs para os dois conjuntos de correntes, sendo duas fileiras de romãs para cada conjunto;', 3, CURRENT_TIMESTAMP, false),
(11, 7, 43, 'os dez carrinhos com as suas dez pias;', 3, CURRENT_TIMESTAMP, false),
(11, 7, 44, 'o tanque e os doze touros debaixo dele;', 3, CURRENT_TIMESTAMP, false),
(11, 7, 45, 'e os jarros, as pás e as bacias de aspersão. Todos esses utensílios que Hurão fez a pedido do rei Salomão para o templo do Senhor, eram de bronze polido.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 46, 'Foi na planície do Jordão, entre Sucote e Zaretã, que o rei os mandou fundir, em moldes de barro.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 47, 'Salomão não mandou pesar esses utensílios, tão grande era o seu número que o peso do bronze não foi determinado.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 48, 'Além desses, Salomão mandou fazer também todos estes outros utensílios para o templo do Senhor: o altar de ouro; a mesa de ouro sobre a qual ficavam os pães da Presença;', 3, CURRENT_TIMESTAMP, false),
(11, 7, 49, 'os candelabros de ouro puro, cinco à direita e cinco à esquerda, em frente do santuário interno; as flores, as lâmpadas e as tenazes de ouro;', 3, CURRENT_TIMESTAMP, false),
(11, 7, 50, 'as bacias, os cortadores de pavio, as bacias para aspersão, as tigelas e os incensários; e as dobradiças de ouro para as portas da sala interna, o Lugar Santíssimo, e também para as portas do átrio principal.', 3, CURRENT_TIMESTAMP, false),
(11, 7, 51, 'Terminada toda a obra que Salomão realizou para o templo do Senhor, ele trouxe tudo que seu pai havia consagrado e colocou junto com os tesouros do templo do Senhor: a prata, o ouro e os utensílios.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 1, 'Então o rei Salomão reuniu em Jerusalém as autoridades de Israel, todos os líderes das tribos e os chefes das famílias israelitas, para levarem de Sião, a cidade de Davi, a arca da aliança do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 2, 'E todos os homens de Israel uniram-se ao rei Salomão por ocasião da festa, no mês de etanim, que é o sétimo mês.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 3, 'Quando todas as autoridades de Israel chegaram, os sacerdotes pegaram', 3, CURRENT_TIMESTAMP, false),
(11, 8, 4, 'a arca do Senhor e a levaram, com a Tenda do Encontro e com todos os seus utensílios sagrados. Foram os sacerdotes e os levitas que levaram tudo.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 5, 'O rei Salomão e toda a comunidade de Israel que se havia reunido a ele diante da arca, sacrificaram tantas ovelhas e bois que nem era possível contar.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 6, 'Os sacerdotes levaram a arca da aliança do Senhor para o seu lugar no santuário interno do templo, no Lugar Santíssimo, e a colocaram debaixo das asas dos querubins.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 7, 'Os querubins tinham suas asas estendidas sobre o lugar da arca e cobriam a arca e as varas utilizadas para o transporte.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 8, 'Essas varas eram tão compridas que as suas pontas, que se estendiam para fora da arca, podiam ser vistas da frente do santuário interno, mas não de fora dele; e elas estão lá até hoje.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 9, 'Na arca havia só as duas tábuas de pedra que Moisés tinha colocado quando estava em Horebe, onde o Senhor fez uma aliança com os israelitas depois que saíram do Egito.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 10, 'Quando os sacerdotes se retiraram do Lugar Santo, uma nuvem encheu o templo do Senhor,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 11, 'de forma que os sacerdotes não podiam desempenhar o seu serviço, pois a glória do Senhor encheu o seu templo.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 12, 'E Salomão exclamou: "O Senhor disse que habitaria numa nuvem escura!', 3, CURRENT_TIMESTAMP, false),
(11, 8, 13, 'Na realidade construí para ti um templo magnífico, um lugar para nele habitares para sempre! "', 3, CURRENT_TIMESTAMP, false),
(11, 8, 14, 'Depois o rei virou-se e abençoou toda a assembléia de Israel, que estava ali de pé.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 15, 'E disse: "Bendito seja o Senhor, o Deus de Israel, que com a sua mão cumpriu o que prometeu com sua própria boca a meu pai Davi, quando lhe disse:', 3, CURRENT_TIMESTAMP, false),
(11, 8, 16, '‘Desde o dia em que tirei o meu povo Israel do Egito, não escolhi nenhuma cidade das tribos de Israel para nela construir um templo em honra do meu nome. Mas escolhi Davi para governar Israel, o meu povo’.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 17, '"Meu pai Davi tinha no coração o propósito de construir um templo em honra do nome do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 18, 'Mas o Senhor lhe disse: ‘Você fez bem em ter no coração o plano de construir um templo em honra do meu nome;', 3, CURRENT_TIMESTAMP, false),
(11, 8, 19, 'no entanto, não será você que o construirá, mas o seu filho, que procederá de você; ele construirá o templo em honra do meu nome’.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 20, '"E o Senhor cumpriu a sua promessa: Sou o sucessor de meu pai Davi, e agora ocupo o trono de Israel, como o Senhor tinha prometido, e construí o templo em honra do nome do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 21, 'Providenciei nele um lugar para a arca, na qual estão as tábuas da aliança do Senhor, aliança que fez com os nossos antepassados quando os tirou do Egito".', 3, CURRENT_TIMESTAMP, false),
(11, 8, 22, 'Depois Salomão colocou-se diante do altar do Senhor, diante de toda a assembléia de Israel, levantou as mãos para o céu', 3, CURRENT_TIMESTAMP, false),
(11, 8, 23, 'e orou: "Senhor, Deus de Israel, não há Deus como tu em cima nos céus nem embaixo na terra! Tu que guardas a tua aliança de amor com os teus servos que, de todo o coração, andam segundo a tua vontade.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 24, 'Cumpriste a tua promessa a teu servo Davi, meu pai; com tua boca prometeste e com tua mão a cumpriste, conforme hoje se vê.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 25, '"Agora, Senhor, Deus de Israel, cumpre a outra promessa que fizeste a teu servo Davi, meu pai, quando disseste: ‘Você nunca deixará de ter, diante de mim, um descendente que se assente no trono de Israel, se tão-somente os seus descendentes tiverem o cuidado de, em tudo, andarem segundo a minha vontade, como você tem feito’.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 26, 'Agora, ó Deus de Israel, que se confirme a palavra que falaste a teu servo Davi, meu pai.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 27, '"Mas será possível que Deus habite na terra? Os céus, mesmo os mais altos céus, não podem conter-te. Muito menos este templo que construí!', 3, CURRENT_TIMESTAMP, false),
(11, 8, 28, 'Ainda assim, atende à oração do teu servo e ao seu pedido de misericórdia, ó Senhor, meu Deus. Ouve o clamor e a oração que o teu servo faz hoje na tua presença.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 29, 'Estejam os teus olhos voltados dia e noite para este templo, lugar do qual disseste que nele porias o teu nome, para que ouças a oração que o teu servo fizer voltado para este lugar.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 30, 'Ouve as súplicas do teu servo e de Israel, teu povo, quando orarem voltados para este lugar. Ouve desde os céus, lugar da tua habitação, e quando ouvires, dá-lhes o teu perdão.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 31, '"Quando um homem pecar contra seu próximo e tiver que fazer um juramento, e vier jurar diante do teu altar neste templo,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 32, 'ouve dos céus e age. Julga os teus servos; condena o culpado, fazendo recair sobre a sua própria cabeça o resultado da sua conduta, e declara sem culpa o inocente, dando-lhe o que a sua inocência merece.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 33, '"Quando Israel, o teu povo, for derrotado por um inimigo por ter pecado contra ti, e voltar-se para ti e invocar o teu nome, orando e suplicando a ti neste templo,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 34, 'ouve dos céus e perdoa o pecado de Israel, teu povo, e traze-o de volta à terra que deste aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 35, '"Quando fechar-se o céu, e não houver chuva por haver o teu povo pecado contra ti, e, se o teu povo, voltado para este lugar, invocar o teu nome e afastar-se do seu pecado por o haveres castigado,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 36, 'ouve dos céus e perdoa o pecado dos teus servos, do teu povo Israel. Ensina-lhes o caminho certo e envia chuva sobre a tua terra, que deste por herança ao teu povo.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 37, '"Quando houver fome ou praga no país, ferrugem e mofo, gafanhotos peregrinos e gafanhotos devastadores, ou quando inimigos sitiarem suas cidades, quando, em meio a qualquer praga ou epidemia,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 38, 'uma oração ou súplica por misericórdia for feita por um israelita ou por todo o teu povo Israel, cada um sentindo as suas próprias aflições e dores, estendendo as mãos na direção deste templo,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 39, 'ouve dos céus, o lugar da tua habitação. Perdoa e age; trata cada um de acordo com o que merece, visto que conheces o seu coração. Sim, só tu conheces o coração do homem.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 40, 'Assim eles te temerão durante todo o tempo em que viverem na terra que deste aos nossos antepassados.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 41, '"Quanto ao estrangeiro, que não pertence ao teu povo Israel, e que veio de uma terra distante por causa do teu nome —', 3, CURRENT_TIMESTAMP, false),
(11, 8, 42, 'pois ouvirão acerca do teu grande nome, da tua mão poderosa e do teu braço forte — quando ele vier e orar voltado para este templo,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 43, 'ouve dos céus, lugar da tua habitação, e atende o pedido do estrangeiro, a fim de que todos os povos da terra conheçam o teu nome e te temam, como faz Israel, teu povo, e saibam que este templo que construí traz o teu nome.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 44, '"Quando o teu povo for à guerra contra os seus inimigos, por onde quer que tu o enviares, e orar ao Senhor voltado para a cidade que escolheste e para o templo que construí em honra do teu nome,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 45, 'então ouve dos céus a sua oração e a sua súplica, e defende a sua causa.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 46, '"Quando pecarem contra ti, pois não há ninguém que não peque, e ficares irado com eles e os entregares ao inimigo, que os leve prisioneiros para a sua terra, distante ou próxima;', 3, CURRENT_TIMESTAMP, false),
(11, 8, 47, 'se eles caírem em si, na terra para a qual foram deportados, e se arrependerem e lá orarem: ‘Pecamos, praticamos o mal e fomos rebeldes’;', 3, CURRENT_TIMESTAMP, false),
(11, 8, 48, 'e se lá eles se voltarem para ti de todo o coração e de toda a sua alma, na terra dos inimigos que os levaram como prisioneiros, e orarem voltados para a terra que deste aos seus antepassados, para a cidade que escolheste e para o templo que construí em honra do teu nome,', 3, CURRENT_TIMESTAMP, false),
(11, 8, 49, 'então, desde os céus, o lugar da tua habitação, ouve a sua oração e a sua súplica, e defende a sua causa.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 50, 'Perdoa o teu povo, que pecou contra ti; perdoa todas as transgressões que cometeram contra ti, e faze com que os seus conquistadores tenham misericórdia deles;', 3, CURRENT_TIMESTAMP, false),
(11, 8, 51, 'pois são o teu povo e a tua herança, que tiraste do Egito, da fornalha de fundição.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 52, '"Que os teus olhos estejam abertos para a súplica do teu servo e para a súplica do teu povo Israel, e que os ouças sempre que clamarem a ti.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 53, 'Pois tu os escolheste dentre todos os povos da terra para serem a tua herança, assim como declaraste por meio do teu servo Moisés, quando tu, ó Soberano Senhor, tiraste os nossos antepassados do Egito".', 3, CURRENT_TIMESTAMP, false),
(11, 8, 54, 'Quando Salomão terminou a oração e a súplica ao Senhor, levantou-se diante do altar do Senhor, onde tinha se ajoelhado e estendido as mãos para o céu.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 55, 'Pôs-se de pé e abençoou em voz alta toda a assembléia de Israel, dizendo:', 3, CURRENT_TIMESTAMP, false),
(11, 8, 56, '"Bendito seja o Senhor, que deu descanso a Israel, seu povo, como havia prometido. Não ficou sem cumprimento nem uma de todas as boas promessas que ele fez por meio do seu servo Moisés.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 57, 'Que o Senhor, o nosso Deus, esteja conosco, assim como esteve com os nossos antepassados. Que ele jamais nos deixe nem nos abandone!', 3, CURRENT_TIMESTAMP, false),
(11, 8, 58, 'E faça com que de coração nos voltemos para ele, a fim de andarmos em todos os seus caminhos e obedecermos aos seus mandamentos, decretos e ordenanças, que deu aos nossos antepassados.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 59, 'E que as palavras da minha súplica ao Senhor tenham acesso ao Senhor, ao nosso Deus, dia e noite, para que ele defenda a causa do seu servo e a causa de Israel, seu povo, de acordo com o que precisarem.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 60, 'Assim, todos os povos da terra saberão que o Senhor é Deus e que não há nenhum outro.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 61, 'Mas vocês, tenham coração íntegro para com o Senhor, o nosso Deus, para viverem por seus decretos e obedecerem aos seus mandamentos, como acontece hoje".', 3, CURRENT_TIMESTAMP, false),
(11, 8, 62, 'Então o rei Salomão e todo o Israel ofereceram sacrifícios ao Senhor;', 3, CURRENT_TIMESTAMP, false),
(11, 8, 63, 'ele ofereceu em sacrifício de comunhão ao Senhor vinte e dois mil bois e cento e vinte mil ovelhas. Assim o rei e todos os israelitas fizeram a dedicação do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 64, 'Naquele mesmo dia o rei consagrou a parte central do pátio, que ficava na frente do templo do Senhor, e ali ofereceu holocaustos, ofertas de cereal e a gordura das ofertas de comunhão, pois o altar de bronze diante do Senhor era pequeno demais para comportar os holocaustos, as ofertas de cereal e a gordura das ofertas de comunhão.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 65, 'E foi assim que Salomão, junto com todo o Israel, celebrou a festa naquela data; era uma grande multidão, gente vinda desde Lebo-Hamate até o ribeiro do Egito. Comemoraram diante do Senhor, o nosso Deus, durante sete dias.', 3, CURRENT_TIMESTAMP, false),
(11, 8, 66, 'No oitavo dia Salomão mandou o povo para casa. Eles abençoaram o rei e foram embora, jubilosos e de coração alegre por todas as coisas boas que o Senhor havia feito por seu servo Davi e por seu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 1, 'Quando Salomão acabou de construir o templo do Senhor, o palácio real e tudo mais que desejara construir,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 2, 'o Senhor lhe apareceu pela segunda vez, como lhe havia aparecido em Gibeom.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 3, 'O Senhor lhe disse: "Ouvi a oração e a súplica que você fez diante de mim; consagrei este templo que você construiu, para que nele habite o meu nome para sempre. Os meus olhos e o meu coração nele sempre estarão.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 4, '"E se você andar segundo a minha vontade, com integridade de coração e com retidão, como fez o seu pai Davi, se fizer tudo o que eu lhe ordeno, obedecendo aos meus decretos e às minhas ordenanças,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 5, 'firmarei para sempre sobre Israel o seu trono, conforme prometi a Davi, seu pai, quando lhe disse: Você nunca deixará de ter um descendente para governar Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 6, '"Mas, se vocês ou seus filhos se afastarem de mim e não obedecerem aos mandamentos e aos decretos que lhes dei, e prestarem culto a outros deuses e adorá-los,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 7, 'desarraigarei Israel da terra que lhes dei, e lançarei para longe da minha presença este templo que consagrei ao meu nome. Israel se tornará então motivo de zombaria entre todos os povos.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 8, 'E, embora agora este templo seja imponente, todos os que passarem por ele ficarão espantados e perguntarão: ‘Por que o Senhor fez uma coisa dessas a esta terra e a este templo? ’', 3, CURRENT_TIMESTAMP, false),
(11, 9, 9, 'E a resposta será: ‘Porque abandonaram o Senhor, o seu Deus, que tirou os seus antepassados do Egito, e se apegaram a outros deuses, adorando-os e prestando-lhes culto; por isso o Senhor trouxe sobre eles toda esta desgraça’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 9, 10, 'Depois de vinte anos, durante os quais construiu estes dois edifícios, o templo do Senhor e o palácio real,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 11, 'o rei Salomão deu vinte cidades da Galiléia a Hirão, rei de Tiro, pois Hirão lhe havia fornecido toda a madeira de cedro e de pinho e o ouro que ele precisou.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 12, 'Mas, quando este veio de Tiro para ver as cidades que Salomão lhe dera, não gostou.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 13, '"Que cidades são essas que você me deu, meu irmão? ", ele perguntou. E as chamou terra de Cabul, nome que elas têm até hoje.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 14, 'Hirão tinha enviado ao rei quatro mil e duzentos quilos de ouro!', 3, CURRENT_TIMESTAMP, false),
(11, 9, 15, 'O rei Salomão impôs trabalhos forçados para que se construísse o templo do Senhor, seu próprio palácio, o Milo, o muro de Jerusalém, como também Hazor, Megido e Gezer.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 16, 'O faraó, rei do Egito, havia atacado e conquistado Gezer. Incendiou a cidade e matou os seus habitantes, que eram cananeus, e a deu como presente de casamento à sua filha, mulher de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 17, 'E Salomão reconstruiu Gezer. Ele construiu Bete-Horom Baixa,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 18, 'Baalate, e Tadmor, no deserto dessa região,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 19, 'bem como todas as cidades-armazéns e as cidades onde ficavam os seus carros de guerra e os seus cavalos. Construiu tudo o que desejou em Jerusalém, no Líbano e em todo o território que governou.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 20, 'Todos os não israelitas, descendentes dos amorreus, dos hititas, dos ferezeus, dos heveus e dos jebuseus,', 3, CURRENT_TIMESTAMP, false),
(11, 9, 21, 'que não tinham sido mortos pelos israelitas, Salomão recrutou para o trabalho forçado, como continuam até hoje.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 22, 'Mas Salomão não obrigou nenhum israelita a trabalhos forçados; eles eram seus homens de guerra, os seus capitães, e os comandantes dos seus carros de guerra e os condutores de carros.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 23, 'Também eram israelitas os principais funcionários encarregados das construções de Salomão: quinhentos e cinqüenta funcionários que supervisionavam os trabalhadores.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 24, 'Somente depois que a filha do faraó mudou-se da cidade de Davi para o palácio que Salomão havia construído para ela, foi que ele construiu o Milo.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 25, 'Três vezes por ano Salomão oferecia holocaustos e sacrifícios de comunhão no altar que havia construído para o Senhor, e ao mesmo tempo queimava incenso diante do Senhor. Assim, ele concluiu o templo.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 26, 'O rei Salomão também construiu navios em Eziom-Geber, que fica perto de Elate, na terra de Edom, às margens do mar Vermelho.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 27, 'E Hirão enviou em navios os seus marinheiros, homens experimentados que conheciam o mar, para trabalharem com os marinheiros de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 9, 28, 'Navegaram até Ofir, e de lá trouxeram catorze toneladas e setecentos quilos de ouro para o rei Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 1, 'A rainha de Sabá soube da fama que Salomão tinha alcançado, graças ao nome do Senhor, e foi a Jerusalém para pô-lo à prova com perguntas difíceis.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 2, 'Quando chegou, acompanhada de uma enorme caravana, com camelos carregados de especiarias, grande quantidade de ouro e pedras preciosas, foi até Salomão e lhe fez todas as perguntas que tinha em mente.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 3, 'Salomão respondeu a todas; nenhuma lhe foi tão difícil que não pudesse responder.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 4, 'Vendo toda a sabedoria de Salomão, bem como o palácio que ele havia construído,', 3, CURRENT_TIMESTAMP, false),
(11, 10, 5, 'o que era servido em sua mesa, o lugar de seus oficiais, os criados e copeiros, todos uniformizados, e os holocaustos que ele fazia no templo do Senhor, ela ficou impressionada.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 6, 'Disse ela então ao rei: "Tudo o que ouvi em meu país acerca de tuas realizações e de tua sabedoria era verdade.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 7, 'Mas eu não acreditava no que diziam, até ver com os meus próprios olhos. Na realidade, não me contaram nem a metade; tu ultrapassas em muito o que ouvi, tanto em sabedoria como em riqueza.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 8, 'Como devem ser felizes os homens da tua corte, que continuamente estão diante de ti e ouvem a tua sabedoria!', 3, CURRENT_TIMESTAMP, false),
(11, 10, 9, 'Bendito seja o Senhor, o teu Deus, que se agradou de ti e te colocou no trono de Israel. Por causa do amor eterno do Senhor para com Israel, ele te fez rei, para manter a justiça e a retidão".', 3, CURRENT_TIMESTAMP, false),
(11, 10, 10, 'E ela deu ao rei quatro toneladas e duzentos quilos de ouro e grande quantidade de especiarias e pedras preciosas. E nunca mais foram trazidas tantas especiarias quanto as que a rainha de Sabá deu ao rei Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 11, '( Os navios de Hirão, que carregavam ouro de Ofir, também trouxeram de lá grande quantidade de madeira de junípero e pedras preciosas.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 12, 'O rei utilizou a madeira para fazer a escadaria do templo do Senhor e a do palácio real, além de harpas e liras para os músicos. Nunca mais foi importada nem se viu tanta madeira de junípero. )', 3, CURRENT_TIMESTAMP, false),
(11, 10, 13, 'O rei Salomão deu à rainha de Sabá tudo o que ela desejou e pediu, além do que já lhe tinha dado por sua generosidade real. Então ela e os seus servos voltaram para o seu país.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 14, 'O peso do ouro que Salomão recebia anualmente era de vinte e três toneladas e trezentos quilos,', 3, CURRENT_TIMESTAMP, false),
(11, 10, 15, 'fora os impostos pagos por mercadores e comerciantes e por todos os reis da Arábia e pelos governadores do país.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 16, 'O rei Salomão fez duzentos escudos grandes de ouro batido, utilizando três quilos e seiscentos gramas de ouro em cada um.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 17, 'Também fez trezentos escudos pequenos de ouro batido, com um quilo e oitocentos gramas de ouro em cada um. O rei os colocou no Palácio da Floresta do Líbano.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 18, 'O rei mandou fazer ainda um grande trono de marfim revestido de ouro puro.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 19, 'O trono tinha seis degraus, e o seu encosto tinha a parte alta arredondada. Nos dois lados do assento havia braços, com um leão junto a cada braço.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 20, 'Doze leões ficavam nos seis degraus, um de cada lado. Nada igual havia sido feito em nenhum outro reino.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 21, 'Todas as taças do rei Salomão eram de ouro, bem como todos os utensílios do Palácio da Floresta do Líbano. Não havia nada de prata, pois a prata quase não tinha valor nos dias de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 22, 'O rei tinha no mar uma frota de navios mercantes junto com os navios de Hirão. Cada três anos a frota voltava, trazendo ouro, prata, marfim, macacos e pavões.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 23, 'O rei Salomão era o mais rico e o mais sábio de todos os reis da terra.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 24, 'Gente de todo o mundo pedia audiência a Salomão para ouvir a sabedoria que Deus lhe tinha dado.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 25, 'Ano após ano, todos os que vinham traziam algum presente: utensílios de prata e de ouro, mantos, armas e especiarias, cavalos e mulas.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 26, 'Salomão juntou carros e cavalos; possuía mil e quatrocentos carros e doze mil cavalos, dos quais mantinha uma parte nas guarnições de algumas cidades e a outra perto dele, em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 27, 'O rei tornou a prata tão comum em Jerusalém quanto as pedras, e o cedro tão numeroso quanto as figueiras bravas da Sefelá.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 28, 'Os cavalos de Salomão eram importados do Egito e da Cilícia, onde os fornecedores do rei os compravam.', 3, CURRENT_TIMESTAMP, false),
(11, 10, 29, 'Importavam do Egito um carro por sete quilos e duzentos gramas de prata, e um cavalo por um quilo e oitocentos gramas, e os exportavam para todos os reis dos hititas e dos arameus.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 1, 'O rei Salomão amou muitas mulheres estrangeiras, além da filha do faraó. Eram mulheres moabitas, amonitas, edomitas, sidônias e hititas.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 2, 'Elas eram das nações sobre as quais o Senhor tinha dito aos israelitas: "Vocês não poderão tomar mulheres dentre essas nações, porque elas os farão desviar-se para seguir os seus deuses". No entanto, Salomão apegou-se amorosamente a elas.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 3, 'Casou com setecentas princesas e trezentas concubinas, e as suas mulheres o levaram a desviar-se.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 4, 'À medida que Salomão foi envelhecendo, suas mulheres o induziram a voltar-se para outros deuses, e o seu coração já não era totalmente dedicado ao Senhor, o seu Deus, como fora o coração do seu pai Davi.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 5, 'Ele seguiu os postes sagrados, a deusa dos sidônios, e Moloque, o repugnante deus dos amonitas.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 6, 'Dessa forma Salomão fez o que o Senhor reprova; não seguiu completamente o Senhor, como o seu pai Davi.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 7, 'No monte que fica a leste de Jerusalém, Salomão construiu um altar para Camos, o repugnante deus de Moabe, e para Moloque, o repugnante deus dos amonitas.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 8, 'Também fez altares para os deuses de todas as suas outras mulheres estrangeiras, que queimavam incenso e ofereciam sacrifícios a eles.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 9, 'O Senhor irou-se contra Salomão por ter-se desviado do Senhor, o Deus de Israel, que lhe havia aparecido duas vezes.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 10, 'Embora ele tivesse proibido Salomão de seguir outros deuses, Salomão não obedeceu à ordem do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 11, 'Então o Senhor disse a Salomão: "Já que essa é a sua atitude e você não obedeceu à minha aliança e aos meus decretos, os quais lhe ordenei, certamente lhe tirarei o reino e o darei a um dos seus servos.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 12, 'No entanto, por amor a Davi, seu pai, não farei isso enquanto você viver. Eu o tirarei da mão do seu filho.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 13, 'Mas, não tirarei dele o reino inteiro, eu lhe darei uma tribo por amor de Davi, meu servo, e por amor de Jerusalém, a cidade que escolhi".', 3, CURRENT_TIMESTAMP, false),
(11, 11, 14, 'Então o Senhor levantou contra Salomão um adversário, o edomita Hadade, da linhagem real de Edom.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 15, 'Anteriormente, quando Davi estava lutando contra Edom, Joabe, o comandante do exército, que tinha ido para lá enterrar os mortos, exterminara todos os homens de Edom.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 16, 'Joabe e todo o exército israelita permaneceram lá seis meses, até matarem todos os edomitas.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 17, 'Mas Hadade, sendo ainda um menino, fugiu para o Egito com alguns dos oficiais edomitas que tinham servido a seu pai.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 18, 'Partiram de Midiã e foram a Parã. Lá reuniram alguns homens e foram ao Egito, até o faraó, rei do Egito, que deu uma casa e terras a Hadade e lhe forneceu alimento.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 19, 'O faraó acolheu bem a Hadade, a ponto de dar-lhe em casamento uma irmã de sua própria mulher, a rainha Tafnes.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 20, 'A irmã de Tafnes deu-lhe um filho, chamado Genubate, que fora criado por Tafnes no palácio real. Ali Genubate viveu com os próprios filhos do faraó.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 21, 'Enquanto estava no Egito, Hadade soube que Davi tinha descansado com seus antepassados e que Joabe, o comandante do exército, também estava morto. Então Hadade disse ao faraó: "Deixa-me voltar para a minha terra".', 3, CURRENT_TIMESTAMP, false),
(11, 11, 22, '"O que lhe falta aqui para que você queira voltar para a sua terra? ", perguntou o faraó. "Nada me falta", respondeu Hadade, "mas deixa-me ir! "', 3, CURRENT_TIMESTAMP, false),
(11, 11, 23, 'E Deus fez um outro adversário levantar-se contra Salomão: Rezom, filho de Eliada, que tinha fugido do seu senhor, Hadadezer, rei de Zobá.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 24, 'Quando Davi destruiu o exército de Zobá, Rezom reuniu alguns homens e tornou-se líder de um bando de rebeldes. Eles foram para Damasco, onde se instalaram e assumiram o controle.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 25, 'Rezom foi adversário de Israel enquanto Salomão viveu, e trouxe-lhe muitos problemas, além dos causados por Hadade. Assim Rezom governou a Síria e foi hostil para com Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 26, 'Também Jeroboão, filho de Nebate, rebelou-se contra o rei. Ele era um dos oficiais de Salomão, um efraimita de Zeredá, e a sua mãe era uma viúva chamada Zerua.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 27, 'E foi assim que ele se revoltou contra o rei: Salomão tinha construído o Milo e havia tapado a abertura no muro da cidade de Davi, seu pai.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 28, 'Ora, Jeroboão era homem capaz, e, quando Salomão viu como ele fazia bem o seu trabalho, encarregou-o de todos os que faziam trabalho forçado, pertencentes às tribos de José.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 29, 'Naquela ocasião, Jeroboão saiu de Jerusalém, e Aías, o profeta de Siló, que estava usando uma capa nova, encontrou-se com ele no caminho. Os dois estavam sozinhos no campo,', 3, CURRENT_TIMESTAMP, false),
(11, 11, 30, 'e Aías segurou firmemente a capa que estava usando e a rasgou em doze pedaços.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 31, 'Então disse a Jeroboão: "Apanhe dez pedaços para você, pois assim diz o Senhor, o Deus de Israel: ‘Saiba que vou tirar o reino das mãos de Salomão e dar a você dez tribos.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 32, 'Mas, por amor ao meu servo Davi e à cidade de Jerusalém, a qual escolhi dentre todas as tribos de Israel, ele terá uma tribo.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 33, 'Farei isso porque eles me abandonaram e adoraram os postes sagrados, deusa dos sidônios, Camos, deus dos moabitas, e Moloque, deus dos amonitas, e não andaram nos meus caminhos, nem fizeram o que eu aprovo, nem obedeceram aos meus decretos e as minhas ordenanças, como fez Davi, pai de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 34, '" ‘Mas não tirarei o reino todo das mãos de Salomão; eu o fiz governante todos os dias de sua vida por amor ao meu servo Davi, a quem escolhi e que obedeceu aos meus mandamentos e aos meus decretos.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 35, 'Tirarei o reino das mãos do seu filho e darei dez tribos a você.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 36, 'Darei uma tribo ao seu filho a fim de que o meu servo Davi sempre tenha diante de mim um descendente no trono em Jerusalém, a cidade onde eu quis pôr o meu nome.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 37, 'Quanto a você, eu o farei governar tudo o que o seu coração desejar; você será rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 38, 'Se você fizer tudo o que eu lhe ordenar e andar nos meus caminhos e fizer o que eu aprovo, obedecendo aos meus decretos e aos meus mandamentos, como fez o meu servo Davi, estarei com você. Edificarei para você uma dinastia tão permanente quanto a que edifiquei para Davi, e darei Israel a você.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 39, 'Humilharei os descendentes de Davi por causa disso, mas não para sempre’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 11, 40, 'Salomão tentou matar Jeroboão, mas ele fugiu para o Egito, para o rei Sisaque, e lá permaneceu até a morte de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 41, 'Os demais acontecimentos do reinado de Salomão, tudo o que fez e a sabedoria que teve, estão todos escritos nos registros históricos de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 42, 'Salomão reinou quarenta anos em Jerusalém sobre todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 11, 43, 'Então descansou com os seus antepassados e foi sepultado na cidade de Davi, seu pai. E o seu filho Roboão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 1, 'Roboão foi a Siquém, onde todos os israelitas tinham se reunido para proclamá-lo rei.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 2, 'Assim que Jeroboão, filho de Nebate, que estava no Egito fugindo do rei Salomão, soube disso, voltou de lá.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 3, 'E mandaram chamá-lo. Então ele e toda a assembléia de Israel foram ao encontro de Roboão e disseram:', 3, CURRENT_TIMESTAMP, false),
(11, 12, 4, '"Teu pai colocou sobre nós um jugo pesado, mas agora diminui o trabalho árduo e este jugo pesado, e nós te serviremos".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 5, 'Roboão respondeu: "Voltem a mim daqui a três dias". Então o povo foi embora.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 6, 'O rei Roboão perguntou às autoridades que haviam servido ao seu pai Salomão durante a vida dele: "Como vocês me aconselham a responder a este povo? "', 3, CURRENT_TIMESTAMP, false),
(11, 12, 7, 'Eles responderam: "Se hoje fores um servo desse povo e servi-lo, dando-lhe uma resposta favorável, eles sempre serão teus servos".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 8, 'Roboão, contudo, rejeitou o conselho que as autoridades de Israel lhe tinham dito e consultou os jovens que haviam crescido com ele e o estavam servindo.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 9, 'Perguntou-lhes: "Qual é o conselho de vocês? Como devemos responder a este povo que me diz: ‘Diminui o jugo que teu pai colocou sobre nós’? "', 3, CURRENT_TIMESTAMP, false),
(11, 12, 10, 'Os jovens que haviam crescido com ele responderam: "A este povo que te disse: ‘Teu pai colocou sobre nós um jugo pesado; torna-o mais leve’ — dize: ‘Meu dedo mínimo é mais grosso do que a cintura do meu pai.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 11, 'Pois bem, meu pai lhes impôs um jugo pesado; eu o tornarei ainda mais pesado. Meu pai os castigou com simples chicotes; eu os castigarei com chicotes pontiagudos’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 12, 'Três dias depois, Jeroboão e todo o povo voltaram a Roboão, segundo a orientação dada pelo rei: "Voltem a mim daqui a três dias".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 13, 'Mas o rei lhes respondeu asperamente. Rejeitando o conselho das autoridades de Israel,', 3, CURRENT_TIMESTAMP, false),
(11, 12, 14, 'seguiu o conselho dos jovens e disse: "Meu pai lhes tornou pesado o jugo; eu o tornarei ainda mais pesado. Meu pai os castigou com simples chicotes; eu os castigarei com chicotes pontiagudos".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 15, 'E o rei não ouviu o povo, pois esta mudança nos acontecimentos vinha da parte do Senhor, para que se cumprisse a palavra que o Senhor havia falado a Jeroboão, filho de Nebate, por meio do silonita Aías.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 16, 'Quando todo o Israel viu que o rei se recusava a ouvi-los, responderam ao rei: "Que temos em comum com Davi? Que temos em comum com o filho de Jessé? Para as suas tendas, ó Israel! Cuide da sua própria casa, ó Davi! " E assim os israelitas foram para as suas casas.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 17, 'Quanto, porém, aos israelitas que moravam nas cidades de Judá, Roboão continuou como rei deles.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 18, 'O rei Roboão enviou Adonirão, chefe de trabalhos forçados, mas todo o Israel o apedrejou até à morte. O rei, contudo, conseguiu subir em sua carruagem e fugir para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 19, 'Desta forma Israel se rebelou contra a dinastia de Davi, e assim permanece até hoje.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 20, 'Quando todos os israelitas souberam que Jeroboão tinha voltado, mandaram chamá-lo para a reunião da comunidade e o fizeram rei sobre todo o Israel. Somente a tribo de Judá permaneceu leal à dinastia de Davi.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 21, 'Quando Roboão chegou em Jerusalém, convocou cento e oitenta mil homens de combate, das tribos de Judá e de Benjamim, para guerrearem contra Israel e recuperarem o reino para Roboão, filho de Salomão.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 22, 'Entretanto, veio esta palavra de Deus a Semaías, homem de Deus:', 3, CURRENT_TIMESTAMP, false),
(11, 12, 23, '"Diga a Roboão, filho de Salomão, rei de Judá, às tribos de Judá e Benjamim, e ao restante do povo:', 3, CURRENT_TIMESTAMP, false),
(11, 12, 24, '‘Assim diz o Senhor: Não saiam à guerra contra os seus irmãos israelitas. Voltem para casa, todos vocês, pois fui eu que fiz isso’ ". E eles obedeceram à palavra do Senhor e voltaram para as suas casas, conforme o Senhor tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 25, 'Jeroboão fortificou Siquém, nos montes de Efraim, onde passou a morar. Depois ele saiu e fortificou Peniel.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 26, 'Jeroboão pensou: "O reino agora provavelmente voltará para a dinastia de Davi.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 27, 'Se esse povo subir a Jerusalém para oferecer sacrifícios no templo do Senhor, novamente dedicarão sua lealdade ao senhor deles, Roboão, rei de Judá. Eles vão me matar e voltar para o rei Roboão".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 28, 'Depois de aconselhar-se, o rei fez dois bezerros de ouro e disse ao povo: "Vocês já subiram muito a Jerusalém. Aqui estão os seus deuses, ó Israel, que tiraram vocês do Egito".', 3, CURRENT_TIMESTAMP, false),
(11, 12, 29, 'Mandou por um bezerro em Betel, e o outro em Dã.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 30, 'E isso veio a ser um pecado, pois o povo ia até Dã para adorar aquele bezerro.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 31, 'Jeroboão construiu altares idólatras e designou sacerdotes dentre o povo, apesar de não serem levitas.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 32, 'Instituiu uma festa no dia quinze do oitavo mês, semelhante à festa realizada em Judá, e ofereceu sacrifícios no altar. Ele fez isso em Betel, onde também sacrificou aos bezerros que havia feito. Também estabeleceu lá sacerdotes nos seus altares idólatras.', 3, CURRENT_TIMESTAMP, false),
(11, 12, 33, 'No dia quinze do oitavo mês, data que ele mesmo escolheu, ofereceu sacrifícios no altar que havia construído em Betel. Assim ele instituiu a festa para os israelitas e foi ao altar para queimar incenso.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 1, 'Por ordem do Senhor um homem de Deus foi de Judá a Betel, quando Jeroboão estava de pé junto ao altar para queimar incenso.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 2, 'Ele clamou contra o altar, segundo a ordem do Senhor: "Ó altar, ó altar! Assim diz o Senhor: ‘Um filho nascerá na família de Davi e se chamará Josias. Sobre você ele sacrificará os sacerdotes dos altares idólatras que agora queimam incenso aqui, e ossos humanos serão queimados sobre você’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 3, 'Naquele mesmo dia o homem de Deus deu um sinal: "Este é o sinal que o Senhor declarou: O altar se fenderá, e as cinzas que estão sobre ele se derramarão".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 4, 'Quando o rei Jeroboão ouviu o que o homem de Deus proclamava contra o altar de Betel, apontou para ele e ordenou: "Prendam-no! " Mas o braço que ele tinha estendido ficou paralisado, e não voltava ao normal.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 5, 'Além disso, o altar se fendeu, e as suas cinzas se derramaram, conforme o sinal dado pelo homem de Deus por ordem do Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 6, 'Então o rei disse ao homem de Deus: "Interceda junto ao Senhor, o seu Deus, e ore por mim para que meu braço se recupere". O homem de Deus intercedeu junto ao Senhor, e o braço do rei recuperou-se e voltou ao normal.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 7, 'O rei disse ao homem de Deus: "Venha à minha casa e coma algo, e eu o recompensarei".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 8, 'Mas o homem de Deus respondeu ao rei: "Mesmo que me desse a metade dos seus bens, eu não iria com você, nem comeria nem beberia nada neste lugar.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 9, 'Pois recebi estas ordens pela palavra do Senhor: ‘Não coma pão nem beba água nem volte pelo mesmo caminho por onde veio’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 10, 'Por isso, quando ele voltou, não foi pelo caminho pelo qual tinha vindo a Betel.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 11, 'Ora, havia um certo profeta, já idoso, morando em Betel. Seus filhos lhe contaram tudo o que o homem de Deus havia feito naquele dia e também o que ele dissera ao rei.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 12, 'O pai lhes perguntou: "Por qual caminho ele foi? " E os seus filhos lhe mostraram por onde tinha ido o homem de Deus que viera de Judá.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 13, 'Então disse aos filhos: "Selem o jumento para mim". E, depois de selarem o jumento, ele montou', 3, CURRENT_TIMESTAMP, false),
(11, 13, 14, 'e cavalgou à procura do homem de Deus, até que o encontrou sentado embaixo da Grande Árvore. E lhe perguntou: "Você é o homem de Deus que veio de Judá? " "Sou", respondeu.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 15, 'Então o profeta lhe disse: "Venha à minha casa, comer alguma coisa".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 16, 'O homem de Deus disse: "Não posso ir com você, nem posso comer pão ou beber água neste lugar.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 17, 'A palavra do Senhor deu-me esta ordem: ‘Não coma pão nem beba água lá, nem volte pelo mesmo caminho por onde você foi’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 18, 'O profeta idoso respondeu: "Eu também sou profeta como você. E um anjo me disse por ordem do Senhor: ‘Faça-o voltar com você para a sua casa para que coma pão e beba água’ ". Mas ele estava mentindo.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 19, 'E o homem de Deus voltou com ele e foi comer e beber em sua casa.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 20, 'Enquanto ainda estavam sentados à mesa, a palavra do Senhor veio ao profeta idoso que o havia feito voltar.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 21, 'Ele bradou ao homem de Deus que tinha vindo de Judá: "Assim diz o Senhor: ‘Você desafiou a palavra do Senhor e não obedeceu à ordem que o Senhor, o seu Deus, lhe deu.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 22, 'Você voltou e comeu pão e bebeu água no lugar onde ele lhe falou que não comesse nem bebesse. Por isso o seu corpo não será sepultado no túmulo dos seus antepassados’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 23, 'Quando o homem de Deus acabou de comer e beber, o outro profeta selou seu jumento para ele.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 24, 'No caminho, um leão o atacou e o matou, e o seu corpo ficou estendido no chão, ao lado do leão e do jumento.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 25, 'Algumas pessoas que passaram viram o cadáver estendido ali, com o leão ao lado, e foram dar a notícia na cidade onde o profeta idoso vivia.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 26, 'Quando o outro profeta soube disso, exclamou: "É o homem de Deus que desafiou a palavra do Senhor! O Senhor o entregou ao leão, que o feriu e o matou, conforme a palavra do Senhor o tinha advertido".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 27, 'O profeta disse aos seus filhos: "Selem o jumento para mim", e eles o fizeram.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 28, 'Ele foi e encontrou o cadáver caído no caminho, com o jumento e o leão ao seu lado. O leão não tinha comido o corpo nem ferido o jumento.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 29, 'O profeta apanhou o corpo do homem de Deus, colocou-o sobre o jumento, e o levou de volta para Betel, a fim de chorar por ele e sepultá-lo.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 30, 'Ele o pôs no seu próprio túmulo, e lamentaram por ele, exclamando: "Ah, meu irmão! "', 3, CURRENT_TIMESTAMP, false),
(11, 13, 31, 'Depois de sepultá-lo, disse aos seus filhos: "Quando eu morrer, enterrem-me no túmulo onde está sepultado o homem de Deus; ponham os meus ossos ao lado dos ossos dele.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 32, 'Pois a mensagem que declarou por ordem do Senhor contra o altar de Betel e contra todos os altares idólatras das cidades de Samaria certamente se cumprirá".', 3, CURRENT_TIMESTAMP, false),
(11, 13, 33, 'Mesmo depois disso Jeroboão não mudou o seu mau procedimento, mas continuou a nomear dentre o povo sacerdotes para os altares idólatras. Ele consagrava para esses altares todo aquele que quisesse tornar-se sacerdote.', 3, CURRENT_TIMESTAMP, false),
(11, 13, 34, 'Esse foi o pecado da família de Jeroboão, que levou à sua queda e à sua eliminação da face da terra.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 1, 'Naquela época, Abias, filho de Jeroboão, ficou doente,', 3, CURRENT_TIMESTAMP, false),
(11, 14, 2, 'e este disse à sua mulher: "Use um disfarce para não ser reconhecida como a mulher de Jeroboão, e vá a Siló, onde vive o profeta Aías, aquele que me disse que eu seria rei sobre este povo.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 3, 'Leve para ele dez pães, alguns bolos e uma garrafa de mel. Ele lhe dirá o que vai acontecer com o menino".', 3, CURRENT_TIMESTAMP, false),
(11, 14, 4, 'A mulher de Jeroboão atendeu o seu pedido e foi à casa de Aías, em Siló. Ora, Aías já não conseguia enxergar; tinha ficado cego por causa da idade.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 5, 'Mas o Senhor lhe tinha dito: "A mulher de Jeroboão está vindo para lhe perguntar acerca do filho dela, pois ele está doente, e você deve responder-lhe assim e assim. Quando ela chegar, vai fingir que é outra pessoa".', 3, CURRENT_TIMESTAMP, false),
(11, 14, 6, 'Quando Aías ouviu o som dos passos junto da porta, disse: "Entre, mulher de Jeroboão. Por que esse fingimento? Fui encarregado de lhe dar más notícias.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 7, 'Vá dizer a Jeroboão que é isto o que o Senhor, o Deus de Israel, diz: ‘Tirei-o dentre o povo e o tornei líder sobre o meu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 8, 'Tirei o reino da família de Davi e o dei a você, mas você não tem sido como o meu servo Davi, que obedecia aos meus mandamentos e me seguia de todo o coração, fazendo apenas o que eu aprovo.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 9, 'Você tem feito mais mal do que todos os que viveram antes de você, pois fez para si outros deuses, ídolos de metal; você provocou a minha ira e voltou as costas para mim.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 10, '" ‘Por isso, trarei desgraça à família de Jeroboão. Matarei de Jeroboão até o último indivíduo do sexo masculino em Israel, seja escravo ou livre. Queimarei a família de Jeroboão até o fim como quem queima esterco.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 11, 'Dos que pertencem a Jeroboão, os cães comerão os que morrerem na cidade, e as aves do céu se alimentarão dos que morrerem no campo. O Senhor falou! ’', 3, CURRENT_TIMESTAMP, false),
(11, 14, 12, '"Quanto a você, volte para casa. Quando você puser os pés na cidade, o menino morrerá.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 13, 'Todo o Israel chorará por ele e o sepultará. Ele é o único da família de Jeroboão que será sepultado, pois é o único da família de Jeroboão em quem o Senhor, o Deus de Israel, encontrou alguma coisa boa.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 14, '"O Senhor levantará para si um rei sobre Israel que eliminará a família de Jeroboão. Este é o dia! Como? Sim, agora mesmo.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 15, 'E o Senhor ferirá Israel, de maneira que ficará como um junco balançando na água. Ele desarraigará Israel desta boa terra que deu aos seus antepassados e os espalhará para além do Rio, pois provocaram a ira do Senhor com os postes sagrados que fizeram.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 16, 'E ele abandonará Israel por causa dos pecados que Jeroboão cometeu e tem feito Israel cometer".', 3, CURRENT_TIMESTAMP, false),
(11, 14, 17, 'Então a mulher de Jeroboão levantou-se e voltou para Tirza. Assim que entrou em casa, o menino morreu.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 18, 'Eles o sepultaram, e todo o Israel chorou por ele, conforme o Senhor predissera por meio do seu servo, o profeta Aías.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 19, 'Os demais acontecimentos do reinado de Jeroboão, suas guerras e como governou, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 20, 'Ele reinou durante vinte e dois anos, e então descansou com os seus antepassados. E o seu filho Nadabe foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 21, 'Roboão, filho de Salomão, foi rei de Judá. Tinha quarenta e um anos de idade quando começou a reinar, e reinou dezessete anos em Jerusalém, cidade que o Senhor havia escolhido dentre todas as tribos de Israel para nela pôr o seu nome. Sua mãe, uma amonita, chamava-se Naamá.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 22, 'Judá fez o que o Senhor reprova. Pelos pecados que cometeram, eles despertaram a sua ira zelosa mais do que os seus antepassados o tinham feito.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 23, 'Também construíram para si altares idólatras, colunas sagradas e postes sagrados sobre todos os montes e debaixo de todas as árvores frondosas.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 24, 'Havia no país até prostitutos cultuais; o povo se envolvia em todas as práticas detestáveis das nações que o Senhor havia expulsado de diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 25, 'No quinto ano do reinado de Roboão, Sisaque, rei do Egito, atacou Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 26, 'Levou embora todos os tesouros do templo do Senhor e do palácio real, inclusive os escudos de ouro que Salomão havia feito.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 27, 'Por isso o rei Roboão mandou fazer escudos de bronze para substituí-los, e os entregou aos chefes da guarda da entrada do palácio real.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 28, 'Sempre que o rei ia ao templo do Senhor, os guardas empunhavam os escudos, e, em seguida, os devolviam à sala da guarda.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 29, 'Os demais acontecimentos do reinado de Roboão, e tudo o que fez, estão escritos nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 30, 'Houve guerra constante entre Roboão e Jeroboão.', 3, CURRENT_TIMESTAMP, false),
(11, 14, 31, 'Roboão descansou com os seus antepassados e foi sepultado com eles na cidade de Davi. Sua mãe, uma amonita, chamava-se Naamá. E o seu filho Abias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 1, 'No décimo oitavo ano do reinado de Jeroboão, filho de Nebate, Abias tornou-se rei de Judá,', 3, CURRENT_TIMESTAMP, false),
(11, 15, 2, 'e reinou três anos em Jerusalém. O nome de sua mãe era Maaca, filha de Absalão.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 3, 'Ele cometeu todos os pecados que o seu pai tinha cometido; seu coração não era inteiramente consagrado ao Senhor, ao seu Deus, quanto fora o coração de Davi, seu antepassado.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 4, 'No entanto, por amor de Davi, o Senhor, o seu Deus, concedeu-lhe uma lâmpada em Jerusalém dando-lhe um filho como sucessor e fortalecendo Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 5, 'Pois Davi fizera o que o Senhor aprova e não deixara de obedecer a nenhum dos mandamentos do Senhor durante todos os dias da sua vida, exceto no caso de Urias, o hitita.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 6, 'E houve guerra entre Roboão e Jeroboão durante toda a vida de Abias.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 7, 'Os demais acontecimentos do reinado de Abias e todas as suas realizações estão escritos nos registros históricos dos reis de Judá. Também houve guerra entre Abias e Jeroboão.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 8, 'E Abias descansou com os seus antepassados e foi sepultado na cidade de Davi. E o seu filho Asa foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 9, 'No vigésimo ano do reinado de Jeroboão, rei de Israel, Asa tornou-se rei de Judá,', 3, CURRENT_TIMESTAMP, false),
(11, 15, 10, 'e reinou quarenta e um anos em Jerusalém. O nome da sua avó era Maaca, filha de Absalão.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 11, 'Asa fez o que o Senhor aprova, tal como Davi, seu predecessor.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 12, 'Expulsou do país os prostitutos cultuais e se desfez de todos os ídolos que seu pai havia feito.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 13, 'Chegou até a depor sua avó Maaca da posição de rainha-mãe, pois ela havia feito um poste sagrado repugnante. Asa derrubou o poste e o queimou no vale do Cedrom.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 14, 'Embora os altares idólatras não tenham sido eliminados, o coração de Asa foi totalmente dedicado ao Senhor durante toda a sua vida.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 15, 'Ele trouxe para o templo do Senhor a prata, o ouro e os utensílios que ele e seu pai haviam consagrado.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 16, 'Houve guerra entre Asa e Baasa, rei de Israel, durante todo o reinado deles.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 17, 'Baasa, rei de Israel, invadiu Judá e fortificou Ramá, para que ninguém pudesse entrar nem sair do território de Asa, rei de Judá.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 18, 'Então Asa ajuntou a prata e o ouro que haviam sobrado no tesouro do templo do Senhor e do seu próprio palácio. Confiou tudo isso a alguns dos seus oficiais e os enviou a Ben-Hadade, filho de Tabriom e neto de Heziom, rei da Síria, que governava em Damasco,', 3, CURRENT_TIMESTAMP, false),
(11, 15, 19, 'com uma mensagem que dizia: "Façamos um tratado, como fizeram meu pai e o teu. Estou te enviando como presente prata e ouro. Agora, rompe o tratado que tens com Baasa, rei de Israel, para que ele saia do meu país".', 3, CURRENT_TIMESTAMP, false),
(11, 15, 20, 'Ben-Hadade aceitou a proposta do rei Asa e ordenou aos comandantes das suas forças que atacassem as cidades de Israel. Ele conquistou Ijom, Dã, Abel-Bete-Maaca e todo o Quinerete, além de Naftali.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 21, 'Quando Baasa soube disso, abandonou a construção dos muros de Ramá e foi para Tirza.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 22, 'Então o rei Asa reuniu todos homens de Judá — ninguém foi isentado — e eles retiraram de Ramá as pedras e a madeira que Baasa estivera usando. Com esse material Asa fortificou Geba, em Benjamim, e também Mispá.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 23, 'Os demais acontecimentos do reinado de Asa, todas as suas realizações, tudo o que fez e todas as cidades que construiu, tudo isso está escrito nos registros históricos dos reis de Judá. Na velhice Asa sofreu uma doença nos pés,', 3, CURRENT_TIMESTAMP, false),
(11, 15, 24, 'e quando descansou com os seus antepassados, foi sepultado com eles na cidade de Davi, seu pai. E seu filho Josafá foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 25, 'Nadabe, filho de Jeroboão, tornou-se rei de Israel no segundo ano do reinado de Asa, rei de Judá, e reinou dois anos sobre Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 26, 'Fez o que o Senhor reprova, andando nos caminhos do seu pai e no pecado que ele tinha levado Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 27, 'Baasa, filho de Aías, da tribo de Issacar, conspirou contra ele, e o matou na cidade filistéia de Gibetom, enquanto Nadabe e todo o exército de Israel a sitiavam.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 28, 'Baasa matou Nadabe no terceiro ano do reinado de Asa, rei de Judá, e foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 29, 'Assim que começou a reinar, matou toda a família de Jeroboão. Dos pertencentes a Jeroboão não deixou ninguém vivo, mas destruiu a todos, de acordo com a palavra do Senhor anunciada por seu servo, o silonita Aías.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 30, 'Isso aconteceu por causa dos pecados que Jeroboão havia cometido e havia feito Israel cometer, e porque ele tinha provocado a ira do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 31, 'Os demais acontecimentos do reinado de Nadabe e tudo o que fez, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 32, 'Houve guerra entre Asa e Baasa, rei de Israel, durante todo o reinado deles.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 33, 'No terceiro ano do reinado de Asa, rei de Judá, Baasa, filho de Aías, tornou-se rei de todo o Israel, em Tirza, e reinou vinte e quatro anos.', 3, CURRENT_TIMESTAMP, false),
(11, 15, 34, 'Fez o que o Senhor reprova, andando nos caminhos de Jeroboão e nos pecados que ele tinha levado Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 1, 'Então a palavra do Senhor contra Baasa veio a Jeú, filho de Hanani:', 3, CURRENT_TIMESTAMP, false),
(11, 16, 2, '"Eu o levantei do pó e o tornei líder de Israel, meu povo, mas você andou nos caminhos de Jeroboão e fez o meu povo pecar e provocar a minha ira por causa dos pecados deles.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 3, 'Por isso estou na iminência de destruir Baasa e a sua família, fazendo a ela o que fiz à de Jeroboão, filho de Nebate.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 4, 'Cães comerão os da família de Baasa que morrerem na cidade, e as aves do céu se alimentarão dos que morrerem no campo".', 3, CURRENT_TIMESTAMP, false),
(11, 16, 5, 'Os demais acontecimentos do reinado de Baasa, o que fez e as suas realizações, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 6, 'Baasa descansou com os seus antepassados e foi sepultado em Tirza. E seu filho Elá foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 7, 'A palavra do Senhor veio por meio do profeta Jeú, filho de Hanani, a Baasa e sua família, por terem feito o que o Senhor reprova, provocando a sua ira, tornando-se como a família de Jeroboão — e também porque Baasa destruiu a família de Jeroboão.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 8, 'No vigésimo sexto ano do reinado de Asa, rei de Judá, Elá, filho de Baasa, tornou-se rei de Israel, e reinou dois anos em Tirza.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 9, 'Zinri, um dos seus oficiais, que comandava metade dos seus carros de guerra, conspirou contra ele. Elá estava em Tirza naquela ocasião, embriagando-se na casa de Arsa, o encarregado do palácio de Tirza.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 10, 'Zinri entrou e o feriu e o matou, no vigésimo sétimo ano do reinado de Asa, rei de Judá. E foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 11, 'Assim que começou a reinar, logo que se assentou no trono, eliminou toda a família de Baasa. Não poupou uma só pessoa do sexo masculino, fosse parente ou amigo.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 12, 'Assim Zinri destruiu toda a família de Baasa, de acordo com a palavra do Senhor falada contra Baasa pelo profeta Jeú,', 3, CURRENT_TIMESTAMP, false),
(11, 16, 13, 'por causa de todos os pecados que Baasa e seu filho Elá haviam cometido e levado Israel a cometer, pois, com os seus ídolos inúteis, provocaram a ira do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 14, 'Os demais acontecimentos do reinado de Elá e tudo o que fez estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 15, 'No vigésimo sétimo ano do reinado de Asa, rei de Judá, Zinri reinou sete dias em Tirza. O exército estava acampado perto da cidade filistéia de Gibetom.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 16, 'Quando os acampados souberam que Zinri havia conspirado contra o rei e o tinha assassinado, proclamaram ali no acampamento, naquele mesmo dia, Onri, o comandante do exército, rei sobre Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 17, 'Então Onri e todo o seu exército saíram de Gibetom e sitiaram Tirza.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 18, 'Quando Zinri viu que a cidade tinha sido tomada, entrou na cidadela do palácio real e incendiou o palácio em torno de si, e morreu.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 19, 'Tudo por causa dos pecados que ele havia cometido, fazendo o que o Senhor reprova e andando nos caminhos de Jeroboão e no pecado que ele tinha cometido e levado Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 20, 'Os demais acontecimentos do reinado de Zinri e a rebelião que liderou estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 21, 'Então o povo de Israel dividiu-se em duas facções; metade apoiava Tibni, filho de Ginate, para fazê-lo rei, e a outra metade apoiava Onri.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 22, 'Mas os seguidores de Onri revelaram-se mais fortes do que os de Tibni, filho de Ginate. E aconteceu que Tibni morreu e Onri tornou-se rei.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 23, 'No trigésimo primeiro ano do reinado de Asa, rei de Judá, Onri tornou-se rei de Israel e reinou doze anos, seis deles em Tirza.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 24, 'Por setenta quilos de prata ele comprou de Sêmer a colina de Samaria, onde construiu uma cidade, a qual chamou Samaria, por causa de Sêmer, o nome do antigo proprietário da colina.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 25, 'Onri, porém, fez o que o Senhor reprova e pecou mais do que todos que reinaram antes dele.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 26, 'Andou nos caminhos de Jeroboão, filho de Nebate, e no pecado que ele tinha levado Israel a cometer, e assim, com os seus ídolos inúteis, provocou a ira do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 27, 'Os demais acontecimentos do reinado de Onri, o que fez e as suas realizações, tudo está escrito nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 28, 'Onri descansou com os seus antepassados e foi sepultado em Samaria. E seu filho Acabe foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 29, 'No trigésimo oitavo ano do reinado de Asa, rei de Judá, Acabe, filho de Onri, tornou-se rei de Israel, e reinou vinte e dois anos sobre Israel, em Samaria.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 30, 'Acabe, filho de Onri, fez o que o Senhor reprova, mais do que qualquer outro antes dele.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 31, 'Ele não apenas achou que não tinha importância cometer os pecados de Jeroboão, filho de Nebate, mas também se casou com Jezabel, filha de Etbaal, rei dos sidônios, e passou a prestar culto a Baal e adorá-lo.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 32, 'No templo de Baal, que ele mesmo tinha construído em Samaria, Acabe ergueu um altar para Baal.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 33, 'Fez também um poste sagrado. Ele provocou a ira do Senhor, o Deus de Israel, mais do que todos os reis de Israel antes dele.', 3, CURRENT_TIMESTAMP, false),
(11, 16, 34, 'Durante o seu reinado, Hiel, de Betel, reconstruiu Jericó. Lançou os alicerces à custa do seu filho mais velho, Abirão, e instalou as suas portas à custa do seu filho mais novo, Segube, de acordo com a palavra que o Senhor tinha falado por meio de Josué, filho de Num.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 1, 'Ora, Elias, o tesbita da Tisbe de Gileade, disse a Acabe: "Juro pelo nome do Senhor, o Deus de Israel, a quem sirvo, que não cairá orvalho nem chuva nos anos seguintes, exceto mediante a minha palavra".', 3, CURRENT_TIMESTAMP, false),
(11, 17, 2, 'Depois disso a palavra do Senhor veio a Elias:', 3, CURRENT_TIMESTAMP, false),
(11, 17, 3, '"Saia daqui, vá para o leste e esconda-se perto do riacho de Querite, a leste do Jordão.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 4, 'Você beberá do riacho, e dei ordens aos corvos para o alimentarem lá".', 3, CURRENT_TIMESTAMP, false),
(11, 17, 5, 'E ele fez o que o Senhor lhe tinha dito. Foi para o riacho de Querite, a leste do Jordão, e ficou por lá.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 6, 'Os corvos lhe traziam pão e carne de manhã e de tarde, e ele bebia água do riacho.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 7, 'Algum tempo depois, o riacho secou-se por falta de chuva.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 8, 'Então a palavra do Senhor veio a Elias:', 3, CURRENT_TIMESTAMP, false),
(11, 17, 9, '"Vá imediatamente para a cidade de Sarepta de Sidom e fique por lá. Ordenei a uma viúva daquele lugar que lhe forneça comida".', 3, CURRENT_TIMESTAMP, false),
(11, 17, 10, 'E ele foi. Quando chegou à porta da cidade, encontrou uma viúva que estava colhendo gravetos. Ele a chamou e perguntou: "Pode me trazer um pouco d’água numa jarra para eu beber? "', 3, CURRENT_TIMESTAMP, false),
(11, 17, 11, 'Enquanto ela ia indo buscar água, ele gritou: "Por favor, traga também um pedaço de pão".', 3, CURRENT_TIMESTAMP, false),
(11, 17, 12, '"Juro pelo nome do Senhor, o teu Deus", ela respondeu, "não tenho nenhum pedaço de pão; só um punhado de farinha num jarro e um pouco de azeite numa botija. Estou colhendo uns dois gravetos para levar para casa e preparar uma refeição para mim e para o meu filho, para que a comamos e depois morramos. "', 3, CURRENT_TIMESTAMP, false),
(11, 17, 13, 'Elias, porém, lhe disse: "Não tenha medo. Vá para casa e faça o que disse. Mas primeiro faça um pequeno bolo com o que você tem e traga para mim, e depois faça algo para você e para o seu filho.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 14, 'Pois assim diz o Senhor, o Deus de Israel: ‘A farinha na vasilha não se acabará e o azeite na botija não se secará até o dia em que o Senhor fizer chover sobre a terra’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 17, 15, 'Ela foi e fez conforme Elias lhe dissera. E aconteceu que a comida durou todos os dias para Elias e para a mulher e sua família.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 16, 'Pois a farinha na vasilha não se acabou e o azeite na botija não se secou, conforme a palavra do Senhor proferida por Elias.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 17, 'Algum tempo depois o filho da mulher, dona da casa, ficou doente, foi piorando e finalmente parou de respirar.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 18, 'E a mulher reclamou a Elias: "Que foi que eu te fiz, ó homem de Deus? Vieste para lembrar-me do meu pecado e matar o meu filho? "', 3, CURRENT_TIMESTAMP, false),
(11, 17, 19, '"Dê-me o seu filho", respondeu Elias. Ele o apanhou dos braços dela, levou-o para o quarto de cima onde estava hospedado, e o pôs em cima da cama.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 20, 'Então clamou ao Senhor: "Ó Senhor, meu Deus, trouxeste também desgraça sobre esta viúva, com quem estou hospedado, fazendo morrer o seu filho? "', 3, CURRENT_TIMESTAMP, false),
(11, 17, 21, 'Então ele se deitou sobre o menino três vezes e clamou ao Senhor: "Ó Senhor, meu Deus, faze voltar a vida a este menino! "', 3, CURRENT_TIMESTAMP, false),
(11, 17, 22, 'O Senhor ouviu o clamor de Elias, e a vida voltou ao menino, e ele viveu.', 3, CURRENT_TIMESTAMP, false),
(11, 17, 23, 'Então Elias levou o menino para baixo, entregou-o à mãe e disse: "Veja, seu filho está vivo! "', 3, CURRENT_TIMESTAMP, false),
(11, 17, 24, 'Então a mulher disse a Elias: "Agora sei que tu és um homem de Deus e que a palavra do Senhor, vinda da tua boca, é a verdade".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 1, 'Depois de um longo tempo, no terceiro ano da seca, a palavra do Senhor veio a Elias: "Vá apresentar-se a Acabe, pois enviarei chuva sobre a terra".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 2, 'E Elias foi. Como a fome era grande em Samaria,', 3, CURRENT_TIMESTAMP, false),
(11, 18, 3, 'Acabe convocou Obadias, o responsável por seu palácio, homem que temia muito ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 4, 'Enquanto Jezabel estava eliminando os profetas do Senhor, Obadias reuniu cem profetas e os escondeu em duas cavernas, cinqüenta em cada uma, e lhes forneceu comida e água.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 5, 'Certa vez Acabe disse a Obadias: "Vamos a todas as fontes e vales do país. Talvez consigamos achar um pouco de capim para manter vivos os cavalos e as mulas e assim não será preciso matar nenhum animal".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 6, 'De modo que dividiram o território que iam percorrer; Acabe foi numa direção e Obadias noutra.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 7, 'Quando Obadias estava a caminho, Elias o encontrou. Obadias o reconheceu, inclinou-se até o chão e perguntou: "És tu mesmo, meu senhor Elias? "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 8, '"Sou", respondeu Elias. "Vá dizer ao seu senhor: Elias está aqui. "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 9, '"O que eu fiz de errado", perguntou Obadias, "para que entregues o teu servo a Acabe para ser morto?', 3, CURRENT_TIMESTAMP, false),
(11, 18, 10, 'Juro pelo nome do Senhor, o teu Deus, que não há uma só nação ou reino aonde o rei, meu senhor, não enviou alguém para procurar por ti. E, sempre que uma nação ou reino afirmava que tu não estavas lá, ele os fazia jurar que não conseguiram encontrar-te.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 11, 'Mas agora me dizes para ir até o meu senhor e dizer-lhe: ‘Elias está aqui’.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 12, 'Não sei para onde o Espírito do Senhor poderá levar-te quando eu te deixar. Se eu for dizer a Acabe e ele não te encontrar, ele me matará. E eu, que sou teu servo, tenho adorado o Senhor desde a minha juventude.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 13, 'Por acaso não ouviste, meu senhor, o que eu fiz enquanto Jezabel estava matando os profetas do Senhor? Escondi cem dos profetas do Senhor em duas cavernas, cinqüenta em cada uma, e os abasteci de comida e água.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 14, 'E agora me dizes para ir ao meu senhor e dizer-lhe: ‘Elias está aqui’. Ele vai me matar! "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 15, 'E disse Elias: "Juro pelo nome do Senhor dos Exércitos, a quem eu sirvo, que hoje eu me apresentarei a Acabe".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 16, 'Então Obadias dirigiu-se a Acabe e passou-lhe a informação, e Acabe foi ao encontro de Elias.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 17, 'Quando viu Elias, disse-lhe: "É você mesmo, perturbador de Israel? "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 18, '"Não tenho perturbado Israel", Elias respondeu. "Mas você e a família do seu pai têm. Vocês abandonaram os mandamentos do Senhor e seguiram os baalins.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 19, 'Agora convoque todo o povo de Israel para encontrar-se comigo no monte Carmelo. E traga os quatrocentos e cinqüenta profetas de Baal e os quatrocentos profetas de Aserá, que comem à mesa de Jezabel. "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 20, 'Acabe convocou então todo o Israel e reuniu os profetas no monte Carmelo.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 21, 'Elias dirigiu-se ao povo e disse: "Até quando vocês vão oscilar entre duas opiniões? Se o Senhor é Deus, sigam-no; mas, se Baal é Deus, sigam-no". O povo, porém, nada respondeu.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 22, 'Disse então Elias: "Eu sou o único que restou dos profetas do Senhor, mas Baal tem quatrocentos e cinqüenta profetas.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 23, 'Tragam dois novilhos. Escolham eles um, e cortem-no em pedaços e o ponham sobre a lenha, mas não acendam fogo. Eu prepararei o outro novilho e o colocarei sobre a lenha, e também não acenderei fogo nela.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 24, 'Então vocês invocarão o nome do seu deus, e eu invocarei o nome do Senhor. O deus que responder por meio do fogo, esse é Deus". Então todo o povo disse: "O que você disse é bom".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 25, 'Elias disse aos profetas de Baal: "Escolham um dos novilhos e preparem-no primeiro, visto que vocês são tantos. Clamem pelo nome do seu deus, mas não acendam o fogo".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 26, 'Então pegaram o novilho que lhes foi dado e o prepararam. E clamaram pelo nome de Baal desde a manhã até o meio-dia. "Ó Baal, responde-nos! ", gritavam. E dançavam em volta do altar que haviam feito. Mas não houve nenhuma resposta; ninguém respondeu.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 27, 'Ao meio-dia Elias começou a zombar deles. "Gritem mais alto! ", dizia, "já que ele é um deus. Quem sabe está meditando, ou ocupado, ou viajando. Talvez esteja dormindo e precise ser despertado. "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 28, 'Então passaram a gritar ainda mais alto e a ferir-se com espadas e lanças, de acordo com o costume deles, até sangrarem.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 29, 'Passou o meio-dia, e eles continuaram profetizando em transe até a hora do sacrifício da tarde. Mas não houve resposta alguma; ninguém respondeu, ninguém deu atenção.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 30, 'Então Elias disse a todo o povo: "Aproximem-se de mim". O povo aproximou-se, e Elias reparou o altar do Senhor, que estava em ruínas.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 31, 'Depois apanhou doze pedras, uma para cada tribo dos descendentes de Jacó, a quem a palavra do Senhor tinha sido dirigida, e disse: "Seu nome será Israel".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 32, 'Com as pedras construiu um altar em honra do nome do Senhor, e cavou ao redor do altar uma valeta com capacidade de duas medidas de semente.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 33, 'Depois arrumou a lenha, cortou o novilho em pedaços e o pôs sobre a lenha. Então lhes disse: "Encham de água quatro jarras grandes e derramem-na sobre o holocausto e sobre a lenha".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 34, '"Façam-no novamente", disse, e eles o fizeram de novo. "Façam-no pela terceira vez", ordenou, e eles o fizeram pela terceira vez.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 35, 'A água escorria do altar, chegando a encher a valeta.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 36, 'À hora do sacrifício, o profeta Elias colocou-se à frente e orou: "Ó Senhor, Deus de Abraão, de Isaque e de Israel, que hoje fique conhecido que tu és Deus em Israel e que sou o teu servo e que fiz todas estas coisas por ordem tua.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 37, 'Responde-me, ó Senhor, responde-me, para que este povo saiba que tu, ó Senhor, és Deus, e que fazes o coração deles voltar para ti".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 38, 'Então o fogo do Senhor caiu e queimou completamente o holocausto, a lenha, as pedras e o chão, e também secou totalmente a água na valeta.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 39, 'Quando o povo viu isso, todos caíram prostrados e gritaram: "O Senhor é Deus! O Senhor é Deus! "', 3, CURRENT_TIMESTAMP, false),
(11, 18, 40, 'Então Elias ordenou-lhes: "Prendam os profetas de Baal. Não deixem nenhum escapar! " Eles os prenderam, e Elias os fez descer ao riacho de Quisom e lá os matou.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 41, 'E Elias disse a Acabe: "Vá comer e beber, pois já ouço o barulho de chuva pesada".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 42, 'Então Acabe foi comer e beber, mas Elias subiu até o alto do Carmelo, dobrou-se até o chão e pôs o rosto entre os joelhos.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 43, '"Vá e olhe na direção do mar", disse ao seu servo. E ele foi e olhou. "Não há nada lá", disse ele. Sete vezes Elias mandou: "Volte para ver".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 44, 'Na sétima vez o servo disse: "Uma nuvem tão pequena quanto a mão de um homem está se levantando do mar". Então Elias disse: "Vá dizer a Acabe: Prepare o seu carro e desça, antes que a chuva o impeça".', 3, CURRENT_TIMESTAMP, false),
(11, 18, 45, 'Enquanto isso, nuvens escuras apareceram no céu, começou a ventar e começou a chover forte, e Acabe partiu de carro para Jezreel.', 3, CURRENT_TIMESTAMP, false),
(11, 18, 46, 'O poder do Senhor veio sobre Elias, e este, prendendo a capa com o cinto, correu à frente de Acabe por todo o caminho até Jezreel.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 1, 'Ora, Acabe contou a Jezabel tudo o que Elias tinha feito e como havia matado todos aqueles profetas à espada.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 2, 'Por isso Jezabel mandou um mensageiro a Elias para dizer-lhe: "Que os deuses me castiguem com todo o rigor, caso amanhã nesta hora eu não faça com a sua vida o que você fez com a deles".', 3, CURRENT_TIMESTAMP, false),
(11, 19, 3, 'Elias teve medo e fugiu para salvar a vida. Em Berseba de Judá ele deixou o seu servo', 3, CURRENT_TIMESTAMP, false),
(11, 19, 4, 'e entrou no deserto, caminhando um dia. Chegou a um pé de giesta, sentou-se debaixo dele e orou, pedindo a morte. "Já tive o bastante, Senhor. Tira a minha vida; não sou melhor do que os meus antepassados. "', 3, CURRENT_TIMESTAMP, false),
(11, 19, 5, 'Depois se deitou debaixo da árvore e dormiu. De repente um anjo tocou nele e disse: "Levante-se e coma".', 3, CURRENT_TIMESTAMP, false),
(11, 19, 6, 'Elias olhou ao redor e ali, junto à sua cabeça, havia um pão assado sobre brasas quentes e um jarro de água. Ele comeu, bebeu e deitou-se de novo.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 7, 'O anjo do Senhor voltou, tocou nele e disse: "Levante-se e coma, pois a sua viagem será muito longa".', 3, CURRENT_TIMESTAMP, false),
(11, 19, 8, 'Então ele se levantou, comeu e bebeu. Fortalecido com aquela comida, viajou quarenta dias e quarenta noites, até que chegou a Horebe, o monte de Deus.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 9, 'Ali entrou numa caverna e passou a noite. E a palavra do Senhor veio a ele: "O que você está fazendo aqui, Elias? "', 3, CURRENT_TIMESTAMP, false),
(11, 19, 10, 'Ele respondeu: "Tenho sido muito zeloso pelo Senhor, Deus dos Exércitos. Os israelitas rejeitaram a tua aliança, quebraram os teus altares, e mataram os teus profetas à espada. Sou o único que sobrou, e agora também estão procurando matar-me".', 3, CURRENT_TIMESTAMP, false),
(11, 19, 11, 'O Senhor lhe disse: "Saia e fique no monte, na presença do Senhor, pois o Senhor vai passar". Então veio um vento fortíssimo que separou os montes e esmigalhou as rochas diante do Senhor, mas o Senhor não estava no vento. Depois do vento houve um terremoto, mas o Senhor não estava no terremoto.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 12, 'Depois do terremoto houve um fogo, mas o Senhor não estava nele. E depois do fogo houve o murmúrio de uma brisa suave.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 13, 'Quando Elias ouviu, puxou a capa para cobrir o rosto, saiu e ficou à entrada da caverna. E uma voz lhe perguntou: "O que você está fazendo aqui, Elias? "', 3, CURRENT_TIMESTAMP, false),
(11, 19, 14, 'Ele respondeu: "Tenho sido muito zeloso pelo Senhor, Deus dos Exércitos. Os israelitas rejeitaram a tua aliança, quebraram os teus altares, e mataram os teus profetas à espada. Sou o único que sobrou, e agora também estão procurando matar-me".', 3, CURRENT_TIMESTAMP, false),
(11, 19, 15, 'O Senhor lhe disse: "Volte pelo caminho por onde veio, e vá para o deserto de Damasco. Chegando lá, unja Hazael como rei da Síria.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 16, 'Unja também Jeú, filho de Ninsi, como rei de Israel, e unja Eliseu, filho de Safate, de Abel-Meolá, para suceder a você como profeta.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 17, 'Jeú matará todo aquele que escapar da espada de Hazael, e Eliseu matará todo aquele que escapar da espada de Jeú.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 18, 'No entanto, fiz sobrar sete mil em Israel, todos aqueles cujos joelhos não se inclinaram diante de Baal e todos aqueles cujas bocas não o beijaram".', 3, CURRENT_TIMESTAMP, false),
(11, 19, 19, 'Então Elias saiu de lá e encontrou Eliseu, filho de Safate. Ele estava arando com doze parelhas de bois, e estava conduzindo a décima-segunda parelha. Elias o alcançou e lançou a sua capa sobre ele.', 3, CURRENT_TIMESTAMP, false),
(11, 19, 20, 'Eliseu deixou os bois e correu atrás de Elias. "Deixa-me dar um beijo de despedida em meu pai e minha mãe", disse, "e então irei contigo. " "Vá e volte", respondeu Elias, "pelo que lhe fiz. "', 3, CURRENT_TIMESTAMP, false),
(11, 19, 21, 'E Eliseu voltou, apanhou a sua parelha de bois e os matou. Queimou o equipamento de arar para cozinhar a carne e a deu ao povo, e eles comeram. Depois partiu com Elias, e se tornou o seu auxiliar.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 1, 'O rei Ben-Hadade, da Síria, convocou todo o seu exército e, acompanhado de trinta e dois reis com seus cavalos e carros de guerra, cercou e atacou Samaria.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 2, 'Ele enviou mensageiros à cidade, a Acabe, o rei de Israel, que lhe disseram: "Isto é o que diz Ben-Hadade:', 3, CURRENT_TIMESTAMP, false),
(11, 20, 3, '‘A sua prata e o seu ouro são meus, e o melhor de suas mulheres e filhos também’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 4, 'O rei respondeu: "Que seja conforme tu dizes, ó rei, meu senhor. Eu e tudo o que tenho somos teus".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 5, 'Os mensageiros voltaram e disseram: "Assim diz Ben-Hadade: ‘Mandei tomar sua prata e seu ouro, suas mulheres e seus filhos.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 6, 'Mas amanhã, a esta hora, enviarei meus oficiais para vasculharem o seu palácio e as casas dos seus oficiais. Eles me trarão tudo o que você considera de valor’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 7, 'O rei de Israel convocou todas as autoridades de Israel e lhes disse: "Vejam como esse homem está querendo a nossa desgraça! Quando mandou tomar as minhas mulheres e os meus filhos, a minha prata e o meu ouro, eu não lhe neguei! "', 3, CURRENT_TIMESTAMP, false),
(11, 20, 8, 'As autoridades e todo o povo responderam: "Não lhe dês atenção nem concordes com as suas exigências".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 9, 'E ele respondeu aos mensageiros de Ben-Hadade: "Digam ao rei, meu senhor: Teu servo fará tudo o que exigiste na primeira vez, mas não posso atender a esta exigência". E eles levaram a resposta a Ben-Hadade.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 10, 'Então Ben-Hadade mandou esta outra mensagem a Acabe: "Que os deuses me castiguem com todo o rigor, caso fique em Samaria pó suficiente para dar um punhado a cada um dos meus homens".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 11, 'O rei de Israel respondeu: "Digam-lhe: ‘Quem está vestindo a sua armadura não deve se gabar como aquele que a está tirando’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 12, 'Ben-Hadade recebeu essa mensagem quando ele e os reis estavam bebendo em suas tendas, e ordenou aos seus homens: "Preparem-se para atacar a cidade". E eles lhe obedeceram.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 13, 'Nessa ocasião, um profeta foi até Acabe, rei de Israel, e anunciou: "Assim diz o Senhor: ‘Vê este exército enorme? Hoje eu o entregarei nas suas mãos, e então você saberá que eu sou o Senhor’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 14, '"Mas quem fará isso? ", perguntou Acabe. O profeta respondeu: "Assim diz o Senhor: ‘Os jovens soldados dos líderes das províncias o farão’ ". "E quem começará a batalha? ", perguntou. O profeta respondeu: "Você".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 15, 'Então Acabe convocou os jovens soldados dos líderes das províncias, duzentos e trinta e dois homens. Em seguida reuniu o restante dos israelitas, sete mil ao todo.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 16, 'Eles partiram ao meio-dia, enquanto Ben-Hadade e os trinta e dois reis aliados a ele estavam se embriagando nas suas tendas.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 17, 'Os jovens soldados dos líderes das províncias saíram primeiro. Nisso, uma patrulha de Ben-Hadade informou: "Saíram alguns homens de Samaria".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 18, 'Ele disse: "Quer tenham saído para a paz, quer para a guerra, tragam-nos vivos".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 19, 'Os jovens soldados dos líderes das províncias marcharam para fora da cidade, com o exército na retaguarda,', 3, CURRENT_TIMESTAMP, false),
(11, 20, 20, 'e cada um matou o seu adversário. Diante disso, os arameus fugiram, perseguidos pelos israelitas. Mas Ben-Hadade, rei da Síria, escapou a cavalo com alguns de seus cavaleiros.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 21, 'O rei de Israel avançou e destruiu os cavalos e carros de guerra e infligiu pesadas baixas aos arameus.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 22, 'Depois disso, o profeta foi ao rei de Israel e disse: "Fortaleça a sua posição e veja o que deve ser feito, pois na próxima primavera o rei da Síria o atacará de novo".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 23, 'Enquanto isso, os conselheiros do rei da Síria lhe diziam: "Os deuses deles são deuses das montanhas. É por isso que eles foram fortes demais para nós. Mas, se os combatermos nas planícies, com certeza seremos mais fortes do que eles.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 24, 'Deves tirá-los todos os reis dos seus comandos e substituí-los por outros oficiais.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 25, 'Também deves organizar um exército como o que perdeste, cavalo por cavalo e carro por carro, para que possamos combater Israel nas planícies. Então é certo que os venceremos". Ele concordou com eles e fez como foi aconselhado.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 26, 'Na primavera seguinte Ben-Hadade convocou os arameus e marchou até Afeque para lutar contra Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 27, 'Os israelitas foram convocados e, tendo recebido provisões, saíram para enfrentar os arameus. Os israelitas acamparam no lado oposto como dois pequenos rebanhos de cabras, enquanto que os arameus cobriam todo o campo.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 28, 'O homem de Deus foi ao rei de Israel e lhe disse: "Assim diz o Senhor: ‘Como os arameus pensam que o Senhor é um deus das montanhas e não um deus dos vales, eu entregarei esse exército enorme nas suas mãos, e vocês saberão que eu sou o Senhor’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 29, 'Durante sete dias estiveram acampados em frente um do outro, e no sétimo dia entraram em combate. Num só dia os israelitas mataram cem mil soldados de infantaria arameus.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 30, 'O restante deles escapou para a cidade de Afeque, onde o muro caiu sobre vinte e sete mil deles. Ben-Hadade também fugiu para a cidade e se escondeu, ora num aposento, ora noutro.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 31, 'Seus oficiais lhe disseram: "Soubemos que os reis do povo de Israel são misericordiosos. Nós vamos até o rei de Israel vestidos com panos de saco e com cordas no pescoço. Talvez ele poupe a tua vida".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 32, 'Vestindo panos de saco e tendo cordas envolvendo o pescoço, foram ao rei de Israel e disseram: "Teu servo Ben-Hadade diz: ‘Rogo-te que me deixes viver’ ". O rei respondeu: "Ele ainda está vivo? Ele é meu irmão! "', 3, CURRENT_TIMESTAMP, false),
(11, 20, 33, 'Os homens interpretaram isso como um bom sinal e de imediato aproveitaram o que ele tinha dito. "Isso mesmo, teu irmão Ben-Hadade! ", disseram. "Tragam-no aqui", disse o rei. Quando Ben-Hadade chegou, Acabe o fez subir no seu carro.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 34, '"Devolverei as cidades que o meu pai tomou do teu pai", ofereceu Ben-Hadade. "Tu poderás estabelecer os teus próprios mercados em Damasco, como fez meu pai em Samaria. " Acabe disse: "Mediante um tratado, libertarei você". Então fizeram um tratado, e Acabe o deixou ir.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 35, 'Por ordem do Senhor um dos discípulos dos profetas disse ao seu companheiro: "Fira-me", mas o homem se recusou a fazê-lo.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 36, 'Então o profeta disse: "Como você não obedeceu ao Senhor, assim que você sair daqui um leão o ferirá". E, logo que o homem partiu, um leão o atacou e o feriu.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 37, 'O profeta encontrou outro homem e lhe disse: "Fira-me, por favor". Este o atingiu e o feriu.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 38, 'Então o profeta saiu e ficou ao lado da estrada, à espera do rei. Ele se disfarçou, cobrindo os olhos com sua testeira.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 39, 'Quando o rei ia passando, o profeta gritou para ele: "Teu servo entrou no auge do combate, e alguém veio a mim com um prisioneiro e me disse: ‘Vigie este homem. Se ele escapar, será a sua vida pela dele, ou você deverá pagar trinta e cinco quilos de prata’.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 40, 'Enquanto o teu servo estava ocupado com outras coisas, o homem desapareceu". "Essa é a sua sentença", disse o rei de Israel. "Você mesmo a pronunciou. "', 3, CURRENT_TIMESTAMP, false),
(11, 20, 41, 'Então o profeta rapidamente removeu a testeira dos olhos, e o rei o reconheceu como um dos profetas.', 3, CURRENT_TIMESTAMP, false),
(11, 20, 42, 'Ele disse ao rei: "Assim diz o Senhor: ‘Você libertou um homem que eu havia decidido que devia morrer. Por isso, é a sua vida pela vida dele, o seu povo pelo povo dele’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 20, 43, 'Aborrecido e irritado, o rei de Israel voltou para o seu palácio em Samaria.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 1, 'Algum tempo depois houve um incidente envolvendo uma vinha que pertencia a Nabote, de Jezreel. A vinha ficava em Jezreel, ao lado do palácio de Acabe, rei de Samaria.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 2, 'Acabe tinha dito a Nabote: "Dê-me a sua vinha para eu usar como horta, já que fica ao lado do meu palácio. Em troca eu lhe darei uma vinha melhor ou, se preferir, eu lhe pagarei, seja qual for o seu valor".', 3, CURRENT_TIMESTAMP, false),
(11, 21, 3, 'Nabote, contudo, respondeu: "O SENHOR me livre de dar a ti a herança dos meus pais! "', 3, CURRENT_TIMESTAMP, false),
(11, 21, 4, 'Então Acabe foi para casa, aborrecido e indignado porque Nabote, de Jezreel, lhe dissera: "Não te darei a herança dos meus pais". Deitou-se na cama, virou o rosto para a parede e recusou-se a comer.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 5, 'Sua mulher Jezabel entrou e lhe perguntou: "Por que você está tão aborrecido? Por que não come? "', 3, CURRENT_TIMESTAMP, false),
(11, 21, 6, 'Ele respondeu-lhe: "Porque eu disse a Nabote, de Jezreel: Venda-me a sua vinha; ou, se preferir, eu lhe darei outra vinha em lugar dessa. Mas ele disse: ‘Não te darei minha vinha’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 21, 7, 'Disse-lhe Jezabel, sua mulher: "É assim que você age como rei de Israel? Levante-se e coma! Anime-se. Conseguirei para você a vinha de Nabote, de Jezreel".', 3, CURRENT_TIMESTAMP, false),
(11, 21, 8, 'Então ela escreveu cartas em nome de Acabe, pôs nelas o selo do rei, e as enviou às autoridades e aos nobres da cidade de Nabote.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 9, 'Naquelas cartas ela escreveu: "Decretem um dia de jejum e ponham Nabote sentado num lugar de destaque entre o povo.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 10, 'E mandem dois homens vadios sentar-se em frente dele e façam com que testemunhem que ele amaldiçoou tanto a Deus quanto ao rei. Levem-no para fora e apedrejem-no até a morte".', 3, CURRENT_TIMESTAMP, false),
(11, 21, 11, 'As autoridades e os nobres da cidade de Nabote fizeram conforme Jezabel os orientara nas cartas que lhes tinha escrito.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 12, 'Decretaram jejum e fizeram Nabote sentar-se num local destacado no meio do povo.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 13, 'Então dois homens vadios vieram e se sentaram em frente dele e o acusaram diante do povo, dizendo: "Nabote amaldiçoou tanto a Deus quanto ao rei". Por isso o levaram para fora da cidade e o apedrejaram até a morte.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 14, 'Então mandaram informar a Jezabel: "Nabote foi apedrejado e está morto".', 3, CURRENT_TIMESTAMP, false),
(11, 21, 15, 'Assim que Jezabel soube que Nabote tinha sido apedrejado até a morte, disse a Acabe: "Levante-se e tome posse da vinha que Nabote, de Jezreel, recusou-se a vender-lhe. Ele não está mais vivo; está morto! "', 3, CURRENT_TIMESTAMP, false),
(11, 21, 16, 'Quando Acabe ouviu que Nabote estava morto, levantou-se e foi tomar posse da vinha.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 17, 'Então a palavra do Senhor veio ao tesbita Elias:', 3, CURRENT_TIMESTAMP, false),
(11, 21, 18, '"Vá encontrar-se com Acabe, o rei de Israel, que reina em Samaria. Agora ele está na vinha de Nabote para tomar posse dela.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 19, 'Diga-lhe: Assim diz o Senhor: Você assassinou um homem e ainda se apossou de sua propriedade? E acrescentou: Assim diz o Senhor: No local onde os cães lamberam o sangue de Nabote, lamberão também o seu sangue; isso mesmo, o seu sangue! "', 3, CURRENT_TIMESTAMP, false),
(11, 21, 20, 'Acabe disse a Elias: "Então você me encontrou, meu inimigo! " "Eu o encontrei", ele respondeu, "porque você se vendeu para fazer o que o Senhor reprova.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 21, '‘Vou trazer desgraça sobre você. Devorarei os seus descendentes e eliminarei da sua família todos os do sexo masculino em Israel, sejam escravos ou livres.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 22, 'Farei à sua família o que fiz à de Jeroboão, filho de Nebate, e à de Baasa, filho de Aías, pois você provocou a minha ira e fez Israel pecar. ’', 3, CURRENT_TIMESTAMP, false),
(11, 21, 23, '"E, acerca de Jezabel, o Senhor diz: ‘Os cães devorarão Jezabel junto ao muro de Jezreel’.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 24, '"Os que pertencem a Acabe e que morrerem na cidade os cães comerão, e as aves do céu se alimentarão dos que morrerem no campo".', 3, CURRENT_TIMESTAMP, false),
(11, 21, 25, '( Nunca existiu ninguém como Acabe, que se vendeu para fazer o que o Senhor reprova, pressionado por sua mulher Jezabel.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 26, 'Ele se comportou da maneira mais detestável possível, indo atrás de ídolos, como faziam os amorreus, que o Senhor tinha expulsado de diante de Israel. )', 3, CURRENT_TIMESTAMP, false),
(11, 21, 27, 'Quando Acabe ouviu essas palavras, rasgou as suas vestes, vestiu-se de pano de saco e jejuou. Passou a dormir sobre panos de saco e agia com mansidão.', 3, CURRENT_TIMESTAMP, false),
(11, 21, 28, 'Então a palavra do Senhor veio ao tesbita Elias:', 3, CURRENT_TIMESTAMP, false),
(11, 21, 29, '"Você notou como Acabe se humilhou diante de mim? Visto que se humilhou, não trarei essa desgraça durante o seu reinado, mas durante o reinado de seu filho".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 1, 'Durante três anos não houve guerra entre a Síria e Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 2, 'Mas no terceiro ano, Josafá, rei de Judá, foi visitar o rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 3, 'Este havia perguntado aos seus oficiais: "Por acaso vocês não sabem que Ramote-Gileade nos pertence, e ainda assim não estamos fazendo nada para retomá-la do rei da Síria? "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 4, 'Então perguntou a Josafá: "Irás comigo lutar contra Ramote-Gileade? " Josafá respondeu ao rei de Israel: "Sou como tu, e meu povo é como o teu povo, e os meus cavalos são como se fossem teus".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 5, 'Mas acrescentou: "Peço-te que busques primeiro o conselho do Senhor".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 6, 'Então o rei de Israel reuniu quatrocentos profetas, e lhes perguntou: "Devo ir à guerra contra Ramote-Gileade, ou não? " Eles responderam: "Sim, pois o Senhor a entregará nas mãos do rei".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 7, 'Josafá, porém, perguntou: "Não existe aqui mais nenhum profeta do Senhor, a quem possamos consultar? "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 8, 'O rei de Israel respondeu a Josafá: "Ainda há um homem por meio de quem podemos consultar o Senhor, mas eu o odeio, porque nunca profetiza coisas boas a meu respeito, mas sempre coisas ruins. É Micaías, filho de Inlá". "O rei não deveria dizer isso", Josafá respondeu.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 9, 'Então o rei de Israel chamou um dos seus oficiais e disse: "Traga Micaías, filho de Inlá, imediatamente".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 10, 'Usando vestes reais, o rei de Israel e Josafá, rei de Judá, estavam sentados em seus tronos, na eira, junto à porta de Samaria, e todos os profetas estavam profetizando em transe diante deles.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 11, 'E Zedequias, filho de Quenaaná, tinha feito chifres de ferro, e declarou: "Assim diz o Senhor: ‘Com estes chifres tu ferirás os arameus até que sejam destruídos’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 12, 'Todos os outros profetas estavam profetizando a mesma coisa, dizendo: "Ataca Ramote-Gileade, e serás vitorioso, pois o Senhor a entregará nas mãos do rei".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 13, 'O mensageiro que tinha ido chamar Micaías lhe disse: "Veja, todos os outros profetas estão predizendo que o rei terá sucesso. Sua palavra também deve ser favorável".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 14, 'Micaías, porém, disse: "Juro pelo nome do Senhor, que direi o que o Senhor me mandar".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 15, 'Quando ele chegou, o rei lhe perguntou: "Micaías, devemos ir à guerra contra Ramote-Gileade, ou não? " Ele respondeu: "Ataca, e serás vitorioso, pois o Senhor a entregará nas mãos do rei".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 16, 'O rei lhe disse: "Quantas vezes devo fazer você jurar que irá me dizer somente a verdade em nome do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 17, 'Então Micaías respondeu: "Vi todo o Israel espalhado pelas colinas, como ovelhas sem pastor, e o Senhor dizer: ‘Estes não têm dono. Cada um volte para casa em paz’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 18, 'O rei de Israel disse a Josafá: "Não lhe disse que ele nunca profetiza nada de bom a meu respeito, mas apenas coisas ruins? "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 19, 'Micaías prosseguiu: "Ouça a palavra do Senhor: Vi o Senhor assentado em seu trono, com todo o exército dos céus ao seu redor, à sua direita e à sua esquerda.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 20, 'E o Senhor disse: ‘Quem enganará Acabe para que ataque Ramote-Gileade e morra lá? ’ "E um sugeria uma coisa, outro sugeria outra,', 3, CURRENT_TIMESTAMP, false),
(11, 22, 21, 'até que, finalmente, um espírito colocou-se diante do Senhor e disse: ‘Eu o enganarei’.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 22, '" ‘De que maneira? ’, perguntou o Senhor. "Ele respondeu: ‘Irei e serei um espírito mentiroso na boca de todos os profetas do rei’. "Disse o Senhor: ‘Você conseguirá enganá-lo; vá e engane-o’.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 23, '"E o Senhor pôs um espírito mentiroso na boca destes seus profetas. O Senhor decretou a sua desgraça".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 24, 'Então Zedequias, filho de Quenaaná, aproximou-se, deu um tapa no rosto de Micaías e perguntou: "Por qual caminho foi o espírito da parte do Senhor, quando saiu de mim para falar a você? "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 25, 'Micaías respondeu: "Você descobrirá no dia em que estiver se escondendo de quarto em quarto".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 26, 'O rei então ordenou: "Enviem Micaías de volta a Amom, o governador da cidade, e a Joás, filho do rei,', 3, CURRENT_TIMESTAMP, false),
(11, 22, 27, 'e digam: ‘Assim diz o rei: Ponham este homem na prisão a pão e água, até que eu volte em segurança’ ".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 28, 'Micaías declarou: "Se você de fato voltar em segurança, o Senhor não falou por meu intermédio". E acrescentou: "Ouçam o que estou dizendo, todos vocês! "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 29, 'Então o rei de Israel e Josafá, rei de Judá, foram atacar Ramote-Gileade.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 30, 'E o rei de Israel disse a Josafá: "Entrarei disfarçado em combate, mas tu, usa as tuas vestes reais". O rei de Israel disfarçou-se, e ambos foram para o combate.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 31, 'O rei da Síria havia ordenado aos seus trinta e dois chefes de carros de guerra: "Não lutem contra ninguém, seja soldado seja oficial, senão contra o rei de Israel".', 3, CURRENT_TIMESTAMP, false),
(11, 22, 32, 'Quando os chefes dos carros viram Josafá, pensaram: "É o rei de Israel", e o cercaram para atacá-lo, mas Josafá gritou,', 3, CURRENT_TIMESTAMP, false),
(11, 22, 33, 'e quando os comandantes dos carros viram que não era o rei de Israel, deixaram de persegui-lo.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 34, 'De repente, um soldado disparou seu arco ao acaso, e atingiu o rei de Israel entre os encaixes da sua armadura. Então o rei disse ao condutor do seu carro: "Tire-me do combate. Fui ferido! "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 35, 'A batalha foi violenta durante todo o dia, e assim, o rei teve que enfrentar os arameus em pé no seu carro. O sangue de seu ferimento ficou escorrendo até o piso do carro de guerra, e ao cair da tarde, ele morreu.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 36, 'Quando o sol estava se pondo, propagou-se um grito por todo o exército: "Cada homem para a sua cidade; cada um para a sua terra! "', 3, CURRENT_TIMESTAMP, false),
(11, 22, 37, 'Assim o rei morreu e foi levado para Samaria, e ali o sepultaram.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 38, 'Lavaram o seu carro de guerra num açude em Samaria onde as prostitutas se banhavam, e os cães lamberam o seu sangue, conforme a palavra do Senhor havia declarado.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 39, 'Os demais acontecimentos do reinado de Acabe, e tudo o que fez, o palácio que construiu com revestimento de marfim, e as cidades que fortificou, tudo está escrito nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 40, 'Acabe descansou com os seus antepassados, e o seu filho Acazias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 41, 'Josafá, filho de Asa, tornou-se rei de Judá no quarto ano do reinado de Acabe, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 42, 'Josafá tinha trinta e cinco anos de idade quando se tornou rei, e reinou vinte e cinco anos em Jerusalém. O nome da sua mãe era Azuba, filha de Sili.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 43, 'Em tudo andou nos caminhos de seu pai Asa, e não se desviou deles; fez o que o Senhor aprova. Contudo, não acabou com os altares idólatras, nos quais o povo continuou a oferecer sacrifícios e a queimar incenso.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 44, 'Josafá teve paz com o rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 45, 'Os demais acontecimentos do reinado de Josafá, as suas realizações e façanhas militares, tudo está escrito nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 46, 'Ele livrou o país dos prostitutos cultuais que restaram depois do reinado do seu pai Asa.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 47, 'Ora, na época não havia rei em Edom, mas sim um governador nomeado.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 48, 'Josafá construiu uma frota de navios mercantes para buscar ouro em Ofir, mas nunca foram, pois eles naufragaram em Eziom-Geber.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 49, 'Naquela ocasião, Acazias, filho de Acabe, disse a Josafá: "Os meus marinheiros poderão navegar com os teus", mas Josafá recusou.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 50, 'Josafá descansou com seus antepassados e foi sepultado junto deles na cidade de Davi, seu pai. E o seu filho Jeorão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 51, 'Acazias, filho de Acabe, tornou-se rei de Israel em Samaria no décimo sétimo ano do reinado de Josafá, rei de Judá, e reinou dois anos sobre Israel.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 52, 'Fez o que o Senhor reprova, pois andou nos caminhos de seu pai e de sua mãe e nos caminhos de Jeroboão, filho de Nebate, que fez Israel pecar.', 3, CURRENT_TIMESTAMP, false),
(11, 22, 53, 'Prestou culto a Baal e adorou-o, e provocou a ira do Senhor, o Deus de Israel, como o seu pai tinha feito.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 1, 'Havia certo homem de Ramataim, zufita, dos montes de Efraim, chamado Elcana, filho de Jeroão, neto de Eliú e bisneto de Toú, filho do efraimita Zufe.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 2, 'Ele tinha duas mulheres; uma se chamava Ana, e a outra Penina. Penina tinha filhos, Ana, porém, não tinha.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 3, 'Todos os anos esse homem subia de sua cidade a Siló para adorar e sacrificar ao Senhor dos Exércitos. Lá, Hofni e Finéias, os dois filhos de Eli, eram sacerdotes do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 4, 'No dia em que Elcana oferecia sacrifícios, dava porções à sua mulher Penina e a todos os filhos e filhas dela.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 5, 'Mas a Ana dava uma porção dupla, porque a amava, mesmo que o Senhor a houvesse deixado estéril.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 6, 'E porque o Senhor a tinha deixado estéril, sua rival a provocava continuamente, a fim de irritá-la.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 7, 'Isso acontecia ano após ano. Sempre que Ana subia à casa do Senhor, sua rival a provocava e ela chorava e não comia.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 8, 'Elcana, seu marido, lhe perguntava: "Ana, por que você está chorando? Por que não come? Por que está triste? Será que eu não sou melhor para você do que dez filhos? "', 3, CURRENT_TIMESTAMP, false),
(9, 1, 9, 'Certa vez quando terminou de comer e beber em Siló, estando o sacerdote Eli sentado numa cadeira junto à entrada do santuário do Senhor, Ana se levantou', 3, CURRENT_TIMESTAMP, false),
(9, 1, 10, 'e, com a alma amargurada, chorou muito e orou ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 11, 'E fez um voto, dizendo: "Ó Senhor dos Exércitos, se tu deres atenção à humilhação de tua serva, te lembrares de mim e não te esqueceres de tua serva, mas lhe deres um filho, então eu o dedicarei ao Senhor por todos os dias de sua vida, e o seu cabelo e a sua barba nunca serão cortados".', 3, CURRENT_TIMESTAMP, false),
(9, 1, 12, 'Enquanto ela continuava a orar diante do Senhor, Eli observava sua boca.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 13, 'Como Ana orava silenciosamente, seus lábios se mexiam mas não se ouvia sua voz. Então Eli pensou que ela estivesse embriagada', 3, CURRENT_TIMESTAMP, false),
(9, 1, 14, 'e lhe disse: "Até quando você continuará embriagada? Abandone o vinho! "', 3, CURRENT_TIMESTAMP, false),
(9, 1, 15, 'Ana respondeu: "Não se trata disso, meu senhor. Sou uma mulher muito angustiada. Não bebi vinho nem bebida fermentada; eu estava derramando minha alma diante do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 16, 'Não julgues tua serva uma mulher vadia; estou orando aqui até agora por causa de minha grande angústia e tristeza".', 3, CURRENT_TIMESTAMP, false),
(9, 1, 17, 'Eli respondeu: "Vá em paz, e que o Deus de Israel lhe conceda o que você pediu".', 3, CURRENT_TIMESTAMP, false),
(9, 1, 18, 'Ela disse: "Espero que sejas benevolente para com tua serva! " Então ela seguiu seu caminho, comeu, e seu rosto já não estava mais abatido.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 19, 'Na manhã seguinte, eles se levantaram e adoraram ao Senhor; então voltaram para casa, em Ramá. Elcana teve relações com sua mulher Ana, e o Senhor se lembrou dela.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 20, 'Assim Ana engravidou e, no devido tempo, deu à luz um filho. E deu-lhe o nome de Samuel, dizendo: "Eu o pedi ao Senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 1, 21, 'Quando no ano seguinte Elcana subiu com toda a família para oferecer o sacrifício anual ao Senhor e para cumprir o seu voto,', 3, CURRENT_TIMESTAMP, false),
(9, 1, 22, 'Ana não foi e disse a seu marido: "Depois que o menino for desmamado, eu o levarei e o apresentarei ao Senhor, e ele morará ali para sempre".', 3, CURRENT_TIMESTAMP, false),
(9, 1, 23, 'Disse Elcana, seu marido: "Faça o que lhe parecer melhor. Fique aqui até desmamá-lo; que o Senhor apenas confirme a palavra dele! " Então ela ficou em casa e amamentou seu filho até que o desmamou.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 24, 'Depois de desmamá-lo, levou o menino, ainda pequeno, à casa do Senhor, em Siló, com um novilho de três anos de idade, uma arroba de farinha e uma vasilha de couro cheia de vinho.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 25, 'Eles sacrificaram o novilho e levaram o menino a Eli,', 3, CURRENT_TIMESTAMP, false),
(9, 1, 26, 'e ela lhe disse: "Meu senhor, juro por tua vida que eu sou a mulher que esteve aqui a teu lado, orando ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 27, 'Era este menino que eu pedia, e o Senhor concedeu-me o pedido.', 3, CURRENT_TIMESTAMP, false),
(9, 1, 28, 'Por isso, agora, eu o dedico ao Senhor. Por toda a sua vida será dedicado ao Senhor". E ali adorou o Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 1, 'Então Ana orou assim: "Meu coração exulta no Senhor; no Senhor minha força é exaltada. Minha boca se exalta sobre os meus inimigos, pois me alegro em tua libertação.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 2, '"Não há ninguém santo como o Senhor; não há outro além de ti; não há rocha alguma como o nosso Deus.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 3, '"Não falem tão orgulhosamente, nem saia de suas bocas tal arrogância, pois o Senhor é Deus sábio; é ele quem julga os atos dos homens.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 4, '"O arco dos fortes é quebrado, mas os fracos são revestidos de força.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 5, 'Os que tinham muito, agora trabalham por comida, mas os que estavam famintos, agora não passam fome. A que era estéril deu à luz sete filhos, mas a que tinha muitos filhos ficou sem vigor.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 6, '"O Senhor mata e preserva a vida; ele faz descer à sepultura e dela resgata.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 7, 'O Senhor é quem dá pobreza e riqueza; ele humilha e exalta.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 8, 'Levanta do pó o necessitado e, do monte de cinzas ergue o pobre; ele os faz sentarem-se com príncipes e lhes dá lugar de honra. "Pois os alicerces da terra são do Senhor; sobre eles estabeleceu o mundo.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 9, 'Ele guardará os pés dos seus santos, mas os ímpios serão silenciados nas trevas, pois não é pela força que o homem prevalece.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 10, 'Aqueles que se opõem ao Senhor serão despedaçados. Ele trovejará do céu contra eles; o Senhor julgará até os confins da terra. Ele dará poder a seu rei e exaltará a força do seu ungido".', 3, CURRENT_TIMESTAMP, false),
(9, 2, 11, 'Então Elcana voltou para casa em Ramá; mas o menino começou a servir o Senhor sob a direção do sacerdote Eli.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 12, 'Os filhos de Eli eram ímpios; não se importavam com o Senhor', 3, CURRENT_TIMESTAMP, false),
(9, 2, 13, 'nem cumpriam os deveres de sacerdotes para com o povo; sempre que alguém oferecia um sacrifício o auxiliar do sacerdote vinha com um garfo de três dentes,', 3, CURRENT_TIMESTAMP, false),
(9, 2, 14, 'e, enquanto a carne estava cozinhando, ele enfiava o garfo na panela, ou travessa, ou caldeirão, ou caçarola, e o sacerdote pegava para si tudo o que vinha no garfo. Assim faziam com todos os israelitas que iam a Siló.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 15, 'Mas, antes mesmo de queimarem a gordura, vinha o auxiliar do sacerdote e dizia ao homem que estava oferecendo o sacrifício: "Dê um pedaço desta carne para o sacerdote assar; ele não aceitará de você carne cozida, somente crua".', 3, CURRENT_TIMESTAMP, false),
(9, 2, 16, 'Se o homem lhe dissesse: "Deixe primeiro a gordura se queimar e então pegue o que quiser", o auxiliar respondia: "Não. Entregue a carne agora. Se não, eu a tomarei à força".', 3, CURRENT_TIMESTAMP, false),
(9, 2, 17, 'O pecado desses jovens era muito grande à vista do Senhor, pois eles estavam tratando com desprezo a oferta do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 18, 'Samuel, contudo, ainda menino, ministrava perante o Senhor, vestindo uma túnica de linho.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 19, 'Todos os anos sua mãe fazia uma pequena túnica e a levava para ele, quando subia a Siló com o marido para oferecer o sacrifício anual.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 20, 'Eli abençoava Elcana e sua mulher, dizendo: "O Senhor dê a você filhos desta mulher no lugar daquele por quem ela pediu e dedicou ao Senhor". Então voltavam para casa.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 21, 'O Senhor foi bondoso com Ana; ela engravidou e deu à luz três filhos e duas filhas. Enquanto isso, o menino Samuel crescia na presença do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 22, 'Eli, já bem idoso, ficou sabendo de tudo que seus filhos faziam a todo o Israel e que eles se deitavam com as mulheres que serviam na entrada da Tenda do Encontro.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 23, 'Por isso lhes perguntou: "Por que vocês fazem estas coisas? De todo o povo ouço a respeito do mal que vocês fazem.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 24, 'Não, meus filhos; não é bom o que escuto se espalhando entre o povo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 25, 'Se um homem pecar contra outro homem, os juízes poderão intervir em seu favor; mas, se pecar contra o Senhor, quem intercederá por ele? " Seus filhos, contudo, não deram atenção à repreensão de seu pai, pois o Senhor queria matá-los.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 26, 'E o menino Samuel continuava a crescer, sendo cada vez mais estimado pelo Senhor e pelo povo.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 27, 'E veio um homem de Deus a Eli e lhe disse: "Assim diz o Senhor: ‘Acaso não me revelei claramente à família de seu pai, quando eles estavam no Egito, sob o domínio do faraó?', 3, CURRENT_TIMESTAMP, false),
(9, 2, 28, 'Escolhi seu pai dentre todas as tribos de Israel para ser o meu sacerdote, subir ao meu altar, queimar incenso e usar um colete sacerdotal na minha presença. Também dei à família de seu pai todas as ofertas preparadas no fogo pelos israelitas.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 29, 'Por que vocês zombam de meu sacrifício e de minha oferta que determinei para a minha habitação? Por que você honra seus filhos mais do que a mim, deixando-os engordar com as melhores partes de todas as ofertas feitas pelo meu povo Israel? ’', 3, CURRENT_TIMESTAMP, false),
(9, 2, 30, 'Portanto, o Senhor, o Deus de Israel, declara: ‘Prometi à sua família e à linhagem de seu pai, que ministrariam diante de mim para sempre’. Mas agora o Senhor declara: ‘Longe de mim tal coisa! Honrarei aqueles que me honram, mas aqueles que me desprezam serão tratados com desprezo.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 31, 'É chegada a hora em que eliminarei a sua força e a força da família de seu pai, e não haverá mais nenhum idoso na sua família,', 3, CURRENT_TIMESTAMP, false),
(9, 2, 32, 'e você verá aflição na minha habitação. Embora Israel prospere, na sua família ninguém alcançará idade avançada.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 33, 'E todo descendente seu que eu não eliminar de meu altar será poupado apenas para lhe consumir os olhos com lágrimas e para lhe entristecer o coração, e todos os seus descendentes morrerão no vigor da vida.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 34, 'E o que acontecer a seus dois filhos, Hofni e Finéias, será um sinal para você: os dois morrerão no mesmo dia.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 35, 'Levantarei para mim um sacerdote fiel, que agirá de acordo com o meu coração e o meu pensamento. Edificarei firmemente a família dele, e ele ministrará sempre perante o meu rei ungido.', 3, CURRENT_TIMESTAMP, false),
(9, 2, 36, 'Então todo o que restar da sua família virá e se prostrará perante ele, para obter uma moeda de prata e um pedaço de pão. E lhe implorará que o ponha em alguma função sacerdotal, para ter o que comer’ ".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 1, 'O menino Samuel ministrava perante o Senhor, sob a direção de Eli; naqueles dias raramente o Senhor falava, e as visões não eram freqüentes.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 2, 'Certa noite, Eli, cujos olhos estavam ficando tão fracos que já não conseguia mais enxergar, estava deitado em seu lugar de costume.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 3, 'A lâmpada de Deus ainda não havia se apagado, e Samuel estava deitado no santuário do Senhor, onde se encontrava a arca de Deus.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 4, 'Então o Senhor chamou Samuel. Samuel respondeu: "Estou aqui".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 5, 'E correu até Eli e disse: "Estou aqui; o senhor me chamou? " Eli, porém, disse: "Não o chamei; volte e deite-se". Então, ele foi e se deitou.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 6, 'De novo o Senhor chamou: "Samuel! " E Samuel se levantou e foi até Eli e disse: "Estou aqui; o senhor me chamou? " Disse Eli: "Meu filho, não o chamei; volte e deite-se".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 7, 'Ora, Samuel ainda não conhecia o Senhor. A palavra do Senhor ainda não lhe havia sido revelada.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 8, 'O Senhor chamou Samuel pela terceira vez. Ele se levantou, foi até Eli e disse: "Estou aqui; o senhor me chamou? " Então Eli percebeu que o Senhor estava chamando o menino', 3, CURRENT_TIMESTAMP, false),
(9, 3, 9, 'e lhe disse: "Vá e deite-se; se ele chamá-lo, diga: ‘Fala, Senhor, pois o teu servo está ouvindo’ ". Então Samuel foi se deitar.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 10, 'O Senhor voltou a chamá-lo como nas outras vezes: "Samuel, Samuel! " Então Samuel disse: "Fala, pois o teu servo está ouvindo".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 11, 'E o Senhor disse a Samuel: "Vou realizar em Israel algo que fará tinir os ouvidos de todos os que ficarem sabendo.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 12, 'Nessa ocasião executarei contra Eli tudo o que falei contra sua família, do começo ao fim.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 13, 'Pois eu lhe disse que julgaria sua família para sempre, por causa do pecado dos seus filhos, do qual ele tinha consciência; seus filhos se fizeram desprezíveis, e ele não os repreendeu.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 14, 'Por isso jurei à família de Eli: ‘Jamais se fará propiciação pela culpa da família de Eli mediante sacrifício ou oferta’ ".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 15, 'Samuel ficou deitado até de manhã e então abriu as portas da casa do Senhor. Ele teve medo de contar a visão a Eli,', 3, CURRENT_TIMESTAMP, false),
(9, 3, 16, 'mas este o chamou e disse: "Samuel, meu filho". "Estou aqui", respondeu Samuel.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 17, 'Eli perguntou: "O que o Senhor lhe disse? Não esconda de mim. Deus o castigue, e o faça com muita severidade, se você esconder de mim qualquer coisa que ele lhe falou".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 18, 'Então, Samuel lhe contou tudo, e nada escondeu. Então Eli disse: "Ele é o Senhor; que faça o que lhe parecer melhor".', 3, CURRENT_TIMESTAMP, false),
(9, 3, 19, 'O Senhor estava com Samuel enquanto este crescia, e fazia com que todas as suas palavras se cumprissem.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 20, 'Todo o Israel, de Dã até Berseba, reconhecia que Samuel estava confirmado como profeta do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 3, 21, 'O Senhor continuou aparecendo em Siló, onde havia se revelado a Samuel por meio de sua palavra.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 1, 'Os filisteus dispuseram suas forças em linha para enfrentar Israel, e, intensificando-se o combate, Israel foi derrotado pelos filisteus, que mataram cerca de quatro mil deles no campo de batalha.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 2, 'Quando os soldados voltaram ao acampamento, as autoridades de Israel perguntaram: "Por que o Senhor deixou que os filisteus nos derrotassem? Vamos a Siló buscar a arca da aliança do Senhor, para que ele vá conosco e nos salve das mãos de nossos inimigos".', 3, CURRENT_TIMESTAMP, false),
(9, 4, 3, 'Então mandaram trazer de Siló a arca da aliança do Senhor dos Exércitos, que tem o seu trono entre os querubins. E os dois filhos de Eli, Hofni e Finéias, acompanharam a arca da aliança de Deus.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 4, 'Quando a arca da aliança do Senhor entrou no acampamento, todos os israelitas gritaram tão alto que o chão estremeceu.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 5, 'Os filisteus, ouvindo os gritos, perguntaram: "O que significam todos esses gritos no acampamento dos hebreus? "', 3, CURRENT_TIMESTAMP, false),
(9, 4, 6, 'souberam que a arca do Senhor viera para o acampamento,', 3, CURRENT_TIMESTAMP, false),
(9, 4, 7, 'os filisteus ficaram com medo e disseram: "Deuses chegaram ao acampamento. Ai de nós! Nunca nos aconteceu uma coisa dessas!', 3, CURRENT_TIMESTAMP, false),
(9, 4, 8, 'Ai de nós! Quem nos livrará das mãos desses deuses poderosos? São os deuses que feriram os egípcios com toda espécie de pragas, no deserto.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 9, 'Sejam fortes, filisteus! Sejam homens ou vocês se tornarão escravos dos hebreus, assim como eles foram escravos de vocês. Sejam homens e lutem! "', 3, CURRENT_TIMESTAMP, false),
(9, 4, 10, 'Então os filisteus lutaram e Israel foi derrotado; cada homem fugiu para sua tenda. O massacre foi muito grande: Israel perdeu trinta mil homens de infantaria.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 11, 'A arca de Deus foi tomada, e os dois filhos de Eli, Hofni e Finéias, morreram.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 12, 'Naquele mesmo dia um benjamita correu da linha de batalha até Siló, com as roupas rasgadas e terra na cabeça.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 13, 'Quando ele chegou, Eli estava sentado, observando sua cadeira, ao lado da estrada, pois seu coração temia pela arca de Deus. O homem entrou na cidade e contou o que havia acontecido, e a cidade começou a gritar.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 14, 'Eli ouviu os gritos e perguntou: "O que significa esse tumulto? " O homem correu para contar tudo a Eli.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 15, 'Eli tinha noventa e oito anos de idade e seus olhos estavam imóveis, e ele já não conseguia enxergar.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 16, 'O homem lhe disse: "Acabei de chegar da linha de batalha; fugi de lá hoje mesmo". Eli perguntou: "O que aconteceu, meu filho? "', 3, CURRENT_TIMESTAMP, false),
(9, 4, 17, 'O mensageiro respondeu: "Israel fugiu dos filisteus, e houve uma grande matança entre os soldados. Também os seus dois filhos, Hofni e Finéias, estão mortos, e a arca de Deus foi tomada".', 3, CURRENT_TIMESTAMP, false),
(9, 4, 18, 'Quando ele mencionou a arca de Deus, Eli caiu da cadeira para trás, ao lado do portão, quebrou o pescoço, e morreu, pois era velho e pesado. Ele liderou Israel durante quarenta anos.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 19, 'Sua nora, a mulher de Finéias, estava grávida e perto de dar à luz. Quando ouviu a notícia de que a arca de Deus havia sido tomada e que seu sogro e seu marido estavam mortos, entrou em trabalho de parto e deu à luz, mas não resistiu às dores do parto.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 20, 'Enquanto morria, as mulheres que a ajudavam disseram: "Não se desespere; você teve um menino". Mas ela não respondeu nem deu atenção.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 21, 'Ela deu ao menino o nome de Icabode, e disse: "A glória se foi de Israel". Porque a arca foi tomada e por causa da morte do sogro e do marido.', 3, CURRENT_TIMESTAMP, false),
(9, 4, 22, 'E ainda acrescentou: "A glória se foi de Israel, pois a arca de Deus foi tomada".', 3, CURRENT_TIMESTAMP, false),
(9, 5, 1, 'Depois que os filisteus tomaram a arca de Deus, eles a levaram de Ebenézer para Asdode.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 2, 'E a colocaram dentro do templo de Dagom, ao lado de sua estátua.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 3, 'Quando o povo de Asdode se levantou na madrugada do dia seguinte, lá estava Dagom caído, rosto em terra, diante da arca do Senhor! Eles levantaram Dagom e o colocaram de volta em seu lugar.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 4, 'Mas, na manhã seguinte, quando se levantaram de madrugada, lá estava Dagom caído, rosto em terra, diante da arca do Senhor! Sua cabeça e mãos tinham sido quebradas e estavam sobre a soleira; só o seu corpo ficou no lugar.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 5, 'Por isso, até hoje, os sacerdotes de Dagom e todos os que entram em seu templo, em Asdode, não pisam na soleira.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 6, 'Depois disso a mão do Senhor pesou sobre o povo de Asdode e dos arredores, trazendo devastação sobre eles e afligindo-os com tumores.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 7, 'Quando os homens de Asdode viram o que estava acontecendo, disseram: "A arca do deus de Israel não deve ficar aqui conosco, pois a mão dele pesa sobre nós e sobre nosso deus Dagom".', 3, CURRENT_TIMESTAMP, false),
(9, 5, 8, 'Então reuniram todos os governantes dos filisteus e lhes perguntaram: "O que faremos com a arca do deus de Israel? " Eles responderam: "Levem a arca do deus de Israel para Gate". E então levaram a arca do Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 9, 'Mas, quando a arca chegou, a mão do Senhor castigou aquela cidade, e trouxe-lhe grande pânico. Ele afligiu o povo da cidade, jovens e velhos, com uma epidemia de tumores.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 10, 'Então enviaram a arca de Deus para Ecrom. Quando a arca de deus estava entrando na cidade de Ecrom, o povo começou a gritar: "Eles trouxeram a arca do deus de Israel para cá afim de matar a nós e a nosso povo".', 3, CURRENT_TIMESTAMP, false),
(9, 5, 11, 'Então reuniram todos os governantes dos filisteus e disseram: "Levem embora a arca do deus de Israel; que ela volte ao seu lugar; caso contrário ela matará a nós e a nosso povo". Pois havia pânico mortal em toda a cidade; a mão de Deus pesava muito sobre ela.', 3, CURRENT_TIMESTAMP, false),
(9, 5, 12, 'Aqueles que não morreram foram afligidos com tumores, e o clamor da cidade subiu até o céu.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 1, 'Quando já fazia sete meses que a arca do Senhor estava em território filisteu,', 3, CURRENT_TIMESTAMP, false),
(9, 6, 2, 'os filisteus chamaram os sacerdotes e adivinhos e disseram: "O que faremos com a arca do Senhor? Digam-nos com o que devemos mandá-la de volta a seu lugar".', 3, CURRENT_TIMESTAMP, false),
(9, 6, 3, 'Eles responderam: "Se vocês devolverem a arca do deus de Israel, não mandem de volta só a arca, mas enviem também uma oferta pela culpa. Então vocês serão curados e saberão por que a sua mão não tem se afastado de vocês".', 3, CURRENT_TIMESTAMP, false),
(9, 6, 4, 'Os filisteus perguntaram: "Que oferta pela culpa devemos lhe enviar? " Eles responderam: "Cinco tumores de ouro e cinco ratos de ouro, de acordo com o número de governantes filisteus, porquanto a mesma praga atingiu vocês e todos os seus governantes.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 5, 'Façam imagens dos tumores e dos ratos que estão assolando o país e dêem glória ao deus de Israel. Talvez ele alivie a sua mão de sobre vocês, seus deuses e sua terra.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 6, 'Por que ter o coração obstinado como os egípcios e o faraó? Somente quando esse deus os tratou severamente, eles deixaram os israelitas seguir o seu caminho.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 7, 'Agora, então, preparem uma carroça nova, com duas vacas que deram cria e sobre as quais nunca foi colocado jugo. Amarrem-nas à carroça, mas afastem delas os seus bezerros e os ponham no curral.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 8, 'Coloquem a arca do Senhor sobre a carroça, e ponham numa caixa ao lado os objetos de ouro que vocês estão lhe enviando como oferta pela culpa. Enviem a carroça,', 3, CURRENT_TIMESTAMP, false),
(9, 6, 9, 'e fiquem observando. Se ela for para seu próprio território, na direção de Bete-Semes, então foi o Senhor quem trouxe essa grande desgraça sobre nós. Mas, se ela não for, então saberemos que não foi a sua mão que nos atingiu e que isso aconteceu conosco por acaso".', 3, CURRENT_TIMESTAMP, false),
(9, 6, 10, 'E assim fizeram. Pegaram duas vacas com cria e as amarraram a uma carroça e prenderam seus bezerros no curral.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 11, 'Colocaram a arca do Senhor na carroça e junto dela a caixa com os ratos de ouro e as imagens dos tumores.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 12, 'Então as vacas foram diretamente para Bete-Semes, mantendo-se na estrada e mugindo por todo o caminho; não se desviaram para a direita nem para a esquerda. Os governantes dos filisteus as seguiram até a fronteira de Bete-Semes.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 13, 'Ora, o povo de Bete-Semes estava colhendo trigo no vale e, quando olharam e viram a arca, alegraram-se muito.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 14, 'A carroça chegou ao campo de Josué, de Bete-Semes, e ali parou ao lado de uma grande rocha. Então cortaram a madeira da carroça e ofereceram as vacas como holocausto ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 15, 'Os levitas tinham descido a arca do Senhor e a caixa com os objetos de ouro e colocado sobre a grande rocha. Naquele dia, o povo de Bete-Semes ofereceu holocaustos e sacrifícios ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 16, 'Os cinco governantes dos filisteus viram tudo isso e voltaram naquele mesmo dia a Ecrom.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 17, 'Os filisteus enviaram ao Senhor como oferta pela culpa estes tumores de ouro: um por Asdode, outro por Gaza, outro por Ascalom, outro por Gate e outro por Ecrom.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 18, 'O número dos ratos de ouro foi conforme o número das cidades filistéias que pertenciam aos cinco governantes; tanto as cidades fortificadas como os povoados no campo. A grande rocha, sobre a qual puseram a arca do Senhor, é até hoje uma testemunha no campo de Josué, de Bete-Semes.', 3, CURRENT_TIMESTAMP, false),
(9, 6, 19, 'Deus, contudo, feriu alguns dos homens de Bete-Semes, matando setenta deles, por terem olhado para dentro da arca do Senhor. O povo chorou por causa da grande matança que o Senhor fizera,', 3, CURRENT_TIMESTAMP, false),
(9, 6, 20, 'e os homens de Bete-Semes perguntaram: "Quem pode permanecer na presença do Senhor, esse Deus santo? Para quem enviamos a arca, para que se afaste de nós? "', 3, CURRENT_TIMESTAMP, false),
(9, 6, 21, 'Então enviaram mensageiros ao povo de Quiriate-Jearim, dizendo: "Os filisteus devolveram a arca do Senhor. Venham e a levem para vocês".', 3, CURRENT_TIMESTAMP, false),
(9, 7, 1, 'Então, os homens de Quiriate-Jearim vieram para levar a arca do Senhor. Eles a levaram para a casa de Abinadabe, na colina, e consagraram seu filho Eleazar para guardar a arca do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 2, 'A arca permaneceu em Quiriate-Jearim muito tempo; foram vinte anos. E todo o povo de Israel buscava o Senhor com súplicas.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 3, 'E Samuel disse a toda a nação de Israel: "Se vocês querem voltar-se para o Senhor de todo o coração, livrem-se então dos deuses estrangeiros e dos postes sagrados, consagrem-se ao Senhor e prestem culto somente a ele, e ele os libertará das mãos dos filisteus".', 3, CURRENT_TIMESTAMP, false),
(9, 7, 4, 'Assim, os israelitas se livraram dos baalins e dos postes sagrados, e começaram a prestar culto somente ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 5, 'E Samuel prosseguiu: "Reúnam todo Israel em Mispá, e eu intercederei ao Senhor a favor de vocês".', 3, CURRENT_TIMESTAMP, false),
(9, 7, 6, 'Quando eles se reuniram em Mispá, tiraram água e a derramaram perante o Senhor. Naquele dia jejuaram e disseram ali: "Temos pecado contra o Senhor". E foi em Mispá que Samuel liderou os israelitas como juiz.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 7, 'Quando os filisteus souberam que os israelitas estavam reunidos em Mispá, os governantes dos filisteus saíram para atacá-los. Quando os israelitas souberam disso, ficaram com medo dos filisteus.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 8, 'E disseram a Samuel: "Não pare de clamar por nós ao Senhor nosso Deus, para que nos salve das mãos dos filisteus".', 3, CURRENT_TIMESTAMP, false),
(9, 7, 9, 'Então Samuel pegou um cordeiro ainda não desmamado e o ofereceu inteiro como holocausto ao Senhor. Ele clamou ao Senhor em favor de Israel, e o Senhor lhe respondeu.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 10, 'Enquanto Samuel oferecia o holocausto, os filisteus se aproximaram para combater Israel. Naquele dia, porém, o Senhor trovejou com fortíssimo estrondo contra os filisteus e os colocou em pânico. Então foram derrotados por Israel.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 11, 'Os soldados de Israel saíram de Mispá e perseguiram os filisteus até um lugar abaixo de Bete-Car, matando-os pelo caminho.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 12, 'Então Samuel pegou uma pedra e a ergueu entre Mispá e Sem; e deu-lhe o nome de Ebenézer, dizendo: "Até aqui o Senhor nos ajudou".', 3, CURRENT_TIMESTAMP, false),
(9, 7, 13, 'Assim os filisteus foram dominados e não voltaram a invadir o território israelita. A mão do Senhor opôs-se aos filisteus durante toda a vida de Samuel.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 14, 'As cidades que os filisteus haviam conquistado, foram devolvidas a Israel, desde Ecrom até Gate. Israel libertou os territórios ao redor delas do poder dos filisteus. E houve também paz entre Israel e os amorreus.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 15, 'Samuel continuou como juiz de Israel durante todos os dias de sua vida.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 16, 'A cada ano percorria Betel, Gilgal, e Mispá, decidindo as questões de Israel em todos esses lugares.', 3, CURRENT_TIMESTAMP, false),
(9, 7, 17, 'Mas sempre retornava a Ramá, onde ficava sua casa; ali ele liderava Israel como juiz e naquele lugar construiu um altar em honra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 1, 'Quando envelheceu, Samuel nomeou seus filhos como líderes de Israel.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 2, 'Seu filho mais velho chamava-se Joel, o segundo, Abias. Eles eram líderes em Berseba.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 3, 'Mas os filhos dele não andaram em seus caminhos. Eles se tornaram gananciosos, aceitaram suborno e perverteram a justiça.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 4, 'Por isso, todas as autoridades de Israel reuniram-se e foram falar com Samuel, em Ramá.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 5, 'E disseram-lhe: "Tu já estás idoso, e teus filhos não andam em teus caminhos; escolhe agora um rei para que nos lidere, à semelhança das outras nações".', 3, CURRENT_TIMESTAMP, false),
(9, 8, 6, 'Quando, porém, disseram: "Dá-nos um rei para que nos lidere", isto desagradou a Samuel; então ele orou ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 7, 'E o Senhor lhe respondeu: "Atenda a tudo o que o povo está lhe pedindo; não foi a você que rejeitaram; foi a mim que rejeitaram como rei.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 8, 'Assim como fizeram comigo desde o dia em que os tirei do Egito, até hoje, abandonando-me e prestando culto a outros deuses, também estão fazendo com você.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 9, 'Agora atenda-os; mas advirta-os solenemente e diga-lhes que direitos reivindicará o rei que os governará".', 3, CURRENT_TIMESTAMP, false),
(9, 8, 10, 'Samuel transmitiu todas as palavras do Senhor ao povo, que estava lhe pedindo um rei,', 3, CURRENT_TIMESTAMP, false),
(9, 8, 11, 'dizendo: "Isto é o que o rei que reinará sobre vocês reivindicará como seu direito: ele tomará os filhos de vocês para servi-lo em seus carros de guerra e em sua cavalaria, e para correr à frente dos seus carros de guerra.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 12, 'Colocará alguns como comandantes de mil e outros como comandantes de cinqüenta. Ele os fará arar as terras dele, fazer a colheita, e fabricar armas de guerra e equipamentos para os seus carros de guerra.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 13, 'Tomará as filhas de vocês para serem perfumistas, cozinheiras e padeiras.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 14, 'Tomará de vocês o melhor das plantações, das vinhas e dos olivais, e o dará aos criados dele.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 15, 'Tomará um décimo dos cereais e da colheita das uvas e o dará a seus oficiais e a seus criados.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 16, 'Também tomará de vocês para seu uso particular os servos e as servas, o melhor do gado e dos jumentos.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 17, 'E tomará de vocês um décimo dos rebanhos, e vocês mesmos se tornarão escravos dele.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 18, 'Naquele dia, vocês clamarão por causa do rei que vocês mesmos escolheram, e o Senhor não os ouvirá".', 3, CURRENT_TIMESTAMP, false),
(9, 8, 19, 'Todavia, o povo recusou-se a ouvir Samuel, e disseram: "Não! Queremos ter um rei.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 20, 'Seremos como todas as outras nações; um rei nos governará, e sairá à nossa frente para combater em nossas batalhas".', 3, CURRENT_TIMESTAMP, false),
(9, 8, 21, 'Depois de ter ouvido tudo o que o povo disse, Samuel o repetiu perante o Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 8, 22, 'E o Senhor respondeu: "Atenda-os e dê-lhes um rei". Então Samuel disse aos homens de Israel: "Volte cada um para sua cidade".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 1, 'Havia um homem de Benjamim, rico e influente, chamado Quis, filho de Abiel, neto de Zeror, bisneto de Becorate e trineto de Afia.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 2, 'Ele tinha um filho chamado Saul, jovem de boa aparência, sem igual entre os israelitas; os mais altos batiam nos seus ombros.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 3, 'E aconteceu que jumentas de Quis, pai de Saul, extraviaram-se. E ele disse a Saul: "Chame um dos servos e vá procurar as jumentas".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 4, 'Eles atravessaram os montes de Efraim e a região de Salisa, mas não as encontraram. Prosseguindo, entraram no distrito de Saalim, mas as jumentas não estavam lá. Então atravessaram o território de Benjamim, e mesmo assim não as encontrou.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 5, 'Chegando ao distrito de Zufe, disse Saul ao seu servo: "Vamos voltar, ou meu pai deixará de pensar nas jumentas para começar a preocupar-se conosco".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 6, 'O servo, contudo, respondeu: "Nesta cidade mora um homem de Deus que é muito respeitado. Tudo o que ele diz acontece. Vamos falar com ele. Talvez ele nos aponte o caminho a seguir".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 7, 'Saul disse a seu servo: "Se formos, o que poderemos lhe dar? A comida de nossas sacos de viagem acabou. Não temos nenhum presente para levar ao homem de Deus. O que temos para oferecer? "', 3, CURRENT_TIMESTAMP, false),
(9, 9, 8, 'O servo lhe respondeu: "Tenho três gramas de prata. Darei isto ao homem de Deus para que ele nos aponte o caminho a seguir".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 9, '( Antigamente em Israel, quando alguém ia consultar a Deus, dizia: "Vamos ao vidente", pois o profeta de hoje era chamado vidente. )', 3, CURRENT_TIMESTAMP, false),
(9, 9, 10, 'E Saul concordou: "Muito bem, vamos! " Assim, foram em direção à cidade onde estava o homem de Deus.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 11, 'Ao subirem a colina para chegar à cidade, encontraram algumas jovens que estavam saindo para buscar água e perguntaram a elas: "O vidente está na cidade? "', 3, CURRENT_TIMESTAMP, false),
(9, 9, 12, 'Elas responderam: "Sim. Ele está ali adiante. Apressem-se; ele chegou hoje à nossa cidade, porque o povo vai oferecer um sacrifício no altar no monte.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 13, 'Assim que entrarem na cidade, vocês o encontrarão antes que suba ao altar no monte para comer. O povo não começará a comer antes que ele chegue, pois ele deve abençoar o sacrifício; depois disso, os convidados irão comer. Subam agora e vocês logo o encontrarão".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 14, 'Eles foram à cidade e, ao entrarem, Samuel vinha na direção deles a caminho do altar no monte.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 15, 'No dia anterior à chegada de Saul, o Senhor havia revelado isto a Samuel:', 3, CURRENT_TIMESTAMP, false),
(9, 9, 16, '"Amanhã, por volta desta hora, enviarei a você um homem da terra de Benjamim. Unja-o como líder sobre meu povo Israel; ele libertará o meu povo das mãos dos filisteus. Atentei para o meu povo, pois seu clamor chegou a mim".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 17, 'Quando Samuel viu Saul, o Senhor lhe disse: "Este é o homem de quem lhe falei; ele governará o meu povo".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 18, 'Saul aproximou-se de Samuel na entrada da cidade e lhe perguntou: "Por favor, pode me dizer onde é a casa do vidente? "', 3, CURRENT_TIMESTAMP, false),
(9, 9, 19, 'Respondeu Samuel: "Eu sou o vidente. Vá na minha frente para o altar, pois hoje você comerá comigo. Amanhã cedo eu lhe contarei tudo o que você quer saber e o deixarei ir.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 20, 'Quanto às jumentas que você perdeu há três dias, não se preocupe com elas; já foram encontradas. E a quem pertencerá tudo o que é precioso em Israel, senão a você e toda a família de seu pai? "', 3, CURRENT_TIMESTAMP, false),
(9, 9, 21, 'Saul respondeu: "Acaso não sou eu um benjamita, da menor das tribos de Israel, e não é o meu clã o mais insignificante de todos os clãs da tribo de Benjamim? Por que então estás me dizendo tudo isso? "', 3, CURRENT_TIMESTAMP, false),
(9, 9, 22, 'Então Samuel levou a Saul e seu servo para a sala e deu a eles o lugar de honra entre os convidados, cerca de trinta pessoas.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 23, 'E disse ao cozinheiro: "Traga-me a porção de carne que lhe entreguei e mandei reservar".', 3, CURRENT_TIMESTAMP, false),
(9, 9, 24, 'Então o cozinheiro pegou a coxa do animal com o que estava sobre ele e colocou tudo diante de Saul. E disse Samuel: "Aqui está o que lhe foi reservado. Coma, pois desde o momento em que eu disse: ‘Tenho convidados’, ela lhe foi separada para esta ocasião". E Saul comeu com Samuel naquele dia.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 25, 'Depois de ter descido do altar no monte para a cidade, Samuel conversou com Saul no terraço de sua casa.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 26, 'Ao romper do dia, quando se levantaram, Samuel chamou Saul no terraço e disse: "Levante-se, e eu o acompanharei, e depois você seguirá viagem". Saul se levantou e saiu junto com Samuel.', 3, CURRENT_TIMESTAMP, false),
(9, 9, 27, 'Enquanto desciam para a saída da cidade, Samuel disse a Saul: "Diga ao servo que vá na frente". O servo foi. Samuel prosseguiu: "Fique você aqui um instante, para que eu lhe dê uma mensagem da parte de Deus".', 3, CURRENT_TIMESTAMP, false),
(9, 10, 1, 'Então Samuel apanhou um jarro de óleo, derramou-o sobre a cabeça de Saul e o beijou, dizendo: "O Senhor o tem ungido como líder da herança dele.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 2, 'Hoje, quando você partir, encontrará dois homens perto do túmulo de Raquel, em Zelza, na fronteira de Benjamim. Eles lhe dirão: ‘As jumentas que você foi procurar já foram encontradas. Agora seu pai deixou de se importar com elas e está preocupado com vocês. Ele está perguntando: "Como encontrarei meu filho? "', 3, CURRENT_TIMESTAMP, false),
(9, 10, 3, 'Então, dali, você prosseguirá para o carvalho de Tabor. Três homens virão subindo ao santuário de Deus em Betel, e encontrarão você ali. Um estará levando três cabritos, outro três pães, e outro uma vasilha de couro cheia de vinho.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 4, 'Eles o cumprimentarão e lhe oferecerão dois pães, que você deve aceitar.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 5, 'Depois você irá a Gibeá de Deus, onde há um destacamento filisteu. Ao chegar à cidade, você encontrará um grupo de profetas descendo do altar no monte tocando liras, tamborins, flautas e harpas; e eles estarão profetizando.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 6, 'O Espírito do Senhor se apossará de você, e com eles você profetizará em transe, e será um novo homem.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 7, 'Assim que esses sinais tiverem se cumprido, faça o que achar melhor, pois Deus está com você.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 8, 'Vá na minha frente até Gilgal. Depois eu irei também, para oferecer holocaustos e sacrifícios de comunhão, mas você deve esperar sete dias, até que eu chegue e lhe diga o que fazer".', 3, CURRENT_TIMESTAMP, false),
(9, 10, 9, 'Quando se virou para afastar-se de Samuel, Deus mudou o coração de Saul, e todos esses sinais se cumpriram naquele dia.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 10, 'Chegando em Gibeá, um grupo de profetas o encontrou; o Espírito de Deus se apossou dele, e ele profetizou em transe no meio deles.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 11, 'Quando os que já o conheciam viram-no profetizando com os profetas, perguntaram uns aos outros: "O que aconteceu ao filho de Quis? Saul também está entre os profetas? "', 3, CURRENT_TIMESTAMP, false),
(9, 10, 12, 'Um homem daquele lugar respondeu: "E quem é o pai deles? " De modo que isto se tornou um ditado: "Saul também está entre os profetas? "', 3, CURRENT_TIMESTAMP, false),
(9, 10, 13, 'Depois que Saul parou de profetizar, foi para o altar no monte.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 14, 'Então o tio de Saul perguntou a ele e ao seu servo: "Aonde vocês foram? " Ele respondeu: "Procurar as jumentas. Quando, porém, vimos que não seriam encontradas, fomos falar com Samuel".', 3, CURRENT_TIMESTAMP, false),
(9, 10, 15, '"O que Samuel lhe disse? ", perguntou o tio.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 16, 'Saul respondeu: "Ele nos garantiu que as jumentas tinham sido encontradas". Todavia, Saul não contou ao tio o que Samuel tinha dito sobre o reino.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 17, 'Samuel convocou o povo de Israel ao Senhor, em Mispá,', 3, CURRENT_TIMESTAMP, false),
(9, 10, 18, 'e lhes disse: "Assim diz o Senhor, o Deus de Israel: ‘Eu tirei Israel do Egito, e libertei vocês do poder do Egito e de todos os reinos que os oprimiam’.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 19, 'Mas vocês agora rejeitaram o Deus que os salva de todas as suas desgraças e angústias. E disseram: ‘Não! Escolhe um rei para nós’. Por isso, agora, apresentem-se perante o Senhor, de acordo com as suas tribos e clãs".', 3, CURRENT_TIMESTAMP, false),
(9, 10, 20, 'Tendo Samuel feito todas as tribos de Israel se aproximarem, a de Benjamim foi escolhida.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 21, 'Então fez ir à frente a tribo de Benjamim, clã por clã, e o clã de Matri foi escolhido. Finalmente foi escolhido Saul, filho de Quis. Quando, porém, o procuraram, ele não foi encontrado.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 22, 'Então consultaram novamente o Senhor: "Ele já chegou? " E o Senhor disse: "Sim, ele está escondido no meio da bagagem".', 3, CURRENT_TIMESTAMP, false),
(9, 10, 23, 'Então correram e o tiraram de lá. Quando ficou de pé no meio do povo; os mais altos do povo batiam-lhe nos ombros.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 24, 'E Samuel disse a todos: "Vocês vêem o homem que o Senhor escolheu? Não há ninguém como ele entre todo o povo". Então todos gritaram: "Viva o rei! "', 3, CURRENT_TIMESTAMP, false),
(9, 10, 25, 'Samuel expôs ao povo as leis do reino. Ele as escreveu num livro e o pôs perante o Senhor. Então Samuel mandou o povo de volta para suas casas.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 26, 'Saul também foi para sua casa em Gibeá, acompanhado por guerreiros, cujos corações Deus tinha tocado.', 3, CURRENT_TIMESTAMP, false),
(9, 10, 27, 'Alguns vadios, porém, disseram: "Como este homem pode nos salvar? " Desprezaram-no e não lhe trouxeram presente algum. Mas Saul ficou calado.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 1, 'O amonita Naás avançou contra a cidade de Jabes-Gileade e a cercou. E os homens de Jabes lhe disseram: "Faça um tratado conosco, e nos sujeitaremos a você".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 2, 'Contudo, Naás, o amonita, respondeu: "Só farei um tratado com vocês sob a condição de que eu arranque o olho direito de cada um de vocês e assim humilhei todo o Israel".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 3, 'As autoridades de Jabes lhe disseram: "Dê-nos sete dias para que possamos enviar mensageiros a todo Israel; se ninguém vier nos socorrer, nós nos renderemos".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 4, 'Quando os mensageiros chegaram a Gibeá, cidade de Saul, e relataram essas coisas ao povo, todos choraram em voz alta.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 5, 'Naquele momento, Saul estava trazendo o gado do campo e perguntou: "O que há com o povo? Por que estão chorando? " Então lhe contaram o que os homens de Jabes tinham dito.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 6, 'Quando Saul ouviu isso, o Espírito de Deus apoderou-se dele, e ele ficou furioso.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 7, 'Apanhou dois bois, cortou-os em pedaços e, por meio dos mensageiros, enviou os pedaços a todo o Israel, proclamando: "Isto é o que acontecerá aos bois de quem não seguir Saul e Samuel". Então o temor do Senhor caiu sobre o povo, e eles vieram unânimes.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 8, 'Quando Saul os reuniu em Bezeque, havia trezentos mil de Israel e trinta mil de Judá.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 9, 'E disseram aos mensageiros de Jabes: "Digam aos homens de Jabes-Gileade: ‘Amanhã, na hora mais quente do dia, haverá libertação para vocês’ ". Quando relataram isso aos habitantes de Jabes, eles se alegraram.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 10, 'Então, os homens de Jabes disseram aos amonitas: "Amanhã nós nos renderemos a vocês, e poderão fazer conosco o que quiserem".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 11, 'No dia seguinte, Saul dividiu seus soldados em três grupos; entraram no acampamento amonita na alta madrugada e os mataram até a hora mais quente do dia. Aqueles que sobreviveram se dispersaram, de modo que não ficaram dois juntos.', 3, CURRENT_TIMESTAMP, false),
(9, 11, 12, 'Então o povo disse a Samuel: "Quem foi que perguntou: ‘Será que Saul vai reinar sobre nós? ’ Traga-nos esses homens, e nós os mataremos".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 13, 'Saul, porém, disse: "Hoje ninguém será morto, pois neste dia o Senhor trouxe libertação a Israel".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 14, 'Então Samuel disse ao povo: "Venham, vamos a Gilgal e reafirmemos ali o reino".', 3, CURRENT_TIMESTAMP, false),
(9, 11, 15, 'Assim, todo o povo foi a Gilgal e proclamou Saul como rei na presença do Senhor. Ali ofereceram sacrifícios de comunhão ao Senhor, e Saul e todos os israelitas se alegraram muito.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 1, 'Samuel disse a todo Israel: "Atendi tudo o que vocês me pediram e estabeleci um rei para vocês.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 2, 'Agora vocês têm um rei que os governará. Quanto a mim, estou velho e de cabelos brancos, e meus filhos estão aqui com vocês. Tenho vivido diante de vocês desde a minha juventude até agora.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 3, 'Aqui estou. Se tomei um boi ou um jumento de alguém, ou se explorei ou oprimi a alguém, ou se das mãos de alguém aceitei suborno, fechando os olhos para sua culpa, testemunhem contra mim na presença do Senhor e do seu ungido. Se alguma dessas coisas pratiquei, eu farei restituição".', 3, CURRENT_TIMESTAMP, false),
(9, 12, 4, 'E responderam: "Você não nos explorou nem nos oprimiu. Você não tirou coisa alguma das mãos de ninguém".', 3, CURRENT_TIMESTAMP, false),
(9, 12, 5, 'Samuel lhes disse: "O Senhor é testemunha diante de vocês, e bem como o seu ungido é hoje testemunha de que vocês não encontraram culpa alguma em minhas mãos". E disseram: "Ele é testemunha".', 3, CURRENT_TIMESTAMP, false),
(9, 12, 6, 'Então Samuel disse ao povo: "O Senhor designou Moisés e Arão e tirou os seus antepassados do Egito.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 7, 'Agora, pois, fiquem aqui, porque vou entrar em julgamento com vocês, perante o Senhor, com base nos atos justos realizados pelo Senhor em favor de vocês e de seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 8, 'Depois que Jacó entrou no Egito, eles clamaram ao Senhor, e ele enviou Moisés e Arão para tirar seus antepassados do Egito e os estabelecer neste lugar.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 9, 'Seus antepassados, porém, se esqueceram do Senhor seu Deus; então ele os vendeu à Sísera, o comandante do exército de Hazor, e aos filisteus e ao rei de Moabe, que lutaram contra eles.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 10, 'Eles clamaram ao Senhor, dizendo: ‘Pecamos, abandonando o Senhor e prestando culto aos baalins e aos postes sagrados. Agora, porém, liberta-nos das mãos dos nossos inimigos, e nós prestaremos culto a ti’.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 11, 'Então o Senhor enviou Jerubaal, Baraque, Jefté e Samuel, e os libertou das mãos dos inimigos que os rodeavam, de modo que vocês viveram em segurança.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 12, 'Quando, porém, vocês viram que Naás, rei dos amonitas, estava avançando contra vocês, então me disseram: ‘Não! Escolha um rei para nós’, embora o Senhor, o seu Deus, fosse o rei.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 13, 'Agora, aqui está o rei que vocês escolheram, aquele que vocês pediram; o Senhor deu um rei a vocês.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 14, 'Se vocês temerem, servirem e obedecerem ao Senhor, e não se rebelarem contra suas ordens, e, se vocês e o rei que reinar sobre vocês seguirem o Senhor, o seu Deus, tudo lhes irá bem!', 3, CURRENT_TIMESTAMP, false),
(9, 12, 15, 'Todavia, se vocês desobedecerem ao Senhor e se rebelarem contra o seu mandamento, sua mão se oporá a vocês da mesma forma como se opôs aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 16, 'Agora, preparem-se para ver este grande feito que o Senhor vai realizar diante de vocês!', 3, CURRENT_TIMESTAMP, false),
(9, 12, 17, 'Agora não é a época da colheita do trigo? Pedirei ao Senhor que envie trovões e chuva para que vocês reconheçam que fizeram o que o Senhor reprova totalmente, quando pediram um rei".', 3, CURRENT_TIMESTAMP, false),
(9, 12, 18, 'Então Samuel clamou ao Senhor, e naquele mesmo dia o Senhor enviou trovões e chuva. E assim todo o povo temeu grandemente o Senhor e Samuel.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 19, 'E todo o povo disse a Samuel: "Ore ao Senhor seu Deus em favor dos seus servos, para que não morramos, pois a todos os nossos pecados acrescentamos o mal de pedir um rei".', 3, CURRENT_TIMESTAMP, false),
(9, 12, 20, 'Respondeu Samuel: "Não tenham medo. De fato, vocês fizeram todo esse mal, mas não deixem de seguir o Senhor, antes, sirvam o Senhor de todo o coração.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 21, 'Não se desviem, para seguir ídolos inúteis, que não têm qualquer proveito nem podem livrá-los, pois são inúteis.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 22, 'Por causa de seu grande nome o Senhor não os rejeitará, pois o Senhor teve prazer em torná-los o seu próprio povo.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 23, 'E longe de mim esteja pecar contra o Senhor, deixando de orar por vocês. Também lhes ensinarei o caminho que é bom e direito.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 24, 'Somente temam o Senhor e o sirvam fielmente de todo o coração; e considerem as grandes coisas que ele tem feito por vocês.', 3, CURRENT_TIMESTAMP, false),
(9, 12, 25, 'Todavia, se insistirem em fazer o mal, tanto vocês quanto o seu rei serão destruídos".', 3, CURRENT_TIMESTAMP, false),
(9, 13, 1, 'Saul tinha trinta anos de idade quando começou a reinar, e reinou sobre Israel quarenta e dois anos.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 2, 'Saul escolheu três mil homens de Israel; dois mil ficaram com ele em Micmás e nos montes de Betel, e mil ficaram com Jônatas em Gibeá de Benjamim. O restante dos homens ele mandou de volta para suas tendas.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 3, 'Jônatas atacou os destacamentos dos filisteus em Gibeá, e os filisteus foram informados disso. Então Saul mandou tocar a trombeta por todo o país dizendo: "Que os hebreus fiquem sabendo disto! "', 3, CURRENT_TIMESTAMP, false),
(9, 13, 4, 'E todo Israel ouviu a notícia de que Saul tinha atacado o destacamento dos filisteus atraindo o ódio dos filisteus sobre Israel. Então os homens foram convocados para se unirem a Saul em Gilgal.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 5, 'Os filisteus reuniram-se para lutar contra Israel, com três mil carros de guerra, seis mil condutores de carros e tantos soldados quanto a areia da praia. Eles foram a Micmás, a leste de Bete-Áven e lá acamparam.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 6, 'Quando os soldados de Israel viram que a situação era difícil e que seu exército estava sendo muito pressionado, esconderam-se em cavernas e buracos, entre as rochas e em poços e cisternas.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 7, 'Alguns hebreus até atravessaram o Jordão para chegar à terra de Gade e de Gileade. Saul ficou em Gilgal, e os soldados que estavam com ele tremiam de medo.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 8, 'Ele esperou sete dias, o prazo estabelecido por Samuel; mas este não chegou a Gilgal, e os soldados de Saul começaram a se dispersar.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 9, 'Então ele ordenou: "Tragam-me o holocausto e os sacrifícios de comunhão". Saul ofereceu então o holocausto,', 3, CURRENT_TIMESTAMP, false),
(9, 13, 10, 'e quando ele terminou de oferecê-lo, Samuel chegou, e Saul foi saudá-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 11, 'E perguntou-lhe Samuel: "O que você fez? " Saul respondeu: "Quando vi que os soldados estavam se dispersando e que você não tinha chegado no prazo estabelecido e que os filisteus estavam reunidos em Micmás,', 3, CURRENT_TIMESTAMP, false),
(9, 13, 12, 'pensei: ‘Agora, os filisteus me atacarão em Gilgal, e eu não busquei o Senhor’. Por isso senti-me obrigado a oferecer o holocausto".', 3, CURRENT_TIMESTAMP, false),
(9, 13, 13, 'Disse Samuel: "Você agiu como tolo, desobedecendo ao mandamento que o Senhor seu Deus lhe deu; se você tivesse obedecido, ele teria estabelecido para sempre o seu reinado sobre Israel.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 14, 'Mas agora seu reinado não permanecerá; o Senhor procurou um homem segundo o seu coração e o designou líder de seu povo, pois você não obedeceu ao mandamento do Senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 13, 15, 'Então Samuel partiu de Gilgal e foi a Gibeá de Benjamim, e Saul contou soldados que estavam com ele. Eram cerca de seiscentos.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 16, 'Saul e seu filho Jônatas, acompanhados de seus soldados, ficaram em Gibeá de Benjamim, enquanto os filisteus estavam acampados em Micmás.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 17, 'Uma tropa de ataque saiu do acampamento filisteu em três divisões. Uma foi em direção a Ofra, nos arredores de Sual,', 3, CURRENT_TIMESTAMP, false),
(9, 13, 18, 'outra para Bete-Horom, e a terceira para a região fronteiriça de onde se avista o vale de Zeboim, diante do deserto.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 19, 'Naquela época não havia nem mesmo um único ferreiro em toda a terra de Israel, pois os filisteus não queriam que os hebreus fizessem espadas e lanças.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 20, 'Assim, eles tinham que ir aos filisteus para afiar seus arados, enxadas, machados e foices.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 21, 'O preço para afiar rastelos e enxadas era oito gramas de prata, e quatro gramas de prata para afiar tridentes, machados e pontas de aguilhadas.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 22, 'Por isso no dia da batalha nenhum soldado de Saul e Jônatas tinha espada ou lança nas mãos, exceto o próprio Saul e seu filho Jônatas.', 3, CURRENT_TIMESTAMP, false),
(9, 13, 23, 'Aconteceu que um destacamento filisteu foi para o desfiladeiro de Micmás.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 1, 'Certo dia, Jônatas, filho de Saul, disse ao seu jovem escudeiro: "Vamos ao destacamento filisteu, do outro lado". Ele, porém, não contou isto a seu pai.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 2, 'Saul estava sentado debaixo de uma romãzeira na fronteira de Gibeá, em Migrom. Com ele estavam uns seiscentos soldados,', 3, CURRENT_TIMESTAMP, false),
(9, 14, 3, 'entre os quais Aías, que levava o colete sacerdotal. Ele era filho de Aitube, irmão de Icabode, filho de Finéias e neto de Eli, o sacerdote do Senhor em Siló. Ninguém sabia que Jônatas havia saído.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 4, 'Em cada lado do desfiladeiro que Jônatas pretendia atravessar para chegar ao destacamento filisteu, havia um penhasco íngreme; um se chamava Bozez; o outro, Sené.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 5, 'Havia um penhasco ao norte, na direção de Micmás, e outro ao sul, na direção de Geba.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 6, 'E Jônatas disse a seu escudeiro: "Vamos ao destacamento daqueles incircuncisos. Talvez o Senhor aja em nosso favor, pois nada pode impedir o Senhor de salvar, seja com muitos ou com poucos".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 7, 'Disse seu escudeiro: "Faze tudo o que tiveres em mente; eu irei contigo".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 8, 'Jônatas disse: "Venha, vamos atravessar na direção dos soldados e deixaremos que nos avistem.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 9, 'Se nos disserem: ‘Esperem aí até que cheguemos perto’, ficaremos onde estivermos e não avançaremos.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 10, 'Mas, se disserem: ‘Subam até aqui’, subiremos, pois este será um sinal para nós de que o Senhor os entregou em nossas mãos".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 11, 'Então os dois se deixaram ver pelo destacamento dos filisteus, que disseram: "Vejam, os hebreus estão saindo dos buracos onde estavam escondidos".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 12, 'E gritaram para Jônatas e seu escudeiro: "Subam até aqui e lhes daremos uma lição". Diante disso, Jônatas disse a seu escudeiro: "Siga-me; o Senhor os entregou nas mãos de Israel".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 13, 'Jônatas escalou, usando as mãos e os pés, e o escudeiro foi logo atrás. Jônatas começou a derrubá-los, e seu escudeiro, logo atrás dele, os matava.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 14, 'Naquele primeiro ataque, Jônatas e seu escudeiro mataram cerca de vinte homens numa pequena área de terra.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 15, 'Então caiu terror sobre todo o exército, tanto sobre os que estavam no acampamento e no campo, como sobre os que estavam nos destacamentos e até mesmo nas tropas de ataque. O chão tremeu e houve um pânico terrível.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 16, 'As sentinelas de Saul em Gibeá de Benjamim viram o exército filisteu se dispersando, correndo em todas as direções.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 17, 'Então Saul disse aos seus soldados: "Contem os soldados e vejam quem está faltando". Quando o fizeram, viram que Jônatas e seu escudeiro não estavam presentes.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 18, 'Saul ordenou a Aías: "Traga a arca de Deus". Naquele tempo ela estava com os israelitas.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 19, 'Enquanto Saul falava com o sacerdote, o tumulto no acampamento filisteu ia crescendo cada vez mais. Então Saul disse ao sacerdote: "Não precisa trazer a arca".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 20, 'Então Saul e todos os soldados se reuniram e foram para a batalha. Encontraram os filisteus em total confusão, ferindo uns aos outros com suas espadas.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 21, 'Alguns hebreus que antes estavam do lado dos filisteus e que com eles tinham ido ao acampamento filisteu, passaram para o lado dos israelitas que estavam com Saul e Jônatas.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 22, 'Quando todos os israelitas que haviam se escondido nos montes de Efraim ouviram que os filisteus batiam em retirada, também entraram na batalha, perseguindo-os.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 23, 'Assim o Senhor concedeu vitória a Israel naquele dia, e a batalha se espalhou para além de Bete-Áven.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 24, 'Os homens de Israel estavam exaustos naquele dia, pois Saul havia lhes imposto um juramento, dizendo: "Maldito seja todo o que comer antes do anoitecer, antes que eu tenha me vingado de meus inimigos! " Por isso ninguém tinha comido nada.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 25, 'O exército inteiro entrou num bosque, onde havia mel no chão.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 26, 'Eles viram o mel escorrendo, contudo ninguém comeu pois temiam o juramento.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 27, 'Jônatas, porém, não sabia do juramento que seu pai havia imposto ao exército de modo que estendeu a ponta da vara que tinha na mão e a molhou no favo de mel. Quando comeu seus olhos brilharam.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 28, 'Então um dos soldados lhe disse: "Seu pai impôs ao exército um juramento severo, dizendo: ‘Maldito seja todo o que comer hoje! ’ Por isso os homens estão exaustos".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 29, 'Jônatas disse: "Meu pai trouxe desgraça para nós. Veja como meus olhos brilham desde que provei um pouco deste mel.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 30, 'Como teria sido bem melhor se os homens tivessem comido hoje um pouco do que tomaram dos seus inimigos. A matança de filisteus não teria sido ainda maior? "', 3, CURRENT_TIMESTAMP, false),
(9, 14, 31, 'Naquele dia, depois de derrotarem os filisteus, desde Micmás até Aijalom, os israelitas estavam completamente exaustos.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 32, 'Eles então se lançaram sobre os despojos e pegaram ovelhas, bois e bezerros, e mataram-nos ali mesmo e comeram a carne com o sangue.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 33, 'E alguém disse a Saul: "Veja, os soldados estão pecando contra o Senhor, comendo carne com sangue". Ele disse: "Vocês foram infiéis. Rolem uma grande pedra até aqui.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 34, 'Saiam entre os soldados e digam-lhes: ‘Cada um traga a mim seu boi ou sua ovelha, abatam-nos e comam a carne aqui. Não pequem contra o Senhor comendo carne com sangue’ ". Assim, cada um levou seu boi naquela noite e ali os abateram.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 35, 'Então, Saul edificou um altar para o Senhor; foi a primeira vez que fez isso.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 36, 'Saul disse ainda: "Desçamos atrás dos filisteus, à noite, e os saqueemos até o amanhecer, e não deixemos vivo nem um só deles". Eles responderam: "Faze o que achares melhor". O sacerdote, porém, disse: "Consultemos aqui a Deus".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 37, 'Então Saul perguntou a Deus: "Devo perseguir os filisteus? Tu os entregarás nas mãos de Israel? " Mas naquele dia Deus não lhe respondeu.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 38, 'Disse então Saul: "Venham cá, todos vocês que são líderes do exército, e descubramos que pecado foi cometido hoje.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 39, 'Juro pelo nome do Senhor, o libertador de Israel, mesmo que seja meu filho Jônatas, ele morrerá". Mas ninguém disse uma só palavra.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 40, 'Então disse Saul a todos os israelitas: "Fiquem vocês de um lado; eu e meu filho Jônatas ficaremos do outro". E eles responderam: "Faze o que achares melhor".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 41, 'E Saul orou ao Senhor, ao Deus de Israel: "Dá-me a resposta certa". A sorte caiu em Jônatas e Saul, e os soldados saíram livres.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 42, 'Saul disse: "Tirem sortes entre mim e meu filho Jônatas". E Jônatas foi indicado.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 43, 'Então Saul disse a Jônatas: "Diga-me o que você fez". E Jônatas lhe contou: "Eu provei um pouco de mel com a ponta de minha vara. Estou pronto para morrer".', 3, CURRENT_TIMESTAMP, false),
(9, 14, 44, 'Saul disse: "Que Deus me castigue com todo rigor, caso você não morra, Jônatas! "', 3, CURRENT_TIMESTAMP, false),
(9, 14, 45, 'Os soldados, porém, disseram a Saul: "Será que Jônatas, que trouxe esta grande libertação para Israel deve morrer? Nunca! Juramos pelo nome do Senhor, nem um só cabelo de sua cabeça cairá ao chão, pois ele fez isso hoje com o auxílio de Deus". Então os homens resgataram Jônatas, e ele não foi morto.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 46, 'E Saul parou de perseguir os filisteus, e eles voltaram para sua própria terra.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 47, 'Quando Saul assumiu o reinado sobre Israel, lutou contra os seus inimigos em redor: moabitas, amonitas, edomitas, os reis de Zobá e os filisteus. Para qualquer lado que fosse, infligia-lhes castigo.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 48, 'Lutou corajosamente e derrotou os amalequitas, libertando Israel das mãos daqueles que os saqueavam.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 49, 'Os filhos de Saul foram Jônatas, Isvi e Malquisua. O nome de sua filha mais velha era Merabe, e o da mais nova era Mical.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 50, 'Sua mulher chamava-se Ainoã e era filha de Aimaás. O nome do comandante do exército de Saul era Abner, filho de Ner, tio de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 51, 'Quis, pai de Saul, e Ner, pai de Abner, eram filhos de Abiel.', 3, CURRENT_TIMESTAMP, false),
(9, 14, 52, 'Houve guerra acirrada contra os filisteus durante todo o reinado de Saul. Por isso sempre que Saul conhecia um homem forte e corajoso, alistava-o no seu exército.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 1, 'Samuel disse a Saul: "Eu sou aquele a quem o Senhor enviou para ungi-lo como rei de Israel, o povo dele; por isso escute agora a mensagem do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 2, 'Assim diz o Senhor dos Exércitos: ‘Castigarei os amalequitas pelo que fizeram a Israel, atacando-os quando saíam do Egito.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 3, 'Agora vão, ataquem os amalequitas e consagrem ao SENHOR para destruição tudo o que lhes pertence. Não os poupem; matem homens, mulheres, crianças, recém-nascidos, bois, ovelhas, camelos e jumentos’ ".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 4, 'Então convocou Saul os homens e os reuniu em Telaim: duzentos mil soldados de infantaria e dez mil homens de Judá.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 5, 'Saul foi à cidade de Amaleque e armou uma emboscada no vale.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 6, 'Então disse aos queneus: "Retirem-se, saiam do meio dos amalequitas para que eu não os destrua junto com eles; pois vocês foram bondosos com os israelitas, quando eles estavam vindo do Egito". Então os queneus saíram do meio dos amalequitas.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 7, 'E Saul atacou os amalequitas por todo caminho desde Havilá até Sur, a leste do Egito.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 8, 'Capturou vivo Agague, rei dos amalequitas, e exterminou o seu povo.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 9, 'Mas Saul e o exército pouparam Agague e o melhor das ovelhas e dos bois, os bezerros gordos e os cordeiros. Pouparam tudo que era bom, mas a tudo que era desprezível e inútil destruíram por completo.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 10, 'Então o Senhor falou a Samuel:', 3, CURRENT_TIMESTAMP, false),
(9, 15, 11, '"Arrependo-me de ter constituído a Saul rei, pois ele me abandonou e não seguiu as minhas instruções". Samuel ficou irado e clamou ao Senhor toda aquela noite.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 12, 'De madrugada Samuel foi ao encontro de Saul, mas lhe disseram: "Saul foi para o Carmelo, onde ergueu um monumento em sua própria honra e depois foi para Gilgal".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 13, 'Quando Samuel o encontrou, Saul disse: "O Senhor o abençoe! Segui as instruções do Senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 14, 'Samuel, porém, perguntou: "Então que balido de ovelhas é esse que ouço com meus próprios ouvidos? Que mugido de bois é esse que estou ouvindo? "', 3, CURRENT_TIMESTAMP, false),
(9, 15, 15, 'Respondeu Saul: "Os soldados os trouxeram dos amalequitas; eles pouparam o melhor das ovelhas e dos bois para o sacrificarem ao Senhor seu Deus, mas destruímos totalmente o restante".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 16, 'Samuel disse a Saul: "Fique quieto! Eu lhe direi o que o Senhor me falou esta noite". Respondeu Saul: "Diga-me".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 17, 'E Samuel disse: "Embora pequeno aos seus próprios olhos, você não se tornou o líder das tribos de Israel? O Senhor o ungiu como rei sobre Israel', 3, CURRENT_TIMESTAMP, false),
(9, 15, 18, 'e o enviou numa missão, ordenando: ‘Vá e destrua completamente aquele povo ímpio, os amalequitas; guerreie contra eles, até que os tenha eliminado’.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 19, 'Por que você não obedeceu ao Senhor? Por que se lançou sobre os despojos e fez o que o Senhor reprova? "', 3, CURRENT_TIMESTAMP, false),
(9, 15, 20, 'Disse Saul: "Mas eu obedeci ao Senhor! Cumpri a missão que o Senhor me designou. Trouxe Agague, o rei dos amalequitas, mas exterminei os amalequitas.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 21, 'Os soldados tomaram ovelhas e bois do despojo, o melhor do que estava consagrado a Deus para destruição, a fim de os sacrificarem ao Senhor seu Deus, em Gilgal".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 22, 'Samuel, porém, respondeu: "Acaso tem o Senhor tanto prazer em holocaustos e em sacrifícios quanto em que se obedeça à sua palavra? A obediência é melhor do que o sacrifício, e a submissão é melhor do que a gordura de carneiros.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 23, 'Pois a rebeldia é como o pecado da feitiçaria, e a arrogância como o mal da idolatria. Assim como você rejeitou a palavra do Senhor, ele o rejeitou como rei".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 24, '"Pequei", disse Saul. "Violei a ordem do Senhor e as instruções que você me deu. Tive medo dos soldados e lhes atendi.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 25, 'Agora eu lhe imploro, perdoe o meu pecado e volte comigo, para que eu adore o Senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 26, 'Samuel, contudo, lhe disse: "Não voltarei com você. Você rejeitou a palavra do Senhor, e o Senhor o rejeitou como rei de Israel! "', 3, CURRENT_TIMESTAMP, false),
(9, 15, 27, 'Quando Samuel se virou para sair, Saul agarrou-se à barra do manto dele, e o manto se rasgou.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 28, 'E Samuel lhe disse: "O Senhor rasgou de você, hoje, o reino de Israel, e o entregou a alguém que é melhor que você.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 29, 'Aquele que é a Glória de Israel não mente nem se arrepende, pois não é homem para se arrepender".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 30, 'Saul repetiu: "Pequei. Agora, honra-me perante as autoridades do meu povo e perante Israel; volte comigo, para que eu possa adorar o Senhor seu Deus".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 31, 'E assim Samuel voltou com ele, e Saul adorou o Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 32, 'Então Samuel disse: "Traga-me Agague, o rei dos amalequitas". Agague veio confiante, pensando: "Com certeza já passou a amargura da morte".', 3, CURRENT_TIMESTAMP, false),
(9, 15, 33, 'Samuel, porém, disse: "Assim como a sua espada deixou mulheres sem filhos, também sua mãe ficará sem o seu filho, entre as mulheres". E Samuel despedaçou Agague perante o Senhor, em Gilgal.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 34, 'Então Samuel partiu para Ramá, e Saul foi para sua casa, em Gibeá de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 15, 35, 'Nunca mais Samuel viu a Saul, até o dia de sua morte, embora se entristecesse por causa dele porque o Senhor arrependeu-se de ter estabelecido Saul como rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 1, 'O Senhor disse a Samuel: "Até quando você irá se entristecer por causa de Saul? Eu o rejeitei como rei de Israel. Encha um chifre com óleo e vá a Belém; eu o enviarei a Jessé. Escolhi um de seus filhos para ser rei".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 2, 'Samuel, porém, disse: "Como poderei ir? Saul saberá disto e me matará". O Senhor disse: "Leve um novilho com você e diga que foi sacrificar ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 3, 'Convide Jessé para o sacrifício, e eu lhe mostrarei o que fazer. Você irá ungir para mim aquele que eu indicar".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 4, 'Samuel fez o que o Senhor disse. Quando chegou a Belém, as autoridades da cidade foram encontrar-se com ele tremendo e perguntaram: "Você vem em paz? "', 3, CURRENT_TIMESTAMP, false),
(9, 16, 5, 'Respondeu Samuel: "Sim, venho em paz; vim sacrificar ao Senhor. Consagrem-se e venham ao sacrifício comigo". Então ele consagrou Jessé e os filhos dele e os convidou para o sacrifício.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 6, 'Quando chegaram, Samuel viu Eliabe e pensou: "Com certeza este aqui é o que o Senhor quer ungir".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 7, 'O Senhor, contudo, disse a Samuel: "Não considere a sua aparência nem sua altura, pois eu o rejeitei. O Senhor não vê como o homem: o homem vê a aparência, mas o Senhor vê o coração".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 8, 'Então Jessé chamou Abinadabe e o levou a Samuel. Ele, porém, disse: "O Senhor também não escolheu a este".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 9, 'Então Jessé levou Samá a Samuel, mas este disse: "Também não foi este que o Senhor escolheu".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 10, 'Jessé levou a Samuel sete de seus filhos, mas Samuel lhe disse: "O Senhor não escolheu nenhum destes".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 11, 'Então perguntou a Jessé: "Estes são todos os filhos que você tem? " Jessé respondeu: "Ainda tenho o caçula, mas ele está cuidando das ovelhas". Samuel disse: "Traga-o aqui; não nos sentaremos para comer até que ele chegue".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 12, 'Então Jessé mandou chamá-lo e ele veio. Ele era ruivo, de belos olhos e boa aparência. Então o Senhor disse a Samuel: "É este! Levante-se e unja-o".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 13, 'Samuel então apanhou o chifre cheio de óleo e o ungiu na presença de seus irmãos, e a partir daquele dia o Espírito do Senhor apoderou-se de Davi. E Samuel voltou para Ramá.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 14, 'O Espírito do Senhor se retirou de Saul, e um espírito maligno, vindo da parte do Senhor, o atormentava.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 15, 'Os funcionários de Saul lhe disseram: "Há um espírito maligno mandado por Deus te atormentando.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 16, 'Que nosso soberano mande estes seus servos procurar um homem que saiba tocar a harpa. Quando o espírito maligno se apoderar de ti, o homem tocará a harpa e tu te sentirás melhor".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 17, 'E Saul respondeu aos que o serviam: "Encontrem alguém que toque bem e o tragam até aqui".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 18, 'Um dos funcionários respondeu: "Conheço um dos filhos de Jessé, de Belém, que sabe tocar harpa. É um guerreiro valente, sabe falar bem, tem boa aparência e o Senhor está com ele".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 19, 'Então Saul mandou mensageiros a Jessé com a seguinte mensagem: "Envie-me seu filho Davi, que cuida das ovelhas".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 20, 'Jessé apanhou um jumento e o carregou de pães, uma vasilha de couro cheia de vinho e um cabrito e o enviou a Saul por meio de Davi, seu filho.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 21, 'Davi foi apresentar-se a Saul e passou a trabalhar para ele. Saul gostou muito dele, e Davi tornou-se seu escudeiro.', 3, CURRENT_TIMESTAMP, false),
(9, 16, 22, 'Então Saul enviou a seguinte mensagem a Jessé: "Deixe que Davi continue trabalhando para mim, pois estou satisfeito com ele".', 3, CURRENT_TIMESTAMP, false),
(9, 16, 23, 'E sempre que o espírito mandado por Deus se apoderava de Saul, Davi apanhava sua harpa e tocava. Então Saul sentia alívio e melhorava, e o espírito maligno o deixava.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 1, 'Os filisteus juntaram suas forças para a guerra e reuniram-se em Socó de Judá. E acamparam em Efes-Damim, entre Socó e Azeca.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 2, 'Saul e os israelitas reuniram-se e acamparam no vale de Elá, posicionando-se em linha de batalha para enfrentar os filisteus.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 3, 'Os filisteus ocuparam uma colina e os israelitas outra, estando o vale entre eles.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 4, 'Um guerreiro chamado Golias, que era de Gate, veio do acampamento filisteu. Tinha dois metros e noventa centímetros de altura.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 5, 'Ele usava um capacete de bronze e vestia uma couraça de escamas de bronze que pesava sessenta quilos;', 3, CURRENT_TIMESTAMP, false),
(9, 17, 6, 'nas pernas usava caneleiras de bronze e tinha um dardo de bronze pendurado nas costas.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 7, 'A haste de sua lança era parecida com uma lançadeira de tecelão, e sua ponta de ferro pesava sete quilos e duzentos gramas. Seu escudeiro ia à frente dele.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 8, 'Golias parou e gritou às tropas de Israel: "Por que vocês estão se posicionando para a batalha? Não sou eu um filisteu, e vocês os servos de Saul? Escolham um homem para lutar comigo.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 9, 'Se ele puder lutar e matar-me, nós seremos seus escravos; todavia, se eu o vencer e o matar, vocês serão nossos escravos e nos servirão".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 10, 'E acrescentou: "Eu desafio hoje as tropas de Israel! Mandem-me um homem para lutar sozinho comigo".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 11, 'Ao ouvirem as palavras do filisteu, Saul e todos os israelitas ficaram atônitos e apavorados.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 12, 'Davi era filho de um efrateu, de Belém de Judá, chamado Jessé. Este tinha oito filhos e já era idoso na época de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 13, 'Os três filhos mais velhos de Jessé tinham ido para a guerra com Saul: Eliabe, o mais velho, Abinadabe, o segundo e Samá, o terceiro.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 14, 'Davi era o caçula. Os três mais velhos seguiram Saul,', 3, CURRENT_TIMESTAMP, false),
(9, 17, 15, 'mas Davi ia ao acampamento de Saul e voltava para apascentar as ovelhas de seu pai, em Belém.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 16, 'Durante quarenta dias o filisteu aproximava-se, de manhã e de tarde, e tomava posição.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 17, 'Nessa ocasião Jessé disse a seu filho Davi: "Pegue uma arroba de grãos tostados e dez pães e leve-os rapidamente para seus irmãos no acampamento.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 18, 'Leve também estes dez queijos ao comandante da unidade deles. Veja como estão seus irmãos e traga-me alguma garantia de que estão bem.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 19, 'Eles estão com Saul e com todos os homens de Israel no vale de Elá, lutando contra os filisteus".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 20, 'Levantando-se de madrugada, Davi deixou o rebanho com outro pastor, pegou a carga e partiu, conforme Jessé lhe havia ordenado. Chegou ao acampamento na hora em que, com grito de batalha, o exército estava saindo para suas posições de combate.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 21, 'Israel e os filisteus estavam se posicionando em linha de batalha, frente a frente.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 22, 'Davi deixou o que havia trazido com o responsável pelos suprimentos, correu para a linha de batalha para saber como estavam seus irmãos.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 23, 'Enquanto conversava com eles, Golias, o guerreiro filisteu de Gate, avançou e lançou seu desafio habitual; e Davi o ouviu.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 24, 'Quando os israelitas viram o homem, todos fugiram com muito medo.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 25, 'Os israelitas diziam entre si: "Vocês viram aquele homem? Ele veio desafiar Israel. O rei dará grandes riquezas a quem o matar. Também lhe dará sua filha em casamento e isentará de impostos em Israel a família de seu pai".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 26, 'Davi perguntou aos soldados que estavam ali ao seu lado: "O que receberá o homem que matar esse filisteu e salvar a honra de Israel? Quem é esse filisteu incircunciso para desafiar os exércitos do Deus vivo? "', 3, CURRENT_TIMESTAMP, false),
(9, 17, 27, 'Repetiram a Davi o que haviam comentado e lhe disseram: "Isto é o que receberá o homem que matá-lo".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 28, 'Quando Eliabe, o irmão mais velho, ouviu Davi falando com os soldados, ficou muito irritado com ele e perguntou: "Por que você veio até aqui? Com quem deixou aquelas poucas ovelhas no deserto? Sei que você é presunçoso e como seu coração é mau; você veio só para ver a batalha".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 29, 'E disse Davi: "O que fiz agora? Será que não posso nem mesmo conversar? "', 3, CURRENT_TIMESTAMP, false),
(9, 17, 30, 'Ele então se virou para outro e perguntou a mesma coisa, e os homens responderam-lhe como antes.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 31, 'As palavras de Davi chegaram aos ouvidos de Saul, que o mandou chamar.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 32, 'Davi disse a Saul: "Ninguém deve ficar com o coração abatido por causa desse filisteu; teu servo irá e lutará com ele".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 33, 'Respondeu Saul: "Você não tem condições de lutar contra este filisteu; você é apenas um rapaz, e ele é um guerreiro desde a mocidade".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 34, 'Davi, entretanto, disse a Saul: "Teu servo toma conta das ovelhas de seu pai. Quando aparece um leão ou um urso e leva uma ovelha do rebanho,', 3, CURRENT_TIMESTAMP, false),
(9, 17, 35, 'eu vou atrás dele, atinjo-o com golpes e livro a ovelha de sua boca. Quando se vira contra mim, eu o pego pela juba, atinjo-o com golpes até matá-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 36, 'Teu servo é capaz de matar tanto um leão quanto um urso; esse filisteu incircunciso será como um deles, pois desafiou os exércitos do Deus vivo.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 37, 'O Senhor que me livrou das garras do leão e das garras do urso me livrará das mãos desse filisteu". Diante disso Saul disse a Davi: "Vá, e que o Senhor esteja com você".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 38, 'Então Saul vestiu Davi com sua própria túnica. Colocou-lhe uma armadura e um capacete de bronze na cabeça.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 39, 'Davi prendeu sua espada sobre a túnica e tentou andar, pois não estava acostumado àquilo. E disse a Saul: "Não consigo andar com isto, pois não estou acostumado". Assim tirou tudo aquilo,', 3, CURRENT_TIMESTAMP, false),
(9, 17, 40, 'e em seguida pegou seu cajado, escolheu no riacho cinco pedras lisas, colocou-as na bolsa, isto é, no seu alforje de pastor e, com sua atiradeira na mão, aproximou-se do filisteu.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 41, 'Enquanto isso, o filisteu, com seu escudeiro à frente, vinha se aproximando de Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 42, 'Olhou para Davi com desprezo, viu que era só um rapaz, ruivo e de boa aparência, e fez pouco caso dele.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 43, 'E disse a Davi: "Por acaso sou um cão para que você venha contra mim com pedaços de pau? " E o filisteu amaldiçoou Davi invocando seus deuses,', 3, CURRENT_TIMESTAMP, false),
(9, 17, 44, 'e disse: "Venha aqui, e darei sua carne às aves do céu e aos animais do campo! "', 3, CURRENT_TIMESTAMP, false),
(9, 17, 45, 'E Davi disse ao filisteu: "Você vem contra mim com espada, com lança e com dardo, mas eu vou contra você em nome do Senhor dos Exércitos, o Deus dos exércitos de Israel, a quem você desafiou.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 46, 'Hoje mesmo o Senhor o entregará nas minhas mãos, e eu o matarei e cortarei a sua cabeça. Hoje mesmo darei os cadáveres do exército filisteu às aves do céu e aos animais selvagens, e toda a terra saberá que há Deus em Israel.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 47, 'Todos que estão aqui saberão que não é por espada ou por lança que o Senhor concede vitória; pois a batalha é do Senhor, e ele entregará todos vocês em nossas mãos".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 48, 'Quando o filisteu começou a vir na direção de Davi, este correu depressa na direção da linha de batalha para enfrentá-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 49, 'Retirando uma pedra de seu alforje ele a arremessou com a atiradeira e atingiu o filisteu na testa, de tal modo que ela ficou encravada, e ele caiu com o rosto no chão.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 50, 'Assim Davi venceu o filisteu com uma atiradeira e uma pedra; sem espada na mão ele derrubou o filisteu e o matou.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 51, 'Davi correu e se pôs de pé sobre ele; e desembainhando a espada do filisteu acabou de matá-lo, cortando-lhe a cabeça com ela. Quando os filisteus viram que seu guerreiro estava morto, recuaram e fugiram.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 52, 'Então os homens de Israel e de Judá deram o grito de guerra e perseguiram os filisteus até a entrada de Gate, e até as portas de Ecrom. Cadáveres de filisteus ficaram espalhados ao longo da estrada de Saaraim até Gate e Ecrom.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 53, 'Quando os israelitas voltaram da perseguição aos filisteus, levaram tudo o que havia no acampamento deles.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 54, 'Davi pegou a cabeça do filisteu, levou-a para Jerusalém e guardou as armas do filisteu em sua própria tenda.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 55, 'Quando Saul viu Davi avançando para enfrentar o filisteu, perguntou a Abner, o comandante do exército: "Abner, quem é o pai daquele rapaz? " Abner respondeu: "Juro por tua vida, ó rei, que eu não sei".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 56, 'E o rei ordenou-lhe: "Descubra quem é o pai dele".', 3, CURRENT_TIMESTAMP, false),
(9, 17, 57, 'Logo que Davi voltou, depois de ter matado o filisteu, Abner levou-o perante Saul. Davi ainda segurava a cabeça de Golias.', 3, CURRENT_TIMESTAMP, false),
(9, 17, 58, 'E Saul lhe perguntou: "De quem você é filho, meu jovem? " Respondeu Davi: "Sou filho de teu servo Jessé, de Belém".', 3, CURRENT_TIMESTAMP, false),
(9, 18, 1, 'Depois dessa conversa de Davi com Saul, surgiu tão grande amizade entre Jônatas e Davi que Jônatas tornou-se o seu melhor amigo.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 2, 'Daquele dia em diante, Saul manteve Davi consigo e não o deixou voltar à casa de seu pai.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 3, 'E Jônatas fez um acordo de amizade com Davi, pois se tornara o melhor amigo de Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 4, 'Jônatas tirou o manto que estava vestindo e deu-o a Davi, junto com sua túnica, e até sua espada, seu arco e seu cinturão.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 5, 'Tudo que Saul lhe ordenava fazer, Davi fazia com tanta habilidade que Saul lhe deu um posto elevado no exército. Isto agradou a todo o povo, bem como aos conselheiros de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 6, 'Quando os soldados voltavam para casa, depois de Davi ter matado o filisteu, as mulheres saíram de todas as cidades de Israel ao encontro do rei Saul com cânticos e danças, com tamborins, com músicas alegres e instrumentos de três cordas.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 7, 'Enquanto dançavam, as mulheres cantavam: "Saul matou milhares, e Davi, dezenas de milhares".', 3, CURRENT_TIMESTAMP, false),
(9, 18, 8, 'Saul ficou muito irritado, com esse refrão e, aborrecido disse: "Atribuíram a Davi dezenas de milhares, mas a mim apenas milhares. O que mais lhe falta senão o reino? "', 3, CURRENT_TIMESTAMP, false),
(9, 18, 9, 'Daí em diante Saul olhava com inveja para Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 10, 'No dia seguinte, um espírito maligno mandado por Deus apoderou-se de Saul e ele entrou em transe profético em sua casa, enquanto Davi tocava harpa, como costumava fazer. Saul estava com uma lança na mão', 3, CURRENT_TIMESTAMP, false),
(9, 18, 11, 'e a atirou, dizendo: "Encravarei Davi na parede". Mas Davi desviou-se duas vezes.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 12, 'Saul tinha medo de Davi porque o Senhor o havia abandonado e agora estava com Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 13, 'Então afastou Davi de sua presença e deu-lhe o comando de uma tropa de mil soldados, e Davi a conduzia em suas campanhas.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 14, 'Ele tinha êxito em tudo o que fazia, pois o Senhor estava com ele.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 15, 'Quando Saul como ele tinha habilidade, teve muito medo dele.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 16, 'Todo Israel e Judá, porém, gostava de Davi, pois ele os conduzia em suas batalhas.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 17, 'Saul disse a Davi: "Aqui está a minha filha mais velha, Merabe. Eu a darei em casamento a você; apenas sirva-me com bravura e lute as batalhas do Senhor". Pois Saul pensou: "Não o matarei. Deixo isso para os filisteus! "', 3, CURRENT_TIMESTAMP, false),
(9, 18, 18, 'Mas Davi disse a Saul: "Quem sou eu, e o que é minha família ou o clã de meu pai em Israel para que eu me torne genro do rei? "', 3, CURRENT_TIMESTAMP, false),
(9, 18, 19, 'Por isso, quando chegou a época de Merabe, a filha de Saul, ser dada em casamento a Davi, ela foi dada a Adriel, de Meolá.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 20, 'Mical, a outra filha de Saul, gostava de Davi. Quando disseram isto a Saul, ele ficou contente e pensou:', 3, CURRENT_TIMESTAMP, false),
(9, 18, 21, '"Eu a darei a ele, para que lhe sirva de armadilha, fazendo-o cair nas mãos dos filisteus". Então Saul disse a Davi: "Hoje você tem uma segunda oportunidade de tornar-se meu genro".', 3, CURRENT_TIMESTAMP, false),
(9, 18, 22, 'Então Saul ordenou aos seus conselheiros que falassem em particular com Davi, dizendo: "O rei está satisfeito com você, e todos os seus conselheiros o estimam. Torne-se, agora, seu genro".', 3, CURRENT_TIMESTAMP, false),
(9, 18, 23, 'Quando falaram com Davi, ele disse: "Vocês acham que tornar-se genro do rei é fácil? Sou homem pobre e sem recursos".', 3, CURRENT_TIMESTAMP, false),
(9, 18, 24, 'Quando os conselheiros de Saul lhe contaram o que Davi tinha dito,', 3, CURRENT_TIMESTAMP, false),
(9, 18, 25, 'Saul ordenou que dissessem a Davi: "O rei não quer outro preço pela noiva além de cem prepúcios de filisteus, para vingar-se de seus inimigos". O plano de Saul era que Davi fosse morto pelos filisteus.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 26, 'Quando os conselheiros falaram novamente com Davi, ele gostou da idéia de tornar-se genro do rei. Por isso, antes de terminar o prazo estipulado,', 3, CURRENT_TIMESTAMP, false),
(9, 18, 27, 'Davi e seus soldados saíram e mataram duzentos filisteus. Ele trouxe os prepúcios e apresentou-os ao rei para que se tornasse seu genro. Então Saul lhe deu em casamento sua filha Mical.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 28, 'Quando Saul viu claramente que o Senhor estava com Davi e que sua filha Mical o amava,', 3, CURRENT_TIMESTAMP, false),
(9, 18, 29, 'temeu-o ainda mais e continuou seu inimigo pelo resto de sua vida.', 3, CURRENT_TIMESTAMP, false),
(9, 18, 30, 'Os comandantes filisteus continuaram saindo para a batalha, e, todas as vezes que o faziam, Davi tinha mais habilidade do que os outros oficiais de Saul, e ele tornou-se ainda mais famoso.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 1, 'Saul falou a seu filho Jônatas e a todos os seus conselheiros sobre a sua intenção de matar Davi. Jônatas, porém, gostava muito de Davi', 3, CURRENT_TIMESTAMP, false),
(9, 19, 2, 'e o alertou: "Meu pai, está procurando uma oportunidade para matá-lo. Tenha cuidado amanhã cedo. Vá para um esconderijo e fique por lá.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 3, 'Sairei e ficarei com meu pai no campo onde você estiver. Falarei a ele sobre você e, depois, contarei a você o que eu descobrir".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 4, 'Jônatas falou bem de Davi a Saul, seu pai, e lhe disse: "Que o rei não faça mal a seu servo Davi; ele não lhe fez mal nenhum. Ao contrário, o que ele fez trouxe grandes benefícios ao rei.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 5, 'Ele arriscou a vida quando matou o filisteu. O Senhor trouxe grande vitória para todo o Israel; tu mesmo viste tudo e ficaste contente. Por que, então, farias mal a um inocente como Davi, matando-o sem motivo? "', 3, CURRENT_TIMESTAMP, false),
(9, 19, 6, 'Saul atendeu a Jônatas e fez este juramento: "Juro pelo nome do Senhor que Davi não será morto".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 7, 'Então Jônatas chamou a Davi e lhe contou a conversa toda. Levou-o até Saul, e Davi voltou a servir a Saul como anteriormente.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 8, 'E houve guerra outra vez, e Davi foi lutar com os filisteus. Ele lhes impôs uma grande derrota e eles fugiram dele.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 9, 'Mas um espírito maligno mandado pelo Senhor apoderou-se de Saul quando ele estava sentado em sua casa, com sua lança na mão. Enquanto Davi estava tocando harpa,', 3, CURRENT_TIMESTAMP, false),
(9, 19, 10, 'Saul tentou encravá-lo na parede com sua lança, mas Davi desviou-se e a lança encravou na parede. E Davi conseguiu escapar. Naquela mesma noite,', 3, CURRENT_TIMESTAMP, false),
(9, 19, 11, 'Saul enviou alguns homens à casa de Davi para vigiá-lo e matá-lo de manhã; mas Mical, a mulher de Davi, o alertou: "Se você não fugir esta noite para salvar sua vida, amanhã estará morto".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 12, 'Então Mical fez Davi descer por uma janela, e ele fugiu.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 13, 'Depois Mical pegou um ídolo do clã e o deitou na cama, pôs uma almofada de pêlos de cabra na cabeceira e o cobriu com um manto.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 14, 'Quando chegaram os homens que Saul tinha enviado para prenderem Davi, Mical disse: "Ele está doente".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 15, 'Então Saul enviou os homens de volta para verem Davi dizendo: "Tragam-no até aqui em sua cama para que eu o mate".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 16, 'Quando, porém, os homens entraram, o ídolo do clã estava na cama, e na cabeceira havia uma almofada de pêlos de cabra.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 17, 'Saul disse a Mical: "Por que você me enganou desse modo e deixou que o meu inimigo escapasse? " Ela lhe respondeu: "Ele me disse que o deixasse, se não me mataria? "', 3, CURRENT_TIMESTAMP, false),
(9, 19, 18, 'Depois que fugiu, Davi foi falar com Samuel em Ramá, e contou-lhe tudo o que Saul lhe havia feito. Então ele e Samuel foram a Naiote e ficaram lá.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 19, 'E Saul foi informado: "Davi está em Naiote, em Ramá".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 20, 'Então Saul enviou alguns homens para capturá-lo. Todavia, quando viram um grupo de profetas profetizando, dirigidos por Samuel, o Espírito de Deus apoderou-se dos mensageiros de Saul e eles também entraram em transe profético.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 21, 'Contaram isto a Saul, e ele enviou mais mensageiros, e estes também entraram em transe profético. Depois mandou um terceiro grupo e eles também entraram em transe profético.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 22, 'Finalmente ele mesmo foi para Ramá. Chegando à grande cisterna do lugar chamado Seco, perguntou onde estavam Samuel e Davi. E lhe responderam: "Em Naiote de Ramá".', 3, CURRENT_TIMESTAMP, false),
(9, 19, 23, 'Então Saul foi para lá. Entretanto, o Espírito de Deus apoderou-se dele; e ele foi pelo caminho em transe profético, até chegar a Naiote.', 3, CURRENT_TIMESTAMP, false),
(9, 19, 24, 'E despindo-se de suas roupas, também profetizou em transe na presença de Samuel. Ele ficou deitado nu todo aquele dia e toda aquela noite. Por isso, o povo diz: "Está Saul também entre os profetas? "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 1, 'Então Davi fugiu de Naiote, em Ramá, foi falar com Jônatas e perguntou: "O que foi que eu fiz? Qual é o meu crime? Qual foi o pecado que cometi contra seu pai para que ele queira tirar minha vida? "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 2, '"Nem pense nisso", respondeu Jônatas, "você não será morto! Meu pai não fará coisa alguma sem antes me avisar, seja importante ou não. Por que ele iria esconder isso de mim? Não é nada disso! "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 3, 'Davi, contudo, fez um juramento e disse: "Seu pai sabe muito bem que eu conto com a sua simpatia, e pensou: ‘Jônatas não deve saber disso para não se entristecer’. No entanto, eu juro pelo nome do Senhor e por sua vida que estou a um passo da morte".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 4, 'Jônatas disse a Davi: "Eu farei o que você achar necessário".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 5, 'Então disse Davi: "Amanhã é a festa da lua nova, e devo jantar com o rei; mas deixe-me ir esconder-me no campo até o final da tarde de depois de amanhã.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 6, 'Se seu pai sentir minha falta, diga-lhe: ‘Davi insistiu comigo para que lhe permitisse ir a Belém, sua cidade natal, por causa do sacrifício anual que está sendo feito lá por todo o seu clã’.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 7, 'Se ele disser: ‘Está bem’, então seu servo estará seguro. Se ele, porém, ficar muito irado, você pode estar certo de que está decidido a me fazer mal.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 8, 'Mas seja leal a seu servo, porque fizemos um acordo perante o Senhor. Se sou culpado, então mate-me você mesmo! Por que entregar-me a seu pai? "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 9, 'Disse Jônatas: "Nem pense nisso! Se eu tiver a menor suspeita de que meu pai está decidido a matá-lo, certamente eu o avisarei! "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 10, 'Davi perguntou: "Quem irá contar-me, se seu pai lhe responder asperamente? "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 11, 'Jônatas disse: "Venha, vamos ao campo". Eles foram', 3, CURRENT_TIMESTAMP, false),
(9, 20, 12, 'e Jônatas disse a Davi: "Pelo Senhor, o Deus de Israel, prometo que sondarei meu pai, a esta hora, depois de amanhã! Saberei se as suas intenções são boas ou não para com você, e lhe mandarei avisar.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 13, 'E, se meu pai quiser fazer-lhe mal, que o Senhor me castigue com todo rigor, se eu não lhe informar e não deixá-lo ir em segurança. O Senhor esteja com você assim como esteve com meu pai.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 14, 'Se eu continuar vivo, mostre a lealdade do Senhor a mim; mas se eu morrer,', 3, CURRENT_TIMESTAMP, false),
(9, 20, 15, 'jamais deixe de mostrar a sua lealdade para com a minha família, inclusive quando o Senhor eliminar da face da terra todos os inimigos de Davi".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 16, 'Assim Jônatas fez uma aliança com a família de Davi, dizendo: "Que o Senhor chame os inimigos de Davi para prestarem contas".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 17, 'E Jônatas fez Davi reafirmar seu juramento, por causa de sua amizade por ele, pois ele havia se tornado seu amigo leal.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 18, 'Então Jônatas disse a Davi: "Amanhã é a festa da lua nova. Vão sentir sua falta, pois sua cadeira estará vazia.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 19, 'Depois de amanhã, vá ao lugar onde você se escondeu quando tudo isto começou, e espere junto à pedra de Ezel.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 20, 'Atirarei três flechas para o lado dela, como se estivesse atirando num alvo.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 21, 'Então mandarei um menino procurar as flechas. Se eu gritar para ele: ‘As flechas estão mais para cá, traga-as aqui’, você poderá vir, pois, juro pelo nome do Senhor que você estará seguro; não haverá perigo algum.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 22, 'Mas, se eu gritar para ele: ‘Olhe, as flechas estão mais para lá’, vá embora, pois o Senhor o manda ir.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 23, 'Quanto ao nosso acordo, o Senhor é testemunha entre mim e você para sempre".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 24, 'Então Davi escondeu-se no campo. Quando chegou a festa da lua nova, o rei sentou-se à mesa.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 25, 'Ele se assentou no lugar de costume, junto à parede, em frente de Jônatas, e Abner sentou-se ao lado de Saul, mas o lugar de Davi ficou vazio.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 26, 'Saul não disse nada naquele dia, pois pensou: "Algo deve ter acontecido a Davi, deixando-o cerimonialmente impuro. Com certeza ele está impuro".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 27, 'No dia seguinte, o segundo dia da festa da lua nova, o lugar de Davi continuou vazio. Então Saul perguntou a seu filho Jônatas: "Por que o filho de Jessé não veio para a refeição, nem ontem nem hoje? "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 28, 'Jônatas respondeu: "Davi me pediu, com insistência, permissão para ir a Belém,', 3, CURRENT_TIMESTAMP, false),
(9, 20, 29, 'dizendo: ‘Deixe-me ir, pois nossa família oferecerá um sacrifício na cidade, e meu irmão ordenou que eu estivesse lá. Se conto com a sua simpatia, deixe-me ir ver meus irmãos’. Por isso ele não veio à mesa do rei".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 30, 'A ira de Saul se acendeu contra Jônatas, e ele lhe disse: "Filho de uma mulher perversa e rebelde! Será que eu não sei que você tem apoiado o filho de Jessé para sua própria vergonha e para vergonha daquela que o deu à luz?', 3, CURRENT_TIMESTAMP, false),
(9, 20, 31, 'Enquanto o filho de Jessé viver, nem você nem seu reino serão estabelecidos. Agora mande chamá-lo e traga-o a mim, pois ele deve morrer! "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 32, 'Jônatas perguntou a seu pai: "Por que ele deve morrer? O que ele fez? "', 3, CURRENT_TIMESTAMP, false),
(9, 20, 33, 'Então Saul atirou sua lança contra Jônatas para matá-lo. E assim Jônatas percebeu que seu pai estava decidido a matar Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 34, 'Jônatas levantou-se da mesa muito irado; naquele segundo dia da festa da lua nova ele não comeu, pois estava triste porque seu pai havia humilhado a Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 35, 'Pela manhã, Jônatas saiu ao campo para encontrar Davi. Levava consigo um menino', 3, CURRENT_TIMESTAMP, false),
(9, 20, 36, 'e lhe disse: "Corra e ache as flechas que eu atirar". O menino correu e Jônatas atirou uma flecha para além dele.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 37, 'Quando o menino chegou ao lugar onde a flecha havia caído, Jônatas gritou: "A flecha não está mais para lá?', 3, CURRENT_TIMESTAMP, false),
(9, 20, 38, 'Vamos! Rápido! Não pare! " O menino apanhou a flecha e voltou', 3, CURRENT_TIMESTAMP, false),
(9, 20, 39, 'sem saber de nada, pois somente Jônatas e Davi sabiam do que tinham combinado.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 40, 'Então Jônatas deu suas armas ao menino e disse: "Vá, leve-as de volta à cidade".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 41, 'Depois que o menino se foi, Davi saiu do lado sul da pedra e inclinou-se três vezes perante Jônatas, com o rosto no chão. Então despediram-se beijando um ao outro e chorando; Davi chorou ainda mais do que Jônatas.', 3, CURRENT_TIMESTAMP, false),
(9, 20, 42, 'E ele disse a Davi: "Vá em paz, pois temos jurado um ao outro, em nome do Senhor, dizendo: ‘O Senhor para sempre é testemunha entre nós e entre os nossos descendentes’ ".', 3, CURRENT_TIMESTAMP, false),
(9, 20, 43, 'Então Davi partiu, e Jônatas voltou à cidade.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 1, 'Davi foi falar com o sacerdote Aimeleque, em Nobe. Aimeleque tremia quando se encontrou com ele, e perguntou: "Por que você está sozinho? Ninguém veio com você? "', 3, CURRENT_TIMESTAMP, false),
(9, 21, 2, 'Respondeu Davi: "O rei me encarregou de uma certa missão e me disse: ‘Ninguém deve saber coisa alguma sobre sua missão e sobre as suas instruções’. E eu ordenei aos meus soldados que se encontrassem comigo num certo lugar.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 3, 'Agora, então, o que você pode oferecer-me? Dê-me cinco pães ou algo que tiver".', 3, CURRENT_TIMESTAMP, false),
(9, 21, 4, 'O sacerdote, contudo, respondeu a Davi: "Não tenho pão comum; somente pão consagrado; se os soldados não tiveram relações com mulheres recentemente podem comê-lo".', 3, CURRENT_TIMESTAMP, false),
(9, 21, 5, 'Davi respondeu: "Certamente que não, conforme o nosso costume sempre que saio em campanha. Não tocamos em mulher. Esses homens mantém o corpo puro mesmo em missões comuns. Quanto mais hoje! "', 3, CURRENT_TIMESTAMP, false),
(9, 21, 6, 'Então, o sacerdote lhe deu os pães consagrados, visto que não havia outro além do pão da Presença, que era retirado de diante do Senhor e substituído por pão quente no dia em que era tirado.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 7, 'Aconteceu que um dos servos de Saul estava ali naquele dia, cumprindo seus deveres diante do Senhor; era o edomita Doegue, chefe dos pastores de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 8, 'Davi perguntou a Aimeleque: "Você tem uma lança ou uma espada aqui? Não trouxe minha espada nem qualquer outra arma, pois o rei exigiu urgência".', 3, CURRENT_TIMESTAMP, false),
(9, 21, 9, 'O sacerdote respondeu: "A espada de Golias, o filisteu que você matou no vale de Elá, está enrolada num pano atrás do colete sacerdotal. Se quiser, pegue-a; não há nenhuma outra espada". Davi disse: "Não há outra melhor; dê-me essa espada".', 3, CURRENT_TIMESTAMP, false),
(9, 21, 10, 'Naquele dia, Davi fugiu de Saul e foi procurar Aquis, rei de Gate.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 11, 'Todavia os conselheiros de Aquis lhe disseram: "Não é este Davi, o rei da terra de Israel? Não é aquele sobre quem cantavam em suas danças: ‘Saul abateu seus milhares, e Davi suas dezenas de milhares’? "', 3, CURRENT_TIMESTAMP, false),
(9, 21, 12, 'Davi levou a sério aquelas palavras e ficou com muito medo de Aquis, rei de Gate.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 13, 'Por isso, na presença deles ele fingiu estar louco; enquanto esteve com eles, agiu como um louco, riscando as portas da cidade e deixando escorrer saliva pela barba.', 3, CURRENT_TIMESTAMP, false),
(9, 21, 14, 'Aquis disse a seus conselheiros: "Vejam este homem! Ele está louco! Por que trazê-lo aqui?', 3, CURRENT_TIMESTAMP, false),
(9, 21, 15, 'Será que me faltam loucos para que vocês o tragam para agir como doido na minha frente? O que ele veio fazer no meu palácio? "', 3, CURRENT_TIMESTAMP, false),
(9, 22, 1, 'Davi fugiu da cidade de Gate e foi para a caverna de Adulão. Quando seus irmãos e a família de seu pai souberam disso, foram até lá para encontrá-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 2, 'Também juntaram-se a ele todos os que estavam em dificuldades, os endividados e os descontentes; e ele se tornou o líder deles. Havia cerca de quatrocentos homens com ele.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 3, 'De lá Davi foi para Mispá, em Moabe, e disse ao rei de Moabe: "Posso deixar meu pai e minha mãe virem para cá e ficarem contigo até que eu saiba o que Deus fará comigo? "', 3, CURRENT_TIMESTAMP, false),
(9, 22, 4, 'E assim ele os deixou com o rei de Moabe, e lá eles ficaram enquanto Davi permaneceu na fortaleza.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 5, 'Contudo, o profeta Gade disse a Davi: "Não fique na fortaleza. Vá para Judá". Então Davi foi para a floresta de Herete.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 6, 'Saul ficou sabendo que Davi e seus homens tinham sido descobertos. Saul estava sentado, com a lança na mão, debaixo da tamargueira, na colina de Gibeá, com todos os seus oficiais ao redor,', 3, CURRENT_TIMESTAMP, false),
(9, 22, 7, 'e ele lhes disse: "Ouçam, homens de Benjamim! Será que o filho de Jessé lhes dará a todos vocês terras e vinhas? Será que ele os fará todos comandantes de mil e comandantes de cem?', 3, CURRENT_TIMESTAMP, false),
(9, 22, 8, 'É por isso que todos vocês têm conspirado contra mim? Ninguém me informa quando meu filho faz acordo com o filho de Jessé. Nenhum de vocês se preocupa comigo nem me avisa que meu filho incitou meu servo a ficar à minha espreita, como ele hoje faz".', 3, CURRENT_TIMESTAMP, false),
(9, 22, 9, 'Entretanto, Doegue, o edomita, que estava com os oficiais de Saul, disse: "Vi o filho de Jessé chegar em Nobe e encontrar-se com Aimeleque, filho de Aitube.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 10, 'Aimeleque consultou o Senhor em favor dele; também lhe deu provisões e a espada de Golias, o filisteu".', 3, CURRENT_TIMESTAMP, false),
(9, 22, 11, 'Então o rei mandou chamar o sacerdote Aimeleque, filho de Aitube, e toda a família de seu pai, que eram os sacerdotes em Nobe, e todos foram falar com o rei.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 12, 'E Saul disse: "Ouça agora, filho de Aitube". Ele respondeu: "Sim, meu senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 22, 13, 'Saul lhe disse: "Por que vocês conspiraram contra mim, você e o filho de Jessé? Porque você lhe deu comida e espada, e consultou a Deus em favor dele, para que se rebelasse contra mim e me armasse cilada, como ele está fazendo? "', 3, CURRENT_TIMESTAMP, false),
(9, 22, 14, 'Aimeleque respondeu ao rei: "Quem dentre todos os teus oficiais é tão leal quanto Davi, o genro do rei, capitão de sua guarda pessoal e altamente respeitado em sua casa?', 3, CURRENT_TIMESTAMP, false),
(9, 22, 15, 'Será que foi essa a primeira vez que consultei a Deus em favor dele? Certamente que não! Que o rei não acuse a mim, seu servo, nem qualquer um da família de meu pai, pois seu servo nada sabe acerca do que está acontecendo".', 3, CURRENT_TIMESTAMP, false),
(9, 22, 16, 'O rei, porém, disse: "Com certeza você será morto, Aimeleque, você e toda a família de seu pai".', 3, CURRENT_TIMESTAMP, false),
(9, 22, 17, 'Então o rei ordenou aos guardas que estavam ao seu lado: "Matem os sacerdotes do Senhor, pois eles também apóiam Davi. Sabiam que ele estava fugindo, mas nada me informaram". Contudo, os oficiais do rei recusaram erguer as mãos para matar os sacerdotes do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 18, 'Então o rei ordenou a Doegue: "Mate os sacerdotes", e ele os matou. E naquele dia, matou oitenta e cinco homens que vestiam túnica de linho.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 19, 'Além disso, Saul mandou matar os habitantes de Nobe, a cidade dos sacerdotes: homens, mulheres, crianças, recém-nascidos, bois, jumentos e ovelhas.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 20, 'Entretanto, Abiatar, filho de Aimeleque e neto de Aitube, escapou e fugiu para juntar-se a Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 21, 'E contou a Davi que Saul havia matado os sacerdotes do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 22, 'Então Davi disse a Abiatar: "Naquele dia, quando o edomita Doegue estava ali, eu sabia que ele não deixaria de informar a Saul. Sou responsável pela morte de toda a família de seu pai.', 3, CURRENT_TIMESTAMP, false),
(9, 22, 23, 'Fique comigo, não tenha medo; o homem que está atrás de sua vida também está atrás da minha. Mas você estará a salvo comigo".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 1, 'Quando disseram a Davi que os filisteus estavam atacando a cidade de Queila e saqueando as eiras,', 3, CURRENT_TIMESTAMP, false),
(9, 23, 2, 'ele perguntou ao Senhor: "Devo atacar esses filisteus? " O Senhor lhe respondeu: "Vá, ataque os filisteus e liberte Queila".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 3, 'Os soldados de Davi, porém, lhe disseram: "Aqui em Judá estamos com medo. Quanto mais, então, se formos a Queila lutar contra as tropas dos filisteus! "', 3, CURRENT_TIMESTAMP, false),
(9, 23, 4, 'Davi consultou o Senhor novamente. "Levante-se", disse o Senhor, "vá à cidade de Queila, pois estou entregando os filisteus em suas mãos".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 5, 'Então Davi e seus homens foram a Queila, combateram os filisteus e se apoderaram de seus rebanhos, impondo-lhes grande derrota e libertando o povo de Queila.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 6, 'Ora, Abiatar, filho de Aimeleque, tinha levado o colete sacerdotal, quando fugiu para se juntar a Davi, em Queila.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 7, 'Foi dito a Saul que Davi tinha ido a Queila, e ele disse: "Deus o entregou nas minhas mãos, pois Davi se aprisionou ao entrar numa cidade com portas e trancas".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 8, 'E Saul convocou todo o seu exército para a batalha, para irem a Queila e cercarem Davi e os homens que o seguiam.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 9, 'Quando Davi soube que Saul tramava atacá-lo, disse a Abiatar: "Traga o colete sacerdotal".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 10, 'Então orou: "Ó Senhor, Deus de Israel, este teu servo ouviu claramente que Saul planeja vir a Queila e destruir a cidade por causa dele.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 11, 'Será que os cidadãos de Queila me entregarão a ele? Saul virá de fato, conforme teu servo ouviu? Ó Senhor, Deus de Israel, responde". E o Senhor disse: "Ele virá".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 12, 'E Davi, novamente, perguntou: "Será que os cidadãos de Queila entregarão a mim e a meus soldados a Saul? " E o Senhor respondeu: "Entregarão".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 13, 'Então Davi e seus soldados, que eram cerca de seiscentos, partiram de Queila, e ficaram andando sem direção definida. Quando informaram a Saul que Davi tinha fugido de Queila, ele interrompeu a marcha.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 14, 'Davi permaneceu nas fortalezas do deserto e nas colinas do deserto de Zife. Dia após dia, Saul o procurava, mas Deus não entregou Davi em suas mãos.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 15, 'Quando Davi estava em Horesa, no deserto de Zife, soube que Saul tinha saído para matá-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 16, 'E Jônatas, filho de Saul, foi falar com ele, em Horesa, e o ajudou a encontrar forças em Deus.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 17, '"Não tenha medo", disse ele, "meu pai não porá as mãos em você. Você será rei de Israel, e eu lhe serei o segundo em comando. Até meu pai sabe disso. "', 3, CURRENT_TIMESTAMP, false),
(9, 23, 18, 'Os dois fizeram um acordo perante o Senhor. Então, Jônatas foi para casa, mas Davi ficou em Horesa.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 19, 'Alguns zifeus foram informar a Saul, em Gibeá: "Davi está se escondendo entre nós nas fortalezas de Horesa, na colina de Haquilá, ao sul do Deserto de Jesimom.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 20, 'Agora, ó rei, vá quando quiser, e nós seremos responsáveis por entregá-lo em suas mãos".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 21, 'Saul respondeu: "O Senhor os abençoe por terem compaixão de mim.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 22, 'Vão e façam mais preparativos. Descubram aonde Davi geralmente vai e quem o tem visto ali. Dizem-me que ele é muito astuto.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 23, 'Descubram todos os esconderijos dele e voltem aqui com informações exatas. Então irei com vocês; se ele estiver na região, eu o procurarei entre todos os clãs de Judá".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 24, 'E eles voltaram para Zife, à frente de Saul. Davi e seus soldados estavam no deserto de Maom, na Arabá, ao sul do deserto de Jesimom.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 25, 'Saul e seus soldados começaram a busca, e, ao ser informado disso, Davi desceu à rocha e permaneceu no deserto de Maom. Sabendo disso, Saul foi para lá em perseguição a Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 26, 'Saul ia por um lado da montanha, e Davi e seus soldados pelo outro, fugiam depressa para escapar de Saul. Quando Saul e suas tropas estavam cercando Davi e seus soldados para capturá-los,', 3, CURRENT_TIMESTAMP, false),
(9, 23, 27, 'um mensageiro veio dizer a Saul: "Venha depressa! Os filisteus estão atacando Israel".', 3, CURRENT_TIMESTAMP, false),
(9, 23, 28, 'Então Saul interrompeu a perseguição a Davi e foi enfrentar os filisteus. Por isso chamam esse lugar Selá-Hamalecote.', 3, CURRENT_TIMESTAMP, false),
(9, 23, 29, 'E Davi saiu daquele lugar e foi viver nas fortalezas de En-Gedi.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 1, 'Saul voltou da luta contra os filisteus e disseram-lhe que Davi estava no deserto de En-Gedi.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 2, 'Então Saul tomou três mil de seus melhores soldados de todo o Israel e partiu à procura de Davi e seus homens perto dos rochedos dos Bodes Selvagens.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 3, 'Ele foi aos currais de ovelhas que ficavam junto ao caminho; havia ali uma caverna, e Saul entrou nela para fazer suas necessidades. Davi e seus soldados estavam bem no fundo da caverna.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 4, 'Eles disseram: "Este é o dia sobre o qual o Senhor lhe falou: ‘Entregarei nas suas mãos seu inimigo para que você faça com ele o que quiser’ ". Então Davi foi com muito cuidado e cortou uma ponta do manto de Saul, sem que este percebesse.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 5, 'Mas Davi sentiu bater-lhe o coração de remorso por ele ter cortado uma ponta do manto de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 6, 'E então disse a seus soldados: "Que o SENHOR me livre de fazer tal coisa a meu senhor, de erguer a mão contra ele; pois é o ungido do Senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 24, 7, 'Com essas palavras Davi repreendeu os soldados e não permitiu que atacassem Saul. E este saiu da caverna e seguiu seu caminho.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 8, 'Então Davi saiu da caverna e gritou para Saul: "Ó rei, meu senhor! " Quando Saul olhou para trás, Davi inclinou-se, rosto em terra.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 9, 'E depois disse: "Por que o rei dá atenção aos que dizem que eu pretendo lhe fazer mal?', 3, CURRENT_TIMESTAMP, false),
(9, 24, 10, 'Hoje o rei pode ver com os próprios olhos como o Senhor o entregou em minhas mãos na caverna. Alguns insistiram que eu o matasse, mas eu o poupei, pois disse: ‘Não erguerei a mão contra meu senhor, pois ele é o ungido do Senhor’.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 11, 'Olha, meu pai, olha para este pedaço de teu manto em minha mão! Cortei a ponta de teu manto, mas não o matei. Agora entende e reconhece que não sou culpado de fazer o mal ou de rebelar-me. Não lhe fiz mal algum, embora estejas à minha procura para tirar-me a vida.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 12, 'O Senhor julgue entre mim e ti. Vingue ele os males que tens feito contra mim, mas não levantarei a mão contra ti.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 13, 'Como diz o provérbio antigo: ‘Dos ímpios vêm coisas ímpias’; por isso não levantarei a minha mão contra ti".', 3, CURRENT_TIMESTAMP, false),
(9, 24, 14, '"Contra quem saiu o rei de Israel? A quem está perseguindo? A um cão morto! A uma pulga!', 3, CURRENT_TIMESTAMP, false),
(9, 24, 15, 'O Senhor seja o juiz e nos julgue. Considere ele minha causa e a sustente; que ele me julgue, livrando-me de tuas mãos. "', 3, CURRENT_TIMESTAMP, false),
(9, 24, 16, 'Tendo Davi falado todas essas palavras, Saul perguntou: "É você, meu filho Davi? " E chorou em voz alta.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 17, '"Você é mais justo do que eu", disse ele a Davi. "Você me tratou bem, mas eu o tratei mal. "', 3, CURRENT_TIMESTAMP, false),
(9, 24, 18, '"Você acabou de mostrar o bem que me tem feito; o Senhor me entregou em suas mãos, mas você não me matou.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 19, 'Quando um homem encontra um inimigo e o deixa ir sem fazer-lhe mal? O Senhor o recompense com o bem, pelo modo como você me tratou hoje.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 20, 'Agora tenho certeza de que você será rei e de que o reino de Israel será firmado em suas mãos.', 3, CURRENT_TIMESTAMP, false),
(9, 24, 21, 'Portanto, jure-me pelo Senhor que você não eliminará meus descendentes nem fará meu nome desaparecer da família de meu pai".', 3, CURRENT_TIMESTAMP, false),
(9, 24, 22, 'Então Davi fez seu juramento a Saul. E este voltou para casa, mas Davi e seus soldados foram para a fortaleza.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 1, 'Samuel morreu, e todo o Israel se reuniu e o pranteou; e o sepultaram onde vivia, em Ramá. Depois Davi foi para o deserto de Maom.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 2, 'Certo homem de Maom, que tinha seus bens na cidade de Carmelo, era muito rico. Possuía mil cabras e três mil ovelhas, as quais estavam sendo tosquiadas em Carmelo.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 3, 'Seu nome era Nabal e o nome de sua mulher era Abigail, mulher inteligente e bonita; mas seu marido, descendente de Calebe, era rude e mau.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 4, 'No deserto, Davi ficou sabendo que Nabal estava tosquiando as ovelhas.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 5, 'Por isso, enviou dez rapazes e lhes disse: "Levem minha mensagem a Nabal, em Carmelo, e o cumprimentem em meu nome.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 6, 'Digam-lhe: ‘Longa vida para o senhor! Muita paz para o senhor e sua família! E muita prosperidade para tudo que é teu! ’', 3, CURRENT_TIMESTAMP, false),
(9, 25, 7, '‘Sei que estás tosquiando tuas ovelhas. Quando os teus pastores estavam conosco, nós não os maltratamos, e durante todo o tempo em que estiveram em Carmelo não se perdeu nada que fosse deles.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 8, 'Pergunte a eles, e eles lhe dirão. Por isso, seja favorável, pois estamos vindo em época de festa. Por favor, dá a nós teus servos e a teu filho Davi o que puderes’ ".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 9, 'Os rapazes foram e deram a Nabal essa mensagem, em nome de Davi. E ficaram esperando.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 10, 'Nabal respondeu então aos servos de Davi: "Quem é Davi? Quem é esse filho de Jessé? Hoje em dia, muitos servos estão fugindo de seus senhores.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 11, 'Por que deveria eu pegar meu pão e minha água, e a carne do gado que abati para meus tosquiadores, e dá-los a homens que vêm não se sabe de onde? "', 3, CURRENT_TIMESTAMP, false),
(9, 25, 12, 'Então, os mensageiros de Davi voltaram, e ao chegarem, relataram a ele cada uma dessas palavras.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 13, 'Davi ordenou a seus homens: "Ponham suas espadas na cintura! " Assim eles fizeram e também Davi. Cerca de quatrocentos homens acompanharam Davi, enquanto duzentos permaneceram com a bagagem.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 14, 'Um dos servos disse a Abigail, mulher de Nabal: "Do deserto, Davi enviou mensageiros para saudar o nosso senhor, mas ele os insultou.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 15, 'No entanto, aqueles homens foram muito bons para conosco. Não nos maltrataram, e, durante todo o tempo em que estivemos com eles nos campos, nada perdemos.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 16, 'Dia e noite eles eram como um muro ao nosso redor, durante todo o tempo em que estivemos com eles cuidando de nossas ovelhas.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 17, 'Agora, leve isso em consideração e veja o que a senhora pode fazer, pois a destruição paira sobre o nosso senhor e sobre toda a sua família. Ele é um homem tão mau que ninguém consegue conversar com ele".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 18, 'Imediatamente, Abigail pegou duzentos pães, duas vasilhas de couro cheias de vinho, cinco ovelhas preparadas, cinco medidas de grãos torrados, cem bolos de uvas passas e duzentos bolos de figos prensados, e os carregou em jumentos.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 19, 'E disse a seus servos: "Vocês vão na frente; eu os seguirei". Ela, porém, nada disse a Nabal, seu marido.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 20, 'Enquanto ela ia montada num jumento, encoberta pela montanha, Davi e seus soldados estavam descendo em sua direção, e ela os encontrou.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 21, 'Davi tinha dito: "De nada adiantou proteger os bens daquele homem no deserto, para que nada se perdesse. Ele me pagou o bem com o mal.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 22, 'Que Deus castigue a Davi, e o faça com muita severidade, caso até de manhã eu deixe vivo um só do sexo masculino de todos os que pertencem a Nabal! "', 3, CURRENT_TIMESTAMP, false),
(9, 25, 23, 'Quando Abigail viu Davi, desceu depressa do jumento e prostrou-se perante Davi, rosto em terra.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 24, 'Ela caiu a seus pés e disse: "Meu senhor, a culpa é toda minha. Por favor, deixa a tua serva lhe falar; ouve o que ela tem a dizer.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 25, 'Meu senhor, não dês atenção àquele homem mau, Nabal. Ele é insensato, conforme o seu nome significa; e a insensatez o acompanha. Contudo, eu, tua serva, não vi os rapazes que meu senhor enviou.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 26, '"Agora, meu senhor, juro pelo nome do Senhor e por tua vida que foi o Senhor que o impediu de derramar sangue e de vingar-se com tuas próprias mãos. Que teus inimigos e todos os que pretendem fazer-te mal sejam castigados como Nabal.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 27, 'E que este presente que esta tua serva trouxe ao meu senhor seja dado aos homens que o seguem.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 28, 'Esqueça, eu te suplico, a ofensa de tua serva, pois o Senhor certamente fará um reino duradouro para ti, que travas os combates do Senhor. E em toda a tua vida, nenhuma culpa se ache em ti.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 29, 'Mesmo que alguém te persiga para tirar-te a vida, a vida de meu senhor estará firmemente segura como a dos que são protegidos pelo Senhor teu Deus. Mas a vida de teus inimigos será atirada para longe como por uma atiradeira.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 30, 'Quando o Senhor tiver feito a meu senhor todo o bem que prometeu e te tiver nomeado líder sobre Israel,', 3, CURRENT_TIMESTAMP, false),
(9, 25, 31, 'meu senhor não terá no coração o peso de ter derramado sangue desnecessariamente nem de ter feito justiça com as próprias mãos. E, quando o Senhor tiver abençoado a ti, lembra-te de tua serva".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 32, 'Davi disse a Abigail: "Bendito seja o Senhor, o Deus de Israel, que hoje a enviou ao meu encontro.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 33, 'Seja você abençoada pelo seu bom senso e por evitar que eu hoje derrame sangue e me vingue com minhas próprias mãos.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 34, 'De outro modo, juro pelo nome do Senhor, o Deus de Israel, que evitou que eu lhe fizesse mal, se você não tivesse vindo depressa encontrar-me, nem um só do sexo masculino pertencente a Nabal teria sido deixado vivo ao romper do dia".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 35, 'Então Davi aceitou o que ela havia lhe trazido e disse: "Vá para sua casa em paz. Ouvi o que você disse e atenderei o seu pedido".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 36, 'Quando Abigail retornou a Nabal, ele estava dando um banquete em casa, como um banquete de rei. Ele estava alegre e bastante bêbado, e ela nada lhe falou até o amanhecer.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 37, 'De manhã, quando Nabal estava sóbrio, sua mulher lhe contou todas essas coisas; ele sofreu um ataque e ficou paralisado como uma pedra.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 38, 'Cerca de dez dias depois, o Senhor feriu a Nabal, e ele morreu.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 39, 'Quando Davi soube que Nabal estava morto, disse: "Bendito seja o Senhor, que defendeu a minha causa contra Nabal, por ter me tratado com desprezo. O Senhor impediu seu servo de praticar o mal e fez com que a maldade de Nabal caísse sobre sua própria cabeça". Então Davi enviou uma mensagem a Abigail, pedindo-lhe que se tornasse sua mulher.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 40, 'Seus servos foram a Carmelo e disseram a Abigail: "Davi nos enviou a você para levá-la para tornar-se mulher dele".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 41, 'Ela se levantou, depois inclinou-se rosto em terra e disse: "Aqui está a sua serva, pronta para servi-los e lavar os pés dos servos de meu senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 25, 42, 'Abigail logo montou num jumento e, acompanhada por suas cinco servas, foi com os mensageiros de Davi e tornou-se sua mulher.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 43, 'Davi também casou-se com Ainoã de Jezreel; e as duas foram suas mulheres.', 3, CURRENT_TIMESTAMP, false),
(9, 25, 44, 'Saul, porém, tinha dado sua filha Mical, mulher de Davi, a Paltiel, filho de Laís, de Galim.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 1, 'Os zifeus foram falar com Saul, em Gibeá, e disseram: "Davi está escondido na colina de Haquilá, em frente do deserto de Jesimom"', 3, CURRENT_TIMESTAMP, false),
(9, 26, 2, 'Então Saul desceu ao deserto de Zife, com três mil dos melhores soldados de Israel, em busca de Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 3, 'Saul acampou ao lado da estrada, na colina de Haquilá, em frente do deserto de Jesimom, mas Davi permaneceu no deserto. Quando viu que Saul o estava seguindo,', 3, CURRENT_TIMESTAMP, false),
(9, 26, 4, 'enviou espiões e soube que Saul havia de fato chegado.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 5, 'Então Davi foi para o lugar onde Saul estava acampado. E viu o lugar onde Saul e Abner, filho de Ner, comandante de seu exército, haviam se deitado. Saul estava deitado no acampamento, com o exército acampado ao redor.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 6, 'Davi então perguntou ao hitita Aimeleque e a Abisai, filho de Zeruia, irmão de Joabe: "Quem descerá comigo ao acampamento de Saul? " Disse Abisai: "Irei com você".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 7, 'Davi e Abisai entraram à noite no acampamento. Saul estava deitado, dormindo com sua lança fincada no chão, perto da cabeça. Abner e os soldados estavam deitados à sua volta.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 8, 'Abisai disse a Davi: "Hoje Deus entregou o seu inimigo nas suas mãos. Deixe-me, agora, cravar a lança nele até o chão com um só golpe; não precisarei de outro".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 9, 'Davi, contudo, disse a Abisai: "Não o mate! Quem pode levantar a mão contra o ungido do Senhor e permanecer inocente?', 3, CURRENT_TIMESTAMP, false),
(9, 26, 10, 'Juro pelo nome do Senhor", disse ele, "o Senhor mesmo o matará; ou chegará a sua hora e ele morrerá, ou ele irá para a batalha e perecerá.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 11, 'O Senhor me livre de levantar a mão contra seu ungido. Agora, vamos pegar a lança e o jarro com água que estão perto da cabeça dele, e vamos embora".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 12, 'Então, Davi apanhou a lança e o jarro que estavam perto da cabeça de Saul, e eles foram embora. Ninguém os viu, ninguém percebeu e ninguém acordou. Estavam todos dormindo, pois um sono pesado vindo do Senhor havia caído sobre eles.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 13, 'Então Davi atravessou para o outro lado e colocou-se no topo da colina, ao longe, a uma boa distância deles.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 14, 'E gritou para o exército e para Abner, filho de Ner: "Você não vai me responder, Abner? " Abner respondeu: "Quem é que está gritando para o rei? "', 3, CURRENT_TIMESTAMP, false),
(9, 26, 15, 'Disse Davi: "Você é homem, não é? Quem é como você em Israel? Por que você não protegeu o rei, seu senhor? Alguém foi até aí para matá-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 16, 'Não é bom isso que você fez! Juro pelo Senhor que todos vocês merecem morrer, pois não protegeram o seu rei, o ungido do Senhor. Agora, olhem! Onde estão a lança e o jarro de água do rei, que estavam perto da cabeça dele? "', 3, CURRENT_TIMESTAMP, false),
(9, 26, 17, 'Saul reconheceu a voz de Davi e disse: "É você, meu filho Davi? " Davi respondeu: "Sim, ó rei, meu senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 18, 'E acrescentou: "Por que meu senhor está perseguindo este seu servo? O que eu fiz e de que mal sou culpado?', 3, CURRENT_TIMESTAMP, false),
(9, 26, 19, 'Que o rei, meu senhor, escute as palavras de seu servo. Se o Senhor o instigou contra mim, então que ele aceite uma oferta; se, porém, são homens que o fizeram, que sejam amaldiçoados perante o Senhor! Eles agora me afastaram de minha porção na herança do Senhor e disseram: ‘Vá, preste culto a outros deuses’.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 20, 'Agora, que meu sangue não caia sobre a terra, longe da presença do Senhor. O rei de Israel saiu à procura de uma pulga, como alguém que caça uma perdiz nos montes".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 21, 'Então Saul disse: "Pequei! Volte, meu filho Davi! Como hoje você considerou preciosa a minha vida, não lhe farei mal de novo. Tenho agido como um tolo e cometido um grande erro".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 22, 'Respondeu Davi: "Aqui está a lança do rei. Venha um de seus servos e a pegue.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 23, 'O Senhor recompensa a justiça e a fidelidade de cada um. Ele o entregou nas minhas mãos hoje, mas eu não levantaria a mão contra o ungido do Senhor.', 3, CURRENT_TIMESTAMP, false),
(9, 26, 24, 'Assim como eu hoje considerei a sua vida de grande valor, que o Senhor também considere a minha vida e me livre de toda a angústia".', 3, CURRENT_TIMESTAMP, false),
(9, 26, 25, 'Então Saul disse a Davi: "Seja você abençoado, meu filho Davi; você fará muitas coisas e em tudo será bem sucedido". Assim Davi prosseguiu seu caminho, e Saul voltou para casa.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 1, 'Davi, contudo, pensou: "Algum dia serei morto por Saul. É melhor fugir para a terra dos filisteus. Então Saul desistirá de procurar-me por todo o Israel, e escaparei dele".', 3, CURRENT_TIMESTAMP, false),
(9, 27, 2, 'Assim, Davi e os seiscentos homens que estavam com ele foram até Aquis, filho de Maoque, rei de Gate.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 3, 'Davi e seus soldados se estabeleceram com Aquis, em Gate. Cada homem levou sua família, e Davi, suas duas mulheres, Ainoã, de Jezreel, e Abigail, mulher de Nabal, de Carmelo.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 4, 'Quando contaram a Saul que Davi havia fugido para Gate, ele parou de persegui-lo.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 5, 'Então Davi disse a Aquis: "Se eu conto com a sua simpatia, dá-me um lugar numa das cidades desta terra onde eu possa viver. Por que este teu servo viveria contigo na cidade real? "', 3, CURRENT_TIMESTAMP, false),
(9, 27, 6, 'Naquele dia Aquis deu-lhe Ziclague. Por isso, Ziclague pertence aos reis de Judá até hoje.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 7, 'Davi morou em território filisteu durante um ano e quatro meses.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 8, 'Davi e seus soldados atacavam os gesuritas, os gersitas e os amalequitas, povos que, desde tempos antigos, habitavam a terra que se estende de Sur até o Egito.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 9, 'Quando Davi atacava a região, não poupava homens nem mulheres, e tomava ovelhas, bois, jumentos, camelos e roupas. Então retornava a Aquis.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 10, 'Quando Aquis perguntava: "Onde você atacou hoje? " Davi respondia: "O Neguebe de Judá" ou "O Neguebe de Jerameel" ou "O Neguebe dos queneus".', 3, CURRENT_TIMESTAMP, false),
(9, 27, 11, 'Ele matava a todos, homens e mulheres, para que não fossem levados a Gate, pois pensava: "Eles poderão denunciar-me". Este foi o seu procedimento enquanto viveu em território filisteu.', 3, CURRENT_TIMESTAMP, false),
(9, 27, 12, 'Aquis confiava em Davi e dizia: "Ele se tornou tão odiado por seu povo, os israelitas, que será meu servo para sempre".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 1, 'Naqueles dias os filisteus reuniram suas tropas para lutar contra Israel. Aquis disse a Davi: "Você deve saber que você e seus soldados me acompanharão no exército".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 2, 'Disse Davi a Aquis: "Então tu saberás o que teu servo é capaz de fazer". Aquis respondeu-lhe: "Então, o colocarei como minha guarda pessoal permanente".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 3, 'Samuel já havia morrido, e todo o Israel o havia pranteado e sepultado em Ramá, sua cidade natal. Saul havia expulsado do país os médiuns e os espíritas.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 4, 'Depois que os filisteus se reuniram, vieram e acamparam em Suném, enquanto Saul reunia todos os israelitas e acampava em Gilboa.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 5, 'Quando Saul viu o acampamento filisteu, teve medo; ficou apavorado.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 6, 'Ele consultou o Senhor, mas este não lhe respondeu nem por sonhos nem por Urim nem por profetas.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 7, 'Então Saul disse aos seus auxiliares: "Procurem uma mulher que invoca espíritos, para que eu a consulte". Eles disseram: "Existe uma em En-Dor".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 8, 'Saul então se disfarçou, vestindo outras roupas, e foi à noite, com dois homens, até a casa da mulher. Ele disse a ela: "Invoque um espírito para mim, fazendo subir aquele cujo nome eu disser".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 9, 'A mulher, porém, lhe disse: "Certamente você sabe o que Saul fez. Ele eliminou os médiuns e os espíritas da terra de Israel. Por que você está preparando uma armadilha contra mim que me levará à morte? "', 3, CURRENT_TIMESTAMP, false),
(9, 28, 10, 'Saul jurou-lhe pelo Senhor: "Juro pelo nome do Senhor que você não será punida por isso".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 11, '"Quem devo fazer subir? ", perguntou a mulher. Ele respondeu: "Samuel".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 12, 'Quando a mulher viu Samuel, gritou e disse a Saul: "Por que me enganaste? Tu mesmo és Saul! "', 3, CURRENT_TIMESTAMP, false),
(9, 28, 13, 'O rei lhe disse: "Não tenha medo. O que você está vendo? " A mulher disse a Saul: "Vejo um ser que sobe do chão".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 14, 'Ele perguntou: "Qual a aparência dele? " E disse ela: "Um ancião vestindo um manto está subindo". Então Saul ficou sabendo que era Samuel, inclinou-se e prostrou-se, rosto em terra.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 15, 'Samuel perguntou a Saul: "Por que você me perturbou, fazendo-me subir? " Respondeu Saul: "Estou muito angustiado. Os filisteus estão me atacando e Deus se afastou de mim. Ele já não responde nem por profetas nem por sonhos; por isso o chamei para dizer-me o que fazer".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 16, 'Disse Samuel: "Por que você me chamou, já que o Senhor se afastou de você e se tornou seu inimigo?', 3, CURRENT_TIMESTAMP, false),
(9, 28, 17, 'O Senhor fez o que predisse por meu intermédio: rasgou de suas mãos o reino e o deu a seu próximo, a Davi.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 18, 'Porque você não obedeceu ao Senhor nem executou a grande ira dele contra os amalequitas, ele lhe faz isso hoje.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 19, 'O Senhor entregará você e o povo de Israel nas mãos dos filisteus, e amanhã você e seus filhos estarão comigo. O Senhor também entregará o exército de Israel nas mãos dos filisteus".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 20, 'Na mesma hora Saul caiu estendido no chão, aterrorizado pelas palavras de Samuel. Suas forças haviam se esgotado, pois ele tinha passado todo aquele dia e toda aquela noite sem comer.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 21, 'Quando a mulher se aproximou de Saul e viu que ele estava profundamente perturbado, disse: "Olha, tua serva te obedeceu. Arrisquei minha vida e fiz o que me ordenaste.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 22, 'Agora, por favor, ouve tua serva e come um pouco para que tenhas forças para seguir teu caminho".', 3, CURRENT_TIMESTAMP, false),
(9, 28, 23, 'Ele recusou e disse: "Não vou comer". Seus homens, porém, insistiram com ele, e a mulher também; e ele os atendeu. Ele se levantou do chão e sentou-se na cama.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 24, 'A mulher matou depressa um bezerro gordo que tinha em casa; apanhou um pouco de farinha, amassou-a e assou pão sem fermento.', 3, CURRENT_TIMESTAMP, false),
(9, 28, 25, 'Então ela serviu a Saul e a seus homens, e eles comeram. E naquela mesma noite eles partiram.', 3, CURRENT_TIMESTAMP, false),
(9, 29, 1, 'Os filisteus reuniram todas as suas tropas em Afeque, e Israel acampou junto à fonte em Jezreel.', 3, CURRENT_TIMESTAMP, false),
(9, 29, 2, 'Enquanto os governantes filisteus avançavam com seus grupos de cem e de mil, Davi e seus homens iam na retaguarda com Aquis.', 3, CURRENT_TIMESTAMP, false),
(9, 29, 3, 'Os comandantes dos filisteus perguntaram: "O que estes hebreus fazem aqui? " Aquis respondeu: "Este é Davi, que era oficial de Saul, rei de Israel. Ele já está comigo há mais de um ano, e desde o dia em que deixou Saul nada fez que mereça desconfiança".', 3, CURRENT_TIMESTAMP, false),
(9, 29, 4, 'Contudo, os comandantes filisteus se iraram contra ele e disseram: "Mande embora este homem para a cidade que você lhe designou. Ele não deve ir para a guerra conosco, senão se tornará nosso adversário durante o combate. Qual seria a melhor maneira de recuperar a boa vontade de seu senhor, senão às custas das cabeças de nossos homens?', 3, CURRENT_TIMESTAMP, false),
(9, 29, 5, 'Não é ele o Davi de quem cantavam em suas danças: ‘Saul abateu seus milhares, e Davi suas dezenas de milhares’? "', 3, CURRENT_TIMESTAMP, false),
(9, 29, 6, 'Então Aquis chamou a Davi e lhe disse: "Juro pelo nome do Senhor que você tem sido leal, e ficaria contente em tê-lo servindo comigo no exército. Desde o dia em que você veio a mim, nunca desconfiei de você, mas os governantes não o aprovam.', 3, CURRENT_TIMESTAMP, false),
(9, 29, 7, 'Agora, volte e vá em paz! Não faça nada que desagrade os governantes filisteus".', 3, CURRENT_TIMESTAMP, false),
(9, 29, 8, 'Davi perguntou: "O que foi que eu fiz? O que descobriste contra teu servo, desde o dia em que cheguei? Por que não posso ir e lutar contra os inimigos do rei, meu senhor? "', 3, CURRENT_TIMESTAMP, false),
(9, 29, 9, 'Aquis respondeu: "Reconheço que você tem feito o que eu aprovo, como um anjo de Deus. Os comandantes filisteus, no entanto, dizem que você não deve ir à batalha conosco.', 3, CURRENT_TIMESTAMP, false),
(9, 29, 10, 'Agora, levante-se bem cedo, junto com os servos de seu senhor que vieram com você, e partam de manhã, assim que clarear o dia".', 3, CURRENT_TIMESTAMP, false),
(9, 29, 11, 'Então Davi e seus soldados levantaram-se de madrugada para voltar à terra dos filisteus. Os filisteus, porém, foram para Jezreel.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 1, 'Quando Davi e seus soldados chegaram a Ziclague, no terceiro dia, os amalequitas tinham atacado o Neguebe e Ziclague, e haviam incendiado a cidade.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 2, 'Levaram como prisioneiros todos os que lá estavam: as mulheres, os jovens e os idosos. A ninguém mataram, mas os levaram consigo, quando prosseguiram seu caminho.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 3, 'Ao chegarem a Ziclague, Davi e seus soldados encontraram a cidade destruída pelo fogo e viram que suas mulheres, filhos e filhas haviam sido levados como prisioneiros.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 4, 'Então Davi e seus soldados choraram em alta voz até não terem mais forças.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 5, 'As duas mulheres de Davi também tinham sido levadas: Ainoã de Jezreel, e Abigail de Carmelo, a que fora mulher de Nabal.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 6, 'Davi ficou profundamente angustiado, pois os homens falavam em apedrejá-lo; todos estavam amargurados por causa de seus filhos e suas filhas. Davi, porém, fortaleceu-se no Senhor seu Deus.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 7, 'Então Davi disse ao sacerdote Abiatar, filho de Aimeleque: "Traga-me o colete sacerdotal". Abiatar o trouxe a Davi,', 3, CURRENT_TIMESTAMP, false),
(9, 30, 8, 'e ele perguntou ao Senhor: "Devo perseguir este bando de invasores? Irei alcançá-los? " E o Senhor respondeu: "Persiga-os; é certo que você os alcançará e conseguirá libertar os prisioneiros".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 9, 'Davi e os seiscentos homens que estavam com ele foram ao ribeiro de Besor, onde ficaram alguns,', 3, CURRENT_TIMESTAMP, false),
(9, 30, 10, 'pois duzentos deles estavam exaustos demais para atravessar o ribeiro. Todavia, Davi e quatrocentos homens continuaram a perseguição.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 11, 'Encontraram um egípcio no campo e o trouxeram a Davi. Deram-lhe água e comida:', 3, CURRENT_TIMESTAMP, false),
(9, 30, 12, 'um pedaço de bolo de figos prensados e dois bolos de uvas passas. Ele comeu e recobrou as forças, pois tinha ficado três dias e três noites sem comer e sem beber.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 13, 'Davi lhe perguntou: "A quem você pertence e de onde vem? " Ele respondeu: "Sou um jovem egípcio, servo de um amalequita. Meu senhor me abandonou quando fiquei doente há três dias.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 14, 'Nós atacamos o Neguebe dos queretitas, o território que pertence a Judá e o Neguebe de Calebe. E incendiamos a cidade de Ziclague".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 15, 'Davi lhe perguntou: "Você pode levar-me até esse bando de invasores? " Ele respondeu: "Jura, diante de Deus, que não me matarás nem me entregarás nas mãos de meu senhor, e te levarei até eles".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 16, 'Quando ele levou Davi até lá, eles estavam espalhados pela região, comendo, bebendo e festejando os muitos bens que haviam tomado da terra dos filisteus e de Judá.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 17, 'Davi os atacou no dia seguinte, desde o amanhecer até à tarde, e nenhum deles escapou, com a exceção de quatrocentos jovens que montaram em camelos e fugiram.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 18, 'Davi recuperou tudo o que os amalequitas tinham levado, incluindo suas duas mulheres.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 19, 'Nada faltou; nem jovens, nem velhos, nem filhos, nem filhas, nem bens nem qualquer outra coisa que fora levada. Davi recuperou tudo.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 20, 'E tomou também todos os rebanhos dos amalequitas, e seus soldados os conduziram à frente dos outros animais, dizendo: "Estes são os despojos de Davi".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 21, 'Então Davi foi até os duzentos homens que estavam exaustos demais para segui-lo e tinham ficado no ribeiro de Besor. Eles saíram para encontrar Davi e os que estavam com ele. Ao se aproximar com seus soldados, Davi os saudou.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 22, 'Mas todos os maus e vadios que tinham ido com Davi disseram: "Uma vez que não saíram conosco, não repartiremos com eles os bens que recuperamos. No entanto, cada um poderá pegar sua mulher e seus filhos e partir".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 23, 'Davi respondeu: "Não, meus irmãos! Não façam isso com o que o Senhor nos deu. Ele nos protegeu e entregou em nossas mãos as forças que vieram contra nós.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 24, 'Quem concordará com o que vocês estão dizendo? A parte de quem ficou com a bagagem será a mesma de quem foi à batalha. Todos receberão partes iguais".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 25, 'Davi fez disso um decreto e uma ordenança para Israel, desde aquele dia até hoje.', 3, CURRENT_TIMESTAMP, false),
(9, 30, 26, 'Quando Davi chegou a Ziclague, enviou parte dos bens às autoridades de Judá, que eram seus amigos, dizendo: "Eis um presente para vocês, tirado dos bens dos inimigos do Senhor".', 3, CURRENT_TIMESTAMP, false),
(9, 30, 27, 'Ele enviou esse presente às autoridades de Betel, de Ramote do Neguebe, de Jatir,', 3, CURRENT_TIMESTAMP, false),
(9, 30, 28, 'de Aroer, de Sifmote, de Estemoa,', 3, CURRENT_TIMESTAMP, false),
(9, 30, 29, 'de Racal, das cidades dos jerameelitas e dos queneus,', 3, CURRENT_TIMESTAMP, false),
(9, 30, 30, 'e de Hormá, de Corasã, de Atace,', 3, CURRENT_TIMESTAMP, false),
(9, 30, 31, 'de Hebrom e de todos os lugares onde Davi e seus soldados tinham passado.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 1, 'E aconteceu que, em combate com os filisteus, os israelitas foram postos em fuga e muitos caíram mortos no monte Gilboa.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 2, 'Os filisteus perseguiram Saul e seus filhos, e mataram Jônatas, Abinadabe e Malquisua, filhos de Saul.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 3, 'O combate foi se tornando cada vez mais violento em torno de Saul, até que os flecheiros o alcançaram e o feriram gravemente.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 4, 'Então Saul ordenou ao seu escudeiro: "Tire sua espada e mate-me com ela, senão sofrerei a vergonha de cair nas mãos desses incircuncisos". Mas seu escudeiro estava apavorado e não quis fazê-lo. Saul, então, pegou a própria espada e jogou-se sobre ela.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 5, 'Quando o escudeiro viu que Saul estava morto, jogou-se também sobre sua espada e morreu com ele.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 6, 'De maneira que Saul, seus três filhos, seu escudeiro e todos os seus soldados morreram juntos naquele dia.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 7, 'Quando os israelitas que habitavam do outro lado do vale e a leste do Jordão viram que o exército tinha fugido, e que Saul e seus filhos estavam mortos, fugiram abandonando suas cidades. Depois os filisteus foram ocupá-las.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 8, 'No dia seguinte, quando os filisteus foram saquear os mortos, encontraram Saul e seus três filhos caídos no monte Gilboa.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 9, 'Cortaram a cabeça de Saul, pegaram suas armas, e enviaram mensageiros por toda a terra dos filisteus proclamando a notícia nos templos de seus ídolos e entre seu povo.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 10, 'Expuseram as armas de Saul no templo dos postes sagrados e penduraram seu corpo no muro de Bete-Seã.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 11, 'Quando os habitantes de Jabes-Gileade ficaram sabendo do que os filisteus tinham feito com Saul,', 3, CURRENT_TIMESTAMP, false),
(9, 31, 12, 'os mais corajosos dentre eles foram durante a noite a Bete-Seã. Baixaram os corpos de Saul e de seus filhos do muro de Bete-Seã e foram para Jabes, onde os queimaram.', 3, CURRENT_TIMESTAMP, false),
(9, 31, 13, 'Depois enterraram seus ossos debaixo de uma tamargueira em Jabes, e jejuaram por sete dias.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 1, 'Paulo, Silvano e Timóteo, à igreja dos tessalonicenses, em Deus Pai e no Senhor Jesus Cristo: A vocês, graça e paz da parte de Deus e de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 2, 'Sempre damos graças a Deus por todos vocês, mencionando-os em nossas orações.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 3, 'Lembramos continuamente, diante de nosso Deus e Pai, o que vocês têm demonstrado: o trabalho que resulta da fé, o esforço motivado pelo amor e a perseverança proveniente da esperança em nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 4, 'Sabemos, irmãos, amados de Deus, que ele os escolheu', 3, CURRENT_TIMESTAMP, false),
(52, 1, 5, 'porque o nosso evangelho não chegou a vocês somente em palavra, mas também em poder, no Espírito Santo e em plena convicção. Vocês sabem como procedemos entre vocês, em seu favor.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 6, 'De fato, vocês se tornaram nossos imitadores e do Senhor; apesar de muito sofrimento, receberam a palavra com alegria que vem do Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 7, 'E, assim, tornaram-se modelo para todos os crentes que estão na Macedônia e na Acaia.', 3, CURRENT_TIMESTAMP, false),
(52, 1, 8, 'Porque, partindo de vocês, propagou-se a mensagem do Senhor na Macedônia e na Acaia. Não somente isso, mas também por toda parte tornou-se conhecida a fé que vocês têm em Deus. O resultado é que não temos necessidade de dizer mais nada sobre isso,', 3, CURRENT_TIMESTAMP, false),
(52, 1, 9, 'pois eles mesmos relatam de que maneira vocês nos receberam, como se voltaram para Deus, deixando os ídolos a fim de servir ao Deus vivo e verdadeiro,', 3, CURRENT_TIMESTAMP, false),
(52, 1, 10, 'e esperar dos céus a seu Filho, a quem ressuscitou dos mortos: Jesus, que nos livra da ira que há de vir.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 1, 'Irmãos, vocês mesmos sabem que a visita que lhes fizemos não foi inútil.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 2, 'Apesar de termos sido maltratados e insultados em Filipos, como vocês sabem, com a ajuda de nosso Deus tivemos coragem de anunciar-lhes o evangelho de Deus, em meio a muita luta.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 3, 'Pois nossa exortação não tem origem no erro nem em motivos impuros, nem temos intenção de enganá-los;', 3, CURRENT_TIMESTAMP, false),
(52, 2, 4, 'pelo contrário, como homens aprovados por Deus, a ponto de nos ter sido confiado por ele o evangelho, não falamos para agradar a pessoas, mas a Deus, que prova os nossos corações.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 5, 'Vocês bem sabem a nossa linguagem nunca foi de bajulação nem de pretexto para ganância; Deus é testemunha.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 6, 'Nem buscamos reconhecimento humano, quer de vocês quer de outros.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 7, 'Embora, como apóstolos de Cristo, pudéssemos ter sido um peso, tornamo-nos bondosos entre vocês, como uma mãe que cuida dos próprios filhos.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 8, 'Sentindo, assim, tanta afeição por vocês, decidimos dar-lhes não somente o evangelho de Deus, mas também a nossa própria vida, porque vocês se tornaram muito amados por nós.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 9, 'Irmãos, certamente vocês se lembram do nosso trabalho esgotante e da nossa fadiga; trabalhamos noite e dia para não sermos pesados a ninguém, enquanto lhes pregávamos o evangelho de Deus.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 10, 'Tanto vocês como Deus são testemunhas de como nos portamos de maneira santa, justa e irrepreensível entre vocês, os que crêem.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 11, 'Pois vocês sabem que tratamos cada um como um pai trata seus filhos,', 3, CURRENT_TIMESTAMP, false),
(52, 2, 12, 'exortando, consolando e dando testemunho, para que vocês vivam de maneira digna de Deus, que os chamou para o seu Reino e glória.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 13, 'Também agradecemos a Deus sem cessar, pois, ao receberem de nossa parte a palavra de Deus, vocês a aceitaram não como palavra de homens, mas segundo verdadeiramente é, como palavra de Deus, que atua com eficácia em vocês, os que crêem.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 14, 'Porque vocês, irmãos, tornaram-se imitadores das igrejas de Deus em Cristo Jesus que estão na Judéia. Vocês sofreram da parte dos seus próprios conterrâneos as mesmas coisas que aquelas igrejas sofreram da parte dos judeus,', 3, CURRENT_TIMESTAMP, false),
(52, 2, 15, 'que mataram o Senhor Jesus e os profetas, e também nos perseguiram. Eles desagradam a Deus e são hostis a todos,', 3, CURRENT_TIMESTAMP, false),
(52, 2, 16, 'esforçando-se para nos impedir que falemos aos gentios, e estes sejam salvos. Dessa forma, vão sempre completando a medida dos seus pecados. Sobre eles, finalmente, veio a ira.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 17, 'Nós, porém, irmãos, privados da companhia de vocês por breve tempo, em pessoa, mas não no coração, esforçamo-nos ainda mais para vê-los pessoalmente, pela saudade que temos de vocês.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 18, 'Quisemos visitá-los. Eu mesmo, Paulo o quis, e não apenas uma vez, mas duas; Satanás, porém, nos impediu.', 3, CURRENT_TIMESTAMP, false),
(52, 2, 19, 'Pois quem é a nossa esperança, alegria ou coroa em que nos gloriamos perante o Senhor Jesus na sua vinda? Não são vocês?', 3, CURRENT_TIMESTAMP, false),
(52, 2, 20, 'De fato, vocês são a nossa glória e a nossa alegria.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 1, 'Por isso, quando não pudemos mais suportar, achamos por bem permanecer sozinhos em Atenas', 3, CURRENT_TIMESTAMP, false),
(52, 3, 2, 'e, assim, enviamos Timóteo, nosso irmão e cooperador de Deus no evangelho de Cristo, para fortalecê-los e dar-lhes ânimo na fé,', 3, CURRENT_TIMESTAMP, false),
(52, 3, 3, 'para que ninguém seja abalado por essas tribulações. Vocês sabem muito bem que fomos designados para isso.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 4, 'Quando estávamos com vocês, já lhes dizíamos que seríamos perseguidos, o que realmente aconteceu, como vocês sabem.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 5, 'Por essa razão, não suportando mais, enviei Timóteo para saber a respeito da fé que vocês têm, a fim de que o tentador não os seduzisse, tornando inútil o nosso esforço.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 6, 'Agora, porém, Timóteo acaba de chegar da parte de vocês, dando-nos boas notícias a respeito da fé e do amor que vocês têm. Ele nos falou que vocês sempre guardam boas recordações de nós, desejando ver-nos, assim como nós queremos vê-los.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 7, 'Por isso, irmãos, em toda a nossa necessidade e tribulação temos bom ânimo a seu respeito, por sabermos da sua fé;', 3, CURRENT_TIMESTAMP, false),
(52, 3, 8, 'pois agora vivemos, visto que vocês estão firmes no Senhor.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 9, 'Como podemos ser suficientemente gratos a Deus por vocês, por toda a alegria que temos diante dele por causa de vocês?', 3, CURRENT_TIMESTAMP, false),
(52, 3, 10, 'Noite e dia com perseverança oramos para que possamos vê-los pessoalmente e suprir o que falta à sua fé.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 11, 'Que o próprio Deus, nosso Pai, e nosso Senhor Jesus preparem o nosso caminho até vocês.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 12, 'Que o Senhor faça crescer e transbordar o amor que vocês têm uns para com os outros e para com todos, a exemplo do nosso amor por vocês.', 3, CURRENT_TIMESTAMP, false),
(52, 3, 13, 'Que ele fortaleça os seus corações para serem irrepreensíveis em santidade diante de nosso Deus e Pai, na vinda de nosso Senhor Jesus com todos os seus santos.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 1, 'Quanto ao mais, irmãos, já os instruímos acerca de como viver a fim de agradar a Deus e, de fato, assim vocês estão procedendo. Agora lhes pedimos e exortamos no Senhor Jesus que cresçam nisso cada vez mais.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 2, 'Pois vocês conhecem os mandamentos que lhes demos pela autoridade do Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 3, 'A vontade de Deus é que vocês sejam santificados: abstenham-se da imoralidade sexual.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 4, 'Cada um saiba controlar o próprio corpo de maneira santa e honrosa,', 3, CURRENT_TIMESTAMP, false),
(52, 4, 5, 'não com a paixão de desejo desenfreado, como os pagãos que desconhecem a Deus.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 6, 'Neste assunto, ninguém prejudique a seu irmão nem dele se aproveite. O Senhor castigará todas essas práticas, como já lhes dissemos e asseguramos.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 7, 'Porque Deus não nos chamou para a impureza, mas para a santidade.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 8, 'Portanto, aquele que rejeita estas coisas não está rejeitando o homem, mas a Deus, que lhes dá o seu Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 9, 'Quanto ao amor fraternal, não precisamos escrever-lhes, pois vocês mesmos já foram ensinados por Deus a se amarem uns aos outros.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 10, 'E, de fato, vocês amam a todos os irmãos em toda a Macedônia. Contudo, irmãos, insistimos com vocês que cada vez mais assim procedam.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 11, 'Esforcem-se para ter uma vida tranqüila, cuidar dos seus próprios negócios e trabalhar com as próprias mãos, como nós os instruímos;', 3, CURRENT_TIMESTAMP, false),
(52, 4, 12, 'a fim de que andem decentemente aos olhos dos que são de fora e não dependam de ninguém.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 13, 'Irmãos, não queremos que vocês sejam ignorantes quanto aos que dormem, para que não se entristeçam como os outros que não têm esperança.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 14, 'Se cremos que Jesus morreu e ressurgiu, cremos também que Deus trará, mediante Jesus e juntamente com ele, aqueles que nele dormiram.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 15, 'Dizemos a vocês, pela palavra do Senhor, que nós, os que estivermos vivos, os que ficarmos até a vinda do Senhor, certamente não precederemos os que dormem.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 16, 'Pois, dada a ordem, com a voz do arcanjo e o ressoar da trombeta de Deus, o próprio Senhor descerá do céu, e os mortos em Cristo ressuscitarão primeiro.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 17, 'Depois disso, os que estivermos vivos seremos arrebatados juntamente com eles nas nuvens, para o encontro com o Senhor nos ares. E assim estaremos com o Senhor para sempre.', 3, CURRENT_TIMESTAMP, false),
(52, 4, 18, 'Consolem-se uns aos outros com estas palavras.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 1, 'Irmãos, quanto aos tempos e épocas, não precisamos escrever-lhes,', 3, CURRENT_TIMESTAMP, false),
(52, 5, 2, 'pois vocês mesmos sabem perfeitamente que o dia do Senhor virá como ladrão à noite.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 3, 'Quando disserem: "Paz e segurança", então, de repente, a destruição virá sobre eles, como dores à mulher grávida; e de modo nenhum escaparão.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 4, 'Mas vocês, irmãos, não estão nas trevas, para que esse dia os surpreenda como ladrão.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 5, 'Vocês todos são filhos da luz, filhos do dia. Não somos da noite nem das trevas.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 6, 'Portanto, não durmamos como os demais, mas estejamos atentos e sejamos sóbrios;', 3, CURRENT_TIMESTAMP, false),
(52, 5, 7, 'pois os que dormem, dormem de noite, e os que se embriagam, embriagam-se de noite.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 8, 'Nós, porém, que somos do dia, sejamos sóbrios, vestindo a couraça da fé e do amor e o capacete da esperança da salvação.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 9, 'Porque Deus não nos destinou para a ira, mas para recebermos a salvação por meio de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 10, 'Ele morreu por nós para que, quer estejamos acordados quer dormindo, vivamos unidos a ele.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 11, 'Por isso, exortem-se e edifiquem-se uns aos outros, como de fato vocês estão fazendo.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 12, 'Agora lhes pedimos, irmãos, que tenham consideração para com os que se esforçam no trabalho entre vocês, que os lideram no Senhor e os aconselham.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 13, 'Tenham-nos na mais alta estima, com amor, por causa do trabalho deles. Vivam em paz uns com os outros.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 14, 'Exortamos vocês, irmãos, a que advirtam os ociosos, confortem os desanimados, auxiliem os fracos, sejam pacientes para com todos.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 15, 'Tenham cuidado para que ninguém retribua o mal com o mal, mas sejam sempre bondosos uns para com os outros e para com todos.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 16, 'Alegrem-se sempre.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 17, 'Orem continuamente.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 18, 'Dêem graças em todas as circunstâncias, pois esta é a vontade de Deus para vocês em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 19, 'Não apaguem o Espírito.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 20, 'Não tratem com desprezo as profecias,', 3, CURRENT_TIMESTAMP, false),
(52, 5, 21, 'mas ponham à prova todas as coisas e fiquem com o que é bom.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 22, 'Afastem-se de toda forma de mal.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 23, 'Que o próprio Deus da paz os santifique inteiramente. Que todo o espírito, alma e corpo de vocês seja conservado irrepreensível na vinda de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 24, 'Aquele que os chama é fiel, e fará isso.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 25, 'Irmãos, orem por nós.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 26, 'Saúdem todos os irmãos com beijo santo.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 27, 'Responsabilizo-os diante do Senhor para que esta carta seja lida a todos os irmãos.', 3, CURRENT_TIMESTAMP, false),
(52, 5, 28, 'A graça de nosso Senhor Jesus Cristo seja com vocês.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 1, 'Paulo, apóstolo de Cristo Jesus, por ordem de Deus, nosso Salvador, e de Cristo Jesus, a nossa esperança,', 3, CURRENT_TIMESTAMP, false),
(54, 1, 2, 'a Timóteo, meu verdadeiro filho na fé: Graça, misericórdia e paz da parte de Deus Pai e de Cristo Jesus, o nosso Senhor.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 3, 'Partindo eu para a Macedônia, roguei-lhe que permanecesse em Éfeso para ordenar a certas pessoas que não mais ensinem doutrinas falsas,', 3, CURRENT_TIMESTAMP, false),
(54, 1, 4, 'e que deixem de dar atenção a mitos e genealogias intermináveis, que causam controvérsias em vez de promoverem a obra de Deus, que é pela fé.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 5, 'O objetivo desta instrução é o amor que procede de um coração puro, de uma boa consciência e de uma fé sincera.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 6, 'Alguns se desviaram dessas coisas, voltando-se para discussões inúteis,', 3, CURRENT_TIMESTAMP, false),
(54, 1, 7, 'querendo ser mestres da lei, quando não compreendem nem o que dizem nem as coisas acerca das quais fazem afirmações tão categóricas.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 8, 'Sabemos que a lei é boa, se alguém a usa de maneira adequada.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 9, 'Também sabemos que ela não é feita para os justos, mas para os transgressores e insubordinados, para os ímpios e pecadores, para os profanos e irreverentes, para os que matam pai e mãe, para os homicidas,', 3, CURRENT_TIMESTAMP, false),
(54, 1, 10, 'para os que praticam imoralidade sexual e os homossexuais, para os seqüestradores, para os mentirosos e os que juram falsamente; e para todo aquele que se opõe à sã doutrina.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 11, 'Essa sã doutrina se vê no glorioso evangelho que me foi confiado, o evangelho do Deus bendito.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 12, 'Dou graças a Cristo Jesus, nosso Senhor, que me deu forças e me considerou fiel, designando-me para o ministério,', 3, CURRENT_TIMESTAMP, false),
(54, 1, 13, 'a mim que anteriormente fui blasfemo, perseguidor e insolente; mas alcancei misericórdia, porque o fiz por ignorância e na minha incredulidade;', 3, CURRENT_TIMESTAMP, false),
(54, 1, 14, 'contudo, a graça de nosso Senhor transbordou sobre mim, juntamente com a fé e o amor que estão em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 15, 'Esta afirmação é fiel e digna de toda aceitação: Cristo Jesus veio ao mundo para salvar os pecadores, dos quais eu sou o pior.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 16, 'Mas, por isso mesmo alcancei misericórdia, para que em mim, o pior dos pecadores, Cristo Jesus demonstrasse toda a grandeza da sua paciência, usando-me como um exemplo para aqueles que nele haveriam de crer para a vida eterna.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 17, 'Ao Rei eterno, ao Deus único, imortal e invisível, sejam honra e glória para todo o sempre. Amém.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 18, 'Timóteo, meu filho, dou-lhe esta instrução, segundo as profecias já proferidas a seu respeito, para que, seguindo-as, você combata o bom combate,', 3, CURRENT_TIMESTAMP, false),
(54, 1, 19, 'mantendo a fé e a boa consciência que alguns rejeitaram e, por isso, naufragaram na fé.', 3, CURRENT_TIMESTAMP, false),
(54, 1, 20, 'Entre eles estão Himeneu e Alexandre, os quais entreguei a Satanás, para que aprendam a não blasfemar.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 1, 'Antes de tudo, recomendo que se façam súplicas, orações, intercessões e ação de graças por todos os homens;', 3, CURRENT_TIMESTAMP, false),
(54, 2, 2, 'pelos reis e por todos os que exercem autoridade, para que tenhamos uma vida tranqüila e pacífica, com toda a piedade e dignidade.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 3, 'Isso é bom e agradável perante Deus, nosso Salvador,', 3, CURRENT_TIMESTAMP, false),
(54, 2, 4, 'que deseja que todos os homens sejam salvos e cheguem ao conhecimento da verdade.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 5, 'Pois há um só Deus e um só mediador entre Deus e os homens: o homem Cristo Jesus,', 3, CURRENT_TIMESTAMP, false),
(54, 2, 6, 'o qual se entregou a si mesmo como resgate por todos. Esse foi o testemunho dado em seu próprio tempo.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 7, 'Para isso fui designado pregador e apóstolo mestre da verdadeira fé aos gentios. Digo-lhes a verdade, não minto.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 8, 'Quero, pois, que os homens orem em todo lugar, levantando mãos santas, sem ira e sem discussões.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 9, 'Da mesma forma quero que as mulheres se vistam modestamente, com decência e discrição, não se adornando com tranças, nem ouro, nem pérolas, nem roupas caras,', 3, CURRENT_TIMESTAMP, false),
(54, 2, 10, 'mas com boas obras, como convém a mulheres que professam adorar a Deus.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 11, 'A mulher deve aprender em silêncio, com toda a sujeição.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 12, 'Não permito que a mulher ensine, nem que tenha autoridade sobre o homem. Esteja, porém, em silêncio.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 13, 'Porque primeiro foi formado Adão, e depois Eva.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 14, 'E Adão não foi enganado, mas sim a mulher, que, tendo sido enganada, tornou-se transgressora.', 3, CURRENT_TIMESTAMP, false),
(54, 2, 15, 'Entretanto, a mulher será salva dando à luz filhos — se elas permanecerem na fé, no amor e na santidade, com bom senso.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 1, 'Esta afirmação é digna de confiança: se alguém deseja ser bispo, deseja uma nobre função.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 2, 'É necessário, pois, que o bispo seja irrepreensível, marido de uma só mulher, sóbrio, prudente, respeitável, hospitaleiro e apto para ensinar;', 3, CURRENT_TIMESTAMP, false),
(54, 3, 3, 'não deve ser apegado ao vinho, nem violento, mas sim amável, pacífico e não apegado ao dinheiro.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 4, 'Ele deve governar bem sua própria família, tendo os filhos sujeitos a ele, com toda a dignidade.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 5, 'Pois, se alguém não sabe governar sua própria família, como poderá cuidar da igreja de Deus?', 3, CURRENT_TIMESTAMP, false),
(54, 3, 6, 'Não pode ser recém-convertido, para que não se ensoberbeça e caia na mesma condenação em que caiu o diabo.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 7, 'Também deve ter boa reputação perante os de fora, para que não caia em descrédito nem na cilada do diabo.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 8, 'Os diáconos igualmente devem ser dignos, homens de palavra, não amigos de muito vinho nem de lucros desonestos.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 9, 'Devem apegar-se ao mistério da fé com a consciência limpa.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 10, 'Devem ser primeiramente experimentados; depois, se não houver nada contra eles, que atuem como diáconos.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 11, 'As mulheres igualmente sejam dignas, não caluniadoras, mas sóbrias e confiáveis em tudo.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 12, 'O diácono deve ser marido de uma só mulher e governar bem seus filhos e sua própria casa.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 13, 'Os que servirem bem alcançarão uma excelente posição e grande determinação na fé em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 14, 'Escrevo-lhe estas coisas embora espere ir vê-lo em breve;', 3, CURRENT_TIMESTAMP, false),
(54, 3, 15, 'mas, se eu demorar, saiba como as pessoas devem comportar-se na casa de Deus, que é a igreja do Deus vivo, coluna e fundamento da verdade.', 3, CURRENT_TIMESTAMP, false),
(54, 3, 16, 'Não há dúvida de que é grande o mistério da piedade: Deus foi manifestado em corpo, justificado no Espírito, visto pelos anjos, pregado entre as nações, crido no mundo, recebido na glória.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 1, 'O Espírito diz claramente que nos últimos tempos alguns abandonarão a fé e seguirão espíritos enganadores e doutrinas de demônios.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 2, 'Tais ensinamentos vêm de homens hipócritas e mentirosos, que têm a consciência cauterizada', 3, CURRENT_TIMESTAMP, false),
(54, 4, 3, 'e proíbem o casamento e o consumo de alimentos que Deus criou para serem recebidos com ação de graças pelos que crêem e conhecem a verdade.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 4, 'Pois tudo o que Deus criou é bom, e nada deve ser rejeitado, se for recebido com ação de graças,', 3, CURRENT_TIMESTAMP, false),
(54, 4, 5, 'pois é santificado pela palavra de Deus e pela oração.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 6, 'Se você transmitir essas instruções aos irmãos, será um bom ministro de Cristo Jesus, nutrido com as verdades da fé e da boa doutrina que tem seguido.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 7, 'Rejeite, porém, as fábulas profanas de velhas e exercite-se na piedade.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 8, 'O exercício físico é de pouco proveito; a piedade, porém, para tudo é proveitosa, porque tem promessa da vida presente e da futura.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 9, 'Esta é uma afirmação fiel e digna de plena aceitação.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 10, 'Se trabalhamos e lutamos é porque temos colocado a nossa esperança no Deus vivo, o Salvador de todos os homens, especialmente dos que crêem.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 11, 'Ordene e ensine estas coisas.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 12, 'Ninguém o despreze pelo fato de você ser jovem, mas seja um exemplo para os fiéis na palavra, no procedimento, no amor, na fé e na pureza.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 13, 'Até a minha chegada, dedique-se à leitura pública da Escritura, à exortação e ao ensino.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 14, 'Não negligencie o dom que lhe foi dado por mensagem profética com imposição de mãos dos presbíteros.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 15, 'Seja diligente nestas coisas; dedique-se inteiramente a elas, para que todos vejam o seu progresso.', 3, CURRENT_TIMESTAMP, false),
(54, 4, 16, 'Atente bem para a sua própria vida e para a doutrina, perseverando nesses deveres, pois, fazendo isso, você salvará tanto a si mesmo quanto aos que o ouvem.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 1, 'Não repreenda asperamente ao homem idoso, mas exorte-o como se ele fosse seu pai; trate os jovens como a irmãos;', 3, CURRENT_TIMESTAMP, false),
(54, 5, 2, 'as mulheres idosas, como a mães; e as moças, como a irmãs, com toda a pureza.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 3, 'Trate adequadamente as viúvas que são realmente necessitadas.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 4, 'Mas se uma viúva tem filhos ou netos, que estes aprendam primeiramente a colocar a sua religião em prática, cuidando de sua própria família e retribuindo o bem recebido de seus pais e avós, pois isso agrada a Deus.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 5, 'A viúva realmente necessitada e desamparada põe sua esperança em Deus e persiste dia e noite em oração e em súplica.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 6, 'Mas a que vive para os prazeres, ainda que esteja viva, está morta.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 7, 'Ordene estas coisas para que sejam irrepreensíveis.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 8, 'Se alguém não cuida de seus parentes, e especialmente dos de sua própria família, negou a fé e é pior que um descrente.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 9, 'Nenhuma mulher deve ser inscrita na lista de viúvas, a não ser que tenha mais de sessenta anos de idade, tenha sido fiel a seu marido', 3, CURRENT_TIMESTAMP, false),
(54, 5, 10, 'e seja bem conhecida por suas boas obras, tais como criar filhos, ser hospitaleira, lavar os pés dos santos, socorrer os atribulados e dedicar-se a todo tipo de boa obra.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 11, 'Não inclua nessa lista as viúvas mais jovens, pois, quando os seus desejos sensuais superam a sua dedicação a Cristo, querem se casar.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 12, 'Assim, elas trazem condenação sobre si, por haverem rompido seu primeiro compromisso.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 13, 'Além disso, aprendem a ficar ociosas, andando de casa em casa; e não se tornam apenas ociosas, mas também fofoqueiras e indiscretas, falando coisas que não devem.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 14, 'Portanto, aconselho que as viúvas mais jovens se casem, tenham filhos, administrem suas casas e não dêem ao inimigo nenhum motivo para maledicência.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 15, 'Algumas, na verdade, já se desviaram, para seguir a Satanás.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 16, 'Se alguma mulher crente tem viúvas em sua família, deve ajudá-las. Não seja a igreja sobrecarregada com elas, a fim de que as viúvas realmente necessitadas sejam auxiliadas.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 17, 'Os presbíteros que lideram bem a igreja são dignos de dupla honra, especialmente aqueles cujo trabalho é a pregação e o ensino,', 3, CURRENT_TIMESTAMP, false),
(54, 5, 18, 'pois a Escritura diz: "Não amordace o boi enquanto está debulhando o cereal", e "o trabalhador merece o seu salário".', 3, CURRENT_TIMESTAMP, false),
(54, 5, 19, 'Não aceite acusação contra um presbítero, se não for apoiada por duas ou três testemunhas.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 20, 'Os que pecarem deverão ser repreendidos em público, para que os demais também temam.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 21, 'Eu o exorto solenemente, diante de Deus, de Cristo Jesus e dos anjos eleitos, a que procure observar essas instruções sem parcialidade; e não faça nada por favoritismo.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 22, 'Não se precipite em impor as mãos sobre ninguém e não participe dos pecados dos outros. Conserve-se puro.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 23, 'Não continue a beber somente água; tome também um pouco de vinho, por causa do seu estômago e das suas freqüentes enfermidades.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 24, 'Os pecados de alguns são evidentes, mesmo antes de serem submetidos a julgamento; enquanto que os pecados de outros se manifestam posteriormente.', 3, CURRENT_TIMESTAMP, false),
(54, 5, 25, 'Da mesma forma, as boas obras são evidentes, e as que não o são não podem permanecer ocultas.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 1, 'Todos os que estão sob o jugo da escravidão devem considerar seus senhores como dignos de todo o respeito, para que o nome de Deus e o nosso ensino não sejam blasfemados.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 2, 'Os que têm senhores crentes não devem ter por eles menos respeito, pelo fato de serem irmãos; pelo contrário, devem servi-los ainda melhor, porque os que se beneficiam do seu serviço são fiéis e amados. Ensine e recomende essas coisas.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 3, 'Se alguém ensina falsas doutrinas e não concorda com a sã doutrina de nosso Senhor Jesus Cristo e com o ensino que é segundo a piedade,', 3, CURRENT_TIMESTAMP, false),
(54, 6, 4, 'é orgulhoso e nada entende. Esse tal mostra um interesse doentio por controvérsias e contendas acerca de palavras, que resultam em inveja, brigas, difamações, suspeitas malignas', 3, CURRENT_TIMESTAMP, false),
(54, 6, 5, 'e atritos constantes entre pessoas que têm a mente corrompida e que são privados da verdade, os quais pensam que a piedade é fonte de lucro.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 6, 'De fato, a piedade com contentamento é grande fonte de lucro,', 3, CURRENT_TIMESTAMP, false),
(54, 6, 7, 'pois nada trouxemos para este mundo e dele nada podemos levar;', 3, CURRENT_TIMESTAMP, false),
(54, 6, 8, 'por isso, tendo o que comer e com que vestir-nos, estejamos com isso satisfeitos.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 9, 'Os que querem ficar ricos caem em tentação, em armadilhas e em muitos desejos descontrolados e nocivos, que levam os homens a mergulharem na ruína e na destruição,', 3, CURRENT_TIMESTAMP, false),
(54, 6, 10, 'pois o amor ao dinheiro é raiz de todos os males. Algumas pessoas, por cobiçarem o dinheiro, desviaram-se da fé e se atormentaram a si mesmas com muitos sofrimentos.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 11, 'Você, porém, homem de Deus, fuja de tudo isso e busque a justiça, a piedade, a fé, o amor, a perseverança e a mansidão.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 12, 'Combata o bom combate da fé. Tome posse da vida eterna, para a qual você foi chamado e fez a boa confissão na presença de muitas testemunhas.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 13, 'Diante de Deus, que a tudo dá vida, e de Cristo Jesus, que diante de Pôncio Pilatos fez a boa confissão, eu lhe recomendo:', 3, CURRENT_TIMESTAMP, false),
(54, 6, 14, 'Guarde este mandamento imaculado, irrepreensível, até a manifestação de nosso Senhor Jesus Cristo,', 3, CURRENT_TIMESTAMP, false),
(54, 6, 15, 'a qual Deus fará se cumprir no seu devido tempo. Ele é o bendito e único Soberano, o Rei dos reis e Senhor dos senhores,', 3, CURRENT_TIMESTAMP, false),
(54, 6, 16, 'o único que é imortal e habita em luz inacessível, a quem ninguém viu nem pode ver. A ele sejam honra e poder para sempre. Amém.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 17, 'Ordene aos que são ricos no presente mundo que não sejam arrogantes, nem ponham sua esperança na incerteza da riqueza, mas em Deus, que de tudo nos provê ricamente, para a nossa satisfação.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 18, 'Ordene-lhes que pratiquem o bem, sejam ricos em boas obras, generosos e prontos para repartir.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 19, 'Dessa forma, eles acumularão um tesouro para si mesmos, um firme fundamento para a era que há de vir, e assim alcançarão a verdadeira vida.', 3, CURRENT_TIMESTAMP, false),
(54, 6, 20, 'Timóteo, guarde o que lhe foi confiado. Evite as conversas inúteis e profanas e as idéias contraditórias do que é falsamente chamado conhecimento;', 3, CURRENT_TIMESTAMP, false),
(54, 6, 21, 'professando-o, alguns desviaram-se da fé. A graça seja com vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, e o irmão Timóteo, à igreja de Deus que está em Corinto, juntamente com todos os santos de toda a Acaia:', 3, CURRENT_TIMESTAMP, false),
(47, 1, 2, 'A vocês, graça e paz da parte de Deus nosso Pai e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, Pai das misericórdias e Deus de toda consolação,', 3, CURRENT_TIMESTAMP, false),
(47, 1, 4, 'que nos consola em todas as nossas tribulações, para que, com a consolação que recebemos de Deus, possamos consolar os que estão passando por tribulações.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 5, 'Pois assim como os sofrimentos de Cristo transbordam sobre nós, também por meio de Cristo transborda a nossa consolação.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 6, 'Se somos atribulados, é para consolação e salvação de vocês; se somos consolados, é para consolação de vocês, a qual lhes dá paciência para suportarem os mesmos sofrimentos que nós estamos padecendo.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 7, 'E a nossa esperança em relação a vocês está firme, porque sabemos que, da mesma forma como vocês participam dos nossos sofrimentos, participam também da nossa consolação.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 8, 'Irmãos, não queremos que vocês desconheçam as tribulações que sofremos na província da Ásia, as quais foram muito além da nossa capacidade de suportar, a ponto de perdermos a esperança da própria vida.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 9, 'De fato, já tínhamos sobre nós a sentença de morte, para que não confiássemos em nós mesmos, mas em Deus, que ressuscita os mortos.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 10, 'Ele nos livrou e continuará nos livrando de tal perigo de morte. Nele temos colocado a nossa esperança de que continuará a livrar-nos,', 3, CURRENT_TIMESTAMP, false),
(47, 1, 11, 'enquanto vocês nos ajudam com as suas orações. Assim muitos darão graças por nossa causa, pelo favor a nós concedido em resposta às orações de muitos.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 12, 'Este é o nosso orgulho: A nossa consciência dá testemunho de que nos temos conduzido no mundo, especialmente em nosso relacionamento com vocês, com santidade e sinceridade provenientes de Deus, não de acordo com a sabedoria do mundo, mas de acordo com a graça de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 13, 'Pois nada lhes escrevemos que vocês não sejam capazes de ler ou entender. E espero que,', 3, CURRENT_TIMESTAMP, false),
(47, 1, 14, 'assim como vocês nos entenderam em parte, venham a entender plenamente que podem orgulhar-se de nós, assim como nos orgulharemos de vocês no dia do Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 15, 'Confiando nisso, e para que vocês fossem duplamente beneficiados, planejava primeiro visitá-los', 3, CURRENT_TIMESTAMP, false),
(47, 1, 16, 'em minha ida à Macedônia e voltar a vocês vindo de lá, para que me ajudassem em minha viagem para a Judéia.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 17, 'Quando planejei isso, será que o fiz levianamente? Ou será que faço meus planos de modo mundano, dizendo ao mesmo tempo "sim" e "não"?', 3, CURRENT_TIMESTAMP, false),
(47, 1, 18, 'Todavia, como Deus é fiel, nossa mensagem a vocês não é "sim" e "não",', 3, CURRENT_TIMESTAMP, false),
(47, 1, 19, 'pois o Filho de Deus, Jesus Cristo, pregado entre vocês por mim e também por Silvano e Timóteo, não foi "sim" e "não", mas nele sempre houve "sim";', 3, CURRENT_TIMESTAMP, false),
(47, 1, 20, 'pois quantas forem as promessas feitas por Deus, tantas têm em Cristo o "sim". Por isso, por meio dele, o "Amém" é pronunciado por nós para a glória de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 21, 'Ora, é Deus que faz que nós e vocês permaneçamos firmes em Cristo. Ele nos ungiu,', 3, CURRENT_TIMESTAMP, false),
(47, 1, 22, 'nos selou como sua propriedade e pôs o seu Espírito em nossos corações como garantia do que está por vir.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 23, 'Invoco a Deus como testemunha de que foi a fim de poupá-los que não voltei a Corinto.', 3, CURRENT_TIMESTAMP, false),
(47, 1, 24, 'Não que tenhamos domínio sobre a sua fé, mas cooperamos com vocês para que tenham alegria, pois é pela fé que vocês permanecem firmes.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 1, 'De modo que resolvi não lhes fazer outra visita que causasse tristeza.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 2, 'Pois, se os entristeço, quem me alegrará senão vocês, a quem tenho entristecido?', 3, CURRENT_TIMESTAMP, false),
(47, 2, 3, 'Escrevi como escrevi para que, quando eu for, não seja entristecido por aqueles que deveriam alegrar-me. Estava confiante em que todos vocês compartilhariam da minha alegria.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 4, 'Pois eu lhes escrevi com grande aflição e angústia de coração, e com muitas lágrimas: não para entristecê-los, mas para que soubessem como e profundo o meu amor por vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 5, 'Se alguém tem causado tristeza, não o tem causado apenas a mim, mas também, em parte, para eu não ser demasiadamente severo, a todos vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 6, 'A punição que lhe foi imposta pela maioria é suficiente.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 7, 'Agora, pelo contrário, vocês devem perdoar-lhe e consolá-lo, para que ele não seja dominado por excessiva tristeza.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 8, 'Portanto, eu lhes recomendo que reafirmem o amor que têm por ele.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 9, 'Eu lhes escrevi com o propósito de saber se vocês seriam aprovados, isto é, se seriam obedientes em tudo.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 10, 'Se vocês perdoam a alguém, eu também perdôo; e aquilo que perdoei, se é que havia alguma coisa para perdoar, perdoei na presença de Cristo, por amor a vocês,', 3, CURRENT_TIMESTAMP, false),
(47, 2, 11, 'a fim de que Satanás não tivesse vantagem sobre nós; pois não ignoramos as suas intenções.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 12, 'Quando cheguei a Trôade para pregar o evangelho de Cristo e vi que o Senhor me havia aberto uma porta,', 3, CURRENT_TIMESTAMP, false),
(47, 2, 13, 'ainda assim, não tive sossego em meu espírito, porque não encontrei ali meu irmão Tito. Por isso, despedi-me deles e fui para a Macedônia.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 14, 'Mas graças a Deus, que sempre nos conduz vitoriosamente em Cristo e por nosso intermédio exala em todo lugar a fragrância do seu conhecimento;', 3, CURRENT_TIMESTAMP, false),
(47, 2, 15, 'porque para Deus somos o aroma de Cristo entre os que estão sendo salvos e os que estão perecendo.', 3, CURRENT_TIMESTAMP, false),
(47, 2, 16, 'Para estes somos cheiro de morte; para aqueles fragrância de vida. Mas, quem está capacitado para tanto?', 3, CURRENT_TIMESTAMP, false),
(47, 2, 17, 'Ao contrário de muitos, não negociamos a palavra de Deus visando lucro; antes, em Cristo falamos diante de Deus com sinceridade, como homens enviados por Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 1, 'Será que com isso, estamos começando a nos recomendar a nós mesmos novamente? Será que precisamos, como alguns, de cartas de recomendação para vocês ou da parte de vocês?', 3, CURRENT_TIMESTAMP, false),
(47, 3, 2, 'Vocês mesmos são a nossa carta, escrita em nosso coração, conhecida e lida por todos.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 3, 'Vocês demonstram que são uma carta de Cristo, resultado do nosso ministério, escrita não com tinta, mas com o Espírito do Deus vivo, não em tábuas de pedra, mas em tábuas de corações humanos.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 4, 'Tal é a confiança que temos diante de Deus, por meio de Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 5, 'Não que possamos reivindicar qualquer coisa com base em nossos próprios méritos, mas a nossa capacidade vem de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 6, 'Ele nos capacitou para sermos ministros de uma nova aliança, não da letra, mas do Espírito; pois a letra mata, mas o Espírito vivifica.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 7, 'O ministério que trouxe a morte foi gravado com letras em pedras; mas esse ministério veio com tal glória que os israelitas não podiam fixar os olhos na face de Moisés por causa do resplendor do seu rosto, ainda que desvanecente.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 8, 'Não será o ministério do Espírito ainda muito mais glorioso?', 3, CURRENT_TIMESTAMP, false),
(47, 3, 9, 'Se era glorioso o ministério que trouxe condenação, quanto mais glorioso será o ministério que produz justiça!', 3, CURRENT_TIMESTAMP, false),
(47, 3, 10, 'Pois o que outrora foi glorioso, agora não tem glória, em comparação com a glória insuperável.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 11, 'E se o que estava se desvanecendo se manifestou com glória, quanto maior será a glória do que permanece!', 3, CURRENT_TIMESTAMP, false),
(47, 3, 12, 'Portanto, visto que temos tal esperança, mostramos muita confiança.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 13, 'Não somos como Moisés, que colocava um véu sobre a face para que os israelitas não contemplassem o resplendor que se desvanecia.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 14, 'Na verdade as mentes deles se fecharam, pois até hoje o mesmo véu permanece quando é lida a antiga aliança. Não foi retirado, porque é somente em Cristo que ele é removido.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 15, 'De fato, até o dia de hoje, quando Moisés é lido, um véu cobre os seus corações.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 16, 'Mas quando alguém se converte ao Senhor, o véu é retirado.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 17, 'Ora, o Senhor é o Espírito e, onde está o Espírito do Senhor, ali há liberdade.', 3, CURRENT_TIMESTAMP, false),
(47, 3, 18, 'E todos nós, que com a face descoberta contemplamos a glória do Senhor, segundo a sua imagem estamos sendo transformados com glória cada vez maior, a qual vem do Senhor, que é o Espírito.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 1, 'Portanto, visto que temos este ministério pela misericórdia que nos foi dada, não desanimamos.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 2, 'Antes, renunciamos aos procedimentos secretos e vergonhosos; não usamos de engano nem torcemos a palavra de Deus. Pelo contrário, mediante a clara exposição da verdade, recomendamo-nos à consciência de todos, diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 3, 'Mas se o nosso evangelho está encoberto, para os que estão perecendo é que está encoberto.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 4, 'O deus desta era cegou o entendimento dos descrentes, para que não vejam a luz do evangelho da glória de Cristo, que é a imagem de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 5, 'Pois não nos pregamos a nós mesmos, mas a Jesus Cristo, o Senhor, e a nós como escravos de vocês, por amor de Jesus.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 6, 'Pois Deus que disse: "Das trevas resplandeça a luz", ele mesmo brilhou em nossos corações, para iluminação do conhecimento da glória de Deus na face de Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 7, 'Mas temos esse tesouro em vasos de barro, para mostrar que este poder que a tudo excede provém de Deus, e não de nós.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 8, 'De todos os lados somos pressionados, mas não desanimados; ficamos perplexos, mas não desesperados;', 3, CURRENT_TIMESTAMP, false),
(47, 4, 9, 'somos perseguidos, mas não abandonados; abatidos, mas não destruídos.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 10, 'Trazemos sempre em nosso corpo o morrer de Jesus, para que a vida de Jesus também seja revelada em nosso corpo.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 11, 'Pois nós, que estamos vivos, somos sempre entregues à morte por amor a Jesus, para que a sua vida também se manifeste em nosso corpo mortal.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 12, 'De modo que em nós atua a morte; mas em vocês, a vida.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 13, 'Está escrito: "Cri, por isso falei". Com esse mesmo espírito de fé nós também cremos e, por isso, falamos,', 3, CURRENT_TIMESTAMP, false),
(47, 4, 14, 'porque sabemos que aquele que ressuscitou ao Senhor Jesus dentre os mortos, também nos ressuscitará com Jesus e nos apresentará com vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 15, 'Tudo isso é para o bem de vocês, para que a graça, que está alcançando um número cada vez maior de pessoas, faça que transbordem as ações de graças para a glória de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 16, 'Por isso não desanimamos. Embora exteriormente estejamos a desgastar-nos, interiormente estamos sendo renovados dia após dia,', 3, CURRENT_TIMESTAMP, false),
(47, 4, 17, 'pois os nossos sofrimentos leves e momentâneos estão produzindo para nós uma glória eterna que pesa mais do que todos eles.', 3, CURRENT_TIMESTAMP, false),
(47, 4, 18, 'Assim, fixamos os olhos, não naquilo que se vê, mas no que não se vê, pois o que se vê é transitório, mas o que não se vê é eterno.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 1, 'Sabemos que, se for destruída a temporária habitação terrena em que vivemos, temos da parte de Deus um edifício, uma casa eterna no céu, não construída por mãos humanas.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 2, 'Enquanto isso, gememos, desejando ser revestidos da nossa habitação celestial,', 3, CURRENT_TIMESTAMP, false),
(47, 5, 3, 'porque, estando vestidos, não seremos encontrados nus.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 4, 'Pois, enquanto estamos nesta casa, gememos e nos angustiamos, porque não queremos ser despidos, mas revestidos da nossa habitação celestial, para que aquilo que é mortal seja absorvido pela vida.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 5, 'Foi Deus que nos preparou para esse propósito, dando-nos o Espírito como garantia do que está por vir.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 6, 'Portanto, temos sempre confiança e sabemos que, enquanto estamos no corpo, estamos longe do Senhor.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 7, 'Porque vivemos por fé, e não pelo que vemos.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 8, 'Temos, pois, confiança e preferimos estar ausentes do corpo e habitar com o Senhor.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 9, 'Por isso, temos o propósito de lhe agradar, quer estejamos no corpo, quer o deixemos.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 10, 'Pois todos nós devemos comparecer perante o tribunal de Cristo, para que cada um receba de acordo com as obras praticadas por meio do corpo, quer sejam boas quer sejam más.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 11, 'Uma vez que conhecemos o temor ao Senhor, procuramos persuadir os homens. O que somos está manifesto diante de Deus, e esperamos que esteja manifesto também diante da consciência de vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 12, 'Não estamos tentando novamente recomendar-nos a vocês, porém lhes estamos dando a oportunidade de exultarem em nós, para que tenham o que responder aos que se vangloriam das aparências e não do que está no coração.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 13, 'Se enlouquecemos, é por amor a Deus; se conservamos o juízo, é por amor a vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 14, 'Pois o amor de Cristo nos constrange, porque estamos convencidos de que um morreu por todos; logo, todos morreram.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 15, 'E ele morreu por todos para que aqueles que vivem já não vivam mais para si mesmos, mas para aquele que por eles morreu e ressuscitou.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 16, 'De modo que, de agora em diante, a ninguém mais consideramos do ponto de vista humano. Ainda que antes tenhamos considerado a Cristo dessa forma, agora já não o consideramos assim.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 17, 'Portanto, se alguém está em Cristo, é nova criação. As coisas antigas já passaram; eis que surgiram coisas novas!', 3, CURRENT_TIMESTAMP, false),
(47, 5, 18, 'Tudo isso provém de Deus, que nos reconciliou consigo mesmo por meio de Cristo e nos deu o ministério da reconciliação,', 3, CURRENT_TIMESTAMP, false),
(47, 5, 19, 'ou seja, que Deus em Cristo estava reconciliando consigo o mundo, não lançando em conta os pecados dos homens, e nos confiou a mensagem da reconciliação.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 20, 'Portanto, somos embaixadores de Cristo, como se Deus estivesse fazendo o seu apelo por nosso intermédio. Por amor a Cristo lhes suplicamos: Reconciliem-se com Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 5, 21, 'Deus tornou pecado por nós aquele que não tinha pecado, para que nele nos tornássemos justiça de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 6, 1, 'Como cooperadores de Deus, insistimos com vocês para não receberem em vão a graça de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 6, 2, 'Pois ele diz: "Eu o ouvi no tempo favorável e o socorri no dia da salvação". Digo-lhes que agora é o tempo favorável, agora é o dia da salvação!', 3, CURRENT_TIMESTAMP, false),
(47, 6, 3, 'Não damos motivo de escândalo a ninguém, em circunstância alguma, para que o nosso ministério não caia em descrédito.', 3, CURRENT_TIMESTAMP, false),
(47, 6, 4, 'Pelo contrário, como servos de Deus, recomendamo-nos de todas as formas: em muita perseverança; em sofrimentos, privações e tristezas;', 3, CURRENT_TIMESTAMP, false),
(47, 6, 5, 'em açoites, prisões e tumultos; em trabalhos árduos, noites sem dormir e jejuns;', 3, CURRENT_TIMESTAMP, false),
(47, 6, 6, 'em pureza, conhecimento, paciência e bondade; no Espírito Santo e no amor sincero;', 3, CURRENT_TIMESTAMP, false),
(47, 6, 7, 'na palavra da verdade e no poder de Deus; com as armas da justiça, quer de ataque, quer de defesa;', 3, CURRENT_TIMESTAMP, false),
(47, 6, 8, 'por honra e por desonra; por difamação e por boa fama; tidos por enganadores, sendo verdadeiros;', 3, CURRENT_TIMESTAMP, false),
(47, 6, 9, 'como desconhecidos, apesar de bem conhecidos; como morrendo, mas eis que vivemos; espancados, mas não mortos;', 3, CURRENT_TIMESTAMP, false),
(47, 6, 10, 'entristecidos, mas sempre alegres; pobres, mas enriquecendo a muitos; nada tendo, mas possuindo tudo.', 3, CURRENT_TIMESTAMP, false),
(47, 6, 11, 'Falamos abertamente a vocês, coríntios, e lhes abrimos todo o nosso coração!', 3, CURRENT_TIMESTAMP, false),
(47, 6, 12, 'Não lhes estamos limitando nosso afeto, mas vocês nos estão limitando o afeto que têm por nós.', 3, CURRENT_TIMESTAMP, false),
(47, 6, 13, 'Numa justa compensação, falo como a meus filhos, abram também o coração para nós!', 3, CURRENT_TIMESTAMP, false),
(47, 6, 14, 'Não se ponham em jugo desigual com descrentes. Pois o que têm em comum a justiça e a maldade? Ou que comunhão pode ter a luz com as trevas?', 3, CURRENT_TIMESTAMP, false),
(47, 6, 15, 'Que harmonia entre Cristo e Belial? Que há de comum entre o crente e o descrente?', 3, CURRENT_TIMESTAMP, false),
(47, 6, 16, 'Que acordo há entre o templo de Deus e os ídolos? Pois somos santuário do Deus vivo. Como disse Deus: "Habitarei com eles e entre eles andarei; serei o seu Deus, e eles serão o meu povo".', 3, CURRENT_TIMESTAMP, false),
(47, 6, 17, 'Portanto, "saiam do meio deles e separem-se", diz o Senhor. "Não toquem em coisas impuras, e eu os receberei"', 3, CURRENT_TIMESTAMP, false),
(47, 6, 18, '"e lhes serei Pai, e vocês serão meus filhos e minhas filhas", diz o Senhor Todo-poderoso.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 1, 'Amados, visto que temos essas promessas, purifiquemo-nos de tudo o que contamina o corpo e o espírito, aperfeiçoando a santidade no temor de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 2, 'Concedam-nos lugar no coração de vocês. A ninguém prejudicamos, a ninguém causamos dano, a ninguém exploramos.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 3, 'Não digo isso para condená-los; já lhes disse que vocês estão em nosso coração para juntos morrermos ou vivermos.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 4, 'Tenho grande confiança em vocês, e de vocês tenho muito orgulho. Sinto-me bastante encorajado; minha alegria transborda em todas as tribulações.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 5, 'Pois, quando chegamos à Macedônia, não tivemos nenhum descanso, mas fomos atribulados de toda forma: conflitos externos, temores internos.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 6, 'Deus, porém, que consola os abatidos, consolou-nos com a chegada de Tito,', 3, CURRENT_TIMESTAMP, false),
(47, 7, 7, 'e não apenas com a vinda dele, mas também com a consolação que vocês lhe ministraram. Ele nos falou da saudade, da tristeza e da preocupação de vocês por mim, de modo que a minha alegria se tornou ainda maior.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 8, 'Mesmo que a minha carta lhes tenha causado tristeza, não me arrependo. É verdade que a princípio me arrependi, pois percebi que a minha carta os entristeceu, ainda que por pouco tempo. 9 Agora, porém, me alegro, não porque vocês foram entristecidos, mas porque a tristeza os levou ao arrependimento. Pois vocês se entristeceram como Deus desejava, e de forma alguma foram prejudicados por nossa causa.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 9, 'A tristeza segundo Deus produz um arrependimento que leva à salvação e não remorso, mas a tristeza segundo o mundo produz morte.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 10, 'Vejam o que esta tristeza segundo Deus produziu em vocês: que dedicação, que desculpas, que indignação, que temor, que saudade, que preocupação, que desejo de ver a justiça feita! Em tudo vocês se mostraram inocentes a esse respeito.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 11, 'Assim, se lhes escrevi, não foi por causa daquele que cometeu o erro nem daquele que foi prejudicado, mas para que diante de Deus vocês pudessem ver por si próprios como são dedicados a nós.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 12, 'Por isso tudo fomos revigorados.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 13, 'de encorajados, ficamos mais contentes ainda ao ver como Tito estava alegre, porque seu espírito recebeu refrigério de todos vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 14, 'Eu lhe tinha dito que estava orgulhoso de vocês, e vocês não me decepcionaram. Da mesma forma como era verdade tudo o que lhes dissemos, o orgulho que temos de vocês diante de Tito também mostrou-se verdadeiro.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 15, 'E a afeição dele por vocês fica maior ainda, quando lembra que todos vocês foram obedientes, recebendo-o com temor e tremor.', 3, CURRENT_TIMESTAMP, false),
(47, 7, 16, 'Alegro-me por poder ter plena confiança em vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 1, 'Agora, irmãos, queremos que vocês tomem conhecimento da graça que Deus concedeu às igrejas da Macedônia.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 2, 'No meio da mais severa tribulação, a grande alegria e a extrema pobreza deles transbordaram em rica generosidade.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 3, 'Pois dou testemunho de que eles deram tudo quanto podiam, e até além do que podiam. Por iniciativa própria', 3, CURRENT_TIMESTAMP, false),
(47, 8, 4, 'eles nos suplicaram insistentemente o privilégio de participar da assistência aos santos.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 5, 'E não somente fizeram o que esperávamos, mas entregaram-se primeiramente a si mesmos ao Senhor e, depois, a nós, pela vontade de Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 6, 'Assim, recomendamos a Tito, visto que ele já havia começado, que completasse esse ato de graça da parte de vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 7, 'Todavia, assim como vocês se destacam em tudo: na fé, na palavra, no conhecimento, na dedicação completa e no amor que vocês têm por nós, destaquem-se também neste privilégio de contribuir.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 8, 'Não lhes estou dando uma ordem, mas quero verificar a sinceridade do amor de vocês, comparando-o com a dedicação dos outros.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 9, 'Pois vocês conhecem a graça de nosso Senhor Jesus Cristo que, sendo rico, se fez pobre por amor de vocês, para que por meio de sua pobreza vocês se tornassem ricos.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 10, 'Este é meu conselho: convém que vocês contribuam, já que desde o ano passado vocês foram os primeiros, não somente a contribuir, mas também a propor esse plano.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 11, 'Agora, completem a obra, para que a forte disposição de realizá-la seja igualada pelo zelo em concluí-la, de acordo com os bens que vocês possuem.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 12, 'Porque, se há prontidão, a contribuição é aceitável de acordo com aquilo que alguém tem, e não de acordo com o que não tem.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 13, 'Nosso desejo não é que outros sejam aliviados enquanto vocês são sobrecarregados, mas que haja igualdade.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 14, 'No presente momento, a fartura de vocês suprirá a necessidade deles, para que, por sua vez, a fartura deles supra a necessidade de vocês. Então haverá igualdade,', 3, CURRENT_TIMESTAMP, false),
(47, 8, 15, 'como está escrito: "Quem tinha recolhido muito não teve demais, e não faltou a quem tinha recolhido pouco".', 3, CURRENT_TIMESTAMP, false),
(47, 8, 16, 'Agradeço a Deus, que pôs no coração de Tito o mesmo cuidado que tenho por vocês,', 3, CURRENT_TIMESTAMP, false),
(47, 8, 17, 'pois Tito não apenas aceitou o nosso pedido, mas está indo até vocês, com muito entusiasmo e por iniciativa própria.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 18, 'Com ele estamos enviando o irmão que é recomendado por todas as igrejas por seu serviço no evangelho.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 19, 'Não só por isso, mas ele também foi escolhido pelas igrejas para nos acompanhar quando formos ministrar esta doação, o que fazemos para honrar o próprio Senhor e mostrar a nossa disposição.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 20, 'Queremos evitar que alguém nos critique quanto ao nosso modo de ministrar essa generosa oferta,', 3, CURRENT_TIMESTAMP, false),
(47, 8, 21, 'pois estamos tendo o cuidado de fazer o que é correto, não apenas aos olhos do Senhor, mas também aos olhos dos homens.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 22, 'Além disso, estamos enviando com eles o nosso irmão que muitas vezes e de muitas maneiras já nos provou que é muito dedicado, e agora ainda mais, por causa da grande confiança que ele tem em vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 23, 'Quanto a Tito, ele é meu companheiro e cooperador entre vocês; quanto a nossos irmãos, eles são representantes das igrejas e uma honra para Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 8, 24, 'Portanto, diante das demais igrejas, demonstrem a esses irmãos a prova do amor que vocês têm e a razão do orgulho que temos de vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 1, 'Não tenho necessidade de escrever-lhes a respeito dessa assistência aos santos.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 2, 'Reconheço a sua disposição em ajudar e já mostrei aos macedônios o orgulho que tenho de vocês, dizendo-lhes que, desde o ano passado, vocês da Acaia estavam prontos a contribuir; e a dedicação de vocês motivou a muitos.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 3, 'Contudo, estou enviando os irmãos para que o orgulho que temos de vocês a esse respeito não seja em vão, mas que vocês estejam preparados, como eu disse que estariam,', 3, CURRENT_TIMESTAMP, false),
(47, 9, 4, 'a fim de que, se alguns macedônios forem comigo e os encontrarem despreparados, nós, para não mencionar vocês, não fiquemos envergonhados por tanta confiança que tivemos.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 5, 'Assim, achei necessário recomendar que os irmãos os visitem antes e concluam os preparativos para a contribuição que vocês prometeram. Então ela estará pronta como oferta generosa, e não como algo dado com avareza.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 6, 'Lembrem-se: aquele que semeia pouco, também colherá pouco, e aquele que semeia com fartura, também colherá fartamente.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 7, 'Cada um dê conforme determinou em seu coração, não com pesar ou por obrigação, pois Deus ama quem dá com alegria.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 8, 'E Deus é poderoso para fazer que lhes seja acrescentada toda a graça, para que em todas as coisas, em todo o tempo, tendo tudo o que é necessário, vocês transbordem em toda boa obra.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 9, 'Como está escrito: "Distribuiu, deu os seus bens aos necessitados; a sua justiça dura para sempre".', 3, CURRENT_TIMESTAMP, false),
(47, 9, 10, 'Aquele que supre a semente ao que semeia e o pão ao que come, também lhes suprirá e aumentará a semente e fará crescer os frutos da sua justiça.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 11, 'Vocês serão enriquecidos de todas as formas, para que possam ser generosos em qualquer ocasião e, por nosso intermédio, a sua generosidade resulte em ação de graças a Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 12, 'O serviço ministerial que vocês estão realizando não está apenas suprindo as necessidades do povo de Deus, mas também transbordando em muitas expressões de gratidão a Deus.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 13, 'Por meio dessa prova de serviço ministerial, outros louvarão a Deus pela obediência que acompanha a confissão que vocês fazem do evangelho de Cristo e pela generosidade de vocês em compartilhar seus bens com eles e com todos os outros.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 14, 'E nas orações que fazem por vocês, eles estarão cheios de amor por vocês, por causa da insuperável graça que Deus tem dado a vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 9, 15, 'Graças a Deus por seu dom indescritível!', 3, CURRENT_TIMESTAMP, false),
(47, 10, 1, 'Eu, Paulo, pela mansidão e pela bondade de Cristo, apelo para vocês; eu, que sou "humilde" quando estou face a face com vocês, mas "audaz" quando ausente!', 3, CURRENT_TIMESTAMP, false),
(47, 10, 2, 'Rogo-lhes que, quando estiver presente, não me obriguem a agir com audácia, tal como penso que ousarei fazer, para com alguns que acham que procedemos segundo os padrões humanos.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 3, 'Pois, embora vivamos como homens, não lutamos segundo os padrões humanos.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 4, 'As armas com as quais lutamos não são humanas; pelo contrário, são poderosas em Deus para destruir fortalezas.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 5, 'Destruímos argumentos e toda pretensão que se levanta contra o conhecimento de Deus, e levamos cativo todo pensamento, para torná-lo obediente a Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 6, 'E estaremos prontos para punir todo ato de desobediência, uma vez completa a obediência de vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 7, 'Vocês observam apenas a aparência das coisas. Se alguém está convencido de que pertence a Cristo, deveria considerar novamente consigo mesmo que, assim como ele, nós também pertencemos a Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 8, 'Pois mesmo que eu tenha me orgulhado um pouco mais da autoridade que o Senhor nos deu, não me envergonho disso, pois essa autoridade é para edificá-los, e não para destruí-los.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 9, 'Não quero que pareça que estou tentando amedrontá-los com as minhas cartas.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 10, 'Pois alguns dizem: "As cartas dele são duras e fortes, mas ele pessoalmente não impressiona, e a sua palavra é desprezível".', 3, CURRENT_TIMESTAMP, false),
(47, 10, 11, 'Saibam tais pessoas que aquilo que somos em cartas, quando estamos ausentes, seremos em atos, quando estivermos presentes.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 12, 'Não temos a pretensão de nos igualar ou de nos comparar com alguns que se recomendam a si mesmos. Quando eles se medem e se comparam consigo mesmos, agem sem entendimento.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 13, 'Nós, porém, não nos gloriaremos além do limite adequado, mas limitaremos nosso orgulho à esfera de ação que Deus nos confiou, a qual alcança vocês inclusive.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 14, 'Não estamos indo longe demais em nosso orgulho, como seria o caso se não tivéssemos chegado até vocês, pois chegamos a vocês com o evangelho de Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 15, 'Da mesma forma, não vamos além de nossos limites, gloriando-nos de trabalhos que outros fizeram. Nossa esperança é que, à medida que for crescendo a fé que vocês têm, nossa atuação entre vocês aumente ainda mais,', 3, CURRENT_TIMESTAMP, false),
(47, 10, 16, 'para que possamos pregar o evangelho nas regiões que estão além de vocês, sem nos vangloriarmos de trabalho já realizado em território de outro.', 3, CURRENT_TIMESTAMP, false),
(47, 10, 17, 'Contudo, "quem se gloriar, glorie-se no Senhor",', 3, CURRENT_TIMESTAMP, false),
(47, 10, 18, 'pois não é aprovado quem a si mesmo se recomenda, mas aquele a quem o Senhor recomenda.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 1, 'Espero que vocês suportem um pouco da minha insensatez. Sim, por favor, sejam pacientes comigo.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 2, 'O zelo que tenho por vocês é um zelo que vem de Deus. Eu os prometi a um único marido, Cristo, querendo apresentá-los a ele como uma virgem pura.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 3, 'O que receio, e quero evitar, é que assim como a serpente enganou Eva com astúcia, a mente de vocês seja corrompida e se desvie da sua sincera e pura devoção a Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 4, 'Pois, se alguém lhes vem pregando um Jesus que não é aquele que pregamos, ou se vocês acolhem um espírito diferente do que acolheram ou um evangelho diferente do que aceitaram, vocês o suportam facilmente.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 5, 'Todavia, não me julgo nem um pouco inferior a esses "super-apóstolos".', 3, CURRENT_TIMESTAMP, false),
(47, 11, 6, 'Eu posso não ser um orador eloqüente; contudo tenho conhecimento. De fato, já manifestamos isso a vocês em todo tipo de situação.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 7, 'Será que cometi algum pecado ao humilhar-me a fim de elevá-los, pregando-lhes gratuitamente o evangelho de Deus?', 3, CURRENT_TIMESTAMP, false),
(47, 11, 8, 'Despojei outras igrejas, recebendo delas sustento, a fim de servi-los.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 9, 'Quando estive entre vocês e passei por alguma necessidade, não fui um peso para ninguém; pois os irmãos, quando vieram da Macedônia, supriram aquilo de que eu necessitava. Fiz tudo para não ser pesado a vocês, e continuarei a agir assim.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 10, 'Tão certo como a verdade de Cristo está em mim, ninguém na região da Acaia poderá privar-me deste orgulho.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 11, 'Por quê? Por que não os amo? Deus sabe que os amo!', 3, CURRENT_TIMESTAMP, false),
(47, 11, 12, 'E continuarei fazendo o que faço, a fim de não dar oportunidade àqueles que desejam encontrar ocasião de serem considerados iguais a nós nas coisas de que se orgulham.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 13, 'Pois tais homens são falsos apóstolos, obreiros enganosos, fingindo-se apóstolos de Cristo.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 14, 'Isto não é de admirar, pois o próprio Satanás se disfarça de anjo de luz.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 15, 'Portanto, não é surpresa que os seus servos finjam que são servos da justiça. O fim deles será o que as suas ações merecem.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 16, 'Faço questão de repetir: ninguém me considere insensato. Mas se vocês assim me consideram, recebam-me como receberiam um insensato, a fim de que eu me orgulhe um pouco.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 17, 'Ao ostentar este orgulho, não estou falando segundo o Senhor, mas como insensato.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 18, 'Visto que muitos estão se vangloriando de modo bem humano, eu também me orgulharei.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 19, 'Vocês, por serem tão sábios, suportam de boa vontade os insensatos!', 3, CURRENT_TIMESTAMP, false),
(47, 11, 20, 'De fato, vocês suportam até quem os escraviza ou os explora, ou quem se exalta ou lhes fere a face.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 21, 'Para minha vergonha, admito que fomos fracos demais para isso! Naquilo em que todos os outros se atrevem a gloriar-se — falo como insensato — eu também me atrevo.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 22, 'São eles hebreus? Eu também. São israelitas? Eu também. São descendentes de Abraão? Eu também.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 23, 'São eles servos de Cristo? — estou fora de mim para falar desta forma — eu ainda mais: trabalhei muito mais, fui encarcerado mais vezes, fui açoitado mais severamente e exposto à morte repetidas vezes.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 24, 'Cinco vezes recebi dos judeus trinta e nove açoites.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 25, 'Três vezes fui golpeado com varas, uma vez apedrejado, três vezes sofri naufrágio, passei uma noite e um dia exposto à fúria do mar.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 26, 'Estive continuamente viajando de uma parte a outra, enfrentei perigos nos rios, perigos de assaltantes, perigos dos meus compatriotas, perigos dos gentios; perigos na cidade, perigos no deserto, perigos no mar, e perigos dos falsos irmãos.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 27, 'Trabalhei arduamente; muitas vezes fiquei sem dormir, passei fome e sede, e muitas vezes fiquei em jejum; suportei frio e nudez.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 28, 'Além disso, enfrento diariamente uma pressão interior, a saber, a minha preocupação com todas as igrejas.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 29, 'Quem está fraco, que eu não me sinta fraco? Quem não se escandaliza, que eu não me queime por dentro?', 3, CURRENT_TIMESTAMP, false),
(47, 11, 30, 'Se devo me orgulhar, que seja nas coisas que mostram a minha fraqueza.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 31, 'O Deus e Pai do Senhor Jesus, que é bendito para sempre, sabe que não estou mentindo.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 32, 'Em Damasco, o governador nomeado pelo rei Aretas mandou que se vigiasse a cidade para me prender.', 3, CURRENT_TIMESTAMP, false),
(47, 11, 33, 'Mas de uma janela na muralha fui baixado numa cesta e escapei das mãos dele.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 1, 'É necessário que eu continue a gloriar-me com isso. Ainda que eu não ganhe nada com isso, passarei às visões e revelações do Senhor.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 2, 'Conheço um homem em Cristo que há catorze anos foi arrebatado ao terceiro céu. Se foi no corpo ou fora do corpo, não sei; Deus o sabe.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 3, 'E sei que esse homem — se no corpo ou fora do corpo, não sei, mas Deus o sabe —', 3, CURRENT_TIMESTAMP, false),
(47, 12, 4, 'foi arrebatado ao paraíso e ouviu coisas indizíveis, coisas que ao homem não é permitido falar.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 5, 'Nesse homem me gloriarei, mas não em mim mesmo, a não ser em minhas fraquezas.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 6, 'Mesmo que eu preferisse gloriar-me não seria insensato, porque estaria falando a verdade. Evito fazer isso para que ninguém pense a meu respeito mais do que em mim vê ou de mim ouve.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 7, 'Para impedir que eu me exaltasse por causa da grandeza dessas revelações, foi-me dado um espinho na carne, um mensageiro de Satanás, para me atormentar.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 8, 'Três vezes roguei ao Senhor que o tirasse de mim.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 9, 'Mas ele me disse: "Minha graça é suficiente para você, pois o meu poder se aperfeiçoa na fraqueza". Portanto, eu me gloriarei ainda mais alegremente em minhas fraquezas, para que o poder de Cristo repouse em mim.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 10, 'Por isso, por amor de Cristo, regozijo-me nas fraquezas, nos insultos, nas necessidades, nas perseguições, nas angústias. Pois, quando sou fraco é que sou forte.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 11, 'Fui insensato, mas vocês me obrigaram a isso. Eu devia ser recomendado por vocês, pois em nada sou inferior aos "super-apóstolos", embora eu nada seja.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 12, 'As marcas de um apóstolo — sinais, maravilhas e milagres — foram demonstradas entre vocês, com grande perseverança.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 13, 'Em que vocês foram inferiores às outras igrejas, exceto no fato de eu nunca ter sido um peso para vocês? Perdoem-me esta ofensa!', 3, CURRENT_TIMESTAMP, false),
(47, 12, 14, 'Agora, estou pronto para visitá-los pela terceira vez e não lhes serei um peso, porque o que desejo não são os seus bens, mas vocês mesmos. Além disso, os filhos não devem ajuntar riquezas para os pais, mas os pais para os filhos.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 15, 'Assim, de boa vontade, por amor de vocês, gastarei tudo o que tenho e também me desgastarei pessoalmente. Visto que os amo tanto, devo ser menos amado?', 3, CURRENT_TIMESTAMP, false),
(47, 12, 16, 'Seja como for, não lhes tenho sido um peso. No entanto, como sou astuto, eu os prendi com astúcia.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 17, 'Porventura eu os explorei por meio de alguém que lhes enviei?', 3, CURRENT_TIMESTAMP, false),
(47, 12, 18, 'Recomendei a Tito que os visitasse, acompanhado de outro irmão. Por acaso Tito os explorou? Não agimos nós no mesmo espírito e não seguimos os mesmos passos?', 3, CURRENT_TIMESTAMP, false),
(47, 12, 19, 'Vocês pensam que durante todo este tempo estamos nos defendendo perante vocês? Falamos diante de Deus como alguém que está em Cristo; e tudo o que fazemos, amados irmãos, é para fortalecê-los.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 20, 'Pois temo que, ao visitá-los, não os encontre como eu esperava, e que vocês não me encontrem como esperavam. Temo que haja entre vocês brigas, invejas, manifestações de ira, divisões, calúnias, intrigas, arrogância e desordem.', 3, CURRENT_TIMESTAMP, false),
(47, 12, 21, 'Receio que, ao visitá-los outra vez, o meu Deus me humilhe diante de vocês e eu lamente por causa de muitos que pecaram anteriormente e não se arrependeram da impureza, da imoralidade sexual e da libertinagem que praticaram.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 1, 'Esta será minha terceira visita a vocês. "Toda questão precisa ser confirmada pelo depoimento de duas ou três testemunhas".', 3, CURRENT_TIMESTAMP, false),
(47, 13, 2, 'Já os adverti quando estive com vocês pela segunda vez. Agora, estando ausente, escrevo aos que antes pecaram e aos demais: quando voltar, não os pouparei,', 3, CURRENT_TIMESTAMP, false),
(47, 13, 3, 'visto que vocês estão exigindo uma prova de que Cristo fala por meu intermédio. Ele não é fraco ao tratar com vocês, mas poderoso entre vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 4, 'Pois, na verdade, foi crucificado em fraqueza, mas vive pelo poder de Deus. Da mesma forma, somos fracos nele, mas, pelo poder de Deus, viveremos com ele para servir a vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 5, 'Examinem-se para ver se vocês estão na fé; provem-se a si mesmos. Não percebem que Cristo Jesus está em vocês? A não ser que tenham sido reprovados!', 3, CURRENT_TIMESTAMP, false),
(47, 13, 6, 'E espero que saibam que nós não fomos reprovados.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 7, 'Agora, oramos a Deus para que vocês não pratiquem mal algum. Não para que os outros vejam que temos sido aprovados, mas para que vocês façam o que é certo, embora pareça que tenhamos falhado.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 8, 'Pois nada podemos contra a verdade, mas somente em favor da verdade.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 9, 'Ficamos alegres sempre que estamos fracos, e vocês estão fortes; nossa oração é que vocês sejam aperfeiçoados.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 10, 'Por isso escrevo estas coisas estando ausente, para que, quando eu for, não precise ser rigoroso no uso da autoridade que o Senhor me deu para edificá-los, e não para destruí-los.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 11, 'Sem mais, irmãos, despeço-me de vocês! Procurem aperfeiçoar-se, exortem-se mutuamente, tenham um só pensamento, vivam em paz. E o Deus de amor e paz estará com vocês.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 12, 'Saúdem uns aos outros com beijo santo.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 13, 'Todos os santos lhes enviam saudações.', 3, CURRENT_TIMESTAMP, false),
(47, 13, 14, 'A graça do Senhor Jesus Cristo, o amor de Deus e a comunhão do Espírito Santo sejam com todos vocês.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 1, 'Salomão, filho de Davi, estabeleceu-se com firmeza sobre o seu reino, pois o Senhor, o seu Deus, estava com ele e tornou-o muito poderoso.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 2, 'Salomão reuniu todo o Israel: os líderes de mil e de cem, os juízes, todos os líderes de Israel e os chefes de famílias.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 3, 'E foi com toda a assembléia ao lugar sagrado, no alto de Gibeom, pois ali estava a Tenda do Encontro que Moisés, servo do Senhor, havia feito no deserto.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 4, 'Davi tinha transportado a arca de Deus de Quiriate-Jearim para a tenda que ele tinha armado para ela em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 5, 'O altar de bronze que Bezalel, filho de Uri e neto de Hur, fizera, estava em Gibeom, em frente do tabernáculo do Senhor; ali Salomão e a assembléia consultaram o Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 6, 'Salomão ofereceu ao Senhor mil holocaustos sobre o altar de bronze, na Tenda do Encontro.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 7, 'Naquela noite Deus apareceu a Salomão e lhe disse: "Peça-me o que quiser, e eu lhe darei".', 3, CURRENT_TIMESTAMP, false),
(14, 1, 8, 'Salomão respondeu: "Tu foste muito bondoso para com meu pai Davi e me fizeste rei em seu lugar.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 9, 'Agora, Senhor Deus, que se confirme a tua promessa a meu pai Davi, pois me fizeste rei sobre um povo tão numeroso quanto o pó da terra.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 10, 'Dá-me sabedoria e conhecimento, para que eu possa liderar esta nação, pois, quem pode governar este teu grande povo? "', 3, CURRENT_TIMESTAMP, false),
(14, 1, 11, 'Deus disse a Salomão: "Já que este é o desejo de seu coração e você não pediu riquezas, nem bens, nem honra, nem a morte dos seus inimigos, nem vida longa, mas sabedoria e conhecimento para governar o meu povo, sobre o qual o fiz rei,', 3, CURRENT_TIMESTAMP, false),
(14, 1, 12, 'você receberá o que pediu, mas também lhe darei riquezas, bens e honra, como nenhum rei antes de você teve e nenhum depois de você terá".', 3, CURRENT_TIMESTAMP, false),
(14, 1, 13, 'Então Salomão voltou de Gibeom, de diante da Tenda do Encontro, para Jerusalém. E reinou sobre Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 14, 'Salomão juntou carros e cavalos; possuía mil e quatrocentos carros e doze mil cavalos, dos quais mantinha uma parte nas guarnições de algumas cidades e a outra perto dele, em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 15, 'O rei tornou tão comuns a prata e o ouro em Jerusalém quanto as pedras, e o cedro tão numeroso quanto as figueiras bravas da Sefelá.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 16, 'Os cavalos de Salomão eram importados do Egito e da Cilícia, onde os fornecedores do rei os compravam.', 3, CURRENT_TIMESTAMP, false),
(14, 1, 17, 'Importavam do Egito um carro por sete quilos e duzentos gramas de prata, e um cavalo por um quilo e oitocentos gramas, e os exportavam para todos os reis dos hititas e dos arameus.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 1, 'Salomão deu ordens para a construção de um templo em honra do nome do Senhor e de um palácio para si mesmo.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 2, 'Ele designou setenta mil homens como carregadores, oitenta mil como cortadores de pedras nas colinas e três mil e seiscentos como capatazes.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 3, 'Depois Salomão enviou esta mensagem a Hirão, rei de Tiro: "Envia-me cedros como fizeste para meu pai Davi, quando da construção do palácio dele.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 4, 'Agora estou para construir um templo em honra do nome do Senhor, o meu Deus, e dedicá-lo a ele, para queimar incenso aromático diante dele, apresentar regularmente o pão consagrado e fazer holocaustos todas as manhãs e todas as tardes, nos sábados, nas luas novas e nas festas fixas do Senhor, o nosso Deus. Esse é um decreto perpétuo para Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 5, '"O templo que vou construir será grande, pois o nosso Deus é maior do que todos os outros deuses.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 6, 'Mas quem é capaz de construir um templo para ele, visto que os céus não podem contê-lo, nem mesmo os mais altos céus? Quem sou eu, então, para lhe construir um templo, a não ser como um lugar para queimar sacrifícios perante ele?', 3, CURRENT_TIMESTAMP, false),
(14, 2, 7, '"Por isso, manda-me um homem competente no trabalho com ouro, com prata, com bronze, com ferro e com tecido roxo, vermelho e azul, e experiente em esculturas, para trabalhar em Judá e em Jerusalém com os meus hábeis artesãos, preparados por meu pai Davi.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 8, '"Também envia-me do Líbano madeira de cedro, de pinho e de junípero, pois eu sei que os teus servos são hábeis em cortar a madeira de lá. Os meus servos trabalharão com os teus', 3, CURRENT_TIMESTAMP, false),
(14, 2, 9, 'para me fornecerem madeira em grande quantidade, pois é preciso que o templo que vou edificar seja grande e imponente.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 10, 'E eu darei como sustento a teus servos, os lenhadores, vinte mil tonéis de trigo, vinte mil tonéis de cevada, dois mil barris de vinho e dois mil barris de azeite".', 3, CURRENT_TIMESTAMP, false),
(14, 2, 11, 'Hirão, rei de Tiro, respondeu por carta a Salomão: "O Senhor ama o seu povo, e por isso te fez rei sobre ele".', 3, CURRENT_TIMESTAMP, false),
(14, 2, 12, 'E acrescentou: "Bendito seja o Senhor, o Deus de Israel, que fez os céus e a terra, pois deu ao rei Davi um filho sábio, que tem inteligência e discernimento, e que vai construir um templo para o Senhor e um palácio para si.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 13, '"Estou te enviando Hirão-Abi, homem de grande habilidade.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 14, 'Sua mãe era de Dã e seu pai, de Tiro. Ele foi treinado para trabalhar com ouro e prata, bronze e ferro, pedra e madeira, e em tecido roxo, azul e vermelho, e em linho fino e em todo tipo de entalhe. Ele pode executar qualquer projeto que lhe for dado. Trabalhará com os teus artesãos e com os de meu senhor Davi, teu pai.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 15, '"Agora, envie meu senhor a seus servos o trigo, a cevada, o azeite e o vinho que prometeste,', 3, CURRENT_TIMESTAMP, false),
(14, 2, 16, 'e cortaremos toda a madeira do Líbano necessária, e a faremos flutuar em jangadas pelo mar, descendo até Jope. De lá poderás levá-la a Jerusalém".', 3, CURRENT_TIMESTAMP, false),
(14, 2, 17, 'Salomão fez um recenseamento de todos os estrangeiros que viviam em Israel, como o que fizera seu pai Davi; e descobriu-se que eram cento e cinqüenta e três mil e seiscentos.', 3, CURRENT_TIMESTAMP, false),
(14, 2, 18, 'Ele designou setenta mil deles para serem carregadores e oitenta mil para serem cortadores de pedras nas colinas, com três mil e seiscentos capatazes para manter o povo trabalhando.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 1, 'Então Salomão começou a construir o templo do Senhor em Jerusalém, no monte Moriá, onde o Senhor havia aparecido a seu pai Davi, na eira de Araúna, o jebuseu. Local providenciado por Davi.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 2, 'Ele começou a construir no segundo dia do segundo mês do quarto ano de seu reinado.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 3, 'Os alicerces que Salomão lançou para o templo de Deus tinham vinte e sete metros de comprimento e nove metros de largura, pela medida antiga.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 4, 'O pórtico da entrada do templo tinha nove metros de largura e nove metros de altura. Ele revestiu de ouro puro o seu interior.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 5, 'Recobriu de pinho o átrio principal, revestiu-o de ouro puro e o decorou com desenhos de tamareiras e correntes.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 6, 'Ornamentou o templo com pedras preciosas. O ouro utilizado era de Parvaim.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 7, 'Também revestiu de ouro as vigas do forro, os batentes, as paredes e as portas do templo, e esculpiu querubins nas paredes.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 8, 'Fez o Lugar Santíssimo, com nove metros de comprimento e nove metros de largura, igual à largura do templo. Revestiu de vinte e uma toneladas de ouro puro o seu interior.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 9, 'Os pregos de ouro pesavam seiscentos gramas. Também revestiu de ouro as salas superiores.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 10, 'No Lugar Santíssimo esculpiu e revestiu de ouro dois querubins,', 3, CURRENT_TIMESTAMP, false),
(14, 3, 11, 'os quais, de asas abertas, mediam juntos nove metros. Cada asa, de dois metros e vinte e cinco centímetros, tocava, de um lado, na parede do templo,', 3, CURRENT_TIMESTAMP, false),
(14, 3, 12, 'e do outro lado, na asa do outro querubim.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 13, 'Assim os querubins, com asas que se estendiam por nove metros, estavam de pé, de frente para o átrio principal.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 14, 'Ele fez o véu de tecido azul, roxo, vermelho e linho fino com querubins desenhados nele.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 15, 'Fez na frente do templo duas colunas, que juntas tinham dezesseis metros, cada uma tendo em cima um capitel com dois metros e vinte e cinco centímetros.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 16, 'E fez correntes entrelaçadas e colocou-as no alto das colunas. Fez também cem romãs, colocando-as nas correntes.', 3, CURRENT_TIMESTAMP, false),
(14, 3, 17, 'Então levantou as colunas na frente do templo, uma ao sul, outra ao norte; à que ficava ao sul deu o nome de Jaquim, e à que ficava ao norte, Boaz.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 1, 'Salomão também mandou fazer um altar de bronze de nove metros de comprimento, nove metros de largura e quatro metros e meio de altura.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 2, 'Fez o tanque de metal fundido, redondo, medindo quatro metros e meio de diâmetro e dois metros e vinte e cinco centímetros de altura. Era preciso um fio de treze metros e meio para medir a sua circunferência.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 3, 'Abaixo da borda e ao seu redor havia figuras de touro, de cinco em cinco centímetros. Os touros foram fundidos em duas fileiras numa só peça com o tanque.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 4, 'O tanque ficava sobre doze touros, três voltados para o norte, três para o oeste, três para o sul e três para o leste. Ficava em cima deles, e as pernas traseiras dos touros eram voltadas para o centro.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 5, 'A espessura do tanque era de quatro dedos, e sua borda era como a borda de um cálice, como uma flor de lírio. Tinha capacidade de sessenta e seis mil litros.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 6, 'Fez dez pias, colocando cinco no lado sul e cinco no lado norte. Nelas tudo o que era usado nos holocaustos era lavado, enquanto que o tanque servia para os sacerdotes se lavarem.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 7, 'Fez dez candelabros de ouro, de acordo com as especificações, e colocou-os no templo, cinco no lado sul e cinco no lado norte.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 8, 'Fez dez mesas e colocou-as no templo, cinco no lado sul e cinco no lado norte. Também fez cem bacias de ouro para aspersão.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 9, 'E fez o pátio dos sacerdotes e o pátio principal com suas portas, e revestiu de bronze as suas portas.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 10, 'Pôs o tanque no lado sul, no canto sudeste do templo.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 11, 'Também fez os jarros, as pás e as bacias para aspersão. Assim, Hirão terminou o trabalho de que fora encarregado pelo rei Salomão, no templo de Deus:', 3, CURRENT_TIMESTAMP, false),
(14, 4, 12, 'as duas colunas; os dois capitéis em forma de taça no alto das colunas; os dois conjuntos de correntes que decoravam os dois capitéis;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 13, 'as quatrocentas romãs para os dois conjuntos de correntes, sendo duas fileiras de romãs para cada conjunto;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 14, 'os dez carrinhos com as suas dez pias;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 15, 'o tanque e os doze touros debaixo dele;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 16, 'e os jarros, as pás, os garfos de carne e todos os utensílios afins. Todos esses utensílios que Hirão-Abi fez a pedido do rei Salomão, para o templo do Senhor, eram de bronze polido.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 17, 'Foi na planície do Jordão, entre Sucote e Zeredá, que o rei os mandou fundir, em moldes de barro.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 18, 'Salomão os fez em tão grande quantidade, a ponto de não se poder determinar o peso do bronze utilizado.', 3, CURRENT_TIMESTAMP, false),
(14, 4, 19, 'Além desses, Salomão mandou fazer também todos estes outros utensílios para o templo de Deus: o altar de ouro; as mesas sobre as quais ficavam os pães da Presença;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 20, 'os candelabros de ouro puro com suas lâmpadas, para iluminarem diante do santuário interno, conforme determinado;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 21, 'as flores, as lâmpadas e as tenazes de ouro maciço;', 3, CURRENT_TIMESTAMP, false),
(14, 4, 22, 'os cortadores de pavio, as bacias para aspersão, as tigelas, os incensários de ouro puro e as portas de ouro do templo: tanto as portas da sala interna, o Lugar Santíssimo, quanto as portas do átrio principal.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 1, 'Terminada toda a obra que Salomão havia realizado para o templo do Senhor, ele trouxe as coisas que seu pai Davi tinha consagrado e colocou junto com os tesouros do templo de Deus: a prata, o ouro e todos os utensílios.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 2, 'Então Salomão reuniu em Jerusalém as autoridades de Israel e todos os líderes das tribos e os chefes das famílias israelitas, para levarem de Sião, a cidade de Davi, a arca da aliança do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 3, 'E todos os homens de Israel uniram-se ao rei por ocasião da festa, no sétimo mês.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 4, 'Quando todas as autoridades de Israel chegaram, os levitas pegaram a arca', 3, CURRENT_TIMESTAMP, false),
(14, 5, 5, 'e a levaram, com a Tenda do Encontro e com todos os seus utensílios sagrados. Foram os sacerdotes levitas que levaram tudo.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 6, 'O rei Salomão e toda a comunidade de Israel que se havia reunido a ele diante da arca, sacrificaram tantas ovelhas e bois que nem era possível contar.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 7, 'Os sacerdotes levaram a arca da aliança do Senhor para o seu lugar no santuário interno do templo, no Lugar Santíssimo, e a colocaram debaixo das asas dos querubins.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 8, 'Os querubins tinham suas asas estendidas sobre o lugar da arca e cobriam a arca e as varas utilizadas para o transporte.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 9, 'Essas varas eram tão compridas que as suas pontas, que se estendiam para fora da arca, podiam ser vistas da frente do santuário interno, mas não de fora dele; e elas estão lá até hoje.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 10, 'Na arca havia só as duas tábuas que Moisés tinha colocado quando estava em Horebe, onde o Senhor fez uma aliança com os israelitas depois que saíram do Egito.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 11, 'Então os sacerdotes saíram do Lugar Santo. Todos eles haviam se consagrado, não importando a divisão a que pertenciam.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 12, 'E, todos os levitas que eram músicos — Asafe, Hemã, Jedutum e os filhos e parentes deles — ficaram a leste do altar, vestidos de linho fino, tocando címbalos, harpas e liras, e os acompanhavam cento e vinte sacerdotes tocando cornetas.', 3, CURRENT_TIMESTAMP, false),
(14, 5, 13, 'Os que tocavam cornetas e os cantores, em uníssono, louvaram e agradeceram ao Senhor. Ao som de cornetas, címbalos e outros instrumentos, levantaram suas vozes em louvor ao Senhor e cantaram: "Ele é bom; o seu amor dura para sempre". Então uma nuvem encheu o templo do Senhor,', 3, CURRENT_TIMESTAMP, false),
(14, 5, 14, 'de forma que os sacerdotes não podiam desempenhar o seu serviço, pois a glória do Senhor encheu o templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 1, 'E Salomão exclamou: "O Senhor disse que habitaria numa nuvem escura!', 3, CURRENT_TIMESTAMP, false),
(14, 6, 2, 'Na realidade construí para ti um templo magnífico, um lugar para nele habitares para sempre! "', 3, CURRENT_TIMESTAMP, false),
(14, 6, 3, 'Depois o rei virou-se e abençoou toda a assembléia de Israel, que estava ali de pé.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 4, 'E disse: "Bendito seja o Senhor, o Deus de Israel, que por suas mãos cumpriu o que prometeu com sua própria boca a meu pai Davi, quando lhe disse:', 3, CURRENT_TIMESTAMP, false),
(14, 6, 5, '‘Desde o dia em que tirei meu povo do Egito, não escolhi nenhuma cidade das tribos de Israel para nela construir um templo em honra do meu nome, nem escolhi ninguém para ser o líder do meu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 6, 'Mas, agora, escolhi Jerusalém para o meu nome ali estar e escolhi Davi para governar Israel, o meu povo’.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 7, '"Meu pai Davi tinha no coração o propósito de construir um templo em honra do nome do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 8, 'Mas o Senhor lhe disse: ‘Você fez bem em ter no coração o plano de construir um templo em honra do meu nome;', 3, CURRENT_TIMESTAMP, false),
(14, 6, 9, 'no entanto, não será você que o construirá, mas o seu filho, que procederá de você; ele construirá o templo em honra do meu nome’.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 10, '"E o Senhor cumpriu a sua promessa. Sou o sucessor de meu pai Davi, e agora ocupo o trono de Israel, como o Senhor tinha prometido, e construí o templo em honra do nome do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 11, 'Coloquei nele a arca, na qual estão as tábuas da aliança do Senhor, aliança que ele fez com os israelitas".', 3, CURRENT_TIMESTAMP, false),
(14, 6, 12, 'Depois Salomão colocou-se diante do altar do Senhor, diante de toda a assembléia de Israel, e levantou as mãos para orar.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 13, 'Ele havia mandado fazer uma plataforma de bronze com dois metros e vinte e cinco centímetros de comprimento e de largura, e um metro e trinta e cinco centímetros de altura, no centro do pátio externo. Ele ficou de pé na plataforma, depois ajoelhou-se diante de toda a assembléia de Israel, levantou as mãos para o céu,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 14, 'e orou: "Senhor, Deus de Israel, não há Deus como tu nos céus e na terra! Tu que guardas a tua aliança de amor com os teus servos que, de todo o coração, andam segundo a tua vontade.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 15, 'Cumpriste a tua promessa a teu servo Davi, meu pai; com tua boca prometeste e com tua mão a cumpriste, conforme hoje se vê.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 16, '"Agora, Senhor, Deus de Israel, cumpre a outra promessa que fizeste a teu servo Davi, meu pai, quando disseste: ‘Você nunca deixará de ter, diante de mim, um descendente que se assente no trono de Israel, se tão-somente os seus descendentes tiverem o cuidado de, em tudo, andarem segundo a minha lei, como você tem feito’.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 17, 'Agora, ó Senhor, Deus de Israel, que se confirme a palavra que falaste a teu servo Davi.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 18, '"Mas será possível que Deus habite na terra com os homens? Os céus, mesmo os mais altos céus, não podem conter-te. Muito menos este templo que construí!', 3, CURRENT_TIMESTAMP, false),
(14, 6, 19, 'Ainda assim, atende à oração do teu servo e ao seu pedido de misericórdia, ó Senhor, meu Deus. Ouve o clamor e a oração que teu servo faz hoje na tua presença.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 20, 'Estejam os teus olhos voltados dia e noite para este templo, lugar do qual disseste que nele porias o teu nome, para que ouças a oração que o teu servo fizer voltado para este lugar.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 21, 'Ouve as súplicas do teu servo e de Israel, teu povo, quando orarem voltados para este lugar. Ouve desde os céus, lugar da tua habitação, e quando ouvires, dá-lhes o teu perdão.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 22, '"Quando um homem pecar contra seu próximo e tiver que fazer um juramento, e vier jurar diante do teu altar neste templo,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 23, 'ouve dos céus e age. Julga os teus servos; retribui ao culpado, fazendo recair sobre a sua própria cabeça o resultado da sua conduta, e declara sem culpa o inocente, dando-lhe o que a sua inocência merece.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 24, '"Quando Israel, o teu povo, for derrotado por um inimigo por ter pecado contra ti, e voltar-se para ti e invocar o teu nome, orando e suplicando a ti neste templo,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 25, 'ouve dos céus e perdoa o pecado de Israel, teu povo, e traze-o de volta à terra que deste a ele e aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 26, '"Quando fechar-se o céu, e não houver chuva por haver o teu povo pecado contra ti, e, se o teu povo, voltado para este lugar, invocar o teu nome e afastar-se do seu pecado por o haveres castigado,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 27, 'ouve dos céus e perdoa o pecado dos teus servos, do teu povo Israel. Ensina-lhes o caminho certo e envia chuva sobre a tua terra, que deste por herança ao teu povo.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 28, '"Quando houver fome ou praga no país, ferrugem e mofo, gafanhotos peregrinos e gafanhotos devastadores, ou quando inimigos sitiarem suas cidades, quando, em meio a qualquer praga ou epidemia,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 29, 'uma oração ou uma súplica por misericórdia for feita por um israelita ou por todo o teu povo Israel, cada um sentindo as suas próprias aflições e dores, estendendo as mãos na direção deste templo,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 30, 'ouve dos céus, o lugar da tua habitação. Perdoa e trata cada um de acordo com o que merece, visto que conheces o seu coração. Sim, só tu conheces o coração do homem.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 31, 'Assim eles te temerão, e andarão segundo a tua vontade durante todo o tempo em que viverem na terra que deste aos nossos antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 32, '"Quanto ao estrangeiro, que não pertence a teu povo Israel, e que veio de uma terra distante por causa do teu grande nome, da tua mão poderosa e do teu braço forte; quando ele vier e orar voltado para este templo,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 33, 'ouve dos céus, lugar da tua habitação, e atende o pedido do estrangeiro, a fim de que todos os povos da terra conheçam o teu nome e te temam, como faz Israel, teu povo, e saibam que este templo que construí traz o teu nome.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 34, '"Quando o teu povo for à guerra contra os seus inimigos, por onde quer que tu o enviares, e orar a ti, voltado para a cidade que escolheste e para o templo que construí em honra do teu nome,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 35, 'então ouve dos céus a sua oração e a sua súplica, e defende a sua causa.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 36, '"Quando pecarem contra ti, pois não há ninguém que não peque, e ficares irado com eles e os entregares ao inimigo, que os leve prisioneiros para uma terra distante ou próxima;', 3, CURRENT_TIMESTAMP, false),
(14, 6, 37, 'se eles caírem em si, na terra para a qual foram deportados, e se arrependerem e lá orarem: ‘Pecamos, praticamos o mal e fomos rebeldes’;', 3, CURRENT_TIMESTAMP, false),
(14, 6, 38, 'e se lá eles se voltarem para ti de todo o coração e de toda a sua alma, na terra de seu cativeiro para onde foram levados, e orarem voltados para a terra que deste aos seus antepassados, para a cidade que escolheste e para o templo que construí em honra do teu nome,', 3, CURRENT_TIMESTAMP, false),
(14, 6, 39, 'então, dos céus, lugar da tua habitação, ouve a sua oração e a sua súplica, e defende a sua causa. Perdoa o teu povo, que pecou contra ti.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 40, '"Assim, meu Deus, que os teus olhos estejam abertos e teus ouvidos atentos às orações feitas neste lugar.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 41, '"Agora, levanta-te, ó Senhor, ó Deus, e vem para o teu lugar de descanso, tu e a arca do teu poder. Estejam os teus sacerdotes vestidos de salvação, ó Senhor, ó Deus; que os teus santos se regozijem em tua bondade.', 3, CURRENT_TIMESTAMP, false),
(14, 6, 42, 'Ó Senhor, ó Deus, não rejeites o teu ungido. Lembra-te da fidelidade prometida a teu servo Davi".', 3, CURRENT_TIMESTAMP, false),
(14, 7, 1, 'Assim que Salomão acabou de orar, desceu fogo do céu e consumiu o holocausto e os sacrifícios, e a glória do Senhor encheu o templo.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 2, 'Os sacerdotes não conseguiam entrar no templo do Senhor, porque a glória do Senhor o enchia.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 3, 'Quando todos os israelitas viram o fogo descendo e a glória do Senhor sobre o templo, ajoelharam-se no pavimento, chegando o rosto ao chão, adoraram e deram graças ao Senhor, dizendo: "Ele é bom; o seu amor dura para sempre".', 3, CURRENT_TIMESTAMP, false),
(14, 7, 4, 'Então o rei e todo o Israel ofereceram sacrifícios ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 5, 'O rei Salomão ofereceu em sacrifício vinte e dois mil bois e cento e vinte mil ovelhas. Assim o rei e todo o povo fizeram a dedicação do templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 6, 'Os sacerdotes tomaram seus lugares, bem como os levitas, com os instrumentos musicais do Senhor feitos pelo rei Davi para louvar o Senhor cantando: "O seu amor dura para sempre". No outro lado, de frente para os levitas, os sacerdotes tocavam suas cornetas. Todo o povo estava de pé.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 7, 'Salomão consagrou a parte central do pátio, que ficava na frente do templo do Senhor, e ali ofereceu holocaustos e a gordura das ofertas de comunhão, pois o altar de bronze que Salomão tinha construído não comportava os holocaustos, as ofertas de cereal e as porções de gordura.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 8, 'Durante sete dias, Salomão, juntamente com todo o Israel, celebrou a festa; era uma grande multidão, gente vinda desde Lebo-Hamate até o ribeiro do Egito.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 9, 'No oitavo dia realizaram uma assembléia solene. Levaram sete dias para a dedicação do altar, e a festa se prolongou por mais sete dias.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 10, 'No dia vinte e três do sétimo mês, ele mandou o povo para as suas casas. E todos se foram, jubilosos e de coração alegre pelas coisas boas que o Senhor havia feito por Davi e Salomão e por seu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 11, 'Quando Salomão acabou de construir o templo do Senhor e o palácio real, executando bem tudo o que tinha em mente realizar no templo do Senhor e em seu próprio palácio,', 3, CURRENT_TIMESTAMP, false),
(14, 7, 12, 'o Senhor lhe apareceu de noite e disse: "Ouvi sua oração, e escolhi este lugar para mim, como um templo para sacrifícios.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 13, '"Se eu fechar o céu para que não chova ou mandar que os gafanhotos devorem o país ou sobre o meu povo enviar uma praga,', 3, CURRENT_TIMESTAMP, false),
(14, 7, 14, 'se o meu povo, que se chama pelo meu nome, se humilhar e orar, buscar a minha face e se afastar dos seus maus caminhos, dos céus o ouvirei, perdoarei o seu pecado e curarei a sua terra.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 15, 'De hoje em diante os meus olhos estarão abertos e os meus ouvidos atentos às orações feitas neste lugar.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 16, 'Escolhi e consagrei este templo para que o meu nome esteja nele para sempre. Meus olhos e meu coração nele sempre estarão.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 17, '"E se você andar segundo a minha vontade como fez seu pai Davi e fizer tudo o que eu lhe ordeno, obedecendo aos meus decretos e às minhas leis,', 3, CURRENT_TIMESTAMP, false),
(14, 7, 18, 'firmarei o seu trono, conforme a aliança que fiz com Davi, seu pai, quando lhe disse: ‘Você nunca deixará de ter um descendente para governar Israel’.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 19, '"Mas, se vocês se afastarem de mim e abandonarem os decretos e os mandamentos que lhes dei, e prestarem culto a outros deuses e adorá-los,', 3, CURRENT_TIMESTAMP, false),
(14, 7, 20, 'desarraigarei Israel da minha terra, que lhes dei, e lançarei para longe da minha presença este templo que consagrei ao meu nome. Farei que ele se torne motivo de zombaria entre todos os povos.', 3, CURRENT_TIMESTAMP, false),
(14, 7, 21, 'E embora agora este templo seja imponente, todos os que passarem por ele ficarão espantados e perguntarão: ‘Por que o Senhor fez uma coisa dessas a esta terra e a este templo? ’', 3, CURRENT_TIMESTAMP, false),
(14, 7, 22, 'E a resposta será: ‘Porque abandonaram o Senhor, o Deus dos seus antepassados, que os tirou do Egito, e se apegaram a outros deuses, adorando-os e prestando-lhes culto; por isso ele trouxe sobre eles toda esta desgraça’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 8, 1, 'Depois de vinte anos, durante os quais Salomão construiu o templo do Senhor e o seu próprio palácio,', 3, CURRENT_TIMESTAMP, false),
(14, 8, 2, 'ele reconstruiu as cidades que Hirão lhe tinha dado, e nelas estabeleceu israelitas.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 3, 'Depois atacou Hamate-Zobá e a conquistou.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 4, 'Também reconstruiu Tadmor, no deserto, e todas as cidades-armazéns que havia construído em Hamate.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 5, 'Reconstruiu Bete-Horom Alta e Bete-Horom Baixa, cidades fortificadas com muros, portas e trancas,', 3, CURRENT_TIMESTAMP, false),
(14, 8, 6, 'e também Baalate e todas as cidades-armazéns que possuía, e todas as cidades onde ficavam os seus carros e os seus cavalos. Construiu tudo o que desejou em Jerusalém, no Líbano e em todo o território que governou.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 7, 'Todos os não israelitas, descendentes dos hititas, dos amorreus, dos ferezeus, dos heveus e dos jebuseus,', 3, CURRENT_TIMESTAMP, false),
(14, 8, 8, 'que não tinham sido mortos pelos israelitas, Salomão recrutou para o trabalho forçado, como continuam até hoje.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 9, 'Mas Salomão não obrigou nenhum israelita a trabalhos forçados; eles eram seus homens de guerra, chefes de seus capitães, comandantes dos seus carros e condutores de carros.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 10, 'Também eram israelitas os principais funcionários do rei Salomão, duzentos e cinqüenta funcionários que supervisionavam os trabalhadores.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 11, 'Salomão levou a filha do faraó da cidade de Davi para o palácio que ele havia construído para ela, pois dissera: "Minha mulher não deve morar no palácio de Davi, rei de Israel, pois os lugares onde entrou a arca do Senhor são sagrados".', 3, CURRENT_TIMESTAMP, false),
(14, 8, 12, 'Sobre o altar do Senhor, que havia construído diante do pórtico, Salomão passou a sacrificar holocaustos ao Senhor,', 3, CURRENT_TIMESTAMP, false),
(14, 8, 13, 'conforme as determinações de Moisés acerca das ofertas diárias e dos sábados, das luas novas e das três festas anuais: a festa dos pães sem fermento, a festa das semanas e a festa das cabanas.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 14, 'De acordo com a ordem de seu pai Davi, designou os grupos dos sacerdotes para as suas tarefas, e os levitas para conduzirem o louvor e ajudarem os sacerdotes, conforme as determinações diárias. Também designou, por divisões, os porteiros das várias portas, conforme o que Davi, homem de Deus, tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 15, 'Todas as ordens dadas pelo rei aos sacerdotes e aos levitas, inclusive as ordens relativas aos tesouros, foram seguidas à risca.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 16, 'Todo o trabalho de Salomão foi executado, desde o dia em que foram lançados os alicerces do templo do Senhor até seu término. Assim foi concluído o templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 17, 'Depois Salomão foi a Eziom-Geber e a Elate, no litoral de Edom.', 3, CURRENT_TIMESTAMP, false),
(14, 8, 18, 'E Hirão enviou-lhe navios comandados por seus próprios marinheiros, homens que conheciam o mar. Eles navegavam com os marinheiros de Salomão até Ofir, e de lá trouxeram quinze toneladas e setecentos e cinqüenta quilos de ouro para o rei Salomão.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 1, 'A rainha de Sabá soube da fama de Salomão, e foi a Jerusalém para pô-lo à prova com perguntas difíceis. Quando chegou, acompanhada de uma enorme caravana, com camelos carregados de especiarias, grande quantidade de ouro e pedras preciosas, foi até Salomão e lhe fez todas as perguntas que tinha em mente.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 2, 'Salomão respondeu a todas; nenhuma lhe foi tão difícil que não pudesse responder.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 3, 'Vendo a sabedoria de Salomão, bem como o palácio que ele havia construído,', 3, CURRENT_TIMESTAMP, false),
(14, 9, 4, 'o que era servido em sua mesa, o lugar de seus oficiais, os criados e copeiros, todos uniformizados, e os holocaustos que ele fazia no templo do Senhor, ela ficou impressionada.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 5, 'Disse ela então ao rei: "Tudo o que ouvi em meu país acerca de tuas realizações e de tua sabedoria era verdade.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 6, 'Mas eu não acreditava no que diziam, até ver com os meus próprios olhos. Na realidade, não me contaram nem a metade da grandeza de tua sabedoria; tu ultrapassas em muito o que ouvi.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 7, 'Como devem ser felizes os homens da tua corte, que continuamente estão diante de ti e ouvem a tua sabedoria!', 3, CURRENT_TIMESTAMP, false),
(14, 9, 8, 'Bendito seja o Senhor, o teu Deus, que se agradou de ti e te colocou no trono dele para reinar pelo Senhor, pelo teu Deus. Por causa do amor de teu Deus para com Israel e do seu desejo de preservá-lo para sempre, ele te fez rei, para manter a justiça e a retidão".', 3, CURRENT_TIMESTAMP, false),
(14, 9, 9, 'E ela deu ao rei quatro toneladas e duzentos quilos de ouro e grande quantidade de especiarias e de pedras preciosas. Nunca se viu tantas especiarias tais como aquelas que a rainha de Sabá deu ao rei Salomão.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 10, '( Os marinheiros de Hirão e de Salomão trouxeram ouro de Ofir, e também madeira de junípero e pedras preciosas.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 11, 'O rei utilizou a madeira para fazer a escadaria do templo do Senhor e a do palácio real, além de harpas e liras para os músicos. Nunca se havia visto algo semelhante em Judá. )', 3, CURRENT_TIMESTAMP, false),
(14, 9, 12, 'O rei Salomão deu à rainha de Sabá tudo o que ela desejou e pediu; muito mais do que ela lhe tinha trazido. Então ela e seus servos voltaram para o seu país.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 13, 'O peso do ouro que Salomão recebia anualmente era de vinte e três toneladas e trezentos quilos,', 3, CURRENT_TIMESTAMP, false),
(14, 9, 14, 'fora o que os mercadores e os comerciantes traziam. Também todos os reis da Arábia e os governadores do país traziam ouro e prata para Salomão.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 15, 'O rei Salomão fez duzentos escudos grandes de ouro batido, utilizando três quilos e seiscentos gramas de ouro em cada um.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 16, 'Também fez trezentos escudos pequenos de ouro batido, com um quilo e oitocentos gramas de ouro em cada um. O rei os colocou no Palácio da Floresta do Líbano.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 17, 'O rei mandou fazer ainda um grande trono de marfim revestido de ouro puro.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 18, 'O trono tinha seis degraus, e um estrado de ouro fixo nele. Nos dois lados do assento havia braços, com um leão junto a cada braço.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 19, 'Doze leões ficavam nos seis degraus, um de cada lado. Nada igual havia sido feito em nenhum outro reino.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 20, 'Todas as taças do rei Salomão eram de ouro, bem como todos os utensílios do Palácio da Floresta do Líbano. Não havia nada de prata, pois a prata quase não tinha valor nos dias de Salomão.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 21, 'O rei tinha uma frota de navios mercantes tripulados por marinheiros do rei Hirão. Cada três anos a frota voltava, trazendo ouro, prata, marfim, macacos e pavões.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 22, 'O rei Salomão era o mais rico e o mais sábio de todos os reis da terra.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 23, 'Esses pediam audiência a Salomão, para ouvirem a sabedoria que Deus lhe tinha dado.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 24, 'Ano após ano, todos os que vinham traziam algum presente: utensílios de prata e de ouro, mantos, armas e especiarias, cavalos e mulas.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 25, 'Salomão possuía quatro mil estábulos para cavalos e carros, e doze mil cavalos, dos quais mantinha uma parte nas guarnições de algumas cidades e a outra perto dele, em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 26, 'Ele dominava sobre todos os reis desde o Eufrates até a terra dos filisteus, junto à fronteira do Egito.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 27, 'O rei tornou a prata tão comum em Jerusalém quanto as pedras, e o cedro tão numeroso quanto as figueiras bravas da Sefelá.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 28, 'Os cavalos de Salomão eram importados do Egito e de todos os outros países.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 29, 'Os demais acontecimentos do reinado de Salomão, desde o início até o fim, estão escritos nos relatos do profeta Natã, nas profecias do silonita Aías e nas visões do vidente Ido acerca de Jeroboão, filho de Nebate.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 30, 'Salomão reinou quarenta anos em Jerusalém, sobre todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 9, 31, 'Então descansou com os seus antepassados e foi sepultado na cidade de Davi, seu pai. E o seu filho Roboão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 1, 'Roboão foi a Siquém, onde todos os israelitas tinham se reunido para proclamá-lo rei.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 2, 'Assim que Jeroboão, filho de Nebate, que estava no Egito fugindo do rei Salomão, soube disso, voltou de lá.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 3, 'E mandaram chamá-lo. Então ele e todo o Israel foram ao encontro de Roboão e disseram:', 3, CURRENT_TIMESTAMP, false),
(14, 10, 4, '"Teu pai colocou sobre nós um jugo pesado, mas agora diminui o trabalho árduo e este jugo pesado, e nós te serviremos".', 3, CURRENT_TIMESTAMP, false),
(14, 10, 5, 'Roboão respondeu: "Voltem a mim daqui a três dias". Então o povo foi embora.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 6, 'O rei Roboão perguntou às autoridades que haviam servido ao seu pai Salomão durante a vida dele: "Como vocês me aconselham a responder a este povo? "', 3, CURRENT_TIMESTAMP, false),
(14, 10, 7, 'Eles responderam: "Se hoje fores bom para esse povo, se o agradares e lhe deres resposta favorável, eles sempre serão teus servos".', 3, CURRENT_TIMESTAMP, false),
(14, 10, 8, 'Roboão, contudo, rejeitou o conselho que as autoridades de Israel lhe tinham dado e consultou os jovens que haviam crescido com ele e o estavam servindo.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 9, 'Perguntou-lhes: "Qual é o conselho de vocês? Como devemos responder a este povo que me diz: ‘Diminui o jugo que teu pai colocou sobre nós’? "', 3, CURRENT_TIMESTAMP, false),
(14, 10, 10, 'Os jovens que haviam crescido com ele responderam: "A este povo que te disse: ‘Teu pai colocou sobre nós um jugo pesado; torna-o mais leve’ — dize: ‘Meu dedo mínimo é mais grosso do que a cintura do meu pai.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 11, 'Pois bem, meu pai lhes impôs um jugo pesado; eu o tornarei ainda mais pesado. Meu pai os castigou com simples chicotes; eu os castigarei com chicotes pontiagudos’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 10, 12, 'Três dias depois, Jeroboão e todo o povo voltaram a Roboão, segundo a orientação dada pelo rei: "Voltem a mim daqui a três dias".', 3, CURRENT_TIMESTAMP, false),
(14, 10, 13, 'Mas o rei lhes respondeu asperamente. Rejeitando o conselho das autoridades de Israel,', 3, CURRENT_TIMESTAMP, false),
(14, 10, 14, 'seguiu o conselho dos jovens e disse: "Meu pai lhes tornou pesado o jugo; eu o tornarei ainda mais pesado. Meu pai os castigou com simples chicotes; eu os castigarei com chicotes pontiagudos".', 3, CURRENT_TIMESTAMP, false),
(14, 10, 15, 'E o rei não ouviu o povo, pois esta mudança nos acontecimentos vinha da parte de Deus, para que se cumprisse a palavra que o Senhor havia falado a Jeroboão, filho de Nebate, por meio do silonita Aías.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 16, 'Quando todo o Israel viu que o rei se recusava a ouvi-los, responderam ao rei: "Que temos em comum com Davi? Que temos em comum com o filho de Jessé? Para as suas tendas, ó Israel! Cuide da sua própria casa, ó Davi! " E assim os israelitas foram para as suas casas.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 17, 'Quanto, porém, aos israelitas que moravam nas cidades de Judá, Roboão continuou como rei deles.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 18, 'O rei Roboão enviou Adonirão, chefe de trabalhos forçados, mas todo o Israel o apedrejou até à morte. O rei, contudo, conseguiu subir em sua carruagem e fugir para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 10, 19, 'Desta forma Israel se rebelou contra a dinastia de Davi, e assim permanece até hoje.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 1, 'Quando Roboão chegou em Jerusalém, convocou cento e oitenta mil homens de combate, das tribos de Judá e de Benjamim, para guerrearem contra Israel e recuperarem o reino para Roboão.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 2, 'Entretanto, veio esta palavra do Senhor a Semaías, homem de Deus:', 3, CURRENT_TIMESTAMP, false),
(14, 11, 3, '"Diga a Roboão, filho de Salomão, rei de Judá, e a todos os israelitas de Judá e de Benjamim:', 3, CURRENT_TIMESTAMP, false),
(14, 11, 4, '‘Assim diz o Senhor: Não saiam à guerra contra os seus irmãos. Voltem para casa, todos vocês, pois fui eu que fiz isso’ ". E eles obedeceram à palavra do Senhor e desistiram de marchar contra Jeroboão.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 5, 'Roboão morou em Jerusalém e reconstruiu algumas cidades para a defesa de Judá. Foram elas:', 3, CURRENT_TIMESTAMP, false),
(14, 11, 6, 'Belém, Etã, Tecoa,', 3, CURRENT_TIMESTAMP, false),
(14, 11, 7, 'Bete-Zur, Socó, Adulão,', 3, CURRENT_TIMESTAMP, false),
(14, 11, 8, 'Gate, Maressa, Zife,', 3, CURRENT_TIMESTAMP, false),
(14, 11, 9, 'Adoraim, Láquis, Azeca,', 3, CURRENT_TIMESTAMP, false),
(14, 11, 10, 'Zorá, Aijalom e Hebrom. Essas cidades foram fortificadas em Judá e em Benjamim.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 11, 'Ele fortaleceu as suas defesas e nelas colocou comandantes, com suprimentos de alimentos, azeite e vinho.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 12, 'Armazenou escudos grandes e lanças em todas as cidades, tornando-as muito fortes. Assim, Judá e Benjamim continuaram sob o seu domínio.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 13, 'Os sacerdotes e os levitas de todos os distritos de Israel o apoiaram.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 14, 'Os levitas chegaram até a abandonar as suas pastagens e os seus bens, e foram para Judá e para Jerusalém, porque Jeroboão e seus filhos os haviam rejeitado como sacerdotes do Senhor,', 3, CURRENT_TIMESTAMP, false),
(14, 11, 15, 'nomeando seus próprios sacerdotes para os altares idólatras e para os ídolos que haviam feito em forma de bodes e de bezerros.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 16, 'De todas as tribos de Israel aqueles que estavam realmente dispostos a buscar o Senhor, o Deus de Israel, seguiram os levitas até Jerusalém para oferecerem sacrifícios ao Senhor, ao Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 17, 'Eles fortaleceram o reino de Judá e durante três anos apoiaram Roboão, filho de Salomão, andando nos caminhos de Davi e de Salomão durante esse tempo.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 18, 'Roboão casou-se com Maalate, filha de Jeremote e neta de Davi. A mãe de Maalate era Abiail, filha de Eliabe e neta de Jessé.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 19, 'Ela deu-lhe três filhos: Jeús, Semarias e Zaão.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 20, 'Depois ele casou-se com Maaca, filha de Absalão, a qual lhe deu os filhos Abias, Atai, Ziza e Selomite.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 21, 'Roboão amava Maaca, filha de Absalão, mais do que a qualquer outra de suas esposas e concubinas. Ao todo ele teve dezoito esposas e sessenta concubinas, vinte e oito filhos e sessenta filhas.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 22, 'Roboão nomeou Abias, filho de Maaca, o chefe entre os seus irmãos, com o intuito de fazê-lo rei.', 3, CURRENT_TIMESTAMP, false),
(14, 11, 23, 'Ele agiu com sabedoria, dispersando seus filhos pelos distritos de Judá e de Benjamim, e pelas cidades fortificadas. Garantiu-lhes fartas provisões e lhes conseguiu muitas mulheres.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 1, 'Depois que Roboão se fortaleceu, firmou-se como rei, ele e todo o Israel abandonaram a lei do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 2, 'Por terem sido infiéis ao Senhor, Sisaque, rei do Egito, atacou Jerusalém no quinto ano do reinado de Roboão.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 3, 'Com mil e duzentos carros de guerra, sessenta mil cavaleiros e um exército incontável de líbios, suquitas e etíopes, que vieram do Egito com ele,', 3, CURRENT_TIMESTAMP, false),
(14, 12, 4, 'conquistou as cidades fortificadas de Judá e chegou até Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 5, 'Então o profeta Semaías apresentou-se a Roboão e aos líderes de Judá que se haviam reunido em Jerusalém, fugindo de Sisaque, e lhes disse: "Assim diz o Senhor: ‘Vocês me abandonaram; por isso eu agora os abandono, entregando-os a Sisaque’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 12, 6, 'Os líderes de Israel e o rei se humilharam e disseram: "O Senhor é justo".', 3, CURRENT_TIMESTAMP, false),
(14, 12, 7, 'Quando o Senhor viu que eles se humilharam, veio a Semaías esta palavra do Senhor: "Visto que eles se humilharam, não os destruirei, mas em breve lhes darei livramento. Minha ira não será derramada sobre Jerusalém por meio de Sisaque.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 8, 'Eles, contudo, ficarão sujeitos a ele, para que aprendam a diferença entre servir a mim e servir aos reis de outras terras".', 3, CURRENT_TIMESTAMP, false),
(14, 12, 9, 'Quando Sisaque, rei do Egito, atacou Jerusalém, levou todos os tesouros do templo do Senhor e do palácio real, inclusive os escudos de ouro que Salomão havia feito.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 10, 'Por isso o rei Roboão mandou fazer escudos de bronze para substituí-los, e os entregou aos chefes da guarda da entrada do palácio real.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 11, 'Sempre que o rei ia ao templo do Senhor, os guardas empunhavam os escudos, e, em seguida, os devolviam à sala da guarda.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 12, 'Como Roboão se humilhou, a ira do Senhor afastou-se dele, e ele não foi totalmente destruído. Aliás, ainda havia algo de bom em Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 13, 'O rei Roboão firmou-se no poder em Jerusalém e continuou a reinar. Tinha quarenta e um anos de idade quando começou a reinar, e reinou dezessete anos em Jerusalém, cidade que o Senhor havia escolhido dentre todas as tribos de Israel para nela pôr o seu nome. Sua mãe, uma amonita, chamava-se Naamá.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 14, 'Ele agiu mal porque não dispôs o seu coração para buscar o Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 15, 'Os demais acontecimentos do reinado de Roboão, do início ao fim, estão escritos nos relatos do profeta Semaías e do vidente Ido, que tratam de genealogias. Houve guerra constante entre Roboão e Jeroboão.', 3, CURRENT_TIMESTAMP, false),
(14, 12, 16, 'Roboão descansou com os seus antepassados e foi sepultado na cidade de Davi; seu filho Abias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 1, 'No décimo oitavo ano do reinado de Jeroboão, Abias tornou-se rei de Judá,', 3, CURRENT_TIMESTAMP, false),
(14, 13, 2, 'e reinou três anos em Jerusalém. O nome de sua mãe era Maaca, filha de Uriel, de Gibeá. E houve guerra entre Abias e Jeroboão.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 3, 'Abias entrou em combate levando uma força de quatrocentos mil excelentes guerreiros, e Jeroboão foi enfrentá-lo com oitocentos mil excelentes guerreiros.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 4, 'Abias subiu o monte Zemaraim, nos montes de Efraim, e gritou: "Jeroboão e todo o Israel, ouçam-me!', 3, CURRENT_TIMESTAMP, false),
(14, 13, 5, 'Vocês não sabem que o Senhor, o Deus de Israel, deu para sempre o reino de Israel a Davi e a seus descendentes mediante uma aliança irrevogável?', 3, CURRENT_TIMESTAMP, false),
(14, 13, 6, 'Mesmo assim, Jeroboão, filho de Nebate, servo de Salomão, filho de Davi, rebelou-se contra o seu senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 7, 'Alguns homens vadios e imprestáveis juntaram-se a ele e se opuseram a Roboão, filho de Salomão, quando ainda era jovem, indeciso e incapaz de oferecer-lhes resistência.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 8, '"E agora vocês pretendem resistir ao reino do Senhor, que está nas mãos dos descendentes de Davi. Vocês são de fato uma multidão imensa e têm os bezerros de ouro que Jeroboão fez para serem os seus deuses.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 9, 'Mas, não foram vocês que expulsaram os sacerdotes do Senhor, os descendentes de Arão, e os levitas, e escolheram os seus próprios sacerdotes, como fazem os outros povos? Quem quer que se consagre com um novilho e sete carneiros pode tornar-se sacerdote daqueles que não são deuses.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 10, '"Quanto a nós, o Senhor é o nosso Deus, e não o abandonamos. Os nossos sacerdotes, que servem ao Senhor auxiliados pelos levitas, são descendentes de Arão.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 11, 'Todas as manhãs e todas as tardes eles apresentam holocaustos e incenso aromático ao Senhor, arrumam os pães sobre a mesa cerimonialmente pura e todas as tardes acendem as lâmpadas do candelabro de ouro. Pois nós observamos as exigências do Senhor, o nosso Deus, enquanto que vocês o abandonaram.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 12, 'E vejam bem! Deus está conosco; ele é o nosso chefe. Os sacerdotes dele, com suas cornetas, farão soar o grito de guerra contra vocês. Israelitas, não lutem contra o Senhor, o Deus dos seus antepassados, pois vocês não terão êxito! "', 3, CURRENT_TIMESTAMP, false),
(14, 13, 13, 'Enquanto isso, Jeroboão tinha mandado tropas para a retaguarda do exército de Judá, de forma que ele estava em frente de Judá e a emboscada estava atrás.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 14, 'Quando o exército de Judá virou-se e viu que estava sendo atacado pela frente e pela retaguarda, clamou ao Senhor. Os sacerdotes tocaram suas cornetas,', 3, CURRENT_TIMESTAMP, false),
(14, 13, 15, 'e os homens de Judá deram o grito de guerra. Ao som do grito de guerra, Deus derrotou Jeroboão e todo o Israel diante de Abias e de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 16, 'Os israelitas fugiram dos soldados de Judá, e Deus os entregou nas mãos deles.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 17, 'Abias e os seus soldados lhes infligiram grande derrota; quinhentos mil excelentes guerreiros de Israel foram mortos.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 18, 'Os israelitas foram subjugados naquela ocasião, e os homens de Judá tiveram força para vencer, pois confiaram no Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 19, 'Abias perseguiu Jeroboão e tomou-lhe as cidades de Betel, Jesana e Efrom, com os seus povoados ao redor.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 20, 'Durante o reinado de Abias, Jeroboão não recuperou o seu poder; até que o Senhor o feriu, e ele morreu.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 21, 'Abias, ao contrário, fortaleceu-se. Ele se casou com catorze mulheres e teve vinte e dois filhos e dezesseis filhas.', 3, CURRENT_TIMESTAMP, false),
(14, 13, 22, 'Os demais acontecimentos do reinado de Abias, o que ele fez e o que disse, estão escritos nos relatos do profeta Ido.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 1, 'Abias descansou com os seus antepassados e foi sepultado na cidade de Davi. E o seu filho Asa foi o seu sucessor, e em seu reinado o país esteve em paz durante dez anos.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 2, 'Asa fez o que o Senhor, o seu Deus, aprova.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 3, 'Retirou os altares dos deuses estrangeiros e os altares idólatras que havia nos montes, despedaçou as colunas sagradas e derrubou os postes sagrados.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 4, 'Ordenou ao povo de Judá que buscasse o Senhor, o Deus dos seus antepassados, e que obedecesse às leis e aos mandamentos dele.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 5, 'Retirou os altares idólatras e os altares de incenso de todas as cidades de Judá, e o reino esteve em paz durante o seu governo.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 6, 'Também construiu cidades fortificadas em Judá, aproveitando esse período de paz. Ninguém entrou em guerra com ele durante aqueles anos, pois o Senhor lhe deu descanso.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 7, 'Disse ele ao povo de Judá: "Vamos construir estas cidades com muros ao redor, fortificadas com torres, portas e trancas. A terra ainda é nossa, porque temos buscado o Senhor, o nosso Deus; nós o buscamos, e ele nos tem concedido paz em nossas fronteiras". Eles então as construíram e prosperaram.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 8, 'Asa tinha um exército de trezentos mil homens de Judá, equipados com escudos grandes e lanças, e duzentos e oitenta mil de Benjamim, armados com escudos pequenos e arcos. Todos eram valentes homens de combate.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 9, 'O etíope Zerá marchou contra eles com um exército de um milhão de soldados e trezentos carros de guerra, e chegou a Maressa.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 10, 'Asa saiu para enfrentá-lo, e eles se puseram em posição de combate no vale de Zefatá, perto de Maressa.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 11, 'Então Asa clamou ao Senhor, o seu Deus: "Senhor, não há ninguém como tu para ajudar os fracos contra os poderosos. Ajuda-nos, ó Senhor, ó nosso Deus, pois em ti pomos a nossa confiança, e em teu nome viemos contra este imenso exército. Ó Senhor, tu és o nosso Deus; não deixes o homem prevalecer contra ti".', 3, CURRENT_TIMESTAMP, false),
(14, 14, 12, 'O Senhor derrotou os etíopes diante de Asa e de Judá. Os etíopes fugiram,', 3, CURRENT_TIMESTAMP, false),
(14, 14, 13, 'e Asa e seu exército os perseguiram até Gerar. E caíram tantos deles que o exército não conseguiu recuperar-se; foram destruídos perante o Senhor e suas forças. E os homens de Judá saquearam muitos bens.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 14, 'Destruíram todas as cidades ao redor de Gerar, pois o terror do Senhor havia caído sobre elas. Saquearam todas essas cidades, pois havia nelas muitos despojos.', 3, CURRENT_TIMESTAMP, false),
(14, 14, 15, 'Também atacaram os acampamentos onde havia gado e se apoderaram de muitas ovelhas, cabras e camelos. E então voltaram para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 1, 'O Espírito de Deus veio sobre Azarias, filho de Odede.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 2, 'Ele saiu para encontrar-se com Asa e lhe disse: "Escutem-me, Asa e todo o povo de Judá e de Benjamim. O Senhor está com vocês quando vocês estão com ele. Se o buscarem, ele deixará que o encontrem, mas, se o abandonarem, ele os abandonará.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 3, 'Durante muito tempo Israel esteve sem o verdadeiro Deus, sem sacerdote para ensiná-lo e sem a Lei.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 4, 'Mas em sua angústia eles se voltaram para o Senhor, o Deus de Israel; buscaram-no, e ele deixou que o encontrassem.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 5, 'Naqueles dias não era seguro viajar, pois muitos distúrbios afligiam a todos os habitantes do território.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 6, 'Nações e cidades se destruíam umas às outras, pois Deus as estava afligindo com toda espécie de desgraças.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 7, 'Mas, vocês devem ser fortes e não se desanimar, pois o trabalho de vocês será recompensado".', 3, CURRENT_TIMESTAMP, false),
(14, 15, 8, 'Assim que ouviu as palavras e a profecia do profeta Azarias, filho de Odede, o rei Asa encheu-se de coragem. Retirou os ídolos repugnantes de toda a terra de Judá e de Benjamim, e das cidades que havia conquistado nos montes de Efraim, e restaurou o altar do Senhor que estava em frente do pórtico do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 9, 'Depois reuniu todo o povo de Judá e de Benjamim; convocou também os que pertenciam a Efraim, a Manassés e a Simeão que viviam entre eles, pois muitos de Israel tinham passado para o lado do rei Asa, ao verem que o Senhor, o seu Deus, estava com ele.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 10, 'Eles se reuniram em Jerusalém no terceiro mês do décimo quinto ano do reinado de Asa.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 11, 'Naquela ocasião sacrificaram ao Senhor setecentos bois e sete mil ovelhas e cabras, do saque que haviam feito.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 12, 'Fizeram um acordo de todo o coração e de toda a alma de buscar o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 13, 'Todo aquele que não buscasse o Senhor, o Deus de Israel, deveria ser morto, gente simples ou importante, homem ou mulher.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 14, 'Fizeram esse juramento ao Senhor em voz alta, bradando ao som de cornetas e trombetas.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 15, 'Todo o povo de Judá alegrou-se com o juramento, pois o havia feito de todo o coração. Eles buscaram a Deus com toda disposição; então ele deixou que o encontrassem e lhes concedeu paz em suas fronteiras.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 16, 'O rei Asa chegou até a depor sua avó Maaca da posição de rainha-mãe, pois ela havia feito um poste sagrado repugnante. Asa derrubou o poste, despedaçou-o e queimou-o no vale do Cedrom.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 17, 'Embora os altares idólatras não tenham sido eliminados de Israel, o coração de Asa foi totalmente dedicado ao Senhor durante toda a sua vida.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 18, 'Ele trouxe para o templo de Deus a prata, o ouro e os utensílios que ele e seu pai haviam consagrado.', 3, CURRENT_TIMESTAMP, false),
(14, 15, 19, 'E não houve mais nenhuma guerra até o trigésimo quinto ano do seu reinado.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 1, 'No trigésimo sexto ano do reinado de Asa, Baasa, rei de Israel, invadiu Judá e fortificou Ramá, para que ninguém pudesse entrar nem sair do território de Asa, rei de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 2, 'Então Asa ajuntou a prata e o ouro do tesouro do templo do Senhor e do seu próprio palácio e os enviou a Ben-Hadade, rei da Síria, que governava em Damasco, com uma mensagem que dizia:', 3, CURRENT_TIMESTAMP, false),
(14, 16, 3, '"Façamos um tratado, como fizeram meu pai e o teu. Estou te enviando prata e ouro. Agora, rompe o tratado que tens com Baasa, rei de Israel, para que ele saia do meu país".', 3, CURRENT_TIMESTAMP, false),
(14, 16, 4, 'Ben-Hadade aceitou a proposta do rei Asa e ordenou aos comandantes das suas forças que atacassem as cidades de Israel. Eles conquistaram Ijom, Dã, Abel-Maim e todas as cidades-armazéns de Naftali.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 5, 'Quando Baasa soube disso, abandonou a construção dos muros de Ramá.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 6, 'Então o rei Asa reuniu todos os homens de Judá, e eles retiraram de Ramá as pedras e a madeira que Baasa estivera usando. Com esse material Asa fortificou Geba e Mispá.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 7, 'Naquela época, o vidente Hanani foi dizer a Asa, rei de Judá: "Por você ter pedido ajuda ao rei da Síria e não ao Senhor, ao seu Deus, o exército do rei da Síria escapou de suas mãos.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 8, 'Por acaso os etíopes e os líbios não eram um exército poderoso, com uma grande multidão de carros e cavalos? Contudo, quando você pediu ajuda ao Senhor, ele os entregou em suas mãos.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 9, 'Pois os olhos do Senhor estão atentos sobre toda a terra para fortalecer aqueles que lhe dedicam totalmente o coração. Nisso você cometeu uma loucura. De agora em diante terás que enfrentar guerras".', 3, CURRENT_TIMESTAMP, false),
(14, 16, 10, 'Asa irritou-se contra o vidente por causa disso; ficou tão indignado que mandou prendê-lo. Nessa época Asa oprimiu brutalmente alguns do povo.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 11, 'Os demais acontecimentos do reinado de Asa, do início ao fim, estão escritos nos registros históricos dos reis de Judá e de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 12, 'No trigésimo nono ano de seu reinado, Asa foi atacado por uma doença nos pés. Embora a sua doença fosse grave, não buscou ajuda do Senhor, mas só dos médicos.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 13, 'Então, no quadragésimo primeiro ano do seu reinado, Asa morreu e descansou com os seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 16, 14, 'Sepultaram-no no túmulo que ele havia mandado cavar para si na cidade de Davi. Deitaram-no num leito coberto de especiarias e de vários perfumes de fina mistura, e fizeram uma imensa fogueira em sua honra.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 1, 'Josafá, filho de Asa, foi o seu sucessor e fortaleceu-se contra Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 2, 'Posicionou tropas em todas as cidades fortificadas de Judá e pôs guarnições em Judá e nas cidades de Efraim que seu pai, Asa, tinha conquistado.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 3, 'O Senhor esteve com Josafá porque, em seus primeiros anos, ele andou nos caminhos que seu pai Davi tinha seguido. Não consultou os baalins,', 3, CURRENT_TIMESTAMP, false),
(14, 17, 4, 'mas buscou o Deus de seu pai e obedeceu aos seus mandamentos, e não imitou as práticas de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 5, 'O Senhor firmou o reino de Josafá, e todo o Judá lhe trazia presentes, de maneira que teve grande riqueza e honra.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 6, 'Ele seguiu corajosamente os caminhos do Senhor; além disso, retirou de Judá os altares idólatras e os postes sagrados.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 7, 'No terceiro ano de seu reinado, ele enviou seus oficiais Bene-Hail, Obadias, Zacarias, Natanael e Micaías para ensinarem nas cidades de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 8, 'Com eles foram os levitas Semaías, Netanias, Zebadias, Asael, Semiramote, Jônatas, Adonias, Tobias, Tobe-Adonias e os sacerdotes Elisama e Jeorão.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 9, 'Eles percorreram todas as cidades do reino de Judá, levando consigo o Livro da Lei do Senhor e ensinando o povo.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 10, 'O temor do Senhor caiu sobre todos os reinos ao redor de Judá, de forma que não entraram em guerra contra Josafá.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 11, 'Alguns filisteus levaram presentes a Josafá, além da prata que lhe deram como tributo, e os árabes levaram-lhe rebanhos: sete mil e setecentos carneiros e sete mil e setecentos bodes.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 12, 'Josafá foi se tornando cada vez mais poderoso; construiu fortalezas e cidades-armazéns em Judá,', 3, CURRENT_TIMESTAMP, false),
(14, 17, 13, 'onde guardava enorme quantidade de suprimentos. Também mantinha em Jerusalém homens de combate experientes.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 14, 'A lista desses homens, por famílias, era a seguinte: De Judá, líderes de batalhões de 1. 000: o líder Adna, com 300. 000 homens de combate;', 3, CURRENT_TIMESTAMP, false),
(14, 17, 15, 'em seguida, o líder Joanã, com 280. 000;', 3, CURRENT_TIMESTAMP, false),
(14, 17, 16, 'depois, Amasias, filho de Zicri, que se apresentou voluntariamente para o serviço do Senhor, com 200. 000.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 17, 'De Benjamim: Eliada, um guerreiro valente, com 200. 000 homens armados com arcos e escudos;', 3, CURRENT_TIMESTAMP, false),
(14, 17, 18, 'Jeozabade, com 180. 000 homens armados para a batalha.', 3, CURRENT_TIMESTAMP, false),
(14, 17, 19, 'Esses eram os homens que serviam o rei, além dos que estavam posicionados nas cidades fortificadas em todo o Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 1, 'Josafá tinha grande riqueza e honra, e aliou-se a Acabe mediante casamento.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 2, 'Alguns anos depois, ele foi visitar Acabe em Samaria. Acabe abateu muitas ovelhas e bois para receber a ele e à sua comitiva, e insistiu que atacasse Ramote-Gileade.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 3, 'Acabe, rei de Israel, perguntou a Josafá, rei de Judá: "Irás comigo lutar contra Ramote-Gileade? " Josafá respondeu: "Sou como tu, e meu povo é como o teu povo; estaremos contigo na guerra".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 4, 'Mas acrescentou: "Peço-te que busques primeiro o conselho do Senhor".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 5, 'Então o rei de Israel reuniu quatrocentos profetas, e lhes perguntou: "Devemos ir à guerra contra Ramote-Gileade, ou não? " Eles responderam: "Sim, pois Deus a entregará nas mãos do rei".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 6, 'Josafá, porém, perguntou: "Não existe aqui mais nenhum profeta do Senhor, a quem possamos consultar? "', 3, CURRENT_TIMESTAMP, false),
(14, 18, 7, 'O rei de Israel respondeu a Josafá: "Ainda há um homem por meio de quem podemos consultar o Senhor, mas eu o odeio, porque nunca profetiza coisas boas a meu respeito, mas sempre coisas ruins. É Micaías, filho de Inlá". "O rei não deveria dizer isso", Josafá respondeu.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 8, 'Então o rei de Israel chamou um dos seus oficiais e disse: "Traga Micaías, filho de Inlá, imediatamente".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 9, 'Usando vestes reais, o rei de Israel e Josafá, rei de Judá, estavam sentados em seus tronos, na eira, junto à porta de Samaria, e todos os profetas estavam profetizando em transe diante deles.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 10, 'E Zedequias, filho de Quenaaná, tinha feito chifres de ferro, e declarou: "Assim diz o Senhor: ‘Com estes chifres tu ferirás os arameus até que sejam destruídos’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 11, 'Todos os outros profetas estavam profetizando a mesma coisa, dizendo: "Ataca Ramote-Gileade, e serás vitorioso, pois o Senhor a entregará nas mãos do rei".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 12, 'O mensageiro que tinha ido chamar Micaías lhe disse: "Veja, todos os outros profetas estão predizendo que o rei terá sucesso. Sua palavra também deve ser favorável".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 13, 'Micaías, porém, disse: "Juro pelo nome do Senhor, que direi o que o meu Deus mandar".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 14, 'Quando ele chegou, o rei lhe perguntou: "Micaías, devemos ir à guerra contra Ramote-Gileade, ou não? " Ele respondeu: "Atacai, e sereis vitoriosos, pois eles serão entregues em vossas mãos".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 15, 'O rei lhe disse: "Quantas vezes devo fazer você jurar que me irá dizer somente a verdade em nome do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(14, 18, 16, 'Então Micaías respondeu: "Vi todo o Israel espalhado pelas colinas, como ovelhas sem pastor, e o Senhor dizer: ‘Estes não têm dono. Cada um volte para casa em paz’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 17, 'O rei de Israel disse a Josafá: "Não lhe disse que ele nunca profetiza nada de bom a meu respeito, mas apenas coisas ruins? "', 3, CURRENT_TIMESTAMP, false),
(14, 18, 18, 'Micaías prosseguiu: "Ouçam a palavra do Senhor: Vi o Senhor assentado em seu trono, com todo o exército dos céus à sua direita e à sua esquerda.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 19, 'E o Senhor disse: ‘Quem enganará Acabe, rei de Israel, para que ataque Ramote-Gileade e morra lá? ’ "E um sugeria uma coisa, outro sugeria outra, até que,', 3, CURRENT_TIMESTAMP, false),
(14, 18, 20, 'finalmente, um espírito colocou-se diante do Senhor e disse: ‘Eu o enganarei’. " ‘De que maneira? ’, perguntou o Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 21, '"Ele respondeu: ‘Irei e serei um espírito mentiroso na boca de todos os profetas do rei’. "Disse o Senhor: ‘Você conseguirá enganá-lo; vá e engane-o’.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 22, '"E o Senhor pôs um espírito mentiroso na boca destes seus profetas. O Senhor decretou a sua desgraça".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 23, 'Então Zedequias, filho de Quenaaná, aproximou-se, deu um tapa no rosto de Micaías e perguntou: "Por qual caminho foi o espírito da parte do Senhor, quando saiu de mim para falar a você? "', 3, CURRENT_TIMESTAMP, false),
(14, 18, 24, 'Micaías respondeu: "Você descobrirá no dia em que estiver se escondendo de quarto em quarto".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 25, 'O rei de Israel então ordenou: "Enviem Micaías de volta a Amom, o governador da cidade, e a Joás, filho do rei,', 3, CURRENT_TIMESTAMP, false),
(14, 18, 26, 'e digam: Assim diz o rei: Ponham este homem na prisão a pão e água, até que eu volte em segurança".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 27, 'Micaías declarou: "Se você de fato voltar em segurança, o Senhor não falou por meu intermédio". E acrescentou: "Ouçam o que estou dizendo, todos vocês! "', 3, CURRENT_TIMESTAMP, false),
(14, 18, 28, 'Então o rei de Israel e Josafá, rei de Judá, foram atacar Ramote-Gileade.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 29, 'E o rei de Israel disse a Josafá: "Entrarei disfarçado em combate, mas tu, usa as tuas vestes reais". O rei de Israel disfarçou-se, e ambos foram para o combate.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 30, 'O rei da Síria havia ordenado a seus chefes dos carros de guerra: "Não lutem contra ninguém, seja soldado seja oficial, senão contra o rei de Israel".', 3, CURRENT_TIMESTAMP, false),
(14, 18, 31, 'Quando os chefes dos carros viram Josafá, pensaram: "É o rei de Israel", e o cercaram para atacá-lo, mas Josafá clamou, e o Senhor o ajudou. Deus os afastou dele,', 3, CURRENT_TIMESTAMP, false),
(14, 18, 32, 'pois, quando os comandantes dos carros viram que não era o rei de Israel, deixaram de persegui-lo.', 3, CURRENT_TIMESTAMP, false),
(14, 18, 33, 'De repente, um soldado disparou seu arco ao acaso, e atingiu o rei de Israel entre os encaixes da sua armadura. Então o rei disse ao condutor do seu carro: "Tire-me do combate. Fui ferido! "', 3, CURRENT_TIMESTAMP, false),
(14, 18, 34, 'A batalha foi violenta durante todo o dia, e assim, o rei de Israel teve que enfrentar os arameus em pé no seu carro, até à tarde. E, ao pôr-do-sol, ele morreu.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 1, 'Quando Josafá, rei de Judá, voltou em segurança ao seu palácio em Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(14, 19, 2, 'o vidente Jeú, filho de Hanani, saiu ao seu encontro e lhe disse: "Será que você devia ajudar os ímpios e amar aqueles que odeiam o Senhor? Por causa disso, a ira do Senhor está sobre você.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 3, 'Contudo, existe em você algo de bom, pois você livrou a terra dos postes sagrados e buscou a Deus de todo o seu coração".', 3, CURRENT_TIMESTAMP, false),
(14, 19, 4, 'Josafá morava em Jerusalém; e saiu de novo entre o povo, desde Berseba até os montes de Efraim, fazendo-o voltar para o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 5, 'Ele nomeou juízes, em cada uma das cidades fortificadas de Judá,', 3, CURRENT_TIMESTAMP, false),
(14, 19, 6, 'dizendo-lhes: "Considerem atentamente aquilo que fazem, pois vocês não estão julgando para o homem, mas para o Senhor, que estará com vocês sempre que derem um veredicto.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 7, 'Agora, que o temor do Senhor esteja sobre vocês. Julguem com cuidado, pois com o Senhor, o nosso Deus, não há injustiça nem parcialidade nem suborno".', 3, CURRENT_TIMESTAMP, false),
(14, 19, 8, 'Também em Jerusalém nomeou Josafá alguns dos levitas, dos sacerdotes e dos chefes de famílias israelitas para julgarem questões da lei do Senhor e resolverem pendências dos habitantes.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 9, 'Deu-lhes as seguintes ordens: "Vocês devem servir com fidelidade e com coração íntegro, no temor do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 10, 'Em cada caso que chegar a vocês da parte dos seus irmãos israelitas das outras cidades, seja caso de derramamento de sangue sejam questões referentes à lei, aos mandamentos, aos decretos ou às ordenanças, vocês deverão adverti-los de que não pequem contra o Senhor; caso contrário a ira dele virá sobre vocês e sobre eles. Façam assim, e vocês não pecarão.', 3, CURRENT_TIMESTAMP, false),
(14, 19, 11, '"Amarias, o sumo sacerdote, estará com vocês para decidir qualquer questão referente à lei do Senhor; Zebadias, filho de Ismael, líder da tribo de Judá, estará com vocês para decidir qualquer questão civil; e os levitas atuarão como oficiais diante de vocês. Cumpram seus deveres com coragem, e esteja o Senhor com aqueles que agirem corretamente".', 3, CURRENT_TIMESTAMP, false),
(14, 20, 1, 'Depois disso, os moabitas e os amonitas, com alguns dos meunitas, entraram em guerra contra Josafá.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 2, 'Então informaram a Josafá: "Um exército enorme vem contra ti de Edom, do outro lado do mar Morto. Já está em Hazazom-Tamar, isto é, En-Gedi".', 3, CURRENT_TIMESTAMP, false),
(14, 20, 3, 'Alarmado, Josafá decidiu consultar o Senhor e proclamou um jejum em todo o reino de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 4, 'Reuniu-se, pois, o povo, vindo de todas as cidades de Judá para buscar a ajuda do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 5, 'Então Josafá levantou-se na assembléia de Judá e de Jerusalém, no templo do Senhor, na frente do pátio novo,', 3, CURRENT_TIMESTAMP, false),
(14, 20, 6, 'e orou: "Senhor, Deus dos nossos antepassados, não és tu o Deus que está nos céus? Tu governas sobre todos os reinos do mundo. Força e poder estão em tuas mãos, e ninguém pode opor-se a ti.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 7, 'Não és tu o nosso Deus, que expulsaste os habitantes desta terra perante Israel, teu povo, e a deste para sempre aos descendentes de teu amigo Abraão?', 3, CURRENT_TIMESTAMP, false),
(14, 20, 8, 'Eles a têm habitado e nela construíram um santuário em honra do teu nome, dizendo:', 3, CURRENT_TIMESTAMP, false),
(14, 20, 9, '‘Se alguma desgraça nos atingir, seja o castigo da espada, seja a peste, seja a fome, nós nos colocaremos em tua presença diante deste templo, pois ele leva o teu nome, e clamaremos a ti em nossa angústia, e tu nos ouvirás e nos salvarás’.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 10, '"Mas agora, aí estão amonitas, moabitas e habitantes dos montes de Seir, cujos territórios não permitiste que Israel invadisse quando vinha do Egito; por isso os israelitas se desviaram deles e não os destruíram.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 11, 'Vê agora como estão nos retribuindo, ao virem expulsar-nos da terra que nos deste por herança.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 12, 'Ó nosso Deus, não irás tu julgá-los? Pois não temos força para enfrentar esse exército imenso que está nos atacando. Não sabemos o que fazer, mas os nossos olhos se voltam para ti".', 3, CURRENT_TIMESTAMP, false),
(14, 20, 13, 'Todos os homens de Judá, com suas mulheres e seus filhos, até os de colo, estavam ali de pé, diante do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 14, 'Então o Espírito do Senhor veio sobre Jaaziel, filho de Zacarias, neto de Benaia, bisneto de Jeiel e trineto de Matanias, levita e descendente de Asafe, no meio da assembléia.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 15, 'Ele disse: "Escutem, todos os que vivem em Judá e em Jerusalém e o rei Josafá! Assim lhes diz o Senhor: ‘Não tenham medo nem fiquem desanimados por causa desse exército enorme. Pois a batalha não é de vocês, mas de Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 16, 'Amanhã, desçam contra eles. Eles virão pela subida de Ziz, e vocês os encontrarão no fim do vale, em frente do deserto de Jeruel.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 17, 'Vocês não precisarão lutar nessa batalha. Tomem suas posições; permaneçam firmes e vejam o livramento que o Senhor lhes dará, ó Judá, ó Jerusalém. Não tenham medo nem se desanimem. Saiam para enfrentá-los amanhã, e o Senhor estará com vocês’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 20, 18, 'Josafá prostrou-se, rosto em terra, e todo o povo de Judá e de Jerusalém prostrou-se em adoração perante o Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 19, 'Então os levitas descendentes dos coatitas e dos coreítas levantaram-se e louvaram o Senhor, o Deus de Israel, em alta voz.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 20, 'De madrugada partiram para o deserto de Tecoa. Quando estavam saindo, Josafá lhes disse: "Escutem-me, Judá e povo de Jerusalém! Tenham fé no Senhor, o seu Deus, e vocês serão sustentados; tenham fé nos profetas dele e vocês terão a vitória".', 3, CURRENT_TIMESTAMP, false),
(14, 20, 21, 'Depois de consultar o povo, Josafá nomeou alguns homens para cantarem ao Senhor e o louvarem pelo esplendor de sua santidade, indo à frente do exército, cantando: "Dêem graças ao Senhor, pois o seu amor dura para sempre".', 3, CURRENT_TIMESTAMP, false),
(14, 20, 22, 'Quando começaram a cantar e a entoar louvores, o Senhor preparou emboscadas contra os homens de Amom, de Moabe e dos montes de Seir que estavam invadindo Judá, e eles foram derrotados.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 23, 'Os amonitas e os moabitas atacaram os dos montes de Seir para destruí-los e aniquilá-los. Depois de massacrarem os homens de Seir, destruiram-se uns aos outros.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 24, 'Quando os homens de Judá foram para o lugar de onde se avista o deserto e olharam para o imenso exército, viram somente cadáveres no chão; ninguém havia escapado.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 25, 'Então, Josafá e os seus soldados foram saquear os cadáveres e encontraram entre eles grande quantidade de equipamentos e roupas, e também objetos de valor; passaram três dias saqueando, mas havia mais do que eram capazes de levar.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 26, 'No quarto dia eles se reuniram no vale de Beraca, onde louvaram o Senhor. Por isso até hoje ele é chamado vale de Beraca.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 27, 'Depois sob a liderança de Josafá, todos os homens de Judá e de Jerusalém voltaram alegres para Jerusalém, pois o Senhor lhes enchera de alegria, dando-lhes vitória sobre os seus inimigos.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 28, 'Entraram em Jerusalém e foram ao templo do Senhor, ao som de liras, harpas e cornetas.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 29, 'O temor de Deus veio sobre todas as nações, quando souberam como o Senhor havia lutado contra os inimigos de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 30, 'E o reino de Josafá manteve-se em paz, pois o seu Deus lhe concedeu paz em todas as suas fronteiras.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 31, 'Assim Josafá reinou sobre Judá. Ele tinha trinta e cinco anos de idade quando se tornou rei, e reinou vinte e cinco anos em Jerusalém. O nome da sua mãe era Azuba, filha de Sili.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 32, 'Ele andou nos caminhos de Asa, seu pai, e não se desviou deles; fez o que o Senhor aprova.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 33, 'Contudo, não acabou com os altares idólatras, e o povo ainda não havia firmado o coração no Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 34, 'Os demais acontecimentos do reinado de Josafá, do início ao fim, estão escritos nos relatos de Jeú, filho de Hanani, e incluídos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 35, 'Posteriormente, Josafá, rei de Judá, fez um tratado com Acazias, rei de Israel, que tinha vida ímpia.', 3, CURRENT_TIMESTAMP, false),
(14, 20, 36, 'Era um tratado para a construção de navios mercantes. Depois de serem construídos os navios em Eziom-Geber,', 3, CURRENT_TIMESTAMP, false),
(14, 20, 37, 'Eliézer, filho de Dodava de Maressa, profetizou contra Josafá, dizendo: "Por haver feito um tratado com Acazias, o Senhor destruirá o que você fez". Assim, os navios naufragaram e não puderam sair para negociar.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 1, 'Josafá descansou com seus antepassados e foi sepultado junto deles na cidade de Davi, e seu filho Jeorão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 2, 'Os irmãos de Jeorão, filhos de Josafá, foram Azarias, Jeiel, Zacarias, Azarias, Micael e Sefatias. Todos eles foram filhos de Josafá, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 3, 'Ele deu-lhes muitos presentes de prata e ouro e objetos de valor, bem como cidades fortificadas em Judá, mas o reino deu a Jeorão, porque este era seu filho mais velho.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 4, 'Logo Jeorão se fortaleceu no reino de seu pai, e matou à espada todos os seus irmãos, juntamente com alguns dos líderes de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 5, 'Ele tinha trinta e dois anos de idade quando começou a reinar, e reinou oito anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 6, 'Andou nos caminhos dos reis de Israel, como a família de Acabe havia feito, pois se casou com uma filha de Acabe. E fez o que o Senhor reprova.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 7, 'Entretanto, por causa da aliança que havia feito com Davi, o Senhor não quis destruir a dinastia dele. Ele havia prometido manter para sempre um descendente de Davi no trono.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 8, 'Nos dias de Jeorão, os edomitas rebelaram-se contra o domínio de Judá, proclamando seu próprio rei.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 9, 'Por isso, Jeorão foi combatê-los com seus líderes e com todos os seus carros de guerra. Os edomitas cercaram a ele e aos chefes de seus carros de guerra, mas ele os atacou de noite e rompeu o cerco inimigo.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 10, 'E até hoje Edom continua independente de Judá. Nessa mesma época, a cidade de Libna também tornou-se independente, pois Jeorão havia abandonado o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 11, 'Ele até construiu altares idólatras nas colinas de Judá, levando o povo de Jerusalém a prostituir-se e Judá a desviar-se.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 12, 'Então Jeorão recebeu uma carta do profeta Elias, que dizia: "Assim diz o Senhor, o Deus de Davi, seu antepassado: ‘Você não tem andado nos caminhos de seu pai Josafá nem de Asa, rei de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 13, 'Mas sim nos caminhos dos reis de Israel, e levou Judá e o povo de Jerusalém a se prostituírem na idolatria como a família de Acabe. E ainda assassinou seus próprios irmãos, membros da família de seu pai, homens que eram melhores do que você.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 14, 'Por isso, o Senhor vai ferir terrivelmente seu povo, seus filhos, suas mulheres e tudo o que é seu.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 15, 'Você ficará muito doente; terá uma enfermidade no ventre, que irá piorar até que saiam os seus intestinos’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 21, 16, 'O Senhor despertou contra Jeorão a hostilidade dos filisteus e dos árabes que viviam perto dos etíopes.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 17, 'Eles atacaram o reino de Judá, invadiram-no e levaram todos os bens que encontraram no palácio do rei, juntamente com suas mulheres e seus filhos. Só ficou Acazias, o filho mais novo.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 18, 'Depois disso tudo, o Senhor afligiu Jeorão com uma doença incurável nos intestinos.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 19, 'Algum tempo depois, ao fim do segundo ano, tanto se agravou a doença que os seus intestinos saíram, e ele morreu sofrendo dores horríveis. Seu povo não fez nenhuma fogueira em sua homenagem, como havia feito para os seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 21, 20, 'Jeorão tinha trinta e dois anos de idade quando começou a reinar, e reinou oito anos em Jerusalém. Morreu sem que ninguém o lamentasse, e foi sepultado na cidade de Davi, mas não nos túmulos dos reis.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 1, 'O povo de Jerusalém proclamou Acazias, filho mais novo de Jeorão, rei em seu lugar, uma vez que as tropas que vieram com os árabes haviam matado todos os outros filhos dele. Assim começou a reinar Acazias, filho de Jeorão, rei de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 2, 'Acazias tinha vinte e dois anos de idade quando começou a reinar, e reinou um ano em Jerusalém. O nome de sua mãe era Atalia, neta de Onri.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 3, 'Ele também andou nos caminhos da família de Acabe, pois sua mãe lhe dava maus conselhos.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 4, 'Ele fez o que o Senhor reprova, como a família de Acabe havia feito, pois, depois da morte de seu pai, eles se tornaram seus conselheiros, para sua ruína.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 5, 'Ele também seguiu o conselho deles quando aliou-se a Jorão, filho de Acabe, rei de Israel, e saiu à guerra contra Hazael, rei da Síria, em Ramote-Gileade. Jorão foi ferido', 3, CURRENT_TIMESTAMP, false),
(14, 22, 6, 'e voltou a Jezreel para recuperar-se dos ferimentos sofridos em Ramote, na batalha contra Hazael, rei da Síria. Depois Acazias, rei de Judá, foi a Jezreel visitar Jorão, que se recuperava de seus ferimentos.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 7, 'Por meio dessa visita, Deus provocou a queda de Acazias. Quando ele chegou, saiu com Jorão ao encontro de Jeú, filho de Ninsi, a quem o Senhor havia ungido para destruir a família de Acabe.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 8, 'Quando Jeú estava executando juízo sobre a família de Acabe, encontrou os líderes de Judá e os filhos dos parentes de Acazias, que o serviam, e os matou.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 9, 'Saiu então em busca de Acazias, e seus soldados o capturaram em Samaria, onde estava escondido. Levado a Jeú, Acazias foi morto. Mas não lhe negaram sepultura, pois disseram: "Ele era neto de Josafá, que buscou o Senhor de todo o coração". Assim, a família de Acazias não tinha mais ninguém que pudesse ser rei.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 10, 'Quando Atalia, mãe de Acazias, soube que seu filho estava morto, mandou matar toda a família real de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 11, 'Mas Jeoseba, filha do rei Jeorão, pegou Joás, um dos filhos do rei Acazias que iam ser assassinados, e o colocou num quarto, junto com a sua ama. Assim Jeoseba, filha do rei Jeorão, mulher do sacerdote Joiada e irmã de Acazias, escondeu Joás de Atalia, de forma que ela não pôde matá-lo.', 3, CURRENT_TIMESTAMP, false),
(14, 22, 12, 'Seis anos ele ficou escondido com elas no templo de Deus, enquanto Atalia governava o país.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 1, 'No sétimo ano Joiada encorajou-se e fez um acordo com os líderes dos batalhões de cem: Azarias, filho de Jeroão, Ismael, filho de Joanã, Azarias, filho de Obede, Maaséias, filho de Adaías, e Elisafate, filho de Zicri.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 2, 'Eles percorreram todo o Judá e reuniram de todas as cidades, os levitas e os chefes das famílias israelitas. Quando chegaram a Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(14, 23, 3, 'toda a assembléia fez um acordo com o rei no templo de Deus. Joiada lhes disse: "Reinará o filho do rei, conforme o Senhor prometeu acerca dos descendentes de Davi.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 4, 'Vocês vão fazer o seguinte: Um terço de vocês, sacerdotes e levitas que entrarão de serviço no sábado, deverá ficar vigiando nas portas do templo;', 3, CURRENT_TIMESTAMP, false),
(14, 23, 5, 'um terço, no palácio real; e um terço, na porta do Alicerce; e todo o povo estará nos pátios do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 6, 'Ninguém deverá entrar no templo do Senhor, exceto os sacerdotes e os levitas de serviço; esses podem entrar porque são consagrados, mas o povo deverá observar o que o Senhor lhes determinou.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 7, 'Os levitas deverão posicionar-se em torno do rei, todos de armas na mão. Matem todo aquele que entrar no templo. Acompanhem o rei aonde quer que ele for".', 3, CURRENT_TIMESTAMP, false),
(14, 23, 8, 'Os levitas e todos os homens de Judá fizeram como o sacerdote Joiada havia ordenado. Cada um levou seus soldados, tanto os que estavam entrando de serviço no sábado como os que estavam saindo, pois o sacerdote Joiada não havia dispensado nenhuma das divisões.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 9, 'Então ele deu aos líderes dos batalhões de cem, as lanças e os escudos grandes e pequenos que haviam pertencido ao rei Davi, e que estavam no templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 10, 'Posicionou todos os homens, todos de arma na mão, em volta do rei, perto do altar e do templo, desde o lado sul até o lado norte do templo.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 11, 'Joiada e seus filhos trouxeram o filho do rei e o coroaram; entregaram-lhe uma cópia da aliança e o proclamaram rei, ungindo-o e gritando: "Viva o rei! "', 3, CURRENT_TIMESTAMP, false),
(14, 23, 12, 'Quando Atalia ouviu o barulho do povo correndo e aclamando o rei, foi ao templo do Senhor, onde estava o povo.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 13, 'Lá ela viu o rei à entrada, de pé junto à coluna. Os oficiais e tocadores de cornetas estavam ao lado do rei, e todo o povo se alegrava ao som das cornetas; os músicos com seus instrumentos musicais dirigiam os louvores. Então Atalia rasgou suas vestes e gritou: "Traição! Traição! "', 3, CURRENT_TIMESTAMP, false),
(14, 23, 14, 'O sacerdote Joiada ordenou aos líderes dos batalhões de cem que estavam no comando das tropas: "Levem-na para fora por entre as fileiras, e matem à espada todo que a seguir". Pois o sacerdote dissera: "Não a matem no templo do Senhor".', 3, CURRENT_TIMESTAMP, false),
(14, 23, 15, 'Então eles a prenderam e levaram à porta dos Cavalos, no terreno do palácio, e lá a mataram.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 16, 'E Joiada fez um acordo pelo qual ele, o povo e o rei seriam o povo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 17, 'Então todo o povo foi ao templo de Baal e o derrubou. Despedaçaram os altares e os ídolos, e mataram Matã, sacerdote de Baal, em frente dos altares.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 18, 'E Joiada confiou a supervisão do templo do Senhor aos sacerdotes levitas, aos quais Davi tinha atribuído tarefas no templo, para apresentarem os holocaustos ao Senhor, conforme está escrito na lei de Moisés, com júbilo e cânticos, segundo as instruções de Davi.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 19, 'Também pôs guardas nas portas do templo do Senhor para que não entrasse ninguém que de alguma forma estivesse impuro.', 3, CURRENT_TIMESTAMP, false),
(14, 23, 20, 'Levou consigo os líderes dos batalhões de cem, os nobres, os governantes do povo e todo o povo e, juntos, conduziram o rei do templo do Senhor ao palácio, passando pela porta superior, e instalaram o rei no trono;', 3, CURRENT_TIMESTAMP, false),
(14, 23, 21, 'e todo o povo se alegrou. A cidade acalmou-se depois que Atalia foi morta à espada.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 1, 'Joás tinha sete anos de idade quando se tornou rei, e reinou quarenta anos em Jerusalém. O nome de sua mãe era Zíbia; ela era de Berseba.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 2, 'Joás fez o que o Senhor aprova enquanto viveu o sacerdote Joiada.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 3, 'Joiada escolheu para ele duas mulheres, e ele teve filhos e filhas.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 4, 'Algum tempo depois Joás decidiu fazer reparos no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 5, 'Ele reuniu os sacerdotes e os levitas e lhes disse: "Vão às cidades de Judá e recolham o imposto devido anualmente por todo o Israel, para fazer reparos no templo de seu Deus. Vão agora mesmo! " Os levitas, porém, não agiram imediatamente.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 6, 'Por isso, o rei convocou Joiada, o sumo sacerdote, e lhe perguntou: "Por que você não exigiu que os levitas trouxessem de Judá e de Jerusalém o imposto determinado por Moisés, servo do Senhor, e pela assembléia de Israel para a tenda da arca da aliança? "', 3, CURRENT_TIMESTAMP, false),
(14, 24, 7, 'De fato, Atalia, aquela mulher ímpia, e os seus filhos tinham arrombado o templo de Deus e tinham até usado os seus objetos sagrados para cultuar os baalins.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 8, 'Então, por ordem do rei, fizeram uma caixa e a colocaram do lado de fora, à entrada do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 9, 'Fez-se então uma proclamação em Judá e em Jerusalém para que trouxessem ao Senhor o imposto que Moisés, servo do Senhor, havia exigido de Israel no deserto.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 10, 'Todos os líderes e todo o povo trouxeram com alegria as suas contribuições, colocando-as na caixa até enchê-la.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 11, 'Sempre que os levitas levavam a caixa até os supervisores do rei, e esses viam que havia muita prata, o secretário real e o oficial do sumo sacerdote esvaziavam-na e a levavam de volta. Fazendo isso regularmente, ajuntaram uma grande quantidade de prata.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 12, 'O rei e Joiada entregavam essa prata aos homens que executavam os trabalhos necessários no templo do Senhor. Eles contratavam pedreiros, carpinteiros e também operários que trabalham em ferro e em bronze para restaurarem o templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 13, 'Os homens encarregados do trabalho eram diligentes, o que garantiu o progresso da obra de reforma. Eles reconstruíram o templo de Deus de acordo com o modelo original e o reforçaram.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 14, 'Quando terminaram, trouxeram o restante da prata ao rei e a Joiada, e com ela foram feitos utensílios para o templo do Senhor; utensílios para o serviço e para os holocaustos, além de tigelas e outros objetos de ouro e prata. Enquanto Joiada viveu, holocaustos foram apresentados continuamente no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 15, 'Joiada chegou à idade avançada, e morreu com cento e trinta anos.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 16, 'Ele foi sepultado com os reis na cidade de Davi, em atenção ao bem que havia feito em Israel em favor de Deus e do seu templo.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 17, 'Depois da morte de Joiada, os líderes de Judá foram falar com o rei e lhe prestaram reverências, e ele aceitou o que disseram.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 18, 'Então abandonaram o templo do Senhor, o Deus dos seus antepassados, e prestaram culto aos postes sagrados e aos ídolos. Por culpa deles, a ira de Deus veio sobre Judá e Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 19, 'Embora o Senhor tivesse enviado profetas ao povo para trazê-los de volta para ele e os profetas tivessem testemunhado contra eles, o povo não quis ouvi-los.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 20, 'Então o Espírito de Deus apoderou-se de Zacarias, filho do sacerdote Joiada. Ele se colocou diante do povo e disse: "Isto é o que Deus diz: ‘Por que vocês desobedecem aos mandamentos do Senhor? Vocês não prosperarão. Já que abandonaram o Senhor, ele os abandonará’ ".', 3, CURRENT_TIMESTAMP, false),
(14, 24, 21, 'Mas, alguns conspiraram contra ele e, por ordem do rei, apedrejaram-no até à morte no pátio do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 22, 'O rei Joás não levou em conta que Joiada, pai de Zacarias, tinha sido bondoso com ele, e matou o seu filho. Este, ao morrer, exclamou: "Veja isto o Senhor e faça justiça! "', 3, CURRENT_TIMESTAMP, false),
(14, 24, 23, 'Na virada do ano, o exército arameu marchou contra Joás; invadiu Judá e Jerusalém, matou todos os líderes do povo, e enviou para Damasco, para o seu rei, tudo o que saqueou.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 24, 'Embora o exército arameu fosse pequeno, o Senhor entregou nas mãos dele um exército muito maior, por haver Judá abandonado o Senhor, o Deus dos seus antepassados. Assim o juízo foi executado sobre Joás.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 25, 'Quando os arameus foram embora, deixaram Joás seriamente ferido. Seus oficiais conspiraram contra ele, porque ele tinha assassinado o filho do sacerdote Joiada, e o mataram em sua cama. Assim ele morreu e foi sepultado na cidade de Davi, mas não nos túmulos dos reis.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 26, 'Os que conspiraram contra ele foram Zabade, filho da amonita Simeate, e Jeozabade, filho da moabita Sinrite.', 3, CURRENT_TIMESTAMP, false),
(14, 24, 27, 'Quanto a seus filhos, às muitas profecias a seu respeito e ao relato da restauração do templo, tudo está escrito nas anotações dos livros dos reis. E seu filho Amazias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 1, 'Amazias tinha vinte e cinco anos de idade quando começou a reinar, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Jeoadã; ela era de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 2, 'Ele fez o que o Senhor aprova, mas não de todo o coração.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 3, 'Quando sentiu que tinha o reino sob pleno controle, mandou executar os oficiais que haviam assassinado o rei, seu pai.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 4, 'Contudo, não matou os filhos dos assassinos, de acordo com o que está escrito na Lei, no livro de Moisés, onde o Senhor ordenou: "Os pais não morrerão no lugar dos filhos, nem os filhos no lugar dos pais; cada um morrerá pelo seu próprio pecado".', 3, CURRENT_TIMESTAMP, false),
(14, 25, 5, 'Amazias reuniu os homens de Judá e, de acordo com as suas respectivas famílias, nomeou chefes de mil e de cem em todo o Judá e Benjamim. Então convocou todos os de vinte anos para cima e constatou que havia trezentos mil homens prontos para o serviço militar, capazes de empunhar a lança e o escudo.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 6, 'Também contratou em Israel cem mil homens de combate pelo valor de três toneladas e meia de prata.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 7, 'Entretanto, um homem de Deus foi até ele e lhe disse: "Ó, rei, essas tropas de Israel não devem marchar com você, pois o Senhor não está com Israel; não está com ninguém do povo de Efraim.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 8, 'Mesmo que vá e combata corajosamente, Deus o derrotará diante do inimigo, pois tem poder para dar a vitória e a derrota".', 3, CURRENT_TIMESTAMP, false),
(14, 25, 9, 'Amazias perguntou ao homem de Deus: "Mas, e as três toneladas e meia de prata que paguei a estas tropas israelitas? " Ele respondeu: "O Senhor pode dar-lhe muito mais que isso".', 3, CURRENT_TIMESTAMP, false),
(14, 25, 10, 'Amazias, mandou então de volta os soldados de Efraim. Eles ficaram furiosos com Judá e foram embora indignados.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 11, 'Amazias encheu-se de coragem e conduziu o seu exército até o vale do Sal, onde matou dez mil homens de Seir.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 12, 'Também capturou outros dez mil, que levou para o alto de um penhasco e os atirou de lá, e todos eles se espatifaram.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 13, 'Enquanto isso, as tropas que Amazias havia mandado de volta não lhes permitindo participar da guerra, atacaram cidades de Judá, desde Samaria até Bete-Horom. Mataram três mil pessoas e levaram grande quantidade de despojos.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 14, 'Amazias voltou da matança dos edomitas trazendo os deuses do povo de Seir, os quais estabeleceu como seus próprios deuses, inclinou-se diante deles e lhes queimou incenso.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 15, 'Então a ira do Senhor acendeu-se contra Amazias, e ele lhe enviou um profeta, que disse ao rei: "Por que você consulta os deuses desse povo, os quais nem o povo deles puderam salvar de suas mãos? "', 3, CURRENT_TIMESTAMP, false),
(14, 25, 16, 'Enquanto ele ainda falava, o rei o interrompeu: "Por acaso nós o nomeamos conselheiro do rei? Pare! Por que você quer ser morto? " O profeta parou, mas disse: "Sei que Deus decidiu destruí-lo, porque você fez tudo isso e não deu atenção ao meu conselho".', 3, CURRENT_TIMESTAMP, false),
(14, 25, 17, 'Depois de consultar os seus conselheiros, Amazias, rei de Judá, enviou mensageiros a Jeoás, filho de Jeoacaz e neto de Jeú, rei de Israel, com este desafio: "Venha me enfrentar".', 3, CURRENT_TIMESTAMP, false),
(14, 25, 18, 'Contudo, Jeoás, respondeu a Amazias: "O espinheiro do Líbano enviou uma mensagem ao cedro do Líbano: ‘Dê sua filha em casamento a meu filho’. Mas um animal selvagem do Líbano veio e pisoteou o espinheiro.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 19, 'Você diz a si mesmo que derrotou Edom, e agora está arrogante e orgulhoso. Mas fique em casa! Por que provocar uma desgraça que levará você e também Judá à ruína? "', 3, CURRENT_TIMESTAMP, false),
(14, 25, 20, 'Amazias, porém, não quis ouvi-lo, pois Deus mesmo queria entregar Amazias e seu povo a Jeoás, pois pediram conselhos aos deuses de Edom.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 21, 'Então Jeoás, rei de Israel, o atacou. Ele e Amazias, rei de Judá, enfrentaram-se em Bete-Semes, em Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 22, 'Judá foi derrotado por Israel, e seus soldados fugiram para as suas casas.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 23, 'Jeoás capturou Amazias, filho de Joás e neto de Acazias, em Bete-Semes. Então Jeoás levou-o para Jerusalém e derrubou cento e oitenta metros do muro da cidade, desde a porta de Efraim até a porta da Esquina.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 24, 'Ele se apoderou de todo o ouro, de toda a prata e de todos os utensílios encontrados no templo de Deus, que haviam estado sob a guarda de Obede-Edom, e ainda dos tesouros do palácio real. Também fez reféns e, então, voltou para Samaria.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 25, 'Amazias, filho de Joás, rei de Judá, viveu ainda mais quinze anos depois da morte de Jeoás, filho de Jeoacaz, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 26, 'Os demais acontecimentos do reinado de Amazias, do início ao fim, estão escritos nos registros históricos dos reis de Judá e de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 27, 'A partir do momento em que Amazias deixou de seguir o Senhor, conspiraram contra ele em Jerusalém, e ele fugiu para Láquis, mas o perseguiram até lá e o mataram.', 3, CURRENT_TIMESTAMP, false),
(14, 25, 28, 'Ele foi trazido de volta a cavalo, e sepultado junto aos seus antepassados na cidade de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 1, 'Então todo o povo de Judá proclamou rei a Uzias, de dezesseis anos de idade, no lugar de seu pai, Amazias.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 2, 'Foi ele quem reconquistou e reconstruiu a cidade de Elate para Judá, depois que Amazias descansou com os seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 3, 'Uzias tinha dezesseis anos de idade quando se tornou rei, e reinou cinqüenta e dois anos em Jerusalém. Sua mãe era de Jerusalém e chamava-se Jecolias.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 4, 'Ele fez o que o Senhor aprova, tal como o seu pai Amazias;', 3, CURRENT_TIMESTAMP, false),
(14, 26, 5, 'e buscou a Deus durante a vida de Zacarias, que o instruiu no temor de Deus. Enquanto buscou o Senhor, Deus o fez prosperar.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 6, 'Ele saiu à guerra contra os filisteus e derrubou os muros de Gate, de Jabne e de Asdode. Depois reconstruiu cidades próximo a Asdode e em outros lugares do território filisteu.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 7, 'Deus o ajudou contra os filisteus, contra os árabes que viviam em Gur-Baal e contra os meunitas.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 8, 'Os amonitas pagavam tributo a Uzias, e sua fama estendeu-se até a fronteira do Egito, pois havia se tornado muito poderoso.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 9, 'Uzias construiu torres fortificadas em Jerusalém, na porta da Esquina, na porta do Vale e no canto do muro.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 10, 'Também construiu torres no deserto e cavou muitas cisternas, pois ele possuía muitos rebanhos na Sefelá e na planície. Ele mantinha trabalhadores em seus campos e em suas vinhas, nas colinas e nas terras férteis, pois gostava da agricultura.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 11, 'Uzias possuía um exército bem preparado, organizado em divisões de acordo com o número dos soldados convocados pelo secretário Jeiel e pelo oficial Maaséias, sob o comando de Hananias, um dos oficiais do rei.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 12, 'O total de chefes de família no comando dos homens de combate era de dois mil e seiscentos.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 13, 'Sob o comando deles estava um exército de trezentos e sete mil e quinhentos homens treinados para a guerra, uma força poderosíssima que apoiava o rei contra os seus inimigos.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 14, 'Uzias providenciou escudos, lanças, capacetes, couraças, arcos e atiradeiras de pedras para todo o exército.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 15, 'Em Jerusalém, construiu máquinas projetadas por peritos para serem usadas nas torres e nas defesas das esquinas, máquinas que atiravam flechas e grandes pedras. Ele foi extraordinariamente ajudado, e assim tornou-se muito poderoso e a sua fama espalhou-se para longe.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 16, 'Entretanto, depois que Uzias se tornou poderoso, o seu orgulho provocou a sua queda. Ele foi infiel ao Senhor, ao seu Deus, e entrou no templo do Senhor para queimar incenso no altar de incenso.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 17, 'O sumo sacerdote Azarias, e outros oitenta corajosos sacerdotes do Senhor, foram atrás dele.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 18, 'Eles o enfrentaram e disseram: "Não é certo que você, Uzias, queime incenso ao Senhor. Isto é tarefa dos sacerdotes, os descendentes de Arão consagrados para queimar incenso. Saia do santuário, pois você foi infiel e não será honrado por Deus, o Senhor".', 3, CURRENT_TIMESTAMP, false),
(14, 26, 19, 'Uzias, que estava com um incensário na mão, pronto para queimar o incenso, irritou-se e indignou-se contra os sacerdotes; e na mesma hora, na presença deles, diante do altar de incenso no templo do Senhor, surgiu lepra em sua testa.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 20, 'Quando o sumo sacerdote Azarias e todos os outros sacerdotes viram a lepra, expulsaram-no imediatamente do templo. Na verdade, ele mesmo ficou ansioso para sair, pois o Senhor o havia ferido.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 21, 'O rei Uzias sofreu de lepra até o dia em que morreu. Durante todo esse tempo morou numa casa separada, leproso e excluído do templo do Senhor. Seu filho Jotão tomava conta do palácio e governava o povo.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 22, 'Os demais acontecimentos do reinado de Uzias, do início ao fim, foram registrados pelo profeta Isaías, filho de Amoz.', 3, CURRENT_TIMESTAMP, false),
(14, 26, 23, 'Uzias descansou com os seus antepassados e foi sepultado perto deles, num cemitério que pertencia aos reis, pois o povo dizia: "Ele tinha lepra". Seu filho Jotão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 1, 'Jotão tinha vinte e cinco anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém. O nome da sua mãe era Jerusa, filha de Zadoque.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 2, 'Ele fez o que o Senhor aprova, tal como seu pai, mas, ao contrário deste, não entrou no templo do Senhor. O povo, contudo, prosseguiu em suas práticas corruptas.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 3, 'Jotão reconstruiu a porta superior do templo do Senhor e fez amplos trabalhos no muro, na colina de Ofel.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 4, 'Construiu cidades nos montes de Judá, bem como fortes e torres nas matas.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 5, 'Jotão guerreou contra o rei dos amonitas e o derrotou. Então os amonitas pagaram-lhe três toneladas e meia de prata, dez mil barris de trigo e dez mil de cevada durante três anos seguidos.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 6, 'Jotão tornou-se cada vez mais poderoso, pois andava firmemente segundo a vontade do Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 7, 'Os demais acontecimentos do reinado de Jotão, inclusive todas as suas guerras e as suas outras realizações, estão escritos nos registros históricos dos reis de Israel e de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 8, 'Tinha vinte e cinco anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 27, 9, 'Jotão descansou com os seus antepassados e foi sepultado na cidade de Davi. Seu filho Acaz foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 1, 'Acaz tinha vinte anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém. Ao contrário de Davi, seu predecessor, não fez o que o Senhor aprova.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 2, 'Ele andou nos caminhos dos reis de Israel e fez ídolos de metal para adorar os baalins.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 3, 'Queimou sacrifícios no vale de Ben-Hinom e chegou até a queimar seus filhos em sacrifício, imitando os costumes detestáveis das nações que o Senhor havia expulsado de diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 4, 'Também ofereceu sacrifícios e queimou incenso nos altares idólatras, no alto das colinas e debaixo de toda árvore frondosa.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 5, 'Por isso o Senhor, o seu Deus, entregou-o nas mãos do rei da Síria. Os arameus o derrotaram, fizeram muitos prisioneiros entre o seu povo e os levaram para Damasco. Israel também lhe infligiu grande derrota.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 6, 'Num único dia, Peca, filho de Remalias, matou cento e vinte mil soldados corajosos de Judá; pois Judá havia abandonado o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 7, 'Zicri, guerreiro efraimita, matou Maaséias, filho do rei, Azricão, oficial encarregado do palácio, e Elcana, o braço direito do rei.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 8, 'Os israelitas levaram para Samaria duzentos mil prisioneiros dentre os seus parentes, incluindo mulheres, meninos e meninas. Também levaram muitos despojos.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 9, 'Mas um profeta do Senhor, chamado Odede, estava em Samaria e saiu ao encontro do exército. Ele lhes disse: "Estando irado contra Judá, o Senhor, o Deus dos seus antepassados, entregou-os nas mãos de vocês. Mas a fúria com que vocês os mataram chegou aos céus.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 10, 'E agora ainda pretendem escravizar homens e mulheres de Judá e de Jerusalém. Vocês também não são culpados de pecados contra o Senhor, o seu Deus?', 3, CURRENT_TIMESTAMP, false),
(14, 28, 11, 'Agora, ouçam-me! Mandem de volta seus irmãos que vocês fizeram prisioneiros, pois o fogo da ira do Senhor está sobre vocês".', 3, CURRENT_TIMESTAMP, false),
(14, 28, 12, 'Então Azarias, filho de Joanã, Berequias, filho de Mesilemote, Jeizquias, filho de Salum, e Amasa, filho de Hadlai, que eram alguns dos chefes de Efraim, questionaram os que estavam chegando da guerra, dizendo:', 3, CURRENT_TIMESTAMP, false),
(14, 28, 13, '"Não tragam os prisioneiros para cá. Caso contrário seremos culpados diante do Senhor. Vocês querem aumentar ainda mais o nosso pecado e a nossa culpa? A nossa culpa já é grande, e o fogo da sua ira está sobre Israel".', 3, CURRENT_TIMESTAMP, false),
(14, 28, 14, 'Então os soldados libertaram os prisioneiros e colocaram os despojos na presença dos líderes e de toda a assembléia.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 15, 'Os homens citados nominalmente apanharam os prisioneiros e com as roupas e as sandálias dos despojos vestiram todos os que estavam nus. Deram-lhes comida, bebida, e bálsamo medicinal. Puseram sobre jumentos todos aqueles que estavam fracos. Assim os levaram de volta a seus patrícios residentes em Jericó, a cidade das Palmeiras, e voltaram para Samaria.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 16, 'Nessa época, o rei Acaz enviou mensageiros ao rei da Assíria para pedir-lhe ajuda.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 17, 'Os edomitas tinham voltado a atacar Judá fazendo prisioneiros,', 3, CURRENT_TIMESTAMP, false),
(14, 28, 18, 'e os filisteus atacaram cidades na Sefelá e no sul de Judá. Conquistaram e ocuparam Bete-Semes, Aijalom e Gederote, bem como Socó, Timna e Ginzo, com os seus povoados ao redor.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 19, 'O Senhor humilhou Judá por causa de Acaz, rei de Israel, por sua conduta desregrada em Judá, muito infiel ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 20, 'Quando chegou Tiglate-Pileser, rei da Assíria, causou-lhe problemas em vez de ajudá-lo.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 21, 'Acaz apanhou algumas coisas do templo do Senhor, do palácio real e dos líderes e ofereceu-as ao rei da Assíria, mas isso não adiantou.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 22, 'Mesmo nessa época em que passou por tantas dificuldades, o rei Acaz tornou-se ainda mais infiel ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 23, 'Ele ofereceu sacrifícios aos deuses de Damasco que o haviam derrotado, pois pensava: "Já que os deuses da Síria os têm ajudado, oferecerei sacrifícios a eles para que me ajudem também". Mas eles foram a causa da sua ruína e da ruína de todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 24, 'Acaz juntou os utensílios do templo de Deus e os retirou de lá. Trancou as portas do templo do Senhor e ergueu altares em todas as esquinas de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 25, 'Em todas as cidades de Judá construiu altares idólatras para queimar sacrifícios a outros deuses e provocou a ira do Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 26, 'Os demais acontecimentos de seu reinado e todos os seus atos, do início ao fim, estão escritos nos registros históricos dos reis de Judá e de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 28, 27, 'Acaz descansou com os seus antepassados e foi sepultado na cidade de Jerusalém, mas não nos túmulos dos reis de Israel. Seu filho Ezequias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 1, 'Ezequias tinha vinte e cinco anos de idade quando começou a reinar, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Abia, filha de Zacarias.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 2, 'Ele fez o que o Senhor aprova, tal como tinha feito Davi, seu predecessor.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 3, 'No primeiro mês do primeiro ano de seu reinado, ele reabriu as portas do templo do Senhor e as consertou.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 4, 'Convocou os sacerdotes e os levitas, reuniu-os na praça que fica no lado leste', 3, CURRENT_TIMESTAMP, false),
(14, 29, 5, 'e disse: "Escutem-me, levitas! Consagrem-se agora e consagrem o templo do Senhor, o Deus dos seus antepassados. Retirem tudo o que é impuro do santuário.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 6, 'Nossos pais foram infiéis; fizeram o que o Senhor, o nosso Deus, reprova e o abandonaram. Desviaram o rosto do local da habitação do Senhor e deram-lhe as costas.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 7, 'Também fecharam as portas do pórtico e apagaram as lâmpadas. Não queimaram incenso nem apresentaram holocausto no santuário para o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 8, 'Por isso, a ira do Senhor caiu sobre Judá e sobre Jerusalém; e ele fez deles objeto de espanto, horror e zombaria, conforme vocês podem ver com os seus próprios olhos.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 9, 'Por isso os nossos pais caíram à espada e os nossos filhos, as nossas filhas e as nossas mulheres foram levadas como prisioneiras.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 10, 'Pretendo, pois, agora fazer uma aliança com o Senhor, o Deus de Israel, para que o fogo da sua ira se afaste de nós.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 11, 'Meus filhos, não sejam negligentes agora, pois o Senhor os escolheu para estarem diante dele e o servirem, para ministrarem perante ele e queimarem incenso".', 3, CURRENT_TIMESTAMP, false),
(14, 29, 12, 'Então estes levitas puseram-se a trabalhar: dentre os descendentes de Coate: Maate, filho de Amasai, e Joel, filho de Azarias; dentre os descendentes de Merari: Quis, filho de Abdi, e Azarias, filho de Jealelel; dentre os descendentes de Gérson: Joá, filho de Zima, e Éden, filho de Joá;', 3, CURRENT_TIMESTAMP, false),
(14, 29, 13, 'dentre os descendentes de Elisafã: Sinri e Jeuel; dentre os descendentes de Asafe: Zacarias e Matanias;', 3, CURRENT_TIMESTAMP, false),
(14, 29, 14, 'dentre os descendentes de Hemã: Jeuel e Simei; dentre os descendentes de Jedutum: Semaías e Uziel.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 15, 'Tendo reunido e consagrado os seus parentes, os levitas foram purificar o templo do Senhor, conforme o rei havia ordenado em obediência à palavra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 16, 'Os sacerdotes entraram no santuário do Senhor para purificá-lo e trouxeram para o pátio do templo do Senhor todas as coisas impuras que lá havia, e os levitas as levaram para o vale de Cedrom.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 17, 'Começaram a consagração no dia primeiro do primeiro mês, e no oitavo dia chegaram ao pórtico do Senhor. Durante mais oito dias consagraram o templo do Senhor propriamente dito, terminando tudo no dia dezesseis.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 18, 'Depois foram falar com o rei Ezequias e lhe relataram: "Purificamos todo o templo do Senhor, o altar dos holocaustos e a mesa do pão consagrado, ambos com todos seus utensílios.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 19, 'Preparamos e consagramos todos os utensílios que o rei Acaz, em sua infidelidade, retirou durante o seu reinado. Eles estão em frente do altar do Senhor".', 3, CURRENT_TIMESTAMP, false),
(14, 29, 20, 'Cedo, na manhã seguinte, o rei Ezequias reuniu os líderes da cidade e, juntos, subiram ao templo do Senhor,', 3, CURRENT_TIMESTAMP, false),
(14, 29, 21, 'levando sete novilhos, sete carneiros, sete cordeiros e sete bodes como oferta pelo pecado, em favor da realeza, do santuário e de Judá. O rei ordenou que os sacerdotes, descendentes de Arão, sacrificassem os animais no altar do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 22, 'Então os sacerdotes abateram os novilhos e aspergiram o sangue sobre o altar; em seguida fizeram o mesmo com os carneiros e com os cordeiros.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 23, 'Depois, os bodes para a oferta pelo pecado foram levados para diante do rei e da assembléia, que impuseram as mãos sobre eles.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 24, 'Os sacerdotes abateram os bodes e apresentaram o sangue sobre o altar como oferta pelo pecado, para fazer propiciação por todo o Israel, pois era em favor de todo o Israel que o rei havia ordenado o holocausto e a oferta pelo pecado.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 25, 'O rei posicionou os levitas no templo do Senhor, com címbalos, liras e harpas, segundo a prescrição de Davi, de Gade, vidente do rei, e do profeta Natã; isso foi ordenado pelo Senhor, por meio de seus profetas.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 26, 'Assim os levitas ficaram em pé, preparados com os instrumentos de Davi, e os sacerdotes com as cornetas.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 27, 'Então Ezequias ordenou que sacrificassem o holocausto sobre o altar. Iniciado o sacrifício, começou também o canto ao Senhor, ao som das cornetas e dos instrumentos de Davi, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 28, 'Toda a assembléia prostrou-se em adoração, enquanto os músicos cantavam e os corneteiros tocavam, até que terminou o holocausto.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 29, 'Então o rei e todos os presentes ajoelharam-se e adoraram.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 30, 'O rei Ezequias e seus oficiais ordenaram aos levitas que louvassem o Senhor com as palavras de Davi e do vidente Asafe. Eles louvaram com alegria, depois inclinaram suas cabeças e adoraram.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 31, 'Disse então Ezequias: "Agora que vocês se dedicaram ao Senhor, tragam sacrifícios e ofertas de gratidão ao templo do Senhor". Assim, a comunidade levou sacrifícios e ofertas de gratidão, e alguns, espontaneamente, levaram também holocaustos.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 32, 'Esses holocaustos que a assembléia ofertou ao Senhor foram setenta bois, cem carneiros e duzentos cordeiros.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 33, 'Os animais consagrados como sacrifícios chegaram a seiscentos bois e três mil ovelhas e bodes.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 34, 'Como os sacerdotes eram muito poucos para tirar a pele de todos os holocaustos, os seus parentes, os levitas, os ajudaram até o fim da tarefa e até que outros sacerdotes se consagrassem, pois os levitas demoraram menos para se consagrarem do que os sacerdotes.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 35, 'Houve holocaustos em grande quantidade, oferecidos com a gordura das ofertas de comunhão e com as ofertas derramadas que acompanhavam esses holocaustos. Assim foi restabelecido o culto no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 29, 36, 'Ezequias e todo o povo regozijavam-se com o que Deus havia feito por seu povo, e tudo em tão pouco tempo.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 1, 'Ezequias enviou uma mensagem a todo o Israel e Judá e também escreveu cartas a Efraim e a Manassés, convidando-os para ir ao templo do Senhor em Jerusalém e celebrar a Páscoa do Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 2, 'O rei, seus oficiais e toda a comunidade de Jerusalém decidiram celebrar a Páscoa no segundo mês.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 3, 'Não tinha sido possível celebrá-la na data prescrita, pois não havia número suficiente de sacerdotes consagrados, e o povo não estava reunido em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 4, 'A idéia pareceu boa tanto ao rei quanto a toda a assembléia.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 5, 'Então decidiram fazer uma proclamação em todo o Israel, desde Berseba até Dã, convocando o povo a Jerusalém para celebrar a Páscoa do Senhor, o Deus de Israel. Pois muitos não a celebravam segundo o que estava escrito.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 6, 'Por ordem do rei, mensageiros percorreram Israel e Judá com cartas assinadas pelo rei e pelos seus oficiais, com a seguinte mensagem: "Israelitas, voltem para o Senhor, o Deus de Abraão, de Isaque e de Israel, para que ele se volte para vocês que restaram e escaparam das mãos dos reis da Assíria.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 7, 'Não sejam como seus pais e seus irmãos, que foram infiéis ao Senhor, o Deus dos seus antepassados, de maneira que ele os deixou em ruínas, conforme vocês vêem.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 8, 'Portanto não sejam obstinados como seus antepassados; submetam-se ao Senhor. Venham ao santuário que ele consagrou para sempre. Sirvam ao Senhor, ao seu Deus, para que o fogo da sua ira se desvie de vocês.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 9, 'Se vocês voltarem para o Senhor, os que capturaram os seus irmãos e os seus filhos terão misericórdia deles, e eles voltarão a esta terra, pois o Senhor, o seu Deus, é bondoso e compassivo. Ele não os rejeitará, se vocês se voltarem para ele".', 3, CURRENT_TIMESTAMP, false),
(14, 30, 10, 'Os mensageiros foram de cidade em cidade, em Efraim e em Manassés, e até em Zebulom, mas o povo zombou deles e os expôs ao ridículo.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 11, 'No entanto, alguns homens de Aser, de Manassés e de Zebulom humilharam-se e foram para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 12, 'Já em Judá a mão de Deus esteve sobre o povo dando-lhes unidade de pensamento para executarem o que o rei e os seus oficiais haviam ordenado, conforme a palavra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 13, 'Uma imensa multidão reuniu-se em Jerusalém no segundo mês, para celebrar a festa dos pães sem fermento.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 14, 'Eles retiraram os altares que havia em Jerusalém e se desfizeram de todos os altares de incenso, atirando-os no vale de Cedrom.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 15, 'Abateram o cordeiro da Páscoa no dia catorze do segundo mês. Os sacerdotes e os levitas, envergonhados, consagraram-se e levaram holocaustos ao templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 16, 'E assumiram seus postos, conforme prescrito na Lei de Moisés, homem de Deus. Os sacerdotes aspergiram o sangue que os levitas lhes entregaram.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 17, 'Visto que muitos na multidão não haviam se consagrado, os levitas tiveram que matar cordeiros da Páscoa para todos os que não estavam cerimonialmente puros e que por isso não podiam consagrar os seus cordeiros ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 18, 'Embora muitos dos que vieram de Efraim, de Manassés, de Issacar e de Zebulom não se tivessem purificado, assim mesmo comeram a Páscoa, contrariando o que estava escrito. Mas Ezequias orou por eles, dizendo: "Queira o Senhor, que é bondoso, perdoar todo', 3, CURRENT_TIMESTAMP, false),
(14, 30, 19, 'aquele que inclina o seu coração para buscar a Deus, o Senhor, o Deus dos seus antepassados, mesmo que não esteja puro de acordo com as regras do santuário".', 3, CURRENT_TIMESTAMP, false),
(14, 30, 20, 'E o Senhor ouviu a oração de Ezequias e não castigou o povo.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 21, 'Os israelitas presentes em Jerusalém celebraram com muita alegria a festa dos pães sem fermento durante sete dias. Diariamente os levitas e os sacerdotes cantavam louvores, ao som dos instrumentos ressonantes do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 22, 'Ezequias dirigiu palavras animadoras a todos os levitas, que mostraram boa disposição para com o serviço do Senhor. Durante os sete dias eles comeram suas porções das ofertas, apresentaram sacrifícios de comunhão e louvaram o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 23, 'E toda a assembléia decidiu prolongar a festa por mais sete dias, e a celebraram com alegria.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 24, 'Ezequias, rei de Judá, forneceu mil novilhos e sete mil ovelhas e bodes para a assembléia, e os líderes, mil novilhos e dez mil ovelhas e bodes. Muitos sacerdotes se consagraram,', 3, CURRENT_TIMESTAMP, false),
(14, 30, 25, 'e toda a assembléia de Judá se regozijava, juntamente com os sacerdotes, com os levitas e com todos os que se haviam reunido, vindos de Israel, inclusive os estrangeiros que viviam em Israel e em Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 26, 'Houve grande alegria em Jerusalém, pois desde os dias de Salomão, filho de Davi, rei de Israel, não havia acontecido algo assim na cidade.', 3, CURRENT_TIMESTAMP, false),
(14, 30, 27, 'Os sacerdotes e os levitas levantaram-se para abençoar o povo, e Deus os ouviu; a oração deles chegou aos céus, sua santa habitação.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 1, 'Quando a festa acabou, os israelitas saíram pelas cidades de Judá e despedaçaram as pedras sagradas e derrubaram os postes sagrados. Eles destruíram os altares idólatras em todo o Judá e Benjamim, e em Efraim e Manassés. Depois de destruírem tudo, voltaram para as suas cidades, cada um para a sua propriedade.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 2, 'Ezequias designou os sacerdotes e os levitas por turnos, cada um de acordo com os seus deveres, para apresentarem holocaustos e sacrifícios de comunhão, ministrarem, darem graças e cantarem louvores junto às portas da habitação do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 3, 'O rei contribuía com seus próprios bens para os holocaustos da manhã e da tarde e para os holocaustos dos sábados, das Luas Novas e das festas fixas, conforme o que está escrito na Lei do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 4, 'Ele ordenou ao povo de Jerusalém que desse aos sacerdotes e aos levitas a porção que lhes era devida a fim de que pudessem dedicar-se à Lei do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 5, 'Assim que se divulgou essa ordem, os israelitas deram com generosidade o melhor do trigo, do vinho, do óleo, do mel e de tudo o que os campos produziam. Trouxeram o dízimo de tudo. Era uma grande quantidade.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 6, 'Os habitantes de Israel e de Judá que viviam nas cidades de Judá também levaram o dízimo de todos os seus rebanhos e das coisas sagradas dedicadas ao Senhor, o seu Deus, ajuntando-os em muitas pilhas.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 7, 'Começaram a fazer isso no terceiro mês e terminaram no sétimo.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 8, 'Quando Ezequias e os seus oficiais chegaram e viram as pilhas de ofertas, louvaram o Senhor e abençoaram Israel, o seu povo.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 9, 'Ezequias perguntou aos sacerdotes e aos levitas sobre essas ofertas;', 3, CURRENT_TIMESTAMP, false),
(14, 31, 10, 'o sumo sacerdote Azarias, da família de Zadoque, respondeu: "Desde que o povo começou a trazer suas contribuições ao templo do Senhor, temos tido o suficiente para comer e ainda tem sobrado muito, pois o Senhor tem abençoado o seu povo, e esta é a grande quantidade que sobra".', 3, CURRENT_TIMESTAMP, false),
(14, 31, 11, 'Ezequias ordenou que preparassem despensas no templo do Senhor, e assim foi feito.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 12, 'Então recolheram fielmente as contribuições, os dízimos e os presentes dedicados. O levita Conanias foi encarregado dessas coisas, e seu irmão Simei era o seu auxiliar.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 13, 'Jeiel, Azazias, Naate, Asael, Jeremote, Jozabade, Eliel, Ismaquias, Maate e Benaia eram supervisores, subordinados a Conanias e ao seu irmão Simei, por nomeação do rei Ezequias e de Azarias, o oficial encarregado do templo de Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 14, 'Coré, filho do levita Imna, guarda da porta leste, foi encarregado das ofertas voluntárias feitas a Deus, distribuindo as contribuições dedicadas ao Senhor e as ofertas consagradas.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 15, 'Sob o comando dele estavam Éden, Miniamim, Jesua, Semaías, Amarias e Secanias, que, nas cidades dos sacerdotes, com toda a fidelidade distribuíam ofertas aos seus colegas sacerdotes de acordo com seus turnos, tanto aos idosos quanto aos jovens.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 16, 'Eles as distribuíram aos homens e aos meninos de três anos para cima, cujos nomes estavam nos registros genealógicos, também a todos os que entravam no templo do Senhor para realizar suas várias tarefas diárias, de acordo com suas responsabilidades e seus turnos.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 17, 'Os registros genealógicos dos sacerdotes eram feitos segundo suas famílias, o dos levitas de vinte anos para cima, de acordo com suas responsabilidades e seus turnos.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 18, 'O registro incluía todos os filhos pequenos, as mulheres, e os filhos e filhas de todo o grupo, pois os sacerdotes e os levitas haviam sido fiéis em se consagrarem.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 19, 'Entre os sacerdotes, descendentes de Arão, que viviam nas terras de pastagem ao redor de suas cidades, foram nomeados alguns deles, de cidade em cidade, para distribuírem as ofertas a todos os sacerdotes e a todos os que estavam registrados nas genealogias dos levitas.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 20, 'Foi isso que Ezequias fez em todo o reino de Judá. Ele fez o que era bom e certo, e em tudo foi fiel diante do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 31, 21, 'Em tudo o que ele empreendeu no serviço do templo de Deus e na obediência à lei e aos mandamentos, ele buscou o seu Deus e trabalhou de todo o coração; e por isso prosperou.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 1, 'Depois de tudo o que Ezequias fez com tanta fidelidade, Senaqueribe, rei da Assíria, invadiu Judá. Ele sitiou as cidades fortificadas para conquistá-las.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 2, 'Quando Ezequias viu que Senaqueribe pretendia guerrear contra Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(14, 32, 3, 'consultou os seus oficiais e os comandantes do exército sobre a idéia de mandar fechar a passagem de água das fontes do lado de fora da cidade; e eles concordaram.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 4, 'Assim, ajuntaram-se muitos homens, e fecharam todas as fontes e o riacho que atravessava a região. Eles diziam: "Por que deixar que os reis da Assíria venham e encontrem toda essa água? "', 3, CURRENT_TIMESTAMP, false),
(14, 32, 5, 'Depois, com grande empenho consertou todos os trechos quebrados do muro e construiu torres sobre ele. Construiu outro muro do lado de fora do primeiro e reforçou os muros de arrimo da cidade de Davi; e mandou fazer também muitas lanças e muitos escudos.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 6, 'Nomeou sobre o povo oficiais militares e os reuniu na praça, junto à porta da cidade, animando-os com estas palavras:', 3, CURRENT_TIMESTAMP, false),
(14, 32, 7, '"Sejam fortes e corajosos. Não tenham medo nem se desanimem por causa do rei da Assíria e do enorme exército que está com ele, pois conosco está um poder maior do que o que está com ele.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 8, 'Com ele está somente o poder humano, mas conosco está o Senhor, o nosso Deus, para nos ajudar e para travar as nossas batalhas". E o povo ganhou confiança com o que disse Ezequias, rei de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 9, 'Mais tarde, quando Senaqueribe, rei da Assíria, e todas as suas forças estavam sitiando Láquis, mandou oficiais a Jerusalém com a seguinte mensagem a Ezequias e a todo o povo de Judá que morava lá:', 3, CURRENT_TIMESTAMP, false),
(14, 32, 10, '"Assim diz Senaqueribe, rei da Assíria: Em que vocês baseiam a sua confiança, para permanecerem cercados em Jerusalém?', 3, CURRENT_TIMESTAMP, false),
(14, 32, 11, 'Quando Ezequias diz: ‘O Senhor, o nosso Deus, nos salvará das mãos do rei da Assíria’, ele os está enganando, para deixá-los morrer de fome e de sede.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 12, 'Mas não foi o próprio Ezequias que retirou os altares desse deus, dizendo a Judá e a Jerusalém: ‘Vocês devem adorar diante de um só altar e sobre ele queimar incenso’? "', 3, CURRENT_TIMESTAMP, false),
(14, 32, 13, '"Vocês não sabem o que eu e os meus antepassados fizemos a todos os povos das outras terras? Acaso alguma vez os deuses daquelas nações conseguiram livrar das minhas mãos a terra deles?', 3, CURRENT_TIMESTAMP, false),
(14, 32, 14, 'De todos os deuses das nações que os meus antepassados destruíram, qual deles conseguiu salvar o seu povo de mim? Como então o deus de vocês poderá livrá-los das minhas mãos?', 3, CURRENT_TIMESTAMP, false),
(14, 32, 15, 'Portanto, não deixem Ezequias enganá-los ou iludi-los dessa maneira. Não acreditem nele, pois nenhum deus de qualquer nação ou reino jamais conseguiu livrar o seu povo das minhas mãos ou das mãos de meus antepassados. Muito menos o deus de vocês conseguirá livrá-los das minhas mãos! "', 3, CURRENT_TIMESTAMP, false),
(14, 32, 16, 'Os oficiais de Senaqueribe desafiaram ainda mais a Deus, ao Senhor, e ao seu servo Ezequias.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 17, 'Senaqueribe também escreveu cartas insultando o Senhor, o Deus de Israel, e o desafiando: "Assim como os deuses dos povos das outras terras não livraram o povo deles das minhas mãos, também o deus de Ezequias não livrará o seu povo das minhas mãos".', 3, CURRENT_TIMESTAMP, false),
(14, 32, 18, 'Então os oficiais gritaram na língua dos judeus ao povo de Jerusalém que estava sobre o muro, para assustá-lo e amedrontá-lo, com o intuito de conquistarem a cidade.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 19, 'Referiram-se ao Deus de Jerusalém como falavam dos deuses dos outros povos da terra, que não passam de obra das mãos dos homens.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 20, 'Por tudo isso o rei Ezequias e o profeta Isaías, filho de Amoz, clamaram em oração aos céus.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 21, 'E o Senhor enviou um anjo, que matou todos os homens de combate e todos os líderes e oficiais no acampamento do rei assírio, de forma que este se retirou envergonhado para a sua terra. E certo dia, ao adentrar o templo do seu deus, alguns dos seus filhos o mataram à espada.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 22, 'Assim o Senhor salvou Ezequias e o povo de Jerusalém das mãos de Senaqueribe, rei da Assíria, e das mãos de todos os outros; e cuidou deles em todas as fronteiras.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 23, 'Muitos levaram a Jerusalém ofertas para o Senhor e presentes valiosos para Ezequias, rei de Judá. Daquela ocasião em diante ele foi muito respeitado por todas as nações.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 24, 'Naquele tempo Ezequias ficou doente, e quase morreu. Ele orou ao Senhor, que lhe respondeu dando-lhe um sinal miraculoso.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 25, 'Mas Ezequias tornou-se orgulhoso, e não correspondeu à bondade com que foi tratado; por isso a ira do Senhor veio sobre ele, sobre Judá e sobre Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 26, 'Então Ezequias humilhou-se reconhecendo o seu orgulho, como também o povo de Jerusalém; por isso a ira do Senhor não veio sobre eles durante o reinado de Ezequias.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 27, 'Possuía Ezequias muitíssimas riquezas e glória; construiu depósitos para guardar prata, ouro, pedras preciosas, especiarias, escudos e todo tipo de objetos de valor.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 28, 'Também construiu armazéns para estocar trigo, vinho e azeite; fez ainda estábulos para os seus diversos rebanhos e para as ovelhas.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 29, 'Construiu cidades e adquiriu muitos rebanhos, pois Deus lhe dera muitas riquezas.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 30, 'Foi Ezequias que bloqueou o manancial superior da fonte de Giom e, canalizou a água para a parte oeste da cidade de Davi. Ele foi bem sucedido em tudo o que se propôs a fazer.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 31, 'Mas, quando os governantes da Babilônia enviaram uma delegação para perguntar-lhe acerca do sinal miraculoso que havia ocorrido no país, Deus o deixou, para prová-lo e para saber tudo o que havia em seu coração.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 32, 'Os demais acontecimentos do reinado de Ezequias e os seus atos piedosos, estão escritos na visão do profeta Isaías, filho de Amoz, no livro dos reis de Judá e de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 32, 33, 'Ezequias descansou com os seus antepassados e foi sepultado na colina onde estão os túmulos dos descendentes de Davi. Todo o Judá e o povo de Jerusalém prestaram-lhe homenagens por ocasião da sua morte. E o seu filho Manassés foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 1, 'Manassés tinha doze anos de idade quando começou a reinar, e reinou cinqüenta e cinco anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 2, 'Ele fez o que o Senhor reprova, imitando as práticas detestáveis das nações que o Senhor havia expulsado de diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 3, 'Reconstruiu os altares idólatras que seu pai Ezequias havia demolido; também ergueu altares para os baalins e fez postes sagrados. Inclinou-se diante de todos os exércitos celestes e lhes prestou culto.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 4, 'Construiu altares no templo do Senhor, do qual o Senhor tinha dito: "Meu nome permanecerá para sempre em Jerusalém".', 3, CURRENT_TIMESTAMP, false),
(14, 33, 5, 'Nos dois pátios do templo do Senhor ele construiu altares para todos os exércitos celestes.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 6, 'Chegou a queimar seus filhos em sacrifício, no vale de Ben-Hinom; praticou feitiçaria, adivinhação e magia, e consultou médiuns e espíritas. Fez o que o Senhor reprova, provocando-o à ira.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 7, 'Ele tomou a imagem esculpida que havia feito e a colocou no templo, do qual Deus tinha dito a Davi e a seu filho Salomão: "Neste templo e em Jerusalém, que escolhi dentre todas as tribos de Israel, porei meu nome para sempre.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 8, 'Não farei os pés dos israelitas deixarem novamente a terra que dei aos seus antepassados, se tão-somente tiverem o cuidado de fazer tudo o que lhes ordenei em todas as leis, os decretos e as ordenanças dados por meio de Moisés".', 3, CURRENT_TIMESTAMP, false),
(14, 33, 9, 'Manassés, porém, desencaminhou Judá e o povo de Jerusalém, a ponto de fazerem pior do que as nações que o Senhor havia destruído diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 10, 'O Senhor falou a Manassés e a seu povo, mas não lhe deram atenção.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 11, 'Por isso o Senhor enviou contra eles os comandantes do exército do rei da Assíria, os quais prenderam Manassés, colocaram-lhe um gancho no nariz e algemas de bronze, e o levaram para a Babilônia.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 12, 'Em sua angústia, ele buscou o favor do Senhor, o seu Deus, e humilhou-se muito diante do Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 13, 'Quando ele orou, o Senhor o ouviu e atendeu o seu pedido; de forma que o trouxe de volta a Jerusalém e a seu reino. E assim Manassés reconheceu que o Senhor é Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 14, 'Depois disso ele reconstruiu e aumentou a altura do muro externo da cidade de Davi, a oeste da fonte de Giom, no vale, até a entrada da porta do Peixe, em torno da colina de Ofel. Também pôs comandantes militares em todas as cidades fortificadas de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 15, 'Manassés tirou do templo do Senhor os deuses estrangeiros e a imagem que lá havia colocado, bem como todos os altares idólatras que havia construído na colina do templo e em Jerusalém; e jogou-os fora da cidade.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 16, 'Então restaurou o altar do Senhor e sobre ele ofereceu sacrifícios de comunhão e ofertas de gratidão, ordenando a Judá que servisse o Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 17, 'O povo, contudo, continuou a sacrificar nos altares idólatras, mas somente ao Senhor, ao seu Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 18, 'Os demais acontecimentos do reinado de Manassés, inclusive sua oração a seu Deus e as palavras que os videntes lhe falaram em nome do Senhor, o Deus de Israel, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 19, 'Sua oração e a resposta de Deus, bem como todos os seus pecados e a sua infidelidade, além dos locais onde construiu altares idólatras e ergueu postes sagrados e ídolos, antes de humilhar-se, tudo está escrito nos registros históricos dos videntes.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 20, 'Manassés descansou com os seus antepassados e foi sepultado em sua propriedade. E seu filho Amom foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 21, 'Amom tinha vinte e dois anos de idade quando começou a reinar, e reinou dois anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 22, 'Ele fez o que o Senhor reprova; à semelhança de seu pai, Amom prestou culto e ofereceu sacrifícios a todos os ídolos que Manassés havia feito.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 23, 'Mas, ao contrário de seu pai Manassés, não se humilhou diante do Senhor, antes, aumentou a sua culpa.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 24, 'Os oficiais de Amom conspiraram contra ele e o assassinaram em seu palácio.', 3, CURRENT_TIMESTAMP, false),
(14, 33, 25, 'Mas o povo matou todos os que haviam conspirado contra o rei Amom, e a seu filho Josias proclamou rei em seu lugar.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 1, 'Josias tinha oito anos de idade quando começou a reinar, e reinou trinta e um anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 2, 'Ele fez o que o Senhor aprova e andou nos caminhos de Davi, seu predecessor, sem desviar-se nem para a direita nem para a esquerda.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 3, 'No oitavo ano do seu reinado, sendo ainda bem jovem, ele começou a buscar o Deus de Davi, seu predecessor. No décimo segundo ano, começou a purificar Judá e Jerusalém dos altares idólatras, dos postes sagrados, das imagens esculpidas e dos ídolos de metal.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 4, 'Sob as suas ordens foram derrubados os altares dos baalins; além disso, ele despedaçou os altares de incenso que ficavam acima deles. Também despedaçou e reduziu a pó os postes sagrados, as imagens esculpidas e os ídolos de metal, e os espalhou sobre os túmulos daqueles que lhes haviam oferecido sacrifícios.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 5, 'Depois queimou os ossos dos sacerdotes sobre esses altares, purificando assim Judá e Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 6, 'Nas cidades das tribos de Manassés, de Efraim e de Simeão, e até mesmo de Naftali, e nas ruínas ao redor delas,', 3, CURRENT_TIMESTAMP, false),
(14, 34, 7, 'derrubou os altares e os postes sagrados, esmagou os ídolos, reduzindo-os a pó, e despedaçou todos os altares de incenso espalhados por Israel. Então voltou para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 8, 'No décimo oitavo ano do seu reinado, a fim de purificar o país e o templo, ele enviou Safã, filho de Azalias, e Maaséias, governador da cidade, junto com Joá, filho do arquivista real Joacaz, para restaurarem o templo do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 9, 'Eles foram entregar ao sumo sacerdote Hilquias a prata que havia sido trazida ao templo de Deus e que os porteiros levitas haviam recolhido das ofertas do povo de Manassés e de Efraim, e de todo o remanescente de Israel, e também de todo o povo de Judá e de Benjamim e dos habitantes de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 10, 'Então confiaram a prata aos homens nomeados para supervisionarem a reforma no templo do Senhor, que pagavam os trabalhadores que faziam os reparos no templo.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 11, 'Também deram dessa prata aos carpinteiros e aos construtores para comprarem pedras lavradas, e madeira para as juntas e as vigas dos edifícios que os reis de Judá haviam deixado ficar em ruínas.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 12, 'Esses homens fizeram o trabalho com fidelidade. Eram dirigidos por Jaate e Obadias, levitas descendentes de Merari, e Zacarias e Mesulão, descendentes de Coate. Todos os levitas que sabiam tocar instrumentos musicais', 3, CURRENT_TIMESTAMP, false),
(14, 34, 13, 'estavam encarregados dos operários e supervisionavam todos os trabalhadores em todas as funções. Outros levitas eram secretários, oficiais e porteiros.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 14, 'Enquanto recolhiam a prata que tinha sido levada para o templo do Senhor, o sacerdote Hilquias encontrou o livro da Lei do Senhor que havia sido dada por meio de Moisés.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 15, 'Hilquias disse ao secretário Safã: "Encontrei o livro da Lei no templo do Senhor". E o entregou a Safã.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 16, 'Então Safã levou o livro ao rei e lhe informou: "Teus servos estão fazendo tudo o que lhes foi ordenado.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 17, 'Fundiram a prata que estava no templo do Senhor e a confiaram aos supervisores e aos trabalhadores".', 3, CURRENT_TIMESTAMP, false),
(14, 34, 18, 'E acrescentou: "O sacerdote Hilquias entregou-me um livro". E Safã leu trechos do livro para o rei.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 19, 'Assim que o rei ouviu as palavras da Lei, rasgou suas vestes', 3, CURRENT_TIMESTAMP, false),
(14, 34, 20, 'e deu estas ordens a Hilquias, a Aicam, filho de Safã, a Abdom, filho de Mica, ao secretário Safã e ao auxiliar real Asaías:', 3, CURRENT_TIMESTAMP, false),
(14, 34, 21, '"Vão consultar o Senhor por mim e pelo remanescente de Israel e de Judá acerca do que está escrito neste livro que foi encontrado. A ira do Senhor contra nós deve ser grande, pois os nossos antepassados não obedeceram à palavra do Senhor e não agiram de acordo com tudo o que está escrito neste livro".', 3, CURRENT_TIMESTAMP, false),
(14, 34, 22, 'Hilquias e aqueles que o rei tinha enviado com ele foram falar com a profetisa Hulda, mulher de Salum, responsável pelo guarda-roupa do templo, filho de Tocate e neto de Harás. Ela morava no bairro novo de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 23, 'Ela lhes disse: "Assim diz o Senhor, o Deus de Israel: ‘Digam ao homem que os enviou a mim:', 3, CURRENT_TIMESTAMP, false),
(14, 34, 24, 'Assim diz o Senhor: Eu vou trazer uma desgraça sobre este lugar e sobre seus habitantes; todas as maldições escritas no livro que foi lido na presença do rei de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 25, 'Porque me abandonaram e queimaram incenso a outros deuses, provocando-me a ira por meio de todos os ídolos que as mãos deles têm feito, minha ira arderá contra este lugar e não será apagada’.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 26, 'Digam ao rei de Judá, que os enviou para consultar o Senhor: ‘Assim diz o Senhor, o Deus de Israel, acerca das palavras que você ouviu:', 3, CURRENT_TIMESTAMP, false),
(14, 34, 27, 'Já que o seu coração se abriu e você se humilhou diante de Deus quando ouviu o que ele falou contra este lugar e contra os seus habitantes, e você se humilhou diante de mim, rasgou as suas vestes e chorou na minha presença, eu o ouvi, declara o Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 28, 'Portanto, eu o reunirei aos seus antepassados, e você será sepultado em paz. Seus olhos não verão a desgraça que trarei sobre este lugar e sobre seus habitantes’ ". Então eles levaram a resposta ao rei.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 29, 'Então o rei convocou todas as autoridades de Judá e de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 30, 'Depois subiu ao templo do Senhor acompanhado por todos os homens de Judá, todo o povo de Jerusalém, os sacerdotes e os levitas: todo o povo, dos mais simples aos mais importantes. Para todos o rei leu em voz alta todas as palavras do Livro da Aliança, que havia sido encontrado no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 31, 'Ele tomou o seu lugar e, na presença do Senhor, fez uma aliança, comprometendo-se a seguir o Senhor e obedecer de todo o coração e de toda a alma aos seus mandamentos, seus testemunhos e seus decretos, cumprindo as palavras da aliança escritas naquele livro.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 32, 'Depois fez com que todos em Jerusalém e em Benjamim se comprometessem com a aliança; os habitantes de Jerusalém passaram a cumprir a aliança de Deus, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 34, 33, 'Josias retirou todos os ídolos detestáveis de todo o território dos israelitas e obrigou todos os que estavam em Israel a servirem ao Senhor, ao seu Deus. E enquanto ele viveu, o povo não deixou de seguir o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 1, 'Josias celebrou a Páscoa do Senhor em Jerusalém, e o cordeiro da Páscoa foi abatido no dia catorze do primeiro mês.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 2, 'Ele nomeou os sacerdotes para as suas responsabilidades e os encorajou a dedicar-se ao serviço no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 3, 'Ele disse aos levitas que instruíam todo Israel e haviam sido consagrados ao Senhor: "Ponham a arca sagrada no templo construído por Salomão, filho de Davi, rei de Israel. Vocês não precisam mais levá-la de um lado para outro sobre os ombros. Agora sirvam ao Senhor, ao seu Deus, e ao povo dele, Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 4, 'Preparem-se por famílias, em suas divisões, de acordo com a orientação escrita por Davi, rei de Israel, e por seu filho Salomão.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 5, '"Fiquem no lugar santo com um grupo de levitas para cada subdivisão das famílias do povo.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 6, 'Abatam os cordeiros da Páscoa, consagrem-se e preparem os cordeiros para os seus irmãos israelitas, fazendo o que o Senhor ordenou por meio de Moisés".', 3, CURRENT_TIMESTAMP, false),
(14, 35, 7, 'Josias deu a todo o povo que ali estava um total de trinta mil ovelhas e cabritos para as ofertas da Páscoa, além de três mil bois; tudo foi tirado dos bens pessoais do rei.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 8, 'Seus oficiais também contribuíram voluntariamente para o povo, para os sacerdotes e para os levitas. Hilquias, Zacarias e Jeiel, os administradores do templo de Deus, deram aos sacerdotes duas mil e seiscentas ovelhas e cabritos e trezentos bois.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 9, 'Também Conanias, junto com seus irmãos Semaías, Natanael e com os líderes dos levitas, Hasabias, Jeiel e Jozabade, ofereceram aos levitas cinco mil ovelhas e cabritos e quinhentos bois.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 10, 'O serviço foi organizado e os sacerdotes assumiram os seus lugares com os levitas em seus turnos, conforme o rei ordenara.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 11, 'Os cordeiros da Páscoa foram abatidos, e os sacerdotes aspergiram o sangue que lhes fora entregue, enquanto os levitas tiravam a pele dos animais.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 12, 'Eles separaram também os holocaustos para dá-los aos grupos das famílias do povo, para que essas os oferecessem ao Senhor, conforme está escrito no livro de Moisés; e fizeram o mesmo com os bois.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 13, 'Assaram os animais da Páscoa sobre o fogo, conforme prescrito, cozinharam as ofertas sagradas em potes, caldeirões e panelas, e serviram rapidamente a todo o povo.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 14, 'Depois disso, os levitas prepararam a parte deles e a dos sacerdotes, pois estes, descendentes de Arão, ficaram sacrificando os holocaustos e as porções de gordura até o anoitecer. Foi por isso que os levitas prepararam a parte deles e a dos sacerdotes, descendentes de Arão.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 15, 'Os músicos, descendentes de Asafe, estavam nos locais prescritos por Davi, e por Asafe, Hemã e Jedutum, videntes do rei. Os porteiros que guardavam cada porta não precisaram deixar os seus postos, pois os seus colegas levitas prepararam as ofertas para eles.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 16, 'Assim, naquele dia, todo o serviço do Senhor foi executado para a celebração da Páscoa e para a apresentação de holocaustos no altar do Senhor, conforme o rei Josias havia ordenado.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 17, 'Os israelitas que estavam presentes celebraram a Páscoa naquele dia e durante sete dias celebraram a festa dos pães sem fermento.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 18, 'A Páscoa não havia sido celebrada dessa maneira em Israel desde os dias do profeta Samuel; e nenhum dos reis de Israel havia celebrado uma Páscoa como esta, como o fez Josias, com os sacerdotes, os levitas e todo o Judá e Israel que estavam ali com o povo de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 19, 'Esta Páscoa foi celebrada no décimo oitavo ano do reinado de Josias.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 20, 'Depois de tudo o que Josias fez, e depois de colocar em ordem o templo, Neco, rei do Egito, saiu para lutar em Carquemis, junto ao Eufrates, e Josias marchou para combatê-lo.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 21, 'Neco, porém, enviou-lhe mensageiros, dizendo: "Não interfiras nisso, ó rei de Judá. Desta vez não estou atacando a ti, mas a outro reino com o qual estou em guerra. Deus me disse que me apressasse; por isso pára de opor-se a Deus, que está comigo; caso contrário ele o destruirá".', 3, CURRENT_TIMESTAMP, false),
(14, 35, 22, 'Josias, contudo, não quis voltar atrás, e disfarçou-se para enfrentá-lo em combate. Ele não quis ouvir o que Neco lhe disse por ordem de Deus, mas foi combatê-lo na planície de Megido.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 23, 'E na batalha, flecheiros atingiram o rei Josias, pelo que disse aos seus oficiais: "Tirem-me daqui. Estou gravemente ferido".', 3, CURRENT_TIMESTAMP, false),
(14, 35, 24, 'Eles o tiraram do seu carro, colocaram-no em outro e o levaram para Jerusalém, onde morreu. Ele foi sepultado nos túmulos dos seus antepassados, e todos os moradores de Judá e de Jerusalém choraram por ele.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 25, 'Jeremias compôs um cântico de lamento em homenagem a Josias, e até hoje todos os cantores e cantoras homenageiam Josias com cânticos de lamento. Estes se tornaram uma tradição em Israel e estão escritos na Coletânea das Lamentações.', 3, CURRENT_TIMESTAMP, false),
(14, 35, 26, 'Os demais acontecimentos do reinado de Josias e os seus atos piedosos, de acordo com o que está escrito na Lei do Senhor,', 3, CURRENT_TIMESTAMP, false),
(14, 35, 27, 'todos os acontecimentos, do início ao fim, estão escritos nos registros históricos dos reis de Israel e de Judá.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 1, 'E o povo tomou Jeoacaz, filho de Josias, e proclamou-o rei em Jerusalém, no lugar de seu pai.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 2, 'Jeoacaz tinha vinte e três anos de idade quando começou a reinar, e reinou três meses em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 3, 'O rei do Egito destronou-o em Jerusalém e impôs a Judá um tributo de três toneladas e meia de prata e trinta e cinco quilos de ouro.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 4, 'O rei do Egito proclamou Eliaquim, irmão de Jeoacaz, rei sobre Judá e sobre Jerusalém, e mudou-lhe o nome para Jeoaquim. Mas Neco levou Jeoacaz, irmão de Eliaquim, para o Egito.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 5, 'Jeoaquim tinha vinte e cinco anos de idade quando começou a reinar, e reinou onze anos em Jerusalém. Ele fez o que o Senhor, o seu Deus, reprova.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 6, 'Nabucodonosor, rei da Babilônia, atacou-o e prendeu-o com algemas de bronze para levá-lo para a Babilônia.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 7, 'E levou também para a Babilônia objetos do templo do Senhor e os colocou no seu templo.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 8, 'Os demais acontecimentos do reinado de Jeoaquim, as coisas detestáveis que fez e tudo o que foi achado contra ele, estão escritos nos registros históricos dos reis de Israel e de Judá. Seu filho Joaquim foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 9, 'Joaquim tinha dezoito anos de idade quando começou a reinar; e reinou três meses e dez dias em Jerusalém. Ele fez o que o Senhor reprova.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 10, 'Na primavera o rei Nabucodonosor mandou levá-lo para a Babilônia, junto com objetos de valor retirados do templo do Senhor, e proclamou Zedequias, tio de Joaquim, rei sobre Judá e sobre Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 11, 'Zedequias tinha vinte e um anos de idade quando começou a reinar, e reinou onze anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 12, 'Ele fez o que o Senhor, o seu Deus, reprova, e não se humilhou diante do profeta Jeremias, que lhe falava como porta-voz do Senhor.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 13, 'Também se revoltou contra o rei Nabucodonosor, que o havia obrigado a fazer um juramento em nome de Deus. Tornou-se muito obstinado e não quis se voltar para o Senhor, o Deus de Israel.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 14, 'Além disso, todos os líderes dos sacerdotes e o povo se tornaram cada vez mais infiéis, seguindo todas as práticas detestáveis das outras nações e contaminando o templo do Senhor, consagrado por ele em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 15, 'O Senhor, o Deus dos seus antepassados, advertiu-os várias vezes por meio de seus mensageiros, pois ele tinha compaixão de seu povo e do lugar de sua habitação.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 16, 'Mas eles zombaram dos mensageiros de Deus, desprezaram as palavras dele e expuseram ao ridículo os seus profetas, até que a ira do Senhor se levantou contra o seu povo, e já não houve remédio.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 17, 'Ele enviou contra eles o rei dos babilônios, que no santuário matou os seus jovens à espada. Não poupou nem rapazes, nem moças, nem adultos, nem velhos. Deus entregou todos eles nas mãos de Nabucodonosor;', 3, CURRENT_TIMESTAMP, false),
(14, 36, 18, 'este levou para a Babilônia todos os utensílios do templo de Deus, tanto os pequenos como os grandes, juntamente com os tesouros do templo do Senhor, os do rei e os de seus oficiais.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 19, 'Os babilônios incendiaram o templo de Deus e derrubaram o muro de Jerusalém; queimaram todos os palácios e destruíram todos os utensílios de valor que havia neles.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 20, 'Nabucodonosor levou para o exílio, na Babilônia, os remanescentes, que escaparam da espada, para serem seus escravos e dos seus descendentes, até à época do domínio persa.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 21, 'A terra desfrutou os seus descansos sabáticos; descansou durante todo o tempo de sua desolação, até que os setenta anos se completaram, em cumprimento da palavra do Senhor anunciada por Jeremias.', 3, CURRENT_TIMESTAMP, false),
(14, 36, 22, 'No primeiro ano do reinado de Ciro, rei da Pérsia, para que se cumprisse a palavra do Senhor anunciada por Jeremias, o Senhor tocou no coração de Ciro, rei da Pérsia, para que fizesse uma proclamação em todo o território de seu domínio e a pusesse por escrito, nestes termos:', 3, CURRENT_TIMESTAMP, false),
(14, 36, 23, '"Assim declaro Ciro, rei da Pérsia: ‘O Senhor, o Deus dos céus, deu-me todos os reinos da terra e designou-me para construir-lhe um templo em Jerusalém, na terra de Judá. Quem dentre vocês pertencer ao seu povo vá para Jerusalém, e que o Senhor, o seu Deus, esteja com ele’ ".', 3, CURRENT_TIMESTAMP, false),
(63, 1, 1, 'O presbítero à senhora eleita e aos seus filhos, a quem amo na verdade, — e não apenas eu os amo, mas também todos os que conhecem a verdade —', 3, CURRENT_TIMESTAMP, false),
(63, 1, 2, 'por causa da verdade que permanece em nós e estará conosco para sempre.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 3, 'A graça, a misericórdia e a paz da parte de Deus Pai e de Jesus Cristo, seu Filho, estarão conosco em verdade e em amor.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 4, 'Ao encontrar alguns dos seus filhos, muito me alegrei, pois eles estão andando na verdade, conforme o mandamento que recebemos do Pai.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 5, 'E agora eu lhe peço, senhora — não como se estivesse escrevendo um mandamento novo, o que já tínhamos desde o princípio — que nos amemos uns aos outros.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 6, 'E este é o amor: que andemos em obediência aos seus mandamentos. Como vocês já têm ouvido desde o princípio, o mandamento é este: que vocês andem em amor.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 7, 'De fato, muitos enganadores têm saído pelo mundo, os quais não confessam que Jesus Cristo veio em corpo. Tal é o enganador e o anticristo.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 8, 'Tenham cuidado, para que vocês não destruam o fruto do nosso trabalho, antes sejam recompensados plenamente.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 9, 'Todo aquele que não permanece no ensino de Cristo, mas vai além dele, não tem Deus; quem permanece no ensino tem o Pai e também o Filho.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 10, 'Se alguém chega a vocês e não trouxer esse ensino, não o recebam em casa nem o saúdem.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 11, 'Pois quem o saúda torna-se participante das suas obras malignas.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 12, 'Tenho muito que lhes escrever, mas não é meu propósito fazê-lo com papel e tinta. Em vez disso, espero visitá-los e falar com vocês face a face, para que a nossa alegria seja completa.', 3, CURRENT_TIMESTAMP, false),
(63, 1, 13, 'Os filhos da sua irmã eleita lhe enviam saudações.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 1, 'Simão Pedro, servo e apóstolo de Jesus Cristo, àqueles que, mediante a justiça de nosso Deus e Salvador Jesus Cristo, receberam conosco uma fé igualmente valiosa:', 3, CURRENT_TIMESTAMP, false),
(61, 1, 2, 'Graça e paz lhes sejam multiplicadas, pelo pleno conhecimento de Deus e de Jesus, o nosso Senhor.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 3, 'Seu divino poder nos deu todas as coisas de que necessitamos para a vida e para a piedade, por meio do pleno conhecimento daquele que nos chamou para a sua própria glória e virtude.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 4, 'Por intermédio destas ele nos deu as suas grandiosas e preciosas promessas, para que por elas vocês se tornassem participantes da natureza divina e fugissem da corrupção que há no mundo, causada pela cobiça.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 5, 'Por isso mesmo, empenhem-se para acrescentar à sua fé a virtude; à virtude o conhecimento;', 3, CURRENT_TIMESTAMP, false),
(61, 1, 6, 'ao conhecimento o domínio próprio; ao domínio próprio a perseverança; à perseverança a piedade;', 3, CURRENT_TIMESTAMP, false),
(61, 1, 7, 'à piedade a fraternidade; e à fraternidade o amor.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 8, 'Porque, se essas qualidades existirem e estiverem crescendo em suas vidas, elas impedirão que vocês, no pleno conhecimento de nosso Senhor Jesus Cristo, sejam inoperantes e improdutivos.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 9, 'Todavia, se alguém não as tem, está cego, só vê o que está perto, esquecendo-se da purificação dos seus antigos pecados.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 10, 'Portanto, irmãos, empenhem-se ainda mais para consolidar o chamado e a eleição de vocês, pois se agirem dessa forma, jamais tropeçarão,', 3, CURRENT_TIMESTAMP, false),
(61, 1, 11, 'e assim vocês estarão ricamente providos quando entrarem no Reino eterno de nosso Senhor e Salvador Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 12, 'Por isso, sempre terei o cuidado de lembrar-lhes estas coisas, se bem que vocês já as sabem e estão solidamente firmados na verdade que receberam.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 13, 'Considero importante, enquanto estiver no tabernáculo deste corpo, despertar a memória de vocês,', 3, CURRENT_TIMESTAMP, false),
(61, 1, 14, 'porque sei que em breve deixarei este tabernáculo, como o nosso Senhor Jesus Cristo já me revelou.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 15, 'Eu me empenharei para que, também depois da minha partida, vocês sejam sempre capazes de lembrar-se destas coisas.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 16, 'De fato, não seguimos fábulas engenhosamente inventadas, quando lhes falamos a respeito do poder e da vinda de nosso Senhor Jesus Cristo; pelo contrário, nós fomos testemunhas oculares da sua majestade.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 17, 'Ele recebeu honra e glória da parte de Deus Pai, quando da suprema glória lhe foi dirigida a voz que disse: "Este é o meu filho amado, em quem me agrado".', 3, CURRENT_TIMESTAMP, false),
(61, 1, 18, 'Nós mesmos ouvimos essa voz vinda do céu, quando estávamos com ele no monte santo.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 19, 'Assim, temos ainda mais firme a palavra dos profetas, e vocês farão bem se a ela prestarem atenção, como a uma candeia que brilha em lugar escuro, até que o dia clareie e a estrela da alva nasça em seus corações.', 3, CURRENT_TIMESTAMP, false),
(61, 1, 20, 'Antes de mais nada, saibam que nenhuma profecia da Escritura provém de interpretação pessoal,', 3, CURRENT_TIMESTAMP, false),
(61, 1, 21, 'pois jamais a profecia teve origem na vontade humana, mas homens falaram da parte de Deus, impelidos pelo Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 1, 'No passado surgiram falsos profetas no meio do povo, como também surgirão entre vocês falsos mestres. Estes introduzirão secretamente heresias destruidoras, chegando a negar o Soberano que os resgatou, trazendo sobre si mesmos repentina destruição.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 2, 'Muitos seguirão os caminhos vergonhosos desses homens e, por causa deles, será difamado o caminho da verdade.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 3, 'Em sua cobiça, tais mestres os explorarão com histórias que inventaram. Há muito tempo a sua condenação paira sobre eles, e a sua destruição não tarda.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 4, 'Pois Deus não poupou os anjos que pecaram, mas os lançou no inferno, prendendo-os em abismos tenebrosos a fim de serem reservados para o juízo.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 5, 'Ele não poupou o mundo antigo quando trouxe o dilúvio sobre aquele povo ímpio, mas preservou Noé, pregador da justiça, e mais sete pessoas.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 6, 'Também condenou as cidades de Sodoma e Gomorra, reduzindo-as a cinzas, tornando-as exemplo do que acontecerá aos ímpios;', 3, CURRENT_TIMESTAMP, false),
(61, 2, 7, 'mas livrou Ló, homem justo, que se afligia com o procedimento libertino dos que não tinham princípios morais', 3, CURRENT_TIMESTAMP, false),
(61, 2, 8, '( pois, vivendo entre eles, todos os dias aquele justo se atormentava em sua alma justa por causa das maldades que via e ouvia ).', 3, CURRENT_TIMESTAMP, false),
(61, 2, 9, 'Vemos, portanto, que o Senhor sabe livrar os piedosos da provação e manter em castigo os ímpios para o dia do juízo,', 3, CURRENT_TIMESTAMP, false),
(61, 2, 10, 'especialmente os que seguem os desejos impuros da carne e desprezam a autoridade. Insolentes e arrogantes, tais homens não têm medo de difamar os seres celestiais;', 3, CURRENT_TIMESTAMP, false),
(61, 2, 11, 'contudo, nem os anjos, embora sendo maiores em força e poder, fazem acusações injuriosas contra aqueles seres na presença do Senhor.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 12, 'Mas eles difamam o que desconhecem e são como criaturas irracionais, guiadas pelo instinto, nascidas para serem capturadas e destruídas; serão corrompidos pela sua própria corrupção!', 3, CURRENT_TIMESTAMP, false),
(61, 2, 13, 'Eles receberão retribuição pela injustiça que causaram. Consideram prazer entregar-se à devassidão em plena luz do dia. São nódoas e manchas, regalando-se em seus prazeres, quando participam das festas de vocês.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 14, 'Tendo os olhos cheios de adultério, nunca param de pecar, iludem os instáveis e têm o coração exercitado na ganância. Malditos!', 3, CURRENT_TIMESTAMP, false),
(61, 2, 15, 'Eles abandonaram o caminho reto e se desviaram, seguindo o caminho de Balaão, filho de Beor, que amou o salário da injustiça,', 3, CURRENT_TIMESTAMP, false),
(61, 2, 16, 'mas em sua transgressão foi repreendido por uma jumenta, um animal mudo, que falou com voz humana e refreou a insensatez do profeta.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 17, 'Esses homens são fontes sem água e névoas impelidas pela tempestade. A escuridão das trevas lhes está reservada,', 3, CURRENT_TIMESTAMP, false),
(61, 2, 18, 'pois eles, com palavras de vaidosa arrogância e provocando os desejos libertinos da carne, seduzem os que estão quase conseguindo fugir daqueles que vivem no erro.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 19, 'Prometendo-lhes liberdade, eles mesmos são escravos da corrupção, pois o homem é escravo daquilo que o domina.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 20, 'Se, tendo escapado das contaminações do mundo por meio do conhecimento de nosso Senhor e Salvador Jesus Cristo, encontram-se novamente nelas enredados e por elas dominados, estão em pior estado do que no princípio.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 21, 'Teria sido melhor que não tivessem conhecido o caminho da justiça, do que, depois de o terem conhecido, voltarem as costas para o santo mandamento que lhes foi transmitido.', 3, CURRENT_TIMESTAMP, false),
(61, 2, 22, 'Confirma-se neles que é verdadeiro o provérbio: "O cão voltou ao seu vômito" e ainda: "A porca lavada voltou a revolver-se na lama".', 3, CURRENT_TIMESTAMP, false),
(61, 3, 1, 'Amados, esta é agora a segunda carta que lhes escrevo. Em ambas quero despertar com estas lembranças a sua mente sincera para que vocês se lembrem', 3, CURRENT_TIMESTAMP, false),
(61, 3, 2, 'das palavras proferidas no passado pelos santos profetas, e do mandamento de nosso Senhor e Salvador que os apóstolos de vocês lhes ensinaram.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 3, 'Antes de tudo saibam que, nos últimos dias, surgirão escarnecedores zombando e seguindo suas próprias paixões.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 4, 'Eles dirão: "O que houve com a promessa da sua vinda? Desde que os antepassados morreram, tudo continua como desde o princípio da criação".', 3, CURRENT_TIMESTAMP, false),
(61, 3, 5, 'Mas eles deliberadamente se esquecem de que há muito tempo, pela palavra de Deus, existiam céus e terra, esta formada da água e pela água.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 6, 'E pela água o mundo daquele tempo foi submerso e destruído.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 7, 'Pela mesma palavra os céus e a terra que agora existem estão reservados para o fogo, guardados para o dia do juízo e para a destruição dos ímpios.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 8, 'Não se esqueçam disto, amados: para o Senhor um dia é como mil anos, e mil anos como um dia.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 9, 'O Senhor não demora em cumprir a sua promessa, como julgam alguns. Pelo contrário, ele é paciente com vocês, não querendo que ninguém pereça, mas que todos cheguem ao arrependimento.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 10, 'O dia do Senhor, porém, virá como ladrão. Os céus desaparecerão com um grande estrondo, os elementos serão desfeitos pelo calor, e a terra, e tudo o que nela há, será desnudada.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 11, 'Visto que tudo será assim desfeito, que tipo de pessoas é necessário que vocês sejam? Vivam de maneira santa e piedosa,', 3, CURRENT_TIMESTAMP, false),
(61, 3, 12, 'esperando o dia de Deus e apressando a sua vinda. Naquele dia os céus serão desfeitos pelo fogo, e os elementos se derreterão pelo calor.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 13, 'Todavia, de acordo com a sua promessa, esperamos novos céus e nova terra, onde habita a justiça.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 14, 'Portanto, amados, enquanto esperam estas coisas, empenhem-se para serem encontrados por ele em paz, imaculados e inculpáveis.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 15, 'Tenham em mente que a paciência de nosso Senhor significa salvação, como também o nosso amado irmão Paulo lhes escreveu, com a sabedoria que Deus lhe deu.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 16, 'Ele escreve da mesma forma em todas as suas cartas, falando nelas destes assuntos. Suas cartas contêm algumas coisas difíceis de entender, as quais os ignorantes e instáveis torcem, como também o fazem com as demais Escrituras, para a própria destruição deles.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 17, 'Portanto, amados, sabendo disso, guardem-se para que não sejam levados pelo erro dos que não têm princípios morais, nem percam a sua firmeza e caiam.', 3, CURRENT_TIMESTAMP, false),
(61, 3, 18, 'Cresçam, porém, na graça e no conhecimento de nosso Senhor e Salvador Jesus Cristo. A ele seja a glória, agora e para sempre! Amém.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 1, 'Depois da morte de Acabe, Moabe rebelou-se contra Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 2, 'Certo dia, Acazias caiu da sacada do seu quarto no palácio de Samaria, e ficou muito ferido. Então enviou mensageiros para consultar Baal-Zebube, deus de Ecrom, para saber se ele se recuperaria.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 3, 'Mas o anjo do Senhor disse ao tesbita Elias: "Vá encontrar-se com os mensageiros do rei de Samaria e lhes pergunte: ‘Acaso não há Deus em Israel? Por que vocês vão consultar Baal-Zebube, deus de Ecrom? ’', 3, CURRENT_TIMESTAMP, false),
(12, 1, 4, 'Por isso, assim diz o Senhor: ‘Você não se levantará mais dessa cama e certamente morrerá! ’ " E assim Elias se foi.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 5, 'Quando os mensageiros voltaram ao rei, ele lhes perguntou: "Por que vocês voltaram? "', 3, CURRENT_TIMESTAMP, false),
(12, 1, 6, 'Eles responderam: "Um homem veio ao nosso encontro e nos disse: ‘Voltem ao rei que os enviou e digam-lhe: Assim diz o Senhor: "Acaso não há Deus em Israel? Por que você mandou consultar Baal-Zebube, deus de Ecrom? Por isso você não se levantará mais dessa cama e certamente morrerá! " ’ "', 3, CURRENT_TIMESTAMP, false),
(12, 1, 7, 'O rei lhes perguntou: "Como era o homem que os encontrou e lhes disse isso? "', 3, CURRENT_TIMESTAMP, false),
(12, 1, 8, 'Eles responderam: "Ele vestia roupas de pêlos e usava um cinto de couro". O rei concluiu: "Era o tesbita Elias".', 3, CURRENT_TIMESTAMP, false),
(12, 1, 9, 'Em seguida mandou um oficial com cinqüenta soldados procurar Elias. O oficial o encontrou sentado no alto de uma colina, e lhe disse: "Homem de Deus, o rei ordena que você desça"', 3, CURRENT_TIMESTAMP, false),
(12, 1, 10, 'Elias respondeu ao oficial: "Se sou homem de Deus, que desça fogo do céu e consuma você e seus cinqüenta soldados! " E desceu fogo do céu e consumiu o oficial e seus soldados.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 11, 'Depois disso o rei enviou outro oficial com mais cinqüenta soldados. E ele disse a Elias: "Homem de Deus o rei ordena que você desça imediatamente".', 3, CURRENT_TIMESTAMP, false),
(12, 1, 12, 'Respondeu Elias: "Se sou homem de Deus, que desça fogo do céu e consuma você e seus cinqüenta soldados! " De novo fogo de Deus desceu do céu e consumiu o oficial e seus soldados.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 13, 'Então o rei enviou um terceiro oficial com outros cinqüenta soldados. O oficial subiu o monte, caiu de joelhos diante de Elias e implorou: "Homem de Deus, tenha consideração por minha vida e pela vida destes cinqüenta soldados, teus servos!', 3, CURRENT_TIMESTAMP, false),
(12, 1, 14, 'Sei que desceu fogo do céu e consumiu os dois primeiros oficiais com todos os seus soldados. Mas agora tenha consideração por minha vida! "', 3, CURRENT_TIMESTAMP, false),
(12, 1, 15, 'O anjo do Senhor disse a Elias: "Acompanhe-o; não tenha medo dele". Então Elias se levantou, desceu com ele e foi falar com o rei.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 16, 'Ao chegar, disse ao rei: "Assim diz o Senhor: Acaso não há Deus em Israel? Por que você mandou consultar Baal-Zebube, deus de Ecrom? Por isso, você não se levantará mais dessa cama e certamente morrerá! "', 3, CURRENT_TIMESTAMP, false),
(12, 1, 17, 'E Acazias morreu, conforme a palavra do Senhor, anunciada por Elias. Como não tinha filhos, Jorão foi o seu sucessor no segundo ano do reinado de Jeorão, rei de Judá, filho de Josafá.', 3, CURRENT_TIMESTAMP, false),
(12, 1, 18, 'Os demais acontecimentos do reinado de Acazias e suas realizações estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 1, 'Quando o Senhor levou Elias aos céus num redemoinho aconteceu o seguinte: Elias e Eliseu saíram de Gilgal,', 3, CURRENT_TIMESTAMP, false),
(12, 2, 2, 'e no caminho disse-lhe Elias: "Fique aqui, pois o Senhor me enviou a Betel". Eliseu, porém, disse: "Juro pelo nome do Senhor e por tua vida, que não te deixarei ir só". Então foram a Betel.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 3, 'Em Betel os discípulos dos profetas foram falar com Eliseu e perguntaram: "Você sabe que hoje o Senhor vai levar para os céus o seu mestre, separando-o de você? " Respondeu Eliseu: "Sim, eu sei, mas não falem nisso".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 4, 'Então Elias lhe disse: "Fique aqui, Eliseu, pois o Senhor me enviou a Jericó". Ele respondeu: "Juro pelo nome do Senhor e por tua vida, que não te deixarei ir só". Desceram então a Jericó.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 5, 'Em Jericó os discípulos dos profetas foram falar com Eliseu e lhe perguntaram: "Você sabe que hoje o Senhor vai levar para os céus o seu mestre, separando-o de você? " Respondeu Eliseu: "Sim, eu sei, mas não falem nisso".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 6, 'Em seguida Elias lhe disse: "Fique aqui, pois o Senhor me enviou ao rio Jordão". Ele respondeu: "Juro pelo nome do Senhor e por tua vida, que não te deixarei ir só! " Então partiram juntos.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 7, 'Cinqüenta discípulos dos profetas os acompanharam e ficaram olhando a distância, quando Elias e Eliseu pararam à margem do Jordão.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 8, 'Então Elias tirou o manto, enrolou-o e com ele bateu nas águas. As águas se dividiram, e os dois atravessaram a seco.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 9, 'Depois de atravessar, Elias disse a Eliseu: "O que posso fazer por você antes que eu seja levado para longe de você? " Respondeu Eliseu: "Faze de mim o principal herdeiro de teu espírito profético".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 10, 'Disse Elias: "Você fez um pedido difícil; mas, se você me vir quando eu for separado de você, terá o que pediu; do contrário, não será atendido".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 11, 'De repente, enquanto caminhavam e conversavam, apareceu um carro de fogo, puxado por cavalos de fogo, que os separou, e Elias foi levado aos céus num redemoinho.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 12, 'Quando viu isso, Eliseu gritou: "Meu pai! Meu pai! Tu eras como os carros de guerra e os cavaleiros de Israel! " E quando já não podia mais vê-lo, Eliseu pegou as próprias vestes e as rasgou ao meio.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 13, 'Depois pegou o manto de Elias, que tinha caído, e voltou para a margem do Jordão.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 14, 'Então bateu nas águas do rio com o manto e perguntou: "Onde está agora o Senhor, o Deus de Elias? " Tendo batido nas águas, essas se dividiram e ele atravessou.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 15, 'Quando os discípulos dos profetas, vindos de Jericó, viram isso, disseram: "O espírito profético de Elias repousa sobre Eliseu". Então foram ao seu encontro, prostraram-se diante dele e disseram:', 3, CURRENT_TIMESTAMP, false),
(12, 2, 16, '"Olha, nós, teus servos, temos cinqüenta homens fortes. Deixa-os sair à procura do teu mestre. Talvez o Espírito do Senhor o tenha levado e deixado em algum monte ou em algum vale". Respondeu Eliseu: "Não mandem ninguém".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 17, 'Mas eles insistiram até que, constrangido, consentiu: "Podem mandar os homens". E mandaram cinqüenta homens, que procuraram Elias por três dias, mas não o encontraram.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 18, 'Quando voltaram a Eliseu, que tinha ficado em Jericó, ele lhes falou: "Não lhes disse que não fossem? "', 3, CURRENT_TIMESTAMP, false),
(12, 2, 19, 'Alguns homens da cidade foram dizer a Eliseu: "Como podes ver, esta cidade está bem localizada, mas a água não é boa e a terra é improdutiva".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 20, 'E disse ele: "Ponham sal numa tigela nova e tragam-na para mim". Quando a levaram,', 3, CURRENT_TIMESTAMP, false),
(12, 2, 21, 'ele foi à nascente, jogou o sal ali e disse: "Assim diz o Senhor: ‘Purifiquei esta água. Não causará mais mortes nem deixará a terra improdutiva’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 2, 22, 'E até hoje a água permanece pura, conforme a palavra de Eliseu.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 23, 'De Jericó Eliseu foi para Betel. No caminho, alguns meninos que vinham da cidade começaram a caçoar dele, gritando: "Suma daqui, careca! "', 3, CURRENT_TIMESTAMP, false),
(12, 2, 24, 'Voltando-se, olhou para eles e os amaldiçoou em nome do Senhor. Então, duas ursas saíram do bosque e despedaçaram quarenta e dois meninos.', 3, CURRENT_TIMESTAMP, false),
(12, 2, 25, 'De Betel prosseguiu até o monte Carmelo e dali voltou a Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 1, 'Jorão, filho de Acabe, tornou-se rei de Israel em Samaria no décimo oitavo ano de Josafá, rei de Judá, e reinou doze anos.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 2, 'Fez o que o Senhor reprova, mas não como seu pai e sua mãe, pois derrubou a coluna sagrada de Baal, que seu pai havia feito.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 3, 'No entanto, persistiu nos pecados que Jeroboão, filho de Nebate, levara Israel a cometer e deles não se afastou.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 4, 'Ora, Messa, rei de Moabe, tinha muitos rebanhos e pagava como tributo ao rei de Israel cem mil cordeiros e a lã de cem mil carneiros.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 5, 'Mas, depois que Acabe morreu, o rei de Moabe rebelou-se contra o rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 6, 'E, naquela ocasião, o rei Jorão partiu de Samaria e mobilizou todo Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 7, 'Também enviou esta mensagem a Josafá, rei de Judá: "O rei de Moabe rebelou-se contra mim. Irás acompanhar-me na luta contra Moabe? " Ele respondeu: "Sim, eu irei. Serei teu aliado, os meus soldados e os teus, os meus cavalos e os teus serão um só exército".', 3, CURRENT_TIMESTAMP, false),
(12, 3, 8, 'E perguntou: "Por qual caminho atacaremos? " Respondeu Jorão: "Pelo deserto de Edom".', 3, CURRENT_TIMESTAMP, false),
(12, 3, 9, 'Então o rei de Israel partiu com os reis de Judá e de Edom. Depois de uma marcha de sete dias, já havia acabado a água para os homens e para os animais.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 10, 'Exclamou, então, o rei de Israel: "E agora? Será que o Senhor ajuntou a nós, os três reis, para nos entregar nas mãos de Moabe? "', 3, CURRENT_TIMESTAMP, false),
(12, 3, 11, 'Mas Josafá perguntou: "Será que não há aqui profeta do Senhor, para que possamos consultar o Senhor por meio dele? " Um conselheiro do rei de Israel respondeu: "Eliseu, filho de Safate, está aqui. Ele era auxiliar de Elias".', 3, CURRENT_TIMESTAMP, false),
(12, 3, 12, 'Josafá prosseguiu: "A palavra do Senhor está com ele". Então o rei de Israel, Josafá e o rei de Edom foram falar com ele.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 13, 'Eliseu disse ao rei de Israel: "Nada tenho a ver com você. Vá consultar os profetas de seu pai e de sua mãe". Mas o rei de Israel insistiu: "Não, pois foi o Senhor que ajuntou a nós, estes três reis, para entregar-nos nas mãos de Moabe".', 3, CURRENT_TIMESTAMP, false),
(12, 3, 14, 'Então Eliseu disse: "Juro pelo nome do Senhor dos Exércitos, a quem sirvo, que se não fosse por respeito a Josafá, rei de Judá, eu não olharia para você nem mesmo lhe daria atenção.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 15, 'Mas agora tragam-me um harpista". Enquanto o harpista estava tocando, o poder do Senhor veio sobre Eliseu,', 3, CURRENT_TIMESTAMP, false),
(12, 3, 16, 'e ele disse: "Assim diz o Senhor: Cavem muitas cisternas neste vale.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 17, 'Pois assim diz o Senhor: Vocês não verão vento nem chuva, contudo este vale ficará cheio de água, e vocês, seus rebanhos e seus outros animais beberão.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 18, 'Mas para o Senhor isso ainda é pouco; ele também lhes entregará Moabe nas suas mãos.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 19, 'Vocês destruirão todas as cidades fortificadas e todas as cidades importantes. Derrubarão toda árvore frutífera, taparão todas as fontes e encherão de pedras todas as terras de cultivo".', 3, CURRENT_TIMESTAMP, false),
(12, 3, 20, 'No dia seguinte, na hora do sacrifício da manhã, a água veio descendo da direção de Edom e alagou a região.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 21, 'Quando os moabitas ficaram sabendo que os reis tinham vindo para atacá-los, todos os que eram capazes de empunhar armas, do mais jovem ao mais velho, foram convocados e posicionaram-se na fronteira.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 22, 'Ao se levantarem na manhã seguinte, o sol refletia na água. Para os moabitas que estavam defronte dela, a água era vermelha como sangue.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 23, 'Então gritaram: "É sangue! Os reis lutaram entre si e se mataram. Agora, ao saque, Moabe! "', 3, CURRENT_TIMESTAMP, false),
(12, 3, 24, 'Quando, porém, os moabitas chegaram ao acampamento de Israel, os israelitas os atacaram e os puseram em fuga. Entraram no território de Moabe e o arrasaram.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 25, 'Destruíram as cidades, e quando passavam por um campo cultivável cada homem atirava uma pedra até que ficasse coberto. Taparam todas as fontes e derrubaram toda árvore frutífera. Só Quir-Haresete ficou com as pedras no lugar, mas homens armados de atiradeiras a cercaram e também a atacaram.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 26, 'Quando o rei de Moabe viu que estava perdendo a batalha, reuniu setecentos homens armados de espadas para forçar a passagem, para alcançar o rei de Edom, mas fracassou.', 3, CURRENT_TIMESTAMP, false),
(12, 3, 27, 'Então pegou seu filho mais velho, que devia sucedê-lo como rei, e o sacrificou sobre o muro da cidade. Isso trouxe grande ira contra Israel, de modo que eles se retiraram e voltaram para sua própria terra.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 1, 'Certo dia, a mulher de um dos discípulos dos profetas foi falar a Eliseu: "Teu servo, meu marido, morreu, e tu sabes que ele temia o Senhor. Mas agora veio um credor que está querendo levar meus dois filhos como escravos".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 2, 'Eliseu perguntou-lhe: "Como posso ajudá-la? Diga-me, o que você tem em casa? " E ela respondeu: "Tua serva não tem nada além de uma vasilha de azeite".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 3, 'Então disse Eliseu: "Vá pedir emprestadas vasilhas a todos os vizinhos. Mas, peça muitas.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 4, 'Depois entre em casa com seus filhos e feche a porta. Derrame daquele azeite em cada vasilha e vá separando as que você for enchendo".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 5, 'Depois disso, ela foi embora, fechou-se em casa com seus filhos e começou a encher as vasilhas que eles lhe traziam.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 6, 'Quando todas as vasilhas estavam cheias, ela disse a um dos filhos: "Traga-me mais uma". Mas ele respondeu: "Já acabaram". Então o azeite parou de correr.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 7, 'Ela foi e contou tudo ao homem de Deus, que lhe disse: "Vá, venda o azeite e pague suas dívidas. E você e seus filhos ainda poderão viver do que sobrar".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 8, 'Certo dia, Eliseu foi a Suném, onde uma mulher rica insistiu que ele fosse tomar uma refeição em sua casa. Depois disso, sempre que passava por ali, ele parava para uma refeição.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 9, 'De modo que ela disse ao marido: "Sei que esse homem que sempre vem aqui é um santo homem de Deus.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 10, 'Vamos construir lá em cima um quartinho de tijolos e colocar nele uma cama, uma mesa, uma cadeira e uma lamparina para ele. Assim, sempre que nos visitar ele poderá ocupá-lo".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 11, 'Um dia, quando Eliseu chegou, subiu ao seu quarto e deitou-se.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 12, 'Ele mandou o seu servo Geazi chamar a sunamita. Então ele a chamou, e quando ela veio,', 3, CURRENT_TIMESTAMP, false),
(12, 4, 13, 'Eliseu mandou que Geazi dissesse a ela: "Você teve todo este trabalho por nossa causa. O que podemos fazer por você? Quer que eu interceda por você junto ao rei ou ao comandante do exército? " Ela respondeu: "Estou bem entre minha própria gente".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 14, 'Mais tarde Eliseu perguntou a Geazi: "O que se pode fazer por ela? " Ele respondeu: "Bem, ela não tem filhos, e seu marido é idoso".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 15, 'Então Eliseu mandou chamá-la de novo. Geazi a chamou, e ela veio até a porta.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 16, 'E ele disse: "Por volta desta época, no ano que vem, você estará com um filho nos braços". Ela contestou: "Não, meu senhor. Não iludas a tua serva, ó homem de Deus! "', 3, CURRENT_TIMESTAMP, false),
(12, 4, 17, 'Mas, como Eliseu lhe dissera, a mulher engravidou e, no ano seguinte, por volta daquela mesma época, deu à luz um filho.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 18, 'O menino cresceu e, certo dia, foi encontrar seu pai, que estava com os ceifeiros.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 19, 'De repente, ele começou a chamar o pai, gritando: "Ai, minha cabeça! Ai, minha cabeça! " Então o pai disse a um servo: "Leve-o para a mãe dele".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 20, 'O servo o pegou e o levou à mãe, o menino ficou no colo dela até o meio-dia, quando morreu.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 21, 'Ela subiu ao quarto do homem de Deus, deitou o menino na cama, saiu e fechou a porta.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 22, 'Ela chamou o marido e disse: "Preciso de um servo e uma jumenta para ir falar com o homem de Deus. Vou e volto depressa".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 23, 'Ele perguntou: "Mas, por que hoje? Não é lua nova nem sábado! " Ela respondeu: "Não se preocupe".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 24, 'Ela mandou selar a jumenta, e disse ao servo: "Vamos rápido, só pare quando eu mandar".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 25, 'Assim ela partiu para encontrar-se com o homem de Deus no monte Carmelo. Quando ele a viu a distância, disse a seu servo Geazi: "Olhe! É a sunamita!', 3, CURRENT_TIMESTAMP, false),
(12, 4, 26, 'Corra ao encontro dela e lhe pergunte: ‘Está tudo bem com você? Tudo bem com seu marido? E com seu filho? ’ " Ela respondeu a Geazi: "Está tudo bem".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 27, 'Ao encontrar o homem de Deus no monte, ela se abraçou aos seus pés. Geazi veio para afastá-la, mas o homem de Deus lhe disse: "Deixe-a em paz! Ela está muito angustiada, mas o Senhor nada me revelou e escondeu de mim a razão de sua angústia".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 28, 'E disse a mulher: "Acaso eu te pedi um filho, meu senhor? Não te disse para não me dar falsas esperanças? "', 3, CURRENT_TIMESTAMP, false),
(12, 4, 29, 'Então Eliseu disse a Geazi: "Ponha a capa por dentro do cinto, pegue o meu cajado e corra. Se você encontrar alguém, não o cumprimente e, se alguém o cumprimentar, não responda. Quando lá chegar, ponha o meu cajado sobre o rosto do menino".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 30, 'Mas a mãe do menino disse: "Juro pelo nome do Senhor e por tua vida que, se ficares, não irei". Então ele foi com ela.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 31, 'Geazi chegou primeiro e pôs o cajado sobre o rosto do menino, mas ele não falou nem reagiu. Então Geazi voltou para encontrar-se com Eliseu e lhe disse: "O menino não voltou a si".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 32, 'Quando Eliseu chegou à casa, lá estava o menino, morto, estendido na cama.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 33, 'Ele entrou, fechou a porta e orou ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 34, 'Então, deitou-se sobre o menino, boca a boca, olhos com olhos, mãos com mãos. Enquanto se debruçava sobre ele, o corpo do menino foi se aquecendo.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 35, 'Eliseu levantou-se e começou a andar pelo quarto; depois subiu na cama e debruçou-se mais uma vez sobre ele. O menino espirrou sete vezes e abriu os olhos.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 36, 'Eliseu chamou Geazi e o mandou chamar a sunamita. E ele obedeceu. Quando ela chegou, Eliseu disse: "Pegue seu filho".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 37, 'Ela entrou, prostrou-se a seus pés, curvando-se até o chão. Então pegou o filho e saiu.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 38, 'Depois Eliseu voltou a Gilgal. Nesse tempo a fome assolava a região. Quando os discípulos dos profetas estavam reunidos com ele, ordenou ao seu servo: "Ponha o caldeirão no fogo e faça um ensopado para estes homens".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 39, 'Um deles foi ao campo apanhar legumes e encontrou uma trepadeira. Apanhou alguns de seus frutos e encheu deles o seu manto. Quando voltou, cortou-os em pedaços e colocou-os no caldeirão do ensopado, embora ninguém soubesse o que era.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 40, 'O ensopado foi servido aos homens, mas, logo que o provaram, eles gritaram: "Homem de Deus, há morte na panela! " E não puderam mais tomá-lo.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 41, 'Então Eliseu pediu um pouco de farinha, colocou no caldeirão e disse: "Sirvam a todos". E já não havia mais perigo no caldeirão.', 3, CURRENT_TIMESTAMP, false),
(12, 4, 42, 'Veio um homem de Baal-Salisa, trazendo ao homem de Deus vinte pães de cevada, feitos dos primeiros grãos da colheita, e também algumas espigas verdes. Então Eliseu ordenou ao seu servo: "Sirva a todos".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 43, 'O auxiliar de Eliseu perguntou: "Como poderei servir isso a cem homens? " Eliseu, porém, respondeu: "Sirva a todos, pois assim diz o Senhor: ‘Eles comerão, e ainda sobrará’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 4, 44, 'Então ele serviu a todos, e conforme a palavra do Senhor, eles comeram e ainda sobrou.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 1, 'Naamã, comandante do exército do rei da Síria, era muito respeitado e honrado pelo seu senhor, pois por meio dele o Senhor dera vitória à Síria. Mas esse grande guerreiro ficou leproso.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 2, 'Ora, tropas da Síria haviam atacado Israel e levado cativa uma menina, que passou a servir à mulher de Naamã.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 3, 'Um dia ela disse à sua senhora: "Se o meu senhor procurasse o profeta que está em Samaria, ele o curaria da lepra".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 4, 'Naamã foi contar ao seu senhor o que a menina israelita dissera.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 5, 'O rei da Síria respondeu: "Vá. Eu lhe darei uma carta que você entregará ao rei de Israel". Então Naamã partiu, levando consigo trezentos e cinqüenta quilos de prata, setenta e dois quilos de ouro e dez mudas de roupas finas.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 6, 'A carta que levou ao rei de Israel dizia: "Junto com esta carta estou te enviando meu oficial Naamã, para que o cures da lepra".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 7, 'Assim que o rei de Israel leu a carta, rasgou as vestes e disse: "Por acaso sou Deus, capaz de conceder vida ou morte? Por que este homem me envia alguém para que eu o cure da lepra? Vejam como ele procura um motivo para se desentender comigo! "', 3, CURRENT_TIMESTAMP, false),
(12, 5, 8, 'Quando Eliseu, o homem de Deus, soube que o rei de Israel havia rasgado suas vestes, mandou-lhe esta mensagem: "Por que rasgaste tuas vestes? Envia o homem a mim, e ele saberá que há profeta em Israel".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 9, 'Então, Naamã foi com seus cavalos e carros e parou à porta da casa de Eliseu.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 10, 'Eliseu enviou um mensageiro para lhe dizer: "Vá e lave-se sete vezes no rio Jordão; sua pele será restaurada e você ficará purificado".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 11, 'Mas Naamã ficou indignado e saiu dizendo: "Eu estava certo de que ele sairia para receber-me, invocaria de pé o nome do Senhor seu Deus, moveria a mão sobre o lugar afetado e me curaria da lepra.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 12, 'Não são os rios Abana e Farfar, em Damasco, melhores do que todas as águas de Israel? Será que não poderia lavar-me neles e ser purificado? " Então, foi embora dali furioso.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 13, 'Mas os seus servos lhe disseram: "Meu pai, se o profeta lhe tivesse pedido alguma coisa difícil, o senhor não faria? Quanto mais, quando ele apenas lhe diz para que se lave e seja purificado! "', 3, CURRENT_TIMESTAMP, false),
(12, 5, 14, 'Assim ele desceu ao Jordão e mergulhou sete vezes conforme a ordem do homem de Deus; ele foi purificado e sua pele tornou-se como a de uma criança.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 15, 'Então Naamã e toda a sua comitiva voltaram à casa do homem de Deus. Ao chegar diante do profeta, Naamã lhe disse: "Agora sei que não há Deus em nenhum outro lugar, senão em Israel. Por favor, aceita um presente de teu servo".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 16, 'O profeta respondeu: "Juro pelo nome do Senhor, a quem sirvo, que nada aceitarei". Embora Naamã insistisse, ele recusou.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 17, 'E disse Naamã: "Já que não aceitas o presente, ao menos permite que eu leve duas mulas carregadas de terra, pois teu servo nunca mais fará holocaustos e sacrifícios a nenhum outro deus senão ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 18, 'Mas que o Senhor me perdoe por uma única coisa: quando meu senhor vai adorar no templo de Rimom, eu também tenho que me ajoelhar ali pois ele se apóia em meu braço. Que o Senhor perdoe o teu servo por isso".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 19, 'Disse Eliseu: "Vá em paz". Quando Naamã já estava a certa distância,', 3, CURRENT_TIMESTAMP, false),
(12, 5, 20, 'Geazi, servo de Eliseu, o homem de Deus, pensou: "Meu senhor foi bom demais para Naamã, aquele arameu, não aceitando o que ele lhe ofereceu. Juro pelo nome do Senhor que correrei atrás dele para ver se ganho alguma coisa".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 21, 'Então Geazi correu para alcançar Naamã, que, vendo-o se aproximar, desceu da carruagem para encontrá-lo e perguntou: "Está tudo bem? "', 3, CURRENT_TIMESTAMP, false),
(12, 5, 22, 'Geazi respondeu: "Sim, tudo bem. Mas o meu senhor enviou-me para dizer que dois jovens, discípulos dos profetas, acabaram de chegar, vindos dos montes de Efraim. Por favor, dê-lhes trinta e cinco quilos de prata e duas mudas de roupas finas".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 23, '"Claro", respondeu Naamã, "leve setenta quilos". Ele insistiu com Geazi para que aceitasse e colocou os setenta quilos de prata em duas sacolas, com as duas mudas de roupas, entregando tudo a dois de seus servos, os quais foram à frente de Geazi, levando as sacolas.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 24, 'Quando Geazi chegou à colina onde morava, pegou as sacolas dos servos e guardou-as em casa. Mandou os homens de volta, e eles partiram.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 25, 'Então entrou e apresentou-se ao seu senhor Eliseu. E este perguntou: "Onde você esteve, Geazi? " Geazi respondeu: "Teu servo não foi a lugar algum".', 3, CURRENT_TIMESTAMP, false),
(12, 5, 26, 'Mas Eliseu lhe disse: "Você acha que eu não estava com você em espírito quando o homem desceu da carruagem para encontrar-se com você? Este não era o momento de aceitar prata nem roupas, nem de cobiçar olivais, vinhas, ovelhas, bois, servos e servas.', 3, CURRENT_TIMESTAMP, false),
(12, 5, 27, 'Por isso a lepra de Naamã atingirá você e os seus descendentes para sempre". Então Geazi saiu da presença de Eliseu já leproso, parecido com neve.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 1, 'Os discípulos dos profetas disseram a Eliseu: "Como vês, o lugar onde nos reunimos contigo é pequeno demais para nós.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 2, 'Por que não vamos ao rio Jordão? Lá cada um de nós poderá cortar um tronco para construirmos ali um lugar de reuniões". Eliseu disse: "Podem ir".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 3, 'Então um deles perguntou: "Não gostarias de ir com os teus servos? " "Sim", ele respondeu.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 4, 'E foi com eles. Foram ao Jordão e começaram a derrubar árvores.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 5, 'Quando um deles estava cortando um tronco, o ferro do machado caiu na água. E ele gritou: "Ah, meu senhor, era emprestado! "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 6, 'O homem de Deus perguntou: "Onde caiu? " Quando ele lhe mostrou o lugar, Eliseu cortou um galho e o jogou ali, fazendo o ferro flutuar,', 3, CURRENT_TIMESTAMP, false),
(12, 6, 7, 'e disse: "Pegue-o". O homem esticou o braço e o pegou.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 8, 'Ora, o rei da Síria estava em guerra contra Israel. Depois de deliberar com os seus conselheiros, dizia: "Montarei o meu acampamento em tal lugar".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 9, 'Mas o homem de Deus mandava uma mensagem ao rei de Israel: "Evite passar por tal lugar, pois os arameus estão descendo para lá".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 10, 'Assim, o rei de Israel investigava o lugar indicado pelo homem de Deus. Repetidas vezes Eliseu alertou o rei, que tomava as devidas precauções.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 11, 'Isto enfureceu o rei da Síria, que, convocando seus conselheiros, lhes perguntou: "Vocês não me apontarão qual dos nossos está do lado do rei de Israel? "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 12, 'Respondeu um dos conselheiros: "Nenhum de nós, majestade. É Eliseu, o profeta que está em Israel, que revela ao rei de Israel até as palavras que tu falas em teu quarto".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 13, 'Ordenou o rei: "Descubram onde ele está, para que eu mande capturá-lo". Quando lhe informaram que o profeta estava em Dotã,', 3, CURRENT_TIMESTAMP, false),
(12, 6, 14, 'ele enviou para lá uma grande tropa com cavalos e carros de guerra. Eles chegaram de noite e cercaram a cidade.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 15, 'O servo do homem de Deus levantou-se bem cedo pela manhã e, quando saía, viu que uma tropa com cavalos e carros de guerra havia cercado a cidade. Então ele exclamou: "Ah, meu senhor! O que faremos? "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 16, 'O profeta respondeu: "Não tenha medo. Aqueles que estão conosco são mais numerosos do que eles".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 17, 'E Eliseu orou: "Senhor, abre os olhos dele para que veja". Então o Senhor abriu os olhos do rapaz, que olhou e viu as colinas cheias de cavalos e carros de fogo ao redor de Eliseu.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 18, 'Quando os arameus desceram na direção de Eliseu, ele orou ao Senhor: "Fere estes homens de cegueira". Então ele os feriu de cegueira, conforme Eliseu havia pedido.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 19, 'Eliseu lhes disse: "Este não é o caminho nem esta é a cidade que procuram. Sigam-me, e eu os levarei ao homem que vocês estão procurando". E os guiou até a cidade de Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 20, 'Assim que entraram na cidade, Eliseu disse: "Senhor, abre os olhos destes homens para que possam ver". Então o Senhor abriu-lhes os olhos, e eles viram que estavam dentro de Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 21, 'Quando o rei de Israel os viu, perguntou a Eliseu: "Devo matá-los, meu pai? Devo matá-los? "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 22, 'Ele respondeu: "Não! Costumas matar prisioneiros que capturas com a tua espada e o teu arco? Manda-lhes servir comida e bebida e deixa que voltem ao seu senhor".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 23, 'Então preparou-lhes um grande banquete e, terminando eles de comer e beber, mandou-os de volta para o seu senhor. Assim, as tropas da Síria pararam de invadir o território de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 24, 'Algum tempo depois, Ben-Hadade, rei da Síria, mobilizou todo o seu exército e cercou Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 25, 'O cerco durou tanto e causou tamanha fome que uma cabeça de jumento chegou a valer oitenta peças de prata, e uma caneca de esterco de pomba, cinco peças de prata.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 26, 'Um dia, quando o rei de Israel inspecionava os muros da cidade, uma mulher gritou para ele: "Socorro, majestade! "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 27, 'O rei respondeu: "Se o Senhor não socorrê-la, como poderei ajudá-la? Acaso há trigo na eira ou vinho no lagar? "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 28, 'Contudo ele perguntou: "Qual é o problema? " Ela respondeu: "Esta mulher me disse: ‘Vamos comer o seu filho hoje, e amanhã comeremos o meu’.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 29, 'Então cozinhamos o meu filho e o comemos. No dia seguinte eu disse a ela que era a vez de comermos o seu filho, mas ela o havia escondido".', 3, CURRENT_TIMESTAMP, false),
(12, 6, 30, 'Quando o rei ouviu as palavras da mulher, rasgou as próprias vestes. Como estava sobre os muros, o povo viu que ele estava usando pano de saco por baixo, junto ao corpo.', 3, CURRENT_TIMESTAMP, false),
(12, 6, 31, 'E ele disse: "Deus me castigue com todo rigor, se a cabeça de Eliseu, filho de Safate, continuar hoje sobre seus ombros! "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 32, 'Ora, Eliseu estava sentado em sua casa, reunido com as autoridades de Israel. O rei havia mandado um mensageiro à sua frente, mas, antes que ele chegasse, Eliseu disse às autoridades: "Aquele assassino mandou alguém para cortar-me a cabeça? Quando o mensageiro chegar, fechem a porta e mantenham-na trancada. Vocês não estão ouvindo os passos do seu senhor que vem atrás dele? "', 3, CURRENT_TIMESTAMP, false),
(12, 6, 33, 'Enquanto ainda lhes falava, o mensageiro chegou. Na mesma hora o rei disse: "Esta desgraça vem do Senhor. Por que devo ainda ter esperança no Senhor? "', 3, CURRENT_TIMESTAMP, false),
(12, 7, 1, 'Eliseu respondeu: "Ouçam a palavra do Senhor! Assim diz o Senhor: Amanhã, por volta desta hora, na porta de Samaria, tanto uma medida de farinha como duas medidas de cevada serão vendidas por uma peça de prata".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 2, 'O oficial, em cujo braço o rei estava se apoiando, disse ao homem de Deus: "Ainda que o Senhor abrisse as comportas do céu, será que isso poderia acontecer? " Mas Eliseu advertiu: "Você o verá com os próprios olhos, mas não comerá coisa alguma! "', 3, CURRENT_TIMESTAMP, false),
(12, 7, 3, 'Havia quatro leprosos junto à porta da cidade. Eles disseram uns aos outros: "Por que ficar aqui esperando a morte?', 3, CURRENT_TIMESTAMP, false),
(12, 7, 4, 'Se resolvermos entrar na cidade, morreremos de fome, mas se ficarmos aqui, também morreremos. Vamos, pois, ao acampamento dos arameus para nos render. Se eles nos pouparem, viveremos; se nos matarem, morreremos".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 5, 'Ao anoitecer, eles foram ao acampamento dos arameus. Quando chegaram às imediações do acampamento, não havia ninguém ali,', 3, CURRENT_TIMESTAMP, false),
(12, 7, 6, 'pois o Senhor tinha feito os arameus ouvirem o ruído de um grande exército com cavalos e carros de guerra, de modo que disseram uns aos outros: "Ouçam, o rei de Israel contratou os reis dos hititas e dos egípcios para nos atacar! "', 3, CURRENT_TIMESTAMP, false),
(12, 7, 7, 'Então, para salvar suas vidas, fugiram ao anoitecer, abandonando tendas, cavalos e jumentos, deixando o acampamento como estava.', 3, CURRENT_TIMESTAMP, false),
(12, 7, 8, 'Tendo chegado às imediações do acampamento os leprosos entraram numa das tendas. Comeram e beberam; pegaram prata, ouro e roupas e saíram para esconder tudo. Depois voltaram e entraram noutra tenda, pegaram o que quiseram e esconderam isso também.', 3, CURRENT_TIMESTAMP, false),
(12, 7, 9, 'Então disseram uns aos outros: "Não estamos agindo certo. Este é um dia de boas notícias, e não podemos ficar calados. Se esperarmos até o amanhecer, seremos castigados. Vamos imediatamente contar tudo no palácio do rei".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 10, 'Então foram e chamaram as sentinelas da porta da cidade e lhes contaram: "Entramos no acampamento arameu, e não vimos nem ouvimos ninguém. Havia apenas cavalos e jumentos amarrados, e tendas abandonadas".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 11, 'As sentinelas da porta proclamaram a notícia, e ela foi anunciada dentro do palácio.', 3, CURRENT_TIMESTAMP, false),
(12, 7, 12, 'O rei se levantou de noite e disse aos seus conselheiros: "Eu lhes explicarei o que os arameus planejaram. Como sabem que estamos passando fome, deixaram o acampamento e se esconderam no campo, pensando: ‘Com certeza eles sairão, e então os pegaremos vivos e entraremos na cidade’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 13, 'Um de seus conselheiros respondeu: "Manda que alguns homens apanhem cinco dos cavalos que restam na cidade. O destino desses homens será o mesmo de todos os israelitas que ficarem, sim, como toda esta multidão condenada. Por isso vamos enviá-los para descobrir o que aconteceu".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 14, 'Assim que prepararam dois carros de guerra com seus cavalos, o rei os enviou atrás do exército arameu, ordenando aos condutores: "Vão e descubram o que aconteceu".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 15, 'Eles seguiram as pegadas do exército até o Jordão e encontraram todo o caminho cheio de roupas e armas que os arameus haviam deixado para trás enquanto fugiam. Os mensageiros voltaram e relataram tudo ao rei.', 3, CURRENT_TIMESTAMP, false),
(12, 7, 16, 'Então o povo saiu e saqueou o acampamento dos arameus. Assim, tanto uma medida de farinha como duas medidas de cevada passaram a ser vendidas por uma peça de prata, conforme o Senhor tinha dito.', 3, CURRENT_TIMESTAMP, false),
(12, 7, 17, 'Ora, o rei havia posto o oficial em cujo braço tinha se apoiado como encarregado da porta da cidade, mas quando o povo saiu, atropelou-o junto à porta, e ele morreu, conforme o homem de Deus havia predito quando o rei foi à sua casa.', 3, CURRENT_TIMESTAMP, false),
(12, 7, 18, 'Aconteceu conforme o homem de Deus dissera ao rei: "Amanhã, por volta desta hora, na porta de Samaria, tanto uma medida de farinha como duas medidas de cevada serão vendidas por uma peça de prata".', 3, CURRENT_TIMESTAMP, false),
(12, 7, 19, 'O oficial tinha contestado o homem de Deus perguntando: "Ainda que o Senhor abrisse as comportas do céu, será que isso poderia acontecer? " O homem de Deus havia respondido: "Você verá com os próprios olhos, mas não comerá coisa alguma! "', 3, CURRENT_TIMESTAMP, false),
(12, 7, 20, 'E foi exatamente isso que lhe aconteceu, pois o povo o pisoteou junto à porta da cidade, e ele morreu.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 1, 'Eliseu tinha prevenido a mãe do menino que ele havia ressuscitado: "Saia do país com sua família e vá morar onde puder, pois o Senhor determinou uma fome nesta terra, que durará sete anos".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 2, 'A mulher seguiu o conselho do homem de Deus, partiu com sua família e passou sete anos na terra dos filisteus.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 3, 'Ao final dos sete anos ela voltou a Israel e foi fazer um apelo ao rei para readquirir sua casa e sua propriedade.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 4, 'O rei estava conversando com Geazi, servo do homem de Deus, e disse: "Conte-me todos os prodígios que Eliseu tem feito".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 5, 'Enquanto Geazi contava ao rei como Eliseu havia ressuscitado o menino, a própria mãe do menino que Eliseu tinha ressuscitado, chegou para apresentar sua petição ao rei para readquirir sua casa e sua propriedade. Geazi exclamou: "Esta é a mulher, ó rei, meu senhor, e este é o filho dela, a quem Eliseu ressuscitou".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 6, 'O rei pediu que ela contasse o ocorrido, e ela confirmou os fatos. Então ele designou um funcionário para cuidar do caso dela e lhe ordenou: "Devolva tudo o que lhe pertencia, inclusive toda a renda das colheitas, desde que ela saiu do país até hoje".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 7, 'Certa ocasião, Eliseu foi a Damasco. Ben-Hadade, rei da Síria, estava doente. Quando disseram ao rei: "O homem de Deus está na cidade",', 3, CURRENT_TIMESTAMP, false),
(12, 8, 8, 'ele ordenou a Hazael: "Vá encontrar-se com o homem de Deus e leve-lhe um presente. Consulte o Senhor por meio dele: pergunte-lhe se vou me recuperar desta doença".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 9, 'Hazael foi encontrar-se com Eliseu, levando consigo de tudo o que havia de melhor em Damasco, um presente carregado por quarenta camelos. Ao chegar diante dele Hazael disse: "Teu filho Ben-Hadade, rei da Síria, enviou-me para perguntar se ele vai recuperar-se de sua doença".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 10, 'Eliseu respondeu: "Vá e diga-lhe: ‘Com certeza te recuperarás’, no entanto o Senhor me revelou que de fato ele vai morrer".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 11, 'Eliseu ficou olhando fixamente para Hazael até deixá-lo constrangido. Então o homem de Deus começou a chorar.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 12, 'E perguntou Hazael: "Por que meu senhor está chorando? " Ele respondeu: "Porque sei das coisas terríveis que você fará aos israelitas. Você incendiará suas fortalezas, matará seus jovens à espada, esmagará as crianças e rasgará o ventre de suas mulheres grávidas".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 13, 'Hazael disse: "Como poderia teu servo, que não passa de um cão, realizar algo assim? " Respondeu Eliseu: "O Senhor me mostrou que você se tornará rei da Síria".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 14, 'Então Hazael saiu dali e voltou para seu senhor. Quando Ben-Hadade perguntou: "O que Eliseu lhe disse? ", Hazael respondeu: "Ele me falou que certamente te recuperarás".', 3, CURRENT_TIMESTAMP, false),
(12, 8, 15, 'Mas, no dia seguinte, ele apanhou um cobertor, encharcou-o e com ele sufocou o rei, até matá-lo. E assim Hazael foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 16, 'No quinto ano de Jorão, filho de Acabe, rei de Israel, sendo Josafá rei de Judá, Jeorão, seu filho, começou a reinar em Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 17, 'Ele tinha trinta e dois anos de idade quando começou a reinar, e reinou oito anos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 18, 'Andou nos caminhos dos reis de Israel, como a família de Acabe havia feito, pois se casou com uma filha de Acabe. E fez o que o Senhor reprova.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 19, 'Entretanto, por amor ao seu servo Davi, o Senhor não quis destruir Judá. Ele havia prometido manter para sempre um descendente de Davi no trono.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 20, 'Nos dias de Jeorão, os edomitas rebelaram-se contra o domínio de Judá, proclamando seu próprio rei.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 21, 'Por isso, Jeorão foi a Zair com todos os seus carros de guerra. Lá os edomitas cercaram a ele e aos chefes dos seus carros de guerra, mas ele os atacou de noite e rompeu o cerco inimigo, e seu exército conseguiu fugir para casa.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 22, 'E até hoje Edom continua independente de Judá. Nessa mesma época, a cidade de Libna também tornou-se independente.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 23, 'Os demais acontecimentos do reinado de Jeorão e todas as suas realizações, estão escritos nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 24, 'Jeorão descansou com seus antepassados e foi sepultado com eles na cidade de Davi. E seu filho Acazias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 25, 'No décimo segundo ano do reinado de Jorão, filho de Acabe, rei de Israel, Acazias, filho de Jeorão, rei de Judá, começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 26, 'Ele tinha vinte e dois anos de idade quando começou a reinar, e reinou um ano em Jerusalém. O nome de sua mãe era Atalia, neta de Onri, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 27, 'Ele andou nos caminhos da família de Acabe e fez o que o Senhor reprova, como a família de Acabe havia feito, pois casou-se com uma mulher da família de Acabe.', 3, CURRENT_TIMESTAMP, false),
(12, 8, 28, 'Acazias aliou-se a Jorão, filho de Acabe, e saiu à guerra contra Hazael, rei da Síria, em Ramote-Gileade. Jorão foi ferido', 3, CURRENT_TIMESTAMP, false),
(12, 8, 29, 'e voltou a Jezreel para recuperar-se dos ferimentos sofridos em Ramote, na batalha contra Hazael, rei da Síria. Depois Acazias, rei de Judá, foi a Jezreel visitar Jorão, que se recuperava de seus ferimentos.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 1, 'Enquanto isso o profeta Eliseu chamou um dos discípulos dos profetas e lhe disse: "Ponha a capa por dentro do cinto, pegue este frasco de óleo e vá a Ramote-Gileade.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 2, 'Quando lá chegar, procure Jeú, filho de Josafá e neto de Ninsi. Dirija-se a ele e leve-o para uma sala longe dos seus companheiros.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 3, 'Depois pegue o frasco, derrame o óleo sobre a cabeça dele e declare: ‘Assim diz o Senhor: Eu o estou ungindo rei sobre Israel’. Então abra a porta e fuja sem demora! "', 3, CURRENT_TIMESTAMP, false),
(12, 9, 4, 'Então o jovem profeta foi a Ramote-Gileade.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 5, 'Ao chegar, encontrou os comandantes do exército reunidos e disse: "Trago uma mensagem para ti, comandante". "Para qual de nós? ", perguntou Jeú. Ele respondeu: "Para ti, comandante".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 6, 'Jeú levantou-se e entrou na casa. Então o jovem profeta derramou o óleo na cabeça de Jeú e declarou-lhe: "Assim diz o Senhor, o Deus de Israel: ‘Eu o estou ungindo rei de Israel, o povo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 7, 'Você dará fim à família de Acabe, seu senhor, e assim eu vingarei o sangue de meus servos, os profetas, e o sangue de todos os servos do Senhor, derramado por Jezabel.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 8, 'Toda a família de Acabe perecerá. Eliminarei todos os de sexo masculino de sua família em Israel, seja escravo seja livre.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 9, 'Tratarei a família de Acabe como tratei a de Jeroboão, filho de Nebate, e a de Baasa, filho de Aías.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 10, 'E Jezabel será devorada por cães num terreno em Jezreel, e ninguém a sepultará’ ". Então ele abriu a porta e saiu correndo.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 11, 'Quando Jeú voltou para junto dos outros oficiais do rei, um deles lhe perguntou: "Está tudo bem? O que esse louco queria com você? " Jeú respondeu: "Vocês conhecem essa gente e as coisas que dizem".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 12, 'Mas insistiram: "Não nos engane! Conte-nos o que ele disse". Então Jeú contou: "Ele me disse o seguinte: ‘Assim diz o Senhor: Eu o estou ungindo rei sobre Israel’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 13, 'Imediatamente eles pegaram os seus mantos e os estenderam sobre os degraus diante dele. Em seguida tocaram a trombeta e gritaram: "Jeú é rei! "', 3, CURRENT_TIMESTAMP, false),
(12, 9, 14, 'Então Jeú, filho de Josafá e neto de Ninsi, começou uma conspiração contra o rei Jorão, na época em que este defendeu, com todo Israel, Ramote-Gileade contra Hazael, rei da Síria.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 15, 'O rei Jorão tinha voltado a Jezreel para recuperar-se dos ferimentos sofridos na batalha contra Hazael, rei da Síria. Jeú propôs: "Se vocês me apóiam, não deixem ninguém sair escondido da cidade para nos denunciar em Jezreel".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 16, 'Então ele subiu em seu carro e foi para Jezreel, porque Jorão estava lá se recuperando; e Acazias, rei de Judá, tinha ido visitá-lo.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 17, 'Quando a sentinela que estava na torre de vigia de Jezreel percebeu a tropa de Jeú se aproximando, gritou: "Estou vendo uma tropa! " Jorão ordenou: "Chame um cavaleiro e envie-o ao encontro deles para perguntar se eles vêm em paz".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 18, 'O cavaleiro foi ao encontro de Jeú e disse: "O rei pergunta: ‘Vocês vêm em paz? ’ " Jeú respondeu: "Não me venha falar em paz. Saia da minha frente". A sentinela relatou: "O mensageiro chegou a eles, mas não está voltando".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 19, 'Então o rei enviou um segundo cavaleiro. Quando chegou a eles disse: "O rei pergunta: ‘Vocês vêm em paz? ’ " Jeú respondeu: "Não me venha falar em paz. Saia da minha frente".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 20, 'A sentinela relatou: "Ele chegou a eles, mas também não está voltando". E acrescentou: "O jeito do chefe da tropa guiar o carro é como o de Jeú, neto de Ninsi; dirige como louco".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 21, 'Jorão ordenou que preparassem seu carro de guerra. Assim que ficou pronto, Jorão, rei de Israel, e Acazias, rei de Judá, saíram, cada um em seu carro, ao encontro de Jeú. Eles o encontraram na propriedade que havia pertencido a Nabote, de Jezreel.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 22, 'Quando Jorão viu Jeú, perguntou: "Você vem em paz, Jeú? " Jeú respondeu: "Como pode haver paz, enquanto continua toda a idolatria e as feitiçarias de sua mãe Jezabel? "', 3, CURRENT_TIMESTAMP, false),
(12, 9, 23, 'Jorão deu meia-volta e fugiu, gritando para Acazias: "Traição, Acazias! "', 3, CURRENT_TIMESTAMP, false),
(12, 9, 24, 'Então Jeú disparou seu arco com toda força e atingiu Jorão nas costas. A flecha atravessou-lhe o coração e ele caiu morto.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 25, 'Jeú disse a Bidcar, seu oficial: "Pegue o cadáver e jogue-o nesta propriedade que pertencia a Nabote, de Jezreel. Lembre-se da advertência que o Senhor proferiu contra Acabe, pai dele, quando juntos acompanhávamos sua comitiva. Ele disse:', 3, CURRENT_TIMESTAMP, false),
(12, 9, 26, '‘Ontem, vi o sangue de Nabote e o sangue dos seus filhos, declara o Senhor, e com certeza farei você pagar por isso nesta mesma propriedade, declara o Senhor’. Agora, então, pegue o cadáver e jogue-o nesta propriedade, conforme a palavra do Senhor".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 27, 'Vendo isso, Acazias, rei de Judá, fugiu na direção de Bete-Hagã. Mas Jeú o perseguiu, gritando: "Matem-no também! " Eles o atingiram em seu carro de guerra na subida para Gur, perto de Ibleã, mas ele conseguiu refugiar-se em Megido, onde morreu.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 28, 'Seus oficiais o levaram até Jerusalém e o sepultaram com seus antepassados em seu túmulo, na cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 29, 'Acazias havia se tornado rei de Judá no décimo primeiro ano de Jorão, filho de Acabe.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 30, 'Em seguida Jeú entrou em Jezreel. Ao saber disso, Jezabel pintou os olhos, arrumou o cabelo e ficou olhando de uma janela do palácio.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 31, 'Quando Jeú passou pelo portão, ela gritou: "Como vai, Zinri, assassino do seu senhor? "', 3, CURRENT_TIMESTAMP, false),
(12, 9, 32, 'Ele ergueu os olhos para a janela e gritou: "Quem de vocês está do meu lado? " Dois ou três funcionários olharam para ele.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 33, 'Então Jeú ordenou: "Joguem essa mulher para baixo! " Eles a jogaram e o sangue dela espirrou na parede e nos cavalos, e Jeú a atropelou.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 34, 'Jeú entrou, comeu, bebeu e ordenou: "Peguem aquela maldita e sepultem-na, afinal era filha de rei".', 3, CURRENT_TIMESTAMP, false),
(12, 9, 35, 'Mas, quando foram sepultá-la, só encontraram o crânio, os pés e as mãos.', 3, CURRENT_TIMESTAMP, false),
(12, 9, 36, 'Então voltaram e contaram isso a Jeú, que disse: "Cumpriu-se a palavra do Senhor, anunciada por meio do seu servo Elias, o tesbita: Num terreno em Jezreel cães devorarão a carne de Jezabel,', 3, CURRENT_TIMESTAMP, false),
(12, 9, 37, 'os seus restos mortais serão espalhados num terreno em Jezreel, como esterco no campo, de modo que ninguém será capaz de dizer: ‘Esta é Jezabel’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 1, 'Ora, viviam em Samaria setenta descendentes de Acabe. Jeú escreveu uma carta e a enviou a Samaria, aos líderes da cidade, às autoridades e aos tutores dos descendentes de Acabe. A carta dizia:', 3, CURRENT_TIMESTAMP, false),
(12, 10, 2, '"Assim que receberem esta carta, vocês que cuidam dos filhos do rei, e que têm carros de guerra e cavalos, uma cidade fortificada e armas,', 3, CURRENT_TIMESTAMP, false),
(12, 10, 3, 'escolham o melhor e o mais capaz dos filhos do rei e coloquem-no no trono de seu pai. E lutem pela dinastia de seu senhor".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 4, 'Eles, porém, estavam aterrorizados e disseram: "Se dois reis não puderam enfrentá-lo, como poderemos nós? "', 3, CURRENT_TIMESTAMP, false),
(12, 10, 5, 'Por isso o administrador do palácio, o governador da cidade, as autoridades e os tutores enviaram esta mensagem a Jeú: "Somos teus servos e faremos tudo o que exigires de nós. Não proclamaremos ninguém como rei. Faze o que achares melhor".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 6, 'Então Jeú escreveu-lhes uma segunda carta que dizia: "Se vocês estão do meu lado e estão dispostos a obedecer-me, tragam-me as cabeças dos descendentes de seu senhor a Jezreel, amanhã a esta hora". Os setenta descendentes de Acabe estavam sendo criados pelas autoridades da cidade.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 7, 'Logo que receberam a carta, pegaram todos os setenta, os decapitaram, colocaram as cabeças em cestos e as enviaram a Jeú, em Jezreel.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 8, 'Ao ser informado de que tinham trazido as cabeças, Jeú ordenou: "Façam com elas dois montes junto à porta da cidade, para que fiquem expostas lá até amanhã".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 9, 'Na manhã seguinte Jeú saiu e, diante de todo o povo, declarou: "Vocês são inocentes! Fui eu que conspirei contra meu senhor e o matei, mas quem matou todos estes?', 3, CURRENT_TIMESTAMP, false),
(12, 10, 10, 'Saibam, então, que não deixará de se cumprir uma só palavra que o Senhor falou contra a família de Acabe. O Senhor fez o que prometeu por meio de seu servo Elias".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 11, 'Então Jeú matou todos os que restavam da família de Acabe em Jezreel, bem como todos os seus aliados influentes, os seus amigos pessoais e os seus sacerdotes, não lhe deixando sobrevivente algum.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 12, 'Depois Jeú partiu para Samaria. Em Bete-Equede dos Pastores', 3, CURRENT_TIMESTAMP, false),
(12, 10, 13, 'encontrou alguns parentes de Acazias, rei de Judá, e perguntou: "Quem são vocês? " Eles responderam: "Somos parentes de Acazias e estamos indo visitar as famílias do rei e da rainha-mãe".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 14, 'Então Jeú ordenou aos seus soldados: "Peguem-nos vivos! " Então os pegaram vivos e os mataram junto ao poço de Bete-Equede. Eram quarenta e dois homens, e nenhum deles foi deixado vivo.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 15, 'Saindo dali, Jeú encontrou Jonadabe, filho de Recabe, que tinha ido falar com ele. Depois de saudá-lo Jeú perguntou: "Você está de acordo com o que estou fazendo? " Jonadabe respondeu: "Estou". E disse Jeú: "Então, dê-me a mão". Jonadabe estendeu-lhe a mão, e Jeú o ajudou a subir no carro', 3, CURRENT_TIMESTAMP, false),
(12, 10, 16, 'e disse-lhe: "Venha comigo e veja o meu zelo pelo Senhor". Então ele o levou em seu carro.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 17, 'Quando Jeú chegou a Samaria, matou todos os que restavam da família de Acabe na cidade; ele os exterminou, conforme a palavra que o Senhor tinha dito a Elias.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 18, 'Jeú reuniu todo o povo e declarou: "Acabe não cultuou ao deus Baal o bastante; eu, Jeú, o cultuarei muito mais.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 19, 'Por isso convoquem todos os profetas de Baal, todos os seus ministros e todos os seus sacerdotes. Ninguém deverá faltar, pois oferecerei um grande sacrifício a Baal. Quem não vier, morrerá". Mas Jeú estava agindo traiçoeiramente, a fim de exterminar os ministros de Baal.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 20, 'Então Jeú ordenou: "Convoquem uma assembléia em honra de Baal". Foi feita a proclamação', 3, CURRENT_TIMESTAMP, false),
(12, 10, 21, 'e ele enviou mensageiros por todo o Israel. Todos os ministros de Baal vieram; nem um deles faltou. Eles se reuniram no templo de Baal, que ficou completamente lotado.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 22, 'E Jeú disse ao encarregado das vestes cultuais: "Traga os mantos para todos os ministros de Baal". E ele os trouxe.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 23, 'Depois Jeú entrou no templo com Jonadabe, filho de Recabe, e disse aos ministros de Baal: "Olhem em volta e certifiquem-se de que nenhum servo do Senhor está aqui com vocês, mas somente ministros de Baal".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 24, 'E eles se aproximaram para oferecer sacrifícios e holocaustos. Jeú havia posto oitenta homens do lado de fora, fazendo-lhes esta advertência: "Se um de vocês deixar escapar um só dos homens que estou entregando a vocês, será a sua vida pela dele".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 25, 'Logo que Jeú terminou de oferecer o holocausto, ordenou aos guardas e oficiais: "Entrem e matem a todos! Não deixem ninguém escapar! " E eles os mataram ao fio da espada, jogaram os corpos para fora e depois entraram no santuário interno do templo de Baal.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 26, 'Levaram a coluna sagrada para fora do templo de Baal e a queimaram.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 27, 'Assim destruíram a coluna sagrada de Baal e demoliram o seu templo, e até hoje o local tem sido usado como latrina.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 28, 'Assim, Jeú eliminou a adoração de Baal em Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 29, 'No entanto, não se afastou dos pecados de Jeroboão, filho de Nebate, pois levou Israel a cometer o pecado de adorar os bezerros de ouro em Betel e em Dã.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 30, 'E o Senhor disse a Jeú: "Como você executou corretamente o que eu aprovo, fazendo com a família de Acabe tudo o que eu queria, seus descendentes ocuparão o trono de Israel até a quarta geração".', 3, CURRENT_TIMESTAMP, false),
(12, 10, 31, 'Entretanto, Jeú não se preocupou em obedecer de todo o coração à lei do Senhor, Deus de Israel, nem se afastou dos pecados que Jeroboão levou Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 32, 'Naqueles dias, o Senhor começou a reduzir o tamanho de Israel. O rei Hazael conquistou todo o território israelita', 3, CURRENT_TIMESTAMP, false),
(12, 10, 33, 'a leste do Jordão, incluindo toda a terra de Gileade. Conquistou desde Aroer, junto à garganta do Arnom, até Basã, passando por Gileade, terras das tribos de Gade, de Rúben e de Manassés.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 34, 'Os demais acontecimentos do reinado de Jeú, tudo o que fez e todas as suas realizações, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 35, 'Jeú descansou com seus antepassados e foi sepultado em Samaria. Seu filho Jeoacaz foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 10, 36, 'Reinou Jeú vinte e oito anos sobre Israel, em Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 1, 'Quando Atalia, mãe de Acazias, soube que seu filho estava morto, mandou matar toda a família real.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 2, 'Mas Jeoseba, filha do rei Jeorão e irmã de Acazias, pegou Joás, um dos filhos do rei que iam ser assassinados, e o colocou num quarto, junto com a sua ama, para escondê-lo de Atalia; assim ele não foi morto.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 3, 'Seis anos ele ficou escondido com ela no templo do Senhor, enquanto Atalia governava o país.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 4, 'No sétimo ano, o sacerdote Joiada mandou chamar à sua presença no templo do Senhor os líderes dos batalhões de cem dos cários e dos guardas. E fez um acordo com eles, fazendo-os jurar no templo do Senhor. Então lhes mostrou o filho do rei', 3, CURRENT_TIMESTAMP, false),
(12, 11, 5, 'e lhes ordenou: "Vocês vão fazer o seguinte: Quando entrarem de serviço no sábado, uma companhia ficará de guarda no palácio real,', 3, CURRENT_TIMESTAMP, false),
(12, 11, 6, 'outra, na porta de Sur e a terceira, na porta atrás das outras companhias. Elas montarão guarda no templo por turnos.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 7, 'As outras duas companhias que normalmente não estão de serviço no sábado ficarão de guarda no templo, para proteger o rei.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 8, 'Posicionem-se ao redor do rei, de armas na mão. Matem todo o que se aproximar de suas fileiras. Acompanhem o rei aonde quer que ele for".', 3, CURRENT_TIMESTAMP, false),
(12, 11, 9, 'Os líderes dos batalhões de cem fizeram como o sacerdote Joiada havia ordenado. Cada um levou seus soldados, tanto os que estavam entrando de serviço no sábado como os que estavam saindo, ao sacerdote Joiada.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 10, 'Então ele deu aos líderes dos batalhões de cem, as lanças e os escudos que haviam pertencido ao rei Davi, e que estavam no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 11, 'Os guardas, todos de arma na mão, posicionaram-se em volta do rei, perto do altar e do templo, desde o lado sul até o lado norte do templo.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 12, 'Depois Joiada trouxe para fora o filho do rei, colocou nele a coroa e entregou-lhe uma cópia da aliança. Então o proclamaram rei ungindo-o, e o povo aplaudia e gritava: "Viva o rei! "', 3, CURRENT_TIMESTAMP, false),
(12, 11, 13, 'Quando Atalia ouviu o barulho dos guardas e do povo, foi ao templo do Senhor, onde estava o povo.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 14, 'Lá ela viu o rei, conforme o costume, de pé junto à coluna. Os oficiais e os tocadores de corneta estavam ao lado do rei, e todo o povo se alegrava ao som das cornetas. Então, Atalia rasgou suas vestes e gritou: "Traição! Traição! "', 3, CURRENT_TIMESTAMP, false),
(12, 11, 15, 'O sacerdote Joiada ordenou aos líderes dos batalhões de cem que estavam no comando das tropas: "Levem-na para fora por entre as fileiras, e matem à espada todo que a seguir". Pois o sacerdote dissera: "Ela não será morta no templo do Senhor".', 3, CURRENT_TIMESTAMP, false),
(12, 11, 16, 'Então eles a prenderam e a levaram ao lugar onde os cavalos entram no terreno do palácio, e lá a mataram.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 17, 'E Joiada fez uma aliança entre o Senhor, o rei e o povo, para que fossem o povo do Senhor. Também fez um acordo entre o rei e o povo.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 18, 'Então todo o povo foi ao templo de Baal e o derrubou. Despedaçaram os altares e os ídolos, e mataram Matã, sacerdote de Baal, em frente dos altares. E o sacerdote Joiada colocou guardas no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 19, 'Levou consigo os líderes dos batalhões de cem dos cários, os guardas e todo o povo e, juntos, conduziram o rei do templo ao palácio, passando pela porta da guarda. O rei então ocupou seu lugar no trono real,', 3, CURRENT_TIMESTAMP, false),
(12, 11, 20, 'e todo o povo se alegrou. E a cidade acalmou-se depois que Atalia foi morta à espada no palácio.', 3, CURRENT_TIMESTAMP, false),
(12, 11, 21, 'Joás tinha sete anos de idade quando começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 1, 'No sétimo ano do reinado de Jeú, Joás começou a reinar, e reinou quarenta anos em Jerusalém. O nome de sua mãe era Zíbia; ela era de Berseba.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 2, 'Joás fez o que o Senhor aprova durante todos os anos em que o sacerdote Joiada o orientou.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 3, 'Contudo, os altares idólatras não foram derrubados; o povo continuava a oferecer sacrifícios e a queimar incenso neles.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 4, 'Joás ordenou aos sacerdotes: "Reúnam toda a prata trazida como dádivas sagradas ao templo do Senhor: a prata recolhida no recenseamento, a prata recebida de votos pessoais e a que foi trazida voluntariamente ao templo.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 5, 'Cada sacerdote recolha a prata de um dos tesoureiros para que seja usada na reforma do templo".', 3, CURRENT_TIMESTAMP, false),
(12, 12, 6, 'Contudo, no vigésimo terceiro ano do reinado de Joás, os sacerdotes ainda não tinham feito as reformas.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 7, 'Por isso, o rei Joás chamou o sacerdote Joiada e os outros sacerdotes e lhes perguntou: "Por que vocês não estão fazendo as reformas no templo? Não recolham mais prata com seus tesoureiros, mas deixem-na para as reformas".', 3, CURRENT_TIMESTAMP, false),
(12, 12, 8, 'Os sacerdotes concordaram em não mais receber nenhuma prata do povo e em não serem mais os encarregados dessas reformas.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 9, 'Então o sacerdote Joiada pegou uma caixa, fez um furo na tampa e colocou-a ao lado do altar, à direita de quem entra no templo do Senhor. Os sacerdotes que guardavam a entrada colocavam na caixa toda a prata trazida ao templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 10, 'Sempre que havia uma grande quantidade de prata na caixa, o secretário real e o sumo sacerdote vinham, pesavam a prata trazida ao templo do Senhor e a colocavam em sacolas.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 11, 'Depois de pesada, entregavam a prata aos supervisores do trabalho no templo. Assim pagavam aqueles que trabalhavam no templo do Senhor: os carpinteiros e construtores,', 3, CURRENT_TIMESTAMP, false),
(12, 12, 12, 'os pedreiros e cortadores de pedras. Também compravam madeira e pedras lavradas para os consertos no templo do Senhor e cobriam todas as outras despesas.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 13, 'A prata trazida ao templo não era utilizada na confecção de bacias de prata, cortadores de pavio, bacias para aspersão, cornetas ou quaisquer outros utensílios de ouro ou prata para o templo do Senhor;', 3, CURRENT_TIMESTAMP, false),
(12, 12, 14, 'era usada como pagamento dos trabalhadores, que a empregavam para o reparo do templo.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 15, 'Não se exigia prestação de contas dos que pagavam os trabalhadores, pois agiam com honestidade.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 16, 'Mas a prata das ofertas pela culpa e das ofertas pelo pecado não era levada ao templo do Senhor, pois pertencia aos sacerdotes.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 17, 'Nessa época, Hazael, rei da Síria, atacou Gate e a conquistou. Depois decidiu atacar Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 18, 'Então Joás, rei de Judá, apanhou todos os objetos consagrados por seus antepassados Josafá, Jeorão e Acazias, reis de Judá, e os que ele mesmo havia consagrado e todo o ouro encontrado no depósito do templo do Senhor e do palácio real, e enviou tudo a Hazael, rei da Síria, que, assim, desistiu de atacar Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 19, 'Os demais acontecimentos do reinado de Joás, e as suas realizações, estão todos escritos no livro dos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 20, 'Dois de seus oficiais conspiraram contra ele e o assassinaram em Bete-Milo, no caminho que desce para Sila.', 3, CURRENT_TIMESTAMP, false),
(12, 12, 21, 'Os oficiais que o assassinaram foram Jozabade, filho de Simeate, e Jeozabade, filho de Somer. Ele morreu e foi sepultado junto aos seus antepassados na cidade de Davi. E seu filho Amazias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 1, 'No vigésimo terceiro ano do reinado de Joás, filho de Acazias, rei de Judá, Jeoacaz, filho de Jeú, tornou-se rei de Israel em Samaria, e reinou dezessete anos.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 2, 'E fez o que o Senhor reprova, seguindo os pecados que Jeroboão, filho de Nebate, levara Israel a cometer; e não se afastou deles.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 3, 'Por isso a ira do Senhor se acendeu contra Israel, e por longo tempo ele os manteve sob o poder de Hazael, rei da Síria, e de seu filho Ben-Hadade.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 4, 'Então Jeoacaz buscou o favor do Senhor, e este o ouviu, pois viu o quanto o rei da Síria oprimia Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 5, 'O Senhor providenciou um libertador para Israel, e eles escaparam do poder da Síria. Assim os israelitas moraram em suas casas como anteriormente.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 6, 'Mas continuaram a praticar os pecados que a dinastia de Jeroboão havia levado Israel a cometer, permanecendo neles. Inclusive a coluna sagrada permanecia de pé em Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 7, 'Nada havia sobrado do exército de Jeoacaz, com exceção de cinqüenta cavaleiros, dez carros de guerra e dez mil soldados de infantaria, pois o rei da Síria havia destruído o restante, reduzindo-o a pó.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 8, 'Os demais acontecimentos do reinado de Jeoacaz, os seus feitos e tudo o que realizou, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 9, 'Jeoacaz descansou com seus antepassados e foi sepultado em Samaria. Seu filho Jeoás foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 10, 'No trigésimo sétimo ano do reinado de Joás, rei de Judá, Jeoás, filho de Jeoacaz, tornou-se rei de Israel em Samaria, e reinou dezesseis anos.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 11, 'Ele fez o que o Senhor reprova e não se desviou de nenhum dos pecados que Jeroboão, filho de Nebate, levara Israel a cometer; antes permaneceu neles.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 12, 'Os demais acontecimentos do reinado de Jeoás, os seus feitos e as suas realizações, inclusive sua guerra contra Amazias, rei de Judá, estão escritos no livro dos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 13, 'Jeoás descansou com seus antepassados, e Jeroboão o sucedeu no trono. Jeoás foi sepultado com os reis de Israel, em Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 14, 'Ora, Eliseu estava sofrendo da doença da qual morreria. Então Jeoás, rei de Israel, foi visitá-lo e, curvado sobre ele, chorou gritando: "Meu pai! Meu pai! Tu és como os carros e os cavaleiros de Israel! "', 3, CURRENT_TIMESTAMP, false),
(12, 13, 15, 'E Eliseu lhe disse: "Traga um arco e algumas flechas"; e ele assim fez.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 16, '"Pegue o arco em suas mãos", disse ao rei de Israel. Quando pegou, Eliseu pôs suas mãos sobre as mãos do rei', 3, CURRENT_TIMESTAMP, false),
(12, 13, 17, 'e lhe disse para abrir a janela que dava para o leste e atirar. O rei o fez, então Eliseu declarou: "Esta é a flecha da vitória do Senhor, a flecha da vitória sobre a Síria! Você destruirá totalmente os arameus, em Afeque".', 3, CURRENT_TIMESTAMP, false),
(12, 13, 18, 'Em seguida Eliseu mandou o rei pegar as flechas e golpear o chão. Ele golpeou o chão três vezes e parou.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 19, 'O homem de Deus ficou irado com ele e disse: "Você deveria ter golpeado o chão cinco ou seis vezes; então iria derrotar a Síria e a destruiria completamente. Mas agora você a derrotará somente três vezes".', 3, CURRENT_TIMESTAMP, false),
(12, 13, 20, 'Então Eliseu morreu e foi sepultado. Ora, tropas moabitas costumavam entrar no país em todas as primaveras.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 21, 'Certa vez, enquanto alguns israelitas sepultavam um homem, viram de repente uma dessas tropas; então jogaram o corpo do homem no túmulo de Eliseu e fugiram. Assim que o cadáver encostou nos ossos de Eliseu, o homem voltou à vida e se levantou.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 22, 'Hazael, rei da Síria, oprimiu Israel durante todo o reinado de Jeoacaz.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 23, 'Mas o Senhor foi bondoso para com eles, teve compaixão e mostrou preocupação por eles, por causa da sua aliança com Abraão, Isaque e Jacó. Até hoje ele não se dispôs a destruí-los ou eliminá-los de sua presença.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 24, 'E Hazael, rei da Síria, morreu, e seu filho Ben-Hadade foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 13, 25, 'Então Jeoás, filho de Jeoacaz, conquistou de Ben-Hadade, filho de Hazael, as cidades que, em combate, Hazael havia tomado de seu pai Jeoacaz. Três vezes Jeoás o derrotou e, assim, reconquistou essas cidades israelitas.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 1, 'No segundo ano do reinado de Jeoás, filho de Jeoacaz, rei de Israel, Amazias, filho de Joás, rei de Judá, começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 2, 'Ele tinha vinte e cinco anos de idade quando começou a reinar, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Jeoadã; ela era de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 3, 'Ele fez o que o Senhor aprova, mas não como Davi, seu predecessor. Em tudo seguiu o exemplo do seu pai Joás.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 4, 'Contudo, os altares não foram derrubados; o povo continuava a oferecer sacrifícios e a queimar incenso neles.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 5, 'Quando sentiu que tinha o reino sob pleno controle, mandou executar os oficiais que haviam assassinado o rei, seu pai.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 6, 'Contudo, não matou os filhos dos assassinos, de acordo com o que está escrito no livro da Lei de Moisés, onde o Senhor ordenou: "Os pais não morrerão no lugar dos filhos, nem os filhos no lugar dos pais; cada um morrerá pelo seu próprio pecado".', 3, CURRENT_TIMESTAMP, false),
(12, 14, 7, 'Foi ele que derrotou dez mil edomitas no vale do Sal e conquistou a cidade de Selá em combate, dando-lhe o nome de Jocteel, nome que tem até hoje.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 8, 'Então Amazias enviou mensageiros a Jeoás, filho de Jeoacaz e neto de Jeú, rei de Israel, com este desafio: "Venha me enfrentar".', 3, CURRENT_TIMESTAMP, false),
(12, 14, 9, 'Contudo, Jeoás respondeu a Amazias: "O espinheiro do Líbano enviou uma mensagem ao cedro do Líbano: ‘Dê sua filha em casamento a meu filho’. Mas um animal selvagem do Líbano veio e pisoteou o espinheiro.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 10, 'De fato, você derrotou Edom e agora está arrogante. Comemore a sua vitória, mas fique em casa! Por que provocar uma desgraça que levará você e também Judá à ruína? "', 3, CURRENT_TIMESTAMP, false),
(12, 14, 11, 'Amazias, porém, não quis ouvi-lo, de modo que Jeoás, rei de Israel, o atacou. Ele e Amazias, rei de Judá, enfrentaram-se em Bete-Semes, em Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 12, 'Judá foi derrotado por Israel, e seus soldados fugiram para as suas casas.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 13, 'Jeoás capturou Amazias, filho de Joás e neto de Acazias, em Bete-Semes. Então Jeoás foi a Jerusalém e derrubou cento e oitenta metros do muro da cidade, desde a porta de Efraim até a porta da Esquina.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 14, 'Ele se apoderou de todo o ouro, de toda a prata e todos os utensílios encontrados no templo do Senhor e nos tesouros do palácio real. Também fez reféns e, então, voltou para Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 15, 'Os demais acontecimentos do reinado de Jeoás, os seus feitos e todas as suas realizações, inclusive sua guerra contra Amazias, rei de Judá, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 16, 'Jeoás descansou com seus antepassados e foi sepultado com os reis de Israel em Samaria. E seu filho Jeroboão o sucedeu como rei.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 17, 'Amazias, filho de Joás, rei de Judá, viveu ainda mais quinze anos depois da morte de Jeoás, filho de Jeoacaz, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 18, 'Os demais acontecimentos do reinado de Amazias estão escritos nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 19, 'Vítima de uma conspiração em Jerusalém, ele fugiu para Láquis, mas o perseguiram até lá e o mataram.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 20, 'Ele foi trazido de volta a cavalo, e sepultado em Jerusalém junto aos seus antepassados, na cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 21, 'Então todo o povo de Judá proclamou rei a Azarias, de dezesseis anos de idade, no lugar de seu pai, Amazias.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 22, 'Foi ele quem reconquistou e reconstruiu a cidade de Elate para Judá, depois que Amazias descansou com os seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 23, 'No décimo quinto ano do reinado de Amazias, filho de Joás, rei de Judá, Jeroboão, filho de Jeoás, rei de Israel, tornou-se rei em Samaria e reinou quarenta e um anos.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 24, 'Ele fez o que o Senhor reprova e não se desviou de nenhum dos pecados que Jeroboão, filho de Nebate, levara Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 25, 'Foi ele quem restabeleceu as fronteiras de Israel desde Lebo-Hamate até o mar da Arabá, conforme a palavra do Senhor, Deus de Israel, anunciada pelo seu servo Jonas, filho de Amitai, profeta de Gate-Héfer.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 26, 'O Senhor viu a amargura com que todos em Israel, tanto escravos quanto livres, estavam sofrendo; não havia ninguém para socorrê-los.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 27, 'Visto que o Senhor não dissera que apagaria o nome de Israel de debaixo do céu, ele os libertou pela mão de Jeroboão, filho de Jeoás.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 28, 'Os demais acontecimentos do reinado de Jeroboão, os seus feitos e as suas realizações militares, inclusive a maneira pela qual recuperou para Israel Damasco e Hamate, que haviam pertencido a Iaudi, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 14, 29, 'Jeroboão descansou com seus antepassados, os reis de Israel. Seu filho Zacarias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 1, 'No vigésimo sétimo ano do reinado de Jeroboão, rei de Israel, Azarias, filho de Amazias, rei de Judá, começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 2, 'Tinha dezesseis anos de idade quando se tornou rei, e reinou cinqüenta e dois anos em Jerusalém. Sua mãe era de Jerusalém e chamava-se Jecolias.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 3, 'Ele fez o que o Senhor aprova, tal como o seu pai Amazias.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 4, 'Contudo, os altares idólatras não foram derrubados; o povo continuava a oferecer sacrifícios e a queimar incenso neles.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 5, 'O Senhor feriu o rei com lepra, até o dia de sua morte. Durante todo esse tempo morou numa casa separada. Jotão, filho do rei, tomava conta do palácio e governava o povo.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 6, 'Os demais acontecimentos do reinado de Azarias e todas as suas realizações, estão escritos nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 7, 'Azarias descansou com os seus antepassados e foi sepultado junto a eles na cidade de Davi. Seu filho Jotão foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 8, 'No trigésimo oitavo ano do reinado de Azarias, rei de Judá, Zacarias, filho de Jeroboão, tornou-se rei de Israel em Samaria, e reinou seis meses.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 9, 'Ele fez o que o Senhor reprova, como seus antepassados haviam feito. Não se desviou dos pecados que Jeroboão, filho de Nebate, levara Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 10, 'Salum, filho de Jabes, conspirou contra Zacarias. Ele o atacou na frente do povo, assassinou-o e foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 11, 'Os demais acontecimentos do reinado de Zacarias estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 12, 'Assim se cumpriu a palavra do Senhor anunciada a Jeú: "Seus descendentes ocuparão o trono de Israel até a quarta geração".', 3, CURRENT_TIMESTAMP, false),
(12, 15, 13, 'Salum, filho de Jabes, começou a reinar no trigésimo oitavo ano do reinado de Uzias, rei de Judá, e reinou um mês em Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 14, 'Então Menaém, filho de Gadi, foi de Tirza a Samaria e atacou a Salum, filho de Jabes, assassinou-o e foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 15, 'Os demais acontecimentos do reinado de Salum e a conspiração que liderou estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 16, 'Naquela ocasião, Menaém, partindo de Tirza, atacou Tifsa e todos que estavam na cidade e seus arredores, porque eles se recusaram a abrir as portas da cidade. Saqueou Tifsa e rasgou ao meio todas as mulheres grávidas.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 17, 'No trigésimo nono ano do reinado de Azarias, rei de Judá, Menaém, filho de Gadi, tornou-se rei de Israel, e reinou dez anos em Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 18, 'Ele fez o que o Senhor reprova. Durante todo o seu reinado não se desviou dos pecados que Jeroboão, filho de Nebate, levara Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 19, 'Então Pul, rei da Assíria, invadiu o país, e Menaém lhe deu trinta e cinco toneladas de prata para obter seu apoio e manter-se no trono.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 20, 'Menaém cobrou essa quantia de Israel. Todos os homens de posses tiveram de contribuir com seiscentos gramas de prata no pagamento ao rei da Assíria. Então ele interrompeu a invasão e foi embora.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 21, 'Os demais acontecimentos do reinado de Menaém e todas as suas realizações, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 22, 'Menaém descansou com seus antepassados, e seu filho Pecaías foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 23, 'No qüinquagésimo ano do reinado de Azarias, rei de Judá, Pecaías, filho de Menaém, tornou-se rei de Israel em Samaria, e reinou dois anos.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 24, 'Pecaías fez o que o Senhor reprova. Não se desviou dos pecados que Jeroboão, filho de Nebate, levara Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 25, 'Um de seus principais oficiais, Peca, filho de Remalias, conspirou contra ele. Levando consigo cinqüenta homens de Gileade, assassinou Pecaías juntamente com Argobe e Arié, na cidadela do palácio real em Samaria. Assim Peca matou Pecaías e foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 26, 'Os demais acontecimentos do reinado de Pecaías e todas as suas realizações estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 27, 'No qüinquagésimo segundo ano do reinado de Azarias, rei de Judá, Peca, filho de Remalias, tornou-se rei de Israel em Samaria, e reinou vinte anos.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 28, 'Ele fez o que o Senhor reprova. Não se desviou dos pecados que Jeroboão, filho de Nebate, levara Israel a cometer.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 29, 'Durante seu reinado, Tiglate-Pileser, rei da Assíria, invadiu e conquistou Ijom, Abel-Bete-Maaca, Janoa, Quedes e Hazor. Tomou Gileade e a Galiléia, inclusive toda a terra de Naftali, e deportou o povo para a Assíria.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 30, 'Então Oséias, filho de Elá, conspirou contra Peca, filho de Remalias. Ele o atacou e o assassinou, tornando-se seu sucessor no vigésimo ano do reinado de Jotão, filho de Uzias.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 31, 'Os demais acontecimentos do reinado de Peca e todas as suas realizações, estão escritos nos registros históricos dos reis de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 32, 'No segundo ano do reinado de Peca, filho de Remalias, rei de Israel, Jotão, filho de Uzias, rei de Judá, começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 33, 'Ele tinha vinte e cinco anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém. O nome da sua mãe era Jerusa, filha de Zadoque.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 34, 'Ele fez o que o Senhor aprova, tal como seu pai Uzias.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 35, 'Contudo, os altares idólatras não foram derrubados; o povo continuou a oferecer sacrifícios e a queimar incenso neles. Jotão reconstruiu a porta superior do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 36, 'Os demais acontecimentos do reinado de Jotão e as suas realizações, estão escritos nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 15, 37, '( Naqueles dias o Senhor começou a enviar Rezim, rei da Síria, e Peca, filho de Remalias, contra Judá. )', 3, CURRENT_TIMESTAMP, false),
(12, 15, 38, 'Jotão descansou com os seus antepassados e foi sepultado junto a eles na cidade de Davi, cidade de seu pai. Seu filho Acaz foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 1, 'No décimo sétimo ano do reinado de Peca, filho de Remalias, Acaz, filho de Jotão, rei de Judá, começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 2, 'Acaz tinha vinte anos de idade quando começou a reinar e reinou dezesseis anos em Jerusalém. Ao contrário de Davi, seu predecessor, não fez o que o Senhor seu Deus aprova.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 3, 'Andou nos caminhos dos reis de Israel e chegou até a queimar o seu filho em sacrifício, imitando os costumes detestáveis das nações que o Senhor havia expulsado de diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 4, 'Também ofereceu sacrifícios e queimou incenso nos altares idólatras, no alto das colinas e debaixo de toda árvore frondosa.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 5, 'Então Rezim, rei da Síria, e Peca, filho de Remalias, rei de Israel, saíram para lutar contra Acaz e sitiaram Jerusalém, mas não conseguiram vencê-lo.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 6, 'Naquela ocasião, Rezim recuperou Elate para a Síria, expulsando os homens de Judá. Os edomitas então se mudaram para Elate, onde vivem até hoje.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 7, 'Acaz enviou mensageiros para dizer a Tiglate-Pileser, rei da Assíria: "Sou teu servo e teu vassalo. Vem salvar-me das mãos do rei da Síria e do rei de Israel, que estão me atacando".', 3, CURRENT_TIMESTAMP, false),
(12, 16, 8, 'Acaz ajuntou a prata e o ouro encontrados no templo do Senhor e nos tesouros do palácio real e enviou-os como presente para o rei da Assíria.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 9, 'Este atendeu o pedido, atacou Damasco e a conquistou. Deportou seus habitantes para Quir e matou a Rezim.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 10, 'Então o rei Acaz foi a Damasco encontrar-se com Tiglate-Pileser, rei da Assíria. Ele viu o altar que havia em Damasco e mandou ao sacerdote Urias um modelo do altar, com informações detalhadas para sua construção.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 11, 'O sacerdote Urias construiu um altar conforme as instruções que o rei Acaz tinha enviado de Damasco e o terminou antes do retorno do rei Acaz.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 12, 'Quando o rei voltou de Damasco e viu o altar, aproximou-se dele e apresentou ofertas sobre ele.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 13, 'Ofereceu seu holocausto e sua oferta de cereal, derramou sua oferta de bebidas e aspergiu sobre o altar o sangue dos seus sacrifícios de comunhão.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 14, 'Ele tirou da frente do templo, dentre o altar e o templo do Senhor, o altar de bronze que ficava diante do Senhor e o colocou no lado norte do altar.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 15, 'Então o rei Acaz deu estas ordens ao sacerdote Urias: "No altar grande, ofereça o holocausto da manhã e a oferta de cereal da tarde, o holocausto do rei e sua oferta de cereal, e o holocausto, a oferta de cereal e a oferta derramada de todo o povo. Espalhe sobre o altar todo o sangue dos holocaustos e dos sacrifícios. Mas utilizarei o altar de bronze para buscar orientação".', 3, CURRENT_TIMESTAMP, false),
(12, 16, 16, 'E o sacerdote Urias fez como o rei Acaz tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 17, 'O rei tirou os painéis laterais e retirou as pias dos estrados móveis. Tirou o tanque de cima dos touros de bronze que o sustentavam e o colocou sobre uma base de pedra.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 18, 'Por causa do rei da Assíria tirou a cobertura para ser usada no sábado, que fora construída no templo, e retirou a entrada real do lado de fora do templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 19, 'Os demais acontecimentos do reinado de Acaz, e suas realizações, estão escritos nos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 16, 20, 'Acaz descansou com seus antepassados e foi sepultado junto a eles na cidade de Davi. Seu filho Ezequias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 1, 'No décimo segundo ano do reinado de Acaz, rei de Judá, Oséias, filho de Elá, tornou-se rei de Israel em Samaria, e reinou nove anos.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 2, 'Ele fez o que o Senhor reprova, mas não como os reis de Israel que o precederam.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 3, 'Salmaneser, rei da Assíria, foi atacar Oséias, que fora seu vassalo e lhe pagara tributo.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 4, 'Mas o rei da Assíria descobriu que Oséias era um traidor, pois havia mandado emissários a Sô, rei do Egito, e já não pagava mais o tributo, como costumava fazer a cada ano. Por isso, Salmaneser mandou lançá-lo na prisão.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 5, 'O rei da Assíria invadiu todo o país, marchou contra Samaria e a sitiou por três anos.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 6, 'No nono ano do reinado de Oséias, o rei assírio conquistou Samaria e deportou os israelitas para a Assíria. Ele os colocou em Hala, em Gozã do rio Habor e nas cidades dos medos.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 7, 'Tudo isso aconteceu porque os israelitas haviam pecado contra o Senhor seu Deus, que os tirara do Egito, de sob o poder do faraó, rei do Egito. Eles prestaram culto a outros deuses', 3, CURRENT_TIMESTAMP, false),
(12, 17, 8, 'e seguiram os costumes das nações que o Senhor havia expulsado de diante deles, bem como os costumes que os reis de Israel haviam introduzido.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 9, 'Os israelitas praticaram o mal secretamente contra o Senhor seu Deus. Desde torres de sentinela até cidades fortificadas, eles mesmos construíram altares idólatras em todas as suas cidades.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 10, 'Ergueram colunas sagradas e postes sagrados em todo monte alto e debaixo de toda árvore frondosa.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 11, 'Em todos os altares idólatras queimavam incenso, como fizeram as nações a quem o Senhor havia expulsado de diante deles. Fizeram males que provocaram o Senhor à ira.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 12, 'Prestaram culto a ídolos, embora o Senhor houvesse dito: "Não façam isso".', 3, CURRENT_TIMESTAMP, false),
(12, 17, 13, 'O Senhor advertiu Israel e Judá por meio de todos os seus profetas e videntes: "Desviem-se de seus maus caminhos. Obedeçam às minhas ordenanças e aos meus decretos, de acordo com toda a Lei que ordenei a seus antepassados que obedecessem e que lhes entreguei por meio de meus servos, os profetas".', 3, CURRENT_TIMESTAMP, false),
(12, 17, 14, 'Mas eles não quiseram ouvir e foram obstinados como seus antepassados, que não confiaram no Senhor seu Deus.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 15, 'Rejeitaram os seus decretos, a aliança que tinha feito com seus antepassados e as suas advertências. Seguiram ídolos inúteis, tornando-se eles mesmos inúteis. Imitaram as nações ao seu redor, embora o Senhor tivesse lhes ordenado: "Não as imitem".', 3, CURRENT_TIMESTAMP, false),
(12, 17, 16, 'Abandonaram todos os mandamentos do Senhor, do seu Deus e fizeram para si dois ídolos de metal na forma de bezerros e um poste sagrado. Inclinaram-se diante de todos os exércitos celestiais e prestaram culto a Baal.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 17, 'Queimaram seus filhos e filhas em sacrifício. Praticaram adivinhação e feitiçaria e venderam-se para fazer o que o Senhor reprova, provocando-o à ira.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 18, 'Então o Senhor indignou-se muito contra Israel e os expulsou da sua presença. Só a tribo de Judá escapou,', 3, CURRENT_TIMESTAMP, false),
(12, 17, 19, 'mas nem ela obedeceu aos mandamentos do Senhor seu Deus. Seguiram os costumes que Israel havia introduzido.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 20, 'Por isso, o Senhor rejeitou todo o povo de Israel; ele o afligiu e o entregou nas mãos de saqueadores, até expulsá-lo da sua presença.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 21, 'Quando o Senhor separou Israel da dinastia de Davi, os israelitas escolheram como rei Jeroboão, filho de Nebate, que induziu Israel a deixar de seguir o Senhor e o levou a cometer grande pecado.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 22, 'Eles permaneceram em todos os pecados de Jeroboão e não se desviaram deles,', 3, CURRENT_TIMESTAMP, false),
(12, 17, 23, 'até que o Senhor os afastou de sua presença, conforme havia advertido por meio de todos os seus servos, os profetas. Assim, o povo de Israel foi tirado de sua terra e levado ao exílio na Assíria, onde ainda hoje permanecem.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 24, 'O rei da Assíria trouxe gente da Babilônia, de Cuta, de Ava, de Hamate e de Sefarvaim e os estabeleceu nas cidades de Samaria para substituir os israelitas. Eles ocuparam Samaria e habitaram em suas cidades.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 25, 'Quando começaram a viver ali, não adoravam o Senhor; por isso ele enviou leões para o meio deles, que mataram alguns dentre o povo.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 26, 'Então informaram o rei da Assíria: "Os povos que deportaste e fizeste morar nas cidades de Samaria não sabem o que o Deus daquela terra exige. Ele enviou leões para matá-los pois desconhecem suas exigências".', 3, CURRENT_TIMESTAMP, false),
(12, 17, 27, 'Então o rei da Assíria deu esta ordem: "Façam um dos sacerdotes de Samaria que vocês levaram prisioneiro retornar e viver ali para ensinar as exigências do Deus da terra".', 3, CURRENT_TIMESTAMP, false),
(12, 17, 28, 'Então um dos sacerdotes exilados de Samaria veio morar em Betel e lhes ensinou a adorar o Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 29, 'No entanto, cada grupo fez seus próprios deuses nas diversas cidades em que moravam e os puseram nos altares idólatras que o povo de Samaria havia feito.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 30, 'Os de Babilônia fizeram Sucote-Benote, os de Cuta fizeram Nergal e os de Hamate fizeram Asima;', 3, CURRENT_TIMESTAMP, false),
(12, 17, 31, 'os aveus fizeram Nibaz e Tartaque; os sefarvitas queimavam seus filhos em sacrifício a Adrameleque e Anameleque, deuses de Sefarvaim.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 32, 'Eles adoravam o Senhor, mas também nomeavam qualquer pessoa para lhes servir como sacerdote nos altares idólatras.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 33, 'Adoravam o Senhor, mas também prestavam culto aos seus próprios deuses, conforme os costumes das nações de onde haviam sido trazidos.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 34, 'Até hoje eles continuam em suas antigas práticas. Não adoram o Senhor nem se comprometem com os decretos, com as ordenanças, com as leis e com os mandamentos que o Senhor deu aos descendentes de Jacó, a quem deu o nome de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 35, 'Quando o Senhor fez uma aliança com os israelitas, ele lhes ordenou: "Não adorem a outros deuses, não se inclinem diante deles, não lhes prestem culto nem lhes ofereçam sacrifício.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 36, 'Mas o Senhor, que os tirou do Egito com grande poder e braço forte, é a quem vocês adorarão. Diante dele vocês se inclinarão e lhe oferecerão sacrifícios.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 37, 'Vocês sempre tomarão o cuidado de obedecer aos decretos, e às ordenanças, às leis e aos mandamentos que lhes prescreveu. Não adorem a outros deuses.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 38, 'Não esqueçam a aliança que fiz com vocês e não adorem a outros deuses.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 39, 'Antes, adorem o Senhor, o seu Deus; ele os livrará das mãos de todos os seus inimigos".', 3, CURRENT_TIMESTAMP, false),
(12, 17, 40, 'Contudo, eles não deram atenção, mas continuaram em suas antigas práticas.', 3, CURRENT_TIMESTAMP, false),
(12, 17, 41, 'Mesmo enquanto esses povos adoravam o Senhor, também prestavam culto aos seus ídolos. Até hoje seus filhos e netos continuam a fazer o que seus antepassados faziam.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 1, 'No terceiro ano do reinado de Oséias, filho de Elá, rei de Israel, Ezequias, filho de Acaz, rei de Judá, começou a reinar.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 2, 'Ele tinha vinte e cinco anos de idade quando começou a reinar, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Abia, filha de Zacarias.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 3, 'Ele fez o que o Senhor aprova, tal como tinha feito Davi, seu predecessor.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 4, 'Removeu os altares idólatras, quebrou as colunas sagradas e derrubou os postes sagrados. Despedaçou a serpente de bronze que Moisés havia feito, pois até àquela época os israelitas lhe queimavam incenso. Ela era chamada Neustã.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 5, 'Ezequias confiava no Senhor, o Deus de Israel. Nunca houve ninguém como ele entre todos os reis de Judá, nem antes nem depois dele.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 6, 'Ele se apegou ao Senhor e não deixou de segui-lo; obedeceu aos mandamentos que o Senhor tinha dado a Moisés.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 7, 'E o Senhor estava com ele; era bem sucedido em tudo o que fazia. Rebelou-se contra o rei da Assíria e deixou de submeter-se a ele.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 8, 'Desde a torre de sentinela até à cidade fortificada, ele derrotou os filisteus, até Gaza e o seu território.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 9, 'No quarto ano do reinado do rei Ezequias, o sétimo ano do reinado de Oséias, filho de Elá, rei de Israel, Salmaneser, rei da Assíria, marchou contra Samaria e a cercou.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 10, 'Ao fim de três anos, os assírios a tomaram. Assim a cidade foi conquistada no sexto ano do reinado de Ezequias, o nono ano do reinado de Oséias, rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 11, 'O rei assírio deportou os israelitas para a Assíria e os estabeleceu em Hala, em Gozã do rio Tabor e nas cidades dos medos.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 12, 'Isto aconteceu porque os israelitas não obedeceram ao Senhor seu Deus, mas violaram a sua aliança: tudo o que Moisés, o servo do Senhor, tinha ordenado. Não o ouviram nem lhe obedeceram.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 13, 'No décimo quarto ano do reinado do rei Ezequias, Senaqueribe, rei da Assíria, atacou todas as cidades fortificadas de Judá e as conquistou.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 14, 'Então Ezequias, rei de Judá, enviou esta mensagem ao rei da Assíria, em Láquis: "Cometi um erro. Pára de atacar-me, e eu pagarei tudo que exigires". O rei da Assíria cobrou de Ezequias, rei de Judá, dez toneladas e meia de prata e uma tonelada e cinqüenta quilos de ouro.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 15, 'Assim, Ezequias lhes deu toda a prata que se encontrou no templo e na tesouraria do palácio real.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 16, 'Nessa ocasião Ezequias, rei de Judá, retirou o ouro com que havia coberto as portas e batentes do templo do Senhor, e o deu ao rei da Assíria.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 17, 'De Láquis o rei da Assíria enviou ao rei Ezequias, em Jerusalém, seu general, seu oficial principal e seu comandante de campo com um grande exército. Eles subiram a Jerusalém e pararam no aqueduto do açude superior, na estrada que leva ao campo do Lavandeiro.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 18, 'Eles chamaram pelo rei; e o administrador do palácio, Eliaquim, filho de Hilquias, o secretário Sebna e o arquivista real Joá, filho de Asafe, foram ao seu encontro.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 19, 'O comandante de campo lhes disse: "Digam isto a Ezequias: Assim diz o grande rei, o rei da Assíria: Em que você baseia sua confiança?', 3, CURRENT_TIMESTAMP, false),
(12, 18, 20, 'Você pensa que meras palavras já são estratégia e poderio militar. Em quem você está confiando para se rebelar contra mim?', 3, CURRENT_TIMESTAMP, false),
(12, 18, 21, 'Você está confiando no Egito, aquele caniço quebrado, que espeta e perfura a mão do homem que nele se apóia! Assim o faraó, rei do Egito, retribui a quem confia nele.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 22, 'Mas, se vocês me disserem: "Estamos confiando no Senhor nosso Deus"; não é ele aquele cujos santuários e altares Ezequias removeu, dizendo a Judá e Jerusalém: "Vocês devem adorar diante deste altar em Jerusalém? "', 3, CURRENT_TIMESTAMP, false),
(12, 18, 23, 'Aceite, pois, agora, o desafio do meu senhor, o rei da Assíria: Eu lhe darei dois mil cavalos; se você tiver cavaleiros para eles!', 3, CURRENT_TIMESTAMP, false),
(12, 18, 24, 'Como você pode derrotar o mais insignificante guerreiro do meu senhor? Você confia no Egito para lhe dar carros de guerra e cavaleiros?', 3, CURRENT_TIMESTAMP, false),
(12, 18, 25, 'Além disso, será que vim atacar e destruir este local sem uma palavra da parte do Senhor? O próprio Senhor me disse que marchasse contra este país e o destruísse".', 3, CURRENT_TIMESTAMP, false),
(12, 18, 26, 'Então Eliaquim, filho de Hilquias, Sebna e Joá disseram ao comandante de campo: "Por favor, fala com teus servos em aramaico, porque entendemos essa língua. Não fales em hebraico, pois assim o povo que está sobre os muros entenderá".', 3, CURRENT_TIMESTAMP, false),
(12, 18, 27, 'O comandante, porém, respondeu: "Será que meu senhor enviou-me para dizer essas coisas, somente para o seu senhor e para você e não para os que estão sentados no muro, que, como vocês, terão de comer as próprias fezes e beber a própria urina? "', 3, CURRENT_TIMESTAMP, false),
(12, 18, 28, 'Então o comandante levantou-se e gritou em hebraico: "Ouçam a palavra do grande rei, o rei da Assíria!', 3, CURRENT_TIMESTAMP, false),
(12, 18, 29, 'Assim diz o rei: Não deixem que Ezequias os engane. Ele não poderá livrá-los de minha mão.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 30, 'Não deixem Ezequias convencê-los a confiar no Senhor, quando diz: ‘Com certeza o Senhor nos livrará; esta cidade não será entregue nas mãos do rei da Assíria’.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 31, 'Não dêem ouvidos a Ezequias. Assim diz o rei da Assíria: Façam paz comigo e rendam-se. Então cada um de vocês comerá de sua própria videira e de sua própria figueira e beberá água de sua própria cisterna,', 3, CURRENT_TIMESTAMP, false),
(12, 18, 32, 'até que eu venha e os leve para uma terra igual à de vocês, terra de cereais, de vinho, terra de pão e de vinhas, terra de oliveiras e de mel. Escolham a vida e não a morte! Não dêem ouvidos a Ezequias, pois ele os está iludindo, quando diz: ‘O Senhor nos livrará’.', 3, CURRENT_TIMESTAMP, false),
(12, 18, 33, 'Será que o deus de alguma nação conseguiu livrar sua terra das mãos do rei da Assíria?', 3, CURRENT_TIMESTAMP, false),
(12, 18, 34, 'Onde estão os deuses de Hamate e de Arpade? Onde estão os deuses de Sefarvaim, Hena e Iva? Acaso livraram Samaria das minhas mãos?', 3, CURRENT_TIMESTAMP, false),
(12, 18, 35, 'Qual dentre todos os deuses dessas nações conseguiu livrar sua terra do meu poder? Como então o Senhor poderá livrar Jerusalém das minhas mãos? "', 3, CURRENT_TIMESTAMP, false),
(12, 18, 36, 'Mas o povo permaneceu calado e nada disse em resposta, pois o rei tinha ordenado: "Não lhe respondam".', 3, CURRENT_TIMESTAMP, false),
(12, 18, 37, 'Então o administrador do palácio, Eliaquim, filho de Hilquias, o secretário Sebna e o arquivista real Joá, filho de Asafe, retornaram com as vestes rasgadas a Ezequias e lhe relataram o que o comandante de campo tinha dito.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 1, 'Ao ouvir o relato, o rei Ezequias rasgou as suas vestes, pôs roupas de luto e entrou no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 2, 'Ele enviou o administrador do palácio, Eliaquim, o secretário Sebna e os sacerdotes principais, todos vestidos com pano de saco, ao profeta Isaías, filho de Amoz.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 3, 'Eles lhe disseram: "Assim diz Ezequias: Hoje é dia de angústia, de repreensão e de humilhação; estamos como a mulher que está para dar à luz filhos, mas não tem forças para fazê-los nascer.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 4, 'Talvez o Senhor seu Deus ouça todas as palavras do comandante de campo, a quem o senhor dele, o rei da Assíria, enviou para zombar do Deus vivo. E que o Senhor seu Deus o repreenda pelas palavras que ouviu. Portanto, suplique a Deus pelo remanescente que ainda sobrevive".', 3, CURRENT_TIMESTAMP, false),
(12, 19, 5, 'Quando os oficiais do rei Ezequias chegaram a Isaías,', 3, CURRENT_TIMESTAMP, false),
(12, 19, 6, 'este lhes disse: "Digam a seu senhor: ‘Assim diz o Senhor: Não tenha medo das palavras que você ouviu, das blasfêmias que os servos do rei da Assíria lançaram contra mim.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 7, 'Ouça! Eu o farei tomar a decisão de retornar ao seu próprio país, quando ele ouvir certa notícia. E lá o farei morrer à espada’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 19, 8, 'Quando o comandante de campo soube que o rei da Assíria havia partido de Láquis, retirou-se e encontrou o rei lutando contra Libna.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 9, 'Ora, Senaqueribe fora informado de que Tiraca, rei etíope do Egito, estava vindo lutar contra ele, de modo que mandou novamente mensageiros a Ezequias com este recado:', 3, CURRENT_TIMESTAMP, false),
(12, 19, 10, '"Digam a Ezequias, rei de Judá: Não deixe que o Deus no qual você confia o engane, quando diz: ‘Jerusalém não cairá nas mãos do rei da Assíria’.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 11, 'Com certeza você ouviu o que os reis da Assíria têm feito a todas as nações, como as destruíram por completo. E você haveria de livrar-se?', 3, CURRENT_TIMESTAMP, false),
(12, 19, 12, 'Acaso os deuses das nações que foram destruídas por meus antepassados as livraram: os deuses de Gozã, Harã, Rezefe e do povo de Éden, que estava em Telassar?', 3, CURRENT_TIMESTAMP, false),
(12, 19, 13, 'Onde estão o rei de Hamate, o rei de Arpade, o rei da cidade de Sevarfaim, de Hena ou de Iva? "', 3, CURRENT_TIMESTAMP, false),
(12, 19, 14, 'Ezequias recebeu a carta das mãos dos mensageiros e a leu. Então subiu ao templo do Senhor e estendeu-a perante o Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 15, 'E Ezequias orou ao Senhor: "Senhor, Deus de Israel, que reina em teu trono, entre os querubins, só tu és Deus sobre todos os reinos da terra. Tu criaste os céus e a terra.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 16, 'Dá ouvidos, Senhor, e vê; ouve as palavras que Senaqueribe enviou para insultar o Deus vivo.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 17, 'É verdade, Senhor, que os reis assírios fizeram de todas essas nações e seus territórios um deserto.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 18, 'Atiraram os deuses delas no fogo e os destruíram, pois não eram deuses; eram apenas madeira e pedra moldadas por mãos humanas.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 19, 'Agora, Senhor nosso Deus, salva-nos das mãos dele, para que todos os reinos da terra saibam que só tu, Senhor, és Deus".', 3, CURRENT_TIMESTAMP, false),
(12, 19, 20, 'Então Isaías, filho de Amoz, enviou uma mensagem a Ezequias: "Assim diz o Senhor, o Deus de Israel: Ouvi a sua oração acerca de Senaqueribe, o rei da Assíria.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 21, 'Esta é a palavra que o Senhor falou contra ele: ‘A virgem, a filha de Sião, o despreza e zomba de você. A filha de Jerusalém meneia a cabeça enquanto você foge.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 22, 'De quem você zombou e contra quem blasfemou? Contra quem você levantou a voz e contra quem ergueu o seu olhar arrogante? Contra o Santo de Israel!', 3, CURRENT_TIMESTAMP, false),
(12, 19, 23, 'Sim, você insultou o Senhor por meio dos seus mensageiros. E declarou: "Com carros sem conta subi, aos pontos mais elevados e às inacessíveis alturas do Líbano. Derrubei os seus mais altos cedros, os seus melhores pinheiros. Entrei em suas regiões mais remotas, e nas suas mais densas florestas.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 24, 'Em terras estrangeiras cavei poços e bebi água. Com as solas de meus pés sequei todos os rios do Egito".', 3, CURRENT_TIMESTAMP, false),
(12, 19, 25, 'Você não percebe que há muito tempo eu já havia determinado tudo isso. Desde a antigüidade planejei o que agora faço acontecer, que você deixaria cidades fortificadas em ruínas.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 26, 'Seus habitantes, sem forças, desanimam-se envergonhados. São como pastagens, como brotos tenros e verdes, como ervas no telhado, queimadas antes de crescer.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 27, 'Eu, porém, sei onde você está, sei quando você sai e quando retorna; e como você se enfurece contra mim.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 28, 'Sim, contra mim você se enfureceu e o seu atrevimento chegou aos meus ouvidos. Por isso porei o meu anzol em seu nariz e o meu freio em sua boca, e o farei voltar pelo caminho por onde veio.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 29, 'A você, Ezequias, darei este sinal: Neste ano vocês comerão do que crescer por si, e no próximo o que daquilo brotar. Mas no terceiro ano semeiem e colham, plantem vinhas e comam o seu fruto.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 30, 'Mais uma vez, um remanescente da tribo de Judá sobreviverá, lançará raízes na terra e se encherão de frutos os seus ramos.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 31, 'De Jerusalém sairão sobreviventes, e um remanescente do monte Sião. O zelo do Senhor dos Exércitos o executará’.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 32, 'Portanto, assim diz o Senhor acerca do rei da Assíria: ‘Ele não invadirá esta cidade nem disparará contra ela uma só flecha. Não a enfrentará com escudo nem construirá rampas de cerco contra ela.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 33, 'Pelo caminho por onde veio voltará; não invadirá esta cidade’, declara o Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 34, '‘Eu a defenderei e a salvarei, por amor de mim mesmo e do meu servo Davi’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 19, 35, 'Naquela noite o anjo do Senhor saiu e matou cento e oitenta e cinco mil homens no acampamento assírio. Quando o povo se levantou na manhã seguinte, o lugar estava repleto de cadáveres!', 3, CURRENT_TIMESTAMP, false),
(12, 19, 36, 'Assim Senaqueribe, rei da Assíria, desmontou o acampamento e foi embora. Voltou para Nínive e lá ficou.', 3, CURRENT_TIMESTAMP, false),
(12, 19, 37, 'Certo dia, enquanto ele estava adorando no templo de seu deus Nisroque, seus filhos Adrameleque e Sarezer mataram-no à espada e fugiram para a terra de Ararate. Seu filho Esar-Hadom foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 1, 'Naquele tempo Ezequias ficou doente, e quase morreu. O profeta Isaías, filho de Amoz, foi visitá-lo e lhe disse: "Assim diz o Senhor: Ponha em ordem a sua casa, pois você vai morrer; não se recuperará".', 3, CURRENT_TIMESTAMP, false),
(12, 20, 2, 'Ezequias virou o rosto para a parede e orou ao Senhor:', 3, CURRENT_TIMESTAMP, false),
(12, 20, 3, '"Lembra-te, Senhor, como tenho te servido com fidelidade e com devoção sincera. Tenho feito o que tu aprovas". E Ezequias chorou amargamente.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 4, 'Antes de Isaías deixar o pátio intermediário, a palavra do Senhor veio a ele:', 3, CURRENT_TIMESTAMP, false),
(12, 20, 5, '"Volte e diga a Ezequias, líder do meu povo: ‘Assim diz o Senhor, Deus de Davi, seu predecessor: Ouvi sua oração e vi suas lágrimas; eu o curarei. Daqui a três dias você subirá ao templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 6, 'Acrescentarei quinze anos à sua vida. E livrarei você e esta cidade das mãos do rei da Assíria. Defenderei esta cidade por causa de mim mesmo e do meu servo Davi’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 20, 7, 'Então disse Isaías: "Preparem um emplastro de figos". Eles o fizeram e o aplicaram na úlcera; e ele se recuperou.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 8, 'Ezequias havia perguntado a Isaías: "Qual será o sinal de que o Senhor me curará e de que de hoje a três dias subirei ao templo do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(12, 20, 9, 'Isaías respondeu: "O sinal de que o Senhor vai cumprir o que prometeu é este: Você prefere que a sombra avance ou recue dez degraus na escadaria? "', 3, CURRENT_TIMESTAMP, false),
(12, 20, 10, 'Disse Ezequias: "Como é fácil a sombra avançar dez degraus, prefiro que ela recue dez degraus".', 3, CURRENT_TIMESTAMP, false),
(12, 20, 11, 'Então o profeta Isaías clamou ao Senhor, e este fez a sombra recuar os dez degraus que havia descido na escadaria de Acaz.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 12, 'Naquela época, o rei da Babilônia, Merodaque-Baladã, filho de Baladã, enviou cartas e um presente para Ezequias, pois soubera da doença de Ezequias.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 13, 'Ezequias recebeu em audiência os mensageiros e mostrou-lhes tudo o que havia em seus armazéns, a prata, o ouro, as especiarias e o azeite finíssimo, o seu arsenal e tudo que estava em seus tesouros. Não houve nada em seu palácio ou em seu reino que Ezequias não lhes mostrasse.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 14, 'Então o profeta Isaías foi ao rei Ezequias e lhe perguntou: "O que esses homens disseram? De onde vieram? " Ezequias respondeu: "De uma terra distante. Vieram da Babilônia".', 3, CURRENT_TIMESTAMP, false),
(12, 20, 15, 'O profeta perguntou: "O que eles viram em seu palácio? " Disse Ezequias: "Viram tudo em meu palácio. Não há nada em meus tesouros que não lhes tenha mostrado".', 3, CURRENT_TIMESTAMP, false),
(12, 20, 16, 'Então Isaías disse a Ezequias: "Ouça a palavra do Senhor:', 3, CURRENT_TIMESTAMP, false),
(12, 20, 17, 'Um dia tudo que se encontra em seu palácio bem como tudo o que os seus antepassados acumularam até hoje será levado para a Babilônia. Nada restará, diz o Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 18, 'Alguns dos seus próprios descendentes serão levados, e eles se tornarão eunucos no palácio do rei da Babilônia".', 3, CURRENT_TIMESTAMP, false),
(12, 20, 19, 'Respondeu Ezequias ao profeta: "Boa é a palavra do Senhor que você anunciou", pois ele entendeu que durante sua vida haveria paz e segurança.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 20, 'Os demais acontecimentos do reinado de Ezequias, todas as suas realizações, inclusive a construção do açude e do túnel que canalizou água para a cidade, estão escritos no livro dos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 20, 21, 'Ezequias descansou com os seus antepassados, e seu filho Manassés foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 1, 'Manassés tinha doze anos de idade quando começou a reinar, e reinou cinqüenta e cinco anos em Jerusalém. O nome de sua mãe era Hefzibá.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 2, 'Ele fez o que o Senhor reprova, imitando as práticas detestáveis das nações que o Senhor havia expulsado de diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 3, 'Reconstruiu os altares idólatras que seu pai Ezequias havia demolido; também ergueu altares para Baal e fez um poste sagrado, como fizera Acabe, rei de Israel. Inclinou-se diante de todos os exércitos celestes e lhes prestou culto.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 4, 'Construiu altares no templo do Senhor, do qual este tinha dito: "Em Jerusalém porei meu nome".', 3, CURRENT_TIMESTAMP, false),
(12, 21, 5, 'Nos dois pátios do templo do Senhor ele construiu altares para todos os exércitos celestes.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 6, 'Chegou a queimar o próprio filho em sacrifício, praticou feitiçaria e adivinhação e consultou médiuns e espíritas. Fez o que o Senhor reprova, provocando-o à ira.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 7, 'Ele tomou o poste sagrado que havia feito e o pôs no templo, do qual o Senhor tinha dito a Davi e a seu filho Salomão: "Neste templo e em Jerusalém, que escolhi dentre todas as tribos de Israel, porei meu nome para sempre.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 8, 'Não farei os pés dos israelitas andarem errantes novamente, longe da terra que dei aos seus antepassados, se tão-somente tiverem o cuidado de fazer tudo o que lhes ordenei e obedecer à toda a Lei que meu servo Moisés lhes deu".', 3, CURRENT_TIMESTAMP, false),
(12, 21, 9, 'Mas o povo não quis ouvir. Manassés os desviou, a ponto de fazerem pior do que as nações que o Senhor havia destruído diante dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 10, 'E o Senhor disse por meio dos seus servos, os profetas:', 3, CURRENT_TIMESTAMP, false),
(12, 21, 11, '"Manassés, rei de Judá, cometeu esses atos repugnantes. Agiu pior do que os amorreus que o antecederam e também levou Judá a pecar com os ídolos que fizera.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 12, 'Portanto, assim diz o Senhor, o Deus de Israel: Causarei uma tal desgraça em Jerusalém e em Judá que os ouvidos de quem ouvir a respeito ficarão zumbindo.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 13, 'Estenderei sobre Jerusalém o fio de medir utilizado contra Samaria e o fio de prumo usado contra a família de Acabe. Limparei Jerusalém como se lava um prato, lavando-o e virando-o de cabeça para baixo.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 14, 'Abandonarei o remanescente da minha herança e o entregarei nas mãos de seus inimigos. Serão despojados e saqueados por todos os seus adversários,', 3, CURRENT_TIMESTAMP, false),
(12, 21, 15, 'pois fizeram o que eu reprovo e me provocaram à ira, desde o dia em que seus antepassados saíram do Egito até hoje".', 3, CURRENT_TIMESTAMP, false),
(12, 21, 16, 'Manassés também derramou tanto sangue inocente que encheu Jerusalém de um lado a outro; além disso levou Judá a cometer pecado, a fim de que fizessem o que o Senhor reprova.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 17, 'Os demais acontecimentos do reinado de Manassés e todas as suas realizações, inclusive o pecado que cometeu, estão escritos no livro dos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 18, 'Manassés descansou com seus antepassados e foi sepultado no jardim do seu palácio, o jardim de Uzá. E seu filho Amom foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 19, 'Amom tinha vinte e dois anos de idade quando começou a reinar, e reinou dois anos em Jerusalém. O nome de sua mãe era Mesulemete, filha de Haruz; ela era de Jotbá.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 20, 'Ele fez o que o Senhor reprova, como fizera Manassés, seu pai.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 21, 'Imitou o seu pai em tudo; prestou culto aos ídolos aos quais seu pai havia cultuado e inclinou-se diante deles.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 22, 'Abandonou o Senhor, o Deus de seus antepassados e não andou no caminho do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 23, 'Os oficiais de Amom conspiraram contra ele e o assassinaram em seu palácio.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 24, 'Mas o povo matou todos os que haviam conspirado contra o rei Amom, e a seu filho Josias proclamou rei em seu lugar.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 25, 'Os demais acontecimentos do reinado de Amom e as suas realizações, estão escritos no livro dos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 21, 26, 'Ele foi sepultado em seu túmulo no jardim de Uzá. Seu filho Josias foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 1, 'Josias tinha oito anos de idade quando começou a reinar, e reinou trinta e um anos em Jerusalém. O nome de sua mãe era Jedida, filha de Adaías; ela era de Bozcate.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 2, 'Ele fez o que o Senhor aprova e andou nos caminhos de Davi, seu predecessor, sem desviar-se nem para a direita nem para a esquerda.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 3, 'No décimo oitavo ano do seu reinado, o rei Josias enviou o secretário Safã, filho de Azalias e neto de Mesulão, ao templo do Senhor, dizendo:', 3, CURRENT_TIMESTAMP, false),
(12, 22, 4, '"Vá ao sumo sacerdote Hilquias e mande-o ajuntar a prata que foi trazida ao templo do Senhor, que os guardas das portas recolheram do povo.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 5, 'Eles deverão entregar a prata aos homens nomeados para supervisionar a reforma do templo, para poderem pagar os trabalhadores que fazem os reparos no templo do Senhor:', 3, CURRENT_TIMESTAMP, false),
(12, 22, 6, 'os carpinteiros, os construtores e os pedreiros. Além disso comprarão madeira e pedras lavradas para os reparos no templo.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 7, 'Mas eles não precisarão prestar contas da prata que lhes foi confiada, pois estão agindo com honestidade".', 3, CURRENT_TIMESTAMP, false),
(12, 22, 8, 'Então o sumo sacerdote Hilquias disse ao secretário Safã: "Encontrei o livro da Lei no templo do Senhor". Ele o entregou a Safã, que o leu.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 9, 'O secretário Safã voltou ao rei e lhe informou: "Teus servos entregaram a prata que havia no templo do Senhor e a confiaram aos trabalhadores e supervisores no templo".', 3, CURRENT_TIMESTAMP, false),
(12, 22, 10, 'E o secretário Safã acrescentou: "O sacerdote Hilquias entregou-me um livro". E Safã o leu para o rei.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 11, 'Assim que o rei ouviu as palavras do livro da Lei, rasgou suas vestes', 3, CURRENT_TIMESTAMP, false),
(12, 22, 12, 'e deu estas ordens ao sacerdote Hilquias, a Aicam, filho de Safã, a Acbor, filho de Micaías, ao secretário Safã e ao auxiliar real Asaías:', 3, CURRENT_TIMESTAMP, false),
(12, 22, 13, '"Vão consultar o Senhor por mim, pelo povo e por todo Judá acerca do que está escrito neste livro que foi encontrado. A ira do Senhor contra nós deve ser grande, pois nossos antepassados não obedeceram às palavras deste livro, nem agiram de acordo com tudo que nele está escrito a nosso respeito".', 3, CURRENT_TIMESTAMP, false),
(12, 22, 14, 'O sacerdote Hilquias, Aicam, Acbor, Safã e Asaías foram falar com a profetisa Hulda, mulher de Salum, filho de Ticvá e neto de Harás, responsável pelo guarda-roupa do templo. Ela morava no bairro novo de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 15, 'Ela lhes disse: "Assim diz o Senhor, o Deus de Israel: ‘Digam ao homem que os enviou a mim:', 3, CURRENT_TIMESTAMP, false),
(12, 22, 16, 'Assim diz o Senhor: Eu vou trazer desgraça sobre este lugar e sobre seus habitantes; tudo o que está escrito no livro que o rei de Judá leu.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 17, 'Porque me abandonaram e queimaram incenso a outros deuses, provocando-me à ira por meio de todos os ídolos que as mãos deles têm feito, minha ira arderá contra este lugar e não será apagada’.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 18, 'Digam ao rei de Judá, que os enviou para consultar o Senhor: ‘Assim diz o Senhor, o Deus de Israel, acerca das palavras que você ouviu:', 3, CURRENT_TIMESTAMP, false),
(12, 22, 19, 'Já que o seu coração se abriu e você se humilhou diante do Senhor, ao ouvir o que falei contra este lugar e contra seus habitantes, que seriam arrasados e amaldiçoados, e porque você rasgou as vestes e chorou na minha presença, eu o ouvi, declara o Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 22, 20, 'Portanto, eu o reunirei aos seus antepassados, e você será sepultado em paz. Seus olhos não verão toda a desgraça que eu vou trazer sobre este lugar’ ". Então eles levaram a resposta ao rei.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 1, 'Então o rei convocou todas as autoridades de Judá e de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 2, 'Depois o rei subiu ao templo do Senhor acompanhado por todos os homens de Judá, todo o povo de Jerusalém, os sacerdotes e os profetas; todo o povo, dos mais simples aos mais importantes. Para todos o rei leu em voz alta todas as palavras do Livro da Aliança, que havia sido encontrado no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 3, 'O rei colocou-se junto à coluna real e, na presença do Senhor, fez uma aliança, comprometendo-se a seguir o Senhor e obedecer de todo o coração e de toda a alma aos seus mandamentos, seus preceitos e seus decretos, confirmando assim as palavras da aliança escritas naquele livro. Então todo o povo se comprometeu com a aliança.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 4, 'O rei deu ordens ao sumo sacerdote Hilquias, aos sacerdotes auxiliares e aos guardas das portas que retirassem do templo do Senhor todos os utensílios feitos para Baal e Aserá e para todos os exércitos celestes. Ele os queimou fora de Jerusalém, nos campos do vale de Cedrom e levou as cinzas para Betel.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 5, 'E eliminou os sacerdotes pagãos nomeados pelos reis de Judá para queimar incenso nos altares idólatras das cidades de Judá e dos arredores de Jerusalém, aqueles que queimavam incenso a Baal, ao sol e à lua, às constelações e a todos os exércitos celestes.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 6, 'Também mandou levar o poste sagrado do templo do Senhor para o vale de Cedrom, fora de Jerusalém, para ser queimado e reduzido a cinzas, que foram espalhadas sobre os túmulos de um cemitério público.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 7, 'Também derrubou as acomodações dos prostitutos cultuais, que ficavam no templo do Senhor, onde as mulheres teciam para Aserá.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 8, 'Josias trouxe todos os sacerdotes das cidades de Judá e, desde Geba até Berseba, profanou os altares onde os sacerdotes haviam queimado incenso. Derrubou os altares idólatras junto às portas, inclusive o altar da entrada da porta de Josué, o governador da cidade, que fica à esquerda da porta da cidade.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 9, 'Embora os sacerdotes dos altares não servissem no altar do Senhor em Jerusalém, comiam pães sem fermento junto com os sacerdotes, seus colegas.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 10, 'Também profanou Tofete, que ficava no vale de Ben-Hinom, de modo que ninguém mais pudesse usá-lo para queimar seu filho ou filha em sacrifício a Moloque.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 11, 'Acabou com os cavalos que os reis de Judá tinham consagrado ao sol. Estavam na entrada do templo do Senhor perto da sala de um oficial chamado Natã-Meleque. Também queimou as carruagens consagradas ao sol.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 12, 'Derrubou os altares que os seus antecessores haviam erguido no terraço, em cima do quarto superior de Acaz, e os altares que Manassés havia construído nos dois pátios do templo do Senhor. Retirou-os dali, despedaçou-os e atirou o entulho no vale de Cedrom.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 13, 'O rei também profanou os altares que ficavam a leste de Jerusalém no sul do monte da Destruição, os quais Salomão, rei de Israel, havia construído para o poste sagrado, a detestável deusa dos sidônios, para Camos, o detestável deus de Moabe, e para Moloque, o detestável deus do povo de Amom.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 14, 'Josias despedaçou as colunas sagradas, derrubou os postes sagrados e cobriu os locais com ossos humanos.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 15, 'Até o altar de Betel, o altar idólatra edificado por Jeroboão, filho de Nebate, que levou Israel a pecar; até aquele altar e o seu santuário, ele os demoliu. Queimou o santuário e o reduziu a pó, queimando também o poste sagrado.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 16, 'Quando Josias olhou em volta e, viu os túmulos que havia na encosta da colina, mandou retirar os ossos dos túmulos e queimá-los no altar a fim de contaminá-lo, conforme a palavra do Senhor proclamada pelo homem de Deus que predisse essas coisas.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 17, 'O rei perguntou: "Que monumento é este que estou vendo? " Os homens da cidade disseram: "É o túmulo do homem de Deus que veio de Judá e proclamou estas coisas que tu fizeste ao altar de Betel".', 3, CURRENT_TIMESTAMP, false),
(12, 23, 18, 'Então ele disse: "Deixem-no em paz. Ninguém toque nos seus ossos". Assim pouparam seus ossos bem como os do profeta que tinha vindo de Samaria.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 19, 'Como havia feito em Betel, Josias tirou e profanou todos os santuários idólatras que os reis de Israel haviam construído nas cidades de Samaria e que provocaram o Senhor à ira.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 20, 'Josias também mandou sacrificar todos os sacerdotes daqueles altares idólatras e queimou ossos humanos sobre os altares. Depois voltou a Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 21, 'Então o rei deu a seguinte ordem a todo o povo: "Celebrem a Páscoa ao Senhor seu Deus, conforme está escrito neste livro da Aliança".', 3, CURRENT_TIMESTAMP, false),
(12, 23, 22, 'Nem nos dias dos juízes que lideraram Israel, nem durante todos os dias dos reis de Israel e dos reis de Judá, foi celebrada uma Páscoa como esta.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 23, 'Mas no décimo oitavo ano do reinado de Josias, esta Páscoa foi celebrada ao Senhor em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 24, 'Além disso, Josias eliminou os médiuns, os espíritas, os ídolos da família, os ídolos e todas as outras coisas repugnantes que havia em Judá e em Jerusalém. Ele fez isto para cumprir as exigências da lei escritas no livro que o sacerdote Hilquias havia descoberto no templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 25, 'Nem antes nem depois de Josias houve um rei como ele, que se voltasse para o Senhor de todo o coração, de toda a alma e de todas as suas forças, de acordo com toda a Lei de Moisés.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 26, 'Entretanto, o Senhor não voltou atrás do fogo de sua grande ira, que se acendeu contra Judá por causa de tudo o que Manassés fizera para provocá-lo à ira.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 27, 'Por isso o Senhor disse: "Também retirarei Judá da minha presença, tal como retirei de Israel, e rejeitarei Jerusalém, a cidade que escolhi, e este templo, do qual eu disse: ‘Ali porei o meu nome’ ".', 3, CURRENT_TIMESTAMP, false),
(12, 23, 28, 'Os demais acontecimentos do reinado de Josias e todas as suas realizações, estão escritos no livro dos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 29, 'Durante o seu reinado, o faraó Neco, rei do Egito, avançou até o rio Eufrates ao encontro do rei da Assíria. O rei Josias marchou para combatê-lo, mas o faraó Neco o enfrentou e o matou em Megido.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 30, 'Os oficiais de Josias levaram o seu corpo de Megido para Jerusalém, e o sepultaram em seu próprio túmulo. O povo tomou Jeoacaz, filho de Josias, ungiu-o e o proclamou como rei no lugar de seu pai.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 31, 'Jeoacaz tinha vinte e três anos de idade quando começou a reinar, e reinou três meses em Jerusalém. O nome de sua mãe era Hamutal, filha de Jeremias; ela era de Libna.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 32, 'Ele fez o que o Senhor reprova, tal como seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 33, 'O faraó Neco o prendeu em Ribla, na terra de Hamate, de modo que não mais reinou em Jerusalém. O faraó também impôs a Judá um tributo de três toneladas e meia de prata e trinta e cinco quilos de ouro.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 34, 'Colocou Eliaquim, filho de Josias, como rei no lugar do seu pai Josias, e mudou o nome de Eliaquim para Jeoaquim. Mas levou Jeoacaz consigo para o Egito, onde ele morreu.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 35, 'Jeoaquim pagou ao faraó Neco a prata e o ouro. Mas, para cumprir as exigências do faraó, Jeoaquim impôs tributos ao povo, cobrando a prata e o ouro, de cada um conforme suas posses.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 36, 'Jeoaquim tinha vinte e cinco anos de idade quando começou a reinar, e reinou onze anos em Jerusalém. O nome de sua mãe era Zebida, filha de Pedaías; ela era de Ruma.', 3, CURRENT_TIMESTAMP, false),
(12, 23, 37, 'Ele fez o que o Senhor reprova, tal como seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 1, 'Durante o reinado de Jeoaquim, Nabucodonosor, rei da Babilônia, invadiu o país, e Jeoaquim tornou-se seu vassalo por três anos. Então ele voltou atrás e rebelou-se contra Nabucodonosor.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 2, 'O Senhor enviou contra ele tropas babilônicas, aramaicas, moabitas e amonitas, para destruir Judá, de acordo com a palavra do Senhor proclamada por seus servos, os profetas.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 3, 'Com certeza isto aconteceu a Judá conforme a ordem do Senhor, a fim de removê-los da sua presença, por causa de todos os pecados que Manassés cometeu,', 3, CURRENT_TIMESTAMP, false),
(12, 24, 4, 'inclusive o derramamento de sangue inocente. Pois ele havia enchido Jerusalém de sangue inocente, e o Senhor não o quis perdoar.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 5, 'Os demais acontecimentos do reinado de Jeoaquim e todas as suas realizações, estão escritos no livro dos registros históricos dos reis de Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 6, 'Jeoaquim descansou com seus antepassados. Seu filho Joaquim foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 7, 'O rei do Egito não mais se atreveu a sair com seu exército de suas próprias fronteiras, pois o rei da Babilônia havia ocupado todo o território entre o ribeiro do Egito e o rio Eufrates, que antes pertencera ao Egito.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 8, 'Joaquim tinha dezoito anos de idade quando começou a reinar, e reinou três meses em Jerusalém. O nome da sua mãe era Neusta, filha de Elnatã; ela era de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 9, 'Ele fez o que o Senhor reprova, tal como seu pai.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 10, 'Naquela ocasião os oficiais de Nabucodonosor, rei da Babilônia, avançaram até Jerusalém e a cercaram,', 3, CURRENT_TIMESTAMP, false),
(12, 24, 11, 'Enquanto seus oficiais a cercavam o próprio Nabucodonosor veio à cidade.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 12, 'Então Joaquim, rei de Judá, sua mãe, seus conselheiros, seus nobres e seus oficiais se entregaram; todos se renderam a ele. No oitavo ano do reinado do rei da Babilônia, ele levou Joaquim como prisioneiro.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 13, 'Conforme o Senhor tinha declarado, Nabucodonosor retirou todos os tesouros do templo do Senhor e do palácio real, quebrando todos os utensílios de ouro que Salomão, rei de Israel, fizera para o templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 14, 'Levou para o exílio toda Jerusalém: todos os líderes e os homens de combate, todos os artesãos e artífices. Era um total de dez mil pessoas; só ficaram os mais pobres.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 15, 'Nabucodonosor levou prisioneiro Joaquim para a Babilônia. Também levou de Jerusalém para a Babilônia a mãe do rei, as mulheres do rei e os oficiais do rei e os líderes do país.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 16, 'O rei da Babilônia também deportou para a Babilônia toda a força de sete mil homens de combate, homens fortes e preparados para a guerra, e mil artífices e artesãos.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 17, 'Fez Matanias, tio de Joaquim, reinar em seu lugar, e mudou seu nome para Zedequias.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 18, 'Zedequias tinha vinte e um anos de idade quando começou a reinar, e reinou onze anos em Jerusalém. O nome de sua mãe era Hamutal, filha de Jeremias; ela era de Libna.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 19, 'Ele fez o que o Senhor reprova, tal como fizera Jeoaquim.', 3, CURRENT_TIMESTAMP, false),
(12, 24, 20, 'Por causa da ira do Senhor tudo isso aconteceu a Jerusalém e a Judá; por fim ele os lançou para longe da sua presença. Ora, Zedequias rebelou-se contra o rei da Babilônia.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 1, 'Então, no nono ano do reinado de Zedequias, no décimo dia do décimo mês, Nabucodonosor, rei da Babilônia, marchou contra Jerusalém com todo o seu exército. Ele acampou em frente da cidade e construiu rampas de ataque ao redor dela.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 2, 'A cidade foi mantida sob cerco até o décimo primeiro ano do reinado de Zedequias.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 3, 'No nono dia do quarto mês, a fome na cidade havia se tornado tão severa que não havia nada para o povo comer.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 4, 'Então o muro da cidade foi rompido, e todos os soldados fugiram de noite pela porta entre os dois muros próximos ao jardim do rei, embora os babilônios estivessem em torno da cidade. Fugiram na direção da Arabá,', 3, CURRENT_TIMESTAMP, false),
(12, 25, 5, 'mas o exército babilônio perseguiu o rei e o alcançou nas planícies de Jericó. Todos os seus soldados o abandonaram,', 3, CURRENT_TIMESTAMP, false),
(12, 25, 6, 'e ele foi capturado. Foi levado até o rei da Babilônia, em Ribla, onde pronunciaram a sentença contra ele.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 7, 'Executaram os filhos de Zedequias na sua frente; depois furaram seus olhos, prenderam-no com algemas de bronze e o levaram para a Babilônia.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 8, 'No sétimo dia do quinto mês do décimo nono ano do reinado de Nabucodonosor, rei da Babilônia, Nebuzaradã, comandante da guarda imperial, conselheiro do rei da Babilônia, foi a Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 9, 'Incendiou o templo do Senhor, o palácio real, todas as casas de Jerusalém e todos os edifícios importantes.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 10, 'Todo o exército babilônio, que acompanhava Nebuzaradã derrubou os muros de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 11, 'E ele levou para o exílio o povo que sobrou na cidade, os que passaram para o lado do rei da Babilônia e o restante da população.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 12, 'Mas alguns dos mais pobres do país o comandante deixou para trás, para trabalharem nas vinhas e nos campos.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 13, 'Os babilônios destruíram as colunas de bronze, os suportes e o tanque de bronze que estavam no templo do Senhor, e levaram o bronze para a Babilônia.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 14, 'Também levaram as panelas, as pás, os cortadores de pavio, as vasilhas e todos os utensílios de bronze utilizados no serviço do templo.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 15, 'O comandante da guarda imperial levou os incensários e as bacias de aspersão, tudo o que era feito de ouro puro ou prata.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 16, 'As duas colunas, o tanque e os suportes, que Salomão fizera para o templo do Senhor, eram mais do que podia ser pesado.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 17, 'Cada coluna tinha oito metros e dez centímetros de altura. O capitel de bronze no alto de cada coluna tinha um metro e trinta e cinco centímetros de altura e era decorado com uma fileira de romãs de bronze ao redor.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 18, 'O comandante da guarda levou como prisioneiros o sumo sacerdote, Seraías, Sofonias, o segundo sacerdote, e os três guardas da porta.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 19, 'Dos que ainda estavam na cidade, ele levou o oficial responsável pelos homens de combate e cinco conselheiros reais. Também levou o secretário, principal líder responsável pelo alistamento militar no país e sessenta homens do povo.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 20, 'O comandante Nebuzaradã levou a todos ao rei da Babilônia, em Ribla.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 21, 'Lá, em Ribla, na terra de Hamate, o rei mandou executá-los. Assim Judá foi para o exílio, para longe de sua terra.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 22, 'Nabucodonosor, rei da Babilônia, nomeou Gedalias, filho de Aicam e neto de Safã, como governador do povo que havia sido deixado em Judá.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 23, 'Quando Ismael, filho de Netanias, Joanã, filho de Careá, Seraías, filho do netofatita Tanumete, e Jazanias, filho de um maacatita, todos os líderes do exército, souberam que o rei da Babilônia havia nomeado Gedalias como governador, eles e seus soldados foram falar com Gedalias em Mispá.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 24, 'Gedalias fez um juramento a esses líderes e a seus soldados, dizendo: "Não tenham medo dos oficiais babilônios. Estabeleçam-se nesta terra e sirvam o rei da Babilônia, e tudo lhes irá bem".', 3, CURRENT_TIMESTAMP, false),
(12, 25, 25, 'Mas no sétimo mês, Ismael, filho de Netanias e neto de Elisama, que tinha sangue real, foi com dez homens e assassinou Gedalias e os judeus e os babilônios que estavam com ele em Mispá.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 26, 'Então todo o povo, desde as crianças até os velhos, juntamente com os líderes do exército, fugiram para o Egito, com medo dos babilônios.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 27, 'No trigésimo sétimo ano do exílio de Joaquim, rei de Judá, no ano em que Evil-Merodaque se tornou rei da Babilônia, ele tirou Joaquim da prisão, no dia vinte e sete do décimo segundo mês.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 28, 'Ele lhe tratou com bondade e deu-lhe o lugar mais honrado entre os outros reis que estavam com ele na Babilônia.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 29, 'Assim, Joaquim deixou suas vestes de prisão e pelo resto de sua vida comeu à mesa do rei.', 3, CURRENT_TIMESTAMP, false),
(12, 25, 30, 'E diariamente, enquanto viveu, Joaquim recebeu uma pensão do rei.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 1, 'Depois da morte de Saul, Davi retornou de sua vitória sobre os amalequitas. Fazia dois dias que ele estava em Ziclague', 3, CURRENT_TIMESTAMP, false),
(10, 1, 2, 'quando, no terceiro dia, chegou um homem que vinha do acampamento de Saul, com as roupas rasgadas e terra na cabeça. Ao aproximar-se de Davi, prostrou-se em terra, em sinal de respeito.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 3, 'Davi então lhe perguntou: "De onde você vem? " Ele respondeu: "Fugi do acampamento israelita".', 3, CURRENT_TIMESTAMP, false),
(10, 1, 4, 'Disse Davi: "Conte-me o que aconteceu? " E o homem contou: "O nosso exército fugiu da batalha, e muitos morreram. Saul e Jônatas também estão mortos".', 3, CURRENT_TIMESTAMP, false),
(10, 1, 5, 'Então Davi perguntou ao jovem que lhe trouxera as notícias: "Como você sabe que Saul e Jônatas estão mortos? "', 3, CURRENT_TIMESTAMP, false),
(10, 1, 6, 'O jovem respondeu: "Cheguei por acaso ao monte Gilboa, e lá estava Saul, apoiado em sua lança. Os carros de guerra e os oficiais da cavalaria estavam a ponto de alcançá-lo.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 7, 'Quando ele se virou e me viu, chamou-me, gritando, e eu disse: ‘Estou aqui’ ".', 3, CURRENT_TIMESTAMP, false),
(10, 1, 8, '"Ele me perguntou: ‘Quem é você? ’ " ‘Sou um amalequita’, respondi.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 9, '"Então ele me ordenou: ‘Venha aqui e mate-me! Estou na angústia da morte, mas ainda vivo’.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 10, '"Por isso aproximei-me dele e o matei, pois sabia que ele não sobreviveria ao ferimento. Peguei a coroa e o bracelete dele e trouxe-os para ti, meu senhor. "', 3, CURRENT_TIMESTAMP, false),
(10, 1, 11, 'Então Davi rasgou suas vestes; e os homens que estavam com ele fizeram o mesmo.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 12, 'E lamentaram, chorando e jejuando até o fim da tarde, por Saul e por seu filho Jônatas, pelo exército do Senhor e pelo povo de Israel, porque muitos haviam sido mortos à espada.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 13, 'E Davi perguntou ao jovem que lhe trouxera as notícias: "De onde você é? " E ele respondeu: "Sou filho de um estrangeiro, sou amalequita".', 3, CURRENT_TIMESTAMP, false),
(10, 1, 14, 'Davi lhe perguntou: "Como você não temeu levantar a mão para matar o ungido do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(10, 1, 15, 'Então Davi chamou um dos seus soldados e disse-lhe: "Venha aqui e mate-o! " O servo o feriu, e o homem morreu.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 16, 'Davi tinha dito ao jovem: "Você é responsável por sua própria morte. Sua boca testemunhou contra você, quando disse: ‘Matei o ungido do Senhor’ ".', 3, CURRENT_TIMESTAMP, false),
(10, 1, 17, 'Davi cantou este lamento sobre Saul e seu filho Jônatas,', 3, CURRENT_TIMESTAMP, false),
(10, 1, 18, 'e ordenou que se ensinasse aos homens de Judá este Lamento do Arco, que foi registrado no Livro de Jasar:', 3, CURRENT_TIMESTAMP, false),
(10, 1, 19, '"O seu esplendor, ó Israel, está morto sobre os seus montes. Como caíram os guerreiros!', 3, CURRENT_TIMESTAMP, false),
(10, 1, 20, '"Não conte isso em Gate, não o proclame nas ruas de Ascalom, para que não se alegrem as filhas dos filisteus nem exultem as filhas dos incircuncisos.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 21, '"Ó colinas de Gilboa, nunca mais haja orvalho nem chuva sobre vocês, nem campos que produzam trigo para as ofertas. Porque ali foi profanado o escudo dos guerreiros, o escudo de Saul, que nunca mais será polido com óleo.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 22, 'Do sangue dos mortos, da carne dos guerreiros, o arco de Jônatas nunca recuou, a espada de Saul sempre cumpriu a sua tarefa.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 23, '"Saul e Jônatas, mui amados, nem na vida nem na morte foram separados. Eram mais ágeis que as águias, mais fortes que os leões.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 24, '"Chorem por Saul, ó filhas de Israel! Chorem aquele que as vestia de rubros ornamentos, e suas roupas enfeitava com adornos de ouro.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 25, '"Como caíram os guerreiros no meio da batalha! Jônatas está morto sobre os montes de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 1, 26, 'Como estou triste por você, Jônatas, meu irmão! Como eu lhe queria bem! Sua amizade me era mais preciosa que o amor das mulheres!', 3, CURRENT_TIMESTAMP, false),
(10, 1, 27, '"Caíram os guerreiros! As armas de guerra foram destruídas! "', 3, CURRENT_TIMESTAMP, false),
(10, 2, 1, 'Passado algum tempo, Davi perguntou ao Senhor: "Devo ir para uma das cidades de Judá? " O Senhor respondeu que sim, e Davi perguntou para qual delas. "Para Hebrom", respondeu o Senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 2, 'Então Davi foi para Hebrom com suas duas mulheres, Ainoã, de Jezreel e Abigail, viúva de Nabal, o carmelita.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 3, 'Davi também levou os homens que o acompanhavam, cada um com sua família, e estabeleceram-se em Hebrom e nos povoados vizinhos.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 4, 'Então os homens de Judá foram a Hebrom e ali ungiram Davi rei da tribo de Judá. Informado de que os habitantes de Jabes-Gileade tinham sepultado Saul,', 3, CURRENT_TIMESTAMP, false),
(10, 2, 5, 'Davi enviou-lhes mensageiros que lhes disseram: "O Senhor os abençoe pelo seu ato de lealdade, ao sepultar Saul, seu rei.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 6, 'Seja o Senhor leal e fiel para com vocês. Também eu firmarei minha amizade com vocês, por terem feito essa boa ação.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 7, 'Mas, agora, sejam fortes e corajosos, pois Saul, seu senhor, está morto, e já fui ungido rei pela tribo de Judá".', 3, CURRENT_TIMESTAMP, false),
(10, 2, 8, 'Enquanto isso, Abner, filho de Ner, comandante do exército de Saul, levou Is-Bosete, filho de Saul, a Maanaim,', 3, CURRENT_TIMESTAMP, false),
(10, 2, 9, 'onde o proclamou rei sobre Gileade, Assuri, Jezreel, Efraim, Benjamim e sobre todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 10, 'Is-Bosete, filho de Saul, tinha quarenta anos de idade quando começou a reinar em Israel, e reinou dois anos. A tribo de Judá, entretanto, seguia Davi,', 3, CURRENT_TIMESTAMP, false),
(10, 2, 11, 'que a governou por sete anos e seis meses, em Hebrom.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 12, 'Abner, filho de Ner, e os soldados de Is-Bosete, filho de Saul, partiram de Maanaim e marcharam para Gibeom.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 13, 'Joabe, filho de Zeruia, e os soldados de Davi foram ao encontro deles no açude de Gibeom. Um grupo posicionou-se num lado do açude, o outro grupo, no lado oposto.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 14, 'Então Abner disse a Joabe: "Vamos fazer alguns soldados lutarem diante de nós". Joabe respondeu: "De acordo".', 3, CURRENT_TIMESTAMP, false),
(10, 2, 15, 'Então doze soldados aliados de Benjamim e Is-Bosete, filho de Saul, atravessaram o açude para enfrentar doze dos soldados aliados de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 16, 'Cada soldado pegou o adversário pela cabeça e fincou-lhe o punhal no lado, e juntos caíram mortos. Por isso aquele lugar, situado em Gibeom, foi chamado Helcate-Hazurim.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 17, 'Houve uma violenta batalha naquele dia, e Abner e os soldados de Israel foram derrotados pelos soldados de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 18, 'Estavam lá Joabe, Abisai e Asael, os três filhos de Zeruia. E Asael, que corria como uma gazela em terreno plano,', 3, CURRENT_TIMESTAMP, false),
(10, 2, 19, 'perseguiu Abner, sem se desviar nem para a direita nem para a esquerda.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 20, 'Abner olhou para trás e perguntou: "É você, Asael? " "Sou eu", respondeu ele.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 21, 'Disse-lhe então Abner: "É melhor você sair para a direita ou para a esquerda, capturar um dos soldados e ficar com as armas dele". Mas Asael não quis parar de persegui-lo.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 22, 'Então Abner advertiu Asael mais uma vez: "Pare de me perseguir! Não quero matá-lo. Como poderia olhar seu irmão Joabe nos olhos de novo? "', 3, CURRENT_TIMESTAMP, false),
(10, 2, 23, 'Como, porém, Asael, não desistiu de persegui-lo, Abner cravou no estômago dele a ponta da lança, que saiu pelas costas. E ele caiu, morrendo ali mesmo. E paravam todos os que chegavam ao lugar onde Asael estava caído.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 24, 'Então Joabe e Abisai perseguiram Abner. Ao pôr-do-sol, chegaram à colina de Amá, defronte de Gia, no caminho para o deserto de Gibeom.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 25, 'Os soldados de Benjamim, seguindo Abner, reuniram-se formando um só grupo e ocuparam o alto de uma colina.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 26, 'Então Abner gritou para Joabe: "O derramamento de sangue vai continuar? Não vê que isso vai trazer amargura? Quando é que você vai mandar o seu exército parar de perseguir os seus irmãos? "', 3, CURRENT_TIMESTAMP, false),
(10, 2, 27, 'Respondeu Joabe: "Juro pelo nome de Deus, que se você não tivesse falado, o meu exército perseguiria os seus irmãos até de manhã".', 3, CURRENT_TIMESTAMP, false),
(10, 2, 28, 'Então Joabe tocou a trombeta, e o exército parou de perseguir Israel e de lutar.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 29, 'Abner e seus soldados marcharam pela Arabá durante toda a noite. Atravessaram o Jordão, marcharam durante a manhã inteira e chegaram a Maanaim.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 30, 'Quando Joabe voltou da perseguição a Abner, reuniu todo o exército. E viram que faltavam dezenove soldados, além de Asael.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 31, 'Mas os soldados de Davi tinham matado trezentos e sessenta benjamitas que estavam com Abner.', 3, CURRENT_TIMESTAMP, false),
(10, 2, 32, 'Levaram Asael e o sepultaram no túmulo de seu pai, em Belém. Depois disso, Joabe e seus soldados marcharam durante toda a noite e chegaram a Hebrom ao amanhecer.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 1, 'A guerra entre as famílias de Saul e Davi durou muito tempo. Davi tornava-se cada vez mais forte, enquanto que a família de Saul se enfraquecia.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 2, 'Estes foram os filhos de Davi nascidos em Hebrom: O seu filho mais velho era Amnom, filho de Ainoã, de Jezreel;', 3, CURRENT_TIMESTAMP, false),
(10, 3, 3, 'o segundo, Quileabe, de Abigail, viúva de Nabal, de Carmelo; o terceiro, Absalão, de Maaca, filha de Talmai, rei de Gesur;', 3, CURRENT_TIMESTAMP, false),
(10, 3, 4, 'o quarto, Adonias, de Hagite; o quinto, Sefatias, de Abital;', 3, CURRENT_TIMESTAMP, false),
(10, 3, 5, 'e o sexto, Itreão, de sua mulher Eglá. Esses foram os filhos de Davi que lhe nasceram em Hebrom.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 6, 'Enquanto transcorria a guerra entre as famílias de Saul e de Davi, Abner foi se tornando poderoso na família de Saul.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 7, 'Saul tivera uma concubina chamada Rispa, filha de Aiá. Certa vez Is-Bosete perguntou a Abner: "Por que você se deitou com a concubina de meu pai? "', 3, CURRENT_TIMESTAMP, false),
(10, 3, 8, 'Abner ficou furioso com a pergunta de Is-Bosete e exclamou: "Por acaso eu sou um cão a serviço de Judá? Até agora tenho sido leal à família de Saul, seu pai, e aos parentes e amigos dele, e não deixei que você caísse nas mãos de Davi; e agora você me acusa de um delito envolvendo esta mulher!', 3, CURRENT_TIMESTAMP, false),
(10, 3, 9, 'Que Deus me castigue com todo rigor, se eu não fizer por Davi o que o Senhor lhe prometeu sob juramento,', 3, CURRENT_TIMESTAMP, false),
(10, 3, 10, 'tirar o reino da família de Saul e estabelecer o trono de Davi sobre Israel e Judá, de Dã a Berseba".', 3, CURRENT_TIMESTAMP, false),
(10, 3, 11, 'Is-Bosete não respondeu nada a Abner, pois tinha medo dele.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 12, 'Então Abner enviou mensageiros a Davi com esta proposta: "A quem pertence esta terra? Faze um acordo comigo e eu te ajudarei a conseguir o apoio de todo o Israel".', 3, CURRENT_TIMESTAMP, false),
(10, 3, 13, '"Está bem", disse Davi. "Farei um acordo com você, mas com uma condição: não compareça à minha presença sem trazer-me Mical, filha de Saul, quando você vier me ver. "', 3, CURRENT_TIMESTAMP, false),
(10, 3, 14, 'E Davi enviou mensageiros a Is-Bosete, filho de Saul, exigindo: "Entregue-me minha mulher Mical, com quem me casei pelo preço de cem prepúcios de filisteus".', 3, CURRENT_TIMESTAMP, false),
(10, 3, 15, 'Diante disso, Is-Bosete mandou que a tirassem do seu marido Paltiel, filho de Laís.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 16, 'Mas Paltiel foi atrás dela, e a seguiu chorando até Baurim. Então Abner ordenou-lhe que voltasse para casa; e ele voltou.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 17, 'Nesse meio tempo, Abner enviou esta mensagem às autoridades de Israel: "Já faz algum tempo que vocês querem Davi como rei.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 18, 'Agora é o momento de agir! Porque o Senhor prometeu a Davi: ‘Por meio de Davi, meu servo, livrarei Israel do poder dos filisteus e de todos os seus inimigos’ ".', 3, CURRENT_TIMESTAMP, false),
(10, 3, 19, 'Abner também falou pessoalmente com os benjamitas. Depois foi a Hebrom dizer a Davi tudo o que Israel e a tribo de Benjamim haviam aprovado.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 20, 'Quando Abner, acompanhado de vinte homens, apresentou-se a Davi em Hebrom, este ofereceu um banquete para ele e para os homens que o acompanhavam.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 21, 'Disse então Abner a Davi: "Deixa que eu me vá e reúna todo o Israel, meu senhor, para que façam um acordo contigo, ó rei, e reines sobre tudo o que desejares". Davi o deixou ir, e ele se foi em paz.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 22, 'Naquele momento, os soldados de Davi e Joabe voltavam de um ataque, trazendo muitos bens. Abner, porém, já não estava com Davi em Hebrom, porque Davi o tinha deixado partir em paz.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 23, 'Quando Joabe chegou com todo o seu exército, contaram-lhe que Abner, filho de Ner, se apresentara ao rei, que o tinha deixado ir em paz.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 24, 'Então Joabe foi falar com o rei e lhe disse: "Que foi que fizeste? Abner veio à tua presença e o deixaste ir?', 3, CURRENT_TIMESTAMP, false),
(10, 3, 25, 'Conheces Abner, filho de Ner; ele veio para enganá-lo, observar os teus movimentos e descobrir tudo o que estás fazendo".', 3, CURRENT_TIMESTAMP, false),
(10, 3, 26, 'Saindo da presença de Davi, Joabe enviou mensageiros atrás de Abner, e eles o trouxeram de volta, desde a cisterna de Sirá. Mas Davi não ficou sabendo disso.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 27, 'Quando Abner retornou a Hebrom, Joabe o chamou à parte, na porta da cidade, sob o pretexto de falar-lhe em particular, e ali mesmo o feriu no estômago. E Abner morreu por ter derramado o sangue de Asael, irmão de Joabe.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 28, 'Mais tarde, quando Davi soube o que tinha acontecido, disse: "Eu e o meu reino, perante o Senhor, somos para sempre inocentes do sangue de Abner, filho de Ner.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 29, 'Caia a responsabilidade pela morte dele sobre a cabeça de Joabe e de toda a sua família! Jamais falte entre os seus descendentes quem sofra fluxo ou lepra, quem use muletas, quem morra pela espada, ou quem passe fome".', 3, CURRENT_TIMESTAMP, false),
(10, 3, 30, 'Assim, Joabe e seu irmão Abisai mataram Abner porque ele havia matado Asael, irmão deles, na batalha de Gibeom.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 31, 'Então Davi disse a Joabe e a todo o exército que o acompanhava: "Rasguem suas vestes, vistam roupas de luto e vão chorando à frente de Abner". E o rei Davi seguiu atrás da maca que levava o corpo.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 32, 'Enterraram-no em Hebrom, e o rei chorou em alta voz junto ao túmulo de Abner, como também todo o povo.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 33, 'Então o rei cantou este lamento por Abner: "Por que morreu Abner como morrem os insensatos?', 3, CURRENT_TIMESTAMP, false),
(10, 3, 34, 'Suas mãos não estavam algemadas, nem seus pés acorrentados. Você caiu como quem cai perante homens perversos". E todo o povo chorou ainda mais por ele.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 35, 'Depois, quando o povo insistiu com Davi que comesse alguma coisa enquanto ainda era dia, Davi fez este juramento: "Deus me castigue com todo rigor, caso eu prove pão ou qualquer outra coisa antes do pôr-do-sol! "', 3, CURRENT_TIMESTAMP, false),
(10, 3, 36, 'Todo o povo ouviu isso e aprovou; de fato, tudo o que o rei fazia o povo aprovava.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 37, 'Assim, naquele dia, todo o povo e todo o Israel reconheceram que o rei não tivera participação no assassinato de Abner, filho de Ner.', 3, CURRENT_TIMESTAMP, false),
(10, 3, 38, 'Então o rei disse aos seus conselheiros: "Não percebem que caiu hoje em Israel um líder, um grande homem?', 3, CURRENT_TIMESTAMP, false),
(10, 3, 39, 'Embora rei ungido, ainda sou fraco, e esses filhos de Zeruia são mais fortes do que eu. Que o Senhor retribua ao malfeitor de acordo com as suas más obras! "', 3, CURRENT_TIMESTAMP, false),
(10, 4, 1, 'Ao saber que Abner havia morrido em Hebrom, Is-Bosete, filho de Saul, perdeu a coragem, e todo Israel ficou alarmado.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 2, 'Ora, o filho de Saul tinha a seu serviço dois líderes de grupos de ataque. Um deles chamava-se Baaná e o outro, Recabe; ambos filhos de Rimom, de Beerote, da tribo de Benjamim; a cidade de Beerote era considerada parte de Benjamim.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 3, 'O povo de Beerote fugiu para Gitaim e até hoje vive ali como estrangeiro.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 4, '( Jônatas, filho de Saul, tinha um filho aleijado dos pés. Ele tinha cinco anos de idade quando chegou a notícia de Jezreel de que Saul e Jônatas haviam morrido. Sua ama o apanhou e fugiu, mas, na pressa, ele o deixou cair e ele ficou manco. Seu nome era Mefibosete. )', 3, CURRENT_TIMESTAMP, false),
(10, 4, 5, 'Aconteceu então que Recabe e Baaná, filhos de Rimom, de Beerote, foram à casa de Is-Bosete na hora mais quente do dia, na hora do seu descanso do meio-dia.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 6, 'Os dois entraram na casa como se fossem buscar trigo, transpassaram-lhe o estômago e depois fugiram.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 7, 'Eles haviam entrado na casa enquanto Is-Bosete estava deitado, em seu quarto. Depois de o transpassarem e o matarem, cortaram-lhe a cabeça. E levando-a consigo, viajaram toda a noite pela rota da Arabá.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 8, 'Levaram a cabeça de Is-Bosete a Davi, em Hebrom, e disseram-lhe: "Aqui está a cabeça de Is-Bosete, filho de Saul, teu inimigo, que tentou tirar-te a vida. Hoje o Senhor vingou o nosso rei e senhor, de Saul e de sua descendência".', 3, CURRENT_TIMESTAMP, false),
(10, 4, 9, 'Davi respondeu a Recabe e a Baaná, seu irmão, filhos de Rimom, de Beerote: "Juro pelo nome do Senhor, que me tem livrado de todas as aflições.', 3, CURRENT_TIMESTAMP, false),
(10, 4, 10, 'Quando um homem me disse que Saul estava morto, pensando que me trazia boa notícia, eu o agarrei e o matei em Ziclague, como recompensa pela notícia que trouxe!', 3, CURRENT_TIMESTAMP, false),
(10, 4, 11, 'Muito mais agora, que homens ímpios mataram um inocente em sua própria casa e em sua própria cama! Vou castigá-los e eliminá-los da face da terra porque vocês fizeram correr o sangue dele! "', 3, CURRENT_TIMESTAMP, false),
(10, 4, 12, 'Então Davi ordenou a seus soldados, e eles os mataram. E cortaram as mãos e os pés deles e penduraram os corpos junto ao açude de Hebrom. Mas sepultaram a cabeça de Is-Bosete no túmulo de Abner, em Hebrom.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 1, 'Representantes de todas as tribos de Israel foram dizer a Davi, em Hebrom: "Somos sangue do teu sangue.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 2, 'No passado, mesmo quando Saul era rei, eras tu quem liderava Israel em suas batalhas. E o Senhor te disse: ‘Você pastoreará o meu povo Israel, e será o seu governante’ ".', 3, CURRENT_TIMESTAMP, false),
(10, 5, 3, 'Então todas as autoridades de Israel foram ao encontro do rei Davi em Hebrom, e ele fez um acordo com eles em Hebrom perante o Senhor, e eles ungiram Davi rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 4, 'Davi tinha trinta anos de idade quando começou a reinar, e reinou durante quarenta anos.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 5, 'Em Hebrom, reinou sobre Judá sete anos e meio, e em Jerusalém reinou sobre todo o Israel e Judá trinta e três anos.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 6, 'O rei e seus soldados marcharam para Jerusalém para atacar os jebuseus que viviam lá. E os jebuseus disseram a Davi: "Você não entrará aqui! Até os cegos e os aleijados podem se defender de você". Eles achavam que Davi não conseguiria entrar,', 3, CURRENT_TIMESTAMP, false),
(10, 5, 7, 'mas, Davi conquistou a fortaleza de Sião, que veio a ser a cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 8, 'Naquele dia disse Davi: "Quem quiser vencer os jebuseus terá que utilizar a passagem de água para chegar àqueles cegos e aleijados, inimigos de Davi". É por isso que dizem: "Os ‘cegos e aleijados’ não entrarão no palácio".', 3, CURRENT_TIMESTAMP, false),
(10, 5, 9, 'Davi passou a morar na fortaleza e chamou-a cidade de Davi. Construiu defesas na parte interna da cidade desde os muros de arrimo.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 10, 'E foi se tornando cada vez mais poderoso, pois o Senhor Deus dos Exércitos estava com ele.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 11, 'Pouco depois Hirão, rei de Tiro, enviou a Davi uma delegação, que trouxe toras de cedro, e também carpinteiros e pedreiros que construíram um palácio para Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 12, 'Então Davi teve certeza de que o Senhor o confirmara como rei de Israel e que seu reino estava prosperando por amor de seu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 13, 'Depois de mudar-se de Hebrom para Jerusalém, Davi tomou mais concubinas e esposas, e gerou mais filhos e filhas.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 14, 'Estes são os nomes dos que lhe nasceram ali: Samua, Sobabe, Natã, Salomão,', 3, CURRENT_TIMESTAMP, false),
(10, 5, 15, 'Ibar, Elisua, Nefegue, Jafia,', 3, CURRENT_TIMESTAMP, false),
(10, 5, 16, 'Elisama, Eliada e Elifelete.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 17, 'Ao saber que Davi tinha sido ungido rei de Israel, os filisteus foram com todo o exército prendê-lo, mas Davi soube disso e foi para a fortaleza.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 18, 'Tendo os filisteus se espalhado pelo vale de Refaim,', 3, CURRENT_TIMESTAMP, false),
(10, 5, 19, 'Davi perguntou ao Senhor: "Devo atacar os filisteus? Tu os entregarás nas minhas mãos? " O Senhor lhe respondeu: "Vá, eu os entregarei nas suas mãos".', 3, CURRENT_TIMESTAMP, false),
(10, 5, 20, 'Então Davi foi a Baal-Perazim e lá os derrotou. E disse: "Assim como as águas de uma enchente causam destruição, pelas minhas mãos o Senhor destruiu os meus inimigos diante de mim". Então aquele lugar passou a ser chamado Baal-Perazim.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 21, 'Como os filisteus haviam abandonado os seus ídolos ali, Davi e seus soldados os apanharam.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 22, 'Mais uma vez os filisteus marcharam e se espalharam pelo vale de Refaim;', 3, CURRENT_TIMESTAMP, false),
(10, 5, 23, 'então Davi consultou o Senhor de novo, que lhe respondeu: "Não ataque pela frente, mas dê a volta por trás deles e ataque-os em frente das amoreiras.', 3, CURRENT_TIMESTAMP, false),
(10, 5, 24, 'Assim que você ouvir um som de passos por cima das amoreiras, saia rapidamente, pois este é o sinal de que o Senhor saiu à sua frente para ferir o exército filisteu".', 3, CURRENT_TIMESTAMP, false),
(10, 5, 25, 'Davi fez como o Senhor lhe tinha ordenado, e derrotou os filisteus por todo o caminho, desde Gibeom até Gezer.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 1, 'De novo Davi reuniu os melhores guerreiros de Israel, trinta mil ao todo.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 2, 'Ele e todos os que o acompanhavam partiram para Baalim, em Judá, para buscar a arca de Deus, arca sobre a qual é invocado o nome do Senhor dos Exércitos, entronizado entre os querubins acima dela.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 3, 'Puseram a arca de Deus num carroção novo e a levaram da casa de Abinadabe, na colina. Uzá e Aiô, filhos de Abinadabe, conduziam o carroção', 3, CURRENT_TIMESTAMP, false),
(10, 6, 4, 'com a arca de Deus; e Aiô andava na frente dela.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 5, 'Davi e todos os israelitas iam cantando e dançando perante o Senhor, ao som de todo o tipo de instrumentos de pinho, harpas, liras, tamborins, chocalhos e címbalos.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 6, 'Quando chegaram à eira de Nacom, Uzá esticou o braço e segurou a arca de Deus, porque os bois haviam tropeçado.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 7, 'A ira do Senhor acendeu-se contra Uzá por seu ato de irreverência. Por isso Deus o feriu, e ele morreu ali mesmo, ao lado da arca de Deus.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 8, 'Davi ficou contrariado porque o Senhor, em sua ira, havia fulminado Uzá. Até hoje aquele lugar é chamado Perez-Uzá.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 9, 'Naquele dia, Davi teve medo do Senhor e se perguntou: "Como vou conseguir levar a arca do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(10, 6, 10, 'Por isso ele desistiu de levar a arca do Senhor para a cidade de Davi. Em vez disso, levou-a para a casa de Obede-Edom, de Gate.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 11, 'A arca do Senhor ficou na casa dele por três meses, e o Senhor o abençoou e a toda a sua família.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 12, 'E disseram ao rei Davi: "O Senhor tem abençoado a família de Obede-Edom e tudo o que ele possui, por causa da arca de Deus". Então Davi, com grande festa, foi à casa de Obede-Edom e ordenou que levassem a arca de Deus para a cidade de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 13, 'Quando os que carregavam a arca do Senhor davam seis passos, ele sacrificava um boi e um novilho gordo.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 14, 'Davi, vestindo o colete sacerdotal de linho, foi dançando com todas as suas forças perante o Senhor,', 3, CURRENT_TIMESTAMP, false),
(10, 6, 15, 'enquanto ele e todos os israelitas levavam a arca do Senhor ao som de gritos de alegria e de trombetas.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 16, 'Aconteceu que, entrando a arca do Senhor na cidade de Davi, Mical, filha de Saul, observava de uma janela. E, ao ver o rei Davi dançando e comemorando perante o Senhor, ela o desprezou em seu coração.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 17, 'Eles trouxeram a arca do Senhor e a colocaram na tenda que Davi lhe havia preparado; e Davi ofereceu holocaustos e sacrifícios de comunhão perante o Senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 18, 'Após oferecer os holocaustos e os sacrifícios de comunhão, ele abençoou o povo em nome do Senhor dos Exércitos,', 3, CURRENT_TIMESTAMP, false),
(10, 6, 19, 'e deu um pão, um bolo de tâmaras e um bolo de uvas passas a cada homem e a cada mulher israelita. Então todo o povo partiu, cada um para a sua casa.', 3, CURRENT_TIMESTAMP, false),
(10, 6, 20, 'Voltando Davi para casa para abençoar sua família, Mical, filha de Saul, saiu ao seu encontro e lhe disse: "Como o rei de Israel se destacou hoje, tirando o manto na frente das escravas de seus servos, como um homem vulgar! "', 3, CURRENT_TIMESTAMP, false),
(10, 6, 21, 'Mas Davi disse a Mical: "Foi perante o Senhor que eu dancei, perante aquele que me escolheu em lugar de seu pai ou de qualquer outro da família dele, quando me designou soberano sobre o povo do Senhor, sobre Israel; perante o Senhor celebrarei', 3, CURRENT_TIMESTAMP, false),
(10, 6, 22, 'e me rebaixarei ainda mais, e me humilharei aos meus próprios olhos. Mas serei honrado por essas escravas que você mencionou".', 3, CURRENT_TIMESTAMP, false),
(10, 6, 23, 'E até o dia de sua morte, Mical, filha de Saul, jamais teve filhos.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 1, 'O rei Davi já morava em seu palácio e o Senhor lhe dera descanso de todos os seus inimigos ao redor.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 2, 'Certo dia ele disse ao profeta Natã: "Aqui estou eu, morando num palácio de cedro, enquanto a arca do Senhor permanece numa simples tenda".', 3, CURRENT_TIMESTAMP, false),
(10, 7, 3, 'Natã respondeu ao rei: "Faze o que tiveres em mente, pois o Senhor está contigo".', 3, CURRENT_TIMESTAMP, false),
(10, 7, 4, 'E naquela mesma noite o Senhor falou a Natã:', 3, CURRENT_TIMESTAMP, false),
(10, 7, 5, '"Vá dizer a meu servo Davi que assim diz o Senhor: Você construirá uma casa para eu morar?', 3, CURRENT_TIMESTAMP, false),
(10, 7, 6, 'Não tenho morado em nenhuma casa desde o dia em que tirei os israelitas do Egito. Tenho ido de uma tenda para outra, de um tabernáculo para outro.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 7, 'Por onde tenho acompanhado os israelitas, alguma vez perguntei a algum líder deles, a quem ordenei que pastoreasse o meu povo Israel: "Por que você não me construiu um templo de cedro? "', 3, CURRENT_TIMESTAMP, false),
(10, 7, 8, '"Agora, pois, diga ao meu servo Davi: Assim diz o Senhor dos Exércitos: Eu o tirei das pastagens, onde cuidava dos rebanhos, para ser o soberano do meu povo Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 9, 'Sempre estive com você por onde você andou, e eliminei todos os seus inimigos. Agora eu o farei tão famoso quanto os homens mais importantes da terra.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 10, 'E providenciarei um lugar para o meu povo Israel e os plantarei lá, para que tenham o seu próprio lar e não mais sejam incomodados. Povos ímpios não mais os oprimirão, como fizeram no início', 3, CURRENT_TIMESTAMP, false),
(10, 7, 11, 'e têm feito desde a época em que nomeei juízes sobre o meu povo Israel. Também subjugarei todos os seus inimigos. Saiba também que eu, o Senhor, lhe estabelecerei uma dinastia.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 12, 'Quando a sua vida chegar ao fim e você descansar com os seus antepassados, escolherei um dos seus filhos para sucedê-lo, um fruto do seu próprio corpo, e eu estabelecerei o reino dele.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 13, 'Será ele quem construirá um templo em honra do meu nome, e eu firmarei o trono dele para sempre.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 14, 'Eu serei seu pai, e ele será meu filho. Quando ele cometer algum erro, eu o punirei com o castigo dos homens, com açoites aplicados por homens.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 15, 'Mas nunca retirarei dele o meu amor, como retirei de Saul, a quem tirei do seu caminho.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 16, 'Quanto a você, sua dinastia e seu reino permanecerão para sempre diante de mim; o seu trono será estabelecido para sempre".', 3, CURRENT_TIMESTAMP, false),
(10, 7, 17, 'E Natã transmitiu a Davi tudo o que o Senhor lhe tinha falado e revelado.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 18, 'Então o rei Davi entrou no tabernáculo, assentou-se diante do Senhor, e orou: "Quem sou eu, ó Soberano Senhor, e o que é a minha família, para que me trouxesses a este ponto?', 3, CURRENT_TIMESTAMP, false),
(10, 7, 19, 'E, como se isso não bastasse para ti, ó Soberano Senhor, também falaste sobre o futuro da família deste teu servo. É assim que procedes com os homens, ó Soberano Senhor?', 3, CURRENT_TIMESTAMP, false),
(10, 7, 20, '"Que mais Davi poderá dizer-te? Tu conheces o teu servo, ó Soberano Senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 21, 'Por amor de tua palavra e de acordo com tua vontade, realizaste este feito grandioso e o revelaste ao teu servo.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 22, '"Quão grande és tu, ó Soberano Senhor! Não há ninguém como tu nem há outro Deus além de ti, conforme tudo o que sabemos.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 23, 'E quem é como o teu povo Israel, a única nação da terra que tu, ó Deus, resgataste para dela fazeres um povo para ti mesmo, e assim tornaste o teu nome famoso, realizaste grandes e impressionantes maravilhas ao expulsar nações e seus deuses de diante dessa mesma nação que libertaste do Egito?', 3, CURRENT_TIMESTAMP, false),
(10, 7, 24, 'Tu mesmo fizeste de Israel o teu povo particular para sempre, e tu, ó Senhor, te tornaste o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 25, '"Agora, Senhor Deus, confirma para sempre a promessa que fizeste a respeito de teu servo e de sua descendência. Faze conforme prometeste,', 3, CURRENT_TIMESTAMP, false),
(10, 7, 26, 'para que o teu nome seja engrandecido para sempre e os homens digam: ‘O Senhor dos Exércitos é o Deus de Israel! ’ E a descendência de teu servo Davi se manterá firme diante de ti.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 27, '"Ó Senhor dos Exércitos, Deus de Israel, tu mesmo o revelaste a teu servo, quando disseste: ‘Estabelecerei uma dinastia para você’. Por isso o teu servo achou coragem para orar a ti.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 28, 'Ó Soberano Senhor, tu és Deus! Tuas palavras são verdadeiras, e tu fizeste essa boa promessa a teu servo.', 3, CURRENT_TIMESTAMP, false),
(10, 7, 29, 'Agora, por tua bondade, abençoa a família de teu servo, para que ela continue para sempre na tua presença. Tu, ó Soberano Senhor, o prometeste! E, abençoada por ti, bendita será para sempre a família de teu servo".', 3, CURRENT_TIMESTAMP, false),
(10, 8, 1, 'Depois disso, Davi derrotou os filisteus e os subjugou, e tirou do controle deles Metegue-Amá.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 2, 'Davi derrotou também os moabitas. Ele os fez deitarem-se no chão e mandou que os medissem com uma corda; os moabitas que ficavam dentro das duas primeiras medidas da corda foram mortos, mas os que ficavam dentro da terceira foram poupados. Assim, os moabitas ficaram sujeitos a Davi, pagando-lhe impostos.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 3, 'Além disso, Davi derrotou Hadadezer, filho de Reobe, rei de Zobá, quando Hadadezer tentava recuperar o controle na região do rio Eufrates.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 4, 'Davi se apossou de mil dos seus carros de guerra, sete mil cavaleiros e vinte mil soldados de infantaria. Ainda levou cem cavalos de carros de guerra, e aleijou todos o outros.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 5, 'Quando os arameus de Damasco vieram ajudar Hadadezer, rei de Zobá, Davi matou vinte e dois mil deles.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 6, 'Em seguida estabeleceu guarnições militares no reino dos arameus de Damasco, sujeitando-os a lhe pagarem impostos. E o Senhor dava vitórias a Davi aonde quer que ele fosse.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 7, 'Davi também levou para Jerusalém os escudos de ouro usados pelos oficiais de Hadadezer.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 8, 'De Tebá e Berotai, cidades que pertenciam a Hadadezer, o rei Davi levou grande quantidade de bronze.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 9, 'Quando Toú, rei de Hamate, soube que Davi tinha derrotado todo o exército de Hadadezer,', 3, CURRENT_TIMESTAMP, false),
(10, 8, 10, 'enviou seu filho Jorão ao rei Davi para saudá-lo e parabenizá-lo por sua vitória na batalha contra Hadadezer, que tinha estado em guerra com Toú. E, com Jorão, mandou todo tipo de utensílios de prata, de ouro e de bronze.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 11, 'O rei Davi consagrou esses utensílios ao Senhor, como fizera com a prata e com o ouro tomados de todas as nações que havia subjugado:', 3, CURRENT_TIMESTAMP, false),
(10, 8, 12, 'Edom e Moabe, os amonitas e os filisteus, e Amaleque. Também consagrou os bens tomados de Hadadezer, filho de Reobe, rei de Zobá.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 13, 'Davi ficou ainda mais famoso ao retornar da batalha em que matou dezoito mil edomitas no vale do Sal.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 14, 'Ele estabeleceu guarnições militares por todo o território de Edom, sujeitando todos os edomitas. O Senhor dava vitórias a Davi aonde quer que ele fosse.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 15, 'Davi reinou sobre todo o Israel, administrando o direito e a justiça a todo o seu povo.', 3, CURRENT_TIMESTAMP, false),
(10, 8, 16, 'Joabe, filho de Zeruia, era comandante do exército; Josafá, filho de Ailude, era o arquivista real;', 3, CURRENT_TIMESTAMP, false),
(10, 8, 17, 'Zadoque, filho de Aitube, e Aimeleque, filho de Abiatar, eram sacerdotes; Seraías era secretário;', 3, CURRENT_TIMESTAMP, false),
(10, 8, 18, 'Benaia, filho de Joiada, comandava os queretitas e os peletitas; e os filhos de Davi eram sacerdotes.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 1, 'Certa ocasião Davi perguntou: "Resta ainda alguém da família de Saul, a quem eu possa mostrar lealdade por causa de minha amizade com Jônatas? "', 3, CURRENT_TIMESTAMP, false),
(10, 9, 2, 'Então chamaram Ziba, um dos servos de Saul, para apresentar-se a Davi, e o rei lhe perguntou: "Você é Ziba? " "Sou teu servo", respondeu ele.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 3, 'Perguntou-lhe Davi: "Resta ainda alguém da família de Saul, a quem eu possa mostrar a lealdade de Deus? " Respondeu Ziba: "Ainda há um filho de Jônatas, aleijado dos pés".', 3, CURRENT_TIMESTAMP, false),
(10, 9, 4, '"Onde está ele? ", perguntou o rei. Ziba respondeu: "Na casa de Maquir, filho de Amiel, em Lo-Debar".', 3, CURRENT_TIMESTAMP, false),
(10, 9, 5, 'Então o rei Davi mandou trazê-lo de Lo-Debar.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 6, 'Quando Mefibosete, filho de Jônatas e neto de Saul, compareceu diante de Davi, prostrou-se, rosto em terra. "Mefibosete? ", perguntou Davi. Ele respondeu: "Sim, sou teu servo".', 3, CURRENT_TIMESTAMP, false),
(10, 9, 7, '"Não tenha medo", disse-lhe Davi, "pois é certo que eu tratarei com bondade por causa de minha amizade com Jônatas, seu pai. Vou devolver-lhe todas as terras que pertenciam a seu avô Saul; e você comerá sempre à minha mesa".', 3, CURRENT_TIMESTAMP, false),
(10, 9, 8, 'Mefibosete prostrou-se e disse: "Quem é o teu servo, para que te preocupes com um cão morto como eu? "', 3, CURRENT_TIMESTAMP, false),
(10, 9, 9, 'Então o rei convocou Ziba e disse-lhe: "Devolvi ao neto de Saul, seu senhor, tudo o que pertencia a ele e à família dele.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 10, 'Você, seus filhos e seus servos cultivarão a terra para ele. Você trará a colheita para que haja provisões na casa do neto de seu senhor. Mas, Mefibosete comerá sempre à minha mesa". Ziba tinha quinze filhos e vinte servos.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 11, 'Então Ziba disse ao rei: "O teu servo fará tudo o que o rei, meu senhor, ordenou". Assim, Mefibosete passou a comer à mesa de Davi como se fosse um dos seus filhos.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 12, 'Mefibosete tinha um filho ainda jovem chamado Mica. E todos os que moravam na casa de Ziba tornaram-se servos de Mefibosete.', 3, CURRENT_TIMESTAMP, false),
(10, 9, 13, 'Então Mefibosete foi morar em Jerusalém, pois passou a comer sempre à mesa do rei. E era aleijado dos pés.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 1, 'Algum tempo depois, o rei dos amonitas morreu, e seu filho Hanum foi o seu sucessor.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 2, 'Davi pensou: "Serei bondoso com Hanum, filho de Naás, como seu pai foi bondoso comigo". Então Davi enviou uma delegação para transmitir a Hanum seu pesar pela morte do pai. Mas, quando os mensageiros de Davi chegaram à terra dos amonitas,', 3, CURRENT_TIMESTAMP, false),
(10, 10, 3, 'os líderes amonitas disseram a Hanum, seu senhor: "Achas que Davi está honrando teu pai ao enviar mensageiros para expressar condolências? Não é nada disso! Davi os enviou como espiões para examinar a cidade e destruí-la".', 3, CURRENT_TIMESTAMP, false),
(10, 10, 4, 'Então Hanum prendeu os mensageiros de Davi, rapou metade da barba de cada um, cortou metade de suas roupas até as nádegas, e os mandou embora.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 5, 'Quando Davi soube disso, enviou mensageiros ao encontro deles, pois haviam sido profundamente humilhados, e lhes mandou dizer: "Fiquem em Jericó até que a barba cresça, e então voltem para casa".', 3, CURRENT_TIMESTAMP, false),
(10, 10, 6, 'Vendo que tinham atraído sobre si o ódio de Davi, os amonitas contrataram vinte mil soldados de infantaria dos arameus de Bete-Reobe e de Zobá, e mais mil homens do rei de Maaca e doze mil dos homens de Tobe.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 7, 'Ao saber disso, Davi ordenou a Joabe que marchasse com todo o exército.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 8, 'Os amonitas saíram e se puseram em posição de combate na entrada da cidade, e os arameus de Zobá e de Reobe e os homens de Tobe e de Maaca posicionaram-se em campo aberto.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 9, 'Vendo Joabe que estava cercado pelas linhas de combate, escolheu alguns dos melhores soldados de Israel e os posicionou contra os arameus.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 10, 'Pôs o restante dos homens sob o comando de seu irmão Abisai e os posicionou contra os amonitas.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 11, 'E Joabe disse a Abisai: "Se os arameus forem fortes demais para mim, venha me ajudar; mas, se os amonitas forem fortes demais para você, eu irei ajudá-lo.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 12, 'Seja forte e lutemos com bravura pelo nosso povo e pelas cidades do nosso Deus. E que o Senhor faça o que for de sua vontade".', 3, CURRENT_TIMESTAMP, false),
(10, 10, 13, 'Então Joabe e seus soldados avançaram contra os arameus, que fugiram dele.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 14, 'Quando os amonitas viram que os arameus estavam fugindo de Joabe, também fugiram de seu irmão Abisai e entraram na cidade. Assim, Joabe parou a batalha contra os amonitas e voltou para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 15, 'Ao perceberem que haviam sido derrotados por Israel, os arameus tornaram a agrupar-se.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 16, 'Hadadezer mandou trazer os arameus que viviam do outro lado do Eufrates. Estes chegaram a Helã, tendo à frente Soboque, comandante do exército de Hadadezer.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 17, 'Informado disso, Davi reuniu todo o Israel, atravessou o Jordão e chegou a Helã. Os arameus estavam em posição de combate para enfrentá-lo,', 3, CURRENT_TIMESTAMP, false),
(10, 10, 18, 'mas acabaram fugindo de diante de Israel. E Davi matou setecentos condutores de carros de guerra e quarenta mil soldados de infantaria dos arameus. Soboque, o comandante do exército, também foi ferido e morreu ali mesmo.', 3, CURRENT_TIMESTAMP, false),
(10, 10, 19, 'Quando todos os reis vassalos de Hadadezer viram que tinham sido derrotados por Israel, fizeram a paz com os israelitas e sujeitaram-se a eles. E os arameus ficaram com medo de voltar a ajudar os amonitas.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 1, 'Na primavera, época em que os reis saíam para a guerra, Davi enviou para a batalha Joabe com seus oficiais e todo o exército de Israel; e eles derrotaram os amonitas e cercaram Rabá. Mas Davi permaneceu em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 2, 'Uma tarde Davi levantou-se da cama e foi passear pelo terraço do palácio. Do terraço viu uma mulher muito bonita tomando banho,', 3, CURRENT_TIMESTAMP, false),
(10, 11, 3, 'e mandou alguém procurar saber quem era ela. Disseram-lhe: "É Bate-Seba, filha de Eliã e mulher de Urias, o hitita".', 3, CURRENT_TIMESTAMP, false),
(10, 11, 4, 'Davi mandou que a trouxessem, e se deitou com ela, que havia acabado de se purificar da impureza da sua menstruação. Depois, voltou para casa.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 5, 'A mulher engravidou e mandou um recado a Davi, dizendo que estava grávida.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 6, 'Em face disso, Davi mandou esta mensagem a Joabe: "Envie-me Urias, o hitita". E Joabe o enviou.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 7, 'Quando Urias chegou, Davi perguntou-lhe como estavam Joabe e os soldados e como estava indo a guerra,', 3, CURRENT_TIMESTAMP, false),
(10, 11, 8, 'e lhe disse: "Vá descansar um pouco em sua casa". Urias saiu do palácio e logo lhe foi mandado um presente da parte do rei.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 9, 'Mas Urias dormiu na entrada do palácio, onde dormiam os guardas de seu senhor, e não foi para casa.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 10, 'Quando informaram a Davi que Urias não tinha ido para casa, ele lhe perguntou: "Depois da viagem que você fez, por que não foi para casa? "', 3, CURRENT_TIMESTAMP, false),
(10, 11, 11, 'Urias respondeu: "A arca e os homens de Israel e de Judá repousam em tendas; o meu senhor Joabe e os seus soldados estão acampados ao ar livre. Como poderia eu ir para casa para comer, beber e deitar-me com minha mulher? Juro por teu nome e por tua vida que não farei uma coisa dessas! "', 3, CURRENT_TIMESTAMP, false),
(10, 11, 12, 'Então Davi lhe disse: "Fique aqui mais um dia; amanhã eu o mandarei de volta". Urias ficou em Jerusalém, mas no dia seguinte', 3, CURRENT_TIMESTAMP, false),
(10, 11, 13, 'Davi o convidou para comer e beber, e o embriagou. À tarde, porém, Urias saiu para dormir em sua esteira onde os guardas de seu senhor dormiam; e não foi para casa.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 14, 'De manhã, Davi enviou uma carta a Joabe por meio de Urias.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 15, 'Nela escreveu: "Ponha Urias na linha de frente e deixe-o onde o combate estiver mais violento, para que seja ferido e morra".', 3, CURRENT_TIMESTAMP, false),
(10, 11, 16, 'Como Joabe tinha cercado a cidade, colocou Urias no lugar onde sabia que os inimigos eram mais fortes.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 17, 'Quando os homens da cidade saíram e lutaram contra Joabe, alguns dos oficiais da guarda de Davi morreram, e morreu também Urias, o hitita.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 18, 'Joabe enviou a Davi um relatório completo da batalha,', 3, CURRENT_TIMESTAMP, false),
(10, 11, 19, 'dando a seguinte instrução ao mensageiro: "Ao acabar de apresentar ao rei este relatório,', 3, CURRENT_TIMESTAMP, false),
(10, 11, 20, 'pode ser que o rei fique muito indignado e lhe pergunte: ‘Por que vocês se aproximaram tanto da cidade para combater? Não sabiam que eles atirariam flechas da muralha?', 3, CURRENT_TIMESTAMP, false),
(10, 11, 21, 'Em Tebes, quem matou Abimeleque, filho de Jerubesete? Não foi uma mulher que da muralha atirou-lhe uma pedra de moinho, e ele morreu? Por que vocês se aproximaram tanto da muralha? ’ Se ele perguntar isso, diga-lhe: E morreu também o teu servo Urias, o hitita".', 3, CURRENT_TIMESTAMP, false),
(10, 11, 22, 'O mensageiro partiu, e, ao chegar, contou a Davi tudo o que Joabe lhe havia mandado falar,', 3, CURRENT_TIMESTAMP, false),
(10, 11, 23, 'dizendo: "Eles nos sobrepujaram e saíram contra nós em campo aberto, mas nós os fizemos retroceder para a porta da cidade.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 24, 'Então os flecheiros atiraram do alto da muralha contra os teus servos, e mataram alguns deles. E morreu também o teu servo Urias, o hitita".', 3, CURRENT_TIMESTAMP, false),
(10, 11, 25, 'Davi mandou o mensageiro dizer a Joabe: "Não fique preocupado com isso, pois a espada não escolhe a quem devorar. Reforce o ataque à cidade até destruí-la". E ainda insistiu com o mensageiro que encorajasse Joabe.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 26, 'Quando a mulher de Urias soube que o seu marido havia morrido, ela chorou por ele.', 3, CURRENT_TIMESTAMP, false),
(10, 11, 27, 'Passado o luto, Davi mandou que a trouxessem para o palácio; ela se tornou sua mulher e teve um filho dele. Mas o que Davi fez desagradou ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 1, 'E o Senhor enviou a Davi o profeta Natã. Ao chegar, ele disse a Davi: "Dois homens viviam numa cidade, um era rico e o outro, pobre.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 2, 'O rico possuía muitas ovelhas e bois,', 3, CURRENT_TIMESTAMP, false),
(10, 12, 3, 'mas o pobre nada tinha, senão uma cordeirinha que havia comprado. Ele a criou, e ela cresceu com ele e com seus filhos. Ela comia junto dele, bebia do seu copo e até dormia em seus braços. Era como uma filha para ele.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 4, '"Certo dia, um viajante chegou à casa do rico, e este não quis pegar uma de suas próprias ovelhas ou do seus bois para preparar-lhe uma refeição. Em vez disso, preparou para o visitante a cordeira que pertencia ao pobre".', 3, CURRENT_TIMESTAMP, false),
(10, 12, 5, 'Então, Davi encheu-se de ira contra o homem e disse a Natã: "Juro pelo nome do Senhor que o homem que fez isso merece a morte!', 3, CURRENT_TIMESTAMP, false),
(10, 12, 6, 'Deverá pagar quatro vezes o preço da cordeira, porquanto agiu sem misericórdia".', 3, CURRENT_TIMESTAMP, false),
(10, 12, 7, 'Então Natã disse a Davi: "Você é esse homem! Assim diz o Senhor, o Deus de Israel: ‘Eu o ungi rei de Israel, e livrei-o das mãos de Saul.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 8, 'Dei-lhe a casa e as mulheres do seu senhor. Dei-lhe a nação de Israel e Judá. E, se tudo isso não fosse suficiente, eu lhe teria dado mais ainda.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 9, 'Por que você desprezou a palavra do Senhor, fazendo o que ele reprova? Você matou Urias, o hitita, com a espada dos amonitas e ficou com a mulher dele.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 10, 'Por isso, a espada nunca se afastará de sua família, pois você me desprezou e tomou a mulher de Urias, o hitita, para ser sua mulher’.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 11, '"Assim diz o Senhor: ‘De sua própria família trarei desgraça sobre você. Tomarei as suas mulheres diante dos seus próprios olhos e as darei a outro; e ele se deitará com elas em plena luz do dia.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 12, 'Você fez isso às escondidas, mas eu o farei diante de todo o Israel, em plena luz do dia’ ".', 3, CURRENT_TIMESTAMP, false),
(10, 12, 13, 'Então Davi disse a Natã: "Pequei contra o Senhor! " E Natã respondeu: "O Senhor perdoou o seu pecado. Você não morrerá.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 14, 'Entretanto, uma vez que você insultou o Senhor, o menino morrerá".', 3, CURRENT_TIMESTAMP, false),
(10, 12, 15, 'Depois que Natã foi para casa, o Senhor fez adoecer o filho que a mulher de Urias dera a Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 16, 'E Davi implorou a Deus em favor da criança. Ele jejuou e, entrando em casa, passou a noite deitado no chão.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 17, 'Os oficiais do palácio tentaram fazê-lo levantar-se do chão, mas ele não quis, e recusou comer.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 18, 'Sete dias depois a criança morreu. Os conselheiros de Davi estavam com medo de dizer-lhe que a criança estava morta, e comentavam: "Enquanto a criança ainda estava viva, falamos com ele, e ele não quis escutar-nos. Como vamos dizer-lhe que a criança morreu? Ele poderá cometer alguma loucura! "', 3, CURRENT_TIMESTAMP, false),
(10, 12, 19, 'Davi, percebendo que seus conselheiros cochichavam entre si, compreendeu que a criança estava morta e perguntou: "A criança morreu? " "Sim, morreu", responderam eles.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 20, 'Então Davi levantou-se do chão, lavou-se, perfumou-se e trocou de roupa. Depois entrou no santuário do Senhor e adorou. E voltando ao palácio, pediu que lhe preparassem uma refeição e comeu.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 21, 'Seus conselheiros lhe perguntaram: "Por que ages assim? Enquanto a criança estava viva, jejuaste e choraste; mas, agora que a criança está morta, te levantas e comes! "', 3, CURRENT_TIMESTAMP, false),
(10, 12, 22, 'Ele respondeu: "Enquanto a criança ainda estava viva, jejuei e chorei. Eu pensava: ‘Quem sabe? Talvez o Senhor tenha misericórdia de mim e deixe a criança viver’.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 23, 'Mas agora que ela morreu, por que deveria jejuar? Poderia eu trazê-la de volta à vida? Eu irei até ela, mas ela não voltará para mim".', 3, CURRENT_TIMESTAMP, false),
(10, 12, 24, 'Depois Davi consolou sua mulher Bate-Seba e deitou-se com ela, e ela teve um menino, a quem Davi deu o nome de Salomão. E o Senhor o amou', 3, CURRENT_TIMESTAMP, false),
(10, 12, 25, 'e, por isso, enviou o profeta Natã para dizer a Davi que, o menino deveria chamar-se Jedidias.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 26, 'Enquanto isso, Joabe atacou Rabá dos amonitas e conquistou a fortaleza real.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 27, 'Então mandou mensageiros a Davi, dizendo: "Lutei contra Rabá e apoderei-me dos seus reservatórios de água.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 28, 'Agora, convoca o restante do exército, cerca a cidade e conquista-a. Se não, eu terei a fama de havê-la conquistado".', 3, CURRENT_TIMESTAMP, false),
(10, 12, 29, 'Então, Davi convocou todo o exército, foi a Rabá, atacou a cidade e a conquistou.', 3, CURRENT_TIMESTAMP, false),
(10, 12, 30, 'A seguir tirou a coroa da cabeça de Milcom, uma coroa de ouro de trinta e cinco quilos; ornamentada com pedras preciosas. E ela foi colocada na cabeça de Davi. Ele levou uma grande quantidade de bens da cidade', 3, CURRENT_TIMESTAMP, false),
(10, 12, 31, 'e levou também os seus habitantes, designando-lhes trabalhos com serras, picaretas e machados, além da fabricação de tijolos. Davi fez assim com todas as cidades amonitas. Depois voltou com todo o seu exército para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 1, 'Depois de algum tempo, Amnom, filho de Davi, apaixonou-se por Tamar; ela era muito bonita e era irmã de Absalão, outro filho de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 2, 'Amnom ficou angustiado a ponto de adoecer por causa de sua meio-irmã Tamar, pois ela era virgem, e parecia-lhe impossível aproximar-se dela.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 3, 'Amnom tinha um amigo muito astuto chamado Jonadabe, filho de Siméia, irmão de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 4, 'Ele perguntou a Amnom: "Filho do rei, por que todo dia você está abatido? Quer me contar o que se passa? " Amnom lhe disse: "Estou apaixonado por Tamar, irmã de meu irmão Absalão".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 5, 'Então disse Jonadabe: "Vá para a cama e finja estar doente". "Quando seu pai vier visitá-lo, diga-lhe: Permite que minha irmã Tamar venha dar-me de comer. Gostaria que ela preparasse a comida aqui mesmo e me servisse. Assim poderei vê-la. "', 3, CURRENT_TIMESTAMP, false),
(10, 13, 6, 'Amnom atendeu e deitou-se na cama, fingindo-se doente. Quando o rei foi visitá-lo, Amnom lhe disse: "Eu gostaria que minha irmã Tamar viesse e preparasse dois bolos aqui mesmo e me servisse".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 7, 'Davi mandou dizer a Tamar no palácio: "Vá à casa de seu irmão Amnom e prepare algo para ele comer".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 8, 'Assim, Tamar foi à casa de seu irmão, que estava deitado. Ela amassou a farinha, preparou os bolos na presença dele e os assou.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 9, 'Depois pegou a assadeira e lhe serviu os bolos, mas ele não quis comer. Então Amnom deu ordem para que todos saíssem; depois que todos saíram,', 3, CURRENT_TIMESTAMP, false),
(10, 13, 10, 'Amnom disse a Tamar: "Traga os bolos e sirva-me aqui no meu quarto". Tamar levou os bolos que havia preparado ao quarto de seu irmão.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 11, 'Mas quando ela se aproximou para servi-lo, ele a agarrou e disse: "Deite-se comigo, minha irmã".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 12, 'Mas ela lhe disse: "Não, meu irmão! Não me faça essa violência. Não se faz uma coisa dessas em Israel! Não cometa essa loucura.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 13, 'O que seria de mim? Como eu poderia livrar-me da minha desonra? E o que seria de você? Você cairia em desgraça em Israel. Fale com o rei; ele deixará que eu me case com você".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 14, 'Mas Amnom não quis ouvir e, sendo mais forte que ela, violentou-a.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 15, 'Logo depois Amnom sentiu uma forte aversão por ela, mais forte que a paixão que sentira. E disse a ela: "Levante-se e saia! "', 3, CURRENT_TIMESTAMP, false),
(10, 13, 16, 'Mas ela lhe disse: "Não, meu irmão, mandar-me embora seria pior do que o mal que você já me fez". Ele, porém, não quis ouvi-la,', 3, CURRENT_TIMESTAMP, false),
(10, 13, 17, 'e chamando seu servo, disse-lhe: "Ponha esta mulher para fora daqui e tranque a porta".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 18, 'Então o servo a pôs para fora e trancou a porta. Ela estava vestindo uma túnica longa, pois esse era o tipo de roupa que as filhas virgens do rei usavam desde a puberdade.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 19, 'Tamar pôs cinza na cabeça, rasgou a túnica longa que estava usando e se pôs a caminho, com as mãos sobre a cabeça e chorando em alta voz.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 20, 'Absalão, seu irmão, lhe perguntou: "Seu irmão, Amnom, lhe fez algum mal? Agora, acalme-se, minha irmã; ele é seu irmão! Não se deixe dominar pela angústia". E Tamar, muito triste, ficou na casa de seu irmão Absalão.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 21, 'Ao saber de tudo isso, o rei Davi ficou furioso.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 22, 'E Absalão não falou nada com Amnom, nem bem, nem mal, embora o odiasse por ter violentado sua irmã Tamar.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 23, 'Dois anos depois, quando os tosquiadores de ovelhas de Absalão estavam em Baal-Hazor, perto da fronteira de Efraim, Absalão convidou todos os filhos do rei para se reunirem com ele.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 24, 'Absalão foi ao rei e lhe disse: "Eu, teu servo, estou tosquiando as ovelhas e gostaria que o rei e os seus conselheiros estivessem comigo".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 25, 'Respondeu o rei: "Não, meu filho. Não iremos todos, pois isso seria um peso para você". Embora Absalão insistisse, ele se recusou a ir, mas o abençoou.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 26, 'Então Absalão lhe disse: "Se não queres ir, permite, por favor, que o meu irmão Amnom vá conosco". O rei perguntou: "Mas, por que ele iria com você? "', 3, CURRENT_TIMESTAMP, false),
(10, 13, 27, 'Mas Absalão insistiu tanto que o rei acabou deixando que Amnom e os seus outros filhos fossem com ele.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 28, 'Absalão ordenou aos seus homens: "Ouçam! Quando Amnom estiver embriagado de vinho e eu disser: ‘Matem Amnom! ’, vocês o matarão. Não tenham medo; eu assumo a responsabilidade. Sejam fortes e corajosos! "', 3, CURRENT_TIMESTAMP, false),
(10, 13, 29, 'Assim os homens de Absalão mataram Amnom, obedecendo às suas ordens. Então todos os filhos do rei montaram em suas mulas e fugiram.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 30, 'Estando eles ainda a caminho, chegou a seguinte notícia ao rei: "Absalão matou todos os teus filhos; nenhum deles escapou".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 31, 'O rei levantou-se, rasgou as suas vestes, prostrou-se, e todos os conselheiros que estavam com ele também rasgaram as vestes.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 32, 'Mas, Jonadabe, filho de Siméia, irmão de Davi, disse: "Não pense o meu senhor que mataram todos os teus filhos. Somente Amnom foi morto. Essa era a intenção de Absalão desde o dia em que Amnom violentou Tamar, irmã dele.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 33, 'O rei, meu senhor, não deve acreditar que todos os seus filhos estão mortos. Apenas Amnom morreu".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 34, 'Enquanto isso, Absalão fugiu. Nesse meio tempo o sentinela viu muita gente que vinha pela estrada de Horonaim, descendo pela encosta da colina, e disse ao rei: "Vejo homens vindo pela estrada de Horonaim, na encosta da colina".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 35, 'E Jonadabe disse ao rei: "São os filhos do rei! Aconteceu como o teu servo disse".', 3, CURRENT_TIMESTAMP, false),
(10, 13, 36, 'Acabando de falar, os filhos do rei chegaram, chorando em alta voz. Também o rei e todos os seus conselheiros choraram muito.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 37, 'Absalão fugiu para o território de Talmai, filho de Amiúde, rei de Gesur. E o rei Davi pranteava por seu filho todos os dias.', 3, CURRENT_TIMESTAMP, false),
(10, 13, 38, 'Depois que Absalão fugiu para Gesur, e lá permaneceu três anos,', 3, CURRENT_TIMESTAMP, false),
(10, 13, 39, 'a ira do rei contra Absalão cessou, pois ele se sentia consolado da morte de Amnom.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 1, 'Joabe, filho de Zeruia, percebeu que o rei estava com saudade de Absalão,', 3, CURRENT_TIMESTAMP, false),
(10, 14, 2, 'então mandou buscar uma mulher astuta em Tecoa, e lhe disse: "Finja que está de luto: Vista-se de preto e não se perfume. Aja como uma mulher que há algum tempo está de luto.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 3, 'Vá dizer ao rei estas palavras", e a instruiu sobre o que ela deveria dizer.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 4, 'Quando a mulher apresentou-se ao rei, prostrou-se, rosto em terra, em sinal de respeito, e lhe disse: "Ajuda-me, ó rei! "', 3, CURRENT_TIMESTAMP, false),
(10, 14, 5, '"Qual é o seu problema? ", perguntou-lhe o rei, e ela respondeu: "Sou viúva, meu marido morreu', 3, CURRENT_TIMESTAMP, false),
(10, 14, 6, 'deixando-me com dois filhos. Eles brigaram no campo e, não havendo ninguém para separá-los, um acabou matando o outro.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 7, 'Agora, todo o clã levantou-se contra a tua serva, exigindo: ‘Entregue o assassino, para que o matemos pela vida do irmão, e nos livremos também do herdeiro’. Assim eles querem apagar a última centelha que me restou, deixando meu marido sem nome nem descendência na face da terra".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 8, 'O rei disse à mulher: "Vá para casa. Eu mandarei que cuidem do seu caso".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 9, 'Mas a mulher de Tecoa lhe disse: "Ó rei, meu senhor, é sobre mim e sobre a família de meu pai que pesará a iniqüidade; não pesa culpa sobre o rei e sobre o seu trono".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 10, 'O rei respondeu: "Se alguém ameaçá-la, traga-o a mim, e ele não mais a incomodará".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 11, 'Ela acrescentou: "Peço então ao rei que, em nome do Senhor, o seu Deus, não permita que o vingador da vítima cause maior destruição, matando meu outro filho". E disse ele: "Eu juro pelo nome do Senhor, que nem um só fio de cabelo da cabeça de seu filho cairá".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 12, 'Disse-lhe ainda a mulher: "Permite que a tua serva fale mais uma coisa ao rei meu senhor". "Fale", respondeu ele.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 13, 'Disse então a mulher: "Por que terá o rei agido contra o povo de Deus? O rei está se condenando com o que acaba de dizer, pois não permitiu a volta do que foi banido.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 14, 'Que teremos que morrer um dia, é tão certo como não se pode recolher a água que se espalhou pela terra. Mas Deus não tira a vida; pelo contrário, cria meios para que o banido não permaneça afastado dele.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 15, '"E eu vim falar sobre isso ao rei, meu senhor, porque o povo me ameaçou. Tua serva pensou que se falasse com o rei, talvez ele atendesse o seu pedido,', 3, CURRENT_TIMESTAMP, false),
(10, 14, 16, 'e concordasse em livrar a sua serva das mãos do homem que está tentando eliminar tanto a mim como a meu filho da herança que Deus nos deu.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 17, '"E agora a tua serva diz: Traga-me descanso a decisão do rei, o meu senhor, pois o rei, meu senhor, é como um anjo de Deus, capaz de discernir entre o bem e o mal. Que o Senhor teu Deus esteja contigo! "', 3, CURRENT_TIMESTAMP, false),
(10, 14, 18, 'Então o rei disse à mulher: "Não me esconda nada do que vou lhe perguntar". "Fale o rei, meu senhor", disse a mulher.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 19, 'O rei perguntou: "Não é Joabe que está por trás de tudo isso? " A mulher respondeu: "Juro por tua vida, ó rei, ninguém é capaz de desviar-se para a direita ou para a esquerda do que tu dizes. Sim, foi o teu servo Joabe quem me mandou aqui para dizer tudo isso.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 20, 'O teu servo Joabe agiu assim para mudar essa situação. Mas o meu senhor é sábio como um anjo de Deus, e nada lhe escapa de tudo o que acontece em seu país".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 21, 'Depois o rei disse a Joabe: "Muito bem, atenderei esse pedido. Vá e traga de volta o jovem Absalão".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 22, 'Joabe prostrou-se, rosto em terra, abençoou o rei e disse: "Hoje o teu servo ficou sabendo que o vês com bons olhos, pois o rei atendeu o pedido de seu servo".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 23, 'Então Joabe foi a Gesur e trouxe Absalão de volta para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 24, 'Mas o rei disse: "Ele irá para a casa dele; não virá à minha presença". Assim, Absalão foi para a sua casa e não compareceu mais à presença do rei.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 25, 'Em todo o Israel não havia homem tão elogiado por sua beleza como Absalão. Da cabeça aos pés não havia nele nenhum defeito.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 26, 'Sempre que o cabelo lhe ficava pesado demais, ele o cortava e o pesava: eram dois quilos e quatrocentos gramas, segundo o padrão do rei.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 27, 'Ele teve três filhos e uma filha, chamada Tamar, que se tornou uma linda mulher.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 28, 'Absalão morou dois anos em Jerusalém sem ser recebido pelo rei.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 29, 'Então mandou chamar Joabe para enviá-lo ao rei, mas Joabe não quis ir. Mandou chamá-lo pela segunda vez, mas ele, novamente, não quis ir.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 30, 'Então Absalão disse a seus servos: "Vejam, a propriedade de Joabe é vizinha da minha, e ele tem uma plantação de cevada. Tratem de incendiá-la". E os servos de Absalão puseram fogo na plantação.', 3, CURRENT_TIMESTAMP, false),
(10, 14, 31, 'Então Joabe foi à casa de Absalão e lhe perguntou: "Porque os seus servos puseram fogo na minha propriedade? "', 3, CURRENT_TIMESTAMP, false),
(10, 14, 32, 'Absalão respondeu: "Mandei chamá-lo para enviá-lo ao rei com a seguinte mensagem: ‘Por que voltei de Gesur? Melhor seria que eu lá permanecesse! ’ Quero ser recebido pelo rei; e, se eu for culpado de alguma coisa, que ele mande me matar".', 3, CURRENT_TIMESTAMP, false),
(10, 14, 33, 'Então Joabe foi contar tudo ao rei. Este mandou chamar Absalão, que entrou e prostrou-se, rosto em terra, perante o rei. E o rei saudou-o com um beijo.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 1, 'Algum tempo depois, Absalão adquiriu uma carruagem, cavalos e uma escolta de cinqüenta homens.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 2, 'Ele se levantava cedo e ficava junto ao caminho que levava à porta da cidade. Sempre que alguém trazia uma causa para ser decidida pelo rei, Absalão o chamava e perguntava de que cidade vinha. A pessoa respondia que era de uma das tribos de Israel,', 3, CURRENT_TIMESTAMP, false),
(10, 15, 3, 'e Absalão dizia: "A sua causa é válida e legítima, mas não há nenhum representante do rei para ouvi-lo".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 4, 'E Absalão acrescentava: "Quem me dera ser designado juiz desta terra! Todos os que tivessem uma causa ou uma questão legal viriam a mim, e eu lhe faria justiça".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 5, 'E sempre que alguém se aproximava dele para prostrar-se em sinal de respeito, Absalão estendia a mão, abraçava-o e beijava-o.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 6, 'Absalão agia assim com todos os israelitas que vinham pedir que o rei lhes fizesse justiça. Assim ele foi conquistando a lealdade dos homens de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 7, 'Ao final de quatro anos, Absalão disse ao rei: "Deixa-me ir a Hebrom para cumprir um voto que fiz ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 8, 'Quando o teu servo estava em Gesur, na Síria, fez este voto: Se o Senhor me permitir voltar a Jerusalém, prestarei culto a ele em Hebrom".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 9, '"Vá em paz! ", disse o rei. E ele foi para Hebrom.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 10, 'Absalão enviou secretamente mensageiros a todas as tribos de Israel, dizendo: "Assim que vocês ouvirem o som das trombetas, digam: Absalão é rei em Hebrom".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 11, 'Absalão levou duzentos homens de Jerusalém. Eles tinham sido convidados e nada sabiam nem suspeitavam do que estava acontecendo.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 12, 'Depois de oferecer sacrifícios, Absalão mandou chamar da cidade de Gilo Aitofel, que era de Gilo, conselheiro de Davi. A conspiração ganhou força, e cresceu o número dos que seguiam Absalão.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 13, 'Então um mensageiro chegou e disse a Davi: "Os israelitas estão com Absalão! "', 3, CURRENT_TIMESTAMP, false),
(10, 15, 14, 'Então Davi disse aos conselheiros que estavam com ele em Jerusalém: "Vamos fugir; caso contrário não escaparemos de Absalão. Se não partirmos imediatamente ele nos alcançará, causará a nossa ruína e matará o povo à espada".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 15, 'Os conselheiros do rei lhe responderam: "Teus servos estão dispostos a fazer tudo o que o rei, nosso senhor, decidir".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 16, 'O rei partiu, seguido por todos os de sua família; deixou, porém, dez concubinas para tomarem conta do palácio.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 17, 'Assim, o rei partiu com todo o povo. Pararam na última casa da cidade,', 3, CURRENT_TIMESTAMP, false),
(10, 15, 18, 'e todos os seus soldados marcharam, passando por ele: todos os queretitas e peletitas, e os seiscentos giteus que o acompanhavam desde Gate.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 19, 'O rei disse então a Itai, de Gate: "Por que você está indo conosco? Volte e fique com o novo rei, pois você é estrangeiro, um exilado de sua terra.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 20, 'Faz pouco tempo que você chegou. Como eu poderia fazê-lo acompanhar-me? Volte e leve consigo os seus irmãos. Que o Senhor o trate com bondade e fidelidade! "', 3, CURRENT_TIMESTAMP, false),
(10, 15, 21, 'Itai, contudo, respondeu ao rei: "Juro pelo nome do Senhor e por tua vida que onde quer que o rei, meu senhor, esteja, ali estará o seu servo, para viver ou para morrer! "', 3, CURRENT_TIMESTAMP, false),
(10, 15, 22, 'Então Davi disse a Itai: "Está bem, pode ir adiante". E Itai, o giteu, marchou, com todos os seus soldados e com as famílias que estavam com ele.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 23, 'Todo o povo do lugar chorava em alta voz enquanto o exército passava. O rei atravessou o vale do Cedrom e todo o povo foi com ele em direção ao deserto.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 24, 'Zadoque também estava lá, e com ele todos os levitas que carregavam a arca da aliança de Deus; Abiatar também estava lá. Puseram no chão a arca de Deus até que todo o povo saísse da cidade.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 25, 'Então o rei disse a Zadoque: "Leve a arca de Deus de volta para a cidade. Se o Senhor mostrar benevolência a mim, ele me trará de volta e me deixará ver a arca e o lugar onde ela deve permanecer.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 26, 'Mas, se ele disser que já não sou do seu agrado, aqui estou! Faça ele comigo o que for de sua vontade".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 27, 'Disse ainda o rei ao sacerdote Zadoque: "Fique alerta! Volte em paz para a cidade, você, Aimaás, seu filho, e Jônatas, filho de Abiatar.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 28, 'Junto às torrentes do deserto ficarei esperando notícias de vocês".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 29, 'Então Zadoque e Abiatar levaram a arca de Deus de volta para Jerusalém, e lá permaneceram.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 30, 'Davi, porém, continuou subindo o monte das Oliveiras, caminhando e chorando, e com a cabeça coberta e os pés descalços. E todos os que iam com ele também tinham a cabeça coberta e subiam chorando.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 31, 'Quando informaram a Davi que Aitofel era um dos conspiradores que apoiavam Absalão, Davi orou: "Ó Senhor, transforma em loucura os conselhos de Aitofel".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 32, 'Quando Davi chegou ao alto do monte, ao lugar onde o povo costumava adorar a Deus, veio ao seu encontro o arquita Husai, com a roupa rasgada e com terra sobre a cabeça.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 33, 'E Davi lhe disse: "Não adianta você vir comigo.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 34, 'Mas se voltar à cidade, poderá dizer a Absalão: ‘Estarei a teu serviço, ó rei. No passado estive a serviço de teu pai, mas agora estarei a teu serviço’. Assim você me ajudará, frustrando o conselho de Aitofel.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 35, 'Os sacerdotes Zadoque e Abiatar estarão lá com você. Informe-os do que você souber no palácio.', 3, CURRENT_TIMESTAMP, false),
(10, 15, 36, 'Também estão lá os dois filhos deles: Aimaás e Jônatas. Por meio deles me informe de tudo que você ouvir".', 3, CURRENT_TIMESTAMP, false),
(10, 15, 37, 'Então Husai, amigo de Davi, chegou a Jerusalém quando Absalão estava entrando na cidade.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 1, 'Mal Davi tinha passado pelo alto do monte, lá estava à sua espera Ziba, criado de Mefibosete. Ele trazia dois jumentos carregando duzentos pães, cem bolos de uvas passas, cem frutas da estação e uma vasilha de couro cheia de vinho.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 2, 'O rei perguntou a Ziba: "Por que você trouxe essas coisas? " Ziba respondeu: "Os jumentos servirão de montaria para a família do rei, os pães e as frutas são para os homens comerem, e o vinho servirá para reanimar os que ficarem exaustos no deserto".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 3, 'O rei então perguntou: "Onde está Mefibosete, neto de seu senhor? " Respondeu-lhe Ziba: "Ele ficou em Jerusalém, pois acredita que os israelitas lhe restituirão o reino de seu avô ".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 4, 'Então o rei disse a Ziba: "Tudo o que pertencia a Mefibosete agora é seu". "Humildemente me prostro", disse Ziba. "Que o rei, meu senhor, agrade-se de mim".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 5, 'Chegando o rei Davi a Baurim, um homem do clã da família de Saul chamado Simei, filho de Gera, saiu da cidade proferindo maldições contra ele.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 6, 'Ele atirava pedras em Davi e em todos os conselheiros do rei, embora todo o exército e a guarda de elite estivessem à direita e à esquerda de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 7, 'Enquanto amaldiçoava, Simei dizia: "Saia daqui, saia daqui! Assassino! Bandido!', 3, CURRENT_TIMESTAMP, false),
(10, 16, 8, 'O Senhor retribuiu a você todo o sangue derramado na família de Saul, em cujo lugar você reinou. O Senhor entregou o reino nas mãos de seu filho Absalão. Você está arruinado porque é um assassino! "', 3, CURRENT_TIMESTAMP, false),
(10, 16, 9, 'Então Abisai, filho de Zeruia, disse ao rei: "Por que esse cão morto amaldiçoa o rei meu senhor? Permite que eu lhe corte a cabeça".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 10, 'Mas o rei disse: "Que é que vocês têm com isso, filhos de Zeruia? Ele me amaldiçoa porque o Senhor lhe disse que amaldiçoasse Davi. Portanto, quem poderá questioná-lo? "', 3, CURRENT_TIMESTAMP, false),
(10, 16, 11, 'Disse então Davi a Abisai e a todos os seus conselheiros: "Até meu filho, sangue do meu sangue, procura matar-me. Quanto mais este benjamita! Deixem-no em paz! Que amaldiçoe, pois foi o que o Senhor lhe mandou fazer.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 12, 'Talvez o Senhor considere a minha aflição e me retribua com o bem a maldição que hoje recebo".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 13, 'Assim, Davi e os seus soldados prosseguiram pela estrada, enquanto Simei ia pela encosta do monte, no lado oposto, amaldiçoando, jogando pedras e terra.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 14, 'O rei e todo o povo que estava com ele chegaram exaustos a seu destino. E lá descansaram.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 15, 'Enquanto isso, Absalão e todos os homens de Israel entraram em Jerusalém, e Aitofel estava com eles.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 16, 'Então Husai, o arquita, amigo de Davi, aproximou-se de Absalão e exclamou: "Viva o rei! Viva o rei! "', 3, CURRENT_TIMESTAMP, false),
(10, 16, 17, 'Mas Absalão disse a Husai: "É essa a lealdade que você tem para com o seu amigo? Por que você não foi com ele? "', 3, CURRENT_TIMESTAMP, false),
(10, 16, 18, 'Respondeu Husai: "Não! Sou do escolhido do Senhor, deste povo e de todos os israelitas; e com ele permanecerei.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 19, 'Além disso, a quem devo servir? Não deveria eu servir o filho? Assim como servi a teu pai, também te servirei".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 20, 'Então Absalão disse a Aitofel: "Dê-nos o seu conselho. Que devemos fazer? "', 3, CURRENT_TIMESTAMP, false),
(10, 16, 21, 'Aitofel respondeu: "Tenha relações com as concubinas de teu pai, que ele deixou para tomar conta do palácio. Então todo o Israel ficará sabendo que te tornaste repugnante para teu pai, e todos os que estão contigo se encherão de coragem".', 3, CURRENT_TIMESTAMP, false),
(10, 16, 22, 'E assim armaram uma tenda no terraço do palácio para Absalão, e ele teve relações com as concubinas de seu pai à vista de todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 16, 23, 'Naquela época, tanto Davi como Absalão consideravam os conselhos de Aitofel como se fossem a palavra do próprio Deus.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 1, 'Aitofel disse a Absalão: "Permite-me escolher doze mil homens, e partirei esta noite em perseguição a Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 2, 'Eu o atacarei enquanto ele está exausto e fraco; vou causar-lhe pânico, e seu exército fugirá. Depois matarei somente o rei,', 3, CURRENT_TIMESTAMP, false),
(10, 17, 3, 'e trarei todo o exército de volta a ti. É somente um homem que procuras matar. Assim, todo o exército ficará em paz".', 3, CURRENT_TIMESTAMP, false),
(10, 17, 4, 'Esse plano pareceu bom a Absalão e a todas as autoridades de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 5, 'Entretanto, Absalão disse: "Chamem também Husai, o arquita, para que ouçamos a opinião dele".', 3, CURRENT_TIMESTAMP, false),
(10, 17, 6, 'Quando Husai entrou, Absalão lhe disse: "Aitofel deu-nos o conselho dele. Devemos fazer o que ele diz, ou você tem outra opinião? "', 3, CURRENT_TIMESTAMP, false),
(10, 17, 7, 'Husai respondeu: "O conselho que Aitofel deu desta vez não é bom.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 8, 'Sabes que o teu pai e os homens que estão com ele são guerreiros, e estão furiosos como uma ursa selvagem da qual roubaram os filhotes. Além disso, teu pai é um soldado experiente e não passará a noite com o exército.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 9, 'Ele, agora, já deve estar escondido numa caverna ou nalgum outro lugar. Se alguns dos teus soldados forem mortos no primeiro ataque, quem souber disso dirá: ‘Houve matança no meio do exército de Absalão’.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 10, 'Então, até o mais bravo soldado, corajoso como leão, ficará morrendo de medo, pois todo o Israel sabe que teu pai é um guerreiro valente e que seus soldados são corajosos.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 11, '"Por isso, dou o seguinte conselho: Que se reúnam a ti todos os homens de Israel, desde Dã até Berseba, tantos como a areia da praia e que tu mesmo os conduzas na batalha.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 12, 'Então o atacaremos onde quer que ele se encontre, e cairemos sobre ele como o orvalho cai sobre a terra. Nem ele nem nenhum dos seus homens escapará.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 13, 'Se ele se refugiar em alguma cidade, todo o Israel levará cordas para lá, e arrastaremos aquela cidade para o vale, até que não reste ali sequer uma pequena pedra".', 3, CURRENT_TIMESTAMP, false),
(10, 17, 14, 'Absalão e todos os homens de Israel consideraram o conselho de Husai, o arquita, melhor do que o de Aitofel; pois o Senhor tinha decidido frustrar o eficiente conselho de Aitofel a fim de trazer ruína sobre Absalão.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 15, 'Husai contou aos sacerdotes Zadoque e Abiatar o conselho que Aitofel dera a Absalão e às autoridades de Israel, e o que ele mesmo lhes tinha aconselhado em seguida.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 16, 'Então pediu que enviassem imediatamente esta mensagem a Davi: "Não passe a noite nos pontos de travessia do Jordão, no deserto, mas atravesse logo o rio, senão o rei e todo o seu exército serão exterminados".', 3, CURRENT_TIMESTAMP, false),
(10, 17, 17, 'Jônatas e Aimaás estavam em En-Rogel, e uma serva os informava regularmente, pois não podiam arriscar-se a serem vistos na cidade. Eles, por sua vez, iam relatar ao rei Davi o que tinham ouvido.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 18, 'Mas um jovem os viu e avisou Absalão. Então eles partiram rapidamente e foram para a casa de um habitante de Baurim, que tinha um poço no quintal. Eles desceram ao poço,', 3, CURRENT_TIMESTAMP, false),
(10, 17, 19, 'e a dona da casa colocou a tampa no poço e, para disfarçar, espalhou grãos de cereal por cima.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 20, 'Os soldados de Absalão chegaram à casa da mulher e lhe perguntaram: "Onde estão Aimaás e Jônatas? " A mulher respondeu: "Eles atravessaram as águas". Os homens os procuraram sem sucesso, e voltaram a Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 21, 'Tendo eles ido embora, os dois saíram do poço e foram informar o rei Davi. Falaram-lhe do conselho que Aitofel dera contra ele, e lhe disseram que atravessasse imediatamente o Jordão.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 22, 'Então Davi e todo o seu exército saíram e, quando o sol nasceu, todos tinham atravessado o Jordão.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 23, 'Vendo Aitofel que o seu conselho não havia sido aceito, selou seu jumento e foi para casa, para a sua cidade natal; pôs seus negócios em ordem, e depois se enforcou. Ele foi sepultado no túmulo de seu pai.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 24, 'Davi já tinha chegado a Maanaim, quando Absalão atravessou o Jordão com todos os homens de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 25, 'Absalão havia nomeado Amasa para comandar o exército em lugar de Joabe. Amasa era filho de Jéter, um israelita que havia possuído Abigail, filha de Naás e irmã de Zeruia, mãe de Joabe.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 26, 'Absalão e os israelitas acamparam em Gileade.', 3, CURRENT_TIMESTAMP, false),
(10, 17, 27, 'Quando Davi chegou a Maanaim, Sobi, filho de Naás, de Rabá dos amonitas, e Maquir, filho de Amiel, de Lo-Debar, e o gileadita Barzilai, de Rogelim,', 3, CURRENT_TIMESTAMP, false),
(10, 17, 28, 'trouxeram a Davi e ao seu exército camas, bacias e utensílios de cerâmica e também trigo, cevada, farinha, grãos torrados, feijão e lentilha,', 3, CURRENT_TIMESTAMP, false),
(10, 17, 29, 'mel e coalhada, ovelhas e queijo de leite de vaca; pois sabiam que o exército estava cansado, com fome e com sede no deserto.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 1, 'Davi passou em revista o exército e nomeou comandantes de batalhões de mil e de cem.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 2, 'Davi dividiu o exército em três companhias: uma sob o comando de Joabe, outra sob o comando de Abisai, irmão de Joabe, filho de Zeruia, e outra sob o comando de Itai, o giteu. Disse então o rei ao exército: "Eu também marcharei com vocês".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 3, 'Mas os homens disseram: "Não faças isso! Se tivermos que fugir, eles não se preocuparão conosco, e mesmo que metade de nós morra em batalha, eles não se importarão. Tu, porém, vales por dez mil de nós. Melhor será que fiques na cidade e dali nos dês apoio".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 4, 'O rei respondeu: "Farei o que acharem melhor". E o rei ficou junto à porta, enquanto os soldados marchavam, saindo em unidades de cem e de mil.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 5, 'O rei ordenou a Joabe, a Abisai e a Itai: "Por amor a mim, tratem bem o jovem Absalão! " E todo o exército ouviu quando o rei deu essa ordem sobre Absalão a cada um dos comandantes.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 6, 'O exército saiu a campo para enfrentar Israel, e a batalha aconteceu na floresta de Efraim,', 3, CURRENT_TIMESTAMP, false),
(10, 18, 7, 'onde o exército de Israel foi derrotado pelos soldados de Davi. Houve grande matança naquele dia, elevando-se o número de mortos a vinte mil.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 8, 'A batalha espalhou-se por toda a região e, naquele dia, a floresta matou mais que a espada.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 9, 'Durante a batalha, Absalão, montado em sua mula, encontrou-se com os soldados de Davi. Passando a mula debaixo dos galhos de uma grande árvore, e Absalão ficou preso pela cabeça nos galhos. Ele ficou pendurado entre o céu e a terra, e a mula prosseguiu.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 10, 'Um homem o viu, e foi informar a Joabe: "Acabei de ver Absalão pendurado numa grande árvore".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 11, '"Você o viu? ", perguntou Joabe ao homem. "E por que não o matou ali mesmo? Eu teria dado a você dez peças de prata e um cinturão de guerreiro! "', 3, CURRENT_TIMESTAMP, false),
(10, 18, 12, 'Mas o homem respondeu: "Mesmo que fossem pesadas e colocadas em minhas mãos mil peças de prata, eu não levantaria a mão contra o filho do rei. Ouvimos o rei ordenar a ti, a Abisai e a Itai: ‘Protejam, por amor a mim, o jovem Absalão’.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 13, 'Por outro lado, se eu tivesse atentado traiçoeiramente contra a vida dele, o rei ficaria sabendo, pois não se pode esconder nada dele, e tu mesmo ficarias contra mim".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 14, 'E Joabe disse: "Não vou perder mais tempo com você". Então pegou três dardos e com eles traspassou o coração de Absalão, quando ele ainda estava vivo na árvore.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 15, 'E dez dos escudeiros de Joabe cercaram Absalão e acabaram de matá-lo.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 16, 'A seguir Joabe tocou a trombeta para que o exército parasse de perseguir Israel, e assim deteve o exército.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 17, 'Retiraram o corpo de Absalão, jogaram-no num grande fosso na floresta e fizeram um grande monte de pedras sobre ele. Enquanto isso, todos os israelitas fugiam para casa.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 18, 'Quando em vida, Absalão tinha levantado um monumento para si mesmo no vale do Rei, dizendo: "Não tenho nenhum filho para preservar a minha memória". Por isso deu à coluna o seu próprio nome. Chama-se ainda hoje Monumento de Absalão.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 19, 'Então Aimaás, filho de Zadoque, disse: "Deixa-me correr e levar ao rei a notícia de que o Senhor lhe fez justiça, livrando-o de seus inimigos".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 20, '"Não é você quem deve levar a notícia hoje", disse-lhe Joabe. "Deixe isso para outra ocasião. Hoje não, porque o filho do rei morreu".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 21, 'Então Joabe ordenou a um etíope: "Vá dizer ao rei o que você viu". O cuxita inclinou-se diante de Joabe e saiu correndo para levar as notícias.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 22, 'Todavia Aimaás, filho de Zadoque, disse de novo a Joabe: "Não importa o que aconteça, deixa-me ir com o cuxita". Joabe, porém, respondeu: "Por que quer tanto ir, meu filho? Você não receberá nenhuma recompensa pela notícia".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 23, 'Mas ele insistiu: "Não importa o que aconteça, quero ir". Disse então Joabe: "Pois vá! " E Aimaás correu pelo caminho da planície e passou à frente do cuxita.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 24, 'Davi estava sentado entre a porta interna e a externa da cidade. E quando a sentinela subiu ao terraço sobre a porta, junto à muralha, viu um homem que vinha correndo sozinho.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 25, 'A sentinela gritou, avisando o rei. O rei disse: "Se ele está sozinho, deve trazer boa notícia". E o homem foi se aproximando.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 26, 'Então a sentinela viu outro homem que vinha correndo e gritou ao porteiro: "Vem outro homem correndo sozinho! " "Esse também deve estar trazendo boa notícia! ", exclamou o rei.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 27, 'A sentinela disse: "Está me parecendo que, pelo jeito de correr, o da frente é Aimaás, filho de Zadoque". "É um bom homem", disse o rei. "Ele traz boas notícias".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 28, 'Então Aimaás aproximou-se do rei e o saudou. Prostrou-se, rosto em terra, diante do rei e disse: "Bendito seja o Senhor teu Deus! Ele entregou os homens que se rebelaram contra o rei, meu senhor".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 29, 'O rei perguntou: "O jovem Absalão está bem? " Aimaás respondeu: "Vi que houve grande confusão quando Joabe, o servo do rei, ia enviar teu servo, mas não sei o que aconteceu".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 30, 'O rei disse: "Fique ali ao lado esperando". E Aimaás ficou esperando.', 3, CURRENT_TIMESTAMP, false),
(10, 18, 31, 'Então o cuxita chegou e disse: "Ó rei, meu senhor, ouve a boa notícia! Hoje o Senhor te livrou de todos os que se levantaram contra ti".', 3, CURRENT_TIMESTAMP, false),
(10, 18, 32, 'O rei perguntou ao cuxita: "O jovem Absalão está bem? " O cuxita respondeu: "Que os inimigos do rei meu senhor e todos que se levantam para lhe fazer mal acabem como aquele jovem! "', 3, CURRENT_TIMESTAMP, false),
(10, 18, 33, 'Então o rei, abalado, subiu ao quarto que ficava por cima da porta e chorou. Foi subindo e clamando: "Ah, meu filho Absalão! Meu filho, meu filho Absalão! Quem me dera ter morrido em seu lugar! Ah, Absalão, meu filho, meu filho! "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 1, 'Informaram a Joabe que o rei estava chorando e se lamentando por Absalão.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 2, 'E para todo o exército a vitória daquele dia se transformou em luto, porque as tropas ouviram dizer: "O rei está de luto por seu filho".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 3, 'Naquele dia, o exército ficou em silêncio na cidade, como fazem os que fogem humilhados da batalha.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 4, 'O rei, com o rosto coberto, gritava: "Ah, meu filho Absalão! Ah, Absalão, meu filho, meu filho! "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 5, 'Então Joabe entrou no palácio e foi falar com o rei: "Hoje humilhaste todos os teus soldados, os quais salvaram a tua vida, bem como a de teus filhos e filhas, e de tuas mulheres e concubinas.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 6, 'Amas os que te odeiam e odeias os que te amam. Hoje deixaste claro que os comandantes e os seus soldados nada significam para ti. Vejo que ficarias satisfeito se, hoje, Absalão estivesse vivo e todos nós, mortos.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 7, 'Agora, vai e encoraja teus soldados! Juro pelo Senhor que, se não fores, nem um só deles permanecerá contigo esta noite, o que para ti seria pior do que todas as desgraças que já te aconteceram, desde a tua juventude".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 8, 'Então o rei levantou-se e sentou-se junto à porta da cidade. Quando o exército soube que o rei estava sentado junto à porta, todos os soldados foram até ele. Enquanto isso, os israelitas fugiam para casa.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 9, 'Em todas as tribos de Israel o povo discutia, dizendo: "Davi nos livrou das mãos de nossos inimigos; foi ele que nos libertou dos filisteus. Mas agora fugiu do país por causa de Absalão;', 3, CURRENT_TIMESTAMP, false),
(10, 19, 10, 'e Absalão, a quem tínhamos ungido rei, morreu em combate. E então, por que não falam em trazer o rei de volta? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 11, 'Quando chegou aos ouvidos do rei o que todo o Israel estava comentando, Davi mandou a seguinte mensagem aos sacerdotes Zadoque e Abiatar: "Perguntem às autoridades de Judá: Por que vocês seriam os últimos a conduzir o rei de volta ao seu palácio?', 3, CURRENT_TIMESTAMP, false),
(10, 19, 12, 'Vocês são meus irmãos, sangue do meu sangue! Por que, então, seriam os últimos a ajudar no meu retorno? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 13, 'E digam a Amasa: "Você é sangue do meu sangue! Que Deus me castigue com todo o rigor se, de agora em diante, você não for o comandante do meu exército em lugar de Joabe".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 14, 'As palavras de Davi conquistaram a lealdade unânime de todos os homens de Judá. E eles mandaram dizer ao rei que voltasse com todos os seus servos.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 15, 'Então o rei voltou e chegou ao Jordão. E os homens de Judá foram a Gilgal, ao encontro do rei, para ajudá-lo a atravessar o Jordão.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 16, 'Simei, filho de Gera, benjamita de Baurim, foi depressa com os homens de Judá para encontrar-se com o rei Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 17, 'Com ele estavam outros mil benjamitas e também Ziba, supervisor da casa de Saul, com seus quinze filhos e vinte servos. Eles entraram no Jordão antes do rei,', 3, CURRENT_TIMESTAMP, false),
(10, 19, 18, 'e atravessaram o rio a fim de ajudar a família real na travessia e fazer o que o rei desejasse. Simei, filho de Gera, atravessou o Jordão, prostrou-se perante o rei', 3, CURRENT_TIMESTAMP, false),
(10, 19, 19, 'e lhe disse: "Que o meu senhor não leve em conta o meu crime. E que não te lembres do mal que o teu servo cometeu no dia em que o rei, meu senhor, saiu de Jerusalém. Que o rei não pense mais nisso!', 3, CURRENT_TIMESTAMP, false),
(10, 19, 20, 'Eu, teu servo, reconheço que pequei. Por isso, de toda a tribo de José, fui o primeiro a vir ao encontro do rei, meu senhor".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 21, 'Então Abisai, filho de Zeruia, disse: "Simei amaldiçoou o ungido do Senhor, ele deve ser morto! "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 22, 'Davi respondeu: "Que é que vocês têm com isso, filhos de Zeruia? Acaso se tornaram agora meus acusadores? Deve alguém ser morto hoje em Israel? Ou não tenho hoje a garantia de que voltei a reinar sobre Israel? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 23, 'E o rei prometeu a Simei, sob juramento: "Você não será morto".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 24, 'Mefibosete, neto de Saul, também foi ao encontro do rei. Ele não havia lavado os pés nem aparado a barba nem lavado as roupas, desde o dia em que o rei partira até o dia em que voltou em segurança.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 25, 'Quando chegou de Jerusalém e encontrou-se com o rei, este lhe perguntou: "Por que você não foi comigo, Mefibosete? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 26, 'Ele respondeu: "Ó rei, meu senhor! Eu, teu servo, sendo aleijado, mandei selar o meu jumento para montá-lo e acompanhar o rei. Mas o meu servo me enganou.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 27, 'Ele falou mal de mim ao rei, meu senhor. Tu és como um anjo de Deus! Faze o que achares melhor.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 28, 'Todos os descendentes do meu avô nada mereciam do meu senhor e rei, senão a morte. Entretanto, deste a teu servo um lugar entre os que comem à tua mesa. Que direito tenho eu, pois, de te pedir qualquer outro favor? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 29, 'Disse-lhe então o rei: "Você já disse o suficiente. Minha decisão é que você e Ziba dividam a propriedade".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 30, 'Mas Mefibosete disse ao rei: "Deixa que ele fique com tudo, agora que o rei meu senhor chegou em segurança ao seu lar".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 31, 'Barzilai, de Gileade, também saiu de Rogelim, acompanhando o rei até o Jordão, para despedir-se dele.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 32, 'Barzilai era bastante idoso; tinha oitenta anos. Foi ele que sustentou o rei durante sua permanência em Maanaim, pois era muito rico.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 33, 'O rei disse a Barzilai: "Venha comigo para Jerusalém, e eu cuidarei de você".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 34, 'Barzilai, porém, respondeu: "Quantos anos de vida ainda me restam, para que eu vá com o rei e viva com ele em Jerusalém?', 3, CURRENT_TIMESTAMP, false),
(10, 19, 35, 'Já fiz oitenta anos. Como eu poderia distinguir entre o que é bom e o que é mau? Será que hoje o teu servo ainda pode sentir o gosto daquilo que come e bebe? Posso ainda apreciar a voz de homens e mulheres cantando? Eu seria mais um peso para o rei, meu senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 36, 'Teu servo acompanhará o rei um pouco mais, atravessando o Jordão, mas não há motivo para uma recompensa dessas.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 37, 'Permite que o teu servo volte! E que eu possa morrer na minha própria cidade, perto do túmulo de meu pai e de minha mãe. Mas aqui está o meu servo Quimã. Que ele vá com o meu senhor e rei. Faze por ele o que achares melhor! "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 38, 'O rei disse: "Quimã virá comigo! Farei por ele o que você achar melhor. E tudo o mais que desejar de mim, eu o farei por você".', 3, CURRENT_TIMESTAMP, false),
(10, 19, 39, 'Então, todo o exército atravessou o Jordão, e também o rei o atravessou. O rei beijou Barzilai e o abençoou. E Barzilai voltou para casa.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 40, 'O rei seguiu para Gilgal; e com ele foi Quimã. Todo o exército de Judá e a metade do exército de Israel acompanharam o rei.', 3, CURRENT_TIMESTAMP, false),
(10, 19, 41, 'Logo os homens de Israel chegaram ao rei para reclamar: "Por que os nossos irmãos, os de Judá, seqüestraram o rei e o levaram para o outro lado do Jordão, como também a família dele e todos os seus homens? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 42, 'Todos os homens de Judá responderam aos israelitas: "Fizemos isso porque o rei é nosso parente mais chegado. Por que vocês estão irritados? Acaso comemos das provisões do rei ou tomamos dele alguma coisa? "', 3, CURRENT_TIMESTAMP, false),
(10, 19, 43, 'Então os israelitas disseram aos homens de Judá: "Somos dez com o rei; e muito maior é o nosso direito sobre Davi do que o de vocês. Por que nos desprezam? Nós fomos os primeiros a propor o retorno do nosso rei! " Mas os homens de Judá falaram ainda mais asperamente do que os israelitas.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 1, 'Também estava lá um desordeiro chamado Seba, filho de Bicri, de Benjamim. Ele tocou a trombeta e gritou: "Não temos parte alguma com Davi, nenhuma herança com o filho de Jessé! Para casa todos, ó Israel! "', 3, CURRENT_TIMESTAMP, false),
(10, 20, 2, 'Então todos os de Israel abandonaram Davi para seguir Seba, filho de Bicri. Mas os de Judá permaneceram com seu rei e o acompanharam desde o Jordão até Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 3, 'Quando Davi voltou ao palácio, em Jerusalém, mandou confinar numa casa, sob guarda, as dez concubinas que tinha deixado tomando conta do palácio. Ele as sustentou, mas nunca mais as possuiu. Ficaram confinadas, vivendo como viúvas até à morte.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 4, 'E o rei disse a Amasa: "Convoque os homens de Judá, e dentro de três dias apresente-se aqui com eles".', 3, CURRENT_TIMESTAMP, false),
(10, 20, 5, 'Mas Amasa levou mais tempo para convocar Judá do que o prazo estabelecido pelo rei.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 6, 'Disse então Davi a Abisai: "Agora Seba, filho de Bicri, será pior para nós do que Absalão. Chame os meus soldados e persiga-o, antes que ele encontre alguma cidade fortificada e, depois, nos arranque os olhos".', 3, CURRENT_TIMESTAMP, false),
(10, 20, 7, 'Assim, os soldados de Joabe, os queretitas, os peletitas e todos os guerreiros saíram de Jerusalém para perseguir Seba, filho de Bicri.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 8, 'Quando estavam junto à grande rocha de Gibeom, Amasa encontrou-se com eles. Joabe vestia seu traje militar e tinha um cinto com um punhal na bainha. Ao aproximar-se de Amasa, deixou cair a adaga.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 9, '"Como vai, meu irmão? ", disse Joabe, pegando Amasa pela barba com a mão direita, para beijá-lo.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 10, 'E Amasa, não percebendo o punhal na mão esquerda de Joabe, foi por ele golpeado no estômago. Suas entranhas se derramaram no chão, e ele morreu, sem necessidade de um segundo golpe. Então Joabe e, Abisai, seu irmão, perseguiram Seba, filho de Bicri.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 11, 'Um dos soldados de Joabe ficou ao lado do corpo de Amasa e disse: "Quem estiver do lado de Joabe e de Davi, que siga a Joabe! "', 3, CURRENT_TIMESTAMP, false),
(10, 20, 12, 'Amasa jazia numa poça de sangue no meio da estrada. Quando o homem viu que todos os que se aproximavam do corpo de Amasa paravam, arrastou-o para fora da estrada e o cobriu com uma coberta.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 13, 'Depois que o corpo de Amasa foi retirado da estrada, todos os homens seguiram com Joabe em perseguição a Seba, filho de Bicri.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 14, 'Seba atravessou todas as tribos de Israel e chegou até Abel-Bete-Maaca, e todos os bicritas se reuniram para segui-lo.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 15, 'O exército de Joabe veio e cercou Seba em Abel-Bete-Maaca. Eles construíram contra a cidade uma rampa que chegou até à muralha externa. Quando o exército de Joabe estava para derrubar a muralha,', 3, CURRENT_TIMESTAMP, false),
(10, 20, 16, 'uma mulher sábia gritou da cidade: "Ouçam! Ouçam! Digam a Joabe que venha aqui para que eu fale com ele".', 3, CURRENT_TIMESTAMP, false),
(10, 20, 17, 'Quando ele se aproximou a mulher perguntou: "Tu és Joabe? " Ele respondeu: "Sim". Ela disse: "Ouve o que a tua serva tem para dizer-te". "Estou ouvindo", disse ele.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 18, 'E ela prosseguiu: "Antigamente se dizia: ‘Peça conselho na cidade de Abel’, e isso resolvia a questão.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 19, 'Nós somos pacíficos e fiéis em Israel. Tu procuras destruir uma cidade que é mãe em Israel. Por que queres arruinar a herança do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(10, 20, 20, 'Respondeu Joabe: "Longe de mim uma coisa dessas! Longe de mim arruinar e destruir esta cidade!', 3, CURRENT_TIMESTAMP, false),
(10, 20, 21, 'Não é esse o problema. Mas um homem chamado Seba, filho de Bicri, dos montes de Efraim, rebelou-se contra o rei Davi. Entreguem-me esse homem, e iremos embora". A mulher disse a Joabe: "A cabeça dele te será jogada do alto da muralha".', 3, CURRENT_TIMESTAMP, false),
(10, 20, 22, 'Então a mulher foi falar com todo o povo, dando o seu sábio conselho, e eles cortaram a cabeça de Seba, filho de Bicri, e a jogaram para Joabe. Ele tocou a trombeta, e seus homens se dispersaram, abandonaram o cerco da cidade e cada um voltou para sua casa. E Joabe voltou ao rei, em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(10, 20, 23, 'Joabe comandava todo o exército de Israel; Benaia, filho de Joiada, comandava os queretitas e os peletitas;', 3, CURRENT_TIMESTAMP, false),
(10, 20, 24, 'Adonirão era responsável pelos trabalhos forçados; Josafá, filho de Ailude, era arquivista real;', 3, CURRENT_TIMESTAMP, false),
(10, 20, 25, 'Seva era secretário; Zadoque e Abiatar eram sacerdotes;', 3, CURRENT_TIMESTAMP, false),
(10, 20, 26, 'e Ira, de Jair, era sacerdote de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 1, 'Durante o reinado de Davi, houve uma fome que durou três anos. Davi consultou o Senhor, que lhe disse: "A fome veio por causa de Saul e de sua família sanguinária, por terem matado os gibeonitas".', 3, CURRENT_TIMESTAMP, false),
(10, 21, 2, 'O rei então mandou chamar os gibeonitas e falou com eles. ( Os gibeonitas não eram de origem israelita, mas remanescentes dos amorreus. Os israelitas tinham feito com eles um acordo sob juramento; mas Saul, em seu zelo por Israel e Judá, havia tentado exterminá-los. )', 3, CURRENT_TIMESTAMP, false),
(10, 21, 3, 'Davi perguntou aos gibeonitas: "Que posso fazer por vocês? Como posso reparar o que foi feito, para que abençoem a herança do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(10, 21, 4, 'Os gibeonitas responderam: "Não exigimos de Saul ou de sua família prata ou ouro, nem queremos matar ninguém em Israel". Davi perguntou: "O que querem que eu faça por vocês? ",', 3, CURRENT_TIMESTAMP, false),
(10, 21, 5, 'e eles responderam: "Quanto ao homem que quase nos exterminou e que pretendia destruir-nos, para que não tivéssemos lugar em Israel,', 3, CURRENT_TIMESTAMP, false),
(10, 21, 6, 'que sete descendentes dele sejam executados perante o Senhor, em Gibeá de Saul, no monte do Senhor". "Eu os entregarei a vocês", disse o rei.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 7, 'O rei poupou Mefibosete, filho de Jônatas e neto de Saul, por causa do juramento feito perante o Senhor entre Davi e Jônatas, filho de Saul.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 8, 'Mas o rei mandou buscar Armoni e Mefibosete, dois filhos de Rispa, filha de Aiá, que ela teve com Saul, e os cinco filhos de Merabe, filha de Saul, que ela teve com Adriel, filho de Barzilai, de Meolá.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 9, 'Ele os entregou aos gibeonitas, que os executaram no monte, perante o Senhor. Os sete foram mortos ao mesmo tempo, nos primeiros dias da colheita de cevada.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 10, 'Então Rispa, filha de Aiá, pegou um pano de saco e o estendeu para si sobre uma rocha. Desde o início da colheita até cair chuva do céu sobre os corpos, ela não deixou que as aves de rapina os tocassem de dia, nem os animais selvagens à noite.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 11, 'Quando Davi foi informado do que Rispa, filha de Aiá, concubina de Saul, havia feito,', 3, CURRENT_TIMESTAMP, false),
(10, 21, 12, 'ele mandou recolher os ossos de Saul e de Jônatas, tomando-os dos cidadãos de Jabes-Gileade. ( Eles haviam roubado os ossos da praça de Bete-Seã, onde os filisteus os tinham pendurado, no dia em que mataram Saul no monte Gilboa. )', 3, CURRENT_TIMESTAMP, false),
(10, 21, 13, 'Davi trouxe de lá os ossos de Saul e de seu filho Jônatas, que foram recolhidos dentre os ossos dos que haviam sido executados.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 14, 'Enterraram os ossos de Saul e de Jônatas no túmulo de Quis, pai de Saul, em Zela, na terra de Benjamim, e fizeram tudo o que o rei ordenou. Depois disso, Deus respondeu as orações em favor da terra de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 15, 'Houve, ainda, outra batalha entre os filisteus e Israel; Davi e seus soldados foram lutar contra os filisteus. Davi se cansou muito,', 3, CURRENT_TIMESTAMP, false),
(10, 21, 16, 'e Isbi-Benobe, descendente de Rafa, prometeu matar Davi. ( A ponta de bronze da lança de Isbi-Benobe pesava três quilos e seiscentos gramas, e ele ainda estava armado com uma espada nova. )', 3, CURRENT_TIMESTAMP, false),
(10, 21, 17, 'Mas Abisai, filho de Zeruia, foi em socorro de Davi e matou o filisteu. Então os soldados de Davi lhe juraram, dizendo: "Nunca mais sairás conosco à guerra, para que não apagues a lâmpada de Israel".', 3, CURRENT_TIMESTAMP, false),
(10, 21, 18, 'Houve depois outra batalha com os filisteus, em Gobe. Naquela ocasião Sibecai, de Husate, matou Safe, um dos descendentes de Rafa.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 19, 'Noutra batalha contra os filisteus em Gobe, Elanã, filho de Jaaré-Oregim, de Belém, matou Golias, de Gate, que possuía uma lança cuja haste parecia uma lançadeira de tecelão.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 20, 'Noutra batalha, em Gate, havia um homem de grande estatura e que tinha seis dedos em cada mão e seis dedos em cada pé, vinte e quatro dedos ao todo. Ele também era descendente de Rafa,', 3, CURRENT_TIMESTAMP, false),
(10, 21, 21, 'e desafiou Israel, mas Jônatas, filho de Siméia, irmão de Davi, o matou.', 3, CURRENT_TIMESTAMP, false),
(10, 21, 22, 'Esses quatro eram descendentes de Rafa, em Gate, e foram mortos por Davi e seus soldados.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 1, 'Davi cantou ao Senhor este cântico, quando este o livrou das mãos de todos os seus inimigos e das mãos de Saul,', 3, CURRENT_TIMESTAMP, false),
(10, 22, 2, 'dizendo: "O Senhor é a minha rocha, a minha fortaleza e o meu libertador;', 3, CURRENT_TIMESTAMP, false),
(10, 22, 3, 'o meu Deus é a minha rocha, em que me refugio; o meu escudo e o meu poderoso salvador. Ele é a minha torre alta, o meu abrigo seguro. És o meu salvador, que me salva dos violentos.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 4, 'Clamo ao Senhor, que é digno de louvor, e sou salvo dos meus inimigos.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 5, '"As ondas da morte me cercaram; as torrentes da destruição me aterrorizaram.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 6, 'As cordas da sepultura me envolveram; as armadilhas da morte me confrontaram.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 7, 'Na minha angústia, clamei ao Senhor; clamei ao meu Deus. Do seu templo ele ouviu a minha voz; o meu grito de socorro chegou aos seus ouvidos.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 8, '"A terra abalou-se e tremeu, os alicerces dos céus estremeceram; tremeram porque ele estava irado.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 9, 'Das suas narinas saiu fumaça; da sua boca saiu fogo consumidor; dele saíram brasas vivas e flamejantes.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 10, 'Ele abriu os céus e desceu; nuvens escuras estavam debaixo dos seus pés.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 11, 'Montou sobre um querubim e voou; elevou-se sobre as asas do vento.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 12, 'Pôs as trevas ao seu redor; das densas nuvens de chuva fez o seu abrigo.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 13, 'Do brilho da sua presença flamejavam carvões em brasa.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 14, 'Dos céus o Senhor trovejou; ressoou a voz do Altíssimo.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 15, 'Ele atirou flechas e dispersou os inimigos, arremessou raios e os fez bater em retirada.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 16, 'Os vales apareceram, e os fundamentos da terra foram expostos, diante da repreensão do Senhor, com o forte sopro de suas narinas.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 17, '"Das alturas estendeu a mão e me segurou; tirou-me de águas profundas.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 18, 'Livrou-me do meu inimigo poderoso, dos meus adversários, que eram fortes demais para mim.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 19, 'Eles me atacaram no dia da minha calamidade, mas o Senhor foi o meu amparo.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 20, 'Deu-me ampla liberdade; livrou-me, pois me quer bem.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 21, '"O Senhor me tratou segundo a minha retidão; segundo a pureza das minhas mãos me recompensou.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 22, 'Pois guardei os caminhos do Senhor; não cometi a perversidade de afastar-me do meu Deus.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 23, 'Todos os seus mandamentos estão diante de mim; não me afastei dos seus decretos.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 24, 'Tenho sido irrepreensível para com ele e guardei-me de pecar.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 25, 'O Senhor recompensou-me segundo a minha retidão, segundo a pureza das minhas mãos perante ele.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 26, '"Ao fiel te revelas fiel, ao irrepreensível te revelas irrepreensível,', 3, CURRENT_TIMESTAMP, false),
(10, 22, 27, 'ao puro te revelas puro, mas ao perverso te revelas astuto.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 28, 'Salvas os humildes, mas os teus olhos estão sobre os orgulhosos para os humilhar.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 29, 'Tu és a minha lâmpada, ó Senhor! O Senhor ilumina-me as trevas.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 30, 'Contigo posso avançar contra uma tropa; com o meu Deus posso transpor muralhas.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 31, '"Este é o Deus cujo caminho é perfeito; a palavra do Senhor é comprovadamente genuína. Ele é escudo para todos os que nele se refugiam.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 32, 'Pois quem é Deus além do Senhor? E quem é Rocha senão o nosso Deus?', 3, CURRENT_TIMESTAMP, false),
(10, 22, 33, 'É Deus quem me reveste de força e torna perfeito o meu caminho.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 34, 'Ele me faz correr veloz como a gazela e me firma os passos nos lugares altos.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 35, 'É ele que treina as minhas mãos para a batalha, e assim os meus braços vergam o arco de bronze.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 36, 'Tu me dás o teu escudo de livramento; a tua ajuda me fez forte.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 37, 'Alargas sob mim o meu caminho, para que os meus tornozelos não se torçam.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 38, '"Persegui os meus inimigos e os derrotei; não voltei enquanto não foram destruídos.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 39, 'Esmaguei-os completamente, e não puderam levantar-se; caíram debaixo dos meus pés.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 40, 'Tu me revestiste de força para a batalha; fizeste cair aos meus pés os meus adversários.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 41, 'Fizeste que os meus inimigos fugissem de mim; destruí os que me odiavam.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 42, 'Gritaram por socorro, mas não havia quem os salvasse; gritaram ao Senhor, mas ele não respondeu.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 43, 'Eu os reduzi a pó, como o pó da terra; esmaguei-os e os amassei como a lama das ruas.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 44, '"Tu me livraste dos ataques do meu povo; preservaste-me como líder de nações. Um povo que eu não conhecia me é sujeito.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 45, 'Estrangeiros me bajulam; assim que me ouvem, me obedecem.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 46, 'Todos eles perdem a coragem; saem tremendo das suas fortalezas.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 47, '"O Senhor vive! Bendita seja a minha Rocha! Exaltado seja Deus, a Rocha que me salva!', 3, CURRENT_TIMESTAMP, false),
(10, 22, 48, 'Este é o Deus que em meu favor executa vingança, que sujeita nações ao meu poder;', 3, CURRENT_TIMESTAMP, false),
(10, 22, 49, 'que me livrou dos meus inimigos. Tu me exaltaste acima dos meus agressores; de homens violentos me libertaste.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 50, 'Por isso te louvarei entre as nações, ó Senhor; cantarei louvores ao teu nome.', 3, CURRENT_TIMESTAMP, false),
(10, 22, 51, 'Ele concede grandes vitórias ao seu rei; é bondoso com o seu ungido, Davi e seus descendentes para sempre".', 3, CURRENT_TIMESTAMP, false),
(10, 23, 1, 'Estas são as últimas palavras de Davi: "Palavras de Davi, filho de Jessé; palavras do homem que foi exaltado, do ungido pelo Deus de Jacó, do cantor dos cânticos de Israel:', 3, CURRENT_TIMESTAMP, false),
(10, 23, 2, '"O Espírito do Senhor falou por meu intermédio; sua palavra esteve em minha língua.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 3, 'O Deus de Israel falou, a Rocha de Israel me disse: ‘Quem governa o povo com justiça, quem o governa com o temor de Deus,', 3, CURRENT_TIMESTAMP, false),
(10, 23, 4, 'é como a luz da manhã ao nascer do sol, numa manhã sem nuvens. É como a claridade depois da chuva, que faz crescer as plantas da terra’.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 5, '"A minha dinastia está de bem com Deus. Ele fez uma aliança eterna comigo, firmada e garantida em todos os aspectos. Certamente fará prosperar em tudo e concede-me tudo quanto desejo.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 6, 'Mas os perversos serão lançados fora como espinhos, que não se ajuntam com as mãos;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 7, 'quem quer tocá-los usa uma ferramenta ou o cabo de madeira da lança. Os espinhos serão totalmente queimados onde estiverem".', 3, CURRENT_TIMESTAMP, false),
(10, 23, 8, 'Estes são os nomes dos principais guerreiros de Davi: Jabesão, um tacmonita, chefe dos três guerreiros principais; numa ocasião, com uma lança, enfrentou oitocentos homens numa mesma batalha e os matou.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 9, 'Depois dele, Eleazar, filho do aoíta Dodô. Ele era um dos três principais guerreiros e esteve com Davi quando os filisteus se reuniram em Pas-Damim para a batalha. Os israelitas recuaram,', 3, CURRENT_TIMESTAMP, false),
(10, 23, 10, 'mas ele manteve a sua posição e feriu os filisteus até a sua mão ficar dormente e grudar na espada. E o Senhor concedeu uma grande vitória naquele dia, e o exército voltou para onde Eleazar estava, mas somente para saquear os mortos.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 11, 'Depois dele, Samá, filho de Agé, de Harar. Os filisteus reuniram-se em Leí, onde havia uma plantação de lentilha. O exército de Israel fugiu dos filisteus,', 3, CURRENT_TIMESTAMP, false),
(10, 23, 12, 'mas Samá tomou posição no meio da plantação, defendeu-a e derrotou os filisteus. E o Senhor concedeu-lhe uma grande vitória.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 13, 'Durante a colheita, três chefes do batalhão dos trinta foram encontrar Davi na caverna de Adulão, enquanto um grupo de filisteus acampava no vale de Refaim.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 14, 'Estando Davi nessa fortaleza, e o destacamento filisteu em Belém,', 3, CURRENT_TIMESTAMP, false),
(10, 23, 15, 'Davi expressou este forte desejo: "Quem me dera me trouxessem água da cisterna da porta de Belém! "', 3, CURRENT_TIMESTAMP, false),
(10, 23, 16, 'Então aqueles três atravessaram o acampamento filisteu, tiraram água da cisterna e a trouxeram a Davi. Mas ele se recusou a beber; em vez disso, derramou-a como uma oferta ao Senhor e disse:', 3, CURRENT_TIMESTAMP, false),
(10, 23, 17, '"O Senhor me livre de beber desta água! Seria como beber o sangue dos que arriscaram a vida para trazê-la! " E Davi não bebeu daquela água. Foram esses os feitos dos três principais guerreiros.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 18, 'Abisai, irmão de Joabe e filho de Zeruia, era o chefe do batalhão dos trinta. Certa ocasião, com sua lança matou trezentos homens, tornando-se tão famoso quanto os três.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 19, 'Foi mais honrado que o batalhão dos trinta e tornou-se o chefe deles. Mas nunca igualou-se aos três principais guerreiros.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 20, 'Benaia, filho de Joiada, era um corajoso soldado de Cabzeel, que realizou grandes feitos. Matou dois dos melhores guerreiros de Moabe e, num dia de neve, desceu num buraco e matou um leão.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 21, 'Também matou um egípcio de grande estatura. O egípcio tinha na mão uma lança, e Benaia o enfrentou com um cajado. Arrancou a lança da mão do egípcio e com ela o matou.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 22, 'Esses foram os grandes feitos de Benaia, filho de Joiada, que também foi tão famoso quanto os três principais guerreiros de Davi.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 23, 'Foi mais honrado do que qualquer dos trinta, mas nunca igualou-se aos três. E Davi lhe deu o comando da sua guarda pessoal.', 3, CURRENT_TIMESTAMP, false),
(10, 23, 24, 'Entre os trinta estavam: Asael, irmão de Joabe; Elanã, filho de Dodô, de Belém;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 25, 'Samá e Elica, de Harode;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 26, 'Heles, de Pelete; Ira, filho de Iques, de Tecoa;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 27, 'Abiezer, de Anatote; Mebunai, de Husate;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 28, 'Zalmom, de Aoí; Maarai, de Netofate;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 29, 'Helede, filho de Baaná, de Netofate; Itai, filho de Ribai, de Gibeá de Benjamim;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 30, 'Benaia, de Piratom; Hidai, dos riachos de Gaás;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 31, 'Abi-Albom, de Arbate; Azmavete, de Baurim;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 32, 'Eliaba, de Saalbom; os filhos de Jasém; Jônatas,', 3, CURRENT_TIMESTAMP, false),
(10, 23, 33, 'filho de Samá, de Harar; Aião, filho de Sarar, de Harar;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 34, 'Elifelete, filho de Aasbai, de Maaca; Eliã, filho de Aitofel, de Gilo;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 35, 'Hezrai, de Carmelo; Paarai, de Arabe;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 36, 'Igal, filho de Natã, de Zobá; o filho de Hagri;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 37, 'Zeleque, de Amom; Naarai, de Beerote, escudeiro de Joabe, filho de Zeruia;', 3, CURRENT_TIMESTAMP, false),
(10, 23, 38, 'Ira e Garebe, de Jatir,', 3, CURRENT_TIMESTAMP, false),
(10, 23, 39, 'e o hitita Urias. Foram ao todo trinta e sete.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 1, 'Mais uma vez, irou-se o Senhor contra Israel. E incitou Davi contra o povo, levando-o a fazer um censo de Israel e de Judá.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 2, 'Então o rei disse a Joabe e aos outros comandantes do exército: "Vão por todas as tribos de Israel, de Dã a Berseba, e contem o povo, para que eu saiba quantos são".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 3, 'Joabe, porém, respondeu ao rei: "Que o Senhor teu Deus multiplique o povo por cem, e que os olhos do rei, meu senhor, o vejam! Mas, por que o rei, meu senhor, deseja fazer isso? "', 3, CURRENT_TIMESTAMP, false),
(10, 24, 4, 'Mas a palavra do rei prevaleceu sobre a de Joabe e dos comandantes do exército; então eles saíram da presença do rei para contar o povo de Israel.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 5, 'E atravessando o Jordão, começaram em Aroer, ao sul da cidade, no vale; depois foram para Gade e de lá para Jazar,', 3, CURRENT_TIMESTAMP, false),
(10, 24, 6, 'Gileade e Cades dos hititas, chegaram a Dã-Jaã e às proximidades de Sidom.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 7, 'Dali seguiram na direção da fortaleza de Tiro e de todas as cidades dos heveus e dos cananeus. Por último foram até Berseba, no Neguebe de Judá.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 8, 'Percorreram todo o país, e voltaram a Jerusalém ao fim de nove meses e vinte dias.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 9, 'Então Joabe apresentou ao rei o relatório do recenseamento do povo; havia em Israel oitocentos mil homens habilitados para o serviço militar, e em Judá, quinhentos mil.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 10, 'Depois de contar o povo, Davi sentiu remorso e disse ao Senhor: "Pequei gravemente com o que fiz! Agora, Senhor, eu imploro que perdoes o pecado do teu servo, porque cometi uma grande loucura! "', 3, CURRENT_TIMESTAMP, false),
(10, 24, 11, 'Levantando-se Davi pela manhã, o Senhor já tinha falado a Gade, o vidente dele:', 3, CURRENT_TIMESTAMP, false),
(10, 24, 12, '"Vá dizer a Davi: ‘Assim diz o Senhor: Estou lhe dando três opções de punição; escolha uma delas, e eu a executarei contra você’ ".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 13, 'Então Gade foi a Davi e lhe perguntou: "O que você prefere: três anos de fome em sua terra; três meses fugindo de seus adversários, que o perseguirão; ou três dias de praga em sua terra? Pense bem e diga-me o que deverei responder àquele que me enviou".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 14, 'Davi respondeu: "É grande a minha angústia! Prefiro cair nas mãos do Senhor, pois grande é a sua misericórdia, e não nas mãos dos homens".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 15, 'Então o Senhor enviou uma praga sobre Israel, desde aquela manhã até a hora que tinha determinado. E morreram setenta mil homens do povo, de Dã a Berseba.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 16, 'Quando o anjo estendeu a mão para destruir Jerusalém, o Senhor arrependeu-se de trazer essa catástrofe, e ele disse ao anjo destruidor: "Pare! Já basta! " Naquele momento o anjo do Senhor estava perto da eira de Araúna, o jebuseu.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 17, 'Ao ver o anjo que estava matando o povo, disse Davi ao Senhor: "Fui eu que pequei e cometi iniqüidade. Estes não passam de ovelhas. O que eles fizeram? Que o teu castigo caia sobre mim e sobre a minha família! "', 3, CURRENT_TIMESTAMP, false),
(10, 24, 18, 'Naquele mesmo dia Gade foi dizer a Davi: "Vá e edifique um altar na eira de Araúna, o jebuseu".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 19, 'Davi foi para lá, em obediência à ordem que Gade tinha dado em nome do Senhor.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 20, 'Quando Araúna viu o rei e seus soldados vindo ao encontro dele, saiu e prostrou-se perante o rei, rosto em terra,', 3, CURRENT_TIMESTAMP, false),
(10, 24, 21, 'e disse: "Por que o meu senhor e rei veio ao seu servo? " Respondeu Davi: "Para comprar sua eira, e edificar nela um altar ao Senhor, para que cesse a praga no meio do povo".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 22, 'Araúna disse a Davi: "O meu senhor e rei pode ficar com o que quiser e ofereça-o em sacrifício. Aqui estão os bois para o holocausto, e o debulhador e o jugo dos bois para a lenha.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 23, 'Ó rei, eu dou tudo isso a ti". E acrescentou: "Que o Senhor teu Deus aceite a tua oferta".', 3, CURRENT_TIMESTAMP, false),
(10, 24, 24, 'Mas o rei respondeu a Araúna: "Não! Faço questão de pagar o preço justo. Não oferecerei ao Senhor meu Deus holocaustos que não me custem nada". Davi comprou, pois, a eira e os bois por cinqüenta peças de prata.', 3, CURRENT_TIMESTAMP, false),
(10, 24, 25, 'E Davi edificou ali um altar ao Senhor e ofereceu holocaustos e sacrifícios de comunhão. Então o Senhor aceitou as súplicas em favor da terra, e a praga parou de destruir Israel.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 1, 'Paulo, Silvano e Timóteo, à igreja dos tessalonicenses, em Deus nosso Pai e no Senhor Jesus Cristo:', 3, CURRENT_TIMESTAMP, false),
(53, 1, 2, 'A vocês, graça e paz da parte de Deus Pai e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 3, 'Irmãos, devemos sempre dar graças a Deus por vocês; e isso é apropriado, porque a fé que vocês têm cresce cada vez mais, e muito aumenta o amor que todos vocês têm uns pelos outros.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 4, 'Por esta causa nos gloriamos em vocês entre as igrejas de Deus pela perseverança e fé que mostram em todas as perseguições e tribulações que vocês estão suportando.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 5, 'Elas dão prova do justo juízo de Deus, que deseja que vocês sejam considerados dignos do seu Reino, pelo qual vocês também estão sofrendo.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 6, 'É justo da parte de Deus retribuir com tribulação aos que lhes causam tribulação,', 3, CURRENT_TIMESTAMP, false),
(53, 1, 7, 'e dar alívio a vocês, que estão sendo atribulados, e a nós também. Isso acontecerá quando o Senhor Jesus for revelado lá do céu, com os seus anjos poderosos, em meio a chamas flamejantes.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 8, 'Ele punirá os que não conhecem a Deus e os que não obedecem ao evangelho de nosso Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 9, 'Eles sofrerão a pena de destruição eterna, a separação da presença do Senhor e da majestade do seu poder.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 10, 'Isso acontecerá no dia em que ele vier para ser glorificado em seus santos e admirado em todos os que creram, inclusive vocês que creram em nosso testemunho.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 11, 'Conscientes disso, oramos constantemente por vocês, para que o nosso Deus os faça dignos da vocação e, com poder, cumpra todo bom propósito e toda obra que procede da fé.', 3, CURRENT_TIMESTAMP, false),
(53, 1, 12, 'Assim o nome de nosso Senhor Jesus será glorificado em vocês, e vocês nele, segundo a graça de nosso Deus e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 1, 'Irmãos, quanto à vinda de nosso Senhor Jesus Cristo e à nossa reencontro com ele, rogamos a vocês', 3, CURRENT_TIMESTAMP, false),
(53, 2, 2, 'que não se deixem abalar nem alarmar tão facilmente, quer por profecia, quer por palavra, quer por carta supostamente vinda de nós, como se o dia do Senhor já tivesse chegado.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 3, 'Não deixem que ninguém os engane de modo algum. Antes daquele dia virá a apostasia e, então, será revelado o homem do pecado, o filho da perdição.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 4, 'Este se opõe e se exalta acima de tudo o que se chama Deus ou é objeto de adoração, a ponto de se assentar no santuário de Deus, proclamando que ele mesmo é Deus.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 5, 'Não se lembram de que quando eu ainda estava com vocês costumava lhes falar essas coisas?', 3, CURRENT_TIMESTAMP, false),
(53, 2, 6, 'E agora vocês sabem o que o está detendo, para que ele seja revelado no seu devido tempo.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 7, 'A verdade é que o mistério da iniqüidade já está em ação, restando apenas que seja afastado aquele que agora o detém.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 8, 'Então será revelado o perverso, a quem o Senhor Jesus matará com o sopro de sua boca e destruirá pela manifestação de sua vinda.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 9, 'A vinda desse perverso é segundo a ação de Satanás, com todo o poder, com sinais e com maravilhas enganadoras.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 10, 'Ele fará uso de todas as formas de engano da injustiça para os que estão perecendo, porquanto rejeitaram o amor à verdade que os poderia salvar.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 11, 'Por essa razão Deus lhes envia um poder sedutor, a fim de que creiam na mentira,', 3, CURRENT_TIMESTAMP, false),
(53, 2, 12, 'e sejam condenados todos os que não creram na verdade, mas tiveram prazer na injustiça.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 13, 'Mas nós, devemos sempre dar graças a Deus por vocês, irmãos amados pelo Senhor, porque desde o princípio Deus os escolheu para serem salvos mediante a obra santificadora do Espírito e a fé na verdade.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 14, 'Ele os chamou para isso por meio de nosso evangelho, a fim de tomarem posse da glória de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 15, 'Portanto, irmãos, permaneçam firmes e apeguem-se às tradições que lhes foram ensinadas, quer de viva voz, quer por carta nossa.', 3, CURRENT_TIMESTAMP, false),
(53, 2, 16, 'Que o próprio Senhor Jesus Cristo e Deus nosso Pai, que nos amou e nos deu eterna consolação e boa esperança pela graça,', 3, CURRENT_TIMESTAMP, false),
(53, 2, 17, 'dê ânimo aos seus corações e os fortaleça para fazerem sempre o bem, tanto em atos como em palavras.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 1, 'Finalmente, irmãos, orem por nós, para que a palavra do Senhor se propague rapidamente e receba a hora merecida, como aconteceu entre vocês.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 2, 'Orem também para que sejamos libertos dos homens perversos e maus, pois a fé não é de todos.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 3, 'Mas o Senhor é fiel; ele os fortalecerá e os guardará do Maligno.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 4, 'Confiamos no Senhor que vocês estão fazendo e continuarão a fazer as coisas que lhes ordenamos.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 5, 'O Senhor conduza os seus corações ao amor de Deus e à perseverança de Cristo.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 6, 'Irmãos, em nome do nosso Senhor Jesus Cristo nós lhes ordenamos que se afastem de todo irmão que vive ociosamente e não conforme a tradição que receberam de nós.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 7, 'Pois vocês mesmos sabem como devem seguir o nosso exemplo, porque não vivemos ociosamente quando estivemos entre vocês,', 3, CURRENT_TIMESTAMP, false),
(53, 3, 8, 'nem comemos coisa alguma à custa de ninguém. Pelo contrário, trabalhamos arduamente e com fadiga, dia e noite, para não sermos pesados a nenhum de vocês,', 3, CURRENT_TIMESTAMP, false),
(53, 3, 9, 'não por que não tivéssemos tal direito, mas para que nos tornássemos um modelo para ser imitado por vocês.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 10, 'Quando ainda estávamos com vocês, nós lhes ordenamos isto: se alguém não quiser trabalhar, também não coma.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 11, 'Pois ouvimos que alguns de vocês estão ociosos; não trabalham, mas andam se intrometendo na vida alheia.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 12, 'A tais pessoas ordenamos e exortamos no Senhor Jesus Cristo que trabalhem tranqüilamente e comam o seu próprio pão.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 13, 'Quanto a vocês, irmãos, nunca se cansem de fazer o bem.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 14, 'Se alguém não obedecer à nossa palavra por esta carta, marquem-no e não se associem com ele, para que se sinta envergonhado;', 3, CURRENT_TIMESTAMP, false),
(53, 3, 15, 'contudo, não o considerem como inimigo, mas chamem a atenção dele como irmão.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 16, 'O próprio Senhor da paz lhes dê a paz em todo o tempo e de todas as formas. O Senhor seja com todos vocês.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 17, 'Eu, Paulo, escrevo esta saudação de próprio punho, a qual é um sinal em todas as minhas cartas. É dessa forma que escrevo.', 3, CURRENT_TIMESTAMP, false),
(53, 3, 18, 'A graça de nosso Senhor Jesus Cristo seja com todos vocês.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, segundo a promessa da vida que está em Cristo Jesus,', 3, CURRENT_TIMESTAMP, false),
(55, 1, 2, 'a Timóteo, meu amado filho: Graça, misericórdia e paz da parte de Deus Pai e de Cristo Jesus, nosso Senhor.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 3, 'Dou graças a Deus, a quem sirvo com a consciência limpa, como o serviram os meus antepassados, ao lembrar-me constantemente de você noite e dia em minhas orações.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 4, 'Lembro-me das suas lágrimas e desejo muito vê-lo, para que a minha alegria seja completa.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 5, 'Recordo-me da sua fé não fingida, que primeiro habitou em sua avó Lóide e em sua mãe Eunice, e estou convencido de que também habita em você.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 6, 'Por essa razão, torno a lembrar-lhe que mantenha viva a chama do dom de Deus que está em você mediante a imposição das minhas mãos.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 7, 'Pois Deus não nos deu espírito de covardia, mas de poder, de amor e de equilíbrio.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 8, 'Portanto, não se envergonhe de testemunhar do Senhor, nem de mim, que sou prisioneiro dele, mas suporte comigo os sofrimentos pelo evangelho, segundo o poder de Deus,', 3, CURRENT_TIMESTAMP, false),
(55, 1, 9, 'que nos salvou e nos chamou com uma santa vocação, não em virtude das nossas obras, mas por causa da sua própria determinação e graça. Esta graça nos foi dada em Cristo Jesus desde os tempos eternos,', 3, CURRENT_TIMESTAMP, false),
(55, 1, 10, 'sendo agora revelada pela manifestação de nosso Salvador, Cristo Jesus. Ele tornou inoperante a morte e trouxe à luz a vida e a imortalidade por meio do evangelho.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 11, 'Deste evangelho fui constituído pregador, apóstolo e mestre.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 12, 'Por essa causa também sofro, mas não me envergonho, porque sei em quem tenho crido e estou bem certo de que ele é poderoso para guardar o meu depósito até aquele dia.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 13, 'Retenha, com fé e amor em Cristo Jesus, o modelo da sã doutrina que você ouviu de mim.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 14, 'Quanto ao bom depósito, guarde-o por meio do Espírito Santo que habita em nós.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 15, 'Você sabe que todos os da província da Ásia me abandonaram, inclusive Fígelo e Hermógenes.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 16, 'O Senhor conceda misericórdia à casa de Onesíforo, porque muitas vezes ele me reanimou e não se envergonhou por eu estar preso;', 3, CURRENT_TIMESTAMP, false),
(55, 1, 17, 'pelo contrário, quando chegou a Roma procurou-me diligentemente até me encontrar.', 3, CURRENT_TIMESTAMP, false),
(55, 1, 18, 'Conceda-lhe o Senhor que, naquele dia, encontre misericórdia da parte do Senhor! Você sabe muito bem quantos serviços ele me prestou em Éfeso.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 1, 'Portanto, você, meu filho, fortifique-se na graça que há em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 2, 'E as coisas que me ouviu dizer na presença de muitas testemunhas, confie a homens fiéis que sejam também capazes de ensinar a outros.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 3, 'Suporte comigo os sofrimentos, como bom soldado de Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 4, 'Nenhum soldado se deixa envolver pelos negócios da vida civil, já que deseja agradar aquele que o alistou.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 5, 'Semelhantemente, nenhum atleta é coroado como vencedor, se não competir de acordo com as regras.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 6, 'O lavrador que trabalha arduamente deve ser o primeiro a participar dos frutos da colheita.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 7, 'Reflita no que estou dizendo, pois o Senhor lhe dará entendimento em tudo.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 8, 'Lembre-se de Jesus Cristo, ressuscitado dos mortos, descendente de Davi, conforme o meu evangelho,', 3, CURRENT_TIMESTAMP, false),
(55, 2, 9, 'pelo qual sofro a ponto de estar preso como criminoso; contudo a palavra de Deus não está presa.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 10, 'Por isso, tudo suporto por causa dos eleitos, para que também eles alcancem a salvação que está em Cristo Jesus, com glória eterna.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 11, 'Esta palavra é digna de confiança: Se morremos com ele, com ele também viveremos;', 3, CURRENT_TIMESTAMP, false),
(55, 2, 12, 'se perseveramos, com ele também reinaremos. Se o negamos, ele também nos negará;', 3, CURRENT_TIMESTAMP, false),
(55, 2, 13, 'se somos infiéis, ele permanece fiel, pois não pode negar-se a si mesmo.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 14, 'Continue a lembrar essas coisas a todos, advertindo-os solenemente diante de Deus, para que não se envolvam em discussões acerca de palavras; isso não tem proveito, e serve apenas para perverter os ouvintes.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 15, 'Procure apresentar-se a Deus aprovado, como obreiro que não tem do que se envergonhar, que maneja corretamente a palavra da verdade.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 16, 'Evite as conversas inúteis e profanas, pois os que se dão a isso prosseguem cada vez mais para a impiedade.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 17, 'O ensino deles alastra como câncer; entre eles estão Himeneu e Fileto.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 18, 'Estes se desviaram da verdade, dizendo que a ressurreição já aconteceu, e assim a alguns pervertem a fé.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 19, 'Entretanto, o firme fundamento de Deus permanece inabalável e selado com esta inscrição: "O Senhor conhece quem lhe pertence" e "afaste-se da iniqüidade todo aquele que confessa o nome do Senhor".', 3, CURRENT_TIMESTAMP, false),
(55, 2, 20, 'Numa grande casa há vasos não apenas de ouro e prata, mas também de madeira e barro; alguns para fins honrosos, outros para fins desonrosos.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 21, 'Se alguém se purificar dessas coisas, será vaso para honra, santificado, útil para o Senhor e preparado para toda boa obra.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 22, 'Fuja dos desejos malignos da juventude e siga a justiça, a fé, o amor e a paz, juntamente com os que, de coração puro, invocam o Senhor.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 23, 'Evite as controvérsias tolas e fúteis, pois você sabe que acabam em brigas.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 24, 'Ao servo do Senhor não convém brigar mas, sim, ser amável para com todos, apto para ensinar, paciente.', 3, CURRENT_TIMESTAMP, false),
(55, 2, 25, 'Deve corrigir com mansidão os que se lhe opõem, na esperança de que Deus lhes conceda o arrependimento, levando-os ao conhecimento da verdade,', 3, CURRENT_TIMESTAMP, false),
(55, 2, 26, 'para que assim voltem à sobriedade e escapem da armadilha do diabo, que os aprisionou para fazerem a sua vontade.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 1, 'Saiba disto: nos últimos dias sobrevirão tempos terríveis.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 2, 'Os homens serão egoístas, avarentos, presunçosos, arrogantes, blasfemos, desobedientes aos pais, ingratos, ímpios,', 3, CURRENT_TIMESTAMP, false),
(55, 3, 3, 'sem amor pela família, irreconciliáveis, caluniadores, sem domínio próprio, cruéis, inimigos do bem,', 3, CURRENT_TIMESTAMP, false),
(55, 3, 4, 'traidores, precipitados, soberbos, mais amantes dos prazeres do que amigos de Deus,', 3, CURRENT_TIMESTAMP, false),
(55, 3, 5, 'tendo aparência de piedade, mas negando o seu poder. Afaste-se também destes.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 6, 'São estes os que se introduzem pelas casas e conquistam mulherzinhas sobrecarregadas de pecados, as quais se deixam levar por toda espécie de desejos.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 7, 'Elas estão sempre aprendendo, mas não conseguem nunca de chegar ao conhecimento da verdade.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 8, 'Como Janes e Jambres se opuseram a Moisés, esses também resistem à verdade. A mente deles é depravada; são reprovados na fé.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 9, 'Não irão longe, porém; como no caso daqueles, a sua insensatez se tornará evidente a todos.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 10, 'Mas você tem seguido de perto o meu ensino, a minha conduta, o meu propósito, a minha fé, a minha paciência, o meu amor, a minha perseverança,', 3, CURRENT_TIMESTAMP, false),
(55, 3, 11, 'as perseguições e os sofrimentos que enfrentei, coisas que me aconteceram em Antioquia, Icônio e Listra. Quanta perseguição suportei! Mas, de todas essas coisas o Senhor me livrou!', 3, CURRENT_TIMESTAMP, false),
(55, 3, 12, 'De fato, todos os que desejam viver piedosamente em Cristo Jesus serão perseguidos.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 13, 'Contudo, os perversos e impostores irão de mal a pior, enganando e sendo enganados.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 14, 'Quanto a você, porém, permaneça nas coisas que aprendeu e das quais tem convicção, pois você sabe de quem o aprendeu.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 15, 'Porque desde criança você conhece as sagradas letras, que são capazes de torná-lo sábio para a salvação mediante a fé em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(55, 3, 16, 'Toda a Escritura é inspirada por Deus e útil para o ensino, para a repreensão, para a correção e para a instrução na justiça,', 3, CURRENT_TIMESTAMP, false),
(55, 3, 17, 'para que o homem de Deus seja apto e plenamente preparado para toda boa obra.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 1, 'Na presença de Deus e de Cristo Jesus, que há de julgar os vivos e os mortos por sua manifestação e por seu Reino, eu o exorto solenemente:', 3, CURRENT_TIMESTAMP, false),
(55, 4, 2, 'Pregue a palavra, esteja preparado a tempo e fora de tempo, repreenda, corrija, exorte com toda a paciência e doutrina.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 3, 'Pois virá o tempo em que não suportarão a sã doutrina; pelo contrário, sentindo coceira nos ouvidos, segundo os seus próprios desejos juntarão mestres para si mesmos.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 4, 'Eles se recusarão a dar ouvidos à verdade, voltando-se para os mitos.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 5, 'Você, porém, seja sóbrio em tudo, suporte os sofrimentos, faça a obra de um evangelista, cumpra plenamente o seu ministério.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 6, 'Eu já estou sendo derramado como uma oferta de bebida. Está próximo o tempo da minha partida.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 7, 'Combati o bom combate, terminei a corrida, guardei a fé.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 8, 'Agora me está reservada a coroa da justiça, que o Senhor, justo Juiz, me dará naquele dia; e não somente a mim, mas também a todos os que amam a sua vinda.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 9, 'Procure vir logo ao meu encontro,', 3, CURRENT_TIMESTAMP, false),
(55, 4, 10, 'pois Demas, amando este mundo, abandonou-me e foi para Tessalônica. Crescente foi para a Galácia, e Tito, para a Dalmácia.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 11, 'Só Lucas está comigo. Traga Marcos com você, porque ele me é útil para o ministério.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 12, 'Enviei Tíquico a Éfeso.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 13, 'Quando você vier, traga a capa que deixei na casa de Carpo, em Trôade, e os meus livros, especialmente os pergaminhos.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 14, 'Alexandre, o ferreiro, causou-me muitos males. O Senhor lhe dará a retribuição pelo que fez.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 15, 'Previna-se contra ele, porque se opôs fortemente às nossas palavras.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 16, 'Na minha primeira defesa, ninguém apareceu para me apoiar; todos me abandonaram. Que isso não lhes cobrado.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 17, 'Mas o Senhor permaneceu ao meu lado e me deu forças, para que por mim a mensagem fosse plenamente proclamada, e todos os gentios a ouvissem. E eu fui libertado da boca do leão.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 18, 'O Senhor me livrará de toda obra maligna e me levará a salvo para o seu Reino celestial. A ele seja a glória para todo o sempre. Amém.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 19, 'Saudações a Priscila e Áqüila, e à casa de Onesíforo.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 20, 'Erasto permaneceu em Corinto, mas deixei Trófimo doente em Mileto.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 21, 'Procure vir antes do inverno. Êubulo, Prudente, Lino, Cláudia e todos os irmãos enviam-lhe saudações.', 3, CURRENT_TIMESTAMP, false),
(55, 4, 22, 'O Senhor seja com o seu espírito. A graça seja com vocês.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 1, 'O presbítero ao amado Gaio, a quem amo na verdade.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 2, 'Amado, oro para que você tenha boa saúde e tudo lhe corra bem, assim como vai bem a sua alma.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 3, 'Muito me alegrei ao receber a visita de alguns irmãos que falaram a respeito da sua fidelidade, de como você continua andando na verdade.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 4, 'Não tenho alegria maior do que ouvir que meus filhos estão andando na verdade.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 5, 'Amado, você é fiel no que está fazendo pelos irmãos, apesar de lhe serem desconhecidos.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 6, 'Eles falaram à igreja a respeito deste seu amor. Você fará bem se os encaminhar em sua viagem de modo agradável a Deus,', 3, CURRENT_TIMESTAMP, false),
(64, 1, 7, 'pois foi por causa do Nome que eles saíram, sem receber ajuda alguma dos gentios.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 8, 'É, pois, nosso dever receber com hospitalidade a irmãos como esses, para que nos tornemos cooperadores em favor da verdade.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 9, 'Escrevi à igreja, mas Diótrefes, que gosta muito de ser o mais importante entre eles, não nos recebe.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 10, 'Portanto, se eu for, chamarei a atenção dele para o que está fazendo com suas palavras maldosas contra nós. Não satisfeito com isso, ele se recusa a receber os irmãos, impede os que desejam recebê-los e os expulsa da igreja.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 11, 'Amado, não imite o que é mau, mas sim o que é bom. Aquele que faz o bem é de Deus; aquele que faz o mal não viu a Deus.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 12, 'Quanto a Demétrio, todos dão bom testemunho dele, inclusive a própria verdade. Nós também damos, e você sabe que o nosso testemunho é verdadeiro.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 13, 'Tenho muito que lhe escrever, mas não desejo fazê-lo com pena e tinta.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 14, 'Espero vê-lo em breve, e então conversaremos face a face.', 3, CURRENT_TIMESTAMP, false),
(64, 1, 15, 'A paz seja com você. Os amigos daqui lhe enviam saudações. Saúde os amigos daí, um por um.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 1, 'No primeiro dia do sexto mês do segundo ano do reinado de Dario, a palavra do Senhor veio por meio do profeta Ageu ao governador de Judá, Zorobabel, filho de Sealtiel, e ao sumo sacerdote Josué, filho de Jeozadaque, dizendo:', 3, CURRENT_TIMESTAMP, false),
(37, 1, 2, '"Assim diz o Senhor dos Exércitos: Este povo afirma: ‘Ainda não chegou o tempo de reconstruir a casa do Senhor’ ".', 3, CURRENT_TIMESTAMP, false),
(37, 1, 3, 'Por isso, a palavra do Senhor veio novamente por meio do profeta Ageu:', 3, CURRENT_TIMESTAMP, false),
(37, 1, 4, '"Acaso é tempo de vocês morarem em casas de fino acabamento, enquanto a minha casa continua destruída? "', 3, CURRENT_TIMESTAMP, false),
(37, 1, 5, 'Agora, assim diz o Senhor dos Exércitos: "Vejam aonde os seus caminhos os levaram.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 6, 'Vocês têm plantado muito, e colhido pouco. Vocês comem, mas não se fartam. Bebem, mas não se satisfazem. Vestem-se, mas não se aquecem. Aquele que recebe salário, recebe-o para colocá-lo numa bolsa furada".', 3, CURRENT_TIMESTAMP, false),
(37, 1, 7, 'Assim diz o Senhor dos Exércitos: "Vejam aonde os seus caminhos os levaram!', 3, CURRENT_TIMESTAMP, false),
(37, 1, 8, 'Subam o monte para trazer madeira. Construam o templo, para que eu me alegre e nele seja glorificado", diz o Senhor.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 9, '"Vocês esperavam muito, mas, para surpresa de vocês, acabou sendo pouco. E o que vocês trouxeram para casa eu dissipei com um sopro. E por que fiz isso? ", pergunta o Senhor dos Exércitos. "Por causa do meu templo, que ainda está destruído, enquanto cada um de vocês se ocupa com a sua própria casa.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 10, 'Por isso, por causa de vocês, o céu reteu o orvalho e a terra deixou de dar o seu fruto.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 11, 'Provoquei uma seca nos campos e nos montes, que atingiu o trigo, o vinho, o azeite e tudo mais que a terra produz, e também os homens e o gado. O trabalho das mãos de vocês foi prejudicado".', 3, CURRENT_TIMESTAMP, false),
(37, 1, 12, 'Zorobabel, filho de Sealtiel, o sumo sacerdote Josué, filho de Jeozadaque, e todo o restante do povo obedeceram à voz do Senhor, o seu Deus, por causa das palavras do profeta Ageu, a quem o Senhor, o seu Deus, enviara. E o povo temeu ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 13, 'Então Ageu, o mensageiro do Senhor, trouxe esta mensagem do Senhor para o povo: "Eu estou com vocês", declara o Senhor.', 3, CURRENT_TIMESTAMP, false),
(37, 1, 14, 'Assim o Senhor encorajou o governador de Judá, Zorobabel, filho de Sealtiel, o sumo sacerdote Josué, filho de Jeozadaque, e todo o restante do povo, de modo que eles começaram a trabalhar no templo do Senhor dos Exércitos, o seu Deus,', 3, CURRENT_TIMESTAMP, false),
(37, 1, 15, 'no dia vinte e quatro do sexto mês do segundo ano do reinado de Dario.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 1, 'No dia vinte e um do sétimo mês, veio a palavra do Senhor por meio do profeta Ageu:', 3, CURRENT_TIMESTAMP, false),
(37, 2, 2, '"Pergunte ao governador de Judá, Zorobabel, filho de Sealtiel, ao sumo sacerdote Josué, filho de Jeozadaque, e ao restante do povo, o seguinte:', 3, CURRENT_TIMESTAMP, false),
(37, 2, 3, '‘Quem de vocês viu este templo em seu primeiro esplendor? Comparado com ele, não é como nada o que vocês vêem agora?', 3, CURRENT_TIMESTAMP, false),
(37, 2, 4, '"Coragem, Zorobabel", declara o Senhor. "Coragem, sumo sacerdote Josué, filho de Jeozadaque. Coragem! Ao trabalho, ó povo da terra! ", declara o Senhor. "Porque eu estou com vocês", declara o Senhor dos Exércitos.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 5, 'Esta é a aliança que fiz com vocês quando vocês saíram do Egito: "Meu espírito está entre vocês. Não tenham medo".', 3, CURRENT_TIMESTAMP, false),
(37, 2, 6, 'Assim diz o Senhor dos Exércitos: "Dentro de pouco tempo farei tremer o céu, a terra, o mar e o continente.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 7, 'Farei tremer todas as nações, que trarão para cá os seus tesouros, e encherei este templo de glória", diz o Senhor dos Exércitos.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 8, '"Tanto a prata quanto o ouro me pertencem", declara o Senhor dos Exércitos.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 9, '"A glória deste novo templo será maior do que a do antigo", diz o Senhor dos Exércitos. "E neste lugar estabelecerei a paz", declara o Senhor dos Exércitos.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 10, 'No dia vinte e quatro do nono mês, no segundo ano do reinado de Dario, a palavra do Senhor veio ao profeta Ageu:', 3, CURRENT_TIMESTAMP, false),
(37, 2, 11, '"Assim diz o Senhor dos Exércitos: ‘Pergunte aos sacerdotes sobre a seguinte questão da Lei:', 3, CURRENT_TIMESTAMP, false),
(37, 2, 12, 'Se alguém levar carne consagrada na borda de suas vestes, e com ela tocar num pão, ou em algo cozido, ou em vinho, ou em azeite ou em qualquer comida, isso ficará consagrado? ’ " Os sacerdotes responderam: "Não".', 3, CURRENT_TIMESTAMP, false),
(37, 2, 13, 'Em seguida perguntou Ageu: "Se alguém ficar impuro por tocar num cadáver e depois tocar em alguma dessas coisas, ela ficará impura? "Sim", responderam os sacerdotes, "ficará impura".', 3, CURRENT_TIMESTAMP, false),
(37, 2, 14, 'Então disse Ageu: "É o que acontece com este povo e com esta nação", declara o Senhor. "Tudo o que fazem e tudo o que me oferecem é impuro".', 3, CURRENT_TIMESTAMP, false),
(37, 2, 15, '"Agora prestem atenção: de hoje em diante reconsiderem. Como eram as coisas antes que se colocasse pedra sobre pedra no templo do Senhor?', 3, CURRENT_TIMESTAMP, false),
(37, 2, 16, 'Quando alguém chegava a um monte de trigo procurando vinte medidas, havia apenas dez. Quando alguém ia ao depósito de vinho para tirar cinqüenta medidas, só encontrava vinte.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 17, 'Eu destruí todo o trabalho das mãos de vocês, com mofo, ferrugem e granizo, mas vocês não se voltaram para mim", declara o Senhor.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 18, '"A partir de hoje, dia vinte e quatro do nono mês, atentem para o dia em que os fundamentos do templo do Senhor foram lançados. Reconsiderem:', 3, CURRENT_TIMESTAMP, false),
(37, 2, 19, 'Ainda há alguma semente no celeiro? Até hoje a videira, a figueira, a romeira e a oliveira não têm dado fruto. Mas, de hoje em diante, abençoarei vocês".', 3, CURRENT_TIMESTAMP, false),
(37, 2, 20, 'A palavra do Senhor veio a Ageu pela segunda vez, no dia vinte e quatro do nono mês:', 3, CURRENT_TIMESTAMP, false),
(37, 2, 21, '"Diga a Zorobabel, governador de Judá, que eu farei tremer o céu e a terra.', 3, CURRENT_TIMESTAMP, false),
(37, 2, 22, 'Derrubarei tronos e destruirei o poder dos reinos estrangeiros. Virarei os carros e os seus condutores; os cavalos e os seus cavaleiros cairão, cada um pela espada do seu companheiro".', 3, CURRENT_TIMESTAMP, false),
(37, 2, 23, '"Naquele dia", declara o Senhor dos Exércitos, "eu o tomarei, meu servo Zorobabel, filho de Sealtiel", declara o Senhor, "e farei de você um anel de selar, porque o tenho escolhido", declara o Senhor dos Exércitos.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 1, 'Palavras que Amós, criador de ovelhas em Tecoa, recebeu em visões, a respeito de Israel dois anos antes do terremoto. Nesse tempo, Uzias era rei de Judá e Jeroboão, filho de Jeoás, era rei de Israel.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 2, 'Ele disse: "O SENHOR ruge de Sião e troveja de Jerusalém; secam-se as pastagens dos pastores, e murcha o topo do Carmelo".', 3, CURRENT_TIMESTAMP, false),
(30, 1, 3, 'Assim diz o SENHOR: "Por três transgressões de Damasco e ainda mais por quatro, não anularei o castigo. Porque trilhou Gileade com trilhos de ferro pontudos,', 3, CURRENT_TIMESTAMP, false),
(30, 1, 4, 'porei fogo na casa de Hazael que consumirá as fortalezas de Ben-Hadade.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 5, 'Derrubarei a porta de Damasco; destruirei o rei que está no vale de Áven e aquele que segura o cetro em Bete-Éden. O povo da Síria irá para o exílio em Quir", diz o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 6, 'Assim diz o SENHOR: "Por três transgressões de Gaza, e ainda mais por quatro, não anularei o castigo. Porque levou cativas comunidades inteiras e as vendeu a Edom,', 3, CURRENT_TIMESTAMP, false),
(30, 1, 7, 'porei fogo nos muros de Gaza, que consumirá as suas fortalezas.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 8, 'Destruirei o rei de Asdode e aquele que segura o cetro em Ascalom. Erguerei a minha mão contra Ecrom, até que morra o último dos filisteus", diz o SENHOR Soberano.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 9, 'Assim diz o SENHOR: "Por três transgressões de Tiro, e ainda mais por quatro, não anularei o castigo. Porque vendeu comunidades inteiras de cativos a Edom, desprezando irmãos,', 3, CURRENT_TIMESTAMP, false),
(30, 1, 10, 'porei fogo nos muros de Tiro, que consumirá as suas fortalezas".', 3, CURRENT_TIMESTAMP, false),
(30, 1, 11, 'Assim diz o SENHOR: "Por três transgressões de Edom, e ainda mais por quatro, não anularei o castigo. Porque com a espada perseguiu seu irmão, e reprimiu toda a compaixão, mutilando-o furiosamente e perpetuando para sempre a sua ira,', 3, CURRENT_TIMESTAMP, false),
(30, 1, 12, 'porei fogo em Temã, que consumirá as fortalezas de Bozra".', 3, CURRENT_TIMESTAMP, false),
(30, 1, 13, 'Assim diz o SENHOR: "Por três transgressões de Amom, e ainda mais por quatro, não anularei o castigo. Porque rasgou ao meio as grávidas de Gileade a fim de ampliar as suas fronteiras,', 3, CURRENT_TIMESTAMP, false),
(30, 1, 14, 'porei fogo nos muros de Rabá, que consumirá as suas fortalezas em meio a gritos de guerra no dia do combate, em meio a ventos violentos num dia de tempestade.', 3, CURRENT_TIMESTAMP, false),
(30, 1, 15, 'O seu rei irá para o exílio, ele e toda a sua corte", diz o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 1, 'Assim diz o SENHOR: "Por três transgressões de Moabe, e ainda mais por quatro, não anularei o castigo. Porque ele queimou até reduzir a cinzas os ossos do rei de Edom,', 3, CURRENT_TIMESTAMP, false),
(30, 2, 2, 'porei fogo em Moabe, que consumirá as fortalezas de Queriote. Moabe perecerá em grande tumulto, em meio a gritos de guerra e ao toque da trombeta.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 3, 'Destruirei o seu governante e com ele matarei todas as autoridades", diz o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 4, 'Assim diz o SENHOR: "Por três transgressões de Judá, e ainda mais por quatro, não anularei o castigo. Porque rejeitou a lei do SENHOR e não obedeceu aos seus decretos, porque se deixou enganar por deuses falsos, deuses que os seus antepassados seguiram,', 3, CURRENT_TIMESTAMP, false),
(30, 2, 5, 'porei fogo em Judá, que consumirá as fortalezas de Jerusalém".', 3, CURRENT_TIMESTAMP, false),
(30, 2, 6, 'Assim diz o SENHOR: "Por três transgressões de Israel, e ainda mais por quatro, não anularei o castigo. Vendem por prata o justo, e por um par de sandálias o pobre.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 7, 'Pisam sobre a cabeça dos necessitados como pisam no pó da terra, e negam justiça ao oprimido. Pai e filho possuem a mesma mulher e assim profanam o meu santo nome.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 8, 'Inclinam-se ao lado de todo altar com roupas tomadas como penhor. No templo do seu deus bebem vinho recebido como multa.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 9, '"Fui eu que destruí os amorreus diante deles, embora fossem altos como o cedro e fortes como o carvalho. Eu destruí os seus frutos em cima e as suas raízes embaixo".', 3, CURRENT_TIMESTAMP, false),
(30, 2, 10, '"Eu mesmo os tirei do Egito, e os conduzi por quarenta anos no deserto para lhes dar a terra dos amorreus.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 11, 'Também escolhi alguns de seus filhos para serem profetas e alguns de seus jovens para serem nazireus. Não é verdade, povo de Israel? ", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 12, '"Mas vocês fizeram os nazireus beber vinho e ordenaram aos profetas que não profetizassem".', 3, CURRENT_TIMESTAMP, false),
(30, 2, 13, '"Agora, então, eu os amassarei como uma carroça amassa a terra quando carregada de trigo.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 14, 'O ágil não escapará, o forte não reunirá as suas forças, e o guerreiro não salvará a sua vida.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 15, 'O arqueiro não manterá a sua posição, o que corre não se livrará, e o cavaleiro não salvará a própria vida.', 3, CURRENT_TIMESTAMP, false),
(30, 2, 16, 'Até mesmo os guerreiros mais corajosos fugirão nus naquele dia", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 3, 1, 'Ouçam esta palavra que o SENHOR falou contra vocês, ó israelitas; contra toda esta família que tirei do Egito:', 3, CURRENT_TIMESTAMP, false),
(30, 3, 2, '"Escolhi apenas vocês de todas as famílias da terra; por isso eu os castigarei por causa de todas as suas maldades".', 3, CURRENT_TIMESTAMP, false),
(30, 3, 3, 'Duas pessoas andarão juntas se não tiverem de acordo?', 3, CURRENT_TIMESTAMP, false),
(30, 3, 4, 'O leão ruge na floresta se não apanhou presa alguma? O leão novo ruge em sua toca se nada caçou?', 3, CURRENT_TIMESTAMP, false),
(30, 3, 5, 'Cai o pássaro num laço se não há nenhuma armadilha? Será que a armadilha do laço se desarma se nada foi apanhado?', 3, CURRENT_TIMESTAMP, false),
(30, 3, 6, 'Quando a trombeta toca na cidade, o povo não treme? Ocorre alguma desgraça na cidade, sem que o SENHOR a tenha mandado?', 3, CURRENT_TIMESTAMP, false),
(30, 3, 7, 'Certamente o SENHOR Soberano não faz coisa alguma sem revelar o seu plano aos seus servos, os profetas.', 3, CURRENT_TIMESTAMP, false),
(30, 3, 8, 'O leão rugiu, quem não temerá? O SENHOR Soberano falou, quem não profetizará?', 3, CURRENT_TIMESTAMP, false),
(30, 3, 9, 'Proclamem os palácios de Asdode e do Egito: "Reúnam-se nos montes de Samaria para verem o grande tumulto que há ali e a opressão no meio do seu povo".', 3, CURRENT_TIMESTAMP, false),
(30, 3, 10, '"Eles não sabem como agir direito", declara o SENHOR, "eles, que acumulam em seus palácios o que roubaram e saquearam".', 3, CURRENT_TIMESTAMP, false),
(30, 3, 11, 'Portanto, assim diz o SENHOR Soberano: "Um inimigo está cercando o país. Ele derrubará as suas fortalezas e saqueará os seus palácios".', 3, CURRENT_TIMESTAMP, false),
(30, 3, 12, 'Assim diz o SENHOR: "Assim como o pastor arranca da boca do leão só dois ossos da perna ou um pedaço da orelha, assim serão arrancados os israelitas de Samaria, com um canto de cama e um pedaço de sofá.', 3, CURRENT_TIMESTAMP, false),
(30, 3, 13, '"Ouçam isto e testemunhem contra a descendência de Jacó", declara o SENHOR Soberano, o Deus dos Exércitos.', 3, CURRENT_TIMESTAMP, false),
(30, 3, 14, '"No dia em que eu castigar Israel por causa dos seus pecados, destruirei os altares de Betel; as pontas do altar serão cortadas e cairão no chão.', 3, CURRENT_TIMESTAMP, false),
(30, 3, 15, 'Derrubarei a casa de inverno junto com a casa de verão; as casas enfeitadas de marfim serão destruídas, e as mansões desaparecerão", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 1, 'Ouçam esta palavra, vocês, vacas de Basã que estão no monte de Samaria, vocês, que oprimem os pobres e esmagam os necessitados e dizem aos senhores deles: "Tragam bebidas e vamos beber! "', 3, CURRENT_TIMESTAMP, false),
(30, 4, 2, 'O SENHOR Soberano jurou pela sua santidade: "Certamente vai chegar o tempo em que serão levados com ganchos, e os últimos de vocês com anzóis.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 3, 'Cada um de vocês sairá pelas brechas no muro, e vocês serão atirados na direção do Hermom", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 4, '"Vão a Betel e ponham-se a pecar; vão a Gilgal e pequem ainda mais. Ofereçam os seus sacrifícios cada manhã, os seus dízimos no terceiro dia.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 5, 'Queimem pão fermentado como oferta de gratidão e fiquem proclamando por aí suas ofertas voluntárias; anunciem-nas, israelitas, pois é isso o que gostam de fazer", declara o SENHOR Soberano.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 6, '"Fui eu mesmo quem deu a vocês estômagos vazios em cada cidade e falta de alimentos em todo lugar, e ainda assim vocês não se voltaram para mim", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 7, '"Também fui eu que retive a chuva quando ainda faltavam três meses para a colheita. Mandei chuva a uma cidade, mas não a outra. Uma plantação teve chuva; outra não teve e secou.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 8, 'Gente de duas ou três cidades ia cambaleando de uma cidade a outra em busca de água, sem matar a sede, e ainda assim vocês não se voltaram para mim", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 9, '"Muitas vezes castiguei os seus jardins e as suas vinhas, castiguei-os com pragas e ferrugem. Gafanhotos devoraram as suas figueiras e as suas oliveiras, e ainda assim vocês não se voltaram para mim", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 10, '"Enviei pragas contra vocês como fiz com o Egito. Matei os seus jovens à espada, deixei que capturassem os seus cavalos. Enchi os seus narizes com o mau cheiro dos mortos em seus acampamentos, e ainda assim vocês não se voltaram para mim", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 11, '"Destruí algumas de suas cidades, como destruí Sodoma e Gomorra. Ficaram como um tição tirado do fogo, e ainda assim vocês não se voltaram para mim", declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 4, 12, '"Por isso, ainda os castigarei, ó Israel, e, porque eu farei isto com você, prepare-se para encontrar-se com o seu Deus, ó Israel. "', 3, CURRENT_TIMESTAMP, false),
(30, 4, 13, 'Aquele que forma os montes, cria o vento e revela os seus pensamentos ao homem, aquele que transforma a alvorada em trevas, e pisa sobre as montanhas da terra; o SENHOR, o Deus dos Exércitos, é o seu nome.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 1, 'Ouça esta palavra, ó nação de Israel, este lamento acerca de vocês:', 3, CURRENT_TIMESTAMP, false),
(30, 5, 2, '"Caída para nunca mais se levantar, está a Virgem Israel. Abandonada em sua própria terra, não há quem a levante".', 3, CURRENT_TIMESTAMP, false),
(30, 5, 3, 'Assim diz o Soberano SENHOR: "A cidade que mandar mil para o exército ficará com cem; e a que mandar cem ficará com dez".', 3, CURRENT_TIMESTAMP, false),
(30, 5, 4, 'Assim diz o SENHOR à nação de Israel: "Busquem-me e terão vida;', 3, CURRENT_TIMESTAMP, false),
(30, 5, 5, 'não busquem Betel, não vão a Gilgal, não façam peregrinação a Berseba. Pois Gilgal certamente irá para o exílio, e Betel será reduzida a nada".', 3, CURRENT_TIMESTAMP, false),
(30, 5, 6, 'Busquem o SENHOR e terão vida, do contrário, ele irromperá como um fogo entre os descendentes de José, e a devastará, e não haverá ninguém em Betel para apagá-lo.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 7, 'Vocês estão transformando o direito em amargura e atirando a justiça ao chão,', 3, CURRENT_TIMESTAMP, false),
(30, 5, 8, '( aquele que fez as Plêiades e o Órion, que faz da escuridão alvorada e do dia, noite escura, que chama as águas do mar e as espalha sobre a face da terra, o SENHOR é o seu nome.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 9, 'Ele traz repentina destruição sobre a fortaleza, e a destruição vem sobre a cidade fortificada ),', 3, CURRENT_TIMESTAMP, false),
(30, 5, 10, 'vocês odeiam aquele que defende a justiça no tribunal e detestam aquele que conta a verdade.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 11, 'Vocês pisam no pobre e o forçam a dar-lhes o trigo. Por isso, embora vocês tenham construído mansões de pedra, nelas não morarão; embora tenham plantado vinhas verdejantes, não beberão do seu vinho.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 12, 'Pois sei quantas são as suas transgressões e quão grandes são os seus pecados. Vocês oprimem o justo, recebem suborno e impedem que se faça justiça ao pobre nos tribunais.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 13, 'Por isso o prudente se cala em tais situações, pois é tempo de desgraças.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 14, 'Busquem o bem, não o mal, para que tenham vida. Então o SENHOR, o Deus dos Exércitos, estará com vocês, conforme vocês afirmam.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 15, 'Odeiem o mal, amem o bem; estabeleçam a justiça nos tribunais. Talvez o SENHOR, o Deus dos Exércitos, tenha misericórdia do remanescente de José.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 16, 'Portanto assim diz o SENHOR, o Deus dos Exércitos, o Soberano: "Haverá lamentação em todas as praças e gritos de angústia em todas as ruas. Os lavradores serão convocados para chorar e os pranteadores para lamentar.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 17, 'Haverá lamentos em todas as vinhas, pois passarei no meio de vocês", diz o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 18, 'Ai de vocês que anseiam pelo dia do SENHOR! O que pensam vocês do dia do SENHOR? Será dia de trevas, não de luz.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 19, 'Será como se um homem fugisse de um leão, e encontrasse um urso; como alguém que entrasse em sua casa e, encostando a mão na parede, fosse picado por uma serpente.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 20, 'O dia do SENHOR será de trevas e não de luz. Uma escuridão total, sem um raio de claridade.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 21, '"Eu odeio e desprezo as suas festas religiosas; não suporto as suas assembléias solenes.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 22, 'Mesmo que vocês me tragam holocaustos e ofertas de cereal, isso não me agradará. Mesmo que me tragam as melhores ofertas de comunhão, não darei a menor atenção a elas.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 23, 'Afastem de mim o som das suas canções e a música das suas liras.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 24, 'Em vez disso, corra a retidão como um rio, a justiça como um ribeiro perene! "', 3, CURRENT_TIMESTAMP, false),
(30, 5, 25, '"Foi a mim que vocês trouxeram sacrifícios e ofertas durante os quarenta anos no deserto, ó nação de Israel?', 3, CURRENT_TIMESTAMP, false),
(30, 5, 26, 'Não! Vocês carregaram o seu rei Sicute, e Quium, imagens dos deuses astrais, que vocês fizeram para si mesmos.', 3, CURRENT_TIMESTAMP, false),
(30, 5, 27, 'Por isso eu os mandarei para o exílio, para além de Damasco", diz o SENHOR, o Deus dos Exércitos é o seu nome.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 1, 'Ai de vocês que vivem tranqüilos em Sião, e que se sentem seguros no monte de Samaria; vocês, homens notáveis da primeira entre as nações, aos quais o povo de Israel recorre!', 3, CURRENT_TIMESTAMP, false),
(30, 6, 2, 'Vão a Calné e olhem para ela; depois prossigam até a grande Hamate e em seguida desçam até Gate, na Filístia. São elas melhores do que os seus dois reinos? O território delas é maior do que o de vocês?', 3, CURRENT_TIMESTAMP, false),
(30, 6, 3, 'Vocês acham que estão afastando o dia mau mas na verdade estão atraindo o reinado do terror.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 4, 'Vocês se deitam em camas de marfim e se espreguiçam em seus sofás. Comem os melhores cordeiros e os novilhos mais gordos.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 5, 'Dedilham em suas liras como Davi e improvisam em instrumentos musicais.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 6, 'Vocês bebem vinho em grandes taças e se ungem com os mais finos óleos, mas não se entristecem com a ruína de José.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 7, 'Por isso vocês estarão entre os primeiros a ir para o exílio; cessarão os banquetes dos que vivem no ócio.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 8, 'O SENHOR Soberano jurou por si mesmo! Assim declara o SENHOR, o Deus dos Exércitos: "Eu detesto o orgulho de Jacó e odeio os seus palácios; entregarei a cidade e tudo que nela existe".', 3, CURRENT_TIMESTAMP, false),
(30, 6, 9, 'Se dez homens forem deixados numa casa, também eles morrerão.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 10, 'E se um parente que tiver que queimar os corpos vier para tirá-los da casa e perguntar a alguém que ainda estiver escondido ali: “Há mais alguém com você? ”, e a resposta for: “Não”, ele dirá: “Calado! Não devemos sequer mencionar o nome do SENHOR”.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 11, 'Pois o SENHOR deu a ordem, e ele despedaçará a casa grande e fará em pedacinhos a casa pequena.', 3, CURRENT_TIMESTAMP, false),
(30, 6, 12, 'Acaso correm os cavalos sobre os rochedos? Poderá alguém ará-los com bois? Mas vocês transformaram o direito em veneno, e o fruto da justiça em amargura;', 3, CURRENT_TIMESTAMP, false),
(30, 6, 13, 'vocês que se regozijam pela conquista de Lo-Debara e dizem: “Acaso não conquistamos Carnaimb com a nossa própria força? ”', 3, CURRENT_TIMESTAMP, false),
(30, 6, 14, 'Palavra do SENHOR, o Deus dos Exércitos: “Farei vir uma nação contra você, ó nação de Israel, e ela a oprimirá desde Lebo-Hamate até o vale da Arabá”.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 1, 'Foi isto que o SENHOR, o Soberano, me mostrou: ele estava preparando enxames de gafanhotos depois da colheita do rei, justo quando brotava a segunda safra.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 2, 'Depois que eles devoraram todas as plantas dos campos, eu clamei: “SENHOR Soberano, perdoa! Como Jacó poderá sobreviver? Ele é tão pequeno! ”', 3, CURRENT_TIMESTAMP, false),
(30, 7, 3, 'Então o SENHOR arrependeu-se e declarou: “Isso não acontecerá”.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 4, 'O Soberano, o SENHOR, mostrou-me também que, para o julgamento, estava chamando o fogo, o qual secou o grande abismo e devorou a terra.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 5, 'Então eu clamei: “Soberano SENHOR, eu te imploro que pares! Como Jacó poderá sobreviver? Ele é tão pequeno! ”', 3, CURRENT_TIMESTAMP, false),
(30, 7, 6, 'Então o SENHOR arrependeu-se e declarou: “Isso também não acontecerá”.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 7, 'Ele me mostrou ainda isto: o Senhor, com um prumo na mão, estava junto a um muro construído no rigor do prumo.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 8, 'E o SENHOR me perguntou: “O que você está vendo, Amós? ” “Um prumo”, respondi. Então disse o Senhor: “Veja! Estou pondo um prumo no meio de Israel, o meu povo; não vou poupá-lo mais.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 9, '“Os altares idólatras de Isaque serão destruídos, e os santuários de Israel ficarão em ruínas; com a espada me levantarei contra a dinastia de Jeroboão”.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 10, 'Então o sacerdote de Betel, Amazias, enviou esta mensagem a Jeroboão, rei de Israel: “Amós está tramando uma conspiração contra ti no centro de Israel. A nação não suportará as suas palavras.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 11, 'Amós está dizendo o seguinte: ‘Jeroboão morrerá à espada, e certamente Israel irá para o exílio, para longe da sua terra natal’ ”.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 12, 'Depois Amazias disse a Amós: “Vá embora, vidente! Vá profetizar em Judá; vá ganhar lá o seu pão.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 13, 'Não profetize mais em Betel, porque este é o santuário do rei e o templo do reino”.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 14, 'Amós respondeu a Amazias: “Eu não sou profeta nem pertenço a nenhum grupo de profetasc, apenas cuido do gado e faço colheita de figos silvestres.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 15, 'Mas o SENHOR me tirou do serviço junto ao rebanho e me disse: ‘Vá, profetize a Israel, o meu povo’.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 16, 'Agora ouça, então, a palavra do SENHOR. Você diz: “ ‘Não profetize contra Israel, e pare de pregar contra a descendência de Isaque’.', 3, CURRENT_TIMESTAMP, false),
(30, 7, 17, '“Mas, o SENHOR lhe diz: “ ‘Sua mulher se tornará uma prostituta na cidade, e os seus filhos e as suas filhas morrerão à espada. Suas terras serão loteadas, e você mesmo morrerá numa terra pagãa. E Israel certamente irá para o exílio, para longe da sua terra natal’ ”.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 1, 'O SENHOR, o Soberano, me mostrou um cesto de frutas maduras.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 2, '“O que você está vendo, Amós? ”, ele perguntou. Um cesto de frutas maduras, respondi. Então o SENHOR me disse: “Chegou o fim de Israel, o meu povo; não mais o pouparei”.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 3, '“Naquele dia”, declara o SENHOR, o Soberano, “as canções no templo se tornarão lamentos. Muitos, muitos serão os corpos, atirados por todos os lados! Silêncio! ”', 3, CURRENT_TIMESTAMP, false),
(30, 8, 4, 'Ouçam, vocês que pisam os pobres e arruínam os necessitados da terra,', 3, CURRENT_TIMESTAMP, false),
(30, 8, 5, 'dizendo: “Quando acabará a lua nova para que vendamos o cereal? E quando terminará o sábado para que comercializemos o trigo, diminuindo a medida, aumentando o preço, enganando com balanças desonestas e', 3, CURRENT_TIMESTAMP, false),
(30, 8, 6, 'comprando o pobre com prata e o necessitado por um par de sandálias, vendendo até palha com o trigo? ”', 3, CURRENT_TIMESTAMP, false),
(30, 8, 7, 'O SENHOR jurou contra o orgulho de Jacó: “Jamais esquecerei coisa alguma do que eles fizeram.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 8, '“Acaso não tremerá a terra por causa disso, e não chorarão todos os que nela vivem? Toda esta terra se levantará como o Nilo; será agitada e depois afundará como o ribeiro do Egito.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 9, '“Naquele dia”, declara o SENHOR, o Soberano: “Farei o sol se pôr ao meio-dia e em plena luz do dia escurecerei a terra.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 10, 'Transformarei as suas festas em velório e todos os seus cânticos em lamentação. Farei que todos vocês vistam roupas de luto e rapem a cabeça. Farei daquele dia um dia de luto por um filho único, e o fim dele, como um dia de amargura.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 11, '“Estão chegando os dias”, declara o SENHOR, o Soberano, “em que enviarei fome a toda esta terra; não fome de comida nem sede de água, mas fome e sede de ouvir as palavras do SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 12, 'Os homens vaguearão de um mar a outro, do Norte ao Oriente, buscando a palavra do SENHOR, mas não a encontrarão.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 13, '“Naquele dia as jovens belas e os rapazes fortes desmaiarão de sede.', 3, CURRENT_TIMESTAMP, false),
(30, 8, 14, 'Aqueles que juram pela vergonhaa de Samaria, e os que dizem: ‘Juro pelo nome do seu deus, ó Dã’ ou ‘Juro pelo nome do deusb de Berseba’, cairão, para nunca mais se levantar! ”', 3, CURRENT_TIMESTAMP, false),
(30, 9, 1, 'Vi o Senhor junto ao altar, e ele disse: “Bata no topo das colunas para que tremam os umbrais. Faça que elas caiam sobre todos os presentes; e os que sobrarem matarei à espada. Ninguém fugirá, ninguém escapará.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 2, 'Ainda que escavem até às profundezas, dali a minha mão irá tirá-los. Se subirem até os céus, de lá os farei descer.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 3, 'Mesmo que se escondam no topo do Carmelo, lá os caçarei e os prenderei. Ainda que se escondam de mim no fundo do mar, ali ordenarei à serpente que os morda.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 4, 'Mesmo que sejam levados ao exílio por seus inimigos, ali ordenarei que a espada os mate. Vou vigiá-los para lhes fazer o mal e não o bem”.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 5, 'Quanto ao Senhor, o SENHOR dos Exércitos, ele toca na terra, e ela se derrete, e todos os que nela vivem pranteiam; ele ergue toda a terra como o Nilo, e depois a afunda como o ribeiro do Egito.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 6, 'Ele constrói suas câmaras altas, e firma a abóbada sobre a terra; ele reúne as águas do mar e as espalha sobre a superfície da terra. SENHOR é o seu nome.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 7, '“Vocês, israelitas, não são para mim melhores do que os etíopes”, declara o SENHOR. “Eu tirei Israel do Egito, os filisteus de Caftor e os arameus de Quir.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 8, '“Sem dúvida, os olhos do SENHOR, o Soberano, se voltam para este reino pecaminoso. Eu o varrerei da superfície da terra, mas não destruirei totalmente a descendência de Jacó”, declara o SENHOR.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 9, '“Pois darei a ordem, e sacudirei a nação de Israel entre todas as nações, tal como o trigo é abanado numa peneira, e nem um grão cai na terra.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 10, 'Todos os pecadores que há no meio do meu povo morrerão à espada, todos os que dizem: ‘A desgraça não nos atingirá nem nos encontrará’.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 11, '“Naquele dia levantarei a tenda caída de Davi. Consertarei o que estiver quebrado, e restaurarei as suas ruínas. Eu a reerguerei, para que seja como era no passado,', 3, CURRENT_TIMESTAMP, false),
(30, 9, 12, 'para que o meu povo conquiste o remanescente de Edom e todas as nações que me pertencem”, declara o SENHOR, que realizará essas coisas.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 13, '“Dias virão”, declara o SENHOR, “em que a ceifa continuará até o tempo de arar, e o pisar das uvas até o tempo de semear. Vinho novo gotejará dos montes e fluirá de todas as colinas.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 14, 'Trarei de volta Israel, o meu povo exilado, eles reconstruirão as cidades em ruínas e nelas viverão. Plantarão vinhas e beberão do seu vinho; cultivarão pomares e comerão do seu fruto.', 3, CURRENT_TIMESTAMP, false),
(30, 9, 15, 'Plantarei Israel em sua própria terra, para nunca mais ser desarraigado da terra que lhe dei”, diz o SENHOR, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 1, 'Revelação de Jesus Cristo, que Deus lhe deu para mostrar aos seus servos o que em breve há de acontecer. Ele enviou o seu anjo para torná-la conhecida ao seu servo João,', 3, CURRENT_TIMESTAMP, false),
(66, 1, 2, 'que dá testemunho de tudo o que viu, isto é, a palavra de Deus e o testemunho de Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 3, 'Feliz aquele que lê as palavras desta profecia e felizes aqueles que ouvem e guardam o que nela está escrito, porque o tempo está próximo.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 4, 'João às sete igrejas da província da Ásia: A vocês, graça e paz da parte daquele que é, que era e que há de vir, dos sete espíritos que estão diante do seu trono,', 3, CURRENT_TIMESTAMP, false),
(66, 1, 5, 'e de Jesus Cristo, que é a testemunha fiel, o primogênito dentre os mortos e o soberano dos reis da terra. Ele que nos ama e nos libertou dos nossos pecados por meio do seu sangue,', 3, CURRENT_TIMESTAMP, false),
(66, 1, 6, 'e nos constituiu reino e sacerdotes para servir a seu Deus e Pai. A ele sejam glória e poder para todo o sempre! Amém.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 7, 'Eis que ele vem com as nuvens, e todo olho o verá, até mesmo aqueles que o traspassaram; e todos os povos da terra se lamentarão por causa dele. Assim será! Amém.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 8, '"Eu sou o Alfa e o Ômega", diz o Senhor Deus, "o que é, o que era e o que há de vir, o Todo-poderoso".', 3, CURRENT_TIMESTAMP, false),
(66, 1, 9, 'Eu, João, irmão e companheiro de vocês no sofrimento, no Reino e na perseverança em Jesus, estava na ilha de Patmos, por causa da palavra de Deus e do testemunho de Jesus.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 10, 'No dia do Senhor achei-me no Espírito e ouvi por trás de mim uma voz forte, como de trombeta,', 3, CURRENT_TIMESTAMP, false),
(66, 1, 11, 'que dizia: "Escreva num livro o que você vê e envie a estas sete igrejas: Éfeso, Esmirna, Pérgamo, Tiatira, Sardes, Filadélfia e Laodicéia".', 3, CURRENT_TIMESTAMP, false),
(66, 1, 12, 'Voltei-me para ver quem falava comigo. Voltando-me, vi sete candelabros de ouro', 3, CURRENT_TIMESTAMP, false),
(66, 1, 13, 'e entre os candelabros alguém "semelhante a um filho de homem", com uma veste que chegava aos seus pés e um cinturão de ouro ao redor do peito.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 14, 'Sua cabeça e seus cabelos eram brancos como a lã, tão brancos quanto a neve, e seus olhos eram como chama de fogo.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 15, 'Seus pés eram como o bronze numa fornalha ardente e sua voz como o som de muitas águas.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 16, 'Tinha em sua mão direita sete estrelas, e da sua boca saía uma espada afiada de dois gumes. Sua face era como o sol quando brilha em todo o seu fulgor.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 17, 'Quando o vi, caí aos seus pés como morto. Então ele colocou sua mão direita sobre mim e disse: "Não tenha medo. Eu sou o primeiro e o último.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 18, 'Sou aquele que vive. Estive morto mas agora estou vivo para todo o sempre! E tenho as chaves da morte e do Hades.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 19, '"Escreva, pois, as coisas que você viu, tanto as presentes como as que estão por vir.', 3, CURRENT_TIMESTAMP, false),
(66, 1, 20, 'Este é o mistério das sete estrelas que você viu em minha mão direita e dos sete candelabros: as sete estrelas são os anjos das sete igrejas, e os sete candelabros são as sete igrejas".', 3, CURRENT_TIMESTAMP, false),
(66, 2, 1, 'Ao anjo da igreja em Éfeso escreva: Estas são as palavras daquele que tem as sete estrelas em sua mão direita e anda entre os sete candelabros de ouro.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 2, 'Conheço as suas obras, o seu trabalho árduo e a sua perseverança. Sei que você não pode tolerar homens maus, que pôs à prova os que dizem ser apóstolos mas não são, e descobriu que eles eram impostores.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 3, 'Você tem perseverado e suportado sofrimentos por causa do meu nome, e não tem desfalecido.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 4, 'Contra você, porém, tenho isto: você abandonou o seu primeiro amor.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 5, 'Lembre-se de onde caiu! Arrependa-se e pratique as obras que praticava no princípio. Se não se arrepender, virei a você e tirarei o seu candelabro do seu lugar.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 6, 'Mas há uma coisa a seu favor: você odeia as práticas dos nicolaítas, como eu também as odeio.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 7, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas. Ao vencedor darei o direito de comer da árvore da vida, que está no paraíso de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 8, 'Ao anjo da igreja em Esmirna escreva: Estas são as palavras daquele que é o Primeiro e o Último, que morreu e tornou a viver.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 9, 'Conheço as suas aflições e a sua pobreza; mas você é rico! Conheço a blasfêmia dos que se dizem judeus mas não são, sendo antes sinagoga de Satanás.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 10, 'Não tenha medo do que você está prestes a sofrer. Saibam que o diabo lançará alguns de vocês na prisão para prová-los, e vocês sofrerão perseguição durante dez dias. Seja fiel até a morte, e eu lhe darei a coroa da vida.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 11, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas. O vencedor de modo algum sofrerá a segunda morte.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 12, 'Ao anjo da igreja em Pérgamo escreva: Estas são as palavras daquele que tem a espada afiada de dois gumes.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 13, 'Sei onde você vive, onde está o trono de Satanás. Contudo, você permanece fiel ao meu nome e não renunciou à sua fé em mim, nem mesmo quando Antipas, minha fiel testemunha, foi morto nessa cidade, onde Satanás habita.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 14, 'No entanto, tenho contra você algumas coisas: você tem aí pessoas que se apegam aos ensinos de Balaão, que ensinou Balaque a armar ciladas contra os israelitas, induzindo-os a comer alimentos sacrificados a ídolos e a praticar imoralidade sexual.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 15, 'De igual modo você tem também os que se apegam aos ensinos dos nicolaítas.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 16, 'Portanto, arrependa-se! Se não, virei em breve até você e lutarei contra eles com a espada da minha boca.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 17, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas. Ao vencedor darei do maná escondido. Também lhe darei uma pedra branca com um novo nome nela inscrito, conhecido apenas por aquele que o recebe.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 18, 'Ao anjo da igreja em Tiatira escreva: Estas são as palavras do Filho de Deus, cujos olhos são como chama de fogo e os pés como bronze reluzente.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 19, 'Conheço as suas obras, o seu amor, a sua fé, o seu serviço e a sua perseverança, e sei que você está fazendo mais agora do que no princípio.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 20, 'No entanto, contra você tenho isto: você tolera Jezabel, aquela mulher que se diz profetisa. Com os seus ensinos, ela induz os meus servos à imoralidade sexual e a comerem alimentos sacrificados aos ídolos.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 21, 'Dei-lhe tempo para que se arrependesse da sua imoralidade sexual, mas ela não quer se arrepender.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 22, 'Por isso, vou fazê-la adoecer e trarei grande sofrimento aos que cometem adultério com ela, a não ser que se arrependam das obras que ela pratica.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 23, 'Matarei os filhos dessa mulher. Então, todas as igrejas saberão que eu sou aquele que sonda mentes e corações, e retribuirei a cada um de vocês de acordo com as suas obras.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 24, 'Aos demais que estão em Tiatira, a vocês que não seguem a doutrina dela e não aprenderam, como eles dizem, os profundos segredos de Satanás, digo: não porei outra carga sobre vocês;', 3, CURRENT_TIMESTAMP, false),
(66, 2, 25, 'tão-somente apeguem-se com firmeza ao que vocês têm, até que eu venha.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 26, 'Àquele que vencer e fizer a minha vontade até o fim darei autoridade sobre as nações.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 27, '"Ele as governará com cetro de ferro e as despedaçará a um vaso de barro"', 3, CURRENT_TIMESTAMP, false),
(66, 2, 28, 'Eu lhes darei a mesma autoridade que recebi autoridade de meu Pai. Também lhe darei a estrela da manhã.', 3, CURRENT_TIMESTAMP, false),
(66, 2, 29, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 1, 'Ao anjo da igreja em Sardes escreva: Estas são as palavras daquele que tem os sete espíritos de Deus e as sete estrelas. Conheço as suas obras; você tem fama de estar vivo, mas está morto.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 2, 'Esteja atento! Fortaleça o que resta e que estava para morrer, pois não achei suas obras perfeitas aos olhos do meu Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 3, 'Lembre-se, portanto, do que você recebeu e ouviu; obedeça e arrependa-se. Mas se você não estiver atento, virei como um ladrão e você não saberá a que hora virei contra você.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 4, 'No entanto, você tem aí em Sardes uns poucos que não contaminaram as suas vestes. Eles andarão comigo, vestidos de branco, pois são dignos.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 5, 'O vencedor será igualmente vestido de branco. Jamais apagarei o seu nome do livro da vida, mas o reconhecerei diante do meu Pai e dos seus anjos.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 6, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 7, 'Ao anjo da igreja em Filadélfia escreva: Estas são as palavras daquele que é santo e verdadeiro, que tem a chave de Davi. O que ele abre ninguém pode fechar, e o que ele fecha ninguém pode abrir.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 8, 'Conheço as suas obras. Eis que coloquei diante de você uma porta aberta que ninguém pode fechar. Sei que você tem pouca força, mas guardou a minha palavra e não negou o meu nome.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 9, 'Vejam o que farei com aqueles que são sinagoga de Satanás e que se dizem judeus e não são, mas são mentirosos. Farei que se prostrem aos seus pés e reconheçam que eu amei você.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 10, 'Visto que você guardou a minha palavra de exortação à perseverança, eu também o guardarei da hora da provação que está para vir sobre todo o mundo, para pôr à prova os que habitam na terra.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 11, 'Venho em breve! Retenha o que você tem, para que ninguém tome a sua coroa.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 12, 'Farei do vencedor uma coluna no santuário do meu Deus, e dali ele jamais sairá. Escreverei nele o nome do meu Deus e o nome da cidade do meu Deus, a nova Jerusalém, que desce do céu da parte de Deus; e também escreverei nele o meu novo nome.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 13, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 14, 'Ao anjo da igreja em Laodicéia escreva: Estas são as palavras do Amém, a testemunha fiel e verdadeira, o soberano da criação de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 15, 'Conheço as suas obras, sei que você não é frio nem quente. Melhor seria que você fosse frio ou quente!', 3, CURRENT_TIMESTAMP, false),
(66, 3, 16, 'Assim, porque você é morno, nem frio nem quente, estou a ponto de vomitá-lo da minha boca.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 17, 'Você diz: Estou rico, adquiri riquezas e não preciso de nada. Não reconhece, porém, que é miserável, digno de compaixão, pobre, cego e que está nu.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 18, 'Dou-lhe este aconselho: Compre de mim ouro refinado no fogo e você se tornará rico; compre roupas brancas e vista-se para cobrir a sua vergonhosa nudez; e compre colírio para ungir os seus olhos e poder enxergar.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 19, 'Repreendo e disciplino aqueles que eu amo. Por isso, seja diligente e arrependa-se.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 20, 'Eis que estou à porta e bato. Se alguém ouvir a minha voz e abrir a porta, entrarei e cearei com ele, e ele comigo.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 21, 'Ao vencedor darei o direito de sentar-se comigo em meu trono, assim como eu também venci e sentei-me com meu Pai em seu trono.', 3, CURRENT_TIMESTAMP, false),
(66, 3, 22, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas.', 3, CURRENT_TIMESTAMP, false),
(66, 4, 1, 'Depois dessas coisas olhei, e diante de mim estava uma porta aberta no céu. A voz que eu tinha ouvido no princípio, falando comigo como trombeta, disse: "Suba para cá, e lhe mostrarei o que deve acontecer depois dessas coisas".', 3, CURRENT_TIMESTAMP, false),
(66, 4, 2, 'Imediatamente me vi tomado pelo Espírito, e diante de mim estava um trono no céu e nele estava assentado alguém.', 3, CURRENT_TIMESTAMP, false),
(66, 4, 3, 'Aquele que estava assentado era de aspecto semelhante a jaspe e sardônio. Um arco-íris, parecendo uma esmeralda, circundava o trono,', 3, CURRENT_TIMESTAMP, false),
(66, 4, 4, 'ao redor do qual estavam outros vinte e quatro tronos, e assentados neles havia vinte e quatro anciãos. Eles estavam vestidos de branco e tinham na cabeça coroas de ouro.', 3, CURRENT_TIMESTAMP, false),
(66, 4, 5, 'Do trono saíam relâmpagos, vozes e trovões. Diante dele estavam acesas sete lâmpadas de fogo, que são os sete espíritos de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 4, 6, 'Também diante do trono havia algo parecido com um mar de vidro, claro como cristal. No centro, ao redor do trono, havia quatro seres viventes cobertos de olhos, tanto na frente como atrás.', 3, CURRENT_TIMESTAMP, false),
(66, 4, 7, 'O primeiro ser parecia um leão, o segundo parecia um boi, o terceiro tinha rosto como de homem, o quarto parecia uma águia quando em vôo.', 3, CURRENT_TIMESTAMP, false),
(66, 4, 8, 'Cada um deles tinha seis asas e era cheio de olhos, tanto ao redor como por baixo das asas. Dia e noite repetem sem cessar: "Santo, santo, santo é o Senhor, o Deus todo-poderoso, que era, que é e que há de vir".', 3, CURRENT_TIMESTAMP, false),
(66, 4, 9, 'Toda vez que os seres viventes dão glória, honra e graças àquele que está assentado no trono e que vive para todo o sempre,', 3, CURRENT_TIMESTAMP, false),
(66, 4, 10, 'os vinte e quatro anciãos se prostram diante daquele que está assentado no trono e adoram aquele que vive para todo o sempre. Eles lançam as suas coroas diante do trono, dizem:', 3, CURRENT_TIMESTAMP, false),
(66, 4, 11, '"Tu, Senhor e Deus nosso, és digno de receber a glória, a honra e o poder, porque criaste todas as coisas, e por tua vontade elas existem e foram criadas".', 3, CURRENT_TIMESTAMP, false),
(66, 5, 1, 'Então vi na mão direita daquele que está assentado no trono um livro em forma de rolo escrito de ambos os lados e selado com sete selos.', 3, CURRENT_TIMESTAMP, false),
(66, 5, 2, 'Vi um anjo poderoso, proclamando em alta voz: "Quem é digno de romper os selos e de abrir o livro? "', 3, CURRENT_TIMESTAMP, false),
(66, 5, 3, 'Mas não havia ninguém, nem no céu nem na terra nem debaixo da terra, que podia abrir o livro, ou sequer olhar para ele.', 3, CURRENT_TIMESTAMP, false),
(66, 5, 4, 'Eu chorava muito, porque não se encontrou ninguém que fosse digno de abrir o livro e de olhar para ele.', 3, CURRENT_TIMESTAMP, false),
(66, 5, 5, 'Então um dos anciãos me disse: "Não chore! Eis que o Leão da tribo de Judá, a Raiz de Davi, venceu para abrir o livro e os seus sete selos".', 3, CURRENT_TIMESTAMP, false),
(66, 5, 6, 'Então vi um Cordeiro, que parecia ter estado morto, de pé, no centro do trono, cercado pelos quatro seres viventes e pelos anciãos. Ele tinha sete chifres e sete olhos, que são os sete espíritos de Deus enviados a toda a terra.', 3, CURRENT_TIMESTAMP, false),
(66, 5, 7, 'Ele se aproximou e recebeu o livro da mão direita daquele que estava assentado no trono.', 3, CURRENT_TIMESTAMP, false),
(66, 5, 8, 'Ao recebê-lo, os quatro seres viventes e os vinte e quatro anciãos prostraram-se diante do Cordeiro. Cada um deles tinha uma harpa e taças de ouro cheias de incenso, que são as orações dos santos;', 3, CURRENT_TIMESTAMP, false),
(66, 5, 9, 'e eles cantavam um cântico novo: "Tu és digno de receber o livro e de abrir os seus selos, pois foste morto, e com teu sangue compraste para Deus homens de toda tribo, língua, povo e nação.', 3, CURRENT_TIMESTAMP, false),
(66, 5, 10, 'Tu os constituíste reino e sacerdotes para o nosso Deus, e eles reinarão sobre a terra".', 3, CURRENT_TIMESTAMP, false),
(66, 5, 11, 'Então olhei e ouvi a voz de muitos anjos, milhares de milhares e milhões de milhões. Eles rodeavam o trono, bem como os seres viventes e os anciãos,', 3, CURRENT_TIMESTAMP, false),
(66, 5, 12, 'e cantavam em alta voz: "Digno é o Cordeiro que foi morto de receber poder, riqueza, sabedoria, força, honra, glória e louvor! "', 3, CURRENT_TIMESTAMP, false),
(66, 5, 13, 'Depois ouvi todas as criaturas existentes no céu, na terra, debaixo da terra e no mar, e tudo o que neles há, que diziam: "Àquele que está assentado no trono e ao Cordeiro sejam o louvor, a honra, a glória e o poder, para todo o sempre! "', 3, CURRENT_TIMESTAMP, false),
(66, 5, 14, 'Os quatro seres viventes disseram: "Amém", e os anciãos prostraram-se e o adoraram.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 1, 'Observei quando o Cordeiro abriu o primeiro dos sete selos. Então ouvi um dos seres viventes dizer com voz de trovão: "Venha! "', 3, CURRENT_TIMESTAMP, false),
(66, 6, 2, 'Olhei, e diante de mim estava um cavalo branco! Seu cavaleiro empunhava um arco, e foi-lhe dada uma coroa; ele cavalgava como vencedor determinado a vencer.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 3, 'Quando o Cordeiro abriu o segundo selo, ouvi o segundo ser vivente dizer: "Venha! "', 3, CURRENT_TIMESTAMP, false),
(66, 6, 4, 'Então saiu outro cavalo; e este era vermelho. Seu cavaleiro recebeu poder para tirar a paz da terra e fazer que os homens se matassem uns aos outros. E lhe foi dada uma grande espada.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 5, 'Quando o Cordeiro abriu o terceiro selo, ouvi o terceiro ser vivente dizer: "Venha! " Olhei, e diante de mim estava um cavalo preto. Seu cavaleiro tinha na mão uma balança.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 6, 'Então ouvi o que parecia uma voz entre os quatro seres viventes, dizendo: "Um quilo de trigo por um denário, e três quilos de cevada por um denário, e não danifique o azeite e o vinho! "', 3, CURRENT_TIMESTAMP, false),
(66, 6, 7, 'Quando o Cordeiro abriu o quarto selo, ouvi a voz do quarto ser vivente dizer: "Venha! "', 3, CURRENT_TIMESTAMP, false),
(66, 6, 8, 'Olhei, e diante de mim estava um cavalo amarelo. Seu cavaleiro chamava-se Morte, e o Hades o seguia de perto. Foi-lhes dado poder sobre um quarto da terra para matar pela espada, pela fome, por pragas e por meio dos animais selvagens da terra.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 9, 'Quando ele abriu o quinto selo, vi debaixo do altar as almas daqueles que haviam sido mortos por causa da palavra de Deus e do testemunho que deram.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 10, 'Eles clamavam em alta voz: "Até quando, ó Soberano santo e verdadeiro, esperarás para julgar os habitantes da terra e vingar o nosso sangue? "', 3, CURRENT_TIMESTAMP, false),
(66, 6, 11, 'Então cada um deles recebeu uma veste branca, e foi-lhes dito que esperassem um pouco mais, até que se completasse o número dos seus conservos e irmãos, que deveriam ser mortos como eles.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 12, 'Observei quando ele abriu o sexto selo. Houve um grande terremoto. O sol ficou escuro como tecido de crina negra, toda a lua tornou-se vermelha como sangue,', 3, CURRENT_TIMESTAMP, false),
(66, 6, 13, 'e as estrelas do céu caíram sobre a terra como figos verdes caem da figueira quando sacudidos por um vento forte.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 14, 'O céu foi se recolhendo como se enrola um pergaminho, e todas as montanhas e ilhas foram removidas de seus lugares.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 15, 'Então os reis da terra, os príncipes, os generais, os ricos, os poderosos — todos os homens, quer escravos, quer livres, esconderam-se em cavernas e entre as rochas das montanhas.', 3, CURRENT_TIMESTAMP, false),
(66, 6, 16, 'Eles gritavam às montanhas e às rochas: "Caiam sobre nós e escondam-nos da face daquele que está assentado no trono e da ira do Cordeiro!', 3, CURRENT_TIMESTAMP, false),
(66, 6, 17, 'Pois chegou o grande dia da ira deles; e quem poderá suportar? "', 3, CURRENT_TIMESTAMP, false),
(66, 7, 1, 'Depois disso vi quatro anjos de pé nos quatro cantos da terra, retendo os quatro ventos, para impedir que qualquer vento soprasse na terra, no mar ou em qualquer árvore.', 3, CURRENT_TIMESTAMP, false),
(66, 7, 2, 'Então vi outro anjo subindo do Oriente, tendo o selo do Deus vivo. Ele bradou em alta voz aos quatro anjos a quem havia sido dado poder para danificar a terra e o mar:', 3, CURRENT_TIMESTAMP, false),
(66, 7, 3, '"Não danifiquem nem a terra, nem o mar nem as árvores, até que selemos as testas dos servos do nosso Deus".', 3, CURRENT_TIMESTAMP, false),
(66, 7, 4, 'Então ouvi o número dos que foram selados: cento e quarenta e quatro mil, de todas as tribos de Israel.', 3, CURRENT_TIMESTAMP, false),
(66, 7, 5, 'Da tribo de Judá foram selados doze mil, da tribo de Rúben, doze mil, da tribo de Gade, doze mil,', 3, CURRENT_TIMESTAMP, false),
(66, 7, 6, 'da tribo de Aser, doze mil, da tribo de Naftali, doze mil, da tribo de Manassés, doze mil,', 3, CURRENT_TIMESTAMP, false),
(66, 7, 7, 'da tribo de Simeão, doze mil, da tribo de Levi, doze mil, da tribo de Issacar, doze mil,', 3, CURRENT_TIMESTAMP, false),
(66, 7, 8, 'da tribo de Zebulom, doze mil, da tribo de José, doze mil, da tribo de Benjamim, doze mil.', 3, CURRENT_TIMESTAMP, false),
(66, 7, 9, 'Depois disso olhei, e diante de mim estava uma grande multidão que ninguém podia contar, de todas as nações, tribos, povos e línguas, de pé, diante do trono e do Cordeiro, com vestes brancas e segurando palmas.', 3, CURRENT_TIMESTAMP, false),
(66, 7, 10, 'E clamavam em alta voz: "A salvação pertence ao nosso Deus, que se assenta no trono, e ao Cordeiro".', 3, CURRENT_TIMESTAMP, false),
(66, 7, 11, 'Todos os anjos estavam de pé ao redor do trono, dos anciãos e dos quatro seres viventes. Eles se prostraram com o rosto em terra diante do trono e adoraram a Deus,', 3, CURRENT_TIMESTAMP, false),
(66, 7, 12, 'dizendo: "Amém! Louvor e glória, sabedoria, ação de graças, honra, poder e força sejam ao nosso Deus para todo o sempre. Amém! "', 3, CURRENT_TIMESTAMP, false),
(66, 7, 13, 'Então um dos anciãos me perguntou: "Quem são estes que estão vestidos de branco, e de onde vieram? "', 3, CURRENT_TIMESTAMP, false),
(66, 7, 14, 'Respondi: "Senhor, tu o sabes". E ele disse: "Estes são os que vieram da grande tribulação e lavaram as suas vestes e as branquearam no sangue do Cordeiro.', 3, CURRENT_TIMESTAMP, false),
(66, 7, 15, 'Por isso, eles estão diante do trono de Deus e o servem dia e noite em seu santuário; e aquele que está assentado no trono estenderá sobre eles o seu tabernáculo.', 3, CURRENT_TIMESTAMP, false),
(66, 7, 16, 'Nunca mais terão fome, nunca mais terão sede. Não cairá sobre eles sol, e nenhum calor abrasador,', 3, CURRENT_TIMESTAMP, false),
(66, 7, 17, 'pois o Cordeiro que está no centro do trono será o seu Pastor; ele os guiará às fontes de água viva. E Deus enxugará dos seus olhos toda lágrima".', 3, CURRENT_TIMESTAMP, false),
(66, 8, 1, 'Quando ele abriu o sétimo selo, houve silêncio no céu por volta de meia hora.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 2, 'Vi os sete anjos que se acham em pé diante de Deus; a eles foram dadas sete trombetas.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 3, 'Outro anjo, que trazia um incensário de ouro, aproximou-se e se colocou de pé junto ao altar. A ele foi dado muito incenso para oferecer com as orações de todos os santos sobre o altar de ouro diante do trono.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 4, 'E da mão do anjo subiu diante de Deus a fumaça do incenso juntamente com as orações dos santos.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 5, 'Então o anjo pegou o incensário, encheu-o com fogo do altar e lançou-o sobre a terra; e houve trovões, vozes, relâmpagos e um terremoto.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 6, 'Então os sete anjos, que tinham as sete trombetas, prepararam-se para tocá-las.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 7, 'O primeiro anjo tocou a sua trombeta, e granizo e fogo misturado com sangue foram lançados sobre a terra. Foi queimado um terço da terra, um terço das árvores e toda a planta verde.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 8, 'O segundo anjo tocou a sua trombeta, e algo como um grande monte em chamas foi lançado ao mar. Um terço do mar transformou-se em sangue,', 3, CURRENT_TIMESTAMP, false),
(66, 8, 9, 'morreu um terço das criaturas vivas do mar e foi destruído um terço das embarcações.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 10, 'O terceiro anjo tocou a sua trombeta, e caiu do céu uma grande estrela, queimando como tocha, sobre um terço dos rios e das fontes de águas;', 3, CURRENT_TIMESTAMP, false),
(66, 8, 11, 'o nome da estrela é Absinto. Tornou-se amargo um terço das águas, e muitos morreram pela ação das águas que se tornaram amargas.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 12, 'O quarto anjo tocou a sua trombeta, e foi ferido um terço do sol, um terço da lua e um terço das estrelas, de forma que um terço deles escureceu. Um terço do dia ficou sem luz, e também um terço da noite.', 3, CURRENT_TIMESTAMP, false),
(66, 8, 13, 'Enquanto eu olhava, ouvi uma águia que voava pelo meio do céu e dizia em alta voz: "Ai, ai, ai dos que habitam na terra, por causa do toque das trombetas que está prestes a ser dado pelos três outros anjos! "', 3, CURRENT_TIMESTAMP, false),
(66, 9, 1, 'O quinto anjo tocou a sua trombeta, e vi uma estrela que havia caído do céu sobre a terra. À estrela foi dada a chave do poço do Abismo.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 2, 'Quando ela abriu o Abismo, subiu dele fumaça como a de uma gigantesca fornalha. O sol e o céu escureceram com a fumaça que saía do abismo.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 3, 'Da fumaça saíram gafanhotos que vieram sobre a terra, e lhes foi dado poder como o dos escorpiões da terra.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 4, 'Eles receberam ordens para não causar dano nem à relva da terra nem a qualquer planta ou árvore, mas apenas àqueles que não tinham o selo de Deus na testa.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 5, 'Não lhes foi dado poder para matá-los, mas sim para causar-lhes tormento durante cinco meses. A agonia que eles sofreram era como a da picada do escorpião.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 6, 'Naqueles dias os homens procurarão a morte, mas não a encontrarão; desejarão morrer, mas a morte fugirá deles.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 7, 'Os gafanhotos pareciam cavalos preparados para a batalha. Tinham sobre a cabeça algo como coroas de ouro, e o rosto deles parecia rosto humano.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 8, 'Os cabelos deles eram como os de mulheres e os dentes como os de leão.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 9, 'Tinham couraças como couraças de ferro, e o som das suas asas era como o barulho de muitos cavalos e carruagens correndo para a batalha.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 10, 'Tinham caudas e ferrões como de escorpiões, e na cauda tinham poder para causar tormento aos homens durante cinco meses.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 11, 'Tinham um rei sobre eles, o anjo do Abismo, cujo nome, em hebraico, é Abadom, e, em grego, Apoliom.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 12, 'O primeiro ai passou; dois outros ais ainda estão por vir.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 13, 'O sexto anjo tocou a sua trombeta, e ouvi uma voz que vinha das pontas do altar de ouro que está diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 14, 'Ela disse ao sexto anjo que tinha a trombeta: "Solte os quatro anjos que estão amarrados junto ao grande rio Eufrates".', 3, CURRENT_TIMESTAMP, false),
(66, 9, 15, 'Os quatro anjos, que estavam preparados para aquela hora, dia, mês e ano, foram soltos para matar um terço da humanidade.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 16, 'O número dos cavaleiros que compunham os exércitos era de duzentos milhões; eu ouvi o seu número.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 17, 'Os cavalos e os cavaleiros que vi em minha visão tinham este aspecto: as suas couraças eram vermelhas como o fogo, azul-escuras, e amarelas como o enxofre. A cabeça dos cavalos parecia a cabeça de um leão, e da boca lançavam fogo, fumaça e enxofre.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 18, 'Um terço da humanidade foi morto pelas três pragas de fogo, fumaça e enxofre que saíam das suas bocas.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 19, 'O poder dos cavalos estava na boca e na cauda; pois as suas caudas eram como cobras; tinham cabeças com as quais feriam as pessoas.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 20, 'O restante da humanidade que não morreu por essas pragas, nem assim se arrependeu das obras das suas mãos; eles não pararam de adorar os demônios e os ídolos de ouro, prata, bronze, pedra e madeira, ídolos que não podem ver nem ouvir nem andar.', 3, CURRENT_TIMESTAMP, false),
(66, 9, 21, 'Também não se arrependeram dos seus assassinatos, das suas feitiçarias, da sua imoralidade sexual e dos seus roubos.', 3, CURRENT_TIMESTAMP, false),
(66, 10, 1, 'Então vi outro anjo poderoso, que descia do céu. Ele estava envolto numa nuvem, e havia um arco-íris acima de sua cabeça. Sua face era como o sol, e suas pernas eram como colunas de fogo.', 3, CURRENT_TIMESTAMP, false),
(66, 10, 2, 'E ele segurava um livrinho, que estava aberto em sua mão. Colocou o pé direito sobre o mar e o pé esquerdo sobre a terra,', 3, CURRENT_TIMESTAMP, false),
(66, 10, 3, 'e deu um alto brado, como o rugido de um leão. Quando ele bradou, os sete trovões falaram.', 3, CURRENT_TIMESTAMP, false),
(66, 10, 4, 'Logo que os sete trovões falaram, eu estava prestes a escrever, mas ouvi uma voz do céu, que disse: "Sele o que disseram os sete trovões, e não o escreva".', 3, CURRENT_TIMESTAMP, false),
(66, 10, 5, 'Então o anjo que eu tinha visto de pé sobre o mar e sobre a terra levantou a mão direita para o céu', 3, CURRENT_TIMESTAMP, false),
(66, 10, 6, 'e jurou por aquele que vive para todo o sempre, que criou os céus e tudo o que neles há, a terra e tudo o que nela há, e o mar e tudo o que nele há, dizendo: "Não haverá mais demora!', 3, CURRENT_TIMESTAMP, false),
(66, 10, 7, 'Mas, nos dias em que o sétimo anjo estiver para tocar sua trombeta, vai se cumprir o mistério de Deus, da forma como ele o anunciou aos seus servos, os profetas".', 3, CURRENT_TIMESTAMP, false),
(66, 10, 8, 'Depois falou comigo mais uma vez a voz que eu tinha ouvido falar do céu: "Vá, pegue o livro aberto que está na mão do anjo que se encontra de pé sobre o mar e sobre a terra".', 3, CURRENT_TIMESTAMP, false),
(66, 10, 9, 'Assim me aproximei do anjo e lhe pedi que me desse o livrinho. Ele me disse: "Pegue-o e coma-o! Ele será amargo em seu estômago, mas em sua boca será doce como mel".', 3, CURRENT_TIMESTAMP, false),
(66, 10, 10, 'Peguei o livrinho da mão do anjo e o comi. Ele me pareceu doce como mel em minha boca; mas, ao comê-lo, senti que o meu estômago ficou amargo.', 3, CURRENT_TIMESTAMP, false),
(66, 10, 11, 'Então me foi dito: "É preciso que você profetize de novo acerca de muitos povos, nações, línguas e reis".', 3, CURRENT_TIMESTAMP, false),
(66, 11, 1, 'Deram-me um caniço semelhante a uma vara de medir, e me foi dito: "Vá e meça o templo de Deus e o altar, e conte os adoradores que lá estiverem.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 2, 'Exclua, porém, o pátio exterior; não o meça, pois ele foi dado aos gentios. Eles pisarão a cidade santa durante quarenta e dois meses.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 3, 'Darei poder às minhas duas testemunhas, e elas profetizarão durante mil duzentos e sessenta dias, vestidas de pano de saco".', 3, CURRENT_TIMESTAMP, false),
(66, 11, 4, 'Estas são as duas oliveiras e os dois candelabros que permanecem diante do Senhor da terra.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 5, 'Se alguém quiser lhes causar dano, da boca deles sairá fogo que devorará os seus inimigos. É assim que deve morrer qualquer pessoa que quiser causar-lhes dano.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 6, 'Estes homens têm poder para fechar o céu, de modo que não chova durante o tempo em que estiverem profetizando, e têm poder para transformar a água em sangue e ferir a terra com toda sorte de pragas, quantas vezes desejarem.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 7, 'Quando eles tiverem terminado o seu testemunho, a besta que vem do Abismo os atacará. E irá vencê-los e matá-los.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 8, 'Os seus cadáveres ficarão expostos na rua principal da grande cidade, que figuradamente é chamada Sodoma e Egito, onde também foi crucificado o seu Senhor.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 9, 'Durante três dias e meio, homens de todos povos, tribos, línguas e nações contemplarão os seus cadáveres e não permitirão que sejam sepultados.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 10, 'Os habitantes da terra se alegrarão por causa deles e festejarão, enviando presentes uns aos outros, pois esses dois profetas haviam atormentado os que habitam na terra.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 11, 'Mas, depois dos três dias e meio, entrou neles um sopro de vida da parte de Deus, e eles ficaram de pé, e um grande terror tomou conta daqueles que os viram.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 12, 'Então eles ouviram uma forte voz do céu que lhes disse: "Subam para cá". E eles subiram para o céu numa nuvem, enquanto os seus inimigos olhavam.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 13, 'Naquela mesma hora houve um forte terremoto, e um décimo da cidade ruiu. Sete mil pessoas foram mortas no terremoto; os sobreviventes ficaram aterrorizados e deram glória ao Deus do céu.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 14, 'O segundo ai passou; o terceiro ai virá em breve.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 15, 'O sétimo anjo tocou a sua trombeta, e houve altas vozes no céu que diziam: "O reino do mundo se tornou de nosso Senhor e do seu Cristo, e ele reinará para todo o sempre".', 3, CURRENT_TIMESTAMP, false),
(66, 11, 16, 'Os vinte e quatro anciãos que estavam assentados em seus tronos diante de Deus prostraram-se sobre seus rostos e adoraram a Deus,', 3, CURRENT_TIMESTAMP, false),
(66, 11, 17, 'dizendo: "Graças te damos, Senhor Deus todo-poderoso, que és e que eras, porque assumiste o teu grande poder e começaste a reinar.', 3, CURRENT_TIMESTAMP, false),
(66, 11, 18, 'As nações se iraram; e chegou a tua ira. Chegou o tempo de julgares os mortos e de recompensares os teus servos, os profetas, os teus santos e os que temem o teu nome, tanto pequenos como grandes, e de destruir os que destroem a terra".', 3, CURRENT_TIMESTAMP, false),
(66, 11, 19, 'Então foi aberto o santuário de Deus no céu, e ali foi vista a arca da sua aliança. Houve relâmpagos, vozes, trovões, um terremoto e um grande temporal de granizo.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 1, 'Apareceu no céu um sinal extraordinário: uma mulher vestida do sol, com a lua debaixo dos seus pés e uma coroa de doze estrelas sobre a cabeça.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 2, 'Ela estava grávida e gritava de dor, pois estava para dar à luz.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 3, 'Então apareceu no céu outro sinal: um enorme dragão vermelho com sete cabeças e dez chifres, tendo sobre as cabeças sete coroas.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 4, 'Sua cauda arrastou consigo um terço das estrelas do céu, lançando-as na terra. O dragão colocou-se diante da mulher que estava para dar à luz, para devorar o seu filho no momento em que nascesse.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 5, 'Ela deu à luz um filho, um homem, que governará todas as nações com cetro de ferro. Seu filho foi arrebatado para junto de Deus e de seu trono.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 6, 'A mulher fugiu para o deserto, para um lugar que lhe havia sido preparado por Deus, para que ali a sustentassem durante mil duzentos e sessenta dias.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 7, 'Houve então uma guerra no céu. Miguel e seus anjos lutaram contra o dragão, e o dragão e os seus anjos revidaram.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 8, 'Mas estes não foram suficientemente fortes, e assim perderam o seu lugar no céu.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 9, 'O grande dragão foi lançado fora. Ele é a antiga serpente chamada diabo ou Satanás, que engana o mundo todo. Ele e os seus anjos foram lançado à terra.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 10, 'Então ouvi uma forte voz do céu que dizia: "Agora veio a salvação, o poder e o Reino do nosso Deus, e a autoridade do seu Cristo, pois foi lançado fora o acusador dos nossos irmãos, que os acusa diante do nosso Deus, dia e noite.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 11, 'Eles o venceram pelo sangue do Cordeiro e pela palavra do testemunho que deram; diante da morte, não amaram a própria vida.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 12, 'Portanto, celebrem, ó céus, e os que neles habitam! Mas, ai da terra e do mar, pois o diabo desceu até vocês! Ele está cheio de fúria, pois sabe que lhe resta pouco tempo".', 3, CURRENT_TIMESTAMP, false),
(66, 12, 13, 'Quando o dragão viu que havia sido lançado à terra, começou a perseguir a mulher que dera à luz o menino.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 14, 'Foram dadas à mulher as duas asas da grande águia, para que ela pudesse voar para o lugar que lhe havia sido preparado no deserto, onde seria sustentada durante um tempo, tempos e meio tempo, fora do alcance da serpente.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 15, 'Então a serpente fez jorrar da sua boca água como um rio, para alcançar a mulher e arrastá-la com a correnteza.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 16, 'A terra, porém, ajudou a mulher, abrindo a boca e engolindo o rio que o dragão fizera jorrar da sua boca.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 17, 'O dragão irou-se contra a mulher e saiu para guerrear contra o restante da sua descendência, os que obedecem aos mandamentos de Deus e se mantêm fiéis ao testemunho de Jesus.', 3, CURRENT_TIMESTAMP, false),
(66, 12, 18, 'Então o dragão se pôs em pé na areia do mar.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 1, 'Vi uma besta que saía do mar. Tinha dez chifres e sete cabeças, com dez coroas, uma sobre cada chifre, e em cada cabeça um nome de blasfêmia.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 2, 'A besta que vi era semelhante a um leopardo, mas tinha pés como os de urso e boca como a de leão. O dragão deu à besta o seu poder, o seu trono e grande autoridade.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 3, 'Uma das cabeças da besta parecia ter sofrido um ferimento mortal, mas o ferimento mortal foi curado. Todo o mundo ficou maravilhado e seguiu a besta.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 4, 'Adoraram o dragão, que tinha dado autoridade à besta, e também adoraram a besta, dizendo: "Quem é como a besta? Quem pode guerrear contra ela? "', 3, CURRENT_TIMESTAMP, false),
(66, 13, 5, 'À besta foi dada uma boca para falar palavras arrogantes e blasfemas, e lhe foi autoridade para agir durante quarenta e dois meses.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 6, 'Ela abriu a boca para blasfemar contra Deus e amaldiçoar o seu nome e o seu tabernáculo, os que habitam no céu.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 7, 'Foi-lhe dado poder para guerrear contra os santos e vencê-los. Foi-lhe dada autoridade sobre toda tribo, povo, língua e nação.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 8, 'Todos os habitantes da terra adorarão a besta, a saber, todos aqueles que não tiveram seus nomes escritos no livro da vida do Cordeiro que foi morto desde a criação do mundo.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 9, 'Aquele que tem ouvidos ouça:', 3, CURRENT_TIMESTAMP, false),
(66, 13, 10, 'Se alguém há de ir para o cativeiro, para o cativeiro irá. Se alguém há de ser morto à espada, à espada haverá de ser morto. Aqui estão a perseverança e a fidelidade dos santos.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 11, 'Então vi outra besta que saía da terra, com dois chifres como cordeiro, mas que falava como dragão.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 12, 'Exercia toda a autoridade da primeira besta, em nome dela, e fazia a terra e seus habitantes adorarem a primeira besta, cujo ferimento mortal havia sido curado.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 13, 'E realizava grandes sinais, chegando a fazer descer fogo do céu à terra, à vista dos homens.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 14, 'Por causa dos sinais que lhe foi permitido realizar em nome da primeira besta, ela enganou os habitantes da terra. Ordenou-lhes que fizessem uma imagem em honra da besta que fora ferida pela espada e contudo revivera.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 15, 'Foi-lhe dado poder para dar fôlego à imagem da primeira besta, de modo que ela podia falar e fazer que fossem mortos todos os que se recusassem a adorar a imagem.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 16, 'Também obrigou todos, pequenos e grandes, ricos e pobres, livres e escravos, a receberem certa marca na mão direita ou na testa,', 3, CURRENT_TIMESTAMP, false),
(66, 13, 17, 'para que ninguém pudesse comprar nem vender, a não ser quem tivesse a marca, que é o nome da besta ou o número do seu nome.', 3, CURRENT_TIMESTAMP, false),
(66, 13, 18, 'Aqui há sabedoria. Aquele que tem entendimento calcule o número da besta, pois é número de homem. Seu número é seiscentos e sessenta e seis.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 1, 'Então olhei, e diante de mim estava o Cordeiro, de pé sobre o monte Sião, e com ele cento e quarenta e quatro mil que traziam escritos na testa o nome dele e o nome de seu Pai.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 2, 'Ouvi um som do céu como o de muitas águas e de um forte trovão. Era como o de harpistas tocando suas harpas.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 3, 'Eles cantavam um cântico novo diante do trono, dos quatro seres viventes e dos anciãos. Ninguém podia aprender o cântico, a não ser os cento e quarenta e quatro mil que haviam sido comprados da terra.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 4, 'Estes são os que não se contaminaram com mulheres, pois se conservaram castos e seguem o Cordeiro por onde quer que ele vá. Foram comprados dentre os homens e ofertados como primícias a Deus e ao Cordeiro.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 5, 'Mentira nenhuma foi encontrada em suas bocas; são imaculados.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 6, 'Então vi outro anjo, que voava pelo céu e tinha na mão o evangelho eterno para proclamar aos que habitam na terra, a toda nação, tribo, língua e povo.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 7, 'Ele disse em alta voz: "Temam a Deus e glorifiquem-no, pois chegou a hora do seu juízo. Adorem aquele que fez os céus, a terra, o mar e as fontes das águas".', 3, CURRENT_TIMESTAMP, false),
(66, 14, 8, 'Um segundo anjo o seguiu, dizendo: "Caiu! Caiu a grande Babilônia que fez todas as nações beberem do vinho da fúria da sua prostituição! "', 3, CURRENT_TIMESTAMP, false),
(66, 14, 9, 'Um terceiro anjo os seguiu, dizendo em alta voz: "Se alguém adorar a besta e a sua imagem e receber a sua marca na testa ou na mão,', 3, CURRENT_TIMESTAMP, false),
(66, 14, 10, 'também beberá do vinho do furor de Deus que foi derramado sem mistura no cálice da sua ira. Será ainda atormentado com enxofre ardente na presença dos santos anjos e do Cordeiro,', 3, CURRENT_TIMESTAMP, false),
(66, 14, 11, 'e a fumaça do tormento de tais pessoas sobe para todo o sempre. Para todos os que adoram a besta e a sua imagem, e para quem recebe a marca do seu nome, não há descanso, dia e noite".', 3, CURRENT_TIMESTAMP, false),
(66, 14, 12, 'Aqui está a perseverança dos santos que obedecem aos mandamentos de Deus e permanecem fiéis a Jesus.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 13, 'Então ouvi uma voz do céu dizendo: "Escreva: Felizes os mortos que morrem no Senhor de agora em diante". Diz o Espírito: "Sim, eles descansarão das suas fadigas, pois as suas obras os seguirão".', 3, CURRENT_TIMESTAMP, false),
(66, 14, 14, 'Olhei, e diante de mim estava uma nuvem branca e, assentado sobre a nuvem, alguém "semelhante a um filho de homem". Ele estava com uma coroa de ouro na cabeça e uma foice afiada na mão.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 15, 'Então saiu do santuário um outro anjo, que bradou em alta voz àquele que estava assentado sobre a nuvem: "Tome a sua foice e faça a colheita, pois a safra da terra está madura; chegou a hora de colhê-la".', 3, CURRENT_TIMESTAMP, false),
(66, 14, 16, 'Assim, aquele que estava assentado sobre a nuvem passou sua foice pela terra, e a terra foi ceifada.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 17, 'Outro anjo saiu do santuário do céu, trazendo também uma foice afiada.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 18, 'E ainda outro anjo, que tem autoridade sobre o fogo, saiu do altar e bradou em alta voz àquele que tinha a foice afiada: "Tome sua foice afiada e ajunte os cachos de uva da videira da terra, porque as suas uvas estão maduras! "', 3, CURRENT_TIMESTAMP, false),
(66, 14, 19, 'O anjo passou a foice pela terra, ajuntou as uvas e as lançou no grande lagar da ira de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 14, 20, 'Elas foram pisadas no lagar, fora da cidade, e correu sangue do lagar, chegando ao nível dos freios dos cavalos, numa distância de cerca de trezentos quilômetros.', 3, CURRENT_TIMESTAMP, false),
(66, 15, 1, 'Vi no céu outro sinal, grande e maravilhoso: sete anjos com as sete últimas pragas, pois com elas se completa a ira de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 15, 2, 'Vi algo semelhante a um mar de vidro misturado com fogo, e, de pé, junto ao mar, os que tinham vencido a besta, a sua imagem e o número do seu nome. Eles seguravam harpas que lhes haviam sido dadas por Deus,', 3, CURRENT_TIMESTAMP, false),
(66, 15, 3, 'e cantavam o cântico de Moisés, servo de Deus, e o cântico do Cordeiro: "Grandes e maravilhosas são as tuas obras, Senhor Deus todo-poderoso. Justos e verdadeiros são os teus caminhos, ó Rei das nações.', 3, CURRENT_TIMESTAMP, false),
(66, 15, 4, 'Quem não te temerá, ó Senhor? Quem não glorificará o teu nome? Pois tu somente és santo. Todas as nações virão à tua presença e te adorarão, pois os teus atos de justiça se tornaram manifestos".', 3, CURRENT_TIMESTAMP, false),
(66, 15, 5, 'Depois disso olhei, e vi que se abriu no céu o santuário, o tabernáculo da aliança.', 3, CURRENT_TIMESTAMP, false),
(66, 15, 6, 'Saíram do santuário os sete anjos com as sete pragas. Eles estavam vestidos de linho puro e resplandecente, e tinham cinturões de ouro ao redor do peito.', 3, CURRENT_TIMESTAMP, false),
(66, 15, 7, 'E um dos quatro seres viventes deu aos sete anjos sete taças de ouro cheias da ira de Deus, que vive para todo o sempre.', 3, CURRENT_TIMESTAMP, false),
(66, 15, 8, 'O santuário ficou cheio da fumaça da glória de Deus e do seu poder, e ninguém podia entrar no santuário enquanto não se completassem as sete pragas dos sete anjos.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 1, 'Então ouvi uma forte voz que vinha do santuário dizendo aos sete anjos: "Vão derramar sobre a terra as sete taças da ira de Deus".', 3, CURRENT_TIMESTAMP, false),
(66, 16, 2, 'O primeiro anjo foi e derramou a sua taça pela terra, e abriram-se feridas malignas e dolorosas naqueles que tinham a marca da besta e adoravam a sua imagem.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 3, 'O segundo anjo derramou a sua taça no mar, e este se transformou em sangue como de um morto, e morreu toda criatura que vivia no mar.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 4, 'O terceiro anjo derramou a sua taça nos rios e nas fontes de águas, e eles se transformaram em sangue.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 5, 'Então ouvi o anjo que tem autoridade sobre as águas dizer: "Tu és justo, tu, o Santo, que és e que eras, porque julgaste estas coisas;', 3, CURRENT_TIMESTAMP, false),
(66, 16, 6, 'pois eles derramaram o sangue dos teus santos e dos teus profetas, e tu lhes deste sangue para beber, como eles merecem".', 3, CURRENT_TIMESTAMP, false),
(66, 16, 7, 'E ouvi o altar responder: "Sim, Senhor Deus todo-poderoso, verdadeiros e justos são os teus juízos".', 3, CURRENT_TIMESTAMP, false),
(66, 16, 8, 'O quarto anjo derramou a sua taça no sol, e foi dado poder ao sol para queimar os homens com fogo.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 9, 'Estes foram queimados pelo forte calor e amaldiçoaram o nome de Deus, que tem domínio sobre estas pragas; contudo se recusaram a se arrepender e a glorificá-lo.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 10, 'O quinto anjo derramou a sua taça sobre o trono da besta, cujo reino ficou em trevas. De tanta agonia, os homens mordiam a própria língua,', 3, CURRENT_TIMESTAMP, false),
(66, 16, 11, 'e blasfemavam contra o Deus do céu, por causa das suas dores e das suas feridas; contudo, recusaram-se a arrepender-se das obras que haviam praticado.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 12, 'O sexto anjo derramou a sua taça sobre o grande rio Eufrates, e secaram-se as suas águas para que fosse preparado o caminho para os reis que vêm do Oriente.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 13, 'Então vi saírem da boca do dragão, da boca da besta e da boca do falso profeta três espíritos imundos semelhantes a rãs.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 14, 'São espíritos de demônios que realizam sinais miraculosos; eles vão aos reis de todo o mundo, a fim de reuni-los para a batalha do grande dia do Deus todo-poderoso.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 15, '"Eis que venho como ladrão! Feliz aquele que permanece vigilante e conserva consigo as suas vestes, para que não ande nu e não seja vista a sua vergonha".', 3, CURRENT_TIMESTAMP, false),
(66, 16, 16, 'Então os três espíritos os reuniram no lugar que, em hebraico, é chamado Armagedom.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 17, 'O sétimo anjo derramou a sua taça no ar, e do santuário saiu uma forte voz que vinha do trono, dizendo: "Está feito! "', 3, CURRENT_TIMESTAMP, false),
(66, 16, 18, 'Houve, então, relâmpagos, vozes, trovões e um forte terremoto. Nunca havia ocorrido um terremoto tão forte como esse desde que o homem existe sobre a terra.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 19, 'A grande cidade foi fracionada em três partes, e as cidades das nações se desmoronaram. Deus lembrou-se da grande Babilônia e lhe deu o cálice do vinho do furor da sua ira.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 20, 'Todas as ilhas fugiram, e as montanhas desapareceram.', 3, CURRENT_TIMESTAMP, false),
(66, 16, 21, 'Caíram sobre os homens, vindas do céu, enormes pedras de granizo, de cerca de trinta e cinco quilos cada; eles blasfemaram contra Deus por causa do granizo, pois a praga fora terrível.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 1, 'Um dos sete anjos que tinham as sete taças aproximou-se e me disse: "Venha, eu lhe mostrarei o julgamento da grande prostituta que está sentada sobre muitas águas,', 3, CURRENT_TIMESTAMP, false),
(66, 17, 2, 'com quem os reis da terra se prostituíram; os habitantes da terra se embriagaram com o vinho da sua prostituição".', 3, CURRENT_TIMESTAMP, false),
(66, 17, 3, 'Então o anjo me levou no Espírito para um deserto. Ali vi uma mulher montada numa besta vermelha, que estava coberta de nomes blasfemos e que tinha sete cabeças e dez chifres.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 4, 'A mulher estava vestida de azul e vermelho, e adornada de ouro, pedras preciosas e pérolas. Segurava um cálice de ouro, cheio de coisas repugnantes e da impureza da sua prostituição.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 5, 'Em sua testa havia esta inscrição: MISTÉRIO: BABILÔNIA, A GRANDE; A MÃE DAS PROSTITUTAS E DAS PRÁTICAS REPUGNANTES DA TERRA.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 6, 'Vi que a mulher estava embriagada com o sangue dos santos, o sangue das testemunhas de Jesus. Quando a vi, fiquei muito admirado.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 7, 'Então o anjo me disse: "Por que você está admirado? Eu lhe explicarei o mistério dessa mulher e da besta sobre a qual ela está montada, que tem sete cabeças e dez chifres.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 8, 'A besta que você viu, era e já não é. Ela está para subir do abismo e caminha para a perdição. Os habitantes da terra, cujos nomes não foram escritos no livro da vida desde a criação do mundo, ficarão admirados quando virem a besta, porque ela era, agora não é, e entretanto virá.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 9, '"Aqui se requer mente sábia. As sete cabeças são sete colinas sobre as quais está sentada a mulher.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 10, 'São também sete reis. Cinco já caíram, um ainda existe, e o outro ainda não surgiu; mas, quando surgir, deverá permanecer durante pouco tempo.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 11, 'A besta que era, e agora não é, é o oitavo rei. É um dos sete, e caminha para a perdição.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 12, '"Os dez chifres que você viu são dez reis que ainda não receberam reino, mas que por uma hora receberão autoridade como reis, juntamente com a besta.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 13, 'Eles têm um único propósito, e darão seu poder e sua autoridade à besta.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 14, 'Guerrearão contra o Cordeiro, mas o Cordeiro os vencerá, pois é o Senhor dos senhores e o Rei dos reis; e vencerão com ele os seus chamados, escolhidos e fiéis".', 3, CURRENT_TIMESTAMP, false),
(66, 17, 15, 'Então o anjo me disse: "As águas que você viu, onde está sentada a prostituta, são povos, multidões, nações e línguas.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 16, 'A besta e os dez chifres que você viu odiarão a prostituta. Eles a levarão à ruína e a deixarão nua, comerão a sua carne e a destruirão com fogo,', 3, CURRENT_TIMESTAMP, false),
(66, 17, 17, 'pois Deus colocou no coração deles o desejo de realizar o propósito que ele tem, levando-os a concordarem em dar à besta o poder que eles têm para reinar até que se cumpram as palavras de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 17, 18, 'A mulher que você viu é a grande cidade que reina sobre os reis da terra".', 3, CURRENT_TIMESTAMP, false),
(66, 18, 1, 'Depois disso vi outro anjo que descia do céu. Tinha grande autoridade, e a terra foi iluminada por seu esplendor.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 2, 'E ele bradou com voz poderosa: "Caiu! Caiu a grande Babilônia! Ela se tornou habitação de demônios e antro de todo espírito imundo antro de toda ave impura e detestável,', 3, CURRENT_TIMESTAMP, false),
(66, 18, 3, 'pois todas as nações beberam do vinho da fúria da sua prostituição. Os reis da terra se prostituíram com ela; à custa do seu luxo excessivo os negociantes da terra se enriqueceram".', 3, CURRENT_TIMESTAMP, false),
(66, 18, 4, 'Então ouvi outra voz do céu que dizia: "Saiam dela, vocês, povo meu, para que vocês não participem dos seus pecados, para que as pragas que vão cair sobre ela não os atinjam!', 3, CURRENT_TIMESTAMP, false),
(66, 18, 5, 'Pois os pecados da Babilônia acumularam-se até o céu, e Deus se lembrou dos seus crimes.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 6, 'Retribuam-lhe na mesma moeda; paguem-lhe em dobro pelo que fez; misturem para ela uma porção dupla no seu próprio cálice.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 7, 'Façam-lhe sofrer tanto tormento e tanta aflição como a glória e o luxo a que ela se entregou. Em seu coração ela se vangloriava: ‘Estou sentada como rainha; não sou viúva e jamais terei tristeza’.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 8, 'Por isso num só dia as suas pragas a alcançarão: morte, tristeza e fome, e o fogo a consumirá, pois poderoso é o Senhor Deus que a julga.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 9, '"Quando os reis da terra, que se prostituíram com ela e participaram do seu luxo, virem a fumaça do seu incêndio, chorarão e se lamentarão por ela.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 10, 'Amedrontados por causa do tormento dela, ficarão de longe e gritarão: ‘Ai! A grande cidade! Babilônia, cidade poderosa! Em apenas uma hora chegou a sua condenação! ’', 3, CURRENT_TIMESTAMP, false),
(66, 18, 11, '"Os negociantes da terra chorarão e se lamentarão por causa dela, porque ninguém mais compra a sua mercadoria:', 3, CURRENT_TIMESTAMP, false),
(66, 18, 12, 'artigos como ouro, prata, pedras preciosas e pérolas; linho fino, púrpura, seda e tecido vermelho; todo tipo de madeira de cedro e peças de marfim, madeira preciosa, bronze, ferro e mármore;', 3, CURRENT_TIMESTAMP, false),
(66, 18, 13, 'canela e outras especiarias, incenso, mirra e perfumes, vinho e azeite de oliva; farinha fina e trigo, bois e ovelhas, cavalos e carruagens, e corpos e almas de seres humanos.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 14, '"Eles dirão: ‘Foram-se as frutas que tanto lhe apeteciam! Todas as suas riquezas e todo o seu esplendor se desvaneceram; nunca mais serão recuperados’.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 15, 'Os negociantes dessas coisas, que enriqueceram à custa dela, ficarão de longe, amedrontados com o tormento dela, e chorarão e se lamentarão,', 3, CURRENT_TIMESTAMP, false),
(66, 18, 16, 'gritando: ‘Ai! A grande cidade, vestida de linho fino, de roupas de púrpura e vestes vermelhas, adornada de ouro, pedras preciosas e pérolas!', 3, CURRENT_TIMESTAMP, false),
(66, 18, 17, 'Em apenas uma hora, tamanha riqueza foi arruinada! ’ "Todos os pilotos, todos os passageiros e marinheiros dos navios e todos os que ganham a vida no mar ficarão de longe.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 18, 'Ao verem a fumaça do incêndio dela, exclamarão: ‘Que outra cidade jamais se igualou a esta grande cidade? ’', 3, CURRENT_TIMESTAMP, false),
(66, 18, 19, 'Lançarão pó sobre a cabeça, e lamentando-se e chorando, gritarão: ‘Ai! A grande cidade! Graças à sua riqueza, nela prosperaram todos os que tinham navios no mar! Em apenas uma hora ela ficou em ruínas!', 3, CURRENT_TIMESTAMP, false),
(66, 18, 20, 'Celebre o que se deu com ela, ó céus! Celebrem, ó santos, apóstolos e profetas! Deus a julgou, retribuindo-lhe o que ela fez a vocês ’ ".', 3, CURRENT_TIMESTAMP, false),
(66, 18, 21, 'Então um anjo poderoso levantou uma pedra do tamanho de uma grande pedra de moinho, lançou-a ao mar e disse: "Com igual violência será lançada por terra a grande cidade da Babilônia, para nunca mais ser encontrada.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 22, 'Nunca mais se ouvirá em seu meio o som de harpistas, dos músicos, dos flautistas e dos tocadores de trombeta. Nunca mais se achará dentro de seus muros artífice algum, de qualquer profissão. Nunca mais se ouvirá em seu meio o ruído das pedras de moinho.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 23, 'Nunca mais brilhará dentro de seus muros a luz da candeia. Nunca mais se ouvirá ali a voz do noivo e da noiva. Seus mercadores eram os grandes do mundo. Todas as nações foram seduzidas por suas feitiçarias.', 3, CURRENT_TIMESTAMP, false),
(66, 18, 24, 'Nela foi encontrado sangue de profetas e de santos, e de todos os que foram assassinados na terra".', 3, CURRENT_TIMESTAMP, false),
(66, 19, 1, 'Depois disso ouvi no céu algo semelhante à voz de uma grande multidão, que exclamava: "Aleluia! A salvação, a glória e o poder pertencem ao nosso Deus,', 3, CURRENT_TIMESTAMP, false),
(66, 19, 2, 'pois verdadeiros e justos são os seus juízos. Ele condenou a grande prostituta que corrompia a terra com a sua prostituição. Ele cobrou dela o sangue dos seus servos".', 3, CURRENT_TIMESTAMP, false),
(66, 19, 3, 'E mais uma vez a multidão exclamou: "Aleluia! A fumaça que dela vem, sobe para todo o sempre".', 3, CURRENT_TIMESTAMP, false),
(66, 19, 4, 'Os vinte e quatro anciãos e os quatro seres viventes prostraram-se e adoraram a Deus, que estava assentado no trono, e exclamaram: "Amém, Aleluia! "', 3, CURRENT_TIMESTAMP, false),
(66, 19, 5, 'Então veio do trono uma voz, conclamando: "Louvem o nosso Deus, todos vocês, seus servos, vocês que o temem, tanto pequenos como grandes! "', 3, CURRENT_TIMESTAMP, false),
(66, 19, 6, 'Então ouvi algo semelhante ao som de uma grande multidão, como o estrondo de muitas águas e fortes trovões, que bradava: "Aleluia! pois reina o Senhor, o nosso Deus, o Todo-poderoso.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 7, 'Regozijemo-nos! Vamos nos alegrar e dar-lhe glória! Pois chegou a hora do casamento do Cordeiro, e a sua noiva já se aprontou.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 8, 'Foi-lhe dado para vestir-se linho fino, brilhante e puro". O linho fino são os atos justos dos santos.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 9, 'E o anjo me disse: "Escreva: Felizes os convidados para o banquete do casamento do Cordeiro! " E acrescentou: "Estas são as palavras verdadeiras de Deus".', 3, CURRENT_TIMESTAMP, false),
(66, 19, 10, 'Então caí aos seus pés para adorá-lo, mas ele me disse: "Não faça isso! Sou servo como você e como os seus irmãos que se mantêm fiéis ao testemunho de Jesus. Adore a Deus! O testemunho de Jesus é o espírito de profecia".', 3, CURRENT_TIMESTAMP, false),
(66, 19, 11, 'Vi o céu aberto e diante de mim um cavalo branco, cujo cavaleiro se chama Fiel e Verdadeiro. Ele julga e guerreia com justiça.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 12, 'Seus olhos são como chamas de fogo, e em sua cabeça há muitas coroas e um nome que só ele conhece, e ninguém mais.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 13, 'Está vestido com um manto tingido de sangue, e o seu nome é Palavra de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 14, 'Os exércitos do céu o seguiam, vestidos de linho fino, branco e puro, e montados em cavalos brancos.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 15, 'De sua boca sai uma espada afiada, com a qual ferirá as nações. "Ele as governará com cetro de ferro". Ele pisa o lagar do vinho do furor da ira do Deus todo-poderoso.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 16, 'Em seu manto e em sua coxa está escrito este nome: REI DOS REIS E SENHOR DOS SENHORES.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 17, 'Vi um anjo que estava de pé no sol e que clamava em alta voz a todas as aves que voavam pelo meio do céu: "Venham, reúnam-se para o grande banquete de Deus,', 3, CURRENT_TIMESTAMP, false),
(66, 19, 18, 'para comerem carne de reis, generais e poderosos, carne de cavalos e seus cavaleiros, carne de todos: livres e escravos, pequenos e grandes".', 3, CURRENT_TIMESTAMP, false),
(66, 19, 19, 'Então vi a besta, os reis da terra e os seus exércitos reunidos para guerrearem contra aquele que está montado no cavalo e contra o seu exército.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 20, 'Mas a besta foi presa, e com ela o falso profeta que havia realizado os sinais miraculosos em nome dela, com os quais ele havia enganado os que receberam a marca da besta e adoraram a imagem dela. Os dois foram lançados vivos no lago de fogo que arde com enxofre.', 3, CURRENT_TIMESTAMP, false),
(66, 19, 21, 'Os demais foram mortos com a espada que saía da boca daquele que está montado no cavalo. E todas as aves se fartaram com a carne deles.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 1, 'Vi descer do céu um anjo que trazia na mão a chave do abismo e uma grande corrente.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 2, 'Ele prendeu o dragão, a antiga serpente, que é o diabo, Satanás, e o acorrentou por mil anos;', 3, CURRENT_TIMESTAMP, false),
(66, 20, 3, 'lançou-o no abismo, fechou-o e pôs um selo sobre ele, para assim impedi-lo de enganar as nações até que terminassem os mil anos. Depois disso, é necessário que ele seja solto por um pouco de tempo.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 4, 'Vi tronos em que se assentaram aqueles a quem havia sido dada autoridade para julgar. Vi as almas dos que foram decapitados por causa do testemunho de Jesus e da palavra de Deus. Eles não tinham adorado a besta nem a sua imagem, e não tinham recebido a sua marca na testa nem nas mãos. Eles ressuscitaram e reinaram com Cristo durante mil anos.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 5, '( O restante dos mortos não voltou a viver até se completarem os mil anos. ) Esta é a primeira ressurreição.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 6, 'Felizes e santos os que participam da primeira ressurreição! A segunda morte não tem poder sobre eles; serão sacerdotes de Deus e de Cristo, e reinarão com ele durante mil anos.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 7, 'Quando terminarem os mil anos, Satanás será solto da sua prisão', 3, CURRENT_TIMESTAMP, false),
(66, 20, 8, 'e sairá para enganar as nações que estão nos quatro cantos da terra, Gogue e Magogue, a fim de reuni-las para a batalha. Seu número é como a areia do mar.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 9, 'As nações marcharam por toda a superfície da terra e cercaram o acampamento dos santos, a cidade amada; mas um fogo desceu do céu e as devorou.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 10, 'O diabo, que as enganava, foi lançado no lago de fogo que arde com enxofre, onde já haviam sido lançados a besta e o falso profeta. Eles serão atormentados dia e noite, para todo o sempre.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 11, 'Depois vi um grande trono branco e aquele que nele estava assentado. A terra e o céu fugiram da sua presença, e não se encontrou lugar para eles.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 12, 'Vi também os mortos, grandes e pequenos, de pé diante do trono, e livros foram abertos. Outro livro foi aberto, o livro da vida. Os mortos foram julgados de acordo com o que tinham feito, segundo o que estava registrado nos livros.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 13, 'O mar entregou os mortos que nele havia, e a morte e o Hades entregaram os mortos que neles havia; e cada um foi julgado de acordo com o que tinha feito.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 14, 'Então a morte e o Hades foram lançados no lago de fogo. O lago de fogo é a segunda morte.', 3, CURRENT_TIMESTAMP, false),
(66, 20, 15, 'Se o nome de alguém não foi encontrado no livro da vida, este foi lançado no lago de fogo.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 1, 'Então vi um novo céu e uma nova terra, pois o primeiro céu e a primeira terra tinham passado; e o mar já não existia.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 2, 'Vi a cidade santa, a nova Jerusalém, que descia do céu, da parte de Deus, preparada como uma noiva adornada para o seu marido.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 3, 'Ouvi uma forte voz que vinha do trono e dizia: "Agora o tabernáculo de Deus está com os homens, com os quais ele viverá. Eles serão os seus povos; o próprio Deus estará com eles e será o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 4, 'Ele enxugará dos seus olhos toda lágrima. Não haverá mais morte, nem tristeza, nem choro, nem dor, pois a antiga ordem já passou".', 3, CURRENT_TIMESTAMP, false),
(66, 21, 5, 'Aquele que estava assentado no trono disse: "Estou fazendo novas todas as coisas! " E acrescentou: "Escreva isto, pois estas palavras são verdadeiras e dignas de confiança".', 3, CURRENT_TIMESTAMP, false),
(66, 21, 6, 'Disse-me ainda: "Está feito. Eu sou o Alfa e o Ômega, o Princípio e o Fim. A quem tiver sede, darei de beber gratuitamente da fonte da água da vida.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 7, 'O vencedor herdará tudo isto, e eu serei seu Deus e ele será meu filho.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 8, 'Mas os covardes, os incrédulos, os depravados, os assassinos, os que cometem imoralidade sexual, os que praticam feitiçaria, os idólatras e todos os mentirosos — o lugar deles será no lago de fogo que arde com enxofre. Esta é a segunda morte".', 3, CURRENT_TIMESTAMP, false),
(66, 21, 9, 'Um dos sete anjos que tinham as sete taças cheias das últimas sete pragas aproximou-se e me disse: "Venha, eu lhe mostrarei a noiva, a esposa do Cordeiro".', 3, CURRENT_TIMESTAMP, false),
(66, 21, 10, 'Ele me levou no Espírito a um grande e alto monte e mostrou-me a Cidade Santa, Jerusalém, que descia do céu, da parte de Deus.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 11, 'Ela resplandecia com a glória de Deus, e o seu brilho era como o de uma jóia muito preciosa, como jaspe, clara como cristal.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 12, 'Tinha uma grande e alta muralha com doze portas e doze anjos junto às portas. Nas portas estavam escritos os nomes das doze tribos de Israel.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 13, 'Havia três portas ao oriente, três ao norte, três ao sul e três ao ocidente.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 14, 'A muralha da cidade tinha doze fundamentos, e neles estavam os nomes dos doze apóstolos do Cordeiro.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 15, 'O anjo que falava comigo tinha como medida uma vara feita de ouro, para medir a cidade, suas portas e seus muros.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 16, 'A cidade era quadrangular, de comprimento e largura iguais. Ele mediu a cidade com a vara; tinha dois mil e duzentos quilômetros de comprimento; a largura e a altura eram iguais ao comprimento.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 17, 'Ele mediu a muralha, e deu sessenta e cinco metros de espessura, segundo a medida humana que o anjo estava usando.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 18, 'A muralha era feita de jaspe e a cidade de ouro puro, semelhante ao vidro puro.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 19, 'Os fundamentos das muros da cidade eram ornamentados com toda sorte de pedras preciosas. O primeiro fundamento era ornamentado com jaspe; o segundo com safira; o terceiro com calcedônia; o quarto com esmeralda;', 3, CURRENT_TIMESTAMP, false),
(66, 21, 20, 'o quinto com sardônio; o sexto com sárdio; o sétimo com crisólito; o oitavo com berilo; o nono com topázio; o décimo com crisópraso; o décimo primeiro com jacinto; e o décimo segundo com ametista.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 21, 'As doze portas eram doze pérolas, cada porta feita de uma única pérola. A rua principal da cidade era de ouro puro, como vidro transparente.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 22, 'Não vi templo algum na cidade, pois o Senhor Deus todo-poderoso e o Cordeiro são o seu templo.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 23, 'A cidade não precisa de sol nem de lua para brilharem sobre ela, pois a glória de Deus a ilumina, e o Cordeiro é a sua candeia.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 24, 'As nações andarão em sua luz, e os reis da terra lhe trarão a sua glória.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 25, 'Suas portas jamais se fecharão de dia, pois ali não haverá noite.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 26, 'A glória e a honra das nações lhe serão trazidas.', 3, CURRENT_TIMESTAMP, false),
(66, 21, 27, 'Nela jamais entrará algo impuro, nem ninguém que pratique o que é vergonhoso ou enganoso, mas unicamente aqueles cujos nomes estão escritos no livro da vida do Cordeiro.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 1, 'Então o anjo me mostrou o rio da água da vida que, claro como cristal, fluía do trono de Deus e do Cordeiro,', 3, CURRENT_TIMESTAMP, false),
(66, 22, 2, 'no meio da rua principal da cidade. De cada lado do rio estava a árvore da vida, que dá doze colheitas, dando fruto todos os meses. As folhas da árvore servem para a cura das nações.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 3, 'Já não haverá maldição nenhuma. O trono de Deus e do Cordeiro estará na cidade, e os seus servos o servirão.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 4, 'Eles verão a sua face, e o seu nome estará em suas testas.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 5, 'Não haverá mais noite. Eles não precisarão de luz de candeia nem da luz do sol, pois o Senhor Deus os iluminará; e eles reinarão para todo o sempre.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 6, 'O anjo me disse: "Estas palavras são dignas de confiança e verdadeiras. O Senhor, o Deus dos espíritos dos profetas, enviou o seu anjo para mostrar aos seus servos as coisas que em breve hão de acontecer".', 3, CURRENT_TIMESTAMP, false),
(66, 22, 7, '"Eis que venho em breve! Feliz é aquele que guarda as palavras da profecia deste livro".', 3, CURRENT_TIMESTAMP, false),
(66, 22, 8, 'Eu, João, sou aquele que ouviu e viu estas coisas. Tendo-as ouvido e visto, caí aos pés do anjo que me mostrou tudo aquilo para mim, para adorá-lo.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 9, 'Mas ele me disse: "Não faça isso! Sou servo como você e seus irmãos, os profetas, e como os que guardam as palavras deste livro. Adore a Deus! "', 3, CURRENT_TIMESTAMP, false),
(66, 22, 10, 'Então me disse: "Não sele as palavras da profecia deste livro, pois o tempo está próximo.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 11, 'Continue o injusto a praticar injustiça; continue o imundo na imundícia; continue o justo a praticar justiça; e continue o santo a santificar-se".', 3, CURRENT_TIMESTAMP, false),
(66, 22, 12, '"Eis que venho em breve! A minha recompensa está comigo, e eu retribuirei a cada um de acordo com o que fez.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 13, 'Eu sou o Alfa e o Ômega, o Primeiro e o Último, o Princípio e o Fim.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 14, '"Felizes os que lavam as suas vestes, para que tenham direito à árvore da vida e possam entrar na cidade pelas portas.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 15, 'Fora ficam os cães, os que praticam feitiçaria, os que cometem imoralidades sexuais, os assassinos, os idólatras e todos os que amam e praticam a mentira.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 16, '"Eu, Jesus, enviei o meu anjo para dar a vocês este testemunho concernente às igrejas. Eu sou a Raiz e o Descendente de Davi, e a resplandecente Estrela da Manhã".', 3, CURRENT_TIMESTAMP, false),
(66, 22, 17, 'O Espírito e a noiva dizem: "Vem! " E todo aquele que ouvir diga: "Vem! " Quem tiver sede, venha; e quem quiser, beba de graça da água da vida.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 18, 'Declaro a todos os que ouvem as palavras da profecia deste livro: se alguém lhe acrescentar algo, Deus lhe acrescentará as pragas descritas neste livro.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 19, 'Se alguém tirar alguma palavra deste livro de profecia, Deus tirará dele a sua parte na árvore da vida e na cidade santa, que são descritas neste livro.', 3, CURRENT_TIMESTAMP, false),
(66, 22, 20, 'Aquele que dá testemunho destas coisas diz: "Sim, venho em breve! " Amém. Vem, Senhor Jesus!', 3, CURRENT_TIMESTAMP, false),
(66, 22, 21, 'A graça do Senhor Jesus seja com todos. Amém.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 1, 'Em meu livro anterior, Teófilo, escrevi a respeito de tudo o que Jesus começou a fazer e a ensinar,', 3, CURRENT_TIMESTAMP, false),
(44, 1, 2, 'até o dia em que foi elevado ao céu, depois de ter dado instruções por meio do Espírito Santo aos apóstolos que havia escolhido.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 3, 'Depois do seu sofrimento, Jesus apresentou-se a eles e deu-lhes muitas provas indiscutíveis de que estava vivo. Apareceu-lhes por um período de quarenta dias falando-lhes acerca do Reino de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 4, 'Certa ocasião, enquanto comia com eles, deu-lhes esta ordem: "Não saiam de Jerusalém, mas esperem pela promessa de meu Pai, da qual lhes falei.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 5, 'Pois João batizou com água, mas dentro de poucos dias vocês serão batizados com o Espírito Santo".', 3, CURRENT_TIMESTAMP, false),
(44, 1, 6, 'Então os que estavam reunidos lhe perguntaram: "Senhor, é neste tempo que vais restaurar o reino a Israel? "', 3, CURRENT_TIMESTAMP, false),
(44, 1, 7, 'Ele lhes respondeu: "Não lhes compete saber os tempos ou as datas que o Pai estabeleceu pela sua própria autoridade.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 8, 'Mas receberão poder quando o Espírito Santo descer sobre vocês, e serão minhas testemunhas em Jerusalém, em toda a Judéia e Samaria, e até os confins da terra".', 3, CURRENT_TIMESTAMP, false),
(44, 1, 9, 'Tendo dito isso, foi elevado às alturas enquanto eles olhavam, e uma nuvem o encobriu da vista deles.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 10, 'E eles ficaram com os olhos fixos no céu enquanto ele subia. De repente surgiram diante deles dois homens vestidos de branco,', 3, CURRENT_TIMESTAMP, false),
(44, 1, 11, 'que lhes disseram: "Galileus, por que vocês estão olhando para o céu? Este mesmo Jesus, que dentre vocês foi elevado ao céu, voltará da mesma forma como o viram subir".', 3, CURRENT_TIMESTAMP, false),
(44, 1, 12, 'Então eles voltaram para Jerusalém, vindo do monte chamado das Oliveiras, que fica perto da cidade, cerca de um quilômetro.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 13, 'Quando chegaram, subiram ao aposento onde estavam hospedados. Achavam-se presentes Pedro, João, Tiago e André; Filipe, Tomé, Bartolomeu e Mateus; Tiago, filho de Alfeu, Simão, o zelote, e Judas, filho de Tiago.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 14, 'Todos eles se reuniam sempre em oração, com as mulheres, inclusive Maria, a mãe de Jesus, e com os irmãos de Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 15, 'Naqueles dias Pedro levantou-se entre os irmãos, um grupo de cerca de cento e vinte pessoas,', 3, CURRENT_TIMESTAMP, false),
(44, 1, 16, 'e disse: "Irmãos, era necessário que se cumprisse a Escritura que o Espírito Santo predisse por boca de Davi, a respeito de Judas, que serviu de guia aos que prenderam Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 17, 'Ele foi contado como um dos nossos e teve participação neste ministério".', 3, CURRENT_TIMESTAMP, false),
(44, 1, 18, '( Com a recompensa que recebeu pelo seu pecado, Judas comprou um campo. Ali caiu de cabeça, seu corpo partiu-se ao meio, e as suas vísceras se derramaram.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 19, 'Todos em Jerusalém ficaram sabendo disso, de modo que, na língua deles, esse campo passou a chamar-se Aceldama, isto é, campo de Sangue. )', 3, CURRENT_TIMESTAMP, false),
(44, 1, 20, '"Porque", prosseguiu Pedro, "está escrito no Livro de Salmos: ‘Fique deserto o seu lugar, e não haja ninguém que nele habite’; e ainda: ‘Que outro ocupe o seu lugar’.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 21, 'Portanto, é necessário que escolhamos um dos homens que estiveram conosco durante todo o tempo em que o Senhor Jesus viveu entre nós,', 3, CURRENT_TIMESTAMP, false),
(44, 1, 22, 'desde o batismo de João até o dia em que Jesus foi elevado dentre nós às alturas. É preciso que um deles seja conosco testemunha de sua ressurreição".', 3, CURRENT_TIMESTAMP, false),
(44, 1, 23, 'Então indicaram dois nomes: José, chamado Barsabás, também conhecido como Justo, e Matias.', 3, CURRENT_TIMESTAMP, false),
(44, 1, 24, 'Depois oraram: "Senhor, tu conheces o coração de todos. Mostra-nos qual destes dois tens escolhido', 3, CURRENT_TIMESTAMP, false),
(44, 1, 25, 'para assumir este ministério apostólico que Judas abandonou, indo para o lugar que lhe era devido".', 3, CURRENT_TIMESTAMP, false),
(44, 1, 26, 'Então tiraram sortes, e a sorte caiu sobre Matias; assim, ele foi acrescentado aos onze apóstolos.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 1, 'Chegando o dia de Pentecoste, estavam todos reunidos num só lugar.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 2, 'De repente veio do céu um som, como de um vento muito forte, e encheu toda a casa na qual estavam assentados.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 3, 'E viram o que parecia línguas de fogo, que se separaram e pousaram sobre cada um deles.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 4, 'Todos ficaram cheios do Espírito Santo e começaram a falar noutras línguas, conforme o Espírito os capacitava.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 5, 'Havia em Jerusalém judeus, tementes a Deus, vindos de todas as nações do mundo.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 6, 'Ouvindo-se este som, ajuntou-se uma multidão que ficou perplexa, pois cada um os ouvia falar em sua própria língua.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 7, 'Atônitos e maravilhados, eles perguntavam: "Acaso não são galileus todos estes homens que estão falando?', 3, CURRENT_TIMESTAMP, false),
(44, 2, 8, 'Então, como os ouvimos, cada um de nós, em nossa própria língua materna?', 3, CURRENT_TIMESTAMP, false),
(44, 2, 9, 'Partos, medos e elamitas; habitantes da Mesopotâmia, Judéia e Capadócia, Ponto e da província da Ásia,', 3, CURRENT_TIMESTAMP, false),
(44, 2, 10, 'Frígia e Panfília, Egito e das partes da Líbia próximas a Cirene; visitantes vindos de Roma,', 3, CURRENT_TIMESTAMP, false),
(44, 2, 11, 'tanto judeus como convertidos ao judaísmo; cretenses e árabes. Nós os ouvimos declarar as maravilhas de Deus em nossa própria língua! "', 3, CURRENT_TIMESTAMP, false),
(44, 2, 12, 'Atônitos e perplexos, todos perguntavam uns aos outros: "Que significa isto? "', 3, CURRENT_TIMESTAMP, false),
(44, 2, 13, 'Alguns, todavia, zombavam deles e diziam: "Eles beberam vinho demais".', 3, CURRENT_TIMESTAMP, false),
(44, 2, 14, 'Então Pedro levantou-se com os Onze e, em alta voz, dirigiu-se à multidão: "Homens da Judéia e todos os que vivem em Jerusalém, deixem-me explicar-lhes isto! Ouçam com atenção:', 3, CURRENT_TIMESTAMP, false),
(44, 2, 15, 'estes homens não estão bêbados, como vocês supõem. Ainda são nove horas da manhã!', 3, CURRENT_TIMESTAMP, false),
(44, 2, 16, 'Pelo contrário, isto é o que foi predito pelo profeta Joel:', 3, CURRENT_TIMESTAMP, false),
(44, 2, 17, '‘Nos últimos dias, diz Deus, derramarei do meu Espírito sobre todos os povos. Os seus filhos e as suas filhas profetizarão, os jovens terão visões, os velhos terão sonhos.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 18, 'Sobre os meus servos e as minhas servas derramarei do meu Espírito naqueles dias, e eles profetizarão.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 19, 'Mostrarei maravilhas em cima no céu e sinais em baixo, na terra, sangue, fogo e nuvens de fumaça.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 20, 'O sol se tornará em trevas e a lua em sangue, antes que venha o grande e glorioso dia do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 21, 'E todo aquele que invocar o nome do Senhor será salvo! ’', 3, CURRENT_TIMESTAMP, false),
(44, 2, 22, '"Israelitas, ouçam estas palavras: Jesus de Nazaré foi aprovado por Deus diante de vocês por meio de milagres, maravilhas e sinais, que Deus fez entre vocês por intermédio dele, como vocês mesmos sabem.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 23, 'Este homem lhes foi entregue por propósito determinado e pré-conhecimento de Deus; e vocês, com a ajuda de homens perversos, o mataram, pregando-o na cruz.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 24, 'Mas Deus o ressuscitou dos mortos, rompendo os laços da morte, porque era impossível que a morte o retivesse.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 25, 'A respeito dele, disse Davi: ‘Eu sempre via o Senhor diante de mim. Porque ele está à minha direita, não serei abalado.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 26, 'Por isso o meu coração está alegre e a minha língua exulta; o meu corpo também repousará em esperança,', 3, CURRENT_TIMESTAMP, false),
(44, 2, 27, 'porque tu não me abandonarás no sepulcro, nem permitirás que o teu Santo sofra decomposição.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 28, 'Tu me fizeste conhecer os caminhos da vida e me encherás de alegria na tua presença’.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 29, '"Irmãos, posso dizer-lhes com franqueza que o patriarca Davi morreu e foi sepultado, e o seu túmulo está entre nós até o dia de hoje.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 30, 'Mas ele era profeta e sabia que Deus lhe prometera sob juramento que colocaria um dos seus descendentes em seu trono.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 31, 'Prevendo isso, falou da ressurreição do Cristo, que não foi abandonado no sepulcro e cujo corpo não sofreu decomposição.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 32, 'Deus ressuscitou este Jesus, e todos nós somos testemunhas desse fato.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 33, 'Exaltado à direita de Deus, ele recebeu do Pai o Espírito Santo prometido e derramou o que vocês agora vêem e ouvem.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 34, 'Pois Davi não subiu ao céu, mas ele mesmo declarou: ‘O Senhor disse ao meu Senhor: Senta-te à minha direita', 3, CURRENT_TIMESTAMP, false),
(44, 2, 35, 'até que eu ponha os teus inimigos como estrado para os teus pés’.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 36, '"Portanto, que todo Israel fique certo disto: Este Jesus, a quem vocês crucificaram, Deus o fez Senhor e Cristo".', 3, CURRENT_TIMESTAMP, false),
(44, 2, 37, 'Quando ouviram isso, os seus corações ficaram aflitos, e eles perguntaram a Pedro e aos outros apóstolos: "Irmãos, que faremos? "', 3, CURRENT_TIMESTAMP, false),
(44, 2, 38, 'Pedro respondeu: "Arrependam-se, e cada um de vocês seja batizado em nome de Jesus Cristo, para perdão dos seus pecados, e receberão o dom do Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 39, 'Pois a promessa é para vocês, para os seus filhos e para todos os que estão longe, para todos quantos o Senhor, o nosso Deus chamar".', 3, CURRENT_TIMESTAMP, false),
(44, 2, 40, 'Com muitas outras palavras os advertia e insistia com eles: "Salvem-se desta geração corrompida! "', 3, CURRENT_TIMESTAMP, false),
(44, 2, 41, 'Os que aceitaram a mensagem foram batizados, e naquele dia houve um acréscimo de cerca de três mil pessoas.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 42, 'Eles se dedicavam ao ensino dos apóstolos e à comunhão, ao partir do pão e às orações.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 43, 'Todos estavam cheios de temor, e muitas maravilhas e sinais eram feitos pelos apóstolos.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 44, 'Todos os que criam mantinham-se unidos e tinham tudo em comum.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 45, 'Vendendo suas propriedades e bens, distribuíam a cada um conforme a sua necessidade.', 3, CURRENT_TIMESTAMP, false),
(44, 2, 46, 'Todos os dias, continuavam a reunir-se no pátio do templo. Partiam o pão em suas casas, e juntos participavam das refeições, com alegria e sinceridade de coração,', 3, CURRENT_TIMESTAMP, false),
(44, 2, 47, 'louvando a Deus e tendo a simpatia de todo o povo. E o Senhor lhes acrescentava todos os dias os que iam sendo salvos.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 1, 'Certo dia Pedro e João estavam subindo ao templo na hora da oração, às três horas da tarde.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 2, 'Estava sendo levado para a porta do templo chamada Formosa um aleijado de nascença, que ali era colocado todos os dias para pedir esmolas aos que entravam no templo.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 3, 'Vendo que Pedro e João iam entrar no pátio do templo, pediu-lhes esmola.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 4, 'Pedro e João olharam bem para ele e, então, Pedro disse: "Olhe para nós! "', 3, CURRENT_TIMESTAMP, false),
(44, 3, 5, 'O homem olhou para eles com atenção, esperando receber deles alguma coisa.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 6, 'Disse Pedro: "Não tenho prata nem ouro, mas o que tenho, isto lhe dou. Em nome de Jesus Cristo, o Nazareno, ande".', 3, CURRENT_TIMESTAMP, false),
(44, 3, 7, 'Segurando-o pela mão direita, ajudou-o a levantar-se, e imediatamente os pés e os tornozelos do homem ficaram firmes.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 8, 'E de um salto pôs-se de pé e começou a andar. Depois entrou com eles no pátio do templo, andando, saltando e louvando a Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 9, 'Quando todo o povo o viu andando e louvando a Deus,', 3, CURRENT_TIMESTAMP, false),
(44, 3, 10, 'reconheceu que era ele o mesmo homem que costumava mendigar sentado à porta do templo chamada Formosa. Todos ficaram perplexos e muito admirados com o que lhe tinha acontecido.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 11, 'Apegando-se o mendigo a Pedro e João, todo o povo ficou maravilhado e correu até eles, ao lugar chamado Pórtico de Salomão.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 12, 'Vendo isso, Pedro lhes disse: "Israelitas, por que isto os surpreende? Por que vocês estão olhando para nós, como se tivéssemos feito este homem andar por nosso próprio poder ou piedade?', 3, CURRENT_TIMESTAMP, false),
(44, 3, 13, 'O Deus de Abraão, de Isaque e de Jacó, o Deus dos nossos antepassados, glorificou seu servo Jesus, a quem vocês entregaram para ser morto e negaram perante Pilatos, embora ele tivesse decidido soltá-lo.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 14, 'Vocês negaram publicamente o Santo e Justo e pediram que lhes fosse libertado um assassino.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 15, 'Vocês mataram o autor da vida, mas Deus o ressuscitou dos mortos. E nós somos testemunhas disso.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 16, 'Pela fé no nome de Jesus, o Nome curou este homem que vocês vêem e conhecem. A fé que vem por meio dele lhe deu esta saúde perfeita, como todos podem ver.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 17, '"Agora, irmãos, eu sei que vocês agiram por ignorância, bem como os seus líderes.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 18, 'Mas foi assim que Deus cumpriu o que tinha predito por todos os profetas, dizendo que o seu Cristo haveria de sofrer.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 19, 'Arrependam-se, pois, e voltem-se para Deus, para que os seus pecados sejam cancelados,', 3, CURRENT_TIMESTAMP, false),
(44, 3, 20, 'para que venham tempos de descanso da parte do Senhor, e ele mande o Cristo, o qual lhes foi designado, Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 21, 'É necessário que ele permaneça no céu até que chegue o tempo em que Deus restaurará todas as coisas, como falou há muito tempo, por meio dos seus santos profetas.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 22, 'Pois disse Moisés: ‘O Senhor Deus lhes levantará dentre seus irmãos um profeta como eu; ouçam-no em tudo o que ele lhes disser.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 23, 'Quem não ouvir esse profeta, será eliminado do meio do seu povo’.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 24, '"De fato, todos os profetas, de Samuel em diante, um por um, falaram e predisseram estes dias.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 25, 'E vocês são herdeiros dos profetas e da aliança que Deus fez com os seus antepassados. Ele disse a Abraão: ‘Por meio da sua descendência todos os povos da terra serão abençoados’.', 3, CURRENT_TIMESTAMP, false),
(44, 3, 26, 'Tendo Deus ressuscitado o seu Servo, enviou-o primeiramente a vocês, para abençoá-los, convertendo cada um de vocês das suas maldades".', 3, CURRENT_TIMESTAMP, false),
(44, 4, 1, 'Enquanto Pedro e João falavam ao povo, chegaram os sacerdotes, o capitão da guarda do templo e os saduceus.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 2, 'Eles estavam muito perturbados porque os apóstolos estavam ensinando o povo e proclamando em Jesus a ressurreição dos mortos.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 3, 'Agarraram Pedro e João e, como já estava anoitecendo, os colocaram na prisão até o dia seguinte.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 4, 'Mas, muitos dos que tinham ouvido a mensagem creram, chegando o número dos homens que creram a perto de cinco mil.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 5, 'No dia seguinte, as autoridades, os líderes religiosos e os mestres da lei reuniram-se em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 6, 'Estavam ali Anás, o sumo sacerdote, bem como Caifás, João, Alexandre e todos os que eram da família do sumo sacerdote.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 7, 'Mandaram trazer Pedro e João diante deles e começaram a interrogá-los: "Com que poder ou em nome de quem vocês fizeram isso? "', 3, CURRENT_TIMESTAMP, false),
(44, 4, 8, 'Então Pedro, cheio do Espírito Santo, disse-lhes: "Autoridades e líderes do povo!', 3, CURRENT_TIMESTAMP, false),
(44, 4, 9, 'Visto que hoje somos chamados para prestar contas de um ato de bondade em favor de um aleijado, sendo interrogados acerca de como ele foi curado,', 3, CURRENT_TIMESTAMP, false),
(44, 4, 10, 'saibam os senhores e todo o povo de Israel que por meio do nome de Jesus Cristo, o Nazareno, a quem os senhores crucificaram, mas a quem Deus ressuscitou dos mortos, este homem está aí curado diante dos senhores.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 11, 'Este Jesus é ‘a pedra que vocês, construtores, rejeitaram, e que se tornou a pedra angular’.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 12, 'Não há salvação em nenhum outro, pois, debaixo do céu não há nenhum outro nome dado aos homens pelo qual devamos ser salvos".', 3, CURRENT_TIMESTAMP, false),
(44, 4, 13, 'Vendo a coragem de Pedro e de João, e percebendo que eram homens comuns e sem instrução, ficaram admirados e reconheceram que eles haviam estado com Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 14, 'E como podiam ver ali com eles o homem que fora curado, nada podiam dizer contra eles.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 15, 'Assim, ordenaram que se retirassem do Sinédrio e começaram a discutir,', 3, CURRENT_TIMESTAMP, false),
(44, 4, 16, 'perguntando: "Que faremos com esses homens? Todos os que moram em Jerusalém sabem que eles realizaram um milagre notório que não podemos negar.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 17, 'Todavia, para impedir que isso se espalhe ainda mais entre o povo, precisamos adverti-los de que não falem mais com ninguém sobre esse nome".', 3, CURRENT_TIMESTAMP, false),
(44, 4, 18, 'Então, chamando-os novamente, ordenaram-lhes que não falassem nem ensinassem em nome de Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 19, 'Mas Pedro e João responderam: "Julguem os senhores mesmos se é justo aos olhos de Deus obedecer aos senhores e não a Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 20, 'Pois não podemos deixar de falar do que vimos e ouvimos".', 3, CURRENT_TIMESTAMP, false),
(44, 4, 21, 'Depois de mais ameaças, eles os deixaram ir. Não tinham como castigá-los, porque todo o povo estava louvando a Deus pelo que acontecera.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 22, 'Pois o homem que fora curado milagrosamente tinha mais de quarenta anos de idade.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 23, 'Quando foram soltos, Pedro e João voltaram para os seus e contaram tudo o que os chefes dos sacerdotes e os líderes religiosos lhes tinham dito.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 24, 'Ouvindo isso, levantaram juntos a voz a Deus, dizendo: "Ó Soberano, tu fizeste o céu, a terra, o mar e tudo o que neles há!', 3, CURRENT_TIMESTAMP, false),
(44, 4, 25, 'Tu falaste pelo Espírito Santo por boca do teu servo, nosso pai Davi: ‘Por que se enfurecem as nações, e os povos conspiram em vão?', 3, CURRENT_TIMESTAMP, false),
(44, 4, 26, 'Os reis da terra se levantam, e os governantes se reúnem contra o Senhor e contra o seu Ungido’.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 27, 'De fato, Herodes e Pôncio Pilatos reuniram-se com os gentios e com os povos de Israel nesta cidade, para conspirar contra o teu santo servo Jesus, a quem ungiste.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 28, 'Fizeram o que o teu poder e a tua vontade haviam decidido de antemão que acontecesse.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 29, 'Agora, Senhor, considera as ameaças deles e capacita os teus servos para anunciarem a tua palavra corajosamente.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 30, 'Estende a tua mão para curar e realizar sinais e maravilhas por meio do nome do teu santo servo Jesus".', 3, CURRENT_TIMESTAMP, false),
(44, 4, 31, 'Depois de orarem, tremeu o lugar em que estavam reunidos; todos ficaram cheios do Espírito Santo e anunciavam corajosamente a palavra de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 32, 'Da multidão dos que creram, uma era a mente e um o coração. Ninguém considerava unicamente sua coisa alguma que possuísse, mas compartilhavam tudo o que tinham.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 33, 'Com grande poder os apóstolos continuavam a testemunhar da ressurreição do Senhor Jesus, e grandiosa graça estava sobre todos eles.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 34, 'Não havia pessoas necessitadas entre eles, pois os que possuíam terras ou casas as vendiam, traziam o dinheiro da venda', 3, CURRENT_TIMESTAMP, false),
(44, 4, 35, 'e o colocavam aos pés dos apóstolos, que o distribuíam segundo a necessidade de cada um.', 3, CURRENT_TIMESTAMP, false),
(44, 4, 36, 'José, um levita de Chipre a quem os apóstolos deram o nome de Barnabé, que significa encorajador,', 3, CURRENT_TIMESTAMP, false),
(44, 4, 37, 'vendeu um campo que possuía, trouxe o dinheiro e o colocou aos pés dos apóstolos.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 1, 'Um homem chamado Ananias, juntamente com Safira, sua mulher, também vendeu uma propriedade.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 2, 'Ele reteve parte do dinheiro para si, sabendo disso também sua mulher; e o restante levou e colocou aos pés dos apóstolos.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 3, 'Então perguntou Pedro: "Ananias, como você permitiu que Satanás enchesse o seu coração, a ponto de você mentir ao Espírito Santo e guardar para si uma parte do dinheiro que recebeu pela propriedade?', 3, CURRENT_TIMESTAMP, false),
(44, 5, 4, 'Ela não lhe pertencia? E, depois de vendida, o dinheiro não estava em seu poder? O que o levou a pensar em fazer tal coisa? Você não mentiu aos homens, mas sim a Deus".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 5, 'Ouvindo isso, Ananias caiu e morreu. Grande temor apoderou-se de todos os que ouviram o que tinha acontecido.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 6, 'Então os moços vieram, envolveram seu corpo, levaram-no para fora e o sepultaram.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 7, 'Cerca de três horas mais tarde, entrou sua mulher, sem saber o que havia acontecido.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 8, 'Pedro lhe perguntou: "Diga-me, foi esse o preço que vocês conseguiram pela propriedade? " Respondeu ela: "Sim, foi esse mesmo".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 9, 'Pedro lhe disse: "Por que vocês entraram em acordo para tentar o Espírito do Senhor? Veja! Estão à porta os pés dos que sepultaram seu marido, e eles a levarão também".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 10, 'Naquele mesmo instante, ela caiu aos pés dele e morreu. Então os moços entraram e, encontrando-a morta, levaram-na e a sepultaram ao lado de seu marido.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 11, 'E grande temor apoderou-se de toda a igreja e de todos os que ouviram falar desses acontecimentos.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 12, 'Os apóstolos realizavam muitos sinais e maravilhas entre o povo. Todos os que creram costumavam reunir-se no Pórtico de Salomão.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 13, 'Dos demais, ninguém ousava juntar-se a eles, embora o povo os tivesse em alto conceito.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 14, 'Em número cada vez maior, homens e mulheres criam no Senhor e lhes eram acrescentados,', 3, CURRENT_TIMESTAMP, false),
(44, 5, 15, 'de modo que o povo também levava os doentes às ruas e os colocava em camas e macas, para que pelo menos a sombra de Pedro se projetasse sobre alguns, enquanto ele passava.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 16, 'Afluíam também multidões das cidades próximas a Jerusalém, trazendo seus doentes e os que eram atormentados por espíritos imundos; e todos eram curados.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 17, 'Então o sumo sacerdote e todos os seus companheiros, membros do partido dos saduceus, ficaram cheios de inveja.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 18, 'Por isso, mandaram prender os apóstolos, colocando-os numa prisão pública.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 19, 'Mas durante a noite um anjo do Senhor abriu as portas do cárcere, levou-os para fora e', 3, CURRENT_TIMESTAMP, false),
(44, 5, 20, 'disse: "Dirijam-se ao templo e relatem ao povo toda a mensagem desta Vida".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 21, 'Ao amanhecer, eles entraram no pátio do templo, como haviam sido instruídos, e começaram a ensinar o povo. Quando chegaram o sumo sacerdote e os que os seus companheiros, convocaram o Sinédrio — toda a assembléia dos líderes religiosos de Israel — e mandaram buscar os apóstolos na prisão.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 22, 'Todavia, ao chegarem à prisão, os guardas não os encontraram ali. Então, voltaram e relataram:', 3, CURRENT_TIMESTAMP, false),
(44, 5, 23, '"Encontramos a prisão trancada com toda a segurança, com os guardas diante das portas; mas, quando as abrimos não havia ninguém".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 24, 'Diante desse relato, o capitão da guarda do templo e os chefes dos sacerdotes ficaram perplexos, imaginando o que teria acontecido.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 25, 'Nesse momento chegou alguém e disse: "Os homens que os senhores puseram na prisão estão no pátio do templo, ensinando o povo".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 26, 'Então, indo para lá com os guardas, o capitão trouxe os apóstolos, mas sem o uso de força, pois temiam que o povo os apedrejasse.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 27, 'Tendo levado os apóstolos, apresentaram-nos ao Sinédrio para serem interrogados pelo sumo sacerdote,', 3, CURRENT_TIMESTAMP, false),
(44, 5, 28, 'que lhes disse: "Demos ordens expressas a vocês para que não ensinassem neste nome. Todavia, vocês encheram Jerusalém com sua doutrina e nos querem tornar culpados do sangue desse homem".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 29, 'Pedro e os outros apóstolos responderam: "É preciso obedecer antes a Deus do que aos homens!', 3, CURRENT_TIMESTAMP, false),
(44, 5, 30, 'O Deus dos nossos antepassados ressuscitou Jesus, a quem os senhores mataram, suspendendo-o num madeiro.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 31, 'Deus o exaltou, colocando-o à sua direita como Príncipe e Salvador, para dar a Israel arrependimento e perdão de pecados.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 32, 'Nós somos testemunhas destas coisas, bem como o Espírito Santo, que Deus concedeu aos que lhe obedecem".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 33, 'Ouvindo isso, eles ficaram furiosos e queriam matá-los.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 34, 'Mas um fariseu chamado Gamaliel, mestre da lei, respeitado por todo o povo, levantou-se no Sinédrio e pediu que os homens fossem retirados por um momento.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 35, 'Então lhes disse: "Israelitas, considerem cuidadosamente o que pretendem fazer a esses homens.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 36, 'Há algum tempo, apareceu Teudas, reivindicando ser alguém, e cerca de quatrocentos homens se juntaram a ele. Ele foi morto, todos os seus seguidores se dispersaram e acabaram em nada.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 37, 'Depois dele, nos dias do recenseamento, apareceu Judas, o galileu, que liderou um grupo em rebelião. Ele também foi morto, e todos os seus seguidores foram dispersos.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 38, 'Portanto, neste caso eu os aconselho: deixem esses homens em paz e soltem-nos. Se o propósito ou atividade deles for de origem humana, fracassará;', 3, CURRENT_TIMESTAMP, false),
(44, 5, 39, 'se proceder de Deus, vocês não serão capazes de impedi-los, pois se acharão lutando contra Deus".', 3, CURRENT_TIMESTAMP, false),
(44, 5, 40, 'Eles foram convencidos pelo discurso de Gamaliel. Chamaram os apóstolos e mandaram açoitá-los. Depois, ordenaram-lhes que não falassem em nome de Jesus e os deixaram sair em liberdade.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 41, 'Os apóstolos saíram do Sinédrio, alegres por terem sido considerados dignos de serem humilhados por causa do Nome.', 3, CURRENT_TIMESTAMP, false),
(44, 5, 42, 'Todos os dias, no templo e de casa em casa, não deixavam de ensinar e proclamar que Jesus é o Cristo.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 1, 'Naqueles dias, crescendo o número de discípulos, os judeus de fala grega entre eles queixaram-se dos judeus de fala hebraica, porque suas viúvas estavam sendo esquecidas na distribuição diária de alimento.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 2, 'Por isso os Doze reuniram todos os discípulos e disseram: "Não é certo negligenciarmos o ministério da palavra de Deus, a fim de servir às mesas.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 3, 'Irmãos, escolham entre vocês sete homens de bom testemunho, cheios do Espírito e de sabedoria. Passaremos a eles essa tarefa', 3, CURRENT_TIMESTAMP, false),
(44, 6, 4, 'e nos dedicaremos à oração e ao ministério da palavra".', 3, CURRENT_TIMESTAMP, false),
(44, 6, 5, 'Tal proposta agradou a todos. Então escolheram Estêvão, homem cheio de fé e do Espírito Santo, além de Filipe, Prócoro, Nicanor, Timom, Pármenas e Nicolau, um convertido ao judaísmo, proveniente de Antioquia.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 6, 'Apresentaram esses homens aos apóstolos, os quais oraram e lhes impuseram as mãos.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 7, 'Assim, a palavra de Deus se espalhava. Crescia rapidamente o número de discípulos em Jerusalém; também um grande número de sacerdotes obedecia à fé.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 8, 'Estêvão, homem cheio da graça e do poder de Deus, realizava grandes maravilhas e sinais entre o povo.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 9, 'Contudo, levantou-se oposição dos membros da chamada Sinagoga dos Libertos, dos judeus de Cirene e de Alexandria, bem como das províncias da Cilícia e da Ásia. Esses homens começaram a discutir com Estêvão,', 3, CURRENT_TIMESTAMP, false),
(44, 6, 10, 'mas não podiam resistir à sabedoria e ao Espírito com que ele falava.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 11, 'Então subornaram alguns homens para dizerem: "Ouvimos Estêvão falar palavras blasfemas contra Moisés e contra Deus".', 3, CURRENT_TIMESTAMP, false),
(44, 6, 12, 'Com isso agitaram o povo, os líderes religiosos e os mestres da lei. E, prendendo Estêvão, levaram-no ao Sinédrio.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 13, 'Ali apresentaram falsas testemunhas que diziam: "Este homem não pára de falar contra este lugar santo e contra a lei.', 3, CURRENT_TIMESTAMP, false),
(44, 6, 14, 'Pois o ouvimos dizer que esse Jesus, o Nazareno, destruirá este lugar e mudará os costumes que Moisés nos legou".', 3, CURRENT_TIMESTAMP, false),
(44, 6, 15, 'Olhando para ele, todos os que estavam sentados no Sinédrio viram que o seu rosto parecia o rosto de um anjo.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 1, 'Então o sumo sacerdote perguntou a Estêvão: "São verdadeiras estas acusações? "', 3, CURRENT_TIMESTAMP, false),
(44, 7, 2, 'A isso ele respondeu: "Irmãos e pais, ouçam-me! O Deus glorioso apareceu a Abraão, nosso pai, estando ele ainda na Mesopotâmia, antes de morar em Harã, e lhe disse:', 3, CURRENT_TIMESTAMP, false),
(44, 7, 3, '‘Saia da sua terra e do meio dos seus parentes e vá para a terra que eu lhe mostrarei’.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 4, '"Então, ele saiu da terra dos caldeus e se estabeleceu em Harã. Depois da morte de seu pai, Deus o trouxe a esta terra, onde vocês agora vivem.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 5, 'Deus não lhe deu nenhuma herança aqui, nem mesmo o espaço de um pé. Mas lhe prometeu que ele e, depois dele, seus descendentes, possuiriam a terra, embora, naquele tempo, Abraão não tivesse filhos.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 6, 'Deus lhe falou desta forma: ‘Seus descendentes serão peregrinos numa terra estrangeira, e serão escravizados e maltratados por quatrocentos anos.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 7, 'Mas eu castigarei a nação a quem servirão como escravos, e depois sairão dali e me adorarão neste lugar’.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 8, 'E deu a Abraão a aliança da circuncisão. Por isso, Abraão gerou Isaque e o circuncidou oito dias depois do seu nascimento. Mais tarde, Isaque gerou Jacó, e este os doze patriarcas.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 9, '"Os patriarcas, tendo inveja de José, venderam-no como escravo para o Egito. Mas Deus estava com ele', 3, CURRENT_TIMESTAMP, false),
(44, 7, 10, 'e o libertou de todas as suas tribulações, dando a José favor e sabedoria diante do faraó, rei do Egito; este o tornou governador do Egito e de todo o seu palácio.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 11, '"Depois houve fome em todo o Egito e em Canaã, trazendo consigo grande sofrimento, e os nossos antepassados não encontravam alimento.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 12, 'Ouvindo que havia trigo no Egito, Jacó enviou nossos antepassados em sua primeira viagem.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 13, 'Na segunda viagem deles, José fez-se reconhecer por seus irmãos, e o faraó pôde conhecer a família de José.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 14, 'Depois disso, José mandou buscar seu pai Jacó e toda a sua família, que eram setenta e cinco pessoas.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 15, 'Então Jacó desceu ao Egito, onde faleceram ele e os nossos antepassados.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 16, 'Seus corpos foram levados de volta a Siquém e colocados no túmulo que Abraão havia comprado ali dos filhos de Hamor, por certa quantia.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 17, '"Ao se aproximar o tempo em que Deus cumpriria sua promessa a Abraão, aumentou muito o número do nosso povo no Egito.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 18, 'Então outro rei, que nada sabia a respeito de José, passou a governar o Egito.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 19, 'Ele agiu traiçoeiramente para com o nosso povo e oprimiu os nossos antepassados, obrigando-os a abandonar os seus recém-nascidos, para que não sobrevivessem.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 20, '"Naquele tempo nasceu Moisés, que era um menino extraordinário. Por três meses ele foi criado na casa de seu pai.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 21, 'Quando foi abandonado, a filha do faraó o tomou e o criou como seu próprio filho.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 22, 'Moisés foi educado em toda a sabedoria dos egípcios e veio a ser poderoso em palavras e obras.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 23, '"Ao completar quarenta anos, Moisés decidiu visitar seus irmãos israelitas.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 24, 'Ao ver um deles sendo maltratado por um egípcio, saiu em defesa do oprimido e o vingou, matando o egípcio.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 25, 'Ele pensava que seus irmãos compreenderiam que Deus o estava usando para salvá-los, mas eles não o compreenderam.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 26, 'No dia seguinte, Moisés dirigiu-se a dois israelitas que estavam brigando, e tentou reconciliá-los, dizendo: ‘Homens, vocês são irmãos; por que ferem um ao outro? ’', 3, CURRENT_TIMESTAMP, false),
(44, 7, 27, '"Mas o homem que maltratava o outro empurrou Moisés e disse: ‘Quem o nomeou líder e juiz sobre nós?', 3, CURRENT_TIMESTAMP, false),
(44, 7, 28, 'Quer matar-me como matou o egípcio ontem? ’', 3, CURRENT_TIMESTAMP, false),
(44, 7, 29, 'Ouvindo isso, Moisés fugiu para Midiã, onde ficou morando como estrangeiro e teve dois filhos.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 30, '"Passados quarenta anos, apareceu a Moisés um anjo nas labaredas de uma sarça em chamas no deserto, perto do monte Sinai.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 31, 'Vendo aquilo, ficou atônito. E, aproximando-se para observar, ouviu a voz do Senhor:', 3, CURRENT_TIMESTAMP, false),
(44, 7, 32, '‘Eu sou o Deus dos seus antepassados, o Deus de Abraão, o Deus de Isaque e o Deus de Jacó’. Moisés, tremendo de medo, não ousava olhar.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 33, '"Então o Senhor lhe disse: ‘Tire as sandálias dos pés, porque o lugar em que você está é terra santa.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 34, 'De fato tenho visto a opressão sobre o meu povo no Egito. Ouvi seus gemidos e desci para livrá-lo. Venha agora, e eu o enviarei de volta ao Egito’.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 35, '"Este é o mesmo Moisés que tinham rejeitado com estas palavras: ‘Quem o nomeou líder e juiz? ’ Ele foi enviado pelo próprio Deus para ser líder e libertador deles, por meio do anjo que lhe tinha aparecido na sarça.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 36, 'Ele os tirou de lá, fazendo maravilhas e sinais no Egito, no mar Vermelho e no deserto durante quarenta anos.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 37, '"Este é aquele Moisés que disse aos israelitas: ‘Deus lhes levantará dentre seus irmãos um profeta como eu’.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 38, 'Ele estava na congregação, no deserto, com o anjo que lhe falava no monte Sinai e com os nossos antepassados, e recebeu palavras vivas, para transmiti-las a nós.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 39, '"Mas nossos antepassados se recusaram a obedecer-lhe; pelo contrário, rejeitaram-no, e em seus corações voltaram para o Egito.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 40, 'Disseram a Arão: ‘Faça para nós deuses que nos conduzam, pois a esse Moisés que nos tirou do Egito, não sabemos o que lhe aconteceu! ’', 3, CURRENT_TIMESTAMP, false),
(44, 7, 41, 'Naquela ocasião fizeram um ídolo em forma de bezerro. Trouxeram-lhe sacrifícios e fizeram uma celebração em honra ao que suas mãos tinham feito.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 42, 'Mas Deus afastou-se deles e os entregou à adoração dos astros, conforme o que foi escrito no livro dos profetas: ‘Foi a mim que vocês apresentaram sacrifícios e ofertas durante os quarenta anos no deserto, Ó nação de Israel?', 3, CURRENT_TIMESTAMP, false),
(44, 7, 43, 'Ao invés disso, levantaram o santuário de Moloque e a estrela do seu deus Renfã, ídolos que vocês fizeram para adorar! Portanto, eu os enviarei para o exílio, para além da Babilônia’.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 44, '"No deserto os nossos antepassados tinham o tabernáculo da aliança, que fora feito segundo a ordem de Deus a Moisés, de acordo com o modelo que ele tinha visto.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 45, 'Tendo recebido o tabernáculo, nossos antepassados o levaram, sob a liderança de Josué, quando tomaram a terra das nações que Deus expulsou de diante deles. Esse tabernáculo permaneceu na terra até a época de Davi,', 3, CURRENT_TIMESTAMP, false),
(44, 7, 46, 'que encontrou graça diante de Deus e pediu que ele lhe permitisse providenciar uma habitação para o Deus de Jacó.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 47, 'Mas foi Salomão quem lhe construiu a casa.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 48, '"Todavia, o Altíssimo não habita em casas feitas por homens. Como diz o profeta:', 3, CURRENT_TIMESTAMP, false),
(44, 7, 49, '‘O céu é o meu trono, e a terra, o estrado dos meus pés. Que espécie de casa vocês me edificarão? diz o Senhor, ou onde seria meu lugar de descanso?', 3, CURRENT_TIMESTAMP, false),
(44, 7, 50, 'Não foram as minhas mãos que fizeram todas estas coisas? ’', 3, CURRENT_TIMESTAMP, false),
(44, 7, 51, '"Povo rebelde, obstinado de coração e de ouvidos! Vocês são iguais aos seus antepassados: sempre resistem ao Espírito Santo!', 3, CURRENT_TIMESTAMP, false),
(44, 7, 52, 'Qual dos profetas os seus antepassados não perseguiram? Eles mataram aqueles que prediziam a vinda do Justo, de quem agora vocês se tornaram traidores e assassinos —', 3, CURRENT_TIMESTAMP, false),
(44, 7, 53, 'vocês, que receberam a Lei por intermédio de anjos, mas não lhe obedeceram".', 3, CURRENT_TIMESTAMP, false),
(44, 7, 54, 'Ouvindo isso, ficavam furiosos e rangiam os dentes contra ele.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 55, 'Mas Estêvão, cheio do Espírito Santo, levantou os olhos para o céu e viu a glória de Deus, e Jesus de pé, à direita de Deus,', 3, CURRENT_TIMESTAMP, false),
(44, 7, 56, 'e disse: "Vejo o céu aberto e o Filho do homem de pé, à direita de Deus".', 3, CURRENT_TIMESTAMP, false),
(44, 7, 57, 'Mas eles taparam os ouvidos e, gritando bem alto, lançaram-se todos juntos contra ele,', 3, CURRENT_TIMESTAMP, false),
(44, 7, 58, 'arrastaram-no para fora da cidade e começaram a apedrejá-lo. As testemunhas deixaram seus mantos aos pés de um jovem chamado Saulo.', 3, CURRENT_TIMESTAMP, false),
(44, 7, 59, 'Enquanto apedrejavam Estêvão, este orava: "Senhor Jesus, recebe o meu espírito".', 3, CURRENT_TIMESTAMP, false),
(44, 7, 60, 'Então caiu de joelhos e bradou: "Senhor, não os consideres culpados deste pecado". E, dizendo isso, adormeceu.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 1, 'E Saulo estava ali, consentindo na morte de Estêvão. Naquela ocasião desencadeou-se grande perseguição contra a igreja em Jerusalém. Todos, exceto os apóstolos, foram dispersos pelas regiões da Judéia e de Samaria.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 2, 'Alguns homens piedosos sepultaram Estêvão e fizeram por ele grande lamentação.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 3, 'Saulo, por sua vez, devastava a igreja. Indo de casa em casa, arrastava homens e mulheres e os lançava na prisão.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 4, 'Os que haviam sido dispersos pregavam a palavra por onde quer que fossem.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 5, 'Indo Filipe para uma cidade de Samaria, ali lhes anunciava o Cristo.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 6, 'Quando a multidão ouviu Filipe e viu os sinais miraculosos que ele realizava, deu unânime atenção ao que ele dizia.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 7, 'Os espíritos imundos saíam de muitos, dando gritos, e muitos paralíticos e mancos foram curados.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 8, 'Assim, houve grande alegria naquela cidade.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 9, 'Um homem chamado Simão vinha praticando feitiçaria durante algum tempo naquela cidade, impressionando todo o povo de Samaria. Ele se dizia muito importante,', 3, CURRENT_TIMESTAMP, false),
(44, 8, 10, 'e todo o povo, do mais simples ao mais rico, dava-lhe atenção e exclamava: "Este homem é o poder divino conhecido como Grande Poder".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 11, 'Eles o seguiam, pois ele os havia iludido com sua mágica durante muito tempo.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 12, 'No entanto, quando Filipe lhes pregou as boas novas do Reino de Deus e do nome de Jesus Cristo, creram nele, e foram batizados, tanto homens como mulheres.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 13, 'O próprio Simão também creu e foi batizado, e seguia a Filipe por toda parte, observando maravilhado os grandes sinais e milagres que eram realizados.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 14, 'Os apóstolos em Jerusalém, ouvindo que Samaria havia aceitado a palavra de Deus, enviaram para lá Pedro e João.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 15, 'Estes, ao chegarem, oraram para que eles recebessem o Espírito Santo,', 3, CURRENT_TIMESTAMP, false),
(44, 8, 16, 'pois o Espírito ainda não havia descido sobre nenhum deles; tinham apenas sido batizados em nome do Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 17, 'Então Pedro e João lhes impuseram as mãos, e eles receberam o Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 18, 'Vendo Simão que o Espírito era dado com a imposição das mãos dos apóstolos, ofereceu-lhes dinheiro', 3, CURRENT_TIMESTAMP, false),
(44, 8, 19, 'e disse: "Dêem-me também este poder, para que a pessoa sobre quem eu impuser as mãos receba o Espírito Santo".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 20, 'Pedro respondeu: "Pereça com você o seu dinheiro! Você pensa que pode comprar o dom de Deus com dinheiro?', 3, CURRENT_TIMESTAMP, false),
(44, 8, 21, 'Você não tem parte nem direito algum neste ministério, porque o seu coração não é reto diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 22, 'Arrependa-se dessa maldade e ore ao Senhor. Talvez ele lhe perdoe tal pensamento do seu coração,', 3, CURRENT_TIMESTAMP, false),
(44, 8, 23, 'pois vejo que você está cheio de amargura e preso pelo pecado".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 24, 'Simão, porém, respondeu: "Orem vocês ao Senhor por mim, para que não me aconteça nada do que vocês disseram".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 25, 'Tendo testemunhado e proclamado a palavra do Senhor, Pedro e João voltaram a Jerusalém, pregando o evangelho em muitos povoados samaritanos.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 26, 'Um anjo do Senhor disse a Filipe: "Vá para o sul, para a estrada deserta que desce de Jerusalém a Gaza".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 27, 'Ele se levantou e partiu. No caminho encontrou um eunuco etíope, um oficial importante, encarregado de todos os tesouros de Candace, rainha dos etíopes. Esse homem viera a Jerusalém para adorar a Deus e,', 3, CURRENT_TIMESTAMP, false),
(44, 8, 28, 'de volta para casa, sentado em sua carruagem, lia o livro do profeta Isaías.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 29, 'E o Espírito disse a Filipe: "Aproxime-se dessa carruagem e acompanhe-a".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 30, 'Então Filipe correu para a carruagem, ouviu o homem lendo o profeta Isaías e lhe perguntou: "O senhor entende o que está lendo? "', 3, CURRENT_TIMESTAMP, false),
(44, 8, 31, 'Ele respondeu: "Como posso entender se alguém não me explicar? " Assim, convidou Filipe para subir e sentar-se ao seu lado.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 32, 'O eunuco estava lendo esta passagem da Escritura: "Ele foi levado como ovelha para o matadouro, e como cordeiro mudo diante do tosquiador, ele não abriu a sua boca.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 33, 'Em sua humilhação foi privado de justiça. Quem pode falar dos seus descendentes? Pois a sua vida foi tirada da terra".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 34, 'O eunuco perguntou a Filipe: "Diga-me, por favor: de quem o profeta está falando? De si próprio ou de outro? "', 3, CURRENT_TIMESTAMP, false),
(44, 8, 35, 'Então Filipe, começando com aquela passagem da Escritura, anunciou-lhe as boas novas de Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 36, 'Prosseguindo pela estrada, chegaram a um lugar onde havia água. O eunuco disse: "Olhe, aqui há água. Que me impede de ser batizado? "', 3, CURRENT_TIMESTAMP, false),
(44, 8, 37, 'Disse Filipe: "Você pode, se crê de todo o coração". O eunuco respondeu: "Creio que Jesus Cristo é o Filho de Deus".', 3, CURRENT_TIMESTAMP, false),
(44, 8, 38, 'Assim, deu ordem para parar a carruagem. Então Filipe e o eunuco desceram à água, e Filipe o batizou.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 39, 'Quando saíram da água, o Espírito do Senhor arrebatou Filipe repentinamente. O eunuco não o viu mais e, cheio de alegria, seguiu o seu caminho.', 3, CURRENT_TIMESTAMP, false),
(44, 8, 40, 'Filipe, porém, apareceu em Azoto e, indo para Cesaréia, pregava o evangelho em todas as cidades pelas quais passava.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 1, 'Enquanto isso, Saulo ainda respirava ameaças de morte contra os discípulos do Senhor. Dirigindo-se ao sumo sacerdote,', 3, CURRENT_TIMESTAMP, false),
(44, 9, 2, 'pediu-lhe cartas para as sinagogas de Damasco, de maneira que, caso encontrasse ali homens ou mulheres que pertencessem ao Caminho, pudesse levá-los presos para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 3, 'Em sua viagem, quando se aproximava de Damasco, de repente brilhou ao seu redor uma luz vinda do céu.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 4, 'Ele caiu por terra e ouviu uma voz que lhe dizia: "Saulo, Saulo, por que você me persegue? "', 3, CURRENT_TIMESTAMP, false),
(44, 9, 5, 'Saulo perguntou: "Quem és tu, Senhor? " Ele respondeu: "Eu sou Jesus, a quem você persegue.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 6, 'Levante-se, entre na cidade; alguém lhe dirá o que você deve fazer".', 3, CURRENT_TIMESTAMP, false),
(44, 9, 7, 'Os homens que viajavam com Saulo pararam emudecidos; ouviam a voz mas não viam ninguém.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 8, 'Saulo levantou-se do chão e, abrindo os olhos, não conseguia ver nada. E eles o levaram pela mão até Damasco.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 9, 'Por três dias ele esteve cego, não comeu nem bebeu.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 10, 'Em Damasco havia um discípulo chamado Ananias. O Senhor o chamou numa visão: "Ananias! " "Eis-me aqui, Senhor", respondeu ele.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 11, 'O Senhor lhe disse: "Vá à casa de Judas, na rua chamada Direita, e pergunte por um homem de Tarso chamado Saulo. Ele está orando;', 3, CURRENT_TIMESTAMP, false),
(44, 9, 12, 'numa visão viu um homem chamado Ananias chegar e impor-lhe as mãos para que voltasse a ver".', 3, CURRENT_TIMESTAMP, false),
(44, 9, 13, 'Respondeu Ananias: "Senhor, tenho ouvido muita coisa a respeito desse homem e de todo o mal que ele tem feito aos teus santos em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 14, 'Ele chegou aqui com autorização dos chefes dos sacerdotes para prender todos os que invocam o teu nome".', 3, CURRENT_TIMESTAMP, false),
(44, 9, 15, 'Mas o Senhor disse a Ananias: "Vá! Este homem é meu instrumento escolhido para levar o meu nome perante os gentios e seus reis, e perante o povo de Israel.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 16, 'Mostrarei a ele o quanto deve sofrer pelo meu nome".', 3, CURRENT_TIMESTAMP, false),
(44, 9, 17, 'Então Ananias foi, entrou na casa, impôs as mãos sobre Saulo e disse: "Irmão Saulo, o Senhor Jesus, que lhe apareceu no caminho por onde você vinha, enviou-me para que você volte a ver e seja cheio do Espírito Santo".', 3, CURRENT_TIMESTAMP, false),
(44, 9, 18, 'Imediatamente, algo como escamas caiu dos olhos de Saulo e ele passou a ver novamente. Levantando-se, foi batizado', 3, CURRENT_TIMESTAMP, false),
(44, 9, 19, 'e, depois de comer, recuperou as forças. Saulo passou vários dias com os discípulos em Damasco.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 20, 'Logo começou a pregar nas sinagogas que Jesus é o Filho de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 21, 'Todos os que o ouviam ficavam perplexos e perguntavam: "Não é ele o homem que procurava destruir em Jerusalém aqueles que invocam este nome? E não veio para cá justamente para levá-los presos aos chefes dos sacerdotes? "', 3, CURRENT_TIMESTAMP, false),
(44, 9, 22, 'Todavia, Saulo se fortalecia cada vez mais e confundia os judeus que viviam em Damasco, demonstrando que Jesus é o Cristo.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 23, 'Decorridos muitos dias, os judeus decidiram de comum acordo matá-lo,', 3, CURRENT_TIMESTAMP, false),
(44, 9, 24, 'mas Saulo ficou sabendo do plano deles. Dia e noite eles vigiavam as portas da cidade a fim de matá-lo.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 25, 'Mas os seus discípulos o levaram de noite e o fizeram descer num cesto, através de uma abertura na muralha.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 26, 'Quando chegou a Jerusalém, tentou reunir-se aos discípulos, mas todos estavam com medo dele, não acreditando que fosse realmente um discípulo.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 27, 'Então Barnabé o levou aos apóstolos e lhes contou como, no caminho, Saulo vira o Senhor, que lhe falara, e como em Damasco ele havia pregado corajosamente em nome de Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 28, 'Assim, Saulo ficou com eles, e andava com liberdade em Jerusalém, pregando corajosamente em nome do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 29, 'Falava e discutia com os judeus de fala grega, mas estes tentavam matá-lo.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 30, 'Sabendo disso, os irmãos o levaram para Cesaréia e o enviaram para Tarso.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 31, 'A igreja passava por um período de paz em toda a Judéia, Galiléia e Samaria. Ela se edificava e, encorajada pelo Espírito Santo, crescia em número, vivendo no temor do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 32, 'Viajando por toda parte, Pedro foi visitar os santos que viviam em Lida.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 33, 'Ali encontrou um paralítico chamado Enéias, que estava acamado fazia oito anos.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 34, 'Disse-lhe Pedro: "Enéias, Jesus Cristo vai curá-lo! Levante-se e arrume a sua cama". Ele se levantou imediatamente.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 35, 'Todos os que viviam em Lida e Sarona o viram e se converteram ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 36, 'Em Jope havia uma discípula chamada Tabita, que em grego é Dorcas, que se dedicava a praticar boas obras e dar esmolas.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 37, 'Naqueles dias ela ficou doente e morreu, e seu corpo foi lavado e colocado num quarto do andar superior.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 38, 'Lida ficava perto de Jope, e quando os discípulos ouviram falar que Pedro estava em Lida, mandaram-lhe dois homens dizer-lhe: "Não se demore em vir até nós".', 3, CURRENT_TIMESTAMP, false),
(44, 9, 39, 'Pedro foi com eles e, quando chegou, foi levado para o quarto do andar superior. Todas as viúvas o rodearam, chorando e mostrando-lhe os vestidos e outras roupas que Dorcas tinha feito quando ainda estava com elas.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 40, 'Pedro mandou que todos saíssem do quarto; depois, ajoelhou-se e orou. Voltando-se para a mulher morta, disse: "Tabita, levante-se". Ela abriu os olhos e, vendo Pedro, sentou-se.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 41, 'Tomando-a pela mão, ajudou-a a pôr-se de pé. Então, chamando os santos e as viúvas, apresentou-a viva.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 42, 'Este fato se tornou conhecido em toda a cidade de Jope, e muitos creram no Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 9, 43, 'Pedro ficou em Jope durante algum tempo, com um curtidor de couro chamado Simão.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 1, 'Havia em Cesaréia um homem chamado Cornélio, centurião do regimento conhecido como Italiano.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 2, 'Ele e toda a sua família eram piedosos e tementes a Deus; dava muitas esmolas ao povo e orava continuamente a Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 3, 'Certo dia, por volta das três horas da tarde, ele teve uma visão. Viu claramente um anjo de Deus que se aproximava dele e dizia: "Cornélio! "', 3, CURRENT_TIMESTAMP, false),
(44, 10, 4, 'Atemorizado, Cornélio olhou para ele e perguntou: "Que é, Senhor? " O anjo respondeu: "Suas orações e esmolas subiram como oferta memorial diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 5, 'Agora, mande alguns homens a Jope para trazerem um certo Simão, também conhecido como Pedro,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 6, 'que está hospedado na casa de Simão, o curtidor de couro, que fica perto do mar".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 7, 'Depois que o anjo que lhe falou se foi, Cornélio chamou dois dos seus servos e um soldado piedoso dentre os seus auxiliares,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 8, 'e, contando-lhes tudo o que tinha acontecido, enviou-os a Jope.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 9, 'No dia seguinte, por volta do meio dia, enquanto eles viajavam e se aproximavam da cidade, Pedro subiu ao terraço para orar.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 10, 'Tendo fome, queria comer; enquanto a refeição estava sendo preparada, caiu em êxtase.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 11, 'Viu o céu aberto e algo semelhante a um grande lençol que descia à terra, preso pelas quatro pontas,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 12, 'contendo toda espécie de quadrúpedes, bem como de répteis da terra e aves do céu.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 13, 'Então uma voz lhe disse: "Levante-se, Pedro; mate e coma".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 14, 'Mas Pedro respondeu: "De modo nenhum, Senhor! Jamais comi algo impuro ou imundo! "', 3, CURRENT_TIMESTAMP, false),
(44, 10, 15, 'A voz lhe falou segunda vez: "Não chame impuro ao que Deus purificou".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 16, 'Isso aconteceu três vezes, e em seguida o lençol foi recolhido ao céu.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 17, 'Enquanto Pedro estava refletindo no significado da visão, os homens enviados por Cornélio descobriram onde era a casa de Simão e chegaram à porta.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 18, 'Chamando, perguntaram se ali estava hospedado Simão, conhecido como Pedro.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 19, 'Enquanto Pedro ainda estava pensando na visão, o Espírito lhe disse: "Simão, três homens estão procurando por você.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 20, 'Portanto, levante-se e desça. Não hesite em ir com eles, pois eu os enviei".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 21, 'Pedro desceu e disse aos homens: "Eu sou quem vocês estão procurando. Por que motivo vieram? "', 3, CURRENT_TIMESTAMP, false),
(44, 10, 22, 'Os homens responderam: "Viemos da parte do centurião Cornélio. Ele é um homem justo e temente a Deus, respeitado por todo o povo judeu. Um santo anjo lhe disse que o chamasse à sua casa, para que ele ouça o que você tem para dizer".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 23, 'Pedro os convidou a entrar e os hospedou. No dia seguinte Pedro partiu com eles, e alguns dos irmãos de Jope o acompanharam.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 24, 'No outro dia chegaram a Cesaréia. Cornélio os esperava com seus parentes e amigos mais íntimos que tinha convidado.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 25, 'Quando Pedro ia entrando na casa, Cornélio dirigiu-se a ele e prostrou-se aos seus pés, adorando-o.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 26, 'Mas Pedro o fez levantar-se, dizendo: "Levante-se, eu sou homem como você".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 27, 'Conversando com ele, Pedro entrou e encontrou ali reunidas muitas pessoas', 3, CURRENT_TIMESTAMP, false),
(44, 10, 28, 'e lhes disse: "Vocês sabem muito bem que é contra a nossa lei um judeu associar-se a um gentio ou mesmo visitá-lo. Mas Deus me mostrou que eu não deveria chamar impuro ou imundo a homem nenhum.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 29, 'Por isso, quando fui procurado, vim sem qualquer objeção. Posso perguntar por que vocês me mandaram buscar? "', 3, CURRENT_TIMESTAMP, false),
(44, 10, 30, 'Cornélio respondeu: "Há quatro dias eu estava em minha casa orando a esta hora, às três horas da tarde. De repente, colocou-se diante de mim um homem com roupas resplandecentes', 3, CURRENT_TIMESTAMP, false),
(44, 10, 31, 'e disse: ‘Cornélio, Deus ouviu sua oração e lembrou-se de suas esmolas.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 32, 'Mande buscar em Jope a Simão, chamado Pedro. Ele está hospedado na casa de Simão, o curtidor de couro, que mora perto do mar’.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 33, 'Assim, mandei buscar-te imediatamente, e foi bom que tenhas vindo. Agora estamos todos aqui na presença de Deus, para ouvir tudo que o Senhor te mandou dizer-nos".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 34, 'Então Pedro começou a falar: "Agora percebo verdadeiramente que Deus não trata as pessoas com parcialidade,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 35, 'mas de todas as nações aceita todo aquele que o teme e faz o que é justo.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 36, 'Vocês conhecem a mensagem enviada por Deus ao povo de Israel, que fala das boas novas de paz por meio de Jesus Cristo, Senhor de todos.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 37, 'Sabem o que aconteceu em toda a Judéia, começando na Galiléia, depois do batismo que João pregou,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 38, 'como Deus ungiu a Jesus de Nazaré com o Espírito Santo e poder, e como ele andou por toda parte fazendo o bem e curando todos os oprimidos pelo diabo, porque Deus estava com ele.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 39, '"Nós somos testemunhas de tudo o que ele fez na terra dos judeus e em Jerusalém, onde o mataram, suspendendo-o num madeiro.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 40, 'Deus, porém, o ressuscitou no terceiro dia e fez que ele fosse visto,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 41, 'não por todo o povo, mas por testemunhas que designara de antemão, por nós que comemos e bebemos com ele depois que ressuscitou dos mortos.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 42, 'Ele nos mandou pregar ao povo e testemunhar que este é aquele a quem Deus constituiu juiz de vivos e de mortos.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 43, 'Todos os profetas dão testemunho dele, de que todo aquele que nele crê recebe o perdão dos pecados mediante o seu nome".', 3, CURRENT_TIMESTAMP, false),
(44, 10, 44, 'Enquanto Pedro ainda estava falando estas palavras, o Espírito Santo desceu sobre todos os que ouviam a mensagem.', 3, CURRENT_TIMESTAMP, false),
(44, 10, 45, 'Os judeus convertidos que vieram com Pedro ficaram admirados de que o dom do Espírito Santo fosse derramado até sobre os gentios,', 3, CURRENT_TIMESTAMP, false),
(44, 10, 46, 'pois os ouviam falando em línguas e exaltando a Deus. A seguir Pedro disse:', 3, CURRENT_TIMESTAMP, false),
(44, 10, 47, '"Pode alguém negar a água, impedindo que estes sejam batizados? Eles receberam o Espírito Santo como nós! "', 3, CURRENT_TIMESTAMP, false),
(44, 10, 48, 'Então ordenou que fossem batizados em nome de Jesus Cristo. Depois pediram a Pedro que ficasse com eles alguns dias.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 1, 'Os apóstolos e os irmãos de toda a Judéia ouviram falar que os gentios também haviam recebido a palavra de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 2, 'Assim, quando Pedro subiu a Jerusalém, os que eram do partido dos circuncisos o criticavam, dizendo:', 3, CURRENT_TIMESTAMP, false),
(44, 11, 3, '"Você entrou na casa de homens incircuncisos e comeu com eles".', 3, CURRENT_TIMESTAMP, false),
(44, 11, 4, 'Pedro, então, começou a explicar-lhes exatamente como tudo havia acontecido:', 3, CURRENT_TIMESTAMP, false),
(44, 11, 5, '"Eu estava na cidade de Jope orando; caindo em êxtase, tive uma visão. Vi algo parecido com um grande lençol sendo baixado do céu, preso pelas quatro pontas, e que vinha até o lugar onde eu estava.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 6, 'Olhei para dentro dele e notei que havia ali quadrúpedes da terra, animais selvagens, répteis e aves do céu.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 7, 'Então ouvi uma voz que me dizia: ‘Levante-se, Pedro; mate e coma’.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 8, '"Eu respondi: De modo nenhum, Senhor! Nunca entrou em minha boca algo impuro ou imundo.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 9, '"A voz falou do céu segunda vez: ‘Não chame impuro ao que Deus purificou’.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 10, 'Isso aconteceu três vezes, e então tudo foi recolhido ao céu.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 11, '"Na mesma hora chegaram à casa em que eu estava hospedado três homens que me haviam sido enviados de Cesaréia.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 12, 'O Espírito me disse que não hesitasse em ir com eles. Estes seis irmãos também foram comigo, e entramos na casa de um certo homem.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 13, 'Ele nos contou como um anjo lhe tinha aparecido em sua casa e dissera: ‘Mande buscar, em Jope, a Simão, chamado Pedro.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 14, 'Ele lhe trará uma mensagem por meio da qual serão salvos você e todos os da sua casa’.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 15, '"Quando comecei a falar, o Espírito Santo desceu sobre eles como sobre nós no princípio.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 16, 'Então me lembrei do que o Senhor tinha dito: ‘João batizou com água, mas vocês serão batizados com o Espírito Santo’.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 17, 'Se, pois, Deus lhes deu o mesmo dom que nos dera quando cremos no Senhor Jesus Cristo, quem era eu para pensar em opor-me a Deus? "', 3, CURRENT_TIMESTAMP, false),
(44, 11, 18, 'Ouvindo isso, não apresentaram mais objeções e louvaram a Deus, dizendo: "Então, Deus concedeu arrependimento para a vida até mesmo aos gentios! "', 3, CURRENT_TIMESTAMP, false),
(44, 11, 19, 'Os que tinham sido dispersos por causa da perseguição desencadeada com a morte de Estêvão chegaram até à Fenícia, Chipre e Antioquia, anunciando a mensagem apenas aos judeus.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 20, 'Alguns deles, todavia, cipriotas e cireneus, foram a Antioquia e começaram a falar também aos gregos, contando-lhes as boas novas a respeito do Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 21, 'A mão do Senhor estava com eles, e muitos creram e se converteram ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 22, 'Notícias desse fato chegaram aos ouvidos da igreja em Jerusalém, e eles enviaram Barnabé a Antioquia.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 23, 'Este, ali chegando e vendo a graça de Deus, ficou alegre e os animou a permanecerem fiéis ao Senhor, de todo o coração.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 24, 'Ele era um homem bom, cheio do Espírito Santo e de fé; e muitas pessoas foram acrescentadas ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 25, 'Então Barnabé foi a Tarso procurar Saulo', 3, CURRENT_TIMESTAMP, false),
(44, 11, 26, 'e, quando o encontrou, levou-o para Antioquia. Assim, durante um ano inteiro Barnabé e Saulo se reuniram com a igreja e ensinaram a muitos. Em Antioquia, os discípulos foram pela primeira vez chamados cristãos.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 27, 'Naqueles dias alguns profetas desceram de Jerusalém para Antioquia.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 28, 'Um deles, Ágabo, levantou-se e pelo Espírito predisse que uma grande fome sobreviria a todo o mundo romano, o que aconteceu durante o reinado de Cláudio.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 29, 'Os discípulos, cada um segundo as suas possibilidades, decidiram providenciar ajuda para os irmãos que viviam na Judéia.', 3, CURRENT_TIMESTAMP, false),
(44, 11, 30, 'E o fizeram, enviando suas ofertas aos presbíteros pelas mãos de Barnabé e Saulo.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 1, 'Nessa ocasião, o rei Herodes prendeu alguns que pertenciam à igreja, com a intenção de maltratá-los,', 3, CURRENT_TIMESTAMP, false),
(44, 12, 2, 'e mandou matar à espada Tiago, irmão de João.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 3, 'Vendo que isso agradava aos judeus, prosseguiu, prendendo também Pedro, durante a festa dos pães sem fermento.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 4, 'Tendo-o prendido, lançou-o no cárcere, entregando-o para ser guardado por quatro escoltas de quatro soldados cada uma. Herodes pretendia submetê-lo a julgamento público depois da Páscoa.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 5, 'Pedro, então, ficou detido na prisão, mas a igreja orava intensamente a Deus por ele.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 6, 'Na noite anterior ao dia em que Herodes iria submetê-lo a julgamento, Pedro estava dormindo entre dois soldados, preso com duas algemas, e sentinelas montavam guarda à entrada do cárcere.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 7, 'Repentinamente apareceu um anjo do Senhor, e uma luz brilhou na cela. Ele tocou no lado de Pedro e o acordou. "Depressa, levante-se! ", disse ele. Então as algemas caíram dos punhos de Pedro.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 8, 'O anjo lhe disse: "Vista-se e calce as sandálias". E Pedro assim fez. Disse-lhe ainda o anjo: "Ponha a capa e siga-me".', 3, CURRENT_TIMESTAMP, false),
(44, 12, 9, 'E, saindo, Pedro o seguiu, não sabendo que era real o que se fazia por meio do anjo; tudo lhe parecia uma visão.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 10, 'Passaram a primeira e a segunda guarda, e chegaram ao portão de ferro que dava para a cidade. Este se abriu por si mesmo para eles, e passaram. Tendo saído, caminharam ao longo de uma rua, e de repente, o anjo o deixou.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 11, 'Então Pedro caiu em si e disse: "Agora sei, sem nenhuma dúvida, que o Senhor enviou o seu anjo e me libertou das mãos de Herodes e de tudo o que o povo judeu esperava".', 3, CURRENT_TIMESTAMP, false),
(44, 12, 12, 'Percebendo isso, ele se dirigiu à casa de Maria, mãe de João, também chamado Marcos, onde muita gente se havia reunido e estava orando.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 13, 'Pedro bateu à porta do alpendre, e uma serva chamada Rode veio atender.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 14, 'Ao reconhecer a voz de Pedro, tomada de alegria, ela correu de volta, sem abrir a porta, e exclamou: "Pedro está à porta! "', 3, CURRENT_TIMESTAMP, false),
(44, 12, 15, 'Eles porém lhe disseram: "Você está fora de si! " Insistindo ela em afirmar que era Pedro, disseram-lhe: "Deve ser o anjo dele".', 3, CURRENT_TIMESTAMP, false),
(44, 12, 16, 'Mas Pedro continuou batendo e, quando abriram a porta e o viram, ficaram perplexos.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 17, 'Mas ele, fazendo-lhes sinal para que se calassem, descreveu como o Senhor o havia tirado da prisão e disse: "Contem isso a Tiago e aos irmãos". Então saiu e foi para outro lugar.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 18, 'De manhã, não foi pequeno o alvoroço entre os soldados quanto ao que tinha acontecido a Pedro.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 19, 'Fazendo uma busca completa e não o encontrando, Herodes fez uma investigação entre os guardas e ordenou que fossem executados. Depois Herodes foi da Judéia para Cesaréia e permaneceu ali durante algum tempo.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 20, 'Ele estava cheio de ira contra o povo de Tiro e Sidom; contudo, eles haviam se reunido e procuravam ter uma audiência com ele. Tendo conseguido o apoio de Blasto, homem de confiança do rei, pediram paz, porque dependiam das terras do rei para obter alimento.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 21, 'No dia marcado, Herodes, vestindo seus trajes reais, sentou-se em seu trono e fez um discurso ao povo.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 22, 'Eles começaram a gritar: "É voz de deus, e não de homem".', 3, CURRENT_TIMESTAMP, false),
(44, 12, 23, 'Visto que Herodes não glorificou a Deus, imediatamente um anjo do Senhor o feriu; e ele morreu comido por vermes.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 24, 'Entretanto, a palavra de Deus continuava a crescer e a espalhar-se.', 3, CURRENT_TIMESTAMP, false),
(44, 12, 25, 'Tendo terminado sua missão, Barnabé e Saulo voltaram de Jerusalém, levando consigo João, também chamado Marcos.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 1, 'Na igreja de Antioquia havia profetas e mestres: Barnabé, Simeão, chamado Níger, Lúcio de Cirene, Manaém, que fora criado com Herodes, o tetrarca, e Saulo.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 2, 'Enquanto adoravam ao Senhor e jejuavam, disse o Espírito Santo: "Separem-me Barnabé e Saulo para a obra a que os tenho chamado".', 3, CURRENT_TIMESTAMP, false),
(44, 13, 3, 'Assim, depois de jejuar e orar, impuseram-lhes as mãos e os enviaram.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 4, 'Enviados pelo Espírito Santo, desceram a Selêucia e dali navegaram para Chipre.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 5, 'Chegando em Salamina, proclamaram a palavra de Deus nas sinagogas judaicas. João estava com eles como auxiliar.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 6, 'Viajaram por toda a ilha, até que chegaram a Pafos. Ali encontraram um judeu, chamado Barjesus, que praticava magia e era falso profeta.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 7, 'Ele era assessor do procônsul Sérgio Paulo. O procônsul, sendo homem culto, mandou chamar Barnabé e Saulo, porque queria ouvir a palavra de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 8, 'Mas Elimas, o mágico ( esse é o significado do seu nome ) opôs-se a eles e tentava desviar da fé o procônsul.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 9, 'Então Saulo, também chamado Paulo, cheio do Espírito Santo, olhou firmemente para Elimas e disse:', 3, CURRENT_TIMESTAMP, false),
(44, 13, 10, '"Filho do diabo e inimigo de tudo o que é justo! Você está cheio de toda espécie de engano e maldade. Quando é que vai parar de perverter os retos caminhos do Senhor?', 3, CURRENT_TIMESTAMP, false),
(44, 13, 11, 'Saiba agora que a mão do Senhor está contra você, e você ficará cego e incapaz de ver a luz do sol durante algum tempo". Imediatamente vieram sobre ele névoa e escuridão, e ele, tateando, procurava quem o guiasse pela mão.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 12, 'O procônsul, vendo o que havia acontecido, creu, profundamente impressionado com o ensino do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 13, 'De Pafos, Paulo e seus companheiros navegaram para Perge, na Panfília. João os deixou ali e voltou para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 14, 'De Perge prosseguiram até Antioquia da Pisídia. No sábado, entraram na sinagoga e se assentaram.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 15, 'Depois da leitura da Lei e dos Profetas, os chefes da sinagoga lhes mandaram dizer: "Irmãos, se vocês têm uma mensagem de encorajamento para o povo, falem".', 3, CURRENT_TIMESTAMP, false),
(44, 13, 16, 'Pondo-se de pé, Paulo fez sinal com a mão e disse: "Israelitas e gentios que temem a Deus, ouçam-me!', 3, CURRENT_TIMESTAMP, false),
(44, 13, 17, 'O Deus do povo de Israel escolheu nossos antepassados, e exaltou o povo durante a sua permanência no Egito; com grande poder os fez sair daquele país', 3, CURRENT_TIMESTAMP, false),
(44, 13, 18, 'e os aturou no deserto durante cerca de quarenta anos.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 19, 'Ele destruiu sete nações em Canaã e deu a terra delas como herança ao seu povo.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 20, 'Tudo isso levou cerca de quatrocentos e cinqüenta anos. "Depois disso, ele lhes deu juízes até o tempo do profeta Samuel.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 21, 'Então o povo pediu um rei, e Deus lhes deu Saul, filho de Quis, da tribo de Benjamim, que reinou quarenta anos.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 22, 'Depois de rejeitar Saul, levantou-lhes Davi como rei, sobre quem testemunhou: ‘Encontrei Davi, filho de Jessé, homem segundo o meu coração; ele fará tudo o que for da minha vontade’.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 23, '"Da descendência desse homem Deus trouxe a Israel o Salvador Jesus, como prometera.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 24, 'Antes da vinda de Jesus, João pregou um batismo de arrependimento para todo o povo de Israel.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 25, 'Quando estava completando sua carreira, João disse: ‘Quem vocês pensam que eu sou? Não sou quem vocês pensam. Mas eis que vem depois de mim aquele cujas sandálias não sou digno nem de desamarrar’.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 26, '"Irmãos, filhos de Abraão, e gentios que temem a Deus, a nós foi enviada esta mensagem de salvação.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 27, 'O povo de Jerusalém e seus governantes não reconheceram Jesus, mas, ao condená-lo, cumpriram as palavras dos profetas, que são lidas todos os sábados.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 28, 'Mesmo não achando motivo legal para uma sentença de morte, pediram a Pilatos que o mandasse executar.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 29, 'Tendo cumprido tudo o que estava escrito a respeito dele, tiraram-no do madeiro e o colocaram num sepulcro.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 30, 'Mas Deus o ressuscitou dos mortos,', 3, CURRENT_TIMESTAMP, false),
(44, 13, 31, 'e, por muitos dias, foi visto por aqueles que tinham ido com ele da Galiléia para Jerusalém. Eles agora são testemunhas dele para o povo.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 32, '"Nós lhes anunciamos as boas novas: o que Deus prometeu a nossos antepassados', 3, CURRENT_TIMESTAMP, false),
(44, 13, 33, 'ele cumpriu para nós, seus filhos, ressuscitando Jesus, como está escrito no Salmo segundo: ‘Tu és meu filho; eu hoje te gerei’.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 34, 'O fato de que Deus o ressuscitou dos mortos, para que nunca entrasse em decomposição, é declarado nestas palavras: ‘Eu lhes dou as santas e fiéis bênçãos prometidas a Davi’.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 35, 'Assim ele diz noutra passagem: ‘Não permitirás que o teu Santo sofra decomposição’.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 36, '"Tendo, pois, Davi servido ao propósito de Deus em sua geração, adormeceu, foi sepultado com os seus antepassados e seu corpo se decompôs.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 37, 'Mas aquele a quem Deus ressuscitou não sofreu decomposição.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 38, '"Portanto, meus irmãos, quero que saibam que mediante Jesus lhes é proclamado o perdão dos pecados.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 39, 'Por meio dele, todo aquele que crê é justificado de todas as coisas das quais não podiam ser justificados pela lei de Moisés.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 40, 'Cuidem para que não lhes aconteça o que disseram os profetas:', 3, CURRENT_TIMESTAMP, false),
(44, 13, 41, '‘Olhem, escarnecedores, admirem-se e pereçam; pois nos dias de vocês farei algo que vocês jamais creriam se alguém lhes contasse! ’"', 3, CURRENT_TIMESTAMP, false),
(44, 13, 42, 'Quando Paulo e Barnabé estavam saindo da sinagoga, o povo os convidou a falar mais a respeito dessas coisas no sábado seguinte.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 43, 'Despedida a congregação, muitos dos judeus e estrangeiros piedosos convertidos ao judaísmo seguiram Paulo e Barnabé. Estes conversavam com eles, recomendando-lhes que continuassem na graça de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 44, 'No sábado seguinte, quase toda a cidade se reuniu para ouvir a palavra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 45, 'Quando os judeus viram a multidão, ficaram cheios de inveja e, blasfemando, contradiziam o que Paulo estava dizendo.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 46, 'Então Paulo e Barnabé lhes responderam corajosamente: "Era necessário anunciar primeiro a vocês a palavra de Deus; uma vez que a rejeitam e não se julgam dignos da vida eterna, agora nos voltamos para os gentios.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 47, 'Pois assim o Senhor nos ordenou: ‘Eu fiz de você luz para os gentios, para que você leve a salvação até aos confins da terra’ ".', 3, CURRENT_TIMESTAMP, false),
(44, 13, 48, 'Ouvindo isso, os gentios alegraram-se e bendisseram a palavra do Senhor; e creram todos os que haviam sido designados para a vida eterna.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 49, 'A palavra do Senhor se espalhava por toda a região.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 50, 'Mas os judeus incitaram as mulheres piedosas de elevada posição e os principais da cidade. E, provocando perseguição contra Paulo e Barnabé, os expulsaram do seu território.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 51, 'Estes sacudiram o pó dos seus pés em protesto contra eles e foram para Icônio.', 3, CURRENT_TIMESTAMP, false),
(44, 13, 52, 'Os discípulos continuavam cheios de alegria e do Espírito Santo.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 1, 'Em Icônio, Paulo e Barnabé, como de costume, foram à sinagoga judaica. Ali falaram de tal modo que veio a crer grande multidão de judeus e gentios.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 2, 'Mas os judeus que se tinham recusado a crer incitaram os gentios e irritaram-lhes os ânimos contra os irmãos.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 3, 'Paulo e Barnabé passaram bastante tempo ali, falando corajosamente do Senhor, que confirmava a mensagem de sua graça realizando sinais e maravilhas pelas mãos deles.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 4, 'O povo da cidade ficou dividido: alguns estavam a favor dos judeus, outros a favor dos apóstolos.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 5, 'Formou-se uma conspiração de gentios e judeus, juntamente com os seus líderes, para maltratá-los e apedrejá-los.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 6, 'Quando eles souberam disso, fugiram para as cidades licaônicas de Listra e Derbe, e seus arredores,', 3, CURRENT_TIMESTAMP, false),
(44, 14, 7, 'onde continuaram a pregar as boas novas.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 8, 'Em Listra havia um homem paralítico dos pés, aleijado desde o nascimento, que vivia ali sentado e nunca tinha andado.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 9, 'Ele ouvira Paulo falar. Quando Paulo olhou diretamente para ele e viu que o homem tinha fé para ser curado,', 3, CURRENT_TIMESTAMP, false),
(44, 14, 10, 'disse em alta voz: "Levante-se! Fique de pé! " Com isso, o homem deu um salto e começou a andar.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 11, 'Ao ver o que Paulo fizera, a multidão começou a gritar em língua licaônica: "Os deuses desceram até nós em forma humana! "', 3, CURRENT_TIMESTAMP, false),
(44, 14, 12, 'A Barnabé chamavam Zeus e a Paulo Hermes, porque era ele quem trazia a palavra.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 13, 'O sacerdote de Zeus, cujo templo ficava diante da cidade, trouxe bois e coroas de flores à porta da cidade, porque ele e a multidão queriam oferecer-lhes sacrifícios.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 14, 'Ouvindo isso, os apóstolos Barnabé e Paulo rasgaram as roupas e correram para o meio da multidão, gritando:', 3, CURRENT_TIMESTAMP, false),
(44, 14, 15, '"Homens, por que vocês estão fazendo isso? Nós também somos humanos como vocês. Estamos trazendo boas novas para vocês, dizendo-lhes que se afastem dessas coisas vãs e se voltem para o Deus vivo, que fez o céu, a terra, o mar e tudo o que neles há.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 16, 'No passado ele permitiu que todas as nações seguissem os seus próprios caminhos.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 17, 'Contudo, não ficou sem testemunho: mostrou sua bondade, dando-lhes chuva do céu e colheitas no tempo certo, concedendo-lhes sustento com fartura e enchendo de alegria os seus corações".', 3, CURRENT_TIMESTAMP, false),
(44, 14, 18, 'Apesar dessas palavras, eles tiveram dificuldade para impedir que a multidão lhes oferecesse sacrifícios.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 19, 'Então alguns judeus chegaram de Antioquia e de Icônio e mudaram o ânimo das multidões. Apedrejaram Paulo e o arrastaram para fora da cidade, pensando que estivesse morto.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 20, 'Mas quando os discípulos se ajuntaram em volta de Paulo, ele se levantou e voltou à cidade. No dia seguinte, ele e Barnabé partiram para Derbe.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 21, 'Eles pregaram as boas novas naquela cidade e fizeram muitos discípulos. Então voltaram para Listra, Icônio e Antioquia,', 3, CURRENT_TIMESTAMP, false),
(44, 14, 22, 'fortalecendo os discípulos e encorajando-os a permanecer na fé, dizendo: "É necessário que passemos por muitas tribulações para entrarmos no Reino de Deus".', 3, CURRENT_TIMESTAMP, false),
(44, 14, 23, 'Paulo e Barnabé designaram-lhes presbíteros em cada igreja; tendo orado e jejuado, eles os encomendaram ao Senhor, em quem haviam confiado.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 24, 'Passando pela Pisídia, chegaram à Panfília', 3, CURRENT_TIMESTAMP, false),
(44, 14, 25, 'e, tendo pregado a palavra em Perge, desceram para Atália.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 26, 'De Atália navegaram de volta a Antioquia, onde tinham sido recomendados à graça de Deus para a missão que agora haviam completado.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 27, 'Chegando ali, reuniram a igreja e relataram tudo o que Deus tinha feito por meio deles e como abrira a porta da fé aos gentios.', 3, CURRENT_TIMESTAMP, false),
(44, 14, 28, 'E ficaram ali muito tempo com os discípulos.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 1, 'Alguns homens desceram da Judéia para Antioquia e passaram a ensinar aos irmãos: "Se vocês não forem circuncidados conforme o costume ensinado por Moisés, não poderão ser salvos".', 3, CURRENT_TIMESTAMP, false),
(44, 15, 2, 'Isso levou Paulo e Barnabé a uma grande contenda e discussão com eles. Assim, Paulo e Barnabé foram designados, juntamente com outros, para irem a Jerusalém tratar dessa questão com os apóstolos e com os presbíteros.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 3, 'A igreja os enviou e, ao passarem pela Fenícia e por Samaria, contaram como os gentios tinham se convertido; essas notícias alegravam muito a todos os irmãos.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 4, 'Chegando a Jerusalém, foram bem recebidos pela igreja, pelos apóstolos e pelos presbíteros, a quem relataram tudo o que Deus tinha feito por meio deles.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 5, 'Então se levantaram alguns do partido religioso dos fariseus que haviam crido e disseram: "É necessário circuncidá-los e exigir deles que obedeçam à lei de Moisés".', 3, CURRENT_TIMESTAMP, false),
(44, 15, 6, 'Os apóstolos e os presbíteros se reuniram para considerar essa questão.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 7, 'Depois de muita discussão, Pedro levantou-se e dirigiu-se a eles: "Irmãos, vocês sabem que há muito tempo Deus me escolheu dentre vocês para que os gentios ouvissem de meus lábios a mensagem do evangelho e cressem.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 8, 'Deus, que conhece os corações, demonstrou que os aceitou, dando-lhes o Espírito Santo, como antes nos tinha concedido.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 9, 'Ele não fez distinção alguma entre nós e eles, visto que purificou os seus corações pela fé.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 10, 'Então, por que agora vocês estão querendo tentar a Deus, impondo sobre os discípulos um jugo que nem nós nem nossos antepassados conseguimos suportar?', 3, CURRENT_TIMESTAMP, false),
(44, 15, 11, 'De modo nenhum! Cremos que somos salvos pela graça de nosso Senhor Jesus, assim como eles também".', 3, CURRENT_TIMESTAMP, false),
(44, 15, 12, 'Toda a assembléia ficou em silêncio, enquanto ouvia Barnabé e Paulo falando de todos os sinais e maravilhas que, por meio deles, Deus fizera entre os gentios.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 13, 'Quando terminaram de falar, Tiago tomou a palavra e disse: "Irmãos, ouçam-me.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 14, 'Simão nos expôs como Deus, no princípio, voltou-se para os gentios a fim de reunir dentre as nações um povo para o seu nome.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 15, 'Concordam com isso as palavras dos profetas, conforme está escrito:', 3, CURRENT_TIMESTAMP, false),
(44, 15, 16, '‘Depois disso voltarei e reconstruirei a tenda caída de Davi. Reedificarei as suas ruínas, e a restaurarei,', 3, CURRENT_TIMESTAMP, false),
(44, 15, 17, 'para que o restante dos homens busque o Senhor, e todos os gentios sobre os quais tem sido invocado o meu nome, diz o Senhor, que faz estas coisas’', 3, CURRENT_TIMESTAMP, false),
(44, 15, 18, 'conhecidas desde os tempos antigos.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 19, '"Portanto, julgo que não devemos pôr dificuldades aos gentios que estão se convertendo a Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 20, 'Pelo contrário, devemos escrever a eles, dizendo-lhes que se abstenham de comida contaminada pelos ídolos, da imoralidade sexual, da carne de animais estrangulados e do sangue.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 21, 'Pois, desde os tempos antigos, Moisés é pregado em todas as cidades, sendo lido nas sinagogas todos os sábados".', 3, CURRENT_TIMESTAMP, false),
(44, 15, 22, 'Então os apóstolos e os presbíteros, com toda a igreja, decidiram escolher alguns dentre eles e enviá-los a Antioquia com Paulo e Barnabé. Escolheram Judas, chamado Barsabás, e Silas, dois líderes entre os irmãos.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 23, 'Com eles enviaram a seguinte carta: Os irmãos apóstolos e presbíteros, aos cristãos gentios que estão em Antioquia, na Síria e na Cilícia: Saudações.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 24, 'Soubemos que alguns saíram de nosso meio, sem nossa autorização, e os perturbaram, transtornando suas mentes com o que disseram.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 25, 'Assim, concordamos todos em escolher alguns homens e enviá-los a vocês com nossos amados irmãos Paulo e Barnabé,', 3, CURRENT_TIMESTAMP, false),
(44, 15, 26, 'homens que têm arriscado a vida pelo nome de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 27, 'Portanto, estamos enviando Judas e Silas para confirmarem verbalmente o que estamos escrevendo.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 28, 'Pareceu bem ao Espírito Santo e a nós não impor a vocês nada além das seguintes exigências necessárias:', 3, CURRENT_TIMESTAMP, false),
(44, 15, 29, 'Abster-se de comida sacrificada aos ídolos, do sangue, da carne de animais estrangulados e da imoralidade sexual. Vocês farão bem em evitar essas coisas. Que tudo lhes vá bem.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 30, 'Uma vez despedidos, os homens desceram para Antioquia, onde reuniram a igreja e entregaram a carta.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 31, 'Os irmãos a leram e se alegraram com a sua animadora mensagem.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 32, 'Judas e Silas, que eram profetas, encorajaram e fortaleceram os irmãos com muitas palavras.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 33, 'Tendo passado algum tempo ali, foram despedidos pelos irmãos com a bênção da paz para voltarem aos que os tinham enviado.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 34, 'Mas Silas decidiu ficar ali.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 35, 'Mas Paulo e Barnabé permaneceram em Antioquia, onde, com muitos outros ensinavam e pregavam a palavra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 36, 'Algum tempo depois, Paulo disse a Barnabé: "Voltemos para visitar os irmãos em todas as cidades onde pregamos a palavra do Senhor, para ver como estão indo".', 3, CURRENT_TIMESTAMP, false),
(44, 15, 37, 'Barnabé queria levar João, também chamado Marcos.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 38, 'Mas Paulo não achava prudente levá-lo, pois ele, abandonando-os na Panfília, não permanecera com eles no trabalho.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 39, 'Tiveram um desentendimento tão sério que se separaram. Barnabé, levando consigo Marcos, navegou para Chipre,', 3, CURRENT_TIMESTAMP, false),
(44, 15, 40, 'mas Paulo escolheu Silas e partiu, encomendado pelos irmãos à graça do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 15, 41, 'Passou, então, pela Síria e pela Cilícia, fortalecendo as igrejas.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 1, 'Chegou a Derbe e depois a Listra, onde vivia um discípulo chamado Timóteo. Sua mãe era uma judia convertida e seu pai era grego.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 2, 'Os irmãos de Listra e Icônio davam bom testemunho dele.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 3, 'Paulo, querendo levá-lo na viagem, circuncidou-o por causa dos judeus que viviam naquela região, pois todos sabiam que seu pai era grego.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 4, 'Nas cidades por onde passavam, transmitiam as decisões tomadas pelos apóstolos e presbíteros em Jerusalém, para que fossem obedecidas.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 5, 'Assim as igrejas eram fortalecidas na fé e cresciam em número cada dia.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 6, 'Paulo e seus companheiros viajaram pela região da Frígia e da Galácia, tendo sido impedidos pelo Espírito Santo de pregar a palavra na província da Ásia.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 7, 'Quando chegaram à fronteira da Mísia, tentaram entrar na Bitínia, mas o Espírito de Jesus os impediu.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 8, 'Então, contornaram a Mísia e desceram a Trôade.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 9, 'Durante a noite Paulo teve uma visão, na qual um homem da Macedônia estava em pé e lhe suplicava: "Passe à Macedônia e ajude-nos".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 10, 'Depois que Paulo teve essa visão, preparamo-nos imediatamente para partir para a Macedônia, concluindo que Deus nos tinha chamado para lhes pregar o evangelho.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 11, 'Partindo de Trôade, navegamos diretamente para Samotrácia e, no dia seguinte, para Neápolis.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 12, 'Dali partimos para Filipos, na Macedônia, que é colônia romana e a principal cidade daquele distrito. Ali ficamos vários dias.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 13, 'No sábado saímos da cidade e fomos para a beira do rio, onde esperávamos encontrar um lugar de oração. Sentamo-nos e começamos a conversar com as mulheres que se haviam reunido ali.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 14, 'Uma das que ouviam era uma mulher temente a Deus chamada Lídia, vendedora de tecido de púrpura, da cidade de Tiatira. O Senhor abriu seu coração para atender à mensagem de Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 15, 'Tendo sido batizada, bem como os de sua casa, ela nos convidou, dizendo: "Se os senhores me consideram uma crente no Senhor, venham ficar em minha casa". E nos convenceu.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 16, 'Certo dia, indo nós para o lugar de oração, encontramos uma escrava que tinha um espírito pelo qual predizia o futuro. Ela ganhava muito dinheiro para os seus senhores com adivinhações.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 17, 'Essa moça seguia a Paulo e a nós, gritando: "Estes homens são servos do Deus Altíssimo e lhes anunciam o caminho da salvação".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 18, 'Ela continuou fazendo isso por muitos dias. Finalmente, Paulo ficou indignado, voltou-se e disse ao espírito: "Em nome de Jesus Cristo eu lhe ordeno que saia dela! " No mesmo instante o espírito a deixou.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 19, 'Percebendo que a sua esperança de lucro tinha se acabado, os donos da escrava agarraram Paulo e Silas e os arrastaram para a praça principal, diante das autoridades.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 20, 'E, levando-os aos magistrados, disseram: "Estes homens são judeus e estão perturbando a nossa cidade,', 3, CURRENT_TIMESTAMP, false),
(44, 16, 21, 'propagando costumes que a nós, romanos, não é permitido aceitar nem praticar".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 22, 'A multidão ajuntou-se contra Paulo e Silas, e os magistrados ordenaram que se lhes tirassem as roupas e fossem açoitados.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 23, 'Depois de serem severamente açoitados, foram lançados na prisão. O carcereiro recebeu instrução para vigiá-los com cuidado.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 24, 'Tendo recebido tais ordens, ele os lançou no cárcere interior e lhes prendeu os pés no tronco.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 25, 'Por volta da meia-noite, Paulo e Silas estavam orando e cantando hinos a Deus; os outros presos os ouviam.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 26, 'De repente, houve um terremoto tão violento que os alicerces da prisão foram abalados. Imediatamente todas as portas se abriram, e as correntes de todos se soltaram.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 27, 'O carcereiro acordou e, vendo abertas as portas da prisão, desembainhou sua espada para se matar, porque pensava que os presos tivessem fugido.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 28, 'Mas Paulo gritou: "Não faça isso! Estamos todos aqui! "', 3, CURRENT_TIMESTAMP, false),
(44, 16, 29, 'O carcereiro pediu luz, entrou correndo e, trêmulo, prostrou-se diante de Paulo e Silas.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 30, 'Então levou-os para fora e perguntou: "Senhores, que devo fazer para ser salvo? "', 3, CURRENT_TIMESTAMP, false),
(44, 16, 31, 'Eles responderam: "Creia no Senhor Jesus, e serão salvos, você e os de sua casa".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 32, 'E pregaram a palavra de Deus, a ele e a todos os de sua casa.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 33, 'Naquela mesma hora da noite o carcereiro lavou as feridas deles; em seguida, ele e todos os seus foram batizados.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 34, 'Então os levou para a sua casa, serviu-lhes uma refeição e com todos os de sua casa alegrou-se muito por haver crido em Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 35, 'Quando amanheceu, os magistrados mandaram os seus soldados ao carcereiro com esta ordem: "Solte estes homens".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 36, 'O carcereiro disse a Paulo: "Os magistrados deram ordens para que você e Silas sejam libertados. Agora podem sair. Vão em paz".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 37, 'Mas Paulo disse aos soldados: "Sendo nós cidadãos romanos, eles nos açoitaram publicamente sem processo formal e nos lançaram na prisão. E agora querem livrar-se de nós secretamente? Não! Venham eles mesmos e nos libertem".', 3, CURRENT_TIMESTAMP, false),
(44, 16, 38, 'Os soldados relataram isso aos magistrados, os quais, ouvindo que Paulo e Silas eram romanos, ficaram atemorizados.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 39, 'Vieram para se desculpar diante deles e, conduzindo-os para fora da prisão, pediram-lhes que saíssem da cidade.', 3, CURRENT_TIMESTAMP, false),
(44, 16, 40, 'Depois de saírem da prisão, Paulo e Silas foram à casa de Lídia, onde se encontraram com os irmãos e os encorajaram. E então partiram.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 1, 'Tendo passado por Anfípolis e Apolônia, chegaram a Tessalônica, onde havia uma sinagoga judaica.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 2, 'Segundo o seu costume, Paulo foi à sinagoga e por três sábados discutiu com eles com base nas Escrituras,', 3, CURRENT_TIMESTAMP, false),
(44, 17, 3, 'explicando e provando que o Cristo deveria sofrer e ressuscitar dentre os mortos. E dizia: "Este Jesus que lhes proclamo é o Cristo".', 3, CURRENT_TIMESTAMP, false),
(44, 17, 4, 'Alguns dos judeus foram persuadidos e se uniram a Paulo e Silas, bem como muitos gregos tementes a Deus, e não poucas mulheres de alta posição.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 5, 'Mas os judeus ficaram com inveja. Reuniram alguns homens perversos dentre os desocupados e, com a multidão, iniciaram um tumulto na cidade. Invadiram a casa de Jasom, em busca de Paulo e Silas, a fim de trazê-los para o meio da multidão.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 6, 'Contudo, não os achando, arrastaram Jasom e alguns outros irmãos para diante dos oficiais da cidade, gritando: "Esses homens que têm causado alvoroço por todo o mundo, agora chegaram aqui,', 3, CURRENT_TIMESTAMP, false),
(44, 17, 7, 'e Jasom os recebeu em sua casa. Todos eles estão agindo contra os decretos de César, dizendo que existe um outro rei, chamado Jesus".', 3, CURRENT_TIMESTAMP, false),
(44, 17, 8, 'Ouvindo isso, a multidão e os oficiais da cidade ficaram agitados.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 9, 'Então receberam de Jasom e dos outros a fiança estipulada e os soltaram.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 10, 'Logo que anoiteceu, os irmãos enviaram Paulo e Silas para Beréia. Chegando ali, eles foram à sinagoga judaica.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 11, 'Os bereanos eram mais nobres do que os tessalonicenses, pois receberam a mensagem com grande interesse, examinando todos os dias as Escrituras, para ver se tudo era assim mesmo.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 12, 'E creram muitos dentre os judeus, bem como dentre os gregos, um bom número de mulheres de elevada posição e não poucos homens.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 13, 'Quando os judeus de Tessalônica ficaram sabendo que Paulo estava pregando a palavra de Deus em Beréia, dirigiram-se também para lá, agitando e alvoroçando as multidões.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 14, 'Imediatamente os irmãos enviaram Paulo para o litoral, mas Silas e Timóteo permaneceram em Beréia.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 15, 'Os homens que foram com Paulo o levaram até Atenas, partindo depois com instruções para que Silas e Timóteo se juntassem a ele, tão logo fosse possível.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 16, 'Enquanto esperava por eles em Atenas, Paulo ficou profundamente indignado ao ver que a cidade estava cheia de ídolos.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 17, 'Por isso, discutia na sinagoga com judeus e com gregos tementes a Deus, bem como na praça principal, todos os dias, com aqueles que por ali se encontravam.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 18, 'Alguns filósofos epicureus e estóicos começaram a discutir com ele. Alguns perguntavam: "O que está tentando dizer esse tagarela? " Outros diziam: "Parece que ele está anunciando deuses estrangeiros", pois Paulo estava pregando as boas novas a respeito de Jesus e da ressurreição.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 19, 'Então o levaram a uma reunião do Areópago, onde lhe perguntaram: "Podemos saber que novo ensino é esse que você está anunciando?', 3, CURRENT_TIMESTAMP, false),
(44, 17, 20, 'Você está nos apresentando algumas idéias estranhas, e queremos saber o que elas significam".', 3, CURRENT_TIMESTAMP, false),
(44, 17, 21, 'Todos os atenienses e estrangeiros que ali viviam não cuidavam de outra coisa senão falar ou ouvir as últimas novidades.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 22, 'Então Paulo levantou-se na reunião do Areópago e disse: "Atenienses! Vejo que em todos os aspectos vocês são muito religiosos,', 3, CURRENT_TIMESTAMP, false),
(44, 17, 23, 'pois, andando pela cidade, observei cuidadosamente seus objetos de culto e encontrei até um altar com esta inscrição: AO DEUS DESCONHECIDO. Ora, o que vocês adoram, apesar de não conhecerem, eu lhes anuncio.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 24, '"O Deus que fez o mundo e tudo o que nele há é o Senhor do céu e da terra, e não habita em santuários feitos por mãos humanas.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 25, 'Ele não é servido por mãos de homens, como se necessitasse de algo, porque ele mesmo dá a todos a vida, o fôlego e as demais coisas.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 26, 'De um só fez ele todos os povos, para que povoassem toda a terra, tendo determinado os tempos anteriormente estabelecidos e os lugares exatos em que deveriam habitar.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 27, 'Deus fez isso para que os homens o buscassem e talvez, tateando, pudessem encontrá-lo, embora não esteja longe de cada um de nós.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 28, '‘Pois nele vivemos, nos movemos e existimos’, como disseram alguns dos poetas de vocês: ‘Também somos descendência dele’.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 29, '"Assim, visto que somos descendência de Deus, não devemos pensar que a Divindade é semelhante a uma escultura de ouro, prata ou pedra, feita pela arte e imaginação do homem.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 30, 'No passado Deus não levou em conta essa ignorância, mas agora ordena que todos, em todo lugar, se arrependam.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 31, 'Pois estabeleceu um dia em que há de julgar o mundo com justiça, por meio do homem que designou. E deu provas disso a todos, ressuscitando-o dentre os mortos".', 3, CURRENT_TIMESTAMP, false),
(44, 17, 32, 'Quando ouviram sobre a ressurreição dos mortos, alguns deles zombaram, e outros disseram: "A esse respeito nós o ouviremos outra vez".', 3, CURRENT_TIMESTAMP, false),
(44, 17, 33, 'Com isso, Paulo retirou-se do meio deles.', 3, CURRENT_TIMESTAMP, false),
(44, 17, 34, 'Alguns homens juntaram-se a ele e creram. Entre eles estava Dionísio, membro do Areópago, e também uma mulher chamada Dâmaris, e outros com eles.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 1, 'Depois disso Paulo saiu de Atenas e foi para Corinto.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 2, 'Ali, encontrou um judeu chamado Áqüila, natural do Ponto, que havia chegado recentemente da Itália com Priscila, sua mulher, pois Cláudio havia ordenado que todos os judeus saíssem de Roma. Paulo foi vê-los', 3, CURRENT_TIMESTAMP, false),
(44, 18, 3, 'e, uma vez que tinham a mesma profissão, ficou morando e trabalhando com eles, pois eram fabricantes de tendas.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 4, 'Todos os sábados ele debatia na sinagoga, e convencia judeus e gregos.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 5, 'Depois que Silas e Timóteo chegaram da Macedônia, Paulo se dedicou exclusivamente à pregação, testemunhando aos judeus que Jesus era o Cristo.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 6, 'Opondo-se eles e lançando maldições, Paulo sacudiu a roupa e lhes disse: "Caia sobre a cabeça de vocês o seu próprio sangue! Estou livre da minha responsabilidade. De agora em diante irei para os gentios".', 3, CURRENT_TIMESTAMP, false),
(44, 18, 7, 'Então Paulo saiu da sinagoga e foi para a casa de Tício Justo, que era temente a Deus e que morava ao lado da sinagoga.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 8, 'Crispo, chefe da sinagoga, creu no Senhor, ele e toda a sua casa; e dos coríntios que o ouviam, muitos criam e eram batizados.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 9, 'Certa noite o Senhor falou a Paulo em visão: "Não tenha medo, continue falando e não fique calado,', 3, CURRENT_TIMESTAMP, false),
(44, 18, 10, 'pois estou com você, e ninguém vai lhe fazer mal ou feri-lo, porque tenho muita gente nesta cidade".', 3, CURRENT_TIMESTAMP, false),
(44, 18, 11, 'Assim, Paulo ficou ali durante um ano e meio, ensinando-lhes a palavra de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 12, 'Sendo Gálio procônsul da Acaia, os judeus fizeram em conjunto um levante contra Paulo e o levaram ao tribunal, fazendo a seguinte acusação:', 3, CURRENT_TIMESTAMP, false),
(44, 18, 13, '"Este homem está persuadindo o povo a adorar a Deus de maneira contrária à lei".', 3, CURRENT_TIMESTAMP, false),
(44, 18, 14, 'Quando Paulo ia começar a falar, Gálio disse aos judeus: "Se vocês, judeus, estivessem apresentando queixa de algum delito ou crime grave, seria razoável que eu os ouvisse.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 15, 'Mas, visto que se trata de uma questão de palavras e nomes de sua própria lei, resolvam o problema vocês mesmos. Não serei juiz dessas coisas".', 3, CURRENT_TIMESTAMP, false),
(44, 18, 16, 'E mandou expulsá-los do tribunal.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 17, 'Então todos se voltaram contra Sóstenes, o chefe da sinagoga, e o espancaram diante do tribunal. Mas Gálio não demonstrava nenhuma preocupação com isso.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 18, 'Paulo permaneceu em Corinto por algum tempo. Depois despediu-se dos irmãos e navegou para a Síria, acompanhado de Priscila e Áqüila. Antes de embarcar, rapou a cabeça em Cencréia, devido a um voto que havia feito.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 19, 'Chegaram a Éfeso, onde Paulo deixou Priscila e Áqüila. Ele, porém, entrando na sinagoga, começou a debater com os judeus.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 20, 'Pedindo eles que ficasse mais tempo, não cedeu.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 21, 'Mas, ao partir, prometeu: "Voltarei, se for da vontade de Deus". Então, embarcando, partiu de Éfeso.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 22, 'Ao chegar a Cesaréia, subiu até a igreja para saudá-la, e depois desceu para Antioquia.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 23, 'Depois de passar algum tempo em Antioquia, Paulo partiu dali e viajou por toda a região da Galácia e da Frígia, fortalecendo todos os discípulos.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 24, 'Enquanto isso, um judeu chamado Apolo, natural de Alexandria, chegou a Éfeso. Ele era homem culto e tinha grande conhecimento das Escrituras.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 25, 'Fora instruído no caminho do Senhor e com grande fervor falava e ensinava com exatidão acerca de Jesus, embora conhecesse apenas o batismo de João.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 26, 'Logo começou a falar corajosamente na sinagoga. Quando Priscila e Áqüila o ouviram, convidaram-no para ir à sua casa e lhe explicaram com mais exatidão o caminho de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 18, 27, 'Querendo ele ir para a Acaia, os irmãos o encorajaram e escreveram aos discípulos que o recebessem. Ao chegar, ele auxiliou muito os que pela graça haviam crido,', 3, CURRENT_TIMESTAMP, false),
(44, 18, 28, 'pois refutava vigorosamente os judeus em debate público, provando pelas Escrituras que Jesus é o Cristo.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 1, 'Enquanto Apolo estava em Corinto, Paulo, atravessando as regiões altas, chegou a Éfeso. Ali encontrou alguns discípulos', 3, CURRENT_TIMESTAMP, false),
(44, 19, 2, 'e lhes perguntou: "Vocês receberam o Espírito Santo quando creram? " Eles responderam: "Não, nem sequer ouvimos que existe o Espírito Santo".', 3, CURRENT_TIMESTAMP, false),
(44, 19, 3, '"Então, que batismo vocês receberam? ", perguntou Paulo. "O batismo de João", responderam eles.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 4, 'Disse Paulo: "O batismo de João foi um batismo de arrependimento. Ele dizia ao povo que cresse naquele que viria depois dele, isto é, em Jesus".', 3, CURRENT_TIMESTAMP, false),
(44, 19, 5, 'Ouvindo isso, eles foram batizados no nome do Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 6, 'Quando Paulo lhes impôs as mãos, veio sobre eles o Espírito Santo, e começaram a falar em línguas e a profetizar.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 7, 'Eram ao todo uns doze homens.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 8, 'Paulo entrou na sinagoga e ali falou com liberdade durante três meses, argumentando convincentemente acerca do Reino de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 9, 'Mas alguns deles se endureceram e se recusaram a crer, e começaram a falar mal do Caminho diante da multidão. Paulo, então, afastou-se deles. Tomando consigo os discípulos, passou a ensinar diariamente na escola de Tirano.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 10, 'Isso continuou por dois anos, de forma que todos os judeus e os gregos que viviam na província da Ásia ouviram a palavra do Senhor.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 11, 'Deus fazia milagres extraordinários por meio de Paulo,', 3, CURRENT_TIMESTAMP, false),
(44, 19, 12, 'de modo que até lenços e aventais que Paulo usava eram levados e colocados sobre os enfermos. Estes eram curados de suas doenças, e os espíritos malignos saíam deles.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 13, 'Alguns judeus que andavam expulsando espíritos malignos tentaram invocar o nome do Senhor Jesus sobre os endemoninhados, dizendo: "Em nome de Jesus, a quem Paulo prega, eu lhes ordeno que saiam! "', 3, CURRENT_TIMESTAMP, false),
(44, 19, 14, 'Os que estavam fazendo isso eram os sete filhos de Ceva, um dos chefes dos sacerdotes dos judeus.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 15, 'Um dia, o espírito maligno lhes respondeu: "Jesus, eu conheço, Paulo, eu sei quem é; mas vocês, quem são? "', 3, CURRENT_TIMESTAMP, false),
(44, 19, 16, 'Então o endemoninhado saltou sobre eles e os dominou, espancando-os com tamanha violência que eles fugiram da casa nus e feridos.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 17, 'Quando isso se tornou conhecido de todos os judeus e os gregos que viviam em Éfeso, todos eles foram tomados de temor; e o nome do Senhor Jesus era engrandecido.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 18, 'Muitos dos que creram vinham, e confessavam e declaravam abertamente suas más obras.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 19, 'Grande número dos que tinham praticado ocultismo reuniram seus livros e os queimaram publicamente. Calculado o valor total, este chegou a cinqüenta mil dracmas.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 20, 'Dessa maneira a palavra do Senhor muito se difundia e se fortalecia.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 21, 'Depois dessas coisas, Paulo decidiu no espírito ir a Jerusalém, passando pela Macedônia e pela Acaia. Ele dizia: "Depois de haver estado ali, é necessário também que eu vá visitar Roma".', 3, CURRENT_TIMESTAMP, false),
(44, 19, 22, 'Então enviou à Macedônia dois dos seus auxiliares, Timóteo e Erasto, e permaneceu mais um pouco na província da Ásia.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 23, 'Naquele tempo houve um grande tumulto por causa do Caminho.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 24, 'Um ourives chamado Demétrio, que fazia miniaturas de prata do templo de Ártemis e que dava muito lucro aos artífices,', 3, CURRENT_TIMESTAMP, false),
(44, 19, 25, 'reuniu-os juntamente com os trabalhadores dessa profissão e disse: "Senhores, vocês sabem que temos uma boa fonte de lucro nesta atividade', 3, CURRENT_TIMESTAMP, false),
(44, 19, 26, 'e estão vendo e ouvindo como este indivíduo, Paulo, está convencendo e desviando grande número de pessoas aqui em Éfeso e em quase toda a província da Ásia. Diz ele que deuses feitos por mãos humanas não são deuses.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 27, 'Não somente há o perigo de nossa profissão perder sua reputação, mas também de o templo da grande deusa Ártemis cair em descrédito e de a própria deusa, adorada em toda a província da Ásia e em todo o mundo, ser destituída de sua majestade divina".', 3, CURRENT_TIMESTAMP, false),
(44, 19, 28, 'Ao ouvirem isso, eles ficaram furiosos e começaram a gritar: "Grande é a Ártemis dos efésios! "', 3, CURRENT_TIMESTAMP, false),
(44, 19, 29, 'Em pouco tempo a cidade toda estava em tumulto. O povo foi às pressas para o teatro, arrastando os companheiros de viagem de Paulo, os macedônios Gaio e Aristarco.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 30, 'Paulo queria apresentar-se à multidão, mas os discípulos não o permitiram.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 31, 'Alguns amigos de Paulo dentre as autoridades da província chegaram a mandar-lhe um recado, pedindo-lhe que não se arriscasse a ir ao teatro.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 32, 'A assembléia estava em confusão: uns gritavam uma coisa, outros gritavam outra. A maior parte do povo nem sabia por que estava ali.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 33, 'Alguns da multidão julgaram que Alexandre era a causa do tumulto, quando os judeus o empurraram para frente. Ele fez sinal pedindo silêncio, com a intenção de fazer sua defesa diante do povo.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 34, 'Mas quando ficaram sabendo que ele era judeu, todos gritaram a uma só voz durante cerca de duas horas: "Grande é a Ártemis dos efésios! "', 3, CURRENT_TIMESTAMP, false),
(44, 19, 35, 'O escrivão da cidade acalmou a multidão e disse: "Efésios, quem não sabe que a cidade de Éfeso é a guardiã do templo da grande Ártemis e da sua imagem que caiu do céu?', 3, CURRENT_TIMESTAMP, false),
(44, 19, 36, 'Portanto, visto que estes fatos são inegáveis, acalmem-se e não façam nada precipitadamente.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 37, 'Vocês trouxeram estes homens aqui, embora eles não tenham roubado templos nem blasfemado contra a nossa deusa.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 38, 'Se Demétrio e seus companheiros de profissão têm alguma queixa contra alguém, os tribunais estão abertos, e há procônsules. Eles que apresentem suas queixas ali.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 39, 'Se há mais alguma coisa que vocês desejam apresentar, isso será decidido em assembléia, conforme a lei.', 3, CURRENT_TIMESTAMP, false),
(44, 19, 40, 'Da maneira como está, corremos o perigo de sermos acusados de perturbar a ordem pública por causa dos acontecimentos de hoje. Nesse caso, não seríamos capazes de justificar este tumulto, visto que não há razão para tal".', 3, CURRENT_TIMESTAMP, false),
(44, 19, 41, 'E, tendo dito isso, encerrou a assembléia.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 1, 'Cessado o tumulto, Paulo mandou chamar os discípulos e, depois de encorajá-los, despediu-se e partiu para a Macedônia.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 2, 'Viajou por aquela região, encorajando os irmãos com muitas palavras e, por fim, chegou à Grécia,', 3, CURRENT_TIMESTAMP, false),
(44, 20, 3, 'onde ficou três meses. Quando estava a ponto de embarcar para a Síria, os judeus fizeram uma conspiração contra ele; por isso decidiu voltar pela Macedônia,', 3, CURRENT_TIMESTAMP, false),
(44, 20, 4, 'sendo acompanhado por Sópatro, filho de Pirro, de Beréia; Aristarco e Secundo, de Tessalônica; Gaio, de Derbe; e Timóteo, além de Tíquico e Trófimo, da província da Ásia.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 5, 'Esses homens foram adiante e nos esperaram em Trôade.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 6, 'Navegamos de Filipos, após a festa dos pães sem fermento, e cinco dias depois nos reunimos com os outros em Trôade, onde ficamos sete dias.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 7, 'No primeiro dia da semana reunimo-nos para partir o pão, e Paulo falou ao povo. Pretendendo partir no dia seguinte, continuou falando até à meia-noite.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 8, 'Havia muitas candeias no piso superior onde estávamos reunidos.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 9, 'Um jovem chamado Êutico, que estava sentado numa janela, adormeceu profundamente durante o longo discurso de Paulo. Vencido pelo sono, caiu do terceiro andar. Quando o levantaram, estava morto.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 10, 'Paulo desceu, inclinou-se sobre o rapaz e o abraçou, dizendo: "Não fiquem alarmados! Ele está vivo! "', 3, CURRENT_TIMESTAMP, false),
(44, 20, 11, 'Então subiu novamente, partiu o pão e comeu. Depois, continuou a falar até o amanhecer e foi embora.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 12, 'Levaram vivo o jovem, o que muito os consolou.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 13, 'Quanto a nós, fomos até o navio e embarcamos para Assôs, onde iríamos receber Paulo a bordo. Assim ele tinha determinado, tendo preferido ir a pé.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 14, 'Quando nos encontrou em Assôs, nós o recebemos a bordo e prosseguimos até Mitilene.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 15, 'No dia seguinte navegamos dali e chegamos defronte de Quio; no outro dia atravessamos para Samos e, um dia depois, chegamos a Mileto.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 16, 'Paulo tinha decidido não aportar em Éfeso, para não se demorar na província da Ásia, pois estava com pressa de chegar a Jerusalém, se possível antes do dia de Pentecoste.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 17, 'De Mileto, Paulo mandou chamar os presbíteros da igreja de Éfeso.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 18, 'Quando chegaram, ele lhes disse: "Vocês sabem como vivi todo o tempo em que estive com vocês, desde o primeiro dia em que cheguei à província da Ásia.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 19, 'Servi ao Senhor com toda a humildade e com lágrimas, sendo severamente provado pelas conspirações dos judeus.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 20, 'Vocês sabem que não deixei de pregar-lhes nada que fosse proveitoso, mas ensinei-lhes tudo publicamente e de casa em casa.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 21, 'Testifiquei, tanto a judeus como a gregos, que eles precisam converter-se a Deus com arrependimento e fé em nosso Senhor Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 22, '"Agora, compelido pelo Espírito, estou indo para Jerusalém, sem saber o que me acontecerá ali,', 3, CURRENT_TIMESTAMP, false),
(44, 20, 23, 'senão que, em todas as cidades, o Espírito Santo me avisa que prisões e sofrimentos me esperam.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 24, 'Todavia, não me importo, nem considero a minha vida de valor algum para mim mesmo, se tão-somente puder terminar a corrida e completar o ministério que o Senhor Jesus me confiou, de testemunhar do evangelho da graça de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 25, '"Agora sei que nenhum de vocês, entre os quais passei pregando o Reino, verá novamente a minha face.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 26, 'Portanto, eu lhes declaro hoje que estou inocente do sangue de todos.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 27, 'Pois não deixei de proclamar-lhes toda a vontade de Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 28, 'Cuidem de vocês mesmos e de todo o rebanho sobre o qual o Espírito Santo os colocou como bispos, para pastorearem a igreja de Deus, que ele comprou com o seu próprio sangue.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 29, 'Sei que, depois da minha partida, lobos ferozes penetrarão no meio de vocês e não pouparão o rebanho.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 30, 'E dentre vocês mesmos se levantarão homens que torcerão a verdade, a fim de atrair os discípulos.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 31, 'Por isso, vigiem! Lembrem-se de que durante três anos jamais cessei de advertir a cada um de vocês disso, noite e dia, com lágrimas.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 32, '"Agora, eu os entrego a Deus e à palavra da sua graça, que pode edificá-los e dar-lhes herança entre todos os que são santificados.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 33, 'Não cobicei a prata nem o ouro nem as roupas de ninguém.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 34, 'Vocês mesmos sabem que estas minhas mãos supriram minhas necessidades e as de meus companheiros.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 35, 'Em tudo o que fiz, mostrei-lhes que mediante trabalho árduo devemos ajudar os fracos, lembrando as palavras do próprio Senhor Jesus, que disse: ‘Há maior felicidade em dar do que em receber’ ".', 3, CURRENT_TIMESTAMP, false),
(44, 20, 36, 'Tendo dito isso, ajoelhou-se com todos eles e orou.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 37, 'Todos choraram muito e, abraçando-o, o beijavam.', 3, CURRENT_TIMESTAMP, false),
(44, 20, 38, 'O que mais os entristeceu foi a declaração de que nunca mais veriam a sua face. Então o acompanharam até o navio.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 1, 'Depois de nos separarmos deles, embarcamos e navegamos diretamente para Cós. No dia seguinte fomos para Rodes, e dali até Pátara.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 2, 'Encontrando um navio que ia fazer a travessia para a Fenícia, embarcamos nele e partimos.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 3, 'Depois de avistarmos Chipre e seguirmos rumo sul, navegamos para a Síria. Desembarcamos em Tiro, onde o nosso navio deveria deixar sua carga.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 4, 'Encontrando os discípulos dali, ficamos com eles sete dias. Eles, pelo Espírito, recomendavam a Paulo que não fosse a Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 5, 'Mas quando terminou o nosso tempo ali, partimos e continuamos nossa viagem. Todos os discípulos, com suas mulheres e filhos, nos acompanharam até fora da cidade, e ali na praia nos ajoelhamos e oramos.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 6, 'Depois de nos despedirmos, embarcamos, e eles voltaram para casa.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 7, 'Demos prosseguimento à nossa viagem partindo de Tiro, e aportamos em Ptolemaida, onde saudamos os irmãos e passamos um dia com eles.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 8, 'Partindo no dia seguinte, chegamos a Cesaréia e ficamos na casa de Filipe, o evangelista, um dos sete.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 9, 'Ele tinha quatro filhas virgens, que profetizavam.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 10, 'Depois de passarmos ali vários dias, desceu da Judéia um profeta chamado Ágabo.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 11, 'Vindo ao nosso encontro, tomou o cinto de Paulo e, amarrando as suas próprias mãos e pés, disse: "Assim diz o Espírito Santo: ‘Desta maneira os judeus amarrarão o dono deste cinto em Jerusalém e o entregarão aos gentios’ ".', 3, CURRENT_TIMESTAMP, false),
(44, 21, 12, 'Quando ouvimos isso, nós e o povo dali rogamos a Paulo que não subisse para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 13, 'Então Paulo respondeu: "Por que vocês estão chorando e partindo o meu coração? Estou pronto não apenas para ser amarrado, mas também para morrer em Jerusalém pelo nome do Senhor Jesus".', 3, CURRENT_TIMESTAMP, false),
(44, 21, 14, 'Como não pudemos dissuadi-lo, desistimos e dissemos: "Seja feita a vontade do Senhor".', 3, CURRENT_TIMESTAMP, false),
(44, 21, 15, 'Depois disso, preparamo-nos e subimos para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 16, 'Alguns dos discípulos de Cesaréia nos acompanharam e nos levaram à casa de Mnasom, onde devíamos ficar. Ele era natural de Chipre e um dos primeiros discípulos.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 17, 'Quando chegamos em Jerusalém, os irmãos nos receberam com alegria.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 18, 'No dia seguinte Paulo foi conosco encontrar-se com Tiago, e todos os presbíteros estavam presentes.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 19, 'Paulo os saudou e relatou minuciosamente o que Deus havia feito entre os gentios por meio do seu ministério.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 20, 'Ouvindo isso, eles louvaram a Deus e disseram a Paulo: "Veja, irmão, quantos milhares de judeus creram, e todos eles são zelosos da lei.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 21, 'Eles foram informados de que você ensina todos os judeus que vivem entre os gentios a se afastarem de Moisés, dizendo-lhes que não circuncidem seus filhos nem vivam de acordo com os nossos costumes.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 22, 'Que faremos? Certamente eles saberão que você chegou;', 3, CURRENT_TIMESTAMP, false),
(44, 21, 23, 'portanto, faça o que lhe dizemos. Estão conosco quatro homens que fizeram um voto.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 24, 'Participe com esses homens dos rituais de purificação e pague as despesas deles, para que rapem a cabeça. Então todos saberão que não é verdade o que falam de você, mas que você continua vivendo em obediência à lei.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 25, 'Quanto aos gentios convertidos, já lhes escrevemos a nossa decisão de que eles devem abster-se de comida sacrificada aos ídolos, do sangue, da carne de animais estrangulados e da imoralidade sexual".', 3, CURRENT_TIMESTAMP, false),
(44, 21, 26, 'No dia seguinte Paulo tomou aqueles homens e purificou-se juntamente com eles. Depois foi ao templo para declarar o prazo do cumprimento dos dias da purificação e da oferta que seria feita individualmente em favor deles.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 27, 'Quando já estavam para terminar os sete dias, alguns judeus da Província da Ásia, vendo Paulo no templo, agitaram toda a multidão e o agarraram,', 3, CURRENT_TIMESTAMP, false),
(44, 21, 28, 'gritando: "Israelitas, ajudem-nos! Este é o homem que ensina a todos em toda parte contra o nosso povo, contra a nossa lei e contra este lugar. Além disso, ele fez entrar gregos no templo e profanou este santo lugar".', 3, CURRENT_TIMESTAMP, false),
(44, 21, 29, 'Anteriormente eles haviam visto o efésio Trófimo na cidade com Paulo e julgaram que Paulo o tinha introduzido no templo.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 30, 'Toda a cidade ficou alvoroçada, e juntou-se uma multidão. Agarrando Paulo, arrastaram-no para fora do templo, e imediatamente as portas foram fechadas.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 31, 'Tentando eles matá-lo, chegaram notícias ao comandante das tropas romanas de que toda a cidade de Jerusalém estava em tumulto.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 32, 'Ele reuniu imediatamente alguns oficiais e soldados, e com eles correu para o meio da multidão. Quando viram o comandante e os seus soldados, pararam de espancar Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 33, 'O comandante chegou, prendeu-o e ordenou que ele fosse amarrado com duas correntes. Então perguntou quem era ele e o que tinha feito.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 34, 'Alguns da multidão gritavam uma coisa, outros gritavam outra; não conseguindo saber ao certo o que havia acontecido, por causa do tumulto, o comandante ordenou que Paulo fosse levado para a fortaleza.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 35, 'Quando chegou às escadas, a violência do povo era tão grande que ele precisou ser carregado pelos soldados.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 36, 'A multidão que o seguia continuava gritando: "Acaba com ele! "', 3, CURRENT_TIMESTAMP, false),
(44, 21, 37, 'Quando os soldados estavam para introduzir Paulo na fortaleza, ele perguntou ao comandante: "Posso dizer-te algo? " "Você fala grego? ", perguntou ele.', 3, CURRENT_TIMESTAMP, false),
(44, 21, 38, '"Não é você o egípcio que iniciou uma revolta e há algum tempo levou quatro mil assassinos para o deserto? "', 3, CURRENT_TIMESTAMP, false),
(44, 21, 39, 'Paulo respondeu: "Sou judeu, cidadão de Tarso, cidade importante da Cilícia. Permite-me falar ao povo".', 3, CURRENT_TIMESTAMP, false),
(44, 21, 40, 'Tendo recebido permissão do comandante, Paulo levantou-se na escadaria e fez sinal à multidão. Quando todos fizeram silêncio, dirigiu-se a eles em aramaico:', 3, CURRENT_TIMESTAMP, false),
(44, 22, 1, '"Irmãos e pais, ouçam agora a minha defesa".', 3, CURRENT_TIMESTAMP, false),
(44, 22, 2, 'Quando ouviram que lhes falava em aramaico, ficaram em absoluto silêncio. Então Paulo disse:', 3, CURRENT_TIMESTAMP, false),
(44, 22, 3, '"Sou judeu, nascido em Tarso da Cilícia, mas criado nesta cidade. Fui instruído rigorosamente por Gamaliel na lei de nossos antepassados, sendo tão zeloso por Deus quanto qualquer de vocês hoje.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 4, 'Persegui os seguidores deste Caminho até a morte, prendendo tanto homens como mulheres e lançando-os na prisão,', 3, CURRENT_TIMESTAMP, false),
(44, 22, 5, 'como o podem testemunhar o sumo sacerdote e todo o Conselho, de quem cheguei a obter cartas para seus irmãos em Damasco e fui até lá, a fim de trazer essas pessoas a Jerusalém como prisioneiras, para serem punidas.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 6, '"Por volta do meio-dia, eu me aproximava de Damasco, quando de repente uma forte luz vinda do céu brilhou ao meu redor.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 7, 'Caí por terra e ouvi uma voz que me dizia: ‘Saulo, Saulo! por que você está me perseguindo? ’', 3, CURRENT_TIMESTAMP, false),
(44, 22, 8, 'Então perguntei: Quem és tu, Senhor? E ele respondeu: ‘Eu sou Jesus, o Nazareno, a quem você persegue’.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 9, 'Os que me acompanhavam viram a luz, mas não entenderam a voz daquele que falava comigo.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 10, '"Assim perguntei: Que devo fazer, Senhor? Disse o Senhor: ‘Levante-se, entre em Damasco, onde lhe será dito o que você deve fazer’.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 11, 'Os que estavam comigo me levaram pela mão até Damasco, porque o resplendor da luz me deixara cego.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 12, '"Um homem chamado Ananias, piedoso segundo a lei e muito respeitado por todos os judeus que ali viviam,', 3, CURRENT_TIMESTAMP, false),
(44, 22, 13, 'veio ver-me e, pondo-se junto a mim, disse: ‘Irmão Saulo, recupere a visão’. Naquele mesmo instante pude vê-lo.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 14, '"Então ele disse: ‘O Deus dos nossos antepassados o escolheu para conhecer a sua vontade, ver o Justo e ouvir as palavras de sua boca.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 15, 'Você será testemunha dele a todos os homens, daquilo que viu e ouviu.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 16, 'E agora, que está esperando? Levante-se, seja batizado e lave os seus pecados, invocando o nome dele’.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 17, '"Quando voltei a Jerusalém, estando eu a orar no templo, caí em êxtase e', 3, CURRENT_TIMESTAMP, false),
(44, 22, 18, 'vi o Senhor que me dizia: ‘Depressa! Saia de Jerusalém imediatamente, pois não aceitarão seu testemunho a meu respeito’.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 19, '"Eu respondi: Senhor, estes homens sabem que eu ia de uma sinagoga a outra, a fim de prender e açoitar os que crêem em ti.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 20, 'E quando foi derramado o sangue de tua testemunha Estêvão, eu estava lá, dando minha aprovação e cuidando das roupas dos que o matavam.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 21, '"Então o Senhor me disse: ‘Vá, eu o enviarei para longe, aos gentios’ ".', 3, CURRENT_TIMESTAMP, false),
(44, 22, 22, 'A multidão ouvia Paulo até que ele disse isso. Então todos levantaram a voz e gritaram: "Tira esse homem da face da terra! Ele não merece viver! "', 3, CURRENT_TIMESTAMP, false),
(44, 22, 23, 'Estando eles gritando, tirando suas capas e lançando poeira para o ar,', 3, CURRENT_TIMESTAMP, false),
(44, 22, 24, 'o comandante ordenou que Paulo fosse levado à fortaleza e fosse açoitado e interrogado, para saber por que o povo gritava daquela forma contra ele.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 25, 'Enquanto o amarravam a fim de açoitá-lo, Paulo disse ao centurião que ali estava: "Vocês têm o direito de açoitar um cidadão romano sem que ele tenha sido condenado? "', 3, CURRENT_TIMESTAMP, false),
(44, 22, 26, 'Ao ouvir isso, o centurião foi prevenir o comandante: "Que vais fazer? Este homem é cidadão romano".', 3, CURRENT_TIMESTAMP, false),
(44, 22, 27, 'O comandante dirigiu-se a Paulo e perguntou: "Diga-me, você é cidadão romano? " Ele respondeu: "Sim, sou".', 3, CURRENT_TIMESTAMP, false),
(44, 22, 28, 'Então o comandante disse: "Eu precisei pagar um elevado preço por minha cidadania". Respondeu Paulo: "Eu a tenho por direito de nascimento".', 3, CURRENT_TIMESTAMP, false),
(44, 22, 29, 'Os que iam interrogá-lo retiraram-se imediatamente. O próprio comandante ficou alarmado, ao saber que havia prendido um cidadão romano.', 3, CURRENT_TIMESTAMP, false),
(44, 22, 30, 'No dia seguinte, visto que o comandante queria descobrir exatamente por que Paulo estava sendo acusado pelos judeus, libertou-o e ordenou que se reunissem os chefes dos sacerdotes e todo o Sinédrio. Então, trazendo Paulo, apresentou-o a eles.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 1, 'Paulo, fixando os olhos no Sinédrio, disse: "Meus irmãos, tenho cumprido meu dever para com Deus com toda a boa consciência, até o dia de hoje".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 2, 'Diante disso o sumo sacerdote Ananias deu ordens aos que estavam perto de Paulo para que lhe batessem na boca.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 3, 'Então Paulo lhe disse: "Deus te ferirá, parede branqueada! Estás aí sentado para me julgar conforme a lei, mas contra a lei me mandas ferir? "', 3, CURRENT_TIMESTAMP, false),
(44, 23, 4, 'Os que estavam perto de Paulo disseram: "Você ousa insultar o sumo sacerdote de Deus? "', 3, CURRENT_TIMESTAMP, false),
(44, 23, 5, 'Paulo respondeu: "Irmãos, eu não sabia que ele era o sumo sacerdote, pois está escrito: ‘Não fale mal de uma autoridade do seu povo’ ".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 6, 'Então Paulo, sabendo que alguns deles eram saduceus e os outros fariseus, bradou no Sinédrio: "Irmãos, sou fariseu, filho de fariseu. Estou sendo julgado por causa da minha esperança na ressurreição dos mortos! "', 3, CURRENT_TIMESTAMP, false),
(44, 23, 7, 'Dizendo isso, surgiu uma violenta discussão entre os fariseus e os saduceus, e a assembléia ficou dividida.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 8, '( Os saduceus dizem que não há ressurreição nem anjos nem espíritos, mas os fariseus admitem todas essas coisas. )', 3, CURRENT_TIMESTAMP, false),
(44, 23, 9, 'Houve um grande alvoroço, e alguns dos mestres da lei que eram fariseus se levantaram e começaram a discutir intensamente, dizendo: "Não encontramos nada de errado neste homem. Quem sabe se algum espírito ou anjo falou com ele? "', 3, CURRENT_TIMESTAMP, false),
(44, 23, 10, 'A discussão tornou-se tão violenta que o comandante teve medo que Paulo fosse despedaçado por eles. Então ordenou que as tropas descessem e o retirassem à força do meio deles, levando-o para a fortaleza.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 11, 'Na noite seguinte o Senhor, pondo-se ao lado dele, disse: "Coragem! Assim como você testemunhou a meu respeito em Jerusalém, deverá testemunhar também em Roma".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 12, 'Na manhã seguinte os judeus tramaram uma conspiração e juraram solenemente que não comeriam nem beberiam enquanto não matassem Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 13, 'Mais de quarenta homens estavam envolvidos nessa conspiração.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 14, 'E, dirigindo-se aos chefes dos sacerdotes e aos líderes dos judeus, disseram: "Juramos solenemente, sob maldição, que não comeremos nada enquanto não matarmos Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 15, 'Agora, portanto, vocês e o Sinédrio peçam ao comandante que o faça comparecer diante de vocês com o pretexto de obter informações mais exatas sobre o seu caso. Estaremos prontos para matá-lo antes que ele chegue aqui".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 16, 'Entretanto, o sobrinho de Paulo, filho de sua irmã, teve conhecimento dessa conspiração, foi à fortaleza e contou tudo a Paulo,', 3, CURRENT_TIMESTAMP, false),
(44, 23, 17, 'que, chamando um dos centuriões, disse: "Leve este rapaz ao comandante; ele tem algo para lhe dizer".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 18, 'Assim ele o levou ao comandante. Então disse o centurião: "Paulo, o prisioneiro, chamou-me, pediu-me que te trouxesse este rapaz, pois ele tem algo para te falar".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 19, 'O comandante tomou o rapaz pela mão, levou-o à parte e perguntou: "Que você tem para me dizer? "', 3, CURRENT_TIMESTAMP, false),
(44, 23, 20, 'Ele respondeu: "Os judeus planejaram pedir-te que apresentes Paulo ao Sinédrio amanhã, sob pretexto de buscar informações mais exatas a respeito dele.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 21, 'Não te deixes convencer, pois mais de quarenta deles estão preparando uma emboscada contra Paulo. Eles juraram solenemente não comer nem beber enquanto não o matarem. Estão preparados agora, esperando que prometas atender-lhes o pedido".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 22, 'O comandante despediu o rapaz e recomendou-lhe: "Não diga a ninguém que você me contou isso".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 23, 'Então ele chamou dois de seus centuriões e ordenou-lhes: "Preparem um destacamento de duzentos soldados, setenta cavaleiros e duzentos lanceiros a fim de irem para Cesaréia esta noite, às nove horas da noite.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 24, 'Providenciem montarias para Paulo, e levem-no em segurança ao governador Félix".', 3, CURRENT_TIMESTAMP, false),
(44, 23, 25, 'O comandante escreveu uma carta nestes termos:', 3, CURRENT_TIMESTAMP, false),
(44, 23, 26, 'Cláudio Lísias, ao Excelentíssimo Governador Félix, Saudações.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 27, 'Este homem foi preso pelos judeus, que estavam prestes a matá-lo quando eu, chegando com minhas tropas, o resgatei, pois soube que ele é cidadão romano.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 28, 'Querendo saber por que o estavam acusando, levei-o ao Sinédrio deles.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 29, 'Descobri que ele estava sendo acusado em questões acerca da lei deles, mas não havia contra ele nenhuma acusação que merecesse morte ou prisão.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 30, 'Quando fui informado de que estava sendo preparada uma cilada contra ele, enviei-o imediatamente a Vossa Excelência. Também ordenei que os seus acusadores apresentassem a Vossa Excelência aquilo que têm contra ele.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 31, 'Os soldados, cumprindo o seu dever, levaram Paulo durante a noite, e chegaram a Antipátride.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 32, 'No dia seguinte deixaram a cavalaria prosseguir com ele, e voltaram para a fortaleza.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 33, 'Quando a cavalaria chegou a Cesaréia, deu a carta ao governador e lhe entregou Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 23, 34, 'O governador leu a carta e perguntou de que província era ele. Informado de que era da Cilícia,', 3, CURRENT_TIMESTAMP, false),
(44, 23, 35, 'disse: "Ouvirei seu caso quando os seus acusadores chegarem aqui". Então ordenou que Paulo fosse mantido sob custódia no palácio de Herodes.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 1, 'Cinco dias depois, o sumo sacerdote Ananias desceu a Cesaréia com alguns dos líderes dos judeus e um advogado chamado Tértulo, os quais apresentaram ao governador suas acusações contra Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 2, 'Quando Paulo foi chamado, Tértulo apresentou sua causa a Félix: "Temos desfrutado de um longo período de paz durante o teu governo, e o teu providente cuidado resultou em reformas nesta nação.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 3, 'Em tudo e em toda parte, excelentíssimo Félix, reconhecemos estes benefícios com profunda gratidão.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 4, 'Todavia, a fim de não tomar-te mais tempo, peço-te o favor de ouvir-nos apenas por um pouco.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 5, '"Verificamos que este homem é um perturbador, que promove tumultos entre os judeus pelo mundo todo. Ele é o principal cabeça da seita dos nazarenos', 3, CURRENT_TIMESTAMP, false),
(44, 24, 6, 'e tentou até mesmo profanar o templo; então o prendemos e quisemos julgá-lo segundo a nossa lei.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 7, 'Mas o comandante Lísias interveio, e com muita força o arrebatou de nossas mãos e ordenou que os seus acusadores se apresentassem.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 8, 'Se tu mesmo o interrogares, poderás verificar a verdade a respeito de todas estas acusações que estamos fazendo contra ele".', 3, CURRENT_TIMESTAMP, false),
(44, 24, 9, 'Os judeus confirmaram a acusação, garantindo que as afirmações eram verdadeiras.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 10, 'Quando o governador lhe deu sinal para que falasse, Paulo declarou: "Sei que há muitos anos tens sido juiz nesta nação; por isso, de bom grado faço minha defesa.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 11, 'Facilmente poderás verificar que há menos de doze dias subi a Jerusalém para adorar a Deus.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 12, 'Meus acusadores não me encontraram discutindo com ninguém no templo, nem incitando uma multidão nas sinagogas ou em qualquer outro lugar na cidade.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 13, 'Nem tampouco podem provar-te as acusações que agora estão levantando contra mim.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 14, 'Confesso-te, porém, que adoro o Deus dos nossos antepassados como seguidor do Caminho, a que chamam seita. Creio em tudo o que concorda com a Lei e no que está escrito nos Profetas,', 3, CURRENT_TIMESTAMP, false),
(44, 24, 15, 'e tenho em Deus a mesma esperança desses homens: de que haverá ressurreição tanto de justos como de injustos.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 16, 'Por isso procuro sempre conservar minha consciência limpa diante de Deus e dos homens.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 17, '"Depois de estar ausente por vários anos, vim a Jerusalém para trazer esmolas ao meu povo e apresentar ofertas.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 18, 'Enquanto fazia isso, já cerimonialmente puro, encontraram-me no templo, sem envolver-me em nenhum ajuntamento ou tumulto.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 19, 'Mas há alguns judeus da província da Ásia que deveriam estar aqui diante de ti e apresentar acusações, se é que têm algo contra mim.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 20, 'Ou os que aqui se acham deveriam declarar que crime encontraram em mim quando fui levado perante o Sinédrio,', 3, CURRENT_TIMESTAMP, false),
(44, 24, 21, 'a não ser que tenha sido este: quando me apresentei a eles, bradei: Por causa da ressurreição dos mortos estou sendo julgado hoje diante de vocês".', 3, CURRENT_TIMESTAMP, false),
(44, 24, 22, 'Então Félix, que tinha bom conhecimento do Caminho, adiou a causa e disse: "Quando chegar o comandante Lísias, decidirei o caso de vocês".', 3, CURRENT_TIMESTAMP, false),
(44, 24, 23, 'E ordenou ao centurião que mantivesse Paulo sob custódia, mas que lhe desse certa liberdade e permitisse que os seus amigos o servissem.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 24, 'Vários dias depois, Félix veio com Drusila sua mulher, que era judia, mandou chamar Paulo e o ouviu falar sobre a fé em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 25, 'Quando Paulo se pôs a discorrer acerca da justiça, do domínio próprio e do juízo vindouro, Félix teve medo e disse: "Basta, por enquanto! Pode sair. Quando achar conveniente, mandarei chamá-lo de novo".', 3, CURRENT_TIMESTAMP, false),
(44, 24, 26, 'Ao mesmo tempo esperava que Paulo lhe oferecesse algum dinheiro, pelo que mandava buscá-lo freqüentemente e conversava com ele.', 3, CURRENT_TIMESTAMP, false),
(44, 24, 27, 'Passados dois anos, Félix foi sucedido por Pórcio Festo; todavia, porque desejava manter a simpatia dos judeus, Félix deixou Paulo na prisão.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 1, 'Três dias depois de chegar à província, Festo subiu de Cesaréia para Jerusalém,', 3, CURRENT_TIMESTAMP, false),
(44, 25, 2, 'onde os chefes dos sacerdotes e os judeus mais importantes compareceram diante dele, apresentando as acusações contra Paulo.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 3, 'Pediram a Festo o favor de transferir Paulo para Jerusalém, contra os interesses do próprio Paulo, pois estavam preparando uma emboscada para matá-lo no caminho.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 4, 'Festo respondeu: "Paulo está preso em Cesaréia, e eu mesmo vou para lá em breve.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 5, 'Desçam comigo alguns dos seus líderes e apresentem ali as acusações que têm contra esse homem, se realmente ele fez algo de errado".', 3, CURRENT_TIMESTAMP, false),
(44, 25, 6, 'Tendo passado com eles oito a dez dias, desceu para Cesaréia e, no dia seguinte, convocou o tribunal e ordenou que Paulo fosse trazido perante ele.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 7, 'Quando Paulo apareceu, os judeus que tinham chegado de Jerusalém se aglomeraram ao seu redor, fazendo contra ele muitas e graves acusações que não podiam provar.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 8, 'Então Paulo fez sua defesa: "Nada fiz de errado contra a lei dos judeus, contra o templo ou contra César".', 3, CURRENT_TIMESTAMP, false),
(44, 25, 9, 'Festo, querendo prestar um favor aos judeus, perguntou a Paulo: "Você está disposto a ir a Jerusalém e ali ser julgado diante de mim, acerca destas acusações? "', 3, CURRENT_TIMESTAMP, false),
(44, 25, 10, 'Paulo respondeu: "Estou agora diante do tribunal de César, onde devo ser julgado. Não fiz nenhum mal aos judeus, como bem sabes.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 11, 'Se, de fato, sou culpado de ter feito algo que mereça pena de morte, não me recuso a morrer. Mas se as acusações feitas contra mim por estes judeus não são verdadeiras, ninguém tem o direito de me entregar a eles. Apelo para César! "', 3, CURRENT_TIMESTAMP, false),
(44, 25, 12, 'Depois de ter consultado seus conselheiros, Festo declarou: "Você apelou para César, para César irá! "', 3, CURRENT_TIMESTAMP, false),
(44, 25, 13, 'Alguns dias depois, o rei Agripa e Berenice chegaram a Cesaréia para saudar Festo.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 14, 'Visto que estavam passando muitos dias ali, Festo explicou o caso de Paulo ao rei: "Há aqui um homem que Félix deixou preso.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 15, 'Quando fui a Jerusalém, os chefes dos sacerdotes e os líderes dos judeus fizeram acusações contra ele, pedindo que fosse condenado.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 16, '"Eu lhes disse que não é costume romano condenar ninguém antes que ele se defronte pessoalmente com seus acusadores e tenha a oportunidade de se defender das acusações que lhe fazem.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 17, 'Vindo eles comigo para cá, não retardei o caso; convoquei o tribunal no dia seguinte e ordenei que o homem fosse apresentado.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 18, 'Quando os seus acusadores se levantaram para falar, não o acusaram de nenhum dos crimes que eu esperava.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 19, 'Pelo contrário, tinham alguns pontos de divergência com ele acerca de sua própria religião e de um certo Jesus, já morto, o qual Paulo insiste que está vivo.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 20, 'Fiquei sem saber como investigar tais assuntos; por isso perguntei-lhe se ele estaria disposto a ir a Jerusalém e ser julgado ali acerca destas acusações.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 21, 'Apelando Paulo para que fosse guardado até a decisão do Imperador, ordenei que ficasse sob custódia até que eu pudesse enviá-lo a César".', 3, CURRENT_TIMESTAMP, false),
(44, 25, 22, 'Então Agripa disse a Festo: "Eu também gostaria de ouvir esse homem". Ele respondeu: "Amanhã o ouvirás".', 3, CURRENT_TIMESTAMP, false),
(44, 25, 23, 'No dia seguinte, Agripa e Berenice vieram com grande pompa e entraram na sala de audiências com os altos oficiais e os homens importantes da cidade. Por ordem de Festo, Paulo foi trazido.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 24, 'Então Festo disse: "Ó rei Agripa e todos os senhores aqui presentes conosco, vejam este homem! Toda a comunidade judaica me fez petições a respeito dele em Jerusalém e aqui em Cesaréia, gritando que ele não deveria mais viver.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 25, 'Mas verifiquei que ele nada fez que mereça pena de morte; todavia, porque apelou para o Imperador, decidi enviá-lo a Roma.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 26, 'No entanto, não tenho nada definido a respeito dele para escrever a Sua Majestade. Por isso, eu o trouxe diante dos senhores, e especialmente diante de ti, rei Agripa, de forma que, feita esta investigação, eu tenha algo para escrever.', 3, CURRENT_TIMESTAMP, false),
(44, 25, 27, 'Pois não me parece razoável enviar um preso sem especificar as acusações contra ele".', 3, CURRENT_TIMESTAMP, false),
(44, 26, 1, 'Então Agripa disse a Paulo: "Você tem permissão para falar em sua defesa". A seguir, Paulo fez sinal com a mão e começou a sua defesa:', 3, CURRENT_TIMESTAMP, false),
(44, 26, 2, '"Rei Agripa, considero-me feliz por poder estar hoje em tua presença, para fazer a minha defesa contra todas as acusações dos judeus,', 3, CURRENT_TIMESTAMP, false),
(44, 26, 3, 'e especialmente porque estás bem familiarizado com todos os costumes e controvérsias deles. Portanto, peço que me ouças pacientemente.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 4, '"Todos os judeus sabem como tenho vivido desde pequeno, tanto em minha terra natal como em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 5, 'Eles me conhecem há muito tempo e podem testemunhar, se quiserem, que, como fariseu, vivi de acordo com a seita mais severa da nossa religião.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 6, 'Agora, estou sendo julgado por causa da minha esperança no que Deus prometeu aos nossos antepassados.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 7, 'Esta é a promessa que as nossas doze tribos esperam que se cumpra, cultuando a Deus com fervor, dia e noite. É por causa desta esperança, ó rei, que estou sendo acusado pelos judeus.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 8, 'Por que os senhores acham impossível que Deus ressuscite os mortos?', 3, CURRENT_TIMESTAMP, false),
(44, 26, 9, '"Eu também estava convencido de que deveria fazer todo o possível para me opor ao nome de Jesus, o Nazareno.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 10, 'E foi exatamente isso que fiz em Jerusalém. Com autorização dos chefes dos sacerdotes lancei muitos santos na prisão, e quando eles eram condenados à morte eu dava o meu voto contra eles.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 11, 'Muitas vezes ia de uma sinagoga para outra a fim de castigá-los, e tentava forçá-los a blasfemar. Em minha fúria contra eles, cheguei a ir a cidades estrangeiras para persegui-los.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 12, '"Numa dessas viagens eu estava indo para Damasco, com autorização e permissão dos chefes dos sacerdotes.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 13, 'Por volta do meio-dia, ó rei, estando eu a caminho, vi uma luz do céu, mais resplandecente que o sol, brilhando ao meu redor e ao redor dos que iam comigo.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 14, 'Todos caímos por terra. Então ouvi uma voz que me dizia em aramaico. ‘Saulo, Saulo, por que você está me perseguindo? Resistir ao aguilhão só lhe trará dor! ’', 3, CURRENT_TIMESTAMP, false),
(44, 26, 15, '"Então perguntei: Quem és tu, Senhor? "Respondeu o Senhor: ‘Sou Jesus, a quem você está perseguindo.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 16, 'Agora, levante-se, fique de pé. Eu lhe apareci para constituí-lo servo e testemunha do que você viu a meu respeito e do que lhe mostrarei.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 17, 'Eu o livrarei do seu próprio povo e dos gentios, aos quais eu o envio', 3, CURRENT_TIMESTAMP, false),
(44, 26, 18, 'para abrir-lhes os olhos e convertê-los das trevas para a luz, e do poder de Satanás para Deus, a fim de que recebam o perdão dos pecados e herança entre os que são santificados pela fé em mim’.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 19, '"Assim, rei Agripa, não fui desobediente à visão celestial.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 20, 'Preguei em primeiro lugar aos que estavam em Damasco, depois aos que estavam em Jerusalém e em toda a Judéia, e também aos gentios, dizendo que se arrependessem e se voltassem para Deus, praticando obras que mostrassem o seu arrependimento.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 21, 'Por isso os judeus me prenderam no pátio do templo e tentaram matar-me.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 22, 'Mas tenho contado com a ajuda de Deus até o dia de hoje, e, por este motivo, estou aqui e dou testemunho tanto a gente simples como a gente importante. Não estou dizendo nada além do que os profetas e Moisés disseram que haveria de acontecer:', 3, CURRENT_TIMESTAMP, false),
(44, 26, 23, 'que o Cristo haveria de sofrer e, sendo o primeiro a ressuscitar dentre os mortos, proclamaria luz para o seu próprio povo e para os gentios".', 3, CURRENT_TIMESTAMP, false),
(44, 26, 24, 'A esta altura Festo interrompeu a defesa de Paulo e disse em alta voz: "Você está louco, Paulo! As muitas letras o estão levando à loucura! "', 3, CURRENT_TIMESTAMP, false),
(44, 26, 25, 'Respondeu Paulo: "Não estou louco, excelentíssimo Festo. O que estou dizendo é verdadeiro e de bom senso.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 26, 'O rei está familiarizado com essas coisas, e lhe posso falar abertamente. Estou certo de que nada disso escapou do seu conhecimento, pois nada se passou num lugar qualquer.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 27, 'Rei Agripa, crês nos profetas? Eu sei que sim".', 3, CURRENT_TIMESTAMP, false),
(44, 26, 28, 'Então Agripa disse a Paulo: "Você acha que em tão pouco tempo pode convencer-me a tornar-me cristão? "', 3, CURRENT_TIMESTAMP, false),
(44, 26, 29, 'Paulo respondeu: "Em pouco ou em muito, peço a Deus que não apenas tu, mas todos os que hoje me ouvem se tornem como eu, menos estas algemas".', 3, CURRENT_TIMESTAMP, false),
(44, 26, 30, 'O rei se levantou, e com ele o governador e Berenice, como também os que estavam assentados com eles.', 3, CURRENT_TIMESTAMP, false),
(44, 26, 31, 'Saindo do salão, comentavam entre si: "Este homem não fez nada que mereça morte ou prisão".', 3, CURRENT_TIMESTAMP, false),
(44, 26, 32, 'Agripa disse a Festo: "Ele poderia ser posto em liberdade, se não tivesse apelado para César".', 3, CURRENT_TIMESTAMP, false),
(44, 27, 1, 'Quando ficou decidido que navegaríamos para a Itália, Paulo e alguns outros presos foram entregues a um centurião chamado Júlio, que pertencia ao Regimento Imperial.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 2, 'Embarcamos num navio de Adramítio, que estava de partida para alguns lugares da província da Ásia, e saímos ao mar, estando conosco Aristarco, um macedônio de Tessalônica.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 3, 'No dia seguinte, ancoramos em Sidom; e Júlio, num gesto de bondade para com Paulo, permitiu-lhe que fosse ao encontro dos seus amigos, para que estes suprissem as suas necessidades.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 4, 'Quando partimos de lá, passamos ao norte de Chipre, porque os ventos nos eram contrários.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 5, 'Tendo atravessado o mar aberto ao longo da Cilícia e da Panfília, ancoramos em Mirra, na Lícia.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 6, 'Ali, o centurião encontrou um navio alexandrino que estava de partida para a Itália e nele nos fez embarcar.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 7, 'Navegamos vagarosamente por muitos dias e tivemos dificuldade para chegar a Cnido. Não sendo possível prosseguir em nossa rota, devido aos ventos contrários, navegamos ao sul de Creta, defronte a Salmona.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 8, 'Costeamos a ilha com dificuldade e chegamos a um lugar chamado Bons Portos, perto da cidade de Laséia.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 9, 'Tínhamos perdido muito tempo, e agora a navegação se tornara perigosa, pois já havia passado o Jejum. Por isso Paulo os advertiu:', 3, CURRENT_TIMESTAMP, false),
(44, 27, 10, '"Senhores, vejo que a nossa viagem será desastrosa e acarretará grande prejuízo para o navio, para a carga e também para as nossas vidas".', 3, CURRENT_TIMESTAMP, false),
(44, 27, 11, 'Mas o centurião, em vez de ouvir o que Paulo falava, seguiu o conselho do piloto e do dono do navio.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 12, 'Visto que o porto não era próprio para passar o inverno, a maioria decidiu que deveríamos continuar navegando, com a esperança de alcançar Fenice e ali passar o inverno. Este era um porto de Creta, que dava para sudoeste e noroeste.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 13, 'Começando a soprar suavemente o vento sul, eles pensaram que haviam obtido o que desejavam; por isso levantaram âncoras e foram navegando ao longo da costa de Creta.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 14, 'Pouco tempo depois, desencadeou-se da ilha um vento muito forte, chamado Nordeste.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 15, 'O navio foi arrastado pela tempestade, sem poder resistir ao vento; assim, cessamos as manobras e ficamos à deriva.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 16, 'Passando ao sul de uma pequena ilha chamada Clauda, foi com dificuldade que conseguimos recolher o barco salva-vidas.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 17, 'Levantando-o, lançaram mão de todos os meios para reforçar o navio com cordas; e temendo que ele encalhasse nos bancos de areia de Sirte, baixaram as velas e deixaram o navio à deriva.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 18, 'No dia seguinte, sendo violentamente castigados pela tempestade, começaram a lançar fora a carga.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 19, 'No terceiro dia, lançaram fora, com as próprias mãos, a armação do navio.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 20, 'Não aparecendo nem sol nem estrelas por muitos dias, e continuando a abater-se sobre nós grande tempestade, finalmente perdemos toda a esperança de salvamento.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 21, 'Visto que os homens tinham passado muito tempo sem comer, Paulo levantou-se diante deles e disse: "Os senhores deviam ter aceitado o meu conselho de não partir de Creta, pois assim teriam evitado este dano e prejuízo.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 22, 'Mas agora recomendo-lhes que tenham coragem, pois nenhum de vocês perderá a vida; apenas o navio será destruído.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 23, 'Pois ontem à noite apareceu-me um anjo do Deus a quem pertenço e a quem adoro, dizendo-me:', 3, CURRENT_TIMESTAMP, false),
(44, 27, 24, '‘Paulo, não tenha medo. É preciso que você compareça perante César; Deus, por sua graça, deu-lhe as vidas de todos os que estão navegando com você’.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 25, 'Assim, tenham ânimo, senhores! Creio em Deus que acontecerá do modo como me foi dito.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 26, 'Devemos ser arrastados para alguma ilha".', 3, CURRENT_TIMESTAMP, false),
(44, 27, 27, 'Na décima quarta noite, ainda estávamos sendo levados de um lado para outro no mar Adriático, quando, por volta da meia-noite, os marinheiros imaginaram que estávamos próximos da terra.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 28, 'Lançando a sonda, verificaram que a profundidade era de trinta e sete metros; pouco tempo depois, lançaram novamente a sonda e encontraram vinte e sete metros.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 29, 'Temendo que fôssemos jogados contra as pedras, lançaram quatro âncoras da popa e faziam preces para que amanhecesse o dia.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 30, 'Tentando escapar do navio, os marinheiros baixaram o barco salva-vidas ao mar, a pretexto de lançar âncoras da proa.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 31, 'Então Paulo disse ao centurião e aos soldados: "Se estes homens não ficarem no navio, vocês não poderão salvar-se".', 3, CURRENT_TIMESTAMP, false),
(44, 27, 32, 'Com isso os soldados cortaram as cordas que prendiam o barco salva-vidas e o deixaram cair.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 33, 'Pouco antes do amanhecer, Paulo insistia que todos se alimentassem, dizendo: "Hoje faz catorze dias que vocês têm estado em vigília constante, sem nada comer.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 34, 'Agora eu os aconselho a comerem algo, pois só assim poderão sobreviver. Nenhum de vocês perderá um fio de cabelo sequer".', 3, CURRENT_TIMESTAMP, false),
(44, 27, 35, 'Tendo dito isso, tomou pão e deu graças a Deus diante de todos. Então o partiu e começou a comer.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 36, 'Todos se reanimaram e também comeram algo.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 37, 'Estavam a bordo duzentas e setenta e seis pessoas.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 38, 'Depois de terem comido até ficarem satisfeitos, aliviaram o peso do navio, atirando todo o trigo ao mar.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 39, 'Quando amanheceu não reconheceram a terra, mas viram uma enseada com uma praia, para onde decidiram conduzir o navio, se fosse possível.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 40, 'Cortando as âncoras, deixaram-nas no mar, desatando ao mesmo tempo as cordas que prendiam os lemes. Então, alçando a vela da proa ao vento, dirigiram-se para a praia.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 41, 'Mas o navio encalhou num banco de areia, onde tocou o fundo. A proa encravou-se e ficou imóvel, e a popa foi quebrada pela violência das ondas.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 42, 'Os soldados resolveram matar os presos para impedir que algum deles fugisse, jogando-se ao mar.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 43, 'Mas o centurião queria poupar a vida de Paulo e os impediu de executar o plano. Então ordenou aos que sabiam nadar que se lançassem primeiro ao mar em direção à terra.', 3, CURRENT_TIMESTAMP, false),
(44, 27, 44, 'Os outros teriam que salvar-se em tábuas ou em pedaços do navio. Dessa forma, todos chegaram a salvo em terra.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 1, 'Uma vez em terra, descobrimos que a ilha se chamava Malta.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 2, 'Os habitantes da ilha mostraram extraordinária bondade para conosco. Fizeram uma fogueira e receberam bem a todos nós, pois estava chovendo e fazia frio.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 3, 'Paulo ajuntou um monte de gravetos; quando os colocava no fogo, uma víbora, fugindo do calor, prendeu-se à sua mão.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 4, 'Quando os habitantes da ilha viram a cobra agarrada na mão de Paulo, disseram uns aos outros: "Certamente este homem é assassino, pois, tendo escapado do mar, a Justiça não lhe permite viver".', 3, CURRENT_TIMESTAMP, false),
(44, 28, 5, 'Mas Paulo, sacudindo a cobra no fogo, não sofreu mal nenhum.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 6, 'Eles, porém, esperavam que ele começasse a inchar ou que caísse morto de repente, mas, tendo esperado muito tempo e vendo que nada de estranho lhe sucedia, mudaram de idéia e passaram a dizer que ele era um deus.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 7, 'Próximo dali havia uma propriedade pertencente a Públio, o homem principal da ilha. Ele nos convidou a ficar em sua casa e, por três dias, bondosamente nos recebeu e nos hospedou.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 8, 'Seu pai estava doente, acamado, sofrendo de febre e disenteria. Paulo entrou para vê-lo e, depois de orar, impôs-lhe as mãos e o curou.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 9, 'Tendo acontecido isso, os outros doentes da ilha vieram e foram curados.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 10, 'Eles nos prestaram muitas honras e, quando estávamos para embarcar, forneceram-nos os suprimentos que necessitávamos.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 11, 'Passados três meses, embarcamos num navio que tinha passado o inverno na ilha; era um navio alexandrino, que tinha por emblema os deuses gêmeos Castor e Pólux.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 12, 'Aportando em Siracusa, ficamos ali três dias.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 13, 'Dali partimos e chegamos a Régio. No dia seguinte, soprando o vento sul, prosseguimos, chegando a Potéoli no segundo dia.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 14, 'Ali encontramos alguns irmãos que nos convidaram a passar uma semana com eles. E depois fomos para Roma.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 15, 'Os irmãos dali tinham ouvido falar que estávamos chegando e foram até a praça de Ápio e às Três Vendas para nos encontrar. Vendo-os, Paulo deu graças a Deus e sentiu-se encorajado.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 16, 'Quando chegamos a Roma, Paulo recebeu permissão para morar por conta própria, sob a custódia de um soldado.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 17, 'Três dias depois, ele convocou os líderes dos judeus. Quando estes se reuniram, Paulo lhes disse: "Meus irmãos, embora eu não tenha feito nada contra o nosso povo nem contra os costumes dos nossos antepassados, fui preso em Jerusalém e entregue aos romanos.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 18, 'Eles me interrogaram e queriam me soltar, porque eu não era culpado de crime algum que merecesse pena de morte.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 19, 'Todavia, tendo os judeus feito objeção, fui obrigado a apelar para César, não porém, por ter alguma acusação contra o meu próprio povo.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 20, 'Por essa razão pedi para vê-los e conversar com vocês. Por causa da esperança de Israel é que estou preso com estas algemas".', 3, CURRENT_TIMESTAMP, false),
(44, 28, 21, 'Eles responderam: "Não recebemos nenhuma carta da Judéia a seu respeito, e nenhum dos irmãos que vieram de lá relatou ou disse qualquer coisa de mal contra você.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 22, 'Todavia, queremos ouvir de sua parte o que você pensa, pois sabemos que por todo lugar há gente falando contra esta seita".', 3, CURRENT_TIMESTAMP, false),
(44, 28, 23, 'Assim combinaram encontrar-se com Paulo em dia determinado, indo em grupo ainda mais numeroso ao lugar onde ele estava. Desde a manhã até à tarde ele lhes deu explicações e lhes testemunhou do Reino de Deus, procurando convencê-los a respeito de Jesus, com base na Lei de Moisés e nos Profetas.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 24, 'Alguns foram convencidos pelo que ele dizia, mas outros não creram.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 25, 'Discordaram entre si mesmos e começaram a ir embora, depois de Paulo ter feito esta declaração final: "Bem que o Espírito Santo falou aos seus antepassados, por meio do profeta Isaías:', 3, CURRENT_TIMESTAMP, false),
(44, 28, 26, '‘Vá a este povo e diga: "Ainda que estejam sempre ouvindo, vocês nunca entenderão; ainda que estejam sempre vendo, jamais perceberão".', 3, CURRENT_TIMESTAMP, false),
(44, 28, 27, 'Pois o coração deste povo se tornou insensível; de má vontade ouviram com os seus ouvidos, e fecharam os seus olhos. Se assim não fosse, poderiam ver com os olhos, ouvir com os ouvidos, entender com o coração e converter-se, e eu os curaria’.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 28, '"Portanto, quero que saibam que esta salvação de Deus é enviada aos gentios; eles a ouvirão! "', 3, CURRENT_TIMESTAMP, false),
(44, 28, 29, 'Depois que ele disse isto, os judeus se retiraram, discutindo intensamente entre si.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 30, 'Por dois anos inteiros Paulo permaneceu na casa que havia alugado, e recebia a todos os que iam vê-lo.', 3, CURRENT_TIMESTAMP, false),
(44, 28, 31, 'Pregava o Reino de Deus e ensinava a respeito do Senhor Jesus Cristo, abertamente e sem impedimento algum.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 1, 'Cântico dos Cânticos de Salomão.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 2, 'Ah, se ele me beijasse, se a sua boca me cobrisse de beijos... Sim, as suas carícias são mais agradáveis que o vinho.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 3, 'A fragrância dos seus perfumes é suave; o seu nome é como perfume derramado. Não é à toa que as jovens o amam!', 3, CURRENT_TIMESTAMP, false),
(22, 1, 4, 'Leve-me com você! Vamos depressa! Leve-me o rei para os seus aposentos! Estamos alegres e felizes por sua causa; celebraremos o seu amor mais do que o vinho. Com toda a razão você é amado!', 3, CURRENT_TIMESTAMP, false),
(22, 1, 5, 'Estou escura, mas sou bela, ó mulheres de Jerusalém; escura como as tendas de Quedar, bela como as cortinas de Salomão.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 6, 'Não me fiquem olhando assim porque estou escura; foi o sol que me queimou a pele. Os filhos de minha mãe zangaram-se comigo e fizeram-me tomar conta das vinhas; da minha própria vinha, porém, eu não pude cuidar.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 7, 'Conte-me, você a quem amo, onde faz pastar o seu rebanho e onde faz as suas ovelhas descansarem ao meio-dia? Se eu não o souber, serei como uma mulher coberta com véu junto aos rebanhos dos seus amigos.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 8, 'Se você, a mais linda das mulheres, se você não o sabe, siga a trilha das ovelhas e faça as suas cabritas pastarem junto às tendas dos pastores.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 9, 'Comparo você, minha querida, a uma égua das carruagens do faraó.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 10, 'Como são belas as suas faces entre os brincos, e o seu pescoço com os colares de jóias!', 3, CURRENT_TIMESTAMP, false),
(22, 1, 11, 'Faremos para você brincos de ouro com incrustações de prata.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 12, 'Enquanto o rei estava em seus aposentos, o meu nardo espalhou a sua fragrância.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 13, 'O meu amado é para mim como uma pequenina bolsa de mirra que passa a noite entre os meus seios.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 14, 'O meu amado é para mim um ramalhete de flores de hena das vinhas de En-Gedi.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 15, 'Como você é linda, minha querida! Ah, como é linda! Seus olhos são pombas.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 16, 'Como você é belo, meu amado! Ah, como é encantador! Verdejante é o nosso leito.', 3, CURRENT_TIMESTAMP, false),
(22, 1, 17, 'De cedro são as vigas da nossa casa, e de cipreste os caibros do nosso telhado.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 1, 'Sou uma flor de Sarom, um lírio dos vales.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 2, 'Como um lírio entre os espinhos é a minha amada entre as jovens.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 3, 'Como uma macieira entre as árvores da floresta é o meu amado entre os jovens. Tenho prazer em sentar-me à sua sombra; o seu fruto é doce ao meu paladar.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 4, 'Ele me levou ao salão de banquetes, e o seu estandarte sobre mim é o amor.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 5, 'Por favor, sustentem-me com passas, revigorem-me com maçãs, pois estou doente de amor.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 6, 'O seu braço esquerdo esteja debaixo da minha cabeça, e o seu braço direito me abrace.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 7, 'Mulheres de Jerusalém, eu as faço jurar pelas gazelas e pelas corças do campo: não despertem nem provoquem o amor enquanto ele não o quiser.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 8, 'Escutem! É o meu amado! Vejam! Aí vem ele, saltando pelos montes, pulando sobre as colinas.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 9, 'O meu amado é como uma gazela, como um cervo novo. Vejam! Lá está ele atrás do nosso muro, observando pelas janelas, espiando pelas grades.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 10, 'O meu amado falou e me disse: Levante-se, minha querida, minha bela, e venha comigo.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 11, 'Veja! O inverno passou; as chuvas acabaram e já se foram.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 12, 'Aparecem flores sobre a terra, e chegou o tempo de cantar; já se ouve em nossa terra o arrulhar dos pombos.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 13, 'A figueira produz os primeiros frutos; as vinhas florescem e espalham sua fragrância. Levante-se, venha, minha querida; minha bela, venha comigo.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 14, 'Minha pomba que está nas fendas da rocha, nos esconderijos, nas encostas dos montes, mostre-me o seu rosto, deixe-me ouvir a sua voz; pois a sua voz é suave, e o seu rosto é lindo.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 15, 'Apanhem para nós as raposas, as raposinhas que estragam as vinhas, pois as nossas vinhas estão floridas.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 16, 'O meu amado é meu, e eu sou dele; ele pastoreia entre os lírios.', 3, CURRENT_TIMESTAMP, false),
(22, 2, 17, 'Volte, amado meu, antes que rompa o dia e fujam as sombras, e seja como a gazela ou como o cervo novo nas colinas escarpadas.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 1, 'A noite toda procurei em meu leito aquele a quem o meu coração ama, mas não o encontrei.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 2, 'Vou levantar-me agora e percorrer a cidade, irei por suas ruas e praças; buscarei aquele a quem o meu coração ama. Eu o procurei, mas não o encontrei.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 3, 'As sentinelas me encontraram quando faziam as suas rondas na cidade. "Vocês viram aquele a quem o meu coração ama? ", perguntei.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 4, 'Mal havia passado por elas, quando encontrei aquele a quem o meu coração ama. Eu o segurei e não o deixei ir até que o trouxe para a casa de minha mãe, para o quarto daquela que me concebeu.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 5, 'Mulheres de Jerusalém, eu as faço jurar pelas gazelas e pelas corças do campo: Não despertem nem incomodem o amor enquanto ele não o quiser.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 6, 'Que é que vem subindo do deserto, como uma coluna de fumaça, perfumado com mirra e incenso com extrato de todas as especiarias dos mercadores?', 3, CURRENT_TIMESTAMP, false),
(22, 3, 7, 'Vejam! É a liteira de Salomão, escoltada por sessenta guerreiros, os mais nobres de Israel;', 3, CURRENT_TIMESTAMP, false),
(22, 3, 8, 'todos eles trazem espada, todos são experientes na guerra, cada um com a sua espada, preparado para enfrentar os pavores da noite.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 9, 'O rei Salomão fez para si uma liteira; ele a fez com madeira do Líbano.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 10, 'Suas traves ele fez de prata, seu teto, de ouro. Seu banco foi estofado em púrpura, seu interior foi cuidadosamente preparado pelas mulheres de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(22, 3, 11, 'Mulheres de Sião, saiam! Venham ver o rei Salomão! Ele está usando a coroa, a coroa que sua mãe lhe colocou no dia do seu casamento, no dia em que o seu coração se alegrou.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 1, 'Como você é linda, minha querida! Ah, como é linda! Seus olhos, por trás do véu, são pombas. Seu cabelo é como um rebanho de cabras que vem descendo do monte Gileade.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 2, 'Seus dentes são como um rebanho de ovelhas recém-tosquiadas que vão subindo do lavadouro. Cada uma tem o seu par; não há nenhuma sem crias.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 3, 'Seus lábios são como um fio vermelho; sua boca é belíssima. Suas faces, por trás do véu, são como as metades de uma romã.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 4, 'Seu pescoço é como a torre de Davi, construída como arsenal. Nela estão pendurados mil escudos, todos eles escudos de heróicos guerreiros.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 5, 'Seus dois seios são como filhotes de cervo, como filhotes gêmeos de uma gazela que repousam entre os lírios.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 6, 'Enquanto não raia o dia e as sombras não fogem, irei à montanha da mirra e à colina do incenso.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 7, 'Você é toda linda, minha querida; em você não há defeito algum.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 8, 'Venha do Líbano comigo, minha noiva, venha do Líbano comigo. Desça do alto do Amana, do topo do Senir, do alto do Hermom, das covas dos leões e das tocas dos leopardos nas montanhas.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 9, 'Você fez disparar o meu coração, minha irmã, minha noiva; fez disparar o meu coração com um simples olhar, com uma simples jóia dos seus colares.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 10, 'Quão deliciosas são as suas carícias, minha irmã, minha noiva! Suas carícias são mais agradáveis que o vinho, e a fragrância do seu perfume supera o de qualquer especiaria!', 3, CURRENT_TIMESTAMP, false),
(22, 4, 11, 'Os seus lábios gotejam a doçura dos favos de mel, minha noiva; leite e mel estão debaixo da sua língua. A fragrância das suas vestes é como a fragrância do Líbano.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 12, 'Você é um jardim fechado, minha irmã, minha noiva; você é uma nascente fechada, uma fonte selada.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 13, 'De você brota um pomar de romãs com frutos seletos, com flores de hena e nardo,', 3, CURRENT_TIMESTAMP, false),
(22, 4, 14, 'nardo e açafrão, cálamo e canela, com todas as madeiras aromáticas, mirra e aloés e as mais finas especiarias.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 15, 'Você é uma fonte de jardim, um poço de águas vivas, que descem do Líbano.', 3, CURRENT_TIMESTAMP, false),
(22, 4, 16, 'Acorde, vento norte! Venha, vento sul! Soprem em meu jardim, para que a sua fragrância se espalhe ao seu redor. Que o meu amado entre em seu jardim e saboreie os seus deliciosos frutos.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 1, 'Entrei em meu jardim, minha irmã, minha noiva; ajuntei a minha mirra com as minhas especiarias. Comi o meu favo e o meu mel; Bebi o meu vinho e o meu leite. Comam, amigos, bebam e embriaguem-se, ó amados.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 2, 'Eu estava quase dormindo, mas o meu coração estava acordado. Escutem! O meu amado está batendo: Abra-me a porta, minha irmã, minha querida, minha pomba, minha mulher ideal, pois a minha cabeça está encharcada de orvalho, o meu cabelo, da umidade da noite.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 3, 'Já tirei a túnica; terei que vestir-me de novo? Já lavei os pés; terei que sujá-los de novo?', 3, CURRENT_TIMESTAMP, false),
(22, 5, 4, 'O meu amado pôs a mão por uma abertura da tranca; meu coração começou a palpitar por causa dele.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 5, 'Levantei-me para abrir-lhe a porta; minhas mãos destilavam mirra, meus dedos vertiam mirra, na maçaneta da tranca.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 6, 'Eu abri, mas o meu amado se fora; o meu amado já havia partido. Eu quase desmaiei de tristeza! Procurei-o, mas não o encontrei. Eu o chamei, mas ele não respondeu.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 7, 'As sentinelas me encontraram enquanto faziam a ronda na cidade. Bateram-me, feriram-me; e tomaram o meu manto, as sentinelas dos muros!', 3, CURRENT_TIMESTAMP, false),
(22, 5, 8, 'Ó mulheres de Jerusalém, eu lhes faço jurar: se encontrarem o meu amado, o que dirão a ele? Digam-lhe que estou doente de amor.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 9, 'Que diferença há entre o seu amado e outro qualquer, ó você, das mulheres a mais linda? Que diferença há entre o seu amado e outro qualquer, para você nos obrigar a tal promessa?', 3, CURRENT_TIMESTAMP, false),
(22, 5, 10, 'O meu amado tem a pele bronzeada; ele se destaca entre dez mil.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 11, 'Sua cabeça é ouro, o ouro mais puro; seus cabelos ondulam ao vento como ramos de palmeira; são negros como o corvo.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 12, 'Seus olhos são como pombas junto aos regatos de água, lavados em leite, incrustados como jóias.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 13, 'Suas faces são como um jardim de especiarias que exalam perfume. Seus lábios são como lírios que destilam mirra.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 14, 'Seus braços são cilindros de ouro engastados com berilo. Seu tronco é como marfim polido adornado de safiras.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 15, 'Suas pernas são colunas de mármore firmadas em bases de ouro puro. Sua aparência é como o Líbano; ele é elegante como os cedros.', 3, CURRENT_TIMESTAMP, false),
(22, 5, 16, 'Sua boca é a própria doçura; ele é mui desejável. Esse é o meu amado, esse é o meu querido, ó mulheres de Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 1, 'Para onde foi o seu amado, ó mais linda das mulheres? Diga-nos para onde foi o seu amado e o procuraremos junto com você!', 3, CURRENT_TIMESTAMP, false),
(22, 6, 2, 'O meu amado desceu ao seu jardim, aos canteiros de especiarias, para descansar nos jardins e colher lírios.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 3, 'Eu sou do meu amado, e o meu amado é meu; ele descansa entre os lírios.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 4, 'Minha querida, você é linda como Tirza, bela como Jerusalém, admirável como um exército e suas bandeiras.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 5, 'Desvie de mim os seus olhos, pois eles me perturbam. Seu cabelo é como um rebanho de cabras que desce de Gileade.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 6, 'Seus dentes são como um rebanho de ovelhas que sobem do lavadouro. Cada uma tem o seu par, não há nenhuma sem crias.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 7, 'Suas faces, por trás do véu, são como as metades de uma romã.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 8, 'Pode haver sessenta rainhas, e oitenta concubinas, e um número sem fim de virgens,', 3, CURRENT_TIMESTAMP, false),
(22, 6, 9, 'mas ela é única, a minha pomba, minha mulher ideal! Ela é a filha favorita de sua mãe, a predileta daquela que a deu à luz. Quando outras jovens a vêem, dizem que ela é muito feliz; as rainhas e as concubinas a elogiam.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 10, 'Quem é essa que aparece como o alvorecer, bela como a lua, brilhante como o sol, admirável como um exército e suas bandeiras?', 3, CURRENT_TIMESTAMP, false),
(22, 6, 11, 'Desci ao bosque das nogueiras para ver os renovos no vale, para ver se as videiras tinham brotado e se as romãs estavam em flor.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 12, 'Antes que eu o percebesse, você me colocou entre as carruagens, com um príncipe ao meu lado.', 3, CURRENT_TIMESTAMP, false),
(22, 6, 13, 'Volte, volte, Sulamita; volte, volte, para que a contemplemos. Por que vocês querem contemplar a Sulamita, como na dança de Maanaim?', 3, CURRENT_TIMESTAMP, false),
(22, 7, 1, 'Como são lindos os seus pés calçados com sandálias, ó filha do príncipe! As curvas das suas coxas são como jóias, obra das mãos de um artífice.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 2, 'Seu umbigo é uma taça redonda onde nunca falta o vinho de boa mistura. Sua cintura é um monte de trigo cercado de lírios.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 3, 'Seus seios são como dois filhotes de corça, gêmeos de uma gazela.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 4, 'Seu pescoço é como uma torre de marfim. Seus olhos são como os açudes de Hesbom, junto à porta de Bate-Rabim. Seu nariz é como a torre do Líbano voltada para Damasco.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 5, 'Sua cabeça se eleva como o monte Carmelo. Seus cabelos soltos têm reflexos de púrpura; o rei caiu prisioneiro das suas ondas.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 6, 'Como você é linda! Como você me agrada! Ó amor, com suas delícias!', 3, CURRENT_TIMESTAMP, false),
(22, 7, 7, 'Seu porte é como o da palmeira, e os seus seios como cachos de frutos.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 8, 'Eu disse: Subirei à palmeira; eu me apossarei dos seus frutos. Sejam os seus seios como os cachos da videira, o aroma da sua respiração como maçãs,', 3, CURRENT_TIMESTAMP, false),
(22, 7, 9, 'e a sua boca como o melhor vinho... vinho que flui suavemente para o meu amado, escorrendo suavemente sobre os lábios de quem já vai adormecendo.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 10, 'Eu pertenço ao meu amado, e ele me deseja.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 11, 'Venha, meu amado, vamos fugir para o campo, passemos a noite nos povoados.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 12, 'Vamos cedo para as vinhas para ver se as videiras brotaram, se as suas flores se abriram, e se as romãs estão em flor; ali eu lhe darei o meu amor.', 3, CURRENT_TIMESTAMP, false),
(22, 7, 13, 'As mandrágoras exalam o seu perfume, e à nossa porta há todo tipo de frutos finos, secos e frescos, que reservei para você, meu amado.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 1, 'Ah, quem dera você fosse meu irmão, amamentado nos seios de minha mãe! Então, se eu o encontrasse fora de casa, eu o beijaria, e ninguém me desprezaria.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 2, 'Eu o conduziria e o traria à casa de minha mãe, e você me ensinaria. Eu lhe daria vinho aromatizado para beber, o néctar das minhas romãs.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 3, 'O seu braço esquerdo esteja debaixo da minha cabeça e o seu braço direito me abrace.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 4, 'Mulheres de Jerusalém, eu as faço jurar: Não despertem nem incomodem o amor enquanto ele não o quiser.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 5, 'Quem vem subindo do deserto, apoiada em seu amado? Debaixo da macieira eu o despertei; ali esteve a sua mãe em trabalho de parto, ali sofreu as dores aquela que o deu à luz.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 6, 'Coloque-me como um selo sobre o seu coração; como um selo sobre o seu braço; pois o amor é tão forte quanto a morte, e o ciúme é tão inflexível quanto a sepultura. Suas brasas são fogo ardente, são labaredas do Senhor.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 7, 'Nem muitas águas conseguem apagar o amor; os rios não conseguem levá-lo na correnteza. Se alguém oferecesse todas as riquezas da sua casa para adquirir o amor, seria totalmente desprezado.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 8, 'Temos uma irmãzinha; seus seios ainda não estão crescidos. O que faremos com nossa irmã no dia em que for pedida em casamento?', 3, CURRENT_TIMESTAMP, false),
(22, 8, 9, 'Se ela for um muro, construiremos sobre ela uma torre de prata. Se ela for uma porta, nós a reforçaremos com tábuas de cedro.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 10, 'Eu sou um muro, e meus seios são as suas torres. Assim me tornei aos olhos dele como alguém que dá paz.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 11, 'Salomão possuía uma vinha em Baal-Hamom; ele entregou a sua vinha a arrendatários. Cada um devia trazer pelos frutos da vinha doze quilos de prata.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 12, 'Quanto à minha própria vinha, essa está em meu poder; os doze quilos de prata são para você, ó Salomão, e dois quilos e meio são para os que tomaram conta dos seus frutos.', 3, CURRENT_TIMESTAMP, false),
(22, 8, 13, 'Você, que habita nos jardins, os amigos desejam ouvi-la; deixe-me ouvir a sua voz!', 3, CURRENT_TIMESTAMP, false),
(22, 8, 14, 'Venha depressa, meu amado, e seja como uma gazela, ou como um cervo novo saltando sobre os montes carregados de especiarias.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, e o irmão Timóteo,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 2, 'aos santos e fiéis irmãos em Cristo que estão em Colossos: A vocês, graça e paz da parte de Deus nosso Pai e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 3, 'Sempre agradecemos a Deus, o Pai de nosso Senhor Jesus Cristo, quando oramos por vocês,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 4, 'pois temos ouvido falar da fé que vocês têm em Cristo Jesus e do amor por todos os santos,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 5, 'por causa da esperança que lhes está reservada nos céus, a respeito da qual vocês ouviram por meio da palavra da verdade, o evangelho', 3, CURRENT_TIMESTAMP, false),
(51, 1, 6, 'que chegou até vocês. Por todo o mundo este evangelho vai frutificando e crescendo, como também ocorre entre vocês, desde o dia em que o ouviram e entenderam a graça de Deus em toda a sua verdade.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 7, 'Vocês o aprenderam de Epafras, nosso amado cooperador, fiel ministro de Cristo para conosco,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 8, 'que também nos falou do amor que vocês têm no Espírito.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 9, 'Por essa razão, desde o dia em que o ouvimos, não deixamos de orar por vocês e de pedir que sejam cheios do pleno conhecimento da vontade de Deus, com toda a sabedoria e entendimento espiritual.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 10, 'E isso para que vocês vivam de maneira digna do Senhor e em tudo possam agradá-lo, frutificando em toda boa obra, crescendo no conhecimento de Deus e', 3, CURRENT_TIMESTAMP, false),
(51, 1, 11, 'sendo fortalecidos com todo o poder, de acordo com a força da sua glória, para que tenham toda a perseverança e paciência com alegria,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 12, 'dando graças ao Pai, que nos tornou dignos de participar da herança dos santos no reino da luz.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 13, 'Pois ele nos resgatou do domínio das trevas e nos transportou para o Reino do seu Filho amado,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 14, 'em quem temos a redenção, a saber, o perdão dos pecados.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 15, 'Ele é a imagem do Deus invisível, o primogênito de toda a criação,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 16, 'pois nele foram criadas todas as coisas nos céus e na terra, as visíveis e as invisíveis, sejam tronos ou soberanias, poderes ou autoridades; todas as coisas foram criadas por ele e para ele.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 17, 'Ele é antes de todas as coisas, e nele tudo subsiste.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 18, 'Ele é a cabeça do corpo, que é a igreja; é o princípio e o primogênito dentre os mortos, para que em tudo tenha a supremacia.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 19, 'Pois foi do agrado de Deus que nele habitasse toda a plenitude,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 20, 'e por meio dele reconciliasse consigo todas as coisas, tanto as que estão na terra quanto as que estão no céu, estabelecendo a paz pelo seu sangue derramado na cruz.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 21, 'Antes vocês estavam separados de Deus e, em suas mentes, eram inimigos por causa do mau procedimento de vocês.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 22, 'Mas agora ele os reconciliou pelo corpo físico de Cristo, mediante a morte, para apresentá-los diante dele santos, inculpáveis e livres de qualquer acusação,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 23, 'desde que continuem alicerçados e firmes na fé, sem se afastarem da esperança do evangelho, que vocês ouviram e que tem sido proclamado a todos os que estão debaixo do céu. Esse é o evangelho do qual eu, Paulo, me tornei ministro.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 24, 'Agora me alegro em meus sofrimentos por vocês, e completo no meu corpo o que resta das aflições de Cristo, em favor do seu corpo, que é a igreja.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 25, 'Dela me tornei ministro de acordo com a responsabilidade por Deus a mim atribuída de apresentar-lhes plenamente a palavra de Deus,', 3, CURRENT_TIMESTAMP, false),
(51, 1, 26, 'o mistério que esteve oculto durante épocas e gerações, mas que agora foi manifestado a seus santos.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 27, 'A eles quis Deus dar a conhecer entre os gentios a gloriosa riqueza deste mistério, que é Cristo em vocês, a esperança da glória.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 28, 'Nós o proclamamos, advertindo e ensinando a cada um com toda a sabedoria, a fim de que apresentemos todo homem perfeito em Cristo.', 3, CURRENT_TIMESTAMP, false),
(51, 1, 29, 'Para isso eu me esforço, lutando conforme a sua força, que atua poderosamente em mim.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 1, 'Quero que vocês saibam quanto estou lutando por vocês, pelos que estão em Laodicéia e por todos os que ainda não me conhecem pessoalmente.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 2, 'Esforço-me para que eles sejam fortalecidos em seus corações, estejam unidos em amor e alcancem toda a riqueza do pleno entendimento, a fim de conhecerem plenamente o mistério de Deus, a saber, Cristo.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 3, 'Nele estão escondidos todos os tesouros da sabedoria e do conhecimento.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 4, 'Eu lhes digo isso para que ninguém os engane com argumentos aparentemente convincentes.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 5, 'Porque, embora esteja fisicamente ausente, estou presente com vocês em espírito, e alegro-me em ver como estão vivendo em ordem e como está firme a fé que vocês têm em Cristo.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 6, 'Portanto, assim como vocês receberam a Cristo Jesus, o Senhor, continuem a viver nele,', 3, CURRENT_TIMESTAMP, false),
(51, 2, 7, 'enraizados e edificados nele, firmados na fé, como foram ensinados, transbordando de gratidão.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 8, 'Tenham cuidado para que ninguém os escravize a filosofias vãs e enganosas, que se fundamentam nas tradições humanas e nos princípios elementares deste mundo, e não em Cristo.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 9, 'Pois em Cristo habita corporalmente toda a plenitude da divindade,', 3, CURRENT_TIMESTAMP, false),
(51, 2, 10, 'e, por estarem nele, que é o Cabeça de todo poder e autoridade, vocês receberam a plenitude.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 11, 'Nele também vocês foram circuncidados, não com uma circuncisão feita por mãos humanas, mas com a circuncisão feita por Cristo, que é o despojar do corpo da carne.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 12, 'Isso aconteceu quando vocês foram sepultados com ele no batismo, e com ele foram ressuscitados mediante a fé no poder de Deus que o ressuscitou dentre os mortos.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 13, 'Quando vocês estavam mortos em pecados e na incircuncisão da sua carne, Deus os vivificou juntamente com Cristo. Ele nos perdoou todas as transgressões,', 3, CURRENT_TIMESTAMP, false),
(51, 2, 14, 'e cancelou a escrita de dívida, que consistia em ordenanças, e que nos era contrária. Ele a removeu, pregando-a na cruz,', 3, CURRENT_TIMESTAMP, false),
(51, 2, 15, 'e, tendo despojado os poderes e as autoridades, fez deles um espetáculo público, triunfando sobre eles na cruz.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 16, 'Portanto, não permitam que ninguém os julgue pelo que vocês comem ou bebem, ou com relação a alguma festividade religiosa ou à celebração das luas novas ou dos dias de sábado.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 17, 'Estas coisas são sombras do que haveria de vir; a realidade, porém, encontra-se em Cristo.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 18, 'Não permitam que ninguém que tenha prazer numa falsa humildade e na adoração de anjos os impeça de alcançar o prêmio. Tal pessoa conta detalhadamente suas visões, e sua mente carnal a torna orgulhosa.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 19, 'Trata-se de alguém que não está unido à Cabeça, a partir da qual todo o corpo, sustentado e unido por seus ligamentos e juntas, efetua o crescimento dado por Deus.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 20, 'Já que vocês morreram com Cristo para os princípios elementares deste mundo, por que é que vocês, então, como se ainda pertencessem a ele, se submetem a regras:', 3, CURRENT_TIMESTAMP, false),
(51, 2, 21, '"Não manuseie! " "Não prove! " "Não toque! "?', 3, CURRENT_TIMESTAMP, false),
(51, 2, 22, 'Todas essas coisas estão destinadas a perecer pelo uso, pois se baseiam em mandamentos e ensinos humanos.', 3, CURRENT_TIMESTAMP, false),
(51, 2, 23, 'Essas regras têm, de fato, aparência de sabedoria, com sua pretensa religiosidade, falsa humildade e severidade com o corpo, mas não têm valor algum para refrear os impulsos da carne.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 1, 'Portanto, já que vocês ressuscitaram com Cristo, procurem as coisas que são do alto, onde Cristo está assentado à direita de Deus.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 2, 'Mantenham o pensamento nas coisas do alto, e não nas coisas terrenas.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 3, 'Pois vocês morreram, e agora a sua vida está escondida com Cristo em Deus.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 4, 'Quando Cristo, que é a sua vida, for manifestado, então vocês também serão manifestados com ele em glória.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 5, 'Assim, façam morrer tudo o que pertence à natureza terrena de vocês: imoralidade sexual, impureza, paixão, desejos maus e a ganância, que é idolatria.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 6, 'É por causa dessas coisas que vem a ira de Deus sobre os que vivem na desobediência,', 3, CURRENT_TIMESTAMP, false),
(51, 3, 7, 'as quais vocês praticaram no passado, quando costumavam viver nelas.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 8, 'Mas agora, abandonem todas estas coisas: ira, indignação, maldade, maledicência e linguagem indecente no falar.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 9, 'Não mintam uns aos outros, visto que vocês já se despiram do velho homem com suas práticas', 3, CURRENT_TIMESTAMP, false),
(51, 3, 10, 'e se revestiram do novo, o qual está sendo renovado em conhecimento, à imagem do seu Criador.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 11, 'Nessa nova vida já não há diferença entre grego e judeu, circunciso e incircunciso, bárbaro e cita, escravo e livre, mas Cristo é tudo e está em todos.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 12, 'Portanto, como povo escolhido de Deus, santo e amado, revistam-se de profunda compaixão, bondade, humildade, mansidão e paciência.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 13, 'Suportem-se uns aos outros e perdoem as queixas que tiverem uns contra os outros. Perdoem como o Senhor lhes perdoou.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 14, 'Acima de tudo, porém, revistam-se do amor, que é o elo perfeito.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 15, 'Que a paz de Cristo seja o juiz em seus corações, visto que vocês foram chamados a viver em paz, como membros de um só corpo. E sejam agradecidos.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 16, 'Habite ricamente em vocês a palavra de Cristo; ensinem e aconselhem-se uns aos outros com toda a sabedoria, e cantem salmos, hinos e cânticos espirituais com gratidão a Deus em seus corações.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 17, 'Tudo o que fizerem, seja em palavra ou em ação, façam-no em nome do Senhor Jesus, dando por meio dele graças a Deus Pai.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 18, 'Mulheres, sujeitem-se a seus maridos, como convém a quem está no Senhor.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 19, 'Maridos, amem suas mulheres e não as tratem com amargura.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 20, 'Filhos, obedeçam a seus pais em tudo, pois isso agrada ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 21, 'Pais, não irritem seus filhos, para que eles não se desanimem.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 22, 'Escravos, obedeçam em tudo a seus senhores terrenos, não somente para agradar os homens quando eles estão observando, mas com sinceridade de coração, pelo fato de vocês temerem ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 23, 'Tudo o que fizerem, façam de todo o coração, como para o Senhor, e não para os homens,', 3, CURRENT_TIMESTAMP, false),
(51, 3, 24, 'sabendo que receberão do Senhor a recompensa da herança. É a Cristo, o Senhor, que vocês estão servindo.', 3, CURRENT_TIMESTAMP, false),
(51, 3, 25, 'Quem cometer injustiça receberá de volta injustiça, e não haverá exceção para ninguém.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 1, 'Senhores, dêem aos seus escravos o que é justo e direito, sabendo que vocês também têm um Senhor no céu.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 2, 'Dediquem-se à oração, estejam alertas e sejam agradecidos.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 3, 'Ao mesmo tempo, orem também por nós, para que Deus abra uma porta para a nossa mensagem, a fim de que possamos proclamar o mistério de Cristo, pelo qual estou preso.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 4, 'Orem para que eu possa manifestá-lo abertamente, como me cumpre fazê-lo.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 5, 'Sejam sábios no procedimento para com os de fora; aproveitem ao máximo todas as oportunidades.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 6, 'O seu falar seja sempre agradável e temperado com sal, para que saibam como responder a cada um.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 7, 'Tíquico lhes informará todas as coisas a meu respeito. Ele é um irmão amado, ministro fiel e cooperador no serviço do Senhor.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 8, 'Eu o envio a vocês precisamente com o propósito de que saibam de tudo o que se passa conosco, e para que ele fortaleça os seus corações.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 9, 'Ele irá com Onésimo, fiel e amado irmão, que é um de vocês. Eles irão contar-lhes tudo o que está acontecendo aqui.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 10, 'Aristarco, meu companheiro de prisão, envia-lhes saudações, bem como Marcos, primo de Barnabé. Vocês receberam instruções a respeito de Marcos, e se ele for visitá-los, recebam-no.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 11, 'Jesus, chamado Justo, também envia saudações. Estes são os únicos da circuncisão que são meus cooperadores em favor do Reino de Deus. Eles têm sido uma fonte de ânimo para mim.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 12, 'Epafras, que é um de vocês e servo de Cristo Jesus, envia saudações. Ele está sempre batalhando por vocês em oração, para que, como pessoas maduras e plenamente convictas, continuem firmes em toda a vontade de Deus.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 13, 'Dele dou testemunho de que se esforça muito por vocês e pelos que estão em Laodicéia e em Hierápolis.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 14, 'Lucas, o médico amado, e Demas, enviam saudações.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 15, 'Saúdem os irmãos de Laodicéia, bem como Ninfa e a igreja que se reúne em sua casa.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 16, 'Depois que esta carta for lida entre vocês, façam que também seja lida na igreja dos laodicenses, e que vocês igualmente leiam a carta de Laodicéia.', 3, CURRENT_TIMESTAMP, false),
(51, 4, 17, 'Digam a Arquipo: "Cuide em cumprir o ministério que você recebeu no Senhor".', 3, CURRENT_TIMESTAMP, false),
(51, 4, 18, 'Eu, Paulo, escrevo esta saudação de próprio punho. Lembrem-se das minhas algemas. A graça seja com vocês.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 1, 'No terceiro ano do reinado de Jeoaquim, rei de Judá, Nabucodonosor, rei da Babilônia, veio a Jerusalém e a sitiou.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 2, 'E o Senhor entregou Jeoaquim, rei de Judá, nas suas mãos, e também alguns dos utensílios do templo de Deus. Ele levou os utensílios para o templo do seu deus na terra de Sinear e os colocou na casa do tesouro do seu deus.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 3, 'Então o rei ordenou que Aspenaz, o chefe dos oficiais da sua corte, trouxesse alguns dos israelitas da família real e da nobreza;', 3, CURRENT_TIMESTAMP, false),
(27, 1, 4, 'jovens sem defeito físico, de boa aparência, cultos, inteligentes, que dominassem os vários campos do conhecimento e fossem capacitados para servir no palácio do rei. Ele devia ensinar-lhes a língua e a literatura dos babilônios.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 5, 'O rei designou-lhes uma porção diária de comida e de vinho da própria mesa do rei. Eles receberiam um treinamento durante três anos, e depois disso passariam a servir o rei.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 6, 'Entre esses estavam alguns que vieram de Judá: Daniel, Hananias, Misael e Azarias.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 7, 'O chefe dos oficiais deu-lhes novos nomes: a Daniel deu o nome de Beltessazar; a Hananias, Sadraque; a Misael, Mesaque; e a Azarias, Abede-Nego.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 8, 'Daniel, contudo, decidiu não se tornar impuro com a comida e com o vinho do rei, e pediu ao chefe dos oficiais permissão para se abster deles.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 9, 'E Deus fez com que o homem fosse bondoso para com Daniel e tivesse simpatia por ele.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 10, 'Apesar disso, ele disse a Daniel: "Tenho medo do rei, o meu senhor, que determinou a comida e a bebida de vocês. E se ele os achar menos saudáveis que os outros jovens da mesma idade? O rei poderia pedir a minha cabeça por causa de vocês".', 3, CURRENT_TIMESTAMP, false),
(27, 1, 11, 'Daniel disse então ao homem que o chefe dos oficiais tinha encarregado de cuidar de Daniel, Hananias, Misael e Azarias:', 3, CURRENT_TIMESTAMP, false),
(27, 1, 12, '"Peço-lhe que faça uma experiência com os seus servos durante dez dias: Não nos dê nada além de vegetais para comer e água para beber.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 13, 'Depois compare a nossa aparência com a dos jovens que comem a comida do rei, e trate os seus servos de acordo com o que você concluir".', 3, CURRENT_TIMESTAMP, false),
(27, 1, 14, 'Ele concordou e fez a experiência com eles durante dez dias.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 15, 'Passados os dez dias eles pareciam mais saudáveis e mais fortes do que todos os jovens que comiam a comida da mesa do rei.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 16, 'Assim o encarregado tirou a comida especial e o vinho que haviam sido designados e em lugar disso lhes dava vegetais.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 17, 'A esses quatro jovens Deus deu sabedoria e inteligência para conhecerem todos os aspectos da cultura e da ciência. E Daniel, além disso, sabia interpretar todo tipo de visões e sonhos.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 18, 'Ao final do tempo estabelecido pelo rei para que os jovens fossem trazidos à sua presença, o chefe dos oficiais os apresentou a Nabucodonosor.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 19, 'O rei conversou com eles, e não encontrou ninguém comparável a Daniel, Hananias, Misael e Azarias; de modo que eles passaram a servir o rei.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 20, 'O rei lhes fez perguntas sobre todos os assuntos nos quais se exigia sabedoria e conhecimento, e descobriu que eram dez vezes mais sábios do que todos os magos e encantadores de todo o seu reino.', 3, CURRENT_TIMESTAMP, false),
(27, 1, 21, 'E Daniel permaneceu ali até o primeiro ano do rei Ciro.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 1, 'No segundo ano de seu reinado, Nabucodonosor teve sonhos; sua mente ficou tão perturbada que ele não conseguia dormir.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 2, 'Por isso o rei convocou os magos, os encantadores, os feiticeiros e os astrólogos para que lhe dissessem o que ele havia sonhado. Quando eles vieram e se apresentaram ao rei,', 3, CURRENT_TIMESTAMP, false),
(27, 2, 3, 'ele lhes disse: "Tive um sonho que me perturba e quero saber o que significa".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 4, 'Então os astrólogos responderam em aramaico ao rei: "Ó rei, vive para sempre! Conta o sonho aos teus servos, e nós o interpretaremos".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 5, 'O rei respondeu aos astrólogos: "Esta é a minha decisão: Se vocês não me disserem qual foi o meu sonho e não o interpretarem, farei que vocês sejam cortados em pedaços e que as suas casas se tornem montes de entulho.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 6, 'Mas, se me revelarem o sonho e o interpretarem, eu lhes darei presentes e recompensas e grandes honrarias. Por isso, revelem-me o sonho e a sua interpretação".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 7, 'Mas eles tornaram a dizer: "Conte o rei o sonho a seus servos, e nós o interpretaremos".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 8, 'Então o rei respondeu: "Já descobri que vocês estão tentando ganhar tempo, pois sabem da minha decisão.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 9, 'Se não me contarem o sonho, todos vocês receberão a mesma sentença; pois vocês combinaram enganar-me com mentiras, esperando que a situação mudasse. Contem-me o sonho, e saberei que vocês são capazes de interpretá-lo para mim".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 10, 'Os astrólogos responderam ao rei: "Não há homem na terra que possa fazer o que o rei está pedindo! Nenhum rei, por maior e mais poderoso que tenha sido, chegou a pedir uma coisa dessas a nenhum mago, encantador ou astrólogo.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 11, 'O que o rei está pedindo é difícil demais; ninguém pode revelar isso ao rei, senão os deuses, e eles não vivem entre os mortais".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 12, 'Isso deixou o rei tão irritado e furioso que ele ordenou a execução de todos os sábios da Babilônia.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 13, 'E assim foi emitido o decreto para que fossem mortos os sábios; os encarregados saíram à procura de Daniel e dos seus amigos, para que também fossem mortos.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 14, 'Arioque, o comandante da guarda do rei, já se preparava para matar os sábios da Babilônia, quando Daniel dirigiu-se a ele com sabedoria e bom senso.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 15, 'Ele perguntou ao oficial do rei: "Por que o rei emitiu um decreto tão severo? " Arioque explicou o motivo a Daniel.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 16, 'Diante disso, Daniel foi pedir ao rei que lhe desse um prazo, e ele daria a interpretação.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 17, 'Daniel voltou para casa, contou o problema aos seus amigos Hananias, Misael e Azarias,', 3, CURRENT_TIMESTAMP, false),
(27, 2, 18, 'e lhes pediu que rogassem ao Deus dos céus que tivesse misericórdia acerca desse mistério, para que ele e seus amigos não fossem executados com os outros sábios da Babilônia.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 19, 'Então o mistério foi revelado a Daniel de noite, numa visão. Daniel louvou o Deus dos céus', 3, CURRENT_TIMESTAMP, false),
(27, 2, 20, 'e disse: "Louvado seja o nome de Deus para todo o sempre; a sabedoria e o poder a ele pertencem.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 21, 'Ele muda as épocas e as estações; destrona reis e os estabelece. Dá sabedoria aos sábios e conhecimento aos que sabem discernir.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 22, 'Revela coisas profundas e ocultas; conhece o que jaz nas trevas, e a luz habita com ele.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 23, 'Eu te agradeço e te louvo, ó Deus dos meus antepassados; tu me deste sabedoria e poder, e me revelaste o que te pedimos, revelaste-nos o sonho do rei".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 24, 'Então Daniel foi falar com Arioque, a quem o rei tinha nomeado para executar os sábios da Babilônia, e lhe disse: "Não execute os sábios. Leve-me ao rei, e eu interpretarei para ele o sonho que teve".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 25, 'Imediatamente Arioque levou Daniel ao rei e disse: "Encontrei um homem entre os exilados de Judá que pode dizer ao rei o significado do sonho".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 26, 'O rei perguntou a Daniel, também chamado Beltessazar: "Você é capaz de contar-me o que vi no meu sonho e interpretá-lo? "', 3, CURRENT_TIMESTAMP, false),
(27, 2, 27, 'Daniel respondeu: "Nenhum sábio, encantador, mago ou adivinho é capaz de revelar ao rei o mistério sobre o qual ele perguntou,', 3, CURRENT_TIMESTAMP, false),
(27, 2, 28, 'mas existe um Deus nos céus que revela os mistérios. Ele mostrou ao rei Nabucodonosor o que acontecerá nos últimos dias. O sonho e as visões que passaram por tua mente quando estavas deitado foram os seguintes:', 3, CURRENT_TIMESTAMP, false),
(27, 2, 29, '"Quando estavas deitado, ó rei, tua mente se voltou para as coisas futuras, e aquele que revela os mistérios te mostrou o que vai acontecer.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 30, 'Quanto a mim, esse mistério não me foi revelado porque eu tenha mais sabedoria do que os outros homens, mas para que tu ó rei, saibas a interpretação e entendas o que passou pela tua mente.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 31, '"Tu olhaste, ó rei, e diante de ti estava uma grande estátua: uma estátua enorme, impressionante, e sua aparência era terrível.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 32, 'A cabeça da estátua era feita de ouro puro, o peito e o braço eram de prata, o ventre e os quadris eram de bronze,', 3, CURRENT_TIMESTAMP, false),
(27, 2, 33, 'as pernas eram de ferro, e os pés eram em parte de ferro e em parte de barro.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 34, 'Enquanto estavas observando, uma pedra soltou-se, sem auxílio de mãos, atingiu a estátua nos pés de ferro e de barro e os esmigalhou.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 35, 'Então o ferro, o barro, o bronze, a prata e o ouro foram despedaçados, viraram pó, como o pó da debulha do trigo na eira durante o verão. O vento os levou sem deixar vestígio. Mas a pedra que atingiu a estátua tornou-se uma montanha e encheu a terra toda.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 36, '"Foi esse o sonho, e nós o interpretaremos para o rei.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 37, 'Tu, ó rei, és rei de reis. O Deus dos céus te tem dado domínio, poder, força e glória;', 3, CURRENT_TIMESTAMP, false),
(27, 2, 38, 'nas tuas mãos ele colocou a humanidade, os animais selvagens e as aves do céu. Onde quer que vivam, ele fez de ti o governante deles todos. Tu és a cabeça de ouro.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 39, '"Depois de ti surgirá um outro reino, inferior ao teu. Em seguida surgirá um terceiro reino, reino de bronze, que governará sobre toda a terra.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 40, 'Finalmente, haverá um quarto reino, forte como o ferro, pois o ferro quebra e destrói tudo; e assim como o ferro a tudo despedaça, também ele destruirá e quebrará todos os outros.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 41, 'Como viste, os pés e os dedos eram em parte de barro e em parte de ferro. Isso quer dizer que esse será um reino dividido, mas ainda assim terá um pouco da força do ferro, embora tenhas visto ferro misturado com barro.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 42, 'Assim como os dedos eram em parte de ferro e em parte de barro, também esse reino será em parte forte e em parte frágil.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 43, 'E, como viste, o ferro estava misturado com o barro. Isso quer dizer que se procurará fazer alianças políticas por meio de casamentos, mas essa união não se firmará, assim como o ferro não se mistura com o barro.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 44, '"Na época desses reis, o Deus dos céus estabelecerá um reino que jamais será destruído e que nunca será dominado por nenhum outro povo. Destruirá todos esses reinos e os exterminará, mas esse reino durará para sempre.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 45, 'Esse é o significado da visão da pedra que se soltou de uma montanha, sem auxílio de mãos, pedra que esmigalhou o ferro, o bronze, o barro, a prata e o ouro. "O Deus poderoso mostrou ao rei o que acontecerá no futuro. O sonho é verdadeiro, e a interpretação é fiel".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 46, 'Então o rei Nabucodonosor caiu prostrado diante de Daniel, prestou-lhe honra e ordenou que lhe fosse apresentada uma oferta de cereal e incenso.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 47, 'O rei disse a Daniel: "Não há dúvida de que o seu Deus é o Deus dos deuses, o Senhor dos reis e aquele que revela os mistérios, pois você conseguiu revelar esse mistério".', 3, CURRENT_TIMESTAMP, false),
(27, 2, 48, 'Então o rei colocou Daniel num alto cargo e o cobriu de presentes. Ele o designou governante de toda a província da Babilônia e o encarregou de todos os sábios da província.', 3, CURRENT_TIMESTAMP, false),
(27, 2, 49, 'Além disso, a pedido de Daniel, o rei nomeou Sadraque, Mesaque e Abede-Nego administradores da província da Babilônia, enquanto o próprio Daniel permanecia na corte do rei.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 1, 'O rei Nabucodonosor fez uma imagem de ouro de vinte e sete metros de altura e dois metros e setenta centímetros de largura, e a ergueu na planície de Dura, na província da Babilônia.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 2, 'Depois convocou os sátrapas, os prefeitos, os governadores, os conselheiros, os tesoureiros, os juízes, os magistrados e todas as autoridades provinciais para assistirem à dedicação da imagem que mandara erguer.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 3, 'Assim todos eles, sátrapas, prefeitos, governadores, conselheiros, tesoureiros, juízes, magistrados e todas as autoridades provinciais se reuniram para a dedicação da imagem que o rei Nabucodonosor mandara erguer, e ficaram de pé diante dela.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 4, 'Então o arauto proclamou em alta voz: "Esta é a ordem que lhes é dada, ó homens de todas nações, povos e línguas:', 3, CURRENT_TIMESTAMP, false),
(27, 3, 5, 'Quando ouvirem o som da trombeta, do pífaro, da cítara, da harpa, do saltério, da flauta dupla e de toda espécie de música, prostrem-se em terra e adorem a imagem de ouro que o rei Nabucodonosor ergueu.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 6, 'Quem não se prostrar em terra e não adorá-la será imediatamente atirado numa fornalha em chamas".', 3, CURRENT_TIMESTAMP, false),
(27, 3, 7, 'Por isso, logo que ouviram o som da trombeta, do pífaro, da cítara, da harpa, do saltério e de toda espécie de música, os homens de todas nações, povos e línguas prostraram-se em terra e adoraram a imagem de ouro que o rei Nabucodonosor mandara erguer.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 8, 'Nesse momento alguns astrólogos se aproximaram e denunciaram os judeus,', 3, CURRENT_TIMESTAMP, false),
(27, 3, 9, 'dizendo ao rei Nabucodonosor: "Ó rei, vive para sempre!', 3, CURRENT_TIMESTAMP, false),
(27, 3, 10, 'Tu emitiste um decreto, ó rei, ordenando que todo o que ouvisse o som da trombeta, do pífaro, da cítara, da harpa, do saltério, da flauta dupla e de toda espécie de música se prostrasse em terra e adorasse a imagem de ouro,', 3, CURRENT_TIMESTAMP, false),
(27, 3, 11, 'e que todo o que não se prostrasse em terra e não a adorasse seria atirado numa fornalha em chamas.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 12, 'Mas há alguns judeus que nomeaste para administrar a província da Babilônia, Sadraque, Mesaque e Abede-Nego, que não te dão ouvidos, ó rei. Não prestam culto aos teus deuses nem adoram a imagem de ouro que mandaste erguer".', 3, CURRENT_TIMESTAMP, false),
(27, 3, 13, 'Furioso, Nabucodonosor mandou chamar Sadraque, Mesaque e Abede-Nego. E assim que eles foram conduzidos à presença do rei,', 3, CURRENT_TIMESTAMP, false),
(27, 3, 14, 'Nabucodonosor lhes disse: "É verdade, Sadraque, Mesaque e Abede-Nego, que vocês não prestam culto aos meus deuses nem adoram a imagem de ouro que mandei erguer?', 3, CURRENT_TIMESTAMP, false),
(27, 3, 15, 'Agora, porém, quando vocês ouvirem o som da trombeta, do pífaro, da cítara, da harpa, do saltério, da flauta dupla e de toda espécie de música, se vocês se dispuserem a prostrar-se em terra e a adorar a imagem que eu fiz, será melhor para vocês. Mas, se não a adorarem, serão imediatamente atirados numa fornalha em chamas. E que deus poderá livrá-los das minhas mãos? "', 3, CURRENT_TIMESTAMP, false),
(27, 3, 16, 'Sadraque, Mesaque e Abede-Nego responderam ao rei: "Ó Nabucodonosor, não precisamos defender-nos diante de ti.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 17, 'Se formos atirados na fornalha em chamas, o Deus a quem prestamos culto pode livrar-nos, e ele nos livrará das suas mãos, ó rei.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 18, 'Mas, se ele não nos livrar, saiba, ó rei, que não prestaremos culto aos seus deuses nem adoraremos a imagem de ouro que mandaste erguer".', 3, CURRENT_TIMESTAMP, false),
(27, 3, 19, 'Nabucodonosor ficou tão furioso com Sadraque, Mesaque e Abede-Nego, que o seu semblante mudou. Deu ordens para que a fornalha fosse aquecida sete vezes mais do que de costume', 3, CURRENT_TIMESTAMP, false),
(27, 3, 20, 'e ordenou que alguns dos soldados mais fortes do seu exército amarrassem Sadraque, Mesaque e Abede-Nego e os atirassem na fornalha em chamas.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 21, 'E os três homens, vestidos com seus mantos, calções, turbantes e outras roupas, foram amarrados e atirados na fornalha extraordinariamente quente.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 22, 'A ordem do rei era tão urgente e a fornalha estava tão quente que as chamas mataram os soldados que levaram Sadraque, Mesaque e Abede-Nego,', 3, CURRENT_TIMESTAMP, false),
(27, 3, 23, 'os quais caíram amarrados dentro da fornalha em chamas.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 24, 'Mas, logo depois o rei Nabucodonosor, alarmado, levantou-se e perguntou aos seus conselheiros: "Não foram três homens amarrados que nós atiramos no fogo? " Eles responderam: "Sim, ó rei".', 3, CURRENT_TIMESTAMP, false),
(27, 3, 25, 'E o rei exclamou: "Olhem! Estou vendo quatro homens, desamarrados e ilesos, andando pelo fogo, e o quarto se parece com um filho dos deuses".', 3, CURRENT_TIMESTAMP, false),
(27, 3, 26, 'Então Nabucodonosor aproximou-se da entrada da fornalha em chamas e gritou: "Sadraque, Mesaque e Abede-Nego, servos do Deus Altíssimo, saiam! Venham aqui! " E Sadraque, Mesaque e Abede-Nego saíram do fogo.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 27, 'Os sátrapas, os prefeitos, os governadores e os conselheiros do rei se ajuntaram em torno deles e comprovaram que o fogo não tinha ferido o corpo deles. Nem um só fio do cabelo tinha sido chamuscado, os seus mantos não estavam queimados, e não havia cheiro de fogo neles.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 28, 'Disse então Nabucodonosor: "Louvado seja o Deus de Sadraque, Mesaque e Abede-Nego, que enviou o seu anjo e livrou os seus servos! Eles confiaram nele, desafiaram a ordem do rei, preferindo abrir mão de suas vidas a que prestar culto e adorar a outro deus, que não fosse o seu próprio Deus.', 3, CURRENT_TIMESTAMP, false),
(27, 3, 29, 'Por isso eu decreto que todo homem de qualquer povo, nação e língua que disser alguma coisa contra o Deus de Sadraque, Mesaque e Abede-Nego seja despedaçado e sua casa seja transformada em montes de entulho, pois nenhum outro deus é capaz de livrar ninguém dessa maneira".', 3, CURRENT_TIMESTAMP, false),
(27, 3, 30, 'Então o rei promoveu Sadraque, Mesaque e Abede-Nego a melhores posições na província da Babilônia.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 1, 'O rei Nabucodonosor, aos homens de todas nações, povos e línguas, que vivem no mundo inteiro: Paz e prosperidade!', 3, CURRENT_TIMESTAMP, false),
(27, 4, 2, 'Tenho a satisfação de falar-lhes a respeito dos sinais e das maravilhas que o Deus Altíssimo realizou para mim.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 3, 'Como são grandes os seus sinais, como são poderosas as suas maravilhas! O seu reino é um reino eterno; o seu domínio dura de geração em geração.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 4, 'Eu, Nabucodonosor, estava satisfeito e próspero em casa, no meu palácio.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 5, 'Tive um sonho que me deixou alarmado. Estando eu deitado em minha cama, os pensamentos e visões que passaram pela minha mente deixaram-me aterrorizado.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 6, 'Por isso decretei que todos os sábios da Babilônia fossem trazidos à minha presença para interpretarem o sonho para mim.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 7, 'Quando os magos, os encantadores, os astrólogos e os adivinhos vieram, contei-lhes o sonho, mas eles não puderam interpretá-lo.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 8, 'Por fim veio Daniel à minha presença e eu lhe contei o sonho. Ele é chamado Beltessazar, em homenagem ao nome do meu deus; e o espírito dos santos deuses está nele.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 9, 'Eu disse: "Beltessazar, chefe dos magos, sei que o espírito dos santos deuses está em você, e que nenhum mistério é difícil demais para você. Vou contar-lhe o meu sonho; interprete-o para mim.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 10, 'Estas são as visões que tive quando estava deitado na minha cama: olhei, e ali diante de mim estava uma árvore muito alta no meio da terra.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 11, 'A árvore cresceu tanto que a sua copa encostou no céu; era visível até os confins da terra.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 12, 'Tinha belas folhas, muitos frutos, e nela havia alimento para todos. Debaixo dela os animais do campo achavam abrigo, e as aves do céu viviam em seus galhos; todas as criaturas se alimentavam da árvore.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 13, '"Nas visões que tive deitado em minha cama, olhei e vi diante de mim uma sentinela, um anjo que descia do céu;', 3, CURRENT_TIMESTAMP, false),
(27, 4, 14, 'e ele gritou em alta voz: ‘Derrubem a árvore e cortem os seus galhos; arranquem as suas folhas e espalhem os seus frutos. Fujam os animais de debaixo dela e as aves dos seus galhos.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 15, 'Mas deixem o toco e as suas raízes, presos com ferro e bronze; fique ele no chão, em meio a relva do campo’. "Ele será molhado com o orvalho do céu e com os animais comerá a grama da terra.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 16, 'A mente humana lhe será tirada, e ele será como um animal, até que se passem sete tempos.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 17, '"A decisão é anunciada por sentinelas, os anjos declaram o veredicto, para que todos os que vivem saibam que o Altíssimo domina sobre os reinos dos homens e os dá a quem quer, e põe no poder o homem mais simples.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 18, '"Esse é o sonho que eu, o rei Nabucodonosor, tive. Agora, Beltessazar, diga-me o significado do sonho, pois nenhum dos sábios do meu reino consegue interpretá-lo para mim, exceto você, pois o espírito dos santos deuses está em você".', 3, CURRENT_TIMESTAMP, false),
(27, 4, 19, 'Então Daniel, também chamado Beltessazar, ficou estarrecido por algum tempo, e os seus pensamentos o deixaram aterrorizado. Então o rei disse: "Beltessazar, não deixe que o sonho ou a sua interpretação o assuste". Beltessazar respondeu: "Meu senhor, quem dera o sonho só se aplicasse aos seus inimigos e o seu significado somente aos seus adversários!', 3, CURRENT_TIMESTAMP, false),
(27, 4, 20, 'A árvore que viste, que cresceu e ficou enorme, e a sua copa encostava no céu, visível em toda a terra,', 3, CURRENT_TIMESTAMP, false),
(27, 4, 21, 'que também tinha belas folhas e muitos frutos, na qual havia alimento para todos, abrigo para os animais do campo, e morada para as aves do céu nos seus galhos,', 3, CURRENT_TIMESTAMP, false),
(27, 4, 22, 'és tu, ó rei! Tu te tornaste grande e poderoso, pois a tua grandeza cresceu até alcançar o céu, e o teu domínio se estende até os confins da terra.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 23, '"E tu, ó rei, viste também uma sentinela, o anjo que descia do céu e dizia: ‘Derrubem a árvore e destruam-na, mas deixem o toco e as suas raízes, presos com ferro e bronze; fique ele no chão, em meio a relva do campo. Ele será molhado com o orvalho do céu e viverá com os animais selvagens, até que se passem sete tempos’.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 24, '"Esta é a interpretação, ó rei, e este é o decreto que o Altíssimo emitiu contra o rei, meu senhor:', 3, CURRENT_TIMESTAMP, false),
(27, 4, 25, 'Tu serás expulso do meio dos homens e viverás com os animais selvagens; comerás capim como os bois e te molharás com o orvalho do céu. Passarão sete tempos até que admitas que o Altíssimo domina sobre os reinos dos homens e os dá a quem quer.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 26, 'A ordem para deixar o toco da árvore com as raízes significa que o teu reino te será devolvido quando reconheceres que os Céus dominam.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 27, 'Portanto, ó rei, aceita o meu conselho: Renuncia a teus pecados e à tua maldade, pratique a justiça e tenha compaixão dos necessitados. Talvez, então, continues a viver em paz".', 3, CURRENT_TIMESTAMP, false),
(27, 4, 28, 'Tudo isso aconteceu com o rei Nabucodonosor.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 29, 'Doze meses depois, quando o rei estava andando no terraço do palácio real da Babilônia,', 3, CURRENT_TIMESTAMP, false),
(27, 4, 30, 'disse: "Acaso não é esta a grande Babilônia que eu construí como capital do meu reino, com o meu enorme poder e para a glória da minha majestade? "', 3, CURRENT_TIMESTAMP, false),
(27, 4, 31, 'As palavras ainda estavam nos seus lábios quando veio do céu uma voz que disse: "É isto que está decretado quanto a você, rei Nabucodonosor: Sua autoridade real lhe foi tirada.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 32, 'Você será expulso do meio dos homens, viverá com os animais selvagens e comerá capim como os bois. Passarão sete tempos até que admita que o Altíssimo domina sobre os reinos dos homens e os dá a quem quer".', 3, CURRENT_TIMESTAMP, false),
(27, 4, 33, 'A sentença sobre Nabucodonosor cumpriu-se imediatamente. Ele foi expulso do meio dos homens e passou a comer capim como os bois. Seu corpo molhou-se com o orvalho do céu, até que os seus cabelos e pêlos cresceram como as penas de uma águia, e as suas unhas como as garras de uma ave.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 34, 'Ao fim daquele período, eu, Nabucodonosor, levantei os olhos ao céu, e percebi que o meu entendimento tinha voltado. Então louvei o Altíssimo; honrei e glorifiquei aquele que vive para sempre. O seu domínio é um domínio eterno; o seu reino dura de geração em geração.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 35, 'Todos os povos da terra são como nada diante dele. Ele age como lhe agrada com os exércitos dos céus e com os habitantes da terra. Ninguém é capaz de resistir à sua mão nem de dizer-lhe: "O que fizeste? "', 3, CURRENT_TIMESTAMP, false),
(27, 4, 36, 'Naquele momento voltou-me o entendimento, e eu recuperei a honra a majestade e a glória do meu reino. Meus conselheiros e nobres me procuraram, meu trono me foi restaurado, e minha grandeza veio a ser ainda maior.', 3, CURRENT_TIMESTAMP, false),
(27, 4, 37, 'Agora eu, Nabucodonosor, louvo e exalto e glorifico o Rei dos céus, porque tudo o que ele faz é certo, e todos os seus caminhos são justos. E ele tem poder para humilhar aqueles que vivem com arrogância.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 1, 'Certa vez o rei Belsazar deu um grande banquete para mil dos seus nobres, e eles beberam muito vinho.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 2, 'Enquanto Belsazar bebia vinho, deu ordens para trazerem as taças de ouro e de prata que o seu predecessor, Nabucodonosor, tinha tomado do templo de Jerusalém, para que o rei e os seus nobres, as suas mulheres e as suas concubinas bebessem nessas taças.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 3, 'Então trouxeram as taças de ouro que tinham sido tomadas do templo de Deus em Jerusalém; e o rei e os seus nobres, as suas mulheres e as suas concubinas, beberam nas taças.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 4, 'Enquanto bebiam o vinho, louvaram os deuses de ouro, de prata, de bronze, de ferro, de madeira e de pedra.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 5, 'Mas, de repente apareceram dedos de mão humana que começaram a escrever no reboco da parede, da parte mais iluminada do palácio real. O rei observou a mão enquanto ela escrevia.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 6, 'Seu rosto ficou pálido, e ele ficou tão assustado que os seus joelhos batiam e as suas pernas vacilaram.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 7, 'Aos gritos, o rei mandou chamar os encantadores, os astrólogos e os adivinhos e disse a esses sábios da Babilônia: "Aquele que ler essa inscrição e interpretá-la, revelando-me o seu significado, vestirá um manto vermelho, terá uma corrente de ouro no pescoço, e será o terceiro em importância no governo do reino".', 3, CURRENT_TIMESTAMP, false),
(27, 5, 8, 'Todos os sábios do rei vieram, mas não conseguiram ler a inscrição nem dizer ao rei o seu significado.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 9, 'Diante disso o rei Belsazar ficou ainda mais aterrorizado e o seu rosto, mais pálido. Seus nobres estavam alarmados.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 10, 'E tendo a rainha, ouvido os gritos do rei e de seus nobres, entrou na sala do banquete e disse: "Ó rei, vive para sempre! Não fiques assustado nem tão pálido!', 3, CURRENT_TIMESTAMP, false),
(27, 5, 11, 'Existe um homem em teu reino que possui o espírito dos santos deuses. Na época do teu predecessor verificou-se que ele tinha percepção, inteligência e sabedoria como a dos deuses. O rei Nabucodonosor, teu predecessor, sim, teu predecessor, o rei, o nomeou chefe dos magos, dos encantadores, dos astrólogos e dos adivinhos.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 12, 'Verificou-se que esse homem, Daniel, a quem o rei dera o nome de Beltessazar, tinha inteligência extraordinária e também a capacidade de interpretar sonhos e resolver enigmas e mistérios. Manda chamar Daniel, e ele te dará o significado da escrita".', 3, CURRENT_TIMESTAMP, false),
(27, 5, 13, 'Assim Daniel foi levado à presença do rei, que lhe disse: "Você é Daniel, um dos exilados que meu pai, o rei, trouxe de Judá?', 3, CURRENT_TIMESTAMP, false),
(27, 5, 14, 'Soube que o espírito dos deuses está em você e que você possui percepção, inteligência e uma sabedoria fora do comum.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 15, 'Trouxeram os sábios e os encantadores à minha presença para lerem essa inscrição e me dizerem o seu significado, eles porém não conseguiram.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 16, 'Mas eu soube que você é capaz de dar interpretações e de resolver mistérios. Se você puder ler essa inscrição e dar-me o seu significado, você será vestido de vermelho e terá uma corrente de ouro no pescoço, e se tornará o terceiro em importância no governo do reino".', 3, CURRENT_TIMESTAMP, false),
(27, 5, 17, 'Então Daniel respondeu ao rei: "Podes guardar os teus presentes para ti mesmo e dar as tuas recompensas a algum outro. No entanto, eu lerei a inscrição para o rei e lhe direi o seu significado.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 18, '"Ó rei, foi a Nabucodonosor, teu predecessor que o Deus Altíssimo deu soberania, grandeza, glória e majestade.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 19, 'Devido à alta posição que lhe concedeu, homens de todas as nações, povos e línguas tremiam diante dele e o temiam. A quem o rei queria matar, matava; a quem queria poupar, poupava; a quem queria promover, promovia; e a quem queria humilhar, humilhava.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 20, 'Mas, quando o seu coração se tornou arrogante e endurecido por causa do orgulho, ele foi deposto de seu trono real e despojado da sua glória.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 21, 'Foi expulso do meio dos homens e sua mente ficou como a de um animal; ele passou a viver com os jumentos selvagens e a comer capim como os bois; e o seu corpo se molhava com o orvalho do céu, até reconhecer que o Deus Altíssimo domina sobre os reinos dos homens e coloca no poder a quem ele quer.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 22, '"Mas tu, Belsazar, seu sucessor, não te humilhaste, embora soubesses de tudo isso.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 23, 'Pelo contrário, tu te exaltaste acima do Senhor dos céus. Mandaste trazer as taças do templo do Senhor para que nelas bebessem tu, os teus nobres, as tuas mulheres e as tuas concubinas. Louvaste os deuses de prata, de ouro, de bronze, de ferro, de madeira e de pedra, que não podem ver nem ouvir nem entender. Mas não glorificaste o Deus que sustenta em suas mãos a tua vida e todos os teus caminhos.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 24, 'Por isso ele enviou a mão que escreveu as palavras da inscrição.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 25, '"Esta é a inscrição que foi feita: MENE, MENE, TEQUEL, PARSIM.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 26, '"E este é o significado dessas palavras: Mene: Deus contou os dias do teu reinado e determinou o seu fim.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 27, 'Tequel: Foste pesado na balança e achado em falta.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 28, 'Peres: Teu reino foi dividido e entregue aos medos e persas".', 3, CURRENT_TIMESTAMP, false),
(27, 5, 29, 'Então, por ordem de Belsazar, vestiram Daniel com um manto vermelho, puseram-lhe uma corrente de ouro no pescoço, e o proclamaram o terceiro em importância no governo do reino.', 3, CURRENT_TIMESTAMP, false),
(27, 5, 30, 'Naquela mesma noite Belsazar, rei dos babilônios, foi morto,', 3, CURRENT_TIMESTAMP, false),
(27, 5, 31, 'e Dario, o medo, apoderou-se do reino, com a idade de sessenta e dois anos.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 1, 'Dario achou por bem nomear cento e vinte sátrapas para governarem todo o reino;', 3, CURRENT_TIMESTAMP, false),
(27, 6, 2, 'e colocou três supervisores sobre eles, um dos quais era Daniel. Os sátrapas tinham que prestar contas a eles para que o rei não sofresse nenhuma perda.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 3, 'Ora, Daniel se destacou tanto entre os supervisores e os sátrapas por suas grandes qualidades, que o rei planejava colocá-lo à frente do governo de todo o império.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 4, 'Diante disso, os supervisores e os sátrapas procuraram motivos para acusar Daniel em sua administração governamental, mas nada conseguiram. Não puderam achar falta alguma nele, pois ele era fiel; não era desonesto nem negligente.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 5, 'Finalmente esses homens disseram: "Jamais encontraremos algum motivo para acusar esse Daniel, a menos que seja algo relacionado com a lei do Deus dele".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 6, 'E assim os supervisores e os sátrapas de comum acordo foram falar com o rei: "Ó rei Dario, vive para sempre!', 3, CURRENT_TIMESTAMP, false),
(27, 6, 7, 'Todos os supervisores reais, os prefeitos, os sátrapas, os conselheiros e os governadores concordaram em que o rei deve emitir um decreto ordenando que todo aquele que orar a qualquer deus ou a qualquer homem nos próximos trinta dias, exceto a ti, ó rei, seja atirado na cova dos leões.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 8, 'Agora, ó rei, emite o decreto e assina-o para que não seja alterado, conforme a lei dos medos e dos persas, que não pode ser revogada".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 9, 'E o rei Dario assinou o decreto.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 10, 'Quando Daniel soube que o decreto tinha sido publicado, foi para casa, para o seu quarto, no andar de cima, onde as janelas davam para Jerusalém. Três vezes por dia ele se ajoelhava e orava, agradecendo ao seu Deus, como costumava fazer.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 11, 'Então aqueles homens foram ver e encontraram Daniel orando, pedindo ajuda a Deus.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 12, 'Assim foram falar com o rei acerca do decreto real: "Tu não publicaste um decreto ordenando que nos próximos trinta dias todo aquele que fizesse algum pedido a qualquer deus ou a qualquer homem, exceto a ti, ó rei, seria lançado na cova dos leões? " O rei respondeu: "O decreto está em vigor, conforme a lei dos medos e dos persas, que não pode ser revogada".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 13, 'Então disseram ao rei: "Daniel, um dos exilados de Judá, não te dá ouvidos, ó rei, nem ao decreto que assinaste. Ele continua orando três vezes por dia".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 14, 'Quando o rei ouviu isso, ficou muito contrariado, e como estava decidido a salvar Daniel, até o pôr-do-sol fez todo o esforço que pôde para livrá-lo.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 15, 'Mas os homens lhe disseram: "Lembra-te, ó rei, que, conforme a lei dos medos e dos persas, nenhum decreto ou edito do rei pode ser modificado".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 16, 'Então o rei deu ordens, e eles trouxeram Daniel e o jogaram na cova dos leões. O rei, porém, disse a Daniel: "Que o seu Deus, a quem você serve continuamente, o livre! "', 3, CURRENT_TIMESTAMP, false),
(27, 6, 17, 'Taparam a cova com uma pedra, e o rei a selou com o seu próprio anel-selo e com os anéis dos seus nobres, para que a situação de Daniel não se modificasse.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 18, 'Tendo voltado ao palácio, o rei passou a noite sem comer e não aceitou nenhum divertimento em sua presença. Além disso, não conseguiu dormir.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 19, 'Logo ao alvorecer, o rei se levantou e correu para a cova dos leões.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 20, 'Quando ia se aproximando da cova, chamou Daniel com voz aflita: "Daniel, servo do Deus vivo, será que o seu Deus, a quem você serve continuamente, pôde livrá-lo dos leões? "', 3, CURRENT_TIMESTAMP, false),
(27, 6, 21, 'Daniel respondeu: "Ó rei, vive para sempre!', 3, CURRENT_TIMESTAMP, false),
(27, 6, 22, 'O meu Deus enviou o seu anjo, que fechou a boca dos leões. Eles não me fizeram mal algum, pois fui considerado inocente à vista de Deus. Também contra ti não cometi mal algum, ó rei".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 23, 'O rei muito se alegrou e ordenou que tirassem Daniel da cova. Quando o tiraram da cova, viram que não havia nele nenhum ferimento, pois ele tinha confiado no seu Deus.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 24, 'E por ordem do rei, os homens que tinham acusado Daniel foram atirados na cova dos leões, juntamente com as suas mulheres e os seus filhos. E, antes de chegarem ao fundo, os leões os atacaram e despedaçaram todos os seus ossos.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 25, 'Então o rei Dario escreveu aos homens de todas as nações, povos e línguas de toda a terra: "Paz e prosperidade!', 3, CURRENT_TIMESTAMP, false),
(27, 6, 26, '"Estou editando um decreto para que nos domínios do império os homens temam e reverenciem o Deus de Daniel. "Pois ele é o Deus vivo e permanece para sempre; o seu reino não será destruído, o seu domínio jamais acabará.', 3, CURRENT_TIMESTAMP, false),
(27, 6, 27, 'Ele livra e salva; faz sinais e maravilhas nos céus e na terra. Ele livrou Daniel do poder dos leões".', 3, CURRENT_TIMESTAMP, false),
(27, 6, 28, 'Assim Daniel prosperou durante os reinados de Dario e de Ciro, o persa.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 1, 'No primeiro ano de Belsazar, rei da Babilônia, Daniel teve um sonho, e certas visões passaram por sua mente, estando ele deitado em sua cama. Ele escreveu o resumo do seu sonho.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 2, 'Daniel disse: "Na minha visão à noite, eu vi os quatro ventos do céu agitando o grande mar.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 3, 'Quatro grandes animais, cada um diferente dos outros, subiram do mar.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 4, '"O primeiro parecia um leão, e tinha as asas de águia. Eu o observei até que as suas asas foram arrancadas, e ele foi erguido do chão de modo que levantou-se sobre dois pés como um homem, e recebeu coração de homem.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 5, '"A seguir vi um segundo animal, que tinha a aparência de um urso. Ele foi erguido por um dos seus lados, e na boca, entre os dentes, tinha três costelas. E lhe foi dito: ‘Levante-se e coma quanta carne puder! ’', 3, CURRENT_TIMESTAMP, false),
(27, 7, 6, '"Depois disso, vi um outro animal, que se parecia com um leopardo. E nas costas tinha quatro asas, como asas de uma ave. Esse animal tinha quatro cabeças, e recebeu autoridade para governar.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 7, '"Na minha visão à noite, vi ainda um quarto animal, aterrorizante, assustador e muito poderoso. Tinha grandes dentes de ferro, com as quais despedaçava e devorava suas vítimas, e pisoteava tudo o que sobrava. Era diferente de todos os animais anteriores, e tinha dez chifres.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 8, '"Enquanto eu estava refletindo nos chifres, vi um outro chifre, pequeno, que surgiu entre eles; e três dos primeiros chifres foram arrancados para dar lugar a ele. Esse chifre possuía olhos como os olhos de um homem e uma boca que falava com arrogância.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 9, '"Enquanto eu olhava, "tronos foram postos no lugar, e um ancião se assentou. Sua veste era branca como a neve; o cabelo era branco como a lã. Seu trono ardia em fogo, e as rodas do trono estavam todas incandescentes.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 10, 'E saía um rio de fogo, de diante dele. Milhares de milhares o serviam; milhões e milhões estavam diante dele. O tribunal iniciou o julgamento, e os livros foram abertos.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 11, '"Continuei a observar por causa das palavras arrogantes que o chifre falava. Fiquei olhando até que o animal foi morto, e o seu corpo foi destruído e atirado no fogo.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 12, 'E foi tirada a autoridade dos outros animais, mas eles tiveram permissão para viver por um período de tempo.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 13, '"Na minha visão à noite, vi alguém semelhante a um filho de um homem, vindo com as nuvens dos céus. Ele se aproximou do ancião e foi conduzido à sua presença.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 14, 'A ele foram dados autoridade, glória e reino; todos os povos, nações e homens de todas as línguas o adoraram. Seu domínio é um domínio eterno que não acabará, e seu reino jamais será destruído.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 15, '"Eu, Daniel, fiquei agitado em meu espírito, e as visões que passaram pela minha mente me aterrorizaram.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 16, 'Então me aproximei de um dos que ali estavam e lhe perguntei o significado disso tudo. "E ele me respondeu, dando-me a interpretação:', 3, CURRENT_TIMESTAMP, false),
(27, 7, 17, '‘Os quatro grandes animais são quatro reinos que se levantarão na terra.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 18, 'Mas os santos do Altíssimo receberão o reino e o possuirão para sempre; sim, para todo o sempre’.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 19, '"Então eu quis saber o significado do quarto animal, diferente de todos os outros e o mais aterrorizante, com seus dentes de ferro e garras de bronze, o animal que despedaçava e devorava suas vítimas, e pisoteava tudo o que sobrava.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 20, 'E também quis saber sobre os dez chifres da sua cabeça e sobre o outro chifre que surgiu para ocupar o lugar dos três chifres que caíram, o chifre que era maior do que os demais e que tinha olhos e uma boca que falava com arrogância.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 21, 'Enquanto eu observava, esse chifre guerreava contra os santos e os derrotava,', 3, CURRENT_TIMESTAMP, false),
(27, 7, 22, 'até que o ancião veio e pronunciou a sentença a favor dos santos do Altíssimo, e chegou a hora de eles tomarem posse do reino.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 23, '"Ele me deu a seguinte explicação: ‘O quarto animal é um quarto reino que aparecerá na terra. Será diferente de todos os outros reinos e devorará a terra inteira, despedaçando-a e pisoteando-a.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 24, 'Os dez chifres são dez reis que sairão desse reino. Depois deles um outro rei se levantará, e será diferente dos primeiros reis.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 25, 'Ele falará contra o Altíssimo, oprimirá os seus santos e tentará mudar os tempos e as leis. Os santos serão entregues nas mãos dele por um tempo, tempos e meio tempo’.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 26, '"Mas o tribunal o julgará, e o seu poder será tirado e totalmente destruído para sempre.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 27, 'Então a soberania, o poder e a grandeza dos reinos debaixo de todo o céu serão entregues nas mãos dos santos, o povo do Altíssimo. O reino dele será um reino eterno, e todos os governantes o adorarão e lhe obedecerão.', 3, CURRENT_TIMESTAMP, false),
(27, 7, 28, '"Esse é o fim da visão. Eu, Daniel, fiquei aterrorizado por causa de meus pensamentos, e meu rosto empalideceu, mas guardei essas coisas comigo".', 3, CURRENT_TIMESTAMP, false),
(27, 8, 1, 'No terceiro ano do reinado do rei Belsazar, eu, Daniel, tive outra visão, depois da primeira.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 2, 'Na minha visão eu me vi na cidadela de Susã, na província de Elão; na visão eu estava junto do canal de Ulai.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 3, 'Olhei para cima, e diante de mim, junto ao canal, estava um carneiro, seus dois chifres eram compridos, um mais que o outro, mas o mais comprido cresceu depois do outro.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 4, 'Observei o carneiro enquanto ele avançava para o oeste, para o norte e para o sul. Nenhum animal conseguia resistir-lhe, e ninguém podia livrar-se do seu poder. Ele fazia o que bem queria e foi ficando cada vez maior.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 5, 'Enquanto eu estava considerando isso, de repente um bode, com um chifre enorme entre os olhos, veio do oeste, percorrendo toda a extensão da terra sem encostar no chão.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 6, 'Ele veio na direção do carneiro de dois chifres que eu tinha visto ao lado do canal, e avançou contra ele com grande fúria.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 7, 'Eu o vi atacar furiosamente o carneiro, atingi-lo e quebrar os seus dois chifres. O carneiro não teve forças para resistir-lhe; o bode o derrubou no chão e o pisoteou, e ninguém foi capaz de livrar o carneiro do seu poder.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 8, 'O bode tornou-se muito grande, mas no auge da sua força o seu grande chifre foi quebrado, e em seu lugar cresceram quatro chifres enormes, na direção dos quatro ventos da terra.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 9, 'De um deles saiu um outro chifre, que começou pequeno, mas cresceu em poder na direção do sul, do leste e da Terra Magnífica.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 10, 'Cresceu até alcançar o exército dos céus, e atirou na terra alguns componentes do exército das estrelas e os pisoteou.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 11, 'Tanto cresceu que chegou a desafiar o príncipe do exército; suprimiu o sacrifício diário oferecido ao príncipe, e o local do santuário foi destruído.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 12, 'Por causa da rebelião, o exército dos santos e o sacrifício diário foram dados ao chifre. Ele tinha êxito em tudo o que fazia, e a verdade foi lançada por terra.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 13, 'Então ouvi dois anjos conversando, e um deles perguntou ao outro: "Quanto tempo durarão os acontecimentos anunciados por essa visão? Até quando será suprimido o sacrifício diário e a rebelião devastadora prevalecerá? Até quando o santuário e o exército ficarão entregues ao poder do chifre e serão pisoteados? "', 3, CURRENT_TIMESTAMP, false),
(27, 8, 14, 'Ele me disse: "Isso tudo levará duas mil e trezentas tardes e manhãs; então o santuário será reconsagrado".', 3, CURRENT_TIMESTAMP, false),
(27, 8, 15, 'Enquanto eu, Daniel, observava a visão e tentava entendê-la, diante de mim apareceu um ser que parecia homem.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 16, 'E ouvi a voz de um homem que vinha do Ulai: "Gabriel, dê a esse homem o significado da visão".', 3, CURRENT_TIMESTAMP, false),
(27, 8, 17, 'Quando ele se aproximou de mim, fiquei aterrorizado e caí prostrado. E ele me disse: "Filho do homem, saiba que a visão refere-se aos tempos do fim".', 3, CURRENT_TIMESTAMP, false),
(27, 8, 18, 'Enquanto ele falava comigo, caí prostrado, rosto em terra, e perdi os sentidos. Então ele tocou em mim e me pôs de pé.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 19, 'E disse: "Vou contar-lhe o que acontecerá depois, no tempo da ira, pois a visão se refere ao tempo do fim.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 20, 'O carneiro de dois chifres que você viu representa os reis da Média e da Pérsia.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 21, 'O bode peludo é o rei da Grécia, e o grande chifre entre os seus olhos é o primeiro rei.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 22, 'Os quatro chifres que tomaram o lugar do chifre que foi quebrado são quatro reinos que surgirão da nação daquele rei, mas não terão o mesmo poder.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 23, '"No final do reinado deles, quando a rebelião dos ímpios tiver chegado ao máximo, surgirá um rei de duro semblante, mestre em astúcias.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 24, 'Ele se tornará muito forte, mas não pelo seu próprio poder. Provocará devastações terríveis e será bem sucedido em tudo o que fizer. Destruirá os homens poderosos e o povo santo.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 25, 'Com o intuito de prosperar, ele enganará a muitos, e se considerará superior aos outros. Destruirá muitos que nele confiam e se insurgirá contra o Príncipe dos príncipes. Apesar disso, ele será destruído, mas não pelo poder dos homens.', 3, CURRENT_TIMESTAMP, false),
(27, 8, 26, '"A visão das tardes e das manhãs que você recebeu é verdadeira; sela porém a visão, pois refere-se ao futuro distante".', 3, CURRENT_TIMESTAMP, false),
(27, 8, 27, 'Eu, Daniel, fiquei exausto e doente por vários dias. Depois levantei-me e voltei a cuidar dos negócios do rei. Fiquei assustado com a visão; estava além da compreensão.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 1, 'Dario, filho de Xerxes, de origem meda, foi constituído governante do reino babilônio.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 2, 'No primeiro ano do seu reinado, eu, Daniel, compreendi pelas Escrituras, conforme a palavra do Senhor dada ao profeta Jeremias, que a desolação de Jerusalém iria durar setenta anos.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 3, 'Por isso me voltei para o Senhor Deus com orações e súplicas, em jejum, em pano de saco e coberto de cinza.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 4, 'Orei ao Senhor, ao meu Deus, e confessei: "Ó Senhor, Deus grande e temível, que mantém a sua aliança de amor com todos aqueles que o amam e obedecem aos seus mandamentos,', 3, CURRENT_TIMESTAMP, false),
(27, 9, 5, 'nós temos pecado e somos culpados. Temos sido ímpios e rebeldes, e nos afastamos dos teus mandamentos e das tuas leis.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 6, 'Não demos ouvido aos teus servos, os profetas, que falaram em teu nome aos nossos reis, aos nossos líderes e aos nossos antepassados, e a todo o povo desta terra.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 7, '"Senhor, tu és justo, e hoje estamos envergonhados. Sim, nós, o povo de Judá, de Jerusalém e de todo o Israel, tanto os que estão perto como os que estão distantes, em todas as terras pelas quais nos espalhaste por causa de nossa infidelidade para contigo.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 8, 'Ó Senhor, nós e nossos reis, nossos líderes e nossos antepassados estamos envergonhados por termos pecado contra ti.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 9, 'O Senhor nosso Deus é misericordioso e perdoador, apesar de termos sido rebeldes;', 3, CURRENT_TIMESTAMP, false),
(27, 9, 10, 'não te demos ouvidos, Senhor, nosso Deus, nem obedecemos às leis que nos deste por meio dos teus servos, os profetas.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 11, 'Todo o Israel tem transgredido a tua lei e se desviou, recusando-se a te ouvir. "Por isso as maldições e as pragas escritas na Lei de Moisés, servo de Deus, têm sido derramadas sobre nós, porque temos pecado contra ti.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 12, 'Tu tens cumprido as palavras faladas contra nós e contra os nossos governantes, trazendo-nos grande desgraça. Debaixo de todo o céu jamais se fez algo como o que foi feito a Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 13, 'Assim como está escrito na Lei de Moisés, toda essa desgraça nos atingiu, e ainda assim não temos buscado o favor do Senhor, do nosso Deus, afastando-nos de nossas maldades e obedecendo à tua verdade.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 14, 'O Senhor não hesitou em trazer desgraça sobre nós, pois o Senhor, o nosso Deus, é justo em tudo o que faz; ainda assim nós não o temos ouvido.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 15, 'Ó Senhor, nosso Deus, que tiraste o teu povo do Egito com mão poderosa e que fizeste para ti um nome que permanece até hoje, nós temos pecado e somos culpados.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 16, 'Agora Senhor, conforme todos os teus feitos justos, afasta de Jerusalém, da tua cidade, do teu santo monte, a tua ira e a tua indignação. Os nossos pecados e as iniqüidades de nossos antepassados fizeram de Jerusalém e do teu povo motivo de zombaria para todos os que nos rodeiam.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 17, 'Ouve, nosso Deus, as orações e as súplicas do teu servo. Por amor de ti, Senhor, olha com bondade para o teu santuário abandonado.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 18, 'Inclina os teus ouvidos, ó Deus, e ouve; abre os teus olhos e vê a desolação da cidade que leva o teu nome. Não te fazemos pedidos por sermos justos, mas por causa da tua grande misericórdia.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 19, 'Senhor, ouve! Senhor, perdoa! Senhor, vê e age! Por amor de ti, meu Deus, não te demores, pois a tua cidade e o teu povo levam o teu nome".', 3, CURRENT_TIMESTAMP, false),
(27, 9, 20, 'Enquanto eu estava falando e orando, confessando o meu pecado e o pecado de Israel, meu povo, e fazendo o meu pedido ao Senhor, ao meu Deus, em favor do seu santo monte;', 3, CURRENT_TIMESTAMP, false),
(27, 9, 21, 'enquanto eu ainda estava em oração, Gabriel, o homem que eu tinha visto na visão anterior, veio a mim, voando rapidamente para onde eu estava, à hora do sacrifício da tarde.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 22, 'Ele me instruiu e me disse: "Daniel, agora vim para dar-lhe percepção e entendimento.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 23, 'Assim que você começou a orar, houve uma resposta, que eu lhe trouxe porque você é muito amado. Por isso, preste atenção à mensagem para entender a visão:', 3, CURRENT_TIMESTAMP, false),
(27, 9, 24, '"Setenta semanas estão decretadas para o seu povo e sua santa cidade para acabar com a transgressão, para dar fim ao pecado, para expiar as culpas, para trazer justiça eterna, para cumprir a visão e a profecia, e para ungir o santíssimo.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 25, '"Saiba e entenda que a partir da promulgação do decreto que manda restaurar e reconstruir Jerusalém até que o Ungido, o líder, venha, haverá sete semanas, e sessenta e duas semanas. Ela será reconstruída com ruas e muros, mas em tempos difíceis.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 26, 'Depois das sessenta e duas semanas, o Ungido será morto, e já não haverá lugar para ele. A cidade e o lugar santo serão destruídos pelo povo do governante que virá. O fim virá como uma inundação: Guerras continuarão até o fim, e desolações foram decretadas.', 3, CURRENT_TIMESTAMP, false),
(27, 9, 27, 'Com muitos ele fará uma aliança que durará uma semana. No meio da semana ele dará fim ao sacrifício e à oferta. E numa ala do templo será colocado o sacrilégio terrível, até que chegue sobre ele o fim que lhe está decretado".', 3, CURRENT_TIMESTAMP, false),
(27, 10, 1, 'No terceiro ano de Ciro, rei da Pérsia, Daniel, chamado Beltessazar, recebeu uma revelação. A mensagem era verdadeira e falava de uma grande guerra. E numa visão veio-lhe o entendimento da mensagem.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 2, 'Naquela ocasião eu, Daniel, passei três semanas chorando.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 3, 'Não comi nada saboroso; carne e vinho nem provei; e não usei nenhuma fragrância perfumada, até se passarem as três semanas.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 4, 'No vigésimo quarto dia do primeiro mês, estava eu de pé junto à margem do grande rio, o Tigre.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 5, 'Olhei para cima, e diante de mim estava um homem vestido de linho, com um cinto de ouro puríssimo na cintura.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 6, 'Seu corpo era como o berilo, o rosto como o relâmpago, os olhos como tochas acesas, os braços e pernas como o reflexo do bronze polido, e a sua voz era como o som de uma multidão.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 7, 'Somente eu, Daniel, vi a visão; os que me acompanhavam nada viram, mas apoderou-se deles tanto pavor que eles fugiram e se esconderam.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 8, 'Assim fiquei sozinho, olhando para aquela grande visão; fiquei sem forças, muito pálido, e quase desfaleci.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 9, 'Então eu o ouvi falando, e, ao ouvi-lo, caí prostrado, rosto em terra, e perdi os sentidos.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 10, 'Em seguida, a mão de alguém tocou em mim e me pôs sobre as minhas mãos e os meus joelhos vacilantes.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 11, 'E ele disse: "Daniel, você é muito amado. Preste bem atenção ao que vou lhe falar; levante-se, pois eu fui enviado a você". Quando ele me disse isso, pus-me de pé, tremendo.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 12, 'E ele prosseguiu: "Não tenha medo, Daniel. Desde o primeiro dia em que você decidiu buscar entendimento e humilhar-se diante do seu Deus, suas palavras foram ouvidas, e eu vim em resposta a elas.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 13, 'Mas o príncipe do reino da Pérsia me resistiu vinte e um dias. Então Miguel, um dos príncipes supremos, veio em minha ajuda, pois eu fui impedido de prosseguir ali com os reis da Pérsia.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 14, 'Agora vim explicar-lhe o que acontecerá ao seu povo no futuro, pois a visão se refere a uma época futura".', 3, CURRENT_TIMESTAMP, false),
(27, 10, 15, 'Enquanto ele me dizia isso, prostrei-me, rosto em terra, sem conseguir falar.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 16, 'Então um ser que parecia homem tocou nos meus lábios, e eu abri a minha boca e comecei a falar. Eu disse àquele que estava de pé diante de mim: Estou angustiado por causa da visão, meu senhor, e quase desfaleço.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 17, 'Como posso eu, teu servo, conversar contigo, meu senhor? Minhas forças se foram, e mal posso respirar.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 18, 'O ser que parecia homem tocou em mim outra vez e me deu forças.', 3, CURRENT_TIMESTAMP, false),
(27, 10, 19, 'Ele disse: "Não tenha medo, você, que é muito amado. Que a paz seja com você! Seja forte! Seja forte! " Ditas essas palavras, senti-me fortalecido e disse: "Fala, meu senhor, visto que me deste forças".', 3, CURRENT_TIMESTAMP, false),
(27, 10, 20, 'Então ele me disse: "Você sabe por que vim? Vou ter que voltar para lutar contra o príncipe da Pérsia, e, logo que eu for, chegará o príncipe da Grécia;', 3, CURRENT_TIMESTAMP, false),
(27, 10, 21, 'mas antes lhe revelarei o que está escrito no Livro da Verdade. E nessa luta ninguém me ajuda contra eles, senão Miguel, o príncipe de vocês,', 3, CURRENT_TIMESTAMP, false),
(27, 11, 1, 'sendo que, no primeiro ano de Dario, rei dos medos, ajudei-o e dei-lhe apoio.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 2, '"Agora, pois, vou dar-lhe a conhecer a verdade: Outros três reis aparecerão na Pérsia, e depois virá um quarto rei, que será bem mais rico do que todos os outros. Quando ele tiver conquistado o poder com sua riqueza, instigará todos contra o reino da Grécia.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 3, 'Então surgirá um rei guerreiro, que governará com grande poder e fará o que quiser.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 4, 'Depois que ele surgir, o seu império se desfará e será repartido para os quatro ventos do céu. Não passará para os seus descendentes, e o império não será poderoso como antes, pois será desarraigado e dado a outros.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 5, '"O rei do sul se tornará forte, mas um dos seus príncipes se tornará ainda mais forte que ele e governará o seu próprio reino com grande poder.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 6, 'Depois de alguns anos, eles se tornarão aliados. A filha do rei do sul fará um tratado com o rei do norte, mas ela não manterá o seu poder, nem ele conservará o dele. Naqueles dias ela será entregue à morte, junto com sua escolta real e com seu pai e com aquele que a apoiou.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 7, '"Alguém da linhagem dela se levantará para tomar-lhe o lugar. Ele atacará as forças do rei do norte e invadirá a sua fortaleza; lutará contra eles e será vitorioso.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 8, 'Também se apoderará dos deuses deles, das suas imagens de metal e dos seus utensílios valiosos de prata e de ouro, e os levará para o Egito. E por alguns anos ele deixará o rei do norte em paz.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 9, 'Então o rei do norte invadirá as terras do rei do sul, mas terá que se retirar para a sua própria terra.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 10, 'Seus filhos se prepararão para a guerra e reunirão um grande exército, que avançará como uma inundação irresistível e levará os combates até a fortaleza do rei do sul.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 11, '"Em face disso, o rei do sul marchará furioso para combater o rei do norte, que o enfrentará com um enorme exército, mas mesmo assim será derrotado.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 12, 'Quando o exército for vencido, o rei do sul se encherá de orgulho e matará milhares, mas o seu triunfo será breve.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 13, 'Pois o rei do norte reunirá um outro exército, maior do que o primeiro; e depois de alguns anos voltará a atacá-lo com um exército enorme e bem equipado.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 14, '"Naquela época muitos se rebelarão contra o rei do sul. E os homens violentos do povo a que você pertence se revoltarão para cumprirem esta visão, mas não terão sucesso.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 15, 'Então o rei do norte virá e construirá rampas de cerco e conquistará uma cidade fortificada. As forças do sul serão incapazes de resistir; mesmo as suas melhores tropas não terão forças para resistir.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 16, 'O invasor fará o que bem entender; ninguém conseguirá resistir-lhe. Ele se instalará na Terra Magnífica e terá poder para destruí-la.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 17, 'Virá com o poder de todo o seu reino e fará uma aliança com o rei do sul. Ele lhe dará uma filha em casamento a fim de derrubar o reino, mas o seu plano não terá sucesso nem o ajudará.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 18, 'Então ele voltará a atenção para as regiões costeiras e tomará muitas delas, mas um comandante dará fim à arrogância dele e lhe devolverá a sua arrogância.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 19, 'Depois disso ele se dirigirá para as fortalezas de sua própria terra, mas tropeçará e cairá, para nunca mais aparecer.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 20, '"Seu sucessor enviará um cobrador de impostos para manter o esplendor real. Contudo, em poucos anos ele será destruído, ainda que não com ira nem em combate.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 21, '"Ele será sucedido por um ser desprezível, a quem não tinha sido dada a honra da realeza. Este invadirá o reino quando o povo do reino sentir-se seguro, e ele se apoderará dele mediante intrigas.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 22, 'Então um exército avassalador será arrasado diante dele; tanto o exército como um príncipe da aliança serão destruídos.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 23, 'Depois de um acordo feito com ele, agirá traiçoeiramente, e com apenas uns poucos chegará ao poder.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 24, 'Quando as províncias mais ricas se sentirem seguras, ele as invadirá e realizará o que nem seus pais nem seus antepassados conseguiram. Distribuirá despojos, saques e riquezas entre seus seguidores. Ele tramará a tomada de fortalezas, mas só por algum tempo.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 25, '"Com um grande exército juntará suas forças e sua coragem contra o rei do sul. O rei do sul guerreará com um exército grande e poderoso, mas não conseguirá resistir por causa dos golpes tramados contra ele.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 26, 'Mesmo os que estiverem sendo alimentados pelo rei tentarão destruí-lo; seu exército será arrasado, e muitos cairão em combate.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 27, 'Os dois reis, com seus corações inclinados para o mal, sentarão à mesma mesa e mentirão um para o outro, mas sem resultado, pois o fim só virá no tempo determinado.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 28, 'O rei do norte voltará para a sua terra com grande riqueza, mas o seu coração estará voltado contra a santa aliança. Ele empreenderá ação contra ela e então voltará para a sua terra.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 29, '"No tempo determinado ele invadirá de novo o sul, mas dessa vez o resultado será diferente do anterior.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 30, 'Navios das regiões da costa ocidental se oporão a ele, e ele perderá o ânimo. Então se voltará e despejará sua fúria contra a santa aliança. Ele retornará e será bondoso com aqueles que abandonarem a santa aliança.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 31, '"Suas forças armadas se levantarão para profanar a fortaleza e o templo, acabarão com o sacrifício diário e colocarão o sacrilégio terrível.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 32, 'Com lisonjas corromperá aqueles que tiverem violado a aliança, mas o povo que conhece o seu Deus resistirá com firmeza.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 33, '"Aqueles que são sábios instruirão a muitos, mas por certo período cairão pela espada e serão queimados, capturados e saqueados.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 34, 'Quando caírem, receberão uma pequena ajuda, e muitos que não são sinceros se juntarão a eles.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 35, 'Alguns dos sábios tropeçarão para que sejam refinados, purificados e alvejados até a época do fim, pois isso só virá no tempo determinado.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 36, '"O rei fará o que bem entender. Ele se exaltará e se engrandecerá acima de todos os deuses e dirá coisas jamais ouvidas contra o Deus dos deuses. Ele terá sucesso até que o tempo da ira se complete, pois o que foi decidido irá acontecer.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 37, 'Ele não terá consideração pelos deuses dos seus antepassados nem pelo deus preferido das mulheres, nem por deus algum, mas se exaltará acima deles todos.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 38, 'Em seu lugar adorará um deus das fortalezas; um deus desconhecido de seus antepassados ele honrará com ouro e prata, com pedras preciosas e presentes caros.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 39, 'Atacará as fortalezas mais poderosas com a ajuda de um deus estrangeiro e dará grande honra àqueles que o reconhecerem. Ele os fará governantes sobre muitos e distribuirá a terra, mas a um preço elevado.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 40, '"No tempo do fim o rei do sul se envolverá em combate, e o rei do norte o atacará com carros e cavaleiros e uma grande frota de navios. Ele invadirá muitos países e avançará por eles como uma inundação.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 41, 'Também invadirá a Terra Magnífica. Muitos países cairão, mas Edom, Moabe e os líderes de Amom ficarão livres da sua mão.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 42, 'Ele estenderá o seu poder sobre muitos países; o Egito não escapará,', 3, CURRENT_TIMESTAMP, false),
(27, 11, 43, 'pois ele terá o controle dos tesouros de ouro e de prata e de todas as riquezas do Egito; os líbios e os núbios a ele se submeterão.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 44, 'Mas, informações provenientes do leste e do norte o deixarão alarmado, e irado partirá para destruir e aniquilar a muitos.', 3, CURRENT_TIMESTAMP, false),
(27, 11, 45, 'Armará suas tendas reais entre os mares, no belo monte santo. No entanto, ele chegará ao seu fim, e ninguém o socorrerá.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 1, '"Naquela ocasião Miguel, o grande príncipe que protege o seu povo, se levantará. Haverá um tempo de angústia tal como nunca houve desde o início das nações e até então. Mas naquela ocasião o seu povo, todo aquele cujo nome está escrito no livro, será liberto.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 2, 'Multidões que dormem no pó da terra acordarão: uns para a vida eterna, outros para a vergonha, para o desprezo eterno.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 3, 'Aqueles que são sábios reluzirão como o brilho do céu, e aqueles que conduzem muitos à justiça serão como as estrelas, para todo o sempre.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 4, 'Mas você, Daniel, feche com um selo as palavras do livro até o tempo do fim. Muitos irão ali e acolá para aumentarem o conhecimento".', 3, CURRENT_TIMESTAMP, false),
(27, 12, 5, 'Então eu, Daniel, olhei, e diante de mim estavam dois outros, um na margem de cá do rio e outro na margem de lá.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 6, 'Um deles disse ao homem vestido de linho, que estava acima das águas do rio: "Quanto tempo decorrerá antes de se cumprirem essas coisas estupendas? "', 3, CURRENT_TIMESTAMP, false),
(27, 12, 7, 'O homem vestido de linho, que estava acima das águas do rio, ergueu para o céu a mão direita e a mão esquerda, e eu o ouvi jurar por aquele que vive para sempre, dizendo: "Haverá um tempo, tempos e meio tempo. Quando o poder do povo santo for finalmente quebrado, todas essas coisas se cumprirão".', 3, CURRENT_TIMESTAMP, false),
(27, 12, 8, 'Eu ouvi, mas não compreendi. Por isso perguntei: "Meu senhor, qual será o resultado disso tudo? "', 3, CURRENT_TIMESTAMP, false),
(27, 12, 9, 'Ele respondeu: "Siga o seu caminho, Daniel, pois as palavras estão seladas e lacradas até o tempo do fim.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 10, 'Muitos serão purificados, alvejados e refinados, mas os ímpios continuarão ímpios. Nenhum dos ímpios levará isto em consideração, mas os sábios sim.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 11, '"A partir do momento em que for abolido o sacrifício diário e for colocado o sacrilégio terrível, haverá mil e duzentos e noventa dias.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 12, 'Feliz aquele que esperar e alcançar o fim dos mil trezentos e trinta e cinco dias.', 3, CURRENT_TIMESTAMP, false),
(27, 12, 13, '"Quanto a você, siga o seu caminho até o fim. Você descansará, e então, no final dos dias, você se levantará para receber a herança que lhe cabe".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 1, 'Estas são as palavras ditas por Moisés a todo o Israel no deserto, a leste do Jordão, na Arabá, defronte de Sufe, entre Parã e Tofel, Labã, Hazerote e Di-Zaabe.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 2, 'Em onze dias se vai de Horebe a Cades-Barnéia pelo caminho dos montes de Seir.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 3, 'No quadragésimo ano, no primeiro dia do décimo primeiro mês, Moisés proclamou aos israelitas todas as ordens do Senhor acerca deles.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 4, 'Isso foi depois que ele derrotou Seom, rei dos amorreus, que habitava em Hesbom, e em Edrei derrotou Ogue, rei de Basã, que habitava em Asterote.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 5, 'A leste do Jordão, na terra de Moabe, Moisés tomou sobre si a responsabilidade de expor esta lei:', 3, CURRENT_TIMESTAMP, false),
(5, 1, 6, 'O Senhor, o nosso Deus, disse-nos em Horebe: "Vocês já ficaram bastante tempo nesta montanha.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 7, 'Levantem acampamento e avancem para a serra dos amorreus; vão a todos os povos vizinhos na Arabá, nas montanhas, na Sefelá, no Neguebe e ao longo do litoral, à terra dos cananeus e ao Líbano, até o grande rio, o Eufrates.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 8, '"Ponho esta terra diante de vocês. Entrem e tomem posse da terra que o Senhor prometeu sob juramento dar aos seus antepassados, Abraão, Isaque e Jacó, e aos seus descendentes".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 9, 'Naquela ocasião eu lhes disse: "Não posso levá-los sozinho.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 10, 'O Senhor, o seu Deus, os fez multiplicar de tal modo que hoje vocês são tão numerosos quanto as estrelas do céu.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 11, 'Que o Senhor, o Deus dos seus antepassados, os multiplique mil vezes mais e os abençoe, conforme lhes prometeu!', 3, CURRENT_TIMESTAMP, false),
(5, 1, 12, 'Mas como poderei levar sozinho os seus problemas, as suas cargas e as suas disputas?', 3, CURRENT_TIMESTAMP, false),
(5, 1, 13, 'Escolham homens sábios, criteriosos e experientes de cada uma de suas tribos, e eu os colocarei como chefes de vocês".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 14, 'Vocês me disseram que essa era uma boa proposta.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 15, 'Então convoquei os chefes das tribos, homens sábios e experientes, e os designei como chefes de mil, de cem, de cinqüenta e de dez, além de oficiais para cada tribo.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 16, 'Naquela ocasião ordenei aos juízes de vocês: "Atendam as questões de seus irmãos e julguem com justiça, não só as questões entre os seus compatriotas como também entre um israelita e um estrangeiro.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 17, 'Não sejam parciais no julgamento! Atendam tanto o pequeno como o grande. Não se deixem intimidar por ninguém, pois o veredicto pertence a Deus. Tragam-me os casos mais difíceis e eu os ouvirei.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 18, 'Naquela ocasião eu lhes ordenei tudo o que deveriam fazer".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 19, 'Depois, conforme o Senhor, o nosso Deus, nos tinha ordenado, partimos de Horebe e fomos para a serra dos amorreus, passando por todo aquele imenso e terrível deserto que vocês viram, e assim chegamos a Cades-Barnéia.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 20, 'Então eu lhes disse: "Vocês chegaram à serra dos amorreus, a qual o Senhor, o nosso Deus, nos dá.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 21, 'Vejam, o Senhor, o seu Deus, põe diante de vocês esta terra. Entrem na terra e tomem posse dela, conforme o Senhor, o Deus dos seus antepassados, lhes disse. Não tenham medo nem se desanimem".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 22, 'Vocês todos vieram dizer-me: "Mandemos alguns homens à nossa frente em missão de reconhecimento da região, para que nos indiquem por qual caminho subiremos e a quais cidades iremos".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 23, 'A sugestão pareceu-me boa; por isso escolhi doze de vocês, um homem de cada tribo.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 24, 'Eles subiram a região montanhosa, chegaram ao vale de Escol e o exploraram.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 25, 'Trouxeram alguns frutos da região, com o seguinte relato: "Essa terra que o Senhor, o nosso Deus, nos dá é boa".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 26, 'Vocês, contudo, não quiseram ir, e se rebelaram contra a ordem do Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 27, 'Queixaram-se em suas tendas, dizendo: "O Senhor nos odeia; por isso nos trouxe do Egito para nos entregar nas mãos dos amorreus e destruir-nos.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 28, 'Para onde iremos? Nossos compatriotas nos desanimaram quando disseram: O povo é mais forte e mais alto do que nós; as cidades são grandes, com muros que vão até o céu. Vimos ali os enaquins".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 29, 'Então eu lhes disse: Não fiquem apavorados; não tenham medo deles.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 30, 'O Senhor, o seu Deus, que está indo à frente de vocês, lutará por vocês, como fez no Egito, diante de seus próprios olhos.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 31, 'Também no deserto vocês viram como o Senhor, o seu Deus, os carregou, como um pai carrega seu filho, por todo o caminho que percorreram até chegarem a este lugar.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 32, 'Apesar disso, vocês não confiaram no Senhor, o seu Deus,', 3, CURRENT_TIMESTAMP, false),
(5, 1, 33, 'que foi à frente de vocês, numa coluna de fogo de noite e numa nuvem de dia, para procurar lugares para vocês acamparem e para mostrar-lhes o caminho que vocês deviam seguir.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 34, 'Quando o Senhor ouviu o que vocês diziam, irou-se e jurou:', 3, CURRENT_TIMESTAMP, false),
(5, 1, 35, '"Ninguém desta geração má verá a boa terra que jurei dar aos seus antepassados,', 3, CURRENT_TIMESTAMP, false),
(5, 1, 36, 'exceto Calebe, filho de Jefoné. Ele a verá, e eu darei a ele e a seus descendentes a terra em que pisou, pois seguiu o Senhor de todo o coração".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 37, 'Por causa de vocês o Senhor irou-se contra mim e me disse: "Você também não entrará na terra.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 38, 'Mas o seu auxiliar, Josué, filho de Num, entrará. Encoraje-o, pois ele fará com que Israel tome posse dela.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 39, 'Mas as crianças que vocês disseram que seriam levadas como despojo, os seus filhos que ainda não distinguem entre o bem e o mal, eles entrarão na terra. Eu a darei a eles, e eles tomarão posse dela.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 40, 'Mas quanto a vocês, dêem meia-volta e partam para o deserto pelo caminho do mar Vermelho".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 41, 'Então vocês responderam: "Pecamos contra o Senhor. Nós subiremos e lutaremos, conforme tudo o que o Senhor, o nosso Deus, nos ordenou". Cada um de vocês preparou-se com as suas armas de guerra, achando que seria fácil subir a região montanhosa.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 42, 'Mas o Senhor me disse: "Diga-lhes que não subam nem lutem, porque não estarei com vocês. Vocês serão derrotados pelos seus inimigos".', 3, CURRENT_TIMESTAMP, false),
(5, 1, 43, 'Eu lhes disse isso, mas vocês não me deram ouvidos, rebelaram-se contra o Senhor e, com presunção, subiram a região montanhosa.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 44, 'Os amorreus que lá viviam os atacaram, os perseguiram como um enxame de abelhas e os arrasaram desde Seir até Hormá.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 45, 'Vocês voltaram e choraram perante o Senhor, mas ele não ouviu o seu clamor nem lhes deu atenção.', 3, CURRENT_TIMESTAMP, false),
(5, 1, 46, 'Então vocês ficaram em Cades, onde permaneceram muito tempo.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 1, 'Então demos meia-volta e partimos para o deserto pelo caminho do mar Vermelho, como o Senhor me havia ordenado. E por muitos anos caminhamos em redor dos montes de Seir.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 2, 'Então o Senhor me disse:', 3, CURRENT_TIMESTAMP, false),
(5, 2, 3, '"Vocês já caminharam bastante tempo ao redor destas montanhas; agora andem para o norte.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 4, 'E diga ao povo: Vocês estão passando pelo território de seus irmãos, os descendentes de Esaú, que vivem em Seir. Eles terão medo de vocês, mas tenham muito cuidado.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 5, 'Não os provoquem, pois não darei a vocês parte alguma da terra deles, nem mesmo o espaço de um pé. Já dei a Esaú a posse dos montes de Seir.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 6, 'Vocês lhes pagarão com prata a comida que comerem e a água que beberem".', 3, CURRENT_TIMESTAMP, false),
(5, 2, 7, 'Pois o Senhor, o seu Deus, os tem abençoado em tudo o que vocês têm feito. Ele cuidou de vocês em sua jornada por este grande deserto. Nestes quarenta anos o Senhor, o seu Deus, tem estado com vocês, e não lhes tem faltado coisa alguma.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 8, 'Assim, passamos ao largo de nossos irmãos, os descendentes de Esaú, que habitam em Seir. Saímos da rota da Arabá, de Elate e de Eziom-Geber. Voltamos e fomos pela rota do deserto de Moabe.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 9, 'Então o Senhor me disse: "Não perturbem os moabitas nem os provoquem à guerra, pois não darei a vocês parte alguma da terra deles, pois já entreguei a região de Ar aos descendentes de Ló".', 3, CURRENT_TIMESTAMP, false),
(5, 2, 10, '( Antigamente os emins habitavam nessa terra; era um povo forte e numeroso, alto como os enaquins.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 11, 'Como os enaquins, eles também eram considerados refains, mas os moabitas os chamavam emins.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 12, 'Também em Seir antigamente habitavam os horeus. Mas os descendentes de Esaú os expulsaram e os exterminaram e se estabeleceram no seu lugar, tal como Israel fez com a terra que o Senhor lhe deu. )', 3, CURRENT_TIMESTAMP, false),
(5, 2, 13, '"Agora levantem-se! Atravessem o vale de Zerede". Assim atravessamos o vale.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 14, 'Passaram-se trinta e oito anos entre a época em que partimos de Cades-Barnéia, até quando atravessamos o vale de Zerede, até que pereceu do acampamento toda aquela geração de homens de guerra, conforme o Senhor lhes havia jurado.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 15, 'A mão do Senhor caiu sobre eles e por fim os eliminou completamente do acampamento.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 16, 'Depois que todos os guerreiros do povo tinham morrido,', 3, CURRENT_TIMESTAMP, false),
(5, 2, 17, 'o Senhor me disse:', 3, CURRENT_TIMESTAMP, false),
(5, 2, 18, '"Vocês estão prestes a passar pelo território de Moabe, pela região de Ar,', 3, CURRENT_TIMESTAMP, false),
(5, 2, 19, 'e vão chegar perto da fronteira dos amonitas. Não sejam hostis a eles, pois não darei a vocês parte alguma da terra dos amonitas, pois eu a entreguei aos descendentes de Ló".', 3, CURRENT_TIMESTAMP, false),
(5, 2, 20, '( Essa região também era considerada terra dos refains, que ali habitaram no passado. Os amonitas os chamavam zanzumins.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 21, 'Eram fortes, numerosos e altos como os enaquins. O Senhor os exterminou, e os amonitas os expulsaram e se estabeleceram em seu lugar.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 22, 'O Senhor fez o mesmo com os descendentes de Esaú que vivem em Seir, quando exterminou os horeus diante deles. Os descendentes de Esaú os expulsaram e se estabeleceram em seu lugar até hoje.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 23, 'Foi o que também aconteceu aos aveus, que viviam em povoados próximos de Gaza; os caftoritas, vindos de Caftor, os destruíram e se estabeleceram em seu lugar. )', 3, CURRENT_TIMESTAMP, false),
(5, 2, 24, '"Vão agora e atravessem o ribeiro do Arnom. Vejam que eu entreguei em suas mãos Seom o amorreu, rei de Hesbom, e a terra dele. Comecem a ocupação, entrem em guerra contra ele.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 25, 'Hoje mesmo começarei a infundir pavor e medo de vocês em todos os povos debaixo do céu. Quando ouvirem da fama de vocês, tremerão e ficarão angustiados".', 3, CURRENT_TIMESTAMP, false),
(5, 2, 26, 'Do deserto de Quedemote enviei mensageiros a Seom, rei de Hesbom, oferecendo paz e dizendo:', 3, CURRENT_TIMESTAMP, false),
(5, 2, 27, 'Deixa-nos passar pela tua terra. Iremos somente pela estrada; não nos desviaremos nem para a direita nem para a esquerda.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 28, 'Por prata nos venderás tanto a comida que comermos como a água que bebermos. Apenas deixe-nos passar a pé,', 3, CURRENT_TIMESTAMP, false),
(5, 2, 29, 'como fizeram os descendentes de Esaú, que habitam em Seir, e os moabitas, que habitam em Ar. Assim chegarei ao Jordão, e, através dele, à terra que o Senhor, o nosso Deus, nos dá.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 30, 'Mas Seom, rei de Hesbom, não quis deixar-nos passar; pois o Senhor, o Deus de vocês, tornou-lhe obstinado o espírito e endureceu-lhe o coração, para entregá-lo nas mãos de vocês, como hoje se vê.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 31, 'O Senhor me disse: "Estou entregando a você Seom e sua terra. Comece a ocupação, tome posse da terra dele! "', 3, CURRENT_TIMESTAMP, false),
(5, 2, 32, 'Então Seom saiu à batalha contra nós em Jaza, com todo o seu exército.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 33, 'Mas o Senhor, o nosso Deus, entregou-o a nós, e o derrotamos, a ele, aos seus filhos e a todo o seu exército.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 34, 'Naquela ocasião conquistamos todas as suas cidades e as destruímos totalmente, matando homens, mulheres e crianças, sem deixar nenhum sobrevivente.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 35, 'Tomamos como presa somente os animais e o despojo das cidades que conquistamos.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 36, 'Desde Aroer, junto ao ribeiro do Arnom, e a cidade que fica no mesmo vale, até Gileade, não houve cidade de muros altos demais para nós. O Senhor, o nosso Deus, entregou-nos tudo.', 3, CURRENT_TIMESTAMP, false),
(5, 2, 37, 'Somente da terra dos amonitas vocês não se aproximaram, ou seja, toda a extensão do vale do Rio Jaboque, e as cidades da região montanhosa, conforme o Senhor, o nosso Deus, tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 1, 'Depois, voltamos e subimos rumo a Basã. Ogue, rei de Basã, atacou-nos com todo o seu exército, em Edrei.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 2, 'O Senhor me disse: "Não tenha medo dele, pois eu o entreguei em suas mãos, com todo o seu exército, e dei-lhe também a terra dele. Você fará com ele como fez com Seom, rei dos amorreus, que habitava em Hesbom".', 3, CURRENT_TIMESTAMP, false),
(5, 3, 3, 'Então o Senhor, o nosso Deus, também nos entregou em nossas mãos Ogue, rei de Basã, e todo o seu exército. Nós os derrotamos, sem deixar nenhum sobrevivente.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 4, 'Naquela ocasião conquistamos todas as suas cidades. Não houve cidades que não tomássemos. Foram sessenta cidades, em toda a região de Argobe, o reino de Ogue, em Basã.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 5, 'Todas essas cidades eram fortificadas com muros altos e com portas e trancas. Além delas havia muitas cidades sem muros.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 6, 'Nós as destruímos completamente, tal como havíamos feito com Seom, rei de Hesbom, destruindo todas as cidades, matando também os homens, as mulheres e as crianças.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 7, 'Mas os animais todos e o despojo das cidades tomamos como espólio de guerra.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 8, 'Foi assim que, naquela ocasião, tomamos desses dois reis amorreus o território a leste do Jordão, que vai desde o ribeiro do Arnom até o monte Hermom.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 9, '( Os sidônios chamam o Hermom de Siriom; e os amorreus o chamam Senir. )', 3, CURRENT_TIMESTAMP, false),
(5, 3, 10, 'Conquistamos todas as cidades do planalto, e toda a Gileade, e também toda a Basã, até Salcá e Edrei, cidades do reino de Ogue, em Basã.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 11, 'Ogue, rei de Basã, era o único sobrevivente dos refains. Sua cama era de ferro e tinha, pela medida comum, quatro metros de comprimento e um metro e oitenta centímetros de largura. Ela ainda está em Rabá dos amonitas.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 12, 'Da terra da qual tomamos posse naquela época, o território que vai de Aroer, junto ao ribeiro do Arnom, até mais da metade dos montes de Gileade com as suas cidades, dei-o às tribos de Rúben e de Gade.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 13, 'O restante de Gileade e também toda a Basã, o reino de Ogue, dei-o à metade da tribo de Manassés. ( Toda a região de Argobe em Basã era conhecida no passado como a terra dos refains.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 14, 'Jair, um descendente de Manassés, conquistou toda a região de Argobe até à fronteira dos gesuritas e dos maacatitas; essa região recebeu o seu nome, de modo que até hoje Basã é chamada Povoados de Jair. )', 3, CURRENT_TIMESTAMP, false),
(5, 3, 15, 'E dei Gileade a Maquir.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 16, 'Às tribos de Rúben e de Gade dei a região que vai de Gileade, até o ribeiro do Arnom ( a fronteira passava bem no meio do vale ) e até o vale do Jaboque, na fronteira dos amonitas.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 17, 'Dei-lhe também a Arabá, tendo como fronteira ocidental o Jordão, desde Quinerete até o mar da Arabá, que é o mar Salgado, abaixo das encostas do Pisga.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 18, 'Naquela ocasião eu lhes ordenei o seguinte: O Senhor, o Deus de vocês, deu-lhes esta terra para que dela tomem posse. Todos os guerreiros devem marchar à frente dos seus irmãos israelitas, armados para a guerra!', 3, CURRENT_TIMESTAMP, false),
(5, 3, 19, 'Deixem nas cidades que lhes dei as mulheres, as crianças e os grandes rebanhos, que eu sei que vocês possuem,', 3, CURRENT_TIMESTAMP, false),
(5, 3, 20, 'até que o Senhor conceda descanso aos seus outros irmãos israelitas como deu a vocês, e tomem eles posse da terra que o Senhor, o Deus de vocês, está dando a eles, do outro lado do Jordão. Depois vocês poderão retornar, cada um à propriedade que lhes dei.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 21, 'Naquela ocasião também ordenei a Josué: "Você viu com os seus próprios olhos tudo o que o Senhor, o Deus de vocês, fez com estes dois reis. Assim o Senhor fará com todos os reinos pelos quais vocês terão que passar.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 22, 'Não tenham medo deles. O Senhor, o Deus de vocês, é quem lutará por vocês".', 3, CURRENT_TIMESTAMP, false),
(5, 3, 23, 'Naquela ocasião implorei ao Senhor:', 3, CURRENT_TIMESTAMP, false),
(5, 3, 24, '"Ó Soberano Senhor, tu começaste a mostrar a teu servo a tua grandeza e a tua mão poderosa! Que Deus existe no céu ou na terra que possa realizar as tuas obras e os teus feitos poderosos?', 3, CURRENT_TIMESTAMP, false),
(5, 3, 25, 'Deixa-me atravessar, eu te suplico, e ver a boa terra do outro lado do Jordão, a bela região montanhosa e o Líbano! "', 3, CURRENT_TIMESTAMP, false),
(5, 3, 26, 'Todavia, por causa de vocês, o Senhor irou-se contra mim e não quis me atender. "Basta", ele disse. "Não me fale mais sobre isso.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 27, 'Suba ao ponto mais alto do Pisga e olhe para o Oeste, para o Norte, para o Sul, e para o Leste. Veja a terra com os seus próprios olhos, pois você não atravessará o Jordão.', 3, CURRENT_TIMESTAMP, false),
(5, 3, 28, 'Portanto, dê ordens a Josué, fortaleça-o e encoraje-o; porque será ele que atravessará à frente deste povo, e lhes repartirá por herança a terra que você apenas verá".', 3, CURRENT_TIMESTAMP, false),
(5, 3, 29, 'Então ficamos acampados no vale, diante de Bete-Peor.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 1, 'E agora, ó Israel, ouça os decretos e as leis que lhes estou ensinando a cumprir, para que vivam e tomem posse da terra, que o Senhor, o Deus dos seus antepassados, dá a vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 2, 'Nada acrescentem às palavras que eu lhes ordeno e delas nada retirem, mas obedeçam aos mandamentos do Senhor, o Deus de vocês, que eu lhes ordeno.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 3, 'Vocês viram com os próprios olhos o que o Senhor fez em Baal-Peor. O Senhor, o seu Deus, destruiu do meio de vocês todos os que seguiram a Baal-Peor,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 4, 'mas vocês, que permaneceram fiéis ao Senhor, o Deus de vocês, estão hoje todos vivos.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 5, 'Eu lhes ensinei decretos e leis, como me ordenou o Senhor, o meu Deus, para que sejam cumpridos na terra na qual vocês estão entrando para dela tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 6, 'Vocês devem obedecer-lhes e cumpri-los, pois assim os outros povos verão a sabedoria e o discernimento de vocês. Quando eles ouvirem todos estes decretos dirão: "De fato esta grande nação é um povo sábio e inteligente".', 3, CURRENT_TIMESTAMP, false),
(5, 4, 7, 'Pois, que grande nação tem um Deus tão próximo como o Senhor, o nosso Deus, sempre que o invocamos?', 3, CURRENT_TIMESTAMP, false),
(5, 4, 8, 'Ou, que grande nação tem decretos e preceitos tão justos como esta lei que estou apresentando a vocês hoje?', 3, CURRENT_TIMESTAMP, false),
(5, 4, 9, 'Apenas cuidado! Muito cuidado, para que vocês nunca se esqueçam das coisas que os seus olhos viram; conservem-nas na memória por toda a sua vida. Contem-nas a seus filhos e a seus netos.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 10, 'Houve um dia em que vocês estiveram diante do Senhor, o seu Deus, em Horebe, quando o Senhor me disse: "Reúna o povo diante de mim para ouvir as minhas palavras, a fim de que aprendam a me temer enquanto viverem sobre a terra, e as ensinem a seus filhos".', 3, CURRENT_TIMESTAMP, false),
(5, 4, 11, 'Vocês se aproximaram e ficaram ao pé do monte. O monte ardia em chamas que subiam até o céu, e estava envolvido por uma nuvem escura e densa.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 12, 'Então o Senhor falou a vocês do meio do fogo. Vocês ouviram as palavras, mas não viram forma alguma; apenas se ouvia a voz.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 13, 'Ele lhes anunciou a sua aliança, os Dez Mandamentos. E escreveu-os sobre duas tábuas de pedra e ordenou que os cumprissem.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 14, 'Naquela ocasião, o Senhor mandou-me ensinar-lhes decretos e leis para que vocês os cumprissem na terra da qual vão tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 15, 'No dia em que o Senhor lhes falou do meio do fogo em Horebe, vocês não viram forma alguma. Portanto, tenham muito cuidado,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 16, 'para que não se corrompam e não façam para si um ídolo, uma imagem de qualquer forma semelhante a homem ou mulher,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 17, 'ou a qualquer animal da terra ou a qualquer ave que voa no céu,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 18, 'ou a qualquer criatura que se move rente ao chão ou a qualquer peixe que vive nas águas debaixo da terra.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 19, 'E para que, ao erguerem os olhos ao céu e virem o sol, a lua e as estrelas, todos os corpos celestes, vocês não se desviem e se prostrem diante deles, e prestem culto àquilo que o Senhor, o seu Deus, distribuiu a todos os povos debaixo do céu.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 20, 'A vocês, o Senhor tomou e os tirou da fornalha de fundir ferro, do Egito, para serem o povo de sua herança, como hoje se pode ver.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 21, 'O Senhor irou-se contra mim por causa de vocês e jurou que eu não atravessaria o Jordão e não entraria na boa terra que o Senhor, o seu Deus, está lhes dando por herança.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 22, 'Eu morrerei nesta terra; não atravessarei o Jordão. Mas vocês atravessarão e tomarão posse daquela boa terra.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 23, 'Tenham o cuidado de não esquecer da aliança que o Senhor, o seu Deus, fez com vocês; não façam para si ídolo algum com a forma de qualquer coisa que o Senhor, o seu Deus, proibiu.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 24, 'Pois o Senhor, o seu Deus, é Deus zeloso; é fogo consumidor.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 25, 'Quando vocês tiverem filhos e netos, e já estiverem a muito tempo na terra, e se corromperem e fizerem ídolos de qualquer tipo, fazendo o que o Senhor, o seu Deus, reprova, provocando a sua ira,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 26, 'invoco hoje o céu e a terra como testemunhas contra vocês de que vocês serão rapidamente eliminados da terra, da qual estão tomando posse ao atravessar o Jordão. Vocês não viverão muito ali; serão totalmente destruídos.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 27, 'O Senhor os espalhará entre os povos, e restarão apenas alguns de vocês entre as nações às quais o Senhor os levará.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 28, 'Lá vocês prestarão culto a deuses de madeira e de pedra, deuses feitos por mãos humanas, deuses que não podem ver, nem ouvir, nem comer, nem cheirar.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 29, 'E lá procurarão o Senhor, o seu Deus, e o acharão, se o procurarem de todo o seu coração e de toda a sua alma.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 30, 'Quando vocês estiverem sofrendo e todas essas coisas tiverem acontecido com vocês, então, em dias futuros, vocês voltarão para o Senhor, o seu Deus, e lhe obedecerão.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 31, 'Pois o Senhor, o seu Deus, é Deus misericordioso; ele não os abandonará, nem os destruirá nem se esquecerá da aliança que com juramento fez com os seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 32, 'Perguntem, agora, aos tempos antigos, antes de vocês existirem, desde o dia em que Deus criou o homem sobre a terra. Perguntem de um lado ao outro do céu: Já aconteceu algo tão grandioso ou já se ouviu algo parecido?', 3, CURRENT_TIMESTAMP, false),
(5, 4, 33, 'Que povo ouviu a voz de Deus falando do meio do fogo, como vocês ouviram, e continua vivo?', 3, CURRENT_TIMESTAMP, false),
(5, 4, 34, 'Ou que deus decidiu tirar uma nação do meio de outra para lhe pertencer, com provas, sinais, maravilhas e lutas, com mão poderosa e braço forte, e com feitos temíveis e grandiosos, conforme tudo o que o Senhor fez por vocês no Egito, como vocês viram com os seus próprios olhos?', 3, CURRENT_TIMESTAMP, false),
(5, 4, 35, 'Tudo isso foi mostrado a vocês para que soubessem que o Senhor é Deus; e que não há outro além dele.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 36, 'Do céu ele fez com que vocês ouvissem a sua voz, para discipliná-los. Na terra, mostrou-lhes o seu grande fogo, e vocês ouviram as suas palavras vindas do meio do fogo.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 37, 'E porque amou os seus antepassados e escolheu a descendência deles, ele foi em pessoa tirá-los do Egito com o seu grande poder,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 38, 'para expulsar diante de vocês nações maiores e mais fortes, a fim de fazê-los entrar e possuir como herança a terra deles, como hoje se vê.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 39, 'Reconheçam isso hoje, e ponham no coração que o Senhor é Deus em cima nos céus e embaixo na terra. Não há nenhum outro.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 40, 'Obedeçam aos seus decretos e mandamentos que hoje eu lhes ordeno, para que tudo vá bem com vocês e com seus descendentes, e para que vivam muito tempo na terra que o Senhor, o seu Deus, lhes dá para sempre.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 41, 'Então Moisés separou três cidades a leste do Jordão,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 42, 'para onde poderia fugir quem tivesse matado alguém sem intenção e sem premeditação. O perseguido poderia fugir para uma dessas cidades a fim de salvar a vida.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 43, 'As cidades eram as seguintes: Bezer, no planalto do deserto, para a tribo de Rúben; Ramote, em Gileade, para a tribo de Gade; e Golã, em Basã, para a tribo de Manassés.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 44, 'Esta é a lei que Moisés apresentou aos israelitas.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 45, 'Estes são os mandamentos, os decretos e as ordenanças que Moisés promulgou como leis para os israelitas quando saíram do Egito,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 46, 'do outro lado do Jordão, no vale fronteiro a Bete-Peor, na terra de Seom, rei dos amorreus, que habitava em Hesbom, a quem Moisés e os israelitas derrotaram quando saíram do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 47, 'Eles tomaram posse da terra dele e da terra de Ogue, rei de Basã, os dois reis amorreus que viviam a leste do Jordão.', 3, CURRENT_TIMESTAMP, false),
(5, 4, 48, 'Essa terra estendia-se desde Aroer, na margem do ribeiro do Arnom, até o monte Siom, isto é, o Hermom,', 3, CURRENT_TIMESTAMP, false),
(5, 4, 49, 'e incluía toda a região da Arabá, a leste do Jordão, até o mar da Arabá, abaixo das encostas do Pisga.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 1, 'Então Moisés convocou todo o Israel e lhe disse: Ouçam, ó Israel, os decretos e as ordenanças que hoje lhes estou anunciando. Aprendam-nos e tenham o cuidado de cumpri-los.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 2, 'O Senhor, o nosso Deus, fez conosco uma aliança em Horebe.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 3, 'Não foi com os nossos antepassados que o Senhor fez essa aliança, mas conosco, com todos nós que aqui hoje estamos vivos.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 4, 'O Senhor falou com vocês face a face do meio do fogo, no monte.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 5, 'Naquela ocasião eu fiquei entre o Senhor e vocês para declarar-lhes a palavra do Senhor, porque vocês tiveram medo do fogo e não subiram o monte. E ele disse:', 3, CURRENT_TIMESTAMP, false),
(5, 5, 6, '"Eu sou o Senhor, o teu Deus, que te tirei do Egito, da terra da escravidão.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 7, '"Não terás outros deuses além de mim.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 8, '"Não farás para ti nenhum ídolo, nenhuma imagem de qualquer coisa no céu, na terra ou nas águas debaixo da terra.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 9, 'Não te prostrarás diante deles nem lhes prestarás culto, porque eu, o Senhor, o teu Deus, sou Deus zeloso, que castigo os filhos pelo pecado de seus pais até a terceira e quarta geração daqueles que me desprezam,', 3, CURRENT_TIMESTAMP, false),
(5, 5, 10, 'mas trato com bondade até mil gerações os que me amam e guardam os meus mandamentos.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 11, '"Não tomarás em vão o nome do Senhor, o teu Deus, pois o Senhor não deixará impune quem usar o seu nome em vão.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 12, '"Guardarás o dia de sábado a fim de santificá-lo, conforme o Senhor, o teu Deus, te ordenou.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 13, 'Trabalharás seis dias e neles farás todos os teus trabalhos,', 3, CURRENT_TIMESTAMP, false),
(5, 5, 14, 'mas o sétimo dia é um sábado para o Senhor, o teu Deus. Nesse dia não farás trabalho algum, nem tu nem teu filho ou filha, nem o teu servo ou serva, nem o teu boi, teu jumento ou qualquer dos teus animais, nem o estrangeiro que estiver em tua propriedade; para que o teu servo e a tua serva descansem como tu.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 15, 'Lembra-te de que foste escravo no Egito e que o Senhor, o teu Deus, te tirou de lá com mão poderosa e com braço forte. Por isso o Senhor, o teu Deus, te ordenou que guardes o dia de sábado.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 16, '"Honra teu pai e tua mãe, como te ordenou o Senhor, o teu Deus, para que tenhas longa vida e tudo te vá bem na terra que o Senhor, o teu Deus, te dá.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 17, '"Não matarás.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 18, '"Não adulterarás.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 19, '"Não furtarás.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 20, '"Não darás falso testemunho contra o teu próximo.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 21, '"Não cobiçarás a mulher do teu próximo. Não desejarás a casa do teu próximo, nem sua propriedade; nem seu servo ou serva; nem seu boi ou jumento; nem coisa alguma que lhe pertença".', 3, CURRENT_TIMESTAMP, false),
(5, 5, 22, 'Essas foram as palavras que o Senhor falou a toda a assembléia de vocês, em alta voz, no monte, do meio do fogo, da nuvem e da densa escuridão; e nada mais acrescentou. Então as escreveu em duas tábuas de pedra e as deu a mim.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 23, 'Quando vocês ouviram a voz que vinha do meio da escuridão, estando o monte em chamas, aproximaram-se de mim todos os chefes das tribos de vocês, com as suas autoridades.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 24, 'E vocês disseram: "O Senhor, o nosso Deus, mostrou-nos sua glória e sua majestade, e nós ouvimos a sua voz vinda de dentro do fogo. Hoje vimos que Deus fala com o homem e que este ainda continua vivo!', 3, CURRENT_TIMESTAMP, false),
(5, 5, 25, 'Mas, agora, por que deveríamos morrer? Este grande fogo por certo nos consumirá. Se continuarmos a ouvir a voz do Senhor, o nosso Deus, morreremos.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 26, 'Pois, que homem mortal chegou a ouvir a voz do Deus vivo falando de dentro do fogo, como nós o ouvimos, e sobreviveu?', 3, CURRENT_TIMESTAMP, false),
(5, 5, 27, 'Aproxime-se você, Moisés, e ouça tudo o que o Senhor, o nosso Deus, disser; você nos relatará tudo o que o Senhor, o nosso Deus, lhe disser. Nós ouviremos e obedeceremos".', 3, CURRENT_TIMESTAMP, false),
(5, 5, 28, 'O Senhor ouviu quando vocês me falaram e me disse: "Ouvi o que este povo lhe disse, e eles têm razão em tudo o que disseram.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 29, 'Quem dera eles tivessem sempre no coração esta disposição para temer-me e para obedecer a todos os meus mandamentos. Assim tudo iria bem com eles e com seus descendentes para sempre! "', 3, CURRENT_TIMESTAMP, false),
(5, 5, 30, 'Vá, diga-lhes que voltem às suas tendas.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 31, 'Você ficará aqui comigo, e lhe anunciarei toda a lei, isto é, os decretos e as ordenanças que você lhes ensinará, e que eles deverão cumprir na terra que eu dou a eles como propriedade.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 32, 'Por isso, tenham o cuidado de fazer tudo como o Senhor, o seu Deus, lhes ordenou; não se desviem, nem para a direita, nem para a esquerda.', 3, CURRENT_TIMESTAMP, false),
(5, 5, 33, 'Andem sempre pelo caminho que o Senhor, o seu Deus, lhes ordenou, para que tenham vida, tudo lhes vá bem e os seus dias se prolonguem na terra da qual tomarão posse.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 1, 'Esta é a lei, isto é, os decretos e as ordenanças, que o Senhor, o seu Deus ordenou que eu lhes ensinasse, para que vocês os cumpram na terra para a qual estão indo para dela tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 2, 'Desse modo vocês, seus filhos e seus netos temerão ao Senhor, o seu Deus, e obedecerão a todos os seus decretos e mandamentos, que eu lhes ordeno, todos os dias da sua vida, para que tenham vida longa.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 3, 'Ouça e obedeça, ó Israel! Assim tudo lhe irá bem e você será muito numeroso numa terra onde manam leite e mel, como lhe prometeu o Senhor, o Deus dos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 4, 'Ouça, ó Israel: O Senhor, o nosso Deus, é o único Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 5, 'Ame o Senhor, o seu Deus, de todo o seu coração, de toda a sua alma e de todas as suas forças.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 6, 'Que todas estas palavras que hoje lhe ordeno estejam em seu coração.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 7, 'Ensine-as com persistência a seus filhos. Converse sobre elas quando estiver sentado em casa, quando estiver andando pelo caminho, quando se deitar e quando se levantar.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 8, 'Amarre-as como um sinal nos braços e prenda-as na testa.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 9, 'Escreva-as nos batentes das portas de sua casa e em seus portões.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 10, 'O Senhor, o seu Deus, os conduzirá à terra que jurou aos seus antepassados, Abraão, Isaque e Jacó, que daria a vocês, terra com grandes e boas cidades que vocês não construíram,', 3, CURRENT_TIMESTAMP, false),
(5, 6, 11, 'com casas cheias de tudo que há de melhor, de coisas que vocês não produziram, com cisternas que vocês não cavaram, com vinhas e oliveiras que não plantaram. Quando isso acontecer, e vocês comerem e ficarem satisfeitos,', 3, CURRENT_TIMESTAMP, false),
(5, 6, 12, 'tenham cuidado! Não esqueçam o Senhor que os tirou do Egito, da terra da escravidão.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 13, 'Temam o Senhor, o seu Deus, e só a ele prestem culto, e jurem somente pelo seu nome.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 14, 'Não sigam outros deuses, os deuses dos povos ao redor;', 3, CURRENT_TIMESTAMP, false),
(5, 6, 15, 'pois o Senhor, o seu Deus, que está no meio de vocês, é Deus zeloso; a ira do Senhor, o seu Deus, se acenderá contra vocês, e ele os banirá da face da terra.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 16, 'Não ponham à prova o Senhor, o seu Deus, como fizeram em Massá.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 17, 'Obedeçam cuidadosamente aos mandamentos do Senhor, o seu Deus, e aos preceitos e decretos que ele lhes ordenou.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 18, 'Façam o que é justo e bom perante o Senhor, para que tudo lhes vá bem e vocês entrem e tomem posse da boa terra que o Senhor prometeu, sob juramento, a seus antepassados,', 3, CURRENT_TIMESTAMP, false),
(5, 6, 19, 'expulsando todos os seus inimigos de diante de vocês, conforme o Senhor prometeu.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 20, 'No futuro, quando o seu filho lhes perguntar: "O que significam estes preceitos, decretos e ordenanças que o Senhor, o nosso Deus, ordenou a vocês? "', 3, CURRENT_TIMESTAMP, false),
(5, 6, 21, 'Vocês lhe responderão: "Fomos escravos do faraó no Egito, mas o Senhor nos tirou do Egito com mão poderosa.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 22, 'O Senhor realizou, diante dos nossos olhos, sinais e maravilhas grandiosas e terríveis contra o Egito e contra o faraó e toda a sua família.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 23, 'Mas ele nos tirou de lá para nos trazer para cá e nos dar a terra que, sob juramento, prometeu a nossos antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 24, 'O Senhor nos ordenou que obedecêssemos a todos estes decretos e que temêssemos o Senhor, o nosso Deus, para que sempre fôssemos bem sucedidos e preservados em vida, como hoje se pode ver.', 3, CURRENT_TIMESTAMP, false),
(5, 6, 25, 'E, se nós nos aplicarmos a obedecer a toda essa lei perante o Senhor, o nosso Deus, conforme ele nos ordenou, esta será a nossa justiça".', 3, CURRENT_TIMESTAMP, false),
(5, 7, 1, 'Quando o Senhor, o seu Deus, os fizer entrar na terra, para a qual vocês estão indo para dela tomar posse, ele expulsará de diante de vocês muitas nações: os hititas, os girgaseus, os amorreus, os cananeus, os ferezeus, os heveus e os jebuseus. São sete nações maiores e mais fortes do que vocês;', 3, CURRENT_TIMESTAMP, false),
(5, 7, 2, 'e quando o Senhor seu Deus as tiver entregue a vocês, e vocês as tiverem derrotado, então vocês as destruirão totalmente. Não façam com elas tratado algum, e não tenham piedade delas.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 3, 'Não se casem com pessoas de lá. Não dêem suas filhas aos filhos delas, nem tomem as filhas delas para os seus filhos,', 3, CURRENT_TIMESTAMP, false),
(5, 7, 4, 'pois elas desviariam seus filhos de seguir-me para servir a outros deuses e, por causa disso, a ira do Senhor se acenderia contra vocês e rapidamente os destruiria.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 5, 'Assim vocês tratarão essas nações: Derrubem os seus altares, quebrem as suas colunas sagradas, cortem os seus postes sagrados e queimem os seus ídolos.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 6, 'Pois vocês são um povo santo para o Senhor, o seu Deus. O Senhor, o seu Deus, os escolheu dentre todos os povos da face da terra para ser o seu povo, o seu tesouro pessoal.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 7, 'O Senhor não se afeiçoou a vocês nem os escolheu por serem mais numerosos do que os outros povos, pois vocês eram o menor de todos os povos.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 8, 'Mas foi porque o Senhor os amou e por causa do juramento que fez aos seus antepassados. Por isso ele os tirou com mão poderosa e os redimiu da terra da escravidão, do poder do faraó, rei do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 9, 'Saibam, portanto, que o Senhor, o seu Deus, é Deus; ele é o Deus fiel, que mantém a aliança e a bondade por mil gerações daqueles que o amam e guardam os seus mandamentos.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 10, 'Mas àqueles que o desprezam, retribuirá com destruição; ele não demora em retribuir àqueles que o desprezam.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 11, 'Obedeçam, pois, à lei, isto é, aos decretos e às ordenanças que hoje lhes ordeno.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 12, 'Se vocês obedecerem a essas ordenanças, as guardarem e as cumprirem, então o Senhor, o seu Deus, manterá com vocês a aliança e a bondade que prometeu sob juramento aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 13, 'Ele os amará, os abençoará e fará com que vocês se multipliquem. Ele abençoará os seus filhos e os frutos da sua terra: o cereal, o vinho novo e o azeite, as crias das vacas e das ovelhas, na terra que jurou dar aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 14, 'Vocês serão mais abençoados do que qualquer outro povo! Nenhum dos seus homens ou mulheres será estéril, nem mesmo os animais do seu rebanho.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 15, 'O Senhor os guardará de todas as doenças. Não infligirá a vocês as doenças terríveis que, como sabem, atingiram o Egito, mas as infligirá a todos os seus inimigos.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 16, 'Vocês destruirão todos os povos que o Senhor, o seu Deus, lhes entregar. Não olhem com piedade para eles, nem sirvam aos seus deuses, pois isso lhes seria uma armadilha.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 17, 'Talvez vocês digam a si mesmos: "Essas nações são mais fortes do que nós. Como poderemos expulsá-las? "', 3, CURRENT_TIMESTAMP, false),
(5, 7, 18, 'Não tenham medo delas! Lembrem-se bem do que o Senhor, o seu Deus, fez ao faraó e a todo o Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 19, 'Vocês viram com os próprios olhos as grandes provas, os sinais miraculosos e as maravilhas, a mão poderosa e o braço forte com que o Senhor, o seu Deus, os tirou de lá. O Senhor, o seu Deus, fará o mesmo com todos os povos que agora vocês temem.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 20, 'Além disso, o Senhor, o seu Deus, causará pânico entre eles até destruir o restante deles, os que se esconderam de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 21, 'Não fiquem apavorados por causa deles, pois o Senhor, o seu Deus, que está com vocês, é Deus grande e temível.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 22, 'O Senhor, o seu Deus, expulsará, aos poucos, essas nações de diante de vocês. Vocês não poderão eliminá-las de uma só vez, se não os animais selvagens se multiplicarão, ameaçando-os.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 23, 'Mas o Senhor, o seu Deus, as entregará a vocês, lançando-as em grande confusão, até que sejam destruídas.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 24, 'Ele entregará nas mãos de vocês os reis dessas nações, e vocês apagarão o nome deles de debaixo do céu. Ninguém conseguirá resistir a vocês até que os tenham destruído.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 25, 'Vocês queimarão as imagens dos deuses dessas nações. Não cobicem a prata e o ouro de que são revestidas; isso lhes seria uma armadilha. Para o Senhor, o seu Deus, isso é detestável.', 3, CURRENT_TIMESTAMP, false),
(5, 7, 26, 'Não levem coisa alguma que seja detestável para dentro de casa, se não também vocês serão separados para a destruição. Considerem-na proibida e detestem-na totalmente, pois está separada para a destruição.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 1, 'Tenham o cuidado de obedecer toda a lei que eu hoje lhes ordeno, para que vocês vivam, multipliquem-se e tomem posse da terra que o Senhor prometeu, com juramento, aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 2, 'Lembre-se de como o Senhor, o seu Deus, os conduziu por todo o caminho no deserto, durante estes quarenta anos, para humilhá-los e pô-los à prova, a fim de conhecer suas intenções, se iriam obedecer aos seus mandamentos ou não.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 3, 'Assim, ele os humilhou e os deixou passar fome. Mas depois os sustentou com maná, que nem vocês nem os seus antepassados conheciam, para mostrar-lhe que nem só de pão viverá o homem, mas de toda palavra que procede da boca do Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 4, 'As roupas de vocês não se gastaram e os seus pés não incharam durante esses quarenta anos.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 5, 'Saibam, pois, em seu coração que, assim como um homem disciplina o seu filho, da mesma forma o Senhor, o seu Deus, os disciplina.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 6, 'Obedeçam aos mandamentos do Senhor, o seu Deus, andando em seus caminhos e dele tendo temor.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 7, 'Pois o Senhor, o seu Deus, os está levando a uma boa terra, cheia de riachos e tanques de água, de fontes que jorram nos vales e nas colinas;', 3, CURRENT_TIMESTAMP, false),
(5, 8, 8, 'terra de trigo e cevada, videiras e figueiras e romãzeiras, azeite de oliva e mel;', 3, CURRENT_TIMESTAMP, false),
(5, 8, 9, 'terra onde não faltará pão e onde não terão falta de nada; terra onde as rochas têm ferro e onde você poderá escavar cobre nas colinas.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 10, 'Depois que tiverem comido até ficarem satisfeitos, louvem ao Senhor, o seu Deus, pela boa terra que lhe deu.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 11, 'Tenham o cuidado de não se esquecer do Senhor, do seu Deus, deixando de obedecer aos seus mandamentos, às suas ordenanças e aos seus decretos que hoje lhes ordeno.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 12, 'Não aconteça que, depois de terem comido até ficarem satisfeitos, de terem construído boas casas e nelas morado,', 3, CURRENT_TIMESTAMP, false),
(5, 8, 13, 'de aumentarem os seus rebanhos, a sua prata e o seu ouro, e todos os seus bens,', 3, CURRENT_TIMESTAMP, false),
(5, 8, 14, 'o seu coração fique orgulhoso e vocês se esqueçam do Senhor, do seu Deus, que os tirou do Egito, da terra da escravidão.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 15, 'Ele os conduziu pelo imenso e pavoroso deserto, por aquela terra seca e sem água, de serpentes e escorpiões venenosos. Ele tirou água da rocha para vocês,', 3, CURRENT_TIMESTAMP, false),
(5, 8, 16, 'e o sustentou no deserto com maná, que os seus antepassados não conheciam, para humilhá-los e prová-los, a fim de que tudo fosse bem com vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 17, 'Não digam, pois, em seu coração: "A minha capacidade e a força das minhas mãos ajuntaram para mim toda esta riqueza".', 3, CURRENT_TIMESTAMP, false),
(5, 8, 18, 'Mas, lembrem-se do Senhor, do seu Deus, pois é ele que lhes dá a capacidade de produzir riqueza, confirmando a aliança que jurou aos seus antepassados, conforme hoje se vê.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 19, 'Mas se vocês se esquecerem do Senhor, do seu Deus, e seguirem outros deuses, prestando-lhes culto e curvando-se diante deles, asseguro-lhes hoje que vocês serão destruídos.', 3, CURRENT_TIMESTAMP, false),
(5, 8, 20, 'Por não obedecerem ao Senhor, ao seu Deus, vocês serão destruídos como o foram as outras nações que o Senhor destruiu perante vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 1, 'Ouça, ó Israel: Hoje você está atravessando o Jordão para entrar na terra e conquistar nações maiores e mais poderosas do que você, as quais têm cidades grandes, com muros que vão até o céu.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 2, 'O povo é forte e alto. São enaquins! Você já ouviu falar deles e até conhece o que se diz: "Quem é capaz de resistir aos enaquins? "', 3, CURRENT_TIMESTAMP, false),
(5, 9, 3, 'Esteja, hoje, certo de que o Senhor, o seu Deus, ele mesmo, vai adiante de você como fogo consumidor. Ele os exterminará e os subjugará diante de você. E você os expulsará e os destruirá, como o Senhor lhe prometeu.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 4, 'Depois que o Senhor, o seu Deus, os tiver expulsado da presença de você, não diga a si mesmo: "O Senhor nos trouxe aqui para tomarmos posse desta terra por causa da nossa justiça". Não! É devido à impiedade destas nações que o Senhor vai expulsá-las da presença de você.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 5, 'Não é por causa de sua justiça ou de sua retidão que você conquistará a terra deles. Mas é por causa da maldade destas nações que o Senhor, o seu Deus, as expulsará de diante de você, para cumprir a palavra que o Senhor prometeu, sob juramento, aos seus antepassados, Abraão, Isaque e Jacó.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 6, 'Portanto, esteja certo de que não é por causa de sua justiça que o Senhor seu Deus lhe dá esta boa terra para dela tomar posse, pois você é um povo obstinado.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 7, 'Lembrem-se disto e jamais esqueçam como vocês provocaram a ira do Senhor, o seu Deus, no deserto. Desde o dia em que saíram do Egito até chegarem aqui, vocês têm sido rebeldes contra o Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 8, 'Até mesmo em Horebe vocês provocaram o Senhor à ira, e ele ficou furioso, a ponto de querer exterminá-los.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 9, 'Quando subi o monte para receber as tábuas de pedra, as tábuas da aliança que o Senhor tinha feito com vocês, fiquei no monte quarenta dias e quarenta noites; não comi pão, nem bebi água.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 10, 'O Senhor me deu as duas tábuas de pedra escritas pelo dedo de Deus. Nelas estavam escritas todas as palavras que o Senhor proclamou a vocês no monte, de dentro do fogo, no dia da assembléia.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 11, 'Passados os quarenta dias e quarenta noites, o Senhor me deu as duas tábuas de pedra, as tábuas da aliança,', 3, CURRENT_TIMESTAMP, false),
(5, 9, 12, 'e me disse: "Desça imediatamente, pois o seu povo, que você tirou do Egito, corrompeu-se. Eles se afastaram bem depressa do caminho que eu lhes ordenei e fizeram um ídolo de metal para si".', 3, CURRENT_TIMESTAMP, false),
(5, 9, 13, 'E o Senhor me disse: "Vejo que este povo é realmente um povo obstinado!', 3, CURRENT_TIMESTAMP, false),
(5, 9, 14, 'Deixe que eu os destrua e apague o nome deles de debaixo do céu. E farei de você uma nação mais forte e mais numerosa do que eles".', 3, CURRENT_TIMESTAMP, false),
(5, 9, 15, 'Então voltei e desci do monte, enquanto este ardia em chamas. E as duas tábuas da aliança estavam em minhas mãos.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 16, 'E vi que vocês tinham pecado contra o Senhor, o Deus de vocês. Fizeram para si um ídolo de metal em forma de bezerro. Bem depressa vocês se desviaram do caminho que o Senhor, o Deus de vocês, lhes tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 17, 'Então peguei as duas tábuas e as lancei das minhas mãos, quebrando-as diante dos olhos de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 18, 'Depois prostrei-me perante o Senhor outros quarenta dias e quarenta noites; não comi pão, nem bebi água, por causa do grande pecado que vocês tinham cometido, fazendo o que o Senhor reprova, provocando a ira dele.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 19, 'Tive medo da ira e do furor do Senhor, pois ele estava suficientemente irado para destruí-los, mas de novo o Senhor me escutou.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 20, 'O Senhor irou-se contra Arão a ponto de querer destruí-lo, mas naquela ocasião também orei por Arão.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 21, 'Então peguei o bezerro, o bezerro do pecado de vocês, e o queimei no fogo; depois o esmigalhei e o moí até virar pó, e o joguei no riacho que desce do monte.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 22, 'Além disso, vocês tornaram a provocar o Senhor à ira em Taberá, em Massá e em Quibrote-Hataavá.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 23, 'E, quando o Senhor os enviou de Cades-Barnéia, disse: "Entrem lá e tomem posse da terra que lhes dei". Mas vocês se rebelaram contra a ordem do Senhor, do seu Deus. Não confiaram nele, nem lhe obedeceram.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 24, 'Vocês têm sido rebeldes contra o Senhor desde que os conheço.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 25, 'Fiquei prostrado perante o Senhor durante aqueles quarenta dias e quarenta noites porque o Senhor tinha dito que ia destruí-los.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 26, 'Foi quando orei ao Senhor, dizendo: Ó Soberano Senhor, não destruas o teu povo, a tua própria herança! Tu o redimiste com a tua grandeza e o tiraste da terra do Egito com mão poderosa.', 3, CURRENT_TIMESTAMP, false),
(5, 9, 27, 'Lembra-te de teus servos Abraão, Isaque e Jacó. Não leves em conta a obstinação deste povo, a sua maldade e o seu pecado,', 3, CURRENT_TIMESTAMP, false),
(5, 9, 28, 'se não os habitantes da terra de onde nos tiraste dirão: "Como o Senhor não conseguiu levá-los à terra que lhes havia prometido, e como ele os odiava, tirou-os para fazê-los morrer no deserto".', 3, CURRENT_TIMESTAMP, false),
(5, 9, 29, 'Mas eles são o teu povo, a tua herança, que tiraste do Egito com o teu grande poder e com o teu braço forte.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 1, 'Naquela ocasião o Senhor me ordenou: "Corte duas tábuas de pedra, como as primeiras, e suba para encontrar-se comigo no monte. Faça também uma arca de madeira.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 2, 'Eu escreverei nas tábuas as palavras que estavam nas primeiras, que você quebrou, e você as colocará na arca".', 3, CURRENT_TIMESTAMP, false),
(5, 10, 3, 'Então fiz a arca de madeira de acácia, cortei duas tábuas de pedra como as primeiras e subi o monte com as duas tábuas nas mãos.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 4, 'O Senhor escreveu nelas o que tinha escrito anteriormente, os Dez Mandamentos que havia proclamado a vocês no monte, do meio do fogo, no dia em que estavam todos reunidos. O Senhor as entregou a mim,', 3, CURRENT_TIMESTAMP, false),
(5, 10, 5, 'e eu voltei, desci do monte e coloquei as tábuas na arca que eu tinha feito. E lá ficaram, conforme o Senhor tinha ordenado.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 6, '( Os israelitas partiram dos poços dos jaacanitas e foram até Moserá. Ali Arão morreu e foi sepultado, e o seu filho Eleazar foi o seu sucessor como sacerdote.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 7, 'Dali foram para Gudgodá e de lá para Jotbatá, terra de riachos.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 8, 'Naquela ocasião o Senhor separou a tribo de Levi para carregar a arca da aliança do Senhor, para estar perante o Senhor a fim de ministrar e pronunciar bênçãos em seu nome, como se faz ainda hoje.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 9, 'É por isso que os levitas não têm nenhuma porção de terra ou herança entre os seus irmãos; o Senhor é a sua herança, conforme o Senhor, o seu Deus, lhes havia prometido. )', 3, CURRENT_TIMESTAMP, false),
(5, 10, 10, 'Assim eu fiquei no monte quarenta dias e quarenta noites, como da primeira vez; e também desta vez o Senhor me atendeu e não quis destruí-los.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 11, '"Vá", o Senhor me disse. "Conduza o povo em seu caminho, para que tomem posse da terra que jurei aos seus antepassados que lhes daria. "', 3, CURRENT_TIMESTAMP, false),
(5, 10, 12, 'E agora, ó Israel, que é que o Senhor seu Deus pede de você, senão que tema o Senhor, o seu Deus, que ande em todos os seus caminhos, que o ame e que sirva ao Senhor, ao seu Deus, de todo o seu coração e de toda a sua alma,', 3, CURRENT_TIMESTAMP, false),
(5, 10, 13, 'e que obedeça aos mandamentos e aos decretos do Senhor, que hoje lhe dou para o seu próprio bem?', 3, CURRENT_TIMESTAMP, false),
(5, 10, 14, 'Ao Senhor, ao seu Deus, pertencem os céus e até os mais altos céus, a terra e tudo o que nela existe.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 15, 'No entanto, o Senhor se afeiçoou aos seus antepassados e os amou, e a vocês, descendentes deles, escolheu entre todas as nações, como hoje se vê.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 16, 'Sejam fiéis à sua aliança em seus corações, e deixem de ser obstinados.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 17, 'Pois o Senhor, o seu Deus, é o Deus dos deuses e o Soberano dos soberanos, o grande Deus, poderoso e temível, que não age com parcialidade nem aceita suborno.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 18, 'Ele defende a causa do órfão e da viúva e ama o estrangeiro, dando-lhe alimento e roupa.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 19, 'Amem os estrangeiros, pois vocês mesmos foram estrangeiros no Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 20, 'Temam o Senhor, o seu Deus, e sirvam-no. Apeguem-se a ele e façam os seus juramentos somente em nome dele.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 21, 'Seja ele o motivo do seu louvor, pois ele é o seu Deus, que por vocês fez aquelas grandes e temíveis maravilhas que vocês viram com os próprios olhos.', 3, CURRENT_TIMESTAMP, false),
(5, 10, 22, 'Os seus antepassados que desceram ao Egito eram setenta ao todo, mas agora o Senhor, o seu Deus, os tornou tão numerosos quanto as estrelas do céu.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 1, 'Amem o Senhor, o seu Deus e obedeçam sempre aos seus preceitos, aos seus decretos, às suas ordenanças e aos seus mandamentos.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 2, 'Lembrem-se hoje de que não foram os seus filhos que experimentaram e viram a disciplina do Senhor, o seu Deus, a sua majestade, a sua mão poderosa, o seu braço forte.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 3, 'Vocês viram os sinais que ele realizou e tudo o que fez no coração do Egito, tanto com o faraó, rei do Egito, quanto com toda a sua terra;', 3, CURRENT_TIMESTAMP, false),
(5, 11, 4, 'o que fez com o exército egípcio, com os seus cavalos e carros, como os surpreendeu com as águas do mar Vermelho, quando estavam perseguindo vocês, e como o Senhor os destruiu para sempre.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 5, 'Vocês também viram o que ele fez por vocês no deserto até chegarem a este lugar,', 3, CURRENT_TIMESTAMP, false),
(5, 11, 6, 'e o que fez a Datã e a Abirão, filhos de Eliabe, da tribo de Rúben, quando a terra abriu a boca no meio de todo o Israel e os engoliu com suas famílias, suas tendas e tudo o que lhes pertencia.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 7, 'Vocês mesmos viram com os próprios olhos todas essas coisas grandiosas que o Senhor fez.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 8, 'Obedeçam, portanto, a toda a lei que hoje lhes estou dando, para que tenham forças para invadir e conquistar a terra para onde estão indo,', 3, CURRENT_TIMESTAMP, false),
(5, 11, 9, 'e para que vivam muito tempo na terra que o Senhor jurou dar aos seus antepassados e aos descendentes deles, terra onde manam leite e mel.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 10, 'A terra da qual vocês vão tomar posse não é como a terra do Egito, de onde vocês vieram e onde plantavam as sementes e tinham que fazer a irrigação a pé, como numa horta.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 11, 'Mas a terra em que vocês, atravessando o Jordão, vão entrar para dela tomar posse, é terra de montes e vales, que bebe chuva do céu.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 12, 'É uma terra da qual o Senhor, o seu Deus, cuida; os olhos do Senhor, do seu Deus, estão continuamente sobre ela, do início ao fim do ano.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 13, 'Portanto, se vocês obedecerem fielmente aos mandamentos que hoje lhes dou, amando o Senhor, o seu Deus, e servindo-o de todo o coração e de toda a alma,', 3, CURRENT_TIMESTAMP, false),
(5, 11, 14, 'então, no devido tempo, enviarei chuva sobre a sua terra, chuva de outono e de primavera, para que vocês recolham o seu cereal, e tenham vinho novo e azeite.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 15, 'Ela dará pasto nos campos para os seus rebanhos, e quanto a vocês, terão o que comer e ficarão satisfeitos.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 16, 'Por isso, tenham cuidado para não serem enganados e levados a desviar-se para adorar outros deuses e a prostrar-se perante eles.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 17, 'Caso contrário, a ira do Senhor se acenderá contra vocês e ele fechará o céu para que não chova e para que a terra nada produza e assim vocês logo desaparecerão da boa terra que o Senhor lhes está dando.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 18, 'Gravem estas minhas palavras no coração e na mente; amarrem-nas como símbolos nas mãos e prendam-nas na testa.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 19, 'Ensinem-nas a seus filhos, conversando a respeito delas quando estiverem sentados em casa e quando estiverem andando pelo caminho, quando se deitarem e quando se levantarem.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 20, 'Escrevam-nas nos batentes das portas de suas casas, e nos seus portões,', 3, CURRENT_TIMESTAMP, false),
(5, 11, 21, 'para que, na terra que o Senhor jurou que daria aos seus antepassados, os seus dias e os dias dos seus filhos sejam muitos, sejam tantos como os dias durante os quais o céu está acima da terra.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 22, 'Se vocês obedecerem cuidadosamente todo o mandamento que lhes mando cumprir, amando o Senhor, o seu Deus, andando em todos os seus caminhos e apegando-se a ele,', 3, CURRENT_TIMESTAMP, false),
(5, 11, 23, 'então o Senhor expulsará todas essas nações da presença de vocês, e vocês despojarão nações maiores e mais fortes do que vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 24, 'Todo lugar onde vocês puserem os pés será de vocês. O seu território se estenderá do deserto do Líbano e do rio Eufrates ao mar Ocidental.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 25, 'Ninguém conseguirá resisti-los. O Senhor, o seu Deus, conforme lhes prometeu, trará pavor e medo de vocês a todos os povos daquela terra, aonde quer que vocês forem.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 26, 'Prestem atenção! Hoje estou pondo diante de vocês a bênção e a maldição.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 27, 'Vocês terão bênção, se obedecerem aos mandamentos do Senhor, o seu Deus, que hoje lhes estou dando;', 3, CURRENT_TIMESTAMP, false),
(5, 11, 28, 'mas terão maldição, se desobedecerem aos mandamentos do Senhor, o seu Deus, e se afastarem do caminho que hoje lhes ordeno, para seguir deuses desconhecidos.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 29, 'Quando o Senhor, o seu Deus, os tiver levado para a terra da qual vão tomar posse, vocês terão que proclamar a bênção no monte Gerizim, e a maldição no monte Ebal.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 30, 'Como sabem, esses montes estão do outro lado do Jordão, a oeste da estrada, na direção do poente, perto dos carvalhos de Moré, no território dos cananeus que vivem na Arabá, próximos de Gilgal.', 3, CURRENT_TIMESTAMP, false),
(5, 11, 31, 'Vocês estão a ponto de atravessar o Jordão e de tomar posse da terra que o Senhor, o seu Deus, lhes está dando. Quando vocês a tiverem conquistado e estiverem vivendo ali,', 3, CURRENT_TIMESTAMP, false),
(5, 11, 32, 'tenham o cuidado de obedecer a todos os decretos e ordenanças que hoje estou dando a vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 1, 'Estes são os decretos e ordenanças que vocês devem ter o cuidado de cumprir enquanto viverem na terra que o Senhor, o Deus dos seus antepassados, deu a vocês como herança.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 2, 'Destruam completamente todos os lugares nos quais as nações que vocês estão desalojando adoram os seus deuses, tanto nos altos montes como nas colinas e à sombra de toda árvore frondosa.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 3, 'Derrubem os seus altares, esmigalhem as suas colunas sagradas e queimem os seus postes sagrados; despedacem os ídolos dos seus deuses e eliminem os nomes deles daqueles lugares.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 4, 'Vocês, porém, não adorarão ao Senhor, o seu Deus, como eles.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 5, 'Mas procurarão o local que o Senhor, o seu Deus, escolher dentre todas as tribos para ali pôr o seu nome para sua habitação. Para lá vocês deverão ir', 3, CURRENT_TIMESTAMP, false),
(5, 12, 6, 'e levar holocaustos e sacrifícios, dízimos e dádivas especiais, o que em voto tiverem prometido, as suas ofertas voluntárias e a primeira cria de todos os rebanhos.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 7, 'Ali, na presença do Senhor, do seu Deus, vocês e suas famílias comerão e se alegrarão com tudo o que tiverem feito, pois o Senhor, o seu Deus, os terá abençoado.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 8, 'Vocês não agirão como estamos agindo aqui, cada um fazendo o que bem entende,', 3, CURRENT_TIMESTAMP, false),
(5, 12, 9, 'pois ainda não chegaram ao lugar de descanso e à herança que o Senhor, o seu Deus, lhes está dando.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 10, 'Mas vocês atravessarão o Jordão e se estabelecerão na terra que o Senhor, o seu Deus, lhes dá como herança, e ele lhes concederá descanso de todos os inimigos que os cercam, para que vocês vivam em segurança.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 11, 'Então, para o lugar que o Senhor, o seu Deus, escolher como habitação do seu Nome, vocês levarão tudo o que eu lhes ordenar: holocaustos e sacrifícios, dízimos e dádivas especiais e tudo o que tiverem prometido em voto ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 12, 'E regozijem-se ali perante o Senhor, o seu Deus, vocês, os seus filhos e filhas, os seus servos e servas e os levitas que vivem nas cidades de vocês, por não terem recebido terras nem propriedades.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 13, 'Tenham o cuidado de não sacrificar os seus holocaustos em qualquer lugar que lhes agrade.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 14, 'Ofereçam-nos somente no local que o Senhor escolher numa das suas tribos, e ali ponham em prática tudo o que eu lhes ordenar.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 15, 'No entanto, vocês poderão abater os seus animais em qualquer das suas cidades e comer quanta carne desejarem, como se fosse carne de gazela ou de veado, de acordo com a bênção que o Senhor, o seu Deus, lhes der. Tanto os cerimonialmente impuros quanto os puros poderão comê-la.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 16, 'Mas não poderão comer o sangue; derramem-no no chão como se fosse água.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 17, 'Vocês não poderão comer em suas próprias cidades o dízimo do cereal, do vinho novo e do azeite, nem a primeira cria dos rebanhos, nem o que, em voto, tiverem prometido, nem as suas ofertas voluntárias ou dádivas especiais.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 18, 'Ao invés disso, vocês os comerão na presença do Senhor, do seu Deus, no local que o Senhor, o seu Deus, escolher; vocês, os seus filhos e filhas, os seus servos e servas, e os levitas das suas cidades. Alegrem-se perante o Senhor, o seu Deus, em tudo o que fizerem.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 19, 'Tenham o cuidado de não abandonar os levitas enquanto vocês viverem na sua terra.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 20, 'Quando o Senhor, o seu Deus, tiver aumentado o seu território conforme lhes prometeu, e vocês desejarem comer carne e disserem: "Gostaríamos de um pouco de carne", poderão comer o quanto quiserem.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 21, 'Se o local que o Senhor, o seu Deus, escolher para pôr o seu Nome ficar longe demais, vocês poderão abater animais de todos os rebanhos que o Senhor lhes der, conforme lhes ordenei, e em suas próprias cidades poderão comer quanta carne desejarem.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 22, 'Vocês a comerão como comeriam carne de gazela ou de veado. Tanto os cerimonialmente impuros quanto os puros poderão comer.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 23, 'Mas não comam o sangue, porque o sangue é a vida, e vocês não poderão comer a vida com o sangue.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 24, 'Vocês não comerão o sangue; derramem-no no chão como se fosse água.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 25, 'Não o comam, para que tudo vá bem com vocês e com os seus filhos, porque estarão fazendo o que é justo perante o Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 26, 'Todavia, apanhem os seus objetos consagrados e o que, em voto, tiverem prometido, e dirijam-se ao local que o Senhor escolher.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 27, 'Apresentem os seus holocaustos colocando-os no altar do Senhor, do seu Deus, tanto a carne quanto o sangue. O sangue dos seus sacrifícios será derramado ao lado do altar do Senhor, do seu Deus, mas vocês poderão comer a carne.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 28, 'Tenham o cuidado de obedecer a todos estes regulamentos que lhe estou dando, para que sempre vá tudo bem com vocês e com os seus filhos, porque estarão fazendo o que é bom e certo perante o Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 29, 'O Senhor, o seu Deus, eliminará da sua presença as nações que vocês estão a ponto de invadir e expulsar. Mas, quando vocês as tiverem expulsado e tiverem se estabelecido na terra delas,', 3, CURRENT_TIMESTAMP, false),
(5, 12, 30, 'e depois que elas forem destruídas, tenham cuidado para não serem enganados e para não se interessarem pelos deuses delas, dizendo: "Como essas nações servem aos seus deuses? Faremos o mesmo".', 3, CURRENT_TIMESTAMP, false),
(5, 12, 31, 'Não adorem ao Senhor, ao seu Deus, como fazem essas nações, porque, ao adorarem os seus deuses, elas fazem todo tipo de coisas repugnantes que o Senhor odeia, como queimar seus filhos e filhas no fogo em sacrifícios aos seus deuses.', 3, CURRENT_TIMESTAMP, false),
(5, 12, 32, 'Apliquem-se a fazer tudo o que eu lhes ordeno; não lhe acrescentem nem lhe tirem coisa alguma.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 1, 'Se aparecer entre vocês um profeta ou alguém que faz predições por meio de sonhos e lhes anunciar um sinal miraculoso ou um prodígio,', 3, CURRENT_TIMESTAMP, false),
(5, 13, 2, 'e se o sinal ou prodígio de que ele falou acontecer, e ele disser: "Vamos seguir outros deuses que vocês não conhecem e vamos adorá-los",', 3, CURRENT_TIMESTAMP, false),
(5, 13, 3, 'não dêem ouvidos às palavras daquele profeta ou sonhador. O Senhor, o seu Deus, está pondo vocês à prova para ver se o amam de todo o coração e de toda a alma.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 4, 'Sigam somente o Senhor, o seu Deus, e temam a ele somente. Cumpram os seus mandamentos e obedeçam-lhe; sirvam-no e apeguem-se a ele.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 5, 'Aquele profeta ou sonhador terá que ser morto, pois pregou rebelião contra o Senhor, contra o seu Deus, que os tirou do Egito e os redimiu da terra da escravidão; ele tentou afastá-los do caminho que o Senhor, o seu Deus, lhes ordenou que seguissem. Eliminem o mal do meio de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 6, 'Se o seu próprio irmão ou filho ou filha, ou a mulher que você ama ou o seu amigo mais chegado secretamente instigá-lo, dizendo: "Vamos adorar outros deuses! " — deuses que nem você nem os seus antepassados conheceram,', 3, CURRENT_TIMESTAMP, false),
(5, 13, 7, 'deuses dos povos que vivem ao seu redor, quer próximos, quer distantes, de um ao outro lado da terra —', 3, CURRENT_TIMESTAMP, false),
(5, 13, 8, 'não se deixe convencer nem ouça o que ele diz. Não tenha piedade nem compaixão dele e não o proteja.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 9, 'Você terá que matá-lo. Seja a sua mão a primeira a levantar-se para matá-lo, e depois as mãos de todo o povo.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 10, 'Apedreje-o até à morte, porque tentou desviá-lo do Senhor, o seu Deus, que o tirou do Egito, da terra da escravidão.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 11, 'Então todo o Israel saberá disso; todos temerão e ninguém tornará a cometer uma maldade dessas.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 12, 'Se vocês ouvirem dizer que numa das cidades que o Senhor, o seu Deus, lhes dá para nelas morarem,', 3, CURRENT_TIMESTAMP, false),
(5, 13, 13, 'surgiram homens perversos e desviaram os seus habitantes, dizendo: "Vamos adorar outros deuses! ", deuses que vocês não conhecem,', 3, CURRENT_TIMESTAMP, false),
(5, 13, 14, 'vocês deverão verificar e investigar. Se for verdade e ficar comprovado que se praticou esse ato detestável entre vocês,', 3, CURRENT_TIMESTAMP, false),
(5, 13, 15, 'matem ao fio da espada todos os que viverem naquela cidade. Destruam totalmente a cidade, matando tanto os seus habitantes quanto os seus animais.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 16, 'Ajuntem todos os despojos no meio da praça pública e queimem totalmente a cidade e todos os seus despojos, como oferta ao Senhor, ao seu Deus. Fique ela em ruínas para sempre, e nunca mais seja reconstruída.', 3, CURRENT_TIMESTAMP, false),
(5, 13, 17, 'Não seja encontrado em suas mãos nada do que foi destinado à destruição, para que o Senhor se afaste do fogo da sua ira; terá misericórdia e compaixão de vocês, e os fará multiplicar, conforme prometeu sob juramento aos seus antepassados,', 3, CURRENT_TIMESTAMP, false),
(5, 13, 18, 'somente se obedecerem ao Senhor, ao seu Deus, guardando todos os seus mandamentos, que lhes estou dando, e fazendo o que é justo aos seus olhos.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 1, 'Vocês são os filhos do Senhor, do seu Deus. Não façam cortes no corpo nem rapem a frente da cabeça por causa dos mortos,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 2, 'pois vocês são povo consagrado ao Senhor, ao seu Deus. Dentre todos os povos da face da terra, o Senhor os escolheu para serem o seu tesouro pessoal.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 3, 'Não comam nada que seja proibido.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 4, 'São estes os animais que vocês podem comer: o boi, a ovelha, o bode,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 5, 'o veado, a gazela, a corça, o bode montês, o antílope, o bode selvagem e a ovelha montês.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 6, 'Vocês poderão comer qualquer animal que tenha o casco fendido e dividido em duas unhas e que rumine.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 7, 'Contudo, dos que ruminam ou têm o casco fendido, vocês não poderão comer o camelo, o coelho e o rato silvestre. Embora ruminem, não têm casco fendido; são impuros para vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 8, 'O porco também é impuro; embora tenha casco fendido, não rumina. Vocês não poderão comer a carne deles nem tocar em seus cadáveres.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 9, 'De todas as criaturas que vivem nas águas vocês poderão comer as que possuem barbatanas e escamas.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 10, 'Mas não poderão comer nenhuma criatura que não tiver barbatanas nem escamas; é impura para vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 11, 'Vocês poderão comer qualquer ave pura.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 12, 'Mas estas vocês não poderão comer: a águia, o urubu, a águia-marinha,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 13, 'o milhafre, qualquer espécie de falcão,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 14, 'qualquer espécie de corvo,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 15, 'a coruja-de-chifre, a coruja-de-orelha-pequena, a coruja-orelhuda, qualquer espécie de gavião,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 16, 'o mocho, o corujão, a coruja-branca,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 17, 'a coruja-do-deserto, o abutre, a coruja-pescadora,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 18, 'a cegonha, qualquer tipo de garça, a poupa e o morcego.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 19, 'Todas as pequenas criaturas que enxameiam e têm asas são impuras para vocês; não as comam.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 20, 'Mas qualquer criatura que têm asas, sendo pura, vocês poderão comer.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 21, 'Não comam nada que encontrarem morto. Vocês poderão dá-lo a um estrangeiro residente de qualquer cidade de vocês, e ele poderá comê-lo, ou vocês poderão vendê-lo a outros estrangeiros. Mas vocês são povo consagrado ao Senhor, ao seu Deus. Não cozinhem o cabrito no leite da própria mãe.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 22, 'Separem o dízimo de tudo o que a terra produzir anualmente.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 23, 'Comam o dízimo do cereal, do vinho novo e do azeite, e a primeira cria de todos os seus rebanhos na presença do Senhor, o seu Deus, no local que ele escolher como habitação do seu Nome, para que aprendam a temer sempre o Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 24, 'Mas, se o local for longe demais e vocês tiverem sido abençoados pelo Senhor, pelo seu Deus, e não puderem carregar o dízimo, pois o local escolhido pelo Senhor para ali pôr o seu Nome é longe demais,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 25, 'troquem o dízimo por prata, e levem a prata ao local que o Senhor, o seu Deus, tiver escolhido.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 26, 'Com prata comprem o que quiserem: bois, ovelhas, vinho ou outra bebida fermentada, ou qualquer outra coisa que desejarem. Então juntamente com suas famílias comam e alegrem-se ali, na presença do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 27, 'E nunca se esqueçam dos levitas que vivem em suas cidades, pois eles não possuem propriedade nem herança próprias.', 3, CURRENT_TIMESTAMP, false),
(5, 14, 28, 'Ao final de cada três anos, tragam todos os dízimos da colheita do terceiro ano e armazene-os em sua própria cidade,', 3, CURRENT_TIMESTAMP, false),
(5, 14, 29, 'para que os levitas, que não possuem propriedade nem herança, e os estrangeiros, os órfãos e as viúvas que vivem na sua cidade venham comer e saciar-se, e para que o Senhor, o seu Deus, o abençoe em todo o trabalho das suas mãos.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 1, 'No final de cada sete anos as dívidas deverão ser canceladas.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 2, 'Isso deverá ser feito da seguinte forma: Todo credor cancelará o empréstimo que fez ao seu próximo. Nenhum israelita exigirá pagamento de seu próximo ou de seu parente, porque foi proclamado o tempo do Senhor para o cancelamento das dívidas.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 3, 'Vocês poderão exigir pagamento do estrangeiro, mas terão que cancelar qualquer dívida de seus irmãos israelitas.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 4, 'Assim, não deverá haver pobre algum no meio de vocês, pois na terra que o Senhor, o seu Deus, lhes está dando como herança para que dela tomem posse, ele os abençoará ricamente,', 3, CURRENT_TIMESTAMP, false),
(5, 15, 5, 'contanto que obedeçam em tudo ao Senhor, ao seu Deus, e colocarem em prática toda esta lei que hoje lhes estou dando.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 6, 'Pois o Senhor, o seu Deus, os abençoará conforme prometeu, e vocês emprestarão a muitas nações, mas de nenhuma tomarão emprestado. Vocês dominarão muitas nações, mas por nenhuma serão dominados.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 7, 'Se houver algum israelita pobre em qualquer das cidades da terra que o Senhor, o seu Deus, lhe está dando, não endureçam o coração, nem fechem a mão para com o seu irmão pobre.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 8, 'Ao contrário, tenham mão aberta e emprestem-lhe liberalmente o que ele precisar.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 9, 'Cuidado! Que nenhum de vocês alimente este pensamento ímpio: "O sétimo ano, o ano do cancelamento das dívidas, está se aproximando, e não quero ajudar o meu irmão pobre". Ele poderá apelar para o Senhor contra você, e você será culpado pelo pecado.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 10, 'Dê-lhe generosamente, e sem relutância no coração; pois, por isso, o Senhor, o seu Deus, o abençoará em todo o seu trabalho e em tudo o que você fizer.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 11, 'Sempre haverá pobres na terra. Portanto, eu lhe ordeno que abra o coração para o seu irmão israelita, tanto para o pobre como para o necessitado de sua terra.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 12, 'Se seu concidadão hebreu, homem ou mulher, vender-se a você e servi-lo seis anos, no sétimo ano dê-lhe a liberdade.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 13, 'E, quando o fizer, não o mande embora de mãos vazias.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 14, 'Dê-lhe com generosidade dos animais do seu rebanho, do produto da sua eira e do seu lagar. Dê-lhe conforme a bênção que o Senhor, o seu Deus, lhe tem dado.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 15, 'Lembre-se de que você foi escravo no Egito e que o Senhor, o seu Deus, o redimiu. É por isso que hoje lhe dou essa ordem.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 16, 'Mas se o seu escravo lhe disser que não quer deixá-lo, porque ama você e sua família e não tem falta de nada,', 3, CURRENT_TIMESTAMP, false),
(5, 15, 17, 'então apanhe um furador e fure a orelha dele contra a porta, e ele se tornará seu escravo para o resto da vida. Faça o mesmo com a sua escrava.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 18, 'Não se sinta prejudicado ao libertar o seu escravo, pois o serviço que ele prestou a você nesses seis anos custou a metade do serviço de um trabalhador contratado. Além disso, o Senhor, o seu Deus, o abençoará em tudo o que você fizer.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 19, 'Separe para o Senhor, para o seu Deus, todo primeiro macho de todos os seus rebanhos. Não use a primeira cria das suas vacas para trabalhar, nem tosquie a primeira cria das suas ovelhas.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 20, 'Todo ano você e a sua família as comerão na presença do Senhor, do seu Deus, no local que ele escolher.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 21, 'Se o animal tiver defeito, ou for manco ou cego, ou tiver qualquer outro defeito grave, você não poderá sacrificá-lo ao Senhor, ao seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 22, 'Coma-o na cidade onde estiver morando. Tanto o cerimonialmente impuro quanto o puro o comerão, como se come a carne da gazela ou do veado.', 3, CURRENT_TIMESTAMP, false),
(5, 15, 23, 'Mas não poderá comer o sangue; derrame-o no chão como se fosse água.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 1, 'Observem o mês de abibe e celebrem a Páscoa do Senhor, do seu Deus, pois no mês de abibe, de noite, ele os tirou do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 2, 'Ofereçam como sacrifício da Páscoa ao Senhor, ao seu Deus, um animal dos rebanhos de bois ou de ovelhas no local que o Senhor escolher para habitação do seu Nome.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 3, 'Não o comam com pão fermentado, mas durante sete dias comam pães sem fermento, o pão da aflição, pois foi às pressas que vocês saíram do Egito, para que todos os dias da sua vida vocês se lembrem da época em que saíram do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 4, 'Durante sete dias, não permitam que seja encontrado fermento com vocês em toda a sua terra. Tampouco permitam que alguma carne sacrificada à tarde do primeiro dia permaneça até a manhã seguinte.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 5, 'Não ofereçam o sacrifício da Páscoa em nenhuma das cidades que o Senhor, o seu Deus, lhe der;', 3, CURRENT_TIMESTAMP, false),
(5, 16, 6, 'sacrifique-a apenas no local que ele escolher para habitação do seu Nome. Ali vocês oferecerão o sacrifício da Páscoa à tarde, ao pôr-do-sol, na data da sua partida do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 7, 'Vocês cozinharão a carne do animal e a comerão no local que o Senhor, o seu Deus, escolher. E, pela manhã, cada um de vocês voltará para a sua tenda.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 8, 'Durante seis dias comam pão sem fermento, e no sétimo dia façam uma assembléia em honra do Senhor, ao seu Deus; não façam trabalho algum.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 9, 'Contem sete semanas a partir da época em que vocês começarem a colheita do cereal.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 10, 'Celebrem então a festa das semanas ao Senhor, ao seu Deus, e tragam uma oferta voluntária conforme às bênçãos recebidas do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 11, 'E alegrem-se perante o Senhor, o seu Deus, no local que ele escolher para habitação do seu Nome, junto com os seus filhos e as suas filhas, os seus servos e as suas servas, os levitas que vivem na sua cidade, os estrangeiros, os órfãos e as viúvas que vivem com vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 12, 'Lembrem-se de que vocês foram escravos no Egito e obedeçam fielmente a estes decretos.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 13, 'Celebrem também a festa das cabanas durante sete dias, depois que ajuntarem o produto da eira e do lagar.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 14, 'Alegrem-se nessa festa com os seus filhos e as suas filhas, os seus servos e as suas servas, os levitas, os estrangeiros, os órfãos e as viúvas que vivem na sua cidade.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 15, 'Durante sete dias celebrem a festa, dedicada ao Senhor, ao seu Deus, no local que o Senhor escolher. Pois o Senhor, o seu Deus, os abençoará em toda a sua colheita e em todo o trabalho de suas mãos, e a sua alegria será completa.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 16, 'Três vezes por ano todos os seus homens se apresentarão ao Senhor, ao seu Deus, no local que ele escolher, por ocasião da festa dos pães sem fermento, da festa das semanas e da festa das cabanas. Nenhum deles deverá apresentar-se ao Senhor de mãos vazias:', 3, CURRENT_TIMESTAMP, false),
(5, 16, 17, 'cada um de vocês trará uma dádiva conforme as bênçãos recebidas do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 18, 'Nomeiem juízes e oficiais para cada uma de suas tribos em todas as cidades que o Senhor, o seu Deus, lhes dá, para que eles julguem o povo com justiça.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 19, 'Não pervertam a justiça nem mostrem parcialidade. Não aceitem suborno, pois o suborno cega até os sábios e prejudica a causa dos justos.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 20, 'Siga única e exclusivamente a justiça, para que tenham vida e tomem posse da terra que o Senhor, o seu Deus, lhes dá.', 3, CURRENT_TIMESTAMP, false),
(5, 16, 21, 'Não ergam nenhum poste sagrado além do altar que construírem em honra do Senhor, do seu Deus,', 3, CURRENT_TIMESTAMP, false),
(5, 16, 22, 'e não levantem nenhuma coluna sagrada, pois isto é detestável para o Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 1, 'Não sacrifiquem para o Senhor, o seu Deus, um boi ou uma ovelha que tenha qualquer defeito ou imperfeição; isso seria detestável para ele.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 2, 'Se um homem ou uma mulher que vive, numa das cidades que o Senhor lhes dá, for encontrado fazendo o que o Senhor, o seu Deus, reprova, violando a sua aliança,', 3, CURRENT_TIMESTAMP, false),
(5, 17, 3, 'e, desobedecendo ao meu mandamento, estiver adorando outros deuses, prostrando-se diante deles, ou diante do sol, ou diante da lua, ou diante das estrelas do céu,', 3, CURRENT_TIMESTAMP, false),
(5, 17, 4, 'e vocês ficarem sabendo disso, investiguem o caso a fundo. Se for verdade e ficar comprovado que se fez tal abominação em Israel,', 3, CURRENT_TIMESTAMP, false),
(5, 17, 5, 'levem o homem ou a mulher que tiver praticado esse pecado à porta da sua cidade e apedreje-o até morrer.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 6, 'Pelo depoimento de duas ou três testemunhas tal pessoa poderá ser morta, mas ninguém será morto pelo depoimento de uma única testemunha.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 7, 'As mãos das testemunhas serão as primeiras a proceder à sua execução, e depois as mãos de todo o povo. Eliminem o mal do meio de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 8, 'Se para os seus tribunais vierem casos difíceis demais de julgar, sejam crimes de sangue, litígios ou agressões, dirijam-se ao local escolhido pelo Senhor, o seu Deus,', 3, CURRENT_TIMESTAMP, false),
(5, 17, 9, 'e procurem os sacerdotes levitas e o juiz que estiver exercendo o cargo na ocasião. Apresentem-lhes o caso, e eles lhes darão o veredicto.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 10, 'Procedam de acordo com a decisão que eles proclamarem no local que o Senhor escolher. Tratem de fazer tudo o que eles ordenarem.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 11, 'Procedam de acordo com a sentença e as orientações que eles lhes derem. Não se desviem daquilo que eles lhes determinarem, nem para a direita, nem para a esquerda.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 12, 'Mas quem agir com rebeldia contra o juiz ou contra o sacerdote que ali estiver no serviço do Senhor, terá que ser morto. Eliminem o mal do meio de Israel.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 13, 'Assim, todo o povo temerá e não ousará mais agir com rebeldia.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 14, 'Se quando entrarem na terra que o Senhor, o seu Deus, lhes dá, tiverem tomado posse dela, nela tiverem se estabelecido, vocês disserem: "Queremos um rei que nos governe, como têm todas as nações vizinhas",', 3, CURRENT_TIMESTAMP, false),
(5, 17, 15, 'tenham o cuidado de nomear o rei que o Senhor, o seu Deus, escolher. Ele deve vir dentre os seus próprios irmãos israelitas. Não coloquem um estrangeiro como rei, alguém que não seja israelita.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 16, 'Esse rei, porém, não deverá adquirir muitos cavalos, nem fazer o povo voltar ao Egito para conseguir mais cavalos, pois o Senhor lhes disse: "Jamais voltem por este caminho".', 3, CURRENT_TIMESTAMP, false),
(5, 17, 17, 'Ele não deverá tomar para si muitas mulheres; se o fizer, desviará o seu coração. Também não deverá acumular muita prata e muito ouro.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 18, 'Quando subir ao trono do seu reino, mandará fazer num rolo, uma cópia da lei, que está aos cuidados dos sacerdotes levitas para o seu próprio uso.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 19, 'Trará sempre essa cópia consigo e terá que lê-la todos os dias da sua vida, para que aprenda a temer o Senhor, o seu Deus, e a cumprir fielmente todas as palavras desta lei, e todos estes decretos.', 3, CURRENT_TIMESTAMP, false),
(5, 17, 20, 'Isso fará que ele não se considere superior aos seus irmãos israelitas e a não se desvie da lei, nem para a direita, nem para a esquerda. Assim prolongará o seu reinado sobre Israel, bem como o dos seus descendentes.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 1, 'Os sacerdotes levitas e todo o restante da tribo de Levi, não terão posse nem herança em Israel. Viverão das ofertas sacrificadas para o Senhor, preparadas no fogo, pois esta é a sua herança.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 2, 'Não terão herança alguma entre os seus compatriotas; o Senhor é a sua herança, conforme lhes prometeu.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 3, 'Quando o povo sacrificar um novilho ou uma ovelha, os sacerdotes receberão a porção devida: o espádua, as queixadas e o estômago.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 4, 'Vocês terão que dar-lhes as primícias do trigo, do vinho e do azeite, e a primeira lã da tosquia das ovelhas,', 3, CURRENT_TIMESTAMP, false),
(5, 18, 5, 'pois, de todas as tribos, o Senhor, o seu Deus, escolheu os levitas e os seus descendentes para estarem na presença do Senhor, e para ministrarem sempre em seu nome.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 6, 'Se um levita que estiver morando em qualquer cidade de Israel, desejar ir ao local escolhido pelo Senhor,', 3, CURRENT_TIMESTAMP, false),
(5, 18, 7, 'poderá ministrar em nome do Senhor, do seu Deus, à semelhança de todos os outros levitas que ali servem na presença do Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 8, 'Ele receberá uma porção de alimento igual à dos outros levitas; além disso, ficará com o que receber com a venda dos bens da sua família.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 9, 'Quando entrarem na terra que o Senhor, o seu Deus, lhes dá, não procurem imitar as coisas repugnantes que as nações de lá praticam.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 10, 'Não permitam que se ache alguém entre vocês que queime em sacrifício o seu filho ou a sua filha; que pratique adivinhação, ou dedique-se à magia, ou faça presságios, ou pratique feitiçaria', 3, CURRENT_TIMESTAMP, false),
(5, 18, 11, 'ou faça encantamentos; que seja médium ou espírita ou que consulte os mortos.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 12, 'O Senhor têm repugnância por quem pratica essas coisas, e é por causa dessas abominações que o Senhor, o seu Deus, vai expulsar aquelas nações da presença de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 13, 'Permaneçam inculpáveis perante o Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 14, 'As nações que vocês vão expulsar dão ouvidos aos que praticam magia e adivinhação. Mas, a vocês, o Senhor, o seu Deus, não permitiu tais práticas.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 15, 'O Senhor, o seu Deus, levantará do meio de seus próprios irmãos um profeta como eu; ouçam-no.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 16, 'Pois foi isso que pediram ao Senhor, ao seu Deus, em Horebe, no dia em que se reuniram, quando disseram: "Não queremos ouvir a voz do Senhor, do nosso Deus, nem ver o seu grande fogo, se não morreremos! "', 3, CURRENT_TIMESTAMP, false),
(5, 18, 17, 'O Senhor me disse: "Eles têm razão!', 3, CURRENT_TIMESTAMP, false),
(5, 18, 18, 'Levantarei do meio dos seus irmãos um profeta como você; porei minhas palavras na sua boca, e ele lhes dirá tudo o que eu lhe ordenar.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 19, 'Se alguém não ouvir as minhas palavras, que o profeta falará em meu nome, eu mesmo lhe pedirei contas.', 3, CURRENT_TIMESTAMP, false),
(5, 18, 20, 'Mas o profeta que ousar falar em meu nome alguma coisa que não lhe ordenei, ou que falar em nome de outros deuses, terá que ser morto".', 3, CURRENT_TIMESTAMP, false),
(5, 18, 21, 'Mas vocês perguntem a si mesmos: "Como saberemos se uma mensagem não vem do Senhor? "', 3, CURRENT_TIMESTAMP, false),
(5, 18, 22, 'Se o que o profeta proclamar em nome do Senhor não acontecer nem se cumprir, essa mensagem não vem do Senhor. Aquele profeta falou com presunção. Não tenham medo dele.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 1, 'Quando o Senhor, o seu Deus, tiver destruído as nações cuja terra lhes dá, e quando vocês as expulsarem e ocuparem as cidades e as casas dessas nações,', 3, CURRENT_TIMESTAMP, false),
(5, 19, 2, 'separem três cidades de refúgio na parte central da terra que o Senhor, o seu Deus, está dando a vocês para que dela tomem posse.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 3, 'Dividam em três partes a terra que o Senhor, o seu Deus, lhe está dando como herança e façam nela acessos, para que aquele que matar alguém possa fugir para lá.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 4, 'Este é o caso em que um homem que matar outro poderá fugir para lá para salvar a vida: se matar o seu próximo sem intenção, sem que houvesse inimizade entre eles.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 5, 'Por exemplo, se um homem for com o seu amigo cortar lenha na floresta e, ao levantar o machado para derrubar uma árvore, o ferro escapar e atingir o seu amigo e matá-lo, ele poderá fugir para uma daquelas cidades para salvar a vida.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 6, 'Do contrário, o vingador da vítima poderia persegui-lo enfurecido e alcançá-lo, caso a distância fosse grande demais, e poderia matá-lo, muito embora este não merecesse morrer, pois não havia inimizade entre ele e o seu próximo.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 7, 'É por isso que lhe ordeno que separe três cidades.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 8, 'Se o Senhor, o seu Deus, aumentar o seu território, como prometeu sob juramento aos seus antepassados, e lhe der toda a terra que prometeu a eles,', 3, CURRENT_TIMESTAMP, false),
(5, 19, 9, 'separem então mais três cidades. Isso acontecerá se vocês obedecerem fielmente a toda esta lei que hoje lhes ordeno: amar o Senhor, o seu Deus, e sempre andar nos seus caminhos.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 10, 'Façam isso para que não se derrame sangue inocente na sua terra, a qual o Senhor, o seu Deus, lhes dá por herança, e para que não sejam culpados de derramamento de sangue.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 11, 'Mas, se alguém odiar o seu próximo, ficar à espreita dele, atacá-lo e matá-lo, e fugir para uma dessas cidades,', 3, CURRENT_TIMESTAMP, false),
(5, 19, 12, 'as autoridades da sua cidade mandarão buscá-lo nas cidade de refúgio, e o entregarão nas mãos do vingador da vítima, para que morra.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 13, 'Não tenham piedade dele. Eliminem de Israel a culpa pelo derramamento de sangue inocente, para que tudo lhes vá bem.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 14, 'Não mudem os marcos de divisa da propriedade do seu vizinho, que os seus colocaram na herança que receberão na terra que o Senhor, o seu Deus, lhes dá para que dela tomem posse.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 15, 'Uma só testemunha não é suficiente para condenar alguém de algum crime ou delito. Qualquer acusação precisa ser confirmada pelo depoimento de duas ou três testemunhas.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 16, 'Se uma testemunha falsa quiser acusar um homem de algum crime,', 3, CURRENT_TIMESTAMP, false),
(5, 19, 17, 'os dois envolvidos na questão deverão apresentar-se ao Senhor, diante dos sacerdotes e juízes que estiverem exercendo o cargo naquela ocasião.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 18, 'Os juízes investigarão o caso e, se ficar provado que a testemunha mentiu e deu falso testemunho contra o seu próximo,', 3, CURRENT_TIMESTAMP, false),
(5, 19, 19, 'dêem-lhe a punição que ele planejava para o seu irmão. Eliminem o mal do meio de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 20, 'O restante do povo saberá disso e terá medo, e nunca mais se fará uma coisa dessas entre vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 19, 21, 'Não tenham piedade. Exijam vida por vida, olho por olho, dente por dente, mão por mão, pé por pé.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 1, 'Quando vocês forem à guerra contra os seus inimigos e virem cavalos e carros, e um exército maior do que o seu, não tenham medo, pois o Senhor, o seu Deus, que os tirou do Egito, estará com vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 2, 'Quando chegar a hora da batalha, o sacerdote virá à frente e dirá ao exército:', 3, CURRENT_TIMESTAMP, false),
(5, 20, 3, '"Ouça, ó Israel. Hoje vocês vão lutar contra os inimigos. Não se desanimem nem tenham medo; não fiquem apavorados nem aterrorizados por causa deles,', 3, CURRENT_TIMESTAMP, false),
(5, 20, 4, 'pois o Senhor, o seu Deus, os acompanhará e lutará por vocês contra os inimigos, para lhes dar a vitória".', 3, CURRENT_TIMESTAMP, false),
(5, 20, 5, 'Os oficiais dirão ao exército: "Há alguém que construiu uma casa e ainda não a dedicou? Volte ele para sua casa, para que não morra na guerra e outro a dedique.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 6, 'Há alguém que plantou uma vinha e ainda não desfrutou dela? Volte ele para sua casa, para que não morra na guerra e outro desfrute da vinha.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 7, 'Há alguém comprometido para casar-se que ainda não recebeu sua mulher? Volte ele para sua casa, para que não morra na guerra e outro case-se com ela".', 3, CURRENT_TIMESTAMP, false),
(5, 20, 8, 'Por fim os oficiais acrescentarão: "Alguém está com medo e não tem coragem? Volte ele para sua casa, para que os seus irmãos israelitas também não fiquem desanimados".', 3, CURRENT_TIMESTAMP, false),
(5, 20, 9, 'Quando os oficiais terminarem de falar ao exército, designarão chefes para comandar as tropas.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 10, 'Quando vocês avançarem para atacar uma cidade, enviem-lhe primeiro uma proposta de paz.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 11, 'Se os seus habitantes aceitarem, e abrirem suas portas, serão seus escravos e se sujeitarão a trabalhos forçados.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 12, 'Mas se eles recusarem a paz e entrarem em guerra contra vocês, sitiem a cidade.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 13, 'Quando o Senhor, o seu Deus, entregá-la em suas mãos, matem ao fio da espada todos os homens que nela houver.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 14, 'Mas as mulheres, as crianças, os rebanhos e tudo o que acharem na cidade, será de vocês; vocês poderão ficar com os despojos dos seus inimigos dados pelo Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 15, 'É assim que vocês tratarão todas as cidades distantes que não pertencem às nações vizinhas de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 16, 'Contudo, nas cidades das nações que o Senhor, o seu Deus, lhes dá por herança, não deixem vivo nenhuma alma.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 17, 'Conforme a ordem do Senhor, o seu Deus, destruam totalmente os hititas, os amorreus, os cananeus, os ferezeus, os heveus e os jebuseus.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 18, 'Se não, eles os ensinarão a praticar todas as coisas repugnantes que eles fazem quando adoram os seus deuses, e vocês pecarão contra o Senhor, contra o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 20, 19, 'Quando sitiarem uma cidade por um longo período, lutando contra ela para conquistá-la, não destruam as árvores dessa cidade a golpes de machado, pois vocês poderão comer as suas frutas. Não as derrubem. Por acaso as árvores são gente, para que vocês as sitiem?', 3, CURRENT_TIMESTAMP, false),
(5, 20, 20, 'Entretanto, poderão derrubar as árvores que vocês sabem que não são frutíferas, para utilizá-las em obras que ajudem o cerco, até que caia a cidade que está em guerra contra vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 1, 'Se alguém for encontrado morto no campo, na terra que o Senhor, o seu Deus, lhes dá para dela tomarem posse, sem que se saiba quem o matou,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 2, 'as autoridades e os juízes sairão e medirão a distância do corpo até as cidades vizinhas.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 3, 'Então as autoridades da cidade mais próxima do corpo apanharão uma novilha que nunca foi usada no trabalho e sobre a qual nunca foi posto jugo', 3, CURRENT_TIMESTAMP, false),
(5, 21, 4, 'e a levarão a um vale de terras nunca aradas nem semeadas e onde haja um ribeiro de águas perenes. Vocês quebrarão o pescoço da novilha.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 5, 'Depois, os sacerdotes, descendentes de Levi, se aproximarão, pois o Senhor, o seu Deus, os escolheu para ministrarem e para pronunciarem bênçãos em nome do Senhor e resolverem todos os casos de litígio e de violência.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 6, 'Então todas as autoridades da cidade mais próxima do corpo lavarão as mãos sobre a novilha cujo pescoço foi quebrado no vale,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 7, 'e declararão: "As nossas mãos não derramaram este sangue, nem os nossos olhos viram quem fez isso.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 8, 'Aceita, Senhor, esta propiciação em favor do teu povo Israel, a quem resgataste, e não consideres o teu povo culpado do sangue de um inocente". Assim a culpa do derramamento de sangue será propiciada.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 9, 'Desse modo vocês eliminarão de vocês mesmos a culpa pelo derramamento de sangue inocente, pois fizeram o que o Senhor aprova.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 10, 'Quando vocês guerrearem contra os seus inimigos e o Senhor, o seu Deus, os entregar em suas mãos e vocês fizerem prisioneiros,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 11, 'um de vocês poderá ver entre eles uma mulher muito bonita, agradar-se dela e tomá-la como esposa.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 12, 'Leve-a para casa; ela rapará a cabeça, cortará as unhas', 3, CURRENT_TIMESTAMP, false),
(5, 21, 13, 'e se desfará das roupas que estava usando quando foi capturada. Ficará em casa e pranteará seu pai e sua mãe um mês inteiro. Depois você poderá chegar-se a ela e ser o seu marido, e ela será sua mulher.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 14, 'Se você já não se agradar dela, deixe-a ir para onde quiser, mas não poderá vendê-la nem tratá-la como escrava, pois você a desonrou.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 15, 'Se um homem tiver duas mulheres e preferir uma delas, e ambas lhe derem filhos, e o filho mais velho for filho da mulher que ele não prefere,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 16, 'quando der a herança de sua propriedade aos filhos, não poderá dar os direitos do filho mais velho ao filho da mulher preferida, se o filho da mulher que ele não prefere for de fato o mais velho.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 17, 'Ele terá que reconhecer o filho da mulher que ele não prefere como filho mais velho, dando-lhe porção dupla de tudo o que possui. Aquele filho é o primeiro sinal da força de seu pai e o direito do filho mais velho lhe pertence.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 18, 'Se um homem tiver um filho obstinado e rebelde que não obedece a seu pai nem à sua mãe e não os escuta quando o disciplinam,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 19, 'o pai e a mãe o levarão aos líderes da sua comunidade, à porta da cidade,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 20, 'e dirão aos líderes: "Este nosso filho é obstinado e rebelde. Não nos obedece! É devasso e vive bêbado".', 3, CURRENT_TIMESTAMP, false),
(5, 21, 21, 'Então todos os homens da cidade o apedrejarão até à morte. Eliminem o mal do meio de vocês. Todo o Israel saberá disso e temerá.', 3, CURRENT_TIMESTAMP, false),
(5, 21, 22, 'Se um homem culpado de um crime que mereça a morte for morto e pendurado num madeiro,', 3, CURRENT_TIMESTAMP, false),
(5, 21, 23, 'não deixem o corpo no madeiro durante a noite. Enterrem-no naquele mesmo dia, porque qualquer que for pendurado num madeiro está debaixo da maldição de Deus. Não contaminem a terra que o Senhor, o seu Deus, lhes dá por herança.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 1, 'Se o boi ou a ovelha de um israelita se extraviar e você o vir, não ignore o fato, mas faça questão de levar o animal de volta ao dono.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 2, 'Se este não morar perto de você ou se você não conhecê-lo, leve o animal para casa e fique com ele até que seu compatriota venha procurá-lo e você possa devolvê-lo.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 3, 'Faça o mesmo com o jumento, com a capa e com qualquer coisa perdida que encontrar. Não ignore o fato.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 4, 'Se você vir o jumento ou o boi de um israelita caído no caminho, não o ignore. Ajude-o a pôr o animal em pé.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 5, 'A mulher não usará roupas de homem, e o homem não usará roupas de mulher, pois o Senhor, o seu Deus, tem aversão por todo aquele que assim procede.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 6, 'Se você passar por um ninho de passarinho junto ao caminho, seja numa árvore ou no chão, e a mãe estiver sobre os filhotes ou sobre os ovos, não apanhe a mãe com os filhotes.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 7, 'Você poderá apanhar os filhotes, mas deixe a mãe solta, para que tudo vá bem com você e você tenha vida longa.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 8, 'Quando algum de vocês construir uma casa nova, faça um parapeito em torno do terraço, para que não traga sobre a sua casa a culpa pelo derramamento de sangue inocente, caso alguém caia do terraço.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 9, 'Não plantem dois tipos de semente em sua vinha; se o fizerem, tanto a semente que plantarem como o fruto da vinha estarão contaminados.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 10, 'Não arem a terra usando um boi e um jumento sob o mesmo jugo.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 11, 'Não usem roupas de lã e de linho misturados no mesmo tecido.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 12, 'Façam borlas nas quatro pontas do manto que vocês usam para cobrir-se.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 13, 'Se um homem casar-se e, depois de deitar-se com a mulher, rejeitá-la', 3, CURRENT_TIMESTAMP, false),
(5, 22, 14, 'e falar mal dela e difamá-la, dizendo: "Casei-me com esta mulher, mas quando me cheguei a ela, descobri que não era mais virgem",', 3, CURRENT_TIMESTAMP, false),
(5, 22, 15, 'o pai e a mãe da moça trarão aos líderes da cidade, junto à porta, a prova da sua virgindade.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 16, 'Então o pai da moça dirá aos líderes: "Dei a minha filha em casamento a este homem, mas ele a rejeita.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 17, 'Ele também a difamou e disse: ‘Descobri que a sua filha não era virgem’. Mas aqui está a prova da virgindade da minha filha". Então os pais dela apresentarão a prova aos líderes da cidade,', 3, CURRENT_TIMESTAMP, false),
(5, 22, 18, 'e eles castigarão o homem.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 19, 'Aplicarão a ele a multa de cem peças de prata, que serão dados ao pai da moça, pois esse homem prejudicou a reputação de uma virgem israelita. E ele não poderá divorciar-se dela enquanto viver.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 20, 'Se, contudo, a acusação for verdadeira e não se encontrar prova de virgindade da moça,', 3, CURRENT_TIMESTAMP, false),
(5, 22, 21, 'ela será levada à porta da casa do seu pai e ali os homens da sua cidade a apedrejarão até à morte. Ela cometeu um ato vergonhoso em Israel, prostituindo-se enquanto estava na casa de seu pai. Eliminem o mal do meio de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 22, 'Se um homem for surpreendido deitado com a mulher de outro, os dois terão que morrer, o homem e a mulher com quem se deitou. Eliminem o mal do meio de Israel.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 23, 'Se numa cidade um homem se encontrar com uma jovem prometida em casamento e se deitar com ela,', 3, CURRENT_TIMESTAMP, false),
(5, 22, 24, 'levem os dois à porta daquela cidade e apedrejem-nos até à morte: a moça porque estava na cidade e não gritou por socorro, e o homem porque desonrou a mulher doutro homem. Eliminem o mal do meio de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 25, 'Se, contudo, um homem encontrar no campo uma jovem prometida em casamento e a forçar, somente o homem morrerá.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 26, 'Não façam nada, pois ela não cometeu pecado algum que mereça a morte. Este caso é semelhante ao daquele que ataca e mata o seu próximo,', 3, CURRENT_TIMESTAMP, false),
(5, 22, 27, 'pois o homem encontrou a moça virgem no campo, e, ainda que a jovem prometida em casamento gritasse, ninguém poderia socorrê-la.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 28, 'Se um homem se encontrar com uma moça sem compromisso de casamento e a violentar, e eles forem descobertos,', 3, CURRENT_TIMESTAMP, false),
(5, 22, 29, 'ele pagará ao pai da moça cinqüenta peças de prata. Terá que casar-se com a moça, pois a violentou. Jamais poderá divorciar-se dela.', 3, CURRENT_TIMESTAMP, false),
(5, 22, 30, 'Nenhum homem poderá tomar por mulher a mulher do seu pai, pois isso desonraria a cama de seu pai.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 1, 'Qualquer que tenha os testículos esmagados ou tenha amputado o membro viril, não poderá entrar na assembléia do Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 2, 'Quem nasceu de união ilícita não poderá entrar na assembléia do Senhor, como também os seus descendentes, até a décima geração.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 3, 'Nenhum amonita ou moabita ou qualquer dos seus descendentes, até a décima geração, poderá entrar na assembléia do Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 4, 'Pois eles não vieram encontrar-se com vocês com pão e água no caminho, quando vocês saíram do Egito; além disso convocaram Balaão, filho de Beor, para vir de Petor, na Mesopotâmia, para pronunciar maldição contra vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 5, 'No entanto, o Senhor, o seu Deus, não atendeu Balaão, e transformou a maldição em bênção para vocês, pois o Senhor, o seu Deus, os ama.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 6, 'Não façam um tratado de amizade com eles enquanto vocês viverem.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 7, 'Não rejeitem o edomita, pois ele é seu irmão. Também não rejeitem o egípcio, pois vocês viveram como estrangeiros na terra deles.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 8, 'A terceira geração dos filhos deles poderá entrar na assembléia do Senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 9, 'Quando estiverem acampados, em guerra contra os seus inimigos, mantenham-se afastados de todas as coisas impuras.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 10, 'Se um de seus homens estiver impuro devido à polução noturna, ele terá que sair do acampamento.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 11, 'Mas ao entardecer ele se lavará, e ao pôr-do-sol poderá voltar ao acampamento.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 12, 'Determinem um local fora do acampamento onde se possa evacuar.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 13, 'Como parte do seu equipamento, tenham algo com que cavar, e quando evacuarem, façam um buraco e cubram as fezes.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 14, 'Pois o Senhor, o seu Deus, anda pelo seu acampamento para protegê-los e entregar-lhes os seus inimigos. O acampamento terá que ser santo, para que ele não veja no meio de vocês alguma coisa desagradável e se afaste de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 15, 'Se um escravo refugiar-se entre vocês, não o entreguem nas mãos do seu senhor.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 16, 'Deixem-no viver no meio de vocês pelo tempo que ele desejar e em qualquer cidade que ele escolher. Não o oprimam.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 17, 'Nenhum israelita, homem ou mulher, poderá tornar-se prostituto cultual.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 18, 'Não tragam ao santuário do Senhor, do seu Deus, os ganhos de uma prostituta ou de um prostituto, a fim de pagar algum voto, pois o Senhor, o seu Deus, por ambos têm repugnância.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 19, 'Não cobrem juros de um israelita, por dinheiro, alimento, ou qualquer outra coisa que possa render juros.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 20, 'Vocês poderão cobrar juros do estrangeiro, mas não do seu irmão israelita, para que o Senhor, o seu Deus, os abençoe em tudo o que vocês fizerem na terra em que estão entrando para dela tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 21, 'Se um de vocês fizer um voto ao Senhor, ao seu Deus, não demore a cumpri-lo, pois o Senhor, o seu Deus, certamente lhe pedirá contas, e você será culpado de pecado se não o cumprir.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 22, 'Mas se você não fizer o voto, de nada será culpado.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 23, 'Faça tudo para cumprir o que os seus lábios prometeram, pois com a sua própria boca você fez, espontaneamente, o seu voto ao Senhor, ao seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 24, 'Se vocês entrarem na vinha do seu próximo, poderão comer as uvas que desejarem, mas nada poderão levar em sua cesta.', 3, CURRENT_TIMESTAMP, false),
(5, 23, 25, 'Se entrarem na plantação de trigo do seu próximo, poderão apanhar espigas com as mãos, mas nunca usem foice para ceifar o trigo do seu próximo.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 1, 'Se um homem casar-se com uma mulher e depois não a quiser mais por encontrar nela algo que ele reprova, dará certidão de divórcio à mulher e a mandará embora.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 2, 'Se, depois de sair da casa, ela se tornar mulher de outro homem,', 3, CURRENT_TIMESTAMP, false),
(5, 24, 3, 'e o seu segundo marido não gostar mais dela, lhe dará certidão de divórcio, e mandará embora a mulher. Ou também, se ele morrer,', 3, CURRENT_TIMESTAMP, false),
(5, 24, 4, 'o primeiro marido, que se divorciou dela, não poderá casar-se com ela de novo, visto que ela foi contaminada. Seria detestável para o Senhor. Não tragam pecado sobre a terra que o Senhor, o seu Deus, lhes dá por herança.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 5, 'Se um homem tiver se casado recentemente, não será enviado à guerra, nem assumirá nenhum compromisso público. Durante um ano estará livre para ficar em casa e fazer feliz à mulher com quem se casou.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 6, 'Não tomem as duas pedras de moinho, nem mesmo apenas a pedra de cima, como garantia de uma dívida, pois isso seria tomar como garantia o meio de subsistência do devedor.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 7, 'Se um homem for pego seqüestrando um dos seus irmãos israelitas, tratando-o como escravo ou vendendo-o, o seqüestrador terá que morrer. Eliminem o mal do meio de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 8, 'Nos casos de doenças de lepra, tenham todo o cuidado de seguir exatamente as instruções dos sacerdotes levitas. Sigam cuidadosamente o que eu ordenei a eles.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 9, 'Lembrem-se do que o Senhor, o seu Deus, fez com Miriã no caminho, depois que vocês saíram do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 10, 'Quando um de vocês fizer um empréstimo de qualquer tipo ao seu próximo, não entre na casa dele para apanhar o que ele lhe oferecer como penhor.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 11, 'Fique do lado de fora e deixe que o homem, a quem você está fazendo o empréstimo, traga a você o penhor.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 12, 'Se o homem for pobre, não vá dormir tendo com você o penhor.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 13, 'Devolva-lhe o manto ao pôr-do-sol, para que ele possa usá-lo para dormir, e lhe seja grato. Isso será considerado um ato de justiça pelo Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 14, 'Não se aproveitem do pobre e necessitado, seja ele um irmão israelita ou um estrangeiro que viva numa das suas cidades.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 15, 'Paguem-lhe o seu salário diariamente, antes do pôr-do-sol, pois ele é necessitado e depende disso. Se não, ele poderá clamar ao Senhor contra você, e você será culpado de pecado.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 16, 'Os pais não serão mortos em lugar dos filhos, nem os filhos em lugar dos pais; cada um morrerá pelo seu próprio pecado.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 17, 'Não neguem justiça ao estrangeiro e ao órfão, nem tomem como penhor o manto de uma viúva.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 18, 'Lembrem-se de que vocês foram escravos no Egito e de que o Senhor, o seu Deus, os libertou; por isso lhes ordeno que façam tudo isso.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 19, 'Quando vocês estiverem fazendo a colheita de sua lavoura e deixarem um feixe de trigo para trás, não voltem para apanhá-lo. Deixem-no para o estrangeiro, para o órfão e para a viúva, para que o Senhor, o seu Deus, os abençoe em todo o trabalho das suas mãos.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 20, 'Quando sacudirem as azeitonas das suas oliveiras, não voltem para colher o que ficar nos ramos. Deixem o que sobrar para o estrangeiro, para o órfão e para a viúva.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 21, 'E quando colherem as uvas da sua vinha, não passem de novo por ela. Deixem o que sobrar para o estrangeiro, para o órfão e para a viúva.', 3, CURRENT_TIMESTAMP, false),
(5, 24, 22, 'Lembrem-se de que vocês foram escravos no Egito; por isso lhes ordeno que façam tudo isso.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 1, 'Quando dois homens se envolverem numa briga, terão que levar a causa ao tribunal, e os juízes decidirão a questão, absolvendo o inocente e condenando o culpado.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 2, 'Se o culpado merecer açoitamento, o juiz ordenará que ele se deite e seja açoitado em sua presença com o número de açoites que o seu crime merecer,', 3, CURRENT_TIMESTAMP, false),
(5, 25, 3, 'desde que nunca ultrapasse quarenta açoites. Açoitá-lo além disso seria humilhar publicamente um israelita.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 4, 'Não amordacem o boi enquanto está debulhando o cereal.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 5, 'Se dois irmãos morarem juntos, e um deles morrer sem deixar filhos, a sua viúva não se casará com alguém de fora da família. O irmão do marido se casará com ela e cumprirá com ela o dever de cunhado.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 6, 'O primeiro filho que ela tiver levará o nome do irmão falecido, para que o seu nome não seja apagado de Israel.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 7, 'Se, todavia, ele não quiser casar-se com a mulher do seu irmão, ela irá aos líderes do lugar, à porta da cidade, e dirá: "O irmão do meu marido está se recusando a dar continuidade ao nome do seu irmão em Israel. Ele não quer cumprir para comigo o dever de cunhado".', 3, CURRENT_TIMESTAMP, false),
(5, 25, 8, 'Os líderes da cidade o convocarão e conversarão com ele. Se ele insistir em dizer: "Não quero me casar com ela",', 3, CURRENT_TIMESTAMP, false),
(5, 25, 9, 'a viúva do seu irmão se aproximará dele, na presença dos líderes, tirará uma das sandálias dele, cuspirá no seu rosto e dirá: "É isso que se faz com o homem que não perpetua a descendência do seu irmão".', 3, CURRENT_TIMESTAMP, false),
(5, 25, 10, 'E a descendência daquele homem será conhecida em Israel como a família do descalçado.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 11, 'Se dois homens estiverem brigando, e a mulher de um deles vier para livrar o marido daquele que o ataca e pegá-lo pelos órgãos genitais,', 3, CURRENT_TIMESTAMP, false),
(5, 25, 12, 'cortem a mão dela. Não tenham piedade.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 13, 'Não tenham na bolsa dois padrões para o mesmo peso, um maior e outro menor.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 14, 'Não tenham em casa dois padrões para a mesma medida, um maior e outro menor.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 15, 'Tenham pesos e medidas exatos e honestos, para que vocês vivam muito tempo na terra que o Senhor, o seu Deus, lhes dá.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 16, 'Pois o seu Deus detesta quem faz essas coisas, quem negocia desonestamente.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 17, 'Lembrem-se do que os amalequitas lhes fizeram no caminho, quando vocês saíram do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 18, 'Quando vocês estavam cansados e exaustos, eles se encontraram com vocês no caminho e eliminaram todos os que ficaram para trás; não tiveram temor de Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 25, 19, 'Quando o Senhor, o seu Deus, der a vocês o descanso de todos os inimigos ao seu redor na terra que ele lhes dá para dela tomar posse como herança, vocês farão que os amalequitas sejam esquecidos debaixo do céu. Não se esqueçam!', 3, CURRENT_TIMESTAMP, false),
(5, 26, 1, 'Quando vocês tiverem entrado na terra que o Senhor, o seu Deus, lhes dá por herança e dela tiverem tomado posse e lá estiverem estabelecidos,', 3, CURRENT_TIMESTAMP, false),
(5, 26, 2, 'apanhem alguns dos primeiros frutos de tudo o que produzirem na terra que o Senhor, o seu Deus, lhes dá e ponha tudo numa cesta. Depois vocês deverão ir ao local que o Senhor, o seu Deus, escolher para habitação do seu Nome', 3, CURRENT_TIMESTAMP, false),
(5, 26, 3, 'e dizer ao sacerdote que estiver exercendo o cargo naquela ocasião: "Declaro hoje ao Senhor, ao seu Deus, que vim para a terra que o Senhor jurou aos nossos antepassados que nos daria".', 3, CURRENT_TIMESTAMP, false),
(5, 26, 4, 'O sacerdote apanhará a cesta das suas mãos e a colocará em frente do altar do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 5, 'Então vocês declararão perante o Senhor, o seu Deus: "O meu pai era um arameu errante. Ele desceu ao Egito com pouca gente e ali viveu e se tornou uma grande nação, poderosa e numerosa.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 6, 'Mas os egípcios nos maltrataram e nos oprimiram, sujeitando-nos a trabalhos forçados.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 7, 'Então clamamos ao Senhor, ao Deus dos nossos antepassados, e o Senhor ouviu a nossa voz e viu o nosso sofrimento, a nossa fadiga e a opressão que sofríamos.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 8, 'Por isso o Senhor nos tirou do Egito com mão poderosa e braço forte, com feitos temíveis e com sinais e maravilhas.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 9, 'Ele nos trouxe a este lugar e nos deu esta terra, terra onde manam leite e mel.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 10, 'E agora trago os primeiros frutos do solo que tu, ó Senhor, me deste". Ponham a cesta perante o Senhor, o seu Deus, e curvem-se perante ele.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 11, 'Vocês e os levitas e os estrangeiros que estiverem no meio de vocês se alegrarão com todas as coisas boas que o Senhor, o seu Deus, dá a vocês e às suas famílias.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 12, 'Quando tiverem separado o dízimo de tudo quanto produziram no terceiro ano, o ano do dízimo, entreguem-no ao levita, ao estrangeiro, ao órfão e à viúva, para que possam comer até saciar-se nas cidades de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 13, 'Depois digam ao Senhor, ao seu Deus: "Retirei da minha casa a porção sagrada e dei-a ao levita, ao estrangeiro, ao órfão e à viúva, de acordo com tudo o que ordenaste. Não me afastei dos teus mandamentos nem esqueci nenhum deles.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 14, 'Não comi nada da porção sagrada enquanto estive de luto, nada retirei dela enquanto estive impuro, e dela não ofereci nada aos mortos. Obedeci ao Senhor, ao meu Deus; fiz tudo o que me ordenaste.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 15, 'Olha dos céus, da tua santa habitação, e abençoa Israel, o teu povo, e a terra que nos deste, conforme prometeste sob juramento aos nossos antepassados, terra onde manam leite e mel".', 3, CURRENT_TIMESTAMP, false),
(5, 26, 16, 'O Senhor, o seu Deus, lhes ordena hoje que sigam estes decretos e ordenanças; obedeçam-lhes atentamente, de todo o seu coração e de toda a sua alma.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 17, 'Hoje vocês declararam que o Senhor é o seu Deus e que vocês andarão nos seus caminhos, que guardarão os seus decretos, os seus mandamentos e as suas ordenanças, e que vocês lhe obedecerão.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 18, 'E hoje o Senhor declarou que vocês são o seu povo, o seu tesouro pessoal, conforme ele prometeu, e que vocês terão que guardar todos os seus mandamentos.', 3, CURRENT_TIMESTAMP, false),
(5, 26, 19, 'Ele declarou que lhes dará uma posição de glória, fama e honra muito acima de todas as nações que ele fez, e que vocês serão um povo santo para o Senhor, para o seu Deus, conforme ele prometeu.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 1, 'Moisés e as autoridades de Israel ordenaram ao povo: "Obedeçam à toda esta lei que hoje lhes dou.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 2, 'Quando vocês atravessarem o Jordão, e entrarem na terra que o Senhor, o seu Deus, lhes dá, levantem algumas pedras grandes e pintem-nas com cal.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 3, 'Escrevam nelas todas as palavras desta lei, assim que tiverem atravessado para entrar na terra que o Senhor, o seu Deus, lhes dá, terra onde manam leite e mel, como o Senhor, o Deus dos seus antepassados, lhes prometeu.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 4, 'E, quando tiverem atravessado o Jordão, levantem essas pedras no monte Ebal, como hoje lhes ordeno, e pintem-nas com cal.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 5, 'Construam ali um altar ao Senhor, ao seu Deus, um altar de pedras. Não utilizem ferramenta de ferro nas pedras.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 6, 'Façam o altar do Senhor, do seu Deus, com pedras brutas, e sobre ele ofereçam holocaustos ao Senhor, ao seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 7, 'Ofereçam também sacrifícios de comunhão, e comam e alegrem-se na presença do Senhor, do seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 8, 'E nessas pedras que levantarem, vocês escreverão com bastante clareza todas as palavras desta lei".', 3, CURRENT_TIMESTAMP, false),
(5, 27, 9, 'Então Moisés e os sacerdotes levitas disseram a todo Israel: "Faça silêncio e escute, ó Israel! Agora você se tornou o povo do Senhor, o seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 10, 'Obedeça ao Senhor, ao seu Deus, e siga os seus mandamentos e decretos que hoje lhe dou".', 3, CURRENT_TIMESTAMP, false),
(5, 27, 11, 'No mesmo dia Moisés ordenou ao povo:', 3, CURRENT_TIMESTAMP, false),
(5, 27, 12, 'Quando vocês tiverem atravessado o Jordão, as tribos que estarão no monte Gerizim para abençoar o povo serão: Simeão, Levi, Judá, Issacar, José e Benjamim.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 13, 'E as tribos que estarão no monte Ebal para declararem maldições serão: Rúben, Gade, Aser, Zebulom, Dã e Naftali.', 3, CURRENT_TIMESTAMP, false),
(5, 27, 14, 'E os levitas recitarão a todo o povo de Israel em alta voz:', 3, CURRENT_TIMESTAMP, false),
(5, 27, 15, '"Maldito quem esculpir uma imagem ou fizer um ídolo fundido, obra de artesãos, detestável ao Senhor, e levantá-lo secretamente". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 16, '"Maldito quem desonrar o seu pai ou a sua mãe". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 17, '"Maldito quem mudar o marco de divisa da propriedade do seu próximo". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 18, '"Maldito quem fizer o cego errar o caminho". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 19, '"Maldito quem negar justiça ao estrangeiro, ao órfão ou à viúva". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 20, '"Maldito quem se deitar com a mulher do seu pai, desonrando a cama do seu pai". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 21, '"Maldito quem tiver relações sexuais com algum animal". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 22, '"Maldito quem se deitar com a sua irmã, filha do seu pai ou da sua mãe". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 23, '"Maldito quem se deitar com a sua sogra". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 24, '"Maldito quem matar secretamente o seu próximo". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 25, '"Maldito quem aceitar pagamento para matar um inocente". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 27, 26, '"Maldito quem não puser em prática as palavras desta lei". Todo o povo dirá: "Amém! "', 3, CURRENT_TIMESTAMP, false),
(5, 28, 1, 'Se vocês obedecerem fielmente ao Senhor, ao seu Deus, e seguirem cuidadosamente todos os seus mandamentos que hoje lhes dou, o Senhor, o seu Deus, os colocará muito acima de todas as nações da terra.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 2, 'Todas estas bênçãos virão sobre vocês e os acompanharão, se vocês obedecerem ao Senhor, ao seu Deus:', 3, CURRENT_TIMESTAMP, false),
(5, 28, 3, 'Vocês serão abençoados na cidade e serão abençoados no campo.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 4, 'Os filhos do seu ventre serão abençoados, como também as colheitas da sua terra e os bezerros e os cordeiros dos seus rebanhos.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 5, 'A sua cesta e a sua amassadeira serão abençoadas.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 6, 'Vocês serão abençoados em tudo o que fizerem.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 7, 'O Senhor concederá que sejam derrotados diante de vocês os inimigos que os atacarem. Virão a vocês por um caminho, e por sete fugirão.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 8, 'O Senhor enviará bênçãos aos seus celeiros e a tudo o que as suas mãos fizerem. O Senhor, o seu Deus, os abençoará na terra que lhes dá.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 9, 'O Senhor fará de vocês o seu povo santo, conforme prometeu sob juramento, se guardarem os mandamentos do Senhor, do seu Deus, e andarem nos caminhos dele.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 10, 'Então todos os povos da terra verão que vocês são chamados pelo nome do Senhor e terão medo de vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 11, 'O Senhor lhes concederá grande prosperidade, no fruto do seu ventre, nas crias dos seus animais e nas colheitas da sua terra, nesta terra que ele jurou aos seus antepassados que daria a vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 12, 'O Senhor abrirá o céu, o depósito do seu tesouro, para enviar chuva à sua terra no devido tempo e para abençoar todo o trabalho das suas mãos. Vocês emprestarão a muitas nações, e de nenhuma tomarão emprestado.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 13, 'O Senhor fará de vocês a cabeça das nações, e não a cauda. Se obedecerem aos mandamentos do Senhor, do seu Deus, que hoje lhes dou e os seguirem cuidadosamente, vocês estarão sempre por cima, nunca por baixo.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 14, 'Não se desviem, nem para a direita nem para a esquerda, de qualquer dos mandamentos que hoje lhes dou, para seguir outros deuses e prestar-lhes culto.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 15, 'Entretanto, se vocês não obedecerem ao Senhor, ao seu Deus, e não seguirem cuidadosamente todos os seus mandamentos e decretos que hoje lhes dou, todas estas maldições cairão sobre vocês e os atingirão:', 3, CURRENT_TIMESTAMP, false),
(5, 28, 16, 'Vocês serão amaldiçoados na cidade e serão amaldiçoados no campo.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 17, 'A sua cesta e a sua amassadeira serão amaldiçoadas.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 18, 'Os filhos do seu ventre serão amaldiçoados, como também as colheitas da sua terra, os bezerros e os cordeiros dos seus rebanhos.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 19, 'Vocês serão amaldiçoados em tudo o que fizerem.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 20, 'O Senhor enviará sobre vocês maldições, confusão e repreensão em tudo o que fizerem, até que vocês sejam destruídos e sofram repentina ruína pelo mal que praticaram ao se esquecerem dele.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 21, 'O Senhor os encherá de doenças até bani-los da terra em que vocês estão entrando para dela tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 22, 'O Senhor os ferirá com doenças devastadoras, febre e inflamação, com calor abrasador e seca, com ferrugem e mofo, que os infestarão até que morram.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 23, 'O céu sobre a sua cabeça será como bronze; o chão debaixo de vocês, como ferro.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 24, 'Na sua terra o Senhor transformará a chuva em cinza e pó, que descerão do céu até que vocês sejam destruídos.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 25, 'O Senhor fará que vocês sejam derrotados pelos inimigos. Vocês irão a eles por um caminho, e por sete fugirão, e vocês se tornarão motivo de horror para todos os reinos da terra.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 26, 'Os seus cadáveres servirão de alimento para todas as aves do céu e para os animais da terra e não haverá quem os espante.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 27, 'O Senhor os castigará com as úlceras do Egito e com tumores, feridas purulentas e sarna, males dos quais vocês não poderão curar-se.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 28, 'O Senhor os afligirá com loucura, cegueira e confusão mental.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 29, 'Ao meio-dia vocês ficarão tateando às voltas, como um cego na escuridão. Vocês não serão bem sucedidos em nada que fizerem; dia após dia serão oprimidos e roubados, sem que ninguém os salve.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 30, 'Você ficará noivo de uma mulher, mas outro homem a possuirá. Construirá uma casa, mas não morará nela. Plantará uma vinha, mas não provará dos seus frutos.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 31, 'O seu boi será abatido diante dos seus olhos, mas você não comerá da sua carne. O seu jumento lhe será tirado à força e não lhe será devolvido. As suas ovelhas serão dadas aos inimigos, e ninguém as livrará.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 32, 'Os seus filhos e as suas filhas serão entregues a outra nação e os seus olhos se consumirão à espera deles, dia após dia, sem que você possa erguer uma só mão para trazê-los de volta.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 33, 'Um povo que vocês não conhecem comerá aquilo que a terra e o seu trabalho produzirem, e vocês sofrerão opressão cruel todos os seus dias.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 34, 'Aquilo que os seus olhos virem os levarão à loucura.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 35, 'O Senhor afligirá os seus joelhos e as suas pernas com feridas dolorosas e incuráveis, e que se espalharão sobre vocês desde a sola do pé até o alto da cabeça.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 36, 'O Senhor os levará, e também o rei que os governar, a uma nação que você e seus antepassados nunca conheceram. Lá vocês adorarão outros deuses, deuses de madeira e de pedra.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 37, 'Vocês serão motivo de horror e motivo de zombaria e de riso para todas as nações para onde o Senhor o levar.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 38, 'Vocês semearão muito em sua terra, mas colherão bem pouco, porque gafanhotos devorarão quase tudo.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 39, 'Plantarão vinhas e as cultivarão, mas não beberão o vinho nem colherão as uvas, porque os vermes as comerão.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 40, 'Vocês terão oliveiras em todo o país, mas vocês mesmos não utilizarão o azeite, porque as azeitonas cairão.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 41, 'Os seus filhos e filhas não ficarão com vocês, porque serão levados para o cativeiro.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 42, 'Enxames de gafanhotos se apoderarão de todas as suas árvores e das plantações da sua terra.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 43, 'Os estrangeiros que vivem no meio de vocês progredirão cada vez mais, e cada vez mais vocês regredirão.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 44, 'Eles lhes emprestarão dinheiro, mas vocês não emprestarão a eles. Eles serão a cabeça, e vocês serão a cauda.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 45, 'Todas essas maldições cairão sobre vocês. Elas o perseguirão e o alcançarão até que sejam destruídos, porque não obedeceram ao Senhor, ao seu Deus, nem guardaram os mandamentos e decretos que ele lhes deu.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 46, 'Essas maldições serão um sinal e um prodígio para vocês e para os seus descendentes para sempre.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 47, 'Uma vez que vocês não serviram com júbilo e alegria ao Senhor, ao seu Deus, na época da prosperidade,', 3, CURRENT_TIMESTAMP, false),
(5, 28, 48, 'então, em meio à fome e à sede, em nudez e pobreza extrema, vocês servirão aos inimigos que o Senhor enviará contra vocês. Ele porá um jugo de ferro sobre o seu pescoço, até que os tenham destruído.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 49, 'O Senhor trará, de um lugar longínquo, dos confins da terra, uma nação que virá contra vocês como a águia em mergulho, nação cujo idioma não compreenderão,', 3, CURRENT_TIMESTAMP, false),
(5, 28, 50, 'nação de aparência feroz, sem respeito pelos idosos nem piedade para com os moços.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 51, 'Ela devorará as crias dos seus animais e as plantações da sua terra até que vocês sejam destruídos. Ela não lhes deixará cereal, vinho, azeite, como também nenhum bezerro ou cordeiro dos seus rebanhos, até que vocês sejam arruinados.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 52, 'Ela sitiará todas as cidades da sua terra, até que caiam os altos muros fortificados em que vocês confiam. Sitiará todas as suas cidades, em toda a terra que o Senhor, o seu Deus, lhe dá.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 53, 'Por causa do sofrimento que o seu inimigo lhes infligirá durante o cerco, vocês comerão o fruto do próprio ventre, a carne dos filhos e filhas que o Senhor, o seu Deus, lhes deu.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 54, 'Até mesmo o homem mais gentil e educado entre vocês não terá compaixão do seu irmão, da mulher que ama e dos filhos que sobreviverem,', 3, CURRENT_TIMESTAMP, false),
(5, 28, 55, 'de modo que não dará a nenhum deles nenhum pedaço da carne dos seus filhos que estiver comendo, pois nada lhe sobrará devido aos sofrimentos que o seu inimigo lhe infligirá durante o cerco de todas as suas cidades.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 56, 'A mulher mais gentil e delicada entre vocês, tão delicada e gentil que não ousaria encostar no chão a sola do pé, será mesquinha com o marido a quem ama e com o filho e a filha,', 3, CURRENT_TIMESTAMP, false),
(5, 28, 57, 'não lhes dando a placenta do ventre nem os filhos que gerar. Pois a sua intenção é comê-los secretamente durante o cerco e no sofrimento que o seu inimigo infligirá a você em suas cidades.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 58, 'Se vocês não seguirem fielmente todas as palavras desta lei, escritas neste livro, e não temerem este nome glorioso e terrível, o Senhor, o seu Deus,', 3, CURRENT_TIMESTAMP, false),
(5, 28, 59, 'ele enviará pestes terríveis sobre vocês e sobre os seus descendentes, desgraças horríveis e prolongadas, doenças graves e persistentes.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 60, 'Ele trará sobre vocês todas as temíveis doenças do Egito, e vocês as contrairão.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 61, 'O Senhor também fará vir sobre vocês todo tipo de enfermidade e desgraça não registradas neste Livro da Lei, até que sejam destruídos.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 62, 'Vocês, que no passado foram tantos quanto as estrelas do céu, ficarão reduzidos a um pequeno número, porque não obedeceram ao Senhor, ao seu Deus.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 63, 'Assim como foi agradável ao Senhor fazê-los prosperar e aumentar em número, também lhe será agradável arruiná-los e destruí-los. Vocês serão desarraigados da terra em que estão entrando para dela tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 64, 'Então o Senhor os espalhará pelas nações, de um lado ao outro da terra. Ali vocês adorarão outros deuses; deuses de madeira e de pedra, que vocês e os seus antepassados nunca conheceram.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 65, 'No meio daquelas nações vocês não encontrarão repouso, nem mesmo um lugar de descanso para a sola dos pés. Lá o Senhor lhes dará coração desesperado, olhos exaustos de tanto esperar, e alma ansiosa.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 66, 'Vocês viverão em constante incerteza, cheios de terror, dia e noite, sem nenhuma segurança na vida.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 67, 'De manhã dirão: "Quem me dera fosse noite! " E de noite: "Ah, quem me dera fosse dia! ", por causa do terror que lhes encherá o coração e por aquilo que os seus olhos verão.', 3, CURRENT_TIMESTAMP, false),
(5, 28, 68, 'O Senhor os enviará de volta ao Egito, ou em navios ou pelo caminho que eu lhes disse que nunca mais poderiam percorrer. Lá vocês serão postos à venda como escravos e escravas, mas ninguém os comprará.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 1, 'São estes os termos da aliança que o Senhor ordenou que Moisés fizesse com os israelitas em Moabe, além da aliança que tinha feito com eles em Horebe.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 2, 'Moisés convocou todos os israelitas e lhes disse: Os seus olhos viram tudo o que o Senhor fez no Egito ao faraó, a todos os seus oficiais e a toda a sua terra.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 3, 'Com os seus próprios olhos vocês viram aquelas grandes provas, aqueles sinais e grandes maravilhas.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 4, 'Mas até hoje o Senhor não lhes deu mente que entenda, olhos que vejam, e ouvidos que ouçam.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 5, '"Durante os quarenta anos que os conduzi pelo deserto", disse ele, "nem as suas roupas, nem as sandálias dos seus pés se gastaram.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 6, 'Vocês não comeram pão, nem beberam vinho, nem qualquer outra bebida fermentada. Fiz isso para que vocês soubessem que eu sou o Senhor, o seu Deus. "', 3, CURRENT_TIMESTAMP, false),
(5, 29, 7, 'Quando vocês chegaram a este lugar, Seom, rei de Hesbom, e Ogue, rei de Basã, atacou-os, mas nós os derrotamos.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 8, 'Conquistamos a terra deles e a demos por herança as tribos de Rúben e de Gade e à metade da tribo de Manassés.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 9, 'Sigam fielmente os termos desta aliança, para que vocês prosperem em tudo o que fizerem.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 10, 'Hoje todos vocês estão na presença do Senhor, do seu Deus: os seus chefes e homens destacados, os seus líderes e oficiais, e todos os demais homens de Israel,', 3, CURRENT_TIMESTAMP, false),
(5, 29, 11, 'juntamente com os seus filhos e as suas mulheres e os estrangeiros que vivem nos seus acampamentos cortando lenha e carregando água para vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 12, 'Vocês estão aqui presentes para entrar em aliança com o Senhor, o seu Deus, aliança que ele está fazendo com vocês hoje, selando-a sob juramento,', 3, CURRENT_TIMESTAMP, false),
(5, 29, 13, 'para hoje confirmá-los como seu povo, para que ele seja o seu Deus conforme lhes prometeu e jurou aos seus antepassados, Abraão, Isaque e Jacó.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 14, 'Não faço esta aliança, sob juramento, somente com vocês', 3, CURRENT_TIMESTAMP, false),
(5, 29, 15, 'que estão aqui conosco na presença do Senhor nosso Deus, mas também com aqueles que não estão aqui hoje.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 16, 'Vocês mesmos sabem como vivemos no Egito e como passamos por várias nações até chegar aqui.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 17, 'Vocês viram nelas as suas imagens e os seus ídolos detestáveis, feitos de madeira, de pedra, de prata e de ouro.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 18, 'Cuidem que não haja entre vocês nenhum homem ou mulher, clã ou tribo cujo coração se afaste do Senhor, do nosso Deus, para adorar os deuses daquelas nações, e para que não haja no meio de vocês nenhuma raiz que produza esse veneno amargo.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 19, 'Se alguém, cujo coração se afastou do Senhor para adorar outros deuses, ouvir as palavras deste juramento, invocar uma bênção sobre si mesmo e pensar: "Estarei em segurança, muito embora persista em seguir o meu próprio caminho", trará desgraça tanto à terra irrigada quanto à terra seca.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 20, 'O Senhor jamais se disporá a perdoá-lo; a sua ira e o seu zelo se acenderão contra tal pessoa. Todas as maldições escritas neste livro cairão sobre ela, e o Senhor apagará o seu nome de debaixo do céu.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 21, 'O Senhor a separará de todas as tribos de Israel para que sofra desgraça, de acordo com todas as maldições da aliança escrita neste Livro da Lei.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 22, 'Os seus filhos, os seus descendentes e os estrangeiros que vierem de terras distantes verão as desgraças que terão caído sobre a terra e as doenças com que o Senhor a terá afligido.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 23, 'A terra inteira será um deserto abrasador de sal e enxofre, no qual nada que for plantado brotará, onde nenhuma vegetação crescerá. Será como a destruição de Sodoma e Gomorra, de Admá e Zeboim, que o Senhor destruiu com ira e furor.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 24, 'Todas as nações perguntarão: "Por que o Senhor fez isto a esta terra? Por que tanta ira e tanto furor? "', 3, CURRENT_TIMESTAMP, false),
(5, 29, 25, 'E a resposta será: "Foi porque este povo abandonou a aliança do Senhor, o Deus dos seus antepassados, aliança feita com eles quando os tirou do Egito.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 26, 'Eles se foram e adoraram outros deuses e se prostraram diante deles, deuses que eles não conheciam antes, deuses que o Senhor não lhes tinha dado.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 27, 'Por isso a ira do Senhor acendeu-se contra esta terra, e ele trouxe sobre ela todas as maldições escritas neste livro.', 3, CURRENT_TIMESTAMP, false),
(5, 29, 28, 'Cheio de ira, indignação e grande furor, o Senhor os desarraigou da sua terra e os lançou numa outra terra, como hoje se vê".', 3, CURRENT_TIMESTAMP, false),
(5, 29, 29, 'As coisas encobertas pertencem ao Senhor, ao nosso Deus, mas as reveladas pertencem a nós e aos nossos filhos para sempre, para que sigamos todas as palavras desta lei.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 1, 'Quando todas essas bênçãos e maldições que coloquei diante de vocês lhes sobrevierem, e elas os atingirem onde quer que o Senhor, o seu Deus, os dispersar entre as nações,', 3, CURRENT_TIMESTAMP, false),
(5, 30, 2, 'e quando vocês e os seus filhos voltarem para o Senhor, para o seu Deus, e lhe obedecerem de todo o coração e de toda a alma, de acordo com tudo o que hoje lhes ordeno,', 3, CURRENT_TIMESTAMP, false),
(5, 30, 3, 'então o Senhor, o seu Deus, lhes trará restauração e terá compaixão de vocês e os reunirá novamente de todas as nações por onde os tiver espalhado.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 4, 'Mesmo que tenham sido levados para a terra mais distante debaixo do céu, de lá o Senhor, o seu Deus, os reunirá e os trará de volta.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 5, 'Ele os trará para a terra dos seus antepassados, e vocês tomarão posse dela. Ele fará com que vocês sejam mais prósperos e mais numerosos do que os seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 6, 'O Senhor, o seu Deus, dará um coração fiel a vocês e aos seus descendentes, para que o amem de todo o coração e de toda a alma e vivam.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 7, 'O Senhor, o seu Deus, enviará então todas essas maldições sobre os inimigos que os odeiam e os perseguem.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 8, 'Vocês obedecerão de novo ao Senhor e seguirão todos os seus mandamentos que lhes dou hoje.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 9, 'Então o Senhor, o seu Deus, abençoará o que as suas mãos fizerem, os filhos do seu ventre, a cria dos seus animais e as colheitas da sua terra. O Senhor se alegrará novamente em vocês e os tornará prósperos, como se alegrou em seus antepassados,', 3, CURRENT_TIMESTAMP, false),
(5, 30, 10, 'se vocês obedecerem ao Senhor, ao seu Deus, e guardarem os seus mandamentos e decretos que estão escritos neste Livro da Lei, e se se voltarem para o Senhor, para o seu Deus, de todo o coração e de toda a alma. Vida ou Morte', 3, CURRENT_TIMESTAMP, false),
(5, 30, 11, 'O que hoje lhes estou ordenando não é difícil fazer, nem está além do seu alcance.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 12, 'Não está lá em cima no céu, de modo que vocês tenham que perguntar: "Quem subirá ao céu para consegui-lo e vir proclamá-lo a nós a fim de que lhe obedeçamos? "', 3, CURRENT_TIMESTAMP, false),
(5, 30, 13, 'Nem está além do mar, de modo que vocês tenham que perguntar: "Quem atravessará o mar para consegui-lo e, voltando, proclamá-lo a nós a fim de que lhe obedeçamos? "', 3, CURRENT_TIMESTAMP, false),
(5, 30, 14, 'Nada disso. A palavra está bem próxima de vocês; está em sua boca e em seu coração; por isso vocês poderão obedecer-lhe.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 15, 'Vejam que hoje ponho diante de vocês vida e prosperidade, ou morte e destruição.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 16, 'Pois hoje lhes ordeno que amem o Senhor, o seu Deus, andem nos seus caminhos e guardem os seus mandamentos, decretos e ordenanças; então vocês terão vida e aumentarão em número, e o Senhor, o seu Deus, os abençoará na terra em que vocês estão entrando para dela tomar posse.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 17, 'Se, todavia, o seu coração se desviar e vocês não forem obedientes, e se deixarem levar, prostrando-se diante de outros deuses para adorá-los,', 3, CURRENT_TIMESTAMP, false),
(5, 30, 18, 'eu hoje lhes declaro que sem dúvida vocês serão destruídos. Vocês não viverão muito tempo na terra em que vão entrar e da qual vão tomar posse, depois de atravessarem o Jordão.', 3, CURRENT_TIMESTAMP, false),
(5, 30, 19, 'Hoje invoco os céus e a terra como testemunhas contra vocês, de que coloquei diante de vocês a vida e a morte, a bênção e a maldição. Agora escolham a vida, para que vocês e os seus filhos vivam,', 3, CURRENT_TIMESTAMP, false),
(5, 30, 20, 'e para que vocês amem o Senhor, o seu Deus, ouçam a sua voz e se apeguem firmemente a ele. Pois o Senhor é a sua vida, e ele lhes dará muitos anos na terra que jurou dar aos seus antepassados, Abraão, Isaque e Jacó.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 1, 'Moisés disse ainda estas palavras a todo o Israel:', 3, CURRENT_TIMESTAMP, false),
(5, 31, 2, '"Estou com cento e vinte anos de idade e já não sou capaz de liderá-los. O Senhor me disse: ‘Você não atravessará o Jordão’.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 3, 'O Senhor, o seu Deus, o atravessará pessoalmente à frente de vocês. Ele destruirá estas nações perante vocês, e vocês tomarão posse da terra delas. Josué também atravessará à frente de vocês, conforme o Senhor disse.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 4, 'E o Senhor fará com eles como fez com Seom e Ogue, os reis dos amorreus, os quais destruiu juntamente com a sua terra.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 5, 'O Senhor os entregará a vocês, e vocês deverão fazer com eles tudo o que lhes ordenei.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 6, 'Sejam fortes e corajosos. Não tenham medo nem fiquem apavorados por causa deles, pois o Senhor, o seu Deus, vai com vocês; nunca os deixará, nunca os abandonará".', 3, CURRENT_TIMESTAMP, false),
(5, 31, 7, 'Então Moisés convocou Josué e lhe disse na presença de todo o Israel: "Seja forte e corajoso, pois você irá com este povo para a terra que o Senhor jurou aos seus antepassados que lhes daria, e você a repartirá entre eles como herança.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 8, 'O próprio Senhor irá à sua frente e estará com você; ele nunca o deixará, nunca o abandonará. Não tenha medo! Não se desanime! "', 3, CURRENT_TIMESTAMP, false),
(5, 31, 9, 'Moisés escreveu esta lei e a deu aos sacerdotes, filhos de Levi, que transportavam a arca da aliança do Senhor, e a todos os líderes de Israel.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 10, 'E Moisés lhes ordenou: "Ao final de cada sete anos, no ano do cancelamento das dívidas, durante a festa das Cabanas,', 3, CURRENT_TIMESTAMP, false),
(5, 31, 11, 'quando todo o Israel vier apresentar-se ao Senhor, ao seu Deus, no local que ele escolher, vocês lerão esta lei perante eles para que a escutem.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 12, 'Reúnam o povo, homens, mulheres e crianças, e os estrangeiros que morarem nas suas cidades, para que ouçam e aprendam a temer o Senhor, o seu Deus, e sigam fielmente todas as palavras desta lei.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 13, 'Os seus filhos, que não conhecem esta lei, terão que ouvi-la e aprender a temer o Senhor, o seu Deus, enquanto vocês viverem na terra da qual tomarão posse quando atravessarem o Jordão".', 3, CURRENT_TIMESTAMP, false),
(5, 31, 14, 'O Senhor disse a Moisés: "O dia da sua morte se aproxima. Chame Josué e apresentem-se na Tenda do Encontro, onde darei incumbências a ele". Então Moisés e Josué vieram e se apresentaram na Tenda do Encontro.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 15, 'Então o Senhor apareceu na Tenda, numa coluna de nuvem, e a coluna pairou sobre a entrada da Tenda.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 16, 'E o Senhor disse a Moisés: "Você vai descansar com os seus antepassados, e este povo logo irá prostituir-se, seguindo aos deuses estrangeiros da terra em que vão entrar. Eles se esquecerão de mim e quebrarão a aliança que fiz com eles.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 17, 'Naquele dia se acenderá a minha ira contra eles e eu me esquecerei deles; esconderei deles o meu rosto, e eles serão destruídos. Muitas desgraças e sofrimentos os atingirão, e naquele dia perguntarão: "Será que essas desgraças não estão acontecendo conosco porque o nosso Deus não está mais conosco? "', 3, CURRENT_TIMESTAMP, false),
(5, 31, 18, 'E com certeza esconderei o meu rosto deles naquele dia, por causa de todo o mal que praticaram, voltando-se para outros deuses.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 19, '"Agora escrevam para vocês esta canção, ensinem-na aos israelitas e façam-nos cantá-la, para que seja uma testemunha a meu favor contra eles.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 20, 'Quando eu os tiver introduzido na terra onde manam leite e mel, terra que prometi sob juramento aos seus antepassados, e quando tiverem comido com fartura e tiverem prosperado, eles se voltarão para outros deuses e os adorarão, rejeitando-me e quebrando a minha aliança.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 21, 'E, quando muitas desgraças e dificuldades lhes sobrevierem, esta canção testemunhará contra eles, porque não será esquecida pelos seus descendentes. Sei o que estão dispostos a fazer antes mesmo de levá-los para a terra que lhes prometi sob juramento".', 3, CURRENT_TIMESTAMP, false),
(5, 31, 22, 'Então, naquele dia, Moisés escreveu esta canção e ensinou-a aos israelitas.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 23, 'O Senhor deu esta ordem a Josué, filho de Num: "Seja forte e corajoso, pois você conduzirá os israelitas à terra que lhes prometi sob juramento, e eu próprio estarei com você".', 3, CURRENT_TIMESTAMP, false),
(5, 31, 24, 'Depois que Moisés terminou de escrever num livro as palavras desta lei do início ao fim,', 3, CURRENT_TIMESTAMP, false),
(5, 31, 25, 'deu esta ordem aos levitas que transportavam a arca da aliança do Senhor:', 3, CURRENT_TIMESTAMP, false),
(5, 31, 26, '"Coloquem este Livro da Lei ao lado da arca da aliança do Senhor, do seu Deus, onde ficará como testemunha contra vocês.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 27, 'Pois sei quão rebeldes e obstinados vocês são. Se vocês têm sido rebeldes contra o Senhor enquanto ainda estou vivo, quanto mais depois que eu morrer!', 3, CURRENT_TIMESTAMP, false),
(5, 31, 28, 'Reúnam na minha presença todos os líderes das suas tribos e todos os seus oficiais, para que eu fale estas palavras de modo que ouçam, e ainda invoquem os céus e a terra para testemunharem contra eles.', 3, CURRENT_TIMESTAMP, false),
(5, 31, 29, 'Pois sei que depois da minha morte vocês com certeza se corromperão e se afastarão do caminho que lhes ordenei. Nos dias futuros a desgraça cairá sobre vocês, porque vocês farão o que o Senhor reprova e o provocarão à ira por aquilo que as mãos de vocês terão feito".', 3, CURRENT_TIMESTAMP, false),
(5, 31, 30, 'E Moisés recitou as palavras desta canção, do começo ao fim, na presença de toda a assembléia de Israel:', 3, CURRENT_TIMESTAMP, false),
(5, 32, 1, 'Escutem, ó céus, e eu falarei; ouça, ó terra, as palavras da minha boca.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 2, 'Que o meu ensino caia como chuva e as minhas palavras desçam como orvalho, como chuva branda sobre o pasto novo, como garoa sobre tenras plantas.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 3, 'Proclamarei o nome do Senhor. Louvem a grandeza do nosso Deus!', 3, CURRENT_TIMESTAMP, false),
(5, 32, 4, 'Ele é a Rocha, as suas obras são perfeitas, e todos os seus caminhos são justos. É Deus fiel, que não comete erros; justo e reto ele é.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 5, 'Seus filhos têm agido corruptamente para com ele, e não como filhos; que vergonha! São geração pervertida e transviada.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 6, 'É assim que retribuem ao Senhor, povo insensato e ignorante? Não é ele o Pai de vocês, o seu Criador, que os fez e os formou?', 3, CURRENT_TIMESTAMP, false),
(5, 32, 7, 'Lembrem-se dos dias do passado; considerem as gerações há muito passadas. Perguntem aos seus pais, e estes lhes contarão, aos seus líderes, e eles lhes explicarão.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 8, 'Quando o Altíssimo deu às nações a sua herança, quando dividiu toda a humanidade, estabeleceu fronteiras para os povos de acordo com o número dos filhos de Israel.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 9, 'Pois o povo preferido do Senhor é este povo, Jacó é a herança que lhe coube.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 10, 'Numa terra deserta ele o encontrou, numa região árida e de ventos uivantes. Ele o protegeu e dele cuidou; guardou-o como a menina dos seus olhos,', 3, CURRENT_TIMESTAMP, false),
(5, 32, 11, 'como a águia que desperta a sua ninhada, paira sobre os seus filhotes, e depois estende as asas para apanhá-los, levando-os sobre elas.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 12, 'O Senhor sozinho o levou; nenhum deus estrangeiro o ajudou.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 13, 'Ele o fez cavalgar nos lugares altos da terra e o alimentou com o fruto dos campos. Ele o nutriu com mel tirado da rocha, e com óleo extraído do penhasco pedregoso,', 3, CURRENT_TIMESTAMP, false),
(5, 32, 14, 'com coalhada e leite do gado e do rebanho, e com cordeiros e bodes cevados; com os melhores carneiros de Basã e com as mais excelentes sementes de trigo. Você bebeu o espumoso sangue das uvas.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 15, 'Jesurum engordou e deu pontapés; você engordou, tornou-se pesado e farto de alimentos. Abandonou o Deus que o fez e rejeitou a Rocha, que é o seu Salvador.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 16, 'Eles o deixaram com ciúmes por causa dos deuses estrangeiros, e o provocaram com os seus ídolos abomináveis.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 17, 'Sacrificaram a demônios que não são Deus, a deuses que não conheceram, a deuses que surgiram recentemente, a deuses que os seus antepassados não adoraram.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 18, 'Vocês abandonaram a Rocha, que os gerou; vocês se esqueceram do Deus que os fez nascer.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 19, 'O Senhor viu isso e os rejeitou, porque foi provocado pelos seus filhos e suas filhas.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 20, '"Esconderei o meu rosto deles", disse, "e verei qual o fim que terão; pois são geração perversa, filhos infiéis.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 21, 'Provocaram-me os ciúmes com aquilo que nem deus é e irritaram-me com seus ídolos inúteis. Farei que tenham ciúmes de quem não é meu povo; eu os provocarei à ira por meio de uma nação insensata.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 22, 'Pois um fogo foi aceso pela minha ira, fogo que queimará até às profundezas do Sheol. Ele devorará a terra e as suas colheitas e consumirá os alicerces dos montes.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 23, '"Amontoarei desgraças sobre eles e contra eles gastarei as minhas flechas.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 24, 'Enviarei dentes de feras, uma fome devastadora, uma peste avassaladora e uma praga mortal; enviarei contra eles dentes de animais selvagens, e veneno de víboras que se arrastam no pó.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 25, 'Nas ruas a espada os deixará sem filhos; em seus lares reinará o terror. Morrerão moços e moças, crianças e homens já grisalhos.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 26, 'Eu disse que os dispersaria e que apagaria da humanidade a lembrança deles.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 27, 'Mas temi a provocação do inimigo, que o adversário entendesse mal e dissesse: ‘A nossa mão triunfou; o Senhor nada fez’. "', 3, CURRENT_TIMESTAMP, false),
(5, 32, 28, 'É uma nação sem juízo; não têm discernimento.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 29, 'Quem dera fossem sábios e entendessem; e compreendessem qual será o seu fim!', 3, CURRENT_TIMESTAMP, false),
(5, 32, 30, 'Como poderia um só homem perseguir mil, ou dois porem em fuga dez mil, a não ser que a sua Rocha os tivesse vendido, a não ser que o Senhor os tivesse abandonado?', 3, CURRENT_TIMESTAMP, false),
(5, 32, 31, 'Pois a rocha deles não é como a nossa Rocha, com o que até mesmo os nossos inimigos concordam.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 32, 'A vinha deles é de Sodoma e das lavouras de Gomorra. Suas uvas estão cheias de veneno, e seus cachos, de amargura.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 33, 'O vinho deles é a peçonha das serpentes, o veneno mortal das cobras.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 34, '"Acaso não guardei isto em segredo? Não o selei em meus tesouros?', 3, CURRENT_TIMESTAMP, false),
(5, 32, 35, 'A mim pertence a vingança e a retribuição. No devido tempo os pés deles escorregarão; o dia da sua desgraça está chegando e o seu próprio destino se apressa sobre eles. "', 3, CURRENT_TIMESTAMP, false),
(5, 32, 36, 'O Senhor julgará o seu povo e terá compaixão dos seus servos, quando vir que a força deles se esvaiu e que ninguém sobrou, nem escravo nem livre.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 37, 'Ele dirá: "Agora, onde estão os seus deuses, a rocha em que se refugiaram,', 3, CURRENT_TIMESTAMP, false),
(5, 32, 38, 'os deuses que comeram a gordura dos seus sacrifícios e beberam o vinho das suas ofertas derramadas? Que eles se levantem para ajudá-los! Que eles lhes ofereçam abrigo!', 3, CURRENT_TIMESTAMP, false),
(5, 32, 39, '"Vejam agora que eu sou o único, eu mesmo. Não há deus além de mim. Faço morrer e faço viver, feri e curarei, e ninguém é capaz de livrar-se da minha mão.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 40, 'Ergo a minha mão para os céus e declaro: Juro pelo meu nome que,', 3, CURRENT_TIMESTAMP, false),
(5, 32, 41, 'quando eu afiar a minha espada refulgente e a minha mão empunhá-la para julgar, eu me vingarei dos meus adversários e retribuirei àqueles que me odeiam.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 42, 'Embeberei as minhas flechas em sangue, enquanto a minha espada devorar carne: o sangue dos mortos e dos cativos, as cabeças dos líderes inimigos".', 3, CURRENT_TIMESTAMP, false),
(5, 32, 43, 'Cantem de alegria, ó nações, com o povo dele, pois ele vingará o sangue dos seus servos; retribuirá com vingança aos seus adversários e fará propiciação por sua terra e por seu povo.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 44, 'Moisés veio com Josué, filho de Num, e recitou todas as palavras desta canção na presença do povo.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 45, 'Quando Moisés terminou de recitar todas essas palavras a todo o Israel,', 3, CURRENT_TIMESTAMP, false),
(5, 32, 46, 'disse-lhes: "Guardem no coração todas as palavras que hoje lhes declarei solenemente, para que ordenem aos seus filhos que obedeçam fielmente a todas as palavras desta lei.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 47, 'Elas não são palavras inúteis. São a sua vida. Por meio delas vocês viverão muito tempo na terra da qual tomarão posse do outro lado do Jordão".', 3, CURRENT_TIMESTAMP, false),
(5, 32, 48, 'Naquele mesmo dia o Senhor disse a Moisés:', 3, CURRENT_TIMESTAMP, false),
(5, 32, 49, '"Suba as montanhas de Abarim, até o monte Nebo, em Moabe, em frente de Jericó, e contemple Canaã, a terra que dou aos israelitas como propriedade.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 50, 'Ali, na montanha que você tiver subido, você morrerá e será reunido aos seus antepassados, assim como o seu irmão Arão morreu no monte Hor e foi reunido aos seus antepassados.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 51, 'Assim será porque vocês dois foram infiéis para comigo na presença dos israelitas, junto às águas de Meribá, em Cades, no deserto de Zim, e porque vocês não sustentaram a minha santidade no meio dos israelitas.', 3, CURRENT_TIMESTAMP, false),
(5, 32, 52, 'Portanto, você verá a terra somente à distância, mas não entrará na terra que estou dando ao povo de Israel".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 1, 'Esta é a bênção com a qual Moisés, homem de Deus, abençoou os israelitas antes da sua morte.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 2, 'Ele disse: "O Senhor veio do Sinai e alvoreceu sobre eles desde o Seir, resplandeceu desde o monte Parã. Veio com miríades de santos desde o sul, desde as encostas de suas montanhas.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 3, 'Certamente és tu que amas o povo; todos os santos estão em tuas mãos. A teus pés todos eles se prostram e de ti recebem instrução,', 3, CURRENT_TIMESTAMP, false),
(5, 33, 4, 'a lei que Moisés nos deu, a herança da assembléia de Jacó.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 5, 'Ele era rei sobre Jesurum, quando os chefes do povo se reuniam, juntamente com as tribos de Israel.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 6, '"Que Rúben viva e não morra, mesmo sendo poucos os seus homens".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 7, 'E disse a respeito de Judá: "Ouve, ó Senhor, o grito de Judá; traze-o para o seu povo. Que as suas próprias mãos sejam suficientes, e que haja auxílio contra os seus adversários! "', 3, CURRENT_TIMESTAMP, false),
(5, 33, 8, 'A respeito de Levi disse: "O teu Urim e o teu Tumim pertencem ao homem a quem favoreceste. Tu o provaste em Massá; disputaste com ele junto às águas de Meribá.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 9, 'Levi disse do seu pai e da sua mãe: ‘Não tenho consideração por eles’. Não reconheceu os seus irmãos, Nem conheceu os próprios filhos, apesar de que guardaram a tua palavra e observaram a tua aliança.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 10, 'Ele ensina as tuas ordenanças a Jacó e a tua lei a Israel. Ele te oferece incenso e holocaustos completos no teu altar.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 11, 'Abençoa todos os seus esforços, ó Senhor, e aprova a obra das suas mãos. Despedaça os lombos dos seus adversários, dos que o odeiam, sejam quem forem".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 12, 'A respeito de Benjamim disse: "Que o amado do Senhor descanse nele em segurança, pois ele o protege o tempo inteiro, e aquele a quem o Senhor ama descansa nos seus braços".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 13, 'A respeito de José disse: "Que o Senhor abençoe a sua terra com o precioso orvalho que vem de cima, do céu, e com as águas das profundezas;', 3, CURRENT_TIMESTAMP, false),
(5, 33, 14, 'com o melhor que o sol amadurece e com o melhor que a lua possa dar;', 3, CURRENT_TIMESTAMP, false),
(5, 33, 15, 'com as dádivas mais bem escolhidas dos montes antigos e com a fertilidade das colinas eternas;', 3, CURRENT_TIMESTAMP, false),
(5, 33, 16, 'com os melhores frutos da terra e a sua plenitude, e o favor daquele que apareceu na sarça ardente. Que tudo isso repouse sobre a cabeça de José, sobre a fronte do escolhido entre os seus irmãos.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 17, 'É majestoso como a primeira cria de um touro; seus chifres são os chifres de um boi selvagem, com os quais ferirá as nações, até os confins da terra. Assim são as dezenas de milhares de Efraim; assim são os milhares de Manassés".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 18, 'A respeito de Zebulom disse: "Alegre-se, Zebulom, em suas viagens, e você, Issacar, em suas tendas.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 19, 'Eles convocarão povos para o monte e ali oferecerão sacrifícios de justiça; farão um banquete com a riqueza dos mares, com os tesouros ocultos das praias".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 20, 'A respeito de Gade disse: "Bendito é aquele que amplia os domínios de Gade! Gade fica à espreita como um leão; despedaça um braço e também a cabeça.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 21, 'Escolheu para si o melhor; a porção do líder lhe foi reservada. Tornou-se o chefe do povo e executou a justa vontade do Senhor e os seus juízos sobre Israel".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 22, 'A respeito de Dã disse: "Dã é um filhote de leão, que vem saltando desde Basã".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 23, 'A respeito de Naftali disse: "Naftali tem fartura do favor do Senhor e está repleto de suas bênçãos; suas posses estendem-se para o sul, em direção ao mar".', 3, CURRENT_TIMESTAMP, false),
(5, 33, 24, 'A respeito de Aser disse: "Bendito é Aser entre os filhos; seja ele favorecido por seus irmãos, e banhe os seus pés no azeite!', 3, CURRENT_TIMESTAMP, false),
(5, 33, 25, 'Sejam de ferro e bronze as trancas das suas portas, e dure a sua força como os seus dias.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 26, '"Não há ninguém como o Deus de Jesurum, que cavalga os céus para ajudá-lo, e cavalga as nuvens em sua majestade!', 3, CURRENT_TIMESTAMP, false),
(5, 33, 27, 'O Deus eterno é o seu refúgio, e para segurá-lo estão os braços eternos. Ele expulsará os inimigos da sua presença, dizendo: ‘Destrua-os! ’', 3, CURRENT_TIMESTAMP, false),
(5, 33, 28, 'Somente Israel viverá em segurança; a fonte de Jacó está segura numa terra de trigo e de vinho novo, onde os céus gotejam orvalho.', 3, CURRENT_TIMESTAMP, false),
(5, 33, 29, 'Como você é feliz, Israel! Quem é como você, povo salvo pelo Senhor? Ele é o seu abrigo, o seu ajudador e a sua espada gloriosa. Os seus inimigos se encolherão diante de você, mas você pisará os seus altos".', 3, CURRENT_TIMESTAMP, false),
(5, 34, 1, 'Então, das campinas de Moabe Moisés subiu ao monte Nebo, ao topo do Pisga, em frente de Jericó. Ali o Senhor lhe mostrou a terra toda: de Gileade a Dã,', 3, CURRENT_TIMESTAMP, false),
(5, 34, 2, 'toda a região de Naftali, o território de Efraim e Manassés, toda a terra de Judá até o mar ocidental,', 3, CURRENT_TIMESTAMP, false),
(5, 34, 3, 'o Neguebe e toda a região que vai do vale de Jericó, a cidade das Palmeiras, até Zoar.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 4, 'E o Senhor lhe disse: "Esta é a terra que prometi, sob juramento a Abraão, a Isaque e a Jacó, quando lhes disse: Eu a darei a seus descendentes. Permiti que você a visse com os seus próprios olhos, mas você não atravessará o rio, não entrará naquela terra".', 3, CURRENT_TIMESTAMP, false),
(5, 34, 5, 'Moisés, o servo do Senhor, morreu ali em Moabe, como o Senhor dissera.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 6, 'Ele o sepultou em Moabe, no vale que fica diante de Bete-Peor, mas até hoje ninguém sabe onde está o seu túmulo.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 7, 'Moisés tinha cento e vinte anos de idade quando morreu; todavia, nem os seus olhos nem o seu vigor se enfraqueceram.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 8, 'Os israelitas choraram Moisés nas campinas de Moabe durante trinta dias, até passar o período de pranto e luto.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 9, 'Ora, Josué, filho de Num, estava cheio do Espírito de sabedoria, porque Moisés tinha imposto as suas mãos sobre ele. De modo que os israelitas lhe obedeceram e fizeram o que o Senhor tinha ordenado a Moisés.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 10, 'Em Israel nunca mais se levantou profeta como Moisés, a quem o Senhor conheceu face a face,', 3, CURRENT_TIMESTAMP, false),
(5, 34, 11, 'e que fez todos aqueles sinais e maravilhas que o Senhor o tinha enviado para fazer no Egito, contra o faraó, contra todos os seus servos e contra toda a sua terra.', 3, CURRENT_TIMESTAMP, false),
(5, 34, 12, 'Pois ninguém jamais mostrou tamanho poder como Moisés nem executou os feitos temíveis que Moisés realizou aos olhos de todo o Israel.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 1, 'As palavras do Mestre, filho de Davi, rei em Jerusalém:', 3, CURRENT_TIMESTAMP, false),
(21, 1, 2, '"Que grande inutilidade! ", diz o Mestre. "Que grande inutilidade! Nada faz sentido! "', 3, CURRENT_TIMESTAMP, false),
(21, 1, 3, 'O que o homem ganha com todo o seu trabalho em que tanto se esforça debaixo do sol?', 3, CURRENT_TIMESTAMP, false),
(21, 1, 4, 'Gerações vêm e gerações vão, mas a terra permanece para sempre.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 5, 'O sol se levanta e o sol se põe, e depressa volta ao lugar de onde se levanta.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 6, 'O vento sopra para o sul e vira para o norte; dá voltas e mais voltas, seguindo sempre o seu curso.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 7, 'Todos os rios vão para o mar, contudo o mar nunca se enche; ainda que sempre corram para lá, para lá voltam a correr.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 8, 'Todas as coisas trazem canseira. O homem não é capaz de descrevê-las; os olhos nunca se saciam de ver, nem os ouvidos de ouvir.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 9, 'O que foi tornará a ser, o que foi feito se fará novamente; não há nada novo debaixo do sol.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 10, 'Haverá algo de que se possa dizer: "Veja! Isto é novo! "? Não! Já existiu há muito tempo; bem antes da nossa época.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 11, 'Ninguém se lembra dos que viveram na antigüidade, e aqueles que ainda virão tampouco serão lembrados pelos que vierem depois deles.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 12, 'Eu, o mestre, fui rei de Israel em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 13, 'Dediquei-me a investigar e a usar a sabedoria para explorar tudo que é feito debaixo do céu. Que fardo pesado Deus pôs sobre os homens!', 3, CURRENT_TIMESTAMP, false),
(21, 1, 14, 'Tenho visto tudo o que é feito debaixo do sol; tudo é inútil, é correr atrás do vento!', 3, CURRENT_TIMESTAMP, false),
(21, 1, 15, 'O que é torto não pode ser endireitado; o que está faltando não pode ser contado.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 16, 'Pensei comigo mesmo: Eu me tornei famoso e ultrapassei em sabedoria todos os que governaram Jerusalém antes de mim; de fato adquiri muita sabedoria e conhecimento.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 17, 'Assim eu me esforcei para compreender a sabedoria, bem como a loucura e a insensatez, mas aprendi que isso também é correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 1, 18, 'Pois quanto maior a sabedoria maior o sofrimento; e quanto maior o conhecimento, maior o desgosto.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 1, 'Pensei comigo mesmo: Vamos. Vou experimentar a alegria. Descubra as coisas boas da vida! Mas isso também se revelou inútil.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 2, 'Concluí que o rir é loucura, e a alegria de nada vale.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 3, 'Decidi-me entregar ao vinho e à extravagância; mantendo, porém, a mente orientada pela sabedoria. Eu queria saber o que valesse a pena, debaixo do céu, nos poucos dias da vida humana.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 4, 'Lancei-me a grandes projetos: construí casas e plantei vinhas para mim.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 5, 'Fiz jardins e pomares, e neles plantei todo tipo de árvore frutífera.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 6, 'Construí também reservatórios para regar os meus bosques verdejantes.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 7, 'Comprei escravos e escravas e tive escravos que nasceram em minha casa. Além disso tive também mais bois e ovelhas do que todos os que viveram antes de mim em Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 8, 'Ajuntei para mim prata e ouro, tesouros de reis e de províncias. Servi-me de cantores e cantoras, e também de um harém, as delícias do homem.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 9, 'Tornei-me mais famoso e poderoso do que todos os que viveram em Jerusalém antes de mim, conservando comigo a minha sabedoria.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 10, 'Não me neguei nada que os meus olhos desejaram; não me recusei a dar prazer algum ao meu coração. Na verdade, eu me alegrei em todo o meu trabalho; essa foi a recompensa de todo o meu esforço.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 11, 'Contudo, quando avaliei tudo o que as minhas mãos haviam feito e o trabalho que eu tanto me esforçara para realizar, percebi que tudo foi inútil, foi correr atrás do vento; não há qualquer proveito no que se faz debaixo do sol.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 12, 'Então passei a refletir na sabedoria, na loucura e na insensatez. O que pode fazer o sucessor do rei a não ser repetir o que já foi feito?', 3, CURRENT_TIMESTAMP, false),
(21, 2, 13, 'Percebi que a sabedoria é melhor que a insensatez, assim como a luz é melhor do que as trevas.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 14, 'O homem sábio tem olhos que enxergam, mas o tolo anda nas trevas; todavia, percebi que ambos têm o mesmo destino.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 15, 'Então pensei comigo mesmo: O que acontece ao tolo também me acontecerá. Que proveito eu tive em ser sábio? Então eu disse no meu íntimo: Isso não faz o menor sentido!', 3, CURRENT_TIMESTAMP, false),
(21, 2, 16, 'Nem o sábio, nem o tolo, serão lembrados para sempre; nos dias futuros ambos serão esquecidos. Como pode o sábio morrer como morre o tolo?', 3, CURRENT_TIMESTAMP, false),
(21, 2, 17, 'Por isso desprezei a vida, pois o trabalho que se faz debaixo do sol pareceu-me muito pesado. Tudo era inútil, era correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 18, 'Desprezei todas as coisas pelas quais eu tanto me esforçara debaixo do sol, pois terei que deixá-las para aquele que me suceder.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 19, 'E quem pode dizer se ele será sábio ou tolo? Contudo, terá domínio sobre tudo o que realizei com o meu trabalho e com a minha sabedoria debaixo do sol. Isso também não faz sentido.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 20, 'Cheguei ao ponto de me desesperar por causa de todo o trabalho em que tanto me esforcei debaixo do sol.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 21, 'Pois um homem pode realizar o seu trabalho com sabedoria, conhecimento e habilidade, mas terá que deixar tudo o que possui como herança para alguém que não se esforçou por aquilo. Isso também é um absurdo e uma grande injustiça.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 22, 'Que proveito tem um homem de todo o esforço e de toda a ansiedade com que trabalha debaixo do sol?', 3, CURRENT_TIMESTAMP, false),
(21, 2, 23, 'Durante toda a sua vida, seu trabalho não passa de dor e tristeza; mesmo à noite a sua mente não descansa. Isso também é absurdo.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 24, 'Para o homem não existe nada melhor do que comer, beber e encontrar prazer em seu trabalho. E vi que isso também vem da mão de Deus.', 3, CURRENT_TIMESTAMP, false),
(21, 2, 25, 'E quem aproveitou melhor as comidas e os prazeres do que eu?', 3, CURRENT_TIMESTAMP, false),
(21, 2, 26, 'Ao homem que o agrada, Deus recompensa com sabedoria, conhecimento e felicidade. Quanto ao pecador, Deus o encarrega de ajuntar e armazenar riquezas para entregá-las a quem o agrada. Isso também é inútil, é correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 1, 'Para tudo há uma ocasião, e um tempo para cada propósito debaixo do céu:', 3, CURRENT_TIMESTAMP, false),
(21, 3, 2, 'tempo de nascer e tempo de morrer, tempo de plantar e tempo de arrancar o que se plantou,', 3, CURRENT_TIMESTAMP, false),
(21, 3, 3, 'tempo de matar e tempo de curar, tempo de derrubar e tempo de construir,', 3, CURRENT_TIMESTAMP, false),
(21, 3, 4, 'tempo de chorar e tempo de rir, tempo de prantear e tempo de dançar,', 3, CURRENT_TIMESTAMP, false),
(21, 3, 5, 'tempo de espalhar pedras e tempo de ajuntá-las, tempo de abraçar e tempo de se conter,', 3, CURRENT_TIMESTAMP, false),
(21, 3, 6, 'tempo de procurar e tempo de desistir, tempo de guardar e tempo de lançar fora,', 3, CURRENT_TIMESTAMP, false),
(21, 3, 7, 'tempo de rasgar e tempo de costurar, tempo de calar e tempo de falar,', 3, CURRENT_TIMESTAMP, false),
(21, 3, 8, 'tempo de amar e tempo de odiar, tempo de lutar e tempo de viver em paz.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 9, 'O que ganha o trabalhador com todo o seu esforço?', 3, CURRENT_TIMESTAMP, false),
(21, 3, 10, 'Tenho visto o fardo que Deus impôs aos homens.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 11, 'Ele fez tudo apropriado a seu tempo. Também pôs no coração do homem o anseio pela eternidade; mesmo assim este não consegue compreender inteiramente o que Deus fez.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 12, 'Descobri que não há nada melhor para o homem do que ser feliz e praticar o bem enquanto vive.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 13, 'Descobri também que poder comer, beber e ser recompensado pelo seu trabalho, é um presente de Deus.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 14, 'Sei que tudo o que Deus faz permanecerá para sempre; a isso nada se pode acrescentar, e disso nada se pode tirar. Deus assim faz para que os homens o temam.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 15, 'Aquilo que é, já foi, e o que será já foi anteriormente; Deus investigará o passado.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 16, 'Descobri também que debaixo do sol: No lugar da justiça havia impiedade, no lugar da retidão, ainda mais impiedade.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 17, 'Pensei comigo mesmo: O justo e o ímpio, Deus julgará a ambos, pois há um tempo para todo propósito, um tempo para tudo o que acontece.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 18, 'Também pensei: Deus prova os homens para que vejam que são como os animais.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 19, 'O destino do homem é o mesmo do animal; o mesmo destino os aguarda. Assim como morre um, também morre o outro. Todos têm o mesmo fôlego de vida; o homem não tem vantagem alguma sobre o animal. Nada faz sentido!', 3, CURRENT_TIMESTAMP, false),
(21, 3, 20, 'Todos vão para o mesmo lugar; vieram todos do pó, e ao pó todos retornarão.', 3, CURRENT_TIMESTAMP, false),
(21, 3, 21, 'Quem pode dizer se o fôlego do homem sobe às alturas e se o fôlego do animal desce para a terra?', 3, CURRENT_TIMESTAMP, false),
(21, 3, 22, 'Por isso concluí que não há nada melhor para o homem do que desfrutar do seu trabalho, porque esta é a sua recompensa. Pois, quem poderá fazê-lo ver o que acontecerá depois de morto?', 3, CURRENT_TIMESTAMP, false),
(21, 4, 1, 'De novo voltei a minha atenção e vi toda a opressão que ocorre debaixo do sol: Vi as lágrimas dos oprimidos, mas não há quem os console; o poder estava do lado dos seus opressores, e não há quem os console.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 2, 'Por isso considerei os mortos, mais felizes do que os vivos, pois estes ainda têm que viver!', 3, CURRENT_TIMESTAMP, false),
(21, 4, 3, 'No entanto, melhor do que ambos é aquele que ainda não nasceu, que não viu o mal que se faz debaixo do sol.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 4, 'Descobri que todo trabalho e toda realização surgem da competição que existe entre as pessoas. Mas isso também é absurdo, é correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 5, 'O tolo cruza os braços e destrói a própria vida.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 6, 'Melhor é ter um punhado com tranqüilidade do que dois punhados à custa de muito esforço e de correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 7, 'Descobri ainda outra situação absurda debaixo do sol:', 3, CURRENT_TIMESTAMP, false),
(21, 4, 8, 'Havia um homem totalmente solitário; não tinha filho nem irmão. Trabalhava sem parar! Contudo, os seus olhos não se satisfaziam com a sua riqueza. Ele sequer perguntava: "Para quem estou trabalhando tanto, e por que razão deixo de me divertir? " Isso também é absurdo. É um trabalho muito ingrato!', 3, CURRENT_TIMESTAMP, false),
(21, 4, 9, 'É melhor ter companhia do que estar sozinho, porque maior é a recompensa do trabalho de duas pessoas.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 10, 'Se um cair, o amigo pode ajudá-lo a levantar-se. Mas pobre do homem que cai e não tem quem o ajude a levantar-se!', 3, CURRENT_TIMESTAMP, false),
(21, 4, 11, 'E se dois dormirem juntos, vão manter-se aquecidos. Como, porém, manter-se aquecido sozinho?', 3, CURRENT_TIMESTAMP, false),
(21, 4, 12, 'Um homem sozinho pode ser vencido, mas dois conseguem defender-se. Um cordão de três dobras não se rompe com facilidade.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 13, 'Melhor é um jovem pobre e sábio, do que um rei idoso e tolo, que não mais aceita repreensão.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 14, 'O jovem pode ter saído da prisão e chegado ao trono, ou pode ter nascido pobre no país daquele rei.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 15, 'Percebi que, ainda assim, o povo que vivia debaixo do sol seguia o jovem, o sucessor do rei.', 3, CURRENT_TIMESTAMP, false),
(21, 4, 16, 'O número dos que aderiram a ele era incontável. A geração seguinte, porém, não ficou satisfeita com o sucessor. Isso também não faz sentido, é correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 1, 'Quando você for ao santuário de Deus, seja reverente. Quem se aproxima para ouvir é melhor do que os tolos que oferecem sacrifício sem saber que estão agindo mal.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 2, 'Não seja precipitado de lábios, nem apressado de coração para fazer promessas diante de Deus. Deus está nos céus, e você está na terra, por isso, fale pouco.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 3, 'Das muitas ocupações brotam sonhos; do muito falar nasce a prosa vã do tolo.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 4, 'Quando você fizer um voto, cumpra-o sem demora, pois os tolos desagradam a Deus; cumpra o seu voto.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 5, 'É melhor não fazer voto do que fazer e não cumprir.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 6, 'Não permita que a sua boca o faça pecar. E não diga ao mensageiro de Deus: "O meu voto foi um engano". Por que irritar a Deus com o que você diz e deixá-lo destruir o que você realizou?', 3, CURRENT_TIMESTAMP, false),
(21, 5, 7, 'Em meio a tantos sonhos, absurdos e conversas inúteis, tenha temor de Deus.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 8, 'Se você vir o pobre oprimido numa província e vir que lhe são negados o direito e a justiça, não fique surpreso; pois todo oficial está subordinado a alguém em posição superior, e sobre os dois há outros em posição ainda mais alta.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 9, 'Mesmo assim, é vantagem a nação ter um rei que a governe e que se interesse pela agricultura.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 10, 'Quem ama o dinheiro jamais terá o suficiente; quem ama as riquezas jamais ficará satisfeito com os seus rendimentos. Isso também não faz sentido.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 11, 'Quando aumentam os bens, também aumentam os que os consomem. E que benefício trazem os bens a quem os possui, senão dar um pouco de alegria aos seus olhos?', 3, CURRENT_TIMESTAMP, false),
(21, 5, 12, 'O sono do trabalhador é ameno, quer coma pouco quer coma muito, mas a fartura de um homem rico não lhe dá tranqüilidade para dormir.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 13, 'Há um mal terrível que vi debaixo do sol: riquezas acumuladas para infelicidade do seu possuidor.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 14, 'Se as riquezas se perdem num mau negócio, nada ficará para o filho que lhe nascer.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 15, 'O homem sai nu do ventre de sua mãe, e como vem, assim vai. De todo o trabalho em que se esforçou nada levará consigo.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 16, 'Há também outro mal terrível: Como o homem vem, assim ele vai, e o que obtém, de todo o seu esforço em busca do vento?', 3, CURRENT_TIMESTAMP, false),
(21, 5, 17, 'Passa toda a sua vida nas trevas, com grande frustração, doença e amargura.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 18, 'Assim, descobri que o melhor e o que vale a pena é comer, beber, e desfrutar o resultado de todo o esforço que se faz debaixo do sol durante os poucos dias de vida que Deus dá ao homem, pois essa é a sua recompensa.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 19, 'E, quando Deus concede riquezas e bens a alguém, e o capacita a desfrutá-los, a aceitar a sua sorte e a ser feliz em seu trabalho, isso é um presente de Deus.', 3, CURRENT_TIMESTAMP, false),
(21, 5, 20, 'Raramente essa pessoa reflete no fato de que a sua vida é curta, porque Deus o mantém ocupado com a alegria do coração.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 1, 'Vi ainda outro mal debaixo do sol, que pesa bastante sobre a humanidade:', 3, CURRENT_TIMESTAMP, false),
(21, 6, 2, 'Deus dá riquezas, bens e honra ao homem, de modo que não lhe falta nada que os seus olhos desejam; mas Deus não lhe permite desfrutar tais coisas, e outro as desfruta em seu lugar. Isso não faz sentido; é um mal terrível.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 3, 'Um homem pode ter cem filhos e viver muitos anos. No entanto, se não desfrutar as coisas boas da vida, digo que uma criança que nasce morta e nem recebe um enterro digno, tem melhor sorte do que ele.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 4, 'Ela nasce em vão, e parte em trevas, e nas trevas o seu nome fica escondido.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 5, 'Embora jamais tenha visto o sol ou conhecido qualquer coisa, ela tem mais descanso do que tal homem.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 6, 'Pois, de que lhe valeria viver dois mil anos, e não poder desfrutar a sua prosperidade? Afinal, não vão todos para o mesmo lugar?', 3, CURRENT_TIMESTAMP, false),
(21, 6, 7, 'Todo o esforço do homem é feito para a sua boca, contudo, o seu apetite jamais se satisfaz.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 8, 'Que vantagem tem o sábio em relação ao tolo? Que vantagem tem o pobre em saber como se portar diante dos outros?', 3, CURRENT_TIMESTAMP, false),
(21, 6, 9, 'Melhor é contentar-se com o que os olhos vêem do que vaguear o apetite. Isso também não faz sentido, é correr atrás do vento.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 10, 'Tudo o que existe já recebeu um nome, e já se sabe o que o homem é; não se pode lutar contra alguém mais forte.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 11, 'Quanto mais palavras, mais tolices, e sem nenhum proveito.', 3, CURRENT_TIMESTAMP, false),
(21, 6, 12, 'Pois, quem sabe o que é bom para o homem, nos poucos dias de sua vida vazia, em que ele passa como uma sombra? Quem poderá lhe contar o que acontecerá debaixo do sol depois que ele partir?', 3, CURRENT_TIMESTAMP, false),
(21, 7, 1, 'Um bom nome é melhor do que um perfume finíssimo, e o dia da morte é melhor do que o dia do nascimento.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 2, 'É melhor ir a uma casa onde há luto do que a uma casa em festa, pois a morte é o destino de todos; os vivos devem levar isso a sério!', 3, CURRENT_TIMESTAMP, false),
(21, 7, 3, 'A tristeza é melhor do que o riso, porque o rosto triste melhora o coração.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 4, 'O coração do sábio está na casa onde há luto, mas o dos tolos, na casa da alegria.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 5, 'É melhor ouvir a repreensão de um sábio do que a canção dos tolos.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 6, 'Tal como o estalo de espinhos debaixo da panela, assim é o riso dos tolos. Isso também não faz sentido.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 7, 'A opressão transforma o sábio em tolo, e o suborno corrompe o coração.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 8, 'O fim das coisas é melhor do que o seu início, e o paciente é melhor que o orgulhoso.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 9, 'Não permita que a ira domine depressa o seu espírito, pois a ira se aloja no íntimo dos tolos.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 10, 'Não diga: "Por que os dias do passado foram melhores que os de hoje? " Pois não é sábio fazer tais perguntas.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 11, 'A sabedoria, como uma herança, é coisa boa e beneficia aqueles que vêem o sol.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 12, 'A sabedoria oferece proteção, como o faz o dinheiro, mas a vantagem do conhecimento é esta: a sabedoria preserva a vida de quem a possui.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 13, 'Considere o que Deus fez: Quem pode endireitar o que ele fez torto?', 3, CURRENT_TIMESTAMP, false),
(21, 7, 14, 'Quando os dias forem bons, aproveite-os bem; mas, quando forem ruins, considere: Deus fez tanto um quanto o outro, para evitar que o homem descubra qualquer coisa sobre o seu futuro.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 15, 'Nesta vida sem sentido eu já vi de tudo: um justo que morreu apesar da sua justiça, e um ímpio que teve vida longa apesar da sua impiedade.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 16, 'Não seja excessivamente justo nem demasiadamente sábio; por que destruir-se a si mesmo?', 3, CURRENT_TIMESTAMP, false),
(21, 7, 17, 'Não seja demasiadamente ímpio e não seja tolo; por que morrer antes do tempo?', 3, CURRENT_TIMESTAMP, false),
(21, 7, 18, 'É bom reter uma coisa e não abrir mão da outra, pois quem teme a Deus evitará ambos os extremos.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 19, 'A sabedoria torna o sábio mais poderoso que uma cidade guardada por dez valentes.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 20, 'Todavia, não há um só justo na terra, ninguém que pratique o bem e nunca peque.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 21, 'Não dê atenção a todas as palavras que o povo diz, caso contrário, poderá ouvir o seu próprio servo falando mal de você;', 3, CURRENT_TIMESTAMP, false),
(21, 7, 22, 'pois em seu coração você sabe que muitas vezes você mesmo também falou mal de outros.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 23, 'Tudo isso eu examinei mediante a sabedoria e disse: Estou decidido a ser sábio; mas isso estava fora do meu alcance.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 24, 'A realidade está bem distante e é muito profunda; quem pode descobri-la?', 3, CURRENT_TIMESTAMP, false),
(21, 7, 25, 'Por isso dediquei-me a aprender, a investigar, a buscar a sabedoria e a razão de ser das coisas, para compreender a insensatez da impiedade e a loucura da insensatez.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 26, 'Descobri que muito mais amarga do que a morte é a mulher que serve de laço, cujo coração é uma armadilha e cujas mãos são correntes. O homem que agrada a Deus escapará dela, mas ao pecador ela apanhará.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 27, '"Veja", diz o Mestre, "foi isto que descobri: Ao comparar uma coisa com outra para descobrir a sua razão de ser,', 3, CURRENT_TIMESTAMP, false),
(21, 7, 28, 'sim, durante essa minha busca que ainda não terminou, entre mil homens, descobri apenas um que julgo digno, mas entre as mulheres não achei uma sequer.', 3, CURRENT_TIMESTAMP, false),
(21, 7, 29, 'Assim, cheguei a esta conclusão: Deus fez os homens justos, mas eles foram em busca de muitas intrigas. "', 3, CURRENT_TIMESTAMP, false),
(21, 8, 1, 'Quem é como o sábio? Quem sabe interpretar as coisas? A sabedoria de um homem Alcança o favor do rei e muda o seu semblante carregado.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 2, 'Este é o meu conselho: obedeça às ordens do rei porque você fez um juramento diante de Deus.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 3, 'Não se apresse em deixar a presença do rei, nem se levante em favor de uma causa errada, pois o rei faz o que bem entende.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 4, 'Pois a palavra do rei é soberana, e ninguém lhe pode perguntar: "Que é que estás fazendo? "', 3, CURRENT_TIMESTAMP, false),
(21, 8, 5, 'Quem obedece às suas ordens não sofrerá mal algum, pois o coração sábio saberá a hora e a maneira certa de agir.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 6, 'Pois há uma hora certa e também uma maneira certa de agir para cada situação. O sofrimento de um homem, no entanto, pesa muito sobre ele,', 3, CURRENT_TIMESTAMP, false),
(21, 8, 7, 'visto que ninguém conhece o futuro. Quem lhe poderá dizer o que vai acontecer?', 3, CURRENT_TIMESTAMP, false),
(21, 8, 8, 'Ninguém tem o poder de conter o próprio espírito; tampouco tem poder sobre o dia da sua morte, e de escapar dos efeitos da guerra; nem mesmo a maldade livra aqueles que a praticam.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 9, 'Tudo isso vi quando me pus a refletir em tudo o que se faz debaixo do sol. Há ocasiões em que um homem domina sobre outros para a sua própria infelicidade.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 10, 'Nessas ocasiões, vi ímpios serem sepultados e gente indo e vindo do lugar onde eles foram enterrados. Todavia, os que haviam praticado o bem foram esquecidos na cidade. Isso também não faz sentido.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 11, 'Quando os crimes não são castigados logo, o coração do homem se enche de planos para fazer o mal.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 12, 'O ímpio pode cometer uma centena de crimes e até ter vida longa, mas sei muito bem que as coisas serão melhores para os que temem a Deus, para os que mostram respeito diante dele.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 13, 'Para os ímpios, no entanto, nada irá bem, porque não temem a Deus, e os seus dias, como sombras, serão poucos.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 14, 'Há mais uma coisa sem sentido na terra: justos que recebem o que os ímpios merecem, e ímpios que recebem o que os justos merecem. Isto também, penso eu, não faz sentido.', 3, CURRENT_TIMESTAMP, false),
(21, 8, 15, 'Por isso recomendo que se desfrute a vida, porque debaixo do sol não há nada melhor para o homem do que comer, beber e alegrar-se. Sejam esses os seus companheiros no seu duro trabalho durante todos os dias da vida que Deus lhe der debaixo do sol!', 3, CURRENT_TIMESTAMP, false),
(21, 8, 16, 'Quando voltei a mente para conhecer a sabedoria e observar as atividades do homem sobre a terra, daquele cujos olhos não vêem sono nem de dia nem de noite,', 3, CURRENT_TIMESTAMP, false),
(21, 8, 17, 'então percebi tudo o que Deus tem feito. Ninguém é capaz de entender o que se faz debaixo do sol. Por mais que se esforce para descobrir o sentido das coisas, o homem não o encontrará. O sábio pode até afirmar que entende, mas, na realidade não o consegue encontrar.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 1, 'Refleti nisso tudo e cheguei à conclusão de que os justos e os sábios, e aquilo que eles fazem, estão nas mãos de Deus. O que os espera, se amor ou ódio, ninguém sabe.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 2, 'Todos partilham um destino comum: o justo e o ímpio, o bom e o mau, o puro e o impuro, o que oferece sacrifícios e o que não oferece. O que acontece com o homem bom, acontece com o pecador; o que acontece com quem faz juramentos, acontece com quem teme fazê-los.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 3, 'Este é o mal que há em tudo o que acontece debaixo do sol: O destino de todos é o mesmo. O coração dos homens, além do mais, está cheio de maldade e de loucura durante toda a vida; e por fim eles se juntarão aos mortos.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 4, 'Quem está entre os vivos tem esperança; até um cachorro vivo é melhor do que um leão morto!', 3, CURRENT_TIMESTAMP, false),
(21, 9, 5, 'Pois os vivos sabem que morrerão, mas os mortos nada sabem; para eles não haverá mais recompensa, e já não se tem lembrança deles.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 6, 'Para eles o amor, o ódio e a inveja há muito desapareceram; nunca mais terão parte em nada do que acontece debaixo do sol.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 7, 'Portanto, vá, coma com prazer a sua comida, e beba o seu vinho de coração alegre, pois Deus já se agradou do que você faz.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 8, 'Esteja sempre vestido com roupas de festa, e unja sempre a sua cabeça com óleo.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 9, 'Desfrute a vida com a mulher a quem você ama, todos os dias desta vida sem sentido que Deus dá a você debaixo do sol; todos os seus dias sem sentido! Pois essa é a sua recompensa na vida pelo seu árduo trabalho debaixo do sol.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 10, 'O que as suas mãos tiverem que fazer, que o façam com toda a sua força, pois na sepultura, para onde você vai, não há atividade nem planejamento, não há conhecimento nem sabedoria.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 11, 'Percebi ainda outra coisa debaixo do sol: Os velozes nem sempre vencem a corrida; os fortes nem sempre triunfam na guerra; os sábios nem sempre têm comida; os prudentes nem sempre são ricos; os instruídos nem sempre têm prestígio; pois o tempo e o acaso afetam a todos.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 12, 'Além do mais, ninguém sabe quando virá a sua hora: Assim como os peixes são apanhados numa rede fatal e os pássaros são pegos num laço, também os homens são enredados pelos tempos de desgraça que caem inesperadamente sobre eles.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 13, 'Também vi debaixo do sol este exemplo de sabedoria que muito me impressionou.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 14, 'Havia uma pequena cidade, de poucos habitantes. Um rei poderoso veio contra ela, cercou-a com muitos dispositivos de guerra.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 15, 'Ora, naquela cidade vivia um homem pobre mas sábio, e com sua sabedoria ele salvou a cidade. No entanto, ninguém se lembrou daquele pobre.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 16, 'Por isso pensei: Embora a sabedoria seja melhor do que a força, a sabedoria do pobre é desprezada, e logo já não se dá atenção às suas palavras.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 17, 'As palavras dos sábios devem ser ouvidas com mais atenção do que os gritos de quem domina sobre tolos.', 3, CURRENT_TIMESTAMP, false),
(21, 9, 18, 'A sabedoria é melhor do que as armas de guerra, mas um só pecador destrói muita coisa boa.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 1, 'Assim como a mosca morta produz mau cheiro e estraga o perfume, também um pouco de insensatez pesa mais que a sabedoria e a honra.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 2, 'O coração do sábio se inclina para o bem, mas o coração do tolo, para o mal.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 3, 'Mesmo quando anda pelo caminho, o tolo age sem o mínimo bom senso e mostra a todos que não passa de um tolo.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 4, 'Se a ira de uma autoridade se levantar contra você, não abandone o seu posto; a tranqüilidade evita grandes erros.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 5, 'Há outro mal que vi debaixo do sol, um erro cometido pelos que governam:', 3, CURRENT_TIMESTAMP, false),
(21, 10, 6, 'Tolos são postos em cargos elevados, enquanto ricos ocupam cargos inferiores.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 7, 'Tenho visto servos andando a cavalo, e príncipes andando a pé, como servos.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 8, 'Quem cava um poço cairá nele; quem derruba um muro será picado por uma cobra.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 9, 'Quem arranca pedras, com elas se ferirá; quem racha lenha se arrisca.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 10, 'Se o machado está cego e sua lâmina não foi afiada, é preciso golpear com mais força; agir com sabedoria assegura o sucesso.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 11, 'Se a cobra morder antes de ser encantada, para que servirá o encantador?', 3, CURRENT_TIMESTAMP, false),
(21, 10, 12, 'As palavras do sábio lhe trazem benefícios, mas os lábios do insensato o destroem.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 13, 'No início as suas palavras são mera tolice, mas no final são loucura perversa.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 14, 'Embora o tolo fale sem parar, ninguém sabe o que está para vir; quem poderá dizer a outrem o que lhe acontecerá depois?', 3, CURRENT_TIMESTAMP, false),
(21, 10, 15, 'O trabalho do tolo o deixa tão exausto que ele nem consegue achar o caminho de casa.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 16, 'Pobre da terra cujo rei é jovem demais e cujos líderes fazem banquetes logo de manhã.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 17, 'Feliz é a terra cujo rei é de origem nobre, e cujos líderes comem no devido tempo, para recuperar as forças, e não para embriagar-se.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 18, 'Por causa da preguiça, o telhado se enverga; por causa das mãos indolentes, a casa tem goteiras.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 19, 'O banquete é feito para divertir, e o vinho torna a vida alegre, mas isso tudo se paga com dinheiro.', 3, CURRENT_TIMESTAMP, false),
(21, 10, 20, 'Nem em pensamento insulte o rei! Nem mesmo em seu quarto amaldiçoe o rico! Porque uma ave do céu poderá levar as suas palavras, e seres alados poderão divulgar o que você disser.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 1, 'Atire o seu pão sobre as águas, e depois de muitos dias você tornará a encontrá-lo.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 2, 'Reparta o que você tem com sete, até mesmo com oito, pois você não sabe que desgraça poderá cair sobre a terra.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 3, 'Quando as nuvens estão cheias de água, derramam chuva sobre a terra. Quer uma árvore caia para o sul quer para o norte, no lugar em que cair ficará.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 4, 'Quem observa o vento não plantará; e quem olha para as nuvens não colherá.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 5, 'Assim como você não conhece o caminho do vento, nem como o corpo é formado no ventre de uma mulher, também não pode compreender as obras de Deus, o Criador de todas as coisas.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 6, 'Plante de manhã a sua semente, e mesmo ao entardecer não deixe as suas mãos ficarem à toa, pois você não sabe o que acontecerá, se esta ou aquela produzirá, ou se as duas serão igualmente boas.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 7, 'A luz é agradável, é bom ver o sol.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 8, 'Por mais que um homem viva, deve desfrutar sua vida toda. Lembre-se, porém, dos dias de trevas, pois serão muitos. Tudo o que está para vir não faz sentido.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 9, 'Alegre-se, jovem, na sua mocidade! Seja feliz o seu coração nos dias da sua juventude! Siga por onde seu coração mandar, até onde a sua vista alcançar; mas saiba que por todas essas coisas Deus o trará a julgamento.', 3, CURRENT_TIMESTAMP, false),
(21, 11, 10, 'Afaste do coração a ansiedade e acabe com o sofrimento do seu corpo, pois a juventude e o vigor são passageiros.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 1, 'Lembre-se do seu Criador nos dias da sua juventude, antes que venham os dias difíceis e antes que se aproximem os anos em que você dirá: "Não tenho satisfação neles";', 3, CURRENT_TIMESTAMP, false),
(21, 12, 2, 'antes que se escureçam o sol e a luz, a lua e as estrelas, e as nuvens voltem depois da chuva;', 3, CURRENT_TIMESTAMP, false),
(21, 12, 3, 'quando os guardas da casa tremerem e os homens fortes caminharem encurvados, e pararem os moedores por serem poucos, e aqueles que olham pelas janelas enxergarem embaçado;', 3, CURRENT_TIMESTAMP, false),
(21, 12, 4, 'quando as portas da rua forem fechadas e diminuir o som da moagem; quando o barulho das aves o fizer despertar, mas o som de todas as canções lhe parecer fraco;', 3, CURRENT_TIMESTAMP, false),
(21, 12, 5, 'quando você tiver medo de altura, e dos perigos das ruas; quando florir a amendoeira, o gafanhoto for um peso e o desejo já não se despertar. Então o homem se vai para o seu lar eterno, e os pranteadores já vagueiam pelas ruas.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 6, 'Sim, lembre-se dele, antes que se rompa o cordão de prata, ou se quebre a taça de ouro; antes que o cântaro se despedace junto à fonte, a roda se quebre junto ao poço,', 3, CURRENT_TIMESTAMP, false),
(21, 12, 7, 'o pó volte à terra, de onde veio, e o espírito volte a Deus, que o deu.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 8, '"Tudo sem sentido! Sem sentido! ", diz o mestre. "Nada faz sentido! Nada faz sentido! "', 3, CURRENT_TIMESTAMP, false),
(21, 12, 9, 'Além de ser sábio, o mestre também ensinou conhecimento ao povo. Ele escutou, examinou e colecionou muitos provérbios.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 10, 'Procurou também encontrar as palavras certas, e o que ele escreveu era reto e verdadeiro.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 11, 'As palavras dos sábios são como aguilhões, a coleção dos seus ditos como pregos bem fixados, provenientes do único Pastor.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 12, 'Cuidado, meu filho; nada acrescente a eles. Não há limite para a produção de livros, e estudar demais deixa exausto o corpo.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 13, 'Agora que já se ouviu tudo, aqui está a conclusão: Tema a Deus e guarde os seus mandamentos, pois isso é o essencial para o homem.', 3, CURRENT_TIMESTAMP, false),
(21, 12, 14, 'Pois Deus trará a julgamento tudo o que foi feito, inclusive tudo o que está escondido, seja bom, seja mal.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, aos santos e fiéis em Cristo Jesus que estão em Éfeso:', 3, CURRENT_TIMESTAMP, false),
(49, 1, 2, 'A vocês, graça e paz da parte de Deus nosso Pai e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, que nos abençoou com todas as bênçãos espirituais nas regiões celestiais em Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 4, 'Porque Deus nos escolheu nele antes da criação do mundo, para sermos santos e irrepreensíveis em sua presença.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 5, 'Em amor nos predestinou para sermos adotados como filhos por meio de Jesus Cristo, conforme o bom propósito da sua vontade,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 6, 'para o louvor da sua gloriosa graça, a qual nos deu gratuitamente no Amado.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 7, 'Nele temos a redenção por meio de seu sangue, o perdão dos pecados, de acordo com as riquezas da graça de Deus,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 8, 'a qual ele derramou sobre nós com toda a sabedoria e entendimento.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 9, 'E nos revelou o mistério da sua vontade, de acordo com o seu bom propósito que ele estabeleceu em Cristo,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 10, 'isto é, de fazer convergir em Cristo todas as coisas, celestiais ou terrenas, na dispensação da plenitude dos tempos.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 11, 'Nele fomos também escolhidos, tendo sido predestinados conforme o plano daquele que faz todas as coisas segundo o propósito da sua vontade,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 12, 'a fim de que nós, os que primeiro esperamos em Cristo, sejamos para o louvor da sua glória.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 13, 'Nele, quando vocês ouviram e creram na palavra da verdade, o evangelho que os salvou, vocês foram selados com o Espírito Santo da promessa,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 14, 'que é a garantia da nossa herança até a redenção daqueles que pertencem a Deus, para o louvor da sua glória.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 15, 'Por essa razão, desde que ouvi falar da fé que vocês têm no Senhor Jesus e do amor que demonstram para com todos os santos,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 16, 'não deixo de dar graças por vocês, mencionando-os em minhas orações.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 17, 'Peço que o Deus de nosso Senhor Jesus Cristo, o glorioso Pai, lhes dê espírito de sabedoria e de revelação, no pleno conhecimento dele.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 18, 'Oro também para que os olhos do coração de vocês sejam iluminados, a fim de que vocês conheçam a esperança para a qual ele os chamou, as riquezas da gloriosa herança dele nos santos', 3, CURRENT_TIMESTAMP, false),
(49, 1, 19, 'e a incomparável grandeza do seu poder para conosco, os que cremos, conforme a atuação da sua poderosa força.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 20, 'Esse poder ele exerceu em Cristo, ressuscitando-o dos mortos e fazendo-o assentar-se à sua direita, nas regiões celestiais,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 21, 'muito acima de todo governo e autoridade, poder e domínio, e de todo nome que se possa mencionar, não apenas nesta era, mas também na que há de vir.', 3, CURRENT_TIMESTAMP, false),
(49, 1, 22, 'Deus colocou todas as coisas debaixo de seus pés e o designou como cabeça de todas as coisas para a igreja,', 3, CURRENT_TIMESTAMP, false),
(49, 1, 23, 'que é o seu corpo, a plenitude daquele que enche todas as coisas, em toda e qualquer circunstância.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 1, 'Vocês estavam mortos em suas transgressões e pecados,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 2, 'nos quais costumavam viver, quando seguiam a presente ordem deste mundo e o príncipe do poder do ar, o espírito que agora está atuando nos que vivem na desobediência.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 3, 'Anteriormente, todos nós também vivíamos entre eles, satisfazendo as vontades da nossa carne, seguindo os seus desejos e pensamentos. Como os outros, éramos por natureza merecedores da ira.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 4, 'Todavia, Deus, que é rico em misericórdia, pelo grande amor com que nos amou,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 5, 'deu-nos vida juntamente com Cristo, quando ainda estávamos mortos em transgressões — pela graça vocês são salvos.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 6, 'Deus nos ressuscitou com Cristo e com ele nos fez assentar nos lugares celestiais em Cristo Jesus,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 7, 'para mostrar, nas eras que hão de vir, a incomparável riqueza de sua graça, demonstrada em sua bondade para conosco em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 8, 'Pois vocês são salvos pela graça, por meio da fé, e isto não vem de vocês, é dom de Deus;', 3, CURRENT_TIMESTAMP, false),
(49, 2, 9, 'não por obras, para que ninguém se glorie.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 10, 'Porque somos criação de Deus realizada em Cristo Jesus para fazermos boas obras, as quais Deus preparou de antemão para que nós as praticássemos.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 11, 'Portanto, lembrem-se de que anteriormente vocês eram gentios por nascimento e chamados incircuncisão pelos que se chamam circuncisão, feita no corpo por mãos humanas, e que', 3, CURRENT_TIMESTAMP, false),
(49, 2, 12, 'naquela época vocês estavam sem Cristo, separados da comunidade de Israel, sendo estrangeiros quanto às alianças da promessa, sem esperança e sem Deus no mundo.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 13, 'Mas agora, em Cristo Jesus, vocês, que antes estavam longe, foram aproximados mediante o sangue de Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 14, 'Pois ele é a nossa paz, o qual de ambos fez um e destruiu a barreira, o muro de inimizade,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 15, 'anulando em seu corpo a lei dos mandamentos expressa em ordenanças. O objetivo dele era criar em si mesmo, dos dois, um novo homem, fazendo a paz,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 16, 'e reconciliar com Deus os dois em um corpo, por meio da cruz, pela qual ele destruiu a inimizade.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 17, 'Ele veio e anunciou paz a vocês que estavam longe e paz aos que estavam perto,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 18, 'pois por meio dele tanto nós como vocês temos acesso ao Pai, por um só Espírito.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 19, 'Portanto, vocês já não são estrangeiros nem forasteiros, mas concidadãos dos santos e membros da família de Deus,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 20, 'edificados sobre o fundamento dos apóstolos e dos profetas, tendo Jesus Cristo como pedra angular,', 3, CURRENT_TIMESTAMP, false),
(49, 2, 21, 'no qual todo o edifício é ajustado e cresce para tornar-se um santuário santo no Senhor.', 3, CURRENT_TIMESTAMP, false),
(49, 2, 22, 'Nele vocês também estão sendo juntamente edificados, para se tornarem morada de Deus por seu Espírito.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 1, 'Por essa razão, eu, Paulo, prisioneiro de Cristo Jesus por amor de vocês, gentios —', 3, CURRENT_TIMESTAMP, false),
(49, 3, 2, 'Certamente vocês ouviram falar da responsabilidade imposta a mim em favor de vocês pela graça de Deus,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 3, 'isto é, o mistério que me foi dado a conhecer por revelação, como já lhes escrevi brevemente.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 4, 'Ao lerem isso vocês poderão entender a minha compreensão do mistério de Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 5, 'Esse mistério não foi dado a conhecer aos homens doutras gerações, mas agora foi revelado pelo Espírito aos santos apóstolos e profetas de Deus,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 6, 'a saber, que mediante o evangelho os gentios são co-herdeiros com Israel, membros do mesmo corpo, e co-participantes da promessa em Cristo Jesus.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 7, 'Deste me tornei ministro pelo dom da graça de Deus, a mim concedida pela operação de seu poder.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 8, 'Embora eu seja o menor dos menores dentre todos os santos, foi-me concedida esta graça de anunciar aos gentios as insondáveis riquezas de Cristo', 3, CURRENT_TIMESTAMP, false),
(49, 3, 9, 'e esclarecer a todos a administração deste mistério que, durante as épocas passadas, foi mantido oculto em Deus, que criou todas as coisas.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 10, 'A intenção dessa graça era que agora, mediante a igreja, a multiforme sabedoria de Deus se tornasse conhecida dos poderes e autoridades nas regiões celestiais,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 11, 'de acordo com o seu eterno plano que ele realizou em Cristo Jesus, nosso Senhor,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 12, 'por intermédio de quem temos livre acesso a Deus em confiança, pela fé nele.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 13, 'Portanto, peço-lhes que não se desanimem por causa das minhas tribulações em seu favor, pois elas são uma glória para vocês.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 14, 'Por essa razão, ajoelho-me diante do Pai,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 15, 'do qual recebe o nome toda a família nos céus e na terra.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 16, 'Oro para que, com as suas gloriosas riquezas, ele os fortaleça no íntimo do seu ser com poder, por meio do seu Espírito,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 17, 'para que Cristo habite em seus corações mediante a fé; e oro para que vocês, arraigados e alicerçados em amor,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 18, 'possam, juntamente com todos os santos, compreender a largura, o comprimento, a altura e a profundidade,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 19, 'e conhecer o amor de Cristo que excede todo conhecimento, para que vocês sejam cheios de toda a plenitude de Deus.', 3, CURRENT_TIMESTAMP, false),
(49, 3, 20, 'Àquele que é capaz de fazer infinitamente mais do que tudo o que pedimos ou pensamos, de acordo com o seu poder que atua em nós,', 3, CURRENT_TIMESTAMP, false),
(49, 3, 21, 'a ele seja a glória na igreja e em Cristo Jesus, por todas as gerações, para todo o sempre! Amém!', 3, CURRENT_TIMESTAMP, false),
(49, 4, 1, 'Como prisioneiro no Senhor, rogo-lhes que vivam de maneira digna da vocação que receberam.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 2, 'Sejam completamente humildes e dóceis, e sejam pacientes, suportando uns aos outros com amor.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 3, 'Façam todo o esforço para conservar a unidade do Espírito pelo vínculo da paz.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 4, 'Há um só corpo e um só Espírito, assim como a esperança para a qual vocês foram chamados é uma só;', 3, CURRENT_TIMESTAMP, false),
(49, 4, 5, 'há um só Senhor, uma só fé, um só batismo,', 3, CURRENT_TIMESTAMP, false),
(49, 4, 6, 'um só Deus e Pai de todos, que é sobre todos, por meio de todos e em todos.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 7, 'E a cada um de nós foi concedida a graça, conforme a medida repartida por Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 8, 'Por isso é que foi dito: "Quando ele subiu em triunfo às alturas, levou cativo muitos prisioneiros, e deu dons aos homens".', 3, CURRENT_TIMESTAMP, false),
(49, 4, 9, '( Que significa "ele subiu", senão que também descera às profundezas da terra?', 3, CURRENT_TIMESTAMP, false),
(49, 4, 10, 'Aquele que desceu é o mesmo que subiu acima de todos os céus, a fim de encher todas as coisas. )', 3, CURRENT_TIMESTAMP, false),
(49, 4, 11, 'E ele designou alguns para apóstolos, outros para profetas, outros para evangelistas, e outros para pastores e mestres,', 3, CURRENT_TIMESTAMP, false),
(49, 4, 12, 'com o fim de preparar os santos para a obra do ministério, para que o corpo de Cristo seja edificado,', 3, CURRENT_TIMESTAMP, false),
(49, 4, 13, 'até que todos alcancemos a unidade da fé e do conhecimento do Filho de Deus, e cheguemos à maturidade, atingindo a medida da plenitude de Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 14, 'O propósito é que não sejamos mais como crianças, levados de um lado para outro pelas ondas, nem jogados para cá e para lá por todo vento de doutrina e pela astúcia e esperteza de homens que induzem ao erro.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 15, 'Antes, seguindo a verdade em amor, cresçamos em tudo naquele que é a cabeça, Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 16, 'Dele todo o corpo, ajustado e unido pelo auxílio de todas as juntas, cresce e edifica-se a si mesmo em amor, na medida em que cada parte realiza a sua função.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 17, 'Assim, eu lhes digo, e no Senhor insisto, que não vivam mais como os gentios, que vivem na futilidade dos seus pensamentos.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 18, 'Eles estão obscurecidos no entendimento e separados da vida de Deus por causa da ignorância em que estão, devido ao endurecimento dos seus corações.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 19, 'Tendo perdido toda a sensibilidade, ele se entregaram à depravação, cometendo com avidez toda espécie de impureza.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 20, 'Todavia, não foi assim que vocês aprenderam de Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 21, 'De fato, vocês ouviram falar dele, e nele foram ensinados de acordo com a verdade que está em Jesus.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 22, 'Quanto à antiga maneira de viver, vocês foram ensinados a despir-se do velho homem, que se corrompe por desejos enganosos,', 3, CURRENT_TIMESTAMP, false),
(49, 4, 23, 'a serem renovados no modo de pensar e', 3, CURRENT_TIMESTAMP, false),
(49, 4, 24, 'a revestir-se do novo homem, criado para ser semelhante a Deus em justiça e em santidade provenientes da verdade.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 25, 'Portanto, cada um de vocês deve abandonar a mentira e falar a verdade ao seu próximo, pois todos somos membros de um mesmo corpo.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 26, '"Quando vocês ficarem irados, não pequem". Apazigüem a sua ira antes que o sol se ponha,', 3, CURRENT_TIMESTAMP, false),
(49, 4, 27, 'e não dêem lugar ao diabo.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 28, 'O que furtava não furte mais; antes trabalhe, fazendo algo de útil com as mãos, para que tenha o que repartir com quem estiver em necessidade.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 29, 'Nenhuma palavra torpe saia da boca de vocês, mas apenas a que for útil para edificar os outros, conforme a necessidade, para que conceda graça aos que a ouvem.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 30, 'Não entristeçam o Espírito Santo de Deus, com o qual vocês foram selados para o dia da redenção.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 31, 'Livrem-se de toda amargura, indignação e ira, gritaria e calúnia, bem como de toda maldade.', 3, CURRENT_TIMESTAMP, false),
(49, 4, 32, 'Sejam bondosos e compassivos uns para com os outros, perdoando-se mutuamente, assim como Deus perdoou vocês em Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 1, 'Portanto, sejam imitadores de Deus, como filhos amados,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 2, 'e vivam em amor, como também Cristo nos amou e se entregou por nós como oferta e sacrifício de aroma agradável a Deus.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 3, 'Entre vocês não deve haver nem sequer menção de imoralidade sexual nem de qualquer espécie de impureza nem de cobiça; pois estas coisas não são próprias para os santos.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 4, 'Não haja obscenidade nem conversas tolas nem gracejos imorais, que são inconvenientes, mas, ao invés disso, ação de graças.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 5, 'Porque vocês podem estar certos disto: nenhum imoral nem impuro nem ganancioso, que é idólatra, tem herança no Reino de Cristo e de Deus.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 6, 'Ninguém os engane com palavras tolas, pois é por causa dessas coisas que a ira de Deus vem sobre os que vivem na desobediência.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 7, 'Portanto, não participem com eles dessas coisas.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 8, 'Porque outrora vocês eram trevas, mas agora são luz no Senhor. Vivam como filhos da luz,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 9, 'pois o fruto da luz consiste em toda bondade, justiça e verdade;', 3, CURRENT_TIMESTAMP, false),
(49, 5, 10, 'e aprendam a discernir o que é agradável ao Senhor.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 11, 'Não participem das obras infrutíferas das trevas; antes, exponham-nas à luz.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 12, 'Porque aquilo que eles fazem em oculto, até mencionar é vergonhoso.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 13, 'Mas, tudo o que é exposto pela luz torna-se visível, pois a luz torna visíveis todas as coisas.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 14, 'Por isso é que foi dito: "Desperta, ó tu que dormes, levanta-te dentre os mortos e Cristo resplandecerá sobre ti".', 3, CURRENT_TIMESTAMP, false),
(49, 5, 15, 'Tenham cuidado com a maneira como vocês vivem; que não seja como insensatos, mas como sábios,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 16, 'aproveitando ao máximo cada oportunidade, porque os dias são maus.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 17, 'Portanto, não sejam insensatos, mas procurem compreender qual é a vontade do Senhor.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 18, 'Não se embriaguem com vinho, que leva à libertinagem, mas deixem-se encher pelo Espírito,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 19, 'falando entre si com salmos, hinos e cânticos espirituais, cantando e louvando de coração ao Senhor,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 20, 'dando graças constantemente a Deus Pai por todas as coisas, em nome de nosso Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 21, 'Sujeitem-se uns aos outros, por temor a Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 22, 'Mulheres, sujeitem-se a seus maridos, como ao Senhor,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 23, 'pois o marido é o cabeça da mulher, como também Cristo é o cabeça da igreja, que é o seu corpo, do qual ele é o Salvador.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 24, 'Assim como a igreja está sujeita a Cristo, também as mulheres estejam em tudo sujeitas a seus maridos.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 25, 'Maridos, amem suas mulheres, assim como Cristo amou a igreja e entregou-se a si mesmo por ela', 3, CURRENT_TIMESTAMP, false),
(49, 5, 26, 'para santificá-la, tendo-a purificado pelo lavar da água mediante a palavra,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 27, 'e apresentá-la a si mesmo como igreja gloriosa, sem mancha nem ruga ou coisa semelhante, mas santa e inculpável.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 28, 'Da mesma forma, os maridos devem amar as suas mulheres como a seus próprios corpos. Quem ama sua mulher, ama a si mesmo.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 29, 'Além do mais, ninguém jamais odiou o seu próprio corpo, antes o alimenta e dele cuida, como também Cristo faz com a igreja,', 3, CURRENT_TIMESTAMP, false),
(49, 5, 30, 'pois somos membros do seu corpo.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 31, '"Por essa razão, o homem deixará pai e mãe e se unirá à sua mulher, e os dois se tornarão uma só carne".', 3, CURRENT_TIMESTAMP, false),
(49, 5, 32, 'Este é um mistério profundo; refiro-me, porém, a Cristo e à igreja.', 3, CURRENT_TIMESTAMP, false),
(49, 5, 33, 'Portanto, cada um de vocês também ame a sua mulher como a si mesmo, e a mulher trate o marido com todo o respeito.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 1, 'Filhos, obedeçam a seus pais no Senhor, pois isso é justo.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 2, '"Honra teu pai e tua mãe", este é o primeiro mandamento com promessa:', 3, CURRENT_TIMESTAMP, false),
(49, 6, 3, '"para que tudo te corra bem e tenhas longa vida sobre a terra".', 3, CURRENT_TIMESTAMP, false),
(49, 6, 4, 'Pais, não irritem seus filhos; antes criem-nos segundo a instrução e o conselho do Senhor.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 5, 'Escravos, obedeçam a seus senhores terrenos com respeito e temor, com sinceridade de coração, como a Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 6, 'Obedeçam-lhes não apenas para agradá-los quando eles os observam, mas como escravos de Cristo, fazendo de coração a vontade de Deus.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 7, 'Sirvam aos seus senhores de boa vontade, como ao Senhor, e não aos homens,', 3, CURRENT_TIMESTAMP, false),
(49, 6, 8, 'porque vocês sabem que o Senhor recompensará a cada um pelo bem que praticar, seja escravo, seja livre.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 9, 'Vocês, senhores, tratem seus escravos da mesma forma. Não os ameacem, uma vez que vocês sabem que o Senhor deles e de vocês está nos céus, e ele não faz diferença entre as pessoas.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 10, 'Finalmente, fortaleçam-se no Senhor e no seu forte poder.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 11, 'Vistam toda a armadura de Deus, para poderem ficar firmes contra as ciladas do diabo,', 3, CURRENT_TIMESTAMP, false),
(49, 6, 12, 'pois a nossa luta não é contra pessoas, mas contra os poderes e autoridades, contra os dominadores deste mundo de trevas, contra as forças espirituais do mal nas regiões celestiais.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 13, 'Por isso, vistam toda a armadura de Deus, para que possam resistir no dia mau e permanecer inabaláveis, depois de terem feito tudo.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 14, 'Assim, mantenham-se firmes, cingindo-se com o cinto da verdade, vestindo a couraça da justiça', 3, CURRENT_TIMESTAMP, false),
(49, 6, 15, 'e tendo os pés calçados com a prontidão do evangelho da paz.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 16, 'Além disso, usem o escudo da fé, com o qual vocês poderão apagar todas as setas inflamadas do Maligno.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 17, 'Usem o capacete da salvação e a espada do Espírito, que é a palavra de Deus.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 18, 'Orem no Espírito em todas as ocasiões, com toda oração e súplica; tendo isso em mente, estejam atentos e perseverem na oração por todos os santos.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 19, 'Orem também por mim, para que, quando eu falar, seja-me dada a mensagem a fim de que, destemidamente, torne conhecido o mistério do evangelho,', 3, CURRENT_TIMESTAMP, false),
(49, 6, 20, 'pelo qual sou embaixador preso em correntes. Orem para que, permanecendo nele, eu fale com coragem, como me cumpre fazer.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 21, 'Tíquico, o irmão amado e fiel servo do Senhor, lhes informará tudo, para que vocês também saibam qual é a minha situação e o que estou fazendo.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 22, 'Enviei-o a vocês por essa mesma razão, para que saibam como estamos e para que ele os encoraje.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 23, 'Paz seja com os irmãos, e amor com fé da parte de Deus Pai e do Senhor Jesus Cristo.', 3, CURRENT_TIMESTAMP, false),
(49, 6, 24, 'A graça seja com todos os que amam a nosso Senhor Jesus Cristo com amor incorruptível.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 1, 'No primeiro ano do reinado de Ciro, rei da Pérsia, a fim de que se cumprisse a palavra do Senhor falada por Jeremias, o Senhor despertou o coração de Ciro, rei da Pérsia, para redigir uma proclamação e divulgá-la em todo o seu reino, nestes termos:', 3, CURRENT_TIMESTAMP, false),
(15, 1, 2, '"Assim diz Ciro, rei da Pérsia: "O Senhor, o Deus dos céus, deu-me todos os reinos da terra e designou-me para construir um templo para ele em Jerusalém de Judá.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 3, 'Qualquer do seu povo que esteja entre vocês, que o seu Deus esteja com ele, e que vá a Jerusalém de Judá reconstruir o templo do Senhor, o Deus de Israel, o Deus que em Jerusalém tem a sua morada.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 4, 'E que todo sobrevivente, seja qual for o lugar em que está vivendo, receba dos que ali vivem em prata, ouro, bens e animais; e ofertas voluntárias para o templo de Deus em Jerusalém".', 3, CURRENT_TIMESTAMP, false),
(15, 1, 5, 'Então os líderes das famílias de Judá e de Benjamim, como também os sacerdotes e os levitas, todos aqueles cujo coração Deus despertou, dispuseram-se a ir para Jerusalém e a construir o templo do Senhor.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 6, 'Todos os seus vizinhos os ajudaram, trazendo-lhes utensílios de prata e ouro, bens, animais, e presentes valiosos, além de todas as ofertas voluntárias que fizeram.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 7, 'Além disso, o rei Ciro mandou tirar os utensílios pertencentes ao templo do Senhor, os quais Nabucodonosor tinha levado de Jerusalém e colocado no templo do seu deus.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 8, 'Ciro, rei da Pérsia, ordenou que fossem tirados pelo tesoureiro Mitredate, que os enumerou e os entregou a Sesbazar, governador de Judá.', 3, CURRENT_TIMESTAMP, false),
(15, 1, 9, 'O total foi o seguinte: 30 tigelas de ouro, 1. 000 tigelas de prata, 29 panelas de prata,', 3, CURRENT_TIMESTAMP, false),
(15, 1, 10, '30 bacias de ouro, 410 bacias de prata de qualidade inferior e 1. 000 outros objetos', 3, CURRENT_TIMESTAMP, false),
(15, 1, 11, 'Ao todo foram, na verdade, cinco mil e quatrocentos utensílos de ouro e de prata. Sesbazar trouxe tudo isso consigo quando os exilados vieram da Babilônia para Jerusalém.', 3, CURRENT_TIMESTAMP, false),
(15, 2, 1, 'Esta é a lista dos homens da província que Nabucodonosor, rei da Babilônia, tinha levado prisioneiros para a Babilônia. Eles voltaram para Jerusalém e Judá, cada um para a sua própria cidade.', 3, CURRENT_TIMESTAMP, false),
(15, 2, 2, 'Vieram na companhia de Zorobabel, Jesua, Neemias, Seraías, Reelaías, Mardoqueu, Bilsã, Mispar, Bigvai, Reum e Baaná. Esta é a lista dos israelitas:', 3, CURRENT_TIMESTAMP, false),
