(16, 7, 43, 'Os levitas: os descendentes de Jesua, por meio de Cadmiel, pela linhagem de Hodeva 74.', 3, CURRENT_TIMESTAMP, false),
(16, 7, 44, 'Os cantores: os descendentes de Asafe 148.', 3, CURRENT_TIMESTAMP, false),
(16, 7, 45, 'Os porteiros do templo: os descendentes de Salum, Ater, Talmom, Acube, Hatita e Sobai 138.', 3, CURRENT_TIMESTAMP, false),
(16, 7, 46, 'Os servidores do templo: os descendentes de Zia, Hasufa, Tabaote,', 3, CURRENT_TIMESTAMP, false),
(16, 7, 47, 'Queros, Sia, Padom,', 3, CURRENT_TIMESTAMP, false),
